--
-- Table structure for table `t_video_info`
--

DROP TABLE IF EXISTS `t_video_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_video_info` (
  `video_id` int NOT NULL AUTO_INCREMENT,
  `video_name` varchar(255) DEFAULT NULL COMMENT '影片名',
  `original_title` varchar(255) DEFAULT NULL COMMENT '原始标题',
  `overview` text COMMENT '简介',
  `tagline` varchar(500) DEFAULT NULL COMMENT '标语',
  `budget` bigint DEFAULT '0' COMMENT '预算',
  `revenue` bigint DEFAULT '0' COMMENT '票房',
  `popularity` double DEFAULT '0' COMMENT '热度值',
  `vote_average` double DEFAULT '0' COMMENT '平均评分',
  `vote_count` int DEFAULT '0' COMMENT '评分人数',
  `runtime` int DEFAULT '0' COMMENT '片长(分钟)',
  `release_date` date DEFAULT NULL COMMENT '上映日期',
  `original_language` varchar(10) DEFAULT NULL COMMENT '原始语言',
  `poster_path` varchar(500) DEFAULT NULL COMMENT '海报路径',
  `heat_score` double DEFAULT '0' COMMENT '综合热度评分',
  `video_category` tinyint(1) DEFAULT NULL COMMENT '1.教学视频，2，娱乐短视频，3，电影 4电视剧',
  `create_time` date DEFAULT NULL,
  `creator_id` int DEFAULT NULL COMMENT '视频上传者的id',
  `last_modify_time` datetime DEFAULT NULL,
  `video_url` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '视频保存的地址',
  PRIMARY KEY (`video_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=459591 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `t_video_info`
--

LOCK TABLES `t_video_info` WRITE;
/*!40000 ALTER TABLE `t_video_info` DISABLE KEYS */;
INSERT INTO `t_video_info` VALUES (3,'小猪佩奇',NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,'/lIv1QinFqz4dlp5U4lQ6HaiskOZ.jpg',1.833782385321101,2,'2020-04-02',NULL,NULL,NULL),(4,'冰雪传奇',NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,'/aTXRaPrWSinhcmCrcfJK17urp3F.jpg',1.833782385321101,2,'2020-04-02',NULL,NULL,NULL),(5,'Four Rooms',NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,'/eznrQyErtHMY5Z1s1amF9P70A0z.jpg',1.833782385321101,2,'2020-04-02',NULL,NULL,NULL),(6,'指环王',NULL,NULL,NULL,0,0,0,0,0,0,NULL,NULL,'/6IDqA1D2NBIVhzEEaMMRL28iBrq.jpg',1.833782385321101,1,'2020-04-02',NULL,NULL,NULL),(11,'星球大战4：新希望','Star Wars','很久以前，在一个遥远的银河系……莱娅公主被邪恶的帝国势力挟为人质，企图镇压反抗银河帝国的起义军。卢克·天行者与汉·索罗船长携手可爱的机器人搭档R2-D2和C-3PO，共同踏上拯救美丽公主、恢复银河系正义的征程。[20世纪福克斯]','A long time ago in a galaxy far, far away...',11000000,775398007,126.393695,8.1,6624,121,'1977-05-25','en','/fai0rspsNeJCS69wHNjOdWxcI7P.jpg',4.5702316983435,3,'2026-09-10',2,NULL,NULL),(12,'海底总动员','Finding Nemo','主角是一对可爱的小丑鱼(Clownfish)父子。父亲玛林和儿子尼莫一直在澳洲外海大堡礁中过着安定而幸福的平静生活。鱼爸爸玛林一直谨小慎微，行事缩手缩脚，虽然已经身为人父，却丝毫不会影响它成为远近闻名的胆小鬼。也正因为这一点，儿子尼莫常常与玛林发生争执，甚至有那么一点瞧不起自己的父亲。直到有一天，一直向往到海洋中冒险的尼莫，游出了他们所居住的珊瑚礁。正当尼莫想要舒展一下小尾巴的时候，一艘渔船毫不留情地将欢天喜地的尼莫捕走，并将它辗转卖到澳洲悉尼湾内的一家牙医诊所。在大堡礁的海底，心爱的儿子突然生死未卜的消息，对于鱼爸爸玛林来说却无异于晴天霹雳。尽管胆小尽管怕事，现在为了救回心爱的孩子，玛林也就只有豁出去了。它决心跟上澳洲洋流，踏上寻找自己儿子的漫漫征程。','There are 3.7 trillion fish in the ocean, they\'re looking for one.',94000000,940335536,85.688789,7.6,6122,100,'2003-05-30','en','/eHuGQ10FUzK1mdOY69wF5pGgEf5.jpg',4.321764296115426,3,'2026-09-10',2,NULL,NULL),(13,'阿甘正传','Forrest Gump','阿甘出生在美国南方阿拉巴马州一个闭塞的小镇，智商只有75，然而他的妈妈是一位性格坚强的女性，她常常鼓励阿甘要自强不息。阿甘像普通孩子一样上学，并认识了一生的朋友和挚爱珍妮。在珍妮和妈妈的爱护下，阿甘凭着自己出众的奔跑能力，开始了一生不停的奔跑。他先后成为橄榄球明星、越战英雄、乒乓球外交使者和亿万富翁，但始终忘不了珍妮。一次次匆匆的相聚与离别，更加深了阿甘对她的思念。有一天，阿甘收到珍妮的来信，他们终于又要见面……','',55000000,677945399,34.4583,8.462,7927,142,'1994-06-23','en','/pplybKImR7LKzSVzRylK6Cl4dzm.jpg',4.507574774986931,3,'2026-09-10',2,NULL,NULL),(14,'美国丽人','American Beauty','被禁忌的欲望所激荡，莱斯特·伯纳姆（凯文·史派西 饰）决定打破自己循规蹈矩的生活。这些改变与其说是中年危机，不如说是青春期的再次苏醒。他活得越恣意，就越快活——这让妻子卡罗琳（安妮特·贝宁 饰）和女儿简（索拉·伯奇 饰）愈发恼火，尤其是当他将炽热的目光投向简的朋友、妖娆的安吉拉（米娜·苏瓦丽 饰）时。[Dreamworks SKG]','Look closer.',15000000,356296601,80.878605,7.9,3313,122,'1999-09-15','en','/wby9315QzVKdW9BonAefg8jGTTb.jpg',4.218270644986454,3,'2026-09-10',2,NULL,NULL),(16,'黑暗中的舞者','Dancer in the Dark','在美国某个乡村工厂做工的捷克移民塞尔玛（比约克）天性善良，因患有先天性疾病，她的视线正日趋模糊。为了不让遗传了该病的儿子也将宿命继承，塞尔玛每日做工都很辛苦，不知情的好友兼同事林达（凯萨琳•丹妮芙）因心疼而好言相劝时，她总是报一微笑，因为她还有另一个纯粹属于音乐的世界，其间的美好与安静，足以抵挡现实的心酸与艰难。  　　令她欣慰的是，在眼睛要彻底变瞎之前，基本筹齐了儿子手术所需的费用，然而就在此时，意外发生，她的命运被加速推向复杂悲惨的境地。','You don\'t need eyes to see.',12800000,40031879,22.022228,7.6,377,140,'2000-05-17','en','/8N78IjsWRzPtx7qvsQSO0nJyPUK.jpg',3.3250110672939495,3,'2026-09-10',2,NULL,NULL),(18,'第五元素','Le Cinquième Élément','一头红发，perfect的“第五元素”莉露受命来到地球，她要协助人类与每隔五百年降临一次的邪恶力量对抗，联合风、火、水、土四块神石击退敌人。在实验室被复制出来后，言语不通的莉露在躲避人类的追捕中搭上了退役特工科本的出租车。科本带莉露找到了负责接头的神父，两人也渐渐的产生了好感。莉露与科本一同前往一个叫“失落天堂”的星球找寻另外四种元素的神石。但是，在战斗中莉露受伤昏迷，而且由于人类的暴行和无知杀戮，莉露陷入了内心的迷惘。大敌当前，科本究竟用什么力量才能唤醒莉露呢？','There is no future without it.',90000000,263920180,109.528572,7.3,3885,126,'1997-05-07','en','/fPtlCO1yQtnoLHOwKtWz7db6RGU.jpg',4.178691786533826,3,'2026-09-10',2,NULL,NULL),(19,'大都会','Metropolis','这部1927年的鸿篇巨制或许堪称默片时代的巅峰成就，弗里茨·朗将二十年代通俗小说狂热的叙事节奏，与自身对人性幽暗面的深刻洞察熔铸一体。','There can be no understanding between the hands and the brain unless the heart acts as mediator.',92620000,650422,32.351527,8,657,153,'1927-01-10','de','/vODOVn29fr0nLF9MVfpfKDcxuXF.jpg',3.585304796360851,3,'2026-09-10',2,NULL,NULL),(20,'没有我的日子','My Life Without Me','尚不满24岁的清洁工安妮（Sarah Polley 饰）被确诊为癌症，只剩下两至三月的寿命，安妮的丈夫是她生命中第一个也是唯一一个男人，丈夫让她在17岁、19岁时分别生下女儿，入狱的父亲无法为她提供庇护，同母亲的关系又不甚良好，一家四口居住在拖车里，所幸丈夫最近得到了修建泳池的工作。安妮决定将病情隐瞒家人，并写了十条身故前的愿望，包括找到又一个爱自己的男人，为女儿准备未来生日的祝词并和一个继母，跟父亲见一次面和享受余下的人生。安妮在洗衣房里偶遇从阿拉斯加归来的测量员，两人彼此摩擦出了爱的火花。但她将满脑子只有节食计划的女同事介绍给丈夫时却遭遇了失败，不久一名与安妮同名的女邻居到来，她似乎是安妮理想的人选。所有事情在按步骤实现，还有安妮的死亡……',NULL,0,9726954,7.958831,7.2,77,106,'2003-03-07','en','/pFEtVPW88pWflYV84UFL0h1iJr3.jpg',2.82919597347139,3,'2026-09-10',2,NULL,NULL),(22,'加勒比海盗1：黑珍珠号的诅咒','Pirates of the Caribbean: The Curse of the Black Pearl','故事发生在17世纪，传说中海盗最为活跃的加勒比海。风趣迷人的杰克·斯伯洛，是活跃在加勒比海上的海盗，拥有属于自己的“黑珍珠”号海盗船。对他来说，最惬意的生活就是驾驶着“黑珍珠”号在加勒比海上游荡，自由自在的打劫过往船只。但不幸的是，他的仇敌，老谋深算的巴博萨船长偷走了他的“黑珍珠”号。','Prepare to be blown out of the water.',140000000,655011224,271.972889,7.5,6985,143,'2003-07-09','en','/poHwCZeWzJCShH7tOjg8RIoyjcw.jpg',4.754047699492178,3,'2026-09-10',2,NULL,NULL),(24,'杀死比尔','Kill Bill: Vol. 1','An assassin is shot at the altar by her ruthless employer, Bill and other members of their assassination circle – but \'The Bride\' lives to plot her vengeance. Setting out for some payback, she makes a death list and hunts down those who wronged her, saving Bill for last.','Go for the kill.',30000000,180949000,79.754966,7.7,4949,111,'2003-10-10','en','/v7TaX8kXMXs5yFFGR41guUDNcnB.jpg',4.278378569177422,3,'2026-09-10',2,NULL,NULL),(25,'Jarhead','Jarhead','Jarhead is a film about a US Marine Anthony Swofford’s experience in the Gulf War. After putting up with an arduous boot camp, Swafford and his unit are sent to the Persian Gulf where they are earger to fight but are forced to stay back from the action. Meanwhile Swofford gets news of his girlfriend is cheating on him. Desperately he wants to kill someone and finally put his training to use.','Welcome to the suck.',72000000,96889998,32.227223,6.6,765,125,'2005-11-04','en','/4vrME6xocVYzgTK84yhu4JiLIgP.jpg',3.42440911160533,3,'2026-09-10',2,NULL,NULL),(28,'现代启示录','Apocalypse Now','越战期间，威拉德上尉受命执行一项危险任务，深入柬埔寨刺杀一位脱离建制的叛变上校——此人已在当地部落自封神明。','This is the end...',31500000,89460381,49.973462,8,2055,153,'1979-08-15','en','/gQB8Y5RCMkv2zwzFHbUJX3kAhvA.jpg',4.022480274272337,3,'2026-09-10',2,NULL,NULL),(33,'不可饶恕','Unforgiven','在这部荣获奥斯卡奖的西部片中，伊斯特伍德与弗里曼饰演穷途末路的法外之徒，为获取怀俄明州偏远大威士忌镇几名复仇心切的妓女悬赏的赏金，他们最后一次拔枪上阵。','Some legends will never be forgotten. Some wrongs can never be forgiven.',14000000,159157447,37.380435,7.7,1113,131,'1992-08-07','en','/54roTwbX9fltg85zjsmrooXAs12.jpg',3.7304453864672995,3,'2026-09-10',2,NULL,NULL),(35,'辛普森一家','The Simpsons Movie','绿日乐队在春田镇办了环保演唱会，惨遭冷遇，成员落水而亡。为了悼念，教堂举办了弥撒仪式。辛普森一家又迟到了，而且爷爷突然灵魂附体，说出了灾难降临的预言。巴特因为踩着滑板裸奔被罚，得到了邻居弗兰德斯的帮助，情同父子。丽莎遇到了志同道合的爱尔兰男孩柯林，两人暗生情愫。荷马丢弃核废料与垃圾严重污染了水资源。他买回了一头猪，引起了妻子玛姬的不满，小女儿美姬倒是乐得其中。一个长着无数眼睛的怪异生物让大家意识到了问题的严峻性。居民大会上，丽萨提出的环保议案被否决，问题传到了施瓦辛格总统的耳朵里。政府下令将污染严重的春田镇隔离。如梦初醒的村民们这才发现环境的重要，愤怒的人们把矛头指向了污染的始作俑者——辛普森一家…… 　　本片是从1987年开始在美国连播18年的TV动画长寿剧集《辛普森一家》第一次登陆大银幕，在影迷中引起巨大反响。','See our family. And feel better about yours.',75000000,527068851,46.875375,6.9,2264,87,'2007-07-25','en','/s3b8TZWwmkYc2KoJ5zk77qB6PzY.jpg',3.7971055679726433,3,'2026-09-10',2,NULL,NULL),(38,'暖暖内含光','Eternal Sunshine of the Spotless Mind','内向沉稳的约尔•巴瑞斯（金•凯瑞 饰）在一次聚会中认识了率真随性的克莱门汀•克罗斯基（凯特•温丝莱特 饰），二人成为情侣。和普通的情侣一样，他们的日子也在甜蜜和争吵中度过。2004年情人节前夕，当约尔精心准备好礼物，为不久前一次争吵找到克莱门汀道歉时，他惊讶地发现，克莱门汀根本都不记得他了。原来冲动的克莱门汀受不了二人交往中争吵的痛苦，到“忘情诊所”，把关于约尔的记忆删除得一干二净。\r 约尔无法原谅克莱门汀的任性，也无法忍受失去她的痛苦，所以他也到了“忘情诊所”，请求医生霍华德博士（汤姆•维尔金森 饰）消除关于克莱门汀的记忆。记忆清除程序开始启动，约尔在自己的记忆中游走，他发现和克莱斯汀一起度过的那些时光，无论是痛苦还是甜蜜，都弥足珍贵，他并不想忘记这个自己深爱的女人。但是，程序一旦启动就无法逆转，约尔只能想尽办法把克莱斯汀藏到记忆最深的地方，那些现实中克莱斯汀本来没有出现过的时间角落，以保存这份爱情……','You can erase someone from your mind. Getting them out of your heart is another story.',20000000,72258126,56.481487,7.9,3652,108,'2004-03-19','en','/5MwkWH9tYHv3mV9OdYTMR5qreIz.jpg',4.191170985919587,3,'2026-09-10',2,NULL,NULL),(55,'爱情是狗娘','Amores perros','这部亚利桑德罗·冈萨雷斯·伊纳里图灼目的长片处女作，以其令人震撼的视觉风格与大胆的多线叙事，如一声原始的呐喊般带来心跳骤停的冲击力，在墨西哥电影界乃至全球引发震荡。在墨西哥城，三个陌生人的命运在悲剧性的转折中相撞：一个深陷斗狗地下世界的青年、一位看似拥有一切的迷人女子、一名渴望与疏远女儿重聚的神秘杀手。这场碰撞永远改变了他们各自的人生轨迹。凭借手持摄影疾速捕捉的暴力与情感，本片将人无情抛入一个残酷而痛楚、彼此相连的人性世界，令人过目难忘。[标准收藏]','Love. Betrayal. Death.',2000000,20908467,23.281616,7.6,521,154,'2000-06-16','es','/fBCG2T2FygISOIQ85Bs5wPsnQFB.jpg',3.431865721985609,3,'2026-09-10',2,NULL,NULL),(58,'加勒比海盗2：聚魂棺','Pirates of the Caribbean: Dead Man\'s Chest','迷人的杰克船长又回来了，这次，他遇到了更为强大的敌人——传说中的不死人大卫·琼斯，他驾驶着让人恐惧的“飞行荷兰人”号快船，在速度与装备上，没有任何船能够超越它。杰克船长欠下琼斯一个血债，他必须赶在最后时限到来之前，找到破解的方法，否则他会永远背负血债，并且在余生永远成为琼斯的奴隶。','Jack is back!',200000000,1065659812,145.847379,7,5246,151,'2006-06-20','en','/uXEqmloGyP7UXAiphJUu2v2pcuE.jpg',4.260641154521705,3,'2026-09-10',2,NULL,NULL),(59,'暴力史','A History of Violence','在大卫·柯南伯格这部含蓄而极具挑衅性的名作中，一切并非表面所见。维果·莫腾森首次与导演合作便贡献了层次丰富的表演，饰演小镇丈夫与父亲汤姆·斯托尔——他在击毙暴力抢劫未遂者后被誉为英雄，但这位平凡的家庭男子何以拥有如此娴熟的制敌手段？本片不动声色地解构美式动作英雄的神话，对身份本质、人性内核以及我们既憎恶又无法移开视线的暴力，提出了根本性的诘问。','Tom Stall had the perfect life... until he became a hero.',32000000,60740827,34.628738,6.9,832,96,'2005-09-23','en','/wt2YZ2Xd40LcOTYAvnFe4Inlfc6.jpg',3.499151718905325,3,'2026-09-10',2,NULL,NULL),(62,'2001太空漫游','2001: A Space Odyssey','本片是一次通向未来的倒计时，一张指引人类命运的地图，一场对无限的求索。库布里克为开启这场未来之旅，先回溯至我们史前的猿类祖先时期，随即跨越数千年（通过电影史上一次极具震撼的跳接）来到已被殖民的太空，最终将宇航员鲍曼（凯尔·杜拉 饰）送入未知的星际领域，乃至可能抵达不朽之境。“打开分离舱门，哈尔。”让这场无与伦比、充满敬畏与奥秘的旅程就此启程。[华纳兄弟]','An epic drama of adventure and exploration',10500000,68700000,86.201184,7.9,2998,149,'1968-04-10','en','/ve72VxNqjGM69Uky4WTo2bK6rfq.jpg',4.2005706410042185,3,'2026-09-10',2,NULL,NULL),(65,'8英里','8 Mile','1995年冬天的底特律，每逢周末乐手们都会聚在一家名为The Shelter的Hip-Hop俱乐部进行一对一的为时一分钟的表演比赛，吉米·史密斯（艾米纳姆 Eminem 饰）是众多黑人乐手中另类的白，虽然他很有实力，却在上台表演时因紧张卡壳，只得到一片喝倒彩的嘲笑声。除了要勇敢面对被起哄的人群轰下台的尴尬，吉米还要应付与母亲（金·贝辛格 Kim Basinger 饰）及同母异父的妹妹一起生活在狭小局促的拖车里的难堪。而母亲的男友、黑人与白人的平行线关系、他的工作和感情等等，也都是他的压力。他试图冲破家庭与团体的束缚，用音乐表达出对生活的愤怒和不满，然而他首先要解决的，是战胜怯弱的自己。','Every moment is another chance.',41000000,215000000,32.798571,6.8,1626,110,'2002-11-08','en','/4DcjAvOnHSmcNw65NgmDB7lCyct.jpg',3.656811097875432,3,'2026-09-10',2,NULL,NULL),(66,'绝对权力','Absolute Power','卢瑟（克林特·伊斯特伍德 Clint Eastwood 饰）是一名技术高超的神偷，在经过了深谋远虑的计划之后，他将下一个目标锁定在了大富翁沃尔特沙利文（E.G.马绍尔 E.G. Marshall 饰）的豪宅之上。在沙利文夫妇外出度假的当口，卢瑟潜入了大宅，正当信心满满的他准备大干一场时，卢瑟在眼前的单向镜之中看到了沃尔特的妻子克里斯蒂（梅罗拉·哈丁 Melora Hardin 饰）和一男子缠绵的身影，这个男人不是别人，正是当今的总统艾伦（吉恩·哈克曼 Gene Hackman 饰）。令卢瑟没有想到的是，原本激情四射的男欢女爱竟然在霎时之间变成了一场血腥谋杀，卢瑟就这样眼睁睁的看着艾伦杀死了克里斯蒂，与此同时，他也成为了这场谋杀的最大嫌疑人。为了洗清自己的罪名，为了揭露艾伦丑恶的嘴脸，卢瑟决定与邪恶一战到底。','Corrupts Absolutely.',50000000,50068310,13.576765,6.4,223,121,'1997-02-14','en','/jiwy7YaPHLN8s1SuXWGgQLKKNKE.jpg',3.060126421608963,3,'2026-09-10',2,NULL,NULL),(68,'妙想天开','Brazil','在反乌托邦杰作中，乔纳森·普雷斯饰演一个沉溺白日梦的普通人，发现自己被卷入噩梦般官僚体系的碾压齿轮。这部由特瑞·吉列姆打造的警世寓言，作为上世纪80年代最伟大的电影之一，已与乔治·奥威尔、奥尔德斯·赫胥黎及库尔特·冯内古特的反极权作品并列于经典之林。而在场景设计、摄影技艺、配乐与视效层面，更是一场持续不断的视觉盛宴。[标准收藏]','It\'s only a state of mind.',15000000,0,41.089863,7.5,861,132,'1985-02-20','en','/p63JPAgFTzZnfPfwJWWGctLfYR6.jpg',3.62085989017946,3,'2026-09-10',2,NULL,NULL),(69,'与歌同行','Walk the Line','约翰·卡什（杰昆·菲尼克斯 Joaquin Phoenix 饰）本是个阿肯色州乡村小子，儿时一场意外令他弟弟身故，从此他便活在父亲（罗伯特·帕特里克 Robert Patrick 饰）的谴责和嘲讽下无力翻身。爱音乐的他慢慢以乡村歌手成名，也有了自己的家庭，但外出巡演时偶然接触到毒品慢慢令他不能自拔，将他带入深渊。吸毒令妻子薇薇安（詹妮弗·古德温 Ginnifer Goodwin 饰）带着孩子离开了他，他只好去找心仪已久、但因婚姻在身无法在一起的女歌手琼·卡特（莉丝·威瑟斯彭 Reese Witherspoon 饰），后者给予他援手，帮助他戒毒，却也一次次拒绝了他的求爱。戒毒成功的卡什得以重启事业，和卡特的爱情也在两人的舞台上终成正果。','Love is a burning thing.',28000000,186438883,35.580032,7.3,718,136,'2005-09-13','en','/gjNOh9z01pka0R3nIdzRHE9sZBq.jpg',3.5202430692181172,3,'2026-09-10',2,NULL,NULL),(70,'百万美元宝贝','Million Dollar Baby','两名退休拳击手在洛杉矶经营一家拳馆，当一位怀揣拳击梦想的女性突然出现、渴望登上拳台时，他们的平静生活就此被打破。','Beyond his silence, there is a past. Beyond her dreams, there is a feeling. Beyond hope, there is a memory. Beyond their journey, there is a love.',30000000,216763646,70.456012,7.7,2439,132,'2004-12-15','en','/jcfEqKdWF1zeyvECPqp3mkWLct2.jpg',4.055112076548795,3,'2026-09-10',2,NULL,NULL),(71,'跳出我天地','Billy Elliot','比利（杰米•贝尔 Jamie Bell 饰）的家人是英国的一个底层矿工。他们参加罢工，挣扎在贫困的生活中，并认为比利应该学些男人的拳术。比利本来每周都去一回拳击班，偶然的机会却让他走上了不一样的路途。  　　因为一个小意外，比利发现了潜意识中对芭蕾的热爱，而挑剔世故的芭蕾老师威尔金森（朱丽•沃特斯 Julie Walters 饰）无意中发现了比利极具芭蕾天赋。二人一拍即合，威尔金森甚至放弃她的一班女学生，把全部心思放在培养小比利上。可是比利的家庭全然不理解儿子为何爱上女生的玩意。比利在家庭的反对下，痛苦的抉择。  　　然而大好机会就在当前。万一考上伦敦的皇家芭蕾学校，比利的芭蕾梦想将得到一个广阔舞台。比利站在一个十字路口，选择着他的人生。','Inside every one of us is a special talent waiting to come out. The trick is finding it.',5000000,110000000,20.428237,7.4,750,110,'2000-05-18','en','/5zeIOLQ73QE1H88K6XI0e0z0jRj.jpg',3.5141906435507115,3,'2026-09-10',2,NULL,NULL),(73,'美国X档案','American History X','德瑞克 的父亲在他很小的时候就被一名黑人毒贩射杀，从此给他幼小的心灵埋下了仇恨的种子。原来德瑞克功课很好，是老师眼中的好学生。但自从父亲遇难后，他就将一切心机都放在了对付有色人种上面。他积极组织起一帮白人青年混混，到处和有色人种对着干。一次，他射杀了两名黑人，因此入狱。入狱后，德瑞克加入了一伙新纳粹的白人。后来，因工作关系他和一名黑人成了好友，他开始反思自己的过去。当他意欲脱离狱中新纳粹组织时，遭到了拳打脚踢。德瑞克出狱后，决心和以前自己组织的帮会脱离关系，带着弟弟远走他乡开始新的生活。','Some Legacies Must End.',20000000,23875127,73.567232,8.2,3016,119,'1998-10-30','en','/x2drgoXYZ8484lqyDj7L1CEVR4T.jpg',4.246007172752432,3,'2026-09-10',2,NULL,NULL),(74,'世界之战','War of the Worlds','雷·费瑞尔（汤姆·克鲁斯饰）和妻子离婚了，一儿一女都跟母亲生活——因为他的的贪玩懒散，疏忽责任，这个家庭才如此支离破碎。一场外星人入侵的灾难却让他们重新建立起亲密的的关系。这天妻子繁忙，只好把儿女交给雷照顾。电闪雷鸣天色灰暗，一切好像有些异样。果然，马路上赫然一个庞大的三脚飞行器掘地而起，邪恶的火星人关顾了这个本来平静的小镇。人们四处逃亡，雷也带着女儿奔走逃命，开始了生死历险。当局想尽办法对付外星人，却屡屡失败，整个世界都陷入了恐慌当中。有了父爱的本能，平日吊儿郎当的父亲变得英勇顽强，保护儿女成了他支撑他的动力和信念。','They\'re already here.',132000000,591739379,48.572726,6.2,2322,116,'2005-06-28','en','/24lga5WJCLuduxTsvU6bcOnGxGL.jpg',3.6477136095259697,3,'2026-09-10',2,NULL,NULL),(75,'Mars Attacks!','Mars Attacks!','\'We come in peace\' is not what those green men from Mars mean when they invade our planet, armed with irresistible weapons and a cruel sense of humor.  This star studded cast must play victim to the alien’s fun and games in this comedy homage to science fiction films of the \'50s and \'60s.','Nice planet. We\'ll take it!',70000000,101371017,44.090535,6.1,1509,106,'1996-12-12','en','/fWpo6O0QcVlUVsxbBzYGVL6zWC7.jpg',3.521431346417592,3,'2026-09-10',2,NULL,NULL),(76,'爱在黎明破晓前','Before Sunrise','美国青年杰西（伊桑·霍克 饰）在火车上偶遇了法国女学生塞琳娜（朱莉·德尔佩 饰），两人在火车上交谈甚欢。当火车到达维也纳时，杰西盛情邀请塞琳娜一起在维也纳游览一番，即使杰西翌日便要坐飞机离开。与杰西一见钟情的塞琳娜接受了杰西的邀请。\r 他们一边游览城市，一边谈论着彼此的过去 ，彼此对生活的感想，两人了解越加深刻。他们非常珍惜这美妙的晚上，这对恋人一起经历了很多浪漫的经历因为他们约定在半年后再见，而此次约会将会在日出之间结束……','Can the greatest romance of your life last only one night?',2500000,5535405,23.672571,7.7,959,105,'1995-01-27','en','/5gisRHtmLULKXHthDvez9DxdlYm.jpg',3.64963468523213,3,'2026-09-10',2,NULL,NULL),(77,'记忆碎片','Memento','警方不予受理后，伦纳德·谢尔比执意追查强奸杀害妻子的凶手。然而，一种罕见且无法治愈的失忆症，使他踏上复仇之路难上加难。','Some memories are best forgotten.',9000000,39723096,60.715151,8.1,4028,113,'2000-10-11','en','/nzlv62aC0octS5AklAiWpXLX9Z0.jpg',4.2799753814013135,3,'2026-09-10',2,NULL,NULL),(78,'银翼杀手','Blade Runner','在一个科技高度发达却因城市与社会凋敝而黯淡的未来，侦探瑞克·戴克奉命追捕叛逃的凶残复制人，同时被一位神秘女子吸引——她的秘密或许将侵蚀他的灵魂。','Man has made his match... now it\'s his problem.',28000000,33139618,94.056131,7.9,3509,117,'1982-06-25','en','/63N9uy8nd9j7Eog2axPQ8lbr3Wj.jpg',4.265318425353367,3,'2026-09-10',2,NULL,NULL),(79,'英雄','英雄','时间：两千年前。地点：秦朝暴烈的崛起之初。故事：即将成为中国首位皇帝的秦王，即将一统战火纷飞的土地。三名刺客决意行刺，一位忠臣却挡在了他们面前。','One man\'s strength will unite an empire.',31000000,177394432,23.607392,7.2,635,99,'2002-12-19','zh','/1NBtOH3KPU9UUp1vzVHJ8qzdW88.jpg',3.441366491534418,3,'2026-09-10',2,NULL,NULL),(80,'爱在日落黄昏时','Before Sunset','九年前，杰西（伊桑·霍克 饰）与席琳（朱莉·德尔佩 饰）在火车上不期而遇，怦然心动。在维也纳渡过疯狂而又浪漫的一夜后，他们在日出前分手，并相约在维也纳重逢。\r 九年之后，杰西已成为畅销书作家，而席琳则是法国环保组织成员。杰西在新书里娓娓道来的，正是九年前的浪漫夜晚。在巴黎促销新书时，杰西与席琳在书店相遇，然而他们只有一下午的时光相处，日落之前，杰西要乘飞机赶回美国。两人在午后的巴黎街头散步，在美丽的护城河上泛舟，无所不谈，兴致勃勃。可是就像命运的捉弄，快乐的时光像烟花一样醉人却短暂。','What if you had a second chance with the one that got away?',2700000,15992615,14.799323,7.6,718,80,'2004-02-10','en','/yxfBGNZBSnqIu4GoIxPcP7EwuV3.jpg',3.5174513403572476,3,'2026-09-10',2,NULL,NULL),(83,'Open Water','Open Water','Two divers are left out at sea without a boat. There’s nothing but water for miles, unless they look at what’s underneath them...','Scream all you want.',130000,54667954,15.611857,5.4,315,79,'2004-08-06','en','/zC1XKPsnO3rSK2wviROF8ojtMpE.jpg',3.0547479610161226,3,'2026-09-10',2,NULL,NULL),(85,'夺宝奇兵：法柜奇兵','Raiders of the Lost Ark','When Dr. Indiana Jones – the tweed-suited professor who just happens to be a celebrated archaeologist – is hired by the government to locate the legendary Ark of the Covenant, he finds himself up against the entire Nazi regime.','Indiana Jones - the new hero from the creators of JAWS and STAR WARS.',18000000,389925971,68.159596,7.7,3854,115,'1981-06-12','en','/ceG9VzoRAVGwivFU403Wc3AHRys.jpg',4.1830018162099485,3,'2026-09-10',2,NULL,NULL),(87,'夺宝奇兵2：魔域奇兵','Indiana Jones and the Temple of Doom','After arriving in India, Indiana Jones is asked by a desperate village to find a mystical stone. He agrees – and stumbles upon a secret cult plotting a terrible plan in the catacombs of an ancient palace.','If adventure has a name... it must be Indiana Jones.',28000000,333000000,66.976776,7.1,2781,118,'1984-05-23','en','/gpdVNUaa4LhRMLfJOPj1AZdhAZ3.jpg',3.943682673027292,3,'2026-09-10',2,NULL,NULL),(89,'夺宝奇兵3：圣战奇兵','Indiana Jones and the Last Crusade','传说用耶稣在最后的晚餐中用到的圣杯喝水，便能长生不老。在一次掘金活动中，记载圣杯的碑石被发现，圣杯存在的可能吸引着大批的疯狂的人展开寻找。印第安纳琼斯博士也是他们中的一员，甚至连他的父亲老琼斯也陷入其中——但他给琼斯留下圣杯的笔记后便不知所踪。踏上威尼斯的土地，琼斯和事先约好的史奈达博士会面，他们在图书馆里凭线索找到圣盾后，却开始遭到莫名的来自十字剑兄弟的追杀。一番波折后，琼斯终于找到了老琼斯，同时，史奈达的纳粹身份暴露，笔记被抢走。圣杯随时都有可能落入纳粹的手中。于是，琼斯父子俩开始联袂上演拯救圣杯的精彩大戏！','The man with the hat is back. And this time, he\'s bringing his Dad.',48000000,474171806,80.972475,7.6,3152,127,'1989-05-24','en','/sizg1AU8f8JDZX4QIgE4pjUMBvx.jpg',4.130555543129515,3,'2026-09-10',2,NULL,NULL),(90,'比佛利山超级警探','Beverly Hills Cop','艾索（艾迪·墨菲 Eddie Murphy 饰）是底特律黑白两道的大名人，身为警探，却也不时干些偷鸡摸狗的勾当，而且他侦办案件时经常不按程序办事，上司对他十分头痛。这天，艾索因为敲诈烟贩而差点被开除出去，幸亏好运气才免遭于难。  　　艾索偶遇了一位刚出狱的好友，这人带着巨额的德国债券来到了底特律。两人重逢后不久，艾索的这位朋友就被谋杀了。深谙此事不简单，艾索开始了调查。他独自一人追踪嫌疑人维克多来到了好莱坞的比佛利山，正当他准备上前盘问时，却被当地警察带回了警局。当艾索调查得悉维多克的确在贩毒时，当地的警长同意介入调查，却将艾索打发回老家。艾索只好劝说当地的一名警员比利（祖德·莱茵霍尔德 Judge Reinhold 饰）和他合作，两人开始了私自调查。','The Heat Is On!',15000000,316360478,29.843818,6.8,961,105,'1984-11-29','en','/wTNCpoyFWvtQ1hKkLYSYfbytomx.jpg',3.510842001108707,3,'2026-09-10',2,NULL,NULL),(95,'世界末日','Armageddon','发现一颗巨大的陨石正朝地球方向奔来，并将于十八日内撞上地球时，美国太空总署想出阻止该陨石与地球相撞造成人类毁灭的办法：派人登陆陨石的表面，钻洞贯穿至陨石的地心，放入核弹引爆。但这一切必须要在十八日内完成。钻油井工头（布鲁斯•威利斯）被委以重任，而他的下属（本•阿弗莱特）恰也是其女儿（丽芙•泰勒）的男朋友，此次任务能否成功完成，关系到女儿下半辈子的幸福。为此，他和下属接受了太空总署的高强度的训练，以期一夜之间从打井工人变成救世英雄。','The Earth\'s Darkest Day Will Be Man\'s Finest Hour',140000000,553799566,58.485967,6.4,2482,151,'1998-07-01','en','/eTM3qtGhDU8cvjpoa6KEt5E2auU.jpg',3.731519477753455,3,'2026-09-10',2,NULL,NULL),(96,'Beverly Hills Cop II','Beverly Hills Cop II','Detroit cop, Axel Foley heads for the land of sunshine and palm trees to find out who shot police Captain Andrew Bogomil. Thanks to a couple of old friends, Axel\'s investigation uncovers a series of robberies masterminded by a heartless weapons kingpin – and the chase is on.',NULL,20000000,299965036,25.28436,6.1,613,100,'1987-05-18','en','/cCoIEkze93horiJAVQxdao4en8E.jpg',3.283892569541241,3,'2026-09-10',2,NULL,NULL),(98,'角斗士','Gladiator','马克西蒙斯是罗马帝国战功显赫，受人拥戴的大将军。老国王马库斯·奥利利乌斯对大将军赏识有加，有意加冕于他。老国王对将军这种超越亲情的宠爱自然招来太子康莫迪乌斯的妒忌与不安，太子伺机杀害父亲，抢先登上王位，并马上下令诛杀大将军一家。马克西蒙斯死里逃生躲过暴君的魔爪，可是他所有的家人都未能幸免于难，返回家园，他只看到满目疮痍的破败景象。走投无路的马克西蒙斯只能投身为奴，从昔日的大将军沦为一名角斗士，在血腥厮杀中苟且求生。凭借英勇的气魄和高超的武艺，马克西蒙斯渐渐脱颖而出，晋级到罗马的大角斗场。这一次，他的剑直指暴君康莫迪乌斯，失去亲人的痛苦，沦为奴隶的屈辱，在马克西蒙斯的内心燃起了熊熊怒火。','A Hero Will Rise.',103000000,457640427,95.301296,7.9,5439,155,'2000-05-01','en','/wN2xWp1eIwCKOD0BHTcErTBv1Uq.jpg',4.3921541205778585,3,'2026-09-10',2,NULL,NULL),(100,'两杆大烟枪','Lock, Stock and Two Smoking Barrels','艾迪（尼克·莫伦）思维敏捷，是个玩牌高手。在三个好友的支持下，艾迪携巨资参加了黑社会的高额赌局，不想落入圈套，欠下50万的赌债。为了还清赌债，艾迪和朋友们绞尽脑汁，最终算计到一群毒贩身上，并为打劫购买了两杆老式烟枪。不想这群不安分的毒贩，正惦念着他们毒品供应商的钱，并在同一天实施了打劫。在毒贩们费劲周折，把毒品供应商熨的整整齐齐的钱款拿到手后，艾迪他们幸运的坐享其成。可是他们不知道，这看似简单的抢劫案背后，更有厉害的角色参与其中。他们手里的两杆破烟枪也隐藏着不少故事。在无知与莽撞中置身漩涡的他们能侥幸脱身么？笑料迭出的偶发事件里，穿插着小人物与大人物的辛酸幽默。','A Disgrace to Criminals Everywhere.',1350000,3897569,16.032594,7.5,1648,105,'1998-03-05','en','/6pJB2t3MbQUy9m5pFIBHXLqnqNd.jpg',3.7676516890644947,3,'2026-09-10',2,NULL,NULL),(103,'出租车司机','Taxi Driver','这部马丁·斯科塞斯1976年的杰作，讲述了一位精神濒临崩溃的纽约出租车司机，为解救一名未成年妓女而走上暴力之路的过于真实的故事。','On every street in every city, there\'s a nobody who dreams of being a somebody.',1300000,28262574,58.845025,8,2535,114,'1976-02-07','en','/ekstpH614fwDX8DUln1a2Opz0N8.jpg',4.110102793278685,3,'2026-09-10',2,NULL,NULL),(104,'罗拉快跑','Lola rennt','罗拉（弗兰卡•波滕特 饰）和曼尼（莫里兹•克雷多 饰）是一对年轻的恋人，其中曼尼是一个不务正业的小混混，而罗拉则是相信“天大的事情有爱情顶着”的爱情至上主义者。\r 　　一天，曼尼为老大完成一项钻石交易，带着装有10万马克的钱袋等候罗拉的接应，然而罗拉的自行车被人抢走，耽误了约定的接应时间，曼尼只好乘地铁回去。在地铁车厢里，曼尼扶起身边的乞丐，同时，看见两名警察向他走来。慌乱中，曼尼下了车，竟然把钱袋忘在了车厢里。显然，钱袋被乞丐拿走了。此时距离曼尼和老大约定见面交钱的时间只剩下20分钟，如果20分钟之内筹集不到10万马克，曼尼就会被老大杀死。走投无路的曼尼打电话向罗拉求救，如果罗拉20分钟之内不能赶到，曼尼只能铤而走险抢劫电话亭对面的超市。\r 　　考验罗拉爱情的时候到了，为了在20分钟内筹到10万马克，救出曼尼，她狂奔在向银行家父亲求助的路上。','Every second of every day you\'re faced with a decision that can change your life.',1530000,7267585,27.36562,7.2,664,81,'1998-08-20','de','/vvFSeaUKZjK21LGKKE8I67SzCyh.jpg',3.463263124631752,3,'2026-09-10',2,NULL,NULL),(105,'回到未来','Back to the Future','马蒂·麦克弗莱，一位典型的八十年代美国青少年，意外被一台由钚动力驱动的德罗宁“时间机器”送回到1955年——这台机器由一位略带疯狂的科学家发明。在这段时常癫狂、总是惊人的穿越之旅中，马蒂必须确保他那正值青春期的未来父母相遇并坠入爱河，他才能顺利返回未来。[官方简介]','He\'s the only kid ever to get into trouble before he was born.',19000000,381109762,76.603233,8,6079,116,'1985-07-03','en','/vN5B5WgYscRGcQpVhHl6p9DDTP0.jpg',4.4063404248826785,3,'2026-09-10',2,NULL,NULL),(106,'铁血战士','Predator','美军一架直升机在南美洲的原始森林坠毁，那里盘踞着不怎么友好的当地游击队。美军特种兵少校达奇（阿诺•施瓦辛格 Arnold Schwarzenegger）率领部下亲自前往搜救。他们在森林里很快就发现了失踪的飞行员的尸体，死状恐怖。大家都认为那是当地的游击队干的，愤怒的队员开始寻找当地游击队的基地，要为同伴报仇。然而当他们发现当地游击队的营地时，发现当地人也被一种恐怖气氛所笼罩着。随后，队员们相继被袭击身亡，但每次都没发现敌人的半个影子。对方就像凭空隐形了一样。孤身一人的达奇决心凭自己的力量面对这股神秘恐怖的力量……','If it bleeds, we can kill it...',18000000,98235548,50.009408,7.3,2093,107,'1987-06-11','en','/k3mW4qfJo6SKqe6laRyNGnbB9n5.jpg',3.8727522266553107,3,'2026-09-10',2,NULL,NULL),(107,'偷拐抢骗','Snatch','The second film from British director Guy Ritchie. Snatch tells an obscure story similar to his first fast-paced crazy character-colliding filled film “Lock, Stock and Two Smoking Barrels.” There are two overlapping stories here – one is the search for a stolen diamond, and the other about a boxing promoter who’s having trouble with a psychotic gangster.','Stealin\' Stones and Breakin\' Bones.',10000000,83557872,53.595686,7.7,2912,103,'2000-09-01','en','/kJZoAHq1SLDdWjeNGtlHAnGpmFV.jpg',4.069304773582268,3,'2026-09-10',2,NULL,NULL),(111,'疤面煞星','Scarface','古巴难民青年托尼（阿尔•帕西诺 Al Pacino 饰）逃难来到了美国的迈阿密，成了一个典型的天不怕、地不怕的美国街头小混混。托尼在当地的一个毒枭手下干活，因其心狠手辣、胆大心细，十分出色地帮老大完成了几件任务而迅速受到赏识，成为毒枭的第一得力助手。然而托尼并没有就此满足，他先是从委内瑞拉的毒枭那里接下了大单子，接着将自己的眼中钉一颗颗除去，势力不断扩大。当他的老大感受到威胁时已经太晚了，托尼将老大干掉然后一统了迈阿密毒品市场的天下。托尼得势后他的性格开始变得疑神疑鬼，对周围的人甚至至亲的家人、好兄弟都充满怀疑。疑心使他逐渐走上了不归路！','The world is yours...',25000000,65884703,70.105981,8,2948,170,'1983-12-08','en','/iQ5ztdjvteGeboxtmRdXEChJOHh.jpg',4.182785585403502,3,'2026-09-10',2,NULL,NULL),(114,'风月俏佳人','Pretty Woman','爱德华·刘易斯是个身家百万的企业巨头，也是个潇洒迷人的青年男子。但是麻烦的是他总是搞不好和女人的关系，最近，他与女友的关系又破裂了。 爱德华到洛杉矶出差。一天夜里，他向他的朋友——律师菲利普借了一辆高级轿车想出去解闷，却不知不觉将车开到了红灯区。在一条林荫道上，迷失方向的爱德华只好向一位年轻漂亮的妓女维维安问路。维维安的美丽活泼吸引了爱德华。在付出一笔小费之后，维维安答应送他回旅馆。当回到套间里时，爱德华已经不想让维维安离开了。于是他又继续“雇”了她一夜。爱德华发现自己喜欢上了维维安，但又碍于面子不能出口。菲利普出了个主意，花3000元雇她一周作为出席交际活动的女伴。维维安接受了爱德华的要求。当她装扮停当赶到时，看上去俨然是一位贵妇人。在用餐时，维维安对年轻的戴维发生了兴趣；而在马球比赛时，两人又热切交谈。这引起了爱德华的醋意大发。回到旅馆后，维维安发现自己已爱上了爱德华，两人谁也不能离开对方了。一周很快过去，爱德华想要出钱把她安置在纽约一所公寓里，维维安干脆地拒绝了。维维安离开了爱德华回到自己的公寓，她决定去上学，开始重新做人。正当她准备出门时，爱德华的汽车已停到了门外……','Who knew it was so much fun to be a hooker?',14000000,463000000,45.473484,7,1746,119,'1990-03-23','en','/oVKX1Pt1q7jXTkTk51mu2S0sAB0.jpg',3.7466468832844746,3,'2026-09-10',2,NULL,NULL),(115,'谋杀绿脚趾','The Big Lebowski','勒保斯基（杰夫·布里吉斯 Jeff Bridges 饰）绰号“督爷”，是个无所事事的中年混混，终日最大的消遣就是和两个同样无能的朋友沃特（约翰·古德曼 John Goodman 饰）和多尼（斯蒂夫·巴斯米 Steve Buscemi 饰）打保龄球。一日，一群打手把他错认成城里和他同名同姓的那个百万富翁加以威胁，临走还尿在他的地毯上。平白无故吃亏的督爷只好跑去找那个富翁（戴维·哈德莱斯顿 David Huddleston 饰）赔偿，未果后自作主张偷了富翁一块地毯。几日后富翁又把督爷找去帮忙，因其年轻妻子邦妮（塔拉·雷德 Tara Reid 饰）遭到绑架，督爷被要求帮忙送赎金给绑匪，就此和两个朋友一起卷入一场哭笑不得的犯罪事件。','Times like these call for a Big Lebowski.',15000000,46189568,49.230089,7.8,2926,117,'1998-03-06','en','/3bv6WAp6BSxxYvB5ozKFUYuRA8C.jpg',4.0847592164953594,3,'2026-09-10',2,NULL,NULL),(116,'Match Point','Match Point','Match Point is Woody Allen’s satire of the British High Society and the ambition of a young tennis instructor to enter into it. Yet when he must decide between two women - one assuring him his place in high society, and the other that would bring him far from it - palms start to sweat and a dark psychological match in his head begins.','Passion Temptation Obsession',15000000,85306374,30.669913,7.3,1105,124,'2005-10-26','en','/xZdhiURivaWt99DquQU8xBp9Ezn.jpg',3.6404067725798526,3,'2026-09-10',2,NULL,NULL),(117,'铁面无私','The Untouchables','在30年代的芝加哥，禁酒令的颁行使贩卖私酒成了 极为有利可图的行当。黑帮首领卡邦使用暴力手段控制着走私酒的市场，犯下了累累罪行。新来的联邦官员纳斯决心打击酒类走私的活动，但他的第一次行动却因走漏了消息而以失败告终。  　　 在一位老警员马龙的领导下，纳斯重新振作起来，并且组成了一个行动小组，独立进行打击酒类走私的活动。纳斯摧毁了卡邦的地下仓库，并且拒绝了卡邦的贿赂。邪恶的卡邦对纳斯发出了威胁。但纳斯毫不妥协，又在边境查获了卡朋的走私车队，并且抓到了卡帮的一位重要手下。马龙设法迫使他答应作指控卡帮的证人，但就在法庭外的电梯里，证人和行动小组的一位成员却都被卡邦的手下所暗杀。愤怒的纳斯前去找卡邦算帐，被老练的马龙制止。马龙从卡邦相勾结的警察局长那里得到了情报。  　　 然而，就在纳斯前往马龙家时，马龙已经被卡朋的杀手袭击，生命垂危，依据马龙所留下的线索，纳斯等人前往车站埋伏，一场枪战过后，抓住了卡邦的记帐员。卡邦以逃税的罪名被起诉，卡邦的手下又企图采取 行动，但却被纳斯察觉，在经过一番效量后，纳斯除掉了杀手，为朋友们报了仇，同时，他还得到了一份卡邦的行贿名单。 在法庭上，纳斯巧妙地使卡邦被判有罪。 这场较量，终于以正义战胜邪恶而结束。','What are you prepared to do?',25000000,76270454,38.272889,7.6,1384,119,'1987-06-02','en','/tPq0R4jTO4Ey8ZspFaWK9wGA4Ls.jpg',3.7842782631639786,3,'2026-09-10',2,NULL,NULL),(118,'查理和巧克力工厂','Charlie and the Chocolate Factory','话说在一个离我们不太远又不太近的城市里，有一座很大很大的巧克力工厂，据说这是世界上最大的巧克力工厂，它的拥有者名叫威利·旺卡先生。虽然每天有很多辆货车把成箱成箱的巧克力从工厂里面运到各地，但是这么多年来，城里人谁都没见过工厂里的工人——到底是什么人在生产这些好吃的巧克力呢？工厂里面究竟藏着什么样的设备呢？……旺卡先生的巧克力工厂成了这个城市最大的迷。　　查理·巴克特住在这个城市里面，是个再普通不过的小男孩，唯一让他有那么点儿不普通的就是——他的家很穷，穷得买不起巧克力。只有在过生日的日子里，查理才能得到一块作为生日礼物的巧克力，那是多么难得的奢侈品啊！　　突然有那么一天，威利·旺卡先生在城里发出广告：他将邀请5位小客人参观他的工厂，而邀请函金券就藏在刚出厂的巧克力里面——只要能吃出金券就可以参观巧克力工厂！于是，一时间全城的孩子们以及一些孩子的家长们都疯狂地扑向巧克力，一块接一块地吃着巧克力，希望能得到金券。当然，此时谁都不知道，旺卡先生的邀请计划其实是在为巧克力工厂寻找合适的继承人。　　尽管查理买不起巧克力，但他依然得到了一张金券（至于他是如何得到的，恕不透露。自己看电影去！），而另外4张金券的持有者分别是：贪婪、肥胖、见到巧克力不要命的男孩奥古斯塔斯；傲慢、骄横、占有欲往超强的女孩威路卡；刻薄、自私、嗜食口香糖并且爱捉弄人的小姑娘维奥莱特；以及冷酷、残暴、痴迷电子游戏和电视的男孩迈克。在旺卡先生的带领下，这5位孩子参观了奇妙无比、充满魔幻色彩的巧克力工厂，终于知道了这个工厂的巧克力是怎么制作出来的。那么谁能成为最后的继承者呢？','Willy Wonka is semi-sweet and nuts.',150000000,474968763,53.905592,6.7,3624,115,'2005-07-13','en','/iKP6wg3c6COUe8gYutoGG7qcPnO.jpg',3.883292896398057,3,'2026-09-10',2,NULL,NULL),(120,'指环王1：护戒使者','The Lord of the Rings: The Fellowship of the Ring','J.R.R.托尔金的文学巨著首次以电影形式磅礴呈现——这是一场正义对抗邪恶的史诗冒险，一段关于友谊力量与个人勇气的传奇，更是一次为人类纪元开辟道路的英雄征程。','',93000000,871368364,38.287,8.445,8705,178,'2001-12-18','en','/dvNHlWMxba5f9r8xS9tILLUig8m.jpg',4.536833597386343,3,'2026-09-10',2,NULL,NULL),(121,'指环王2：双塔奇兵','The Lord of the Rings: The Two Towers','在J.R.R.托尔金史诗三部曲的第二篇章中，护戒同盟队面对难以想象的敌军与诡谲阴谋，同时见证了远古奇迹与同胞未觉醒的力量。','',79000000,926287400,30.037,8.428,7487,179,'2002-12-18','en','/b0DbmadMgfM1Rni8vhaJwDZ1sj1.jpg',4.472604284345876,3,'2026-09-10',2,NULL,NULL),(122,'指环王3：王者无敌','The Lord of the Rings: The Return of the King','索伦大军为剿灭人类种族，已对刚铎都城米那斯提力斯展开围攻。这座昔日的伟大王国由一位日渐衰弱的摄政王守护，此刻比任何时候都更需要它的王者归来。但阿拉贡能否回应血脉的召唤，成为命定之君？中土世界的命运，正系于他宽阔的双肩。','',94000000,1118888979,41.5696,8.505,8064,201,'2003-12-17','en','/kKUgYEOVebuu21N0KnQiGpIStiN.jpg',4.540294263057096,3,'2026-09-10',2,NULL,NULL),(128,'幽灵公主','もののけ姫','室町时代，生活在偏远村落的少年阿席达卡为了保护族人，与一头被邪魔侵蚀的山猪神交战，却因此受到可怕的诅咒。为了寻找诅咒的来源和活下去的方法，他离开故乡前往西方。在旅途中，阿席达卡来到一片古老森林附近，发现以黑帽大人为首的人类为了炼铁不断开采资源，与守护森林的神祇陷入日益激烈的冲突。他也由此遇见了由山犬养大、憎恨人类破坏森林的少女小桑。面对为了生存开拓土地的人类与誓死守护家园的森林生灵，阿席达卡逐渐被卷入双方无法调和的争斗，并试图寻找一条不必以毁灭彼此为代价的道路……','The Fate Of The World Rests On The Courage Of One Warrior.',26500000,159375308,60.732738,8.2,1983,134,'1997-07-12','ja','/cMYCDADoLKLbB83g4WnJegaZimC.jpg',4.079261932622522,3,'2026-09-10',2,NULL,NULL),(129,'千与千寻','千と千尋の神隠し','10岁的千寻跟随父母搬家途中，意外穿过一条神秘隧道，闯入了一个属于神灵的奇异世界。父母因为擅自吃下供奉给神灵的食物而被变成猪，惊慌失措的千寻则在神秘少年白龙的帮助下得以留下。为了在这个世界生存并寻找救回父母的方法，她不得不到汤婆婆掌管的“油屋”浴场工作。在形形色色的神灵与不可思议的遭遇中，原本胆小任性的千寻开始学会独自面对困难，而她也必须找到离开这里、带父母重返人类世界的方法……','',15000000,274925095,35.4064,8.534,3840,125,'2001-07-20','ja','/dnwMqbndJpOEhoVqjlMU9U7LFle.jpg',4.3174709795309445,3,'2026-09-10',2,NULL,NULL),(134,'逃狱三王','O Brother, Where Art Thou?','影片由家喻户晓的科恩兄弟导演，电影原声大碟获得第44届格莱美最佳年度专辑大奖。30年代初，密西西比州荒野的监狱里，唠唠叨叨、油嘴滑舌的艾弗瑞特（乔治·克鲁尼 George Clooney 饰）整天打着各种逃跑的鬼主意。在成功说服了狱友——头脑简单的德尔玛（蒂姆·布雷克 ·尼尔森 Tim Blake Nelson 饰）和贼大胆的皮特（约翰·特托罗 John Turturro 饰）之后，艾弗瑞特的越狱大计终于得以实现，三个穿着犯人服、拖着手铐、脚镣的罪犯叮叮当当地踏上了通往自由之路。据艾弗瑞特说，在密西西比河边还埋藏有一大笔赃款赃物。逃亡途中，他们不仅要对付各种各样令人棘手的突发事件，还要与追捕他们的执法官库利斗智斗勇。这个锲而不舍的家伙发誓要把这三个“脱网之鱼”送回监狱。这一路上意外不断，状况百出，究竟他们能否获得真正的自由？','They have a plan...but not a clue.',26000000,71868327,39.742009,7.3,1112,106,'2000-08-30','en','/2YztYilviFCYcEtDAnrOstUWGie.jpg',3.663037535435877,3,'2026-09-10',2,NULL,NULL),(137,'土拨鼠之日','Groundhog Day','菲尔（Bill Murray饰）是个气象播报员，每天除了在摄像机前给观众做风趣幽默的天气预报外，每年的2月2日他还要前往一个名为普苏塔尼的边境小镇，报导当地的土拨鼠日庆典。事实上，菲尔对这一节日相当嗤之以鼻并开始对工作感到厌倦，当他例行公事完成今年的报导后，便急不可待地想重返家园，却因为一场突如其来的暴风雪耽搁了。第2天醒来后，菲尔意外地发现时间仍然停留在前一天土拨鼠日，昨日的一切重新上演。惊讶、不信、刺激、狂喜、烦闷、焦虑、不安、绝望、倦怠等各种情绪轮流侵占菲尔的感官领域，可无论他如何选择度过这一天，他都始终无法再前进一步，开始了他重复的人生。','He\'s having the worst day of his life... over, and over...',14600000,70906973,52.744331,7.4,2301,101,'1993-02-11','en','/gCgt1WARPZaXnq523ySQEUKinCs.jpg',3.928664575445425,3,'2026-09-10',2,NULL,NULL),(141,'死亡幻觉','Donnie Darko','一名问题少年在诡异地逃过一场离奇事故后，不断被一个穿着巨型兔子装的神秘男子幻象纠缠，并被操纵犯下一连串罪行。','You can never go too far',6000000,1270522,61.210016,7.7,3452,113,'2001-01-18','en','/j2AtZFsflxiluaNtajMTI0Avm8C.jpg',4.135934186863858,3,'2026-09-10',2,NULL,NULL),(142,'Brokeback Mountain','Brokeback Mountain','Brokeback Mountain is an Ang Lee film about two modern day cowboys who meet on a shepherding job in the summer of ’63. The two share a raw and powerful summer together that turns into a life long relationship conflicting with the lives they are supposed to live.','Love is a force of nature.',14000000,178043761,44.135568,7.5,1480,134,'2005-09-02','en','/aByfQOQBNa4CMFwIgq3QrqY2ZHh.jpg',3.7988063129802647,3,'2026-09-10',2,NULL,NULL),(146,'卧虎藏龙','卧虎藏龍','十九世纪的中国，一位侠士将青冥剑赠予红颜知己，宝剑失窃后众人踏上寻剑之旅。追踪线索引向贝勒府，随着神秘刺客的出现与另一段爱情故事的展开，剧情走向陡然转折。','A timeless story of strength, secrets and two warriors who would never surrender.',17000000,213525736,45.742254,7.2,927,120,'2000-10-01','zh','/28FX5rCNo6p602DzgPOTNZjyMPh.jpg',3.604714465444987,3,'2026-09-10',2,NULL,NULL),(149,'阿基拉','AKIRA','1988年7月，关东地区使用新型炸弹进行爆破，第三次世界大战即刻爆发。31年后，人类从一片废墟中重建都市，东京湾上建立了巨大城市——新东京。世界仿佛要恢复到以前的繁荣。2019年的一个夜晚，新东京郊外的封闭高速公路上，暴走族团体正在公路上飙车。带头的少年，是一名叫做金田的职业高中学生。突然，街上出现了一位奇怪的矮个男子，暴走族少年铁雄为躲避车祸连人带车飞出公路。正当金田要拿那位男子问罪之时，军队驾驶直升飞机赶到将那位矮个男子与铁雄一起收押。铁雄进入了一个陌生的地方，这里似乎在从事超能力的研究，而金田则在盘算如何营救铁雄。二人都不知道，他们的未来因为神秘力量——阿基拉已经开始了巨大的变化。','Neo-Tokyo is about to E.X.P.L.O.D.E.',8000000,553171,39.338097,7.8,773,124,'1988-07-16','ja','/lR7wNtyi8qCwEgIESYzp5j9uZdv.jpg',3.628631105593765,3,'2026-09-10',2,NULL,NULL),(152,'星际旅行1：无限太空','Star Trek: The Motion Picture','寇克将军，欢迎您重返企业号！一团硕大无朋的高能离子云，在遥远而神秘的太空中迅疾地飘移。这团能量云具有无坚不摧的威力，足以毁灭宇宙间任何物质结构。在它所划过的轨迹上，早已有好几艘分属银河三大势力的星舰遇难了。地球：银河系星球联邦的重镇，星际舰队总部的所在地。在位于北美洲旧金山的星际联邦舰队总部，寇克将军正像往常一样百无聊赖无所事事，突然间却接到了一个再好不过的命令检视企业号准备执行紧急任务。原来地球的防卫体系己经发现了那团高能离子云，而且侦测出它正对准地球飞来。寇克将军的任务，就是要赶在它到达地球之前，率领企业号先迎上去一探究竟。','The human adventure is just beginning.',35000000,139000000,24.616634,6.2,530,132,'1979-12-06','en','/zC7uTv8MsELsL0pd327YiKkZsjP.jpg',3.2636006814461465,3,'2026-09-10',2,NULL,NULL),(153,'迷失东京','Lost in Translation','失眠的鲍勃与夏洛特——两位身在东京的美国人——某夜在豪华酒店酒吧相遇。这次偶然邂逅很快发展为一段出人意料的友谊。两人结伴探索东京，与当地居民发生种种常令人捧腹的际遇，最终在对生命可能性的崭新信念中找到了慰藉。[焦点影业]','Everyone wants to be found.',4000000,119723856,45.66662,7.3,1895,102,'2003-08-31','en','/3jCLmYDIIiSMPujbwygNpqdpM8N.jpg',3.8343221489677197,3,'2026-09-10',2,NULL,NULL),(154,'星际旅行2：可汗怒吼','Star Trek II: The Wrath of Khan','邪恶的可汗逃脱十五年前被寇克船长拘禁的星球，他本人是一位智勇双全的领袖，但此刻已变成一个邪恶的狂人，他誓言要向寇克船长讨回血仇。于是他先劫持了一艘联邦战舰，后又偷取了寇克船长的儿子和旧情人制造的毁灭性武器。并引诱企业号投入他精心设计的圈套。','At the end of the universe lies the beginning of vengeance.',12000000,96800000,22.434102,7.3,675,113,'1982-06-03','en','/I1TxmhS1BdZNIZIdlGPfuhg18T.jpg',3.471327615707653,3,'2026-09-10',2,NULL,NULL),(155,'蝙蝠侠：黑暗骑士','The Dark Knight','在蝙蝠侠、警官詹姆斯·戈登和地方检察官哈维·丹特的共同努力下，哥谭市的犯罪势力受到前所未有的打击。然而，自称“小丑”的神秘罪犯突然出现，以毫无规则的暴力和精心策划的犯罪不断挑战城市秩序，也将蝙蝠侠、戈登和丹特一步步逼入道德与人性的困境。面对一个无法用常规逻辑理解的敌人，蝙蝠侠必须在守护哥谭与坚守自身原则之间作出艰难选择……','',185000000,1004558444,51.649,8.535,12002,152,'2008-07-16','en','/qYB7QqwT1NtTW9aCwtopGy80rmA.jpg',4.676538877580969,3,'2026-09-10',2,NULL,NULL),(157,'星际旅行3：石破天惊','Star Trek III: The Search for Spock','2285年，在与可汗的战斗中损坏的联邦星舰进取号，返回了地球的太空港以进行维修。柯克还在为斯波克的死感到悲伤。麦科伊医生出现了种种异常的行为：如擅自闯入被封锁的斯波克原来的舱房、胡言乱语等，最后他被送进了医院进行精神检查。斯科提被另分派到了联邦星舰精进号。星际舰队指挥部对新形成的创世星下达了禁入令。柯克被告知，进取号即将除役。斯波克的父亲沙瑞克找到柯克并告诉他，斯波克的遗体必须返回瓦肯星，否则他的灵魂就不得安息。沙瑞克要求柯克必须回到创世星，寻回斯波克的遗棺并将它带回瓦肯星——而斯波克临死前与麦科伊进行了心灵融合，因此带有斯波克灵魂的麦科伊也必须前往瓦肯星。可是，星际舰队拒绝让陈旧的进取号离开太空港。从医院出来后听闻消息的麦科伊，企图招募一艘飞船回到创世星。在与人争吵时他被逮捕，但这并没有影响到整个计划：在柯克、斯科特、苏鲁、乌乎拉和切科夫的帮助下麦科伊顺利逃脱，并一同登上了被废弃的进取号。为了避免被追击，斯科提还破坏了精进号的引擎。六名伙伴冒着毁掉毕生事业的风险，驾驶进取号航向创世星。其间，克林贡人得知了创世计划和创世星的消息。由于担心联邦将其改造为一种新式武器，克鲁格船长率领一艘克林贡猛禽战舰，去夺取或摧毁这一战略性的武器。','A dying planet. A fight for life.',18000000,87000000,15.314027,6.4,434,105,'1984-05-31','en','/Aa6fQItWwfC6YKUNkxyMCCcMrOb.jpg',3.2201971023533256,3,'2026-09-10',2,NULL,NULL),(161,'十一罗汉','Ocean\'s Eleven','丹尼奥逊（乔治-克鲁尼饰,George Clooney饰）是刚从监狱假释出来的大盗，马上又操起了老本行，这次他的目标是为了盗取赌城富豪泰瑞（安迪•加西亚 Andy Garcia 饰）的一亿五千万金钱。泰瑞来头不小，于是丹尼精挑细选了11个高手前来助阵——有扑克天才拉提斯 （布拉德•皮特 Brad Pitt 饰）、爆破专家、扒手大王、杂技演员。精密的盗窃计划开始了。拉提斯却发现了一个秘密，丹尼的前妻竟然和泰瑞有着不寻常的关系。泰瑞举行一个拳击比赛，那一亿五千万就是比赛的奖金。行动就安排在那一晚，拉斯维加斯的夜晚因为这次周密的盗窃计划波澜起伏。','Are you in or out?',85000000,450717150,60.929352,7.2,3783,116,'2001-12-07','en','/hQQCdZrsHtZyR6NbKH2YyCqd2fR.jpg',4.035478025384322,3,'2026-09-10',2,NULL,NULL),(162,'剪刀手爱德华','Edward Scissorhands','爱德华（约翰尼·戴普 饰）是一个机器人，他拥有人的心智，却有一双剪刀手，孤独地生活在古堡里，闯入古堡的化妆品推销员佩格把他带回家，让他走进了人类的世界。单纯的爱德华爱上了佩格的女儿金（薇诺娜·瑞德 饰），金也慢慢的被爱德华的善良所吸引。但是，一连串的意外事情让周围的人邻居对爱德华的态度从喜欢变成无法接受，爱德华痛苦地发现，他总是好心办坏事，连自己的爱人都不能拥抱，或许，他注定就不属于这个世界。','His scars run deep.',20000000,53000000,47.51363,7.5,3601,105,'1990-12-05','en','/e0FqKFvGPdQNWG8tF9cZBtev9Em.jpg',4.0667733640949395,3,'2026-09-10',2,NULL,NULL),(163,'Ocean\'s Twelve','Ocean\'s Twelve','Danny Ocean reunites with his old flame and the rest of his merry band of thieves in carrying out three huge heists in Rome, Paris and Amsterdam – but a Europol agent is hot on their heels.','Twelve is the new eleven.',110000000,362744280,76.840712,6.4,2124,125,'2004-12-09','en','/pE5anFf7nf6ah7V3VRezQ1KSovi.jpg',3.737181223939563,3,'2026-09-10',2,NULL,NULL),(165,'回到未来2','Back to the Future Part II','马丁（Michael J. Fox 饰）才回到现实世界与女友团聚，布朗博士（Christopher Lloyd 饰）就心急火燎地把他们带到了30年后的未来世界，原来这一次是马丁未来的两个孩子因参与抢劫锒铛入狱，博士要携马丁一起阻止悲剧发生。周旋一番后，两个孩子被成功挽救，但三人回到现实世界后，却发现周遭发生了天翻地覆的变化，世界被贝夫（Thomas F. Wilson饰）所控制，马丁的父亲乔治惨死，母亲洛莲（Lea Thompson 饰）竟然成了贝夫的妻子！这一切都是因为时光机器的秘密不慎被未来的老贝夫识破，他偷偷回去捣鬼，竟因此使得整个世界都在他的掌握下！马丁与博士再次踏上时光穿梭的征途，希望将世界扳回正轨。','Roads? Where we\'re going, we don\'t need roads!',40000000,332000000,43.345252,7.4,3829,108,'1989-11-20','en','/hQq8xZe5uLjFzSBt4LanNP7SQjl.jpg',4.0488779311594705,3,'2026-09-10',2,NULL,NULL),(167,'K星异客','K-PAX','改编1995年基恩·布汝尔出版的同名科幻小说，在美国2541家影院首映时，以1750万美元的成绩成为当时北美票房的冠军。片中，以《美国美人》赢得奥斯卡影帝的凯文·斯贝西拥有深沉内敛的演技。此次，他在《K星异客》中饰演一名自称来自K-PAX星球的外星人Port。在《政界风云》中因饰演美国总统而获奥斯卡最佳男配角提名的资深演技派男星杰夫·布里奇斯，则饰演心理医师马克。影片借普络特之口，道出了地球社会的种种弊端。这是该片的长处，短处：它强化了社会意义，但考虑到如此手法在以前的电影中已多次出现，这里显得比较做作，说教味浓了些','Change the way you look at the world.',48000000,50315140,30.920075,7.1,695,120,'2001-10-22','en','/pJjKpJCsshE8NBliLJI5zdpvtKe.jpg',3.470344896974483,3,'2026-09-10',2,NULL,NULL),(168,'星际旅行4：抢救未来','Star Trek IV: The Voyage Home','太空探测器发出的怪声导致地球风暴，并面临自毁的威胁。寇克船长和他们的船员再度担负起拯救人类的使命。他们发现怪声其实是座头鲸的呼唤，唯一的选择就是回到20世纪去带回一只座头鲸来对探测器作出回应。','The key to saving the future can only be found in the past.',24000000,133000000,22.258428,6.9,477,119,'1986-11-25','en','/mKK2L17XGHFbVp4SPoII9PLVCvd.jpg',3.3178124681021726,3,'2026-09-10',2,NULL,NULL),(169,'铁血战士2','Predator 2','洛杉矶最近黑帮的团伙成员一个个被人残忍杀害，警局认为黑帮火拼又开始了。于是派出探员麦克（丹尼•格洛弗 Danny Glover 饰）去调查这次事件，并将凶徒乘之于法。不料麦克出师不利，反遭这些凶徒袭击，差点丧命。凶徒能杀人于无形，具有隐身的能力。原来这是一群来自外星的专门狩猎人类的怪物，能隐身、身上具有多种武器并能利用红外线监测到人类准确位置。联邦调查局也注意到了这一情况，他们派出了特别行动小组想活抓这些怪物作研究。然而麦克心里只有消灭怪物为受害者报仇这一念头……','Silent. Invisible. Invincible. He\'s in town with a few days to kill.',35000000,57120318,27.934978,5.9,730,108,'1990-11-20','en','/pEIqdfUXOEYpJ1S1s5JRCYkvHEc.jpg',3.297624545401016,3,'2026-09-10',2,NULL,NULL),(170,'惊变28天','28 Days Later','剑桥科研小组发现一种可以令传染者处于永久杀人状态的病毒，这种病毒传染速度极快，且无法抑止。动物保护组织成员不慎释放了实验室中一批携带该病毒的大猩猩后，繁华的伦敦于短短28天变成一座死城。自行车快递员于28天后的某一个早晨醒来时，发现自己赤身裸体躺在一家破旧的医院里，周围一片狼藉，令他怀疑是在梦中。夜晚来临时，他受到被病毒传染了的人的袭击，危急时刻幸被施莲娜和马克搭救，他也才知晓伦敦发生的一切，而这座城市没被传染的人，仅剩极小部分伦敦居民和一些驻守在曼彻斯特外的军人。当三人费劲千辛万苦找寻到拯救未来的一线希望时，才发现真正恐怖的还不是病毒。','His fear began when he woke up alone. His terror began when he realised he wasn\'t.',5000000,82719885,45.490374,7.1,1777,113,'2002-10-31','en','/sQckQRt17VaWbo39GIu0TMOiszq.jpg',3.7727523517914117,3,'2026-09-10',2,NULL,NULL),(172,'星际旅行5：终极先锋','Star Trek V: The Final Frontier','本片是《星舰旅行》系列电影的第五集，由原班人马主演，但改由饰演寇克船长的威廉·赛特纳执导，也是他的导演处女作。故事描述一名神秘的疯狂幻想家赛布克占领了一个遥远的星球，劫持星际大使作人质，强迫企业号宇宙飞船紧急出发，进入没有人做访过的未知宇宙去寻找传说中的上帝，但上帝到底是谁呢？本片的开场颇具震撼力，可惜发展下去难以为继，使大部分的篇幅在过分玄奥的故事框架中兴圈子，只能靠壮观的视觉特效维持其吸引力，幸好结局是略有起色，不致令观众太过失望。正在基地修整的企业号接受了一项紧急任务，科克船长一行奉命到属于中立区的宁布星球，解救遭到叛徒控制的乐园市民。叛军挟持了企业号到银河系中心去寻找根源。','Adventure and imagination will meet at the final frontier.',30000000,70200000,19.578249,5.6,376,107,'1989-06-09','en','/35ulPi4Bx1vsl8OEGLFR9um8ios.jpg',3.1143188832676936,3,'2026-09-10',2,NULL,NULL),(173,'海底两万里','20,000 Leagues Under the Sea','本片讲述在1868年航运界传言南海中有海怪破坏船只，各国政府被迫派遣军舰维护航道安全，及调查海怪真伪。不料调查舰被不明怪物撞沉，只有阿洛亚斯教授、助手康索及鱼叉手尼德蓝被鹦鹉螺核子潜艇救起。该船由尼莫舰长指挥，对运载军火船舰均予击沉。尼莫敬重阿洛亚斯之成就，将其视为上宾。潜艇要返回瓦康尼亚基地，中途到深海探索海底世界，此处是该船粮食之主要来源。教授为其科技动力来自海底貂殖的技术惊叹不已，但尼德蓝一心想逃跑，却在荒岛中被食人族逐出。他又查出基地位置，用瓶子装信向外通知。到达瓦康尼岛时，军舰已围住该基地。尼莫破坏基地，引起核子爆炸，尼莫亦中弹命危，临死前将鹦鹉螺号驶入海底坟场加以破坏。','The mightiest motion picture of them all!',5000000,28200000,9.358197,6.8,157,127,'1954-12-23','en','/vIDuo8Y4Aabglofhd2ONsWADLUg.jpg',2.9910523482871327,3,'2026-09-10',2,NULL,NULL),(174,'星际旅行6：未来之城','Star Trek VI: The Undiscovered Country','星际联邦的大敌克林贡帝国因为连年争战，经济及生态环境破坏殆尽，一位克林贡领袖遂在企业号太空船护送下前往地球谈和，中途却遭到阴谋份子暗杀，并且嫁祸企业号。','The battle for peace has begun.',27000000,96900000,16.188572,6.7,413,113,'1991-12-05','en','/rF7ntVAuYdiF66MQUdNb4hDXU1L.jpg',3.243020680024986,3,'2026-09-10',2,NULL,NULL),(176,'电锯惊魂','Saw','亚当渐渐从昏迷中苏醒过来，发现自己被锁在一间破旧的地下室内。地下室相对的另一个房间，还锁着一个不知所措的劳伦斯医生。两个人的中间竟然有一具满身血污的死尸，手中握着一把点三八手枪。他们不知道自己为什么被绑架，但是遗留的磁带却命令劳伦斯在八小时内杀掉亚当。如果劳伦斯失败，两个人都会送命；劳伦斯的妻子艾莉森(莫妮卡·波特饰)、女儿也会跟着陪葬。回想泰普警探(丹尼斯·格洛弗饰)最近正在调查的谋杀案，劳伦斯意识到他和亚当即将成为下一个受害者，而他只知道这个在幕后的变态杀人狂叫“竖锯”。时间只剩下短短的几小时，他们必须克服恐惧，弄清楚精心设计的圈套。杀人狂只留下一点点线索，以及两把不起眼的手锯——尽管它不能锯断铁铐，却足以切割血肉和骨头。','Live or die. Make your choice.',1200000,103911669,63.655973,7.2,2184,103,'2004-10-01','en','/rLNSOudrayDBo1uqXjrhxcjODIC.jpg',3.8935379312205454,3,'2026-09-10',2,NULL,NULL),(177,'渔王','The Fisher King','杰克曾是一名电台主持人，一次意外中，他的不当言辞导致了了一个名为埃德温的男人精神崩溃举枪乱射，酿成了多人伤亡的惨痛后果，心中充满内疚和痛苦的杰克从此陷入了人生的低谷无法自拔。杰克结识了名为帕里的流浪汉，令杰克没有想到的是，竟然是自己造成了帕里的疯疯癫癫。原来，帕里曾是一名学富五车的教授，他的妻子正是埃德温枪下的冤魂，帕里无法承受失去妻子的痛苦，发了疯。为了弥补自己的过失，杰克决定帮助帕里。最终，杰克不仅撮合了帕里和女秘书莉迪亚，还成功的令帕里恢复了理智。','A Modern Day Tale About The Search For Love, Sanity, Ethel Merman And The Holy Grail.',24000000,41895491,16.146572,7.2,341,137,'1991-09-09','en','/hwIYw22HmAUMobV4zsX69MgfVUz.jpg',3.2416955709680653,3,'2026-09-10',2,NULL,NULL),(179,'翻译风波','The Interpreter','在非洲出生的联合国翻译员希尔薇亚，一天无意间听到有人用只有包括希尔薇亚在内的少数人听得懂的非洲土语，讨论一项暗杀阴谋，暗杀对象是即将在联合国大会发表演说的一位非洲国家元首。而希尔薇亚在听到这项惊人秘密之后，很快也成为凶手的追杀对象。密勤局指派托宾·凯勒探员负责席希尔薇亚的安全。但凯勒在调查过程中却发掘出她过去黑暗复杂的一面，他开始怀疑她并没有完全说出实情，对她的不信任感愈来愈强烈。而他在处理这一难题的同时，也必须和这位他负责保护的陌生女子诚实分享他自己的痛苦过去。这场诡谲多变的政治暗杀行动日益逼近，希尔薇亚的人身安全也随时遭到威胁……','The truth needs no translation.',80000000,162944923,18.69984,6.2,392,128,'2005-04-08','en','/z6eHPiYrCXv6zwP6z08NfoAIEoE.jpg',3.1828654152864746,3,'2026-09-10',2,NULL,NULL),(180,'少数派报告','Minority Report','随着科技的发展，人类发明了能侦察人的脑电波的“聪明”的机器人――“先知”。“先知”能侦察出人的犯罪企图，所以在罪犯犯罪之前，就已经被犯罪预防组织的警察逮捕并获刑。乔恩（汤姆•克鲁斯 Tom Cruise 饰）就是犯罪预防组织的一个主管。在一次通过“先知”成功阻止了一起因外遇引起的双人命案之后，乔恩隐约感到了这一套完美的预防犯罪系统中隐含的秘密，那就是少数派报告。原来，共有三个“先知”一起判定一个人是否有杀人企图。当出现分歧时，按少数服从多数原则定案，但最后若证明少数那一方是正确的话，则会秘密保存一份少数派报告。乔恩一觉醒来，突然发现自己已是昔日同事的抓捕对象。乔恩唯一的出路就是找到能证明自己清白的那份少数派报告……','The system is perfect until it comes after you.',102000000,358372926,65.948959,7.1,2608,145,'2002-06-20','en','/ccqpHq5tk5W4ymbSbuoy4uYOxFI.jpg',3.9242053545792825,3,'2026-09-10',2,NULL,NULL),(182,'德国好人','The Good German','《德国好人》根据约瑟夫·卡农的同名小说改编，是由史蒂文·索德伯格执导，乔治·克鲁尼、托比·马奎尔、凯特·布兰切特主演的悬疑电影。影片以第二次世界大战结束时的柏林为背景，讲述了美国战地记者重访柏林探寻自己曾经的德国情人却陷入政治阴谋的故事。','If war is Hell, then what comes after?',32000000,5914908,5.347936,5.9,86,108,'2006-12-08','en','/3LjHC2CWDkzoiPehf3GViujws0.jpg',2.809022631290547,3,'2026-09-10',2,NULL,NULL),(184,'Jackie Brown','Jackie Brown','Jackie Brown is a flight attendant who gets caught in the middle of smuggling cash into the country for her gunrunner boss. When the cops try to use Jackie to get to her boss, she hatches a plan—with help from a bail bondsman—to keep the money for herself. Based on Elmore Leonard\'s novel “Rum Punch”.','Six players on the trail of a half a million in Cash. There\'s only one question... Who\'s playing who?',12000000,39673162,40.631671,7.3,1514,154,'1997-12-24','en','/rOUx7qg4KmEh1juEDwqzbDSL1Nr.jpg',3.7573034308849165,3,'2026-09-10',2,NULL,NULL),(186,'Lucky Number Slevin','Lucky Number Slevin','Slevin is mistakenly put in the middle of a personal war between the city’s biggest criminal bosses. Under constant watch, Slevin must try not to get killed by an infamous assassin and come up with an idea of how to get out of his current dilemma. A film with many twists and turns.','Wrong Time. Wrong Place. Wrong Number.',27000000,56308881,36.921445,7.4,1323,110,'2006-02-24','en','/x21s3p5wPww534nYj1cWakTcqz4.jpg',3.728140091528473,3,'2026-09-10',2,NULL,NULL),(187,'罪恶之城','Sin City','Welcome to Sin City. This town beckons to the tough, the corrupt, the brokenhearted. Some call it dark… Hard-boiled. Then there are those who call it home — Crooked cops, sexy dames, desperate vigilantes. Some are seeking revenge, others lust after redemption, and then there are those hoping for a little of both. A universe of unlikely and reluctant heroes still trying to do the right thing in a city that refuses to care.','Walk down the right back alley in Sin City and you can find anything...',40000000,158733820,66.003433,7.2,2691,124,'2005-04-01','en','/i66G50wATMmPrvpP95f0XP6ZdVS.jpg',3.956309256226997,3,'2026-09-10',2,NULL,NULL),(189,'罪恶之城2：蛇蝎美人','Sin City: A Dame to Kill For','《罪恶之城2》由三个独立的故事组成，其中一个来自来自弗兰克·米勒的漫画《红颜祸水》（A Dame to Kill For），另外两个则是弗兰克·米勒为电影新创的故事。《红颜祸水》（A Dame to Kill For）——这是米勒sin city系列漫画（共7部）中的一部。“续集主要来自《红颜祸水》，”米勒说，“这部漫画也是由一系列短篇组成的，包括《另一个周六夜》和另外两个故事。其中一个涉及到第一部电影中杰西卡·阿尔芭饰演的角色Nancy Callahan；这个角色是为了让几个故事能够结合在一起，并和第一部电影联系起来。”  《红颜祸水》的主要故事讲的是主人公Dwight McCarthy（第一部中由克里夫·欧文饰演），一位生活严谨，避免麻烦的摄影师，遇到了他过去生活中无法对其说“不”的那个女人，她因为遭受丈夫的虐待，面临着危险而向Dwight求助。Dwight应该相信她么？','There is no justice without sin.',65000000,39407616,85.428395,6.3,1286,102,'2014-08-20','en','/sIOSNc1Gdt6DAW2Pp2eGueKUSQC.jpg',3.619595904272225,3,'2026-09-10',2,NULL,NULL),(193,'星际旅行7：斗转星移','Star Trek: Generations','寇克等人作为嘉宾乘新企业号试航，途中收到救援任务……而在另一时空，索伦博士正阴谋毁灭星球，攻击企业号。唯一能够帮助新船长皮卡特来阻止索伦的，只有销声匿迹了78年的寇克船长。','Boldly go.',38000000,120000000,14.779041,6.4,452,118,'1994-11-17','en','/sdIknkvL1P551cgPJbOnsg04bdZ.jpg',3.228603413637291,3,'2026-09-10',2,NULL,NULL),(194,'Amélie','Le fabuleux destin d\'Amélie Poulain','At a tiny Parisian café, the adorable yet painfully shy Amélie (Audrey Tautou) accidentally discovers a gift for helping others. Soon Amelie is spending her days as a matchmaker, guardian angel, and all-around do-gooder. But when she bumps into a handsome stranger, will she find the courage to become the star of her very own love story?','One person can change your life forever.',10000000,173921954,73.720244,7.8,3310,122,'2001-04-25','fr','/nSxDa3M9aMvGVLoItzWTepQ5h5d.jpg',4.177062320593932,3,'2026-09-10',2,NULL,NULL),(196,'回到未来3','Back to the Future Part III','马丁（麦克·J·福克斯饰）从他生活的八十年代来到了1955年，根据好朋友埃米·布朗博士（克里斯托弗·劳埃德饰）于1885年留下的信件，马丁找到了博士研制的时空穿梭机。本以为可以乘坐着这台机器回到未来，马丁却意外发现了博士的墓碑，原来他在留下那封信后不久便被人杀害。为了拯救埃米博士，马丁乘坐时空穿梭机来到了1885年的美国西部。马丁能否改变历史，拯救博士的生命？二人能否成功回到未来？“回到未来三部曲”完结篇，一起与马丁乘坐时空穿梭机畅游时间。','They\'ve saved the best trip for last... But this time they may have gone too far.',40000000,244527583,45.769562,7.1,2900,118,'1990-05-25','en','/crzoVQnMzIrRfHtQw0tLBirNfVg.jpg',3.9063529885727997,3,'2026-09-10',2,NULL,NULL),(197,'勇敢的心','Braveheart','威廉·华莱士童年时，其父、苏格兰民族英雄马索·华莱士在与英军的斗争中牺牲，他开始接受父亲好友的指导，学习苏格兰文化和武术。青年华莱士（梅尔·吉布森 饰）学成回到故乡，向美丽的少女梅伦求婚，不想梅伦被英军抢去且遭杀害。在广大村民“英雄之后”的呼声中，华莱士率众揭竿起义，并与苏格兰贵族罗伯结成联盟，但不久他发现，苏格兰贵族考虑的只是自身的利益。英王为缓和局势，派伊莎贝拉（苏菲·玛索 饰）前去和华莱士谈判，由于英王只想收买华莱士，根本不顾苏格兰人民的自由和平等，谈判失败，但这一切并不为伊莎贝拉所知。伊莎贝拉归国后发现事情真相，且知晓英王正策划阴招，忙送信给华莱士，而两人的爱情，也在战争与阴谋中悄然滋生。','Every man dies. Not every man truly lives.',72000000,210000000,60.722162,7.7,3336,177,'1995-05-24','en','/or1gBugydmjToAEq7OZY0owwFk.jpg',4.12503137868194,3,'2026-09-10',2,NULL,NULL),(199,'星际旅行8：第一类接触','Star Trek: First Contact','本片是以地球人与瓦肯人的“第一类接触”事件为背景，将重心放在《星际迷航之下一代》电视系列剧中的大敌『博格人』。企业号正在宇宙空间做例行巡航时，舰长皮卡特接到密电，称博格人已联合其他星系的力量，准备向地球发起攻击。由于舰长皮卡特曾受敌方俘虏并同化，星际舰队对其不很信任，故没有派其出战。皮卡特不顾命令，仍然参与战斗，之后企业号跟随博格人的时间漩涡回到21世纪，以阻挡博格人试图改变人类的外星发展史达到征服地球的企图。','Resistance is futile.',46000000,150000000,25.6713,7,661,111,'1996-11-21','en','/xpeO5hsCnvWBiyTot9Ja7uwdmyu.jpg',3.429498591282163,3,'2026-09-10',2,NULL,NULL),(200,'星际旅行9：起义','Star Trek: Insurrection','皮卡特舰长获知百科（Data）中尉在巴库（Baku）星球被掳为人质后立刻率企业号前往营救。当他们来到巴库星球，整个星球上只居住了六百名巴库人，与世隔绝、摒弃科技、崇尚和平，过着纯朴的生活；百科被掳不像是巴库人的作风，想必另有隐情。皮卡特舰长遇到一名叫做安妮的巴库女子，经由她得知巴库人虽然看起来年轻，星球的原居民巴库其实年龄都已经超过三百岁了。面临老化的索纳（Sons）人，发现巴库人长生不老的秘诀再于巴库星球外围的特殊放射线能不断的重组基因结构。如今巴库人要遭受灭种的威胁……来自外层空间的索纳人联结星际联盟，根据原有的巴库人村落拟造了一个一模一样的环境，预谋将巴库人迁徙到这个虚拟村落，企图独享青春泉源。瑟纳人首领鲁阿弗假藉文化访查之名率众进入巴库星球，企图赶走巴库人，占领巴库星球。皮卡特舰长将所获知的情报呈报杜尔迪司令，却发现司令与星际联邦总部早已知情，并暗中参与这项阴谋。杜尔迪不理会皮卡特的抗议，下令企业号立即撤返，不得干预。毕卡舰长面临了关键性的一刻，若他服从命令就违背了当初加入星际舰队时曾立下的誓言，反之，若采取行动，他则必须放弃事业、组员、企业号、一切！来投入这场天堂之战。','The battle for paradise has begun.',70000000,118000000,19.711951,6.3,391,103,'1998-12-10','en','/z2iEcgThmiEEDZOP2GtzziUwX7o.jpg',3.195087351415212,3,'2026-09-10',2,NULL,NULL),(201,'星际旅行10：复仇女神','Star Trek: Nemesis','企业号宇宙飞船遨游在太空，在人类和外星人中间传播好意，同时也在防范敌对星球有可能的攻击行为，因为有迹象表明，星际联盟的老对头罗木兰星球有可能发起新一轮的攻击。皮卡特船长和他的船员们也在小心翼翼的观察着事态的进展，时刻准备投入战斗。  　　可就在这时，罗木兰星球发出了和谈的讯息，星际联盟命令企业号前往谈判，当皮卡特船长第一次见到罗木兰星球新的执政官后惊呆了，原来对方就是罗木兰很久以前制造的皮卡特的人类复制品，面对这个难缠的对手，皮卡特船长和他的船员们该如何是好？','A generation\'s final journey... begins.',60000000,67312826,21.605533,6.1,479,117,'2002-12-13','en','/tkgBvQLxlIALtgjJmDdSwfEGyUD.jpg',3.2222537819740587,3,'2026-09-10',2,NULL,NULL),(203,'穷街陋巷','Mean Streets','马丁·斯科塞斯以这部刻画1970年代纽约市粗粝写照的电影，确立了一代标志性导演的地位。这部美国独立电影最具影响力的作品之一，将故事背景设定在斯科塞斯少年时代封闭的小意大利区。影片跟随深陷罪恶感的小混混头目查理，展现他周旋于情绪暴烈的好友约翰尼所欠的债务、与倔强女友特蕾莎的压力之间。当这些交织的人生逐渐失控，斯科塞斯通过从富有冲击力的剪辑节奏到精心编排的原声配乐等方方面面，展现了他早熟的电影风格掌控力，创造出一部关于罪孽与救赎的震撼影像。[标准收藏]','You don\'t make up for your sins in church. You do it in the streets...',500000,3000000,17.002096,7.2,345,110,'1973-10-02','en','/9msfwOeGc9uL1iRRTBdEf15XonC.jpg',3.2470027500521463,3,'2026-09-10',2,NULL,NULL),(205,'卢旺达饭店','Hotel Rwanda','影片来源于一个真实的故事。1962年，卢旺达宣布独立后，胡图族与图西族两部族之间矛盾重重，多次发生冲突，战事持续不断。 1994年4月6日，一架载着卢旺达胡图族总统朱韦纳尔·哈比亚利马纳和布隆迪总统西普里安·恩塔里亚米拉的座机在卢旺达首都基加利上空被火箭击落，两国元首同时罹难。4月7日，空难在卢旺达国内引发了胡图族与图西族两族的互相猜疑，从而爆发了一场规模空前的武装冲突和种族大屠杀，令世界震惊的人间惨剧拉开了帷幕。被胡图族种族主义者控制的广播电台也为大屠杀的行为煽风助阵，他们叫嚣着“让一切的郁积都爆发出来吧。在这样一个时刻，鲜血将滚滚而出”，失控的人群在媒体的号召下四处搜寻和杀死图西族人，空气中弥漫着血腥的味道。 当一个国家陷入了疯狂，世界也闭上了双眼时，有一个名叫保罗·卢斯赛伯吉纳（唐·钱德尔 饰）的饭店经理却敞开了温暖的怀抱，他经营着当地一家云集着欧洲游客和军界政要的米勒·科林斯饭店，八面玲珑地运用着一切关系尽心地呵护着饭店的顾客们。保罗是胡图族人，而他的妻子塔莎娜（苏菲·奥康尼多 饰）却是图西族的，对他而言，在动荡的时局中，保护他的图西族的亲戚与朋友成为了一生中面临的最大使命与挑战。联合国维和部队的无所作为和与世界媒体的隔绝使得保罗夫妇二人和在饭店中避难的1268名当地居民更加坚定了活下去的信心与勇气，“我们一定让全世界都无地自容地去采取应有的行动”。事态越来越严重，百日之内竟有约100万人死于非命，但米勒·科林斯饭店却成为了嗜血荒漠中的一片生命绿洲。','When the world closed its eyes, he opened his arms.',17500000,38000000,28.60542,7.5,793,121,'2004-09-11','en','/7okrglkcWenBy9SpScYvusmTyan.jpg',3.565974006083101,3,'2026-09-10',2,NULL,NULL),(207,'死亡诗社','Dead Poets Society','威尔顿预备学院以其沉稳凝重的教学风格和较高的升学率闻名，作为其毕业班的学生，理想就是升入名校。新学期文学老师约翰·基汀（罗宾·威廉姆斯 饰）的到来如同一阵春风，一反传统名校的严肃刻板...','He was their inspiration. He made their lives extraordinary.',16400000,235860116,55.458584,8.1,2705,129,'1989-06-02','en','/tNvKkSnnn4Z6RCBThyK1gfCSSvv.jpg',4.146349764812463,3,'2026-09-10',2,NULL,NULL),(214,'电锯惊魂3','Saw III','当警方正企图逮捕拼图杀人狂归案之际，女医生莲恩戴伦却未警觉自己将成为下个死亡游戏的目标。某晚当莲恩从医院下班时，惨遭拼图杀人狂绑架，她醒来时发现自己被捆绑在一间废弃的空屋里头，除此之外还有另外一名被害男子杰夫；此时拼图杀人狂已经面临濒死边缘，莲恩被告知她必须让拼图杀人狂活下去，否则她和杰夫必须得死，在拼图杀人狂微弱心跳限时内，心急如焚的莲恩设法让拼图杀人狂存活，但她万万没想到，拼图杀人狂暗地里其实还有更可怕的杀人计划……','Suffering? You Haven\'t Seen Anything Yet...',10000000,163876815,33.124871,6.1,1071,108,'2006-10-27','en','/jboiItOxwwULnr4hyeiYYcJd96y.jpg',3.4222922700854506,3,'2026-09-10',2,NULL,NULL),(215,'电锯惊魂2','Saw II','凶残成性的变态杀人狂带着他新发明的杀人游戏回来了，这回他要用更诡异的方式，令他指定的游戏参与者更加深刻地体验到生命的价值。又一位带着“竖锯” 标签式的死亡特征的受害人被警方发现，这令探员艾里克马休斯重新回到之前的惊竦噩梦之中，但这一次令他意外的是杀人者留下了十分明显的线索，这些令人意料之外的收获让调查进行得十分顺利。但所有这一切其实都在“竖锯”的掌控之中，留下线索并令自己被捕正是他进行下一个邪恶游戏中的重要前提：即将有8位相互陌生的人被迫加入游戏，而更疯狂的是，除此之外的另一位游戏者已经被锁定为马休斯。在“竖锯”的策划下，又一场充满惊险的生死游戏就要开始了……','Oh Yes... There Will Be Blood.',4000000,152925093,42.187986,6.3,1251,92,'2005-10-28','en','/tdEtwpu42Y2LC3WKZMUEGeSzWr1.jpg',3.514479744177591,3,'2026-09-10',2,NULL,NULL),(217,'Indiana Jones and the Kingdom of the Crystal Skull','Indiana Jones and the Kingdom of the Crystal Skull','Set during the Cold War, the Soviets – led by sword-wielding Irina Spalko – are in search of a crystal skull which has supernatural powers related to a mystical Lost City of Gold. After being captured and then escaping from them, Indy is coerced to head to Peru at the behest of a young man whose friend – and Indy\'s colleague – Professor Oxley has been captured for his knowledge of the skull\'s whereabouts.','The adventure continues . . .',185000000,786636033,75.674458,5.7,2495,122,'2008-05-21','en','/sqafQpyJxYoRaR6oMNjjceEYB7W.jpg',3.6094499713393398,3,'2026-09-10',2,NULL,NULL),(218,'终结者','The Terminator','一名半机械人（阿诺·施瓦辛格 饰）从21世纪被派往当代洛杉矶，刺杀一位看似无辜的女子——她的孩子将在杀手所处的未来世界中扮演关键角色。[米高梅]','Your future is in his hands.',6400000,78371200,74.234793,7.3,4128,108,'1984-10-26','en','/qvktm0BHcnmDpul4Hz01GIazWPr.jpg',4.114059181629961,3,'2026-09-10',2,NULL,NULL),(219,'Volver','Volver','Raimunda (Penélope Cruz) works and lives Madrid with her husband Paco and daughter Paula. Her sister Sole (Lola Dueñas) lives nearby and they both miss their mother Irene (Carmen Maura), who died several years ago in a house fire along with their father. A former neighbor from their hometown reports that she has seen the ghost of Irene and both daughters do not believe her. After a murder and a family tragedy, Irene\'s spirit materializes around her daughters to help comfort them.','Return.',12899867,85582407,19.747809,7.3,406,121,'2006-03-16','es','/vAQgJaKFszxRIWI9Ynug80TerGd.jpg',3.3111737894970483,3,'2026-09-10',2,NULL,NULL),(223,'蝴蝶梦','Rebecca','浪漫故事在阿尔弗雷德·希区柯克精心雕琢的本片中演变为心理剧，这也是他进军好莱坞的首部作品。影片如梦似幻地改编自达芙妮·杜穆里埃1938年的小说，由迷人的琼·芳登饰演一位年轻女子，她以为自己觅得心之所向，嫁给了风度翩翩的贵族鳏夫迈克西姆·德温特（劳伦斯·奥利弗以敏锐的脆弱感诠释）。然而，当她搬进曼德利庄园——丈夫那座巴洛克风格的祖传宅邸——便很快发现，已故的前妻不仅萦绕着这座城堡，更深深困扰着性情多变、忧郁沉思的迈克西姆。作为希区柯克与制片人大卫·O·塞尔兹尼克传奇合作的起点，这部哀婉的哥特式影像由乔治·巴恩斯以惊艳的黑白摄影呈现，荣获奥斯卡最佳影片与最佳摄影奖。[标准收藏]','The shadow of this woman darkened their love.',1288000,6000000,18.426825,7.7,336,130,'1940-04-12','en','/jEOk5ZIEwQ4iK95Q3RLYAANAlcx.jpg',3.2900115356301654,3,'2026-09-10',2,NULL,NULL),(226,'男孩别哭','Boys Don\'t Cry','本片改编自真实事件：布兰登·蒂纳（希拉里·斯万克 饰）在内布拉斯加小镇上是受欢迎的“新小伙”，并与当地女孩拉娜（科洛·塞维尼 饰）相恋。当布兰登的生理性别为女性一事曝光后，拉娜的家人和朋友使他的生命陷入危机。','A true story about finding the courage to be yourself.',2000000,11540607,15.557144,7.2,353,118,'1999-09-02','en','/5Ahiw6DgiM6sfdPhsslVQpmjCPJ.jpg',3.250303396445102,3,'2026-09-10',2,NULL,NULL),(227,'小教父','The Outsiders','故事发生在六十年代的塔尔萨城，在这里，学生们分为南北两个帮派，南帮的都是一些含着金汤匙出生的富家子弟，而北帮则充斥着出身贫民窟的名不见经传的穷小子们，南北两帮向来势不两立水火不容，常常发生激烈的矛盾和冲突，是当地巨大的不安定因素之一。  　　波尼博伊（C·托马斯·豪威尔 C. Thomas Howell 饰）、约翰尼（拉尔夫·马奇奥 Ralph Macchio 饰）和达拉斯（马特·狄龙 Matt Dillon 饰）是北帮成员，彼此之间友谊十分坚实。在一场恶斗之中，约翰尼失手将南帮成员鲍勃（雷夫·加勒特 Leif Garrett 饰）杀死，在达拉斯的帮助下，波尼博伊和约翰尼藏身在一座教堂之中，这里成为了两个男孩子暂时躲避外界残酷纷争的世外桃源。','They grew up on the outside of society. They weren\'t looking for a fight. They were looking to belong.',10000000,33697647,13.455373,6.9,291,91,'1983-03-25','en','/fdtG8WeZIRLVt8wVW26XRx6L1ue.jpg',3.164637682779783,3,'2026-09-10',2,NULL,NULL),(231,'辛瑞那','Syriana','美国石油巨头Connex公司准备与一家获得哈萨克斯坦石油开采权的小公司Killen合并，并就开采权向海湾某石油国家的年轻王子纳西尔（亚历山大•希德迪格 Alexander Siddig 饰）施加压力。瑞士日内瓦某能源咨询公司的研究员布莱恩•伍德曼（马特•达蒙 Matt Damon 饰）代表公司参加了纳西尔王子在西班牙马贝拉行宫的聚会，后成为纳西尔王子的经济顾问。但美国政府却支持纳西尔王子腐败无才的弟弟继承王位，并派出CIA特工鲍勃（乔治•克鲁尼 George Clooney 饰）前往黎巴嫩实施刺杀纳西尔王子的计划。与此同时，华盛顿一家律师事务所派班尼特（杰弗里•莱特 Jeffery Wright 饰）对Connex-Killen合并事宜进行事前调查…… 　　本片获奥斯卡、金球奖和英国电影电视协会最佳男配角奖（乔治•克鲁尼），并获奥斯卡奖最佳原创剧本和金球奖最佳电影音乐提名。','Everything is connected.',50000000,94000000,16.871194,6.3,451,128,'2005-11-23','en','/co8DOFfYebS6YUpMEd8fW9Q7glR.jpg',3.221385669926838,3,'2026-09-10',2,NULL,NULL),(235,'伴我同行','Stand by Me','这是一部关于成长的电影。著名作家戈迪（理查德•德莱福斯 Richard Dreyfuss 饰）回忆起他12岁时的一次冒险活动：当时，年少的戈迪（威尔•惠顿 Wil Wheaton 饰）与他的三个小伙伴克里斯（瑞凡•菲尼克斯 River Phoenix 饰）、泰迪（科里•费尔德曼 Corey Feldman 饰）和维恩为了当一回“英雄”去河的对岸的森林里寻找一具12岁男孩的尸体。\r 　　4个少年家庭各有问题，他们都有自己的心事。在旅程中每个人的性格都被体现得淋漓尽致：四个男孩性格中的软弱和坚强，在闪火车，翻铁门，越森林等一系列的行动中被最大限度的放大；每个人都有自己可望而不可及的梦想……\r 　　1987年金球奖最佳电影、最佳导演提名，1987年奥斯卡奖最佳编剧提名','For some, it\'s the last real taste of innocence, and the first real taste of life. But for everyone, it\'s the time that memories are made of.',8000000,52287414,51.109279,7.8,1522,89,'1986-08-22','en','/vz0w9BSehcqjDcJOjRaCk7fgJe7.jpg',3.884238594095737,3,'2026-09-10',2,NULL,NULL),(238,'教父','The Godfather','40年代的美国，“教父”维托·唐·柯里昂是黑手党柯里昂家族的首领，带领家族从事非法的勾当，但同时他也是许多弱小平民的保护神，深得人们爱戴。因为拒绝了毒枭索洛索的毒品交易要求，柯里昂家族和纽约其他几个黑手党家族的矛盾激化、圣诞前夕，索洛索劫持了“教父”的参谋汤姆，并派人暗杀“教父”；因为内奸的出卖，“教父”的大儿子逊尼被仇家杀害；小儿子麦克也被卷了进来，失去爱妻。黑手党家族之间的矛盾越来越白热化。年老的“教父”面对丧子之痛怎样统领全局？黑手党之间的仇杀如何落幕？谁是家族的内奸？谁又能够成为新一代的“教父”？血雨腥风和温情脉脉，在这部里程碑式的黑帮史诗巨片里真实上演。','',6000000,245066411,54.6251,8.686,5893,175,'1972-03-14','en','/y03tzUKvkRCYwJ5NWys4W4bnS9m.jpg',4.530849090318889,3,'2026-09-10',2,NULL,NULL),(239,'热情如火','Some Like It Hot','作为影史最受喜爱的电影之一，比利·怀尔德这部炙手可热的杰作为好莱坞喜剧树立了新标杆。芝加哥乐手乔与杰瑞（托尼·柯蒂斯与杰克·莱蒙贡献了里程碑式的表演）目睹一场黑帮屠杀后，男扮女装混入一支前往迈阿密的女子乐队仓皇逃逸。乐队主唱“蜜糖”凯恩（玛丽莲·梦露正值其致命魅力的巅峰）的魅力使他们陷入越来越夸张的谎言漩涡：乔伪装成百万富翁追求她，而杰瑞的女性身份竟与一位亿万富翁订下婚约。凭借怀尔德与I·A·L·戴蒙德精心打磨的犀利剧本，以及演员间精准碰撞的化学反应，本片至今仍保持着数十年前首次震撼观众时那种令人陶醉的诙谐与鲜活。','The movie too HOT for words!',2883848,25000000,39.30982,8,808,122,'1959-03-18','en','/qp2DvLfyL45P1GAPOeBEGszRvoO.jpg',3.6753186348433875,3,'2026-09-10',2,NULL,NULL),(240,'教父2','The Godfather Part II','作为《教父》的续篇，影片延续了科莱昂家族两代权力交替的史诗。科波拉在第二部分中讲述了两条故事线：由罗伯特·德尼罗以非凡演技演绎的年轻教父维托的根源与崛起，以及迈克尔（阿尔·帕西诺饰）作为新任教父的上位之路。','',13000000,47542841,28.9866,8.572,3338,200,'1974-12-20','en','/4J8jUmjgKPggRPJqqdkjWCj2k0D.jpg',4.267452096583427,3,'2026-09-10',2,NULL,NULL),(242,'教父3','The Godfather Part III','转眼间已经是 1979 年，第二代教父麦克·柯里昂到了垂暮之年，为了灵魂的救赎，麦克慢慢结束家族的黑道事业，转投正当生意。麦克的儿子托尼酷爱艺术，无意接手家族事业，迈克尔决定让大哥逊尼的私生子，火爆好色的文森继承家业，当第三代教父。麦克的爱女玛丽和文森相恋，遭到父亲的反对，父女渐渐疏远。为了使家族资产合法化，麦克通过在梵蒂冈教廷的关系网，准备投资“屹立”集团，却遭到敌人的暗中阻挠，教皇的去世也让事情更加扑朔迷离。麦克无奈之下，只能重新选择用暴力解决问题，他的亲人也被卷入了这场血雨腥风。','All the power on earth can\'t change destiny.',54000000,136766062,59.194915,7.1,1546,162,'1990-12-24','en','/lm3pQ2QoQ16pextRsmnUbG2onES.jpg',3.765088563307869,3,'2026-09-10',2,NULL,NULL),(243,'失恋排行榜','High Fidelity','罗伯（约翰·库萨克 John Cusack 饰）是个音乐狂热爱好者，他经营着一家唱片店，店里的两名店员迪克和伯利都是音乐爱好者。一天，罗伯的女友罗拉（艾本·叶尤 Iben Hjejle 饰）跟他提出分手，他甚至搞不清楚原因。为此他做起自己的“失恋排行榜”，回顾一路以来失败的恋爱。他发现自己总是充当被甩的一方，于是他决定重新联系这些前女友，询问她们当初选择分手的原因。\r 　　与此同时，罗拉因为要搬出罗伯的住处而与他一直保持着联系。一次，罗伯从罗拉的朋友口中得知，罗拉居然开始和住在自家楼上的伊安（蒂姆·罗宾斯 Tim Robbins 饰）约会。这让罗伯大受打击，他开始不停地打电话骚扰罗拉和伊安，在他们楼下徘徊。终于有一天，转机到了，罗拉告诉罗伯，她父亲去世了…… ©豆瓣','A comedy about fear of commitment, hating your job, falling in love and other pop favorites.',30000000,47126295,23.982956,7,628,113,'2000-03-17','en','/e2LZGB62GMhv3Fo8tDZjY87I81a.jpg',3.4111429035302576,3,'2026-09-10',2,NULL,NULL),(245,'关于一个男孩','About a Boy','36岁的英国男子福瑞曼（休·格兰特饰），靠着父亲留下的遗产，过着花天酒地的生活，为了追逐美女，他竟想出了一个绝妙的泡妞方法——混入单身家长的联谊组织，因为那里有无数美丽而且容易上手的独身女人。他谎称自己是一个单身父亲，成功参加了这个组织。在组织的聚会中福瑞曼认识了单身母亲费娜（托妮·柯利特饰），她有一个聪明的儿子马库斯，在交往过程中福瑞曼与马库斯逐渐建立了一种奇怪的友谊，他们象好朋友一样交谈，互相从对方身上学到不少东西。当然，此时的福瑞曼也没有忘记自己混入组织的目的，为了追求一个名叫瑞切尔（拉切尔·薇兹饰）的漂亮单身母亲，福瑞曼甚至要求马库斯装成自己的儿子，以此作为接近瑞切尔的途径，他的泡妞计划能否成功呢？　　休·格兰特从[四个婚礼与一个葬礼]就为人们所熟悉，是目前知名度最高的英国演员之一，不过近年来他的银幕战绩不佳，能否靠此片咸鱼翻身，还是未知之数。女主角方面，拉切尔·薇兹因饰演《木乃伊系列》中的女探险家而一举成名，另一位女主角托妮·柯利特99年在《灵异第六感》中和布鲁斯威利斯的对手戏让人难忘。','One ordinary couple. One little white lie.',27000000,129000000,28.227984,6.6,607,101,'2002-04-26','en','/83IBYLmquAQOx2kN0vrXSbRkaaH.jpg',3.356673485493022,3,'2026-09-10',2,NULL,NULL),(248,'锦囊妙计','Pocketful of Miracles','醉酒的，黄铜色的苹果安妮，一个拿着一篮子苹果的乞丐，和老百老汇一样是纽约市中心的一部分。走私贩子戴夫是个苹果迷，他认为苹果能给他带来好运。但戴夫和女友奎妮·马丁需要的远不止运气，因为安妮陷入困境，只有他们能帮上忙：安妮的女儿路易丝一辈子都住在西班牙修道院，她要和伯爵和儿子一起来美国。伯爵的儿子想娶路易丝，她认为她的母亲是纽约社会的一部分。戴夫和奎尼以及他们那些流氓般的亲信们要把安妮变成一个淑女，让伯爵和他的儿子相信他们正在和纽约的精英们交往。','You have to see it to believe it!',2900000,5000000,3.370225,7.3,25,136,'1961-12-18','en','/xjXwcGJjT5tE22wazQUYH32HwU8.jpg',2.560787174801819,3,'2026-09-10',2,NULL,NULL),(251,'人鬼情未了','Ghost','年轻的银行职员萨姆（帕特里克•斯威兹）与未婚妻美莉（黛咪•摩尔）相爱极深，在朋友卡尔（托尼•戈德温）的热情帮助下，他们搬进一幢漂亮的公寓，做着结婚前的准备。某晚看戏归来时，他们遭遇持枪歹徒，与歹徒搏斗时，萨姆不幸中枪身亡，美莉悲痛欲绝。  　　萨姆变作幽灵，发现卡尔是导致他死亡的幕后策划，而为了窃取银行里的巨款，他又对美莉展开追求，以便获得萨姆所掌握的密码。为了保护美莉，萨姆常常游荡于她的周围，并渐渐地学会了如何使用力量，但他苦于无法同美莉交流。在能与幽灵沟通的灵媒奥塔的帮助下，他与美莉取得联系，但美莉起初并不相信，直到事实令她感受到萨姆的存在，可是，深深相爱的两人仍无法直接接触和交流。','A love that will last forever.',22000000,505000000,41.967005,6.9,1339,127,'1990-07-12','en','/zsbgH75dl1YQjHx3bpPlENYHpgw.jpg',3.6461853014762187,3,'2026-09-10',2,NULL,NULL),(252,'欢乐糖果屋','Willy Wonka & the Chocolate Factory','著名糖果商威利·旺克（吉恩·怀尔德 Gene Wilder 饰）公布了一条让世界震惊的喜讯，他将挑选五名幸运儿参观自己的糖果厂，其中一人将成为终身享用“旺克巧克力”特权的人。出身贫寒的小男孩查理·毕奇（彼得·奥斯图姆 Peter Ostrum 饰）幸运的成为了第五位人选。从小吃不到糖果的查理欣喜若狂，满怀期待的他带上了自己的爷爷乔（杰克·艾伯森 Jack Albertson 饰），开始了这段甜蜜的神奇之旅。而一位邪恶的陌生人正在蛊惑孩子们，谁能为他偷来糖果，就会让谁富有起来。旺克带领孩子们畅游着神奇的糖果厂，然而面对糖果的诱惑，其他四个孩子都接二连三的不见了，最后只剩下查理和他的爷爷乔。  　　本片根据罗尔德·达尔的同名小说改编而成，荣获英国第四频道评选的“最优秀的家庭电影”第八名。 ©豆瓣','It\'s Scrumdiddlyumptious!',3000000,4000000,23.981601,7.4,798,100,'1971-06-29','en','/443AFJ2Y999STMIwblF8Bm7admo.jpg',3.5417445357263637,3,'2026-09-10',2,NULL,NULL),(253,'007：你死我活','Live and Let Die','007（罗杰·摩尔 Roger Moore 饰）接到一单新任务，英国三名情报人员在美国遇害，英国政府却无法查出凶手，007赶赴异邦调查真相，意外发现这宗案件不仅与邪恶的巫术有关，还牵涉到一桩将牵动全世界的毒品案件。阴谋主使人坎南迦（亚菲特·克托 Yaphet Kotto 饰）在加勒比海上的巫岛实施着他的罪恶计划，他用巫术蛊惑愚弄着民众，并以此为幌子，内里进行疯狂的贩毒，企图成为全球毒枭。007勇闯巫岛，开始了危机重重的旅程，险象环生的过程中结识了岛上女主教罗茜，罗茜对坎南迦的统治深感不满，每次都助007顺利脱险，007再一次陷入美女的艳遇与战争的漩涡中。','Roger Moore is James Bond.',7000000,161777836,30.465138,6.4,533,121,'1973-07-05','en','/pmJMiBtY1PwffUNhOKxDnSQ2wSv.jpg',3.303571447451038,3,'2026-09-10',2,NULL,NULL),(254,'金刚','King Kong','1933年美国，经济大萧条和盲目的探险精神激励著每个人去探索陌生的领域，开拓未知的生存空间。漂亮的女演员安(娜奥米·沃茨饰)日益感觉到自己正处于纽约沮丧的气氛之中，就在事业低落的时候，一位野心勃勃的电影制作人卡尔(杰克·布莱克饰)将好运带给了她，她将成为一部最新制作影片的主演，并且影片将会在Skull岛上完成拍摄，安希望这座靠近苏门达拉岛的世外桃源会带给她一个充满刺激和兴奋的旅程。 意外加偶然，轮船最终搁浅在了卡尔的理想目的地——骷髅岛。可还没等卡尔激动地想开始自己的巨制拍摄，一群突如其来的土著野人的疯狂袭击便让几名成员丧生。好不容易逃离野人魔爪启航逃走，娇小的安却被抓走了。原来这名字都很诡异的骷髅岛果然是凶险重重，那些野蛮土著自不必说了，恐龙、野兽更是遍地都是。为了救安，大家不得不又返航回去。 被土著野人当作祭品的安不禁失声尖叫。尖叫声却意外引来了金刚的“关注”，这只巨大无比、连凶悍的恐龙也怕它几分的传奇猩猩，偏偏钟情于安。然而，它不会知道的是，这却是它悲剧命运的开始……','The eighth wonder of the world.',207000000,550000000,61.22601,6.6,2337,187,'2005-12-14','en','/6a2HY6UmD7XiDD3NokgaBAXEsD2.jpg',3.769529190824712,3,'2026-09-10',2,NULL,NULL),(257,'雾都孤儿','Oliver Twist','本片根据英国作家狄更斯1838年的名著《雾都孤儿》改编。\r 孤儿奥利弗（巴尼•克拉克 Barney Clark 饰）由教会抚养长大，9岁时被送去童工厂拣填絮，后被卖给棺材铺当学徒，屡受欺侮。奥利弗从棺材铺逃跑，步行七十英里到达伦敦，遇见小偷“机灵鬼”（哈利•伊登 Harry Eden 饰），并被收入犹太老头费金（本•金斯利 Ben Kinsley 饰）的盗窃团伙。奥利弗第一次出徒便被诬陷偷窃布朗罗先生（爱德华•哈德威克 Edward Hardwicke饰）的丝帕，并被打昏在地。被好心的布朗罗先生带回家收养，却在替布朗罗先生跑差途中被费金的同僚比尔（杰米•福尔曼 Jamie Foreman饰）抓获。比尔逼迫奥利弗协助他与同伙托比（马克•斯特朗 Mark Strong 饰）入夜行窃布朗罗先生家。小奥利弗不从，眼看命在旦夕……',NULL,50000000,42093706,20.415572,6.7,274,130,'2005-09-23','en','/ylAS0uX9tP7TlXvYD2lUS4seYql.jpg',3.1482484796244687,3,'2026-09-10',2,NULL,NULL),(261,'热铁皮屋顶上的猫','Cat on a Hot Tin Roof','布里克，一位酗酒的前足球运动员，终日借酒浇愁，冷漠抗拒妻子玛吉的深情。他与身患癌症、濒临死亡的父亲“大老爹”重逢，激起父子二人对往昔记忆与真相的汹涌回溯。','Just one pillow on her bed ... and just one desire in her heart!',3000000,17570324,16.553594,7.6,165,108,'1958-02-17','en','/5djZZECgqDGuSI1INmrdAcGRBb0.jpg',3.0640562028401024,3,'2026-09-10',2,NULL,NULL),(268,'蝙蝠侠','Batman','在罪恶横行的高汉市，有一个令罪犯们心惊胆颤的名字：蝙蝠侠。蝙蝠侠（迈克尔•基顿 Michael Keaton 饰）穿梭于最黑暗的角落，四处打击罪恶。在一次打击罪恶的行动中，蝙蝠侠令匪徒尼巴（杰克•尼科尔森 Jack Nicholson 饰）落入了化学池。尼巴因此面部神经受损，成了永远咧嘴笑的笑面人，人称“小丑”。“小丑”杀死了团伙的首领，控制了整个高汉市的黑道。“小丑”利用化学药品让人发笑而死，他用这种方法袭击了博物馆，幸得蝙蝠侠及时赶到，挫败了“小丑”的阴谋。在女友碧姬（金•贝辛格 Kim Basinger 饰）家里时，“小丑”突然袭击，蝙蝠侠巧妙躲过了袭击，意外发现“小丑”就是杀死自己的父母的仇人。“小丑”这次虏走了蝙蝠侠的女友碧姬，约定蝙蝠在教堂楼顶决一死战！','Have you ever danced with the devil in the pale moonlight?',35000000,411348924,44.104469,7,2096,126,'1989-06-23','en','/cij4dd21v2Rk2YtUQbV5kW69WB2.jpg',3.792884056515871,3,'2026-09-10',2,NULL,NULL),(272,'蝙蝠侠：侠影之谜','Batman Begins','童年亲眼目睹父母在高谭市街头被杀后，布鲁斯·韦恩始终被恐惧与愤怒所困扰。成年后，他离开故乡周游世界，深入犯罪世界，试图理解罪犯的心理，并在旅途中接受杜卡的训练，学习格斗技巧以及如何驾驭内心的恐惧。当他发现神秘的影忍者盟与自己的信念背道而驰时，毅然返回高谭。借助家族财富、先进装备和韦恩庄园地下的秘密空间，布鲁斯化身蝙蝠侠，开始向笼罩这座城市的犯罪与黑暗宣战……','Evil fears the knight.',150000000,374218673,115.040024,7.5,7359,140,'2005-06-10','en','/sPX89Td70IDDjVr85jdSBb4rWGr.jpg',4.408724469736628,3,'2026-09-10',2,NULL,NULL),(274,'沉默的羔羊','The Silence of the Lambs','在这部改编自托马斯·哈里斯畅销小说的惊世之作中，技艺超凡的导演乔纳森·戴米以令人毛骨悚然的笔触，勾勒出缠绕美国社会的梦魇——连环谋杀。朱迪·福斯特颠覆性地诠释了联邦调查局见习探员克拉丽丝·史达琳的形象，为洞悉另一名连环杀手的心智，她不得不求助于恶名昭彰的\"食人魔\"汉尼拔·莱克特，此番表演亦成为其演艺生涯中最令人难忘的篇章。与她交锋的安东尼·霍普金斯，则塑造出堪称典范的暗黑英雄形象——优雅博学、机锋凌厉却暗藏杀戮本能，令人战栗地呈现了人性彻底堕落的剖面。这部兼具扣人心弦的刑侦叙事与扭曲心理深度探索的杰作，当年横扫奥斯卡最佳影片、导演、改编剧本、男女主角五项大奖，至今仍是影史文化里程碑。[标准收藏]','',19000000,272742922,6.6417,8.345,4443,119,'1991-02-14','en','/a6UMvHPk4YdmhXrueiFaVOwcVjn.jpg',4.2482237928576385,3,'2026-09-10',2,NULL,NULL),(277,'黑夜传说','Underworld','地球上一直存在着一个黑暗的地下世界。那里，两大种族――吸血鬼和狼人――在斗得你死我活，每一方都以消灭对方种族为最终目标。一次，吸血鬼族的“月神”西丽妮在追杀几个落败的狼人时发现，狼人正在密谋绑架人类的一名医生麦克尔。心知狼人必有所图，西丽妮独自前往狼窝查探。不料中了狼人的埋伏，身负重伤之际幸得麦克尔相救。在麦克尔送西丽妮回吸血鬼营地的途中，他意外被一只狼人咬伤了，由此揭开了麦克尔的身世之谜和狼人的阴谋……','Underworld',22000000,95708457,81.829237,6.6,2512,121,'2003-09-19','en','/zsnQ41UZ3jo1wEeemF0eA9cAIU0.jpg',3.8341414333953123,3,'2026-09-10',2,NULL,NULL),(278,'肖申克的救赎','The Shawshank Redemption','1947年，银行家安迪·杜佛兰因被控杀害妻子及其情人，尽管始终坚称清白，仍被判处两项无期徒刑，送入缅因州的肖申克监狱服刑。在残酷而压抑的监狱生活中，安迪凭借冷静、智慧和始终未曾熄灭的希望逐渐赢得狱友们的尊重，并与能够在狱中弄到各种物品的瑞德建立起深厚的友谊。漫长的岁月里，他始终没有让高墙彻底改变自己，也开始用自己的方式影响身边的人，以及这座看似牢不可破的监狱……','',25000000,28341469,77.754,8.7,8205,142,'1994-09-23','en','/iKZev9OgfklidO8AvdrYlwung2o.jpg',4.681378542111055,3,'2026-09-10',2,NULL,NULL),(279,'Amadeus','Amadeus','The incredible story of genius musician Wolfgang Amadeus Mozart, told in flashback by his peer and secret rival Antonio Salieri – now confined to an insane asylum.','...Everything you\'ve heard is true',18000000,51973029,31.82675,7.8,1076,160,'1984-10-26','en','/gQRfiyfGvr1az0quaYyMram3Aqt.jpg',3.7244514569053946,3,'2026-09-10',2,NULL,NULL),(280,'终结者2：审判日','Terminator 2: Judgment Day','上一部中，超级电脑“天网”阻止人类抵抗领袖约翰·康纳诞生的行动失败，时隔13年后，在“审判日”到来之前，“天网”派出了更加先进的生化机器人T-1000（罗伯特·帕特里克 饰）从公元2029年回到洛杉矶追杀已经长大的约翰，与此同时，约翰也派出了机器人T-800（阿诺· 施瓦辛格 饰）回去保护年幼的自己。\r 此时，萨拉·康纳（琳达·汉密尔顿 饰）因为怪异的言行而住进了精神疗养院，约翰则和养父母住在一起，行为叛逆。T-800找到他们，在逃避T-1000追杀过程中，获得了二人的信任。\r 为了改变未来的历史，挽救人类的命运，萨拉、约翰和T-800 Model 101找到了“天网”之父，迈尔斯·戴森（乔·莫顿 饰），说服他销毁一切有关“天网”的资料，此时，警察和T-1000同时赶来，他们陷入了多方争斗中。','It\'s nothing personal.',100000000,520000000,101.74155,7.7,4185,137,'1991-07-01','en','/jFTVD4XoWQTcg7wdyJKa8PEds5q.jpg',4.282696683535697,3,'2026-09-10',2,NULL,NULL),(284,'桃色公寓','The Apartment','C. C. Baxter是纽约一个大公司的小职员，他的单身公寓经常被公司的高层们用去当作幽会的场所，Baxter也因此获得不少升迁的机会。Baxter暗恋着公司的电梯女郎Fran Kubelik，这天他终于鼓起勇气约了她晚上一起去看一出戏剧。然而Baxter等了一晚却未见Fran的踪影，原来Fran是公司的高管有妇之夫Jeffery Sheldrake的地下情人，那晚他们还在Baxter的公寓幽会。Jeffery信誓旦旦向Fran表示，他将和他的妻子离婚然后和她名正言顺地在一起。Fran相信了，然而几个星期后她又从Jeffery的上一任情人知晓了Jeffery所说的不过是个谎言。另一方面，在一个夜里，当Baxter回到他家的时候，意外地发现Fran竟倒在他的床上，并且服了很多安眠药企图自杀......  本片获1960年奥斯卡十项提名，赢得包括最佳导演、最佳影片在内的五项大奖。','Movie-wise, there has never been anything like it - laugh-wise, love-wise, or otherwise-wise!',3000000,25000000,22.889294,8.1,483,125,'1960-06-15','en','/neFYFnQEzwInLgicb15TFnAZfj3.jpg',3.4662020139085774,3,'2026-09-10',2,NULL,NULL),(285,'加勒比海盗3：世界的尽头','Pirates of the Caribbean: At World\'s End','被大章鱼吞下去的杰克船长进入了戴维·琼斯控制的“死界”——世界的尽头。为了拯救杰克，威尔·特纳、伊丽莎白和女巫等一行人也来到了“死界”。','At the end of the world, the adventure begins.',300000000,961000000,139.082615,6.9,4500,169,'2007-05-19','en','/jGWpG4YhpQwVmjyHEGkxEkeRf0S.jpg',4.181436483579669,3,'2026-09-10',2,NULL,NULL),(288,'正午','High Noon','这部1952年的经典西部片中，刚刚完婚的警官威尔·凯恩本欲卸任小镇警长之职，与新娘开始新生活，却得知宿敌——枪手弗兰克·米勒将于正午时分抵达小镇，前来清算旧账。','The story of a man who was too proud to run.',730000,8000000,18.644023,7.6,334,85,'1952-03-27','en','/cNIPhiWzAcA9FU11zbjPZKwcvs3.jpg',3.279170417889595,3,'2026-09-10',2,NULL,NULL),(289,'卡萨布兰卡','Casablanca','二战期间，卡萨布兰卡是欧洲逃往美国的必经之地，那里鱼龙混杂，局势紧张。里克（亨佛莱•鲍嘉 Humphrey Bogart 饰）是一个神秘的商人，他在卡萨布兰卡开了一家人气很旺的夜总会，并拥有两张宝贵的通行证。一天，反纳粹人士维克多和妻子伊尔莎（英格丽•褒曼 Ingrid Bergman 饰）来到夜总会，原来他们正在逃避纳粹的追捕。碰巧的是，里克发现，伊尔莎竟然是他的旧日情人。那段爱曾经刻骨铭心，却因为一个误会而终止。而当误会消解时，伊尔莎和里克的感情还是不可避免的重燃了。里克手上的两张通行证能帮助维克多度过难关，但这样一来，伊尔莎是决定留下，还是离去，他们的爱情在政治和伦理的推波逐流中走向何方。','They had a date with fate in Casablanca!',878000,10462500,43.729123,7.9,1422,102,'1942-11-26','en','/lGCEKlJo2CnWydQj7aamY7s1S7Q.jpg',3.8648516153753394,3,'2026-09-10',2,NULL,NULL),(291,'巨浪骑士','Riding Giants','本片是今年圣丹斯影展的开幕电影，这也是圣丹斯首次打破传统思维以一部记录片做为开幕片，影片由美国传奇人物、前“冲浪大王”斯泰西·佩拉塔执导，风格轻快灵动，娱乐性很强。',NULL,2600000,3166000,0.895946,7.6,23,105,'2004-07-09','en','/8L3ir0KNqSqpps2oVAeCUPVTPhr.jpg',2.539592481954641,3,'2026-09-10',2,NULL,NULL),(292,'Dave Chappelle\'s Block Party','Dave Chappelle\'s Block Party','The American comedian/actor delivers a story about the alternative Hip Hop scene. A small town Ohio man’s moves to Brooklyn, New York, to throw an unprecedented block party. Filmed with inspiration from the 1973 documentary Wattstax.',NULL,3000000,11718595,1.697846,6.4,28,100,'2005-09-12','en','/lGS9iKGGRjM049ZGK4J8TvQeBHg.jpg',2.572051026807152,3,'2026-09-10',2,NULL,NULL),(296,'Terminator 3: Rise of the Machines','Terminator 3: Rise of the Machines','It\'s been 10 years since John Connor saved Earth from Judgment Day, and he\'s now living under the radar, steering clear of using anything Skynet can trace. That is, until he encounters T-X, a robotic assassin ordered to finish what T-1000 started. Good thing Connor\'s former nemesis, the Terminator, is back to aid the now-adult Connor … just like he promised.','The Machines Will Rise.',200000000,435000000,69.405188,5.9,2143,109,'2003-07-02','en','/xu2ftqM7Y0wbw8XZrEMUboZjmNE.jpg',3.610327944640191,3,'2026-09-10',2,NULL,NULL),(297,'第六感生死缘','Meet Joe Black','也许在爱情的天平上，神与人是平等的。死神为了体验人世的悲欢，化身翩翩少年Joe Black(Brad Pitt 饰) 降落到新闻媒体大亨William Parrish（Anthony Hopkins 饰）的家中。机缘巧合，Joe爱上了William的小女儿Susan （Claire Forlani 饰），品尝到人世间爱情的甘醇。这孩子般纯真的，迷恋花生酱的翩翩死神与他美丽端庄的，拥有夜色深邃眼睛的女孩会有着什么样不同寻常的奇遇？他们把爱情谱成乐章，邀你我一同聆听。','Sooner or later everyone does.',90000000,142940100,36.069611,6.9,1147,178,'1998-11-12','en','/89bhR8v9mHAdDFO0XVq4YMwVH1V.jpg',3.5906124469518033,3,'2026-09-10',2,NULL,NULL),(298,'十三罗汉','Ocean\'s Thirteen','老心不老的鲁本•蒂什科夫（Elliott Gould 饰）拿出全部家当与威利•班克（阿尔•帕西诺 Al Pacino 饰）合伙经营赌场饭店。但他忘了，在拉斯韦加斯这个光怪陆离、骗盗横行的地方，防范之心是最不可或缺的。班克混迹赌城多年，奸诈手段让他在此如鱼得水。他骗尽鲁本的钱财，将赌场据为己有。老鲁本不堪如此沉重的打击，从此一病不起。鲁本的遭遇激怒了他的好友丹尼•奥逊（乔治•克鲁尼 George Clooney 饰），在对威利劝说无效的情况下，他重新集结了包括罗斯蒂•雷恩（布莱德•彼特 Brad Pitt 饰）、莱纳斯•凯德维尔（马特•戴蒙 Matt Damon 饰）在内的十三位罗汉，准备对班克赌场进行入侵。7月3日午夜，班克赌场开业，这注定是一个不平凡的夜晚……','What are the odds of getting even? 13 to one.',85000000,311312624,42.069993,6.5,1999,122,'2007-06-07','en','/mZx2BZwUt1c7ZKZbukVWDmeRL7p.jpg',3.6655722397049084,3,'2026-09-10',2,NULL,NULL),(302,'泳池情杀案','Swimming Pool','早已功成名就的女性神秘小说家莎拉•莫顿（Charlotte Rampling 夏洛特•汉普林 饰）却为新作烦恼不已，在出版商约翰•布兰德（Charles Dance 查理士•当斯 饰）的建议下，她来到约翰的家乡别墅，一面休养，一面寻找灵感。乡间的悠哉生活使莎拉从久居伦敦的疲惫中解脱出来，尽情享受着难得的休闲时光。 某晚，自称约翰女儿的茱莉（Ludivine Sagnier 卢蒂文•萨尼埃 饰）不宣而至，茱莉开朗、张扬、放荡，与古板莎拉格格不入。莎拉的创作计划被打乱，而一丝不祥的气息也悄然弥漫开来……','On the surface, all is calm',7800000,22441323,11.000654,6.4,153,102,'2003-05-18','en','/6swLgJfWkv7PIYOBfVDO808ZfPm.jpg',2.9676361864116214,3,'2026-09-10',2,NULL,NULL),(306,'Beverly Hills Cop III','Beverly Hills Cop III','Back in sunny southern California and on the trail of two murderers, Axel Foley again teams up with LA cop Billy Rosewood. Soon, they discover that an amusement park is being used as a front for a massive counterfeiting ring – and it\'s run by the same gang that shot Billy\'s boss.',NULL,50000000,119208989,20.333953,5.5,434,104,'1994-05-24','en','/nQUJajfsxQd8ayCnYFnODOGe3N7.jpg',3.1308575638376013,3,'2026-09-10',2,NULL,NULL),(309,'家宴','Festen','如同惊雷般震撼世界影坛的丹麦道格玛95运动，始于托马斯·温特伯格这部享誉国际的突破之作。这部采用数字视频的经济与美学自由、达到毁灭性情感强度的室内剧，以其辛辣的笔触剖析人性。在一位富商六十岁寿宴上，众多亲友齐聚乡间庄园庆祝，却因一系列爆炸性真相的揭露而陷入疯狂——这些真相撕裂了中产体面的表象，暴露出暗涌的创伤。标志性的手持摄影、颗粒质感的自然光线、嘈杂的同期声以及后来成为道格玛标签的原始表演风格，加剧了这部对父权罪恶的辛辣控诉所带来的震撼性感官冲击。影片在极致的黑色幽默与阴郁悲剧之间游走，将一个家庭的病态灵魂层层剥露。',NULL,1300000,0,10.240917,7.7,207,105,'1998-05-20','da','/ibWzFsS6Z7cTEKJIE738URYS4Mo.jpg',3.121587811720547,3,'2026-09-10',2,NULL,NULL),(310,'冒牌天神','Bruce Almighty','金·凯瑞饰演一名运气奇差的电视记者布鲁斯．诺兰（Bruce Nolan）。在试图帮助流浪汉时被流氓围殴等一连串事故之后，他开始抱怨上帝（摩根·弗里曼饰演）没有做好分内的工作，没想到上帝此时出现在他面前，并把管理他所在的城市的工作交给他……','In Bruce we trust',80000000,484572835,109.684788,6.4,3012,101,'2003-05-23','en','/wqkWrOFtYnZSvIMu8Lsmz7WIvKC.jpg',3.8932507502720335,3,'2026-09-10',2,NULL,NULL),(311,'美国往事','Once Upon a Time in America','　　二十年代的美国，纽约少年“面条”和几个同龄朋友一起认识了聪明狡黠的“麦克斯”，他们开始从事走私活动。不久，面条在一场械斗中杀伤人命，被关进监牢。若干年后，“面条”出狱，当时的小伙伴们已经变成了健壮的青年人，在“麦克斯”的带领下，他们开始了一系列抢劫、盗窃、敲诈活动。随着犯罪活动的不断深入， “麦克斯”似乎被胜利冲昏了头脑，竟然把美国联邦储备银行也列入了行动目标。“面条”不忍眼看好友走向毁灭，偷偷打电话报警，想逼迫“麦克斯”收手。警察与 “面条”的朋友展开激烈枪战，“麦克斯”等人全部被杀。“面条”带着深深的悔恨和痛苦，离开纽约，回到年少时生长的地方。三十五年过去了，几近垂暮的“面条”重新回到纽约的伤心地，他遇见了少时的朋友和旧情人，而当年“麦克斯”他们的死，背后竟然包含着出乎意料的阴谋。','',30000000,0,23.4224,8.373,1069,229,'1984-05-23','en','/mYvSMWFsZnKYLWomUIbbVSoKsL.jpg',3.8052779031032014,3,'2026-09-10',2,NULL,NULL),(314,'猫女','Catwoman','帕蒂恩斯（哈莉•贝瑞 Halle Berry 饰）原本过着平凡满足的日子，她在一家化妆品公司担任美术设计师，是众人眼中潇洒的未婚白领。然而，在这座充满罪恶的城市，厄运正慢慢向帕蒂恩斯袭来。一次偶然，帕蒂恩斯发现了公司的老板乔治（兰伯特•威尔逊 Lambert Wilson 饰）和他的妻子劳雷尔（莎朗•斯通 Sharon Stone 饰）从事的罪恶勾当，随后劳雷尔派出杀手将帕蒂恩斯杀人灭口了。\r 　　这时，奇迹发生了，帕蒂恩斯曾经救过的一直埃及猫出现了在她眼前，原来这只猫竟然是猫神！猫神为了报答帕蒂恩斯，用魔法将她复活了。帕蒂恩斯复活后发现自己的身体有了巨大的变化，她获得了一股神秘的力量，不仅动作敏捷、触觉灵敏，她还变得身怀绝技。于是，帕蒂恩斯化身为猫女，向这个城市的罪恶宣战。','CATch her in IMAX',100000000,82102379,32.271938,4.2,808,104,'2004-07-22','en','/pvnPgukFyEKgCzyOxyLiwyZ8T1C.jpg',3.059723208873712,3,'2026-09-10',2,NULL,NULL),(319,'真实罗曼史','True Romance','漫画店打工仔Clarence Worley（克里斯汀·史莱特 Christian Slater 饰）生日的时候，在电影院邂逅了美女Alabama Whitman (帕特丽夏·阿奎特 Patricia Arquette 饰)，两人一夜春宵。第二天，Alabama告诉Cla rence她是个妓女，是Clarence的老板送给他的生日礼物，但她爱上了他。Clarence决定将Alabama从皮条客Drexl Spivey（加里·奥德曼 Gary Oldman 饰）手中拯救出来。夜总会的一阵混战后，Clarence开枪将Drexl杀死，并拿走了一个他以为属于Alabama的手提箱。后来两人发现，手提箱里竟有大量可卡因。两人欣喜若狂，开始流浪，寻找将可卡因换成现金的机会。两人一路来到了洛杉矶，找到了Clarence的老友Dick Ritchie（迈克尔·拉帕波特 Michael Rapaport 饰）。Dick是个在好莱坞混迹的演员，他把一位能转手可卡因的导演Lee介绍给二人。而另一边，被Drexl偷走了大量可卡因的黑帮老大Vincenzo Coccotti（克里斯托弗·沃肯 Christopher Walken 饰）也带着一帮人开始寻找两人的踪迹。一场场大战即将上演，到底这对恋人的罗曼史能否延续下去？','Stealing, Cheating, Killing. Who said romance was dead?',12500000,12281551,35.268557,7.5,749,120,'1993-09-09','en','/er7DxC9bZXPlpnHcFudFSWrIG2O.jpg',3.5628795575231402,3,'2026-09-10',2,NULL,NULL),(320,'失眠症','Insomnia','Will Dormer（阿尔·帕西诺 Al Pacino 饰）与搭档Hap Eckhart（马丁·唐文 Martin Donovan 饰）来到远离洛杉矶一处日不落的小镇阿拉斯加，调查一名17岁少女被活活殴打致死的案件。阿拉斯加一名女警察llie Burr（希拉里·斯万克 Hilary Swank 饰）对Dormer的办案手法由衷感到敬畏，努力在查案过程中学习。而此刻的多莫其实已经麻烦缠身，他在洛杉矶抓获了一个案件嫌疑人，因为要将其定罪，不得不捏造了假证据，此事已被内务部调查。Hap想向内务部坦诚真相并认为对Dormer也是好事，不过Dormer不这样想。  在引诱真凶的围捕中，Dormer在大雾中失误打死Hap，Hap临死前认为Dormer是故意打死自己的。在陈述事件时Dormer本能性地说那枪是凶手开的。然而在良心的压力和日不落的环境下，他患上了严重的失眠症。这时有人开始给他打电话，声称看见了雾中的一切。Dormer最后将凶手锁定在侦探小说作家Walter Finch（罗宾·威廉斯 Robin Williams 饰）身上，对方也没打算和他捉迷藏的游戏。  一场心理和良心的对决开始了。','A tough cop. A brilliant killer. An unspeakable crime.',46000000,113714830,41.322708,6.8,1148,118,'2002-05-24','en','/grgvwGEAUNurWDsIyTLeGSQkc5r.jpg',3.5844955214858896,3,'2026-09-10',2,NULL,NULL),(321,'Mambo Italiano','Mambo Italiano','A sweet comic film about an Italian man who comes out of the closet and the affect it has on his life and his crazy family. A family movie about the stereotypes of homosexuals and Italians – called by critics \"the gay\" My Big Fat Greek Wedding.','Things change. Family doesn\'t.',4361898,3031801,2.080741,5.6,28,92,'2003-06-06','en','/siYFoZUq0HOCksnOc7me8YT1AOo.jpg',2.5640418028504817,3,'2026-09-10',2,NULL,NULL),(322,'神秘河','Mystic River','随着一桩年轻女性死亡案件的调查逐渐聚焦于三位旧日好友，一个围绕着友谊、家庭以及过早逝去的纯真而展开的不详故事逐渐浮现。','We bury our sins, we wash them clean.',25000000,156822020,31.242999,7.6,1422,138,'2003-10-07','en','/hCHVDbo6XJGj3r2i4hVjKhE0GKF.jpg',3.7768171828828865,3,'2026-09-10',2,NULL,NULL),(326,'航班蛇患','Snakes on a Plane','黑帮老大艾迪·金策划了一起凶杀案，被偶然路过的年轻人西恩·琼斯目击。为了在法庭上成功指控这个作恶多端的黑社会头子，警方派出资深联邦密探尼维利·费恩负责保护西恩，并将其从夏威夷护送至洛杉矶法庭。为避免证人遇害，尼维利采取声东击西的策略，与西恩偷偷乘上一架普通的红眼航班。然而这项绝密的计划被艾迪安排在警方的内奸获知，为了逃脱法律制裁，艾迪派出携带大量毒蛇的杀手登上飞机，一场离奇恐怖的血腥灭口案件就此展开……','At 30,000 feet, snakes aren\'t the deadliest thing on this plane.',33000000,62022014,19.642328,5.1,497,105,'2006-08-06','en','/qEDTomoUkaPQeHAzZ7jLVU4ng8B.jpg',3.104058431255584,3,'2026-09-10',2,NULL,NULL),(327,'Brother','Brother','A Japanese Yakuza gangster’s deadly existence in his homeland gets him exiled to Los Angeles, California, where he is taken in by his little brother and his brother’s gang. This is the first English film by Takeshi Kitano.','Are You Japanese?',12000000,15250000,5.327714,6.8,107,114,'2000-09-09','ja','/lJFjaEsLEQV4fahwIOyiW1zQbTC.jpg',2.889075687730307,3,'2026-09-10',2,NULL,NULL),(329,'侏罗纪公园','Jurassic Park','亿万富豪约翰·哈蒙德利用先进的遗传技术，从封存在琥珀中的远古蚊子血液里提取恐龙DNA，在努布拉岛成功复活了早已灭绝的恐龙，并建造了一座前所未有的主题公园“侏罗纪公园”。在正式开放之前，他邀请古生物学家艾伦·格兰特、艾丽·塞特勒和数学家伊恩·马尔科姆等人登岛，对公园的安全性进行评估。然而就在众人亲眼见证这些史前巨兽带来的震撼时，一场人为造成的系统故障让岛上的安全设施逐渐失效。失去电网与控制系统保护后，原本被关在围栏中的恐龙开始威胁岛上所有人的生命……','An adventure 65 million years in the making.',63000000,920100000,40.413191,7.6,4856,127,'1993-06-11','en','/63viWuPfYQjRYLSZSZNq7dglJP5.jpg',4.157291324381419,3,'2026-09-10',2,NULL,NULL),(330,'侏罗纪公园2：失落的世界','The Lost World: Jurassic Park','侏罗纪公园灾难发生四年后，伊恩·马尔科姆一直试图远离那段噩梦，却从约翰·哈蒙德口中得知，除了努布拉岛之外，国际遗传技术公司还曾在另一座名为索纳岛的基地培育恐龙。如今那里已经没有人类管理，大量恐龙却在野外自行繁衍，形成了完整的生态系统。哈蒙德希望派遣一支小队前往岛上记录这些动物的生存状况，而得知女友莎拉·哈丁已经先行登岛后，马尔科姆不得不再次踏入恐龙的世界。然而他们很快发现，另一支由公司派出的队伍也来到了岛上，并准备捕捉活着的恐龙带回大陆。两支目的截然不同的队伍由此被卷入越来越危险的局面……','Something has survived.',73000000,229074524,2.502487,6.2,2487,129,'1997-05-23','en','/4WBZdRygvBsXfLaJZDSlXD1RiFm.jpg',3.5577019670564316,3,'2026-09-10',2,NULL,NULL),(331,'侏罗纪公园3','Jurassic Park III','经历努布拉岛的灾难多年后，古生物学家艾伦·格兰特始终不愿再次接近任何生活着恐龙的岛屿。然而研究经费的困境让他接受了富商保罗·科比和阿曼达夫妇的高价邀请，陪同他们乘飞机从空中参观已经成为恐龙禁区的索纳岛。格兰特原以为这只是一趟不会降落的短暂旅程，却很快发现科比夫妇隐瞒了真正的目的：他们来到这里，是为了寻找在岛附近失踪的儿子。意外发生后，一行人被困在索纳岛深处，而格兰特也发现，这座岛上的危险远比自己曾经面对的更加陌生……','This time, it\'s not just a walk in the park!',93000000,368780809,1.859364,5.7,2077,92,'2001-07-18','en','/sYt50yDY6zNOHoSqUkLVP8fyYKL.jpg',3.405210037980967,3,'2026-09-10',2,NULL,NULL),(332,'神探加吉特','Inspector Gadget','约翰•布朗（马修•布罗德里克 Matthew Broderick 饰）是某机器人实验室的保安，他的梦想就是有朝一日成为一名真正的警察。某日，实验室的一项计划被人盗窃，德高望重的博士也遭杀害。约翰追踪凶手，结果却遭遇了严重的车祸，命悬一线。此前老博士正和女儿布兰达（Joely Fisher 饰）进行一项名为“加杰特程序”的研究，借此机会，布兰达将约翰改造成一个功能强大的半机器人。死而复生并更名为加杰特的约翰表面上与一般人类别无二致，而身体内却装有超过一万个精密机关，他因此实现梦想，成为协助警方抓捕罪犯的得力助手。\r 　　与此同时，罪恶的科学家克劳博士（鲁伯特•艾弗莱特 Rupert Everett 饰）利用布兰达父女的研究制造出机器人用于犯罪，并将罪行栽赃加杰特。为了维护正义、洗刷罪名，加杰特与克劳展开了一场警匪大战……','The greatest hero ever assembled.',75000000,0,17.561955,4.3,318,78,'1999-07-23','en','/dDcsv1Lql5aM6H4JYfDHjBAXKgT.jpg',2.9605425171849564,3,'2026-09-10',2,NULL,NULL),(334,'木兰花','Magnolia','吉米·盖特主持王牌电视节目《儿童世界》已达33年之久，节目嘉宾斯坦利-斯派克还有三天就能打破一项由神童唐尼-史密斯30年前创下的一项纪录。斯派克深知他不过是娱乐大众的一件道具，而曾经红极一时的唐尼的处境更令人堪忧，他现在一家电器店工作。\r 　　吉米此时也有自己的烦恼，他被诊断患有癌症，活不到两个月。吉米刚过20岁的女儿克劳迪对邻居男子的迷恋搅得家庭生活不再和谐，母亲罗丝对女儿及丈夫不无忧虑。孤独的警官科林因一起噪音扰民纠纷来到吉米家，当第一眼瞧见克劳迪起，科林便陷入了一场痛苦至极的单恋中。克劳迪对父亲有一种发自内心的憎恨，女儿成了吉米最大的一块心病。这一天，吉米准备将自己不久于人世的消息告诉爱女……\r 　　同样位于南加州某山庄的另一家庭里，男主人帕特里奇爵士正躺在病床上，他也深知自己时日无多。老人的病床前站着其年轻的妻子琳达及护理医生菲尔-柏马，这两人的心情各不相同。琳达的心里不无悔意，当初她是为了老爵士的钱财嫁给他的，在老人病入膏肓之际，她发觉自己已爱上他。柏马则肩负着把离家出走多年的爱子弗兰克-迈基带到老人病榻前的重任。一场父子纠纷使得迈基再也没踏进过这个家门。求得儿子的谅解成了老人最后一个心愿。\r 　　迈基已成为著名的电视主持人，他的装扮给人一种颓废的感觉，对继母的成见使他开始憎恨世上所有女人...','Things fall down. People look up. And when it rains, it pours.',37000000,48451803,30.993736,7.5,825,188,'1999-12-08','en','/tpfC325Jk6S38VTe5dDWjWtoyxr.jpg',3.5841141759087236,3,'2026-09-10',2,NULL,NULL),(335,'西部往事','C\'era una volta il West','塞尔吉奥·莱昂内的这部不朽史诗，其恢弘堪比取景地纪念碑谷，其气度媲美星光熠熠的杰出演员阵容，其粗粝不羁正如每个孩子想象中的狂野西部。影片围绕一名神秘的口琴客、一位寻找杀父仇人的寡妇、一个亡命之徒以及一名铁路大亨之间错综复杂的关系展开，以恩尼奥·莫里康内传奇般的配乐为灵魂，塑造了影史中最令人难忘的西部片开场与结局。这是一首对正在消逝的旧西部的挽歌，也是一部永远重塑了该类型的杰作。','There were three men in her life. One to take her... one to love her... and one to kill her.',5000000,5321508,49.333137,8.1,1128,175,'1968-12-21','it','/qbYgqOczabWNn2XKwgMtVrntD6P.jpg',3.835088338973687,3,'2026-09-10',2,NULL,NULL),(338,'Good bye, Lenin!','Good bye, Lenin!','An affectionate and refreshing East/West-Germany comedy about a boy who’s mother was in a coma while the Berlin wall fell and when she wakes up he must try to keep her from learning what happen (since she was an avid communist supporter) to avoid shocking her which could lead to another heart attack.','The German Democratic Republic lives on -- in 79 square meters!',4800000,79384880,11.086001,7.4,586,121,'2003-02-09','de','/nxKe04OP2GOpVsGneqFiBg7h0bS.jpg',3.4156077715087974,3,'2026-09-10',2,NULL,NULL),(342,'夏日风暴','Sommersturm','同在一支青少年赛艇队的Tobi（Robert Stadlober）和Achim（Kostja Ullmann）是死党，训练之外，两人经常一起打闹玩乐，虽然都有女朋友，但Tobi对Achim有超过好兄弟的感情。\r 　　一年一次的夏季青少年赛艇比赛来临，Tobi和Achim随队伍来到一个美丽的湖边露营。当得知驻营地离他们最近的队伍，来自柏林的“横冲直撞”队是一支同性恋赛艇队时，赛艇队成员都觉得非常尴尬，唯独联想到自己同Achim关系的Tobi在羡慕之余，怀起心事。某次游泳结束后，无法自控的Tobi亲吻了Achim，Achim恐慌地逃走，Tobi一人伤心落寞时，“横冲直撞”队的一名队员来到他身边。男孩之间的故事变得复杂起来。',NULL,2700000,0,3.120747,6.7,59,98,'2004-09-02','de','/7t4WDIhpVTzz72G2gDbwdp8OafR.jpg',2.7431899136673388,3,'2026-09-10',2,NULL,NULL),(345,'大开眼戒','Eyes Wide Shut','医生威廉姆携太太参加他的一位主顾――当地一个名流——家里举行的晚会时，巧遇了他的一位大学同学——在晚会上担任钢琴师的尼克。当晚，威廉姆因公外出。料理完公事后，他在一家酒吧再次遇到了尼克，尼克告诉了他有这样一个秘密舞会：在舞会上，所有的人都穿着晚礼服，戴着面具，到处都是裸体的美女。威廉姆禁不住好奇，再三乞求尼克，尼克告诉了他举行那个舞会的地址和入门的暗语。威廉姆匆匆准备后，展开了一次如幻如梦的冒险之旅。过程充满了诡异和神秘，背后的玄机更是令人无法参透。','Cruise. Kidman. Kubrick.',65000000,162091208,27.870312,7.1,1234,159,'1999-07-14','en','/8Wch1De3UpH4XgBRK6cyhs8Zfe.jpg',3.6295423665155724,3,'2026-09-10',2,NULL,NULL),(346,'七武士','七人の侍','这部影史最具震撼力的史诗巨制，讲述十六世纪某村庄的绝望村民雇佣七位武士抵御山贼侵袭的故事。黑泽明历时三个多小时的银幕征程，通过传奇演员三船敏郎与志村乔的演绎，将哲学沉思与娱乐观赏、细腻人情与激烈战斗完美交融，铸就这部关于勇气与希望的丰碑之作——其故事之丰饶、意境之深远，令人过目难忘。[标准收藏]','',2000000,271841,13.5555,8.5,878,207,'1954-04-26','ja','/trW7LvPSPzLzXjmuc05KNWYw0yf.jpg',3.7281914316995293,3,'2026-09-10',2,NULL,NULL),(348,'异形','Alien','未来的世界，人类已能轻松穿梭于星际之间，在太空中展开商业活动。“诺斯特罗莫”是在太空活动的众多星际商业运输船之一。一次，它完成任务满载太空矿石返航地球时，突然收到了一组奇怪的信号，由于这可能是求救信号，飞船接到指令前往信号源地进行搜救。经过一段飞行后，飞船终于抵达信号源发出的地方。船员们发现此处果然有一艘坠毁的飞船，只是，经过一番搜索，他们发现该船的船员们都早已死亡，化为化石。此时，留在“诺斯特罗莫”号的第三指挥官蕾普莉已经破译出该信号并不是求救信号，而是警告信号！队员的生死搏斗开始了！','In space no one can hear you scream.',11000000,104931801,94.184658,7.9,4470,117,'1979-05-25','en','/vfrQk5IPloGg1v9Rzbh2Eg3VGyM.jpg',4.33520110140774,3,'2026-09-10',2,NULL,NULL),(350,'穿普拉达的女王','The Devil Wears Prada','The Devil Wears Prada is about a young journalist who moves to New York to work in the fashion industry. Her boss however is extremely demanding and cruel and won’t let her succeed if she doesn’t fit into the high class elegant look of their magazine when all she really wants to be a good journalist.','Meet Andy Sachs. A million girls would kill to have her job. She\'s not one of them.',35000000,326551094,83.893257,7,3088,109,'2006-06-30','en','/8912AsVuS7Sj915apArUFbv6F9L.jpg',3.985725521147292,3,'2026-09-10',2,NULL,NULL),(364,'蝙蝠侠归来','Batman Returns','蝙蝠侠（迈克尔•基顿 Michael Keaton 饰）归来了！自从打败“小丑”后，高谭市获得片刻的宁静。然而，又一个强大的对手出现了！这次是脾气乖张暴戾的“企鹅”。  　　“企鹅”因为是次子，所以自幼就被父母遗弃，落下残疾，导致“企鹅”对整个社会都心生不忿。长大后“企鹅”的企鹅决心杀回高谭市，将市内的长子都杀光，并控制整个高谭市。在迫使邪恶商人马克斯（克里斯托弗•沃肯 Christopher Walken 饰）帮忙后，“企鹅”顺利当上了高谭市长。同时，马克斯的秘书西莉娅（米歇尔•菲佛 Michelle Pfeiffer 饰）意外获知了他们的秘密，在遭受他们迫害时意外获得了超强能力，成为了亦正亦邪的猫女。  　　蝙蝠侠这次将面临“企鹅”和猫女的双重挑战！','The Bat, the Cat, the Penguin.',80000000,280000000,59.113174,6.6,1673,126,'1992-06-19','en','/gjgPx3iT7hBaAAWN2vypmYZkOp3.jpg',3.6825513855954974,3,'2026-09-10',2,NULL,NULL),(377,'猛鬼街','A Nightmare on Elm Street','南茜·汤普森是住在榆树街上的一个年轻女孩。一日，她的梦中出现了一个脸上有刀疤、手指如剃刀的怪人，从此，她夜夜受到这个恶梦的折磨。怪异的是，榆树街上所有的小孩，竟然都梦到相同的恶梦！不久后，南茜的朋友们一一死去，而且死相奇惨。她这才了解，她必须保持清醒，才有生存下去的机会。经过南茜的调查后，她发现这名梦中杀手就是榆树街上赫赫有名的中产阶级男子弗莱迪（劳勃英格朗饰），多年前，他因为骚扰孩童，而被愤怒的父母活活给烧死，事隔多年后，弗莱迪以鬼魂的身份回来了！他可以随意进入孩子们的梦中，并以极端残忍的方式杀害他们，以示报仇。如今，唯一能阻止这场恶梦的人，就只剩下南茜了。如果她失败了，那么没有人可以活得下去……','If Nancy Doesn\'t Wake Up Screaming, She Won\'t Wake Up At All!',1800000,25504513,38.204158,7.2,1180,91,'1984-11-14','en','/xtSprDnYlB0oOFxtl1amUQREIBC.jpg',3.6588764910654676,3,'2026-09-10',2,NULL,NULL),(380,'雨人','Rain Man','查理（汤姆•克鲁斯 Tom Cruise 饰）父亲去世，留下了300万美元的遗产。然而令他意外的是，遗产全部给了一个他不认识的哥哥雷蒙（达斯汀•霍夫曼 Dustin Hoffman 饰）。雷蒙的名字查理从没听过，这个事件让他气愤不已。他决定前去寻找哥哥。谁知雷蒙的住处就在一个精神病院里，原来他自幼患有自闭症，母亲去世后就被送到精神病院治疗。查理心中有了计算，他把雷蒙带出精神病院，企图骗他出让遗产。　　雷蒙的生活习惯奇异，活在自己的幻想世界里，有很多离奇古怪的行为。并且，查理在共处中发现了雷蒙惊人的记忆能力，他试着利用哥哥过目不忘的本领去赌场上试一下身手，赢得了一大笔奖金，使查理足以摆脱穷困生活。而令查理收获更大的是，他还获得了慢慢升温的亲情，这种手足情远远胜过了他原先图谋的300万的遗产。','A journey through understanding and fellowship.',25000000,412800000,49.510658,7.6,1709,133,'1988-12-11','en','/iTNHwO896WKkaoPtpMMS74d8VNi.jpg',3.876237217934815,3,'2026-09-10',2,NULL,NULL),(387,'从海底出击','Das Boot','1942年，德国潜艇舰队深陷所谓的“大西洋战役”，旨在袭扰并摧毁英国航运。然而，随着驱逐舰级护航力量的加强，德国U型潜艇开始遭受重创。本片讲述了一艘U型潜艇船员的故事，聚焦这些潜艇兵如何保持军人职业素养，执行近乎不可能的任务，同时始终试图理解并服从他们所效忠的政府意识形态。','When the hunters become the hunted',14000000,85000000,26.967494,7.9,613,149,'1981-09-16','de','/veTHiBK1MEPueflQKfwgOglaIQn.jpg',3.534503619792305,3,'2026-09-10',2,NULL,NULL),(388,'局内人','Inside Man','刚刚获得提升的经验丰富的纽约警察局的老警探凯斯·弗雷泽似乎并没有太多值得庆祝的，因为在他周围萦绕的腐败丑闻始终令其感到厌恶。然而，对警探事业的多年追求仍促使着他为这一行尽心尽力着。尤其是他那分独特且惊险刺激的人质交涉工作(谈判专家)更是令他心驰神往。此时，弗雷泽与老搭档比尔·米歇尔接到命令，迅速赶往一处案发现场，那里疯狂的抢匪刚刚劫持了人质与警察对峙着。而且，劫匪的头目就是这一带远近闻名的银行抢劫犯达尔顿·拉塞尔。狡猾的抢匪达尔顿在抢劫败露时顺手劫持了一名人质作为自己的临时挡箭牌。正当弗雷泽与搭档正试图与匪首拉塞尔沟通时，在现场的还有来自ESU(紧急营救部队)特战小组的人员在上尉约翰·达鲁斯的指挥下正准备一套严密的武装营救计划。然而，狡猾的拉塞尔似乎看破了警方的计划，迅速做出了反应，使得警方的营救计划无法实施……','It looked like the perfect bank robbery. But you can\'t judge a crime by its cover.',45000000,184376254,45.220386,7.3,1630,129,'2006-03-23','en','/ffMUgkDZICNiyaws1Jkv8qG8uFW.jpg',3.789497026845022,3,'2026-09-10',2,NULL,NULL),(389,'十二怒汉','12 Angry Men','西德尼·吕美特执导的本片堪称电影史上最颠覆的法庭剧。这部改编自雷金纳德·罗斯电视剧的经典之作，以密室内群像戏的精炼笔法，透视美国司法体系的肌理，张力十足。亨利·方达饰演的异议者，在由白人男性组成的陪审团中孤身抗辩——其余成员皆急于裁定被控弑父的波多黎各少年有罪。故事在一个闷热的午后、一间汗流浃背的房间里层层推进，最终凝聚成一部史诗规模的思辨传奇。吕美特这部震撼人心的导演处女作，精准捕捉了1950年代美国社会变革的前夜，成就了影史不朽的首作丰碑。[标准收藏]','',350000,1000000,29.0677,8.571,2078,96,'1957-04-10','en','/tbhKU2naM5ItPO4ICdF2GKow9ik.jpg',4.105195277929447,3,'2026-09-10',2,NULL,NULL),(391,'荒野大镖客','Per un pugno di dollari','镖客乔（克林特·伊斯特伍德 Clint Eastwood 饰）来到墨西哥边境小镇，伺机寻找挣钱机会的他得知镇上的两大帮派罗霍兄弟和镇长巴克斯特为了争夺小镇的控制权厮杀已久，便决定与两派斡旋，设计将镇上恶霸一网打尽。墨西哥士兵押送黄金经过小镇，罗霍劫持了黄金，并杀光了 士兵，一路跟踪的乔将其中两具尸体藏起来，并透露消息给两边：有两个士兵还活着。巴克斯特火速赶往现场想抓到存活士兵，来指证罗霍；罗霍则试图阻止他们，双方展开了一场激烈枪战。罗霍捕获巴克斯特的儿子安东尼奥。乔趁着两派在激战时，找到了黄金，并发现罗霍囚禁的女人玛利索，他将玛利索交给罗霍家，换回安东尼奥。后来他得知她是安东尼奥的妻子，又救出了她，帮助玛利索与安东尼奥逃出镇子。罗霍发现玛利索被乔放走，便放火烧死了巴克斯特一家，乔侥幸逃脱。  　　当乔孤身一人重现在镇口时，他与罗霍兄弟的生死决战开始了。','In his own way he is perhaps, the most dangerous man who ever lived!',200000,14500000,38.771062,7.6,883,99,'1964-09-12','it','/dU8VVSlgqmBR18k87rBpjIMb7tR.jpg',3.6400788261149253,3,'2026-09-10',2,NULL,NULL),(392,'浓情巧克力','Chocolat','平静的小镇在寒冬里迎来了火热的一天。年轻的薇安萝雪（朱丽叶特-比诺什 Juliette Binoche 饰)）带着女儿来到这里，在当地教堂的对面开了一间名为“天上人间 核桃糖”的巧克力店。巧克力香浓的气味在小镇上空飘荡，吸引众多小镇居民，而神奇的是，薇安萝雪每次做出来的巧克力，都能满足顾客的心理需求，发掘他们心中隐蔽的渴望。很多人原本封闭灰暗的生活有了新的色彩。但是，这却激怒了镇里的神父和贵族，他们视薇安萝雪为异类，镇里出现了对立的两派。而这时，吉普赛人洛克斯（强尼戴普 Johnny Depp 饰）远道而来，加入了薇安萝雪的阵营，他令薇安萝雪勇敢地打开了自己内心的欲望，二人共浸爱河，却想不到神父盘算着如何把这个“不祥”女子赶出小镇，于是，新旧观念的大碰撞开始了。','...and the world is still indulging!',25000000,152500343,28.727731,6.8,951,121,'2000-12-14','en','/y5B44S4FYFQFWrNb1JhHpEQCnyO.jpg',3.5054941433417826,3,'2026-09-10',2,NULL,NULL),(393,'杀死比尔2','Kill Bill: Vol. 2','The Bride unwaveringly continues on her roaring rampage of revenge against the band of assassins who had tried to kill her and her unborn child. She visits each of her former associates one-by-one, checking off the victims on her Death List Five until there\'s nothing left to do … but kill Bill.','The bride is back for the final cut.',30000000,152159461,50.622607,7.6,3948,136,'2004-04-16','en','/2yhg0mZQMhDyvUQ4rG1IZ4oIA8L.jpg',4.1243698846230705,3,'2026-09-10',2,NULL,NULL),(395,'异形大战铁血战士','AVP: Alien vs. Predator','在南极圈厚厚的冰层下面一直潜伏着我们未知的危险，它们静静潜伏，蓄势待发，直到人类的脚步将它们唤醒。  亿万富翁查尔斯·维兰德通过自己的热能成像探测卫星，发现在南极圈冰下几千英尺深处埋藏着一座远古的金字塔形神庙，根据推算，这座阿兹台克神庙的建筑年份应该在埃及人建筑金字塔之前。为了验证自己的发现，查尔斯组建了一队由莱克斯·伍德领导的精英探险队前往南极进行考察。  探险队无意间唤醒了沉睡中的异形，这让它们开始大量产卵繁殖，探险队处于危险之中，而更加糟糕的是，曾经被阿兹台克人奉为神明的铁血战士也在这时来到这里，三名嗜血的铁血战士在地球战场上又一次开始了对异形的狩猎游戏，和2000年前他们以此取乐不同，异形的数量更加庞大，战斗力更强。铁血战士拥有隐身和热感探测能力，同时他们的铁拳上随时可以像“金刚狼”一样弹出利刃，作为他的对手，异形不仅有强大的攻击力，它的血液和尸体都包含强烈腐蚀性的强酸，这正是铁血战士钢铁身体的克星。','Whoever wins... We lose',70000000,171183863,42.957216,5.5,1217,101,'2004-08-12','en','/twqPWgGumWuFWhBHwEwgwp2bAdt.jpg',3.3597602894399983,3,'2026-09-10',2,NULL,NULL),(398,'卡波特','Capote','聚焦杜鲁门·卡波特为创作纪实文学《冷血》进行案件调查的岁月。','In Cold Blood',7000000,49084830,17.434862,6.8,384,114,'2005-09-30','en','/r71wN2mk7zVZQAF13OPXfASwMfb.jpg',3.237521693485123,3,'2026-09-10',2,NULL,NULL),(400,'Things to Do in Denver When You\'re Dead','Things to Do in Denver When You\'re Dead','A mafia film in Tarantino style with a star-studded cast. Jimmy’s “The Saint” gangster career has finally ended. Yet now he finds him self doing favors for a wise godfather known as “The Man with the Plan.”','Protect. Love. Honor. Avenge.',8000000,529766,6.932221,6.7,85,116,'1995-12-01','en','/n6UTVN4Ff8b8VYlAtZ7hgW9Xzp0.jpg',2.835280155902818,3,'2026-09-10',2,NULL,NULL),(401,'情归新泽西','Garden State','26岁的青年安德鲁（扎克·布拉夫 Zach Braff 饰）独自在洛杉矶打拼9年，他志愿成为一名演员，不过时至今日仍默默无名，平常依靠在餐馆打工维持营生。一通电话，将安德鲁带回阔别已久的新泽西老家。多年来，他因某些原因与家人绝少联系，常年服用抗抑郁药物又使得他对周遭的一切都漠不关心，即便如今日，瘫痪多年的母亲意外去世。在故乡，他重新见到身为精神科医生的父亲以及当年的狐朋狗友，一切似乎没变，一切有发生了很大改变。 　　在父亲的建议下，安德鲁前往医院诊疗困扰自己多时头痛，却在此结识了美丽但有些神经质的女孩萨曼（娜塔莉·波曼 饰），有如死水的绝望生活由此发生了转变……',NULL,2500000,26781723,30.583959,7.1,618,102,'2004-07-28','en','/h3iqYiGS6F3y7GxaS4AT8nFxZ2i.jpg',3.4354488362118576,3,'2026-09-10',2,NULL,NULL),(403,'为黛西小姐开车','Driving Miss Daisy','本片改编自阿尔弗雷德·乌里荣获普利策奖的舞台剧，讲述了一位年迈的犹太老妇人与她非裔司机之间长达二十五年的情谊。','The funny, touching and totally irresistible story of a working relationship that became a 25-year friendship.',7500000,145793296,19.585801,7,350,99,'1989-12-13','en','/iaCzvcY42HihFxQBTZCTKMpsI0P.jpg',3.2375735636978873,3,'2026-09-10',2,NULL,NULL),(404,'史崔特先生的故事','The Straight Story','本片根据真实故事改编，讲述阿尔文·史崔特驾驶着他那辆1961年的割草机，从爱荷华州劳伦斯市一路前往威斯康星州锡安山，探望中风后与他疏远多年的兄弟。',NULL,10000000,0,15.280261,7.7,306,112,'1999-10-15','en','/5HxFy0nNDqaPihpWuQCsvWDj4kx.jpg',3.2531269996252314,3,'2026-09-10',2,NULL,NULL),(408,'白雪公主和七个小矮人','Snow White and the Seven Dwarfs','公主被恶毒的继母流放到危险的森林里，被七位矮人矿工救出，并成为他们家庭的一员。','The Happiest, Dopiest, Grumpiest, Sneeziest movie of the year.',1488423,184925486,80.171283,6.9,1914,83,'1937-12-20','en','/3VAHfuNb6Z7UiW12iYKANSPBl8m.jpg',3.829094017367817,3,'2026-09-10',2,NULL,NULL),(409,'The English Patient','The English Patient','Beginning in the 1930s, \"The English Patient\" tells the story of Count Almásy who is a Hungarian map maker employed by the Royal Geographical Society to chart the vast expanses of the Sahara Desert along with several other prominent explorers. As World War II unfolds, Almásy enters into a world of love, betrayal, and politics that is later revealed in a series of flashbacks while Almásy is on his death bed after being horribly burned in a plane crash.','In love, there are no boundaries.',27000000,231976425,29.381878,7,542,162,'1996-11-14','en','/h8F6dyUPSnS07WqR4TK7y2tozdy.jpg',3.3818719344607797,3,'2026-09-10',2,NULL,NULL),(411,'纳尼亚传奇1：狮子、女巫和魔衣橱','The Chronicles of Narnia: The Lion, the Witch and the Wardrobe','二战期间，四个小孩子随着父母来到乡下避战。这些乡村住宅古色古香，其中有一个房间里摆着一个大衣柜。一天，几个小孩子玩捉迷藏，露西躲进了衣柜里，眼前却意外出现了一个神奇的世界——那里白雪皑皑，荒无人烟。她在雪地上走着走着，遇上了人羊怪物。其他孩子也一一进入这个魔法衣橱。他们得知里面的王国叫纳尼亚，正在被一个邪恶的女巫所统治。女巫下了毒咒，使纳尼亚成为永远冰天雪地的冰封世界。四个人类的孩子将在伟大崇高的万兽之王：雄狮阿斯兰的带领下与邪恶的女巫展开一场大战，破除冰封咒语，解救纳尼亚王国，恢复四季如春的世界。','Evil Has Reigned For 100 Years...',180000000,748806957,67.391328,6.7,2629,143,'2005-12-07','en','/iREd0rNCjYdf5Ar0vfaW32yrkm.jpg',3.835680635372509,3,'2026-09-10',2,NULL,NULL),(414,'永远的蝙蝠侠','Batman Forever','高谭市的黑暗势力又开始蠢蠢欲动了，这次是毁了半边脸的“双面人”（汤米•李•琼斯 Tommy Lee Jones 饰）。一次，“双面人”袭击了马戏团，演员迪克（克里斯•奥唐纳 Chris O\'Donnell 饰）阻止了“双面人”的阴谋，家人却因此惨遭杀害。  　　布鲁斯（瓦尔•基尔默 Val Kilmer 饰）收留了迪克，并说服了满腔仇恨的迪克留了下来。因研究计划被拒绝而仇视韦布斯的公司职员爱德华（金•凯瑞 Jim Carrey 饰）成功研究出脑波吸收装置，化身成为“谜语侠”。  　　“双面人”和“谜语侠”联手破坏高谭市，并通过脑电波吸收装置大量吸收市民的脑电波。蝙蝠侠这次的对手强大得可怕，蝙蝠侠最终能否战胜罪恶?','Courage now, truth always...',100000000,336529144,48.205606,5.2,1498,121,'1995-05-31','en','/suyFtu1iuX7NHZbXxWtCucnuh0T.jpg',3.34758641482043,3,'2026-09-10',2,NULL,NULL),(415,'蝙蝠侠与罗宾','Batman & Robin','蝙蝠侠（乔治•克鲁尼 George Clooney 饰）和罗宾（克里斯•奥唐纳 Chris O\'Donnell 饰）这次遇到有生以来最大的挑战：“急冻人”（阿诺•施瓦辛格 Arnold Schwarzenegger 饰）！  　　“急冻人”原是一个科学奇才，但一次意外却令他只能靠急救机器为生。更为糟糕的是，除非他将整个高谭市的温度保持在零度以下，否则他心爱的妻子将永远不能醒来。“急冻人”开始一步步建立自己的冷冻王国，蝙蝠侠将是这个计划的最大阻碍，“急冻人”迫切需要除掉这个眼中钉。  　　罗宾逐渐成为蝙蝠侠的得力助手，两人合力化解了“急冻人”的一次次阴谋。但美艳的“毒藤女”（乌玛•瑟曼 Uma Thurman 饰）的出现给罗宾和蝙蝠侠彼此之间的关系带来了危机：“毒藤女”利用罗宾对她的心意，一步步设下陷阱，诱使两人互相猜疑。  　　蝙蝠侠和罗宾最终能否化解心结，战胜“急冻人”和“毒藤女”？','Strength. Courage. Honor. And loyalty.',125000000,238207122,50.073575,4.2,1418,125,'1997-06-20','en','/63OhJ5UL6sd1TjqKWzndBrSDl5j.jpg',3.1450926356920625,3,'2026-09-10',2,NULL,NULL),(421,'The Life Aquatic with Steve Zissou','The Life Aquatic with Steve Zissou','Wes Anderson’s incisive quirky comedy build up stars complex characters like in ‘The Royal Tenenbaums’ with Bill Murray on in the leading role. An ocean adventure documentary film maker Zissou is put in all imaginable life situations and a tough life crisis as he attempts to make a new film about capturing the creature that caused him pain.','The deeper you go, the weirder life gets.',50000000,34808403,25.237969,7.1,775,119,'2004-12-10','en','/BXhBZoPBsIfWYbl0LXSH4GMvXy.jpg',3.4890582965941395,3,'2026-09-10',2,NULL,NULL),(423,'钢琴家','The Pianist','第二次世界大战爆发前夕，波兰犹太裔钢琴家瓦迪斯瓦夫·什皮尔曼仍在华沙电台演奏钢琴。随着德军占领波兰，针对犹太人的迫害不断升级，他和家人被迫迁入华沙犹太区，原本平静的生活也彻底崩塌。在饥饿、暴力与死亡的阴影下，什皮尔曼与家人艰难求生，却又在战争中被迫分离。侥幸逃过驱逐后，他只能依靠朋友的帮助辗转藏身，并在逐渐沦为废墟的华沙中独自躲避搜捕。曾经陪伴他的音乐几乎从生活中消失，而活下去成为他唯一能够坚持的事情……','',35000000,120072577,19.061,8.371,1864,150,'2002-09-17','en','/1J3yRdmlBF3a5l3GLqBScRBdhJr.jpg',3.9998071657414593,3,'2026-09-10',2,NULL,NULL),(424,'辛德勒的名单','Schindler\'s List','1939年，纳粹德国入侵波兰。德国商人奥斯卡·辛德勒来到被占领的克拉科夫，利用自己的人脉和金钱开办了一家搪瓷厂，并雇用被迫劳动的犹太人生产军需用品，希望借战争获取财富。随着纳粹对犹太人的迫害不断升级，辛德勒亲眼目睹了克拉科夫犹太区遭到清剿，以及无数普通人被驱逐和杀害。曾经只关心生意与利益的他开始发生改变，并利用自己的工厂、财富以及与纳粹官员之间的关系，尽可能保护身边的犹太工人。在愈发疯狂的屠杀与战争阴影下，一场以生命为代价的救援也由此悄然展开……','',22000000,321365567,36.461,8.57,4329,195,'1993-12-15','en','/7cDI6MrIi12uQxfipiNIeJPYljy.jpg',4.366345328765389,3,'2026-09-10',2,NULL,NULL),(425,'冰川时代','Ice Age','With the impending ice age almost upon them, a mismatched trio of prehistoric critters – Manny the woolly mammoth, Diego the saber-toothed tiger and Sid the giant sloth – find an orphaned infant and decide to return it to its human parents. Along the way, the unlikely allies become friends but, when enemies attack, their quest takes on far nobler aims.','They came. They thawed. They conquered.',59000000,383257136,99.561972,7.1,3857,81,'2002-03-10','en','/gLhHHZUzeseRXShoDyC4VqLgsNv.jpg',4.103543834098008,3,'2026-09-10',2,NULL,NULL),(429,'黄金三镖客','Il buono, il brutto, il cattivo','对三个男人而言，内战并非地狱……而只是热身！克林特·伊斯特伍德再度化身“无名客”，此番联手两名枪手，共同追寻一批价值20万美元的黄金，决不让任何人阻挡——哪怕是内战中的交战派系。','',1200000,6000000,24.1991,8.467,2311,161,'1966-12-23','it','/fKp0a1PinDvVB2gRyKKeLDMXQD8.jpg',4.108093227148223,3,'2026-09-10',2,NULL,NULL),(431,'心慌方','Cube','试想像当你一觉醒来，发现独处高度精密且结构繁复，地下甚至天花也是由一个个正立方体切成的，没有食物、饮料，身上穿了囚犯般的简陋衣服，心乱如麻的你四处试探，试图逃出生天。机关找到了，推门进去，是没完没了的密室。终于遇上黑人警察，继而是更多受害者。继续逃亡，他们发觉各人独有特殊技能可助离开这迷宫。人性丑恶和自私在这生死边缘间显露无遗……','Don\'t look for a reason... Look for a way out.',250000,501818,44.656151,6.9,1069,90,'1997-09-09','en','/9X1TlFndO3V8BS6hKl7TjYTgU2a.jpg',3.590965282926264,3,'2026-09-10',2,NULL,NULL),(433,'欢乐满人间','Mary Poppins','一位魔法保姆来到一位冷漠的银行家那并不快乐的家庭中工作。','It\'s supercalifragilisticexpialidocious!',6000000,102272727,59.961523,7.4,1183,139,'1964-08-27','en','/o4Wsby4ydIXhWmtmfvb451D5Np1.jpg',3.7464554164588164,3,'2026-09-10',2,NULL,NULL),(435,'后天','The Day After Tomorrow','气候学家杰克·霍尔在研究全球气候变化时发现，全球变暖和极地冰川融化可能扰乱洋流循环，使地球迅速陷入极端气候危机。然而他的警告并未得到政府足够重视。不久后，异常天气开始席卷世界，巨型冰雹、龙卷风、暴雨和海啸接连出现，北半球气温更在短时间内急剧下降。与此同时，杰克的儿子山姆正在纽约参加学术竞赛，突如其来的灾难将他和同伴困在被洪水与严寒包围的城市中。面对一场远超预想的全球性灾难，杰克决定冒险穿越冰封的大地前往纽约，寻找被困的儿子……','Where will you be?',125000000,544272402,41.380094,6.2,2392,124,'2004-05-26','en','/7ofpLvibdY6YwtpRGGQGsWOn5IG.jpg',3.637871411206914,3,'2026-09-10',2,NULL,NULL),(436,'万福玛丽亚','María, llena eres de gracia','这部影片讲述了一位聪明果敢的年轻女性，从哥伦比亚到纽约，经历了一场改变命运又危及生命的漫长旅程，交织出一段关于风险、决心与生存的惊心动魄的叙事。[Fine Line Features]','Based on 10,000 true stories.',0,0,3.027892,6.9,101,101,'2004-01-18','es','/ygSWLfwtvLt7BarnQGnuU0zXjOn.jpg',2.873763066199954,3,'2026-09-10',2,NULL,NULL),(440,'异形大战铁血战士2','Aliens vs Predator: Requiem','一艘铁血战士的飞船离开地球，船上载有被捕获的异形卵和铁血战士“刀疤”的尸体。突然，一个拥有铁血战士和异形双重特征的胸爆虫（chestburster）从刀疤体内迸出，这个继承了铁血战士与异形双重基因的“终极异形”在返航的飞船上大开杀戒，最终导致飞船失控坠毁。当终极异形和异形抱脸体逃入附近的森林，当地居民便成了它们的猎物与温床。与此同时，在遥远的铁血母星，精英战士“独狼”接收到求救信号，动身前往地球执行他的清理任务。','The Last Place On Earth We Want To Be Is In The Middle',40000000,41797066,39.381913,4.9,740,94,'2007-12-25','en','/xYoxxoCCEYHOGXkqOZaCWpeWcmn.jpg',3.17532323227496,3,'2026-09-10',2,NULL,NULL),(451,'离开拉斯维加斯','Leaving Las Vegas','被解雇后，酗酒编剧拿着最后的遣散费前往拉斯维加斯，计划用酒精了结生命。在那里，他遇上了一名需要被需要的妓女。','I Love You... The Way You Are.',3600000,49800000,22.030517,7.1,360,112,'1995-10-27','en','/wxtZqarfgyT1f9eezacvCLQUTAq.jpg',3.2608324481832733,3,'2026-09-10',2,NULL,NULL),(453,'美丽心灵','A Beautiful Mind','这是一部关于一个真实天才的极富人性的剧情片。英俊而又十分古怪的数学家小约翰纳什念研究生时便发明了他著名的博弈理论，短短26页的论文在经济、军事等领域产生深远的影响，他开始享有国际声誉。但纳什出众的直觉受到了精神分裂症的困扰，使他向学术上最高层次进军的辉煌历程发生了巨大改变。面对这个曾经击毁了许多人的挑战，纳什在深爱着他的妻子艾丽西亚的相助下，与被认为是只能好转、无法治愈的疾病作斗争。经过十几年的不懈努力，完全通过意志的力量，他一如既往地坚持工作，并于1994年获得诺贝尔奖，他在博奕论方面颇具前瞻性的工作也成为20世纪最具影响力的理论。这是一个真人真事的传奇故事，今天纳什继续在他的领域中耕耘着。','I need to believe that something extra ordinary is possible...',60000000,313542341,59.248437,7.7,3009,135,'2001-12-11','en','/rEIg5yJdNOt9fmX4P8gU9LeNoTQ.jpg',4.091802861730031,3,'2026-09-10',2,NULL,NULL),(454,'罗密欧与朱丽叶','Romeo + Juliet','罗密欧（莱昂纳多•迪卡普里奥 饰）与茱丽叶（克莱尔•丹妮丝 饰）在一个派对上一见钟情了，这个派对是为了庆祝茱丽叶找到了如意郎君。可是他们各自所在的家族是死对头，常常爆发冲突。罗密欧潜入了茱丽叶家的后院，两人互诉爱意，由于知道家族之间的不和是他们的障碍，所以他们在神父的帮 助下秘密完婚。茱丽叶的表兄泰华是个暴躁的人，他要跟罗密欧决斗可是罗密欧只想和平相处，罗密欧好友莫邱托想杀死泰华，却先被泰华杀死，罗密欧愤怒之下也把泰华杀了。  　　罗密欧被驱逐出境，茱丽叶要另嫁他门。神父策划让茱丽叶假死，可是没有收到信件的罗密欧信以为真，在茱丽叶醒来之际，喝下了毒药…','My only love sprung from my only hate.',14500000,147298761,41.493042,6.7,1374,120,'1996-10-31','en','/j18A184Jv8qPOvDd6CywlQbGsZa.jpg',3.6128753941669673,3,'2026-09-10',2,NULL,NULL),(455,'我爱贝克汉姆','Bend It Like Beckham','居住在英国的印度裔少女杰西(帕明特·纳格拉饰)酷爱足球，她在自己的小屋里贴满了自己的偶像贝克汉姆的海报和照片，希望自己的球技能和小贝一样出色。一天，杰西在公园里踢球时，一位教练看中她的球技，邀请她加入一支职业足球队，但是信奉印度教的父母并不希望自己的女儿去当一名足球运动员，所以坚决反对。杰西该怎样办呢……','Sometimes, to follow your dreams... you\'ve got to bend the rules!',3500159,76578641,22.054546,6.2,578,112,'2002-04-11','en','/2dzSBmFWWqt8NbnubJKIWU21Y86.jpg',3.277097969360154,3,'2026-09-10',2,NULL,NULL),(462,'永不妥协','Erin Brockovich','埃琳·布罗克维奇（朱莉娅·罗伯茨饰）是一位经历了两次离婚并拖着三个孩子的单身母亲，在一次十分无奈的交通事故之后，这个一贫如洗，既无工作，也无前途的可怜妇女几乎到了走投无路的绝境。万般无奈之下，埃琳只得恳求自己的律师埃德.马斯瑞（阿伯特·芬尼饰）雇用她，在律师事务所里打工度日。一天，埃琳在一堆有关资产和债务的文件中很偶然地发现了一些十分可疑的医药单据，这引起了她的困惑和怀疑。在埃德的支持下，埃琳开始展开调查，并很快找到线索，发现了当地社区隐藏着的重大环境污染事件，一处非法排放的有毒污水正在损害居民的健康，是造成一种致命疾病的根源。 可怕的是居民们对此并未察觉，甚至起初对埃琳的结论表示怀疑，但是不久他们就被埃琳的执着和责任感打动了，大家在一个目标下紧紧地团结了起来，埃 琳用自己的行动赢得了全体居民的信任，成了他们的核心和代言人。邻居乔治（阿伦·埃克哈特饰）在整个事件中是埃琳的一名坚定的支持者，他俩的爱情成了支持埃琳的重要精神支柱。埃琳挨家挨户的做动员工作，终于得到了600多个人的签名支持。埃琳和埃德在一家大型法律事务机构的帮助下，终于使污染事件得到了令人满意的赔偿，创造了美国历史上同类民事案件的赔偿金额之最，达3.33亿美元。埃琳正是用自己的无比坚韧的毅力，克服难以想象的困难，向世人证明了一个“弱女子”的价值，在人生的道路上开辟了一片新的天地。','She brought a small town to its feet and a huge corporation to its knees.',52000000,256271286,30.347332,7.1,716,131,'2000-03-17','en','/dE8Elb3p8wbk7VbUTxMXL2Jppvy.jpg',3.477695464278223,3,'2026-09-10',2,NULL,NULL),(464,'其实在天堂','Så som i himmelen','丹尼尔（迈克尔·恩奎斯特 Michael Nyqvist 饰）是一名指挥家，专业技能出色的他在全世界范围内享有着极高的声誉，随着时间的流逝，他的身体渐渐的开始无法支撑他对音乐的热情，一次突然来袭的心脏病迫使他永远的告别了舞台。为了养病，丹尼尔回到了久违的家乡，在那里，他成为了教堂唱诗班的指挥。',NULL,0,0,4.321249,6.9,42,132,'2004-09-03','sv','/qtPUrODebW2L8JJSWGIWXjs1tOw.jpg',2.67326459575609,3,'2026-09-10',2,NULL,NULL),(468,'我自己的爱达荷','My Own Private Idaho','麦克（瑞凡•菲尼克斯）和斯考特（基努•里维斯）同为沦落街头的男妓，然而因为相差巨大的家庭背景，“同为天涯沦落人”的他们并非表面般“心照不宣”。时常昏厥的麦克脑海中一直充满着有关童年的破碎片段，爱达荷的诗意田园也常常入他梦境，他一心想找回失散多年的母亲，将斯考特视为知己和爱人。斯考特本是波特兰市长的儿子，“自甘堕落”只为体会放荡青春的快感，他清楚地知道，虽然现在陪着麦克一路从波特兰到西雅图，又从爱达荷到意大利，麦克却成不了他最终的温暖归宿，他能回归的，是权势、荣华与姑娘。','It\'s not where you go, it\'s how you get there.',2500000,0,10.363642,7.1,212,104,'1991-10-17','en','/4zxmVVcV25Oh86KJdW3QxwiONL3.jpg',3.0884207373795403,3,'2026-09-10',2,NULL,NULL),(470,'21 Grams','21 Grams','This is the story of three gentle persons: Paul Rivers an ailing mathematician lovelessly married to an English émigré, Christina Peck, an upper-middle-class suburban housewife, happily married and mother of two little girls, and Jack Jordan, an ex-convict who has found in his Christian faith the strength to raise a family. They will be brought together by a terrible accident that will change their lives. By the final frame, none of them will be the same as they will learn harsh truths about love, faith, courage, desire and guilt, and how chance can change our worlds irretrievably, forever.','How much does life weigh?',20000000,60427839,32.243357,7.2,918,124,'2003-09-06','en','/mJ90fpnVWiRWMsRctHUGrUlnSLF.jpg',3.570979432024402,3,'2026-09-10',2,NULL,NULL),(473,'死亡密码','Pi','一个沉迷数字的电脑天才，研究出怎样可以透过数字，推演出种种生命的奥秘和规律。他的研究引来了华尔街股票市场的炒家们和犹太神秘教派的注意，前者要他计算出股票的起跌规律，后者要他解读出隐藏在犹太教的摩西五书中的密码。阿罗诺夫斯基用了六万美元的成本,粗微粒的黑白摄影和大量的电子音乐,营造出一个介乎真实与虚拟的电脑奇幻世界。','There will be no order, only chaos',60000,3221152,27.788067,7.1,586,84,'1998-07-10','en','/fJA22FjlAW8rzrOw9Mwanl6oTc9.jpg',3.4136347324781178,3,'2026-09-10',2,NULL,NULL),(479,'杀戮战警','Shaft','纨裤子弟华特谋杀了年轻黑人学生，遭到黑豹的逮捕。但由于他父亲有钱有势，支付保释金后，华特再度获得自由，并誓言不杀黑豹誓不休。而想取黑豹性命的，还有与罪犯同流合污的警察同僚，曾遭受黑豹羞辱的多米尼加籍毒枭。黑豹除了要躲避追杀，还要找出并保护现已不知去向的谋杀案目击证人，将华特绳之于法。','Still the man, any questions?',46000000,107196498,19.643365,5.5,308,99,'2000-06-15','en','/pn7AE658mAHDS5xOinIeIOF7zBE.jpg',3.0690156181272394,3,'2026-09-10',2,NULL,NULL),(480,'季风婚宴','Monsoon Wedding','印度新德里的一家人正在筹备女儿阿迪特（瓦塞达拉Vasundhara Das 饰）出嫁的婚礼。父亲拉里特（纳萨鲁丁•沙 Naseeruddin Shah 饰）为她选定的如意郎君是从美国留学回来的富商之子海蒙特。然而，阿迪特并不开心，因为她还有一个在电视台做主持人的情人，并且是个有妇之夫。所以她一面在父母的督促下准备婚礼，一方面又要偷偷跟意中人约会……婚礼还改变了很多人的命运：婚礼设计师杜比跟女仆爱丽丝机缘巧合，堕入爱河；阿迪特的表妹跟澳大利亚的留学生打得火热；阿迪特的姑丈泰迦表示要资助她的表姐丽尔出国留学。然而，丽尔并不领情，反而极力反对女儿跟泰迦相处，因为她隐瞒了一段不堪回首的往事……','A stressed father, a bride-to-be with a secret, a smitten event planner, and relatives from around the world create much ado about the preparations for an arranged marriage in India.',0,0,8.109958,6.8,57,114,'2001-08-30','hi','/nchsMqHcTE7kIylMKQjmEZb4E6H.jpg',2.7489866802944887,3,'2026-09-10',2,NULL,NULL),(489,'心灵捕手','Good Will Hunting','麻省理工学院的数学教授蓝波在席上公布了一道困难的数学题，却被年轻的清洁工威尔（马特·戴蒙 饰）解了出来。可是威尔却是个问题少年，成天和好朋友查克（本·阿弗莱特 饰）等人四处闲逛，打架滋事。当蓝波找到这个天才的时候，他正因为打架袭警被法庭宣判送进看守所。蓝波向法官求情保释，才使他免于牢狱之灾。蓝波为了让威尔找到自己的人生目标，不浪费他的数学天赋，请了很多心理学专家为威尔做辅导，但是威尔十分抗拒，专家们都束手无策。无计可施之下，蓝波求助于他大学的好友，心理学教授尚恩（罗宾·威廉姆斯 饰），希望能够帮助威尔打开心房。经过蓝波和尚恩的不懈努力，威尔渐渐敞开心胸，而好友查克的一席话，更是让他豁然开朗。','Some people can never believe in themselves, until someone believes in them.',10000000,225933435,43.734886,7.9,2811,126,'1997-12-05','en','/z2FnLKpFi1HPO7BEJxdkv6hpJSU.jpg',4.084050794758975,3,'2026-09-10',2,NULL,NULL),(492,'Being John Malkovich','Being John Malkovich','Spike Jonze’s debut feature film is a love story mix of comedy and fantasy. The story is about an unsuccessful puppeteer named Craig, who one day at work finds a portal into the head of actor John Malkovich. The portal soon becomes a passion for anybody who enters it’s mad and controlling world of overtaking another human body.','Ever wanted to be someone else? Now you can.',13000000,22863596,27.546914,7.3,1101,112,'1999-09-30','en','/31FGQu3OnwdmS4COquENe0vMZc0.jpg',3.632177017332401,3,'2026-09-10',2,NULL,NULL),(496,'波拉特','Borat: Cultural Learnings of America for Make Benefit Glorious Nation of Kazakhstan','此电影项目系政府委派，旨在拓宽民众视野，弘扬国家荣耀。文化学习对遵循全球标准至关重要。我们将祖国建设为更美好、更宜居的家园。哈萨克人民是进取且令人赞叹的民族，本项目完成后，将在世界民族之林中树立全新的乐观生活姿态。本片将拉近我国与美利坚合众国之距离。我们致力于满足国民对哈萨克知识之需求，学习美利坚文化是对光荣祖国未来发展的积极举措。[20世纪福克斯]','Come to Kazakhstan, it\'s nice!',18000000,261572744,29.487784,6.5,1579,82,'2006-11-01','en','/fIj1s9OLmtpjcmYXg8WTNhgnMiQ.jpg',3.5799958228255133,3,'2026-09-10',2,NULL,NULL),(497,'绿里奇迹','The Green Mile','1935年。美国南部惨淡肃杀的冷山监狱。这里有片一英里长的绿地，人们叫它“绿里”。不过，它的居民皆为死囚，在绿地的另一头，便是行刑用的电椅。保罗·艾治科姆（汤姆·汉 克斯饰）是这里的狱监，对于走过“绿里”、继而在电椅上惨叫毙命的死囚行刑程序，他俨然已无动于衷。除了保罗及其爱妻简外，“绿里”上还有凶残的副狱监豪威尔，有施虐倾向 的狱吏佩西，良心未泯的看守海尔和他身患绝症的妻子美琳达，喜用宠物鼠逗狱吏和诸“难友”取乐的德拉克，连环杀人狂威廉，负疚深重的犯人彼特等一干形形色色的人们。他们之 间充满了敌意和不屑。但神秘的约翰·考夫利的到来改变了一切。考夫利因谋杀两名幼女被 判死罪，他相貌恐怖，体形硕大，却出奇地平和、敏感而缄默，天真时甚至像个孩子，同时， 他似乎还具有一种不可名状的神秘力量，令人不由自主地对其产生信任感，这不禁让艾治科姆对其罪行是否属实深怀疑问。 真情无法取代程式，考夫利终要走过“绿里”。在这个貌似粗鲁的男人即将赴死的刹那，“绿里”上的人们以不同以往的形式实现了各自生命的重要跨越。','',60000000,284600000,35.9003,8.506,4048,189,'1999-12-10','en','/oHL5har21XS91tAL0gUnDCg9kvD.jpg',4.327975832165856,3,'2026-09-10',2,NULL,NULL),(500,'落水狗','Reservoir Dogs','昆汀·塔伦蒂诺的邪典经典处女作，讲述了一桩珠宝劫案出了差错的故事。','Every dog has his day.',1200000,14661007,66.925866,8,3697,99,'1992-09-02','en','/xi8Iu6qyTfyZVDVy60raIOYJJmk.jpg',4.2436553013383636,3,'2026-09-10',2,NULL,NULL),(503,'海神号','Poseidon','新年的钟声即将响起，欢快喜庆的气氛弥漫在正孤独航行于北大西洋上的海神号中。这是一艘拥有800个房间、13层楼高、载客量超过2000人的超豪华邮轮。在船长麦克•布莱福德（Andre Braugher 饰）的组织下，达官显贵、社会名流纷纷云集在豪华明亮的大厅，伴着美食佳酒、轻歌曼舞一同庆祝新年的到来。与此同时，大西洋底的地壳发生剧烈震动，继而掀起足以摧毁万物的滔天巨浪。在自然面前，再坚固的船只也需俯首称臣。海神号被巨浪掀翻，无数人丢掉性命。面对死神的威胁，侥幸逃过第一波劫难的人们开始想尽办法逃生。在茫茫无所依靠的大海中央，他们的命运终将如何？本片翻拍自1972年经典灾难片《海神号遇险记》（The Poseidon Adventure）。','Mayday',160000000,181674817,21.133748,5.5,583,99,'2006-05-12','en','/A3GKV0paKvadgEI9wLpHHwCFXzr.jpg',3.1835614805539882,3,'2026-09-10',2,NULL,NULL),(504,'女魔头','Monster','沃诺斯 童年的不幸把她推向了罪孽深重的人生。她的母亲离她而去，对待她的是无休止的谩骂和虐打。沃诺斯为了满足毒瘾和生计，十来岁就开始了卖淫的生活。她在公路上为司机们提供低级的性服务，无望的生活无穷无尽。然而，年轻女孩西尔比  的出现让她心中有了亮光，两人开始了一段恋情，住在一起。西尔比对于金钱的需求很大，这使得沃诺斯心甘情愿为爱人奔波赚钱。她去面试了好几份工作，却因为知识的匮乏和粗鲁的男性化性格而被拒之门外。她只能重操旧业，在公路上遇见了一个变态的嫖客，一怒之下把他杀死，夺走了他的钱和车。从此，沃诺斯开始频频犯罪，成为公路上的心狠手辣的女魔头。','The first female serial killer of America',8000000,60378584,19.683187,7,485,110,'2003-11-16','en','/sWPKG1GX0woLNBuvDZkwZC8Q3Ub.jpg',3.3284661911085642,3,'2026-09-10',2,NULL,NULL),(507,'亡命之徒','Killing Zoe','锡特是美国顶尖的职业大盗，他应好友艾力的邀请，前往巴黎合作“做世界\"。他一抵达，便结识了兼职妓女祖儿，并发展了一段感情；另一边，艾力准备一伙人在法国国庆日打劫银行。本来一切照原计划进行，但是艾力突然性情大变，当场杀掉十多名银行员工，碰巧祖儿正在上班，锡特唯恐失控的艾力会对祖儿不利，遂决定带同祖儿一起逃离银行，但他们能否顺利逃生呢？',NULL,1500000,418961,5.817519,6.1,111,96,'1993-10-01','en','/k3UEKMVnkljOlsO5sLmz87YGlaG.jpg',2.8711796004710926,3,'2026-09-10',2,NULL,NULL),(508,'Love Actually','Love Actually','Follows seemingly unrelated people as their lives begin to intertwine while they fall in – and out – of love. Affections languish and develop as Christmas draws near.','The ultimate romantic comedy.',40000000,244931766,37.073127,7,1869,135,'2003-09-07','en','/7QPeVsr9rcFU9Gl90yg0gTOTpVv.jpg',3.7459443351574593,3,'2026-09-10',2,NULL,NULL),(509,'诺丁山','Notting Hill','------著名影星安娜斯各特（茱莉亚罗伯茨 饰）的演艺事业如日中天。一天她来到了诺丁山的一间书店，邂逅了事业爱情两失意的老板威廉萨克（休格朗特 饰）。威廉认出了安娜是红极一时的明星，十分惊讶，也没想到自己会爱上这位明星，假扮记者借故约会安娜。很快两人坠入爱河，本来甜蜜的生活却一下子被发现了的记者破坏了。安娜承受着媒体的压力，需要做出决定，两人也吵了起来……','Can the most famous film star in the world fall for the man on the street?',42000000,363889678,28.969151,7,1262,124,'1999-05-13','en','/rOO9QoPSmCWTzHUwUbBqnNrvSoC.jpg',3.6194462498308,3,'2026-09-10',2,NULL,NULL),(510,'飞越疯人院','One Flew Over the Cuckoo\'s Nest','在州立精神病院里休养总比蹲监狱强，对吧？兰德尔·P·麦克墨菲（杰克·尼科尔森 饰），一个血管里流淌着闪电、舌绽莲花的自由派骗子，装疯混进了他所谓的“疯子们”中间。很快，他那极具感染力的无序感便与麻木的例行程序发生冲撞。当世界大赛正酣时，这群被镇静剂泡透的家伙怎能披着浴袍拖沓度日？这意味着战争！一方是麦克墨菲，另一方则是轻声细语的拉契特护士（路易丝·弗莱彻 饰）——这位影史上最冷酷可怕的恶魔之一。而赌注，是整个病房每位患者的命运。','',3000000,108981275,22.5808,8.406,2919,133,'1975-11-19','en','/iAUJA80BI8nsvN8TgeZSzm4tIdc.jpg',4.16866603068358,3,'2026-09-10',2,NULL,NULL),(512,'独家新闻','Scoop','一个美国女大学生桑德拉（斯嘉丽·约翰逊 Scarlett Johansson 饰），为了替学校报纸寻找独家新闻，来到英国伦敦采访一个电影导演。在调查和采访的过程中，她参加了魔术师希德（伍迪·艾伦 Woody Allen 饰）一次魔术戏法表演，在密闭的箱中她遇见了一个离世 的资深记者鬼魂。记者生前是一个为了拿到独家新闻无所不尽其用的人。他在去往阴间的船上从一个被害的前任秘书口中得知“塔罗牌杀手”竟然是英俊多金的贵族彼得（休·杰克曼 Hugh Jackman 饰）。他不想让这有爆炸性的新闻埋葬，于是找上桑德拉希望她帮他完成心愿。\r 　　面对这个千载难逢的机会，桑德拉决定深入虎穴，拉上魔术师希德假扮父女混进上流社会，接近彼得。事情顺利得令人惊讶，桑德拉与彼得成了甜蜜的一对。然而塔罗牌杀手又继续行动……','The perfect man. The perfect story. The perfect murder.',4000000,31584901,17.229537,6.4,420,96,'2006-07-27','en','/5hySJdYdBYZdE9NJnDrSANOKM59.jpg',3.216810295155243,3,'2026-09-10',2,NULL,NULL),(522,'艾德·伍德','Ed Wood','这是一部关于奋斗的个人自传电影。1951年，心怀大志的艾德•伍德（约翰尼•德普 Johnny Depp 饰）终于等来机会上演一出自导自演的电影，但是，这个计划不久就夭折了。艾德并没有气馁，而是接着又一个一个的找投资商，找演员，甚至连他的女友也被拉进剧组参加演出。每次总是准备工作进行得大半时，电影合同最终还是没有拿到，梦想一次次的破灭，女友也离他而去。我们的艾德虽然自此住进了医院一阵子，但他还没有放弃自己的追梦之旅：还是到处跑着找投资人，苦苦跪求那些著名演员加入自己的剧组，在电影院里被观众的臭鸡蛋烂番茄打得抱头鼠窜。场面热闹而搞笑……','When it came to making bad movies, Ed Wood was the best.',18000000,5887457,24.548633,7.3,630,127,'1994-09-27','en','/n8SrO3WbyuY2b6KazogqbQF348C.jpg',3.455074211716983,3,'2026-09-10',2,NULL,NULL),(524,'Casino','Casino','The life of the gambling paradise – Las Vegas – and its dark mafia underbelly.','No one stays at the top forever.',52000000,116112375,40.06688,7.8,1307,178,'1995-11-22','en','/gziIkUSnYuj9ChCi8qOu2ZunpSC.jpg',3.8086616997491207,3,'2026-09-10',2,NULL,NULL),(525,'The Blues Brothers','The Blues Brothers','Jake Blues is just out of jail, and teams up with his brother, Elwood on a \'mission from God\' to raise funds for the orphanage in which they grew up. The only thing they can do is do what they do best – play music – so they get their old band together and they\'re on their way, while getting in a bit of trouble here and there.','They\'ll never get caught. They\'re on a mission from God.',27000000,115229890,44.714264,7.5,1065,133,'1980-06-17','en','/b0hq1d2d7FIvRGNLewKLm79JNTK.jpg',3.6969613518170195,3,'2026-09-10',2,NULL,NULL),(526,'鹰狼传奇','Ladyhawke','中古世纪一对相爱的豪杰美人，在嫉妒的大主教（里昂•麦考恩 Leo McKern 饰）从中作梗下，以魔咒将两人化为永不能相聚的野狼（拉特格•豪厄 Rutger Hauer饰）与鹰女（米切尔•菲菲 Michelle Pfeiffer饰），白昼美女为鹰黑夜豪杰为狼，不过美人也因为可以化身飞鹰逃脱了好几次大主教的毒手。少年扒手（马修•布罗德里克 Matthew Broderick 饰）适逢其会看到他们的痛苦决定出手相助，虽然有时候因为他可以在黑夜里和美女相处而遭到狼武士的嫉妒而被抓到遍体鳞伤，可是少年还是出于商量和对美女的崇拜准备和邪恶的大主教战斗到底。但崇高的爱情是否可以真的破除法力高强的魔咒，白昼和黑夜是否真的可以相逢，武士能否最后抱得美人归和将大主教惩罚于他的剑下？  　　本片获得1986奥斯卡奖的最佳音响 (Best Sound) 提名；最佳效果(音响编辑) (Best Effects, Sound Effects Editing) 提名。 ©豆瓣','No force in Heaven will release them. No power on Earth can save them.',20000000,18432000,14.370111,6.8,260,121,'1985-03-27','en','/lecujxA7LsuxSBqnw7kFijuf42h.jpg',3.1291709646444144,3,'2026-09-10',2,NULL,NULL),(533,'超级无敌掌门狗：人兔的诅咒','Wallace & Gromit: The Curse of the Were-Rabbit','热爱奶酪的华莱士与他忠诚无比的狗狗格罗米特——这对出自阿德曼公司奥斯卡获奖粘土动画短片的经典组合，将在一部全新的喜剧冒险中亮相，这也是他们的首部长片电影。[梦工厂]','Something bunny is going on...',30000000,192452832,30.380747,6.8,643,85,'2005-09-04','en','/yV4GQP0xHpn81JDXYgJneLYPpnF.jpg',3.4043067841363976,3,'2026-09-10',2,NULL,NULL),(534,'终结者4：救世主','Terminator Salvation','2018年，审判日摧毁了人类文明，地球被大量由“天网”控制的机械人“终结者”占据，苟延残喘的人类被逐一捕杀，自小已被预告未来的约翰·康纳现已长大成人，他与预言一样成为人类领袖，带领生还者团结起义，组织反抗军以寡敌众。 现在，人类已走到约翰·康纳预知的未来，但情况却与他母亲一直向他预警的未来不同，神秘人马库斯的出现，动摇了约翰·康纳从小到大深信不移的理念，他开始怀疑人类能够战胜这场硬仗。 来自过去的马库斯声称最后的记忆是在死囚监房等待行刑，醒来却身处这个陌生的世界，约翰·康纳必须选择是否相信这个不明来历的神秘人，而当天网正准备发动终极突击灭绝反抗军之际，约翰·康纳决定与马库斯联手，潜入“天网”的基地，与敌人迎面交锋，更发现了人类歼灭计划背后的惊天秘密。“天网”利用核浩劫摧毁了大部分人类，一群幸存者们在首领约翰·康纳的带领下，与机器人展开抗衡，阻止他们完成摧毁任务。','The End Begins.',200000000,371353001,71.862892,5.9,2463,115,'2009-05-20','en','/qSrIQb6KS22zZRPgfZ2HQznWmoP.jpg',3.644527395976678,3,'2026-09-10',2,NULL,NULL),(535,'Flashdance','Flashdance','The popular 1980’s dance movie that depicts the life of an exotic dancer with a side job as a welder who true desire is to get into ballet school. It’s her dream to be a professional dancer and now is her chance. The film has a great soundtrack with an Oscar winning song.','When the dancer becomes the dance.',4000000,92921203,18.422323,6.1,302,95,'1983-04-14','en','/62XB7w6gFDzLn0NtwvjWaMvCRcE.jpg',3.115475363633697,3,'2026-09-10',2,NULL,NULL),(539,'惊魂记','Psycho','凤凰城一女秘书卷走客户四万美元公款，仓皇出逃途中入住一家偏僻汽车旅馆。旅馆经营者诺曼·贝茨是位受其母亲支配的年轻人。','',806948,32000000,19.7763,8.407,2320,109,'1960-06-22','en','/gga2k6J5Hxded3Q3Aa4a1zJFJOd.jpg',4.085635244560938,3,'2026-09-10',2,NULL,NULL),(540,'少女特工队','D.E.B.S.','每一年，高中生都需要经过SAT的考试，但是这些天真的学生不知道，美国政府正在通过这项测试，暗中考验他们偷、骗、打的天分。如果一个女孩在测试中取得高分，她便被征收进入一所秘密学园。这个传说中的学园就是D.E.B.S.，而那个幸运的女孩也将成为秘密特工。经过严格的培训后，这些天赋凛异的女孩便被派遣执行特殊任务，坚持“纪律、活力、美貌、力量”的学园宗旨，保护她们的国家免于罪犯的危害。从此，她们就成为英雄与侠义的化身，为了打击犯罪、维护和平四处奔波。现在，四个集美貌和智慧于一身的女孩组成一支特工队，她们经过秘密跟踪、武器爆破和武术训练后，个个都身怀绝技不让须眉。艾美(莎拉·福斯特饰)每项技能都取得高分，也是学院内唯一一个全优毕业的特工；队长麦克丝(蜜根·古德饰)是一个暴脾气的姑娘，但是雷厉风行的作风深得队友爱戴；队中受训时间最短的珍妮特(吉尔·里奇饰)很容易害羞的女孩，不过却是一个骗死人不偿命的狠角色；多米妮克(戴文青木饰)是一个暴喜欢抽烟的女孩，这个性爱机器的床上总少不了男孩。在女校长比特瑞(霍兰德·泰勒饰)和学园主席非普斯(迈克尔·克拉克·邓肯饰)的监管和指导下，这些独一无二的女孩终于顺利地完成了学业。别看她们平日是只穿着格仔短裙的纯情女学生，一遇有危难就立时提枪上马成为“少女特工队”。这一次她们出征的任务就是对付“空中露茜”(乔丹娜·布鲁斯特饰)，但一场简单的兵贼大决战竟然变成情场大混战，头号珠宝女贼露茜一不小心爱上了队长艾美，是为爱倒戈还是将计就计，那就让疯狂惹笑的《少女特工队》告诉你吧……','Evil is so totally busted!',3500000,0,6.396936,5.6,90,91,'2004-01-21','en','/68BfXrFQPHg9iBWJVgp5R48gTix.jpg',2.8110040171704354,3,'2026-09-10',2,NULL,NULL),(542,'阿马罗神父的罪恶','El crimen del padre Amaro','阿马罗（盖尔·加西亚·贝纳尔 Gael García Bernal 饰）是一名年轻的神父，他被教会派往一个偏僻的小村子，帮助在那里传教的神父本尼托（Sancho Gracia 饰）。谁知道本尼托早已经放弃了对上帝的信仰，他利用自己的身份，参与了替毒贩洗黑钱的行动牟取暴利，与此同时，他和寡妇桑嘉娜里（Angélica Aragón 饰）一直保持着肉体关系。桑嘉娜里的女儿艾米丽（安娜·克劳迪亚·塔兰康 Ana Claudia Talancón 饰）是一名虔诚的信徒，她常常找阿马罗忏悔，久而久之，两人之间竟然擦出了爱的火花。一场意外让本尼托的所作所为濒临曝光的边缘，与此同时，艾米丽告诉阿马罗自己怀孕了，她天真的希望阿马罗能够放弃神职娶自己为妻。','Lead us not into temptation',1800000,0,2.179428,6.2,36,118,'2002-10-01','es','/6sWYtAqZem9DTh5cLsb6g3hgdYx.jpg',2.6240961792391353,3,'2026-09-10',2,NULL,NULL),(544,'我为玛丽狂','There\'s Something About Mary','泰德（本•斯蒂勒 饰）在十三年前认识了美丽的玛丽（卡梅隆•迪亚茨 饰）。当时他是个平凡的男孩，爱上的是众人的梦中情人玛丽，玛丽也因为泰德挺身而出救了玛丽患有精神病哥哥沃伦而对他产生了好感。可是因为阴差阳错，两人之间的恋情无法继续发展。泰德从未忘记过玛丽，即使当今他已个有名作家。终于他在朋友的建议下雇私家侦探帕特（马特•狄龙 饰）寻找玛丽。帕特很快在迈阿密找到了玛丽，她依然美丽，身为外科整形医生的她为了照顾哥哥，仍孑然一人。帕特见到美女便会神魂颠倒，他深深的被玛丽吸引了。他决定要欺骗泰德说如今的玛丽变得潦倒贫穷，风采不再，希望借此能让泰德退出。帕特也不忘不择手段的追求玛丽，就在他即将得手的时候，真相还是被泰德知道了。前往迈阿密的路上，泰德遇到一名变态杀人犯，泰德竟然被误以为是杀人凶手。同样的阴差阳错，他也在真凶落网的时候重遇了玛丽……','Love Is In The Hair.',23000000,369884651,57.110486,6.5,1590,119,'1998-07-15','en','/slJD1Dvnsf15LoeqhERsyzisAdn.jpg',3.6447721286574626,3,'2026-09-10',2,NULL,NULL),(546,'Transamerica','Transamerica','Bree is about to get a sex change operation that will finally allow her to actually be what she’s already been in her mind for a long time: a transitioned woman. Yet before this happens she suddenly runs into her son who ends up coming for the trip across the United States.','Life is a Journey. Bring an Open Mind.',1000000,13350369,9.773398,6.9,144,103,'2005-12-23','en','/3MmLpqRlrYSP0uFIDr9BHA4o2LP.jpg',2.975779920965855,3,'2026-09-10',2,NULL,NULL),(547,'马语者','The Horse Whisperer','安妮（克里斯汀•斯科特•托马斯 Kristin Scott Thomas 饰）的女儿格雷斯（斯嘉丽•约翰逊 Scarlett Johansson 饰） 喜欢骑马，却在一次事故中和好友一同从马背摔下，好友遇难，而格雷斯也摔断了一条腿，她心爱的马匹“朝圣者”受伤得面目全非。格雷斯的心里蒙上了挥之不去的阴霾。  　　母亲心里十分着急。听说蒙大拿有精通马语之人汤姆（罗伯特•雷德福 Robert Redford 饰），安妮决定携女儿和“朝圣者”同往疗伤。汤姆起初不答应，终被感动，格雷斯和“朝圣者”在马语者精心的训练调养下慢慢复原，而离开了大都市的安妮也沉浸在那一片安静广袤的天地中。但是，安妮为此付出了代价——她长期离职，被解雇了，同时和丈夫的感情越来越疏远淡漠。另一方面，汤姆的与众不同让安妮心里泛起了阵阵涟漪。 ©豆瓣',NULL,60000000,186883563,12.867352,6.7,292,170,'1998-05-14','en','/8mmcAkkcLpZuQZYDeP7lvI1z8Ap.jpg',3.1470330944162788,3,'2026-09-10',2,NULL,NULL),(549,'Basquiat','Basquiat','Director Julian Schnabel illustrates the portrait of his friend, the first Afro-American Pop Art artist Jean Michel Basquiat who unfortunately died at a young age and just as he was beginning to make a name for himself in the art world. Along side the biography of Basquiat are the artists and the art scene from the early 1980’s New York.','In 1981, A Nineteen-Year-Old Unknown Graffiti Writer Took The New York Art World By Storm. The Rest Is Art History.',2962051,3011195,3.636634,6.6,94,108,'1996-08-09','en','/gFfVhN8BbgHhMb3ZNQRAH5xc7kq.jpg',2.8476629748177755,3,'2026-09-10',2,NULL,NULL),(550,'搏击俱乐部','Fight Club','杰克( 爱德华·诺顿 Edward Norton 饰)是一个充满中年危机意识的人，他非常憎恨自己的生活及一切，再加上他患有严重的失眠症，所以他常常参加各种团体咨询会，只为了能接触人群。在某一个团体咨询会上，杰克遇上了一个跟他同样理由来参加的女烟枪，玛拉(海伦娜·邦汉·卡特 Helena Bonham Carter  饰)，在莫名激素的影响下，杰克和玛拉一起逃离了咨询会，两人的情愫因而滋生…  一个偶然的机会，杰克遇到了卖肥皂的商人泰勒(布拉德·皮特 Brad Pitt 饰)，一个浑身充满叛逆、残酷和暴烈的痞子英雄，并因为自己公寓失火而住进了泰勒破旧不堪的家中。两人因缘际会地成为了好朋友，并创立了“搏击俱乐部”：一个让人们不戴护具而徒手搏击，宗旨在于发泄情绪的地下组织。','',63000000,100853753,37.9973,8.437,9413,139,'1999-10-15','en','/qkrH7rjYKU4KOwwIl6wF6H3ISvm.jpg',4.554694047374519,3,'2026-09-10',2,NULL,NULL),(557,'蜘蛛侠','Spider-Man','彼得·帕克只是美国一个平凡的高中生，当他被蜘蛛博物馆偷跑出来的变种蜘蛛咬了一口之后，彼得的生活彻底改变了。他变得和蜘蛛一样，拥有各种蜘蛛特有的超能力：从手指喷出粘力极强的蜘蛛丝、飞檐走壁等等。彼得兴奋异常，开始利用自己的超能力去赚钱。但当他最爱的叔叔被自己放走的罪犯杀死后，彼得发誓要用自己的超能力去打击犯罪。彼得好友哈利的父亲诺曼是一家生物科技公司的老板，因自己公司生产的飞行器没得到军方首脑赏识而苦恼不堪。一次意外诺曼吸入神经毒气而具有了超能力，引发了自身邪恶的本性，骑着自己研发的飞行器去到处破坏、杀人。彼得化身的蜘蛛侠开始出击了！','With great power comes great responsibility.',139000000,821708551,82.502566,6.8,5265,121,'2002-05-01','en','/or6XJBVpcEbIkma0V9zshnbEtx4.jpg',4.064129218001811,3,'2026-09-10',2,NULL,NULL),(558,'蜘蛛侠2','Spider-Man 2','在根据经典漫威漫画英雄改编的蜘蛛侠系列第二部中，托比·马奎尔再度饰演性情温和的彼得·帕克，他正努力维持着大学生与超级英雄犯罪克星的双重身份间的微妙平衡。当蜘蛛侠遭遇由天才科学家奥托·奥克塔维斯（阿尔弗雷德·莫里纳 饰）化身而成的疯狂多触手反派“章鱼博士”时，这场妙趣横生的冒险之旅更加刺激，蜘蛛侠的生活也变得更加复杂。（索尼影业）','There\'s a hero in all of us.',200000000,783766341,35.149586,6.7,4321,127,'2004-06-25','en','/aGuvNAaaZuWXYQQ6N2v7DeuP6mB.jpg',3.8827098151105197,3,'2026-09-10',2,NULL,NULL),(559,'Spider-Man 3','Spider-Man 3','The seemingly invincible Spider-Man goes up against an all-new crop of villain – including the shape-shifting Sandman. While Spider-Man’s superpowers are altered by an alien organism, his alter ego, Peter Parker, deals with nemesis Eddie Brock and also gets caught up in a love triangle.','The battle within.',258000000,890871626,115.699814,5.9,3576,139,'2007-05-01','en','/qFmwhVUoUSXjkKRmca5yGDEXBIj.jpg',3.8218343819491287,3,'2026-09-10',2,NULL,NULL),(562,'虎胆龙威','Die Hard','警探约翰·麦卡伦从纽约来到洛杉矶，见他分别已有半年之久的妻子霍莉。他被邀请参加在一栋大厦的30层举行的圣诞晚会。然而一群匪徒却打起了大厦金库中存有的六亿多元公债券的主意。他们封锁了大楼，将参加晚会的人扣作人质。麦卡伦侥幸逃脱，只身与匪徒们展开了周旋。','40 Stories. Twelve Terrorists. One Cop.',28000000,140767956,66.169628,7.5,3948,131,'1988-07-15','en','/7Bjd8kfmDSOzpmhySpEhkUyK2oH.jpg',4.134555329744598,3,'2026-09-10',2,NULL,NULL),(563,'星河战队','Starship Troopers','高中生瑞科（卡斯帕·凡·迪恩 Casper Van Dien 饰）毕业后，在女友卡门（丹妮丝·理查兹 Denise Richards 饰）的鼓动下，违背了父亲的意志，加入了机械化步兵学院，卡门亦加入了海军学院。在他们参加训练不久后，地球遭到了来自外星球的昆虫袭击。瑞科的亲人均惨遭杀害，卡门将拍摄到的影像传送给了瑞科。悲愤交加的瑞科率领部下投入到了对抗外星昆虫的战斗中。然而，军队低估了这些昆虫的实力。在一次遭遇战中，10万军队惨遭杀戮，只剩瑞科、卡门等几人侥幸逃生。瑞科亲眼目睹了恐怖的杀戮场面，意外获知了这些昆虫变得如此聪明、强大的秘密。瑞科意识到必须制造更先进的武器才能对付这些昆虫，人类的反击开始了！','The only good bug is a dead bug.',105000000,121214377,58.782359,6.7,1560,129,'1997-11-06','en','/bY5IpMWmd5puJzpZQAXlYgmsBTk.jpg',3.6848800899248078,3,'2026-09-10',2,NULL,NULL),(568,'阿波罗13号','Apollo 13','1970年4月，太空船阿波罗13号正在执行登陆月球的任务，但控制中心忽然接获太空船在20万5千哩外传来的讯息——“休斯顿，我们出问题了！”这句话如洪水般扰乱了中心内所有科学家和工程师们的心，这是他们最不愿听到的消息。太空船已快接近月球了，然而在外太空中的一场爆炸，导致阿波罗13号失去氧气、动力还有导向功能。这一瞬间，三位太空人吉姆·洛维尔、佛瑞·德汉斯、杰克·史威吉特要面对前所未有的考验，他们必须把握仅有的4天时间重返地球，每分每秒对他们来说都显得弥足珍贵，除接受控制中心的指引外，其他的一切都得靠他们自己，他们不愿抛下妻儿成太空中的孤魂，勇气、信心及毅力支持着他们奋斗下去。','Houston, we have a problem.',52000000,355237933,68.140214,7.3,1599,140,'1995-06-30','en','/tVeKscCm2fY1xDXZk8PgnZ87h9S.jpg',3.8362180040313456,3,'2026-09-10',2,NULL,NULL),(573,'狂凶记','Frenzy','一名连环杀手用领带勒杀女性，伦敦警方锁定了嫌疑人，却错抓无辜，真凶仍在城市中游荡。','Just an ordinary necktie used with a deadly new twist.',3500000,12600000,10.219942,7.1,158,116,'1972-05-25','en','/4SFvqrlSigAt9tnhXFSMyKeJWQk.jpg',3.0106240191646,3,'2026-09-10',2,NULL,NULL),(576,'日落黄沙','The Wild Bunch','当“传统”的美国西部在周遭悄然消逝，一群上了年纪的亡命徒正试图干成最后一票。','If you only want to spend two hours in a movie theatre and go home and forget it, stay away from THE WILD BUNCH.',6244087,638641,14.970654,7.6,259,145,'1969-06-17','en','/4NiKQ5dDyCLpraV2IY3vkfd6rZK.jpg',3.192506509101366,3,'2026-09-10',2,NULL,NULL),(577,'不惜一切','To Die For','这部犀利颠覆（且惊人地具有预见性）的讽刺之作，将美国式名人崇拜的执念扭曲成一场恐怖喜剧，精准剖开我们这个被电视媒介支配、沉迷真实罪案的时代。妮可·基德曼迎来突破性演出，以邻家女孩式的气象播报员形象进行恶魔般解构——她阳光完美的表象下掩藏着谋杀之心，对名誉的残酷追逐将三名迷惘青年卷入一桩低俗不堪、足以登上小报头条的丑闻。格斯·范·桑特导演通过巧妙转换叙事视角、伪纪录片式访谈，以及华金·菲尼克斯、马特·狄龙、卡西·阿弗莱克等组成的出色配角阵容，为这部审视郊区社会病态的黑暗喜剧增添了层层耐人寻味的深意。[标准收藏]','All she wanted was a little attention.',20000000,21284514,12.309715,6.7,175,106,'1995-05-20','en','/woWEjoUaqbZvdqTuaY4kq6NBr13.jpg',3.018790962399447,3,'2026-09-10',2,NULL,NULL),(578,'大白鲨','Jaws','当海滨小镇艾米蒂遭遇一头危险大白鲨的袭击时，当地的警长（罗伊·谢德 饰）、一位年轻的海洋生物学家（理查德·德莱福斯 饰）与一位身经百战的老练鲨鱼猎人（罗伯特·肖 饰）联手展开殊死追捕，决心在这头猛兽再次发动攻击前将其消灭。','Don\'t go in the water.',7000000,470654000,50.152327,7.5,2542,124,'1975-06-18','en','/lxM6kqilAdpdhqUl2biYp5frUxE.jpg',3.974525870529609,3,'2026-09-10',2,NULL,NULL),(579,'大白鲨2','Jaws 2','影片故事背景一如上集，主要人物布迪警长亦由上集的罗伊·谢德扮演，但是今次出现肆虐艾密迪海滩的大白鲨，却是一条满含恨意，一心前来报“杀夫之仇”的母鲨。','Just when you thought it was safe to go back in the water...',20000000,187884007,19.636044,5.9,406,116,'1978-06-16','en','/wIEo1j92rPpW9x3fZwJgULqMmwh.jpg',3.1606051729826796,3,'2026-09-10',2,NULL,NULL),(580,'大白鲨4','Jaws: The Revenge','度假胜地阿米堤海滩曾多次有人被大白鲨侵袭，警长夫人艾伦对此心有余悸。多年后，其子西恩接替警长职位，他在一次出海巡逻中神秘失踪，显然是受到了大白鲨的侵袭，在艾伦悲痛之时，神秘的航海冒险家出现在她身边，于是他们一起联手对付大白鲨。','This time, it’s personal.',23000000,51881013,12.777008,3.5,224,89,'1987-07-17','en','/ebYw9tR0iqBzDGA6HVBhtd2xJM3.jpg',2.8547227942254385,3,'2026-09-10',2,NULL,NULL),(581,'Dances with Wolves','Dances with Wolves','Wounded Civil War soldier, John Dunbar tries to commit suicide – and becomes a hero instead. As a reward, he\'s assigned to his dream post, a remote junction on the Western frontier, and soon makes unlikely friends with the local Sioux tribe.','Inside everyone is a frontier waiting to be discovered.',22000000,424208848,45.707835,7.6,1046,181,'1990-11-09','en','/hw0ZEHAaTqTxSXGVwUFX7uvanSA.jpg',3.7111999835526817,3,'2026-09-10',2,NULL,NULL),(582,'窃听风暴','Das Leben der Anderen','1984年的东柏林，东德国家安全机构“史塔西”以严密的监控维持着对社会的控制。忠于体制的秘密警察格尔德·维斯勒上尉奉命监听著名剧作家格奥尔格·德莱曼及其女友、演员克里斯塔-玛丽亚·西兰的一举一动，希望从他们的生活中找到足以定罪的证据。然而随着监听不断深入，维斯勒逐渐被这个完全不同于自己的人生世界所吸引。爱情、艺术、思想与自由开始动摇他曾经坚信的一切，而一次原本普通的监视任务，也逐渐演变成一场关于忠诚、良知与选择的危险考验……','Before the Fall of the Berlin Wall, East Germany\'s Secret Police Listened to Your Secrets.',2000000,70000000,34.938177,7.9,958,137,'2006-03-15','de','/cVUDMnskSc01rdbyH0tLATTJUdP.jpg',3.7091031608123335,3,'2026-09-10',2,NULL,NULL),(584,'速度与激情2','2 Fast 2 Furious','迈阿密狡猾的商人卡特（科尔·豪瑟 Cole Hauser 饰）利用自己的贸易公司做幌子，暗中进行着国际洗钱活动。虽然 FBI 对他监视已久，但是卡特平日十分小心谨慎，几乎与世隔绝，所以一直没找到他的犯罪证据。FBI 获悉了卡特十分喜欢地下赛车，是当地飞车党的头目。为了获得他的犯罪证据，只好找上一集中成功破获洛杉矶飞车党劫车案的布莱恩（保罗·沃克 Paul Walker 饰）重新出山。布莱恩凭借出色的车技、和飞车党一起进行犯罪活动很快就赢得了卡特的信任。同时，另一名同为飞车党卧底的女警梦妮卡（伊娃·门德斯 Eva Mendes 饰）闯进了布莱恩的生活，布莱恩不知不觉中爱上了梦妮卡。梦妮卡已经获得了不少卡特的犯罪证据，但是她和卡特之间的暧昧关系却说不清道不明。','How Fast Do You Want It?',76000000,236350661,10.520961,6.2,2028,107,'2003-06-05','en','/2LnxGMd1dnUk3wZbVzdSGGIWUPA.jpg',3.530744548932171,3,'2026-09-10',2,NULL,NULL),(585,'怪兽电力公司','Monsters, Inc.','我们不知道，在那样的世界里住着那样一群怪物。他们长相滑稽，却必须装作狰狞。因为，在夜深的时候，他们要悄悄的出现在孩子的衣橱里，吓唬刚刚甜美睡去的宝宝。一切，只因为他们是怪物电力公司的员工，而孩子的尖叫，则是怪物王国发电的全部能量。怪物们害怕孩子，却又必须让孩子尖叫。在怪物的国度里，他们都是为全民造福的英雄。\r 　　毛怪苏利文（约翰•古德曼）是怪物公司最出色的员工，业绩总是摇摇领先，他吓哭的小孩儿不计其数。他与搭档大眼怪麦克（比利•克里斯托）很受大家的爱戴。一次偶然，毛怪不小心把一个两岁的小女孩阿布（玛丽•吉布斯）带回了怪物世界，引起了极大的恐慌，调皮可爱的阿布把这些可怕的怪物吓的人仰马翻。警方在追捕阿布，而坏蛋亨利（詹姆斯•柯博）也计划利用阿布进行他改革工厂的邪恶计划。\r 　　另一方面，在与阿布相处的过程中，毛怪渐渐对她产生莫名的情愫，甚至因此被放逐野外。可是一切都不能抵挡毛怪拯救女孩的信念，为了阿布，毛怪踏上了艰险的旅程……','We Scare Because We Care.',115000000,562816256,106.815545,7.5,5996,92,'2001-11-01','en','/wFSpyMsp7H0ttERbxY7Trlv8xry.jpg',4.337867575918209,3,'2026-09-10',2,NULL,NULL),(586,'摇尾狗','Wag the Dog','美国华盛顿特区。距离新一轮总统大选日期仅11天了，突然，一桩现任总统骚扰少女的丑闻被披露出来，闹得沸沸扬，这使总统谋求连任的计划受到巨大的威胁。紧要关头，经常奔走于各党派之间的神秘人物、总统的专职撰稿人康拉德布里恩博士被紧急召进白宫，与总统助理威妮弗里德弗姆斯及其他白宫宫员一起商讨对策。他们没一个关心这事是真是假，因为反正支持率肯定会下降，现在他们关心的是怎么把支持率再搞上去。','A comedy about truth, justice and other special effects.',15000000,64256513,13.581966,6.7,270,97,'1997-12-25','en','/kAwOj7t8ZeaniTFtLWVSKO79JxX.jpg',3.1289444678700953,3,'2026-09-10',2,NULL,NULL),(587,'大鱼','Big Fish','一个美丽的亲情童话。父亲爱德华年轻时，很爱给年幼的儿子讲自己的传奇经历，他自称在阿拉巴马旅行推销员时，经历过很多光怪陆离，魔幻荒诞的事情。威尔并不相信，觉得是父亲在虚荣和浮夸，父子关系渐渐疏离。直到父亲得了癌症，不久于人世了，儿子决定回去见父亲最后一面。儿子面对病榻上的父亲时，父亲又开始说他早年的经历：他曾经为了离开小村庄去大城市闯荡，在途中遇到巫婆和巨人，还一起去了幽灵庄，再后来，认识了一个神奇的马戏团演员，一个亚洲艺人，一条怎么也抓不到的大鱼，还有怎样跟母亲一见钟情，定下终身……从父亲病弱的气息里，威尔仿佛领悟到以前从来没有过的感受，也许父亲的叙述有修饰的成分，但在他的心中，那些经历到生命的最后一刻仍是充满激情和想象，而父亲终于在儿子的理解和深爱下闭上眼睛。','An adventure as big as life itself.',70000000,122919055,46.199482,7.6,1994,125,'2003-12-25','en','/tjK063yCgaBAluVU72rZ6PKPH2l.jpg',3.916107402307857,3,'2026-09-10',2,NULL,NULL),(588,'Silent Hill','Silent Hill','The eerie and deserted ghost town of Silent Hill draws a young mother desperate to find a cure for her only child\'s illness. Unable to accept the doctor\'s diagnosis that her daughter should be permanently institutionalized for psychiatric care, Rose flees with her child, heading for the abandoned town in search of answers – and ignoring the protests of her husband. It\'s soon clear this place is unlike anywhere she\'s ever been. It\'s smothered by fog, inhabited by a variety of strange beings and periodically overcome by a living \'darkness\' that literally transforms everything it touches. As Rose searches for her little girl, she begins to learn the history of the strange town and realizes that her daughter is just a pawn in a larger game.','We\'ve been expecting you.',50000000,97607453,32.927994,6.3,1067,125,'2006-04-21','en','/mIXGoXgnKObaSEyt10P6vUG3UTm.jpg',3.456691398002687,3,'2026-09-10',2,NULL,NULL),(590,'时时刻刻','The Hours','跨越时空的三个女人，因为一个名字被联系起来----戴罗薇夫人。  弗吉妮娅·伍尔芙(妮可·基德曼)，生活在上世纪20年代的伦敦郊区，正在完成她最后一部小说《戴罗薇夫人》。游走在虚构与现实生活边缘的她，承受着巨大的压力与被束缚感，内心甚至渴求着死亡。  劳拉·布朗(朱丽安·摩尔)，生活在二战末期的洛杉矶家庭主妇。《戴罗薇夫人》引起她不断追问自己，什么才是更有意义的生活？日复一日的持家生活同样让她萌生自杀的愿望。  克拉丽萨·沃甘(梅丽尔·斯特里普)，生活在90年代的纽约，正过着戴罗薇夫人式的生活。她深爱的朋友理查德，才华横溢却因艾滋病难以自理。好心的戴罗薇夫人担当起派对的主人，为每个人带来快乐，却难以化解内心的孤单与忧伤。  不同的时空里，她们的内心深处，关于死亡的挣扎与抗争，没有停息，时时刻刻。','The time to hide is over. The time to regret is gone. The time to live is now.',25000000,41597830,20.953265,7,451,114,'2002-12-27','en','/aF2vn9NtHDxG1Ovh0WcmC96GhUA.jpg',3.3110113992658228,3,'2026-09-10',2,NULL,NULL),(591,'达·芬奇密码','The Da Vinci Code','卢浮宫博物馆馆长被人杀害在卢浮宫内，临死前他费力的留下骇人的符号，从而惊动了符号专家罗伯特·兰登（汤姆·汉克斯）。在破案过程中，兰登结识了死者的孙女，索菲（奥黛丽·塔图），俩人几次遇险，九死一生，逐渐产生爱慕之情。随着案情的深入，他们渐渐发现这起谋杀案后隐藏着天大的秘密，甚至牵连到隐匿多年的神秘组织——峋山隐修会。兰登按图索骥，发现所有的解密的密码都藏在达芬奇的作品中，而最让人震惊的是，索菲的身世一时间随之复杂起来，她究竟是谁？峋山隐修会再现江湖想要达到什么目的？','Seek the truth.',125000000,767820459,45.313197,6.5,2704,149,'2006-05-17','en','/9ejKfNk0LBhSI9AahH4f9NJNZNM.jpg',3.74492419125649,3,'2026-09-10',2,NULL,NULL),(592,'窃听大阴谋','The Conversation','哈里・考尔（Gene Hackman 饰）是全美国最顶尖的窃听与录音专家，性格孤僻、极度内向、被宗教愧疚感折磨，一生只做一件事：用最精密的设备录下别人听不到的对话。\r 这次他接到一单机密任务：在旧金山联合广场，录下一对年轻男女的秘密谈话。他完美完成工作，却在反复听录音时，从模糊字句里听出阴谋、谋杀与杀机。\r 哈里本想 “只录音、不问事”，但良知与恐惧让他越陷越深。他开始偏执、焦虑、被幻觉与监视感吞噬，坚信自己手里的录音带会害死那对男女。最终，他以为自己阻止了悲剧，却落入一个完全反转、细思极恐的真相陷阱 ——他监听了世界，却从未能真正听懂那段对话。','Harry Caul is an invader of privacy. The best in the business.',1600000,4420000,20.810292,7.5,372,113,'1974-04-07','en','/dHqVBwcv1SGymOpUueRoKzcmdes.jpg',3.307873782948436,3,'2026-09-10',2,NULL,NULL),(593,'飞向太空','Солярис','地面控制中心持续收到来自索拉里斯空间站三名幸存宇航员的神秘信号。当宇航员兼心理学家克里斯·凯尔文被派往调查时，他遭遇了与空间站成员相同的奇异现象，由此踏上通往自我意识深处最黑暗角落的旅程。凭借本片，传奇俄罗斯导演安德烈·塔可夫斯基创造了一部极具独创性的科幻史诗，对爱、真理乃至人性本身的既有观念发起挑战。[标准收藏]',NULL,0,0,24.132271,7.7,357,167,'1972-03-20','ru','/huooRmB7yksJyVVSkqOgitxlCec.jpg',3.322475582966833,3,'2026-09-10',2,NULL,NULL),(594,'The Terminal','The Terminal','Viktor Navorski is a man without a country; his plane took off just as a coup d\'etat exploded in his homeland, leaving it in shambles, and now he\'s stranded at Kennedy Airport, where he\'s holding a passport that nobody recognizes. While quarantined in the transit lounge until authorities can figure out what to do with him, Viktor simply goes on living – and courts romance with a beautiful flight attendant.','Life is waiting.',60000000,219417255,57.753914,7,1910,128,'2004-06-17','en','/cPB3ZMM4UdsSAhNdS4c7ps5nypY.jpg',3.79905302589191,3,'2026-09-10',2,NULL,NULL),(595,'杀死一只知更鸟','To Kill a Mockingbird','在美国大萧条时期的南方，律师阿提克斯·芬奇为一名遭受不公正强奸指控的黑人男子辩护，同时亦保护着自己的孩子免受偏见侵蚀。影片通过孩子们的眼睛，见证父亲如何在充满种族偏见的法庭与社会中坚守正义与良知，成为一部关于勇气、尊严与成长的永恒经典。该片改编自哈珀·李的同名普利策奖小说，深刻影响了数代人对平等与公正的理解。',NULL,2000000,13129846,22.139842,8,657,129,'1962-12-25','en','/mbUce6BYRKMLBvQ7CHDzi9PqlqO.jpg',3.561979298336427,3,'2026-09-10',2,NULL,NULL),(597,'泰坦尼克号','Titanic','84 years later, a 101-year-old woman named Rose DeWitt Bukater tells the story to her granddaughter Lizzy Calvert, Brock Lovett, Lewis Bodine, Bobby Buell and Anatoly Mikailavich on the Keldysh about her life set in April 10th 1912, on a ship called Titanic when young Rose boards the departing ship with the upper-class passengers and her mother, Ruth DeWitt Bukater, and her fiancé, Caledon Hockley. Meanwhile, a drifter and artist named Jack Dawson and his best friend Fabrizio De Rossi win third-class tickets to the ship in a game. And she explains the whole story from departure until the death of Titanic on its first and last voyage April 15th, 1912 at 2:20 in the morning.','Nothing on Earth could come between them.',200000000,1845034188,100.025899,7.5,7562,194,'1997-11-18','en','/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg',4.381255342273006,3,'2026-09-10',2,NULL,NULL),(598,'上帝之城','Cidade de Deus','巴西里约热内卢的贫民窟，这里是“上帝之城”，更是魔鬼也会叹息着转身的地方。\r 阿炮带着我们到了这里，他见证了这里二十多年来被残暴、贪婪、复仇、野心、背叛、掠夺所裹挟的混乱生活以及最终导致的一场灾难性的黑帮争斗。虽然从小就要 辗转于匪徒间求生存，但胆小怕事的性格与自我保护的本能却使他一直能平安度日。\r 60年代初，阿毛、阿夹和阿呆是这里的“少年三侠”，在抢劫完旅馆之后，他们三人分道扬镳，阿夹重回上帝的怀抱，而阿呆和阿毛纷纷付出了生命的代价。\r 70年，当年“少年三侠”手下的小弟小豆子靠着自己的心狠手辣，不停地吞并别人的地盘，成为了贫民区的“小霸王”，生意也从抢劫升级到了更为暴利的毒品买卖，和他一起飞黄腾达的还有班尼。\r 班尼认识了美丽的安迪丽卡，准备归隐，在送别的晚会上，他意外被对头杀害，悲痛之下，“小霸王”集合人手给班尼报仇，帮派之间的厮杀就此开始。\r 此时的阿炮，机缘巧合下成为了杂志社的见习摄影师，他的相机，照下的却是孩子们持枪荷弹的狰狞，和帮派间无休无止的仇杀。','',3300000,30641770,20.7395,8.429,1814,130,'2002-08-30','pt','/AhTemxbjHVkf456eEGxKK333xfr.jpg',4.006410937128627,3,'2026-09-10',2,NULL,NULL),(601,'E.T.外星人','E.T. the Extra-Terrestrial','当一个充满想象力的男孩遇见迷路的外星人，一段影史上最令人珍视的友谊就此展开——埃利奥特帮助这个被他称为E.T.的奇妙生物，在政府人员找到他之前，踏上回家的路。','He is afraid. He is alone. He is three million light years from home.',10500000,792910554,56.105798,7.3,3269,115,'1982-04-03','en','/an0nD6uq6byfxXCfk6lQBzdL2J1.jpg',4.010518927163999,3,'2026-09-10',2,NULL,NULL),(602,'独立日','Independence Day','未来某年的7月2日，美国各地的监视站发现一艘巨大飞船接近了地球。飞船发出的无线电信号干扰了地球的通信卫星信号，并放出了多艘直径达15英里的子飞船飞抵地球上各大城市的上空。外星飞船敌友未明，电脑工程师戴维破译出外星人发出的无线电信号，但是为时已晚，7月3日，外星人的飞船开始攻击地球，人类文明瞬间遭到巨大的打击和灾难。总统等人撤离到军事基地，指挥空军反击，却犹如以卵击石，毫无作用，军事基地也被摧毁，唯有飞行员史蒂文设法诱使一架外星人战斗飞艇坠毁。幸存者们逃到了秘密军事基地，在那里，科学家们一直在研究一艘50多年前坠毁的外星飞艇，致力于找出对付外星人的办法，那里也是人类最后的希望……','Earth. Take a good look. It might be your last.',75000000,816969268,60.442593,6.7,3260,145,'1996-06-25','en','/p0BPQGSPoSa8Ml0DAf2mB2kCU0R.jpg',3.872554521814666,3,'2026-09-10',2,NULL,NULL),(603,'黑客帝国','The Matrix','不久的将来，网络黑客尼奥对这个看似正常的现实世界产生了怀疑。他结识了黑客崔妮蒂，并见到了黑客组织的首领墨菲斯。墨菲斯告诉他，现实世界其实是由一个名叫“母体”的计算机人工智能系统控制，人们就像他们饲养的动物，没有自由和思想，而尼奥就是能够拯救人类的救世主。可是，救赎之路从来都不会一帆风顺，到底哪里才是真实的世界？如何才能打败那些超人一样的特勤？尼奥是不是人类的希望？这是黑客的帝国，程序和代码欢迎大家的到来。','Welcome to the Real World.',63000000,463517383,104.309993,7.9,8907,136,'1999-03-30','en','/aOIuZAjPaRIE6CMzbazvcHuHXDc.jpg',4.5426170570131355,3,'2026-09-10',2,NULL,NULL),(604,'黑客帝国2：重装上阵','The Matrix Reloaded','上一部结尾，尼奥终于意识到自己的能力和使命，中弹复活后，变成了无所不能的“救世主”，他和女友崔妮蒂，舰长墨菲斯回到了人类的基地锡安，受到人们的热烈欢迎。此时，“母体”决定先下手为强，派出了两万五千只电子乌贼攻击锡安基地；墨菲斯、尼奥和崔妮蒂则再次进入“母体”，寻找“制钥者”，准备从内部破坏；而本该被尼奥消灭的特勤史密斯似乎出了点问题，脱离了“母体”的控制，拥有可怕的复制能力，阻碍尼奥他们的行动。','Free your mind.',150000000,738599701,70.78591,6.7,3443,138,'2003-05-15','en','/aA5qHS0FbSXO8PxcxUIHbDrJyuh.jpg',3.9094487571017993,3,'2026-09-10',2,NULL,NULL),(605,'黑客帝国3：矩阵革命','The Matrix Revolutions','在前一部中，尼奥没有能从摧毁内部“母体”，他的身体在真实世界的飞船上陷于昏迷，思想却被困在介于“母体”和真实世界的中间地带，这个地方由“火车人”控制。墨菲斯和崔妮蒂等人知道了尼奥的情况，在守护天使的带领下，找到了“火车人”的控制者梅罗纹加，经过一番激斗，将尼奥救了出来。此时，电子乌贼部队对锡安发起了猛烈的攻击，人类组织所有机甲战士展开顽强的抵抗，形势危在旦夕。尼奥和崔妮蒂驾驶了一艘飞船克服重重困难，到达机器城市，尼奥终于见到了机器世界的统治者“机器大帝”，双方谈判并达成了协议：尼奥除掉不受“母体”控制的史密斯，以换取锡安的和平。在“母体”中，尼奥和史密斯展开了关系人类生死存亡的最后决斗。','Everything that has a beginning has an end.',150000000,424988211,73.313918,6.4,3096,129,'2003-11-05','en','/qEWiBXJGXK28jGBAm8oFKKTB0WD.jpg',3.816512349361012,3,'2026-09-10',2,NULL,NULL),(606,'走出非洲','Out of Africa','凯伦（梅丽尔·斯特里普 Meryl Streep 饰）是一个爱慕虚荣的富家女，为了得到一个男爵夫人的称号她离开故土丹麦远嫁东非肯尼亚，然而男爵夫人的称号并没有给凯伦带来美满的婚姻生活。幸运的是在那片广袤的土地上，凯伦可以经常外出打猎、探险，她渐渐的爱上了这片神奇的土地。在一次打猎遇险时，凯伦邂逅了年青的英国贵族邓尼斯（罗伯特·雷德福 Robert Redford 饰）。在遭遇婚姻的破裂和丈夫出走之后，凯伦独立承担起经营庄园的任务，在劳动的过程中，凯伦渐渐的与种植园里的仆人们产生了深厚友谊，而她与邓尼斯的关系似乎也有了进展。然尔命运之神并没有从此让凯伦一帆风顺，一次大火让她不得不出卖庄园从而缓解经济的拮据，后来邓尼斯驾机意外身亡又一次给了她沉重的打击。在经历了生命的磨炼之后，凯伦最终告别了那片她洒下青春和热情的土地……\r 　　该片在1986年的第58届奥斯卡上荣获了包括最佳影片、最佳导演、最佳改编剧本在内6项大奖。','Based on a true story.',31000000,128499205,13.864975,7,279,161,'1985-12-20','en','/iiVbSzeITmxri9nhqWCJHTMpzMZ.jpg',3.162758628133376,3,'2026-09-10',2,NULL,NULL),(607,'黑衣人','Men in Black','地球并不只是人类的天下，其实有1500名外星人生活中我们当中，而星际移民局则处理和外星人相关的事情。纽约普通警察爱德华兹（威尔•史密斯 饰）因缘际会之下加入了这一组织，成为MIB的一员，代号J，从此没有名字、没有身份，成为特警K（汤姆•李；琼斯 饰）的搭档。J应对的第一起事件就是虫族的入侵。亚基伦王子罗斯伯在地球被虫族杀害，而他随身携带的“银河系”——宇宙次原子能源的最好来源也失踪了，若虫族找到，将给亚基伦人带来毁灭性的打击；亚基伦人发出最后通牒，如果地球人不能在一个小时之内交出“银河系”，他们就摧毁地球。为了地球的安全，K和J不得不挺身而出。','Protecting the Earth from the scum of the universe.',90000000,589390539,104.121555,6.9,4412,98,'1997-07-02','en','/uLOmOF5IzWoyrgIF5MfUnh5pa1X.jpg',4.096727606093204,3,'2026-09-10',2,NULL,NULL),(608,'Men in Black II','Men in Black II','Kay and Jay reunite to provide our best, last and only line of defense against a sinister seductress who levels the toughest challenge yet to the MIB\'s untarnished mission statement – protecting Earth from the scum of the universe. It\'s been four years since the alien-seeking agents averted an intergalactic disaster of epic proportions. Now it\'s a race against the clock as Jay must convince Kay – who not only has absolutely no memory of his time spent with the MIB, but is also the only living person left with the expertise to save the galaxy – to reunite with the MIB before the earth submits to ultimate destruction.','Same Planet. New Scum.',140000000,441818803,91.332849,6,3114,88,'2002-07-03','en','/enA22EPyzc2WQ1VVyY7zxresQQr.jpg',3.7617555354535184,3,'2026-09-10',2,NULL,NULL),(609,'鬼驱人','Poltergeist','事业有成、意气风发的史蒂文•弗瑞林（Craig T. Nelson 饰）带着妻子戴安（JoBeth Williams 饰）和三个孩子搬进了加利福尼亚某郊外社区。但在入住不久，怪事便频繁发生。先是小女儿卡萝（Heather O\'Rourke 饰）梦游，对着自动开启漫屏雪花的电视机自言自语。接着便又不明物体从电视机中飘出，莫名的地震，破碎的玻璃杯……如此种种，搅得弗瑞林一家坐卧不定。过了不久，恐怖事件逐渐升级，卡萝最终竟被拉入电视机中……','They\'re here.',10700000,122200000,36.230204,7,794,114,'1982-06-04','en','/gKiJwqXJP8F9SuypDUXySHe7FUt.jpg',3.505564541656467,3,'2026-09-10',2,NULL,NULL),(612,'慕尼黑','Munich','这是一部关于政治、复仇的真实的电影。1972年在联邦德国举办的第20届奥运会上，巴勒斯坦的极端恐怖组织“黑色九月”闯进了奥运村绑架了11名以色列运动员，以此要挟以色列释放被关押的该组织成员。  　　联邦德国的警察草率对待了这次绑架事件，他们直接冲进了恐怖组织的巢穴企图武装营救人质，熟料导致了11名以色列运动员全部遇难!  　　事件发生之后，以色列“摩萨德”高层迅速训练了一批特工，展开了对“黑色九月”组织以及相关的巴勒斯坦人长达一个世纪的血腥报复……','The world was watching in 1972 as 11 Israeli athletes were murdered at the Munich Olympics. This is the story of what happened next.',70000000,130358911,29.035222,6.9,696,164,'2005-12-22','en','/wzsmwEBKSNrYrXcmYR4AZZj6Gvs.jpg',3.4371407284315483,3,'2026-09-10',2,NULL,NULL),(613,'帝国的毁灭','Der Untergang','1945年4月，第二次世界大战接近尾声，苏联红军攻入柏林，第三帝国已濒临覆灭。希特勒与爱娃·布劳恩以及一众军政高层躲进柏林地下掩体，仍试图在不断恶化的战局中作出最后的挣扎。随着德军防线接连崩溃、命令无法执行，地堡中的希望逐渐被绝望取代，而地面上的柏林也陷入战火与混乱。影片通过希特勒生命最后十二天以及身边追随者、士兵和普通人的经历，展现纳粹德国走向最后崩溃的过程……','April 1945, a nation awaits its...Downfall',18339750,92180910,32.445895,7.7,1037,156,'2004-09-08','de','/cP1ElGjBhbZAAqmueXjHDKlSwiP.jpg',3.695720374464839,3,'2026-09-10',2,NULL,NULL),(615,'耶稣受难记','The Passion of the Christ','耶稣(詹姆斯·卡维泽 James Caviezel饰)拒绝了魔鬼的诱惑，受到了犹大的出卖。他被罗马人带到了罗马政权主持者比拉多那里。比拉多本来不想处死耶稣——他明知这样会引起一场政治风波。于是，他让希律王建议如何决断这件事。 　　希律王把耶稣的命运交到了人们手上。但是，愚蠢的民众宁愿放过罪犯，也不能容忍耶稣逃过刑罚。受尽苦难的耶稣还远远不能满足人们的愿望。他们要把耶稣推上绞刑架。 　　比拉多顺从民意，耶稣走往执行绞刑的山头。一路上，人们疯狂的往他身上扔杂物，耶稣受难日成为民众狂欢日。 　　耶稣的双手被钉在十字架上，这时还没有人意识到这一幕永远被后世铭记。','By his wounds, we were healed.',30000000,611899420,38.171417,6.9,864,127,'2004-02-25','en','/o4TwGNMcS3bRCovOfksrvlfME8L.jpg',3.517645323924476,3,'2026-09-10',2,NULL,NULL),(616,'最后的武士','The Last Samurai','1865年，美国内战结束。但战士的心却无法安宁，在随即而来的大规模西进运动中，刚刚从内战硝烟中幸存下来的白人士兵，又被带到了击杀印第安人的第一线。 上尉纳森.欧格仁在战争中见证了过多的鲜血与暴力，以至于迷失了自己的灵魂；特别是看到上级军官——上校本杰明巴格利屠杀印第安人时，他更感到作为战士的荣誉感消失殆尽。在义勇与牺牲精神被新时代的功利与自私主义代替时，沉浸在往日光荣梦想中的纳森.欧格仁只能整日借酒浇愁。\r 一个偶然的机会，纳森.欧格仁被推荐给来自大洋对岸的新成立的明治政府代表，去给日本训练第一支现代化军队。消沉的纳森.欧格仁觉得这个工作不错，至少他还可能像个真正的战士一样死在战场上。  纳森.欧格仁所训练的军队第一个要对付的，就是妄图阻挡现代化进程的顽固武士集团。在一场浓雾中的激战后，不仅天皇的现代化军队被击败，连教官艾尔格兰本人也被武士们俘虏。尽管在搏斗中他杀死了围攻他的一名武士，但并没有得到料想中的速死。相反，武士集团首领胜元生擒了他，并派自己的妹妹多香照顾他；而多香的丈夫，正是被纳森.欧格仁杀死的武士……\r 身处武士及其家属聚居的村落里，纳森.欧格仁竟然发现自己居然不由自主地爱上了武士文化，从武士道的精神与肉体修炼中，他似乎又找到了一个战士应有的荣誉感。同时，在多丽子的悉心照料下，似乎有某种微妙的感情在他们之间产生。然而，历史的车轮是不可逆转的，明治政府自然不会放弃现代化进程，武士与天皇军队之间终有一战。已经为武士道深深着迷的纳森.欧格仁该何去何从？','In the face of an enemy, in the heart of one man, lies the soul of a warrior.',140000000,456758981,52.341226,7.3,1895,154,'2003-12-05','en','/a8jmJPs5eZBARmnuEEvZwbjwyz4.jpg',3.849568262519676,3,'2026-09-10',2,NULL,NULL),(617,'玩尽杀绝','Wild Things','这是一局环环紧扣的阴谋游戏。小镇上的中学教师萨姆（马特•狄龙 Matt Dillon 饰）这天为学生作完性主题的犯罪演讲后，女学生凯莉就溜进了他的房间，面对青春迷人的凯莉（丹妮丝•理查兹 Denise Richards 饰），萨姆惊得目瞪口呆。这一幕被凯莉的母亲桑德拉（泰莉莎•拉塞尔 Theresa Russell 饰）撞见了，她此前曾和萨姆有过风流的一夜。醋意大发的桑德拉以学校捐助人的身份要求校长将萨姆解职，萨姆因此糊里糊涂丢掉了工作。屋漏偏逢连夜雨，小镇上的一名女学生苏茜（内芙•坎贝尔 Neve Campbell 饰）突然控告萨姆强奸了自己，桑德拉出资聘请了有名的大律师状告萨姆。身无分文的萨姆请不起律师，虽然有贪财的保险人博登在庭上帮他辩护，但面对对方的资深律师，法庭的形势对萨姆十分不利。然而此时，事态有了新的转折！','They\'re dying to play with you.',20000000,67200000,25.041992,6.3,444,108,'1998-03-20','en','/tVQgBwAgUT9Y1nd8uNcDJSjpBVG.jpg',3.236452868597884,3,'2026-09-10',2,NULL,NULL),(619,'保镖','The Bodyguard','已退职的特工弗兰克始终无法忘记在一次枪战中的痛苦经历。著名黑人女歌星梅伦的经纪人狄克请他去做梅伦的保镖。弗兰克本想拒绝，但看到梅伦5岁大的孩子×时，他终于答应了。  　　梅伦家中还住着她姐姐妮基和保镖托尼。他们经常收到恐吓信，但梅伦却并不知情。弗兰克来到后加强了家中的防护措施，但梅伦对他并无好感。一次汽车跟踪事件使弗兰克确定海伦的生命确实正受到威胁，而梅伦也由此逐渐改变了对他的看法。在演唱会上，梅伦终于发现了恐吓信，狄克只好对她讲了实情。梅伦被歌迷冲下了舞台，多亏弗兰克及时相救才避免了灾难的发生。  　　梅伦为了答谢弗兰克而邀请他共进晚餐。两人在舞曲中渐渐陶醉。 梅伦难以抑制心中的×，与弗兰克发生了密切的关系。梅伦感到在弗兰克身边有一种安全感。但第二天弗兰克却觉得不该和客户发生感情，两人的关系一下子疏远了。为了报复弗兰克，梅伦甚至与弗兰克的旧同事鲍曼假装亲热，使弗兰克颇为不快。　　在乡村别墅，弗兰克又一次救了梅伦。他开始感到妮基有问题。在逼问下，妮基终于承认是她雇了杀手想杀梅伦。杀手潜入房间，但却将妮基误认为梅伦而加以杀害。  　　梅伦将要出席金像奖的颁奖晚会。弗兰克知道杀手一定会乘机下手，叮嘱梅伦要大胆小心。就在梅伦登上舞台时，弗兰克忽然发现了伪装成摄影师的鲍曼，他顿时明白了一切。弗兰克冲上舞台救下了梅伦，自己却中枪倒地。他挣扎着击毙了鲍曼，随即失去了知觉。  　　梅伦安全了。弗兰克送她登上飞机去作巡回演出，他已不再是梅伦的保镖。经过心中的激烈斗争，梅伦终于在飞机起飞前的最后一刻跑下了飞机。在风中，梅伦与弗兰克紧紧拥吻在一起。','Never let her out of your sight. Never let your guard down. Never fall in love.',25000000,411006740,26.576385,6.1,661,129,'1992-11-25','en','/dkZnQibVvyHLS3rX2pDYZHsIrWv.jpg',3.303117661874859,3,'2026-09-10',2,NULL,NULL),(621,'油脂','Grease','由美国派拉蒙影片公司出品，导演兰德尔．克莱泽。澳大利亚姑娘珊迪．奥森爱上了学校“硬汉帮”的头头丹尼，为了能和他配对，原本端庄稳重的珊迪变得赶时髦潮流，也故意和全校有名的漂亮运动员约会。这样丹尼出于嫉妒又来追求珊迪。本片有很多歌舞场面，男女主角也唱了不少新老流行歌曲。成为1978年入夏以来美国影坛上又一部轰动的影片。','Grease is the word',6000000,181813770,67.608041,7.2,1581,110,'1978-07-07','en','/2rM7fQKpb7cs1Iq7IBqub9LFDzJ.jpg',3.8111391833783714,3,'2026-09-10',2,NULL,NULL),(622,'第九道门','The Ninth Gate','卡索(约翰尼·德普 Johnny Depp 饰)着迷于收藏离奇古怪的珍稀书籍。这种才华令富翁巴尔坎（弗兰克·兰格拉 Frank Langella 饰）大为赏识。他派给卡索一个艰巨的任务——寻找一本叫《第九道门》的古书，并鉴定他手中那本的真假。这本书在世界上仅存3本，剩下的两本，分别流落到了葡萄牙和法国。 　　传说，只要通读此书，就可以召唤魔鬼的到来。卡索开始了曲折而又魔幻的寻找历程。他探访了书的原主人之妻、古籍修缮专家、遇上绿眼珠的神秘女人，期间他朋友的暴毙竟然跟书里的插图如出一辙，命案还在连连上演。原来，书中所带的咒语，恐怕会使得拥有者无一幸免。而如果三本书合在了一起，就会迎来邪恶的撒旦。而到底最终魔鬼的脸有没有出现？','Every book has a life of its own.',38000000,58401898,30.359164,6.3,756,133,'1999-08-24','en','/jKGHGL2Uyq1FPgXPYYtCqHBMGni.jpg',3.3713074887244314,3,'2026-09-10',2,NULL,NULL),(627,'猜火车','Trainspotting','如一剂直击1990年代英国电影心脏的肾上腺素，这部改编自欧文·威尔士小说的黑色幽默作品，是导演丹尼·博伊尔、制片人安德鲁·麦克唐纳与编剧约翰·霍奇的重要突破。凭借通电般的能量与风格化的胆识，本片跃动穿梭于苏格兰海洛因成瘾者马克·雷顿（伊万·麦克格雷格 饰）的生活与时代——他与一群格格不入的伙伴一起，时而沉溺毒海，时而惹上麻烦，时而尝试清醒，时而又重蹈覆辙，一切只为逃离现代生存的平庸。影片以电子乐、摇滚与英伦流行金曲组成的标志性原声带为节奏，进行着动态剪辑，这部独立电影现象之作，选择了生命全部丑陋、美丽、骇人又振奋的面貌。[标准收藏]','Choose life.',4000000,16491080,63.513324,7.8,2655,93,'1996-02-23','en','/1jUC02qsqS2NxBMFarbIhcQtazV.jpg',4.088205632208619,3,'2026-09-10',2,NULL,NULL),(628,'夜访吸血鬼','Interview with the Vampire','18世纪的路易斯安娜州，丧失妻女痛不欲生的庄园主路易（布拉德·皮特 饰）遇上了吸血鬼莱斯塔特（汤姆·克鲁斯 饰），被其施法变成吸血鬼。路易心存人性，不愿意吸血杀人，靠吸食动物的血为生，而莱斯塔特则一心要把路易斯教导成一个真正的吸血同类。在新奥尔良，路易禁不起诱惑吸了小女孩克萝迪娅（克尔斯滕·邓斯特 饰）的血，而莱斯塔特则不顾路易斯的反对把克萝迪娅也变成了吸血鬼。三个人组成了一个奇特的家庭。几十年过去了，克萝迪娅开始怨恨莱斯塔特剥夺了他真正的人生，她设计杀死了莱斯塔特，和路易周游世界，过着既像父女、又像情人的生活，寻找同类，也寻找着自身存在的意义。在巴黎，他们遇上了以阿蒙（安东尼奥·班德拉斯 饰）为首的一群吸血鬼，聚居在剧院地下，过着和他们迥然不同的生活，阿蒙给了路易许多教导，想成为路易的新伙伴，为此，路易和克萝迪娅之间出现了裂痕，最终，酿成了无可挽回的悲剧。1988年，路易斯返回了新奥尔良，向一个年轻记者马洛伊（克里斯琴·斯莱特 饰）讲述了自己的经历，讲述了吸血鬼长生不死背后的哀伤，不料，马洛伊在听完之后却被深深地吸引，一个新的吸血鬼的故事，将由此开始。','Drink from me and live forever',60000000,223664608,50.163785,7.2,1516,123,'1994-11-11','en','/t7NU8IcmcNBrlunCxiycX9JV7Rp.jpg',3.7592027474423015,3,'2026-09-10',2,NULL,NULL),(629,'非常嫌疑犯','The Usual Suspects','Held in an L.A. interrogation room, Verbal Kint attempts to convince the feds that a mythic crime lord, Keyser Soze, not only exists, but was also responsible for drawing him and his four partners into a multi-million dollar heist that ended with an explosion in San Pedro harbor – leaving few survivors. Verbal lures his interrogators with an incredible story of the crime lord\'s almost supernatural prowess.','Five Criminals. One Line Up. No Coincidence.',6000000,23341568,64.025031,8.1,3254,106,'1995-07-19','en','/99X2SgyFunJFXGAYnDv3sb9pnUD.jpg',4.2234664980137415,3,'2026-09-10',2,NULL,NULL),(630,'绿野仙踪','The Wizard of Oz','改编自L·弗兰克·鲍姆永恒的儿童童话，讲述一位堪萨斯女孩跨越彩虹的旅程。','We\'re off to see the Wizard, the wonderful Wizard of Oz!',2777000,33754967,67.417542,7.4,1642,102,'1939-08-15','en','/uCC3j4pV9eOZwzDUWp2ilbcTf1f.jpg',3.8631295101442147,3,'2026-09-10',2,NULL,NULL),(634,'BJ单身日记','Bridget Jones\'s Diary','布里奇特•琼斯（蕾妮•齐维格 饰）是一个32岁的单身女子。她的工作及生活都是平淡无奇的，她唯一想得到一份真挚的爱情，就算有一众好友在身边及时安慰，布里奇特还是没有好过点。新的一年里，她要过一种新的生活。她选择用日记把自己生活里的点点滴滴都记录下来，她开始变得喜悦起来。\r 　　这时在她与风流倜傥的上司丹尼尔•克里弗（休•格兰特 饰）产生了感情，丹尼尔原来早与女友订婚，使布里奇特伤心不已。高傲却真实的马克•达西（科林•菲尔斯 饰）也表示对她的爱慕之情。布里奇特周旋在两个男人之间，不知如何选择。','Health Warning: Adopting Bridget\'s lifestyle could seriously damage your health.',25000000,281929795,35.310712,6.5,1356,97,'2001-04-13','en','/k4HbmnGkycnWjbigALN6hdNkkWi.jpg',3.556332833358277,3,'2026-09-10',2,NULL,NULL),(639,'当哈利遇到莎莉','When Harry Met Sally...','大学毕业后，莎莉（梅格·瑞恩 Meg Ryan 饰）开车载哈利（比利·克里斯托 Billy Crystal 饰）前往纽约，二人聊得并不愉快。哈里认为男女之间不可能有真正的友谊，萨莉却不以为然，于是不欢而散。5年后，二人又在飞机上巧遇，这时他们都有了意中人，但观点却没有改变，再次不欢而散。当又有一个5年后，二人再度重逢，都因感情出现了危机而有了共同语言。他们彼此安慰，临睡前通话，共度圣诞，为对方的感情出谋划策，哈利与莎莉有着不可言喻的默契。然而，这真的是一段伟大友谊的开始吗？','Can two friends sleep together and still love each other in the morning?',16000000,92823546,18.430419,7.3,950,96,'1989-07-21','en','/mb2b04MAjem65yy8CXe2O3jWNKp.jpg',3.5665923016226397,3,'2026-09-10',2,NULL,NULL),(640,'猫鼠游戏','Catch Me If You Can','父母婚姻破裂后，尚未成年的弗兰克·阿巴内尔离家出走，并凭借过人的伪装能力和伪造支票的手段四处行骗。他先后冒充飞行员、医生和律师，在不同身份之间游刃有余，并骗取了数百万美元。与此同时，FBI探员卡尔·汉拉蒂逐渐锁定了这个年轻而狡猾的骗子，并对他展开锲而不舍的追捕。一次次逃脱与追踪之间，两人由此展开了一场旷日持久的“猫鼠游戏”……','The true story of a real fake.',52000000,352114312,73.944049,7.7,3795,141,'2002-12-25','en','/ctjEj2xM32OvBXCq8zAdK3ZrsAj.jpg',4.19187818172925,3,'2026-09-10',2,NULL,NULL),(641,'梦之安魂曲','Requiem for a Dream','哈瑞和玛丽安彼此相爱，梦想着开个服装店，梦想着有个美好的明天。然而他们都离不开毒品，并想着以销毒赚得第一桶金。哈瑞的母亲是个彻底的电视迷，最大的梦想是上电视，为此不顾年迈吞食减肥药。由于药品里的毒品成分，她渐渐上了瘾。哈瑞的朋友狄龙同样是个瘾君子，为了挣大钱加入了黑社会。为了梦想，他们努力着，却一步步深陷毒品难以自拔。\r 哈瑞的胳膊因注射毒品感染而被割去；玛丽安为了毒品出卖肉体和自尊；哈瑞的母亲最终住进了精神病院受尽折磨；狄龙锒铛入狱。当视线变得模糊，梦在遥远处呼唤，迷失的人该以怎样的姿态安抚自己的灵魂。',NULL,4500000,7390108,11.573034,7.9,2443,102,'2000-10-27','en','/9BTwsLaMVHOGFlmsSlx5QYCaXb.jpg',3.9673244788812143,3,'2026-09-10',2,NULL,NULL),(642,'虎豹小霸王','Butch Cassidy and the Sundance Kid','19世纪末，威名四震的“虎豹小霸王”布奇（保罗·纽曼 Paul Newman 饰）与搭档太阳舞小子（罗伯特·雷德福 Robert Redford 饰）在美国西部的一个小镇上四处抢劫银行，与对手凶残搏杀，与警察机智周旋。一次，两人抢劫“飞人”公司邮车，引来警长与当地居民的追捕。但他俩依旧我行我素，抢占强占了女教师埃塔（凯瑟琳·罗斯 Katharine Ross 饰），逍遥自在地过着快乐时光。当他们再次抢劫“飞人”邮车后，招来一队骑警，对他们紧追不舍，展开天罗地网的搜捕，迫使布奇和太阳舞小子展开了逃亡之路。从悬崖跳下逃命的两人找到埃塔，商议去玻利维亚谋生。在异国他乡，他们尝试金盆洗手走上正道，终究还是认为这种生活不适合他们，于是重操旧业。埃塔一气之下，抛下他们重回美国。他们在一座小镇不慎暴露身份，被追捕的警察重重包围。前有拦截，后有追兵，虎豹小霸王是否能够在重重夹击之下浴火重生？\r 　　本片获得第42届奥斯卡最佳原创剧本奖、最佳摄影奖、最佳原创歌曲奖、最佳配乐奖等。','Not that it matters, but most of it is true.',6000000,102308889,24.499996,7.4,650,110,'1969-09-23','en','/cjTARCnSgsOu2LojTsXtvIeIYRh.jpg',3.478656931646739,3,'2026-09-10',2,NULL,NULL),(644,'人工智能','A.I. Artificial Intelligence','21世纪中期，由于气候变暖，南北两极冰盖的融化，地球上很多城市都被淹没在了一片汪洋之中。此时，人类的科学技术已经达到了相当高的水平，人工智能机器人就是人类发明出来的用以应对恶劣自然环境的科技手段之一。先进的人工智能机器人不但拥有可以乱真的人类外表，而且还能像人类一样感知自己的存在。大卫（海利·乔·奥斯蒙特 饰）就是这样一个有思想、有感情的小孩机器人，他被一对人类父母莫妮卡和亨利所收养，但他始终不是真人。由于种种原因，莫妮卡还是将大卫留在郊外（为了使大卫不被销毁），所以他一直渴望着自己终有一天不再仅仅是个机器人。抱着对这个愿望的执着，大卫踏上了漫长的寻找蓝仙女的旅程，途中遇到了被追杀的善良的机器人乔（裘德·洛 饰）。谁也不知道他们能否完成自己的心愿成为真正的人，得到真正的爱。','David is 11 years old. He weighs 60 pounds. He is 4 feet, 6 inches tall. He has brown hair. His love is real. But he is not.',100000000,235926552,34.035114,6.8,1974,146,'2001-06-29','en','/wnUAcUrMRGPPZUDroLeZhSjLkuu.jpg',3.7099412324021737,3,'2026-09-10',2,NULL,NULL),(646,'007：诺博士','Dr. No','本片取材于伊安·佛莱明的作品，是007电影系列的第一部。故事讲述英国秘密情报局特工詹姆斯·邦德（代号007）到牙买加侦查凶案，却发现野心家建有核子基地以图不轨，于是他凭着自己的机智将基地加以摧毁的故事。','NOW meet the most extraordinary gentleman spy in all fiction!',950000,59600000,48.901542,6.9,940,110,'1962-10-04','en','/4DIFOE3255payWKIaBnTcU6Adzb.jpg',3.565363841627016,3,'2026-09-10',2,NULL,NULL),(650,'街区男孩','Boyz n the Hood','在美国西部的黑人街区中，暴力与犯罪几乎随时都在发生，街上闲晃的青年与草丛里发臭的尸体点缀着小学生提瑞·斯代尔每天与伙伴们的生活，提瑞性格多话好胜，在课堂上与同学大打出手，为了他的教育问题，母亲将提瑞送到了前夫福瑞斯（劳伦斯·菲什伯恩 Laurence Fishburne 饰）那里，父亲有着强悍的个性，提瑞在他的引导下成长着……七年之后，提瑞（小库珀·古丁 Cuba Gooding Jr 饰）已是一名青年，黑人街区的混乱状况并没有改善，提瑞和他的朋友们卷入了宿命般的街头仇杀中……  　　本片编导约翰·辛格顿以23岁之龄获得奥斯卡最佳导演提名，保持着最年轻获提名导演的纪录。 ©豆瓣','Once upon a time in South Central L.A... It ain\'t no fairy tale.',6500000,57504069,17.705671,7.4,364,112,'1991-07-12','en','/kaS8BkTZESnkoB5i1zRQ02FIRGk.jpg',3.2840605406931744,3,'2026-09-10',2,NULL,NULL),(652,'特洛伊','Troy','特洛伊王子帕里斯掳走斯巴达王后海伦，二人的恋情引发特洛伊战争。斯巴达国王墨涅拉奥斯蒙受奇耻，向兄长迈锡尼王阿伽门农求援。野心勃勃的阿伽门农借机出兵，意欲征服特洛伊扩张势力。特洛伊城防御坚固，在国王普里阿摩斯与王子赫克托耳镇守下难以攻克；希腊方能否破城，全系第一勇士阿喀琉斯。','For passion. For honor. For destiny. For victory. For love.',175000000,497409852,66.803149,6.9,2759,163,'2004-05-13','en','/a07wLy4ONfpsjnBqMwhlWTJTcm.jpg',3.893706574744041,3,'2026-09-10',2,NULL,NULL),(654,'码头风云','On the Waterfront','马龙·白兰度演绎其生涯代表作，饰演由退役拳击手转行的码头工人特里·马洛伊。这部城市诗篇般的杰作，以粗粝而情感澎湃的笔触描绘个体挫败与社会腐败。随着当局逐渐逼近，特里陷入日益深重的道德危机——他必须在忠于与黑帮勾结的工会头目约翰尼·弗兰德利（李·科布 饰）及其心腹、特里的哥哥查利（罗德·斯泰格尔 饰）之间做出抉择。在伊利亚·卡赞鲜活而充满自然主义色彩的执导，与巴德·舒尔伯格犀利又深谙市井的剧本驱动下，本片问世即引发轰动，斩获八项奥斯卡奖，包括最佳影片、最佳导演、最佳男主角、最佳女配角（爱娃·玛丽·森特）及最佳剧本。','The Man Lived by the Jungle Law of the Docks!',910000,9600000,16.015599,8,357,108,'1954-06-22','en','/d4S8LpbCyFJsh1tGgwGQSJdGzKm.jpg',3.333536668496986,3,'2026-09-10',2,NULL,NULL),(657,'007：俄罗斯之恋','From Russia with Love','魔鬼党策划窃取一台能获取苏联国家机密的解码器，企图彻底颠覆世界秩序。詹姆斯·邦德奉命抢先找到该装置，却必须与冷酷的前克格勃特工罗莎·克莱布周旋。即便在与美艳的苏联女特工缠绵之际，邦德也意识到自己正步入陷阱——他必须动用全部智慧，方能战胜魔鬼党。[官方简介]','The world\'s masters of murder pull out all the stops to destroy Agent 007!',2000000,78898765,41.298723,6.9,760,115,'1963-10-11','en','/vh7KtT8HHS3XM4FW0GkUGf0T7GK.jpg',3.4894230202150056,3,'2026-09-10',2,NULL,NULL),(658,'007：金手指','Goldfinger','詹姆斯·邦德调查一位黄金大亨的走私活动，意外揭穿一项企图污染诺克斯堡黄金储备的惊天阴谋。','Everything he touches turns into excitement!',2500000,124881062,47.812466,7.2,987,110,'1964-09-17','en','/gowsJ3sHgxuMF0cWvwdvkqZOY81.jpg',3.6280684029331107,3,'2026-09-10',2,NULL,NULL),(660,'007：霹雳弹','Thunderball','007（肖恩·康纳利 Sean Connery 饰）这次的行动将会惊险万分，因为英国军方将派他完成一项关系到英国各大城市人民安危的行动。当然，007随身配备的各式各样的武器将会大大增加他的胜算。这次任务起因于一个世界性的恐怖组织——幽灵党，他们通过卧底获得了美国准备运输两枚原子弹前往英国的计划，于是在半路上拦截了美国军方的运输队，抢走了原子弹。得手后幽灵党向英国政府勒索一亿英镑，否则英国随时会在原子弹的袭击下毁于一旦。形势万分危急，007只能在幽灵党最后通牒的时间内潜入它总部，阻止它的阴谋。这简直就是一项不可能完成的任务，幸好有幽灵党的内应——美丽的邦女郎多明诺（’Domino‘ 克劳迪娜·奥格尔 Claudine Auger 饰）的帮助，007屡屡躲过敌人的跟踪和追杀，离成功越来越近。','Look up!  Look down!  Look out!',5500000,141195658,31.036,6.5,562,130,'1965-12-16','en','/xzoQ5Iw9BWZ276Rifbwp73imTUM.jpg',3.330543267732831,3,'2026-09-10',2,NULL,NULL),(663,'电锯惊魂4','Saw IV','SWAT指挥官瑞格突然被绑架，卷入了一场致命游戏，他必须在一个半小时之内过关斩将，躲过一个比一个恐怖的陷阱，才能保住性命。经验十足的FBI探员斯琼姆（斯科特•派特森 饰）来到被折磨得筋疲力尽的警察局，协助警探一起研究被竖锯玩死的受害者尸体，试图找出蛛丝马迹。随着调查的深入，竖锯变态的起因以及他邪恶的计划渐渐浮出水面……','You think it is over...but the games have just begun',10000000,139352633,29.244768,5.9,903,93,'2007-10-25','en','/5H5KVBY3gEgRRnHwShGLKXBPy0F.jpg',3.343363726785446,3,'2026-09-10',2,NULL,NULL),(664,'龙卷风','Twister','龙卷风的暴戾和神秘吸引了大批科学家的深入研究，深入风暴中间是最危险的行为，但亦是探索龙卷风最有效的方法。乔和离婚的丈夫比尔就是这类“与龙共舞”的科学家，即使他们感情已经破裂，比尔也已找到新的恋人，但出于对龙卷风研究的痴迷，他们还是决定共同追逐一场俄克拉何马州的飓风，并把新研制成功的探测仪“多萝西”放到龙卷风中心收集数据。他们驾驶着破旧的货车，带领着追风队，向最危险的地方进发。同时，另一队装备精良的人马也朝着这个方向驶去，由裘纳领队，在追风行动中和乔激励较劲。一边是志同道合的乔，一边是畏惧惊险生活的新女友，比尔在追风过程中如何重新抉择自己的感情道路？更重要的是，面对实力雄厚的对手，和随时葬身其中的龙卷风，乔和比尔如何实现自己的追风梦想？','The Dark Side of Nature.',92000000,494471524,32.079995,6.1,950,113,'1996-05-10','en','/h9cC1XkuVpzEzLBAZSXIKzvpIyx.jpg',3.3940088161264255,3,'2026-09-10',2,NULL,NULL),(666,'中央车站','Central do Brasil','里约热内卢的中央车站，朵拉在这里帮人写信。但她会把看不顺眼的信统统撕掉不寄，甚至公开读信里的内容取乐。朵拉生活拮据，年纪不小却还未嫁，或许在她内心，人与人之间的真情根本就不值得信赖。 小男孩约书亚的出现令她开始了一段重新认识人生的旅程——约书亚很想见到远方素未谋面的父亲，不断写信给他。男孩母亲意外的车祸让朵拉决定陪伴约书亚前往东北部寻找父亲。在约书亚眼中，即使父亲很陌生，却总是骄傲地谈起父亲。而朵拉，也同样有着一段和父亲的痛苦往事。在约书亚寻父的过程中，朵拉因为往事而冰冻的内心慢慢回暖。','He was looking for the father he never knew. She was looking for a second chance.',2900000,5596708,5.928937,7.6,126,113,'1998-01-16','pt','/sn98rIme6rHAkIB7RWmLX2uAPVK.jpg',2.9650293290635625,3,'2026-09-10',2,NULL,NULL),(667,'007：雷霆谷','You Only Live Twice','一天，美国太空船遭到了不明飞行物的攻击，美方怀疑是苏联的阴谋，目的是想独霸太空。美方测出了不明飞行物的降落地点是在日本，于是英国军方派出007（肖恩·康纳利 Sean Connery 饰）前往日本替美方调查此事。由于007的身份特殊，直接进入日本容易被敌人察觉。为了掩人耳目，007先是在香港假死，然后用新的身份进入了日本。另一方面，苏联的太空船也受到攻击，苏联同样认为是美国的阴谋。007在经过一番调查之后，发现整个阴谋的幕后主脑竟然是日本一家化学公司！007能否及时粉碎它的阴谋，化解误会？','You Only Live Twice...and Twice is the only way to live!',9500000,111584787,28.675891,6.5,531,117,'1967-06-12','en','/ebutL2sxSJbP47TFaYYPjhdEFh4.jpg',3.3112391545720166,3,'2026-09-10',2,NULL,NULL),(668,'007：女王密使','On Her Majesty\'s Secret Service','这次，阴谋家贝洛福（特利·萨瓦拉斯 Telly Savalas 饰）在瑞士山区建立一个疗养院，表面上这是一个普通的高级疗养院，风景秀丽、服务一流，但实际上却是贝洛福进行的一项旨在控制全球的计划的重要基地。在这个疗养院里，贝洛福开发出一种新型病毒，他企图将病毒注射到来这里疗养的女患者身上，然后通过她们传播到世界各地，达到掌握世界主权的目的。贝洛福的阴谋行动引起了英国情报部门的注意，于是007（乔治·拉扎贝 George Lazenby 饰）奉命出动。邦德乔装打扮成家谱学的专家混进了这座疗养院，他必须及时查处贝洛福的阴谋，并阻止他！','Far up! Far out! Far more! James Bond 007 is back!',6500000,81974493,25.289665,6.5,456,142,'1969-12-12','en','/kSpdYukU28GXzD4uG51tzUEdYjA.jpg',3.266250279619439,3,'2026-09-10',2,NULL,NULL),(670,'老男孩','올드보이','女儿生日那天，中年男子吴大修（崔岷植饰）在醉酒回家路上，突遭不明身份的人绑架失踪。就此，他毫无理由地被囚禁在一个神秘的私人监狱中。寻死未果的吴大修，每天看电视，三餐吃煎饺。通过电视，他得知妻子已遭杀害，女儿下落不明，自己更被怀疑为凶手。就此，吴大修开始锻炼身体，决心复仇，并在牢中度过漫长的15年...','15 years of imprisonment, five days of vengeance',3000000,14980005,56.76349,8,1945,120,'2003-01-01','ko','/pWDtjs568ZfOTMbURQBYuT4Qxka.jpg',4.019952915813055,3,'2026-09-10',2,NULL,NULL),(671,'哈利·波特与魔法石','Harry Potter and the Philosopher\'s Stone','从小失去双亲的哈利·波特一直寄住在姨妈一家，直到11岁生日那天，他意外得知自己是一名巫师，并收到了霍格沃茨魔法学校的入学通知。在海格的带领下，哈利第一次走进神奇的魔法世界，也得知父母当年死于黑巫师伏地魔之手，而自己却奇迹般地从袭击中幸存。进入霍格沃茨后，哈利与罗恩·韦斯莱、赫敏·格兰杰成为好友，开始学习魔法并展现出出色的魁地奇天赋。与此同时，三人发现学校里一只三头犬守护着某个秘密，而一块拥有神奇力量的“魔法石”似乎正成为某股黑暗势力的目标……','',125000000,976475550,49.3392,7.903,7006,152,'2001-11-16','en','/rUcN8fnvb6R8GY1NttAoLyjsRw0.jpg',4.3557806439642714,3,'2026-09-10',2,NULL,NULL),(672,'哈利·波特与密室','Harry Potter and the Chamber of Secrets','暑假期间，家养小精灵多比突然出现在哈利面前，警告他不要返回霍格沃茨，否则将面临巨大的危险。哈利没有听从劝告，仍与罗恩、赫敏开始了第二学年的生活。然而不久后，学校接连发生离奇的石化事件，墙上还出现了“密室已经被打开”的警告，而哈利也开始听见一种只有自己能够听到的神秘声音。传说霍格沃茨创办人之一萨拉查·斯莱特林曾在学校中留下一个密室，只有他的继承人才能开启。由于哈利意外展现出与蛇交流的能力，越来越多的人开始怀疑他与事件有关。为了查明真相，哈利、罗恩和赫敏开始追查密室以及霍格沃茨五十年前的一段往事……','',100000000,876688482,36.6148,7.707,5815,161,'2002-11-13','en','/314kPYq0WQNj7ts7ifSdpgXboTU.jpg',4.224800142216993,3,'2026-09-10',2,NULL,NULL),(673,'哈利·波特与阿兹卡班的囚徒','Harry Potter and the Prisoner of Azkaban','Harry, Ron and Hermione return to Hogwarts for another magic-filled year. Harry comes face to face with danger yet again, this time in the form of escaped convict, Sirius Black – and turns to sympathetic Professor Lupin for help.','Something wicked this way comes.',130000000,789804554,79.679601,7.7,5877,141,'2004-05-31','en','/aWxwnYoe8p2d2fcxOqtvAtJ72Rw.jpg',4.3241025890554985,3,'2026-09-10',2,NULL,NULL),(674,'哈利·波特与火焰杯','Harry Potter and the Goblet of Fire','Harry starts his fourth year at Hogwarts, competes in the treacherous Triwizard Tournament and faces the evil Lord Voldemort. Ron and Hermione help Harry manage the pressure – but Voldemort lurks, awaiting his chance to destroy Harry and all that he stands for.','Dark And Difficult Times Lie Ahead.',150000000,895921036,101.250416,7.5,5608,157,'2005-11-05','en','/fECBtHlr0RB3foNHDiCBXeg9Bv9.jpg',4.307870589229314,3,'2026-09-10',2,NULL,NULL),(675,'哈利·波特与凤凰社','Harry Potter and the Order of the Phoenix','Returning for his fifth year of study at Hogwarts, Harry is stunned to find that his warnings about the return of Lord Voldemort have been ignored. Left with no choice, Harry takes matters into his own hands, training a small group of students – dubbed \'Dumbledore\'s Army\' – to defend themselves against the dark arts.','Evil Must Be Confronted.',150000000,938212738,78.144395,7.4,5494,138,'2007-06-28','en','/5aOyriWkPec0zUDxmHFP9qMmBaj.jpg',4.223268361832417,3,'2026-09-10',2,NULL,NULL),(676,'珍珠港','Pearl Harbor','雷夫和丹尼是一对从小一起长大的好友，两人都热爱飞行，成年后又一同成为美国陆军航空队飞行员。受训期间，雷夫结识了军中护士伊弗琳，两人很快坠入爱河。此时第二次世界大战正在欧洲蔓延，渴望参战的雷夫主动加入英国皇家空军的鹰中队，前往欧洲战场，而丹尼和伊弗琳则被调往夏威夷珍珠港。不久后，雷夫在一次空战中失踪，被认为已经阵亡。失去共同挚爱与好友的伊弗琳和丹尼只能彼此扶持，而就在他们试图重新面对生活时，太平洋上日益紧张的局势也正悄然逼近珍珠港……','It takes a moment to change history. It takes love to change lives.',140000000,449220945,34.20669,6.6,1791,183,'2001-05-21','en','/uMyeYnL47TZgGVhPnEp3YCsfkmR.jpg',3.642528642042944,3,'2026-09-10',2,NULL,NULL),(679,'异形2','Aliens','在这部承接《异形》剧情的动作续集中，西格妮·韦弗回归饰演蕾普莉——人类首次遭遇异形怪物后的唯一幸存者。她关于异形及其船员命运的陈述起初备受质疑，直到LV-426殖民星球上的居民神秘失踪，促使她加入一支奉命前往调查的高科技殖民陆战队。','This Time It\'s War',18500000,183316455,67.66094,7.7,3220,137,'1986-07-18','en','/r1x5JGpyqZU8PYhbs4UcrO1Xb6x.jpg',4.130690750795226,3,'2026-09-10',2,NULL,NULL),(680,'低俗小说','Pulp Fiction','由序幕、尾声及三个独立又环环相扣的故事构成。早餐店两名劫匪打劫时，偶遇黑道打手朱尔斯与文森特；文森特奉命陪伴老大马沙的妻子，深陷诱惑困境；拳击手布奇因祖传金表，和马沙结下恩怨。','',8000000,213928762,36.9862,8.48,8428,154,'1994-09-10','en','/WZW5PCtCbtyKfojdLlPCi89DNx.jpg',4.534871155960428,3,'2026-09-10',2,NULL,NULL),(681,'Diamonds Are Forever','Diamonds Are Forever','Diamonds are stolen only to be sold again in the international market. James Bond infiltrates a smuggling mission to find out who’s guilty. The mission takes him to Las Vegas where Bond meets his archenemy Blofeld.','The man who made 007 a household number',7200000,116019547,34.634181,6.3,553,120,'1971-12-13','en','/4nh5y0Bl0CU4QVCqTEqoXgOl4Jz.jpg',3.3089092079939935,3,'2026-09-10',2,NULL,NULL),(682,'007：金枪人','The Man with the Golden Gun','世界上又多了一个杀人不眨眼的冷血杀手，注定又将引起一场惊涛骇浪。绰号金枪人的职业杀手几乎百发百中，没有他完成不了的任务，由此成为世界各恐怖组织争相高酬聘请的对象。同一时间，英国军方为了取回可将太阳能95%转化的高效率太阳能转化器（万一这种厉害的武器落入恐怖分子手中后果不堪设想），007（罗杰·摩尔 Roger Moore 饰）奉命出动了。恐怖组织为了阻止007的行动，高薪聘请了金枪人来对付007。最终鹿死谁手，007又能否顺利完成任务？','The man with the golden gun is ready to assassinate James Bond.',7000000,97572000,30.214716,6.3,524,125,'1974-12-01','en','/kalfeiqn18Ady2f8b7WPXmta4e8.jpg',3.286399086855569,3,'2026-09-10',2,NULL,NULL),(686,'超时空接触','Contact','艾莉·爱罗维（茱迪·福斯特 饰）自幼就对无线电通讯情有独钟。长大后，她成为一名天文学家，其项目内容为接收外太空信号。她希望能借此找到宇宙其他文明的存在。天才的理想得到的却是投资者的冷眼相看，幸好有神秘人帮助艾莉继续工作。 一次偶然的机会，艾莉收到了来自织女星的频率信号，似乎证明了艾莉一直以来的工作是正确的。但这带来的不是她个人事业的成功，而是政治、社会、宗教、国家各个角度的矛盾与讨论。深陷这一切暴风中心的艾莉，更要面对与神职人士帕尔默·乔丝（马修·麦康纳 饰）的感情纠葛。 个人与世界，真相与现实，艾莉面临着远远超越学术范围的挑战。','If it\'s just us, it seems like an awful waste of space.',90000000,171120329,55.249434,7.2,1308,150,'1997-07-11','en','/bCpMIywuNZeWt3i5UMLEIc0VSwM.jpg',3.7279824850476704,3,'2026-09-10',2,NULL,NULL),(687,'死囚漫步','Dead Man Walking','修女海伦（苏珊·萨兰登 Susan Sarandon饰）受死刑犯马修·庞斯莱（西恩·潘 Sean Penn饰）之托，前往监狱探望他。马修否认残杀年轻情侣被判死刑，提出上诉。海伦一路走访，深入村庄调查真相。一方面是被虐杀而死的无辜情侣，一方面是即将被处决的罪犯的精神依托， 海伦使尽各种办法帮助马修，但当她面对受害者双亲的痛诉以及公众的愤怒时，海伦的内心也陷入纠结的道德审判中。海伦最终感化了马修。行刑前，马修承认自己的罪行并祈求得到受害者家人的宽恕，安心而有尊严的走完人生的最后168小时。 本片改编自修女海伦·普雷金的真实故事，苏珊·萨兰登因本片荣获第68届奥斯卡最佳女主角。',NULL,11000000,39363635,15.864928,7.3,337,122,'1995-12-29','en','/eShxyjhWoFl3BwsuEmVsr4nLaMZ.jpg',3.247152446122146,3,'2026-09-10',2,NULL,NULL),(688,'廊桥遗梦','The Bridges of Madison County','弗朗西斯卡（Meryl Streep 饰）的子女翻看母亲的旧信，揭开了母亲生前不为人知的一段动人感情。1965年的一天，弗朗西斯卡独自在家，最后一个牛仔——摄影记者罗伯特•金凯（Clint Eastwood 饰）把车停在她门口，向她打听曼迪逊桥的所在。她带他来到桥边，完成工作 后他送她一把野菊花表示谢意。她的心中荡漾起难以言喻的滋味。她将一张纸条订在桥头，邀请他共进晚餐。欣然前来的他与她度过了美妙的一晚。此后2天二人整天厮守。 　　但是弗朗西斯卡割舍不下孩子和世俗的幸福，罗伯特最终独自上路。几年后二人在超市门口有过短暂的一瞥，当时弗朗西斯卡强忍奔上前去的冲动，漫天的雨成了他们诀别的泪。 　　1982年3月，她知道了罗伯特的死讯。在生命的最后旅程，她立下遗嘱：要子女们将自己的骨灰撒在曼迪逊桥畔，生前她把所有的时光都留给了家庭，但求死后能永远依偎在爱人的身边。','The path of Francesca Johnson\'s future seems destined due to an unexpected fork in the road...',24000000,182016617,17.606087,7.3,385,135,'1995-05-28','en','/lsi3wfSvWxyqDk5pi2788lVSgli.jpg',3.29046410602396,3,'2026-09-10',2,NULL,NULL),(691,'007：海底城','The Spy Who Loved Me','近日，英国、苏联两国的核子潜艇竟然相继离奇失踪了！这一现象引起了英国军方的高度重视，当然又到了王牌特工007（罗杰·摩尔 Roger Moore 饰）的出场时间。007经过调查终于发现幕后的黑手原来就是世界巨富航运业大亨史登堡，他为实现自己征服世界的野心，建立了一座海底城。史登堡高薪聘请科学家研发出了潜水艇跟踪系统，把把英、苏两国的核子动力潜艇占为己有，他计划利用核子飞弹将纽约和莫斯科炸毁，实现一次毁灭两个超级强国的野心。007即将进入海底城阻止这个狂人的疯狂计划！','It\'s the BIGGEST. It\'s the BEST. It\'s BOND. And B-E-Y-O-N-D.',14000000,185438673,27.17347,6.6,507,125,'1977-07-07','en','/8cBz4HNdbiYU93lA3eGAGOs7JFp.jpg',3.3087890620255758,3,'2026-09-10',2,NULL,NULL),(692,'粉红色的火烈鸟','Pink Flamingos','影片的主角是一个肥胖的女人，自认为是“世界上最污秽”的人，她可以把在肉店偷来的肉塞进阴道，也可以把地上的狗屎放进嘴里咀嚼。影片的另一个主角是一对同样变态的夫妇，这对夫妇专门强迫被绑架的妇女受孕，然后将出生的孩子卖给别人。影片就在双方不可避免的冲突中展开，最后，胖女人赢得了胜利，解放了那些被关押的妇女，又枪决了这对夫妇。','An exercise in poor taste.',12000,6000000,4.553644,6.2,110,93,'1972-03-12','en','/10N8SvTQwUqyWgocPam1P18Jgr.jpg',2.870284980147885,3,'2026-09-10',2,NULL,NULL),(693,'拜见岳父大人2','Meet the Fockers','格雷戈（Ben Stiller 本•斯蒂勒 饰）在上一集过五关、斩六将，终于凭着一份执着感动了未来岳父（罗伯特•德尼罗 Robert De Niro 饰），答应了他和潘米拉（Teri Polo特莉•保罗 饰）的婚事。本以为就此抱得美人归，然而，别忘了，还有亲家互相见面这一关。格雷戈的父母不像他们的亲家一般古板、对子女高要求、拒绝新事物。他们的教育方式另有一套：他们会为格雷戈在比赛中得第十名而高兴、会像朋友一样取消笑格雷戈的初夜失身、会以开放的姿态看待性、父亲会以母亲的成就为骄傲等等。这样两家风格完全不一样的亲家聚头，无论什么样的荒诞搞笑、无厘头场面都有可能发生，这对准新人能否顺利度过这一关?','Misery loves family.',80000000,516642939,32.829538,6.1,1373,115,'2004-12-22','en','/gG5WLZEBBnThAI8hbAzZMnhtrvm.jpg',3.475293600484408,3,'2026-09-10',2,NULL,NULL),(694,'闪灵','The Shining','杰克是一个作家。一个冬天，他得到了一个看管山顶酒店的差事。这正合杰克的意思，他正好可以有一个幽静的地方写作。于是杰克带着妻儿搬进了酒店。冬天大雪封路，山顶酒店只有杰克一家三口。从他们一搬进来，杰克的妻子温蒂就发现这里气氛诡异，杰克的儿子丹尼经常看到一些他不认识的人，但这里除了他们一家别无他人。而杰克除了一整天闷头写作外，脾气亦变得越来越古怪。直到有一天，温蒂发现丈夫这些天来一直写就只有一句话：杰克发疯了！','A masterpiece of modern horror.',19000000,44017374,78.699993,8.1,3757,144,'1980-05-22','en','/uAR0AWqhQL1hQa69UDEbb2rE5Wx.jpg',4.300419385448143,3,'2026-09-10',2,NULL,NULL),(698,'007：太空城','Moonraker','从美国运送英国太空船半途失去了行踪，这引起了美英两国的高度重视，于是英过军方派出了007（罗杰·摩尔 Roger Moore 饰）前去追查。经过调查，007发现了这件事背后后隐藏的另一个阴谋。世界上某个组织正在在制造一种神经麻痹气体，该气体是由一种极稀有的尼格拉兰花提取出来的。当007在这种兰花的产地详细调查后，一个足以震惊世界的大阴谋浮出了水面。原来，该组织已经在太空中建立了一个太空城，为了称霸世界，他们准备从太空城中发射50个自行研制毒气弹袭击地球上的50个大城市。007发现他们的阴谋后，准备飞上太空阻止他们这个疯狂的计划！','Outer space now belongs to 007.',34000000,210308099,29.887404,5.9,541,126,'1979-06-26','en','/8ZJ6Tn4N7E1sv9EuGM02oqJ9ZvT.jpg',3.2418682570152444,3,'2026-09-10',2,NULL,NULL),(699,'007：最高机密','For Your Eyes Only','英国军方一艘绝密的间谍船在希腊发生了爆炸，船上有一个威力无比的发射机（据说它可以使整个北极星飞弹系统全部报废）沉入了海底。这下，不仅英国军方，还有世界各地的间谍、恐怖分子都开始蠢蠢欲动。于是，007（罗杰·摩尔 Roger Moore 饰）出动了，他的任务就是尽快毁掉这台发射机。同一时候，哈维洛克先生在寻找这项装置时不幸被人刺杀身亡，他的女儿美琳娜（卡洛尔·布盖 Carole Bouquet 饰）试图千方百计想帮父亲报仇。007说服了美琳娜协助他潜入海底从沉船里取出了发射机。不幸的是，两人浮出水面被敌人抓住了……','No one comes close to James Bond, 007.',28000000,195312802,26.090746,6.3,490,127,'1981-06-23','en','/8VJo26SzoqJVzHul40rdXHmH0cc.jpg',3.2615278226429507,3,'2026-09-10',2,NULL,NULL),(700,'Octopussy','Octopussy','James Bond is sent to investigate after a fellow “00” agent is found dead with a priceless Farberge egg. James bond follows the mystery and uncovers a smuggling scandal and a Russian General who wants to provoke a new World War.','James Bond’s all time high.',27500000,187500000,25.633663,6.2,527,131,'1983-06-05','en','/ceGFRLvSwthnAKo5lfenT8B6i0F.jpg',3.2646572121290545,3,'2026-09-10',2,NULL,NULL),(702,'欲望号街车','A Streetcar Named Desire','精神恍惚的布兰奇·杜波依斯搬往新奥尔良与妹妹同住，在现实世界逐渐崩塌之际，又遭受野蛮妹夫的残酷折磨。','...Blanche, who wanted so much to stay a lady...',1800000,8000000,14.884756,7.6,281,125,'1951-09-18','en','/aicdlO5vt7z2ARm279eGzJeYCLQ.jpg',3.2171223996170975,3,'2026-09-10',2,NULL,NULL),(703,'安妮·霍尔','Annie Hall','伍迪·艾伦饰演一位神经质、极度缺乏安全感和优柔寡断的喜剧编剧，他疯狂迷恋上一位渴望成为歌手的天真小镇女孩。他们关系初期的互动充满了各种浪漫俗套。即便同居后，他的不安仍占据上风，将她的每个举动都解读为拒绝。当她的自信日渐增长，他的信心却逐渐消褪。这种古怪的恋情能否维系？','A nervous romance.',4000000,38251425,35.892034,7.8,1010,93,'1977-04-19','en','/dEtjPywhDbAXYjoFfhBC4U9unU7.jpg',3.7122466981446816,3,'2026-09-10',2,NULL,NULL),(704,'一夜狂欢','A Hard Day\'s Night','认识披头士！就在他们凭借《埃德·沙利文秀》引爆美国乐坛仅仅一个月后，约翰、保罗、乔治和林戈便开启了一项将他们革命性才华搬上银幕的计划。这部让乐队成员以嬉闹形象演绎自我的电影，捕捉了那个惊人的历史时刻——他们正式成为时代独一无二、桀骜不驯的偶像，并永远改变了音乐轨迹。导演理查德·莱斯特以狂放不羁的自由魄力，注入一系列标志性流行圣歌——包括同名主题曲《一夜狂欢》及《无法买我的爱》《我早该明白》《若我坠入》等。本片重构了音乐电影形态，对后世音乐录像带产生不可估量的影响，堪称影史最具狂欢气质的娱乐佳作之一。[标准收藏公司]','The Beatles, starring in their first full-length, hilarious, action-packed film!',560000,12299668,10.730056,7.3,168,88,'1964-07-06','en','/6Ulsccp2VkaVU5qbya3bxm9JG4x.jpg',3.0389940334405816,3,'2026-09-10',2,NULL,NULL),(707,'007：雷霆杀机','A View to a Kill','这次，007（罗杰·摩尔 Roger Moore 饰）在西伯利亚死亡的英国特工身上找到了科技秘密“微晶硒”之后，发现这个样品与英国的样品一样，证明克格勃的间谍肯定混进了英国的高科技研究秘密领域。于是，007奉命去调查在进行高科技研究的富商佐林（克里斯托弗·沃肯 Christopher Walken 饰）。不料他的身份被人识破，007被锁入车中沉进湖底。幸亏命运之神帮了007一个大忙，他得以侥幸逃脱。随后，007跟踪佐林来到了美国。007从苏联女间谍口中套出佐林正计划炸毁位于旧金山的硒矿的计划。为了阻止佐林的阴谋得逞，007行动开始了！','Has James Bond finally met his match?',30000000,152427960,27.230493,6,506,131,'1985-05-24','en','/gixqzbaRUOGNiqG9vyNhVQDNq9n.jpg',3.2346385785005274,3,'2026-09-10',2,NULL,NULL),(708,'007：黎明生机','The Living Daylights','东西双方处于针锋相对的奇妙情势。克格勃内部有些人为了自己的私利，搞出了一系列的阴谋，首先是科斯柯夫假意向西方“投诚”，并道出克格勃准备进行一项名为“特务飞龙”的计划，目的是消灭00组的特工，007怀疑其动机，伪装刺杀，并查出科斯柯夫与军火贩子一起用购买军火的货款走私毒品，007得到反政府武装的支持，终于炸毁了毒品，科斯柯夫的计划彻底破产。','Licensed to thrill.',40000000,191185897,23.331459,6.2,440,130,'1987-06-29','en','/4gXOyYrj2h2ExbCzIvSxhmHnNmv.jpg',3.2191681844337316,3,'2026-09-10',2,NULL,NULL),(709,'007：杀人执照','Licence to Kill','007（提摩西·道尔顿 Timothy Dalton 饰）和好友赖特在南美洲追踪毒品大王桑切斯，不但被狡猾的桑切斯逃脱了，而且赖特还掉进了桑切斯的陷阱――一个鲨鱼池。虽然最终赖特保住了性命，但他却失去了一双腿。上司要求007停止追查，然而报仇心切的007执意要追查到底，却被没收了他间谍独有的“杀人执照”。没了情报机关的支持，007决心一个人独干。当007赶往巴拿马的一家夜总会，并准备将在这里聚会的桑切斯逮捕归案时，他被一名香港的特工抓住了并被送到与英国情报机关接头的地方。狡猾的桑切斯随后派出武装人员将他们接头的地方炸毁了。幸亏007大难不死，他发誓一定要桑切斯血债血偿！','His bad side is a dangerous place to be.',32000000,156167015,28.22119,5.9,541,133,'1989-07-07','en','/uODaDsXqeZsHsM7lMUviFlpklYS.jpg',3.2380622963569134,3,'2026-09-10',2,NULL,NULL),(710,'007：黄金眼','GoldenEye','黄金眼是苏联研制的用于发射电磁波破坏对方电子系统的攻击性卫星。与007一块出生入死的朋友艾里克死后突然复出，夺取了黄金眼，并密谋从伦敦银行电脑中转出巨款，然后利用黄金眼毁灭证据，007深入基地，并炸毁基地。此次冒险行动中，007必须寻找在苏联被劫走的黄金眼，那是一种带有电磁波的武器，被一位叛变的苏联将军所偷。这项任务背后，最复杂的是007发现制造这次阴谋的歹徒是他的一位旧识及同僚，他是英国籍的探员006，他计划使用这项武器引起全球金融的瓦解，借此增加财富。同时，007遇见美艳女郎西娜·奥纳托，她是一位变态的歹徒，并用尽一切方法对付007。另一位新进的邦女郎是娜塔丽娅，她将协助007打败006。','No limits. No fears. No substitutes.',58000000,352194034,59.824565,6.6,1174,130,'1995-11-16','en','/5qD5eSKi1uCpgPcdjtZsaXy5rVX.jpg',3.595684072601631,3,'2026-09-10',2,NULL,NULL),(711,'心灵访客','Finding Forrester','十六岁的黑人男孩詹姆·华莱士（罗伯·布朗 Rob Brown 饰）在篮球方面极富天赋，非常有潜力成为篮球界的明日之星。他常常与小伙伴们一起打篮球，他们注意到住在对面公寓顶层的沉默男人总是看着他们。这位神秘的隐士原来就是知名作家威廉·佛瑞斯特（肖恩·康纳利 Sean Connery 饰）。一次偶然的恶作剧让两人相互结识，威廉发现他在写作方面也很有天份。很快，詹姆凭借自己出色的篮球技术和优秀成绩，获得了一所著名私立学校的邀请。然而对于一所白人学校而言，詹姆却面临着艰难选择和种种质疑。威廉同意帮助詹姆提高他的写作水平。渐渐地，两人在交流中建立了深厚的友谊，循循善诱的威廉激发出詹姆潜藏的写作才能，而威廉自己也开始改变，终于走出避世多年的隐居公寓。','In an ordinary place, he found the one person to make his life extraordinary.',43000000,80049764,19.043286,7,302,136,'2000-12-21','en','/y7CS21qnCcXICwt0qVsvb2U21Oq.jpg',3.1960257492050514,3,'2026-09-10',2,NULL,NULL),(712,'四个婚礼和一个葬礼','Four Weddings and a Funeral','查尔斯是婚礼上的常客，却对结婚却怀有疑惧。一次乡间婚礼上，他对美丽的美国姑娘凯莉一见钟情。虽然从朋友口中查尔斯听到凯莉的很多坏话，但他还是推掉了朋友们的邀请前去寻找凯莉。两人度过一个美好的夜晚。但第二天凯莉竟只身回了美国，弄得查尔斯心神不宁。查尔斯的朋友们一个个都开始准备结婚。两个月后，在伦敦的一个婚礼上，查尔斯凯莉重又相逢。就在查尔斯满心欢喜之时，凯莉却向他介绍了自己的未婚夫。查尔斯非常失落。女友海伦娜向他表达爱意，他根本无心回应。凯莉前来寻找查尔斯，两人再次共度良宵。 一个月后，查尔斯收到了凯莉的结婚请柬。在选礼物时，查尔斯遇上了凯莉。凯莉向查尔斯说起了自己的风流韵史。冲动的查尔斯想向凯莉求婚，但始终没能开口。查尔斯还是去参加了凯莉的婚礼，心灰意冷的他接受了海伦娜。查尔斯的朋友盖诺斯心脏病突发去世。葬礼上，查尔斯又见到了凯莉，终于向她表白。','Five good reasons to stay single.',6000000,254700832,29.834065,6.6,632,117,'1994-03-09','en','/qa72G2VS0bpxms6yo0tI9vsHm2e.jpg',3.3705578056077843,3,'2026-09-10',2,NULL,NULL),(713,'钢琴课','The Piano','简·坎皮恩凭借这部关于欲望与创造力的崇高寓言，成为戛纳电影节首位荣膺金棕榈奖的女性导演。霍利·亨特通过静默演绎出痛彻心扉的感染力，以奥斯卡获奖表演塑造了艾达——一位选择缄默的苏格兰女性，通过珍爱的钢琴倾诉灵魂深处的悸动。当包办婚姻将艾达与她桀骜不驯的女儿带到十九世纪新西兰的荒野，她陷入与掌控欲强烈的丈夫以及一位粗犷拓荒者之间的意志博弈，而对后者的禁忌情愫更使她内心波澜翻涌。影片以感性忧郁的影像诗学、戏剧性的海岸景观与恢弘配乐，铸造出这场超越时代的女性觉醒颂歌，令人沉醉的感官体验中燃烧着音乐与情欲的双重火焰。',NULL,7000000,116700000,17.681707,7.1,281,121,'1993-05-19','en','/udSvOHlG6CuuNX6x1n2PZcVzQ2b.jpg',3.181754963025632,3,'2026-09-10',2,NULL,NULL),(714,'007：明日帝国','Tomorrow Never Dies','英国海军的德文郡号军舰在中国领海内被遭到不明鱼雷攻击沉没。为了查明情况，英国海军决定动用武力，派出军舰前往出事海域进行反击。然而却被秘密情报负责人M（朱迪·丹奇 Judi Dench 饰）阻止，并派出代号007的情报员詹姆斯·邦德（皮尔斯·布鲁斯南 Pierce Brosnan 饰）去查清真正的原因，避免两国之间一触即发的战争。在不断深入的调查中，媒体大亨卡佛（乔纳森·普雷斯 Jonathan Pryce 饰）进入了邦德的视线。而且在卡佛举办的晚宴上，邦德遇上了前女友帕丽丝（泰瑞·海切尔 Teri Hatcher 饰），现在的卡佛夫人。在帕丽丝的帮助下，邦德利用GPS让已出动的英国军舰偏离了航道为自己的调查争取到了宝贵的时间。从卡佛处偷来的设备上，邦德发现了沉没军舰的准确位置，不过在沉船处却与中国女特工林惠（杨紫琼 饰）一起被卡佛擒获。原来，卡佛是想通过引发战争来获得全球媒体的垄断地位。这一次，邦德能否逃出魔掌捣毁卡佛的阴谋？','Yesterday is a memory. Today is history. Tomorrow is in the hands of one man.',110000000,333011068,42.887121,6,925,119,'1997-12-11','en','/5xF1rWo5v7S7jILyJKmeQhcvu1k.jpg',3.396151184516205,3,'2026-09-10',2,NULL,NULL),(744,'壮志凌云','Top Gun','“独行侠”皮特·米切尔（汤姆•克鲁斯饰）的父亲是个战功显赫的老飞行员，他决心也要成为父亲那样的英雄。终于机会来了，他与军官“笨鹅”尼克·布拉德肖（安东尼•爱德华兹 饰）一起被派到了Top Gun训练基地接受最严格的飞行训练。可是，“独行侠”的训练并不像预想中顺利，他的成绩一直不令人满意，一起训练的”冰人”汤姆·卡赞斯基（方·基默饰）也对他也颇有微词。与此同时，“独行侠”遇到了美丽的女教官查莉（凯莉•麦吉利斯饰），两人对彼此暗生情愫，这令本来有些心灰意冷的“独行侠”重拾信心。在毕业前的一次训练中，“独行侠”搭档“笨鹅”再次同驾一机，但由于马达发生故障，“独行侠”与“笨鹅”被迫跳海，结果“笨鹅”不幸身亡。这次事件给“独行侠”带来了沉重的打击，本来因学业不顺就郁郁寡欢的他更加消沉了，甚至想要彻底放弃成为飞行员的梦想。“独行侠”最终能否克服心障重回蓝天？','Up there with the best of the best.',15000000,356830601,58.900647,6.7,1698,110,'1986-05-16','en','/xUuHj3CgmZQ9P2cMaqQs4J0d4Zc.jpg',3.70673566950729,3,'2026-09-10',2,NULL,NULL),(745,'第六感','The Sixth Sense','麦克（布鲁斯·威利斯 饰）是著名儿童心理学家，却也有始终未能治愈的患者，甚至因此遭到枪杀，这名少年随后也饮枪自毙。这给麦克带来很大心理阴影，一年后他找到另一个症状很像这名患者的男孩柯尔（海利·乔·奥斯蒙 饰），并耐心的做起了他的医生。柯尔并不容易接近，但麦克还是慢慢赢得 了他的信任，得知了柯尔的秘密。原来柯尔有着灵异的第六感，可以看到鬼魂。虽然这令人感到难以置信，但麦克在证实了事情的真相后还是帮助柯尔接受了这个事实。  　　可是就在问题即将得到解决的时候，麦克却在柯尔的引导下，发现了一个更令人震惊的秘密……','Not every gift is a blessing.',40000000,672806292,73.085576,7.7,3147,107,'1999-08-06','en','/vOyfUXNFSnaTk7Vk5AjpsKTUWsu.jpg',4.136448785625264,3,'2026-09-10',2,NULL,NULL),(746,'末代皇帝','The Last Emperor','1908年，三岁的溥仪被接入紫禁城，登上皇位，成为清王朝最后一位皇帝。年幼的他生活在宫墙之内，拥有至高无上的名义与礼遇，却始终与真实的世界相隔绝。随着时代巨变，清王朝覆灭，溥仪被迫离开紫禁城，此后又在日本人的扶植下成为伪满洲国皇帝，自以为重新掌握权力，却逐渐发现自己不过是被操纵的傀儡。战争结束后，曾经高高在上的皇帝以战犯身份被押回中国，开始重新面对自己跌宕起伏的一生……','He was the Lord of Ten Thousand Years, the absolute monarch of China. He was born to rule a world of ancient tradition. Nothing prepared him for our world of change.',23000000,43984230,21.189028,7.4,355,163,'1987-10-21','en','/f1gDRukoKvHwitvF0HvrBiX2V58.jpg',3.284456499180827,3,'2026-09-10',2,NULL,NULL),(747,'僵尸肖恩','Shaun of the Dead','肖恩（西蒙·佩吉 Simon Pegg 饰）事业不如意，爱情也不怎么顺心。认识了一帮同样游手好闲的朋友，整天和他们厮混，包括皮特，和只会打机和讨人厌的艾德。难得肖恩为了女朋友振作一次，却遭到同事嘲笑，女友也不能会意，肖恩只有继续和朋友醉酒纵乐。  但这天整个城市却有了翻天覆地的变化。僵尸入侵了，只要是被他们咬到的人，都会随之变成僵尸。而肖恩正和艾德在酒吧里豪饮，却发现陷入僵尸的重重包围中。现在肖恩必须拿出英雄气概，去捍卫家人朋友。','A romantic comedy. With zombies.',4000000,30039392,49.12486,7.5,2420,99,'2004-04-09','en','/dgXPhzNJH8HFTBjXPB177yNx6RI.jpg',3.9579108753543415,3,'2026-09-10',2,NULL,NULL),(752,'V字仇杀队','V for Vendetta','未来的英国社会处于极权统治的高压下，不能容许同性恋者、异教徒等社会角色的存在，人民在黑暗政权下苟延残喘。  这晚，年轻女子艾薇身陷险境，幸得V相助。V是一个永远带着面具的神秘男子，拥有高智商和超凡战斗力。他摧毁了伦敦的标志性建筑，同时也点燃了反政府的熊熊烈火。 艾薇在和V深入接触后，不仅得知了V的神秘使命，还渐渐发现了自己的身世，这也注定了自己和V会是同一条阵线的人。','People should not be afraid of their governments. Governments should be afraid of their people.',54000000,132511035,84.630969,7.7,4442,132,'2006-03-15','en','/piZOwjyk1g51oPHonc7zaQY3WOv.jpg',4.260060550688959,3,'2026-09-10',2,NULL,NULL),(754,'变脸','Face/Off','FBI探员肖恩·阿彻知道如何阻止行踪诡秘的恐怖分子卡斯特·特洛伊——他必须成为特洛伊。阿彻接受未来科技手术，将特洛伊的脸移植到自己脸上，以此潜入恐怖分子的世界，揭露其致命秘密。然而尽管阿彻在外表与行为上酷似特洛伊，他却并未真正了解对方。他万万没想到特洛伊会展开报复，强迫医生将自己变成了阿彻。如今这位探员面临着彻底崩溃的噩梦：他的宿敌正与他的家人生活在一起。[派拉蒙影业]','In order to catch him, he must become him.',80000000,245676146,46.075037,6.8,1583,138,'1997-06-27','en','/6vsqENdRdpskj0sMmNetfBh5O5s.jpg',3.680134066956496,3,'2026-09-10',2,NULL,NULL),(755,'杀出个黎明','From Dusk Till Dawn','塞斯•杰科（乔治•克鲁尼 George Clooney 饰）恶贯满盈，被判刑多年；弟弟理查德（昆汀•塔伦蒂诺 Quentin Tarantino 饰）打通关节帮他成功越狱。为了能顺利逃往墨西哥，兄弟俩挟持了牧师一家人，一路上以他们作掩护。最终经过重重关卡，他们顺利逃到了墨西哥。　　到达墨西哥后，杰科兄弟联系上了当地的匪徒卡洛斯为他们打点一切，并约好在一家酒吧碰面。按计划杰科兄弟和卡洛斯接上头后就将释放牧师一家，似乎结局皆大欢喜。然而，他们在酒吧里等到入夜还没见到卡洛斯，等来的却是一大群僵尸！为了保命，他们只能和僵尸浴血奋战！','One night is all that stands between them and freedom. But it\'s going to be a hell of a night.',19000000,25836616,64.181668,6.9,1603,108,'1996-01-19','en','/sV3kIAmvJ9tPz4Lq5fuf9LLMxte.jpg',3.745402085275846,3,'2026-09-10',2,NULL,NULL),(756,'幻想曲','Fantasia','一系列以动画形式演绎西方古典音乐伟大作品的动画合集。','The most sensational sound you\'ll ever see!',2280000,83320000,32.875469,7.2,808,124,'1940-11-13','en','/4WmOUxT3RZuEWRpf2MFtXosfCZ3.jpg',3.534406675505865,3,'2026-09-10',2,NULL,NULL),(762,'巨蟒与圣杯','Monty Python and the Holy Grail','故事跟随亚瑟王和他的圆桌骑士展开寻找圣杯的征程。这绝非寻常的中世纪骑士与战马传说——首先，由于王国资源短缺，所有战马竟都被用拍击椰子壳模仿马蹄声的仆人所替代！','And now! At Last! Another film completely different from some of the other films which aren\'t quite the same as this one is.',400000,5028948,64.782984,7.8,1708,91,'1975-03-13','en','/7nTkHjETdGMYK1phHwDbPsrzbYl.jpg',3.95300199345528,3,'2026-09-10',2,NULL,NULL),(764,'鬼玩人','The Evil Dead','五个年轻人艾什，雪莉等相约一起自驾游，他们预订了一座坐落于深山里房子作为野外落脚点，他们翻山越岭终于找到了这间小木屋。晚上，他们发现了这间屋子主人留下来的一本封面吓人的古怪的书和一部老式录音机。屋子主人在录音留言里说他在研究远古流传的丧礼和一些咒语，而那本古怪的书名字就叫“死亡之书”；根据书上说人死了其实只是保持睡眠状态，并没有真正死去，通过咒语可以重新活过来。接着录音机里就播放了一段令人毛骨悚然的咒文。随后，恐怖的事情开始陆续发生。','The Ultimate Experience In Grueling Terror',350000,29400000,35.037625,7.3,894,85,'1981-10-15','en','/ud89aWIuaSLaj1yMcl3dBVVr6UR.jpg',3.5860116105906417,3,'2026-09-10',2,NULL,NULL),(765,'Evil Dead II','Evil Dead II','Ash Williams and his girlfriend Linda find a log cabin in the woods with a voice recording from an archeologist who had recorded himself reciting ancient chants from “The Book of the Dead.” As they play the recording an evil power is unleashed taking over Linda’s body.','The Sequel To The Ultimate Experience In Grueling Terror',3600000,5923044,35.674774,7.6,742,84,'1987-03-13','en','/7UM8LrX6MIib03VKk1kl24SQm75.jpg',3.57593272616159,3,'2026-09-10',2,NULL,NULL),(766,'鬼玩人3：魔界英豪','Army of Darkness','美国青年艾许（布鲁斯•坎贝尔 Bruce Campbell 饰）在和女友琳达（布丽切特•方达 Bridget Fonda 饰）度假时，偶然发现一本《死亡之书》。书中记载各种神秘的丧葬风俗以及招魂仪式，更为诡异恐怖的是，这本不应该存在于人间的书具有十分强大和邪恶的魔力。为与之斗争，艾许失去了女友和自己的右手，但最后还是体力不支，被《死亡之书》带到600年前的中世纪。他奇怪的穿着一度被骑士们当作间谍抓起来，经过一番波折，艾许决定帮国王打败《死亡之书》幻化出来的怪兽，这也是他回到现代社会的唯一办法……','Trapped in time. Surrounded by evil. Low on gas.',11000000,0,33.758281,7.3,838,81,'1992-10-09','en','/tNnOQnrFYK7DYzMHHDkt1Awoski.jpg',3.5633411928959973,3,'2026-09-10',2,NULL,NULL),(767,'哈利·波特与混血王子','Harry Potter and the Half-Blood Prince','伏地魔及食死徒的势力不断扩张，危险已经从魔法世界蔓延到麻瓜社会。哈利开始了在霍格沃茨的第六个学年，邓布利多则带他拜访退休多年的霍拉斯·斯拉格霍恩，希望从这位昔日教授关于少年汤姆·里德尔的记忆中，找到破解伏地魔力量秘密的关键。与此同时，哈利偶然得到一本写满神秘批注的旧魔药课本，扉页上署着“混血王子”的名字，书中的笔记让他在魔药课上突飞猛进，却也隐藏着危险。另一边，德拉科·马尔福似乎被赋予了一项秘密任务，哈利越来越确信霍格沃茨内部正在酝酿一场阴谋……','Dark Secrets Revealed',250000000,933959197,98.885637,7.4,5293,153,'2009-07-07','en','/z7uo9zmQdQwU5ZJHFpv2Upl30i1.jpg',4.261044326574357,3,'2026-09-10',2,NULL,NULL),(768,'来自地狱','From Hell','1888年伦敦东部的Whitechapel区，犹太人、黑人和下层贫民混杂其中，犯罪事件层出不穷，是伦敦城的一个大毒瘤。妓女安的被绑架拉开了一系列恐怖事件的序幕，紧接着另一名妓女波丽也被残忍地杀害了，这令这群可怜的姑娘们陷入了深深的惊惧之中，她们发现自己已成为连环杀手的猎取目标，一个接一个……这一系列罪案引起了一位探员弗雷德艾伯林的注意。艾伯林不仅头脑灵活，还具有一种超自然的感应力量，这种奇异的能力经常在他办案中发挥重要作用，但遭受丧妻之痛的他不得不长期依赖鸦片来麻醉自己。 艾伯林预感到将有惨剧发生，于是深入到这一黑暗地区进行调查，尽管当地居民对他怀着深深的排斥，艾伯林还是得到了妓女玛丽和私人医生威廉戈尔的帮助。艾伯林逐渐发现失踪的安和她的孩子是一个重要线索，但她们的失踪与杀手不断制造的谋杀案之间究竟有什么联系呢？恐怖的阴云依旧不散，妓女们人人自危。一起更令人震撼的阴谋似乎开始浮出水面，但同时艾伯林自身也受到了严重威胁。此时他的调查也变得更加与自己息息相关，因为他已与玛丽坠入了爱河......','Only the legend will survive.',35000000,74558115,26.134678,6.6,741,122,'2001-10-19','en','/t2WpWM8nBO4sULXr2bDfNEt4qgr.jpg',3.4024152711872246,3,'2026-09-10',2,NULL,NULL),(769,'好家伙','GoodFellas','本片根据真实故事改编，讲述了纽约黑手党血腥的江湖恩怨，把所谓的“江湖道义”还原为人性的丑陋与贪婪。\r 亨利•希尔（雷•李欧塔 饰）从小不学无术，跟着老大保利，靠收取保护费、走私、抢劫，他娶了美丽的妻子凯伦，有可爱的女儿，迷人的情妇，名车豪宅，生活优渥。\r 吉米•康维（罗伯特•德尼罗 饰）和汤米（乔•佩西 饰）是亨利的好朋友，三人一起经历和很多事情：杀死羞辱汤米的意大利黑手党头领比利•贝兹；策划德航劫案，并干掉同伙，私吞赃款；甚至背着老大保利贩毒。\r 当然，他们的生活，除了享受金钱带来的权势之外，更多的，是朝不保夕的动荡：汤米因为比利•贝兹的死，被人枪杀；亨利自己因为贩毒被警方逮捕，其他人也受到牵连。\r 凯伦想尽办法将亨利保释出来，此时他们已经一无所有，被人孤立，危机四伏。他们要想尽办法活下去，无论以怎样的方式，付出怎样的代价……','',25000000,46836394,24.5617,8.452,3128,145,'1990-09-12','en','/4W6gXVoNJKBCx2X1Jh5BQ17SAGN.jpg',4.2068421660439315,3,'2026-09-10',2,NULL,NULL),(770,'乱世佳人','Gone with the Wind','这部史诗巨制描绘了一位南方佳丽在美国内战与重建时期的命运浮沉。影片荣获八项奥斯卡金像奖，其中包括最佳影片奖。','The greatest romance of all time!',4000000,400176459,48.98255,7.7,970,238,'1939-12-15','en','/lNz2Ow0wGCAvzckW7EOjE03KcYv.jpg',3.7112530686103042,3,'2026-09-10',2,NULL,NULL),(771,'小鬼当家','Home Alone','一年一度的圣诞节又到了。全家忙着外出欢度圣诞假期，不料忙中出错，将家里最小的成员-8岁的凯文（麦考利•卡尔金 Macaulay Culkin饰）留在了家里。爸爸妈妈急坏了，可此时他们已经身在外地，一时亦无可奈何。倒是凯文乐坏了，难得一个人在家，凯文将家里布置成了“游乐场”。两个刚出狱的窃贼将目光瞄向了凯文家。当他们鬼鬼祟祟的踏入凯文家时，凯文凭借自己的醒目和家里的“游乐场机关”，和两个笨贼玩起了“游戏”，笑料百出。凯文最后能否这场“游戏”的胜利？','A Family Comedy Without the Family.',18000000,476684675,2.186927,7.1,2414,103,'1990-11-09','en','/onTSipZ8R3bliBdKfPtsDuHTdlL.jpg',3.757789280637402,3,'2026-09-10',2,NULL,NULL),(772,'Home Alone 2: Lost in New York','Home Alone 2: Lost in New York','Instead of flying to Florida with his folks, Kevin ends up alone in New York, where he gets a hotel room with his dad\'s credit card—despite problems from a clerk and meddling bellboy. But when Kevin runs into his old nemeses, the Wet Bandits, he\'s determined to foil their plans to rob a toy store on Christmas eve.','He\'s up past his bedtime in the city that never sleeps.',18000000,358991681,81.487685,6.3,2395,120,'1992-11-19','en','/uuitWHpJwxD1wruFl2nZHIb4UGN.jpg',3.7527665316575867,3,'2026-09-10',2,NULL,NULL),(773,'阳光小美女','Little Miss Sunshine','7岁的奥利芙（阿比盖尔·布蕾斯琳 Abigail Breslin 饰），戴眼镜，小肚腩，做着一夜成名的美梦，坚信自己有朝一日能当选美国小姐。爸爸（格雷戈·金尼尔 Greg Kinnear 饰），推销成功学书籍的讲师，认为“世界上只有两种人，成功者和失败者”，四处贩卖他的“成功九部曲”；哥哥（保罗·达诺 Paul Dano 饰），自闭男，崇拜尼采，为了考上飞行学院发哑誓，九个月没有同家人说话；舅舅（史蒂夫·卡瑞尔 Steve Carell 饰），自称是美国最好的普鲁斯特研究学者，同性恋，恋人和同事跑掉、失业，自杀未遂，生活混乱；爷爷（艾伦·阿金 Alan Arkin 饰），被养老院赶出来的老流氓，满嘴脏话、吸毒；妈妈（托妮·克莱特 Toni Collette 饰），是这个疯狂家庭唯一正常的人。在家人的支持下，奥利芙参加了“阳光小美女”的选美比赛，一家人踏上了集体寻梦的旅程。','A family on the verge of a breakdown',8000000,100523181,14.793177,7.5,1686,102,'2006-07-26','en','/niNdhTpPHSgw22tK0PLjQMV640v.jpg',3.7717757775550718,3,'2026-09-10',2,NULL,NULL),(782,'千钧一发','Gattaca','未来的世界，科技的力量胜过一切，基因决定命运，几乎成为金科玉律。不幸文森特（伊桑·霍克 Ethan Hawke 饰）是一个基因不良的人，出生以来就决定了他近视和心脏病的缺陷，他只能活到30岁。\r 于是父母为文森特增添了一个有着优良基因的弟弟。文森特的梦想是漫游太空，然而恶劣的基因令他无法圆梦，直到他遇到了太空中心的杰罗姆（裘德·洛 Jude Law 饰）。杰罗姆有优秀的基因，却在一次意外中半身瘫痪。\r 二人决定调换身份，文森特千方百计隐藏自己的基因信息，每天都认真清洗掉自己的皮屑毛发，不暴露任何蛛丝马迹。另一方面，杰罗姆帮他筹备进入太空前需要检查的基因物品。事情进展得非常顺利，然而一桩谋杀案和一根睫毛，让事情节外生枝。','There is no gene for the human spirit.',36000000,12532777,70.398356,7.5,1808,106,'1997-09-07','en','/eSKr5Fl1MEC7zpAXaLWBWSBjgJq.jpg',3.9199906039475323,3,'2026-09-10',2,NULL,NULL),(783,'甘地传','Gandhi','本片记录了印度圣雄甘地史诗般传奇伟大的一生。1893年，24岁的甘地（本•金斯利 Ben Kingsley 饰）受邀前往南非任律师职，决心在当地带领印度移民开展非暴力不合作的抗议活动，并因此入狱。出狱后甘地回到祖国，在三八朗地区建立了高僧修行所，加入了国大党领导的印度独立运动，宣传非暴力不合作的斗争理念。运动中甘地曾四次入狱；在其不懈努力及国大党的带领下，印度独立终于提上议事日程，甘地也于1931年赴伦敦参加商讨独立的圆桌会议。然而随着独立的临近，印度国内穆斯林与印度教人民之间的宗教矛盾日益突出，甘地的非暴力不合作理念又面临着更为严峻的新挑战…… 　　本片获1982年奥斯卡最佳影片，最佳导演（理查德•阿滕伯勒Richard Attenborough），最佳男演员（本•金斯利），最佳原创剧本，最佳艺术指导，最佳摄影，最佳服装设计和最佳剪辑共八项大奖，并获奥斯卡最佳化妆，最佳电影音乐和最佳音效三项提名。','His triumph changed the world forever.',22000000,77737889,35.227212,7.4,716,191,'1982-11-30','en','/4oRfsT71F3xKpRsSy5QFIPS1IkI.jpg',3.533454812645564,3,'2026-09-10',2,NULL,NULL),(786,'几近成名','Almost Famous','1970年代，一名高中生获准跟随当红新晋摇滚乐团“静水”全美巡演，并撰写他们的故事。','Experience it. Enjoy it. Just don\'t fall for it.',60000000,47383689,21.547446,7.4,797,122,'2000-09-15','en','/pfHW98d8Vj7tDSqCcsseDOMikzp.jpg',3.5357916794131885,3,'2026-09-10',2,NULL,NULL),(787,'史密斯夫妇','Mr. & Mrs. Smith','约翰和简已经结婚了7年多，生活就像淡水般无味。婚姻就像坟墓，让他们过着死水一潭的生活。然而这仅仅是表象。背后他们各有刺激惊险的职业——约翰和简分属两个不同的秘密杀手机构，但彼此却不知道对方的职业身份。直到他们同时接到一个任务，刺杀目标竟是同一人。身份的真相才开始慢慢揭开。 反复的试探和猜测，简终于不小心说穿了自己身份。于是一场同室操戈不可避免的发生了。但是他们也开始意识到，自己只是组织的一个棋子。而眼前的，是共同生活了7年的爱人。','Smart and sexy.',110000000,478207520,44.635452,6.5,2965,120,'2005-06-07','en','/kjD700RtyhveN3ZbOnSvUSne0Qj.jpg',3.7651209124445746,3,'2026-09-10',2,NULL,NULL),(788,'窈窕奶爸','Mrs. Doubtfire','丹尼尔·希拉德因与同事产生摩擦而辞掉了配音员的工作。家中可爱的孩子给了他十足的快乐，于是丹尼尔在儿子生日的时候，与孩子们疯狂的玩耍起来。当妻子米兰达看到家中一片狼藉后十分生气。面对不争气的丈夫，米兰达决定与之离婚，因为没有工作，丹尼尔也失去了孩子的抚养权。丹尼尔对孩子们无比思念，突发奇想乔装成一名老太太——道特菲尔太太应聘成为妻子家中的佣人。不懂家务的丹尼尔闹出了不少的笑话，却无形中为米兰达减轻了负担，孩子们也开始依赖这名“老太太”，“道特菲尔太太”成为了他们家中的重要一员，丹尼尔也因此改变了不少。但面对米兰达的新男友的恋情，“道特菲尔太太”暗中捣乱。米兰达生日当天，丹尼尔需要以真实身份与“道特菲尔太太”的身份周旋与电视台主管与米兰达之间，使他狼狈不看。匆忙间会否被米兰达识破身份呢？','She makes dinner. She does windows. She reads bedtime stories. She\'s a blessing... in disguise.',25000000,441286195,30.884535,7,1591,125,'1993-11-24','en','/shHrSmXS5140o6sQzgzXxn3KqSm.jpg',3.687910722524166,3,'2026-09-10',2,NULL,NULL),(790,'夜雾杀机','The Fog','100年前的北加利福尼亚的安东尼奥海滩，患有麻风病的富豪布雷克希望在此建立一个小镇，将同样患有麻风病的患者集中起来治疗。然而他的爱心并未得到应有的回报，许多觊觎布雷克财富的贪婪之徒来到这里，伺机杀害了布雷克。100年后，当小镇人民举行百年庆典时，一团神秘雾气降临小镇，布雷克及其随从的冤魂从大海深处归来，所到之处人们尽皆死亡。神父罗伯特（Hal HolbrooK 饰）无意中发现其祖父藏在教堂墙壁中的日记，终于得知曾发生在100年前的惨剧……','Lock your doors. Bolt your windows. There\'s something in THE FOG!',1000000,21378361,14.518598,6.4,311,89,'1980-02-08','en','/12EeSboRofP3CI4SPmMFNNXCbtY.jpg',3.1398195291419815,3,'2026-09-10',2,NULL,NULL),(792,'野战排','Platoon','一名年轻士兵在越南战场上直面战争的恐怖与人性的双重性，陷入道德危机。','The first casualty of war is innocence.',6000000,138530565,49.802914,7.5,1205,120,'1986-12-18','en','/m3mmFkPQKvPZq5exmh0bDuXlD9T.jpg',3.747621066880612,3,'2026-09-10',2,NULL,NULL),(794,'The Omen','The Omen','Immediately after their miscarriage, the US diplomat Robert Thorn adopts the newborn Damien without the knowledge of his wife. Yet what he doesn’t know is that their new son is the son of the devil. A classic horror film with Gregory Peck from 1976.','It is the greatest mystery of all because no human being will ever solve it.',2800000,60922980,25.939385,7.2,476,111,'1976-06-06','en','/4iNKCJ2cm4GG3PBPUO0o1WfwyWa.jpg',3.3612159046929877,3,'2026-09-10',2,NULL,NULL),(795,'天使之城','City of Angels','天使塞斯（尼古拉斯•凯奇 饰）拥有天使应该拥有的一切法力，还能永生。他的使命就是每天游荡在医院里将已去的人们带到另外一个世界，他却爱上了医院的医生梅姬（梅格•瑞恩 饰），为了能够和心爱的人在一起，塞斯放弃了天使的身份，放弃永生，坠入了凡间。然而，他却并不明白，等待他的，除了动人的爱情，还有弄人的命运。','She didn\'t believe in angels until she fell in love with one.',55000000,198685114,21.272734,6.4,529,114,'1998-04-10','en','/43pfHjaotWHGtf7Jv43LDUe6Q2M.jpg',3.280783115380535,3,'2026-09-10',2,NULL,NULL),(796,'危险性游戏','Cruel Intentions','凯萨琳（莎拉米雪儿吉兰）和萨巴斯丁（雷恩菲力浦）是一对姊弟，他们俩是非常喜欢操纵人的富家子弟。当他们两人看到同是富家子弟的赛西尔（塞玛布莱儿）和安妮（瑞丝怀丝彭），是如此的天真无邪时，他们俩决定玩一个性爱的操控游戏，而赌注是……','In the game of seduction, There is only one rule: Never fall in love.',10500000,75902208,23.449703,6.6,827,97,'1999-03-05','en','/zPIMHb6UeGMJaNiVCRIXSj4Sg7T.jpg',3.424103096322101,3,'2026-09-10',2,NULL,NULL),(801,'早安越南','Good Morning, Vietnam','罗宾．威廉姆斯因主演本片轰动卖座而成为第一线的喜剧巨星。他饰演一名越南美军电台的DJ，每天以妙语如珠的风格主持早晨广播节目，甚受大兵欢迎。后来他深入越南的民间生活，渐渐喜欢上这个国家，以至在节目中发表了一些跟军方宣传有抵触的言论，遭到黯然下台的命运。本片剧本由一位电台主持人根据自己当年在越南的亲身经历撰写而成，故内容特别真实而生动。导演巴里．莱文森以侧面方式来反映越战问题，在同类电影中显得别具新意，此外，穿梭在全片中的多首六十年代流行曲，也可以唤起中年观众的怀旧情绪。','Time to rock it from the Delta to the DMZ!',13000000,123922370,18.362333,7.1,642,121,'1987-12-23','en','/sreISlFUn5TyR41QNjlfAdX5SEW.jpg',3.418598926812948,3,'2026-09-10',2,NULL,NULL),(802,'洛丽塔','Lolita','在大学教授法文的亨博特（James Mason 詹姆斯•梅森 饰）少年时期曾有一段刻骨铭心的经历，当年的初恋情人不幸夭亡，令他此去经年依旧对那些充满青春气息的少女有着别样情感。因工作之需，亨博特寻找住房，因此结识了寡妇夏洛特（Shelley Winters谢利•温特斯 饰）及其妖精一般的女儿洛丽塔（Sue Lyon 休•莱昂 饰）。夏洛特迷上了这位儒雅庄重的大学教师，一心与之交往；而亨博特却迷恋上了青春逼人的洛丽塔，为了和这个精灵长相厮守，甚至违心与夏洛特结婚。他将对洛丽塔的情感全部写进日记，锁入抽屉。直到某天夏洛特打开了潘多拉宝盒，他们的命运从此改变……','How did they ever make a movie of ...',2000000,9250000,23.962109,7.3,395,153,'1962-06-13','en','/qQ39VPZNMRtmhBZ7MsYnF3XvLjH.jpg',3.3126108598099195,3,'2026-09-10',2,NULL,NULL),(805,'罗斯玛丽的婴儿','Rosemary\'s Baby','既令人毛骨悚然，又带有黑色喜剧色彩，是罗曼·波兰斯基的好莱坞首秀。这部极其引人入胜的噩梦之作，忠实改编自艾拉·莱文的畅销小说，由贡献了突破性表演的米亚·法罗主演，饰演一位日渐疑心的准妈妈。她开始愈发怀疑，她那过度热心的老邻居以及只顾自己的丈夫，正在密谋一场针对她和她腹中孩子的邪恶阴谋。在波兰斯基这部亵渎神灵的杰作所催生的数十年神秘题材电影中，其在纯粹心理恐怖层面的地位，始终无人能够超越。','Pray for Rosemary\'s Baby',3200000,33395426,26.180367,7.5,863,136,'1968-06-12','en','/uYgvlHceRFjAFbsNeMInYcLZLUb.jpg',3.5875466285127757,3,'2026-09-10',2,NULL,NULL),(807,'七宗罪','Se7en','“暴食”、“贪婪”、“懒惰”、“嫉妒”、“骄傲”、“淫欲”、“愤怒”，这是天主教教义所指的人性七宗罪。城市中发生的连坏杀人案，死者恰好都是犯有这些教义的人。凶手故弄玄虚的作案手法，令资深冷静的警员沙摩塞（摩根•弗里曼 Morgan Freeman 饰）和血气方刚的新扎警员米尔斯（布拉德•皮特 Brad Pitt 饰）都陷入了破案的谜团中。他们去图书馆研读但丁的《神曲》，企图从人间地狱的描绘中找到线索，最后从宗教文学哲学的世界中找到了凶手作案计划和手段的蛛丝马迹。凶手前来投案自首，这令众人都松了一口气，以为案件就此结束，怎料还是逃不出七宗罪的杀人逻辑，这次凶手瞄准的目标，是那个犯了“愤怒”罪的人……','',33000000,327311859,32.8879,8.38,5765,127,'1995-09-22','en','/e7J95YHcmLtyUtB1yojY76xQO90.jpg',4.393253219204984,3,'2026-09-10',2,NULL,NULL),(808,'怪物史瑞克','Shrek','从前，在一片遥远的沼泽里，住着一个脾气暴躁的怪物史莱克（迈克·迈尔斯 配音）。他珍贵的独居生活，突然被一群恼人的童话人物入侵而彻底打乱。[梦工厂]','The greatest fairy tale never told.',60000000,484409218,67.298732,7.3,4056,90,'2001-05-16','en','/iB64vpL3dIObOtMZgX3RqdVdQDc.jpg',4.093591855688781,3,'2026-09-10',2,NULL,NULL),(809,'怪物史瑞克2','Shrek 2','很久很久以前……史莱克和他拯救的菲奥娜公主结婚了。夫妻俩甩下超级电灯泡加扩音机的驴子，去渡蜜月。小两口卿卿我我，甚是甜蜜。当他们返回沼泽地，收到一封来自“远的要命王国”的邀请函。菲奥娜的父母哈洛国王和雅莉王后想请分别许久的女儿和从未谋面的乘龙快婿回娘家看看。于是这对怪物夫妻乘坐马车浩浩荡荡地赶往“远的要命王国”，当然还得带上他们最丢不起的驴子。正当“远的要命王国”的人们兴高采烈地准备迎接美丽的公主和帅气的驸马爷时，居然从马车上走出一对怪物来……','Once upon another time...',150000000,919838758,47.320801,6.7,2988,93,'2004-05-19','en','/2yYP0PQjG8zVqturh1BAqu2Tixl.jpg',3.821313851188137,3,'2026-09-10',2,NULL,NULL),(810,'怪物史瑞克3','Shrek the Third','“绿怪”史莱克的故事依然在延续。而这一次，爱人朋友却一个都不少。如愿和心爱的菲奥娜公主结成连理之后，史莱克终于能在众朋友的陪伴下在自己的沼泽丛林乐园里过着幸福的小日子了，然而等着他们的却是继承“远的要命王国”的国王和王后之位的使命。别说懒散成性的史莱克了，就连曾经尊贵美丽的菲奥娜公主，也分外挂念沼泽地里的泥藻谷和自由广阔的生活……','Who\'s ready for Thirds?',160000000,798958165,42.986467,6,2278,93,'2007-05-17','en','/aeW63b7chYzWvZJ0Djj4Fh5CXTn.jpg',3.585246872887698,3,'2026-09-10',2,NULL,NULL),(811,'宇宙静悄悄','Silent Running','一名植物学家花费了8年的时间通过太空飞船Valley Forge保存着地球上带出来的植物标本。当接到命令要摧毁标本并返航的时候，他劫持了飞船...','Amazing companions on an incredible journey...that journeys beyond imagination!',1000000,0,11.095414,6.3,177,89,'1972-03-09','en','/ahasZ5HILZHtlrl6cbXgpfk0y8H.jpg',2.9953263164664516,3,'2026-09-10',2,NULL,NULL),(812,'阿拉丁','Aladdin','本片叙述少年阿拉丁的冒险故事。市井小民阿拉丁和猴子好友阿布原本过着快乐自在的生活，一场意外让他获的一张飞天魔毯以及一盏神灯。逗趣的神灯精灵把阿拉丁变成风度翩翩的王子。阿拉丁要赢得茉莉公主的芳心，可是王宫里邪恶的巫师贾方却掳走了神灯和公主。在猴子阿布及飞天魔毯的帮忙下，阿拉丁能够克服自己不是真正王子的心理障碍，勇敢面对挑战，把心爱的公主从贾方的魔掌中救出吗？而且，阿拉丁的第三个愿望也面临抉择：他是要继续假扮王子身份以追求公主，还是要信守诺言放精灵自由呢？本片中由罗宾·威廉姆斯配音的精灵是最抢眼的人物，在片中模仿许多美国的明星、政要，实在令人捧腹。片中利用电脑科技作出神奇洞穴一景，给人视觉上的震撼，是迪士尼电脑动画部门继《美女与野兽》的舞池后又一杰作。本片推出虽然大受欢迎，但却遭到回教组织的强烈抗议，因为在“天方夜谭”的歌词中把他们说成一群“不喜欢你就砍你耳朵”的民族，后来迪士尼在发行录影带时，硬是把这段歌词给换掉，把原声带和录影带这首歌的部分听来比较看看即可发现。','Wish granted!',28000000,504050219,92.982009,7.4,3416,90,'1992-11-25','en','/eLFfl7vS8dkeG1hKp5mwbm37V83.jpg',4.131329593911135,3,'2026-09-10',2,NULL,NULL),(813,'空前绝后满天飞','Airplane!','在这部爆笑恶搞版的灾难片中，机组成员全都食物中毒，一名有心理阴影的前战斗飞行员不得不驾机迫降。','What\'s slower than a speeding bullet, and able to hit tall buildings at a single bound?',3500000,83453539,46.116885,7.1,1074,88,'1980-07-02','en','/nnjCDsvSpg3pTt1E2bmHDHZtCTL.jpg',3.631331516014298,3,'2026-09-10',2,NULL,NULL),(816,'王牌大贱谍','Austin Powers: International Man of Mystery','20世纪60年代最杰出的特工奥斯汀（麦克·迈尔斯饰）是一次次打败“邪恶博士”（麦克·迈尔斯饰）拯救世界的超级英雄。邪恶博士把自己冷冻在外太空，以求来日再战。奥斯汀便也如法炮制，冷冻了自己。30年过去了，美国太空局发现不明飞行物正向地球飞来。邪恶博士回来了。美国特工局马上把斯汀解冻，把战胜邪恶的希望全寄托在他的身上。可是，30年的变化让这位特工措手不及。科技的发展，潮流的变化，奥斯汀的行为全都变成了笑料。美女助手凡妮莎·肯辛顿（伊丽莎白·赫莉饰）挺身而出，帮助奥斯汀完成任务，但怎知越帮越乱。迟到30年的决战变成了无厘头的演出，奥斯汀还能否像30年前打败邪恶博士，拯救地球呢？','If he were any cooler, he\'d still be frozen, baby!',16500000,67683989,36.15716,6.5,1013,94,'1997-05-02','en','/cF22VhaOVpNxP48wj5XEFM3Ys9x.jpg',3.486995881832614,3,'2026-09-10',2,NULL,NULL),(817,'Austin Powers: The Spy Who Shagged Me','Austin Powers: The Spy Who Shagged Me','When diabolical genius, Dr. Evil travels back in time to steal superspy Austin Powers\'s ‘mojo’, Austin must return to the swingin\' \'60s himself – with the help of American agent, Felicity Shagwell – to stop the dastardly plan. Once there, Austin faces off against Dr. Evil\'s army of minions and saves the world in his own unbelievably groovy way.','I\'m back, baby!',33000000,310940086,18.316151,6.2,1011,95,'1999-06-08','en','/jiF7UShERJFn5RtgfBK2lIJrOTc.jpg',3.3934486615079744,3,'2026-09-10',2,NULL,NULL),(818,'王牌大贱谍3','Austin Powers in Goldmember','本已经被特工奥斯汀（麦克•迈尔斯饰）抓住的“邪恶博士”（麦克•迈尔斯饰）成功越狱。这一次，邪恶博士计划了更大的阴谋，他乘坐时间机器回到1975年，妄图绑架奥斯汀的父亲，进而毁灭奥斯汀家族的一切。得知这一计划的奥斯汀不得不抛弃1999年高度发达的资本社会，回到1975年与邪恶博士决斗，而他竟遇到了当时年轻的自己，一个不出名的小人物。回到过去的奥斯汀不仅要打倒邪恶博士，救出自己的父亲，还要正视自己的内心。当然，无厘头的他是不会忘了自己的搞笑功夫。','He\'s still evil... He\'s still deadly... and he\'s still surrounded by frickin\' idiots!',63000000,296655431,40.137264,5.9,979,94,'2002-07-26','en','/n8V61f1v7idya4WJzGEJNoIp9iL.jpg',3.3845055285578414,3,'2026-09-10',2,NULL,NULL),(819,'沉睡者','Sleepers','纽约街头，四名顽皮少年策划着一场好戏捉弄一下街边卖热狗的小贩以打发午后无聊的时光。不料玩笑开大了，他们错手杀死了小贩，被判进入男童院监禁数月。在男童院里，每到半夜，他们都会被狱卒们叫出去，被殴打、鸡奸。当他们重获自由后，四个伙伴决定将这段屈辱永埋心底。  　　多年后，其中两个 伙伴迈克尔（布拉德•皮特 Brad Pitt 饰）成了副检察官，洛伦左（杰森•帕特里克 Jason Patric 饰）成了记者，然而另外两个约翰（朗•埃达德 Ron Eldard 饰）和汤米（比利•克鲁德普 Billy Crudup 饰）却无法走出当年阴影，成了黑帮分子。当约翰和汤米在餐厅碰到当年鸡奸他们的狱卒之一肖恩（凯文•贝肯 Kevin Bacon 饰）时，毫不犹豫射杀了他。为了帮助伙伴，迈克尔想出了一个周全的计划：他们请来著名的糊涂律师为他们作辩护，而迈克尔为肖恩担任控方，努力要将官司打输；洛伦左则通过手段将肖恩卑劣的人品揭露……','When friendship runs deeper than blood.',44000000,165615285,16.245068,7.3,715,147,'1996-10-18','en','/yUpiEk2EojS9ZEXb3nIQonQCYYF.jpg',3.4747974250431595,3,'2026-09-10',2,NULL,NULL),(820,'刺杀肯尼迪','JFK','肯尼迪的遇刺成为了一桩美国历史上的悬案，电影重新审视了那一段历史，到底杀手是一个普通人，还是整个庞大的政治阴谋，真相和幻象，都在调查中渐渐露出端倪。  　　总统遇刺的两小时内，官方认定的凶手即被逮捕，他就是里•哈威•奥斯瓦多。然而巧合的是，在随后的一个小时，这个嫌疑犯却火速被一名流氓杀死。经过调查，官方还是认定里•哈威•奥斯瓦多为真凶。但是，二十多年后的一个美国律师吉姆•加里森（凯文•科斯特纳 Kevin Costner 饰），却发现肯尼迪中弹的蹊跷，从而推测当年官方的误判，接下来，他的侦查牵连着一个历史上的惊天阴谋。','The story that won’t go away.',40000000,205405498,26.82041,7.5,502,189,'1991-12-20','en','/kosdfJ9iX3DhFEquwAZIVFtKI4b.jpg',3.415640983932436,3,'2026-09-10',2,NULL,NULL),(821,'纽伦堡的审判','Judgment at Nuremberg','由斯潘塞．特蕾西、理查德．威德马克等联合主演的本片是一部群星戏。讲述二战后在纽伦堡提审德国纳粹计划的法律关系者，三个被告提审的原因是给犹太人施行断种手术。担任主审判长的是美国人赫鲁特，他主张其中两个被告无罪；而德国司法部长亚林克竟对此事保持沉默，但检查官罗森上校却激烈的指责被告，因此三个人展开激烈的辩论。审讯继续进行下去。而美国的高级官员们希望能在审判中获提德国所犯罪行的良好证明，因此对审判施以极大的压力，但赫鲁特坚守法律的正义立场，给予了最公正的判决。在宣布判决结果时，只有亚林对赫鲁特审判长的态度表示赞赏。这部电影是社会派制作人斯坦利．克雷默将赫鲁特审判长的回忆录搬上银幕，拍摄而成的，以突出的演技来表现伦理与伦理间的纠缠关系。此片获得最佳男主角金像奖及最佳改编剧本奖。','The event the world will never forget',3000000,10000000,13.338539,7.6,155,186,'1961-12-01','en','/3x1oDbjqdNoHKTg38x8S2pUdCWj.jpg',3.0391024939367215,3,'2026-09-10',2,NULL,NULL),(824,'红磨坊','Moulin Rouge!','红磨坊日日歌舞升平。夜总会，康康舞，这是个男人们花天酒地的享乐国度。然而，这儿的爱情，却无比纯净动人。　　克里斯蒂安（伊万•麦戈雷格 饰）是年轻的钢琴诗人，拥有美丽的歌喉。不顾父亲的反对，他来到了蒙马达小镇，这个“追求享乐”的地方。在这儿，他与莎婷（妮可•基德曼 饰）意外的相遇了。莎婷是红磨坊的当家花旦，被誉为“璀璨钻石”，受到很多人的青睐。然而她并不满足于卖唱的生活，想要借助公爵的力量，成为一名真正的巨星。克里斯蒂安的到来，打乱了她结识公爵的计划，却闯入了她的内心。英俊的少年用歌声，向莎婷诉说着“自由”、“美”、“真理”，并给她带来了她从未感受过的“爱”。莎婷找到了自己的梦想，渴望同她心爱的男人一同完成。然而，公爵的阻挠却让一切变得艰难。爱情，要怎样，与命运抗衡。','No Laws. No Limits. One Rule. Never Fall In Love.',52500000,179213434,57.374341,7.4,1300,127,'2001-03-09','en','/2kjM5CUZRIU5yOANUowrbJcRL9L.jpg',3.769498184063898,3,'2026-09-10',2,NULL,NULL),(826,'桂河大桥','The Bridge on the River Kwai','一位英国上校在与日本战俘营指挥官化解分歧后，竟协作督建部下为俘虏者建造一座铁路桥——而对盟军旨在炸毁该桥的计划全然不知。','It spans a whole new world of entertainment!',3000000,33300000,23.109959,7.7,542,161,'1957-10-02','en','/nXrhOAXM90q7h8CxWaFYFIBiZLd.jpg',3.4571373237027143,3,'2026-09-10',2,NULL,NULL),(834,'黑夜传说2：进化','Underworld: Evolution','狼人和吸血鬼之间的大战还在继续。当麦克尔和西丽妮还在企图以自己薄弱的能力阻止这场大战时，阴谋家们的杰作又诞生了――狼人和吸血鬼融合的具有超强能力的种族――“血族”。马克思便是便是这个种族的第二代。他杀死了父亲，夺取了密钥和西丽妮的记忆，救出了一个是狼人、一个是吸血鬼的被囚禁千年的孪生兄弟，企图一统狼人、吸血鬼和人类三大种族。麦克尔和西丽妮这对恋人为了爱，他们必须挫败马克思的阴谋、打败囚禁千年的孪生兄弟……','My God. Brother, what have you done?',50000000,111340801,49.020045,6.4,1528,106,'2006-01-12','en','/kRJJObEaK8BdpvUizY2IPBB7k8O.jpg',3.596342037555366,3,'2026-09-10',2,NULL,NULL),(837,'录影带谋杀案','Videodrome','马克思（James Woods 饰）是一家小型电视台的台长，为提高收视率，马克思四处搜罗带有色情或暴力内容的剧集。马克思的下属哈兰盗用卫星信号，获取了一档名为影视场的节目，内容为写实粗糙的暴力虐待场面，马克思看过这套节目后无法忘怀，对其他剧集丧失了兴趣。电台主播尼奇（Deborah Harry 饰）与马克思相识不久，这名有受虐倾向的女子也被影视场吸引，奔赴节目可能的产地匹兹堡欲参与制作。马克思经人指点拜访影视场的创始人布莱恩教授却没有见到真人，教授寄来的以尼奇为主角的录像让马克思产生了幻觉，马克思再度拜访始知布莱恩早已被杀死，现在的影视场节目由惊人视力公司的巴里负责，马克思一步步落入了巴里设计好的圈套，在巴里与布莱恩两种力量间越陷越深……','First it controls your mind. Then it destroys your body.',5952000,2120439,18.119265,7.1,454,87,'1983-02-04','en','/aJuL4SUtYs09V6zWJZMvZnP783U.jpg',3.317910270819383,3,'2026-09-10',2,NULL,NULL),(838,'美国风情画','American Graffiti','两个高中毕业生在奔赴大学前夜，与伙伴们一同在街头展开最后一场飞车巡游。','Where were you in \'62?',777000,140000000,19.326115,6.9,324,110,'1973-08-01','en','/1tjLivPad2PX8FAzWko7FPIb8d2.jpg',3.206590397461934,3,'2026-09-10',2,NULL,NULL),(840,'第三类接触','Close Encounters of the Third Kind','电力维修工罗伊·尼瑞在外出工作时与一艘奇异飞船发生了非凡接触。反复出现的山脉幻象加剧了他的痴迷，将他推向情感崩溃的边缘。在竭力理解自身遭遇的过程中，他与单身母亲吉莉安结成盟友——她坚信儿子已被外星人掳走。与此同时，由法国专家克劳德·拉孔布领导的国际科学家团队正寻求人类与外星沟通的突破。众人的追寻最终汇聚于怀俄明州偏远地区的相会，一场人类历史上无与伦比的重要事件即将展开。','We are not alone.',20000000,303788635,52.456505,7.2,1098,135,'1977-11-16','en','/yaPx3cK9zGFX3SbcKwxWM1QIbUh.jpg',3.670215321193581,3,'2026-09-10',2,NULL,NULL),(841,'Dune','Dune','In the year 10,191, the world is at war for control of the desert planet Dune – the only place where the time-travel substance \'Spice\' can be found. But when one leader gives up control, it\'s only so he can stage a coup with some unsavory characters.','A world beyond your experience, beyond your imagination.',40000000,30925690,25.876582,6.5,562,137,'1984-12-14','en','/tiWTNR4f6oMYB09059YH8nDke5K.jpg',3.31875814173588,3,'2026-09-10',2,NULL,NULL),(844,'2046','2046','2046 is the sequel to Wong Kar-Wais’ successful box-office hit In The Mood For Love. A film about affairs, ending relationships, and a shared love for Kung-Fu novels as the main character, Chow, writes his own novel and reflects back on his favorite love Su.','Are you still in the mood for love?',12000000,19271312,12.664787,6.9,206,129,'2004-05-20','zh','/jKD7aeiMLrgj8njSE5hpdDM0y3I.jpg',3.072771816237201,3,'2026-09-10',2,NULL,NULL),(846,'X档案：征服未来','The X-Files','五年的追逐化为泡影，随着X档案的关闭，福克斯·穆德（大卫·杜楚尼 David Duchovny 饰）和丹娜·斯科莉（吉莲·安德森 Gillian Anderson 饰）被迫调任处理一些平常的案件。某天，美国得州达拉斯市发生一起爆炸案。虽然穆德和斯科莉极力疏散写字楼内的人群，但爆炸还是夺取了4名无辜者的性命，他们也因此受到上级的指摘。然而事后不久，穆德便得知4名牺牲者早在爆炸之前便已死亡，所谓爆炸案不过是某个神秘部门为了掩盖证据而实施的骗局。该部门据说多年来一直从事外星人的研究，并且他们的研究足以导致人类的毁灭。两名搭档决定彻查此事，但是神秘且难以抗拒的力量无时无刻不在阻挠他们追寻真相的脚步……  本片为同名美剧的第一部电影。','Fight the Future',66000000,189198313,18.59991,6.6,488,121,'1998-06-19','en','/4MErIW61y8rO0o5me8yV9QZZgRI.jpg',3.279581345953239,3,'2026-09-10',2,NULL,NULL),(848,'Dragonslayer','Dragonslayer','The sorcerer and his apprentice Galen are on a mission to kill an evil dragon in order to save the King’s daughter from being sacrificed in accordance to a pact that the King himself made with the dragon to protect his kingdom. A fantasy film from Disney Studios that exhausted all possible visual effects of the time.','In the Dark Ages, Magic was a weapon. Love was a mystery. Adventure was everywhere... And Dragons were real.',18000000,14110013,3.258422,6.5,67,108,'1981-06-26','en','/92VXAEwbjebYqTeUa7uX5bBtDuD.jpg',2.767268859806396,3,'2026-09-10',2,NULL,NULL),(849,'国王与怪兽','Krull','这是一个发生在很久以前的故事。有一个神秘的预言，如果谁可以娶到丽萨公主为妻，谁就可以成为这个世界的主宰，而他们的儿子将统治整个银河。','A world light-years beyond your imagination.',27000000,16519460,9.904881,5.8,129,117,'1983-07-29','en','/i6pEnXkhy98fXzImCexZiYXz7cM.jpg',2.899269242694816,3,'2026-09-10',2,NULL,NULL),(850,'圣诞故事','A Christmas Story','四十年代，9岁的孩子拉尔夫认为圣诞节最完美的礼物就是一把Red Ryder BB gun，但是所有的人都认为这是非常危险的礼物，甚至不惜与老师，父母甚至圣诞老人对立。  　　本片最有意思的是描写了一个孩子丰富的世界，很多地方让人不禁捧腹，又想到我们小时候。拉尔夫的独白是一位成年男子的声音，同样也有意思。','Peace, Harmony, Comfort and Joy... Maybe Next Year.',0,19294144,15.128316,7.4,344,94,'1983-11-18','en','/qfhQ7tlGI3wIEP5hthURLXWWQTp.jpg',3.2611337502406594,3,'2026-09-10',2,NULL,NULL),(853,'兵临城下','Enemy at the Gates','斯大林格勒战役中，瓦西里（裘德•洛 Jude Law 饰）是一个威震部队的神枪手。他的好枪法百发百中，令敌人闻风丧胆。\r 为了激励士气，树立榜样，瓦西里的战友——苏军文宣部军官丹尼洛夫（约瑟夫•费因斯 Joseph Fiennes 饰）在报纸上大量刊登瓦西里的英雄事迹，令瓦西里的形象更为高大。然而，坦妮娅（雷切尔•薇姿 Rachel Weisz 饰）的出现，让瓦西里和丹尼洛夫都同时迷恋上了这个飒爽女兵。但塔妮娅喜欢的是瓦西里，这让丹尼洛夫大为妒忌。\r 另一方面，德军派出了他们的狙击手康尼（艾德•哈里斯 Ed Harris 饰），让同是神枪手的他抗衡瓦西里。在硝烟弥漫的战场上，瓦西里和康尼开始了斗智斗勇的决斗。','Some Men Are Born To Be Heroes.',68000000,96976270,41.273567,7.2,999,131,'2001-03-13','en','/tJSD1pkdtdMhj2U9NZInXgUsmRN.jpg',3.616716082112098,3,'2026-09-10',2,NULL,NULL),(854,'变相怪杰','The Mask','银行小职员斯坦利（金•凯瑞 Jim Carrey 饰）老实本分，过着和所有老实人一样的平凡生活。一次，斯坦利在接待金发美女蒂娜（卡梅隆•迪亚茨 Cameron Diaz 饰）时深深恋上了对方，不料蒂娜却是黑帮头目多利安（彼得•格林纳 Peter Greene 饰）抢劫银行前派来打探地形的。多利安随后成功抢劫了斯坦利所在的银行。一晚，斯坦利意外获得了一个奇怪的面具。戴上面具后的斯坦利变得力大无比、身手敏捷。斯坦利开始四出捉弄平日欺负他的人，并抢走了多利安劫得的巨款，与蒂娜在夜总会尽情飞舞。多利安知道了面具的威力后，用计夺走了面具，斯坦利则被关进了监狱。斯坦利最后能否凭自己的智慧夺回面具，与蒂娜有情人终成眷属?','From zero to hero.',23000000,351583407,85.30318,6.6,2472,101,'1994-07-29','en','/jPC2eYub74zwf2tPGVtzSlBW6Oy.jpg',3.8381816108195315,3,'2026-09-10',2,NULL,NULL),(855,'黑鹰坠落','Black Hawk Down','导演雷德利·斯科特改编自真实战争故事，讲述1993年一支美军特种部队被派往索马里，旨在推翻政府并为饥民提供粮食与人道主义援助，却遭到袭击的经过。','Leave No Man Behind.',92000000,172989651,44.455166,7.2,1811,144,'2001-12-28','en','/7fU5dSqKRL4XHeEUz62rCKBfYok.jpg',3.797048592461967,3,'2026-09-10',2,NULL,NULL),(857,'拯救大兵瑞恩','Saving Private Ryan','1944年，诺曼底登陆期间。经历奥马哈海滩的惨烈战斗后，约翰·米勒上尉突然接到一项特殊命令：深入德军控制区，寻找失散的伞兵詹姆斯·瑞恩。瑞恩家中四兄弟均在军中服役，其中三人已经先后阵亡，为了避免他们的母亲失去最后一个儿子，美军决定将瑞恩找到并安全送回家。米勒只得带领七名士兵离开正在推进的部队，深入危机四伏的法国战场寻找一个素未谋面的人。随着搜寻不断深入，小队不仅要面对随时可能出现的德军，也开始无法回避同一个问题：为了拯救一个人的生命，让更多人冒险甚至牺牲，究竟是否值得……','The mission is a man.',70000000,481840909,76.041867,7.9,5048,169,'1998-07-24','en','/uqx37cS8cpHg8U35f9U5IBlrCV3.jpg',4.327678142844249,3,'2026-09-10',2,NULL,NULL),(859,'Dangerous Liaisons','Dangerous Liaisons','Dangerous Liaisons is the film based on the novel of the same name by Choderlos de Laclos set in 18th century France. Marquise de Merteuil’s asks her ex-lover Vicomte de Valmont to seduce the future wife of another ex-lover of hers in return for one last night with her. Yet things don’t go as planned in this love triangle drama.','Lust. Seduction. Revenge. The Game As You\'ve Never Seen It Played Before.',14000000,34670720,14.480628,7,257,119,'1988-12-16','en','/7etDozwd9Pf5oCcyo4h1Hki6U13.jpg',3.142098330626373,3,'2026-09-10',2,NULL,NULL),(860,'战争游戏','WarGames','大卫•莱特曼（马修•布罗德里克饰）是一位天才少年，他将业余时间全都投在了电脑游戏上。一天，他通过搜索，搜到了一台网络电脑，简单破解后，他开始玩一个叫做“全球热核战争”的游戏，一个模拟世界大战的游戏。\r 　　但大卫并不知道，隐藏在“全球热核战争”之后的，竟是美国军方的战争操作计划响应系统（WOPR）。这个机密系统控制着美国军方的武器，而大卫启动的“全球热核战争”游戏竟然导致系统自动准备发射核弹！\r 　　第三次世界大战一触即发，各国军队严阵以待，而大卫不得不行动起来，他要用自己的黑客技术阻止电脑发射核弹，阻止这一切。','Is it a game, or is it real?',12000000,79567667,23.161754,7,504,114,'1983-06-03','en','/qVbIbxz6bORlKA6aM7AAQg7bfQ9.jpg',3.3472032528582463,3,'2026-09-10',2,NULL,NULL),(861,'全面回忆','Total Recall','未来世界中，工程工人道格拉斯（Arnold Schwarzenegger 饰）被持续的梦境困扰，那是一系列发生在红色火星上的体验。道格拉斯在广告上发现了回忆旅行公司的介绍，虽然同事警告他这种虚拟旅行可能会危害人类的大脑，但比起亲自去一趟充斥着反政府武装的火星，回忆旅行公司确是一个不错的选择。道格拉斯如愿接受了回忆旅行的服务，但是虚拟记忆的过程突然出现错误，自此一系列不可思议的经历出现在道格拉斯的身上，先是妻子劳瑞（Sharon Stone 饰）向他发起攻击并承认自己是监视道格拉斯的间谍，后来有陌生人出现帮助他逃脱并指出他是火星独裁者针对反政府武装派出的特工，结果因为一名女子梅丽（Rachel Ticotin 饰）改变了立场……道格拉斯动身前往火星，那里有一切的谜底，或者一切又只是梦境一场？','They stole his mind, now he wants it back.',65000000,261317921,43.129703,7.1,1710,113,'1990-06-01','en','/wVbeL6fkbTKSmNfalj4VoAUUqJv.jpg',3.7566528799569525,3,'2026-09-10',2,NULL,NULL),(862,'玩具总动员','Toy Story','在胡迪的带领下，安迪的玩具们一直在他的房间里快乐地生活着，直到安迪的生日将巴斯光年带入这个大家庭。由于害怕自己在安迪心中的地位被取代，胡迪对这位新成员心存忌惮并密谋排挤。然而当各种意外将巴斯和胡迪与主人分离后，这对冤家逐渐学会了搁置分歧、携手共渡难关。[皮克斯]',NULL,30000000,373554033,73.640445,7.7,5269,81,'1995-10-30','en','/uXDfjJbdP4ijW5hWSBrPrlKpxab.jpg',4.28127457455253,3,'2026-09-10',2,NULL,NULL),(863,'玩具总动员2','Toy Story 2','胡迪和巴斯光年等一班玩具们经历了上回的历险后友谊日益增强。同时，多迪的看家狗也成为了他们要好的朋友，大家在一起真是其乐融融。一天，胡迪不幸失足掉到院子里，被经过的一个胖玩具商偷走，并把他带回到了一个玩具工厂。当胡迪惊恐万分急着要逃出工厂时，却发现这里有许多的牛仔玩具，并且他们见到胡迪后显得十分激动。原来，这些玩具都是胖玩具商搜罗来的，他们是过去一部热门卡通片中的人物，这里就缺少胡迪这个主角了。为了让胡迪明白自己的身世，他们为胡迪播放了牛仔卡通片的剧集，胡迪这才知道了自己过去的很多英雄故事，也才知道这些玩具都是当年和自己一起出道的伙伴，同时他还知道了一个他不安的消息，胖玩具商将要把他和这些牛仔伙伴一块儿被卖到日本的一家玩具博物馆去！在家里所有的玩具都很担心胡迪，因此巴斯光年自告奋勇去寻找胡迪，但是当他们在玩具工厂找到胡迪时，他却似乎不再愿意回去过那平凡的生活……','The toys are back!',90000000,497366869,73.575118,7.3,3806,92,'1999-10-30','en','/4rbcp3ng8n1MKHjpeqW0L7Fnpzz.jpg',4.091127158192204,3,'2026-09-10',2,NULL,NULL),(864,'冰上轻驰','Cool Runnings','影片前部分集中描绘四名黑人运动员如何排除万 难，踏出冬季奥运会第一步，而后半段则是惯有的励志模式，对于未尝试过摄氏零下二十五度地问的牙买加运动员来说，他们既要面对天时、地理、人和等各项不利条件，亦要忍受嘲笑轻视自己的国内外观众；而观众又如何凭着坚硬的遗志，唤醒运动健儿向着目标勇往前进的精神。三个牙买加田径好手，在奥运会选拔赛不幸同时失足跌倒，另三人梦想变成泡影。不过，其中的狄礼雄心勃勃决定转而参加前所未有的雪橇比赛，并请乐天搞笑的好友辛加协助，落魄潦倒的昔日冠军艾荣出任教练，组成牙买加第一雪橇队。本片喜剧成分相当丰富。诸如四人筹集经费、训练过程、及气候差异等大造惹笑效果的背后，却带出一个振奋人心的讯息，值得捧场。','One dream. Four Jamaicans. Twenty below zero.',14000000,154864401,22.409117,6.8,491,98,'1993-09-30','en','/6fXuGEb7EqGmAeUodxm7l5ELPZ.jpg',3.3139846764224,3,'2026-09-10',2,NULL,NULL),(865,'The Running Man','The Running Man','By 2017, the global economy has collapsed and American society has become a totalitarian police state, censoring all cultural activity. The government pacifies the populace by broadcasting a number of game shows in which convicted criminals fight for their lives, including the gladiator-style The Running Man, hosted by the ruthless Damon Killian, where “runners” attempt to evade “stalkers” and certain death for a chance to be pardoned and set free.','A game nobody survives. But Schwarzenegger has yet to play.',27000000,38122105,30.131498,6.4,703,101,'1987-11-13','en','/9TWXzoJvEOK4o72XyoW6urxkpwu.jpg',3.3687379344498303,3,'2026-09-10',2,NULL,NULL),(866,'Finding Neverland','Finding Neverland','Finding Neverland is an amusing drama about how the story of Peter Pan and Neverland came to be. During a writing slump play writer J.M. Barrie meets the widowed Sylvia and her three children who soon become an important part of Barrie’s life and the inspiration that lead him to create his masterpiece “Peter Pan.”','Where will your imagination take you?',25000000,116766556,34.160448,7.2,1223,106,'2004-10-17','en','/xYVAKXyU006qcza0NyRESr1KKDp.jpg',3.6601493085661816,3,'2026-09-10',2,NULL,NULL),(868,'Tsotsi','Tsotsi','The South African multi-award winning film about a young South African boy from the ghetto named Tsotsi, meaning Gangster. Tsotsi, who left home as a child to get away from helpless parents, finds a baby in the back seat of a car that he has just stolen. He decides that it his responsibility to take care of the baby and in the process learns that maybe the gangster life isn’t the best way.','In this world... Redemption comes just once.',3000000,9879971,2.504169,6.9,94,94,'2005-08-18','af','/6iVt3jrygcl1406EtqvRAxQWt2N.jpg',2.8553627869308267,3,'2026-09-10',2,NULL,NULL),(869,'决战猩球','Planet of the Apes','公元2029年，飞行员利奥·戴维森（马克·沃尔伯格饰）驾驶着一架小型太空巡洋舰从空间站出发，准备完成一次常规的侦察任务。途中，利奥意外地被卷进时间空洞，被迫降落在了一个陌生、奇异的星球上。才逃离危险的利奥刚一走出舱门，就被一群凶恶的人猿抓了起来。原来，这是一个由人猿统治着的星球，在这里，人类没有身份和地位，只能充当猿类的奴隶。在母猩猩艾丽和其他人类的帮助下，利奥开始了与人猿军队首领塞德（蒂姆·罗斯）及大将阿塔尔（迈克尔·克拉克·邓肯）之间的战斗。利奥他们不仅要在塞德的追杀下活命，还要伺机闯入人猿星球的禁区，去揭开一个关于人类历史的重大秘密——这将决定所有人类的未来。这个惊人的秘密到底是什么？利奥他们能顺利完成重任吗？人猿星球的命运会改变吗……','You\'ll be sorry you were ever born human',100000000,362211740,51.188633,5.6,1243,119,'2001-07-25','en','/p6LmcFFBlb0GEWs203XK8CGQQbg.jpg',3.4011566668168913,3,'2026-09-10',2,NULL,NULL),(872,'雨中曲','Singin\' in the Rain','1927年，由唐·洛克伍德（吉恩·凯利 饰）和丽娜·雷蒙德（简·哈根 饰）主演的《皇家流氓》在好莱坞首映。由于丽娜刺耳的嗓音无法匹配其夺目的外貌，为了维护明星形象，宣传部只得安排唐一人讲话。首映后，由于钢琴师科斯莫·布朗（唐纳德·奥康纳 饰）的汽车爆胎，为了躲避疯狂的影迷，唐意外结识了能歌善舞的凯西·塞尔登（黛比·雷诺斯 饰），并被其深深吸引。数周后，首部有声电影《爵士歌手》爆红，唐与丽娜的新片《决斗骑士》不得不临时改变拍摄方式，而凯西也成为歌舞片演员。因预映口碑极差，科斯莫提议将《决斗骑士》改为歌舞片，由凯西为丽娜配音，凯西积极附议。与凯西吻别后，唐心花怒放，在雨中载歌载舞。科斯莫的计划能否奏效？幕后的凯西能否走到台前接受观众的掌声？','What a Glorious Feeling!',2540800,7200000,36.556954,7.8,727,103,'1952-04-10','en','/7XRfsgxWPUbCwe4w3EHYTfSmadR.jpg',3.601211407143449,3,'2026-09-10',2,NULL,NULL),(873,'紫色','The Color Purple','故事发生在1909年的美国，西丽和南蒂是一对情同手足的姐妹，虽然作为黑人女性她们必须面对残酷的现实，但有了彼此的陪伴，尚可苦中作乐，直到西丽被迫嫁给了黑人男子亚伯特。亚伯特性格粗暴，对于他来说，西丽比一个女佣好不了多少，动辄拳打脚踢，他真心爱着的是一个远在他乡的叫做夏戈的女演员。南蒂前来陪伴西丽，亚伯特却因强暴她未遂而将她赶出家门，这一别，西丽彻底的失去了南蒂的音讯。在苦闷的生活中，女人们试图挣扎和抵抗，但最终无一例外的都屈服于歧视和强权之下，夏戈的到来改变了这一切，她独立坚强，从不因为自己女性的身份而有所畏惧，她的乐观给了西丽反抗的勇气，终于，她拿起行李离开了亚伯特，成立了自己的裁缝店，生意红火。而突然有一天，南蒂和自己幸福的家庭再一次出现在了西丽的眼前，出现在了那篇紫色的花海之中。','It\'s about life. It\'s about love. It\'s about us.',15000000,146292009,17.571533,7.7,338,154,'1985-12-18','en','/6bvxkcTAXyqxGRwo38mxw92D6Xr.jpg',3.28995396553186,3,'2026-09-10',2,NULL,NULL),(874,'A Man for All Seasons','A Man for All Seasons','A Man for All Seasons is the filmed version of the life of Thomas More. An English man comes to Sir Thomas More to ask if he can divorce his wife since King Henry VIII has made it illegal. Sir Thomas More stands up in opposition to the King even though he knows he’s risking his own life. An award winning film from 1966.','...a motion picture for all times!',3900000,28350000,9.541688,7.5,89,120,'1966-12-12','en','/kcwcqMitcnRO1SySlX1HKVn7yUV.jpg',2.8780155805274155,3,'2026-09-10',2,NULL,NULL),(879,'Hook','Hook','The boy who wasn\'t supposed to grow up—Peter Pan—did just that, becoming a soulless corporate lawyer whose workaholism could cost him his wife and kids. But a trip to see Granny Wendy in London, where the vengeful Capt. Hook kidnaps Peter\'s kids and forces Peter to return to Neverland, could lead to a chance at redemption, in this family-oriented fantasy from director Steven Spielberg.','What if Peter Pan grew up?',70000000,300854823,33.648404,6.6,1532,144,'1991-12-11','en','/wKqoUD8iSXLoy0WIFPb5yNnPFta.jpg',3.6025115946352897,3,'2026-09-10',2,NULL,NULL),(881,'好人寥寥','A Few Good Men','在美国驻古巴关达那摩湾的海军基地，两名海军陆战队员道森和多尼被指控杀害了另一名士兵圣地亚哥。海军律师丹尼尔·卡菲（汤姆·克鲁斯 Tom Cruise 饰）和助手山姆被派接手此桩案件，他们调查到圣地亚哥曾希望调离基地，还举报过道森。卡菲本想进行庭外协调，争取两年刑期。然而 两名士兵坚持自己无罪，他们对圣地亚哥的行为是执行上级给他们下达的“红色条规”。所谓红色条规，就是一种军官默许的由士兵私下进行的训诫条规。  　　卡菲、山姆以及另一名女律师盖洛维（黛米·摩尔 Demi Moore 饰）组成辩方律师进行调查，而基地指挥官杰塞普上校（杰克·尼科尔森 Jack Nicholson 饰）是本案的关键人物，他拒绝了圣地亚哥的调离申请，对他下达了“红色条规”，事后私自篡改了飞行记录。卡菲虽然知道真相，却苦于证据不足，这种情况下若是指证杰塞普上校还会给自己带来麻烦。这场关乎正义的诉讼案，会有一个怎样的结果？',NULL,40000000,243240178,40.379966,7.1,877,138,'1992-12-11','en','/rx08NCtG8rD7r3qWW0pfzvNw9IB.jpg',3.5595805136696956,3,'2026-09-10',2,NULL,NULL),(887,'黄金时代','The Best Years of Our Lives','三位二战老兵回到美国小镇的家中，发现他们与家人的生活早已不复往昔。','Three wonderful loves in the best picture of the year!',2100000,23650000,8.38717,7.6,143,172,'1946-12-25','en','/gd5EoAU4MM57sW3vlWxJ0NMM8cV.jpg',3.005345005433916,3,'2026-09-10',2,NULL,NULL),(888,'摩登原始人之摔跤赛攻击波','The Flintstones','故事的背景是公元前二百万年，恐龙的石器时代，某个小镇住着一群石器时代的原始人，但他们的意识却非常现代。聪明的弗雷德用石头、动物骨骼和毛皮制作出电话机、照像机甚至影印机。家庭厨房设备还有以猪提供动力的环保型垃圾处理装置。','Yabba-Dabba-Doo!',46000000,341631208,28.964162,5,543,91,'1994-05-26','en','/3xaN8vlVw5cUDyJ4m6xWNBAonmz.jpg',3.1251905522063637,3,'2026-09-10',2,NULL,NULL),(889,'摩登原始人2','The Flintstones in Viva Rock Vegas','弗林特一家又来了。Flintstones和Rubbles夫妇前往Rock Vegas，Fred希望能讨好可爱的Wilma。没有什么会阻碍爱情，除了纵容的奇普·洛克菲勒，他是出生在贝斯维尔的花花公子，但却在残酷的摇滚小镇拉斯维加斯成功了。弗雷德会赢得威尔玛的爱吗？','Get ready to rock!',83000000,59468275,6.248309,4.4,134,90,'2000-04-28','en','/o4pijWLImp7TQ64Yg2nuUYzdiDy.jpg',2.8333927701658403,3,'2026-09-10',2,NULL,NULL),(905,'潘多拉的魔盒','Die Büchse der Pandora','露露（露易丝·布鲁克斯 Louise Brooks 饰）是一个妓女，而她的相好史恩先生已经五十多岁了，有一个孩子阿尔瓦。史恩先生要和一个医生的女儿结婚，露露不甘，逼迫史恩先生娶她。史恩先生迫于无奈只能娶了她。在婚礼上，史恩先生又发现露露和她的皮条客史考西的亲密关系，拿出了一把手枪。史恩在与露露的争执中被子弹击毙。法院判决露露犯了杀人罪。露露和同样迷恋她的阿尔瓦、一名也爱着她的女伯爵、史考西等人一起出逃。后来露露和阿尔瓦、史考西一起逃到了伦敦。在圣诞夜，露露在街上遇到了臭名昭彰的连环杀人犯——开膛手杰克。她带着他进了房间......',NULL,0,0,1.824184,7.6,45,109,'1929-01-30','de','/pPUr6mtHlOVlgQjg2xeJgZZEgn2.jpg',2.6952900876050756,3,'2026-09-10',2,NULL,NULL),(907,'日瓦戈医生','Doctor Zhivago','幼年丧母的日瓦戈（Omar Sharif 饰）被过继给母亲的朋友，自此与继母一家的小女儿冬妮娅一同成长，并顺利修完医学专业，成为了一名优秀的医生。在另一条平行的生命线上，出生于裁缝之家的拉娜（Julie Christie 饰）正是十七岁的金色年华，母亲的情人维克多不时骚扰她，热衷于工人革命的未婚夫帕夏更让拉娜日日为其担忧。在工人运动风起云涌的日子里，日瓦戈目睹了当局对工人的残酷镇压，拉娜则因帕夏被卷入工人运动而遭到维克多的玷污，由于维克多的关系，日瓦戈与拉娜的人生终于汇合，在不久后混乱的一战中，他们终于不顾各自的伴侣陷入了热恋……不久布尔什维克掌握政权，返回家乡与冬妮娅团聚的日瓦戈发现生活却每况愈下，以至他们不得不远赴乡村谋生，岂料在遥远的北方村落，日瓦戈再次与拉娜相遇……  　　本片根据Pasternak的同名小说改编，获1966年奥斯卡最佳美术指导、最佳摄影等多项专业褒奖。','Turbulent were the times and fiery was the love story of Zhivago, his wife and the passionate, tender Lara.',11000000,111858363,12.854853,7.4,247,197,'1965-12-22','en','/r0Iv2BiCFYDnzc6uU1q3AJ56igT.jpg',3.158169865785466,3,'2026-09-10',2,NULL,NULL),(913,'天罗地网','The Thomas Crown Affair','一个炎热的夏日，纽约大都会艺术博物馆内突然停电，馆内一幅正在展出的价值一亿美金的克劳迪·莫奈的名画被手段高明的窃贼盗走。由于馆内红外线监控系统在夏日高温下全然失去功效，因此神秘的作案者在现场几乎没留下任何作案痕迹。将莫奈名画窃走的神秘窃贼正是亿万富翁托马斯·克劳恩，这位拥有私人飞机、豪华游艇及上百仆从的企业界大亨住在曼哈顿的一幢豪宅中。克劳恩的钱财几乎可买来世上一切可用金钱买到的东西，但他却只对那些无法用金钱买到的东西感兴趣。克劳恩在光天化日之下窃走名画一不为钱，二不为艺术收藏，只因博物馆一再声称此画概不对外出售，有着极强征服欲的克劳恩最喜欢做的便是那些令他深感刺激的事情。','How do you get the man who has everything?',48000000,124305181,18.102572,6.6,339,113,'1999-08-06','en','/ulsEC0fUpOlPYy09nxIaQfQcXgA.jpg',3.187308218663757,3,'2026-09-10',2,NULL,NULL),(920,'赛车总动员','Cars','汽车世界中，一年一度的活塞杯再次拉开序幕。红色跑车“闪电”麦坤和“冠军”、“路霸”是冠军最有力的竞争者。作为新人，麦坤具有极高的天赋，同时也是一个目空一切的家伙。经过紧张激烈的对抗，这三辆车同时冲过终点线。由于无法判定最终优胜者，组委会决定一个月后在加州洛杉矶召开一次只有这三辆车参加的殊死战，只有最后的胜者才能捧得活塞杯。信心满满麦坤和搭档拖车麦大叔早早启程。但是长时间的疲劳驾驶，令麦大叔不慎将麦坤丢在半路。麦坤东闯西撞，无意间来到了被众车遗忘的油车水镇。因躲避警长的追捕，麦坤毁坏了小镇的马路。在法官哈迪逊韩大夫和律师保时捷莎莉的裁决下，他被迫留在这里修路。短短几天相处，麦坤和小镇的居民渐渐融洽起来，同时他也爱上了美丽的莎莉。只不过，路终有修完的时候，未完的比赛仍在等待着他……','Ahhh... it\'s got that new movie smell.',120000000,461983149,82.643036,6.6,3877,117,'2006-06-08','en','/2Touk3m5gzsqr1VsvxypdyHY5ci.jpg',3.9399499540248017,3,'2026-09-10',2,NULL,NULL),(921,'Cinderella Man','Cinderella Man','The true story of boxer, Jim Braddock who, in the 1920’s after his retirement, has a surprise comeback in order to get him and his family out of a socially poor state.','One man\'s extraordinary fight to save the family he loved.',88000000,108539911,24.100863,7.3,616,144,'2005-06-02','en','/4q1tydxW2acjQQa2iupo6vgdMX9.jpg',3.4471902231808667,3,'2026-09-10',2,NULL,NULL),(924,'活死人黎明','Dawn of the Dead','看似平凡的一天，护士安娜（莎拉·波利 Sarah Polley 饰）正准备和丈夫路易斯（Justin Louis 饰）共享快乐的周末，却不知一场恐怖、致命的瘟疫正在大肆蔓延。被瘟疫感染的丧失人性，转而变成嗜血如命、残暴无情的活死人。安娜的丈夫和女儿薇薇安（Hannah Lochner 饰）无一幸免，她侥幸从家中逃生，却发现整个城市都已变成活死人的天下，幸存者所剩无几，眼前的世界宛如人间地狱。是时瘟疫蔓延全球，各国都已陷入瘫痪状态之中。  安娜驾车一路逃亡，最终与警察肯尼斯（文·雷姆斯 Ving Rhames 饰）以及其他几名幸存者躲在一家购物中心内。然而这终究不是一个长久的避难场所，活死人闻风而至，时刻都有冲进来的危险。安娜他们必须团结一心，逃出生天……','When the undead rise, civilization will fall.',28000000,102356381,44.529429,6.8,1016,101,'2004-03-19','en','/5VSPraq8dwVTgaEea0YPsOoaUg.jpg',3.559263150739428,3,'2026-09-10',2,NULL,NULL),(925,'为所应为','Do the Right Thing','这部斯派克·李1989年的杰作以布鲁克林贝德-斯图“不成功便成仁”街区的某个街坊为背景，在盛夏时节展开，确立了李作为独具社会关怀的编剧与导演的非凡地位。在短短一天内，一群令人难忘的角色——戴镇长、修女妈妈、爱老爹先生、蒂娜、甜心迪基·威利、巴金·奥特、电台拉希姆、萨尔、皮诺、维托，以及李饰演的穆基等——原本轻松的互动，随着种族分歧引发的紧张升级而演变为激烈对峙，最终爆发为暴力冲突。在公敌乐队《对抗权力》的反复呐喊中，本片成为美国电影的里程碑之作，其政治与情感冲击力及现实意义，至今仍与初登银幕时同样振聋发聩。','It\'s the hottest day of the summer. You can do nothing, you can do something, or you can...',6500000,37295445,15.580335,7.6,292,120,'1989-06-30','en','/63rmSDPahrH7C1gEFYzRuIBAN9W.jpg',3.2304915995026837,3,'2026-09-10',2,NULL,NULL),(926,'惊爆银河系','Galaxy Quest','《银河探险》是一套二十年前讲述太空NSEA保护者故事的电视科幻剧集，1982年停播，接近二十年后，饰演指挥官的贾森 ，饰演博士的亚历山大，以及格温 等几位演员再度聚首，参加一系列粉丝见面会和商业活动。期间，一群自称塞米安人的怪诞粉丝跟随贾森到他的家里，疲惫的贾森发现这群塞米安人并非疯狂粉丝，而是真正的外星人！没有欺骗能力的塞米安人在收看《银河探险》后以为贾森等人是真正的太空英雄，他们在和宇宙恶徒萨里斯的对决中节节败退，于是远赴地球寻求保护者们的帮助，贾森和亚历山大等船员假戏真做，帮助塞米安人对抗宇宙邪恶势力……','A comedy of Galactic Proportions.',45000000,90683916,30.816341,6.9,710,102,'1999-12-23','en','/fZXSwgZknp81vmciTb86rw0MejV.jpg',3.4467032708365943,3,'2026-09-10',2,NULL,NULL),(927,'小精灵','Gremlins','比利的父亲在唐人街买了一份圣诞礼物给比利，尽管比利对这份礼物――小魔怪宠爱有加，但原来养小魔怪有三大规条：一，别让它接触水；二，别让它接触阳光；三，千万不要午夜后喂它。比利没料到违反规条竟会带来天大的麻烦，而麻烦正以倍数急剧增长，令比利的小镇陷入空前的混乱，一向宁静的圣诞夜变成小魔怪肆虐的狂欢捣乱夜……  幕后制作：本片有黑色幽默的味道，而1990年的续集更像是针砭时政的讽刺喜剧。','Don\'t get him wet, keep him out of bright light, and never feed him after midnight.',11000000,153083102,45.072136,6.9,1596,106,'1984-06-07','en','/6m0F7fsXjQvUbCZrPWcJNrjvIui.jpg',3.7005801708452104,3,'2026-09-10',2,NULL,NULL),(928,'小精灵2','Gremlins 2: The New Batch','剧情描述一家研究DNA遗传工程的药厂实验室将小精灵加以实验，结果制造了一群破坏力强烈的怪物，将大楼搞得人仰马翻，男女主角费尽九牛二虎之力才把这群怪物消灭。','Here they grow again.',50000000,41482207,33.98637,6.2,652,106,'1990-06-15','en','/35F5yD7MljvBE2AC0NHAVCoPGEi.jpg',3.3312535441365347,3,'2026-09-10',2,NULL,NULL),(935,'奇爱博士','Dr. Strangelove or: How I Learned to Stop Worrying and Love the Bomb','斯坦利·库布里克对冷战焦虑的痛苦式幽默诠释，是好莱坞有史以来对人类愚行最尖锐的讽刺之一。千面戏骨彼得·塞勒斯一人分饰三个截然不同的角色：皇家空军上校莱昂内尔·曼德雷克——怯懦地试图阻止一位精神失常的美军将军下令对苏联发动核袭击；优柔寡断且始终惊愕的美国总统默金·马夫利，不得不将噩耗告知苏联总理；以及片名所指的奇爱博士本人，那位身坐轮椅、有着纳粹过往的总统顾问。在几乎所有难以想象的场景中发掘出荒诞笑料，本片是一部颠覆性杰作，正式宣告库布里克成为无与伦比的风格大师与漆黑讽刺家。[标准收藏]','The hot-line suspense comedy',1800000,9440272,41.996783,8,1442,95,'1964-01-29','en','/gHm96BRW4GoI339rF1vYoYTB6Qe.jpg',3.885530595802922,3,'2026-09-10',2,NULL,NULL),(943,'致命武器3','Lethal Weapon 3','马丁（梅尔·吉布森 Mel Gibson 饰）与罗格（Danny Glover 饰）这对儿老搭档再次出马，但是一开场就将歹徒的炸弹引爆毁掉了整座大楼，罗格退休前一星期的生活就这样开始了。第二天，两人在街上偶遇假冒解款人员的匪徒，一番苦战将对方擒获，但是警队却将此案移交内政部美丽的女探员劳娜（Rene Russo 饰）负责。关押中的犯人被警察查韦斯射杀，马丁追捕对方但终于错失。罗格在一次街头枪战中射杀了儿子的好友，满心愧疚让他暂时离开调查。马丁与劳娜的组合逐步介入了案件幕后一起武器贩卖集团的交易，该集团实力强大，与近期的大宗枪支失窃案有密切关系，马丁的出现，打乱了对方的步骤。很快罗格归队，三人向犯罪集团发起了最后的冲击。  　　本片获1993年MTV电影奖最佳动作场面奖。','The magic is back again!',35000000,321731527,36.172182,6.4,811,118,'1992-05-15','en','/98VX3Ma5HuhGHWVtHNFXEJyxrQb.jpg',3.416605793610219,3,'2026-09-10',2,NULL,NULL),(944,'致命武器4','Lethal Weapon 4','马丁（梅尔·吉布森 Mel Gibson 饰）和罗杰（丹尼·格洛弗 Danny Glover 饰）是相识多年的老友兼同事，两人都是警察。一次在与共同的好友盖茨（乔·佩西 Joe Pesci 饰）相约出海的途中，三人偶遇了一艘非法偷渡的船只。身为警察的马丁自知绝不能对此坐视不管，于是展开了与黑道分子的激烈斗争。\r 　　在这批偷渡客中，有一位名为阿洪（高雄 饰）的男子，善良的罗杰收留了他和他无处可去的家人，没想到正是这一举动激怒了危险的黑帮教头王（李连杰 饰），为了从罗杰的手里将洪抢走，王不惜干下了许多伤天害理的勾当。在阿洪的身上究竟隐藏了怎样的秘密？王千方百计的想要得到阿洪又究竟是为了什么？','The faces you love. The action you expect.',140000000,285444603,24.855701,6.3,767,127,'1998-07-10','en','/uGfVJpP2FDbhruOjfkyUBy8BNdG.jpg',3.362072087568449,3,'2026-09-10',2,NULL,NULL),(947,'阿拉伯的劳伦斯','Lawrence of Arabia','大卫·里恩1962年的史诗巨制。彼得·奥图尔在此献上了影史中最震撼人心的银幕首秀之一，其饰演的传奇人物劳伦斯在广袤沙漠中交织着理想主义与身份迷失的壮阔篇章，至今仍闪耀着不朽的光芒。',NULL,15000000,69995385,41.286336,7.8,851,216,'1962-12-10','en','/g1RPFNzdjZ7oS8x6nLI1nSOX5eL.jpg',3.666059282925772,3,'2026-09-10',2,NULL,NULL),(948,'月光光心慌慌','Halloween','1963年万圣节之夜，六岁的迈克尔·迈尔斯持刀杀害了自己的姐姐。在精神病院监禁十五年后，迈尔斯逃脱并重返伊利诺伊州哈登菲尔德镇展开杀戮。','The Night He Came Home',300000,70000000,30.301307,7.4,1035,91,'1978-10-25','en','/xrQlKAzrJ8PNJeLyIOUPYR70PUd.jpg',3.6373568835340735,3,'2026-09-10',2,NULL,NULL),(950,'冰川时代2：融冰之灾','Ice Age: The Meltdown','冰河期就快要结束了，大大小小的动物们都在欢天喜的庆祝水世界的即将来临，一片歌舞升平。然而迭哥(丹尼斯·劳瑞配音)、希德(约翰·莱格扎莫配音)和曼尼(雷·罗曼诺配音)在享受和煦阳光的同时却发现大势不妙，溶化的雪水即将湮没她们的村庄，他们必须承担起警告所有居民从灾区撤离的艰巨责任。三兄弟毅然挥军南征，沿途经历诸多危险，最终到达安全的彼岸。在旅途过程中，经常逗嘴的三兄弟互相扶持，有难同当。同时，一直认为自己是最后一头猛犸象的曼尼在旅途中遇到了爱丽(奎因·拉蒂法配音)--世界最后一头雌性猛犸象。我们的长毛英雄在面对一筹莫展的爱情和恶劣的天气条件下一时完全没有了对策。而偏偏这场破冰之旅还万万少不了爱丽…','The Ice age is melting away.',80000000,660940780,85.115058,6.5,2951,91,'2006-03-23','en','/zDduhCHasKQ9YOTvlOreHem7Wbi.jpg',3.856469689211019,3,'2026-09-10',2,NULL,NULL),(951,'Kindergarten Cop','Kindergarten Cop','Hard-edged cop John Kimble gets more than he bargained for when he goes undercover as a kindergarten teacher to get the goods on a brutal drug lord while at the same time protecting the man\'s young son. Pitted against a class of boisterous moppets whose antics try his patience and test his mettle, Kimble may have met his match … in more ways than one.','Go ahead, you tell him you didn\'t do your homework.',15000000,201957688,5.411154,5.8,628,111,'1990-12-21','en','/bAxsac2udNcLSaEdqjRLrLMc64n.jpg',3.202048489250378,3,'2026-09-10',2,NULL,NULL),(953,'马达加斯加','Madagascar','在纽约的中央公园里，生活着这样一群无忧无虑的好朋友：狮子亚利克斯、斑马马蒂、长颈鹿麦尔曼以及胖河马格洛丽亚。他们的性格开朗活泼，因此每天的生活都过得丰富多彩。直到有一天，一群流浪的企鹅令斑马马蒂产生了一个大胆的念头，那就是逃出动物园，探寻自己的故乡，寻找新世界。于是，没有通知其他朋友，马蒂悄悄上路了。这下可急坏了朋友们，亚历克斯和其他几个朋友也逃出了中央公园，踏上了寻找马蒂的旅途。','Someone\'s got a zoo loose.',75000000,532680671,48.110909,6.6,3237,86,'2005-05-25','en','/zMpJY5CJKUufG9OTw0In4eAFqPX.jpg',3.8181737372903095,3,'2026-09-10',2,NULL,NULL),(954,'碟中谍','Mission: Impossible','中情局向以吉姆为首的特工小组发来指令，一名特工人员已经叛国，将在布拉格的领事馆窃取中情局在东欧潜伏的特工名单，一旦落入坏人手中，后果将不堪设想。他们奉命获取该特工窃取情报的证据，并将其与买家逮捕。很快，在吉姆的策划下，一线主力伊森·亨特和其他几名成员全部到位，不过当计划进行到一半时，情况突然急转直下，包括吉姆在内的小组成员相继殒命，情报失踪，只有伊森一人生还。精神几乎崩溃的伊森与上司见面，却因幸免遇难和帐户上突然多出的12万美元被指认为叛徒，原来失窃的是假情报，行动的真正目的是为了查出内奸。突出重围的伊森决定查出叛徒，而此时，同样侥幸生还的吉姆的妻子克莱尔与伊森重逢。','Expect the Impossible.',80000000,457696359,75.290998,6.7,2631,110,'1996-05-22','en','/l5uxY5m5OInWpcExIpKG6AR3rgL.jpg',3.8539128655743884,3,'2026-09-10',2,NULL,NULL),(955,'碟中谍2','Mission: Impossible II','一位医学博士研制出一种威力巨大的新型病毒“金美拉”，为保证运送安全请求中情局提供援助，不料被扮作伊森的前中情局特工肖恩谋害，并窃取了病毒资料。伊森受命找到肖恩并获取相关情报，而在这之前，伊森必须得到女神偷奈雅的帮助，因为奈雅是肖恩的前女友，是接近肖恩的唯一人选。在获取奈雅信任的同时，伊森和奈雅萌生爱意。在制造奈雅被捕的假情报后，肖恩如期将奈雅救出，接到自己住处，不过肖恩已经怀疑奈雅的到来另有图谋。伊森和奈雅终于在赛马场接头并获知了情报内容，而同时肖恩已经察觉奈雅不仅奉命卧底，还与伊森坠入爱河。怀恨在心的肖恩已经猜测出伊森将前去药厂销毁病毒，遂率人争夺，交战之中，奈雅为帮助伊森完成任务，将仅存的病毒注入自己体内，并要求伊森杀死自己，而伊森不忍下手，并承诺将会挽救奈雅。肖恩开始和制药厂老板交易病毒和解药，声称病毒将很快席卷世界，正在此时，伊森赶到，经过激烈搏斗，伊森终于夺回病毒和解药，结果了肖恩，并及时挽救了奈雅的生命。','Expect the impossible again.',125000000,546388105,54.931334,5.9,1928,123,'2000-05-24','en','/uI1imrGqaj94VPY7JK0vpYmUkX0.jpg',3.5556301126956433,3,'2026-09-10',2,NULL,NULL),(956,'碟中谍3','Mission: Impossible III','伊森（汤姆·克鲁斯 Tom Cruise 饰）曾是任职于特殊部门的秘密特工，自从一位名叫茱莉亚（米歇尔·莫娜汉 Michelle Monaghan 饰）的美丽女子出现在他的生命里后，伊森决定金盆洗手，卸甲归田。遗憾的是，好景不长，幸福的生活还没过多久，伊森便接到了徒弟林德赛（凯丽·拉塞尔 Keri Russell 饰）被死对头戴维恩（菲利普·塞默·霍夫曼 Philip Seymour Hoffman 饰）掳走的消息。戴维恩冷酷又凶残，林德赛落入他的手中可谓是凶多吉少。为了解救林德赛，伊森重操旧业，他组织了一支精干的特工小组，向着目标人物发起了进攻。让伊森没有想到的是，戴维恩的真正目标并不是林德赛，而是茱莉亚，当爱妻落入敌手之时，伊森会做出怎样的反击？','The Mission Begins 05:05:06.',150000000,397850012,63.079003,6.5,2028,126,'2006-05-03','en','/vKGYCpmQyV9uHybWDzXuII8Los5.jpg',3.7170135341683377,3,'2026-09-10',2,NULL,NULL),(957,'太空炮弹','Spaceballs','在很久以前的遥远星系中，“炮弹一族”因其领袖的愚蠢，耗尽了自己星球的大气，于是计划夺取邻近的朱迪亚星球的纯净空气。在朱迪亚星球维斯帕公主（达芙妮•祖尼加 Daphne Zuniga 饰）婚礼前夕，炮弹族总统斯古（梅尔•布鲁克斯 Mel Brooks 饰）派出黑帽子大人率领巨型战舰绑架维斯帕，以威胁朱迪亚方面就范。维斯帕拒绝没有爱情的婚姻选择逃婚，却陷入了炮弹族巨舰的追击，这时，因为欠高利贷在太空中奔逃的太空牛仔“孤星”（比尔•普尔曼 Bill Pullman 饰）与半人半狗的搭档巴夫受朱迪亚国王所托，出面将维斯帕救走。炮弹族岂肯善罢甘休，正邪势力在太空上演了又一场激战……','May the schwartz be with you',22700000,38119483,39.890798,6.7,902,96,'1987-06-24','en','/kNbaxEsnCyWBTfANVPHayujBsxp.jpg',3.500233239925839,3,'2026-09-10',2,NULL,NULL),(978,'西藏七年','Seven Years in Tibet','1939年，两位奥地利登山运动员海因里希·哈勒 和彼得·奥弗施奈特 以纳粹党徒的身份来到印度攀登喜马拉雅山。由于德国和英国的宣战，二人在登山时被印度的英国殖民军抓获并囚禁了5年，终于在1944年成功地逃往青藏高原。 经历了千辛万苦，二人终于逃到了西藏拉萨。因为西藏人民认为外国人是邪恶的，会给西藏带来危险，因此，西藏禁止外国人入内。但他们却通过伪装，偷偷的溜进圣城拉萨，最后被西藏地方政府的一个官员收留。在西藏期间，哈勒有幸与西藏的精神领袖第十四世达赖喇嘛（当时还是个小男孩）结识，并成为了他的亲密无间的朋友和老师。在这几年里，哈勒受西藏地方政府官员的供养，衣食无忧。 但是，1950年中国人民解放军以武力占领西藏，导致西藏政教合一的领导人逃亡印度。在哈勒听说德国战败之后，哈勒决定动身返回奥地利。在离开西藏前，哈勒来到布达拉宫和达赖喇嘛道别。达赖喇嘛送给他一个八音盒作为临别的礼物。','At the end of the world his real journey began.',70000000,131457682,16.92991,7,630,136,'1997-09-12','en','/qm87HHUew8ICtUCM4asO3gFYvby.jpg',3.3959321998600296,3,'2026-09-10',2,NULL,NULL),(979,'不可撤销','Irréversible','整部影片用倒带一样的叙述方式，不断往前追溯，令人感到宿命的不可逃避。爱里克斯亮丽性感，独自行走在城市的地下道，却被酒醉的歹徒盯上。歹徒残忍的对她强暴施虐，让她美丽的脸庞变得血肉模糊。于是， 她的服了摇头丸的男友马尔克什，带着朋友闯进各式各样的酒吧，寻找凶手报仇。他们意识接近失控，举起灭火筒猛砸疑凶脑袋。然而，就在这些血腥的事件之前，爱里克斯和男友过着幸福生活，他们感情甜腻，爱里克斯腹中还有了男友的孩子。然而，在接下来的12个小时里，所有的线索，都不可撤消的把爱里克斯引向了那个噩梦般的深渊。','Time destroys everything.',0,792,32.476098,7.1,538,97,'2002-05-22','fr','/AdrItykbv1evqcbIPrItVWnkaKj.jpg',3.399596575088667,3,'2026-09-10',2,NULL,NULL),(985,'橡皮头','Eraserhead','一个黑暗而扰人的梦境……大卫·林奇1977年的首部长片既是影史留存的邪典传奇，亦是一部技艺非凡、充满诡谲美学的作品。凭借弗雷德里克·埃尔姆斯与赫伯特·卡德维尔令人沉醉的黑白摄影、极具氛围的音效设计，以及杰克·南斯令人过目不忘的神秘表演，这场充满幻想的黑夜漫游，至今仍如幽灵般盘踞在美国影史上，独此一作。','Where your nightmares end...',10000,7000000,20.399578,7.5,485,89,'1977-03-19','en','/dxJgthXG7bggC7z1pLTlgvf8Xf5.jpg',3.390056565143413,3,'2026-09-10',2,NULL,NULL),(987,'The Front Page','The Front Page','A journalist suffering from burn-out wants to finally say goodbye to his office – but his boss doesn’t like the idea one bit.',NULL,4000000,0,4.117968,6.9,68,105,'1974-12-01','en','/r4RtbJk8wVyZ1yk6yBZjzGD4ANU.jpg',2.7827816695712504,3,'2026-09-10',2,NULL,NULL),(990,'江湖浪子','The Hustler','一位崭露头角的台球选手与一位卫冕冠军展开了一场孤注一掷的对决。','They called him Fast Eddie. He was a winner. He was a loser. He was a hustler.',2000000,7600000,17.639478,7.6,240,134,'1961-09-25','en','/snItsSViawjaadW9mlWUmGwR41R.jpg',3.175666246122271,3,'2026-09-10',2,NULL,NULL),(1018,'穆赫兰道','Mulholland Drive','深夜的穆赫兰道发生一桩车祸，女子丽塔在车祸中失了忆。她跌跌撞撞来到一个公寓里藏身。 一名男子说他常常梦见一个叫云奇的地方，那里有个恶魔盯着他。于是就来到云奇，果真见到墙后有怪物出现，男子当场晕死。另有一名杀手杀死了他面前的男人，然而蹩脚的他却惹来了不少一连串的麻烦。','An actress longing to be a star. A woman searching for herself. Both worlds will collide... on Mulholland Drive.',15000000,20117339,31.60985,7.6,1477,147,'2001-05-16','en','/x7A59t6ySylr1L7aubOQEA480vM.jpg',3.789659366018495,3,'2026-09-10',2,NULL,NULL),(1024,'罪孽天使','Heavenly Creatures','两名少女之间有着非同寻常的羁绊；双方父母因担忧这份友谊过于激烈而将她们强行分开，女孩们便展开了报复。','From a secret world no one could see... came a crime no one could believe.',5000000,3049135,8.753409,7,294,99,'1994-09-02','en','/uvb86wVCIqD3Rlbr0GTNgWDF7Zo.jpg',3.1652388148544697,3,'2026-09-10',2,NULL,NULL),(1051,'法国贩毒网','The French Connection','纽约缉毒警察“大力水手”道尔与搭档着手侦破一桩将海洛因走私至美国的国际贩毒集团案。','There are no rules and no holds barred when Popeye cuts loose!',1800000,41158757,15.978136,7.4,422,104,'1971-10-09','en','/pH4saPwMjhnVGwmSH6RkMaHrt3s.jpg',3.325121828879844,3,'2026-09-10',2,NULL,NULL),(1073,'无懈可击','Arlington Road','迈克尔·法拉第（杰夫·布里吉斯 Jeff Bridges 饰）是一名乔治华盛顿大学的历史系教授，单独抚养着9岁的儿子，他的妻子原是FBI探员，前不久死于一次执勤。最近，迈克尔家街对面搬来了一户新人家，奥利弗（蒂姆·罗宾斯 Tim Robbins 饰）和雪柔（琼·库萨克 Joan Cusack 饰）以及他们的儿子布雷迪。然而不知是由于正在讲授恐怖组织一课的职业惯性还是第六感作祟，迈克尔总是对这户新邻居心存怀疑，当然，周围没有一个人相信他的荒谬推理。迈克尔开始对奥利弗一家明察暗访，渐渐发现了原来奥利弗一直在用假身份生活，家族史也颇有疑点，但是奥利弗和雪柔的警惕始终让迈克尔的调查寸步难行。直到一天，迈克尔的女友无意在奥利弗的车后发现了一只可疑的包裹，然而就在他们还来不及弄清楚事情原委的时候，谋杀已经笼罩了这座城市……','Your Paranoia Is Real.',21500000,0,12.819447,7,239,117,'1999-03-19','en','/o2vgfDgJQF1j8bIudrakS2lvnwd.jpg',3.1189381962799656,3,'2026-09-10',2,NULL,NULL),(1088,'鲸骑士','Whale Rider','佩（凯莎·卡斯特-休伊斯 Keisha Castle-Hughes饰）是新西兰海岸上古老部落的酋长孙女。母亲曾经诞下龙凤胎，但不幸她和男婴都死去了，心灰意冷的父亲远走他方，剩下孤女佩给祖父母抚养成人。  　　奶奶非常疼爱佩，而酋长寇罗（拉维里·帕拉特恩Rawiri Paratene饰）却一度认为孙女是不祥之人。现今更令寇罗头痛的是继承人的问题。这个部落的有着严格的信条：继承人必须是男性。而眼看自己的儿子无法继承家业，寇罗万分苦恼。他从族人中间选出壮健男子，希望可以培养成为领袖，结果很不如意。而他的孙女佩，却在练习各式武艺，一心要接过爷爷的担子。  　　寇罗却执意遵从族人规条，不允许女性当上领袖位置。直到一条鲸鱼搁浅在此处的海岸，事情才开始峰回路转。佩凭着出色的勇气和能力，让爷爷改变了决定。 ©豆瓣',NULL,8000000,41400000,12.439495,7.1,111,101,'2003-01-30','en','/cVBZQZq091KtwBm2qObOv0JTFcH.jpg',2.9259752548416342,3,'2026-09-10',2,NULL,NULL),(1090,'异次元骇客','The Thirteenth Floor','十三，一个听起来就有些阴冷的数字。在一座大厦的第十三层，科学家道格拉斯·霍尔（克雷格·比尔克 饰）和汉农·富勒（阿明·缪勒-斯塔尔 饰）用电脑模拟出一个逼真的1937年的洛杉矶，他们可以通过电脑进入这个虚拟世界，真实地体验1937年的生活与自己。然而一个夜里，富勒被人杀死，种种线索都表明似乎是霍尔所为。可霍尔却对当天夜里的事情全无记忆。这时一个自称是富勒女儿的女人又神秘出现，可霍尔从未听富勒说过自己有女儿……为了找到凶手明晓真相，霍尔循着富勒留下的线索来到虚拟世界中，他离真相越来越近了……近到窒息……','Question reality. You can go there even though it doesn\'t exist.',16000000,18564088,19.890428,6.8,378,100,'1999-04-16','en','/5SInN5iJ4uTggNqgNKtp8heDtkQ.jpg',3.238987664923776,3,'2026-09-10',2,NULL,NULL),(1091,'怪形','The Thing','1982年冬天，挪威科考队的一架直升机突然打破了南极大陆的平静，直升机疯狂的追逐一只雪橇犬，最后坠毁在美国科考营地的附近。美国科考队员对挪威考察队近期人员骤减的情况有所耳闻，于是飞行员麦克（Kurt Russell 饰）与众人赶赴挪威营地，结果看到的是一地破败中四处散落着奇怪的尸体，并有证据表明挪威人得到了某种冰封状态中的生物。医生布莱尔（Wilford Brimley 饰）研究了尸体的变异却无法破解成因。当晚，犬笼中的狗遭到袭击并发生了变异，一种不可知的生物正在这孤寂的南极大陆威胁着科考队员们的生命……\r 　　本片翻拍自1951年由霍华德•霍克斯指导的《The Thing From Another World》。','Man is The Warmest Place to Hide.',15000000,19629760,52.731379,7.8,1588,109,'1982-06-25','en','/tzGY49kseSE9QAKk47uuDGwnSCu.jpg',3.901824362321677,3,'2026-09-10',2,NULL,NULL),(1103,'纽约大逃亡','Escape from New York','1988年，为了应对不断翻倍的犯罪增长率，联邦将曼哈顿岛改建成一座庞大的监狱，囚犯们被扔到其中自生自灭，纽约城变成了犯罪之城。转眼已是1997年，代号“大卫14”的美国空军一号被美国国家解放阵线劫持，最后坠毁在监狱城内，美国总统独自深陷城中。曾经的空军英雄、功勋特种队员普林斯肯中校（库尔特•拉塞尔 Kurt Russell 饰）由于抢劫银行入狱，政府决定利用普林斯肯潜入监狱城，救出总统。  　　普林斯肯的任务时间只有二十四小时，他在城中找到了自己昔日的战友、如今监狱地下统治者“公爵”的部下瑟翁，他们合作搭救总统，而要面对的是无处不在的疯狂犯人……','1997. New York City is now a maximum security prison. Breaking out is impossible. Breaking in is insane.',6000000,50244700,24.351305,6.9,703,99,'1981-05-22','en','/qwZzAespaxUn2iyC1A4NeCbUpqc.jpg',3.429202407934518,3,'2026-09-10',2,NULL,NULL),(1116,'The Wind That Shakes the Barley','The Wind That Shakes the Barley','Set during the 1920’s Irish revolution against the British, an Irish medical student is about to start his new job in London – but after he witnesses the mercenary atrocities of the British, he decides to join his brother in the IRA to fight for Irish independence.','Winner of the PALME D\'OR at the 2006 Cannes Film Festival.',6500000,22889018,6.787967,7.1,154,124,'2006-05-18','en','/imDGOLT1CtYzudS0fmy0vS41b9X.jpg',2.996148597650427,3,'2026-09-10',2,NULL,NULL),(1123,'揭竿而起','Catch a Fire','故事发生在20世纪80年代初期，种族隔离政策在南非掀起了狂风暴雨般的波澜。帕特里克（德瑞克·卢克 Derek Luke 饰）是炼油厂的领班，他和妻子普利西斯结婚多年，共同养育着两个可爱的小女儿，生活过得十分幸福美满。','The spark that ignites us, unites us.',0,4291965,4.052219,6.4,25,101,'2006-10-27','en','/2sgujWX2yWH7REnDI35ZZXsqPiV.jpg',2.553385960405972,3,'2026-09-10',2,NULL,NULL),(1124,'致命魔术','The Prestige','19世纪末的伦敦，罗伯特·安吉尔与阿尔弗雷德·伯登都是充满野心的年轻魔术师，曾经作为伙伴一起登台表演。然而一次意外造成的悲剧彻底改变了两人的关系，让昔日伙伴变成势不两立的竞争对手。此后，他们各自建立自己的舞台事业，不断钻研新的魔术，也开始想尽办法窥探、破坏甚至超越对方的表演。当伯登推出一个近乎不可能破解的惊人幻术后，安吉尔对其中的秘密愈发执着，甚至将目光投向正在迅速发展的实验科学。随着两人的竞争逐渐演变成无法停止的痴迷，他们愿意为成为最伟大的魔术师付出的代价也越来越高……','Are You Watching Closely?',40000000,109676311,74.440708,8,4391,130,'2006-10-19','en','/Ag2B2KHKQPukjH7WutmgnnSNurZ.jpg',4.310802765931953,3,'2026-09-10',2,NULL,NULL),(1125,'Dreamgirls','Dreamgirls','Three young women – Deena Jones, Effie White and Lorrell Robinson – dream of becoming pop stars and they get their wish when they\'re chosen to be backup singers for the legendary James \'Thunder\' Early.','One Dream Will Change Everything',70000000,154937680,14.486311,6.6,284,134,'2006-12-25','en','/6bNoDyxaIsDxzWsqUY0R4O1MU8l.jpg',3.1353103590387823,3,'2026-09-10',2,NULL,NULL),(1164,'通天塔','Babel','在摩洛哥、墨西哥和日本发生的三个故事。  理查德和妻子苏珊因为婚姻危机，去摩洛哥旅行，苏珊在旅行车里遭遇枪击，为了医治苏珊，一车美国游客不得不在摩洛哥的小村滞留，而警方也将此次事件上升为恐怖袭击，展开了调查，其实真相却惊人的简单。  理查德夫妇滞留在摩洛哥，影响到了家里的孩子们，墨西哥保姆为了参加儿子的婚礼，只能让她的侄子开车带着她和孩子们一起去，但是，从墨西哥过境回来的时候，他们遇到了麻烦，警方怀疑她绑架美国小孩，事情开始不受控制。  日本，聋哑少女千惠子孤寂地生活在无声的世界中，母亲的自杀使她和父亲的沟通越发困难，由于自己的残疾，她也得不到异性的关注，性格越发叛逆。于是，她用自己的方式，和世界沟通交流。','If You Want to be Understood...Listen',25000000,135330182,25.785925,6.9,1055,143,'2006-09-08','en','/eJLnfIXe4I17EifuVvCRHxu7Cok.jpg',3.544250558989193,3,'2026-09-10',2,NULL,NULL),(1165,'女王','The Queen','本片将观众带入近年来最震撼的公共事件幕后——当悲剧袭来时，镜头深入权力走廊，呈现一段发人深省、深切动人且充满戏剧性的真实图景。[米拉麦克斯]','Our Leaders. Ourselves.',15000000,123384128,19.113278,6.8,338,103,'2006-09-15','en','/olwdewYzs4FSXTy5x1zUdiKddys.jpg',3.2079004077606483,3,'2026-09-10',2,NULL,NULL),(1213,'天才瑞普利','The Talented Mr. Ripley','年轻有钱又置身于意大利的艳阳下，这是汤姆·瑞普利（马特·达蒙 Matt Damon 饰）所渴望的生活，却是迪基·格林利（裘德·洛 Jude Law 饰）早已拥有的东西。 瑞普利是个出身平凡，生活也毫无值得炫耀的年轻人，他受到一个富商之托，到意大利去游说他放荡不羁的儿子迪基，重回他的家乡美国。但是当瑞普利一到那里，就深深地被迪基的生活形态所迷惑：美丽的别墅、高级浮华的渡假饭店、一掷千金的奢靡生活，以及他美丽温柔的女友，都令他羡慕不已。 由于瑞普利一心凯觎迪基的生活，最后这样的欲望竟扩张成想要将迪基取而代之，他缜密的心思不仅令人昨舌，而冷静的犯罪手法更教人措手不及。就在他陶醉于亲手打造的美梦中时，瑞普利因为一次意外的巧合害他露出了马脚，于是引起警方的注意并展开调查…… 本片改编自女作家派翠西亚·海史密斯写于1955年的同名小说，法国导演雷内·克莱芒曾于1960年拍摄过一部以该小说为蓝本的电影《太阳背面》，由法国影星阿兰·德隆主演','How far would you go to become someone else?',40000000,128798265,31.385257,7,767,139,'1999-12-25','en','/kiKO4XSKI8yWSY8lbfTJtIr6UnL.jpg',3.4846950020445884,3,'2026-09-10',2,NULL,NULL),(1245,'告别有情天','The Remains of the Day','故事背景设定于二战前夕，影片聚焦一位英国乡村宅邸的男管家（安东尼·霍普金斯 饰）与他心怀热忱的女管家（艾玛·汤普森 饰）之间克制而深刻的情感纠葛。','Diamond in the Rough',11500000,23237911,15.355589,7.5,202,134,'1993-11-05','en','/hlW4MAnKE2onlwoc1iC6niX1Sf8.jpg',3.112968030232269,3,'2026-09-10',2,NULL,NULL),(1246,'洛奇6：永远的拳王','Rocky Balboa','转眼30年过去，往日的荣光渐渐不再。曾经的传奇拳王洛奇（西尔维斯特·史泰龙 Sylvester Stallone 饰）生活平淡乏味，心爱的妻子亚德里安（Talia Shire 饰）因癌症去世，自己与儿子的关系又分外紧张，他终日坐在所开的小餐馆里追忆往昔，谁也不会想到这位拳王退休后的人生竟如此落寞。 　　是时，新一代的拳王横空出世，年轻的梅森·迪克逊（Antonio Tarver 饰）统治者重量级冠军的头衔。在体育频道工作的波利（Burt Young 饰）突发奇想，策划了一场新老两代拳王的世纪对决。梅森渴望在比赛中向拳迷们证明自己的实力，洛奇则希望在此感受万众欢呼呐喊的狂热气氛，他们怀着各自的心愿重返拳台……','It ain\'t over \'til it\'s over.',24000000,155721132,30.445257,6.5,835,102,'2006-12-20','en','/LADHlYVffBhCb5oEm3LZIjlsjt.jpg',3.4264982165285955,3,'2026-09-10',2,NULL,NULL),(1248,'Hannibal Rising','Hannibal Rising','The story of the early, murderous roots of the cannibalistic killer, Hannibal Lecter – from his hard-scrabble Lithuanian childhood, where he witnesses the repulsive lengths to which hungry soldiers will go to satiate themselves, through his sojourn in France, where as a med student he hones his appetite for the kill.','It started with revenge.',50000000,82169884,6.567065,6,654,121,'2007-02-06','en','/ctwPZAy1GobC9FDq5KzJI93S23X.jpg',3.2409217371940815,3,'2026-09-10',2,NULL,NULL),(1250,'恶灵骑士','Ghost Rider','年轻的约翰尼·布雷泽为了挽救父亲的生命，以自己的灵魂为价和地狱魔王墨菲斯特交易，谁知一个星期后，父亲却在一次摩托车特技表演中丢掉了性命。成年后的布雷泽也成为了一名摩托车特技车手，并在一个夜晚与少年时的女友洛克塞偶然相遇，此时的洛克塞已经成为了一名雄心勃勃的记者。墨菲斯特承诺可以释放布雷泽的灵魂，条件是布雷泽在夜晚必须为他服务，充当“幽灵骑士”--一个拥有超自然力量的复仇者，任务是按照墨菲斯特的指令，惩处那些跟墨菲斯特作对的魔鬼，其中包括黑心魔--墨菲斯特无数儿子中最不听话、最有野心，也是最狡诈的一个。数百年来，他一直想要取代父亲。为了王位，黑心魔不断招兵买马，还想诱惑布雷泽加入他的阵营。布雷泽坚决地对抗着自己的宿命，用加诸于自己身上的诅咒和力量去保护无辜者，惩奸除恶，为受害的冤魂复仇。','Hell Is About To Be Unleashed',110000000,228738393,46.834704,5.2,1712,114,'2007-02-16','en','/oNpUAqpwSkCUnSZGEkfIizppZHW.jpg',3.365578130487657,3,'2026-09-10',2,NULL,NULL),(1251,'硫磺岛的来信','Letters from Iwo Jima','在这部《父辈的旗帜》的姊妹篇中，克林特·伊斯特伍德将镜头转向六十一年前在硫磺岛上抵御美军进攻的日本士兵与他们的将领，呈现了那段不为人知的故事。','The battle of Iwo Jima seen through the eyes of the Japanese soldiers.',19000000,68673228,24.47248,7.2,541,141,'2006-12-19','en','/dfzEO1akoT0WN50yJ8LevJbIdfg.jpg',3.395707911415766,3,'2026-09-10',2,NULL,NULL),(1255,'The Host','괴물','Gang-du is a dim-witted man working at his father\'s tiny snack bar near the Han River. One day, Gang-du\'s one and only daughter Hyun-seo comes back from school irritated. She is angry at her uncle, Nam-il, who visited her school as her guardian shamelessly drunk. Ignoring her father\'s excuses for Nam-il, Hyun-seo is soon engrossed in her aunt Nam-joo\'s archery tournament on TV. Meanwhile, outside of the snack bar, people are fascinated by an unidentified object hanging onto a bridge. In an instant, the object reveals itself as a terrifying creature turning the riverbank into a gruesome sea of blood¡¦ Amid the chaos, Hyun-seo is helplessly snatched up by the creature right before Gang-du\'s eyes. These unforeseen circumstances render the government powerless to act. But receiving a call of help from Hyun-seo, the once-ordinary citizen Gang-du and his family are thrust into a battle with the monster to rescue their beloved Hyun-seo.','Monsters are real.',11000000,88489643,27.65527,6.7,537,119,'2006-07-27','ko','/lTCwDvMpBYVl92krl3qjYk5KwPq.jpg',3.337123582538677,3,'2026-09-10',2,NULL,NULL),(1257,'老娘说了算','Because I Said So','达芙妮（黛安·基顿）是个漂亮高雅的单身母亲，独自带大三个如花似玉的女儿。眼看就要庆祝六十大寿的她，却总有件事放不下，小女儿蜜莉（曼迪·摩尔）的终身幸福仍无定音。虽然两个大女儿都一再劝她放手、放心让蜜莉自己寻觅真爱，可达芙妮还是抑制不住亲自操刀，瞒着女儿在网上打了征友广告。','She\'s just your normal, overprotective, overbearing, over-the-top mother.',0,69485490,18.678415,5.8,191,102,'2007-02-02','en','/wQtGQnr5RPnmzSfV9zUcgh8R9NX.jpg',2.99861607398757,3,'2026-09-10',2,NULL,NULL),(1259,'丑闻笔记','Notes on a Scandal','伦敦北部的圣乔治学校，美丽的希芭·哈特(凯特·布兰切特饰)成为这所学校新的美术老师。她的到来引起了同事芭芭拉·卡福特(朱迪·丹奇饰)的注意，她在自己的日记中写到她无法说清楚这个新来的人“是一个斯芬克斯女神还是一个很简单的傻瓜”。在一次课堂上，她出手帮助毫无经验的希芭来摆平搅乱纪律的学生，两个人因此而结为好友。为了表示谢意，希芭邀请芭芭拉去她家吃午餐。希芭有一个年纪她大很多岁的丈夫理查德（比尔·奈伊饰），这个老男人的脾气十分暴躁，还有一个喜怒无常的十几岁的女儿波丽 (Juno Temple饰)以及先天愚型的儿子本(迈克斯·路易斯饰)。正是由于芭芭拉在自己的日记里，对每一件事情都做出无比尖酸刻薄的评价，影片把哈特一家碌碌无为的中产阶级生活方式刻画得入木三分，加上布兰切特精确演绎出希芭对她的家庭的热爱，同时还有一个女人因为过早结婚，开始工作却又过晚而在内心产生的种种不满。一天下课后，芭芭拉无意中看到希芭正在与一个满脸长着雀斑的男孩偷情。这个15岁的男孩出生于工人阶级家庭，名字叫斯帝文·康纳利(安德鲁·辛普森饰）。事情败露之后，芭芭拉直接面对希芭。在一系列的闪回镜头中，希芭流泪满面地供认了自己与学生的恋情开始于上门补习课程时，最终在铁路旁边开始了肮脏的约会。芭芭拉意识到握住了好友的把柄，虽然答应保守秘密，但是也无不暗示出希芭的处境很危险，她随时都有可能说出去……','One woman\'s secret is another woman\'s power. One woman\'s fear is another woman\'s weapon. One woman\'s life is in another woman\'s hands....',15000000,49469904,12.576381,6.9,235,92,'2006-12-25','en','/k1K9iIcjq1iRGtHh75GF64OF6xW.jpg',3.1065835316985364,3,'2026-09-10',2,NULL,NULL),(1262,'奇幻人生','Stranger Than Fiction','他——Harold Crick（威尔·法瑞尔 Will Ferrell 饰）是一个国税局的审计员，每天过着极具规律性的单调生活，一把旁白的声音却打破了这一切——他发现耳边常常响起某个人的说话，她能洞悉自己每日的生活规律，甚至能预测他不久将来的死去，他深深惶恐。  　　她——Karen Eiffel（艾玛·汤普森 Emma Thompson 饰）是一个作家，性格悲观颓唐，从来不让笔下的主角逃过死去命运，正为如何安排主人公死得伟大而烦恼。她不知道，笔下的那个男主角，和现实生活的他完全重合，而男主角死去的剧情，将一一在他身上应验。  　　然而，当他得知自己的人生被他人设计，但可以死得其所获得生命的价值时，他再也没有惊恐和反抗，而是坦然接受这一切。他的选择让作家开始了新的顿悟，故事也随之峰回路转。','Harold Crick isn\'t ready to go. Period.',30000000,53653224,32.26789,7.1,721,113,'2006-09-09','en','/nLFQtd4G5xjMg7Owvf1kuths1y8.jpg',3.4841067352168045,3,'2026-09-10',2,NULL,NULL),(1265,'仙境之桥','Bridge to Terabithia','杰西 是个过得不怎么快乐的孩子。他在学校里受同学欺负，在家中又无法得到父母的宠爱。只有两个人能为他的童年带来亮光——一个是音乐老师，另一个便是刚转校来到班上的莱斯利。 莱斯利以她独特的方式感染了生活暗淡的杰西，慢慢打开了他的生活的另一扇窗。在河的另一边，他们要建造一个叫做“特雷比西亚”的王国，他们在树上打造一个屋子，王国的成员有妖怪、马蜂军团、松鼠和秃鹰。这个幻想的天地创造了他们每天放学后最好的时光。 然而，童话毕竟太虚幻，杰西和莱斯利的特雷比西亚世界，迎来了风雨飘摇的一天……','Close your eyes, but keep your mind wide open.',60000000,137587063,40.646102,7,1113,96,'2007-02-16','en','/xKZGSfeYA8RmgWUyYDBoaM9YdRM.jpg',3.6109763101483736,3,'2026-09-10',2,NULL,NULL),(1266,'街头之王','Street Kings','洛杉矶警察汤姆·罗德（基努·里维斯 Keanu Reeves 饰）作风骠悍，勇猛果敢，经常和队友不顾警察条例而对嫌疑犯暴力相向。他们的做法令不法分子既恐惧又憎恨，同时也受到同僚的指摘。凭借队长杰克·沃德（福里斯特·惠特克 Forest Whitaker 饰）的关照，汤姆我行我素，不为所动。  泰伦斯·华盛顿（Terry Crews 饰）是汤姆的昔日搭档，他奉命调查汤姆暴力执法的问题。某晚，泰伦斯遭到两个戴面具之人的杀害，根据现场遗留下来的证据，汤姆便成了头号嫌疑犯。几经周折，他和负责调查此案的警官保罗·迪斯坎特（Chris Evans 饰）合作，却发现这起谋杀案的背后竟然隐藏着惊天的阴谋。与此同时，危险尾随而至，汤姆必须抓紧时间，为了自由和清白全力奋战……','Their city. Their rules. No prisoners.',20000000,65569869,18.666876,6.3,363,109,'2008-04-10','en','/mL1Ho7VNoeVg1L8tDYTlqjNTrNA.jpg',3.17566937202545,3,'2026-09-10',2,NULL,NULL),(1268,'憨豆先生的黄金周','Mr. Bean\'s Holiday','憨豆先生（罗温•艾金森 Rowan Atkinson 饰）总是傻人有傻福，这次，他的运气又来了！我们的憨豆以一张“616”的彩票夺得了中奖号码是“919”的法国度假大奖。憨豆先生马上收拾好行囊，前往法国圆他的先锋派电影之梦！抵达巴黎后，憨豆先生遇到了嘎纳电影节的其中一名来自俄罗斯的评委。奇思妙想的憨豆希望能拍摄一部关于自己的先锋派电影，于是做事从来不管后果的他带上了该评委的儿子跳上了火车，一路上扮演一对父子，却因语言不通大闹笑话，最后陷入了困境。憨豆最后会被作为“绑架者”被捕还是凭借他的影片入围嘎纳，夺得大奖？','Disaster has a passport.',25000000,229736344,27.683874,6.1,663,90,'2007-03-22','en','/3QcmqHvZx91yEFXDAbynjO9OeCJ.jpg',3.306299579382861,3,'2026-09-10',2,NULL,NULL),(1271,'斯巴达300勇士','300','这部电影描述了人类史上最残酷的战争之一：温泉关之战。公元前 480 年，波斯国王薛西斯一世（罗德里格·桑托罗 Rodrigo Santoro 饰）亲率 30 万大军征战希腊。希腊各个城邦迅速派出军队结成了联军，准备抵御波斯军队的入侵。防线的最前线设在希腊的温泉关，此处由斯巴达 城的国王列奥尼达（杰拉德·巴特勒 Gerard Butler 饰）率领本城 300 精兵和联军 4000 余人镇守。由于叛徒的出卖，希腊军队被波斯军队抄到了身后形成围剿之势。列奥尼达为了保存联军实力，让联军首先撤退，自己率领 300 精兵死守温泉关断后。数以十万波斯大军浩浩汤汤蜂拥而至，自知必死的斯巴达士兵反而士气高涨，在战斗中爆发出惊人的战力。整个战争整整持续了 2 天，最后列奥尼达和他的 300 精兵全部阵亡，而波斯军队则损失了 20000 多士兵，薛西斯一世的两个兄弟也在此役中战死……','Spartans, prepare for glory!',65000000,422610419,65.197968,7,4997,117,'2006-12-09','en','/h7Lcio0c9ohxPhSZg42eTlKIVVY.jpg',4.064452997523275,3,'2026-09-10',2,NULL,NULL),(1272,'Sunshine','Sunshine','Fifty years into the future, the sun is dying, and Earth is threatened by arctic temperatures. A team of astronauts is sent to revive the Sun — but the mission fails. Seven years later, a new team is sent to finish the mission as mankind’s last hope.','If the sun dies, so do we.',50000000,32017803,51.502884,7,1182,107,'2007-04-05','en','/j2jxwdxZHJAqKurxOtG00t9QtAG.jpg',3.6526286484883626,3,'2026-09-10',2,NULL,NULL),(1273,'忍者神龟','TMNT','将施莱德回老家之后，四只原本亲如兄弟的神龟由于没有了敌人，于是不再想以往一样一起战斗，而是各自在喜欢的领域内钻研，以往一起行动的忍者神龟们变成了四个独来独往的“独行侠”！这时，纽约市中发生一连窜的怪事。原来实业家马克西米林安意图征服纽约市，秘密培养了一支远古怪兽组成的军队，加上恶名昭著的忍者组织Foot Clan，各种黑暗势力又在城市的角落里蠢蠢欲动！神龟们又处于备战状态了！他们再次联合起来，准备向黑暗势力出击！',NULL,34000000,95608995,18.39217,6,345,90,'2007-03-23','en','/rmQrEsMGqispIfkT4AJPjBdRscI.jpg',3.1344741280853383,3,'2026-09-10',2,NULL,NULL),(1282,'狗镇和滑板少年','Dogtown and Z-Boys','这个屡获殊荣、激动人心的故事讲述的是一群被抛弃的孩子，他们彻底改变了滑板运动，塑造了现代极限运动的态度和文化。《DOGTOWN and Z-BOYS》以古老的skool滑冰镜头、独家采访和火爆的摇滚配乐为特色，捕捉到了来自威尼斯DOGTOWN的Zephyr滑板队的崛起，这是一个艰苦的“只有当地人”的海滩，有着非法冲浪的传统。',NULL,0,0,3.291609,7.2,52,91,'2001-01-18','en','/eb02dpopuAhuThf7nXAAwKtAF88.jpg',2.725174850695173,3,'2026-09-10',2,NULL,NULL),(1359,'美国精神病人','American Psycho','本片改编自布莱特·伊斯顿·艾利斯极具争议的同名小说，是一部描述20世纪80年代末期美国都市生活的黑色社会讽刺片。帕特里克·贝特曼（克里斯蒂安·贝尔 Christian Bale 饰）是华尔街的骄子，炙手可热的股票经纪人，英俊迷人，谈吐风趣幽默，年轻有为的他每天给自己的 客户们赚进无数的美元。可当夜幕降临时，黑暗的无边恐怖唤醒了贝特曼双重性格中的另一面。他将一个个猎物绑架到他的豪华公寓，一点一点折磨，看着鲜血慢慢涌出，猎物痛苦地死去，一种莫名的快感袭击着他。他身份使得调查这一系列罪案的警官从未把他列为嫌疑对象，而另外一名同样嗜血的杀人狂却想作下一件更为血腥的案子，成为真正的杀手之王。贝特曼的双重性格让他终日忙碌。然而罪恶终是无法掩盖，一个冷血的连环杀人案凶手的结局会是怎样呢？贝特曼会被抓住吗？','I think my mask of sanity is about to slip.',7000000,34266564,45.310443,7.3,2066,102,'2000-04-13','en','/9uGHEgsiUXjCNq8wdq4r49YL8A1.jpg',3.858312169115105,3,'2026-09-10',2,NULL,NULL),(1360,'弗里达','Frida','弗里达（salma hayek 饰）是墨西哥著名的女画家，18岁之前她是一个快乐活泼的少女，跟其他人一样，享受着爱情的甜蜜。然而18岁的车祸让她遭遇重创，死里逃生的她从此跟病痛伴随一生。原来的小情人也离她而去。躺在病床18个月的她整日与画为伴，她的画充满了不可思议的活力与激情。那时候她也真正开始考虑卖画养活自己，她前去请求画家里维拉指导自己的画，对方激赏她的天分。他们也从师生转变成一生的伴侣，他们结婚了。婚后他们经历了墨西哥最动荡的革命时期，他们狂热地追随着共产主义的脚步，甚至当托洛斯基被斯大林逐出苏联后，他们不畏风险地予以热情接待。弗里达与托洛斯基朦胧的爱恋，以及她的女同性恋情结让她的感情史一样绚烂。1954年，弗里达离开了这个充满了病痛的世界，但愿离去是幸。','Prepare to be seduced',12000000,56298474,18.422327,7.3,383,123,'2002-08-29','en','/w61xW5t5iEK9VlLpYHYxI3Iom00.jpg',3.2907811575883827,3,'2026-09-10',2,NULL,NULL),(1365,'死囚之舞','Monster\'s Ball','故事发生在种族偏见根深蒂固的美国南方小镇，主人公汉克（比利·鲍勃·汤顿饰）生长在一个保守的白人家庭，他在小镇监狱的死囚牢里当看守。汉克的职责之一是帮助执行死刑。汉克的父亲巴克是一个极端种族主义者，并且保守僵化，在他的家庭中，甚至连感情的过多流露也是不恰当的。汉克一辈子都生活在父亲的影子中，他的生活和思想好象倒模一样重复着父亲的轨迹，最近，汉克刚刚处死了一个黑人死囚。意想不到的是汉克偶然间结识了黑人死囚的遗孀莱茜娅（哈莉·贝瑞），并与这个贫穷的黑人妇女堕入情网，在固守种族偏见的家庭中掀起轩然大波。','A lifetime of change can happen in a single moment.',4000000,44909486,14.042041,6.5,250,111,'2001-11-11','en','/rQeufx98gKH4CCeVw57KT1Fd0gr.jpg',3.0953889426539067,3,'2026-09-10',2,NULL,NULL),(1366,'洛奇','Rocky','洛基•巴尔博厄(西尔维斯特•史泰龙 Sylvester Stallone 饰)是费城的过气拳击手。他空有拳击热忱，却只混杂于三流拳击赛中。一天，他对售货员艾黛丽安（塔里亚•希雷Talia Shire 饰）一见倾心，虽然这个姑娘长相一般，性格内向，却毫不阻碍洛奇对她爱得炽热。 　　爱情得意，事业也开始一路畅通。为了庆祝美国建国200周年，当地举办了一个拳击比赛，胜出者将获得15万美元的高额奖金。美国一个拳击巨星在比赛中受了伤，主办方选中了洛奇去上演一场“灰姑娘”式的比赛，大敌当前的同时，也是洛奇事业转机、大显身手的良机。洛奇在赛场上苦撑15回合，在面肿血流之际，会不会有奇迹的发生？','His whole life was a million-to-one shot.',1000000,117235147,72.19808,7.5,1791,119,'1976-11-21','en','/xSI0dbKLDETwhiVUy6hGE8KXUln.jpg',3.9212446954227786,3,'2026-09-10',2,NULL,NULL),(1368,'第一滴血','First Blood','退伍军人兰博（西尔维斯特•史泰龙Sylvester Stallone 饰）从越南回国，他回到已显得陌生的原居小镇，当地警长（布莱恩•丹内利 Brian Dennehy 饰）看到这个退伍军人的第一眼起，就开始对兰博百般挑剔，甚至将他带回警局肆意侮辱，不堪忍受责打的兰博袭警之后逃跑。警长召集大批警察展开对兰博的追捕，兰博逃至荒山野林之中，不断用自己在越战中掌握的游击战术对警察展开反击，他抢劫了一辆武器运输车返回小镇烧毁了商店，法律和武器都不能阻止兰博了。兰博在越战时的长官上校（理查德•克里纳 Richard Crenna 饰）出现，劝说兰博放下枪械，愤懑已久的兰博吼出了自己的困惑与不甘。','This time he\'s fighting for his life.',15000000,125212904,63.071046,7.2,1488,93,'1982-10-22','en','/a9sa6ERZCpplbPEO7OMWE763CLD.jpg',3.783302531623393,3,'2026-09-10',2,NULL,NULL),(1369,'第一滴血2','Rambo: First Blood Part II','神勇的兰博又回来了！这次，兰博奉命返回越南调查失踪的美军是否已成为战俘。然而，他刚刚登陆越南，就丢失了所有装备和武器，随身剩下的只有一把军刀和一套军用弓箭。身处逆境的兰博，偶然发现了出卖他的正是自己的部队。蓝波在九死一生之际，得到了当地一名越南少女的帮助，在少女的帮助下，蓝波凭借其高超的求生技能和坚强的意志，克服了一切困难，终于逃出生天。他决定向出卖他的人重拳出击。','What most people call hell, he calls home.',44000000,300400432,38.653969,6.3,864,96,'1985-05-21','en','/reVg95Mk7cjf22eIeLSPT7P6MQX.jpg',3.421085527143041,3,'2026-09-10',2,NULL,NULL),(1370,'第一滴血3','Rambo III','历经无数战火与生死考验，孔武有力的豪情勇士约翰·兰博放下手中的杀人武器，在泰国过起了平静的修行生活。这一日，特劳特曼上校突然出现在他面前。此前不久，上校受命率部队前往阿富汗，协助当地的圣战勇士反抗苏联人的入侵。虽然照片中阿富汗平民饱受外敌侵略和蹂躏的情景触目惊心，但兰博还是拒绝了上校的邀请。某晚，特劳特曼的部队在执行任务途中遭到苏联军队的伏击，其本人也不幸沦为阶下囚。得知这一消息，兰博再也无法静观其变。浴血战士重披战甲，只身闯入充满凶险的阿富汗腹地，展开一场紧张纷呈的绝命营救。','The first was for himself. The second for his country. This time it\'s to save his friend.',63000000,189015611,31.294717,5.7,690,102,'1988-05-24','en','/3fpF1yOll5377GFM48p3tlyxDlp.jpg',3.2647903631030943,3,'2026-09-10',2,NULL,NULL),(1372,'血钻','Blood Diamond','1999年，非洲塞拉利昂深陷内战的战乱纷飞之中。普普通通的渔民索罗蒙（迪杰蒙·豪索）被迫为一家钻石矿厂工作，一次偶然机会，在山涧河流中清洗淘到的石头时，索罗蒙发现了一颗精美的石头，那是一颗世上少有的粉红钻石，而它不仅能帮助自己的家庭，也能解救成为难民的妻女，挽救被抓去当童兵的最心爱的儿子迪亚。因此，虽然面对着死亡的危险，索罗蒙还是不顾一切地藏起了钻石。 丹尼（莱奥纳多·迪卡普里奥）是个靠非法交易钻石和武器为生的贩子，因为走私而被关进监狱的他无意得知了索罗蒙的钻石，他清楚那样稀有的钻石价值连城，完全能助他逃离非洲，逃出暴力腐败的罪恶圈。在一个调查钻石工业复杂黑幕的美国理想主义女记者曼迪（珍妮弗·康纳莉）的帮助下，三人开始了穿越战乱区域的长途逃亡。 对丹尼来说，他需要离开战乱的非洲；对索罗蒙来说，是要拯救自己的儿子和家庭；对曼迪来说，揭开钻石黑幕，成为第一个报导者，是她的夙愿。三个本不相关的陌生人，一颗罕有的粉钻，一场血腥杀戮的内战，在青葱广袤的非洲大陆之上，他们是否能得到最终的救赎？','It will cost you everything.',100000000,170877916,52.792678,7.3,2281,143,'2006-12-07','en','/sYAUuiWpoXGKHxUfHyjTj7Apj2h.jpg',3.9035244774618243,3,'2026-09-10',2,NULL,NULL),(1378,'性爱巴士','Shortbus','在繁华之都纽约，有一间名为短巴士（Short Bus）的俱乐部，肆意享受人生的青年男女云集于此，体验着彼此身体所带给自己的莫大快感。索非娅（Sook-Yin Lee 饰）是一名亚裔性临床专家，虽然和丈夫罗伯（Raphael Barker 饰）的婚姻生活无比幸福，但是她从未达到过高潮，为此索非娅苦恼不已；詹姆斯（Paul Dawson 饰）与杰米（PJ DeBoy 饰）是一对同性恋人，平淡的生活让詹姆斯渴望新鲜和刺激，这时，偷窥他们的加勒伯（Peter Stickles 饰）介入进来……','Open Your Mind. And Everything Else.',2000000,5179037,14.846001,6.3,140,101,'2006-05-20','en','/kOW6WfGXI46oNeQaRsMzEJe0luP.jpg',2.951365992971898,3,'2026-09-10',2,NULL,NULL),(1381,'珍爱泉源','The Fountain','一千年的历程，抒写一部史诗般的神话，一个跨越时空去拯救爱的故事。主人公分别出现在三段时空中：在16世纪的西班牙，他是英勇的武士托马斯·克莱奥，要去寻找传说中的生命之树，据说这种树的浆液会让人永生不死，以挽救自己垂死的爱人；生活在当今的他是科学家汤米·克莱奥，心爱的妻子身患癌症生命将尽，他在想方设法寻求解救的方法；而26世纪的他是宇宙探险家汤姆，开始逐渐领悟一个多世纪以来困惑他的生命奥秘……','Death is the road to awe',35000000,15304890,24.606012,6.8,827,96,'2006-09-06','en','/qeJxxYSHkT4zAaQGc2Rn7wYuHSx.jpg',3.458645472191184,3,'2026-09-10',2,NULL,NULL),(1382,'Me and You and Everyone We Know','Me and You and Everyone We Know','The feature film debut by artist Miranda July about a various comic situations and plots that intertwine. One story line is about a father who is ending his marriage and the other story is of a video artist (possibly autobiographical of Miranda July, also played by her) who is desperately trying to get her work in a modern art museum. The film won Caméra d\'Or at Cannes.',NULL,0,0,9.719094,7,107,90,'2005-06-17','en','/hrj9VsInHnqSDBhEc2FvY0qd79F.jpg',2.9067911257111096,3,'2026-09-10',2,NULL,NULL),(1389,'Out of Sight','Out of Sight','Meet Jack Foley, a smooth criminal who bends the law and is determined to make one last heist. Karen Sisco is a federal marshal who chooses all the right moves … and all the wrong guys. Now they\'re willing to risk it all to find out if there\'s more between them than just the law. Variety hails Out of Sight as \"a sly, sexy, vastly entertaining film.\"','Opposites attract.',48000000,77745568,16.000178,6.5,333,123,'1998-06-26','en','/xf0pt8jS4FmvDayAhgEuf4x7nmj.jpg',3.1686638466453028,3,'2026-09-10',2,NULL,NULL),(1391,'Y Tu Mamá También','Y tu mamá también','这部由奥斯卡获奖导演阿方索·卡隆执导的爆款公路喜剧，巧妙融合了直白露骨的题材与真挚的情感温度，实属影坛罕见。盖尔·加西亚·贝纳尔与迭戈·卢纳凭借此片跃升国际影星，二人饰演两个来自不同阶层、血气方刚的墨西哥城少年，当他们的女友飞往意大利度夏后，他们在婚礼上邂逅了一位美艳的西班牙熟女并被其迷住。当她答应陪同两人前往遥远的海滩旅行时，三人在旅途中逐渐形成了一种愈发浓烈而亲密的关系，最终让彼此的身心都彻底袒露。本片由摄影大师埃曼纽尔·卢贝兹基以优雅灵动的镜头执镜，本片以既诙谐又动人的方式审视了人类欲望的本质。','Life has its ways of teaching. Life has its ways to confuse us. Life has its ways to move us. Life has its ways to amaze. Life has its ways to hurt us. Life has its ways to heal. Life has its ways to inspire.',5000000,33616692,16.890285,7.3,315,106,'2001-06-08','es','/ejcn704nKthyZIdhiWiQ5Z3xkmY.jpg',3.229744788488456,3,'2026-09-10',2,NULL,NULL),(1402,'当幸福来敲门','The Pursuit of Happyness','克里斯·加纳用尽积蓄买下一批高科技医疗设备，希望靠推销它们改善一家人的生活，然而由于价格昂贵，销售情况并不理想，家庭也逐渐陷入困境。即使拼尽全力，他仍无法为妻儿提供稳定的生活，妻子最终选择离开，克里斯只得独自带着年幼的儿子克里斯托弗相依为命。为了改变命运，他好不容易争取到一家证券公司的实习机会，虽然没有薪水，而且只有极少数人能够最终留下，他仍决定全力以赴。生活的压力却接踵而至，父子二人一度无家可归，只能辗转于公共厕所和收容所。在人生最艰难的时刻，克里斯依然没有放弃这个可能改变命运的机会，也始终相信幸福终会来临……',NULL,55000000,307077295,80.581367,7.7,2525,117,'2006-12-14','en','/lBYOKAMcxIvuk9s9hMuecB9dPBV.jpg',4.088657105090666,3,'2026-09-10',2,NULL,NULL),(1408,'割喉岛','Cutthroat Island','活跃于加勒比海上的哈里、道格（Frank Langella 饰）、莫迪三兄弟各保存着一份藏宝图的三分之一，道格欲独占宝藏将哈里重伤致死。哈里之女摩根（Geena Davis 饰）接管晨星号海盗船，继承了父亲复仇与寻宝的遗愿。摩根取下父亲头皮上的藏宝图，却因无法辨识图上的拉丁文而登陆求助，适逢惯偷肖（Matthew Modine 饰）被官方贩卖为奴，摩根依赖肖的翻译能力把他买下，并且很快在官军对自己的追捕中展现了悍女本色。摩根等人寻至莫迪处，不料道格意外出现，混乱中莫迪身死，而肖将第二张藏宝图占为己有。摩根惩治了肖的不忠，但却无法摆脱尾随的道格，最终船员叛变，摩根失去了晨星号，虽然肖协助摩根发现割喉岛宝藏所在，但是在道格和官军的围堵下，取得宝藏谈何容易？','The Course Has Been Set. There Is No Turning Back. Prepare Your Weapons. Summon Your Courage. Discover the Adventure of a Lifetime!',98000000,10017322,7.029308,5.7,136,119,'1995-12-22','en','/yV3B0qIwf2jFsqzoA7dwo8hJZZz.jpg',2.898724427965575,3,'2026-09-10',2,NULL,NULL),(1412,'性、谎言和录像带','sex, lies, and videotape','二十六岁的史蒂文·索德伯格以其引人深思的长片处女作，将焦点对准现代人际亲密关系与欺瞒的复杂性。家庭主妇安（安迪·麦克道威尔 饰）感到与律师丈夫约翰（彼得·加拉格尔 饰）日渐疏远，而约翰正与她的妹妹辛西娅（劳拉·圣·贾科莫 饰）偷情。当约翰的老友格雷厄姆（魅力逼人、荣获戛纳影帝的詹姆斯·斯派德 饰）来到小镇，安被这位温和的局外人吸引，最终发现他惊人的私人癖好：用录像机记录女性袒露内心最深处的欲望。这部荣获金棕榈奖的影片以敏锐的智慧与无瑕的表演，构筑了一部室内剧风格的杰作——摄像机成为角色孤独处境的强烈隐喻。本片改变了美国电影的面貌，为1990年代独立电影的蓬勃发展铺平了道路。[标准收藏]',NULL,1200000,0,10.869492,6.7,185,100,'1989-08-18','en','/dE0u4uB5UPfVIdz258Ye2XEPuuh.jpg',3.029056837870966,3,'2026-09-10',2,NULL,NULL),(1415,'Party Monster','Party Monster','The New York club scene of the 80s and 90s was a world like no other. Into this candy-colored, mirror ball playground stepped Michael Alig, a wannabe from nowhere special. Under the watchful eye of veteran club kid James St. James, Alig quickly rose to the top... and there was no place to go but down.','\'Til death do they party...',5000000,742898,4.129165,5.9,58,98,'2003-09-05','en','/4DVWGtV1OA3W8kZxiimdNsepS6O.jpg',2.7239362040204216,3,'2026-09-10',2,NULL,NULL),(1417,'潘神的迷宫','El laberinto del fauno','这部荣获奥斯卡奖的黑暗童话，以西班牙内战结束五年后为背景，浓缩了吉列尔莫·德尔托罗视觉风格浓烈、突破类型桎梏的独特匠心。十一岁的奥菲莉亚（伊万娜·巴克罗饰，表演兼具成熟韵味与纯真质感）随怀孕的母亲迁往乡间，被迫直面法西斯统治的恐怖——她的新任继父正是弗朗哥将军麾下嗜血成性的军官，奉命剿灭拒不投降的共和军游击队。当奥菲莉亚在颓败迷宫中遇见农牧神，现实暴力与奇幻秘境便无缝交融：她由此踏上一段诡谲壮丽的神话旅程，集惊悚与华美于一体。导演通过重探西班牙史上的血腥时期，生动展现战争暴行如何渗入孩童的想象疆域，浸染纯真年华。[标准收藏]','What happens when make-believe believes it\'s real?',19000000,83258226,90.809408,7.6,3041,118,'2006-05-27','es','/z7xXihu5wHuSMWymq5VAulPVuvg.jpg',4.142776034079821,3,'2026-09-10',2,NULL,NULL),(1422,'无间道风云','The Departed','这部由马丁·斯科塞斯执导的硬派犯罪剧情片，将我们带入两名警察的人生：科林·沙利文（马特·达蒙 饰）精明而野心勃勃，看似在麻省州警精英特别调查组中拥有快速晋升通道，该部门的首要目标是势力庞大的爱尔兰黑帮头目弗兰克·卡斯特罗（杰克·尼科尔森 饰）。比利·科斯蒂根（莱昂纳多·迪卡普里奥 饰）熟知街头法则且强悍坚韧，却因被指暴力倾向而失去警徽，最终重回南波士顿的混乱街头，并被招募加入卡斯特罗的团伙。然而两人皆隐藏着真实身份，当他们在对立阵营中展开行动时，被迫卷入一场生死攸关的致命猫鼠游戏。[华纳兄弟]','Lies. Betrayal. Sacrifice. How far will you take it?',90000000,289847354,63.429157,7.9,4339,151,'2006-10-05','en','/nT97ifVT2J1yMQmeq20Qblg61T.jpg',4.256549607058536,3,'2026-09-10',2,NULL,NULL),(1424,'November','November','Sophie Jacobs is going through the most difficult time of her life. Now, she just has to find out if it\'s real.',NULL,0,0,5.742359,4.9,11,73,'2004-07-22','en','/qqCn3bYlG85dlVdUBd5Vjv3i0Qg.jpg',2.3810779445551393,3,'2026-09-10',2,NULL,NULL),(1427,'香水','Perfume: The Story of a Murderer','十八世纪，让-马普蒂斯特•格雷诺耶（本•韦肖 饰）出生在巴黎最肮脏、最恶臭不堪的地方——鱼市场上。格雷诺耶天生对气味有着惊人的天赋：无论恶臭还芳香，他都一一记住，并能轻易分辨各种气味。\r 当他在孤儿院长到13岁的时候，被院长卖给了制皮匠。格雷诺耶在制皮铺过着犬马不如的生活。机缘巧合，格雷诺耶在香水巴尔蒂尼面前展露了其过人的天赋，进入了香水铺工作。但格雷诺耶并不仅仅满足于制作出世界上最芳香的香水，他梦想学得如何保存万物气味的方法。巴尔蒂尼告诉格雷诺耶香水的起源地在格拉斯，那里的人知道保存气味的方法。格雷诺耶拿着巴尔蒂尼的推荐信来到了格拉斯。\r 格雷诺耶爱上了青春少女的体香，为了把这种香味保存下来，格雷诺耶最终走上了杀手的道路。','Based on the best-selling novel',50000000,132180323,42.551902,7.1,1165,147,'2006-09-13','en','/ipsKPG5NzJzMQT651y4FOIFQV7i.jpg',3.646586941239924,3,'2026-09-10',2,NULL,NULL),(1428,'墨西哥往事','Once Upon a Time in Mexico','独具拉丁忧郁气质的埃尔·马拉齐，是墨西哥传奇式的民间英雄和正义战士。表面上，他总是穿着宛如西部牛仔一般的华丽衣服，手提一把吉它四处演唱，仿佛是一位流浪歌手。但实际上，在他冷峻的长发下涌动着的是边漠的狂野。在墨西哥荒凉的沙漠上，埃尔·马拉齐是最令恶人畏惧的枪手。在他的吉它匣子里装的绝不仅仅是吉它，还有各种装备精良、巧布机关的武器，随时都可以大开杀戒。但是，埃尔虽然摧毁了一个又一个毒枭，却也为自己树立了无数的敌人，以至于只能过着终日被众人追杀的亡命生活。每当血腥过后，失意笼罩下的埃尔，便只能选择远离他乡、离群索居。','The Time Has Come.',29000000,98185582,27.555646,6.2,594,102,'2003-09-11','en','/sy8deWWtMrm1WOfGEL83qft45GL.jpg',3.295759630373351,3,'2026-09-10',2,NULL,NULL),(1429,'第25小时','25th Hour','蒙蒂在纽约生活，他的好友雅各布是中学英语老师，弗兰克忙于工作。蒙蒂在家和女友娜图拉莉相处时，警方查获他藏的毒品，他被判 7 年。入狱前最后几小时，蒙蒂怀疑女友告密，和父亲谈心，一行人在酒吧偶遇雅各布的学生玛丽。时限将尽，他马上就要入狱。','This life was so close to never happening.',15000000,13060843,30.196039,7.2,629,135,'2002-12-16','en','/uW7tTRElr2tRhmAVESzvHy4ByXg.jpg',3.4535876103671788,3,'2026-09-10',2,NULL,NULL),(1430,'科伦拜校园事件','Bowling for Columbine','这部记录片拍摄的起因是美国哥伦比亚中学的校园枪击事件。纪录片人摩尔着眼于大屠杀的背景、环境以及公众对这个事件反应，深入到美国暴力事件的本质，把枪支作为一种符号来探讨美国自由和自我毁灭之间的联系与矛盾。摩尔通过与南方公园作者Matt Stone、美国枪支协会时任主席Charlton Heston和音乐人Marilyn Manson等人的互动，逐步揭示出科伦拜恩大屠杀发生和美国高暴力犯罪的根源。','One nation under the gun.',4000000,35564473,11.414843,7.3,453,120,'2002-10-09','en','/4XsiTsZcNCRSkee1o0fdr5OqYRT.jpg',3.3249698308313995,3,'2026-09-10',2,NULL,NULL),(1435,'诅咒','Tarnation','乔纳森·考埃特的影片重构了纪录片的可能性边界。他以迷幻旋风般的手法编织起快照、超8家庭影像、电话答录机留言、视频日记、早期短片、80年代流行文化碎片及戏剧化重现场景，谱就一幅关于一个美国家庭的史诗画卷——这个家庭因创伤与失能而支离破碎，最终又因爱的力量重新凝聚。[Wellspring Media]',NULL,218,1162014,1.063439,7.5,22,91,'2003-10-19','en','/7zeQapdvD8poOizcaHwzmPxN9Km.jpg',2.52927745532588,3,'2026-09-10',2,NULL,NULL),(1439,'安娜与国王','Anna and the King','本片根据史事改编，与1956年的黛博拉•蔻尔与尤•伯连纳（女男主角）版本相比，重新诠释了寡居的英籍女教师安娜•里欧诺文与暹罗（泰国旧称）国王之间著名的爱情故事。\r 19世纪60年代，安娜（朱迪•福斯特）携子来到暹罗，成为该国多妻多子的国王（周润发）家的家庭教师。起初，由于迥异的风俗文化，安娜遭遇了许多看似难以克服的困难，国王对她也近似“野蛮人”。随着两人的深入交往，尽管仍有许多不和谐存在，但他们逐渐赢得了互相的尊重，并碰撞出爱情的火花。',NULL,75000000,0,13.327372,6.4,197,148,'1999-12-16','en','/b9LtQ0OMr8efAUTt9T7TzCRzfUK.jpg',3.030910803046172,3,'2026-09-10',2,NULL,NULL),(1440,'身为人母','Little Children','一处平静又寻常的社区里，主妇萨拉（凯特•温丝莱特 Kate Winslet 饰）每天的工作就是带孩子，而她的丈夫理查德却整日沉迷于成人网站自慰，夫妻关系濒临有名无实的境地。无聊的日子中，萨拉的注意力被同社区的“律师情人”布拉德（帕特里克•威尔森 Patrick Wilson 饰）所吸引。布拉德的妻子凯西（詹妮弗•康纳利 Jennifer Connelly 饰）是位女强人，平日忙于工作，无暇顾及家庭，夫妻之间越渐陌生。萨拉和布拉德由借带孩子之名越走越近，时常在社区游泳池相会，他们最终跨越了界线……这个夏天的压抑气氛，伴随社区到来了一位恋童者所引发的恐慌达到了顶峰，萨拉在难以忍受与布拉德的地下情之后提出了私奔计划。而在当晚，没有料到的情况发生了。',NULL,26000000,14821658,11.942862,6.9,240,136,'2006-10-06','en','/dZyrXl6uORLqhXVwwZm14SBJp9e.jpg',3.1106110770218747,3,'2026-09-10',2,NULL,NULL),(1443,'处女之死','The Virgin Suicides','一把冷冷的男声带来了故事的开始。青春期对里斯本一家的5个豆蔻女儿们来说，是一道迈不过的槛。首先自杀的是最小的女儿赛西利娅（汉娜霍尔 Hanna R. Hall 饰）。她变得脆弱低落，想结束生命，这一切都没有道得明的原因。父母以为，让她去和男孩交往，会改善情况。然而，赛西利娅还是选择了告别人生。和男孩交往频繁，性情放纵的，是另一个女儿勒克斯(克尔斯滕·邓斯特 Kirsten Dunst 饰)。勒克斯认识花花公子特里普，被和他发生了关系，却最终被特里普抛弃。里斯本父母害怕再次失去女儿，于是失去了理性。他们把四个女儿困在家中，给她们最严密的保护。然而自杀的惨剧就像疫情一样，迅速的扩散。','Beautiful, mysterious, haunting, invariably fatal. Just like life.',6000000,10409377,26.218912,7.1,817,97,'1999-04-21','en','/iBLu2Zw8RAPwqMy5YnM5R9XNn2w.jpg',3.5066452112804116,3,'2026-09-10',2,NULL,NULL),(1452,'超人归来','Superman Returns','一直想寻根的超人（Brandon Routh饰）返回了氪星，希望可以找到其他同伴，但那里的一切早已不复存在。而这一去便是5年。5年后，超人回到了地球，但是周遭的一切已经改变。他发现地球已经习惯了没有超人的保护，他一直爱慕的路易丝（Kate Bosworth饰）因为馔写了一篇“为什么世界不需要超人”的报道而获得普利策大奖。更令他心碎的是，她已经与主编的侄子订婚，而且是一个5岁孩子的母亲了。另一边，他的死对头莱克斯（Kevin Spacey饰）利用卑鄙手段骗取了巨额遗产，企图卷土重来。在南极莱克斯找到了超人父亲的线索，以及一块含有超级能量的水晶，妄想借助水晶的力量控制地球。超人能否战胜心魔，再一次挽救地球于水火？',NULL,270000000,391081192,57.925623,5.4,1400,154,'2006-06-28','en','/nRZaSIvWjpbDOJQCcCBCnqpzOzs.jpg',3.3986971077802415,3,'2026-09-10',2,NULL,NULL),(1487,'地狱男爵','Hellboy','1944年，第二次世界大战即将结束，纳粹的残余党羽试图利用黑魔法的力量挽救自己濒临灭亡的命运，不过，他们没有达到目的，同盟国军队的一个小分队赶到从事秘密仪式的地点，虽然他们驱散了施魔法的人，但撒旦之子——地狱男爵(朗·普尔曼饰)已经被黑魔法召唤到了人间。不过，与众人想象的不同，地狱男爵并没有站在邪恶的一方，他加入了同盟国，被教授布鲁姆(约翰·赫特饰)收养，并为美国政府完成各种难以完成的任务。凭借金刚不坏之身所向披靡，他与鱼人朋友亚伯(道格·琼斯饰)将一切胆敢阻碍正义的势力打得粉碎。不过，随着地狱男爵的不断长大，他开始露出了自己心底狰狞的一面。在一次执行任务的时候，地狱男爵与曾参与召唤他的纳粹邪恶巫师不期而遇，地狱般阴暗的本性能否战胜善良的感化？地狱男爵必须在正义与邪恶之间做出自己的选择……','From the Dark Side to Our Side.',66000000,99318987,47.479755,6.5,2225,122,'2004-04-02','en','/lbaTEneOofwvAyg77R8HbFML2zT.jpg',3.7035519163794954,3,'2026-09-10',2,NULL,NULL),(1491,'魔术师','The Illusionist','在十九、二十世纪之交的维也纳，依然受封建社会的浓郁气息所笼罩。一切奇闻怪事都无法用看似幼稚的科学所解释。而神秘的魔术师这一行当却有着极强的竞争力。艾森希姆（爱德华·诺顿）便是一个不折不扣的充满神秘色彩的魔术师。艾森希姆在与美丽的苏菲公主（杰西卡·贝尔）短暂的交往之后便深深爱上了这位绝世的美人。但无奈公主的地位高高在上，而且与王子利奥波德（鲁弗斯·塞维尔）有婚约在前。但一身法力的艾森希姆怎会轻易放弃爱情放弃美人，于是他利用自己的无边法术，将苏美丽的菲公主从王子身边夺走，并一手制造了无数奇幻事件，将整个维也纳皇室搅得乱七八糟……','Nothing Is What It Seems.',40000000,86915017,36.960953,7.1,1615,110,'2006-08-18','en','/1O9jUvqkHaGBMVRyOJz1AlkmALW.jpg',3.726570677099976,3,'2026-09-10',2,NULL,NULL),(1493,'特工佳丽','Miss Congeniality','格雷西的母亲是一名出色的联邦特工，在一次任务中不幸殉职。格雷西（桑德拉•布洛克 Sandra Bullock 饰）长大后继承了母亲的事业，也成为了一名联邦特工。格雷西从小就脾气刚烈、不修边幅，作为“假小子”的她并不受欢迎，只有她的拍档兼好友艾瑞克（本杰明•布拉特 Benjamin Bratt 饰）理解她。FBI获悉有一伙恐怖分子准备在美国小姐选美时制造恐怖袭击，为挫败这次阴谋，FBI决定派卧底参加选美。任务自然落到了格雷西身上。经过造型师的巧手，格雷西令所有人都眼前一亮，她的“假小子”性格自然也令到这次任务笑料百出。直到美国小姐庆典举行当晚，一切似乎都没有异常。然而，当格雷西和一众佳丽站到台上时，意外发生了！','Never Mess With An Agent In A Dress.',45000000,212000000,32.624355,6.1,961,111,'2000-12-14','en','/3KeMUGfHoc9eGqFgOKEgyMFlRay.jpg',3.397738830879136,3,'2026-09-10',2,NULL,NULL),(1494,'满城尽带黄金甲','滿城盡帶黃金甲','满城的菊花，意态舒展。人的忧思，却绞缠于胸。金碧辉煌的宫廷里，心绪不宁的皇后领着王子们在等王。宫闱上下，因为这个即将到来的重阳，忙碌得有序而繁密。一场盛大仪式准备就绪，王却悄然回宫，他好像要有意冷落那些恭候已久的人们，不给他们一个稍微镇定的机会去察言观色，暗自忖量。独自一人的时候他开怀大笑，他的笑里好像有很多的秘密。王是这样的王，仿佛振一振袍子，也有雷霆迅至。大的王子是祥，他的秘密太沉太重，矜贵之躯，也被这秘密打发成落魄的形骸。小的王子是昌，他的笑容灿烂，但是金玉之体，转过身来是温厚端笑，变过身去，嘴角竟有了一丝冷凝。','Unspeakable secrets are hidden within the Forbidden City.',110,0,9.950505,6.6,203,114,'2006-12-21','zh','/ifd1VMBBu9NG9sfIW0lujBVbZlO.jpg',3.0431936853971453,3,'2026-09-10',2,NULL,NULL),(1495,'天国王朝','Kingdom of Heaven','12世纪，巴里安是一个法国小铁匠，在妻子自杀后不情愿地加入了十字军。当他随着十字军东征来到耶路撒冷后，深深地被当地陌生而奇特的文化吸引，巴里安甚至爱上了公主希比拉。但是萨拉丁率领的撒拉森骑士很快来袭，他们发誓要夺回心中的圣地，一场惊心动魄又野蛮残酷的战争即将展开…… 奥兰多布鲁饰演贝里昂，一名失去家人和几乎丧失信仰的铁匠，在圣地发生的宗教大战似乎距离他很遥远，但他被命运逼入这个戏剧场景。他在中世纪神秘且复杂汹涌的耶路撒冷，陷入爱河，成为一名领袖，最后用全部的勇气和高超技艺悍卫整个城市不被悲剧摧毁。 命运要贝里昂成为一名骑士，再也不能自外于这场战争，高佛瑞是一位十字军战士，短暂从在东方的战场返回老家法国，透露说原来他是贝里昂的父亲，高佛瑞展现给他真正的骑士精神，并带他上路，越过大陆，抵达传说中的圣城。 这时的耶路撒冷正僵持在一种脆弱、一触即发的和平状态，由开明的基督教君王巴特文在幕僚提贝里尔斯，以及以骑士风范著称的回教优秀军队领导人撒拉丁帮助下，勉力维持。但巴特文的日子所剩无多，并承受著十字军们的狂热、贪婪、嫉妒等人性弱点，和平摇摇欲坠。 包括高佛瑞在内的一群骑士，和巴特文国王一样有著王者天下的和平愿景，他们宣誓用生命来效忠这份荣誉。高佛瑞将宝剑传给儿子的同时，也等于递交给他这份誓言，要保护无助的人、捍卫和平、为文化和宗教上的和谐努力，成就天国一样的乐土帝国。','Be without fear in the face of your enemies. Safeguard the helpless, and do no wrong',130000000,211643158,44.490453,6.6,1157,144,'2005-05-03','en','/23o6kVPP5RsrIizPZvxZVxdIdA1.jpg',3.55698849196586,3,'2026-09-10',2,NULL,NULL),(1497,'忍者神龟2','Teenage Mutant Ninja Turtles II: The Secret of the Ooze','忍者神龟们发现了变种物质的泄漏之处,但史莱德同时也发现这一秘密,于是他们之间又展开了新一轮的战斗,而忍者神龟们也在战斗中得到了提高!','Cowabunga, it\'s the new turtle movie.',25000000,78000000,15.505137,5.8,286,88,'1991-03-22','en','/Hyvvz9Z3le1is8a0EeFJQm0aSC.jpg',3.0716998978841215,3,'2026-09-10',2,NULL,NULL),(1499,'忍者神龟3','Teenage Mutant Ninja Turtles III','忍者神龟被一把神奇的魔杖传送到了17世纪的日本,他们将在那里对抗邪恶的则长领主,并夺回魔杖拯救纽约市!','The Turtles Are Back....In Time.',21000000,42000000,10.207065,5.1,184,96,'1993-03-17','en','/fwX5RdPDBFsbEAXc46DrvRz5Bca.jpg',2.9294226750729067,3,'2026-09-10',2,NULL,NULL),(1523,'末代独裁','The Last King of Scotland','尼古拉斯·哥瑞肯偶然结识了乌乾达新总统安迪·艾明Idi Amin（福里斯特·惠特克Forest Whitaker饰），安迪·艾明经常传诏尼古拉斯·哥瑞肯和莎拉，所以，他们在医学会上的时间便越来越少了。艾明刚刚通过军队武装获得了至高的权力，并卷入了一起公路案。','Charming. Magnetic. Murderous.',6000000,48027970,26.286954,7.4,558,121,'2006-09-01','en','/n1CgN2mS7RSxHhv2R1DdisYDvT6.jpg',3.4350580049875514,3,'2026-09-10',2,NULL,NULL),(1535,'Spy Game','Spy Game','Veteran spy Nathan Muir is on the verge of retiring from the CIA when he learns that his one-time protégé and close friend, Tom Bishop, is a political prisoner sentenced to die in Beijing. Although their friendship has been marred by bad blood and resentment, Muir agrees to take on the most dangerous mission of his career and rescue Bishop.','It\'s not how you play the game. It\'s how the game plays you.',92000000,143049560,27.166757,6.8,579,126,'2001-11-18','en','/qvQWAdLzoK13OUI0CjPy7BH66eq.jpg',3.3688747747683787,3,'2026-09-10',2,NULL,NULL),(1537,'变线人生','Changing Lanes','都勒（塞缪尔•杰克逊 Samuel L. Jackson 饰）是一个失意的黑人商贩，为了能获得孩子的抚养权，他费力地争取到了房屋贷款。在酗酒者分享会上，滴酒不沾的他难掩心中的欢喜，言辞激动。凯文（本•阿弗莱克 Ben Affleck 饰）是一家艺术品基金会的白人律师，他曾经帮助某富豪做过慈善捐助工作。但当老人死后，他却在上司的授意下，接连清洗了基金会的老成员，此举被老人的继承人视为背叛，一纸诉状将其告上法庭。\r 　　正在此时，一场车祸让都勒和凯文相遇。因为拿错了对方的文件，两人的命运发生了改变。因为错过了约会的时间，都勒的孩子被判由妻子抚养，从此父子难得见面。而凯文也在法庭上被逼上了绝路，陷入了信任危机。这时，两人才发现彼此的对抗只会让事情更糟，但是化敌为友的路途却荆棘丛生……','An ambitious lawyer, a desperate father, they had no reason to meet, until today,',45000000,94935764,17.270539,5.9,299,89,'2002-04-07','en','/xaLRlNj740OOnKgArQqiHUaFJa2.jpg',3.093230545626812,3,'2026-09-10',2,NULL,NULL),(1538,'借刀杀人','Collateral','夜幕低垂，麦克斯（杰米·福克斯 Jamie Foxx 饰）接了一位注定要改变他人生的客人――文森特（汤姆·克鲁斯 Tom Cruise 饰）。  文森特受雇于一家跨国贩毒集团，这晚来到洛杉矶要干掉五名重要证人。他与我们经常看到的杀手大不一样，他天生喜欢唠叨，在他挟持 麦克斯去帮他完成杀人工作时，还振振有词――“我又不是卢旺达大屠杀，我杀人本来就不是好人，可以说是替天行道，你有什么可以指责我的？”麦克斯也一时语塞。  这晚要杀的最后一个人是助理检查官，她曾是麦克斯的顾客。麦克斯决心保护她……','It started like any other night.',65000000,217764291,44.815022,7,1451,120,'2004-08-04','en','/nV5316WUsVij8sVXLCF1g7TFitg.jpg',3.6943718018100298,3,'2026-09-10',2,NULL,NULL),(1542,'上班一条虫','Office Space','在Initech公司上班的电脑工程师彼得?吉邦斯，正值他28岁的中年危机时期，他觉得无法再忍受日复一日那些琐碎、令人麻木的办公室生活。更令他沮丧的是，他的私生活也不是很乐观，因为他非常相信他的女友――安有别的男人。  　　唯一让彼德感到稍感欣慰的是，他的伙伴麦克尔?波尔顿和塞米尔最近分别感觉到他们在Initech的工作，并不如他们的副总比尔?兰伯格说得那样有保障。比尔是一位综合所有坏老板应有的特质的上司，一位颇有年纪，也喜欢掌控的雅痞，但他又是那种文质彬彬十分客气的人，让公司大小都找不出适当理由对他生气。  　　米尔顿是公司另一位五斗米折腰的员工。表现一直不如他人的米尔顿，一直处于被调座位的生活中。终于有一天，当他发现自己的座位越来越靠近储藏室时，他的忍耐度达到了极限。  　　一天公司新来了两位效率专家约翰和保罗，他们决定要简化公司的整个员工组织，彼得、麦克尔、塞米尔和米尔顿也面临被裁员的困境。事情虽然看来很糟，但彼得只要想到他未来30年还要过这样的生活，被裁员似乎就不是那么严重。在一家叫Chotchkies的主题餐厅服务的女服务生乔安娜，也面临类似彼得的相同问题。虽然事事看来都挺不乐观，彼得和他的朋友们却没有放弃希望，相反的，他们计划了一件大事，如果成功了他们将可以带着大笔钱早早退休。他们能如愿以偿吗？','Work sucks.',10000000,12827813,18.366362,7.4,1050,89,'1999-02-19','en','/iEmTwOkUaLziMQCUZii5wPQBIAO.jpg',3.6145622015552026,3,'2026-09-10',2,NULL,NULL),(1544,'四角关系','Imagine Me & You','瑞秋（派珀•佩拉博 Piper Perabo 饰）终于要嫁给了青梅竹马的男友海克（马修•古迪 Matthew Goode 饰）了，海克英俊温柔体贴忠厚，深深爱着瑞秋，瑞秋以为自己也同样深深爱着海克。婚礼上，就在通往神圣婚姻的红地毯上，瑞秋不经意地向旁边一瞥时，她突然像被闪电击中一样，而她，就是花店老板露丝（琳娜•海蒂 Lena Headey 饰），负责婚礼所有的鲜花。就这样，她们在婚礼上结识，并成为了朋友。虽然瑞秋和露丝彼此爱慕，但是她已经结婚了，而且海克是那么的好，最终瑞秋选择了放弃，露丝也选择了离开。瑞秋的变化被海克看到了眼里，他想给瑞秋幸福，于是，他选择了离开。瑞秋与露丝最终能否有情人终成眷属？ ©豆瓣','There goes the bride.',0,2455831,9.100352,7,177,93,'2005-02-01','en','/a7CbxY3TMwFKX6awlBxhb7Es6tS.jpg',3.0318215028470292,3,'2026-09-10',2,NULL,NULL),(1546,'吮拇指的人','Thumbsucker','无论你今年几岁，长大成人真不是件容易事！当贾斯丁(路波西)想要戒除咬手指的坏习惯时，周遭的人都因此陷入一片混乱。本片提供了人们对于重塑自我付出的努力一个诚恳与诙谐的检视，他们总想脱胎换骨却又担心和别人不一样。要了解没有人能够变成别人，「正常」是不存在的，缺陷美才是令你人性化及可爱的地方……',NULL,0,1919197,4.757625,6.1,67,96,'2005-01-23','en','/fBLjXNRkH0KuC5JEnGBUZx3SQw3.jpg',2.760585598801155,3,'2026-09-10',2,NULL,NULL),(1547,'捉鬼小灵精','The Lost Boys','因家庭财政危机，单身妈妈露茜（Dianne Wiest 饰）不得不带着两个儿子——麦克（Jason Patric 饰）和山姆（Corey Haim 饰）来到加利福尼亚某偏僻的海滨小镇桑塔卡拉居住。桑塔卡拉被青少年飞车党弄得乌烟瘴气，而且当地还流传着吸血鬼的传说。 两兄弟在这里很快结识了艾加（Corey Feldman 饰）和艾兰（Jamison Newlander 饰）两兄弟，他们自称吸血鬼猎人，当然麦克和山姆对这种传闻嗤之以鼻。不久，麦克迷上了飞车党头目戴维（Keifer Sutherland 饰）的女友斯塔（Jami Gertz 饰）。山姆很快便发现，哥哥的举止竟越来越像传说中的吸血鬼……','Sleep all day. Party all night. Never grow old. Never die. It\'s fun to be a vampire.',8500000,32222567,24.750909,6.8,538,97,'1987-07-31','en','/nH1lvyQvfbL5GKScTtT6zkIvDEn.jpg',3.3437172752051025,3,'2026-09-10',2,NULL,NULL),(1548,'幽灵世界','Ghost World','特里·茨威戈夫的首部剧情长片改编自丹尼尔·克洛斯的邪典经典漫画，以独特笔触描绘青少年疏离感，既浸透着冷峻幽默又充满动人温情。故事发生于高中毕业后的迷惘岁月，骄傲的叛逆少女伊妮德在消费主义美国的文化荒原中直面不确定的未来。当她的愤世嫉俗连挚友爱贝卡也难以承受时，伊妮德发现自己竟与一位年长许多的悲催唱片收藏家产生了意想不到的精神共鸣。凭借其怪诞角色群像、入选奥斯卡提名、金句频出的剧本，以及杂糅复古冷门曲目的不拘一格原声，本片堪称二十一世纪最受狂热喜爱的喜剧之一。[标准收藏]','Accentuate the negative.',7000000,0,14.072941,7.1,426,111,'2001-07-20','en','/rb1UhuPkhfQWZ5UlZB39AirXjwH.jpg',3.290449887052037,3,'2026-09-10',2,NULL,NULL),(1550,'四月碎片','Pieces of April','感恩节到了，白人女孩四月（凯蒂•霍尔姆斯 Katie Holmes 饰）在黑人男友巴比（德瑞克•卢克 Derek Luke 饰）的劝说下，终于鼓足勇气邀请她的家人共进晚餐。然而，家人对于这个约定却各怀心事，原因是四月曾经的叛逆行为令他们望而生畏。这时，父亲吉姆（奥利弗•普莱特 Oliver Platt 饰）还是积极招呼全家前往，但是在路上母亲乔伊（派翠西娅•克拉克森 Patricia Clarkson 饰）对此冷嘲热讽，希望取消这次聚会……  　　四月为了感恩节大餐煞费苦心。她在黑人夫妇的帮助下，制作了香浓的火鸡大餐，但是为了寻找存放的烤箱，她却几经周折；与此同时，巴比为了给四月的家人留下好印象，他计划向朋友借西装，却遭受了意想不到的打击……','She\'s the one in every family.',300000,0,4.270596,6.4,64,81,'2003-01-19','en','/qm3jGZwz2UkwwEFEFzSot8T0pz1.jpg',2.7569572413671333,3,'2026-09-10',2,NULL,NULL),(1551,'别闯阴阳界','Flatliners','几个芝加哥大学附属医院高材生，在好奇心的驱使下，策划了一场探索死亡奥秘的疯狂实验。他们轮流躺在手术室里进入死亡状态，再由其他守护的同学将自己救活。这场惊险又刺激的死亡穿梭，在一个漆黑的深夜里一步步的开始了。  　　第一个进行测试的纳尔逊（基弗·萨瑟兰 Kiefer Sutherland 饰）在“死”去之后，遇见了因他的侮辱而死去的男孩。死而复生后的纳尔逊，虽然各种感官都变得更加敏锐和灵敏，却陷入深深的梦魇之中；接受实验的第二个人是好色的乔（威廉·鲍德温 William Baldwin 饰），他见到了各种色情场面，并且遇见了曾虐待过的女孩；紧接着，戴维（凯文·贝肯 Kevin Bacon 饰）也接受了实验，他则将死亡实验延迟到了两分钟；女学生蕾切尔（朱莉娅·罗伯茨 Julia Roberts 饰）更是在死亡时间里，重温了父亲自杀的经过。在体验过死亡世界之后，那些挥之不去的往日记忆开始无孔不入的侵占他们的一切。','Some lines shouldn\'t be crossed.',26000000,61489265,24.114459,6.3,404,115,'1990-08-09','en','/qQp1cWTLWQsY6RdaNWrA9FVikYV.jpg',3.212647971831802,3,'2026-09-10',2,NULL,NULL),(1555,'西班牙公寓','L\'Auberge espagnole','哈维（罗曼•达瑞斯 Romain Duris 饰）是巴黎某大学毕业生，在老爸的帮助下当了公务员，因该职位需要通晓西班牙经济和语言。所以，他只能告别唠叨妈妈和感性女友玛赫蒂娜（奥黛丽•塔图 Audrey Tautou 饰）奔赴巴塞罗那深造。在机场，他遇见了一堆新婚夫妇，男主人热情地约他到家里居住。但他却对女主人安娜苏菲（朱迪丝•哥德雷科 Judith Godrèche 饰）更感兴趣。在学校，哈维结识了女同性恋伊莎贝拉（西西•迪•法兰丝 Cécile De France 饰），两人先后搬进了一个国际宿舍。这里有平时挑剔的德国男人，有未婚先孕的荷兰男人，有烦人弟弟的英国女人温蒂（凯利•蕾莉 Kelly Reilly 饰），有挑剔的意大利人，他爱上了这种混合的生活。然而，此时玛赫蒂娜却因为忍受不了寂寞而决定与他分手…… ©豆瓣','They came from Paris, Rome, London and Berlin to... the Spanish Apartment... where a year can change a lifetime.',5300000,3897799,13.034602,7,266,122,'2002-05-17','fr','/qKq4uLZDAJhBfpRsfPRYouQ5jW5.jpg',3.148022113095184,3,'2026-09-10',2,NULL,NULL),(1562,'惊变28周','28 Weeks Later','在恐怖的致命病毒横行28周之后，英国境内已经空无一人。由于失去了载体，病毒也随之消亡。随着一架从美国飞来的运输机的降落，在病毒爆发前就离开英国的英国人，重新踏上了被病毒肆虐半年的土地。这可以说是地球上最后的一群英国人，重建家园的重担就落在了这群平民身上。然而，重建工作才开展不久，就有人报告发现了病毒感染的幸存者。科学家们也希望能从幸存者身上提取血清研究出对付病毒的疫苗。可是，万万没有想到的是，病毒并没有像大家想象中的那样已经消亡，反而进化后变得更加强大。这英伦三岛上最后的一群人们，将面对空前的危机……','When days turn to weeks... the horror returns.',15000000,64238440,34.759855,6.5,1197,100,'2007-04-26','en','/ecTl7SKjAhpQmRvWOnrVKw9q33z.jpg',3.524659216032502,3,'2026-09-10',2,NULL,NULL),(1571,'虎胆龙威4','Live Free or Die Hard','某年7月4日，周末，正在休假的约翰•麦卡伦（布鲁斯•威利斯 饰）接到一个新任务：逮捕黑客马特•法莱尔（贾斯汀•朗 饰），然后送到FBI那里接受审讯。其实，事情并没有看上去那么简单：极端恐怖分子经过周密策划之后，准备利用黑客技术，在美国独立日当天让全美国的计算机系统集体瘫痪，从而达到他们控制全球的阴谋。而且，幕后黑手托马斯•加布里埃尔（提摩西•欧里芬特 饰）为了阻止麦卡伦插手这件事情，为他准备了一大堆机关障碍，其中包括绑架他的女儿露西。老英雄遇上了新问题，在马特•法莱尔的帮助下，麦卡伦继续“生猛”……','The old school cop is back!',110000000,383531464,48.93337,6.4,2089,128,'2007-06-20','en','/kG6xqBdykoeAFaZUCcCtdlY0s8i.jpg',3.6695555222861436,3,'2026-09-10',2,NULL,NULL),(1572,'虎胆龙威3','Die Hard: With a Vengeance','西蒙（杰里米•艾恩斯 饰）是个头脑慎密，心狠手毒的恐怖分子。为了实现一场惊天大阴谋，他先是制造了一起爆炸案。在警方紧张破案之际，他又给警长约翰•麦卡伦（布鲁斯•威利斯 饰）打电话，声称警方必须听从他的一系列指令，否则他将继续在全市搞爆炸活动。在杂货店老板宙斯（塞缪尔•杰克逊 饰）的帮助下，麦卡伦完成了西蒙的一系列指令，多次死里逃生。然而意犹未尽的西蒙，命令麦克莱恩去拆除街心花园的炸弹，又宣称在纽约市一所小学校内安放了炸弹。警方和市政官员几乎全部出动，去各小学疏散学生，搜寻炸弹。麦卡伦逐渐对西蒙一个又一个的指令产生疑虑，他终于发现西蒙调动全市警力背后的真相……','Think fast. Look alive. Die hard.',90000000,366101666,51.881077,6.9,2066,128,'1995-05-19','en','/buqmCdFQEWwEpL3agGgg2GVjN2d.jpg',3.784601456864684,3,'2026-09-10',2,NULL,NULL),(1573,'Die Hard 2','Die Hard 2','John McClane is an off-duty cop gripped with a feeling of déjà vu when on a snowy Christmas Eve in the nation\'s capital, terrorists seize a major international airport, holding thousands of holiday travelers hostage. Renegade military commandos led by a murderous rogue officer plot to rescue a drug lord from justice and are prepared for every contingency except one: McClane\'s smart-mouthed heroics.','Die Harder',70000000,240031094,57.69847,6.6,1896,124,'1990-07-02','en','/ybki0UWO3OPhaM6MSniuKC7sy1R.jpg',3.7102445270250546,3,'2026-09-10',2,NULL,NULL),(1574,'芝加哥','Chicago','两个女人，有着相似的经历，甚至是相似的心计，展开了为求成名的争夺战。\r 维尔玛（凯瑟琳•泽塔-琼斯 Catherine Zeta-Jones饰）是一个夜总会舞女，名气不大。因为一怒之下枪杀了出轨丈夫而被关进大牢。比利（理查德•基尔Richard Gere饰）是当地一个靠打谋杀案官司而提升知名度的律师，他受理了这桩案件，心中有着自己的打算。他借助媒体炒作维尔玛的案子，一方面维尔玛瞬间成为红人，而他自己也声名大振。\r 然而洛克茜（芮妮·齐薇格 Renée Zellweger 饰）的案件却让比利转移了注意力。梦想成为歌星的洛克茜也是因为怒杀男友而身负罪名，比利决定要把她包装成楚楚可怜的受害者，令媒体更疯狂的大肆报道。\r 维尔玛觉察形势不妙，为了成名，她跟洛克茜之间的斗法不可避免的开始了。','If You Can\'t Be Famous, Be Infamous',45000000,306776732,32.217425,6.9,677,113,'2002-12-26','en','/7Eq0EgMyWLyOV0GMVcbyrUPjoSH.jpg',3.4367748995653655,3,'2026-09-10',2,NULL,NULL),(1576,'生化危机','Resident Evil','为军方研究生化武器的保护伞公司在浣熊市地下设有巨大的研究中心——蜂巢，由于一次意外事故导致可通过空气传播的生化武器泄露，负责蜂巢安保的电脑系统“红后”启动应急措施，却导致数百名工作人员罹难……四小时后，蜂巢安保人员爱丽丝（米拉·乔沃维奇 Milla Jovovich 饰）在蜂巢出口醒来，并且因为催眠气体而失忆。一支受命关闭红后的特种小队来到此处，与爱丽丝、自称警察的安德森，以及蜂巢工作人员帕克斯组队深入地下。一行人因任务目标与红后冲突而先后遭遇保卫系统和丧尸的连番袭击，而爱丽丝渐渐恢复的记忆揭示了她与同行者非同一般的联系。这场生化丧尸危机该如何解除？又或者根本是一曲绝望的前奏？','A secret experiment. A deadly virus. A fatal mistake.',33000000,102984862,40.715623,6.4,2065,100,'2002-03-15','en','/oI2FkdMoMgUctKDcQduXL6Bj66v.jpg',3.648085070921406,3,'2026-09-10',2,NULL,NULL),(1577,'生化危机2：启示录','Resident Evil: Apocalypse','T病毒在蜂巢中肆虐并很快打破了地面上浣熊市的平静，丧尸开始在人群中出现，保护伞公司将整个城市封锁，计划使用核武器摧毁城市以掩盖病毒外泄的事实。被保护伞注射T病毒使身体能力远超常人的爱丽丝由昏睡中醒来，她在混乱的浣熊市与防卫队员瓦伦汀、记者泰莉等人组成队伍，试图找到脱身之法。另一方面，保护伞公司的科学家艾肯佛博士为搭救被公司抛弃在城中的女儿安琪拉，以提供逃生方式为代价请求爱丽丝和防卫人员卡洛斯两组人马帮助。而保护伞公司派出了由环保分子麦特所改造成的“复仇邪神”阻止这一切……','You\'re all going to die.',45000000,129394835,29.880122,6.1,1267,94,'2004-09-10','en','/3kyjgWU9hZdH9153IgatlRltX0Z.jpg',3.4511924622685326,3,'2026-09-10',2,NULL,NULL),(1578,'愤怒的公牛','Raging Bull','通过这幅令人血脉喷张的自我毁灭式雄性气概肖像，马丁·斯科塞斯创造了现代电影中一部真正伟大且具远见的作品。罗伯特·德尼罗倾注其鲜血、汗水与蛮悍身躯，塑造了荣获奥斯卡奖的杰克·拉莫塔——这位来自布朗克斯的崛起中量级拳击手，其狂暴野心推动他在拳坛获得成功，但不受控的偏执与嫉妒却撕裂了他与身边所有人的关系，包括他的兄弟兼经纪人（乔·佩西 饰）以及美艳世故的妻子（凯西·莫拉蒂 饰）。塞尔玛·斯昆梅克获得奥斯卡奖的剪辑、迈克尔·查普曼极具触感的黑白摄影，以及弗兰克·沃纳匠心独运的音效设计，共同使本片成为一部多层次暴力（身体、情感、心理与精神）的独特而震撼的探索。[标准收藏]',NULL,18000000,23000000,35.524457,7.7,938,129,'1980-11-14','en','/rH7yqByvoN0nW0qIbyEJVcf2pNW.jpg',3.669313308292028,3,'2026-09-10',2,NULL,NULL),(1579,'启示','Apocalypto','故事发生在15世纪末期，辉煌的玛雅文明即将走完最后的历程。青年猎手“美洲虎之爪”加夸尔（鲁迪·杨布拉德饰）是一个丛林小村落中数一数二的勇士，守着身怀六甲的妻子和年幼的爱子，过着自足而平静的生活。然而突然天降横祸，加夸尔的部落遭到一个强大部落的侵袭，一夜之间，奋起反抗的族人们不是当场毙命，就是被掠为战俘，在被俘之前，加夸尔匆忙间把即将分娩的妻子和爱子藏在了洞穴之中。随后，加夸尔与被俘的族人们一道踏上了前往玛雅帝国都城的漫长苦旅。      当时的玛雅帝国正日渐衰落，在神权政治的体制下，玛雅王族和祭司将种种“衰败之象”都归结为神的不满，为了显示对神的忠诚，他们一味奴役百姓修建更多的神殿，他们相信活人祭品是他们所信仰的神的食物，因此更频繁、更隆重的进行祈祷、祭祀，期盼能借神力扭转乾坤。被选为活人祭品的加夸尔不愿像其他受害者那样接受命运的安排，他选择了拚命逃离。为了回到故乡、为了与妻儿团聚，加夸尔一次又一次的陷入极度危险的境地，经历了无数次的磨难…… 【一句话评论】      从影片可以得出一个结论，梅尔·吉布森是一位能力超凡的电影人。 ——奥斯汀纪事      影片不但呈现出一个我们前所未见的世界，还让我们瞥见了令人担忧的未来。 ——迈阿密先驱','No one can outrun their destiny.',40000000,120175290,41.570047,7.3,1221,139,'2006-12-07','en','/cRY25Q32kDNPFDkFkxAs6bgCq3L.jpg',3.695384359652784,3,'2026-09-10',2,NULL,NULL),(1581,'恋爱假期','The Holiday','爱丽斯住在英国伦敦的乡村，而阿曼达则是洛杉矶的美国丽人。她们在天南地北的两端，却遇上了同样的问题：在感情上遭受了挫败，令生活灰暗无光。二人在网上聊天，商议在圣诞节到来之前，到对方的环境去生活，交互双方的住所作为度假场地。于是，一场令人兴奋的旅行开始了。爱丽斯来到美国大都市，阿曼达则乘班机前往极具英伦情调的英国乡村。除了新鲜的生活环境，当地男生的魅力更让她们猝不及防。','It\'s Christmas Eve and we are going to go celebrate being young and being alive.',85000000,194168700,44.967453,6.7,1225,136,'2006-12-08','en','/eHL3vjC6y8VJwx6FywTBK72Yh8Y.jpg',3.5912485417934654,3,'2026-09-10',2,NULL,NULL),(1584,'摇滚校园','The School of Rock','一个自命不凡、惹是生非的吉他手杜威·芬被自己的乐队踢了出来。穷途末路之际，他冒名顶替成为一名代课老师，把一群五年级的优等生调教成激情四射的摇滚乐手。[派拉蒙影业]','He just landed the gig of his life: 5th grade.',35000000,131282949,43.057323,6.7,1414,108,'2003-10-03','en','/zXLXaepIBvFVLU25DH3wv4IPSbe.jpg',3.6238152965842376,3,'2026-09-10',2,NULL,NULL),(1585,'生活多美好','It\'s a Wonderful Life','一位天使被派往人间，帮助一位万念俱灰的商人，向他展现假如他从未存在过，生活将会是怎样的光景。','It\'s a wonderful laugh! It\'s a wonderful love!',3180000,9644124,42.868495,8,1076,130,'1946-12-20','en','/bSqt9rhDZx1Q7UZ86dBPKdNomp2.jpg',3.785451579361154,3,'2026-09-10',2,NULL,NULL),(1586,'秘窗','Secret Window','雷尼 的妻子出了轨，他发现她和另一个男人躺在床上，他提出了离婚。然而，婚姻的阴影并没能使雷尼恢复原气。他的文笔开始暗淡无光，找不到从前的创作激情。于是，他来到了一个湖畔小屋疗伤创作。然而这个小屋，却给他带来了新的麻烦。 首先是一个陌生人的造访令他十分恼火。那人声称雷尼抄袭了他的作品，雷尼百般解释也不能让他信服。于是雷尼翻箱倒柜，想找出原稿，却发现原稿离奇失踪。惊悚事件陆续有来，整个小屋，好像出于某种危险的情势中，雷尼非常害怕，然而却查不出缘由。是不是前妻和她的情人在作怪？他们到底有何目的？然而，真相却让雷尼自己都不敢相信。','The most important part of a story is the ending.',40000000,92913171,32.908414,6.4,972,96,'2004-03-12','en','/hvzw4wufKZkDCTPVeG71Z7pGfZh.jpg',3.452291811126987,3,'2026-09-10',2,NULL,NULL),(1587,'不一样的天空','What\'s Eating Gilbert Grape','因为不能面对丈夫自杀的事实，吉伯特的母亲不停进食，致使体重剧增至六百磅，难以行动。吉伯特的智障弟弟阿尼(莱昂纳多·迪卡普里奥 饰)一出生就被医生诊断活不过十岁，却即将过十八岁生日，最小的妹妹爱伦却正值叛逆的青春期。整个家庭的生计及阿尼的日常起居成了吉伯特的生活全部，姐姐是他唯一的帮手。四处旅游、活泼开朗的贝琪(朱丽叶特·刘易斯 饰)路过小镇，与吉伯特一见钟情，两人很快沉浸在甜蜜的爱情中。贝琪对生活的热情也让吉伯特渐渐认识到，除了家人，生命中他也该有属于自己的追求。阿尼就要过十八岁生日了，这是母亲最后的心愿，待这一切结束，吉伯特能有一个不一样的天空吧。','A film about the love you find...In the last place you look.',11000000,30000000,33.282794,7.5,919,118,'1993-12-17','en','/mFRNL7Qq5APuJdprvmkQFQdOy5B.jpg',3.6238829369662287,3,'2026-09-10',2,NULL,NULL),(1588,'魅力四射','Bring It On','蓝丘高中有一支著名的拉拉队名叫“托罗”，这支队伍已经连续六届称霸在全国的拉拉队比赛。多伦斯（克尔斯腾•邓斯特 饰）接手这支拉拉队成为新一任队长，她雄心勃勃的想要队伍在自己的带领下继续光辉的前程。就在她们正准备积极备战与全国比赛的时候，多伦斯才惊讶的发现，那套她们引以为豪的舞步原来是前任队长从对手那里学来的。这便使多伦斯与队友们着急不已，她们也只能重新编排一套新的舞步。可是这并不是件容易的事，她们都显得信心不足。与此同时，她们的强劲对手克罗佛高中的拉拉队也正陷入了经费问题的困难当中。可是时间并没有因为她们的努力而放慢脚步，比赛的时间还是如期而至，到底谁能得到最后的冠军呢？','May the best moves win.',28000000,90449929,14.754281,5.8,568,98,'2000-08-25','en','/9FxKW6wxcvSzmQOFA1Kbw0O1laF.jpg',3.2039516879025243,3,'2026-09-10',2,NULL,NULL),(1590,'复制贝多芬','Copying Beethoven','1824年，维也纳。年仅23岁的安娜·霍兹（戴安·克鲁格 Diane Kruger 饰）凭借自己对于音乐的出色领悟力成为贝多芬（艾德·哈里斯 Ed Harris 饰）的乐稿抄写员，此时已经失聪的贝多芬正醉心于创作自己的“告别作”。安娜本想借着为贝多芬工作的机会向他学习，从而成为一名出色的作曲家，可是很快她发现贝多芬是一个固执、粗鲁、一味沉浸在自我世界中的疯子。贝多芬《第九交响曲》的首演由于安娜在危急时给予帮助而取得成功，两人的关系逐渐好转。安娜拿出自己所写的曲子让贝多芬评价时，却惹来贝多芬尖酸刻薄的嘲讽，安娜一气之下离开了贝多芬。在贝多芬的请求下，安娜又重新回到贝多芬身边并且尝试接受他那些过激言语所传达的意见，安娜似乎渐渐理解了这位天才级的大师……  　　本片2007年在素有“西班牙奥斯卡”之称的哥雅奖（Goya Awards）上获最佳欧洲电影提名。',NULL,11000000,0,5.062687,6.2,42,104,'2006-09-10','en','/xplAbPXhZF9B3H4OnhjQsEKUESe.jpg',2.6635100393243243,3,'2026-09-10',2,NULL,NULL),(1591,'何处是我家','Nirgendwo in Afrika','1938年1月，德国的政治空气越来越紧张，一种暴雨将至的恐慌感笼罩在犹太人的心头。沃尔特先行前往肯尼亚开发农场，并决定举家迁往非洲避难。在他的催促下，妻子洁塔带着5岁的女儿蕾吉娜告别家乡，踏上了陌生的非洲大陆。 面对着生疏的面孔、恶劣的环境、贫瘠的土地，这一家人开始了艰难的适应过程。原本是律师的沃尔特从头学起管理农场，而过惯奢侈日子的洁塔则不得不学会在这尚未开化的穷乡僻壤生活，繁重的体力劳动与背井离乡的忧愁令她逐渐心生怨气，夫妻间也愈发不和。而充满好奇的蕾吉娜却对周围一切新鲜事物大感兴趣，她迅速接受了当地的风俗习惯，与孩子们交上了朋友，生机勃勃的大草原也令她着迷。6个月后，英国正式对德国宣战，沃尔特甚至一度被关进一所英军营地。在一位英国兵帮助下，洁塔为他弄来了一张经营农场的许可证。蕾吉娜也进入了当地的英国人学校读书。外面的世界战火纷飞，这里的时光也在或平静或不安的日子中流逝。他们学会了珍惜生活，认识到文化之间的差异，也努力寻回昔日的自我和情感。特别是洁塔变得越来越独立，她重新确定了自己在家庭中的位置。战争终于结束，沃尔特得到了回法兰克福的工作机会，然而他却开始犹豫究竟是该返乡还是继续留在非洲，尤其是蕾吉娜已经完全融入了肯尼亚……','One family\'s tale of a homeland lost... and a homeland found.',0,0,3.481517,7,32,140,'2001-12-11','de','/k5e9FOYnpRfZRbSKXrHz3vAGpGC.jpg',2.612194643917638,3,'2026-09-10',2,NULL,NULL),(1593,'博物馆奇妙夜','Night at the Museum','拉里•达利（本•斯蒂勒 饰）生活似乎不太顺利：经常换工作，居无定所；妻子与他离婚，找了一个证券经纪人，即将再婚，自己在儿子心目中的地位也岌岌可危。达利为了挽救自己的生活，也为了争取到儿子的抚养权，他不得不放弃“做大事”的梦想，成为了纽约自然博物馆的夜间警卫。达利原本以为这是一份无聊的工作，谁知道上班的第一天，不可思议的事情就发生了：博物馆里的法老金牌拥有神奇的魔法，当夜晚来临的时候，馆中所有的标本都会活过来，追逐骨头的霸王龙、爱捣乱的猴子、暴虐的匈奴王、钻木取火的穴居人……将一切弄得不可开交。在26届总统特迪•罗斯福的帮助下，达利好不容易控制住了局面，但是，他马上又遇到了新的麻烦：有人想打法老金牌的主意。职责所在，也是为了博物馆夜晚的奇迹，达利不得不挺身而出。','Where History Comes To Life',110000000,574480841,48.780039,6.3,2862,108,'2006-10-20','en','/pDsAAYf6Zn0yiAGJ6lYGs6hoZ4E.jpg',3.7184283920219725,3,'2026-09-10',2,NULL,NULL),(1597,'拜见岳父大人','Meet the Parents','格雷戈（Ben Stiller 本•斯蒂勒 饰）准备向相恋多年的女友潘米拉（Teri Polo特莉•保罗 饰）求婚时，意外获悉了求婚成功成功与否，不仅要过美人关，更要过岳父关。潘米拉的姐姐下个礼拜即将举行婚礼，届时格雷戈将和潘米拉一起回家参加婚礼。小伙子心想这次正是讨好未来岳父，搞定岳父那关的大好时机。格雷戈的名字在美语中很容易被理解成“同性恋•性交者”的意思，有着这么个稀奇古怪的名字，注定格雷戈拜见未来岳父之行不会如他所料那般顺利。果然，当他们来到了潘米拉家时，格雷戈虽然表现得文质彬彬，但当他总是插话时力图幽默却效果相反时，未来岳父（罗伯特•德尼罗 Robert De Niro 饰）的脸色越来越难看。','First comes love. Then comes the interrogation.',55000000,330444045,29.97224,6.6,1698,108,'2000-10-06','en','/nSVdRFNnyJC3FfrR9cFEb9SkkAH.jpg',3.6196636928537913,3,'2026-09-10',2,NULL,NULL),(1598,'恐怖角','Cape Fear','迈克斯（罗伯特•德尼罗 Robert De Niro 饰）因为强奸而遭到起诉，他找来了律师萨姆（尼克·诺尔蒂 Nick Nolte 饰）为自己辩护；萨姆是一个女权主义者。出于义愤，萨姆在辩护是故意隐瞒了一项对迈克斯有利的证据，最终导致了迈克斯被多判了6年。本来不懂法律的迈克斯在狱中通过自学法律发现了萨姆对他的背叛，发誓一定要找萨姆报仇。 一晃14年过去了，迈克斯刑满获释了，他开始展开他的复仇计划。','There is nothing in the dark that isn\'t there in the light. Except fear.',35000000,182300000,27.714043,7,675,128,'1991-11-15','en','/meJZAAuVcjic2ipvbOPz5UlE4P9.jpg',3.440101247114713,3,'2026-09-10',2,NULL,NULL),(1599,'我爱哈克比','I ♥ Huckabees','伯纳德（达斯汀·霍夫曼 Dustin Hoffman 饰）和薇薇安（莉莉·汤普琳 Lily Tomlin 饰）是一对感情十分要好的夫妻，两人经营着一家私人侦探所，专门帮助人们解决生活里遇到的各种难题。作为他们的客户，艾伯特（詹森·舒瓦兹曼 Jason Schwartzman 饰）的处境显然不容乐观，仿佛是在一瞬间，他发现生命中的一切都偏离了他的掌控，朝着未知的方向迅速发展开去，与此同时，他的死对头布莱德（裘德·洛 Jude Law 饰）似乎正春风得意。\r 　　然而，上帝是公平的，因为布莱德也有着自己无法解决的难题，对于他如花似玉的女朋友道恩（娜奥米·沃茨 Naomi Watts 饰），布莱德始终放心不下，于是他成为了伯纳德和薇薇安的下一个客户','An existential comedy',22000000,0,14.925633,6.2,239,106,'2004-09-10','en','/h27ytqXyOrAB6KmRx2abOp8p2W.jpg',3.064458051179094,3,'2026-09-10',2,NULL,NULL),(1613,'51号公式','The 51st State','比历史上任何的震颤、愉悦、高潮都强烈51倍的蓝色化合物，2千万的交易，为蓝色药丸疯狂的城市。这一切都开始于1971年，艾尔默·麦科尔罗伊(萨缪尔·杰克逊)毕业的当天，在开车回家的路上吸大麻被当场擒获，于是一眨眼的功夫，他的药剂师执照之梦，象他手里的青烟一样飘散了……','Nice Wheels. Dirty Deals. And One Mean Mother In A Kilt.',28,14,9.670031,5.9,173,93,'2001-12-07','en','/aYlrGirWrRCTU1PF6Svghn1EMAc.jpg',2.963904325936554,3,'2026-09-10',2,NULL,NULL),(1619,'绑票惊爆点','The Way of the Gun','帕克（瑞恩·菲利 Ryan Phillippe 饰）和隆巴顿（本尼西奥·德尔·托罗 Benicio Del Toro 饰）是合作多年的老友，靠着经营绑票的勾当从中牟取暴利。这一次，他们将目标放在了一个名叫罗宾（朱丽叶特·刘易斯 Juliette Lewis 饰）的女人的身上，她的腹中怀着富豪史达克先生（斯科特·威尔森 Scott Wilson 饰）的孩子，他们决定利用这个孩子，向史达克好好的敲上一笔。  　　然而，这一次，兄弟两似乎看走了眼。史达克可不是可以随他们欺负的软蛋，与此同时，看似天真无邪的罗宾亦是一个难缠的女人，在史达克派出的杀手步步逼近之时，帕克也坠入了罗宾一手编织的情网之中。眼看着搭档鬼迷了心窍，隆巴顿必须做好万全的准备。',NULL,8500000,19125401,8.775844,6.4,100,119,'2000-09-08','en','/wrjMMdgn1a4ChlaBmlzKnb78nr6.jpg',2.8663961727182032,3,'2026-09-10',2,NULL,NULL),(1620,'杀手：代号47','Hitman','代号47（蒂莫西•奥利分特 饰）是一个利用基因技术制作的复制人，受雇于名为“The Agency”的组织进行刺杀活动，47是他颈背条码的最后两个数字，也是他的名字。因为卷入了政治阴谋，47在东欧遭到了国际刑警和俄国军队的双重追杀。在追查真凶的过程中，他遇上了一个致命的女人（欧嘉•克瑞兰蔻 饰）。杀手的冷酷无情渐渐被女人瓦解，但是生命也正在受到威胁……','Assassin 47',24000000,99965753,42.669304,5.9,966,89,'2007-11-21','en','/asss61hhkFgGOCM04aPUwZjUlZn.jpg',3.3875981740935757,3,'2026-09-10',2,NULL,NULL),(1621,'颠倒乾坤','Trading Places','路易斯·温索普三世是个金融家，他在兰道夫-莫蒂默公爵兄弟公司里有着显赫的地位和优厚的待遇。黑人比利是个流浪汉，为了讨口饭吃，他装扮作残废军人沿街乞讨。一次，比利被警察追捕，情急中躲进了上等俱乐部，不巧撞见了路易斯·温索普，路易斯遂将其交给了警察。莫蒂默公爵兄弟目睹了此事的全过程，兄弟俩对这件事持不同的观点，就命运的问题发生了争执，为了印证他们的话，两人决定以打赌这种形式定输赢：如果条件成熟，比利也可以成为上等人，而温索普同样可沦落到最底层。接下来，莫蒂默兄弟想方设法地将温索普搞臭，使他狼狈不堪，还丢掉了工作和金钱，而接替他的人则是比利。这种巨大的转变将温索普和比利弄得莫名其妙，洋相出尽后才发现了事情的真相。最后，温索普和比利团结起来报复了莫蒂默兄弟。','Some very funny business.',40600000,90400000,34.022209,7.1,738,116,'1983-06-07','en','/8mBuLCOcpWnmYtZc4aqtvDXslv6.jpg',3.494893359795306,3,'2026-09-10',2,NULL,NULL),(1624,'大话王','Liar Liar','弗莱彻是个炙手可热的大律师，他追求的物质生活，跟他在法庭上追求的真相一样：一切都能以金钱来衡量。事实对他来说，远不及有力的辩词来得重要，于是他为了胜诉，在法庭上说谎骗人，丝毫不以为意。久而久之，他在日常生活上也变得口是心非，成为不可救药的大骗子。就连他和前妻所生的5岁小儿子麦克斯，都对他的谎言习以为常，虽然如此，每次麦克斯遇到父亲爽约，却编造谎言当藉口时，他还是会伤心难过。 　　麦克斯生日那天，弗莱彻又因事失约，没有能前往参加他的生日派对，失望的麦克斯于是在许愿时许下父亲能有一天不能说谎的心愿，一连串神奇的事情也因此发生了……','Trust me.',45000000,181000000,26.721386,6.4,1424,86,'1997-03-21','en','/AjPfXn1ojsWX85sWzT5AmOeumAM.jpg',3.5287663751164904,3,'2026-09-10',2,NULL,NULL),(1635,'The Island','The Island','In 2019, Lincoln Six-Echo is a resident of a seemingly \"Utopian\" but contained facility. Like all of the inhabitants of this carefully-controlled environment, Lincoln hopes to be chosen to go to The Island — reportedly the last uncontaminated location on the planet. But Lincoln soon discovers that everything about his existence is a lie.','Your time will come...',126000000,162949164,37.68056,6.5,1770,136,'2005-07-20','en','/mzEY7u5tbRdj2fl6qkMa5WtHpNM.jpg',3.626295244219211,3,'2026-09-10',2,NULL,NULL),(1636,'神鬼愿望','Bedazzled','艾利奥特是个呆头呆脑的电脑公司技术顾问，爱上公司一位漂亮的女同事爱莉森，却苦于没机会表达自己的爱意。一晚，艾利奥特和同事们在PUB闲聊，无意撞见爱莉森，在同事及酒精的起哄下，艾利奥特终于鼓起勇气向她求爱，可是下场却是被拒绝和取笑。\r 　　举足无措的艾利奥特在PUB中遇见了另一位外表艳丽的红衣女子，这名女子对艾利奥特说：“我是魔鬼，只要给我你那不值钱的灵魂，我就给你七个愿望！”在魔鬼的诱惑下，艾利奥特许下自己的愿望：“希望自己成为娶爱莉森为妻的富翁。”\r 　　艾利奥特的愿望真的实现了！他成了满口西班牙语的南美洲大富翁，而且爱莉森就睡在他的旁边！当艾利奥特高兴万分的时候，才猛然发现自己竟是个被人追杀的大毒枭！紧接着就是一堆爆破、动作场面，非常滑稽。毫无疑问，这个梦想破灭了！\r 　　艾利奥特在之后的愿望中，先后变成摇滚歌星、NBA篮球明星……他发现魔鬼虽都能达成他所许的愿望，但也都让他有某方面的“残缺”，使他欲哭无泪。就好象虽然成为抱得美人归的大富翁，但大毒枭的遭遇是很难堪的；而成为“Stone Cold Dead”摇滚乐队的主唱，也只带给他15分钟的名声，由于大量吸毒和酗酒，很快就被另一同行取代了位置。\r 　　他最后要怎么许愿才能让魔鬼无法进行恶作剧呢？','Meet the Devil. She\'s giving Elliott seven wishes. But not a chance in Hell.',48000000,90383208,19.348007,5.6,512,93,'2000-10-19','en','/bcpstzWj9mMs5j2tldI33ApWLM1.jpg',3.169560511122077,3,'2026-09-10',2,NULL,NULL),(1637,'生死时速','Speed','退休炸弹专家佩恩因不满政府的退休政策，产生了报复社会的念头。他先是在电梯里安装炸弹，劫持人质勒索100万美元赎金，但被特警杰克拆除了炸弹，救出了人质。佩恩趁乱逃脱。一计不成，佩恩并没有放弃，他继续他疯狂的计划。这次他炸毁了一辆公车，并在另一辆公车上安装了炸弹，只要该公车的时速超过了50英里就不能再减速，否则就会引起爆炸。当杰克赶上这辆公车时，公车已经满载乘客行驶在高速公路上，时速也早已过了50英里。杰克是俗称的“胆生毛”，他冒险上了公车，和佩恩之间的生死时速开始了。','Get ready for rush hour',30000000,350448145,49.526736,6.8,1783,116,'1994-06-09','en','/82PkCE4R95KhHICUDF7G4Ly2z3l.jpg',3.7190136383409786,3,'2026-09-10',2,NULL,NULL),(1639,'生死时速2：海上惊情','Speed 2: Cruise Control','在《生死时速》中曾经一同出生入死，共同跨上感情高速路的安妮和杰克如今已劳燕分飞。原因很简单，危难关头产生的感情是不会长久的。杰克虽然勇武过人，但感情上不够细腻。而更主要的是安妮不想总过那种提心吊胆的日子。安妮的新男友阿列克斯是警察局敢死队队员。为了不让安妮担心，他隐瞒了自己的真实身份。但在一次飞车执行追捕任务时，还是被正在驾车考试的安妮发现了。阿列克斯真诚地向安妮道歉，并愿带安妮乘豪华客轮共赴加勒比海度假作为补偿。','As the stakes get higher, the ride gets even faster.',160000000,164508066,23.336875,4.1,434,121,'1997-06-13','en','/8QSrSgPVPlpG8GDREUOxRV6z8lE.jpg',2.980907437199068,3,'2026-09-10',2,NULL,NULL),(1640,'撞车','Crash','一个黑人电视导演和他的妻子，莫名其妙地因为莫须有的违章驾驶受到了白人警察的侮辱；看似该受到谴责的警察却在最危急关头挽救了那名曾遭他侮辱的黑人妇女；老实巴交的波斯商店店主，却差点谋杀了有着刺青的墨西哥修锁匠；地区检察官和他的妻子被抢吉普车后只能把怨气发泄到无辜的修锁匠身上；黑人警察在承受着上司的威胁和焦急地寻找自己的弟弟。这一切看似无关的琐事，却在36小时内以一种出人意料的方式绞缠在一起，在这个以暴力，性，金钱闻名的多民族、多文化聚集的大城市—洛杉矶街头一幕幕上演。','You think you know who you are. You have no idea.',6500000,98410061,28.223163,7.2,1149,112,'2004-01-13','en','/3R28iyBqIeziMRCFMzJsqylXzwv.jpg',3.6282459347463405,3,'2026-09-10',2,NULL,NULL),(1642,'网络惊魂','The Net','安吉拉 是一个与世隔绝的程序员，电脑是她的好帮手也是好朋友，她的大部分生活都围绕着电脑有条不紊的进行着。一次偶然中，安吉拉收到了同事寄来的一张磁盘，而之后没多久，这位同事便死于非命。之后，在一次度假中，安吉拉邂逅了一名英俊帅气的男子，但很快聪明的安吉拉便发现了这名男子心中所怀的不轨。 　　安吉拉隐约觉得自己被卷入了大麻烦之中，而一切和那张神秘的磁盘脱不开干系。一次意外中，安吉拉陷入了昏迷，醒来后的她丢失了一切可以证明其身份的证件，而当她完成了挂失补办程序之后，手中的证件上赫然写着一个陌生的名字。这其中究竟发生了怎样的变故？在一次又一次逃脱暗杀的过程中，安吉拉也在渐渐的接近真相。','No driver\'s license, no credit cards, no passport, no access to her bank accounts in a foreign country ... She finds her identity stolen.',22000000,110627965,23.218144,5.6,354,114,'1995-07-28','en','/dtupntUFMD5iXBo8HLfALt2ET4R.jpg',3.1116381005789426,3,'2026-09-10',2,NULL,NULL),(1645,'杀戮时刻','A Time to Kill','黑人工人卡尔（塞缪尔•杰克逊 Samuel L. Jackson 饰）十岁的女儿被两个白人蹂躏了，在那种族歧视盛行的岁月，卡尔不相信法律能帮他和女儿讨回公道。于是，他径自找到了那个家伙并将他们射杀。复仇后的卡尔直接来到了警察局投案自首。  　　年轻律师杰克（马修•麦康纳 Matthew McConaughey 饰）被指派为卡尔的辩护律师，由于卡尔根本不相信法律会对黑人公正，所以他和杰克没有达成一致。果然，庭上卡尔收到了不公正的对待。法律系那大学生艾伦（桑德拉•布洛克 Sandra Bullock 饰）这时出现了，她站在杰克这一边，决定为卡尔做无罪辩护。  　　虽然杰克获得了支持，但他的生活却受到了极大的威胁：当地的三K党用尽各种方法要挟杰克，甚至威胁要炸毁他的房子！卡尔看到了杰克和其他人的努力，他决定和众人团结一致，为公义而战。','Experience a time you\'ll never forget.',40000000,152266007,25.219805,7,509,149,'1996-07-24','en','/1jj7mmPfcI3eSC4XAPAhqBPiPC1.jpg',3.3546794323643763,3,'2026-09-10',2,NULL,NULL),(1646,'自由作家','Freedom Writers','爱林（希拉里·斯万克 Hilary Swank饰）从事的第一份教育工作，就是在威尔逊学校一个糟糕透顶的班级里担任老师。这里有着给老师们带来噩梦的学生：他们虚度光阴，消磨时辰，把学校当成18岁之前的游乐场；更混乱的是，学生们来自社会里的不同种族和各类底层阶级，分帮结派互相斗殴。\r 　　爱林想方设法让仇恨远离孩子们的心，消解他们之间的敌意，可是，作为一名白人老师，孩子们对她树起了重重心墙，爱林的教育理想在现实中一次又一次地碰壁。\r 　　孩子们跌入深渊的心灵是否无药可救，他们的未来能否在爱林的循循教导下重现曙光，爱林的肩上承着千斤重担，她只有一本或者可以感化孩子的《安妮日记》，以及一颗热忱真诚的心，带领迷失的孩子找到明灯。','Their story. Their world. Their future.',21000000,41170784,17.746981,7.5,356,123,'2007-01-05','en','/221iE3mK1lRc4QzREXtj2dKjpw9.jpg',3.2872912354102577,3,'2026-09-10',2,NULL,NULL),(1648,'比尔和泰德历险记','Bill & Ted\'s Excellent Adventure','泰德（基努·里维斯 Keanu Reeves 饰）和比尔（亚历克斯·温特 Alex Winter 饰）是就读于同一所高中的同学，两人之间感情十分要好。也许，他们会如此一见如故的原因在于，两人的智商处在同一水平线上，没错，就是那条比别人都低的水平线。更糟糕的是，比尔和泰德在一起只晓得整日游手好闲，丝毫不将心思放在学习上，成绩可想而知。历史考试在即，就在这个节骨眼上，泰德和比尔得知了一个惊天噩耗，如果不能通过这次考试，他们就将无法拿到毕业证书，一下子懵了的两人陷入了手足无措之中。就在此时，一位名叫鲁佛斯（乔治·卡林 George Carlin 饰）的天外来客出现在了他们面前，他自称来自未来世界。无论鲁佛斯所言是真是假，泰德和比尔明白，他是他们那道毕业证书的唯一一根救命稻草。','History is about to be rewritten by two guys who can\'t spell.',10000000,40485039,25.929893,6.7,454,90,'1989-02-17','en','/rzZa2uCf7UAqAzpSHgkXSdhdH3S.jpg',3.2896766877978774,3,'2026-09-10',2,NULL,NULL),(1649,'比尔和泰德畅游鬼门关','Bill & Ted\'s Bogus Journey','热爱摇滚乐，一心想赢得大赛的阿比阿弟不小心被另一对长得一模一样的阿比阿弟机器推冥界。在他们大闹阴曹地府、畅游天堂之后还拖著死神回到阳世，拯救女友的性命···节奏强烈的热门歌曲、地狱游历的惊险怪谭，还有一对胡搞蛮缠的活宝兄弟，就已经使「阿」片够新鲜热闹了，再加上导演创新的拍摄手法，许多趣味的桥段串连，使本片不论在视觉效果、技术处理上皆比上集精进，娱乐效果更有过之而无不及。','Once... they made history. Now... they are history.',0,0,11.349664,5.9,308,98,'1991-07-19','en','/4n0iJhdFGhQDBgUsxV8AAC6SSIo.jpg',3.085732034355376,3,'2026-09-10',2,NULL,NULL),(1651,'骗婚记','La Sirène du Mississipi','杜鲁福为法国影坛天王天后打造他们的高峰代表作。尚保罗·贝蒙多与嘉芙莲· 丹露的演出令人神魂颠倒，影片取得空前成功，亦成了杜鲁福电影生涯的转折点。法属岛国的烟草老板，用征婚启事寻找另一半，飘然而至的女人，竟美得像个掉下凡间的天使。新婚不久爱妻赫然拿掉他整副身家人间蒸发，他奔走天涯海角原要寻仇，但面对她的一刻，心却瘫软地上。杜鲁福将希治阁完美融合到爱情里去，拍出只此一家的惊栗爱情片。镜头随着亡命鸳鸯从热带森林跑过冰封雪地，弹奏出一阕神采飞扬的狂想曲，彩色阔银幕的眩目影像如同飨宴，尽情满足影痴贪婪的眼睛。','The Bride Came as Advertised...With an Unadvertised Special',0,0,3.654018,6.7,32,123,'1969-06-18','fr','/pTD0x1P2bXi3AosA9RVCh1s9GjB.jpg',2.6088013411730744,3,'2026-09-10',2,NULL,NULL),(1656,'佐罗传奇','The Legend of Zorro','1850年加州即将成为美利坚合众国第三十一州，但是某些别有用心的人士以及一个中古时代的神秘组织却为了本身的利益从中阻挠，于是蒙面侠佐罗必须再度出马，帮助加州人民对抗这些强权恶霸。在这同时，贪污腐败的麦吉文伯爵不断欺压善良的老百姓，强占他们的土地，并威胁他们的人身安全。蒙面侠佐罗也必须阻止他的恶行。','The original caped crusader is back!',75000000,142400065,31.054334,5.9,893,129,'2005-10-24','en','/oulvMkerckhqFbH13RHsvkgkPzX.jpg',3.3452573151856377,3,'2026-09-10',2,NULL,NULL),(1667,'帝企鹅日记','La Marche de l\'empereur','这是一部真实反映企鹅生活的电影。南极大陆的北部气候温和，食物充足；而南部则终年覆雪、气候寒冷，食物短缺。但南部也有其好处，那就是这里生态稳定，没有天敌的追击。为了让企鹅宝宝健康成长，企鹅爸爸妈妈每年都会从北部来到南部孵化小企鹅蛋。\r 　　企鹅爸爸和企鹅妈妈轮流进行孵蛋工作，另 一方则不远万里去找寻食物。途中的艰辛任何人都难以承受，而柔弱的企鹅们则每年都这样往复进行着这项艰辛的任务。\r 　　影片所展现的顽强的生命力发人深省。','In the harshest place on Earth, love finds a way.',8000000,127392239,17.537154,6.9,358,80,'2005-01-26','fr','/7DuALkXeR3CK7xYVnvUAt8dOvWT.jpg',3.229226231796678,3,'2026-09-10',2,NULL,NULL),(1669,'猎杀红色十月','The Hunt for Red October','1984年11月，苏联正处于戈尔巴乔夫上台前夕，也是美、苏两个超级大国明争暗斗的冷战高潮时期。苏联研制了一艘新型核潜艇“红十月号”，并派老练的雷米斯负责该艇的首次试航演习。此时，美国中央情报局也获取了有关“红十月”号的情报。途中，艇长雷米斯杀死了发现他隐私的专横政委并命令潜艇改变航向。他向全体官兵声称此举是要利用该艇先进的无声推进系统去通过美国海军的监视网并纵情游览美国的海岸线。一个苏联高级将领秘密挟带一艘超级军用潜艇“红月十月号”，究竟是想投奔美国，还是制造一场核战争？苏联国防部大为震动，遣派军队追捕，美国中央情报局亦派出精英部队拦截，一场联系美苏两国军事平衡的追击行动由此展开。','Invisible. Silent. Stolen.',30000000,199200000,46.212155,7.2,957,134,'1990-03-02','en','/ftUnGph9vJnek6hALIlwcCU1nPb.jpg',3.615251602167211,3,'2026-09-10',2,NULL,NULL),(1677,'灵魂歌王','Ray','本片是是一部关于美国灵魂乐之父雷.查尔斯(Ray Charles)的人物传记影片。像大多数的音乐天才一样，他的一生经理了许多的坎坷与磨难，但最终取得了辉煌的成功。','The extraordinary life story of Ray Charles.',40000000,124731534,21.743321,7.2,467,152,'2004-10-29','en','/lpYXebyLVPtaHjegqqJ5Zr3Iy1i.jpg',3.3460096449536896,3,'2026-09-10',2,NULL,NULL),(1683,'致命报应','The Reaping','科学与宗教之间的界限到底怎样划分？两者是对立的，还是一步就能跨越？凯瑟琳（希拉里·斯万克 Hilary Swank饰）的转变就多次源于这个古老神秘的哲学命题。她曾经忠实地信仰天主，虔诚布道，丈夫和女儿却惨死他人手中，这令凯瑟琳不再相信宗教，她坚定的认为，科学才是一切现象的根本，所谓神，只是人们愚蠢的迷信。\r 小镇上发生的怪事，却令凯瑟琳的观念发生了又一次的逆转。只因为，圣经上的预言和这里发生的一系列怪事竟然不谋而合。面对这些神秘的现象，凯瑟琳发现，自己的科学信仰面临着严峻的挑战，在小镇沸沸扬扬的风波中，也许主宰一切的是她一直不愿相信的神明……','What Hath God Wrought?',40000000,62771059,13.445697,5.4,205,99,'2007-04-05','en','/uxz3VCe14HMNXxx2MkCxizKqcBS.jpg',2.9744777211615814,3,'2026-09-10',2,NULL,NULL),(1685,'失陷猩球','Beneath the Planet of the Apes','为了寻找乔治·泰勒的飞船，宇航员布伦特所在的飞船也来到了3955年的“人猿星球”。布伦特很快遇到了与乔治·泰勒相同的遭遇。在这里，布伦特发现了一小群尚未退化反而获得进化了的变种人，他们生活废旧的建筑内，偷藏着一颗遗留下来的核弹。同时布伦特也发现被囚禁在这里的乔治·泰勒，并与他一起逃出变种人的地下洞穴。最后泰勒与布伦特引爆了核弹，而人类与猿族玉石俱焚，整个星球就此毁灭。','An army of civilized apes...A fortress of radiation-crazed super humans...Earth\'s final battle is about to begin - Beneath the atomic rubble of what was once the city of New York!',3000000,18999718,24.393296,6.2,361,95,'1970-05-01','en','/9dnmsELrfR5oghsKg2s29rhDo5Q.jpg',3.1775433804547157,3,'2026-09-10',2,NULL,NULL),(1687,'逃离猩球','Escape from the Planet of the Apes','在乔治·泰勒和布伦特引爆核弹之前，猿族科学家吉拉和考耐利斯通过飞船穿越到了1973年的地球，并接受了政府科学家的检查以及军方顾问的审问。尽管他们向人类透露了地球的未来——猿人将成为人类的统治者，两位科学家斯蒂芬妮·布兰顿和刘易斯·迪克森依旧愿意帮助他们融入到当时的社会当中。而当科学家奥托·哈斯莱因发现吉拉怀孕时，他开始担心猿族新的生命将意味着猿族的崛起，于是他开始密谋将吉拉和考耐利斯杀害以防未来的悲剧发生。在吉拉和考耐利斯被哈斯莱因害死前，他们的宝宝米洛出生了。拥有过人才智的米洛被马戏团团长艾蒙多抚养长大，并改名为“凯撒”，而艾蒙多则向社会隐瞒了凯撒的超人天赋。','Meet baby Milo who has Washington terrified.',2500000,12348905,18.30961,6.3,264,98,'1971-05-20','en','/wN4NRxyke2XVn3ZTPCuv9szhixq.jpg',3.1021827258921735,3,'2026-09-10',2,NULL,NULL),(1688,'猩球征服','Conquest of the Planet of the Apes','马戏团主任艾蒙多（里卡多·蒙特尔班饰）收留并保护了一只孤苦无依的猩猩，取名凯撒（罗迪·麦克道尔饰）。在艾蒙多无微不至的关怀下，凯撒渐渐长大，它和“父亲”艾蒙多之间的关系十分亲密。一场病毒的肆虐让猫和狗在地球上绝迹了，失去了最忠诚的朋友们，需要动物们陪伴的人类将目光转向了和他们极为相像的猩猩，就这样，饲养猩猩当做宠物成为了新的时尚。然而，人类的残暴本性使得这些原本温顺善良的猩猩们生活苦不堪言，它们被折磨虐待，永远的失去了自由。终于，猩猩们决定不再忍耐，在凯撒的带领下，它们英勇起义，发誓定要推翻人类的压迫和统治。','All new! The revolt of the apes. The most awesome spectacle in the annals of science fiction!',1700000,9700000,18.828683,6.1,236,88,'1972-06-29','en','/xN5VSWUoC2gXaAYl4GB92Q0cPlN.jpg',3.063239410528662,3,'2026-09-10',2,NULL,NULL),(1690,'人皮客栈','Hostel','三名无忧无虑的学生前往斯洛伐克找寻一家据称满是放荡女人的青年旅馆，结果却遭到了无法想象的折磨。','Welcome To Your Worst Nightmare',4800000,80578934,38.83192,5.7,887,94,'2005-01-06','en','/qrcMbqpcfGBShJ2VWzCb3FmSBrl.jpg',3.3287222220072437,3,'2026-09-10',2,NULL,NULL),(1691,'人皮客栈2','Hostel: Part II','美国年轻人最典型的特点就是无知没大脑，他们愿意尝试新鲜事物，哪有热闹就往哪凑，而且过于自以为是--年轻人好奇心旺盛，这本无可厚非，坏就坏在他们太容易相信别人，只要投其所好稍加利用，就没有不上钩的。\r 三个美国女孩为了减轻学业压力所带来的烦恼，决定在周末来一次自助游，地点就定在了旅游胜地布拉格。在这个异域风光怡人的美丽城市中，她们玩得并不尽兴，似乎总觉得这次旅行缺少点什么。这时候，三个女孩遇到了在美术课上的一位美丽模特，并受到她热情的邀请，一起到布拉格附近的小镇来次天然温泉之旅，她深情并茂地将那里描述得美轮美奂，许诺三个女孩可以充分放松、恢复活力。当然这个过程如果没有帅哥为伴，岂不可惜？三个在这方面没什么经验的女孩，几乎是想都没想，马上就点头同意了对方的建议，收拾行囊，一起向小镇进发……她们到那里一看，发现自己还真是没有白来，小镇充满着浓郁的欧洲风情，热情开放的自由作风更是让三个女孩大呼受不了，在模特的带领下，她们找到了下榻的客栈，却发现自己还未来得及享受，就已经进入了噩梦般的开始：模特将三个女孩卖了，使她们成了供人猎杀的猎物。这是一个病态的世界，如果她们最终能够幸运地生存下来的话，肯定也会真正体会到，什么叫 “往事不堪回首”吧。','Americans...they have no imagination.',10200000,35619521,20.745052,5.6,453,93,'2007-06-08','en','/r1DdltU2jfvvUA994OqeIYpWL9.jpg',3.1507307725314155,3,'2026-09-10',2,NULL,NULL),(1696,'The Devil\'s Rejects','The Devil\'s Rejects','The sequel to House of 1000 Corpses – the Firefly family are ambushed at their isolated home by Sheriff Wydell and a squad of armed men guns blazing – yet only Otis and his sister, Baby, manage to escape the barrage of bullets unharmed. Hiding out in a backwater motel, the wanted siblings wait to rendezvous with their errant father, Captain Spaulding, killing whoever happens to stand in their way.','Death walks behind. Hell waits ahead.',0,0,16.754452,6.6,322,107,'2005-07-22','en','/iLO3KcszEyJv6gbS6dkHZrmdGet.jpg',3.1714758086926484,3,'2026-09-10',2,NULL,NULL),(1698,'解剖','Anatomie','奋发向上的医学院学生宝拉（FrankaPotente），好不容易获准进入颇负盛名的海德堡研究机构，她希望能继承祖父的衣钵，成为一名出色的医生。在上解剖课时，她发现解剖台上的尸体竟是她认识的人，便积极暗中调查尸体的来源，发现有一个以残酷手法研究活人的神秘社团在学校活动，而班上的同学也一一离奇失踪，她决定继续挖掘真相。','Some study. Some are studied.',0,0,5.025938,6.1,61,103,'2000-02-03','de','/oCGsfTIu5r7ZG1WUq5VGbmLXjhP.jpg',2.741166193142243,3,'2026-09-10',2,NULL,NULL),(1701,'空中监狱','Con Air','空中监狱是美国运送最凶狠、最危险的罪犯的专用装甲飞机，配备了全副武装的警卫以及手脚镣铐，飞行目的地是绝密的，连囚犯都不知道。没人逃出过这个空中堡垒，这次却出了差错。在这部火爆的动作片中，一群暴力的末路罪犯劫持了一架飞机，将警卫作为人质，准备逃离境外。服完刑后打算回家团圆的坡也搭乘这架飞机。面对劫机者他奋起抵抗，避免灾难的发生。在一番惊心动魄的搏斗之后，飞机安全降落在洛杉矶，罪犯们也得到了应得的惩罚。','They were deadly on the ground; Now they have wings',75000000,224012234,45.154631,6.5,1270,115,'1997-06-01','en','/x4sPfL7dUgCULZvuTySZ1V5wNpQ.jpg',3.562853371928476,3,'2026-09-10',2,NULL,NULL),(1705,'决战猩球','Battle for the Planet of the Apes','2678年，猿族教授在讲述凯撒当年的故事，那是在2015年，猿族中发生叛乱，大猩猩们在将军艾多的带领下和一群发生变异的人类一同意图推翻凯撒的领导，决战开始了……','The final chapter in the incredible Apes saga. The most suspenseful showdown ever filmed as two civilizations battle for the right to inherit what\'s left of the earth!',1700000,8844595,13.315383,5.5,215,93,'1973-06-15','en','/e6PoyXDy9UnD0hX5Bjc5DoyLy9X.jpg',2.9895417264304127,3,'2026-09-10',2,NULL,NULL),(1710,'凶手就在门外','Copycat','犯罪心理学家海伦.赫德森干得太出色了：在别人看来毫无线索的情况下她能分析出杀人凶手的活动规律、作案手法甚至下一个目标。所以她才被惊扰全城的连环杀手忌恨，险遭杀害。现在她已足不出户，终日与电脑为伴。而一心想破这个连环凶杀案的女警探在无计可施的情况下来找海伦相助，并最终说服她出山。海伦做了大量分析工作后发现，凶手是在模仿古今中外着名的杀人事件，这次要想准确推断出谁是下一个目标真是难上加难，因为这样的事件真是浩如烟海，从中找出必然的联系几乎可以说是不可能的。当海伦借助电脑，从作案细节上有所发现时，凶手已经站到了他们门外。','One man is copying the most notorious killers in history one at a time. Together, two women must stop him from killing again. Or they\'re next.',0,0,14.211699,6.4,194,124,'1995-10-27','en','/oMgwJb016znNZcpDR20eXxZoW8A.jpg',3.029394777462113,3,'2026-09-10',2,NULL,NULL),(1717,'国王班底','All the King\'s Men','1949年奥斯卡最佳影片「一代奸雄」重拍，小说家罗柏华纳畅销巨作改编。描写美国一代南方政治家威力史塔克(西恩潘)纵横政坛，呼风唤雨的传奇事迹，从小小的南方议员到前进华盛顿特区的奋斗历程…  　　肖恩-潘领衔主演，裘德·洛、凯特-温斯莱特、詹姆斯·甘多费尼和安东尼·霍普金斯等联合主演，星光灿烂。肖恩-潘、裘德-洛、凯特-温斯莱特、安东尼-霍普金斯、帕特丽夏-克拉克森……光是这个明星班底，也足有国王气派了。本片改编自罗伯特-佩恩-沃伦小说，讲述了一个国王的政治手腕。肖恩-潘本次出任第一男主角，他曾因《神秘河》而获得奥斯卡影帝殊荣，不知这次在众实力明星的光芒比拼中，究竟谁能称王。有环环相扣的曲折情节，明星们的演技才有发挥的空间，《国王班底》会不会成为明年奥斯卡的扛鼎之作，我们拭目以待。','Some people will do anything to gain power. Some will do anything to keep it.',55000000,9450897,7.768223,5.7,95,125,'2006-09-10','en','/r3Yu6JdufxUSqy6PJgT887UpSMt.jpg',2.8283812521510914,3,'2026-09-10',2,NULL,NULL),(1722,'战地情人','Captain Corelli\'s Mandolin','这部发生在二战硝烟战火中感人至深的爱情故事《战地情人》，改编自英国著名作家路易斯·德·伯尔涅斯的畅销小说《柯莱利上尉的曼陀林》。女主角佩内洛普·克鲁兹凭借此片荣获2001年第14届欧洲电影奖“观众-最佳女演员”提名。希腊小岛塞佛伦尼亚岛，纯美恬静，仿若世外桃源。岛民世代居住生活在这里，与世无争。然而二战烽烟很快打破了这份宁静祥和。意大利军团上尉安东尼奥·柯莱利（尼古拉斯·凯奇饰）带领士兵驻扎进小岛，双方都保持着敌对的距离。跟随柯莱利的唯有一把排遣孤寂的曼陀林琴。一次偶然的机会，柯莱利邂逅当地姑娘佩拉吉娅（佩内洛普·克鲁兹饰）。两人在最初的相处中格格不入，但佩拉吉娅优雅的举止与坚韧的性格很快打动了柯莱利的心，柯莱利天籁般的琴声也令佩拉吉娅神往不已。然而美好的时光总是如此短暂，随着战事的日益临近，坠入爱河的两人不得不做出最后的抉择……',NULL,57000000,62112895,9.061866,5.5,145,131,'2001-08-17','en','/zjKyfNSFMw5lWdrYYQZzgVrnix1.jpg',2.9061478009861332,3,'2026-09-10',2,NULL,NULL),(1724,'无敌浩克','The Incredible Hulk','科学家布鲁斯·班纳因一次伽马实验发生变异，每当情绪失控时，便会化身为拥有惊人力量的绿色巨人浩克。为了摆脱这种无法控制的力量，也为了躲避罗斯将军率领的美军追捕，班纳隐姓埋名生活在巴西，并秘密寻找让自己恢复正常的方法。然而一次意外暴露了他的行踪，军方随即派出精锐部队展开追捕。被迫重新踏上逃亡之路的班纳回到美国，并再次遇见昔日恋人贝蒂·罗斯。与此同时，为了获得足以对抗浩克的力量，军方也开始进行更加危险的尝试，一场远超班纳预料的危机逐渐逼近……','You\'ll like him when he\'s angry.',150000000,163712074,62.898336,6.1,3021,114,'2008-06-12','en','/gKzYx79y0AQTL4UAk1cBQJ3nvrm.jpg',3.7145542395239426,3,'2026-09-10',2,NULL,NULL),(1725,'西区故事','West Side Story','两位来自纽约对立帮派的年轻人坠入爱河，但他们各自友伴间的紧张关系最终酿成悲剧。','The screen achieves one of the great entertainments in the history of motion pictures',6000000,43656822,23.431117,7,389,152,'1961-10-18','en','/nzCMu6D5q60i2bVrIQ0DxlRSgCZ.jpg',3.2755116795892723,3,'2026-09-10',2,NULL,NULL),(1726,'钢铁侠','Iron Man','斯塔克工业是美国军方的重要武器供应商，掌门人托尼·斯塔克天资聪颖，却也过着放纵不羁的富豪生活，在助手维吉尼亚·波茨和公司元老俄巴迪亚·斯坦的协助下经营着庞大的军火事业。一次前往中东展示新型武器时，托尼遭到武装分子袭击并被俘，体内残留的弹片随时可能危及心脏。在英森博士的帮助下，他利用微型电弧反应炉维持胸前的电磁装置，并暗中制造出一套钢铁盔甲逃离囚禁。回到美国后，托尼重新审视自己的事业，并不断改进这套战甲，却也逐渐发现斯塔克工业背后隐藏着更危险的秘密……','Heroes aren\'t born. They\'re built.',140000000,585174222,120.725053,7.4,8776,126,'2008-04-30','en','/78lPtwv72eTNqFW9COBYI0dWDJa.jpg',4.43783266865347,3,'2026-09-10',2,NULL,NULL),(1729,'功夫之王','The Forbidden Kingdom','杰森（迈克尔·安格拉诺饰）是一个疯狂迷恋港台功夫片的美国少年，然而现实中的他却饱受坏孩子的欺负，不敢反抗。一次偶然的机会，他从某中国古董店得到一根如意金箍棒，借着金箍棒的力量，他竟然回到了几千年前的中国。此时，邪恶的玉疆战神（邹兆龙饰）凭借降伏齐天大圣孙悟空的威名篡夺天界，靠武力鱼肉百姓，民不聊生。杰森先后邂逅了嗜酒的游侠鲁彦（成龙饰）、沉默寡言的默僧（李连杰饰）以及轻盈美丽的金燕子（刘亦菲饰）。他们为解救被困的齐天大圣朝着天界进发。','The battle for eternity is the fantasy of a lifetime.',55000000,127906624,17.097041,6.3,461,104,'2008-04-18','en','/8r0xTpVuEAVS54wxXZzLyOonfw1.jpg',3.2269452293942473,3,'2026-09-10',2,NULL,NULL),(1734,'木乃伊2：木乃伊归来','The Mummy Returns','续集的故事背景安排在9年后，冒险家里克和他的图书馆情人艾弗琳已是一对恩爱夫妻，还有了个活泼可爱，同样富有冒险精神的儿子艾里克斯。全家赴埃及度假，无意中里克发现了一只古手镯，不料却因为这只手镯而遭到一伙盗墓人的追杀。大家千辛万苦回到伦敦，手镯竟在艾里克斯手腕上生了根，再也无法取下。原来这只手镯是召唤大魔头蝎子王的法器。这时一伙盗挖死亡之城的狂人已通过死亡之书将木乃伊与他的情人复活，只要再将蝎子王收编麾下，就可以达到他们统治世界的险恶目的。不过他们必须先把手镯弄到手，把大魔头蝎子王召唤回来才行，一场神鬼恶斗由此在伦敦上演……','The most powerful force on earth is about to be unleashed by the two people who should know better.',98000000,433013274,41.862983,6,2206,130,'2001-04-28','en','/gmKa9pDN2NDPrJinbMRdTQtHcl9.jpg',3.5759104517190186,3,'2026-09-10',2,NULL,NULL),(1735,'木乃伊3：龙帝之墓','The Mummy: Tomb of the Dragon Emperor','一名公元前50年的中国帝王，由于太过残暴受到女巫的诅咒，他和他的军队全部变成了兵马俑被封在地下宫殿中，等待着被人重新唤醒。1946年，里克·奥康纳和伊芙琳俩人已经隐退到英国牛津郡居住，他们在二战期间曾为英国政府担任间谍。平静的生活有些乏味，于是他们很高兴地接受了一个外国办事处提供的“最后的任务”——负责把一件从中国上海博物馆偷走的珍贵文物物归原主。与此同时，当年被诅咒的那个中国帝王被唤醒，一场惊心动魄的大战随即开始。','A New Evil Awakens.',145000000,401128639,60.034162,5.2,1387,112,'2008-07-01','en','/o9poTCI2Xu0aG5fZGnvCsDoEYF1.jpg',3.3625991980820227,3,'2026-09-10',2,NULL,NULL),(1770,'傲气盖天','Michael Collins','影片的剧本在1983年就完成了，导演努力了12年才将其搬上银幕。故事从1916年爱尔兰武装叛乱失败、反叛领袖被处决说起。作为叛军年轻指挥官的迈克尔.柯林斯也被关押。获释后，他与哈利.勃兰德一起再展反旗。这次，他们放弃大规模武装起义，而是开展游击战和暗杀行动。在一次行动时，柯林斯受伤，由凯蒂进行护理，并逐渐建立起恋情。后来，柯林斯被迫放弃暗杀行动，进行大规模作战，爱尔兰共和军因此受到重创。柯林斯在充当停火协议的主要谈判者期间惨遭暗杀。','Ireland, 1916. His Dreams Inspired Hope. His Words Ignited Passion. His Courage Forged A Nation\'s Destiny.',28000000,16900000,8.314624,6.7,97,132,'1996-10-25','en','/brIBbU6t9glEGAKRTJ4PMj9OiDC.jpg',2.869095777314164,3,'2026-09-10',2,NULL,NULL),(1771,'美国队长','Captain America: The First Avenger','Predominantly set during World War II, Steve Rogers is a sickly man from Brooklyn who\'s transformed into super-soldier Captain America to aid in the war effort. Rogers must stop the Red Skull – Adolf Hitler\'s ruthless head of weaponry, and the leader of an organization that intends to use a mysterious device of untold powers for world domination.','When patriots become heroes',140000000,370569774,74.506246,6.6,7047,124,'2011-07-22','en','/vSNxAJTlD0r02V9sPYpOjqDZXUK.jpg',4.060521681313941,3,'2026-09-10',2,NULL,NULL),(1777,'华氏911','Fahrenheit 9/11','一部记述伊拉克战争前后美国情势的纪录片。美国因何成为恐怖分子的袭击目标？为何乐于卷入战争？乔治布什的政策与9·11事件的爆发有何联系？而他和本·拉登之间关系怎样演变至宿敌？片中用真实的历史场景，从某个侧面提供了一种解读方式。除了关注美国国内，镜头也对准了伊拉克战场。厌倦了战争的美国士兵、被耻笑的伊拉克俘虏、饱受战乱之苦的当地人民，人人都在这场战争遭受着不同的痛苦和煎熬。美军家中的善良母亲，准备去前线服役的热血青年，都对布什的政策、对伊拉克战争，开始沉重的思考。','Controversy... what controversy?',6000000,119114517,16.20985,6.8,397,122,'2004-06-25','en','/aVOfSjEbWjqDnkoZGrYtHZPRDh4.jpg',3.243494484701173,3,'2026-09-10',2,NULL,NULL),(1779,'罗杰和我','Roger & Me','这部《罗杰和我》是Moore在89年拍的，那时候他老家密执安州的FLINT镇，因为通用汽车公司大幅裁员而全面衰败，他拍这个片子不是为了拯救他们镇，而是拿来质问大企业，用事实撕开他们的正人君子的假象。罗杰是Roger Smith，当时通用汽车的大头头。',NULL,160000,6706368,3.284903,7.4,90,91,'1989-09-01','en','/vSi4YK4E63geptUAxtizRUeTCFu.jpg',2.8632774815018855,3,'2026-09-10',2,NULL,NULL),(1781,'难以忽视的真相','An Inconvenient Truth','他是几乎成为美国总统的人——阿尔·戈尔。很难说他成为总统会给世界带来怎样的改变，但是现在，他就在改变世界的路上。  　　本片记录了戈尔作为一个环保专家，一个世界公民，为了环保世界进行的种种努力。他精彩的演说，议会上咄咄逼人的质询，对于环保议程的推进努力，还有在这一切的背后，他的内心世界。','By far the most terrifying film you will ever see.',1000000,46243000,14.139004,6.7,251,100,'2006-01-24','en','/68IgvTfIBIsr5ScvQ2KUCok9LQ8.jpg',3.1119384590666295,3,'2026-09-10',2,NULL,NULL),(1788,'浑身是劲','Footloose','伦·迈克马科从大城市芝加哥搬到了南部的小城贝农居住，在这里，他体会到了严重而激烈的文化冲突。在这个小镇子里，吵闹的摇滚乐和酒精与跳舞的派对是禁止的。原因是几年前，在当地发生了一件骇人听闻的大事件。五个十几岁的少年，因为晚上出去游玩，遭遇了车祸，全部遇难。所以贝农当地的议 员、牧师和德高望重的名流共同起草了一个法案，禁止年轻人晚上出去聚会，禁止摇滚乐等等。  没有人敢于尝试明目张胆地打破禁区，但是来自大城市的伦偏偏要做第一个吃螃蟹的人。在和这种老旧的体制做斗争的时候，伦还和当地牧师的问题不断的女儿艾瑞尔坠入了爱河……',NULL,8200000,80035402,25.03414,6.4,505,107,'1984-02-17','en','/9JEDjBCXCx3eKTSkXwispf0UN3O.jpg',3.278340386153288,3,'2026-09-10',2,NULL,NULL),(1792,'贴身兄弟','Stuck on You','鲍勃（马特·达蒙 Matt Damon 饰）和华特（格雷戈·金尼尔 Greg Kinnear）这一对双胞胎兄弟从小就备受关注，因为打娘胎里出来的那一刻起，他们相互联结的手臂就注定了他们不平凡的人生。幸运的是，童年时代的两兄弟并没有因为身体上的异常而受到他人的歧视，恰恰相反，利用身体构造上的特点，两人在体育场上大放异彩。随着毕业的临近，鲍勃和华特的学生时代即将抵达终点。在华特的极力劝说下，鲍勃终于答应同他一起前往好莱坞发展。在灯红酒绿的好莱坞，两人一炮而红，而正是随之而来的金钱和名誉成为了兄弟二人分家的导火索。华特恋上了名叫艾普丽（伊娃·门德斯 Eva Mendes 饰）的漂亮姑娘，这一事件让从小到大都未曾分开过的兄弟两人开始认真的考虑起了各自的未来。','Whatever happens to the boys, one thing is certain. Nothing will ever come between them.',55000000,33828318,8.802525,5.1,188,118,'2003-12-10','en','/5TmPGPsOP4EgMo8X14pyywxB1j2.jpg',2.929800917113062,3,'2026-09-10',2,NULL,NULL),(1808,'天鹅绒金矿','Velvet Goldmine','摇滚史上最华丽的70年代，性感、妖艳、前卫、激进等各种大胆元素被融合成独特的摇滚流派。这场摇滚革命的代言人布莱德·斯莱德（乔纳森·莱斯·梅耶斯 Jonathan Rhys Meyers 饰）彼时倾倒众生。然而，1984年，他在一次演出中遭遇“暗杀”，巨星自此陨落。伦敦先 驱报 记者阿瑟（克里斯蒂安·贝尔 Christian Bale 饰）对自己的偶像展开调查。在回溯逝去岁月之中，却挖掘出布莱德与美国摇滚歌手库尔特·怀尔德（伊万·麦克格雷格 Ewan McGregor 饰）的一段冰火之恋。布莱德受库尔特音乐的感染，创造出自己的华丽风格，迅速走红。两人相互激发灵感、彼此迷恋，最终却因为性格冲突而决裂。风头正劲的布莱德在失去库尔特之后也开始自暴自弃，导演出一场“暗杀”剧……。阿瑟在酒吧邂逅消沉的库尔特，他仿佛被布莱德灵魂附体，他们共同沉浸在对布莱德的怀念中难以自拔，同时一种奇妙的情感在他们之间诞生。\r 　　本片获得第71届奥斯卡金像奖最佳服装设计提名、第51届戛纳电影节最佳艺术贡献奖及金棕榈奖提名。','Style matters. Even when it comes to murder.',0,1053788,10.932711,6.9,116,119,'1998-10-23','en','/4EJkObEJFvXCuoVqOP7XBXGqdQ1.jpg',2.9252971608032934,3,'2026-09-10',2,NULL,NULL),(1809,'诱惑法则','The Rules of Attraction','影片改编自布莱特·伊斯顿·埃利斯的同名小说，故事发生在80年代新英格兰州的一所富裕的文科大学（康顿大学）中。在三个年轻人之间出现了一种三角性关系，他们是兼职买卖毒品的肖恩·贝特曼（詹姆士·范德比克饰），双性恋的保罗·欧文（伊恩·索莫赫德饰）还有保罗的前女友劳伦（夏妮·索塞蒙饰）。肖恩·贝特曼是个不折不扣的无政府主义者，他对自己的性取向并不十分明确。有一天，他发现自己成了双性恋者保罗·欧文的猎取目标，接着又成了保罗的前女友劳伦的梦中情人。虽然在这场三人游戏中，每个人都不时的有些疑惑和悔恨，但是他们还是在周旋在不同的床第间享受着爱情与性带来的欢愉。','We all run on instinct',4000000,0,11.387335,6.3,168,110,'2002-10-11','en','/6OybelUmwUkDm7fbX1BI7OhpYeQ.jpg',2.9842723937019273,3,'2026-09-10',2,NULL,NULL),(1813,'魔鬼代言人','The Devil\'s Advocate','凯文（基努·里维斯Keanu Reeves 饰）是个保持不败记录的年轻律师，一个又一个案子在他的辩护下得以胜诉。但与此同时，他也逐渐地意识到自己为之洗脱罪名的客户并非清白。同时有娇妻玛丽相伴，事业有为的他宛如生活在天堂一般。受到纽约著名事务所的邀请，他携妻子来到纽约。奢华的生活近在眼前，一切似乎都昭示着明天的坦途与光明。老板米尔顿（艾尔·帕西诺Al Pacino饰）对凯文非常赏识，不断地委以重任，同时也带他见识了五光十色的世界。面临着工作的压力和色情，名利各个方面的诱惑，凯文渐渐的迷失在生活中，和玛丽住着豪宅，手上有花不完的钞票，甚至忽视了妻子精神上的反常。但是，玛丽却渐渐地感到与凯文疏远了，而且生活的并不幸福。玛丽总是能看到诡异的情景，而且整个人的精神都彻底崩溃了。在强大的压力下，玛丽选择了自杀。直到失常的妻子自刎在他的臂弯中，凯文才猛然意识到身边的危机。凯文愤怒地去找米尔顿，指责米尔顿给他设下陷阱。同时，凯文从母亲那里得到了一个惊人的秘密，原来凯文任职的那家律师行的老板米尔顿，就是自己的父亲。气愤的凯文去找米尔顿报仇。当他开枪射向米尔顿的时候，米尔顿却毫发无损。原来米尔顿就是撒旦，他要让整个世界变为已有。米尔顿还有个女儿克丽丝塔，她是罗麦斯同父异母的孩子。然而，究竟是魔鬼的诱惑还是内心的虚荣将凯文引向今日的迷雾与深渊？自由意志下凯文又会做出怎样的抉择？','Evil has its winning ways.',57000000,152944660,33.8473,7.2,1374,144,'1997-10-17','en','/5ZzBGpxy55OQzHxKVY11IpY6a0o.jpg',3.6934404203982187,3,'2026-09-10',2,NULL,NULL),(1817,'狙击电话亭','Phone Booth','广告推销员斯图（柯林•法瑞尔 Colin Farrell 饰）在外面瞒着妻子有一个秘密情人，为了躲避妻子的电话单检查，这天他又偷偷溜到街上公用电话亭准备打电话约会情人。不料，在他进入电话亭的一刹那，电话铃响了。虽然不知是谁打的电话，出于习惯，斯图拿起了听筒。\r 一把阴沉单调的男声随即响起，警告斯图不要挂掉，否则将血渐街头！斯图当然没有理会这恶作剧般的警告，马上挂了电话。这时，一声枪响，一名路人已经倒在地上。斯图吓得魂飞魄散，动也不敢动。\r 警察闻讯而来，然而他们对斯图的解释怎么也不相信，斯图还成了枪击案的主要嫌疑人。一时间，全城轰动，斯图的妻子和情人都闻讯赶来了……','No options. No lies. No fear. No deals. Just keep talking.',13000000,97837138,38.018085,6.7,1062,81,'2002-09-09','en','/Ar8RjaJvlg3Bup2R8gofN3l54Sh.jpg',3.53841389553644,3,'2026-09-10',2,NULL,NULL),(1819,'同居三人行','You, Me and Dupree','卡尔（马特·狄龙 Matt Dillon饰）和莫利（凯特·哈德森 Kate Hudson饰）的新婚生活眼看就要甜甜蜜蜜的铺开，此时却来了个不速之客：卡尔的老友杜普瑞（欧文·威尔逊 Owen Wilson饰）。这个家伙行为怪异，思想奇特，有自己一套慵懒散漫的生活方式。如今他倒了大霉，被公司解雇，随后无家可归，好心的卡尔收留他住下，并不介意杜普瑞给自己新婚生活带来的麻烦。杜普瑞的生活上的种种疯狂行径却已经让莫利忍无可忍，那些近乎荒唐的生活闹剧严重地影响了夫妻两人原本平静的生活。然而出人意料的是，杜普瑞跟街坊们打成一片，个个都受到他性格的感染。与之相反的是，卡尔的工作非常忙碌，分给家庭的时间日渐减少。于是杜普瑞更像是这里的男主人。不止邻居，就连莫利，也渐渐喜爱上这个电灯泡。这个三人同居的困境，到了非解决不可的地步','Two\'s company. Dupree\'s a crowd.',54000000,130431368,18.600367,5.4,407,108,'2006-07-14','en','/2VvjXd5g4T0tAl8UQvsyWmLzZb1.jpg',3.104968131413166,3,'2026-09-10',2,NULL,NULL),(1824,'50 First Dates','50 First Dates','Henry is a player skilled at seducing women. But when this veterinarian meets Lucy, a girl with a quirky problem when it comes to total recall, he realizes it\'s possible to fall in love all over again…and again, and again. That\'s because the delightful Lucy has no short-term memory, so Henry must woo her day after day until he finally sweeps her off her feet.','Imagine having to win over the girl of your dreams... every friggin\' day.',75000000,196482882,61.437586,6.6,2105,99,'2004-02-13','en','/lzUI2Cg7OMfcUNv3f7MywYNBjs6.jpg',3.7444744711327087,3,'2026-09-10',2,NULL,NULL),(1830,'战争之王','Lord of War','根据真实故事改编，一部关于战争、金钱和个人良知的动作大片。主人公自欺欺人的相信：军火和其他商品没有什么区别，而忽略了军火背后战争的原罪性，因而最终家破人亡，备受良心的折磨。主人公尤瑞在少年时跟随家人从欧洲移居美国。18岁那年，他加入联合国维和部队，作为一名翻译被派往非洲。由于厌恶战争，他对自己所从事的工作毫无兴趣。一个偶然的机会，他把枪支转手倒卖给民间武装军队。并在此期间，遇到了一见钟情的女人—埃娃。回到美国后，尤瑞劝说弟弟维塔利加入了他的军火生意，两人开始靠倒卖地下军火赚钱。但是两大威胁像幽灵一样困扰着尤瑞：他生意上的死对头和杰克—一个对他紧追不放的国际警察……','Where there\'s a will, there\'s a weapon',42000000,24127895,34.828241,7,1335,122,'2005-09-16','en','/s9G6AFTi6tzzpzekijKECUB1ayW.jpg',3.648477876891977,3,'2026-09-10',2,NULL,NULL),(1831,'下一件好事','The Next Best Thing','阿比是一名瑜珈辅导员，她刚刚经历过和男朋友痛苦的分手。此时，她多想有一个人来和她分担她的空虚甚至生一个孩子。阿比有个最好的朋友叫罗伯特，他是一个同性恋建筑设计师，在自己的“爱情”方面也一直没有什么起色。当阿比找到了罗伯特时，两个孤独的心灵依偎到了一起，彼此填充着各自的空虚。 一个亲密朋友的死成为了他们友情进一步发展的催化剂。在一个鸡尾酒餐的下午，两个深陷悲哀中的生命终于碰撞出了激情。尽管这之后他们彼此都在回避对方，而阿比却发现自己怀孕了。\r 　　两个人不得不对这件事情进行了协商，他们作出了一个惊人的决定——生下这个孩子。而他们也开始充当起这个孩子父母的角色。尽管这遭到了他们朋友的强烈反对，但他们决心做下去。但随着故事的进展，阿比和罗伯特的儿子山姆已经成长成为了一个漂亮、自信的六岁男孩，他的父母也在幽默和轻松的气氛中竭力保持着自己的“父母身份”，然而，这一天，这种情况终于发生了改变，一名因商务旅行从纽约来到洛山矶的银行投资家本·库伯走进了阿比的瑜珈教室，他和她一见钟情……\r 　　“美满”的三口之家正将面临终结，而罗伯特却发现自己的人生已经和6年前有所不同，阿比和罗伯特的“临时爱情故事”将会如何结局呢？','Best Friends Make The Best Mistakes',25000000,24362772,3.707511,4.3,29,108,'2000-03-03','en','/iYK1ZUtY4etcn91glUmrGuZRH6M.jpg',2.559991712269691,3,'2026-09-10',2,NULL,NULL),(1832,'怒犯天条','Dogma','枢密主教为改善天主教予人的刻板印象，锐意改革，宣称在百年庆典时走进新泽西教堂大门即得豁免所有罪行。遭贬斥的死亡天使卢克（Matt Damon 饰）与守护天使巴特比（Ben Affleck 饰）认为可借此机会返回天堂。遂前往新泽西，沿路惩罚人类罪行大开杀戒。与此同时，天使长曼德川下界找到耶稣后人——堕胎医生贝瑟尼（Linda Fiorentino 饰），授意她阻止两名天使进入教堂，因为天使的行为会使上帝旨意自相矛盾引发世界毁灭。贝瑟尼在两名好色先知、黑人门徒以及缪斯（Salma Hayek 饰）的陪同下踏上拯救世界之旅。而地狱方面，恶魔艾兹瑞携三名仆从、屎魔等沿途设障，并控制上帝肉身以毁灭世界。一场决定世界命运的三界之战，在新泽西拉开了荒诞疯狂的帷幕……','It can be Hell getting into Heaven',10000000,30652890,14.543435,6.8,823,130,'1999-11-12','en','/hU6Fcn2dKZzYZFtQUEL5MT5anSS.jpg',3.434360008461556,3,'2026-09-10',2,NULL,NULL),(1833,'吉屋出租','Rent','一栋老旧楼房顶层的简陋公寓中，住着两个为了艺术而挣扎的室友：罗杰(Adam Pascal 亚当•帕斯考 饰)和马克（Anthony Rapp 安东尼•雷普 饰）。马克最近失恋了，他的女友莫琳因为喜欢同性的乔安妮而抛弃了他。\r 　　马克之前的另一位室友汤姆(Jesse L. Martin 杰西•L•马丁 饰)――一个电脑奇才，也是艾滋病毒的携带者，不幸路遇抢劫，遍体鳞伤之时被同性恋街头鼓手安琪(Wilson Jermaine Heredia 威尔森•杰梅因•贺雷迪亚 饰)接回了这栋公寓，他们很快走到了一起。\r 　　罗杰认识了前来借用火柴的邻居咪咪(罗萨里奥•道森 Rosario Dawson 饰)，咪咪是个脱衣舞女。不久，罗杰就发现咪咪跟自己有着相同的秘密和疾病――艾滋病，二人同病相爱。\r 　　三对有情人由于没钱交房租，即将度过一个没有暖气、没有电力，只靠蜡烛取暖的圣诞夜。','No day but today.',40000000,31670620,10.433667,6.7,155,135,'2005-11-23','en','/5IzB3J6uXWoRUTYpR1nR73SPodV.jpg',2.9850950405186967,3,'2026-09-10',2,NULL,NULL),(1844,'偷天陷阱','Entrapment','一个著名画家在纽约举办了一次画展，不料展出的名画却被盗走，众人怀疑的矛头指向了大盗麦克（肖恩•康纳利 Sean Connery 饰）。因为麦克是一个名贵艺术品的惯偷分子，而这次名画失窃的所有证据，也表明麦克嫌疑最大。\r 为了使其入罪，承包此画的保险公司决定使用美人计——职员维吉尼亚（凯瑟琳•泽塔-琼斯 Catherine Zeta-Jones 饰）假扮麦克的同道中人，诱使麦克出手犯罪，而保险公司则随后追踪取证。然而，每一次麦克都没有落入圈套，还与维吉尼亚渐生情愫。得知千年虫入侵电脑，维吉尼亚唆使麦克利用这个机会入侵马来西亚的国际银行，这里管理森严，号称全球之最。一场斗智斗勇的计划开始了，而维吉尼亚也陷入了效忠公司和帮助爱人的选择当中。','The trap is set.',66000000,212404396,25.877794,6,602,112,'1999-04-29','en','/f1guOvTOYhvU5ezbXTyDYWVv4BI.jpg',3.2677649872187335,3,'2026-09-10',2,NULL,NULL),(1850,'月亮上的男人','Man on the Moon','这部传记电影的一开场，主人公安迪·考夫曼（金·凯瑞 Jim Carrey 饰）却向观众开了一个谢幕的玩笑。安迪自幼喜爱表演，成年后顺理成章成为饭店驻场演员，但事业并不顺利，一次他模仿猫王的表演引起好莱坞经纪人乔治注意，后者将他引荐到电视界。上镜前安迪从东方修行课上得到幽默的秘诀：沉默。安迪凭独特的表演风格得到观众青睐，进入了他颇为鄙视的情景喜剧领域。他创造出了一个不存在的人物托尼·克里夫，然后借克里夫的身份实现他和搭档的疯狂点子，和女人们进行的摔跤比赛更把他的疯狂推向了巅峰，安迪不断的戏弄、激怒观众，直至他患上癌症却没人相信，但安迪不在乎，因为生活本身就是一场无止尽的玩笑……本片获2000年柏林国际电影节最佳导演银熊奖，金球奖最佳男演员奖。','Hello, my name is Andy and this is my movie.',82000000,47434430,24.444186,6.9,435,118,'1999-12-22','en','/wR0f51hWzj1qHQn8sVkbAaz6yNx.jpg',3.2976813834111054,3,'2026-09-10',2,NULL,NULL),(1852,'世贸中心','World Trade Center','2001年9月11日，位于美国纽约的世贸双子大厦遭遇了史无前例的恐怖袭击。美国联合航空公司的两架航班猛然撞向两座高耸的大楼。爆炸、坍塌接踵而至，纽约市内所有的消防队员以及警察等都参与到这场惊天动地的大营救当中。让人意想不到的是，参与营救的人在如此严重且危机四伏的灾祸面前也时常变成了被救者。许多救险队员都被困在了轰然而降的废墟中。其中就包括纽约市港务局的两位警官约翰·迈克劳林(尼古拉斯·凯奇)和威廉·吉梅诺(迈克尔·佩纳)。身处险境的两人牵动了许许多多的关注，特别是他们的家人，当然还有其他身处安全境地的救援人员。一方面，是家人和抢救人员通力合作，在积极寻求有效的营救方案，早日救出两位警员；另一方面，被困废墟内的两人，身处在氧气渐渐稀薄的绝境，想尽一切办法并凭着自己的坚强毅力和不懈的努力，寻找着可能还生的一线希望。然而，所有的恐惧、彷徨、伤心、绝望无不从四面八方甚至从地狱中缓缓袭来。营救与自救在这惊心动魄且颇显漫长的24小时内同时展开了。废墟内两个旺盛的生命在备受煎熬……','The world saw evil that day. Two men saw something else.',63000000,162945894,24.697533,5.9,447,128,'2006-08-09','en','/uLL4KbLD1sY14el7kTzoiCRR6HM.jpg',3.1915798541703633,3,'2026-09-10',2,NULL,NULL),(1858,'Transformers','Transformers','Young teenager, Sam Witwicky becomes involved in the ancient struggle between two extraterrestrial factions of transforming robots – the heroic Autobots and the evil Decepticons. Sam holds the clue to unimaginable power and the Decepticons will stop at nothing to retrieve it.','Their war. Our world.',150000000,709709780,25.468493,6.6,4040,144,'2007-06-27','en','/lkZ9gqCEjzX85lKR6Jjd1uGAXNp.jpg',3.8190831203079387,3,'2026-09-10',2,NULL,NULL),(1865,'加勒比海盗4：惊涛怪浪','Pirates of the Caribbean: On Stranger Tides','杰克船长邂逅老情人，她究竟是为爱而来，还是只想利用他找到传说中的“不老泉”。','Live Forever Or Die Trying.',380000000,1045713802,135.413856,6.4,4948,136,'2011-05-14','en','/keGfSvCmYj7CvdRx36OdVrAEibE.jpg',4.065506708532328,3,'2026-09-10',2,NULL,NULL),(1874,'再见巴法纳','Goodbye Bafana','\"故事发生在1968年的南非，严格残酷的种族隔离制度让在那里生活着的两千五百万黑人面临着悲惨的命运。为了维护种族的权利，一部分黑人们奋起反抗，但等待着他们的结局不是驱逐出境就是被关押在罗宾岛监狱之中。\r 詹姆斯（约瑟夫·费因斯 Joseph Fiennes 饰）就出生在这样恶劣的局势之中，幸运的是，他是一位不折不扣的白人。从小大人们就向詹姆斯灌输着“黑人低人一等”的荒谬概念，成年之后，已然完全被洗脑的詹姆斯成为了罗宾岛监狱的一名看守，而他所看管的囚犯正是南非的民主斗士曼德拉（丹尼斯·海斯伯特 Dennis Haysbert 饰）。随着时间的推移，对黑人们越来越了解的詹姆斯开始对自己的所作所为产生了质疑——难道白人就真的可以这样理所当然的囚禁和侮辱自己的同胞吗？\"',NULL,30000000,0,12.257654,7,38,140,'2007-02-11','en','/omL85DnSNaZLLnF0KzqSZihuWAr.jpg',2.67051278465417,3,'2026-09-10',2,NULL,NULL),(1878,'恐惧拉斯维加斯','Fear and Loathing in Las Vegas','来自南太平洋萨摩亚群岛的体育记者杜克（约翰尼·德普 Johnny Depp 饰）和他的律师朋友刚佐博士（本尼西奥·德·托尔 Benicio Del Tore 饰）一起开车前往拉斯维加斯，寻找他们的“美国梦”。一路上，他们带了大量毒品和酒精，也遇到形形色色的人，药物作用下，许多迷乱和癫狂的画面出现，让他们分不清幻觉和现实，到底哪个更残破，哪个更肮脏扭曲。两个人的混沌，加上拉斯维加斯本身的纸醉金迷，“美国梦”似乎遥不可及，两个人留下垃圾场一样的五星级酒店房间，无法停止迷幻的路途……','Buy the ticket, take the ride.',18500000,10680275,44.511363,7.2,1301,118,'1998-05-22','en','/tisNLcMkxryU2zxhi0PiyDFqhm0.jpg',3.701887801588213,3,'2026-09-10',2,NULL,NULL),(1880,'天狐入侵','Red Dawn','20世纪80年代中期， 苏联和古巴军队从空中着陆在科罗拉多高中的足球场。 在几秒钟内，伞兵袭击了学校，将一群青少年派到山上。 武器只有猎枪，手枪和弓箭，十几岁的孩子在寒冬努力生存。',NULL,4200000,38376497,11.743085,6.4,215,114,'1984-08-10','en','/a2GkHcioc2QEFJbQk1NTB85u3vD.jpg',3.0474810609957164,3,'2026-09-10',2,NULL,NULL),(1883,'黑潮','Malcolm X','迈尔肯（丹泽尔•华盛顿 Denzel Washington 饰）出生于一个黑白通婚的家庭，其父是黑人牧师，其母是无偏见的白人。但是当时，美国种族矛盾激化，3K党经常骚扰他家，在他的幼小心灵中种下了复仇的种子。迈尔肯长大后，混迹于街巷酒吧之中，甚至染上了毒品、偷盗等恶习。一次偶然的机会，迈尔肯与白人女子索菲亚相遇，但这段爱情因种族偏见而夭折。迈尔肯因犯罪锒铛入狱，正当他处于困境之时，一位黑人教徒引领他皈依了伊斯兰教，这也成为他人生的转捩点。他通过阅读大量书籍，逐渐了解了种族歧视的文化根源，并多次在公开场合宣扬黑人要独立、对白人复仇的激进主张，引起轩然大波。迈尔肯成为很多人的眼中钉，甚至遭遇了背叛，引来了灭顶之灾……',NULL,34000000,48169908,19.822791,7.2,370,202,'1992-11-18','en','/o2s9ow0uRRm1BcF3teznk5twd90.jpg',3.273633036208085,3,'2026-09-10',2,NULL,NULL),(1885,'龙威小子','The Karate Kid','新泽西少年丹尼尔（Ralph Macchio 饰）随母亲一起搬到了加利福尼亚的公寓中，母亲面对新生活踌躇满志，少年天性的丹尼尔也很快爱上了加利福尼亚温暖的沙滩，在那里，丹尼尔遇到了金发小美女艾丽（伊丽莎白·苏 Elisabeth Shue 饰）。想要接近艾丽的丹尼尔被姑娘的前男友强尼用空手道狠狠的教训，同样对空手道颇有兴趣的丹尼尔自尊受伤，但是仍未放弃和艾丽的交往，这激起了强尼和一干朋友们对丹尼尔长期的欺侮。万圣节舞会之夜，丹尼尔再次被强尼等人追打，丹尼尔居住的公寓中的维修工宫城（森田则之 Pat Morita 饰）先生及时出现，用空手道击退了强尼。宫城决定用两个月时间训练丹尼尔，令他可以击败强尼并领悟空手道的真谛……','Only the \'Old One\' could teach him the secrets of the masters.',8000000,90815558,28.456572,6.9,891,126,'1984-06-22','en','/1mp4ViklKvA0WXXsNvNx0RBuiit.jpg',3.503930609099258,3,'2026-09-10',2,NULL,NULL),(1887,'绝代艳后','Marie Antoinette','这部电影讲述了一位法兰西王后的一生，讲述了那个年代，法国大革命前贵族们奢华迷乱的生活。奥地利公主玛丽（克尔斯滕·邓斯特 Kirsten Dunst饰）非常聪明，生性活泼，14岁的时候，在一场政治婚姻中，从奥地利公主变成法国的太子妃。由于某些原因，王子对玛丽非常的纵容，婚后，玛丽一直过着极其奢华的生活，同样，玛丽也一直无法与内心的寂寞彻底脱离。这部电影将给我们带来关于18世纪法国宫廷和社会的各种震撼，匪夷所思的奢侈，欲望交织的爱情，以及最后法国人民的怒吼。','Rumor. Scandal. Fame. Revolution.',40000000,60474340,22.364549,6.5,642,123,'2006-05-24','en','/cGiqOwXguegR7jKJiflEStq7PUs.jpg',3.3434169005933168,3,'2026-09-10',2,NULL,NULL),(1891,'星球大战5：帝国反击战','The Empire Strikes Back','星球大战事件三年后，帝国军队继续追捕义军。义军在霍斯冰原星球战败后，卢克前往达戈巴星球，跟随自共和国覆灭后隐居的绝地大师尤达进行训练。为诱使卢克堕入黑暗面，达斯·维达将年轻的天行者引入贝斯平云城的陷阱。在与西斯尊主的激烈光剑对决中，卢克面对一个惊人的真相。[20世纪福克斯]','',18000000,538400000,15.7157,8.393,5879,124,'1980-05-20','en','/unc5VVWPNTJlZP9oGDgL1dCE1vL.jpg',4.363066466928697,3,'2026-09-10',2,NULL,NULL),(1892,'星球大战6：绝地归来','Return of the Jedi','银河帝国再度建造威力更强大、更坚不可破的“死星”，邪恶的势力又再一次威胁莱娅公主所领导的反抗军。莱娅公主等人前去援救被贾巴囚禁的索罗船长，却失败被贾巴捉住，最后在卢克·天行者的支持下，众人才成功逃出。卢克前往大师尤达的住所，即将离世的尤达告诉他一个令人震惊的事实：达斯·维德正是他的父亲！尽管如此，卢克仍重新加入反抗军的行列，并准备攻打帝国军新建的死星。此时，帝国皇帝达斯·西迪厄斯也正在新死星上，他设下了陷阱准备诱捕卢克。独闯虎穴的卢克无法抵御代表黑暗最高势力的西迪厄斯的西斯闪电，奄奄一息陷入绝境。身处一旁的达斯·维德眼见儿子即将死去，终于觉醒，为保护卢克而与皇帝同归于尽。安纳金·天行者终于恢复了善良的本性，在卢克“父亲！父亲！”呼唤声中，他释然地微笑着死去。','The Empire Falls...',32350000,572700000,46.509071,7.9,4665,135,'1983-05-23','en','/jQYlydvHm3kUix1f8prMucrplhm.jpg',4.2382873158311165,3,'2026-09-10',2,NULL,NULL),(1893,'星球大战1：幽灵的威胁','Star Wars: Episode I - The Phantom Menace','作为星球大战前传系列的首部曲，这部电影诞生了一个重要的人物：阿纳金（杰克·洛伊德 Jake Lloyd 饰）。银河国会会议上出现了利益争执，纳布星的女王阿米达拉（娜塔丽·波特曼 Natalie Portman 饰）被贸易联盟绑架并威胁签署新的贸易协议。绝地武士奎刚·金（连姆·尼森 Liam Neeson 饰）及徒弟欧比旺·肯诺比（伊万·麦克格雷格 Ewan McGregor 饰）受命前去解决纠纷，维护和平。他们的飞船在塔图因星意外降落的时候遇到了阿纳金并且带走了他。在奇异天才少年阿纳金等人的帮助下，奎刚及欧比旺与贸易联盟的机器人部队和西斯武士展开了决斗……','Every generation has a legend. Every journey has a first step. Every saga has a beginning.',115000000,924317558,54.035265,6.3,4432,136,'1999-05-19','en','/6wkfovpn7Eq8dYNKaG5PY3q2oq6.jpg',3.828840539664688,3,'2026-09-10',2,NULL,NULL),(1894,'Star Wars: Episode II - Attack of the Clones','Star Wars: Episode II - Attack of the Clones','Ten years after the invasion of Naboo, the galaxy is on the brink of civil war. Under the leadership of a renegade Jedi named Count Dooku, thousands of solar systems threaten to break away from the Galactic Republic. When an assassination attempt is made on Senator Padmé Amidala, the former Queen of Naboo, twenty-year-old Jedi apprentice Anakin Skywalker is assigned to protect her. In the course of his mission, Anakin discovers his love for Padmé as well as his own darker side. Soon, Anakin, Padmé, and Obi-Wan Kenobi are drawn into the heart of the Separatist movement and the beginning of the Clone Wars.','A Jedi Shall Not Know Anger. Nor Hatred. Nor Love.',120000000,649398328,43.987061,6.4,3992,142,'2002-05-15','en','/oZNPzxqM2s5DyVWab09NTQScDQt.jpg',3.8078201389187822,3,'2026-09-10',2,NULL,NULL),(1895,'星球大战3：西斯的复仇','Star Wars: Episode III - Revenge of the Sith','Years after the onset of the Clone Wars, the noble Jedi Knights lead a massive clone army into a galaxy-wide battle against the Separatists. When the sinister Sith unveil a thousand-year-old plot to rule the galaxy, the Republic crumbles and from its ashes rises the evil Galactic Empire. Jedi hero Anakin Skywalker is seduced by the dark side of the Force to become the Emperor\'s new apprentice – Darth Vader. The Jedi are decimated, as Obi-Wan Kenobi and Jedi Master Yoda are forced into hiding. The only hope for the galaxy are Anakin\'s own offspring – the twin children born in secrecy who will grow up to become heroes.','The saga is complete.',113000000,850000000,44.108427,7.1,4116,140,'2005-05-17','en','/xfSAoBEm9MNBjmlNcDYLvLSMlnq.jpg',3.9935021454535002,3,'2026-09-10',2,NULL,NULL),(1900,'毒品网络','Traffic','影片将毒品问题置于政治、商业与生活方式的层面进行审视。导演史蒂文·索德伯格以创新的色彩编码视觉处理区分交织的叙事线，将观众卷入新任禁毒主管及其家庭、西海岸毒枭的妻子、关键线人以及美墨边境两侧警察的生活之中。这部影片以不牺牲张力与悬念的方式，对具有国际重要性的议题作出了复杂而细腻的剖析，成为当代经典之作，并荣获四项奥斯卡奖，包括最佳导演、最佳改编剧本、最佳剪辑，以及本尼西奥·德尔·托罗的最佳男配角奖。[标准收藏]','No one gets away clean',48000000,207515725,25.170217,6.9,562,147,'2000-12-27','en','/jbccmnqE4oAPI67bApgt2JiRPz8.jpg',3.3694062990180673,3,'2026-09-10',2,NULL,NULL),(1901,'大公司小老板','In Good Company','51岁的霍丹（丹尼斯•奎德 饰）是一本美国权威杂志的广告部总监，事业得意的他家庭也十分美满。两名女儿非常出色以外，妻子最近又怀孕了。可是，霍丹的生活，因为事业上的突然转变，有了翻天覆地的改变。他的公司被大财团收购了，而他的职位将有一名叫卡达（托弗•戈瑞斯 饰）所替代，而这位新人只有26岁，没有一点广告经验，这使霍丹气氛不已。为了家庭，霍丹不能就此辞职。与霍丹相反的是，卡达早已与妻子离婚，了无牵挂。两个男人也开始了办公室里的明争暗斗，令人意想不到的是，因为霍丹女儿爱丽斯（斯嘉丽•约翰逊 饰），使两位男士改变了自己的态度。','He\'s rich, young and handsome. He\'s in love with you and he\'s your dad\'s boss.',0,0,15.376391,5.9,194,109,'2004-12-29','en','/sLmx9ctyxcLrPctkQwPYeseW924.jpg',3.0005080668148523,3,'2026-09-10',2,NULL,NULL),(1903,'香草的天空','Vanilla Sky','大卫·阿姆斯（汤姆·克鲁斯 Tom Cruise 饰）可以称为上帝的完美杰作：他家境优渥、事业有成、仪表堂堂、风度翩翩，无数性感迷人的女性都为其柔情蜜语所倾倒。而大卫自是不愿浪费这天赐的条件，他四处出击，以猎艳为乐，甚至连好友的女朋友索菲娅（佩内洛普·克鲁兹 Penélope Cruz 饰）都不放过。不过，大卫终要为自己的花心付出代价，在和前女友茱丽（卡梅伦·迪雅兹 Cameron Diaz 饰）乘车出行之时，茱丽开车撞向大树，企图与之同归于尽。这场车祸使大卫的人生跌入谷底，而更为诡异的却仍在前面等待着他……','Forget everything you know, and open your eyes.',68000000,203388341,27.299301,6.5,1078,136,'2001-12-10','en','/AbgzoLeZVxbTFDORtzl12MHLlYz.jpg',3.4820037600272604,3,'2026-09-10',2,NULL,NULL),(1904,'艺伎回忆录','Memoirs of a Geisha','有着一双蓝灰色眼睛的小百合（章子怡 饰）出生于贫穷小渔村，被卖到京都一家知名的艺妓馆。小百合在那里学习了舞蹈、茶艺等，渐渐成为当地头牌艺妓，同时也不断受到京都第一红妓初桃（巩俐 饰）的压迫与挑战。一个偶然的机会，全日本最美丽、知名的艺妓真美羽（杨紫琼 饰）要认小百合为“妹妹”，此举从此改变了小百合的一生……','My world is as forbidden as it is fragile; without its mysteries, it cannot survive.',85000000,162242962,16.595874,7.3,652,145,'2005-12-06','en','/mokNerxQ1B6wYcPP3e6Nhv3vbjp.jpg',3.447394663546193,3,'2026-09-10',2,NULL,NULL),(1907,'海滩','The Beach','Richard（Leonardo DiCaprio）是位酷爱网上冲浪和冒险的美国年轻人，一天，他来到泰国曼谷，欲找寻在网络上得知的天堂海滩。在投宿的廉价旅馆里，他遇到法国女孩Franoise（Virginie Ledoyen）和其男友，三人成了朋友，不久Richard爱上Franoise。 Richard从诡异的光头佬那里得到一些听来奇怪的秘密，随后光头佬留下一张神秘地图意外死去，这激起Richard的好奇心，按图索骥一番追踪，他确信天堂海滩的确存在，开始说服Franoise和其男友同他一起去找寻天堂海滩，并复制了一份地图供另外认识的美国朋友前去探险……','Somewhere on this planet it must exist.',40000000,144056873,41.362082,6.3,1233,119,'2000-02-11','en','/tMgbegbwP0dUfLmPKkSnp4mDOyH.jpg',3.509258778290525,3,'2026-09-10',2,NULL,NULL),(1909,'天生爱情狂','Don Juan DeMarco','精神科医生杰克（马龙·白兰度 Marlon Brando 饰）的家庭平静但缺少激情，随着年岁的增长，他感到曾经的梦想离自己越来越远。就在离退休还有10天时，他接手了一个有妄想症，企图自杀的青年。青年自称唐璜（约翰尼·德普 Johnny Depp 饰），带着面具，穿着不符合时代的长靴和披风，佩带长剑，他因被最爱的女人抛弃，而萌生了自杀的念头。唐璜虽然行为举止十分怪异，但却有着无法抵挡的个人魅力，他向杰克倾诉自己的过往，他的传奇经历深深吸引了杰克，同时也引发了他对自己婚姻生活的深刻的思考。就在杰克被唐璜吸引之时，唐璜的祖母和母亲相继出现，两人所言却大相径庭。他到底是谁？只是一个疯疯癫癫的浪荡子，还是真的是一个背负着沉重过去的大情圣？10天很快就要过去了，面对同事和法官，他又会做出怎样的选择呢？','The story of the man who thought he was the greatest lover in the world... and the people who tried to cure him of it!',25000000,22200000,8.870614,6.2,183,97,'1994-10-01','en','/y5tYV5QvMniUCLluKxdg94caCOL.jpg',2.9917175840130317,3,'2026-09-10',2,NULL,NULL),(1911,'终极奇兵','The 13th Warrior','曾几何时，阿莫德（安东尼奥·班德拉斯 Antonio Banderas 饰）也享受着锦衣玉食的生活，可犯了色戒的他最终遭到了被放逐的命运，他带着仆人梅奇塞德（奥马尔·沙里夫 Omar Sharif 饰）踏上了无尽的旅程。在旅途中，阿莫德结识了由波利维（Vladimir Kulich 饰）领导的勇士团，他们告诉阿莫德，有一种可怕的食人怪兽在他的家乡肆虐，许多平明百姓无辜死去。对于波利维的说辞，阿莫德半信半疑，决定跟随他们去一探究竟。勇士团里人才辈出，但阿莫德很快就发现，即便如此，他们想要战胜凶残的食人魔却仍显吃力。可是，异种已经兵临城下，若不奋起反抗则只有被残忍的吞噬。在勇士团的帮助下，阿莫德一行人能够获得最后的胜利吗？','Prey for the living.',160000000,61698899,27.220157,6.4,510,102,'1999-08-27','en','/pj1IQQ7ajwaOrjjTCxyM1L4mSnX.jpg',3.285674444625963,3,'2026-09-10',2,NULL,NULL),(1913,'The Sea Inside','Mar adentro','The Sea Inside is about Spaniard Ramón Sampedro, who fought a 30-year campaign to win the right to end his life with dignity. It is the story of Ramón’s relationships with two women: Julia a lawyer who supports his cause, and Rosa, a local woman who wants to convince him that life is worth living.','Sensitive Drama About a Polemic Theme',12806000,38535221,17.363739,7.2,219,125,'2004-09-03','es','/6mGgn60Riv14B3zPjTNNZnFHp3c.jpg',3.1200616296959565,3,'2026-09-10',2,NULL,NULL),(1921,'甜蜜十一月','Sweet November','尼尔森·摩斯（基努·李维斯饰）是广告界的精英，作为一个工作狂，他的生活却总是一成不变，除了工作和自己，他对周遭一切漠不关心。也许，与莎拉·蒂佛(查理兹·塞隆饰)的邂逅是上天给他转变的一个契机。美丽迷人的莎拉是一个个性开朗的姑娘，她的笑容甜蜜且温柔。在莎拉的眼中，尼尔森完全不懂得享受人生，于是莎拉提出一个建议，她邀请尼尔森搬来与她同住一个月，这一个月里，他必须完全依照莎拉的生活方式来过日子，她信誓旦旦地向尼尔森表示，只要短短一个月的时间，她可以让事业陷入低谷的尼尔森变成另外一个人。两个人的协议就此达成：时间只有一个月，时限一到就分手，没有压力，不留期待。尼尔森成了莎拉的“甜蜜十一月”，在莎拉的带领下他重新认识了这个世界。就在一个月即将进入尾声的时候，尼尔森终于明白原来生命尽然如此简单，快乐也唾手可得。正当尼尔森准备与莎拉携手到老的时候，他却发现了隐藏在莎拉背后一个令他心痛的秘密，他陷入两难的境地……','She Just Needed A Month To Change His Life For Ever.',40000000,65754228,19.372805,6.4,278,119,'2001-02-16','en','/xiVMzRNqMIHJneMxkD1RF2VOzrW.jpg',3.124651140978257,3,'2026-09-10',2,NULL,NULL),(1924,'Superman','Superman','Mild-mannered Clark Kent works as a reporter at the Daily Planet alongside his crush, Lois Lane − who\'s in love with Superman. Clark must summon his superhero alter ego when the nefarious Lex Luthor launches a plan to take over the world.','You\'ll Believe a Man Can Fly!',55000000,300218018,48.507081,6.9,1022,143,'1978-12-13','en','/6GtoQ9ZStPapXbt4QLlnhhK2Y9r.jpg',3.587437089571978,3,'2026-09-10',2,NULL,NULL),(1927,'绿巨人浩克','Hulk','从小孤苦无依的布鲁斯·班纳长大后成为了美国伯克利军方的科学家，专职从事新型高能炸弹的研究工作，他与罗斯将军的女儿贝蒂·罗斯相恋。事业与感情一帆风顺的布鲁斯似乎已经摆脱了幼年孤独的阴影，走上了一条让人艳羡的成功之路。然而好景不长，在一次试验中，为了保护一名同事，布鲁斯暴露在致命的伽马射线之下，布鲁斯体内的神秘力量被意外唤醒。从此之后，每当情绪激动时，布鲁斯就会失去自我意识，变身成为绿巨人，并且同时具有超强的破坏力和抗拒意志。但布鲁斯并不知道也不想知道自己异于常人的变身能力。对他来说，自己只是一名没有过去、充满困惑的孤独科学家，丝毫不能理解为何会突然招致军方的围捕。面对一系列措手不及的突发事件，布鲁斯的女友贝蒂·罗斯同样感到迷茫无助。她希望帮助布鲁斯，但却遭到负责围捕绿巨人的父亲的阻止。而此时，自称是布鲁斯父亲的神秘人物大卫(尼克·诺尔蒂 饰)出现在罗斯将军身边，他告诫贝蒂不要接近自己的儿子，令贝蒂更感困惑。就在贝蒂思念班纳的同时，罗斯将军所带领的特种军队非但不会同情绿巨人的遭遇，反而早已洒下天罗地网并派出最强大的战士，意欲抓获绿巨人以获知其中的秘密。为了对抗绿巨人的超能力，罗斯将军也有自己的秘密武器，那就是神秘的超能力怪物——“吸收人”(Crusher Creel)。“吸收人”可以变身成为任何自己接触到的物体，与绿巨人势均力敌。而更为惊人的是，“吸收人”其实就是布鲁斯的生身父亲大卫·班纳。由此，布鲁斯的神秘身世开始逐渐清晰起来……','Unleash the hero within',137000000,245360480,34.981698,5.3,1533,138,'2003-06-19','en','/bxyaXFv6kJbMB3wCRQUHd6e4fGS.jpg',3.341342617909453,3,'2026-09-10',2,NULL,NULL),(1930,'超凡蜘蛛侠','The Amazing Spider-Man','Peter Parker is an outcast high schooler abandoned by his parents as a boy, leaving him to be raised by his Uncle Ben and Aunt May. Like most teenagers, Peter is trying to figure out who he is and how he got to be the person he is today. As Peter discovers a mysterious briefcase that belonged to his father, he begins a quest to understand his parents\' disappearance – leading him directly to Oscorp and the lab of Dr. Curt Connors, his father\'s former partner. As Spider-Man is set on a collision course with Connors\' alter ego, The Lizard, Peter will make life-altering choices to use his powers and shape his destiny to become a hero.','The untold story begins.',215000000,752215857,89.866276,6.5,6586,136,'2012-06-27','en','/jexoNYnPd6vVrmygwF6QZmWPFdu.jpg',4.053042196377688,3,'2026-09-10',2,NULL,NULL),(1931,'街舞少年','Stomp the Yard','有舞王之称的DJ·威廉斯（哥伦布·绍特 Columbus Short 饰）就刚刚经历了一场因为飙舞而引起的社团争斗，他一直呵护的弟弟在这场流血事件中意外丧生。身心俱疲的他来自洛杉矶，到来亚特兰大一所黑人学校进修。  　　在新环境里感到非常不适应的他，自从加入了一个街舞爱好者同盟会之后，生活开始有了翻天覆地的变化。他的出众舞技在这里得到施展，同盟的人在景仰之余，都期待他能帮助同盟会夺取大家垂涎已久的全国街舞大赛冠军。然而他们不知道的事，纵然有出神入化的舞技，在成为同盟会最有竞争力的主心骨之前，DJ必须面对的是如何抛开残酷的往事带给他的种种阴影。DJ是否能够重新站起身来，正视前方的道路，在这条自己曾经深深热爱的街舞道路上勇往直前呢？','He will challenge their traditions. Their traditions will change his life.',13000000,75511123,6.92205,6.1,88,114,'2007-05-16','en','/dald9tUbRmGQ91CUJnzaBAjjvUf.jpg',2.823881023709613,3,'2026-09-10',2,NULL,NULL),(1933,'小岛惊魂','The Others','二战结束，格蕾丝(尼科尔•基德曼 饰)在英伦的小岛上独自抚养着一对儿女，耐心等待着丈夫从战场归来。儿女怕光，受到光照会发病，因此家里的窗帘常年拉得严严实实。就在这样一间阴暗的古宅里，格蕾丝迎来了三个新仆人。这三个人到来之后，却让格蕾丝寒了心——窗帘经常被拉开，门无故打开，钢琴自动发声，而她的女儿说，在房间里经常可以见到陌生男人。格蕾丝陷入了精神紧张的状态，她不明白怪事为何屡屡发生，不明白丈夫为何迟迟未归。而她最后才醒悟，所有的惊恐，其实都来源自身，但是事情已经不可逆转……','Sooner or later she\'ll see them, then everything will be different.',0,0,25.881355,7.4,1660,101,'2001-08-02','en','/p8g1vlTvpM6nr2hMMiZ1fUlKF0D.jpg',3.771513163287986,3,'2026-09-10',2,NULL,NULL),(1934,'莎翁情史','Shakespeare in Love','本片是一部背景设定在1590年代、献给1990年代的浪漫喜剧。它富有想象力地铺陈出这部旷世爱情杰作背后那段妙趣横生、香艳动人且永恒传世的创作故事。[米拉麦克斯影业]','Love is the only inspiration.',25000000,289317794,31.792964,6.8,796,122,'1998-12-11','en','/vEPCWYt9DZIYJrNqE8gGFbndmBW.jpg',3.4648119863558304,3,'2026-09-10',2,NULL,NULL),(1946,'感官游戏','eXistenZ','在科技发展到尖端的未来，爱丽拉盖勒这位美丽性感的设计师有若电玩界的女王，她所设计的[X接触]远远超越时代，它非常真实引人入胜，在试玩大会上，各方玩家齐聚一堂，体验爱丽拉的最新杰作，想不到半途杀进一群狂热者企图刺杀爱丽拉，在一片混乱中，爱丽拉被守卫泰德皮库救走，皮库是公司的新进员工，为了躲避追杀，在爱丽拉的带领下，双双进入X接触的异世界，但包括双头怪兽在内的各方杀手仍穷追不舍…','Play it. Live it. Kill for it.',15000000,2856712,21.928025,6.7,475,97,'1999-04-14','en','/gRTMkYKtHBElyD2OZ20u6XmkZXi.jpg',3.2922277613430673,3,'2026-09-10',2,NULL,NULL),(1947,'未竟一生','An Unfinished Life','艾纳（罗伯特·雷德福 Robert Redford 饰）拥有一段伤感的过去，车祸夺走了儿子格里芬（Trevor Moss 饰）的性命，而这车祸的始作俑者不是别人，正是自己的儿媳简（詹妮弗·洛佩兹 Jennifer Lopez 饰）。愤怒的艾纳无法原谅简的过失，无奈之下，简只得带着腹中的胎儿远走高飞。  　　如今的艾纳生活在怀俄明牧场里，除了放牧，他还担负起了照顾被熊所伤的老朋友米特（摩根·弗里曼 Morgan Freeman 饰）饮食起居的责任。曾经的悲伤未曾消逝，但一对老友相互扶持，生活倒也宁静祥和。琼的再度到来打破了这难得的宁静，同时到来的，还有11岁的艾纳的孙女格瑞芙（Becca Gardner 饰）。出于同情，艾纳收留了母女两，但往日的冤仇并未完全化解。同时，导致米特受伤的灰熊被捉拿归案等待处置。面对曾经的仇恨，两个老人会做出怎样的选择？','Every secret takes on a life of its own.',30000000,18618284,6.353971,6.7,161,108,'2005-09-09','en','/7ugLG1yF1l8HWYhmdmHHSC3kJ8b.jpg',2.9849515967351494,3,'2026-09-10',2,NULL,NULL),(1948,'怒火攻心','Crank','一向在道上风光无限的黑帮大哥切夫·切里奥斯（杰森·斯塔森）如今却倒霉地遭遇黑手袭击。 一次正当自己熟睡的时候，不小心被一个已经被对手收买的小弟暗算。那小子趁着他熟睡的时候，悄悄地给他注射了一种侵害人体心脏的毒药。这种毒药有着独特的功效，通常状况下会让人被注射者在一个小时内他就猝然死去。而这种神奇的毒药竟然还有一种神奇的也是唯一的补救方法是——就是让被注射者的心脏一直保持在一个相对很快的跳动的频率上，就能幸免一死。 醒来后得知此事的切里奥斯，愤怒之余只有想尽一切办法拯救自己的心脏乃至性命。于是，切里奥斯开始拼命地让自己进入心脏兴奋的状态下，并尽快找到陷害自己的小子，弄到解药，同时，还要反击来自敌手的不断进攻，并保护好自己美丽的女友。 所有这一切，让所有人自然也包括切夫·切里奥斯自身进入了一个真正的心惊肉跳的状态。好莱坞“心脏版”生死时速亦全面展开了！','There are a thousand ways to raise your adrenaline. Today, Chev Chelios will need every single one.',12000000,42931041,47.992817,6.6,1151,88,'2006-08-31','en','/4KAqVwgHC9Dl1xg4YcmRqyK25NT.jpg',3.5636801961649893,3,'2026-09-10',2,NULL,NULL),(1949,'十二宫','Zodiac','二十世纪70年代，旧金山出现了一个自称“十二宫”的杀人狂，杀人后，向媒体寄一封信，留下密码、线索，向警方挑衅，多次的阴差阳错使案件陷入僵局，警方渐渐束手无策。连环杀人案件也引起了《旧金山纪事报》的记者罗伯特（杰克•格兰恩哈尔 饰）和保罗（小罗伯特•唐尼 饰）的注意，他们在警察大卫（马克•普法洛 饰）的帮助下，开始调查这一系列的连环凶杀案件，在和“十二宫”杀手斗志斗勇的同时，他们个人的生活也面临了极大的挑战。','There\'s more than one way to lose your life to a killer.',65000000,84785914,51.970905,7.3,2023,157,'2007-03-02','en','/6YmeO4pB7XTh8P8F960O1uA14JO.jpg',3.8675098148030305,3,'2026-09-10',2,NULL,NULL),(1950,'幸运赌神','Lucky You','一场世界性的扑克牌比赛正在人人趋之若鹜的拉斯维加斯轰轰烈烈的举行着，每天，无数的扑克牌高手从世界各地赶到此处，为的就是能在这样的权威性赛事里一决高下。在诸多的选手中，一个名叫哈克（艾瑞克·巴纳 Eric Bana 饰）的年轻人颇为显眼。在比赛中，哈克不仅屡屡创下佳绩，更是光明正大的将目光投向了冠军的宝座。\r 　　一次偶然中，哈克结识了美丽聪明的歌女比莉（德鲁·巴里摩尔 Drew Barrymore 饰），郎才女貌的两人一见钟情。比莉不仅为哈克带来了爱情，还令哈克明白了人生中除了成功，还有许多宝贵的东西。决赛的赛场上，坐在牌桌前的哈克震惊的发现，他所要面对的对手不是别人，正是自己的父亲。','Change your game. Change your life.',0,5761917,6.162872,5.4,81,124,'2007-05-01','en','/23jI1zZnrLlrkeGjjkBkUF4FVTf.jpg',2.783373240805288,3,'2026-09-10',2,NULL,NULL),(1951,'曼德勒','Manderlay','故事发生在1933年，格蕾丝和父亲离开狗镇一路南下，希望寻找一个稳定安全的落脚点。一行人来到了阿拉巴马州，停在了曼德勒庄园的门前。  　　正当众人准备离开此地之时，格蕾丝忽然收到了一名年轻黑人女子的求助，女子告诉格蕾丝，在曼德勒庄园里，正在发生一些惨无人道的事情。枝蔓丛生的慢的了庄园之中，时间似乎停止了，尽管奴隶们早已经获得了自由，但在这里，依旧沿用着森严的奴隶制度。不顾父亲的阻止，格蕾丝执意要留在此处解放奴隶，父亲留给了格蕾丝一些保镖和一名律师，绝尘而去，形单影只的格蕾丝面对强大而又固执的奴隶主们，会做出怎样的反击呢？','Liberation. Whether They Want It Or Not.',14200000,674918,7.05145,6.9,78,139,'2005-05-16','da','/iKN0WQ1qVYaHUHqXnwpyHyUQOw.jpg',2.8215503996918243,3,'2026-09-10',2,NULL,NULL),(1954,'蝴蝶效应','The Butterfly Effect','伊万从小经历着一个充满创伤的童年，每当一些可怕的事情发生时，他总会莫名失去一段记忆，只留下零碎而模糊的片段。在心理医生的建议下，他开始用日记记录自己的生活。多年后，已经进入大学的伊万重新翻看童年时期的日记，意外发现自己的意识能够回到那些曾经失去记忆的时刻，并借由童年的身体重新作出选择。为了弥补过去留下的伤痛，也为了改变凯蕾和朋友们的人生，他一次次回到过去，希望让所有人的生活变得更好。然而每一次看似微小的改变，都会让现实走向完全不同的方向，并带来更加无法预料的后果……','Such minor changes, such huge consequences.',13000000,96060858,73.307513,7.3,2060,113,'2004-01-22','en','/ea5iv7TWMh18fOKoRGgmtcg85Gx.jpg',3.921431941104461,3,'2026-09-10',2,NULL,NULL),(1955,'The Elephant Man','The Elephant Man','A Victorian surgeon rescues a heavily disfigured man being mistreated by his \"owner\" as a side-show freak. Behind his monstrous façade, there is revealed a person of great intelligence and sensitivity. Based on the true story of Joseph Merrick (called John Merrick in the film), a severely deformed man in 19th century London.','I am not an animal! I am a human being! I... am... a man!',5000000,26010864,30.271066,7.9,719,124,'1980-10-02','en','/uWl32ismsTMCSviQZx6fkc52k6s.jpg',3.5979557153539243,3,'2026-09-10',2,NULL,NULL),(1956,'盖瑞','Gerry','两个年轻人在一次旅途中迷失了方向，巧的是他俩的名字都名叫“杰瑞”。于是在沙漠里两人开始了寻找归途之旅。  　　在去年圣丹斯电影节上，这部影片让半数以上观众离场。在关于此片的国外评论中最常用到的词是“极端极简主义”。的确，整部片子拥有一句话可以讲完的故事情节，构图简单的超长镜头(全片不超过50个镜头)，还有著名现代音乐家，极简主义的代表人物阿沃·帕特的音乐，所有这一切，构成了这部爱之极爱，恨之极恨的作品。',NULL,3500000,0,5.038953,6.2,68,103,'2002-01-12','en','/jzuPVECdfWuHoBIqQEFajbSwwpa.jpg',2.7669553763548373,3,'2026-09-10',2,NULL,NULL),(1957,'忍无可忍','Enough','《忍无可忍》以女性应勇敢抗争为主题，片中有不少暴力镜头。\r 　　六年前，在餐馆打工的Slim（詹妮弗·洛佩兹 Jennifer Lopez 饰）被客人纠缠，幸得Mitch（比利·坎尔贝 Bill Campbell 饰）挺身而出，很快两人坠入爱河并结了婚。6年过去了，他们有了女儿Gracie，一家人过着平静富足的生活。但偶然，Slim发现Mitch和其他女人有染而发生了争吵被Mitch打伤，从此恶梦般的生活开始了。Mitch有严重暴力倾向，他的变本加厉彻底毁灭了Slim原本打算忍辱偷生的念头，不堪忍受痛苦的她带着女儿逃离了这个家。她们辗转于西亚图、旧金山等多个城市，却仍无法摆脱Slim幽灵一般的纠缠。Slim终于被逼到崩溃的边缘，她决定用最极端的方法来结束自己和女儿的恶梦——杀死Mitch......','Everyone has a limit.',38000000,51801187,11.500783,6.2,264,114,'2002-05-24','en','/yAfXnB6B69iM8KiWwzGulCXF4Mo.jpg',3.078649616480031,3,'2026-09-10',2,NULL,NULL),(1958,'八美图','8 femmes','圣诞节前夕，一个富裕人家正在忙着筹备圣诞。窗外白雪皑皑，屋里迎来了女儿大学归来。一家人沉浸在圣诞前团聚的气氛。此时，大家以为作为一家之主的父亲还没有睡醒，谁知打开房门一开，他竟死在了睡床上，背后插着一把刀。众人惊慌失措，想报警之时却发现电话线早以被剪断；车已被蓄意破坏，无法开到警局。明显地，凶手就在这8人中间。彼此的猜忌和指控开始了，各人不为人知的秘密一一曝光，伦理道德的颠覆，贪婪自私的本性，令这个圣诞前夕特别混乱。讽刺的是，最后谁是凶手已经不重要了……','Living in a house full of women can be murder.',8000000,0,8.204829,6.9,196,111,'2002-01-08','fr','/zjSfFj8vVCJ9YHI7Qs0JHrCnPSA.jpg',3.0498403814859327,3,'2026-09-10',2,NULL,NULL),(1961,'我叫布鲁斯','My Name Is Bruce','故事讲述了拍摄过《鬼玩人》三部曲的布鲁斯，被绑架到俄勒冈州的一个小镇上，重演他在《鬼玩人》中的角色，被迫与怪物进行战斗。','Fearless! Unstoppable! Ready For His Close-Up!',1500000,173066,7.5591,5.9,107,86,'2007-10-01','en','/et2f1JBW533ZzYiCEA2T7nwzcs1.jpg',2.8595916338462954,3,'2026-09-10',2,NULL,NULL),(1966,'亚历山大大帝','Alexander','亚历山大大帝生于纪元前356年为马其顿王（菲利普）之子，是历史上第一位征服欧亚大陆的著名帝王。亚历山大自幼聪颖过人，曾受教于大师（亚利斯多德），稍长即被授予首府总督之职，并以平定山贼有功而任命为马其顿大军统帅，随父横扫希腊城邦之乱。  　　西元前336年菲利普遇刺，亚历山大继任王位并继承乃夫遗志，率领希腊联军进攻波斯，关尼卡卡一役大败波斯并直入小亚细亚攻占两河流域，波斯帝国崩溃，波斯王大流士被杀，又进军埃及又越过印度河进入恒河流域，因军士思乡被迫退回。亚历山大融合东西文化，鼓励民族间通婚，并倡导民族间地位平等，讲希腊思想律法散布各地，开创希腊化时代文化，死时却年仅33岁。','The greatest legend of all was real.',155000000,167298192,39.019229,5.6,927,175,'2004-11-21','en','/hsNqRRSTOCyapldRcgKElBTpyEn.jpg',3.3205696447674775,3,'2026-09-10',2,NULL,NULL),(1969,'Bandidas','Bandidas','Set in the late 19th century. When a ruthless robber baron takes away everything they cherish, a rough-and-tumble, idealistic peasant and a sophisticated heiress embark on a quest for justice, vengeance…and a few good heists.','Being BAD never looked so GOOD!',35000000,10496317,20.27704,5.8,307,93,'2006-01-18','es','/31wgXG6OxDaXbp5IzyNoUJdVS5e.jpg',3.096568478399848,3,'2026-09-10',2,NULL,NULL),(1970,'The Grudge','The Grudge','American nurse, Karen Davis moves to Tokyo and encounters a vengeful supernatural spirit known as The Grudge that often possesses its victims. When a series of horrifying and mysterious deaths occur – with the spirit passing its curse onto each victim - Karen must find away to break the spell before she becomes the spirit\'s next victim.','It never forgives. It never forgets.',10000000,183474602,35.695442,5.8,865,92,'2004-10-22','en','/nr2YFEx3sc2IL1LWYxTP6a3Dwiw.jpg',3.333166605283507,3,'2026-09-10',2,NULL,NULL),(1975,'咒怨2 美版','The Grudge 2','陌生的东京街头，一辆出租车疾驰而过，车窗上映出奥布莉（安珀·汤伯林饰）疑惑的脸。奥布莉的姐姐是两年前到日本修读的美国交换生凯伦（萨拉·米歇尔·盖拉饰），就在昨天晚上，家里收到通知--姐姐凯伦被控杀死男友和放火烧毁房屋，被关入了一间医院治疗。匆忙订了航班赶到东京的奥布莉，却只得到凯伦意外死亡的消息和“千万不要进入老屋”的忠告。  为了调查姐姐的神秘死亡，奥布莉和来自香港、专门报道灵异现象的记者伊森（陈冠希饰）一起踏入了诅咒老屋，果不其然，两人都开始逐渐看到异象。经过一番寻根究底，他们发现恶灵伽椰子的母亲正是离东京不远的一个小村庄的巫女。  与此同时，在东京的一间国际交流学校里，不太受欢迎的艾莉森为了融入学校，甘愿跟随两名校花去到咒怨之屋。当她受到惊吓惊恐哭泣着寻求帮助时，只是为了看她笑话的两名校花却大笑离开。没过多久，她们一个被拖入镜子永久消失，另一个则在公用电话亭里被活生生吞噬。而在芝加哥的一个普通家庭里，小儿子也因为邻居公寓里的奇怪噪音变得神神叨叨...到底这一切，有什么千丝万缕的联系？不死咒怨是否将再次肆意蔓延？','What Was Once Trapped, Will Now Be Unleashed',20000000,39143839,13.906944,5.2,283,102,'2006-10-13','en','/a8pBMlpFeh50ZCyzuTTwqb0BqVY.jpg',3.0156029587236475,3,'2026-09-10',2,NULL,NULL),(1979,'神奇四侠2','Fantastic Four: Rise of the Silver Surfer','在解决了“毁灭博士”后，“神奇四侠”已经逐渐适应了新的身份，队员们的生活亦过得有滋有味 。里德（艾恩·格拉法德 Ioan Gruffudd 饰）和苏珊（杰西卡·阿尔芭 Jessica Alba 饰）终于步入婚姻教堂，然而，正当婚礼进行到一半时，突然狂风大作，一道银色闪电在天空闪过。里德忙叫“霹雳火”（克里斯·埃文斯 Chris Evans 饰）追上去看过究竟，熟料“霹雳火”完全不是对方对手，里德的担忧变成了现实：新的敌人出现了――“银影侠”（道格·琼斯 Doug Jones 饰）。世界各地开始灾难不断。通过调查，苏珊发现“银影侠”只不过受“行星吞噬者”所迫，帮其在宇宙寻找可供其吞噬的星球，今次的目标正是――地球！“神奇四侠”又出动了，这次能否帮助可怜的“银影侠”、成功挽救地球？','Discover the secret of the Surfer.',130000000,289047763,60.810723,5.4,2589,92,'2007-06-13','en','/52IDYpQjJPoHDa2HmPP4PnqlyBD.jpg',3.5124951681479977,3,'2026-09-10',2,NULL,NULL),(1985,'不朽的园丁','The Constant Gardener','改编自约翰·勒卡雷的小说，这部扣人心弦的爱情惊悚片带领观众踏上一段情感与全球交织的探寻之旅，揭开个人悲剧与跨国阴谋背后的真相。[焦点影业]','Love. At any cost.',25000000,82466670,20.679652,6.8,417,129,'2005-08-31','en','/s5aqbBvPqkJaC4jFQsbbBXsoCKD.jpg',3.2666815364286914,3,'2026-09-10',2,NULL,NULL),(1988,'坚强的心','A Mighty Heart','电影改编自《华尔街日报》战地记者丹尼尔•珀尔的妻子所写的回忆录。丹尼尔（丹·福特曼 Dan Futterman饰）前往巴基斯坦调查报道一桩恐怖分子的新闻，却不幸遭到绑架，不久后惨遭杀害。妻子玛林娜（安吉丽娜·朱莉 Angelina Jolie饰）却一直在祈求丈夫能平安归来，寻找丈夫的信念一直支撑着这个已有着身孕的准妈妈。 她坚毅地书写回忆录，里面布满着和丹尼尔相识相知的点滴，更令丹尼尔的新闻理想和奔赴真相的勇气跃然纸上，她要让孩子知道，自己的父亲，曾经是一个称职的新闻人。玛琳娜终于能够坚强而平静的接受丈夫的遇害，同时，她不仅要让孩子远离种族仇恨和战争烟尘，还回到法国继续自己的事业，抚养孩子长大成人。','One woman dared to keep hope alive',16000000,18928871,9.717392,6.7,95,100,'2007-01-01','en','/rv4uwX3YQob8Ecaorx6DIy9kVzr.jpg',2.8674448427946815,3,'2026-09-10',2,NULL,NULL),(1989,'蓝莓之夜','藍莓之夜','伊丽莎白（诺拉•琼斯饰）被男友抛弃，伤心又苦恼的她把钥匙扔在咖啡店里。咖啡店的老板杰瑞米（裘德•洛饰）保存了很多钥匙，每把钥匙都埋藏了一个伤心的故事。伊丽莎白爱吃店里没人点的蓝莓蛋糕，在某一晚决定离开纽约，穿越美国到处看看。在旅途上认识了明明深爱却困囿彼此的分居夫妇，还有豪爽爱赌却鲜回家看望父亲的少女（娜塔莉•波曼饰），每到一个地方她就给杰瑞米写一张明信片。以他人为镜，伊丽莎白找到了爱的真谛，回到纽约，看见等待自己的杰瑞米，可以幸福地，再吃一客蓝莓蛋糕，放心享受爱的欢愉。','How do you say goodbye to someone you can\'t imagine living without?',10000000,21786738,10.733761,6,190,111,'2007-05-16','en','/wQAJv7qukZSd7grUWmXf6vt4OXC.jpg',2.991828370782146,3,'2026-09-10',2,NULL,NULL),(1995,'古墓丽影','Lara Croft: Tomb Raider','正当三颗行星在天上排成一列时，萝拉卡芙特在他父亲寇伯爵二十年前挖掘古墓带回来的箱子里，找到一具神秘的时钟。多年前，她父亲曾跟她提到一个叫作光明会的神秘组织，这个组织一直在寻找一具古钟，他们相信这具古钟是打开时间和空间的钥匙，这把钥匙是一块结晶的陨石金属所铸成的三角形神秘物体，五千年前被用来消灭他们所有的敌人。这块三角形被分成两半，只要把这两半结合为一，光明会的始祖将获得重生，人类的未来也将永远改变。四十八小时后，当行星完全排成一列，天空将出现日全蚀现象，而这时候三角的力量达到巅峰，如果错过这个时辰，就必须再等待另一个五千年。萝拉必须在短短的两天内，先到柬埔寨的光舞墓，找到三角形其中的一半，然后再赶到西伯利亚的万影窟，找到另一半。萝拉寇芙特究竟能不能在四十八小时内，找到神秘的三角形，并且及时拯救宇宙呢？','Born into Wealth. Groomed by the Elite. Trained for Combat.',115000000,274703340,41.498631,5.7,2192,100,'2001-06-11','en','/hNM9Y9AreeN1Q2OoKx6KpalKXNW.jpg',3.506184862776123,3,'2026-09-10',2,NULL,NULL),(1996,'古墓丽影：生命的摇篮','Lara Croft: Tomb Raider - The Cradle of Life','女探险家劳拉·克劳福特的生活，总是充满着各种凡人不可想象的惊奇与神秘。这一次，劳拉追随着“生命摇篮”的传说，又一次将目标瞄准了古老的神秘世界—— 已经沉入大海的月神庙。劳拉收集来的各种线索都显示着，神秘的月神庙正是传说中“潘朵拉魔盒”的埋藏地。据我们所知，“潘朵拉魔盒”是上古世界的神秘宝藏，蕴含着足以毁灭整个人类的巨大能量。但这样充满强大力量的宝藏，自然也招来了邪恶势力的窥伺。由香港黑社会头子陈洛(Chen Lo)所率领的犯罪集团，妄想夺取“潘朵拉魔盒”，获得其中足以摧毁地球的神秘力量！为了阻止犯罪集团背后所掩盖的邪恶野心，劳拉必须抢先找回盒子，破坏陈洛的计划……','Adventuress Lara Croft goes on a quest to save the mythical Pandora\'s Box',95000000,156505388,56.811056,5.5,1418,117,'2003-07-21','en','/cwFaQGC50NyzMyRev9G57WPp6T7.jpg',3.4181287403834846,3,'2026-09-10',2,NULL,NULL),(1997,'虎兄虎弟','Deux Frères','故事背景设定在20世纪20年代法属印度支那时期的柬埔寨，讲述了一对雌雄老虎相遇并交配的经历。数月后，这对虎夫妇生下了两只幼崽；然而，当艾丹·麦克罗里（盖·皮尔斯饰）——一名企图盗取古庙雕像并运往伦敦拍卖的男子——闯入它们栖息的古庙并惊扰了它们时，两只幼崽不幸失散。','Two infant tiger cubs, separated from their parents and each other.',74500000,62172050,8.884318,6.9,180,109,'2004-04-07','en','/5I2pRuJI3SZVsxP5iaorGaczzkI.jpg',3.0297202989413528,3,'2026-09-10',2,NULL,NULL),(1999,'意外边缘','In the Bedroom','故事发生在缅因州海岸一座宁静小镇，讲述一对夫妇的独生子与一位单身母亲陷入热恋。当这段关系以突如其来的悲剧告终，每个人都必须直面那个极其艰难的决定：该作何反应。[米拉麦克斯影业]','A young man. An older woman. Her ex-husband. Things are about to explode...',1700000,0,6.979638,6.4,89,130,'2001-11-23','en','/IQj11YbraLDyPYaz79jtDoAscc.jpg',2.836233688685764,3,'2026-09-10',2,NULL,NULL),(2001,'我们拥有夜晚','We Own the Night','1988年的纽约布鲁克林，鲍比（Joaquin Phoenix 饰）为俄罗斯商人巴斯哈耶夫打理着一家大型俱乐部，女友阿曼达（Eva Mendes 饰）与他互相深爱，事业与爱情颇为顺意，但是鲍比的家庭却让他感到抗拒，身为纽约警察局长的父亲和新近荣升缉毒组队长的哥哥约瑟夫（Mark Wahlberg 饰）所处的职业环境令鲍比厌烦难耐。他毫不迟疑的拒绝了约瑟夫的协查要求，任毒枭瓦汀在自己的俱乐部活动，约瑟夫对俱乐部的突查激怒了鲍比，同时也找来了瓦汀的报复。目睹被瓦汀重伤的兄长，鲍比无法继续置身事外，他接下了警方的卧底任务，使瓦汀的毒品工厂被警方清剿，不甘失败的瓦汀卷土重来，但这次他面对的，是鲍比与约瑟夫的联手出击……','Two brothers on opposite sides of the law. Beyond their differences lies loyalty.',21000000,54926886,14.518708,6.5,323,117,'2007-05-25','en','/fcb2c9BcRc21iiWih23FQfT39uB.jpg',3.157920592766626,3,'2026-09-10',2,NULL,NULL),(2008,'无极','无极','穷女孩受到命运女神满神（陈红 饰）的特殊眷顾，长大成人后做了集万般宠爱于一身的王妃倾城（张柏芝 饰），但是因此也成了被命运咒语所诅咒的“永远得不到真爱，除非时光倒流，人死复生”之人。在与北宫爵无欢（谢霆峰 饰）、大将军光明（真田广之 饰）等人进行的爱情角力中，倾城一次次被对方当作筹码，咒语灵验。但是身分卑微的奴隶昆仑奴（张东健 饰）却是真心爱着倾城。他期望用自己接近光速的奔跑来打破加诸在倾城身上的命运锁链，好让她返回人生的起点重获选择的权利。','the promise',0,0,3.866026,5,29,98,'2005-12-15','zh','/reF0KERj5TtCZMlbPni361Vbuj6.jpg',2.568394134681749,3,'2026-09-10',2,NULL,NULL),(2009,'四月三周两天','4 luni, 3 săptămâni și 2 zile','罗马尼亚导演克里斯蒂安·蒙吉凭借这部严谨现实主义的第二部长片荣获金棕榈奖，由此蜚声国际。影片设定在1987年齐奥塞斯库独裁时期，女大学生室友奥蒂莉娅与加比塔为后者寻求非法堕胎。影片以毫不妥协却又充满同理心的笔触，记述了她们生命中危机四伏的二十四小时，最终聚焦于她们与一名操控欲十足的威胁性堕胎医生的遭遇。凭借凸显角色缺陷人性的强大表演，本片成为一部椎心泣血的写实录，揭示了当女性掌控身体自主权意味着触犯法律时，所面临的艰难抉择。[标准收藏]','At what moment do we begin to live?',852510,1185783,9.270133,7.3,156,113,'2007-08-24','ro','/v3mdPzV5Ne8NFmU22rdTfKbKSNR.jpg',3.015738361938422,3,'2026-09-10',2,NULL,NULL),(2011,'我在伊朗长大','Persepolis','本片是一个年轻女孩在伊朗伊斯兰革命时期的动人故事。透过早慧直言的九岁玛嘉的眼睛，我们看到当原教旨主义者掌权后人民的希望如何破灭——他们强制妇女佩戴头巾，并囚禁了成千上万的人。机智而无畏的玛嘉智斗“社会卫士”，发现了朋克音乐、ABBA乐队和铁娘子乐队。然而，当她的叔叔被无故处决，两伊战争的炸弹在德黑兰落下时，渗透在伊朗日常生活中的恐惧变得清晰可触。[索尼经典]',NULL,7300000,0,24.281951,7.7,450,95,'2007-05-23','fr','/wDVqJXjU3mDP4yNyLLFiTT1JVjU.jpg',3.398185718243185,3,'2026-09-10',2,NULL,NULL),(2013,'潜水钟与蝴蝶','Le Scaphandre et le Papillon','本片讲述了让-多米尼克·鲍比非凡的真实故事。这位曾担任法国《Elle》杂志主编的成功且富有魅力的总编，原本认为自己正充分享受着完满人生，却因突发中风陷入生命被彻底颠覆的状态。尽管身体的困境让鲍比对未来几乎失去希望，他却逐渐发现，生命中曾有的激情、丰富的记忆与新生的想象力，能够引领他抵达一个没有边界的崭新世界。[米拉麦克斯影业]','Let your imagination set you free',14000000,19777647,13.65494,7.4,283,112,'2007-05-22','fr','/res4M4iWhMl15fD4lxaeUh7obh9.jpg',3.1996964938269157,3,'2026-09-10',2,NULL,NULL),(2018,'The Wedding Planner','The Wedding Planner','Mary Fiore, San Francisco\'s premiere wedding planner is rescued from an accident by the man of her dreams, pediatrician Steve Edison, only to find he is the fiancé of her latest client, wealthy Fran Donnolly. As Mary continues making the wedding arrangements, she and Steve are put into a string of uncomfortable situations that force them to face their mutual attraction.','His big day is her big problem.',35000000,94728529,14.949395,5.5,427,103,'2001-01-26','en','/meq4bLUPcBlOG3Z5YdiWuBMlpO.jpg',3.115733146703133,3,'2026-09-10',2,NULL,NULL),(2022,'Mr. Deeds','Mr. Deeds','When Longfellow Deeds, a small-town pizzeria owner and poet, inherits $40 billion from his deceased uncle, he quickly begins rolling in a different kind of dough. Moving to the big city, Deeds finds himself besieged by opportunists all gunning for their piece of the pie. Babe, a television tabloid reporter, poses as an innocent small-town girl to do an exposé on Deeds.','Small town kid, big time right hook.',50000000,171269535,18.121404,5.6,644,96,'2002-06-28','en','/7gGk3pkpRsNlJ4PrJgEfgY9PG43.jpg',3.2077941626090465,3,'2026-09-10',2,NULL,NULL),(2023,'沙漠骑兵','Hidalgo','《狂沙神驹》根据美国西部顶尖赛马手弗兰克·霍普金斯(Frank T. Hopkins)的真实经历改编而成，是一部充满着动作冒险与个人救赎的史诗巨作。 数个世纪以来每年举办的“火的海洋”(Ocean of Fire)是一项极其艰苦的耐力赛马竞技，3000英里的征程即使在平素地域尚且困难重重，何况选择了酷热郁闷而冷酷无情的阿拉伯沙漠，而且参赛赛马必须是由阿拉伯世界中最纯种、最高贵，由最尊贵的皇室家族拥有的赛马组成，但在公元1890年，这一根深蒂固的世俗被彻底的击碎了。 美国人弗兰克·霍普金斯(维果·莫天森饰)曾经是美国骑兵部队一名骁勇善战骑术高绝的骑士。国际知名人士的声望除了弗兰克凭借自身不懈努力以外，得力坐骑“海德尔格”(Hidalgo)的鼎立辅助同样是功不可没。如是背景下的1890年，弗兰克首次受邀带着“海德尔格”共同参加这项悲壮的沙漠耐力竞技，一人一马要面对整个阿拉伯世界中最优秀赛马的挑战。 把比赛的艰辛姑且放到一边，公平竞赛的意义也变得越发淡薄，阿拉伯人显然并不能接受外国人的介入，这其中尤以阿拉伯半岛和北非沙漠地区从事游牧的贝督因人最为露骨，他们中的一些骑士暗下决心不惜一切手段来阻止外籍人完成比赛。对弗兰克而言，“火的海洋”不仅仅成为了一场为荣誉与自尊的角力，更是一场为了自己及爱马“海德尔格”的生死存亡的战斗，把不可能完成的任务完成是唯一的选择。结局是令人胆战心惊后的满足，在朋友的帮助下，弗兰克最终完成了比赛，“海德尔格”也成为了阿拉伯耐力竞技历史上获胜的绝无仅有的美国赛马。','Unbridled. Unbroken. Unbeaten.',100000000,108103450,16.759252,6.5,318,136,'2004-03-05','en','/py8s68GTqujVr140l2jgy9bN5Sh.jpg',3.1592765575601933,3,'2026-09-10',2,NULL,NULL),(2024,'爱国者','The Patriot','梅尔·吉布森又一次为自由而战。故事发生在美国独立战争期间，一位爱好和平的父亲被逼上梁山，跟残暴的英国军队作殊死搏斗。本杰明·马丁早已告别戎马生涯，虽然他曾经同英国人并肩与法国人和印第安人浴血奋战，但终于有一天，他的儿子成为对抗英国军队的民兵组织头领，而英军掠夺了他的家园及他所挚爱的一切，于是他从一个理想主义的爱国者演变为现实主义的爱国者。','Some things are worth fighting for.',110000000,215294342,23.657284,6.8,1099,165,'2000-06-28','en','/99pFc3gOzu9TDAUrABY9anjlHSc.jpg',3.532534016880456,3,'2026-09-10',2,NULL,NULL),(2026,'Hostage','Hostage','When a mafia accountant is taken hostage on his beat, a police officer – wracked by guilt from a prior stint as a negotiator – must negotiate the standoff, even as his own family is held captive by the mob.','Every Second Counts',52000000,77944725,23.663713,6.2,512,113,'2005-03-09','en','/vjhLmtjO2pMQXRgkxcwZoq2Ma8n.jpg',3.2537152267187985,3,'2026-09-10',2,NULL,NULL),(2034,'训练日','Training Day','阿洛佐是美国毒品缉查部的黑人警探，经验丰富，查案出色，对毒品案件有着敏锐的嗅觉。人称“魔幻之眼”。这天阿洛佐的部门来了一个新同事杰克（伊桑•霍克 Ethan Hawke 饰），杰克跟随阿洛佐深入到街头的每一个阴暗角落，发现这个城市光怪陆离的同时，也慢慢见识了阿洛佐亦正亦邪的办案手法。阿洛佐虽然身为警探，手段却游走在法律边缘。他秉持“以毒攻毒”的原则，先把自己武装起来：没收罪犯的毒品自己服下，用枪指着杰克命令他跟着照做，他与贩毒分子甚至有着某种不寻常关系。但另一方面，他却奋力保护杰克这个年轻人，复杂的性格让杰克对这个神探上司捉摸不透。','The only thing more dangerous than the line being crossed, is the cop who will cross it.',45000000,104876233,52.081131,7.3,1634,122,'2001-10-05','en','/bUeiwBQdupBLQthMCHKV7zv56uv.jpg',3.805886502966885,3,'2026-09-10',2,NULL,NULL),(2043,'蛛丝马迹','Along Came a Spider','华盛顿一所贵族中学里，一名国会议员的女儿竟然在光天化日之下被人绑架了，资深警探亚历克斯·科罗斯（摩根·弗里曼）接下了这个棘手的案件，与此同时，原本负责保护议员女儿安全的年轻女特工杰姬·弗莱宁根（莫妮卡·波特）正为自己的大意失职而懊恼不已，为了弥补这个错误，杰姬自告奋勇要求协助亚历克斯进行调查。  　　一系列的调查取证之后，经验丰富的亚历克斯推断这并不是一起单纯的绑票，它和之前发生在城里的连环少女绑架案有着千丝万缕的关联，应该是同一罪犯所为，而所有的线索渐渐都指向了一个人——此人叫加里·索尼基（迈克尔·温柯特），他患有严重的精神分裂症但同时又智商过人，是个异常危险的犯罪分子。  　　尽管亚历克斯经验老道见多识广，但还是不知不觉中陷入罪犯布下的重重迷阵中，时间在一点一点流逝，亚历克斯最终能否识破的加里的花招，及时将议员的女儿和其他被绑架的女孩解救出来呢？面对如此狡猾的变态凶犯，年轻的杰姬是否能鼓起勇气，重新找回自信呢？','The game is far from over.',60000000,105178561,21.252797,6.1,400,104,'2001-04-06','en','/2mjHpWvmFmuwk1lZOowhEggCVhR.jpg',3.182559382328146,3,'2026-09-10',2,NULL,NULL),(2044,'触不到的恋人','The Lake House','女医生凯特（桑德拉•布洛克 饰）因为工作繁忙，搬离了郊外的河边小屋。临走时她在信箱里放了一封信，希望下一位住客能帮忙处理信件。不久，她来到了旧址，发现信箱里面有一封来自建筑师亚历克斯（基努•里维斯 饰）的来信。然而更让她意外的是，这竟然是一封来自两年前的信。凯特试着写了一封回信，放在信箱里，希望亚历克斯能够给他新地址。亚历克斯是个建筑师，这幢湖边小屋就出自他的手笔。然而他的作品总也得不到赏识。独自生活在小屋中的亚历克斯朋友不多，生活平静得孤独。不过在信箱中发现一封来自未来的信时，他发现原来一切还不是那么糟糕。他与凯特渐渐成为了笔友，两年的时间界线似乎并不存在，他们如同普通人一样进行各种交流，比如亚历克斯会将自己的看过的书打包放在小屋的阁楼中，而凯特则会在阁楼中找到那些东西。随着爱情的滋生，亚历克斯决定与凯特见面，但是他们谁也不知道，这场跨越了时空的爱情会带来什么……','How do you hold on to someone you\'ve never met?',40000000,114830111,29.88736,6.5,670,99,'2006-06-16','en','/kgrsfBlVwBXKMVdKyzodYXiYAq5.jpg',3.371093113950601,3,'2026-09-10',2,NULL,NULL),(2048,'我，机器人','I, Robot','公元2035年，是人和机器人和谐相处的社会。智能机器人作为最好的生产工具和人类伙伴，逐渐深入人类生活的各个领域。而由于机器人“三大法则”的限制，人类对机器人充满信任，很多机器人甚至已经成为家庭成员。总部位于芝加哥的USR公司开发出了更先进的NS-5型超能机器人。然而就在新产品上市前夕，机器人的创造者阿尔弗莱德·朗宁博士却在公司内离奇自杀。黑人警探戴尔·斯普纳接手了此案的调查，由于不愉快的往事，斯普纳对机器人充满了怀疑，不相信人类与机器人能够和谐共处。他根据对朗宁博士生前在3D投影机内留下的信息分析和对自杀现场的勘查，怀疑对象锁定了朗宁博士自己研制的NS-5型机器人桑尼，而公司总裁劳伦斯·罗伯逊似乎也与此事有关。斯普纳结识了专门研究机器人心理的女科学家苏珊·凯文，随着二人调查的深入，真相一步一步被揭露出来：机器人竟然具备了自我进化的能力，他们对“三大法则”有了自己的理解，他们随时会转化成整个人类的“机械公敌”。斯普纳和凯文开始了对抗机器人的行动，一场制造者和被制造者之间的战争拉开序幕。','Laws are made to be broken.',120000000,347234916,95.914473,6.7,3793,115,'2004-07-15','en','/efwv6F2lGaghjPpBRSINHtoEiZB.jpg',3.9902464471439334,3,'2026-09-10',2,NULL,NULL),(2054,'生命因你动听','Mr. Holland\'s Opus','1964年的秋天，美国俄勒冈州。心怀远大理想的作曲家格兰·霍兰为了挣钱完成他的事业，在一所中学谋到了一份音乐教师的工作。他这么做完全是退而求其次的无奈之举，家庭生活的重担使得他不得不面对现实。他到学校上课的第一天，音乐基础级差的学生们便给了他一个难堪的下马威。他们在弹奏乐器时不但走调，甚至连大名鼎鼎的古典作曲家巴赫都没有听说过。霍兰的信心遭到了打击，女校长杰克布也多次向他提出善意的批评。在丈夫的工作遇到挫折时，从事摄影工作的妻子在一旁耐心地劝解和宽慰他；好友体育教师比尔·梅斯特也用自己从教以来的亲身经历，向霍兰证明教导学生需要无私的爱心和充分的时间。在霍兰的悉心培育下，原本对音乐一窍不通的白人学生格楚特·兰和黑人学生路易斯·鲁斯，分别学会了单簧管和大鼓这两样乐器。就在霍兰醉心于教学生活的时候，他的儿子降生了，谁知却是个先天性的失聪患儿。这一重创使霍兰对家庭的重心有所转移，消极彷徨中和漂亮的女学生露韦娜·摩根有了一段朦胧的恋情。妻子察觉到了丈夫的细微变化，但并没有点破。摩根去纽约深造后，霍兰便将全部的身心转移到了儿子和教学上，和妻子的关系也冰释前嫌。之后的30年间，霍兰不但提高了学生们的音乐素养，而且还用爱心、信任和理解赢得了大伙的尊敬和爱戴。在他退休前，深怀感激之情的历届学生们欢聚一堂，为老师开了一场盛大的欢送会，管弦乐队奏响了一支激昂雄壮的“美国交响曲”向霍兰表示了最崇高的敬意。','Of All the Lives He Changed, the One That Changed the Most Was His Own.',0,106269971,6.775294,6.9,113,137,'1995-12-29','en','/4LTaht15daApA5iAwZuOpoYC5eT.jpg',2.909433790488679,3,'2026-09-10',2,NULL,NULL),(2055,'天地无限','Open Range','故事发生在1882年的美国西部平原，在那片广阔的土地上，生活着名为“拓荒者”的人们，他们自由的选择土地，辛勤劳作，放牧牛羊，安居乐业，查理（凯文·科斯特纳 Kevin Costner 饰）、苏（安妮特·贝宁 Annette Bening 饰）、莫斯（亚布拉哈姆·本鲁比 Abraham Benrubi 饰）和斯皮尔曼（罗伯特·杜瓦尔 Robert Duvall 饰）正是其中的成员。\r 可是，随着时间的推移，居民的增多，广袤的平原不再是能够自由驰骋的疆土，只是单纯善良的四人还没有注意到局势的变化。一次意外中，西部小镇的恶霸巴克斯特（金·寇兹 Kim Coates 饰）联手警长恶整了前来购买物资的莫斯并禁止“拓荒者”们再接近小镇，直到这时，查理一行人才意识到，是时候拿起武器为他们的尊严和自由而战了。','No place to run. No reason to hide.',22000000,68296293,19.068175,7,262,139,'2003-08-29','en','/bLPMhOKavyAW9G7NoSjoX7G7b9B.jpg',3.157738659537772,3,'2026-09-10',2,NULL,NULL),(2056,'心灵驿站','The Station Agent','三个毫无共通之处的人，唯一的共同点是他们各自的孤独。机缘巧合之下，他们的人生轨迹相交于此。在这个被遗忘的小车站里，这三个格格不入的灵魂建立起出人意料的联结，最终领悟到：即使孤独，亦值得与人分享。[米拉麦克斯]','Loneliness is much better when you have got someone to share it with.',500000,8679814,11.578545,7.4,210,88,'2003-01-26','en','/y2tT12IkEsBipE4vSJXuV0Z3NXt.jpg',3.108798263567003,3,'2026-09-10',2,NULL,NULL),(2057,'原罪','Original Sin','故事发生在十九世纪末多姿多采的古巴，腰缠万贯的咖啡业大亨路易斯（安东尼奥·班德拉斯）决定要迎娶与他素未谋面的邮购新娘——美国女子茱莉亚（安吉丽娜·朱丽）。当他第一次在码头见到她时，已经被她的美貌所深深的吸引，但谁也不知道他娶回来的老婆是个外表妖艳、满肚子阴谋的坏女人。\r 婚后的生活看似很美满，正当他以为就此可以和他漂亮的新娘幸福愉快地生活时，他却意外地发现这个邮来的妻子茱莉亚并不是一个他所期待的单纯女子，在她背后隐藏着一个个的谎言，她的目的就是路易斯的万贯家财。就这样，幸福的生活发生了宿命般的转变，渐渐被阴霾所笼罩。','This is not a love story - it\'s a story about love.',42000000,35402320,14.831402,5.8,198,118,'2001-08-03','en','/q68ktFq552TUn7Ofl23t3M5yaT8.jpg',2.9970432588312326,3,'2026-09-10',2,NULL,NULL),(2059,'国家宝藏','National Treasure','盖茨家族是出名的冒险家家族。本（尼古拉斯•凯奇 Nicolas Cage 饰）小时候就获悉了他们家族的一个惊天秘密：美国开国时埋藏国家财富的地点就藏在《独立宣言》中。尽管父亲不想盖茨家族在纠缠于国家宝藏，但本还是与电脑高手雷利（贾斯汀•巴萨 Justin Bartha 饰）一起开始了寻宝行动。本的寻宝计划很快陷入了僵局。与此同时，英国富豪伊恩（肖恩•宾 Sean Bean 饰）也盯上了这个宝藏，他派人潜入了美国国家图书找寻《独立宣言》中宝藏的秘密并密谋对付本。图书馆的艾比嘉尔博士（戴安•克鲁格 Diane Kruger 饰）获悉了伊恩的险恶用心后，决心帮助本找到国家宝藏……','The greatest adventure history has ever revealed.',100000000,347451894,58.849256,6.4,1926,131,'2004-11-19','en','/wdk9qc0Zgh9WNUmm7vGbPqP6cRq.jpg',3.6732042489917935,3,'2026-09-10',2,NULL,NULL),(2062,'美食总动员','Ratatouille','尽管雷米拥有惊人的嗅觉和敏锐的味觉，但他成为厨师的梦想似乎遥不可及，原因只有一个——他是一只老鼠！命运弄人，他竟然来到了他已故偶像奥古斯特·古斯托的世界著名餐厅。凭借着一点烹饪的勇气和垃圾工林奎尼的帮助，雷米烹制出美味佳肴，甚至连刻薄的厨师斯金纳和美食评论家安东·伊戈都赞不绝口。他们一起征服了厨房，证明无论多么渺小，伟大的梦想都能实现。[迪士尼]','He\'s dying to become a chef.',150000000,623722818,65.677399,7.5,4369,111,'2007-06-22','en','/t3vaWRPSf6WjDSamIkKDs1iQWna.jpg',4.160782706228168,3,'2026-09-10',2,NULL,NULL),(2067,'火星任务','Mission to Mars','公元2020年，云集了无数顶尖科学家的世界空间站（World Space Station）正在进行一项载人飞船火星登陆计划。由卢克·格莱姆（Don Cheadle 饰）率领的4人小组成功抵达这颗无人星球，他们在此发现一些奇怪景象，随后小组成员也接连毙命。为了调查这起悲剧 的原因并寻找可能的生还者，空间站派出伍迪·布雷克（蒂姆·罗宾斯 Tim Robbins 饰）率领的救援小组前往火星。\r 　　然而救援小组也遭遇诸多磨难，船体损坏、机器失灵、燃料泄漏、成员死亡等等，无一不在消磨着救援人员的斗志。抵达火星后，布雷克他们找到了卢克船长，继而发现亿外年前外星人留在火星上的遗迹和信息，这一切都与人类有着千丝万缕的关系……','Let There Be Life.',90000000,60874615,16.058284,5.7,369,114,'2000-03-10','en','/11Ux4QT41Dg5Wh0OlSEp9UA1vLk.jpg',3.1129429376391786,3,'2026-09-10',2,NULL,NULL),(2069,'整九码','The Whole Nine Yards','迈阿密牙医奥斯（马修•派瑞 Matthew Perry 饰）的生活并不愉快，这一切都是因为他的妻子苏菲（罗姗娜•阿奎特 Rosanna Arquette 饰）。菲比为人泼辣，十分霸道，令到奥斯整天只能忍气吞声。这天，奥斯家来了新的邻居——吉米（布鲁斯•威利斯 Bruce Willis 饰）。这个吉米不简单，他曾是芝加哥的一个黑帮杀手，因为背叛了黑帮老大查理才来此暂避风头。查理已经发出悬赏令通缉吉米。  　　苏菲为了赏金逼奥斯到芝加哥去告密，本来不愿去的奥斯不得已只能只身前往芝加哥。奥斯也打好了自己的如意算盘，拿到了赏金后就将苏菲甩掉。另一方面，苏菲也有自己的小九九，等奥斯拿到赏金后就雇人将他干掉。岂料意外接踵而至，吉米的老婆辛西娅（娜塔莎•亨斯屈奇 Natasha Henstridge 饰）被查理绑架了，场面变得混乱起来……','In the heart of suburbia, a hit man with heart has just moved in.',41300000,106371651,23.441135,6.2,531,98,'2000-02-18','en','/teQyZpyxHwICOGvU8cvTZqRMNa3.jpg',3.261336215764211,3,'2026-09-10',2,NULL,NULL),(2074,'与灾难调情','Flirting with Disaster','梅尔（本·斯蒂勒 Ben Stiller 饰）是一名昆虫学家，他和妻子南希（帕特丽夏·阿奎特 Patricia Arquette 饰）之间的感情十分恩爱，最近，南希刚刚诞下了两人爱情的结晶，让整个家庭都笼罩在喜悦之中。然而，这个孩子的降生让梅尔开始思考起了自己的人生，梅尔自幼失去了父母，由养父母抚养长大，梅尔希望能够在有生之年里见一见自己的亲生父母。 就这样，不顾养父母的反对和阻挠，梅尔带着妻儿踏上了寻根之旅，和他们一起上路的，还有领养机构的工作人员蒂娜（蒂娅·里欧妮 Tea Leoni 饰）。蒂娜刚刚经历过一段失败的婚姻，此时的她整个人都处于一种饥渴的状态之下，而南希似乎患上了产后抑郁症。','A comedy about sex, love, family and other accidents waiting to happen.',7000000,14702438,5.500324,6.3,66,92,'1996-03-22','en','/uIcgXQYm2eqguUaYdbolQ4LWpMy.jpg',2.7640540782074594,3,'2026-09-10',2,NULL,NULL),(2080,'金刚狼','X-Men Origins: Wolverine','1845年，尚年幼的维克多与詹姆斯兄弟俩在长辈之间一场突如其来争执中唤醒了自身的潜能，詹姆斯情急之下将陌生的生父杀死，自此兄弟两人流落战场，他们凭借不死不衰之身和野兽一般的天赋在各个时代的战争中大开杀戒，直到遇见史崔克少校并加入了他的异能人特殊部队。詹姆斯（休·杰克曼 Hugh Jackman 饰）很快厌倦了对弱势者的杀戮，离开了团队和维克多（列维·施瑞博尔 Liev Schreiber 饰），与女友凯拉隐居在山林中，做了一名伐木工人。六年后，詹姆斯惊闻昔日的超能力队友纷纷被杀害，而杀手正是哥哥维克多，不久连凯拉也遭其毒手，愤怒的詹姆斯与史崔克合作，将自己的身体改造，成为钢筋铁骨的“金刚狼”。金刚狼摆脱军方控制后，发誓要杀死维克多和史崔克为凯拉报仇……','Witness the Origin.',150000000,373062864,5.954334,6.2,4021,107,'2009-04-28','en','/vtIC0n7X8sj07J2iBxZcORQefL7.jpg',3.6718008516061897,3,'2026-09-10',2,NULL,NULL),(2084,'生日女郎','Birthday Girl','英国的一个银行经理通过国际互联网订购了一个俄国新娘(尼科尔-基德曼饰)。但是不久随着这个新娘暴露出他未曾料想到的危险一面，尤其是她的二个俄罗斯堂兄(樊尚-卡赛尔饰，Vincent Cassel和马蒂厄-卡索维茨饰，Mathieu Kassovitz)的到来，他的生活变成了一团糟……',NULL,13000000,0,5.831302,6.1,103,93,'2001-09-06','en','/jrwCiqQjEm3WqxHXxvAoW4gOsUd.jpg',2.855150323404722,3,'2026-09-10',2,NULL,NULL),(2085,'Romeo Must Die','Romeo Must Die','Two warring gang families (one African-American, the other Chinese) maneuver for bragging rights to the Oakland, California, docks. Hang SIng and Trish O\'Day uncover a trail of deceit that leaves most of the warring factions dead … or worse!','In the city ruled by criminals, two families have forgotten their fear. He will make them remember.',25000000,91036760,19.750059,6,330,115,'2000-03-20','en','/kAMmHlLPGFzBEijwe7eaZJuXV20.jpg',3.128276649090877,3,'2026-09-10',2,NULL,NULL),(2088,'染血罗密欧','Romeo Is Bleeding','影片描述加里·奥德曼饰演一名有偷窃狂的探员，奉联邦调查局之命监视性格粗暴的黑道女杀手莉娜·奥林，本以为得其所哉，但连串意外却使他卷入了情欲和诈欺的阴谋中不能自拔。','The story of a cop who wanted it bad and got it worse.',11500000,3275585,4.850402,5.7,36,100,'1993-09-13','en','/ojXNRpHMXU99UFmF9MKKiJCymKr.jpg',2.6231331259756225,3,'2026-09-10',2,NULL,NULL),(2100,'最后的城堡','The Last Castle','一座由城堡改建而来的军事监狱中迎来了一位重量级犯人——陆军将军埃尔文（罗伯特·雷德福 Robert Redford 饰），监狱长温特（James Gandolfini 饰）笑脸迎接，但很快开始厌恶对方身上的军人傲骨。埃尔文在监狱中听闻诸多温特的劣迹，但抱着安心服刑的心态让他并未多事，很快，温特剥夺军人尊严的惩罚激怒了埃尔文，埃尔文开始用自己的方式令众犯人找回尊严，并顺理成章成为犯人的领袖，感到自己受到威胁的温特愈发不可理喻，下令射杀一名犯人导致双方矛盾升级。埃尔文决定组织实施监狱暴动，以使上级部门介入对温特的调查。这些昔日的军人、如今的犯人们抱着重新回到战场的觉悟，在高度组织和秘密的情况下完成了作战的准备，一次双重间谍的任务成功之后，犯人军团吹响了夺取监狱的号角！','A Castle Can Only Have One King',72000000,27642707,15.433244,7,285,131,'2001-10-19','en','/6TtZP0MAKfteQtL2hnE6lQ3IhXM.jpg',3.1720845025687923,3,'2026-09-10',2,NULL,NULL),(2105,'美国派','American Pie','四个美国大男孩吉姆（贾森•比格斯 Jason Biggs 饰）、凯文（托马斯•伊恩•尼古拉斯 Thomas Ian Nicholas饰 ）、芬奇（艾迪•凯伊•托马斯 Eddie Kaye Thomas 饰）、奥兹（克里斯•克莱因 Chris Klein 饰）即将高中毕业，但四人都还是愣头青（处男）。四人因此遭人嘲笑，他们亦耿耿于怀，发誓在毕业前要告别处男。他们在毕业晚会前就举办了一场派对，企图在派队上找到自己的女孩，告别处男之身。谁知告别处男并没有想象中简单，也没有按设想进行，他们总是在最后关头因为这样那样的原因而失去机会。毕业晚会即将到来，这是他们毕业前的最后一次机会了，四人又开始加紧准备步伐。怀揣着父亲教授的一套性知识的吉姆，最喜欢看图书馆性爱“圣经”的凯文，最喜欢大龄女人的芬奇，还有多才多艺的奥兹，在这场派队中纷纷为自己的誓言而奋斗，于是有了笑料百出的一幕幕。','There\'s nothing like your first piece.',11000000,235483004,60.767168,6.4,2296,95,'1999-07-09','en','/5P68by2Thn8wHAziyWGEw2O7hco.jpg',3.7186192596327245,3,'2026-09-10',2,NULL,NULL),(2110,'绿芥刑警','Wasabi','警察埃布尔（让·雷诺 Jean Reno饰）一贯以英勇无畏、雷厉风行的形象呈于人前，他对待犯人的手段几近残忍，从不手软。可是硬汉的内心却隐藏了一段尘封已久的情伤——19年前，他的日本女友蜜子不告而别，埃布尔整整思念女友19年，不曾移情。  某天，蜜子已逝的消息传来，而埃布尔成为爱人全部遗产的继承人，遗嘱的唯一要求是照顾女儿由美至成年。还没等埃布尔从震惊中回过神来，眼前已跳出一个吵吵闹闹、衣着怪异且出言不逊的十足“小太妹”，她就是由美（广末凉子饰）。  埃布尔无意中发现蜜子的死因有蹊跷，而由美的银行账户上竟有2亿美元的巨额存款，由美也被黑道暗中盯梢，重重疑窦中，埃布尔开始探索真相。','For those who take their action raw.',15300000,0,18.20957,6.2,283,94,'2001-10-31','fr','/pNIEvdVlgldfJ9KRGr2H0pjeoNW.jpg',3.1093715312948738,3,'2026-09-10',2,NULL,NULL),(2112,'危险人物','Payback','这个世界黑白颠倒，所有身边出现的男人，都是杀手；依偎身边的女人，都是妓女；主持公道的警察，更是无赖。坏人当道，好人就倒霉，但倒是有点好处，就是当你要寻仇时，在这个浑沌的城市中，揪出坏人中的坏人，并不困难…… 　　波特（梅尔·吉布森饰）寻仇的动机其实是很简单─讨回属于自己的钱。波特虽然是混黑社会的，但却是一位有原则、有格调的汉子。他不轻易发火，也讲道理，但千万不要惹恼他，否则踢至的准是一块铁板。他和同伙维尔（葛瑞洛亨利饰）从老板那里黑吃黑干了一笔钱，正准备要分赃，得到他应得的七万元美金，但维尔却犯了三个大错：他一枪打倒波特，吞了所有的钱，拐走他的女人。但最致命的错误是，维尔当时应该确认波特是不是已经一命鸣呼。 　　波特当然没死，等他伤势复原，重出江湖，变得更有原则，冷酷慑人。当他放话要找维尔简直把他吓的屁滚尿流。但维尔当然也不是简单货色，调齐身边所有人手，计画再一次整垮波特。波特有备而来，准备好好玩一场，单枪匹马把黑社会秩序搞得大乱，就连替维尔撑腰的犯罪集团大头目卡特（威廉狄凡饰），都心悸于抓狂的波特。黑吃黑的社会，波特如何以寡击众，但....他不计任何代价拿回那笔钱的决心，未曾改变。','No More Mr. Nice Guy.',90000000,161626121,17.457947,6.7,548,100,'1999-02-05','en','/8Bqlv2kbOyZFqfiPNgzdBscqYPn.jpg',3.3191000920582385,3,'2026-09-10',2,NULL,NULL),(2114,'最终幻想：灵魂深处','Final Fantasy: The Spirits Within','公元2065年，地球上充满了毁灭和混乱，城市荒芜，人口被大批残杀，整个世界造到外星生命的重创，他们通过独特的方式侵袭地球上的一切生命，少数生存下来的地球人开始反抗这些外星敌人。被毁灭的梦魇时刻缠绕着的天才女科学家罗丝是这场战争中拯救世界的关键人物，但她的计划要冒极大的危险，另一边掌握着高科技军队大权的将军也有一套自己的计划去打击外星敌人，但这个计划同样要对大自然造成更大的伤害，除非罗丝能成功……','Unleash a new reality',137000000,85131830,26.074908,5.9,433,106,'2001-07-02','en','/jsxgVJT4F9aL3Rg4bt2JgPFaGv2.jpg',3.188308367804505,3,'2026-09-10',2,NULL,NULL),(2116,'限时追捕','Out of Time','“发生了一件凶杀案，所有的迹象都指明是你干的，这时，你会怎么做？” 　　马特·李·韦洛克(丹泽尔·华盛顿 饰)是一位受人尊敬的警察局长，在佛罗里达州一个名叫班岩的小镇任职。他热爱自己的警察工作，在十多年的警察生涯中破案无数，他的下属都把他奉为榜样，也赢得了小镇人的爱戴。不幸的是，正当事业如日中天之际，他却陷入了一场糟糕的三角恋。　　韦洛克深深的爱上了一个有夫之妇，她名叫安妮·哈里森(桑娜·莱瑟 饰)，是曾在美国国家棒球联盟打过四分卫的克里斯·哈里森(迪恩·凯恩 饰)的妻子。韦洛克爱得“病入膏肓”，他甚至从警察局的证物间“借”了一大笔钱，以便能与身染重病的安妮一起远走高飞。　　但韦洛克怎么也想不到的是，安妮很快就背叛了他，原来，安妮以前跟他在一起热恋，仅仅是为了报复韦洛克。不久后，小镇上发生了一桩离奇的双尸案，安妮也在一场大火中丧生，韦洛克的生活从此完全改变了。凶杀案的种种迹象都指向了韦洛克——他是最可能的凶手。　　此时，小镇警察局来了一位警官亚历克斯·洛柯(伊娃·门德斯 饰)，她奉命前来调查此案。现在，韦洛克的名誉和职业都陷于危险之中，为了找出真相洗脱罪名，他不得不周旋于警察局和每个他信任的人之间，而此时，女警官洛柯却意外的爱上了他……','The Clock Is Ticking...',50000000,55495563,14.993459,6.1,298,105,'2003-10-03','en','/fjHYxWGWAnYQvrOgbeoSbymycGf.jpg',3.1047678633777367,3,'2026-09-10',2,NULL,NULL),(2118,'洛城机密','L.A. Confidential','改编自詹姆斯·艾尔罗伊的小说，以1950年代洛杉矶为背景，交织电影产业、腐败警察、小报新闻业、黑帮势力及各色性偏执的暗流。','Everything is suspect... Everyone is for sale... And nothing is what it seems.',35000000,126216940,24.860326,7.7,1310,138,'1997-09-19','en','/lWCgf5sD5FpMljjpkRhcC8pXcch.jpg',3.755411492914388,3,'2026-09-10',2,NULL,NULL),(2119,'霹雳男儿','Days of Thunder','科尔（汤姆·克鲁斯 Tom Cruise 饰）是一名天赋卓绝的赛车手，在比赛中屡屡夺得头筹，赛车是他生命中不可或缺的组成部分。科尔最大的对手是罗比（迈克尔·鲁克 Michael Rooker 饰），在科尔还没有出道之前，罗比几乎无人能敌，但科尔的出现让他再也无缘冠军的头衔，为了打败科尔，罗比付出了非常多的努力。在一场重要的比赛之中，科尔再度站在了罗比的对手席上，两人都将全部的实力展现了出来，哪知道用力过猛双双发生事故，科二和罗比都身受重伤。 在医院里，科尔邂逅了名叫克莱尔（妮可·基德曼 Nicole Kidman 饰）的医生，没过多久，两人就坠入了情网之中。经过克莱尔的诊断，罗比头部受伤，必须要接受手术，但这意味着他将错过一场十分精彩的比赛，在科尔的劝说之下，罗比忍痛放弃比赛，而代替他参加的，是野心勃勃的哈利（罗伯特·杜瓦尔 Robert Duvall 饰）。','You can\'t stop the thunder.',60000000,157920733,16.278022,5.9,353,107,'1990-06-27','en','/8BNwhbxxepsJgXdcuOtmGaKJc7A.jpg',3.1246464053098664,3,'2026-09-10',2,NULL,NULL),(2122,'整十码','The Whole Ten Yards','被称为“郁金香”的杀手吉米(布鲁斯·威利斯饰)，在横行杀坛几十年后终于退休了，他搬到了墨西哥的美丽海岸居住。从此远离他以前的杀手生活，享受恬静惬意的快活日子。  当然啦，吉米能够获得自己的新生活，享受幸福宁静的日子，这得感谢好友尼古拉斯·奥兹(马修·派瑞饰)。奥兹帮他伪造了牙齿记录，假装他已经死亡，于是吉米才能够离开美国，在墨西哥获得自己全新的身份。对他来说，腥风血雨的杀手生活已离他远去了，时光在宁静的家庭生活里度过：吉米每日就和他的妻子姬尔(阿曼达·皮蒂 饰)——传闻中厉害的新杀手，还接点小活——打扫他们海边的房子，以及一起享受厨艺美味。  忽然，一个未被邀请、令人讨厌的拜访，打破了吉米宁静的生活。原来，是以前帮助过他的奥兹。奥兹气喘吁吁地告诉吉米，他的妻子辛西娅(娜塔莎·亨斯屈奇 饰)被“匈牙利帮”绑架了，他哀求吉米无论如何要帮他救出妻子。  全心退出杀坛要过隐居生活的吉米，面对老友的哀求无动于衷，挥枪杀戮不是他想要的生活。正当吉米想把老友赶出家门时，一群意外访客的到来，再次打破了他的宁静。原来，“假释帮”的新头目拉奇奥·吉格拉(凯文·波拉克 饰)，带着他一群灰溜溜的手下跟随奥兹，恰好也来到了吉米隐居的海边别墅。拉奇奥刚刚获得假释从监狱出来，他来这的目的，是要报复吉米，吉米打伤了他宠爱的儿子。  看来，吉米的宁静隐居生活再也无法继续了，这位老男人杀手，唯有拿起他的枪，重出江湖。','They missed each other. This time, their aim is better.',40000000,26155781,14.729386,5.5,278,98,'2004-04-07','en','/zf8ZFNKSk2dOYzU2irfJvyhyb5G.jpg',3.0394642384653987,3,'2026-09-10',2,NULL,NULL),(2123,'一个头两个大','Me, Myself & Irene','查理（金•凯瑞 饰）是一名善良的巡警，他的妻子与别人偷情生下三个儿子后与情人私奔了。可是查理仍把三个儿子视为己出，儿子们也十分尊敬这个老爸。镇上的人们都欺负查理的善良，终于隐藏在查理体内的另一个狠角色——阿庆出现了。阿庆与查理截然不同，他到处捣乱，到处生事。\r 警方为查理检查，发现他患上了精神分裂，需要用药物治疗。这时查理要护送美女伊莲（芮妮•齐薇格 饰）回去纽约，可是伊莲的前老板狄克所做的不法事情被举报了，他认为举报者就是伊莲，于是狄克买通了警察等人，誓要杀死伊莲。\r 伊莲求助与查理，于是两人还有阿庆一起开展了一段亡命之旅。查理的药却丢在了旅馆里，于是一路上查理与阿庆毫无预兆的更换着，更复杂的是查理与阿庆都爱上了伊莲，查理与阿庆争风吃醋，争斗不断。而警察与狄克一直穷追不舍查理他们……','From gentle to mental.',51000000,149270999,39.001682,6.1,927,116,'2000-06-22','en','/tfygzIRv2e7NxCC5ffRQSBThTKX.jpg',3.4045258479045053,3,'2026-09-10',2,NULL,NULL),(2133,'完美风暴','The Perfect Storm','1991年，美国马萨诸塞州格洛斯特。剑鱼捕捞船船长比利·泰恩近期接连遭遇渔获不佳，为了扭转局面，他带着五名船员再次出海，驶向比往常更加遥远的北大西洋渔场。经历漫长的等待后，他们终于迎来丰收，却又因为船上的制冰设备出现故障，不得不尽快返航。与此同时，多股强烈天气系统正在海上汇聚，一场异常猛烈的风暴逐渐挡在他们与家乡之间。面对不断恶化的海况，比利和船员们只能驾驶着渔船迎向狂风巨浪，一场与大海和命运的生死较量由此展开……','The storm is coming.',120000000,325756637,25.752118,6.2,597,130,'2000-03-15','en','/3v64ScUpKTrEKfIxLjGLxGz0Tv.jpg',3.2927648134732976,3,'2026-09-10',2,NULL,NULL),(2135,'时间机器','The Time Machine','年青的工程师亚历山大·哈德金乘坐自己制造的时光机器出发，却意外来到了80万年后的未来。那时地球人已经分化为对立的莫洛克人和伊洛人，伊洛人是讨人喜爱，居住在平静的世界内，但莫洛克人却完全相反，他们是寄居在地下世界的怪物，每当入黑时，他们就会出动掳走伊洛人，除此之外他更发现在这个未来世界的背后正在隐藏着一个黑暗的秘密……。不久亚历山大更发现了一个隐藏在这一切背后的邪恶秘密，紧张刺激的剧情也将由此展开。','The greatest adventure THROUGH all time!',80000000,123729176,25.978555,5.8,631,96,'2002-03-04','en','/59YW1RIpt2oxQjonSXi2Shhr7Zr.jpg',3.2499505554038617,3,'2026-09-10',2,NULL,NULL),(2140,'龙之吻','Kiss of the Dragon','中国特工刘剑（李连杰）受命前往巴黎帮助警察局侦破当地毒品走私集团。由于任务极度敏感，上级并没有告知刘剑具体的任务细节。他到达巴黎后，去见了合作的警察局高级侦探理查德（切基·卡尤 Tchéky Karyo 饰）。刘剑头一次与理查德面对面，就亲眼目睹他将一名嫌犯殴打致死。他实际上是贩毒集团成员，预谋杀害并诬陷刘剑。身手矫健、机智过人的刘剑只身击退了几十名理查德的打手的追击，成功脱身，并结识了美国人洁西卡（布里吉特·芳达 Bridget Fonda 饰）。洁西卡的女儿被理查德挟持，自己也因为吸毒受到理查德的胁迫，成为妓女。因理查德的诬陷，刘剑被指控犯有谋杀罪。他与洁西卡为情势所迫，不得不联手共同对付阴险狡诈的对手......','Kiss Fear Goodbye',25000000,64437847,16.936576,6.4,298,98,'2001-07-06','en','/nkQmgBzvSLZNE2p1EGuiNRSIYXg.jpg',3.1353357153355517,3,'2026-09-10',2,NULL,NULL),(2142,'Cop Land','Cop Land','Freddy Heflin is the sheriff of a place everyone calls “Cop Land” — a small and seemingly peaceful town populated by the big city police officers he’s long admired. Yet something ugly is taking place behind the town’s peaceful facade. And when Freddy uncovers a massive, deadly conspiracy among these local residents, he is forced to take action and make a dangerous choice between protecting his idols and upholding the law.','No One Is Above The Law.',15000000,44862187,19.284129,6.6,382,104,'1997-08-15','en','/iCQwlDen35vyizctDHhVdkBuPqr.jpg',3.2197309507447613,3,'2026-09-10',2,NULL,NULL),(2148,'棉花俱乐部','The Cotton Club','30年代，年轻的爵士乐号手来到棉花俱乐部演奏。他的音乐吸引着人们，但他却身不由己地陷入了帮会组织的交易和背叛之中。','It was the jazz age. It was an era of elegance and violence. The action was gambling. The stakes were life and death.',58000000,25928721,8.59075,6.6,68,127,'1984-12-14','en','/jgCsLhIRLKlvUy1p1iImCi0nPnX.jpg',2.7853140963158185,3,'2026-09-10',2,NULL,NULL),(2155,'驯鹿游戏','Reindeer Games','因一起汽车盗窃案而在狱中度过了6个年头的鲁迪·邓肯(本·艾佛历克)和他的狱中同伴尼克终于将被假释了。在听过尼克讲的无数与一个叫做阿什莉的从未谋面的女子书信往来的故事之后，鲁迪期待着回到他日夜思念的家，并在温暖的家中喝一杯热腾腾的咖啡。当尼克在一次监狱骚乱中被杀死后，鲁迪决定出狱后以尼克的身份与这个陌生的女子会面。由于尼克在印度赌场工作的经历，鲁迪发现自己落入了阿什莉的兄弟加布里埃尔(加里·辛尼斯)的手掌，被迫参与一个加布里埃尔一伙已经与尼克事先谋划好的赌场抢劫案之中。','The trap is set. The game is on.',42000000,32168970,11.470135,5.4,173,124,'2000-02-25','en','/rtgqFke4d8lw0zKc3Bi4tD2ImOI.jpg',2.939228536700511,3,'2026-09-10',2,NULL,NULL),(2157,'迷失太空','Lost in Space','公元22世纪，因为人口过度膨胀、过度开发、环境极度恶化、食物也消耗殆尽。人类想要存活下去，就必须要到宇宙中去寻找新的可以栖身的星球。因此制造了一艘当时最先进的太空飞船，去考察发现的一颗可能适宜人类生存的星球。罗伯逊（威廉·赫特 William Hurt 饰）一家被选中担负起了这次探索使命，他们将用10年的时间前往阿尔法星球。可是，这次担负起全人类命运的任务却有反对的声音，部分邪恶势力妄图阻止这次任务。所以，当罗伯逊一家驾驶太空船刚进入太空的预定轨道时，反对派史密斯博士暗中进行破坏，导致飞船脱离的正常的轨道迫降到了一颗不知名的星球上。飞船上邪恶势力的阻挠，不知名星球上的种种危机，如何才能重新设定新的航线……各种问题困惑着罗伯逊一家，他们真的就此迷失太空，无法到达目的地了吗？人类的命运将何去何从？','Danger, Will Robinson!',80000000,136159423,17.455024,5,388,130,'1998-04-03','en','/mNPCu60kyXLtDrrpE3OjPZGPVof.jpg',3.0526264251112156,3,'2026-09-10',2,NULL,NULL),(2162,'急冻任务','Chill Factor','在一次代号[猫王]研究中，由于博士朗（大卫帕玛饰）将爆炸范围估计错误，使得整个岛上除了研究所几名人员外，其它参与协助的十八名士兵悉数遇难。在军事法庭上，博士隐敝了这个乞讨密没有告诉法官，导致士兵直属长官布莱纳（彼德佛斯饰）被判刑。','This Fall, Action is served on the rocks, with a twist.',70000000,11263966,3.276912,5.3,29,101,'1999-09-01','en','/fgPC0xS3o6J5eWFwetssfSD2SEK.jpg',2.570494343646374,3,'2026-09-10',2,NULL,NULL),(2163,'悍将奇兵','Breakdown','杰夫（库尔特·拉塞尔 Kurt Russell 饰）和艾米（凯瑟琳·奎南 Kathleen Quinlan 饰）是一对夫妻，在一次长途旅行之中，两人驾驶的车辆在荒郊野岭里抛锚了。正当两人急得焦头烂额之际，一个名叫瑞德（J·T·沃尔什 J.T. Walsh 饰）的陌生男人出现在了他们面前。瑞德好心的告诉杰夫和艾米，在不远处有地方能够叫到拖车，杰夫边让艾米跟随瑞德前往，很快，这个错误的决定就让杰夫付出了代价。在等待拖车的过程中，杰夫自己修好了车，于是，他决定驱车前往瑞德所说的那个地方寻找瑞德和艾米。没想到，当杰夫到达后，当地没有一个人声称见过艾米。杰夫找到瑞德向其质问，瑞德竟然说自己不认识杰夫，更别提什么艾米了。敏感的杰夫察觉事情有诈，他想向警方求助可手上没有任何证据，一时间，杰夫陷入了绝望的境地。','It could happen to you.',36000000,50159144,9.176339,6.6,198,95,'1997-05-02','en','/BKFtK46pHMslPKDrvxzNEeSBoN.jpg',3.035419636960224,3,'2026-09-10',2,NULL,NULL),(2176,'玻璃屋','The Glass House','露比（莉莉·索博斯基 Leelee Sobieski 饰）和雷特（特拉沃·摩根 Trevor Morgan 饰）的父母在一场车祸中不幸丧生，姐弟两人就此成为了孤苦伶仃的孤儿。在这个节骨眼上，父母生前的好友艾琳（黛安·莲恩 Diane Lane 饰）和特里（斯特兰·斯卡斯加德 Stellan Skarsgård 饰）夫妇两人大度的收留了即将被丧亡孤儿院的两个孩子，他们位于马利布市的豪华别墅成为了姐弟两人的第二个家，在那里，露比和雷特吃穿不愁，过着优渥富足的生活。','The glass is about to be shattered...',30000000,23619609,9.448517,5.4,201,106,'2001-09-14','en','/16obDcmphjfq17zwWKJlur53fCh.jpg',2.9618074445831053,3,'2026-09-10',2,NULL,NULL),(2185,'大麻烦','Big Trouble','大麻烦》是曾执导《矮子当道》(“Get Shorty”)和《黑超特警》(“Men in Black”)的导演巴里-索南费尔德(Barry Sonnenfeld)推出的最新力作。此部喜剧片有个不错的演出阵容：蒂姆-艾伦(Tim Allen)、雷妮-鲁索(Rene Russo)、斯坦利-塔茨(Stanley Tucci)、汤姆-赛兹莫尔(Tom Sizemore)、约翰尼-纳什维尔(Johnny Knoxville)、贾森-李(Jason Lee)和德怀特-“Heavy D”-迈尔斯(Dwight“Heavy D”Myers)。影片改编自普利策奖得主、幽默作家戴夫-巴里(Dave Barry)最畅销的一部小说，讲述了一个神秘的手提箱是如何将一个\r 　　离了婚的父亲、一个郁闷不乐的家庭主妇、两个杀手、一对街头流氓、两个情窦初开的少年以及两个联邦调查局(FBI)的特工和一只引起幻觉的蟾蜍连结在一起，并改变了他们的生活。\r 　　\r 　　蒂姆-艾伦在片中饰演埃利奥特-阿诺德(Eliot Arnold)--一位已卸任的新闻工作者和离了婚的父亲。他的儿子马特(Matt，本-福斯特饰，Ben Foster)正在与他的邻居朋友珍妮(Jenny，祖伊-德施尼尔饰，Zooey Deschanel)一起玩水枪游戏。与此同时，混乱场面来临了。二个傻乎乎的杀手斯纳克(Snake，汤姆-赛兹莫尔饰)和埃迪(Eddie，约翰尼-纳什维尔饰)出现了，他们准备暗杀珍妮名声不好的继父阿瑟-赫克(Arthur Herk，斯坦利-塔茨饰)，因为阿瑟偷了他老板的钱。然而，这两个自称“杀手”的傻瓜并没有去刺杀阿瑟，相反却去偷了一个军火商装有核武器的手提箱。\r 　　\r 　　当利奥特-阿诺德和莫妮卡警官(Monica，简尼安-加罗法洛饰，Janeane Garofalo)前去追寻斯纳克和埃迪时，一路上遇见了迈阿密当地形形色色的居民，还有一只巨大的引起幻觉的蟾蜍、一条名叫达夫妮(Daphne)的巨蟒和拦路的山羊，以及市民们熟悉的娱乐公园“假牙冒险园”(Denture Adventure)。','They have forty-five minutes to save the world. They need forty-six.',40000000,8493890,5.201688,6.3,80,85,'2002-04-05','en','/h844gBztdYMLrroUen6qbsomrGx.jpg',2.805469711041343,3,'2026-09-10',2,NULL,NULL),(2196,'葬礼上的死亡','Death at a Funeral','丹尼尔（马修·麦克费登 Matthew Macfadyen 饰）是个久不得志的作家，而且一直生活在名作家哥哥罗伯特（拉珀特·格雷夫斯 Rupert Graves 饰）的阴影之下。默默担负赡养父母义务的他这次主办父亲的葬礼，却同样被哥哥喧宾夺主。\r 　　本来严肃而又神圣的葬礼更是被堂姐的未婚夫，错食了迷幻药的可怜虫西蒙（艾伦·图代克 Alan Tudyk 饰），搅得一团糟。然而更大的危机在后面，一个神秘的侏儒男子（彼特·丁拉基 Peter Dinklage 饰）现身了，带着毁坏父亲所有声名的证据对丹尼尔进行敲诈。原来丹尼尔的父亲是同性恋，这个秘密眼看就要在他死后被揭开。\r 　　在一团混乱中，葬礼断断续续的进行着。戏剧化的悲伤和幽默悄然向我们揭示葬礼的意义——带着挚爱的心情缅怀死者，也让生者将不如意的过去埋葬在葬礼上。 ©豆瓣','From director Frank Oz comes the story of a family that puts the F U in funeral.',9000000,46,20.410354,6.9,497,90,'2007-02-09','en','/r90Mmt0mn9KbWCR0m3f76ipgM1H.jpg',3.3248215240809227,3,'2026-09-10',2,NULL,NULL),(2207,'勇闯16街区','16 Blocks','纽约警察局里一如既往的忙碌着，老干探杰克·莫斯利（布鲁斯·威利斯）虽当年勇猛过人尽破些要紧的大案，可如今日渐衰老的他却勇猛不敢当年。但“姜还是老的辣！”虽身手打斗大不如前，但机警过人、经验老道的他却总能化险为夷，依然可以在很多重要案件上发挥着巨大的作用。眼前，便有一件10非常棘手的案件发生，一个名叫埃迪·班克（莫斯·戴夫）的黑人小子无意间看到了一起罪恶事件的发生，从而成为这起案件的重要目击证人。如今更是成了匪首党羽们竞相追杀的目标。因此，警方决定由资历深厚的老警探杰克·莫斯利来负责在开庭那天将目击证人从警局的看守所护送到相距16个街区之远的法庭现场。　　而此时闻风而来的黑社会党羽们早已是蠢蠢欲动，这伙亡命之徒正是想利用这漫长而短暂的16个街区之路程来劫持并干掉证人埃迪，从而帮助他们的老大在法庭上因罪证不足而逃脱法律的制裁。而“黑证人”埃迪·班克却是个天生调皮喜欢无事打屁且乐观开朗的小子。性格不羁的他对穿制服的人也是从来都没有什么好感可言，对眼前的这位古板的老警察亦是百般的不合作。相反，老警探杰克对这位给他带来麻烦不断的黑人小子更是反感异常，但是出于对职业的尽心尽责，杰克还是拼尽全力与活力强劲的众匪徒们展开周折和惊险的斗智斗勇。而埃迪则似乎一点也没意识到将要面临怎样的险恶情境。在复杂而纷繁、不大不小的十六个街区之内，一场证人争夺战，或者说是一次亡命大逃杀就这样轰轰烈烈地开始了……','For a New York cop and his witness, the distance between life and death just got very short.',55000000,65664721,32.31022,6.2,661,105,'2006-03-01','en','/rqSIWq1KpJ1qVoCJ9bqShZ9PrLK.jpg',3.330486905074389,3,'2026-09-10',2,NULL,NULL),(2211,'战火中的伊甸园','Aimée & Jaguar','影片根据真人真事改编，讲述一段发生在战火下的女同爱情故事。1943年的柏林，正是第二次世界大战纳粹时期。已婚的莉莉（茱莉安·柯勒 Juliane Köhler饰）一如既往的过着毫无激情的生活，直到在一次音乐会上结识了犹太女子菲利斯（乔娜·沃卡莱克 Johanna Wokalek饰），一股激情四射的爱火被瞬间点燃了。她们互唤对方昵称艾米和加古娅，彼此深爱着对方。菲利斯一直在为反纳粹组织搜集资料，直到1944年的一天，被纳粹残害早逝。战火下的爱情，谁又能逃过生离死别。',NULL,0,0,2.832628,6.3,20,125,'1999-02-10','de','/6DXbzVRbAz5JmomAshoNhFwIcPK.jpg',2.5028645928622724,3,'2026-09-10',2,NULL,NULL),(2251,'不忠','Unfaithful','爱德华（理查•吉尔 饰）与妻子康妮（黛安•莱恩 饰）是令人艳羡的一对，他们有一个8岁的儿子。他们结婚已有11年，日子过得平平淡淡却十分美满幸福。可是生活的一成不变是康妮开始有些厌倦了。正在此时，她邂逅了神秘男子（奥利佛•马提纳兹 饰），更一发不可收拾的爱上了这名陌生人。面对丈夫，康妮不得不一而再再而三的向丈夫撒谎，不知不觉间，她已陷身于危险之中。爱德华还是发现了妻子的异样，当他知道了妻子果真有越轨行为的时候，他疯狂得要知道妻子对他不忠的所以细节。无奈知道得越多越痛苦，接着他偷偷约见了妻子的情人……','Where do you go when you\'ve gone too far?',50000000,119137784,14.382253,6.3,276,124,'2002-05-10','en','/hUqwervLJ7rJBO0DehOuHqUyOpb.jpg',3.103321788741789,3,'2026-09-10',2,NULL,NULL),(2252,'东方的承诺','Eastern Promises','神秘而富有魅力的俄裔男子尼古拉·卢津，是伦敦最臭名昭著的东欧黑道家族之一的司机。该家族隶属于“律贼兄弟会”犯罪组织。家族首领塞苗恩是豪华的“跨西伯利亚”餐厅的老板，其殷勤迷人的外表完美掩饰了冷酷残暴的本性。家族正面临考验——塞苗恩喜怒无常的儿子、也是打手的基里尔，与尼古拉的关系比亲生父亲更为紧密。然而尼古拉精心维持的生活，在圣诞节期间与安娜·基特洛娃相遇后被打破。安娜是北伦敦一家医院的助产士，一名少女在分娩时死亡的绝望境遇深深触动了她。她决心追溯婴儿的血缘与亲属。女孩遗留的俄文日记也成为安娜探寻答案的线索。安娜的母亲海伦并未阻拦，但她脾气暴躁的俄裔舅舅斯捷潘却力劝她谨慎行事。他的担忧不无道理：对日记的深入追查，已无意间触怒了整个“律贼”组织的杀机。','Every sin leaves a mark.',51500000,55112356,35.481169,7.2,848,100,'2007-09-14','en','/qWkHv78LzOAhGDyY1L3ZH1NheFI.jpg',3.554762541684741,3,'2026-09-10',2,NULL,NULL),(2253,'Valkyrie','Valkyrie','Wounded in Africa during World War II, Nazi Col. Claus von Stauffenberg returns to his native Germany and joins the Resistance in a daring plan to create a shadow government and assassinate Adolf Hitler. When events unfold so that he becomes a central player, he finds himself tasked with both leading the coup and personally killing the Führer.','Many saw evil. They dared to stop it.',75000000,200276000,38.832842,6.7,1173,121,'2008-12-25','en','/4vCNDtAzSREAjSEuB0D0UWhJXQt.jpg',3.56602763740787,3,'2026-09-10',2,NULL,NULL),(2255,'寻找艾米','Chasing Amy','从看到艾丽莎（乔伊·劳伦·亚当斯 Joey Lauren Adams 饰）的第一眼起，霍登（本·阿弗莱克 Ben Affleck 饰）就知道自己在劫难逃，可接下来的消息对霍登来说无疑是一记噩耗，漂亮开朗的艾丽莎居然是一个完完全全的女同性恋者。得知了死党的遭遇，班克（杰森·李 Jason Lee 饰）为此十分打抱不平，他告诉霍登他的恋情并没有走入绝望的境地，并且表示愿意在此方面助他一臂之力。随着时间的流逝，艾丽莎和霍登之间产生了真挚的感情，一段良缘眼看着就要结成，这时的班克才发现自己内心中充斥着的竟然全是负面的感情，他并不希望霍登能够得到艾丽莎的垂怜，而他和霍登之间的友谊也开始出现了裂痕。','It\'s not who you love. It\'s how.',250000,12021272,20.601483,6.7,433,113,'1997-04-04','en','/d4E7KtVNi0Bxia8yxncc4Ve04H2.jpg',3.2652818636753915,3,'2026-09-10',2,NULL,NULL),(2266,'巴黎，我爱你','Paris, je t\'aime','一个还算小有成就的中年男友，在路边停车时，突发感概，为什么满街上的人，只有自己形单只影？就在这时，一个女人因为低血糖晕倒了在他的车旁，热心的男人将她扶进了自己的小车后座休息，两颗孤独的心由此靠近。塞纳河畔，三个年轻人在调戏着路过的年轻女子。其中一个发现了就在他们旁边有一个戴头巾的漂亮女孩，女孩离开时不小心摔倒了，那个年轻人跑过去把她扶了起来。爱情在两人中间慢慢滋长。一间画室里，一个法国男孩对另一个男孩一见钟情，絮絮叨叨的讲着自己是如何抑制不住和他谈话，讲着自己是如何被对方的气质所吸引……然而另一个男孩对他却无动于衷，最后，法国男孩留下了自己的联系方式离开了。这时，男孩用英语问旁人，“刚才他在讲什么？我法语不好。”随后，男孩冲出了画室，奔跑着去追寻自己的爱情。一个美国中年妇女来到巴黎旅游，她望着川流不息的人群，此时她多么希望自己就是法国人，能长此居住在这个陌生而又极具魅力的城市。她想起了自己的前男友，虽然两人已经分手了十一年，他也有了自己的家庭。最后，他参观了巴黎的公墓，看到历史上叱咤风云的人物安静的躺在那里，她也感悟了。','Fall in love with Paris 18 times.',13000000,4857367,10.573191,6.8,207,120,'2006-05-16','fr','/kN2kjPwnYjpHkwI9MbtnZgV96FX.jpg',3.062598891597873,3,'2026-09-10',2,NULL,NULL),(2268,'黄金罗盘','The Golden Compass','这一个不凡世界，人的灵魂是一个以动物形式存在的精灵，且人与精灵密不可分，不然，生命将不复存在。 13岁的莱拉，长在这世界的约旦大学，没有家庭之爱，不识富有、强大但已成敌的父母，更不知自己身负震撼世界的诅咒；她终日与玩伴及他们的精灵自由自在地嬉闹，长成了一个诡计多端、恣意妄为且谎话连篇的野女孩。然而，可怕的预言无法抗拒，莱拉注定要承担起救世主之责，扮演人类之母夏娃的角色：人人畏惧的“尘埃”出现了，饕餮游荡在城市各个角，玩伴接连莫名失踪，快乐时光彻底完结于密友罗杰的失去，巨大的阴谋正在酝酿之中……于是，在个惟她可懂、能预知未来的黄金罗盘——真理仪的帮助下，浑然不觉险恶的莱拉决定去寻找被邪恶科学家掠走的孩子们，从此开了拯救世界的艰难之旅；她朝着未知的北极而去；等待她的，有披甲熊、女巫、天使、厉鬼，更有能够终结生命的精灵切割机…而领引她步步踏入死亡之地的，竟是其父，自然科学家阿斯里尔勋爵，与其母，狂热的原教旨主义信徒库尔特夫人……','There are worlds beyond our own - the compass will show the way.',180000000,372234864,42.990906,5.8,1303,113,'2007-12-04','en','/64Bj9QNrGGfo566iis1ujXipLtM.jpg',3.429466975951196,3,'2026-09-10',2,NULL,NULL),(2270,'星尘','Stardust','特里斯顿(查理·考克斯饰演)是魔法王国的王子，但是他成长在市井凡间，并不知道自己的身份。他爱上了美艳而冰冷的维多利亚，为了赢得她的芳心，他发誓要替她找到一颗坠落的星星，并将那个星星带回到她的面前。机缘巧合之下，他找到了这颗星星。它如今已经变化成为一个美丽的少女亚伊尼(克莱尔·丹妮丝饰演)，而这个少女带着魔法王国王位的钥匙——一颗魔法宝石。国王的四个活着的王子和三个死去王子的鬼魂也需要这颗宝石来赢得父亲王位。邪恶的女巫拉米尔(米歇尔·菲佛饰演)为了让自己恢复青春也加入了抢夺星星的行列。特里斯顿与这些竞争对手展开了激烈的争斗，随着旅程的进行，特里逐渐意识到什么才是真爱，爱情在亚伊尼和特里之间逐渐萌发了。','This Summer A Star Falls. The Chase Begins.',70000000,135560026,48.032734,7.1,1184,127,'2007-08-09','en','/5T0Cl5ZMSecIRIYZypVYGMsEDCP.jpg',3.6637483254385264,3,'2026-09-10',2,NULL,NULL),(2275,'西点揭秘','The General\'s Daughter','“军队罪行调查部”的高级官员布伦纳（约翰·特拉沃夫塔 饰）和其助手森希尔（马德琳·斯托 饰）奉命36小时内调查清楚一起神秘的谋杀案，副总统的有力竞争者坎贝尔将军（詹姆斯·克伦威尔 饰 ）的女儿伊丽莎白（莱斯利·斯蒂芬森 饰）在军事基地内被残忍杀害。随着调查深入，布伦纳发现曾就读于西点军校的伊丽莎白除了成绩优异、长相出众外在高中时还发生过一起不为人知的事情，她的私生活糜烂不堪，与父亲的关系并不融洽，而坎贝尔将军也不像他所塑造的形象一样刚正不阿。在揭开事情真相的同时布伦纳也发现了许多军队中的秘密。最终，杀人凶手被惩治以法，事件得以平息。','Go behind the lies.',60000000,149705852,18.345613,6.1,205,116,'1999-06-18','en','/v7wXPMOBUEvRWexFHxZW90pSjgn.jpg',3.0317902981520324,3,'2026-09-10',2,NULL,NULL),(2277,'机器管家','Bicentennial Man','机器人安德鲁（罗宾·威廉姆斯 Robin Williams 饰）原本只是马丁一家购买的家务机器人，但随着时间推移，他逐渐展现出创造力、幽默感和对人类情感的理解。在主人理查德·马丁（山姆·尼尔 Sam Neill 饰）的支持下，安德鲁获得自由，并不断改造自己的身体，努力成为真正的人类。后来，他爱上了波西亚（艾伯丝·戴维茨 Embeth Davidtz 饰），也因此体会到嫉妒、痛苦与爱情。为了得到人类社会的认可，安德鲁最终放弃了机器的永恒生命，并在生命尽头被正式承认为人类，与波西亚相伴至老，幸福离世。','One robot\'s 200 year journey to become an ordinary man.',100000000,93700000,24.939295,6.9,963,131,'1999-12-17','en','/4jtC5tnsVyDdCzwiXeWYyVZQlEH.jpg',3.517275440133731,3,'2026-09-10',2,NULL,NULL),(2280,'飞越未来','Big','12岁的乔什（汤姆·汉克斯 Tom Hanks 饰）似乎对自己的年龄有些意见：个子太矮而无法坐绕环滑车，年纪太小追不到心仪女孩……于是他向游乐场里的一个古旧许愿机投了25美分，许愿变成一个大人。不料第二天起床，乔什竟发现自己一夜之间长大了近20岁，现在他是一个不折不扣的大人了，连母亲都认为他是绑架儿子的陌生人而将他赶了出去。乔什只好自谋生计，在一家玩具公司找到了职位。在一次偶然的机会，乔什孩子般的天真与热情给玩具公司老板留下了深刻印象，他的点子也使他在工作中频获嘉奖，很快住进了宽敞的公寓，并与年轻同事苏珊（伊丽莎白·帕金斯 Elizabeth Perkins 饰）展开了浪漫恋情。然而随着工作、生活、爱情这些成人世界的压力开始向乔什逼近，乔什那颗刚满13岁的心渐渐感到困倦失落，他开始回想，这是否就是自己想要的成长……  　　本片曾获提名奥斯卡最佳男主角及最佳原创剧本。','You\'re Only Young Once But For Josh It Might Just Last A Lifetime.',18000000,151668774,20.716023,6.9,993,104,'1988-06-03','en','/dCcWY468h63I1bYvT0DzXehN0Ia.jpg',3.516056205569845,3,'2026-09-10',2,NULL,NULL),(2287,'街头舞魂','Rize','这是一个研究团体跳舞运动的纪录片，从洛杉矶中南部开始，让我们全面接触街舞。在片中你可以看到导演完美诠释的hip-hop，可以看到美国独特的文化。虽然影片采用了快速拍摄的手法，但是整个电影的进程我们却看不出一点加速的痕迹，随着六月新片《这个夏天有异类》的上映，《瑞兹》也用它独特的感染力影响着这个夏天的影坛……',NULL,0,0,1.623769,5.9,13,86,'2005-01-15','en','/bx7UAcyumQZuNj3dZFK7Wh4dbRl.jpg',2.4094370714082176,3,'2026-09-10',2,NULL,NULL),(2288,'偷心','Closer','故事中的两对情人本相安无事，却由于一对的男方搭上另一对的女方，而开始变得越来越复杂起来。就这样交织着激情、欲望、放纵和背叛，四个男女的爱情故事在镜头前被慢慢放大。','If you believe in love at first sight, you never stop looking.',27000000,115505027,22.636908,6.7,811,104,'2004-12-01','en','/fGGaokx4k00S0J603VG53Qlr9jz.jpg',3.433102205773346,3,'2026-09-10',2,NULL,NULL),(2289,'冷山','Cold Mountain','英曼是美国南北战争末期一名受伤士兵，在灵魂仿佛燃尽之后，对家园强烈的渴望支撑他站立起来，踏上了艰辛漫长的归家旅程。他的情人艾达则在山影交错的乡间忍受孤独，度过了失怙独立的蜕变期，学会了如何与粗砺尖锐的生活抗挣。战争摧毁了一切，而依然兀立的冷山是他们之间唯一的联系，也是他们回忆与想望的地方——一个即使你所信仰的天堂已然破灭，却仍能为你疗伤止痛的美好国度。','Find the strength. Find the courage. No matter what it takes... find the way home.',79000000,173013509,24.598479,6.7,533,154,'2003-12-24','en','/xe267XOTXyvCFJqiyNsCTHbUHRR.jpg',3.328199101970443,3,'2026-09-10',2,NULL,NULL),(2290,'善意的谎言','Jakob the Liar','故事发生在1944年的波兰，德军的铁蹄踏上了这片苦难的土地，一时间，生灵涂炭，此处成为了人间地狱。身为犹太男孩，雅各布（罗宾·威廉斯 Robin Williams 饰）和许多与他一样的男孩们被迫被德军做牛做马，所有的信息渠道被军队封锁，波兰成为了一座孤城。  　　一次偶然中，雅各布从收音机中听到了德军正在与苏军激战的消息，战斗地点不在别处，就在离波兰只有几百公里的本沙尼克。士气高昂的雅各布决定将这条珍贵的消息告诉更多的人，在雅各布的添油加醋之下，盟军苏联已然在争斗中获得了不可逆转的优势。这条虚假信息振奋了犹太人的士气，却也传到了德军的耳中，他们开始了缜密的调查，势要抓到造谣生事的始作俑者。','When all hope was lost, he invented it.',0,0,8.962245,6,90,120,'1999-09-16','en','/vvwsvPyQFuQbKKfzNgoRhAcL5ml.jpg',2.830059678868162,3,'2026-09-10',2,NULL,NULL),(2292,'疯狂店员','Clerks','美国的小众独立电影，讲述了便士多店小店员但丁（布莱恩·奥哈罗兰 Brian O\'Halloran 饰）郁闷抓狂的一天。过了睡眠质量极差的一晚后，但丁大清早被老板叫去加班。这只是倒霉的一天的起始，接下来，还有更多麻烦事情接踵而至，开店门、喷标语、遇见唠叨的反吸烟人士阻挠店面生意。一个头两个大的但丁，还要和前来店铺的女朋友维罗尼卡（玛丽莲·吉格洛尔蒂 Marilyn Ghigliotti饰）交流性生活经验。结果落得个不欢而散，因为女朋友拥有过的性伴侣数目实在令但丁叹为观止。 　　麻烦事还是一桩接一桩，这时前女友的到来令但丁的心狠狠振作了一下。他的艳遇到了，似乎终于可以扫走霉运。可是，卫生间内的“奇遇”，又摧毁了这件美好的事情。','Just because they serve you doesn\'t mean they like you.',27000,3151130,19.748658,7.4,755,92,'1994-09-13','en','/9IiSgiq4h4siTIS9H3o4nZ3h5L9.jpg',3.5147206704863256,3,'2026-09-10',2,NULL,NULL),(2293,'耍酷一族','Mallrats','TS（杰瑞米·伦敦 Jeremy London 饰）的一句戏言导致女友博兰蒂不得不参加她父亲的电视相亲节目，而这也使他们的旅行计划泡汤，愤怒的TS甩手而去，找到老友鲍迪（杰森·李 Jason Lee 饰）寻求安慰。鲍迪的情况也很糟糕，女友蕾娜厌倦了他无所事事沉迷于漫画和电子游戏，果断分手去寻找浪漫爱情。失意的TS与鲍迪选择逛商场排遣烦闷，然而这里也不让人舒畅！博兰蒂父亲的电视节目正在这里搭台准备录制，正在追求蕾娜的时装店经理也处处找鲍迪的不痛快。决定反击的二人找来恶作剧二人组杰伊（杰森·缪斯 Jason Mewes 饰）和鲍勃（凯文·史密斯 Kevin Smith 饰）破坏搭台，与此同时，漫画大师、执着于3D图像的胖子、从事性学研究的少女等异人也在商场中悉数登场，TS和鲍迪要在一片混乱中发起自己的爱情保卫战。','They\'re not there to shop. They\'re not there to work. They\'re just there.',6000000,2122561,16.139771,6.8,392,94,'1995-10-20','en','/2ip0sGIMPN0XEN6q3lQIoaNI6tP.jpg',3.239993514496214,3,'2026-09-10',2,NULL,NULL),(2294,'白烂贱客','Jay and Silent Bob Strike Back','从婴儿时被母亲并排的放在便利店门口起，杰（杰森•缪斯 Jason Mewes 饰）与鲍伯（凯文•史密斯 Kevin Smith 饰）这对贱友与便利店的缘分便开始绵延，然而店主不堪忍受两人整日在门外闲晃，报警将他们驱逐。杰与鲍伯坏运气还没完，一部以他们为主人公的漫画改编电影即将开拍，除了片方一分钱也没给他们，网上还充满了对他俩的谩骂与嘲讽，愤怒的二人组决定从新泽西赶赴好莱坞，阻止电影的拍摄。两人于路搭上了动物保护主义者杰斯特等四名美女的顺风车，杰迷恋杰斯特，答应帮助偷窃被用于实验的猩猩，谁知这四名女子实际是珠宝大盗，杰与鲍伯带出猩猩后被警方认定为恐怖主义者。两个人和一只红毛猩猩，在警方围堵中继续向好莱坞前进……','Hollywood had it coming',22000000,33788161,21.865021,6.4,480,104,'2001-08-22','en','/aEsAdMAhwKYFgnHHxMOknktQYKK.jpg',3.2590453879030385,3,'2026-09-10',2,NULL,NULL),(2295,'疯狂店员2','Clerks II','距上一集约十年后，一场大火将但丁（布莱恩•奥哈罗兰 Brian O\'Halloran 饰）所在的便利店付之一炬，他本人也被老板扫地出门。在此之后，他和好哥们兰度（杰弗•安德森 Jeff Anderson 饰）到佛罗里达一家名为“Mooby’s”的快餐店打工，这里有一个狂迷魔戒、还带着点儿gay倾向的店员埃里亚斯（Trevor Fehrman 饰），以及和但丁始终大玩暧昧、纠缠不清的女主管贝姬，当然还少不了毒品贩子二人组杰（Jason Mewes 饰）和沉默鲍勃（Kevin Smith 饰）。这群人凑在一起，每天插科打诨，互相攻讦，过着无忧无虑混吃等死的逍遥日子。 　　年过三十，即使再怎样玩乐的人也希望安定下来。但丁认识了一个富家女，未来岳父许诺只要和其女儿来佛罗里达结婚，便会赠送一个洗衣店。这对始终辛苦打拼的但丁来说无疑天上掉馅饼，不过，这也意味着他要离开一众好友，结束这样简单快乐的生活…… 　　本片荣获2006年艾丁堡国际电影节观众奖、2007年MTV电影奖最猛粗口时刻。','With No Power Comes No Responsibility',5000000,26888376,18.077963,6.9,398,97,'2006-05-25','en','/cLSW0nW94XT0DmBS69ublcLfQ9c.jpg',3.2590248828854986,3,'2026-09-10',2,NULL,NULL),(2300,'空中大灌篮','Space Jam','美国NBA传奇人物迈克尔·乔丹在事业最顶峰之际引退篮坛，决定转入职棒。与此同时，怪物行星的太空游乐场经营遭遇窘境，游乐场老板派出手下的小怪物们前往地球，目的是绑架华纳公司包括兔八哥、太妃鸭、三只小猪等在内的动画片明星们为游乐场招揽顾客。为了维护自由，动画明星们紧急磋商对策，他们自作聪明认为外星怪物身材短小，于是决定采取篮球比赛的方式决定胜负。不过动画明星的如意算盘落空，小怪物们暗中盗取了皮蓬、巴克利等NBA明星们的球技，变成了身形健壮修长、球技高超的怪物篮球手。眼看败局已定，兔八哥紧急找来迈克尔·乔丹助阵，决定动画明星去留的时刻越来越近……','Get ready to jam.',80000000,250200000,36.125715,6.5,1288,88,'1996-11-15','en','/4ttJz7otn4AfGdF4QdaT8b2z1Us.jpg',3.5456613810982405,3,'2026-09-10',2,NULL,NULL),(2309,'墨水心','Inkheart','麦琪（伊丽莎•班尼特 Eliza Bennett 饰）是一个生活在德国的12岁小女孩，她和父亲阿莫（布兰登•费舍 Brendan Fraser 饰）相依为命。妈妈莱莎（Sienna Guillory 饰）在麦琪尚在襁褓中时便神秘失踪，十几年来阿莫凭借旧书装祯的手艺维持父女二人的生活。麦琪对母亲的下落充满好奇，而父亲则三缄其口。孤单的小女孩每日徜徉书海，任凭思绪飞扬。某晚，一个肮脏邪恶的家伙（Paul Bettany 饰）闯入父女的家中，阿莫和女儿仓皇逃到姑妈爱利诺（海伦•米兰 Helen Mirren 饰）的家中，此时麦琪终于得知母亲失踪真正的原因以及父亲所具有的神奇能力。原来阿莫能够通过阅读将书中的人物带到现实的世界中来，而这也正是灾难的开始……\r 　　本片根据德国著名女作家科尼莉亚畅销丛书中的第一部改编。','Every story ever written is just waiting to become real.',60000000,57490374,27.018886,6,592,106,'2008-12-11','en','/wIH3Gnc4ccxXZh01YswhiWdbOXV.jpg',3.266880234753837,3,'2026-09-10',2,NULL,NULL),(2310,'贝奥武夫','Beowulf','在英国撒克逊人长篇史诗《贝奥武夫》的描述中，主人公贝奥武夫（雷·温斯顿 Ray Winstone 饰）是一位拥有强健体魄和惊人战力的武士，他一身将经历三场对其影响重大的战役。为了拯救被巨人格兰戴尔（克利斯丁·格拉夫 Crispin Glover 饰）掠夺的村庄，贝奥武夫带领一群武士渡过海洋向其挑战。在一场浴血奋战之后，格兰戴尔被武士们所击败。但是战斗却没有结束，格兰戴尔的母亲（安吉丽娜·朱莉 Angelina Jolie 饰）为了复仇向贝奥武夫发起了挑战。一场更大的战役即将打响。虽然这次，勇士们将付出更加惨痛的代价，但是在无所畏惧的贝奥武夫面前，即便是再厉害的对手，也将被毁灭。多年后，与一条恶龙的终极之战，最终将贝奥武夫的名字变成了不朽的传奇。','Evil breeds pain.',70000000,195735876,35.601665,5.5,841,115,'2007-11-05','en','/1BrQPYg6FsFImFeLtWbIx6WTUpA.jpg',3.2792774207624302,3,'2026-09-10',2,NULL,NULL),(2312,'地牢围攻','In the Name of the King: A Dungeon Siege Tale','故事发生在一个历史悠久的古老王国之中，邪恶的魔鬼巫师加里安（雷·利奥塔 Ray Liotta 饰）盯上了这片宁静祥和的土地，带领着他的爪牙，他们血洗了村庄，杀害了农夫戴蒙（杰森·斯坦森 Jason Statham 饰）的孩子，并且夺走了他的妻子索拉纳（克莱尔·弗兰妮 Claire Forlani 饰）。\r 　　愤怒和绝望之中，戴蒙决心报仇并且夺回妻子。在国王康雷德（伯特·雷诺兹 Burt Reynolds 饰）和善良法师莫瑞科（约翰·里斯-戴维斯 John Rhys-Davies 饰）的帮助之下，戴蒙集结了一支精明强干的敢死队，然而，他们所要面对的敌人却并不仅仅是嗜血残暴的野兽兵团这么简单，众人需要抵抗的，是更邪恶的，更黑暗的，更强大的黑暗魔法。','Rise and fight',60000000,0,15.406173,4.1,224,127,'2007-11-29','en','/oHQBWyirDj17D4vYveoPFn7Nn3J.jpg',2.9030621275039286,3,'2026-09-10',2,NULL,NULL),(2320,'最高危机','Executive Decision','一架载满400名乘客的巨型波音747正飞向美国首府华盛顿，在途中被国际恐怖组织劫持,他们设圈套要求美国当局释放其恐怖组织的首脑，真正目的是要在华盛顿上空引爆在飞机上的毒气弹。此举威胁着千万人的生命。 美国国防部中校戴维斯和国际犯罪专家格兰特博士率领一批精良特遣队，通过F117隐形战斗机潜入747解救人质，但对接过程中战斗机不幸爆裂坠毁，中校阵亡，潜入客机内的特遣人员和国防部无法进行通讯。时间己迫在眉睫，毫无胜算的美国国防部忍痛下了“致命决定”，派战斗机升空拦截并要摧毁这架747客机。且看机内的特遣人员如何在千钧一发之际化险为夷……','Fasten your seat belts',55000000,121969216,17.231675,5.8,256,133,'1996-03-15','en','/qe9vTaSRyvsGrzvIcHlDumEbYua.jpg',3.053721480939718,3,'2026-09-10',2,NULL,NULL),(2355,'从心开始','Reign Over Me','查理(亚当·桑德勒 Adam Sandler饰)是一个9•11的直接受害者，他的妻儿和爱狗都在这场灾难中丧生。查理从此一蹶不振，严重的自闭抑郁。他已经习惯了每天踩着电动滑车，戴着大耳机在街头行尸走肉般游荡，心灵巨大的创伤让他回归不了正常的生活。 　　艾伦（唐·钱德尔 Don Cheadle 饰）则是一个表面看来非常幸福的男人，有成功的事业和美满的家庭，然而他承受的生活压力是常人无法理解的，他的内心在暗暗苦撑。 　　直到有一天，艾伦在街头遇上了查理。得知这个老同学为何变得如此颓唐后，艾伦心里便下定决心也帮他一把，让他从低谷中走出来。他们一起谈心，游戏，慢慢的发现彼此的心灵都从窒息中苏醒过来。','Let in the unexpected.',20000000,22222308,20.82778,7.1,334,124,'2007-03-23','en','/vYkGSLwlK5xuPnkY5bZgkIpvyyV.jpg',3.237002517416193,3,'2026-09-10',2,NULL,NULL),(2359,'医疗内幕','Sicko','美国是唯一没有统一且公营的医疗保险的发达国家。美国医疗系统奉行私有化与市场化，每个人要自己买医疗保险。经济困难的美国人，只能希望自己不要生病；因为一旦发生意外，高昂的医疗费用在没有医疗保险公司负担的情况下，是一笔巨大的开销。《医疗内幕》片中讲述了一个美国男人意外地用电锯切断了自己的中指和无名指，赶到医院后，医生告诉他，接合中指要6万美元，接合无名指要1万2千美元；这个没有医疗保险的人只好选择只接上“便宜”的无名指，而放弃自己的中指。','This might hurt a little.',9000000,24538513,14.098952,7.3,235,123,'2007-05-18','en','/9zJ9HBG8a7hNXUawuswvXE6DPvW.jpg',3.13933179125082,3,'2026-09-10',2,NULL,NULL),(2370,'谍魂','Topaz','故事描写一位高阶的苏联军官投诚美国后，透露出一个惊人的消息：一名代号“黄宝石”的法国间谍，不断的将北大西洋公约组织的秘密透露给卡斯楚与苏联政府。于是，法国秘密特务安德鲁受命前往当地调查，在美国中情局官员的帮助下，他们赫然发现这名顶尖的法国官员，竟然是苏联特务！他们两人是否能揭露间谍“黄宝石”的真面目呢？','Hitchcock takes you behind the actual headlines to expose the most explosive spy scandal of the century!',4000000,6000000,5.975604,6.1,77,143,'1969-12-18','en','/dod6V4XSyj5xOgIUwj3yQno4EGL.jpg',2.793117542042401,3,'2026-09-10',2,NULL,NULL),(2395,'Asterix at the Olympic Games','Astérix aux Jeux Olympiques','Astérix and Obélix have to win the Olympic Games in order to help their friend Alafolix marry Princess Irina (portrayed by supermodel Vanessa Hessler). Brutus (Benoît Poelvoorde) uses every trick in the book to have his own team win the game, and get rid of his father Julius Caesar (Alain Delon) in the process.',NULL,97250400,132900000,20.344364,5,471,116,'2008-01-13','fr','/qCy6c8UVEoUeA0cEn6Dkufd3mI9.jpg',3.0861521112870047,3,'2026-09-10',2,NULL,NULL),(2428,'万世流芳','The Greatest Story Ever Told','乔治．史蒂文斯导演的此片长二百二十余分钟，堪称同一题材片之最，同时也是正面描写耶稣生平事迹的影片中投资最大之作。剧情讲述基督耶稣自出生至钉死十字架上的故事。影片场面颇为壮观，可惜节奏太慢，剧情的进展亦不够流畅，看来相当沉闷乏味。马克斯．冯．赛多、卡罗尔．贝克等大批影星出演了此片，均有不错表现。',NULL,20000000,15473333,3.011205,6.5,41,199,'1965-02-15','en','/c21ON7BZn0jwdNl6ibZ1vhXJmpy.jpg',2.6584780071863974,3,'2026-09-10',2,NULL,NULL),(2447,'基督诞生记','The Nativity Story','本片叙述玛丽和约瑟从拿撒勒跋涉100里到达伯利恒，最终让耶稣出生的故事','Her child would change the world.',35000000,0,3.721272,6.4,35,101,'2006-12-01','en','/nd0oj0lmEx1X8WraiVkYMZlDjKk.jpg',2.624386460127725,3,'2026-09-10',2,NULL,NULL),(2453,'铁汉狂奔','Harley Davidson and the Marlboro Man','浪人哈雷和万宝路为了帮老友保住经营的酒吧，连手抢了一个银行。但这银行来头可不小，武装车里装的不是现金，而是毒品。现在哈雷和万宝路成为腐败银行猎捕的对象，而两人必须在格杀追捕下设法逃生。','When the going gets tough... the tough take the law into their own hands.',23000000,7434726,12.869436,6.1,82,98,'1991-08-23','en','/4WRdrjHyLuHRwep2UJWBoIn6KTW.jpg',2.8223350510162253,3,'2026-09-10',2,NULL,NULL),(2454,'纳尼亚传奇2：凯斯宾王子','The Chronicles of Narnia: Prince Caspian','彼得、苏珊、埃蒙德和露西四人回到现实世界一年以后，突然被一股特殊的力量强行带进纳尼亚王国。原来，自从他们离开后，这里已经过去1300多年了，纳尼亚的黄金时代早已不复存在。现在的纳尼亚由台尔马人统治，同时还受奴役于邪恶的国王弥若兹--他害死了自己的兄长，谋权篡位，在他的暴政之下，纳尼亚王国的子民真是民不聊生、苦不堪言啊。老国王的儿子凯斯宾王子本是王位的正统继承人，因为害怕受到想让自己儿子当国王的亲叔叔的迫害，才被迫躲藏了起来。凯斯宾王子吹响了苏珊留下的魔法号角，重新召回亚当之子和夏娃之女，在善良的小矮人“杜鲁普金”、会说话的老鼠勇士“雷佩契普”和黑小矮人“尼克布瑞克”的帮助下，强大的骑士彼得和凯斯宾王子踏上了寻找狮王亚瑟兰的旅程……他们最终将会带领着纳尼亚会说话的生物和精灵们去战胜残暴的国王弥若兹，凯斯宾王子得以继位为王，荣耀也必定会重新回到这片充满了魔法的神奇土地上。','Hope has a new face.',225000000,419651413,53.978602,6.3,1630,150,'2008-05-15','en','/7Y76smJTpGVIOEFgoyJ88rm5bsq.jpg',3.6021612242890173,3,'2026-09-10',2,NULL,NULL),(2486,'龙骑士','Eragon','曾经和平富饶的国度阿拉盖西亚，如今陷在邪恶国王（约翰·马尔科维奇 John Malkovich 饰）的暴政统治下，期待神灵解救敢怒不敢言的人民。一日，农家少年伊拉贡（艾德·斯皮尔斯 Ed Speleers 饰）在林中拾获一枚奇石，不想竟是一枚龙卵，孵出一只蓝色飞龙。伊拉贡为小龙取名“萨菲拉”，遇到先知布鲁姆（杰瑞米·艾恩斯 Jeremy Irons 饰）后，才明白这是一场怎样的机缘——曾经守护这片土地的龙骑士应该回来了，带领人民找回自由。在布鲁姆的指导下，伊拉贡开始学习剑术和驭龙技巧，慢慢从一个普通少年成长为担当重任的龙骑士，前路危险重重，前路通向光明……  　　本片根据同名小说改编而成，是《遗传三部曲》中的第一部。','As darkness falls, the last dragon will choose its rider.',100000000,249288105,30.863434,4.9,967,104,'2006-12-14','en','/ildeO0jMFfRE1mj8PyhxeFHb67N.jpg',3.189732515908299,3,'2026-09-10',2,NULL,NULL),(2493,'公主新娘','The Princess Bride','一部很老派的童话式影片，爱情加冒险，但处理得当，融入了一丝嘲讽精神，故具有很强的观赏性。《公主新娘》这个关于爱与冒险的古老童话。邪恶的王子绑架了美丽的公主，并逼迫公主嫁给自己。公主儿时的玩伴、现在的勇敢海盗决定前去拯救公主，路上遇到了武艺超群的剑客、力大无比的巨人，二者成为海盗的同伴。\r 本片荣获1988年奥斯卡最佳音乐奖，1987年多伦多国际电影节民选奖！','It\'s as real as the feelings you feel.',16000000,30857814,44.533612,7.6,1486,98,'1987-09-18','en','/2FC9L9MrjBoGHYjYZjdWQdopVYb.jpg',3.821097042023864,3,'2026-09-10',2,NULL,NULL),(2501,'谍影重重','The Bourne Identity','Wounded to the brink of death and suffering from amnesia, Jason Bourne is rescued at sea by a fisherman. With nothing to go on but a Swiss bank account number, he starts to reconstruct his life, but finds that many people he encounters want him dead. However, Bourne realizes that he has the combat and mental skills of a world-class spy – but who does he work for?','He was the perfect weapon until he became the target.',60000000,214034224,86.476817,7.3,3583,119,'2002-06-14','en','/aP8swke3gmowbkfZ6lmNidu0y9p.jpg',4.1045299272145686,3,'2026-09-10',2,NULL,NULL),(2502,'谍影重重2','The Bourne Supremacy','经历第一集中的腥风血雨之后，伯恩（马特·达蒙饰）和自己的女友化名隐身在一个偏僻遥远的海滨小镇。虽然伯恩不愿意回视过去，但“过去”却一直都在追随着他，伯恩发现秘密组织的杀手已经潜入小镇，为了保护女友玛丽·克鲁兹，他必须战斗。是一起国际政治刺杀事件让CIA重新审视已经失踪的伯恩的档案，一名某大国政要被职业杀手刺杀，刺杀者留下的证据显示他的名字叫“杰森·伯恩”，这是大卫·韦伯从前在中央情报局的化名。于是大卫·韦伯不仅仅要防备秘密组织暗地里的追杀，还要避开时刻寻找他的CIA特工。在上一集中和伯恩并肩作战的尼科莱特信任伯恩，但她发现自己也身陷困境。事态似乎变得越发失去控制，四面楚歌的“伯恩”现在只有单枪匹马地去找出那个冒充自己的人，洗刷自己和尼科莱特的清白','They should have left him alone.',75000000,288500217,53.213931,7.2,2825,108,'2004-07-23','en','/jupG9sFT64YwM8PSkwkUD2wHcYD.jpg',3.94026465546556,3,'2026-09-10',2,NULL,NULL),(2503,'谍影重重3','The Bourne Ultimatum','他只想隐姓埋名，如今却遭造就他的人追杀。杰森·伯恩虽已失去记忆与所爱之人，却未被弹雨和新一代训练有素的杀手所阻。他只有一个目标：回到起点，查明自己究竟是谁。[环球影业]','Remember everything. Forgive nothing.',70000000,442824138,45.381501,7.3,2888,115,'2007-08-03','en','/15rMz5MRXFp7CP4VxhjYw4y0FUn.jpg',3.9522838139564294,3,'2026-09-10',2,NULL,NULL),(2539,'西班牙女佣','Spanglish','为了过上更好的生活，漂亮的单身母亲芙兰（帕姿•薇阁 饰）带着她12岁的女儿，从墨西哥搬家到美国这个自由国度。经朋友介绍，芙兰受雇到一个上等家庭做女管家。而语言的不同，沟通的障碍，文化的差异，成为芙兰新生活道路上最大的绊脚石。主人约翰（亚当•桑德勒饰）和黛博拉（蒂亚•李欧妮 饰）夫妇虽然都很善良，但他们与芙兰在生活方式以及对待孩子的态度上的分歧，也着实令芙兰伤透了脑筋。要完全融入美国上流社会，芙兰还需经历一些坎坷。脉脉温情笼罩下的文化冲突，悄然上演……','Every family has a hero.',80000000,55041367,14.209329,5.8,369,130,'2004-12-17','en','/x3OTaBvjqzhRL53Q39fOoIYqxyO.jpg',3.118806760849418,3,'2026-09-10',2,NULL,NULL),(2567,'飞行家','The Aviator','1906年，霍华德·休斯出生于美国德州的休斯顿。在他17岁时，他的母亲和父亲就先后去世，但其父亲以买卖租赁德州油井和发明深井钻头致富，死后留给休斯一笔巨额遗产。霍华德·休斯从小就对电影和飞机有着浓厚的兴趣 ，当他18岁时继承了父母的大笔遗产，怀着电影梦的霍华德·休斯从德州移居到了好莱坞。1926年他买入125家戏院的控制权，并且砸下数百万美金拍了著名的实景空战史诗电影《地狱天使》。1939年，霍华德·休斯入主环球航空公司，他迅速就使公司扭亏为盈，风光数十年。此外，对飞机兴趣异常浓厚的他常与工程师讨论改善飞机性能并且亲自设计出一架飞机，并驾机试飞五次，创造了平均时速352.39英里成绩，打破了法国人林白创下的最快飞行纪录。二战期间，他与美国政府合作，制造高空侦察机；战后他积极向电子领域拓展事业，旗下的公司对卫星技术做出了重大贡献，而他在拉斯维加斯的赌场也享有盛名。晚年的霍华德·休斯患上了强迫性精神症，他害怕细菌和外面的世界，独居在拉斯维加斯的几家酒店，与世隔绝，最终于1976年去世 ……','For some men, the sky was the limit. For him, it was just the beginning.',116000000,102000000,45.616098,7,1489,170,'2004-12-17','en','/lx4kWcZc3o9PaNxlQpEJZM17XUI.jpg',3.703336252034059,3,'2026-09-10',2,NULL,NULL),(2575,'巴拿马裁缝','The Tailor of Panama','故事发生在充满了异国风情的巴拿马，哈里（杰弗里·拉什 Geoffrey Rush 饰）是一个身怀绝技的裁缝，他凭借着出色的手艺和其三寸不烂之舌在巴拿马的达官显贵与政界要员之间混得风生水起，而他所作的一切，都是为了掩盖他的一段灰暗的过去。  　　可是，纸终究包不住火，英国大使馆成员安德鲁（皮尔斯·布鲁斯南 Pierce Brosnan 饰）的出现将哈里抛入了一个危险的环境中，安德鲁利用哈里的过去作为威胁，命令哈里成为他在巴拿马政界的眼线，为英国和美国获得巴拿马运河的所属权收集情报。无奈之中，哈里只得就范，但心中的愤怒和不满铸就了他口中的谎言，他告诉安德鲁，一个地下组织正在策划一场武装运动企图推翻政权。令哈里没有想到的是，正是自己的谎言酿成了大祸。 ©豆瓣','In a place this treacherous, what a good spy needs is a spy of his own.',21000000,28008462,7.047975,6.2,92,109,'2001-02-11','en','/jNwhufCAtXllsZem1cGj8iXT2i0.jpg',2.8370627668638453,3,'2026-09-10',2,NULL,NULL),(2577,'代码46','Code 46','威廉被派到上海去调查斯芬克斯保险公司的一桩伪造证件案，由于他染上了一种奇特的病毒，使他能够一清二楚地知道嫌疑犯的心理活动。玛丽娅是斯芬克斯的雇员，这家公司发行一种特殊的证件「papelles」，这是保险、护照与信用卡的混合体。没有这种证件的人就只能生活在被指派的次等区域内，那里条件极其恶劣，基本就是沙漠般的荒地，这些低等公民被禁止进入文明地带。\r 经过调查，威廉发现正是玛丽娅在把伪造的证件卖给那些斯芬克斯公司拒绝与之交易的人。他很明白把玛丽娅交给组织是自己的职责，但是似乎还有一股更大的力量在悄悄发生作用。威廉深深地爱上了她，他无法就此一手将玛丽娅送上绝路。\r 事情甚至更复杂，最令威廉惊讶的是，玛丽娅竟然是从他死去的母亲脑部DNA克隆而成。\r 这对情侣受到驱逐，为了躲避当局追捕，他们不得不亡命天涯……','How do you solve a crime when the last thing you want to know is the truth?',7500000,0,8.859657,6.2,116,92,'2003-09-02','en','/2LZpKvJhYp7qGZsPn0CmVAUQpy0.jpg',2.891714048539452,3,'2026-09-10',2,NULL,NULL),(2604,'生于七月四日','Born on the Fourth of July','朗自幼就是一个争强好胜的男孩，向往男子汉的生活。年轻的朗被总统那番充满煽动性的越战演说彻底征服，一种挑战和为国牺牲的冲动在朗的内心渐渐滋长。一次摔跤比赛的失利，令一向要强的他毅然告别了恋人唐娜和大学生活，踏上了从军参战之路。然而，来到了越南的朗并没有在这里找到向往已久的英雄气概，反而目睹一出出反人类的悲剧。朗的好友威尔逊也在一次混战中死于朗的子弹，不久，朗中弹瘫痪被送回了美国。坐在轮椅上的朗仍然坚持着对美国发动的战争的信仰，但女友唐娜重遇了朗之后，痛心的认为朗的悲剧都是战争的错。噩梦缠绕着朗，朗去拜祭了战友威尔逊，反战呼声中，朗终于觉醒。','A story of innocence lost and courage found.',14000000,161001698,25.949277,6.7,395,145,'1989-12-20','en','/cquBhG1GGgOgnUzqgkY3R0llSFN.jpg',3.2538616414402193,3,'2026-09-10',2,NULL,NULL),(2610,'Shopgirl','Shopgirl','Mirabelle is a disenchanted salesgirl and aspiring artist who sells gloves and accessories at a department store. She has two men in her life: wealthy divorcée Ray Porter and struggling musician Jeremy. Mirabelle falls in love with the glamorous Ray, and her life takes a magical turn, but eventually she realizes that she must empower herself and make a choice between them.',NULL,10284523,11588205,4.820166,5.7,75,104,'2005-10-21','en','/mEpnYHytC1MuLECf4N0g4Xql2t8.jpg',2.773644338236053,3,'2026-09-10',2,NULL,NULL),(2619,'美人鱼','Splash','当艾伦·鲍尔（汤姆·汉克斯 Tom Hanks 饰）还是孩童时，曾在科德角的波涛中看见过传说中的美人鱼，这段经历在他的脑海中深深扎根。20年后，艾伦已成长为英俊的帅小伙，他终日奔波忙碌，真爱却始终未曾到来。某天，艾伦重返科德角，并且在此不慎落水。就在危急之时，一个美丽的美人鱼（达丽尔·汉纳 Daryl Hannah 饰）出现，拯救了他的性命。未过多久，美人鱼隐去鱼尾，来到纽约寻找艾伦，两人由此坠入爱河。一场现代的都市传奇爱情就此展开，但在这物欲横流的都市里，他们的爱情将何去何从……  　　本片荣获1985年美国科幻与恐怖电影学院最佳女主角奖（Daryl Hannah）、1985年美国国家影评人协会最佳剧本奖。','Allen Bauer Thought He\'d Never Find The Right Woman... He Was Only Half Wrong!',8000000,69821334,21.735068,6.1,321,111,'1984-03-09','en','/7FutTsMWBwVhjk1Ujf1wtndUVZh.jpg',3.1362005366960743,3,'2026-09-10',2,NULL,NULL),(2621,'爱归来','Return to Me','鲍勃（大卫·杜楚尼 David Duchovny 饰）是一名建筑工程师，和妻子伊丽莎白（朱莉·理查德森 Joely Richardson 饰）结婚多年，两人之间感情非常的要好。然而，一场可怕的疾病夺取了伊丽莎白的生命，也夺取了鲍勃人生里所有的幸福和快乐。伊丽莎白生前非常的喜欢动物，因此，鲍勃决定完成妻子的遗志，帮助动物园的大猩猩建造屋舍。\r 　　格瑞斯（明妮·德里弗 Minnie Driver 饰）是一名平凡的餐厅服务员，在经历了一场成功的换心手术之后，格瑞斯开启了她的第二次生命。在命运的安排之下，人生已经结束的鲍勃邂逅了人生刚刚开始的格瑞斯，两人之间会碰撞出怎样有趣的故事呢？','A comedy straight from the heart',24000000,36609995,5.771479,6.1,67,115,'2000-04-07','en','/mtYZyZh7hSiTq3gAU0C8FlcMC5.jpg',2.7629014408462296,3,'2026-09-10',2,NULL,NULL),(2636,'炮弹专家','The Specialist','美国中央情报局的特种兵炸弹专家雷（西尔维斯特•史泰龙 Sylvester Stallone 饰）因为过失引咎辞职，辞职后的他靠当职业杀手为生。这天他接到了神秘女子美（莎朗•斯通 Sharon Stone 饰）的生意，美要他杀死当地的黑社会头子。其实美就是那个黑社会头子的情妇，因他早前曾杀害了美的父母，所以美不惜一切要报父母之仇。美甚至以身体作为引诱，雷接下了这单生意，两人也暗暗互生情愫。　　雷在准备行动中，发现了黑社会头子的贴身保镖就是自己当年在特种兵部队里的死对头立特，旧恨新仇交织在一起，于是一场生死大战在两个前特种兵之间展开了！','The government taught him to kill. Now he\'s using his skills to help a woman seek revenge against the Miami underworld.',45000000,170362582,16.582709,5.5,313,110,'1994-10-07','en','/9CVAjtkSaFs9FyddGfThj11ZuQq.jpg',3.064889919268046,3,'2026-09-10',2,NULL,NULL),(2637,'天蛾人的预言','The Mothman Prophecies','约翰（理查·基尔 Richard Gere 饰）是一位专门调查科学无法解释的不思议事件的记者，妻子玛丽（黛博拉·梅辛 Debra Messing 饰）的意外死亡让原本生活幸福美满的他陷入了痛苦之中。令约翰耿耿于怀的是妻子生前留下的画作，画面上鬼魅一般的形象让约翰联想到了妻子曾经说过的一些奇怪的话语，这些迹象表明，玛丽的死亡或许并不是一个意外。  一次偶然中，约翰在出差的途中迷了路，兜兜转转下，他来到了一个名叫极乐镇的地方，在那里，正发生着一些诡异又可怕的事情。好奇心驱使约翰留在了此地进行调查，让他惊讶的是，妻子画里的可怕形象竟然出现在了小镇居民们的梦境中，而对于这个模糊不清的形象，小镇的居民们将它称为“天蛾人”。','What do you see?',32000000,55157539,14.733513,6.1,305,119,'2002-01-25','en','/dx9b6oRliLBi9i7Jup3rRVhP1OY.jpg',3.1091810326609672,3,'2026-09-10',2,NULL,NULL),(2639,'解构爱情狂','Deconstructing Harry','哈里是一个才华横溢的著名作家，由于他神经兮兮、过于疯狂，他一直过着支离破碎、混乱无序的生活。他把身边的人和周围发生的事都写进自己的小说里，把自己和多名女性的感情生活也写成小说出版，由此哈里伤害和得罪了身边很多人。哈里的真实生活与小说中的虚构情节不断交织，同时哈里发现自己的灵感开始枯竭。在哈里的生活过得一团糟的时候，他被母校邀请回校接受名誉学位，但他找不到一个可以陪他一起去的伴儿。他只好找了个妓女陪同，第二天朋友理查德也来陪他，路上他还从前妻手中拐来自己的儿子一同前去。四人在途中又遇到了什么，到达目的地之后又有什么状况？  哈里试图解构自己的现实生活、解构自己小说中的虚构人物的生活、解构小说人物在自己生活中起到的影响，这个不能正常运作自己的生活，却只能在艺术中发挥才能的天才作家，究竟能不能解构出自己人生中的“真相”……','Harry Block has written a best seller... bout his best friends... he revealed their deepest secrets... and they\'re not pleased... now Harry Block is going to Hell...',20000000,10686841,11.352693,7.3,187,96,'1997-08-26','en','/i7Z5DdznqANJUjqWISEFu9bw6J7.jpg',3.0695596269015515,3,'2026-09-10',2,NULL,NULL),(2642,'贴身情人','Two Weeks Notice','百万富翁乔治·维德(休·格兰特 Hugh Grant 饰)的衣食住行都倚赖公司的律师露西·凯尔森(桑德拉·布洛克 Sandra Bullock 饰)。露西条理分明，但也有点神经质。而露西喜欢上了聪明，迷人的乔治。她一直在帮助乔治打点从服装到离婚案的所有大小事件，但乔治并没有什么表示。五年过去了，露西终要停止这一切。 乔治一开始不想让露西走，但最终还是答应了她，但他有个要求，让露西找个人来代替她。经过寻找，露西雇佣了一个年轻漂亮又野心勃勃的律师琼（艾丽西亚·维特 Alicia Witt 饰）。琼对她富有的新老板很感兴趣，而乔治也仿佛受到她的吸引。露西终于摆脱了乔治，准备和自己忠心耿耿的男朋友一起去海上旅行。失去露丝后，乔治也像失去了一个近身知己，接替的人如何主动献身也填补不了他精神上的失落。原来，一切彼此最需要的就在身边，只是一直未曾为意，漏了眼的缘份','Over. Done. Finished. A comedy about love at last glance.',60000000,93354918,24.153567,5.9,487,101,'2002-12-19','en','/r18hSGAcxWiUysbX6nFShIZyjjP.jpg',3.2076073990235017,3,'2026-09-10',2,NULL,NULL),(2649,'心理游戏','The Game','四十八岁的尼克是一个大富翁，他很富有，但精神却很空虚，他父亲在四十八生曰那天自杀的阴影一直部在他的心里。在他四十八岁生日那天，弟弟康罗送给他一张消费者娱乐服务会的游戏卡，没想到这张卡改变了他的一生。','What do you get for the man who has everything?',50000000,109423648,62.925175,7.5,1506,129,'1997-09-12','en','/4UOa079915QjiTA2u5hT2yKVgUu.jpg',3.847102034595928,3,'2026-09-10',2,NULL,NULL),(2652,'水果硬糖','Hard Candy','天真甜美的十四岁少女海莉（艾伦·佩吉 Ellen Page 饰）在网络上认识了三十二岁的摄影师杰夫（帕特里克·威尔森 Patrick Wilson 饰），二人相约在咖啡馆见面，相谈甚欢。海莉主动要求去杰夫家，让他为自己拍摄艺术照片，杰夫欣然从命。聊天喝酒之后，杰夫突然眩晕倒地，醒来发现自己竟被五花大绑。原来海莉是有备而来，就是要惩罚在网络上勾引未成年少女的恋童癖。海莉在屋中搜寻杰夫进行不法行为的证据，并为他实施了阉割手术。中途邻居太太（吴珊卓 Sandra Oh 饰）来访，也被海莉成功蒙混过关。随着海莉惩罚计划的一步步展开，杰夫的真面目也逐渐浮出水面……本片被提名英国独立电影奖最佳外国独立制片电影，并获西班牙加泰罗尼亚电影节最佳剧本、最佳电影及最受观众喜爱影片奖。','Strangers shouldn\'t talk to little girls.',950000,7022209,25.918007,6.8,701,103,'2005-01-14','en','/uHTmlcivbPeclEdmtuQg3zOQWPS.jpg',3.4172829471793413,3,'2026-09-10',2,NULL,NULL),(2655,'危机四伏','What Lies Beneath','对于家庭主妇克莱尔（Michelle Pfeiffer 饰）来说，家对她而言早已经不是温馨和安全的所在了。原来，最近家中发生了一些她无法解释的事情，亦出现了一些让她感到恐惧的影像，而当她向丈夫诺曼（Harrison Ford 饰）发出求助信号的时候，诺曼并不相信妻子所说的那些听上去无比荒唐的话语。  发生的更多怪事让克莱尔坚信，有一个幽灵侵入了她平静正常的生活，而那个神出鬼没的幽灵似乎有求于克莱尔。随着时间的流逝，幽灵的真实身份渐渐浮出水面，而让克莱尔吃惊的是，这个幽灵竟和自己的丈夫诺曼有着丝丝缕缕的联系。幽灵究竟想要怎样？丈夫是否如表面上看上去的那样清白？透过心中的迷雾，克莱尔似乎明白了什么。','He was the perfect husband until his one mistake followed them home.',100000000,155464351,15.835672,6.3,488,130,'2000-07-21','en','/rCjDzijUxGR7DQY8HxfvxyPqWs1.jpg',3.2371616401730585,3,'2026-09-10',2,NULL,NULL),(2661,'蝙蝠侠','Batman','蝙蝠侠与罗宾突然收到一个情报，得悉一名大人物正身陷险境，他们正欲展开拯救行动。岂料这原来是小丑、猫女、企鹅、谜语人四名超级份子合作布下的局，他们打算利用仪器把全人类变做灰尘，继而统治全世界！全人类的性命悬于一线，蝙蝠侠与罗宾决定伸张正义，儆恶惩奸，击退坏份子。然而面对天下最聪  明的四大坏蛋连手，要粉碎这计谋真是谈何容易……','He\'s Here Big As Life In A Real Bat-Epic',1377800,0,9.815394,6.1,203,105,'1966-07-30','en','/iBaHizz1sfMs4N03aHsGe7I2G6S.jpg',3.010193410872711,3,'2026-09-10',2,NULL,NULL),(2662,'千尸屋','House of 1000 Corpses','为了对传说中的撒旦博士进行调查，杰瑞（Chris Hardwick 饰）和玛丽（Jennifer Jostyn 饰）、比尔（Rainn Wilson 饰）和丹尼丝（Erin Daniels 饰）这两对情侣驾车行驶在某乡村小路上。他们来到一个荒无人烟的地方，且遭遇狂风暴雨，万般无奈之下，他们躲进了一幢破旧的房子内。  　　当他们进入后发现，这里竟住着一个凶残嗜血且变态失常的邪恶家族。他们的到来，无异于羊入虎口……  　　本片荣获2004年Fangoria（美国恐怖电影杂志）链锯奖最佳男配角奖（Sid Haig）、2004年葡萄牙奇幻国际电影节最佳特效奖。','You\'ll never get out alive.',7000000,16829545,19.301432,6,306,89,'2003-04-11','en','/bUcPIClvK50DBzx3XfD1TjxsdLK.jpg',3.1114465063438033,3,'2026-09-10',2,NULL,NULL),(2666,'移魂都市','Dark City','似乎永无止境的黑夜，笼罩着破败冰冷的现代化大都市，空气中弥漫着不祥的气息。约翰·默多（卢夫斯·塞维尔 Rufus Sewell 饰）在某旅馆的浴缸中醒来，对于之前发生的一切毫无印象，甚至忘记了自己的身份和姓名。神秘的电话、冰冷的尸体以及不明身份的追杀者，这一切都令他无所适从。他凭借仅有的线索开始追查自己的身份以及这一切混乱的肇因。关于这个黑暗世界离奇的一面，也在他的调查中慢慢揭开面纱…… 　　本片荣获1998年美国科幻恐怖电影学院最佳科幻电影奖、1998年阿姆斯特丹奇幻电影节银屏奖、1999年布鲁塞尔国际奇幻电影节佩格萨斯观众奖、1999年澳大利亚影评人协会最佳原创剧本奖。','A world where the night never ends.',27000000,27200316,39.324831,7.2,828,100,'1998-02-27','en','/1cRJqFhnf15wrJtFmsQqknrNmsE.jpg',3.556428680846045,3,'2026-09-10',2,NULL,NULL),(2667,'女巫布莱尔','The Blair Witch Project','1994年十月，三个电影学院的学生——迈克（Michael C. Williams 饰），希瑟（Heather Donahue 饰）和乔什（Joshua Leonard 饰）前往马里兰州的布莱尔小镇，拍摄一部关于女巫布莱尔的纪录片，然而在拍摄过程中三人全部失踪。人们在一年以后，发现了他们留下的电影胶片，记录了他们失踪前发生的一切……\r 　　在布莱尔小镇上，长久以来流传着关于杀害孩子的女巫布莱尔的传说，这里集中的儿童墓地，还有小镇上几乎人尽皆知的古老故事，都印证着女巫的存在。迈克等三名同学，在一个平静的周日展开了对布莱尔故事的追索，可是在他们深入密林的同时，诅咒也开始降临在他们头上。','The scariest movie of all time is a true story.',60000,248000000,41.690578,6.3,1055,81,'1999-07-14','en','/b2mJp7PljRUxVBBGofjPscYAfRE.jpg',3.474099729238894,3,'2026-09-10',2,NULL,NULL),(2669,'叛舰喋血记','The Bounty','本片是叙述十八世纪发生在苍茫大海上的一件感人肺腑的故事，一个基督教徒在蛮荒小岛上希望传播耶稣基督博爱精神，他的工作非常不容易，遭逢土著的阻挠，因为改变宗教的信仰比改变一个人还要困难，但是他并没有丝毫的灰心，还是虽千万人吾往也，他也与土著公主发生了...\r 　　故事发生在一艘名为Bounty的船上，这艘船的目的地在位于大溪地的一座岛屿上，在这里生长着一种能够代替面包的水果，而船长威廉姆（安东尼·霍普金斯 Anthony Hopkins 饰）的最主要任务，就是找到这种水果，并将它带回国。威廉姆是一个非常强势的男人，这让身为大副的克里斯坦（梅尔·吉布森 Mel Gibson 饰）感到非常的不满，但是暴戾的威廉姆动不动就会体罚船员们，甚至不给他们水喝，因此整艘船上的其余人都是敢怒不敢言。\r 　　当威廉姆对船员们的惩罚逐渐升级成为折磨后，再也无法忍受的威廉姆带领着船员们将威廉姆流放了。之后，一群人隐居在小岛上，开始了他们的快乐生活。','After 200 years, the truth behind the legend.',25000000,8613462,7.436491,6.5,108,132,'1984-05-04','en','/hXFXIc6F4NXI5emWCKcUwqEPjIZ.jpg',2.8844880767588883,3,'2026-09-10',2,NULL,NULL),(2675,'天兆','Signs','格雷汉姆·海斯（梅尔·吉布森 Mel Gibson 饰）是美国费城某小镇上一个普通的农场主，一天早上醒来，他和家人意外的发现自己的玉米田里出现了几个一串串紧紧连结在一起的庞大环状神秘图案。这可让格雷汉姆一家吃惊不小，因为玉米田里根本没有任何足迹，看上去像是外星球人的飞船降落的痕迹。很快全世界各地都传出了一夜之间出现神秘图案的消息，人们惊恐万分，惶惶不可终日。全国的媒体、记者和观众也都把焦点以风一般的速度转移到了这个美国南部的小镇，集中到了巴克斯郡的海斯一家。  　　这足有500英尺宽的神秘麦田圈，到底是有人恶意制造的恶作剧，还是乘坐UFO的外星人降临的痕迹，或者是某种灵异事件的结果？只有格雷汉姆发现了一些端倪，决定追查到底......','It’s not like they didn’t warn us.',72000000,408247917,28.848187,6.4,1599,106,'2002-08-02','en','/ywU3XSIkbgGFsjXS1vWGFjoPMsf.jpg',3.56097086355389,3,'2026-09-10',2,NULL,NULL),(2687,'穿墙隐形人','Memoirs of an Invisible Man','尼克（切维·切斯 Chevy Chase 饰）是一名普普通通的地质分析员，每天认认真真、勤勤恳恳地工作，对人生没有一点非分之想。某日，宿醉未醒的他拖着疲惫的身躯，前往研讨会的现场，没想到，过于疲劳的尼克竟然在洗手间里睡着了。不幸的是，当日研讨会上的磁力回旋加速器发生了故障，为了保证参会人员的安全，主办方决定全员撤离，却独独忘记了还在洗手间里酣睡的尼克。  　　就这样，尼克成为了机械故障的唯一一名幸存者，然而，没有一个人知道这件事情，因为当尼克一觉醒来之时，他已经因为磁场的异变而变成了一名隐形人！一时间，尼克的生活发生了翻天覆地的变化。','An adventure like you\'ve never seen.',40000000,14358033,7.222985,5.7,125,99,'1992-02-28','en','/yijMoBFOLxLypQI2r7mDbbRZftg.jpg',2.8823362534460664,3,'2026-09-10',2,NULL,NULL),(2698,'冒牌天神2','Evan Almighty','曾在直播节目中大出其丑的主播埃文·巴克斯特（史蒂夫·卡瑞尔 Steve Carell 饰）走下演播台，开始转战政界，并成功当选布法罗的议员。他努力打造自己的良好形象，以“改变世界”的口号赢得选民的支持，同时这也是夜晚睡前祈祷的内容。在此之后，埃文带着一家四口人来到弗吉尼亚州的亨茨维尔小镇居住，即将展开全新的政坛生活。埃文的仕途顺风顺水，刚刚走马上任就得到呼风唤雨的朗议员（约翰·古德曼 John Goodman 饰）的器重，成为最新议案的共同发起人。正在这关键时刻，上帝（摩根·弗里曼 Morgan Freeman 饰）却突然出现在埃文面前，他只被要求干一件事，那就是建造一艘方舟。埃文的生活自此起了翻天覆地的变化…','A comedy of biblical proportions',175000000,173000000,27.082182,5.3,1151,96,'2007-06-09','en','/wN1nhaqRanMuiRu9BNmUAljWTxi.jpg',3.277072546931726,3,'2026-09-10',2,NULL,NULL),(2749,'千钧一刻','15 Minutes','警探艾迪（罗伯特•德尼罗 Robert De Niro 饰）是纽约的知名人物，他长期在媒体上出镜为公众带来案件实况。两名出狱不久的东欧男子埃米尔（卡瑞尔•罗登 Karel Roden 饰）和奥列格来到纽约，他们找到背叛了自己的同伙，将其杀死后把现场付之一炬，崇拜美国电影的奥列格更把整个过程拍了下来。艾迪在被焚毁的现场遇到纵火调查员乔迪（爱德华•伯恩斯 Edward Burns 饰），后者的干劲令艾迪瞩目，随即两人开始合作。埃米尔和乔迪都发现了目击证人达芙妮的存在，双方展开了寻找达芙妮的竞争，期间埃米尔和奥列格又杀一人，艾迪颇感被动。终于，艾迪和乔迪在达芙妮工作的店中正遇两名嫌凶，艾迪将埃米尔击伤，而这令埃米尔把下一个目标锁定为艾迪……','America Likes to Watch',60000000,56359980,15.205371,5.7,191,120,'2001-03-01','en','/qXwyeBGEp9ZfusBnYcYGI6uBvAe.jpg',2.9844508385369815,3,'2026-09-10',2,NULL,NULL),(2752,'禁欲40天','40 Days and 40 Nights','对于甜蜜的恋爱，马特（乔什·哈奈特 Josh Hartnett 饰）也曾有过梦幻的憧憬，而屡屡遭遇的失败爱情却让他对女人这种难缠又奇怪的生物彻底的死了心。在又一次残酷被甩之后，悲痛欲绝的马特做出了一个对于所有男人来说都无比沉重的决定——禁欲40天。在这不近女色的40天中，马特希望自己能潜心修炼，最终成为一个无欲则刚的优秀青年。\r 　　而就在禁欲的生活让马特觉得神清气爽的时候，那个名叫艾瑞卡（莎妮·索萨蒙 Shannyn Sossamon 饰）的美丽女孩来到了他的身边。虽然被艾瑞卡迷得神魂颠倒，但马特并没有忘记自己最初的誓言，更何况自己的周围有一群损友都在等着看自己的笑话。扳着手指头，马特觉得时间似乎走得越来越慢。 ©豆瓣','Easier said than done.',17000000,0,14.18136,5.2,297,94,'2002-03-01','en','/fYnqQdGXOKER1qNb3JQqYuFtVku.jpg',3.0239867138578136,3,'2026-09-10',2,NULL,NULL),(2755,'关于施密特','About Schmidt','沃伦·施密特（杰克·尼科尔森 饰）同时走到了人生的多个十字路口。失业、丧偶、无家人陪伴，他绝望地试图在自己毫无亮点的一生中寻找意义。他驾驶一辆35英尺长的房车，穿越内布拉斯加州踏上寻根之旅，开启了一段自我发现的旅程。[新线影业]','Schmidt Happens',30000000,105834556,19.925026,6.7,362,125,'2002-12-13','en','/tstvsrJHY57hc951lb190alXRQm.jpg',3.217748927863104,3,'2026-09-10',2,NULL,NULL),(2756,'深渊','The Abyss','当一架美国核子潜艇的队员在雷达荧幕上发现一件不明物体之际，潜艇突然被撞击，沉没于一个无底深渊，由巴德为首的钻油工人奉命前往拯救潜艇队员，这群拯救队伍还包括科菲中尉率领的水底军事专家，科菲中尉的秘密任务是找回艇上的150枚核弹头，然而当拯救队到达了一个位于水面下2000多英尺深的石层上时，遇到了种种前所未有的困难。先是海面上的风暴和器材的不足给工作带来阻碍，然后是潜水仓周围有奇怪的物体出现给人带来混乱，在万分危机的时刻，科菲中尉却因为一意孤行而导致一枚核弹坠向暗藏不明生物的深渊……','There\'s everything you\'ve ever known about adventure, and then there\'s The Abyss.',70000000,90000098,24.961625,7.1,808,139,'1989-08-09','en','/2DnoRYvGlaRsgl117Lp9xJ8eAjQ.jpg',3.5005530690656768,3,'2026-09-10',2,NULL,NULL),(2757,'改编剧本','Adaptation.','在这部改编自畅销书《兰花窃贼》的电影中，编剧查理·考夫曼（尼古拉斯·凯奇 饰）、作家苏珊·奥尔琳（梅丽尔·斯特里普 饰）与兰花偷猎者约翰·拉罗什（克里斯·库珀 饰）的生活奇妙地纠缠在一起——他们各自对激情的追寻在此相互碰撞。','From the creator of Being John Malkovich, comes the story about the creator of Being John Malkovich.',19000000,32801173,26.441669,7.3,638,114,'2002-12-06','en','/ffEmHQAiD0m5dEQ6rlsuA9vlllW.jpg',3.4632523542030587,3,'2026-09-10',2,NULL,NULL),(2770,'美国派2','American Pie 2','在经历了高中毕业晚会激情一夜后，一年很快过去了。大一的暑假，吉姆（贾森•比格斯 Jason Biggs 饰）、凯文（托马斯•伊恩•尼古拉斯 Thomas Ian Nicholas 饰）、奥兹（克里斯•克莱因 Chris Klein 饰）和芬奇（艾迪•凯伊•托马斯 Eddie Kaye Thomas 饰）四个好友又聚在一起了，当然，还有不怎么讨人喜欢的史蒂夫（西恩•威廉•斯科特 Seann William Scott 饰）。\r 四个好友决定摆脱史蒂夫，去过一个激情的暑假，庆祝他们顺利度过大一和伟大的友谊。但是史蒂夫在海边有一栋别墅，那是玩乐的最好场所，无奈他们只有带上史蒂夫一起驶往海边。\r 经历了大学一年后，他们都比高中时更成熟了。海边美女如云，他们面临了更大的激情挑战，笑话百出。海边的狂欢舞会即将拉开，每人都在努力准备。','This Summer It\'s All About Sticking Together.',30000000,287553595,36.432598,6,1344,108,'2001-08-10','en','/8Rxp85Kd3Gz7R9Br9hBN6tGJLgV.jpg',3.4594544026505245,3,'2026-09-10',2,NULL,NULL),(2771,'美国荣耀','American Splendor','这是一个工人阶级普通人追寻不加掩饰的自我表达的真实传奇——他最终赢得了知音的观众、评论界的赞誉，以及最非凡的幸福结局：一个充满爱的家庭。[Fine Line Features]','Ordinary life is pretty complex stuff',0,6003587,7.792851,7.1,120,101,'2003-08-15','en','/rPLMxuk82AiqDiwEUVJ6E7WpjYs.jpg',2.934871799413162,3,'2026-09-10',2,NULL,NULL),(2779,'玉蝎子的魔咒','The Curse of the Jade Scorpion','CW•布里格斯（伍迪•艾伦饰）是20世纪40年代美国纽约著名的北海岸保险公司的最出色的保险调查员，他的拿手绝活是能窥探犯人心中所想，从而轻而易举地破案。自从老板请来了“效率专家”贝蒂，这一切就改变了。贝蒂新官上任，带来新的策划新的管理方式，布里格斯成为被开刀的第一人。二人之间火药味甚浓。在同事乔治的生日会上，他俩被魔术师叫上台，在玉蝎子的魔力下，二人被催眠，醒来后对刚才发生的事一无所知。之后城内接二连三发生珠宝盗窃事件，而被窃珠宝的报警装置是布里格斯亲手设置的，没有他是不可能破开的。在调查案件中，肯辛顿家的尤物女儿（查理•塞隆饰）主动约他约会，他怀疑她的动机。而贝蒂请来侦探协助他调查让他更为不快。贝蒂是上司的情人，因为老板迟迟不肯跟妻子离婚而倍感伤心。神使鬼差走到了布里格斯家跟他倾诉，布里格斯怀疑是贝蒂泄漏了公司机密，随后贝蒂对他的示爱更令他加深怀疑。 要在一系列欢笑嬉闹中，最后才想起一切缘自当初的那个玉蝎子的魔法，这些盗窃案最后还撮合了一对天作之合。','Love stings',0,0,9.317265,6.5,165,103,'2001-08-05','en','/mfvWefUp09oaLLxb8KhsvUYi7mX.jpg',2.9865821313932925,3,'2026-09-10',2,NULL,NULL),(2786,'狂人皮埃罗','Pierrot le fou','费迪南德（让-保罗·贝尔蒙多 Jean Paul Belmondo 饰）经受着一段糟糕的婚姻，又不幸被公司开除。他在一个无趣的聚会上遇见前女友玛丽安娜（安娜·卡里娜 Anna Karina 饰），重燃旧情。厌烦一切的他决定抛妻弃子同她一起逃离。他跟着玛丽安娜去了她的公寓 ，发现一具尸体，接着很快发现她正在被黑帮追杀。在相处期间，玛丽安娜给费迪南德取了个昵称：皮埃罗。他们开车奔向南方，一路上疯狂抢杀。当他们到了法国，两人关系开始紧张。皮埃罗不再读书、思考、写日记，玛丽安娜也厌倦了这种生活，坚持要回城里。他们在一个夜店里遇到黑帮，混乱中两人失散了。皮埃罗疯狂寻找玛丽安娜，两人最终重聚。玛丽安娜利用皮埃罗得到一箱钱，之后逃走去找自己真正的男友——之前她多次提到的哥哥。皮埃罗开枪打死玛丽安娜和她的男友，将自己的脸涂成蓝色，身上绑上炸药。最后一秒，他后悔了，试图摁灭导火索，但是失败了，炸药砰地一声爆炸了。\r 　　本片获得1965年威尼斯电影节金狮奖提名。',NULL,300000,0,7.791898,7.6,127,110,'1965-08-29','fr','/eBfWgh4txJ255meWlHj6bJvKxKS.jpg',2.9714325293635606,3,'2026-09-10',2,NULL,NULL),(2787,'星际传奇','Pitch Black','在浩瀚的宇宙间，一艘名为猎人号的商用飞船正进行着漫长的旅程。船上搭载着40位乘客，其中包括重刑罪犯理查·雷迪克（Vin Diesel 饰）。当行驶到丹吉尔星系时，突如其来的事故令飞船遭受重创，空气飞速泄漏，最终迫降到一颗炎热而荒凉的星球上。着陆时的巨大冲击力几乎让飞船支离破碎，死伤者众多。幸存者们来到这片陌生的国土，严酷的自然环境考验着每一个人，不同民族不同职业的他们此时必须捐弃前嫌，联合起来。他们不仅要与天空中三个太阳作抗争，还要时刻提防隐藏在黑暗中的危险……  　　本片荣获2001年澳大利亚摄影师协会年度最佳摄影师和金三角架奖。 ©豆瓣','Don\'t be afraid of the dark. Be afraid of what\'s in the dark',23000000,53187659,18.493202,6.7,1789,108,'2000-02-18','en','/ubP0DgqDsPy0RjRScjNxAbKrQcn.jpg',3.6276792283800567,3,'2026-09-10',2,NULL,NULL),(2789,'星际传奇2','The Chronicles of Riddick','故事接着上一集的5年之后，在未来的星际世界，经过降落酷热星球上的劫难后，喜欢在星际冒险的李迪克(文•迪塞尔 饰)虽然摆脱了黑暗的控制，暂时逃脱了赏金猎手的追捕，却惊恐地发现自己陷入了一场声势浩大的星际大战之中。他自己也被一个宗教恶势力抓获，这个26世纪宗教战队“第10十字军”的头目，就是被称为“星际之王”的大恶棍洛德•马歇尔(科姆•菲尔 饰)，也正是他发起了一系列的星际大战。被俘虏后度过了一段黑暗的日子，李迪克幸得“第四元素”种族的大使亚伦(朱迪•丹奇 饰)救出，并帮助他找回了身世之迷。一次意外的遭遇，使李迪克再次被困在一座地下监狱里，在那里他见到了上一集在酷热星球上认识的那个女孩——基拉——现在已经长成个大女孩了(艾莉莎•黛娃洛丝 饰)。此时，整个宇宙星际正笼罩在马歇尔的黑暗统治下，他的“第10十字军”军团在各个星系各个星球间横行霸道，笼络更多...','All the power in the universe can\'t change destiny',105000000,115772733,27.835436,6.3,1570,119,'2004-06-11','en','/bzWcAhkhVYvOZTXZJNDkmqBOH6X.jpg',3.5338529302795108,3,'2026-09-10',2,NULL,NULL),(2830,'My Boss\'s Daughter','My Boss\'s Daughter','When a young man agrees to housesit for his boss, he thinks it\'ll be the perfect opportunity to get close to the woman he desperately has a crush on – his boss\'s daughter. But he doesn\'t plan on the long line of other houseguests that try to keep him from his mission. And he also has to deal with the daughter\'s older brother, who\'s on the run from local drug dealers.',NULL,14000000,0,14.813614,4.4,180,83,'2003-08-21','en','/6z6ehjP1GyMLFeja9pHGGZb9B2.jpg',2.894656001445174,3,'2026-09-10',2,NULL,NULL),(2832,'致命ID','Identity','一个典型而又引人入胜的悬疑故事：一个汽车旅馆里，住进了10个人，他们中间有司机、妓女、过气女星、夫妇、警探和他的犯人，还有神秘的旅馆经理。这天风雨大作，通讯中断，10人被困在了旅馆里，惊悚的故事开始了。\r 他们一个接一个的死去，并且按照顺序留下牌号。10个人存活下来的渐渐变少，他们开始恐慌，互相猜忌，却无意间发现了彼此间的联系。但是，大家怀疑的嫌疑人却纷纷死去，谜团笼罩在旅馆狭小的空间里，这样的凶杀案件却有着人们猜不到的真相……','The secret lies within.',30000000,90259536,45.915165,7.1,1061,90,'2003-04-25','en','/p59g3NUxuOK4ghPqblA5e3k26sv.jpg',3.6273590750725218,3,'2026-09-10',2,NULL,NULL),(2841,'A Very Long Engagement','Un long dimanche de fiançailles','In 1919, Mathilde was 19 years old. Two years earlier, her fiancé Manech left for the front at the Somme. Like millions of others he was \"killed on the field of battle.\" It\'s written in black and white on the official notice. But Mathilde refuses to believe it. If Manech had died, she would know. She hangs on to her intuition as tightly as she would onto the last thread of hope linking her to her lover. A former sergeant tells her in vain that Manech died in the no man\'s land of a trench named Bingo Crepescule, in the company of four other men condemned to die for self-inflicted wounds. Her path ahead is full of obstacles but Mathilde is not frightened. Anything is possible to someone who is willing to challenge fate...','Never let go',47000000,0,23.05451,7.1,346,133,'2004-10-26','fr','/3E1RD1EmGsyFL7X8QPnqfIgmQFG.jpg',3.251999445621785,3,'2026-09-10',2,NULL,NULL),(2895,'来自天上的声音','The Apostle','他被力量触动，被圣灵充满。他是信仰的使者，亦是血肉之躯。一个被人类欲望的暗面与怒火所困之人。罗伯特·杜瓦尔饰演桑尼，一位深受社区爱戴、才华横溢的南方传教士。当桑尼失控犯下激情之罪后，他被迫逃离法律制裁。藏身于巴尤布特小镇的他，伪装新身份，踏上一段寻求救赎之路的使命。[环球影业]','The hardest soul to save was his own.',5000000,0,4.227807,6.1,38,134,'1997-10-09','en','/9KqCzLhWbFMBPjqRpZ69izRiYgG.jpg',2.638784299433316,3,'2026-09-10',2,NULL,NULL),(2898,'尽善尽美','As Good as It Gets','作家梅尔文是一个脾气古怪的强迫症老头，没有家庭也没有朋友，整天关在屋里写他的第六十二部小说，生活如时钟般精准，受不了一点的打扰。梅尔文的邻居西蒙是年轻的同性恋画家，养了一条可爱的小狗，生性活泼，脾气温和，经常受到梅尔文的侮辱。梅尔文每天只出门一次，到同一家餐厅吃饭，餐厅女招待卡罗尔·康奈莉是唯一愿意而且能够为他服务的人。离了婚的卡罗尔与儿子斯潘塞住在一起，斯潘塞患有严重的哮喘病，这使得许多对卡罗尔有意思的男子知难而退。一天，西蒙的住所遭到抢劫，西蒙身受重伤，住院前，将小狗托付给梅尔文照料，梅尔文渐渐喜欢上了这个小家伙，心理也发生了变化，开始关注周边的世界，主动帮助别人，认真审视自己对卡罗尔的好感……','A comedy from the heart that goes for the throat.',50000000,314178011,37.885022,7.2,915,139,'1997-12-19','en','/8b5UsCqg2f4WWkcRlh34RApWCYW.jpg',3.582892621753562,3,'2026-09-10',2,NULL,NULL),(2900,'太空异种','The Astronaut\'s Wife','居住在休士顿的阿玛考斯特夫妇生活安逸幸福，妻子吉莉安（查理兹·塞隆 Charlize Theron 饰）是一名小学教员，丈夫史宾塞（约翰尼·德普 Jonny Depp 饰）则是供职于太空总署的宇航员。为了维修故障卫星，史宾塞和老搭档艾力克斯·史瑞克（Nick Cassavetes 饰）进入地球轨道。然而原本简单的任务却突发事故，故障卫星爆炸，导致两人与地球失去联系长达两分钟之久。所幸他们并无大碍，最终还是安全回到地球。  　　在此之后，史宾塞和艾力克斯对那神秘的两分钟绝口不提，吉莉安也从他们的沉默中预感到什么。就在史宾塞决定辞职和妻子搬到纽约前不久，艾力克斯与妻子娜塔莉（Donna Murphy 饰）相继暴亡。吉莉安对此深感不安，她隐隐感到某些不祥的事件将发生在她和丈夫的身上…… ©豆瓣','How well do you know the one you love?',75000000,19598588,20.697556,5.4,254,109,'1999-08-26','en','/54RGJ6INW9ERG8IaalmMKbbDgwH.jpg',3.029057935268753,3,'2026-09-10',2,NULL,NULL),(2907,'亚当斯一家','The Addams Family','亚当斯庄园里住着一个典型哥特式家庭。戈梅斯（劳尔·朱力亚 Raul Julia 饰）和妻子（安杰丽卡·休斯顿 Anjelica Huston 饰）终年生活在这里，到处弥漫阴郁腐败的气息。二人感情如蜜，有一双喜欢玩谋杀游戏的儿女。戈梅斯的心里，却埋藏着一个伤疤。那就是他曾经和哥哥费斯特失和，费斯特已经失踪25年，戈梅特仍然放不下对哥哥的惦念。  一心要夺取亚当斯庄园和这里的财富的母亲有一个儿子戈登（克里斯托弗·洛伊德 Christopher Lloyd 饰），貌相跟费斯特相向。于是，一场阴谋上演了，她教唆戈登佯装费斯特潜入亚当斯庄园，利用戈梅斯的兄弟情一步一步地夺取庄园。','Weird Is Relative',30000000,191502426,37.179547,6.7,848,99,'1991-11-22','en','/5kPsSI6VIrqp7EwocWKxCjm6TNJ.jpg',3.4779533459577188,3,'2026-09-10',2,NULL,NULL),(2925,'前妻俱乐部','The First Wives Club','三位大学好友布兰达（贝特•米德勒 饰）、埃利斯（歌蒂•韩 饰）、安妮黛安•基顿 饰）离开大学后各奔前程。但她们的婚姻是相似的，她们各自的丈夫都爱上了别的女人。虽然她们都把青春贡献给了自己的丈夫，协助丈夫名成利就，但她们还是无可避免都被丈夫抛弃了，成为了弃妇。\r 　　三位昔日的好友成为了彼此之间的倾诉对象，难免得同病相怜一番。而她们更做出了一个重要的决定，团结一致的她们要对她们无情的丈夫们实行报复，组成了一支“前期俱乐部”，务求成功执行她们的计划……','Don\'t get mad. Get everything.',26000000,116400000,10.704596,6.5,166,102,'1996-09-20','en','/2ApifgYnfdJUSmCKzTBrWOYYWsn.jpg',2.9911611981933324,3,'2026-09-10',2,NULL,NULL),(2959,'结婚证书','License to Wed','本·墨菲（约翰·克劳辛斯基 John Krasinski 饰）和莎蒂·琼斯（曼蒂·穆尔 Mandy Moore 饰）是一对彼此深爱对方的情侣，他们的爱情充满浪漫和温馨，顺理成章两人也即将走入婚礼殿堂。莎蒂希望在与她的家族渊源颇深的圣•奥古斯汀教堂举行婚礼，但是这恐怕是一个糟糕的决定。这间教堂的弗兰克牧师（罗宾·威廉姆斯 Robin Williams 饰）看似和蔼可亲，却是个极为苛刻和奇怪的家伙。他对年轻男女贸然进入婚姻又选择逃避感到痛心疾首，因此弗兰克坚持任何一对来他的教堂举行婚礼的情侣都要接受婚前准备课程。未能通过该课程的情侣，弗兰克将有权取消婚礼。  　　看似只是例行的公事，却发现实行起来障碍重重。感情一向顺风顺水的本和莎蒂，将迎来走入教堂前的最大挑战……','First came love... then came Reverend Frank.',35000000,69307224,14.503568,5.2,253,91,'2007-07-04','en','/i4K9wF8tnPRlx9GLGzclGko9uPj.jpg',2.998750705178095,3,'2026-09-10',2,NULL,NULL),(2976,'Hairspray','Hairspray','Pleasantly plump teenager, Tracy Turnblad and her best friend, Penny Pingleton audition to be on The Corny Collins Show – and Tracy wins. But when scheming Amber Von Tussle and her mother plot to destroy Tracy, it turns to chaos.','When you follow your own beat, the world will follow you.',50000000,90450008,31.160542,6.5,709,117,'2007-07-13','en','/kUcUER1zaGdqSfIazh6wHMyBNcM.jpg',3.387911694560686,3,'2026-09-10',2,NULL,NULL),(2977,'成为简·奥斯汀','Becoming Jane','简•奥斯汀（安妮·海瑟薇 Anne Hathaway 饰）的一生是否如她的文字那样充满曲折的过程和完满的结局？《成为简》用传记方式描述她的一生：她的母亲竭力为她撮合婚事，对象是上层社会的有钱人。但是简不接受没有爱情的婚姻，认为女人要靠自己的能力去养活自身。于是，她拒绝贵族瓦斯莱先生的求婚，爱上了心灵相通的汤姆•勒弗罗伊（詹姆斯·麦卡沃伊 James McAvoy 饰）。\r 　　好事多磨，有人从中作梗，导致汤姆家人并不赞成二人婚事，汤姆决定携简私奔。但是这样一来，汤姆的经济来源就会被切断，简亦将面临着世俗的压力和贫困的生活。到底二人在私奔路上会走得多远？会不会有美满的结局？','Her own life is her greatest inspiration.',16500000,37311672,18.236284,6.9,317,120,'2007-03-02','en','/1dw7k9KJxfXzkqFPdnCjpt0VIit.jpg',3.198278151295643,3,'2026-09-10',2,NULL,NULL),(2989,'咆哮','Roar','制作了超过十年的过程中，咆哮是一个大胆的电影实验：惊悚片展示的威严和非洲狮的凶猛，拍摄地点几十之中使用普通的演员，而不是特技实际未经过培训的大型猫科动物。编剧/导演诺埃尔·马歇尔明星汉克，在非洲的医生，刚直不阿博物谁允许狮子，老虎，猎豹和其他大型猫科动物自由地漫游在他的遥控房地产。虽然离保护动物免受盗猎者，汉克的家庭（包括马歇尔的现实生活中的妻子和女儿，蒂皮赫德伦和梅兰妮·格里菲斯），到达他的家，由具有溢出的房子大量石狮大步。','No animals were harmed in the making of this movie. 70 members of the cast and crew were.',17000000,2000000,1.15641,5.6,19,102,'1981-11-12','en','/7AoDfoRDQ0hfoyasvl0J2PIFUJ0.jpg',2.483029637119075,3,'2026-09-10',2,NULL,NULL),(3021,'幻影凶间','1408','他不相信，不相信这个世界上有鬼，不相信人死后会有灵魂，不相信上帝……他只相信自己双眼看到的一切，眼见为实，眼睛是鉴别真伪的最有力武器。他是恐怖小说家迈克·安瑟林，在文学界积累的名气则来自于他的作品中对一系列恐怖事件客观而中肯的剖析与见解。最近小说界流行着这样一个约定俗成的风向标：只要这本小说是对一个闹鬼的房间或墓地进行不负责任的胡说八道，肯定畅销，因为这种超出正常范围的灵异事件，往往能够满足读者永无止境的猎奇心理。迈克最近也在忙叨着一本这种类型的恐怖小说，然而苦于没有供参考的实例，迈克总感觉自己的故事中缺乏相应的灵魂。所以在惊闻发生在纽约海豚酒店的闹鬼事件之后，迈克迅速收拾行囊，登记入住到酒店里，不顾大堂经理奥林先生的警告，硬是住进了那间据说被鬼魂霸占了的1408室，成了这个房间许多年来的第一位客人……其实迈克心里自有他的如意算盘，根据以往的经验，他认为房间的闹鬼事件是经理伙同员工共同捏造出来的假消息，目的很简单，想通过这种方法吸引更多的客人慕名前来，他决定借助发生在这个房间的事件为自己小说结尾的一章提供素材，同时还可以揭发海豚酒店的卑鄙行为，让他们功亏一篑。然而这一次，迈克却彻底地想错了，住在1408室的几个晚上成了他一辈子都挥之不去的梦魇，让他从一个无神论者变成了彻头彻尾的信徒，每一个晚上他都在与恶魔不停地缠斗——对于迈克来说，现在最重要的不是创作出一部畅销小说，而是如何活命。','The only demons in room 1408 are those within you.',25000000,94679598,35.169779,6.5,1343,104,'2007-07-12','en','/uiuM6l2PB2yBgrbn3BV0eRcyaVF.jpg',3.5536657393922253,3,'2026-09-10',2,NULL,NULL),(3028,'疯狂医生','Jekyll and Hyde... Together Again','杰基尔医生吸入白色粉末，变成了一个讨厌的南加州人。','The comedy that examines modern living through chemistry',0,0,0.805312,4.6,5,87,'1982-11-10','en','/o3CTFJuHGEBE9UzyXjGX6Vy74aC.jpg',2.2216039401622174,3,'2026-09-10',2,NULL,NULL),(3033,'众神与野兽','Gods and Monsters','本片讲述好莱坞著名大导演詹姆斯·威尔（伊安·麦克莱恩 Ian McKellen 饰）1957年的最后人生。这位创造影史最惊悚角色“科学怪人”的导演已淡出电影界， 正潜心研究绘画，闲时仍与一些男子频频约会。当管家汉娜（琳恩·雷德格瑞夫 Lynn Redgrave 饰）录用了新园丁、身强力壮的前海军陆战队成员布恩（布兰登·费舍 Brendan Fraser 饰）后，威尔的兴趣渐渐全部转移到布恩身上。威尔象一只爬向苍蝇的蜘蛛一样一点点接近布恩，引领后者一步步走进精心设计的圈套。原来威尔虽然已停止拍片，但自从见到布恩后，他发现布恩同自己片中的主角弗兰肯斯坦极为相似——不善言辞、单纯质朴且难以理解。威尔感到自己无法冷却心中的热爱，只有布恩才能解除他的痛苦，他的计划就是诱使布恩最终杀死他本人，从而得以亲手实现一生中最完美的电影情节......\r 　　本片通过年老好莱坞名导与年轻园丁的微妙接触，以及由此触发过往回忆的碎片，娓娓刻画奇妙而复杂的同性情愫，勾勒出一个友谊、尊重、爱恋、抗拒、厌恶、恐惧等情感荡涤的世界。影片不断穿插《科学怪人》的电影画面和台词，它巧妙地暗合了同性恋与科学怪人共同的被歧视性地位和恐惧处境。导演戏谑而平静的虚实铺陈出一位同性恋导演的最后生命旅程，堪称黑色喜剧的杰作。《众神与野兽》获当年奥斯卡最佳改编剧本奖，同时入围最佳男主角、最佳女配角。本片也是以“甘道夫”形象风靡世界的伊安·麦克莱恩爵士演艺生涯中最重要也是最出色的一次演绎。 ©豆瓣',NULL,10000000,6451628,5.588652,6.8,81,105,'1998-01-21','en','/awvJH3NtXoStsjAtXKr99hfuVaG.jpg',2.8240911661128907,3,'2026-09-10',2,NULL,NULL),(3034,'新科学怪人','Young Frankenstein','在这部对恐怖片的戏谑模仿中，那位恶名昭彰的弗兰肯斯坦博士的孙子，心不甘情不愿地决定追随祖父的脚步。','The scariest comedy of all time!',2800000,86273333,36.444894,7.7,854,106,'1974-12-15','en','/3BvvVKPg9yucChlSvQtJxAbLmj9.jpg',3.6400160611480388,3,'2026-09-10',2,NULL,NULL),(3040,'守夜人','Ночной дозор','世界上充满了异类生物。这些异类有光明的，也有黑暗的。他们可以进入冥界，可以完成被人类称为魔法的种种行为。一千年前，代表光明的军队与代表黑暗的军队狭路相逢，展开了一场恶战。双方势均力敌，为了避免两败俱伤，双方签订了一项为期一千年的合约和几项模糊的协议。  时光荏苒，一千年后，两支军队的首领-格谢尔(符拉季米尔门少夫饰)和扎乌龙(维克多尔维尔热宾茨基饰)生活在今日的莫斯科。其他的巡查队员都在他们的领导下工作。守夜人跟踪黑暗的异己势力，他们的使命是维持善与恶之间的平衡；而守日人的工作则是监视光明力量的活动，一旦善恶比例失衡就会引起战争、革命、毁灭甚至全世界的灾难。','All That Stands Between Light And Darkness Is The Night Watch.',4200000,32000000,12.540624,6.3,210,114,'2004-06-27','ru',NULL,3.0371491269735937,3,'2026-09-10',2,NULL,NULL),(3049,'神探飞机头','Ace Ventura: Pet Detective','王牌•威龙（金•凯瑞 饰）是一位专与动物打交道的宠物侦探，以帮人寻找丢失的宠物为生。在橄榄球大赛即将来临时，迈阿密海豚队的吉祥物——海豚“雪花”遭到了绑架。这无疑会大大影响到队员们的士气。无奈之下，球队经济人麦提莎小姐找来了王牌•威龙以找回失去的海豚。王牌•威龙用自己的方式对事件展开了彻底的调查，虽然期间笑料不断，时时受到女警官艾露丝的阻挠，但也找到了很多的线索，麦提莎小姐也逐渐被他的风趣与机敏所打动，开始对他刮目相看。就在王牌侦查工作慢慢接近事实真相的时候，海豚队的另一个经纪人普罗杰在家中跳楼自杀，队员马连奴又被绑架了，好不容易锁定的犯罪嫌疑人也神秘失踪了，案情更加的扑朔迷离。','He\'s the best there is! (Actually, he\'s the only one there is.)',15000000,107217396,41.249004,6.4,1648,86,'1994-02-04','en','/5A5BNqUJFk8RS2PBBzHNZJt0eZt.jpg',3.596403495092043,3,'2026-09-10',2,NULL,NULL),(3050,'怪医杜立德','Doctor Dolittle','杜立德医生（艾迪·墨菲 Eddie Murphy饰）拥有一个幸福的家庭，一个小有名气的诊所，没有人知道他曾经有着异常的经历，那就是能够听懂动物的说话。小时候，他就和猫狗马驴之类的动物交谈过，了解动物的需要，知道它们的心事。随着岁数增长，杜立德医生早已失去了这个“特异功能”。然而，他却因为一次开车差点撞上路边的小狗，似乎又能听到了小狗骂他笨蛋。这下子杜立德的生活可热闹起来了，因为他沉睡已久的动物语言天赋又被重新唤醒，阿猫阿狗不但成为了他的朋友，还主动找上门来找杜立德医生看病。诊所变成了熙熙攘攘的动物世界，而生意也因此陷入低迷。人人都以为杜立德疯了，家人对他的行为也非常的不理解，杜立德医生和他的诊所面临着不小的挑战。','He doesn\'t just talk to the animals!',71000000,294456605,21.462935,5.4,686,85,'1998-06-22','en','/tLrchGMIkdo1KamQJA6fwvDQEy0.jpg',3.197601672537103,3,'2026-09-10',2,NULL,NULL),(3059,'党同伐异','Intolerance: Love\'s Struggle Throughout the Ages','一位贫困少妇因社会偏见被迫与丈夫、婴孩分离的遭遇，与人类历史上诸多关于偏狭迫害的故事古今交织。','The Cruel Hand of Intolerance',385907,8394751,3.232447,7.4,60,197,'1916-09-04','en','/1SzJmhqKVs5j3LrJb5CWwBP0GXL.jpg',2.7632222279431113,3,'2026-09-10',2,NULL,NULL),(3060,'战地之花','The Big Parade','第一次世界大战的末期，美国派兵赴欧洲参战，富家子弟吉姆(约翰·吉尔伯特 饰)也加入了军队，在部队中跟建筑工人出身的斯利姆和酒保布尔很快成为了好友。部队在法国登陆，驻扎在一个小村庄里。在那里，吉姆认识了法国村姑梅丽桑德(蕾妮·阿多莉 饰)，两人很快燃起了爱火。不久，部队奉命开赴前线，吉姆被迫离去。梅丽桑德在军用卡车后紧追不舍，吉姆脱下军靴抛给她，表达自己对她的爱意。  　　在前线，炮火密集，吉姆、斯利姆和布尔躲在炮弹坑中十分着急。经过抽签，由斯利姆冲出坑外对付敌人的大炮。炮声停止了，但斯利姆一直没有回来。吉姆十分担心，往敌阵中寻找，果然发现了斯利姆的尸体。  　　美军进行大规模反攻，吉姆奋勇作战，结果因腿部中弹而住进野战医院。在那里，他听说梅丽桑德所在的村庄处境十分危险，于是偷偷溜出医院赶到村庄，却发现该地已成一片废墟……',NULL,245000,22000000,0.785744,7,21,151,'1925-11-05','en','/8aBXJEkAHcwG2ghNYh6GIFd9ool.jpg',2.514248278525474,3,'2026-09-10',2,NULL,NULL),(3062,'第四十二街','42nd Street','一位导演筹备他可能最后一场的百老汇演出，恰在此时，一位天真的新人不得不临危受命，顶替明星登场。',NULL,439000,2281000,1.933366,6.1,37,89,'1933-02-02','en','/q4UEd8BL74zVsOOaJkKVMLMmdTg.jpg',2.62790753598961,3,'2026-09-10',2,NULL,NULL),(3078,'一夜风流','It Happened One Night','在这部由弗兰克·卡普拉打造的浪漫公路喜剧中，截然相反的两人以磁石般的吸引力彼此靠近——一位骄纵逃家的富家女（克劳黛·考尔白 饰）与一位玩世不恭的平民记者（克拉克·盖博 饰）相遇，后者一心要挖掘她失踪背后的绯闻真相。作为影史首部一举囊括奥斯卡五项核心大奖（最佳影片、最佳男主角、最佳女主角、最佳导演、最佳改编剧本）的罕见佳作，本片在有声电影初期以其精妙的结构与剪辑独树一帜。片中无数巧思情境与幽默桥段早已跻身好莱坞喜剧经典宝库，两位巅峰状态的演员火花四溅的化学反应，至今仍为影史佳话。','TOGETHER... for the first time',325000,4500000,11.871424,7.7,275,105,'1934-02-22','en','/rbkiTF8g6rCcIY7aqVPLjoAiBhg.jpg',3.2118657330402804,3,'2026-09-10',2,NULL,NULL),(3080,'礼帽','Top Hat','一位美国舞者来到英国，对一位模特一见倾心——尽管初次相遇便惹恼了对方，而她却将他误认作他那傻气十足的制片人。','They\'re Dancing Cheek-To-Cheek Again!',609000,3202000,3.898498,7.4,59,101,'1935-09-06','en','/qoPBiN6PBs2NsP7BNOJGCnmwruG.jpg',2.760701174438892,3,'2026-09-10',2,NULL,NULL),(3082,'摩登时代','Modern Times','二十年代的美国处于经济萧条时期，失业率居高不下，工人受尽压榨，成为了大机器生产中的一颗螺丝钉。查理就是一个底层市民，他在一个机器隆隆的厂房里日以继夜地工作，以赚取微薄的收入。重复繁重的工作压得他喘不过气，他把人们的鼻子当成螺丝钉来拧，卷入流水线机器的皮带里，令人苦笑不得。\r 查理尽管贫穷，但却很善良。他在路上搭救了流浪女，和她一起生活，家里破烂却又温馨。每次身无分文的查理为了找到吃的，都会故意犯事，以便进入监牢。光景一时间有了好转，流浪女成了歌舞红星，然而好景太短暂了。','He stands alone as the greatest entertainer of modern times! No one on earth can make you laugh as heartily or touch your heart as deeply...the whole world laughs, cries and thrills to his priceless genius!',1,8500000,28.27648,8.1,856,87,'1936-02-05','en','/3OR9kt3TIjGoiMtv7OGwM6LGavC.jpg',3.6869727304448583,3,'2026-09-10',2,NULL,NULL),(3083,'史密斯先生到华盛顿','Mr. Smith Goes to Washington','美国的一个小镇，Jefferson Smith（詹姆斯·斯图尔特 James Stewart饰）是当地的童子军的首领，深受青少年们的喜爱，被选为新的参议员，来到了华盛顿。遇到了他父亲的老朋友，同为参议员的Joseph Paine（克劳德·雷恩斯 Claude Rains饰），并且迷上了Joseph的漂亮女儿。单纯的Jefferson从来没来过华盛顿，在华盛顿闹了不少笑话，被媒体纷纷取笑。Joseph让Jefferson起草一个提案，并让他的女秘书Clarissa Saunders（琪恩·亚瑟 Jean Arthur 饰）协助Jefferson。然而Jefferson却发现，他的这个所谓参议员不过是其他老谋深算的参议员手中的木偶，他发现了他们一个巨大的阴谋。Jefferson决定以自己单薄的力量来对抗那群人，来改变这个腐败的政治环境。到底他能否成功？史密斯先生的华盛顿之旅会如何结束？\r 　　本片获第11届奥斯卡10项提名，赢得最佳原创剧本一奖。','Romance, drama, laughter and heartbreak... created out of the very heart and soil of America!',1500000,9600000,12.2624,7.9,241,129,'1939-10-19','en','/nDjg1fbNyq15excNDl3acd2IqAk.jpg',3.1870032852556758,3,'2026-09-10',2,NULL,NULL),(3089,'红河','Red River','无论驾驭何种类型片，霍华德·霍克斯始终遵循自己的艺术法则，这一点在其首部西部片中体现得尤为深刻。这部粗犷不羁又睿智犀利的作品，让约翰·韦恩迎来了演艺生涯的重要突破——他将一位饱经风霜、性情专横的得克萨斯牧场主演绎得入木三分。影片中，韦恩与初登银幕便光芒四射的蒙哥马利·克利夫特饰演的独立养子矛盾不断，在前往密苏里州的贩牛旅程中，两人的冲突逐渐升级为史诗级对决。本片改编自小说，其原型是十九世纪末沿奇泽姆牧道发生的真实远征，但霍克斯无意还原历史细节，而是着力颠覆那些驱动美国西部神话的男性准则。阳刚气概十足的韦恩与敏感稚嫩的克利夫特形成了奇妙而完美的反差，二者在层次丰富的机智对白与霍克斯精湛的导演调度下相得益彰。','Big as the men who faced this challenge! Bold as the women who loved them!',3000000,9012000,5.344815,7.3,82,133,'1948-08-26','en','/jyNTsAzrIWB441OtvfbgKtx1kFS.jpg',2.841572426642917,3,'2026-09-10',2,NULL,NULL),(3093,'本能2','Basic Instinct 2','一个夜晚，美艳而富有的女作家凯瑟琳（莎朗•斯通 Sharon Stone 饰）与某球星狂欢后驾车落入水中，结果该球星死亡而凯瑟琳却安然无恙。\r 警方怀疑这是一起谋杀案，委派精神病医生格拉斯（大卫·莫利塞 David Morrissey饰）对凯瑟琳进行精神鉴定。因为其他原因，凯瑟琳被无罪释放了。但此后她却要求格拉斯对其进行精神治疗，格拉斯也想通过凯瑟琳这个案例完成一篇学术论文。在这个过程中，格拉斯被凯瑟琳的美丽与智慧所吸引，渐渐忘记了医生与病人的原则，陷入了无法自拔的情爱之中。就在这时，他感觉身边的一切都发生了可怕的变化，而这些又都与凯瑟琳有关。他仿佛生活在这个女人所编织的无形的网中。\r 那么他能够逃离这个危险女人的掌控吗？他该如何抉择？','Everything interesting begins in the mind',70000000,38629478,13.483387,4.6,180,114,'2006-03-29','en','/5lRMde89yajPvBfTS2WXiYhSzeh.jpg',2.9035061393188335,3,'2026-09-10',2,NULL,NULL),(3116,'午夜牛郎','Midnight Cowboy','生活清贫的牛仔乔恩（乔恩·沃伊特 Jon Voight 饰）从老家来到纽约讨生活，他自认为风流倜傥，因此想在纽约当个男妓混口饭吃。当他第一天来到纽约时，就在大街上勾搭女人。不料，人地生疏的他生意不成反而亏了20块钱。沮丧不已的乔恩遇到了专靠骗点小钱为生的里佐（达斯汀·霍夫曼 Dustin Hoffman 饰），里佐骗乔恩说他认识一个男妓集团的首脑，但要收20元作为中介费。最后里佐只是把乔恩介绍给了一个同性恋的皮条客，愤怒不已的乔恩随后找到了里佐。里佐收留了无家可归的乔恩，两人渐渐成了无所不谈的好朋友。 寒冷的纽约冬天，两人过的十分辛酸，以至于衣食无着，里佐也没有钱买药治病\r 　　里佐向往着迈阿密的生活，他邀请乔恩和他一起到迈阿密去闯世界。生活无着的两人这晚来到一家地下酒吧去碰运气，当乔恩终于搞到一单生意后，体力不支的里佐摔下了楼梯。奄奄一息的里佐此时最记挂的仍是迈阿密家乡的阳光，乔为了完成朋友的愿望，开始铤而走险。','Whatever you hear about Midnight Cowboy is true.',3600000,44785053,21.119209,7.4,299,113,'1969-05-25','en','/ckklq45UxUkwgHve9xItXqXr06r.jpg',3.2329794439954607,3,'2026-09-10',2,NULL,NULL),(3131,'纽约黑帮','Gangs of New York','所有的黑帮故事似乎都不能摆脱杀戮和复仇的套路，但这部电影却将黑帮的复仇升华为一次追求平等与自由的集体反抗。 　　纽约的黑帮主要由意大利裔的瓦龙领导的意大利派和爱尔兰裔的比尔（丹尼尔•戴-刘易斯 Daniel Day Lewis ）领导爱尔兰派组成。瓦龙被比尔暗杀后，其子阿姆斯特朗（莱昂纳多•迪卡普里奥 Leonardo DiCaprio 饰）被送进监牢。 　　怀着强烈的复仇愿望，阿姆斯特朗熬过了10年牢狱之苦。为了复仇，阿姆斯特朗隐形埋名加入了比尔领导的爱尔兰派黑帮。然而，随着他越接近比尔，就越发觉杀掉比尔并不能使所有迫害的人最终得到解脱，因为黑帮背后还有强大的政治力量支持……','America was born in the streets.',100000000,193772504,46.160048,7.1,1910,167,'2002-12-14','en','/lemqKtcCuAano5aqrzxYiKC8kkn.jpg',3.7942878121320955,3,'2026-09-10',2,NULL,NULL),(3132,'临时特工','Bad Company','身为中情局探员的，凯文（克里斯·洛克 Chris Rock 饰）目前正在执行一项危险的卧底任务并且已经得到了至关重要的线索。不幸的是，就在这个节骨眼上，凯文被杀害了，为了任务的顺利进行，中情局找到了凯文的孪生兄弟杰克（克里斯·洛克 Chris Rock 饰），希望他能够代替死去的哥哥。和凯文的精明强干不同，杰克只是一个普通的年轻人，为了让他更快的适应新的工作，经验丰富的老探员奥克斯（安东尼·霍普金斯 Anthony Hopkins 饰）成为了杰克的“教练”。没想到，脾气火爆的杰克对奥克斯的存在十分不感冒，两人关系紧张。时间紧迫，一旦杰克的伪装被识破，他将面临死亡的命运，在这样的危机时刻，杰克和奥克斯这一对冤家搭档能否顺利的完成任务呢？','Two Mismatched Partners. One Messed Up Case!',70000000,65977295,14.086292,5.4,228,116,'2002-06-07','en','/umu141mcfIEhRLgyQp7TWlGJFW.jpg',2.9949131749019733,3,'2026-09-10',2,NULL,NULL),(3170,'小鹿斑比','Bambi','这是一个关于成长的故事。小鹿斑比来到了这个世界上，和其他好朋友一起无忧无虑生活在森林里。一天，他见到了鹿群的领袖，妈妈这时才告诉他，这就是他的父亲。鹿妈妈不久就牺牲在猎人的枪下，斑比只能和父亲相依为命了。转眼间，斑比长大了。到了恋爱的季节，他为了争夺一头母鹿的爱而和另一头公鹿进行了决斗，他大获全胜；秋天来临，森林燃起了大火，在父亲的鼓励下，斑比勇敢地跃入了瀑布；春天又得到了，斑比真的长大了，成了鹿群的新领袖。','A great love story.',858000,267447150,47.651878,6.8,1405,70,'1942-08-14','en','/hqJIgMETOilzode3fvGiwTHujwv.jpg',3.652428766468967,3,'2026-09-10',2,NULL,NULL),(3172,'完美盗贼','Bandits','每个人都有自己的梦想，而实现梦想的路途上往往充满了…… 　　在俄勒冈州的一所监狱里，一对难兄难弟——性格温和的乔·布雷克（布鲁斯·威利斯）和郁郁寡欢的泰瑞·科林斯（比利·鲍伯·汤顿）——最大的梦想就是在墨西哥开一家夜总会。不过身陷囹圄的他们首要的任务就是逃出监牢。乔不愧是一个头脑机敏、身经百战的高手，在他的策划下，两人不但成功越狱，恢复了自由之身，还顺便用一只荧光笔冒充手枪抢劫了一家银行。初战告捷给了泰瑞很大启发，哥俩一合计：乾脆一路抢下去，快活潇洒地直奔加州而去。 　　几次漂亮的打劫之后，乔和泰瑞被冠以“夜行大盗”的名号，成了电视台“犯罪终结者”节目中的热门人物，被列为美国头号通缉犯。与此同时，曾经作过特技演员的菲尔（安东尼·伯奇）也加入了行动，组成了一个“劫匪三人行”。每次打劫后，三人都将赃物均分，然后各自跑路一段时间，以躲避众多追捕者的围追堵截。他们行动迅速，从无半点儿闪失。 　　不过，在一次行动的间隙中，泰瑞出了车祸——他被一个叫凯特·威尔勒（凯特·布兰切特）的女人撞伤了。为了掩饰行踪，凯特成了劫匪们的人质。身为家庭主妇的凯特早就厌倦了一成不变的枯燥生活，劫匪们的世界倒是让她感到新奇刺激。于是渐渐地，她也成了劫匪中的一员。 　　俗话说“英雄难过美人关”，一个美女加三个大男人肯定有好戏。不出所料：没过多长时间，凯特、乔和泰瑞就陷入了三角关系之中。两个男人同时爱上了凯特，而凯特则是谁都不想伤害。结果凯特走了，劫匪们在最后一次行动中也空手而归，这场戏该如何结尾呢？','Two\'s company, three\'s a crime.',75000000,67631903,24.353302,6.2,302,123,'2001-10-12','en','/vSLcOgmxrfzzs0Kzah5DWcBTQo8.jpg',3.137815329438449,3,'2026-09-10',2,NULL,NULL),(3175,'巴里·林登','Barry Lyndon','斯坦利·库布里克以其耀眼的视觉呈现，改编威廉·梅克比斯·萨克雷的小说，将历史剧情片的传统规则纳入自己的意志之下，勾勒出一幅冷酷贵族阶层的画卷。影片以流浪汉小说式的细腻笔触，记述了无可救药的骗子巴里·林登的冒险生涯——他从爱尔兰农场投机发迹，辗转七年战争的沙场，直至跻身上流社会的华丽沙龙。为了这部职业生涯中工艺最显奢华的影片，库布里克以开创性的摄影技术、华美的服饰与场景设计，重现了那个时代的颓靡表象与繁复社会法则，唤醒了十八世纪绘画的光影与肌理。这些探索也为影片赢得了奥斯卡奖项。最终成就的是一部杰作：它以冷嘲而凌厉的笔调，描绘了一个正在消逝的世界，其浮华之下掩盖的，是核心处空洞的道德底色。[标准收藏公司]','At long last Redmond Barry became a gentleman - and that was his tragedy.',11000000,20000000,29.543331,7.7,505,184,'1975-12-18','en','/t8ZvN3E0hTFK5jssX0nFvDUbrgR.jpg',3.4483168908921926,3,'2026-09-10',2,NULL,NULL),(3179,'瘪四与大头蛋','Beavis and Butt-Head Do America','金发瘪四与黑发大头蛋是一对正值青春期的死党，他们认为凡是只能归纳为两类，不是酷就是逊！这对荷尔蒙分泌过盛的宝贝并不笨，只是聪明没用对地方，他们满脑子想的都是怎样上马子，急欲摆脱处男之身的他们可以把任何事物都形容得“性“致勃勃，令人绝倒！本片缘起于瘪赐与大头蛋的电视遭窃，他们急著上天下海四处找寻，终于来到一煎破旅馆，遇到个叫曼迪的老粗。曼迪说他愿付一万元雇他们去洛杉矶“做“了他老婆，色欲薰心的瘪四与大头蛋一听，不禁喜出望外，殊不知此“做“非彼“做“！于是，他们欢天喜地的搭上往洛杉矶的飞机，展开他们的处男航（第一次搭飞机）。但到了洛杉矶，事情并不如他们所想像的，为了追上曼迪的前妻，瘪四与大头蛋始终周旋在两名联邦调查员和一群老人之间。','Coming to a screen bigger than your TV.',12000000,0,12.60629,6.5,168,81,'1996-12-15','en','/vqdgQiRCSzgpFXLlbxbybfkleBM.jpg',2.998301325654537,3,'2026-09-10',2,NULL,NULL),(3291,'晚安，好运','Good Night, and Good Luck.','这部电影记载了上世纪中叶美国一场轰烈的政治抗争，此次对抗冲突是美国新闻界和政治史册上不可或缺的一页。 在冷战的背景下，参议员约瑟夫·麦卡锡（Joseph McCarthy Himself）作为新兴政治人物崛起，他以反共产主义的政治立场而闻名。麦卡锡用强硬的手腕，搜集国会内的共产主义分子资料，实行高压的政治迫害，意欲掀起席卷政坛的反共风潮。美国哥伦比亚电视台的新闻记者爱德华（大卫·斯特雷泽恩 David Strathairn饰）和他的同事们对这个政治阴谋坚决抗争。他们用自己的新闻理想、新闻阵地，毫无退缩地与麦卡锡主义对抗到底，并把这个丑陋的政客拉下政治舞台。爱德华和他的同事，成为了美国历史上的传奇人物。','They took on the Government with nothing but the truth.',7000000,54600000,17.717681,6.8,273,93,'2005-09-16','en','/w4QSEno2xxHqMtSr3mPUhJpO3F2.jpg',3.1493453339690185,3,'2026-09-10',2,NULL,NULL),(3472,'美丽坏东西','Dirty Pretty Things','一名阿尔及利亚非法移民在伦敦一间高级旅馆打零工时不巧目击了一桩诡异的谋杀案，他联合土耳其裔女侍(Audrey Tautou)与中国妓女私下调查此案来龙去脉。 　　史提芬．费雅斯回归其成名作《欢乐洗衣店》的风格，反讽世情笑中有泪，拍出伦敦各式新移民的苦与乐，以写实的笔触细诉英国的不景气之余，又反映来自土耳其、东欧、非洲等地的新移民所面对的艰辛与危机感。非洲移民奥加日间驾的士晚上到聚满非法劳工的廉价酒店帮工，意外揭发有人以贩卖器官求取居留权的人间惨事。移民是为了寻梦，还是终日左闪右避不见天日？饰演土耳其裔酒店女工的是《天使爱美丽》的柯德莉．塔图，一腔土式英语含辛茹苦保证令观众耳目一新。','Every dream has its price.',0,0,9.177896,6.8,131,97,'2002-09-05','en','/dtQ4Y44GBtncBhezvSL8AvvXGxj.jpg',2.9464665092300417,3,'2026-09-10',2,NULL,NULL),(3482,'战斗列车','The Train','以火车为主要叙事舞台的影片中，约翰．弗兰肯海默导演的这部战争动作片是令人难忘的杰作。故事时代背景是二次世界大战末期，德军眼看大势已去，深黯艺术无价的德国指挥官保罗．斯科菲尔德乃下令将一批法国名画从博物馆搬回德国去。负责驾驶这列火车的司机伯特．兰卡斯特在严密监视下，仍跟法国铁路局人员及地下游击队配合行动，用鱼目混珠及瞒骗等种种方式跟德军斗智，力保国宝不致流出国境之外。全片剧情结构严谨，气氛处理紧凑生动，常有令人捏一把汗的精彩场面出现。两位男主角的表演旗逢敌手，张力十足，也表现了各自的爱国心。','It carried their hopes, their nation\'s honour!',5800000,6800000,4.49029,7.2,72,133,'1964-09-21','en','/bzgPLB7efMohled42PIn6CcOTnO.jpg',2.805044320548043,3,'2026-09-10',2,NULL,NULL),(3489,'88分钟','88 Minutes','一夜的纸醉金迷后美国联邦调查局的法庭精神分析师Jack Gramm博士（Al Pacino饰）被一宗谋杀案的电话带离了美人香，这宗谋杀案和9年前的西雅图杀手案极其相似。Jack当时的精神分析是判定嫌疑犯Foster有罪的关键依据。现在联邦调查局认为Foster是无辜的，而被害者在临死前的录象带也亲口证实Jack抓错了人。真正的罪犯也许正在逍遥法外。  　　当Jack正处于迷惑之时，他又收到了莫名的死亡威胁，得知自己只能再活88分钟。  　　面对种种突如其来的迷团以及死亡的威胁，Jack该如何应对……','He has 88 minutes to solve a murder. His own.',30000000,16930884,16.883429,5.7,313,108,'2007-02-14','en','/nCC2Y3jm7DziBavn31ZK2nA0trD.jpg',3.083609713467974,3,'2026-09-10',2,NULL,NULL),(3509,'黑暗扫描仪','A Scanner Darkly','不久的未来，毒品泛滥已经失去控制，一种极易上瘾的非法药品“D药丸”在美国境内流行，政府当局只好利用高科技监视系统对抗失控的局面。卧底的缉毒探员弗瑞德（基努•里维斯 饰）化名巴布•亚特，试图追踪毒品来源，这样，他与小毒贩唐娜•霍桑（薇诺娜•瑞德饰）、吸毒者吉姆•贝芮斯（小罗伯特•唐尼饰）、厄尼•洛克曼（伍迪•哈里逊饰）、查尔斯•费克（罗瑞•考克兰饰）等人住在一起。但实际上，弗瑞德也被“D药丸”的毒瘾深深吸引。随着毒瘾越来越深，他逐渐模糊现实与虚假间的界线，失去神智的弗瑞德，不断追寻大毒枭的隐藏之处，毫不知情自己一直置身于幕后黑手的摆弄。','Everything Is Not Going To Be OK',8700000,7659918,26.093043,6.8,532,100,'2006-05-25','en','/lUKudOpHICDj6A6SO7DdaZM4W48.jpg',3.3437875640834482,3,'2026-09-10',2,NULL,NULL),(3512,'潜龙轰天2：黑暗领域','Under Siege 2: Dark Territory','“游牧者一号”是美国国防部开发的配备有超级粒子束武器的同步卫星，他具有高倍的望远镜，并可精确打击地面上任一目标。然而掌握卫星密码的两名技术人员却被疯狂的科学家查维斯·丹（Eric Bogosian 饰）和特种部队上校马库斯·潘（Everett McGill 饰）率领的恐怖团伙所虏获，“游牧者一号”也毫无悬念地被这群家伙所劫持。国防部虽然紧急应对，却无法与狡猾的恐怖分子抗衡，只能眼睁睁地看着华盛顿成为“游牧者一号”将要袭击的目标。  与此同时，前海军特种部队成员西斯·里贝克（史蒂文·西格 Steven Seagal 饰）正与侄女莎拉（Katherine Heigl 饰）搭乘这趟列车旅行。在危急时刻，西斯挺身而出，独自与恐怖分子展开正邪对抗……','Last time he rocked the boat. This time the sky\'s the limit.',60000000,104324083,13.080725,5.6,210,100,'1995-07-13','en','/1af1w7tGT5nLKj9yL9QbLSFnZq2.jpg',2.9913894602629005,3,'2026-09-10',2,NULL,NULL),(3536,'猎杀U-571','U-571','1942年四月，第二次世界大战期间，大西洋，史上规模最大的海军战役正在进行中......一艘美国潜艇 S-33 秘密出航，船员们的使命是：从一艘德国潜艇上获取德军最先进的译码设备。只有这样，盟军才能及时发觉德军的打击行动以减小损失！如果一切顺利进行，船员们将能够在敌方毫无所觉的情况下摧毁敌方的潜艇，并得到他们所需要的东西。但是，一切事情都会这么顺利吗？他们要面对的不仅是敌人，还要与有限的时间竞争，更要克服潜藏于内心深处的恐惧......','Heroes are ordinary men who do extraordinary things in extraordinary times.',62000000,127666415,18.096884,6.1,340,116,'2000-04-20','en','/2BdHom767rIfnYItlB5wDSsbOg4.jpg',3.1402927739100024,3,'2026-09-10',2,NULL,NULL),(3558,'移魂女郎','Girl, Interrupted','本片根据苏珊娜凯森的自传体小说改编而成。苏珊娜（薇诺娜·瑞德 Winona Ryder饰）本是正值花季的普通少女，却被诊断为“边缘精神错乱症”而送进了精神病院。虽然苏珊娜深陷现实世界的精神压力中饱受折磨，但在精神病院苏珊娜结识到了一群看似乖戾却不同寻常的新朋友。具有反社会人格的莉莎（安吉丽娜·朱莉 Angelina Jolie饰），带领患有说谎癖的乔治娜（克丽·杜瓦尔 Clea DuVall饰），对火深怀恐惧的珀丽（伊丽莎白·莫斯 Elisabeth Moss饰），不能当着他人面进食的戴西（布莱特妮·墨菲 Brittany Murphy饰）等其他女孩，做出了很多令人瞠目结舌的举动，这令医院管理人员头痛不已。苏珊娜逐渐融入了女孩们的“秘密活动”中。这一次次离经叛道的疯狂冒险，使她踏上了一场寻找自我的精神之旅。\r 　　安吉丽娜·朱莉因本片荣获第72届奥斯卡金像奖(2000)奥斯卡奖-最佳女配角。','The crazy thing is, you\'re not crazy.',40000000,0,10.713521,7.6,721,127,'1999-12-21','en','/dOBdatHIVppvmRFw2z7bf9VKJr9.jpg',3.5094878339965776,3,'2026-09-10',2,NULL,NULL),(3580,'换子疑云','Changeling','1928年美国洛杉矶，在电话局接线台工作的克莉斯汀•柯林斯（Angelina Jolie 安吉莉娜•朱丽 饰）独自抚养儿子沃特（Gattlin Griffith 加特林•格里菲斯 饰），母子的生活简单而幸福。然而她们的生活很快被打乱，某天当克莉斯汀下班后，发现儿子不见踪影。  　　在公众的舆论压力下，腐败的洛杉矶警方于5个月后找回沃特，但克莉斯汀发现这并非自己的亲生儿子。她三番五次要求警方澄清事实，帮其寻找真正的沃特，却一次次受到阻挠和指责，甚至以妨碍警方公务的罪名被送入精神病院。一向以揭露警方暴行为己任的牧师古斯塔夫•布里格拉伯（John Malkovich 约翰•马尔科维奇 饰），为了这个可怜女人的不幸遭遇奔走呼告。  　　另一方面，探员莱斯特（Michael Kelly 饰）在侦办一件偷渡案时，无意中发现了一起重大的连环儿童杀人案。少年沃特的失踪案似乎渐露眉目……','To find her son, she did what no one else dared.',55000000,113020255,27.50916,7.3,1131,141,'2008-01-30','en','/4F6dYjryVmrCWFjCN95FxhE2ipq.jpg',3.640211579851207,3,'2026-09-10',2,NULL,NULL),(3587,'妈咪也疯狂','Bogus','Recently orphaned, a young boy is taken in by his godmother who is shocked to realize that she can see the boy\'s imaginary friend: a flamboyant, French magician named Bogus.','A comedy about losing your heart, finding your inner child and meeting the one friend you\'ve always tried to avoid.',32000000,0,3.379454,5.4,44,110,'1996-09-06','en','/kiZot43Jj9VeToK7DDlhamw7l75.jpg',2.655930280745776,3,'2026-09-10',2,NULL,NULL),(3594,'灵数23','The Number 23','故事以谜一般的数字23作为切入点，产生了一种不可抵挡的黑暗力量，这种力量让主角沃尔特·斯派洛幸福的田园生活陷入了痛苦的心理折磨之中，并引导着他走向死亡，而他所爱的人也不能幸免于难。 　　这一切，都开始于一本名叫《数字23》的神秘小说……从沃尔特翻开它的那天起，就再也无法对此释怀，小说中所描写的一切都与他的生活不谋而合，它就像一面镜子，一面让沃尔特胆战心惊的镜子，迫使他面对尘封已久的过去和遥不可及的未来。','First it takes hold of your mind...then it takes hold of your life.',30000000,77566815,23.197408,6.3,1018,101,'2007-02-23','en','/k2kxNPY3alce9TEkP1LcmphuPMj.jpg',3.4236263541947434,3,'2026-09-10',2,NULL,NULL),(3595,'赎金','Ransom','美国协力航空公司的总裁汤姆（梅尔·吉布森 Mel Gibson 饰）打拼多年获得令人瞩目的成绩，但最近却被一宗行贿工会案卷入，所幸美满的家庭总能及时给予他安慰。是日，汤姆一家三口参加一次儿童科学园游会，在纷乱的人流中，儿子肖恩被人掳走。劫匪很快打来了电话，向汤姆勒索两百万美金，同时绑架案处理专家朗尼带同FBI介入此案，劫匪头目是纽约警察吉米（Gary Sinise 饰），他高强的反侦破手段让警方一时无从下手，约翰配合警方安排却导致步步被动。心急如焚的约翰决定放手一搏，在媒体公开将赎金变为抓捕绑匪的悬赏，吉米针锋相对，双方展开了走钢丝般的心理较量。吉米团伙抵不过约翰强大的心理攻势出现了分裂，但是吉米又想出了新的对策，两名强硬男人之间的对决，究竟谁生谁负？','Someone is going to pay.',80000000,309492681,16.411345,6.4,470,117,'1996-11-08','en','/4DGjgQMR1Sxjhxc9HPNXLJr20Vq.jpg',3.2415923738632686,3,'2026-09-10',2,NULL,NULL),(3597,'我知道你去年夏天干了什么','I Know What You Did Last Summer','两男两女四个中学生在毕业后的那个暑假开了庆祝晚会，为纪念这个人生的转折点，他们滥饮狂欢。正应了乐极生悲这句老话，归途中他们的车撞死一个路人。慌忙中，大家决定把尸体抛进大海，并相互约定，谁也不要再提起此事。接下来的事又应了另一句老话：若想人不知，除非己莫为。一年后，四人中的朱莉第一个收到匿名信，内容就是片名那句话。自此，四人的生活由不平静到风波骤起，再后来就越来越清楚地听到死亡的脚步声·.....','If you\'re going to bury the truth, make sure it stays buried.',17000000,125586134,27.654472,5.6,687,100,'1997-10-17','en','/6fLLdLj8hQSciPKmBsqe1GXeia3.jpg',3.241104312618776,3,'2026-09-10',2,NULL,NULL),(3600,'我仍然知道你去年夏天干了什么','I Still Know What You Did Last Summer','本片延续了第一集的故事结尾，两年前茱莉 和朋友们开车撞死了一个 路人后众人遭到“铁钩杀手”的报复。最后茱莉虽然得意生还，但这团阴影却始终笼罩着她。  　　两年后，茱莉的好友卡拉赢得了电台的猜奖，卡拉及其男友泰洛要请茱莉与同班同学维尔，四人一同前往巴哈马的塔湾岛度假。就在享受阳光沙滩的同时，一连串的离奇事件也在这个孤岛上展开，旅馆里的工作人员也不明原因的接二连三死亡。茱莉收到“I Still Know What You Did Last Summer”的警告，众人惊恐万分。难道是“铁钩杀手”死而复生？这一次凶手是谁？冷酷的杀手正在等待着他们…… 我仍然知道你去年夏天干了什么','Someone is dying for a second chance.',65000000,40002112,20.793026,5.1,374,100,'1998-11-13','en','/tT6XLi2TwjLfZLxLnLjLtzmIFCM.jpg',3.0652350717838766,3,'2026-09-10',2,NULL,NULL),(3604,'飞侠哥顿','Flash Gordon','《飞侠哥顿》是迈克·豪杰斯执导，赖恩·布莱斯德等主演的动作幻想科幻电影。影片讲述了蒙戈星球的邪恶帝王明准备摧毁地球，查可夫预知外星人的攻击，于是强迫高登及黛儿登上他的火箭，前去拯救地球而引发的一系列故事。','He\'ll save every one of us!',35000000,27107960,12.343507,6.1,233,111,'1980-09-01','en','/eR3s9bDHhf49bnlLpWdcTWst5OM.jpg',3.04566866235495,3,'2026-09-10',2,NULL,NULL),(3635,'戴珍珠耳环的少女','Girl with a Pearl Earring','少女葛利叶（Scarlett Johansson 饰）家境贫寒，于是来到画家维梅尔（Colin Firth 饰）家做女佣。维梅尔的家庭是一个母系社会。他的岳母、妻子，常常摆出颐指气使的神情。因为维梅尔曾经有过外遇，妻子对正当青春的葛利叶更是戒心重重。在非常苛刻和压抑的氛围下，葛利叶在维梅尔家过得卑躬屈膝。维梅尔的画带给了她一点生活的乐趣。她收拾主人画室的时候，流露出了对艺术的天分。她跟维梅尔谈论对画的理解，二人的交心让彼此的情意慢慢滋长。葛利叶知道不可能与维梅尔修得正果，但她愿意做模特奉献给维梅尔作画。她默默地，忍受着维梅尔给她的耳朵打上洞，戴上他妻子的珍珠耳环，画出这一刻的窒息的美丽。','Discover the mystery behind the legend.',0,31466789,19.944479,6.4,377,101,'2003-08-31','en','/41DkOi1MvTgTQXt5BevVSzo94kk.jpg',3.1974893691808,3,'2026-09-10',2,NULL,NULL),(3638,'美味情缘','No Reservations','凯特（凯瑟琳·泽塔-琼斯 Catherine Zeta-Jones 饰）天生丽质，是一所餐厅里杰出的主厨，她是个十足的工作狂，因为工作她的生活变得十分刻板，没有一丝火花。对自己的手艺非常自信的她常常都坚持己见，老板只好强迫她去看心理医生。  凯特的妹妹因车祸而逝世了，留下年幼的女儿祖需要凯特照顾。妈妈离开后，祖变 得越来越封闭。无论凯特怎么努力，祖还是与阿姨保持距离。  此时餐厅里请来了新的厨师尼克（艾伦·艾克哈特 Aaron Eckhart 饰），工作态度完全有别与凯特，这使凯特无法接受，但他却有能耐使不喜欢吃正餐的祖乖乖吃饭。凯特不得不对尼克另眼相看，此后因为祖的关系他们约会渐多，凯特与尼克之间也产生了微妙的情缘，就连凯特与祖之间的关系也大大改进了。  但这时，两人在工作上却出现了分歧，感情受到了挑战……','Life isn\'t always made to order.',28000000,92601050,15.794946,6.1,327,104,'2007-07-25','en','/iUeM8ayARaBvVmjVHKSjLSJvYFu.jpg',3.1266261898838876,3,'2026-09-10',2,NULL,NULL),(3682,'54','54','Shane, a Jersey boy with big dreams, crosses the river in hopes of finding a more exciting life at Studio 54. When Steve Rubell, the mastermind behind the infamous disco, plucks Shane from the sea of faces clamoring to get inside his club, Shane not only gets his foot in the door, but lands a coveted job behind the bar – and a front-row seat at the most legendary party on the planet.','You\'ve never been anywhere until you\'ve been here',13000000,16757163,11.880899,5.5,135,106,'1998-08-28','en','/gLjt54vow8CEOHdgRkQCyXwbq52.jpg',2.8989552085367443,3,'2026-09-10',2,NULL,NULL),(3683,'Flags of Our Fathers','Flags of Our Fathers','There were five Marines and one Navy Corpsman photographed raising the U.S. flag on Mt. Suribachi by Joe Rosenthal on February 23, 1945. This is the story of three of the six surviving servicemen – John \'Doc\' Bradley, Pvt. Rene Gagnon and Pvt. Ira Hayes, who fought in the battle to take Iwo Jima from the Japanese.','They fight for their country but they die for their friends.',90000000,65900249,23.9366,6.7,526,132,'2006-10-18','en','/bscwspZdwY0L7xsZwnG5SdZWzx8.jpg',3.3232540797327674,3,'2026-09-10',2,NULL,NULL),(3766,'上海小姐','The Lady from Shanghai','曾在西班牙杀过人的水手Michael O\'Hara（奥逊·威尔斯 Orson Welles 饰）回到了纽约，一天夜里他在路上救了遭到打劫的美女Elsa（丽塔·海华斯 Rita Hayworth 饰），于是Elsa让她的丈夫，律师Arthur Bannister（埃弗雷特·斯隆 Everett Sloane 饰）找到Michael，让他来船上当水手。Bannister一家刚从上海回到纽约，正要坐船前往旧金山。在海上航行的时候，Michael和Elsa情愫暗生。而Michael也认识了Arthur的朋友George Grisby（Glenn Anders 饰）。George知道Michael曾经杀过人后，想让Michael再杀一个人，并承诺给他五千美元的佣金，而他想让Michael杀的人，就是George自己。原来George想制造自己已经死了的假象，然后从现在的生活和他的妻子身边逃走。两人的计划看起来天衣无缝，George却失手杀死了Arthur的管家，随后George也真的被杀。Michael被认为是两个死者的凶手，法庭上，为Michael辩论的却是他的情敌Arthur，到底谁才是杀死George的真正凶手？','I told you... you know nothing about wickedness',2300000,0,8.055084,7.2,102,87,'1947-12-24','en','/whqdqWavNMSoeXTx1X3DauO1LG6.jpg',2.8986690115951963,3,'2026-09-10',2,NULL,NULL),(3877,'遗失在火中的记忆','Things We Lost in the Fire','两个受到命运召唤的人，他们注定要依偎在一起共同度过生命中最困难的时刻。当奥德丽·伯克站在自家门口，听着警察为她带来的丈夫布莱恩的死讯时，顿觉天旋地转，险些晕倒。奥德丽与布莱恩的婚姻刚刚步入第11个年头，共同孕育了一对儿女，他们都尽情地享受着美满的婚姻所能带来的舒服的感觉，心甘情愿地被对方所束缚，幻想着就这样过一辈子，相守到老……奥德丽怎么也没想到，她那脾气温和、性格可爱的丈夫竟然是在一次混乱且偶然的暴力事件中丧生的。突如其来的打击，让猝不及防的奥德丽再次变成了一个无根、随意漂泊的浮萍，而她的手中，还牵着一对年纪尚小的儿女.','Hope comes with letting go.',16000000,2849142,8.842869,6.7,90,113,'2007-09-26','en','/fyMziX8tPzPSguUgOpKWkKK322S.jpg',2.8528799850756297,3,'2026-09-10',2,NULL,NULL),(3902,'我不在那儿','I\'m Not There','在这部关于鲍勃·迪伦生平的传记电影中，将分别由六位演员扮演鲍勃·迪伦，分别演绎鲍勃在不同时代的生活故事和音乐经历。该片讲述了鲍勃·迪伦早期作为民谣歌手艰苦奋斗的生活，和1960年代初成形的美国民歌界的英雄和知识分子，具有争议的摇滚转型、摩托车意外事故还有后来从公众视线里销声匿迹的隐退，近年来工作重心不放在录制唱片而是举行巡回演唱会上，如名为“永不停止的巡演”（The Never Ending Tour）等等。','All I Can Do Is Be Me Whoever That Is',20000000,4001121,13.032308,6.6,195,135,'2007-10-01','en','/x6OPFkBWaMDCpDAuIJH2SDYmKiN.jpg',3.0405554251728786,3,'2026-09-10',2,NULL,NULL),(3933,'僵尸新娘','Corpse Bride','故事背景设定在19世纪的欧洲村庄。这部定格动画长片讲述了年轻人维克多（约翰尼·德普 配音）的故事——他被带往冥界，与一位神秘的僵尸新娘（海伦娜·伯翰·卡特 配音）成婚，而他真正的新娘却在人世悲痛等候。[华纳兄弟]','There\'s been a grave misunderstanding.',40000000,117195061,43.571612,7.2,1894,77,'2005-09-09','en','/3RAoVTxUk1OzZClscAsynuu670p.jpg',3.807717538588407,3,'2026-09-10',2,NULL,NULL),(3981,'偷听女人心','What Women Want','尼克（梅尔·吉布森 Mel Gibson 饰）是芝加哥一间广告公司的小经理，是个典型的大男子主义者。对于新来的女上司达西（海伦·亨特 Helen Hunt 饰），他更是满腹牢骚。达西要求尼克设计出女性用品的创意广告，令达西分外头痛，一不留神，尼克在自家浴室中触了电，这次事故让他获得了一个神奇的本领 ——读心术。有了这个意外的收获，尼克现在就能轻而易举的知道身边女人们的心事。他渐渐的沉迷于此，并惊奇地发现原来达西一直都对自己有好感。于是，尼克决定将计就计，利用达西的心事好好捉弄她一番，他千方百计接近达西，讨她欢心，却不知自己正在堕入情网。自从得知女人的内心世界，这个大男人终于领悟到她们的美丽，和水火不容的女上司共赴爱海。','He has the power to hear everything women are thinking. Finally... a man is listening.',70000000,374111707,31.39165,6.1,992,127,'2000-12-15','en','/httDaqrJROAK8auXGDha7rdxCWM.jpg',3.4017807924726435,3,'2026-09-10',2,NULL,NULL),(3989,'Team America: World Police','Team America: World Police','Team America World Police follows an international police force dedicated to maintaining global stability. Learning that dictator Kim Jong il is out to destroy the world, the team recruits Broadway star Gary Johnston to go undercover. With the help of Team America, Gary manages to uncover the plan to destroy the world. Will Team America be able to save it in time? It stars… Samuel L Jackson, Tim Robbins, Sean Penn, Michael Moore, Helen Hunt, Matt Damon, Susan Sarandon, George Clooney, Danny Glover, Ethan Hawke, Alec Baldwin… or does it?','Putting The \'F\' back in \'Freedom\'',32000000,50907422,26.509175,6.6,660,98,'2004-10-10','en','/m1Q2VFe1DVVbjfu1LDZe7tlp9yb.jpg',3.3739408435710856,3,'2026-09-10',2,NULL,NULL),(4011,'阴间大法师','Beetlejuice','经营着一家五金店的亚当（亚历克·鲍德温 Alec Baldwin 饰）与芭芭拉（吉娜·戴维斯 Geena Davis 饰）夫妻俩非常恩爱，两人虽然没有孩子，但把所有对彼此的爱都倾注在装扮自己的家上。这天夫妻俩出行时发生车祸，双双殒命。成为鬼魂的两夫妻不忍离开自己的家，但阴阳相隔他们只能眼睁睁看的自己的家中搬来了新主人。入住的迪兹与查尔斯一家将夫妻俩的房子大肆改造，亚当和芭芭拉想出闹鬼招数试图吓走迪兹一家却不起作用，反被迪兹喜爱呆在黑暗中的怪异女儿莉迪亚（薇诺娜·瑞德 Winona Ryder 饰）看破，做鬼也难得尊严。无计可施的夫妻俩按照亡灵手册指引，拜托流离于阴间主流之外的大法师“甲壳虫汁”（迈克尔·基顿 Michael Keaton 饰）帮助他们夺回自己的家……','He\'s guaranteed to put some life in your afterlife.',15000000,73326666,58.553213,7.1,1444,92,'1988-02-29','en','/nnl6OWkyPpuMm595hmAxNW3rZFn.jpg',3.744357244842806,3,'2026-09-10',2,NULL,NULL),(4012,'信徒','The Believer','居住在纽约的犹太青年丹尼•贝林特（Ryan Gosling 雷恩•高斯林 饰）曾是希伯来语学校的高材生，但在学习过程中他不断对《旧约》以及本民族的信仰产生质疑。他的疑问令校方不知所措，最终将其开除了之。  　　丹尼自此对犹太同胞由爱生恨，他开始有意识地接触新纳粹团体，并最终成为3K党中的一员……  　　影片根据真实事件改编，男主角原型Dan Burros先后参加美国新纳粹和3K党，在记者揭露其犹太身份后，Dan自杀身亡。本片荣获2001年圣丹斯电影节评审团大奖、2001年俄罗斯影评人协会最佳外语片男主角（Ryan Gosling）。',NULL,1500000,416925,9.856826,6.8,151,98,'2001-01-19','en','/doe1zmrCRCSRkC3EdalFiUZhMxn.jpg',2.9826270970484563,3,'2026-09-10',2,NULL,NULL),(4032,'宝贝小情人','My Girl','因为有着一个开殡仪馆的父亲加上母亲的早逝，女孩维达（安娜·克鲁姆斯基 Anna Chlumsky 饰）对生离死别有着自己深刻而另类的见解，同时，对于死亡的恐惧也无时不刻的纠缠着维达。在维达的身边， 男孩托马斯（麦考利·卡尔金 Macaulay Culkin 饰）将她的喜怒哀乐全部看在眼里，个性内向的托马斯唯一能够做的事情，就是温柔的陪伴在女孩身边。 　　雪莉（杰米·李·柯蒂斯 Jamie Lee Curtis 饰）的出现让维达有了强烈的危机感，她感到这个女人很可能将要分享父亲对她的独一无二的关注和爱。一次维达造成的意外中，托马斯死去了，看着心爱的人又一次永远的离开了自己，维达痛不欲生，而来自父亲和继母的安慰与教导终于让她明白了要如何珍惜生命里真正重要的东西。','When your Dad\'s an undertaker, your Mom\'s in heaven, and your Grandma\'s got a screw loose...it\'s good to have a friend who understands you. Even if he is a boy.',16500000,0,20.935169,7,428,102,'1991-11-27','en','/qyJJNHteA7BUwQSey05t7qP4vRV.jpg',3.296359394344691,3,'2026-09-10',2,NULL,NULL),(4105,'黑雨','Black Rain','纽约探员尼克（迈克尔•道格拉斯 Michael Douglas 饰）是个桀骜不驯的离异男子，他最近因渎职嫌疑被风纪部门调查。某日尼克与搭档文森（安迪•加西亚 Andy Garcia 饰）在一家餐厅中偶然遇到日本黑帮的内部火并，二人虽将主犯佐藤（松田优作 饰）捕获，但佐藤抢到的神秘块状物却不翼而飞。日本方面要求引渡佐藤，尼克和文森只得押解佐藤到达大阪，岂料在飞机场，尼克误将佐藤交给了乔装后的黑帮分子。不甘心失去人犯的尼克和文森以观察员的身份，在日方助理兼翻译松本正弘（高仓健 饰）协助下继续调查佐藤一案，他们发现佐藤正与大老板菅井为了制造假钞的铜板火并。不久，文森被佐藤一伙杀害，尼克的处境也愈发艰难，但他固执的要在晦暗的陌生城市中抓到凶手……','Their country. Their laws. Their game. His rules.',30000000,45892212,11.19602,6.2,243,125,'1989-09-22','en','/hb4AnfJM7yrZdBhC9wbyVpzvsI9.jpg',3.059609458365645,3,'2026-09-10',2,NULL,NULL),(4107,'血腥星期天','Bloody Sunday','这部备受争议且广受好评的电影再现了1972年1月30日的事件：27名平民在一次和平民权游行中被英国军队枪杀。该事件引发了英国与南北爱尔兰各方之间长达25年的暴力循环。[派拉蒙经典]',NULL,0,773228,7.330691,7.2,53,107,'2002-01-16','en','/oqdQMDJucR7R0ol0LFvzmqcDyEb.jpg',2.7388495006150944,3,'2026-09-10',2,NULL,NULL),(4108,'玩命快递','The Transporter','故事发生在法国南部，弗兰克·马丁是个送货员，是那种专门为黑道人物送包裹的“地下送货员”，他当过特种兵，身手了得，外表冷漠，喜欢独来独往，多年来他一直坚守三条戒规，那就是：一、一旦接货就要干到底；二、从不打听雇主的情况；三、从不私自拆开包裹，这也是他能一直干到现在的原因。这不马丁又接了一单生意，一个美国人让他送一个包裹，马丁二话不说就上路了，可是路上他发现他的“包裹”动起来了。强烈的好奇心驱使他打破了自己的第三条规矩，去查看了包裹——结果发现里面是一个美丽的东方女子，嘴里被塞上了东西。这女孩是一个中国蛇头的女儿，她父亲专门把中国非法移民走私运送到法国。因为父亲在生意上得罪了人而被绑架。马丁决定帮这个女孩逃生，这个决定为他带来了种种麻烦，美国人开始追杀他们，而马丁和女孩也发生了感情。','Rules are made to be broken.',21000000,43928932,34.433521,6.6,1692,92,'2002-10-02','en','/h8WMDOTgJxcqKZhO0S7MDKyO4Cx.jpg',3.628977113737423,3,'2026-09-10',2,NULL,NULL),(4133,'大毒枭','Blow','一名平凡的美国人乔治戎格（强尼戴普饰）原本只是一个每天为生活奋斗打拼的小市民，但是在短短的几年内，他竟然成为美国境内贩卖古柯硷的大盘商，他每年向哥伦比亚贩毒集团引进价值三百五十亿元的毒品，也从此改变了这个世纪美国年轻人的价值观。  　　乔治戎格一生都在追求所谓的美国梦，也就是享受美好富裕的生活，但是他却不愿像他父亲那样一辈子都只是个出卖劳力的建筑工人。于是他搬到阳光明媚的加州，靠著贩卖大麻赚钱，起初，他贩毒只是为了享受自由自在的生活，但是当他野心越来越大，他的势力也日益坐大之际，却不幸被捕入狱。  　　他在牢里认识一个能言善道，自称熟识哥伦比亚贩毒集团的牢友狄亚哥，他出狱后果真把当时势力最大的毒枭艾斯科巴介绍给乔治认识，艾斯科巴计画将古柯硷大量引进美国的迪斯可舞厅，希望能引领一股吸毒狂欢的风潮。除了毒品供应商之外，狄亚哥也介绍了一个美艳又狂野的女人玛莎给乔治，他们疯狂相爱，之后马莎还替他生下一个可爱的女儿克莉丝汀娜，也是乔治一生的最爱。  　　乔治很快就靠著贩毒发大财，他还得买一栋大房子专门存放每天赚进来的大把钞票，但是日进斗金却整天提心吊胆的生活却让乔治开始省思，到底他要继续过著挥霍富裕的生活，还是为了自己心爱的女儿应该转性投资正当的事业？可是这时联邦调查局的探员，也开始盯上毒源祸首的乔治……','Based on a True Story.',53000000,83282296,28.350529,7.4,1317,124,'2001-04-04','en','/yYZFVfk8aeMP4GxBSU9MTvqs9mJ.jpg',3.7071738640082597,3,'2026-09-10',2,NULL,NULL),(4147,'毁灭之路','Road to Perdition','1930年代，芝加哥。美国实行禁酒令，道德观念保守，而这个年代却是个堕落而充满暴力的年代。芝加哥的地下世界被卡波尼黑帮分子牢牢控制。芝加哥所在的伊利诺伊州是意大利和爱尔兰暴徒聚集的地方。在这个州的洛克岛，爱尔兰裔的鲁尼（保罗·纽曼），人称“老头约翰”，控制着这里的生意。他的社区里居住的多是爱尔兰移民和他们的后裔。鲁尼的助手是他的儿子库纳尔（丹尼尔·克雷格），和“养子”迈克尔·奥苏利文（汤姆·汉克斯）。奥苏利文在圈子内有“死亡天使”之名，是个令人生畏的职业杀手；但他同时却有他的同情心和正直的一面，更重要的是他十分看重自己的家庭，忠实于妻子和两个儿子，从不抽烟喝酒，家庭生活中规中矩。多年来他努力在杀手和丈夫父亲的角色间保持着平衡。　　然而变故突然降临。他的两个儿子小迈克尔和彼德虽然不知道父亲是干什么的，却一直当他是自己的英雄，十分崇拜。小迈克尔12岁了，渐渐懂事，他非常想知道父亲的职业。于是有一天父亲和库纳尔出去办事时他悄悄藏在了汽车里。不久以后小迈克尔目睹了一起杀人事件，而自己的父亲是杀手。　　帮派里的人担心迈克尔会泄露看见的一切。奥苏利文只说了一句：他是我的儿子。然而这并不能让其他人放心。小迈克尔还没来得及理解真实世界的种种和自己的父亲，他的母亲和弟弟已经被人杀害，而他和父亲本是这场杀戮的目标。　　父子两人开始逃亡。尽管儿子哀求他不要再有任何暴力，奥苏利文还是决定向鲁尼复仇。鲁尼和库纳尔都躲了起来,奥苏利文决定一一袭击他们的生意据点,直到他们出来应战。　　这个计划却使他同卡波尼派发生了冲突，他们因为与鲁尼有生意往来，奥苏利文的行动使他们的利益受到了损害。于是他们派出杀手马奎尔追踪奥苏利文和迈克尔。马奎尔(裘德·洛)原来是个记者，从事杀手行业之后外号就叫“记者”，他的任务只有一个：杀死这父子俩。','Pray for Michael Sullivan.',80000000,181001478,49.078546,7.3,1077,117,'2002-07-12','en','/kBxURaP3aoehPDO42IBs6EvelcS.jpg',3.6746926218891103,3,'2026-09-10',2,NULL,NULL),(4148,'革命之路','Revolutionary Road','当他们第一次见面，他是高谈阔论的有志青年，她是向往成为名演员的未来之星。而如今，婚后的他们变了。他变成了在公司做不喜欢工作的无聊上班族，她成了不入流的糟糕演员。在一次演出后，丈夫弗兰克（莱奥纳多•迪卡布莱里奥饰）与妻子爱波（凯特•温斯莱特饰）大动肝火，两人多年的积怨终于爆发。莫非婚姻真的躲不过七年之痒？悲痛的爱波整理照片，发现弗兰克年轻的照片，想起他曾经描述的“美好的巴黎”，她提出了一个计划“全家搬到巴黎”，以拯救这个家庭。但是，这看似遥不可及的计划，却成为了催化剂，将两人推向婚姻更痛苦的深渊。','How do you break free without breaking apart?',35000000,75225693,20.360549,6.7,796,119,'2008-12-19','en','/qsUQZsze2yL7lcBO7zb4vRZmopv.jpg',3.423033233208248,3,'2026-09-10',2,NULL,NULL),(4170,'交易','Trade','自从被人贩绑架后，13岁的艾德里安（鲍琳娜·盖坦 Paulina Gaitan 饰）的生活一下子从天堂跌入了地狱，年轻美丽的她被卷入了一起国际性的“性奴”交易阴谋中。好在得到了好友维罗妮卡（艾丽卡·巴赫蕾达-库鲁斯 Alicja Bachleda-Curus 饰）的帮助，艾德里安幸运的免于了被伤害的命运，可她明白好运不会太长久。','Each year, more than 1,000,000 people are trafficked across international borders... against their will.',12000000,0,11.237374,6.8,67,120,'2007-01-23','en','/x2ckiEGoYz2AomOeviEPqnhrw7Q.jpg',2.7930751580512725,3,'2026-09-10',2,NULL,NULL),(4174,'爱德华大夫','Spellbound','精神病院的默奇逊院长即将退休，接手的是年轻有为的爱德华大夫（格利高里·派克 Gregory Peck 饰）。医院里年轻漂亮的女医生彼特森（英格丽·褒曼 Ingrid Bergman 饰）和他相爱，然而竟发现眼前的爱人不是爱德华大夫，而真实的爱德华的秘书，还前来指出这个冒牌人士是杀害爱德华的凶手。  　　面对恋人扑朔迷离的身份，彼特森始终不相信他是杀人凶手，然而默奇逊院长却用精神分析法印证了“事实”。更为棘手的是，这个假爱德华也相信自己有罪，他甚至连自己是谁，经历过的事情也不知道。  　　彼特森对自己的判断非常坚持，她决定要帮他找出事件真相。在警察的追捕下，她带他逃到了心理分析教授的家中，展开了一联串精彩的心理分析过程，他童年的阴影和爱德华大夫被杀的真相渐渐浮出水面。','The maddest love that ever possessed a woman.',1500000,7000000,11.145915,7.3,160,111,'1945-12-28','en','/dPAox7jGScLBvxKLeRptJIBF7v.jpg',3.0268070485487897,3,'2026-09-10',2,NULL,NULL),(4232,'惊声尖叫','Scream','锡德尼•普雷斯科特（内芙•坎贝尔饰）的母亲去世一周年，这个本该平静的加州小镇变成了一片血海！两名学生被残忍地杀害，凶手是一位带着面具的恐怖片爱好者。警方将锡德尼的男友比尔•卢米斯（斯基特•乌尔里奇饰）定为嫌疑犯，并予以逮捕。但这时又有命案发生！神出鬼没的面具凶手仿佛死神般带走一个又一个生命，但凶手的真面目却无人知晓。夜幕降临，凶手将锡德尼身边的人一个个杀害，而被害人只能在被害前惊声尖叫。谁能够从凶手的刀下躲过，谁能揭开凶手的面具呢？','Someone has taken their love of scary movies one step too far.',14000000,173046663,45.99611,7,1476,111,'1996-12-20','en','/lr9ZIrmuwVmZhpZuTCW8D9g0ZJe.jpg',3.7017856583677515,3,'2026-09-10',2,NULL,NULL),(4233,'惊声尖叫2','Scream 2','血雨腥风再度向温莎学院袭来！一对儿学生情侣在观看恐怖电影时被头套面具的凶徒当众杀死，而台下观众在案发时以为是电影造成的一场玩笑而无人制止。另一方面，希德妮（内芙•坎贝尔 Neve Campbell 饰）现在已经是克兹镇上的知名人物，在卡顿维瑞因魏盖尔的新书无罪释放后，媒体和警方再次将注意力集中在希德妮身上。同时，面具杀人狂再次大开杀戒，而神秘的电话也继续纠缠希德妮和她身边的人。一时间，打大家再次陷入了对未知凶手的恐慌中，而希德妮的男友德瑞克，看上去颇为符合凶手暴露的蛛丝马迹。究竟，面具杀人狂的真身是谁？魏盖尔、兰迪等希德妮的好友或者相关人士，卷入了这场追凶冒险。','Someone has taken their love of sequels one step too far.',24000000,172363301,35.244037,6.1,840,120,'1997-12-09','en','/ArnlYY07Ix26q7IhylU3tRrykM7.jpg',3.374658977309803,3,'2026-09-10',2,NULL,NULL),(4234,'惊声尖叫3','Scream 3','经历了常人难以想象的痛苦与折磨，威兹堡温莎大学杀人案的幸存者悉妮·普利斯科特（内维·坎贝尔 Neve Campbell 饰），如今隐居在山中，通过电话对有着生活危机的女性们进行心理辅导。与此同时，她的事迹被改编成系列恐怖电影“血腥刺杀”（Stab），第3部《Stab》的主角卡顿却被当街杀害。这一事件让悉妮、戴维（David Arquette 饰）以及盖尔（Courteney Cox 饰）重新聚首。而鬼脸杀手更是阴魂不散，在好莱坞引发了新一轮的血腥屠杀……','Someone has taken their love of trilogies one step too far.',40000000,161834276,24.992057,5.7,736,116,'2000-02-03','en','/e51xCNIU4Qhpx3S7whQFbsQeJiD.jpg',3.2623917979629637,3,'2026-09-10',2,NULL,NULL),(4244,'扭转乾坤','The Kid','罗素（布鲁斯·威利斯 Bruce Willis 饰）人到中年，事业上成绩平平，感情生活一片空白，忙忙碌碌大半辈子，所得也仅能用“乏善可陈”来形容。一次偶然中，罗素遇见了一个看起来十分眼熟的男孩，令罗素感到吃惊的是，这个男孩不是别人，正是8岁时的自己（史宾塞·布瑞斯林 Spencer Breslin 饰）。\r 　　费了好大的功夫，罗素才让小罗素相信，自己就是32年后的他，而令小罗素十分失望的是，原来自己并没有如同理想中的那样成为一名帅气的飞行员，而是长成了默默无闻形单影只的落魄中年人。为了改变自己的未来，小罗素决定帮助未来的自己，在和小罗素相处的过程中，罗素亦走出了迷惘，重新看到了希望','Nobody ever grows up quite like they imagined.',65000000,69700000,18.281798,6,238,104,'2000-07-07','en','/nPiXS0NZJyYjrvCU78pcNprc0Ew.jpg',3.056421070128779,3,'2026-09-10',2,NULL,NULL),(4248,'惊声尖笑2','Scary Movie 2','经历了高中万圣节的杀人惨剧，辛蒂和好友们进入大学校门，大学快乐悠闲的生活让他们渐渐忘记万圣节的恐怖经历。热衷于超自然学的教授奥德曼计划到一年前曾发生恐怖事件的鬼屋做试验，需要拥有濒死体验的人做沟通灵异的媒介。助手歪头得知辛蒂等人的经历，将他们集中起来，以获得优等成绩为诱饵请他们参加一个关于失眠的课题研究。众人怀着玩乐的心情随奥德曼教授和歪头来到了阴森诡异的鬼屋，却经历了极为难忘和恐怖的一夜……','No More Mercy. No More Shame. No More Sequels - Honest! - We Lied.',45000000,141220678,35.376971,5.4,982,83,'2001-07-04','en','/u8uKGdqnPogk5z4WsFPXuXRQYhs.jpg',3.2881294006354795,3,'2026-09-10',2,NULL,NULL),(4251,'爱无国界','वीर-ज़ारा','维尔（沙鲁克·罕 Shahrukh Khan 饰）是一名印度空军救援飞行员，在工作上勤勤恳恳的维尔在内心里也充满了正义感。一次事故中，维尔救下了一个名叫扎拉（普丽缇·泽塔 Preity Zinta 饰）的女子，扎拉的美丽和柔弱让维尔几乎在瞬间就决定将她看做自己此生独一无二的爱人，扎拉亦然。不幸的是，扎拉是巴基斯坦人，政治和宗教在她和维尔之间铸造了深不见底的鸿沟，世界如此之大，却容不下两人纯洁的爱情，很快，维尔被冠上间谍的罪名锒铛入狱。\r 22年过去了，精明强干的律师萨米亚（拉妮·玛克赫吉 Rani Mukherjee 饰）在无意间得知了维尔和扎拉之间凄美的爱情，感动之中，她决定为两人牵线搭桥，成全这一段旷世姻缘。','A Love Legend',7000000,29385320,3.721858,7.4,64,192,'2004-11-12','hi',NULL,2.7799330737230017,3,'2026-09-10',2,NULL,NULL),(4256,'惊声尖笑3','Scary Movie 3','在华盛顿特区以西20哩的小镇上，农夫汤姆的田中出现了怪圈，当地记者辛迪对这条新闻颇为留意，不顾上层反对着力调查，汤姆的弟弟乔治痴迷嘻哈音乐无心农业令汤姆颇为头疼。在怪圈出现后，小镇上的孩子们出现了诸多怪异表现。辛迪的朋友布兰达在看了一部录像带后离奇死亡，而辛迪本人也接到了宣布七天后她将死亡的神秘电话，无助的辛迪向乔治求助，得以拜见了黑人先知，才发现一系列怪事的根源与一座灯塔有关。同时，辛迪通过电视向身处危机之中的人们发出外星人可能来袭的警告，连美国总统也开始正视此事……','Great trilogies come in threes.',48000000,220673217,36.585509,5.8,912,84,'2003-10-24','en','/1t4o6vCBJ6JiaUNsoBlHXBeNCMM.jpg',3.3454478027493852,3,'2026-09-10',2,NULL,NULL),(4257,'惊声尖笑4','Scary Movie 4','经历了好友之死和几多悲惨恐怖的过去，辛蒂•坎贝尔（Anna Faris 饰）决心开始新的人生。她受聘来到一所闹鬼的房子里照顾一位行动不便的老妇人，笨手笨脚的辛蒂好心办坏事，使得老妇人灾难连连。而这座鬼屋也绝非徒有虚名，一个因被杀而冤魂不散的男孩不时出现，希望辛蒂帮他找到真正的凶手。\r 在这所房子的旁边住着失败的父亲汤姆•瑞恩（Craig Bierko 饰），他正和一双儿女共度周末。一来二去的交谈过后，汤姆与辛蒂坠入爱河。就在此时，恐怖的外星人入侵地球，他们欲将人类彻底消灭。辛蒂和汤姆如何才能逃出生天？','Bury the grudge. Burn the village.  See the saw.',45000000,178262620,32.549282,5.3,750,83,'2006-04-13','en','/ztkGAPTURtBdAYUzTlqDF0QKswH.jpg',3.2222817896541813,3,'2026-09-10',2,NULL,NULL),(4258,'惊声尖笑5','Scary Movie 5','戴恩·桑德斯 和乔迪 是一对快乐的新婚夫妇，这一天他们意外接到一通电话。此前戴恩的哥哥查理遭遇灵异事件，惨死家中，而他的三个孩子凯西、莉莉 和尚在襁褓中的艾登 则宣告失踪。三个形同野人的孩子被人偶然发现于某个林中小屋之中，经过一番争执和讨论，戴恩最终令妻子同意收养三个小外甥。突然增加的人口，令戴恩不得不更加努力赚钱养家。可是在他们的新家内，接二连三发生了各种诡异事件，举止反常的小姐妹花，来自另一个世界的神秘访客，桑德斯一家开启了爆笑而恐怖的大门……','Evil is coming. Bring protection.',20000000,78378744,36.819044,4.6,793,86,'2013-04-11','en','/1M1GZGaw8LV2Jqf0OOvUZ3qbQYF.jpg',3.131274105968081,3,'2026-09-10',2,NULL,NULL),(4327,'霹雳娇娃','Charlie\'s Angels','查理先生手下有三名女打手，她们才貌双全拥有一身好功夫，专门接受查理先生的命令为他人伸张正义。她们分别是：娜塔莉（卡梅伦•迪亚兹 饰）、戴兰（茱莉•巴里摩尔 饰）与艾利克斯（刘玉玲 饰）。　　她们最近接受了一个任务：艾瑞克•克诺斯（萨姆•罗克韦尔 饰）先生设计了一款高科技的声音辨别系统。艾瑞克却不幸被绑架了，这三名“天使”需要从不法分子手中拯救艾瑞克。因为这套由艾瑞克设计的高科技系统，一旦被不法分子利用的话后果堪虞。　　三位“天使”得知情况后，很快联想到了艾瑞克公司的对手，该负责人罗格成为了最大的嫌疑。三人于是日夜调查罗格的行踪，也掌握了重要的线索。正在她们有把握拯救艾瑞克的时候，一通电话打破了她们三人的全盘计划。','Get Some Action',92000000,264105545,40.20395,5.6,1232,98,'2000-11-02','en','/MVvqQjDImcBeUULBGuY6BYCXYY.jpg',3.3744556639030803,3,'2026-09-10',2,NULL,NULL),(4347,'赎罪','Atonement','影片时间跨度长达数十年。1935年，13岁的初露头角的作家布里奥妮·塔利斯与家人居住在一座巨大的庄园中，过着富裕优越的生活。在一年中最炎热的日子里，乡间庄园笼罩在一种令人不安的温室氛围中，催生了布里奥妮活跃的想象。管家的儿子、受过良好教育的罗比·特纳暗恋着布里奥妮倔强的姐姐塞西莉亚。他期望塞西莉亚怀有同样的感情，只需一点火花便能点燃这段关系。当火花终于迸发时，一直迷恋罗比的布里奥妮受冲动驱使横加干涉，甚至诬告罗比犯下他并未实施的罪行。塞西莉亚与罗比互诉爱意，但罗比却遭逮捕——由于布里奥妮作伪证，三个人的命运从此永远改变。布里奥妮终其一生都在为她儿时的过错寻求宽恕。通过一次痛苦而勇敢的想象，她找到了通往不确定的赎罪之路，也领悟到恒久之爱的力量。[焦点影业]','Torn apart by betrayal. Separated by war. Bound by love.',30000000,129266061,33.369305,7.4,1049,123,'2007-08-29','en','/B2a5vjUKeerfX3oqERx3T7U32W.jpg',3.648536167076017,3,'2026-09-10',2,NULL,NULL),(4348,'傲慢与偏见','Pride & Prejudice','根据简·奥斯汀同名小说改编。伊丽莎白·班纳特(凯拉·奈特丽 饰)出身于小地主家庭，有四个姐妹，母亲班纳特太太整天操心着为女儿物色称心如意的丈夫。新来的邻居宾格来先生和他的朋友达西（马修·麦克菲迪恩 饰）打破了她们一家人单调的乡村生活。宾格来和伊丽莎白的姐姐简·班纳特互生情愫；达西对善良聪明的伊丽莎白产生了好感，而伊丽莎白却对达西不可一世的傲慢心存偏见，不接受他的感情。然而，世事难料，宾格来和简·班纳特因为误会，关系危在旦夕；达西的种种作为，展示了性格中和伊丽莎白相同的善良一面，逐渐赢得了伊丽莎白的好感。两对有情人能否终成眷属？班纳特姐妹们能否得到自己想要的生活？\r 简·奥斯汀笔下十九世纪初英国乡村生活和社会风貌，重新展现在大银幕上。','A romance ahead of its time.',28000000,121147947,36.58383,7.7,1358,135,'2005-09-16','en','/o8UhmEbWPHmTUxP0lMuCoqNkbB3.jpg',3.7939136943584644,3,'2026-09-10',2,NULL,NULL),(4349,'染血王国','The Kingdom','这里讲述的是一个适合用来自我疗伤的乌托邦故事，而中东所面对的混乱局面，就形成了一个最完美的天然大环境：沙特阿拉伯的首都利雅得，发生了一场针对西方人的恐怖袭击，人体炸弹在海湾绿洲的复式住宅区被引爆。在这场大爆炸中，至少有100人死亡、200人受伤，其中包括石油公司的雇员以及他们的家人……由于至高无上的领土问题，沙特阿拉伯和美国在当地的办事处就案件的归属而发生了争执，FBI特派探员罗纳德·弗鲁瑞带领他的小队抵达沙特阿拉伯进行专案调查，小组成员包括前特种部队士兵和爆破专家格兰特·塞克斯、法医珍妮特·梅耶斯和情报分析师亚当·莱维特，他们只有5天的时间，却要穿越沙特阿拉伯的沙漠，抓住那个在背后策划了爆炸案的极端的宗教疯子。但是，当罗纳德和他的组员踏上这个沙漠的王国时，他们才发现，沙特阿拉伯政府对来自于美国的闯入者根本就持怀疑和不欢迎的态度，因为他们认为这场爆炸案发生在沙特阿拉伯国土上，属于自己的“家事”，外人无权干涉。 几经协商无果，罗纳德焦急的发现留给自己的时间正在慢慢缩短。这些FBI中最优秀的探员终于清醒地意识到，没有沙特阿拉伯外交部的信任和支持，他们的专业技术再出类拔萃，到了这里也没什么使用价值。 而沙特阿拉伯官方却希望按照自己的办案手段，自己去寻找那些制造了血案的恐怖分子。当局为了确保这些美国佬不会在自己的地盘上乱来，特别派来阿尔·戛兹军官“保护”他们。 但当阿尔·戛兹与罗纳德共同解开了犯罪现场一些未被人注意到的蛛丝马迹的秘密时，他们惊恐地发现这些恐怖分子正在计划另一场更大规模的爆炸案，于是，两个来自于不同世界、不同文化的男人，因为一个共同的目标而将任务变得一体化，他们撇开了外交政策的失败和民族仇恨，结成了最值得信任的同盟，共同在沙特阿拉伯酷热的沙漠中追踪凶手。没想到，这样的同盟却使恐怖分子掉转矛头，将怨恨而疯狂的目光对准在他们身上……在一场惊心动魄、你死我亡的对质当中，完全陌生的人因为一个共同的目标而站到了一起，他们绝对不会停下来，直到正义的审判抵达这片沙漠。','How do you stop an enemy who isn\'t afraid to die?',70000000,86658558,26.123705,6.5,513,110,'2007-08-22','en','/uAcqK5nATWA7HfaOYVOTpuiCkbU.jpg',3.296960581391498,3,'2026-09-10',2,NULL,NULL),(4379,'怪兽婆婆','Monster-in-Law','自古婆媳关系大多棘手，查丽（詹妮弗·洛佩兹 Jennifer Lopez饰）也遇上了同样的问题。当她就要和男友凯文（迈克尔·瓦尔坦 Michael Vartan饰）百年好合时，却遇到了一个严峻的问题：凯文的妈妈菲尔茨太太（简·方达 Jane Fonda饰）对这个未来儿媳另有意见。菲尔茨太太曾经拥有体面的事业，然而如今她把全部的爱和心思都摆在儿子身上，不能接受查丽的“入侵”。菲尔茨太太联同助手一起，千方百计地要把查丽这个不速之客赶走，查丽好不容易才觅得如意郎君，当然不能束手就擒，招数一来一往，两方都在暗处开始较量。','This relationship is going to be a real mother.',43000000,154749918,10.411996,5.6,406,101,'2005-05-13','en','/iRqcGkIPdRbEaW0xMEA5kgceUF8.jpg',3.107325634374645,3,'2026-09-10',2,NULL,NULL),(4380,'谈谈情，跳跳舞','Shall We Dance?','约翰（理查·基尔 Richard Gere饰）面临着典型的中年危机：即使有着幸福家庭和体面事业，内心的空虚和压力却随着年龄而倍增。他一成不变的生活需要某些催化剂，来重新唤醒内心激情。每次路过舞蹈室，约翰都会看到舞蹈老师宝琳娜（詹妮弗·洛佩兹 Jennifer Lopez饰）。她美丽而略带神秘的魅力、加上约翰内心期待的某种生活的变化，终于把他带进了里面的舞蹈课程。他报名参加这里的社交舞培训，但令人失望的是老师并不是宝琳娜。更糟糕的是，约翰舞姿笨拙，似乎并不是跳舞的料。然而，当学舞成为了约翰生活的一部分，当他终于结识了宝琳娜并和她甚为投缘，情况开始有了变化——约翰报名参加了一个芝加哥的舞蹈大赛，而约翰的婚姻，也亮起了红灯。','Step out of the ordinary',50000000,170128460,14.231899,5.9,297,107,'2004-10-15','en','/7A7Tqz1KxYQVsjeh7KrZVqcXHAf.jpg',3.0849253968941093,3,'2026-09-10',2,NULL,NULL),(4421,'魔鬼女大兵','G.I. Jane','作为一枚政治筹码，海军情报官欧尼尔（黛咪·摩尔 Demi Moore 饰）成为了美国历史上第一个参加特种部队“海豹突击队”训练的女性军官。凭借此事，一直呼吁男女平等的参议员狄海雯（安妮·班克罗夫特 Anne Bancroft 饰）获得了诸多选票。然而，利欲熏心的狄海雯根本就不关心欧尼尔作为个体的感受和遭遇，因为她心里明白，欧尼尔根本不可能完成特种部队里残酷而又可怕的训练。让所有人大吃一惊的是，欧尼尔不仅出色的完成了训练任务，甚至有可能通过最终考试成为特种部队正式的一员，在此节骨眼上，狄海雯只得使出阴招，以欧尼尔为同性恋的虚假理由将其逐出了队伍。在朋友的帮助下，欧尼尔揭穿了狄海雯的阴谋，不仅如此，她还一次实战任务中凭借着自己的智慧大展拳脚，获得了同伴的尊重。','Failure is not an option.',50000000,48169156,19.434672,6,395,125,'1997-08-22','en','/dUcFq00Rvz5gvf8CygEFWtzjUgZ.jpg',3.165144650348397,3,'2026-09-10',2,NULL,NULL),(4442,'格林兄弟','The Brothers Grimm','威尔·格林（马特·达蒙 Matt Damon 饰）和杰克·格林（希斯·莱杰 Heath Ledger 饰）是一对游手好闲、靠诈骗为生的骗子。他们经常在不同地方雇人扮演妖魔鬼怪进行大肆的破坏，然后自己以驱魔人的身份出现“消灭”妖怪，以此来骗取村民们的报酬。由于这样的手法屡屡得逞，格林兄弟驱魔人的名声越来越大，甚至被法国国王召见，邀请他们前往被诅咒的森林里面揭开失踪少女之谜。这下，格林兄弟只得硬着头皮前往魔法森林。在森林里，灰姑娘、小红帽这些原本童话里面的人物悉数登场……最后，他们发现原来是因为女魔头镜子皇后（莫妮卡·贝鲁奇 Monica Bellucci 饰）为了保持青春，必须杀死年轻的女性，并用她们的血肉来回复青春。于是，格林兄弟与女魔头的世纪大战就此拉开……他们能否获得童话般的美好结局呢？','Eliminating Evil Since 1812.',88000000,105316267,40.138009,5.6,818,118,'2005-08-26','en','/j0I5SfUGF6JYVXnhWjRLiUj19JE.jpg',3.300762698024494,3,'2026-09-10',2,NULL,NULL),(4464,'奔腾年代','Seabiscuit','大萧条时期，每个人都要守住一个梦想，以此来度过最黑暗的时光，生活失意的汽车制造商查尔斯•霍华德（杰夫•布里吉斯 Jeff Bridges 饰）也不例外。他买了一匹小个子赛马，名为“海饼干”，并笼络了一批同样有梦想的人，意图进入赛马圈。 第一个发现海饼干天赋的是训练师 汤姆•史密斯（克里斯•库珀 Chris Cooper 饰），他认为这匹马虽然个头矮小，腿脚也不太灵光，天性中却藏着十足的执拗和倔强，这有可能使其成为赛马圈的王者。他们找来前拳击冠军瑞德•波拉德（托比•马奎尔 Tobey Maguire饰）作为海饼干的骑师，三个人一匹马在共同的征程中重新找到了生活的方向。','The hopes of a nation rode on a long shot.',87000000,148336445,14.824166,6.7,216,141,'2003-07-22','en','/jCamhO2YEKnxAGGJYDhfMI4CTMr.jpg',3.0761761698800356,3,'2026-09-10',2,NULL,NULL),(4474,'我的超级前女友','My Super Ex-Girlfriend','俗话有云：最毒妇人心。得罪女友的后果常常会非常严重，更何况片中可怜的马特（卢克·威尔逊 Luke Wilson饰）冒犯的是超人女朋友。其实，马特和女超人珍妮（乌玛·瑟曼 Uma Thurman饰）的恋爱故事也开始得算是浪漫，但是马特却慢慢发现这个新女友的的超人面目。她爱闹脾气，占有欲强，霸气十足，让马特望而生畏。马特果断的和珍妮分了手。本来马特以为可以喘口气了，却不料他的“灾难”才刚刚开始。珍妮凭借着自己的超能力，随时随地让马特栽进大坑。她想方设法让马特得不到一刻安宁，总是在生活和工作中屡屡出丑。更糟糕的是，马特正在萌芽的新感情也泡了汤，他尝到了得罪女超人的后果：丢了工作，也无法正常的生活。马特该如何收拾这个烂摊子，让珍妮手下留情……','Hell hath no fury like a superwoman scorned.',0,60896147,20.252143,4.8,442,95,'2006-06-20','en','/e6PvD8DbTCVp7BC1wgUDxHpZqO0.jpg',3.0545365949983063,3,'2026-09-10',2,NULL,NULL),(4476,'燃情岁月','Legends of the Fall','骑兵上校威廉厌倦了战争，他带着全家来到西部荒原，在一处偏僻的 山区开垦牧场。上校的妻子因为无法忍受艰苦的环境而抛夫弃子回到了东 部，威廉上校独自一人肩负起了养育三个儿子的重担。在艰苦的环境中三兄弟渐渐长大，他们手足情深但性格却大不相同。 大哥艾尔弗莱德为人忠厚，办事认真；三弟塞缪尔是位理想主义者，深 受父亲的宠爱；而老二特里斯坦则是一位狂放不羁的人，他自由奔放，常 与印第安人交往，从他们那里学到了不少东西。父子四人在一个纯男性的 世界里过着淡泊的生活。然而，塞缪尔大学毕业后，把未婚妻苏珊娜带回了家里。平静的生活 被打破了。艾尔弗莱德暗恋上了苏珊娜，而特里斯坦的气质却又打动了苏 珊娜的心。四个年轻人在痛苦地压抑着各自的情感。就在此时，第一次世界大战爆发了。三兄弟不顾父亲的劝阻，参军前 往欧洲。在战争中，特里斯坦眼睁睁地看着塞缪尔死去却无能为力。无限 悲哀的特里斯坦按印第安人的方式挖出了弟弟的心脏，带回祖国埋葬。艾尔弗莱德在向苏珊娜求婚被拒绝后离开了家乡。弟弟死亡的阴影也 使特里斯坦无法面对他所深爱的苏珊娜。特里斯坦也离家出走，从此杳无 音讯。在苦苦的等待中光阴流逝。苏珊娜心灰意冷，终于答应嫁给艾尔弗 莱德。这时，上校不幸中风，流浪多年的特里斯坦此时又回到了家中。在这 些年中，他吃了许多苦，回来后他娶妻生子，想过上平静的生活，一切似 乎就要这样平静的结束了，然而在一次进城返回途中，妻子不幸被人误杀， 这再一次燃起他心中躁动的烈火。苏珊娜一直对塞缪尔深感内疚，如今特里斯坦妻子的死又使他十分痛 苦，她忍受不住这样的折磨以自杀结束了自己的生命。而特里斯坦此时已 将所有的一切置之度外，他终于在父亲和大哥艾尔弗莱德的帮助下报了 仇。特里斯坦又重新过起艰苦的生活，他活的时间很长，他亲手送走了自 己的父亲，又亲眼看着自己的孩子结婚生子，他是在60年代的一场与熊的 激战中，被熊爪夺去生命的，他的死法很英勇... ...','After the Fall from Innocence the Legend begins.',30000000,160638883,26.952727,7.2,619,133,'1994-12-16','en','/avnHkpsf1Iq2JQLS6DTc9kkO1GY.jpg',3.4414056308757734,3,'2026-09-10',2,NULL,NULL),(4477,'与魔鬼同行','The Devil\'s Own','法兰西是北爱共和军成员，与一些志同道合的伙伴在北爱首府贝尔法斯特从事对抗英国政府军的工作。在一次任务中，他与同僚被出卖而被捕入狱。由于狱中的严刑铐打，因而潜逃出狱。在北爱的支持者法官彼德的协助下，法兰西化名罗伊丹凡尼，潜逃至美国纽约，寄住在毫不知情的警官汤姆欧梅拉（哈里逊福特饰）家中，并继续暗中从事飞弹的非法买卖，用来对抗英国政府军。由于对罗伊的过去一无所知，汤姆及其妻子希拉对罗伊的到皆表欢迎。不久，罗伊便与哥儿们西恩相逢，二人共商对策，如何将飞弹运出美国，同时法官彼德也为他们筹钱。但慢慢的罗伊爱上汤姆的家人及纽约的朋友，他开始在全新的未来及过去中挣扎。一晚，三个蒙面歹徒潜入汤姆家中，罗伊突然出现并击退入侵者，希拉打电话报警，但是在警察到达时，罗伊却悄悄地逃走。看著罗伊逃走，汤姆开始怀疑罗伊是否与这件事有关。罗伊返家后，汤姆严斥其不是，罗伊决定不惜一切代价，挥别过去……','They come from different worlds. They fight for different causes. Now, two men from opposite sides of the law are about to go to war.',90000000,140807547,15.350451,5.9,290,107,'1997-03-12','en','/6tANoM1KTZ7HCjjUa9Z9TSdo21Y.jpg',3.082630174252058,3,'2026-09-10',2,NULL,NULL),(4512,'神枪手之死','The Assassination of Jesse James by the Coward Robert Ford','杰西·詹姆斯，南北战争时期最著名的强盗，他与兄长组建的詹姆斯帮伙同其喽罗犯下无数宗抢劫案，即使防卫再出色的银行也难逃他们的魔掌。杰西凭借其出神入化的枪法和经历成为平民百姓心中的传奇人物。人过中年杰西逐渐厌倦颠沛流离和与政府捉迷藏的生活，手下的喽罗或死或伤，兄长也因杰西的坏脾气选择离开。新加入“詹姆斯帮” 的懦弱男孩罗伯特·福特视杰西为超级偶像，与渐感疲惫的杰西隐居乡间。然而经过多年的相处，罗伯特却最终成为这名传奇侠盗生命之闸的掣动者……','Beyond the myth lies America\'s greatest betrayal',30000000,14711793,35.53352,7,776,160,'2007-09-02','en','/rx4qjoteBLkaUhY42OLXn81P8fk.jpg',3.4974761134127768,3,'2026-09-10',2,NULL,NULL),(4513,'三十极夜','30 Days of Night','由导演大卫·斯雷德（David Slade）执导，讲述北美阿拉斯加最北端的小城镇里的人们在经历连续30天的极夜过程中与吸血鬼之间的较量。','They\'re Coming!',30000000,75505973,33.394082,6.2,767,113,'2007-10-17','en','/7ffTkVlwqvbOhVfYJM0N7V6aCEk.jpg',3.3661885551697033,3,'2026-09-10',2,NULL,NULL),(4515,'狮入羊口','Lions for Lambs','一场阵容豪华的政治秀。 　　西海岸大学的两个热血青年Arian（Derek Luke 饰）和Ernest（Michael Pena 饰），受他们理想主义导师Dr. Stephen Malley（Robert Redford 饰）的精神鼓舞，决定去做一些积极追求生活理想的事情，奔赴阿富汗参加了反恐战争，但这两位青年绝对没有想到，所谓的战争，无关人类和平、国家大义，只是让自己在战场上活下去而已。 　　与他们命运紧密相连的另一端，美国国内情况迥然不。在加利福尼亚，苦恼的Dr. Stephen Malley试图以Arian和Ernest参战的事情为例，说服自己的学生Todd（Andrew Garfield 饰）不要放弃政治学习，但Todd全然反感Dr. Stephen Malley的激进想法。而在千里之外的华盛顿，总统候选人、参议员Senator Jasper Irving（Tom Cruise 饰）发现自己正卷入一场政治密谋，他准备向电视台记者Janine Roth（Meryl Streep 饰）透露有关阿富汗战争的惊人内幕，此番举动很可能直接影响到正在前线作战的Arian和Ernest的命运。','If you don\'t STAND for something, you might FALL for anything.',35000000,63215872,9.789027,6,216,92,'2007-10-22','en','/pbYmWrGF1DMMGnJlZlKjPWWhiTP.jpg',3.016645970900997,3,'2026-09-10',2,NULL,NULL),(4517,'伊丽莎白：黄金时代','Elizabeth: The Golden Age','故事发生在前作《伊丽莎白》的十五年后，此时的英国女王伊丽莎白一世(凯特·布兰切特饰)已经被政敌的无数次阴谋暗算历练得更加强大，她已经不再把国内的阴谋家们放在眼里，因为在她身边依然有那个忠诚无二的皇家重臣弗朗西斯·沃辛汉爵士(杰弗瑞·拉什饰)守护者。而女王则开始为壮大大不列颠的实力而伤神。摆在她面前的难题主要有两个：一是对内，如何降服处处与她作对的苏格兰女王玛丽·斯图尔特(萨曼莎·莫顿饰)；第二是对外，怎样将英国海军训练装备的更加强大，从而击败来自大洋彼岸的不可一世的西班牙王国的“无敌舰队”，并最终能英国登上海上霸主的地位。然而，伊丽莎白一世虽为至高无上的女王，但作为一个同样有血有肉、有七情六欲的女人，她在情感方面，则主要是与英国的沃尔特·罗利爵士(克里夫·欧文饰)纠缠不清。在英国的历史上，风流倜傥的爵士是伊丽莎白一世的宠臣，他热衷于冒险，为了替女王陛下寻找财富，于1584年4月率领由两艘帆船组成的探险队远征新大陆，三个月后，罗利爵士在今天的美国北卡罗来纳州登陆，成为最早抵达新大陆的西方人。虽然他的远洋探险并没有找到什么财富，但他对新大陆的精彩描述还是得到了伊丽莎白女王的赞赏。但事实上，这个号称女王情人的罗利已有家室，却始终无法摆脱女王对他的迷恋……','Woman. Warrior. Queen.',55000000,74237563,15.274137,6.6,303,114,'2007-09-09','en','/vX4vp0az2yn11KycIFZaNf1yvZ2.jpg',3.1530621923019244,3,'2026-09-10',2,NULL,NULL),(4518,'伊丽莎白','Elizabeth','英国，一五五四年。人称「血腥玛丽」的玛丽一世君临天下。她的父亲亨利八世与天主教会分道扬镳，自创英国国教。但玛丽一世是狂热的天主教徒，她藉着一连串的血腥镇压，将英国带回天主教门下，造成帝国更进一步的分裂。英国境内各种阴谋谣传不断，玛丽一世因此将同父异母的妹妹－伊莉莎白都铎公主加以软禁。','Declared illegitimate aged 3. Tried for treason aged 21. Crowned Queen aged 25.',30000000,82150642,14.179538,7.1,334,124,'1998-09-13','en','/fzUF6hQ9VcpljXBgwjrLujcAmGn.jpg',3.2218166244282194,3,'2026-09-10',2,NULL,NULL),(4523,'魔法奇缘','Enchanted','女孩吉赛尔美丽的歌声飞遍森林，小动物们轻轻的和着，王子被深深地吸引。于是，王子和女孩一见倾心，正准备着他们盛大的婚礼。谁知，坏王后为了保住自己的权利，从中作梗，把吉赛尔送到了21世纪的纽约街头。吉赛尔（艾米•亚当斯 饰）无所适从的游走在喧嚣的纽约，没人知道她是真的公主，她害怕极了，找不到能够帮她的人。幸好，好心的律师罗伯特（帕特里克•德姆西 饰）收留了她。渐渐的，公主纯真的心打动了原本刻板的律师，机缘巧合，相遇的两个人互生情愫。而这时，爱德华王子（詹姆斯•麦斯登 饰）也不顾一切地，穿越时空，来到了纽约，营救他心爱的公主。公主真爱的天平，将倾向何处…','This fairytale princess is about to meet a real Prince Charming',85000000,340487652,29.21998,6.6,1449,107,'2007-11-20','en','/tYDH8drc45kJ9Zh0j708V3cLCMi.jpg',3.5785130268423533,3,'2026-09-10',2,NULL,NULL),(4547,'战栗空间','Panic Room','梅格•阿特曼刚刚与丈夫离婚，她带着11岁的女儿莎拉新搬到一个古怪的房子——里面暗藏了一个密室，密室里有16个摄录机，8个监视器，还有一条不与外面的线路连接的电话线，以及一道坚不可摧的房门。没有料想过有朝一日会用上这间密室的母女俩，第一夜就遭遇了不速之客——房子的建造者伯罕姆、前屋主的孙子朱尼尔、以及他请来的帮手劳尔。他们想要朱尼尔祖父的大笔遗产，随着他们步步逼近梅格藏身的密室，一场斗智斗勇的游戏开始了，而患有哮喘的莎拉，能不能在这场斗争中存活下来？',NULL,48000000,196397415,53.043124,6.5,1267,111,'2002-03-29','en','/sfSya28qMIkj4fK8mnoCpx5U8cw.jpg',3.5802954060426933,3,'2026-09-10',2,NULL,NULL),(4550,'亲切的金子','친절한 금자씨','金子20岁时，就因被控“诱拐儿童”入狱而成为头条新闻，人们惊诧于她的美貌、她的年轻。在13年的牢狱生活中，有着天使般容貌的她是狱中绝对的模范。金子尽心尽力地帮助身边的每一个人，因此狱友们都称她为“亲切的金子”。表面上金子似乎比谁都诚实守纪，但内心里的复仇火焰一天也没有熄灭。','All she wanted was a peaceful life... they didn\'t give it.',0,23803308,17.074843,7.4,356,115,'2005-07-29','ko',NULL,3.2759074515439264,3,'2026-09-10',2,NULL,NULL),(4551,'一酷到底','Be Cool','奇利·帕尔默曾经是混迹黑道的嚣张人物，不过黑道混久了，或许是因为厌倦，很多人开始洗白自己，找份体面的工作，得到社会的认可。奇利也不例外，从黑道退役后，他摇身变作好莱坞电影制片人，纯熟的社交手段使他的事业蒸蒸日上，名气大增，尝到甜头的奇利开始进军乐坛。他找来一位开唱片公司的朋友，不料朋友却意外死亡，奇利只好寄望于这位朋友的妻子艾迪，艾迪也是个狠角色，两人磨合良久才达成共识，决意捧红一名有着优异音乐天赋的黑人女孩琳达，然而事情却并非想象中顺利，琳达的经纪人为了留住琳达，使尽刁钻权术，而更令人意想不到的是，琳达竟然同时在被俄罗斯的黑手党秘密追杀。面对混乱的局面，已金盆洗手的奇利是否要重操旧业，摆平一切呢？','Everyone is looking for the next big hit',53000000,95226116,18.61472,5.4,292,118,'2005-03-04','en','/vg93H1WmWjy5NyEqw16zTI4yBqP.jpg',3.04856124340097,3,'2026-09-10',2,NULL,NULL),(4553,'机械师','The Machinist','如果你根本没有睡着，又如何从噩梦中醒来？特雷弗·莱兹尼克(克里斯丁·贝尔)受失眠的困扰日渐消瘦。这一年以来，他都几乎没有正常的睡眠了。这种生活严重的影响了他的身体以及心理健康。他在自己的公寓里发现了一个神秘的字条；他在车间里总感觉有个工友和他在一起工作，但是没有别人能看到这个工友。随着他生活的世界逐渐变成一个现实的噩梦，他的女朋友，一位应召女郎，成了他生活中唯一可以安慰他的人。  他决定找到这一切的答案。然而当他开始试图恢复自我意识的时候，他发现他了解的越多，他就越抗拒知道更多。','A little guilt goes a long way...',5000000,8203235,35.252056,7.3,1247,101,'2004-02-09','en','/hzelseMGuOAW1J7KjeUo81vmy5o.jpg',3.687276406661347,3,'2026-09-10',2,NULL,NULL),(4566,'迈克尔·克莱顿','Michael Clayton','迈克尔·克莱顿是纽约一家大型企业律所的内部“清道夫”。受律所联合创始人马蒂·巴赫指派，这位出身警察世家的前检察官负责处理肯纳-巴赫-利丁律所最肮脏的勾当——从肇事逃逸、负面新闻，到顺手牵羊的阔太和腐败政客，克莱顿专门为客户收拾烂摊子。尽管对工作深感厌倦，他却与律所有着无法割舍的羁绊。在农化公司U/North，内部首席法律顾问凯伦·克劳德的仕途完全依赖于这场由肯纳-巴赫-利丁律所主导、看似即将成功和解的诉讼案。当律所王牌诉讼律师、才华横溢的亚瑟·埃登斯突然精神崩溃并企图破坏整桩案件时，马蒂·巴赫派迈克尔·克莱顿前去处理这场前所未有的灾难。而在处理过程中，克莱顿不得不直面自己所成之人的真相。[华纳兄弟]','The truth can be adjusted',25000000,92991835,18.961323,6.5,501,119,'2007-09-28','en','/tewDlVnyJuJcZKXnSsho8eaqqEt.jpg',3.2748049880447416,3,'2026-09-10',2,NULL,NULL),(4584,'理智与情感','Sense and Sensibility','达什伍德夫人与她的女儿们——埃丽诺、玛丽安及尚在豆蔻年华的假小子玛格丽特，在父亲去世后惨遭驱逐，失去了家园与遗产继承权。法律规定，宏伟的诺兰庄园必须传予他与前妻所生之子、即姑娘们的异母兄长约翰，而约翰的人生伴侣是那位表面优雅却精于算计的范妮。正当贫困的达什伍德一家即将陷入更深窘境时，达什伍德夫人的表亲约翰·米德尔顿爵士伸出援手，将她们安置于自己广阔的德文郡庄园内一处名为巴顿小屋的新居。','Lose your heart and come to your senses.',16500000,135000000,20.898711,7.2,352,136,'1995-12-13','en','/eIrbkRa3ydxLRb6tqXUPQgLzhIz.jpg',3.261686932093633,3,'2026-09-10',2,NULL,NULL),(4597,'激战运钞车','Armored','哈克特（哥伦布·绍特 Columbus Short 饰）、拜尼斯（劳伦斯·菲什伯恩 Laurence Fishburne 饰）、杜比斯（斯基特·乌尔里奇 Skeet Ulrich 饰）、潘梅尔（阿莫里·诺拉斯科 Amaury Nolasco 饰）几个人都任职于一个保安公司。每天的工作就是开着荷枪实弹的装甲车负责押运上千万的现款。大家最近都面临着一个严峻问题——缺钱，于是几个人不免开始动起了歪脑筋。虽然哈克特不情愿，不过其他人的威逼利诱下，他最终还是半推半就的加入了该计划，他们的目标是：打劫自己押运的4200万现金。有老朋友同时也是这方面的行家奎因（让·雷诺饰）帮忙，事情进行得相当顺利。不过在实施计划的当天，一切在计划中的事情突然被一件意外之事打断：有人开枪打死了一个无辜的流浪汉。哈克特因此想退出因而和众人产生了分歧。原本看似坚固的兄弟之情，因为这起意外而开始产生裂痕……','Who will be the last man standing?',20000000,22942221,15.21229,5.5,208,88,'2009-12-04','en','/oQrAXGkBy84FyGpWrY71ptqs7zD.jpg',2.9877816322186592,3,'2026-09-10',2,NULL,NULL),(4599,'流行教母','Raising Helen','海伦•哈瑞思（凯特•哈德森 饰）深得模特公司老板的厚爱，时尚美丽的她懂得如何享受生活。可是，姐姐琳赛（菲丽西提•霍夫曼 饰）夫妇的突然离世，把三个分别只有15岁、10岁与5岁的孩子托付给海伦抚养。\r 面对可怜的孩子们，海伦努力习惯被改变了的生活，尽力做好监护人应做的事。可是她发现，自己以往繁忙的工作与长时间照顾孩子是互相冲突的，更导致了她失去了她喜爱的事业。与孩子们的相处与教育上，她也遇到了困难。\r 这时海伦把孩子们安排到了同一所学校就读，也幸好得到校内牧师丹（约翰•科比特 饰）帮助海伦解除困境，两人也在这时候发生了感情。\r 到最后海伦是否能担当好监护人的角色？她与丹的感情又能否更进一步呢？','Her uptown life gets turned inside out!',50000000,49718611,13.298205,5.9,189,119,'2004-05-27','en','/igRjm4dPHRzddnlg9hy3VGDkWdn.jpg',2.9903950819962843,3,'2026-09-10',2,NULL,NULL),(4614,'惊天核网','The Sum of All Fears','1973年的第四次中东战争中，一架携带着核武器的以色列战机在叙利亚被击毁，核弹随之便被时间和风沙掩埋。然而29年后，核弹却被一对平民夫妇掘起，并廉价变卖给军火商，最后兜售给了恐怖分子，而这些恐怖分子正在策划一场在美国繁华集会地点的核爆，并将其嫁祸给俄罗斯，意在挑起新一轮世界大战。年轻警觉的CIA情报分析师杰克·瑞恩（本·阿弗莱克 Ben Affleck 饰）在与俄罗斯新任总统会面时，隐约感到事有蹊跷，并通过眼线很快洞察了恐怖分子的惊天阴谋。然而瑞恩的判断却未能得到局里的重视，在一筹莫展之际，他得到了资深睿智的老分析顾问威廉·卡伯特（摩根·弗里曼 Morgan Freeman 饰）的信任与合作，然而仅凭他们二人之力，能否赶在恐怖分子下手前找到核弹，阻止这一毁灭性的悲剧发生呢？\r 　　本片改编自美国军事作家汤姆·克兰西的同名小说。','27,000 nuclear weapons. One is missing.',68000000,193000000,22.392544,5.9,437,124,'2002-05-31','en','/o734hQYhWZXqogx5qShvCwtgNgy.jpg',3.18175201469505,3,'2026-09-10',2,NULL,NULL),(4638,'热血警探','Hot Fuzz','尼古拉斯•安奇尔（西蒙•佩吉 饰）在伦敦担任高级巡警，抓贼破案似乎是他最大的乐趣。为此他成为警局中最敬业最能干的警员。但这却招致了警长的妒嫉，可怜的尼古拉斯被调至一个偏僻平静的小镇当警察。\r 小镇已经几十年没有过恶性犯罪事件。尼古拉斯在那里过得相当郁闷 ，他觉得自己的擒贼本领没有施展空间。更令他烦恼的是，镇里警察局局长儿子丹尼•巴特曼（尼克•弗罗斯特 饰）也来凑热闹，成为他的搭档。这个新搭档麻烦至极，整天询问大城市的警员经历。正在尼古拉斯烦心于镇里鸡毛蒜皮的事务和身边的苯搭档时，镇里却发生了一桩案件，让尼古拉斯嗅到了大展拳脚的机会，惊心动魄的战役开始了。','Big cops. Small town. Moderate violence.',12000000,80573774,38.623178,7.4,2199,121,'2007-02-14','en','/zPib4ukTSdXvHP9pxGkFCe34f3y.jpg',3.883332030447094,3,'2026-09-10',2,NULL,NULL),(4657,'湖边疑云','Jindabyne','Stewart Kane, an Irishman living in the Australian town of Jindabyne, is on a fishing trip in isolated hill country with three other men when they discover the body of a murdered girl in the river. Rather than return to the town immediately, they continue fishing and report their gruesome find days later. The story of a murder and a marriage - a film about the things that haunt us.','Under the surface of every life lies a mystery',0,0,8.950864,5.7,25,123,'2006-07-20','en','/zozfpvbl8OezjqBsgFByTGkbnw8.jpg',2.5576073006357194,3,'2026-09-10',2,NULL,NULL),(4688,'穿越苍穹','Across the Universe','上世纪60年代中期是一个因为反战抗议、精神诉求和摇滚乐而异常喧嚣的时代，而在这样一个大环境下发生的爱情故事，不安中却又能显示出更多的浪漫情怀和热情……一对在爱情的道路上经历了太多障碍的小情侣裘德和露西，随着一群朋友和音乐家从利物浦码头的造船厂到格林威治镇那充满了创新的幻象中，再从底特律永远是骚乱的街道抵达越南杀戮血腥的战场，在罗伯特博士和凯特先生的引导下，积极地将自己投身于反战和反主流文化的运动中。然而，由于无法控制、来自外界的各种冲突引起的混乱，令裘德和露西最终走向了不同的道路……这一切都迫使着这对年轻的爱人拨开重重的阻碍，疯狂地寻找着那座灵魂的桥梁，能够将他们重新带回爱情的起点。','All you need is love.',0,0,11.872841,7.1,410,133,'2007-09-14','en','/b0y6Xkx5izPTjc1K3bWoq9Lu3c8.jpg',3.2745044921835,3,'2026-09-10',2,NULL,NULL),(4723,'南方传奇','Southland Tales','2005年7月4日，美国独立日当天，沉浸在欢乐气氛的得州亚比里安市人民突然迎来巨大灾难。一个带着死亡气息的蘑菇云在市中心升起，亚比里安从此在地球上消失。这一事件引发了针对伊朗、叙利亚、北朝和阿富汗的第三次世界大战。战争在美国境内引起一系列的问题，能源短缺、人权侵害、种族主义、极端主义、政治动荡……全美上下一片混乱。\r 在2008年大选之际，与共和党有着千丝万缕关系的动作明星鲍克瑟·桑塔罗斯（巨石强森 Dwayne Johnson The Rock 饰）失踪，当他再次出现时却已失去记忆。不久，他邂逅色情片女明星克瑞斯塔·瑙（莎拉·米歇尔·盖拉 Sarah Michelle Gellar 饰），一个攸关全人类命运的故事就此展开……','Have a nice apocalypse.',17000000,374743,9.349386,5.2,153,144,'2006-05-15','en','/7dbIDQ80z4bxiDlAvxRwc5TI44C.jpg',2.901375028223141,3,'2026-09-10',2,NULL,NULL),(4806,'落跑新娘','Runaway Bride','艾克(理查•基尔 Richard Gere 饰)是一名专栏记者，他的妻子就是顶头上司。然而，这并没有给他带来多少好运气，相反，和妻子性格不合离婚后，因这层关系艾克过得更加抑郁。一次偶然，艾克在酒吧里听闻了马里兰州一名女子玛琪(朱莉娅•罗伯茨 Julia Roberts 饰)三次踏上红地毯时临阵脱逃的故事。他对这件事深感兴趣，并将其写成了专栏。当艾克去到实地采访当地人时，没想到人们普遍对他的做法感到很愤怒。而即将第四次踏上红地毯的事件主人公玛琪因为看了艾克的专栏后大感尴尬，第四次临阵逃脱。玛琪认为是艾克害惨了自己，决定以牙还牙。','Catch her if you can.',70000000,309457509,20.230535,5.7,455,116,'1999-07-30','en','/gylepJHGkdYlYJW9CGJRGFG8fJZ.jpg',3.1618840336611806,3,'2026-09-10',2,NULL,NULL),(4816,'鬼狗杀手','Ghost Dog: The Way of the Samurai','\"居住在新泽西的黑帮杀手“鬼狗”（Forest Whitaker弗雷斯特•惠特克 饰）身为非裔，却浸淫在日本武士道的精神世界里，“忠义”为其平生最高信条。他深居简出，不苟言笑，日常与老大靠飞鸽传书联系。鬼狗视老大路易（John Tormey 饰）如亲生父亲，接到命令后决不手软，手起刀落，血浆四溅。\r 孤独的他也有可以交心的朋友，闲暇时与公园买冰淇淋说法语的非裔聊聊天，各说各话，却也有趣；或与爱看书的小女孩交流品读《罗生门》的心得。\r 鬼狗活在自己的世界里，但周遭已发生巨大变化。终于有一天，他被路易抛弃，成为帮派倾轧的牺牲品……\"','All assassins live beyond the law … only one follows the code',0,0,18.223139,7.2,298,116,'1999-09-13','en','/gjcl07r9zgQ9tVo9alyHmysPFfX.jpg',3.207952852688342,3,'2026-09-10',2,NULL,NULL),(4824,'狙击职业杀手','The Jackal','一直以来，联邦调查局副局长卡特（西德尼·波蒂埃 Sidney Poitier 饰）和俄国情报官瓦伦蒂娜（戴安·维诺拉 Diane Venora 饰）都在追击一名十分危险的犯人，他手持高杀伤性化学武器，精通电脑和变装术，个性狡猾又残忍，是威胁到世界和平的重大隐患，他甚至连名字都没有，人送代号“豺狼”（布鲁斯·威利斯 Bruce Willis 饰）。  　　在屡战屡败的不利立场之下，卡特和瓦伦蒂娜决定动用手上的“秘密武器”——一位曾经和豺狼交过手的被囚杀手莫昆（理查·基尔 Richard Gere 饰）。在经验丰富的莫昆的帮助下，卡特一行人能否顺利捕获豺狼呢？对于莫昆来说，前路上又有怎样的危险在等待着他呢？','How do you stop an assassin who has no identity?',60000000,159330280,19.747459,6.1,527,124,'1997-11-14','en','/bM5BAqLZn8zMxzrtugH6PfzDrsF.jpg',3.2386186729447592,3,'2026-09-10',2,NULL,NULL),(4836,'夹心蛋糕','Layer Cake','X先生（丹尼尔·克雷格 Daniel Craig 饰）可谓是一名业绩丰厚的毒品贩卖精英，然而在他正想功成名就提前退休的时候，买卖却没这么轻易放过他。他的大客户吉米（肯内斯·库兰汉姆 Kenneth Cranham 饰）给他带来了两单交易：找到竞争对手埃迪（迈克尔·刚本 Michael Gambon 饰）失踪了的女儿，同时帮助公爵将手里的巨量摇头丸顺利出手。这次任务看似小菜一碟，然而在追踪埃迪女儿的过程中，X先生竟从埃迪口中得知此事另有蹊跷。吉米原来是警方卧底，此次行动就是为了使X先生锒铛入狱。而当X先生在着手第二个任务时，又无意中发现公爵因为这批摇头丸而与心狠手辣的塞族人结怨。随着事态发展，X先生发现自已已不知不觉深入险境，他心目中那个平静的晚年似乎已变得越来越遥远和艰难，如同他的名字一般，能否从危机中全身而退才是眼前最大的未知数……  　　本片根据J.J.康纳利的同名小说改编。',NULL,6500000,11850214,24.0034,7,559,105,'2004-09-30','en','/rDOxXteqxALBaSa3V3zTjGJuyWB.jpg',3.3782961068281265,3,'2026-09-10',2,NULL,NULL),(4858,'致命拜访','The Invasion','一艘太空船在华盛顿附近的小镇坠毁，人们一觉醒来，发现身边的人变得冷漠而陌生。精神科医生卡罗尔（妮可•基德曼 饰）和助手本（丹尼尔•奎格 饰）几经周折，发现这种变化是因为感染了外星病毒。灾难不可控制的蔓延，感染的人越来越多，他们占领城市，设置隔离区，想把人类变成没有情感的怪物，卡罗尔带着儿子奥利弗开始逃亡，她惊奇地发现奥利弗正是拯救人类的希望。','Do not trust anyone. Do not show emotion. Do not fall asleep.',80000000,15071514,15.673154,5.7,359,99,'2007-08-17','en','/tXqBv4phGJDYJpmVY3rJXVV9cGD.jpg',3.1068691724122024,3,'2026-09-10',2,NULL,NULL),(4911,'私法行动','Dark Blue','1992年4月的洛杉矶, 种族气氛非常浓烈。当时有一个曾经引起市民震惊全美的大骚乱的案件：4个白人警官殴打黑人而被判无罪。本片正是讲述宣判前几天警署里面发生的事情。  　　洛杉矶警局精锐的特别调查小队接受了一个倍受关注的4条人命案。其间警探艾尔顿•佩里(库尔特•拉塞尔Kurt Russell 饰)向新人鲍比•泰德鲁(斯科特•斯比德曼Scott Speedman 饰)讲述差馆种种腐败、阴暗的现象；而黑人警官豪岚(文•雷姆斯Ving Rhames 饰)亦对警署极为不满，决心追查到底。就这样，几个警员在腐败丛生的环境中，坚守着良心和正义。影片揭露了当时洛杉矶警署内部贪污、勒索、酷刑等内幕，这些错综复杂的因素最终引发了全美震惊的市民暴乱。','1992, L.A is at boiling point. One cop\'s turning up the heat',15000000,9237470,6.373316,6.5,85,118,'2002-12-14','en','/ekW39lKhQ3L3rdOgzyF3d0CoPLV.jpg',2.8277337631785433,3,'2026-09-10',2,NULL,NULL),(4912,'危险思想的自白','Confessions of a Dangerous Mind','一心要出名发财的查克·巴瑞斯(萨姆·罗克威尔饰)在一次偶然中赤裸的与他未来的妻子潘妮(德鲁·巴里摩尔饰)见面了。这绝对是一个巧合，因为他只不过是刚刚和潘妮的室友上了床，光着身子到她们厨房找东西而已。但更加巧合的并不仅仅这些。巴瑞斯后来不仅凭借机遇当上了电视台几款疯狂的综艺竞赛节目的主持人，而且还被中央情报局的吉姆(乔治·克鲁尼饰)看中。吉姆要巴瑞斯利用主持人的身份作掩护，执行暗杀计划。为了国家的荣誉，巴瑞斯义不容辞，何况还有美丽的帮手帕特丽夏(朱丽娅·罗伯茨饰)在暗中帮忙呢！ 这个奢靡、夸大、好色的家伙，于是开始了一场绝对疯狂的双面游戏。但这种时而命悬一线，时而众人瞩目的角色，真的可以为他带来期待的人生么？','Some things are better left top secret.',30000000,33013805,18.165957,6.6,275,113,'2002-12-30','en','/mM58ABMRzwn5zVx6BS7IiNK0j3F.jpg',3.135803927547503,3,'2026-09-10',2,NULL,NULL),(4922,'本杰明·巴顿奇事','The Curious Case of Benjamin Button','飓风正在侵袭美国新奥尔良，一位病危的老妇睁开了她的睡眼。老妇名叫戴茜，她叫女儿凯若琳 为她阅读一本日记。这本日记的作者叫本杰明•巴顿。本杰明出生在第一次世界大战停战之时，但生来便像个老人的他被父亲当作怪物，被遗弃在了养老院。本杰明在养老院与老人们一起生活。但谁都没有想到，本杰明逆向发育——越活越年轻！也许“越活越年轻”是某些人的梦想，但真正这样成长的本杰明却有了别人无法理解的烦恼与快乐。穿越半世纪的世界变革，本杰明身处其中，感受别人感受不到的感受。','Life isn\'t measured in minutes, but in moments.',150000000,333932083,60.269279,7.3,3292,166,'2008-11-24','en','/26wEWZYt6yJkwRVkjcbwJEFh9IS.jpg',4.0219224713014174,3,'2026-09-10',2,NULL,NULL),(4929,'吊人索','Hang \'em High','故事讲述哥伯误被当成盗贼，遭人用刑，便把他绑于绳上，欲置他于死地。幸好，哥伯大难不死，更决定要找出他们来进行大报复……','The hanging was the best show in town. But they made two mistakes. They hung the wrong man and they didn\'t finish the job!',1800000,6800000,11.756943,6.7,192,114,'1968-07-31','en','/gFvRKgCAa1MKlcAKZfoDNdR2dgy.jpg',3.0401748654765575,3,'2026-09-10',2,NULL,NULL),(4935,'哈尔的移动城堡','ハウルの動く城','18岁少女苏菲在街上遇到神秘青年霍尔，霍尔忽然抱起苏菲一同飞上天空，苏菲的心从此深深地被霍尔吸引。然而那天晚上，苏菲被名叫荒地魔女的女巫施了魔法，外表变成了90岁的老婆婆。心灰意冷的苏菲只好整理行李，远离人群，前往霍尔在荒郊野外的城堡……','',24000000,234710455,30.9909,8.387,1991,119,'2004-09-09','ja','/mOkZtsb8UObRAa77EDTmbPB5BuY.jpg',4.0537674423707895,3,'2026-09-10',2,NULL,NULL),(4942,'爱情达阵','Leatherheads','道奇（乔治·克鲁尼 George Clooney 饰）所带领的橄榄球队由于投资方拒绝继续赞助而面临着被迫解散的下场，为了自己挚爱的橄榄球运动，也为了一同流血流汗的队友们，道奇必须想出解决的办法。大学橄榄球明星卡特（约翰·卡拉辛斯基 John Krasinski 饰）的出现吸引了道奇的注意，一个绝妙的注意应运而生。\r 道奇将卡特纳入了队中，利用其明星效应成功的吸引了公众的目光。卡特的履历表上写满了他的英雄事迹，曾经凭借一人力量让众多德军缴械投降的事迹也屡屡被人提起。但是，对于新闻记者莱西（芮妮·齐薇格 Renée Zellweger 饰）来说，卡特的历史充满了疑点。为了查明真相，莱西想方设法的接近了卡特，没想到，她的美貌和美丽却在橄榄球队中掀起了轩然大波。','If Love Is a Game, Who\'ll Make the First Pass?',58000000,41299492,7.739276,5.7,130,114,'2008-03-24','en','/dl2yu8iuwG3dqbpjalm2odadRaH.jpg',2.8913505584631087,3,'2026-09-10',2,NULL,NULL),(4944,'阅后即焚','Burn After Reading','本片根据曾于1977年至1981年间担任美国中央情报局局长的斯坦菲尔德·特纳的小说《高度机密：总统、中情局局长和特工》改编而成。 　　Osbourne（约翰·马尔科维奇 John Malkovich 饰）是CIA的资深分析员，因酗酒问题被开除。沮丧的Osbourne回到家中又不被老婆重视。他妻子Katie（蒂尔达·斯文顿 Tilda Swinton 饰）是个冷冰冰的职业医生，与财政部的Harry（乔治·克鲁尼 George Clooney 饰）偷情，在船上共度春光。Osbourne赌咒写一本自传来透露CIA的高极机密，却被一心想跟自己离婚的Katie错拿去记录调查自己的财政报告，后又不慎落在了健身房。被傻里傻气的健身房女员工Linda（弗兰西斯·麦克多蒙德 Frances McDormand 饰）和稍有点二百五的健身教练Chad（布拉德·皮特 Brad Pitt 饰）拾得，这下一直为整容手术费用发愁的Linda有了主意，决定去敲诈。这一群人的命运就因为这张光盘而发生了变化。','Intelligence is relative.',37000000,163720069,31.941347,6.5,1222,96,'2008-09-05','en','/iQFbKNrCnUQ9upDav1qLcRAjoSW.jpg',3.523269570671664,3,'2026-09-10',2,NULL,NULL),(4951,'我恨你的十件事','10 Things I Hate About You','比安卡是全校公认的甜心宝贝，可事实上，她甚至未有过一次约会——比安卡的老爸对女儿的管教极尽苛刻，男生们只能对她望而却步。在女儿的不断抗议下，老爸终于做了“让步”，他声明，比安卡可以约会，只要她的姐姐凯特也去。听到这个消息，暗恋比安卡的喀麦隆决心无论如何都要找到能和凯特约会的人。千挑万选之下，他找到派特里克帮忙。凯特可是人人眼中的怪物啊，仿佛愤世嫉俗般，对任何人和事都有一股不满的情绪。要让约会顺利进行，这是前所未有的挑战，还是一个不可能的任务？','How do I loathe thee? Let me count the ways.',16000000,53478166,54.550275,7.3,1701,97,'1999-03-30','en','/ujERk3aKABXU3NDXOAxEQYTHe9A.jpg',3.823276521184066,3,'2026-09-10',2,NULL,NULL),(4953,'王牌制片家','Be Kind Rewind','在爵士乐大师“胖子沃勒”成长的新泽西帕塞克小镇上，弗莱彻老人（丹尼•格洛弗 Danny Glover 饰）带着对大师的回忆，在商业化大潮中坚守者一家录像带出租店，黑小伙迈克（茅斯•达夫 Mos Def 饰）和镇上神经质的无业游民杰瑞（杰克•布莱克 Jack Black 饰）整日盘踞在录像带店，杰瑞最近感到发电厂的微波辐射正在控制小镇居民，遂要求迈克和他一起炸毁发电厂，但是受旅行的弗莱彻所托照顾店子的迈克临阵退缩，导致杰瑞任务失败，出人意料的是，杰瑞自此变成了“磁化人”，录像带全部因为杰瑞的磁化而失去了画面！老顾客费罗唯茨小姐（米亚•法罗 Mia Farrow 饰）每日和弗莱彻通话，为了不让弗莱彻发现店中变故，迈克和杰瑞假装一切如常，他们不得不开始自己拍摄电影，以瞒过弗莱彻和小镇电影迷们……','You name it, we shoot it.',0,0,17.662683,6.2,424,102,'2008-01-20','en','/f0oX20YrQEiVPDH9InCQ1d3Cm66.jpg',3.1979678291299094,3,'2026-09-10',2,NULL,NULL),(4958,'重返荣耀','The Legend of Bagger Vance','一战的硝烟渐渐散去，饱经战火洗礼的年轻人兰努夫·朱诺（马特·达蒙 Matt Damon 饰）拖着疲惫的身心，回到了故乡佐治亚州的萨凡纳。兰努夫曾是镇上最为著名的业余高尔夫球手，但是战火阻断了他的梦想，也让他暂时作别心爱的女孩爱黛尔·因夫戈登（查理兹·塞隆 Charlize Theron 饰）。爱黛尔的父亲是当地最有钱的人，他打造了超豪华的高尔夫球场，曾经轰动一时，只是经济大萧条让球场的经营举步维艰。为了让爱人重振信心，也为了让球场再现辉煌，爱黛尔邀请了两名职业选手与兰努夫比赛。希望之光慢慢降临……','It Was Just A Moment Ago.',80000000,39459427,16.848899,6.3,251,126,'2000-11-02','en','/bJO8wKCmsusJQplaMG54mbPcjHS.jpg',3.0873758237673194,3,'2026-09-10',2,NULL,NULL),(4959,'跨国银行','The International','一位国际警察组织的主管（克里夫·欧文饰）奉命调查一家全球知名的银行业机构，后者被怀疑与国际军火交易，以及一些贪污腐败和谋杀案件有着密切关系。娜奥米·沃茨在片中扮演欧文的助手——一名曼哈顿的律师，与欧文一起对这宗案件进行调查。 执着的国际刑警在调查一桩离奇案件的过程中，逐渐将矛头指向了某全球规模第一的金融机构。随着涉入渐深，刑警先生惊觉该组织长期以来一直在通过操纵各国政坛、利用各地的腐败牟取暴利、contraband包括核弹头在内的ammo以及针对首脑政要的暗杀等一系列跨国犯罪行径，来达到从背后遥控整个世界的邪恶目的。于是，他将和自己半道儿上英雄救美得来的靓女检察官一起，扫除这片笼罩着整个地球的不祥的阴影。 经济全球化的坏处在今年得到了一次历史性的集结展示，可本片的关键镜头补拍却让索尼方面痛失在秋天的金融危机爆发初期趁火打劫的上映计划。于是乎一延再延，直到影迷开始揶揄\"不会是烂片吧？\"，才终于碍着面子定格在情人节的黄金档。不过预告片糅杂了《生死狙击》、《谍影重重》、《刺杀疑云》的风格以及跟中国有关的情节，再度点燃影迷们对《跨国银行》的热情，且看两位奥斯卡提名者联袂主演的惊悚片有啥内涵吧.','Is your money making a killing?',50000000,60161391,13.391833,6,368,118,'2009-02-03','en','/4Rv53hIi0ovKgfgrDw7oBVmDI9N.jpg',3.1365466119799006,3,'2026-09-10',2,NULL,NULL),(4960,'纽约提喻法','Synecdoche, New York','9月，伴随着秋天到来的，似乎还有戏剧导演凯顿（菲利普·塞默·霍夫曼 Philip Seymour Hoffman 饰）的孤独，因一次意外的受伤，凯顿陷入了无休止的诊疗，不停拜访各专业医生；另一方面，创作微缩油画的妻子阿黛尔（凯瑟琳·基纳 Catherine Keener 饰）和他日渐疏远，冷漠尴尬的家庭气氛加深了凯顿的自我怀疑，即便他的剧目获得巨大成功也不能掩盖这一切。凯顿与在剧场工作的女子以及一名女演员保持着暧昧关系，在妻子抛弃他之后，凯顿从这两个女人身上试图找到改善自我精神状态的可能性，然而他还是失败了。凯顿最后决定从戏剧中找到答案，他产生了一个庞杂的创作计划……',NULL,21000000,0,12.761176,7.4,278,124,'2008-10-24','en','/uo7SJzExKg8A0zVX7VsWusQWV2Y.jpg',3.1924160123667136,3,'2026-09-10',2,NULL,NULL),(4964,'一夜大肚','Knocked Up','本片讲述一夜情引发的意外后果。贾德·阿帕图以喜剧视角审视那件会打乱你所有完美计划的美好之事：为人父母。[环球影业]','Save the due date.',30000000,219076518,22.527211,6.2,1214,129,'2007-06-01','en','/bE5DxHVRMbi7qcPCOH3TD8DgAdg.jpg',3.443912860098685,3,'2026-09-10',2,NULL,NULL),(4965,'冒名顶替','Impostor','21世纪第一个50年，人类没有迎来最终的繁荣与和平，反而陷入旷日持久的星际战争中。地外文明辛塔利入侵地球，无数人类的勇士前仆后继，战死沙场。  　　时间来到2079年。为了最终摧毁外星入侵者，人类加紧对新式武器的开发。斯宾赛·奥哈蒙（加里·希尼斯 Gary Sinise 饰）是武器研发部门的工程师，他的研究取得突破，新式武器的诞生指日可待。而就在这关键时刻，斯宾塞的身份遭到质疑。政府怀疑他是辛塔利派来的间谍，其体内更藏有一颗威力强大的炸弹。他虽然不断辩解，但无济于事。眼看命悬一线，斯宾塞伺机逃亡。他一面躲避政府的追捕，一面要想方设法证明自己的清白。在这一过程中真相逐渐浮出水面，面对真相，斯宾塞本人也受到莫大震动','In the Future, not everyone is who they seem to be.',40000000,0,9.579975,6.1,135,102,'2001-12-03','en','/qhFyrikZzQjXW4TFTqsuXHYefH1.jpg',2.9218429999811404,3,'2026-09-10',2,NULL,NULL),(4967,'一如既往','Keeping the Faith','杰克（本·斯蒂勒 Ben Stiller）和布莱恩（爱德华·诺顿 Edward Norton）有着各自的信仰。布莱恩是一个天主教徒，为表虔诚，他最好终身不结婚。杰克是个犹太教徒，他可以成家立室，却有一个规矩需要遵守：妻子必须也是一名犹太教徒。于是，当青梅竹马的安娜（珍娜·艾夫曼 Jenna Elfman）重新出现在两人面前时，便掀起了他们生活的波澜。  　　他们心里都着迷于如今出落得明艳大方的童年伙伴安娜，正如很多爱情轻喜剧一样，一段搞笑而又美好的感情开始了。两人在这段感情上都有着宗教信仰的阻碍，布莱恩约会安娜时，更是遮遮掩掩，生怕和安娜这个非犹太教徒一起会招致旁人话柄。信仰会否令真爱错失，安娜最终情归何人，这段感情的悬念还多着呢。','If you have to believe in something, you may as well believe in love.',30000000,37036004,8.085872,5.9,159,127,'2000-04-14','en','/9NF199FTvHr9ggqdBTVbPhF1MGk.jpg',2.9428842742144274,3,'2026-09-10',2,NULL,NULL),(4970,'鬼影人','Gothika','年轻干练的米兰达（海莉·贝瑞 Halle Berry 饰）是一名卓有成就的犯罪心理学家，她和丈夫共同经营一家精神治疗机构，两人无论生活还是事业都春风得意，顺风顺水。不过一向理性的米兰达也遇到了难缠的对手，她的病人之一克罗伊（佩内洛普·克鲁兹 Penélope Cruz 饰）因谋害继父背叛入狱，克罗伊经常沉浸在不切实际的幻想中，这令米兰达困扰不已。在某个雨夜，米兰达驱车回家途中险些撞上一名小女孩，继而发生了令人难以置信的事情。当她从昏迷中苏醒后，发现自己被关在了精神病院，接下来则要面对谋杀丈夫的指控。米兰达想方设法要证明自己的清白，在这一过程中也发现了恐怖、黑暗的真相……\r 　　本片荣获2004年青年选择奖最佳女主角奖（Halle Berry）。 ©豆瓣','Because someone is dead doesn\'t mean they\'re gone.',40000000,141591324,27.303608,5.8,629,98,'2003-11-21','en','/frSGNQcWx1ek8dCduFYCux1ho7n.jpg',3.2523630125120855,3,'2026-09-10',2,NULL,NULL),(4982,'美国黑帮','American Gangster','上世纪70年代，哈莱姆黑人区，弗兰克•卢卡斯（丹泽尔•华盛顿 饰）是黑帮老大约翰逊的司机。约翰逊暴毙后，弗兰克充分利用了这个来之不易的机会，将地下世界的所有权利分配进行了重组，成功上位，接手大佬事业，掌控了毒品交易大权。期间他远赴东南亚金三角走私高纯度海洛因，张罗自己的家族兄弟，集结了一帮为他卖命的手下，一股黑暗势力正在兴起。 　　另一边，警察里奇•罗伯茨（卢塞尔•克劳 饰）家庭破裂，与主流社会格格不入，整天以一副邋遢鬼模样流连于街头。他慢慢觉察出毒品圈内的风起云涌，，并展开了秘密调查。 　　随着调查的深入，罗伯茨和卢卡斯之间的距离越来越短，两个气质相近，惺惺相惜的男人，不可避免地进行正面对决……','There are two sides to the American dream',100000000,266465037,42.361215,7.4,1502,157,'2007-11-02','en','/sX9idXDqRUxE5ffww3n3RV5gL55.jpg',3.7791070486571114,3,'2026-09-10',2,NULL,NULL),(4995,'不羁夜','Boogie Nights','故事发生在上世纪70年代，17岁的夜店服务生艾迪（马克·沃尔伯格 Mark Wahlberg 饰）天生拥有巨大的秘密武器，一次偶然机会，他被色情片导演杰克（伯特·雷诺兹 Burt Reynolds 饰）看中。于是，艾迪改艺名为德克，在杰克的栽培下在色情电影界大放异彩，成 了该行业的天皇巨星。因为所拍影片都很卖座，杰克和德克名利双收，过着豪华无度的生活。然而进入80年代以后，色情电影工业发生了重大变化，过去辉煌的历史一去不返，德克和杰克这对色情电影业的最佳拍档也分道扬镳……','The life of a dreamer, the days of a business, and the nights in between.',15000000,43101594,19.85579,7.5,796,155,'1997-09-11','en','/tbUipowcqHBKd7nCuWJBS3R4ow1.jpg',3.5471992049998256,3,'2026-09-10',2,NULL,NULL),(4997,'仙境大道谋杀案','Wonderland','1981年，约翰·何姆斯（方·基墨饰）与他才十几岁的未成年女友（凯特·伯斯沃茨）卷进了一起洛杉矶奇境四尸命案中难以脱身。故事一开始，约翰·何姆斯已经从最著名的影星，沦落到为金钱和药物毁灭的状态。尽管何姆斯倾力爱着他的少年女友Dawn，然而他还是和Sharon结了婚，于是在他们之间形成了显而易见的三角恋关系。这时何姆斯又援助当地毒品交易者罗恩和苏珊·劳纽斯，很快何姆斯就陷入深深的债务和绝望中，为了使自己免遭臭名昭彰的强盗埃迪·纳什的暴力，何姆斯只能去杀害他最好的朋友……尊荷斯(韦基马饰)凭着十四吋那话儿，在色情界一直很吃得香﹕由他主演的成人电影超过二千部，堪称四仔片天王，慕名者众。超过一万名女子与他发生过关系。挥金如土是他的写照，只因钱银去得快来得更快。然而，他过气了。收入减少支出依旧，尊荷斯顿然陷入经济困境，偏偏这时候接触到毒品。变卖了所有家俱仍未能过足瘾，身无分文的尊荷斯只好投靠同道损友，蛇鼠一窝尽在九反地带。爆窃、抢刧、贩毒无所不为，只因一切离不开一个「钱」字，最后竟然挑上恶名昭彰的艾廸纳殊，腥风血雨，开始降临在两帮流氓身上……','Sex, drugs, murder. Welcome to L.A.',5000000,2466444,7.79068,6.2,73,104,'2003-10-23','en','/mfG8S7D4rYeVqvTzjc3D36PAK3R.jpg',2.7885817788859106,3,'2026-09-10',2,NULL,NULL),(5038,'午夜巴塞罗那','Vicky Cristina Barcelona','维琪与克莉丝汀娜来到巴塞隆那旅游，克莉丝汀娜性感而大胆，维琪则是理性已有婚约，两人不约而同遇上了风度翩翩的瀟洒艺术家Juan Antonio，噯味的情愫与异国情调，在两人的友情与感情世界掀起大波涛。维琪一开始认为Antonio是个玩世不恭的花心男人，但在相处多日后，两人之间產生了爱情，让维琪内心充满矛盾，开始怀疑自己对未婚夫的忠诚度，自己是否真的準备好步入礼堂？单身且喜爱摄影、对肉体接触与异国恋情感到刺激的克莉丝汀娜，则是享受著与Antonio的情慾关係，除此之外，与Antonio藕断丝连又火爆的疯狂前妻Maria Elena也突然出现。原本豪放不羈的克莉丝汀娜，却发现自己爱上了这个完美男人，并且与Elena发展出另一段似有似无的蕾丝边情谊。这三个性格迴异的女人：对爱徬徨不安的维琪、豪放追求刺激的克莉丝汀娜与对爱神经质又火爆的Elena，将在旅程的终点寻找到什麼样的自我和真爱？','Life is the ultimate work of art',15000000,96408652,32.758254,6.7,1020,96,'2008-08-15','en','/nwVac9GeMDBOq1qVDL9NcGvgbe7.jpg',3.5159234560109884,3,'2026-09-10',2,NULL,NULL),(5072,'断头气','Severance','匈牙利近郊东部山区，一趟误入歧途驶向死亡的恐怖之旅。国际知名军火公司“篱笆防御”集团的老总为了庆祝业绩创新高，特意为员工们举办了一次豪华温泉乡之旅，共度这个周末。然而这次旅程却并非像员工们想得那么奢华美好，接二连三发生的恐怖血腥事件，让众人如坐针毡，人人自危。当众人来到荒无人烟并被群山环绕着的边境地带时，就已经个个胆战心惊。更令他们毛骨悚然的是，他们过夜的地方居然是一间废弃破旧的精神病院。而更糟的还在后面，一群手持该公司军火的俄罗斯人对他们发起了疯狂的攻击。','The Company Is Making Cutbacks',0,0,12.898984,6.4,169,96,'2006-05-19','en','/mdadz02hkGMFZQ4o3V0PWFD10Af.jpg',2.9947067721601135,3,'2026-09-10',2,NULL,NULL),(5123,'八月迷情','August Rush','莱拉（凯丽•拉塞尔 Keri Russell 饰），一个出色的大提琴手；路易斯（乔纳森•莱斯•梅耶斯 Jonathan Rhys Meyers 饰），一名流浪的爱尔兰歌手。一个月色迷离的晚上，两人相遇了。度过难忘的一晚后，莱拉那专横的父亲又强逼她继续踏上音乐会的旅程。路易斯因等不到恋人失望之下离开了；而莱拉发觉爱人走后，独自伤心的等待肚中的孩子出生。岂料几个月后莱拉遭遇了一场车祸，宝宝亦随之夭折。孰料，莱拉的宝宝其实并没有死，而是被她狠心的父亲送到了孤儿院。一晃眼10多年过去了，生活在孤儿院的少年奥古斯特（弗莱迪•海默 Freddie Highmore 饰）坚信自己的父母还在世上，于是踏上了漫漫寻亲路。','An incredible journey moving at the speed of sound',25000000,66122026,29.533437,7.1,797,114,'2007-11-21','en','/cAMmDJM2PH7P7qq33RJffYRgxTu.jpg',3.5070104593056954,3,'2026-09-10',2,NULL,NULL),(5125,'反恐疑云','Rendition','如果你深爱的人，突然人间蒸发般的消失了，你会怎么办？伊莎贝拉的丈夫安瓦尔•艾布拉汉姆，是一名埃及裔化工工程师，在结束了南非的工作任务后，搭乘飞机返家与妻儿团聚。安瓦尔刚一到达美国的机场就被警方无端扣押了，苦等多时的伊莎贝拉不相信丈夫会平白无故的消失。她求助前男友艾伦，希望这位CIA探员能寻获有关丈夫的蛛丝马迹。调查终于有了进展，他们发现安瓦尔的确遭人挟持……　　原来，安瓦尔之所以会“消失”，是由于其特殊的身份背景。美国的CIA当局怀疑中东移民身份的安瓦尔与多宗恐怖活动有关，为了一举铲除幕后的恐怖组织，CIA密谋绑架了安瓦尔，并在高层管理人员惠特曼的授意下，通过“非常规引渡”法则，将安瓦尔被秘密引渡至开罗。在秘密审讯室里，安瓦尔不仅受到中情局分析师道格拉斯的严辞逼供，还遭受到电击、水囚等严刑拷打，在那里遭到了惨无人道的虐待。无辜的安瓦尔能否活着走出审讯室？伊莎贝拉又能否再次见到心爱的丈夫？到底又是谁，能带给这对夫妻唯一的希望呢?','What if someone you love...just disappeared?',27500000,24748670,12.741073,6.2,205,120,'2007-09-07','en','/gebF4P3k0AyINOiYWrTVHUSy2EG.jpg',3.025577026575714,3,'2026-09-10',2,NULL,NULL),(5126,'火星的孩子','Martian Child','2年前，科幻小说家大卫·戈登（约翰·库萨克 John Cusack 饰）遭受了丧妻之痛，时间并未抚平他心中的伤口，反倒令其愈感空虚。为了排遣心中的孤独，大卫决定收养一个小孩，当然这个决定遭到周围亲友的质疑和反对。不顾他人的意见，大卫领养了名叫丹尼斯（鲍比·科尔曼 Bobby Coleman 饰）的小男孩。丹尼斯虽然清秀可爱，性格却非常古怪。他自称来自火星，终日躲在纸盒子里，不与其他小朋友玩耍，喜欢用没有胶卷的相机拍照。丹尼斯的到来为大卫的生活注入活力，也为他带来久违的爱情。而随着生活的继续，大卫却发现与火星男孩的相处实非易事……','doesn\'t matter where you come from, as long as you find where you belong!',0,0,5.737161,6.8,79,106,'2007-11-02','en','/amRUHHflkZsbcvRnfJN9ZKxv8R3.jpg',2.818608773374754,3,'2026-09-10',2,NULL,NULL),(5137,'天空上尉与明日世界','Sky Captain and the World of Tomorrow','在将来的某一天，纽约遭到了不明来历的攻击，天空上尉飞行员约瑟夫•苏立文（裘德洛饰）收到求救信号出手相助，在经过激烈的较量后，纽约迎来了暂时的平静，天空上尉也在这次战斗中偶遇并且救下了身为记者的旧情人波莉(格温妮斯•帕特洛饰)。原来波莉所调查的事件和这次袭击有着千丝万缕的联系，背后有一个巨大的阴谋。为了迎接即将到来的恶战，保卫世界，他们向海军女子特谴队队长弗兰姬•库克(安吉莉娜•朱丽饰)和技术专家戴克斯(吉奥瓦尼•瑞比西饰)寻求了帮助。一场正义与邪恶的较量揭开了序幕…… ©豆瓣','Who will save us?',70000000,57958696,24.664776,5.7,439,107,'2004-09-17','en','/gflMXZBFrhwpwGphxrk9YI9eSiO.jpg',3.1653008524094237,3,'2026-09-10',2,NULL,NULL),(5172,'The Astronaut Farmer','The Astronaut Farmer','Texan Charles Farmer left the Air Force as a young man to save the family ranch when his dad died. Like most American ranchers, he owes his bank. Unlike most, he\'s an astrophysicist with a rocket in his barn - one he\'s built and wants to take into space. It\'s his dream. The FBI puts him under surveillance when he tries to buy rocket fuel, and the FAA stalls him when he files a flight plan – but Charles is undeterred.',NULL,13000000,11130889,6.764437,6.2,123,104,'2006-10-15','en','/c6WlqXSQa8VKIO4EFFZHsDuRhY1.jpg',2.8997320026595856,3,'2026-09-10',2,NULL,NULL),(5174,'尖峰时刻3','Rush Hour 3','严肃机警的李探长（成龙 饰）和贫嘴的警探James Carter (Chris Tucker饰)，在成功完成两次的跨国任务之后，这次又迎来了更加艰巨的任务。调查“三和会”犯罪证据的韩领事被人暗杀，深感自责的李警官疯狂追击杀手，却被贬职当交警的James Carter帮了一个倒忙，理所当然，他们二日的奇特组合又开始。一方面，按照韩领事的线索，他们到了巴黎——这个“三和会”千方百计隐藏的心脏地带，克服重重困难，探索真相；另一方面，他们还要保护韩领事长大成人的女儿苏阳（张静初），而杀手，却是李探长小时候在孤儿院的好兄弟Kenji（Hiroyuki Sanada 饰）。重重危机之下，二人如何应对？尖峰时刻，李探长的中国功夫将扭转乾坤。','The Rush Is On!',140000000,258022233,22.57178,6.1,783,91,'2007-08-08','en','/9xTiZXqf4MsRyXsBiJVK95JVrUL.jpg',3.330539330465226,3,'2026-09-10',2,NULL,NULL),(5175,'尖峰时刻2','Rush Hour 2','李督察（成龙 饰）和从洛杉矶赶来香港度假的老搭档詹姆斯•卡特（克里斯•塔克 Chris Tucker 饰）真是一刻不得闲，因美国领事馆遭到炸弹袭击，两名工作人员身亡，李督察只得带上卡特去拜访三合会头目、也是自己父亲的昔日搭档邓力奇（尊龙 饰），邓力奇的手下胡莉（章子怡 饰）等人先后出面袭击李与卡特，不久李被美国方面禁止参与此案，而香港警局也遭到了炸弹袭击。失散的李和卡特分别来到了邓力奇的游艇，得知三合会出现了内讧，话音刚落，胡莉将邓力奇射杀在海中……暂时失去线索的二人奔赴洛杉矶，在当地大亨荣士勋家中发现了胡莉的踪迹和美国的卧底特工，原来邓、胡等人卷入了一场巨额假钞案，李与卡特决定拿回胡莉手中的印版……','Get ready for a second Rush!',90000000,347325802,35.814765,6.4,1054,90,'2001-08-03','en','/uHeeDMKrOlEAsgOwSR22kMDMfNe.jpg',3.4781994278916986,3,'2026-09-10',2,NULL,NULL),(5176,'决战犹马镇','3:10 to Yuma','丹•埃文斯（克里斯汀·贝尔 饰）在南北战争断了一条腿，得到政府小小的补偿，他和妻子艾丽丝还有两个儿子在亚利桑那的农场居住。然而，恶劣的气候和腐败之风却让丹负债累累，一些人想在建造铁路上获得暴利，他们想尽办法赶走埃文斯一家，家人开始质疑丹的能力。就在此时，西部声名狼藉罪犯 宾•维德（罗素·克劳 饰）被捕获。他曾带领着副手查理•普林斯（本·福斯特 饰）和一帮手下驰骋荒野，劫得大量财物并犯下无数命案。被逮捕的宾•维德将由押送队带到康坦森镇，搭上火车他会被送到亚利桑那州的犹马镇，在那里接受联邦法庭的公开审判。为了拯救农场和家人，丹自愿参加了押送队，但即使被束缚，宾·维德仍然是危险的。在旅程中，押送队不断折损。当火车到来之时，一切会发生什么改变？','Time waits for one man.',55000000,70016220,48.801089,6.9,1188,122,'2007-09-06','en','/4RRdCnrOiVtxd5pfKSjpe9BOaOl.jpg',3.629276495240356,3,'2026-09-10',2,NULL,NULL),(5178,'一片好心','The Good Heart','由于心脏病发作，贾克斯（布莱恩·考克斯 Brian Cox 饰）又一次的住进了医院，躺在病床上的他明白自己时日无多，可他经营的酒吧却后继无人。在医院里，贾克斯结识了神情萎靡颓废而又沮丧的年轻人卢卡斯（保罗·达诺 Paul Dano 饰），他来到这里的原因是自杀未遂。卢卡斯的境遇让贾克斯很是感慨，在一股不知所以然的冲动下，卢卡斯成为了贾克斯心目中的继承人选。','Everyone needs a refuge from the world.',3800000,0,2.201678,6,21,95,'2009-09-11','en','/cSoUB8SFcVNaCFs1b3dTN3niYck.jpg',2.5090761657881515,3,'2026-09-10',2,NULL,NULL),(5236,'小贼、美女和妙探','Kiss Kiss Bang Bang','在哈里（小罗伯特·唐尼 Robert Downey Jr.饰）的旁白中，这个带着黑色幽默的故事开始了。他本来是一个衰运连连的惯偷，因为一次躲避警察追捕的缘故，闯入了好莱坞电影的选秀片场。可谓歪打正着，导演竟然一下子就看上了哈里，让他前往洛杉矶接受角色培训。\r 　　哈里就这样莫名其妙地成为了“准演员”，他将会出演一名神探。剧组专门安排哈里到真正的侦探佩里（瓦尔·基尔默 Val Kilmer饰）身边，体验真实的侦探生活。一桩命案等待着他们的调查，而死者是一名女士。这种惊险的生活真让哈里受尽了苦头，因为冷酷的佩里可不是一个容易应付的搭档。\r 　　而同时，哈里在派对上重遇了年少时的梦中情人哈莫妮（米歇尔·莫娜汉 Michelle Monaghan饰）。她已经在好莱坞摸爬滚打一番，仍然名声未扬，如今她的妹妹更是神秘自杀。为了赢得美人心，哈里开始调查这件事情，这时才慢慢发现，这和他们之前接手的命案竟然相关，而且背后还隐藏着一个不为人知的巨大秘密。','SeX. MurdEr. MyStery. Welcome to the party.',15000000,15785148,32.690038,7.2,886,103,'2005-09-05','en','/oAONG8TjXpVAv94iuvHVI7pF1tX.jpg',3.561443024862415,3,'2026-09-10',2,NULL,NULL),(5255,'极地特快','The Polar Express','信则灵。小男孩始终坚信圣诞老人的存在，但周围的大人和玩伴都认为这只是他天真的一厢情愿。圣诞前夕，小男孩终于因为他的坚持而得到了回报，睡梦中的他忽然感到屋子颤抖起来了，一列长长的火车停在了他的家门口。当他战战兢兢打开房门时，和蔼的列车长邀请他参加北极的圣诞派对。惴惴不安的克 劳斯踏上了火车，发现很多和他一样的小伙伴们。于是，兴奋不已的小男孩开始了他的北极狂欢之旅。','This holiday season... believe.',165000000,305875730,47.323228,6.4,1474,100,'2004-11-10','en','/8lH49KeBWjrgqasmNvTBlCqkEUD.jpg',3.583976018026874,3,'2026-09-10',2,NULL,NULL),(5279,'高斯福庄园','Gosford Park','这部背景设定于1930年代英国的群像谋杀悬疑讽刺剧，围绕一场在乡村庄园举办的优雅狩猎周末聚会展开，描绘了一个贵族家庭及其友人们的众生相。','Tea at four. Dinner at eight. Murder at midnight.',19800000,87754044,11.693272,6.8,246,137,'2001-11-07','en','/4Rt9KVMDaDYCTIbMSsi368mYgU4.jpg',3.108901302057639,3,'2026-09-10',2,NULL,NULL),(5353,'狩猎聚会','The Hunting Party','摄影师达克（泰伦斯·霍华德 Terrence Dashon Howard 饰）和记者西蒙（理查·基尔 Richard Gere 饰）是一对出生入死的好搭档，每日，他们穿梭在枪林弹雨之中，在最危险的前线为全世界人们带来战地的消息。凭借着真实可靠的报道，达克和西蒙获得了新闻 界人人梦寐以求的艾美奖，就此，他们的事业到达了巅峰。\r 一次意外中，报道现场发生了事故，西蒙失踪了，之后，达克获得了晋升，而西蒙始终杳无音信。时间流逝，五年后，当达克和新的搭档本杰明（杰西·艾森伯格 Jesse Eisenberg 饰）重新回到萨拉热窝后，西蒙意外的出现在了他们的面前。西蒙的出现带出了一个重量级的爆炸性新闻，为了证实这条新闻，达克、本杰明和西蒙三人决定深入虎穴。','How can they find the world\'s most wanted war criminal when the C.I.A. can\'t? [by actually looking]',0,0,8.048305,6.6,96,101,'2007-09-03','en','/4pro3nAEbFSCcM5PoraVaCJPGNu.jpg',2.8625783339381696,3,'2026-09-10',2,NULL,NULL),(5393,'邪恶新世界','Happily N\'Ever After','邪恶新世界','Fairy Tale Endings Aren\'t What They Used To Be',47000000,38085778,10.410933,4.6,104,75,'2006-09-14','en','/geXsapJfihg78gVDvEVPoK5c07y.jpg',2.8114641827690603,3,'2026-09-10',2,NULL,NULL),(5491,'地球战场','Battlefield Earth','公元3000年，人类不再是地球的统治者，地球在数百年前惨遭残暴的外星人征服，90%的人类被消灭，残存的成为外星人奴隶，过着如原始人般的生活，人类的历史与文明逐渐被遗忘。如今人类受控于着12尺高、爪如利刃、个性刁猾的外星人。就在人类濒临灭亡边缘的危急时刻，一个名叫强尼（贝瑞·佩珀饰）的青年从原来的藏身之地勇敢地走了出来，并到处寻找其他幸存人群，希望有一天能够推翻外星人的统治','Take Back The Planet',44000000,21400000,7.89147,3,255,118,'2000-05-10','en','/wXCRuBHdJ5aTFQdsuGJFXNdo79T.jpg',2.8138015861142027,3,'2026-09-10',2,NULL,NULL),(5494,'乔治和龙','George and the Dragon','乔治是个小伙子，其实并没有什么辉煌的梦想。他的全部希望就是能得到几亩地和几头牛过上平静的日子。他的父亲老乔治却念念不忘自己的梦想杀死一头龙。实际上老乔治曾经离自己的梦想如此之近，以至于有一条龙的身上现在还留着老乔治的长矛。不过那条龙也咬掉了老乔治的双腿做为报复。带着父亲的嘱托，小乔治向邻国英格兰出发，去找寻自己的梦想。不料，英格兰正在举国大乱，原因是国王的宝贝女儿不见了，为了追求赏金或者权力，各种各样的势力都在极力寻找公证。小乔治的到来究竟会给英格兰带来什么？他能实现老乔治的梦想吗？',NULL,32000000,0,4.120549,5,13,93,'2004-03-28','en','/50NxkQexHBoQypzfADEdlxxOlWA.jpg',2.410406115735254,3,'2026-09-10',2,NULL,NULL),(5503,'亡命天涯','The Fugitive','本片改编自1960年代热门电视剧，讲述了理查德·金波医生（哈里森·福特 饰）被诬告谋杀妻子并定罪的故事。','A murdered wife. A one-armed man. An obsessed detective. The chase begins.',44000000,368875760,54.884297,7.2,1220,130,'1993-08-06','en','/b3rEtLKyOnF89mcK75GXDXdmOEf.jpg',3.7067662905676544,3,'2026-09-10',2,NULL,NULL),(5516,'The Ladykillers','The Ladykillers','An eccentric, if not charming Southern professor and his crew pose as a band in order to rob a casino, all under the nose of his unsuspecting landlord – a sharp old woman.','The greatest criminal minds of all time have finally met their match.',0,0,23.666229,6,415,104,'2004-03-25','en','/l4g9R39NCp6VaYFrw6q8JwKNW9x.jpg',3.185126296020748,3,'2026-09-10',2,NULL,NULL),(5528,'放牛班的春天','Les Choristes','1949年的法国乡村，音乐家克莱门特·马修来到一所名为“池塘之底”的男子寄宿学校担任助理教师。这里的学生大多顽皮难管，体罚和高压管教更是司空见惯。性格温和的马修不认同校长的教育方式，决定尝试用音乐改变这些孩子。他重新创作合唱曲，组织起一支合唱团，希望用歌声打开学生们封闭的心灵。在这个过程中，马修发现性格敏感孤僻的皮埃尔拥有非同一般的歌唱天赋，也开始尝试引导这个难以接近的少年找到属于自己的声音。随着歌声在校园中响起，这群曾被视为“问题儿童”的孩子，也逐渐发生着意想不到的变化……',NULL,0,0,20.982455,7.5,526,96,'2004-03-17','fr','/d623rdQLxw7QhdP7ECsz1UkJrHl.jpg',3.417141549295489,3,'2026-09-10',2,NULL,NULL),(5550,'机器战警3','RoboCop 3','泛消费公司已完全掌控了底特律市之后，与日本金光财团合作组建OCP，在底特律开发三角洲城，并招揽雇佣兵组成暴力改建队，驱逐居民，相当数量的拆迁地居民为捍卫家园组成武装力量反抗财阀的不义计划，女童妮科（Remy Ryan Hernandez 饰）凭借高超的电脑技术在反抗军中表现抢眼。机器战警墨菲（Robert John Burke 饰）与老搭档路易斯执行任务期间偶然发现了居民们的藏身地点，出于正义感，墨菲同随后赶到的改建队交火，机体损坏严重，路易斯不幸身亡，墨菲决定加入反抗军。同时日本方面为执行拆迁计划派出特工忍者雄志，改建队头目亦利用反抗军中的叛徒查到了反抗总部。在妮科的帮助下，墨菲被拉瑟斯博士整修完备，汇同不齿改建队暴力行径而选择站到居民一边的底特律警察们，同雄志、改建队展开最后决战。','He\'s back to lay down the law.',22000000,10696210,14.725467,4.2,305,104,'1993-04-17','en','/lm7h0G1rG5OOBLJY4RkjAZJkg86.jpg',2.9409365172160036,3,'2026-09-10',2,NULL,NULL),(5551,'Space Cowboys','Space Cowboys','Frank Corvin, ‘Hawk’ Hawkins, Jerry O\'Neill and ‘Tank’ Sullivan were hotdog members of Project Daedalus, the Air Force\'s test program for space travel, but their hopes were dashed in 1958 with the formation of NASA and the use of trained chimps. They blackmail their way into orbit when Russia\'s mysterious ‘Ikon’ communications satellite\'s orbit begins to degrade and threatens to crash to Earth.','Space will never be the same.',65000000,128884132,15.772081,6.3,403,130,'2000-07-31','en','/8wSCduD0la1VgeztbNKppfQb7XZ.jpg',3.1930235487350735,3,'2026-09-10',2,NULL,NULL),(5559,'蜜蜂总动员','Bee Movie','怎么说呢？任何族群里都会出现那么一两个异类，即便是整日劳作的小蜜蜂，也有走出蜂箱看世界的时候。相信你在看过了这部极具颠覆意义的影片之后，将会改变自己最初对蜜蜂的那些约定俗成的观念……巴瑞·B·拜森与他的蜜蜂伙伴们有那么一点不一样，虽然同样很勤劳，但他的想象力就有些出格了。从蜜蜂学校正式毕业之后，巴瑞不想从事那份早在他出生的时候就安排好的工作--像其他小蜜蜂那样整日忙进忙出，以一只工蜂的身份制造蜂蜜。  　　别说，还真被巴瑞等到了一个合适的时机，让他走出了蜂箱，离开了蜜蜂所组成的那个独特的群体社会……展现在他面前的，是一个从未接触过、却更为广阔的世界，他很快就发现，这次旅行将会成为一个比他的任何想象都要狂野的历险。  　　在一个非常偶然的情况下，巴瑞遇到了一名古怪离奇的同时也很勇敢的种花姑娘温妮沙，巴瑞甚至还为她打破了蜜蜂界最大的禁忌--开口和她说话。好在天真浪漫的温妮沙并没有觉得，一只蜜蜂竟然能够说人类的语言是多么地惊世骇俗，反而和巴瑞成为了无话不谈的好朋友。虽然巴瑞的新生活经历了各式各样的定向碰撞，但在温妮沙帮忙下，大多有惊无险。然而，巴瑞随后发现的一个事实，却让他感到了前所未有的震惊和愤怒：人类竟然偷走了蜜蜂的劳动果实，并用其牟利。巴瑞悲哀地看着，自己同伴辛勤采集的蜂蜜，竟然被随意地摆放在了超市的货架上，任何人只要出钱就可以随意拿回家进行品尝。巴瑞终于意识到，上天给了他一个离开蜂箱的机会，可能就是希望他完成这个使命，他要以“偷窃罪”和“奴役罪”控告人类，还世界一个公正，因为在巴瑞的眼中，世界万物，都应该拥有平等的生存权利。','Born to bee wild.',150000000,287594577,29.332905,5.7,1171,91,'2007-10-28','en','/cxWo5B4tBGraBdDq2kGn1xYtHon.jpg',3.358936401435994,3,'2026-09-10',2,NULL,NULL),(5689,'青春珊瑚岛','The Blue Lagoon','一次意外中，艾米丽（波姬·小丝 Brooke Shields 饰）和理查德（克里斯托弗斯·阿特金斯 Christopher Atkins 饰）流落到了一座孤岛上，面对凶险的大自然，他们必须为自己开拓一片赖以生存的环境。好在岛上的物资十分的丰饶，两人的生活上不成问题，只是在偌大的天地间，茕茕独立的孤独只有两人自己清楚。\r 　　获救之日遥遥无期，艾米丽和理查德却早已习惯了岛上闲散安逸的生活。孤男寡女，奇妙的感情慢慢的拉近了两人的距离，不久之后，艾米丽生下了一名男婴，为两人的生活又增加了一份快乐。救援队的不期而至打破了这世外桃源般的生活，在和救援人员进行了交流后，两人发现，他们早已不适合再生活在文明社会之中，两人决定留在此地，永远的生活在他们的伊甸园之中。','A sensuous story of natural love.',4500000,58853106,22.585384,5.8,408,104,'1980-07-05','en','/hg57Zr63A96mpIQKHxOjHYqCVhI.jpg',3.1575638506539314,3,'2026-09-10',2,NULL,NULL),(5708,'控制','Control','18岁的叛逆男孩伊恩（萨姆•赖利 Sam Riley 饰）最喜欢做的事就是把自己关在房间里听着摇滚乐，对着镜子为自己画眼线。在他的眼中，家乡小镇死气沉沉，毫无出路，而喊出人生真谛的摇滚乐才会使得人的青春有着那么点儿乐趣。这日，伊恩前往伦敦观看著名摇滚乐队性枪手的演出。伊恩似乎天生就是为了摇滚活着，他在演出会现场结识了性枪手的三位成员，当时正在寻找主唱的他们认定了伊恩就是最佳人选。于是，男孩伊恩开始了他的摇滚之路。',NULL,0,8159508,11.357474,7.5,200,121,'2007-09-26','en','/jOJiaOhwrDdwqTRZvZOhbndqHGp.jpg',3.100983610021489,3,'2026-09-10',2,NULL,NULL),(5722,'飞越美人谷','Beyond the Valley of the Dolls','三个青春无敌少女，组成了一个女子乐队，她们一心成为明日之星。然而除了付出努力，她们还牵涉毒品、酒精、性爱、甚至同性恋……','This Is Not A Sequel. There Has Never Been Anything Like It!',2090000,40000000,4.289003,6.6,53,109,'1970-07-17','en','/eslylQSssnNIV4f06fHtfxPTH3I.jpg',2.719693305376,3,'2026-09-10',2,NULL,NULL),(5723,'曾经','Once','一部发生在都柏林街头的现代音乐剧。影片由爱尔兰乐队\"The Frames\"成员格伦·汉塞德主演，讲述街头音乐人与捷克移民在短暂而深刻的一周里，通过创作、排练并录制歌曲，谱写出一段独特恋曲的故事。[福克斯探照灯影业]','How often do you find the right person?',160000,20710513,19.052179,7.3,453,85,'2007-03-23','en','/gaGkihU9gSxTnloXJhF4llMPYJ9.jpg',3.342415009152104,3,'2026-09-10',2,NULL,NULL),(5759,'纸袋头','Baghead','杜普拉斯兄弟在拍摄电影《帕妃椅》期间，一群摄制组成员无聊时提出一个问题：你能想到的让你惊慌的事情是什么？有人立刻回答：一个头上戴着袋子的人盯着你的窗口。对于这一说法，有的人同意，但有的人不以为然，认为这很荒谬，或者很滑稽，但一点都不会引起惊慌。于是，《纸袋头》随之诞生，试图抓住那种“头上戴袋子”的荒谬感觉，制作出一部滑稽、真实、可爱的电影，当然也许——仅仅也许，有一点点的恐惧。',NULL,0,0,3.299345,5.8,23,84,'2008-01-21','en','/pO3Au8iDpZsJt7Xco6fRsNvm3vz.jpg',2.528553840827202,3,'2026-09-10',2,NULL,NULL),(5769,'汤姆·琼斯','Tom Jones','汤姆琼斯（阿尔伯特·芬尼 Albert Finney 饰）本为私生子，后被一绅士收养，他天性热情奔放，模样又生得风流俊朗，庄园主的女儿索菲亚（苏珊娜·约克 Susannah York 饰）同他坠入情网，后遭到表弟比菲尔（大卫·沃纳 David Warner 饰）的插足干涉，一番纠葛之后，声名狼藉的汤姆琼斯决定离开家乡，去外面的世界寻找属于自己的天地。\r 汤姆离开后没多久，伤心的索菲亚便也踏上了旅途，两人在缘分的驱使之下在一名女商贩的家中重逢了。之后，比菲尔亦来到了伦敦，想要报复汤姆。在比菲尔的阴谋筹划之下，汤姆被送上了绞刑架，就在即将行刑的生死攸关的时刻，索菲亚的父亲及时赶到，破解了比菲尔的阴谋，挽救了汤姆的性命。','Tom Jones! . . . loves and loves and loves and loves . . .',1000000,37600000,2.833166,6.1,39,128,'1963-10-06','en','/yKuZKLMhe74PJzaxYLh2s8h4P2P.jpg',2.6410916728264358,3,'2026-09-10',2,NULL,NULL),(5780,'冲破铁幕','Torn Curtain','美国青年阿姆斯特朗为了搞到一个属于尖端机密的科学公式，假装叛逃到东柏林，不惜干掉他的贴身保镖。经过一番激烈追逐，阿姆斯特朗终于搞到了秘密公式，最后携萨拉飞往瑞典……','It tears you apart with suspense!',3000000,13000000,7.924982,6.4,120,128,'1966-07-13','en','/7XC1l9eP2TBYMEdA4KRUqKAFmbm.jpg',2.9054717058051676,3,'2026-09-10',2,NULL,NULL),(5820,'一级戒备','The Sentinel','彼得·格瑞森(迈克尔·道格拉斯 饰)是美国白宫的一名特工，心思缜密、动作敏捷的他是众多特工中出类拔萃的一员。一天，格瑞森的特工同伴被残忍杀害了，格瑞森经过深入调查后，发现新纳粹分子已经将一名卧底安插进了白宫，而同伴的死与他们息息相关。格瑞森果断地认为总统的安全正受到一些在暗处的邪恶力量的威胁。但就在他准备深入调查时，却受到了一个神秘人物的恐吓，此人不但对他与第一夫人萨拉·巴伦坦(金·贝辛格 饰)的秘密偷情知道的一清二楚，还将谋杀案的罪名嫁祸于他。','In 141 years, there\'s never been a traitor in the Secret Service.... Until Now.',60000000,77920346,15.352807,5.8,225,108,'2006-04-19','en','/eVCnd3opHS7SP6aOQODlUl7nJp6.jpg',3.0237737355538425,3,'2026-09-10',2,NULL,NULL),(5822,'斯维特拜克之歌','Sweet Sweetback\'s Baadasssss Song','在从一些种族主义警察手中救下一只黑豹后，一名黑人男妓在贫民区社区和一些幻灭的地狱天使的帮助下逃离了“那个男人”。','The Film that THE MAN doesn\'t want you to see!',150000,15200000,0.132878,4.6,18,97,'1971-04-23','en','/ykGkbDp1QxQTM3UUrUvowtXLI0i.jpg',2.462519845540511,3,'2026-09-10',2,NULL,NULL),(5852,'天使之眼','Angel Eyes','莎朗是芝加哥警察局一名极为出色的女警官，她自信好强，坚韧而从不轻易言败。能干的她被派往芝加哥罪犯密集的南部地区。在那里，她将致力于抓捕毒贩和对抗全副武装的歹徒。莎朗在工作上独当一面，但外表的坚强，却仍难掩内心的失落。整日忙于与罪恶打交道，让她疲惫不堪；她与家人的关系并不融洽，早已不再来往。同时，幼年时的一段的痛苦经历也时时困扰着她，一直不能开解，直到遇上了一个叫凯奇的神秘男子。  　　凯奇是莎朗的邻居，住在隔壁的一间小公寓里。他与邻居相处和睦，经常派发一些小礼物给周围的人；如果谁的车窗在雨天打开着，他也会帮忙摇上；凯奇还每周两次给一个残疾老人送去生活用品。但就是这样一个大好人，却日夜受到精神上的折磨。凯奇曾亲眼目睹了自己的妻子女儿在一场车祸中丧生，巨大的悲痛使得他失去了记忆。  　　两个失心人相遇，为了使凯奇恢复记忆，莎朗开始与凯奇一起寻找线索……','The deeper you look, the more you will find.',53000000,29700000,6.454634,5.6,88,102,'2001-05-15','en','/6ZeMoynnz4pRweKKZ9c2G1absMJ.jpg',2.80664541034302,3,'2026-09-10',2,NULL,NULL),(5854,'大巧局','Family Plot','女富翁兰白黛年事已高，可膝下无人，偌大的家产谁来继承？为此她很苦恼，特地请来女巫师布朗什乞灵。布朗什胡诌了一通后，兰白黛道出真情。原来，在四十年前，她的妹妹私通生子，因违反家规，兰白黛把婴儿送到一个隐蔽地方藏了起来。现在她愿出一万美元，请布朗什帮助找到那个已长大成人的外甥。布朗什和她的情夫、汽车司机拉姆莱一起开始调查了……','There’s no body in the family plot.',2000000,7900000,3.832858,6.7,86,121,'1976-04-09','en','/oQ9QbyBuIM2uYaheSKjs2x1xIQV.jpg',2.830904761101738,3,'2026-09-10',2,NULL,NULL),(5876,'迷雾','The Mist','一座风景秀美的小镇被一场突如其来的浓雾瞬间淹没。雾中传来阵阵惨叫，人们惊慌失措地四处逃散。戴维和他的儿子与众多镇上的人被困在小镇超市里，等待雾的消散。浓雾并没有如期望的散开，而走进浓雾的人一去不返。浓雾逐渐露出了它狰狞的面目。恐惧、惊慌、挣扎、悲伤、绝望……人们的精神濒临崩溃。如何才能活着走出迷雾？面对超市里几近癫狂的人们和超市外吞噬一切、不可知的迷雾，戴维紧紧搂着儿子，开始了艰难的求生之路……','Belief divides them, mystery surrounds them, but fear changes everything.',18000000,57096190,37.104353,6.7,1399,126,'2007-11-21','en','/h7bb3HpX45o1Cre9XLmRArEPXMb.jpg',3.607480898094037,3,'2026-09-10',2,NULL,NULL),(5900,'夺命裙','De jurk','获奖：1996年威尼斯电影节影评人大奖',NULL,0,0,0.144031,7,3,103,'1996-03-21','nl','/jmAQ4eXd5GCvYFrmoI0fKLr1zuD.jpg',2.136233281621442,3,'2026-09-10',2,NULL,NULL),(5902,'遥远的桥','A Bridge Too Far','欧战尾声，盟军上下逐渐弥漫着乐观的情绪。为了提前结束战争，各地盟军将领认为只要一番猛攻，便可提早直捣柏林结束战争。于是轻率地将大批伞兵空投在德军营地背后，去攻占阿纳姆的那座横跨莱茵河的大桥。不料遭遇德军的顽强抵抗，盟军付出了伤亡惨重的代价。这场堪称二战中最具戏剧性的战役，终以盟军的惨痛失败而告终。\r 由奥斯卡金像奖得奖导演理查德·阿滕伯勒执导的战争巨片《遥远的桥》，根据科尼利厄斯·瑞恩的同名小说改编而成。影片表现和讴歌了盟军在二战中浴血奋战的斗争精神，被誉为电影史上的超级战争巨片。本片的明星阵容空前强大，聚集了诸如詹姆斯·卡恩、迈克尔·凯恩、肖恩·康纳利、罗伯特·雷德福、安东尼·霍普金斯等数国的数十位明星。本片荣获1978年第31届英国电影和电视艺术学院奖最佳摄影、最佳男配角、最佳原声等多项大奖与提名。','Out of the sky comes the screen\'s most incredible spectacle of men and war!',22000000,50750000,20.256571,6.9,207,175,'1977-06-15','en','/b1DVFV9JDcsg2XsSNSlaF3tq5QL.jpg',3.0913562925214357,3,'2026-09-10',2,NULL,NULL),(5915,'荒野生存','Into the Wild','影片改编自真实的故事，展现了一个理想主义者的传奇，一个流浪的故事。克里斯托弗（埃米尔•赫斯基 饰）家境优渥，是亚特兰大私立名校艾莫里的优等生，前程似锦。但是，他从学校毕业后，选择了截然不同的人生，放弃令人羡慕的工作，把存款捐给慈善机构，去阿拉斯加寻找自我。在家人的劝阻声中，他踏上了回归自然的慢慢长路，成为名副其实的流浪者。一路上，他遇到不少人，也数次遭受野外生存的挑战，每一步都充满了艰辛，他以坚韧的毅力，实践着寻找自我的梦想……','Into the heart. Into the soul.',15000000,56255142,43.644978,7.8,3045,148,'2007-09-11','en','/jnLnLYP5pGDfri04gxtAqAvkHMw.jpg',4.083837429828258,3,'2026-09-10',2,NULL,NULL),(5925,'大逃亡','The Great Escape','这部史上最激动人心的冒险故事之一，以动作史诗的规格再现了二战期间一次真实的越狱行动——250名战俘试图通过地道从德国战俘营挣脱枷锁，影片详实刻画了行动的筹划、执行与后续波澜。史蒂夫·麦奎因凭借片中摩托车特技狂人的角色奠定其巨星地位，他与查尔斯·勃朗宁、詹姆斯·柯本、詹姆斯·加纳、唐纳德·普利森斯等全明星阵容携手对抗纳粹。约翰·斯特奇斯的精湛执导、埃尔默·伯恩斯坦朗朗上口的配乐，以及惊心动魄的特技场面，共同铸就这部影史最具观赏性的越狱电影，成为一曲献给平凡英雄之决心、情谊与勇气的激昂颂歌。[标准收藏]','Put a fence in front of these men... and they\'ll climb it!',4000000,11744471,35.061467,7.8,717,172,'1963-06-20','en','/gBH4H8UMFxl139HaLz6lRuvsel8.jpg',3.593039135560818,3,'2026-09-10',2,NULL,NULL),(5955,'The Pledge','The Pledge','A police chief about to retire pledges to help a woman find her daughter\'s killer. Based on a story by Swiss writer Friedrich Dürrenmatt.',NULL,35000000,29400000,12.495436,6.5,215,123,'2001-01-09','en','/9QOzFL3FPMAUNNPrNiKC3mEDxco.jpg',3.0560363312404393,3,'2026-09-10',2,NULL,NULL),(5966,'遇见波莉','Along Came Polly','鲁本（本·斯蒂勒 Ben Stiller饰）的职业名称简直在讽刺他的性格——风险分析师。因为，鲁本是一个平凡甚至有点窝囊的人，不敢冒一丁点生活的险，可以说，他就像一辆僵直的列车，规规矩矩沿着铁轨开往人生终点。 这样的人，生活还是要给他一点打击。本来可以和新娶的老婆平平静静过两口子生活，不料蜜月期就遭到婚变，可怜的鲁本亲眼看到老婆和一个法国肌肉男缠绵悱恻。懦弱的他，默默的回到自己原本一个人的生活，过去的阴影令这个男人更加灰心。波莉（詹妮弗·安妮斯顿 Jennifer Aniston饰）的出现，在他糟糕的人生里投下了一缕明快的阳光。 波莉带着他尝试着这个世上种种的精彩之事，这些疯狂的举动，鲁本过去连想像的勇气的没有。如今，他像一个刚刚见识到世界如何缤纷多彩的孩子，在波莉的带领下重新发现了生活的乐趣，二人的爱意也在迅速萌芽。','For the most cautious man on Earth, life is about to get interesting.',42000000,171963386,33.238296,5.8,773,90,'2004-01-16','en','/aKDO4uCnFe6ImefBihs1wwHjeci.jpg',3.305792527291654,3,'2026-09-10',2,NULL,NULL),(5971,'我们不是天使','We\'re No Angels','奈德（罗伯特·德尼罗 Robert De Niro 饰）和吉姆（西恩·潘 Sean Penn 饰）是两名逃犯，在逃亡的路途中，他们来到了一个地处偏远的小镇。阴差阳错之下，奈德和吉姆成为了牧师，而很快他们便发现，在这个小镇上，牧师享有着极高的地位和声誉。\r 　　就这样，奈德和吉姆这两个毫无信仰，对神学一无所知的混混们开始了他们的牧师生活，在这里，奈德结识了名叫莫利（黛咪·摩尔 Demi Moore 饰）的姑娘，莫利的悲惨身世让奈德很受触动，随着时间的推移，两人之间产生了真挚的感情，而吉姆亦在小镇中重新体会到了友情的美妙滋味。不幸的是，正当奈德和吉姆沉浸在小镇平静的生活中之时，一直追捕两人的监狱长来到了小镇。','Escaped convicts disguised as priests. It\'ll take a miracle to get away with this one.',20000000,0,9.927018,5.6,105,106,'1989-12-15','en','/5XBVURkON7jyzxr0cONWeTbgAov.jpg',2.849736256172302,3,'2026-09-10',2,NULL,NULL),(5994,'居家男人','The Family Man','1987年，踌躇满志的杰克·坎贝尔告别女友凯特，只身前往纽约打拼。13年后，杰克已然成为华尔街炙手可热的投资经纪人，他的事业一帆风顺，生活奢侈优渥，身边美女如云，俨然一个完美无瑕的成功人士。然而，就在圣诞夜节的前两天，杰克的人生发生翻天覆地的变化。当他一觉醒来时，发现自己身在新泽西老家，凯特成为他的妻子，两人更育有两个可爱的孩子。全新而对立的人生让杰克无所适从，而他终将在金钱和亲情间做出抉择。','What if you made different choices? What if you said yes, instead of no? What if you got a second chance?',60000000,0,19.705489,6.5,521,125,'2000-12-12','en','/A59qi4fXmhba3Qbrlljr6a3NwAm.jpg',3.2860904370591837,3,'2026-09-10',2,NULL,NULL),(6007,'他傻瓜谁聪明','Elling','When his mother, who has sheltered him his entire 40 years, dies, Elling, a sensitive, would-be poet, is sent to live in a state institution. There he meets Kjell Bjarne, a gentle giant and female-obsessed virgin in his 40s. After two years, the men are released and provided with a state-funded apartment and stipend with the hope they will be able to live on their own.',NULL,0,0,2.526356,7,51,89,'2001-03-16','en','/o6s7QPk7nOoXXZUcUDfbL2iy4pL.jpg',2.7149740087647074,3,'2026-09-10',2,NULL,NULL),(6016,'宝刀未老','The Good Thief','一个上了年纪的赌徒连败，企图抢劫蒙特卡洛的一家赌场。但有人在他采取行动之前就已经向警察通风报信了。','He doesn\'t want money. He wants what money can\'t buy.',0,0,2.774811,6,31,108,'2003-04-03','en','/TMlSiPuj9LymfwPiKFiRRnhkRq.jpg',2.5913165895581076,3,'2026-09-10',2,NULL,NULL),(6020,'Sorority Boys','Sorority Boys','Three friends who head the Social Committee in a frat house, called KOK (Kappa Omicron Kappa), are charged with stealing money their fraternity has been saving for a cocktail cruise at the end of the semester, the one that guarantees them a spot at a very high paying company.',NULL,12000000,0,3.444542,4.6,47,93,'2002-03-22','en','/yBhRjKi16T9R3GJepPwS6ARViBi.jpg',2.6547665837242183,3,'2026-09-10',2,NULL,NULL),(6023,'附注：我爱你','P.S. I Love You','霍莉（希拉里•斯万克 饰）与盖里（杰拉德•巴特勒 饰）深爱彼此，虽然有时候他们会有争吵，可是这些都是他们生活中的情趣。霍莉感觉自己已经找到了最爱，盖里却在他们婚后罹患脑癌并逝世了。自此，霍莉便生活在失去挚爱的痛苦中。她感觉丈夫并没有就此离开，她还能在家中感受到盖里的气息。她把自己困在家中，两位好友丹尼丝（莉莎•库卓 饰）、莎拉及霍莉的母亲还有母亲酒吧里的酒保丹尼尔都十分担心她。就在她三十岁生日的那天开始，她便不断收到由盖里给她寄来的信，每封信的最后都加上一句“我爱你”的附注。盖里的信为霍莉的生活注入了力量，她一步步的向前走，但事实上盖里已经死去了，她终究要自己独自生活。丹尼丝怀孕了，莎拉即将要结婚，她们两个都生活在幸福当中，霍莉突感落寞。她又开始躲避众人，自认识霍莉后丹尼尔一直都陪在霍莉身边，丹尼尔向霍莉表达自己的爱意。霍莉第一次跑到母亲怀里痛哭，她也知道了盖里的信原来一直由母亲代寄。最后一封信就要拆开，霍莉会否得到重生呢？','His life ended. Now, a new one will begin.',30000000,156835339,29.489274,6.9,977,126,'2007-11-15','en','/659xVXSCWbbgpXB1df2fPf7HW9Z.jpg',3.531634501353913,3,'2026-09-10',2,NULL,NULL),(6038,'上海正午2：上海骑士','Shanghai Knights','1887年，在西部某镇担任治安官的强（成龙 饰）忽然收到一封家信，惊闻看护玉玺的父亲被人杀死，玉玺失踪，妹妹铃（范文芳 饰）追踪犯人一路到了英国。于是强匆忙奔赴纽约，寻找老友罗伊（欧文•威尔逊 饰），强本想用上次得来的皇家黄金帮助自己，岂料风流兼吹牛成性的罗伊早将黄金豪赌一空，如今落魄成了一个偶尔卖身的侍应。强虽无奈，还是带着罗伊一起到了英国。先期抵达英国的铃跟踪仇人雷斯本多日，在后者身上，隐藏着一宗涉及清、英两国的重大阴谋。原来私生子出身的皇帝之弟吴超（甄子丹 饰），为了夺取皇位同雷斯本联手，抢夺玉玺计划发动兵变。匆忙赶到的强，为了复仇和家族荣誉，决定不惜一切阻止吴超。','A Royal Kick In The Arse.',50000000,88323487,16.251204,6,692,115,'2003-02-06','en','/83Gg4vgc5nI5RF3DctJDyXMHtEY.jpg',3.2748119734052072,3,'2026-09-10',2,NULL,NULL),(6068,'六天七夜','Six Days Seven Nights','奎因是一个粗鲁乏味的货机驾驶员，洛宾是一个唠叨的职场女强人，二人有着自己各自的生活。但是，所谓千里姻缘一线牵，自从洛宾和未婚夫一起前来夏威夷度假，她和奎因之间的故事便开始了。洛宾在度假第二天便接到工作任务，需要尽快赶往大溪地拍摄明星广告。洛宾央求奎因用货机载她一程，不料飞行路上货机不幸遇上暴风雨，奎因只好紧急迫降在一个荒凉的小岛上。在这里，奎因和洛宾将面临着严峻的生存问题：如何寻找食物，如何寻找活路，以及如何逃过岛上凶险的海盗。奎因虽是个粗人，此时却强有力地保护着洛宾，二人情不自禁地互生情愫，然而身为他人未婚妻的洛宾，心中却有万分挣扎。这段感情，是否只能存活在这个现实世界之外的小岛…','After this week in paradise, they’re going to need a vacation.',70000000,164000000,18.264635,5.6,332,98,'1998-06-12','en','/fzWrrCzRa16v51TXAUuT6Wendw7.jpg',3.0885782670362043,3,'2026-09-10',2,NULL,NULL),(6071,'致命布局','Kiss of Death','吉米（大卫·卡罗素 David Caruso 饰）曾经在黑道里摸爬滚打，但如今改邪归正，成为了替警方效力的卧底。黑帮大佬利特（尼古拉斯·凯奇 Nicolas Cage 饰）十分赏识有勇有谋的吉米，对他十分重用，甚至想要吸纳他成为帮派内部的核心成员。这对警方来说是一件好事，但对吉米来说就没那么好了，因为利特生性残暴而又多疑，如果被他发现了自己的真实身份，那自己就只有死路一条。\r 　　终于，吉米创造了一个大好机会，使得警方终于找到了能够逮捕利特的证据。可是最终，利特还是因为证据不足而重获自由，这也就意味着，吉米的身份已经曝光，而他已经成为了利特的眼中钉肉中刺。',NULL,40000000,0,6.90894,5.7,81,101,'1995-04-21','en','/2cCxEqeIy6Q8HgVjfT7obOnF5Zi.jpg',2.7940837405272956,3,'2026-09-10',2,NULL,NULL),(6073,'墨西哥人','The Mexican','“墨西哥人”不是人，而是一把古董手枪。附带在它身上有一个传说，故事的悲剧收场，让这把枪沾上了凶险的不祥之兆。每个持有它的人，都会遭来不测。  如今，小混混杰瑞（布拉德·皮特 Brad Pitt饰）面临着抉择：要么接过黑帮大佬的任务，远赴墨西哥把这支枪找回来；要么乖乖地听漂亮女友萨蔓莎（朱莉娅·罗伯茨 Julia Roberts饰）的话，和黑道断绝来往，做回一个光明正大的人。当然，得罪黑帮无异于惹火烧身，杰瑞再三考虑，还是决定把“墨西哥人”寻回，干完这桩事情就金盘洗手。  风尘仆仆的赶到墨西哥后，杰瑞在异乡经历着曲折的寻枪过程。“墨西哥人”的神秘魔咒也渐渐浮现——萨蔓莎遭到了黑帮老大的绑架，以此来威胁杰瑞务必把枪完好带回。杰瑞的前路，面临着凶险的黑帮势力、手枪的古老魔咒，更有爱情的真谛等待他发现。','Love with the safety off.',57000000,147845033,21.021809,5.8,441,123,'2001-03-01','en','/cMviZTYfU1V8HIFRpRrqbHvc0Od.jpg',3.169145505075414,3,'2026-09-10',2,NULL,NULL),(6106,'萨尔瓦多','Salvador','理查德（詹姆斯·伍兹 James Woods 饰）是一位职业摄影师，每日，他穿梭于世界各地，寻找能够为他带来经济效益的摄影题材。在行业里浸淫已久的他明白，那些美好的，善良的事物无法吸引人们的注意，唯有暴力、恐怖和灾难能够为他带来机遇。\r 　　就这样，理查德和朋友们来到了烽火连天的萨尔瓦多，让理查德没有想到的是，展现在他眼前的，竟然完全是一副人间地狱的惨象。纵使是阅历丰富的理查德，也无法忍受这里发生的点点滴滴，心灰意冷的他决定离开。就在这个节骨眼上，一位名叫玛利亚（艾尔皮迪娅·卡里洛 Elpidia Carrillo 饰）的美丽女子出现在了理查德的生命力，在爱情和事业之间，理查德会做出怎样的选择？','Based on a true story.',4500000,0,3.819796,7,71,123,'1986-04-23','en','/c5JgUmzN7syTFy9suwoHF3vhNsN.jpg',2.7948174475262126,3,'2026-09-10',2,NULL,NULL),(6114,'惊情四百年','Bram Stoker\'s Dracula','公元1462年，土耳其人入侵君士坦丁堡，并威胁到整个基督教。罗马尼亚大将军德古拉伯爵(加里•奥德曼 饰)临危受命征讨，不料就在他获胜之时，城内谣言四起， 盛传他已战死沙场。他的妻子伊丽莎白（薇诺娜•赖德 饰）因悲痛欲绝而投河自杀，班师回朝的德古拉看到的只是妻子的尸体。由此他迁怒于上帝，从而化身投入邪恶势力，以吸食鲜血延续生命，成了一个不死的吸血僵尸。四百年后，故事辗转到了1897年的伦敦，年轻律师强•纳生（基努•里维斯 饰）受命到罗马尼亚特兰斯瓦尼亚属地的德古拉家族城堡去办理这位贵族后裔在伦敦的地产手续。为此，他将与未婚妻——美丽的美娜（薇诺娜•赖德 饰）分离。德古拉城堡的主人公正是已化为吸血鬼的德古拉伯爵，他发现美娜与伊丽莎白惊人相象，认为美娜就是莉莎的转世再生。他决定找到美娜，找回那一份遗失了四百年的真爱。他将约拿囚禁在城堡之中，带上成箱子的故乡泥土：这是他力量的源泉，乘船一路呼风唤雨来到伦敦。他的到来复苏了伦敦的黑暗力量。吸血蝙蝠与狼人醒了，伦敦处于一种神秘的恐怖之中。而美娜却总在冥冥之中听到一种心灵的神秘的召唤，在恐惧中又带有一种强烈的向往...','Love never dies.',40000000,215862692,45.022964,7.1,1056,128,'1992-11-13','en','/8gfUgMk78XKpCBjTEVglHycTXC3.jpg',3.6239584738968476,3,'2026-09-10',2,NULL,NULL),(6116,'辣妹合唱团','Spice World','The film follows the Spice Girls and their entourage (mostly fictional characters) - manager Clifford, his assistant Deborah, filmmaker Piers (who is trying to shoot a documentary on \"the real Spice Girls\") and others in their everyday life.','You say you want a revolution?',25000000,100000000,6.889437,4.7,123,93,'1997-12-19','en','/yWK6Wz8kHPlBcWW9BzZm2Dm0cOl.jpg',2.835009275867324,3,'2026-09-10',2,NULL,NULL),(6171,'捕梦网','Dreamcatcher','一个偏僻的小镇上，四个小男孩共同在一个废弃车站救了一个智障男孩，由此各自获得了神秘的能力。此后的25年里，四个人长大成人、各奔东西，但在每年的狩猎季节仍要重聚在缅因州的森林里度假，一起重温童年的快乐。又到了一年聚会的时候，四人到了森林，却被一场暴风雪困住，与此同时降临的还有一些来自外星的古怪生物，四个人逐渐了解到，外星生物想要对人类展开控制，而当地驻军的遏制方案是连同小镇所有人一起毁灭。四人果断参与进这起事件，开始寻找儿时的能力，试图打退外星人，拯救当地平民……','A circle of friendship. A web of mystery. A pattern of fear.',68000000,75715436,26.792794,5.3,567,136,'2003-03-21','en','/fcAqXdJKNfzGcMlHqC7BH5FRHG3.jpg',3.165454875524834,3,'2026-09-10',2,NULL,NULL),(6217,'豹人','Cat People','最近，美丽少女伊瑞娜（娜塔莎·金斯基 Nastassja Kinski 饰）发现了隐藏在自己家族中的秘密，这一发现源于她和哥哥保罗（马尔科姆·麦克道威尔 Malcolm McDowell 饰）之间的不伦之恋，当他们肌肤相亲时，伊瑞娜居然变身成为了一只残暴嗜血的豹子。随着这个秘密的揭开，伊瑞娜被关进了动物园，动物学家奥利弗（约翰·赫德 John Heard 饰）成为了她的负责人。随着时间的推移，奥利弗渐渐发现了伊瑞娜的不平凡之处，并被其深深的吸引了，这让奥利弗的同事爱丽丝（安妮特·奥图 Annette O\'Toole 饰）十分不满。同样感到不满的还有保罗，他告诉伊瑞娜，如果想要恢复人形，唯一的方法就是杀掉奥利弗。面临艰难的选择，伊瑞娜不知该何去何从。','They are something more than lovers who are about to become something less than human.',0,0,5.69872,6,94,118,'1982-04-02','en','/nYcQnkbTD4LDmp11HCReQuUoMKD.jpg',2.831800014979454,3,'2026-09-10',2,NULL,NULL),(6278,'火龙帝国','Reign of Fire','故事发生在2084年的英国伦敦，一次偶然中，十二岁的小奎因（Ben Thornton 饰）发现了一条沉睡的巨龙，巨龙苏醒了，奎因的母亲和许多无辜的人类死在了巨龙的焰火之下。一转眼二十年过去，在此期间，巨龙在地球上安居落户繁衍生息，它们残忍的杀害和驱逐人类，霸占了人类赖以生存的家园。  　　仅存的人类们聚集到了一间古堡里，那里是他们最后的防线，而他们的领头人不是别人，正是已经长大成人的奎因（克里斯蒂安·贝尔 Christian Bale 饰）。一个名叫丹顿（马修·麦康纳 Matthew McConaughey 饰）的男人的出现改变了人类所面临的局面，他希望找到能够协助他的勇士，同他一起去斩杀巨龙。丹顿的行为很快遭到了巨龙的报复，古堡被毁，人类再次流离失所，被逼得走投无路的奎因明白，除了奋起反击，他们再无退路。','Fight Fire With Fire',60000000,43061982,27.615108,6,669,101,'2002-07-12','en','/1BxelEUo9VqMDotBsYQTcaPc3hc.jpg',3.293725289040976,3,'2026-09-10',2,NULL,NULL),(6282,'女狼俱乐部','Coyote Ugly','“Coyote Ugly”是纽约最热门的酒吧，因为这里的调酒师全是性感女孩，美丽的Violet亦是其中一员。她21岁离开家乡，独自一人来到纽约。本想成为一名作曲家，可到纽约后，就被大都市纸醉金迷的生活所吸引，在“Coyote Ugly”做了一名兼职调酒师。因为酒吧调酒师的名声并不好听，影响了她作曲家愿望的实现。但她并不后悔，努力工作，最新的愿望是要成为酒吧最出色、最受欢迎的调酒师。 Violet的老板(由Bello扮演)对教导害羞的姑娘融入酒吧环境很有一套。新来的姑娘很快就变得奔放而有魅力 ……','This party never ends.',45000000,113916474,26.79781,5.8,575,100,'2000-07-30','en','/xYM0laKrEqjiRSQNvqRrXPXN3iL.jpg',3.2338335971095287,3,'2026-09-10',2,NULL,NULL),(6415,'夺金三王','Three Kings','海湾战争结束之际，一小队胆大妄为的美军士兵盘踞伊拉克，决心盗取传说中埋藏于沙漠驻地附近的大批黄金。他们找到一张据信能指引金库的地图后，踏上征程，却在一系列意外发现中，被卷入一场改写人生的英勇挑战。','It\'s good to be King.',75000000,108000000,34.973086,6.6,692,114,'1999-09-27','en','/cLlZCKW1FO0OwcuOuGe2IPT9lOR.jpg',3.4052681680671903,3,'2026-09-10',2,NULL,NULL),(6435,'巫法闯情关','Practical Magic','　　莎莉（桑德拉·布洛克 Sandra Bullock 饰）和吉莉（妮可·基德曼 Nicole Kidman 饰）是一对感情十分要好的姐妹，表面上和常人无异的她们，实则出生在一个世世代代研习巫术的魔法家庭。姐妹两人的父母皆已去世，究其原因，要归结于笼罩在整个家族之上的诅咒——家族中女人们若与男人相爱，必将死于非命。  　　多年后，莎莉和吉莉长大成为了充满魅力的女性，尽管被诅咒的阴影所困，但她们的内心里依然充满着对于异性和爱情的憧憬。很快，莎莉就邂逅了她的真命天子，不顾家人的反对，她毅然同他结婚生子。同时，吉莉也陷入了与浪子杰米（高兰·维斯耶克 Goran Visnjic 饰）的情感纠葛中，两姐妹就此失散。当命运的不幸让她们再度聚首之后，她们都已经饱尝了失去爱人的痛苦滋味，内心倔强的二人决定潜心研究魔法，誓要同命运一决高下','',75000000,46683377,55.9267,6.783,338,104,'1998-10-16','en','/uHdgbrdx8lv5INu5aUS6irQ5SGG.jpg',3.290373087286796,3,'2026-09-10',2,NULL,NULL),(6439,'赛场大反攻','Racing Stripes','在一个狂风暴雨的夜晚，萨拉诺马戏团匆忙赶路，无意间丢失了团内的小斑马。这个孤独无助的小家伙很幸运地得到沃尔什农场主诺兰（Bruce Greenwood 饰）的救助，并由此得名小斑（Frankie Muniz 配音）。在诺兰及其女儿切宁（Hayden Panettiere 饰）的悉心照料下，小斑茁壮成长，它拥有极高的奔跑天赋，却因自己的怪模怪样而经常遭到隔壁农场内赛马们的嘲笑。它一心打败那些拥有纯正血统的赛马，为此私下里努力练习，并渴望有朝一日走入赛场。\r 某天，切宁的摩托车被故意损坏。为了不耽误打工，诺兰破例允许女儿骑着小斑上班。从小梦想成为妈妈那样优秀骑手的切宁，就这样和小斑开始了梦想之旅…','Cheer \'til you\'re horse!',30000000,93772522,8.058109,5.1,123,102,'2005-01-06','en','/epDsuf5oUdzTFYHqV2IRcyy8Rwc.jpg',2.8550142863939563,3,'2026-09-10',2,NULL,NULL),(6440,'航运新闻','The Shipping News','本片改编自E.安妮-普罗克斯(E.Annie Proulx)荣获普利策奖(Pulitzer Prize)的小说。描述的是一个男人回到了他位于纽芬兰(Newfoundland)海岸的故居后，追寻自我的奇异旅程故事。 　　在诺瓦-斯科蒂亚省(Nova Scotia)的纽芬兰，报纸专栏作家夸伊勒(Quoyle，凯文-斯贝西饰，Kevin Spacey)，带着他年幼的女儿邦尼(Bunny，阿丽莎-盖纳饰，Alyssa Gainer)在严厉的姑妈阿格尼丝-哈姆(Agnis Hamm，朱迪-丹奇饰，Judi Dench)的劝说下回到了他们祖上传下来的故居，这所房子在咆哮大海的悬崖峭壁边已空关了40年。北方海边的空气和那个死气沉沉港口的世俗工作渐渐地抚慰着夸伊勒的伤痛。 　　夸伊勒自小生长在一个不和的家庭，双亲告诫他说他将一事无成。当他爱上了邦尼的母亲佩特尔(Petal，一个极为放荡而又异常漂亮的女人，凯特-布兰切特饰，Cate Blanchett)时，夸伊勒想他终于交上了一丝好运。然而，佩特尔的突然去世，加上全无爱意的双亲也同时谢世，夸伊勒从带来伤感的纽约波基普希(Poughkeepsie)移居到了加拿大的海岸边，以寻求解脱。 　　在一家名叫《跛鸟》(Gammy Bird)的小报社，夸伊勒每天与同事们的交往使他重新获得了自信与自尊，通过与韦弗(Wavey，可爱的朱丽安-摩尔，Julianne Moore)的友谊，以及对祖上那些古怪的家族秘密的了解，夸伊勒、邦尼和阿格尼丝慢慢地重新找到了新的方向、新的希望，重新开始了一种全新的生活。','You\'ll never guess what you\'ll find inside...',0,0,11.1399,6.4,108,111,'2001-12-18','en','/3IdEZw4YN4NfvjLRyZVWpI0z2IH.jpg',2.8890737877476584,3,'2026-09-10',2,NULL,NULL),(6466,'弗莱迪大战杰森','Freddy vs. Jason','某日在地狱里，有两个臭名昭著的变态杀人狂碰到了一起，一个是带着冰球面具而且从来不开口说话的杰森(肯·克辛格)，他喜欢用一把弯刀肢解小孩子，另外一个是戴一顶黑色礼帽、手指甲是锋利长刀的弗莱迪(罗伯特·恩朗德)，他的嗜好是进入到别人的睡梦中将其置于死地。 　　两个大魔头在地狱里还不老实，弗莱迪利用他的特长进入杰森的梦中，利用杰森母亲的形象控制他，命令他到榆树街上杀人，这样弗莱迪才能重新得到复生的力量，到杰森意识到自己被狡猾的弗莱迪的愚弄时，决定也杀回到人间，找到弗莱迪要看看到底谁才是变态杀人王。 　　于是他们从榆树街一路杀到水晶湖少年营地，正在这里渡假的一群年轻人被卷入两个魔头的杀人竞争，但是今时不同往日，几个年轻人当然不堪束手待毙，他们暗中对杰森和弗莱迪进行着不动声色的挑拨和分化。最终，两个本来就互相看不顺眼的杀人狂在水晶湖畔上演了一出血腥大戏，而一番较量后胜出的那个，是智商比较高的弗莱迪？还是占了地利的杰森？抑或是双方两败俱伤？','Evil Will Battle Evil',30000000,114908830,26.69592,5.8,594,97,'2003-08-15','en','/jwdck1dIodD6PhimH7opvzYaOiT.jpg',3.2398950888069744,3,'2026-09-10',2,NULL,NULL),(6477,'鼠来宝','Alvin and the Chipmunks','在人们的脑海里，活泼可爱的花栗鼠原本属于浓密茂盛的树林。那里才是他们生活、嬉戏的世界。但在无奇不有、无所不能的大银幕上，三只活蹦乱跳的花栗鼠则成为能说擅唱的活宝级人物（动物似乎更确切一点）：穿红色帽衫的艾尔文 可以说是花栗鼠三人组的头儿，性格张扬爱搞恶作剧；穿蓝色帽衫的高个子西蒙 则是个爱安静且脑子充满智慧的家伙，鼻子上的黑边眼镜就能说明这一点；身形略显富态的西奥多 喜欢穿绿色帽衫，是个活泼、可爱好吃懒动的家伙。 　　这不三只穿着时髦的小可爱闯入了人类的世界，游荡到了一个穷困料到、事业失败的作曲家大卫·塞维尔 的门下。小家伙们二话不说就霸占了大卫的房子，为了说服大卫收留它们，三只花栗鼠也展露天分，原来它们不仅会说话，还很会唱歌。于是，在倒霉音乐人的建议下，一支花栗鼠合唱组应运而生。身兼合唱组经纪人及歌曲作者的大卫，在三只小可爱的帮助下，很快在竞争激烈的流行音乐圈名声大振。三只花栗鼠也在转瞬间成了家喻户晓的知名“人士”。不过，调皮捣蛋的小花栗鼠可不是可塑性很强的人类歌手，要管住它们可花费了大卫不少的心思和力气。大卫·塞维尔穷困寂静的生活也在三只小动物的“帮助”下，热闹、混乱、一团糟……','Get your squeak on!',60000000,361366633,47.336034,5.5,1177,92,'2007-12-13','en','/dEBB88CkGtPRzTRDEGnS1Sw5DdT.jpg',3.3639559576558793,3,'2026-09-10',2,NULL,NULL),(6478,'飞跃情海','Beyond the Sea','在七岁那年，达林（凯文·史派西 Kevin Spacey 饰）被医生预言，无法活过十五岁。然而，在母亲波利（布兰达·布莱斯 Brenda Blethyn 饰）、姐姐妮娜（卡罗娜·艾伦 Caroline Aaron 饰）和杰夫查理（鲍勃·霍斯金斯 Bob Hoskins 饰）的帮助和支持之下，达林最终长大成人，并且成为了一名小有名气的歌手。\r 　　之后，达林遇见了史蒂夫（约翰·古德曼 John Goodman 饰），在后者的帮助下，达林成为了当时最有名也是最受欢迎的爵士乐手。一次偶然中，达林结识了名为桑德拉（凯特·波茨沃斯 Kate Bosworth 饰）的女演员，两人迅速坠入情网，并且不顾家人的反对结为夫妻。然而，好运似乎就此截然而止，达林的事业陷入了低谷，感情遭到阻碍，就连健康也在急剧恶化。','In the era of cool, Bobby Darin was the soundtrack.',23000000,0,6.138213,6.5,55,118,'2004-12-17','en','/wIewPJNyyTIMI5rQzcElc23jenW.jpg',2.730056234613282,3,'2026-09-10',2,NULL,NULL),(6479,'我是传奇','I Am Legend','2012年，人类被不知名病毒感染，纽约成为一座空城。Robert Neville是为军方服务的科学家，也是对病毒有免疫力的幸存者。白天，他带着狗Sam在街道上寻找食物，用广播寻找幸存者，在实验室里研究治愈病毒的方法；晚上，他只能躲在屋子里，因为那些感染病毒而没有死亡的人们，成为了“夜魔”只能夜晚出来活动，丧失理智，会攻击所有的人。某天，Sam也感染病毒死去，Robert Neville陷入了前所未有的孤独。当他准备和“夜魔”们同归于尽的时候，另外一个幸存者Anna救了他。Anna相信山上的隔离区还有幸存者，但是固执的Robert Neville却坚持守在纽约。又一个晚上，“夜魔”攻击Robert Neville的住所，此时他的研究已经获得成功，但是只有坚持到天亮，人类才能得以延存。','The last man on Earth is not alone',150000000,585349010,70.867401,6.9,4853,101,'2007-12-14','en','/iPDkaSdKk2jRLTM65UOEoKtsIZ8.jpg',4.0440963034127675,3,'2026-09-10',2,NULL,NULL),(6488,'小魔星','Arachnophobia','一只来自丛林的特种蜘蛛，意外的来到文明镇上，经历了一连串的巧合波折后，她找到了一个安稳的家——医师家中的壳仓。原来安宁的小镇，却因为它的小蜘蛛群出现而陷入危机，镇上的居民要如何消灭它们呢？','Eight legs, two fangs, and an attitude.',31000000,53208180,15.895661,6.2,433,103,'1990-08-09','en','/lHjpwv1Yv2RcGcTQb4Lc1cKw1y9.jpg',3.198610417922959,3,'2026-09-10',2,NULL,NULL),(6519,'正义前锋','The Dukes of Hazzard','故事发生在乔治亚州的海泽镇，卢克（约翰尼·诺克斯维尔 Johnny Knoxville 饰）和博（西恩·威廉·斯科特 Seann William Scott 饰）是情同手足的两兄弟，无所事事的两人每日就在叔叔杰西（威利·纳尔逊 Willie Nelson 饰）的农场里鬼混，整日不务正业。某日，卢克和博意外得知海泽镇的局长霍格（伯特·雷诺兹 Burt Reynolds 饰）和治安官柯尔特（大卫·科恩查内 David Koechner 饰）想要得到农场的阴谋，只因为在农场底下埋藏着珍贵的矿藏。对农场有着很深感情的两兄弟当然不能让他们得逞，联手性感火辣的表妹黛西（杰西卡·辛普森 Jessica Simpson 饰），四人在农场之中上演了一场你争我夺的精彩“战役”。最终鹿死谁手，尚未可知。','Cousins. Outlaws. Thrillbillies.',50000000,110803676,15.98212,5.1,316,104,'2005-08-05','en','/2ZrNyYJEgE0VIqhelQPqFTR20xF.jpg',3.0289067553932205,3,'2026-09-10',2,NULL,NULL),(6520,'第一武士','First Knight','圆桌武士兰思洛一次在森林中意外营救了亚瑟王的未婚妻Guinevere，两人虽一见钟情，但碍于Guinevere早已是亚瑟王的未婚妻，所以只好无奈地将他婉拒。后来亚瑟王揭发了他们两人的恋情，在痛心之余，亚瑟王决定要公审他们，不过此时亚瑟王却受到敌人的大举入侵，全国人民束手无策，兰思洛见势立刻拔刀相助，拯救亚瑟王于危难中。','Their greatest battle would be for her love.',55000000,127600435,19.143321,5.9,311,134,'1995-07-07','en','/dJH5bwtu3UxbwRsSlhlhmMrV8ZH.jpg',3.105502955701063,3,'2026-09-10',2,NULL,NULL),(6521,'暗潮汹涌','The Contender','副总统的突然去世将民主党参议院莱恩（琼·艾伦 Joan Allen 饰）推向了风口浪尖，她被提名为最佳总统候选人，如果莱恩当选，那她将成为美国历史上第一位女性总统。莱恩的性别很快就成为了保守党们激烈攻击的目标，其中要属谢力（加里·奥德曼 Gary Oldman 饰）的攻击性最强。\r 　　谢力是一个老谋深算阴险狡诈的老政客了，他是那种为了达到目的可以不惜一切手段的男人。谢力不知道从哪里挖出了莱恩大学时代的黑历史，这段历史的曝光不仅将影响莱恩此次的竞选，而且有可能毁掉她的政治生命乃至个人生活。为了捍卫自己的权利，莱恩必须勇敢的站在聚光灯下进行反击。','Sometimes you can assassinate a leader without firing a shot.',9000000,0,7.029126,6.7,60,126,'2000-10-13','en','/duRe0F2GYHIDvqe2bqIAMP4gWeP.jpg',2.755913470495433,3,'2026-09-10',2,NULL,NULL),(6537,'孤堡惊情','El orfanato','劳拉自幼在孤儿院中长大，一大群小朋友天天玩着“一二三，回头看”的游戏，十分友爱。30年后，结婚成家的劳拉带着丈夫和儿子再次来到这座海岸边上的荒废已久的孤儿院，为了重温童年时温暖的回忆以及帮助更多的孤儿，他们决定重建这里。然而7岁的儿子西蒙自从搬来这屋子就开始变得不对劲，他幻想出三个不存在的小朋友嬉戏。劳拉和丈夫担心这个收养又同时患有艾滋病的儿子，劳拉的过度担心让儿子反感。他们一直不相信那些幻觉的真实性，直到一天西蒙失踪了。长达9个月的调查，劳拉开始相信鬼魂的存在，并且发现事情与自己童年时的一位护理员有关，她沉下心来，陪伴这些“孩子们”玩游戏，希望能救出西蒙。','A tale of love.  A story of horror.',0,44000000,29.071955,7.1,633,105,'2007-08-27','es','/Af7QpR36BCn6oSA5VowSDZBHX06.jpg',3.4389601013041204,3,'2026-09-10',2,NULL,NULL),(6538,'查理·威尔森的战争','Charlie Wilson\'s War','查理（汤姆•汉克斯 Tom Hanks 饰）被美国国防部授予了反战间谍英雄的称号，因为他跟其他的谍报人员——乔安妮（朱莉娅•罗伯茨 Julia Roberts 饰）与盖斯特（菲利普•塞默•霍夫曼 Philip Seymour Hoffman 饰）一起为前苏联的解体、柏林墙的倒塌都做出了重要贡献。查理具有光鲜身份，他身兼国防部、政府、CIA等多方角色，终日周旋于商界政要之间，美色金钱纷至沓来，谁都希望借助他的能量满足一己私利。他关注阿富汗战争的局势，并且跟巴基斯坦的军方也通了气。其实，他所做的都是为了美国的利益，在红颜知己乔安妮与性格伙伴盖斯特的帮助下，他们导演了这场充满了传奇色彩的间谍战争…… ©豆瓣','Based on a true story. You think we could make all this up?',75000000,119000410,18.70031,6.5,338,102,'2007-12-19','en','/3caK23lKqRfuaPeUUFnzOqSP3IN.jpg',3.178432038670238,3,'2026-09-10',2,NULL,NULL),(6552,'Idle Hands','Idle Hands','Anton is a cheerful but exceedingly non-ambitious 17-year-old stoner who lives to stay buzzed, watch TV, and moon over Molly, the beautiful girl who lives next door. However, it turns out that the old cliché about idle hands being the devil\'s playground has a kernel of truth after all.','The touching story of a boy and his right hand.',25000000,4152230,8.583217,6.1,182,92,'1999-04-30','en','/mCO4gU1lkViGXTkoRBEYrvjDIJu.jpg',2.9838575673805607,3,'2026-09-10',2,NULL,NULL),(6557,'27套礼服','27 Dresses','珍（Katherine Heigl饰）是个完美伴娘，已经穿过27套伴娘服的她笃信真爱，可是面对自己暗恋许久的人——她的上司乔治，珍却总是爱在心，口难开。一次派对上，珍的妹妹苔丝和乔治邂逅了，火热招摇的苔丝迅速攫住乔治的目光，事实上，苔丝就是个骄横跋扈的大小姐，但为了俘获乔治的心，她编出种种谎言，装成温顺可爱的乖乖女，使两人关系迅速升温。不久，两人便打算闪电结婚，而珍则再一次被邀请成为伴娘……','She\'s about to find the perfect fit.',30000000,160259319,30.695228,6.1,978,111,'2008-01-10','en','/hL8VAPu5xNe0kYwGo7xATJInLKH.jpg',3.3971198880490214,3,'2026-09-10',2,NULL,NULL),(6575,'永不止步：戴维·寇克斯的故事','Walk Hard: The Dewey Cox Story','1946年，时年七岁的戴维•寇克斯（约翰•C•赖利 John C. Reilly 饰）在玩闹时失手将兄弟内特一刀砍为两段，父亲对逝去精通钢琴梦想远大的儿子伤心异常，从此对戴维心有芥蒂，而戴维带着内特死前的嘱托，发挥出了自己的音乐天赋。14岁的一次表演，令戴维卷入小镇的舆论中心，他不堪周围逼仄的环境，带着12岁的女友奔向了自己的音乐梦想。在舞厅中栖身的戴维偶然得到顶替演出的机会并幸运的在犹太商人资助下发行了一支热门单曲《艰难前行》，自此大热，此后的巡演中，戴维开始吸毒、创造更多佳作、并与副唱女歌手达令•麦迪森（珍娜•费舍尔 Jenna Fischer 饰）冲动结婚犯下重婚过错。21岁的戴维经历了牢狱之灾和康复治疗，在六十年代的反战潮流中与披头士在印度一同静思。关于他的传奇故事，还远未结束……','Life made him tough. Love made him strong. Music made him hard.',35000000,18317151,10.73522,6.6,212,96,'2007-12-21','en','/Aa1IQ4Cuin3d7qIahvPheMmR4E5.jpg',3.0554551892314414,3,'2026-09-10',2,NULL,NULL),(6615,'充气娃娃之恋','Lars and the Real Girl','在寒冷的冰雪中，单身汉拉斯（瑞恩•高斯林 Ryan Gosling 饰）感到有些孤寂而无聊。他是一个典型的宅男，性格自闭，无友无伴。他的哥哥格斯（保罗•施耐德 Paul Schneider 饰）和嫂子（艾米莉•莫迪默 Emily Mortimer 饰）住在隔壁，见此情景也觉得辛酸。嫂子见他整天宅在家中，于是邀请他前来吃饭，但是兄嫂的嘘寒问暖仍无济于事。某天，拉斯居然从玩具公司定制了一个充气娃娃比安卡，并带她参加家庭聚会，一起吃饭，一起入眠，一起去教堂礼拜。周围的人都觉得拉斯的精神不正常，兄嫂为此专门咨询了医生达戈玛（派翠西娅•克拉克森 Patricia Clarkson 饰），后者认为拉斯的症状是一种幻觉，最好的治疗就是因势利导。而此时，拉斯对于比安卡的痴迷已经达到了无以复加的地步，甚至还要在教堂跟它举行婚礼……','The search for true love begins outside the box.',12000000,11293663,15.817096,7.1,509,106,'2007-10-12','en','/nkAt4a7KIPc7Fi1BhxNHhYYbe2b.jpg',3.3455418829201147,3,'2026-09-10',2,NULL,NULL),(6623,'末日戒备','The Peacemaker','美国白宫反核走私情报部门的朱莉亚.凯利博士怀疑俄罗斯境内造成重大伤亡的核意外不是偶然发生的事故，而是某位俄罗斯将军为掩盖窃取核弹头制造的烟幕，他们经历失败之后又把核弹头盗卖给波斯尼亚的一位政客。失莉亚在戴夫上校的陪同下来到东欧，通过艰苦的调查终于查明，这名政客实际是一名核恐怖分子，并已带着一枚核弹头进入美国本土，欲炸毁设在纽约的联合国总部......','How do you get the world\'s attention?',50000000,0,15.931084,5.8,255,124,'1997-09-26','en','/xLmZDzzi6qftlcX6OgEyElTysUC.jpg',3.0499746597468267,3,'2026-09-10',2,NULL,NULL),(6639,'霍乱时期的爱情','Love in the Time of Cholera','长达半个世纪的爱情故事。  　　19世纪末期哥伦比亚的喀他赫纳，电报员Florentino Ariza（Javier Bardem 饰）爱上了富商的女儿Fermina Daza（Giovanna Mezzogiorno 饰），他用热情洋溢的情书打动了Fermina Daza的心，二人迅速相恋。然而，由于身份地位的悬殊，Fermina Daza不得不屈从于父亲，离开了喀他赫纳，在年轻的Fermina Daza看来，二人的爱情只是少不更事的幻觉而已。  　　几年后，Fermina Daza在父亲的安排下，嫁给了有好感的医生Dr. Juvenal Urbino（Benjamin Bratt 饰）。正值霍乱时期，一个医生丈夫不仅能带来优渥的生活，更是生命有力的保障。Fermina Daza渐渐忘记了当年的事情。可是Florentino Ariza却没有忘记，当年一无所有的青涩少年，继承了伯父的遗产，成为富有的船商，他经历着不同的女人，但是内心却对Fermina Daza念念不忘，他能做的事情，就是等待，等待重逢的那一天，纵然五十多年过去，对她的心意还一如往昔。','How long would you wait for love?',45000000,4607608,5.361699,6.4,81,139,'2007-10-04','en','/lU3uvWGQlWeySxrUlJpxNaHW2Ra.jpg',2.8115643160049344,3,'2026-09-10',2,NULL,NULL),(6687,'穿越西伯利亚','TransSiberian','美国夫妇罗伊（伍迪·哈里森 Woody Harrelson 饰）和杰西（艾米莉·莫迪默 Emily Mortimer 饰）坐火车从北京到莫斯科度假。在车上他们认识了西班牙小伙子卡洛斯（爱德华多·诺列加 Eduardo Noriega 饰）和美国姑娘艾比（凯特·玛拉 Kate Mara 饰）。当火车在西伯利亚小镇伊尔库茨克停留时，罗伊因贪恋观光而误了火车，卡洛斯和艾比决定与杰西在下站的伊兰斯基一同等待罗伊乘下班火车赶来。风流的卡洛斯很快便向杰西发起了追求攻势，使本来单纯的观光之旅变得复杂。而下一位与杰西夫妇同车厢的旅客竟是俄罗斯缉毒警官格林科（本·金斯利 Ben Kingsley 饰），随着事态越变越诡异，罗伊夫妇发现自己已深陷危机……\r 　　本片获西班牙高迪奖最佳艺术指导和最佳电影剪辑奖及最佳摄影、最佳外语、最佳音效和最佳特效四项提名，并获美国科幻、幻象及恐怖电影协会土星奖最佳女主角（艾米莉·莫迪默）、最佳国际影片及最佳男配角（伍迪·哈里森）提名。 ©豆瓣','You can\'t escape your lies.',15000000,5926410,11.428903,6.5,195,111,'2008-01-18','en','/kyI8UvsS29zPd00frnrWjlVYik5.jpg',3.030557858384671,3,'2026-09-10',2,NULL,NULL),(6795,'勇敢者的游戏：太空飞行棋','Zathura: A Space Adventure','父亲因为工作需要出门，姐姐莉莎（克里斯汀•斯图尔特 Kristen Stewart 饰）作为老大不得已担负起照顾两个弟弟丹尼和沃特的责任。然而莉莎偷懒留下丹尼（乔纳什•波波 Jonah Bobo 饰）和沃特（乔什•哈切森 Josh Hutcherson 饰）这两个生性好动，年幼顽皮的的家伙自己上楼去睡觉。无聊至极的二人只得自娱自乐，但二人不断的争吵让丹尼赌气离开，独自来到地下室淘宝，意外的发现了一套太空飞行棋。好奇心起的丹尼开启了游戏的开关，并邀请哥哥沃特参与到游戏中来。不断的流星雨和外星人侵袭让这场游戏越发的惊心动魄，而中途加入的神秘太空人真实的身份更是让人大跌眼镜。渐渐他们意识到，这不是一盘普通的游戏棋，而一旦开启了游戏的开关，如若不能到达游戏的终点扎图拉行星，等待他们的将是永远滞留在外太空。那么两兄弟能否在这场真实的冒险中尽释前嫌，联手度过难关？','Adventure Is Waiting',65000000,64321501,15.194239,6.1,779,101,'2005-11-06','en','/12uGT9JzZyB0oW3GgDnobhOu2LX.jpg',3.312581682187877,3,'2026-09-10',2,NULL,NULL),(6877,'赖家王老五','Failure to Launch','俗话说的好“女大不中留！”可如今，这句话用到男儿身上，同样有着深不可测的意义。闲话不扯，但说本故事中的男一号，帅哥特瑞普(马修·麦康纳)虽有着令众多同龄人羡慕的好工作和丰厚收入，而且，尚显青春的他也是风度翩翩、举止高雅的主。可是早已进入而立之年的他却至今仍与和他相识的众多适龄的女人保持着授受不亲的关系。虽说做个钻石王老五也有着很多的优越性和尚可炫耀之处。可长此以往，日渐衰老的父母却急上了房。眼见着大龄爱子这样整日赖在这个“老家庭”里，做着老父母的大小孩，两位老人恨不得立刻让儿子特瑞普卷铺盖走人，以早早营建自己的小家，这样也可为老人日后增添了不尽的安慰。　　于是乎，聪明的二老经过了缜密的筹划，终于制订出一整套周密的计划来对付这个不愿长大离开家的大小子。首先，是对儿子特瑞普对异性的兴趣取向进行调查了解，几次测试后，终于得知，性感成熟、金发碧眼的女孩总能令稍显木讷的儿子精神百倍。然后，两位老人私下里雇佣了一位有着一头美丽的金发以及性感迷人的外形的漂亮姑娘(莎拉·杰西卡·帕克)主动接触儿子特瑞普，以鼓动儿子逐渐建立起独立自主的冲动和决心。最让二老放心的是，这位美丽的姑娘不但有着勾人的外表，还有着足够聪明的头脑，足以顺利完成他们的目标。　　接下来，便是此起彼伏的浪漫事件接连发生，而主动的女性似乎更让那些高傲的大男子们无法招架。尤其是面对眼前如梦中情人转瞬出现般的金发美女，特瑞普更是没有了丝毫的心理设防。来了个全身心中招。激情的派对、阳光遍洒的出海旅游、餐馆里的浪漫缠绵……无不令往日闪闪发光的钻石王老五完全褪去了光彩，忘我地投入到了这场浪漫的情感大戏之中。而只是身为受雇者的漂亮姑娘似乎也在不经意间进入了“角色”。再加之众多朋友、同事们的“倾情加盟”，一场“大龄青年拯救运动”轰轰烈烈、热热闹闹、沸沸扬扬地展开了……','To leave the nest, some men just need a little push.',50000000,88715192,18.806031,5.5,399,97,'2006-03-10','en','/omReuKQ8ItWYD5pOLmsKh3MF24w.jpg',3.112728080812507,3,'2026-09-10',2,NULL,NULL),(6933,'鬼来电','One Missed Call','年轻少女贝丝•雷蒙德（Shannyn Sossamon 莎妮•索萨蒙 饰）正经历人生最恐怖的时刻。她的两位好友谢莉（Meagan Good 饰）和琳恩（Azura Skye 饰）短短几天内相继遭遇横祸，离奇死亡。更为恐怖的是，她们在死前的几天皆收到来自自己手机的语音短信，短信不仅预告了死期，还录下她们惊恐绝望的呼叫。此后几天，贝丝更亲眼目睹其他几位朋友的死亡，阴森肃杀的气氛在她们之间蔓延。 警察杰克（Edward Burns 饰）受命调查此案，与其他警探不同，他对贝丝的描述深信不疑，因为杰克的妹妹便是这一连串离奇事件的第一位牺牲者。两人达成共识，联合调查背后真相，而这时贝丝却接到了自己手机发来的神秘短信…… 本片根据日本同名电影翻拍。','What will it sound like when you die?',20000000,0,12.458131,4.7,171,87,'2008-01-04','en','/9OK7nyD9a5pViIElRjK9HVzQQ0Y.jpg',2.8994337846358986,3,'2026-09-10',2,NULL,NULL),(6947,'神秘村','The Village','1897年，宾夕法尼亚州有一座名为考明顿的小村庄。这里风光秀美，景色宜人，村民间更是团结友爱，和善为亲，过着平静自在的生活。然而，考明顿村民的心中却有着一个挥之不去的梦魇。传说在村子周围的丛林中隐藏着残忍而恐怖的怪物，它们和村民间似乎有着一道不可僭越的约定，双方守在各自的领地，秋毫无犯。但是近一段时间种种迹象表明，盘踞在森林中的怪物正试图践足人类的领地。人们对此无计可施，只能用古老的办法——在树干漆上黄色——来阻退怪物。  　　为了医治母亲的病，年青人路西斯（杰昆·菲尼克斯 Joaquin Phoenix 饰）决心去森林另一边的城镇采购药品。这一举动彻底改变了考明顿的命运…… ©豆瓣','There is no turning back',60000000,256697520,27.491891,6.2,1071,108,'2004-07-30','en','/6NZGRm0iKS2nA3KFdg9JUTIddcj.jpg',3.4272810858395473,3,'2026-09-10',2,NULL,NULL),(6950,'极度恐慌','Outbreak','1967年，在非洲的扎伊尔莫他巴河谷，美国的雇佣军兵营中被一种突如其来的疾病肆虐，死亡人数不断攀升。军医抽取感染血样离开后，整个军营被炸弹摧毁，附近树林中的白脸猴发出阵阵惊叫声……  直到90年代，一个美国年轻人在非洲扎伊尔捕捉到一只小白脸猴，并带回国出售。由于不合买主要求，年轻人将猴子放生，之后一种新型疾病在旧金山的香柏溪镇上蔓延。美国传染病研究所上校军医山姆（达斯汀·霍夫曼 Dustin Hoffman饰）接到消息，与妻子（蕾妮·罗素 Rene Russo 饰）及同事立刻展开研究和救治工作。由于疾病传染性极高，政府紧急出动军队封锁镇子，想要逃离者格杀勿论。此时，有一批保密的染毒血清被送来，但山姆等一群人研究发现，这批血清能救治1967年的疾病，却对如今变异后的病毒毫无作用。不久，山姆的妻子不幸被感染，生命垂危中时，政府也作出决定，准备投放炸弹摧毁整个镇子，以此消灭病毒。时间迫在眉睫，山姆查出了病毒的来源，他必须抢在投弹前找到原始病毒携带者。','This animal carries a deadly virus... and the greatest medical crisis in the world is about to happen.',50000000,189859560,30.397496,6.3,513,127,'1995-03-10','en','/vxQiCdZ1Pb7UkMvOo8g2Pj9gY1l.jpg',3.2819287809982134,3,'2026-09-10',2,NULL,NULL),(6957,'四十岁的老处男','The 40 Year-Old Virgin','安迪40岁了，有着高薪厚职的他过着平静的日子。然而，当他有一次和他的狐朋狗党聊天时无意中透露了自己还是处男的时候，麻烦来了。他的朋友们最急于的是如何介绍一个女孩给安迪好让他尽快摆脱处男身。虽然安迪自己也着急，但有些时候就是越急越乱。朋友们安排安迪去酒吧结识女孩，无奈安迪不能像其他人一样带着结识的女孩去兜风，因为他还不会驾驶。每次约会都笑料百出，安迪洋相尽出。安迪遇上了带着三个孩子的单亲妈妈翠西，两人很快堕入爱河，安迪这次能否摆脱处男身？','The longer you wait, the harder it gets',26000000,109449237,38.473732,6.2,1983,116,'2005-08-11','en','/svz3lO6wuwOUhwICPY4DrLe60XG.jpg',3.5896090020439693,3,'2026-09-10',2,NULL,NULL),(6961,'结婚纪念日','The Wedding Date','妹妹艾米（艾米·亚当斯 Amy Adams 饰）结婚的消息本应该让凯特（黛博拉·梅辛 Debra Messing 饰）感到高兴，但得知婚礼的伴郎竟然是曾经抛弃过自己的负心汉时，曾经的那种恨之入骨的感情又卷土重来。难道真的要形单影只的看着大家沉浸在浪漫的气氛中吗？凯特发誓决不让这样惨绝人寰的事情发生！一个念头在凯特的脑海中逐渐清晰起来。\r 　　几番周折后，凯特雇佣了临时男友尼克（德蒙特·莫罗尼 Dermot Mulroney 饰），温文尔雅又英俊帅气的尼克很快就赢得了凯特父母以及亲人的热烈欢迎，就连凯特自己也被尼克那不知是真是假的柔情和关怀所感动了，一种奇妙的感情在这对以金钱维系着关系的男女之间产生了。','Love doesn\'t come cheap.',15000000,47175038,10.194097,6.2,230,88,'2005-02-04','en','/x3o3VMEdwct54uLZmuzI4iyi2Zh.jpg',3.0451652892553787,3,'2026-09-10',2,NULL,NULL),(6963,'天气预报员','The Weather Man','戴维（尼古拉斯·凯奇 饰）是名天气预报员，可是他没有专业知识能用在工作上，当预报的天气并不理想时，观众们会在街上肆意向他丢垃圾。戴维对自己的生活感到灰暗，与妻子（霍普·戴维斯 饰）离婚更是对他的一个打击。如今他得到一个前往纽约重新工作的机会，可是他必须要面对与孩子们并不融洽的关系。儿子迈克被戒毒时认识的辅导员性骚扰；女儿雪丽的肥胖被学校的同学耻笑，性格忧郁。更令戴维伤心的是，他的小说家父亲罗伯特（迈克尔·凯恩 饰）患上了绝症。 　　戴维希望父亲能看到他的成功，他更想与前妻复合，一家人到纽约重新生活。无论做了多大的努力，他与家人的关系并没得到和缓，他依然遭到观众的垃圾袭击，他更开始抗拒前往纽约。 　　此时他看到父亲平静面对死亡的态度，并在与父亲相处的最后时光中，戴维被授予了很多人生的道理。','Dave Spritz is about to take his best shot . . . at life',20000000,12482775,14.031377,6,289,101,'2005-10-20','en','/ouBpYrhSnk1ieXKsVYKLDj5J6eP.jpg',3.0874359604010446,3,'2026-09-10',2,NULL,NULL),(6964,'爱是妥协','Something\'s Gotta Give','纽约音乐制作人哈利(Jack Nicholson 饰)是名专挑年轻美眉下手的老不休，直到一次机缘巧合下遇见了她现任女友玛琳的母亲艾瑞卡(Diane Keaton 饰)，一名离了婚的剧作家，竟然对她怦然心动。哈利觉得自己不正常去请求年轻医师的协助，不料这名年轻医师竟成了他的头号情敌，也爱上了年纪几乎可以当妈的艾瑞卡……','Schmucks are people too.',80000000,266728738,16.939441,6.3,410,128,'2003-12-12','en','/2JKCL1ekF60JEe6j8XB8OkeGTQ5.jpg',3.1996428053288914,3,'2026-09-10',2,NULL,NULL),(6968,'巴德尔和迈因霍夫集团','Der Baader Meinhof Komplex','本片讲述了1970年代德国极左恐怖组织“红军支队”的兴衰史。由安德里亚斯·巴德尔（莫里兹·布雷多 Moritz Bleibtreu饰）和乌尔丽克·迈因霍夫（马蒂娜·戈黛特 Martina Gedeck饰）领导的德国无政府主义组织“红军支队”，从1972年开始一直从事极左的恐怖活动。在标榜以德国“国家道德腐败”的名义下，该组织试图创建一个更加人性化的社会体制。然而他们正是用以暴制暴的方式，犯下了多起暗杀、爆炸攻击以及绑架的罪行，所谓的人性在嗜血成性的恐怖事件当中消失殆尽。影片根据记者斯特凡·奥斯特80年代的畅销书改编而成，荣获2009年第81届奥斯卡金像奖最佳外语片提名，2009年第66届金球奖电影类-最佳外语片提名，2009年第22届欧洲电影奖最佳男演员提名等多项大奖。',NULL,27000000,0,7.727035,7.1,157,150,'2008-09-24','de','/zjhAW6rEL2HQaTFgvpkQi2tp9F7.jpg',3.0032847944180174,3,'2026-09-10',2,NULL,NULL),(6972,'澳洲乱世情','Australia','故事发生在二次大战前夕的澳洲，优雅的英国贵族莎拉，为了保护她所继承的土地，千里迢迢的来到地球另一端的蛮荒之地——澳洲。当她抵达这片一望无际的土地时，她发现除了必须克服陌生环境所带来的重重挑战外，还必须和当地粗野不羁的放牧人共同合作，一起横越北澳洲大陆。在这趟艰辛的路程中，他们二人一路扶携相随，穿越了大半个澳大利亚，领略了迥然不同的壮丽景观，结识了众多豪放热情的居民和当地土著人。同时，他们也开始感受到彼此内心冲突的转变，一股莫名的奇妙感觉不住涌上心头。正当他们到达目的地，打算开始一番轰轰烈烈的新生活时，战争却轰然而至。1942年，日军轰炸澳大利亚达尔文港，莎拉的豪宅被火光吞噬，他们该如何面对接二连三的艰险考验与战争的威胁？这场可歌可泣的爱情与家园保护之旅能否继续下去呢？','Welcome to Australia!',130000000,49554002,28.840997,6.3,694,165,'2008-11-18','en','/bpQr3GCQpOQCNLR4UEZXCcr8o3C.jpg',3.348081724945126,3,'2026-09-10',2,NULL,NULL),(6973,'决战以拉谷','In the Valley of Elah','本片取材自真实事件。伊拉克步兵麦克•德尔菲尔德（乔纳森•塔克 Jonathan Tucker 饰）的父亲汉克•德尔菲尔德（汤米•李•琼斯 Tommy Lee Jones 饰）某天突然接到儿子回国后失踪的消息。老兵汉克驱车来到军营亲自调查，从儿子手机的影像中一点点了解到了麦克在伊拉克所经历的心理创伤。没多久警方发现麦克遇害，并被肢解焚尸。汉克的妻子琼（苏珊•萨兰登 Susan Sarandon 饰）得知噩耗后悲恸万分，不能自己。汉克在调查案件的过程中结识了当地探员艾米莉（查理兹•塞隆 Charlize Theron 饰），二人建立了一种特殊的友谊，并一步步接近事件的真相。  　　本片获奥斯卡奖最佳男主角提名（汤米•李•琼斯），并获第64界威尼斯电影节天主教文化奖大奖及金狮奖提名。','Sometimes finding the truth is easier than facing it.',23000000,29541790,15.676123,6.6,261,124,'2007-08-31','en','/9ukVlcxBcZtxI444BfgvWCaRcSo.jpg',3.117310853486063,3,'2026-09-10',2,NULL,NULL),(6977,'老无所依','No Country for Old Men','1980年的美国德克萨斯州西部，美国与墨西哥交界的格兰德河镇，一穷二白的前越战老兵莱维雷伦·摩斯（乔什·布洛林 饰）在打猎中偶然发现了数具尸体，以及数量庞大的海洛因和用来交易毒品的大量现金。死者都是火拼中死于枪下的黑帮分子。雷伦当即决定把枪战现场留下的毒品交易巨款带回家窝藏。夜里，忐忑不安的雷伦回到交易地点。不想，他的举动给自己招致杀身之祸。至此，黑帮头目派出冷血杀手安东·奇古尔（哈维尔·巴登 饰）、老警长埃德·贝尔（汤米·李·琼斯 饰）、雷伦展开了一场相互追逐的杀戮之旅。','There are no clean getaways.',25000000,171600000,53.645267,7.7,3003,122,'2007-11-08','en','/6d5XOczc226jECq0LIX0siKtgHR.jpg',4.07842159141075,3,'2026-09-10',2,NULL,NULL),(6978,'妖魔大闹唐人街','Big Trouble in Little China','香港功夫动作片到底对好莱坞的影响有多深？本片是较早期的一个例证。从故事情节、场景布置、演员数量以至武打镜头设计，均大量移植港片，只不过导演约翰．卡彭特始终是美国人，虽然他卖力地想拍一部纯娱乐性的东方版《魔宫传奇》，仍不免会让中国观众觉得有点非骡非马。库尔特．拉塞尔在片中饰演卡车司机波顿，他与中国好友王记去机场接王的未婚妻，但她被歹徒绑架，主使者竟是修行两千年的恶魔。王为了救未婚妻，遂伙同波顿及一群中国功夫高手闯进魔殿，和妖魔鬼怪大决斗。影片拍得颇为热闹有趣，如将它视为用美国电影技术拍摄的中国功夫片当会发现不少好玩之处。','Adventure doesn\'t come any bigger!',25000000,11000000,29.796394,7.1,705,99,'1986-05-30','en','/kR53dFS1httAr2O516MEY0e5Mf2.jpg',3.4719334330965927,3,'2026-09-10',2,NULL,NULL),(7006,'鬼讯号2：灵异透视','White Noise 2: The Light','艾比·戴尔（内森·菲利安 Nathan Fillion 饰）原本拥有幸福的家庭，但正当一家三口在餐馆用餐之际，他们却遭到一个持枪男子的袭击。艾比的妻子和儿子当场死亡，男子随后引弹自尽。时间过去三个月，艾比依然未能从丧失妻儿的悲痛中走出，他绝望之际，选择结束生命。然而造物弄人，艾比在医生的全力抢救之下自再次回到人间。此后不久，艾比发现自己能够听到一些奇怪的声音，甚至能看到某些人四周闪现的白光。他最终发现，身泛白光的全都是命之不久的人。借助这项奇特的能力，他开始尝试拯救那些徘徊于鬼门关的可怜人，但是他很快便意识到死亡的程序断不可随意更改，他必须为此付出代价…','Sometimes they don\'t come back alone.',0,0,6.814247,5.6,80,99,'2007-01-05','en','/du5coR9C7rY5rjys2nlmOvxgrq3.jpg',2.7883721028147628,3,'2026-09-10',2,NULL,NULL),(7191,'科洛弗档案','Cloverfield','好友罗布要去日本工作，他的弟弟杰森和朋友莉莉为他举办了一场欢送派对。看到杰森拎着DV只顾拍摄美女玛莲娜，莉莉很恼火，指出他更加关注罗布，因为后者才是今天的主角。罗布姗姗来迟，并且感到没落。原来他跟好友贝丝的地下情刚刚告吹，这令他异常沮丧。正在此时，贝丝携新男友出现在派对现场，这令好友感到既尴尬又愤怒，而真正的地震危险正在悄悄逼近……本片故事是采用伪DV风格的拍摄而成。','Some Thing Has Found Us',25000000,170764026,46.942396,6.4,2251,85,'2008-01-15','en','/2gVc19hmaP0LlkfZcLFfrKp6uJw.jpg',3.682430823857202,3,'2026-09-10',2,NULL,NULL),(7214,'卡特教练','Coach Carter','本片根据1999年对于卡特教练和他的常胜不败的篮球队的新闻报道改编，萨缪尔·杰克逊在剧中饰演颇具争议的卡特教练。 　　里士满高中篮球队原本从未在任何比赛中获胜过，是一支屡败屡战的队伍，这一切在卡特执教之后发生了变化。他相信这支队伍在他的带领下可以成为最优秀的篮球队，所以他要求队员和他签订一个协议，约定如果队伍不团结或是成绩不佳就不再继续参加任何比赛。在他的带领下，这支队伍开始走上了上坡路，最后成为无人能敌的长胜王。但是在1999年举行的国家锦标赛上，队员们的表现却十分不尽人意，这让卡特教练沮丧不已，他真的关闭了训练馆，禁止队伍继续参加任何比赛。此举引起了极大的反响，他一时成了大众议论的焦点，有人赞赏他视篮球为生命的品格，但更多的人对他的举动表示不解，甚至是批评。','It begins on the street. It ends here.',30000000,76669806,23.234651,7.3,496,136,'2005-01-14','en','/wFYYg2YJuFjrQhyx1VxRnL9BQNW.jpg',3.3793319786871168,3,'2026-09-10',2,NULL,NULL),(7220,'惩罚者','The Punisher','弗兰克·卡斯特（托马斯·简 Thomas Jane 饰）的生命中，绝大部分时间都在于死神赛跑。早年在海军陆战队服役，退役后又进入FBI。在枪炮火光中生活了多年之后，弗兰克不愿再整日收到死亡的威胁，家人整日为他担惊受怕。所以，他决定提前退休与妻儿享受平静的生活。可是，在最后的一次任务中，却因意外使一名无辜青年死亡。而这名青年的父亲却是坦帕市的大富商霍华德·桑特（约翰·特拉沃塔 John Travolta 饰）。为了给儿子报仇，霍华德向黑市发出了对弗兰克一家的绞杀令。不过弗兰克却侥幸在这场浩劫中存活下来。为了报仇，弗兰克不再寄望于法制，而是全副武装向霍华德发起挑战。面对霍华德组建的私人军队，弗兰克凭一己之力将如何应对？ ©豆瓣','There is no justice, there is only revenge.',33000000,54700105,35.099611,6.1,766,124,'2004-04-15','en','/jE0KxwtDiIuheflmrzcFjo5LSnc.jpg',3.354415749028446,3,'2026-09-10',2,NULL,NULL),(7278,'这不是斯巴达','Meet the Spartans','在军事化的斯巴达，列奥尼达（西恩•马奎尔 Sean Maguire 饰）经过与巨型企鹅的恶战证明了自己是斯巴达最强悍的战士，成功得到斯巴达王位，并迎娶玛戈为皇后。某日，正在对儿子进行毒打训练的列奥尼达接待了波斯使者，对方狂妄的宣称薛西斯王将统治希腊，斯巴达的孩子以后只能在血汗工厂中生产NIKE鞋。怒不可遏的列奥尼达杀死使者以及一干美国偶像，用化妆品贿赂先知请求开战，然而得到的却是丑女贝蒂神女的警告。列奥尼达仍然决定出征，他率领13名用喷漆画出腹肌的战士赶赴隘口布防，用街舞击败了波斯先头部队。肥佬薛西斯用蓝屏电脑特技制造出的大军压境，被列奥尼达弃用的帕里斯•希尔顿又告知波斯人包抄斯巴达军的小路，列奥尼达率众与洛奇、恶灵骑士等波斯大军展开了殊死搏杀。  　　本片改编自《斯巴达300勇士》，用恶搞手法对原片进行了重新演绎。','The Bigger the Hit, The Harder They Fall',30000000,84646831,10.608998,3.7,359,84,'2008-01-24','en','/DWQOjAPvM8Kk1Qp3Xq0zae0Z6w.jpg',2.897219996667487,3,'2026-09-10',2,NULL,NULL),(7288,'双层公寓','Duplex','在纽约这个竞争激烈的城市，生活着一对寻梦的夫妻：丈夫亚历克斯 和妻子南妮，他们青春蓬勃，相信自己拥有无可限量的美好未来。但他们也有一件遗憾的心事：没有属于自己的房子。 直到某一天，他们终于找到了心目中最理想的房子，那是一幢高级住宅区的豪华双层别墅，陈旧却有古典风情，很迷人。亚历克斯和南妮毫不犹豫，立刻把这幢别墅租了下来。他们以为从此可以过上甜蜜幸福的二人世界，然而意想不到的是，别墅的二楼住了一个古怪的老太婆康奈利太太，她的种种行径严重扰乱了他们的新居生活。 正当他们亲热时，老太婆往往会按响他们的门铃，甚至是站在窗外偷看，老太婆身体的虚弱也弄得他们疲惫不堪，他们的新居生活就这样成为了恶梦。于是，亚历克斯和南妮商量，如果不能把这个老太婆赶出这个别墅，那么他们索性一不做二不休，把她……',NULL,40000000,19322135,15.590001,5.9,482,89,'2003-09-26','en','/mCQ4oO9djqcthBRD3ftTnR8qSP7.jpg',3.1859680859557487,3,'2026-09-10',2,NULL,NULL),(7299,'撕裂的末日','Equilibrium','故事发生的时间锁定在一场虚构的世界核战争后。在这场人类的大浩劫之后，为了寻求人类不至于被自己毁灭，政府开始推行一种奇异的设想。给每个人注射一种麻痹情感神经的药物，使人们不再拥有感情，变成一堆行尸走肉。而约翰·普莱斯顿(克利斯汀·贝尔饰)则是这个政府的忠实“看门狗”，军事部门高级官员。他摧毁一切艺术品、工艺品，并将一切抗令不抛弃自己感情的人杀死，甚至于自己的同僚派彻吉(西恩·比恩饰)。而原因仅仅是，派彻吉非法藏有一本违禁的书籍。在一次行动中，约翰遇到了敢于向他挑战的玛丽·奥布赖恩(艾米莉·沃特森饰)。她使得约翰开始断绝药物，试图体会有感情的生活究竟是一种什么样的滋味。他被那些第一次出现在他生命里的奇妙动人景象所陶醉了，也深深的为每天履行的破坏艺术的行为感到愧疚和内疚。他的反常行为，被一直窥探其位置的新同事布兰特(泰亚·迪格斯饰)看在眼里，于是想尽办法，试探约翰的虚实。在工作与道义之间，在危险与安逸之间，在情感与沦丧之间，约翰又会做出怎样的抉择呢？','In a future where freedom is outlawed, outlaws will become heroes.',20000000,5359645,44.566609,6.9,1552,107,'2002-12-06','en','/yQuovle5Ov6q69XSdTNdH52eANc.jpg',3.6919304168072724,3,'2026-09-10',2,NULL,NULL),(7301,'孤独的吉姆','Lonesome Jim','讲述一个27岁的男子回家和父母一起住，当年青的吉姆(Casey Affleck演)决定自己无法独力完成后, 他回到在印第安纳的家乡小镇-- 让双亲庇护着。而当地一名妇女和她儿子解决了吉姆和家庭不和谐的关系，那个小孩更把他当成父亲般看待，想办法履行棘手的家庭责任。',NULL,0,0,3.433625,6.4,26,91,'2005-11-16','en','/z5wh9kFxpqC6bKB7TUx7j6X7BOq.jpg',2.560278667766275,3,'2026-09-10',2,NULL,NULL),(7303,'曼哈顿女佣','Maid in Manhattan','从小生活在贫穷当中的玛丽萨•文图拉（詹妮弗•洛佩兹 饰）十分坚强，如今她需要独自抚养儿子泰勒，她没有丈夫，没有幸福的家庭，而是每天都要为着儿子与自己的生活奔波劳碌。玛丽萨在曼哈顿一间高级酒店内当清洁女工，工资微薄。玛丽萨梦想自己与儿子的生活能有更大的改善，也希望自己能遇到一个真心爱自己的人。就在这时，她与英俊优雅的贵族公子克里斯多佛•马歇尔（拉尔夫•费因斯 饰）在酒店内相遇了，他误会了正试穿名贵时装的玛丽萨是一名社会名媛。两人对彼此都有好感，可是当进一步发展感情的时候，玛丽萨的真实身份成为了最大的障碍，玛丽萨又能否苦尽甘来，得到自己最想要的生活呢？',NULL,55000000,154906693,19.738215,5.6,485,105,'2002-12-13','en','/gnEuTYH3jhHxl80QyoPfZjEYd0J.jpg',3.1607206970404382,3,'2026-09-10',2,NULL,NULL),(7304,'夺命枪火','Running Scared','乔依从事专为黑社会“洗枪”的行当，不守规矩的是，他常常把那些正被警方严密追查的枪支藏在自己的密室里，而不是依行规将他们彻底销毁。一天，乔依这一举动被10岁的儿子和其小伙伴奥利格目睹，心术不正的奥利格随后偷偷从中取出一支0.38手枪，并当天用它击毙了虐待自己的继父。　　事故发生后，奥利格和手枪都不知所踪，更糟的是，奥利格的继父正是乔依一伙生意伙伴大老板的亲侄子，因此乔依一方面要躲着大老板的寻...','Every bullet leaves a trail.',17000000,9500000,19.311572,7,331,122,'2006-01-06','en','/pVOgYMPkblBUFMZCxthsgzS7Z7A.jpg',3.2216377717589912,3,'2026-09-10',2,NULL,NULL),(7305,'天劫余生','Alive','1972年10月13日，赴智利比赛的一支乌拉圭橄榄球队所搭乘的飞机在安第斯山脉失事。生还的二十多位幸存者面对冰天雪地的生存环境，竭尽全力地以求能活着走出这座荒无人烟的死亡之地。在经历了满心希望的等待着救援队伍无果之后，绝望地他们只能面对着残酷的事实，赖以维生的食物日渐减少，海拔气候寒冷严苛，遭遇好几次雪崩以及内心对死亡充满的巨大恐惧。在激烈的讨论和内心挣扎后，他们开始尝试一些不可能做到的事情，分食死尸。终于，在飞机坠毁五十多天以后，天气渐渐转暖，救援队终于找到了他们。活下来的十六个人终于走出了这块死亡之地，再一次与家人团聚在了一起。','They survived the impossible...by doing the unthinkable.',32000000,36733909,14.48851,6.7,374,120,'1993-01-15','en','/uQACcCZqd7WCTRin9xRIW5gr1bd.jpg',3.2136745319455913,3,'2026-09-10',2,NULL,NULL),(7326,'朱诺','Juno','鬼马精灵的少女朱诺面对与同学布里克意外怀孕的局面，与死党莉亚商议后，决定为未出生的孩子寻找一对“完美”的养父母：住在市郊、渴望领养孩子的富裕夫妇马克与瓦内萨。幸运的是，在做出艰难抉择、试探成人世界边界的整个过程中，朱诺始终得到了父母的全力支持，并最终厘清了属于自己的方向。','A comedy about growing up... and the bumps along the way.',7500000,231411584,19.782725,7,2244,96,'2007-12-05','en','/jNIn2tVhpvFD6P9IojldI3mNYcn.jpg',3.755555930697128,3,'2026-09-10',2,NULL,NULL),(7341,'魔女嘉莉2：邪气逼人','The Rage: Carrie 2','在她唯一的朋友自杀后，瑞秋从未感到如此孤立无援。唯一一个向她伸出援手的人，杰西，恰好也是那群以折磨像她一样的局外人为生的受欢迎人群中的一员。但瑞秋拥有一种与众不同的特质——一种用意念操控物体的神奇能力。苏·斯内尔，22年前凯莉·怀特暴乱中唯一的幸存者，或许掌握着帮助瑞秋接受她那令人敬畏却又不受欢迎的力量的关键。然而，随着瑞秋逐渐学会信任，一个可怕的陷阱正在向她袭来。激怒她可能会是致命的。','Looks Can Kill',21000000,17762705,4.781538,5.1,76,104,'1999-03-11','en','/jJmIf22gwwQPAFJfZ6Tr1MwSpRg.jpg',2.759249336929749,3,'2026-09-10',2,NULL,NULL),(7345,'血色将至','There Will Be Blood','当丹尼尔·普莱恩维尤得知西部有个小镇正涌出石油如海的隐秘消息后，便带着儿子H.W.前往尘沙蔽日的小波士顿碰运气。在这片贫瘠土地上，唯一的喧腾围绕着魅力非凡的牧师以利·桑迪所主持的圣滚教教堂。普莱恩维尤父子虽幸运地挖出了油井，但随着财富喷涌，冲突亦日益加剧——爱、希望、信仰、野心、社区纽带，甚至父子亲情，所有人性价值都在腐败、欺骗与石油洪流的冲刷下面临崩解。','There Will Be Greed. There Will Be Vengeance.',25000000,77208711,37.817905,7.9,1537,158,'2007-12-28','en','/fa0RDkAlCec0STeMNAhPaF89q6U.jpg',3.877445371223616,3,'2026-09-10',2,NULL,NULL),(7347,'精英部队','Tropa de Elite','时1997年，教皇即将来此视察，高层要求纳斯西蒙（Wagner Moura 饰）所率领的这支精英部队在最短时间内肃清贫民窟内的毒品链。厌倦刀光血影的纳斯西蒙将心思放在了妻子和尚未出世的婴儿身上，他将任务交给了两个热血且充满理想的年青人——内图（Caio Junqueira 饰）和马提阿斯（André Ramiro 饰）。他们俩都不满警察队伍的腐败，决心在精英部队中大展身手……','On the streets of Rio only the elite survive',4000000,0,23.604936,7.8,504,115,'2007-10-12','pt','/9dOFkUhFGD3HcZvBHdlWFlcTXbS.jpg',3.4463630998536714,3,'2026-09-10',2,NULL,NULL),(7350,'遗愿清单','The Bucket List','老富翁爱德华•科尔（杰克•尼克尔森 Jack Nicholson 饰）近年来在公立医院的私有化改造事业中获利颇丰，他为节省成本，规定病房“一房两床”的做法颇受非议，但性格强势的科尔不以为意，岂料他不久被检查出罹患癌症，本欲入住单人病房的科尔在舆论压力下只得与另一位病人——老卡特（摩根•弗里曼 Morgan Freeman 饰）同处一室。汽车修理技师老卡特博闻强识，将三个子女培养成才，但代价是牺牲了年轻时要做历史教授的梦想。曾经结婚多次如今却孤身一人的科尔逐渐对卡特产生了兴趣，两位老人在病房中结下了友谊。科尔偶然发现了卡特的“遗愿清单”，他决定运用自己的力量，让那些纸面上的疯狂构想一一实现，去发现人生的真正意义……','Find the joy.',45000000,175372502,31.305336,7,1111,97,'2007-12-25','en','/1Xy5DXXiNEjsKCCRM522GCdE77U.jpg',3.5891354578882018,3,'2026-09-10',2,NULL,NULL),(7364,'撒哈拉','Sahara','一枚金币让探险家德克（马修·麦康纳 Matthew McConaughey饰）兴趣盎然，因为金币与某个宝藏传说有着千丝万缕的联系。而德克是个极喜冒险、一刻也停不下来的人，他在非洲尼罗河一带展开了一段曲折的探险之旅，关于这枚金币的秘密层层剥开。更为关键的是，他还发现了一个足以危害人类毁灭地球的大危机——非洲一个独裁政权和当地富豪勾结，把核原料大量倾倒在海洋中。当地的人民已经深受其害，神志癫狂，如果不及时出手，危难将会迅速扩大。　　德克和女科学家伊娃（佩内洛普·克鲁兹 Penélope Cruz饰），共同展开了一场正义的斗争。他们要面对恶势力和艰险的自然环境，一路险相横生。','Dirk Pitt. Adventure has a new name.',130000000,119269486,21.605568,5.7,434,124,'2005-04-06','en','/d1TnHzwlDy5gU3bqCfNPuRI9CDc.jpg',3.1561635243596284,3,'2026-09-10',2,NULL,NULL),(7443,'小鸡快跑','Chicken Run','一部黏土动画戏仿《大逃亡》等经典越狱片。特威迪养鸡场里，一只小鸡策划了一场逃出鸡笼的惊险行动。','This ain\'t no chick flick. It\'s poultry in motion.',45000000,224834564,31.789029,6.5,1150,84,'2000-06-21','en','/iXY5JTEhC69BqX02bdm3BShjoMS.jpg',3.5080824105945245,3,'2026-09-10',2,NULL,NULL),(7445,'Brothers','Brothers','When his helicopter goes down during his fourth tour of duty in Afghanistan, Marine Sam Cahill is presumed dead. Back home, brother Tommy  steps in to look over Sam’s wife, Grace, and two children. Sam’s surprise homecoming triggers domestic mayhem.','There are two sides to every family.',26000000,43318349,22.07638,6.8,633,104,'2009-01-27','en','/AmqMTsREoT0ocuWMi32ts6z8OAh.jpg',3.3811351366348887,3,'2026-09-10',2,NULL,NULL),(7446,'Tropic Thunder','Tropic Thunder','Vietnam veteran \'Four Leaf\' Tayback\'s memoir, Tropic Thunder, is being made into a film, but Director Damien Cockburn can’t control the cast of prima donnas. Behind schedule and over budget, Cockburn is ordered by a studio executive to get filming back on track, or risk its cancellation. On Tayback\'s advice, Cockburn drops the actors into the middle of the jungle to film the remaining scenes but, unbeknownst to the actors and production, the group have been dropped in the middle of the Golden Triangle, the home of heroin-producing gangs.','The movie they think they\'re making... isn\'t a movie anymore.',92000000,188072649,43.192048,6.5,1667,107,'2008-08-09','en','/szaJ7ROtK29rXWW4VgfF78wPLhK.jpg',3.624416353966435,3,'2026-09-10',2,NULL,NULL),(7450,'冰冻星球','Titan A.E.','3028年的地球，人类的航天技术突飞猛进，已与宇宙间的各种智慧生物建立往来，却遭到一种纯能量体生物“锥尔”的攻击。山姆·塔克博士（朗·普尔曼 Ron Perlman 配音）在地球毁灭之际，为了保住“泰坦计划”，不得已将儿子凯尔（阿历克斯·迪·林兹 Alex D. Linz 配音）托付给外星朋友泰克（同恩·洛克 Tone Loc 饰）。15年后的凯尔随泰克在小行星带的垃圾站长大，直到父亲当年的同事约瑟夫·科尔索船长（比尔·普尔曼 Bill Pullman 配音）说服他以人类兴亡为己任，用父亲留下的戒指帮助寻找泰坦飞船的位置。与此同时，凯尔对副船长阿吉玛（德鲁·巴里摩尔Drew Barrymore 配音）一见钟情。众人经历千辛万苦后终于找到泰坦飞船，但他们能否共同抵抗锥尔人的攻击，为人类开辟新世界呢？  　　本片获安妮动画奖效果动画、制片安排及动画电影三项突出贡献提名及美国国际记者协会最佳影片金卫星奖提名，并获美国电影声音剪辑师协会最佳声音剪辑金胶片奖。','When Earth Ends, The Adventure Begins.',75000000,36754634,14.44381,6.3,313,94,'2000-06-16','en','/el2iHk3LTJWfEnwrvcRkvWY501G.jpg',3.1321358152269814,3,'2026-09-10',2,NULL,NULL),(7451,'极限特工','xXx','克桑德是极限运动界的明星，但他离经叛道，总是以他的身手对社会上那些败类名流发出挑战，当地警方对他也经常无可奈何。特工头子奥古斯塔斯看上了克桑德，于是派人将他抓了回来，说服他前往捷克进行一项危险而艰巨的任务。捷克的地下犯罪组织头子尤里正在进行一项疯狂的计划，他抓走了很多前苏联的科学家，利用他们研究一种威力无比的武器——毒气弹。他企图利用即将研制成功的武器引起世界大战，进而达到他统治世界的目的。克桑德以走私汽车贩子的身份前往捷克接近了尤里的组织，一场惊心动魄的行动展开了！','A New Breed Of Secret Agent.',70000000,277448382,46.217769,5.8,1424,124,'2002-08-09','en','/fPS0MgOCD7VmFy4EVmq21cr0BFC.jpg',3.454215959285438,3,'2026-09-10',2,NULL,NULL),(7453,'银河系漫游指南','The Hitchhiker\'s Guide to the Galaxy','每个人都曾经历过懊恼糟糕的早晨。懒床睡过了点，起床弄伤了脚趾，下楼磕了头，早餐烤焦了面包，阿瑟· 登特(马丁·弗里曼Martin Freeman 饰)的这个早上可谓衰运当头，而且还远不止这些。刚认识的美眉被人横刀夺爱，好端端的住家又要被拆，政府已经决定拆掉他的房子。诸事不顺之际，好友福特·普里弗克特(摩斯·德夫Mos Def 饰)承认自己是个外星人，正在地球上寻找新版《银河系漫游指南》。最耸人听闻的是，外星人正在建造银河系高速公路，而地球是阻挡工程进展的障碍物，外星人即将摧毁地球。福特要阿瑟一定要拿条毛巾才可以抢搭外星人的宇宙飞船。在福特的帮助下，阿瑟·登特在地球被毁灭前的最后一刻搭上了一艘路过地球的外星人的太空船，远离这个即将毁灭的伤心地，开始了一段充满惊奇的星河探险。没想到，才刚偷渡上船的他们又被放逐到外层空间，阴错阳差下更和银河系总统、忧郁症机器人一起亡命星际。在太空之旅中，阿瑟发现毛巾是宇宙里最有用的东西，并体会到了生命的精确含义，更发现所有他需要知道的一切居然都写在一本名叫《银河系漫游指南》的电子图书里，甚至体验到宇宙生命的全新意义……','Don\'t leave Earth without it.',50000000,104478416,51.742065,6.6,1315,109,'2005-01-15','en','/jX3KRd37ig3H1IcyD1bbcG7YLP5.jpg',3.6056941837948693,3,'2026-09-10',2,NULL,NULL),(7459,'极速赛车手','Speed Racer','影片改编自动画大师吉田龙夫(Tatsuo Yoshida)的经典系列动画作品。斯皮德·莱瑟（埃米尔·赫斯基 Emile Hirsch 饰）的父亲波普斯（约翰·古德曼 John Goodman 饰）是个汽车制造商，经营的公司已经相当有名气。在他的培养下，大儿子雷克斯成为世界顶级车手，然而，不幸的是雷克斯在一次比赛中失事过世。斯皮德在女友翠茜（克里斯蒂娜·里奇 Christina Ricci 饰）还有家人的支持下决定参加国际汽车大奖赛，并且找出哥哥死亡的真相。在比赛过程中，斯皮德结识了神秘赛车手莱瑟X（马修·福克斯 Matthew Fox 饰），以及同样为对抗罗伊尔顿的亚洲车手天速（郑智薰 饰）。在他们的帮助下，斯皮德开始接受这个可能会通向死亡的赛道的考验。在寻找哥哥死亡真相的过程中，斯皮德发现了让家人相当震惊的事实……','Go!',120000000,93945766,17.060695,5.7,354,135,'2008-05-09','en','/gVAzNbt5WnS7b8h4I1GSzETCgJO.jpg',3.1073845299667666,3,'2026-09-10',2,NULL,NULL),(7461,'刺杀据点','Vantage Point','为了应对911之后日益猖獗的恐怖主义，美国总统亨利·阿什顿与西方各国以及阿拉伯国家首脑相约西班牙的萨拉曼卡，将在此缔结全新的反恐同盟。是日阳光明媚，广场人头攒动，不同社会背景之人齐齐聚集，嘈杂万分。阿什顿总统的车队在一片欢呼和反对声中到来，六个月前为保护总统而遭到枪击的资深探员托马斯·巴恩斯冲在最前方，警觉地监视着来自周遭一切可疑之人。谁知，当总统正准备发表演说时，两发子弹击中了他。广场顿时大乱，有人仓皇而逃，有人冲向主席台，有人则趁乱制造祸端。随之而来的爆炸将这美好的一日彻底毁灭。通过电视台女导播、阿什顿总统、巴恩斯以及几名和此事件有关之人的视角，血腥一日背后的真相逐步得到还原……','8 Strangers, 8 points of view.  1 Truth.',40000000,151161491,24.862767,6.2,716,90,'2008-02-01','en','/9E3kbn7Vs2TCsHDDTwe5tXCST9W.jpg',3.331329412037905,3,'2026-09-10',2,NULL,NULL),(7484,'丛林大反攻','Open Season','棕熊布哥是个幸运儿，他被收养者宠得一塌糊涂，生活安逸舒适。然而现在他却被放归森林，对大自然的艰苦极不习惯的布哥一心想回城，黑尾鹿艾略特的出现却改变了他的计划。艾略特被猎人撞断了一只角，绑在车中运往镇里。布哥犹豫再三，终于救走了艾略特。这个决定让布哥再不能顺利的回到以前的生活。  　　艾略特拜恩人布哥为兄弟，跟着布哥一起前行，并且引诱他来到野丛林好好“享受”。布哥来到丛林，才发现这里的条件太恶劣了，根本不像城里舒服。而且，他们还犯了一个错误，让动物们陷入狩猎区当中，重重危险面前，布哥的野性被逐渐唤醒，他和动物们组成兵团抗击敌人，上演一场轰烈的家园保卫战。','One Fur All & All Fur One',85000000,197309027,26.61951,6.1,656,83,'2006-09-29','en','/w5Lctmkc1yah215Luxmci4djaiW.jpg',3.3015770196176635,3,'2026-09-10',2,NULL,NULL),(7485,'生死狙击','Shooter','在美国军队中服役多年，且在战场上有过优异表现的狙击手鲍勃·李·斯瓦格（马克·沃尔伯格）在执行某次任务中，完成任务后被所在部队的军官抛弃，导致其观察员兼好友的队友牺牲，这位前陆战队优秀的狙击手(在复仇后)心灰意冷。于是，斯瓦格在坚持到退伍之后便带着自己那条忠实的爱犬一同来到了偏僻的阿肯色州。开始过上自己向往已久的平静日子。然而，斯瓦格幸福的宁静生活并未持续多久，便被无情地打破了。一个不明真身的上校带着一队人找上门来。希望，凭借他多年的狙击经验，在总统举行街头演讲的时候出手相助，在暗处为总统担任保镖。因为，政府方面此前收到消息称有恐怖分子或者杀手将会有所行动，对总统的人身安全不利。具有极强爱国主义精神的斯瓦格经不起这名上校地“真情”劝说，便应允接受了这一任务。到了总统演讲那天，斯瓦格站在演讲台对面的大楼里监视着。突然间，身后的警察突然对他开始攻击，同时总统的身边的埃塞俄比亚大主教中枪倒地。可怜的斯瓦格就这样稀里糊涂地被当作刺杀总统的疑犯通缉。还好斯瓦格身手敏捷，身中两枪跌出窗外，凭借着之前自己在地形观察时得到的对当地（费城）街道的粗略了解，斯瓦格逃离现场。仔细的思考过后，斯瓦格方才清醒，原来自己从一开始便被人陷害成替罪羊。于是，斯瓦格拼命展开调查，追逐真凶，亲手为自己洗脱罪责。','Yesterday was about honor. Today is about justice.',61000000,95696996,37.378081,6.9,1462,124,'2007-03-22','en','/udsAccHnLBkwB14L2Kb39T7Enz3.jpg',3.6594465905432485,3,'2026-09-10',2,NULL,NULL),(7501,'黑帮第二代','Knockaround Guys','麦蒂（巴里·佩珀 Barry Pepper 饰）的父亲本尼（丹尼斯·霍珀 Dennis Hopper 饰）是能够一手遮天的纽约黑帮老大，本尼希望麦蒂能够子承父业，将黑帮发展成为一种家庭文化，无奈麦蒂生来软弱胆小，就连加入黑帮的最基本测试——杀一个人都无法通过，无奈，他只得将儿子放回社会，去做一个普通人。\r 可是，麦蒂很快就发现，由于父亲的“名声”，靠自己单枪匹马的力量根本无法再社会上生存下去，走投无路的他只得重新回到了本尼的身边。本尼交给了麦蒂一个“安全”的任务——运送一笔黑钱，踌躇满志的麦蒂决定绝不辜负父亲的期望，他找到了好友强尼（赛斯·格林 Seth Green 饰）、斯卡帕（Andrew Davoli 饰）和泰勒（范·迪塞尔 Vin Diesel 饰）助自己一臂之力。','If they don\'t finish the job, their fathers will finish them.',15000000,12000000,8.113634,5.9,97,92,'2001-09-07','en','/oYqsIxxIfJMRHiNEMLzgG81brkY.jpg',2.8404332076682777,3,'2026-09-10',2,NULL,NULL),(7504,'大地','1947: Earth','1947Earth是1999年上映的，曾获当年奥斯卡最佳外国语电影提名。故事讲述‘一个以浸满印巴分裂鲜血的画布为背景的史诗般的爱情’(An epic romance set against the bloodstained canvas of patition).。导演为一位著名的印度女导演。故事主人公有三位，一个印度教女子和两个穆斯林男子。故事发生在分裂前的拉合尔，印度教女子和两个穆斯林男子是好朋友，和其中一个叫哈桑的关系更为密切。当分治的暴乱高涨时，两个男子都向印度教女子求婚，哈桑更对女子说：‘嫁给我吧，我是穆斯林那又怎样呢？我和你一起去德里，我也作印度教徒吧’。女子很感到，答应了他的求婚并和他发生了关系。不过这一切都被来找少女的另一个穆斯林男子(阿米尔汗扮演)看到了。第二天，人们在马路旁发现了哈桑的尸体，他的喉咙被割断，而阿米尔也率众从帕西人家中抢走了印度教女子。',NULL,0,528972,1.246883,6.6,9,101,'1998-09-16','hi','/hQtvQYlxfEHl45TR41lNSywrq4K.jpg',2.3384150304757507,3,'2026-09-10',2,NULL,NULL),(7509,'水','Water','20世纪30年代的印度，妇女没有人权和自由，她们不过是作为男性的附庸而存在。8岁的小女孩楚娅（Sarala 饰）早早变成了寡妇，她只能被迫剃掉头发，在一个专门为寡妇准备的庭院中度过余下的漫长人生。在这个院子里，生活着恍如天上仙子的年轻女性，也有黄土半埋的枯槁老人，更有处心积虑赚取不义之财的刁蛮之妇。  　　楚娅的明天会怎样？苦命女人的未来又将如何？  　　本片为印度女导演迪帕•梅赫塔（Deepa Mehta）“要素三部曲”的第三部，分别荣获2006年曼谷国际电影节最佳影片；2006年加拿大吉尼金像奖最佳摄影、最佳配乐和最佳女主角（Seema Biswas）三项大奖；2006年美国国家影评奖最佳表现奖；2005年瓦雅多丽国际电影节青年评委会大奖；2006年温哥华影评人协会奖最佳女主角（Lisa Ray）和最佳导演奖；2007年青年艺术家奖最佳青年演员奖（Sarala）。 ©豆瓣',NULL,0,10422387,2.787375,6.8,34,115,'2005-09-08','en','/tdg6JKcqjS7szenmabGAbe5RGdN.jpg',2.621379437433399,3,'2026-09-10',2,NULL,NULL),(7510,'夹缝求生','Running with Scissors','6岁的奥古斯丁（约瑟夫·克罗斯 Joseph Cross 饰）是一个早熟的孩子，在他充满了童稚的目光里，原本应该幸福美满的家庭早已分崩离析。身为奥古斯丁的母亲，迪尔丽德（安妮特·贝宁 Annette Bening 饰）并没有将儿子的需求放在第一位，在她的眼中，自己诗人的身份和在诗坛的地位是最重要的，可实际上，甚至没有人听闻过“诗人”迪尔丽德的大名。自己的妻子整天神神叨叨，无计可施的诺曼（亚历克·鲍德温 Alec Baldwin 饰）选择了无视，失意的他只能向酒精寻求安慰。  精神医生芬奇（布莱恩·考克斯 Brian Cox 饰）的到来将这个家的问题推向了新的层面，本来意在修复家庭裂痕的他居然成为了导致离婚的罪魁祸首。更令奥古斯丁感到头痛的是，母亲竟然将自己托付给了这个疯疯癫癫的蒙古大夫。','Ever have one of those lives?',12000000,6754898,4.770195,5.8,78,116,'2006-10-27','en','/pbWUFYyyZzawsYljkbIKmDxQN8Y.jpg',2.7844211238735794,3,'2026-09-10',2,NULL,NULL),(7512,'蠢蛋进化论','Idiocracy','研究者对同年龄组的两个家庭做了跟踪调查：一对是IQ为130的天才组合，夫妻和睦，但是无嗣，正当两人准备作试管婴儿之时，男主人却在自慰中意外死亡；另一个家庭，都是IQ 80的低能夫妻，天天吵架，不过却人丁兴旺，不仅三代同堂，而且家族甚大。根据这个调查，研究者选择了一个自愿者鲍尔斯（卢克•威尔逊 Luke Wilson 饰）做冷冻实验，不想实验除了差错，500年后他醒来后，却成为地球上最聪明的人。他被盲打误撞地选做了总统的候选人，支持他的甚至还有5届自由搏击冠军。在盛大的竞选现场，他只能硬着头皮面对选民演说，对于目前的种植、沙尘暴等问题，他提出的是灌溉这一看似离谱的解决办法。而且，还得到了选民的拥护，然而这个美梦迅速破灭了，他开始遭到谩骂、攻击，甚至是性命堪忧……','In the future, intelligence is extinct.',30000000,495303,27.940093,6.3,664,84,'2006-09-01','en','/iHpv98lZFRz1iaCLpHRXYuZ4sPl.jpg',3.3358220383769277,3,'2026-09-10',2,NULL,NULL),(7515,'伦敦','London','伦敦在本片并非指英国的首都，而是一个女人，一个非常辣的女人。可以理解的是，虽然西德仍然深爱着伦敦，但是他和伦敦之间暴风雨般热烈的关系已经结束，成为了一个彻底的破坏者。当西德正在毒品和酒精中迷失自己的时候，他受到了更加强烈的刺激。伦敦即将和她的新欢去渡蜜月，西德疯狂了，他取消了城市的聚会，并想尽一切办法要阻止他的前爱离开这个小镇，不论要付出多大的代价。','One young man\'s incredible journey of self-discovery',0,0,5.350423,6.1,96,92,'2005-02-10','en','/zvNHklUZcrwdN8xpL7Vsqedru5l.jpg',2.838949235247563,3,'2026-09-10',2,NULL,NULL),(7516,'五路追杀令','Smokin\' Aces','美国最大黑手党犯罪集团科萨·诺斯特拉横行无忌，连一向风行雷厉的联邦调查局也拿它们没辙。但最近曾加入过团伙的三流魔术师巴蒂“艾斯”以色瑞尔，为了自保，终于同意提供所有的犯罪证据，这无疑是扳倒帮派大佬普莱默的最好机会。但大佬普莱默岂是吃素的主，他马上出重金悬赏艾斯的脑袋，决意让艾斯永远消失。 100万美金的开价在黑帮内外传出，埃斯的那颗原本不值钱的脑袋也成了众家的热门目标。重金很快吸引了赏金猎手、退隐江湖的老手、想进入黑帮内线的混混、杀手级别的辣妹甚至双面黑帮人士的眼光。而FBI也害怕自己指证黑手党的唯一王牌艾斯遭到不测，派出两名特工负责保护，希望赶在杀手之前一步。 偏偏这艾斯，还在风光宜人的内华达州塔霍湖风流快活。身处风景胜地，作为污点证人接受监管，住在豪华饭店，还沾染着毒品和妓女，要想躲过视野开阔的湖畔虎视眈眈的狠家伙们，可不是件容易的差事。而那些或职业或非专业的杀手们，都有着自己的盘算，这块可口的大蛋糕，到底怎么才分得匀？','Nobody gets away clean.',17000000,57103895,23.491962,6.4,534,109,'2006-12-09','en','/zJ8oRyQ6PsZd5m1xXnpIxHoZPM5.jpg',3.2880890416210113,3,'2026-09-10',2,NULL,NULL),(7518,'Over the Hedge','Over the Hedge','A scheming raccoon fools a mismatched family of forest creatures into helping him repay a debt of food, by invading the new suburban sprawl that popped up while they were hibernating – and learns a lesson about family himself.','Taking back the neighborhood... One snack at a time.',80000000,343397247,36.32705,6.3,1074,83,'2006-04-22','en','/fGeNUyDXZrALReYPNSO6ezLrB9v.jpg',3.465962695697373,3,'2026-09-10',2,NULL,NULL),(7547,'Come Early Morning','Come Early Morning','Lucy wakes up in bed with a stranger and obviously from a night of drinking. She checks out and pays for the motel room on her account. Through her grandmother, she finds out her father is in town and pays him a visit. She agrees to go to his new church.','Before you fall in love, you need to love yourself.',6000000,0,3.427061,5.9,10,97,'2006-01-10','en','/5faIZQlDLIKEH8zLBf1oKrbHIXv.jpg',2.361443053361373,3,'2026-09-10',2,NULL,NULL),(7548,'浪荡子','The Libertine','故事发生在17世纪的英国，诗人约翰·威尔默特（约翰尼·德普 Johnny Depp 饰）以其满溢的才华和不羁的性格成为查尔斯二世（约翰·马尔科维奇 John Malkovich 饰）的宠臣。他古怪的行事风格遭人非议，还时常大写淫秽诗篇讽刺贵族的淫乱生活，他天生不羁蔑视社会伦理，结识了特立独行的女演员伊丽莎白·巴里（萨曼莎·莫顿 Samantha Morton 饰）坠入爱河，又和男演员道恩斯（鲁珀特·佛兰德 Rupert Friend 饰）发生暧昧关系。但长期纵欲和酗酒，加之触怒皇室被多次流放，过度燃烧了诗人的生命，他开始饱受失明、关节炎、臆想症的困扰，最终证实身患梅毒，在33岁时黯然逝去。','He didn\'t resist temptation. He pursued it.',0,0,7.588597,5.9,128,114,'2004-09-16','en','/11bd8chDHTPWUaUwIYIVIfwS99u.jpg',2.8968783292323437,3,'2026-09-10',2,NULL,NULL),(7552,'新抢钱夫妻','Fun with Dick and Jane','一间大公司的小职员迪克（金•凯瑞 Jim Carrey 饰）终于时来运转，被总裁杰克提拔当上了副总裁。终于出人投地的迪克尽情享受着生活，妻子简（蒂娅•里欧妮 Tea Leoni 饰）也辞去了工作在家当起了全职主妇。岂料，迪克只是公司的牺牲品，不久公司就传出财务丑闻，总裁杰克也携巨款潜逃。  由于迪克的所有积蓄之前都买了公司的股票，这下，他刹那间就变得一文不值。生活逼人，迪克和简铤而走险当起了“雌雄大盗”。迪克和简有时会打劫咖啡店，只为了两杯咖啡和两块点心；晚上迪克也会跑去每个邻居的院子偷一小块草皮然后铺到自己的院子，夫妻俩的生活虽然贫困却也洋溢着幸福。这天，迪克和简决定向侵吞了巨款的杰克下手。事情有没有他们设想的简单？','Giving big businesses a run for their money!',100000000,202026112,25.159168,5.9,627,90,'2005-12-21','en','/uq4prE1CxkFNkU14yW0WXgjunKJ.jpg',3.2607260059488397,3,'2026-09-10',2,NULL,NULL),(7553,'哈啦上菜','Waiting...','迪安（贾斯汀·朗 Justin Long 饰）是一名餐厅服务员，对于这份职业，迪安十分喜爱，高涨的热情和强烈的责任感让他在顾客中享有良好的口碑，这是迪安引以为豪的所在。没想到，一次同学会彻底改变了迪安的想法，迪安发现，和同学们的功成名就比起来，自己的安于现状是多么的可耻。  整天无所事事四处勾搭的同时莫迪（瑞安·雷诺兹 Ryan Reynolds 饰），个性强势粗暴的前女友塞丽娜（安娜·法瑞丝 Anna Faris 饰），脾气古怪的餐厅老板丹（大卫·科恩查内 David Koechner 饰），当思想上产生了动摇的迪安再次环顾这些围绕在自己身边的怪咖时，他觉得自己在潜移默化中很可能成为他们的接班人，改变现状成为了当务之急。\"','What happens in the kitchen ends up on the plate.',3000000,18637690,10.230583,6.2,237,94,'2005-10-07','en','/h3NJDiaaliUH35ApXPu8PFKZwWz.jpg',3.051875595715343,3,'2026-09-10',2,NULL,NULL),(7735,'浪潮','Die Welle','赖纳•文格尔 是德国某所高中的老师，该学校正在进行“国家体制”的主题活动周。由于他最喜欢的“无政府主义”课被另一位老师捷足先登，因此他只能主讲“独裁统治”课程。 对于自由散漫的学生们来说，任何课程都只是为了学分而上。他们在课上大声聊天，无心听讲。文格尔别出心裁提出假想“独裁”的实验。在为期一周的实验中，文格尔被置于至高无上的地位，学生们对他要绝对服从。从最初的玩乐心态，这些青年男女渐渐沉湎这个名为“浪潮”的组织中，他们体会到集体和纪律的重要性，却在不知不觉中滑向了“独裁”与“纳粹”的深渊……','Evil is something that you learn',7500000,19000000,25.281197,7.5,841,107,'2008-03-11','de','/okD4ZJlmySKI0SBHGFLs0QX4Ief.jpg',3.5772213670435744,3,'2026-09-10',2,NULL,NULL),(7737,'生化危机3：灭绝','Resident Evil: Extinction','爱丽丝（米拉·乔沃维奇 Milla Jovovich 饰）被保护伞公司实验室复制，成了伊萨克博士（伊恩·格雷 Iain Glen 饰）的研究标本。因为她体内的DNA可以对抗T-病毒，所以博士以此来提升丧尸的杀伤力。爱丽丝接到了人类的求救信号，但却中了奸计，几经拼杀，方才自救。她如释重负，然而在睡梦中，她却强烈地感受体内强大力量的召唤，显然保护伞公司实验室对她做了手脚。而且，伊萨克博士还给僵尸注入了人类血液，激活其人类的心智。僵尸变得更强大，根本无法被控制，他们残忍地杀害了实验室助手，被训练对付爱丽丝。3年后，地球成了不毛之地。内华达州的幸存者结成了同盟，爱丽丝也在其中，但是她不敢表露身份，因为实验室给了她超能力，同时也让她被迫做了间谍。爱丽丝被孤立，只有卡洛斯懂得她的苦衷，二人也因此陷入了暧昧之中……','The Extinction Is Coming...',45000000,148412065,12.06538,6.1,1292,94,'2007-09-20','en','/aY3N12d6Ga4VsZnxZeSjntai9VL.jpg',3.4147226366362036,3,'2026-09-10',2,NULL,NULL),(7859,'半个尼尔森','Half Nelson','丹是一位充满理想的市中心初中教师，却染有毒瘾；德雷则是他一名陷入困境的学生。两人意外建立起一段特殊的友谊，这段关系既可能毁掉他们，也可能为他们提供突破生活困境所需的关键转变。[ThinkFilm]','Secrets don\'t let go.',700000,4911725,12.378031,6.5,240,107,'2006-08-11','en','/b4LIJS0yprkSmuOCoz3a0zpOxpY.jpg',3.0818662445601857,3,'2026-09-10',2,NULL,NULL),(7863,'闪亮的风采','Shine','本片灵感源于古典钢琴家戴维·赫尔夫戈特坎坷而最终辉煌的人生，聚焦于他在二十岁出头、即将登上国际舞台之际，痛苦地退缩进自我封闭世界的经历。影片时间跨度从1950年代至1980年代，戏剧化地呈现了赫尔夫戈特在沉寂十年后，通过一位非凡女性的爱与支持，重新实现个人与事业双重圆满的动人历程。[Fine Line Features]','A true story of the mystery of music and the miracle of love',0,0,10.396305,7.3,131,105,'1996-01-21','en','/cbmThowj2XAW7lKlMAXmnhZvjGI.jpg',2.9721135763640465,3,'2026-09-10',2,NULL,NULL),(7870,'流入山谷','Down in the Valley','在油站打工的小伙子哈兰（爱德华·诺顿 Edward Norton 饰）有着很深的牛仔情结。他一身牛仔装，常常学牛仔拔枪的“神勇”模样。尽管很多人都嘲笑他，但少女托博（埃文·蕾切尔·伍德 Evan Rachel Wood 饰）却似乎和他意趣相投，二人堕入爱海。  　　哈兰跟随托博来到小镇的家中，这里住住托博的父亲韦德（大卫·摩斯 David Morse 饰）和弟弟罗尼（罗瑞·库尔金 Rory Culkin 饰）。韦德专横强硬，弟弟一直都在父亲的压抑下成长，个性敏感内向。常常一起外出骑马射枪的哈兰，成为了罗尼的精神依托。慢慢的，罗尼爱上了这个牛仔。  　　随着父亲对哈兰强硬的排斥、以及哈兰神秘身份的渐渐崭露，这个家庭的矛盾一再升级，直到悲剧的一发不可收拾。','Sometimes it\'s hard to find your way.',8000000,852872,7.433574,5.9,63,112,'2005-05-13','en','/qgyp48naq0W7j4NbOttFi91DlYW.jpg',2.748774867632614,3,'2026-09-10',2,NULL,NULL),(7873,'非常时期','Harsh Times','克里斯蒂安·贝尔扮演的海豹突击队退役军人和弗雷迪·罗德里格斯扮演的无业青年是一对挚友，两人每日无所事事只是无止境地酗酒、飙车、吸毒，两人就在为前途和爱人寻找方向的时候产生了无法消弭的分歧，最终惨剧发生。','Take A Ride To The Edge',2000000,5967038,12.999023,6.3,197,120,'2005-09-11','en','/raBWBnGz2X6FQ3iUwPwYQE4FrkY.jpg',3.0237745714597963,3,'2026-09-10',2,NULL,NULL),(7874,'黑蛇呻吟','Black Snake Moan','天生丽质的白人少女莱伊(克里斯蒂娜·瑞茜)在经历了小时候的厄运之后便完全成了另一个人。被恶人无情地性侵犯使得莱伊在长大后罹患了比性冷感更可怕的精神隐疾——一个慕男成狂的花痴。平日里，附近的或者路过此地的男人们只知道她性感撩人的外表，却不知道她在每次卖弄风骚时痛苦的内心在经受着怎样的煎熬。黑人布鲁斯乐手拉扎鲁斯(塞缪尔·杰克逊)一天在夜里发现了流连街头的莱伊。在得知她不得已的放荡缘由之后，决定将这个可怜的女人带回家，因为拉扎鲁斯深知，莱伊的病不但会影响到他人的生活，更会给她自己引来更多的危险。在拉扎鲁斯自己的小屋里，布鲁斯乐手为这个“后天花痴”做了精心的治疗，每日看守、照顾她，帮助她解开心魔。同时，还要时刻提防她畸形的性欲随时爆发，又跑出去招惹麻烦……','To save his soul he must save hers.',15000000,10903846,11.429607,6.6,243,116,'2006-12-08','en','/8Yv7kxsqXSe4ZHl8uJEhmsPjhAP.jpg',3.0901606083002577,3,'2026-09-10',2,NULL,NULL),(7913,'芭萨提的颜色','रंग दे बसंती','影片中的英国女电影人苏，乃由末任香港总督彭定康幼女彭雅思饰演。 镇压过印度革命者的英国警官被革命者视死如归的气概所感动，留下了一本记录当时情况的日记。多年后，他的孙女Sue（彭雅思 Alice Patten 饰）阅读日记后深受感动，凭着一腔热血辞掉电影公司的工作，来到印度拍摄这部记录那段历史的影片。Sue到德里大学的学生中选角。一群充满朝气却和芸芸大众一样对印度这个国家心如死灰的年轻人以及进入她的视野。开始的拍摄，麻醉于醉生梦死的的学生，对于当年那些为国捐躯的革命者的行为根本没法理解，致使迟迟不能进入角色。灾祸横至，国防部长的腐败导致朋友们中的飞行员Ajay（马德哈万 Madhavan 饰）遭遇了空难。Ajay为了防止平民受伤而献出了自己的生命，却因为政府高层的反唇覆舌而死后名誉受损。元凶逍遥法外。小伙子们恍然感觉到，自己体内的热血开始为枉死的朋友，为多难的祖国而沸腾。','A Generation Awakens',2200000,11502151,5.206967,7.2,97,157,'2006-01-26','hi',NULL,2.8796244452766424,3,'2026-09-10',2,NULL,NULL),(7942,'Run, Fatboy, Run','Run Fatboy Run','Five years after jilting his pregnant fiancée on their wedding day, out-of-shape Dennis decides to run a marathon to win her back.','Love. Commitment. Responsibility. There\'s nothing he won\'t run away from.',10000000,33000000,14.905357,6.2,238,100,'2007-09-06','en','/sGYP9dFSoUAuHJlR7PERpdPAXC3.jpg',3.06348464006571,3,'2026-09-10',2,NULL,NULL),(7944,'闪耀光芒','Shine a Light','《闪耀光芒》是马丁·斯科塞斯执导的滚石乐队演唱会纪录片，拍摄于2006年秋在纽约比肯剧院为期两天的演出。影片通过多机位拍摄，生动呈现这支传奇乐队的现场原始能量与舞台魅力。','A master director shining his light on the best rock band on the planet.',0,0,2.162522,7.2,44,122,'2008-02-07','en','/rMVrNWWaO3xAWZHFUbeamWPzVAC.jpg',2.6839106224403104,3,'2026-09-10',2,NULL,NULL),(7973,'焦糖','سكر بنات','故事发生在黎巴嫩的一家美容院，围绕着五名女性的日常生活展开。拉亚里（纳迪·拉巴基 Nadine Labaki 饰）、尼斯瑞和瑞玛在同一家美容院工作，詹美尔则是她们的常客，而美容院附近的一名女裁缝师罗丝和她年老的痴呆的姐姐莉莉一起住。她们年龄不同，性格不同，人生际遇不同，她们有各自独特的故事。 拉亚里因爱上了一个有妇之夫而陷入困苦，而且不得不面对他不知情的妻子；尼斯瑞婚礼在即，却决定到医院做个处女膜修复手术；瑞玛是个女同性恋，对一个美貌的顾客颇有好感；曾经是演员的詹美尔难以接受自己一日一日的衰老；而年老的罗丝因为要照顾姐姐而放弃爱情。一段段故事交织在一起，像焦糖一样，既甜蜜缠绵，又丝丝苦涩…',NULL,0,0,4.554574,6.8,52,96,'2007-07-01','ar',NULL,2.7200641229755806,3,'2026-09-10',2,NULL,NULL),(7978,'狼人','The Wolfman','惊悚片《狼人》翻拍自环球影业1941年的同名恐怖片。影片由奥斯卡最佳男配角本尼西奥·德托罗（Benicio Del Toro）和安东尼·霍普金斯（Anthony Hopkins）联合担正，曾执导过《侏罗纪公园3》的乔·约翰斯顿则肩负起将这一经典角色带回银幕的重任。与由朗·钱尼主演的版本相同，新版《狼人》的故事背景仍定在维多莉亚时代的英国，故事讲述德托罗扮演的主人公从美国回到他祖先的故乡，却不慎被狼人咬伤，从此一到月圆之夜便幻化成毛茸茸的狼人。','When the moon is full the legend comes to life',150000000,0,21.214571,5.5,549,102,'2010-02-11','en','/9Vu1iV0UMF3lg8m2hyQNywrgWyt.jpg',3.173438009452032,3,'2026-09-10',2,NULL,NULL),(7979,'追风筝的人','The Kite Runner','荒凉贫瘠的西亚国家阿富汗，多年来一直饱受着穷困和落后的折磨。但生活在这里的人们却也同样享受着亲情、友情、成长……代给他们的乐趣。富家子阿米尔和他的小仆人哈桑就是一对亲密无间的小伙伴。无论是荒凉的戈壁、突兀的山丘、一眼忘到边的枯树林、繁华的街市……到处都是他们勾肩搭背、打闹玩耍的好地方。如今，喀布尔一年一度的风筝大会再次到来。阿米尔和哈桑各自带着自己的满意之作踊跃参加。令两个天真无邪的小孩子万万没想到的是，这次本来可以为他们的幸福童年再次增添快乐的风筝大会却成了改变两颗幼小心灵一生的梦魇。幸运的阿米尔在仆人哈桑千方百计的帮助下赢得了风筝大赛的殊荣，而倒霉的哈桑却被恶人强暴。胆小懦弱的阿米尔惊吓之余却不敢相助。两个好伙伴天真烂漫的友情就在这样尴尬甚至可悲的情形下，被突如其来的“苏阿战争”所打破。为了躲避战乱，阿米尔的父亲携家产举家移民美国。在条件优异美国，学习上进的阿米尔渐渐成了学校里的优秀生，并最终以优异的成绩毕业成为父亲心中的骄傲。但在阿米尔的内心深处，对儿时伙伴哈桑的愧疚感却无法用任何美好的事物抹去。突然有一天，父亲朋友的一个电话终于给了阿米尔重返故土向小伙伴赎罪的机会和勇气。原来，贫困的哈桑一家多年来一直在饱受战乱之苦的阿富汗山区苦苦煎熬着。而为了保护阿米尔家在喀布尔的房产，忠诚的哈桑一家惨遭凶残的塔利班恐怖组织荼毒。幸存下来的哈桑之子则落到了塔利班恐怖分子手中。为了隐藏二十年的赎罪、为了少年时的真挚友情，阿米尔决定重回荒凉的西亚戈壁，想尽一切办法也要将哈桑的儿子从虎口中营救出来……','There is a way to be good again.',20000000,73276047,10.446722,7.3,394,128,'2007-10-14','en','/1azPp2JFcBAgrVZWOhRw0fA1kzH.jpg',3.2809842336663344,3,'2026-09-10',2,NULL,NULL),(7980,'可爱的骨头','The Lovely Bones','14岁的小女孩苏西（西尔莎·罗南 Saoirse Ronan 饰）生性活泼、古灵精怪，父亲（马克·沃尔伯格 Mark Wahlberg 饰）是一个模型爱好者，母亲（蕾切尔·薇姿 Rachel Weisz 饰）是循规蹈矩的传统女性，妹妹大胆，弟弟弱小。生日时，她收获了一部相机，从此爱上了拍照，甚至在一个月间用光了24卷胶卷，令父母十分挠头。一次，全家在逛超市的时候，她偷偷望着橱窗外的男孩发呆。祖母（苏珊·萨兰登 Susan Sarandon 饰）看穿了苏西的心事，那个英俊的英国学长便是她的暗恋对象。然而，还没等两个人吐露心事，苏西却落入了坏人设下的陷阱。那个色眯眯的邻居哈维，用花言巧语引诱苏西，骗她走入其事先设好的圈套……本片根据艾丽斯·西伯德的畅销小说改编而成，以苏西的视角、倒叙的方式，讲述了一个魔幻主义的犯罪故事。','The story of a life and everything that came after...',65000000,93525586,29.257137,6.6,1065,136,'2009-12-26','en','/fEaHcZcLS9D221NfVUGomZiP2px.jpg',3.501319042204771,3,'2026-09-10',2,NULL,NULL),(8007,'深入敌后','Behind Enemy Lines','圣诞节前夕，波斯尼亚战争终于达成停火协议，亚得里亚海上的美军官兵们即将返回家乡。海军领航员伯纳中尉（Owen Wilson 饰）早已厌倦这场无意义的战争，长官莱斯利（Gene Hackman 饰）出面劝解却无济于事。圣诞当天，伯纳与搭档驾驶大黄蜂战机执行航拍任务，无意中瞥见非安全区中有武装人员行动，两人决定介入，却被对方的萨姆导弹击落，搭档被对方处死，伯纳侥幸脱险，但对方搜寻人员沿路追踪不舍。与此同时，接到伯纳求救信息的莱斯利苦于北约将军节制，在所谓顾全大局的考虑下无法介入非安全区搭救伯纳，莱斯利只好借助媒体力量甚至不惜盗用盟友设备，展开了一场对落入敌后下属的拯救行动。','His only weapon is his will to survive.',40000000,91753202,24.012986,6,457,106,'2001-11-17','en','/fA40j3HucjbpORWjqWkfHVycc2Y.jpg',3.20604192737909,3,'2026-09-10',2,NULL,NULL),(8009,'高地人','Highlander','一九八六年，曼克顿市地下停车场里，两人正在作一场生死战，但竟然在二十世纪里还有人使用古代武器比武……这故事追溯至一五三六年，一位苏格兰籍农夫在一之战争中受了伤，但他的伤口竟不药而愈。他发现自己拥有一具不死之身，只有他的头被斩下才会死亡！在另一方面，一位西班牙贵族亦拥有不死异能，他为了令自己成为最终霸主，不惜花上四百年的时间去追寻另一个不死人，跟他决一死战……','There can be only one.',16000000,5900000,29.253833,6.8,624,116,'1986-03-07','en','/iRa4Pokb2nyzBkYOgP0sTsmOFbu.jpg',3.3936909780224025,3,'2026-09-10',2,NULL,NULL),(8011,'高地人3：终极次元','Highlander III: The Sorcerer','第三部电影是在1994年拍摄的，这意味着它是第二部电影的前传。几个世纪前，他深爱的妻子希瑟去世后，康纳·麦克劳德离开苏格兰高地，在世界各地流浪。最后，他到达了日本，在那里他遇见了著名的巫师中野，他也是一名仙人。不久，他们成为了朋友，中野教授了一些技巧。但有一天，一个宿敌，凯恩来到日本，他愿意找到中野的洞穴并杀死他。虽然他成功了，但在切断了中野的头颅后，山塌了，凯恩被困住了。现在，几个世纪过去了，一场挖掘揭示了这一点。','Throughout time they have hunted each other fulfilling the prophecy, that there can be only one.',26000000,36800000,7.964451,4.5,110,99,'1994-11-29','en','/o4GKLReSGRR0rulOBS9SrfFAXOz.jpg',2.8111651909158595,3,'2026-09-10',2,NULL,NULL),(8012,'矮子当道','Get Shorty','迈阿密放贷人奇利·帕尔默被派往洛杉矶，向电影制片人哈里·齐姆追讨赌债。奇利很快发现，放贷生涯简直是进军电影圈的完美训练营……尽管想在好莱坞混出名堂，同样需要心狠手辣。[米高梅]','The mob is tough, but it’s nothing like show business.',30250000,115101622,15.585138,6.4,302,105,'1995-10-20','en','/7knssyntbpH143PrVFGOQ59ZsUz.jpg',3.135372002745858,3,'2026-09-10',2,NULL,NULL),(8046,'鸳鸯绑匪','Gigli','拉瑞（本·阿弗莱克 Ben Affleck 饰）看起来人高马大仪表堂堂，却是一个整日里不务正业游手好闲的小马仔。某天，老大交给了他一项十分重要的任务——绑架一位名叫布莱恩（贾斯汀·巴萨 Justin Bartha 饰）的男子，他是当地检察官的弟弟，而该检察官手上掌握着能够将老大送进监狱的证据。\r 为了确保行动的顺利进行，老大还派出了性感火辣的瑞琪（詹妮弗·洛佩兹 Jennifer Lopez 饰）和拉瑞一起上路，毫不意外的，无法抵挡瑞琪强大魅力的拉瑞深深的坠入了情网之中，无奈在瑞琪的眼中，拉瑞只是一个笨蛋小混混而已。这一节外生枝让整个计划都充满了不确定性，在拉瑞的莽撞下，瑞琪甚至有可能被连累的丢掉性命。 ©豆瓣','Life doesn\'t play by the rules.',54000000,7266209,9.053456,3.5,104,121,'2003-08-01','en','/qOhAK3WDqdeVTIE59loXvEGU7Lu.jpg',2.767134764951175,3,'2026-09-10',2,NULL,NULL),(8051,'私恋失调','Punch-Drunk Love','单身汉Barry Egan（亚当·桑德勒 Adam Sandler 饰）经营着一家小工厂，生活在七个姐姐压力下的他会不时地哭泣、用暴力来发泄情绪，乱砸东西。这天他在路上捡回了一个被人丢弃的小钢琴，还认识了一个女子。原来这个女子正是他的一个姐姐想要介绍给他认识的Lena Leonard（艾米丽·沃森 Emily Watson 饰），两人相约改天一起吃晚餐。夜里寂寞无聊的Barry拨打了一个色情电话，和电话里的女郎聊的不亦乐乎，却也惹上了麻烦：女郎付不起房租跟他借钱被拒绝后，便不断打电话骚扰他。Barry和Lena第一次约会后，两人情投意合。然而当Barry回到家的时候，却遭到了一伙人的打劫，原来是经营色情电话公司的Dean（菲利普·塞默·霍夫曼 Philip Seymour Hoffman 饰）派来的。当Lena在夏威夷出差的时候，Barry更破天荒地去夏威夷寻找她，两人确立了恋爱关系。当那伙人再次开车撞了Barry的车时，Lena受伤了，Barry终于爆发了......',NULL,25000000,17000000,15.960916,6.9,530,95,'2002-10-25','en','/htYp4yqFu4rzBEIa6j9jP8miDm3.jpg',3.3322728285176857,3,'2026-09-10',2,NULL,NULL),(8053,'艾斯卡达的三次葬礼','The Three Burials of Melquiades Estrada','美国德州与墨西哥接壤的边陲小镇，这里向来就是是非之地，因为这里充斥着从墨西哥进入美国非法的入境者，毒品、枪支也在这里泛滥。艾斯卡达是从墨西哥来的移民，在当地一家农场当牛仔，正直善良的他很快和农场管家皮特成了好朋友。岂料这天艾斯卡达失踪了，很快他的尸体被发现了，当地的警察把他葬在了当地。因为艾斯卡特生前曾托付皮特如果他死于他乡一定要将他的尸体运回故里安葬，所以皮特开始了他生平最大的一次冒险。一方面，他誓要找出杀害好友的真凶；另一方面，他要触犯当地法律千里运尸。','Nobody is beyond redemption.',15000000,12036149,12.163832,7,177,121,'2005-11-17','en','/uHOEb6mo45qMSJaZqbkVa7oW1Y7.jpg',3.0388190940073385,3,'2026-09-10',2,NULL,NULL),(8054,'魔法奇幻秀','The Imaginarium of Doctor Parnassus','几世纪前，帕纳索斯博士（Christopher Plummer 饰）还是一名德高望重的僧侣，他在与世隔绝的荒山野岭中讲述永恒的故事。某天，魔鬼尼克（Tom Waits 饰）不请自来。在他的引诱下，帕纳索斯与魔鬼作赌注，最终如愿得到永恒的生命。  　　时间到了现在，博士带着由女儿瓦莲蒂娜（莉莉·科尔 Lily Cole 饰）、青年安东（Andrew Garfield 饰）、侏儒波西（Verne Troyer 饰）组成的奇幻马戏团周游各地。就在女儿将满16岁时，尼克再次出现。原来，博士曾爱上一个女子（Lily Cole 饰），但永恒的生命却没有永恒的青春，为了和爱人厮守，他又和魔鬼作了一次愚蠢的赌注，而他恢复青春的代价就是要将第一个孩子献给魔鬼。践约的日子越来越近，烦恼的博士再与魔鬼作赌，只要他最先收集到5个灵魂便可保住女儿。这时，落魄的东尼（希斯·莱杰 Heath Ledger 饰）适时出现…',NULL,30000000,64352607,37.181019,6.3,869,123,'2009-10-01','en','/3wYeznQIRNzhSN8Z2AO66P1YmBs.jpg',3.4190530832080186,3,'2026-09-10',2,NULL,NULL),(8055,'朗读者','The Reader','15岁的少年米夏·伯格（大卫·克劳斯 David Kross 饰）偶遇36岁的中年神秘女列车售票员汉娜（凯特·温丝莱特 Kate Winslet 饰），后来两个发展出一段秘密的情人关系。汉娜最喜欢躺在米夏怀里听米夏为他读书，她总是沉浸在那朗朗的读书声中。年轻的米夏沉溺于这种关系不能自拔的同时，却发现他自己根本不了解汉娜。忽然有一天，这个神秘女人不告而别，米夏在短暂的迷惑和悲伤之后，开始了新的生活。二战虽然结束了，但德国对于纳粹战犯的审判还在继续。成为法律学校的实习生的米夏，在一次旁听对纳粹战犯的审判过程中，竟然发现一个熟悉的身影。虽然已经事隔8年，但米夏还是一眼便认出那就是消失8年的汉娜。而这一次，她坐上了纳粹战犯审判法庭的被告席，这个神秘女人的往事在案件的审理过程中逐渐清晰。然而，米夏却发现了一个汉娜宁愿搭上性命也要隐藏秘密。汉娜最终被判终身监禁，而此时米夏（拉尔夫·费因斯 Ralph Fiennes 饰）与汉娜的故事还在继续。','Behind the mystery lies a truth that will make you question everything you know.',32000000,113019290,33.923786,7.2,813,124,'2008-12-10','en','/yMvsKwvXMkIGdmpNMjSLmS8nskY.jpg',3.538640861628332,3,'2026-09-10',2,NULL,NULL),(8060,'婚姻生活','Married Life','Harry（克里斯·库柏 Chris Cooper 饰）和Richard（皮尔斯·布鲁斯南 Pierce Brosnan 饰）是无话不说的好友，Harry走到了人生中最为平庸的一个时候：早已习惯到毫无新鲜感的妻子，熟能生巧不再刺激的工作，与Richard的风流倜傥相比，他简直就是一个不再令人注目的中年男人。然而这些日子他却活得神采飞扬，他与一年轻的女子Kay（瑞秋·麦克亚当斯 Rachel McAdams 饰）坠入爱河，并且毫不避讳地把美丽得不可方物的Kay介绍给Richard认识。\r 　　Richard难以置信朋友在这个年龄还能得到这个尤物的倾心，难以抑制地，他对Kay一见倾心，并总是寻找机会与她接近。Harry在准备着如何与Kay顺利私奔，妻子Pat（派翠西娅·克拉克森 Patricia Clarkson 饰）毫无过错，且凡事为他着想。Harry想制造一起伪装成自杀的凶杀案。在准备的过程中不小心发现了Richard对Kay的爱慕，而Richard更发现了Pat的秘密。\r 　　原来在一段感情里，谁都有可能是谁的第四者。事情最后会有一个怎样的结局，他们能否都得到自己想要的幸福？',NULL,12000000,0,3.004432,6.1,38,90,'2007-09-12','en','/AdJKmRh3AKX5CVCdwdw1dNTqEJ8.jpg',2.6359898701941034,3,'2026-09-10',2,NULL,NULL),(8065,'决胜21点','21','Ben Campbell（吉姆·斯特加斯 Jim Sturgess 饰）有着惊人的才华，身为麻省理工高材生的他学业无懈可击，他亦毫无意外地赢得了哈佛医学院的录取通知书。然而30万的高昂学费和生活费令他的大学梦摇摇欲坠。在争取奖学金的面试中，教授对他说胜出者必须要有过人的经历而不是像本这种一张白纸的学生。Ben在一服装店打工，挣取每小时8美元的薪酬。同时和两个好友准备竞赛2.09以期获得认同和奖金。数学课上本的天才头脑被教授Mickey Rosa（凯文·史派西 Kevin Spacey 饰）发现，Mickey 希望本加入自己的21算法团队，专门去赌场依靠算牌赢得大钱。Ben并不同意，但Ben一直暗恋的女孩Jill Taylor（#凯特·波茨沃斯 Kate Bosworth 饰）也出面诱惑时，Ben开始动摇。Ben开始了严密的训练，出师的成功让Ben尝到了金钱、虚荣、欲望的权力。同时他和旧友开始疏远，渐渐迷失在赌场的漩涡里。','They proved the Vegas Blackjack System was beatable...by beating the hell out of it.',35000000,69823199,45.149948,6.5,1375,123,'2008-03-27','en','/eiMFnqN9oOQruiF2xeD8szoy8em.jpg',3.5821937357605695,3,'2026-09-10',2,NULL,NULL),(8068,'杀人三步曲','Desperado','长发披肩手握吉它盒的独行侠，他深爱的女友被冷血大毒枭所杀，于是只身上路，发誓让仇人血债血偿。大毒枭得到消息后，遂派手下去解决他，就在他身陷险境之际，美艳的书店女郎舍身相救，他才得以逃生。敌人的追杀行动一步一步地迫近，原来的独行侠有了美人的搭档，更是势不可挡所向披靡。英雄救美的同时更要报仇血恨……','When the smoke clears, it just means he\'s reloading.',7000000,25405445,25.511217,6.8,881,104,'1995-08-25','en','/kyt4WoVc1v833BXieV0Y2YsCDCv.jpg',3.4776725595508493,3,'2026-09-10',2,NULL,NULL),(8069,'太空英雌芭芭丽娜','Barbarella','公元四万年，太空英雌芭芭丽娜（简方达 饰）受命寻找恶魔 Durand-Durand 并除掉他。但是途中她的飞船出现了意外迫降了，等待她的是奇奇怪怪的人 ……','See Barbarella do her thing!',9000000,2500000,14.171759,5.7,146,98,'1968-10-10','en','/facTz5BZz4AkJal1FWgjYciekih.jpg',2.929144709414016,3,'2026-09-10',2,NULL,NULL),(8077,'Alien³','Alien³','经过长时间的飞行，蕾普莉搭乘的飞船并没有飞回地球！飞船返航途中发生意外，低温休眠舱在母船爆炸前脱离后，掉进了一个黑暗、寒冷的星球。除了残存的主教外，只有蕾普莉一人生还。这里是地球的一个外星废弃矿井，现在成了一个管制危险犯人的监狱。蕾普莉在医生的救助下恢复了健康。随着蕾普莉的到来，这里的犯人开始一个一个被神秘杀害。当局以为是犯人内部的犯罪，然而蕾普莉隐隐知道没这么简单。当她找出主教的残体连接上电脑查看飞行记录后，证实了她的想法：异形来了。','The bitch is back.',50000000,159773545,45.856409,6.2,1633,114,'1992-05-22','en','/16ExxTjS35LYktkxp8EzqrmhtvO.jpg',3.5632837409781244,3,'2026-09-10',2,NULL,NULL),(8078,'Alien: Resurrection','Alien: Resurrection','Two hundred years after Lt. Ripley died, a group of scientists clone her, hoping to breed the ultimate weapon. But the new Ripley is full of surprises … as are the new aliens. Ripley must team with a band of smugglers to keep the creatures from reaching Earth.','It\'s already too late.',70000000,162000000,37.44963,5.9,1365,109,'1997-11-12','en','/1hzXgA8m0wR17SyYHLHFDYq9UxC.jpg',3.445461403288178,3,'2026-09-10',2,NULL,NULL),(8080,'零号嫌疑犯','Suspect Zero','由于执行任务时过于冲动，FBI探员托马斯（艾伦·艾克哈特 Aaron Eckhart 饰）放跑了他一直都在追踪的连环杀人犯雷蒙德（基斯·坎贝尔 Keith Campbell 饰）。这一事件给予了托马斯巨大的打击，他也因犯下的过错而受到了降职的处罚。  没过多久，另一起杀人事件的发生引起了托马斯的警觉，而雷蒙德尸体的出现则让托马斯更加确信凶手是针对他有备而来。过去的灰暗记忆和目前的混乱状态不断的折磨着托马斯，在他和搭档弗兰（凯瑞-安·莫斯 Carrie-Anne Moss 饰）的努力下，一个名叫本杰明（本·金斯利 Ben Kingsley 饰）的男人浮出了水面。更可怕的是，在本杰明的身上，似乎存在着一种神秘而又强大的特异力量。','Who\'s next?',27000000,13000000,8.715822,5.5,98,99,'2004-08-27','en','/sIIahTE5sfOJtieytf252kB9RcS.jpg',2.829715300557902,3,'2026-09-10',2,NULL,NULL),(8090,'网络杀机','Untraceable','单身妈妈珍妮弗·马什（迪安·雷恩 Diane Lane 饰）是供职于FBI网络犯罪科的探员，她日常的工作就是对网络进行监视，查找任何一个盗取信用卡及其他可能造成危害的犯罪分子。在一次围剿信用卡盗贼的行动中，珍妮弗偶然进入一个名为KillwithMe的网站，网站通过视频直播一只小猫受虐死去的全过程。珍妮弗直觉该网站背后必有黑幕，她试图追踪IP和服务器，最终一无所获，似乎她所面对的对手具有颇为复杂的背景。  　　不久，该网站更新内容。画面中一个男子被捆绑起来，网站宣称浏览者越多，那名男子死得越快。珍妮弗等人眼睁睁看着男人死去，她决定不惜一切代价救出幕后黑手，却让自己也卷入这个死亡漩涡之中……','A cyber killer has finally found the perfect accomplice: You.',35000000,32483410,12.677505,5.9,238,101,'2008-01-22','en','/uILslgpmVnEG5WxQlfc3mQQBGIG.jpg',3.0362317492847612,3,'2026-09-10',2,NULL,NULL),(8095,'埃及艳后','Cleopatra','52岁的凯撒（雷克斯•哈里森 Rex Harrison 饰）以罗马执行官的身份驾临埃及，为了解决王室姐弟争位的事端。皇姐克里奥佩特拉（伊丽莎白•泰勒 Elizabeth Taylor 饰）美艳绝伦，凭借自身的魅力和政治手腕，迅速让凯撒拜倒在她的石榴裙下，不但获得了对埃及的统治权，而且还以美貌征服了罗马。克氏与凯撒完婚后，为其产下一子，深得凯撒喜欢，被立为继承人。但此事引起了凯撒手下大将安东尼（理查德•伯顿 Richard Burton 饰）与屋大维（罗迪•麦克道尔 Roddy McDowall 饰）的不满。在凯撒遇刺驾崩之后，安东尼接掌了罗马的统治权，但他同样无法抵挡克氏的绝世美貌。当安东尼彻底沉溺于暴风雨般爱情的时候，身在罗马的屋大维已经吹响了夺权的号角……','The motion picture the world has been waiting for!',31115000,71000000,13.244365,6.7,146,248,'1963-06-12','en','/7Omj7QGoy2G9sxUMXKu7anyHbNI.jpg',2.9771161101839327,3,'2026-09-10',2,NULL,NULL),(8141,'杀了我吧','You Kill Me','由于酗酒，弗兰克（本·金斯利 Ben Kingsley 饰）又一次将组织分配给他的任务给搞砸了，作为一名职业杀手，这是无法原谅的错误，为了让弗兰克“重回正道”，他的叔叔罗曼（菲利浦·贝克·霍尔 Philip Baker Hall 饰）不得不将他送往旧金山，进行强制戒酒。\r 在好友汤姆（卢克·威尔逊 Luke Wilson 饰）的陪伴下，弗兰克的戒酒事业初显成效，同时，一个叫劳瑞尔（蒂娅·里欧妮 Tea Leoni 饰）的姑娘的出现让弗兰克坠入了情网。坏消息传来，黑帮大佬爱德华（丹尼斯·法里纳 Dennis Farina 饰）对弗兰克的家族进行了大清洗，为了复仇，弗兰克毅然放弃了旧金山平静舒适的生活，踏上了返乡的道路。不同的是，这一次，弗兰克的身边多了一个美人，对于危险的未来，深爱弗兰克的劳瑞尔决定不离不弃，奉陪到底。','Professional alcoholic hit man gets life back on track thanks to her',4000000,2426851,6.091951,6.2,80,90,'2007-02-09','en','/4C5VQVdE2YRBPhpZLnExk1XUzDZ.jpg',2.8045345311637537,3,'2026-09-10',2,NULL,NULL),(8193,'大人物拿破仑','Napoleon Dynamite','爱达荷州普林斯顿高中生拿破仑（乔恩•海德 Jon Heder 饰）是个衰蛋，带着厚厚的眼镜，不酷不帅，还总是搞怪。他和奶奶以及失业的哥哥凯普相依为命。他在学校不受同学待见，还经常被老师修理。他不合群，只能孤独地跟风车球使劲儿。后来，他结识了同学佩德罗（艾弗连•莱米雷斯 Efren Ramirez 饰），两人成了朋友。在佩德罗参加学生会主席竞选时，拿破仑贡献了自己的力量。一次，拿破仑在家扮沙发土豆时，有女孩黛比（蒂娜•米乔里诺 Tina Majorino 饰）上门推销。他于是对这个女孩产生了好感，但是没有勇气追求，只能想出一些拙劣的鬼点子，结果总是不欢而散。凯普看电视购物，被防身术教练深深吸引了，拉着拿破仑两人参加了俱乐部，没想到大失所望……','He\'s out to prove he\'s got nothing to prove.',400000,46118097,23.603514,6.7,554,95,'2004-06-11','en','/rspTtDnXyifO9bKiySad0U2W4j0.jpg',3.3359685936645964,3,'2026-09-10',2,NULL,NULL),(8195,'Ronin','Ronin','A briefcase with undisclosed contents – sought by Irish terrorists and the Russian mob – makes its way into criminals\' hands. An Irish liaison assembles a squad of mercenaries, or \'ronin\', and gives them the thorny task of recovering the case.','Your ally could become your enemy.',55000000,41610884,32.657488,6.7,658,122,'1998-09-25','en','/AirrhRJjHwytOV0pdLu7YZ4DEyr.jpg',3.401454119745252,3,'2026-09-10',2,NULL,NULL),(8197,'午夜善恶花园','Midnight in the Garden of Good and Evil','这部文艺电影透露着浓浓的美国南方历史风味。富豪吉姆（凯文•斯帕西饰）举办了一个盛大的圣诞派对，然而在这个热闹派对的午夜，却发生了一场命案。所有的矛头都指向了吉姆，吉姆委托当晚到场的记者约翰（约翰•库萨克饰）搜集证据帮助自己，在约翰的求证过程中，却发现了被害者和主人吉姆之间的秘密关系，当搜证继续进行，吉姆自己却曝出了一个内幕，使得案件继续陷入迷雾。在这个南方小镇的午夜，究竟隐藏着怎样的善与恶，爱与恨，怎样的人性与阴谋？',NULL,35000000,25105255,5.525544,6.3,157,155,'1997-11-21','en','/4SYIV9cPixTWfjlDd44mGl6F05f.jpg',2.9557005794288016,3,'2026-09-10',2,NULL,NULL),(8198,'沉静的美国人','The Quiet American','改编自格雷厄姆·格林的经典小说，讲述一个以1952年前后越南法国印度支那战争为背景、围绕三角恋情展开的谋杀悬疑故事。[米拉麦克斯]',NULL,30000000,27674124,5.133744,6.4,81,101,'2002-11-22','en','/nLooNNrvzpf49G7HsB9siQT4036.jpg',2.811043621927301,3,'2026-09-10',2,NULL,NULL),(8202,'Æon Flux','Æon Flux','400 years into the future, disease has wiped out the majority of the world\'s population, except one walled city, Bregna, ruled by a congress of scientists. When Æon Flux, the top operative in the underground \'Monican\' rebellion, is sent on a mission to kill a government leader, she uncovers a world of secrets.','The Perfect World Meets The Perfect Assassin',62000000,52304001,29.954302,5.4,703,93,'2005-11-30','en','/78aFZhmgpNxsfcFLNW6GZ0cOmX7.jpg',3.2209980404376797,3,'2026-09-10',2,NULL,NULL),(8204,'奇幻精灵事件簿','The Spiderwick Chronicles','本片根据霍利•布莱克（Holly Black）及托尼•迪特里奇（Tony DiTerlizzi）的同名畅销小说改编。单亲母亲格蕾丝（玛丽-路易斯•帕克 Mary-Louise Parker 饰）带着双胞胎儿子贾里德与西蒙（弗莱迪•海默尔 Freddie Highmore 饰）和大女儿马洛丽（莎拉•伯格 Sarah Bolger 饰）搬入斯派特维克祖居，竟碰到一系列怪事。贾里德在独自调查过程中发现了楼顶阁楼中伯祖母父亲阿瑟•斯派特维克（大卫•斯特雷泽恩 David Strathairn 饰）的精灵探索指南。尽管书表皮有一纸警告，贾里德还是阅读了指南，随后便看到了书中描述的精灵之一，棕精灵辛伯来泰克（马丁•肖特 配音）。辛伯来泰克警告贾里德不能把书拿到斯派特维克祖居保护圈外，以防恶灵莫格拉斯（尼克•诺特 Nick Nolte 饰）将指南据为己有，加害其他精灵。但莫格拉斯的手下已得知指南重见天日的事实，并错抓了西蒙。为了保护指南及家庭，三兄妹必须与莫格拉斯展开殊死搏斗…… ©豆瓣','Their World Is Closer Than You Think.',90000000,162839667,21.436682,6.3,572,95,'2008-02-14','en','/4uXsoe1sgg10E9EITZzdL3xXIOY.jpg',3.2865528605312444,3,'2026-09-10',2,NULL,NULL),(8224,'八毫米','8MM','一个去世议员的家人无意中发现了议员的一件遗物——一卷8毫米的影片，里面竟然有女孩被虐杀的整个过程，于是交给了一名私家侦探汤姆威勒（Nicolas Cage尼古拉斯•凯奇饰）调查真相。汤姆威勒本来平静的生活开始危机四伏。汤姆威勒一步步破解真相的过程，亦是一步步陷入泥潭的过程。但是影片中陌生女子的受虐惨剧在他脑中挥之不去。良心促使他在凶险的真相面前变得无惧。但当真相揭露之时，世间的丑恶不堪得令汤姆威勒也陷入了惊恐……','You can\'t prepare for where the truth will take you.',40000000,96618699,25.580272,6.1,474,123,'1999-02-26','en','/AsCqSMwcyPJrnFrZDI0u9KT9FE.jpg',3.2290685427274144,3,'2026-09-10',2,NULL,NULL),(8247,'Jumper','Jumper','David Rice is a man who knows no boundaries, a Jumper, born with the uncanny ability to teleport instantly to anywhere on Earth. When he discovers others like himself, David is thrust into a dangerous and bloodthirsty war while being hunted by a sinister and determined group of zealots who have sworn to destroy all Jumpers. Now, David’s extraordinary gift may be his only hope for survival!','anywhere is possible.',85000000,222231186,21.218,5.9,1799,88,'2008-02-10','en','/8e9WH8oQXqQ5SZV16F3s8XNSy58.jpg',3.464485052789191,3,'2026-09-10',2,NULL,NULL),(8265,'欢迎来北方','Bienvenue chez les Ch\'tis','菲利普在法国南部普罗旺斯的一家邮局任职了十多年，一成不变的生活和闷闷不乐的妻子朱莉令他感到压抑。为了讨妻子欢心，菲利普装扮成残疾人申请升职到南部的黄金海岸地区，却不料弄巧成拙被调派到了极北的小城贝尔格担任局长。在南方人眼里，那里气候寒冷恶劣，人民粗俗不堪，说话还带着难懂的Ch\'ti口音，是堪比地狱的地方。心灰意冷的菲利普辞别家人，忐忑不安的独自赴任。然而出乎意料的是，他发现自己的新下属们和当地的居民都很热情好客，自己也很快与邮递员安东尼交上了朋友。菲利普逐渐爱上了这处淳朴简单的小城，但当他试图说服朱莉一同来到北方生活，却遭到了妻子的质疑',NULL,11000000,53191886,18.923181,6.8,615,106,'2008-01-09','fr','/dfht1lGq2ALbrRkMj35dUrj5kHG.jpg',3.3661999920538106,3,'2026-09-10',2,NULL,NULL),(8271,'后窗惊魂','Disturbia','父亲因为意外去世后，受到打击的凯尔(希安拉博夫饰)一直沉默寡言，忧虑不安。一位原本好意却反应迟钝的老师不幸成了他发泄郁闷的靶子，被暴揍一顿。凯尔也因此受到法庭判决的居家软禁。母亲朱莉(凯瑞-安莫斯)拼命加班工作维持两人的生计，却始终无法了解儿子性格的变化。　幽禁在郊区的家中，沉闷无聊的生活让凯尔对街坊四邻产生兴趣，通过窗户观察他们的一举一动，他对新搬来的邻家女孩阿什莉(萨拉罗默饰)发生好感。两人相熟后开始怀疑另一个邻居是连环杀手，这种猜测究竟是凯尔无聊荒诞的想像，还是会给他们带来杀身之祸的真实罪行？','The quieter the street, the darker the secrets....',20000000,117760134,31.690456,6.6,1006,105,'2007-04-12','en','/o5xXjqkUdWu4u3EuKJGdZmGTGZA.jpg',3.49249313598252,3,'2026-09-10',2,NULL,NULL),(8272,'萨维奇一家','The Savages','本片通过现代生活最令人困惑与艰难的体验之一——当成年兄弟姐妹突然被拽出自我中心的生活，被迫照顾一位疏远的年迈父母时——对家庭、爱与死亡进行了一场另类审视。[福克斯探照灯影业]',NULL,0,0,5.663889,6.8,110,114,'2007-01-19','en','/nY54gSmTOmSXlQpWDB7DWp4u8a7.jpg',2.8964365547727,3,'2026-09-10',2,NULL,NULL),(8273,'美国派3：美国婚礼','American Wedding','这帮高中时候就一起计划怎么脱离处男身的老友们现今已经长大，就在他们即将踏出大学校门的时候，传来了吉姆（贾森•比格斯 Jason Biggs 饰）和米歇尔（艾丽森•汉妮根 Alyson Hannigan 饰）即将举行婚礼的消息，更加碰巧的是婚礼和他们的成人礼巧合在同一日。于是，这帮死党相约为吉姆举行最后一次单身派对，当然史蒂夫（西恩•威廉•斯科特 Seann William Scott 饰）其实是不想放过婚礼上漂亮的女傧相。芬奇担忧自己性感漂亮的你、妹妹柯登斯落入了史蒂夫的手中，于是也来到参加吉姆的单身派对，一连串妙趣横生的场面自然让你笑破肚皮。','Forever hold your piece.',55000000,231449203,36.194802,6,1129,103,'2003-08-01','en','/qwtOiwLanbdyAgeiShAEhpmSztU.jpg',3.4224637447457242,3,'2026-09-10',2,NULL,NULL),(8285,'闪灵侠','The Spirit','在黑暗冰冷充满歌特味道的中心城，身穿黑衣的闪灵侠（Gabriel Macht 加布里埃尔•马赫特 饰）无声无息保护这个他所钟爱的城市。闪灵侠曾是一个名叫丹尼•寇特的联邦警察，凶恶的匪徒夺去了他的性命，借助一项神秘的技术，丹尼重返人间，并以闪灵侠的身份游走在灰色地带，帮助警方处理各种棘手案件。绰号“章鱼”（Samuel L. Jackson 塞缪尔 L 杰克逊 饰）的疯狂科学家是中心城最大的邪恶势力，也是闪灵侠的头号敌人。他正四处寻找大力神之血，以完成其研究多年的永生试验。丹尼的旧情人珊德•沙瑞芙（Eva Mendes 伊娃•门德斯 饰）的出现搅乱了章鱼的计划……','I\'m gonna kill you all kinds of dead.',60000000,39031337,14.84856,4.7,320,103,'2008-12-25','en','/520gN20oAIvmKYbZlfQJg9bzUyo.jpg',2.9916058508204877,3,'2026-09-10',2,NULL,NULL),(8291,'因果循环','Poetic Justice','男友被杀后，理发师贾斯特依然悲痛欲绝，她通过写诗来排解失恋的痛苦。由于汽车抛锚，贾斯特无法前往奥克兰参加一个会议，她搭上了朋友伊莎和伊莎的邮递员男友芝加哥的顺风车。同行的还有芝加哥的同事拉奇，在经历了最初的一些问题后，贾斯蒂斯与拉奇的关系逐渐亲密起来。但她准备好再次敞开心扉了吗？','A Street Romance.',14000000,27515786,3.650857,6.9,47,109,'1993-07-23','en','/6jE7Vzh3edBQtbbDcF4AC5gMX2g.jpg',2.69705978429119,3,'2026-09-10',2,NULL,NULL),(8292,'四兄弟','Four Brothers','影片以母亲的遇害为起因，讲述了特殊构成家庭里的四兄弟其心协力与黑暗势力作者针锋相对、你死我活的斗争。影片出了饱含黑色暴力元素之外，也相应地加入了“调剂”用的轻喜剧成分，事实上，这也是辛格尔顿的特色之一。除了影片最具亮点的“黑白抗争”、“黑打黑”的动作戏之外，最能打动人的要属影片给人的真实感受。被收养的不同肤色的孩子们在同一个大家庭里过着幸福的生活，怎不令人羡慕、令人动容。而善良老母的被害、与四兄弟愤然掀起复仇狂潮的情节更是激起了所有热血男儿的心潮。另外，影片中，经常萦绕耳边的动感黑人音乐也无形中增加着影片的吸引力。','They came home to bury mom... and her killer',45000000,92374674,24.694551,6.7,607,109,'2005-08-11','en','/y2fkD8q6i17jnD3C94NzjsZPI1D.jpg',3.3622384826506835,3,'2026-09-10',2,NULL,NULL),(8293,'Howards End','Howards End','Merchant Ivory’s adaptation of EM Forster’s classic 1910 novel, starring Emma Thompson, Helena Bonham Carter, Anthony Hopkins & Vanessa Redgrave returns to the big screen in a beautiful new 4K restoration. Stunning location photography, lavishly detailed sets & elegant period costumes, this compelling saga follows the interwoven fates and misfortunes of three families amid the changing times of Edwardian England. It tells the story of two free-spirited, cosmopolitan sisters, Margaret (Emma Thompson) and Helen Schlegel (Helena Bonham Carter), who collide with the world of the very wealthy ­­– one sister benefiting from the acquaintance with the Wilcoxes (owners of the beloved country home Howards End), the other all but destroyed by it. Anthony Hopkins is the conservative industrialist Henry Wilcox and Vanessa Redgrave is his ailing wife Ruth Wilcox.',NULL,0,25966555,5.897391,6.9,95,140,'1992-03-13','en','/kr7rt4fZlVrjjsJke2xNAyUXIDZ.jpg',2.8656414698169317,3,'2026-09-10',2,NULL,NULL),(8321,'杀手没有假期','In Bruges','一对杀手，肯与雷（Colin Farrell 饰），在圣诞期间来到比利时古城布鲁日，他们将在这里接到联系人哈里（Ralph Fiennes 饰）指令的新任务。雷在不久前的一次暗杀中误杀了一名男童，怀着深深愧疚的雷情绪不稳，古城中的等待对他来说是一场难耐的煎熬。肯作为带领雷入行的前辈，试图帮助雷摆脱困境，但他的努力毫无收效。百无聊赖的雷在街上结识了女演员克洛伊，这个神秘女孩引发了雷一系列的冒险经历，与此同时，肯再一次被哈里催促，原来此次任务的真相是暴怒的哈里要雷为他的误杀行为付出代价，肯面对被自己一手引入杀手行当的年轻人，难以做出抉择，两名杀手，在夜色中的古城各怀心事……','Shoot first. Sightsee later.',15000000,34533783,25.329493,7.4,1388,107,'2008-02-08','en','/vz3Vd6nfq9YZrVvyYx5RHFaYKV3.jpg',3.7162807706154353,3,'2026-09-10',2,NULL,NULL),(8326,'别有洞天','Holes','因为一双运动鞋，斯坦利（Allan Kolman 饰）被关进了德克萨斯州的拘留所之中，尽管斯坦利实则无辜，但他祖上遗留下来的坏运气让他毫无疑问地遭受到了并不公正的审判。为了逃脱牢狱之灾，斯坦利选择了前往德州绿湖营进行劳动改造，然而，着却正是他噩梦的开始。 绿湖营位于一片茫茫的沙漠之中，这里的管理员将来这里劳动改造的孩子们视为奴隶，处处苛责刁难，甚至布置了一个看似毫无意义的任务——在已经干涸的河床上挖洞。很快，斯坦利便开始怀疑，管理员的这一要求背后隐藏着某些不可告人的秘密，一批传说中埋在河床里的宝藏随之浮出了水面，而这批宝藏和斯坦利的家族亦有着千丝万缕的关联。','Some secrets are too big to keep hidden.',20000000,0,22.001408,6.7,383,117,'2003-04-18','en','/uCSRqp4zNtHGRe2EL83rzZ1xGXp.jpg',3.236928306036317,3,'2026-09-10',2,NULL,NULL),(8328,'舞出我人生2：街舞','Step Up 2: The Streets','失去双亲的街舞者安迪（布莱恩娜·伊维根 Briana Evigan 饰）自小就开始了对街舞的执着练习，她所在的巴尔的摩知名街舞团体410最近完成了“锐舞争霸赛”的视频参赛宣言，而她的监护人因这次出格的视频内容威胁要把她送离此地，幸好在朋友的斡旋下，安迪选择进入马里兰艺术学校学习，保住了眼下的生活。学校里的明星学生查斯（罗伯特·霍夫曼 Robert Hoffman 饰）对安迪颇有兴趣，要求加入锐舞争霸赛却被后者无视。安迪因学业繁重不能兼顾410的训练，终于导致被开除。失意的安迪接受了查斯的邀请，和他物色来的众多校内隐藏的舞蹈高手组成新队伍，向锐舞争霸赛发起冲击……','It\'s not where you\'re from. It\'s where you\'re at.',23000000,150816700,28.973074,6.5,640,98,'2008-02-14','en','/2gH1gFxqh70cjISQuURmLYD9zmt.jpg',3.357745316533385,3,'2026-09-10',2,NULL,NULL),(8329,'死亡录像','[REC]','女记者安吉拉（Manuela Velasco 饰）和摄影师帕布罗（Pablo Rosso 饰）计划拍一部描写消防员工作的纪录片。接到报警电话后，他们随消防队来到一幢老式的公寓。公寓内似乎有某种致命的病毒在蔓延，感染者莫不心性癫狂，嗜血如命。住户被紧急疏散，死亡人数则不断增加。原本以为是一次平常的采访，却没想到通过摄像机拍下了真实而恐怖的场景……  　　本片荣获2008年阿姆斯特丹奇幻电影节Silver Scream奖、2008葡萄牙奇幻国际电影节最佳影片和观众票选奖、2008西班牙戈雅奖最佳编剧和最佳新人女主角等多个电影节奖项。','One witness. One camera',1500000,30448000,31.691617,7.1,934,78,'2007-04-10','es','/bYrbDneOEx3mxY95oQSHy5baL3R.jpg',3.5580014421420767,3,'2026-09-10',2,NULL,NULL),(8337,'极度空间','They Live','在未来的某个年代，人们的思维已经被政府机构控制，政府机构通过电视信号传输一种催眠电波控制人们的行动。但是一些不甘心被强权统治的人们研究出一种眼镜，戴上这种眼镜，电视节目里道貌岸然的官员就会现出骷髅般的原形……','Who are they? And what do they want?',4000000,13008928,29.852608,7.1,550,94,'1988-11-23','en','/ngnybFTuopfbfmmEeX9jjBQQmF6.jpg',3.399984694443618,3,'2026-09-10',2,NULL,NULL),(8338,'盲流感','Blindness','诺贝尔奖得主Jose Saramago的小说《Blindness》将被搬上电影舞台。书中描述了一个陷入致盲病毒的城市，导火线从一名司机点燃，突然失明后，他得到了一个人的善意帮助，这条线继续燃烧下去，眼科医生也来帮助他们了，故事就这样开始了。所有的致盲者都被关进了一座废弃的精神病院，重兵把守，不惜生命的代价也要制止疾病的扩散。 Julianne Moore将扮演唯一没有失明的人——医生的善良妻子， 著名黑人电影人Danny Glover在片中扮演一名致盲的黑人老者。尽管主角来自美国，但这部电影是由日本、巴西、加拿大合拍的国际性电影',NULL,25000000,19844979,17.603823,6.4,387,121,'2008-05-14','en','/awgi2afKumPiKt9cp2SFj99bHWU.jpg',3.198322155975449,3,'2026-09-10',2,NULL,NULL),(8346,'我盛大的希腊婚礼','My Big Fat Greek Wedding','Toula（妮娅·瓦达拉斯 Nia Vardalos 饰）虽然在美国出生长大，却是生活在一个巨型的希腊世界中，整个庞大的家族以父亲权威般的意志为代表坚持着希腊是世界之源的精神动力，从小就眼观着家人古怪行为的Toula听得最多的就是母亲与神经质祖母的言论：嫁给一个希腊人，生一大堆希腊小孩，喂饱自己的肚子直到世界的最后一天。  　　长到30岁的Toula邋遢肥胖，在一次夜雨中继续听着父亲的唠叨，然而当她走进日复一日工作的家庭餐馆时，她决定要改变自己的命运！她去学习，去美容院整理自己的仪容，当她浑身散发出自信时，命定的白马王子Ian（约翰·考伯特 John Corbett 饰）出现了，二人一见钟情，迫不及待要组织自己的新家庭。  　　对这个庞大的希腊家族来说，Ian不折不扣是一个外人，婚礼的繁琐和斗争才刚刚开始，不同的价值观引发了一连串笑料。','Love is here to stay... so is her family.',5000000,368744044,18.115566,6.2,671,95,'2002-02-22','en','/7TLjQx4WeM0XPRWgJ5n5wIs8IgP.jpg',3.301417382345132,3,'2026-09-10',2,NULL,NULL),(8355,'Ice Age: Dawn of the Dinosaurs','Ice Age: Dawn of the Dinosaurs','Times are changing for Manny the moody mammoth, Sid the motor mouthed sloth and Diego the crafty saber-toothed tiger. Life heats up for our heroes when they meet some new and none-too-friendly neighbors – the mighty dinosaurs.','You Won\'t Believe Your Ice!',90000000,886686817,69.457898,6.5,2271,94,'2009-06-29','en','/cXOLaxcNjNAYmEx1trZxOTKhK3Q.jpg',3.7586354979985406,3,'2026-09-10',2,NULL,NULL),(8357,'我们到底知道多少','What the #$*! Do We (K)now!?','阿曼达（玛丽·玛特琳 Marlee Matlin饰），一位离婚的普通摄影师。她每日的生活平淡又死气沉沉，直到一日她经历了一段犹如“爱丽丝梦游仙境”般奇妙梦幻的时光。影片惊人的视觉特效让观众置身于阿曼达的神经世界里，一览微妙的细胞、分子甚至是量子世界。影片采访了多位著名学者，讨论关于真相、记忆、眼睛、大脑等深奥的话题。\r 　　本部标新立异、别出心裁的影片《我们到底知道多少？》，融合了纪实、剧情、视觉特效、动画等多种表现手法于一身，充满着量子论、物质、真理等一系列深奥玄妙的概念，构建出一个充满不确定性的量子世界。在这个看似稀松平常的未知领域里，到底何为真实。','Time to get wise.',0,10000000,7.288352,5.8,34,109,'2004-04-23','en','/ghoM9gorKvgAcqkSJ6TDQcsObWN.jpg',2.6182822838844966,3,'2026-09-10',2,NULL,NULL),(8358,'荒岛余生','Cast Away','查克（汤姆•汉克斯 Tom Hanks饰）任职于美国联邦快递，他系统工程师的职业决定了他的生活忙碌、自律、充满时间紧迫感。而查克总能把一切工作都井井有序的安排在每天的日程里，时间就在他的控制之下。他无暇顾及的只是女朋友凯莉（海伦•亨特 Helen Hunt 饰）。 一场飞机失事改变了这一切。所有人都以为查克丧生于这场灾难中，然而事实上他活了下来，被困在一个荒无人烟的小岛上。荒岛上的生活就连吃喝都成问题，查克成为了现代鲁滨逊。但另一方面，他在这里却因为与大自然依存，与险境搏斗，与孤独作伴，与饥饿抗争，得到了以前从来没有领悟到的感受。当他回到现代社会时，人生有了新的开始。','At the edge of the world, his journey begins.',90000000,429632142,57.739713,7.5,3218,143,'2000-12-22','en','/7lLJgKnAicAcR5UEuo8xhSMj18w.jpg',4.058924091409926,3,'2026-09-10',2,NULL,NULL),(8359,'美国女孩的秘密','Kit Kittredge: An American Girl','1934年，经济大萧条越来越严重，10岁的女孩Kit（阿比吉尔·布莱斯林 Abigail Breslin 饰）的家庭也遭到连累，父亲前往芝加哥寻找工作，为了维持生计，母亲把房子的空余房间出租，各色各样的住客搬了进来。包括流动图书馆的馆长Miss Bond、健美操小姐Miss Dooley、魔术师、还有Kit的同学Stirling以及他母亲，无业游民Will和弟弟Countee在此打工，做些修补工作以换取食物。Kit的志愿是当一名伟大的新闻记者，当她了解新闻是需要新鲜的题材，便随时挖掘新鲜事件。当地一直发生游民抢劫的恶性案件，这次轮到Kit的好友Ruthie家被抢，继而是Kit家的保险箱而被偷走了，所有的矛头都指向了Will，只有Kit相信他是无辜的。一个偶然的机会下，Kit和她的小伙伴们发现了真凶，并且打算用计谋擒住对方。他们能在感恩节到来之前让生活回复正常吗？','Kit Kittredge, a resourceful young girl, helps her mother run a boardinghouse after her father loses his job.',0,0,6.27141,6.4,34,101,'2008-07-02','en','/niHi0hJSryO5DpSVNCMASc3EELc.jpg',2.623986350678933,3,'2026-09-10',2,NULL,NULL),(8363,'太坏了','Superbad','塞斯（乔纳•希尔 饰）和埃文（迈克尔•塞拉饰）是一对不善交际、性格迥异的好朋友，二人即将高中毕业，对没有彼此的大学生活既焦虑又恐惧。\r 　　一个周末，二人的“桃花运”来了，因为他们收到了一个请柬，邀请他们去参加一个几乎完全是由漂亮女孩们主办的舞会，条件是他们要提供舞会上所需的各种酒类。令人讨厌的朋友弗盖尔（克里斯托弗•米恩特兹•普莱斯 饰）也加入到他们的行列，还给自己弄了一个假身份证，取了“迈克•拉文”这样愚蠢的假名。\r 　　舞会上，塞斯盯上了舞会的组织者茱尔斯，埃文看上了 与他一起上数学课的女孩贝卡，弗盖尔则选择了装扮刺激的妮科拉。\r 　　然而一系列不幸的巧合将三个人带到了一个陌生的地方，还让他们与斯莱特和迈克尔斯警官发生了冲突。对于三个即将高中毕业的小伙子来说，这可能是他们经历的最可怕、最让人感到羞愧的一个夜晚，然而，也是一个值得他们回忆一辈子的夜晚。','Come and Get Some!',20000000,121463226,33.436092,7,2100,113,'2007-08-17','en','/ek8e8txUyUwd2BNqj6lFEerJfbq.jpg',3.769026292656919,3,'2026-09-10',2,NULL,NULL),(8367,'侠盗王子罗宾汉','Robin Hood: Prince of Thieves','十字军东征时期，英国人罗宾被关押在了东方。在黑暗恐怖的牢中生活了五年后，一次偶然的机会，罗宾杀死了看守并解救了两个难友，获得了宝贵的自由。其间，一个难友遇敌死去，临死前叫罗宾把遗物交给其妹玛莉亚，而另一个幸存的难友摩尔人亚森则为了报答救命之恩，紧紧地跟随在了罗宾身边。','For the good of all men, and the love of one woman, he fought to uphold justice by breaking the law.',48000000,390493908,28.803729,6.6,909,143,'1991-06-14','en','/q9mcDkN9CcmzYwvMBEeErKQuNgb.jpg',3.460267436427037,3,'2026-09-10',2,NULL,NULL),(8373,'变形金刚2：卷土重来','Transformers: Revenge of the Fallen','军方和汽车人的秘密合作计划面临被取消的危险，而重新复活的威震天和红蜘蛛引领霸天虎军队，密谋夺取能量源，企图在地球掀起又一场腥风血雨。此时主人公山姆（希亚·拉博夫 Shia LaBeouf 饰）告别相恋的女友米凯拉（梅根·福克斯 Megan Fox 饰），要开始自己梦寐以求的大学生活了，但一切似乎都不那么顺利，一块小小的魔方碎片似乎在给予山姆某种启示。为了获取魔方里的信息，霸天虎开始了对山姆的追击，擎天柱为了保护山姆而牺牲，山姆受其感召，决定重新担负起自己的使命。山姆在自己室友里奥（雷蒙·罗德里格斯 Ramon Rodriguez 饰）和“机器战士”西蒙斯（约翰·托尔托罗 John Turturro 饰）的帮助下，与女友米凯拉根据魔方碎片给山姆的提示来到了埃及，他们在金字塔里发现了能量源。而此时，霸天虎的军队也赶到了埃及。军方此时有一小队人马也在西蒙斯的要求下带着擎天柱的尸体来到了埃及，善恶双方力量在那片金色的沙漠展开了殊死搏斗。','Revenge is coming.',150000000,836297228,21.939663,6,3138,150,'2009-06-19','en','/5PHRDe7vAfrWY4XO7fYQYNOBiQA.jpg',3.60487472227381,3,'2026-09-10',2,NULL,NULL),(8374,'处刑人','The Boondock Saints','一对热血虔诚的爱尔兰裔兄弟，因自卫杀人而得罪黑帮，警署以正当防卫之名无罪释放。从此之后，二人决定以己之力对抗社会渣滓，购买武器以暴制暴，在朋友洛克（大卫·德拉·洛克David Della Rocco 饰）的帮助下清除犯罪分子。联邦警探保罗·斯迈克（威廉·达福 Willem Dafoe 饰）负责侦破案件，本来毫无头绪；但 在黑帮头子“老爸乔”（卡洛·罗塔 Carlo Rota 饰）雇佣了传奇枪手“公爵”（比利·康诺利 Billy Connolly 饰）对抗麦克马纳斯兄弟之后，情况却发生了意想不到的变化……','Thy Kingdom Come. Thy Will Be Done.',6000000,30471,34.917447,7.2,837,108,'1999-01-22','en','/yU9fyTc3lQ4vbROKjc7N6VoHhuS.jpg',3.5495838499543475,3,'2026-09-10',2,NULL,NULL),(8386,'High到哈佛','How High','希拉斯（马索·曼恩 Method Man 饰）擅长用草药来医治各类疑难杂症，他的死党伊福瑞（Chuck Davis 饰）提议希拉斯可以去上大学学习医学，但对于朋友的建议，希拉斯一直没有放在心中。知道有一天，伊福瑞不幸去世，希拉斯用他的骨灰捣鼓出了一些诡异的种子，种植之后竟然长出了伊福瑞幼芽，直到这时，希拉斯才真的将考大学的念头放入了脑袋。  　　詹梅尔（莱德曼 Redman 饰）在大学预科里浑浑噩噩的混了六年，当他的母亲威胁他再不振作起来就要将他从家中赶出去之时，他才意识到，是时候参加大学考试了。在停车场，希拉斯和詹梅尔相遇了，两人误打误撞点燃了伊福瑞幼芽，使得好友灵魂现身，成为了两人的最强助攻。','They\'ve got their degrees all rolled up.',12000000,31155435,11.510281,6.3,218,93,'2001-12-21','en','/qWF784YqUZE8KhbBfuqhMSzmUPs.jpg',3.043245309015681,3,'2026-09-10',2,NULL,NULL),(8390,'爱情三选一','Definitely, Maybe','离婚，就像结婚一样，代表着你的生活中的一个全新的开始……威尔·海斯就在经历着这样一个生命的转折点，在曼哈顿居住的他，目前正在办理着离婚手续，同时，他还打算独自一人带着自己10岁的小女儿玛娅。  　　玛娅是个天真浪漫的小女孩，然而毕竟经历了父母的离婚，所以可以理解她为什么有那么点早熟。玛娅不懈地追问着自己的父亲，她想知道威尔结婚前是什么样子的，更想知道自己的父母从相遇到相爱的每一个小细节。  　　威尔觉得应该从1992年开始讲起，那个时候他还是一个年轻、过分乐观、不切实际的政客，为了一展所长，刚刚从老家威斯康星州搬到纽约，就是想在总统大选中尽一份心力……为了满足玛娅的好奇心和求知欲，威尔仔仔细细地整理了自己在纽约这么多年的一点一滴，自己了也跟随着这些回忆，重新体验了一次过去：一个理想过了头的年轻人，用自己的切身体验，终于明白了大城市的政治体系中的复杂和辗转曲折。当然，他同时也回想起了自己与三个完全不同的女人的三段恋情。  　　威尔一直尝试着，希望可以找到一种温和的方式将自己以前的生活告诉女儿，所以他选择了床头故事，同时把涉及其中的人的名字，全部做了更改，玛娅只能凭着这些故事，自己动脑筋猜测到底是哪个女人和父亲走进了神圣的婚姻殿堂，然后生了自己……玛娅不停地思考着，妈妈到底是哪位呢？是爸爸口中那个大学时代的恋人、值得信赖的邻家女孩艾米丽？还是威尔一生中最好的朋友、对政治一点都不感兴趣的红粉知己埃普丽尔？又或者是那个无拘无束、过于洒脱，却也野心勃勃的新闻记者萨摩尔？  　　就在玛娅把爸爸这些神秘的爱情细节全部拼凑到一起仔细寻找的时候，她明白了爱情并不像歌曲、电影中描述的那样简单和轻松，至于威尔，也在讲述回忆的过程中明白了一个道理，那就是有的时候不要一味地往前走，多回头看看，也许可以走得更快……也许，只是也许，他真的能找到幸福美满的生活。','Three relationships. Three disasters. One last chance.',0,55447968,29.173266,6.7,620,112,'2008-02-08','en','/xdwOlIcesGwp9raKNvqV6OhII3a.jpg',3.3779894419517578,3,'2026-09-10',2,NULL,NULL),(8408,'活死人之日','Day of the Dead','僵尸侵染的范围持续扩大之余，人类也加紧进行针对性研究。研究员莎拉（Lori Cardille 饰）和直升机驾驶员约翰等人空降到矿道改建的地下研究中心，罗根医生在这里研究僵尸习性，并得到了一些初步成果。负责中心安全与捕捉僵尸的军人们对暗无天日的地下生活早已厌倦，每天面对同袍死去、消息隔绝、研究进展缓慢让他们暴躁易怒，并在长官罗德（Joseph Pilato 饰）带领下公然反抗项目负责人。精神濒临崩溃的士兵米格尔因僵尸啮咬失去一臂，同时军人与研究人员的矛盾全面爆发，罗德凶相毕露，将莎拉等人赶入满布僵尸的坑道，米格尔则将僵尸放入中心，失控的局势中，莎拉等人全力求生……','The darkest day of horror the world has ever known.',3500000,34000000,18.025206,6.9,270,96,'1985-07-19','en','/kkFvExiqJ2NnVyqmv7xfmbciGw6.jpg',3.1553191702483527,3,'2026-09-10',2,NULL,NULL),(8409,'单刀直入','A Man Apart','美国和墨西哥的边境的荒漠地带，由于地理位置的优势和两国管理上存在的漏洞，而成为贩毒行动最为猖獗的地方。西恩·维特(范·迪索)从小在街头长大，做事特立独行，是一名出色的DEA(美国药品管理局)缉毒特工，经过长久的艰苦调查和跟踪，他带领着手下的同事终于成功捣毁了一个庞大的贩毒集团，并把集团的龙头老大、臭名昭著的大毒枭卢塞洛(基诺·席尔瓦)送进了监狱……','Love changes a man. Revenge tears him apart.',36000000,44350926,19.854932,5.8,258,109,'2003-04-04','en','/pHlqlcsvzUOixVD9AEruheIHV1a.jpg',3.0612561385307444,3,'2026-09-10',2,NULL,NULL),(8413,'黑洞表面','Event Horizon','未来几十年内，人类探索利用太空的程度不断加深。2040年，利用空间扭曲技术深入宇宙的“新领域号”消失于海王星附近。2047年，新领域号突然在海王星发回讯号，内容似乎为求救，于是当年设计新领域号的威尔博士（Sam Neill 饰）受命乘坐营救船“路易与克拉克”号前去施救。船长米勒（Laurence Fishburnes 饰）不甚友好，所幸路易与克拉克号很快按计划与新领域号对接。虽然生命扫描显示新领域号充满生命迹象，但搜寻之后营救队发现所有船员均死亡或消失，新领域号内制造黑洞的核心动力部分产生的震荡破坏了路易与克拉克号的外壳，营救队被迫暂时停留。新领域号残留的影像记录将当时血腥的一幕呈现给所有人，同时营救队员们被幻象所困——他们分别看到了自己心中无法释怀的伤痛。队员们陷入了崩溃的边缘。然而更令人惊异的是，新领域号似乎具有了生命。威尔博士相信新领域号的变化是由于它进入过地狱，米勒船长为了拯救队员们和威尔展开了生死对决……','Infinite Space - Infinite Terror',60000000,26673242,29.787135,6.5,742,96,'1997-08-15','en','/mKrCQQXtQyZZYrXqTHSLBAyMIS1.jpg',3.395961524967963,3,'2026-09-10',2,NULL,NULL),(8416,'同流者','Il conformista','故事背景设定在1930年代的罗马。一名墨索里尼政权特工，奉命前往巴黎追捕并清除一位在法西斯掌权后逃离意大利的老教授。','Bertolucci\'s Masterpiece about Sex and Politics',750000,0,8.429295,7.6,127,107,'1970-10-21','it','/cLguHl1zGwhAUjDG0VAxAuwVOxV.jpg',2.9728884695403552,3,'2026-09-10',2,NULL,NULL),(8427,'我是间谍','I Spy','美国政府制造了一架名为Switchblade的战斗机原型机，在这架原型机上，政府倾注了全部的财力和精力，它的价值可谓是无法度量。然而，就是这样一架异常重要的原型机，它竟然被偷走了，而美国的顶尖间谍亚里克斯（欧文·威尔逊 Owen Wilson 饰）立刻就奉命上任，追踪原型机的下落，让他没有想到的是，和自己搭档的，居然是一位对谍报工作毫无经验的拳击冠军——凯利（艾迪·墨菲 Eddie Murphy 饰）。\r 　很快，两人就将调查的目标锁定在了一位名叫阿诺德（马尔科姆·麦克道威尔 Malcolm McDowell 饰）的军火商的身上，然而，截止至此，他们只是迈出了整个行动中最简单的一步而已。','Attitude meets espionage.',70000000,33561137,13.267631,5.2,269,97,'2002-10-31','en','/5nYYJuvQjeGb0sUkUAGODG7vTOG.jpg',3.0059329520521167,3,'2026-09-10',2,NULL,NULL),(8435,'一个荒诞的故事','A Cock and Bull Story','根据劳伦斯·斯特恩(Laurence Sterne)1761年的实验性小说《项狄传》改编。一群电影人情急之下，尝试制作长期以来未被考虑拍摄的文学巨着-劳伦斯·斯特恩的《项狄传》。在摄制期间，妻子和他们6个月的孩子出现在摄影棚，扮演项狄的演员被一名小报记者跟随，并被想要他阅读一大堆剧本的代理人纠缠。与此同时，当投资人威胁中断拍摄时，制片人们陷入恐慌中……','Because everyone loves an accurate period piece.',0,0,3.500741,6.2,43,94,'2005-07-17','en','/ww8nEKv3gPOfIkRMGS2A3j566Fr.jpg',2.664966490735855,3,'2026-09-10',2,NULL,NULL),(8452,'第六日','The 6th Day','克隆技术在不远的未来有了长足的进步，但复制人仍是法理上不可逾越的禁区，政府通过《第六天法》严格禁止克隆人。\r 　　飞行员亚当（Arnold Schwarzenegger 饰）拥有幸福的家庭，他出于本能的厌恶那些违背自然规律的基因技术。亚当平时的工作是和搭档送游客上雪峰，这天他们为宠物克隆公司的老板恰克（Tony Goldwyn 饰）服务，搭档顶替亚当驾驶却发生了意外……回到家中的亚当发现居然有一个克隆人顶替了自己的位置参加他的生日宴，莫名惊恐之下他又被来路不明的杀手追杀，他很快明白自己成为了宠物克隆公司的人类复制试验品，做为母体，他面临被消灭的危险。\r 　　在逃亡的过程中亚当与暴力反对克隆人计划的组织合作，成功潜入宠物克隆公司，并控制了克隆人技术的负责人威尔博士……','Are You Who You Think You Are',82000000,96085477,18.447479,5.7,595,123,'2000-11-17','en','/zsmD8sXqMuCb1jjCmDfSSPuTqdF.jpg',3.207891964207317,3,'2026-09-10',2,NULL,NULL),(8456,'永不退缩','Never Back Down','杰克·泰勒（肖恩·法瑞斯 Sean Faris 饰）把父亲的意外身亡归绺为自己的过错，不仅情绪变得难以控制而且与母亲关系变得非常紧张。相对于少年得志的网球明星弟弟，好斗的杰克在母亲眼里只会惹事生非。弟弟得到一大笔奖学金，杰克和家人搬到了佛罗里达的奥兰多市。杰克本想开始安分的生活，却在一次派对上被当地格斗冠军赖安·麦卡锡（凯姆·吉冈戴 Cam Gigandet 饰）激怒，在争斗中杰克被打得很惨。为了一雪前耻，杰克在同学的介绍下开始跟随教练吉恩·罗卡学习格斗术。学习过程中，杰克逞强好斗的性格慢慢发生改变，他开始学会忍耐以及控制自己的情绪，学习格斗找赖安报仇的初衷也已经改变。然而，赖安并不会轻易放过杰克，他们之间注定将要有一场生死格斗。','Win or lose... Everyone has their fight.',20000000,41627431,26.21425,6.4,497,115,'2008-03-04','en','/8oRUTyP1QAtGDMvRpKZyuyFPG0U.jpg',3.2772429951223665,3,'2026-09-10',2,NULL,NULL),(8457,'大兵保镖','Drillbit Taylor','本片根據約翰修斯的小說改編而成，敘述3個高中新生在入學第一天就飽受校園惡霸欺負，為了不讓將來的日子越來越難過，他們在「軍人榮光」雜誌中刊登廣告，希望顧到一名保鏢。沒想到來應徵的是崔比，他以海灘為家、收費低廉，而他將為3個小老闆帶來前所未有的震撼教育。','You get what you pay for',40000000,0,15.055732,5.5,275,102,'2008-03-20','en','/shqO696kFnM8Z4ODa3JglcjP97u.jpg',3.038259804087693,3,'2026-09-10',2,NULL,NULL);
INSERT INTO `t_video_info` VALUES (8461,'趣味游戏','Funny Games','乔治（Tim Roth 蒂姆•罗素 饰）和安（Naomi Watts 娜奥米•沃茨 饰）带着儿子和爱犬来到城外岛某别墅度假，原本美好的假期却被两个不速之客破坏。两个打扮拘谨，文质彬彬的年轻人敲开乔治的房门，向他们借鸡蛋。安热情地接待他们，然而鸡蛋一次次被有意无意打破，他们的电话也被碰倒水中。安的忍耐到了极限，命令他们离开自己的房子。 　　\r 年轻人非但不听，反而变本加厉，开始对乔治一家展开毫不留情的折磨与屠杀……','Let the games begin...',15000000,7938872,15.175289,6.3,545,112,'2007-10-20','en','/5y6tMSV5t7IPoWc587ELtFaXuD4.jpg',3.2611019470716056,3,'2026-09-10',2,NULL,NULL),(8467,'阿呆与阿瓜','Dumb and Dumber','罗伊·克里斯玛特 与好友哈里·邓恩 是一对蠢哥们。二人不仅智商不高，还找不到工作。一次，罗伊得到一个临时工作，驱车送摩登女郎玛丽·斯旺森 去飞机场。罗伊对玛丽一见钟情，怎奈二人身份悬殊。玛丽登上飞机，罗伊发现玛丽遗忘了一个皮箱在飞机场候机厅。于是，为了追求真爱，罗伊决定和哈里一起驾车，向玛丽提到的飞机目的地驶去，他不仅要将皮箱归还，更要追求玛丽。可是皮箱似乎没有这么简单，一伙匪徒盯上了皮箱，试图将罗伊等人置于死地，怎奈罗伊智商不同寻常，阴差阳错地躲过灾难。两个蠢蛋，能否达到他们的目的地。一段傻傻的开心之旅就此展开。','What the one doesn\'t have, the other is missing.',16000000,247275374,35.777067,6.5,1859,107,'1994-12-16','en','/lqi30X0PubuGcXEsksf4q7nUTTN.jpg',3.633759988005407,3,'2026-09-10',2,NULL,NULL),(8469,'动物屋','Animal House','菲博学园中有一个学生组织，参与的全是白种英语系的有钱人，很少人能忍受他们，只有汀沃摩能和伪善的他们相处，沃摩用什么使他们信服？','It was the Deltas against the rules... the rules lost!',2700000,141000000,17.332585,7,418,109,'1978-07-27','en','/fWooBbipMRIKeSRhEzmeaDV0T8H.jpg',3.281546040874127,3,'2026-09-10',2,NULL,NULL),(8470,'迫在眉梢','John Q','生活并不富裕的约翰·Q·阿奇伯德（丹泽尔·华盛顿 Denzel Washington饰）是个工厂里卖命工作的工人。为了养家糊口，两夫妻感情日渐淡漠而导致婚姻濒临破裂。更加雪上加霜的是，不幸降临在了他们9岁的儿子迈克尔身上。\r 　　一天，迈克尔突然在棒球场上昏倒，当约翰·Q把儿子送到医院后才得知：儿子患有严重的先天性心脏病，需要进行心脏移植手术才能保住性命，这高昂的手术费用远远超过他的医疗保险范围。约翰·Q几经沟通未果，医院主管决定把他们从等待移植者的名单中剔除。此举激怒了作为父亲的约翰·Q。他愤然持枪闯入了医院的急诊室，绑架了无辜的医护人员和病人做人质，要求院方立刻为儿子动手术。这场挑战道德与法律的人性之战，并非想象得如此简单…','Give a father no options and you leave him no choice.',36000000,102244770,27.465433,7,594,116,'2002-02-15','en','/iVfA5nR0U3Gt5sIxkXp4GLpwsI8.jpg',3.4033550825350787,3,'2026-09-10',2,NULL,NULL),(8487,'飙风战警','Wild Wild West','一位是作风矫健、机智幽默的联邦特工威斯特（威尔·史密斯 Will Smith 饰），一位是爱耍聪明的易容大师高登（凯文·克莱恩 Kevin Kline 饰），这两个看似一山不容二虎的狠角色却被总统同时召见了，原因是授命他们一同追捕一名神秘毒辣的科学家连环杀手。威斯特和高登只好在摩擦碰撞中培养默契，竟然很快成为一对绝配拍档。经过调查，两人发现原来幕后黑手竟然是曾经的天才博士勒弗里斯（肯尼思·布拉纳 Kenneth Branagh 饰），他因在一次实验中失去双腿，只好永久呆在轮椅上，然而残缺的个性与对社会的怨恨让他开始到处作乱，甚至发明了一架巨型的蜘蛛机器滥杀无辜，并企图谋杀总统，统治美国。危机迫在眉睫，威斯特和高登分头来到新奥尔良，驾驶着一列布满机关的火车迎战蜘蛛博士，一场古怪武器间的斗智斗勇已悄然展开……','It\'s a whole new west.',170000000,222104681,40.748915,5.1,1020,106,'1999-06-29','en','/bZ4jvtTRnsUMXtmyGIGEHgZafV5.jpg',3.2541531096749186,3,'2026-09-10',2,NULL,NULL),(8488,'Hitch','Hitch','Dating coach Alex \'Hitch\' Hitchens mentors a bumbling client, Albert, who hopes to win the heart of the glamorous Allegra Cole. While Albert makes progress, Hitch faces his own romantic setbacks when proven techniques fail to work on Sara Melas, a tabloid reporter digging for dirt on Allegra Cole\'s love life. When Sara discovers Hitch\'s connection to Albert – now Allegra\'s boyfriend – it threatens to destroy both relationships.','The cure for the common man.',70000000,368100420,34.576913,6.4,1665,118,'2005-02-10','en','/uoOfUMRZeW2cx94Ak8HL6Uw1KJ.jpg',3.58357800686534,3,'2026-09-10',2,NULL,NULL),(8489,'拳王阿里','Ali','1964年，年轻的阿里（Will Smith 威尔• 史密斯 饰）凭着高超的拳术，坚韧的毅力战胜尼桑•里斯顿成为了新的拳王！时值越南战争期间，阿里拒绝服兵役，因为“越共没有管我叫黑鬼”。正因为阿里直率的性格，拒绝向自己认为错误的事屈服，阿里因此吃尽苦头：美国政府用尽方法企图将阿里投进监狱；拳击理事会剥夺了阿里拳王的金腰带。在1964至1974这社会动荡的10年里，阿里表现出的坚忍不拔的毅力和决不屈服的独立性不仅对他个人，对拳击界甚至对整个社会都产生了巨大的回响，阿里亦因此成为黑人运动和反越战运动的精神领袖。 1974年，阿里出乎所有人的意料，以34岁的运动高龄，再次参加拳王争霸赛。','Float like a butterfly and sting like a bee.',107000000,87713825,18.866672,6.7,447,157,'2001-12-11','en','/32l3FaCzs8cXWps6hkgNJAcOsP.jpg',3.2695297181362992,3,'2026-09-10',2,NULL,NULL),(8536,'超人2','Superman II','三名氪星反派企图在地球掀起浩劫，而此时超人与露易丝·莱恩正陷入一场期盼已久的恋情——这段关系或许将让超人付出失去超能力的代价。[华纳兄弟]','The Man of Steel meets his match!',54000000,190458706,30.515175,6.5,629,127,'1980-12-04','en','/3xk5cno9BHcnwc97XO9k21aI1Zi.jpg',3.357007721656522,3,'2026-09-10',2,NULL,NULL),(8545,'小嗓门','Little Voice','在北英格兰平民区某幢房子里，住着一个沉默寡言、内向羞涩的少女（Jane Horrocks 饰）。自从疼爱她的父亲去世后，她变得愈加沉默，每天躲在自己的房间内，听父亲留下的唱片；与之相对，她的母亲玛丽（Brenda Blethyn 饰）则是个粗鲁肤浅的女人，她看不惯女儿沉默的样子，因此给女儿取了个绰号——小嗓门。但谁也不知道，小嗓门却拥有一副神奇的好嗓子。她可以逼真模仿茱蒂•嘉兰、玛丽莲•梦露、莎莉•贝雪等名伶的经典曲目，其相似度几可乱真。当然，她的舞台只限于狭小的房间，玛丽根本不知道女儿这副嗓子的价值。玛丽的新男友瑞赛——一个落魄的星探——偶然听到小嗓门的歌喉，惊为天人。为了摆脱困境，他决定抓住这个千载难逢的机会，将小嗓门推向大众舞台……','Finding your own voice can be magic.',0,0,4.647547,6.6,61,97,'1998-11-05','en','/7VxdMxSa3BEAvGl5nLvsgpBwrZH.jpg',2.751892509448546,3,'2026-09-10',2,NULL,NULL),(8584,'上海正午','Shanghai Noon','故事发生在清朝，蓓蓓公主（刘玉玲 饰）由皇帝主婚，必须嫁给皇族亲王，公主心里十万分的不愿意。这时，不怀好意的英文教师安德鲁看出了公主心意，怂恿她出逃美国。公主出逃后，安德鲁留下了一封勒索信给皇帝，所要赎金十万金条。  　　这下皇帝慌了神，马上派出三名大内高手带上赎金前往美国营救公主。大内侍卫黄强（成龙 饰）在公主出逃时曾见过她，不过并没能拦下她，对公主一直不能忘怀。于是，他请求当翻译的叔叔为他说请，让他参与营救行动。侍卫队长批准了他的请求，一行人正式踏上了美国。','The old west meets the far east.',55000000,56932305,25.400935,6.2,735,110,'2000-05-26','en','/kIJK4jGaiLFCpIbMtgYiNxZHK2o.jpg',3.3384096818164926,3,'2026-09-10',2,NULL,NULL),(8587,'狮子王','The Lion King','辛巴是荣耀王国的小王子，他的父亲穆法沙是一个威严的国王。然而叔叔刀疤却对穆法沙的王位觊觎已久。要想坐上王位，刀疤必须除去小王子。于是刀疤利用种种借口让辛巴外出，然后伺机大开杀戒，无奈辛巴被穆法沙及时来救。在反复的算计下，穆法沙惨死在刀疤手下。刀疤一方面别有用心地劝辛巴离开，一方面派人将他赶尽杀绝。辛巴逃亡中遇到了机智的丁满和善良的彭彭，他们抚养辛巴长成雄壮的大狮子，鼓励他回去森林复国。在接下来一场复国救民的斗争中，辛巴真正长成一个坚强的男子汉，领会了责任的真谛。','Life\'s greatest adventure is finding your place in the Circle of Life.',45000000,788241776,90.457886,8,5376,89,'1994-06-23','en','/sKCr78MXSLixwmZ8DyJLrpMsd15.jpg',4.404327930572722,3,'2026-09-10',2,NULL,NULL),(8592,'至尊神探','Dick Tracy','狄克崔西是一位嫉恶如仇的警探，总是身先士卒深入犯罪现场去打击黑帮势力，因此黑帮领袖卡普瑞斯对他恨之入骨，还设下陷阱要陷害他，于是扯出崔西的女友被绑架、俱乐部歌星蜜糖爱上崔西而引起其女友误会、崔西被诬陷杀害检察官……等一连串事端；这位正义警探该如何为自己洗刷冤情、挽回女友的心、以及将歹徒绳之以法呢？','Their turf. Their game. Their rules. They didn\'t count on HIS law...',47000000,103738726,7.859226,5.9,251,103,'1990-06-15','en','/s8VkYusJocRYMMrQboaXkYzLw7l.jpg',3.0360890728817367,3,'2026-09-10',2,NULL,NULL),(8617,'灯红酒绿杀人夜','Prom Night','正值青春年华的美丽少女唐娜•柯派尔（Brittany Snow 布里坦妮•斯诺 饰）却拥有一段悲伤恐怖的过去，她曾亲眼目睹父母和弟弟被人杀害。高中三年的快乐生活以及甜美的爱情让唐娜渐渐淡忘那段伤心往事，如今三年学业已满，盛大的毕业典礼即将召开。唐娜和好友们精心打扮，打算与男友鲍比（Scott Porter 斯考特•波特 饰）迎接那华丽和梦幻夜晚。\r 　　但快乐的舞会因突如其来的停电事故而中断，当灯光再次亮起时，一具男尸出现众人面前。一场恐怖的屠杀随之展开，唐娜不得不再次面对曾经困扰她的血腥恶梦……','A Night To Die For.',0,14796236,9.642041,4.8,167,88,'2008-04-10','en','/pKSeyN02R5khphImEIpAdBjQgEP.jpg',2.895019947620705,3,'2026-09-10',2,NULL,NULL),(8618,'历史系男生','The History Boys','这是一群高智商男生们的故事。二十世纪八十年代，英国北部的一所男子中学里，八个高中生正积极准备着牛津和剑桥大学的招生考试。这几个男生性格各异。有万人迷，自视甚高的Dakin（多米尼克•库珀 Dominic Cooper 饰）；有四肢发达头脑不简单的Rudge（拉塞尔•托维 Russell Tovey 饰）等。他们对课本对知识有属于自己的解读。\r 教他们文学的是个肥胖，教学方式独特的怪老头Hector（理查德•格雷弗斯 Richard Griffiths饰），他主张学生通过课本获得情感上的共鸣和享受，而不是单纯为了升学而读。与他教学模式相反的则是学校新聘请的老师Tom（斯蒂芬•坎贝尔•莫尔 Stephen Campbell Moore 饰）。Tom的目标则是协助这些孩子尽可能考上牛津或剑桥。两种老师的两种教学模式，究竟孰优孰劣，或许并没有一个标准答案。','History. It\'s just one bloody thing after another.',4000000,13401952,3.771652,6.6,66,109,'2006-10-02','en','/a8JNAt4SAmY1c36Ux5zvsmOKh4h.jpg',2.767582506660085,3,'2026-09-10',2,NULL,NULL),(8619,'怒海争锋','Master and Commander: The Far Side of the World','改编自帕特里克·奥布莱恩的“奥布雷与马图林”系列小说，影片背景设定在拿破仑战争时期。罗素·克劳饰演被誉为英国海军骁勇战将的“幸运的”杰克·奥布雷船长，保罗·贝坦尼饰演随船医生斯蒂芬·马图林。他们的战舰“惊奇号”突遭优势敌军袭击，舰体重创，船员伤亡惨重。奥布雷在职责与友情间挣扎，率舰跨越大洋展开高风险的追击，誓要拦截并俘获敌舰。这是一场关乎他声誉的使命——要么成就“幸运的”杰克，要么毁灭他与全体船员。[20世纪福克斯]','The courage to do the impossible lies in the hearts of men.',150000000,212011111,36.973031,6.9,790,138,'2003-11-14','en','/i0YpJSdvln0q3xiEGb1Vmxj8NBi.jpg',3.490222212741182,3,'2026-09-10',2,NULL,NULL),(8643,'驱魔','The Exorcism of Emily Rose','律师艾琳（劳拉·琳妮 Laura Linney 饰）接到一桩官司。一名神父由于用宗教手段——驱魔仪式来治疗女孩艾米莉的重病，因而使得艾米莉耽误了正确的药物治疗时间。法庭上，一场宗教与科学之争展开了。  　　事件的开端，源于19岁女大学生艾米莉（珍妮弗·卡彭特Jennifer Carpenter饰）的恐怖遭遇。她在大学宿舍睡觉时，感觉有灵异恶魔来侵，接下来更为惊悚的事情陆续发生。艾米莉一反常态，她变得双眼发黑，行为怪异，整日活在犹豫恶魔缠身的梦魇中，艾米莉无法控制自己的意志，痛苦得生不如死。家人为她找来精神病医生，却毫无起色。无奈下，请来神父（汤姆·威尔金森 Tom Wilkinson 饰）一探究竟，才得知艾米莉被远古六恶魔上了身。万魔缠身的她，只有通过宗教仪式进行驱魔，才有可能逃出生天。  　　神父的驱魔并没有挽救艾米莉，还引来了控告。无神论者却认为，恶魔缠身是无稽之谈。 ©豆瓣','What happened to Emily?',19000000,144216468,32.602868,6.3,659,122,'2005-09-09','en','/60eylPYjvPJW8MNiZPPhGdJiQJw.jpg',3.3447278938148806,3,'2026-09-10',2,NULL,NULL),(8645,'灭顶之灾','The Happening','一切都发生得很突然，没有预警，没有征兆，散布速度之快更是让人没办法提防，几乎在转瞬间，就遍布了美国主要城市的各个角落，到处弥漫着古怪且可怕的死亡气息，这是一种惊人的破坏力，完全没有任何理由和迹象可循……到底是什么导致这一切发生得如此迅猛？完全摧毁了人类在行为上的自控能力？人类不再具备逃避危险和伤害的本能，也不再能够意识到刀会刺死自己、火会烧死自己、水会淹死自己。没有前因，更没有后果，就这么发生了，有人说这是一场恐怖分子的袭击，有人说是失败的生物实验导致的，也有人说这可能是一件比魔鬼还可怕的武器，或者是一种失去了控制的病毒？可是人类甚至猜不透它的传播途径--水？还是空气？  　　所以说，目前的状况对于在费城的一所高中做老师的艾略特·摩尔来说，他最需要做的不是挖掘为什么会发生这一切的根源，而是要趁着自己还有残留的理智，从这个神秘却致命的环境中逃出来，即使他和妻子阿尔玛正处在婚姻危机中，但在灾难面前，一切争执都应该暂且不提。艾略特与阿尔玛以最快的速度上路，先是坐火车，然后自己开车，与他们一起的还有艾略特在学校的朋友--数学老师朱利安和他8岁的女儿杰丝，一路驱车赶往宾夕法尼亚州的农场，他们将所有的希望都寄托到了那里，希望可以避开这种恐怖且呈持续增长气势的袭击。然而，他们也很快就意识到，无论你逃到哪里，无论你是谁，都不可能得到真正的安全，因为那个可怕的隐形杀手是不会放过任何人的……直到艾略特窥视到了隐藏在表相下的事实真相后，渐渐了解了到底为什么会出现这种足以威胁到人类未来的力量，他决定放手一搏，帮助他那濒临破碎的家庭，得以幸存下来。','We\'ve Sensed It. We\'ve Seen The Signs. Now... It\'s Happening.',60000000,163403799,20.501582,4.9,950,91,'2008-06-11','en','/56AGnNZzIOGPpgf9Lu0LHwNfIKe.jpg',3.1637996393187686,3,'2026-09-10',2,NULL,NULL),(8649,'穿梭阴阳界','Bringing Out the Dead','弗兰克（尼古拉斯·凯奇 Nicolas Cage 饰）是一名急救医生，这个争分夺秒的工作让他在日积月累间承担了许多无形的压力。弗兰克救过很多人的性命，但也眼睁睁的看着很多人无奈的死去。这一次，他的急救对象是一个名叫罗斯（Cynthia Roman 饰）的女孩，不幸的是，罗斯最终死去。罗斯的死给弗兰克带来的前所未有的巨大打击，他甚至出现了幻觉，精神濒临崩溃。在另一次抢救任务中，弗兰克遇见了老人波克（Cullen O. Johnson 饰）和他的孙女玛丽（帕特丽夏·阿奎特 Patricia Arquette 饰），波克的重病让他生不如死，在玛丽和波克的默许下，弗兰克主动结束了老人的生命。而对于弗兰克来说，波克的死带来的是解脱和救赎。',NULL,32000000,0,15.560918,6.6,225,121,'1999-10-22','en','/gE2Q8mL0m0EA6HakRyc92uzSPJn.jpg',3.0808866932938694,3,'2026-09-10',2,NULL,NULL),(8656,'天地大冲撞','Deep Impact','“毕德曼慧星”正朝着地球飞奔而来，给人类致命一击。当局紧急行动，研究出一个最佳方案——由宇航员坦纳（罗伯特·杜瓦尔 Robert Duvall 饰）驾驶“弥赛号”飞船飞往慧星，把预先准备好的核弹放置到慧星上面引爆，以令它化成碎片或是改变轨道。坦纳英勇地完成了任务，却发现并没有取得预期效果。慧星碎成了一大一小两部分，向地球步步逼近。当局迅速采取最后的行动，用“诺亚方舟”计划保住包括人类在内的一些地球物种。这是一个秘密的地下庇护所，只有少数的人可以在这里避开大劫难，等灾难散尽后方重建世界。较小的那部分慧星已经撞向地球，引发山崩地裂，一片世界末日的景象。而跟随其后的大慧星给地球带来的毁灭程度，将远远超乎人们想象，力挽狂澜的人类进入了倒数时刻。','Heaven and Earth are about to collide.',75000000,140464664,34.070054,5.9,855,120,'1998-05-08','en','/4N3T7MN0eZefF6M4IzaFrMrZRi0.jpg',3.3434015982041387,3,'2026-09-10',2,NULL,NULL),(8665,'K-19：寡妇制造者','K-19: The Widowmaker','本片改编自一个真实的故事，叙述了亚里克西·沃斯特赖克奥船长，在冷战最为紧张的时刻接到命令接替原船长米克黑尔·波伦尼，出任核动力导弹潜艇K-19的指挥官。沃斯特赖克奥的任务是不惜一切代价，尽快将这艘维护不当的潜艇投入作战戒备，执行其处女航行。但是沃斯特赖克奥、波伦尼和全艇忠诚的官兵们压根也没想到他们会去执行什么任务。他们也无法料想到失败的代价对于他们以及全世界会意味着什么。那时，一个核反应堆发生故障，一个危险的燃料棒即将溶融、发生核爆炸，这将肯定使艇上所有人员葬身海底。当时他们在北冰洋底游弋，是全体船员们的勇敢，以及船长对国家和对船员们的职责感最终挽救了K-19，避免了一场即将发生的核灾难。','Fate has found its hero.',100000000,35168966,15.625949,6.1,264,138,'2002-07-19','en','/qDNT7c8lJpsgoKT8MWi5MuJ5aja.jpg',3.0800918987021353,3,'2026-09-10',2,NULL,NULL),(8669,'查理·巴特利','Charlie Bartlett','富家小子查理·巴特利（安东·叶利钦 Anton Yelchin 饰）同时是一位点子奇多的中学生，因此履出状况的他常常被各个私立学校拒绝甚至开除，迫于无奈，父母只好让查理进入一所鱼龙混杂的公立学校念书。初来乍到的查理难免被学校里的小霸王欺负得鼻青脸肿，然而很快，鬼马的查理就为自己的小聪明找到了的用武之地。当发现身边的很多同学都需要找人倾诉和寻求开导时，查理摇身变作校园里的心理咨询师，在男生寝室门口挂起了自己的小招牌，专门倾听同学们的苦恼，并给出意见甚至是草率地开起了药房。这个小小心理师的角色不仅给查理创造了一笔不小的财富，也让他成了新学校的宠儿。然而，看似单纯的校园生活可并非想象中那么简单，查理的“小生意”是否一帆风顺，又会有什么麻烦等着他呢？ ©豆瓣','Popularity is a state of mind.',12000000,0,9.779444,6.5,225,97,'2008-02-22','en','/l0jr9jSIW2TYFuunPtDQ1exyjtI.jpg',3.06060097007505,3,'2026-09-10',2,NULL,NULL),(8675,'摩门教徒High上天','Orgazmo','乔(崔帕克饰)是一位年轻的摩 门 教徒，平日都在洛杉矶一带散播福音。不过，原是个替天行道的传教士，却在一次误闯拍A片的片场，让他化身成为一位高知名度的三级片男星。  　　原本就为筹备跟女友莉萨(萝苹莉妮饰)结婚的费用烦恼不已的乔，最后还是接受导演所开出的高片酬，决定豁出去演三级片。在拍片现场，乔的打扮像个精力充沛的超人。由于他始终是瞒着莉萨偷偷拍摄三级片，于是在拍片时所遇到的悲与苦只能对在片中饰演他助手的瘦皮猴宾(戴恩贝区饰)吐露心声。  　　宾其实拥有物理和工程双博士，在家里精心研制了一把「高潮雷射枪」，不过，这支雷射枪又大又重，并非个子瘦小的宾所能举起，只有个子高挺的乔能运用自如。  　　为了试验「高潮雷射枪」的威力，俩人决定到街头去找路人试试看。当他们一出 门 时，迎面看到腰挺不直的老太太，手持扶物缓慢走来，于是俩人窥视四周无人，便瞄准老太太的身躯发射出「高潮雷射枪」。万万没想到，老太太不但抛弃手扶物，甚至挺直着腰手舞足蹈起来， 浑 身散发出如美国舞娘的曼妙热情。  　　自从俩人有了「高潮雷射枪」之后，他们常常扮演成蒙面超人，在大街小巷里整顿社会败类。在这段时间，乔所拍摄的三级片正在推出，没想到一上映就造成轰动，眼见如此成功的票房，三级片导演决定再请乔拍摄续集，没想到乔一口拒绝了导演，甚至不为双倍的酬劳所 心动 ，因为他现在一心一意只想赶快迎娶莉萨回家。  　　不幸的事总是降临在乔的身上，有一天，莉萨经过一家录像带专卖店，看着电视上的电影宣传带，她一眼就认出片中男主角就是自己的男友乔，对于这项突如其来的打击，莉萨决定与乔分手。究竟乔要如何挽回与莉萨的感情呢？乔在往后又会遇到什么三级的爆笑事情呢？','Fighting crime never felt so good!',1000000,0,5.06516,6.2,115,94,'1997-09-06','en','/hu1DbDbrutEuiK9qSR4LExLYQby.jpg',2.8811559200365435,3,'2026-09-10',2,NULL,NULL),(8676,'淘金俏冤家','Fool\'s Gold','本杰明·芬恩·费尼根是一名疯狂的淘金猎人，淘金的热情使他无法如常人一般找份像样的工作养家糊口，他的妻子苔丝也向他提出离婚，并在千万富翁奈杰尔的巨轮上找了份不错的工作。一次意外的沉船事故中，芬恩无意中发现一枚碟子碎片，并推断这来源于一批失落了 300 多年的皇家财产，而这批财产同时也是他与妻子苦寻了 8 年的共同理想，芬恩决定这次决不放弃，然而周围却没有一个人相信他的推测。芬恩唯有想出了一个无厘头却不失精妙的方法登上了奈杰尔的船，并能言善辩地说服了杰奈尔与其女儿，甚至是苔丝也加入寻宝计划。然而与此同时，淘金团伙 Bigg Bunny 和芬恩的前导师已经盯上了他们，一场螳螂捕蝉黄雀在后的淘金好戏，即将上演。','This February True Love Takes a Dive.',70000000,111231041,21.789615,5.4,444,112,'2008-02-07','en','/fwgY054YY9zdQXobHf0dTOyu1SW.jpg',3.1267746576202167,3,'2026-09-10',2,NULL,NULL),(8681,'飓风营救','Taken','特工布莱恩(利亚姆·尼森 饰)深爱着女儿凯姆(麦琪·格雷斯饰)，却由于工作的原因难以给予她日常的父爱，失望的妻子带着女儿改嫁他人。退休后，见识过太多黑暗势力的布莱恩生怕女儿受到伤害，费尽心力的守护她却也因此带给凯姆种种束缚，引发了父女间的矛盾。  17岁生日后，凯姆执意和朋友前往巴黎旅行，无奈的布莱恩只好答应，不成想灾难正等着年轻的凯姆。在电话里亲耳听到女儿被绑架后，布莱恩强忍内心的痛苦只身踏上了营救女儿的征程，而他只有96个小时。','They took his daughter.  He\'ll take their lives.',25000000,226830568,80.879032,7.2,4369,93,'2008-02-18','en','/ognkaUSNgJe1a2pjB4UNdzEo5jT.jpg',4.118367361187018,3,'2026-09-10',2,NULL,NULL),(8688,'蛇眼','Snake Eyes','在布莱恩狄帕玛（Brian De Palmer）的新片[蛇眼]（Snake Eyes）中，亚特兰大市警探瑞克山托洛（尼可拉斯凯吉Nicolas Cage饰），与在国防部位高权重的老朋友一海军司令凯文杜恩（盖瑞辛尼斯Gary Sinise饰），陪同国防部长前往欣赏重量级拳击赛。想不到国防部长竟然遭到暗杀，现场一万四千名观众都有嫌疑、都可能是共犯、也都是目击者。瑞克临危受命，必须在有限的时间内找出...','Believe everything except your eyes.',73000000,103891409,20.790703,5.8,327,98,'1998-08-07','en','/esOspYQAq7uqVpmvG7tMLD53ir6.jpg',3.110153122511916,3,'2026-09-10',2,NULL,NULL),(8698,'天降奇兵','The League of Extraordinary Gentlemen','1899年的新旧世纪之交，欧洲各国处于难得的和平时期，然而一股新近崛起的邪恶势力在首脑“幽灵”的策划下，凭借当时人们闻所未闻的先进武器，在各国间制造误会与摩擦，妄想点燃世界大战的火焰。英国政府邀请隐居非洲的传奇冒险家艾伦·考特曼（Sean Connery 饰）出山解决此次危机，艾伦虽对冒险心生厌倦，但不忍非洲大陆陷入战火，遂与女吸血鬼米娜、化身博士海德、透明人斯基纳、不老不死的英俊青年格雷、尼摩船长、美国特工汤姆·索亚组成绅士联盟，乘坐尼摩船长的鹦鹉号潜艇前往威尼斯阻止幽灵的阴谋。经威尼斯一役，联盟发现此次行动居然是幽灵安排好的棋局，一切只为取得联盟成员各自的超能本领以便实现他更大的野心，被激怒的绅士联盟前往冰雪覆盖下的北国，对幽灵的组织发起了最后的决战……','The power of seven become a league of one.',78000000,179265204,47.436675,5.7,1155,110,'2003-07-11','en','/yUbMtXdJjNk93vnA8MgaE6RFkKV.jpg',3.397707353983855,3,'2026-09-10',2,NULL,NULL),(8699,'王牌播音员','Anchorman: The Legend of Ron Burgundy','在电视播音员被视为权威的昔日年代里，朗•伯甘蒂 是屡屡获奖的圣迭戈王牌播音员，4频道在他的新闻小组的带领下笑傲同行，组内的三个怪家伙只有在朗的身边才能大展拳脚。工作之外，风流成性的朗自然也不会放弃利用知名度勾女，然而一个让他吃瘪的女郎维罗妮卡 居然还是新闻部的新同事，众人先后对维罗妮卡展开攻势结果全军覆没，最后朗用狂野的风度征服了冰美人，维罗妮卡与朗的期望不同，这个有强烈事业心的女人开始在工作中崭露头角并挑战朗的地位，一次车祸后，朗的生活迅速变得混乱起来。影片申明“本片根据真实故事改编”。','They bring you the news so you don\'t have to get it yourself.',26000000,90574188,29.342744,6.7,1493,94,'2004-07-09','en','/1nDZ0qDF7Vqm3pwRuLQRQboqg1C.jpg',3.6064162915494156,3,'2026-09-10',2,NULL,NULL),(8741,'细细的红线','The Thin Red Line','《细细的红线》根据美国作家詹姆斯·琼斯的同名小说改编。1942年，位于南太平洋上的瓜达康纳尔群岛风光如画。美军士兵在岛上登陆，希望能从日本侵略军手中将它收回。美军和日军在这个小岛上展开了大规模的战役，抢夺被日军控制的210阵地的艰巨任务落在了“查理步兵连”的头上。为此，上尉斯塔罗和下达命令的中校塔尔发生了争执。塔尔认为诸位战士应该奋勇向前，将平时训练的技能都展现出来，而斯塔罗则认为在塔尔的勃勃野心驱使下，全连的士兵将走上一条不归之路。可是，斯塔罗最后被解除了职务，众位士兵仍然必须投入这场国家参加的“正义战争”。在长达数月的血腥战役中，步兵连经历了血与火的洗礼，从危机四伏的夜间侦察到艰苦卓绝的露宿野外，从阵地上遭遇的枪林弹雨到生还后医院里承受的心灵创痛，战争中的一切都不可避免的落到他们头上。','Every man fights his own war.',52000000,98126565,40.072583,7.2,771,170,'1998-12-25','en','/3lpxGYOeV4GKnpdQDf5XRrsbyOJ.jpg',3.5368642534557426,3,'2026-09-10',2,NULL,NULL),(8744,'白色鳄鱼','Albino Alligator','三名警察在送三名判刑的犯人入狱前被抢走警枪及杀掉。三名犯人偷车逃到一小镇的酒吧，怎料酒吧原来的非法建筑，根本没有后门，于是三个亡命之徒只好挟持酒吧中的人做人质，向警方索取逃出生命的机会。','They Planned The Perfect Crime... Until It All Went Perfectly Wrong!',6000000,0,2.388683,5.6,45,97,'1996-09-09','en','/jOyV5Rb1MaMUl6XrWWossVTm7BA.jpg',2.6616701020037357,3,'2026-09-10',2,NULL,NULL),(8780,'宝贝妈妈','Baby Mama','凯特（蒂娜·菲 Tina Fey 饰）是个37岁的女强人，但她除了一帆风顺的事业外几乎一无所有，于是起了做单身妈妈、人工授精生子的念头。可惜“不孕”的体检结果击碎了她的梦想，她只好找到代孕中心，选中了一个叫安吉的金发女孩（艾米·波勒 Amy Poehler 饰）为她代孕。安吉受孕成功了，本着迎接孩子的欣喜心情，凯特做了大量物质准备，阅读大量育儿书籍，也迎接安吉住进她家，但是很快两人发现彼此格格不入，安吉是贫民区女孩，有着许多懒散放纵的坏习惯，而凯特是上流社会女强人，非常注重教养规矩。两人的相处从矛盾频发开始，漫长的九个月孕期充满了不平静……','Would you put your eggs...in this basket?',30000000,63833449,11.409124,5.8,205,99,'2008-04-23','en','/xZOwucsL5NInPyFcmqJzytHkaJR.jpg',2.9961801903109766,3,'2026-09-10',2,NULL,NULL),(8810,'疯狂的麦克斯2','Mad Max 2','在未来，因为战争和资源的枯竭，建立在石油之上的工业社会陷入崩溃，人们为了汽油展开生死争夺，这是恐怖如地狱的末世景象。失去了朋友和亲人的麦克斯（梅尔·吉布森 Mel Gibson 饰）以车为家，继续和公路骑士们无休无止的战斗。然而因为他的V8失去燃料，麦克斯只得离开公路，在一个陷阱猎手的指引下，前往一处石油钻井寻找燃料。荒漠中的人们，为了保卫钻井，建立了防御设施对抗骑士休曼格斯一伙，麦克斯从骑士们手中救出了一位奄奄一息的钻井保卫者，结果反被钻井守卫者们扣留，而此时，休曼格斯率领手下将钻井团团包围，危急关头，麦克斯设计对抗休曼格斯。','When all that\'s left is one last chance, pray that he\'s still out there ... somewhere!',2000000,24600832,37.117362,7.3,957,95,'1981-12-24','en','/hUMLRwRSaW1r7fnOrC7MGdegij9.jpg',3.6115115300978617,3,'2026-09-10',2,NULL,NULL),(8814,'毁灭战士','Doom','影片根据1993年同名射击游戏改编而成。  　　2145年火星舰队总部接到从该地区传来的微弱求救信号，而在那里科学探测站正在进行着遗传密码破解的重要实验，一旦该地区失去控制，无疑将会造成整个人类的一场大劫难。特别行动队队长瑞博尔（卡尔·厄本 Karl Urban 饰）、士官长萨吉（道恩·强森 Dwayne Johnson 饰）带着六名队员迅速登陆以救援基地内的幸存者，可当他们进入基地时，发现实验室不仅一片狼藉，而且实验室里满是怪物。更可怕的是，这些行为怪异的生物并非来自外星，而是受到某种未知病毒感染后的人类！面对随时可能被感染的危险，萨吉必须和他的队员们利用手中的每一件武器，深入到实验室中心，找出真相，完成他们的使命。RRTSRTS惟一可以做的是把通往地球的通道用免疫隔离系统封锁，再背水一战，用尽身上每一件终极武器，将这班魔怪一一歼灭……','No one gets out alive.',60000000,55987321,29.261348,5,609,105,'2005-10-20','en','/nijJthoiL7QhrdMcr3QSlKMvMbo.jpg',3.1412979016580014,3,'2026-09-10',2,NULL,NULL),(8818,'Evita','Evita','The hit musical based on the life of Evita Duarte, a B-movie Argentinian actress who eventually became the wife of Argentinian president and dictator Juan Perón, and the most beloved and hated woman in Argentina.','The Most Anticipated Motion Picture Event of The Year',55000000,141047179,7.027139,5.9,120,134,'1996-12-14','en','/rJ6tfaXykwrWHapA7SyM46Lu4ke.jpg',2.8822052079894185,3,'2026-09-10',2,NULL,NULL),(8831,'时空特警','Timecop','科学家们终于终于发明出了时空穿梭机，为了防止有人利用它回到过去改变历史，一支被称为时空特警的队伍成立了，马克斯（尚格·云顿 Jean-Claude Van Damme 饰）就是其中的一员。十年前，马克斯的妻子梅丽莎（米娅·萨拉 Mia Sara 饰）死于非命，凶手至今未被捉拿归案，这成为了马克斯的心结。  　　马克斯决心通过时空穿梭机来调查事件的真相，回到过去的他得知隐藏在幕后的黑手是名叫麦克考姆（马尔科姆·斯图尔特 Malcolm Stewart 饰）的议员，然而此人背景十分复杂，马克斯拿他无可奈何。女警菲尔丁（格劳丽亚·鲁本 Gloria Reuben 饰）成为了马克斯的搭档，跟随他回到1994年，捉拿麦克考姆，哪知道菲尔丁的真实身份其实是麦克考姆的爪牙，马克斯的计划再度失败。','They killed his wife ten years ago. There\'s still time to save her. Murder is forever... until now.',27000000,101646581,13.308127,5.5,282,99,'1994-09-15','en','/ljRz2fNSYloU4avybUQbLmNt5Km.jpg',3.0387823424680414,3,'2026-09-10',2,NULL,NULL),(8834,'连锁阴谋','Conspiracy Theory','杰瑞·弗莱彻（梅尔·吉布森 Mel Gibson 饰）是纽约一名普通的出租车司机，他孑然一身，无所事事。大概是过于无聊，杰瑞的脑中经常幻想关于政府的各种阴谋论，并将它们告诉给每一个乘客。似乎有些弄假成真，他日常生活中也谨小慎微，紧张兮兮。杰瑞迷上了美丽的律师艾丽丝·萨顿（朱丽娅·罗伯茨 Julia Roberts 饰），并经常带着他的那些阴谋论新闻找艾丽丝交流。近一段时间，纽约经常出现水管爆裂的情况，目击到FBI曾在现场出现，杰瑞断定这背后定有什么阴谋。这次他没有猜错，很快一群神秘人物就盯上了这个口无遮拦的男人……','What if your most paranoid nightmares had just come true?',75000000,136982834,22.179658,6.5,431,135,'1997-08-07','en','/4jxANRi2OJYpg6S6s7Z77ZbCPM0.jpg',3.2453890318422327,3,'2026-09-10',2,NULL,NULL),(8835,'律政俏佳人','Legally Blonde','艾丽（瑞茜•威瑟斯彭 Reese Witherspoon 饰）虽然拥有羡煞旁人的美貌——金发，白肤，高挑，精通打扮，就像一个精美的芭比娃娃。美貌和活泼的性格，让艾丽成为了一个完美的女生。她的男友沃纳（马修•戴维斯Matthew Davis饰）条件也不俗，拥有富贵的出身和出众的外表。两人十分般配，却想不到沃纳根本就没把艾丽当成终身伴侣，在他眼中，艾丽只是一个花瓶，除了漂亮别无所长，于是他考上哈佛法学院之后，甩了艾丽，与旧女友重拾旧爱。艾丽不甘心，千方百计也考上了哈佛，她要用行动来证明自己并非徒有外表。哈佛的学习生活非常枯燥，而且这个金发美人还处处受到歧视。令大家大跌眼镜的是，艾丽竟然机智的干了一番事业。','Don\'t judge a book by its hair color!',18000000,141774679,25.43954,6.1,882,96,'2001-07-13','en','/pa5MteLxgMJ0FnY0E1nQdRN750i.jpg',3.3628001169376738,3,'2026-09-10',2,NULL,NULL),(8836,'The X Files: I Want to Believe','The X Files: I Want to Believe','Six years after the events of The X-Files series finale, former FBI agent Doctor Dana Scully is now a staff physician at Our Lady of Sorrows, a Catholic hospital, and treating a boy named Christian who has Sandhoff disease, a terminal brain condition. FBI agent Drummy arrives to ask Scully’s help in locating Fox Mulder, the fugitive former head of the X-Files division, and says they will call off its manhunt for him if he will help investigate the disappearances of several women, including young FBI agent Monica Banan.  Mulder and Scully are called back to duty by the FBI when a former priest claims to be receiving psychic visions pertaining to a kidnapped agent.','To find the truth, you must believe.',30000000,68369434,25.454549,5.5,523,104,'2008-07-24','en','/hF8uFbjiGuUoRJcdWmVV9bmeAxy.jpg',3.174784567723345,3,'2026-09-10',2,NULL,NULL),(8838,'水银蒸发令','Mercury Rising','身为联邦调查局探员的阿特.杰弗里斯因工作失误而被降级。心情沮丧的他被安排执行一项不起眼的差事，寻找一个患自闭症的9岁男孩西蒙。杰弗里斯没费什么事就找到了目标，但这时的西蒙因父母惨遭杀害，精神上受到严重创伤，一句话都说不出来。在某种意义上说，他们两人是同病相伶。所以杰弗里斯很能理解男孩的心情。同时，多年的工作经验也告诉他，此刻的西蒙也面临危险的处境。事实也的确如此，西蒙是个智力超常的孩子，他无意中破解了军方的密码，而那项代号“水星\"的计划是不惜一切代价要保守的机密。这样一来，两个人就成为被追杀的目标...','Someone knows too much.',60000000,0,18.877795,6,368,111,'1998-04-03','en','/lh5SxI8h0wdTvq5LzIEJi6CqTHI.jpg',3.149077628731109,3,'2026-09-10',2,NULL,NULL),(8839,'鬼马小精灵','Casper','某富豪过世，他将大部分财产捐给各种慈善机构，只给自己专横跋扈的继女凯丽根·克里坦顿（凯西·莫拉蒂 Cathy Moriarty 饰）留下一幢位于缅因州的别墅。这幢名为维普斯大府庄园的别墅拥有很久的历史，如今早已破败不堪，无法住人。凯丽根起初愤怒不已，但她偶然知晓别墅内可能藏着金银财宝，于是和律师帝布斯（Eric Idle 饰）欣然前往。令他们想不到的是，这里竟然还住着4个幽灵。财宝当前，贪心之人想方设法要把幽灵赶走……','Get an afterlife',50000000,287928194,19.830132,6,1019,100,'1995-05-26','en','/zfS6zz45Q9Ha1NsmwS8Z2ozg4WR.jpg',3.363678468048924,3,'2026-09-10',2,NULL,NULL),(8840,'龙之心','DragonHeart','武士伯温（丹尼斯·奎德饰）是艾侬王子（大卫·特威利斯饰）的剑术老师，他一心想把王子教导成一位尊从古训的明君。然而，在一次农民叛乱中，老王被杀，王子的心脏也受了致命伤。在王妃的乞求下，一条龙救了王子，分给他半颗心。即位成为新王的王子变得十分残暴。伯温认为这是魔龙的心使王子发生了变化，于是发誓要找这条龙报仇。  　　  　　十多年过去了，伯温在流浪中屠龙无数。最后一次他遇到了强大的对手。苦斗之后，双方成了朋友。伯温这才知道这已是世界上最后一条龙了。伯温给它取名叫苍龙（肖恩·康纳利配音）。在游历中，他们遇到了因父亲被杀而鼓动人民起来反抗的卡拉，双方成了朋友。一次偶遇使伯温看清了艾侬的真面目。他根本不是心魔作怪，而是本性残暴狡诈。这使伯温深受打击。  　　  　　苍龙将伯温等人带到了圣地。在感悟到亚瑟王传下的武士古训后，伯温下定决心要帮助农民起义推翻艾侬的暴政。 因为有苍龙的帮助，人们信心大增。 在战场上，农民起义军英勇作战，打败了国王的军队。  　　  　　老王妃想借杀死苍龙的方法来消灭残暴的艾侬，因为他们的生命是一体的。 然而， 这一秘密却被艾侬发现，老王妃惨遭杀害。伯温带领人们潜入了城堡，彻底打败了艾侬。然而，要杀死艾侬就一定要杀死苍龙。在苍龙的命令与要求下，伯温挥泪杀了苍龙，除掉了暴政王艾侬。  　　  　　死去的苍龙升上天空化作了星星。它的光芒将永远守护着这块土地。','You will believe.',57000000,115267375,31.791979,6.4,535,103,'1996-05-31','en','/rjatcYSCqr9LdNbgg4XFKzWNjzV.jpg',3.3074927930149767,3,'2026-09-10',2,NULL,NULL),(8841,'The Class','Entre les murs','Teacher and novelist François Bégaudeau plays a version of himself as he negotiates a year with his racially mixed students from a tough Parisian neighborhood.','The dynamics of a multicultural class and its teacher will enlighten.',0,28814580,13.437038,6.8,174,128,'2008-09-24','fr','/douDslyUiFSfs9e3ep2ngUo2tsH.jpg',3.0257556151202847,3,'2026-09-10',2,NULL,NULL),(8842,'破网而出','Against the Ropes','故事发生在密歇根州底特律市，杰基（梅格·瑞恩 Meg Ryan 饰）却仍然没有放弃探索生命广度的可能性，她决定成为一名拳击经纪人。长久以来，这一职业一直被男性霸占，如今，腾空出世的杰基能够获得界内的认可和肯定吗？果不其然，杰基的工作受到了诸多的排挤，但她永不言弃的个性使她渐渐获得了客户和同行们的尊敬和钦佩。  　　某日，杰基遇见了名为卢瑟（欧玛·艾普斯 Omar Epps 饰）的次中量级拳手，在一场街头斗殴之中，杰基发现了卢瑟身上隐藏着的拳击天赋。杰基说服了杰基参加职业拳赛，又找来了经验丰富的教练菲利克斯（查尔斯·达顿 Charles Dutton 饰）相助，三人在强敌林立的擂台上打出一条血路。',NULL,39000000,6614280,2.817364,4.5,32,106,'2004-02-20','en','/9CuODYTA3vvrGluaIl0hMPsEIK8.jpg',2.579116512990044,3,'2026-09-10',2,NULL,NULL),(8843,'入侵脑细胞','The Cell','儿童临床医学家凯瑟琳•迪恩（珍妮弗•洛佩斯 Jennifer Lopez 饰）供职于一家研究大脑的医疗研究机构，她的任务是通过高技术手段陷入幼年患者的梦境中，治愈她们幼小心灵中的疮疤。\r 　　警方接到报案，说当地有很多幼女失踪。负责此案的FBI探员（文斯•沃恩 Vince Vaughn 饰）断定，此举为一个连环作案的变态凶手所为。经过调查，警方锁定了犯罪嫌疑人——卡尔•斯塔格（文森特•德奥诺费奥 Vincent D\'Onofrio 饰），但是苦于他守口如瓶，无法救出被他囚禁的女孩。这时，警方联系了凯瑟琳，希望她可以通过梦境的方法，潜入犯人的大脑，找到受害者的所在位置。然而，事情远比想象得更加险象环生……','Enter The Mind Of A Killer',33000000,104155843,25.413955,6,436,107,'2000-08-17','en','/AqvD5NpUhmFszlLSfTG1AmojhWd.jpg',3.1994243718105717,3,'2026-09-10',2,NULL,NULL),(8847,'标准流程','Standard Operating Procedure','bu Ghraib？这个词或许对于大多数的中国人来说都非常陌生，阿布格莱布（Abu Ghraib）监狱，是伊拉克前统治者萨达姆所建造的，据说里面曾经关押迫害了大量的“罪犯”。当然，我对于这段历史并无太大的兴趣，但发生在2003年的美军虐待伊拉克囚犯事件，也发生在这所监狱，这就不得不令人关注了。  这部纪录片调查了巴格达附近Abu Ghraib 监狱的人权丑闻，揭示了所谓“反恐战争”背后不可告人的秘密。其中披露了大量的内幕，让人进一步感受到了战争的荒谬。可笑的是，其中参与虐囚事件的许多士兵到现在还认为他们的行为是在保卫民主。  　　导演介绍：埃罗尔-莫里斯(Errol Morris)1948年出生在纽约，是当之无愧的美国纪录片大师，直接电影的代表人物，多部作品如《细细的蓝线》《时间简史》《又快又贱又失控》都成为纪录片史的经典之作。他执导的《战争迷雾》获得了奥斯卡金像奖。',NULL,0,0,0.888986,6.6,14,117,'2008-02-12','en','/v2QCXsisMLYsozC2qJtYGa3Rvsi.jpg',2.426615857475091,3,'2026-09-10',2,NULL,NULL),(8848,'银行大劫案','The Bank Job','时间：1971年9月。地点：伦敦贝克街某银行地下金库。人物：四男一女。时间倒回数周之前，改行当上汽车交易商的特里过着还算安闲凑合的生活，漂亮的模特旧识玛婷意外找上门来。 美女上门通常不是为了叙旧，而玛婷找来的原因则是为了贝克街的劳埃德银行。价值高达300万英镑的珠宝和现金就锁在银行的地下金库，而由于它们私密保险箱的特殊身份，银行并不直接牵扯在内，拥有者也有99%的可能性不会报警。这简直就是一辈子难遇的良机！虽然金盆洗手的特里早就把危险的过去抛到了九霄云外，也有些担心和银行作对的下场，但近在眼前的大鱼不仅能解决燃眉之急，还能确保他下半辈子无忧，送上门的好东西为什么要拒绝？ 找来了几个不可思议的同谋--比如时尚界人士、三级片男星，仔细研究了银行建筑构造，也顺带打量了周边环境，准备周全之后，这伙临阵磨枪的新手发现：从银行的隔壁打通一条通往金库的地道，是最可行的一个方案。果然，一番磕磕碰碰，他们还真成功潜入。正当几爷们儿在金库里拽着明晃晃的钻石项链，数着大捆的钞票，大开香槟庆祝的同时，他们并不知道：其中一个保险箱中，暗藏了肮脏而见不得光的秘密，而这个秘密将把他们推入延伸至地下犯罪组织、英国政府高层、甚至是高高在上英国皇室的的致命罗网……',NULL,20000000,64822796,30.387754,6.6,697,112,'2008-02-28','en','/tGc0jxK6YKX3DnZgCWgFzITAFiP.jpg',3.396618483294924,3,'2026-09-10',2,NULL,NULL),(8849,'阿尔菲','Alfie','这是一个看似荒诞的爱情悲喜剧。阿尔菲（裘德洛饰）是一个豪华房车司机。英俊不凡的外表，让他在风月场上如鱼得水。身边的女人换了一个又一个，阿尔菲却总在真爱降临的时候临阵逃脱，继续下一轮的风流快活。当有一天，因为某些原因，他急切想要的回头，曾经的爱情还在那里吗？仍然是热闹的节日，阿尔菲是会热闹温馨的拥有爱，还是会一个人孤独的缩在大衣里抵挡城市里迷乱而寒冷的风。他爱这座城市，这座从不缺少爱的城市，会给他留下什么呢？','Meet a man who never met a woman he didn\'t love.',60000000,13395939,15.219263,5.6,248,103,'2004-10-22','en','/cvOHVeuTDiks8v7MjJNMLqhHILi.jpg',3.0275872217441813,3,'2026-09-10',2,NULL,NULL),(8850,'魅影奇侠','The Shadow','一个曾经号称“拉萨屠夫”（字幕翻译如此，实际上影片中他被称为“黑鹰”）的恶棍拉蒙特（鲍德温）被高僧收服，传他法术，后来他回到30年代的纽约，成了魅影侠，扶危济困，白天却是一副公子哥样子。后来同样是高僧弟子，成吉思汗转世的舒云可汗（尊龙）杀死高僧，夺得了具有魔力的金刚杵（老外觉得那就是个Flying Dagger），来到纽约，准备夺得最新技术研制的原子弹，一举实现成吉思汗遗愿，统治世界。两人都是精于心灵控制的大师，展开了各种奇诡的法术斗争。整个纽约成了一场黑暗战争的战场……','The Shadow Knows!',25000000,48063435,8.178203,5.4,138,108,'1994-07-01','en','/xAbFJH3vQYZvUyzzGAtG4OLy492.jpg',2.8899203933119124,3,'2026-09-10',2,NULL,NULL),(8854,'魔鬼任务','Steel','约翰亨利（侠客欧尼尔饰）是军方的治金专家，负责一种新型防卫的武器的研发计划：利用「声波」把敌人歼灭，却不必动到一刀一枪：他和神秘的政府高层研究小组合作，小组领导人是精明的女性电子专家史巴克；就在测试武器的当天，由于小组成员桑纳一时疏忽，导致史巴克半身麻痹，约翰亨利在心力交瘁之余，决定回到洛杉矶，永远离开武器的世界。洛城平静的生活维持不久，他竟在一群抢匪身上见到自己创造的武器，原来，桑纳已经离开政府单位，准备将武器高价售予全球最凶残的恐怖份子，约翰亨利必须在歹徒得逞之前阻止他们，而他最先想到能帮他的人就是躺在医院里的史巴克……','Heroes don\'t come any bigger.',16000000,1686429,2.848727,4.3,48,97,'1997-08-15','en','/ufA7d5LT2rGj58KaZErPhcMkJ4U.jpg',2.651770099076006,3,'2026-09-10',2,NULL,NULL),(8859,'Dude, Where’s My Car?','Dude, Where’s My Car?','杰斯（阿什顿•库彻 Ashton Kutcher 饰）和切斯特（西恩•威廉•斯科特 Seann William Scott 饰）这对儿好友从一夜宿醉中醒来，他们发现家里堆积着陌生人和布丁小山，两人的双胞胎女友家里也被他们搞的一团糟，对昨夜完全失忆的两人为弥补过失，匆匆出门收拾残局赶赴女友家庆祝拍拖一周年，然而他们出门时发现：车不见了。  　　杰斯和切斯特的寻车经历俨然是一场冒险，抽大麻的狗、向他们追讨二十万美元赃款的变性人、笃信外星人阴谋的神秘团伙、卷入贩毒的车子和热辣女郎五人组等等怪异人群和现象层出不穷。显然，杰斯和切斯特在酒醉时创造了非同寻常的故事……','After a night they can\'t remember, comes a day they\'ll never forget.',13000000,73180723,25.316146,5.2,509,83,'2000-12-15','en','/A5FBQplPsSVVvdYn4NHgtWYF8un.jpg',3.132777906502478,3,'2026-09-10',2,NULL,NULL),(8869,'八脚怪','Eight Legged Freaks','故事发生在美国的一个偏远小镇，这里的人们与世无争，过着平静的生活，但是灾难却在一夜之间降临到他们的头上。由于有毒化学废料发生了外泄事故，成千上万的小蜘蛛在一夜之间变得硕大无比、嗜血如命。它们潜入了小镇的角角落落，准备在把这里变成人间炼狱，而在此过程中，只有警长的小儿子麦可觉察到了这一切，但是整个小镇只有采矿工程师克里斯密相信他的话，二人正准备说服小镇上的人们一起消灭这些怪物，却发现他们已经被满山遍野的“八脚怪”给包围了。众人在中断对外通讯的环境下，与铺天盖地的杀人蜘蛛展开生死战……','Do you hate spiders? Do you really hate spiders? Well they don\'t like you either.',0,0,17.834976,5.4,295,99,'2002-07-17','en','/5blAumPPS6vX6zcUlt9oIhOEheK.jpg',3.048544858156598,3,'2026-09-10',2,NULL,NULL),(8870,'红色星球','Red Planet','时间进入2050年，现代文明的发展和人口数量的激增反而令地球不堪重负，原本美丽的星球已经不再适合人类居住。为了寻找新的生存之地，科学家们将目光所定在与地球环境最为相似的火星。在过去的几十年里，他们不断向火星发射无人飞船，试图运用现代科技来改善火星上相对恶劣的居住环境。然而当一切初见成果之时，火星上的机器却突然出现故障，移民火星的计划被迫停滞。地球的状况愈来愈让人担忧，为了尽快排除故障，由凯特·鲍曼（凯瑞-安·莫斯 Carrie-Anne Moss 饰）、罗比·加莱尔（方·基默 Val Kilmer 饰）等顶尖科研人员组成的探险队奉命前往人类从未涉足的红色星球。他们的旅程从一开始便注定充满磨难，队员们不仅要面对恶劣的外星环境，他们的友情和信任也承受着巨大的考验……','Not A Sound. Not A Warning. Not A Chance. Not Alone.',80000000,33463969,13.800656,5.4,267,106,'2000-11-10','en','/vCXNCLrkPwytLue5Hi8IRyFGUfR.jpg',3.0220312685082065,3,'2026-09-10',2,NULL,NULL),(8871,'圣诞怪杰','How the Grinch Stole Christmas','在遥远的松饼山上，有一个胡谷镇，镇民们最爱的圣诞节眼看就要到了，镇上张灯结彩，喜气洋洋，每个人都沉浸在筹备圣诞节的快乐中。然而，在胡谷镇以北的一个垃圾山上，住着一个人人都害怕的“怪物”——格林奇（金·凯瑞 Jim Carrey 饰）。他深居简出，只跟一条狗过活；他心胸狭窄，心脏只有正常人的四分之一大；他讨厌胡谷镇，更讨厌圣诞节。经常捉弄镇民的他，在一次大闹胡谷镇中，认识了小女孩辛蒂（泰勒·摩森 Taylor Momsen 饰）。\r 　　今年的圣诞节正好是胡谷镇建镇一千年纪念，家家户户都在准备迎接这场圣诞盛宴。辛蒂邀请格林奇到镇上参加派对，但是一个误会使格林奇愤怒离开。他决定要报复镇民，在圣诞节那天，他带上他的狗麦克斯，乔装成圣诞老人和驯鹿的样子，悄悄地潜入胡谷镇……','He puts the mean in green.',123000000,345141403,45.419668,6.2,1386,104,'2000-11-17','en','/yZEIB9xSMFm2hVpl1tk6G3GX21N.jpg',3.5257536088172534,3,'2026-09-10',2,NULL,NULL),(8872,'反斗智多星','Wayne\'s World','韦恩（麦克•梅尔斯 Mike Myers 饰）与好友加思（达纳•卡维 Dana Carvey 饰）定期在地下室里和朋友们制作一档展示各种惊奇发明的节目“韦恩的世界”，节目风格怪诞风趣，令他们在当地年轻人之中颇受欢迎。电视制片兼导演本杰明偶然看到了一期韦恩展示吸尘器理发的节目，认为这对儿组合会颇具收视市场，随即开始运作使韦恩、加思登上大银屏。与此同时，韦恩在一次演出中偶遇生于九龙的女歌手卡珊德拉，并为其深深着迷。韦恩与加思的组合顺利签约本杰明，但是合同的约束很快令二人反感，投资方老板的出镜更是让韦恩无法忍受，另一方面，卡珊德拉却为本杰明提供的表演机会而跃跃欲试，与韦恩的关系眼看难以维系……','You\'ll laugh. You\'ll cry. You\'ll hurl.',20000000,121697323,21.815122,6.5,728,94,'1992-02-14','en','/fHwZnFNWR7PaS9t5EBwTvGPeoYQ.jpg',3.3730678170773487,3,'2026-09-10',2,NULL,NULL),(8874,'我最好朋友的婚礼','My Best Friend\'s Wedding','朱莉安（朱莉娅•罗伯茨 Julia Roberts 饰）和迈克尔（德蒙特•莫罗尼 Dermot Mulroney饰）是大学时候的情侣。和大多数的恋人一样，他们的热恋慢慢降温，直到沦为好朋友。于是毕业前有了这样一个约定：如果28岁之前，彼此还是单身，那么就明证了他俩是天造地设的一对，到时候两人就结婚。毕业后二人一直通电，朱莉安以为只是友情。然而迈克尔的婚讯却让她如梦初醒——自己一直都还深爱迈克尔，此时强烈的妒嫉和伤心让她寝食难安。朱莉安决定要改变这一切。她一手设计了一个个令人哭笑不得的“阴谋”，让迈克尔未婚妻当众出丑，离间他们的感情。当发现迈克尔对未婚妻的爱竟然占了上风时，朱莉安在婚礼上做出了疯狂举动，这一招果真气走了新娘。然而事情又有了变化。','It\'s about finding the love of your life. And deciding what to do about it.',38000000,299288605,15.401855,6.3,584,105,'1997-06-19','en','/gmNBnyTKnnTWHQ0tMSCUTfaQsJU.jpg',3.2775566744766893,3,'2026-09-10',2,NULL,NULL),(8875,'伐头岭','Timber Falls','谁也想不到一对年轻夫妇的周末露营会变成一个地狱式的恶梦，而这个恶梦的导演就是一群疯狂而又变态的当地居民…',NULL,2600000,0,3.687574,5.2,38,97,'2007-12-07','en','/v6Lgqh0OYLpeKzbIqxPeDXYstKE.jpg',2.6241635664160112,3,'2026-09-10',2,NULL,NULL),(8879,'苍白骑士','Pale Rider','南北战争后的卡本山谷，一群穷苦的矿工在那里寻找金子，每天他们都要进行艰辛的劳动。公司的老板和当地的驻军首领相互勾结，经常骚扰和欺压这些矿工。就在他们难以忍受，觉得这样的生活几乎没法儿过了时，一个神秘的人物来到了这个山谷。人们对他的经历和名字一无所知，给他起了个外号：“传道士”。“传道士”行侠仗义，成为矿工苦难生活中的一缕亮光。他号召受压迫的矿工团结起来，同老板和驻军首领进行斗争。矿工们在“传道士”的带领下同老板进行了多次较量，将老板的打手逐一铲除，最后，“传道士”在解决了他的仇敌——驻军首领后，只身悄然离去。','... and hell followed with him.',0,41410568,14.574995,7,251,115,'1985-06-28','en','/kpAN5WnDEVWYzMDPkXHTbrDQuak.jpg',3.1359987748612963,3,'2026-09-10',2,NULL,NULL),(8883,'Flame & Citron','Flammen & Citronen','During Nazi occupation, red-headed Bent Faurschou-Hviid (\"Flame\") and Jørgen Haagen Schmith (\"Citron\"), assassins in the Danish resistance, take orders from Winther, who\'s in direct contact with Allied leaders. One shoots, the other drives. Until 1944, they kill only Danes; then Winther gives orders to kill Germans. When a target tells Bent that Winther\'s using them to settle private scores, doubt sets in, complicated by Bent\'s relationship with the mysterious Kitty Selmer, who may be a double agent. Also, someone in their circle is a traitor. Can Bent and Jørgen kill an über-target, evade capture, and survive the war? And is this heroism, naiveté, or mere hatred?',NULL,6500000,0,7.028946,6.8,68,130,'2008-03-25','da','/384NwhPsZbZKOPrF1QPI9ShNj6z.jpg',2.786869486983716,3,'2026-09-10',2,NULL,NULL),(8885,'和巴什尔跳华尔兹','ואלס עם באשיר','酒吧里的一夜，老友向导演阿里吐露反复出现的噩梦：总被26条恶犬追赶。夜夜如此，犬数不变。两人推断这与八十年代初的第一次黎巴嫩战争中以军任务有关。阿里惊觉自己对那段岁月竟毫无记忆。受此谜团牵引，他动身寻访散居世界各地的战友与故人，试图揭开往昔真相与自我迷失的根源。随着探询逐渐深入，记忆开始以超现实的画面悄然浮现。[索尼经典]',NULL,2000000,11125849,14.08251,7.8,291,90,'2008-06-25','he',NULL,3.2431426402634522,3,'2026-09-10',2,NULL,NULL),(8909,'Wanted','Wanted','Doormat Wesley Gibson discovers that his recently murdered father – who Wesley never knew – belonged to a secret guild of assassins. After a leather-clad sexpot drafts Wesley into the society, he hones his innate killing skills and turns avenger.','Choose your destiny.',75000000,258270008,73.82289,6.4,2528,110,'2008-06-19','en','/njy7Pz7ZHZceO7lNfGIHKphY8Hd.jpg',3.7708144184186336,3,'2026-09-10',2,NULL,NULL),(8913,'宠物坟场','Pet Sematary','路易斯·克里德博士的家人搬进了他们梦寐以求的乡间别墅，并在他们财产的后面发现一个宠物公墓。森林深处的被诅咒的埋葬地带使死者重生 - 伴随着“次要”问题。起初，只有家人的猫才能回程，但事故让一个心碎的父亲考虑不可思议的事情。','Sometimes dead is better.',11500000,57469467,20.747994,6.4,407,103,'1989-04-21','en','/ovZsrVWl37fKv34QEqymbku0KzC.jpg',3.2174100502426897,3,'2026-09-10',2,NULL,NULL),(8914,'深海狂鲨','Deep Blue Sea','一群菁英科学家在设备精良的海底研究中心，进行创世纪的医学研究，没想到他们却改变了自然生态，让一群恶鲨的聪明敏捷。这些隐藏在平静海面下的杀手，正蓄势待发，以报复人类为乐趣…。 　　生化制药厂的老板法兰克林（山缪杰克森 饰），是海底研究中心的赞助金主。他提供庞大资金让苏珊麦博士（莎佛朗布洛丝 饰）研究抗老年疑呆症的神奇药丸。麦博士与他的研究小组在孤立海中的海底研究中心，以最古老的生物－鲨 鱼 为实验对象，取其脑中蛋白质，注入人类坏死脑神经细胞，以完成伟大的医学成就。但法兰克林因为投资失利，预备终结研究中心的经费赞助，这对于成功在望的麦博士而言不啻是一个重大打击。在努力说服之下，法兰克林只好要求尽速看到成果，并且前来研究室目睹他们的成就。这时候暴风雨也正在缓缓的向海底研究中心逼近…… 　　为达目的，麦博士早已加大鲨鱼的脑容量，以萃取更多脑蛋白，但同时鲨鱼也逐渐变的聪明，并且越来越强壮。但这不为人知的改变只有麦博士和鲨鱼朝夕相处的潜水夫卡特（汤玛斯杰恩 饰）察觉。 　　虽然卡特曾向苏珊麦提出警语，但苏珊麦为使得实验正常进行，置之不理。终于，在最后一次的成功实验中，向人类展开致命的报复，救援的直升机在风雨中赶到，却也不幸被聪明的巨鲨袭击，一场不可避免的大灾难于是展开……','Bigger. Smarter. Faster. Meaner.',60000000,73648228,22.991269,5.6,604,105,'1999-07-28','en','/snUeXIUt9wqVCV7Drypbt2MUm8h.jpg',3.2074660255478844,3,'2026-09-10',2,NULL,NULL),(8916,'蚁哥正传','Antz','蚂蚁Z对蚂蚁王国的现状十分不满，但天生胆小的他也只能在一边唠唠叨叨，幸好友兵蚁威的保护，瘦弱的Z才不会被欺负。一次偶然机会，Z遇上了逃跑出皇宫的公主宝拉，宝拉因为被母后安排即将与曼将军结婚而不满才离家出走的。在俱乐部里，宝拉主动邀请不起眼的Z跳舞；Z无意中得知了宝拉的身份，跑去和威调换了身份假扮士兵为了能在阅兵中和公主见面。曼将军不仅是个战争狂人，对蚂蚁王国还有着不可告人的阴谋。Z被派上了战场，靠躲在坑内逃过了一劫，被曼将军奉为英雄。但曼将军看出了Z暗恋公主，想把他杀害。情急之下，Z绑架公主逃了出去……','Every ant has his day.',60000000,171757863,41.515702,6,1272,83,'1998-10-02','en','/msRFAcaAuFeCNOcll0JusH12n7L.jpg',3.459545645490137,3,'2026-09-10',2,NULL,NULL),(8920,'加菲猫','Garfield','加菲猫（比尔·默里 配音）是世界上最幸福的一只猫，它愤世又懒惰，整天除了做它热爱的睡觉吃饭之外，就无所事事了。事实就是这样：生活对加菲猫来说简直好得不能再好了，似乎每个人都喜欢它。加菲猫最喜欢做的事情，肯定是坐在电视机前舒服的椅子上，看它喜欢的电视节目。因为这事，它还没少与主人乔恩（布瑞金·梅耶 饰）争夺摇控器呢，不过最后赢的还是它，谁叫它是宝贝宠物呢。','Get ready for frisky business.',50000000,200804534,17.667826,5.2,820,80,'2004-06-10','en','/dC9rbZFIkQxAoNUQ5sE3qGxMpyD.jpg',3.186324219615598,3,'2026-09-10',2,NULL,NULL),(8922,'惊心食人族','Jeepers Creepers','翠施（吉娜·菲利普斯 Gina Philips 饰）与戴利（贾斯汀·朗 Justin Long 饰）姐弟俩正驾车行驶在乡村公路上返家度假，无聊的二人彼此唇枪舌剑解闷，突然，一辆老旧肮脏的货车试图超车，令二人紧张一场。不久他们看到从货车上下来的人在路边小屋前，将一包带着血迹的东西丢入了一个管道，姐弟二人好奇心大起，不顾刚才被货车追逐的经历，悄悄返回小屋查看。戴利落入管道，发现包裹中居然是腹中被缝入了不明物体的活人，大惊失色的戴利与翠施迅速驾车离开，但一个长着翅膀的鬼影开始一路追踪他们。姐弟俩向路上遇到的各种人求助，这却使这场噩梦般的经历变得更加骇人…','What’s eating you?',10000000,59217789,23.316208,6.1,720,90,'2001-07-01','en','/luOVBUWfEiVi1DclNca3XhbWC7E.jpg',3.314128639732283,3,'2026-09-10',2,NULL,NULL),(8942,'温蒂和露茜','Wendy and Lucy','在女孩温蒂（米歇尔·威廉姆斯 Michelle Williams 饰）平凡的人生中，狗狗露西是她最好以及最信任的朋友，那些无法和家长倾诉的苦恼的困惑，温蒂能够很轻易的向露西倾诉。为了赚钱，温蒂决定利用暑假前往阿拉斯加州的一个工厂打工，带着露西，驾驶着一辆破旧的二手车，温蒂上路了。  　　没想到，刚刚来到俄勒冈州，车就报废了，在荒无人烟的小镇上，身无分文的温蒂不仅要为自己找到出路，还要养活露西。无奈之下，温蒂只得干起了偷窃的勾当，毫无经验的她没有悬念的被逮了个正着。在警察局中接受了批评教育后，温蒂惊慌的发现露西不见了，而当她和露西再度相遇时，露西已经有了一个富有的新主人。','On the long road, friendship is everything.',200000,0,0.713906,6.4,64,80,'2008-05-22','en','/cVtF8SW4zMbculTXD52RDvmQAAR.jpg',2.748833061511557,3,'2026-09-10',2,NULL,NULL),(8944,'即时发生','What Just Happened','本（罗伯特·德尼罗 Robert De Niro 饰）是一个失意的好莱坞制片人，当他把全部的筹码压在了他正在制作的那部电影上时，他意识到自己犯了一个巨大的错误。夹在强势的电影公司老板和暴躁的导演杰里（迈克尔·温科特 Michael Wincott 饰）之间，本受尽了委屈，明星经纪人提出的各种匪夷所思的要求也让他气不打一处来，更糟糕的是，麻烦的事情还远远不止于此。  　　为了缓解婚姻上的压力，本和妻子凯利（罗宾·怀特 Robin Wright 饰）决定分居，这一决定本该有利于修复本和凯利之间的感情问题，没想到却让两人之间的距离越来越远，同时，本的女儿佐伊（克里斯汀·斯图尔特 Kristen Stewart 饰）似乎和编剧斯科特（斯坦利·图齐 Stanley Tucci 饰）有着暧昧不明的关系，而据本所知，斯科特是一个彻头彻尾的花花公子。','Admit nothing.',25000000,6673422,8.31653,5.2,127,104,'2008-10-17','en','/Hu5b701NW7i6o7cGquw7Xoz3qK.jpg',2.8657373301582836,3,'2026-09-10',2,NULL,NULL),(8952,'我爱你莫里斯','I Love You Phillip Morris','Steven Russell是一个快乐的已婚警察，他是个虔诚的教徒，每晚都和妻子一起祷告并且在教堂弹奏风琴，还趁著闲暇的时候寻找他的生母，但是当他找到母亲之后，母亲竟然还是狠心的拒绝他，让他非常痛心，于是他决定远离他原本的生活，过著他真正想要的生活---当个快乐的同志，他前往五光十色的迈阿密生活，还交到了一个帅哥男友，但是，他很快的发现，奢侈的生活需要很多的花费，所以他决定铤而走险，开始骗子的生活，但是好景不常，很快的，他因为诈骗行为而锒铛入狱，但是监狱生活不是终点，反而是他爱情的起点，他遇上了他的真命天子Phillip Morris，Steven疯狂的爱上了Phillip，他愿意追随他到天涯海角，包括用尽各种办法越狱。','The Conman who wouldn\'t go straight.',13000000,10652035,19.664699,6.4,503,98,'2009-01-18','en','/4fESsZs3zbOeZHxqRL7Be7QYFO.jpg',3.2651328391382863,3,'2026-09-10',2,NULL,NULL),(8953,'蒸汽男孩','スチームボーイ','十九世纪中叶，维多利亚时代的大英帝国，工业革命方兴未艾，理性与进步似乎凌驾一切，标志了人类文明昂首进步的无限可能。就在第一次万国博览会揭幕前夕，住在伦敦的13岁少年雷•史汀（铃木杏 Anne Suzuki 配音）突然收到发明家祖父（中村嘉葎雄 Katsuo Nakamura 配音）从美国寄来，称之为“蒸气球”（Steam Ball）的神秘动力装置。同时间，英国情报组织，以及一个名为奥哈拉基金会的黑暗组织，都觊觎“蒸气球”所蕴含的惊人力量。雷因此而突遭一伙身份不明的人的袭击，雷只好带着金属球，踏上逃亡之路。为寻求真相雷来到美国，从父亲艾迪（津嘉山正种 Masatane Tsukayama 配音）口中雷得知“蒸气球”依据全新机械理论所设计，可以产生一种划时代的庞大能源，足以供应整个国家所需。路途中，雷邂逅了美丽的富家千金斯嘉丽（小西真奈美 Manami Konishi 配音）。从小娇生惯养，却偏偏爱上了雷，自愿跟随孤独的雷一起踏上了冒险之旅……所谓的科学，究竟是人们的希望？还是将会毁灭一切。本片的制作经历了整整9年，总制作费高达24亿日元。','He will save the future.',20000000,0,9.129808,6.4,102,126,'2004-07-17','ja',NULL,2.8716452022830725,3,'2026-09-10',2,NULL,NULL),(8960,'全民超人汉考克','Hancock','Hancock（Will Smith饰），是刀枪不入的全民超人，犯罪分子对他闻风丧胆。然而这位全民超人每次与犯罪分子对峙都闹得惊天动地，造成严重的破坏，对市民的生命和公共财产都是巨大的威胁。这也就是虽然他有着独一无二的能力却仍然得不到大众认同的原因。他暴躁易怒又不辩解的个性更是激化了矛盾。这天公关经理Ray Embrey（Jason Bateman饰）十分倒霉，不仅他的全球爱心理念推销不出去，更在回家的途中被塞车堵在了火车轨道上，险些就被火车一碾而过。Hancock及时出现救了他一命，不可阻挡地破坏了火车和现场的交通，惹起众怒。Ray却灵光一闪，决定包装Hancock，把他塑造成为一位全民爱戴的英雄。没想到，最大的反对竟然来自他的妻子Mary（Charlize Theron饰），她坚持要Hancock离开她的家庭。事情发展下去，牵扯出令人惊讶的缠绵前缘。','Bad Behavior. Bad Attitude. Real Hero.',150000000,624029371,56.758411,6.2,2961,92,'2008-07-01','en','/7DyuV2G0hLEqHeueDfOqhZ2DVut.jpg',3.720263577493196,3,'2026-09-10',2,NULL,NULL),(8961,'Bad Boys II','Bad Boys II','Out-of-control, trash-talking buddy cops Marcus Burnett and Mike Lowrey of the Miami Narcotics Task Force reunite, and bullets fly, cars crash and laughs explode as they pursue a whacked-out drug lord from the streets of Miami to the barrios of Cuba. But the real fireworks result when Marcus discovers that playboy Mike is secretly romancing Marcus’ sexy sister.','If you can\'t stand the heat, get out of Miami.',130000000,273339556,38.068736,6.3,1564,147,'2003-07-18','en','/wkkZSXdZte1KEf7xuUBcUGhqt6w.jpg',3.556350247621082,3,'2026-09-10',2,NULL,NULL),(8963,'红潮风暴','Crimson Tide','内容描述苏联发生政变时，叛变者控制了一个核子飞弹基地，威胁要攻击美国。美国政府急命阿拉巴马号核子潜艇准备反攻，但就在是否要下达攻击令的关键时刻，潜艇的通讯系统发生故障，无法判断攻击令的真伪。哈克曼饰演的潜艇指挥官决定发射，但新来的副官华盛顿却认为事关重大，应确定讯息再说，不惜为此发动兵变囚禁上司。','Danger runs deep.',53000000,157387195,20.334629,7,498,116,'1995-05-12','en','/9gl4drDLJ27e7sGv8W6Ndbw5R6A.jpg',3.337380339389295,3,'2026-09-10',2,NULL,NULL),(8966,'暮光之城','Twilight','因为父母离异，贝拉随父亲来到小镇生活。在新学校里，贝拉留意到一群举止诡异的怪人，他们特立独行，很是神秘。在实验课上，她遇到了怪人中的一个——金发帅哥爱德华，他俊朗的外形与出众的谈吐令她着迷。在交往中，贝拉渐渐对爱德华产生了感情，但其他怪人对她心存戒备。与此同时，小镇里接连发生死亡事件，贝拉的父亲是警察，负责调查此案。然而，警方的介入并没有阻止死亡威胁的蔓延。在一次意外中，爱德华救出了贝拉。从此，她发现他拥有异于常人的超能力，开始怀疑对方是杀人凶手。在事实面前，爱德华对她坦白，自己是素食吸血鬼，所以凶手另有其人。在杀人凶案的羁绊中，一场人鬼之恋由此展开……','When you can live forever, what do you live for?',37000000,392616625,127.084938,5.8,3561,122,'2008-11-20','en','/3Gkb6jm6962ADUPaCBqzz9CTbn9.jpg',3.8220600736918593,3,'2026-09-10',2,NULL,NULL),(8967,'生命之树','The Tree of Life','在特伦斯·马利克已具传奇色彩的创作生涯迈入第四十年之际，他实现了迄今为止最令人神往的愿景——将一段关于童年、惊奇与哀伤的故事追溯至时间与空间的尽头。马利克将一则少年回忆的故事置于宇宙尺度下展开，回溯至创世之初。影片描绘了1950年代德州一个充满敬畏之心的孩子（新人演员亨特·麦克拉肯 饰）的成长历程，他在严苛甚至专横的父亲（布拉德·皮特 饰）所代表的自然力量与空灵慈爱的母亲（杰西卡·查斯坦，突破性角色）所象征的恩典之间学习前行。在摄影师艾曼努尔·卢贝兹基与美术指导杰克·菲斯克的通力协作下，这部荣获金棕榈奖的影片标志着马利克独树一帜的电影创作理念，既深具个人私密性，又怀抱宇宙级的宏大野心，达到了其艺术追求的顶峰。','Nothing stands still.',32000000,54674226,43.862456,6.5,987,139,'2011-05-18','en','/dmPtkSbkZYprigOFu4xEQ9WEGk.jpg',3.498218981285809,3,'2026-09-10',2,NULL,NULL),(8968,'Boogeyman','Boogeyman','Every culture has one – the horrible monster fueling young children\'s nightmares. But for Tim, the Boogeyman still lives in his memories as a creature that devoured his father 16 years earlier. Is the Boogeyman real? Or did Tim make him up to explain why his father abandoned his family?','You thought it was just a story.',20000000,67192859,11.62423,4.6,191,89,'2005-02-04','en','/8JhDxM72hTV3D4cS3q864DfgILe.jpg',2.9077174930756566,3,'2026-09-10',2,NULL,NULL),(8970,'新老公出差','The Out-of-Towners','亨利和南希·克拉克夫妇的冒险，在纽约市亨利面试工作时遭遇了不幸。','They fell in love 24 years ago... and in the next 24 hours, they\'ll remember why.',75000000,29000000,4.842626,5,45,90,'1999-04-02','en','/wOmLJYh7oOfATE236XpoDfcXhOh.jpg',2.6568025669893025,3,'2026-09-10',2,NULL,NULL),(8975,'海军陆战队员','The Marine','伊拉克战场，美国海军陆战队员约翰•特里顿（约翰•塞那 John Cena 饰）为营救战友独闯虎穴，虽然他的营救成功，却因违抗总部的命令而被强制退伍。约翰解甲归田回到家乡，见到久违的妻子凯特（凯莉•卡尔森 饰）。不愿窝在家里的约翰找到一份保全工作，却在上班第一天就被炒掉鱿鱼。为了排解心中抑郁，夫妇俩相约驾车外出度假。在一间加油站，他们遭遇珠宝大盗罗梅（罗伯特•帕特里克 Robert Patrick 饰）及其同伙。罗梅与路过的警察发生冲突，一番枪战过后，罗梅团伙成功逃跑，并劫持凯特为人质。突如其来的变故唤醒约翰的斗志，他开始独身一人追踪劫匪……','War is Fine But The Fight Continues',20000000,22165608,7.679336,5,163,92,'2006-10-13','en','/fXuX8vCHOUzVhwn0gcqlOdH86C8.jpg',2.897712582554523,3,'2026-09-10',2,NULL,NULL),(8976,'相见恨早','A Lot Like Love','为人谨慎的奥利弗（阿什顿·库彻 Ashton Kutcher 饰）和个性张扬的艾米丽（阿曼达·皮特 Amanda Peet 饰)在洛杉矶到纽约的航班上偶遇。两人一见倾心，但在短暂的相处之后，却又各自回到自己的生活轨道上，只有对彼此挥之不去的影像。初次见面之后，不同的时间，不同的城市，他们又多次相聚、分离。两人变成了无话不谈的好朋友，之间的微妙关系，似乎总是阴差阳错地和爱情擦身而过。在分分合合的七年之后，他们又一次重逢，奥利弗终于意识到了其实艾米丽才是他真正寻找的女孩，但艾米丽已经订婚。他们之间还会拥有单纯的友谊吗？这对冤家是会有情人终成眷属还是，面临再一次分开？','There\'s nothing better than a great romance... to ruin a perfectly good friendship.',30000000,42886719,19.212552,6.5,318,107,'2005-04-22','en','/6xrF9zwEbYiYBOalMO14RAWBLLj.jpg',3.1648803775275463,3,'2026-09-10',2,NULL,NULL),(8978,'血溅13号警署','Assault on Precinct 13','由于亲眼目睹两个要好的搭档在执行卧底任务时被杀害，无法抑制悲伤的杰克·罗尼克（伊森·霍克饰）要求调往普通警署。在心理医生艾莉克丝的定期辅导和自己的努力下，杰克希望能在新的一年里摆脱过去的阴影。再过几个小时就是新的一年了，13号警署这个底特律最老牌的警署也将迎来新生。　　在新年夜之前，警察包围了犯罪头子马里诺·比绍普（劳伦斯·费什伯恩饰），经过一番殊死搏斗后他乖乖就范。被逮捕的比绍普随即被押往一家监狱，一同被押解的罪犯还有瘾君子贝克（约翰·雷吉扎默饰）、小混混斯米利（杰鲁饰）、黑帮成员安娜（艾莎·汉斯饰）。此后大雪突降导致路况相当糟糕，几个当值的警察准备在警署共度新年夜。 　　由于大雪囚车无法安全地抵达目的地，被迫暂时停留在中途的13号警署。尽管这个突发事件搅乱了杰克的好心情，但是在泼辣的女警爱丽丝（德莱阿·德玛托饰）和资深老警察贾斯帕（布莱恩·德尼黑饰）的带动下，13号警署重新充满了新年的祥和气氛。不过两个蒙面枪手的突然袭击，再次打破了这种祥和。　　更让人意想不到的坏消息是，一伙由马库斯·杜瓦尔（加布里埃尔·拜恩饰）率领的涉黑特警，准备血洗13号警署，他们的目标很明确：刚刚抵达此地的比绍普，他将暴露他们的肮脏交易。面对强大而神秘的武装黑警，13号警署的正邪两方不得不妥协，一起在这个糟糕透顶的夜晚并肩作战……','Unite and fight.',30000000,35294470,18.706504,6,311,109,'2005-01-19','en','/dzARBERfzx7BmjeFuVrQpXOKHAm.jpg',3.113481249882784,3,'2026-09-10',2,NULL,NULL),(8981,'法兰基，我的爱','Dear Frankie','法兰基（杰克•麦克艾尔 饰）随母亲莉兹（艾米莉•莫迪默 饰）与外婆搬到了苏格兰。九岁的他是个失聪儿童，聪明懂事，对父亲充满期待。他经常给船员父亲写信，还挂着父亲所在的船的航海图。可是他不知道，一切都是母亲的善意的谎言，虚构了父亲的一切，事实上他们到处搬家就是想要摆脱父亲残酷的家庭暴力。而每一封“父亲的回信”都是莉兹所写的，为了就是不让儿子难过。\r 法兰基得知父亲的船即将靠岸了，想见父亲一面。莉兹没想到真的有这样的一艘船存在又不忍心告诉儿子所有真相，只好在朋友的帮助下找了一名陌生男子（杰拉德•巴特勒 饰）假扮父亲，可爱的法兰基很讨他的喜欢。\r 他们三人相处愉快，正当“丈夫”要离开，莉兹告诉了他法兰基的失聪是因为真正丈夫的施暴。而他们之间也似乎有着若有似无的感情。\r 莉兹拒绝了即将逝世的丈夫戴维要见儿子的要求，不久她便告诉法兰基，父亲已经逝世了。莉兹又取得了儿子的信，原来聪明的法兰基已洞悉一切……',NULL,0,0,3.11319,7,46,105,'2004-05-18','en','/5YRDvaBWBbhTKBYYc7BoOWdW01N.jpg',2.692755378908725,3,'2026-09-10',2,NULL,NULL),(8982,'冬荫功','ต้มยำกุ้ง','纯朴善良的青年阿锦（托尼·贾 Tony Jaa 饰）自幼生长在泰国一个原始丛林中，村民们日出而作，日落而息，过着平和安静的生活。他们以大象作为交通工具和助手，人与动物间建立了深厚的友情。阿锦的父亲曾是一名皇家护卫，他在闲暇之余教儿子学习泰拳，好有朝一日进宫保卫国王。\r 　　父亲精心饲养大象，在泼水节当天拜托村长将大象献给国王。谁知村长图谋不轨，将大象转手卖给黑帮，企图销往澳洲牟取暴利。他们不择手段，还打伤了阿锦的父亲。愤怒的年轻人只身闯入黑帮老巢，与这群不法之徒展开大战。当得知大象正被送往悉尼，阿锦毫不犹豫，只身前往，由此踏上一条充满死亡危险的道路…… ©豆瓣','Vengeance Knows No Mercy',6000000,27165581,11.81832,6.8,167,108,'2005-08-11','th',NULL,3.011892494486129,3,'2026-09-10',2,NULL,NULL),(8984,'桃色机密','Disclosure','汤姆是一家电脑公司制作部主管，并且即将成为副总裁。正当他踌躇满志，准备大干一场时，老板却委任漂亮能干的美迪当副总裁，而她恰恰又是汤姆十年前的情人。更糟的是，这位新上司旧情难忘，不管汤姆已有家小的事实，在自己的办公室里欲强迫汤姆与其好和。第二天汤姆被老板叫去，说美迪要把他对她进行性骚扰的事做内部处理，但汤姆必须调任。汤姆申辩事实正好相反，但是根本没有人相信女会戏男。就这样，汤姆只得动用法律手段。...','Sex Is Power.',55000000,214015089,15.064058,5.9,210,123,'1994-12-09','en','/3lh73oBSXwgtoAQnxB5Qq0bCsp5.jpg',3.016059796125369,3,'2026-09-10',2,NULL,NULL),(8987,'狂野之河','The River Wild','汤姆和盖尔夫妇感情疏远，为了弥合裂隙，他们决定带儿子罗克进行一次激流冒险旅行。途中他们遇到三个可疑的人，韦德、特里和弗兰克。后来做向导的弗兰克突然失踪了。韦德用一些小手段“笼络”住罗克，使罗克拿他当英雄一般崇拜，但汤姆和盖尔始终保持警惕。 　　事实上，韦德和特里是抢劫巨款潜逃的罪犯。他们终于露出了狰狞面目，将一家三口扣做人质，准备顺流而下逃出国境。汤姆逃出虎口，到下游埋伏起来。韦德以为汤姆已死，放心地向下走，没想到汤姆打了他们一个措手不及，船上的盖尔积及配合丈夫，击毙韦德。大难之后，一家人又团结在了一起。','The vacation is over',45000000,0,12.362876,6.1,210,111,'1994-09-30','en','/3tSPLs20BROA3c7IKnVjMv2GuS7.jpg',3.023316440227464,3,'2026-09-10',2,NULL,NULL),(8988,'拒绝再战','Stop-Loss','片名“stop-loss”（止损）原本是金融外汇领域常见的词语，大致指投资失误时设法把损失限定在较小范围内的一种行为。越战之后这个词被美国政府加以利用，“stop-loss procedure”（止损程序）是指军方在其认定的紧急情况下，强迫已经履行完毕服役期间的任务或者有条件退休的士兵延长服役时间的一种行为。根据一项估计，这一备受争议的政策使得大概有7000名原定可以回国的美军士兵被迫滞留在伊拉克。  　　片中由莱恩·菲利普饰演的布兰登·金中士带着荣誉回到了家乡小城并打算重建自己的生活，但是军方在止损程序下强行要求他立即回到伊拉克继续服役，不得已之下布兰登开始了亡命天涯的旅程，逃避一个他原本不惜生命去保护的国家的所谓“正义”。','The bravest place to stand is by each other\'s side.',25000000,11207130,4.002579,6.1,82,113,'2008-03-28','en','/5lR2o3EQ6keYI7R2NtO40fHpvGZ.jpg',2.802081404782881,3,'2026-09-10',2,NULL,NULL),(8998,'老友有钱','Friends with Money','奥利维亚（珍妮佛·安妮斯顿）有三个亲密无间的老朋友，四个女人多年为伴，无话不谈。随着人到中年，朋友的际遇各有不同，却都已然成家立业：她们一个成为著名的服装设计师，一个是当红剧作家，另一个继承大笔遗产，衣食无忧。相比之下，奥利维亚的生活真是一塌糊涂，她不仅单身未婚，而且刚刚丢了工作，生活陷入困境。  虽然带着表面的尴尬与难堪，老友们依然不离不弃，帮奥利维亚介绍工作，介绍男友，却鲜有成效。其实老友们也有自己的烦恼，厌倦工作、厌倦婚姻、厌倦生活，每个人都切实感触着中年的危机与烦恼。奥利维亚游走在大商场，索要着免费的面霜试用装，借着老友的光参加各种高级派对，等待烦恼逝去，等待真命天子的到来。其实不管每个人多有钱，还不是都这样等待着……',NULL,6500000,13368437,11.885221,5.1,128,88,'2006-09-07','en','/8WdKFowmvfxmDJP5uS0Mf7kdskO.jpg',2.8708228480036686,3,'2026-09-10',2,NULL,NULL),(8999,'越轨追击','Derailed','------查尔斯·舒尼(克里夫·欧文饰)是一位成功的广告策划人，同时他也有一个美好的家庭，有很爱他的妻子。在一次旅行中，查尔斯·舒尼在火车上偶然认识了女商人卢辛达·哈里森(詹妮弗·安妮斯顿饰)，两人一见钟情，迅速迸发出了激情。于是，他们倆来到了一个小镇，准备一起过夜。然而，在两人缠绵时，被一个叫菲利浦·拉罗奇(文森特·卡塞尔饰)的人闯进并且要挟，他扬言向双方家庭揭露私情，以此勒索，并且将查尔斯和卢辛达引入了一个危险的阴谋当中。查尔斯和卢辛达的生活受到了极大的威胁，他们必须想出办法扭转局面、拯救家庭。','He never saw it coming.',22000000,57479076,17.7091,6.1,319,108,'2005-11-11','en','/kUFgDtchy8d5m6IXqRi1BivuObe.jpg',3.125656499939087,3,'2026-09-10',2,NULL,NULL),(9003,'养鬼吃人','Hellraiser','英国人弗兰克•科顿在北非发现一个神奇的魔方，回到家后，弗兰克通过某种神秘的仪式打开了魔方和另一个世界的通道，魔鬼赛诺贝斯降临人间，弗兰克也为其所杀。在此之后，弗兰克的哥哥莱瑞和妻子朱莉搬到这座房子里。朱莉是莱瑞的新任妻子，她曾背着丈夫和弗兰克有染。  莱瑞搬家具时不慎弄伤右手，血滴到阁楼地板上，偏巧使埋在下面的弗兰克得以复苏。为了使情人恢复本来面貌，朱莉开始想方设法为其奉上活人的血肉……','He\'ll tear your soul apart.',1000000,14564027,22.583834,6.9,449,94,'1987-09-11','en','/peMiGYfx1hTw5xWx4wSErlhzq4c.jpg',3.3020535275441056,3,'2026-09-10',2,NULL,NULL),(9007,'宛如天堂','Just Like Heaven','温文尔雅的大卫（马克·鲁法洛饰）痛失爱妻，为了忘记悲痛，他决定转租一套古雅而梦幻的公寓，可出乎意料的是，这个举动引来了一个叫伊丽莎白（瑞茜·威瑟斯朋饰）的漂亮姑娘，突然出现的她宣称自己才是这套公寓的拥有者。一头雾水的大卫开始以为这是个误会，他费劲地向伊丽莎白解释，可本来就一团乱的情况却越来越离谱。就当无计可施的大卫考虑把这个纠纷拿到法庭上解决时，伊丽莎白竟然又神奇地突然消失了。 　　从此以后，迷人漂亮的伊丽莎白就幽灵一样随时随地出现在大卫的生活中，对大卫在自己公寓里看不顺眼的生活习惯横加干预。换锁没用、警卫也没辙，因为这个让人咂舌的女人居然还能穿墙而过！焦头烂额的大卫四处调查，一系列的拼凑，大卫开始怀疑伊丽莎白是以前生活在这所公寓里的女医生，因为一次车祸意外死亡。这意味着，我们美丽的伊丽莎白其实是——鬼！ 　　于是，大卫试图一步步地帮助伊丽莎白接受自己已死的现实，并让她能够平静地到达“天堂”。同时，在发现自己不但能够穿墙入壁、被大多数人忽视，还经常如入无人之境后，伊丽莎白也觉得自己的存在似乎有点不合常理。在寻找关于伊丽莎白的真相、帮助她回到属于她的那个世界的过程中，两人深深地相爱了，但不幸的是，这段另类人鬼情的前途有些渺茫，而且，离伊丽莎白“寿终正寝”的时间已经没有多久了！','It\'s a wonderful afterlife.',58000000,102854431,13.43573,6.5,579,95,'2005-09-16','en','/2Y9frFLdtsnDQMoZmyL4imvgMQv.jpg',3.2976536002294115,3,'2026-09-10',2,NULL,NULL),(9008,'The Insider','The Insider','Tells the true story of a 60 Minutes television series exposé of the tobacco industry, as seen through the eyes of a real tobacco executive, Jeffrey Wigand','Two men driven to tell the truth... whatever the cost.',90000000,60289912,26.153669,7.3,481,157,'1999-10-28','en','/pA0kJfqPIDdWPEhAKanFiLJNVgH.jpg',3.376716585941905,3,'2026-09-10',2,NULL,NULL),(9009,'鬼水怪谈','Dark Water','由于丈夫凯尔•威廉姆斯（道格雷•斯科特 Dougray Scott 饰）的不忠，美丽的达莉娅（詹妮弗•康纳莉 Jennifer Connelly 饰）最终选择离婚。长时间的婚姻大战和子女抚养权的争夺让她疲惫不堪，当一切尘埃落定之时，达莉娅带着女儿赛西（艾瑞尔•盖特 Ariel Gade 饰）搬到纽约的路斯维特岛郊区，决定开始崭新的生活。\r 母女二人所租住的公寓虽然稍显老旧，不过价格便宜。中介商莫瑞（John C. Reilly 饰）热情周到，却掩盖不住公寓阴森的气氛。俗话说“便宜没好货”，达莉娅母女恐怕真地撞上了头彩。从莫名其妙的积水，到怪异的响动，各种恐怖离奇事件不断困扰着这对母女，而且愈演愈烈…… ©豆瓣','This Season, The Mystery Of The Darkness Will Consume Your Life',30000000,25473093,14.376463,5.3,274,105,'2005-06-27','en','/iMLA3BNgUovf2LatwVPsStnGZSb.jpg',3.0196529759808843,3,'2026-09-10',2,NULL,NULL),(9012,'蠢蛋搞怪秀','Jackass: The Movie','约翰尼·诺克斯维尔和一班朋友们是疯狂的恶作剧爱好者。他们是无畏的先锋，用身体躯冲撞吊顶电风扇、冲撞铁护栏、冲撞仙人掌；他们是天生的美食家，用鼻子吸成团的芥末、吃自己尿做成的冰激凌；他们是正宗的混球，用鳄鱼和鞭炮和突如其来的抢衣服对待家人、把租来的汽车撞成一堆废铁后还回去、在五金店的待售坐便中拉屎；他们是勇敢的斗士，和女格斗选手对阵结果被击溃、和“四回合拳王”奶油豆在商场里对战结果被殴打的头破血流；他们是旅行家，在日本的街头大跳风骚之舞、身穿熊猫衣和路人打成一片；他们是易容高手，化装成老人或者胖子继续恶作剧……','Do not attempt this at home.',5000000,64282312,14.752587,6.1,345,87,'2002-10-21','en','/9Rb659hvGfmef1xm0mMvDHEBqmf.jpg',3.1358025896829687,3,'2026-09-10',2,NULL,NULL),(9013,'午夜狂奔','Midnight Run','赏金猎人杰克•沃尔什（罗伯特•德尼罗 Robert De Niro 饰）为十万美元决定去纽约搜捕芝加哥黑帮头子吉米•瑟拉诺（丹尼斯•法里纳 Dennis Farina 饰）的会计乔纳森•马杜克斯（查尔斯•格罗丁 Charles Grodin 饰）。乔纳森贪污了吉米一千五百万美元，并将大部分钱捐给了慈善机构。杰克本打算带乔纳森乘飞机于周五午夜前抵达洛杉矶，但乔纳森患有飞行恐惧症，二人只好转乘火车。于此同时，FBI探员阿朗佐•莫斯利（亚菲特•卡托 Yaphet Kotto 饰）、吉米的黑帮手下及吉米的竞争对手，赏金猎人马文（约翰•阿什顿 John Ashton 饰）都在追踪二人。杰克与乔纳森险况横出爆笑风趣的旅程究竟能否顺利完成？\r 　　本片获金球奖最佳喜剧/音乐剧提名及最佳男主角提名（罗伯特•德尼罗）。','This could be the beginning of a beautiful friendship.',30000000,38413606,12.821329,7.2,238,126,'1988-07-20','en','/6V1g3F7W8FLkcJniGF6Qq9GIVb9.jpg',3.132604438045735,3,'2026-09-10',2,NULL,NULL),(9016,'星银岛','Treasure Planet','这天，15岁的少年占美阴差阳错的得到了一张球状星空藏宝图。这张地图记录了宇宙海盗搜刮来的巨额财宝的埋藏地点，于是少年占美踏上了一艘巨大的太空帆船，他的太空历险由此开始。  　　占美遇到了船上的厨师约翰，在约翰的帮助下，占美学习到了很多太空人的知识。在一系列的太空历险与战斗中，占美逐渐掌握在太空生存的技巧与法则。当他们越来越接近宝藏时，占美慢慢发现原来自己一路上的好朋友约翰原来是一个阴险狡诈的海盗。面对朋友的背叛，占美将如何是好？','Find your place in the universe.',140000000,109578115,38.924136,7.2,948,95,'2002-11-26','en','/emJPWGfMKDBMmnhjtMMvPkJUJm9.jpg',3.5957977788478144,3,'2026-09-10',2,NULL,NULL),(9021,'圣诞老人2','The Santa Clause 2','圣诞节马上就要到了，精灵们正在夜以继日地为全世界的孩子准备圣诞礼物。根据圣诞老人法则，圣诞老人必须在今年圣诞节前找到一位妻子，才可以继续他的工作。恰好圣诞老人的儿子查理因淘气被列入本年度坏孩子名单，圣诞老人只得返回家中一面加强对查理的管理，一面寻找可以恋爱的对象。  　　\r 为了不让圣诞老人的离开影响到精灵们的工作，小精灵克里斯和布纳德利用新发明的机器复制了一个塑料圣诞老人，由它代替圣诞老人管理这里的工作，结果事情却渐渐开始失控。','What\'s Christmas Fun without some Reindeer Games?',65000000,172855065,14.646884,5.5,297,104,'2002-10-31','en','/2EAMkz0z1pbr9weOY1Y7buy2AxV.jpg',3.0511171660017027,3,'2026-09-10',2,NULL,NULL),(9022,'爱你至死不渝','All the Boys Love Mandy Lane','曼迪·莲恩是学校里每个男生渴望的对象。当曼蒂接受了同学的邀请，参加位于德州边境乡村小屋的周末摇头狂欢派对，她必须阻止一个个男同学前仆后继向她进攻，然后一个秘密的护花使者自动开始替她除去一个个眼中钉，用其它追求者的血液写下他对曼蒂不悔的爱。','Everyone is dying to be with her. Someone is killing for it.',750000,0,12.284939,5.7,209,90,'2008-02-15','en','/9t7n7K0xqw0gMvrxyhdiyqEF3W1.jpg',2.9953559815682884,3,'2026-09-10',2,NULL,NULL),(9023,'小马王','Spirit: Stallion of the Cimarron','广袤的美国西部地区，野马史比瑞特和他的族群过着平静的生活。然而，当史比瑞特第一次见到人类时，他就被抓去训练成战马。幸好善良的印第安小男孩小溪将史比瑞特从训练营里救了出来，并带他回到了自己部落。在小溪的部落，史比瑞特遇上了斑纹母马小雨。这一次，史比瑞特对回家乡还是留下来感到难以抉择，因为他深深爱上了小雨。小溪察觉出了两匹马的爱情，他决定让他们一起回史比瑞特的家乡。当史比瑞特刚刚依依不舍的和小溪告别后，小溪的部落就遭到了骑兵的袭击。.....','Leader. Hero. Legend.',80000000,122563539,41.670544,7.4,831,83,'2002-05-24','en','/12vGNtCket4azBLobyvIZgxKaTp.jpg',3.594838073604219,3,'2026-09-10',2,NULL,NULL),(9026,'甜心大话王','The Importance of Being Earnest','根据王尔德的同名戏剧《不可儿戏》改编而成。维多利亚时代后期，社会上弥漫着一本正经、虚伪做作的气氛。抱怨生活太沉闷的青年约翰（Colin Firth饰）想出“一人分饰二角”的有趣主意，每次他都告诉周围人自己要去城里探望兄弟厄内斯特，借此离开乡下的府邸；到了城里的交际圈，约翰又给自己取名为厄内斯特。不久，约翰和格林温尔小姐（Frances O\'Connor饰）一见钟情，可是却遭到了格林温尔母亲的阻止，理由是约翰身世不明。心情低落的约翰回到乡下，让他瞠目结舌的是，家里居然在欢迎厄内斯特的到来！原来，这位“厄内斯特”是约翰的朋友阿尔吉（Rupert Everett饰）假扮的，凭着不凡的风度和长期积攒的好印象，阿尔吉居然赢得了约翰的被监护人：少女赛茜丽（Reese Witherspoon饰）的青睐。约翰感到这一切滑稽无比，却又无法当场拆穿阿尔吉的谎言，就在这时，格林温尔找来，两位“厄内斯特”先生的身份就要穿帮了。','Everybody Loves Ernest... But Nobody\'s Quite Sure Who He Really Is.',0,0,7.250379,6.7,127,97,'2002-05-17','en','/87r4e4pL4STfpdjtqNZxlyjvcMd.jpg',2.9301105076814657,3,'2026-09-10',2,NULL,NULL),(9027,'性福大师','The Guru','拉摩（吉米·米斯特雷 Jimi Mistry 饰）是一名舞蹈教师，他只身一人来到纽约，希望能够在这里实现自己的明星梦想。然而，现实是非常残酷的，尽管拉摩在家乡有着不小的名气，但在纽约这座车水马龙的大都市里，他不过是一个无名小卒。走投无路的拉摩在皇后区成为了一名侍者，一次偶然中，他邂逅了名为沙罗娜（海瑟·格拉汉姆 Heather Graham 饰）的女子，沙罗娜是一名成人电影演员，在沙罗娜的带领下，拉摩也加入了这一行业。之后，拉摩又认识了莱克西（玛丽莎·托梅 Marisa Tomei 饰），莱克西为拉摩以后的计划带来了新的思路，在两人的共同努力下，拉摩成为了声名远扬的性学大师。','When he talks, women listen.',0,0,4.093288,5.1,75,91,'2002-08-21','en','/1GQ4nYfRU4rANvCFq4y2o1GExgQ.jpg',2.7551810564145036,3,'2026-09-10',2,NULL,NULL),(9029,'情迷拉斯维加斯','What Happens in Vegas','电影的名字《赌城无记事》 (What Happens In Vegas) 源于拉斯维加斯当地最著名的俗语：“What happens in Vegas stays in Vegas. ”这句话的含义就是，在拉斯维加斯输的再惨，也要把痛苦的记忆留在拉斯维加斯，离开了就别再挂念了。身在拉斯维加斯的男女主角一天早上醒来后，发现自己前一天晚上竟然和对方结了婚，并且还因为一枚硬币赢了很大数目的一笔奖金。两个人想法设法要将其独吞，然而结果却在勾心斗角中陷入了爱河……','Get Lucky',35000000,170000000,38.100488,5.8,923,99,'2008-05-07','da','/nL1IrayCn95H7hKqdb5tHt0vPKE.jpg',3.3512315241342687,3,'2026-09-10',2,NULL,NULL),(9030,'异度见鬼','The Eye','家住洛杉矶的希妮·维尔斯（杰西卡·阿尔芭 Jessica Alba 饰）多才多艺，美丽聪慧，但是上天并未对她过多垂青。童年时发生的一场事故，导致希妮双目失明，从此只能生活在黑暗的世界里。在姐姐海伦（帕克·波西 Parker Posey 饰）的执意劝说下，希妮答应做角膜移植手术，她的世界重见光明。然而好景不长，在慢慢习惯了多彩世界后，希妮经常能够看到一些奇怪诡异的景象，而这些似乎又与死亡紧密联系在一起。在主治医师保罗·福克纳（亚历桑德罗·尼沃拉 Alessandro Nivola 饰）的帮助下，希妮开始踏上一段寻找真相的奇异旅程……','How can you believe your eyes when they\'re not yours?',12000000,56309766,11.135734,5.5,281,98,'2008-02-01','en','/nPZubU9yRcN1tA7bsLm0lt4Ze4N.jpg',3.033182758742636,3,'2026-09-10',2,NULL,NULL),(9032,'冒牌老爸','Big Daddy','法律系毕业生辛尼三十出头，不愿长大和轻浮的性格令女朋友云妮向他提出分手。为了令她回心转意，辛尼向福利署讹称是五岁男孩朱利的生父并收养他，藉以证明自己是可付托终生。岂料云妮去意已决，辛尼只好勉为其难继续收养朱利。辛尼渐渐和朱利培养出感情。这时，福利署揭发辛尼的谎言；为了做“带子洪郎”，辛尼决定踏出人生重要一步……','Nature called. Look who answered.',34200000,234801895,34.86859,6.1,875,93,'1999-06-25','en','/lEYg1X8RjqNB5NWEtodcbK7vm1G.jpg',3.382617092862422,3,'2026-09-10',2,NULL,NULL),(9034,'热力师奶','The Banger Sisters','曾经，苏赛特（歌蒂·韩 Goldie Hawn 饰）和拉维妮娅（苏珊·萨兰登 Susan Sarandon 饰）是摇滚圈里的两朵金花，当时所有活跃的摇滚乐队都和这两个女人有着撇不清的关系，她们肆意的释放着嬉皮士的精神，居无定所环游世界，任谁看了她们的所作所为，都会觉得这两个女人简直是疯了。','Some friendships last forever... like it or not.',10000000,0,6.015354,5.5,62,98,'2002-09-20','en','/pQ7XoEqroHcCQVKP9Xo8JpujuHU.jpg',2.7327773379278573,3,'2026-09-10',2,NULL,NULL),(9035,'撕裂人','Slither','一個美國小鎮，一如往常寧靜安祥。就如同深鎖在美國政府裡的機密X檔案般，外星生物悄悄入侵了這個小鎮…，這類異種前所未見，控制人類的心智再讓其恐怖的撕裂慘死，小鎮人人自危，因為最大的恐懼是「誰才是入侵者…」？','Horror Has A New Face',15500000,0,17.327279,6.3,317,95,'2006-03-31','en','/7rPxKynVxFTsDUNEcPuMsAkCsoq.jpg',3.1416214128024222,3,'2026-09-10',2,NULL,NULL),(9036,'南极大冒险','Eight Below','冰天雪地的南极迎来了三个科考队员，他们要前来搜寻一块陨石，随行的还有八条雪橇狗。南极风景优美，三人惊叹不已，然而危险却也随着美景到来。几天之后，一场暴风雪让他们尝到了苦头，其中一名队员掉进了薄冰下的冰水里面，危在旦夕，幸得雪橇狗奋身相救，队员才脱险——这似乎只是一个小小的序曲，更严峻的考验还在后头。狂暴的风雪在肆虐着南极大地，科考队员进退两难，在恶劣的天气和环境下挣扎求生。而此时，他们只能决定放弃那八条忠实的雪橇狗。当三人安全返回的时候，他们怎样也放不下那些还陷于危难的狗。为了挽救它们，三人沿途折回，回到了那片南极大地……','The Most Amazing Story Of Survival, Friendship, And Adventure Ever Told.',40000000,120455994,24.287306,6.7,542,120,'2006-02-17','en','/yZSFAjo3uaNjYpymYcsXmACtBgS.jpg',3.331838492440981,3,'2026-09-10',2,NULL,NULL),(9042,'魔窟','The Cave','杰克（科尔•豪瑟 Cole Hauser 饰）与泰勒（艾迪•斯比安 Eddie Cibrian 饰）两兄弟是两个酷爱探险的洞窟专家，在生物专家尼古拉（Marcel Iures 饰）和詹妮丝博士（Lena Headey 饰）的邀请下，他们携经验丰富的团队来到罗马尼亚卡尔巴阡山 脉，准备对偶然在这里发现的巨大洞穴以及其中的古教堂进行勘查。\r 探险队员布里格斯（Rick Ravanello 饰）最先入水勘测，但通讯后不久便和队友失去联系。为了安全起见，杰克与泰勒决定全体出发寻找。沿途他们见到各种前所未见的古怪生物，原来在这座封闭的山洞里，竟有着一个完全独立的古生物系统。但是这些发现并未给他们带来太多惊喜，这群探险者已被困在山洞里，而来自未知生物的威胁正渐渐逼向他们……','There are places man was never meant to go.',30000000,15007991,10.756266,5.1,202,97,'2005-08-25','en','/m3mmWSCldBcYS7gCRZdtsDBfyM0.jpg',2.946147512618348,3,'2026-09-10',2,NULL,NULL),(9043,'斯通家族','The Family Stone','斯通家族从英国搬到美国来已有若干年，但是斯通夫妇还保留着英国人保守严谨的风气，一大家子儿女也在父母的影响下变得有点怪里怪气。圣诞节到了，大儿子埃弗特（德莫特•麦隆尼 饰）要带回自己的未婚妻梅瑞迪丝（萨拉•杰西卡•帕克 饰）过来共度圣诞，全家如临大敌。这位可怜的美国姑娘第一天来到就被这家人的阵仗吓了一跳，自己无论从言语都服饰都与这个家庭格格不入，眼看连自己的爱情都保卫不下去了，急中生智的她邀请妹妹朱莉（克莱尔•丹尼斯 饰）来给自己精神支持。然而意想不到的是，每个人很快就都喜欢上了友好、随意的朱莉。事情似乎朝另一个方向飞速发展。  这个圣诞节，能圆谁的梦呢？','Feel The Love',0,0,14.190837,6.2,249,103,'2005-12-14','en','/nlqw53HmTP7o3b2NDttYNOtsK4V.jpg',3.0718459807948792,3,'2026-09-10',2,NULL,NULL),(9045,'见证人','Amen.','根据德国作家Rolf Hochhuth舞台剧《The Deputy》改编，党卫军上尉Kurt Gerstein发现自己为净化水源而合成的化学药剂成为杀人毒气时深感震惊，想要把这种罪行告上中立国或教廷。天主教神父Riccardo是惟一愿意帮助他的人。然而两人的力量不但未能阻止悲剧的发生，还成为了历史车轮下的牺牲品。','Two Men   Two Worlds   One Cause',0,0,5.930533,7.1,75,132,'2002-02-13','fr','/3mtN5NibaTPfYT8nJwTS0vlbSXS.jpg',2.81538751697423,3,'2026-09-10',2,NULL,NULL),(9053,'生死格斗','DOA: Dead or Alive','故事开始于日本一个不知名的宫殿，公主霞不顾众人的阻拦，执意要参加一年一度的“生死格斗”大赛，作为天之骄女的她，目的当然不是那让人垂涎的千万奖金，而是要打探哥哥疾风的下落……疾风在一年前参加“生死格斗”之后，神秘失踪，下落不明。虽然霞身边所有的人都猜测疾风可能已经在武斗中死了，可是不找出真相，霞的内心总是感到一阵阵的不安。拗不过倔强的霞，霞的童年玩伴兼保镖隼也跟随她而去，这次历险，让本来就互相爱慕的两颗心靠得更近。','They\'re the ultimate fighters. They\'ve got the looks. They\'ve got the moves, and the men fall at their feet.',21000000,480314,12.790408,5,205,87,'2006-09-07','en','/hmnz1KOiNmxT6FpYsDYg58HbJwP.jpg',2.9466265094919244,3,'2026-09-10',2,NULL,NULL),(9059,'魔鬼骑士','Tales from the Crypt: Demon Knight','在一部谋杀亲夫的血腥恐怖电影片场，怪模怪样的导演正在吹毛求疵。他面对镜头，开始给观众展示一个新的故事：新墨西哥州的某小镇附近，一名逃逸者用车祸拖延追索后经人指点入住了一家由教堂改造成的旅馆，这里聚集着几个落寞的住客，旅馆服务员杰瑞琳（Jada Pinkett Smith 饰）对工作好不耐烦。追逐者在车祸现场通过警察的帮助寻至旅馆，他声称名为布雷克的逃逸者偷走了他的钥匙瓶，但被拆穿后马上露出了魔鬼的真面目。原来布雷克是救世主的继承者，凭借钥匙瓶内的圣血，布雷克与众人将魔鬼抵御在旅馆之外，魔鬼和召唤魔们不断用强攻与幻术试图闯入，危急关头，布雷克将救世主的使命传递给杰瑞琳…… 　　本片导演在大银幕和电视上皆有《幽冥怪谈》的系列作品，这部《魔鬼骑士》是先声之作。主角Jada Pinkett Smith后来在《黑客帝国》系列中大出风头。','Ready for your deadtime story?',0,0,7.710797,6.7,94,92,'1995-01-13','en','/nK40fPpo789YTb8Ii0BgN7wdmg9.jpg',2.8603980265094058,3,'2026-09-10',2,NULL,NULL),(9067,'坦克女郎','Tank Girl','2033年的未来，由于彗星的撞击，地球成为沙漠废土，整个星球已经11年没有下过一滴雨。水威力公司控制仅存的水资源号令天下，不从者要被榨干水分而死。坦克妹蕾贝卡的反抗军朋友被水威力公司悉数杀害，坦克妹被关进集中营。为了给朋友报仇，坦克妹与飞机妹联手越狱，夺走一辆坦克和一架飞机，率领一群变异基因袋鼠人展开绝地反攻，打垮水威力公司拯救地球。  　　根据英国流行cult漫画改编，一部古灵精怪的后启示录/反乌托邦朋克电影。','In 2033, justice rides a tank and wears lip gloss.',25000000,4064495,8.186936,5.5,138,98,'1995-03-31','en','/dpX63vJd6k5fMTudLaEOw9ffX8h.jpg',2.8947185670231,3,'2026-09-10',2,NULL,NULL),(9072,'小矮人','Little Man','狱中大哥——侏儒罪犯凯尔（马龙•韦恩斯 Marlon Wayans 饰）重获自由，小兄弟波西赶来接他，并带来一项价值十万美元的任务：盗窃女王钻石。波西与凯尔联手将钻石盗走，在撤退时不慎露出马脚，手忙脚乱的凯尔在超市里将钻石扔入了一对夫妻的提包。这对夫妻——丈夫戴洛（肖恩•韦恩斯 Shawn Wayans 饰）非常希望妻子瓦妮莎（凯丽•华盛顿 Kerry Washington 饰）能够生一个孩子，但后者忙于工作无暇顾及婴儿，戴洛颇感失落之余还要忍受岳父的奚落，愈发盼子心切。这边厢，失去了钻石的凯尔和波西无法向雇主交差，想出了化妆成婴儿混入戴洛家偷回钻石的办法。扮成弃婴的凯尔成功进入了戴洛家，但是以一个婴儿的身份盗出钻石，并不是件容易的事情……','Big things come in small packages',64000000,101595121,12.421504,5.3,261,98,'2006-08-31','en','/9KzPw1VN0pMBnq1KIqBaLI8LAB7.jpg',3.0069992881844376,3,'2026-09-10',2,NULL,NULL),(9074,'爷们','The Man','故事发生在罪恶的集中地底特律，德里克（塞缪尔·杰克逊 Samuel L. Jackson 饰）的搭档在执行任务之时不幸遇难，而种种线索均显示，搭档的死和一宗非法军火交易案有着千丝万缕的关联。个性火爆，从来都是以暴制暴的德里克在愤怒之中决定一定要为搭档报仇。\r 德里克接受了一项新的任务，那就是在二十四小时之内找到一批下落不明的武器，然而，和按时完成任务比起来更为困难的是，黑口黑面的德里克得应付他的新搭档——前推销员安迪（尤金·列维 Eugene Levy 饰），即便在误打误撞之中被卷入了危险复杂的案件，安迪依然改不掉自己喋喋不休说个不停的职业习惯。在底特律的街头，这两个男人走到一起，会发生怎样有趣的故事呢？','One guy walks the walk. The other talks and talks.',0,12382362,6.925645,5.4,133,83,'2005-09-08','en','/bnofwLKvg2g7Ky9sSpyTHaan37n.jpg',2.880147523927541,3,'2026-09-10',2,NULL,NULL),(9075,'黑皮书','Zwartboek','二战期间，在纳粹占领下的荷兰，一位犹太歌手潜入盖世太保地区总部，为荷兰抵抗组织效力。然而，当她爱上敌人时，事情变得复杂起来。','To fight the enemy, she must become one of them.',21000000,26193068,13.906611,7.2,277,145,'2006-09-01','nl','/dMpDS9m9IwAsOnXwVigjIjIB9FG.jpg',3.177444447695433,3,'2026-09-10',2,NULL,NULL),(9087,'美国总统','The American President','女主角悉尼是一个政治观点比总统更激进的说客，为一家从事环境保护游说的咨询公司工作。一次她在白宫善意地挖苦总统，碰巧被总统听到。两人一见钟情，总统借用国宴的机会非正式地公开自己的恋爱新动向。当美国总统遇上心仪的女人，不但要面对媒体的批评，更要处理国家大事，她是一位说服政客鼓吹环保的女人，和总统的一段情使她备受压力，而总统却因其余的国家大事忽略了她的环保提案，这样的组合能有完美的结局吗？','Why can\'t the most powerful man in the world have the one thing he wants most?',62000000,107879496,11.056763,6.5,195,106,'1995-11-17','en','/anxzpKmDoexEo5SBRmUvHRTCz7Z.jpg',3.029707817393903,3,'2026-09-10',2,NULL,NULL),(9089,'心情故事','Home for the Holidays','感恩节临近，年轻美丽的单身妈妈克劳迪娅·拉森（霍莉·亨特 Holly Hunter 饰）意外地丢掉了工作，正处在青春期的女儿凯特（克莱尔·丹尼斯 Claire Danes 饰）则坚持要和相爱的男友上床。克劳迪娅倍感落寞，她致电向弟弟汤米（小罗伯特·唐尼 Robert Downey Jr. 饰）哭诉，并通过答录机约定同回家中过节。年近古稀的父母无私地拥抱着这个倦鸟知归的女儿，父亲亨利（查尔斯·德恩 Charles Durning 饰）自由自在，童心未泯；母亲阿黛勒（安妮·班克罗夫特 Anne Bancroft 饰）仍视女儿为孩子，言语中充满着过度而温暖的关怀。  　　不久，汤米和姐姐琼安（辛西娅·斯蒂文森 Cynthia Stevenson 饰）一家以及颇有些怪异的格罗蒂阿姨（杰拉丁·卓别林 Geraldine Chaplin 饰）相继赶回家中，温馨的气氛却渐渐为争吵和矛盾所取代……','We\'ll do it every year..until we get it right',0,17519169,4.031585,6.3,39,103,'1995-11-02','en','/3zqlKdOttWyExzopVxglz50Vjxq.jpg',2.646878234184321,3,'2026-09-10',2,NULL,NULL),(9092,'白雪公主','Snow White: A Tale of Terror','由英、美两国联合制作，在美国的有线电视台首播然后才在各地电影院推出公映的另类童话片，将传统的《白雪公主》故事改拍成黑暗、阴沉和血腥的哥德式恐怖片，主角也变成了西格尔内．维弗饰演的狠心后母。她因为从魔镜中知道继女儿竟然比她还漂亮，乃用毒苹果加害继女，并用各种巫术魔法将她折磨。全片在捷克等东欧国家的森林实景拍摄，映象风格具有浓厚的中世纪色彩，流露出一种阴冷的邪恶气氛。导演迈克尔．科恩与女主角都表现出色，分饰父女的萨姆．尼尔和吉尔．贝洛对比之下较弱。','The fairy tale is over.',26000000,0,4.810621,6,62,100,'1997-07-18','en','/4OInbOnTli896gHIlqZ6IUwfqs.jpg',2.7417912328284104,3,'2026-09-10',2,NULL,NULL),(9093,'The Four Feathers','The Four Feathers','The story, set in 1875, follows a British officer (Heath Ledger) who resigns his post when he learns of his regiment\'s plan to ship out to the Sudan for the conflict with the Mahdi. His friends and fiancée send him four white feathers which symbolize cowardice. To redeem his honor he disguises himself as an Arab and secretly saves the lives of those who branded him a coward.','Freedom. Country. Honor. Passion. To save his best friend, one man must risk everything he loves.',35000000,29882645,10.10364,6.5,159,132,'2002-09-08','en','/bfmpeRr9LTXzBC2dpC89FE5uavK.jpg',2.979743670701733,3,'2026-09-10',2,NULL,NULL),(9095,'致命化身','Mary Reilly','根据著名《化身博士》的故事改编，经由博士家中女佣玛丽的观点来诠释。茱莉亚以朴素的女仆装贯穿全场，变色龙约翰马可维奇饰演身心交战疲累的化身博士。  童年時期經常被父親虐待的瑪莉，在母親安排下，成為名流人士家中的女傭，以躲避家暴危害。從十二歲起開始幫傭的她，自從成為傑高博士的身邊忠心女僕後，第一次感到身心上的「安全感」。就在此時，傑高博士突然宣佈他的助手艾伍德將進駐研究室，協助他的實驗進行。面對傑高博士的仁慈寬厚與艾伍德的致命吸引力，瑪莉身陷其中不可自拔。此時，殺人命案緊接發生，瑪莉明瞭該是自己面對悲慘童年陰影，以及慾望所帶來危險的時分...','The untold story of Jekyll and Hyde',47000000,12379402,6.067212,5.7,74,104,'1996-02-23','en','/cW5wTiv5fdtBOd22utmAIZBCMS3.jpg',2.7737565315322996,3,'2026-09-10',2,NULL,NULL),(9096,'燃烧的天堂','Medicine Man','在南美洲人迹少至的热带雨林深处，经过六年的努力，生化学家罗勃肯贝尔博士，研发出一种癌症治疗法面临一项重大的医学突破。一位冷静的女性学者当可琳博士历经一段艰困的会面；这一对互相厌恶的伙伴终于产生了共同的尊重，而实际的爱苗也滋生于这片异国风情的热带雨林中…','He turned his back on civilization. Only to discover he had the power to save it.',40000000,0,7.021871,5.8,114,106,'1992-02-07','en','/lkHqtViTG4Zzh7i9rrtHJGTnEUg.jpg',2.867479749841637,3,'2026-09-10',2,NULL,NULL),(9099,'鬼头大兵','Sgt. Bilko','艾力比高中士，是一个天生的赌徒，虽然他的正职是巴达基地的机动车组主管，但其暗地里在兵营从事赌业。  长期以来，两种身分毫无冲突，但有一日，已荣升为少校的仇家霍高连突然来基地举行检阅及核点帐目，而一向帐目不清的比高今次如何化解这场挑战，且看他的赌运如何？','All he ever wanted was an honest week\'s pay for an honest day\'s work.',0,0,5.417787,5.5,94,90,'1996-03-29','en','/q4zmVdQq35ZBj8uyxsU2RCPOQxo.jpg',2.8140140003534335,3,'2026-09-10',2,NULL,NULL),(9100,'魔女游戏','The Craft','16岁的少女萨拉·贝利（Robin Tunney 饰）外表阳光美丽，却拥有不为人知的痛苦过去。为了寻找生活的希望，她随父亲（Cliff De Young 饰）和继母从旧金山搬到了位于洛杉矶的一座城市，并在当地一所教会学校继续学业。在这里她遇见三个打扮和举止都很怪异的女孩——（费尔鲁扎·鲍克 Fairuza Balk 饰）、邦妮（Neve Campbell 饰）和罗谢丽（Rachel True 饰）。周围的学生没有一个愿意与她们交往，甚至盛传他们就是恐怖的女巫。萨拉无意间展现出的超能力引起南希等人的注意，这四个本质上有着相同气质的女孩很快便走到一起。  　　他们希望召唤万物之灵马农（Manon），让其进入自己的身体，由此可以使糟糕的生活变得好转起来。只是，世界上绝对没有免费的午餐……','Welcome to the witching hour.',15000000,24769466,19.517239,6.3,380,101,'1996-05-03','en','/8bW2RdRkloYtEPhbQZN4wcdmJP4.jpg',3.1880990109345033,3,'2026-09-10',2,NULL,NULL),(9104,'蛮牛战士','Buffalo Soldiers','故事发生在1989年的德国，斯图加特郊区。此时正值柏林墙摇摇欲坠之际，雷艾伍德，一位陆军第三十七补给军营的战士，从长期在军队里形成的奴隶状态中苏醒，将注意力投向日益繁荣的网上黑市交易。这时一位新士官长（Scott Glenn）上任了，他明确宣布将整顿整个基地低迷的士气。艾伍德不在乎，他自信能搞定这个新官，并且爱上新官的女儿娜宾。然而一次偶然的机会，一批价值五百万的失窃军火从天而降落到了艾伍德的手中，他决定冒风险大赚一笔……','War is hell... but peace is f*#!%!! boring.',15000000,0,6.329672,6.5,93,98,'2001-09-08','en','/qNl4T8xxC0xDeX8JFJVCBzH4Kg8.jpg',2.8479623547726636,3,'2026-09-10',2,NULL,NULL),(9208,'断箭','Broken Arrow','狄坚上尉是美国空军一名十分出色的机师，他英勇善战，屡获殊荣，却始终得不到升职。他的好友希尔中尉是他的副手， 但在拳台上， 希尔每次打赌均输给狄坚。在一次执行飞行任务时，狄坚计划劫持隐型战机上的两枚核导弹，他将希尔打出了机舱，投下核弹，飞机在自然公园坠毁。 希尔的降落伞救了他一命，但他却遭到公园巡警泰莉的拘捕，经过打斗与说服，他终于让泰莉相信了他。狄坚早已有内应和接应，他成功地找到了两枚核弹。希尔和泰莉击毁了直升机，并机智地劫持了运载核弹的汽车，将核弹藏到了一个废铜矿之中。但在慌乱之中，核弹被启动了。狄坚一伙赶到，抢走了另一枚核弹，却将希尔他们关在矿井下，试图让他们被核弹炸死。希尔和泰莉从地下河逃出矿井。地下核爆产生了巨大破坏力， 白宫与国防部震惊之余，不得不答应狄坚要求巨款的威胁。 希尔与泰莉分头追踪狄坚，泰莉跟上了狄坚的火车， 却被抓住。千钧一发之际，希尔找到了政府，并驾直升机前来营救。但政府的军队并未能阻止狄坚，反以失败告终，希尔只能孤军奋战。他与泰莉破坏了狄坚出逃的直升机，在无路可走的情况下，狄坚困兽犹斗，孤注一掷。他启动了核爆密码，妄图同归于尽。希尔赶到，两人再次打赌，只要希尔赢了他就可以关掉启动装置。斗智与斗勇之后，希尔最终取胜，在两列火车即将相撞之际，他关闭了启动装置，并逃出了车厢，而狄坚则得到了应有的下场。 在一片狼藉之中，核弹安然无事，劫后余生的希尔和泰莉紧紧地拥抱在一起。','Prepare to Go Ballistic.',50000000,150270147,22.769108,5.7,453,108,'1996-02-09','en','/l51hUOmE6WxHYJWLayDhMLtg3Qp.jpg',3.1668571201279163,3,'2026-09-10',2,NULL,NULL),(9257,'反恐特警组','S.W.A.T.','Jim Street(Colin Farrell 饰)是洛杉矶S.W.A.T(反恐特警组)的一员，在和搭档Brian Gamble（Jeremy Renner 饰）执行一次人质解救任务时，由于Brian的失误，人质向政府要求赔偿，Brian一怒之下离开警队，Jim也被调到别的部门，二人之间的友谊就此结束了。  　　两年过去了，Jim靠自己不懈努力终于回到S.W.A.T。此时的S.W.A.T由Sgt. Dan \'Hondo\' Harrelson（Samuel L. Jackson 饰）担任指挥官，有五名队员，并打破了没有女人的规则，出现了S.W.A.T.的第一名女队员——一位单亲妈妈 Chris Sanchez(Michelle Rodriguez饰)。  　　在Harrelson的指导下，五名队员接受几个星期的严酷训练之后，Jim和队友开始执行首次任务：看管声明狼籍的大毒枭.Alex Montel (Olivier Martinez 饰)——一个经营贩毒，军火走私，洗黑钱等罪恶勾当的罪犯。  　　Alex Montel被洛杉矶警察逮捕后，仍然打算在引渡之前逃脱法网，他通过媒体许诺：任何能把他解救出来的人将可以得到1亿美元的巨额赏金。为了得到这笔钱，亡命徒们展开了行动，其中包括Jim的老搭档Brian Gamble，S.W.A.T的队员们面临最艰巨的挑战，而关键时刻，队员的变节和上级领导的不信任，几乎将他们逼入绝境。','You\'re either S.W.A.T. or you\'re not.',80000000,116643346,34.052253,5.8,770,117,'2003-08-08','en','/8lwO0u35LySYTvS9ELJx8t1vnZ9.jpg',3.306899567734717,3,'2026-09-10',2,NULL,NULL),(9260,'欢迎来到科林伍德','Welcome to Collinwood','来自克里夫兰黑街的五名笨贼决定团结起来大干一票，但最终发现失去的比获得的还多。','Five guys. One safe. No brains.',1200000,0,3.582733,6.2,50,86,'2002-05-24','en','/7XyvoOopwWwDCWOcItOQiAwm30b.jpg',2.6974351456737686,3,'2026-09-10',2,NULL,NULL),(9266,'碧海娇娃','Blue Crush','安妮·玛丽是一名普通的美国姑娘，她酷爱冲浪，除了冲浪，她的生活中似乎再没有别的东西。为了参加今年的全美冲浪高手大奖赛，她远离温暖舒适的家，住在夏威夷海滩边一间简陋的棚屋里。和她同屋的，还有另外两个志趣相投的女孩。三个女孩开始了刻苦的训练，每天清晨，她们就告别了温暖的被窝，扛着冲浪板走向大海。比赛的日期一天天逼近，安妮却遇到了自己心目中的白马王子—一个叫做马特·托尔曼的男孩，生活就是这么奇妙，爱情总是在不期中降临。与马特的接触很快让安妮的生活失去了平衡，她发觉自己开始慢慢陷入爱河，而心中的理想和抱负在心爱的人面前越发失去了原先的吸引力。爱情，冲浪，她到底该如何取舍呢？','Three Friends, One Passion, No Limits.',25000000,51842679,11.42943,5.6,159,104,'2002-08-08','en','/iZSw0JVG0cIFuZoTHuQU3nmGT4k.jpg',2.934396409984693,3,'2026-09-10',2,NULL,NULL),(9268,'蒸发密令','Eraser','艾伦（范妮莎·L·威廉姆斯 Vanessa Williams 饰）是美国最大武器武器制造公司西历公司的高级职员，她慢慢发现了这加公司的一些黑幕――该公司生产了一种明令禁止的武器并在黑市交易。FBI利用艾伦获得了一些证据，艾伦成了本案的关键证人。鉴于这间公司的势力，证人保护中心派出了法警约翰（阿诺·施瓦辛格 Arnold Schwarzenegger 饰）前往保护艾伦。当约翰赶到艾伦家时，杀手正在谋杀艾伦。约翰救出了惊魂未定的艾伦，并告诉了她现在情况。安顿好艾伦后，约翰前往酒吧和同伴罗伯特（詹姆斯·凯恩 James Caan 饰）见面，罗伯特告诉约翰因为保护证人的计划泄漏，要重新安排，并要求约翰一起行动。向来都是独立完成任务的约翰起了疑心，他慢慢开始觉得这件事背后的势力并不简单。','He will erase your past to protect your future.',100000000,242295562,24.507987,5.6,543,115,'1996-06-21','en','/aXnFyiD4LssfVewDMaTLIJlF2mT.jpg',3.191885819731109,3,'2026-09-10',2,NULL,NULL),(9271,'时空悍将','Virtuosity','1999年，洛杉矶，政府执法技术中心开发出用于训练警探的模拟机原型。这种虚拟现实模拟机装载有最先进人工智能技术，使用者需追捕电脑生成罪犯席德6.7（结合人类所有邪恶，集一百八十三个连环杀手的精华合制而成的），以锻炼他们的侦探技巧。但是，这个复杂的“猫捉老鼠”系统有一个致命的后果：狡猾的席德6.7摆脱束缚离开了虚拟空间，进入现实世界作恶，他只要有玻璃就可以自动修补身上的一切损伤。\r 　　前警察帕克巴恩斯被认为是最有机会制服席德6.7的人。在犯罪行为专家卡特的帮助下，柏加必须穿梭于现实和虚拟世界，在新千年之前抓住席德。同时，柏加在席德6.7身上发现了杀害他的妻子和女儿的变态杀手的影子。这场猎人的游戏变得复杂起来，赌注也更加高昂。\r 　　为了自由，也为了向死而复生的仇人复仇，柏加走上了追杀斯达之路。 追捕过程中，狡猾的席德6.7让柏加再度被关入狱中，又借他的名义杀死狱警让柏加逃跑。面对警方和罪犯的双重压力，柏加义无返顾地继续追踪着。然而，这是一个“杀不死”的家伙，柏加最后能否获胜呢？','Justice needs a new program.',30000000,24048000,5.301589,5.4,163,106,'1995-08-04','en','/nVpBaM6gzqZQnaueZ2yV3PkD2WC.jpg',2.9142236037512896,3,'2026-09-10',2,NULL,NULL),(9273,'神探飞机头2','Ace Ventura: When Nature Calls','浣熊行动的失败，使得艾斯·文图拉（金·凯瑞 Jim Carrey 饰）决定前往喜马拉雅山深处进行修行，锻炼自己避免再出现浣熊行动这样的事情出现。时间过得很快，一天艾斯突然收到邀请。非洲瓦查蒂族的神物——一只白色大蝙蝠不知所踪。他们希望艾斯重出江湖，帮他们找回这只白蝙蝠。一踏上非洲大陆，艾斯就立马展开了侦查工作。首先，艾斯将怀疑对象锁定在了野生动物园园长身上，可是却苦苦无法找到证据，只好作罢。接着他又怀疑是部落巫师偷走的，但是也是毫无头绪。在笑料百出的调查过程中，艾斯发现白蝙蝠原来在两个盗猎者手上，而其幕后首脑居然是大使。原来，为了独占蝙蝠粪这一稀有资源，他不惜挑起部族之间的矛盾，以此来从中渔利。最终，艾斯借助动物们的帮助，将白蝙蝠完璧归赵。','New animals. New adventures. Same hair.',30000000,212385533,34.391792,6.1,1099,90,'1995-11-10','en','/sErewZuIq5tiELdDlKDj7jbhMTk.jpg',3.430761656428843,3,'2026-09-10',2,NULL,NULL),(9275,'斯慕奇之死','Death to Smoochy','尽管兰道夫（罗宾·威廉姆斯 Robin Williams 饰）身为儿童电视节目主持人，但他的真实性格和形象远远不如节目中所表现出来的那样善良与和蔼可亲。为了参加他住持的儿童节目，家长们必须向其行贿，与此同时，兰道夫亦与黑帮分子之间有着千丝万缕的联系。  　　东窗事发之后，电视台开除了兰道夫，为了弥补兰道夫的不良形象为电视台所带来的名誉损害，他们必须尽快找到一个可以信赖、身世清白的人作为替代，就这样，好运落在了一个名为莫普斯（爱德华·诺顿 Edward Norton 饰）的三流演员身上。让所有人没有想到的是，莫普斯居然就此一炮而红，这让生活一落千丈的兰道夫恨红了眼，他的心中只有一个想法，那就是除掉莫普斯。','Get ready for an unexpected hit.',55000000,0,11.329727,5.9,132,109,'2002-03-28','en','/wrwwuNLITsA5N5cVnA3ftvHFqHj.jpg',2.9118025740476106,3,'2026-09-10',2,NULL,NULL),(9276,'The Faculty','The Faculty','When some very creepy things start happening around school, the kids at Herrington High make a chilling discovery that confirms their worst suspicions: their teachers really are from another planet! As mind-controlling parasites rapidly begin spreading from the faculty to the students\' bodies, it\'s ultimately up to the few who are left – an unlikely collection of loners, leaders, nerds and jocks – to save the world from alien domination.','Take me to your teacher.',15000000,40283321,21.535126,6.2,492,104,'1998-12-25','en','/7TjEgFrLWlDjdJ88aGDAnerpcQ8.jpg',3.2399655872466115,3,'2026-09-10',2,NULL,NULL),(9277,'骗中骗','The Sting','1936年9月的芝加哥，一名年轻的骗子为给遇害的搭档复仇，与一位骗术大师联手，设局从一名犯罪头目银行家手中赢取巨额财富。','...all it takes is a little confidence.',5500000,159616327,28.500913,7.9,622,129,'1973-12-25','en','/gwqNNZjRngR8mL9emIMwDPbgJM3.jpg',3.5431066671708176,3,'2026-09-10',2,NULL,NULL),(9279,'一路响叮当','Jingle All the Way','圣诞节快到了，工作缠身的霍华德（阿诺•施瓦辛格 Arnold Schwarzenegger 饰）早把对儿子的圣诞礼物的承诺丢到脑后了――他答应送儿子一个涡轮超人作为圣诞礼物。这天，经过妻子提醒，霍华德一大早就跑到玩具商店抢购，在玩具商店他结识了同为人父的邮递员马鲁（辛贝 Sinbad 饰），无奈涡轮超人一早都已卖光，两人只能失望而归。  　　失望的霍华德几乎没有勇气回家面对儿子失望的眼神，他在街上游荡时碰上了冬季大游行。稀里糊涂的他竟被拉上了花车扮演真人版涡轮超人，按照要求涡轮超人可以挑选一名孩子参加游戏并奖给他一个涡轮超人，霍华德在人群中发现了儿子的身影。当他将儿子挑选上来时，却发现扮演反派的竟然是马鲁，马鲁亦要尽力为儿子争取这最后一个涡轮超人！','Two Dads, One Toy, No Prisoners.',60000000,129832389,22.501041,5.5,575,89,'1996-11-15','en','/52GLevbiaXzaXgxdKwjKG2si6TW.jpg',3.1843160050379313,3,'2026-09-10',2,NULL,NULL),(9280,'蛇蝎美人','Femme Fatale','劳拉•艾什（丽贝卡•罗梅恩 饰）与同党瑞西、威克斯在一个电影首映式上，出尽法宝要偷取一条佩戴在某位明星身上，价值千万的钻石项链。劳拉在神不知鬼不觉之间，把仿品成功与真品掉包。同党打算把女明星杀掉，劳拉出手阻止。两人较量时，劳拉把同党一同杀死了。劳拉害怕自己的身份被识破，处处躲藏，直到她得到了另一个身份。一个与她相貌惊人相似的女人莉莉自杀了，当她目睹这一切之际，她决定盗用莉莉的身份。借助新的身份她的新生活开始了，她也成为了他人的妻子，感受到了家庭的温暖。尼古拉斯（安东尼奥•班德拉斯 饰）的职业是记者，自他认识劳拉后，他对劳拉鲜为人知的过去非常感兴趣，企图要揭开她的底细，也因此迫使劳拉要对自己的身份作出抉择……','Nothing is more desirable or more deadly than a woman with a secret.',35000000,16838910,9.07278,6.2,142,114,'2002-11-06','en','/35srQ0QzS0flyNHsO0EuW1lPxXy.jpg',2.936451500005889,3,'2026-09-10',2,NULL,NULL),(9281,'证人','Witness','美国宾州妇女丽狄因丧夫而带着儿子山姆投奔亲友，但是在车站的洗手间内，山姆偶然目睹了一场谋杀。警长约翰•布克赶到现场，他希望山姆能作为证人指证凶手，不料最终山姆暗地里指认的竟是警探麦克菲。布克将情况告诉了上司保罗，希望得到政府的协助，可是在回家的路上，布克受到了麦克菲的袭击，并中弹负伤。原来保罗与麦克菲是一伙的，他们侵吞公款，倒卖毒品，并要杀了布克灭口。布克勉强将丽狄母子二人送回她的父亲家阿门部落，自己却因伤势过重而昏迷。在丽狄的精心照料下，布克身体恢复的很快，与阿门部落日益融洽，跟丽狄互相也萌生了爱意。不久保罗一伙终于找到了他的下落，并赶来要将他杀死，布克利用熟悉的地形干掉了保罗的手下和麦克菲，保罗却挟持丽狄作人质而抓住了布克，这时周围的村民赶到，保罗终于放下了枪。警察到来之后终于真相大白，可是布克必须离去了，因为他有自己的生活方式，毕竟他不是属于这里的人，他和丽狄只能依依惜别。','A big city cop. A small country boy. They have nothing in common... but a murder.',12000000,68706993,19.195399,7,375,113,'1985-02-08','en','/kOymD1rChAMykmDVEzJpIh4OYS7.jpg',3.2556962364634083,3,'2026-09-10',2,NULL,NULL),(9282,'11点14分','11:14','杰克（亨利•托马斯 Henry Thomas 饰）夜间酒后驾驶，并用手机打电话聊天，却没曾想在穿过立交天桥时，一具尸体从天而降。便利店员达菲（萧恩•哈特西 Shawn Hatosy 饰）因女友雪莉（瑞切尔•蕾•库克 Rachel Leigh Cook 饰）怀孕打胎一事向同事步兹（希拉里•斯万克 Hillary Swank 饰）借钱，假扮便利店被劫。而此前，一群少年从便利店买了过期的甜甜圈，夜晚飙车并向他人投掷甜甜圈取乐。已打算和达菲分手的雪莉不顾父亲弗兰克（帕特里克•斯韦兹 Patrick Swayze 饰）的劝阻，擅自出门与新男友艾伦（布雷克• 海仑Blake Heron 饰）偷欢。所有一切的松散事件，都在11：14分相互交织，互为因果，让结局出人意料，不可思议。','Fate can change in seconds.',6000000,0,15.048067,6.8,206,86,'2003-05-16','en','/6hEbDnHEdGOeen0OVDe60Cli7aW.jpg',3.0716020418914667,3,'2026-09-10',2,NULL,NULL),(9285,'哈啦上路','Road Trip','散漫的乔西·帕克（布雷金·梅耶 Breckin Meyer 饰）与同在一所大学的美丽女孩贝丝·瓦格纳（艾米·斯玛特 Amy Smart 饰）共度春宵，甚至还拍摄录像带留念。千不该万不该，这个没脑子的家伙错把这卷录像带当作校园介绍的录像带寄给了远在奥斯汀的女友蒂芬妮·安迪森（瑞雪儿·布兰切德 Rachel Blanchard 饰）。乔西吓得神魂出壳，连忙叫上好友凯尔·爱德华斯（DJ·奎尔斯 DJ Qualls 饰）和E.L.（肖恩·威廉·斯科特 Seann William Scott 饰）和他绝走奥斯汀，去截停那盘足以毁灭一切的录像带。三个精力旺盛的家伙一路通行，惹出不少的笑话……  　　本片荣获2000年德国Bogey奖、2000年青年选择奖最佳银幕说谎者（Tom Green）。','The greatest college tradition of all.',16000000,119754278,14.759948,5.9,542,93,'2000-05-19','en','/jee4eY5tZprI0V18S6PXUloBzSk.jpg',3.207685633155231,3,'2026-09-10',2,NULL,NULL),(9286,'Final Destination 3','Final Destination 3','A student\'s premonition of a deadly rollercoaster ride saves her life and a lucky few, but not from death itself – which seeks out those who escaped their fate.','This Ride Will Be The Death Of You.',25000000,117719158,31.64341,5.8,974,93,'2006-02-10','en','/8JPWcAGejr68WgXJzRVJKGKYfeC.jpg',3.3469093854235377,3,'2026-09-10',2,NULL,NULL),(9288,'龙与地下城2：龙王的愤怒','Dungeons & Dragons: Wrath of the Dragon God','助于惊人而又成功的游戏角色,龙与地下城2:龙王的愤怒进入幻想史诗的黑暗与空想世界之内更深入的你。 当邪恶的男巫士 Damodar 冒着一个危险的旋风偷他宣布对抗 Ismir 的王国手里一个复仇计划的元素时候。 Berek ，一个被装饰的战士和 Melora, 一位业余者女魔法师接合拥有智力，智能，荣誉和力量对抗 Damodars 可怕人的军队.......',NULL,0,0,4.901936,4.8,36,105,'2005-01-01','en','/n5PV0sV4Nd0eCZMcRfipeNhTpmz.jpg',2.6105354895061565,3,'2026-09-10',2,NULL,NULL),(9289,'最长的一天','The Longest Day','影片描绘的是登陆诺曼底的第一天所发生的事件，所谓最长的一天是该片分别从盟军和德军双方面的角度同时描述诺曼第登陆这一历史战役的来龙去脉，以及双方在此期间的重要反应，手法平实，场面逼真，让整个事件在观众眼前重现。并且粗中有细，无论是决策的将军还是登陆的士兵都写得栩栩如生：英军战机低空飞过攻击；美国特种部队遭德军射击；一群法国修女冒着枪林弹雨抢救联军伤兵……备战实况规模之伟大，叫人印象深刻；过程中做出的种种错误决定及各项导致这场历史上其中一场最浩大战争的大小事件，影响深远。','This is the day that changed the world... When history held its breath.',10000000,50100000,19.524972,7.2,234,178,'1962-09-25','en','/nvqV8QUxiTqsVTlDdurH7QXCd6O.jpg',3.143229941647943,3,'2026-09-10',2,NULL,NULL),(9290,'鳄鱼邓迪在洛杉矶','Crocodile Dundee in Los Angeles','“鳄鱼先生”迈克·邓迪（保罗·霍根饰）是一个著名的冒险家，同时还是一个猎杀鳄鱼的好手，平时他居住在澳大利亚内陆的荒郊野外。现在他要开始最新的一次冒险，目的地就是与他平时的生活环境完全不同的新世界——美国加利福尼亚的洛杉矶。事情的起因源自于邓迪的妻子苏（琳达·柯兹洛斯基饰），这个土生土长的美国女子本来与邓迪一起过着平静悠闲的生活，但有一天她临时被父亲的报馆派往美国采访一宗谋杀案件，而静极思动的邓迪也决定要带儿子出去见见世面，于是一行数人出发前往洛杉矶，当到达了纸醉金迷的大城市后，来自荒野的鳄鱼先生当然亦少不免地闹出一连串的笑话……','He heard there was wildlife in L.A. He didn\'t know how wild.',21150000,39438674,6.081772,4.7,146,92,'2001-04-12','en','/hwt6iJjPuXRDKJON5s9G9pdfPbu.jpg',2.8605758359742146,3,'2026-09-10',2,NULL,NULL),(9291,'最长的一码','The Longest Yard','保罗是曾经红极一时的职业橄榄球选手，但因某种原因被关进了监狱。狱长酷爱橄榄球，却生性残忍。他专门雇佣那些擅长玩橄榄球的狱警，让他们和犯人们进行“比赛”。可怜的犯人们根本不是对手，保罗来到球队中后，顶住压力，团结众人共同对抗狱长。渐渐地，他赢得了伙伴们的尊重，成为球队的精神领袖。可他也因此招致了嫉恨。到底是放弃比赛以重获自由，还是冒着在监狱里度过余生的危险而坚持下去呢？相信每个人都会得到相同的答案。','If you can\'t get out, get even.',82000000,190320568,26.065735,6.2,785,113,'2005-05-19','en','/nbKcVBcxF96ARW2oKHqDYAcLdu.jpg',3.3546317200997176,3,'2026-09-10',2,NULL,NULL),(9292,'终极神鹰','Hudson Hawk','艾迪（布鲁斯·威利斯 Bruce Willis 饰）刚刚结束了他长达10年的监狱生活，可是，刚刚出狱，梅弗劳尔夫妇就找到了他，希望他能够帮助他们偷窃一种特殊的水晶，这种水晶用于500年前达芬奇（Stefano Molinari 饰）发明的点石成金机，是如今人人趋之若鹜的珍宝。  　　想要洗心革面的艾迪并不像再做违法的勾当，无奈梅弗劳尔夫妇绑架了他的好友汤米（丹尼·爱罗 Danny Aiello 饰）用以威胁，艾迪只得就范。在寻找水晶的途中，中央情报局和梵蒂冈教廷都成为了他强劲的对手。通过调查，艾迪发现这种水晶的碎片藏匿于各大博物馆达芬奇的各种艺术品中，身为曾经的“哈德逊之鹰”，艾迪大显身手的时刻来临了。','Danger is his middle name.',65000000,17218080,16.803457,5.4,269,100,'1991-05-23','en','/jlgBROTPlIepfH2WIuhG2aGALFn.jpg',3.030191054984907,3,'2026-09-10',2,NULL,NULL),(9294,'不一样的本能','Phenomenon','乔治（约翰·特拉沃塔 John Travolta 饰）本是一个普通的汽车工程师，然而，一束强光的照射彻底改变了他平凡的命运，一些神奇的能力逐渐的开始在乔治的身上显现。乔治的变化并没有让他获得他人羡慕的目光，正相反，曾经的朋友和邻居都因为他的怪异举动而对他产生了抵触的情绪，乔治渐渐变得孤立无援。  　　至始至终守护在乔治身边的是名叫莱斯（凯拉·塞吉维克 Kyra Sedgwick 饰）的女人，在她的温柔关怀下，乔治重拾了生活的热情和信心。他积极的利用自己的超能力做起了帮助他人的善事，而他的名声也因此越传越远。乔治的能力并非取之不尽用之不竭，当力量逐渐枯竭之时，会有怎样的命运等待着他呢？','Some things in life just can\'t be explained.',32000000,152036382,15.039407,6.2,323,123,'1996-07-05','en','/sEFauS0fgD2dWNq23dqgKXnmRdd.jpg',3.1314619214043034,3,'2026-09-10',2,NULL,NULL),(9297,'怪兽屋','Monster House','12岁的DJ（米切尔•莫索 Mitchel Musso 饰）是个爱幻想的家伙。他整天觉得对面街的老头子的那座荒废的老屋阴森怪气，附近的一些物体经常不翼而飞。经过详细观察，DJ发现原来失踪的物品都被老屋吃了，那么老头子失踪的老伴应该都是被吃了，DJ心想。不过大人们甚至伙伴们都觉得DJ在异想天开。\r 万圣节前的一天，DJ和伙伴乔德（山姆•勒纳 Sam Lerner 饰）不小心将篮球扔到了老屋门前，他们眼睁睁的看着一股神秘力量将篮球吸进了屋内，就连新搬来的伙伴珍妮（史宾塞•洛克 Spencer Locke 饰）也差点成了老屋的美味。伙伴们这下相信了DJ的说法，不过大人们却依然觉得他们在扯蛋。为了阻止老屋继续吃人作恶，伙伴们决定携手与它作战到底。','The House is . . . ALIVE!',75000000,140175006,36.368839,6.3,874,91,'2006-07-21','en','/jV0SCPSh30urIbLj61a6YiKTlrI.jpg',3.418522293299517,3,'2026-09-10',2,NULL,NULL),(9302,'Up Close & Personal','Up Close & Personal','Tally Atwater has a dream: to be a prime-time network newscaster. She pursues this dream with nothing but ambition, raw talent and a homemade demo tape. Warren Justice is a brilliant, hard edged, veteran newsman. He sees Tally has talent and becomes her mentor. Tally’s career takes a meteoric rise and she and Warren fall in love. The romance that results is as intense and revealing as television news itself. Yet, each breaking story, every videotaped crisis that brings them together, also threatens to drive them apart...','Every Day we Have, is One More Than We Deserve.',60000000,0,4.801849,5.9,50,119,'1996-03-01','en','/zF67qcf7skMHLpXnifodinUqCFr.jpg',2.6944389827036987,3,'2026-09-10',2,NULL,NULL),(9303,'惊世狂花','Bound','薇拉（珍妮佛•提莉 Jennifer Tilly 饰）是黑道中人的老婆，阴暗的生活令她非常厌倦。这天，她家隔壁新搬来了一个颇有男子气质的女邻居高琪（吉娜•吉舍恩 Gina Gershon 饰），她会亲自动手修下水管，打扮总是非常脏乱。一种莫名的情愫在薇拉心中涌动，她主动接近高琪，风情万种的引诱她，二人终于堕入断臂之爱。薇拉一心想和高琪远走高飞，逃离现在的生活。于是，高琪和她展开了一场危险游戏。','In their world, you can\'t buy freedom, but you can steal it.',4500000,7011317,15.359952,6.9,198,108,'1996-09-13','en','/rbWSBInXGuNy1cABr3yMEw0TkUL.jpg',3.0687793464463224,3,'2026-09-10',2,NULL,NULL),(9304,'丈夫一箩筐','Multiplicity','无论是为人父还是为人夫，道格都很称职，但是他太忙了，没有时间亨受生活。与遗传学家的巧遇让他生出一个大胆的想法，何不把自己复制几个，那不就分身有术了么。但是，想得好还得行得能，不知道格1、2、3、4、5的人生各是什么样。\r Doug很累，因为他的丈夫，父亲，职员各种身份使他在不同面具之间疲于奔命，在压力大得承受不了的时候，他会随时崩溃。直到他遇见了遗传学家Leeds博士，后者告诉他现代科技昌明，可以将人复制几个副本完成不同的使命。Doug觉得这是个不错的方法，欣然克隆了Doug二号，三号，四号……问题是这些复制品从此便与原版相互独立不受牵制，慢慢地Doug发现这些分身并没有减少他的麻烦，反而产生了各种各样的问题，威胁到他自己——原版Doug——的工作，家庭，甚至差点抢走了他的老婆……','Sometimes to get more out of life, you have to make more of yourself.',45000000,0,11.120344,5.5,154,117,'1996-07-19','en','/rlG2vi85uSEwWigVTtqDecVFTxR.jpg',2.9222759508585163,3,'2026-09-10',2,NULL,NULL),(9306,'拦截人魔岛','The Island of Dr. Moreau','爱德华因飞机失事流落到南太平洋上的一个神秘岛屿，他发现自己置身于一群举止形貌与人类相近但又决非人类的生物当中。原来这里正是大名鼎鼎的莫罗博士搞生物实验的地方。博士解释说，他正在从动物身上提取良好基因，期望创造出完美的物种。时间在一天天过去，爱德华目睹岛上没有人类天性的变种互相杀戮，而博士本人也丧身之中。他下定决心，无论如何要逃出这个鬼地方......故事取材于英国作家威尔斯的科幻小说，片中奇异的怪物造型出自特效大师斯坦.温斯顿之手。','The gates of hell are unlocked.',40000000,49627779,13.210898,4.6,147,96,'1996-08-23','en','/mUqU8ytWf8vtbuGGevFfQGjiiIM.jpg',2.8728915716952588,3,'2026-09-10',2,NULL,NULL),(9310,'美国梦','American Dreamz','这是斯塔顿总统（丹尼斯·奎德 Dennis Quaid 饰）这几年来头一遭翻开报纸，没想到，关于自己的负面新闻以排山倒海之势扑面而来，大受打击的斯塔顿顿时陷入了郁郁寡欢之中，行为举止也日渐怪异。作为斯塔顿的得力助手，萨特（威廉·达福 Willem Dafoe 饰）感到十分焦急。竞选在即，不断下跌的支持率让他所支持的这位竞选人离连任的目标越来越远。\r 为了力挽狂澜，无奈的萨特只得将斯塔顿搞到了目前最火爆的真人秀“美国梦”的特约评审席上。经过层层选拔，奥默（Sam Golzari 饰）和莎莉（曼迪·摩尔 Mandy Moore 饰）两名选手站在了斯塔顿的面前，而他们其中之一，竟然是危险的恐怖分子。谁将获胜，决定权在斯塔顿的手中，他的选择将直接关系到国家的安危。','Imagine a country where more people vote for a pop idol than they do for their next President.',17000000,7314027,7.864011,4.9,95,107,'2006-03-04','en','/qwRbRvfJR7jjsaGfS741Tl3DRr7.jpg',2.800911006724871,3,'2026-09-10',2,NULL,NULL),(9311,'冰雪谜案','Smilla\'s Sense of Snow','1859年，一颗陨石坠落在格陵兰，掀起的冰雪覆盖了茫茫大地……时间回到当代，一名因纽特男孩以赛亚坠楼身亡，他的邻居——冰原学者史米拉（Julia Ormond 饰）发现现场疑点重重，更为重要的是，史米拉清楚有恐高症的以赛亚不会去房顶玩耍。史米拉为了不辜负她和以赛亚的友情，决意将真相调查到底。\r 以赛亚的父亲生前为格陵兰矿业公司雇佣，结果不幸死于野外事故，同时陪同父亲工作但幸免于难的以赛亚开始定期接受丹麦顶尖医生的体检，而医生背后则是矿业公司总裁。各种神秘人物不断阻扰史米拉的调查，同一栋楼内的失语症机械师站到了史米拉身边予以保护让调查得以继续。从一系列谋杀与陷害事件中逃离后，史米拉终于发现一切都源于那颗陨石……','Some Tracks Should Never Be Uncovered.',35000000,0,5.419181,6.6,60,121,'1997-02-13','en','/2BwL0fKCaNRXfqMsu2uvFFS7dZX.jpg',2.7499530222480226,3,'2026-09-10',2,NULL,NULL),(9312,'真人快打','Mortal Kombat','位于天地边沿的魔界向人类挑战，若这次人界落败，邪魔立即统治人类世界，沦入万劫不复之地。为了迎接这项挑战，保卫人界的雷电之神派出三名正义勇士迎战，起初还能轻易打败大魔神的邪魔武士，但当大魔神制造幻像，三人旋即陷入困境，幸得魔界公主相助方能击败魔头，人界才能得以见天日。  根据著名同名正宗美式血腥格斗游戏改编的电影大作！这个游戏在大陆被称作《真人快打》，又名《究极神拳》《龙争虎斗》。  说起电玩改编电影，就不能不提起《魔宫帝国》。这部影片在1995年推出，以魔幻世界、东方武术和电脑特效作卖点，上映后大受欢迎，所取得的7千多万美元票房，更让她在电玩改编电影排行榜上高居榜首之位达6年之久。《魔》电影版改编自1992推出的同名电玩，与《街头霸王》一样吃重於格斗的场面，不过剧中主角的设计安排就与电玩中的角色颇相似，这点就较讨好电玩迷们。《魔》电影版以2千多万美元成本拍摄，在全球推出后创下卖座佳绩，便紧接开拍续集。','Nothing In This World Has Prepared You For This.',18000000,122195920,16.470895,5.4,442,101,'1995-08-18','en','/9YhpvhhvLrtL1wlwEfpVL16GI9d.jpg',3.1138744763054382,3,'2026-09-10',2,NULL,NULL),(9313,'铁面人','The Man in the Iron Mask','阿瑞米斯(Aramis)，阿瑟斯(Athos)，波瑟斯(Porthos)，达·塔南(d\'Artagnan)身为最英勇的皇家卫士，以热情与勇气将步兵队名声大振。阿瑟斯过着简朴的生活并扶养其子洛特(Raoult)，波瑟斯，他虽然有些老、有些迟钝，但依然精力充沛，阿瑞米斯则追求他的信仰，而成了一位神父；只有达·塔南仍担当步兵队队长而向国王效忠。 时值1660年，法国饥荒不断，路易十三驾崩，以傲慢残酷闻名的继承人路易十四继承王位，此时的巴士底监狱有一个神秘的囚犯，以铁覆面在此被监禁了十年。为了拯救国家，步兵队必须重新结合，着手开始他们有始以来最危险的任务——释放那名囚犯。为了那神秘的铁面人，也为了王国的生存与荣誉，步兵队会如何去做呢？','For the honor of a king. And the destiny of a country. All for one.',0,0,28.98027,6.3,1018,132,'1998-03-12','en','/b0fZdpyh3TOJ9ygl6qq3WYnqGYp.jpg',3.4368355489707785,3,'2026-09-10',2,NULL,NULL),(9315,'空中危机','Flightplan','凯尔•普拉特(茱迪•福斯特饰)的丈夫跳楼自杀，满心创痛的她只想尽快带着6岁的女儿赶回温暖的家，登上从柏林飞往纽约的飞机。然而飞机起飞后女儿不翼而飞。所有的证据都证明她的女儿没有登机，所有的人都怀疑凯尔的神经有问题，但是作为一个母亲，她深信不疑自己的女儿就在这架飞机上，并且誓要把莫名失踪的女儿找回来。凯尔是飞机的设计者，对于飞机的每一个内部构造都了然于心，带领观众揭开飞机每一个构造的时候，也纷纷揭开了一个惊天的阴谋。最终飞机爆炸，紧急迫降。当被疏散的乘客和机组人员看见飞机上走下抱着女儿的凯尔时，对母亲的决心和信心涤荡起从心而起的尊敬。','If Someone Took Everything You Live For... How Far Would You Go To Get It Back?',55000000,223387299,32.05145,6.1,772,98,'2005-09-22','en','/6qq8fex5DU9Y85pfsisavodEfW9.jpg',3.3491378419845073,3,'2026-09-10',2,NULL,NULL),(9327,'肥佬教授','The Nutty Professor','超级大胖子金斯教授（艾迪•墨菲 Eddie Murphy 饰演）虽然学术高明，心地善良，但因为体型问题一直成为大家的笑柄。直到有一天，金斯教授发现自己研制的新药成功了，这种药水能改变小白鼠的DNA，使其体重减轻，似乎金斯教授就要迎来自己的新生活了。  金斯教授一直钟情于化学教员的卡洛小姐（贾达•萍克•史密斯 Jada Pinkett Smith 饰），一次约她到俱乐部吃饭时，金斯教授又因为体型问题被主持人瑞基嘲笑而令他在女伴面前抬不起头。回去以后，金斯教授决定喝下自己研制的新药。喝下药水后，奇迹发生了，金斯教授变成了放荡无耻、阴险狡猾的瘦子毕地。幸好药水时效有限，一定时间后毕地又变回了金斯教授。为了在卡洛面前抬得起头，金斯教授一次又一次的喝下了药水……','Inside Sherman Klump, a party animal is about to break out.',54000000,128769345,20.28119,5.4,702,95,'1996-06-26','en','/fMtb5aZoLRNbMnCkatFsTmPRfl5.jpg',3.198670136232912,3,'2026-09-10',2,NULL,NULL),(9331,'燃眉追击','Clear and Present Danger','哈里森·福特依旧饰演美国中情局干员杰克·雷恩，这一次他卷入了哥伦比亚的贩毒战争之中，因为美国总统的友人遭毒贩谋杀，雷恩奉命追查真相。但另一方面总统又派了秘密的突击小组对付毒贩集团，使雷恩在状况不明、敌友不分的情况下陷入重重危机之中。影片叙事手法简练，将后冷战时代复杂的国际局势和政治权谋的诡异多变交代得很清楚，同时也兼顾动作场面紧张刺激的娱乐性，堪称是优秀的政治惊险片，但观众欣赏本片时非得聚精会神不可，要不然难以了解其中的微言大义。','The war of drugs would lead him to the war of power.',62000000,215887717,18.832471,6.4,386,141,'1994-08-03','en','/tWwEQkHg5rqGlYuy5daWuidyMJx.jpg',3.2005177265534157,3,'2026-09-10',2,NULL,NULL),(9334,'蝎子王','The Scorpion King','故事发生在距今5000多年前的俄摩拉城。曼农是俄摩拉城中一个手握重兵的军阀，他对权力的贪婪欲求使得城里其它的部落如临大敌，为了生存，几个部落联合起来誓与曼农杀个你死我活。屡次交锋之后，部落联盟总是败下阵来，这使众人甚为困惑。原来曼农身边有一个懂得巫术的神秘人物，他能够预见未来，可以以此指导曼农部署作战计划。得知这一情况后，部落联盟决定派出一名刺客执行暗杀巫师的任务。　　摩挲尤斯（“岩石”饰）是勇士阿卡德人部落唯一幸存下来的成员，他身强力壮、骁勇善战，是名不可多得的一流杀手。但俗话总说：“英雄难过美人关”，当摩挲尤斯深入敌后发现神秘的巫师卡珊德拉其实是一个美丽的女人（胡凯丽饰）时，他犹豫了。一方面，摩挲尤斯被卡珊德拉的美貌所打动不忍心伤害她；另一方面，摩挲尤斯也了解到，卡珊德拉为曼农所做的一切并非自愿，而是在其胁迫和威逼下无奈而为之。所以，摩挲尤斯最终没有动手。　　没完成任务的摩挲尤斯独自逃到一片荒漠，在那里他遇见了盗马贼阿皮德。他们两人以前只有过一面之交，但却在生死存亡的危难关头结下了深厚友谊。这次再度相遇后，摩挲尤斯讲述了自己未完成的使命，阿皮德遂答应帮助他了却杀敌立功的心愿。他指引着摩挲尤斯摸进了曼农的城堡，于是，正义与邪恶的战争就在摩挲尤斯抽出腰间利剑的那一刻开始了……','Warrior. Legend. King.',60000000,165333180,37.537093,5.3,779,92,'2002-04-16','en','/gUx0JPFzcVTiD2QU4FR3oQUAWw2.jpg',3.239591528879768,3,'2026-09-10',2,NULL,NULL),(9335,'玩命快递2','Transporter 2','前风光无限的职业押运人弗兰克·马丁，好不容易完成了一系列押运任务，开始有点厌倦打打杀杀的生活，决定金盆洗手，回到风光无限好的迈阿密，还在这里找到了一份谋生的差事——当一家富人的司机，准备好好享受自己平凡人一般的平静生活。他甚至还和自己当司机家里的双胞胎小男孩意外成了朋友，这可让本来不怎么喜欢小孩的他意外了很久。  然而好景不长，弗兰克无奈之下又接手了一个颇具挑战性的生意——保护和自己有了不错感情的富豪家的一个小男孩。又一次不用运送是贵重物品的“货物”，弗兰克这趟活肩上的担子不但不轻，还可谓责任不小——富家子一向是那些从事绑架勒索行业的首要“客户”，很明显他必须全副武装、在刀刃上度过这短暂而又漫长的几天了。  不过，既然曾是行业最佳，当然不是误打误撞、光凭运气来的，弗兰克在这行也算混迹多年，保护的孩子还是自己心甘情愿的。于是，看似风平浪静的押运之旅开始，然而短暂的平静之后，凶残的敌手凭空杀出，经历了一番惊险火爆之后，情况到了最糟糕的地步，孩子不但被坏人劫走，还被服用了毒品。为了孩子，为了自己的名声，这次弗兰克可不能善罢甘休了。','The Best In The Business Is Back In The Game.',32000000,85167639,47.5612,6.2,1061,87,'2005-08-02','en','/aBEJ5j3NfW8yq91P1P7l3nDElZM.jpg',3.4710288921148025,3,'2026-09-10',2,NULL,NULL),(9336,'警察学校','Police Academy','某市女市长突发奇想，下令不计教育背景、工作经历等，适龄的年轻人都可以报考警校。一时间，西班牙口音的花花公子乔治、擅长口技的乔维、懦弱的胖子巴巴拉、不爱红装爱武装的汤普森（金·凯特罗尔 Kim Cattrall 饰），以及被父亲好友里德上尉强制塞进警校的惹事泊车仔马哈尼（斯蒂夫·古根伯格 Steve Guttenberg 饰）等人涌向警察学院。与此同时，警校方面痛感严格传统的丧失，拉萨德校长令哈里和卡拉汉两教官在接下来的14周时间内对学员严加训练。这班背景各异的学员绝不是省油的灯，从武器痴迷者到夜夜化妆进入女寝寻欢的大情人无所不有，哈里少尉从学员中选出两人担任班长以配合自己的铁血教育，然而这一切都无法阻止一心求被开除的马哈尼的恶作剧……','What an Institution!',4500000,146198896,15.002502,6.5,602,96,'1984-03-22','en','/3PriqoVUQcPwcyvk0SJRiMTdBJK.jpg',3.3107964539852253,3,'2026-09-10',2,NULL,NULL),(9339,'人生遥控器','Click','身为建筑师的迈克尔·纽曼算是个事业有成家庭美满的中年男人了。漂亮贤惠的老婆和两个可爱的孩子让他成为同龄人当中的佼佼者。但是，和美国众多的中产家庭中的男主人一样，迈克最大的问题就是为了家庭的一切而工作繁忙。忙碌到甚至很少能喝和妻子孩子们正常相处，真正享受家庭生活的天伦之乐。这天，难得在家休息的迈克尔却找不到家里的电视遥控器。于是，他跑到附近一家电器商店买了一个多功能遥控器，既可以遥控电视机又可以控制音响碟机的那种。电器店老板莫蒂推荐他买了一种“可以控制很多事情”的全功能遥控器，迈克尔买回家才发现，莫蒂推荐的遥控器竟然有着更多神奇的功能，不但可以控制一些家用电器，甚至连时间、空间也在这个小东西的掌控之中。利用这个遥控器，他可以随意把自己的时间“快进”“回放”甚至“停止”，也就是说他可以自由的控制时间。当工作时他“快进”一下就可以马上回家与家人共处，当他做错事时可以“回放”一下让自己回到过去的时光重头做起。有了这是“万能的遥控器”，迈克尔生活似乎变得非常惬意且自如。可是，好景总是不长……','What If You Had A Remote... That Controlled Your Universe?',82500000,237681299,41.176631,6,2104,107,'2006-06-22','en','/AugJYWDb8bIHS43mAxP4rGajKGM.jpg',3.5643695642214746,3,'2026-09-10',2,NULL,NULL),(9341,'地心抢险记','The Core','某天，世界各地接连出现奇怪现象：安装心脏起搏器的病人突然暴亡、鸽子迷失方向四处乱撞、金门大桥断裂、罗马竞技场遭到密集雷电袭击……一时间，人类陷入前所未有的恐慌，似乎恐怖的世界末日就在眼前。各国政府及军队紧急动员，急切找到这一连串灾难发生的原因。在这关键时刻，地质物理学家乔许·凯斯（艾伦·艾克哈特 Aaron Eckhart 饰）探明真相，原来地核因某种未知的原因停止转动，导致磁场消失。为了拯救人类和地球，乔许以及蕾贝卡·柴德（希拉里·斯万克 Hilary Swank 饰）、罗伯特·艾维森（布鲁斯·格林伍德 Bruce Greenwood 饰）等专家组成一支救援小组，共同前往地球中心实行艰巨而充满危险的拯救任务。人类的命运命悬一线……','Earth has a deadline.',60000000,74208267,29.211255,5.4,516,136,'2003-03-28','en','/1YOoy8slv0c3TCKTNYs1QyM5VPa.jpg',3.168607570464365,3,'2026-09-10',2,NULL,NULL),(9342,'佐罗的面具','The Mask of Zorro','蒙面英雄佐罗（安东尼•霍普金斯 Anthony Hopkins 饰）为了阻止西班牙总督蒙特罗滥杀无辜，突然从天而降，劫走了准备行刑的犯人，从而与蒙特罗结下深仇。随后，蒙特罗派部队跟踪了佐罗。在一片混战中，佐罗的妻子被杀死，还在襁褓中的女儿被虐走，佐罗也被投入了监牢。一晃眼二十年过去了，为了让自己的事业后继有人，佐罗带上面具逃出了监狱。蒙特罗这时仍然在作恶，他计划买下加利福尼亚的所有权。佐罗找到了年轻的盗贼马瑞塔（安东尼奥•班德拉斯 Antonio Banderas 饰），将毕生所学都传授了给他，希望马瑞塔能够阻止蒙特罗的阴谋。马瑞塔继承了佐罗的面具，然而当他找到蒙特罗时，发现拦在他面前的凶狠的西班牙公主（凯瑟琳•泽塔-琼斯 Catherine Zeta-Jones 饰）竟然就是当年老佐罗的女儿！','No one has seen his face... but everyone ... knows this mark.',95000000,250288523,31.086791,6.3,1183,136,'1998-07-16','en','/jZdnjSok0l6v0VzcvmhoJ94XoLE.jpg',3.476260129151449,3,'2026-09-10',2,NULL,NULL),(9344,'半熟少年','Kids','少年们的生活可以很纯洁，也可以很残酷，很显然，泰利（Leo Fitzpatrick 饰）属于后者。打小在下层社会中摸爬滚打的他练就了一幅玩世不恭的态度，将世间的一切都不放在眼里，将所有的伦理道德都踩在脚下。泰利的一大爱好就是和朋友们一起去勾引纯洁少女并与其发生关系，这么做的原因一是满足欲望，而是源于泰利内心中对性病的恐惧。女孩珍妮（科洛·塞维尼 Chloë Sevigny 饰）发现自己感染了艾滋，而她在不久前刚刚和泰利有过一段露水情缘。为了避免悲剧发生，珍妮想方设法追随着泰利的脚步，而此时，毫不知情的泰利正在对另一个女孩穷追猛打，当珍妮出现在他面前时，为时已晚。',NULL,1500000,7412216,13.291991,6.8,279,91,'1995-07-28','en','/8qV8hUVCUnFIQKewzlhaFWhdszK.jpg',3.1448332870305467,3,'2026-09-10',2,NULL,NULL),(9348,'异种','Species','自20世纪70年代开始，美国政府实施了名为SETI的计划，30年来不间断的用射电望远镜扫描宇宙空间，旨在寻找外星生物和相关文明。在犹他州的德威市，有一所隶属政府的实验室，这里正在进行一项秘密试验。在此之前，人类曾受到外星文明发回的信息，其中包括外星生物的DNA组成和生命重组的方法。犹他州实验室的科学家们利用外星人提供的资料培养出拥有外星人DNA的新人类“塞尔”。出于某种原因，政府决定中止这项实验，但其中一个塞尔却逃出实验室。她将给人类带来怎样的影响？  　　本片荣获1996年MTV电影奖最佳银幕之吻奖、1995年科环宇宙杂志最佳化妆奖、1995年Sitges-Catalonian国际电影节最佳特效奖。','Our time is up.',35000000,113374103,23.607071,5.5,453,108,'1995-07-07','en','/m3ZprThGFmopcA7JM1hyB2UkVtB.jpg',3.1457651817306536,3,'2026-09-10',2,NULL,NULL),(9350,'绝岭雄风','Cliffhanger','加贝是一名高山抢险队队员，对于他来说，不断的征服一座又一座看似高不可攀的山巅就是人生的全部意义所在。然而，在一次行动中，由于加贝的疏忽导致了朋友意外坠山而亡，心中充满了愧疚与悔恨的他决心就此放弃攀登。一次偶然中，加贝接收到了一个神秘的求救信号，信号的发出地位于雪岭之巅，和朋友哈尔、杰西一起，加贝决心到那里一探究竟。让加贝没有想到的是，在雪岭等待着他的，竟然是一帮穷凶极恶的劫匪和一群手无寸铁的人质。比环境更险恶的，是人心，这一次，加贝能否逢凶化吉呢？','The height of adventure.',70000000,255000211,26.19909,6.1,588,112,'1993-05-28','en','/j7OJJGm5iC7quW0EQGuwcqNQNq0.jpg',3.2769944603620815,3,'2026-09-10',2,NULL,NULL),(9352,'欧洲性旅行','EuroTrip','斯科特（斯科特·麦克洛维茨饰）刚从高中毕业，在毕业典礼上和女友菲奥娜（克斯汀·克鲁克饰）商量着好好享受这个暑假，却被女友当着他家人的面把他甩掉，斯科特对着菲奥娜的背影大喊。这成为他朋友库珀（雅各布·皮特斯饰）和他弟弟伯特的笑柄。在韦德家的毕业晚会上，得知双胞胎詹妮（米歇尔·崔切伯格饰）和吉米（特拉维斯·韦斯特饰）要去欧洲旅行，第一站为巴黎。当天晚上，斯科特收到其德国女网友米克的电子邮件，如库珀所说的要和他见面。在弟弟伯特的提醒下，斯科特得知米克是女的，后悔莫及，定和库珀前往柏林找米克。两人到伦敦后误入一曼联球迷聚会的酒吧，阴差阳错下得到球迷们的帮助后，到达了巴黎，并在那找到双胞胎。他们四人决定开始一场欧洲旅行。','No actual Europeans were harmed in the making of this film.',25000000,20796847,25.848003,6.5,656,93,'2004-02-20','en','/iLdO4PwbZCCQSa9rchZMwuJm9xe.jpg',3.356675676701721,3,'2026-09-10',2,NULL,NULL),(9353,'疯狂神父','Nacho Libre','纳丘（Jack Black 杰克•布莱克 饰）自幼父母双亡，他在墨西哥瓦哈卡的一家孤儿院度过了自己的童年时光。成年后他并未离开这里，而是以厨师的身份留在孤儿院为孩子们烧菜做饭，他们都很喜欢这位温柔和爱的胖叔叔。但是，孤儿院的生计开始陷入困境，因资金短缺，这里将面临着关闭的命运。纳丘不愿看到孩子们无家可归，为此他决定以蒙面摔角手的身份走上擂台挣得奖金。即为了那一双双充满期待的眼睛，也为了美丽的卡纳西昂修女（Ana de la Reguera 安娜•雷格拉 饰）……','He\'s not lean. He\'s not mean. He\'s nacho average hero.',32000000,80197993,14.642055,5.6,359,92,'2006-06-16','en','/5KbRVXvWEJCuXOMZk9OkednF5Wf.jpg',3.0946098570485234,3,'2026-09-10',2,NULL,NULL),(9355,'疯狂的麦克斯3','Mad Max Beyond Thunderdome','麦斯抵达巴顿镇，凭着一身好本领，被女皇聘为雇佣兵，消灭操纵地下世界的智武者。麦斯却被女皇的左右手巴斯逐出沙漠。一群居住在世外桃源的野孩子奉麦斯为神，带领他们走出沙漠，几个孩子为了理想，毅然奔向巴顿镇，麦斯为救他们，再入虎穴。','Two men enter. One man leaves.',12305523,36230219,36.582038,5.9,748,107,'1985-06-29','en','/unhFES4BpqoS4RXt0SgX3xjmTUc.jpg',3.3222699672363794,3,'2026-09-10',2,NULL,NULL),(9357,'一小时快照','One Hour Photo','西摩·帕里什（罗宾·威廉姆斯 Robin Williams 饰）是一家大型冲印店的普通职员，四十多岁了，一直过着孤独的单身生活，但是在他心中，一直对幸福美满的家庭有着梦想，不知从什么时候起，这份梦想被投射到熟客尤金一家身上。尤金太太妮娜（康妮·尼尔森 Connie Ni elsen 饰）美丽优雅，男主人威尔（迈克尔·瓦尔坦 Michael Vartan 饰）事业有成，他们还有个可爱的孩子——全是西蒙想得而不得的。西摩开始幻想自己是这家的一员，是可亲的“西蒙叔叔”，他还把这家人送来洗印的照片都偷偷拷贝一份私藏，事情败露后遭到解雇，但只是刺激他更加过分地接近和偷窥这一家人，在发现男主人竟然有外遇时，西蒙愤怒了，他开始着手进行惩罚，只因他梦想中的完美不容任何人破坏…… ©豆瓣','The things that we fear the most have already happened to us...',12000000,52223306,20.624896,6.6,435,96,'2002-08-21','en','/7D6XojvTgfF6CfZ7rOUtNvbRVhF.jpg',3.255306885433652,3,'2026-09-10',2,NULL,NULL),(9358,'死神来了2','Final Destination 2','少女金伯莉（A.J. Cook 饰）与好友驱车去郊外游玩，途中她预见一场严重的连环交通事故，而自己和朋友也将命丧其中。猛然惊醒的金伯莉将车横在路中央，阻挡了后面的车辆。然而车祸仍然发生，金伯莉侥幸逃过一劫，另有六人从灾难中逃生。这奇异的经历让众人想起180号航班幸存者的故事。　　正如他们预料的那样，死神不会放过任何一个逃跑者。这些幸存者按照他们本该在车祸中死去的顺序一个接一个在各种巧合和意外中死去，金伯莉成为最后的生者。她得知180航班幸存者克莉尔（Ali Larter 饰）仍然健在，她希望从克莉尔那里得到逃脱死神魔爪的办法……','Death is like a boomerang. it keeps coming back',26000000,90426405,37.355826,5.9,1023,90,'2003-01-31','en','/crsQTKHnqpRh7xjDiwWkmoLv3ZM.jpg',3.3870055117183595,3,'2026-09-10',2,NULL,NULL),(9360,'狂蟒之灾','Anaconda','在蜿蜒流长的亚马逊河流域的雨林深处，生活着古老而神秘的舒尔族。他们与世隔绝，以食人蛇为叩拜图腾。围绕着舒尔族人的传说和秘密让雨淋之外的人们振奋不已。人类学家史蒂文•凯（埃瑞克•斯图尔茨 Eric Stoltz 饰）对舒尔人颇感兴趣，他和纪录片导演泰莉•劳瑞（杰妮佛•洛佩兹 Jennifer Lopez 饰）组成一个七人摄制组，前往雨林为这神秘的部族拍摄纪录片。路上，他们搭救了一个名叫保罗•沙龙（琼•沃纳 Jon Voight 饰）的男子，保罗自告奋勇带摄制组寻找舒尔人，却不曾想这个男人的真正目的竟是寻找一条恐怖的食人巨蟒。蒙在鼓里的史蒂文等人就次踏上一条充满血腥的不归路……  　　本片荣获1998年ALMA拉丁媒体艺术奖最佳女主角奖（Jennifer Lopez）、1998年BMI百代最佳电影音乐奖、1998年世界动画庆典最佳3D制作。','When You Can\'t Breathe You Can\'t Scream.',45000000,136885767,27.684779,4.7,610,89,'1997-04-11','en','/eWpgQdnDvwBD7uOEHwniJNKWvkR.jpg',3.0968983725994916,3,'2026-09-10',2,NULL,NULL),(9361,'最后的莫希干人','The Last of the Mohicans','本片改编自美国作家库柏“皮袜子”系列小说中的第二部。1757年七年战争期间，英法两军在北美殖民地激战正酣。军官邓肯带队护送长官之女可娜（Madeleine Stowe 饰）前往威廉亨利堡，半路遭法属印第安人埋伏，莫希干族最后的战士——金卡加（Russell Means 饰）、安卡斯父子与白人霍克依（Daniel Day-Lewis 饰）出手相救。但抵达要塞时他们发现这里已陷入战火，要塞长官门罗与邓肯做事强硬，不肯放走民兵自降战力，并将霍克依监禁，可娜这时已同霍克依相恋，但却无力援救。英军战事不利弃堡投降，印第安人马瓜带领族人向英军寻仇，可娜与霍克依失散后被马瓜带走，霍克依、金卡加、安卡斯一行进入马瓜族人的营地，以期带回可娜。','The first American hero.',40000000,75505856,37.776566,7.1,732,112,'1992-09-25','en','/ocZHO18zMur23q7aFHro025dUnk.jpg',3.5010943019977647,3,'2026-09-10',2,NULL,NULL),(9362,'异形魔怪','Tremors','在一个名为“完美”的宁静小镇上，米奇（凯文·贝肯 Kevin Bacon 饰）和死党巴斯特（弗莱德·沃德 Fred Ward 饰）又度过了属于他们的平静一天。对于在这个无趣的小镇里从事着一份又一份没有前途，仅能糊口的工作这一事实，两个血气方刚的年轻人感到十分无奈和困扰。终于，他们决定要走出完美镇，开始他们多姿多彩的新生活，而就在此时，通向镇外的唯一一条公路莫名塌陷了，某些不详的征兆开始显现。  　　早在数星期之前，镇上发生了家畜神秘失踪的恐怖事件，同时，地质系学生蕾贝卡（ 芬妮·卡特 Finn Carter 饰）发现小镇的地壳运动十分异常。现在，众人终于将这些纷乱的线索拼凑到了一起，在大家的脚下，黑不见光的地底，究竟是什么在蠢蠢欲动？','The monster movie that breaks new ground.',11000000,48572000,32.579697,6.6,864,96,'1990-01-19','en','/cA4ggkZ3r1d5r9hOAUWC8x5ul2i.jpg',3.4560417148362124,3,'2026-09-10',2,NULL,NULL),(9366,'忠奸人','Donnie Brasco','为打击黑手党势力，美国联邦调查局委派探员乔皮斯通化名道尼布拉斯科打入黑帮卧底。通过一次珠宝生意，乔结识了黑帮头目本尼罗杰洛，并得到他的赏识。为取得罗杰洛的信任，乔不得不无恶不做，参与了一系列犯罪活动。但随着与罗杰洛接触的越久，乔竟对罗杰洛产生了友谊，为人处事的态度也发生了变化。由于工作的过度投入，更忽视了家人的感受，令妻子与其产生了隔阂。在心意彷徨的这段时间里，他没有按时间向联邦调查局发出情报，而罗杰洛已按奈不住抢班夺权的野心与道尼谋划干掉老大的计划。不料，联邦调查局由于长时间与乔失去联系，另派人进行跟踪监视，致使罗杰洛的计划败露。形势发生急转直下的变化……','Based on a true story.',35000000,41954997,40.370442,7.4,1147,127,'1997-02-27','en','/xtKLvpOfARi1XVm8u2FTdhY5Piq.jpg',3.6921753340342525,3,'2026-09-10',2,NULL,NULL),(9367,'杀手悲歌','El Mariachi','这是导演的成名之作，罗伯特自掏腰包拍了这部低成本的黑色电影，结果一炮而红。影片讲述的是一名心狠手辣的罪犯成功越狱后，来到小镇伺机找他的仇家报仇，仇家的手下只知道那个罪犯将武器藏在吉他盒子里随身携带，而从来都没有见过他本人。一名流浪的吉他手（卡洛斯•加拉尔多 Carlos Gallardo 饰）凑巧这时来到小镇谋生，于是，莫名其妙的他就被卷入了一场不知所谓的追杀中。追杀的场面被导演演绎的笑料百出，黑色幽默表现的淋漓尽致。','He didn\'t come looking for trouble, but trouble came looking for him.',220000,2040920,14.269792,6.6,238,81,'1992-09-04','es','/m2e1CSjgyZJ6MePD5Zw7VhNSICo.jpg',3.091584935750615,3,'2026-09-10',2,NULL,NULL),(9372,'大号的我','Super Size Me','这是一部有趣的纪录片。针对麦当劳快餐和美国人身材肥胖等健康问题之间的关系，摩根策划了一个“以身试法”的实验方案：在一个月里，除了去麦当劳点餐，他不再吃别的食物。在一日三餐麦当劳对肠胃狂轰滥炸后，摩根发现了自己身体急剧的变化：体重飞涨30磅，血压飚升，精神倦怠，呼吸闷滞，性生活质量骤降。摩根用亲身的试验结果，告诉那些依恋速食快餐的人们，回归健康膳食是如何的迫切。否则，就像摩根的遭遇一样，连女友都快要被吓跑！','The first ever reality-based movie ... everything begins and ends in 30 days!',65000,28575078,10.400603,6.6,506,100,'2004-01-17','en','/zYkbqQaCuIHBxqBDGgnQCwJ9jIG.jpg',3.26997881692907,3,'2026-09-10',2,NULL,NULL),(9374,'飞越长生','Death Becomes Her','海伦（歌蒂·韩 Goldie Hawn 饰）和恩尼斯（布鲁斯·威利斯 Bruce Willis 饰）是一对感情十分要好的情侣，海伦的好友梅德林（梅丽尔·斯特里普 Meryl Streep 饰）要在百老汇进行一场演出，两人遂携手一同前往观看。没想到梅德林居然对英俊帅气的恩尼斯搔首弄姿，之后更是插足于两人之间横刀夺爱。同时失去了好友和爱人，海伦悲伤又愤怒，对人生失去希望的她暴饮暴食，很快就变成了一个人人见而避之的肥婆。不要用别人的错误惩罚自己，明白了这个道理，海伦开始发愤图强，她不仅恢复了曾经的姣好身材，更出版了描写期间心路历程的新书。海伦的改变让生活并不如意的恩尼斯重燃了旧情，梅德林坐不住了，为了和昔日好友一决高下，她开始向邪恶的女巫寻求帮助。','In one small bottle... The fountain of youth. The secret of eternal life. The power of an ancient potion. Sometimes it works... sometimes it doesn\'t.',55000000,149022650,29.498304,6.3,636,104,'1992-07-30','en','/kkWxyyyWFK5KNk9WVwQuGEC9H9H.jpg',3.3294366697244735,3,'2026-09-10',2,NULL,NULL),(9378,'十三猛鬼','Thir13en Ghosts','在从古怪的叔叔赛勒斯那里继承了一座神秘的大宅之后，阿瑟·克里蒂科斯和他的家人发现这座房子其实是由一个经验丰富的捉鬼人关押的13个暴力鬼魂组成。当这些黑暗的鬼魂被释放时，克里蒂科斯一家陷入了超自然恐怖的迷宫。在一位灵媒和一位超自然现象专家的帮助下，他们必须揭示这座大宅的秘密，重新将这些幽灵关入囚笼。面对难以想象的恐怖，他们努力求生，并保护彼此免受那13个寻求复仇和永恒释放的幽灵的威胁。','There are ghosts around us all the time. Most of them don\'t want to hurt us. But, there are exceptions...',0,0,20.392858,5.4,440,91,'2001-10-26','en','/6yrrddjIjx0ElCRZp5pTZeqrj3k.jpg',3.1220781843601424,3,'2026-09-10',2,NULL,NULL),(9381,'生死新纪元','Babylon A.D.','未来世界，随着科技的超速发展，大量高科技的机器人投入使用，为人类提供便利的同时也取代了大批劳动力。很快机器人的数量就已与人类不相上下，世界变成了机器与人类共生的一个团体。Toorop(范·迪塞尔 Vin Diesel 饰)是一名退役的老兵，空有一身的武艺却终日无所事事，转业当上了拿钱办事的雇佣兵，专门接受各种护送任务。一日，他接受了一项新任务：在Rebecca修女(杨紫琼 Michelle Yeoh 饰)的陪同下，押解一个神秘女人横跨欧亚大陆。然而他并不知道对方身上原来有着某种可怕的病毒，这种病毒的力量足以毁灭全世界。与此同时，一个邪教组织也正在对她虎视眈眈，企图利用这名女性产下一个基因改良的人种……','Kill or be Killed.',70000000,72108608,27.568194,5.4,676,101,'2008-08-20','en','/jFeT6HyWj2wtuGoopKyaW4I9iqI.jpg',3.209147182927981,3,'2026-09-10',2,NULL,NULL),(9383,'Hollow Man','Hollow Man','Cocky researcher, Sebastian Caine is working on a project to make living creatures invisible and he\'s so confident he\'s found the right formula that he tests it on himself and soon begins to vanish. The only problem is – no-one can determine how to make him visible again. Caine\'s predicament eventually drives him mad, with terrifying results.','What would you do if you knew you couldn\'t be seen?',95000000,190213455,28.200874,5.6,634,112,'2000-08-04','en','/tayTpxo7hTNyQSJPfnorhiVys2m.jpg',3.2280237480297833,3,'2026-09-10',2,NULL,NULL),(9384,'警界双雄','Starsky & Hutch','七十年代的海湾城警局里，有一位敬业又略显癫狂的警探大卫·斯塔斯基（本·斯蒂勒 Ben Stiller 饰），大卫作风强硬，哪怕再小的案件他也要不计代价抓捕罪犯。而卧底探员肯·哈金森（欧文·威尔逊 Owen Wilson 饰）则几乎完全相反，肯时常装做匪徒打劫，之后借卧底身份溜之大吉。因大卫失去了搭档，上峰将他和肯硬撮合到了一起。  拥有海湾城知名商人身份的里斯背地里却是一名大毒枭，里斯一伙最近研制出了不能被警犬发现的新型可卡因，里斯因为运送可卡因的手下办事不利，将他射杀在海中。死者的尸体被发现，大卫和肯的二人组接手此案，两名性格迥异的警探在里斯布下的迷宫中逐渐接近了事实的真相，但是里斯的狡猾，超乎他们的预料。','They\'re the man.',60000000,170268750,28.848842,5.6,644,101,'2004-03-05','en','/fmBYVkBjhVspPv3GGus84qhBo1a.jpg',3.2322977419768133,3,'2026-09-10',2,NULL,NULL),(9387,'野蛮人柯南','Conan the Barbarian','故事发生在远古的洪荒年代。柯南的父母在他小时候就被暴徒残害致死，柯南自幼就无依无靠，孤身一人长大。或许老天见他可怜，赐予了他无穷的力量。当柯南长大后，他遇到了一位神秘的长者，这名长者教授了他一身武艺。出师后，柯南开始独自闯荡江湖。  　　柯南随后在与女巫的斗争中获得了一把威力无穷的“王者之剑”，凭着高超的武艺和这把剑，柯南成了远近文明的剑客。不幸随之而来，柯南痛失了挚爱。邪恶的皇后为了将公主从巫师手中夺回，以公主的血献祭来使自己永保王位，要求柯南抢回公主。在得知只有皇后的魔法能使爱人死而复生后，柯南踏上了寻找公主之路...','Thief. Warrior. Gladiator. King.',20000000,79114085,31.802807,6.6,650,129,'1982-04-02','en','/qw2A587Ee61IwcSOLNFRhuOACZZ.jpg',3.3821657878276645,3,'2026-09-10',2,NULL,NULL),(9388,'感谢你抽烟','Thank You for Smoking','尼克（艾伦•艾克哈特 Aaron Eckhart 饰）是这个世界上最赚钱也最富有争议的行业――烟草业 的代言人。他每天不仅要像推销员一样用三寸不烂之舌去说服人们抽烟，还要不得不变着发子去对付禁烟团体、环保团体和科学团体的抗议，在政府和参议员中想尽办法为烟草业谋取最大利益。\r 　　尼克还有两个知心朋友――为酒业代言的波利（玛丽亚•贝罗 Maria Bello 饰）和为军火业代言的鲍比（大卫•科恩查内 David Koechner 饰）。相同的行业性质让三人成为无话不谈的密友，经常在一起交流怎样对付环保团体等各种社团的抗议、如何在政府、参议员中周旋的诀窍。\r 　　在政治和商业互相交错的舞台上，他们上演了一出又一出好戏。','Tobacco lobbyist Nick Naylor is trying to SAVE YOUR ASH!',6500000,24793509,29.01153,7.1,664,92,'2005-09-05','en','/41bMmglWT72OaRXrMROEyksOf3J.jpg',3.452716785221576,3,'2026-09-10',2,NULL,NULL),(9389,'复活','Renaissance','2054年的巴黎，一个处于全程监控中的独立城，人们的一举一动都会被记录下来。切断了与外界联系的巴黎仍然处在不断的发展中：在这里，一座座挺立的摩天大楼黯然了古典建筑几百年的辉煌；改进后更为错综复杂的地下城市枢纽继承了老式地铁隧道曾经的繁忙。但无论在任何地方，阿瓦隆公司的名字总会映入你的眼中，这个巴黎城最大公司的产品已经渗透了社会日常生活的每一层面--因为它可以承诺你永恒的青春年少和不变的美丽容颜。  　　阿瓦隆公司最有前途的科学家之一--22岁的伊昂娜突然遭到绑架，阿瓦隆雇佣了巴黎警探巴塞里米·卡拉斯去寻找伊昂娜。卡拉斯是寻人天才，天生的直觉让他无往不利。这次，随着线索的渐渐明晰，卡拉斯发现自己并不是唯一一个在寻找美丽女孩的人，而他所要找寻的证人总是先一步被人灭口了事。  　　一条条线索摆在了卡拉斯的面前：孤儿姊妹花伊昂娜和碧丝莲都是被人从战火纷飞的高加索地区拯救出来的，两人的命运却大相径庭：师承伟大遗传学家乔纳斯·穆勒的伊昂娜最终选择了阿瓦隆，终日沉浸在工作中；碧丝莲沦落为黑道；伊昂娜的老师穆勒为了改变城市底层的贫穷而放弃了自己的远大前程；失踪前的伊昂娜似乎参与了一个叫做“复兴草案”的神秘计划……  　　为了找到伊昂娜并解开她失踪的秘密，卡拉斯在公司间谍，黑帮份子和遗传专家中小心周旋，却不知当真正的答案被揭晓后，这个世界面对的将是救赎还是毁灭……','Paris 2054. Live forever or die trying',18000000,1831348,9.244181,6.7,77,105,'2006-03-16','fr','/hbcj9Uon31lpHMCpWF8E1XEybX1.jpg',2.817791806398975,3,'2026-09-10',2,NULL,NULL),(9390,'甜心先生','Jerry Maguire','杰里（汤姆·克鲁斯 Tom Cruise饰）待人和善，仪表不凡，是个出色的体育界经纪人。也许连天都妒嫉这个完美的男人，决定给他一个打击，杰里因为一篇流畅出色的发言稿而招来上司不满，导致被炒鱿鱼。漂亮女友离他而去，职业前景也陷入一片迷茫，从巅峰跌入谷底的杰克在临走前奋起疾呼，动员同事们跟他离开公司一起创业。结果，杰克只带走了一条鱼，还有愿意和他干一番事业的会计多萝西（芮妮·齐薇格 Renée Zellweger饰）。  　　现在，杰克的客户只剩下一名二流的黑人橄榄球员罗德（小库珀·古丁 Cuba Gooding Jr饰）。万事开头难，杰克和多萝西还没有完全搞清楚要如何开始创业生涯。看来，要想迎来事业的第二春，杰克还要狠狠摸爬滚打一番；也正是在逆境中，他得以实践自己的职业信念，并寻获一生中的最爱','Everybody loved him... Everybody disappeared.',50000000,273552592,27.039636,6.7,913,139,'1996-12-06','en','/zGlAn7WY6H6KceRSW8UpW7NQ3xC.jpg',3.474035480396268,3,'2026-09-10',2,NULL,NULL),(9392,'黑暗侵袭','The Descent','莎拉（肖娜·麦克唐纳 饰）本来平静幸福的生活被一次车祸意外打破，丈夫和女儿在事故中丧生，她虽然活了下来却从此一蹶不振，为了让莎拉重新振作起来，她的五个女性朋友为她安排了一次探险旅行，地点是在一个丛林中荒僻而古老洞穴，茹诺(娜塔丽·杰克逊·门多萨 饰)是其中最有野外探险经验也是她选择来到这里。正当女孩们对山洞中景色惊叹不已时，却在不知不觉中惊扰了洞中另外一种生物，他们没有视觉，依靠声音的来源残忍的捕杀她们，女孩们为了自救团结起来，却在逃生中朋友间互生怀疑，为了生存下去，她们要如何在狭小黑暗的洞穴中找到出去的路呢？','Scream your last breath.',0,0,23.413188,6.8,1005,99,'2005-07-08','en','/slqumUUt5Y2Zlr6nM5tdJQT1AIT.jpg',3.5081215698895014,3,'2026-09-10',2,NULL,NULL),(9396,'鳄鱼邓迪2','Crocodile Dundee II','《鳄鱼先生》在世界各地造成轰动，使澳洲藉男星保罗．贺根一炮而红。原班人马再接再励拍摄了这部正宗的续集。虽然换了导演约翰．康奈尔，但仍延续了上集的喜剧风格，并且增添了更多的冒险和动作。故事描述邓迪与女记者苏本来在纽约过着惬意的生活，不料哥伦比亚毒贩闯进了他们的二人世界。邓迪深感危险，乃将一伙歹徒诱至澳洲丛林，利用他对地形地物的熟悉展开反攻。保罗．贺根和他的儿子布雷特．贺根以父子档姿态共同担任本片编剧，在片中套用了不少上集的成功方程式，虽然已无创新感，但娱乐效果依旧可令人开怀。','The world\'s favourite adventurer is back for more! much more!',0,239606210,15.474831,5.5,303,110,'1988-05-19','en','/2Nf0xeDuToLHysdkWj3aT5r42rC.jpg',3.056577573314313,3,'2026-09-10',2,NULL,NULL),(9398,'超级名模','Zoolander','励精图治的马来西亚新总理上台，令滥用童工的各大美国服装集团颇感压力，这班时装界巨头谋划选出最无知愚蠢的男模刺杀马来西亚总理……戴瑞克•祖兰德（本•斯蒂勒 Ben Stiller 饰）是蝉联三届最佳男模的超级模特，但是在最近的模特盛典上，祖兰德的第四次荣誉被新人汉瑟尔（欧文•威尔逊 Owen Wilson 饰）夺走，失落的祖兰德又遭遇了三位死党意外身亡，连续打击之下，祖兰德返回矿区的家乡，但这里的一切已经不再适合养尊处优的超级名模。时装界的超级设计师穆格图（威尔•法瑞尔 Will Ferrell 饰）此时向祖兰德抛出了橄榄枝，邀请后者与自己合作最新设计。《时代》杂志记者雯达（克里斯蒂娜•泰勒 Christine Taylor 饰）追查之下发现穆格图的真实意图是将祖兰德改造成行刺马来西亚总理的杀手……','3% Body Fat. 1% Brain Activity.',28000000,60780981,38.0958,6.1,1337,89,'2001-09-28','en','/coxkb3Lo1pgl7RvwzEggwAXGypE.jpg',3.4815803219005526,3,'2026-09-10',2,NULL,NULL),(9400,'辣姐妹','Set It Off','Stoney、Frankie 、Cleo 、Tisean是四个平日同甘共苦的好朋友，她们四人之中有同志、有被解雇的银行职员、有努力供弟弟念大学的姊姊、有单亲妈妈，四个人的境遇各有不同，唯一相同的是，她们都受到种族或性别上的歧视;她们希望自由与独立的生活，而钱是让她们脱离目前窘况的唯一工具，于是一场令人颤栗的黑色事业就此展开......','It\'s about crime. It\'s about payback. It\'s about survival.',9000000,41590886,6.717994,6.9,66,118,'1996-11-06','en','/wpiARyUqTfabzakAXHMIUY6Tl1A.jpg',2.7817895870512652,3,'2026-09-10',2,NULL,NULL),(9408,'冲浪企鹅','Surf\'s Up','“大Z”吉克（杰夫·布里吉斯 Jeff Bridges 配音）是企鹅世界最知名的冲浪选手，他有着光辉成绩，又在十年前消失在一次比赛里，因此成为传奇，他的故事激励了一代又一代小企鹅继承冲浪事业，科迪（希亚·拉博夫 Shia LaBeouf 配音）就是其中最痴迷的一个，他从小就立志走出小镇，也的确凭自己的努力和天赋，得到经纪人长腿鸟（马里奥·坎东尼 Mario Cantone 配音）和矮熊老板（詹姆斯·伍兹 James Woods 配音）的支持，带他进入世界级冲浪比赛赛场——夏威夷岛。在那里，科迪遇见了一个蔑视“大Z”的傲慢选手“坦克”（狄尔里奇·巴德 Diedrich Bader 配音），为维护偶像向他提出挑战，还遇到美丽的救生企鹅兰妮（佐伊·丹斯切尔 Zooey Deschanel 配音），梦想和爱情，一起摆在年轻科迪的面前……','In the coldest place on Earth, he\'s the hottest thing around.',85000000,149044513,23.230851,5.9,601,85,'2007-06-08','en','/xm2gaCpmlIbFgHkSaKhjFjfRi4g.jpg',3.24781015158432,3,'2026-09-10',2,NULL,NULL),(9414,'特工插班生','The Man Who Knew Too Little','最近，瓦伦斯（比尔·默瑞 Bill Murray 饰）心情不错，因为他即将赶赴伦敦，与他的弟弟詹姆士（彼得·盖勒 Peter Gallagher 饰）共度生日。然而，对于詹姆士来说，这可不是一个好消息，身为一个成功的银行家，繁忙的工作让他再也分不出时间来应付这个成天傻呵呵的弟弟了。为了打发瓦伦斯，詹姆士送给了他一张舞台剧门票，没想到正是这张门票，将瓦伦斯卷入了一个阴谋之中。  　　黑帮，杀手，这些平日里离瓦伦斯的生活无比遥远的角色开始接连出现在了他的身边，而单纯又善良的瓦伦斯将这惊心动魄的一切权当做是一部超真实的电影乐在其中。没想到，能够阻挡杀手强力攻势的竟然是瓦伦斯的单纯，正义和邪恶之间的争斗在笑料百出之中展开了。','He’s on a mission so secret, even he doesn’t know about it.',20000000,13801755,6.397042,6.5,125,97,'1997-11-14','en','/gRuZl4sPKeATTBYu2G0pGwdpLJC.jpg',2.9156018894745643,3,'2026-09-10',2,NULL,NULL),(9416,'超级轰天雷','Money Talks','弗兰克（克里斯·塔克 Chris Tucker 饰）是一个不学无术的小混混，一场意外中，他被捕入狱，在运动囚犯的车上，弗兰克认识了臭名昭著的维拉德。维拉德一直在策划一场越狱，而他决定将弗兰克当做一枚手中的棋子。哪知道弗兰克并没有维拉德想象的那么听话，他竟然擅自脱离了越狱大部队，自己逃跑了。  　　这下可好了，弗兰克不仅要躲避警察的追捕，还要应付维拉德的爪牙，在走投无路的情况下，弗兰克向记者詹姆斯（查理·辛 Charlie Sheen 饰）求救，而詹姆斯也并非好鸟，他希望能够利用弗兰克让自己一举成名，谁知道，事情的发展很快就失控了。','This ain\'t no buddy movie.',0,0,7.615653,5.9,87,97,'1997-08-22','en','/bN57Rl003E9pYred5kw9Rp8h9Np.jpg',2.8166142932294047,3,'2026-09-10',2,NULL,NULL),(9422,'法网边缘','A Civil Action','故事发生在1979年的一座工业小镇上，接连出现的因白血病而死亡的病例惹得居民们人心惶惶，大家都知道，镇上那两家整日排放着污水的大工厂和这些悲剧脱不了干系。在庞大的工厂体系面前，个人是如此的渺小，可是即便如此，失去了日子后，安妮（凯瑟琳·奎南 Kathleen Quinlan 饰）毅然决定联手镇上的8个受害者家庭，对两家工厂提起了诉讼。  　　没有律师愿意接受这样棘手的案例，除了胜算渺小外，他们也不愿意惹上不必要的麻烦，只有一个人是例外，他就是简斯里特曼（约翰·特拉沃塔 John Travolta 饰）。简花费了大量的人力和财力调查两家工厂的日常排水，在证据确凿之后，却因为被告方的暗度陈仓而输了官司，简失去了一切，金钱，家庭，名誉，但他并没有放弃。','Justice has its price.',70000000,56702901,10.147321,6.1,109,115,'1998-03-05','en','/2AVF1cjRGOfaB4oteSzxvHiQ3hR.jpg',2.877164890328991,3,'2026-09-10',2,NULL,NULL),(9424,'恐怖怪谭','Disturbing Behavior','如诗如画、平静和谐的居家环境人人爱，但你相信有这种地方存在吗？摇篮湾，就像它的名字一般，像摇篮那么的令人向往。史提夫在哥哥自杀之后，搬到这个洒满阳光的梦幻小镇。没有人酒后驾车、没有人嗑药、没有人自杀；青少年最常从事的活动是「社区服务」、「烤饼乾」和「考高分」。镇上有一群被称为「蓝丝带」的模范青少年，史提夫拒绝加入，并认识了刚退出的葛文与瑞秋，因为他们都怀疑这群人有失去控制的诡异行为。学校里的心理医生声称有治疗这种怪异行为的妙方；然而，就在大家意识到事情严重性之前，疯狂而恐怖的结果已轰然爆发……','In Cradle Bay it doesn’t matter if you’re not perfect.  You will be.',15000000,17507368,9.378688,5.5,104,84,'1998-07-24','en','/uAhvaueOUUQ6ORCRdsJr1WXz1w0.jpg',2.8428388828787075,3,'2026-09-10',2,NULL,NULL),(9425,'兵人','Soldier','未来世界，为了赢得星际战争，政府从新生儿中严格挑选一批人，从小就进行杀人训练，这些人没有家庭、感情，他们眼中只有杀戮，称为兵人。特德（Kurt Russell）就是这群人中的佼佼者，他经历了数场星际大战，依然屹立不倒。这次政府采用新的基因技术，让婴儿在母体中就接受战争基因的改造，制造了一批改良后的兵人。为了测试效果，特德和另外两名伙伴被挑选和新兵人凯恩（Jason Scott Lee）进行一场较量，结果两名伙伴被打死，而特德因为昏迷被误认为死亡而逃过一劫。他和另外两个伙伴的尸体被扔到了一个垃圾星球。特德在那里遇到了被遗弃的平民，他麻木的心灵在这里滋生了友谊和爱情。当他准备在这里和心爱的女人幸福过活时，政府将这里当成了新兵人的训练场。新兵人们在这里的任务就是杀光所有生物。为心爱的人和伙伴们，特德毅然出战！','Left for dead on a remote planet for obsolete machines and people, a fallen hero has one last battle to fight',75000000,14567883,11.873856,6.1,221,99,'1998-10-23','en','/ykZTBiRiGFLfFkGtjtL1tnue6wO.jpg',3.033200666043586,3,'2026-09-10',2,NULL,NULL),(9427,'光猪六壮士','The Full Monty','下岗恐怕不仅仅是中国工人面对的问题，下岗了怎么办？英国人用他们的幽默给我们上了一课。这天，刚下岗的钢铁工人盖茨（罗伯特•卡莱尔 Robert Carlyle 饰）和戴夫（马克•艾迪 Mark Addy 饰）遇上了一个同病相怜的兄弟――正在自杀的龙珀（史提夫•惠森 Ste ve Huison 饰），二人慌忙救下了他。为了今后的出路，三人绞尽脑汁。最终，他们想出了一个近乎疯狂的主意。他们找到了已经转业在舞厅当演员的前工头杰拉尔，于是，当地第一个专门的男人脱衣舞团成立了！随后，黑人霍斯和小伙子盖伊也闻风加入了这个团体。在一连串爆笑的场面下，这个脱衣舞团第一次演出就获得了空前的成功，虽然因为涉嫌色情遭到了警察调查，却为这个团体增加了更加多人气，很多人出于好奇心而来观看演出。在获得了家庭成员的理解后，这个团体开始了他们的终极演出。','The year\'s most revealing comedy.',3500000,257850122,17.002623,6.8,363,91,'1997-08-13','en','/fjg4EvzoLZVcZli4BwJIytJ6yjn.jpg',3.2217565515931343,3,'2026-09-10',2,NULL,NULL),(9428,'天才一族','The Royal Tenenbaums','罗伊·特伦鲍姆Royal Tenenbaum（吉恩·哈克曼 Gene Hackman 饰）45岁那年夫妻分居，他一个人去住酒店，独自抚养孩子的妻子艾瑟琳Etheline（安杰丽卡·休斯顿 Anjelica Huston 饰）把所有重心都放在了孩子才能的培养方面。不负众望，他们的三个孩子个个都是天生异禀的奇才，她以此写作了一本书——《天才一族》。 大儿子查斯Chas（本·斯蒂勒 Ben Stiller 饰）12岁时就对生意运筹帷幄，初中就购置不动产，对财务有着超同寻常的理解。二女儿玛葛Margot（格温妮斯·帕特洛 Gwyneth Paltrow 饰）两岁时被收养，这个话题被父亲叨叨终身以致玛葛Matgot有点神经质地耿耿于怀。这个天才剧作家9岁时就赢得了勇士奖。里奇Richie（卢克·威尔逊 Luke Wilson 饰）从三年级起就是冠军网球选手，业余喜爱组乐队和收藏汽车模型以及绘画，17岁转做职业选手的他连续三年获得美国公开赛冠军。 罗伊与妻子离了婚后离开了家，时间荏苒，20年过去了，三个天才孩子长大成人。查斯Chas在一次飞机失事失去妻子后，变得神经兮兮，整天替两个儿子的安全而担忧，惶惶度日；玛葛Matgot貌似淑女，其实是个有20年烟龄的“烟枪”，并且已多年没有出版过作品，和做神经科医生的丈夫维持着毫无激情可言的婚姻生活，整日把自己锁在浴室不与丈夫交谈；里奇Richie在大海上准备一年的航行，自在一次大赛中失利后就一蹶不振，如今靠在世界各地航海来打发时间。这一切都被Royal的一个突然消息中止：他患上了癌症只剩下6个礼拜的生命，他想和家人共度最后的时光。 原来是离家多年的罗伊开始想念起自己的妻儿，热切渴望重归家庭怀抱享受天伦之乐。为了达到这个目的，他宣布已被医生诊断为胃癌，而且只剩下六个星期的生命，这个消息令分离的家人又重新团聚到一起，这天才一家再度聚首，有趣的事层出不穷。尽管开始的时候大家还是格格不入，但大家的关系却在悄悄地发生着微妙的变化，当家庭从新拥有凝聚力之后，特伦又该怎样解释自己的“病情”呢？','Family isn’t a word, it’s a sentence.',21000000,71441250,24.13081,7.4,1286,110,'2001-10-05','en','/nG7hZJn7wQTSDCQT39Gy3s3tbrp.jpg',3.690250134210615,3,'2026-09-10',2,NULL,NULL),(9429,'舞翻天','A Night at the Roxbury','史提與德格兩個鄉下佬，一直夢以自創的獨門舞步，在洛杉磯最頂尖的俱樂\r 　　部闖出名堂。為了實現夢想，兩人出盡法寶混入當地最in的俱樂部，希望在舞\r 　　池內一展超凡舞技，這對難兄難弟漸漸打響名堂，卻遇上專向男人騙財的名\r 　　模慧慧與甘碧‥‥','Score!',17000000,30331165,12.709227,5.9,198,81,'1998-10-01','en','/7oZ5xE4AL4D5EbeQUaoRxahgzJX.jpg',2.9986075003786463,3,'2026-09-10',2,NULL,NULL),(9430,'狗男女','Go','罗娜（萨拉·波莉 Sarah Polley 饰）正面临着人生中的重大危机——缺钱，在帮毒虫朋友西蒙（德斯蒙德·奥斯基 Desmond Askew 饰）顶班时，阿戴姆（斯考特·沃夫 Scott Wolf 饰）和扎克（杰·摩尔 Jay Mohr 饰）希望能从罗娜那里弄一点毒品，这点醒了罗娜脑中的商业细胞，她决心当一名毒贩以度过这次难关。  　　实际上，阿戴姆和扎克是警方的线人，而罗娜则是他们第一次“任务”的目标人物，正在为自己的好主意沾沾自喜的罗娜还不知道，她遇上了大麻烦。与此同时，西蒙也遇上了点麻烦，他有些弄不明白，为什么前一刻还在拉斯维加斯逍遥快活的自己，下一刻却变成了身背数罪的逃犯。对于阿戴姆和扎克来说，他们的处境也不乐观，因为他们和负责管理他们的警察巴克（威廉·菲德内尔 William Fichtner 饰）之间的关系十分微妙。 ©豆瓣','A weekend wasted is never a wasted weekend.',6500000,28451622,11.142389,7,196,98,'1999-04-09','en','/7UzD5Dmu3jqb2ls4Lnb4SYQqbYm.jpg',3.0629110203008443,3,'2026-09-10',2,NULL,NULL),(9433,'势不两立','The Edge','查尔斯（安东尼·霍普金斯 Anthony Hopkins 饰）是一个腰缠万贯的百万富翁，对于他来说，金钱、权利和女人不过是生活的基本配置而已。但是，在为查尔斯打工的摄影师罗伯特（亚历克·鲍德温 Alec Baldwin 饰）眼里，老板所拥有的一切，尤其是他年轻的妻子米琪（艾拉·麦克弗森 Elle Macpherson 饰）都让他感到十分眼红，但是，罗伯特不知道的是，敏感又细心的查尔斯早就开始怀疑起了他和米琪之间的清白。  　　在一次工作中，众人乘坐的飞机发生了事故，一行人流落到了阿拉斯加的荒原之上。匮乏的资源，恶劣的天气，凶恶的野生动物，一切的一切都威胁着大家的性命，但最最可怕的，其实是每个人深藏在心底的黑暗面。','They were fighting over a woman when the plane went down. Now, their only chance for survival is each other.',0,43312294,20.632673,6.7,349,117,'1997-09-06','en','/zplJqfuUyqzW0D4jX3W1afl0d7b.jpg',3.2100256984535704,3,'2026-09-10',2,NULL,NULL),(9434,'这个杀手将有难','Grosse Pointe Blank','布兰克（约翰·库萨克 John Cusack 饰）是一名经验丰富的职业杀手，效忠于组织，深得上司的信赖与重用。然而，成日里躲躲藏藏打打杀杀的生活令布兰克感到十分疲惫，产生了金盆洗手的念头，可是，他所签署的合同却并不允许他有此想法。\r 　　这一次，布兰克的目标人物竟然生活在他的老家底特律，在那里，布兰克和曾经的女友德比（明妮·德里弗 Minnie Driver 饰）重逢了，这场意外的重逢让两人之间再度擦出了火花。之后，布兰克意外遭到袭击，凶徒是他的同行格罗希尔（丹·艾克罗伊德 Dan Aykroyd 饰），更让布兰克感到吃惊的是，他和格罗希尔所要刺杀的人，正是德比的父亲。','Even a hit man deserves a second shot.',0,28084357,13.817269,6.9,275,107,'1997-04-11','en','/7lQ0MSNQqBTYpXTTZL82u1n95Z3.jpg',3.1505360568230953,3,'2026-09-10',2,NULL,NULL),(9437,'惊唇劫','Kiss the Girls','华盛顿警官亚历克斯·克洛斯（摩根·弗里曼 Morgan Freeman饰）是警方的一名心理咨询专家。他突然接到在北卡罗来纳州达勒姆小镇上学的侄女失踪的消息。为了找到侄女，亚历克斯决定一探究竟。然而当他到达当地警察局后，亚历克斯发现这里已经连续失踪了多名少女，自己的侄女只是受害者之一，她们无一例外的都是既聪明又漂亮的优秀女孩。死里逃生的女医生凯特·麦克蒂尔南（艾什莉·贾德 Ashley Judd饰）是唯一侥幸逃脱的女孩，她只记得凶犯是一个头戴面具自称“卡萨诺瓦”的变态杀人狂。凯特为亚历克斯提供了许多有价值的线索，然而狡猾的“卡萨诺瓦”却始终没有现身仍逍遥法外。一场漫长而艰辛的追捕开始了。  　　本片根据美国知名畅销小说家詹姆斯·帕特森的同名小说改编而成。','Smart Girls. Pretty Girls. Missing Girls.',27000000,60527873,18.913,6.2,345,115,'1997-10-03','en','/16jHszOhJumWPpFtVXKLiVQAkDc.jpg',3.154947777050001,3,'2026-09-10',2,NULL,NULL),(9440,'Primary Colors','Primary Colors','In this adaptation of the best-selling roman à clef about Bill Clinton\'s 1992 run for the White House, the young and gifted Henry Burton is tapped to oversee the presidential campaign of Governor Jack Stanton. Burton is pulled into the politician\'s colorful world and looks on as Stanton -- who has a wandering eye that could be his downfall -- contends with his ambitious wife, Susan, and an outspoken adviser, Richard Jemmons.','What went down on the way to the top.',65000000,0,9.110247,6.1,94,143,'1998-03-20','en','/RXEgVSEBkMnV8LkEGkBpuz3mkD.jpg',2.843021475651687,3,'2026-09-10',2,NULL,NULL),(9441,'Stepmom','Stepmom','Jackie is a divorced mother of two. Isabel is the career minded girlfriend of Jackie’s ex-husband Luke, forced into the role of unwelcome stepmother to their children. But when Jackie discovers she is ill, both women realise they must put aside their differences to find a common ground and celebrate life to the fullest, while they have the chance.','Be there for the joy. Be there for the tears. Be there for each other.',0,0,16.368283,6.9,277,124,'1998-12-25','en','/wMPv2Yz6QDzv6YhSbaqM48Medl1.jpg',3.158272039070968,3,'2026-09-10',2,NULL,NULL),(9443,'烈火战车','Chariots of Fire','故事发生在1919年。英国贵族化的剑桥大学凯阿斯学院考进了一位犹太学生亚伯拉罕。这位青年深受种族偏见之苦，一心想成为赢得奥运会百米赛金牌得第一个犹太人，以此来对抗种族偏见，为同胞争光。苏格兰高地也有一个决心夺取奥运会百米金牌得青年利德尔。他父亲是传教士，本人是个虔诚的教徒。他认为，运动员应具备顽强意志和献身精神，这和基督的教义是一致的，既然天赐他一双快腿，就是要他为上帝争光。1920年，苏格兰和法国举行田径比赛，利德尔代表苏格兰参加。正当竞争激烈的时候，利德尔忽然摔倒，但他毫不气馁，急起直追，终于抢先到达了终点。亚伯拉罕在看台上目睹这场意志创造奇迹的比赛，十分激动。他热切地请求意大利职业教练穆萨比尼指导他练习。穆萨比尼没有答应。一九二三年，伦敦举行全国性运动会，利德尔和亚伯拉罕在跑道上相会。利德尔获得冠军，亚伯拉罕落后了两码。他的女友、歌剧演员西比尔安慰他下次定能超过利德尔，但亚伯拉罕痛苦地说，他的速度似乎已达到了极限，再也无法提高了。','This is the story of two men who run, not to run, but to prove something to the world. They will sacrifice anything to achieve their goals... except their honor.',5500000,58972904,10.439971,6.8,207,123,'1981-05-15','en','/qnRaum8k0HqGRml2i7OawFqUtEb.jpg',3.062294590902462,3,'2026-09-10',2,NULL,NULL),(9444,'安娜斯塔西娅','Anastasia','故事发生在1916年的俄国，沙皇的灭亡让尚且还是婴孩的公主娜塔西娅（梅格·瑞恩 Meg Ryan 配音）和祖母朵瓦格（安吉拉·兰斯伯瑞 Angela Lansbury 配音）流离失所，在兵荒马乱之中，两人失散了。一晃眼十年过去，曾经的公主已经出落成为了名为安雅的美丽女孩，而一直惦念孙女的朵瓦格则开始花重金寻找公主的下落。一次偶然中，骗子德米特（约翰·库萨克 John Cusack 配音）遇见了安雅，并不知道安雅就是娜塔西娅公主的德米特决定让安雅假扮娜塔西娅，以骗取高额的赏金，在此过程中，两人之间却意外的产生了真挚的感情。一直以来，安雅都对自己的过去和身份耿耿于怀，这一次，她能够得到所谓的真相吗？','Discover the Adventure Behind the Greatest Mystery of Our Time.',53000000,139804348,45.565918,7.4,1432,94,'1997-11-20','en','/bppGWGA8zq1sRvTdDJnUzVW9GcH.jpg',3.7719839709389125,3,'2026-09-10',2,NULL,NULL),(9447,'小猪宝贝2：小猪进城','Babe: Pig in the City','描述当小猪「宝贝」像英雄般地凯旋回诈到何氏农庄后，这只热心过度的小猪不小心造成意外，害主人何先生卧病在床，由于他无法工作，加上银行威胁要沉没收他们的农庄，于是何太太为了拯救这座农庄，就决定接受一笔很高的酬劳，带着小猪到大城市表演那手令人目瞪口呆的牧羊本领，展开一场精彩逗趣的冒险故事。','This little pig went to the city...',90000000,69131860,11.356079,5.2,305,92,'1998-11-25','en','/yJv0Ld9giDQSkAQWzyYZUcPRrpA.jpg',3.021780243985011,3,'2026-09-10',2,NULL,NULL),(9448,'The Big Hit','The Big Hit','Affable hit man Melvin Smiley is constantly being scammed by his cutthroat colleagues in the life-ending business. So, when he and his fellow assassins kidnap the daughter of an electronics mogul, it\'s naturally Melvin who takes the fall when their prime score turns sour. That\'s because the girl is the goddaughter of the gang\'s ruthless crime boss. But, even while dodging bullets, Melvin has to keep his real job secret from his unsuspecting fiancée, Pam.','Nothing\'s more dangerous than some nice guys... with a little time to kill.',13000000,27007143,6.425528,6.1,109,91,'1998-04-24','en','/7b1JP2WE0UrVAy34U7X4UngWtBi.jpg',2.868663582731977,3,'2026-09-10',2,NULL,NULL),(9449,'反斗神偷','The Borrowers','由于律师波特从中作梗，少年皮特家的房屋遗产权受到侵占，以致长期寄居在皮特家地板下面的寄居人波德一家也要随之搬迁。  　　在搬家过程中，波德的女儿阿列埃蒂和皮格林无意中发现了波特的阴谋。她们遭到波特的追剿。  　　在寄居人游侠斯皮勒的帮助下，波德一家团结几千名寄居人战胜了势力强大的波特，为皮特家夺回了他们应得的权利……','Little People. Big Trouble. Lots of fun.',29000000,0,10.364582,5.8,135,86,'1997-12-05','en','/kgaocWyuxihDe5aNqok6fORIHnY.jpg',2.909563419444955,3,'2026-09-10',2,NULL,NULL),(9451,'校园风云','Election','精力过剩、争强好胜的高中生特雷西·弗利克起初就让社会学老师吉姆·麦卡利斯特心烦意乱。而当她竞选学生会主席、他的个人生活也开始分崩离析时，事态逐渐失控。在亚历山大·佩恩的这部讽刺作品中，这位老师病态地执着于打压学生，暗中支持搅局候选人来阻止她强势胜出，并推动了一系列暗箱操作和鲁莽承诺——这一切都与现实政治有着惊人相似的平行对照。佩恩改编自汤姆·佩罗塔当时尚未出版的小说，将核心人物关系的荒诞性扎根于可辨识的现实之中——故事背景设在他的家乡内布拉斯加州奥马哈市，专业演员与非职业演员共同组成出色阵容——并将他对人性深重缺陷的细腻观察，提炼为苦涩却暗中引发共情的本质。[标准收藏]','Reading. Writing. Revenge.',0,0,13.476596,6.7,270,99,'1999-04-23','en','/p1R4eVhbFenL3fuVzoDjhsH7cSG.jpg',3.128703782055087,3,'2026-09-10',2,NULL,NULL),(9452,'吹牛顾客','Bulworth','加州的参议员Jay Bulworth在党内提名选举中落败，政治前途一片黯淡，尘世生活也不使他留恋。心如死灰的Bulworth买了一份一千万美元的保险，并安排杀手暗杀自己以留下大笔抚养金给家人。Bulworth之后在L.A.南部作了一次演讲，却鬼使神差地抛开了陈腐的讲稿自由发挥，他的尖锐言论震惊了听众和他的竞选阵营的同时，也获得了一位黑人美女的好感。Bulworth索性一不做二不休，在比华利山再次发表了他惊世骇俗的演讲，在这之后Bulworth仿佛上了瘾，他甚至将黑人说唱文化的技巧带入演讲里。这一段时间放松无顾忌的生活，尤其是与Nina的相识让Bulworth产生了继续生活的勇气和欲望。但当他打电话去取消安排的那场暗杀时，却被告知整个程序已被启动，他手忙脚乱地应付这个自己设好的局，幸好有Nina在旁相助。','Brace yourself. This politician is about to tell the truth!',30000000,29202884,4.52363,6.3,66,108,'1998-05-15','en','/gR9jZ7W2d28aSa2Yimz797VNXRh.jpg',2.7618231169148353,3,'2026-09-10',2,NULL,NULL),(9454,'Ever After: A Cinderella Story','EverAfter','A unique 16th century woman, Danielle possesses a love of books, and can easily quote from Sir Thomas More’s Utopia. An intriguing mix of tomboyish athleticism and physical beauty, she has more than enough charm to capture the heart of a prince ... after beaning him with an apple.','Desire. Defy. Escape.',26000000,65705772,21.988861,6.8,399,121,'1998-07-31','en','/81OsvEg9T34PIJFKGNwWa0E4efZ.jpg',3.2580201174403998,3,'2026-09-10',2,NULL,NULL),(9455,'边缘战士','The Corruptor','纽约的唐人街，华人黑帮林立。华裔警官陈力（周润发 饰）依靠勾结黑帮势力、平衡各帮间谍利益关系而战绩彪炳，步步高升。然而这平静的一切却忽然被打破了。唐人街内新来了一帮主要成员来自福建的黑帮分子，自称“龙帮”。他们和旧有的帮派之间展开了激烈的地盘争夺战，愈演愈烈，即使陈力也无法出面摆平。这种局面引起了纽约警局的注意，派出了年轻有为的警官丹尼（马克•沃尔伯格 Mark Wahlberg 饰）调查唐人街的黑帮。当各派黑帮贿赂正直的丹尼失败后，他们决定除掉他。左右为难的陈力，会眼睁睁看着自己的同事遇害吗？','You can\'t play by the rules if there aren\'t any.',25000000,15156200,4.068107,6,57,110,'1999-03-12','en','/araXLU4QZ1f8U8wSf9igrAeaipm.jpg',2.722337094652842,3,'2026-09-10',2,NULL,NULL),(9457,'极度深寒','Deep Rising','一艘舰艇正在南中国海上巡弋，舰长约翰.费因纳根及全体船员都不清楚他们此行是执行什么冒险任务，航行的所有费用均由一位幕后人物支付。机械师乔伊意外地在舱内发现一枚核弹头，他立刻意识到事态的严重性。与此同时，在他们的下游，堪称世界第一的豪华客轮“阿尔戈号”正在进行首航，船上满载腰缠万贯、珠光宝气的贵妇富翁。海盗率领部下潜入船舱，他们破坏了通讯系统，打算将金银财宝洗劫一空。  　　就在这时，轮船好像撞上了什么东西……等约翰他们赶到时，“阿尔戈号”已陷入一片血水之中，船上仅剩下几名幸存者，其中包括特里莲和建造“阿尔戈号”的工程师西蒙。起初，约翰并不相信“阿尔戈号”遭到了所谓“深海魔鬼”的浩劫，直到发现他的船员一个接一个地失踪后，他才明白自己已被放到九死一生的危险境地。在走投无路的情况下，他只能与特里莲联手，共同对付嗜血无度的“深海魔鬼”……','Full Scream Ahead',45000000,11203026,6.513856,6,154,106,'1998-01-30','en','/muhKZtMVASkpT8dJxcVdATz1sb5.jpg',2.9379315284128853,3,'2026-09-10',2,NULL,NULL),(9459,'伍德斯托克音乐节1969','Woodstock','1969年，在纽约州北部的一个小农场里，一场持续三天、泥泞与欢欣交织的非凡盛会在此上演——超过五十万人汇聚一堂，共同赞颂生活、爱与音乐，这就是伍德斯托克。一个摄制组置身于这一切的中心，记录下了那个时代许多最伟大的歌手与音乐家的现场表演，以及数十万人所体验到的欢乐、和平与摇滚精神。','3 days of peace, music...and love.',600000,34505110,3.409764,7.1,66,225,'1970-03-26','en','/AapH8Qx4kUZoO7F4aK5cUnHjtdg.jpg',2.7792176423774344,3,'2026-09-10',2,NULL,NULL),(9464,'水牛城66','Buffalo \'66','倒霉的比利（文森特•加洛 Vincent Gallo 饰）替人顶罪蹲了5年牢，今天，他出狱了。可是他的霉运似乎还没有结束，刚出狱的比利内急想上厕所小便时，不是厕所维修就是被拒绝；即使鬼鬼祟祟的躲到汽车后面想就地解决时汽车也马上开走了。比利和双亲的关系并不好，但他一直想修复与父母的关系。即使坐牢，比利也想方设法瞒着家里，他告诉他们这5年自己在外打拼，已功成名就，并承诺将带着女友回家。为了实现承诺，他“绑架”了一名女孩蕾拉作为自己的女友。  可是，当比利带着蕾拉回到家里时，事情并没有预想中顺利。','Billy Brown just got out of jail. Now he\'s going to serve some real time. He\'s going home.',1500000,2375097,10.009994,7.1,166,110,'1998-01-20','en','/fxzXFzbSGNA52NHQCMqQiwzMIQw.jpg',3.0229813271205366,3,'2026-09-10',2,NULL,NULL),(9466,'名人百态','Celebrity','故事讲述一名记者，为融入上流社会，不惜趋炎附势，放弃尊严，看尽名人百态的他，最后也只落得一场空。','A funny look at people who will do anything to get famous... or stay famous.',0,0,7.594593,6,111,113,'1998-09-07','en','/q4UJHtH14nO8tbMfGtJ3Z3Tw5RW.jpg',2.8712718113752427,3,'2026-09-10',2,NULL,NULL),(9469,'单挑','He Got Game','杰西·沙特尔斯沃思是全国有名的高中篮球明星。杰西一心希望在职业篮球生涯中闯出一片天下，然而却因为有一个身为囚犯的父亲杰克·沙特尔斯沃思而蒙上了一层阴影。当年父亲在一次家庭暴力中错手杀死了母亲，锒铛入狱的杰克因为拥有一个明星儿子而面对了一次交易，只要说服杰西加入州政府指定的大学，事成之后便可得到减刑的机会。','The father, the son and the holy game.',25000000,21567853,10.232599,6.7,134,136,'1998-05-01','en','/kd8hRaysUQOz7AvSorZDJHuihcJ.jpg',2.9497023266762668,3,'2026-09-10',2,NULL,NULL),(9470,'功夫','功夫','20世纪40年代的上海，街头混混阿星自小受尽欺辱，一心想加入横行上海的黑道势力“斧头帮”，借此出人头地。一次，他假冒斧头帮成员来到贫民社区“猪笼城寨”敲诈居民，却阴差阳错招来了真正的斧头帮。谁也没有想到，这个看似破败的城寨其实卧虎藏龙，除了脾气火爆的包租婆和看似懦弱的包租公，居民中还隐藏着多位身怀绝技的武林高手。原本只想借斧头帮之名谋取好处的阿星，也因此被卷入斧头帮与猪笼城寨之间不断升级的冲突，并开始面对自己究竟要成为怎样的人……','So many gangsters...so little time.',20000000,100914445,13.658985,7.2,831,99,'2004-02-10','cn','/wv91QM70K9KzF9usPOebYX3LKkp.jpg',3.4988809474024536,3,'2026-09-10',2,NULL,NULL),(9471,'霹雳娇娃2','Charlie\'s Angels: Full Throttle','她们非常漂亮，她们专门给蠢人教训，她们为查理工作。2003年6月27日，美国最秘密的武器将再次出击，娜塔丽·库克（卡梅隆·迪亚兹）、戴兰·桑德斯（德鲁·巴利摩尔）以及阿历克斯·芒蒂（刘玉玲）在查理的天使中再次挑战危险。  　　天使们在毫无预备的情况下集合到一起，承担了营救两位失踪的法官的任务。这不是普通的任务，她们必须持有密码才能正确找到每一个人，这是联邦证人保护计划规定的。当证人开始一个接一个的死去，只有天使们用她们的高超的伪装本领、间谍的技巧和功夫拳脚的厉害才能阻止罪犯——神秘的堕落天使（黛米·摩尔）。在她们可信赖的同行杰米（伯尼·麦克）的帮助下，天使们开始了在遥远的蒙古边境的冒险，而最后只有戴兰面对自己黑暗过去所隐藏的秘密后，事情才能结束，这个秘密让三个好朋友陷入危险……','This summer the Angels are back.',120000000,259175788,33.616115,5.2,914,106,'2003-06-27','en','/3Fomc1zyiGBdSzlVPLMT8tkt8I8.jpg',3.2389209411416173,3,'2026-09-10',2,NULL,NULL),(9472,'疯狂躲避球','DodgeBall: A True Underdog Story','“全球健身中心”的创始人怀特•古德曼（本•斯蒂勒 Ben Stiller 饰）为人嚣张，以兼并其它健身馆为乐事。健身中心附近有一家惨淡经营的大众健身馆，其负责人彼得（文斯•沃恩 Vince Vaughn 饰）生性淡漠，对一班怪诞的老顾客长期免费服务。为吞并大众健身馆，古德曼购入后者的债权，并委托银行找来律师凯特（克里斯蒂娜•泰勒 Christine Taylor 饰）要求彼得在30天内筹集五万美元还债，否则健身馆将转入古德曼名下。一筹莫展的彼得与众位老顾客、雇员想到参加拉斯维加斯举办的“躲避球大赛”，期望得到冠军奖金解决燃眉之急。同时不堪古德曼骚扰的凯特也加入了彼得一边，古德曼亦组织球队参赛，意欲将彼得等人截杀……','Grab Life By The Ball',20000000,167722310,41.156217,6.2,981,92,'2004-06-18','en','/oY5KCtasOykH35moHVxvEnmUHTM.jpg',3.4388926711549326,3,'2026-09-10',2,NULL,NULL),(9473,'南方公园：加长未删减剧场版','South Park: Bigger, Longer & Uncut','South Park是美国一个宁静的小镇，这里的人们生活的单纯、快乐。一日，四个小伙伴Cartman, Stan, Kenny和Kyle偷偷溜进了正在播映一部由加拿大演员P和T主演的低级电影，影中充斥着黄色笑话和不堪入耳的粗口。四个小伙伴看完电影后学会片中的粗口，并到处和其他孩子讲。很快这些粗口就传遍了小镇，小镇上几乎每一个小孩都跑去看了这部电影，都学会了这些粗口。这些粗口让小镇的大人们十分惊慌，他们认为是加拿大人教坏了他们的孩子，更荒唐的是，美国国会也这样认为，于是，一场发生在美国和加拿大之间的战争打响了！','UH-OH.',21000000,0,27.197799,7.1,893,81,'1999-06-30','en','/tS0PedvA2mFO9VCHYwQpaU1K36U.jpg',3.5347176130631244,3,'2026-09-10',2,NULL,NULL),(9476,'圣战骑士','A Knight\'s Tale','小伙子威廉（希思•莱吉尔Heath Ledger 饰）虽然出身于法国的平民家庭，但从小就梦想当一名骑士，从儿时起就苦练剑术和马术。然而当时的社会只有贵族才有资格当骑士，于是威廉只当了一名贵族骑士的侍从。 在一次马上长枪比武中，威廉的主人在场间休息时突然意外死去。威廉灵机一个，穿上了主人的铠甲，骑上他的坐骑，冒名顶替并赢得了这场比赛。捧着胜利的奖杯，威廉决定继续冒充自己的主人参加在伦敦举行的世界骑士锦标赛，通过赢得比赛使自己成为一名真正的骑士。威廉启程了！','He Will Rock You',65000000,117487473,36.670399,6.6,907,132,'2001-05-11','en','/5Uq2RvYFAErPEtnNxOo6mUJsWSM.jpg',3.477679140010372,3,'2026-09-10',2,NULL,NULL),(9481,'The Bone Collector','The Bone Collector','Rookie cop, Amelia Donaghy reluctantly teams with Lincoln Rhyme – formerly the department\'s top homicide detective but now paralyzed as a result of a spinal injury – to catch a grisly serial killer dubbed \'The Bone Collector\'. The murderer\'s special signature is to leave tantalizing clues based on the grim remains of his crimes.','Serial killer vs. forensic genius',73000000,151493655,33.884459,6.5,826,118,'1999-11-04','en','/Ap6F74y4TIl6yVuj8uBqa8LyZbe.jpg',3.4316901357932776,3,'2026-09-10',2,NULL,NULL),(9486,'憨豆特工','Johnny English','在这个动荡不安的乱世中，很少有像英国情报局这么值得信赖的单位。它拥有全世界最顶尖的情报员、最尖端的先进科技、最犀利的武器配备以及最有效的情报搜集网，而且每一名英国情报局特派员都是十八般武艺样样精通的顶尖高手。因此当他们得到有人想偷走英国王室珠宝的情报时，就派出局里最顶尖的超级间...','He knows no fear, he knows no danger, he knows nothing.',40000000,160583018,28.029015,6,852,88,'2003-04-06','en','/aQGTFX4V82kwRLeQ1vaUFGaZhNg.jpg',3.3450688169709712,3,'2026-09-10',2,NULL,NULL),(9487,'虫虫危机','A Bug\'s Life','菲力在蚂蚁王国里并不怎么受欢迎，尽管他发明了先进的收割机，然而阴差阳错，他竟然惹了大祸，公主妹妹小不点因此被蝗虫敌人捉去，而且蚂蚁的粮食也受到了蝗虫的威胁。即使菲力救出了小不点，但还是被赶出蚂蚁王国。只有他在外面的世界找到了对付蝗虫的办法，才有可能回到家园。菲力在城市中遇到了马戏团的一队昆虫。爬虫、蝴蝶、瓢虫、臭虫，他们都似乎身怀绝技，令菲力十分兴奋，于是菲力把他们请回蚂蚁王国对付蝗虫。一场恶战即将开始，昆虫们愈战愈勇，和菲力一同投入到斗争中。智勇双全的菲力也终于回到了蚂蚁王国中，受到大伙儿的赞赏。','An epic presentation of miniature proportions.',120000000,363258859,87.350802,6.8,2303,95,'1998-11-25','en','/Ah3J9OJVc2CNCuH2zMydXy9fmIC.jpg',3.871215085355497,3,'2026-09-10',2,NULL,NULL),(9488,'非常小特务2','Spy Kids 2: The Island of Lost Dreams','国际特工组织OSS将朱尼和卡门姐弟俩派到迪斯尼乐园里完成一件重要任务，事情是这样的：总统的独生女亚历克桑德拉因为长久以来得不到父亲的关爱而心生怨言，于是偷走了被称作“TRANSMOOKER”的国家防御系统电脑芯片，紧接着，许许多多的追杀跟随而至。','Little Spies. Big Attitudes',38000000,119723358,24.085144,5.3,521,100,'2002-08-07','en','/z8pfWCk6SlxxDLXXQdUHdxF5dwJ.jpg',3.1459780231332655,3,'2026-09-10',2,NULL,NULL),(9489,'You\'ve Got Mail','You\'ve Got Mail','Book superstore magnate, Joe Fox and independent book shop owner, Kathleen Kelly fall in love in the anonymity of the Internet – both blissfully unaware that he\'s putting her out of business.','Someone you pass on the street may already be the love of your life.',65000000,250821495,28.540267,6.3,838,119,'1998-12-17','en','/o0ZWDQe7agXcx9tUjuF7GTMKQOJ.jpg',3.390929931055451,3,'2026-09-10',2,NULL,NULL),(9490,'半仙半死','Half Baked','肯尼意外地用从麦奇跑买来的食物喂了一只患有糖尿病的警察的马，结果杀死了它。之后，他被关进了监狱，并获得了100万美元的保释金。其余的人必须在讨厌的内特找到肯尼之前把他保释出来。该组织决定出售瑟古德在一家制药实验室做门卫的大麻。他们与说唱明星Sir Smoke-A-Lot以及毒贩Samson Simpson的竞争对手成为朋友。另一方面，瑟古德寻求玛丽·简的爱，她是一个反大麻的商人的女儿。接下来是典型的瘾君子行为和大量的配角。','They\'ll do anything to save their best bud.',8000000,17460020,7.894489,6.4,177,82,'1998-01-16','en','/14TmEac4bquNaEld9t0uIliYoKE.jpg',2.9938793882482604,3,'2026-09-10',2,NULL,NULL),(9493,'龙兄鼠弟','Twins','多年前科学家进行了一项创造完美人类的饰演，没想到实验过程中的细胞分裂不均匀导致了这个实验只成功了一半，另一半则完全失败。科学家创造出来的这对双胞胎兄弟一个是完美人类的典型――德智体美全面发展的高大的朱利斯（阿诺•施瓦辛格 Arnold Schwarzenegger 饰）；另一个则是人类所有缺点的集合体――小矮个文森（丹尼•德维托 Danny DeVito 饰）。兄弟两一出世就被分离，朱利斯被科学家送到南海的一个小岛上抚养长大，而弟弟则在孤儿院度过了他的童年。直到兄弟两已过不惑之年，他们才知道了对方的存在。朱利斯与未曾谋面的兄弟文森重逢后，两兄弟决定踏上寻找亲生母亲之路。但是这时，一场意外给他们惹来了杀身之祸。','Only their mother can tell them apart.',15000000,216614388,17.638286,5.7,559,107,'1988-12-09','en','/rNWu78iNyPHkTZB6UkFWXcZ7z0L.jpg',3.194419621484699,3,'2026-09-10',2,NULL,NULL),(9495,'The Crow','The Crow','Exactly one year after young rock guitarist Eric Draven and his fiancée are brutally killed by a ruthless gang of criminals, Draven -- watched over by a hypnotic crow -- returns from the grave to exact revenge.','Real love is forever.',15000000,94000000,44.690107,7.3,953,102,'1994-05-11','en','/rMMB3v6jYHjsvXRNJYESacoTD7j.jpg',3.627534355973181,3,'2026-09-10',2,NULL,NULL),(9502,'功夫熊猫','Kung Fu Panda','好食懒做的熊猫阿宝，一直醉心中国功夫，一次误打误撞竟然被认定为传说中的武林高手──龙战士，奉命去对付刚逃狱的魔头大豹！一代宗师施福大师因而要面对人生最大的挑战──如何在迫切的时间内，将拥有一身豪华臀、麒麟臂、肚腩肉、不能看也不能打的大熊猫，训练成为名震江湖的功夫大师？','Prepare for awesomeness.',130000000,631744560,84.689648,6.9,3145,90,'2008-06-04','en','/wWt4JYXTg5Wr3xBW2phBrMKgp3x.jpg',3.96790451923193,3,'2026-09-10',2,NULL,NULL),(9504,'大亨游戏','Glengarry Glen Ross','芝加哥一群房地产销售员在一家专门销售佛罗里达、亚利桑那等“度假”区房产的小公司里，竞相争夺最优质的潜在客户。当总公司派来一位精明干练的高管，提出一场残酷的销售竞赛时，竞争变得异常激烈，那些为公司奉献了一辈子的销售员们发现自己的工作岌岌可危。[Artisan]','Lie. Cheat. Steal. All in a day’s work.',12500000,10725228,13.939054,7.5,323,100,'1992-09-15','en','/zcaEDx8KlVfh4vKfMNLhiSi5Oz4.jpg',3.248756716774506,3,'2026-09-10',2,NULL,NULL),(9509,'怒火救援','Man on Fire','一位有厌世倾向的前CIA探员勉为其难地接下到墨西哥市担任10岁小女孩保镖的工作。不料小女孩遭到绑架，他必须不择手段将她平安救回。','Creasy\'s art is death, and he is about to paint his masterpiece.',70000000,130293714,45.299089,7.3,1553,146,'2004-04-23','en','/grCGLCcTHv9TChibzOwzUpykcjB.jpg',3.7754619938005245,3,'2026-09-10',2,NULL,NULL),(9513,'加菲猫2','Garfield: A Tail of Two Kitties','慵懒搞怪的加菲猫又回来了！这次加菲和主人乔恩（Breckin Meyer 布瑞金•梅耶 饰）远赴英国旅行，一路上它花招不断，主仆俩闹出不少的笑话。巧合的是，伦敦有一只出身名门的猫和加菲长得极其相似，阴差阳错之下它们互换了身份，加菲因此享受了一把它梦寐以求的奢侈而豪华的生活。贵族猫继承了主人的泼天财富，引起了主人贪心亲戚达吉斯（Billy Connolly 饰）的忌恨。达吉斯坏招频出，意欲置其于死地，我们的假贵族加菲面对这个凶险的敌人该如何招架呢？','The Ego has landed.',0,141702264,16.930969,5.1,464,78,'2006-06-15','en','/ga1sIcdN6qIcgCfhvJEKQvKRBZ6.jpg',3.087974344902179,3,'2026-09-10',2,NULL,NULL),(9515,'The Matador','The Matador','The life of Danny Wright, a salesman forever on the road, veers into dangerous and surreal territory when he wanders into a Mexican bar and meets a mysterious stranger, Julian, who\'s very likely a hit man. Their meeting sets off a chain of events that will change their lives forever, as Wright is suddenly thrust into a far-from-mundane existence that he takes to surprisingly well … once he gets acclimated to it.','A hitman and a salesman walk into a bar...',10000000,17297244,5.647538,6.2,136,96,'2005-05-12','en','/oJnlAGmrhsg4QrlVKGgP91J6WPu.jpg',2.919167549136371,3,'2026-09-10',2,NULL,NULL),(9516,'社会威胁','Menace II Society','影片开头两位黑人到韩国人开的杂货店买东西，本来好好的，但是两个韩国夫妇从头到尾把他们当贼看，为此发生一点口角，他们就开枪打死了店里的工作人员，之后他们就踏上了不归路了……\r 　　影片导演是黑人休斯兄弟。尽管他们还比不上影坛的另外几对兄弟帮科恩、沃卓斯基、法拉里有名，但是他们的两部低成本电影《威胁2:社会》（Menace2:Society）、《死亡总统》（Dead Presidents）都取得了不错的反响。作为黑人，能够打进电影制作圈在好莱坞也十分不易，而他们正是擅长于展现美国黑人绝望阴郁的生存环境。','This is the truth. This is what\'s real.',3500000,27900000,3.418871,7.2,173,97,'1993-05-26','en','/guvPiEOeXwROpfCb2LkHkVEvOck.jpg',3.0244731569797425,3,'2026-09-10',2,NULL,NULL),(9517,'横行霸道','Bully','波比和马田自小相识，为求金钱及刺激终日沉迷啪丸、蒲基吧、贩卖色情光碟及嬉玩色情电话。波比个性暴戾，常将马田当作发泄工具，拳打脚踢及故意羞辱，甚至连马田的女朋友丽莎及她的好友爱莉亦受波比侵扰。在丽莎的计划下，马田决意与一班郊区少年联手，除去这个眼中钉…','It\'s 4 a.m... do you know where your kids are?',0,480811,6.677093,6.7,125,113,'2001-06-15','en','/vMJ2WHBbK4Jr3eDuF1e7O6lbC8m.jpg',2.925029644160775,3,'2026-09-10',2,NULL,NULL),(9526,'牧场之家好做伴','A Prairie Home Companion','达斯蒂（约翰·C·赖利 John C. Reilly 饰）和莱福蒂（伍迪·哈里森 Woody Harrelson 饰）是一对小有名气的牛仔音乐组合；罗拉（琳赛·洛翰 Lindsay Lohan 饰）对歌唱和音乐保持着永恒不变的热情；尤兰达（梅丽尔·斯特里普 Meryl Streep 饰）和隆达（莉莉·汤普琳 Lily Tomlin 饰）虽然年事已高，却仍然为自己的音乐梦想不断前进着。','Radio Like You\'ve Never Seen It Before',10000000,0,5.025446,6.4,81,105,'2006-06-09','en','/jVdqvd8SgPTWLdG3qc9pSlXGxQi.jpg',2.8107962479841127,3,'2026-09-10',2,NULL,NULL),(9531,'超人3','Superman III','超人又回来了！这次，超人克拉克（克里斯托弗•里夫 Christopher Reeve 饰）回家乡去参加高中同学聚会。聚会上，克拉克重遇了以前就一直心仪的女孩拉娜（安妮特•奥图勒 Annette O\'Toole 饰）。爱火重燃的克拉克对拉娜展开了爱情攻势，两人很快就堕入了情网。正当两人浓情蜜意时，发生了一场灾难。本应马上出动的克拉克因为沉浸在和拉娜共处的时光而延误了救灾，导致了更多无辜的人们的伤亡，为此克拉克感到异常的自责。　　同时，野心勃勃的巨富利用气象卫星技术控制着世界各地的气候以此牟利，造成了很多地方天灾连连。他心知超人一定会来找自己的麻烦，于是不惜重金又制造出了一个超级电脑机器人用来对付超人。克拉克这次能否最终战胜邪恶？','If the world\'s most powerful computer can control even Superman...no one on earth is safe.',39000000,75850624,22.164202,5.3,490,125,'1983-06-17','en','/c4oR6qgZW2s5foGkQi2Dd86KuAS.jpg',3.131911798613854,3,'2026-09-10',2,NULL,NULL),(9532,'死神来了','Final Destination','高中学生艾利克斯-伯朗宁正与法语课的同学们登上一架飞往巴黎的飞机。所有的乘客都已登机并扣好安全带，飞机即将起飞。突然，艾利克斯有了一种强烈的不祥预感，他仿佛看见这架飞机起飞不久便在空中爆炸，变成一团火球。惊恐万状的艾利克斯大吵大闹，让所有人都离开飞机，由此引发了机舱内的一场混战。最后，包括艾利克斯在内的7名乘客被赶出了机舱。　　回到机场后的艾利克斯被其他6名乘客团团围住，其中包括他的朋友比利和托德，一个名叫克莱尔的年轻女郎，曾与艾利克斯扭打在一起的卡特和他的女朋友泰莉，以及自愿留下来照顾艾利克斯等学生的女教师卢顿。正当人们为无法成行的巴黎之旅而恼怒不已的时候，艾利克斯的可怕预感却被悲剧性地证实了。那架飞机在半空中猛烈爆炸，机上无人幸免一死。震惊之余，幸存者们都非常想知道艾利克斯是如何预见到这场惨剧的。有人对他的特异功能很感兴趣，可是大多数的人却很害怕。 FBI探员们也来盘问艾利克斯，而艾利克斯却感到万分愧疚和大惑不解，他很想忘掉这场悲剧，回到正常的生活中去。　　可是艾利克斯看见的却是不断到来的死亡--幸存者们开始一个接一个地死去，死因非常奇怪。艾利克斯终于明白，死神是不可能被骗过的，他和朋友们必须团结在一起才有可能改变自己的命运。','No accidents. No coincidences. No escapes. You can\'t cheat death.',23000000,53302314,38.799596,6.4,1378,98,'2000-03-16','en','/Opq2EIUJ2ksDGyGwcpzWeFnVPM.jpg',3.548592899283076,3,'2026-09-10',2,NULL,NULL),(9533,'红龙','Red Dragon','最近出现了一起凶徒连环杀人案，最令人恶心的是，凶徒每次作案后都将被害者的喉咙割走。FBI探员威尔（爱德华•诺顿 Edward Norton 饰）负责此案的侦察，经过详细调查，威尔分析此人每次都是将被害者的喉咙割走吃掉，然而却没有找到任何凶徒的蛛丝马迹。威尔向患有精神病的犯罪心理学家汉尼拔（安东尼•霍普金斯 Anthony Hopkins 饰）求助，希望汉尼拔能刻画出凶徒的犯罪心理以助破案。不料汉尼拔精神病发，意图伤害威尔，最后被关进了精神病监狱，此案也就不了了之。多年后，威尔又遇到了一起相同的谋杀案。虽确定了犯罪嫌疑人，但若想清楚推敲出此人的犯罪心理，以将其乘之于法，威尔只好再次找到了汉尼拔。','Before the Silence.',78000000,209196298,10.083905,6.7,1115,124,'2002-09-29','en','/ng1I2aIEXy7lZRaT9cQO0zojaI8.jpg',3.487233438848164,3,'2026-09-10',2,NULL,NULL),(9535,'老大靠边闪','Analyze This','纽约黑社会老大保罗深感自己患上了心脏病，虽然体检报告并没有任何征兆，但他还是在老朋友的介绍下，找了离婚的心理医生本治疗。在治疗中，保罗的黑帮作风令本胆战心惊，但是这次交流却让他的焦虑症得以缓解。此后，即使遇到房事的困扰，他都会对本一吐衷肠。不过，正与未婚妻劳拉度蜜月的本显然对此准备不足。警方发现了医生与黑帮的关系，派他做卧底。与此同时，保罗也钦点他作为私人医生，形影不离。在闹出很多啼笑皆非的笑话后，保罗和本都从中得到了某种心理补偿。','New York\'s most powerful gangster is about to get in touch with his feelings. YOU try telling him his 50 minutes are up.',80000000,176885658,29.415229,6.4,503,103,'1999-03-05','en','/c7cnPWpTOF3DCopk1Y0g421BhZ2.jpg',3.2874049683953173,3,'2026-09-10',2,NULL,NULL),(9541,'泽西女孩','Jersey Girl','身为一名颇有名气的乐评人，奥利（本·阿弗莱克 Ben Affleck 饰）在职场上可谓是风生水起，除了事业上的成功外，美丽的妻子和可爱的女儿格蒂（雷奎尔·卡斯特罗 Raquel Castro 饰）也让他觉得生活几近完美。可是，妻子的突然辞世让这些美好都成为了泡影，祸不单行，不久之后，情绪低落的奥利丢掉了原本收入颇丰的工作。无奈之下，奥利只得带着格蒂回到了位于新泽西的老家。乡下宜人的风景和闲散的生活并没有治愈奥利受伤的心灵，反倒是格蒂感到如鱼得水，不仅仅是因为这里的好气候，更是因为从前忙碌的父亲如今有了更多的时间陪伴自己。机缘巧合之下，奥利遇见了名叫玛雅（丽芙·泰勒 Liv Tyler 饰）的女孩，而这珍贵的相遇终于让他明白了，究竟什么才是生命中最重要的东西。','He wanted it all...but he got more than he bargained for.',35000000,36098382,14.699342,5.8,325,102,'2004-03-25','en','/fVmGWUnuzQJC2qJ48cqq0Tw16pR.jpg',3.0950340199104454,3,'2026-09-10',2,NULL,NULL),(9543,'Prince of Persia: The Sands of Time','Prince of Persia: The Sands of Time','A rogue prince reluctantly joins forces with a mysterious princess and together, they race against dark forces to safeguard an ancient dagger capable of releasing the Sands of Time – gift from the gods that can reverse time and allow its possessor to rule the world.','Defy the Future',150000000,335154643,62.169881,6.2,2317,116,'2010-05-19','en','/19tO1KBLTXvrJDpRqQghZyIsVGN.jpg',3.6782940193696554,3,'2026-09-10',2,NULL,NULL),(9544,'非请勿进','FearDotCom','麦克 是一名心怀大志的警探，最近，一宗连环杀人案件吸引了他的注意，已经有四人成为了残酷凶手刀下的猎物。在搭档泰瑞 的帮助下，麦克开始了对案件的调查。','The last site you\'ll ever see.',40000000,18902015,6.756886,3.2,105,101,'2002-08-09','en','/phcd5AJvA1S45JMKYoNLhTzFwsE.jpg',2.7517856142063963,3,'2026-09-10',2,NULL,NULL),(9548,'神探奇兵','The Adventures of Ford Fairlane','福特的“摇滚侦探先生”费尔莱恩遇到了问题，而且不是针对异性。其中之一就是所有的摇滚明星都给他鼓棒、考拉熊、食品加工机和自行车短裤。另一件事是，所有想让他找到一个叫Zuzu Petals的女孩的雇主都被杀了。为什么他没有成为渔民侦探呢?安德鲁·戴斯·克莱迷的必看景点。','Kojak. Columbo. Dirty Harry. Wimps.',49000000,20423389,2.808428,6.2,71,104,'1990-07-11','en','/u6accimG7LmroR8WgNklEJS7oFq.jpg',2.771192106979922,3,'2026-09-10',2,NULL,NULL),(9549,'太空先锋','The Right Stuff','影片讲述了美国首批水星计划七位宇航员的传奇故事，展现他们凭借勇毅胆识与直觉魄力开创航天纪元的历史篇章。','How the future began.',27000000,21500000,17.567332,7.3,235,193,'1983-10-20','en','/zkPYW7BeAf5HOrklTzW53c37ip.jpg',3.147254253688503,3,'2026-09-10',2,NULL,NULL),(9550,'十面埋伏','十面埋伏','唐大中十三年，民间涌现不少反昏君反腐官的组织，其中以打着“杀富济贫推翻朝廷”旗号的飞刀门的势力最大。飞刀门总部设在靠近都城长安的奉天县境内，为保长安安全，朝廷下令奉天县府将飞刀门成员悉数剿灭。\r 奉天县两大捕头刘捕头与金捕头收到限期缉拿飞刀门新任帮主归案的命令。因怀疑牡丹坊的舞妓小妹是飞刀门前帮主的女儿，刘捕头设计将她拿下押入天牢，后又与金捕头再度设下圈套令金捕头化身义士将她救出，想骗取她的信任查出飞刀门的巢穴，但他不知的是，除了在公务上与金捕头和小妹打交道外，私情上也会与他们有番纠缠。',NULL,0,92863945,21.064082,7.1,439,119,'2004-05-19','zh','/unOXxCipNht3h7RPhGy6OZKe5Gv.jpg',3.315012772030207,3,'2026-09-10',2,NULL,NULL),(9552,'驱魔人','The Exorcist','一名12岁女孩（琳达·布莱尔 饰）被神秘实体附身，她的母亲向两位神父求助以拯救女儿。','Something almost beyond comprehension is happening to a girl on this street, in this house... and a man has been sent for as a last resort. This man is The Exorcist.',8000000,441306145,47.584643,7.5,2005,122,'1973-12-26','en','/5x0CeVHJI8tcDx8tUUwYHQSNILq.jpg',3.898940546634352,3,'2026-09-10',2,NULL,NULL),(9555,'漫漫回家路','Rabbit-Proof Fence','故事发生在二十世纪初期，澳大利亚政府决定实行一项残酷的计划，他们强行将白人与当地土著所生的混血孩子们从亲人身边带走，编入摩尔河营地，通过训练和教化将他们变为廉价劳动力，更妄图用包办婚姻来改变他们那所谓的“低贱血统”。  　　14岁的莫利（Everlyn Sampi 饰）就是这些孩子中的一员，无法忍受营地里的痛苦生活，勇敢的她决定出逃。和莫利一起逃跑的还有黛西（Tianna Sansbury 饰）和格雷西（Laura Monaghan 饰），三个女孩将要面对的是一千五百英里的漫漫路途和在她们身后穷追不舍的木都（大卫·古皮利 David Gulpilil 饰）。三个孩子能够顺利的到达目的地吗？在那里，又会有着怎样的生活在等待着她们呢？','Follow Your Heart, Follow The Fence',0,0,2.128211,6.8,84,94,'2002-02-04','en','/vs8ATIRGEEYpcByrNtJ1WyI3LeD.jpg',2.82467465671325,3,'2026-09-10',2,NULL,NULL),(9557,'寻爱旅程','Boat Trip','为了安慰刚刚惨遭女友抛弃的朋友杰瑞（小库珀·古丁 Cuba Gooding Jr. 饰），尼克（霍拉提奥·桑斯 Horatio Sanz 饰）陪伴着杰瑞登上了前往地中海的邮轮，尼克将希望寄托在了船上的旅客身上，希望从中找到能够安抚杰瑞情商的人。\r 令伙伴两人没有想到的是，这条船上搭载的竟然一帮同性恋者，在旅途中，杰瑞和尼克似乎还颇受欢迎的样子。幸运的是，途中，两位好友偶遇了一帮瑞典女子游泳队员，其中，一个名叫加布里拉（罗塞莉·桑切斯 Roselyn Sanchez 饰）的漂亮姑娘吸引了杰瑞的注意，而尼克亦遇见了自己的梦中情人。糟糕的是，加布里拉误认为杰瑞和船上的其他男人一样是同性恋者，而游泳队的教练也下达了交际禁令，禁止姑娘们和男人调情。','... once you\'re on, you\'ll want to get off...',20000000,8586376,7.034752,4.7,146,94,'2002-10-01','en','/xHFJt9nEfVIUItBfKZr7qhbgveL.jpg',2.86275262982433,3,'2026-09-10',2,NULL,NULL),(9562,'重返中世纪','Timeline','老教授爱德华·乔斯顿（比利·康诺利 Billy Connolly 饰）是一名致力于中世纪考古的历史学家，而发掘14世纪遗留下的拉洛克城堡一直是他的毕生心愿，然而直到今天，一家国际科技公司的总裁罗伯特（大卫•休里斯 David Thewlis 饰）愿意投资该项目，乔斯特的愿望才终于得以实现，他便马不停蹄地与儿子克里斯（保罗·沃克 Paul Walker 饰）一起组建了考古小组准备前往法国，探寻当年的古战场。然而考古小组成员在一次很平常的挖掘中，发现了一张1357年的求救纸条，署名竟然是乔斯顿教授，附近还发现了教授的眼镜，但距今已600多年。百思不得其解的组员们找到投资人罗伯特，方知野心勃勃的罗伯特竟秘密发明了一架时光机器，能穿越虫洞将人送回到1357年。面对着这个可怕而神奇的工具，克里斯决定带领成员一同重返中世纪，拯救父亲。然而他们谁也无从预测，在虫洞的另一头等待着他们的会是什么……','They had to travel into the past to save the future',80000000,19480739,11.22268,5.4,318,116,'2003-11-26','en','/6zP5zNiErMVPElNj1yYbQLD3zDi.jpg',3.0463461516170964,3,'2026-09-10',2,NULL,NULL),(9563,'挑战星期天','Any Given Sunday','威利（杰米·福克斯 Jamie Foxx 饰）本是一位名不见经传的橄榄球运动员，在一次极为艰巨的比赛中，他临危受命上场征战。威利出色的表现吸引了球队老板克里斯蒂娜（卡梅隆·迪亚茨 Cameron Diaz 饰）的注意，她看出威利是一名可塑之才，而威利之后的表现也并没有让克里斯蒂娜失望。  　　一夜成名让威利的自我开始膨胀，骄傲与自满逐渐占据了他的内心，作为球队的教练，经验丰富的托尼（阿尔·帕西诺 Al Pacino 饰）知道威利正处在一个非常危险的状态之下，然而对于托尼的忠告，威利置若罔闻。威利离开了旧日女友，和队员们的关系也越来越差，与此同时，他所效忠的球队也正在面临着前所未有的重大危机。','Play or be Played.',55000000,100230832,23.127561,6.8,422,163,'1999-12-16','en','/bysZeUvSPZPJnku4qkHF34CdgMG.jpg',3.2754250587359706,3,'2026-09-10',2,NULL,NULL),(9566,'烈火终结者','The Fan','球迷崇拜明星球员的情况十分普遍，但走火入魔之后却容易失控。本片男主角吉尔雷纳是个刀具推销员，他一向将黑人棒球选手巴比·雷朋作为偶像。当巴比的运动事业攀上高峰，吉尔自己却走进人生的底端，既离婚又失业。于是他把自己生存的目的完全投注在巴比身上，为了维护巴比的巨星地位而不惜恐吓、杀人，甚至绑架巴比的儿子威胁他一定要击出全垒打。','All fans have a favorite player.  This one has a favorite target.',55000000,18626419,4.366488,5.7,194,116,'1996-08-15','en','/lu7CjP8YES5dJMCFg5O9o9jCkjl.jpg',2.9627404432561537,3,'2026-09-10',2,NULL,NULL),(9567,'太阳泪','Tears of the Sun','美国海军下属“海豹”特种突击队队长沃特斯（布鲁斯·威利斯 Bruce Willis 饰）带领一支小分队前往非洲密林执行命令：把在当地进行紧急医护工作的莱娜医生（莫妮卡·贝鲁齐 Monica Bellucci 饰）营救出来。小分队很快找到了莱娜医生，但在最后关头莱娜医生提出要把这里的70个难民一起转移的要求，否则自己也不会离开。沃特斯犯难了，非洲原始丛林天险众多，而且有剧毒莫测的野生动物，小分队人数不够，如何带着70个老弱病残逃离？然而人道主义最终打了胜仗，这支小分队在前有丛林、后有追兵的情况下带领这浩浩荡荡几十人开始了转移的道路，一个接一个的士兵倒下，生命的价值在这里人人平等。','He was trained to follow orders. He became a hero by defying them.',70000000,85632458,27.055085,6.4,573,121,'2003-03-07','en','/1wfMQzmzEYcMnQWEDcLHy3zdRvS.jpg',3.3129977739893275,3,'2026-09-10',2,NULL,NULL),(9570,'黑洞','The Black Hole','在外太空探险的美国“天鹅号”太空船，由冷酷严峻的蓝刻博士领导，他有著一个狂妄的科学计画，正阴谋进行中，机缘巧遇的“天鹅号”找到了宇宙最神秘的禁地——黑洞，他们不顾一切的闯入，经历了人类前所未有的冒险历程。','A journey that begins where everything ends!',20000000,35841901,8.265317,6.1,131,98,'1979-12-18','en','/gCqOJWvOK5UPospyrLANKfwRBlG.jpg',2.912372425511729,3,'2026-09-10',2,NULL,NULL),(9571,'年少轻狂','Dazed and Confused','1976年，美国。学期最后一天。水烟袅袅，喇叭裤摇曳，摇滚乐响彻云霄。作为有史以来最杰出的青春片之一，本片潜入一群准高三生和新生的世界。理查德·林克莱特首部制片厂作品为众多未来明星提供了起跳板，其台词令人回味无穷，配乐更是具有体育场级别的震撼力。影片拒绝怀旧，与其说是关于\"人生中最美好的岁月\"，不如说它捕捉了青少年在等待——等待某些事情发生——时的百无聊赖、焦虑与兴奋。[标准收藏]','See it with a bud.',6900000,7993039,26.181753,7.4,583,102,'1993-09-24','en','/msG9awbLhVZwv1Eh9Ge7SofMexW.jpg',3.4484871932655907,3,'2026-09-10',2,NULL,NULL),(9573,'血腥拼图','Blood Work','近来，令罪犯们闻风丧胆的联邦调查局探员特瑞（克林特·伊斯特伍德 Clint Eastwood 饰）正在调查一个名为“密码杀手”的神秘人物，就在这个节骨眼上，突发的心脏病让特瑞不得不提前走下了工作岗位，在接受了心脏移植手术后，退休的特瑞选择远离危险的工作，来到了偏僻的乡下静养。  一转眼，两年过去了，一个名叫格莱夏埃拉（旺达·德·杰索斯 Wanda De Jesus 饰）的神秘女子的来访扰乱了特瑞平静的生活。原来，为特瑞提供心脏的是格莱夏埃拉的妹妹，巧合的是，她就是“密码杀手”手下诸多的受害者之一。以此为契机，特瑞重新开始了对于凶手的调查和追击，就在他逐渐接近真相的同时，危险也来到了他的身边。','He\'s a heartbeat away from catching the killer',50000000,26199517,10.089065,6.1,206,110,'2002-08-04','en','/A6wWJkIREagRWFNu3YotID3n9aW.jpg',3.0139791214964733,3,'2026-09-10',2,NULL,NULL),(9574,'飞天法宝','Flubber','从事研究工作的菲利普博士，其生活可用一个“忙”字概括，忙到把婚礼忘记，让新娘在教堂苦等。但他的研究却取得突破：他找到一种绿色物质，它可以克服地心吸力，不管涂在什么东西上，人或者车，都可以腾空而起，自由自在地在天空中飞翔。不过这种物质自身也有脾气，随时会捉弄一下使用它的人。为了把伤心而去的未婚妻找回来，也为了挽救他所在学校关门的命运，他把新发明用在了校篮球队队员的球鞋上，结果球队大胜而归。但同时也招来别有用心者对新发明的觊觎。结果有一天，他的法宝真的不翼而飞了。这样一来，未婚妻又会说他瞎忙而不肯回到他身边。  　　一名天生脱线、终日沉浸于科学研究的菲利普博士(罗宾威廉斯饰)，连自己的婚礼都忘记参加，留下新娘一个人在教堂里。平常照料博士的是一名充满活泼干劲的机器人——薇波(WEEBO)，虽然偶尔会出点小状况，但薇波还是帮了博士不少的忙。然而，薇波一直对博士存有好感。所以，当博士的未婚妻决定再给博士一次机会时，却被薇波从中捣乱，故意把结婚的时间记错，就这样再次地错过了步入礼堂的时间。  　　就在此刻，博士有了一个破天荒的发现，他发明了一种神奇的绿色橡胶，可以抵抗地心引力，只要将它涂抹在任何物体上，就可以让该物体自由飞翔，唯一的缺点就是这玩意儿，颇具个性，而且顽皮，必须花费一段时间才可以掌握他的个性。于是，有了飞天法宝的协助，博士挽回了他的婚姻，同时替妻子就职的学校成功地撑过关门大吉的难关。此外，他们还将飞天法宝涂在原本溃不成军的篮球队的球鞋底下，却出乎意料地打败了敌队。  　　好景不常的是，当博士彰显了飞天法宝的特殊效能时，却引来了坏蛋的觊觎，想利用飞天法宝来做不法之途，正当博士与薇波不注意时，飞天法宝不见了，究竟博士要如何凭一己之力才能找回飞天法宝呢？而调皮捣蛋的绿色小精灵在坏蛋的控制之下会有什么惊人之举呢？','Catch it if you can!',80000000,177977226,11.50396,5.3,695,93,'1997-11-26','en','/hVdGW5t7FghJ9j0SCUrCw0Sj4ty.jpg',3.162335831006433,3,'2026-09-10',2,NULL,NULL),(9576,'窈窕淑男','Tootsie','在本片中，迈克尔·多西得到了一个千载难逢的角色——饰演他的演员达斯汀·霍夫曼亦如此。这部由西德尼·波拉克执导的多层次喜剧，讲述了一位时运不济的纽约演员精心设计的骗局：他假扮女性，只为获得一个肥皂剧角色。当“多萝西·迈克尔丝”一举成名时，迈克尔却发现自己正在学习成为一个更好的人。影片拥有耀眼的演员阵容：达布尼·科尔曼、查尔斯·德宁、特丽·加尔、乔治·盖恩斯、比尔·默瑞，以及凭借突破性表演脱颖而出的杰西卡·兰格。在性别与社会身份动荡变化的美国时代背景下，本片以幽默、尖锐而深刻的笔触，成为一部笑中带泪的经典之作。[标准收藏]','What do you get when you cross a hopelessly straight starving actor with a dynamite red sequined dress? You get America\'s hottest new actress.',21000000,177200000,20.818567,6.9,421,116,'1982-12-16','en','/ngyCzZwb9y5sMUCig5JQT4Y33Q.jpg',3.2805113571772533,3,'2026-09-10',2,NULL,NULL),(9582,'A Guy Thing','A Guy Thing','Paul Morse is a good guy. When his friends throw him a wild bachelor party, he just wants to keep his conscience clean -- which is why he\'s shocked when he wakes up in bed with a beautiful girl named Becky and can\'t remember the night before. Desperate to keep his fiancée, Karen, from finding out what may or may not be the truth, he tells her a teensy lie. Soon his lies are spiraling out of control and his life is a series of comical misunderstandings.','Boy meets girl. Boy meets girl\'s cousin.',20000000,17432163,5.596835,5.3,83,101,'2003-01-17','en','/wWiPuP1wMW32pjX8Q9TEj69TxWI.jpg',2.7837701651709823,3,'2026-09-10',2,NULL,NULL),(9583,'丫丫姐妹们的神圣秘密','Divine Secrets of the Ya-Ya Sisterhood','希达（桑德拉·布洛克 Sandra Bullock 饰）是一名生活在纽约的年轻有为的剧作家，虽然在纽约这座大城市打拼十分的不容易，但是因为这里离她的老家非常的远，希达非常喜欢这里的生活——如此一来，她就可以远离自己古怪的母亲薇薇（艾伦·伯斯汀 Ellen Burstyn 饰）。  一天，在一次采访中，希达委婉的表达了对于母亲的不满，哪知道薇薇看到了这篇报道，她怒了。薇薇的怒火一路烧到了希达的男友身上，这个男人不离不弃的追了希达7年，并且即将和她携手步入婚姻的殿堂。薇薇的好姐妹们也非常着急的想要帮助薇薇修复她和女儿之间的关系，这些人包括梅丽莎（菲奥纽拉·弗拉纳根 Fionnula Flanagan 饰）、萝丝（雪莉·奈特 Shirley Knight 饰）和卡洛（玛吉·史密斯 Maggie Smith 饰）','The Secret Is Out.',27000000,0,5.576937,5.6,65,116,'2002-06-07','en','/hI05FJ8wgPROHQgLtfJ4ZuH3l4b.jpg',2.743694898434394,3,'2026-09-10',2,NULL,NULL),(9587,'小妇人','Little Women','丈夫远赴战场后，马奇太太独自抚养四个女儿——她珍贵的“小妇人”。她们分别是桀骜不驯的乔、娴静保守的梅格、柔婉脆弱的贝丝，以及浪漫多情的艾米。时光荏苒，在母亲与马奇姑婆的引领下，四姐妹历经关于独立、爱情与品格的种种考验，共同编织了成长路上那些最珍贵与痛楚的自我觉醒记忆。[索尼影业]','The story that has lived in our hearts for generations, now comes to the screen for the holidays.',18000000,0,16.418639,7,215,115,'1994-12-21','en','/igwEs4YBwa2RYW859576C40PYWv.jpg',3.0991814614662507,3,'2026-09-10',2,NULL,NULL),(9588,'捍卫游侠','Quigley Down Under','并不是美国才有拍西部片的场景的，澳洲内陆那广袤无垠的荒野和茂密的丛林同样也是西部片的绝佳片场。而确实曾在澳洲客观存在的种族主义，也使得导演可以无缝隙的把美国西部片中常有的殖民者对印第安人的冲突移植到澳洲白人与土著民之间的冲突上来。当然要想成为一部成功的西部片，一定还要有机智的对话，精彩的动作场面，精湛的演技，抢眼的美女和骠悍冷峻的牛仔。而本片在这些方面也都做得不错，再加上独有的澳洲风情。进入九十年代以后，好莱坞已经极少出西部片了，而这部澳洲出品的现代西部片，可以说是西部片迷们一个不错的替代品。','There\'s a price on his head. A girl on his mind. And a twinkle in his eye.',0,0,11.360997,6.5,119,119,'1990-10-17','en','/93HWOYFsjLsCJC8RawGLv1ANZwS.jpg',2.915643563357758,3,'2026-09-10',2,NULL,NULL),(9591,'挡不住的奇迹','That Thing You Do!','影片讲述了六十年代一队名为“奇迹”的摇滚乐队从小镇迅速崛起成为全国知名偶像，但又有如流星般消逝的经过。组成乐队的四位年轻人之中，以沉迷爵士乐的鼓手汤姆·埃弗里特·斯科特和自我为中心的作曲歌手强纳·森萨奇的瑜亮之争的主要戏剧矛盾，清丽佳人莉芙·泰勒则扮演全力支援此乐队的热心歌迷，汤姆·汉克斯客串乐队经理人。在那个基本上社会气氛仍然相当纯洁的1964年，演出了这段一曲成名的歌坛传奇。','In every life there comes a time when that dream you dream becomes that thing you do.',0,34585416,14.885388,6.8,225,108,'1996-10-04','en','/9RmZu33qHdyZFGLfhEOmkTjdNEu.jpg',3.093503047656992,3,'2026-09-10',2,NULL,NULL),(9593,'幻影英雄','Last Action Hero','杰克系列电影是由施瓦辛格主演的系列电影。在这电影中，施瓦辛格扮演的杰克（阿诺•施瓦辛格 Arnold Schwarzenegger 饰）总是世界的救世主，每当他的老对头班尼迪（查里斯•丹斯 Charles Dance 饰）出来作恶时，杰克总是能及时赶到，讲班尼迪打得落花流水。小男孩丹尼是杰克系列电影的忠实影迷，杰克系列电影的前三集他都能倒背如流。这天他的好朋友，电影放映员尼克给了丹尼一张神奇的电影，丹尼凭着这张电影票进入到了还未上演的杰克系列第四集中。不料班尼迪抢走了丹尼的电影票，从电影中来到了现实中。他的目标就是除掉杰克的扮演者施瓦辛格，这样在电影世界里就不再有人能够阻止他的邪恶计划。','This isn\'t the movies anymore.',85000000,137298489,32.044191,6.1,712,130,'1993-06-18','en','/ArQIyajM38EpGeads6bNH39zSYr.jpg',3.3316527676085155,3,'2026-09-10',2,NULL,NULL),(9594,'绝地双尊','Double Impact','尚克劳德范达美一人分饰Alex和Chad这对双胞胎的二个角色，两人目前都是出色的武术专家，当年在父母被凶杀的那天因故分散了，其中Chad被老仆人收养在巴黎抚养长大，Alex变成香港一个三流的小混混。一天，chad看到了Alex的照片，到香港找寻这个失散多年的双胞胎兄弟，并发现杀害两人父母的凶手正是Alex在香港的死对头。但是，对Alex而言，这名从法国来的兄弟疑点重重，尤其是这个和自己有着同样面貌的兄弟和自己的女友似乎互有好感……','Two brothers separated by the violence. Now together in a mission of revenge.',15000000,30102717,10.484642,5.3,215,110,'1991-08-10','en','/tmzwvSqoMC37Tgqwj4mA2dHNSmw.jpg',2.96940225192324,3,'2026-09-10',2,NULL,NULL),(9598,'小猪宝贝','Babe','一部关于不合群的温馨真人童话，讲述一只平凡小猪为寻找接纳而竭尽全力的故事。','A little pig goes a long way.',30000000,254134910,34.36645,6,733,89,'1995-07-18','en','/7mPKIdCVIuPEE0FpYX7UE91yWaW.jpg',3.328186141507073,3,'2026-09-10',2,NULL,NULL),(9600,'卧底肥妈','Big Momma\'s House','FBI探员马刚（马丁•劳伦斯 Martin Lawrence 饰）聪明能干，屡破奇案，而他的破案法宝就是他那高超的伪装绝技，无论什么人，他都自信能扮得惟妙惟肖。新的案子摆在了马刚面前，乔治亚州一个银行抢劫犯身怀巨款逃亡了，马刚奉命前往缉拿，唯一的线索就是抢劫犯的女友雪梨（尼娅•朗 Nia Long 饰）。为了接近雪梨，马刚施展他的变身特技，化身成了雪梨久未碰头的姑母，一个超过两百磅的“老妈子”。马刚的特技堪称一绝，经过化身易容，成功接近了雪梨。然而相处久了，马刚却发现自己爱上了可能有份参与收藏赃款的雪梨，更要命的是，真正的姑母登场了。','This FBI agent is going undercover... and he\'s concealing more than a weapon.',30000000,173959438,24.389194,5.6,506,98,'2000-05-31','en','/5YoSFqpTz5qIxsX61CPMGKONQIY.jpg',3.178959813117511,3,'2026-09-10',2,NULL,NULL),(9603,'独领风骚','Clueless','故事发生在位于比弗利山庄的一所贵族学校中，能够进入此学校就读的学生们，非富即贵，所以，校园里奢侈和自由的风气和普通的学校是无法相比的。在这里，成绩和品行都不重要，重要的是五颜六色的名牌时装，是闪闪发光的珠宝配饰，是张扬奔放肆意挥洒的个性。我们的主人公雪儿（艾丽西亚·希尔维斯通 Alicia Silverstone 饰）就在这样的世界里生活成长着。一位转学生的到来吸引了雪儿的注意，在偌大的校园里，在同学朋友的眼中，这名转学生简直就是“怪胎”，穿着平庸打扮又土气，雪儿决定帮助她改头换面，“重新做人”。在雪儿的指导下，转学生果然有了焕然一新的面貌，甚至更胜雪儿一筹，这让雪儿的内心里十分不平。','Sex. Clothes. Popularity. Is there a problem here?',12000000,0,16.051328,6.9,803,97,'1995-07-19','en','/tfHtFWk4uNgrPWEOTSt9qb66ZDa.jpg',3.446934656557391,3,'2026-09-10',2,NULL,NULL),(9607,'超级马里奥兄弟','Super Mario Bros.','传说在地球被一颗陨石撞击之后，另一半的星球上的生灵在日益毁坏的生态环境下，面临越来越痛苦的境遇。斯凯普林管道公司在挖掘地下时，将两个世界打通。马里奥和鲁基兄弟本来是管道工，因为戴西被抓，他们一同进入岩层，来到由库帕控制的另一个世界。库帕运用他的机器，可以将生物随意进化或退化，而可以统一两个世界的正是戴西，她手中的陨石碎片成了大家争抢的目标。兄弟二人发挥了他们的所长，帮助戴西使父亲复原，并稳定了混乱的局势。','This Ain\'t No Game.',48000000,20915465,14.587367,4,232,104,'1993-05-28','en','/7MzTVSUsXu5ibDVO1nIS1FOrgJM.jpg',2.897685320301639,3,'2026-09-10',2,NULL,NULL),(9610,'毁灭者柯南','Conan the Destroyer','在地球的蛮荒年代，一名公主被巫师所捕获，邪恶的皇后为了拿公主为祭品以永远拿王座，传唤力大无穷的壮硕剑客科南前来寻找公主的下落。失去挚爱而失魂落魄的科南，在明白唯有藉助皇后的神秘魔力，才能使爱人死而复生的道理下，与皇后订下约定，若将公主从巫师手中安全救回城堡，皇后将不计一切代价，设法将他的爱人复活。  在荒野中四处冒险的科南，幸有斗士、男巫以及小偷的协助，使得他能够化险为夷，然而，科南可以安全救回公主吗？失去的挚爱能够重新回到科南身边吗？一段与超自然的邪恶力量对抗的竞赛，正紧锣密鼓进行中  该片在1981年时，改编作者罗伯特·霍华德的《剑上的凤凰》短篇小说，内容主要描写“蛮王柯南”的传奇故事，并由当时尚未走红的动作男星阿诺德·施瓦辛格所主演。','The most powerful legend of all is back in a new adventure.',18000000,100000000,18.379124,5.8,383,103,'1984-06-29','en','/m5i7S46DT1ESy7URkh2l92awGRr.jpg',3.135612031290259,3,'2026-09-10',2,NULL,NULL),(9613,'蜘蛛梦魇','Spider','一部心理惊悚片，讲述一名男子（拉尔夫·费因斯 饰）从精神病院提前获释后，试图重新拼凑起自己生活的故事。','The only thing worse than losing your mind... is finding it again.',0,0,6.948401,6.4,168,98,'2002-12-13','en','/slTjaIfHgpTnIw34g1D0nREmnmY.jpg',2.979755294371456,3,'2026-09-10',2,NULL,NULL),(9614,'高尔夫球也疯狂','Happy Gilmore','Happy Gilmore是一名狂热的冰球爱好者，从小由奶奶抚养大。由于他实在离一个冰球运动员的要求实在太远——他有严重的暴力倾向，而且最要命是他不会滑冰——Gilmore被教练赶出了冰球队，与此同时女朋友也离他而去，而Gilmore的奶奶因为无法承受高额税款，住了几十年的老房子被收回作抵押。一个偶然的机会，Gilmore发现自己在高尔夫球方面天赋异禀，在业余组比赛[1]  一鸣惊人后，Gilmore有机会参加有巨额奖金的大师赛，与此同时，Gilmore的火爆性格和球风也为他赢得了fans，爱情以及一位退休老球手的指点，自然也使一些对手产生了嫉恨……','He doesn\'t play golf... he destroys it.',12000000,41205099,26.598884,6.5,755,92,'1996-02-16','en','/f6cTYFHGsQPZt4NLH4CMWcsk78F.jpg',3.3929499586550995,3,'2026-09-10',2,NULL,NULL),(9615,'速度与激情3：东京漂移','The Fast and the Furious: Tokyo Drift','东京一直是改装汽车爱好者的天堂，复杂狭窄的街道成为了他们用激情和速度去拼杀的赛道。由于东京街道的弯道极度，在这样的路线上比拼速度，单纯的速度是无法获得胜利。所以，东京的街道赛变成了漂移技术的比赛。男主角尚恩注定是个失败者，在学校毫无朋友，唯一能发泄的地方就只有街头赛车，在经历一次非法赛车被警方通缉后，为躲避牢狱之灾，不得不离开美国，到东京他在军中服役的父亲家中。可是父亲的专制，让尚恩觉得与其格格不入，每天仍然沉迷于街头赛车中。东京赛车极高的漂移技术把尚恩深深吸引，并结识了“漂移之王”DK。由于与日本的犯罪集团扯上关系，尚恩不得不为弥补自己的过失再次比赛，而这次比赛的赌注却是自己的生命。一场东京狂飙，就此拉开……','On the streets of Tokyo, speed needs no translation...',85000000,158468292,8.282876,6.1,1705,104,'2006-06-03','en','/53GLm0Ym92zhjRGlxbF6sNZ8zyK.jpg',3.4660414627399985,3,'2026-09-10',2,NULL,NULL),(9616,'食罪人','The Order','艾利克斯（希斯•莱杰 Heath Ledger 饰）是一名神父，但他不是那种行事作风老派的神父，正相反，他对教会内部高层做出的某些举动感到非常的不满，他自然也是他们的眼中钉肉中刺。艾利克斯的朋友死了，警方调查之后判断这是一起自杀案件，然而，尸体上一个神秘的印记让艾利克斯起了疑心，为了调查朋友死亡的真相，他找到了负责调查此案件的尽管马拉（莎妮•索萨蒙 Shannyn Sossamon 饰）。\r 　　艾利克斯将尸体上的标记送到了他位于梵蒂冈的老师多米尼克神父（弗朗切斯科•卡尔内卢蒂 Francesco Carnelutti 饰）手中，教会给出的种种反应更加坐实了艾利克斯的猜测。当艾利克斯一步一步的接近真相的同时，危险也在接近着他。','Every soul has its price.',35000000,11560806,3.746806,4.8,91,102,'2003-09-05','en','/7kj4TffoKCt4gIrNupr2oqmir69.jpg',2.780504122884347,3,'2026-09-10',2,NULL,NULL),(9618,'怒虎狂龙','Tango & Cash','警探探戈及加什，行动勇猛，办案搏命，在某项行动中，破获庞大白粉走私案，黑帮损失极大，于是设下圈套，令二探员成为杀人凶手，被判入狱。黑帮又买通狱长，要玩残两人，两人只有逃狱。往找黑帮晦气，及找出证据证实二人无辜！','Two of L.A.\'s top rival cops are going to have to work together... Even if it kills them.',55000000,63408614,22.787667,6.1,458,104,'1989-12-22','en','/jxxxjTu87OSmQYkMFF7MgOEDXRn.jpg',3.215280122260647,3,'2026-09-10',2,NULL,NULL),(9619,'天崩地裂','Dante\'s Peak','研究火山的科学家哈里在工作中痛失爱妻，四年后他又受命去但丁峰进行地震测试。他测试的结果是火山存在异常活动，有喷发的迹象。但他发出警告的意见为上司所阻。但丁峰小镇的镇长瑞切尔是个单身母亲，她正准备组织一个庆祝活动，因为小镇刚刚获得一个全美最佳居住环境奖。在这种背景下，谁也不愿相信火山即将喷发的事实。但是哈里秉承科学家的良心还是坚持自己的意见。就在疏散工作正在进行的时候，火山爆发了。惊慌的人们纷纷逃离，但瑞切尔却要逆流而上去寻找她的女儿，哈里勇敢地挺身而出，驾车向山上开去……','The pressure is building...',116000000,178127760,16.90444,5.7,428,108,'1997-02-07','en','/AdnDhNBsDHtjp47UPI47YHgGd6X.jpg',3.142811690310769,3,'2026-09-10',2,NULL,NULL),(9620,'Paycheck','Paycheck','Michael Jennings is a genius who\'s hired – and paid handsomely – by high-tech firms to work on highly sensitive projects, after which his short-term memory is erased so he\'s incapable of breaching security. But at the end of a three-year job, he\'s told he isn\'t getting a paycheck and instead receives a mysterious envelope. In it are clues he must piece together to find out why he wasn\'t paid – and why he\'s now in hot water.','Remember the future.',60000000,96269812,29.018826,5.9,581,119,'2003-12-25','en','/h91HmkI6cYyVnqBtzsmirE0pNcV.jpg',3.254228062594226,3,'2026-09-10',2,NULL,NULL),(9621,'伊丽莎白镇','Elizabethtown','德鲁（奥兰多·布鲁姆 Orlando Bloom饰）陷入了人生的谷底期，他设计的产品给公司带来了数亿元的损失，被老板炒鱿、被女友甩掉。万念俱灰中，他决定一死了之。可这时，一个电话 阻止了他的自杀行动——等待他的是一个更糟的消息他必须尽快回到遥远的伊丽莎白镇去处理父亲后事。 在飞机上，他结识了空姐克莱尔（克尔斯滕·邓斯特 Kirsten Dunst饰），她美丽大方，善解人意，总是在德鲁最寂寞低落的时候给予窝心的慰藉。在爱情和亲情的温泽下，德鲁渐渐重拾起来对生活的信心。','It\'s a heck of a place to find yourself',57000000,52034889,22.894898,6.1,327,123,'2005-10-06','en','/mOdlzAQxhMgiaazRzif1YtJzg9s.jpg',3.1428438774006398,3,'2026-09-10',2,NULL,NULL),(9623,'危险机密','The Juror','单亲妈妈安妮莱德（黛米·摩尔 饰）被选中为陪审团成员，审理一起黑手党老大的案子。于此同时，在黑手党内外号”老师”的迷人男子（亚历克·鲍德温 饰）也对她展开追求。他的真正目的是要左右她的判决，以及靠她来影响其他陪审团成员。但是当安妮试图想在审判期间维持公正的态度时，她儿子的性命也因此受到了威胁……','There is no defense.',44000000,0,3.937352,5.5,89,118,'1996-02-02','en','/f7eREf5dI0C00bWZmE5xbbgkO1x.jpg',2.799887509767754,3,'2026-09-10',2,NULL,NULL),(9624,'绝地战将','On Deadly Ground','美丽的阿拉斯加，艾吉斯石油公司的钻机不但破坏了爱斯基摩人的宁静生活。而且也破坏了当地的环境，受到当地爱斯基摩人的抗争。但政府却由于被石油公司收买而一味偏袒勘探队的所作所为， 石油公司的行径也招致了勘探队中一些正直人们的不满，灭火专家塔夫脱也是其中之一。塔夫脱的内心受到极大的震撼。 公司总裁詹宁斯等人正为了获取更多的暴利而扩大采油能力。塔夫脱与爱斯基摩少女玛苏一起与石油公司展开了一展正义的斗争……','His Battle To Save The Alaskan Wilderness And Protect Its People Can Only Be Won...',50000000,49000000,9.114168,4.5,104,102,'1994-02-18','en','/ckzGSzjTV6h5LiDRjeRq5i3qbPk.jpg',2.8047540551259824,3,'2026-09-10',2,NULL,NULL),(9625,'魔鬼尖兵','The Glimmer Man','一个神出鬼末的连续杀手，以他持有的杀人模式震惊整个洛杉矶，他的前身是替国家执行非官主任务。他布下天罗地网，准备追查凶手的行动，但是一切的箭头居然指向杰克，并且显示他本人似乎就是那个凶手……  杰克?考尔曾被国家秘密派到第三世界国家，执行非官方任务。行动迅速、准确是他的天性，因此长官代称他为“闪光人”。不过那是好几年前的事了，现在他的身份是纽约警探。当洛杉矶市发生连续杀人事件，凶手神出鬼没、手法特异的犯案作风令洛杉矶民众人心徨徨、警察们束手无策时，“闪光人”考尔成了可能是唯一能解开神秘杀手之谜的关键人物。这位信仰东方哲学、只穿特定衣服、严肃又我行我素的警探，奉命协助洛杉矶警察破案。和他搭档的是经验丰富的当地警探金?坎贝尔。刚开始两人在观念及行为上有很大的差异，也因此闹了不少笑话。但为了尽快破案，只有忍受对方的不合理。二人连手布下天罗地网，准备追查凶手的行踪，但狡猾的歹徒躲过了两人设下的陷阱。就在此时，考尔接到报案，他发现他的前妻与她的现任丈夫将是最新的受害者，而这一切罪证都指向考尔——他似乎就是那个十恶不赦的凶手……','Two good cops. One bad situation.',45000000,0,6.250282,4.7,100,92,'1996-10-04','en','/667nKLCmGqqDD2cJd3j5XFQXSni.jpg',2.7990650879767482,3,'2026-09-10',2,NULL,NULL),(9626,'女王神剑','Red Sonja','女主角索妮娅生于一个小康之家，过着平静的生活；有一天，她的父母被一名恶毒的皇族杀害。索妮娅伤心欲绝之际，誓要为父母报仇。她原来拥有一种神秘力量，可是她不可爱上男人，除非那个男人强过她，否则，她的神力就会消失。幸好在追寻那个毒后途中，遇上一名心仪的男人……','A woman and a warrior that became a legend.',17900000,6948633,12.752463,5,206,89,'1985-04-09','en','/rflWeK6kldrG1Zh5Zt7yRbCDGVF.jpg',2.947312643241624,3,'2026-09-10',2,NULL,NULL),(9631,'王牌对王牌','The Negotiator','丹尼是一名出色的谈判专家，屡立战功。当他的人生顺风顺水时，刹那间的转折让他措手不及。他的搭档因涉嫌私吞公款而被拘，却在警局惨遭灭口，第一时间赶到现场的丹尼自然最大嫌疑人。当他确信是警局内有人要找他做替死鬼，百口莫辩之际，他铤而走险绑架了局长等一干重要人物，想通过与警方的对话为自己洗刷罪名。丹尼要求另一分局派出谈判专家来和自己对话，因为他清楚要谋害自己的人就在自己的局里。于是邻局的谈判专家史宾恩奉命前来和丹尼谈判，史宾恩相信了丹尼，开始为他搜集证据。','He frees hostages for a living. Now he\'s taking hostages to survive.',50000000,44547681,28.725621,6.8,582,140,'1998-07-29','en','/6upx38XdnXX8NIgHH9xEyPeSfvn.jpg',3.373818835837108,3,'2026-09-10',2,NULL,NULL),(9637,'史酷比','Scooby-Doo','本片改编自60年代美国热门卡通系列剧，故事的主角是一只会说话的大丹狗：史酷比。话说在美国有一个度假圣地“恐怖岛”，这里有全世界最最恐怖的游乐设施，让那些寻求刺激的旅客流连忘返。  　　但是今年的恐怖岛成了名符其实的“恐怖岛”，有人在岛上遇到真实的恐怖现象！从此“恐怖岛”门厅零落，这里的老板也因此蒙受巨大的经济损失，为了证明岛上安全无虞，没有所谓的恐怖现象，于是请来了远近驰名，以费德（小弗莱迪·普林兹饰）为首的四人打击犯罪小组到岛上展开侦查，这组人马当中当然还包括对灵异现象反应敏锐的史酷比，战斗开始了……','Get a Clue',84000000,275650703,31.435539,5.4,820,88,'2002-06-14','en','/mTAiBJGg8mqEfnYHHbi37ZoRSZm.jpg',3.249546497209901,3,'2026-09-10',2,NULL,NULL),(9641,'儿女一箩筐2','Cheaper by the Dozen 2','\"拥有着12个孩子的欢乐家庭——贝克家族如今也难逃岁月出的难题。随着长女诺拉（派珀·佩拉博 Piper Perabo 饰）出嫁怀孕，孩子洛林又远赴纽约深造，身为家长的汤姆（史蒂夫·马丁 Steve Martin 饰）深感家庭聚会的时间将越来越少，今年假期也许是最后一个全员出游的机会，于是他和妻子凯特（邦尼·亨特 Bonnie Hunt 饰）精心策划了一个温内特湖畔的温馨旅行计划。然而汤姆万万没想到的是，他学生时代的宿敌吉米（尤金·列维 Eugene Levy 饰）竟然也带着自己的8个孩子来到了温内特湖消遣夏日。两个处处较劲的老爸，两个闹哄哄的家庭碰到一起，湖光山色瞬间变成火药味十足的战场，两家老小24口人全部出动，为了各自的“荣誉”，全力投入到这场鸡犬不宁、笑料百出的家庭大作战中……\r 本片为2003年家庭喜剧《儿女一箩筐》续集。\"','Same Big Family... Even Bigger Adventure.',60000000,129181830,18.831023,5.7,526,94,'2005-12-21','en','/wD68dEtcKuboxd8bhbqiTTxn6cX.jpg',3.1857977895900773,3,'2026-09-10',2,NULL,NULL),(9644,'重载武器','National Lampoon\'s Loaded Weapon 1','一对黑白警探搭档，出生入死在一起办案，从这个基点出发拍出了一系列影片，由于娱乐性和刺激性兼有，每一部上映后都创下不俗的票房成绩。\r 　　白人警察杰克是不按常规办事的拼命三郎型，与老成持重的黑人警察韦斯正好相得益彰。观众不难发现这部影片在拿许多著名影片中的情节和人物当笑料，让人想起《沉默的羔羊》、《大玩家》、《本能》中的某些场影，这当然不是抄袭，而恰恰是一种有意为之的善意调侃。','See it before they make the sequel!',0,0,12.963328,5.7,157,84,'1993-02-04','en','/moP0nyVWVisqSeH6nMewWyIPV6z.jpg',2.9407732594659306,3,'2026-09-10',2,NULL,NULL),(9645,'幽灵船','Ghost Ship','西恩·墨菲是一艘救援船的船长，莫瑞恩·爱普斯是船上救援小组的组长，他们带领的是救援行业里最出色的团队，他们的工作是登上一艘被遗弃的船，使它能够航行，并把船带回海岸，以此获得雇主的酬劳。这一次，雇佣他们的是发现那艘神秘大船的人，加拿大空军飞行员杰克·弗里曼。那艘船，正是四十年前失踪的安东尼亚号。根据海洋法，任何在公海发现的船只都归发现者所有，如果他有足够运气和技巧发现并把它拖回岸上。对救援队来说，这条豪华客轮是一笔很大的财产。就看他们有没有办法了。西恩带着他“北冰洋武士号”的船员，他的大副格里尔，技术师道奇，门德尔和桑托斯，和莫瑞恩一起，登上了这艘意大利客轮。船不再是当初的样子了。自然。除了岁月造成的痕迹外，怪异的事情也一桩接一桩地发生，比他们以前经历过的都要恐怖和致命。——这艘船并没有被遗弃。船员们的任务不再是获得财富，而是找到出当初这艘船上发生的真相，解开一切秘密，因为船上的神秘力量已经威胁到他们的生命。','Sea Evil',35000000,68349884,27.724913,5.3,531,91,'2002-10-25','en','/5jDGfVnPbYsPRxXfTx4MsquCv0E.jpg',3.157284029709344,3,'2026-09-10',2,NULL,NULL),(9647,'孤寒财主','Scrooged','根据英国文豪狄更斯着名的小说《圣诞颂歌》改编，加上了现代的电视台背景和热闹非凡的特技镜头，变成一部具有警世效果的贺节喜剧。比尔．默里在片中饰演个性凉薄的电视台大亨弗兰克，一切唯利是图，为了提高节目收视率，就是哧死观众也在所不惜。就在耶诞节前夕，已经死了七年的老板拖着腐朽的身躯回来警告弗兰克，并预告他将有三名不速之客来访，包括带他巡访旧时生活和未来际遇的计程司机，带领他分亨亲情与爱情的小仙女，在电视现场扮演鬼魂的吓人妖怪。在这三个鬼魂的引导下，弗兰克终于明白了圣诞节的真谛。导演理查德．唐纳的手法虽有点夸张，但精彩的特技和男主角的喜感演出仍然吸引观众。','The spirits will move you in odd and hysterical ways.',0,60328000,21.620317,6.7,390,101,'1988-11-22','en','/uO0znfB2ZzTXA1IS7jkrjNbpkYK.jpg',3.2407034290643693,3,'2026-09-10',2,NULL,NULL),(9654,'偷天换日','The Italian Job','以查理(马克·沃尔伯格饰)为首的一伙职业盗贼，其中包括内线史蒂夫(爱德华·诺顿饰)、电脑黑客里尔(塞斯·格林饰)、驾车能手罗勃、爆破高手“一只耳”和专攻保险箱的约翰，在意大利威尼斯完成了一票大买卖，抢得了大量黄金。就在几个人满心欢喜准备分钱的时候，史蒂夫竟一个人带着金条溜之大吉。为了抢回属于自己的那份，剩下的人只好重新出发，与新加入的漂亮女贼斯黛拉(查理兹·塞隆饰)一起来到洛杉矶。为了抢在史蒂夫把金条脱手之前找到他，一伙人成功的控制了洛杉矶市的交通系统，造成了有史以来最大的城市交通阻塞。而他们驾驶着迷你型宝马车，在装甲车与直升机的追逐下，在大街小巷甚至是地铁隧道里，完成了一场惊天大逃亡。','Get in. Get out. Get even.',60000000,176070171,62.766854,6.6,1919,110,'2003-05-30','en','/eSkjK4kctyrWpFhxl35GPvSs6tI.jpg',3.724791240981161,3,'2026-09-10',2,NULL,NULL),(9655,'足球尤物','She\'s the Man','电影讲述高中生薇欧拉有个特殊身份──女子足球校队主力健将。为了继续踢足球，她趁着双胞胎哥哥塞巴斯蒂安出国，女扮男装冒充塞巴斯蒂安，前往他的新寄宿学校，加入足球校队。在男生宿舍居住的薇欧拉，渐渐地爱上室友杜克，但杜克暗恋着头号校花奥莉维亚，而奥莉维亚却意外喜欢上了薇欧拉，求爱事件越闹越复杂。','If you wanna chase your dream, sometimes you gotta break the rules.',20000000,33889159,10.81439,6.4,671,105,'2006-03-17','en','/vE01i8i4KnMWWZ9Z1hjGaY3OWuS.jpg',3.3135089077526647,3,'2026-09-10',2,NULL,NULL),(9656,'黑色圣诞节','Black Christmas','\"20世纪70年代，体弱多病的小男孩比利（Cainan Wiebe 饰）降临人间，他不曾感受到父母的温暖，反而自幼备受虐待。他的母亲（Karin Konoval 饰）甚至串通情人杀害了比利的父亲，而这一切都被这个只有5岁大的小男孩看在眼里。可怜的比利从此被母亲囚禁阁楼，度过了黑暗而漫长的童年时代。某个圣诞夜，长成青年的比利（Robert Mann 饰）逃出樊笼，并将母亲和继父残忍杀害，而同母异父的妹妹爱格尼丝（Dean Friss 饰）也被弄瞎一只眼睛。\r 15年后，比利家早已废弃的房子被改造成某学校的校外宿舍，八个青春靓丽的女生以及舍监芭芭拉（Andrea Martin 饰）住在这里。但她们很快发现，传说中的凶残比利似乎就在自己身边……\"','This holiday season, the slay ride begins.',9000000,21510851,4.134327,4.8,119,84,'2006-12-25','en','/4R7nSOFRuurn5tK9YcS1JCoBfeT.jpg',2.8275199241684446,3,'2026-09-10',2,NULL,NULL),(9659,'疯狂的麦克斯','Mad Max','在不远的未来，公路骑士们在道路上肆虐，所过之处留下疯狂破坏的痕迹。为了追逐盗取了警用车的“黑暗骑士”，警方付出了重大代价，幸有比骑士更加疯狂的麦克斯（梅尔·吉布森 Mel Gibson 饰）出场，迫使黑暗骑士车祸身亡。黑暗骑士的同伙们发誓报仇，他们降临小镇，要接回黑暗骑士的尸身，并且肆意凌虐弱者，麦克斯和搭档古斯（Steve Bisley 饰）抓获凶手后，却因为无人敢指认，只得容忍他们继续逍遥法外。古斯被公路骑士们抓到，身负重伤，而麦克斯的妻子杰西（琼妮·萨缪尔 Joanne Samuel 饰）也被他们恐吓骚扰，有“疯狂”之称的麦克斯不再隐忍，向骑士们展开回击。','The Maximum Force Of The Future',400000,100000000,33.142185,6.6,1213,93,'1979-04-12','en','/dKrXmgXOh8kwcoM3innR5Epvmaa.jpg',3.5429513374297095,3,'2026-09-10',2,NULL,NULL),(9662,'疯狂约会美丽都','Les Triplettes de Belleville','一个男孩、他的祖母、他的狗，以及他赢得环法自行车赛的梦想。当男孩在比赛途中被两名神秘男子绑架，这场搜寻将他带往巨大的美丽都之城，以及著名的“美丽都三重唱”——三位来自1930年代的怪诞音乐厅女星。',NULL,8000000,1477676,13.944645,7.3,231,80,'2003-06-11','fr','/6T7PuALPdTI8ZVYF1p4LFc4ruqZ.jpg',3.134144444265796,3,'2026-09-10',2,NULL,NULL),(9664,'空战英豪','Flyboys','1914年，一战在欧洲打响。到了1917年，法国、英国、意大利和许多国家都站在了统一战线联合对抗德国，尽管成千上万的年轻人在海外死去，但处于别人的自由与己无关的歪理，美国首先还是选择了隔山观虎斗。 　　然而，不少热血沸腾的美国年轻人却有不同的看法：被逼放弃家族牧场的布雷恩（詹姆斯·弗兰科）看见了新闻里播放的飞行员，威廉为了家族荣耀发誓让父亲骄傲，富家子弟布里格斯决定开始自己的穿越大西洋旅行，因为种族问题被逐出美国的黑人拳击手尤金发誓报效收留他的法国...。虽然动机各不相同，但这38位年轻人却为了共同的飞行梦想加入了海外作战空军部队。 　　可战争远远超出这些单纯青年的想象，死亡无处不在，危险不可预料，面对战地空军平均只有三到六星期的寿命，他们无所适从。然而，在法国将军赛诺特（让·雷诺）和美国老兵瑞德·卡西迪（马丁·亨德森）的领导下，这些年轻人真正学会了为荣誉和和平而战。面对强大得令人生畏的德国侵略者，亲身试验机械技术尚不完整的新飞机，他们最终成为青史留名的“拉斐特飞行小队”！','Inspired by a true story',60000000,17800000,13.155999,6.3,271,140,'2006-09-22','en','/xezeqrrno6ytLyLrbTXRGUk4rdu.jpg',3.0963613846420257,3,'2026-09-10',2,NULL,NULL),(9665,'光荣战役','Glory','美国南北战争，白人军官罗伯特·古尔德萧（马修·布罗德里克 Matthew Broderick饰）在战斗中负伤，被一位名叫约翰·罗林斯（摩根·弗里曼 Morgan Freeman饰）的掘墓人发现送进了野战医院。在波士顿养病期间，罗伯特自愿接下了全部由黑人组成的“麻州第五十四兵团”指挥官的职务。然而面对种族歧视的严重偏见和白人同僚的冷嘲热讽，以及新兵瑞普（丹泽尔·华盛顿 Denzel Washington饰）的种种质疑，他毅然将一群从南方黑奴制度中脱逃至北方的乌合之众训练成一支纪律严明的部队。由他率领的黑人兵团“麻州第五十四兵团”，在南方的查尔斯坦战役中写下光辉的一页。然而罗伯特自己却在上战场攻坚时壮烈牺牲。','Their innocence. Their heritage. Their lives.',18000000,26828365,16.102271,7.4,383,122,'1989-12-15','en','/nFEl7tmNKwcf5jgvurF7m7kLO10.jpg',3.2958197226134636,3,'2026-09-10',2,NULL,NULL),(9667,'灵幻夹克','The Jacket','杰克·斯塔克斯是一名美国海军陆战队士兵，在1991年的海湾战争中头部不幸中弹，虽然经过抢救保住了性命，却因此留下了后遗症--失忆症。尽管伤复痊愈，然而失忆症的阴影却依旧挥之不去。退役后的斯塔克斯无处可去，无亲无故的他只好回到家乡佛蒙特州。　　9个月后，斯塔克斯搭车行驶在白雪覆盖的佛蒙特州公路上。途中，他看到了一辆抛锚的小货车被困在路边，司机是名叫吉恩的女人，喝得酩酊大醉、神智不清，身边带着8岁大的女儿杰姬。斯塔克斯帮助母女俩重新发动了汽车，并将自己当兵时用来辨别身份的狗牌送给了小女孩。随后又搭上了一辆开往加拿大边境的旅行车。然而不久，他们的车被警察拦截，斯塔克斯又莫名其妙的发生了晕厥。当他醒来时，发现自己竟坐在小镇的法庭上，他被警察当成了在逃的杀人嫌疑犯。由于斯塔克斯被认为精神失常，罪名不能成立，但他被带到了名叫Alpine Grove的地方，这是一家研究精神病人犯罪的机构。贝克医生要他接受一系列的临床治疗，包括神智复苏药物治疗和抑郁恐怖症的物理强制治疗。服药之后，斯塔克斯被穿上精神病人的束缚衣，囚禁在地下太平间的停尸柜里。　　在停尸柜的抽屉里，被黑暗淹没的斯塔克斯的脑海里开始出现过去的记忆碎片，从战争到开车的年轻人射杀警官，他将过去记忆的碎片拼凑在一起，试图感知现在的处境。过去是指引未来的钥匙，斯塔克斯的记忆突然跨越到2007年的佛蒙特的一家餐馆，他认识了一个名叫杰姬的女服务生，她正是斯塔克斯曾在公路上遇见的小女孩。当时正是圣诞节前夕，好心的杰姬希望为可怜的斯塔克斯找到一个安身之处，然而无家可归者的收容站都已人满为患，后来斯塔克斯被杰姬收留在家中，两人间甚至萌生了感情。除此之外，他居然发现自己会在1993年的元旦死去。黑暗中时间一分一秒的过去，斯塔克斯开始意识到抽屉是恢复记忆的秘密，而他的未来和安宁都掌握在那个曾经相遇并后来相恋的杰姬手中……','Terror has a new name.',29000000,21126225,24.240361,6.8,455,103,'2005-03-04','en','/y7SyRWl8B6BSRJzHxGRQ72JkLRT.jpg',3.2979201842207044,3,'2026-09-10',2,NULL,NULL),(9671,'Crocodile Dundee','Crocodile Dundee','When a New York reporter plucks crocodile hunter Dundee from the Australian Outback for a visit to the Big Apple, it\'s a clash of cultures and a recipe for good-natured comedy as naïve Dundee negotiates the concrete jungle. Dundee proves that his instincts are quite useful in the city and adeptly handles everything from wily muggers to high-society snoots without breaking a sweat.','There\'s a little of him in all of us.',5000000,328203506,16.072466,6.3,503,97,'1986-09-26','en','/pduPduL1ub5kok3lPYT15ryC9L6.jpg',3.244673429720668,3,'2026-09-10',2,NULL,NULL),(9672,'声名狼藉','Infamous','电影《声名狼藉》根据乔治·普林顿的原著改编，讲述了杜鲁门·卡波特在哈珀·李的帮助下，采访凶手佩里·史密斯，最终写出了举世名作的故事。听起来，本片的剧情与去年奥斯卡获奖电影《卡波特》极为相似，不过不同的是，《声名狼藉》将侧重点放在了卡波特与青梅竹马的友人哈珀·李的关系上。同时本片也云集了大批巨星，包括新任007丹尼尔·克雷格、好莱坞甜姐儿桑德拉·布洛克以及奥斯卡得主格温妮斯·帕尔特洛等等。','There\'s more to the story than you know',13000000,1151330,3.680896,6.4,60,110,'2006-11-16','en','/cIQUn20lUQpi70W0Z7ixezQJ7gj.jpg',2.741416403127649,3,'2026-09-10',2,NULL,NULL),(9675,'杯酒人生','Sideways','两位老友踏上品酒之旅，却晕头转向地偏离正轨，展开一场对爱情与友谊的疯狂变迁、孤独与梦想该死的执着、以及黑皮诺与赤霞珠之间永恒战争的戏谑喜剧探索。[福克斯探照灯影业]','In search of wine. In search of women. In search of themselves.',16000000,109502303,23.425431,6.9,478,126,'2004-10-22','en','/rcPQXR1gctQ5J1kFxYKOZ5qlu2Q.jpg',3.32105026039449,3,'2026-09-10',2,NULL,NULL),(9676,'黑色大丽花','The Black Dahlia','布奇（乔什•哈奈特 Josh Hartnett 饰）和李（艾伦•艾克哈特 Aaron Eckhart 饰）都是拳击界的佼佼者，李被称为“火先生”、而布奇则被称为“冰先生”。李在警局执行组，而布奇则比较落魄。在警局举行的一场拳赛上，布奇故意输给了李，以此跻身了警局，成为李的搭档，两人更成了无话不谈的好友。两人奉命调查一个叫纳什的家伙犯下的连环凶杀案，在一次埋伏行动中，李为了救布奇射杀了一名监视的疑犯，但却没抓到纳什。随后两人在现场附近发现了被称为“黑色大丽花”的肖特的尸体，肖特死因恐怖。李很快就放弃了调查纳什一案，而集中精力一人追查肖特的案件，而当年被李抓获的抢劫银行犯鲍比提早出狱也让李感到焦头烂额。布奇为了帮助搭档，自己也开始着手调查，然而，随着调查的深入，真相逐渐浮出水面之际，却发现了李身后不为人知的秘密。','Inspired by the most notorious unsolved murder in California history.',50000000,49111202,15.213484,5.7,287,121,'2006-09-15','en','/mL5yWmJ8wSGOmB9ZODn8VKjzVDU.jpg',3.0632435183996534,3,'2026-09-10',2,NULL,NULL),(9678,'魔鬼接班人','Little Nicky','亚当·桑德勒饰演的力奇是一个害羞和笨拙的人，同时他却是魔鬼撒旦的儿子。当老撒旦垂死时，他交托力奇接管他的魔鬼事业。但力奇本性善良，决定将地狱变得『亲切』化，但唯一的障碍就是他那两个已落凡间，到处作恶的兄弟，于是他首先要做的就是去纽约把他兄弟的邪恶力量征服。','He\'s Never Been To Earth. He\'s Never Even Slept Over Some Other Dude\'s House.',85000000,0,18.335992,5.2,438,90,'2000-11-10','en','/AudA8gnTWSBWXBHSBHnr3HHUXXM.jpg',3.0940911077679383,3,'2026-09-10',2,NULL,NULL),(9679,'极速60秒','Gone in Sixty Seconds','孟菲斯（尼古拉斯•凯奇 Nicolas Cage 饰）是这个世界上最高明的窃车贼，人们形容他为“gone in 60 seconds”，即只要他盯上的车停在这里，他60秒内便能连人带车一起消失得无影无踪。孟菲斯终究厌倦了窃车贼的虽然惊险刺激但重压在身的生活，宣布金盘洗手了。但他的弟弟却想步其后尘，不料很快就卷入了一次黑帮危险的交易中。孟菲斯为了救出兄弟，只好重操旧业，答应黑帮一晚内偷来60辆车。不料，警察正在密切监视着孟菲斯。当他偷得最后一辆“悍马”卡车时，警车、警察直升机尾随而至，展开了一场马路追逐……','Ice Cold, Hot Wired.',90000000,237202299,52.995628,6.1,1485,118,'2000-06-09','en','/hdkIJWknBpsDtZqz3jz9pom2Ua5.jpg',3.5383066143675044,3,'2026-09-10',2,NULL,NULL),(9682,'惹鬼回路','Pulse','玛蒂（克里斯汀·贝尔 Kristen Bell 饰）和男友乔什的关系最近有些疏远，她在多次电话联系无效后拜访乔什，但看到的却是男友自杀后的尸体……玛蒂陷入了自责，男友的幻象萦绕在她的眼前。不久，在玛蒂和朋友们使用网络聊天软件时，忽然传来了乔什的即时讯息，玛蒂怀疑有人在使用男友的电脑，委托朋友查看，这导致朋友在乔什家遭遇了恐怖的经历……另一方面玛蒂追索电脑下落，结识了购买电脑的青年德克斯特，后者在乔什电脑中发现了一系列诡异的视频，乔什在视频记录中自述其运用黑客技术释放出了恐怖的物事，而他自己已无法控制。玛蒂在周围人的自杀、失常中愈发体会到一场借助网络传播的恐怖阴云正迅速笼罩整个城市……','You are now infected.',38000000,29907685,9.662715,5,150,90,'2006-08-11','en','/9ePdNzKVvGHsMMphfS3HeoMvuEX.jpg',2.8883460144060837,3,'2026-09-10',2,NULL,NULL),(9683,'泡泡男孩','Bubble Boy','从呱呱坠地的那一刻起，吉米（杰克·吉伦哈尔 Jake Gyllenhaal 饰）就注定是一个不同寻常的男孩，他换上了极为罕见的重症联合免疫缺陷病，这也就意味着，他体内没有任何的免疫系统，任何对于正常人来说不值一提的细菌，都有可能在吉米的体内大量繁殖威胁到他的性命。\r 治疗这种疾病的唯一方法就是骨髓移植，但医生一直都没有寻找到能够和吉米相匹配的骨髓。于是，吉米只能终日生活在一个无菌的圆形气球里，他被人们称为“跑跑男孩”。吉米从小就生活在束缚和担心受怕之中，从未体会过生活的潇洒和肆意，随着时间的推移，吉米的性格越发内向和古怪。此时，一个美丽的女孩出现在了吉米的生命里，她的存在让吉米开始渴望走出泡泡，拥抱生活。','Life is an adventure. Don\'t blow it.',0,0,10.131123,5.1,163,84,'2001-08-24','en','/tFwvUSc8g0HHvDOBQ2rvC9LWVSj.jpg',2.90879851234329,3,'2026-09-10',2,NULL,NULL),(9685,'伊比的堕落','Igby Goes Down','伊比（基南·卡尔金 Kieran Culkin 饰）是一个正处在叛逆期的十七岁男孩，常年生活在压抑的家庭环境之中。伊比的父亲杰森（比尔·普尔曼 Bill Pullman 饰）有着严重的精神分裂症，母亲咪咪（苏珊·萨兰登 Susan Sarandon 饰）自私冷漠依靠服用镇定剂保持冷静，哥哥是一个完完全全的政治狂人，已经丧失了人性。  再也无法忍受这样的家庭氛围的伊比决定离家出走，但是他的反抗很快就遭到了母亲的压制，母亲先后将伊比送往两所军事化管理的学校中，企图让儿子重回正轨，但都以失败告终。最后伊比来到了教父贝恩（杰夫·高布伦 Jeff Goldblum 饰）家中。贝恩是一名成功的商人，在他这里，伊比第一次找到了家的感觉。','Insanity is relative.',9000000,4777465,2.062087,6.5,95,97,'2002-09-13','en','/f53JBgzYESamcYT3LkUeeoSXPgi.jpg',2.843036358725072,3,'2026-09-10',2,NULL,NULL),(9686,'大都会传奇','New York Stories','三位大导演的三个小故事：楼上：《俄狄浦斯的烦恼》，讲述一个被母亲困扰的男人；楼中：《没有伊佐的生活》，讲述了小女孩伊佐与印度小王子和自己的父母的感情；楼下：《生命之课》，一个画家暗恋自己的女助手，失恋与幸福同样刺激她的灵感。','One city, three stories tall.',15000000,0,6.684096,6.2,64,124,'1989-03-10','en','/mViGEH5dfsAnUgJmce1RJkFycAi.jpg',2.7576242987165105,3,'2026-09-10',2,NULL,NULL),(9689,'好莱坞式结局','Hollywood Ending','这时瓦克斯曼（伍迪•艾伦 饰）的事业并不如意，生活有点潦倒。他常常想起当年自己的风采，那段峥嵘岁月里他曾得过两届的奥斯卡奖。他拼命在无奈的生活中挣扎，幸好有前妻艾丽为他推荐，有机会执导一部新电影。出资拍片的人正是艾丽的男友，但瓦克斯曼对这位大老板的身份感到十分不满。但为了能重新振作，再次冲击电影界，瓦克斯曼还是作好出击的准备。可是当一切都准备妥当的时候，他无端失明了，他又如何能导演好一部电影呢，疾病却不能阻止瓦克斯曼前进的步伐，他要隐瞒病情，把电影拍完。到头来，老板兼情敌又会否知道他的秘密呢？','It\'s going to be a shot in the dark!',16000000,0,8.711782,6.4,113,112,'2002-05-03','en','/aDRbdtNoTRoYnIpH3g1icGeHGBh.jpg',2.893712840984773,3,'2026-09-10',2,NULL,NULL),(9691,'刺客战场','Assassins','身为一名杀手，罗伯特（西尔维斯特·史泰龙 Sylvester Stallone 饰）有着自己不可动摇的原则，那就是除了任务目标外，决不滥杀无辜。尽管与罗伯特是同行，但米高（安东尼奥·班德拉斯 Antonio Banderas 饰）的生死观却和罗伯特大相径庭，他不仅为了达成目的不择手段，更是将业内“德高望重”的罗伯特视作眼中钉肉中刺，欲除之而后快。  　　充满了杀戮的生活令罗伯特感到厌倦，他决心再干最后一票，从此金盆洗手。很快，技术高超的罗伯特便捉住了目标任务——一名叫伊莉（朱丽安·摩尔 Julianne Moore 饰）的女贼，不幸的是，此时的伊莉和她手中价值两百万美元的磁盘亦成为了米高的猎物。随着时间的推移，罗伯特渐渐的爱上了伊莉，与此同时，残暴的米高也离他们越来越近。 ©豆瓣','In the shadows of life, In the business of death, One man found a reason to live...',50000000,30303072,23.073933,6,387,132,'1995-10-06','en','/wPmZYnaQpxwoHmwNwVhZ2IY0UbF.jpg',3.1691828097282024,3,'2026-09-10',2,NULL,NULL),(9693,'人类之子','Children of Men','本片勾勒出距今仅一代之遥的未来图景：因人类丧失生育能力，世界紧随其后陷入混乱。全球最年轻的公民刚于18岁离世，人类正面临自身灭绝的危机。故事背景设定在暴力肆虐、民族主义教派割裂的伦敦，影片跟随理想幻灭的官僚西奥（克里夫·欧文 饰），看他如何意外成为拯救地球存亡的关键人物。[环球影业]','The future\'s a thing of the past.',76000000,69959751,35.387874,7.4,2071,109,'2006-09-22','en','/k9IAS4TehZFcKi4HVByxZNPfqex.jpg',3.8585313549911255,3,'2026-09-10',2,NULL,NULL),(9697,'水中女妖','Lady in the Water','“水妖”的传说在西方家喻户晓，据说那是一群住在海、河或森林中的美丽少女。一栋公寓的门卫克里夫兰（保罗·吉亚玛提 Paul Giamatti 饰）在夜里巡逻时，发现在游泳池里有一位少女，他救她出来，得知她名叫斯托丽（布莱丝·达拉斯·霍华德 Bryce Dallas Howard 饰），原来就是传说中的水妖，正在被怪兽追逐。为了帮助斯托丽回到原来的世界，克里夫兰找来许多大厦住户帮助，也慢慢爱上了这个与众不同的女孩，可惜时间紧迫，斯托丽在这个世界耽搁越久，越会惹来怪兽袭击，甚至开始威胁这个世界人们的生命……','Time is running out for a happy ending.',75000000,42285169,20.219385,5.3,409,110,'2006-07-21','en','/ixobe7UQugZMyovOxpveXMVSx83.jpg',3.098699500838355,3,'2026-09-10',2,NULL,NULL),(9700,'迷失城市','The Lost City','1958年的哈瓦纳对许多人来说是个天堂，然而当地居民却对极权统治者感到不满，当\"切格瓦拉\"等人所率领的革命声浪延烧到了这里，一间当地夜总会的老板菲哥即将面临家破人亡妻离子散的危机，这场革命改变了一切，传统典雅文化也付之ㄧ炬，人群潮来潮往，只剩下他最爱的古巴音乐活在他的心底。',NULL,9600000,4386236,3.588529,6,24,144,'2005-09-03','en','/v19DsrJb0TJxTCdgaUzzuvOjfeD.jpg',2.5398717515099967,3,'2026-09-10',2,NULL,NULL),(9701,'决不让步','North Country','乔西（查理兹·塞隆 Charlize Theron 饰）与丈夫分居后，带着两个孩子回到明尼苏达老家，为了生计，决定不顾父亲反对去当地矿上工作。入职后乔西才明白为什么家里人对她的决定如此反对——矿上工作的女人每日要承受男职工们大量的性侮辱、性骚扰，就算忍气吞声，也要被男矿 工的妻子们当成婊子，甚至在公共场合受到辱骂。不堪忍受这一切都乔西决定出头把矿业公司告上法庭。这个念头让乔西受到前所未有压力，在公司里得到的羞辱变本加厉，还连累其他女员工，令她们都和她反目；在家里，从外面承受人言的孩子们也开始怀疑母亲的清白。乔西扛住这一切，只为让男人们知道不尊重女性的应有下场……  　　本片根据1988年发生的真实事件改编，是美国历史上第一桩起诉成功的性骚扰官司。 ©豆瓣','All She Wanted Was To Make A Living. Instead She Made History.',35000000,25224242,12.779201,6.8,125,126,'2005-02-12','en','/dKoVaIwToKIdT5VExnH8IHwGp5a.jpg',2.9433620911694343,3,'2026-09-10',2,NULL,NULL),(9702,'黑帮悍将','Bound by Honor','影片以诗人吉米·圣地亚哥·巴卡的真实生活经历为基础，重点讲述了帕科和克鲁兹的同父异母兄弟，以及他们的两个种族表兄米科。影片于1972年开拍，因为这三人是洛杉矶东部一个叫“瓦托斯机车”的团伙的成员，故事的重点是暴力犯罪和毒品的影响如何改变他们的生活。','An epic story of three brothers. Bound by blood. Divided by fate. Driven by destiny.',35000000,0,9.122828,7.7,115,180,'1993-02-05','en','/8t9ojZ7fyn5iTqKCVjGvJ6nMacN.jpg',2.9517810081837665,3,'2026-09-10',2,NULL,NULL),(9703,'最后的兵团','The Last Legion','罗马皇子罗慕路斯（托马斯·桑斯特 Thomas Sangster 饰）的父亲奥列斯特斯（伊恩·格雷 Iain Glen 饰）被叛军杀死，而罗慕路斯则被敌人软禁在卡普里岛之上。临死前，奥列斯特斯将后事托付给将军奥勒留（科林·费斯 Colin Firth 饰），叮嘱他一定要救出儿子，让罗马帝国的王位回归本宗。  对皇帝忠心耿耿的奥勒留联手埃塞俄比亚人巴蒂亚图斯（侬索·阿诺斯 Nonso Anozie 饰）和安布罗斯纽斯（本·金斯利 Ben Kingsley 饰），组成了一只远征的敢死队。之后，骁勇善战的女战士玛利亚（艾西瓦娅·雷 Aishwarya Rai 饰）亦加入其中，一行人向卡普里岛进发。在卡普里岛，罗慕路斯和他的导师也在为了生存而寻找着最后一丝希望。','The end of an empire...the beginning of a legend.',67000000,25303038,12.282911,5,207,102,'2007-04-19','en','/k2jaEoOsTEMqSskBJm3gfcuxNEc.jpg',2.9470084298724433,3,'2026-09-10',2,NULL,NULL),(9705,'剑鱼行动','Swordfish','间谍加布利尔（约翰•特拉沃塔 John Travolta）在多年特工生涯中，获知政府多年非法收敛了一笔公款。而加布利尔若想实现自己心中的梦想，钱是最关键的因素。正因如此，机智狡猾的加布利尔决定向这笔赃款下手。要想计划能顺利进行，加布利尔需要一名顶尖的电脑黑客。斯坦利（休•杰克曼 Hugh Jackman）正是地球上最顶级的黑客之一，多年前他就把FBI引以为豪的安全系统搞得天翻地覆，亦因此的引来牢狱之灾，妻子带着女儿远走他乡。出狱后一直被禁止使用电脑和其他电子产品。加布利尔派他的女搭档金吉尔（哈莉•贝瑞 Halle Berry）游说斯坦利出山，承诺成功后帮斯坦利取回女儿的抚养权并安排其远走高飞享受新生活。经不住诱惑，斯坦利再度出山。然而，事情并没有像预想中顺利……','Log On. Hack In. Go Anywhere. Get Everything.',102000000,147080413,36.788745,6.1,932,99,'2001-06-07','en','/fcZeDrfvsdAWk5EhcNv8lymbvez.jpg',3.4006328863095936,3,'2026-09-10',2,NULL,NULL),(9707,'打鬼王','Bubba Ho-tep','故事发生在位于德克萨斯州的一年老人院里。艾维斯（布鲁斯·坎贝尔 Bruce Campbell 饰）约翰（奥西·戴维斯 Ossie Davis 饰）是生活在那里的两位老人，实际上，艾维斯一直认为自己是著名的摇滚巨星猫王，而约翰则坚信自己是美国曾经的著名总统肯尼迪，并没有人来戳穿两个老人可悲的幻想。\r 　　一个来自古埃及的可怕魔鬼现身了，每天夜里，他会选中一些可怜人作为目标，吸走他们的灵魂。艾维斯和约翰决定发挥最后的光和热，绝不让魔鬼继续为非作歹。但很快的，两人便发现，魔鬼酝酿着一个更大的阴谋，它企图用人类的灵魂来复活一支古埃及军队，再率领着这支军队征服人界。','The King vs. The King of the Dead.',1000000,0,9.954848,6.7,191,92,'2002-06-09','en','/pKQBit5ZV7GEOTiMBSYC6xBn86K.jpg',3.0347788059832306,3,'2026-09-10',2,NULL,NULL),(9709,'夏日之恋','My Summer of Love','本片生动描绘了两位年轻女性在一个夏天里情感与肉体关系的温室效应，见证其热烈绽放。','The most dangerous thing to want is more.',0,0,3.939753,6,59,86,'2004-08-20','en','/47eozMel2wZgEASToUzScsPVpDs.jpg',2.7293259600981705,3,'2026-09-10',2,NULL,NULL),(9713,'圣人','Holy Man','一名天生具有领袖魅力的教徒平日云游四海乐善好施。有一天高速公路上巧遇汽车报抛锚的购物频的业务主管，这个主管为了拯救业绩频频下滑的购物频道，请求他发挥能言善道的天赋来吸引消费者。他不但挽救了购物频道主管原本快被炒鱿鱼的命运，也将电视购物变成一种宗教仪式...','The Comedy Where Nothing\'s Sacred!',60000000,0,9.265672,4.9,111,114,'1998-10-08','en','/sfJBsOdSbgLLarO6GIS0dWzFcCv.jpg',2.831452150746129,3,'2026-09-10',2,NULL,NULL),(9715,'真爱告白','Hope Floats','博蒂（珊卓布拉克饰）应邀上一个脱口秀节目，却被好友康妮在全国观众前爆料，自己与博蒂的丈夫发生外遇，深受打击的她带着女儿白尼丝，回到家乡投靠母亲箩梦娜。箩梦娜一心撮合女儿与仍暗恋她的高中同学贾斯汀（小亨利康尼克饰），他的鼓励与体贴，让她渐渐走出婚姻的打击，以及生活里不如意的伤痛，也化解与母亲多年来的心结。只是，对于感情害怕却步的她，是否能重拾自信迎向光明的未来呢？','When life fell apart, love fell into place.',0,0,7.922716,5.8,81,114,'1998-05-29','en','/6PRFM09xjGSWpXObW87CT5JELGJ.jpg',2.7994015156038965,3,'2026-09-10',2,NULL,NULL),(9716,'人人都说我爱你','Everyone Says I Love You','影片从朱娜（娜塔莎·雷昂 Natasha Lyonne 饰）的视角出发，展现了一个大家庭中的成员追求真爱的幸福光景。准姐夫霍尔顿（爱德华·诺顿 Edward Norton 饰）一直想找机会向生性浪漫的表姐斯凯勒（德鲁·巴里摩尔 Drew Barrymore 饰）求婚，而后者似乎迷 上了一个有前科的犯罪分子菲利（蒂姆·罗斯 Tim Roth 饰）。生父乔·柏林（伍迪·艾伦 Woody Allen 饰）走出上一段婚姻后一直都保持着单身的状态，直到有夫之妇赛迪尔（朱莉娅·罗伯茨 Julia Roberts 饰）出现，尽管朱娜极力撮合生父与赛迪尔的这段姻缘，但真正的结果只有乔自己能够掌控。妹妹劳拉（娜塔丽·波特曼 Natalie Portman 饰）暗恋着一个几乎不曾有过交流的男生。至于朱娜自己呢，曾经夸下海口绝不谈恋爱的她，居然闪电般地坠入了与一名威尼斯小伙的爱河之中。爱情就是这样可遇不可求，圣诞节就要来了，这群快乐又善良的人们能否在这个合家团圆的节日之中找到自己的真爱呢？',NULL,20000000,0,12.379781,6.5,147,101,'1996-12-06','en','/cFOZ4bNbWtnIIboc43M86yhwPBX.jpg',2.96670605959606,3,'2026-09-10',2,NULL,NULL),(9718,'塔拉德加之夜','Talladega Nights: The Ballad of Ricky Bobby','瑞奇·鲍比的赛车手父亲在他幼年时便宣告失踪，父亲临走前“不是第一，便是最后”的宣言一直陪伴着瑞奇和死党卡尔，成年后的瑞奇与卡尔双双进入丹尼特车队担任维修人员，一次在塔拉德加的比赛中，赛车手因畏惧故障选择退出，救场的瑞奇展示了强大的驾驶技术夺得第三名一举成名，自此和卡尔转为赛车手为车队出战，出色的成绩令瑞奇名利双收，抱得娇妻，好友卡尔则忠心耿耿担任绿叶为他扫清赛道，不可一世的瑞奇很快遭到了队友的挑战——来自法国的F1车手让·杰拉德，杰拉德彻底击败瑞奇令其一蹶不振，正当丧失了一切的瑞奇心灰意懒时，失踪多年的父亲突然出现，要帮助他夺回一切……','The story of a man who could only count to #1',72500000,162966177,12.599836,6.2,491,116,'2006-08-04','en','/96R81T1iUMzn7OGYdF8RjxMcwj9.jpg',3.219101885821856,3,'2026-09-10',2,NULL,NULL),(9725,'十三号星期五2','Friday the 13th Part 2','爱丽丝从为了给儿子复仇而大开杀戒的水晶湖营地厨师霍夫人手中死里逃生，但此后仍旧生活在惊恐中，霍夫人因为营地方面疏于照看导致儿子杰森溺死的怨念一直纠缠着爱丽丝。不久爱丽丝还是遇害了……五年之后，昔日的水晶湖地区已经被称为血腥之地并严禁外人进入，一群青年汇聚附近，在保罗和其助手金妮管理的辅导员训练中心中接受培训，年轻人们遭遇了依旧发出神秘警告的“疯子”劳夫，也听闻了杰森当年并未死去，而是以野人的方式成长至今并时时准备向人类复仇的传言，但他们大都把这些当做一个笑话，在轻松的培训生活中寻欢作乐。又是一个雨夜，传说中的杀人狂杰森出现，抹杀了一个个年轻的生命……','The body count continues...',1250000,21722776,16.517777,6,315,87,'1981-05-01','en','/92rGctBMTv4uaSlIBVnhz01kRWL.jpg',3.1111572541491013,3,'2026-09-10',2,NULL,NULL),(9726,'美好的一年','A Good Year','故事发生在风光惹人醉的法国普罗旺斯。伦敦证券师麦克斯（罗素·克劳 Russell Crowe 饰）作为遗产继承人的身份来到这里，虽然事业陷入低谷，但过世的叔叔留下的一大片葡萄园和一幢大房子，足够他卖出后获得一笔可观的收入。他在这里住下的期间，与当地一个咖啡店女子芳妮（玛丽昂·歌迪亚 Marion Cotillard 饰）相谈甚欢。原来，童年时候芳妮曾经是麦克斯前来叔叔家时的玩伴。芳妮为麦克斯打开了一扇大门，让他重拾渐忘的往事，不再满脑子都是数字和金钱的游戏。麦克斯让心灵在这片美丽的土地上尽情呼吸，以往为名为利的生活渐渐退去。这时，叔叔的私生女（艾比·考尼什 Abbie Cornish 饰）从加州前来造访，并且有着明确的目的：得到葡萄园的继承权，麦克斯刚刚平静下来的生活是否又开始了名争暗斗，抑或在普罗旺斯这个美好的地方，美好的日子天天上演','Everything matures... eventually.',35000000,42064105,16.782471,6.5,357,118,'2006-09-09','en','/bPzEtrKNUuREHmahFfcWOgH94pp.jpg',3.187282547052444,3,'2026-09-10',2,NULL,NULL),(9728,'十三号星期五3','Friday the 13th Part III','金妮用计从杰森的手中侥幸逃生，当地媒体广播了湖畔杀人狂的故事，而杰森的杀戮并没有就此终止……克里斯（Dana Kimmell 饰）、谢利（Rachel Howard 饰）等几个年轻的朋友一起驾车前往湖区度假，路遇神经质的老人手拿眼球向他们发出警告，一行人在克里斯男友瑞克（Paul Kratka 饰）居住的林中木屋安顿下来，克斯利来到这回忆之地，不禁想起被蒙面人袭击的惊险往事；活跃的谢利则不时用血腥的恶作剧开玩笑，而他的作为在这血腥营地中显得非常不合时宜，谢利去购物与当地摩托青年发生摩擦，三个赶到木屋意欲报复的摩托青年却被杀死在马房中……不久，带着面具的杰森现身，再次将杀戮带给无辜的年轻人们。','There\'s nowhere to hide. We dare you to try.',4000000,36690067,14.206525,5.7,254,95,'1982-08-13','en','/9kukTSlgFgXnQGdpcHvHcpTDiUc.jpg',3.037499967610927,3,'2026-09-10',2,NULL,NULL),(9729,'何处寻真相','Where the Truth Lies','八十年代，女记者卡伦（Alison Lohman 饰）正著手调查十五年前一桩酒店凶案的真相。当事人兰尼（Kevin Bacon 饰）与文斯（Colin Firth 饰）是著名搭档艺人，1972年，两人为慈善事业筹款而进行巡回演出期间，人们在他们的套房中发现了一具女尸……卡伦先后接近两人，得到了兰尼的自传手稿，兰尼声称死者莫琳因嗑药过量而溺毙，但卡伦将兰尼的生活习惯与自传两相佐证后发现疑点重重。当年兰尼与文斯事业顺利，于是黑社会邀请他们演出，某夜，校报记者莫琳同两人上床，无意中发现文斯的同性恋倾向并以此要挟。兰尼怀疑吸毒成瘾的文斯杀死莫琳，但两人在黑社会庇护下都逃避了制裁。卡伦对两人各自的陈述不置可否之际，真正的凶手却自己浮出了水面……  　　本片获2006年加拿大吉尼奖最佳剧本奖。',NULL,25000000,0,4.051221,5.9,66,107,'2005-10-07','en','/4gWQoxAmSeBaugpccnWdlg5Ov6f.jpg',2.750774634498689,3,'2026-09-10',2,NULL,NULL),(9730,'十三号星期五4：终结篇','Friday the 13th: The Final Chapter','上一集的大屠杀之后，杰森和十个年轻人的尸体被警方收敛，然而在医院中，杰森再次醒来，将夜班医护杀死，不知所踪……保罗、莎拉（Barbara Howard 饰）等六个年轻人租下了林中的木屋度假，木屋旁边住着汤米、丽丝姐弟以及他们的母亲一家。保罗等人到水晶湖中戏水，全然不知这里曾经上演的血腥故事。汤米和丽丝因汽车抛锚结识了自称是猎熊人的青年罗布（Erich Anderson 饰），罗布拜访汤米一家后在森林中安营，夜幕降临时，莎拉等人和新认识的姑娘在屋中狂欢，再次归来的杰森如常开始了夜色中的猎杀。汤米和丽丝发现母亲失踪，四处寻找时再次遇见罗布，原来罗布的妹妹被杰森所害，他特意在湖区驻扎，寻找向杰森复仇的机会……','Jason\'s Back, and this is the one you\'ve been screaming for.',2600000,32980880,14.013414,5.9,237,91,'1984-04-13','en','/1J7zudfR3VLPwAf9lK5YPfSu0n6.jpg',3.0384225527016935,3,'2026-09-10',2,NULL,NULL),(9731,'Friday the 13th: A New Beginning','Friday the 13th: A New Beginning','Homicidal maniac Jason returns from the grave to cause more bloody mayhem. Young Tommy may have escaped from Crystal Lake, but he’s still haunted by the gruesome events that happened there. When gory murders start happening at the secluded halfway house for troubled teens where he now lives, it seems like his nightmarish nemesis, Jason, is back for more sadistic slaughters. But as things spiral out of control and the body count rises, Tommy begins to wonder if he’s become the killer he fears most.','A New Beginning to the first step in terror.',2200000,21930418,12.639469,5.1,196,92,'1985-03-22','en','/ewnIs4aCuWnKQ13Eaj8f3ybrQc8.jpg',2.94547784506404,3,'2026-09-10',2,NULL,NULL),(9737,'绝地战警','Bad Boys','迈阿密警局的一对“黄金”搭档，顾家爱妻的好男人宾纳（马丁·劳伦斯 饰）和衣着光鲜风流倜傥的富家子弟劳瑞（威尔·史密斯 饰），奉命追查一桩价值上亿美元的毒品证物失窃案，如果不能及时完成任务，他俩就得卷铺盖走人。在两人疲于奔命之际，该案件唯一的性感女证人打电话到警局声称她愿意指认主谋，但条件是劳瑞必须出面保护她，否则一切免谈，此时劳瑞刚好不在警局，宾纳为套取线索，急中生智冒名顶替。其后，为了不失去女证人的信任，两人只得将对调身份一事进行到底，宾纳在枪林弹雨及汽车追逐中贴身保护女证人，劳瑞则来到他家中陪伴其妻。','Whatcha gonna do?',19000000,141407024,33.872182,6.5,1699,118,'1995-04-07','en','/swN5F8iI7WMzELMEEuNm3UchzCE.jpg',3.607720269559416,3,'2026-09-10',2,NULL,NULL),(9741,'Unbreakable','Unbreakable','An ordinary man makes an extraordinary discovery when a train accident leaves his fellow passengers dead – and him unscathed. The answer to this mystery could lie with the mysterious Elijah Price, a man who suffers from a disease that renders his bones as fragile as glass.','Some things are only revealed by accident.',75000000,248118121,42.006908,6.9,1946,106,'2000-11-13','en','/mLuehrGLiK5zFCyRmDDOH6gbfPf.jpg',3.7462968013018143,3,'2026-09-10',2,NULL,NULL),(9746,'活佛传','Kundun','讲述一个出生在牧民家庭小男孩，被寻找转世灵童的人发现并确定为未来的达赖，当其继承前代达赖衣钵后更显示不同凡人的天赋。而后其便在拉萨学习经文，并且有机会接触外界文化和思想。当其还羽翼未满时当时的摄政王企图夺位，好在衷心辅佐他的人平除了那次危机。  　　但是这时的历史已经发生巨变，社会主义中国成立了，要求收回西藏，他不想人民流血而采取非暴力的不合作方式，包括去北京会见毛泽东，接受思想教育。这时达赖向周围那些大国四处求援但无人应答，根本无法拒绝解放军入驻西藏的要求，接着辅佐的人们也相继离他而去，最后他在困顿交加中离开了西藏。',NULL,28000000,5684789,7.039189,6.8,91,134,'1997-12-25','en','/yvdFRDoQIQ5PBk4u8x8gJT8NJAw.jpg',2.8546562258708685,3,'2026-09-10',2,NULL,NULL),(9754,'防火墙','Firewall','年过中旬的杰克·斯坦福（哈里森·福特 Harrison Ford 饰）是位于美国西雅图市太平洋银行的网络安全高级主管，他凭借其主持设计的高科技防火墙软件而备受高层的重视，也因此杰克与妻子儿女过着养尊处优的幸福生活。然而，他的重要性也同样引起了不法之徒的注意。歹徒比尔•考克斯是个高智商的罪犯，他和他的团伙用一年的时间研究斯坦福一家的作息习惯和相关资料。在一切准备充分后，比尔绑架了杰克的家人，并胁迫杰克破解太平洋银行的防盗系统，从而盗出一亿美元现金。顾及到妻儿的性命，杰克违心答应了比尔的要求，与此同时他也和这个狡猾的家伙展开了斗智斗勇的对决','Nothing Is More Dangerous Than A Man With Everything To Lose.',45000000,82800000,18.186026,5.6,267,105,'2006-02-10','en','/h55rjJP8V2ubCZVhZ305zkepaf8.jpg',3.0481418579681145,3,'2026-09-10',2,NULL,NULL),(9759,'Cellular','Cellular','A young man receives an emergency phone call on his cell phone from an older woman. She claims to have been kidnapped – and the kidnappers have targeted her husband and child next.','If the signal dies so does she',25000000,56422687,24.459948,6.1,537,94,'2004-09-06','en','/y4eFuRYkyOIYwpjsUIxpA8iH05f.jpg',3.25343975877574,3,'2026-09-10',2,NULL,NULL),(9760,'史诗电影','Epic Movie','被卢浮宫馆长扶养长大，却因为某白化病刺客杀死馆长而被迫四处流浪的露西（洁玛·梅斯），在墨西哥“自由摔角”大闹过后的难民爱德蒙（卡尔·潘）。近来“航班蛇患”事件中的生还者苏珊（芳恩·钱伯尔斯）和来自“X战警社区”却没有超能力的变种人彼得（亚当·坎贝尔），这四个可怜孤儿终于走到了一起。  　　不幸的四人受邀进入怪人威利·旺卡的“巧克力冒险工厂”参观，结果露西在一个房间发现了神秘的魔衣橱。好奇的露西打开衣橱，竟然发现它可以通到传说中的“哪里呀”王国！在王国里，他们遇见了上半身是人而下半身却长着羊蹄的小鹿，打扮花哨的海盗头子杰克船长，巫师学院的哈利波特，而他们都是正义狮神阿斯兰大军的成员。为了对抗邪恶的“白衣贱女巫”，他们加入了狮神阿斯兰的队伍，成为王国的统领，带着虾兵蟹将，拯救“哪里呀”王国！','We know it\'s big. We measured.',20000000,86865564,6.064638,3.2,326,86,'2007-01-25','en','/sKAhLics4DnOLeXODTjByOC4gGn.jpg',2.834760329476819,3,'2026-09-10',2,NULL,NULL),(9762,'舞出我人生','Step Up','个性张扬的街头嘻哈与高贵典雅的芭蕾可以在舞台上完美的契合，就像泰勒（钱宁 •塔图姆饰）与诺拉（珍娜•迪温）的结合一样。这是一个奇迹，还是一种宿命。泰勒是来自巴尔的摩的底层社会的反叛青年，诺拉是就读与贵族艺校的优秀的芭蕾舞学生。诺拉要参加的高级舞蹈比赛，需要一个舞技超群的舞伴，而泰勒刚好因为被罚在艺术学校社区服务而闯入诺拉的视野。泰勒随意自如的街头舞蹈吸引了诺拉，舞台上的一次次合作，让这两个同样执着于艺术的孩子擦出律动的火花。两条原本平行的直线，交汇于舞蹈的光辉。','Every Second Chance Begins With a First Step',12000000,114194847,45.477802,6.7,1060,104,'2006-08-11','en','/tHiV8eBgEo7oBgpOGlYrRkXjxUI.jpg',3.554964241997492,3,'2026-09-10',2,NULL,NULL),(9763,'一球成名','Goal!','像世界上那些的孩子们一样，桑提亚格有一个梦想，就是成为职业足球运动员。但是，身居洛杉矶贫民区的他，只是个墨西哥来的穷小子，职业足球运动员，对他仅仅是一个梦。直到有一天，命运的大门向桑提亚格敞开，英国超级联赛的纽卡斯尔联队向他敞开了大门。突然间，桑提亚格成为了阿兰·希勒、马丁·泰勒、大卫·贝克汉姆等人中的一员。幸福来的太快让桑提亚格迷失了方向，职业球员的训练远比他经历过的困难，面对挫折与挑战，桑提亚格向着自己的球星之梦前进。','Every Dream Has A Beginning',30000000,27610873,16.541791,6.6,238,118,'2005-06-06','en','/32yi9JPsdCk5oP3rNaFvUQVkS7w.jpg',3.0967746285570414,3,'2026-09-10',2,NULL,NULL),(9766,'重振球风','Gridiron Gang','肖恩（Dwayne Douglas Johnson）是少年监管所的管理员，每天都为少年犯之间的纷争而烦恼。在他看来这些少年犯在这样的监禁环境下根本无法洗心革面，他的工作毫无意义。  　　在年迈母亲的鼓励下，肖恩决定用橄榄球改变孩子们的人生，将他们拉回正轨。尽管通过艰难的游说，肖恩终于说服高校赛季同意他带领少年犯参赛，但说服这些问题少年组成一只真正的队伍更加困难重重。肖恩用自己的强硬和对孩子们的信任打动了他们，组建了一只“野马队”。在他看来，帮孩子们找回失去的人生比赢得比赛更为重要。  　　很快他们参赛了，一路风雨兼程，这只特殊队伍回取得怎样的成绩呢？','One goal. A second chance.',30000000,41480851,9.278361,6.5,206,125,'2006-09-15','en','/tTjDApg546wt8OWazvPbEhygu83.jpg',3.0385819334452466,3,'2026-09-10',2,NULL,NULL),(9767,'分手男女','The Break-Up','盖瑞（文斯•沃恩 饰）在球场上遇见了布鲁克（詹妮弗•安妮斯顿 饰）并对她一见钟情。两人很快同居了。不久两人就在各种生活的琐碎事情中矛盾重重，艺术家气质的布鲁克看不惯盖瑞的不拘小节，矛盾再一次升级，布鲁克提出分手。由于房子是共同的财产，他们都没有搬离房子。布鲁克不断约会帅气的男孩，盖瑞也把屋子弄得乌烟瘴气，更带脱衣女郎回家，但彼此心中还是爱着对方。在朋友的劝解下，他们出售了房子，并要在两个星期之内搬走。凡事粗心的盖瑞终于在与朋友的聊天中得知了布鲁克的真实想法，当他想布鲁克剖白心意的时候，却遭到了布鲁克的拒绝……','. . . pick a side.',52000000,204999686,26.251217,5.6,832,106,'2006-06-01','en','/iawmL33wgRIk9zyXflQdn7pxBM7.jpg',3.272073180184277,3,'2026-09-10',2,NULL,NULL),(9770,'危机最前线','Mad City','麦克斯（达斯汀·霍夫曼 Dustin Hoffman 饰）曾是新闻界炙手可热的新星，一次工作中的失误让他受到了贬职的惩罚，自此无法翻身的他被派往了偏远的小镇中，成为了一个每天播报着无关紧要消息的小镇记者。\r 　　一日，麦克斯正在博物馆采访，一个名叫山姆（约翰·特拉沃塔 John Travolta 饰）的男人持枪劫持了博物馆的馆长。原来，山姆曾经是博物馆的工作人员，在裁员中丢了工作，无法接受现实的他选择了用极端的方式表达自己的愤怒。很快，敏感的麦克斯发现，自己或许可以利用这场事故挽回自己在新闻界的名声，于是，野心勃勃的他立刻展开了他的工作。随着麦克斯的播报，越来越多的媒体和记者聚集到了博物馆周围，很快，事态的发展就脱离了控制。','One man will make a mistake. The other will make it a spectacle.',50000000,10541523,3.314004,5.9,81,114,'1997-11-07','en','/r3daAzAjJavlYosckkhkOECERRo.jpg',2.791876421679313,3,'2026-09-10',2,NULL,NULL),(9772,'空军一号','Air Force One','俄美两国策划一起反恐行动，派出特种部队擒获了掌握核武器的哈萨克王国独裁者伊万·雷迪克将军（Jurgen Prochnow 饰）。数周后的庆功宴上，曾为越战老兵的美国总统詹姆斯·马舍尔（哈里森·福特 Harrison Ford 饰）针对恐怖分子和独裁政权发表了强硬而精彩的演说。莫斯科之旅圆满结束，总统一家及其政要乘空军一号返回美国，同行的还有艾格（加里·奥德曼 Gary Oldman 饰）带队的俄罗斯媒体工作人员。\r 　　安全人员百密一疏，艾格的真实身份是效忠于雷迪克将军的恐怖分子。飞机起飞后，艾格和同伴们劫持飞机，绑架美国政要及总统家人，只有詹姆斯侥幸逃脱。恐怖分子要求俄美释放雷迪克将军，而藏身空军一号中的詹姆斯则和这群匪徒展开殊死决斗……','The fate of a nation rests on the courage of one man.',85000000,315156409,36.38795,6.2,840,124,'1997-07-25','en','/aWIvgE6Fp9t28k32zTs9rvi2q8s.jpg',3.3933389182770117,3,'2026-09-10',2,NULL,NULL),(9776,'乌龙元首','Head of State','梅斯（克里斯·洛克 饰）是华盛顿一个前途渺茫的小议员，亲人和未婚妻先后弃他而去，谁知最近发生的一件事竟然让梅斯咸鱼翻身，原来此时正值总统大选，代表民主党参选的候选人突然遇刺身亡，情急之下，梅斯被推上了前台，委以竞选下届美国总统的重任。\r 　　小议员成了总统候选人，梅斯的哥哥和未婚妻重新回到了梅斯的身边，所有的人都对他堆满笑脸，台前、幕后，形形色色的人怀揣着各自的目的上演了一出大选闹剧......',NULL,0,0,3.457194,5.3,71,95,'2003-01-01','en','/5itBve85q2oXmiQ3SkgCJa5Asxq.jpg',2.7486944420487203,3,'2026-09-10',2,NULL,NULL),(9778,'Serendipity','Serendipity','Although strangers Sara and Jonathan are both already in relationships, they realize they have genuine chemistry after a chance encounter – but part company soon after. Years later, they each yearn to reunite, despite being destined for the altar. But to give true love a chance, they have to find one another again.','Sometimes True Love Can Have More Than One Face.',28000000,77516304,14.530803,6.6,521,90,'2001-10-05','en','/xjZ6kkOdib2G2EV3LmslorUd1vX.jpg',3.2867801365946594,3,'2026-09-10',2,NULL,NULL),(9779,'牛仔裤的夏天','The Sisterhood of the Traveling Pants','该片根据2001年安·布拉谢尔最畅销小说改编而来，讲述了四个闺中密友的故事，这四个小姑娘第一次没有在一起过夏天，将她们联系在一起的是一条会魔法的牛仔裤，尽管这四个女孩体形、个头和欣赏力各不相同，但这条神奇的牛仔裤却总能适合她们。在接下来的一个夏天，在分开的日子里，会飞的牛仔裤给身处不同的地方的她们带来了不同的奇遇，让她们都经历了一个难忘的夏天。','Laugh. Cry. Share the pants.',25000000,39053061,17.17372,6.3,386,119,'2005-06-01','en','/oetVWVTXKZUDKmmdOKWO3iAKIkL.jpg',3.1863378541764558,3,'2026-09-10',2,NULL,NULL),(9781,'摇滚城市底特律','Detroit Rock City','自70年代以来，KISS摇滚乐团一直被誉为地球上最伟大的乐团，狂放不羁的歌词及怪异的装扮，是该团最大的特色。电影[摇滚新世代]是为了向这个传奇乐团致敬而拍摄的。这部电影是一部绝妙喜剧，叙述四个青少年出发前往底特律参加KISS演唱会，开始了他们的KISS朝圣之旅。','Kiss The Rules Goodbye.',6500000,4217115,5.700333,6.7,100,95,'1999-08-13','en','/jedOctnsD20K4IvOeh5jG811B8L.jpg',2.8702350187651375,3,'2026-09-10',2,NULL,NULL),(9782,'午夜听众','The Night Listener','加布里（罗宾·威廉斯Robin Williams饰）作为一档深夜聊天节目的电台DJ，有着这个城市众多的拥趸，小男孩彼特就是其中一员。事实上，加布里首次接触彼特，是在朋友送来的一本书稿上。这本书的作者是彼特，上面写着他的种种不幸：自小遭父母虐待，为大人们提供肮脏的性服务。加布里和彼特在电波中交流谈心，渐渐筑起亲密的情谊。  　　但是，怀疑随之而来。彼特的故事背后还藏着有一个叫唐娜（东妮·克蕾特Toni Collette饰）的女人，她是彼特现时的养母。在唐娜那里，加布里猜测到彼特的故事远远没有表面那样简单。他奔赴往彼特居住的小镇，以图一探究竟。加布里在镇上见到了双目失明的唐娜，这个女人让加布里陷入了更大的谜团当中，到底是否存在过彼特这个男孩，也成了不可知的神秘事件','You never know who\'s listening.',0,0,7.173059,5.5,57,91,'2006-02-12','en','/xIQgviGRTxZ6o0iPooGUSn4Q1PW.jpg',2.7185436644029357,3,'2026-09-10',2,NULL,NULL),(9783,'恐怖杀人医院','Sublime','居家男人兼电脑分析师乔治•格雷夫斯（Thomas Cavanagh 饰）迎来了他四十岁的生日。在这个后半生的起点上，事业有成且家庭美满的乔治却对未来感到阵阵不安。他担心妻子不忠和朋友的虚情假意，害怕一双儿女误入歧途，甚至生活中微小的细节都能引起他阵阵担忧。\r 　　生日的第二天，乔治在妻子珍妮（Kathleen York 饰）的陪同下来到医院做例行的肠道透镜检查。但这项普通的检查却引起了严重的医疗事故。从此，乔治心中的各种担忧开始轮番出现其眼前，在病榻上，他被迫审视和面对自己内心的恐惧和秘密……',NULL,0,0,6.833164,5.3,33,113,'2007-06-15','en','/285yCXj3JIe7rXdedZJ0FD4KPnS.jpg',2.604564732166974,3,'2026-09-10',2,NULL,NULL),(9787,'狗镇之主','Lords of Dogtown','该片讲述了自称为“西风少年”的酷爱冲浪的男孩们希望成为职业冲浪选手的梦想的故事。','They never thought they\'d be famous, but they always thought they\'d be friends.',25000000,13411957,8.127728,7,210,107,'2005-06-03','en','/k2NiPfydLSwmk28C6qpvpJPuqtq.jpg',3.0740625678046714,3,'2026-09-10',2,NULL,NULL),(9792,'隔山有眼','The Hills Have Eyes','老夫妻鲍勃·卡特(泰德·列文饰)与艾塞尔(凯瑟琳·昆兰)为了庆祝他们的结婚纪念日，带着家人开车做一次穿越国境的公路长途旅行。本希望借此次旅行增进家庭成员之间的感情，但旅行中发生的种种摩擦却时时考验着这个家庭。  　　旅程渐渐进入漫漫黄沙荒无人烟的地带，在一次夜晚扎营时休息时，他们遭受到了一群怪物的袭击，原来此处附近曾有一个废弃美军研制核武器的基地，核实验让附近一个村庄的人们遭受到了可怕的核辐射，活下的人身体变的畸形且性情嗜血而暴力，他们伏击这一家人，对他们进行残忍的捕杀，原本老实懦弱的女婿达乌·布库威斯基(亚伦·斯坦福德饰)决心振作起来，做出最强烈的反击。','The lucky ones die first.',15000000,69623713,35.107857,6.1,705,107,'2006-03-10','en','/cUGRobWfsSKpZjFULo73O9HdCt4.jpg',3.336517710005937,3,'2026-09-10',2,NULL,NULL),(9793,'隔山有眼2','The Hills Have Eyes 2','美国新墨西哥州的炎热荒地里，经常发生神秘失踪事件，又因其与世隔绝，里面的凄惨故事很难为外界所知。在卡特家族误入变异食人魔领地惨遭杀戮之后一年，一行八人的国防护卫队士兵又被排到这片戈壁滩执行训练任务。在其余六人被派到山里时，剩下被罚站的法国裔士兵拿破仑（麦克·麦克米兰 Michael McMillian 饰）与金发女兵安博尔（杰西卡·斯托普 Jessica Stroup 饰）在基地留守。异状很快发生，厕所里面伸出一只可怕的手，一位全身被粪便入侵的科学家爬了出来，留下一句“小心他们”就死去了，安博尔坚持上山寻找其他人发出警告，怎料变异食人魔们早就在错综复杂的山道布下天罗地网，等待倒霉的猎物们前来送死……','Help isn\'t coming.',15000000,0,17.141376,5.2,351,89,'2007-03-22','en','/ezTdgoPgfrMUjqWgamjH5ZebtFx.jpg',3.0571817627680447,3,'2026-09-10',2,NULL,NULL),(9794,'明星雇员','Employee of the Month','扎克（戴恩·库克 Dane Cook 饰）和文斯（戴克斯·夏普德 Dax Shepard 饰）供职于一家全国规模最大，商品最齐全，折扣最丰富的超级市场中，在这里，成为每月的“明星雇员”无疑是每一个工作人员的理想与希望。这十年来，履历、年龄、工龄均极为相似的扎克和文斯却走上了两条完全不同的道路，扎克工作勤勤恳恳，恪尽职守的他不仅被连升数职，更是连续17次获得了“明星雇员”的称号。反观文斯，生活里乏善可陈，工作中偷懒耍滑，所以直到现在，他依旧处于超市食物链的最低端。','A slacker competes with a repeat winner for the \"Employee of the Month\" title at work',12000000,38368909,9.559737,5.3,153,103,'2006-10-06','en','/vfALEF9wz4CEep071iOwM5Qqd17.jpg',2.907062956061882,3,'2026-09-10',2,NULL,NULL),(9798,'Enemy of the State','Enemy of the State','Hotshot Washington lawyer, Robert Dean becomes a victim of high-tech identity theft when a hacker slips an incriminating video into his pocket. Soon, a rogue National Security agent sets out to recover the tape – and destroy Dean.','It\'s not paranoia if they\'re really after you.',90000000,250649836,41.207568,6.7,1240,132,'1998-11-20','en','/dJs2A4tkGA5o7Wdj5MVETz7Rs5L.jpg',3.5858016183229173,3,'2026-09-10',2,NULL,NULL),(9799,'速度与激情','The Fast and the Furious','洛杉矶的年轻人都热衷于街头赛车，在这里，只要你拥有速度，你就拥有一切。新晋警官布莱恩（保罗·沃克 Paul Walker 饰）为了破获最近屡屡发生的飞车党劫车案而充当卧底，打入这里活跃的飞车党帮派中，搜集证据以期将罪犯乘之于法。布莱恩凭借高超的车技很快赢得了飞车党老大多米尼克（范·迪塞尔 Vin Diesel 饰）的欣赏和信任，并且很快和多米尼克的妹妹米娅（乔丹娜·布鲁斯特 Jordana Brewster 饰）堕入爱河。然而飞车党的第二把手文斯却是对布莱恩充满敌意，原来文斯一直暗恋米娅，而且布赖恩的到来威胁着他二把手的地位。这时，飞车党的成员们开始怀疑他们内部藏有奸细，布莱恩的日子开始不好过。而且和多米尼克接触越久，他们之间的友谊就越加深厚，布赖恩开始进退两难。','Live life 1/4 mile at a time.',38000000,207283925,6.909942,6.6,3428,106,'2001-06-22','en','/gqY0ITBgT7A82poL9jv851qdnIb.jpg',3.7377422116460415,3,'2026-09-10',2,NULL,NULL),(9800,'费城故事','Philadelphia','安德鲁（汤姆•汉克斯 Tom Hanks 饰）和米勒（丹泽尔•华盛顿 Denzel Washington 饰）认识于法庭上，两人都是年轻有为的律师，各为其主。然而，年轻的安德鲁不久后因为同性恋和身染艾滋病被老板发现，以莫须有理由解雇了。遭解雇后的安德鲁四处寻找律师为他讨回公道。当安德鲁找到米勒时，米勒一开始拒绝了他。因为米勒像普通人一样憎恨同性恋和惧怕艾滋病，但当他看到安德鲁在图书馆搜索“艾滋病歧视”时遭到管理员的白眼，听着妻子缓慢而平静地说出他们的姨妈、朋友有很多也是同性恋时，他决定受理安德鲁的案件。在最后的法庭上，病危的安德鲁毅然出庭……','No one would take on his case... until one man was willing to take on the system.',26000000,206678440,44.301745,7.6,988,125,'1993-12-22','en','/godlAGNI4yN4XcmYOiZ3e2JTavC.jpg',3.6894231882899833,3,'2026-09-10',2,NULL,NULL),(9801,'BJ单身日记2：理性边缘','Bridget Jones: The Edge of Reason','布里奇特•琼斯（蕾妮•齐维格 饰）自从与律师马克•达西（科林•菲尔斯 饰）坠入爱河后，心想着与男友终成眷属的布里奇特又遇到了麻烦。她开始怀疑自己的生活与马克的爱情，她不知道当激情过后会留下什么。当她极力想知道答案的时候，达西美丽温柔的新助手丽贝卡（杰辛达•巴莱特 饰）使她觉得自己的情敌出现了，令布里奇特醋意大发。\r 　　在与男友马克冷战之时，前男友丹尼尔也来到了她所在的电视台，更要跟布里奇特一起到外国录影。布里奇特以为丹尼尔真的悔过想回到自己的身边，谁知丹尼尔仍旧死性不改。布里奇特急急与朋友回国，谁料在机场被捕……','Same Bridget. Brand new diary.',50000000,40203020,28.803802,6.1,750,108,'2004-11-10','en','/uMGlXoEnt263Ut1SUboscpKpYuK.jpg',3.3354771213890184,3,'2026-09-10',2,NULL,NULL),(9802,'The Rock','The Rock','A group of renegade marine commandos seizes a stockpile of chemical weapons and takes over Alcatraz, with 81 tourists as hostages. Their leader demands $100 million to be paid, as restitution to families of Marines who died in covert ops – or he will launch 15 rockets carrying deadly VX gas into the San Francisco Bay area.','Alcatraz.  Only one man has ever broken out.  Now five million lives depend on two men breaking in.',75000000,335062621,51.469576,6.9,1456,136,'1996-06-06','en','/np47mVbr7vdKG8HOOJSYTEuZZPW.jpg',3.6905261844593387,3,'2026-09-10',2,NULL,NULL),(9804,'Waterworld','Waterworld','In a futuristic world where the polar ice caps have melted and made Earth a liquid planet, a beautiful barmaid rescues a mutant seafarer from a floating island prison. They escape, along with her young charge, Enola, and sail off aboard his ship. But the trio soon becomes the target of a menacing pirate who covets the map to \'Dryland\' – which is tattooed on Enola\'s back.','Beyond the horizon lies the secret to a new beginning.',175000000,264218220,44.640292,5.9,992,135,'1995-07-28','en','/z5Ngm5FANTMDUteQABhp7UMwXBi.jpg',3.3974473033282604,3,'2026-09-10',2,NULL,NULL),(9806,'超人总动员','The Incredibles','鲍勃是一个超人特工，他惩恶扬善，深受街坊邻里的爱戴。“不可思议”先生就是他的光荣外号。他和另一个超人特工“弹力女超人”相爱，两人结婚后过上平静的生活。15年过去了，鲍勃已经像普通人一样生活，当上了保险公司的理赔员。然而他心中还是有着技痒之时。当他知道有发明家要展开攻击超人特工队、毁灭人类的计划，鲍勃终于按捺不住了。他要重出江湖，挽救人类护卫地球。但中年的超人已经大腹便便，他和敌人的斗争充满了悬念。鲍勃的妻子也跟丈夫一起投入到这场艰巨的战争中。','No gut, no glory',92000000,631442092,77.817571,7.4,5152,115,'2004-11-05','en','/2LqaLgk4Z226KkgPJuiOQ58wvrm.jpg',4.2059385307506565,3,'2026-09-10',2,NULL,NULL),(9809,'同居牢友','Let\'s Go to Prison','刚刚重获自由的约翰（戴克斯·夏普德 Dax Shepard 饰）再次走入了监狱，不为了别的，只为了复仇。原来，约翰此次入狱是为了执行一个任务——保护检察官的儿子尼尔森（威尔·阿奈特 Will Arnett 饰），这个检察官不是别人，正是害得约翰屡屡遭受牢狱之灾的罪魁祸首。  　　父债子还，刚来到尼尔森身边，约翰就将他卖给了狱中人人望而生畏的同性恋老大巴里（切·麦克布瑞德 Chi McBride 饰），本以为尼尔森即将遭遇非人待遇的约翰却没有想到，尼尔森竟然激起了巴里内心的爱意和温柔，很快两人便心心相印起来。就这样，尼尔森从一个狱中菜鸟转眼变成了大名鼎鼎的“压寨夫人”。绝望中，约翰明白，自己接下来的日子不会太好过。','Welcome to the slammer',4000000,4630045,4.59841,5.5,69,84,'2006-11-17','en','/8p64GZR0xEQaAfHY2309ShgtMap.jpg',2.7509327692507863,3,'2026-09-10',2,NULL,NULL),(9813,'沉默','The Quiet','尼娜（伊丽莎·库斯伯特 Elisha Cuthbert饰）青春貌美，是学校的啦啦队队长。如此明媚的女生，却有着不为人知的隐秘。以此她心里有着浮浮沉沉的挣扎。尼娜的父母从教会处领养了一名美丽的聋哑少女道格（卡米拉·贝勒 Camilla Belle饰）。她幼年丧母，从此不会说话，陷入一片沉默的世界。正因为如此，人人都把这个不会泄密的女孩当作倾说秘密的对象，道格知道了很多人的秘密。但道格本身更为惊人的秘密，却从没有为他人所晓。而且，她将会被尼娜的秘密卷入更深的漩涡…','Isn\'t it time everyone hears your secrets?',900000,381420,4.0971,6.1,73,96,'2005-09-12','en','/lXIuHcRGCRk0YBOi41MCHMvGst5.jpg',2.7774123011688605,3,'2026-09-10',2,NULL,NULL),(9816,'留住最后一支舞','Save the Last Dance','母亲的死让莎拉（朱丽娅·斯蒂尔斯 Julia Stiles 饰）不得不放弃了舞蹈的梦想，她只身来到了芝加哥，在那里，她名义上的父亲正等待着她。新生活来得如此之快，还没有走出丧母阴影的莎拉感到手足无措，就在她濒临崩溃的边缘时，一个叫德里克（西恩·帕特里克·汤玛斯 Sean Patrick Thomas 饰）的黑人男孩出现在了她的身边。','The Only Person You Need To Be Is Yourself.',13000000,91038276,9.969624,6.3,352,112,'2001-01-12','en','/wq3kXDtuoLP2eo9DIuNgxqiR6sN.jpg',3.1487578005290495,3,'2026-09-10',2,NULL,NULL),(9819,'马文的房间','Marvin\'s Room','中年妇女贝西（黛安·基顿 Diane Keaton 饰）的大半生都用来照顾两位年老的亲人：患中风的父亲马文和脾气古怪的姑妈鲁思。现在，贝西自己也患上了血癌，唯一生存的希望是近亲中有人提供骨髓。无奈的贝西只好与20年来没有联系的姐姐李（梅丽尔·斯特里普 Meryl Streep 饰）联络。李是个单身母亲，她并不想与贝西见面，但想到能借此暂时撇开儿子汉克（莱昂纳多·迪卡普里奥 Leonardo DiCaprio 饰）在家里纵火引起的烦恼，还是带着儿子回到佛罗里达的老家。姐妹刚见面时情绪还不错，但时间一久，过去的种种不快又开始作祟。而且住过精神病院的汉克不愿做骨髓化验，伤了贝西的心。后来，汉克与贝西的关系奇迹般地好了起来，并且使两姐妹之间的亲情得以恢复……','A story about the years that keep us apart... And the moments that bring us together.',0,0,6.130231,6.6,124,98,'1996-12-18','en','/7jWBP8A1o0HRjxyoRdKJ9PjFzvN.jpg',2.917509799513794,3,'2026-09-10',2,NULL,NULL),(9821,'陪着你走','The Mighty','麦斯是个大块头的男孩，患有学习障碍，因父亲是杀人犯及能力不足，老是被周遭的人欺侮嘲笑；凯文是矮个子的小男孩，头脑聪明，却因有肢体障碍而被取笑捉弄，他母亲因担忧他的障碍，过度保护，极少让他自由行动。世界总是那么孤独，直到麦斯跟凯文在一次偶然的机缘下相遇，麦斯当凯文的脚，而凯文则当麦斯的头脑，麦斯常背着凯文出游——依他俩人的说法是行侠仗义，他们自封为怪物骑士，打抱不平。两条生命的交会原本以为从此不再孤单，谁知凯文却先一步而去，独留麦斯为自己的人生继续奋斗……','The quest for friendship is the noblest cause of all',0,0,5.497682,7.1,51,100,'1998-10-23','en','/eHcuTZwmY4VAJm7kfbZn7qDAjYs.jpg',2.723724074046573,3,'2026-09-10',2,NULL,NULL),(9822,'无敌大猩猩','Mighty Joe Young','动物学家葛瑞格（比尔派斯顿饰）去中非的潘格里山群时，发现一件令人难以置信的东西，一只十五尺高且看起来令人害怕的大猩猩，当它受到刺激时，会表现出害怕和产生恐惧感的表情；但在吉儿（莎莉塞隆饰）的手中却显得很温驯，于是吉儿便把大猩猩命名为乔。 　当乔的生命受到猎人的威胁时，葛瑞格和吉儿就会拯救乔，带它去加州动物收容所。但乔并没有一直很安全，因为它的来历，使它声明大噪地让残酷的猎人想要偷走乔，想要得到它在危险动物黑市的独特价值。 　在人造的栅栏里，乔感到害怕不安，于是它逃离了囚禁。在它的逃离的路途中只有洛杉矶受到惊吓的居民跟随着它。靠着这种强大的自然意志力，横越了现代都市，但留下将被杀戮的痕迹，在它醒后另一场动汤的生活。 　在要围捕乔的相关单位摧毁乔的前夕，吉儿和葛班瑞格赶往去抢救乔的生命，吉儿在最重要的时刻表现出令人难以置信且无私的勇气，证明在他看起来瘦小的身躯里面，跳动着却是高尚且有英雄气概的心，使整部片达到最高潮','Survival is an instinct.',90000000,0,6.643778,5.9,208,114,'1998-12-25','en','/vaIYz0Y3cMnB2VVZokD4h1GNaE8.jpg',2.994863875518718,3,'2026-09-10',2,NULL,NULL),(9823,'真人快打：歼灭','Mortal Kombat: Annihilation','这次说的是天界恶魔要打通阴阳道，这样一来，能帮助人间勇士的天神亦无计可施，天地格斗大赛的地上一方只有依靠自己的力量，与魔鬼进行一场生死搏斗。期限无多，凡间的斗士怎样才能迅速充实自己的力量呢？','The world was created in six days, so too shall it be destroyed and on the seventh day mankind will rest... in peace',30000000,51376861,11.916389,3.8,221,95,'1997-11-21','en','/ttryglcY2osWZE3sRYBf3ewTZsW.jpg',2.8726857268216204,3,'2026-09-10',2,NULL,NULL),(9824,'神秘兵团','Mystery Men','Champion城的保护者，超级英雄Amazing上尉被绑架了。7个蹩脚“英雄”为拯救Champion城、救出Amazing上尉而同妄图控制整个城市的Casanova Frankenstein展开了斗争。','We\'re not your classic heroes, we\'re the other guys.',68000000,29762011,12.948627,5.7,250,121,'1999-08-06','en','/ciVSbFmDecOIwlxl9F6GhHVgCVJ.jpg',3.031568662237074,3,'2026-09-10',2,NULL,NULL),(9825,'史前巨鳄','Lake Placid','一起神秘的死亡时间吸引了古生物学家凯丽（布里吉特·芳达 Bridget Fonda 饰）的注意，为了了解事件的真相，凯丽千里迢迢的赶到了案发地——一个古老的湖泊，而之后发生的事情更让凯丽确信，在这平静的湖面下，隐藏了什么可怕的东西。凯丽的猜测在小镇上引起了轰动，有些人信以为真，另一些人则不以为然。就在舆论的热度到达最顶峰之时，一个游客被不明物体拖入湖中的惨剧让所有人都意识到，事情严重了。  　　凯丽和管理员杰克（比尔·普尔曼 Bill Pullman 饰），警长汉克（布莱丹·格里森 Brendan Gleeson 饰）等人围绕着古湖展开了调查，令人震惊的是，在湖底，他们发现了一只异常凶猛巨大的史前巨鳄。','You\'ll never know what bit you.',27000000,56870414,11.678561,5.5,247,82,'1999-07-15','en','/6jdsjjRb3HNv8BUT6FIuDkPNfi7.jpg',3.0111466952220183,3,'2026-09-10',2,NULL,NULL),(9826,'轰天奇兵','The Phantom','在本格拉丛林里，传说藏着三个分别用金、银、玉制作的神圣骷髅，将它们合为一体便可激发神奇的力量，从而统治世界。正因为如此，本格拉丛林吸引了来自世界各地的野心家，然而这里却藏着一个令他们闻风丧胆的人物，他就是骷髅奇侠。骷髅奇侠的真实身份是沃克尔家族，四百年前沃克尔的祖先落难于曼加勒岛，并受到土著捷嘉达族的救助。在此之后，捷嘉达族被海盗消灭，他们的神圣骷髅也流落本格拉丛林，从此世代受骷髅奇侠的守护。某天，纽约商人仙德尔·卓克斯（Treat Williams 饰）派出手下闯入本格拉丛林，而新一代的骷髅奇侠（比利·赞恩 Billy Zane 饰）将于他们展开新一轮的正邪大战……  　　本片根据1936年的同名漫画改编，并荣获1997年澳大利亚摄影师协会年度最佳摄影师和金三角架奖。','Slam Evil!',45000000,17300889,9.025236,4.7,136,100,'1996-06-06','en','/eCiLfxpW2O35t5FY8QsIgIe0wlw.jpg',2.8560848087631103,3,'2026-09-10',2,NULL,NULL),(9829,'93航班','United 93','知名电影人保罗·格林格拉斯编剧并执导的这部直面历史的剧作，以冷静笔触呈现了乘客与机组人员、地面家属以及航空管制员的故事——当联合航空93号班机在2001年9月11日（美国本土遭遇最严重恐怖袭击之日）成为第四架被劫持的航班时，所有见证者都逐渐陷入骇然的绝望。[环球影业]','September 11, 2001. Four planes were hijacked. Three of them reached their target. This is the story of the fourth.',15000000,76286096,17.50138,6.9,367,111,'2006-04-28','en','/pN1unN7wzo1mhLo9ElriLxs9nL0.jpg',3.2358224382504677,3,'2026-09-10',2,NULL,NULL),(9833,'歌剧魅影','The Phantom of the Opera','巴黎歌剧院合唱团的新人克莉斯汀最近进步神速，全因剧院内的一间古老房间内每晚都会传出一把优美的男声向她传授歌唱技巧。这个良师益友其实是一个人称“剧院魅影”的人，此人因样貌丑陋，自小便被父母抛弃，戴着面具隐居在剧院的地下室。“剧院魅影”内心其实深爱着克莉斯汀。一次偶然的机会，克莉斯汀有幸担当一部歌剧的主角。凭借从“剧院魅影”那里学得的丰富的歌唱技巧，克莉斯汀一炮而红，并被年轻英俊的剧院赞助人拉乌尔看上了。两个年轻人很快堕入了爱河。“剧院魅影”伤透了心，认为是拉乌尔抢走了克莉斯汀，准备上演一出爱情复仇的大戏……','The classic musical comes to the big screen for the first time.',70000000,154648887,18.927463,7,438,143,'2004-12-08','en','/xLRG0LU2j8x3klOJjlDdKRM4huu.jpg',3.2982146407907145,3,'2026-09-10',2,NULL,NULL),(9836,'快乐的大脚','Happy Feet','这是属于帝企鹅的伟大时代。它们占领者着南极洲的最深处，在这个家族里，只有一个办法能够让新生的小家伙得到大家的认可——拥有一副动听的歌喉。不幸的是，马伯(伊利亚·伍德配音)是整个家族里唱歌唱得最差的那个。但是，他却是一个天生的舞蹈家，街舞跳到出神入化。马伯的妈妈诺玛·吉恩(妮可·基德曼配音)，把马伯舞蹈天赋仅仅看成一个可爱的小爱好，但马伯的爸爸孟菲斯(休·杰克曼配音)却认为，不会唱歌只会跳舞的马伯根本就不是企鹅。不过他们达成共识的是，没有一副好嗓子的巴伯，可能永远也找不到真爱了。有趣的是，不会唱歌的马伯唯一的好朋友格洛丽亚(布兰特妮·墨菲配音)，正好是整个家族当中最好的歌手。虽然他们俩自出生后就一直在一起，对彼此都有特殊的感觉，但格洛丽亚总是被马伯与众不同的节奏舞步困扰着。马伯与其他帝企鹅实在是太不一样了--特别是对于家族中最严厉的领导者诺亚(罗宾·威廉姆斯配音)来说。虽然诺亚的独断专行导致他最后被家族所排斥，但他一贯不依不饶的态度迫使马伯产生了离开的念头。第一次离开家的马伯，在路上碰到了一群企鹅朋友。他们不是帝企鹅，而是阿德兰企鹅，首领叫做罗曼。阿德兰们被马伯独特的舞步深深打动，邀请他去参加一个盛大的舞会。在阿德兰的地盘上，马伯用一块鹅卵石的代价，获得了一位头上长有奇怪羽毛，跳着摇滚舞步的流浪者的指引，他回答了马伯生命中的很多疑问……','WARNING: May Cause Toe-Tapping.',100000000,384335608,37.272385,5.9,1410,108,'2006-11-16','en','/ipnMKGrs6U3WIe35vaJ33GYOnJ2.jpg',3.4516276649113267,3,'2026-09-10',2,NULL,NULL),(9837,'埃及王子','The Prince of Egypt','法老发现自己的王国内希伯来人日益增多，开始感到不安，对希伯来人总是无端猜疑，于是命令所有的希伯来人都去当奴隶，并吩咐讲所有希伯来人生的男孩扔到河里。这天，一个希伯来妇女生了一个漂亮的男孩，为了自己的孩子能够幸免于难，她将他放到一个草箱中放进了尼罗河。  　　皇后在河边捡到了这个漂亮的男孩，将他带回宫殿抚养，取名摩西。摩西和王子兰姆蒂斯一起长大，两人成了最好的朋友。摩西十分反对法老对希伯来人的暴政，一次他为了阻止一名埃及人残害希伯来人而将失手将他打死。为了逃避法老的惩罚，摩西逃到了米甸地。不久法老去世，兰姆蒂斯成了新法老。摩西原本以为兰姆蒂斯会一改以往法老对希伯来人的暴政，没想到兰姆蒂斯反而变本加厉。在神的指示下，摩西知道了自己的身世，于是他决定要带领希伯来人走出困境。','The Power Is Real.',70000000,218613188,29.464852,6.8,817,99,'1998-12-15','en','/fklvThNyav2rCAcTyFgayladQdm.jpg',3.4664805976370467,3,'2026-09-10',2,NULL,NULL),(9839,'超越边界','Beyond Borders','莎拉·乔丹（安吉丽娜·朱莉 Angelina Jolie饰）是一位过着令人艳羡的上流生活的社会名媛，她的丈夫也是事业有成的实业家。杯觥交错的生活，原本可以一直这样富有安逸的过下去，直到她在一次慈善晚宴上邂逅了一生挚爱尼克·卡拉汉（克里夫·欧文 Clive Owen饰）——终生致力于人道主义救援的医生。  尼克常年工作在条件艰苦甚至有生命危险的国家地区，为那些身处战乱忍受饥饿疾病的人们实施医疗援助。莎拉被深深的触动了，她放弃了现有的生活，前往埃塞俄比亚与尼克的队友一起参加救援工作。从贫瘠蹂躏的埃塞俄比亚到战火纷飞的越南再到暴乱不断的车臣，这对超越边界、超越种族、超越时空的爱人，为了共同的信念，付出了一切…… ©豆瓣','Where hope survives.',35000000,0,6.523472,6.7,110,127,'2003-10-23','en','/j7Upm2AtGuTzCs2Asq0GyBIMAxX.jpg',2.8944640854012804,3,'2026-09-10',2,NULL,NULL),(9842,'噱头大王','School for Scoundrels','\"用窝囊废来形容罗杰（琼•海德 饰）一点不为过。生性懦弱的他，面对外表凶狠的人时，大气都不敢出一口。想请倾慕的邻家女孩（杰辛达•巴莱特 饰）出去吃饭，竟然因紧张而昏倒。总是在关键时刻莫名失败的他，决定改变自己的性格。做一个真正的男子汉。\r 经朋友介绍，罗杰来到一所秘密的，号称“懦夫救星”的学校，班主任P博士（鲍勃•松顿 饰）是一个强悍的老师。他的教学方法极端怪异，却收效甚佳。很快，罗杰找回了自信，与女孩的关系也有了进展。然而，罗杰没有想到，他与P博士竟爱上了同一个人。一场师生的竞争，一场荒诞的闹剧，正在上演。\"','Life\'s A Game. Learn How To Play.',20000000,17807569,8.244324,5.6,111,100,'2006-09-29','en','/ffudFsgDUBfxbesYELDIrNtKdkz.jpg',2.856888021597051,3,'2026-09-10',2,NULL,NULL),(9849,'外星人报到','My Favorite Martian','提姆（杰夫丹尼尔 饰演）是个很有企图心的电视新闻记者，可是他却得不到老板的赏识，某次回家的路上，竟遇上火星人的太空船撞上地球！转化地球人外观的火星人马汀，为了修复太空船，只好找上提姆，提姆与马汀相处越久，越发觉它其实是个善良的外星人，但因为马汀的行为怪异，不知不觉被太空研究中心小组成员盯上了……','The martian has landed. There goes the neighborhood.',65000000,36850101,6.80692,5.1,80,94,'1999-02-11','en','/pOp4xriDEFUy2uN0BfnHJcjzqWt.jpg',2.773511787714558,3,'2026-09-10',2,NULL,NULL),(9869,'爱国者游戏','Patriot Games','原美国中央情报局分析员杰克·瑞安和妻子、女儿在伦敦度假。一天他目睹了恐怖分子袭击北爱尔兰国务大臣霍姆斯勋爵。瑞安上前相助，击毙一名袭击者，另一名恐怖分子肖·米勒被警察逮捕。瑞安因此受到奖赏并被封爵。后来他回到美国，继续在一所海军大学任教。米勒被转送到怀特岛的监狱后被同伙营救。匪首奥唐奈又计划于霍姆斯访问美国时再袭击他。越狱的米勒愿意当奥唐奈的助手。一次下课之后，瑞安发现有人跟踪他。他发现米勒已逍遥法外并威胁到他全家的生命安全。不久，米勒在一条拥挤的快车道袭击瑞安的妻子和女儿。当瑞安知道了这一切之后，决心重返中央情报局，粉碎米勒一伙人的阴谋。','Not for honor. Not for country. For his wife and child.',45000000,178051587,19.637704,6.3,433,117,'1992-06-04','en','/54TTGOvCFRrWvkwBodv4UKcYVmF.jpg',3.2183424649607035,3,'2026-09-10',2,NULL,NULL),(9870,'忘掉莎拉·马歇尔','Forgetting Sarah Marshall','剧情：音乐家皮特一直对他的女友——电视剧明星莎拉·马歇尔痴心不已。尽管在莎拉拍照时，皮特只能在一旁帮忙拿包，在莎拉领奖的感谢词里，也经常漏掉皮特的名字，然而皮特仍旧无怨无悔。直到有一天，莎拉终于抛弃了他。这次失恋让皮特倍受打击，他曾试过寻找别的女人来替代莎拉，却毫无用处。工作与生活都因为失恋而变得灰暗起来。为了清醒一下头脑，皮特很冲动的买了去夏威夷的机票。然而命运偏偏跟他开了个玩笑：莎拉和她的新男友居然跟他住在同一家酒店里！每天看着两个人亲亲我我，皮特觉得非常沮丧。就在这时，他邂逅了度假村的服务员瑞秋，在与瑞秋的相处中，皮特又重新找回了爱情……','You lose some, you get some.',30000000,105173115,50.670253,6.4,1172,111,'2008-04-17','en','/d4elOzyhNWVlxpG7BwigrumkFTe.jpg',3.5373428313130604,3,'2026-09-10',2,NULL,NULL),(9877,'下一个就是你','Urban Legend','美国新英格兰地区的普德顿大学流传着一个名为“斯坦利堂大屠杀”的恐怖传奇，话说25年前，一名异常心理学教授在斯坦利堂大开杀戒随后自杀，这起血腥惨案至今在学生中间广为流传。适值此时，校园内发生一连串的凶杀案。校报记者保罗·加德纳（杰拉德·莱托 Jared Leto 饰）坚信凶手就隐藏在校园内，他的朋友之一娜塔莎·西蒙（艾丽西亚·维特Alicia Witt 饰）更将此事与斯坦礼堂大屠杀联系起来。他们二人携手调查此事，在这一过程中，他们的朋友借二连三遇难。娜塔莎吃惊地意识到，她和保罗已经进入凶手设下的狩猎陷阱之中。  　　越逼近真相，危险便离他们越近…','It Happened To Someone Who Knows Someone You Know... You\'re Next.',14000000,72527595,12.159009,5.6,290,99,'1998-09-25','en','/dUvZDNU9G0njhM628NA5phASntq.jpg',3.0497126203700113,3,'2026-09-10',2,NULL,NULL),(9879,'脱衣舞娘','Striptease','佛罗里达的一家酒吧里，每晚都有一个叫埃琳的女人来跳脱衣舞，迷恋她的客人中有国会议员戴维·迪尔贝克。这一天，有个酒鬼纠缠埃琳，被迪尔贝克一顿臭揍，但自己的身份也随之暴露，随后就开始被敲诈。不久敲诈他的人被谋杀。加西亚警官负责侦办此案，发现酒吧的保安人员也有敲诈行为。而埃琳的前夫是个惯偷型的无赖，埃琳之所以出卖色相是为了挣钱以保住对七岁女儿的监护权……','Some People Get Into Trouble No Matter What They WEAR.',50000000,113309743,11.106006,4.4,205,115,'1996-06-28','en','/wE37L0L8Ev4tguZrvLtpmQLXWBo.jpg',2.9032473998964705,3,'2026-09-10',2,NULL,NULL),(9880,'公主日记','The Princess Diaries','15岁的高中生米亚（安妮•海瑟薇 饰）与母亲生活在美国，但她十分不自信，也常常遭到同学的嘲笑。就在她16岁生日那天，她与祖母（茱莉•安德鲁 饰）见面后发现这个优雅的女士是欧洲小国吉诺维亚的女王，米亚正是这个国度的公主。刚开始米亚十分不愿，在母亲的调解下米亚的态度才有所缓和。\r 　　为了可以顺利继承王位，女王不得不对孙女进行一系列的改变，令平时生活便不拘小节的米亚十分困扰，甚至跟好朋友之间也发生了冲突。米亚的身份被好事的同学揭露了，她一下子受到了媒体的高度关注。突如其来的一切让米亚想逃避一切，幸好在父亲的日记里，她重拾了自信。米亚成为了公主，也找到了自己想要的爱情。','She rocks. She rules. She reigns.',37000000,165335153,40.176265,6.5,1023,115,'2001-08-03','en','/qsoT62O7f7ttdGHbNCBlxHnLeKZ.jpg',3.498584872006424,3,'2026-09-10',2,NULL,NULL),(9882,'烈血天空','The Siege','海湾战争后，美国于1992年在伊拉克的南方守望行动中遭遇胡巴尔群楼爆炸攻击，美军将嫌疑组织首领绑架至美秘密调查。FBI探员安东尼•哈勃德（丹泽尔•华盛顿 Denzel Washington 饰）及阿拉伯语搭档弗兰克（托尼•夏尔赫布 Tony　Shalhoub 饰）负责调查纽约巴士自杀炸弹恐怖袭击过程中收到神秘讯息“放人”。CIA特工伊莉斯（安妮特•贝宁 Annette Bening 饰）坚称为恐怖分子办理学生签证入美的阿拉伯人萨米尔（塞米•鲍亚吉拉 Sami Bouajila）是自己重要线人，却不肯透露其他信息。随着恐怖袭击的升级，将军威廉姆•得弗罗（布鲁斯•威利斯 Bruce Willis 饰）奉总统之名进驻纽约对布鲁克林区实施军管，将所有青壮年阿拉伯人收监待审。军方对人权与民主的践踏激起纽约市民的强烈反感，示威游行与下一波恐怖活动的威胁让所有人进退两难……','On November 6th our freedom is history',70000000,116672912,20.089933,6,352,116,'1998-11-06','en','/f9D1KkfOBwd9oDyq7yovFFGOMve.jpg',3.1425529290549936,3,'2026-09-10',2,NULL,NULL),(9884,'间接伤害','Collateral Damage','戈登（阿诺·施瓦辛格）是一名勇敢而敬业的资深消防员，他工作出色，有着温柔的爱妻和活泼可爱的孩子，对戈登来说，生活中的一切都是那么安定和谐而美满，真是人生如此，夫复何求。然而，不幸却在戈登最没有防备的时候以他做梦都没想到的方式降临了——一伙哥伦比亚的左翼极端分子策划谋害哥伦比亚驻美国的大使，他们在大使外出的路上布置了威力强大的炸弹，意图将大使连同整个车队一起炸上天，在炸弹引爆的同时，恰巧经过这里的戈登的妻儿被不幸殃及，双双殒命，而后警方却只是以“因意外事故引起的间接伤害”为理由草草了解了案子。得知这个消息的戈登无疑是五雷轰顶，他无论如何也不能相信，自己温馨幸福的小家就这样在恐怖分子的炸弹下灰飞烟灭，几乎就在一转瞬间，他就失去了对他至关重要的一切，而随后警方的懦弱无能更让他无法接受，求助无门的戈登发誓要不惜一切代价寻求正义，即使追到天涯海角也要严惩罪魁祸首以告慰惨死的妻儿。 在他的不懈追查下，戈登很快就查出此次爆炸事件的主使者——臭名昭著的恐怖分子头子“豺狼”佩里尼（克利夫·柯蒂斯），并且还找到了佩里尼的妻子赛莱娜（弗朗西斯卡·内莉），但是他没想到的是，赛莱娜也正在苦苦追寻丈夫的下落，几经周折，赛莱娜和戈登结成了同盟，他们决定直捣黄龙，一起闯入位于哥伦比亚腹地的恐怖组织老巢…… 一番斗智斗勇、激烈火爆的较量之后，戈登终于制服了佩里尼，就在他将要手刃这个不共戴天的仇人时，却发现自己不得不去面对一个严峻的问题——这种以暴制暴的手段究竟意义何在？杀死佩里尼是否会招致更血腥更疯狂的报复？是否会有更多和自己妻儿一样的无辜者为此付出生命？','What would you do if you lost everything?',85000000,78382433,18.827753,5.5,427,108,'2002-02-06','en','/8djn1ej9x7NLqZwhEXYFNlKO0xJ.jpg',3.124592079569453,3,'2026-09-10',2,NULL,NULL),(9889,'情人眼里出西施','Shallow Hal','哈尔（杰克•布莱克 饰）的父亲竟然在临终前跟儿子说以后一定要找最美丽的女孩做终身伴侣。于是他开始上演追逐不同美女的戏码，可是他的相貌平平，遇到了不少挫折。早已过了而立之年的他仍不愿违背父亲的遗愿，直到他受到了某位专家的催眠，逐步改变他以貌取人的的毛病，他观赏美女的的眼光竟然开始了很大程度上的的下降，后来他甚至爱上了体重达到150公斤的露丝玛丽（格温妮丝•帕特洛 饰），哈尔全然不介意露丝玛丽笨重的身材，他感觉自己的女友是最善良的人，无可救药的彻底爱上了对方。\r 好友马里西奥不忍哈尔有个相貌如此不堪的女友，经想方设法要破除掉施用在哈尔身上的催眠术……','Are You A Shallow Guy?',40000000,141069860,29.854773,5.7,731,114,'2001-11-01','en','/jt48g6PeBgrPuIXhhpHRj3cd5M3.jpg',3.272231937646164,3,'2026-09-10',2,NULL,NULL),(9890,'复制娇妻','The Stepford Wives','当从曼哈顿搬到高尚住宅区斯戴佛之后，乔安娜（妮可•基德曼 饰）与丈夫（马修•布罗德里克 饰）都准备好了新生活的开始。乔安娜本想打好与邻居之间的关系，可是一众邻居太太的性格都将近完美，让乔安娜感到她们都无法靠近。这群有钱的太太中只有一名叫芭比的太太例外，她是乔安娜眼中的正常人，她俩也成为了好友。\r 其他太太们每天都忙着照顾自己的丈夫，对丈夫言听计从。乔安娜与芭比都感到十分好奇，为何邻居太太们似乎没有自己的脾气与喜好。\r 于是她们决定一查究竟，调查结果让她们惊讶不已，有钱的男人竟然把自己的太太变成了机器人，以求他们的妻子都千依百顺。这些一半人类一半机器的太太们背后有着“公开的秘密”，这样的黑手，也逐渐伸向乔安娜与芭比，她们将如何应对呢？','The wives of Stepford have a secret.',90000000,102000000,19.224754,5.4,334,93,'2004-06-10','en','/4wFarOGZpwJw6y2FVfa0dqFcTS6.jpg',3.0730103845472994,3,'2026-09-10',2,NULL,NULL),(9893,'彻夜狂欢','Sleepover','这年夏天，14岁的女孩茱莉（亚历克斯·维加 Alexa Vega 饰)结束初中学业，即将迎来崭新的高中生活。为了庆祝这一重要时刻，她邀请汉娜（迈克·布莱姆 Mika Boorem 饰）、法拉（斯科特·泰勒·坎普顿 Scout Taylor-Compton 饰）和扬希（凯莉·弗兰·奇德瑞斯 Kallie Flynn Childress饰）来家举行狂欢派对。她们穿起睡袍，大声说笑，随意摇摆，尽情吃着高热量食品。然而就在此时，她们接到学校内一伙女孩发来的挑战。在这个晚上，她们要进行一场寻宝比赛，获胜者将有机会和高中内最受欢迎的男孩共进午餐。为此，茱莉她们情愿放下好好学生的名头，展开一场彻夜大冒险……','The rules are set. The game is on.',0,0,5.842299,5.3,101,89,'2004-07-09','en','/w0kE8EufKNtYsliKWtsd4GJRH1b.jpg',2.8217419734300577,3,'2026-09-10',2,NULL,NULL),(9894,'王牌特派员','The Cable Guy','因和女友洛萍·哈瑞斯（莱丝莉·曼 Leslie Mann 饰）发生不快，房地产经营上史蒂夫·考维克斯（马修·布鲁德里克 Matthew Broderick 饰）被迫搬到一幢新的公寓。不久，有线电视安装人员杜哲（吉姆·凯瑞 Jim Carrey 饰）登门拜访。杜哲举止乖张，为人却颇为幽默开朗。两人由此成为好朋友，更相约外出游玩。在杜哲的指点下，史蒂夫成功赢回女友的芳心。然而杜哲似乎过于热情，她越来越多介入到史蒂夫的生活当中，令后者渐感烦躁和不安。史蒂夫开始有意识地远离这个不太正常的家伙，感觉被好友抛弃的杜哲由此暗升报复之心……  　　本片荣获1997年儿童选择奖最受欢迎男主角奖（Jim Carrey）。','There\'s no such thing as free cable.',47000000,102825796,19.525659,5.7,594,96,'1996-06-10','en','/1SMTOdeP8XYSUYcMuSbGWcavJPJ.jpg',3.2100416121478546,3,'2026-09-10',2,NULL,NULL),(9895,'年度人物','Man of the Year','多比斯（罗宾·威廉斯 Robin Williams）主持的脱口秀节目非常犀利，能旁征博引言辞刺骨地把美国总统们讽刺一番，把听众乐得心花怒放。甚至有听众建议他不如参选总统，一展身手。\r 　　多比斯的参选让他成为了草根阶层的代表，自然也获得了民众的大量支持。而且，多比斯拥有的杰出口才更是在辩论赛中占尽优势，令他在众多候选人中显得卓越不凡。大选结果让多比斯大为振奋——无背景无资历的他竟然以超过半数德票选获得总统之位。\r 　　选举期间，统计票数的程序员埃莉诺（劳拉·琳妮 Laura Linney）让多比斯暗暗动心。正是这个姑娘，在关键时刻发现统计系统出错，选举结果其实源于一个BUG……','Elections are made to be broken.',20000000,41237648,11.203335,5.8,129,115,'2006-10-09','en','/s1etp9ZqcRqZVfonrdFJbQ6mgk9.jpg',2.902235167144288,3,'2026-09-10',2,NULL,NULL),(9896,'亡命夺宝','Rat Race','赌场老板（约翰·克里斯 饰）选中了六个幸运儿参加一项竞赛。他们中最早到达银城火车站的人将得到储物柜里的200万美金，而比赛的规则就是没有规则。六个人偕同各自亲友，八仙过海，各显神通。  　　其实在这竞赛背后还有更大的赌博，几位富翁正以这些人作为他们赌博的对象。小人物为了两百万忙得不亦乐乎，大人物却正在幕后自鸣得意。  　　然而，竞赛的最后有了戏剧性的转折。','563 miles. 9 people. $2 million. 1001 problems!',48000000,85498534,18.60049,6,518,112,'2001-07-30','en','/8ghNCfFbCJjcNSz2K5jOC3eO6ZD.jpg',3.2198137305723984,3,'2026-09-10',2,NULL,NULL),(9899,'金牌制作人','The Producers','依据1968年的同名电影及2001年的同名百老汇歌舞剧改编而成。会计师雷欧·布鲁姆（马修·布罗德里克 Matthew Broderick 饰）来到纽约百老汇最糟糕的制作人迈克斯（内森·连恩 Nathan Lane 饰）的办公室为他处理帐务，无意中提及他可通过制作一部最失败的歌舞剧来贪污两百万美元投资。迈克斯说服了一直怀有制作人之梦的雷欧与他一同制作这台歌舞剧，他们采用了前纳粹弗朗兹（威尔·法瑞尔 Will Ferrell 饰）的笑话剧本《希特勒的春天》，雇用了臭名昭著的同性恋导演罗杰（加里·毕什 Gary Beach 饰）及助手卡门（罗杰·巴特 Roger Bart 饰），并找到了一位毫无表演经验的瑞士美女乌拉（乌玛·瑟曼 Uma Thurman 饰）兼当秘书和女主角。可没想到的是，这样一部铁定失败的闹剧竟意外大获成功……  本片被提名金球奖最佳歌舞剧及喜剧电影、最佳电影原创歌曲、最佳喜剧及歌舞剧男主角（内森·连恩）和最佳喜剧及歌舞剧男配角（威尔·法瑞尔），并获格莱美奖最佳电影电视或其他视觉媒体原创歌曲奖提名。 ©豆瓣',NULL,45000000,38058335,6.803965,6.1,151,134,'2005-12-25','en','/nG0Bix2SH2SQcbAIGhb6yqTG5UH.jpg',2.9395963309374955,3,'2026-09-10',2,NULL,NULL),(9900,'祖母的孩子','Grandma\'s Boy','阿莱克斯（艾伦·卡瓦特 Allen Covert 饰）本来有一份体面而又稳定的工作，还有幸福快乐的人生，但一场突如其来的变故将这一切都粉碎殆尽。如今，年近35岁的阿莱克斯在一家游戏公司从事电视游戏测试员的工作，和他一同工作的，都是小年轻，阿莱克斯必须铆足了劲，才不至于被这些年轻人抛在后面。好在阿莱克斯是一个机灵的男人，他总是有办法让自己成为公司里的焦点。 哪知道阿莱克斯的室友因为沉迷于去夜总会风流，欠下了巨额债务，连两人的房租都赔了进去，就这样，一夜之间，阿莱克斯成为了流落街头无家可归的流浪汉。好在很快，阿莱克斯就给自己找到了新的住所，然而让他没有想到的是，他的新同居人，竟然是一位名叫格雷斯（雪莉·琼斯 Shirley Jones 饰）的八十岁老太太。','A movie that proves you\'re never too old to come of age.',0,6538177,9.974681,6.6,220,94,'2006-01-06','en','/fSRdHBtisU0zhks4OjKezI3jnt7.jpg',3.06267961648148,3,'2026-09-10',2,NULL,NULL),(9902,'致命弯道','Wrong Turn','克里斯（Desmond Harrington 戴斯蒙•哈林顿 饰）接到一份紧急的采访任务，他必须在3个小时之内赶到美国北卡罗来纳州的罗利市。原本应该顺利的形成却被一起交通事故打乱，一辆运载化学品的车辆翻倒，导致高速公路大塞车。万般无奈之下，克里斯选择一条人烟稀少的小路行进。另一方面，杰西（Eliza Dushku 艾丽莎•杜舒 饰）、卡莉（Emmanuelle Chriqui 曼纽尔•克莉琪 饰）、斯科特（Jeremy Sisto杰瑞米•西斯托 饰）、埃文（Kevin Zegers 凯文•席格斯 饰）和弗朗丝（Lindy Booth 林蒂•布丝 饰）等5位好友驱车前往山中露营游玩。谁知汽车半路离奇爆胎，等待救援时汽车又被突遇险情的克里斯撞上。众人结伴去附近求助，却未料到走入了变态食人魔所设下的重重陷阱……','It\'s the last one you\'ll ever take.',12600000,28650575,33.555764,6,635,84,'2003-05-30','en','/nwYnlNBb8qmcyujxDQrM3fDapzX.jpg',3.296425203872848,3,'2026-09-10',2,NULL,NULL),(9903,'骗局','The Hoax','无人不知的美国大亨霍华德·休斯在晚年过起了隐居生活，在人们的心中愈加神秘，然而有关他的任何一点新闻都会牵动美国人的神经。  　　这次引起轰动的是一个小作家艾尔文（理查·基尔），他声称得到授权为休斯写回忆录。新闻每天追踪着关于休斯的各种消息，休斯的传记也如约出版。艾尔文因此一夜致富，闻名全美。就在这一切进行的如火如荼时，艾尔文和他的亲友却感到惴惴不安，因为一切都是假的。他们根本没见过休斯，更没有什么授权，他们只是为了一个谎又扯一个谎，最终织成了弥天大谎。或许更让艾尔文悲哀的是，他已经难分生活的真实与虚假，他编造着别人的生活，也让自己走入了谎言的陷阱。','Never let the truth get in the way of a good story.',25000000,11772461,5.073536,6.4,60,116,'2006-10-14','en','/u5KESAGmNa5NLsSbpHVUDWT4ENR.jpg',2.7445974669353097,3,'2026-09-10',2,NULL,NULL),(9906,'别惹蚂蚁','The Ant Bully','想象下你是个在校没朋友，没人陪你玩，又被恶霸欺负的小孩？这是件多么可怕的事。在华纳兄弟出品的动画片《别惹蚂蚁》里的主人公就遇到这种状况。故事根据童话作家约翰·尼科尔(John Nickle)创作的同名儿童小说改编,讲述刚搬家的卢卡斯,在学校没朋友，又被邻居恶霸欺负，只好把怒气出在蚂蚁上,破坏他们的巢穴，不料蚂蚁起来报复，用一把神奇缩小枪，将卢卡斯变成蚂蚁般大小，并把他带回巢穴一同生活，经过这次，卢卡斯学会了宽容与同情，友情的真谛和欣赏和敬畏自然本身。','The battle for the lawn is on.',50000000,55181129,20.239061,5.5,366,88,'2006-07-27','en','/cGd5bwtCSnf01FzJf2PDhDdCINu.jpg',3.1008848105474276,3,'2026-09-10',2,NULL,NULL),(9907,'疯狂农庄','Barnyard','农场里的小动物温顺乖巧。听话的小狗，可爱的小鸡，成群结队的绵羊，在农夫的细心照顾下，健康的生活着。可是，每当农夫不在的时候，他们就会突然站起来，疯狂玩闹。唱歌跳舞，喝啤酒，开Party，他们甚至会去模仿人类，捉弄人类。奶牛奥蒂斯（Otis）就是他们当中最捣蛋的一个，竟玩起了高山滑雪。奥蒂斯的父亲本（Ben）是小动物们的领袖，每天兢兢业业的为他们站岗放哨，保护小动物不受野狼的袭击。大家都敬畏并信任他。\r 　　本一天天的变老，他希望儿子奥蒂斯能像自己一样，担起责任，保护好农场。可是奥蒂斯玩心太重，总是令本失望。一次，奥蒂斯为了一参加个Party，求父亲替他站岗。也就是这次，本为了保护小鸡，牺牲了自己。奥蒂斯深深地自责，一度灰心丧气。本在天上看着奥蒂斯，看着他努力去做好领袖，变成真正的男人','What happens in the barn stays in the barn',51000000,72779000,10.430832,5.3,225,90,'2006-08-04','en','/qB9jFInwUEb2VLhMeKQX17Vdrnp.jpg',2.977132481554006,3,'2026-09-10',2,NULL,NULL),(9912,'世上最快的印第安摩托','The World\'s Fastest Indian','电影改编自世界著名摩托车手伯特·孟若的生平，真实而又生动的再现了一代传奇车手跌宕起伏的一生。故事开始于1899年，孟若降生到了这个世界上，从小体弱多病的他甚至被医生下达过“死亡通知书”，但幸运的是，孟若还是顺利的长大了。1915年，孟若有了自己的第一辆摩托车，从此开启了与风竞速的生涯，直到七十二岁那一年，孟若依然没有放弃自己曾经的梦想。他改装了二十年代购入的印第安牌侦查摩托车，从新西兰骑往美国。一路上，孟若结识了易装癖者蒂娜、寡妇艾达、销售员佛兰多等一干有趣的朋友们，在他们的帮助和鼓励下最终创下了新的世界纪录。',NULL,25000000,0,8.450513,7.3,166,127,'2005-10-12','en','/vUIwPFAAXeCUuS040uGC0xSatcG.jpg',3.0305547444977496,3,'2026-09-10',2,NULL,NULL),(9913,'万能钥匙','The Skeleton Key','年轻的姑娘卡罗琳（凯特•哈德森 Kate Hudson 饰）受雇于老妇人维奥莱特（吉娜•罗兰兹 Gena Rowlands 饰），前往她家照顾她卧病在床的丈夫本（约翰•赫特 John Hurt 饰）。维奥莱特的大房子坐落于以神秘习俗和宗教仪式闻名的地区，卡罗琳刚到这里就觉得阴森诡异。随着日子一天天过去，卡罗琳渐渐对这件大房子和古怪的维奥莱特起疑。一次偶然，她从维奥莱特那里得到了一把万能钥匙，用它可以打开这座大房子的所有房间。当卡罗琳走进了隐藏在顶楼的房间时，她看到了令人惊悚的一幕，直觉告诉她，本的卧病在床和维奥莱特以及这间房间有着莫大的关系，她决心揭开这个迷！','Fearing Is Believing',43000000,91974818,29.105407,6.4,573,104,'2005-07-29','en','/i6RIL8jjDrT93fgObjg1Htku9DP.jpg',3.317681112905523,3,'2026-09-10',2,NULL,NULL),(9916,'最后的食罪人','The Last Sin Eater','最后的食罪者灵感来源于Francine Rivers的小说，故事发生在北美阿巴拉契亚山脉的一个威尔士移民村落。十九世纪五十年代，旧的迷信习俗仍然支配着大部分村民们的思想，甚至有人利用这些迷信的仪式掩盖神秘的过去。十岁的女孩Cadi (Liana Liberato) 在祖母的葬礼上第一次接触到食罪者(Peter Wingfield)，一个被黑色兜帽和斗篷覆盖着的神秘男人，看着他缓缓地匍匐到祖母的尸体上，饮下她的罪，从而接收死者生前不光彩的一切，并使之得到救赎。从那一刻起， Cadi决定去寻找神秘的食罪者，她要让食罪者的魔法清除自己身上的罪——对于妹妹的去世而产生的强烈罪恶感，对于使家人卷入悲伤的深深自责。在寻找食罪者的旅程上，Cadi与一个思想不着边际的男孩Fagan (Soren Fulton)成为了伙伴，虽然途中Fagan的变态父亲(Stewart Finlay-McLennan)不停地躲在暗处阴险地跟踪着他们， Cadi依然固执地寻找着食罪者，然而最终的食罪仪式能否让她减轻罪恶感呢，到底灵魂能否通过外界的干涉而得到救赎呢？',NULL,0,0,2.371477,6.2,11,117,'2007-02-09','en','/nSFmT13VqhdVqRhU08ADMxy8cGX.jpg',2.37917995000138,3,'2026-09-10',2,NULL,NULL),(9918,'光荣之路','Glory Road','故事发生在1965年的美国德克萨斯州，当时的美国社会面临着黑白种族冲突对立的状况。唐·哈金斯(乔什·卢卡斯 饰)是一个年轻气盛的白人篮球教练，由于他在掌管女子篮球队方面的出色成绩，领导决定安排他执教属于NCAA（全国大学生体育协会）的西德州联队(Texas Western)。然而新官上任接到的是个烂摊子，这支篮球队不但基础很差，而且白人球员根本不听一个前女篮教练的指挥。哈金斯是一个具有坚定意志的人，他决心在NCAA里面闯出名堂，而且他的思想非常开明，他并不以肤色区分天才。　　于是哈金斯组织了一群非常有篮球天分的黑人学生作为西德州联队的核心，开始了他艰苦的光荣之路。这些黑人球员连真正的篮球与街球的区别都不知道，而且他们对种族问题极度敏感，可是这些内部问题与外部的大环境相比根本算不得什么，整个学校的人从上到下都认为哈金斯疯了。　　经过一个训练期的接触，哈金斯坚定的信心感染了球队里的每一个人，这支五名黑人先发的球队一路披荆斩棘，直指决赛，最后在马里兰大学著名的Cole Field House击败白人先发的肯塔基，获得了1966 NCAA篮球比赛总冠军，当时肯塔基先发球员里就有湖人、尼克斯和热火的教头帕特·莱利(韦斯·布朗 饰)。这场比赛结果不仅捍卫了黑人的尊严，更具有划时代的意义，它使美国大学篮坛正式进入黑白共存的时代。','The incredible story of the team that changed the game forever.',0,42647449,8.305085,7.2,144,118,'2006-01-13','en','/bGRSV5tStxDNPRLCewnOeeiZzrY.jpg',2.9872810587177705,3,'2026-09-10',2,NULL,NULL),(9919,'十日拍拖手册','How to Lose a Guy in 10 Days','美女安蒂(凯特•哈德森饰)是一家时尚杂志的专栏作家，负责撰写“恋爱指南”之类的情感文章。某天，主编给她派了一个棘手的任务：搜集怎样甩掉男人的第一手资料。因此，安蒂必须在十天之内找到一个男朋友，然后再甩掉他。　　安蒂看上了在广告代理公司工作的本杰明(马修•麦康纳饰)，磨刀霍霍，准备实施她的计划；谁知道，本杰明是一个典型的花花公子，游戏人间的他正在和老板打赌：十天之内让一个女人彻底爱上他。　　干柴烈火，一拍即合，他们开始了真真假假的爱情游戏。','One of them is lying. So is the other.',50000000,177371441,23.854701,6.3,850,116,'2003-02-07','en','/bYWx7WVZnDnxP2JJfSjEC2Recv1.jpg',3.3835097250055757,3,'2026-09-10',2,NULL,NULL),(9920,'致命紫罗兰','Ultraviolet','未来世界，军方研制强化战士作战能力的药剂，却弄巧成拙导致大量民众沾染失败的实验制剂，并由此诞生了身体异于常人的生化人群体。军方兴建了庞大的隔离建筑，同时研发出对付生化人的最终武器，于是生化人组织派出女战士紫罗兰（Milla Jovovich 饰）潜入军方内部，用暴力方式将最终武器抢夺。紫罗兰难耐好奇，于路将最终武器包装打开之后发现里面居然是一名男童（Cameron Bright 饰），原来男童拥有可以消灭生化人的血液抗原，紫罗兰认为血液抗原亦可使生化人返回人类形态，不满组织的粗暴解决方式遂决意背叛，携自称“6号”的男童踏上了躲避军方和生化人组织的亡命之旅。而男童的背后，还有更大的秘密尚未揭开。','The blood war is on.',30000000,31070211,15.89534,4.8,458,87,'2006-03-03','en','/rG89DKg8sqnjfOFijELLLBCn2N2.jpg',3.048984241131941,3,'2026-09-10',2,NULL,NULL),(9922,'邮差','The Postman','2013年，其时地球已被一场毁灭性的战争变成一片荒原。一些小国或者说小村镇散布在现在的美国土地上，一个流浪汉被统治者投进了纳粹式的集中营。从集中营里逃出后，这位人称“莎士比亚”的流浪汉意外地发现一包过期邮件和一身邮递员的制服，为了糊口，他开始来往于各城镇之间，谎称整个国家的公共服务系统正在重建，而自己是邮递员。出乎意料地，居民们收到信后欣喜若狂并接受了他的谎言，很快，第二，第三个邮递员在他的影响下诞生了……“莎士比亚”陪同女子Abby隐居了一段时日，等他重新出现时，他发现社会上已经有了一群邮递员队伍，并且奉自己为精神领袖。他不情愿地接受了这个角色，并带领大家与极权统治者展开斗争，夺回失落的美国梦……','The year is 2013. One man walked in off the horizon and hope came with him.',80000000,17626234,14.564667,6.1,299,177,'1997-12-25','en','/qo4UxbdMcR6VgvVV4wodSKfWwYu.jpg',3.104510838674478,3,'2026-09-10',2,NULL,NULL),(9923,'多米诺','Domino','本片根据英国演员劳伦斯·哈维（Laurence Harvey）的女儿多米诺·哈维（Domino Harvey）的亲身经历改编。多米诺（凯拉·奈特利 Keira Knightley 饰）从小过着奢华富足的生活，即使在成为超模之后也不改其叛逆野性，在一次偶然看到了报纸上招募“赏金猎手”的广告后，加入了由艾德（米基·洛克 Mickey Rourke 饰）和乔克（埃德加·拉米雷兹 Edgar Ramirez 饰）组成的南洛杉矶赏金猎手团，因表现突出，甚至获得了 “年度赏金猎手”的称号，并签约了某电视台的真人秀节目。多米诺及团伙的雇主是洛杉矶律师克莱尔蒙特（德尔罗伊·林多 Delroy Lindo 饰），他的情妇之一，在洛杉矶车辆管理处工作的拉蒂纱（莫妮克Mo\'Nique 饰），因孙女急需钱看病，便与克莱尔蒙特共同设计了一个千万美元抢劫计划，打算骗取佣金；却没想到计划赶不上变化，一个小意外却造成了大纰漏……本片预告片获美国金预告奖最佳声音剪辑奖。','Heads You Live... Tails You Die.',50000000,22944502,18.394571,6,444,127,'2005-09-22','en','/pZdIfYkM5kV5BaUDYzwzgmpUxno.jpg',3.1871858036362464,3,'2026-09-10',2,NULL,NULL),(9928,'Robots','Robots','Rodney Copperbottom is a young robot inventor who dreams of making the world a better place, until the evil Ratchet takes over Big Weld Industries. Now, Rodney\'s dreams – and those of his friends – are in danger of becoming obsolete.','You can shine no matter what you\'re made of.',75000000,260696994,29.558157,6,1333,91,'2005-03-10','en','/m8Ju6kquE5sqyDEjrmUGm1GNHNr.jpg',3.4420319603140235,3,'2026-09-10',2,NULL,NULL),(9930,'法网神鹰','Legal Eagles','一向公正的地方检察官汤姆罗根在处理雀尔喜窃盗名画案时，发现整个案件并不单纯，似乎有官员介入此案；经过暗中调查后，事实的真相渐渐浮现，而他也面临突来的危机...','Tom Logan has a law partner who put a dog on the witness stand. A client who can\'t enter a room without a crime being committed. And a case that could turn out to be the murder of the year. His.',0,0,7.519433,5.8,51,116,'1986-06-18','en','/RH9bXtsxy12YKXqvAwKd5XmGvq.jpg',2.7028235152820073,3,'2026-09-10',2,NULL,NULL),(9932,'老大靠边闪2：歪打正着','Analyze That','电影介绍 1999年的《老大靠边闪》(“Analyze This”)曾在票房榜上创造了奇迹，取得了1亿70万美元的票房佳绩。本片故事延续上一集。老大保罗-维蒂(Paul Vitti，罗伯特-德-尼罗饰，Robert De Niro)在纽约辛辛监狱的刑期就要期满了。但负责监视他的联邦调查局特工却倍感困惑，最近他们看管的这个纽约最臭名昭著的黑帮老大，在他关押的小屋里日复一日、神经般地踱来踱去，当然偶尔也会唱几句影片《西区故事》(“West Side Story”)中的主题曲。  　　维蒂是因为他的对头家族又向他发出死亡威胁而精神崩溃？还是想以他这种古怪的举止而早日离开监狱？联邦特工被弄得是一头雾水，维蒂以前的心理医生本-索贝尔(Ben Sobel，比利-克里斯特尔饰，Billy Crystal)也被召来，检查后也不明所以。  　　上一次，索贝尔给维蒂治疗时就曾想设法找出他日益焦虑的原因，但是毫无结果。要想找出维蒂脑海里潜伏着的病魔，让他恢复正常，这需要时间。而此时此刻，索贝尔并不想浪费时间，特别是对于维蒂，尤其是现在。  　　事实上，索贝尔自己也遇到了麻烦。他的父亲刚去世不久，使他陷入了个人生活和职业生涯的个性转变期。此外，索贝尔知道如果他让那个令人捉摸不透的维蒂再次出现在自己生活中的话，他的妻子劳拉-麦克纳马拉-索贝尔(Laura MacNamara Sobol，莉萨-库德劳饰，Lisa Kudrow)一定会火冒三丈。  　　但是，维蒂获得了假释，并且是在索贝尔的担保下，再次成了他的病人--更糟的是成为了他们家的房客，这个心不甘情不愿的心理医生发现他根本没有选择。为了使他的生活恢复以往的平静，索贝尔必须帮助这个黑帮老大恢复心智，找到一份合适的工作，回到正道上来。  　　终于，维蒂似乎开始认真对待治疗了。索贝尔也认为自己开始相信维蒂了。但是如果象卢-伦奇(Lou The Wrench)这样的家伙不断出现的话，他还能保持这份毅力吗？','Back in therapy',60000000,55003135,21.08952,5.7,380,96,'2002-12-06','en','/Yya8tU4sfI2H9CW1LXHkpoBLJQ.jpg',3.1299815275498015,3,'2026-09-10',2,NULL,NULL),(9942,'大联盟','Major League','克里夫兰红人队的老板想将球队搬去迈阿密，于是想尽办法要球队输，以达成和克里夫兰解约的目的，乌合之众的球员该如何是好呢？','A comedy with bats and balls.',11000000,49797148,7.559192,6.6,217,107,'1989-02-16','en','/ypUedY9zX4nGGf1lQv1UGc8PhPA.jpg',3.0538379265136575,3,'2026-09-10',2,NULL,NULL),(9944,'塘鹅暗杀令','The Pelican Brief','两名高等法院的法官遭杀手谋杀，法学院高材生达比随后开始调查此案，起草一份该案的报告，名为《塘鹅报告》。达比找到了记者格兰，因为他是最后一名见到其中一名法官的人，希望能得到他的帮助调查此案。一天格兰接到了一个神秘人来电，此人自称知道谁是该案凶手，格兰跟踪到了此人，可惜未能拦下他。此时，总统暗中命令相关人士不要插手此案。格兰由此起疑，随后调查到了总统和马氏集团关系密切，而且一切证据都表明，马氏与两位法官的死有着千丝万缕的关系！','Two Supreme Court Justices have been assassinated. One lone law student has stumbled upon the truth. An investigative journalist wants her story. Everybody else wants her dead.',45000000,195268056,17.923254,6.3,371,141,'1993-12-16','en','/gISYIA1R6W3Y3b2bxAz6axEUgNy.jpg',3.1789645862698834,3,'2026-09-10',2,NULL,NULL),(9945,'够僵行动','Vampires','吸血鬼猎杀者杰克（詹姆斯•伍兹 James Woods 饰）有着不同寻常的童年，他亲手杀死了变成吸血鬼的父亲，从小被教会养大。杰克受梵蒂冈教廷委派，在美国猎杀吸血鬼王华生，华生本是一名神父，在七百年前化身吸血鬼，是威力惊人的鬼王始祖。对华生一无所知的杰克小队在任务中损失惨重，只有杰克和一名队员侥幸逃生，华生在屠杀杰克队员的过程中咬啮了一名玩伴女郎卡莲娜，因被吸血鬼咬啮的人在48小时之内可以维持人类思维并通灵吸血鬼王，杰克将卡莲娜带走以便追踪鬼王。教会方面为杰克派来了新的向导——亚当神父，杰克始获悉鬼王的终极目的是夺取圣物十字架，以便能够在阳光下生活。现在有希望能阻止鬼王的人，只有杰克……','From the Master of Evil. Comes a New Breed of Terror',20000000,0,17.016284,5.8,255,108,'1998-04-15','en','/jafpmJcmsmt3rQuIWvKNivSMlt7.jpg',3.05245347009557,3,'2026-09-10',2,NULL,NULL),(9946,'魔鬼末日','End of Days','1979年，罗马梵蒂冈教廷意识到和恶魔撒旦有着莫大关系的一名女婴诞生在纽约，二十年后，距离本世纪还剩最后三天的12月28日，撒旦（加布里埃尔·伯恩 Gabriel Byrne 饰）以一名人类银行家的肉身重现人间，丧失了妻女的前任警察杰瑞克（阿诺·施瓦辛格 Arnold Schwarzenegger 饰）和自己的安保团队受雇于伪装的魔鬼，为其提供保护。不久一名神父冒死狙杀撒旦，不幸失败，他在临死前向布瑞克提出警告。布瑞克与同伴按照神父留下的线索找到了女子克里斯汀（罗宾·汤尼 Robin Tunney 饰），得知她是命中注定要与撒旦结合的女性，如果撒旦能在千禧之夜和克里斯汀发生关系，那就意味着世界的毁灭。布瑞克决定不惜一切代价以人类的身份阻挡撒旦…','Prepare for the end.',100000000,211989043,20.652943,5.5,482,121,'1999-11-24','en','/wGaP6zaSBKV0JIC9IPVmaj5nzJT.jpg',3.1497481851104276,3,'2026-09-10',2,NULL,NULL),(9947,'艾丽卡','Elektra','从创世之初开始，正邪两种力量间的争斗就没有终结，他们一方修炼能够起死回生并预见未来的法术，另一方则结成组织不停寻找终极武器的下落。现在，一个女人的出现将影响正邪间的势力平衡。女杀手艾丽卡的父母数年前被人杀死，而她自己也不幸身亡，幸有掌握复活能力的导师将她救活，又传授给艾丽卡诸多本领。艾丽卡在执行一次任务期间，和相邻的马克与阿碧父女结识，这对儿父女令艾丽卡回想起自己曾经拥有的家庭之爱，然而任务目标揭晓，雇主的目标居然是马克父女。艾丽卡为了保护父女俩不惜与杀手集团作战，因艾丽卡阻扰而愤怒的“The Hand”派出最强组合，追杀艾丽卡等人……','Looks can kill',43000000,56681566,28.613892,4.8,575,97,'2005-01-13','en','/oSNlfW18rTFnJcM0IwXtMiMQm9d.jpg',3.105638798620742,3,'2026-09-10',2,NULL,NULL),(9950,'判我有罪','Find Me Guilty','经过了数年的联合调查，联邦政府欲将素有恶名的黑手党卢切斯家族彻底拿下，大规模扫黑行动后，20名家族成员因76项罪名指控而被押上法庭，其中分管新泽西州的头目杰基·迪诺西奥(文·迪塞尔饰)被判入狱30年，出于对联邦司法系统的蔑视，杰基放弃了做污点证人以获减刑的诱人条件，“宁肯坐牢千年，也不愿出卖从小并肩长大的兄弟”，他断然拒绝出卖同道的黑帮分子和自己的家族，坚持挺身而出为自己做无罪辩护，控辩双方均为此惊诧不已。“我不是黑帮分子，我是爱讲笑话的喜剧明星”，贩毒越货、无法无天的杰基在法庭上巧舌如簧，幽默十足，在竭力开脱罪行的同时，时不时地让检控方陷入尴尬，并无多少学识但极具街头生存智慧的杰基俨然成为了法庭中的焦点，在所谓的义气与忠诚面前，他无悔无畏，固守着自己的道德小宇宙……审判陷入漫长的拉锯状态，最终横跨了1987～88两个年度，持续了21月之久，创下了多项庭审纪录：20名被告配备了20名辩护律师(每人一位)、8个陪审团交替上阵(杜绝超长的审判而致的行贿可能)及史无前例的超长结案陈词(其中一位辩护律师的结案陈词居然宣读了5天)……',NULL,13000000,2636637,12.321302,6.5,138,125,'2006-03-16','en','/8M0dkX7jOor7exKor1txoUl9Ynu.jpg',2.9519445307462395,3,'2026-09-10',2,NULL,NULL),(9952,'重见天日','Rescue Dawn','出生在德国的迪特•丹格勒（克里斯蒂安•贝尔饰）自幼就梦想着驾驶飞机翱翔天际。长大后，他随家人移民至美国，加入军队成为了一名真正的飞行员。随后迪特便随海军投身越南战场。赶往执行任务的途中，迪特飞机不幸被越南军队的地面炮火击落。侥幸逃脱一死的他，却最终被敌人俘获，饱受严刑折磨。迪特被押至设在老挝的战俘集中营，那里还有几个美国军队的同伴。看守敌人给予他们非人待遇，迪特还未坐定就暗下决心要逃跑，但周围的同伴吉恩（杰瑞米•戴维斯饰）、杜恩（史蒂夫•茨恩）等并不那么认为，他们没多少信心。在一番劝说下，迪特精心策划，要在雨季来临时越狱。他们要面对是无边丛林、饥饿、野兽，还有不知道在何处的越南人……','A true story of survival... declassified.',10000000,7177143,17.078656,6.9,336,126,'2006-09-09','en','/86QE5FNqKhAPZiV9EM2zQvSC4Ft.jpg',3.211173222328772,3,'2026-09-10',2,NULL,NULL),(9954,'魔界契约','The Covenant','数百年前，在欧洲有一些拥有神秘力量的人群，他们被视为邪魔遭到绞杀，不得不逃亡美洲大陆。十七世纪，拥有魔力的五大家族联合，开辟了伊普斯维奇殖民地，他们为自保互相订立契约，以普通人的状态隐匿在人群中。五大家族的四名传人——凯勒布（史蒂芬•斯特雷 Steven Strait 饰）、里德、泰勒、伯格年龄相仿互相交好，他们的小集团是学校中的焦点，转校生沙拉（劳拉•拉姆齐 Laura Ramsey 饰）属意低调温顺的凯勒布，尝试着接近凯勒布却被恐怖的幻象困扰。同时，年满十八岁的凯勒布即将获得力量的升级，同伴里德出于嫉妒而敌视凯勒布令小团体出现了裂痕，学校中其他学生的意外身忙和陌生人科林斯试图接近小团体令凯勒布等人自感陷入了一场阴谋……','Only the power of Hell can help them.',20000000,37597471,15.804814,5.2,288,97,'2006-09-08','en','/bKLtDhcdbvdqfS59N0o2AeUnUrt.jpg',3.0227578673324755,3,'2026-09-10',2,NULL,NULL),(9955,'冰刀双人组','Blades of Glory','你想不到，花样滑冰赛场上竟然有如此搞笑的溜冰表演。查兹（威尔·法瑞尔 Will Ferrell 饰）摇滚味十足，耍弄着喷火的伎俩，一举一动都赢得粉丝们的狂热支持，整个场地都变成了他轻松驾驭的舞台。本来胜券在握，却万万想不到对手吉米（乔恩·海德 Jon Heder饰）同样实力超群。别小看吉米一副娘娘腔的打扮，优雅的气质和舞步可是相得益彰。既然两人都平分秋色，大赛决定实行双冠军。这可激怒了二人，他们当场斗殴，把赛场弄得一片混乱——当然，后果严重极了。他们被取消了终身的比赛资格。  两个滑冰王子从此上不了赛场，各自谋生，状况相当黯淡。二人的内心还是想收复失地，卷土重来，然而禁赛规定又让他们无计可施。可是，转机到了，他们发现可以建立起一对男子双人滑组合，就可以重归赛场。这无疑意味着，查兹和吉米要最大限度的化解宿仇，冰释前嫌，在二人组里默契配合，才能重现赛场辉煌。  果然，祛除心病后，这对组合屡屡出奇制胜，在赛场上的表现可谓笑料连连。','Kick Some Ice.',53000000,0,19.412028,5.9,569,93,'2007-03-30','en','/yclY3zyzrL1MS9b6Eygs9ks0ZTY.jpg',3.2280883545724812,3,'2026-09-10',2,NULL,NULL),(9957,'板凳队员','The Benchwarmers','园艺工盖斯、报童克拉克、音像店职员里奇是3个二十年来从没上过棒球场的废柴，除了盖斯技术还可以外，另外两人则是彻彻底底的运动白痴。他们童年时都饱受其他小孩的欺负，即使成年后情况也没有任何改观。盖斯偶然帮助了与他们有着同样经历的小胖子纳尔森，纳尔森的老爹迈尔（Jon Lovitz 饰）是一个坐拥几十亿资产的富豪。为了让儿子在健康快乐的环境中成长，迈尔决定出资帮助三人以及纳尔森组建一支球队进行全国巡回挑战赛，一方面为了打败那些臭名昭著爱欺负人的球队，一方面帮助所有的失败者重拾信心。盖斯等人自此开始全新的人生……','Get off the bench and get into the game.',0,0,6.74556,5.2,242,80,'2006-04-07','en','/5yMPCr4qhuNg6fT538xicHaMaG7.jpg',2.97371952960163,3,'2026-09-10',2,NULL,NULL),(9962,'麦田守望的女孩','The Good Girl','贾斯汀（詹妮弗·安妮斯顿 Jennifer Aniston 饰）和菲尔（约翰·C·赖利 John C. Reilly 饰）是一对结婚多年的夫妻，两人的感情早已名存实亡，菲尔沉迷于毒品和酒精之中，整天和损友布达（蒂姆·布雷克·尼尔森 Tim Blake Nelson 饰）厮混在一起。毒品的副作用让菲尔患上了不育症，贾斯汀想要成为一个母亲的愿望被无情的剥夺了。一个名叫霍尔顿（杰克·吉伦哈尔 Jake Gyllenhaal 饰）的年轻男孩的出现吸引了贾斯汀的注意，霍尔顿特立独行的生活方式让贾斯汀深深的为其着迷，随着时间的推移，他们之间的关系终于超越了单纯的友谊。布达发现了贾斯汀和霍尔顿之间的私情，于是开始了对于贾斯汀的漫长的敲诈，更糟的是，在此节骨眼上，贾斯汀发现自己有喜了。','It\'s her last best chance... is she going to take it?',8000000,16856124,9.799177,6.1,181,93,'2002-01-12','en','/2yTRy45D5HuQORJjtbOVS7WLnRP.jpg',2.9854485360778003,3,'2026-09-10',2,NULL,NULL),(9963,'亡命感应','Premonition','琳达（桑德拉•布洛克 Sandra Bullock 饰）有着一个看似幸福的家庭——漂亮的房子、两个女儿和丈夫吉姆（朱利安•麦克马洪 Julian McMahon 饰）。然而当有一天，琳达一觉醒来，马上被告知这家庭的支柱，丈夫吉姆已经死于一起交通事故。悲痛万分的琳达想都不敢想失去了吉姆以后的生活。这一夜，她在哭泣中睡去。  第二天一觉醒来，琳达赫然发现吉姆还好好的睡在自己的房间！迷惑不解的琳达只好将这一切都当作是自己发过的一场噩梦。但明天一觉醒来，却又发现自己不得不同母亲一起出席丈夫的丧礼！琳达彻底迷惑了，她似乎在不同的时空中来回穿梭：星期四，星期一，星期六，星期二……','Reality is only a nightmare away',20000000,84146832,22.049787,5.8,381,96,'2007-02-08','en','/fPT0VFIX688lXqcqvfgGxpxvalK.jpg',3.1429734215770484,3,'2026-09-10',2,NULL,NULL),(9969,'闪亮的圣诞节','Deck the Halls','斯蒂芬（马修·布罗德里克 Matthew Broderick 饰）循规蹈矩一板一眼的过了一辈子，早就已经习惯并且十分享受一成不变的生活。对于圣诞节，斯蒂芬也是一个保守主义者，有着自己根深蒂固的节日习俗，不能忍受分毫的改变。  　　某一天，斯蒂芬有了一个名叫丹尼（丹尼·德维托 Danny DeVito 饰）的新邻居。这个男人的个性和斯蒂芬有着天壤之别。丹尼向来自由自在，随心所欲，不按常理出牌，脑袋里一堆奇思妙想，并且非常热衷于将这些想法变为现实。圣诞节将近，丹尼竟然决定建造一个彩灯世界，这可不是一般的彩灯世界，丹尼的彩灯世界，要大到在外太空都能看得清清楚楚。眼看着丹尼开始着手建造他的白日梦了，斯蒂芬急坏了。','There glows the neighborhood',0,47231070,5.952527,5.1,109,93,'2006-11-22','en','/smJDzhYGhl6j9OrucsB7IkMNy82.jpg',2.828535133119984,3,'2026-09-10',2,NULL,NULL),(9975,'好奇的乔治','Curious George','影片改编自童书故事《好奇小猴乔治》，乔治是一只生性好奇的小猴子，因被一顶黄色的大草帽所吸引，从而来到了喧嚣的都市，本性善良与机智的他总是闯下无心之祸，但每一次都能化险为夷，让人捏把冷汗的同时不禁会心一笑。','Get Carried Away With The Cutest Little Monkey Around!',50000000,69834815,9.894346,6.2,106,86,'2006-02-10','en','/7SpokDLiRHON9H36GdlF7vWKOm6.jpg',2.8744054036121045,3,'2026-09-10',2,NULL,NULL),(9978,'风暴突击者','Stormbreaker','亚历克斯（亚历克斯·帕蒂弗 Alex Pettyfer 饰）自幼失去了父母，他的整个童年时代都是和叔叔伊恩（伊万·麦克格雷格 Ewan McGregor 饰）一起度过的，不幸的是，伊恩叔叔也因为一场可疑的意外离开了亚历克斯。\r 布朗特先生（比尔·奈伊 Bill Nighy 饰）和琼斯夫人（苏菲·奥康内多 Sophie Okonedo 饰）出现在了亚历克斯的面前，他们向他传达了一个惊人的消息。原来，表面平凡的伊恩一直以来都过着双重生活，背地里，他是一名为英国情报组织MI6工作的间谍。就这样，亚历克斯被迫成为了叔叔的接班人，等待着他的，不仅是十分艰苦的训练，还有异常危险的任务，从小就接受了严苛训练的亚历克斯能够胜任吗？','Rule the school. Save the world.',40000000,23937870,16.282962,5.1,213,93,'2006-07-21','en','/fG5quXbVBt3HBObfixI36wQkTcG.jpg',2.9674515523460183,3,'2026-09-10',2,NULL,NULL),(9981,'足球老爹','Kicking & Screaming','这是一场老爹和儿子的较量。为了荣誉，也为了亲情。\r 　　菲尔•韦斯顿(威尔•法莱尔饰)，与芸芸众生一样，是个平凡的人。日出而作，日落而息，每天周而复始，没有什么激情。而他的老爸巴克(罗伯特•杜瓦尔饰)却是个活力四射的老头，无论做任何事情，巴克都一定要赢。老爸瞧不起生活没有追求儿子，而儿子又总是苦恼于老爸争强好胜所带来的麻烦。两人的关系视同水火。\r 　　这一切，被菲尔小儿子山姆(迪伦•迈克拉林饰)学校里的一场足球赛打破了。在儿子的请求下，菲尔决定去作儿子足球队“猛虎队”的教练。冤家路窄，“猛虎队”的劲敌联赛冠军“勇士队”，刚好由老爸巴克执教。巴克一次又一次挑战菲尔，终于激起了他的怒火。一场空前精彩的球场较量，开始了……','One man could lead this team to glory. . . That man was busy',45000000,56070433,8.99269,5.6,176,95,'2005-05-13','en','/4erPZ5V0yzNXRB2IcypOACMEgOA.jpg',2.9483844056925586,3,'2026-09-10',2,NULL,NULL),(9982,'四眼天鸡','Chicken Little','小鸡玛德机灵聪明，可是一直胆小怕事，戴着一幅笨重的大眼镜常常受到朋友们的捉弄和讥笑。一天它看到了天上忽然落下了一块碎片，以为是天要塌下来了，它到处惊慌的通知大家，一如既往惹来了众人的嘲笑。回到家里也只有爸爸与好朋友的鼓励。它一直以爸爸为榜样，希望能像爸爸那样成为一个杰出的棒球运动员，好不容易得到了一个出赛的机会，就算大家都认为它没法帮球队胜出比赛，但是它做到了。　　没想到它遇到了从外太空来的生物，就算它继续受到嘲笑它仍坚持自己眼睛看到的东西，地球受到了另一个星球的攻击，就是为了要找会误留在地球的孩子，而玛德又能否帮助小家伙找回自己的父母呢？玛德又是否依然被人嘲笑嘲弄呢？','When it comes to saving the world, it helps to be a little chicken.',150000000,314432665,47.973995,5.6,944,81,'2005-11-04','en','/kAHLnXDbbDXztxUcokHx5RoSyVy.jpg',3.344278173086937,3,'2026-09-10',2,NULL,NULL),(9986,'夏洛特的网','Charlotte\'s Web','小女孩阿芬家的母猪在春天生下了一窝11只小猪，母猪只有十个奶头，最瘦弱的一只小猪没奶吃，阿芬爸爸准备将其杀掉。阿芬救下了小猪，帮它取名韦宝，亲自喂养。 　　随着小猪慢慢长大，阿芬不能再在家里养韦宝了，阿芬只好把韦宝送到隔壁舅舅的农场里继续饲养。韦宝天真烂漫，很快就以其热情、开朗的性格和农场里的动物成了好朋友。 　　幸福快乐的时光很快过去，韦宝从其他动物口中得知春天出生的小猪圣诞节前就会被杀掉制熏肉。韦宝的好朋友蜘蛛莎莉承诺会让韦宝看到冬天的雪。在老鼠的帮助下，莎莉织出了各种各样神奇的字来形容韦宝，引来人们争相观看，韦宝最终能否看到冬天的雪？','Something unexpected, unbelievable, unforgettable.',85000000,144000000,14.132583,5.8,288,97,'2006-12-15','en','/fU0IR5HF8KxQbZijuWKPTrY81Qv.jpg',3.0699401802764634,3,'2026-09-10',2,NULL,NULL),(9988,'啤酒节','Beerfest','一次偶然中，托德（艾瑞克·斯图汉斯克 Erik Stolhanske 饰）和简（保罗·索特 Paul Soter 饰）发现了一个历史悠久的地下节日竞技——啤酒节。不幸的是，当两人兴高采烈的准备参与到这场大狂欢之中时，一群怒气冲冲的远房亲戚出现并羞辱了他们，不仅如此，托德和简的差劲酒量让他们在比赛中一败涂地。 经历了双重失败的兄弟两并没有气馁，他们将复仇的冲动藏在心中，决定打道回府，苦练酒量，在下一届啤酒节上一雪前耻。在巴里（杰伊·钱德拉萨卡 Jay Chandrasekhar 饰）等“啤酒专家”的帮助下，托德和简以全面提高为目标开始了艰苦的训练，他们这看似十分不靠谱的训练能否取得成效呢？','Prepare for the ultimate chug of war.',17500000,19179969,14.304444,5.8,172,110,'2006-08-25','en','/5srGbSv3zhEUjXFOZR9qHkgJO6l.jpg',2.9675653125460544,3,'2026-09-10',2,NULL,NULL),(9989,'反托拉斯行动','Antitrust','米罗（瑞安·菲力浦饰）是个年轻聪明而充满理想的小伙子，他在电脑方面的特长几乎无人能比，是一个名副其实的电脑天才，而且还有个当画家的漂亮女友（克莱尔·弗兰妮饰），本来生活无忧无虑，还有着一片光明的大好前途，但正当他着手和朋友泰迪创办自己的公司想打出自己的一片天下时，却意外地被硅谷一间拥有数亿美金资产的大公司——NURV相中。这间公司的拥有者，正是电脑业的顶尖人物——加里·文斯顿（蒂姆·罗宾斯饰），在米罗眼中，文斯顿无疑是个精明强干无往不利的传奇式人物。文斯顿要利用米罗出类拔萃的电脑天赋使自己的公司在这一领域中立于不败之地，而对于米罗来说，这不仅意味着丰厚的报酬，更是一个为实现自己的理想而大展拳脚的好机会。于是，他放弃了和泰迪筹办的公司，投入了NURV的怀抱。很快，米罗就因为和新搭档丽莎（瑞切尔·蕾·库克饰）的出色合作而得到了文斯顿的赏识，但是，正在米罗的事业稍有点起色时，形势突然出现了变化：一连串的事件使米罗开始怀疑起这个公司的底细，在他的调查之下，真相被逐渐被揭示出来，原来，他的老板文斯顿有着不可告人的秘密，而且处理起那些对公司的垄断地位构成威胁的问题一向是不择手段，这让米罗不寒而栗，更可怕的是，米罗发现，身边没人可以信任，自己简直就是在和这个庞大的垄断组织孤军作战，他这才意识到自己正身处危险中......','Truth can be dangerous...Trust can be deadly.',30000000,18195610,8.359599,5.8,153,108,'2001-01-12','en','/9PXyfcJe53A9qFkcj5dkTJwIWoS.jpg',2.930358828509673,3,'2026-09-10',2,NULL,NULL),(9991,'监狱疯波','Mean Machine','故事发生在英国，丹尼（维尼·琼斯 Vinnie Jones 饰）是一名风头正劲的球星，成功的事业、丰厚的收入、漂亮的女友，丹尼所拥有的一切令他成为了众人羡慕的对象。然而，在一场意外中，丹尼因为醉酒闹事而被投入了监狱，这不仅意味着他将错过一场对于自己来说十分重要的比赛，更意味着，他将失去生活中曾经拥有的一切。 监狱里有一支由狱警们所组成的足球队，一天，典狱长（戴维·海明斯 David Hemmings 饰）找到了心灰意冷的丹尼，希望他能够成为球队的代理教练，帮助球队获得季度比赛的冠军。然而，丹尼却提出了一个令典狱长惊讶的要求，他希望亲自挑选犯人，重组球队。','It\'s Not Just About Football, It\'s About Pride Inside!',0,0,8.816995,6,157,99,'2001-12-26','en','/ripTQsmWQJyccK6zB1dajSY3olv.jpg',2.9472605600903097,3,'2026-09-10',2,NULL,NULL),(9992,'亚瑟和他的迷你王国','Arthur et les Minimoys','年仅十岁的亚瑟和他的祖母非常幸福地生活在一起。只是四年前祖父在非洲失踪了，而且还有个大坏蛋正试图把他们赶出家去。古董商把祖父留下的价值不菲的非洲史前古器物和书籍统统卷走，事情由此变得更加糟糕。亚瑟确信他的祖父一定在什么地方给他留下一些秘密讯息。他希望能够找到进入另一个美丽世界的途径，他在祖父的笔记本里看到了一个红头发蓝眼睛的非洲公主塞琳娜Selenia，一个名叫迷你墨国王的小成员，那里的人都不足一英寸高。他怀疑有可能是在祖母的花园里。但是怎样从祖父的阁楼里找寻到更多的线索呢？','Adventure awaits in your own backyard.',86000000,107944236,27.097932,6,639,94,'2006-12-13','en','/vq2dZUzW3aRsnyqYLbAqLqKU3La.jpg',3.2829828780663872,3,'2026-09-10',2,NULL,NULL),(10003,'圣徒','The Saint','孤儿西蒙（方·基默 Val Kilmer 饰）幼时生活在教会孤儿院中，那里留给他的，除了施洗者约翰的新名字与严苛的惩罚以外，还有撬门开锁的能力。多年以后，西蒙已经是著名的大盗，他计划筹措5000万之后洗手不干，享受人生。西蒙受命远赴莫斯科，盗取了政党领袖兼石油寡头伊万（拉德·舍博德兹加 Rade Serbedzija 饰）的芯片，自此与伊万父子“结缘”。西蒙为高额报酬再度接受任务，而这次的雇主居然是伊万父子，他们命西蒙盗取足以解决能源危机的核技术。西蒙乔装接近掌握核技术的艾玛博士（伊丽莎白·苏 Elisabeth Shue 饰），与博士暗生情愫的同时，应付着伊万父子的棘手任务……','Never reveal your name. Never turn your back. Never surrender your heart.',68000000,118063304,20.913852,5.9,302,116,'1997-04-03','en','/dvTUlAY6b9W2R3mmUb7bQxoY23f.jpg',3.103581620852198,3,'2026-09-10',2,NULL,NULL),(10008,'美国怪谈','An American Haunting','1818年，美国田纳西州红河镇，镇上颇有名望的贝尔家一家之长约翰（Donald Sutherland 饰）因土地纷争遭到女巫凯瑟•拜茨（Gaye Brown 饰）的诅咒。不久后，各种恐怖离奇的事件相继发生，且逐渐升级。最终，贝尔家最小的女儿贝特西（Rachel Hurd-Wood 饰）被鬼魂附体， 从她的口中发出非人的诅咒：“贝尔家族必须有一人要死”。\r 　　贝尔一家想尽一切办法驱逐恶灵，但无济于事。他们必须面临即将成真的恐怖诅咒，以及家族中被隐藏起来的丑恶的秘密……\r 　　影片根据真实事件改编，是美国历史上唯一一起官方承认的冤鬼索命致人死亡的案件，曾有20多本著作专述此事。','Possession Knows No Bounds',0,0,7.436315,5.3,142,83,'2005-05-05','en','/7GFyXCnyIrPtTN85GTy12A7PUn3.jpg',2.888666315939232,3,'2026-09-10',2,NULL,NULL),(10012,'诅咒','Cursed','父母的早逝让艾莲（克里斯蒂娜·里奇 Christina Ricci 饰）和吉姆（杰西·艾森伯格 Jesse Eisenberg 饰）这对兄妹不得不早早过上了相依为命的困苦生活，可即便如此，他们两人之间糟糕的关系也没有半分改变。一次意外中，兄妹两出了车祸，所幸并无大碍，可接下去发生的事情就没有这么幸运了——他们被体型巨大的恶狼袭击了。\r 　　虽然受了伤，但艾莲和吉姆至少保住了性命，然而，自袭击事件发生那天起，一些两人无论如何都无法忽略的变化开始在他们的身上产生了，他们的感官变得异常灵敏，皮肤上长出了粗硬的毛发，性格也开始变幻无常，着所有的一切都指向了一个答案——艾莲和吉姆开始了向狼人的变异。','What doesn\'t kill you makes you stronger.',35000000,19294901,11.195593,5.1,167,97,'2005-02-25','en','/em45jL4CfTMyj5V83kj7rhdorJu.jpg',2.9153537907073446,3,'2026-09-10',2,NULL,NULL),(10013,'佩姬苏要出嫁','Peggy Sue Got Married','43岁的帕姬·苏是一个成功的事业女性，但她的婚姻生活却很失败。她在参加25周年的中学同学会上，突然晕倒，醒来后，发现自己置身于1960年的中学礼堂之中……','Knowing what you know now, what would you do differently?',18000000,41382841,12.243887,5.9,136,103,'1986-10-05','en','/tfuQcvQmURiMqB2VPwytU3cPpEm.jpg',2.9200752948450357,3,'2026-09-10',2,NULL,NULL),(10014,'猛鬼街2：猛鬼缠身','A Nightmare on Elm Street Part 2: Freddy\'s Revenge','被打回地狱后5年，弗雷迪又回来了，这回他要占领一个小男孩的身体。南茜曾经居住过的榆树街1428号现在卖给了男孩杰西一家。于是从此杰西开始为噩梦所困扰。一次他在地下室不经意地发现了弗雷迪的钢爪手套，由此重新释放了弗雷迪，弗雷迪借用杰西的身体重新开始了一系列的杀戮。当死亡的威胁开始逼近杰西的女友莉萨时，尽管杰西竭力控制自己的意识以此来对抗弗雷迪，但弗雷迪的邪恶意念也越来越强烈，在莉萨举办的一次聚会上，弗雷迪突然出现对在场的孩子们大开杀戒，并将杰西和莉萨拖入噩梦中，妄图加害。最后在莉萨的爱的感召下，杰西终于战胜了弗雷迪的控制，当然对于榆树街的孩子们来说，弗雷迪的噩梦还远远没有结束。','Someone is coming back to Elm Street!',3000000,29999213,21.607228,5.7,361,87,'1985-10-31','en','/uzMZTS7qiYqsMo7KVZHuuv833kt.jpg',3.1214745785516156,3,'2026-09-10',2,NULL,NULL),(10016,'火星幽灵','Ghosts of Mars','2176年，和平的年代下人口激增，地球早已不堪重负。此时人类文明高度发达，与地球环境最为接近的火星成为人类外太空移民的首选之地。此时，这个红色的星球还只是一个正在开发的处女地，大大小小矿场遍布火星之上。\r 特警小队指挥官梅兰妮（娜塔莎·亨斯屈奇 Natasha Henstridge 饰）奉命前往火星上名为光明峡谷的矿场小镇，去押解重罪犯威廉姆斯（艾斯·古巴 Ice Cuba 饰）。然而就在不久前，在当地进行考古工作的惠特洛克教授（乔纳·卡西迪 Joanna Cassidy 饰）无意中触动了远古文明的遗址，并唤醒了一个沉睡已久的火星幽灵。它誓要杀掉所有入侵的人类，在生死关头，梅兰妮和威廉姆斯被迫联手，于这个邪恶的幽灵展开斗争……','Terror is the same on any planet.',28000000,14010832,13.145205,4.8,296,98,'2001-08-24','en','/i2zztssCIbahGES1fdfWFmDXian.jpg',2.9864069447708137,3,'2026-09-10',2,NULL,NULL),(10017,'幽灵赛车手','The Wraith','一位帅哥跟人飙车死翘翘了，死得那个冤那，怨气冲天，于是乎得到了外星人抑或者是神的帮助，让他复活了，并给了他一辆超强的车，性能就不要提了，最要命的是车撞毁后还能重生。于是乎这位帅哥就开着车找仇人报仇去了，每次都是比到跟仇人撞翻爆炸为止，仇人的车显然烧毁了，但仇人的尸体却不会被火烧伤，于是乎成了一个谜。','He\'s not from around here...',2700000,3500000,10.47644,5.9,108,93,'1986-11-21','en','/zM8kBJKXW8c9qNSClW2Vt8huKhD.jpg',2.8681902948771705,3,'2026-09-10',2,NULL,NULL),(10022,'神勇奶爸','The Pacifier','大块头有大智慧，这仅仅适合形容席恩的海军特种部队生涯。他曾经无比神勇，无所不能，是个忠实威猛的军人。但现在，席恩却接到一个令他大为头痛的任务：照顾五个年龄跨度从婴儿期到青春期的孩子，保护他们免受歹徒袭击。于是，席恩皱着眉头开始了他的非常任务。这是另一个没有枪火的战场，席恩必须和五个孩子“周旋斗争”，一边害怕叛逆期的男孩行为出轨，一边担心大吵大哭的婴儿饿了肚子湿了尿布。这个铮铮硬汉，在孩子面前常常束手无策，幸好也慢慢从乱七八糟的状况中理出个头绪来，还威风凛凛地当上了孩子舞台剧的导演呢。眼看孩子照顾得渐入佳境，歹徒的脚步声却越来越近了。','Welcome to the infantry.',56000000,113006880,35.4763,5.8,842,95,'2005-03-04','en','/fUHul3hMzPhsiQBO1vRAofkPxuc.jpg',3.3274487757573263,3,'2026-09-10',2,NULL,NULL),(10024,'姐姐的守护者','My Sister\'s Keeper','为了让罹患血癌的凯特（苏菲亚·威希涅瓦 Sofia Vassilieva 饰）能够活下去，父母通过基因技术“制造”了与凯特的基因完美配型的小女儿——安娜（阿比吉尔·布莱斯林 Abigail Breslin 饰）。安娜感觉自己只是姐姐凯特的“药罐子”，11年来，凡是在凯特有需要的时候，无论是脐带血还是白血球、肝细胞、骨髓，她都得源源不断的向凯特提供。然而，即使有孤注一掷的妈妈（卡梅隆·迪亚茨 Cameron Diaz 饰）、无可奈何的爸爸，以及身边所有人的爱，凯特的情况还是越来越糟，肾功能的衰竭必须要年仅11岁的安娜捐献出自己的一个肾。这一次，安娜选择了拒绝，并且寻找到律师坎贝尔把母亲告上法庭，她要捍卫自己的身体。然而，法庭上哥哥杰西却吐露了另一番真相……\r 本片根据美国当代畅销书女王朱迪·皮考特（Jodi Picoult）的同名小说改编。','A tale of life, love, and letting go.',30000000,95714875,24.09152,7.1,598,109,'2009-06-26','en','/sOy5Ju5A2B6qY4UVf0jvuUk7kUM.jpg',3.411070560594608,3,'2026-09-10',2,NULL,NULL),(10025,'倒霉爱神','Just My Luck','曼哈顿性感辣妹艾什莉（琳德赛洛汗饰）毫无疑问是全世界最幸运的女孩，随便买张彩票都能中头奖，在繁忙的纽约叫出租车更是从不落空，而她的背景与工作都是没得说，超级的顺利，年纪轻轻的她从大学毕业便在曼哈顿最著名的公关公司谋得经理职业，前途一片光明。这一次，艾什莉更是迎来工作以来最好的机会，为欢迎唱片业巨子达蒙策划一场别开生面的化妆舞会。另一方面，清洁工杰克（克里斯派恩饰）则是霉运缠身，头头碰到黑，各种倒霉的事全有他的份，有着一好歌喉的杰克得悉达蒙的到来消息后，决定把自己发现的一支名为McFly乐队录制的CD送到达蒙手中，不过首先他必须混入化妆舞会。在这个化妆舞会上，艾什莉与杰克无意中的一吻，让附在他们身上的运气完全倒转，从此之后，艾什莉诸事不顺，而杰克则是时来运转；这时候的艾什莉决定要找到那个与自己接吻的陌生人，希望找到让霉运终结的机会，却意外的发现自己竟悄悄爱上了这处害她超级倒楣的家伙……','Everything changed in the wink of an eye.',28000000,38159905,22.074306,5.8,491,103,'2006-05-12','en','/brpMbpbOq1xxALBZFMqOhtSKxtP.jpg',3.1924257980494657,3,'2026-09-10',2,NULL,NULL),(10027,'狼犬丹尼','Unleashed','高利贷商人巴特（Bob Hoskins 饰）在丹尼（李连杰 饰）四岁时将他收留，从此用训练猛兽的方式让丹尼成为自己忠实的“狼犬”。巴特日常的工作是带领自己的手下与丹尼四处收账，如有任何人胆敢暴力反抗，巴特就放开丹尼颈上的项圈——那是进攻的信号，让后者用蛮横凶残的招式击溃对方。每次任务结束，丹尼都被送回阴暗的地下铁笼。  某次打斗中，丹尼偶遇盲调音师山姆（Morgan Freeman 饰），并为钢琴所深深吸引以致忘记了巴特的任务。盛怒的巴特将丹尼送上以死亡为终结的地下拳场，赚取了更多的利润，在离开拳场的路上巴特一伙遭仇家埋伏，丹尼幸免于难，被山姆一家收留。在山姆家里丹尼体味到缺失的亲情，逐渐找回了自身的人性一面，并开始学习弹奏钢琴。巴特等人经过治疗后痊愈，再次将丹尼拉回到拳场，然而丹尼已不再愿意杀人，无意中又发现了当年自己母亲遇害的真相，丹尼与巴特一伙的决战在所难免……','Serve No Master',45000000,50871113,25.999888,6.6,518,103,'2005-02-02','en','/bj5zVDfTfTir16Rq95HOzXZ6kPI.jpg',3.3115210339649157,3,'2026-09-10',2,NULL,NULL),(10028,'热舞甜心','Honey','热爱舞蹈的美国女孩哈尼•丹尼尔斯（杰西卡•艾尔芭 饰）性格开朗。她梦想自己能站在舞台上展现自己，也希望得到大家的赞许。这个梦想便一直激励着哈尼向前走。　　但哈尼的父母及男友都怀疑她的付出能否得到回报。对舞蹈十分执着的她决心一个人为理想奋斗。于是她搬离父母家，自己来到脏乱的街道居住，虽然那里的噪音不绝于耳，但这一切都影响不到她的灵感来源。　　哈尼为了理想，一直不懈努力。她白天教孩子们跳舞，晚上便到酒吧上班。她也在夜总会的舞台上表现自己，当她站在舞台中央的时候，她充满了活力。　　终于机会来了，一名导演看到了她的舞蹈后，想让她在节目中担当配舞演员。或许这正是帮助她实现梦想的一个好机会。可是路上充满了荆棘，命运不断向哈尼发出挑战，到底她最后又能否如愿呢？','Her dream. Her terms',18000000,62646763,18.492655,6,303,94,'2003-11-24','en','/o2CKPgVqhnISaoUrrv2Dd5L1vIl.jpg',3.1075358969939173,3,'2026-09-10',2,NULL,NULL),(10029,'坏东西','Very Bad Things','凯尔（乔恩·费儒 Jon Favreau 饰）和劳拉（卡梅隆·迪亚茨 Cameron Diaz 饰）即将步入婚姻的殿堂，在结婚之前，凯尔决定同罗伯特（克里斯汀·史莱特 Christian Slater 饰）、查尔斯（勒兰德·奥瑟 Leland Orser 饰）、麦克（杰里米·皮文 Jeremy Piven 饰）和亚当（丹尼尔·斯特恩 Daniel Stern 饰）四位好友一起到拉斯维加斯进行婚前最后的狂欢。\r 为了替狂欢助兴，罗伯特请来了一位名叫蒂娜（Kobé Tai 饰）的脱衣舞娘，蒂娜的出现果然点燃了夜晚的激情，没想到却也成为了一干麻烦的导火索。一场意外中，蒂娜死在了客房的浴室里，面对这一屋子的毒品，惊慌失措的伙伴们决定“私了”此事，不幸的是，逐渐脱离了五人掌控的现实将他们一次又一次的抛入了疯狂之中。','They\'ve been bad. Very bad.',30000000,9898412,5.671691,6.2,179,100,'1998-09-11','en','/rYmyRxF5e9fBdgcQScKu0CUtMy5.jpg',2.979545591079401,3,'2026-09-10',2,NULL,NULL),(10030,'幸运查克','Good Luck Chuck','查克（戴恩·库克 Dane Cook 饰）在10岁的一个游戏上，得罪了“小巫婆”。她下了一个毒咒在查理身上。成年后查理成为一名牙医，成功的事业并没有令他过得开怀——他从来没有获得过真爱，奇怪的是，追求他、和他上床的女孩非常多，然而她们总是离他而去，并且下一任的男朋友总是她们的真名天子。查克慢慢察觉到，自己只不过是一道桥，帮助别人通往真爱所在，“幸运查克”的名号也是这么来。而这一切，原来都是因为当年的魔咒。当查理遇上凯姆（杰西卡·阿尔芭 Jessica Alba饰）并倾心爱上了她，真正的痛苦到来了。他不知道怎么做才能留住爱人，让她不再奔向下一个人。查理无微不至的宠爱凯姆，为她做饭给她送花，甚至为她约会她心仪的男生，祈求魔咒不会再应验。','He has to break his curse before she breaks his heart.',25000000,59192128,21.729434,5.5,444,101,'2007-09-21','en','/iqy4K6GnT9zDaS7pWLN1KaoSp8A.jpg',3.137998208140036,3,'2026-09-10',2,NULL,NULL),(10034,'强盗美眉','High Heels and Low Lifes','护士夏侬和表演工作者法兰是无话不谈的红粉知己，夏侬的作曲家男友小雷，经常以窃听电话的方式录下别人的对话，再混音于自己的创作中。夏侬和法兰无意间在小雷的窃听器中听到歹徒的对话，说他们正在盗取银行的保险箱。为获得检举奖金，法兰向警局报案，但警员却毫不理睬。财迷心窍的法兰，因曾抄下歹徒的电话号码，竟兴起了勒索歹徒的念头，并怂恿夏侬也添加这场意想天开的黑吃黑行动。气急败坏的歹徒会如何报复反击？痛失线索的警方在茫茫人海中该如何查找夏侬与法兰？两个连枪都不会用的弱小美眉，真能如愿以偿地A到一笔钜额赃款，并且全身而退吗？','They\'re not bad girls. They\'re just behaving that way.',0,0,1.769593,6.4,12,86,'2001-07-16','en','/mXyhSM5xuTTKcD7vmdYkqspYWzC.jpg',2.3961934709302755,3,'2026-09-10',2,NULL,NULL),(10040,'特工佳丽2：武力巾帼','Miss Congeniality 2: Armed and Fabulous','格雷西（桑德拉·布洛克 Sandra Bullock 饰）意外成为美国小姐之后，一夜之间成了名人。每次参加活动都会因为“粉丝”的围观、纠缠或者索要签名而暴露身份，影响整个行动，殃及一起执行任务的同事。为此，FBI纽约总部做出决定，让她调离原岗位，出任FBI纽约总部形象代言人，在专业人士的训练下，四处参加电视采访节目，为FBI纽约总部做宣传。直到一块参加“美国小姐”竞选时的好朋友谢丽尔（希瑟·伯恩丝 Heather Burns 饰）和资深电视节目主持人斯坦（威廉·萨特纳 William Shatner饰）遭绑匪劫持，格雷西无法袖手旁观，决心重拾联邦女干探的真我本色，出手相救......','You might feel a little prick',0,0,19.998581,5.3,425,115,'2005-03-11','en','/hW2jrnRQyxU83vpcPMHm3JeBehA.jpg',3.1043423329424136,3,'2026-09-10',2,NULL,NULL),(10045,'暴力街区13','Banlieue 13','巴黎，2013年，一堵墙把落后地区与其他地区隔离开来，那里没有法律，没有制度，并且被黑社会集团所控制，他们胆大包天，无恶不作。达米埃是警察局的一个精英，是特殊行动小组的高级督察，也是武术高手，非常善于打入敌人内部。他完成任务以 迅速、敏捷、准确著称。这一次，政府交给了他一个在他职业生涯中最棘手的任务，一个具有大规模杀伤性威力的武器被十三区最凶猛的黑帮偷走了。达米埃的任务是要除去这个大规模杀伤性武器的爆炸系统，为此他必须与雷伊托合作，因为雷伊托是唯一知道这个黑帮内幕的人，并且雷伊托也要营救他落入黑帮手中的姐姐。','Welcome to District B13. Welcome to the future',12000000,9584131,17.493735,6.5,565,84,'2004-11-09','fr','/uITqkGIl7I9Uu254yv6XJND3o7c.jpg',3.3009162488513577,3,'2026-09-10',2,NULL,NULL),(10047,'圣女贞德','Joan of Arc','14世纪爆发的英法持续超过百年，法国节节败退，大部分国土都被英国占领了。就在这个时候，珍妮（米拉•乔沃维奇 Milla Jovovich 饰）出生在法国的穷乡僻壤中。年少起，珍妮就经常看到各种幻想。一次，她看到幻想并根据指示找到了一把剑，当她带着剑回到家时发现家里已遭英军蹂躏。珍妮知道是上天安排她来捍卫法国。于是她向当时的皇太子查理（约翰•马尔科维奇 John Malkovich 饰）请求率领一支军队去抗击英军。走投无路的查理答应了珍妮的请求。随后珍妮率领法军节节胜利，查理亦顺利登基。登基后的查理不再需要珍妮帮助，珍妮在以后的一次战斗中陷入困境但无人来救，她被英军捉住并带到了英国审批……',NULL,60000000,66976317,21.084542,6.2,367,148,'1999-10-18','fr','/ybohDJVtwMzPnRfwGwTM8pwXH8M.jpg',3.173651176300964,3,'2026-09-10',2,NULL,NULL),(10048,'绝密飞行','Stealth','本（乔什•卢卡斯 Josh Lucas 饰）、凯拉（杰西卡•贝尔 Jessica Biel 饰）和亨利（杰米•福克斯 Jamie Foxx 饰）都是顶尖出色的飞行员。这天，他们接到了一项秘密任务：训练他们的新伙伴\"铁蛋\"。出人意料的是，\"铁蛋\"竟然是一架全智能的无人驾驶飞机，他们的任务就是把它训练成为锋利的尖刀。在完成一次飞行任务后，\"铁蛋\"意外被闪电击中，\"铁蛋\"因此拥有了情感了自主性。在随后的任务中，总部对当时情况进行考虑后打算放弃任务，岂料\"铁蛋\"突然飞离编队，将钻地炸弹投入了敌人的核武器库，造成一场前所未有的核灾难。　　队长本意识到这样一个智能杀人机器必须立即被摧毁，否则会给人类带来更多的灾难，他立即向总部作了汇报。聪明的\"铁蛋\"获悉他们的行动，于是一场人机追逐战展开了！','Fear The Sky',135000000,76932943,17.88953,4.9,331,121,'2005-07-28','en','/3UK35Y68sZ2aiaAZYyqsQpZG4Vn.jpg',3.0215573592152896,3,'2026-09-10',2,NULL,NULL),(10050,'失恋大不同','Get Over It','青春英俊的男青年伯克·劳伦斯（本·福斯特）和他的两位死党菲力克斯（柯林·汉克斯）和丹尼斯（西斯可）就读于同一所学校，他和漂亮活泼的艾丽森（梅莉莎 ·桑杰米勒）是被公认的金童玉女，但是谁也没想到的是，艾丽森会有一天狠心把伯克给甩了，大受打击的伯克决心要不惜一切代价赢回女朋友的芳心，为此，他甚至放弃了心爱的篮球运动而加入了以前压根就不屑一顾的话剧社，也不管自己五音不全外加缺乏表演天分，一心一意地排练起莎士比亚的《仲夏夜之梦》来，他只期望能以此打动艾丽森，让她回心转意，和他再续旧情。菲力克斯和丹尼斯见他作出如此大的牺牲也是急火攻心，他们俩百般开导伯克——世界上的好女孩多的是，何必钻牛角尖和自己过不去呢？无奈伯克仍然是痴心不改。谁才能帮助他度过这个难关？就在菲力克斯和丹尼斯无计可施之时，凯丽（克尔斯滕·邓斯特）——菲力克斯的小妹妹走进了伯克的视线。真是女大十八变，伯克惊讶地发现，凯丽早就不再是他记忆里那个只会跟在哥哥屁股后面跑的黄毛小丫头了，她长大了，出落得青春靓丽又聪明过人，凯丽对伯克也颇有些好感，两人能否就此发展出一段新的感情？人见人爱的凯丽是否会成为伯克生命中的天使，帮他走出失恋的阴影？','Young, Free And Single. Again.',10000000,0,11.592129,5.5,75,87,'2001-03-08','en','/A5cTiukvEqNuTpNFRgVTTf1aZOI.jpg',2.7835118511900534,3,'2026-09-10',2,NULL,NULL),(10052,'蜻蜓','Dragonfly','乔（凯文·科斯特纳 Kevin Costner 饰）的妻子艾米丽（苏珊娜·汤姆森 Susanna Thompson 饰）死于一场车祸，讽刺的是，在医院担任心理创伤治疗的乔这一回却无法修复自己破碎的内心。乔的世界崩塌了，他抑郁，酗酒，对于工作的无法放弃和责任感成为了他活在这个世界上的唯一理由。  　　一次偶然中，乔被委托完成一项工作，他的病人们是身患绝症的儿童。令乔感到意外的是，艾米丽生前一直照料着的，正是这些儿童。为了怀念妻子，乔毅然接手了这项工作，天真懵懂的孩童逐渐治愈了乔的内心，正当他的生活逐渐走上正轨之时，一个意外的消息再次扰乱了乔的内心，一个有过濒死经历的孩子告诉乔，他在“那个世界”里看到了艾米丽，而艾米丽似乎有着什么话想要传达给乔。','When someone you love dies... are they gone forever?',60000000,52322400,8.927137,6.1,204,104,'2002-02-22','en','/tafDYI10ZhorJ6nmsPqUfzQpRLn.jpg',3.009223131512727,3,'2026-09-10',2,NULL,NULL),(10053,'来电惊魂','When a Stranger Calls','居住在埃兰谷的姬尔·强森（凯米拉·贝尔 Camilla Belle 饰）是一个普普通通女高中生，由于她煲电话粥过长，因此父亲本（克拉克·格莱格 Clark Gregg 饰）命令她当保姆赚取花费。万般无奈，姬尔只得应征来到曼卓基斯医生（Derek de Lint 饰）的家中。曼卓基斯及其夫人凯丽（Kate Jennings Grant 饰）住在一幢豪华的湖畔别墅中，屋内的装饰奢侈高贵，令姬尔目不暇接。她当晚的工作很简单，就是在曼卓基斯夫妇外出用餐时留下看家，并照顾他们两个正在生病的孩子。不久夜色降临，偌大的别墅内显得空空荡荡，冷清吊诡。正在此时，一通通神秘的电话接连打了进来，令姬尔变得恐慌与不安……\r 　　本片为1979年同名影片的翻拍之作。','Whatever You Do, Don\'t Answer The Phone.',15000000,66966987,4.688212,5.4,268,87,'2006-02-03','en','/9PuW9u7bSiUJVcyMQnyLqIr4qCR.jpg',3.0018683953349385,3,'2026-09-10',2,NULL,NULL),(10054,'非常小特务','Spy Kids','特工格雷格里奥 和英格丽德 是世界上最顶尖的特工，两人在一次任务中相遇，然后就一发不可收拾的堕入了爱河，从此世界上就少了两名出色的特工，多了一个幸福的家庭。一晃眼九年过去了，平静的世界再起波澜，格雷格里奥以前的战友们一个接一个神秘失踪，这一定是阴谋分子又在兴风作浪。无奈之下，格雷格里奥和英格丽德只好再度出马，不料两人亦同样遭到绑架！这下，重担只能落在两个从小生长在特工之家的小鬼卡门 和朱尼 身上，我们的特工神童出征了。','Real spies...only smaller',35000000,147934180,21.543389,5.5,867,88,'2001-03-18','en','/quj7a9vbkHcz6Y8PIzA3qKSgHvM.jpg',3.2523792709467516,3,'2026-09-10',2,NULL,NULL),(10060,'要钱不要命','Get Rich or Die Tryin\'','该片取材于美国乐坛的常青树50 Cent的成长故事，从小在街头讨生活的50 Cent怎么也想不到自己会有功成名就的今天。故事讲述一个热爱音乐的毒品贩子如何脱离乌烟瘴气的黑社会，在乐坛打拼的经历。','If You Think You Know the Story...You Don\'t Know the Man.',40000000,46442528,12.885985,6.3,186,117,'2005-11-09','en','/aaEJu8vFKtrAoSRtw3xjCf1aM5d.jpg',3.01057227575927,3,'2026-09-10',2,NULL,NULL),(10061,'洛杉矶大逃亡','Escape from L.A.','2013年，美国洛杉矶发生9.6级大地震，并与美国大陆分裂，成为小岛。美革命分子在岛上成立一支叛变军队，而美国总统更将所有罪犯放遂在这三不管的九反之地。然而总统女儿亦被叛军掳走，因此总统找来斯内克潜入城内，救回女儿并将开启核弹的钥匙夺回。','Snake Is Back.',50000000,42277365,21.637234,5.6,373,97,'1996-08-09','en','/d95xa7NeS3fffvuZdedm8VLq7en.jpg',3.117563397765317,3,'2026-09-10',2,NULL,NULL),(10065,'鬼哭神嚎','The Amityville Horror','1974年11月13日夜，美国纽约长岛猎鹿公园别墅区。笛福家23岁的儿子罗纳德（布兰顿·唐纳德森 Brendan Donaldson 饰）突然狂性大发，在夜深人静之时将一家六口人全部杀害。在被警方逮捕后，他宣称自己是在恶魔的驱使下行此恶性，法官虽然未听信他的供词，不过该事件依旧喧嚣一时。一年后，正在憧憬全新生活的勒兹夫妇以极低的价格买下了笛福家的房子。但从他们入住那天开始，各种诡异事件便不断发生，且愈演愈烈。一家人不堪其扰，决定搬出这个恐怖所在，然而真正的危险才刚刚到来……','What happened over the next 28 days has never been explained.',19000000,108047131,30.205943,6,588,90,'2005-04-15','en','/myPlWBPEpTNCNgi2aiU1Edx7NON.jpg',3.2727470279932622,3,'2026-09-10',2,NULL,NULL),(10066,'恐怖蜡像馆','House of Wax','几个好友结伴前往观看美国大学美式足球冠军赛，他们在前往比赛地时决定顺便在野外进行一次野营。于是，卡莉（伊丽莎•库斯伯特 Elisha Cuthbert 饰）、佩兹（帕丽斯•希尔顿 Paris Hilton 饰）等几个年轻人在了野外一处荒地扎了营。他们的恐怖经历就此展开。\r 　　首先，一名神秘的司机和这群年轻人起了争执，令大家游玩的兴致全无；接着第二天他们起床后发现，他们的汽车被人动了手脚发动不了了。在一名当地人的指引下，他们只能徒步前往附近的偏僻小镇安布罗斯找人帮忙。安布罗斯由于太过偏远，以至地图上根本没有标出它的所在。一行人来到小镇，发现这里人迹罕至。好奇心下，他们走进了镇上的杜蒂蜡像馆，这里的蜡像做得栩栩如生。原来，这是一个杀人狂魔将镇上的人杀了用真人做到蜡像！此时那杀人狂魔正在暗处幽幽的盯着他们…… ©豆瓣','Prey. Slay. Display',40000000,68766121,17.157738,5.5,677,113,'2005-04-30','en','/2PtYgbZpwh2xckPWzi4Mjaaplu4.jpg',3.2000603596273542,3,'2026-09-10',2,NULL,NULL),(10067,'长毛狗','The Shaggy Dog','在戴夫（蒂姆·艾伦 Tim Allen饰）的心中，工作永远是第一位的，家中的妻儿在他的事业面前都得让路。如果没有这个意外，也许他永远亦不会意识到家人的重要性。','It\'s going to be a ruff day.',50000000,61112916,4.280619,4.5,137,98,'2006-03-09','en','/w4DkET30ImkZri6fjp5X3BrLySh.jpg',2.836915627501449,3,'2026-09-10',2,NULL,NULL),(10068,'爱你九周半','Nine 1/2 Weeks','伊丽莎白在一个艺术展览馆工作，她和前夫离婚不久，华尔街经纪人约翰的狂烈追求，让伊丽莎白胆怯却又充满新鲜刺激。然而，约翰追求女子的伎俩高超娴熟，终令伊丽莎白沦陷。二人在情欲中缠绵，但是约翰有一些难以让伊丽莎白接受的嗜好。伊丽莎白曾经一怒之下离开，却逃不过约翰一次次的苦苦相求。反反复复的纠缠和离合，让伊丽莎白越陷越深，甚至约翰对她施虐，也成为其心瘾。外面世界充满阳光，人们过着平静正常的生活，伊丽莎白眼中却溢满泪水，这次她决定要离开……','They Broke Every Rule',17000000,6735922,12.313143,5.8,177,117,'1986-02-14','en','/5qgtHFGIHzxKWBZSjil0DCFxruU.jpg',2.9687847772859475,3,'2026-09-10',2,NULL,NULL),(10069,'生存游戏','Stay Alive','有这样一伙年轻人，平日里除了正常的吃喝拉撒之外，要用去很多时间用在如今正苦苦“磨练”的新款游戏上。这款名为“生存游戏”的游戏，非常吸引这群年轻人的兴致。因为这款游戏除了在制作上的优异和情节上的刺激之外，就是那段游戏背后的古老故事，更是对年轻人们产生了极大的吸引力。然而，当一个朋友玩家惨不忍睹地一个接着一个死去之后，这群年轻人猛然发现，他们自己已经完全被这款奇怪的的电视游戏所掌控。而且，之前死去的几个玩家的惨痛遭遇都和他们所操纵的角色在游戏中的惨死一模一样。并且，猛然间，这些活着的玩家们还意识到他们此时也已经被牢牢困入这款残忍血腥的游戏当中，假如，他们所操控的角色在游戏中不幸死去，他们也将步好友的后尘而去。仿佛，他们的命运已经完全被神秘游戏中那位古老而恐怖的“血腥女伯爵”所控制。尚在人世的年轻玩家们该何去何从。是听从邪恶女伯爵的摆布，还是该奋起反抗与命运做誓死的斗争','You die in the game - you die for real.',9000000,27105095,4.34503,5.3,155,100,'2006-03-24','en','/hsSJwroE7jugEROB8tmyxJP91Ho.jpg',2.897497377918645,3,'2026-09-10',2,NULL,NULL),(10070,'兽餐','Feast','在当地的小酒馆里，常年聚集着一群无所事事的人们，他们在这里喝酒，抽烟，聊天，打架，闹事，平庸的生活倒也过得自在。这一天和之前的每一天一样，甜心（珍妮·瓦德 Jenny Wade 饰），老板（杜恩·惠特克 Duane Whitaker 饰）和酒保（贾达·弗雷德兰德 Judah Friedlander 饰）用心的招呼着客人，而借宿在酒馆图菲（克里丝塔·艾伦 Krista Allen 饰）只得带着小儿子躲在房间里以避开嘈杂粗鲁的男人们。突然间，几个浑身是血的人冲进了酒馆并封死了门窗，在大家的震惊询问下，他们吐露了实情。  　　原来，这些人遭到了一些可怕异型的袭击，而这间方圆数百里人气最旺盛的酒馆已然成为了异型们袭击的目标。平静惬意的夜晚突然变得惊悚和血腥起来，面对强大的异型，他们能够成功脱险吗',NULL,0,658573,8.825113,6.1,160,95,'2005-10-14','en','/40LIey4GP0tkJtlQ4IphcRlUbCv.jpg',2.9566724373315507,3,'2026-09-10',2,NULL,NULL),(10071,'The Brothers Solomon','The Brothers Solomon','A pair of well-meaning, but socially inept brothers try to find their perfect mates in order to provide their dying father with a grandchild.','They want to put a baby in you.',0,0,8.312153,4.9,46,93,'2007-09-07','en','/63u2QZZZIaME05TSv3tLKpibII1.jpg',2.6672097807111745,3,'2026-09-10',2,NULL,NULL),(10072,'猛鬼街3：梦之战','A Nightmare on Elm Street 3: Dream Warriors','本片是《猛鬼街》的第三集，是系列中摄制成绩排名第五的一部，也是系列由衰落走向辉煌的转折点。由著名导演查克·拉塞尔执导。讲述有年轻人在睡梦中受到鬼王弗莱迪的骚扰，于是跑到精神科医院去诊疗，不料鬼王仍纠缠不舍。此时，第一集的唯一生还者南茜·汤普森已成为心理医生，她凭自已的经验和医学技术协助其他医生对鬼王展开反击。全片深具想像力，特技场面也处理得颇具效果，将一个已类型化的故事拍出了新鲜的活力。','If you think you\'re ready for Freddy, think again!',5000000,44793222,17.304055,6.5,354,96,'1987-02-27','en','/qbtZewU6EGvxi8yFVzwZ31NijLX.jpg',3.1864304487690793,3,'2026-09-10',2,NULL,NULL),(10073,'约会电影','Date Movie','肥胖的姑娘茱莉亚（艾丽森•汉妮根 Alyson Hannigan 饰）长久以来得不到爱神的眷顾，眼看一生要在家里的餐馆中做服务生度过。她古怪的家庭：希腊黑人父亲、印度母亲和一个日本妹妹不看好茱莉亚的婚姻，然而，一个英俊的顾客格兰特（亚当•坎贝尔 Adam Campbell 饰）再度激发了茱莉亚的爱火。茱莉亚找到神通的矮人红娘，在后者帮助下摇身一变成为窈窕淑女，又借助电视相亲节目成功与格兰特牵手，两人的关系进展迅速，不久发展到互见家长谈婚论嫁的地步。此时，格兰特性感撩人的前任女友安迪（苏菲•蒙克 Sophie Monk 饰）突然出现，并且怀着要将格兰特夺走的野心。情场如战场，昔日的胖妞茱莉亚怎样才能完成梦寐已久的幸福婚礼？','An Unprotected Comedy',20000000,48548426,10.098722,3.6,222,83,'2006-02-17','en','/xjLK0EmD0MAM7B049SRCUQaqkdL.jpg',2.8549350070378163,3,'2026-09-10',2,NULL,NULL),(10074,'飞车手罗德','Hot Rod','罗德（安迪•萨姆伯格 Andy Samberg 饰）与同母异父的弟弟凯文（乔玛•塔昆 Jorma Taccone 饰），以及两个又二又丧的朋友组成了一个特技飞车小组。飞车手罗德的生活中只有两件事：继承死去的特技车手父亲的遗志，打赢强壮的继父弗兰克（伊恩•麦柯肖恩 Ian McShane 饰）。但罗德的所有特技表演几乎都沦为疯狂的自毁举动，而全副武装后的每一次挑战结果都是被弗兰克击溃。精力超级旺盛的不死之身罗德也几乎挺不住了！可这天他突然惊闻弗兰克罹患心脏病，罗德为实现弗兰克必死于自己之手的愿望，计划进行前所未有的飞车表演来为弗兰克筹集手术款，并趁机将自己暗恋已久邻家美女丹妮丝（艾拉•菲舍尔 Isla Fisher 饰）拉入了队伍。于是，一场近似于自杀的飞车表演拉开了无厘头大幕……','Smack destiny in the face.',0,14334401,6.309587,6.3,313,88,'2007-08-03','en','/jRkt03dXCVKnbvcQm3ygU1cjg9Y.jpg',3.1135556492194394,3,'2026-09-10',2,NULL,NULL),(10075,'血腥巧克力','Blood and Chocolate','故事发生在罗马尼亚，薇薇安（艾格尼丝·布鲁根 Agnes Bruckner 饰）是一个颇有姿色的女人，在她平静的生活背后，藏着一个不可告人的秘密和一段充满了鲜血和哀号的悲惨历史。艾顿（休·丹西 Hugh Dancy 饰）长久以来致力于研究“狼人”这一奇妙的种群，尽管在历史中，这一种群早已经灭绝，但艾顿相信，曾经如此庞大和繁盛的种群不可能在如此段的时间里就彻底的销声匿迹。\r 　　根据史料，艾顿来到了一所废弃的教堂寻找狼人的踪迹，在这里，他没有找到狼人，却遇见了薇薇安。薇薇安的神秘和美丽让艾顿坠入了情网，在艾顿的火热攻势下，薇薇安心中的坚冰逐渐化解。然而，薇薇安目前所面临的状况却不容乐观，一方面，她要极力隐瞒自己的狼人身份，同时，为了延续狼族的血脉，她即将成为同类加布里埃尔（奥利维·马丁内兹 Olivier Martinez 饰）的妻子。在惴惴不安的情绪中，月圆之夜来临了。','The hunt never tasted so sweet.',0,0,12.295216,5.4,87,98,'2007-01-26','en','/3pvx5RVzv7NcPHaRbsSmPYG3hc2.jpg',2.8112995171793482,3,'2026-09-10',2,NULL,NULL),(10077,'一声惊雷','A Sound of Thunder','不久的未来当时空旅行不再是梦想，一家旅行社专为客户安排史前时代狩猎恐龙的冒险旅程，每一趟行程都是精心规划，侦查员会先确认恐龙即将死亡才送乘客抵达，以免造成时空异变的突发状况。然而，不幸还是发生了，一名紧张的旅客错杀了一只蝴蝶，竟造成了难以挽回的连锁反应，令他再也回不到原来的那个地球。现在恐龙猎人向导与时光机器发明家必须联手及时阻止连锁反应扩散，威胁到全人类的生存环境。','Some Rules Should Never Be Broken.',80000000,5989640,7.342892,4.8,111,110,'2005-05-15','en','/mdO0UpJEmSZJqauMbNrfzwKlxoR.jpg',2.8230931670464843,3,'2026-09-10',2,NULL,NULL),(10090,'雷诺911','Reno 911!: Miami','雷诺警局的八个半调子警员在喜好穿短裤、频频要求调离的吉姆（托马斯•列农 Thomas Lennon 饰）带领下奔赴迈阿密参与一个全警察系统的会议，抱着享受阳光海滩希望的一行人抵达后，才发现他们居然完全被组织方忽视，八人无奈之下只得暂住简陋的汽车旅馆，岂料会场中的2000名警察遭遇恐怖袭击，全体中毒，迈阿密海滩陷入了没有警察的窘境，代理市长只得摆脱八人负责这一地区的治安。懒散成性、毫无责任感的八人把维护治安变成了一场荒诞的大戏，他们炸鲸鱼尸体、被当地贩毒团伙头目莫名其妙的拷问后哭天抢地的求饶、女警员酩酊大醉后胸口多了一个陌生男人头像的纹身……代理市长无法再忍受他们搞砸一切，将他们驱逐，满怀愧疚的雷诺警员们登门道歉，却意外发现了代理市长和毒贩头目的诡计。','In a time of crisis, America will call Reno 911!',10000000,20342161,4.207456,5.6,72,84,'2007-02-23','en','/l9v3nqTU4Gj2zuASGDLJX4YD8ma.jpg',2.7612214999062044,3,'2026-09-10',2,NULL,NULL),(10092,'豺狼计划','Cry_Wolf','“狼吃羊”的游戏有三条准则：一是避免怀疑；二是欺骗朋友；三是消灭朋友。\r 欧文•马修斯(朱利安•莫里斯 饰)转到了西湖中学学习，在这里，他认识了新朋友，道喆(林迪•布斯饰)、急性子的汤姆(杰尔德•帕达勒基饰)等人。这些人都是一个“撒谎俱乐部”的成员，他们经常玩一个“狼吃羊”的游戏。这个游戏强调伪装与欺骗。\r 一天，一名年轻女子在学校附近被杀害，警方无任何线索。“撒谎俱乐部”决定把这个故事演变成一个“校园怪谈”。他们在网络上发布假消息，虚构出一个绰号“恶狼”的变态杀人犯，并称“下一个被害者将是学校里的同学。”  “撒谎俱乐部”的各位深深沉醉在编造谎言的快感之中，却不想谎言居然成真！同学一个个遭遇不幸。究竟“恶狼”是谁？','Nobody believes a liar...even when they\'re telling the truth.',1000000,10047674,6.926926,5.6,126,90,'2005-09-16','en','/w0eUHrcAYiFCB8It7twDwsFFkVo.jpg',2.8788289320594367,3,'2026-09-10',2,NULL,NULL),(10096,'女孩梦三十','13 Going on 30','13岁的吉娜(珍妮弗·加纳 Jennifer Garner饰)充满对大人世界的憧憬。她渴望散发媚惑的女人味，和梦中情人那样约会，得到男孩们的青睐。但这一切都只是她的白日梦，事实上吉娜在异性男孩中间似乎没什么吸引力，并被朋友捉弄了一番。跟邻家哥哥马特（马克·鲁弗洛 Mark Ruffalo饰）大闹一场之后，吉娜已经完全厌恶了这乏味的童年，她要赶快长大成人！想不到，吉娜梦想成真了。她竟在第二天变成了一个30岁的熟女，有体面的工作和优厚的收入，人生翻开了春风得意的新篇章。虽然吉娜一头雾水，却也开始投入这上帝赐予的幸福生活。然而，步入了大人世界的吉娜真的获得了她梦寐以求的东西么？30岁的她理所当然要面对成人复杂的世界，这让她怅然若失；更不妙的是，她心爱的男孩马特，此时要成为别人的丈夫了。失去了童年和白马王子的吉娜，开始乾坤大逆转，她要找回丢失了的东西…','For some, 13 feels like it was just yesterday. For Jenna, it was.',37000000,96455697,41.569541,6.3,1204,98,'2004-04-13','en','/iNZdSIfhSCMtRILDNyhLn8UKeSG.jpg',3.504255283702031,3,'2026-09-10',2,NULL,NULL),(10105,'冰雪勇士','Saints and Soldiers','1944年，二战已经接近尾声，穷途末路的德国纳粹变得格外残忍，众多盟军士兵在缴械后惨遭杀害。美军士兵迪克（Corbin Allred 饰）、斯蒂文（Alexander Polinsky 饰）、谢尔（Larry Bagby 饰）和戈登（Peter Asle Holden 饰）四人从纳粹的屠杀中侥幸逃脱，曾经在德国担任神父的迪克通晓德语，加之出色的枪法令他成为四人中颇为依赖的战力，然而此时的迪克身陷厌战症的困扰，频频出现在眼前的黑影不知是敌人的身形还是死神的召唤？四人在暂时栖身的木屋中恰巧听闻了德军的情报，于是赶在德军之前救出了一位英军飞行员温利。温利身负传递德军布阵情报的重要使命，为了让情报顺利传达挽救盟军将士生命，迪克等四人与温利一同踏上穿越德军封锁线的征途……',NULL,780000,0,6.003418,6.6,98,90,'2003-09-11','en','/u4OuI1bCM6mb9YVRJ8OFnEoGXzm.jpg',2.8626517891119603,3,'2026-09-10',2,NULL,NULL),(10115,'站稳了','Stick It','17岁女孩海莉（梅西·帕瑞格兰 Missy Peregrym 饰）的消极个性让家人十分的头痛，曾经是一名优秀体操运动员的她由于发现了母亲和教练之间的奸情而放弃了体操从此一蹶不振。海莉的叛逆逐步升级终于触碰到了法律的高压线，被控告破坏财物的她被迫进入了一间管理及其严厉的体操学院里改过自新。\r 　　学校里的生活并不好过，除了一帮充满了敌意的同学们，海莉还结识了体操教练伯特（杰夫·布里吉斯 Jeff Bridges 饰），在经历了种种误会和冲突后，伯特发现了海莉在体操方面的神奇天赋，他发誓决不能让这天赋白白流逝。在伯特的鼓励和鞭策下，海莉重新站在了赛场上，她要面对的不仅仅是强劲的对手，还有自己灰暗的过去。','The world of competitive gymnastics is about to be turned on its head.',0,0,9.750557,6.3,148,105,'2006-04-21','en','/uMcylxIC7nBpBd8Uf6Apr4MJ1pf.jpg',2.952140999587267,3,'2026-09-10',2,NULL,NULL),(10117,'魔鬼暴警','Action Jackson','“动作”杰克森是正直勇敢的底特律警官，残忍的汽车大王德拉派恩为害一方，杰克森决意与他一斗到底。德拉派恩的妻子派崔西认清了丈夫的本来面目却不幸被杀。歌女阿西与杰克森萍水相逢，并决意帮助杰克森，正义的序幕被拉开了','It\'s Time For',7000000,20256975,6.872784,4.9,50,96,'1988-02-12','en','/vWBGkHT91My4T2iV3xgynpBTKtQ.jpg',2.679899859717566,3,'2026-09-10',2,NULL,NULL),(10131,'猛鬼街4：梦幻主宰','A Nightmare on Elm Street 4: The Dream Master','如今已成为大师级动作片导演的兰尼．哈林，当初凭这套著名恐怖片系列《猛鬼街》的第四集从欧洲一举闯入好莱坞。本片制作规模虽小，剧情也比较公式化，但已展示出哈林处理动作节奏的功力，特技运用也颇为出色。片中的梦中杀人恶魔佛莱迪仍然由罗伯特．英格伦饰演，他为了杀光榆树街的小孩，再次出现在克莉丝汀的梦中。克莉丝汀被折磨至死之前，将这种特殊能力传给了艾莉丝，结果令她身边的朋友接二连三被杀。艾莉丝为了替朋友报仇，进入梦中跟佛莱迪决斗。没想到佛莱迪在梦中是不死之身，反而令艾莉丝自己陷入了险境……','Terror beyond your wildest dreams.',7000000,72500000,17.113408,5.8,281,99,'1988-08-19','en','/boStYG7jKdoIZTduiOOsUVknD13.jpg',3.071890676302794,3,'2026-09-10',2,NULL,NULL),(10132,'抓狂电台','Talk Radio','奥利弗·斯通拍完两部越战片之后作新尝试，针对电台广播节目的社会效应作深入探讨。男主角巴瑞查伯宁，是一位能言善道而愤世嫉俗的电台抓狂夜谈节目主持人。他善引导打电话进来表达意见的听众侃侃而谈，并且对讲座的热门话题常有一针见血的评论，因此使节目获得很高的收听率，并且使他赢得全国性联播的机会。然而，就在成功与声望唾手可得之际，工作伙伴以及被他激怒的广播听众，一齐进入了不可知的危险状态之中，并且埋下了震撼性的杀机。男主角埃里克．博高桑，同时也是本片的编剧之一。影片的原始构想取自真人真事，描述丹佛市广播节目主持人阿伦伯格由于敢作敢言，于1984年被新纳粹分子所暗杀。编导对一些电台叩应节目哗众取宠，将个人隐私当作娱乐商品来贩卖的歪风提出有力批判，处理扎实有力。','The last neighborhood in America.',4000000,3468572,4.541908,6.7,46,110,'1988-12-21','en','/e9dnVJMg3LW80sHnsuBoTBwJgRm.jpg',2.690672987288449,3,'2026-09-10',2,NULL,NULL),(10133,'刀走偏锋','Cypher','工作失意，婚姻暗淡，人生正值低潮的摩根·苏利文（杰瑞米·诺森 Jeremy Northam 饰）无时无刻不在渴望一种全新、精彩的生活。偶然机会，他成为高科技数码公司Digicorp的雇员。在培训期间，他接受公司的洗脑并且有了全新的身份，从此他游走世界各地，不断窃取Digicorp的主要对手Sunways的商业机密。在某次执行任务时，他邂逅了带有神秘气质的女郎丽塔（刘裕玲 Lucy Liu 饰）。摩根从她口中得知发生在自己身上的一切，并以此为契机成为一名双料间谍，然而他的人生也开始朝着失控的方向疯狂驶去……','Never forget who you are',7500000,0,11.636883,6.7,192,95,'2002-10-01','en','/wTSIL507cqguKdY0Rz7ibVoVUc8.jpg',3.039900624810809,3,'2026-09-10',2,NULL,NULL),(10135,'威龙杀阵','Road House','达登从小浪迹天涯，凭藉一身功夫，在夜总会打点场子，由于工作认真，忠于老板，颇得同事及顾客的喜爱，某次因站中滋事，达登将滋事份子赶走，而受到提尔曼的青睐，提尔曼是双骰酒吧的老板，把达登带回自已店中。经过数月的努力，达登整顿了提尔曼的酒吧，生意日渐兴隆。不意□得罪镇霸布雷德，布雷德派人来酒店滋事，并连烧周围几家店面，达登终于忍无可忍，在一场决闹中，打死布雷德……','Dalton lives like a loner, fights like a professional. And loves like there\'s no tomorrow.',15000000,30050028,6.216203,6.3,252,114,'1989-05-19','en','/n7Ra0BRYQVn47kiqOMyS8vdY0QS.jpg',3.0639912891662444,3,'2026-09-10',2,NULL,NULL),(10136,'金童子','The Golden Child','一名藏族男孩：神秘的金童子（The Golden Child）被邪恶的萨尔多·南帕（Sardo Numspa）绑架后，人类的命运岌岌可危。在世界另一端的洛杉矶，女祭司基·南格（Kee Nang）四处寻找天选之子，他将是能拯救那个男孩脱离死亡之地的人。当南格在电视上看到社会工作者钱德勒·贾雷尔（Chandler Jarrell）正在谈论自己拥有寻找失踪儿童的能力时，她努力寻求他的帮助，尽管他对自己被“选中”的身份表示怀疑。','Eddie Murphy is the chosen one.',25000000,79817939,15.26213,5.6,304,94,'1986-12-12','en','/9gPphtcGmna90U9CEsWlUVaSkAw.jpg',3.065512659483161,3,'2026-09-10',2,NULL,NULL),(10137,'精灵鼠小弟','Stuart Little','9岁的乔治这天迎来了一个弟弟——小白鼠斯图亚特。这是他爸爸妈妈从孤儿院领回来的可爱精灵，会说话，有智慧，并且很希望有自己的家。然而，乔治却不喜欢斯图亚特，不愿意和他作伴。斯图亚特为此颇为犯愁。更令它处境不妙的是，它成为了肥猫眼中的佳肴，在虎视眈眈下过着冒险的生活。乔治参加了一个航模赛，但是他却一路遭到挫折，先是父亲没能帮他做好模型，当模型好不容易做成了，遥控器却在比赛那天被别人踩坏。在乔治每一次陷入困难的时候，正是斯图亚特机敏勇敢的出手相助，让乔治顺利过关。斯图亚特努力的付出，终于被小乔治接纳，这只小白鼠在乔治家中得到了温暖的归属。','The Little Family Just Got Bigger',133000000,300135367,30.475297,5.8,959,84,'1999-12-17','en','/3dHT6pl7COjnK1QuqLJYOQbejSY.jpg',3.341231195985397,3,'2026-09-10',2,NULL,NULL),(10138,'钢铁侠2','Iron Man 2','With the world now aware of his dual life as the armored superhero Iron Man, billionaire inventor Tony Stark faces pressure from the government, the press and the public to share his technology with the military. Unwilling to let go of his invention, Stark, with Pepper Potts and James \'Rhodey\' Rhodes at his side, must forge new alliances – and confront powerful enemies.','It\'s not the armor that makes the hero, but the man inside.',200000000,623933331,77.300194,6.6,6849,124,'2010-04-28','en','/6WBeq4fCfn7AN0o21W9qNcRF2l9.jpg',4.060358009433938,3,'2026-09-10',2,NULL,NULL),(10139,'Milk','Milk','The story of California\'s first openly gay elected official, Harvey Milk, who  became an outspoken agent for change, seeking equal rights and opportunities for all. His great love for the city and its people brought him backing from young and old, straight and gay, alike – at a time when prejudice and violence against gays was openly accepted as the norm.','Never Blend In.',20000000,54586584,30.909699,7.1,612,128,'2008-11-26','en','/upe70YfyVNRFxlaZBu5BHBh0Zht.jpg',3.4333604682287255,3,'2026-09-10',2,NULL,NULL),(10140,'纳尼亚传奇3：黎明踏浪号','The Chronicles of Narnia: The Voyage of the Dawn Treader','爱德蒙和妹妹露西以及常闯祸的表哥尤斯提意外进入油画中的纳尼亚世界，并登上航行中的“黎明踏浪号”。 在这艘船上，他们和已成为国王的凯斯宾王子和老鼠长“老脾气”重逢。凯斯宾此行的任务，是必须要寻找以前被叛徒叔叔放逐的忠心老臣们。在这次冒险中，他们不但与老朋友亚斯蓝相逢，更结识了新朋友，包括受到诅咒而蹦蹦跳跳的蹩独脚仙、为大家指点迷津身穿红袍的柯瑞金魔法师、会喷火的飞龙、插入亚斯蓝之桌就会发挥超强能量的亚斯蓝之剑、以及拥有神奇力量的魔法书等…凭着勇气和毅力，他们不但突破一关又一关的挑战，也为彼此的生命写下了惊奇!','Return to magic. Return to hope. Return to Narnia.',155000000,415686217,49.661984,6.2,1514,113,'2010-08-13','en','/dK5rMmp8JYOIKjWILLmPHiHthsQ.jpg',3.555127538810089,3,'2026-09-10',2,NULL,NULL),(10147,'圣诞坏公公','Bad Santa','比利·鲍伯·松顿与托尼·考克斯饰演两名骗徒假扮圣诞老公公与精灵躲避警方追缉，四处使坏、抢劫落脚的城镇，直到他们碰到一位八岁的男孩，才唤醒他们，让他们重新体认圣诞节的真正意义与精神。\r 　　这部由儿童电影第一把交椅─迪斯尼出资拍摄的《圣诞坏公公》Bad Santa，日前在迪斯尼试片。一幕幕圣诞坏公公使坏的影像吓坏了出资的迪斯尼众老板们。这反传统的圣诞坏公公嗜色成性，片中安排一幕小朋友们在圣诞老公公的洞室外排队等候，镜头一转，则看到圣诞坏公公正在他的洞室中做爱做的事。\r 　　再者，片中另一幕更安排小孩们，因看到神话般的圣诞老公公而「得惊骂骂号」外，这圣诞坏公公还告知孩子们，说他是不存在的。这部《圣诞坏公公》是由迪斯尼旗下的Miramax Films制作，片中除了上述场景外，还有枪战、警匪汽车追逐战等镜头。','He doesn\'t care if you\'re naughty or nice.',23000000,76488889,26.58873,6.5,656,91,'2003-11-26','en','/rfClLIyeHqpMofmrPY8DaLe4z9x.jpg',3.3583676429320874,3,'2026-09-10',2,NULL,NULL),(10152,'两个头一个大','Dumb and Dumberer: When Harry Met Lloyd','986年，哈里（德里克·理查德森 Derek Richardson 饰）一生都跟随父亲生活在学校地下室中，而一直呆在母亲身旁的洛德（艾瑞克·克里斯蒂安·奥森 Eric Christian Olsen 饰）则从未踏进过校园一步，两人的共同点只有一个，那就是他们都是常人眼中的“低能儿”。在偌大的校园中，“心心相惜”的两人迅速成为了朋友。 校长柯林斯（尤金·列维 Eugene Levy 饰）和女友赫勒（切里·奥特莱 Cheri Oteri 饰）想在学校内建立一个特殊教育班，可是，哈里和洛德却发现，柯林斯真正想要的，其实是政府的巨额教育拨款。无意中发现了柯林斯的阴谋，哈里和洛德十分着急，可是，又有谁会相信这两个呆瓜的“疯言疯语”呢？','The evolution of dumb...',19000000,39267515,15.67747,4.1,210,85,'2003-06-13','en','/fapSH52P98lCpBHXPMQaCFFwwEn.jpg',2.896620871814971,3,'2026-09-10',2,NULL,NULL),(10153,'深海圆疑','Sphere','南太平洋1000尺的深海海底，美国政府发现了一艘已有300年历史的神秘太空船。当局立刻组成了一队由心理学家诺曼·古德曼（达斯汀·霍夫曼 Dustin Hoffman饰）、生物化学家贝丝·哈波琳（莎朗·斯通 Sharon Stone饰）和数学家哈瑞·亚当斯（塞缪尔·杰克逊 Samuel L. Jackson饰）这三位顶尖科学家组成的科学小组前往当地调查。他们利用高科技的实验艇深入海底进行探测。然而船体内部的一个巨大而怪异的球状体，拥有着洞悉每个人的内心世界的强大魔力，它似乎能控制每个人的思想和行为。更糟的是，一个不明海底生物也向实验艇发起了攻击。  　　由美国著名导演、编剧巴瑞·莱文森执导的科幻悬疑电影《深海圆疑》，改编自迈克尔·克莱顿于1987年出版的同名小说。本片巨星云集，达斯汀·霍夫曼、莎朗·斯通 、塞缪尔·杰克逊等大牌明星联袂演出这部惊悚科幻影片。','A thousand feet beneath the sea, the blackest holes are in the mind...',75000000,13100000,18.65988,5.8,476,134,'1998-02-13','en','/reR7C7EYe3DiHm5OYpA0ACUMDld.jpg',3.1786009042958527,3,'2026-09-10',2,NULL,NULL),(10154,'黑帮女婿','Mickey Blue Eyes','米歇尔•法尔盖特（休•格兰特 饰）经营一间拍卖行，他是个温和的英国人，拍卖行的生意一向很好。他感觉成家的时候到了，便向他最爱的女友吉娜结婚。可是吉娜对结婚一词十分抗拒，她不愿意跟米歇尔结婚。这样使米歇尔疑惑极了，他认为女友是十分爱自己的，为何不能从此一同生活呢？ 直到后来，他才明白了吉娜的苦心。原来吉娜的父亲是一名黑帮老大，深爱着米歇尔的吉娜不愿自己的丈夫被卷进复杂的黑帮环境中。就算米歇尔向吉娜保证自己不会牵涉进去那些麻烦当中。 可是事情并不如人意，他还是因为这个黑帮岳父惹来了很多麻烦，甚至被警察调查。从此，米歇尔也莫名其妙的成为了黑道中人……','A romantic comedy you can\'t refuse',0,0,6.786117,5.3,140,102,'1999-08-16','en','/9paLy03Y9MbTeCyXkPuzvDZYvo2.jpg',2.8845925147967293,3,'2026-09-10',2,NULL,NULL),(10156,'History of the World: Part I','History of the World: Part I','An uproarious version of history that proves nothing is sacred – not even the Roman Empire, the French Revolution and the Spanish Inquisition.','Ten million years in the making. The truth, the whole truth, and everything, but the truth!',11000000,31672907,14.282314,6.5,204,92,'1981-06-12','en','/1bMaEfI76yrGjCSDquCippAFIDI.jpg',3.0477093805001356,3,'2026-09-10',2,NULL,NULL),(10159,'丛林奇兵','The Rundown','贝克（巨石 The Rock 饰）欠了比利一大笔高利贷，比利承诺只要贝克到亚马逊中部的黄金城把他辍学在外漂泊的儿子屈维斯（西恩?威廉?斯科特 Seann William Scott 饰）带回来即免除一切债务，贝克爽快地答应了。　　贝克在黄金城通过一名酒吧女招待玛丽安娜（罗莎里奥?道森 Rosario Dawson 饰）很快就找到了正在寻宝的屈维斯。就在他要带走屈维斯时，当地的黑社会老大赫切带着手下也来争夺屈维斯，原来屈维斯知道了当地的宝物“加托”的下落。贝克打跑他们后，带着屈维斯赶往机场回家。途中屈维斯企图开溜导致两人都落入了当地的叛军手中，原来玛丽安娜就是叛军首领，她也在寻找“加托”。为了顺利回家，他们只能答应先帮叛军找出“加托”……','cut to the chase',85000000,80916492,24.107835,6.4,514,104,'2003-09-26','en','/pi8lyTu8w1YN6DSsg9B1Wt4kHYp.jpg',3.2804217209213724,3,'2026-09-10',2,NULL,NULL),(10160,'猛鬼街5：猛鬼怪胎','A Nightmare on Elm Street: The Dream Child','被评为“最佳澳大利亚导演”并成功执导《24小时》等巨作，并在美国家喻户晓的著名惊悚片巨导史蒂芬·霍普金斯曾凭本片一举成名并且顺利杀入好莱坞。本片讲述在爱丽丝在上一集将弗莱迪打入地狱后，已经毕业并且和男友丹有了孩子，可怜的是她又染上了弗莱迪·克鲁格的杀人之梦。这次，弗莱迪想刺穿爱丽丝的未出生的孩子的心。他的意图是进现实世界“再次复活”；只有爱丽丝才能阻止他，她该怎么做？本片通篇充满一股诡异、阴森、悬疑的恐怖气氛，满是秘道、可怖异常、充满了哥特式风格的巨大的弗莱迪城堡为本片更添一份惊悚，情节紧凑且深具想象力，各种各样的特效镜头层出不穷，且本片对鬼王弗莱迪的身世也进行了全面复原，可看性极强，是系列中相当经典的一部，也是最为优秀的一部。','Now Freddy’s a daddy, he’s killing for two.',8000000,22168359,12.654051,5.5,245,89,'1989-08-11','en','/kizvpgXQfrAgN8FhOd87LbKk6kO.jpg',3.0118986010715108,3,'2026-09-10',2,NULL,NULL),(10162,'乐翻天','Waking Ned','杰克（伊安·邦纳 Ian Bannen 饰）和麦克（大卫·凯利 David Kelly 饰）做了一辈子的朋友了，彼此之间友谊十分的坚实。两人最大的梦想，就是能够赢得乐透大奖，从此过上不劳而获的生活，可惜这个梦想离他们似乎有点远，也并不太可能通过努力来实现。  　　一天，当乐透公司宣布了中奖号码后，杰克和麦克震惊的发现，获奖者就住在他们所在的小镇之上，然而，并没有人站出来领奖。经过了细心的排查，杰克和麦克将获奖者的目标锁定在了一个名叫奈德（Jimmy Keogh 饰）的老头身上，当他们赶到奈德家时，却发现他因为兴奋过渡已经死了。一个疯狂的念头出现在了两人的脑海里，他们决定冒充奈德的身份，领取这笔奖金。','How far would you go to win a fortune!',0,0,5.735912,7.4,54,91,'1998-09-15','en','/bsxiOOKC40HlhdIJYCUE2BkpJv0.jpg',2.7437207706174185,3,'2026-09-10',2,NULL,NULL),(10163,'天才除草人','The Lawnmower Man','到千年之交时，一种名为“虚拟现实”的技术将得到广泛应用，它能使人进入一个由电脑创造出来的、如同想象力般无限丰富的虚幻世界，它的创造者预测这种技术将为人类社会的发展发挥无数积极的作用，而有些人则担心它会被一些人利用，成为一种控制人类思想的新方法。','God made him simple. Science made him a god.',10000000,32101000,10.125029,5.4,197,108,'1992-03-05','en','/1VLqWcel87oYVmN383FgSH0mCTY.jpg',2.95973384289875,3,'2026-09-10',2,NULL,NULL),(10167,'黑狱风云','Half Past Dead','故事发生在美国旧金山湾的阿尔卡特拉兹监狱，这里关押的犯人都是身犯重罪，监狱里安装了最先进的设备，以防犯人越狱和暴动。最近死囚牢房中的一名犯人成了一些人注意的焦点。因为在他参与了一次抢劫行动后，价值2亿美元的黄金不见踪影，现在只要撬开他的嘴，就能知道黄金的下落。  　　有好几拨人都看上了这个“商机”，特别是高智商的大佬东尼，他以前是政府官僚，熟悉监狱里的情况，他安排了好几个人渗透到监狱里打探黄金的下落。FBI的密探萨沙潜入到监狱中，他的任务就是防止这笔黄金落到坏人的手里，于是在阴森的铁栅栏后面，智力和暴力同时上演了……',NULL,13000000,0,6.337063,4.6,82,98,'2002-11-15','en','/fJhudecoqyoZLoCwAZvqNPd7MK5.jpg',2.7618824622415112,3,'2026-09-10',2,NULL,NULL),(10179,'冰河急先锋','The Ice Pirates','The time is the distant future, where by far the most precious commodity in the galaxy is water. The last surviving water planet was somehow removed to the unreachable centre of the galaxy at the end of the galactic trade wars. The galaxy is ruled by an evil emperor (John Carradine) presiding over a trade oligarchy that controls all mining and sale of ice from asteroids and comets.','A totally SPACED adventure! ...You have to be there to see it.',9000000,0,3.810697,5.7,49,91,'1984-03-16','en','/tv2iZbQYWwKcWOUWVFxOhcchKZT.jpg',2.6841699943170116,3,'2026-09-10',2,NULL,NULL),(10183,'冰冻之河','Frozen River','本片讲述了雷·埃迪的故事，她是纽约上州一名拖车公园的母亲，在遇到一个住在美加边境保留地的莫霍克族女孩后，被卷入了非法移民走私的黑暗世界。丈夫带着购买新房的首付款消失后，雷一贫如洗，无奈之下与走私者莉拉结成了临时搭档。两人开始利用雷的道奇精神轿车的后备箱，载着非法入境的华裔和巴基斯坦裔移民，穿越冰冻的圣劳伦斯河。[索尼影业经典]',NULL,0,0,4.805651,6.7,99,97,'2008-08-01','en','/9Nwfz7f4OnzJmafiIC5oCOz2FWN.jpg',2.8658434400272705,3,'2026-09-10',2,NULL,NULL),(10184,'He\'s Just Not That Into You','He\'s Just Not That Into You','Remember that really cute guy who said he\'d call – and didn\'t? Maybe he lost your number. Maybe he\'s in the hospital. Maybe he\'s awed by your beauty, brains or success. Or maybe... he\'s just not that into you.','Are you the exception...or the rule?',40000000,177259441,26.253357,6.2,959,129,'2009-02-06','en','/qLYVjZohHup3nCIVnLRCWIuCpZ5.jpg',3.399785823502245,3,'2026-09-10',2,NULL,NULL),(10185,'午夜食人列车','The Midnight Meat Train','名不见经传的摄影师里昂•考夫曼为求拍摄到令画廊主人苏珊满意的震撼性作品，每晚穿梭于纽约街头的阴暗角落。某晚里昂跟踪几名黑人，并在铁铁站内营救了被这伙人骚扰的美丽日本女子，然次日便从报纸上得知该女子失踪的消息。里昂向警方提供线索，却遭冷遇。  里昂的这组作品受到苏珊赏识，同时好奇心又促使他继续追查多年来发生在某地铁线上的连续失踪案件。很快他便注意到一个经常出没地铁站、西装革履一脸严肃而又令人不寒而栗的神秘男人','The most terrifying ride you\'ll ever take',15000000,3533227,19.913961,6,290,98,'2008-08-07','en','/pGyFGgukbV9AmYOEILlvqRHGVSa.jpg',3.1015966865568756,3,'2026-09-10',2,NULL,NULL),(10186,'摇滚之王','The Rocker','“小鱼”罗伯特·菲什曼（雷恩·威尔森 Rainn Wilson饰）是名对摇滚极有热情的鼓手，他最大的幻想就是能成为一名超级摇滚巨星。可就是这个极度活跃一心玩儿摇滚的家伙，居然被自己组建的乐队毫不留情地除名了。罗伯特的摇滚之梦瞬间破灭了。二十年后，罗伯特侄子的高中乐队“A.D.D”要寻找一名新鼓手，受过伤害的他此时却是心灰意冷。可对于摇滚的热爱却将他们越拉越近，终于，罗伯特重操旧业，拿起尘封已久的鼓棒，惊艳四座。最终，他打败了以前的乐队，重新拿回“摇滚之王”的宝座。\r 本片是音乐天才泰迪·盖格的首部电影作品，更有雷恩·威尔森的“裸体演出”。','Opportunity rocks.',15000000,8762890,13.832376,5.6,156,102,'2008-08-20','en','/wzgFC7jOEMtf9D6CSdI7ckUMtwU.jpg',2.9362032180795326,3,'2026-09-10',2,NULL,NULL),(10187,'关键一票','Swing Vote','嗜酒如命的中年大叔巴德（凯文·科斯特纳 Kevin Costner 饰）刚刚因为醉酒被解雇了，每天玩乐度日的他对家事国事天下事事事无兴趣，却有一个精明早熟、极有主见的12岁女儿莫莉（玛德琳·卡罗尔 Madeline Carroll 饰）。眼看美国大选在即，按照巴德的前半生经历来看这事跟他八竿子打不着，因为他根本不懂选民资格也从未注册过。然而今年，莫莉却已经悄悄帮他办妥了一切申请，只需他手指一动。然而更出乎预料的是，由于投票机器的故障，巴德的投票竟变成了决定美国总统选举结果的关键一票。一时间各类媒体和候选人团队蜂拥而至，巴德父女俩至此被推到风口浪尖，从未涉足政界的小市民巴德将如何面对和判断这突如其来的局面，又将以怎样的方式投出自己的关键一票呢？','One ordinary guy is giving the candidates a reason to run.',21000000,17600000,5.815881,5.8,65,120,'2008-08-01','en','/aa5pWY2IVObKS7JZpfEw7Fe4FJk.jpg',2.749156058669124,3,'2026-09-10',2,NULL,NULL),(10188,'牛仔裤的夏天2','The Sisterhood of the Traveling Pants 2','经过16岁绚烂的夏天之后，这条神奇的牛仔裤一直轮流陪伴着卡门、堤比、莲娜和布莉姬四个挚友，她们把各自的经历作为图案绣在牛仔裤上，相互传递和分享着彼此的心路历程。3年时间过去了，四个女孩子进入了不同的大学，有了新的朋友，大一暑假即将来临，新的奇遇正在等着她们通话更不能这个夏天，布莉姬跟着考古队去了土耳其，一边探寻古迹一边不断询问自己的过去，陷入了失去妈妈的悲痛。莉娜与希腊男友分手以后，在学院里遇到了一个心动的男孩，犹豫要不要开始新的恋情。堤比为拍摄电影而忙碌着，与男友的关系进入敏感阶段，不自觉陷入了对爱情的恐慌。卡门因为朋友们暑假的缺席，加上妈妈为迎接新生命的无暇顾及，接受了去做戏剧节的幕后工作人员的邀请，期间不但被英俊男主角所关注，甚至还被推荐为女主角。这个夏天，将给四个女孩子带来更多惊喜。','Some friends just fit together.',27000000,44352417,11.870301,6,238,117,'2008-08-06','en','/ym7CD6Tv1TPJgmCIaDI1EXe9IwB.jpg',3.0417759493081604,3,'2026-09-10',2,NULL,NULL),(10189,'菠萝快车','Pineapple Express','戴尔（塞斯•罗根 Seth Rogen 饰）有一份令自己和别人都生厌的工作——传票递送员，高中生女友安吉的帅气男同学们又时时令戴尔如坐针毡，于是抽大麻成了他最好的寄托甚至是信仰。戴尔定期在小混混索尔（詹姆斯•弗兰科 James Franco 饰）的家中购买大麻，索尔视其为朋友，推销给他最好的大麻“菠萝快车”，可戴尔只拿对方当做比自己更失败的落寞者。当晚戴尔偶然撞见当地大毒贩瑞德和一名女警联手杀人，慌不择路逃跑的戴尔将菠萝快车这种罕见大麻遗落在现场，担心被瑞德杀人灭口的戴尔和索尔只得选择逃亡，但他们谨慎又笨拙的隐匿方式只是将更多人卷入这场风波，而逃避性格的两人，在这次事件中渐渐学会正视自己的弱点。','Put this in your pipe and smoke it.',27000000,101624843,41.832392,6.6,1148,111,'2008-08-06','en','/1C6rftqwQIL2h7sHwsIMAbBks1A.jpg',3.54895174338841,3,'2026-09-10',2,NULL,NULL),(10191,'驯龙高手','How to Train Your Dragon','As the son of a Viking leader on the cusp of manhood, shy Hiccup Horrendous Haddock III faces a rite of passage: he must kill a dragon to prove his warrior mettle. But after downing a feared dragon, he realizes that he no longer wants to destroy it, and instead befriends the beast – which he names Toothless – much to the chagrin of his warrior father','One adventure will change two worlds',165000000,494878759,67.263269,7.5,4227,98,'2010-03-05','en','/ygGmAO60t8GyqUo9xYeYxSZAR3b.jpg',4.1555275450894955,3,'2026-09-10',2,NULL,NULL),(10192,'Shrek Forever After','Shrek Forever After','A bored and domesticated Shrek pacts with deal-maker Rumpelstiltskin to get back to feeling like a real ogre again, but when he\'s duped and sent to a twisted version of Far Far Away—where Rumpelstiltskin is king, ogres are hunted, and he and Fiona have never met—he sets out to restore his world and reclaim his true love.','It ain\'t Ogre... Til it\'s Ogre',165000000,752600867,44.041186,6,1959,93,'2010-05-16','en','/rHHoU5vSCdX6xL6xGKJUyGblGXo.jpg',3.5558835164286937,3,'2026-09-10',2,NULL,NULL),(10193,'玩具总动员3','Toy Story 3','安迪已经高中毕业了，即将成为大学生，而他的玩具，包括胡迪、巴斯光年都面临将要被放在阁楼上的命运。在他们被放到阁楼之前，却意外的被丢弃，并被一个清理垃圾的人所捡起。玩具们发现自己被带到了一个当地的日间托儿所，他们必须要在那儿想办法面对一群调皮且粗鲁的学龄前小孩。胡迪打算要带领他的朋友们逃离托儿所，并为自己和他们找到一个新的安身之处。但巴斯光年在一次尝试逃离的行动中受到了损伤，使得整件事情变得更复杂了……','No toy gets left behind.',200000000,1066969703,59.995418,7.6,4597,103,'2010-06-16','en','/AbbXspMOwdvwWZgVN0nabZq03Ec.jpg',4.187290669839779,3,'2026-09-10',2,NULL,NULL),(10195,'雷神','Thor','即将继承阿斯加德王位的雷神索尔勇猛强大，却也傲慢冲动。当冰霜巨人闯入阿斯加德后，他不顾父亲奥丁的命令，擅自带领洛基、希芙等伙伴前往约顿海姆反击，险些重新挑起两个国度之间的战争。震怒的奥丁因此剥夺索尔的神力，将他连同雷神之锤放逐到地球。在新墨西哥州，失去力量的索尔遇到了天体物理学家简·福斯特和她的伙伴，并试图重新取回雷神之锤，却发现自己已经无法将它举起。与此同时，阿斯加德的局势也因洛基发生变化。被迫以普通人的身份生活在地球上的索尔，开始重新认识力量、责任以及真正成为王者所需要的品质……','Two worlds. One hero.',150000000,449326618,86.493424,6.6,6525,115,'2011-04-21','en','/prSfAi1xGrhLQNxVSUFh61xQ4Qy.jpg',4.070207538245365,3,'2026-09-10',2,NULL,NULL),(10196,'最后的风之子','The Last Airbender','《最后的风之子》的故事具有中国传统的神话色彩：世界被四大神力（气、火、水、土）支配着，其中被称为“神通”的便是世上唯一同时拥有这四种神力的人，他可以阻止邪恶的火烈国征服世界。然而令人不解的是，他在人们最需要他的时候，却神秘失踪了。千年之后，在南极还幸存着一个水族部落。水族勇士 Katara和她的哥哥Sokka从一个巨型的冰山洞穴里救出一个名叫Aang的12岁神秘男孩。他们发现原来“Aang”就是失踪已久的神通转世。“神通”被唤醒其体内的神力，最终与同伴一起踏上拯救人类的道路。','Four nations, one destiny',150000000,318502923,33.769336,4.7,1151,103,'2010-06-30','en','/cSUp3sm03PMmUxQfuPxlydXZSN8.jpg',3.182111794566903,3,'2026-09-10',2,NULL,NULL),(10197,'九','Nine','本片改编自百老汇的同名音乐剧。主人公圭多是一位电影导演，正在筹备他的第九部影片，他的前几部作品都遭遇了票房惨败，而对于这部新的电影，吉多也还没有想到合适的情节，事业面临困境。同时生活中与数个女人的复杂关系也让圭多一筹莫展，包括妻子、情妇、同事、母亲等等，让他不知该如何去平衡，他要怎样才能顺利度过这一段人生的低潮期呢？','This Holiday Season, Be Italian',80000000,53825515,9.357734,5.1,165,112,'2009-12-03','en','/oRLqjR3ivuYRiPa83w6EKjZCJm5.jpg',2.909108369793292,3,'2026-09-10',2,NULL,NULL),(10198,'公主与青蛙','The Princess and the Frog','蒂亚娜（Tiana）是个从不相信童话的女孩子，具有烹饪天赋的她最大的目标便是开一家属于自己的餐厅，多年来她一直努力赚钱，希望够自己的双手去实现梦想。可是就在她即将攒够钱的那天晚上，她遇到一只自称是王子马文（Naveen）的青蛙，他说自己是被影子人施了魔法并且许诺只要蒂亚娜吻他，那么他就可以帮蒂亚娜实现梦想。可是当蒂亚娜吻完青蛙，青蛙并没有变成马文王子，蒂亚娜却变成了一只青蛙。他们在躲避坏人的追赶时遇到喜欢演奏爵士乐的鳄鱼路易斯和荧火虫雷蒙，他们决定一起去密西西比河河口找女巫妈妈沃提帮忙。邪恶的影子人派出大批的影子杀手已经追上了这一行人，在紧要关头，妈妈沃提出现救了他们并且告诉了他们如果要变会人类，马文就必须去亲吻真正的公主夏洛特。可是此时马文在和蒂亚娜相处的过程中早已经爱上了这个执着的女孩子……','Every Love Story Begins With a Kiss...',105000000,267045765,62.479574,6.7,1247,97,'2009-12-08','en','/2PQ0iGFtpdoAjtt4M4prWXuoQbZ.jpg',3.6358435432670966,3,'2026-09-10',2,NULL,NULL),(10199,'浪漫的老鼠','The Tale of Despereaux','老鼠德佩罗（马修·布罗德里克 Matthew Broderick 配音）自幼体弱多病，却拥有两只硕大无比的耳朵。童年在图书馆度过，慢慢的开始学会了认字，学会了阅读，他喜欢童话故事中那些英雄救美的故事，常常幻想自己也能成为一个英勇的骑士，在美人落难时拔刀相助。一次外出中，德佩罗认识了豌豆公主（艾玛·沃特森 Emma Watson 配音）。渴望成为英雄的德佩罗，因为触犯了鼠国严苛的律条被父亲勒斯特（威廉姆·H·麦西 William H. Macy 配音）驱逐。在多尔王国外的广袤土地上，德佩罗认识了同样被自己国家驱逐的老鼠罗斯库洛（达斯汀·霍夫曼 Dustin Hoffman 配音）。  不久之后，流放的德佩罗得知豌豆公主被关入地牢，对公主心怀爱恋的德佩罗决定决一死战救出公主，会战胜邪恶赢得自己该有的爱和尊严吗？  本片根据美国著名儿童文学家凯特·迪卡米罗的同名小说改编。','Small Mouse. Big Dreams',60000000,50877145,16.493576,5.8,258,93,'2008-12-19','en','/zGmK7Sidr4GZNik29n5lqbPYodU.jpg',3.0535781399695483,3,'2026-09-10',2,NULL,NULL),(10200,'地球停转之日','The Day the Earth Stood Still','一个从银河系某个星球出发的飞碟向地球无限靠近，最后选择在美国纽约着陆。面对这样一个看似不友好的天外来客，美国警方给出了强烈的回应和攻击。其实来自外星球的智慧生命克拉图踏上地球并非有入侵的妄念，而是带着警示来告知人类－－如果再有“挑衅”之举，践踏和平，地球将惨遭灭亡。随他一同到地球“造访”的还有一个具有超级强悍的机器人戈特，他具有的超级能量能将人类轻易“放倒”。\r 着陆后，这两个天外来客被警方带到了一个地方进行盘问，警方不友好的行为使得克拉图最终自己从这里逃走。通过与人类的交流和沟通，克拉图开始学习关于地球和人类的诸多知识，也让他对这个人类栖居之地有了了解。一个偶然的机会，克拉图遇到了海伦·班森和她的儿子波比，并在这母子俩的带领下开始了他的纽约之旅。克拉图最终在在林肯纪念堂前驻足，因为他看到了林肯在很久以前发表的文字，而他知道这将是拯救地球的希望。\r 当母子俩开始对克拉图产生怀疑时，克拉图直言不讳地告诉了自己和戈特此行的目的。原来戈特是银河系超级机器人执法小组的成员，他们以捍卫宇宙和平为己任。他们认为人类对宇宙的和平危机越来越深重，因此有必要对地球进行摧毁。\r 较量开始了，克拉图在林肯纪念堂前看到的那一段文字“Klaatu barada nikto”果真是解救人类的密码吗？这场地球毁灭战会打响吗？地球真的会惨遭灭绝？谁将会是最后的救世主？','12.12.08 is the Day the Earth Stood Still',80000000,233093859,41.890722,5.2,1043,104,'2008-12-10','en','/hXd1dBiAwGOXjYpzAVvoq1JOlo8.jpg',3.277619032429936,3,'2026-09-10',2,NULL,NULL),(10201,'好好先生','Yes Man','卡尔·阿伦 很长一段时间以来都诸事不顺，因为他总是以消极的“不，不行”式的态度跟人打交道。直到他参加了一个自助课程才有所改变，他在导师泰伦斯的压力下发誓：在一年时间里都只能说“好的”，而不管对方是谁，要求他做的是什么事情。令他惊奇的是，当他开始实践自己的誓言的时候，生活发生了不可思议的变化，他不仅得到了升职，赢得了45000美元的奖金，得到了一只人人爱的小狗，获得了护理学的学位，甚至一次环游世界的大好机会也落到他头上，但这些还不是最美妙的，最终，他还与一个叫蕾妮的美丽女孩 共堕爱河。然而，当他满怀信心地准备拥抱更多的机会时，却没有预料到，他根本消受不了如此之多的好事。','One Word Can Change Everything.',70000000,225990978,43.849351,6.4,1813,104,'2008-12-09','en','/lXCFAATroa1RJNC7pv12x5USoWx.jpg',3.624767305064158,3,'2026-09-10',2,NULL,NULL),(10202,'睡前故事','Bedtime Stories','在斯基特（亚当·桑德勒 Adam Sandler 饰）小时候，凝聚着父亲心血的旅馆被转卖给了诺丁汉。诺丁汉将旅馆改造成酒店，并承诺斯基特长大后交还给他经营。为了这一承诺，25年后斯基特还在酒店里勤勤恳恳的做着杂役，却听到诺丁汉将新酒店总经理指名给别人的消息。  　　沮丧的斯基特把自己的遭遇和期望编成睡前故事讲给侄子侄女听，原本天马行空的故事情节竟一一应验在现实中，令斯基特欣喜不已。他决定利用故事达成夺回酒店的期望。但孩子们对他刻意安排的故事内容百般挑剔，迫使现实也朝着意外的走向发展……','Whatever they dream up... he has to survive.',80000000,212874442,23.531721,5.9,901,99,'2008-12-24','en','/qt0bHqfVpjB3weR2PoeCcPNNKEJ.jpg',3.32986801215492,3,'2026-09-10',2,NULL,NULL),(10204,'环游地球八十天','Around the World in 80 Days','如果这是在公元2004年，那么一定会有人确信制定如此环游世界计划的一定是个时间充裕腰缠万贯的阔绰之人。不过事实上的旅行远没有想象中的悠闲自在，故事中的主人公个个累得要死，几乎没有半秒喘息时间。因为这是发生在没有飞机、没有远洋轮船、也没有新干线的凡尔纳的1872年，是一个只能利用热气球、火车、马车、游艇、商船、雪橇甚至大象作交通工具的1872年。','Let your imagination soar.',110000000,72178895,22.643776,5.7,672,120,'2004-06-16','en','/pjCx8xhCCFr02jxbQDp7sAPVgEr.jpg',3.2401154722234824,3,'2026-09-10',2,NULL,NULL),(10207,'瓶中信','Message in a Bottle','特丽莎（罗宾•莱特•潘 饰）离婚后，儿子是她的珍宝。她是一名专栏作家，为了给儿子好的生活，她工作勤劳。一天她在海边跑步的时候，捡到了一个玻璃瓶，里面竟有一封信。特丽莎深切的感受到了写信人心痛的感觉，阴差阳错之间这封信被刊登在了报纸上。读者反应热烈，为了乘胜追击，报社派出特丽莎寻找这封信的主人。写信的人名叫盖瑞（凯文•科斯特纳 饰），自从妻子凯瑟琳离世之后，他每天都活在悲伤的阴影中，用信表达自己对妻子的爱意。特丽莎还是见到了这名伤心的男子，也没有告诉盖瑞她看过他写的那些瓶中信。两人相处的过程中，特丽莎知道自己已经爱上痴情的盖瑞，盖瑞也因为特丽莎的出现，生活多了许多生气。面对已经逝世的爱妻，与就在面前的特丽莎，盖瑞会如何选择……','A story of love lost and found.',80000000,118880016,10.81051,5.8,196,131,'1999-02-22','en','/7NDgWn9qlO8pOguosmiF0r4PqQ1.jpg',2.9858248587947727,3,'2026-09-10',2,NULL,NULL),(10208,'太空木偶历险记','Muppets from Space','当 Gonzo 的早餐麦片告诉他，他是来自另一个星球的外星人的后代时，他试图与外星人沟通，结果被一个秘密政府机构绑架，促使布偶们开始行动。起初很难相信 Gonzo 的故事，但 Kermit 和朋友们很快就发现自己踏上了一段史诗般的外太空之旅，充满了星际间的不幸。','Space. It\'s not as deep as you think.',24000000,16290976,6.589193,5.8,92,87,'1999-07-14','en','/Aww9cF4uMsbald9ddhCYFoP4gBi.jpg',2.82255846643038,3,'2026-09-10',2,NULL,NULL),(10212,'战地恶魔','Ravenous','在十九世纪的美国与墨西哥战役中，陆军上尉约翰鲍尔因为表现懦弱，被军方派往荒芜的内华达山脉前哨基地驻守，与一群乌合之众的劣等士兵过着无聊透顶的生活。后来一名苏格兰男子艾维斯闯入了军营，他交代自己本来与一队人同往此地，但在途中遇大风雪，众人躲到山洞中栖身。在饥寒交逼下，他们竟互相残杀吃起人肉来，只有艾维斯逃出这个疯狂的山洞。鲍尔上尉闻讯后带队到山洞查察，不料艾维斯竟然是食人魔。本片的故事看来像是低劣的血腥恐怖片，其实拍得相当严肃，对战争与生存的主题有发人深省的探讨。导演安东尼亚贝特的快节奏处理毫不拖泥带水，后段更拍出了黑色喜剧感。两名主角盖皮尔斯和劳勃卡莱尔都演出特色。','You Are Who You Eat',12000000,0,9.164386,6.9,141,100,'1999-03-16','en','/5f7pY4Uzyt4ZNWhHyd1dJhIF4Gc.jpg',2.9691684451261704,3,'2026-09-10',2,NULL,NULL),(10214,'变相怪杰2：面具之子','Son of the Mask','提姆·艾弗瑞（杰米·肯尼迪饰）是一个具有远大抱负的漫画家，他与妻子杜雅（泰勒·霍华德饰）住在一个卡通味十足的小房子里。杜雅十分想要一个孩子，但是一心想要事业成功的提姆却认为操之过急。一天，他的狗狗发现了一个绿色的面具。一天晚上，提姆在去公司举办的万圣节派对前戴上了那个丑陋的面具，戴上之后的他完全变了一个人，具有了神奇的魔力和无法自控的疯狂，原来这个面具是整蛊之神洛基的道具。在舞会上，所有人都被他的“装扮”所吸引，而他那些怪异的举动在一帮动画师眼里看来也是绝对正常的，在场的人都认为他在试图创造一个新的卡通角色。老板则立即下放权利，让他去独自创作。当回到家后，妻子躺在床上，也许是因为他一直压抑的感情被面具释放出来，或者是他还在为刚刚的奇迹而兴奋不已，此时的他极其想要一个孩子。\r 九个月后，孩子威仔出生了，并且具有变相怪杰的超能力。这立即引起了面具的主人“恶作剧之神”洛基（艾伦·卡明饰）的注意，他的父亲——独眼的奥丁神（罗伯·哈斯金斯 饰）命他将面具夺回来，所以洛基开始查询所有在那天出生的孩子。因为如果惹毛了父亲的话，那后果就无法想像了。\r 此时，提姆也在找面具，因为他的狗狗把面具给藏了起来。提姆不知道为何他的孩子具有如此超强的能力，他只想尽快找到面具，来完成老板要求的卡通人物的创作。此时洛基离他们越来越近，杜雅也因商务出差离开了小镇，只留下提姆扮演全职父亲的角色。当威仔已能渐渐掌握这股超能力时，洛基也终于找到了这家人。','Who\'s next?',84000000,0,17.815595,3.6,338,94,'2005-02-18','en','/wuSGQIlRJM1S72chLt6GqNGTVGI.jpg',2.900668842684041,3,'2026-09-10',2,NULL,NULL),(10215,'双面情人','Sliding Doors','滑动门是指地铁或者电梯那种自动关闭的门，快一秒你可能搭上，慢一秒可能就错过了。这是日常生活中再普通不过的现象，可是你有没有想过：搭上或者错过，意味着会遇到不同的人、发生不同的事，生命可能就此改变...... 海伦是个公关经理，与写小说的男友杰瑞住在伦敦。这天海伦和平常一样早起上班，没想到会因意外而遭革职。比平常早回家的她走在伦敦的地铁站里，车子靠站时搭上或者错过地铁使她的人生走向不同的旅程： 两个过程  : (1)海伦搭上了地铁... ... (2)海伦错过了地铁...','What if one split second sent your life in two completely different directions?.',6000000,58000000,15.639016,6.5,354,99,'1998-04-23','en','/iHVz46MCjC4cCqh9tnBZVtGkOTu.jpg',3.1826271720419683,3,'2026-09-10',2,NULL,NULL),(10217,'甜蜜的来世','The Sweet Hereafter','一个冬日，不列颠哥伦比亚省山姆登特小镇发生惨剧：一辆校车离奇坠入冰湖，十四名孩童丧生，多人受伤。不久后，大城市律师米切尔·斯蒂芬斯来到小镇，承诺为居民争取损失赔偿。[Fine Line Films]','There is no such thing as the simple truth.',5000000,3263585,7.673124,6.8,103,112,'1997-05-14','en','/gJy7LMq4b5qO5fsSUSoBgm24BHf.jpg',2.885372814707676,3,'2026-09-10',2,NULL,NULL),(10218,'摇摆者','Swingers','Mike是一个星运欠佳的演员，为明星梦只身奔赴好莱坞打算最后碰碰运气。离开家乡纽约的同时，也被迫与交往了6年的女朋友分手。此后Mike一直无法忘怀，每天生活在郁郁寡欢中。他的朋友们决心将他拉回到正常的社交生活中。其中Trent号称“情场鬼见愁”，他拉上Mike，两人从拉斯维加斯玩到洛杉矶，Trent与见到的每一个女人调情，试图改变Mike的绅士作派。Mike虽然也随着Trent一起玩，但他心里仍存有对爱情的渴望，释放自我的Mike终于明白了自己要的是什么。','Cocktails first. Questions later.',200000,4505922,13.971674,6.8,253,94,'1996-10-18','en','/rRjWk68kU3a2so4lgr3TKB7Y5vA.jpg',3.121273518214842,3,'2026-09-10',2,NULL,NULL),(10219,'落在香杉树的雪花','Snow Falling on Cedars','1950年，美国某岛上的一位当地居民卡尔夜间出海捕鱼时身亡，警长认为此事疑点诸多，颇有排日倾向的法医将日裔居民宫本一雄牵入此案，法院随即对宫本展开审判，岛报记者伊斯梅尔（Ethan Hawke 饰）因个人关系对审理十分在意，原来宫本之妻金田初枝（工藤夕贵 饰）是伊斯梅尔青梅竹马的恋人，后来美日宣战，岛上的日裔居民开始遭受排斥，金田一家也受到了不公对待，被遣往集中营看押劳动，伊斯梅尔仗义执言反被同胞威胁，这段恋情不得不随之终结。伊斯梅尔查询事发当夜岛上的天气记录，得到了比尔是死于意外的重要证据，但这就意味着他与初枝的复合再无可能。随着审判的进行，越来越多的证据指向宫本，同时平息不久的战争让当地人对日裔怀着有色眼镜看待，伊斯梅尔反复考虑做出了最后的决定……\r 　　本片获2000年芝加哥电影评论协会奖最佳摄影奖等多项褒奖。','From the director of \'Shine\'',0,0,2.79483,6.3,32,127,'1999-12-22','en','/h1CujbeKvwkR6LMr4jVuMM0C94X.jpg',2.6017890147425473,3,'2026-09-10',2,NULL,NULL),(10220,'赌王之王','Rounders','迈克( 麦特戴蒙饰)虽然一直以赌博为生．但是他决定要洗心革面脱离扑克生沥，并且进入大学就读法律，虽然这样的改变让他朝向成功之路迈进，不过这一切都比不上扑克牌赌局来得惊险刺激。同时迈克也答应他的红粉知己而且也是他同班同学乔(葛瑞程摩儿饰)，他再也不涉足赌场。可是当他最要好的朋友渥姆(艾德华诺硕饰) 出狱来投靠他时，使得迈克他不得不重操旧业．因为渥姆积欠了黑道一笔钱，他必须在最短的时间内得到这笔钱，否则渥姆就要以命抵偿。麦克在迫不得已的情况之下，只好回到投资报酬率最快，风险也最高赌场，如果他们不在五天之内拿到一万五千元美金，他们的命就风于地下钱庄的…','Trust everyone... But always cut the cards.',12000000,22921898,18.422008,6.9,439,121,'1998-09-11','en','/ac91MjvT7ohuJ54aK1pF1B6Krf.jpg',3.2864153817748565,3,'2026-09-10',2,NULL,NULL),(10223,'绝地计划','A Simple Plan','唾手可得的财富诱惑，打破了两个兄弟平静的乡村生活——当他们在小型飞机坠毁的偏远现场发现超过四百万美元现金时，贪婪、偏执与猜忌喷涌而出。[派拉蒙影业]','Sometimes good people do evil things.',0,0,10.178917,6.9,187,121,'1998-12-11','en','/wO2gH7DMqpMeHlj5QmDhW4IkgAr.jpg',3.042365431277816,3,'2026-09-10',2,NULL,NULL),(10225,'Friday the 13th Part VI: Jason Lives','Friday the 13th Part VI: Jason Lives','As a child, Tommy killed mass-murderer Jason. But now, years later, he is tormented by the fear that maybe Jason isn’t really dead. Determined to finish off the infamous killer once and for all, Tommy and a friend dig up Jason’s corpse in order to cremate him. Unfortunately, things go seriously awry, and Jason is instead resurrected, sparking a new chain of ruthlessly brutal murders. Now it’s up to Tommy to stop the dark, devious and demented deaths that he unwittingly brought about.','Kill or be killed!',3000000,19472057,11.158167,5.7,216,86,'1986-08-01','en','/qSg1lBg9rwNwcEVp2CB9WtytWZn.jpg',2.999189520081091,3,'2026-09-10',2,NULL,NULL),(10226,'高压电','Haute Tension','青春少女玛丽和爱莉西娅是同在法国巴黎一所大学就读的好朋友。某个周末，两人驱车前往爱莉西娅家位于乡下的农场度假。适值深夜，万籁俱寂，玛丽寂寞难耐正在自我宣泄之时，一个不速之客突然闯入。他残忍杀害了爱莉西娅的父母和年幼的弟弟，并将其掳去。为了营救好友，玛丽悄悄钻进凶手的卡车。途经一个加油站，她换上同样惨遭杀害的店员的车继续跟踪，却被狡猾的凶手发现行迹。一场近乎迷幻的猫鼠杀戮游戏旋即进入高潮……','Hearts will bleed.',0,0,4.952983,6.6,271,91,'2003-06-18','fr','/9RbmSeq0cuLGYBQDw2IA6UfkVvf.jpg',3.102027982904457,3,'2026-09-10',2,NULL,NULL),(10229,'初恋的回忆','A Walk to Remember','兰顿·卡特（夏恩·韦斯特饰）生活在北卡罗莱纳州的一个海港小镇，是镇上首富的独生子，他是典型的坏小子，不好好读书还整天和镇上几个吊儿郎当的家伙一起疯玩疯闹。一次，兰顿和他的几个哥们儿恶作剧地诱骗一个新来的插班生跳进水泥厂的大池子里，没想到黑暗的池子里堆放着废弃的钢管，结果插班生满身鲜血地爬了上来。意识到玩笑开大了的男孩们全都吓跑了，只有兰顿多留了一会儿安慰受伤的孩子，于是，他成了唯一被抓住的“凶手”。 　　虽然侥幸逃脱了牢狱之灾，但兰顿还是被判罚做义工——给邻近小学的学生作家教并且参加学校的春季汇演，这对他来说简直比蹲监狱还难受。可是，就是这个偶然事件，让兰顿结识了他这一辈子都不会忘记的女孩--杰米·苏利文（曼迪·摩尔饰），杰米是镇上牧师的女儿，是个典型的乖乖女，她经常利用课余时间自愿作义工，自然认识了兰顿，起初，他对这个差点儿害死一条人命的家伙嗤之以鼻，渐渐地，她发现兰顿并不像她想象的那样坏。随着两人逐渐深入的交往，他们竟然不可思议地坠入了情网，这让简直所有熟悉兰顿和杰米的人都大跌眼镜。 　　杰米的真诚、善良、纯洁和她对生活的热爱每天都在感染、改变着兰顿，他慢慢地厌倦了自己以前的那种生活，开始追求自己的理想和信仰，但在这时，杰米的父亲却扮演了棒打鸳鸯的角色，不相信像兰顿这样的孩子会真正爱上自己的女儿。兰顿到底该如何向女友的父亲证明自己的真爱呢？这段灰姑娘与坏小子的恋爱会如何收场呢？','She didn\'t belong. She was misunderstood. And she would change him forever.',11000000,41227069,33.283554,7.5,1018,101,'2002-01-25','en','/8lUYMvWdHA0Q0k5F76RQCeCBUkA.jpg',3.6565102782406913,3,'2026-09-10',2,NULL,NULL),(10238,'呼喊与细语','Viskningar och rop','艾格尼丝（哈里特·安德森 Harriet Andersson饰）、玛丽亚（丽芙·乌曼 Liv Ullmann饰）和卡琳（英格里德·图林 Ingrid Thulin饰）虽然是三姊妹，各人内心却有着积重难返的隔膜和疏离。艾格尼丝身患绝症，生命将近，守护在她身边的是女仆安娜。艾格尼丝没有得到过母亲完整的爱，死前妄想让关系紧张的姐妹变得珍爱彼此，却一再事与愿违。\r 　　玛丽亚是最得母亲宠爱的孩子，因此遭到姐妹的嫉妒。她的感情生活处理的一塌糊涂，在丈夫和情人之间徘徊周旋。她对爱越是拥有，就越是贪婪。\r 　　卡琳的生活更是充满压抑。和丈夫的关系陷入僵局，令她沉沦于自虐。\r 　　和好的愿望太过遥远，她们想摆脱生活的阴影，重新拉近彼此的心，却发现隔膜似乎不可打破。','A haunting and shattering film experience.',0,0,11.347855,7.8,115,91,'1972-12-21','sv','/cYQJtOdnTodVUOzUUZUYM0GyYTP.jpg',2.9609538460959604,3,'2026-09-10',2,NULL,NULL),(10246,'留校查看','Porky\'s','六个极具叛逆搞笑的高中生成群来到恶名昭彰的波基脱衣酒吧，只为了满足一下性幻想，但由于未成年被酒吧老板扫地出门。为了实现愿望，于是他们精心策划了一个让酒吧老板永远难忘的复仇行动……','Keep an eye out for the funniest movie about growing up ever made!',4000000,125728258,12.891276,6.1,183,94,'1981-11-13','en','/AqCOt1cWfKqCepxK7LIdT812idH.jpg',2.9948780681804084,3,'2026-09-10',2,NULL,NULL),(10253,'龙之战','디 워','朝鲜古老传说中，天界生活着许多巨蟒，它们中间德行最高的将有机会变成龙。每五百年会有一名女性被选中，她将利用龙珠（Yeouijoo）帮助巨蟒实现向龙的蜕变，可是邪恶之蟒布那基（Buraki）处心积虑要夺取正义之蟒蛇伊莫吉（Imoogi）手中夺取化龙的机会，为此不惜召唤魔兽大军攻掠拥有龙印少女所在的城池。少女和保护她的恋人逃亡寻找伊莫吉，但男孩却违背誓言，一切以悲剧收场。  五个世纪过去，童年时代曾听说过巨蟒传说的新闻记者伊森·肯德里克（杰森·贝尔 Jason Behr 饰）意识到，发生在洛杉矶的一连串神秘事件都与布那基（Buraki）和龙印少女有关。及至与女孩萨拉（阿曼达·布鲁克斯 Amanda Brooks 饰）邂逅后，一切似乎变得愈加明朗。穿越了数个世纪的龙之战，正义与邪恶的战火再次点燃……','They\'ve made our world their battleground',70000000,53587404,4.822033,4,104,90,'2007-02-08','ko',NULL,2.776209668157583,3,'2026-09-10',2,NULL,NULL),(10269,'燕特尔','Yentl','故事改编自以撒辛格的短篇小说，描述犹太人女子杨朵在二十世纪初的东欧为了追求梦想而女扮男装求学的故事。在20世纪初，家住东欧的犹太女孩燕特尔非常好学，但当地的风俗禁止女孩上学，于是她只好女扮男装。在学校，有一个男生跟她很要好，但他俩的关系涉及到性取向错乱的议题。',NULL,12000000,30400000,3.389249,6.2,51,132,'1983-11-18','en','/AcCX4tKqwP5BTfRTQEqZW3qabl3.jpg',2.7012412502441823,3,'2026-09-10',2,NULL,NULL),(10279,'山姆的夏天','Summer of Sam','1977年夏天的纽约市发生了历史上第一次连续杀人事件。小报为了增加发行量，纷纷称这位让市民人心惶惶的凶手为「山姆之子」。  　　为了尽早揪出十恶不赦的变态杀人狂，一位黑手党的老大决定悬赏「山姆之子」。乔依与他的狐朋狗友们开始加入缉捕凶嫌的活动。他们把心目中所认定住家附近的变态全列举出来，开使始猎杀的活动。他们锁定一位庞克滚小牌明星，瑞奇为对象，为终结他们恐惧的代羔羊！','No one is safe from son of sam',0,0,3.70789,6.3,112,142,'1999-07-02','en','/yvGGA2CbT6xyFVTZUA9f2ok0q5V.jpg',2.876283000954892,3,'2026-09-10',2,NULL,NULL),(10280,'瘦到死','Thinner','律师比利（罗伯特·约翰·伯克 Robert John Burke 饰）是一个体型硕大的胖子，他一直都在减肥，但从来没有成功。作为一名颠倒黑白的律师，他和检察官及法官的暗地勾结让他获得了不小的成功。一次交通意外中，比利撞死了一个吉普赛老妇人。在法庭上，借由职务之便，比利通过非法的渠道获得了无罪判决，对受害者亲人的愤怒和悲痛视若无睹。从此之后，好运似乎降临在了比利的身上，一直以来令他困扰的体重居然开始下降，同时，他还可以毫无顾忌的敞开肚子品尝人间美食。事态的发展逐渐超出了可控制的范围，短短几天之内，比利已变成一个骨瘦嶙峋的苍老男子，并且他的体重仍然在持续的下降，而参与不公正审判的同僚们也都出现了不同的病变，这令他明白，吉普赛人的诅咒并非空穴来风，而为了求生，他必须找到下诅咒的那个吉普赛人，并且请求他的原谅。','Let the curse fit the crime.',0,0,7.866961,5.5,124,92,'1996-10-25','en','/f5z2D9GjD3VFqn76t6LXAJSo5A.jpg',2.8734729121596474,3,'2026-09-10',2,NULL,NULL),(10281,'十三号星期五7：新血','Friday the 13th Part VII - The New Blood','在汤米·贾维斯(Tommy Jarvis)把杰森炼锁在水晶湖底多年之后，一位有特异功能的年青人又不小心把杰森放了出来，杰森于是又回到了水晶湖营地重操旧业。','Jason is back, but this time someone\'s waiting!',2800000,19170001,9.070842,5.3,192,88,'1988-05-13','en','/rUzk9Qnyz2FZGxHMBrq6DYIQZkO.jpg',2.94642809292632,3,'2026-09-10',2,NULL,NULL),(10283,'十三号星期五8：杰森侵入曼哈顿','Friday the 13th Part VIII: Jason Takes Manhattan','当夜色笼罩，纽约变身为罪恶之城，在羞于见光的角落里，自有一群人按照自己的阴暗方式生存着……杰森的尸体静静的留在湖底，直到这天，一对游船上的情侣无意中将湖底的电缆割断，流泄的电能将杰森再度唤醒，杀人狂翻身上船，顺手杀死了情侣。同时，一艘开往纽约的游船在码头即将起航，古板严苛的教师查尔斯（彼特·马克·里奇曼 Peter Mark Richman 饰）与一班学生们将搭乘该船前往曼哈顿。杰森潜行到了大船上，按部就班残杀每一个落单的乘客，当船长也被杰森杀害后，幸存的人们终于意识到危险降临，他们试图团结一致对抗杰森，这次前往曼哈顿的流程，变成了不折不扣的生存考验……','The Big Apple\'s in BIG trouble!',5000000,14000000,12.904615,4.8,191,100,'1989-07-28','en','/6ezOsZ9UzqGnbDokaatxdOWP6e9.jpg',2.9231063834116795,3,'2026-09-10',2,NULL,NULL),(10285,'十三号星期五9：杰森下地狱','Jason Goes to Hell: The Final Friday','美国水晶湖地区系杀人魔王＂杰森＂的出生地，由于杀人魔连续残害无辜的善良百姓，警方于是布下天罗地网，终于将杰森逼至一隅，并以强大的火力将他击成碎片。警方人员误认杰森已死，便宣布结案，不料杰森藉著验尸官的躯体，再度肆虐。警方经过调查发现杰森以后可能的受害目标便是他的姑姑黛安及表妹蕾贝卡，原因便在杰森可利用亲戚的身体重生，但相对的杰森家人亦拥有摧毁杰森的特异能力。杰森虽然出其不意的杀了黛安，但蕾贝卡却和友人顽强反抗，终于把杰森送入万世沉沦，永劫不复之地狱……','Evil has finally found a home.',3000000,15938065,10.341982,4.2,193,87,'1993-08-13','en','/Aacq05foqiWdXqetFv02HBvMoJy.jpg',2.8811236616880396,3,'2026-09-10',2,NULL,NULL),(10288,'僵尸管家','Fido','近未来的某天，一场规模巨大的宇宙辐射风暴席卷地球。受辐射影响，地下场面的死尸纷纷复活，变成嗜血如命的恐怖僵尸。血雨腥风，地球顿成人间炼狱。经过许多年的抗争，人类渐渐占据主动，掌握摧毁、控制僵尸的办法。于是一家专营出售和租赁业务的僵尸公司应运而生。威拉德镇，罗宾森一家终于成为最后一个拥有僵尸仆人的家庭。这个名叫Fido的僵尸悉心照顾怀孕的罗宾森夫人，帮助11岁的小男孩提米赶走欺负他的同学。与散漫且憎恨僵尸的罗宾森先生相比，Fido俨然是这个家中新的主人……','Good dead are hard to find',8000000,426224,5.244518,6.6,135,91,'2006-09-07','en','/hKUUn6f4Hxj5iqQKMlQzRqbg2yT.jpg',2.935392925251884,3,'2026-09-10',2,NULL,NULL),(10306,'鬼驱人3','Poltergeist III','希瑟．奥鲁克依旧饰演恶鬼企图掳走的目标，可惜她本人在本片公映前四个月就得了怪病去世，当年曾引起了一阵议论。本片中，希瑟搬去跟舅舅汤姆·斯凯里特和舅母南希·艾伦一家同住，但怪事仍不断发生，这一次恶鬼透过镜子作媒介将希瑟及汤姆的女儿捉进阴间，女巫泰珍妮前来协助，并给以护身符。汤姆因不听劝告而陷入险地，但南希却以爱心和勇气身入虎穴说服了恶鬼，得以跟亲人团圆。','He\'s found her.',10500000,14144000,11.225044,4.5,123,98,'1988-06-10','en','/pLewUibOJLGISvMqB94mAMdjz2q.jpg',2.8362448885763873,3,'2026-09-10',2,NULL,NULL),(10307,'圣痕','Stigmata','20來歲的法蘭姬裴吉是個年輕的美髮師，在她身上發生了一些怪事。有一隻看不見的魔手將焦點鎖在這位美麗的女子身上，她用盡各種方法阻止這些可怕事情發生，可是情況卻越變越糟。這種精神上的折磨，讓她找遍了各種心理醫生和心裡輔導員，都不能回答一個最重要的問題：為什麼會是她？  法蘭姬裴吉的事情起梵諦岡一個官員的注意，於是他派一名神父前往調查此一靈異事件，神父在目睹附身在法蘭姬身上的邪惡力量後，他了解此時這是他最刻不容緩的責任......！','The messenger must be silenced.',29000000,50041732,14.993169,6,242,103,'1999-09-10','en','/sKS1Vuqj7OQpOumfs6ArC0TICTN.jpg',3.0524084256085384,3,'2026-09-10',2,NULL,NULL),(10312,'心灵点滴','Patch Adams','亚当（罗宾•威廉斯 饰）想成为一名医生是在他的精神疾病痊愈之后，后来他进入了维吉尼亚医学院学习。可是院内的传统观念的限制使医生们开来都十分不近人情。他不屑于这种状态，于是他把欢笑看做是医治病人的一个重要处方。他总是穿着鲜艳的衣服，带着滑稽的装扮到学院去，为的就是能让每一位病人都开怀大笑。\r 校方对亚当的行为十分不满，但他还是冒着被勒令退学的危险坚持着自己那套理念。亚当需要克服的东西众多，从医路上又将有不同的挑战与不同的人与事在等着他，亚当仍不懈的为着梦想前行。','Laughter is contagious',50000000,202292902,35.537397,7,832,115,'1998-12-25','en','/qV9qUiuC0LrPN1VBCFCgkJTTAIo.jpg',3.5172228619624923,3,'2026-09-10',2,NULL,NULL),(10313,'以眼杀人','The Men Who Stare at Goats','鲍勃·维尔登是个婚姻失败的美国记者，绝望中来到中东，试图设法潜入伊拉克进行战地新闻报道以赢回前妻芳心。鲍勃在科威特遇到了以前采访中听说过的私家建筑商林恩·卡萨迪，苦苦哀求后者带他过境。林恩曾是美国陆军“地球精神部队”的特种兵，在越战老兵嬉皮比尔·迪昂格的特殊训练方法下寻求“绝地武士超能力”，以精神意念战胜敌人；直到军人拉里·霍珀的加入改变了“地球精神部队”的训练方针。鲍勃跟随林恩在伊拉克经历了一系列令人啼笑皆非的事故与事件，到底林恩是否真有“绝地超能力”呢？','No goats. No glory.',24000000,68729358,20.69219,5.9,742,93,'2009-10-17','en','/hr9XmzDDQmyUzBh6n7kt0dlmllH.jpg',3.284356330787208,3,'2026-09-10',2,NULL,NULL),(10314,'窈窕美眉','She\'s All That','长相帅气成绩优异的扎克（小弗雷迪·普林兹 Freddie Prinze Jr. 饰）是学校里众人羡慕的对象，可即便是他，也有着说不出的烦恼和困惑。女友泰勒（乔迪·琳·欧基菲 Jodi Lyn O\'Keefe 饰）竟然向处处都不如自己的布洛克（马修·里沃德 Matthew Lillard 饰）暗送秋波，这让扎克无法接受。为了争回一口气，扎克放出了狠话，声称自己可以将任何女孩调教得风情万种，没想到，当他要调教的女孩兰妮（瑞切尔·蕾·库克 Rachael Leigh Cook 饰）出现在眼前时，扎克却傻了眼。兰妮是个声名远扬的怪胎，她不仅打扮老土，脑子里更是装了一堆乱七八糟的怪点子，要将这样的女孩在短时间内变成一个万人迷，扎克面临着极大的挑战。','These two opposites attract... but EVERYONE\'S trying to keep them apart!',10000000,103166989,8.9876,5.7,418,95,'1999-01-29','en','/a0pepZNFCjggc7Na9gEwbTI1f46.jpg',3.120286546118786,3,'2026-09-10',2,NULL,NULL),(10315,'了不起的狐狸爸爸','Fantastic Mr. Fox','本片讲述了一只聪明、敏捷、灵巧且衣着格外体面的野生动物的故事。这位从惯偷鸡贼转行的报社记者狐狸先生，与家人安顿在一棵美丽大树上的新树洞里——而这里紧邻着三个巨大的养鸡场，它们的主人正是三个穷凶极恶的农场主：博吉斯、邦斯和比恩。狐狸先生根本抵挡不住诱惑。韦斯·安德森对罗尔德·达尔经典儿童小说的改编，是一部精心制作的定格动画作品，配音阵容星光熠熠，包括乔治·克鲁尼、梅丽尔·斯特里普、杰森·舒瓦兹曼、威廉·达福、迈克尔·刚本及比尔·默瑞。[标准收藏]','Dig the life fantastic!',40000000,46471023,41.258956,7.5,1176,87,'2009-10-23','en','/bOVr292mwn3jxr1e0NmUPM1rcjo.jpg',3.720431681009278,3,'2026-09-10',2,NULL,NULL),(10316,'总统杀局','The Ides of March','故事以克鲁尼饰演的完美的民主党政客迈克·莫里斯为核心，他天才、帅气、野心勃勃，充满领袖气场，他向公众保证他会诚实于自己所言。斯蒂芬（瑞恩·高斯林饰）则是他竞选班底中的媒体发言人，这个新兵的势头几乎盖过了竞选班底中的老头目保罗（菲利普·塞默·霍夫曼饰）。不过政治总会慢慢显示出其自身的险恶。 　　斯蒂芬与前来实习的大学生莫莉（埃文·蕾切尔·伍德饰）发生了一段恋情，却不经意发现了莫里斯与她有过一夜情，而莫莉还怀上了孩子。随后，斯蒂芬与莫里斯对手的竞选主管（保罗·吉亚玛提饰）私下会面被曝出，他被迫辞职，而莫莉更是因此自杀……','Ambition seduces. Power corrupts.',12500000,75993061,20.317469,6.5,910,101,'2011-09-24','en','/twDnBGjJe6PR71OUIyuNJSKeT5o.jpg',3.4244990528229393,3,'2026-09-10',2,NULL,NULL),(10317,'危机大逆袭','Our Brand Is Crisis','该片由华纳兄弟公司制作，根据2005年同名纪录片启发创作。在那部纪录片中，前美国总统比尔-克林顿的两位政治顾问詹姆斯-卡维尔和斯坦-格林伯格跑到玻利维亚，帮助当地总统候选人桑切斯用美国选举的这一套公关宣传战术来赢得选举。','May the best campaign win.',28000000,7002261,12.921594,5.8,195,108,'2015-09-11','en','/wFTYt1ruiLvQafTk5M2lzE9mf6W.jpg',2.989621938645376,3,'2026-09-10',2,NULL,NULL),(10320,'午夜凶铃2(美版)','The Ring Two','美丽的单身妈妈瑞切尔·凯勒（纳奥米·沃茨 Naomi Watts 饰）带着儿子艾丹（大卫·多夫曼 David Dorfman 饰）离开留下了永生难以磨灭的恐怖回忆的故地西雅图，搬到了毗邻大海的俄勒冈州艾斯特里亚居住。瑞切尔在当地一家报社谋得一份工作，生活充实忙碌。某天，报社接到一条消息，两名青年在看了一卷神秘录像带后一人死亡，一人精神恍惚，熟悉的场景以及没有标题的录像带，令瑞切尔敏感地察觉到昔日的噩梦即将重现。她烧毁录像带，试图阻止凶铃的诅咒继续蔓延，危害世人，却没想到灾难降临到艾丹的头上。该了结的终要了结，无法逃避的如何也躲不过去……  　　本片根据日本作家铃木光司的同名恐怖原著改编，为日本版的翻拍版本。影片荣获2006年ASCAP电影与电视音乐奖、2006年BMI电影与电视奖最佳配乐奖。','The dead don\'t sleep.',50000000,161451538,32.233713,5.4,632,110,'2005-03-17','en','/86SZRAhRz7AfCpttXlYTt0OYOhf.jpg',3.208797880313269,3,'2026-09-10',2,NULL,NULL),(10327,'律政俏佳人2','Legally Blonde 2: Red, White & Blonde','一段奇妙的“哈佛之旅”让金发美女艾莉•伍兹（瑞茜•威瑟斯彭 饰）既得到了法学学位，又收获了甜蜜爱情。毕业之后，艾莉与帅气男友艾默特（卢克•威尔逊 饰）开始筹备他们盛大浪漫的婚礼。为了让她最亲密的朋友小狗Bruiser分享幸福，艾莉准备“邀请”它的父母一同参加婚礼。然而，此时此刻Bruiser的父母却被关在一个化妆品公司的实验室里，等待命运的审判。 　　这件事激起了艾莉对于动物权利保护的意识。为了她的小狗朋友，也为了更多可爱的小生灵，天真的艾莉只身前往华盛顿，想向政府提交一份保护动物的议案，并希望国会能颁布法律保护动物。正当艾莉孤身一人，无计可施的时候，她幸运的遇到了认识好多上层人士的公寓看门人希德尼（鲍伯•纽哈特 饰）。在希德尼的热心帮助下，艾莉正一步步向自己的目标迈进……','Bigger. Bolder. Blonder.',45000000,124914842,4.340616,5.1,377,95,'2003-07-02','en','/jl8ApAjrZu8yVVqRkB6aMKGjBwr.jpg',3.028840055773477,3,'2026-09-10',2,NULL,NULL),(10329,'刚果惊魂','Congo','一家公司派人到刚果寻找纯度极高的钻石，并将发现进行卫星传送。但从寻像上看，那里似乎发生了突发事件，似乎还看到某种体形巨大的动物。公司只好继续派人到现场查明真相。灵长类动物学家彼得.埃利奥特带着艾美——一只8岁的大猩猩前往。但是，热带雨林是另一个天地，在那里主宰一切的可不是这些城市人的意志。这是一个表现人类和动物复杂关系的故事。影片借助电脑栩栩如生地表现了艾美的动作，情节惊险曲折，激动人心。','Where you are the endangered species.',50000000,152022101,10.755847,5,213,109,'1995-06-09','en','/1d0TCUsHk4d2ydCuFqH6EIxXTEo.jpg',2.948038990159274,3,'2026-09-10',2,NULL,NULL),(10330,'Freaky Friday','Freaky Friday','Mother and daughter bicker over everything -- what Anna wears, whom she likes and what she wants to do when she\'s older. In turn, Anna detests Tess\'s fiancé. When a magical fortune cookie switches their personalities, they each get a peek at how the other person feels, thinks and lives.','Mondays are manic. Wednesdays are wild. And Fridays are about to get a little freaky.',26000000,110230332,24.345651,6,879,97,'2003-08-03','en','/nbrLjMsxxzHXAlFZOcbXmKByEKs.jpg',3.343160571392561,3,'2026-09-10',2,NULL,NULL),(10331,'活死人之夜','Night of the Living Dead','这部由恐怖大师乔治·A·罗梅罗执导的作品，是独立电影史上一个传奇：它最初作为午夜场电影走红，随后票房大爆，最终成为影史上最具影响力的影片之一。一队志在留名的电影人凭借微薄预算在匹兹堡郊外完成拍摄。影片讲述一群陌生人被困农舍，被迫抵御大量刚复活食人尸鬼的围攻，这个看似简单的故事实则暗藏深意。罗梅罗通过幽闭恐怖的视角，呈现了1960年代末美国自我撕裂的社会图景，以血腥画面融合尖锐社会评论，并悄然突破时代局限——启用黑人演员杜安·琼斯担任主角，由此改写了恐怖类型的创作规则。[标准收藏]','If it doesn\'t scare you, you\'re already dead!',114000,30000000,25.666029,7.5,580,96,'1968-10-01','en','/uS38rpWLlA4L34bf9CqyfCNV2y0.jpg',3.4589973329212835,3,'2026-09-10',2,NULL,NULL),(10333,'潮浪王子','The Prince of Tides','汤姆（尼克·诺特 Nick Nolte 饰）是一个典型的美国南方青年，早年间不堪回首的童年经历让他成长为了一个沉默寡言愤世嫉俗的男人，同这个虚与委蛇的世界格格不入。哥哥的死讯让汤姆本来就一团糟的生活陷入了更加彻底的颓废之中，他和妻子莎莉（布莱思·丹纳 Blythe Danner 饰）之间的感情亦因此遭遇了巨大的危机。  　　汤姆有一个名为沙凡娜（梅林达·狄龙 Melinda Dillon 饰）只身一人在纽约闯荡，然而，她扬名立万的消息并非传来，传来的却是沙凡娜自杀未遂住进了精神病院的噩耗。苏珊（芭芭拉·史翠珊 Barbra Streisand 饰）是沙凡娜的主治医生，她发现了苏珊绝口不提的过去里隐藏着治愈她的秘方。于是，苏珊找到了汤姆，希望他能够助自己一臂之力。','A story about the memories that haunt us, and the truth that sets us free.',30000000,74787599,3.845231,5.9,56,132,'1991-12-25','en','/1AyeW3YlwfhRwLDeUCW686obceb.jpg',2.715949692353917,3,'2026-09-10',2,NULL,NULL),(10336,'再生侠','Spawn','五年前一个叫艾尔．西蒙的特工被同伙杀害，五年后他和魔鬼订立了一个协约：他可具有无穷魔力，回到人间见他的妻子，不过之后他要毁灭整个人类。复活后的西蒙来到了人间，不过他面临着一个难题——到底是毁灭人类还是拯救人类?','Born in darkness. Sworn to justice.',40000000,87840042,19.833664,5,336,96,'1997-07-31','en','/kLMPJP9Zv6TIhMsAGD66qyGM5qd.jpg',3.037538981468036,3,'2026-09-10',2,NULL,NULL),(10339,'白鲸记','Moby Dick','根据梅尔．维尔的经典文学名著改编，由老牌导演约翰．休斯顿掌舵，加上格利高里．派克将高傲倔强的艾海伯船长塑造得入木三分，使本片成为海上冒险片的经典佳作。故事以一条全身纯白的巨型鲸鱼莫比敌为中心发展，它是一条被水手们视为魔鬼化身的凶猛鲸鱼。艾海伯在捕捉它的过程中被咬掉了一条腿，这种屈辱与伤痛更激发起他一定要打败这条巨鲸的决心，然而也因他这种偏执狂的意志导致很多无辜船员葬身海底的悲剧。本片的海上历险场面拍得相当壮观，在细腻的心理刻画之外也有不错的娱乐效果。','From the immortal adventure classic...of whaling men, their ships, and the sea!',4500000,10400000,5.224593,6.9,89,116,'1956-06-27','en','/7JXcm3RyWlGsRCZ0YlOliWr6TNv.jpg',2.8485564866676363,3,'2026-09-10',2,NULL,NULL),(10350,'银河飞将','Wing Commander','27世纪中叶，地球人与克尔瑞奇族爆发旷日持久的战争。小行星帕格萨斯某日遭到克尔瑞奇的奇袭，驻守官兵抵挡不住败下阵来，智能导航仪也被敌人夺走，这也意味着克尔瑞奇族将长驱直入，进攻地球。为了确保联邦舰队及时回防，杰弗瑞·吐温司令（戴维·沃纳 David Warner 饰）命令詹姆斯·盖斯特（Tchéky Karyo 饰）和达德·马修（马修·里沃德 Matthew Lillard 饰）、克里斯托弗·布雷尔（小弗雷迪·普林兹 Freddie Prinze Jr. 饰）驾驶的小型商船勤工号前往织女星系，将加密磁盘交给盘桓于此的虎爪号。  　　拥有朝圣者敏感身份的布雷尔，即将和好友、战友经历一场有关地球命运的重要战役……','An action packed thrill ride!',30000000,0,5.259585,4,72,100,'1999-03-11','en','/e3p2vkA4mnFaBlyAIntkZWkzOJW.jpg',2.720447997454183,3,'2026-09-10',2,NULL,NULL),(10353,'时空急转弯2','Les Couloirs du temps : Les Visiteurs II','本片描述了由让．雷诺和克里斯蒂昂．克拉维埃饰演的戈德弗鲁瓦骑士和他的侍从拉弗里普伊两人因巫师的失误由公元1122年被抛送到现代。他们被电话、汽车、洗澡间等等现代化的设施弄得惊讶不已，从而演出一系列笑话。导演让－马力．普瓦雷善于突出并发挥演员的作用，注重对诙谐文字、滑稽剧和高卢幽默的兼收并蓄。本片“玩\"的是长达千年的“时间差\"，充分利用了张冠李戴和过时的习俗，围绕中世纪来客面对现代电子世界的丑恶遭遇产生的惊讶来做文章。它完美地运用了大量特技效果，故成一部滑稽惊险喜剧。','They come back!',0,0,12.283025,5.8,221,118,'1998-02-11','fr','/rRhmNCLnpUPqlcUQwJ9NjlG59xR.jpg',3.013185885126974,3,'2026-09-10',2,NULL,NULL),(10357,'活火熔城','Volcano','一次大地震令洛杉矶地底深处的火山喷发，向着住宅区流去，维修地下管道的工人被烧死。地质学家艾美和朋友下去隧道勘测时亲身经历了朋友被岩浆喷发带走了生命。一时之间，城市一隅充满了地底爆发的岩浆。危机处理中心总指挥麦克（Tommy Lee Jones 饰）采取了艾美博士的建议开始疏散人群，他们先利用数百万吨空中降水来使来势汹汹的岩浆变成障碍物，阻挡了岩浆的流动。正当大家以为松一口气时，艾美博士认为岩浆并没有真正被阻挡，只是改变了流向，而且正在往充满伤员的医院奔涌。他们只剩下30分钟的时间去处理这个问题，他们能成功吗？','The coast is toast',90000000,0,19.836124,5.2,376,104,'1997-04-25','en','/hN29g3tSYksS40PTbJtPv9Vpobp.jpg',3.074054281449128,3,'2026-09-10',2,NULL,NULL),(10358,'情色自拍','Zack and Miri Make a Porno','扎克（塞斯·罗根 Seth Rogen 饰）与米莉（伊丽莎白·班克斯 Elizabeth Banks 饰）虽然不是情侣，但他们对彼此再熟悉不过了，二人同居一室，彼此分担生活支出，唯独没有过亲密接触，因为扎克认为这会让情况变复杂，不过他们眼下面临更复杂的问题——缺钱。账单堆积如山、房子被停水停电，本欲参加感恩节高中同学聚会排遣冬夜寒意，无奈他们除了一堆通讯录一无所获，扎克无法忍受困顿的日子，向米莉提出自拍A片贩卖盈利。作为在网络上意外成名的“大内裤女郎”，米莉终于被同居好友说动。他们找来各色胸怀表演梦想的人才出镜，然而出师不利，简陋的摄影棚被强拆，扎克和米莉的关系也因二人要在镜头前亲密接触而发生了变化……','What would you do to get out of debt?',24000000,42105111,27.326466,6.1,721,102,'2008-09-18','en','/cu8b7EMGP1VC80sjvOBFvSmVeHa.jpg',3.3235885122016886,3,'2026-09-10',2,NULL,NULL),(10362,'两个情人','Two Lovers','理纳德（杰昆•菲尼克斯 Joaquin Phoenix 饰）因病理原因被未婚妻抛弃后长时间无法解脱，居住在纽约父母公寓中的他曾多次尝试自杀。理纳德的父母正考虑与好友科恩一家搞干洗店联营，科恩家的大女儿姗德拉（凡妮莎•肖 Vinessa Shaw 饰）爱上了理纳德，但理纳德却爱上了偶遇的金发邻居蜜雪儿（格温妮丝•帕特洛 Gwyneth Paltrow 饰），然而不幸的是，蜜雪儿正与一位有妇之夫的律师罗纳德（伊莱亚斯•科泰斯 Elia Koteas 饰）陷入婚外恋。理纳德在爱情的煎熬中痛苦不堪，曙光与黑夜交替出现，让他无所适从。本片是导演詹姆斯•格雷即“纽约三部曲”后的第四部作品，也是金球影帝杰昆•菲尼克斯的息影之作。',NULL,12000000,3148182,8.290636,6.6,154,110,'2008-11-19','en','/8g87ztaW0mqBhYviXFB5vi97pd7.jpg',2.973403286721726,3,'2026-09-10',2,NULL,NULL),(10364,'第二十二条军规','Catch-22','迈克·尼科尔斯执导的一部黑色反战喜剧片。描述二次世界大战期间，驻扎在地中海的一个美国空军基地，有很多官兵想法逃避飞行任务及获得不法之财。本片是一部内容丰富的黑色反战喜剧，开始的片段拍得很有气派，但其后的发展却稍嫌混乱松散，未能贯穿主题。不过，有许多片段都拍得相当出色，而且娱乐性不低。',NULL,18000000,24911670,4.504377,6.7,72,121,'1970-06-24','en','/2TtGhA9tkKtGlwve1TiEUdRiML.jpg',2.791583756737823,3,'2026-09-10',2,NULL,NULL),(10366,'再造战士2：反攻时刻','Universal Soldier: The Return','尚克劳德范达美重返“魔鬼命令”战场，再度披挂上场演出的生平第一部续集。当年人类异想天开的创造出宇宙战士，到最後却集体叛变。毫无人性、感情的宇宙战士中，鲁克（尚克劳范达美饰演）是一个改造失败的例子，因为他残存的人性，使得他在第一集里，拯救了人类。  这次，鲁克凭着他的经验，成为改造宇宙战士计划的最佳指导。在鲁克的监督之下，第二代的宇宙战士设备更新颖、功能更强大。一旦他们失去控制，情况将无法收拾。不料，瑕疵再度出现，新一代的宇宙战士，再度失控，危害人类的存亡。于是鲁克再度出击，务必确保人类的生存。','Prepare to become obsolete',45000000,10667893,14.566664,4.2,135,82,'1999-08-05','en','/eE4mUmYoIEjhXT7HwDUPi9bP0tN.jpg',2.844112322583228,3,'2026-09-10',2,NULL,NULL),(10368,'与墨索里尼喝茶','Tea with Mussolini','根据导演Franco Zeffirelli本人的早年个人经历改编，讲述二战期间，一群热爱意大利文化艺术的女性在佛罗伦萨和圣吉米尼亚诺的经历，其中包括和墨索里尼喝茶的前英国大使夫人(Maggie Smith饰)、帮雇主照顾私生子卢卡的玛丽(Joan Plowright饰)、艺术热爱者阿拉贝拉(Judi Dench饰)、年轻英国记者康妮(Tessa Pritchard饰)、干练的美国女性乔琪(Lily Tomlin饰)、放浪但好心的美国女性埃尔莎(Cher饰)。战争爆发前，她们常常聚在前大使夫人处，或是在乌菲齐美术馆里喝茶聊天，二战爆发后，她们都被软禁在了古城圣吉米尼亚诺，被她们照顾过的卢卡已经长大，时常前来帮助她们。',NULL,12000000,21001563,2.238646,5.8,32,117,'1999-03-25','en','/i3rAPxhhDjqsL1rZJM57pyR7xFW.jpg',2.594206366082742,3,'2026-09-10',2,NULL,NULL),(10375,'狙击杀手','D-Tox','女友玛丽（戴安·梅尔 Dina Meyer 饰）和同事的接连死亡让FBI探员杰克（西尔维斯特·史泰龙 Sylvester Stallone 饰）陷入了绝望和崩溃之中，因为他很清楚的知道，这个冷酷的杀手是冲着他来的，痛苦而又无处发泄的杰克只得向酒精寻求帮助。亨德里克斯（查尔斯·达顿 Charles Dutton 饰）不忍心看到好友就此堕落，他建议杰克戒酒。  　　就这样，杰克来到了位于怀俄明荒原之中的戒酒中心，在这里，他结识了助理汉克（汤姆·贝伦杰 Tom Berenger 饰）和护士珍妮（波利·沃克 Polly Walker 饰）。一场可怕的暴风雪破坏了戒酒中心的电路和赖以取暖的锅炉，在黑暗和寒冷之中，杰克要面对的除了自己的心魔，还有潜藏在阴影里的凶手。','Survival is a Killer.',55000000,6416302,12.669778,5.3,123,96,'2002-01-04','en','/5S6JV2tG9hfIE89g9YfEGAIhXap.jpg',2.8742160127393164,3,'2026-09-10',2,NULL,NULL),(10377,'我的表兄维尼','My Cousin Vinny','比尔（拉尔夫·马奇奥 Ralph Macchio 饰）和斯坦（米歇尔·维特菲尔德 Mitchell Whitfield 饰）是一对损友，此时，他们正驾驶着汽车前往学校。这一段旅程注定不会平静，误打误撞之中，两人竟然被指控谋杀。眼看着审理日即将到来，比尔和斯坦找到了刚刚毕业的半吊子律师文森特（乔·佩西 Joe Pesci 饰），请求他为他们辩护。  　　令两人万万没有想到的是，文森特在法庭上的出格表现不仅没有为他们洗清罪名，文森特自己反而因为“蔑视法庭罪”而遭到监禁，而经历了如此挫折后，文森特一蹶不振，辩护水平更是大打折扣。一番波折之后，比尔和斯坦好不容易洗脱了牢狱之灾重获自由，但两人明白，只要文森特存在一天，他们的厄运就会延续一天。','Truth, Justice and the Gambini Way',11000000,64088552,19.231507,7.3,384,120,'1992-03-13','en','/iwSURa8nS2ujwrU3s1lfxxX7voH.jpg',3.2934041055330363,3,'2026-09-10',2,NULL,NULL),(10383,'驱魔人','Lost Souls','玛雅（薇诺娜·瑞德 Winona Ryder 饰）是一个曾经遭到过魔鬼附身的女孩，甚至其中的恐怖与痛苦，幸运的是，在最绝望的时候，她遇见了神父拉瑞奥克斯（约翰·赫特 John Hurt 饰），后者将她从恐惧的深渊中解救了出来。重新回归正常生活的玛雅成为了一名虔诚的信徒，她加入了一个驱魔组织，坚信魔鬼终有一天会再度降临人世，施展它野心勃勃的阴谋。\r 　　皮特（本·卓别林 Ben Chaplin 饰）是一位小有名气的专栏作家，有着一段不堪回首的悲惨往事。特殊的童年经历让他放弃了信仰，并且拒绝相信怪力乱神之说。讽刺的是，魔鬼恰恰选择了不信邪的皮特作为附身的对象，皮特很快就陷入了恐惧之中。',NULL,0,0,3.312385,4.5,38,97,'2000-10-13','en','/9DOq3KqGrNbqa3z5M8iDJ2wuaxJ.jpg',2.6128946562695834,3,'2026-09-10',2,NULL,NULL),(10384,'超级外星历险','Supernova','\"二十二世纪初，一艘医疗救生船“夜莺229号”正进行一次深层太空的例行巡视。在这艘寂静孤独的飞船里工作的有上尉A.J.马尔里，副手尼克.凡山特，主治医师官奇拉.艾凡斯，计算机工程师本.索特摩杰，医学家叶尔治.潘纳罗萨，以及丹尼克.罗德等六名成员。\r 巡视中，他们发现在距离他们上百万光年之外有一颗星体正爆发出奇怪的异类物质，几个人一时不知如何处置，就在此时他们接收到了一个紧急求援信号，尽管很危险，但是救援小组的成员没有选择，只有前往救援。\r 跌跌撞撞的飞船终于接近了那个爆发的中心地带，立刻他们被一个巨大的蓝色星体的引力牵制住了。在这里，他们营救上了一名神秘叵测年青男子卡尔.拉森，让大家不安的是他们感觉到这个人对飞船成员随时可能造成危险。而除此之外，夜莺号上的成员还要和那个巨大的宇宙引力作斗争。\r 飞船上的人们正在面临着死亡，幸存者必须摆脱这颗星体的引力返回银河系，因为，这颗巨大的超新星的爆发随时都有可能发生……\r 本片是米高梅公司新年初推出的一部科幻影片，其特技效果由曾为《泰坦尼克》制作特技的数字空间(Digi tal Domain)工作室完成，在这部影片中，他们再一次用高科技手段为我们创造出了一个未目睹过壮观的宇宙奇景。\"','In the farthest reaches of space, something has gone terribly wrong.',90000000,14828081,5.762037,4.9,109,91,'2000-01-14','en','/AmHGUjhgXnOYRYrF2ZYMtzfwxPe.jpg',2.820290412024918,3,'2026-09-10',2,NULL,NULL),(10385,'来电传情','Hanging Up','年老的劳（沃特尔•马修 饰）有三个女儿，可是他很少与女儿们见面，平常女儿们都只是打电话询问老父亲的情况。身为妇女杂志主编的大女儿乔姬娅（黛安•基顿 饰）每天的工作都非常繁忙，身居要职的她每天都在努力工作；二女儿艾薇（梅格•瑞恩 饰）美丽动人，但也同样与父亲缺少沟通；至于三女儿则是个演员，虽然不是大红大紫，但她仍享受自己的工作。\r 　　父亲从来都很少照顾女儿们，也很少关心她们的生活，无形中也成为了女儿与父亲之间的隔阂。父亲有自己孤独的晚年生活，女儿们也有各自要忙碌的工作与生活。\r 　　可是当有一天，三姐妹接到老父亲病倒的消息，都纷纷赶到了父亲的身边……','Every family has a few hang-ups.',40000000,36037909,3.415534,5,40,94,'2000-02-16','en','/lnnFFGhIXi6ZDU3r29eKHKTHdq0.jpg',2.630601302809979,3,'2026-09-10',2,NULL,NULL),(10386,'钢铁巨人','The Iron Giant','1950年代，一个巨型金属机器坠落在缅因州，令镇民惊恐。然而，这个机器人却与名叫霍加斯的九岁男孩成为了朋友。男孩必须保护它，使其免受镇民的偏见以及一心要摧毁机器人的政府特工的威胁。','It came from outer space!',70000000,23159305,61.245957,7.6,1436,86,'1999-08-06','en','/k1Cv5CHJvqGWK1xJDUJz8DojFEy.jpg',3.8484534504212036,3,'2026-09-10',2,NULL,NULL),(10388,'英国佬','The Limey','著名的韦氏词典中“Limey“的解释之一是“英国水手”，在这部斯蒂芬·索德伯赫的的作品中，我们的主人公曾经做过水手。这位倔强的英国人来到洛杉矶一心要为自己的爱女复仇。所以本片取名“Limey”意为讲述一个在洛杉矶因为愤怒、复仇而迷失了自己的人——威尔森。','Vengeance knows no boundaries.',10000000,3193102,8.902102,6.6,105,89,'1999-05-15','en','/efAnFInZYrenNvBlLIXN2oLYyNc.jpg',2.8851907449467133,3,'2026-09-10',2,NULL,NULL),(10390,'棒球之爱','For Love of the Game','在底特律老虎队服役19年的灵魂人物比利契波（凯文科斯纳饰演）面临生命的低谷：这个赛季球队表现不佳，自己的旧伤复发，老东家将出售球队，新东家一接手就将把他转会，他的女朋友珍欧柏瑞（凯莉普瑞斯顿饰演）要远赴英国。在充满敌意的客场上，他孤零零地站在投手板上，奋力的投出每一球，并且重新审视自己的一生。最终他带领自己的球队创造出了杨基球场上四十年未见的奇迹，一场主队0安打0得分的比赛。这是一个你明知结局也会被深深感动的电影','Billy Chapel must choose between the woman he loves and the game he lives for.',50000000,0,9.622345,6.3,88,137,'1999-09-17','en','/vkeKxoSXE1qMArcFNTNBBH8TjKZ.jpg',2.836516206158602,3,'2026-09-10',2,NULL,NULL),(10391,'末世圣童','Bless the Child','该片讲述了有着超常的能力的小女孩考蒂，在正义与邪恶之间引发了一场冲突，而这场冲突只有通过她的力量才能化解的故事','Mankind\'s last hope just turned six.',40000000,0,3.321949,4.9,71,107,'2000-08-11','en','/s1RGEF8xIA6ecF8W4do8CaWI0yE.jpg',2.737727927347615,3,'2026-09-10',2,NULL,NULL),(10393,'十全大补男','The Replacements','故事发生在1987年，席恩（基努·里维斯 Keanu Reeves 饰）虽然只是一介名不见经传小小擦船工，却拥有着与生俱来的橄榄球天赋，并且深深的热爱着这一项充满了竞争和冲突的体育运动。在令人兴奋而又充满了期待的赛季即将开始之际，明星球员们却突然发起了罢工运动，眼看着球赛的票都销售殆尽，这可急坏了球队老板。','Throw the ball. Catch the girl. Keep it simple.',0,0,14.837288,6.1,203,118,'2000-08-07','en','/6qerI41HqkdRlio1sG0d5HLZcFN.jpg',3.0216644049912986,3,'2026-09-10',2,NULL,NULL),(10395,'狼人生死恋','Wolf','黑夜，威尔·兰德尔驾驶汽车在郊外撞死一只狼。但他走进这只死狼时，它却出人意料的复活，咬了他的手后逃进树林不见了。翌日，威尔在家睡了一整天。自从遇见狼之后，威尔发现自己的感官比过去灵敏得多了，例如听觉、嗅觉和视力都很好，工作效率也很高。他发现妻子的衣服上有一种奇怪的气味。他去斯图尔特的公寓，像一只狼似地狠狠咬了斯图尔特的手。威尔找到一位研究被动物附体的专家亚历齐亚斯博士，告诉他也许他正在发生身体方面的变化——变成一只狼。随后交给他一张护身符，并说用它可以阻止这种变化。翌晨，夏特死了，她的喉咙不知被什么人撕裂了。劳拉为威尔提“案发时他不在犯罪现场”的证明，但随后去向警察告发。斯图尔特追赶劳拉，威尔扔掉了护身符跳起来解救劳拉。经过一场搏斗，劳拉终于用手枪击了斯图尔特。威尔逃进树林，变成了一只活生生的狼。','The animal is out.',0,0,13.758526,6,216,125,'1994-06-17','en','/1nHVuNQ7gdMympgwnGavzkXkzXj.jpg',3.0257130877463023,3,'2026-09-10',2,NULL,NULL),(10397,'天使的孩子','Angela\'s Ashes','当初因为宗教问题，安吉拉（艾米丽·沃森 Emily Watson 饰）和丈夫的婚姻并没有得到亲友的赞许。如今他们已经有好几个孩子，可是在美国生活得并不如意，贫穷折磨再加上不久前的丧子之痛，这家人决定搬回家乡爱尔兰，以祈求在那里获得富裕一点的生活。  　　事情并没有他们想象的那样顺利，在家乡，他们仍然遭遇着亲友冷眼，开始了艰难为继的新生活。每当丈夫没有勇气干些琐碎活扛起家庭重担时，是安吉拉义无反顾的担负起一切又脏又累又卑微的活儿。命运一次次给这个坚强的母亲以打击。她的一对双胞胎孩子相继去世，丈夫到英国谋生却没能改善困窘的家境，安吉拉从不放弃地寻求救助，并教会儿子弗兰克（乔·布林Joe Breen 饰）生存的尊严，母亲的光辉在弗兰克的一生里都不会褪色。',NULL,25,13,4.88794,7,59,145,'1999-12-25','en','/3Zzcys11nAPP14sKW9l97fIHhkK.jpg',2.7539699835638185,3,'2026-09-10',2,NULL,NULL),(10398,'双重危机','Double Jeopardy','莉比-帕森斯(阿什莉-贾德饰)是一位生活在西雅图的年轻母亲，其幸福、快乐的家庭生活令人羡慕。丈夫尼克(布鲁斯-格林伍德饰)是一位风流倜傥的男子，同时又是一位事业有成的商人。莉比五岁的儿子麦迪也非常招人爱怜。一个周末的夜晚，夫妻俩和往常一样，驾驶着私家游艇在静寂的湖面上游弋。入夜，莉比从睡梦中醒来，却不见了丈夫的踪影。她惊奇地发现不光她的身上沾满鲜血，而且游艇的甲板上也遍布了血迹。很快，莉比成了谋杀尼克的头号嫌疑犯，警方怀疑她是由于贪图尼克的二百万保费而谋杀了亲夫。最终，无辜的莉比被判入狱监禁十年。行将服刑之际，莉比将爱子麦迪托付给她最信赖的好友安吉。然而，就在莉比入狱后不久，安吉与麦迪便告神秘失踪。在狱友玛格丽特与伊芙琳的帮助下，莉比开始利用电话查找好友与儿子的下落，并坚持不懈地向警方证明她的清白。而且她越来越怀疑丈夫尼克可能还活在世上，但她不明白深爱她的丈夫是出于何种目的而迫使自己遭受牢狱之灾的。玛格丽特曾是一位优秀的律师，后因误杀丈夫而被判入狱。玛格丽特提醒莉比：如果尼克还没死，她可以畅行无阻地对尼克还以颜色，因为一个人不可能因同一罪名被起诉两回。六年之后，莉比获得假释，失意但不失善良本性的老警官塔维斯-莱曼(汤米-李-琼斯)成了莉比的监护人。在一次极其偶然的情况下，莉比发现尼克已改换了身份，正同安吉与麦迪生活在旧金山的某一个角落。莉比开始不惜一切地从警方的监视下逃脱。警官莱曼也自然承担起了追捕莉比的使命，他的内心隐约感知莉比是清白无辜的。与此同时，穷凶极恶的尼克却准备伺机谋取莉比的性命，在莱曼的暗中协助下，莉比最终让尼克得到了应有的报应。已恢复清白声誉的莉比终于与儿子得以团聚……','Murder isn\'t always a crime.',70000000,177841558,19.439386,6.2,278,105,'1999-09-24','en','/rQhSmBmsJ2od8lw4HBPe1MhMra2.jpg',3.1082297984683316,3,'2026-09-10',2,NULL,NULL),(10400,'飓风','The Hurricane','一个黑人毛头小伙莱斯（维斯罗斯•雷恩•香农 Vicellous Reon Shannon 饰）在旧书市无意中淘到了拳王“飓风”鲁本•卡特（丹泽尔•华盛顿 Denzel Washington 饰）在狱中写的自传，并开始了对他的故事产生了兴趣。鲁本出生于贫寒家庭，幼年时嫉恶如仇，因此与当地的白人警察结怨。后来，他因为出色的身手，名震拳坛，绰号“飓风”。此后，他参加了越战成为荣誉军官，并在某舞会偶然结识了后来的妻子。当生活进入美满轨道的时候，一次新泽西酒吧杀人案彻底毁掉了他美好希望。莱斯与鲁本通信，了解到他蒙受不白之冤，便说服了朋友们，一起查找证据，希望揭开真相，令他重获自由，然而种族歧视的恶势力却在暗中百般刁难，意图把飓风困死在牢房……','His greatest fight was for justice.',50000000,73956241,20.825781,7.2,396,146,'1999-09-17','en','/iH7zKvZRD9GjLgUIZSOnFCPyFAl.jpg',3.29563459181064,3,'2026-09-10',2,NULL,NULL),(10402,'哈啦猛男秀','Deuce Bigalow: Male Gigolo','其貌不扬的小人物米特·德斯·比格劳（罗伯·施奈德 Rob Schneider 饰）是一个鱼缸清洁工，因全裸上阵而被水族馆扫地出门的他，偶然得到一份去别墅清洁鱼缸的工作。别墅的主人安东尼·罗坎特（奥迪德·菲赫尔 Oded Fehr 饰）是一个风光无限的脱衣舞男，他生活优渥，身边美女如云，与米特猥琐不堪的境遇形成鲜明对比。  　　某天，安东尼要去瑞士三周，他希望米特留在别墅照顾他生病的鱼，同时还给米特定下诸多严厉的规则。当然，主人一走，米特便展开他宛如假日般的快乐生活。正所谓乐极生悲，米特给这幢豪华的别墅带来巨大的灾难。为了在安东尼回来之前将一切恢复原状，他不得不化身牛郎四处筹钱……','He charges $10 but he’s willing to negotiate.',17000000,65535067,9.832326,5.5,308,88,'1999-12-10','en','/1a7vGbM5JG97281MCyEJfvEmnUE.jpg',3.046605274407075,3,'2026-09-10',2,NULL,NULL),(10410,'最后巨人','Hoffa','以美国工会领袖吉米·侯法的生平事迹为题材的传记片。侯法是个个性强烈，行事作风极具争议性的工会英雄。从三十年代的经济大崩溃开始，他在工会及政坛经历了四十年的奋斗。',NULL,35000000,0,5.926966,6.1,81,140,'1992-12-25','en','/aMGhaSkhkFwz33hKEsBrJ3ptx3g.jpg',2.8038491634711584,3,'2026-09-10',2,NULL,NULL),(10413,'铁血情奔','Nowhere to Run','从监狱逃出来的萨姆.吉伦与偶遇的男孩穆基成了忘年交。穆基还有一个小妹妹，兄妹俩与母亲相依为命，经营着一个小农场。土地商富兰克林想买下她的农场，将这块地方改造成高尔夫球球场，遭到拒绝后竟以不正当的手段开始进行恐吓。逃犯萨姆看出穆基一家的无助，决定挺身而出，帮着他们对付富兰克林。整个影片既有谷仓大火，摩托车追逐的大场面，也有萨姆与穆基家绵绵的亲情。','When the law can\'t protect the innocent,  the only hero left is an outlaw.',0,0,11.689337,5.5,119,94,'1993-01-15','en','/xc6P8PHh3rLQPOVvJpYjKOugACr.jpg',2.874266201926712,3,'2026-09-10',2,NULL,NULL),(10414,'野鸭变凤凰','The Mighty Ducks','以明尼苏达州的儿童冰上曲棍球运动为主题。片中唯一的知名演员艾米里欧．埃斯特维兹饰演心高气傲的律师戈登庞贝，他在为社区服务的法院判决下，被迫担任儿童冰上曲棍球队的教练。他本来不以为然，但在训练孩子们的过程中他学到了改过自新，而且也为他们的巨鸭队争取到胜利。本片的剧情虽不免公式化，但剧本充满感情和幽默感，导演史蒂芬．赫瑞克也拍得灵活流畅，使它成为一部娱乐性颇高的家庭娱乐片，在欢笑中发挥了励志色彩。','They can\'t skate. They can\'t win. They can\'t be serious.',10000000,50752337,8.932837,6.4,198,101,'1992-10-01','en','/zxaCHxKDFNi6frh1Q0dj19L216o.jpg',3.022040016765114,3,'2026-09-10',2,NULL,NULL),(10416,'外星人的使命','What Planet Are You From?','A highly-evolved planet, whose denizens feel no emotion and reproduce by cloning, plans to take over Earth from the inside by sending an operative, fashioned with a humming, mechanical penis, to impregnate an earthling and stay until the birth. The alien, Harold Anderson, goes to Phoenix as a banker and sets to work finding a mate. His approaches to women are inept, and the humming phallus doesn\'t help, but on the advice of a banking colleague, he cruises an AA meeting, meets Susan, and somehow convinces her to marry. The clock starts to tick: will she conceive, have a baby, and lose Harold (and the child) to his planet before he discovers emotion and starts to care?','To save his planet, an alien must find a woman on Earth to have his baby. There\'s just one problem.',60000000,0,2.275331,5.4,37,105,'2000-03-03','en','/2VtgMZPj3uDLz0zOQqZ74SUZGK4.jpg',2.618537499478367,3,'2026-09-10',2,NULL,NULL),(10425,'生死交锋','The Death and Life of Bobby Z','本应在监狱中度过终生的蒂姆，通过与FBI达成协议：如果完成FBI的任务，便可以免除牢狱之灾。他必须伪装成一个传说中的毒品贩子Bobby Z去和墨西哥的一个毒品大佬进行人质交换。在交换时发生了枪战，假Bobby Z偷偷趁乱带着真Bobby Z6岁的儿子逃跑了……','To live a life of his own, he has to die first.',22000000,413454,12.893219,5.8,103,97,'2007-07-23','en','/sgIthxRLUBTbaetVXvXwQEmbfn2.jpg',2.8601316711757043,3,'2026-09-10',2,NULL,NULL),(10426,'下一个星期五','Friday After Next','这是《星期五》系列影片的第三部。故事发生在圣诞节前的一个星期五，黑人青年克雷格·琼斯（艾斯·库巴饰）和他的堂兄弟也是好友的戴戴（麦克·艾普斯饰）一起住在一幢租来的房子里，现在，房子里堆满了过节用的东西，到处洋溢着圣诞的气氛。可惜，一个伪装成圣诞老人的盗贼光顾了他们的房子，把房间里所有值钱的东西全都拿走，还有他们藏在音箱里的房租！ 　　回到家的克雷格和戴戴傻眼了，没有礼物的圣诞节如何度过？傍晚前交不出房租可就要卷铺盖卷走人，他们唯一的希望就是赶紧找到一份能立刻拿钱的工作。于是两个人来到一个购物中心当上了保安，一场闹剧也开始了……','The party\'s back in the \'hood!',20000000,33526835,7.499639,6,100,85,'2002-11-22','en','/sxHFGPKLWj9e3aaA6wGVxghoiPE.jpg',2.848995844857969,3,'2026-09-10',2,NULL,NULL),(10428,'黑客','Hackers','达德（约翰·李·米勒 Jonny Lee Miller 饰）是一名出色的天才黑客，曾经，股市因为11岁的他的小小恶作剧而差点崩盘，达德因此被剥夺了使用网络的权利，如今，已经成年的达德终于重新获得了这一权利，跃跃欲试的他摩拳擦掌，准备在网络上重新大展拳脚。凯特（安吉丽娜·朱莉 Angelina Jolie 饰）和乔伊（杰西·布拉德福特 Jesse Bradford 饰）都是如同达德一样的黑客，他们因为趣味相投而走到了一起成为了好友。普拉格（费舍·史蒂芬斯 Fisher Stevens 饰）曾经是一名技术高超的超级黑客，如今，被招安的他成为了一家大公司的系统安全专家。背地里，普拉格和黑恶势力勾结，谋取公司账户里的巨额财产，此外，他还发明了一种能令全球网络陷入瘫痪的可怕病毒。一次偶然中，达德一行人发现了普拉格的罪恶和阴谋，他们决定给利用自己的力量，阻止普拉格。 ©豆瓣','There is no right or wrong, only fun and boring',20000000,7563728,17.842246,6.2,398,107,'1995-09-14','en','/t611bi4AVWRAJ5tFeBsT1Y5yctE.jpg',3.184287465579776,3,'2026-09-10',2,NULL,NULL),(10431,'游侠','War','在搭档汤姆·韦恩(特里·陈饰)和他的全家被誉为最残酷的杀手——“游侠”(李连杰饰)全部杀掉后，美国联邦调查局FBI探员杰克·克劳福德(杰森·斯坦森饰)便下定决定，一定要彻查此案，为汤姆及他的全家报仇。　　然而，当杰克的调查愈发深入的时候，他发现，原来杀手“游侠”已经卷入了一场空前浩大的“黑吃黑”的战争当中。争斗的两方是黑道上著名的常(约翰·朗饰)为首的以及以老板史罗(里奥饰)为首的来自亚洲的两伙势力强大的黑社会犯罪集团。但始终困扰着杰克的问题是，搭档汤姆·韦恩是如何卷入这场黑社会战争的，又如何招致灭门之祸？ 　　经过一系列的“明争暗斗”和“黑白之争”之后，杰克终于与传说中的杀手“游侠”面对面，整个事件的真相也随之慢慢的揭开……','Vengeance is the ultimate weapon.',25000000,40452643,18.896239,6,414,103,'2007-08-24','en','/8gVcUXyvhQeQD4dIoPS8vMFBKYu.jpg',3.1737269214290156,3,'2026-09-10',2,NULL,NULL),(10436,'纯真年代','The Age of Innocence','唯有马丁·斯科塞斯能如此精准捕捉纽约的浮华与悸动。通过这部奢华的爱情史诗，他精细改编了另一位纽约文学巨匠伊迪丝·华顿的作品，将镀金时代曼哈顿封闭社会中的悲剧小说赋予鲜活生命。影片讲述纽兰·阿彻与纯真富家女订婚后被牢牢束缚于上流社会的礼仪枷锁，而当她那因离婚丑闻席卷社交界的表姐重返纽约时，却点燃了纽兰内心从未觉察的炽烈激情。影片以考究的时代细节堆叠出华丽帷幕，在令人心碎的浪漫叙事与尖锐的社会讽刺间交织，冷峻剖析旧世界美国的优雅与残酷。[标准收藏]','In a world of tradition. In an age of innocence. They dared to break the rules.',34000000,32255440,9.133747,7,169,139,'1993-09-17','en','/mUpyKgEcqyx79UooGpfwnUcHAC5.jpg',3.0200030098510764,3,'2026-09-10',2,NULL,NULL),(10437,'圣诞欢歌','The Muppet Christmas Carol','这是狄更斯经典故事《守财奴》（Ebenezer Scrooge）的再现。在过去、现在和未来的圣诞鬼魂夜访期间，他要为自己的卑鄙行径负责。',NULL,0,27281507,15.085981,7.2,212,85,'1992-12-10','en','/ssrV29QSVVJuemBHho0Qx7pFYak.jpg',3.105970350014897,3,'2026-09-10',2,NULL,NULL),(10439,'女巫也疯狂','Hocus Pocus','故事发生在万圣节的夜晚，男孩马克思（欧姆里·卡兹 Omri Katz饰）在误打误撞之中点燃了邪恶的蜡烛，将在三百年前早已经死去的三名女巫威尼弗雷德（贝特·米德勒 Bette Midler饰）、莎拉（莎拉·杰西卡·帕克 Sarah Jessica Parker饰）和马莉（凯茜·纳基麦 Kathy Najimy饰）从地狱召唤回了人间。很久很久以前，这三名女巫因为吸食小孩的精气而被判以死刑，如今，再度回到阳间的她们决定重蹈覆辙。得知了女巫们的阴谋，马克思决定绝不坐视不管。他找到了妹妹丹尼（索拉·伯奇 Thora Birch饰）和好友艾莉森（凡妮莎·肖 Vinessa Shaw饰）三人一起行动，计划破坏女巫们的行动。留给孩子们的时间已经很少了。','It\'s just a bunch of Hocus Pocus.',28000000,39514713,18.650748,6.4,471,96,'1993-07-16','en','/7tkjsGzTZslbH6jRlQof7xHSJuo.jpg',3.2472118481679453,3,'2026-09-10',2,NULL,NULL),(10445,'影子大地','Shadowlands','故事发生在1952年的英国，一次偶然中，作家杰克（安东尼·霍普金斯 Anthony Hopkins 饰）结识了名为乔伊（德博拉·温格 Debra Winger 饰）的女子和她的儿子道格拉斯（约瑟夫·梅泽罗 Joseph Mazzello 饰），很快，三人便成为了好友。  　　为了能够留在英国，独身多年的乔伊决定和杰克结婚，然而这段婚姻却并没能给乔伊带来幸福，她最终还是选择了离开。经过医生的诊断，乔伊患上了不治之症，得到了这个消息，杰克才猛然醒悟，原来自己的心底一直深爱着这个坚强的女人，杰克找到了乔伊，两人重新走到了一起。在往后的岁月里，杰克一直不离不弃的陪伴在病重的乔伊身边，虽然死亡步步逼近，但两人都找到了一生的挚爱。 ©豆瓣',NULL,22000000,0,5.609755,6.8,61,131,'1993-12-25','en','/5jTWY1M2O4Zhid4rLOpftzazRGn.jpg',2.7587266361910374,3,'2026-09-10',2,NULL,NULL),(10448,'复活节岛','Rapa Nui','剧情描述复活岛上的“长耳族”和“短耳族”因为建造巨大的“毛艾石像”和举行“鸟人比赛”而爆发致命的种族恶斗，仅剩下欧尼尔带着妻子洛曼娜和刚出生的女儿乘船出海逃过灭族劫难。',NULL,20000000,305070,3.581906,6.2,33,107,'1994-09-09','en','/7SGV2gjYWKQezXOLGdbzPuaYxo2.jpg',2.608839879907885,3,'2026-09-10',2,NULL,NULL),(10461,'大开杀戒','Get Carter','职业杀手杰克·卡特一直在纽约独闯江湖，与自己住在洛杉矶的弟弟很少来往。后来因要出席弟弟葬礼而重返家园，他在深感内疚的同时，很快就感到弟弟的死另有隐情，通过调查，发现不少和弟弟有关系的人都有可疑，包括漂亮的弟媳妇，她的女儿，弟弟的老板，一个神秘的女人，一个百万富翁等，最终凶手伏法，而卡特也为此付出了自己的生命。','The Truth Hurts',63600000,19412993,4.494788,4.8,145,102,'2000-10-06','en','/xGANaRWD6638ch1qQmqgRp395R6.jpg',2.8608531577844416,3,'2026-09-10',2,NULL,NULL),(10468,'醉酒俏佳人','28 Days','在姐姐结婚当天因为酒驾而车祸后，葛雯·康明斯有两个抉择：监狱和勒戒所。她选择了勒戒所，但是她强烈反对参与勒戒所里的任何一个治疗课程，并拒绝承认自己有酒精中毒。在认识一些病人后，葛雯开始自我检讨其一生，并发现自己的确有很严重的酒精中毒的问题。她和Andrea（一位17岁因上瘾海洛因而进入勒戒所的女孩，有时候会自残）做朋友。当她尝试让自己保持清醒状态时，所有其他的病人帮助她，让她看见不同面的自己。在通往矫正、治疗的道路上，并不如想像中的简单，即使成功了，也不一定是自己喜欢的结果。但是，她已经有能力让自己去尝试控制自己别再喝酒了。','The Life of the Party... before she got a life.',43000000,0,5.418921,6,208,103,'2000-04-06','en','/tlgz7Shx0UavR5pyITeJ2mUHKFI.jpg',2.99872966381093,3,'2026-09-10',2,NULL,NULL),(10471,'下个周五','Next Friday','本片是影片《星期五（Friday）》的续集。格瑞戈仍然和他的朋友们一起，住在洛杉矶。现在，他正在寻找新工作。四年前曾与格瑞戈结下仇的迪波正在寻找他，肆机报仇。\r 为了儿子的安全，格瑞戈的父亲把他送到了叔叔家，这样。格瑞戈就和脾气有些古怪的叔叔艾罗依和表兄雷雷同处一个屋檐下。不过，格瑞戈很快就发现，麻烦总会自己找上门来，不管你住在什么地方……','The suburbs make the hood look good.',11000000,59827328,9.337388,6.4,135,98,'2000-01-12','en','/dP4fYCGQZzg17ta7FvLwJVCwwt9.jpg',2.935360660857564,3,'2026-09-10',2,NULL,NULL),(10472,'煞到你','Down to You','College coeds in New York City, Al, the son of a celebrity chef, and Imogen, a talented artist, become smitten the second they lay eyes on one another at a bar. However, the road to happiness is not a smooth one. Outside forces, including a predatory porn star who wants to lure Al into her bed, threaten to pull apart the young lovers before their romance has a chance to really flourish.','A new comedy about giving first love a second chance.',9000000,0,3.269459,4.9,70,91,'2000-01-21','en','/gGnohWv7KvJKsYRPSUBkRvwBM2E.jpg',2.734986112669008,3,'2026-09-10',2,NULL,NULL),(10476,'川流熙攘','Hustle & Flow','迪杰（泰伦斯•霍华德 Terrence Dashon Howard 饰）是一个皮条客， 每天和妓女诺拉（塔恩•曼宁 Taryn Manning 饰）在汽车上接客，日子极为无聊，深感中年危机。在一次黑市交易中，迪杰买到了一个卡通电子钢琴，唤起了自己关于唱诗班的回忆。他得知嘻哈巨星凯尼布莱克（卢达•克里斯 Ludacris 饰）将在7月4日开演唱会。他希望能够录自己的demo小样，寄给这位嘻哈界的大腕。于是，迪杰开始重新组建乐队，找到昔日唱诗班的老友凯（安东尼•安德森 Anthony Anderson 饰），白人钢琴师布莱尔，孕妇莎戈（塔拉吉•P•汉森 Taraji P. Henson 饰）等人帮忙，一步一步实现着自己的理想。他把自己底层生活的经验变成了歌词，用激情荡漾的演绎，征服了媒体和乐迷，然而正当他即将大红时，却因为一次莫名其妙的官司锒铛入狱…','The music will inspire them. The dream will unite them. This summer get crunk.',8000000,23563727,6.39503,6.9,99,116,'2005-07-22','en','/yO5QTMZ2Oex6mwsgJuwRuINGuOQ.jpg',2.8766527461623497,3,'2026-09-10',2,NULL,NULL),(10477,'极速竞赛','Driven','在一次残酷的事故过去多年后，乔.坦托（席维斯.史泰龙）一直试图忘记那令他魂牵梦绕的赛车场。当赛车老板卡尔.亨利（伯特.雷诺兹）找到乔，问他愿不愿意重操旧业时，乔意识到自己圆梦的机会来了——虽然这次他是作为一个教练而不是车手。\r 吉米.布莱（基普.帕杜）是个很有天赋的新人，但在各方面的压力下，吉米反而丧失了信心和斗志。与此同时，他还无可救药地爱上了自己的对头、一流车手鲍（蒂尔.斯威格）的女朋友索非娅（艾斯黛拉.沃伦）。\r 乔和吉米走到了一起。这对老少组合能相得益彰、战胜诸多困难，最终拿到冠军吗？','Get ready for the race of your life.',94000000,54744738,8.468586,4.5,179,116,'2001-04-27','en','/XHvtbtQBRtkaf82k8T3DLIBGg0.jpg',2.8853314901370952,3,'2026-09-10',2,NULL,NULL),(10478,'球爱的天空','Tin Cup','绰号“锡杯”的高尔夫球好手罗伊开了一所学校，心理学博士莫莉来报名学习。之后他们意识到可以换工：罗伊教莫莉打球，而莫莉可以给罗伊做心理辅导。在这个过程中，罗伊爱上莫莉，而莫莉现在的男朋友正是罗伊不服气的竞争对手西姆斯。朋友向罗伊进言：只有在美国公开塞上取胜才能赢得莫莉的好感。但罗伊一上赛场，刚愎自用的毛病又犯了。他不听劝告，非要选择一条最困难的路线，冒着被取消比赛资格的危险，在观众疯狂的鼓励下，打出高尔夫球历史上难度最大的球。这次虽然没有取胜，但他的勇敢和执着也让莫莉扪心自问：生活中是不是也需要有冒险的精神？','Golf Pro. Love Amateur.',45000000,53854588,10.731574,5.9,150,135,'1996-08-16','en','/pVgeUSP71yttnb70iukbhsmNmgI.jpg',2.9368924616527115,3,'2026-09-10',2,NULL,NULL),(10480,'急救爱情狂','Nurse Betty','贝蒂（芮妮·齐薇格 Renée Zellweger 饰）是一个平凡的女招待，有一个个性令人讨厌的丈夫戴尔（艾伦·艾克哈特 Aaron Eckhart 饰）。生活并不如意的她只能将自己全身心的投入到了电视里播放的肥皂剧当中去，在那里，完美的戴维拉威尔医生（格雷戈·金尼尔 Greg Kinnear 饰）永远都用他那性感的微笑等候她的光临。  在一次危险的毒品交易中，戴尔被杀死了，听闻此消息的贝蒂在瞬间意识到，自己的新生活开始了。没有了丈夫的桎梏，贝蒂决定驾车前往洛杉矶，去寻找戴维拉威尔医生，幸运的是，贝蒂竟然被制片人相中，成为了医生新助手的扮演者。尚且沉浸在喜悦之情中的贝蒂不会知道，毒贩们已经盯上了她。','She\'s chasing a dream... they\'re chasing her.',24000000,0,3.572339,5.9,111,108,'2000-09-08','en','/1OCHR9z9k7go669AsShOkTj4CFb.jpg',2.858117215919132,3,'2026-09-10',2,NULL,NULL),(10481,'102真狗','102 Dalmatians','在上一集101真狗中，古拉（格伦•克洛斯 饰）被关进了牢狱中。三年牢狱中古拉提前出狱了，本来以为她会改过自身不在打那些可爱斑点狗的主意，就连她自己也说不会再做杀害斑点狗的残忍事。\r 　　但她的虚荣心还是敌不过自己的意志，看到那些美丽的斑点狗，她再次动心想要取得那些斑点狗的皮毛。法国设计师勾画出的美丽服装设计图，再次让她决定故伎重演的决心。102只斑点狗的生命危在旦夕，但这些懂人性小狗们为了自己家族的生命，也要抵抗到底。在斗争的过程中，一只刚出生的小狗，成为了大英雄。','Meet Two Unlikely Heroes With A Bone To Pick.',85000000,183611771,9.895061,5.1,313,100,'2000-10-07','en','/lVFyy2LvBGk5VSsgIEEV8RTmrnh.jpg',3.0135482341348654,3,'2026-09-10',2,NULL,NULL),(10483,'死亡飞车','Death Race','本片翻拍自1975年的那部由史泰龙主演的《死亡飞车》。　　故事发生在不远的未来，一片后工业时代的荒凉废墟之上，有一座装满了各种凶神恶煞的监狱，里面的每一个犯人都曾犯下了穷凶极恶的罪行……这座监狱里的犯人们有着一个非常可怕的“娱乐项目”，其实也是监狱长强加在他们身上的，那就是每年都要举行一次残忍恐怖的体育赛事——死亡飞车，监狱长则通过网络视频让全世界都看到整个比赛过程中的血腥和暴力，以此牟取高额的利润。由于犯人可以用各种高端武器武装自己的赛车，所以在这样的竞技舞台上，纵然是壮观且引人入胜，可性命也会在瞬间陨落。　　到目前为止，已经当过三次赛车冠军的詹森·艾姆斯，算得上是这片荒蛮之地的生存专家了，也许这正好也应验了詹森常挂在嘴边的那句话：我不相信还能出现比现在更加糟糕的状况。确实，詹森正在为不是他所犯下的罪行坐牢，那是一起手段极其残忍的凶杀案，而被害人则是詹森的妻子……其实，詹森还有几个星期的时间就可以刑满释放了，然而他却被迫再一次戴上了面具，伪装成神秘的赛车手\'科学怪人\'——观众最喜爱的赛车手之一，就好像是拥有不死身的怪物一样。詹森根本就没有回旋的余地，因为“终端岛屿”的监狱长给了他一个不是选择的选择：要么穿上伪装去赛车，要么在自己的牢房中直到腐烂。　　被这样一个金属面具遮去了真实面容，詹森以一个囚犯的身份加入到这场惊心动魄、为期三天的竞赛当中，而他需要做的，就是在一大群最**的罪犯的交叉火力攻击之下寻找突破口以求生存，因为这次比赛的胜者将获得\'自由之身\'的奖励。与“科学怪人”的外形相匹配的是詹森所驾驶的那辆怪物车，车身上则配备着机关枪、喷火器和枪榴弹发射器，这个绝望的男人，发誓要摧毁一切阻挡他赢得这场地球上最可怕的赛事的障碍。','Get ready for a killer race.',45000000,73762516,42.57877,6,1175,105,'2008-08-22','en','/zXyEAZl1nCvrXI3fRzxFz9xnSTj.jpg',3.4453902486066967,3,'2026-09-10',2,NULL,NULL),(10488,'尼姆岛','Nim\'s Island','小女孩尼姆（阿比盖尔·布瑞斯林 Abigail Breslin 饰）和科学家父亲杰克（杰拉德·巴特勒 Gerard Butler 饰）一起生活在一个小岛上，父亲埋头在岛屿的科研工作，而孤独的尼姆每日把岛屿的一切幻想成绚丽多彩的冒险，倒也乐在其中。尼姆最爱读畅销冒险作家艾利克斯·卢文的书，在她的幻想中，他是个和父亲面目一样的英雄，带着她畅游这个世界。但是尼姆所不了解的是，“卢文”英雄形象背后其实是个心理问题严重的女作家（朱迪·福斯特 Jodie Foster 饰），她有严重的社交恐惧症、广场恐惧症，因此只能在大城市纽约以半隐居方式埋头写作，连走出自己房间都很困难。一日父亲杰克出海工作却几日未归，担忧的尼姆只好给心目中的大英雄卢文发邮件求救，为了遥远孤岛上的小女孩，足不出户的女作家鼓起勇气踏上前往尼姆岛的路途……','Your adventure starts here.',37000000,100076342,14.353279,5.6,330,96,'2008-04-03','en','/dWhcA4napVMD8GAetlbRIY4zpho.jpg',3.078535449407862,3,'2026-09-10',2,NULL,NULL),(10490,'美丽比一比','Drop Dead Gorgeous','《美丽比一比》是由Lona Williams编剧，Michael Patrick Jann执导，克尔斯滕·邓斯特、艾伦·巴金等主演的喜剧电影。该片于1999年7月9日在捷克上映。该片讲述了明尼苏达州玫瑰山这个破落的小城将举办一场选美大会，小城里的女孩们为了各自的梦想，无不使出浑身解数，想得到后冠，而被宠坏的贝姬（Becky）和聪明性感的安柏（Amber）就是其中的佼佼者的故事。','The battle between the good and the bad is bound to get ugly.',10000000,10571408,6.736274,6.4,86,98,'1999-07-23','en','/jGXXiatjnwhAD8Imu7DQ7LXEB3r.jpg',2.8280331597989914,3,'2026-09-10',2,NULL,NULL),(10496,'蝙蝠','Bats','基因突变的蝙蝠逃脱了','They will suck you dry',0,10,1.537859,4.1,35,91,'1999-10-22','en','/pZRcf2BwcxWg594X6XT2jkR2qdb.jpg',2.5877655822158676,3,'2026-09-10',2,NULL,NULL),(10501,'勇闯黄金城','The Road to El Dorado','图利（凯文·克莱恩 Kevin Kline 配音）和米格尔（肯尼思·布拉纳 Kenneth Branagh 配音）是一对职业骗子，意外之中得到了前往传说中的黄金之城的地图，兴奋无比的两人自认为找到了通往财富的道路，在战马奥利弗（弗兰克·维尔克 Frank Welker 配音）的帮助下，两人从囚禁他们的船舶上逃脱，踏上了冒险的旅途。 大祭司泽科尔（阿曼德·阿山特 Armand Assante 饰）企图谋权篡位，他设计了一个阴谋，将图利和米格尔捧上了神座以此笼络人心，而图利和米格尔两人必须得到土著秋儿（罗西·培瑞兹 Rosie Perez 饰）的帮助才能够抵达目的地。与此同时，在利益面前，图利和米格尔的友情亦在不断地经受着考验。','They came for the gold... they stayed for the adventure.',95000000,76432727,37.054554,7,858,89,'2000-03-31','en','/YvRPTa4reDc4KqUecKLMwG4HBd.jpg',3.5293991550798474,3,'2026-09-10',2,NULL,NULL),(10514,'人间大浩劫','The Andromeda Strain','罗伯特．怀斯导演的一部具有悬疑性的科幻片，描述美国一枚太空舱堕落墨西哥荒郊小镇上，导致镇民全部离奇死亡，仅剩一老一少受重伤未死。特别营救小组将他们救回实验室研究其病况，最终发现其中奥妙。  　　本片制作相当认真，气氛和映象亦有部分的杰出表现。但整体来说太过沉缓，描述科学家如何研究细胞分裂的过程也太详细了。','The picture runs 130 minutes!... The story covers 96 of the most critical hours in man\'s history!... The suspense will last through your lifetime!',6500000,12376563,12.524953,7,190,131,'1971-03-12','en','/4FBSFz8wLpxd4o6hnvKOJJ8WSIz.jpg',3.0579822129288017,3,'2026-09-10',2,NULL,NULL),(10521,'结婚大作战','Bride Wars','两个好姐妹的婚礼撞期，而且地点都选在了两人心心念念的地方，这让昔日的好姐妹反目成仇。','May the best bride win',30000000,114663461,33.385429,5.9,856,89,'2009-01-09','en','/pmss3fHi5BB7fzywZ9FrVCO3OIH.jpg',3.34207278964133,3,'2026-09-10',2,NULL,NULL),(10523,'W.','W.','Whether you love him or hate him, there is no question that George W. Bush is one of the most controversial public figures in recent memory. W takes viewers through Bush’s eventful life -- his struggles and triumphs, how he found both his wife and his faith, and of course the critical days leading up to Bush’s decision to invade Iraq.','A life misunderestimated.',25100000,29506464,10.445391,6.1,143,131,'2008-10-17','en','/nJm8UF4zbUYEoku9seEtz1PTJGS.jpg',2.9362022779420713,3,'2026-09-10',2,NULL,NULL),(10527,'马达加斯加2：逃往非洲','Madagascar: Escape 2 Africa','延续卖座第一集《马达加斯加》，流落荒岛的狮子艾利克斯与斑马等一行人，决定改造废弃于树头上的飞机离开无人岛，一开始还算顺利，一群动物们在飞机上开心庆祝即将回到五光十色的纽约，但随即坠落于大草原来到动物天堂「非洲」，不单如此，狮子艾利克斯在这里遇上了同类，却因为久居动物园失去沟通的本能，这一群十足观光客的外国动物，要如何融入环境？又是否能回到纽约，搞出多少笑料？','Still together. Still lost!',150000000,603900354,44.141021,6.2,1810,89,'2008-10-30','en','/wN0dsLCJdOqyH7yiadWT9e2kM12.jpg',3.5822625718605106,3,'2026-09-10',2,NULL,NULL),(10528,'大侦探福尔摩斯','Sherlock Holmes','大侦探福尔摩斯（小罗伯特·唐尼 Robert Downer Jr. 饰）即使在置人于死地之时也异常的逻辑清晰，然而办案时有条不紊的他在私底下的生活中简直就是个“怪胎”，至少在他的助手华生医生（裘德·洛 Jude Law饰）眼中他是这样一个人。他们亲手绳之以法的“黑暗巫师”布莱克大人（马克·斯特朗 Mark Strong 饰）在临死前说死亡即是开始，随后艾琳·艾德勒（瑞秋·麦克亚当斯 Rachel McAdams 饰）出现在他的身边要他帮忙找个失踪的人，而她身边有个影子般可怕人物。坊间传说黑暗巫师已经复活，他的墓地遭到破坏，而躺在棺材里的人另有其人。又到了大侦探福尔摩斯出马的时候了，然而调查过程从一开始就险象环生，助手华生医生在调查中更是险些丧命，福尔摩斯也陷入连串的迷团之中。','Nothing escapes him.',90000000,524028679,57.834787,7,5766,128,'2009-12-23','en','/momkKuWburNTqKBF6ez7rvhYVhE.jpg',4.082721424861726,3,'2026-09-10',2,NULL,NULL),(10530,'风中奇缘','Pocahontas','在勇敢的上尉庄迈斯率领下，一批来自英国拓荒者到达了美洲大陆，敲响了美丽的印第安公主宝嘉康蒂和她族人们的警钟，也开始了一个建立在欢笑爱和忠诚上的故事。可爱的浣熊米糕和小蜂岛菲莉快乐地穿梭其间：宝嘉康蒂面临改变一生的决定，又必须避免两军冲突，在充满智慧的柳树婆婆帮助下，她学会了倾听自已心中的声音，并且随著风中的色彩去追寻人生的真谛。  这是一个真实的故事，印第安公主波卡红塔丝历史上确有其人。她救了一名英国士兵，后来还远嫁英国。  　　风中奇缘的女主角是一位印地安公主－波卡红塔丝，她的传奇一生在美国是家喻户晓的故事，迪士尼将这位印第安公主的故事搬上大银幕，叙述她救了英国的探险家约翰·史密斯，并且化解了一场异族间的战争。本片强调与自然界的融合以及族群间的尊重，结局也一改迪士尼过去快乐团圆的传统， 波卡红塔丝选择了留在家乡带领族人，约翰·史密斯则受伤返回英国，留下了一个令人难以释怀的缺憾。','An American legend comes to life.',55000000,346079773,47.845589,6.7,1457,81,'1995-06-14','en','/3jKOw0BtComHCqUHOSxiCWsu0k1.jpg',3.642432040159667,3,'2026-09-10',2,NULL,NULL),(10533,'红字','The Scarlet Letter','故事发生在17世纪。赫丝特（黛米·摩尔 Demi Moore 饰）离开丈夫，孤身一人来到马萨诸塞湾的英属殖民地定居。在这里开拓的英国人信仰坚定，恪守清规，赫丝特的一些举动在这压抑的殖民地环境下颇为引人注目。当地的牧师阿瑟（加里·奥德曼 Gary Oldman 饰）英俊而富有激情，赫丝特为他的神采深深吸引，两个性情相投的人很快陷入了危险的热恋。不久殖民地方面接到了赫丝特的医生丈夫被印第安人杀害的消息，本以为可以公开关系的一对恋人等到的却是东窗事发，赫丝特为保护阿瑟，拒绝供认通奸者，自此被投入监狱直至产下一名女婴，而阿瑟则在监狱外日日承受心灵的拷问……出狱后的赫丝特戴上了通奸者的耻辱标志，同时她大难不死的丈夫突然现身，誓要将通奸者揪出以发泄心中怒火……','When intimacy is forbidden and passion is a sin, love is the most defiant crime of all.',50000000,10382407,7.44268,5.5,108,135,'1995-10-13','en','/48hQBPm8Z8LQSSjLAXwRg3yibqm.jpg',2.8457661743068945,3,'2026-09-10',2,NULL,NULL),(10534,'巨浪','White Squall','“信天翁号\"这次要从百慕大的圣乔治港出发，预计八个月后抵达加拉帕戈斯群岛。船上的14位乘客是来自海洋学院的学生。他们的国籍不同，家庭出身背景也不一样，但在船长谢尔顿的带领下，很快学会海上生存必须的本领以及自律和相处的能力，而这一切与船长的榜样力量是分不开的。然而就在航程即将结束的时候，他们遭遇到所有海员都闻之色变的无形飑--一秒钟内风速增加十几米。在白色的巨浪中，存活率据说只有万分之一……',NULL,38000000,10300000,10.047579,6.3,86,129,'1996-02-02','en','/5xF4qy44Lvv68glS7eHWH7laTqt.jpg',2.8324289737639408,3,'2026-09-10',2,NULL,NULL),(10535,'终极笑探','Spy Hard','出生入死、赴汤蹈火的反恐怖活动，这次可要栽在「终极笑探」的手里。全美无厘头搞笑天王莱斯里尼尔森，这次要完全颠覆严肃的情报员刻板印象，让你从头到尾笑破肚皮！代号WD-40的全美秘密情报组织菁英分子迪克史提尔退隐江湖已有5年之久，直到他的死对头－疯子蓝可将军奇迹式地复活，成为秘密情报局疯狂又危险的头号敌人，才被临危授命，要他复出直捣蓝可的魔窟，救出人质及阻止人类浩劫。虽然迪克年过半百，但机灵诱敌的身手和风流猎艳的功夫仍旧生龙活虎，忙得不可开交。从事爆笑的反恐怖活动，当然不能单枪匹马，幸好有妖娆的美女助阵，迪克才能不费吹灰之力，一一化险为夷','All the action. All the women. Half the intelligence.',18000000,0,11.238522,4.9,147,81,'1996-05-24','en','/yoegp9XEG4YCbJJKR0wvm0BGYpG.jpg',2.8834988435201883,3,'2026-09-10',2,NULL,NULL),(10537,'大门','The Doors','本片忠实地记述了1960年代美国迷幻摇滚代表乐队——大门乐队的灵魂主唱吉姆·莫里森（方·基默 Val Kilmer饰）从成名到自我毁灭的一生。  　　在电影学校，莫里森结识了喜欢弹钢琴的键盘手雷·曼札克，两人一拍即合，决定组建一支令世界震惊的摇滚乐队：The Doors。很快，莫里森在这里找到了其他两位乐队成员：鼓手约翰·丹斯莫和吉他手罗比·克雷格。不久，大门乐队因《Light My Fire》一跃成名，万千乐迷为之疯狂。在拥有金钱名利诸多光环后的莫里森，却始终无法被任何人真正了解，有人认为他是诗人、艺术家，也有人把他当做疯子、瘾君子。27岁的莫里森最终选择了死亡来结束这段无以伦比的个人传奇。','The Ultimate Story of Sex, Drugs & Rock \'N\' Roll',38000000,34416893,10.794175,6.7,275,140,'1991-03-01','en','/epbCZs3HLkHQnpLLiMRD0I3BIgT.jpg',3.1271871229575328,3,'2026-09-10',2,NULL,NULL),(10545,'钟楼怪人','The Hunchback of Notre Dame','耸立于巴黎的钟楼内，住着一位天善良的加西莫多，大家都称呼他钟楼怪人，从他一出生开始，就被主人浮洛囚禁着。尽管他的周遭不乏鼓励他的好友石兽，加西莫多还是渴望能一探外面的缤纷世界。直到有一开，一场愚人节的庆祝活动真的改变了他的一生……究竟美丽的吉普塞女郎爱斯梅达，会给他带来什么样的变化呢？凭着与生俱来的勇气和正义感，加西莫多能够战胜浮罗洛，为他和他的朋友赢得新生吗？',NULL,100000000,100138851,46.727941,6.8,1129,91,'1996-06-21','en','/aM7TWdeKFOpy92zCPk4ThymjVm6.jpg',3.5924024606673055,3,'2026-09-10',2,NULL,NULL),(10549,'哈姆雷特','Hamlet','本片由莎士比亚的著名悲剧改编而成，该剧以中世纪的丹麦宫廷为背景，通过哈姆雷特为父报仇的故事，借古喻今，真实的描绘了文艺复兴时期欧洲和英国社会社会的现实与矛盾，宫廷中尔虞我诈，社会上民怨沸腾，人文主义理想在这个罪恶当道的社会已无法实现。',NULL,0,0,9.814785,7.3,117,242,'1996-12-25','en','/ilurgUOp6SCl4cuhfjctj1qxlfZ.jpg',2.941439620031488,3,'2026-09-10',2,NULL,NULL),(10550,'对垒特工','Ballistic: Ecks vs. Sever','自从妻子韦恩（塔丽萨·索托 Talisa Soto 饰）在一场意外中丧生后，最优秀的联邦调查局探员埃克斯（安东尼奥·班德拉斯 Antonio Banderas 饰）决定退出工作岗位，远离复杂又危险的尘世，去过闲云野鹤的闲散生活。时间匆匆流逝，一转眼，七年过去，妻子依然在世的惊人消息让埃克斯再度走上了工作岗位，这一次，他的对手是一个代号为塞弗（刘玉玲 Lucy Liu 饰）的女特工。  　　一种极其危险的暗杀武器被研制了出来，只要将其植入人体内，便可轻松的杀死暗杀对象且不留下一丝痕迹。经过了一番追踪和调查，埃克斯找到了武器的制作者，令他震惊的是，此人的妻子不是别人，正是韦恩，而韦恩和埃克斯所生的儿子麦克（Aidan Drummond 饰）竟然成为了暗杀武器的携带者。',NULL,70000000,19924033,8.37378,4.3,97,91,'2002-09-20','en','/7Jcb486hN7hQRZTsb0RybFGeDOQ.jpg',2.784620494455543,3,'2026-09-10',2,NULL,NULL),(10555,'鲨鱼黑帮','Shark Tale','在大洋深处的南礁，以大白鲨里诺（罗伯特•德•尼罗 Robert De Niro 饰）为首的鲨鱼黑帮横行霸道，不可一世，其他鱼类对他们又恨又怕，时刻希望有人（鱼？）出来主持公道，消灭这群恶棍。里诺虽然邪恶，不过却各外疼爱他的儿子弗兰奇（Michael Imperioli 配音）和兰尼（杰克•布莱克 Jack Black 配音）。与凶暴的父亲和哥哥不同，兰尼心地善良，平易近鱼，甚至还是个素食主义者。　　吊儿郎当的清洗店小职员奥斯卡（威尔•史密斯 Will Smith 饰）欠下老板钱财，债台高筑。被五花大绑的他遭到弗兰奇的追杀，而弗兰奇却被突然出现的铁锚砸死。喜好吹牛的奥斯卡因此宣称弗兰奇死于他之手，他还间接和兰尼成为朋友。然而，这却引起鲨鱼黑帮的愤怒……','The story of what happens when one little fish tells a great white lie...',75000000,367275019,47.094369,5.8,1557,90,'2004-09-20','en','/p7FjAegzOK7bSuKD3kyQPZGmffa.jpg',3.473747593607589,3,'2026-09-10',2,NULL,NULL),(10557,'东就是东','East Is East','故事发生在1970年代，乔治.克汉是一个生活在英国索尔弗德市的巴基斯坦人，自己经营着一家私人店铺。乔治.克汉的妻子埃拉是个地地道道的英国人，出生在英格兰西北部的兰开夏州。他们一共有七个孩子。乔治一心想让一家人遵从传统的巴基斯坦价值标准和道德观念，但无奈的是七个孩子都有他们自己的想法。对乔治来说，生活更像是一次漫长的妥协。\r 顽皮的女儿米娜喜欢跟男孩子们一起踢足球而不喜欢擦脂抹粉打扮自己；嬉皮儿子沙林表面上是在学习工程学，实际上却身在艺术学校；满脑子情色浪漫的塔里克已经成了当地出名的风流浪子；萨吉德还是个乳臭未干的娃娃。纳吉尔为了不成为家庭中另一出包办婚姻悲剧的受害者，索性临阵逃脱，跑到埃克尔斯镇作起了帽子生意，自己养活自己；乔治为了让另两个儿子就范，逼着他们跟体面富有的屠户夏先生的女儿结婚……','A comedy of families, a chip shop... and a very randy dog.',3800000,28200000,3.667372,6.5,59,97,'1999-05-14','en','/tDchJ4mB23vGgwdQCmq9FCQ4W23.jpg',2.739942877179619,3,'2026-09-10',2,NULL,NULL),(10559,'黑洞频率','Frequency','如果你能够回到过去改变你人生中的一件事情，会发生什么事情？对于约翰苏利万来说，这没有问题，他将阻止一件1969年10月12日发生的一场悲剧，使他的当年做消防员的父亲能够逃离那场火灾死神的魔掌。 那个时候，约翰还只是个6岁的孩子，他的父亲死去以后，他曾经几次梦见自己想要去阻止那场悲剧，父亲的死在他的心灵上留下了重重的伤痕，直到现在已经成为了一名警察，他仍然对此事难以忘怀。  在父亲忌日前一天的暴风夜里，约翰在那座父亲留下的房间里发现了一个他曾经用过的老式收音机，他开始摆弄它，却竟然从收音机中收到了一个自称是 1969年叫弗兰克的消防员的说话，他开始与那个人交谈起来，难道这真是他的父亲吗，就是在30年前的这天夜里，他的父亲正是也在这里，难道此时他正在另一个时空中。 约翰和他谈自己的爱情，谈自己的忏悔，他们谈了整整一夜， 当他终于确信这个人正是他那年轻的父亲后，他意识到他现在可以改变一切。约翰抓紧时间提醒弗兰克在12日那可怕的火灾中如何脱身，他要将他的父亲从死神的手中挽救回来……  1999年10月12日，约翰当约翰醒来时，发现墙上有一张满头银发的父亲的照片，约翰知道自己改变了过去，眼前是一个崭新的现在，这使他欣喜若狂。然而紧接着可怕的事情又发生了，一连串残忍的凶杀案又改变了他的生活，他的母亲成为其中的牺牲者。父亲弗兰克必须再通过收音机频率回到过去，阻止一场后来改变他们家庭命运的谋杀。而每次弗兰克在他的时空中改变了一件事情，约翰一觉醒来都是一个不一样的现在……  本片是一部关于时光倒流的幻想影片，故事中充满了亲情和温馨，同时又包括恐怖的谋杀，是一部集众多卖点于一身的娱乐影片','The future is listening.',31000000,68106245,19.258041,7,462,118,'2000-04-28','en','/oifmNcY2dC6CgRY12LJ0nndvdFf.jpg',3.313879744024751,3,'2026-09-10',2,NULL,NULL),(10560,'中央舞台','Center Stage','12个满怀梦想的年轻人考入了美国芭蕾舞学院，一场关于青春与激情的“人生舞蹈剧”上演了。由于年终将有6人能有机会进入美国国家芭蕾舞剧团，年轻人都开始了精心准备决定他们的前途的那一场年终表演。舞蹈执导乔纳森（彼得•盖勒 Peter Gallagher 饰）和芭蕾舞演员库珀 （Ethan Stiefel 饰）因成为情敌而针锋相对，他们年终将各自执导一部芭蕾舞剧而令到气氛愈加紧张。乔纳森选中了优秀的莫瑞安（苏珊•梅•普拉特 Susan May Pratt 饰）和极具天赋的爱娃（佐伊•桑塔纳 Zoe Saldana 饰），他要将一出经典的芭蕾舞剧完美无暇的进行诠释；而库珀则选中了不够完美的朱迪（阿曼达•舒尔Amanda Schull 饰），他决定要上演一出完全颠覆全统的芭蕾舞剧。经典与颠覆之战将最终决定这3个女孩的归宿！ ©豆瓣','Life doesn\'t hold tryouts.',18000000,17200925,6.961736,6.8,90,115,'2000-05-12','en','/95Et0t08Nv6S8FD593HpXyvcRt8.jpg',2.851882104912158,3,'2026-09-10',2,NULL,NULL),(10563,'三人探戈','Three to Tango','奥斯卡和皮特是一对有富有才华，但却没有机会得以展示的芝加哥建筑师。商界巨子查尔斯正在考虑聘请他们俩设计一个造价数百万美元的文化中心。对两位建筑师来说，这可能成为他们事业转折的契机。然而，他们俩并非唯一的人选。纽曼也在与戴克和史特劳斯----两位奥斯卡和皮特过去曾经为之工作过的非常成功的设计家——进行接触。查尔斯认为，两组人之间的竞争对双方都会产生压力，而且还会很有趣味。  　　被奥斯卡执着的工作热情所感动，查尔斯又布置给他一个额外的任务：监视他的情妇艾米。在执行任务的过程中，奥斯卡发现自己爱上了美丽而任性的艾米，更糟糕的是，他发现查尔斯把这项任务交给他，只是因为他确信奥斯卡是名同性恋者，而艾米对此也深信不疑，奥斯卡一下成了芝加哥有名的同性恋者……  　　当奥斯卡被授予“芝加哥本年度最佳同性恋专业人才”称号的时候，他面临着一个艰难的选择，是继续这个谎言来保证工作和前途呢，还是……','All\'s fair in the war of love.',20000000,0,7.553773,5.4,62,98,'1999-10-22','en','/z2EhRgWvzNa2NgoX0uModV6mEb2.jpg',2.7339382412296565,3,'2026-09-10',2,NULL,NULL),(10564,'芳心何处','Where the Heart Is','被母亲抛弃后，诺瓦利（娜塔莉·波特曼 Natalie Portman 饰）在一辆拖车里度过了自己的整个童年时期，如今，17岁的她也即将成为一个母亲了，在这样一个重要的时刻，男友威利（丹兰·布鲁诺 Dylan Bruno 饰）却选择了将她抛弃，流落街头的诺瓦利无处可去，只能偷偷寄宿在一家沃尔玛超市中。时间流逝，诺瓦利在超市中诞下了一名女婴，她也摇身一变成为了当地的“名人”。  　　成名后，诺瓦利不仅得到了500元的资助，还获得了在沃尔玛工作的机会，与此同时，阔别多年的母亲也找到了诺瓦利，希望与她重修旧好共度余生。不幸的是，在卷跑了诺瓦利的财物后，母亲再一次消失了，好在有善良的修女和老实的图书管理员福尼（詹姆斯·弗莱恩 James Frain 饰）出手相助，诺瓦利和孩子总算找到了安身之所。 ©豆瓣','Laughter is harder... Friendship is stronger... Trust is deeper... When it comes from the heart.',15000000,33771174,6.857923,6.9,155,120,'2000-04-27','en','/bwxZ7uGZl8dt3WLCiiOoVhYS4m4.jpg',2.987454482942298,3,'2026-09-10',2,NULL,NULL),(10567,'恐龙','Dinosaur','小禽龙阿拉达生活在白垩纪晚期，他自小就生活在一个桃花园般的小岛上。由一群狐猴抚养长大大的阿拉达从来就没有见过自己的同类，与他的狐猴朋友一直无忧无虑的生活在一起。一场不期而至的流星雨将阿拉达所在的小岛击毁了，阿拉达和他的狐猴朋友一起逃难来到了大陆。这时，因为大气变热，水源供给越来越紧张，阿拉达他们遇上了一群正在迁徙寻找新的栖身之地的恐龙并加入了他们。于是，阿拉达和同伴们一起开始了这次异常艰难的迁徙之旅。','You have never seen anything like this.',127500000,354248063,26.548594,6.2,542,82,'2000-05-19','en','/iOEMaBXZko3tXbKzHoMxPPx0M4t.jpg',3.2730096574699536,3,'2026-09-10',2,NULL,NULL),(10569,'业余小偷','Small Time Crooks','本过着平凡生活的夫妻雷·温克勒（伍迪·艾伦 Woody Allen饰）和弗伦奇（崔茜·尤玛 Tracey Ullman饰），一个是有犯罪前科的洗碗工，一个是专给人修指甲的美容师。然而这平静而安稳的生活，却被雷密谋抢劫银行的计划所打破。即使妻子极力反对，可雷心意已决。他不仅找上三个愚蠢的同伴入伙实施抢劫计划，居然还千方百计地拖弗伦奇下水。可这场希望一夜暴富的美梦并非如想象中顺利，一场状况百出的银行抢劫行动爆笑上演。由美国著名导演伍迪·艾伦自编自演自导的喜剧电影《业余小偷》，沿袭了他一贯善于揶揄讽刺的喜剧风格形式。本剧一连串笑料百出的状况连连，加之带有浓厚地方色彩的机智对白，让这出幽默诙谐的“内行人笑话”，令人忍俊不禁、捧腹不止。女主角崔茜·尤玛凭借此片荣获2001年第58届金球奖电影类-音乐喜剧类最佳女主角提名。','They took a bite out of crime',0,0,11.423533,6.4,155,94,'2000-05-19','en','/eIJRFZFDmh0xXPlKt3WwN5fiSLe.jpg',2.971565371204328,3,'2026-09-10',2,NULL,NULL),(10571,'挡不住的爱妹','Boys and Girls','瑞恩和詹尼弗是两个性格迥异，彼此都对对方不感兴趣的男孩和女孩，至少他们自己都这么认为。当他们12岁认识的时候，他们就彼此讨厌对方；到中学的时候，他们还是讨厌对方。而现在，他们在大学又相遇了，个性自由的詹尼弗和谨小慎微的瑞恩发现正是他们之间的不同成为了彼此吸引对方的东西，他们之间开始了一段友谊，在他们的室有--疯癫热情的亨特和爱寻开心的阿米的帮助下，他们逐渐懂得了男孩子真正的希望和女孩子的需要，并且品尝到了友情道路上的酸甜苦辣……','Warning: Sex Changes Everything',16000000,20627372,9.119797,5.4,103,94,'2000-06-16','en','/gdVnV2wSESbgrXX4uRD3J0D8dBo.jpg',2.8366464856881426,3,'2026-09-10',2,NULL,NULL),(10577,'德古拉2000','Dracula 2000','故事从很久很久之前的远古时代就已经开始了，温西森是一个非常非常古老的家族，在家长马修（克里斯托弗·普卢默 Christopher Plummer 饰）的领导下，他们牢牢的控制着凶恶狡诈的吸血鬼一族，阻止他们在人间作恶伤人。这样的平衡一直持续到了新千年，直到以马库斯（欧玛·艾普斯 Omar Epps 饰）为首的盗窃团伙潜入了温西森家族的老宅。  　　盗贼们偷走了看似珍贵的陪葬品，却也在无意之间解开了加在吸血鬼一族身上数千年的诅咒，吸血鬼素心了，人类的末日即将来临。面对如此危机的情况，温西森家族重新回到了久违的战场，面对他们的就对手。然而，这一次，在长久的禁锢之下，这群吸血鬼们变得更加邪恶，更加凶残。','The Most Seductive Evil of All Time Has Now Been Unleashed in Ours.',28000000,33000337,6.756771,4.6,148,99,'2000-12-22','en','/9ovaFisJ8lStUOiai3JoTbiBX8b.jpg',2.859180531289218,3,'2026-09-10',2,NULL,NULL),(10585,'鬼娃回魂','Child\'s Play','美国芝加哥的午夜，杀人犯雷在警探迈克（克里斯·萨兰登 Chris Sarandon ）的追捕中身负枪伤，仓皇逃入了一家玩具店，走投无路下，雷念起咒语，将灵魂转移到了一个玩具公仔身上。在商场做售货员的单身母亲凯伦（凯瑟琳·海克丝 Catherine Hicks 饰）为儿子安迪（艾力克斯·文森特 Alex Vincent 饰）的生日礼物发愁，当她看到流浪汉出售的便宜公仔时，兴冲冲的买下了。而这个安迪渴望的礼物，实际正是那只收纳了杀人犯雷的灵魂的公仔。自称“楚其”的公仔在无人时便开口和安迪对话，并杀死了安迪的阿姨和自己昔日的同伙，安迪目睹公仔杀人的线索，却苦于无人相信。凯伦不久终于发现了公仔的秘密，但似乎为时已晚……','Chucky is one mean S.O.B.',9000000,44196684,27.600843,6.3,581,87,'1988-11-08','en','/hO1FN5m3iZN9NSXmtWDSk5KSEtN.jpg',3.304233636569094,3,'2026-09-10',2,NULL,NULL),(10586,'黑夜幽灵','The Ghost and the Darkness','约翰（方·基默 Val Kilmer 饰）是一名工程师，他即将前往遥远的非洲，去完成建造大桥的艰巨任务。到了非洲后约翰才发现，除了糟糕的气候，这里还存在着更加危险和恐怖的东西。食人狮的频繁出没让整个建设团队都无心工作，为了保证工程如期进行，英勇的约翰射杀了食人狮，却引来了更大的麻烦。\r 在当地，“黑夜”和“幽灵”两条狮子恶名远扬，它们体格巨大冷酷无情狡猾多变，前前后后造成了近40起死亡事件，如今它们盯上了约翰。在猎手雷明顿（迈克尔·道格拉斯 Michael Douglas 饰）的帮助下，约翰一次次的死里逃生，这些充满了恐惧的经历也促使约翰下定决心为民除害。','Prey For The Hunters',50000000,75000000,12.46525,6.4,236,109,'1996-10-11','en','/diTgaZ43HhqIMTPXy3K63QzwAzE.jpg',3.0707274400471616,3,'2026-09-10',2,NULL,NULL),(10588,'戴帽子的猫','The Cat in the Hat','妈妈（凯利·普雷斯顿 Kelly Preston 饰）的有事外出让康拉德（史宾塞·布瑞斯林 Spencer Breslin 饰）和塞丽（达科塔·范宁 Dakota Fanning 饰）感到闷闷不乐，妈妈一走，变得空空荡荡的房子里除了“无聊”，再无他物。令兄妹两没有想到的是，门铃竟然响了，打开门，门外站着的不是妈妈，不是陌生人，竟然是一只戴着帽子直立行走会说英语的巨猫（麦克·梅尔斯 Mike Myers 饰）。巨猫的到来让康拉德和塞丽感到十分快乐，它古灵精怪的性格和滑稽可笑的动作时常逗得兄妹两捧腹大笑。可是，随着时间的推移，这只巨猫的行为开始古怪和令人讨厌起来，更让兄妹两头疼的是，妈妈即将回家了，可巨猫似乎丝毫没有在此之前离开的打算。','Don\'t mess with the hat.',0,0,18.251129,4.9,366,82,'2003-11-21','en','/loCaacVaUnrpetb2gAh2apfsMG4.jpg',3.0361482850942334,3,'2026-09-10',2,NULL,NULL),(10589,'日落之后','After the Sunset','麦克斯·波德特（皮尔斯·布鲁斯南 Pierce Brosnan 饰）和罗拉·西里罗（萨尔玛·海耶克 Salma Hayek 饰）是一对身手非凡、亲密无间的雌雄大盗。他们纵横天下，蜚声国际，是同行欣羡崇拜的对象，也是警方和富商恐惧憎恨的目标。在与老对头FBI探员斯坦·罗伊德（伍迪·哈里森 Woody Harrelson 饰）一番斗智斗勇的周旋后，两人成功盗得一枚价值连城的钻石。之后便双双飞往位于中美洲巴哈马群岛的天堂岛，过起了悠哉游哉的隐居生活。  　　安逸的日子固然令人向往，但习惯惊心动魄、刀口舔血的麦克斯却渐渐按捺不住心中的冲动。斯坦适时出现在麦克斯的面前，从对方口中，麦克斯得知将有三颗名贵钻石在豪华游轮上展出，并经过天堂岛。技痒难耐，麦克斯决定重出江湖，殊不知斯坦和警方早已张开落网，等待大鱼上钩……','Who will walk away?',60000000,61347797,14.113066,6,226,97,'2004-11-12','en','/yxl6mEbdRURNp13Xos8OyB7CXZP.jpg',3.0360329875956884,3,'2026-09-10',2,NULL,NULL),(10590,'我们曾是战士','We Were Soldiers','故事发生在1965年的越战初期,美军第一骑兵师第七骑兵团第一营的450名战士，在盲目的指挥下，竟毫不知情、毫无准备地降落在北越军队集结的中心区域。北越方面在降落地点周围早已部署有2000以上的兵力，第一营的战士不得不面对近5倍于自己的敌人。尽管他们背后拥有强大的远程和空中火力支持，但是毕竟众寡悬殊，一营的官兵不得不展开一场异常惨重的生存保命战。 　 所幸，北越部队的情报有限，指挥也十分谨慎，没有抓住乘虚而入一举歼灭整个营地的机会。经过两天伤亡逾百人的战斗之后，第一营终于可以脱离战场，与前来解围的第二营返回基地。但是，途中由于第二营营长缺乏经验，竟然只为了审讯两名战俘，而命令丛林中已拖至500码长的纵队停止前进。以火力薄弱面撞上了北越方面的生力军，在激战中一营几乎被一扫而空。','400 U.S paratroopers. 4000 Vietnamese soldiers. 12 000 miles away from home. 1 man led them into battle.',75000000,114660784,19.708731,6.7,521,138,'2002-03-01','en','/1bDRxZSNs37Kfvw3hpGmbMGSxF.jpg',3.3111172437229683,3,'2026-09-10',2,NULL,NULL),(10591,'邻家女优','The Girl Next Door','雄心勃勃的高中生马修迷上了美丽的邻家女孩，却在无意中得知她过去曾经是色情片明星，马修的远大前程变得岌岌可危。','Matt never saw her coming... but all his friends had!',25000000,30411183,39.784026,6.3,824,108,'2004-04-09','en','/7JeFk09LCR46nE334aGZeq0qmWo.jpg',3.412723125685405,3,'2026-09-10',2,NULL,NULL),(10592,'哈特的战争','Hart\'s War','1944年，盟军已经登陆欧洲对纳粹展开反攻，在耶鲁学习法律的汤姆·哈特（柯林·法瑞尔 Colin Farrell 饰）由参议院父亲的安排下进入部队担任驻扎后方的中尉，一次护送任务中，哈特不幸被俘，被纳粹送往集中营中关押。在集中营里，出身军官世家的威廉·麦克纳马拉上校（布鲁斯·威利斯 Bruce Willis 饰）担任俘虏们的领导，他将可能出卖了盟军情报的哈特分配到士兵营房，又将两名黑人飞行员指派给哈特照顾，集中营中充斥种族歧视的气氛，哈特不得不尽力避免黑人飞行员遭受同袍的伤害，然而一名飞行员还是死于陷害，而剩下的另一名飞行员则卷入了谋杀，哈特决定为黑人辩护，向集中营中的歧视宣战……','Beyond Courage, Beyond Honor.',70000000,32287044,14.244518,5.9,241,125,'2002-02-15','en','/nCY4iGwjnwFbKWufwX0GlMQIGEz.jpg',3.042371075284825,3,'2026-09-10',2,NULL,NULL),(10603,'森林泰山','George of the Jungle','从小被猩猩养大的乔治（布兰登·费舍 Brendan Fraser饰）一直生活在茂密的丛林中，逐渐成了森林之王。白人少女乌苏拉（莱斯利·曼恩 Leslie Mann饰）与未婚夫莱尔（托马斯·哈登·丘奇 Thomas Haden Church饰）来到非洲丛林中探险。然而两人突然遭遇狮子的袭击，危急时刻，自私的男友居然扔下乌苏拉独自逃生。幸好乔治及时将她救下，将她带到丛林的树屋中。在这里，两人度过了一段美好奇妙的丛林时光，单纯善良的乔治也赢得了乌苏拉的芳心。然而死心不改的莱尔竟开枪射伤了乔治，甚至偕同几个盗猎者要抓乔治的猩猩朋友去卖钱。\r 由迪斯尼公司于1997年推出的卖座喜剧电影《森林泰山》，根据美国六、七十年代同名电视卡通系列片改编而成。真人版的《森林泰山》，风格节奏及人物塑造依旧保持着原卡通片的幽默夸张，巧妙地保留了动画风格。本片在当年的全球票房收入高达一亿七千万美元，同时也捧红了“森林之王”布兰登·费舍，使他一跃跻身为好莱坞当红小生的行列。','Watch out!',55000000,0,22.573237,5.4,496,92,'1997-07-15','en','/lWp8hUqE4oLPxsYgilXoYoVThfU.jpg',3.146921974499719,3,'2026-09-10',2,NULL,NULL),(10610,'飞龙再生','The Medallion','传说只要得到“再生龙章”的力量，死后便变成永远不灭的“不死人”。国际人蛇集团主脑“蛇魔”要绑架神秘华籍小孩Jai，其手下李斯（黄秋生 饰）与香港特警阿狄（成龙 饰）两度交锋，最终掳走Jai。阿狄远赴爱尔兰追捕李斯，在前女友妮歌（克莱尔·弗兰妮 Claire Forlani 饰）穿针引线下，到英国与屈逊（李·伊万斯 Lee Evans 饰）再度携手合作。查得李斯的货船抵达码头，众人一番混战后，舍身保住Jai的性命，自己却被淹死。而Jai身上的铁章却让另一个阿狄出现，并且拥有伤口瞬间自愈的能力，而且自己已经拥有超乎常人的体能。但“蛇魔”再次将Jai掳去并夺去他的“龙章”，获得了再生力量，超能力已超越阿狄。',NULL,41000000,0,14.653718,5.3,281,88,'2003-08-15','en','/rxKO4hOZFoCAH6OKJ9lXJcU8vMm.jpg',3.0245160372505593,3,'2026-09-10',2,NULL,NULL),(10611,'哈啦大发师','Barbershop','加尔文（艾斯库伯）从父亲那里继承到一间位于芝加哥南部的理发店，这事他父亲奋斗的成果，但在他严厉看来这间铺子一钱不值，只是个负担，是在浪费他的时间。在将铺子卖给地方上的投机商后，加尔文才意识到父亲的远见卓识，并开始为卖掉铺子感到后悔。','Everyone\'s gettin\' lined up.',12000000,75781642,10.297189,6.2,137,102,'2002-04-01','en','/awO803VGfPQW2ex7zbkMVJqCPRp.jpg',2.9313930547482627,3,'2026-09-10',2,NULL,NULL),(10615,'盖世傻侠','Pootie Tang','Pootie Tang，贫民区的音乐家/演员/民间英雄，从他的童年早期到他与邪恶的企业美国的战斗被记录下来，企图窃取他的魔法腰带并让他代言对他的人民有害的产品。Pootie必须学会找到自己，为美国所有年轻的黑人儿童打败邪恶的企业。','Too cool for words.',0,0,3.115754,5.4,43,81,'2001-06-29','en','/fNvx45x4JWHYucpnV2vuKn9TZnV.jpg',2.6507093582054804,3,'2026-09-10',2,NULL,NULL),(10622,'一个好人','一個好人','澳大利亚墨尔本，华裔厨师积奇（成龙 饰）是当地小有名气的人物，定期在电视上主持烹饪节目。  毒枭金·卡洛（Richard Norton 饰）集团颇有势力，金·卡洛本人残暴冷酷，清除了敌对帮派的卧底之后率众和对方在仓库大打出手，而枪战全过程被记者戴安娜（Gabrielle Fitzpatrick 饰）用摄影机记录。在躲避贩毒集团追逐的路上，戴安娜巧遇积奇，后者仗义出手为她引开歹徒，孰料两人分手时戴安娜错将积奇的节目录像带当做证据带走。戴安娜的住处很快被贩毒集团找到，遍搜不获的歹徒们开始将目标转向积奇。积奇女友美琪（李婷宜 饰）远道来访，特意参加了积奇的节目录制，贩毒集团在录制现场围捕积奇，经过一番街头苦战，积奇终于脱险。黄雀在后的金·卡洛敌对帮派带走了美琪，要挟积奇用录像带换人，一时间，围绕着录像带，积奇、警方、以及两个犯罪集团陷入了混乱的争夺战。','Fight first. Apologize later.',12716953,18814720,7.077505,6.3,128,113,'1997-01-31','cn','/q8MFxAhCdAEqfYEmmKfGKgOsVze.jpg',2.9136458025034893,3,'2026-09-10',2,NULL,NULL),(10623,'龙潭虎穴','Cradle 2 the Grave','世间最珍贵的宝石非钻石莫属，引无数侠盗尽折腰，然而黑钻石的价值更是无可估量。以安东尼（DMX 饰）为首的侠盗帮正在潜入一幢大厦窃取稀世黑钻石，以交中间人并转卖给神秘买家，而他们的电话却被在另一头的台湾特工苏（李连杰 饰）所窃听，并前来争夺黑钻。令安东尼始料不及的是，黑钻到手却使他们陷入四面楚歌的危险境地，业已谈妥的中间人被苏手刃，各方势力对黑钻又虎视眈眈，钻石的原主人还绑架了他女儿，以要挟他交出钻石，而最关键的钻石却已再度被盗走。如今唯一的办法只有夺回钻石，力量薄弱的安东尼不得不与苏通力合作，然而面对眼前牵一发而动全身的局面，二人能否险中取胜？','Mortal enemies make dangerous friends.',25000000,56489558,12.837116,5.8,236,101,'2003-02-28','en','/wkJ4weaOEg14V94VA0p0CP5aLY.jpg',3.0275301297581154,3,'2026-09-10',2,NULL,NULL),(10625,'贱女孩','Mean Girls','凯蒂(林赛·洛韩 饰)青春活泼，单纯可人。因为父母的工作关系，她从小在非洲长大，接受家庭式教育。同时，她在那个原始开阔的地方，凯蒂养成了隐忍坚强性格。15岁的这一年，凯蒂随父母搬到伊利诺斯州，开始了她人生第一次的校园生活。可令人不愉快的是，凯蒂的与新同学的相处根本不是她原本想象的样子。女孩儿们的世界，表面平静和睦，却波涛暗涌。为了适应新的环境，凯蒂暗自学习“生存法则”并很快凭着可人的外表加入了学校很光鲜的一个小圈子。她温顺的性格，也似乎为她赢来了一群要好的朋友。然而，一切平静，都在她爱上男孩亚伦(乔纳森·本尼特 饰)的那一刻发生了变化。原来，亚伦是学校最惹眼的女孩Regina (瑞秋·麦克亚当斯 饰)的前任男友，虽然她们已经分手，可是霸道又自负的Regina根本不能容许凯蒂的介入。于是，一场女孩之间的战争悄然开始。关于友情，关于尊严，关于诚恳，关于信任。一切的一切，女孩儿们将如何学会，如何长大。','Welcome to girl world.',17000000,129042871,36.423717,6.9,2320,97,'2004-04-30','en','/2ZkuQXvVhh45uSvkBej4S7Ix1NJ.jpg',3.779591693247125,3,'2026-09-10',2,NULL,NULL),(10628,'抢钱袋鼠','Kangaroo Jack','发型师查利•卡蓬（Jerry O\'Connell杰里•奥康奈尔 饰）和不知名的音乐人路易斯•富奇（Anthony Anderson安东尼•安德森 饰）是一对从小就在美国街头玩耍长大的好朋友。他们和当地黑帮头子马吉奥（Christopher Walken 饰）多有瓜葛，在马吉奥的责令下，他们不得不接受一项非法任务。那就是将5万美金黑钱送往澳大利亚，交给一个名叫史密斯的人的手中。  　　这个人物似乎颇为轻松，两个好朋友以度假的心态来到澳洲。然而在与一只袋鼠合影的时候，那个淘气的家伙竟然带着现金跑掉了。两个好朋友只得追在袋鼠的屁股后面，展开了一段难忘的澳洲之旅……','He stole the money... And he\'s not giving it back.',0,0,10.292864,4.3,203,89,'2003-01-17','en','/3sphb3Bm8PZ5nqLaQ4u4yv2sSyx.jpg',2.8935940904241493,3,'2026-09-10',2,NULL,NULL),(10629,'毒家新闻','Veronica Guerin','维罗妮卡（凯特·布兰切特 Cate Blanchett 饰）是《星期日独立报》的王牌记者，在母亲伯妮（布兰达·弗里克 Brenda Fricker 饰）的支持下，她一直追踪着一起特大毒品犯罪案件。维罗妮卡对于案件的报道在社会上引起了很大的反响，这在遏制当时猖獗的毒品犯罪市场的同时，亦为维罗妮卡和其儿子吉姆（保罗·罗南 Paul Ronan 饰）带来的许多的威胁和危险。  面对罪犯的威胁，维罗妮卡并没有屈服，这些无处不在的警告反而坚定了维罗妮卡调查到底的决心，在谎言和背叛之中，维罗妮卡不断接近着事件的真相，可是，终于，她还是没能逃脱犯罪分子的暗杀。维罗尼克用自己的生命换来了政府和人民的良心的触动，为改变世界做出了贡献。 ©豆瓣','Why would anyone want to kill Veronica Guerin?',17000000,1569918,9.583578,6.8,59,98,'2003-07-11','en','/1aJYz1YjcZggKsTJhCcYJ3adtcm.jpg',2.760200109222679,3,'2026-09-10',2,NULL,NULL),(10632,'猎捕游戏','The Hunted','邦汉姆(汤米·李·琼斯饰)是一名退役的美军教官，服役期间他曾为政府训练了一支具备高超技能的精英部队，邦汉姆最大的特长就是野外生存、追踪和猎杀目标。 　　这天森林中突然出现了几起谋杀案，前来捕猎的人们被一个善于伪装的杀手残忍的杀害，联邦调查局负责侦破案件的女探员(康妮·尼尔森饰)，找到邦汉姆试图寻求他的帮助。 　　起初邦汉姆拒绝提供帮助，但是当他看到现场图片和一些调查线索之后，发现这个凶手似乎受到过专门的训练，并且和自己追踪猎杀动物的手法极为相似…… 　　原来，凶手亚伦(本尼西奥·德托罗饰)正是邦汉姆以前执教时的学生之一，还曾在科索沃战争中获得过战功，但是他嗜血的天性让他无法忍受平庸的生活。他同时也是邦汉姆的一个仰慕者，对这位高超的追踪者充满了敬仰，并试图通过这样的方式来引起邦汉姆的注意。 　　靠着邦汉姆的帮助，亚伦旋即在森林中落网了，但是故事远远还没有结束。亚伦很快在大城市里面逃脱成功，而当艾比、邦汉姆再次展开追踪的时候，竟发现他们也已成为艾伦的猎杀对象，在“钢筋森林”里，游戏规则业已改变，谁会是这场捕猎游戏最终的赢家？','Some men should not be found.',55000000,34234008,8.634954,6,189,94,'2003-03-11','en','/aa365mcoWXgxBowIbGy6GH0Ewy4.jpg',2.9859236045580917,3,'2026-09-10',2,NULL,NULL),(10634,'星期五','Friday','克雷格（艾斯·库珀 Ice Cube 饰）最近厄运连连，不仅丢掉了工作，生活亦陷入了窘境之中。父亲整日跟在他的屁股后头催他找工作，让克雷格烦不胜烦，他从家中躲了出去，找到朋友史麦格（克里斯·塔克 Chris Tucker 饰）散心。史麦格是个彻头彻尾的大烟鬼，在他的生命之中，毒品是最重要，且唯一的信仰。\r 　　然而，正是史麦格对于毒品的沉迷让他遇上了大麻烦，他竟然没能控制住冲动，将毒贩大虫子（费松·拉夫 Faizon Love 饰）托付给他卖的价值两百美元的毒品给抽了个精光！这也就意味着，如果不能在限定时间内将毒款交给大虫子，那么他们就要有大麻烦了，而一直和史麦格混在一起的克雷格自然也不能幸免于难。','A lot can go down between thursday and saturday...',3500000,28215918,25.5748,7,503,91,'1995-04-26','en','/3Ya1RurP2NqaYoiok4DmfO41rCC.jpg',3.3521569269635108,3,'2026-09-10',2,NULL,NULL),(10637,'Remember the Titans','Remember the Titans','After leading his football team to 15 winning seasons, coach Bill Yoast is demoted and replaced by Herman Boone – tough, opinionated and as different from the beloved Yoast as he could be. The two men learn to overcome their differences and turn a group of hostile young men into true champions.','History is written by the winners.',30000000,136706683,25.996219,7.4,821,113,'2000-09-29','en','/825ohvC4wZ3gCuncCaqkWeQnK8h.jpg',3.5552447304525914,3,'2026-09-10',2,NULL,NULL),(10641,'纽约的秋天','Autumn in New York','一个在情场打滚多年的花花公子（里查·基尔），从来不会对任何女人动真格的，许下承诺。这次他又勾引上的，却是一个患了绝症的女子（薇诺娜·瑞德），当他了解到她的这一秘密时，可以想见他的震惊。然而更象命运捉弄的是：他发现自己真的爱上了她！尽管浪子的爱弥足珍贵，但他们在一起的时间的确是不多了....','He fell in love for the first time. She fell in love forever.',65000000,0,8.680334,5.7,135,103,'2000-08-11','en','/kqzmgpqDn15MYNCXj7WzifRK7Eu.jpg',2.9010256731413815,3,'2026-09-10',2,NULL,NULL),(10642,'呆瓜向前冲','Loser','保罗（杰森・毕格斯饰，《美国派》）是纽约大学有名的“土包子”，同学们都把他视做异类，不过美丽的多拉・蒂蒙德（米娜・苏瓦里饰，《美国派》）倒是和保罗志趣相投，保罗对多拉也是一见倾心。怎奈多拉早已心属风流倜傥的大学教授爱德华・阿尔科特（格雷戈・金尼尔饰，《尽善尽美》），而后者却只是逢场作戏。一场闹剧之后，保罗是继续做“窝囊废”，还是抱得佳人还呢？\r 　　在《美国派》中大出洋相的杰森・毕格斯这次重回校园，不过“献身”对象就由金发美女香农・伊丽莎白换作了娇小迷人的米娜・苏瓦里，一续《美国派》中的不了情。而米娜在拍摄了《美国派》、《美国丽人》、《美国处女》之后，仍然HIGH意不减，执意要与《美国派》的老搭档再来一出青春闹剧。至于杰森“闯关”的对手格雷戈・金尼尔也绝非“善类”，其在《尽善尽美》中的出色表演差点捧回一座小金人，后来一气之下，改行做了老师，玩起了“师生恋”。\r 　　担任这出喜剧幕后指挥的是蛰伏五年之久的好莱坞女导演艾米・海克林，她的上一部青春喜剧《毫无头绪》由于其独特的女性视角与执导手法，得到影评与观众的一致好评。这次复出，自然有所“提高”，故事背景从高中升到了大学。在选用演员方面，艾米也下了一番功夫：杰森・毕格斯自拍摄《美国派》以来可谓片约不断，以至于经常要同时赶几个场子，而米娜・苏瓦里借助《美国丽人》这部奥斯卡大热电影，也是红透半边天，启用这两名人气看涨的青年演员对于提升这部青春剧的号召力可谓大有裨益，加之艾米一贯的表现，相信《窝囊废》一定会吸引相当的年轻观众入场，和他们的青春偶像们一起来疯狂一番。','Dare to be different.',0,0,5.214408,5,120,98,'2000-07-21','en','/nOqWmYfgvpUA6gZjvdB0Cg24kA4.jpg',2.8398764077684873,3,'2026-09-10',2,NULL,NULL),(10643,'哥斯拉2000','ゴジラ2000 ミレニアム','哥斯拉突然从海底出现，于东海村登陆将市内的建筑物及发电厂完全破坏，虽然自队向哥斯拉展开猛烈攻击，但却完全阻止不了它前进。另一方面，危机管理情报局的官博士于茨城县的海沟发现直径200米的古代陨石，後来陨石内的有机物质与哥斯拉相遇并自我进化成巨大怪兽奥加，而哥斯拉就与奥加在西新宿展开一场生死战。','Get ready to crumble.',1000000,10037390,3.322721,5.9,43,107,'1999-12-11','ja','/wlHr0MAMr6xfC628LKLaA9mWM6w.jpg',2.659543203100746,3,'2026-09-10',2,NULL,NULL),(10646,'花花公子','Tomcats','七个好友单身汉都声称自己永不会结婚，于是，他们凑了一笔钱，打赌谁最迟结婚谁就赢得这笔钱。一晃眼，七年过去了，只剩下困窘的漫画迈克尔（Jerry O\'Connell 杰瑞•奥康耐 饰）和出名的“钻石王老五”凯尔（Jake Busey 杰克•布塞 饰）依然单身，而当初这笔钱由于投资得当而成了一笔巨额财富。这天，迈克尔在拉斯维加斯豪赌欠下了巨债，走投无路的他唯一的办法就是想方设法赢得这场打赌。  　　于是，迈克尔找到了凯尔的前女友娜塔莉娅（莎诺•伊丽莎白 Shannon Elizabeth 饰），千方百计游说了她嫁给凯尔，承诺事成之后分她一份奖金。迈克尔的计划进行得非常顺利，然而就在大功即将告成之际，他却发现自己已深深爱上了娜塔莉娅，金钱和爱情之间，他将如何抉择？','The Last Man Standing Gets The Kitty.',11000000,23430766,7.063053,4.9,74,95,'2001-03-30','en','/pAHD3TfoDJX6jCPVhICBNLBxnBH.jpg',2.7538984670378426,3,'2026-09-10',2,NULL,NULL),(10647,'让爱传出去','Pay It Forward','单亲妈妈阿琳·麦肯尼（海伦·亨特 Helen Hunt饰）生活拮据，为了抚养儿子特雷弗·麦肯尼（海利·乔·奥斯蒙特Haley Joel Osment饰）而拼命工作，唯有借酒消愁才能打发深深的失落与无助。相依为命的两母子，一直过着毫无希望的生活。然而这一切在有一天发生了改变。特雷弗的社会学老师尤金·赛门特（凯文·斯帕西Kevin Spacey饰）布置了一道特殊家庭作业：让世界变得更美好。深信善有善报的特雷弗，决心从自己做起，于是他把无家可归的流浪汉请到了自己家中。  　　以彰显人性本善，宣传世界美好为题的社会伦理片《让爱传出去》，由美国女导演咪咪·莱德执导。咪咪为本片推出全奥斯卡阵容：曾获奥斯卡最佳男主角的凯文·斯帕西担当男主角，女主角则由荣获过奥斯卡最佳女主角的海伦·亨特出演，童星海利·乔·奥斯蒙特饰演让世界变得更加美好的小主人公特雷弗。 ©豆瓣','When someone does you a big favor, don\'t pay it back... Pay It Forward',40000000,55707411,24.313684,7,432,122,'2000-10-12','en','/ogXmld4wIJ1xQg2p6LufKMcXU6.jpg',3.306669914023801,3,'2026-09-10',2,NULL,NULL),(10655,'葛底斯堡','Gettysburg','1863年7月1日，十五万名士兵在命运安排下，相会于美国的葛底斯堡；他们各自为了理想中的民主政治抛头颅洒热血。结果，有三分之一的人倒于寂静的麦田中；他们的生命创造了南北战争的转折点，这场战役是历史上的葛底斯堡之战。',NULL,0,25000000,5.529035,6.6,90,254,'1993-10-08','en','/k0XKdT3QbycMB8f2H7CEZVx2t4m.jpg',2.8420115383307167,3,'2026-09-10',2,NULL,NULL),(10656,'Subway','Subway','Fred, a raffish safe blower, takes refuge in the Paris Metro after being chased by the henchmen of a shady businessman from whom he has just stolen some documents. While hiding out in the back rooms and conduits of the Metro, Fred encounters a subterranean society of eccentric characters and petty criminals. Despite being pursued by the henchmen, Fred finds the time to flirt with Héléna, blow a safe, rob a train, evade the hapless Metro police, and start a rock band','An underground story where lives intertwine',2000000,390659,5.261065,6.3,86,104,'1985-04-10','fr','/tc3yGm9pRaY9nM9746hHE2Oe1jA.jpg',2.8214956338840995,3,'2026-09-10',2,NULL,NULL),(10658,'天降神兵','Howard the Duck','地球研究所向太空发离子光束，不料却把其它星球的动物及妖魔吸到地球来，最后还是透过星际鸭人把妖魔给打败。','You will believe that a duck can talk.',37000000,37962774,11.374306,5.1,221,110,'1986-08-01','en','/eU0dWo8PJgsSAZFbcyHiUpuLSyW.jpg',2.9622282507738764,3,'2026-09-10',2,NULL,NULL),(10661,'别惹佐汉','You Don\'t Mess with the Zohan','佐汉·德沃（亚当·桑德勒 Adam Sandler 饰）是一名供职于以色列情报机关摩萨德的特工人员，他身手矫健，力大无穷，而且天赋异秉。闲暇时沟女享乐，优哉游哉；接到任务时，便披挂上阵与来自巴勒斯坦的恐怖分子展开惊险刺激的对决。他干掉的对手不计其数，俨然一个新时代的救世主。但是谁都想不到，这个阳刚味儿十足的爷们儿心中竟然有着当美发师的梦想。他早已厌倦了打打杀杀的生活，渴望为了自己的理想而努力。','Lather. Rinse. Save the world.',90000000,201596308,40.597344,5.5,1048,113,'2008-06-05','en','/uFiNDfC4JYjP2313SJHxTCd7aJz.jpg',3.3284805614845543,3,'2026-09-10',2,NULL,NULL),(10663,'呆呆向前冲','The Waterboy','橄榄球队的茶水男孩鲍比•布施（亚当•桑德勒 Adam Sandler 饰）有人际交往障碍，反应迟钝的鲍比频频被队友们捉弄，教练瑞德认为他妨碍了队员训练，将其开除。失业的鲍比无法离开坚守了18年的茶水员工作，以不计报酬的方式投奔了一只经济状况困窘屡战屡败的大学球队“泥狗”，泥狗教练克莱恩偶然发现愤怒时的鲍比有超乎寻常的拦截能力，随力主鲍比入队，鲍比的母亲（凯西•贝茨 Kathy Bates 饰）因为担心，反对他任何离开自己身边的念头，尤其鲍比童年玩伴、问题女孩维基（费尔鲁扎•鲍克 Fairuza Balk 饰）的出现更令她忧心忡忡。瞒着母亲加入球队的鲍比帮助队伍连连获胜，并最终收获了爱情，还有别人对他真正的认可。','You can mess with him. But don\'t mess with his water.',23000000,185991646,23.839127,5.9,512,90,'1998-11-06','en','/miT42qWYC4D0n2mXNzJ9VfhheWW.jpg',3.216967509895355,3,'2026-09-10',2,NULL,NULL),(10664,'[REC]²','[REC]²','一支全副武装的四人特种部队小组奉命赶往出事地点，在自称卫生署官员的欧文医生（Jonathan Mellor 饰）的带领下，他们进入因感染而被封锁的公寓。行动开始不久，成员之一马托斯（Alejandro Casaseca 饰）即遭到攻击和感染。队长帕洛（Juli Fàbregas 饰）深感蹊跷，从欧文口中，他终于知道事件的真相。另一方面，三个少年出于好奇也钻进了公寓，他们经历了种种恐怖的场面，并因此付出代价。与此同时，特种部队和第一集中幸存的女记者安吉拉（Manuela Velasco 饰）相遇，却不知死亡之手已经伸到他们的身边……\r 　　本片是前作《死亡录像》的续集，并荣获2010年戈迪奖最佳剪辑、最佳音效、最佳特效和最佳视觉效果等数项大奖。','Fear Revisited',5600000,18469680,22.341462,6.4,489,85,'2009-09-15','es','/wRRmVg3E455RoJ82qcAqoohnvhN.jpg',3.2645433777667434,3,'2026-09-10',2,NULL,NULL),(10673,'华尔街','Wall Street','巴德·福克斯是纽约大学的毕业生，华尔街的失意经济人。在一次和大老板戈登·盖柯的面谈之后，改变了自己的生活。他为戈登寻找内幕消息，成功获知了另一位投资人莱里要收购ANC钢铁公司的信息，帮助戈登赚了一大笔钱。并成为了他的合伙人之一。巴德从戈登那里学了很多，包括操纵股市和孙子兵法。最后在收购他父亲工作了一辈子的蓝星航空公司一案中，巴德和戈登产生了“利益上的严重冲突”。以其人之道还其人之身，巴德用戈登教的反击了戈登，并挽救了蓝星公司。但也因为操纵股市而入狱……','Every dream has a price.',15000000,43848069,24.898687,7,546,126,'1987-12-10','en','/y7VHs2ofPYZwlwU6DCaDq6VeKNs.jpg',3.373704283187489,3,'2026-09-10',2,NULL,NULL),(10674,'花木兰','Mulan','花木兰是家中的长女，性格爽朗率真，父母极力想帮女儿找到一个好归宿，可是多次努力未果。此时却收到了北方匈奴侵略的消息，朝廷召集各家各户的壮丁。木兰父亲也在名单之内，木兰不忍年迈残疾的父亲征战沙场，决定割掉长发，偷走父亲的盔甲，决定女扮男装代父从军。花家的祖先为了保护木兰，便派出了心地善良的木须从旁帮忙。从军的过程中，木兰凭着坚强意志，通过了一关又一关的艰苦训练，她的精神也感动了所有战友。就在战况告急的时候，她也被发现了女子的身份。她被遗留在雪地中，而最后也是她的及时出现，顺利协助大军击退了匈奴。','This time, the princess saves the prince.',90000000,304320254,67.427755,7.6,2008,88,'1998-06-18','en','/jAbexAtB0aSfP5Ay4TpWHARyVnG.jpg',3.966726305322035,3,'2026-09-10',2,NULL,NULL),(10676,'月光光心慌慌3：女巫季节','Halloween III: Season of the Witch','埃里·埃里·格里姆布林（Daniel Challis）博士和艾莉·格里姆布里克（Ellie Grimbridge）绊倒了一个可怕的谋杀计划，当时Ellie的新奇推销员的父亲哈里（Harry）在拥有由三叶草银面具公司制造的奇怪面具的同时被杀害。该公司的所有者Conal Cochran希望使用他的面具将万圣节返回到更黑暗的根源 - 他无法形容的计划将在全国各地释放死亡和破坏。','...and now the earth will run with blood again!',2500000,14400000,12.030456,5,229,98,'1982-10-22','en','/xQoJzmvzYSc8a8jpGdG9SXGi8Af.jpg',2.962291532945499,3,'2026-09-10',2,NULL,NULL),(10678,'爱到房倒屋塌','Bringing Down the House','Straight-laced lawyer, Peter Sanderson (Steve Martin) meets and falls in love with online chat friend \"Lawyer-Girl\", Charlene Morton (Queen Latifah), only to discover she\'s a convicted bank robber. Charlene escapes from jail and comes looking for Peter to help clear her name.','Everything he needed to know about life, she learned in prison.',20000000,132675402,8.351385,5.4,183,105,'2003-03-07','en','/jic0ULHTcqQQaCSIEw6SAhHhIPA.jpg',2.9423435704982364,3,'2026-09-10',2,NULL,NULL),(10681,'WALL·E','WALL·E','WALL·E is the last robot left on an Earth that has been overrun with garbage and all humans have fled to outer space. For 700 years he has continued to try and clean up the mess, but has developed some rather interesting human-like qualities. When a ship arrives with a sleek new type of robot, WALL·E thinks he\'s finally found a friend and stows away on the ship when it leaves.','An adventure beyond the ordinar-E.',180000000,521311860,66.390712,7.8,6296,98,'2008-06-22','en','/hbhFnRzzg6ZDmm8YAmxBnQpQIPh.jpg',4.338721750781439,3,'2026-09-10',2,NULL,NULL),(10683,'爱我就让我快乐','Happiness','这部作品既令人毛骨悚然地好笑，又大胆地充满同理心，不安氛围的缔造者托德·索伦兹通过描绘渴望联结的受损灵魂，揭示了美国中产阶级郊区“常态”之下的存在之虚空。一支非凡的群戏阵容——包括菲利普·塞默·霍夫曼、简·亚当斯、劳拉·弗林·博伊尔、本·戈扎那、迪伦·贝克——演绎了一系列松散相连的新泽西怪胎、抑郁者与不合群之人：包括一个受挫的色情电话骚扰者、一个隐藏恋童癖好的模范父亲、一个藏着骇人秘密的孤独女人——他们所有人都只为一件事：被爱。作为1990年代最具争议的影片之一，本片之所以毫不退缩地令人不安，恰因它敢于正视那些最常被剥夺人性之人身上的人性。[标准收藏]','Finding happiness can be a tragic comedy.',3000000,2807390,10.757539,7.4,194,139,'1998-10-16','en','/rYfUcEV88Z3gENrfYTE6i8yBkDr.jpg',3.084598989036012,3,'2026-09-10',2,NULL,NULL),(10684,'生死豪情','Courage Under Fire','海湾战争中，坦克部队军官沙林（丹泽尔•华盛顿 Denzel Washington 饰）一次判断失误下令击毁了己军的坦克，令到好友鲍德温意外死亡了。虽然军事法庭判他不需承担责任，然而他还是日夜受着良心的煎熬，一直想找鲍德温的父母说明此事，却也一直没有勇气。  　　上司为了给沙林授勋，派他调查战争中一起机械师勇救士兵牺牲的事件。沙林调查中发现勇救士兵而英勇牺牲的竟然是卡伦（梅格•瑞安 Meg Ryan 饰）竟然是个女人！但现场的几名士兵的供词自相矛盾、漏洞百出。在沙林对其中一名士兵墨菲逼问后，墨菲竟然自杀了。随着墨菲的自杀，事件的真相慢慢浮出水面…… ©豆瓣','A medal for honor. A search for justice. A battle for truth.',46000000,100860818,12.971122,6.2,232,117,'1996-07-04','en','/vDJurMJkrx049AiXa3DJx5Zx7a4.jpg',3.053422025341608,3,'2026-09-10',2,NULL,NULL),(10685,'正义守望者','The Watcher','联邦调查局的代理人乔尔·坎贝尔（Joel Campbell），经过多年的追捧，连连杀手都被烧毁，并被贝壳震惊，逃离了洛杉矶，在芝加哥为自己开创了新的生活。但是五个月后，当他的新故乡成为一场特别可怕的谋杀事件的时候，乔尔最好的计划就突然缩短了 - 一个只能由一个人犯下的谋杀案：大卫·艾伦·格里芬（David Allen Griffin）。乔尔是最难以捉摸和狡猾的人之一，格里芬已经跟随他以前的追击者到芝加哥，以打一场虐待猫和老鼠的游戏。嘲笑乔尔与他的预期受害者的照片，并使他的犯罪现场非常没有线索，以保持警察在海湾，格里芬从看到乔尔反应每一个动作，看着他的受害者死亡，得到了很多的乐趣。但是，当格里芬进入乔尔的内圈时，乔尔必须快速找到一些方法来阻止他，在他接近他的人成为下一个死亡之前。','Don\'t go home alone.',33000000,0,7.339908,4.9,110,96,'2000-09-08','en','/jKU3wXEOrYTmrWQtN59QHB7XiPS.jpg',2.8254823161829417,3,'2026-09-10',2,NULL,NULL),(10691,'美丽痴狂','Crazy/Beautiful','妮可尔（克尔斯滕·邓斯特 Kirsten Dunst 饰）自小成长与富裕的家庭，衣食无忧的生活将她的性格培养得十分乖僻。在妮可尔就读的贵族学校中，大部分的学生和妮可尔有着相似的家境和精力，他们空虚的生活，只能由酒精和毒品来填充。  　　一个名叫卡洛斯（杰伊·赫尔南德兹 Jay Hernandez 饰）的转校生吸引了妮可尔的注意，尽管卡洛斯的家境普通，但他的言谈举止之中所流露出的一种独特气息让妮可尔忍不住的想要向他靠近。随着时间的推移，妮可尔和卡洛斯之间的距离越来越近，两个年轻的心碰擦出了火花。然而，当卡洛斯第一次见识到妮可尔那近乎于病态的坏脾气之时，他还是吓坏了。','When it\'s real. When it\'s right. Don\'t let anything stand in your way.',13000000,16929123,6.130096,6.6,96,99,'2001-06-29','en','/1kxn6w6lvKkrhmVxfVqI0cfBmLa.jpg',2.858196767111546,3,'2026-09-10',2,NULL,NULL),(10696,'星梦泪痕','Glitter','六七十年代的纽约，一个有着非凡音乐天赋的小女孩比莉诞生了，但伴随着她童年的不是欢乐的歌声，而是动荡凄惨的生活。她的父母抛弃了她，她成为了一名被收养的孤儿，然而她从来都没有放弃自己的梦想，那就是成为一名伟大的音乐家。  　　长大之后，比莉邀请两名朋友组成了一个女子乐队，在纽约的某个俱乐部开始她的寻梦之路。一次偶然的机会，颇有名气的DJ朱利安.戴斯发现了比莉这块璞玉，在他的力捧之下，比莉终于红透了半边天，灰姑娘的美梦也终于成真了...','In music she found her dream, her love, herself.',22000000,5271666,3.809131,3.4,38,104,'2001-09-21','en','/388ru0R7fnBFPaVuJe4caRGGh54.jpg',2.597667757450908,3,'2026-09-10',2,NULL,NULL),(10705,'亨利五世','Henry V','在肯尼斯·布拉纳改编的威廉·莎士比亚《亨利五世》中，这位英格兰国王入侵法国，并在百年战争中赢得了阿金库尔战役。','The great adventure of a king who defied the odds to prove himself a man.',9000000,0,4.641006,7.4,71,137,'1989-10-05','en','/w9R2HsYNnfF3m9uEo2UAmPNJr8a.jpg',2.807350841273462,3,'2026-09-10',2,NULL,NULL),(10707,'鱿鱼和鲸','The Squid and the Whale','本片以一种令人揪心的坦诚，记录了1980年代布鲁克林公园坡区两个年幼的兄弟在作家父母离异后，于家庭破碎的崎岖边缘摸索前行的经历。诺亚·鲍姆巴赫这部备受赞誉的第三部剧情片标志着他转向愈发个人化风格的关键发展——这一转变为他赢得了奥斯卡最佳原创剧本提名。影片以超级16毫米胶片拍摄，杰夫·丹尼尔斯、劳拉·琳妮、杰西·艾森伯格与欧文·克莱恩贡献了四重细腻而含蓄的表演。这部交织着自传元素的喜剧性家庭剧，巧妙捕捉了一个破碎家庭的心碎与迷茫。[标准收藏]','Joint custody blows.',1500000,11098131,13.788054,6.9,226,81,'2005-10-05','en','/z4Di7n3s53C3oyWjsW3Gic0GLZz.jpg',3.0992240181544353,3,'2026-09-10',2,NULL,NULL),(10708,'奶爸安亲班','Daddy Day Care','失业后，这名全职奶爸抓住机会，开办了一家日托中心，把更多孩子接到家中照管，同时还要应对各种恶作剧','Who\'s your daddy?',60000000,164433867,18.106021,5.6,506,92,'2003-05-03','en','/uiey5XUKuPicwpIJMf1OpaOd1jL.jpg',3.164607809564854,3,'2026-09-10',2,NULL,NULL),(10710,'终极贱靶','Envy','蒂姆（本·斯蒂勒 Ben Stiller 饰）是一位平凡无奇的小职员，每天过着朝九晚五的规律生活，日子波澜不惊。最近，蒂姆有些郁闷，这其中的原因，要归结到蒂姆的好友尼克（杰克·布莱克 Jack Black 饰）身上。\r 　　尼克和蒂姆是老相识了，两人之间的友谊经历了漫长时间的洗礼，愈发历久弥新，然而，这坚实的友谊却最终败在了一笔飞来横财之上。原来，尼克发明了一种可以用来稀释难闻气味的喷雾剂，正是这不经意的小小发明给尼克带来了数以百万计的巨大财富。看着曾经和自己境遇相似的朋友一下子“飞上枝头变凤凰”，本应该替朋友的发达感到高兴的蒂姆内心却五味杂陈。','Success didn’t go to his head, it went to his neighbor.',40000000,0,9.842771,4.8,139,99,'2004-04-30','en','/vrsZUr8R041YzINcy9SFe5iSM1m.jpg',2.8662281975057637,3,'2026-09-10',2,NULL,NULL),(10712,'远离天堂','Far from Heaven','一对理想的1950年代夫妇，面对同性恋与跨种族关系的社会禁忌——但代价巨大。','It\'s time to stop hiding from the truth.',13500000,29027914,9.982885,6.9,144,107,'2002-09-01','en','/9gQuvFDRPLx39smUvyafm36tp0d.jpg',2.9762584304973023,3,'2026-09-10',2,NULL,NULL),(10715,'巨星总动员','Looney Tunes: Back in Action','因为不满工作待遇，达菲鸭（Joe Alaskey 配音）要求离开华纳电影公司，为了保证这个淘气鬼在外面不惹麻烦，公司的副总裁凯特（珍娜·艾夫曼 Jenna Elfman 饰）表面上命令一直郁郁不得志的龙套演员德瑞克（布兰登·费舍 Brendan Fraser 饰）护送达菲鸭，实则是为了监视它的一举一动。 德瑞克的父亲达米安（提摩西·道尔顿 Timothy Dalton 饰）失踪已久，其原因要归结到一块拥有强大法力的“神秘之石”上。达菲鸭得知了有关石头的秘密，心中蠢蠢欲动的它说服了德瑞克，两人随即踏上了寻找达米安踪迹的旅途。与此同时，兔八哥（Joe Alaskey 配音）和凯特亦得知了神秘石的消息，面对如此珍宝，他们自然不会善罢甘休。','Real life has never been so animated.',80000000,68514844,16.715631,5.6,297,90,'2003-11-14','en','/q0kntpdsHA0QdYjpQdNBqrVTdQq.jpg',3.064531625817206,3,'2026-09-10',2,NULL,NULL),(10718,'极速酷客','Torque','福特（马丁·亨德森 Martin Henderson 饰）是一名赛车手，曾经，他效力于凶残而又狠毒的毒贩亨利（马特·斯查尔兹 Matt Schulze 饰），如今，重返家乡的他只希望能够和女友夏恩（莫奈特·玛佐 Monet Mazur 饰）一起过上平静的生活。  　　然而，亨利显然并不愿意放过福特，在各种威逼利诱福特重新回到他的身边无果之后，亨利将一桩杀人案栽赃到了福特的头上，而死者不是别人，正是飞车党老大泰瑞（艾斯·库珀 Ice Cube 饰）的弟弟，于是，泰瑞开始了对于福特锲而不舍的追杀，与此同时，联邦调查局亦因此而对福特展开了追踪调查，在如此危机的情况之下，腹背受敌的福特能否证明自己的清白？','Circuit of Fire',40000000,46546197,7.360793,4.7,119,84,'2004-01-16','en','/pY35tW8BMAjZewl87OxjXK8ui02.jpg',2.83067707196533,3,'2026-09-10',2,NULL,NULL),(10719,'圣诞精灵','Elf','平安夜，圣诞老人（爱德华·阿斯纳 Edward Asner 饰）来到一家孤儿院给无家可归的孩子们送圣诞礼物。然而一个淘气的小婴孩不小心爬进了圣诞老人的玩具袋子里，居然被圣诞老人带回了北极。仁慈的圣诞老人收留了这个意外的小访客，并在小精灵们的帮助下，一同抚养他长大成人。可随着年龄的增长，渐渐成年的他（威尔·法瑞尔 Will Ferrell 饰）长得却比其他精灵们大出三倍之多，大家由此给他取了个绰号“大个巴迪”。偶然间，巴迪得知自己并非精灵种族而是人类。于是巴迪踏上了前赴纽约寻找家人的旅程。终于，巴迪找到了失散已久的生父沃尔特（詹姆斯·凯恩 James Caan 饰）和素未蒙面的新家人。可正在筹划圣诞图书而忙得不可开交的沃尔特，并不知道儿子巴迪的存在。面对陌生的现实世界以及冷漠的人情世故，巴迪显得有些举足无措。马上又是圣诞节了，巴迪决定用自己的方式，给他的新家人以及整个世界一份最惊奇的圣诞礼物。','This holiday, discover your inner elf.',32000000,173398518,16.901954,6.4,987,97,'2003-10-09','en','/wmaAJQ0q1SLu0KSzvGGrAtmXkG7.jpg',3.419374914851659,3,'2026-09-10',2,NULL,NULL),(10724,'火狐','Firefox','苏联研发出一种革命性的新型喷气战斗机，代号“火 狐”.英国人担心这种战机将会被用作第一次打击的武器.据说这种战机能避过雷达的探测.  他们派前越战王牌飞行员米切尔.甘特去苏联执行偷窃“火 狐”战机的任务.在内线人员的协助下，甘特避过跟踪，潜入机库，开走了“火 狐”一号，  绕开了围追堵截，并顺利地在北极冰原从己方潜艇加到燃料，最后击落追踪他的“火 狐”2号，顺利飞返基地.  （本片由伊斯特伍德导演并主演）','...the most devastating killing machine ever built... his job... steal it!',18000000,70687344,8.700565,5.5,139,136,'1982-06-13','en','/xP6VaKdFEriMzPXe3j5YyDF3ryS.jpg',2.897270289953994,3,'2026-09-10',2,NULL,NULL),(10727,'暗夜鬼叫声','Darkness Falls','在美国的传说中，孩子要把换掉的牙齿放到枕头下，当他们睡着后牙仙会来拿走牙齿，如果这时孩子不慎看到牙仙的脸，他们就将被残忍杀死。  　　小男孩凯尔（Joshua Anderson 饰）刚刚掉落最后一颗乳牙，牙仙的传说吓得他无法安然入睡。当晚他从梦中突然醒来，看到了牙仙带着面具的狰狞面孔。他逃跑时打翻蜡烛，火苗烧到牙仙的眼睛。接下来惨剧发生，凯尔的母亲（Rebecca McCauley 饰）被愤怒的牙仙残忍杀害。次日警方勘查现场，一致认定凯尔是杀母凶手。12年后，离开监狱的凯尔（Joshua Anderson 饰）半岛拉斯韦加斯，他无论走到哪里都随身带着蜡烛，睡觉的房间夜晚必定灯火通明。所有的人都认为他是疯子，但凯尔知道，怀恨在心的牙仙十几年来无时无刻不在谋划夺取他的性命……','Evil rises.',0,0,11.199544,4.9,161,86,'2003-01-24','en','/qoceKsM15yL5Tmyuhkdl7vM5Vi4.jpg',2.898271884535688,3,'2026-09-10',2,NULL,NULL),(10731,'委托人','The Client','马克 是一名11岁的少年，一日，年幼的他目睹了一个男人自杀的全过程，在死前，男人告诉了马克一个惊天秘密。受惊的马克随即接受了警方的盘问，但对于那个不能说的秘密，马克选择了守口如瓶。可即便如此，马克还是被和黑手党暗中勾结的联邦检察官福特里格 给盯上了，后者向马克提出了控诉。 马克雇佣了精明的女律师洛芙 为其辩护，在两人的联手之下，他们破获了福特里格的阴谋并得到了证据。可是福特里格并没有善罢甘休，而是暗中向马克发起了更为卑鄙的攻击。马克全家人的命运都握在了洛芙的手中，面对压倒性的权利，洛芙能够获得最终的胜利吗？','A district attorney out for a conviction. A new lawyer out of her league. A young boy who knew too much.',45000000,117615211,17.746719,6.4,278,119,'1994-07-20','en','/tkl1nWwNQ18QgfGGGNV2NQAQOjW.jpg',3.120936840568428,3,'2026-09-10',2,NULL,NULL),(10733,'边城英烈传','The Alamo','\"故事发生在1836年，德克萨斯的军事堡垒阿拉莫遭到了独裁者安东尼奥（埃米利洛·艾切瓦利亚 Emilio Echevarría 饰）带领的精锐部队的攻击，这也就意味着，驻守在阿拉莫的两百名平民，必须要面对数千名装备精良的专业士兵。这是一场根本就不可能胜利的战争。\r 在这命悬一线的紧要关头，威廉少尉（帕特里克·威尔森 Patrick Wilson 饰）、詹姆斯（杰森·帕特里克 Jason Patric 饰）和西部牛仔大卫（比利·鲍伯·松顿 Billy Bob Thornton 饰）勇敢的站了出来，领导着其他来自各行各业的勇士们和敌人展开了殊死搏斗。十三天后，阿拉莫尸横遍野，然而，勇士们所争取到的时间使得萨姆将军（丹尼斯·奎德 Dennis Quaid 饰）得以领兵赶往此处，并且最终击退了墨西哥军队。\"','You will never forget',145000000,25819961,10.660441,5.8,106,137,'2004-04-07','en','/x4eBGfhznJ9wIxMVbSN9oJdtwM8.jpg',2.860911383260478,3,'2026-09-10',2,NULL,NULL),(10734,'逃出亚卡拉','Escape from Alcatraz','弗兰克莫瑞斯（克林特·伊斯特伍德 Clint Eastwood 饰）是一名银行抢劫犯，在一个雨夜被关进亚卡拉，入狱后与Limtus（弗兰克·罗茨 Frank Ronzio 饰）结交，并在监狱图书馆工作。智商极高的他决定越狱！在这个被认为无法逃离的监狱，他能不能成为第一个成功越狱者……','No one has ever escaped from Alcatraz...and no one ever will!',8000000,43000000,26.356697,7.2,561,111,'1979-06-22','en','/uORr2GXQnyqgBOg6tVsRCJD2qxc.jpg',3.41078382719852,3,'2026-09-10',2,NULL,NULL),(10735,'水瓶座女孩','What a Girl Wants','17岁的达芙妮(阿曼达•伯恩斯饰)自小与母亲利比(凯莉•普雷斯顿饰)生活在一起，从小开始她便希望她的每个生日都能有父亲的出现。开朗活泼的她看到传统的父女共舞这一环节便会深深的黯然下来。她决定，到英国寻找身份地位显赫的父亲——亨利爵士（科林•菲尔什饰）。当年父亲不爱爵位爱美人，遭到了家族的不满，母亲也在父亲助手的欺骗下离开了那座美丽的城堡。寻找父亲的过程中，达芙妮也找到了自己的爱情。她的到来让父亲原本平静的参政生活带来了很多的冲击。她的到来威胁到了父亲的未婚妻及女儿的地位，就算她们想尽办法让达芙妮出糗，但她还是可以夺得最多的关注，成为焦点。为了父亲，她不得不改变自己的作风，她开始茫然了，男友也因为她的改变深感失望。最后，她能否如愿与父亲一起跳舞，而她的爱情又会否归来呢？','Trying to fit in. Born to stand out.',0,0,7.057765,5.8,368,105,'2003-03-27','en','/gGpMruX59KWNuAXgHpiAm8hiChw.jpg',3.1019402766487345,3,'2026-09-10',2,NULL,NULL),(10739,'奇招尽出','Anything Else','从看到阿曼达（克里斯蒂娜·里奇 Christina Ricci 饰）第一眼起，杰瑞（贾森·比格斯 Jason Biggs 饰）就深深的爱上了她，尽管此时的杰瑞身边已有佳人相伴而阿曼达亦名花有主，但这残酷的事实依旧无法阻挡杰瑞渴求阿曼达的心。并且，撇开世俗道德不谈，两人也确实是天设地造的一对。就这样，都并非“自由身”的两人走到了一起，而他们之间的私情很快就东窗事发了，杰瑞的女友和阿曼达的男友选择退出，杰瑞终于可以名正言顺的和阿曼达出双入对了。如果你以为故事到这里就结束了那可真是大错特错，好不容易在一起的杰瑞和阿曼达之间发生了巨大的分歧和矛盾，两人之间的感情眼看着岌岌可危，为此，杰瑞向自己的导师大卫（伍迪·艾伦 Woody Allen 饰）求助，殊不知，这个在自己眼中无坚不摧的男人，在生活上其实也千疮百孔。','In any relationship one person always does the heavy lifting.',0,0,8.945081,6.2,149,108,'2003-08-27','en','/bvyoWDh60R31ZE5L8TjZ8Qpv5xM.jpg',2.9467124592439147,3,'2026-09-10',2,NULL,NULL),(10740,'重生','Birth','事情发生在Anna与未婚夫准备婚礼的时候，一个年仅十岁的小男孩出现在面前，还自称是Shawn。Anna目瞪口呆。十年前，Anna的未婚夫Shawn意外身亡，用了十年时间平复创伤的Anna刚重新开始新的生活就面临如此怪异的事情。一开始谁也没把小男孩的话语当真，但是小男孩能清晰地说出他们过去的每一个点滴，Anna渐渐软化，开始相信，上天把她的爱人归还给她。  Anna的好朋友却不相信。追随着小男孩的脚步，她知道是当年自己亲手埋下的因导致了今天发生的一切。  用了十年都无法忘怀的爱情，到头来只是一场骗局。','Be careful what you wish for.',20000000,0,7.698075,5.9,179,100,'2004-09-08','en','/5ECjRA94PfQHYIpioKvoFFcQ0Vq.jpg',2.9664208227453748,3,'2026-09-10',2,NULL,NULL),(10741,'鲍比','Bobby','影片再现了美国历史上最具标志性的悲剧夜晚，1968年6月6日美国参议员罗伯特·F·肯尼迪遇刺当夜。美国洛杉矶“大使酒店”，22位见证这一切的酒店职员和房客们的命运从此发生了意想不到的转变。互不相识却有着千丝万缕联系的众人，在这一历史时刻成为了目睹一切的幸存者。  　　由导演艾米利奥·艾斯特维兹自编自导自演的人物传记影片《鲍比》，汇集安东尼·霍普金斯、哈里·贝拉方特、海瑟·格拉汉姆、海伦·亨特、黛米·摩尔、莎朗·斯通等众多影坛巨匠。本片荣获2006年第63届威尼斯国际电影节传记电影奖，入围2006年第63届威尼斯国际电影节金狮奖，并荣获2007年第64届金球奖电影类-剧情类最佳影片提名等多项大奖。','He saw wrong and tried to right it. He saw suffering and tried to heal it. He saw war and tried to stop it.',0,0,11.706309,6.4,119,120,'2006-09-05','en','/ea6aSTUFQopOW7kWFZB9AvMYnbs.jpg',2.9122195884569635,3,'2026-09-10',2,NULL,NULL),(10743,'行骗天下','Confidence','杰克（爱德华•伯恩斯 Edward Burns 饰）是一个千术高明的骗子，加上他的英俊长相，行骗屡获成功。这天，杰克和他的朋友打起了会计师温斯顿（达斯汀•霍夫曼 Dustin Hoffman 饰）的主意，他们伪装成一个艺术团体，轻而易举地从温斯顿那里骗来了500万美金。岂料杰克得手后，也引来了各种狐朋狗友来分一杯羹，那500万美金很快就都被瓜分干净。\r 　　糟糕的事情接踵而至，那名被骗的会计师温斯顿原来是当地黑手党的一个头目，当他得知自己被骗后，暴跳如雷，派人狠狠地修理了杰克。当温斯顿得知自己的500万已经被抢掠一空时，他威逼杰克设计一个骗局为他骗取500万美金。无奈之下杰克只好设计了一个骗局，一切都准备妥当时，意想不到的事发生了！ ©豆瓣','It\'s not about the money. It\'s about the money.',0,0,9.87419,6.4,126,97,'2003-04-25','en','/yJzmAtY9DmhhjJwFnW0Zjlvz6yg.jpg',2.920953063113327,3,'2026-09-10',2,NULL,NULL),(10744,'倒霉蛋','The Cooler','伯尼可以算是整个拉斯维加斯赌城最倒霉的人，这个大霉人却意外被赌场大老板一眼相中。赌场大老板聘请伯尼到赌场工作，利用其扫帚星特质来牵制赌场的幸运赌客。但是，霉人终于得到了上帝的垂青，伯尼遇见了他的幸运女神，陷入爱河的他运气急转直上，老板于是决定拆散伯尼的爱情，于是闹出了一场闹剧。','When your life depends on losing... the last thing you need is lady luck.',32000000,0,9.976428,6.7,89,101,'2003-01-17','en','/gq3cZxo7SS6HAXdaxObLIyw9N1r.jpg',2.8528779464373972,3,'2026-09-10',2,NULL,NULL),(10748,'新乌龙女校','St Trinian\'s','坐落于美丽乡间的圣·崔尼安女子学院，是一所臭名昭著的学校。女校长卡米拉·弗里敦（鲁波特·埃沃雷特 Rupert Everett 饰）癫狂夸张，特立独行。有道是上梁不正下梁歪，连带着其手下的员工和学生也一个个粗暴无行、乖张无比。好在卡米拉极力提倡自由与个性，因此这里宛如女孩们的无上天堂。某天，卡米拉的侄女安娜贝尔（妲露拉·莱莉 Talulah Riley 饰）被他的父亲（鲁波特·埃沃雷特 Rupert Everett 饰）强令转学至此，这个乖乖女受到同学和老师的好一阵捉弄，几近崩溃。  　　与此同时，古板的教育部长乔夫雷（科林·费尔斯 Colin Firth 饰）决心改革糟糕的教育现状，而圣•崔尼安正是首当其冲的整改对象。自由的天堂危在旦夕，女孩们不愿坐以待毙，甚至连安娜贝尔也参与到这场拯救学校的战争中来……','Taking higher education to a new low.',0,0,7.377587,5.6,142,101,'2007-12-21','en','/ipcs1V7qB1mRp7uUVBHd6O5i6cV.jpg',2.9032145616233755,3,'2026-09-10',2,NULL,NULL),(10756,'惊悚豪宅','The Haunted Mansion','吉姆·埃佛斯（艾迪·墨菲 Eddie Murphy 饰）是一名巧舌如簧、口才一流的房地产商人。凭借出色的经营手段，他和妻子儿女过着安逸自在的生活。这一天，吉姆迎来了和老婆莎拉（玛莎·托马森 Marsha Thomason 饰）的结婚纪念日。当晚，吉姆收到一通卖方电话。那是一幢价值不菲的豪宅，他见钱眼看，临时改变了和家人的度假计划，先取道前往这幢位于荒郊野外且拥有上百年历史的宅邸。这里阴森恐怖，荒凉诡异。而接待他们的老管家兰斯利（Terence Stamp 饰）和男主人格雷斯（Nathaniel Parker 饰）更为古怪。暴风雨阻断了埃佛斯家的行程，他们被迫留在格雷斯庄园，却发现这里竟是一幢鬼魂出没的恐怖鬼屋……','Check your pulse at the door... if you have one.',90000000,182290266,16.302378,5.2,466,99,'2003-11-25','en','/zJDzZWe2gB1amzCNQMXGeyB9sY.jpg',3.0988640745331435,3,'2026-09-10',2,NULL,NULL),(10758,'女招待','Waitress','吉娜(凯丽•拉塞尔 饰)擅长制作各种美味非常的馅饼,她把每天在生活中的经历都化为做馅饼的灵感。但实际上她的生活并不快乐，她被一段名存实亡的婚姻困扰多年。她一心想参加馅饼比赛，得到足够多的钱之后离开丈夫厄尔（杰瑞米•西斯托 饰）现自己怀孕了，她知道自己的丈夫是个自私的人，无法养育孩子。她十分迷茫之际，遇到了妇产科医生波马特（内森•菲利安 饰）并且两人疯狂的恋上了，波马特也是个已婚之人。她知道自己的行为是错误的，但她还是不能控制的与波马特见面，受尽良心谴责的她从朋友身上得到了很多的启示。就在女儿出生当天，她决意要与丈夫分开，也要好好处理与波马特的关系。','If only life were as easy as pie',2000000,22179430,9.67299,6.7,129,108,'2007-05-25','en','/ux3SPTHHmJytSjWEaV7xlo9nbOZ.jpg',2.9393609319838583,3,'2026-09-10',2,NULL,NULL),(10760,'大学新生','Sydney White','雪梨（阿曼达•拜恩斯 Amanda Bynes 饰）的妈妈在她很小的时候就去世了，为了寻找妈妈曾经的足迹，今年她进入了妈妈当年的大学——南太平洋大学。新生雪梨刚一入学就申请加入本校的姐妹会，可惜不久她就发现姐妹会里全是些金发碧眼的富家女，一个叫雷切尔（萨拉•帕克斯顿 Sara Paxton 饰）的女生掌管着这里的大权。雷切尔的嫉妒心极强，当她得知自己的男友对这位清纯的新生心怀好感时，就坚决排斥她。无奈之下雪梨只好搬出了姐妹会的宿舍来到了普通宿舍。\r 　　雪梨在这里遇到了7名同样遭到排斥的稀奇古怪的男生，他们很快就打成了一片。雪梨决定联合8人之力向雷切尔控制的专横的学生会挑战，她要竞选下一任学生会主席！这个出人意料的想法最后能否获得成功？','Freshman year is no fairytale',16500000,13620075,10.74648,6,236,108,'2007-09-21','en','/ce3NNmhVZY5NkUe5Y8Je8CciKqf.jpg',3.037436947536115,3,'2026-09-10',2,NULL,NULL),(10761,'新郎不是我','Made of Honor','似乎得到上帝的垂青一般，汤姆·贝利（帕特里克·德姆西 Patrick Dempsey 饰）拥有令人欣羡的人生。他英俊潇洒，事业有成，生活优渥，身旁美女如云，终日游走在花丛中，并且有着一个交往长达10年之久的红颜知己汉娜（米歇尔·莫娜汉 Michelle Monaghan 饰）。对汤姆来说，汉娜是一个无关肉欲且不可或缺的必要存在，他似乎尤其享受这样诚挚的精神交流。  　　某天，汉娜前往苏格兰公干。在接下来的几个月里，汤姆保守孤独折磨，他意识到汉娜对自己的重要性，于是决定等她回来向其求婚。然而，汉娜在苏格兰期间邂逅了一位富有的男人，并决定婚礼当天请汤姆担任伴郎。面对这样的局面，汤姆该如何是好……','He\'ll do anything to get the groom out of the picture.',40000000,84601681,19.574774,6,394,101,'2008-05-02','en','/5h3vLXuQ579I9LLtersGGa4SsRo.jpg',3.1649351409265907,3,'2026-09-10',2,NULL,NULL),(10762,'寻宝假期','Without a Paddle','俄勒冈的汤姆、杰瑞、丹 和比利是四个从小玩到大，喜好冒险和刺激的朋友，二十岁那年，比利出门远行告别了三人。十年以后，比利在旅行中因事故身亡，三个老伙计再度在葬礼上重逢，三十而立的的三人生活各有烦恼，他们回到童年时的树屋，发现了比利留给他们的“藏宝图”，比利美妙的旅行经历吸引着他们，三人决定马上按图出行，完成童年的梦。一路上，三人遇见了视丹为自己孩子的巨熊、在山谷中种植囤积大量大麻的暴徒二人组，还有自诩为自然人的两个美丽姑娘。一路上的冒险经历，使三人对人生有了全新的认识……','The call of the wild, the thrill of adventure. The mistake of a lifetime.',19000000,69631118,8.584398,5.3,214,95,'2004-08-20','en','/bSQBfHDzyfzxrCLepjegVb5F8j8.jpg',2.9642537995263645,3,'2026-09-10',2,NULL,NULL),(10764,'007：大破量子危机','Quantum of Solace','紧接前一集《皇家赌场》的剧情，由于爱人维斯帕的背叛，邦德（丹尼尔·克雷格 Daniel Craig 饰）的怒火被彻底激发，甚至在执行最新任务时都不得不尽量克制个人感情，以免把这次任务升级为个人恩怨。通过与M（朱迪·丹奇 Judi Dench 饰）对白先生（加斯帕·克里斯滕森 Jesper Christensen 饰）的审问，得知维斯帕是被一个难以想象的犯罪组织所要挟。为了能查清楚这个组织的情况，邦德根据手上的线索顺藤摸瓜，最终把目标锁定在了一个名叫格林（马修·阿马立克 Mathieu Amalric 饰）的商人身上。经过不断的调查，最终发现了这个犯罪组织的惊天阴谋——想要控制全球的自然资源。在随时可能遭遇背叛、谋杀和骗局的情况下，邦德再次出击，最终成功挫败了这个惊天阴谋。','For love, for hate, for justice, for revenge.',200000000,586090727,107.928811,6.1,2965,106,'2008-10-30','en','/e3DXXLJHGqMx9yYpXsql1XNljmM.jpg',3.8133621905697836,3,'2026-09-10',2,NULL,NULL),(10765,'小迷糊当大兵','Private Benjamin','戈尔迪．霍恩自制自演的军教喜剧片，把八十年代初期崛起的新女性意识透过娱乐性的包装来表达。她在片中饰演一名三十出头的美国新女性，因为接连两次婚姻失败，不想再依赖男人生活下去，乃毅然离开自己舒适的家庭，跑去当兵吃苦。当她逐渐适应了军营的生活之后，又有机会坠入爱河，但是在结婚前一刻，她发现未来丈夫其实并不理想，于是决定逃婚，再次投入军人的生活。导演霍华德．齐耶夫将女主角接受军训的过程拍得十分有趣，戈尔迪．霍恩也演得卖力，她在后半段再度谈恋爱以及考虑是否要再结婚的戏有意外的感人效果，对女性心态的刻画有细腻动人的笔触。戈尔迪．霍恩也表现了很高的演技。',NULL,0,0,12.18838,6,102,109,'1980-10-06','en','/maIiPNXddZXKHQCi0HyULd5kces.jpg',2.8638922373978866,3,'2026-09-10',2,NULL,NULL),(10771,'神奇燕尾服','The Tuxedo','出租车司机吉米·唐（成龙 饰）是个在自己心仪女子面前缺乏自信的家伙，所经反复排练但还是会在上阵时手足无措。飚出租车是他唯一所长，拥有因超速被九次吊扣执照的光荣记录，也因这一点被富翁戴弗林（Jason Isaacs 饰）的助手选中，担任戴弗林的司机。  　　戴弗林的另一身份是情报局局长，此时正全力调查一宗饮用水公司的商业阴谋。唐被戴弗林优雅的举动深深折服，两人合作融洽，不料一日两人遭滑板炸弹袭击，戴弗林重伤，昏迷前将家中严禁触碰的燕尾服交予唐使用，并留下“沃特史崔达”的莫名词句。  　　唐无奈之下只得扮演戴弗林的角色，接受安全部门的指令，但他很快发现那件燕尾服不同寻常！用腕表调控相关模式便可以让着衣者拥有超人般的身手。唐要仰仗这件高科技战衣与美丽的菜鸟探员黛儿·布兰妮（Jennifer Love Hewitt 饰）合作，用他们的乌龙方式查清班尼公司的真相……','Suit up for action!',0,0,21.549232,5.3,483,98,'2002-09-27','en','/cvjwZHeEkMbLH4s333AgVToJxGD.jpg',3.1282311704526053,3,'2026-09-10',2,NULL,NULL),(10773,'亨德逊夫人敬献','Mrs. Henderson Presents','丈夫死后，劳拉一直郁郁寡欢，周围的朋友们都劝她找一点自己感兴趣的事情来分散注意力，没想到感兴趣的事情对于劳拉来说竟然是买下一间倒闭的剧院。对经营剧院一窍不通的劳拉找来了专业人士范达姆，两个老人强硬的性格导致了许多的争吵却也给他们的生活带来了一丝生机。劳拉将剧院取名为“温德米尔剧院”，他们的经营获得了巨大的成功。但好运并不总是伴随在身边，很快，竞争对手们纷纷效仿劳拉的做法，温德米尔剧院的生意一落千丈。为了挽回局势，劳拉做出了一个大胆的决定——在剧院中表演脱衣舞。这一决定犹如巨石投入大海，激起了无数浪花，但劳拉坚定的意志竟然让这个几乎不可能通过审核的表演项目获得了批准。但就在观众们拭目以待的节骨眼上，战争爆发了。',NULL,0,0,2.894154,6.4,62,103,'2005-09-09','en','/rFmx0ajncGacM8Ono9vpXiHt7Vy.jpg',2.7468262387872544,3,'2026-09-10',2,NULL,NULL),(10774,'电视台风云','Network','这部由西德尼·吕美特执导、帕迪·查耶夫斯基执笔犀利剧本的媒体讽刺剧，犹如一剂X光，透视了企业主导下美国的腐朽灵魂，其对今日煽动性新闻循环的预见力惊人。在一家挣扎求存的电视网里，野心勃勃的高管戴安娜·克里斯滕森（费·唐纳薇 饰）偶然发现爆款——当心怀不满的新闻主播霍华德·比尔（彼得·芬奇 饰）脱离讲稿，变身愤怒的“狂人先知”，痛斥现代社会弊病。然而，她能否控制住他们在电波中掀起的这场民粹风暴？这部毫无保留的新好莱坞经典作品斩获四项奥斯卡奖（包括唐纳薇、芬奇与查耶夫斯基所获奖项），至今仍保持着无畏的幽默感与令人不安的现实意义。','Not since the dawn of time has America experienced a man like Howard Beale!',3800000,23689877,17.234745,7.7,381,121,'1976-11-01','en','/6sdp26CULZ1Z8UhdqROqrAqpoev.jpg',3.3277240200756846,3,'2026-09-10',2,NULL,NULL),(10776,'异形奇花','Little Shop of Horrors','当呆头呆脑的西摩·克雷尔伯恩发现一株非常奇特的植物后，他工作的花店生意开始好转。当这株植物的健康受到威胁时，西摩绝望地发现了让它存活的血腥秘密。随着西摩日渐贫血，手指上缠绕的绷带越来越多，植物却茁壮成长，生意蒸蒸日上，西摩也赢得了女孩的芳心。但随着植物越长越大，它对所渴求的滋养生命液体的需求也与日俱增，西摩必须寻找其他、更大的喂养来源……比如隔壁那位残忍的牙医。','Don\'t feed the plants.',25000000,38748395,12.113235,6.6,384,94,'1986-12-19','en','/5AOe3tDXUcBZ4Ht0hYggpldkdgC.jpg',3.2046546416846238,3,'2026-09-10',2,NULL,NULL),(10781,'德州电锯杀人狂前传','The Texas Chainsaw Massacre: The Beginning','在德州某屠宰场，肥胖的女工正在案板切肉，突然感到腹中剧痛，原来身怀有孕的她羊水已破，产下一个畸形儿，遗弃在垃圾箱，后来被清洁工救起。N年后，一群年轻人驾车路过这里。刚从越南前线归来的艾瑞克（马修•波莫 Matthew Bomer 饰）刚与未婚妻克莉希（乔丹娜•布鲁斯特 Jordana Brewster 饰）团聚，就得知弟弟迪恩（泰勒•汉德雷 Taylor Handley 饰）又要去前线，他本想陪弟弟共赴沙场。但迪安在女友贝莉（迪奥拉•拜尔德 Diora Baird 饰）的劝说下准备将入伍证烧掉，他们为此产生了争执。这时，他们遭到了飙车党挑衅。后来，为首的女孩竟然被警察击毙。警察霍伊特（R•李•艾尔米 R. Lee Ermey 饰）拦住了他们的车子，把他们带到了令人毛骨悚然的屠宰场，开始了惨无人道的折磨……','What you know about fear... doesn\'t even come close.',16000000,0,21.380635,5.9,402,91,'2006-10-06','en','/cCbkpC1txjOdXdGAIApynwrJBC6.jpg',3.1625904001913216,3,'2026-09-10',2,NULL,NULL),(10782,'基地疑云','Basic','这世界上有两种事实，一种是我们所看到的事实，一种是背后隐藏的真正的事实。我们看到的往往是那些像是现实的假象，而另外一个我们看不到的才是真正的答案。 　　在巴拿马丛林的美军训练基地里，发生了一起神秘的失踪事件。6名受训学员出发进行常规的军事训练，却连同教官韦斯特(塞缪尔·杰克逊饰)在飓风后消失得无影无踪。韦斯特素以严厉著称，和学员之间的关系一向十分紧张。仅存的两名幸存者却保持缄默，不愿与官方合作。整个调查陷入了僵局。 　　无奈之下，基地指挥官只好请来昔日的学员哈代(约翰·特拉沃尔塔饰)，现在的美国药品管理局官员协助调查。但是军方调查官员朱丽娅少尉(康妮·尼尔森饰)却并不欢迎他的到来。因为其一，哈代被怀疑与其当地毒品贩子有非法交易；其二，哈代也曾是号称魔鬼教官韦斯特的门下弟子，并且和其他的受训者一样对他心存怨恨。 　　随着调查的展开，哈代与朱丽娅为了整体利益，决定暂时封存彼此的不信任。哈代更使用非常手段从幸免的学员丹巴口中套出惊人“事实”：韦斯特和其他失踪学员是被人谋杀，并且尸首已经被飓风吹走。但另外一个学员肯达尔的供词却与丹巴的大相径庭。 　　究竟是谁在说谎，或者两人的说法都是谎言？究竟在这个神秘的丛林里发生了怎样的故事？随着调查的继续，更多的谎言，更多的欺骗浮出水面，而一个可怕的事实，也在逐渐向哈代他们靠近……','Deception is their most deadly weapon.',50000000,42792561,19.226763,6.2,286,98,'2003-04-18','en','/jtyF4NF9fQlyGP8cgU1mK3DLUTB.jpg',3.1140326184662093,3,'2026-09-10',2,NULL,NULL),(10783,'内神外鬼','Lucky Numbers','罗斯（约翰·特拉沃尔塔 John Travolta 饰）是宾夕法尼亚电视台的一名天气预报员，爱慕虚荣的他贷款购置了豪宅与豪车，虽然过着人人羡慕的生活，但实际上，他在背地里背负着巨额的债务。罗斯还债的全部希望都寄托在雪车的销售商，哪知道天不遂人愿，暖冬的来临让雪车根本就没有任何的销路，眼看着每个月的账单像雪片一样的纷纷而来，罗斯只得求助于歪门邪道。\r 　　在脱衣舞夜总会老板吉吉（蒂姆·罗斯 Tim Roth 饰）的怂恿下，罗斯找到了主持乐透开奖的克里斯特（莉莎·库卓 Lisa Kudrow 饰），几人联手在乐透球上做了手脚。果不其然，罗斯中了乐透大奖，但与此同时，危险也在逼近。','When they put their heads together... it\'s a no brainer.',65000000,0,2.952595,4.9,52,105,'2000-10-27','en','/glmBnEtrmtMypPyg8DiwPZja3Vj.jpg',2.6784258432277652,3,'2026-09-10',2,NULL,NULL),(10786,'Robin and Marian','Robin and Marian','Whatever became of Robin Hood after his famed tale of good deeds ended? Now you can find out, in this sequel that takes place years after Robin and his merry men bested the Sheriff of Nottingham. After following Richard the Lionhearted to the crusades, Robin (Sean Connery) returns to Sherwood Forest to find things drastically changed. Audrey Hepburn plays the stalwart Marian … who\'s joined a nunnery!','Love is the greatest adventure of all.',0,0,3.199904,6.6,50,106,'1976-03-11','en','/y2UlVt6U8mFeegVL42rZjD5y6c7.jpg',2.704268507323834,3,'2026-09-10',2,NULL,NULL),(10796,'宇宙追缉令','The One','有一个这样的理论：宇宙中存在多个平行世界，而且每个平行世界里都有一个你存在，而且所有平行世界里面的自己会分摊整个宇宙中你所具备的能量。所以，只要平行世界中的你都消失了，那所有的能量将汇聚到最后的一个人身上。正是为了这个目的，夺取所有人的能量，在遥远的未来，名叫基比（李连杰 饰）的杀手穿越时空杀掉了123个平行世界中的自己，获得了超能力。而这时，世界中只剩下自己和另外一个平行世界中名叫盖伯瑞（李连杰 饰）的自己。而身处和平世界中的盖伯瑞，完全没有意识到大难临头。只是在突然的一天，发现自己速度极快、力大无穷，而且有一个和他一模一样的人在到处犯罪，作为警察的自己，必须挺身而出，阻止犯罪的同时也为了拯救自己','Stealing the power of the universes one by one.',49000000,72700000,21.746245,5.7,437,87,'2001-11-02','en','/1UotaEtDpiCvjHbZiHvC7p29U2A.jpg',3.157777614143479,3,'2026-09-10',2,NULL,NULL),(10800,'龙战','Chasseurs de dragons','佐埃是一个相信传奇故事的小女孩，这并不是因为她天真幼稚，而是因为她喜欢传奇故事。为了帮助她的叔叔亚瑟大人摆脱可怕的龙，佐埃踏上了寻找英雄之路。她没找到英雄，却碰到了格威兹多和连秋，两个临时凑数的猎龙人，结果佐埃决定还是相信他们！','Dragon hunting isn\'t a fairy tale',15000000,0,8.884405,6.5,129,80,'2008-03-19','fr','/56aN8gqgd0uaF79MS6hT1NeEPhn.jpg',2.9285326766715887,3,'2026-09-10',2,NULL,NULL),(10802,'艳舞女郎','Showgirls','诺密（伊丽莎白·伯克利 Elizabeth Berkley 饰）是一名性感漂亮的女郎，年轻的她来到拉斯维加斯淘金，希望在这里能找到令她立足的工作。没想到，刚到此地，便被小混混骗走了行李，身无分文的她遇见了化妆师克里斯特（吉娜·格申 Gina Gershon 饰），两人一见如故结下了深厚的友谊。诺密发现，想在拉斯维加斯得到一个饭碗实在是太难了，热爱舞蹈的她最后决定加入当地最有名的艳舞团队。经过层层选拔，诺密得到了她的角色，而一旦开始涉入这个复杂的声色世界中，她沦陷的速度就再也不会停止。本来自尊自重的诺密，居然也开始为了向上发展而出卖自己的肉体。诺密越来越有名，但她和克里斯特的距离也越来越远。为了弥补这段友情，诺密安排了克里斯特和她的偶像歌手见面，没想到看似偶像实则禽兽，克里斯特惨遭凌辱住进医院，也击碎了诺密关于名声和金钱的最后的幻觉','Beyond your wildest dreams. Beyond your wildest fantasies.',45000000,20350754,14.513305,4.9,256,128,'1995-09-22','en','/r7URmY57yVKSvca7Pmp1W5kULK1.jpg',2.977298995999227,3,'2026-09-10',2,NULL,NULL),(10803,'逃离地下天堂','Logan\'s Run','公元2274年人类居住在由电脑控制的城市中，在这个城市中无优无虑，可自由毫无拘束的追求享乐；但到30岁时每一个人必须接受考验，一个探究生命永恒于重生的试炼……','The only thing you can\'t have in Logan\'s world is your 30th birthday. Unless you run away.',9000000,25000000,12.268143,6.6,269,119,'1976-06-23','en','/yTtpLizbGUTknIFRC2N7FkAdk7X.jpg',3.1169209886902673,3,'2026-09-10',2,NULL,NULL),(10806,'新郎向后跑','In & Out','霍华德（凯文·克莱恩 Kevin Kline 饰）是一名在高中里任教的老师，一辈子勤勤恳恳的教书育人，获得了朋友和学生们的尊重。霍华德和女友艾米丽（琼·库萨克 Joan Cusack 饰）的爱情长跑终于要开花结果了，再过不久，他们就将携手步入婚姻的殿堂，许下相守一生的诺言。  　　一天，霍华德在艾米丽家，和他的未婚妻一起观看奥斯卡颁奖典礼，让他感到不可思议的是，影帝的殊荣竟然颁发给了他曾经的学生。深感自豪之余，这位新晋影帝的一番获奖感言却将霍华德打落谷底，在成千上万的观众面前，霍华德竟然“被出柜”了。果不其然，艾米丽大怒，霍华德跳进黄河也洗不清冤屈。','An out-and-out comedy.',35000000,0,11.897925,6.3,177,90,'1997-09-10','en','/jUTQp6cPgfOX4St2WfaeUvxZCts.jpg',2.997159409510849,3,'2026-09-10',2,NULL,NULL),(10808,'怪医杜立德2','Dr. Dolittle 2','怪医杜立德又回来了。在本集故事中，埃迪·墨菲（Eddie Murphy）作为一个能与动物交流的医生再次出现。名声在外的杜立德的病人是越来越多了——不仅有2条腿的人，也有4条腿的动物，多得都应付不过来了。但是，他的动物朋友们可不仅仅是来看病的，他们要从那些可恶的滥砍滥伐者手里拯救它们赖以生存的森林，它们希望杜立德医生能伸出援手。杜立德制订了一个拯救森林的计划：找一只濒临绝种又受法律保护的动物。他发现了一只生活在这片即将被砍伐掉的森林中的西太平洋熊——孤独的爱娃（Ava）。如果爱娃找到一个配偶，森林就可得以保留。杜立德立刻在马戏团里弄了头聪明伶俐，喜欢吃快餐，习惯了都市生活的熊——阿尔奇（Archie），杜立德觉得它俩蛮般配的。一开始，已被驯化的阿尔奇对此事并不感兴趣，但杜立德则设法让它相信在森林中，有一段美好的恋情正在等待着它。于是，杜立德和他的狗“来福”（Lucky）带着阿尔奇前往森林，并教会它野外生存之道。极为不幸的是，这两头熊实在不怎么相配。爱娃对阿尔奇的口齿不清和滑稽动作十分反感，另一方面阿尔奇也丧失了动物的野性和繁殖能力，两者之间根本无法产生感情……','The doctor is in again.',70000000,176104344,13.543053,4.9,410,87,'2001-06-22','en','/asYjHXBoD44B6mLOcZtMfMV3hm1.jpg',3.0406238898055005,3,'2026-09-10',2,NULL,NULL),(10822,'欲孽迷宫','Savage Grace','芭芭拉•戴利•贝兰克（朱丽安•摩尔 饰）美艳动人，她的丈夫布鲁克林（史蒂芬·迪兰 饰）是一名探险家。虽然丈夫腰缠万贯，让芭芭拉的生活富足，但她的生活并没有想象中幸福，因为丈夫到处探险的关系，她常常得不到丈夫的陪伴，因而变得让人感觉十分水性杨花。儿子托尼（艾迪•雷德梅纳 饰）成为了她的一切，并常常牵制儿子做事。  　　芭芭拉知道托尼是名同性恋，并极力撮合他与西班牙女友的爱情，可是托尼最后并没有跟那名女孩在一起。布鲁克林却跟儿子的女友私奔了，这样令芭芭拉感到十分伤心。托尼也十分不舍得父亲的离开，他也目睹了母亲自父亲离开后的痛苦。之后他们四处为家，一直患病的芭芭拉还曾自杀过。  　　芭芭拉多年来一直没有放弃要让儿子变回异性恋，她竟然要与儿子发生关系，以让儿子尝试性爱的味道。终于，托尼再也无法忍受母亲了，一把尖刀刺向了芭芭拉…','Truth is more shocking than fiction.',4600000,0,3.531877,5.7,60,97,'2007-05-18','en','/rtJp4ulwC1SvSYAUFGUa1pWV7nk.jpg',2.725094895002293,3,'2026-09-10',2,NULL,NULL),(10833,'偷心俏佳人','Heartbreakers','长久以来，安琪拉（西格妮·韦弗 Sigourney Weaver 饰）和佩吉（詹妮弗·洛芙·休伊特 Jennifer Love Hewitt 饰）都保持着天衣无缝的合作关系，不仅仅是作为母女，同时也作为工作伙伴。而她们的工作非常简单——结识黄金王老五，再通过小小的手段骗取巨额分手费。然而，常在河边走，哪有不湿鞋，春风得意的母女二人不知道的是，她们即将迎来情感和事业上的双重危机。  　　威廉（吉恩·哈克曼 Gene Hackman 饰）是安琪拉物色的最新猎物，与此同时，佩吉却不可救药的和酒吧老板杰克（杰森·李 Jason Lee 饰）坠入了爱河。安琪拉一边为不再像曾经那样听话的女儿所烦恼，一边绝望的发现，自己似乎也陷入了威廉的温柔乡里无法自拔。','Caution: Dangerous Curves Ahead',35000000,0,13.932203,5.7,254,123,'2001-03-23','en','/bw1aD5LVddxzHz5gvTxe3mSJevj.jpg',3.0368733621810633,3,'2026-09-10',2,NULL,NULL),(10844,'Out of the Blue','Out of the Blue','Ordinary people find extraordinary courage in the face of madness. On 13–14 November 1990 that madness came to Aramoana, a small New Zealand seaside town, in the form of a lone gunman with a high-powered semi-automatic rifle. As he stalked his victims the terrified and confused residents were trapped for 24 hours while a handful of under-resourced and under-armed local policemen risked their lives trying to find him and save the survivors. Based on true events.','The true story of a small town massacre',0,0,0.706355,5.9,18,103,'2006-10-12','en','/ngaAaP0DOxv1QDXVfy085yOpUkA.jpg',2.473234541796224,3,'2026-09-10',2,NULL,NULL),(10858,'尼克松','Nixon','影片试图从客观的立场出发探讨因水门丑闻而下台的美国总统理查德·米尔豪斯·尼克松的政治生涯。虽然也涉及到他的童年和早期从政的经历，但重点是在水门事件。当影片中一个女学生当面问总统：“为什么你作为总统制止不了越南战争？是不是因为这个制度？”尼克松似有所悟，他对手下人说：“她懂得我花了二十五年时间搞政治才懂得的事情……”','Triumphant in Victory, Bitter in Defeat. He Changed the World, But Lost a Nation.',44000000,13681765,3.770161,7.1,71,192,'1995-12-22','en','/cz2MTGr2wpDZLirgV2rGHBdA2t3.jpg',2.797368468545698,3,'2026-09-10',2,NULL,NULL),(10861,'极度冒险','Maximum Risk','法国南部某城市，一男子在街巷间躲避一群壮汉的追逐，抢夺了一辆摩托小货车的男子慌不择路，与一辆轿车相撞后身死……经手此案的警员索伯斯坦（Jean-Hugues Anglade 饰）找到自己昔日战友阿雷·莫洛（尚格·云顿 Jean-Claude Van Damme 饰），因为后者的长相和死去的男子一模一样，死者有一个俄国名字米哈伊·苏洛瓦夫。莫洛得知自己本有一名双胞胎弟弟，后被贫病中的母亲送给某律师找人收养。  　　莫洛与搭档奔赴法国，却发现律师本人刚被枪杀，莫洛决定沿着米哈伊遗留下来的护照跟机票，前往纽约调查。莫洛在一位出租车司机的帮助下，找到了关键字“波西米亚”的含义——一家和美国俄裔黑帮联系密切的夜总会，而“亚历克斯”则是指夜总会内的一名艳丽女郎（Natasha Henstridge 饰），由此开始，莫洛逐渐进入到美国俄裔黑帮的世界中去……','The Other Side of Safety.',25000000,51702483,10.115011,5.2,101,100,'1996-09-13','en','/pR0V9v1Jr8KSVdHnRotG3TP4xKE.jpg',2.827848578922923,3,'2026-09-10',2,NULL,NULL),(10865,'亚特兰蒂斯：失落的帝国','Atlantis: The Lost Empire','希腊哲学家柏拉图曾经在公元前360年两度在他的著作【对话录】提及亚特兰提斯这个文明——“在一个分不清楚昼夜的晚上，亚特兰提斯沉入了深海。”  　　1914年华盛顿的市立博物馆里，年轻的男主角迈罗是一位语言学家，对于亚特兰提斯的传说深信不已。迈罗希望自己能像祖父一样成为一位伟大的探险家。在得不到博物馆的资金赞助下，突然出现一位祖父生前怪怪的好友愿意提供迈罗资金，让他去探索亚特兰提斯存在的真假。  　　迈罗领着专家组成最顶尖的探险队，出发前往深海寻找亚特兰提斯城。万万没想到，亚特兰提斯人居然仍然生活在地底的世界里。在亚特兰提斯的国度里，迈罗与探险队见到了亚特兰提斯二万岁高龄的国王以及八千五百岁的姬妲公主，他们对亚特兰提斯文明的未来感到忧虑，公主希望探险队可以帮助她的王国重新找回动力。不料整支探险队伍除了迈罗之外全都心怀不轨，他们全是为了金钱财富而来。  　　探险队准备将公主绑架走，而姬妲公主是亚特兰提斯城生命的源头。此时迈罗必须依靠一己之力在亚特兰提斯人民的帮助下将公主救回。','Atlantis is waiting...',120000000,186053725,51.548589,6.7,1224,95,'2001-06-02','en','/lnz17N1niXhf5pWMhq2UMpHaLne.jpg',3.6060703046246734,3,'2026-09-10',2,NULL,NULL),(10866,'致命玩笑','Joy Ride','暑假来临，大学新生刘易斯·托马斯（保罗·沃克尔 Paul Walker 饰）决定穿州过省，前往新泽西去看望他自高中时代便喜欢的女孩维娜·威尔柯斯（Leelee Sobieski 饰）。为了打发旅途上的无聊时光，他将正因酒后驾车蹲局子的老哥富勒（史蒂夫·赞恩 Steve Zahn 饰）保释出来，兄弟俩一路通行。\r 　　旅途中，富勒买了一部车载对讲机，与其他的司机扯皮聊天。期间他们搭上一个绰号“锈钉”的卡车司机，富勒突发奇想，怂恿弟弟假扮女人用对讲机勾引锈钉。对他们来说，这似乎是旅途中一个无伤大雅、转眼就忘的玩笑。没想到他们却惹上了这个难缠和恐怖的家伙。在接下来的时间里，锈钉成为刘易斯、富勒和维娜难以摆脱的噩梦…… ©豆瓣','It was just a joke, just for fun.',23000000,36642838,11.183197,6.3,325,97,'2001-10-05','en','/ojp2dts5QNoOvGtTwmfN32UTbZi.jpg',3.133279834837615,3,'2026-09-10',2,NULL,NULL),(10871,'极速杀机','Switchback','弗兰克（丹尼斯·奎德 Dennis Quaid 饰）是一位经验丰富精明强干的FBI探员，长久以来，他都在追捕一名高智商连环杀人魔。最近，情况变得十分糟糕，因为弗兰克发现这位凶残冷酷的杀手就潜伏在自己所负责的辖区内，并且已经犯下了数起案件。\r 　　之后，弗兰克绝望的得知，这位神秘杀手竟然将下一个加害目标放在了自己的儿子身上，也正因为如此，当局撤销了弗兰克在此案件中的权限，因为他再也不能冷静的对待这名凶手了。然而，爱子心切的弗兰克并没有就此罢休，他决定靠自己的力量将凶手捉拿归案，也就是在此过程中，弗兰克一步一步地踏入了凶手布下的天罗地网之中。','The hunter becomes the hunted.',37000000,6482195,4.131546,5.8,52,118,'1997-10-31','en','/3v4nX475G97Vd8XCapTKQ7NTqMs.jpg',2.6991088730053323,3,'2026-09-10',2,NULL,NULL),(10873,'吸血鬼魅影','Shadow of the Vampire','导演 F.W. Murnau 与一个吸血鬼签订了浮士德契约，让他出演自己 1922 年拍摄的电影《诺斯费拉图》。','An Unspeakable Horror. A Creative Genius. Captured For Eternity.',8000000,8279017,5.93923,6.6,148,92,'2000-05-15','en','/3MvxtgpQTY4XvOQ5SwoQU0DPI1Z.jpg',2.9586331914122606,3,'2026-09-10',2,NULL,NULL),(10876,'鹅毛笔','Quills','萨德（乔弗瑞•拉什Geoffrey Rush饰）是19世纪的法国作家。他才高八斗，崇尚言论自由，小说中有不少情色描写。这些作品激怒了法国当局，政府把他关入疯人院，然而，专制的枷锁只令到萨德更坚定地奋笔疾书，作品在疯人院里一部一部的诞生。 疯人院的主管是一个开明的年轻神父。他也读萨德的小说，对萨德的才华和精神充满欣赏。他对萨德提供优厚的生活条件，让他专心写作，同时让洗衣女梅德林（凯特•温斯莱特Kate Winslet饰）帮助萨德，把他的作品带到外面出版。梅德林与萨德之间也暗生情愫。 然而，强大的国家机器还是将萨德送上了绞刑架。政府容忍不了他“伤风败俗”，但他的作品却流传了下来，开启了民众的思想。','There are no bad words... only bad deeds.',13500000,7060876,7.261196,6.8,128,124,'2000-11-22','en','/AvGdw3BpvJV2wHmK2qY0N7XHqET.jpg',2.936484023861332,3,'2026-09-10',2,NULL,NULL),(10877,'以毒攻毒','Exit Wounds','警察欧林（史蒂文•席格 Steven Seagal 饰）刚刚调来到这个底特律犯罪最猖獗地区的警局，局里就发生了一件惊天大案！原本所在警局保险柜内的赃物50公斤海洛因不翼而飞了，由于这批毒品价值连城，局里的每一名警员都有作案嫌疑。  　　作风硬朗的欧林开负责调查这起毒品失窃案，但调查进行得异常艰辛。每天，当欧林回到局里，似乎一双双敌对的眼睛就监视着他。欧林找到了街头混混沃克（DMX 饰）协助他调查这起案件，沃克认为警局内的每个人都有份参与这起盗窃案，包括欧林也不例外。解开迷案的关键就在沃克身上！','This Is Gonna Hurt',50000000,79958599,12.601306,5.3,110,101,'2001-03-13','en','/tGIJhBejmredgUZRNdteZyiahag.jpg',2.8532440889462376,3,'2026-09-10',2,NULL,NULL),(10878,'抢救疑情大兵','Saving Silverman','一对好友密谋救他们最好的朋友免于娶错女人，一个冷酷的美女从他们身边抢走了他，并拆散了他们的尼尔·戴蒙德翻唱乐队。','They swore nothing would come between them. Then evil walked in the door',22000000,19351569,12.887673,5.4,154,90,'2001-02-09','en','/5mq8J11266ZL7HCOwDGXoaU6eIO.jpg',2.9210773375497086,3,'2026-09-10',2,NULL,NULL),(10885,'鬼影','Shutter','美国摄影师本杰明•肖（Joshua Jackson 饰）因工作原因携新婚妻子简（Rachael Taylor 饰）飞往日本。夜晚，他们驱车行驶在一条荒无人烟的小路上。突然，一个女子（Megumi Okina 饰）出现在他们的面前，汽车无情撞上该女子。当他们清醒过来时，却未发现那名女子的尸体。本杰明认为女子已经接受治疗或纯粹是幻觉所至，遂匆匆离开此地。  　　不久，本杰明发现自己的照片中经常浮现奇怪的光影，而简也不断为被撞女子的鬼影所困扰。恐怖事件变本加厉，夫妻俩的好友接连死去，随着事态的恶化，他们也逐渐知晓造成这一切的原因……','The most terrifying images are the ones that are real.',0,0,8.864368,5.3,180,85,'2008-03-21','en','/4O47bjo4m9oPZUtwES0GcqrI3MV.jpg',2.9345656243554306,3,'2026-09-10',2,NULL,NULL),(10890,'杂牌军东征','Stripes','屋漏偏遭连夜雨的约翰·温格（比尔·默瑞 Bill Murray 饰）不仅惨遭解雇，他的女友此刻也离他而去。前路渺茫的约翰在一时冲动下，说服了好友罗塞尔（哈罗德·雷米斯 Harold Ramis 饰）一起报名参了军。他们把军营想象成重塑自我的理想之地，却不曾料想到训练他们的是一个顽固又没有耐心的中士胡卡（沃伦·奥茨 Warren Oates 饰），队友更是各个平庸无能，常常做出很多让人啼笑皆非的囧事。两人为了追求漂亮性感的女宪兵斯泰拉（PJ·索尔丝 P.J. Soles 饰）和路易丝（肖恩·杨 Sean Young 饰），竟抢夺了一辆高科技军用车，意外的进入了苏联境内并卷入了一场国际事件。','The story of a man who wanted to keep the world safe for democracy...and meet girls.',10000000,85300000,10.892398,6.5,249,106,'1981-06-25','en','/toyyN62VLUXoUudFbHPdrrmRFSZ.jpg',3.0872391612626515,3,'2026-09-10',2,NULL,NULL),(10894,'五月魔女','May','五月（安吉拉·贝蒂斯 Angela Bettis 饰）是一个个性孤僻喜欢独处的女孩，但除此之外，她和其他的女孩并没有什么不同。目前，五月在一家兽医诊所里担任助手的职务，这卑微的工作让她觉得颜面无光。其实在内心里，五月十分希望能够邂逅一场甜蜜的爱情，可是这样的机会迟迟没有 到来。\r 　　小镇上来了一个机修工，他英俊帅气的外表很快就吸引了五月的目光，她梦寐以求的浪漫遭遇眼看着就快要展开。没想到，致命的打击随之而来，机修工以五月的行为举止过于怪异为由拒绝了五月的试好，在绝望中，五月的内心里燃气了复仇的火焰，她要报复那些自以为是的男人们，将他们折磨，杀死，然后做成人偶，这样他们就可以永远的陪伴在她的身边了。','Be Careful... She Just Might Take Your Heart.',500000,150277,8.650779,6.3,152,93,'2002-01-13','en','/oFXhJYTax1cnNtgvLdKlXuYiWPV.jpg',2.9555937508999817,3,'2026-09-10',2,NULL,NULL),(10895,'木偶奇遇记','Pinocchio','一个活生生的木偶，在蟋蟀的良心帮助下，必须证明自己有资格成为一个真正的男孩。','For anyone who has ever wished upon a star.',2600000,84300000,46.007991,6.9,1355,88,'1940-02-23','en','/mqZDB5yLTkdCJky8iuz2q59VzjY.jpg',3.658632315512802,3,'2026-09-10',2,NULL,NULL),(10913,'亲爱的温迪','Dear Wendy','孤独内向的男孩迪克（Jamie Bell 饰）生活在一个偏远闭塞的矿业小镇上，他的生活有如一潭死水，直到某天，一把手枪改变了这一切。迪克为手枪完美的设计及其散发出的暴力气息所吸引，他深深为之着迷，并给爱枪起名“温迪”。不久，迪克结识了一班喜欢枪的同好，他们组织了名为“性手枪”的俱乐部，谈枪比枪，生活其乐无穷。黑人男孩塞巴斯蒂安（Danso Gordon 饰）的加入令事态发生转变……\r 　　本片剧本由丹麦著名导演拉斯•冯•提尔执笔，荣获2005年莫斯科国际电影节最佳导演奖。','One shot is all it takes.',0,0,2.597665,5.6,33,105,'2005-01-22','en','/2IF19Tcx5D9d8iUWa0PxFhO6MYZ.jpg',2.598790572579001,3,'2026-09-10',2,NULL,NULL),(10914,'智取农场','All Hat','根据著名畅销小说作家Brad Smith的作品改编，这个西部故事紧张刺激。一个前度骗子Ray从监狱释放出来，他回到安大略的家乡，当地一个富有而腐败的纯种赛马饲养场老板. 计划夺取农场，Ray智取之，让他奸计不能得逞……',NULL,0,0,0.137535,1,1,89,'2007-09-11','en','/97BMsVbc6R3sLR6A6GjvWdpukj1.jpg',1.9825088276392853,3,'2026-09-10',2,NULL,NULL),(10923,'少年特工科迪','Agent Cody Banks','15岁的高中生科迪（弗朗基·穆尼兹 Frankie Muniz 饰）平凡得不能再平凡。他和所有年轻人一样，喜欢滑板，讨厌功课，爱出风头，但在喜欢的女孩面前却又结结巴巴。正因为他的平凡，毫不引人注目，所以中情局今次把他招了进来。在接受了一系列特训后，科迪接受了他的生平第一 个任务。\r 　　可是第一次执行任务的科迪就感到万分头痛，因为中情局要求他去追求学校里最受欢迎的美女，也是他的梦中情人――娜塔丽（希拉里·达芙 Hilary Duff 饰），中情局怀疑娜塔丽的科学家父亲正在进行一项疯狂的恐怖计划。可是科迪一见到娜塔丽讲话就结结巴巴，十分困窘害羞。可怜的科迪要怎样才能完成任务？ ©豆瓣','Save the world. Get the girl. Pass math.',28000000,58795814,11.859396,5,284,102,'2003-03-14','en','/fhK0mqqirPsckxkNisvi32A4lf6.jpg',2.994663672487295,3,'2026-09-10',2,NULL,NULL),(10925,'活死人归来','The Return of the Living Dead','佛瑞迪和法兰克发现了僵尸坟场，结果不小心将美军留下的化学毒气外泄，僵尸全部都复活了，一大群在外游荡的不良少年，成了这些从地底爬出的僵尸所攻击的对象，结果美军携带大批尖端武器展开攻击，但是僵尸愈来愈多……','They\'re Back From The Grave and Ready To Party!',4000000,14237000,14.961629,7.3,267,91,'1985-05-15','en','/oNsV9BychAe4Sk6xFKp558Rlpyz.jpg',3.177571802735857,3,'2026-09-10',2,NULL,NULL),(10929,'驭鼠怪人','Willard','维拉德（克利斯丁·格拉夫 Crispin Glover 饰）是一个性格十分内向腼腆的青年。在公司里，他的反应迟钝和笨手笨脚惹出了许多的麻烦，致使他遭到老板和同事们的无情嘲笑排挤，终日生活在压抑和委屈之中。维拉德唯一的两个朋友是本和苏格拉底，它们是两只拥有着高超智商的老鼠。\r 不幸的是，维拉德的同事在偶然之中发现了苏格拉底的存在，苏格拉底被当成普通的老鼠被踩死了。这巨大的悲剧给维拉德和本带来了毁灭性的打击，一人一鼠在绝望之中决定联手向人类复仇，他们率领着终日生活在阴影里的鼠族大军，拉开了一场充满了惨叫和鲜血的，跨越了人类和鼠类两个种族之间的荣誉之战。','When the cat\'s away, the rats will play.',22000000,0,1.322528,5.8,82,100,'2003-03-14','en','/hRVP8Ud9ehv7tp5WWQ4CHk2XNus.jpg',2.7868533682340666,3,'2026-09-10',2,NULL,NULL),(10930,'恶之花','La Fleur du mal','富裕的中产阶级女主人决定竞选市长，男主人从不支持，留学美国多年回来的儿子与异父异母的妹妹（其实算是家族里的表妹）相爱了。 接着一封揭发这个家族三代以来的罪行（前纳粹份子，谋杀父亲，谋杀配偶，乱伦）的告密信件扰乱这养尊处优的家庭。 罪恶如同癌症基因，遗传到每一代成员。 丛林般的客厅，让身处其中的每个人，仿如流着恶露之华美植物。 夏布洛冷静批判中产阶级的镜位，让外在言行世故优雅的人类，现出人性的幽暗内在。',NULL,0,0,1.229667,5.7,10,104,'2003-02-09','fr','/82lerrSCrvjaWm9sAXzrUECKqg7.jpg',2.3556112387689443,3,'2026-09-10',2,NULL,NULL),(10934,'托斯卡纳艳阳下','Under the Tuscan Sun','婚姻失败对于已经三十多岁的女作家法兰西斯来说，是一个很残酷的打击。幸亏朋友体贴窝心，专程安排她到意大利托斯卡尼去旅行一趟。想不到，托斯卡尼这个美丽得令人窒息的城市，竟然改变了法兰西斯的后半生。法兰西斯在托斯卡尼看到了一个郊外别墅的广告。本来并无太多打算，然而接下来的种种巧合却让她和这幢房子接下了不解之缘。于是，这个来自美国的作家毅然决定放弃从前的一切，开始在异国他乡建立自己的新窝。法兰西斯布置自己的新房，大大小小的琐事令她皱眉，各式各样的新人和新事物也令这个新房客应接不暇，新的恋情也在眼前铺开。阳光明净的托斯卡尼，让法兰西斯的内心渐渐丰盈。','Life offers you a thousand chances ... all you have to do is take one.',0,0,12.309718,6.4,172,113,'2003-04-30','en','/uh1G5wztreQ9u54J0RXQcIIDZG2.jpg',2.997392523725078,3,'2026-09-10',2,NULL,NULL),(10935,'天堂之门','Heaven\'s Gate','哈佛大学毕业生詹姆斯·艾弗里尔（James Averill）是怀俄明州繁荣的杰克逊县（Jackson County）的治安官，当时该地区的贫困移民和富裕的养牛农民正在爆发冲突。政治关系密切的牧场主在雇佣兵纳森·坎普（Nathan Champion）的帮助下与移民作战。随着斗争的升级，埃弗里尔和坎普开始质疑他们的决定。','The only thing greater than their passion for America... was their passion for each other.',44000000,3484331,5.380124,6.4,55,219,'1980-11-19','en','/kW4Vk31nhtKPKGuYMaVATq3wcHC.jpg',2.7262184880981475,3,'2026-09-10',2,NULL,NULL),(10944,'裸体切割','In the Cut','弗兰妮是纽约一名大学教师，她孤零零地栖居于曼哈顿一间狭窄凌乱的公寓里，她的生活单调得只剩工作和她的妹妹宝琳娜。她正在为一本研究纽约青年俚语的书搜集资料。在酒吧的盥洗室里弗兰妮无意中发现一对男女正在进行口交，她不声不响地在一旁偷窥，虽然没有看清男人的脸，但这个手腕上带纹身的男人却强烈地激起了她的欲望。不久可怕的事情发生了。在弗兰妮的花园里，竟然找到了一具被肢解的女尸，侦探马龙前来调查，弗兰妮在马龙的手腕上发现了和酒吧洗手间里的男人一样的纹身，心里产生了一股隐隐的不安感，但同时这个冷漠外表下散发着热情的男人具有难以令人抗拒的魅力，他平淡地讲述着案件的残忍细节，随后邀请弗兰妮去喝一杯。仿佛被一股巨大的力量驱使，他们迅速为对方所吸引，卷入激情的漩涡中。疯狂的性爱让弗兰妮令人惊讶地重新焕发活力，她无法自拔地沉醉其中。但一系列相似的女性被害案不断发生，而且每位被杀者都与弗兰妮有着或多或少的联系。种种蛛丝马迹使她怀疑马龙就是那位连环杀手。她甚至开始感到周围的人似乎都逃不了嫌疑。弗兰妮陷入痛苦的矛盾挣扎中，爱欲与惊惧相交织令她身不由己地一点点坠入黑暗深渊……','Everything you know about desire is dead wrong.',12000000,23,10.536092,4.6,89,119,'2003-09-09','en','/34sFVdUugePqzzNhu6XWtqz4XbC.jpg',2.7855633314222663,3,'2026-09-10',2,NULL,NULL),(10947,'歌舞青春','High School Musical','特洛伊（扎克·埃夫隆 饰）和盖布利拉（瓦妮莎·哈金斯 饰）本是分属两个世界的年轻人。特洛伊从小就作为篮球种子来培养，而盖布利拉则是个高智商的学习优秀学生。新年晚会两人被推上舞台，合唱了一首美妙的歌，彼此的内心都燃起了火花。碰巧的是，两人竟成为了高中同班同学。艺术老师打算挑选合适的人选参演一部音乐剧，特洛伊和盖布利拉凭着优美默契的歌声打动了老师。要获得最终的演出资格，他们还得在第二轮面试中打败对手，然而，事情却起了波折。这边篮球队正为了一场重要的比赛而加紧训练，队员纷纷要求特洛伊专心练球；那边学术比赛即将开始，众人反对队员盖布利拉为音乐剧的事情分心。更糟糕的是，他们的竞争对手从中作梗，把篮球赛、学术比赛和音乐剧面试排在了同一天。鱼与熊掌该怎样取舍，两个年轻人当机立断，妙计横生。','This School Rocks Like No Other!',4200000,0,16.536374,6.1,1000,98,'2006-01-20','en','/5FyeSxRciD73OpcCTHbrO5OPt6G.jpg',3.3695834209860105,3,'2026-09-10',2,NULL,NULL),(10950,'我是山姆','I Am Sam','在星巴克工作的山姆（西恩•潘 饰），虽已成人，但智力水平只有7岁。一次偶然，他收留了一个流浪女。该女子帮山姆生下了一个女儿后消失得无影无踪。他给女儿取名叫露西（达科塔•范宁 饰）,因为他最喜欢甲壳虫乐队的《天空中戴钻石的露西》。他非常疼爱自己的孩子。露西在山姆的细心呵护下慢慢地长大了，她发现爸爸不能看懂稍微复杂一些的故事。她在拒绝长大，希望和爸爸一样。父女两的生活是那么幸福。地区的教育官员发现了这个特殊的家庭，他们认为山姆没有能力照顾露西，于是把露西带走了。伤心极了的山姆一心要挣回露西的抚养权，于是他自以为是的去找该地区最好的律师……','love is all you need',22000000,92542418,26.071644,7.2,530,132,'2001-12-28','en','/8lVQXVhKBvAD4dwGvioBInC45HB.jpg',3.3932720824362255,3,'2026-09-10',2,NULL,NULL),(10955,'魔鬼雷普利','Ripley\'s Game','故事发生在《天才雷普利》20年后，已经结婚的雷普利靠他的姻亲及高竿犯罪技巧聚敛了大笔财富，和他的钢琴家妻子路薏莎定居在威尼斯的一座乡村别墅。迫不得已干下无数起法理难容的勾当后，雷普利已经心如止水无所畏惧，做起古画买卖的他仍然时不时巧取豪夺。 在当地一个家庭宴会上，宴会主人画框师强那森暗地里说了雷普利许多坏话，他的妻子想要制止已经为时太晚，悉数听到的雷普利怒火中烧。不久后，雷普利在柏林做生意的老朋友请求雷普利帮忙干掉自己的竞争对手，出于报复，雷普利向朋友推荐了强那森。身患血癌面临死亡的强那森，在金钱的诱惑之下，从一个普通人变成了杀手，虽然他的内心不断挣扎，但杀人已成为事实，而且第二个刺杀任务又摆在了他的面前。雷普利感觉事件已经失去了控制，良心未泯的他希望挽救强那森，帮他完成杀人计划，却不想自己也因此陷入了阴谋之中，无法自拔。虽然杀人计划最终完成，但却被对方抓到蛛丝马迹，追踪之下，发现凶手是强那森和雷普利，身为俄罗斯黑手党的他们立刻派出杀手来到雷普利居住的乡村追杀。强那森和雷普利也察觉到了危险，关键时刻，他们共同联手在雷普利的别墅里展开血拼。杀过多人之后，内心矛盾的强那森已默默接受了这种处境，然而，本以为从此可以与妻儿快乐生活的他，却被另两名杀手枪杀而亡。最后，内心充满愧疚的雷普利匆忙赶到了妻子的钢琴演奏会上，看着轻柔弹奏钢琴的妻子，雷普利的脸上现出内疚、疲惫，也有平静、淡然。',NULL,30000000,0,2.981047,6.6,69,110,'2002-09-02','en','/eVhycD9GBWPwnttygKYDi9hllAy.jpg',2.7757926108493725,3,'2026-09-10',2,NULL,NULL),(10956,'乔迪尔特历险记','Joe Dirt','乔（大卫·斯佩德 David Spade 饰）是一个众所周知的傻孩子，每天都调皮捣蛋招惹一堆的麻烦，终于有一天，乔的父母忍无可忍，于是决定将乔抛弃在一个陌生的城市之中。遭到抛弃的乔无依无靠，只能够凭借着本能在冰冷的城市中孤独的生存下去，好在他傻人有傻福，不仅顺利的长大了，还给自己找到了一份正儿八经的工作。\r 　　填饱了肚子的乔开始思念起自己的父母了，于是，他决定驱车去寻找他们。可是，这么多年的杳无音信，想要寻亲哪是这么容易的事情。一路上，乔遇到了不少的麻烦，却也结实了很多善良的朋友，漂亮姑娘布兰迪（布兰特妮·丹尼尔 Brittany Daniel 饰）更是“独具慧眼”，对乔青睐有加。','He Came. He Cleaned. He Conquered.',17700000,30987695,15.976335,5.5,242,91,'2001-04-10','en','/yykDEtHk6DMtZK8EaxW88YyQ054.jpg',3.0172480864333986,3,'2026-09-10',2,NULL,NULL),(10970,'默片','Silent Movie','本片是一部典型的喜剧片，有一位喜好酗酒的制片家，一天他刚喝完酒，便突发奇想，要拍一部卖大钱的无声电影以便一夜成名，于是他第二天就开始找寻大明星参加这部剧的演出，在这个过程中，这位制片人闹出了一连串的笑话。此片的最大特点是不用对白来交代剧情的发展，另一个的特点是网罗多名大明星客串演出，全片不乏笑料...',NULL,0,0,7.315935,6.7,78,86,'1976-06-17','en','/AeaoOSqEU3elkpDAlKbIWcdKLJ8.jpg',2.8163511826622263,3,'2026-09-10',2,NULL,NULL),(10972,'9号谋杀案','Session 9','丹弗斯州立精神病院离波士顿不远，建于1860年代，最多时住了两千多名病人，如今已经废弃，等待重建，另作他用。重建之前需要将其中的石棉拆走，一家专门拆卸危险材料的公司承担了这个任务。  　　包括公司老板戈登在内的五个男人走进这座阴森的庞然大物。戈登家中有妻子和一个新生的女儿，指着他赚钱养家，因此他极力承揽下活计后还答应一周内干完两三周才能做完的工作；菲尔是个小头目，因为女朋友跟别人走了，吸上大麻；汉克就是拐走他女朋友的家伙，是个得意洋洋的赌徒，还时时嘲讽菲尔；跟着去的还有学法律的学生迈克和戈登的侄子杰夫，一个单纯的小伙子。  　　五个人刚进去，戈登就听见了奇怪的声音，似乎来自这座医院的过去。迈克对医院的历史非常感兴趣，在地下室中他发现了一些磁带，它们记录了一个叫马丽·霍布斯的具多重人格的病人的资料，共有九个部分，迈克开始听这些磁带；与此同时，菲尔开始怀疑戈登的精神状况，杰夫则在竭力与对黑暗的恐惧对抗，汉克在一堵墙里发现了一些财宝，晚上他出去后，就再也没有回来。  　　工作的压力一天天加剧，汉克的失踪和一系列怪事情的发生使每个人的神经拉得越来越紧，人的精神原来那么容易受影响，被扭曲。过去的恐怖历史和痛苦折磨，现在的奇异事件和身边人的内心秘密，一点一点压在大家心上，而丹弗斯精神病院无声地注视着他们，将自己的阴影投到每个人心底。  　　一天一天过去，没有人知道又长又暗的走廊尽头是什么，墙的那一边又隐藏着什么，他们当中谁在撒谎，谁会崩溃，谁又值得信任？恐惧从最深处渗上来，弥漫到每一个角落，面对自己脆弱的精神和神秘的环境，不知道这一切到底意味着什么，心理承受力遭受重大考验。而结局，总是出人意料……','Fear is a place.',1500000,373967,11.064228,6.2,251,100,'2001-08-10','en','/LIUvTaTgVT2RirlPJkIDwMsbOm.jpg',3.066474354694265,3,'2026-09-10',2,NULL,NULL),(10981,'空无一物','Nothing','\"以下是一个真实的故事。人物是确实存在的，名字也是真实可信的。一切都经过查证。戴维和安德鲁是最好的朋友。从九岁开始，他们就是最好的朋友。安德鲁是个非常神经质的年轻人。他害怕一切东西。戴维是个完全以自我为中心的人，从来不能让事情按他满意的方向发展。他们两个都和别的孩子合不来。不久以后，他们意识到，他们生存的最好机会是团结起来。悲惨的安德鲁在他父母去世后变得更加焦虑，很快的甚至变得害怕离开家门。就像尝试做的其它事情一样，戴维成为摇滚明星的梦想被婉转拒绝。身无分文，也没地方可去，戴维搬去和安德鲁一起住，而安德鲁也非常需要帮助。共同生活的日子，戴维提供基本的生活必需品，安德鲁提供一个好朋友的精神支持。戴维勇敢的走出家门找到了工作，而安德鲁留在家的安全区域内作线上旅游经纪。在和社会进行了一生的斗争后，戴维和安德鲁最后快乐的生活在一起。但难过的是，没有什么是永远的。\"',NULL,0,0,3.408955,5.8,38,90,'2003-09-09','en','/vefWBq6xpeMYtF7ROgGfXLdp5Qu.jpg',2.6324516354837177,3,'2026-09-10',2,NULL,NULL),(10982,'小红帽','Hoodwinked!','本片取材自一个经典的寓言故事，一只灰熊和侦探比尔斯托克正在一个老奶奶的家中调查一头狡猾的狼和一个迟到的村民，他们被告以擅闯民宅和偷吃罪，他们之间展开了耐人寻味的故事。  这部影片所讲述的故事就发生在《小红帽》这个童话的结尾，灰熊警长和鹳探员比尔奉命调查发生在祖母小屋的内部动乱案件，多人都被警方指控有犯罪行为，涉案人员包括空手道高手小红帽、搞笑又具讽刺性的大灰、一个略有痴呆的树林里的居民等。他们分别被指控有多项罪名，其中包括：破坏和非法入侵、破坏社会安定、非法偷吃、无执照使用斧子等等。然而，所有被指控的这些不一般嫌疑人都有这他们们自己的故事要讲……  　　虽然《小红帽》曾是全世界家喻户晓的经典童话，不过观看这部全新的动画电影之前要摒弃以往的一切认知，因为本片将颠覆原作中的所有人物和情节，并且涵盖了现实世界中的犯罪调查。  　　影片从童话故事的结尾开始。负责当地治安和法律仲裁工作的警探接到报案，赶到老奶奶的村舍，发现遗留的一堆动物皮毛。根据犯罪现场的证据判断，可能是猎人袭击了扮作老奶奶的大灰狼，触犯的罪名包括：非法闯入、破坏社会安定、馋嘴偷吃和无执照挥舞斧头。  　　可是毕竟，往往表象具有一定欺骗性，警方很快锁定了存在犯罪可能的嫌疑对象，包括身体强健的老奶奶、擅长表演的猎人、投递糖果的小红帽和报道新闻的大灰狼。温文尔雅的青蛙侦探尼基、精明强干的灰熊警长和鹳警员比尔讯问了几个嫌疑犯，结果发现他们每人供述的内容都迥然不同，而且颠三倒四、含混不清。不仅如此，种种迹象表明，案件似乎又与臭名昭著的“糖果大盗”有着千丝万缕的联系，因为该犯正在森林中肆虐，四处窃取糖果配方。  　　排查这些嫌疑犯并非易事，因为其中的每个人都隐藏着秘密和阴谋。随着调查的深入，警探们逐渐发现，表面清白无辜的小红帽绝顶狡猾，外形险恶的大灰狼被严重误解，年岁已高的老奶奶有着出人意料的秘密生活，而危险分子猎人则正酝酿着让人瞠目的巨大野心。  　　为了解开重重谜团，警探们只好求助于目击证人，可由山羊、绵羊和兔子提供的证词却矛盾百出。经过不懈努力，案情最后终于真相大白，穷凶极恶的罪犯得以浮出水面。小红帽、大灰狼、老奶奶和猎人可以暂时忘记彼此之间的分歧，一起狂欢庆祝洗脱罪名了……','Armed And Dangerously Dumb.',15000000,51053787,23.980329,5.9,479,80,'2005-12-16','en','/kwPl1AKX4BLxrh5PCkrwYWeEV5I.jpg',3.2038756686942436,3,'2026-09-10',2,NULL,NULL),(10984,'情人劫','Valentine','本该温馨美好的情人节，四名漂亮的女人却收到了令人不寒而栗的古怪卡片，接着古怪恐怖的事情开始在她们中间发生。原来，这一切起因于她们上学时曾无情的嘲笑过个一个性格内向、古怪的可怜男生。现金一转数年过去了，当年高中舞会上的“丑小鸭”已经变成了“天鹅”，决定回来在情人节当日对她们实施最无情的报复。到底谁才是元凶，这四个漂亮女人能否逃过此劫？围绕在她们周围的男士人人皆有可疑……','Remember that kid everyone ignored on Valentine’s Day? - He remembers you.',0,0,5.904126,5,114,96,'2001-02-01','en','/jMtWV4FixMGTgUjbr9NFVEANGYQ.jpg',2.8324491389757847,3,'2026-09-10',2,NULL,NULL),(10985,'新丁驾到','The New Guy','哈里逊是个让人讨厌的家伙，他是同学眼里永远的笑料。在即将升入高中的暑假里，他为了发泄满腹的怨气而使用暴力伤害了别人。他随即被判入狱。但是这次不愉快的经历却使哈里逊因祸得福。他在狱中结识了老江湖路德，路德教给许多他如何讨别人喜欢的绝招，这可让哈里逊受益匪浅。　 出狱之后哈里逊改名换姓升入新高中，小试身手果然立时当上了一班之长，风流潇洒没多久便成为全校上下的焦点所在。几番努力，他更把啦啦队队长--美女丹妮尔（艾丽莎·杜舒）追到手。可就在他摇身一变成了被人们议论、羡慕、崇拜的偶像的同时，一位深知他老底的旧校友竟然也前来同一所高中就读！天呐，哈里逊的真面目随时都会被揭穿！这可让这出好戏变得难以收场了。','A zero will rise.',13000000,0,13.525704,5.7,151,88,'2002-05-10','en','/aekXSzkn3zry6aummMl7AU4rSa8.jpg',2.934345859344252,3,'2026-09-10',2,NULL,NULL),(10987,'月光光心慌慌6：迈克尔的诅咒','Halloween: The Curse of Michael Myers','迈克尔在六岁的时候，就被恶灵控制，把他的姐姐刺死在血泊之中。为此被关进暗无天日的疗养院多，最后却被他逃脱出来。每到万圣节，迈克尔便会造访他的家乡，并带来一场腥风血雨的屠杀浩劫，万圣节已成为小镇居民深深恐惧的日子。六年前，迈克尔死于大火之中，人们渐渐淡忘迈克尔所带来的恐怖记忆，准备大肆庆祝一年一度的万圣节，然而迈克尔也要和他们一起「狂欢」……！','Haddonfield is ready to celebrate Halloween.... so is Michael Myers!',5000000,15116634,9.483717,5,170,88,'1995-09-29','en','/cd7sA5drCG2wy5XdQ46ZFyTIKkr.jpg',2.908785183446594,3,'2026-09-10',2,NULL,NULL),(10991,'Pokémon: Spell of the Unknown','Pokémon 3: The Movie','绿色草原，是个能够使人和神奇宝贝都心境安宁的地方，在这里住着秀力博士和他的女儿小美，有一天，秀力博士在遗迹里研究神秘神奇宝贝-未知图腾的时候，不小心被吸进异次元内，小美十分思念父亲，没想到竟因此唤醒了未知图腾。未知图腾将小美的心灵以结晶化呈现，最后更创造出小美最喜欢的传说神奇宝贝-炎帝，小美因此误以为爸爸变成炎帝的模样回来了，炎帝为了实现小美的心愿，并充当他的爸爸。小智的妈妈和秀力博士是旧识，因为担心小美而赶来，在这碰到刚结束对战来到这里休息的小智他们。没想到炎帝却从结晶塔中出现，将小智的妈妈暂时催眠，强行带走。得知整件事情的经过后，小智等人于是并决定前往结晶塔，救出小智的妈妈，并让小美脱离那里......','Pokémon: Spell of the Unknown',16000000,68411275,9.18885,5.9,137,93,'2000-07-08','ja',NULL,2.9146141437685635,3,'2026-09-10',2,NULL,NULL),(10992,'猫狗大战','Cats & Dogs','猫狗自古就水火不容，这部动画更是将它们卷入一场势不两立的战斗当中。在这里，猫是最邪恶不过的动物，它们貌似平静温顺，却在暗中紧锣密鼓筹划着统治地球的阴谋。狗则是人类最忠实的保护者，他们忠心耿耿，要把危害人类的猫类“赶尽杀绝”。猎犬小卢正是这么一只身负重任的狗。因为，它得知了猫们正在野心勃勃，要毁灭狗类进而威胁人类。  　　这只毫无战斗经验的小狗，临危受命担任起狗类的统帅，狗军师们帮他出谋划策。众狗各施所长，就连人类惯用的卧底招数也成为了这场猫狗大战的超级战术！看来小卢要在复杂的“战况”中鼓足斗志才行。','Things Are Gonna Get Hairy!',60000000,93375151,18.735024,5,352,87,'2001-07-04','en','/9glj8lbewciFcZ54EUr59kX2kXh.jpg',3.041719221165309,3,'2026-09-10',2,NULL,NULL),(10994,'白色夹竹桃','White Oleander','在阿斯特丽德（爱莉森•洛曼 饰）15岁那年，母亲（米歇尔•菲佛 饰）杀死了抛弃她的情人。阿斯特丽德亲眼看着母亲被捕。自从母亲被捕，她便过着孤苦伶仃的生活，与此同时她被收养了。  　　阿斯特丽德从女主人的男友身上感觉到了父爱，却被女主人认为她勾引自己的男友，向她开枪。康复后的阿斯特丽德居住进抚养院，她常被欺负，但自从被枪伤之后她便知道她需要依靠自己力量来保护自己。  　　在抚养院中，男孩保尔主动接近阿斯特丽德，他们都喜欢画画。他们的来往却得不到母亲的赞同，母亲告诉她无论如何都要靠自己走下去，不能靠男人。  　　在后来阿斯特丽德被一名女明星克莱尔（芮妮•齐薇格 饰）收养。克莱尔很珍爱经历坎坷的阿斯特丽德，可是阿斯特丽德的母亲却嫉妒她们，那次见面之后，克莱尔竟然自杀了。  　　克莱尔的死对阿斯特丽德的打击很大，她要求被一名俄罗斯女商人收养，她变得自甘堕落。这时母亲要求阿斯特丽德为她出庭作证，并从母亲嘴里知道了有关自己的身世，可是她要求母亲放她走。  　　母亲果真放她走了，母亲没有要她出庭，阿斯特丽德看着母亲走上囚车…… ©豆瓣',NULL,0,0,9.423866,7.2,108,109,'2002-10-11','en','/pOdmhUaqvg4twAHqrhL5Onjgalb.jpg',2.9161428598823127,3,'2026-09-10',2,NULL,NULL),(10996,'精灵鼠小弟2','Stuart Little 2','经过了两年的共同生活，如今斯图亚特和乔治一家过得融洽和睦，斯图亚特还是一如既往的聪明精灵，然而内心却为了一件事有点不安——乔治母亲添了小女儿，他们对这个千金宠爱有加，几乎花掉全部时间精力。而乔治功课也日渐繁忙，陪伴斯图亚特的时间也少了。斯图亚特有点落寞，直到它遇上了鸽子玛格罗。斯图亚特上演了一幕英雄救美，把玛格罗从危难中解救出来，并带她回家疗伤，心里对她暗暗倾慕。然而斯图亚特的恋爱并不是特别顺利，他不知道玛格罗有着不为人知的秘密，这只机智勇敢的小白鼠面临着又一次充满挑战的冒险。','A Little Goes A Long Way',120000000,169956806,27.990284,5.4,613,78,'2002-07-19','en','/gpnK7MPDOsYG55NvXtXKeO9O6Kg.jpg',3.1941087053876545,3,'2026-09-10',2,NULL,NULL),(10998,'致命诱惑','Fatal Attraction','麦克（麦克·道格拉斯）是个无业在家的男人，他和阿莉克丝（格伦·科罗斯）的一夜情竟成了他噩梦的开始，因为她坚持要继续两人的关系，并声称已怀了他的孩子。阿里克丝有步骤的威吓麦克，甚至还绑架了他的女儿，希望以此来挽回他的爱。道格拉斯竭尽全力饰演这个颇受困扰的丈夫，他满怀罪恶感，试图将他的家庭和婚姻从自己轻率行为造成的后果中挽救出来。','A look that led to an evening. A mistake he\'ll regret...FOR THE REST OF HIS LIFE.',14000000,320145693,16.742972,6.6,291,119,'1987-09-11','en','/vjB9XwJKnYqFKKjhWcE6WpAf5Ki.jpg',3.146456388116911,3,'2026-09-10',2,NULL,NULL),(10999,'独闯龙潭','Commando','平静的城市中突然发生了一系列暗杀事件，受害者皆为退役特种部队上校约翰（Arnold Schwarzenegger 饰）的昔日部下，老上司克比为此拜访了约翰的山间小屋向其提出警告，退隐多时的约翰只想同尚年幼的女儿詹妮享受生活，不愿再次卷入仇杀，岂料这次的敌人尾随克比寻至约翰住处，他们掳走了詹妮，强迫约翰刺杀奥维地共和国总统，以便为幕后策划者阿里乌斯登上该国总统之位铺平道路。  　　约翰当然不会就范，他摆脱了随行的监视人员，从飞机一跃而下，暂时脱离了阿里乌斯的控制之后，他只有十一小时救出詹妮。约翰在机场请求素不相识的黑人姑娘西迪（Rae Dawn Chong 饰）相助，两人一同经历了连串的火爆战斗，西迪对这位陌生魁梧男子的态度由戒备转向全力协助，并最终登上了阿里乌斯藏匿的岛屿……','Somewhere... somehow... someone\'s going to pay.',10000000,57500000,34.224204,6.4,742,90,'1985-10-03','en','/2TVImRpwy8kLaDTpV9MqaEvNwsu.jpg',3.3909582386910886,3,'2026-09-10',2,NULL,NULL),(11001,'笨贼妙探','Blue Streak','盗贼麦尔斯（马丁·劳伦斯 Martin Lawrence 饰）与三名同伙合作盗窃钻石，岂料其中一人德克背叛了他们，警方被惊动，麦尔斯走投无路，只得逃跑中将钻石藏在一栋未完工的大楼通风管道里，之后束手就擒。两年后，麦尔斯刑满释放，但外面的一切似乎都已改变，女友不再需要他，而当年他藏钻石的那栋楼居然变成了——警察局！为了取回钻石，麦尔斯偷到ID卡，又凭借伪造的档案乔装成警察混入警局，由于警方缺人手，假警察麦尔斯很快得到任命，和菜鸟探员卡森（卢克·威尔逊 Luke Wilson 饰）结成搭档。麦尔斯凭借自己的盗窃经验很快表现出位，在警局得到重用，而管道中的钻石经过冲洗后下落不明，麦尔斯只得坚持假装下去。不久，德克为了得到麦尔斯的钻石再次出现…','He\'s A Cop That\'s Not.',65000000,117758500,16.865782,6.1,352,93,'1999-09-17','en','/aHqwNdK16O2H6O21HBDK06jcJfR.jpg',3.144962216624471,3,'2026-09-10',2,NULL,NULL),(11004,'奇迹小子','Wonder Boys','教授格雷迪（迈克尔·道格拉斯 Michael Douglas 饰）曾经被尊称为“奇迹小子”，因为他7年前出版的小说如此优秀，在文坛上轰动一时。这表面看来是一件好事，却让格雷迪背上了沉重的思想包袱，他害怕自己的新作品落差太大，于是一直把它压在箱底，不敢发表。如今，妻子已经离他而去，他有一个情人萨拉（弗兰西斯·麦克多蒙德 Frances McDormand 饰）。这个情人，是他的校长，同时也是上司的妻子。  　　格雷迪怎么也没想到，一把年纪了，倒霉事才陆续朝他招手。萨拉告诉他肚里怀上了他的骨肉。更糟糕的是他被恶狗所咬，不过也因此和学生詹姆斯（托比·马奎尔 Tobey Maguire 饰）开始一段感情真挚的忘年交。在詹姆斯身上，格雷迪发现了可贵的文学潜质。另一方面，编辑克莱特里（小罗伯特·唐尼 Robert Downey Jr. 饰）催命鬼似的向格雷迪催稿。众多事情使格雷迪的生活就像六国大封相。他该如何厘清头绪，从乱麻中重新整理下人生呢？','Undependable. Unpredictable. Unforgettable.',35000000,0,9.011729,6.9,161,111,'2000-02-22','en','/5yvQe06HPNII2eZCJWTeMwqLWvR.jpg',3.001883322836896,3,'2026-09-10',2,NULL,NULL),(11007,'儿女一箩筐','Cheaper by the Dozen','这个家庭有着一对父母、十二个孩子和一堆宠物，热闹混乱的局面反而为家庭增添快乐。尤其是那些性格不一、年龄各异的儿女们，就像活宝一样深得父母欢喜。现在，这家人正面临着前所未有的变化：因为父亲汤姆（史蒂夫·马丁 Steve Martin 饰）要去大城市的高校球队任教，他们要搬往那里生活了，这亦意味着，孩子们会有更好的教育和更广阔的发展空间；当然，父母日渐繁忙的工作也会削减他们和孩子沟通的时间。  　　母亲凯特（邦尼·亨特 Bonnie Hunt 饰）的作家事业也如日中天，甚至要离家宣传新书。孩子们已经和父母日渐生疏，大城市的生活让这个家庭得到了日渐光鲜的地位，却失去了内在的情感纽带。看来，汤姆和凯特要重新思考和抉择了。','Growing pains? They\'ve got twelve of them!',40000000,190212113,26.516624,6,699,98,'2003-12-24','en','/afclGGoQslTYFTnyW1LRMtJMiBp.jpg',3.3003576579861975,3,'2026-09-10',2,NULL,NULL),(11011,'Ri¢hie Ri¢h','Ri¢hie Ri¢h','亿万富翁继承人Richie Rich拥有一切，包括作为击球教练的雷吉·杰克逊和作为私人教练的克劳迪娅·希弗，但没有玩伴。此外，恶棍劳伦斯·凡·道夫正计划接管这个家族帝国。哦！进入忠实的管家吉百利来挽救这一天。','An adventure so big... even the world\'s richest kid can\'t afford to miss it!',40000000,0,14.398356,5.4,415,95,'1994-12-19','en','/50KTdu5XWIoS9gSJFGLWCfybzcn.jpg',3.098626918418598,3,'2026-09-10',2,NULL,NULL),(11013,'秘书','Secretary','二十几岁的女主人公LeeHolloway，在精神病治疗中心经过短暂治疗后，回到新泽西的家。再次面对嗜酒如命的父亲和懦弱的溺爱自己的母亲，她\"自毁\"症状又有些抬头。她清楚地意识到“旧病复发”的可怕性，于是开始寻找方式，以逃避这个从小长大都倍感压抑的生活环境。她开始去学习打字，并很快在一家律师事务所找到了一份秘书的工作。对她来说，保住这份工作非常重要，尽管她的老板EdwardGrey (JamesSpader)看上去有些专横跋扈。Edward观察她，研究她，慢慢地开始纠正她打字的错误，在华丽的办公桌前以掌臀来惩罚她的打字失误。这反倒激发了Lee对Mr.Grey的情欲。从此，她不断地用“打字失误”来重温这份\'温情\'。电影小心仔细的将角色的个性推展开来，终于使Lee和Edward清楚地认识到，他们之间有一种特别的、肉体上和精神上的彼此依赖。两颗饱受压抑且脆弱的心在不言中慢慢走近，彼此平衡著对方的伤与痛，整个过程充满著温馨与和谐。','Assume the position.',4000000,9304609,19.107285,6.7,376,104,'2002-01-11','en','/mASAr45JxNEGCQ0J6c5wLezSRQT.jpg',3.2255906162399,3,'2026-09-10',2,NULL,NULL),(11015,'第三类终结者','The Relic','生物进化学家玛歌博士（潘妮洛普安蜜勒饰）与警探文生（汤姆赛兹摩饰），遇上一连串令人毛骨悚然的谋案，案发地点皆在玛歌工作的自然历史博物馆。博物馆正筹备南美洲历史遗迹的古文物大展，馆长安卡斯伯（琳达杭特饰）为此次的盛大展出，设计各种令人叹为观止的展览馆，包括了巴西“卡索加”区、埃及古坟区、马雅古坟区、巫毒教展示间以及迷信传说展示区等，以期在募款的开幕酒会中，得到各界瞩目，延续博物馆的命运。开幕酒会在即，博物馆内的谋杀案却未侦破，警方并进一步发现涉案的杀人魔手法惨烈，遇害者皆是头部断裂，头颅有5.5呎大洞，视丘与脑下垂体等具有管理荷尔蒙作用的脑浆凭空消失！这与玛歌博士在古迹上意外取得的卵细胞分子DNA不谋而合，原本深信科学而排斥迷信的玛歌不得不转而求教于指导教授佛洛克（詹姆斯怀特摩饰），探索他时常耳提面命的“卡索加”杀人魔传说。开幕酒会人潮涌进，官盖云集！卡索加躲在历史博物馆迂回的展览屋内伺机而动，玛歌与文生警探正解开“卡索加”之谜，卡索加则已现身酒会会场，惨绝人寰的惊叫声在黑暗中此起彼落……','The Next Evolution In Terror.',60000000,33956608,12.621769,5.8,130,110,'1997-01-10','en','/fAG4nKPUWEIwGBpP38H64GGV8kl.jpg',2.9070463089313923,3,'2026-09-10',2,NULL,NULL),(11022,'缉毒特警','Narc','在一次执行任务中，警察尼克（杰森·帕特里克 Jason Patric 饰）无意中开枪击中了一名孕妇，这场悲剧让尼克丢掉了饭碗，也让他深深的陷入了自责的情绪中无法自拔。一场恶性凶杀案的发生让城市陷入了恐慌，在和罪犯周旋的过程中，警方损失惨重。无奈之下，警方找到了尼克，希望他能够协助破案，与此同时，他们许下了承诺，若果杰克出色的完成任务，他将重新回到警察的岗位上来。  　　亨利（雷·利奥塔 Ray Liotta 饰）成为了尼克的新搭档，亨利的旧搭档在之前追捕凶手的行动中不幸殒命。就这样，怀揣着各自的目的，亨利和尼克展开了对案件的调查，然而，随着调查的深入，一个惊天秘密逐渐浮出了水面，而这个秘密的出现也将亨利和尼克带入了十分危险的境地。',NULL,6500000,12633747,8.526635,6.8,142,105,'2002-01-14','en','/uGHFyVdMQKvIXlsLAoXa5nOUGF.jpg',2.964568781339536,3,'2026-09-10',2,NULL,NULL),(11023,'十三岁','Thirteen','成长于单亲家庭的13岁女孩特蕾西一直是学校的楷模，母亲马兰妮的骄傲。然而这一切在特蕾西进入中学后完全改变了。特蕾西的同学艾维是全校的焦点，她着装性感、身材火辣，特蕾西发现艾维才是自己心中的榜样。于是她跟艾维混在了一起，学会了酗酒、吸毒等等恶习。面对自己的乖乖女忽然间的变化，马兰妮感到不可理解，由于缺乏有效沟通，母女俩爆发了一连串不可调和的冲突……','It\'s happening so fast.',2000000,4601043,20.331593,6.7,339,100,'2003-08-20','en','/uzTLlZrNF6rMPBh5mUQu6vLnTtX.jpg',3.201927294736516,3,'2026-09-10',2,NULL,NULL),(11024,'史酷比2：怪兽偷跑','Scooby-Doo 2: Monsters Unleashed','一位神秘人物的出现让小镇上的居民终日生活在恐惧之中，他利用一架邪恶的机器制造出了许多可怕的怪物，将它们放到镇上为非作歹。这时，就轮到“秘密公司”的诸位出马了，可摩拳擦掌跃跃欲试的沙吉（马修·里沃德 Matthew Lillard 饰）和搭档史酷比（Neil Fanning 配音）却被告知留守公司，不必参加行动。  　　不甘心的沙吉决定和史酷比私下里调查事件的真相，以挽回他们一败涂地的名声，没想到却闹出了一大堆的麻烦。随着调查的深入，博物馆馆长帕特里克（赛斯·格林 Seth Green 饰）带着他的阴谋渐渐浮出水面，线索显示，这一切，很可能和传说中的恶魔复仇有着千丝万缕的关联。','They came. They saw. They ran.',0,181466833,22.644275,5.4,500,93,'2004-03-24','en','/gpsqaqF7nNw2H71pmnh5m3uQnin.jpg',3.148410779150711,3,'2026-09-10',2,NULL,NULL),(11025,'纽约时刻','New York Minute','简（爱什莉•奥尔森 饰）与罗西克（玛丽-凯特•奥尔森 饰）是瑞恩家的一对双胞胎。她们相貌相似，血脉相连，但性格确实彻彻底底的不一样。简热爱学习，乖巧懂事；罗西克则是叛逆好胜，经常逃课缺席。而这对姐妹花也都将前往纽约，同样为着自己的梦想奋斗。不同的是，简为的是自己的大学文凭，需前往纽约参加一场演讲比赛，罗西克为的是自己的音乐道路，希望能在纽约找到最前卫的音乐，得到出色音乐人的赏识。\r 　　她们各自前往曼哈顿，却同样迷失在前往的道路上。陌生的地方都使她们无法适从，姐妹俩在困难的时候还是不愿忘记自己的梦想，继续匍匐前进。\r 　　幸运之神又会否眷顾她们，让她们梦想成真呢？',NULL,0,0,10.0403,5.5,185,91,'2004-05-01','en','/px9hV6w6XzAjGdxCRUAUasAHQsP.jpg',2.9542508392117863,3,'2026-09-10',2,NULL,NULL),(11026,'驱魔人前传','Exorcist: The Beginning','949年的开罗。考古学家、战争时曾担任牧师的梅林接到一份工作，将前往肯尼亚参与发掘一座五世纪的教堂，委托人了解梅林在圣神像领域的专长，要求他取得一个苏美尔风格的恶魔像。梅林来到肯尼亚，与教廷派来的神父汇合，才得知教廷对这座五世纪的教堂一无所知，而这座教堂本身充满了疑点。在发掘队医生莎拉等人的介绍下，梅林发现整个发掘过程也充满诡异现象，考古学家贝松在发掘中发疯，而贝松画出的图画，分明与梅林看到的恶魔像如出一辙。同时，发掘营地的孩子出现了被“恶魔触碰”的状况，浑身抽搐却能操纵土狼。梅林等人似乎在恶魔的诅咒中越陷越深……','Go back to where the horror began.',80000000,78000586,15.761384,4.7,183,114,'2004-08-20','en','/4b7Mhc4HZN7XzMMLukaQ9C0x1Dx.jpg',2.9171049731094136,3,'2026-09-10',2,NULL,NULL),(11027,'邮差总按两次铃','The Postman Always Rings Twice','机械师弗兰克（杰克·尼克尔森 Jack Nicholson 饰）身无分文，被洛城附近小镇上的一位希腊店主尼克收留，尼克年轻的妻子科拉（Jessica Lange 饰）引起弗兰克的强烈兴趣，科拉亦对酗酒的希腊佬心生厌倦，两人很快趁尼克进城时发生了关系，并决定私奔，但弗兰克的好赌成性迫使计划改变，科拉本欲杀死醉酒的尼克但只是将其重伤，尼克出院后科拉与弗兰克又生一计并终于得手。保险公司因不愿赔偿尼克的意外身亡险遂组织人手证明科拉与弗兰克有罪，幸有律师巧借不同保险公司间的厉害冲突使二人得以脱罪。弗兰克与科拉虽在狱中互相倾轧但还是走到了一起，两人接管小店后的生活平淡无奇，直到某天一名男子登门要挟他们…… （本片是詹姆斯·凯恩的原著小说第四次的电影改编版。）','You Will Feel The Heat',12000000,0,6.803763,6.4,110,122,'1981-03-20','en','/k52pPgVOHPwjIyMdvNZZi3Z7zFR.jpg',2.883296546917918,3,'2026-09-10',2,NULL,NULL),(11033,'剃刀边缘','Dressed to Kill','家庭主妇凯特（安吉·迪金森 Angie Dickinson 饰）和丈夫的婚姻生活乏善可陈，儿子皮特又（凯西·戈登 Keith Gordon 饰）终日沉迷于自己的发明之中。对此她经常向艾略特（迈克尔·凯恩 Michael Caine 饰）求助，甚至想引诱这位高大英俊的心理医生。一日，凯特在美术馆里偶遇了一名男子，两人经过短暂的相互试探之后很快就干柴烈火起来。激情退却后的凯特想起了丈夫和儿子，觉得心有愧疚，正当她乘坐电梯准备离开时，被一名戴着墨镜的奇怪女子残忍的用剃刀杀死。妓女布雷克（南茜·艾伦 Nancy Allen 饰）目睹了这恐怖的一幕，作为目击证人的她反而被警方怀疑是杀人凶手。为了洗清嫌疑，她决定深入案件查询真相，在皮特的帮助下，她很快将嫌疑锁定在了一个叫做“巴克”的人身上，而这个“巴克”竟然也是艾略特的病人。这一切是阴谋还是巧合？在布雷克接近真相的同时，巨大的危险也渐渐的离她越来越近。','The Latest Fashion In Murder',6500000,31899000,11.208769,6.8,157,105,'1980-06-25','en','/oy1m5dd44foNrxV8U9l6Walx82V.jpg',2.9952794188959553,3,'2026-09-10',2,NULL,NULL),(11036,'恋恋笔记本','The Notebook','一个浸润着鲜红与纯白的爱情故事，写在一本洒满昏黄的笔记本上，被一位老先生(詹姆斯·加纳 饰)，一遍一遍的讲述。老太太(吉娜·罗兰兹 饰)总是静静的听着，好奇的追问结果。在一家疗养院，这样不变的场景每天都会上演。笔记本上，秀美的字迹，记载着发生在那个夏天的爱情。艾莉(瑞秋·麦克亚当斯 饰)是富有人家的千金，她随家人来到小镇避暑。在一个充满梦幻的游乐场，邂逅了诺亚(瑞恩·高斯林 饰)。诺亚没有钱，却活的很快乐。艾莉在他那学会了自由，得到了欢笑，两人很快热恋起来。然而在艾莉父母的阻挠下，相爱的两个人，就被分开在夏天结束的那一刻。随着诺亚的365封信被偷偷藏起，艾莉在7年后终于放弃了等待。就在她要步入教堂的前一天，突然在报纸上看到了诺亚曾许诺给自己建造的白色房子。一切记忆，全部苏醒……也许，应该苏醒的，不是故事中的，而是听故事的人。','Behind every great love is a great story.',29000000,115603229,55.109138,7.7,3067,123,'2004-06-25','en','/rNzQyW4f8B8cQeg7Dgj3n6eT5k9.jpg',4.087910680993589,3,'2026-09-10',2,NULL,NULL),(11042,'野蛮入侵','Les invasions barbares','与父亲形同陌路的塞巴斯蒂安（斯蒂芬·卢梭 Stéphane Rousseau 饰）忽然接到母亲路易丝的电话，那个风流成性的历史教授父亲莱米如今躺在医院里，命不久矣。塞巴斯蒂安在一番犹豫之后赶回蒙特利尔，陪父亲走过最后一段时光。多年的隔膜以及生活方式的差异让这对父子从一开始就吵了个天翻地覆，但塞巴斯蒂安还是想尽办法让父亲平静的走完最后的日子。他把父亲换到舒适的病房，并且打电话召集了父亲昔日的朋友聚集到一起，甚至为父亲买来海洛因止痛。在相处过程中，父子俩的感情产生了微妙的变化。  　　该片被誉为“生命的告别仪式”，以其平实朴质的影像和细腻入微的感情横扫各大影坛颁奖礼。2003年，法国戛纳电影节上获得了最佳剧本、最佳女演员大奖，并获金棕榈大奖提名；2004年，法国恺撒奖最佳导演、最佳影片、最佳剧本奖；2004年，奥斯卡最佳外语片奖以及最佳原创剧本提名。','A provocative new comedy about sex, friendship, and all other things that invade our lives.',8000000,3432342,3.03091,6.7,77,99,'2003-05-21','fr','/fNNXhMitLAWrxTC6uEm9m6DymSt.jpg',2.8035994727698323,3,'2026-09-10',2,NULL,NULL),(11051,'基督最后的诱惑','The Last Temptation of Christ','木匠出身的耶稣经常为偏头痛所折磨，他在朦胧中感到了上帝的召唤，意识到自己将作为救世主，牺牲自己去拯救世界。他开始了在沙漠中自我放逐的40天的寻道之旅。当耶稣的精神战胜肉体，他就无所不能，甚至挖出自己的心脏给门徒看，叫苹果树立刻生长结果。但是他无法驱逐自己的内心的魔鬼，也无法平息对于自我的犹疑，他表现出一个普通人所具有的惶惑和忧虑，倒是犹大不断的安慰和鼓励他。耶稣在人性和神性之间摇摆。清醒后的耶稣指使犹大去向当局告发自己，以帮助自己实现为世人赎罪的使命。几天之后，头戴荆冠的耶稣被罗马士兵钉到十字架上。耶稣在十字架上忍受着巨大痛苦，恍惚中有一位天使告诉他上帝已经解除了他的责任，从此可以过上正常的生活。耶稣在天使的陪同下走下了十字架，像普通人一样娶妻生子……',NULL,7000000,8373585,14.672151,7,201,164,'1988-08-12','en','/7L4qwrC1mipZXJfU5oRgQWChLv1.jpg',3.0775447686813746,3,'2026-09-10',2,NULL,NULL),(11056,'黑暗','Darkness','在一个阳光明媚的日子里，马克（伊恩·格林 Iain Glen 饰）携妻子玛丽亚（莉娜·奥琳 Lena Olin 饰）、女儿瑞姬（安娜·帕奎因 Anna Paquin 饰）及幼子保罗（Stephan Enquist 饰） 举家搬到一幢林间别墅居住。除却瑞姬，一家人均沉浸在喜悦之中。然而好景不长，不祥的气息渐渐笼罩在这栋房子的上空。先是马克旧病复发，险象迭生，随后保罗也日渐忧郁，仿佛被什么吓倒一样，所绘的图画也多为血腥内容。父子俩的精神与举止越来越诡异，似乎老房子内隐藏着什么东西持续影响着他们。事态愈演愈烈，恐怖阴森的事件接连发生，瑞姬将和家人们经历永生难忘的一段黑暗时光……','A house. A past. A secret. Will you dare enter?',0,0,6.340135,5.6,112,102,'2002-10-02','en','/bXnYpFNcBNdifn7NmjJuqzBBJS0.jpg',2.8543099050746754,3,'2026-09-10',2,NULL,NULL),(11058,'天赐','Godsend','邓肯夫妇(格雷戈•金尼尔、丽贝卡•罗明-斯塔莫斯饰)唯一的儿子亚当(卡梅隆•布莱特饰)在车祸中身亡。痛失爱子的夫妇俩仿佛坠入了生命的深渊，但是古怪的医生查德•威尔斯(罗伯特•德尼罗饰)走到他们面前，告诉他们可以帮助他们重新与儿子团聚时，他们看见了救命稻草。于是克隆亚当的计划产生了。一切都很顺利，这个新生儿果真与亚当一模一样，除了偶尔显露的邪恶。一家三口度过了幸福的8年时光，到了之前亚当死亡的第九年到来时，问题出现了，亚当真正的生命是在8岁截断的，这个克隆人没有样本可以依照，不可预计的问题出现了。人们总要为自己的选择付出代价。','When a miracle becomes a nightmare, evil is born.',25000000,30114487,12.10235,4.7,114,102,'2004-04-30','en','/lLncs8FEzKupj19wCqZ3sPmg3eU.jpg',2.834428054296131,3,'2026-09-10',2,NULL,NULL),(11062,'市政厅','City Hall','纽约市市长约翰（阿尔·帕西诺 Al Pacino 饰）为人成熟老练，处事圆滑，是政坛当中的一把好手。副市长凯文（约翰·库萨克 John Cusack 饰）尽管资历尚欠，但凭借着一腔热血和年轻气盛，亦将自己的事业经营得风生水起，在这一老一少两人的完美配合之下，纽约这座繁华的城市每日都显得如此生机勃勃。  　　某日，发生了一起意外事件。在警方和毒贩的交火中，一名无辜的黑人男孩不幸中弹丧生。这起敏感的事件在城市里掀起了轩然大波，各路媒体争相报道，支持和反对的声音层出不穷，各占风头。凯文决心调查这起事故的真相，却发现其中的种种黑幕和约翰有着千丝万缕的关联。','It started with a shootout on a rainswept street and ended in a scandal that shattered New York.',0,0,3.621837,6,67,111,'1996-02-16','en','/qOBpLHdt8PRRVImmBvYYzGLuCe8.jpg',2.7554643015868936,3,'2026-09-10',2,NULL,NULL),(11065,'千方百计','O','Hot young stars, a hip, driving soundtrack, plus a provocative tale of jealousy and betrayal combine to create this controversial modern-day version of Shakespeare\'s classic, \"Othello.\" O is Odin James (Mekhi Phifer), the school\'s star basketball player and future NBA hopeful. Even though he\'s the only black student at the elite Palmetto Grove Academy...','Trust. Seduction. Betrayal.',0,16017403,4.146752,5.8,75,95,'2001-08-31','en','/6zcnbgNm4Es96sfsgoUavqbAed9.jpg',2.7749066197158014,3,'2026-09-10',2,NULL,NULL),(11066,'情场杀手','Boomerang','担当某广告公司主管职务的马科尔斯（Eddie Murphy 艾迪•墨菲 饰）是一位英俊潇洒、事业爱情双得意的黑人男子。他的风度翩翩和温文尔雅是无数妙龄女郎投怀送抱，也正因为如此，马科尔斯与每位女郎的爱情犹如暴风骤雨一般来的激烈，却很快无影无踪。','A Player Who\'s About to be Played.',40000000,70100000,6.420434,5.4,134,117,'1992-06-30','en','/bIO0uVK8YABHJ2SMIu19wlnQxLm.jpg',2.8803983958460027,3,'2026-09-10',2,NULL,NULL),(11072,'Blazing Saddles','Blazing Saddles','A town – where everyone seems to be named Johnson – is in the way of the railroad and, in order to grab their land, Hedley Lemar, a politically connected nasty person, sends in his henchmen to make the town unlivable. After the sheriff is killed, the town demands a new sheriff from the Governor, so Hedley convinces him to send the town the first black sheriff in the west.','Never give a saga an even break!',2600000,119500000,22.793929,7.2,609,93,'1974-02-07','en','/vNw1gOEDdYTDeNMuuq8OmiEHrfH.jpg',3.4270565758405236,3,'2026-09-10',2,NULL,NULL),(11086,'电影人生','The Majestic','1951年好莱坞，一切带有左翼观点的电影都深受“麦卡锡事件”影响，被列入所谓的黑名单中，众多无辜的电影人被迫害。刚入行的电影编剧彼得·阿普尔顿（金·凯瑞 Jim Carrey饰）本是好莱坞一位才华横溢的青年剧作家，可生不逢时的他因为一次在大学时的无心之举也被政府列入黑名 单之中。然而他的噩梦并没有结束，失业失恋的彼得在一次车祸中失去了所有的记忆。当彼得被好心人救起，带到一座名叫朗森的小镇时，小镇居民都把他误认成九年前在二战中牺牲的鲁克。而鲁克的父亲哈里（马丁·兰杜饰）更是欣喜若狂。彼得修复了哈里无心经营的电影院，也让他在电影中找到了生活的激情。鲁克原来的女友阿黛尔（劳瑞·霍尔登饰）更与彼得坠入情网。当一切都向着大团圆结局发展的时候，调查员却追踪到小镇，要求彼特立刻出庭。','Sometimes your life comes into focus one frame at a time.',72000000,37317558,11.215702,6.6,188,152,'2001-12-21','en','/4ocDDKzMguhqn25UkSCvjh4KA3W.jpg',3.027627793338956,3,'2026-09-10',2,NULL,NULL),(11090,'人面兽心','The Animal','胆小怕事、身体羸弱的马文·曼格（罗伯·施奈德 Rob Schneider 饰）却一心想成为父亲那样勇猛威武的警察，不过由于性格原因，他充其量只能在警察局证物科担当管理员。生活中他得不到任何尊重，同侪嘲笑，小孩戏弄，甚至连邻居家的狗也欺负他。  　　某天，独自在警察局值班的马文接到报警电话，可是所有警察都去球场尽情玩乐。万般无奈之下，马文独自驾车出警，却遭遇一场严重的车祸，命悬一线。危难之时，他被一个神秘之人搭救，醒来时发现自己毫发无损。然而此后马文却显露出许多动物特有的习性，原来神秘人为其移植了动物器官。马文的生活由此发生巨大转变……','He wasn\'t much of a man... Now he\'s not much of an animal!',22000000,84772742,13.786075,4.6,304,84,'2001-06-01','en','/1xDaiDyVJqlhG99jm1AvjtWDHki.jpg',2.973805805017578,3,'2026-09-10',2,NULL,NULL),(11091,'与男孩同车','Riding in Cars with Boys','Beverly（德鲁·巴里摩尔 饰）是一个怀揣作家梦的少女。她的父亲是一名警察，而男朋友Ray却是一个瘾君子。当男友得知Beverly怀了自己的孩子后，便毅然决定和她结婚。然而婚姻并不能改变Ray，他不上进，不顾家，甚至因为吸毒而花掉了本应给儿子治病的钱。Beverly再也无法忍受让这个男人来继续破坏自己和儿子的生活，于是与其分手。可年幼的儿子却并不能理解母亲的所作所为，母子间的隔阂也越来越大。  　　  然而生活的一团糟并没有击垮Beverly，当挚友Fay也离她而去之后，她仍坚持着自己最初的梦想。同时，与儿子同父亲的关系也在慢慢的改善中……','One day can make your life; one day can ruin your life. All life is is four or five big days that change everything.',48000000,35743308,7.226115,6.5,103,132,'2001-10-19','en','/1xzvRrpA9V1TxXP7kIf8d0AgJ1R.jpg',2.8732022978668383,3,'2026-09-10',2,NULL,NULL),(11093,'尘雾家园','House of Sand and Fog','被丈夫抛弃的现实凯西（詹妮弗·康纳利 Jennifer Connelly 饰）倍受打击，每一天，只有在酒精的麻醉之下，她才能抵挡内心所遭受的痛苦的煎熬。这样的凯西日渐消沉下去，对自己和周遭发生的任何事情都不再关心，直到有一天，她收到了来自地方治安官的通知，她所住的房屋即将因为欠税被公开拍卖，而凯西竟对此毫不知情。 艾米尔（本·金斯利 Ben Kingsley 饰）一家人成为了凯西的房子的新主人，当他们怀揣着对未来的美好憧憬准备入住之时，面前出现的却是一个暴怒而又神经质的疯癫女人。一个人为了保护自己的家庭，一个人为了保护自己的回忆，当这两个人站在对立面之时，善恶已经无法再被明确的分辨，只知道，悲剧近在眼前。','Some dreams can\'t be shared.',16500000,16942795,12.102725,7,199,126,'2003-12-19','en','/hLxSOukLfC4j5pNbdE7lqaw8KgL.jpg',3.0690650650646667,3,'2026-09-10',2,NULL,NULL),(11096,'捉迷藏','Hide and Seek','当大卫(罗伯特·德尼罗饰)的妻子睡前对他说\"有些事情是无法挽回的\"的时候，他还不是特别留意，因为他们最近的关系一直比较紧张。直到凌晨两点六分突然被梦惊醒后发现妻子没有躺在自己的身边，最后大卫发现浴室里有烛光——她已经在浴缸里自杀了。这血淋淋的一幕也被自己的女儿艾米莉(达科塔·范宁饰)看见了。 　　为了摆脱这种痛苦，特别是对艾米莉心灵的伤害。大卫把家搬到纽约北部的一个被森林环绕、人烟稀少的名叫伍德兰的小镇。他希望能让艾米莉在这里慢慢恢复过来。而且他也努力让自己做一个好父亲，尽量让艾米莉过得和以前一样。','Come out, come out, whatever you are.',25000000,122644820,18.228538,6.1,440,101,'2005-01-27','en','/3ZGonOtS3wK3P8xmrVOYx2YaCRs.jpg',3.196214901562005,3,'2026-09-10',2,NULL,NULL),(11109,'Vera Drake','Vera Drake','Abortionist Vera Drake finds her beliefs and practices clash with the mores of 1950s Britain – a conflict that leads to tragedy for her family.','Wife. Mother. Criminal.',11000000,0,4.131918,6.8,80,125,'2004-10-22','en','/556fElboCLlEmP8UULaYosU45Bc.jpg',2.8178697246393365,3,'2026-09-10',2,NULL,NULL),(11113,'窈窕淑女','My Fair Lady','一位傲慢的语音学教授接受了一个赌约：将粗俗的卖花姑娘伊莱莎·杜利特尔打造成能在上流社会立足的窈窕淑女。','The loverliest motion picture of them all!',17000000,72070731,20.786616,7.4,352,170,'1964-10-21','en','/eQBCFtzD9IV24KZ7b8Apfr7pdnR.jpg',3.2809786508774272,3,'2026-09-10',2,NULL,NULL),(11128,'烈火雄心','Ladder 49','身为消防队的队长，麦克尔（约翰·特拉沃尔塔 John Travolta 饰）无疑是队员们心目中的精神领袖，在他的领导下，队员们一次又一次出色的完成了火警出警任务。麦克尔的门下有许多优秀的“徒弟”，其中要数杰克（杰昆·菲尼克斯 Joaquin Phoenix 饰）最令他自豪。对于麦克尔来说，正直勇敢的杰克正是他希望寻找到的接班人。  　　可是，杰克也有自己的烦心事，繁忙而又危险的工作让他和妻子之间的感情出现了问题，与此同时，同事兼好友的意外牺牲也让杰克开始考虑是否应该换一份工作。就在这个节骨眼上，又一场大火燃烧了起来，不同的是，这一次的杰克并非施救者，而是等待获救的被困者。面对着汹涌恐怖的火焰，看着同火灾奋勇斗争的同行们，杰克找到了生命的意义。','Their greatest challenge lies in rescuing one of their own',60000000,74541707,10.99991,6.2,207,115,'2004-10-01','en','/aJWQNUUHVcI7kvlVdUzPS9J8XHt.jpg',3.0237416688818533,3,'2026-09-10',2,NULL,NULL),(11129,'周末狂欢','Human Traffic','90年代的卡迪夫俱乐部场景：五个最好的朋友在周末期间处理他们的关系和个人困扰。吉普自称为性偏执狂，害怕自己阳痿。吉普的伙伴露露对男人没有太多兴趣。妮娜讨厌她在快餐店的工作，她的男人库普梦想成为一名伟大的嘻哈音乐DJ，容易出现无端的嫉妒。第五个人是莫夫，他的家人对他的行为不满。从星期五下午开始，准备参加俱乐部活动，我们跟随这五个人从嗨药带来的乐趣，到周六清晨酒精带来的宿醉，再到周末的余波。至少有三个人迎来了突破。','The Weekend has Landed!',600000,4000000,4.859873,6.8,97,99,'1999-06-04','en','/cHwnYGZh1fVuVWqT28GpCN0usYF.jpg',2.8647298798112466,3,'2026-09-10',2,NULL,NULL),(11130,'公主日记2','The Princess Diaries 2: Royal Engagement','公主米亚大学毕业后再次回到了吉诺维亚。公主的到来轰动了全国，米亚也为此十分兴奋。可是，在一次皇家听证会上，大法官宣布公主必须成婚了才能继承王位。米亚必须在30天内订婚，否则她就不得不让出王位。王后只好与助手们匆忙地帮米亚挑选夫婿。几经选择，米亚终于跟一个年轻帅气的贵族男子订婚。与她争夺王位的年轻男孩尼可拉斯跟米亚之间却有了说不出的情愫，男孩的姨丈想让尼可拉斯勾引米亚，让她在一个月内无法完婚，两个年轻人之间却产生了真感情。','It can take a lifetime to find true love; she\'s got 30 days!',40000000,95149435,30.002907,6,697,113,'2004-08-06','en','/7igea33Kmb1CIWZ1tDywplBfwub.jpg',3.307723894118319,3,'2026-09-10',2,NULL,NULL),(11132,'青春舞会皇后','Confessions of a Teenage Drama Queen','青春飞扬，满怀梦想，渴望成为所有人目光的焦点，罗拉•赛普(琳赛•罗翰 饰)就是这样一个金光闪闪的女孩。她生在纽约，迷恋纽约街头繁华的喧嚣，却不得不随着父母搬家到一个叫做新泽西的一个小城镇。对于这一变化，罗拉虽然很不开心，但乐观的她还是接受了新的环境，并打算在新的校园赢得大家的欣赏。  　　然而，女孩子之间的争夺似乎是永远无法避免的。学校现任校花卡拉-珊蒂妮可不会轻易把“高校天后”的宝座让给罗拉。一个青春无敌，灵气逼人；一个高傲美艳，不择手段，究竟，哪个能最终获胜？  　　拥有快乐，哪里都是纽约，记得，要心中拥有梦想。','She\'s making a scene over everything.',15000000,29331068,7.424798,5.1,221,89,'2004-02-17','en','/nQA9Ozh9ftLQyJvuKy6sl5zSlH2.jpg',2.953206797306457,3,'2026-09-10',2,NULL,NULL),(11137,'王子与我','The Prince & Me','又一部讲述灰姑娘故事的爱情轻喜剧电影。这回的女主角叫佩吉（朱莉娅·斯黛尔斯 Julia Stiles 饰），同样有着朴实的家境、美丽的容貌和渴望真命天子快点出现的萌动春心。她遇上了一个叫艾迪（卢克·梅伯利 Luke Mably 饰）的小伙子，他来自丹麦王室，前来寻找印象中的狂野的美国大学生活。二人因误会相识，从冰火不容慢慢变得言语投契，相互扶持，感情日渐深厚。佩吉更是邀请艾迪前来家乡过田园生活，爱情在鸟语花香中生根发芽。 然而，艾迪身为丹麦王子，和佩吉这个美国平民丫头终究身份悬殊。当佩吉好不容易进入了丹麦皇室，准备和王子长相厮守时，皇宫的繁文缛节却让她十分不适。佩吉再三考虑，决定和艾迪道别，回到美国继续念书。灰姑娘和王子难道注定属于不同的世界？','Finding your inner princess can be such a royal pain.',0,0,17.943945,5.9,278,111,'2004-03-28','en','/1rdb6Cr5VuLzW9ha2INswhpgmln.jpg',3.079953777023311,3,'2026-09-10',2,NULL,NULL),(11141,'吸引法则','Laws of Attraction','同是离婚律师的丹尼尔•拉弗提（皮尔斯•布鲁斯南 饰）和奥黛丽•伍斯（朱丽安•摩尔 饰）都是同行中的佼佼者，两人经常在法庭上针锋相对。本来各自过着自己生活的两人，因为一件备受关注的离婚案件，又成为了对手。\r 他们各自为摇滚歌手贾米森（迈克尔•辛 饰）与设计师塞丽娜（帕克•波西 饰）离婚案件的律师，夫妻俩为一座爱尔兰堡垒的归属问题争持不下。为了得到更多的资料，丹尼尔与奥黛丽斗到了爱尔兰收集证据。怎料两人在当地节日狂欢后发生了关系，但他们仍需回到美国处理各自客户的离婚案件，就是说他们将再一次对簿公堂。','Love always has the last word.',28000000,30016165,6.201404,5.6,104,90,'2004-04-04','en','/6aqR0xwmK0mPOIVShDlT88Vo5W0.jpg',2.839329402189696,3,'2026-09-10',2,NULL,NULL),(11152,'恐怖废墟','The Ruins','杰夫（Jonathan Tucker 饰）和艾米（Jena Malone 饰）、艾瑞克（Shawn Ashmore 饰）和斯黛西（Laura Ramsey 饰）这两对从美国来到墨西哥的小情侣，正准备享受他们难得的假期。他们在泳池邂逅了来自德国的马蒂亚斯（Joe Anderson 饰）及其希腊朋友迪米特里（Dimitri Baveas 饰）。马蒂亚斯此行为了寻找其失踪的弟弟，他邀请艾米等人一同前往。无所顾忌的青年们一心追求刺激，欣然同意。他们租车来到墨西哥一片荒凉所在，在当地神秘而古老的废墟中，无尽的恐怖正悄悄向他们逼近……','Terror has evolved.',8000000,0,13.715715,5.6,265,91,'2008-04-02','en','/6HpicbiT7xmlMjQXOSCeNoLZGpf.jpg',3.0365307656524996,3,'2026-09-10',2,NULL,NULL),(11153,'假期历险记','National Lampoon\'s Vacation','克拉克·古瑞斯伍德一家的旅游假期开始了。从置换店里置换出一辆金属加绿色的运动箱式货车，收拾好行李，交代好邻居，克拉克开车，带着妻子艾伦、儿子拉斯蒂、女儿奥德瑞，向旅游假期的目的地——洛杉矶市华利大世界出发。驶出芝加哥，奔驰在高速路上，克拉克一家欢歌笑语，充满 对华利大世界无限的美好向往。  　　途经圣路易斯市，克拉克一家的旅游假期就开始出现麻烦。加油找不到油箱，问路遭地痞流氓打劫，好在有惊无险。入住旅店，不顾旅途疲劳，想要与妻子重温旧梦，美好的旧梦却被不谙世事的孩子搅黄。天亮起来，克拉克采纳了妻子的意见，开车来到艾伦的表姐家。乡下虽然没有都市繁华，但乡村的田园风光景色宜人。慷慨解囊，接济完凯瑟琳表姐一家，克拉克的旅游假期多了两个“客人”：怪异的艾德娜姑妈和见谁咬谁裤腿的一条狗。  　　从出发开始算起，出门两天来的路上，克拉克一家的旅游假期就被接踵而来的麻烦和烦恼所困绕，艾德娜姑妈和见谁咬谁的狗更成麻烦和烦恼的直接制造者。告别凯瑟琳表姐，克拉克继续开车上路。由于克拉克的疏忽，拴在汽车后保险杠的狗被活活脱死，得到警察的原谅，再着车出发，艾德娜姑妈什么时候死去，谁也不知道。  　　将姑妈的尸体用毛毯裹起来绑在车顶上，克拉克冒雨驾车，来到姑妈的儿子诺米家。恰好诺米外出，克拉克放下姑妈的尸体，敷衍了事地一番祷告后，重新上路。没有了讨厌的狗和怪异的姑妈，旅游假期重新找回最初的感觉。一路蓝天、白云、青山、绿水做伴，克拉克一家来到科罗拉州，面临沙漠迷路、身无分纹的窘迫。  　　现金没有，支票不能兑现，却挡不住克拉克对妖艳金发女郎的垂涎。洋相百出、丢人现眼之后，克拉克度过危机，驱车来到加利弗尼亚。洛杉矶就在眼前，华利大世界就在眼前。然而，麻烦一路、辛苦一路换来的结果是：华利大世界因故停止营业两周。克拉克没有因此而放弃，持“枪”挟持保安，强行游园后，得到华利大世界老板华利先生的原谅，在兴师动众的警察面前，畅游华利大世界，继续欢乐的假期。','Every summer Chevy Chase takes his family on a little trip. This year he went too far.',15000000,61399552,22.838834,7.1,410,98,'1983-07-28','en','/q3DvoqY06yZnRp9faH6uge7n7VP.jpg',3.2995529781147983,3,'2026-09-10',2,NULL,NULL),(11156,'时尚先锋香奈儿','Coco avant Chanel','1893年，因母亲去世，加布里埃尔•香奈儿的葡萄酒商父亲将她与妹妹安托妮特抛给了奥巴兹孤儿院。成年后的香奈儿（奥黛丽•塔图 Audrey Tautou 饰）与安托妮特（玛丽•吉莲 Marie Gillain 饰）一边以缝纫为生，一边在酒吧唱歌赚钱。香奈儿因一曲《小狗可可》结识了法国百万富翁艾亭奈•巴桑（贝诺特•波维德 Benoît Poelvoorde 饰），并成为了他众多情妇中的一员。在巴桑的城堡，香奈儿开始制作女帽，并与演员艾米丽安（艾曼纽•德芙 Emmanuelle Devos）成为朋友。香奈儿对取悦巴桑的生活日益不满，同时发现爱上了巴桑的好友，英国工业家阿瑟•伯邑•卡伯（亚历桑德罗•尼沃拉 Alessandro Nivola 饰）。有了伯邑的支持，香奈儿是否便能开始她一直想要的个人事业呢？\r 　　本片被提名2009年欧洲电影奖观众奖。','Before she was France\'s famous mademoiselle...',0,0,8.426589,6.6,246,110,'2009-04-22','fr','/gU2UFzMAPLGwYN5iuOWpucyQlZY.jpg',3.0862922442284817,3,'2026-09-10',2,NULL,NULL),(11162,'威尼斯商人','The Merchant of Venice','年轻人巴萨尼奥（约瑟夫·费因斯 Joseph Fiennes饰）一心要向富商千金鲍西娅小姐（琳恩·柯林斯 Lynn Collins饰）求婚，为了这个愿望，他必须付出三千达克特，无奈中他只好向热心肠的商人安东尼奥（杰里米·艾恩斯 Jeremy Irons饰）借钱。碰巧的是，安东尼奥因为生意周转的问题，只能问犹太人夏洛克（阿尔·帕西诺 Al Pacino饰）借来这笔钱。  　　安东尼奥对犹太人历来抱有强烈的厌恶感，而夏洛克则提出了让人吃惊的要求：安东尼奥必须如期如数的归还这笔钱，否则，他将会切下安东尼奥身上的一磅肉。  　　巴萨尼奥终于如愿以偿的娶回了鲍西娅，安东尼奥却因为生意失败，在夏洛克的讨债中陷入困境。夏洛克还要趁这个机会，一雪安东尼奥对犹太人侮辱之耻。安东尼奥那一磅肉，看来非割不可了，聪明的鲍西娅却用绝妙一招，化险为夷。',NULL,0,0,12.467267,6.7,144,138,'2004-09-03','en','/w9tTZPYXwxemwbrTokboBRwxLGH.jpg',2.9720298788139106,3,'2026-09-10',2,NULL,NULL),(11165,'虎！虎！虎！','Tora! Tora! Tora!','这是一部真实的电影，真实展现了日军偷袭珍珠港的历史。美军插手太平洋战场，日军最高将领山本五十六认为美军实力强大，应速战速战，不宜和美国人打长久战。于是，由他一手策划的偷袭珍珠港行动正式启动了。虽然美军从此前截获的日军密电中得知了日军可能进行突袭的消息，但多数人都对此不屑一顾，密电的内容也没进行上报。即使在突袭当天美军一个士兵发现了雷达上不寻常的飞机群，美军将领仍然认为那是自己的飞机在执行巡逻任务。最终使得日军偷袭行动一举成功，美军损失惨重。山本五十六也成了美国人最大的眼中钉。','The incredible attack on Pearl Harbor.',25485000,29548291,9.795985,6.9,147,144,'1970-01-26','en','/juRP7uqB3Q1C9asNGD071LhufX9.jpg',2.980954250070253,3,'2026-09-10',2,NULL,NULL),(11170,'后继有人','We Are Marshall','本片讲述了一个发生在西弗吉尼亚亨廷顿小镇上的一个真实的故事，小镇上橄榄球传统历史悠久。几十年来，运动员、教练员、 球迷们和他们的家人们一起为马歇尔大学的球队加油助威。在当地，橄榄球已经不仅仅是一项运动，而为马歇尔大学橄榄球队加油已经成了人们的生活方式。但是1970年发生的那场事故改变了这一切。11月14日夜晚，马歇尔大学橄榄球队的教练和队员们从北卡罗来那比赛后乘机返回亨廷顿，结果飞机失事，75人全部罹难。这一重大损失给所有人的打击是无法弥补的。正当所有人都沉浸在悲伤之中而一蹶不振的时候，马歇尔大学Thundering Herd橄榄球队的年轻教练Jack Lengyel(Matthew McConaughey)却决定重新建立球队。虽然起初不被人看好，也经历了四处寻找球员的波折，但是在球队幸存者Red Dawson(Matthew Fox)的帮助下，一切似乎也并非不可能。渐渐地，小镇居民的态度也有所转变……','From the ashes we rose.',65000000,43545364,8.629665,6.7,186,124,'2006-12-12','en','/imCyZwYb6CLGkQvaXxk2iJVlrjL.jpg',3.0252586412511517,3,'2026-09-10',2,NULL,NULL),(11172,'K歌情人','Music and Lyrics','阿莱克斯(休•格兰特 饰)是一个八十年代过气流行乐歌手，近年好不容易逐渐获得更多的演出机会，更得到流行天后Cora邀请他写歌并合唱该曲。但此刻阿莱克斯碰到了创作瓶颈，多年没有作曲之余，而且从来没有过作词的经验，现在却要在几天内作出一首畅销的流行曲。\r 　　就在阿莱克斯十分烦恼时，他遇到了苏菲（德鲁•巴里摩尔 饰），这个美丽的女孩精通运用文字，随口唱出的歌词让阿莱克斯十分满意，多次邀请苏菲才答应与阿莱克斯一起合作。但苏菲一直困在前一段失败的感情中，她害怕承诺。当她与阿莱克斯的感情逐渐升温的时，两人却要一起面对分歧…… ©豆瓣','Share the music with someone you love.',40000000,145896422,17.659032,6.2,554,96,'2007-02-09','en','/9MLJzyeUD0KN1JpdJMdC8i9lmY.jpg',3.2575913876448093,3,'2026-09-10',2,NULL,NULL),(11176,'大青蛙布偶电影','The Muppet Movie','\"【大青蛙布偶秀】（The Muppet Show）是由 Jim Henson 以及他的團隊於１９７６年在美推出的電視節目，這個載歌載舞的綜藝節目，深受全美兒童的喜愛，後來更推出了好幾部電影，第一部推出的就是在１９７９年所推出的【大青蛙布偶電影】（The Muppet Movie），這也成為影史上第一部由布偶結合真人所共同主演的電影。迪士尼公司於２００４年２月買下了 Jim Henson 《布偶系列》的所有作品版權，因此如今本片也成為迪士尼旗下的作品了。\r 【大青蛙布偶電影】是布偶秀明星們初次登上大銀幕的作品，也是一部跟電視節目同樣型態的歌舞類作品。本片的故事的主角大青蛙 Kermit 想出名想瘋了，在別人的慫恿之下，決定起身西行到好萊塢一圓明星夢，在這跨越千里的旅途中，他遇上了不少好朋友，包括豬小妹  Miss Piggy 、小熊 Fozzie 、Gonzo …等等，大家都跟隨 Kermit 要前往好萊塢實現夢想，但是這時候卻有一位心懷不軌的 Doc Hopper ，想要把 Kermit 騙去當他連鎖餐廳的代言人，到底布偶們能不能克服難關呢？\r 本片是由 James Frawley 執導，由 Jack Burns 和 Jerry Juhl 共同擔任編劇，片中擔任布偶配音的都是原來【大青蛙布偶秀】電視節目的配音者，其中本系列的創始人 Jim Henson 在電影中更是一人擔任包括主角 Kermit 等七、八個角色，其他配音者還包括有  Frank Oz 、Richard Hunt 、Jerry Nelson 、Dave Goelz …等等，而片中由真人主演的反派 Doc Hopper 則是由 Charles Durning 所飾演。本片的配樂以及片中歌曲的作曲是由 Paul Williams 負責，至於幫歌曲作詞的則是 Kenny Ascher ，本片的配樂和歌曲“The Rainbow Connection”還獲得該年奧斯卡金像獎的題名，本片的電影原聲帶則已經絕版多年，目前在美國二手市場叫價不斐。\"','More entertaining than humanly possible.',0,76657000,10.639916,7,164,97,'1979-05-31','en','/4128JP0zXaoCMAloie632bIJGLh.jpg',3.0157502545205013,3,'2026-09-10',2,NULL,NULL),(11184,'金赛性学教授','Kinsey','美国印第安纳大学的教授阿尔弗莱德·金赛在1939年发表了震惊世界的《金赛性学报告》，这部迄今为止最为完整和坦率的性生态学调查的学术基础，是面谈了12000名美国人的惊人工作量。在金赛（连姆·尼森 Liam Neeson 饰）对学生们的访谈培训中，他一生的故事娓娓道来……\r 金赛出生在一个由父亲强力掌控的家庭，热爱自然的金赛在青年时终于摆脱了父亲钳制，选择了心仪的生物学研究，在大学任教时，金赛与研究生麦克米兰（劳拉·琳妮 Laura Linney 饰）结为伉俪。婚后他继续着自己的瘿峰研究，然而在与学生的接触中，他发现道德教条造成的性困惑无处不在，于是开始调整自己的研究方向…… ©豆瓣','Let\'s talk about sex',0,0,6.799314,6.6,131,118,'2004-09-04','en','/wD43t0nvpR6UY7baL5jEQ7gUefU.jpg',2.9318877673915034,3,'2026-09-10',2,NULL,NULL),(11186,'鬼娃回魂2','Child\'s Play 2','公仔杀人事件经媒体报道后，引发制作“楚其”的玩具公司对市场前景的担忧，玩具公司将楚其的残骸收回并加以修复，试图向股东证明杀人玩具不过是谣言一场，然而在修复完成时，楚其随即复活，它引发混乱，并最终逃脱。另一方面，安迪（艾力克斯·文森特 Alex Vincent 饰）和母亲分别接受心理治疗，一对好心夫妇暂时照顾安迪。根据灵魂转移的符咒要求，楚其如果要避免与公仔一同人格化的命运，就必须寄宿到第一个知晓它秘密的人——也就是安迪身上，楚其剩下的时间已经不多，它再度找到安迪准备侵占其身体。安迪为了躲避找上门的楚其，用尽办法得到的却是周围大人的不理解与训斥，和安迪一起被收养的少女凯莉也卷入了这场公仔夺取安迪身体的非常事件……','Look out Jack! Chucky\'s back!',13000000,35763605,16.681567,5.8,308,84,'1990-11-09','en','/x1B2hR5oEvffd8B86Io0kGZ3qDw.jpg',3.088995934691863,3,'2026-09-10',2,NULL,NULL),(11190,'回归','Возвращение','在当代俄罗斯，年幼的兄弟伊凡和安德烈因自幼丧父而相依为命，彼此间建立了深厚的情感联结。当失踪十二年的父亲突然归来时，他们倍感震惊。带着母亲不安的祝福，伊凡和安德烈与沉默寡言的父亲踏上了一段他们原以为是钓鱼假期的旅程。[Kino International]',NULL,0,0,7.744166,7.4,100,105,'2003-06-25','ru',NULL,2.90025267841213,3,'2026-09-10',2,NULL,NULL),(11191,'现代灰姑娘','Mystic Pizza','三个在「神奇披萨屋」打工的女孩：黛丝幻想嫁个金龟婿，却碰上玩世不恭的公子哥；凯为赚取学费去当保姆，竟然爱上已婚的男主人；娇娇只想谈情做爱，惹脑了急想结婚的男友掉头而去。她们的故事，要如何结局？传统的成长故事，却有反传统的叙事守法，三对恋人是所有青少年的缩影，编导用心关怀及创新的诚意处处可见，没有老掉牙的道德教诲，看来贴心，大呼过瘾。在海和沙漠之间，棕榈树下的村庄里，莉移动成熟亮丽的皮肤，散发著迷人诱惑、令人动情的身躯。亚菲德是莉的夥伴，在油田工作跟莉生活在一起，他们好像是完美的一对，令人羡慕。然而有个人在身后按地里一步步的跟踪她……','A Romantic Comedy With The Works',0,0,6.379933,5.9,123,104,'1988-10-13','en','/2wqMKLJEMjenT7U8UqnuI070cUC.jpg',2.8858520695817713,3,'2026-09-10',2,NULL,NULL),(11194,'冰峰168小时','Touching the Void','本片跟随登山者乔·辛普森与西蒙·耶茨，记录他们前往秘鲁安第斯山脉挑战修拉格兰德峰西坡的攀登历程。',NULL,0,13885802,14.045887,7.6,138,106,'2003-09-05','en','/fsydA5H8FSDaYlYWddfMpMpDUX.jpg',3.008444306282502,3,'2026-09-10',2,NULL,NULL),(11199,'荒野大飚客','Wild Hogs','四位人到中年的“大叔”道格·玛德森(蒂姆·艾伦)、伍迪·斯蒂文斯(约翰·特拉沃尔塔)、波比·戴维斯(马丁·劳伦斯)和杜德雷·弗兰克(威廉·H·梅西)在最近似乎都面临着各种危机。而且有着很大的相似性——工作上时常遇到各种困难和尴尬，家庭中更是由于沟通的不善而经常被误解。疑似神经衰弱的四个大佬一天突发奇想，决定穿上皮衣、围上头巾、骑上排量超大的“哈雷”摩托车上路，前往新墨西哥州的广阔戈壁游玩观光，好能让自己重新找回对生活的热情。然而一直循规蹈矩的他们从没驾驶过摩托车，在学了几天之后四位大叔开着铁马上路历险，一路上状况百出，遇到美女勇于追求，遇到对手勇于对抗，在磕磕碰碰的逍遥游中，四人开始走出生活的压力，在看清自己的同时更重新找到了对生活的热情……','A lot can happen on the road to nowhere.',0,253625427,31.719463,5.6,648,100,'2007-03-02','en','/G11RAJO7UVJf5YiA66Dhm5NE2O.jpg',3.2399600988370985,3,'2026-09-10',2,NULL,NULL),(11202,'巴顿将军','Patton','这部荣获奥斯卡奖的传记片记述了美国乔治·S·巴顿将军的战时活动与成就，时间跨度从其参与北非战役开始，直至他因公开批评美国战后军事策略而被解除指挥职务为止。','The Rebel Warrior',12000000,89800000,21.933822,7.3,323,172,'1970-01-25','en','/nM3QbKB8oIyeLY9FeOTw7vJtvyn.jpg',3.2485863065577276,3,'2026-09-10',2,NULL,NULL),(11208,'谜情公寓','Wicker Park','马修（乔什•哈奈特 饰）是个年轻有为的广告公司人员，与女友也到了谈婚论嫁的阶段。当他在一次生意洽谈的会晤中，他无意间听到了往日挚爱——莉萨（黛安•克鲁格 饰）的声音。那时两人正处热恋，可是莉萨无端在他的生活中消失了。而一直以来，马修都无法忘记莉萨。  　　他正怀疑那名女子正是莉萨，他决定要留下来寻找这名女子，因为他在电话亭里发现了女子的住址。  　　马修进入了女子的寓所，她发现了一切属于莉萨的特征，可是出现的却是另一个人，另一个叫莉萨（萝丝•拜恩 饰）的女人。马修依然不停止寻找真正爱人的脚步，但他不知道的是他早已进入了一个圈套内…… ©豆瓣','Passion never dies.',30000000,13001257,9.301562,6.7,157,114,'2004-09-03','en','/gRKEluSpV1wBrZVTvLLaCSkzqcf.jpg',2.985603535761142,3,'2026-09-10',2,NULL,NULL),(11212,'小鬼当街','Baby\'s Day Out','比克是百万富翁卡威尔夫妇的独生儿子，长得十分地可爱聪明。当比克九个月大时，卡威尔夫妇希望他可以风光地上报，好让邻居好友认识他们的小孩，于是找来一位知名的摄影师来替比克拍婴儿照系列。这时候，艾迪、诺比和威哥这三位笨贼想要绑架比克来向卡威尔夫妇索取五百万美金，于是他们便假扮成要替比克拍照的摄影师，然后把比克给绑架走，并且叫卡威尔夫妇不得报警。可是聪明的比克不但将他们耍的团团转，还趁诺比睡著时逃走，三个笨贼在追比克的时候，被搞得伤痕累累，到最后他们非但没抓到比克，反而还被警察给捉走。','No bib. No crib. No problem.',50000000,16671505,21.312186,5.8,274,99,'1994-07-01','en','/21U2jwl36hoTHsXB3fDuIQkcchu.jpg',3.0764958858208065,3,'2026-09-10',2,NULL,NULL),(11217,'恐怖俱乐部','Club Dread','When a serial killer interrupts the fun at the swanky Coconut Pete\'s Coconut Beach Resort -- a hedonistic island paradise for swingers --- it\'s up to the club\'s staff to stop the violence ... or at least hide it!','A vacation to die for',8500000,5001655,2.62082,5.1,107,104,'2004-02-27','en','/9slWyVotwxZNthMcKoeFaK3tgNz.jpg',2.8175729829072895,3,'2026-09-10',2,NULL,NULL),(11219,'怪尸案','The Trouble with Harry','小男孩哈尼在森林中漫步时，发现了他的父亲——哈利的尸体。不同于一般谋杀案，这次因为多人都自认为凶手而令案情更加扑朔迷离。亚伯特船长（埃德蒙•格温 Edmund Gwenn 饰）认为是他在打猎射击时误杀了哈利；村落里的老处女葛雷布礼小姐（麦尔翠德•耐维克 Mildred Natwick 饰）认为是因为她为了保住自己的名声而用一只鞋子打了哈利的头部而造成他的死亡；与哈利感情不睦的妻子珍妮佛（雪莉•麦克雷恩 Shirley MacLaine 饰）则认为是她因为反抗哈利的性爱用装牛奶的罐子敲向他的脑袋而造成了他的死亡。真相最后能否水落石出？','A THRILLER with a difference!',1200000,7000000,6.920873,6.9,149,99,'1955-10-03','en','/uUXLq7fEG3hI46ZFMZzgHj11S6S.jpg',2.9777497189209474,3,'2026-09-10',2,NULL,NULL),(11228,'十万火急','Daylight','这天无数往来于曼哈顿与新泽西州的海底隧道的美国民众像往常一样在隧道内抱怨着交通堵塞，岂料死神正在步步逼近。隧道内一辆装满化学物品的卡车意外发生了爆炸，强大的冲击力使得隧道坍塌了，出入口都被堵死了。此时，隧道内一片火海，弥漫着有毒烟雾，河水也在不断涌进，无数无辜的市民们能做似乎只有等死。　　救援队其实早到了，然而隧道被封，里面的有毒烟雾肆虐，救援人员迟迟不敢贸然动手。十万火急之际，出租车司机、前救援队队员骆查（西尔维斯特•史泰龙 Sylvester Stallone 饰）挺身而出了。他从通风口爬进了隧道，他稳定住了隧道内众人的情绪，带领大家开始了生死逃亡。','No air. No escape. No time.',80000000,159212469,16.681269,5.8,378,115,'1996-12-06','en','/jFurKWVfCdDwYIugucTzKpuy8Sf.jpg',3.1291655512535734,3,'2026-09-10',2,NULL,NULL),(11229,'极速惊魂','Freeway','护士简尼开着刚刚从修车部取来的车，去姐姐家接孩子到妈妈家，因为不能按时取车而又必须赶着开会的网络公司经理艾德搭乘她的车一同上路。途中，一个滑板小子撞在车前，他的滑板坏了，身体受了轻伤，于是又多了一个搭车者。途中，车子一连出瑞突然加速现象，且无法控制。以80、90迈的速度，车子象一只炮弹在公路上急驰。所有的办法都失败了，车子还是停不下来。在警方的导引下，为他们开辟了专用车道。在忠于职守的警员陪伴下，车子沿着州际公路不断飞驰。警方决定用直升机从车子的天窗救出孩子先……','Her life is no fairy tale.',3000000,0,4.682881,6.5,95,110,'1996-08-23','en','/m0pAARUq3foDWFsrUmlYDHtNPE9.jpg',2.849022767948371,3,'2026-09-10',2,NULL,NULL),(11232,'穿越时空爱上你','Kate & Leopold','凯特是一家公司的高级主管，现代新女性的典范，非她莫属。凭着聪明才智和果断魅力，她在男性世界中轻松自在地拥有自己的一片天地。李奥是艾班尼公爵，身处19世纪末的纽约，他是一个最有价值的单身汉。两个时空相距百年的男女，唯一的共同点就是：对爱情非常非常……的挑剔！  　　但是谁也别想逃过爱神丘比特的调皮箭，就在凯特的前任男友史都华无意间发现了时光隧道，闯进了19世纪的纽约，并和他的曾曾曾祖父李奥相遇，祖孙两人携手畅游19世纪的纽约市。一个不小心遇上离奇意外，把他们一起又带回到2l世纪的纽约市，并闯入了凯特的世界中时，两个原本不该相遇的男女不但见了面而且还坠入了爱河，但是现实是残酷的，两人终究必须面对年龄差距，“老少配”是不会有结果的……凯特含泪送走了李奥。  　　凄美的爱情故事就这么完了吗?但是一切并不是所想的那么简单，爱神再次对两人开了个大玩笑，凯特发现自己竟怀了李奥的孩子，现代新女性可不是浪得虚名的，在史都华的帮助下，凯特决定跨越百年去追夫，让孩子的爸爸负起责任来。','If they lived in the same century they\'d be perfect for each other.',0,0,11.940711,6,418,118,'2001-12-25','en','/zSO6DBIIE5w3OvJotGlAHhbmqYw.jpg',3.1598469343487046,3,'2026-09-10',2,NULL,NULL),(11237,'狂蟒之灾2：搜寻血兰','Anacondas: The Hunt for the Blood Orchid','位于婆罗洲的原始丛林中，比尔·约翰逊带领着他的探险小队穿行于其中，寻找着一种名为“血兰”的珍稀植物。在记载中，血兰拥有着能够使人长生不老的神秘力量，“几乎从未有人获得过它”的传闻也令血兰逐渐成为了传说。这一次，受一家著名的医药公司所托，比尔一行人决定揭开血兰的神秘面纱。在离目标越来越近的同时，危险也不期而至。血兰的力量没有使人类返老还童，却将一群蛇类变得凶猛而恐怖，为了挪动巨大的身体，它们不得不吃下比以往多达数倍的食物，而此时冒昧来访的人类，成为了它们最好的猎物。一边是丛林中恶劣的生态环境，一边是穷凶极恶的食人恶兽，同伴们一个接着一个的悲惨死去，比尔最终能够自保，并且挽救更多的生命。',NULL,20000000,70992898,9.855474,4.9,199,97,'2004-08-26','en','/6IAOS6QkMgRlNMF1LvVVQrRVM5X.jpg',2.92875194294912,3,'2026-09-10',2,NULL,NULL),(11240,'我美丽的洗衣店','My Beautiful Laundrette','故事发生在人流汹涌的大都市伦敦。奥玛尼萨（Gordon Warnecke 饰）是一位英俊帅气的巴基斯坦青年，在叔父的帮助下开了一间小小的洗衣店，以此为生。叔父十分满意奥玛尼萨的勤恳和老实，觉得他是个可靠的男人，于是开始帮他张罗起了娶妻事宜，当然，在叔父的内心里，自己的女儿是成为奥玛尼萨妻子的最佳人选。  　　强尼（丹尼尔·戴-刘易斯 Daniel Day Lewis 饰）是奥玛尼萨的大学同学，得知好友正在经营洗衣店，强尼主动请缨前来帮忙。和奥玛尼萨不同，强尼个性张扬桀骜不驯，但奇怪的是，这两个男人凑在一起，还颇为投缘。随着时间的推移，一种超越了友谊的感情在他们之间诞生了。 ©豆瓣',NULL,860000,2451545,3.703005,6.6,51,97,'1985-09-07','en','/hfGWxrtbRnxg19ouEYBtQKtMZcN.jpg',2.7098098186575124,3,'2026-09-10',2,NULL,NULL),(11247,'灰姑娘的故事','A Cinderella Story','一个现代版的灰姑娘故事。珊曼（希拉里·达芙 Hilary Duff饰）在父亲的童话故事中长大，不料却成为了童话中的灰姑娘。父亲过世后，继母和同父异母姊妹的侮辱和亏待，令她的日子过得苦不堪言。她想考取普林斯顿大学，想逃离这个龌龊的小世界，珊曼把她的梦想和苦恼都诉说给一个亲密的网友，他是她心灵的依托，是她的白马王子。　　万圣节的相见摧毁了吉娜的梦。眼前的网友，竟然是学校里有名的帅哥运动员奥斯汀（查德·迈克尔·墨瑞 Chad Michael Murray饰）。一个是平凡黯淡的女孩，一个是闪亮耀目的男生。幸好吉娜乔装打扮，没被人奥斯汀认出。二人如此不登对，心虚的吉娜落荒而逃，不小心遗下一部手机。　　就像玻璃鞋被王子拣到之后的故事，奥斯丁拿着手机寻找自己的灰姑娘，而吉娜，却无法相信自己怎会像灰姑娘般幸运。于是这出爱情故事，注定充满曲折而窝心的波澜起伏。','Once upon a time... can happen any time.',19000000,70067909,25.28132,6.1,713,95,'2004-07-10','en','/yGMlLmzrnp7dJaRChgcimmOzqPh.jpg',3.3165080533989855,3,'2026-09-10',2,NULL,NULL),(11249,'鬼娃回魂5：鬼娃孽种','Seed of Chucky','杀人玩偶又回来了！自1998年鬼娃恰奇和鬼娃新娘做完爱做的事后，时间眨眼就过去了6年，鬼娃新娘临死前产下的鬼宝宝——小鬼娃格伦——也成长为大男孩了。孤儿小鬼娃格伦继承了他父母的凶残本性，这也难怪，谁叫他有残忍凶暴的鬼娃老爸恰奇，和同样凶残可怕的鬼娃新娘妈妈蒂芬妮呢。  最近，孤儿小鬼娃听说好莱坞要开拍一部恐怖电影，且是以他死去的父母为主角。小鬼娃顿觉这是个非常好的机会，使饱受孤儿之苦的他，希望能够把死去的父母救活，自己好有一个幸福的家。  就在小鬼娃到达好莱坞的同时，一个年轻的女孩抱着明星梦也踏进了这个梦的城市，她应征了女星“珍妮佛·蒂莉”的私人助理一职。“珍妮佛·蒂莉”即是鬼娃夫妇恐怖片的女主角，她将饰演鬼娃新娘蒂芬妮。  格伦在去好莱坞的路上已经充分展示了他暴戾的天性，大开杀戒了。他经过百般努力找到了父母的尸体，用魔咒救活了他们。复活后的鬼娃夫妇，为突然得到儿子而兴奋不已，鬼娃决定父子联手扫荡好莱坞。而格伦虽然遗传了父亲的残暴，但性格中却有温情的一面，他不愿象父亲那样动辄杀人。鬼娃新娘蒂芬妮怎么也想不到影片是由她最喜欢的女星珍妮佛·蒂莉来主演，喜欢追星的蒂芬妮也不想儿子再走上杀人之路，她与丈夫在儿子的前途问题上产生了分歧，还牵涉到许多无辜的人丧命。鬼娃一家三口人就在吵吵闹闹中将好莱坞搅了个天翻地覆，而一幕幕的血腥事件也就此展开……','Fear The Second Coming',12000000,24829644,12.653831,4.9,287,87,'2004-11-11','en','/34z4UZgtP85TQzHzEqNubc9p1IN.jpg',2.98956346075552,3,'2026-09-10',2,NULL,NULL),(11253,'地狱男爵2：黄金军团','Hellboy II: The Golden Army','这部续集讲述了地狱与人间的休战协定被破坏，一股在地狱深处酝酿已久的邪魔力量冲出地底，残酷的弩亚达王子妄图用地狱的火焚烧人间，被他的血唤醒的魔兽疯狂已难以抑制；地狱男爵重新出山，与“超自然研究发展局”的盟友一同抵御这场危及人类命运的灾难。《地狱男爵》系列一直以有标志性意义的惊险动作场面、用角色做基础的壮丽景观标榜自己，然后融合了一个世界上最坚毅、最热爱生命、来自于地狱的战士，书写出了一段让人目瞪口呆的传奇故事……如今到了第二集故事，观众将会看到更大块的肌肉展示、更猛烈先进的武器、更邪恶的反派、数量更多的怪物，再加上一些不可避免的自己人内部的小冲突，都在曾获得过奥斯卡提名的导演吉尔莫·德尔·托罗的想象力中变成一个像史诗般宏大的画面。人类与地狱之间，一直存在着一个古老的休战协定，有效地限制了那些存在于无形的领域中的奇幻世界染指人间的可能性，然而，不知何故，休战协定突然作废，这也使得来自于地狱的邪恶随时会喷涌而出。无法无天的地狱王子弩阿达早就已经厌倦了地下世界几个世纪以来对人类的顺从和尊重，他计划着趁此机会唤醒一支由杀人机器组成的军队，并让其臣服在自己的脚下，听候他的差遣，一旦他达成所愿，所有拥有魔力的生物最终都将获得自由行动的权利……弩阿达还有一个双胞胎姐妹，相较于他残忍无情的复仇欲望，弩阿拉公主却是在用永无止境的大爱来对待人类。作为地下世界的领导者，弩阿达王子的不计后果已经到达了一种疯狂的地步，现在，是时候让这个世界上最粗枝大叶的超级英雄“地狱男爵”登场了，也许，他的皮肤是红色的，你甚至会质疑他头上的犄角本来就是地狱的产物……但是，当你的生命受到不可思议的力量的威胁时，呼唤“地狱男爵”准没错，他与已经壮大了的“超自然研究发展局”的伙伴们一起－－包括他可以自由操控“火之力”以备防御的女友莉斯，以及水栖的能量感应者亚伯，还有身上充满神秘色彩的约翰，他们将合力阻止那个黑暗的统治者，从毁灭性的打击中拯救我们的世界。','Saving the world is a hell of a job.',85000000,160388063,58.57976,6.5,1527,120,'2008-07-11','en','/7J6TcP59IwXWQmaEhKMHDr7U1hI.jpg',3.6383348811504637,3,'2026-09-10',2,NULL,NULL),(11257,'看得见风景的房间','A Room with a View','由导演詹姆斯·艾沃里和制片人伊斯梅尔·莫钦特领导的莫谦特-艾弗里制片公司，凭借本片成为家喻户晓的名字，这也是他们改编E·M·福斯特小说的非凡系列中的首部作品。天使般的十九岁少女海伦娜·博纳姆·卡特饰演露西·霍尼彻奇，一位思想独立、出身爱德华时代上流阶层的年轻女子。她试图厘清自己心中萌生的浪漫情感——一边是在佛罗伦萨度假时邂逅的神秘自由灵魂（朱利安·桑兹），另一边则是回到礼教森严的萨里郡后与之订婚的迂腐书呆子（丹尼尔·戴-刘易斯）。这部轰动艺术影院的巨作风趣、性感而精致，云集了璀璨的配角阵容——包括西蒙·卡洛、朱迪·丹奇、丹霍姆·艾略特与玛吉·史密斯，至今仍是睿智爱情电影的一块试金石。[标准收藏]',NULL,3000000,20966644,7.961559,6.9,156,117,'1985-12-13','en','/5SDMrRcNJdIbHkYk1gmuSHPx2ME.jpg',2.9915831556193795,3,'2026-09-10',2,NULL,NULL),(11258,'大雨成灾','Hard Rain','汤姆（克里斯汀史莱特饰演）与叔叔理察共同经营着运钞车事业，一日，他们载着三百万美金的现钞前往杭汀堡小镇，没想到，一场连续大雨造成洪水泛滥，镇民全部紧急撤退，全镇空无一人。叔侄俩被困在大洪水中，求救无门之时，一群由吉姆（摩根弗里曼饰演）所率领的歹徒团团包围住他们……吉姆是一个职业小偷，对于偷盗生涯已厌倦，决定利用此次洪水作为最后机会，大干一票后退休，隐居到一个热带小岛上，两方对峙在大洪水当中，汤姆誓死保护小镇的财产，靠站矫健的身手与过的机智，他带着三百万现金徒步逃走，一场紧张的追杀就此上场!在节节高升的洪水之中，人性的力量与大自然的力量展开对抗…… 　　最后警察都因这笔巨款动了心，为了私吞巨款杀死同伴，成为最真正的歹徒，相反小偷吉姆数次良心发现，救了汤姆的性命。在这样的关键时刻他得到一位美女的帮助，她就是为保护小镇教堂－－一座著名的古迹－－而留下来的卡伦。到最后，直到州警察局最后派人救了他。','In the worst storm in living memory, one guard stands between five men and three million dollars.',70000000,19870567,10.930537,5.5,179,97,'1998-01-16','en','/dYOt2Zp2KQ7NGVKfmiFGPAHjdzr.jpg',2.9501331645162634,3,'2026-09-10',2,NULL,NULL),(11260,'戴夫号飞船','Meet Dave','身着一身白西装的戴夫（艾迪·墨菲 Eddie Murphy 饰）看起来是个彬彬有礼的中年人，虽然身处现代纽约的他总显得和这个年代、这个大都市格格不入，但谁能想到，这个看起来非常真实的“人”其实是一架人形飞船，身体里住着许多四分之一英寸高的外星小人，他们来到地球，想寻求解救自己星球的方法，不料却先在让飞船适应地球生活上经受了极大的考验，惹了一堆麻烦之后，谁想到飞船竟然自主爱上了一个美丽的地球女人吉娜（伊丽莎白·班克斯 Elizabeth Banks 饰），外星小人们偏轨的航线越来越难调正……','There\'s a Whole Other World Going on Inside of Him.',60000000,50650079,18.676291,5,371,90,'2008-07-08','en','/7fi6qcABHA43i8IXo5aFDQYM30O.jpg',3.0490801573844912,3,'2026-09-10',2,NULL,NULL),(11282,'猪头逛大街','Harold & Kumar Go to White Castle','供职于招行的初级分析员韩裔青年哈罗德（约翰•赵 John Cho 饰）性格谨慎羞涩，本该放松的周末晚上却被同事塞了一堆工作。这边厢，哈罗德的好友卡玛（卡尔•潘 Kal Penn 饰）又主动搞砸了一次医院面试，这个出身医生世家的印裔青年因为不愿放弃毫无拘束的学生生活一直逃避从医。当晚，哈罗德与卡玛在吸了一通大麻后倍感饥肠辘辘，电视中来自“白色城堡”的汉堡广告引发了二人极大的兴趣，他们驱车前往，谁知本地最近的白色城堡已经在四年前转让，被汉堡勾起食欲的二人决定不顾一切寻找白色城堡，他们为此跨越了整个新泽西，这对儿性格迥异的朋友也在一路上体会到彼此友情的可贵……','Fast Food. High Times.',9000000,23936908,18.514292,6.6,693,88,'2004-05-30','en','/bdp7ehzLQLF6Fzc2dOaA6wRaruo.jpg',3.368038914081552,3,'2026-09-10',2,NULL,NULL),(11283,'魔法保姆麦克菲','Nanny McPhee','在这部充斥了黑色神话的寓言电影里，汤普森扮演了一个长相有点吓人而且拥有魔法的妇女，她进入了由费斯扮演的刚刚死了妻子的布朗先生的家，并试图去制服布朗7个非常玩闹不服管的孩子。\r 　　这些孩子当中，最大的一个男孩名叫西蒙，由托马斯·桑格斯特扮演，他曾经赶走了此前家里雇的17个保姆，他还坚信一定可以赶走“汤普森”，但随着汤普森扮演的女佣麦克菲开始控制这个家庭，这些孩子们渐渐意识到他们过激的行动很快就会产生令他们自己也感到害怕的结果。\r 　　麦克菲的影响力还渐渐扩大到了这个家庭的更深的一些问题上，包括布朗突然毫无理由地计划再找一个妻子，由安吉拉·兰斯布里扮演的喜欢颐指气使的姨妈阿戴莱德宣布她想领养其中一个孩子，以及由凯利·麦克唐纳尔德扮演的女帮佣埃弗吉琳也开始做出一些惊人之举。\r 　　随着孩子们的行为举止开始有所改变，麦克菲的长相和身材也开始发生变化，而孩子们和布朗先生则开始喜欢上了她这个神奇的陌生人，于是一系列问题又接踵而至。','You\'ll Learn To Love Her. Warts And All.',25000000,122489822,24.356483,6.4,711,97,'2005-10-21','en','/8tommndfI0W62teXwSmXdmVZ7gz.jpg',3.358244175615249,3,'2026-09-10',2,NULL,NULL),(11284,'猛鬼街6：弗莱迪之死','Freddy\'s Dead: The Final Nightmare','弗莱迪杀光了所有榆树街的孩子后，通过放逐最后一个幸存者的方法，将魔爪伸向了更广阔的世界。少教中心的麦琪领养了一个处在失忆状态的少年，通过他身上仅有的线索，来到荒凉的榆树街试图寻找他的身世。几个少年也阴差阳错地来到了这里。期间，孩子们一个个被弗莱迪以稀奇古怪的方式杀死。麦琪在调查中发现自己竟然就是弗莱迪的女儿，而弗莱迪试图通过她的身体达到去更大的世界杀人的目的。但是邪不胜正，麦琪在弗莱迪逍遥法外的同时也找到了将父亲消灭的方法，并且将弗莱迪彻底杀死，永不复生。','They saved the best for last.',11000000,34872033,16.856231,5.1,272,89,'1991-09-05','en','/e4qh58n2WaG4Gyh9VhjOUeN9Mhv.jpg',3.0077733949095085,3,'2026-09-10',2,NULL,NULL),(11287,'红粉联盟','A League of Their Own','故事发生在二次世界大战期间，沃尔特（盖瑞·马歇尔 Garry Marshall 饰）是曾经风靡一时的棒球明星，如今，早已屈居二线的他决定组建一支史无前例的女子棒球队。他看重了漂亮高大的多利（吉娜·戴维斯 Geena Davis 饰），多利的妹妹基特（罗莉·佩蒂 Lori Petty 饰）也跟随着姐姐的脚步加入了球队。\r 之后，马拉（梅根·卡瓦纳芙 Megan Cavanagh 饰）等一干得力干将的加入让球队的实力瞬间增强，在几次挫折之后，沃尔特的“娘子军”逐渐得到了体育界的认可。可是，就在这样的关键时刻，棒球队里却发生了内讧，马拉和基特离队，沃尔特也产生了放弃的想法。就在这时，多利远赴战场的丈夫鲍勃（比尔·普尔曼 Bill Pullman 饰）的归来让棒球队看到了新的希望。','To achieve the incredible, you have to attempt the impossible.',40000000,107458785,21.661028,6.7,354,128,'1992-07-01','en','/f9BtX6wYOwJUyfUr4vyeT3COz6m.jpg',3.216005141646931,3,'2026-09-10',2,NULL,NULL),(11298,'破胆三次','The Howling','电视台女记者凯伦·怀特(Dee Wallace-Stone饰)充当诱饵，帮助警察破获了Eddie Quist (Robert Picardo饰)所作的一系列凶杀案件后心力交瘁，她听从瓦格纳医生的建议，和丈夫Chris（Dennis Dugan饰）一起到 (Patrick Macnee饰)的治疗中心\"\"The Colony\"\"疗养。夫妻俩在疗养地并不能享受着轻松平静的生活，凯伦始终无法放松，她丈夫一直试图安抚她脆弱的神经。渐渐的，他们在中心发现病人有一些怪异行径，月圆之时并不时听到狼声，似乎当地的人全都是狼人，其中隐约还有令凯伦忐忑不安的杀手Eddie Quist的身影。更要命的是，凯伦的丈夫被狼人咬伤，受感染后也变成了狼人。留给凯伦的只有两种选择：要么被狼人撕成碎片后吃尽；要么加入其中也变成一个狼人……','Imagine your worst fear a reality',1000000,17985893,6.532855,6.4,161,91,'1981-04-03','en','/w1FN3A2LI5Oiospn6OrhhEa6nnd.jpg',2.9690688772496014,3,'2026-09-10',2,NULL,NULL),(11302,'香蕉','Bananas','Fielding Mellish（伍迪·艾伦 Woody Allen 饰）是一个产品测试公司的小职员，他喜欢上一个叫Nancy（露易丝·拉塞尔 Louise Lasser 饰）的女孩。Nancy热衷社会运动和民主革命，却对Mellish没什么兴趣。她去了一个叫San Marcos的国家参与了当地的革命，而为了追随心上人，Mellish也随之去了那里。他阴差阳错的加入了革命军，经过浴血奋战，革命终于成功。原来革命军的领袖却成为了新的独裁者，随即被推翻，Mellish被选举成为新的领袖，顿时威风八面。Mellish更作为国家领导出访美国，受到了隆重的接待。Nancy也十分倾慕这个革命领袖，想方设法接近他，却没料到此人竟是她之前甩掉的Mellish......',NULL,2000000,11833696,5.941852,6.7,165,82,'1971-04-28','en','/gK11RUXspxqty0Wq6KoV8J0crKO.jpg',2.9899529097007207,3,'2026-09-10',2,NULL,NULL),(11306,'非常手段','Extreme Measures','在纽约一家医院工作的英国医生盖伊-鲁坦（Guy Luthan），因为一具死在急诊室的男尸失踪而开始进行不受欢迎的调查。路坦顺藤摸瓜，找到了医院的一位著名外科医生，但很快他就发现自己身处极端危险之中，这些人希望医院的秘密不被发现。','Not all surgery is intended to cure.',38000000,17380126,3.426555,5.7,80,118,'1996-09-27','en','/uowP2Nw2mLpQni1vtbUb1LUSiP0.jpg',2.7836026634051696,3,'2026-09-10',2,NULL,NULL),(11308,'新汉普夏饭店','The Hotel New Hampshire','二次大战时，贝瑞夫妇在”New England“酒店的暑期打工中相遇了，一个带着小熊的住客撮合了他们。战后，夫妇带着他们的五个孩子决定在孩子的学校附近开办了一家 “New Hampshire”的酒店。一天他们接到一封信邀请他们拜访”New England“酒店……','If you experienced \"The World According To Garp\" and found it witty, delightful and totally unpredictable, then be happily surprised all over again when you join the fun and games that go on at the...Hotel New Hampshire.',7500000,0,2.226412,5.8,26,109,'1984-03-09','en','/9XGGGniMtBqhox7JAV5JujlUqFz.jpg',2.551317799989549,3,'2026-09-10',2,NULL,NULL),(11313,'亚特兰蒂斯之心','Hearts in Atlantis','在父亲去世后，鲍比觉得自己不会再快乐了，尤其是11岁生日那天，他那刻薄而又小气的母亲居然只给了他一张免费的图书卡作为礼物的那一刻。但自从那个名叫泰德房客出现在了他的生命中后，一切开始变得不同起来。泰德租下了鲍比家的阁楼，整天躲在里面，不知道在捣鼓什么东西。他雇佣鲍比为他读报，报酬是一星期一美分。母亲告诫鲍比离这个奇怪的老头远一点，但鲍比并不当做一回事，因为在鲍比那里，他找到了久违的快乐和信任，泰德不仅让他得到了友情，还给予了鲍比一个人的成长中不可或缺的珍贵品质。','What if one of life\'s great mysteries moved in upstairs?',31000000,24185781,7.06762,6.4,131,101,'2001-09-07','en','/qPTEh8vutS5FSCDoR16MWVGHqTm.jpg',2.9233550386071148,3,'2026-09-10',2,NULL,NULL),(11321,'七磅','Seven Pounds','西装革履的国税局官员Ben Thomas（ Will Smith ）在四处走访纳税人的同时，已经做好了自己的自杀计划。带着对自己不幸去世的妻子的怀念，也带着自己身上所背负的歉疚，Ben对这个世界已经没有什么留恋的了。但是还有最后的几件事他要做——他要尽他的能力去帮助七个人。他们无一例外的都是病魔缠身，亟待帮助的人。可问题是，他们究竟是不是值得Ben的慷慨相助的人呢？','Seven names. Seven strangers. One secret.',55000000,168167691,41.472404,7.5,2039,123,'2008-12-18','en','/85zUipgVy2QbvAJ6djZXYaGckMv.jpg',3.8899913170183322,3,'2026-09-10',2,NULL,NULL),(11322,'公众之敌','Public Enemies','1933年，江洋大盗约翰·迪林格与同伙约翰·汉密尔顿持械劫狱，从印第安纳州监狱中成功救出抢劫团伙成员，包括“漂亮男孩”弗洛伊德，“娃娃脸”尼尔森等，并藏身腐败警察马丁的农宅。马丁说服迪林格藏身芝加哥，寻求黑帮保护。在一系列银行抢劫活动中，迪林格爱上了芝加哥女职员比莉·弗雷凯特……','America\'s Most Wanted.',80000000,214104620,33.691694,6.5,1344,140,'2009-07-01','en','/oXp694VFy8ByI2AJAl1nq05ZUNp.jpg',3.5504707303281386,3,'2026-09-10',2,NULL,NULL),(11323,'The Informant!','The Informant!','A rising star at agri-industry giant Archer Daniels Midland (ADM), Mark Whitacre suddenly turns whistleblower. Even as he exposes his company’s multi-national price-fixing conspiracy to the FBI, Whitacre envisions himself being hailed as a hero of the common man and handed a promotion.','Based on a tattle-tale.',22000000,35424826,17.772518,6,301,108,'2009-09-18','en','/jTq837qFlSbHzLVjrH278nkMXn6.jpg',3.10450399436757,3,'2026-09-10',2,NULL,NULL),(11324,'禁闭岛','Shutter Island','故事发生于波士顿海湾的一座与世隔绝的小岛上，66名精神病罪犯被关押于此，传言岛上正在进行种种人体实验。重重戒备之下，一个杀害了三个亲生孩子的女犯雷切尔，竟诡异失踪。联邦执法官泰德·丹尼尔和搭档查克奉命上岛调查此事。而泰德此行前来还有一个隐秘的目的——寻找让妻子 葬身火海的凶手。故事遵循这条线索展开，寻找失踪之谜、访问医院工作人员与病人、地毯式搜查……泰德查遍全岛，意外发现岛上多出一份神秘档案：第67号病人的 ！岛上所有秘密无不纠结于这个多出来的人。但究竟谁是67号？','Someone is missing.',80000000,294804195,81.914696,7.8,6336,138,'2010-02-18','en','/nrmXQ0zcZUL8jFLrakWc90IR8z9.jpg',4.37585382500714,3,'2026-09-10',2,NULL,NULL),(11336,'死亡地带','The Dead Zone','尊尼在回家不幸撞上十八轮的大货车，死里逃生，昏迷了五年，在桑恩维萨克大夫的治疗下，终于醒了。撞伤后的尊尼，变成有奇特的超能力，不但能预测护士家失火，也能看到大夫的过去，顿成镇上的风云人物。','In his mind, he has the power to see the future. In his hands, he has the power to change it.',10000000,20766616,16.78512,6.9,311,103,'1983-10-21','en','/x23IaeIXCbu1kPpxubcFamHBBaF.jpg',3.1898770622416937,3,'2026-09-10',2,NULL,NULL),(11342,'Warlock','Warlock','A warlock flees from the 17th to the 20th century, with a witch-hunter in hot pursuit. A Warlock (Julian Sands) is taken captive in Boston, Massachusetts in 1691 by a witch-hunter Giles Redferne (Richard Grant).  He is sentenced to death for his activities, including the bewitching of Redferne\'s bride-to-be, but before the execution a demon appears and propels the Warlock forward in time to 20th century Los Angeles, California. Redferne follows through the portal.\r The Warlock attempts to assemble The Grand Grimoire, a Satanic book that will reveal the \"true\" name of God.  Redferne and the Warlock then embark on a cat-and-mouse chase with the Grand Grimoire, and Kassandra (Lori Singer), a waitress who encounters Giles while he\'s attempting to find Warlock.','Satan also has one son.',7000000,0,9.887662,5.8,95,103,'1989-06-01','en','/1QHjr4lBd3vBN4kEqdDFlnJbsa7.jpg',2.8366835984047833,3,'2026-09-10',2,NULL,NULL),(11351,'惊心食人族2','Jeepers Creepers 2','长有双翼的食人恶魔再度出现了。它袭击了一座农场，将男主人的小儿子比利掳走，愤怒的父亲与长子杰基在沉默中发誓为亲人报仇……次日，一支高中校队在比赛结束后乘坐校车返回，于路却被尖锐的飞镖刺破了车胎，年轻人们眼见通讯不畅求助无果，只得慢慢行驶前进，夜里，袭击校车的神秘身影显出了真身，食人恶魔令校车彻底瘫痪，在一片恐慌中开始捕捉车中的人们。与此同时，一直追踪食人恶魔的农场父子终于赶到，他们用自制鱼叉阻击恶魔。由于恶魔每次轮回出可以获得23天在人世的时间，如果能坚持到今夜结束，所有人将成功逃生，学生们与农场父子展开了一场同恶魔的拼杀……','He can taste your fear.',17000000,63102666,19.045146,5.5,299,104,'2003-08-08','en','/tSbOPIftLV07xkooCAUdnliQDpe.jpg',3.0623620228973145,3,'2026-09-10',2,NULL,NULL),(11353,'包芬格计划','Bowfinger','包芬格（史蒂夫·马丁 Steve Martin 饰）做梦都想成为一名电影制片人，然而，依然生活在贫困之中的他显然离自己梦寐以求的好莱坞上流社会有着遥远的距离。可是，苍白的现实却并不能打击包芬格实现自己理想的热情，他得到了一个新的剧本，和朋友们夸下海口，将要邀请好莱坞著名的动作明星凯特（艾迪·墨菲 Eddie Murphy 饰）来做自己的男主角。\r 凯特当然毫不犹豫的拒绝了包芬格抛来的橄榄枝，因为后者能够支付给他的片酬实在是少得可怜。无奈之中，执着的包芬格和他的“摄制组”开始了漫长的偷拍计划。这一计划将凯特的生活搅得一团糟，与此同时，亦吸引了一些和包芬格一样疯狂的人。','The con is on.',55000000,0,13.191829,6,254,97,'1999-08-12','en','/iGuiFYEYwFkaRPl3FgLJYEm6dWq.jpg',3.0584510267418814,3,'2026-09-10',2,NULL,NULL),(11354,'愤怒之上','The Upside of Anger','\"泰瑞（琼·艾伦 Joan Allen 饰）曾经也有过美满的家庭和幸福的人生，可是，酗酒的恶习让她的脾气愈发暴躁，性格愈加乖僻，最终，忍受妻子多年的丈夫格瑞（Danny Webb 饰）选择了离开。人到中年却遭到了丈夫的抛弃，泰瑞的精神陷入了崩溃之中，无所适从的她只能借助酒精麻痹自己的神经，但这只会让事情变得越来越糟，泰瑞和四个女儿之间的关系也因此跌入了冰点。\r 一次偶然中，邻居丹尼（凯文·科斯特纳 Kevin Costner 饰）出现在了泰瑞的生活里，随着时间的推移，两颗寂寞的心靠得越来越近。看到母亲的生活因为爱情的降临而步入了正轨，泰瑞的四个女儿决定帮助泰瑞促成这段感情。\"','Sometimes what tears us apart helps us put it back together.',0,0,6.2464,6.4,72,118,'2005-01-23','en','/iS9lP4poDyvSGXyh199ZEXMPHrY.jpg',2.787467235295885,3,'2026-09-10',2,NULL,NULL),(11357,'月光光心慌慌4：迈克尔的回归','Halloween 4: The Return of Michael Myers','10年前，残暴无情的迈克尔·迈尔斯（George P. Wilbur 饰）陷入永久的昏迷之中，周遭的人们得到短暂的宁静。时间推移到1988年10月31日的万圣节，迈克尔被雷蒙德精神病中心的医护人员转去另一个医院。救护车上，医护人员随意的闲谈却唤醒了这个沉睡已有10个年头的恶魔。苏醒的迈克尔得知他姐姐的女儿杰米（Danielle Harris 饰）住在哈登菲尔德，遂将医护人员杀害，只身前往甥女的住处。  　　被克鲁赛斯一家收养的杰米，多年来持续为关于舅舅的恐怖噩梦所困扰。她想不到的是，那梦中的恶魔即将出现在她的面前，摧毁杰米至今仍未平静的生活……','Horror has returned to Haddonfield.',5000000,17768757,9.302349,5.9,209,88,'1988-10-21','en','/eFSOkXF9n9hsfGv45MDsPixiOyx.jpg',3.001920152519548,3,'2026-09-10',2,NULL,NULL),(11358,'威震八方','Walking Tall','俗话说恶人自有恶人磨。恶霸汉密尔顿（尼尔•麦克唐纳 Neal McDonough 饰）纠集了一帮恶棍在华盛顿州的一个小镇横行多年、压榨乡邻，甚至连当地的警察也拿他们没有办法。这天，特种兵克里斯（巨石 The Rock 饰）退役回到了家乡小镇。一心想着集成父亲的木料场安居乐业的克里斯发现这里已经不是自己服役前那个宁静美丽的小镇了，父亲的木料场被汉密尔顿霸占用作了赌场，高中女友也在恶势力的威逼下成了艳舞女郎。怒不可遏的克里斯当上了小镇的治安官，决定凭着这些年在特种部队的所学的非常手段将这群恶棍赶出家乡！','One man will stand up for what\'s right.',56000000,57223890,23.438398,6,381,86,'2004-04-02','en','/kQLkb01Cclv1uW8MAfN0Lgr4BO9.jpg',3.166750450981587,3,'2026-09-10',2,NULL,NULL),(11359,'魔柜小奇兵','The Indian in the Cupboard','该片描述九岁男孩奥利在生日时得到了一个他哥哥不要的小木柜，以及好友派屈克送给他的小印第安武士塑胶玩具。奥利把小武士放进木柜中竟发现他会动，后来更进一步知道小武士竟是个真人，不禁大为兴奋。不料派克偷偷将一个牛仔玩具也放进木柜中，竟引发牛仔与印第安人的一场战争。',NULL,45000000,0,11.095914,5.9,134,96,'1995-07-14','en','/ozQAmW85tTJu2dhRe3evzyY03Nb.jpg',2.914384341374716,3,'2026-09-10',2,NULL,NULL),(11361,'月光光心慌慌5：迈克尔的复仇','Halloween 5: The Revenge of Michael Myers','1988年的万圣节，杀人魔王迈克尔·迈尔斯被警察射伤，几经周折，他逃到一条河边，并得到一位好心人的救治。一年时光转瞬即逝，伤愈的迈克尔如同僵死复苏的毒蛇一般杀掉救命恩人，并决定再次前往哈登菲尔德，向甥女杰米（Danielle Harris 饰）复仇。  　　一年前，杰米因攻击养母及经历了舅舅迈克尔的追杀噩梦而患上失语症，如今正在当地的儿童医院接受康复治疗。虽然失去说话能力，杰米却神奇地拥有了与迈克尔心灵相通的能力。主治医生卢米斯（Donald Pleasence 饰）意识到了这点，他决定利用这个能力和迈克尔做个了断……','Michael Lives, And This Time They\'re Ready!',5000000,11642254,8.008844,5.2,183,96,'1989-10-12','en','/rYvP6yMXCIVHnkVtwGaAXFmpzkB.jpg',2.929514141372185,3,'2026-09-10',2,NULL,NULL),(11362,'The Count of Monte Cristo','The Count of Monte Cristo','Edmond Dantés\'s life and plans to marry the beautiful Mercedes are shattered when his best friend, Fernand, deceives him. After spending 13 miserable years in prison, Dantés escapes with the help of a fellow inmate and plots his revenge, cleverly insinuating himself into the French nobility.','Prepare for adventure. Count on revenge.',35000000,75395048,26.595983,7.3,453,131,'2002-01-23','en','/nitWxelAjcyZLJYn7p6LzpPxjBJ.jpg',3.3596465419793153,3,'2026-09-10',2,NULL,NULL),(11363,'爱是唯一','She\'s the One','故事讲述两兄弟，一个有女友，一个有太太，却因为一个女人出现，令两兄弟不但对爱人不忠，更成为爱情对手。','A romantic comedy about two brothers... and the one thing that came between them.',3500000,9482579,8.406025,5.7,70,96,'1996-08-26','en','/wNd6qM8Qa8tLFOiUOiEivh0qBkH.jpg',2.7677603238000654,3,'2026-09-10',2,NULL,NULL),(11370,'三剑客','The Musketeer','年轻的达塔南试图加入传说中的火枪手旅，为父亲的死复仇，但他发现火枪手已经解散。','As you\'ve never seen it before.',40000000,27053815,3.296933,5.2,56,104,'2001-09-07','en','/oaKp6HZQDTtCOwn4JGi2Mh7Ep95.jpg',2.6997055015655627,3,'2026-09-10',2,NULL,NULL),(11371,'大买卖','The Score','偷窃老手尼克（罗伯特·德尼罗 Robert De Niro 饰）顺利完成了委托人的任务返回住所，但是在交接时委托人麦斯（马龙·白兰度 Marlon Brando饰）给他带来了一好一坏两个消息：坏消息是买主死掉了，尼克无法出货；好消息则是有一单四百万的大生意在等着他——需要尼可从海关大楼的地下室偷出国王的加冕权杖。预备和女友结婚的尼可不想再涉足偷窃，但是麦斯的合作者——乔装弱智打入海关内部的青年杰克（爱德华·诺顿 Edward Norton 饰）对这单生意锲而不舍，杰克终于打动尼可，与之结成了偷窃权杖的二人组合。杰克凭借出色的急智完成了准备工作，尼可对这位锋芒毕露的年青人要求严格，但又不乏暗暗的赞许。行动当夜，两人潜入海关，但事情的发展却出人意表…… ©豆瓣','There are no partners in crime',68000000,71069884,22.572323,6.7,423,124,'2001-07-13','en','/fsb4m9XW59mei8GKznvI3lLzcfp.jpg',3.263761856676671,3,'2026-09-10',2,NULL,NULL),(11374,'艾德私人频道','EDtv','在录像带店工作的店员艾德（马修·麦康纳 Matthew McConaughey 饰）是一个普通的不能再普通的三十岁男人，就连他自己也想象不到，有一天，自己竟然成为了家喻户晓的电视名人。原来，电视台节目总监辛西娅（艾伦·德詹尼丝 Ellen DeGeneres 饰）的事业遭遇了滑铁卢，日渐低迷的收视率让她的职位受到了巨大的威胁，在这个节骨眼上，她决定制作一档二十四小时连续放送的大型真人秀节目，而节目的主人公正是艾德。\r 很快，艾德的名字便响彻了大江南北，名声和利益接踵而至，让一向不引人注目的艾德尝尽了一夜成名的梦幻滋味。然而，随着时间的推移，艾德发现自己的出名带来的并不只是美好的一面，渐渐显露出的贪婪的人心和无处不在的监视和束缚让他开始想要回到曾经简单快乐自由自在的生活中去。','Fame. Be careful. It\'s out there.',80000000,0,14.298297,5.7,166,122,'1999-03-26','en','/xnnjoMONNamGU6ZX6acbcxyOKv1.jpg',2.954827603014756,3,'2026-09-10',2,NULL,NULL),(11375,'好莱坞重案组','Hollywood Homicide','故事发生在位于洛杉矶的好莱坞，一连串的说唱歌手被杀案件在当地居民间制造了不小的恐慌，为此，洛城警署派出了经验丰富的老侦探乔（哈里森·福特 Harrison Ford 饰）调查此事，为了提高效率，他们还替乔配了一位初出茅庐充满了活力的搭档卡尔顿（乔什·哈奈特 Josh Hartnett 饰）。  　　令乔和卡尔顿没有想到的是，这起连环杀人案看似单纯，两人却在取证调查的道路上遭遇了重重的阻力。随着调查的深入，一名叫赛尔丹（艾赛亚·华盛顿 Isaiah Washington 饰）的音乐经纪人进入了乔和卡尔顿的视线，他有着充足的动机杀死那些可能会害得他倾家荡产的解约艺人。可是，案件调查至此，两位侦探才发现，曾经遇到过的阻力并不来自于凶手，而来自于警察局内部。',NULL,75000000,51142659,10.605084,5,166,116,'2003-06-09','en','/okmPBXWn59pAwcByBaYs2soZKk6.jpg',2.907417051750674,3,'2026-09-10',2,NULL,NULL),(11377,'猛鬼屋','House on Haunted Hill','凡纳克精神疗养院内的研究人员曾进行秘密的生物试验，该试验造成病患和医护人员接连死亡。最终，该疗养院废弃，多年来荒凉阴森，无人敢近，成为远近闻名的恐怖鬼屋。\r 性格怪异的亿万富翁史蒂芬•普莱斯（Geoffrey Rush杰佛瑞•罗许 饰）决定在凡纳克精神疗养院为妻子艾芙琳（Famke Janssen 芬卡•杰森 饰）举行一场别出心裁的生日派对，他邀请六个人前来，只要他们敢在这幢“鬼屋”中待上一晚，就有机会获得一百万美元的奖金。挑战者慕名前来，却不知真正的恐怖正等待着他们……\r 本片荣获2000年百视达娱乐奖最佳男配角奖（Taye Diggs）。','Evil loves to party.',19000000,40846082,13.664614,5.5,209,93,'1999-10-29','en','/weiGTsZqBglKxkIn5xj1nEjxn81.jpg',2.985130437330856,3,'2026-09-10',2,NULL,NULL),(11382,'子弹横飞百老汇','Bullets Over Broadway','长久以来，剧作家大卫（约翰·库萨克 John Cusack 饰）都过着郁郁不得志的生活，艺术家特有的清高让他对如今腐败混乱的话剧界充满了失望之情。为了讨好情妇奥利芙（詹妮弗·提莉 Jennifer Tilly 饰），黑帮大佬看中了名不见经传的大卫的剧本想要投资，作为前提条件 ，大卫必须让奥利芙饰演主角。虽然奥利芙唠叨的个性和蹩脚的演技让大卫深感抓狂，但在利益面前，他痛苦的屈服了。就这样，一个奇怪的剧组诞生了。\r 　　剧本的漏洞，女演员们之间的矛盾，男主演日益肥胖的身材都让大卫感到绝望，但令他惊奇的是，一直监视着奥利芙的保镖契奇（查兹·帕尔明特瑞 Chazz Palminteri 饰）在无意中展现了过人的编剧才能。在契奇的帮助下，被改写的剧本居然获得了盛大的成功，与此同时，契奇对由自己操刀的剧本展现出的病态执着和剧组里混乱的男女关系让大卫陷入了另一个困境……',NULL,0,0,7.829295,7,130,98,'1994-10-14','en','/mY9D1oCLeDKNMdUO8EV7MoCZ3up.jpg',2.950617463223784,3,'2026-09-10',2,NULL,NULL),(11386,'哭泣的游戏','The Crying Game','尼尔·乔丹这部情感震撼的国际轰动之作，打破了独立电影与主流电影之间的壁垒，成为定义1990年代的电影之一。故事以北爱尔兰冲突的动荡局势为背景，本片犹如一个层层嵌套的谜盒，审视着忠诚、欲望与身份等复杂命题，追溯着两个受伤灵魂之间紧张关系的发展：前爱尔兰共和军成员弗格斯深受内疚折磨，而迪尔则是那名人质的谜一般的女友，人质之死始终萦绕在弗格斯心头。影片从政治剧变身为黑色惊悚，再化为痛彻心扉的爱情故事，最终呈现出的超越了类型范畴：一幅关于跨越一切藩篱的人类联结的深邃而不朽的图景。[标准收藏]','Play At Your Own Risk.',3705538,62548947,8.839651,6.9,176,112,'1992-09-02','en','/9BXGoat9TYgdDqGk2WJmaX9dVoe.jpg',3.0239279067960365,3,'2026-09-10',2,NULL,NULL),(11395,'圣诞老人','The Santa Clause','斯科特（蒂姆·艾伦 Tim Allen 饰）拥有一段失败的婚姻，离婚之后，儿子查理（艾力克·洛伊德 Eric Lloyd 饰）跟着母亲劳拉（温迪·古逊 Wendy Crewson 饰）生活。探视日很快就到了，斯科特兴致勃勃的准备去享受和儿子之间相处的短暂时光，但正当他准备出门之时，却发现有一个人在他家的屋顶上鬼鬼祟祟的不知道干着什么。斯科特一声大喝吓得屋顶上的人跌落下来，这时斯科特才震惊的发现，这个人居然是圣诞老人。  斯科特令圣诞老人无法工作，为了赎罪，他只能代替他成为新的圣诞老人，就这样，和查理一起，斯科特来到了圣诞老人的大本营，在这里，斯科特必须学习如何成为一名合格的圣诞老人。','What if your dad was Santa Claus?',22000000,189833357,16.234053,6.3,489,97,'1994-11-10','en','/xAgAtehCu5uqjLJD2r0I4SUajXK.jpg',3.2385428833847474,3,'2026-09-10',2,NULL,NULL),(11397,'非常男女','Not Another Teen Movie','洁妮是个梦想成为艺术家的女生，在学校里，洁妮邋邋遢遢、不修边幅的穿戴使她看起来活像是个怪胎，和周围花枝招展的女孩比起来，她显得那么灰头土脸，同龄人的女孩都为此而孤立她。 同洁妮正好相反，杰克是学校里最受欢迎的足球队长，也是无数女生心中的白马王子，某天，闲着无聊的杰克和同伴打赌，要把不起眼的洁妮变成最美丽最耀眼的校园舞会皇后，于是为了赢得赌局，杰克开始对洁妮狂追不舍。 与此同时，一直看洁妮百般不顺眼的女生“大姐头”、一位风骚的啦啦队长不明就里，又嫉又恨之下，当然想方设法对杰克的追求加以阻挠，当然，还有很多花色的人物掺杂故事其间，外国来的交流学生、贫嘴巴舌的黑人男生、暗恋女主角的木讷肥仔。','They served you Breakfast. They gave you Pie. Now we’re gonna stuff your face.',16000000,66468332,23.423082,5.5,431,89,'2001-12-07','en','/9ZaGxvj1mqdKVLpSloq4mzS7SK6.jpg',3.136708977203283,3,'2026-09-10',2,NULL,NULL),(11398,'神鬼任务','The Art of War','中国驻联合国大使意外死亡，特工肖（韦斯利·斯奈普斯 Wesley Snipes 饰）是对案件进行调查的负责人。在调查的过程中，肖震惊的发现，大使的死是一场精心策划的谋杀，而在这场谋杀的背后，隐藏着的是一个恐怖组织以及他们试图攻击联合国的邪恶计划。正当肖决定根据找到的线索摸清事件真相之时，却震惊的发现自己成为了警方通缉的目标，而他莫名背负上的罪名，竟然正是谋杀联合国大使。不愿意向恶势力屈服的肖决定依靠自己的力量抓住栽赃陷害他的罪魁祸首，亲手帮自己洗清冤屈，在此过程中，一个名叫茱莉亚（Marie Matiko 饰）的女翻译浮出了水面，她手上掌握着破案的关键证据。','Who is your foe?',40000000,30199105,7.832337,5.6,135,117,'2000-08-23','en','/tcRjKse55uo8OwrBCHBbMWpCYzH.jpg',2.8943980886816583,3,'2026-09-10',2,NULL,NULL),(11400,'新世界','The New World','故事发生在17世纪的北美大陆，尽管生存环境恶劣，资源稀缺，但世世代代生活在这里的印第安人仍然享受着延续了百年的宁静生活。然而，这样的生活伴随着来自西方文明世界的三艘小船的到来即将划上终点，103名英国水手来到了这片未经开垦的处女地，建设了他们的据点，在这里宣扬他们的宗教和文化。\r “永恒苏珊”号的甲板上，一位名叫史密斯（柯林·法瑞尔 Colin Farrell 饰）的青年因为违抗军令而即将遭到处死，船长纽波特（克里斯托弗·普卢默 Christopher Plummer 饰）看中史密斯的精明强干，留下了他。一行人上岸驻扎，建立了詹姆斯镇，却在无意之中侵犯了酋长波瓦坦（欧琳卡·乔彻 Q\'Orianka Kilcher 饰）的领地。之后，史密斯邂逅了酋长的女儿波卡洪塔斯（Q\'orianka Kilcher 饰），两人之间产生了一段传奇的感情。','Once discovered, it was changed forever.',30000000,30536013,19.106154,6.4,330,135,'2005-12-25','en','/dPyWMlQd54r3pK17GKG3iqjvNZ7.jpg',3.164219735530714,3,'2026-09-10',2,NULL,NULL),(11404,'人生驾驶课','Driving Lessons','本（鲁伯特·格林特 Rupert Grint 饰）生活在一个保守刻板的家庭中，强势专横的母亲劳拉（劳拉·琳妮 Laura Linney 饰）和沉默寡言的父亲罗伯特（Nicholas Farrell 饰）共同组成了一张紧密的大网，将本牢牢的网在其中。暑假到来了，当所有孩子都在对快乐的假期生活充满了期待时，本知道，等待着自己的依然会是枯燥的宗教课程。为了有所改变，本决定找一份兼职。\r 一个名叫艾薇（朱丽·沃特斯 Julie Walters 饰）的女人的出现改变了本压抑的生活，在艾薇的带领下，本参加了各种有趣的课外活动，甚至在公园里演起了莎士比亚的喜剧，在重拾自由和快乐的同时，本也遇到了那个命中注定的女孩。',NULL,0,0,7.667888,6.3,47,98,'2006-04-30','en','/uPRFM5co4v12ksWaZKr8niIHBrC.jpg',2.6953254031846594,3,'2026-09-10',2,NULL,NULL),(11411,'超人4：和平任务','Superman IV: The Quest for Peace','轰动世界的第一英雄——超人，重返地球，接受大敌挑战，对手是坏蛋雷克斯，他针对超人的弱点，用氪元素制造邪恶的核能人，利用最先进的科学武器，面对势均力敌的对手，超人与其展开太空大对决……','Nuclear Power. In the best hands, it is dangerous. In the hands of Lex Luthor, it is pure evil. This is Superman\'s greatest battle. And it is for all of us.',17000000,19300000,17.062117,4.1,318,90,'1987-07-23','en','/nJFBeU1oKIaIoLVyQYUeB36DW55.jpg',2.941167373198375,3,'2026-09-10',2,NULL,NULL),(11412,'特工狂花','The Long Kiss Goodnight','简驾车时出了车祸，伤愈后发现失去的记忆开始恢复，这对患失忆症的她来说真是意外。在私家侦探的帮助下她了解到：自己曾是联邦调查局的特工。受反恐怖组织头目伯吉斯的委派，去对付恐怖分子迪达。但她不知道，警匪两家正串通一气制造大案，为的是让政府意识到反恐怖组织的重要性，增加财政拨款，她自己只是这肮脏交易中的一个牺牲品。但现在，谁都以为早已不在人世的她再次出现，这引起伯吉斯的极大恐慌。了解了自己的过去，简也清楚目前的处境，但此刻的她已不是温文尔雅的女教师，做特工时练就的一身绝技要派上用场了，目标是当年的上司和整个犯罪集团。','What\'s forgotten is not always gone.',65000000,89456761,15.858629,6.5,314,120,'1996-10-11','en','/gZFcFtx9jefk1kbLnTZls8Q2RdE.jpg',3.154168863542459,3,'2026-09-10',2,NULL,NULL),(11426,'乱世忠魂','From Here to Eternity','这部1953年的经典之作，描绘了珍珠港事件前夕夏威夷军营中紧密相连的士兵们的爱情、希望与梦想。','Pouring out of impassioned pages...brawling their way to greatness on the screen!',1650000,30500000,6.915201,7.2,133,118,'1953-08-04','en','/sP3T6hTkTMCksUXb0wzzOgbXIfk.jpg',2.9634966273372356,3,'2026-09-10',2,NULL,NULL),(11431,'极度狂热','Fever Pitch','这是一个关于高中老师与成功职业女性的罗曼恋爱史。他们一见钟情，沉溺其中。Lindsey（Drew Barrymore饰）对Ben（Jimmy Fallon饰）的唯一疑惑是，这么优秀的男人，怎么会从来没有恋爱？随着棒球赛季的到来，谜底揭晓了。Ben继承了舅舅每个赛季的棒球票，从7岁开始他每年夏天都与红袜子队度过，在赛场的观众席上，他有一大群志同道合的朋友。Lindsey开始为了Ben迁就生活脚步，直到她意外怀孕，她认真考虑这个男人是否是婚嫁的好对象；而Ben为了球赛忽略了Lindsey导致二人暂时分开的局面也令他重新衡量女友的重要性。你会选择球赛还是女友？但是真正爱你的人是不会让你二选一的。 ©豆瓣','A Comedy About The Game of Love.',30000000,50451307,9.965073,5.9,182,103,'2005-04-06','en','/xwJBEOM5BVElAgQIA82KBLX10fu.jpg',2.975019671030585,3,'2026-09-10',2,NULL,NULL),(11439,'影子写手','The Ghost Writer','当一个成功的英国影子写手“影子”同意为英国前首相亚当·郎写完回忆录的时候，他的经纪人向他保证这是他一生的一个机遇。但是从一开始这个计划就仿佛被厄运笼罩——因为他的前任写手，亚当·郎的长期助手麦克·艾尔从伍兹霍尔渡轮上掉下去淹死了，虽说这只是一起意外事故但是其中的颇多疑点难免让人心生怀疑和不详的预感。 　　      影子在接受这份工作之后，他的女朋友就离开了他：“她觉得他背叛了她，她曾经是一名党员。”影子在隆冬季节飞到了位于美国东海岸一座岛屿上的房子开始着手这项计划。但是就在他抵达之后的第二天，英国前外交大臣就协助中情局逮捕了亚当·郎。 　　      因为一份他在职期间的备忘录透露，郎犯有非法扣押恐怖分子嫌疑人并让他们接受酷刑的战争罪。现在，亚当·郎面临着被送上国际军事法庭的迫在眉睫的威胁。而这件事，在英国国内也引起了广泛的关注。 　　      争议使得记者和示威者涌郎在岛上的豪宅，郎跟他的妻子露丝，以及他的个人助理（兼情妇）阿梅利亚呆在那里。随着影子的枪手工作的展开，他开始发现郎的被捕不是一件简单的政治事件，也不是郎一个人的过失。看起来，这好像是他的前任，麦克·艾尔故意捏造而杜撰的“真相”，而且麦克·艾尔也不是一个简单的人物，他一直在暗地里给中情局发送资料，“揭露”或者是“栽赃”前首相亚当·郎。而现在，这些蛛丝马迹的证据，就藏在麦克·艾尔留下的手稿里……','Read between the lies.',45000000,60222298,21.118196,6.7,670,128,'2010-02-12','en','/cj7PpgDlfsYu6hQXoKRqP7KUeGd.jpg',3.379809132886811,3,'2026-09-10',2,NULL,NULL),(11442,'月光光心慌慌8：复活','Halloween: Resurrection','一组自以为在竞赛中获胜而选出的青少年，被安排进入麦克·梅尔（Michael Myers，《万圣节》系列中的杀人狂魔）的老屋中过夜。与此同时，他们在这一天中的生活将被送上Internet互联网直播。听起来这一切将是一个像《艾德私人频道》EDTV和《生存者》Survivor一样颇受欢迎的现代直播节目，而且这六名孩子也都迫不及待的想要享受一夜成名的快乐。但是，他们所不知道的是，隐藏在这栋小屋中的秘密很快将致他们于死地。这场互联网上的现场秀，已经变成了麦克·梅尔复活的引子，而他们唯一所剩下的难题就是活着离开……','Evil finds its way home',13000000,37664855,11.045593,4.5,228,94,'2002-07-01','en','/zHTUgLA6y0hdAlybhZnOF1w1p3o.jpg',2.9236032904655604,3,'2026-09-10',2,NULL,NULL),(11446,'欢迎光临娃娃屋','Welcome to the Dollhouse','本片是一部冷峻的郊区喜剧，讲述了11岁的道恩·维纳（希瑟·马塔拉佐 饰）的故事——她在新泽西州一所中学里，是个排行居中、就读于中学、身处新泽西州的“中间”孩子。[索尼影业经典]','Not all girls want to play with dolls.',0,0,5.870319,6.9,103,88,'1995-05-24','en','/fsMMOVto87pvUQyozOF9CaT9aMR.jpg',2.8849713401002903,3,'2026-09-10',2,NULL,NULL),(11451,'疯狂金车','Herbie Fully Loaded','少女玛姬（琳赛·露安 Lindsay Lohan 饰）来自一个赛车手世家，爷爷和爸爸都曾是NASCAR的冠军，玛姬的血液里自然也流淌着对赛车的热情，然而因为几年前的一次意外，玛姬的父亲开始阻拦她成为一名职业赛车手。一个偶然的机会，玛姬在汽车废弃场廉价购入了一辆破旧的甲壳虫贺比，竟不知不觉地开启了她的奇幻赛车之旅：贺比显然不是普通的汽车，它先是让玛姬误打误撞参加了NASCAR挑战赛，更是在险要关头帮玛姬跑赢了卫冕冠军墨菲（马特·狄龙 Matt Dillon 饰），种种迹象让玛姬意识到，贺比其实是一辆有灵性的疯狂汽车，它不仅和玛姬一样有着夺冠的职业理想，还爱管闲事，乐于撮合有情人。然而激速的赛车场并非儿戏，年轻的玛姬和上了年纪的贺比究竟能走多远？\r 本片翻拍自迪士尼1968年的经典冒险喜剧电影《万能金龟车》，金龟车“贺比”诞生后很快便跻身迪士尼经典形象的行列。','Start your engines...',50000000,66002004,12.050755,5.1,542,101,'2005-06-22','en','/qPyHPs0kH2CcgI5mkA2ZcO0Whhd.jpg',3.099106804427385,3,'2026-09-10',2,NULL,NULL),(11452,'National Lampoon’s Van Wilder','National Lampoon’s Van Wilder','Van Wilder has been attending college for far too many years and is scared to graduate, but Van’s father eventually realizes what is going on. When he stops paying his son\'s tuition fees, Van must come up with the money if he wants to stay in college, so he and his friends come up with a great fund-raising idea – throwing parties. However, when the college magazine finds out and reporter, Gwen is sent to do a story on Van Wilder, things get a little complicated.','Don\'t Graduate. Celebrate.',5000000,38275483,35.108498,5.9,858,92,'2002-03-29','en','/z5ZwJJchnxBRqt32mnqgjr6YFUa.jpg',3.3464778213751427,3,'2026-09-10',2,NULL,NULL),(11453,'哈拉猛男秀2：欧洲种马','Deuce Bigalow: European Gigolo','被送到英语牛郎学校后，德斯很高兴地发现了一个男妓的秘密社区。但不幸的是，这些男妓接二连三的遭到了谋杀。','For the women of Europe... The price of love just got a lot cheaper.',22000000,22400154,10.259461,4.7,225,83,'2005-08-06','en','/6nplK9DkX7dPLOlImoUfR9lch2d.jpg',2.9342628430196194,3,'2026-09-10',2,NULL,NULL),(11456,'禁入家园','Domestic Disturbance','弗兰克（约翰·特拉沃塔饰）在一个海滨小镇上经营着一个小造船厂，他和妻子苏珊（特莉·保罗饰）离婚了。11岁的儿子丹尼（马特·欧莱瑞饰）由妻子监护。离婚后弗兰克和苏珊对于丹尼的爱没有丝毫改变，但丹尼却日渐叛逆，经常撒谎、不断惹祸。某日，苏珊邂逅了里克（文斯·沃恩饰），一个初来小镇且热心公益的人，两人走到了一起并很快结婚。渐渐地丹尼却发现了里克的种种怪异之处，在一次意外情况下丹尼还发现里克杀人了，他将这一切告诉周围人，却无人相信他。面对行事诡异的里克和扯谎成性的儿子丹尼，弗兰克会选择相信谁。','He will do anything to protect his family.',75000000,54249294,8.41856,5.4,113,89,'2001-10-30','en','/quRhjnXAuIn04VmgM84nmKzt79J.jpg',2.8527545259086673,3,'2026-09-10',2,NULL,NULL),(11457,'爱在屋檐下','Life as a House','建筑师乔治（凯文·克莱恩 Kevin Kline 饰）很早就和妻子罗宾（克里斯汀·斯科特·托马斯 Kristin Scott Thomas 饰）离婚了，与儿子山姆（海登·克里斯滕森 Hayden Christensen 饰）之间的关系也并不乐观，不如意的工作 干了几十年，不满意的房子住了几十年，而就在不久前，他又被查出患上了不治之症。落入了人生最低谷的乔治暗下决心，即使死期将近，也不能就此沉沦。\r 乔治决定重新修葺房屋，他找来山姆，希望他能够助自己一臂之力。尽管老大的不情愿，山姆还是半推半就的答应了，与此同时，罗宾也开始天天给辛苦劳作的父子二人送饭送菜，一家三口的关系渐渐恢复到了从前的幸福和睦。就当三人沉浸在家庭带来的快乐中时，乔治的生命也已经走到了尽头，然而对于此事，山姆和罗宾竟然一无所知。','Seen from a distance, it\'s perfect.',18000000,0,5.706767,7.2,120,125,'2001-10-25','en','/qNFlcei9vWh5NCRTVrs52qDvUmq.jpg',2.934349902596348,3,'2026-09-10',2,NULL,NULL),(11458,'致命人脉','People I Know','对于反种族歧视组织而言，艾利沃曼（阿尔•帕西诺 Al Pacino 饰）是一个不可多得的公关大亨。虽然他不修边幅，精神萎靡，但是却能够从容地游走于政客、商贩、明星等社会名流之间。他利用自己的人脉关系，不断地创造者政坛和媒体的新闻。一次偶然的机会，他结识了女明星吉莉（蒂娅•里欧妮 Tea Leoni 饰），在车里，这个平日声色犬马的明星痛哭流涕，只有靠艾利的药片得以缓解压力。后来，他跟随她来到了世贸中心的顶层，那里正上演着醉生梦死的私人派对，艾利无意中目睹了一次谋杀事件。曼哈顿的一夜，让艾利开始反思此前工作的威胁，后来他开始向老友维多利亚（金•贝辛格 Kim Basinger 饰）寻求帮助，但是真正摆脱困扰显然更加复杂……',NULL,20000000,0,6.377308,5.5,48,100,'2002-11-21','en','/7FsbWJq43lQGCIPxe8z3zBwEIkh.jpg',2.6820857704542127,3,'2026-09-10',2,NULL,NULL),(11459,'超人高校','Sky High','威尔的爸爸妈妈都是超人界定天皇巨星，理所当然，少年威尔（迈克尔•安格拉诺 Michael Angarano 饰）进入了超人的摇篮——超人高校学习。进校的第一天就要进行超能力测试，拥有超能力的优质学生将进入英雄组，其他人则会被分到吃力不讨好的助手组。很不幸，威尔进入了助手组。从此，威尔的日子相当不好过，他不仅被超人组队同学整蛊，就连啦啦队的美女们都取笑他，而且可怜的他还要尽力向超人父母隐瞒他在学校的悲惨遭遇。屋漏偏逢连夜雨，此时，一只罪恶的黑手伸向了超人学校……','Saving The World... One Homework Assignment At A Time.',35000000,86369815,11.041659,5.8,550,100,'2005-07-29','en','/nBB0XNMwvYvWpo67EcxQqKMoMKf.jpg',3.1892329122882486,3,'2026-09-10',2,NULL,NULL),(11460,'红眼航班','Red Eye','夜间班机因旅客大都熬夜熬得双眼通红，故得名为红眼班机。勒克斯大西洋酒店的高级行政人员丽莎（瑞秋•麦克亚当斯 Rachel McAdams 饰）今天不得不搭乘她最不喜欢的红眼班机，因为她必须在参加完祖母的丧礼后明天就赶回酒店工作。\r 　　丽莎的运气还不错，在机场遇到了英俊潇洒的杰克逊（希里安•墨菲 Cillian Murphy 饰），两日相谈甚欢。更让丽莎惊喜的是，两人搭乘的是同一班红眼班机，而且还相邻而坐。本以为一段美好的缘分就此展开时，丽莎万万没有想到，原本温文尔雅的杰克逊露出了他的狰狞面目。原来杰克逊是恐怖分子的一员，他正要前往刺杀住在勒克斯大西洋酒店的安全部的高官。现在，恐怖分子绑架了丽莎的父亲，要求身为该酒店主管的丽莎协助杰克逊完成这一刺杀任务。在恐怖分子的要挟下，丽莎将何去何从？ ©豆瓣','Fear takes flight.',26000000,57891803,8.802626,6.2,455,85,'2005-08-04','en','/1fBnAYk0JDBqPRtRsOkoIEgXL1n.jpg',3.193451767466264,3,'2026-09-10',2,NULL,NULL),(11467,'美国甜心','America\'s Sweethearts','格温（凯瑟琳·泽塔-琼斯饰）和艾迪（约翰·库萨克饰）是一对貌似美满幸福、实际上危机四伏的好莱坞明星伉俪。格温是个贪慕虚荣、极端自我的女明星，她强迫好脾气的妹妹姬姬（朱莉娅·罗伯茨饰）做她的私人助手，帮她打理个人事务。姬姬一直暗恋着姐夫艾迪，但是在美艳动人的姐姐面前，肥胖的姬姬很自卑。为了赢得爱情，姬姬痛下决心，成功减肥。这时，格温和艾迪正合作主演一部新的影片。但此时他们的婚姻已经濒临破裂。期间，艾迪发现格温在与西班牙“大众情人”赫克特约会。艾迪一怒之下企图用摩托车将两人撞死，但没有成功，还收到了法庭的禁制令，不许艾迪走近格温身边200英尺的区域。格温和艾迪分手的消息传开了，但是为了宣传新片，格温和艾迪的公关经纪人李（比利·克里斯托饰）决定向记者们散布两人复合的假消息。他组织了一个大型新闻发布会，要求格温和艾迪出席。姬姬也答应格温最后再帮她一次，在新闻发布会上协调格温和艾迪的关系，帮他们维护在公众面前的形象。而此时的姬姬已经变成了苗条可人的美女，让艾迪大吃一惊，于是好戏开始了。','Hollywood\'s hottest couple just split up. It\'ll take more than special effects to reunite them.',0,0,10.698929,5.5,252,102,'2001-07-17','en','/uU6sRJNHEO1B3pcPPB9jOdLi5wG.jpg',3.0125435223311996,3,'2026-09-10',2,NULL,NULL),(11468,'苦海惊魂','The Salton Sea','丹尼（方·基默 Val Kilmer 饰）从前拥有一个幸福的家庭，和妻子之间十分的恩爱。然而，不幸降临在了这个家庭之中，丹尼的妻子死在了毒贩的手中，而丹尼则成为了这一场惨剧的目击者。愤怒而又绝望的丹尼发誓要替妻子报仇，他前往洛杉矶大名鼎鼎的沙顿海，那里是毒贩和黑手党的聚集地，他要杀的人就在那里。  丹尼隐姓埋名成为了警方的线人被安插在贩毒团伙之中，在寻仇的过程中，丹尼渐渐的迷失了自我，对他自己所做的一切事情的意义产生了怀疑，唯一支撑着他继续走下去的，便是妻子温柔的面庞。不仅如此，丹尼还有这一个音乐梦，他随身携带着一支小号，奏响自己的命运。','If you\'re looking for the truth, you\'ve come to the wrong place.',18000000,676698,10.991281,7,104,103,'2002-01-01','en','/i3InMSlLUNBEdQTKazMdyVP1ryX.jpg',2.902743280650936,3,'2026-09-10',2,NULL,NULL),(11469,'黑骑士','Black Knight','马丁·劳伦斯扮演一位穷困潦倒的拳击手，在某中世纪主题公园里当招待维生，不料有一天被意外击昏，醒来后却发现自己来到了中世纪，接着被一心想谋杀皇后的邪恶国王当成异类关进大牢，冒险逃出后误入丛林，被一名落难骑士当成是上天派来帮助他们推翻暴政的使者，于是被迫练习剑术，又引来一名美丽的农家女垂青，他们合力对抗邪恶的国王，马丁也重新认识了幸福的真谛……','It\'s only a flesh wound!',0,0,15.913783,5.1,287,95,'2001-11-21','en','/pVxwVH461k9u4tUfRewT29DEZ2e.jpg',3.0139681592502323,3,'2026-09-10',2,NULL,NULL),(11470,'十三号星期五10：杰森在太空','Jason X','2000年，杀不死的杰森被关在水晶湖研究中心，政府为了借杰森研究坏死组织恢复试图将其转移，然而交接时刻杰森再次大开杀戒，危机关头研究员萝文（莱克莎·多伊格 Lexa Doig 饰）把杰森和自己一起封冻。455年后，地球早已不适合人类生存，一支人类科考队返回地球进行考古研究，他们发现了萝文与杰森的尸体，博士卢威（乔纳森·鲍茨 Jonathan Potts 饰）与学生们把尸体带回运输船高刚号，并使用高科技令萝文复活。作为著名杀人狂，杰森尸体的商业价值令卢威心动，岂料杰森在太空船中再次复活并大开杀戒，杰森杀不死的体质结合400年后的科技手段令他的恐怖指数再度上升……','Evil has an upgrade.',11000000,16951798,11.220643,4.5,291,91,'2001-07-24','en','/ggOND0hfoE0f3K857joSzEeIchb.jpg',2.954006577927613,3,'2026-09-10',2,NULL,NULL),(11478,'圣堂风云','The Skulls','一名常春藤盟校的大四学生靠奖学金生活并兼职工作，被秘密社团“头骨”接纳。他希望这能增加在哈佛的机会，但“头骨”并不是他想象的那样，而且是有代价的。','Getting in is easy. Getting out is a killer.',15000000,35007180,11.375032,5.8,156,106,'2000-03-31','en','/tpN4a79KTfWfK67kykbmSSGS2u5.jpg',2.9411732437194535,3,'2026-09-10',2,NULL,NULL),(11495,'凶火','Firestarter','在安迪(David Keith饰)和维姬（Heather Locklear饰）还在上大学的时候，他们为了赚钱参与了一次实验，服用了一种叫做Lot－6的化学品。他们结了婚，现在已经拥有了一个9岁的女儿莎林。莎林有一种特异功能，她可以靠自己的意念点燃东西，这可能要归因于安迪和维姬曾经参与的那次实验，同时，安迪也拥有了某种超能力，可以让人们做他希望人做的事情。那次实验的操作者是一个秘密的政府部门，代号为“商店”，执行人是约瑟夫博士，他开始派人追查两个人的下落，并且派出了一个狙击手，要杀掉两人。而他们没有预料到的是，安迪和维姬拥有的超能力可以帮助他们摆脱追捕，一场大战即将上演。','Will she have the power... to survive?',15000000,17080167,11.379652,5.9,173,114,'1984-05-11','en','/2ux5lqNuibd8eOkwwUhzfzAJBqD.jpg',2.9678094367246377,3,'2026-09-10',2,NULL,NULL),(11499,'对话尼克松','Frost/Nixon','尼克松（弗兰克·兰格拉 Frank Langella 饰）在水门事件后下台，却始终未曾对公众承认过自己的错误，欠美国人民一个道歉。福斯特（麦克·辛 Michael Sheen 饰）是一个在澳大利亚主持脱口秀的英国花花公子，在直播中看见尼克松搭乘直升飞机离开白宫时萌生采访他的意念并决定付诸实践。\r 　　没有人对福斯特抱有期望，没有电视公司愿意出钱购买他的采访，朋友约翰（马修·麦克费登 Matthew Macfadyen 饰）找来业内著名的新闻人鲍勃（奥利弗·普莱特 Oliver Platt 饰）和对尼克松研究颇深的詹姆斯来组成一个小组，开始进行资料挖掘。福斯特自己掏钱付了头笔的采访费，获得了与尼克松见面的机会，并且敲定了连续采访的日子。小组拼命准备问题以便逼尼克松在采访中认罪。尼克松的智囊团也在忙碌地准备应答，他们从不把福斯特放在眼内。正式采访开始，福斯特招架不住尼克松滔滔不绝的自辩，这一切让福斯特破釜沉舟，寻找突破口……','400 million people were waiting for the truth.',0,0,16.87784,7.2,328,122,'2008-10-15','en','/lZpRflNIP0OjRx6YydSiDH7L8Oy.jpg',3.2322165316532274,3,'2026-09-10',2,NULL,NULL),(11507,'粉红色杀人夜','Body Double','杰克（Craig Wasson饰）是一个非常努力的演员，一天他回到家中，发现女朋友和另外一个男人在一起，于是他不得不离开找到一个新的安身之所。他在一部b级的吸血鬼恐怖片中有一份工作，去往工作的途中，他在报纸上搜寻住处。恰巧遇到了一个同事弗兰克，需要找一个人看家，两个人都感到非常满意。于是，杰克住进了弗兰克的家，而弗兰克向他展示了自己“最爱的邻居”——一个丰满的女人，每天晚上她都将自己的窗帘拉开，而杰克也渐渐沉迷于偷窥她的生活。他甚至还试图制止一个小偷偷取邻居的钱包，却在追随小偷的过程中，因为有幽闭症而不得不放弃了。在偷窥的过程中，杰克发现了一起谋杀案，他本来想求助于警察，却发现根本无济于事，而且在他偷窥的过程中，还有其他人也在偷窥着，杰克决定靠自己查出真相……','You can\'t believe everything you see.',10000000,8801940,9.525626,6.4,137,114,'1984-10-25','en','/lRFm5P2AdOGpELwm3HHhmUz6k5I.jpg',2.939128817426966,3,'2026-09-10',2,NULL,NULL),(11509,'西瓦拉多大决战','Silverado','由一个邪恶的警长暗中控制的西部荒凉小镇，在黄沙万里的原野上，成了一切罪恶的渊源，镇民们处于淫威之下，敢怒不敢言，一直到有一天，四大汉出现了，四个被逼上梁山的西部好汉，如何在恶势力的笼罩下，重新建立正义和公理。','Four strangers become friends. Four friends become heros. On the road to...',26000000,0,10.981038,7.1,146,127,'1985-07-10','en','/3aAl3MOefo7bB7kIlzaAKi1lq5B.jpg',2.991982126396466,3,'2026-09-10',2,NULL,NULL),(11516,'迁徙的鸟','Le Peuple migrateur','这部纪录片探索了鸟类穿越四十个国家和七大洲的迁徙过程。',NULL,35866397,20217080,3.75074,7,49,98,'2001-12-12','fr','/xx4PCNqip2g5bNLar6Ksed0dGlh.jpg',2.70861402001981,3,'2026-09-10',2,NULL,NULL),(11517,'银线风暴','Money Train','约翰与查理同属纽约地铁的特警，两人情同手足，为帮助查理戒赌，约翰可没少劳心费力。因工作关系他们对地铁的保安环境十分熟悉，两人经常想象出不同的方法去打劫运钞列车。约翰一直把这当成是一种游戏，但查理却认为这是他唯一能脱离赌徒生涯的途径。当新调任的女警姬丝爱上了约翰而非查理时，失落的查理终于铤而走险，跳上了运钞列车……','Get on, or GET OUT THE WAY!',60000000,35431113,10.004564,5.4,222,103,'1995-11-21','en','/jWBDz6Mf9aQVBiUS76JQsEhvoJl.jpg',2.9808522637680177,3,'2026-09-10',2,NULL,NULL),(11519,'一九四一','1941','这部无厘头式的搞笑电影由史蒂文·斯皮尔伯格执导，并一举获得了奥斯卡三项提名。故事发生在日本偷袭珍珠港后几天的洛杉矶，日本侵犯所带来的恐惧将洛杉矶变成了有如地狱之城。“1941”在好莱坞创造了许多奇异的角色，如热情的军人、极度感伤爱哭的女孩及争吵不休的纳粹，加上怪异莫名的骚动--一个逃离渡口的舵轮、一栋两层楼的废墟。','Paranoia meets pandemonium.',35000000,31755742,10.032626,5.6,143,113,'1979-12-13','en','/52Bn5yC6IHQuVxPUza3Q6RZCZTu.jpg',2.9106447383641907,3,'2026-09-10',2,NULL,NULL),(11529,'情归阿拉巴马','Sweet Home Alabama','梅兰妮（瑞茜•威瑟斯彭 Reese Witherspoon 饰）是纽约炙手可热的设计师之一，年轻貌美的她拥有众多追求者，其中不乏像纽约最有名的钻石王老五、市长的儿子安德鲁这样人物。可是梅兰妮虽然和安德鲁订了婚，却一连三次拒绝了他花费天价的求婚。众人一时都摸不着头脑。其实，梅兰妮有自己的苦处：她本来是阿拉巴马州一个平凡的女孩，早已嫁给了当地一个纯朴的小伙子，但梅兰妮不甘心于小镇平凡无奇的生活，于是几年前独自来到纽约打拼。她必须回家乡办好离婚手续才能返回纽约开始她和安德鲁的新生活。梅兰妮带着一种优越感回到了家乡，回到了之前她不屑一顾的生活的地方。此时，她才猛然醒悟，原来自己一直都没有改变，这里才是她的家！ ©豆瓣','Sometimes What You\'re Looking For Is Right Where You Left It.',30000000,180622424,18.256028,6,394,108,'2002-09-26','en','/698cbxq0SRwCdOPG5Bwi7JDk12d.jpg',3.161922865556001,3,'2026-09-10',2,NULL,NULL),(11531,'女巫布莱尔2：影子之书','Book of Shadows: Blair Witch 2','金（金·迪莱克特 Kim Director 饰）、杰弗里（杰弗里·多诺万 Jeffrey Donovan 饰）、艾瑞卡（艾丽卡·李尔森 Erica Leerhsen 饰）等五个不知死活的年轻人再度走进了黑暗而又神秘的黑山丛林，入夜，一行人驻扎在拉斯廷的房子旁，而这个拉斯廷，正是大名鼎鼎的曾经受到布莱尔女巫蛊惑而杀害了七个孩子的残酷凶手。白昼来临，奇怪的是，年轻人们不约而同的失去了昨晚的记忆，没有人知道前一夜究竟发生了什么，也不知道他们所闻所见究竟是梦境还是现实。离开了黑山丛林，他们聚集到了杰弗里家，在那里，每个人都试图弄清楚事件的真相。渐渐的，诡异的事情开始发生，诸多的证据表明，五个人虽然活着离开了黑山丛林，却依旧处于女巫的掌控之下。','Evil Doesn\'t Die.',0,0,3.890223,4.3,212,90,'2000-10-27','en','/l1jF93S9FYbzp3Byh5VUA1KApSJ.jpg',2.884274064172199,3,'2026-09-10',2,NULL,NULL),(11535,'浴血野球场','Rollerball','在不久后的2005年，一种名为“轮滑球\"(Rollerball)的新兴竞技运动以其超乎寻常的惊险、刺激吸引了大众的注意力，成为一大体育娱乐热点。每当赛季到来时，数以万计狂热的观众都会疯狂地为自己支持的队伍下注，然后守在电视前观看紧张的现场转播。然而，在这项运动的背后，却隐藏着黑暗残酷的内幕……','Go Ballistic',0,0,9.306253,3.4,106,98,'2002-02-08','en','/5Wquo3EjfDpK7S1BHcybuC3TZDO.jpg',2.766354558871628,3,'2026-09-10',2,NULL,NULL),(11536,'乱点鸳鸯谱','The Misfits','由于离婚和自身觉悟的提高，罗斯琳塔伯跟一群“不相称”的人做了朋友，包括成熟的牛仔盖、悲伤的飞行员、机械师吉都以及弄得头破血流、满身是伤的骑术表演者珀斯。他们的背景各不相同，又生活在离婚率全球最高的里诺镇，他们的婚姻故事曲折离奇。在他们的过把瘾就死的生活方式影响下，罗斯琳体验到了自由、愉快和激情，但是在罗斯琳和他们的思想、道德观念在现实中相冲撞时，她必须冒着失去朋友，甚至是丢失唯一真爱的危险去挽救无辜的生灵……','It shouts and sings with life ... explodes with love!',4000000,8200000,2.930058,6.8,72,124,'1961-01-01','en','/rkIkyPhT5oetT463HxpdIuct30l.jpg',2.7906862506009116,3,'2026-09-10',2,NULL,NULL),(11543,'Kingpin','Kingpin','After bowler Roy Munson swindles the wrong crowd and is left with a hook for a hand, he settles into impoverished obscurity. That is, until he uncovers the next big thing: an Amish kid named Ishmael. So, the corrupt and the hopelessly naïve hit the circuit intent on settling an old score with Big Ern.','You wouldn\'t want to meet these pinheads in an alley.',27000000,25023434,17.329269,6.7,244,113,'1996-07-04','en','/lVpejjxzBujSjLpxQ7hGe1s0wP2.jpg',3.1121650077278824,3,'2026-09-10',2,NULL,NULL),(11544,'星际宝贝','Lilo & Stitch','5岁女孩莉萝一直梦想养一只宠物狗，这天她终于得偿所愿，在姐姐的帮助下收养了一只流浪狗，并给它起名叫史迪奇。其实史迪奇并不是什么流浪狗，而是来自外星球的长着六支脚的危险分子，只是在流放中偷跑到地球上来的。为了在地球上隐藏身份，史迪奇只能“忍辱偷生”，把自己的两只脚藏起来，让自己看起来像是一只狗。在和莉萝相处的日子里，小女孩的善良单纯让她和史迪奇成了形影不离的好伙伴。然而另一方面，制造出史迪奇的外星人发现他逃走了，于是立刻全力出动，要将其逮捕归案！当外星人终于在地球上发现了伪装的史迪奇时，他们绑架了莉萝想逼史迪奇就范。为了救回自己的好朋友，也为了证明自己不是无可救药的危险分子，史迪奇只有使出浑身解数，放“脚”一搏了......','He\'s coming to our galaxy.',80000000,145771527,55.659988,7.1,1314,85,'2002-06-21','en','/cFuLvQJPoZpuruAtN3rVnMmLIH8.jpg',3.7109555801808725,3,'2026-09-10',2,NULL,NULL),(11545,'青春年少','Rushmore','韦斯·安德森令人目眩神迷的第二部长片，巧妙融合了成长叙事、法国新浪潮致敬与神经喜剧元素。十年级生马克斯·费舍尔（贾森·舒瓦兹曼 饰）是拉什莫尔学院课外活动最活跃的学生，却也是成绩最糟糕的学子。面临开除危机的他，与一位温柔的一年级教师（奥利维亚·威廉姆斯 饰）以及一位忧郁白手起家的百万富翁（比尔·默瑞获奖级表演）建立了不可思议的友谊。影片搭配经典英伦入侵摇滚乐作为背景音乐，打破了类型界限，以机巧的智慧、深沉的情感与鲜明的电影风格，精准捕捉了青春期的痛楚与蓬勃生机，交织出一幅精彩纷呈的校园生活画卷。[标准收藏]','Love. Expulsion. Revolution.',9000000,17096053,18.289303,7.5,676,93,'1998-09-17','en','/hSJ6swahAuZ8wM96lHDTwQPXUvZ.jpg',3.491192749063522,3,'2026-09-10',2,NULL,NULL),(11546,'警察学校7：进军莫斯科','Police Academy: Mission to Moscow','俄罗斯黑手党领袖康斯坦丁（朗•普尔曼 Ron Perlman 饰）制作的一款名为“游戏”的电子游戏风靡了世界，也令他的势力进一步扩大，对康斯坦丁感到束手无策的俄警方选择向国际求助，于是曾经参加过国际警察大会的拉萨雷受邀前往莫斯科。因恐高症差点不能毕业的警校学生康纳斯和拉萨雷的固定班底：卡伦、泰克布雷、琼斯（Michael Winslow 饰）以及哈里上尉一同前往莫斯科，岂料甫一下飞机，拉萨雷就上错了车，消失于莫斯科的茫茫人海，其余的国际战士们只得自行完成任务。哈里运用种种监控设备探听康斯坦丁的消息却被霉运缠身，康纳斯则深深迷恋俄方派来的翻译美女。另一方面，康斯坦丁计划在新版游戏中加入黑客程序以牟取暴利，卡伦和康纳斯各展所长，接近康斯坦丁找到了后者的犯罪证据……','Just when we thought the Cold War was over, leave it to these guys to heat it up again.',0,126247,11.946898,4.1,178,83,'1994-06-09','en','/3517XQ9LpoEykyYq2TuDNS45MPP.jpg',2.8689303775998476,3,'2026-09-10',2,NULL,NULL),(11551,'晶兵总动员','Small Soldiers','15岁的男孩阿兰•艾伯纳西（Gregory Smith 饰）是一个玩具经销商的儿子，他喜欢玩具，但和父亲不同，那种打打杀杀的战争游戏对阿兰更具有吸引力。而他顽固的父亲则坚持出售那些传统、温馨的玩具，即使生意举步维艰也在所不惜。  　　但小作坊式的玩具店总会受到大企业的冲击，阿兰家的店面临被兼并的命运。替父亲看店时，阿兰偷偷从批发商那进了几套格洛伯特雷奇公司最新推出的能够走动说话的战争游戏玩偶——分别是奇普•哈泽德率领的“精英突击队”和以阿切尔为首的“戈格奈茨”人。实际上，这两款玩偶内配军事设备，是军方为试验最新武器稳定性而秘密放置的。不久，这些危险的玩具引发了一场大混乱……','The few, the proud, and the small.',40000000,54682547,23.088571,6.2,511,110,'1998-07-10','en','/2nuUjSzHsoYlRvTPmLo7m7gCQry.jpg',3.2519653652828575,3,'2026-09-10',2,NULL,NULL),(11560,'一级重罪','High Crimes','旧金山女强人律师克莱尔•库比克 的丈夫汤姆•库比克 突然被FBI抓走，送往洛杉矶附近的军事法庭秘密受审，罪名则是在服役时于萨尔瓦多杀害9名平民。震惊的克莱尔不顾一切丢下工作来到洛杉矶，雇佣了当地军事法庭律师查尔斯•格瑞姆斯，共同与军方指派的年轻辩护律师中尉恩布里 一起为汤姆辩护。三人的调查取证遭到军方层层阻隔，甚至克莱尔的人身安全也遭严重威胁。坚信丈夫无罪的克莱尔与格瑞姆斯竭尽全力，却发现案件背后真相的复杂度远远超过了众人的想象……','Everything you trust. Everything you know. May be a lie...',42000000,63781810,14.046705,6.1,184,115,'2002-04-03','en','/vsEjRPDWydv37Vhd4cU7uj843IW.jpg',2.998690935011972,3,'2026-09-10',2,NULL,NULL),(11561,'傻瓜大闹科学城','Sleeper','一名食品店店主在动手术时被冷藏起来，当他苏醒过来时，已经是200年后的2173年。那时候地球上有一个残暴的君主，一群科学家决定想办法消灭他，他们想到了店主，于是把他解冻，利用这个无知而莽撞的小人物把暴君打倒。伍迪艾伦在片中饰演一个被冰冻两百年的现代人，到了未来，他的财产缩水，更恐怖的是人类不仅走回独裁的盲目崇拜，连“性”都交由机器代劳。','Woody Allen takes a nostalgic look at the future.',2000000,18344729,10.664202,7,200,89,'1973-12-17','en','/YTYSziZZP5aXt5CDvdEMwKDzme.jpg',3.067087439708822,3,'2026-09-10',2,NULL,NULL),(11564,'学校风云','Class of 1984','Andy 到一所高中去任教，另他意外的是这所高中的暴力程度。学生们都需要安检才能进入校园，而他们还在在校内校外经常犯事。而且这些学生也有手段去逃脱法律的制裁，Andy 对这些学生十分头痛……','Class of 1984. Is this the future?',4300000,0,5.643023,6.2,66,98,'1982-08-20','en','/qIu9UGDLeACl7YGuAAgTFfQ0j8I.jpg',2.761887678979634,3,'2026-09-10',2,NULL,NULL),(11565,'卧底肥妈2','Big Momma\'s House 2','FBI探员马刚（马丁•劳伦斯 Martin Lawrence 饰）最近和妻小闹得很不愉快，家人总是责备他太忙于工作而疏忽了照顾家庭。马刚这边正闹得情绪低落，却又有大案件找上了他。原来某日政府机关的电脑突然全部死机，过后发现很多绝密文档都被人浏览过了。FBI怀疑电脑工程师汤姆（马克•摩斯 Mark Moses 饰）有重大嫌疑，却又一直都找不到证据，于是只好派马刚再次出山。军命难违，本来不愿意再增加工作的马刚只有再次化身成肥胖的老妈子，以保姆身份混进了汤姆的家。在这里，他却意外发现了一个喧哗的世界，他和家里的三个孩子玩得不亦乐乎，亦知道了重拾天伦之乐的方法……','The momma of all comedies is back!!!',40000000,138259062,17.61292,5.4,371,99,'2006-01-26','en','/wlbov6pkgySqYZilZcO54f29Dg1.jpg',3.087144905252907,3,'2026-09-10',2,NULL,NULL),(11576,'疯狂世界','It\'s a Mad, Mad, Mad, Mad World','斯坦利．克雷默执导，联美公司制作的本片，讲述的是一个反映人性阴暗面的生活剧。史马尔考文超车坠崖身亡，在临死前透露在圣塔罗西公园埋着一大笔钱。知道这个消息的有八个人，各种不同的身份、不同的背景、不同的职业，为了独得这份意外之财，分别展开了可笑、惊险、疯狂的争夺。谁知他们所争夺的是15前被抢劫的赃款，他们所作的一切都在警方的掌握之中。宝藏终于被挖出，克劳派队长因为退休在即，而退休金又少得可怜，所以便假公济私，夺款潜逃，但最终被警方抓获，使发财梦想成为泡影。本片以嬉笑怒骂的方式，将人性的丑陋形态一表无遗，将人物角色刻划得入木三分，虽闻笑声，但却可见编导的良苦用心。','The biggest entertainment ever to rock the screen with laughter!',9400000,60000000,14.562991,7,140,163,'1963-11-07','en','/j4mWzOisSHFkaqIkq34l2mm8a5K.jpg',2.984573724390972,3,'2026-09-10',2,NULL,NULL),(11577,'比利小子','Pat Garrett & Billy the Kid','第56届柏林电影节的闭幕影片是1973年上映的西部片《比利小子》(Pat Garrett And Billy The Kid)的特别版。《比利小子》讲述的是在1881年的新墨西哥，一个名叫派特·加勒特(Pat Garrett)的人被被委任为警长，追捕自己从前好友比利小子(Billy the Kid)的故事。比利小子是美国历史上的传奇罪犯，真名为威廉·邦尼(William Bonney)，他年轻时四处流浪，最擅长的就是拔枪射击，据说他从拔枪到射击只要0.3秒。比利小子曾经谋杀了21个人，最后为派特·加勒特所击杀。  　　本片导演山姆·佩金法是赫赫有名的美国动作电影大师，为暴力美学的开山鼻祖，发明了用慢镜头、圣歌包装血腥射杀场面的技巧，后来香港著名导演吴宇森的电影就充满了对他的模仿。除《比利小子》外，萨姆·派金帕的代表作还有《午后枪声》(Ride The High Country 1962)、《日落黄沙》(The Wild Bunch 1969)、和喜剧片《牛郎血泪美人恩》等等。著名歌手鲍勃·迪伦不仅在影片中出演了角色，并为本片演唱了主题曲。','Best of enemies. Deadliest of friends.',4638783,11000000,4.495256,7.2,65,106,'1973-05-23','en','/vRDvPypWsjGs7spo7G5bz1cSacC.jpg',2.7805470471233313,3,'2026-09-10',2,NULL,NULL),(11583,'火车大劫案','The First Great Train Robbery','1855年的英格兰，著名黄金大盗爱德华·皮尔斯的最新目标是盗窃一列由伦敦开往克里米亚半岛的列车，因为这辆车上运满了黄金去给当地驻军充当军费。参与这项任务的还有皮尔斯美丽的妻子米利亚姆和英格兰最有名的开锁匠罗伯特·奥嘉。皮尔斯发现列车上存放黄金的仓库上面共有四把不同的锁，要用四把不同的钥匙才可以打开，而这四把钥匙分别在四个不同的人身上。所以这项任务十分艰难，但皮尔斯三人还是凭借着自己聪明的头脑盗走了车上的黄金……','Never have so few taken so much from so many.',6000000,0,12.434688,6.6,74,110,'1979-01-25','en','/4LqLUNoCwoPQNmrRuDZa0zC3hT8.jpg',2.8132004561920825,3,'2026-09-10',2,NULL,NULL),(11586,'驱魔人II','Exorcist II: The Heretic','四年前，可爱的瑞根（琳达·布莱尔扮演）为了摆脱附身的恶魔，因此经历了一场致命的抗争。四年后，她已经变成一个快乐正常的少女，但是事实真是如此吗？一个神甫（理查·波顿扮演）为了解开当年的恶魔之迷，于是使用催眠法，探索瑞根心底深处的潜意识，但是没有想到，却因此再度释放了深藏在瑞根心中的怨灵……','It\'s four years later... what does she remember?',14000000,30749142,11.543363,4.5,133,118,'1977-06-17','en','/ob8RggtTaGxjGdXddTUMOW001hC.jpg',2.849008820746778,3,'2026-09-10',2,NULL,NULL),(11588,'雾气蒙蒙','The I Inside','2002年7月19日，年轻男子西蒙·凯布尔（瑞恩·菲利普 Ryan Phillippe 饰）从昏迷中醒来。他在前一晚因胃痉挛被送入医院，结果却发现自己对过去两年里发生的事情全无印象，而记忆仍停留在2000年。在此期间，美丽温柔的克莱尔（莎拉·波利 Sarah Polley 饰）和自称妻子却非常冷漠的安娜（佩帕·佩拉多 Piper Perabo 饰）前来探望西蒙，两个女人的言谈举止和对过往的描述令他倍感不安。  　　西蒙认为自己正陷入一场阴谋之中，似乎有人正加害于他。他坚持要做一次全身检查。然而当他再次醒来时，却发现自己回到了2000年的7月3日，这次颇为诡异的时空跳跃也让西蒙切实回想起这两年间所发生的一切……','His story began when it all ended',8800000,0,3.789485,5.9,62,90,'2004-01-15','en','/flzdYr3jHiNoYd1jNt3ecZyEi7j.jpg',2.737105608833695,3,'2026-09-10',2,NULL,NULL),(11592,'杀心慈母','Serial Mom','母亲是一个把家里打扫得一尘不染、 为丈夫子女付出一切、追求完美的妈妈，其“美德”的极限发挥，竟是主动杀掉那些对他家人不好、甚至看不顺眼的人，彻底颠覆了贤妻良母及中产阶级的价值。本片运用了黑色喜剧的手法拍摄了一起离奇的连环凶杀案。极具讽刺意味。','Every Mom Wants to Be Wanted, But Not For Murder One!',13000000,7820688,6.170139,6.4,135,95,'1994-04-13','en','/3Qlycp68b6TQkC1fMMahpf04Oq8.jpg',2.9281260408812955,3,'2026-09-10',2,NULL,NULL),(11596,'New Nightmare','New Nightmare','Freddy\'s back … and he\'s badder than ever! Nancy, the historical nemesis of the man with the satanic snarl and pitchfork fingers, discovers that a new monstrous demon has taken on Freddy\'s persona. Can Nancy stop this new threat in time to save her son?','One, Two, Freddy\'s coming for you...',14000000,18090181,14.730796,6.4,291,112,'1994-10-13','en','/q5BWxfL1x34nyYSvA3Qo5odleGW.jpg',3.1247329703565567,3,'2026-09-10',2,NULL,NULL),(11598,'小银幕大电影','The Kentucky Fried Movie','这是一个关于成长的故事。嘉布里埃徘徊在两个女人之间，前任女友珍妮以及现任女友安娜(维吉妮·勒杜杨)，珍妮成熟性感、安娜年轻迷人，前者代表美好的旧日时光，后者热情却任性，嘉布里埃犹豫两者之间无法抉择。除了爱情，工作同样使他困惑，嘉布里埃在出版社担任编辑，却又怀念以前自由创作的日子。这一切的矛盾直到好友亚德忽然去世，嘉布里埃重新审视亚德短暂的人生时才幡然醒悟。亚德出版过四部小说，却在死后才获得文坛肯定，感情方面也同样徘徊在新旧两任女友的爱情边缘，终身寻觅至爱却不料猝死。亚德短暂的人生、以及生命中不可挽回的遗憾。','This movie is totally out of control!',600000,0,10.861167,6.4,66,83,'1977-08-10','en','/qk0iXBQgP6b4xfS2bIUNBSENJAn.jpg',2.778791650365935,3,'2026-09-10',2,NULL,NULL),(11600,'节选修订','Redacted','本片讲述了在伊拉克冲突中作战的年轻美国大兵的故事，并将侧重点集中在了多媒体覆盖下的现代战争模式上。由于年轻人冲动的本性和自身的局限，《节选修订》向我们展示了将一群年轻的美国士兵放置在一个精神上野心勃勃的境地的恶果。导演德·帕尔玛在搜集和整理了大量美伊冲突中美国士兵的经历，此番将镜头对准余热未消的伊拉克战争，可谓浑身是胆。',NULL,5000000,782102,3.792015,6.2,37,90,'2007-01-01','en','/ofXlW8FtBGVGSgRiaOIfnzR5koU.jpg',2.6336032206078603,3,'2026-09-10',2,NULL,NULL),(11601,'灵异骇客','Stir of Echoes','线路工人汤姆·维特斯基（凯文·贝肯 Kevin Bacon 饰）和麦姬（凯瑟琳·厄比 Kathryn Erbe 饰）是一对普通的美国夫妇，他们和儿子杰克（Zachary David Cope 饰）以及麦姬的妹妹丽莎（伊莲娜·道格拉斯 Illeana Douglas 饰）住在芝加哥的郊区，生活波澜不惊。丽莎青春年少，性感迷人，带着神秘的气质。在一次派对上，汤姆被丽莎催眠，继而经历了一场短暂而惊悸的梦境。这次经历让汤姆陷入不安中，奇怪的幻像自此时常出现在他的眼前，生活也开始为诡异的氛围所包围。与此同时，年幼的杰克似乎也和父亲有着同样的感受 ······','In every mind there is a door that should never be opened.',12000000,21133087,6.044161,6.5,330,99,'1999-09-10','en','/9CyJ5aYF27cITX1WSUTENeP4wBE.jpg',3.1437370461848966,3,'2026-09-10',2,NULL,NULL),(11615,'大卫·戈尔的一生','The Life of David Gale','贝茜•布鲁姆（凯特温斯莱 Kate Winslet饰）是纽约某新闻杂志的知名记者，她接到了一个任务是去采访一名死刑犯大卫•戈尔（凯文•斯帕西 Kevin Spacey 饰）。戈尔的罪名是强奸并谋杀了康丝坦斯•哈拉维，并将于周五下午6点被处以死刑，那么布鲁姆将要采访并记录的就是戈尔人生最后的三天，而此前戈尔拒绝了一切采访。布鲁姆起初对这个任务很不以为然，但在和戈尔的接触过程中，她发现一切并非表面呈现的那么简单，于是布鲁姆决定用仅剩的三天开始寻找真相……电影《大卫戈尔的一生》的导演艾伦•帕克凭借该片提名2003年柏林国际电影节金熊奖。','The crime is clear. The truth is not.',50000000,38955598,22.442241,7.3,480,130,'2003-02-21','en','/jXAksqSuByUQSh06NasPupajDym.jpg',3.3676104311834143,3,'2026-09-10',2,NULL,NULL),(11618,'The Haunting','The Haunting','Dr. David Marrow invites Nell Vance, and Theo and Luke Sanderson to the eerie and isolated Hill House to be subjects for a sleep disorder study. The unfortunate guests discover that Marrow is far more interested in the sinister mansion itself – and they soon see the true nature of its horror.','Some houses are born bad.',80000000,91188905,19.375768,5.2,369,113,'1999-07-23','en','/xwLldS5JnB4441iS50ha9ZrkaA8.jpg',3.070084722554796,3,'2026-09-10',2,NULL,NULL),(11619,'鼠国流浪记','Flushed Away','宠物鼠罗迪的奢华生活全被一只从下水道爬上来的流浪鼠西德搅了，无赖西德甚至把罗迪冲进了下水道。从没经历过世事的罗迪简直步入了噩梦一般，他光鲜的衣着和闪亮的皮鞋与肮脏的下水道城市格格不入。不过幸运的他遇到了丽塔，一个独立、勇敢、聪明、强悍的新新鼠类，更重要的是，她是个漂亮的女孩儿。 丽塔答应送罗迪回家，不想这个过程费尽了周折。地下世界里生活着一只妄想灭绝鼠类的疯疯癫癫的癞蛤蟆陶德。他一路对丽塔和罗迪围追堵劫。历尽千辛万苦，他们终于回到罗迪的家。然而在丽塔看来，罗迪的家虽然舒适却宛如金丝雀的鸟笼。已经对丽塔心生爱慕的罗迪该怎么办呢？他会放弃豪华的生活追随着心爱的姑娘去漂泊么？','Someone\'s Going Down',149000000,64459316,22.550135,6,874,85,'2006-10-22','en','/a75ODzZrNq0xvb2Fb2kTNvE4dOL.jpg',3.3378697179540664,3,'2026-09-10',2,NULL,NULL),(11620,'暴君焚城录','Quo Vadis','罗马尼禄皇帝在位时，指挥官维尼吉将宫大胜而回，对利吉国在罗马的人质丽吉儿公主一见钟情，尼禄遂将丽吉儿赏给维将军，未料丽吉却是基督徒，与维将军主张以征服和屠杀一统天下的理念，在心灵上无法沟通，遂逃离。\r 　　为追回丽吉儿，维将军寻至基督徒秘密集会处，初闻彼得关于基督的说教，回程再见到丽吉儿时，虽然此时两人已相爱，但对基督的精神仍感迷感。在回皇宫时碰上疯狂的尼禄为建尼禄之城而焚烧罗马城，维将军赶回火场，救出丽吉儿，并率领民众突围，难民涌入皇宫，皇后城护维将军对丽吉儿的爱，怂勇禄将焚城之罪嫁祸基督徒，将捕获的基督徒或喂猛狮或钉十字架或烈火焚烧。圣彼得亦被子钉十字架而亡，但所有的基督徒均高唱圣歌就义，维将军当场揭发真相，罗马大军反正，尼禄自杀结束暴行。','THIS IS THE BIG ONE! The splendor and savagery of the world\'s wickedest empire! Three hours of spectacle you\'ll remember for a lifetime!',8250000,30000000,7.973109,7,63,171,'1951-11-08','en','/dqF1dattMNiwGjPSphu2VSi558Q.jpg',2.7762761648768612,3,'2026-09-10',2,NULL,NULL),(11622,'超时空宠爱','Blast from the Past','片中讲述主角的父母为美国国防部专家，冷战期间自己家地下有个核避难所，一次空难主角父母误以为核战爆发，躲入避难所。30年后主角已经30岁，被派到地面去探查核污染情况，搞出很多笑料。片中对于核避难所的描述深得生存狂的精髓。','She\'d never met anyone like him. He\'s never met anyone... Period.',35000000,40263020,8.737058,6.3,245,112,'1999-02-12','en','/7UoX2OLoOlxFkgvrKLLA31C0hbm.jpg',3.06335635463932,3,'2026-09-10',2,NULL,NULL),(11624,'性爱宝典','Everything You Always Wanted to Know About Sex *But Were Afraid to Ask','本片由导演伍迪·艾伦亲自出演，全片以章回的形式共提出了七个问题，分别触及了七个敏感而又令人尴尬的性的话题。依次分别是：“要春药吗？”、“何谓兽奸？”、“女人性冷感之迷中”、“同性恋异装癖”、“什么叫性异常”、“性学博士的实验可信吗？”、“射精时会怎样”。虽然不像武林秘笈中的某某宝典一样，传授的是不二法门的独家心法，但这部宝典还是力争做到百科全书一样的全面和权威。全片以章回的形式共提出了七个问题，也自然而然地分成了七段，它们分别触及了七个敏感而又令人尴尬的性的话题。',NULL,2000000,18016290,13.223111,6.6,215,88,'1972-08-06','en','/A1ZNhNd8FV8kCW39OeDelokT0tv.jpg',3.064535236645349,3,'2026-09-10',2,NULL,NULL),(11631,'妈妈咪呀','Mamma Mia!','苏菲（阿曼达·塞弗里德 Amanda Seyfried 饰）与斯盖伊（多米尼克·库珀 Dominic Cooper 饰）的爱情即将修成正果，两人正在为马上来临的婚礼紧张筹备着。不过，在苏菲的心中，一直有一个愿望，就是希望父亲能够在婚礼当天亲手将自己的手送到新郎的手上。可惜，妈妈（梅丽尔·斯特里普 Meryl Streep 饰）一直没有告诉过她到底谁是她的亲生父亲。不得已，苏菲偷看了妈妈的日记，发现其上记录的三个人中的一个很可能就是自己的亲生父亲。于是，她发出了三张请柬邀请他们来参加她的婚礼，想通过这短暂的接触，最终从三人中找出自己的爸爸。于是，在闺蜜的帮助下，在这美丽的希腊小岛上，上演了一出别具特色的寻父记。最终苏菲是否能找出自己的亲生父亲，举行一场完美的婚礼？','Take a trip down the aisle you\'ll never forget',52000000,609841637,30.780599,6.4,1386,108,'2008-07-03','en','/miF8AW7kMfJKlHsPIUwpzPgtsvJ.jpg',3.5316448359309236,3,'2026-09-10',2,NULL,NULL),(11632,'名利场','Vanity Fair','故事发生在十九世纪的英国，贝姬（瑞茜·威瑟斯彭 Reese Witherspoon 饰）出生于贫寒家庭，但是，野心勃勃的她做梦都想要能够跻身上流社会，为此，贝姬来到了爵士彼得考利（鲍勃·霍斯金斯 Bob Hoskins 饰）家中，担任起了家庭教师的职务。聪明伶俐的贝姬很快就获得了姑妈玛蒂尔达（艾琳·阿特金斯 Eileen Atkins 饰）的认可和信任，之后，贝姬跟随玛蒂尔达来到了梦寐以求的伦敦。\r 　　在伦敦，贝姬同曾经的好友艾米利亚（萝玛拉·嘉瑞 Romola Garai 饰）重逢了。艾米利亚深爱着军官乔治（乔纳森·莱斯·梅耶斯 Jonathan Rhys Meyers 饰），为了同他结婚不惜背弃了家庭，与此同时，贝姬亦同考利家的继承人罗顿（杰姆斯·鲍弗 James Purefoy 饰）秘密踏入了婚姻的殿堂。然而，等待着他们的并非光明的前程，而是残酷的战争。','On September 1st, a heroine will rise.',23000000,16123851,6.618149,5.5,73,141,'2004-09-01','en','/6GCjrrd1XIl8VSwjKo8c94LTwtd.jpg',2.766775188200834,3,'2026-09-10',2,NULL,NULL),(11635,'单身男子俱乐部','Old School','米奇·马丁（卢克·威尔森 Luke Wilson 饰）、弗兰克·理查德（威尔·法瑞尔 Will Ferrell 饰）和伯纳德·坎贝尔（文斯·沃恩 Vince Vaughn 饰）是三人自大学时期就感情笃深的死党。毕业后数年，他们有了各自的小圈子，但心中对友情的看法始终没有改变。某晚，米奇回家后撞见女友正在大开性派对，他愤怒之下搬了出来，并落脚在母校附近的一幢屋子中。与此同时，弗兰克和伯纳德各自的生活也出现问题，他们相继聚到米奇的寓所。伯纳德打算仿照大学宿舍的模式，将这里设立成不被世俗侵扰的兄弟会。  　　大学的生活自由自在，又没有该死的校规限制，这让三个大男孩找到久违的快乐……','All the fun of college, none of the education.',24000000,87055349,24.70166,6.6,541,91,'2003-02-21','en','/nYtuwNHpEoIbTgS3aFPSEwZNN6l.jpg',3.319519831458764,3,'2026-09-10',2,NULL,NULL),(11637,'小鬼上路','Are We There Yet?','单身男子尼克·普森斯（艾斯·库柏 Ice Cube 饰）是一个玩世不恭的家伙，他似乎更享受追求心仪对象的过程，而对成功后的感情经营全无兴趣。这一次，他将目标锁定在单身妈妈苏珊娜·金斯顿（妮娅·朗 Nia Long 饰）的身上。之前失败的婚姻让苏珊娜对待感情颇多忌惮，谨小慎微，任凭尼克如何大献殷勤也难有建树。适逢圣诞节临近，苏珊娜因工作原因不得不和一双子女分处温哥华和纽约两地，这令她倍为伤感。尼克瞅准时机，自告奋勇去接11岁的琳赛（艾丽莎·艾伦 Aleisha Allen 饰）和7岁的凯文（菲利普·丹尼尔·波顿 Philip Bolden 饰）来温哥华与母亲团聚。\r 　　令尼克始料未及的是，琳赛和凯文似乎很讨厌任何想追求母亲的男人，他们为尼克设下了无数艰难险阻………','24 hours. 350 miles. His girlfriend\'s kids. What could possibly go wrong?',32000000,97918663,13.590677,5.2,221,95,'2005-01-20','en','/guDkMD4wrZ1BGUO7DFFBVzaiGij.jpg',2.9742740127583507,3,'2026-09-10',2,NULL,NULL),(11638,'Guess Who','Guess Who','The fiancé of an African-American woman who\'s met with skepticism and suspicion from her father when she takes him home for the all-important introduction. As the wedding approaches, Dad must come to terms with his future son-in-law.','His house. His rules. Some in-laws were made to be broken.',35000000,68915888,3.74263,5.5,225,105,'2005-03-25','en','/8BF6qSAANBvhEPZxQVTUiZbfiOy.jpg',2.976014709878428,3,'2026-09-10',2,NULL,NULL),(11644,'凶线','Blow Out','在布莱恩·德·帕尔玛精湛打造的这部引人入胜的影片中，约翰·特拉沃尔塔贡献了其演艺生涯最出色的表演之一，饰演一位坚信自己意外录下政治刺杀案的电影音效师。为揭露真相，他寻求一位可能目睹罪案的关键证人（南希·艾伦 饰）协助，而她自身也可能身处险境。影片以令人震撼的风格表现、错综复杂的剧情、深刻的人物塑造，以及对1980年代初费城社会氛围的粗粝再现，成就了一部独一无二的美国偏执狂式惊悚片，同时也对电影制作进行了一番鬼魅般的反思。','Murder has a sound all of its own!',18000000,12000000,13.628601,7.3,236,108,'1981-07-24','en','/uFzMscVLDrTaYd6KXOXlr6dly7w.jpg',3.139454850773525,3,'2026-09-10',2,NULL,NULL),(11648,'征婚广告','Must Love Dogs','三十出头的萨拉是一所幼儿园的老师，温柔贤惠、大方得体，原本开朗的她却因为婚姻失败受到不小的打击，决定这辈子也不想再谈婚论嫁。为了萨拉的幸福着想，姐姐卡罗尔和克里斯汀决定瞒着她在配对网站上发布征婚广告。萨拉的魅力还不错，很快广告就有了很多回音，接着是一连串糟糕的约会。年轻英俊的杰克对萨拉产生了兴趣，两人一见钟情，可处处要求完美的杰克却让萨拉有些犹豫。这时，莎拉在幼儿园却遇见了另外的机会——单身父亲鲍伯，刚离婚的他迷人、幽默、有风度，完全是萨拉心中的理想伴侣。',NULL,30000000,58405313,11.120167,5.8,140,98,'2005-07-21','en','/252PdRj3y2S05DC4oSf2qk2vva3.jpg',2.9186738963995507,3,'2026-09-10',2,NULL,NULL),(11658,'Tae Guk Gi: The Brotherhood of War','태극기 휘날리며','In 1950, in South Korea, shoe-shiner Jin-tae Lee and his 18-year-old old student brother, Jin-seok Lee, form a poor but happy family with their mother, Jin-tae\'s fiancé Young-shin Kim, and her young sisters. Jin-tae and his mother are tough workers, who sacrifice themselves to send Jin-seok to the university. When North Korea invades the South, the family escapes to a relative\'s house in the country, but along their journey, Jin-seok is forced to join the army to fight in the front, and Jin-tae enlists too to protect his young brother. The commander promises Jin-tae that if he gets a medal he would release his brother, and Jin-tae becomes the braver soldier in the company. Along the bloody war between brothers, the relationship of Jin-seok with his older brother deteriorates leading to a dramatic and tragic end.',NULL,0,15,9.572705,7.4,133,140,'2004-02-05','ko',NULL,2.9788305515978655,3,'2026-09-10',2,NULL,NULL),(11661,'Joyeux Noël','Joyeux Noël','第一次世界大战在一九一四年的时候仍然处于胶着状态，参战的欧洲各国在大大小小的战役里争夺自己的利益，各个阶层的人不断的拖入战争。德国男高音斯普林克，被迫放弃自己的艺术生涯和女友安娜，参军入伍。圣诞节前的平安夜，安娜来看望斯普林克，也为士兵们带来了她柔美的歌声。战场上所有的人都被这雪夜的仙乐所温暖，德国人爬出战壕，高举点缀璀璨的圣诞树；英国人也吹起了悠扬的苏格兰风笛；所有的战士放下武器，走到一起，相互预定度过一个和平安详的圣诞节。然而，短暂的和平还是被上级的命令打破，相互残杀依旧不可避免。  故事发生在1914年的冬天，第一次世界大战战场上一块三角形的阵地，英军、法军抵制德军的进攻。英军中有想在战争中有所作为的兄弟，也有与世无争的牧师军医巴尔迈尔；德军里有刚刚从舞台上征招入伍的演员斯普林克；法军中有妻子即将临产的青年军官阿德贝尔特，每天闹表调到10点、给妈妈准备咖啡的彭瑟尔。因为战争，他们远离佳人，聚集在一起。战争是残酷的，咫尺之遥的战壕里双方死伤都很大，眼睁睁看着战友和兄弟倒下，却无法救助，士兵们都被眼前的血腥吓住了，内心充满恐惧。  寂静的平安夜，英国牧师吹响了风笛，优美动听的笛声回荡在布满尸体的战场上；斯普林克说服女友安娜陪自己离开豪华明亮热闹的军官聚会，来到寒冷紧张的战场上为士兵们延长，他一点点走出战壕，把装饰璀璨的圣诞树也摆在了战壕上；英国风笛慢慢随着歌声飘散战场上空，士兵们也慢慢走出封锁线。三个军官达成协议，要平安度过平安夜，快乐地过个圣诞节。于是，三国士兵走到了一起，度过了一个愉快平安的平安夜。  自从那夜后，士兵们建立起了深深的友谊，不愿意任何人在战争中受伤：德军轰炸英军、法军的时候，德军就让他们躲在自己的战壕里，法军轰炸德军是就让德军躲在自己的战壕。可是，天下没有不透风的墙，不久，后方军官就发现了情况，战争又不可避免地开始了。','France 1914. A moment of humanity that made history.',22000000,17709155,13.960945,7.2,212,116,'2005-11-09','fr','/wQldU9HSVa3lCAp7RSsENe8alF6.jpg',3.1034005464031127,3,'2026-09-10',2,NULL,NULL),(11665,'糊涂侦探','Get Smart','冷战结束后，天控局面临被解散的危险，但是这个美国最大的特务机关，依旧担负着重要的使命。不过，近期天控局总部却遭受了突发性袭击，导致特工们都有被身份曝光的危险。其中也包括强壮如牛、身手不凡的23号特工（道恩•强森 Dwayne Johnson 饰）。总部经过研究发现，袭击事件是一个叫盖不达集团的，为了迎敌，总部对分析家麦克斯韦（史蒂夫•卡瑞尔 Steve Carell 饰）委以重任，后者终于等到了一展身手的机会。于是，他积极参与了对付盖不达的行动，不过之前的两次演习都被他搞砸了。唯一的收获是，他跟99号特工（安妮•海瑟薇 Anne Hathaway 饰）结成了搭档，后者是唯一不怕身份曝光的特工。他们在飞机上遇到了一个疑似的恐怖分子，但是当他们出手时，却意外陷入了对方的圈套。此后，这对欢喜冤家又接连遇到一系列令人啼笑皆非的困境。','Saving The World...And Loving It!',80000000,230685453,23.496054,6,1051,110,'2008-06-19','en','/lJ23wqzbGX8wwMdlwp1QhNGmIeb.jpg',3.3785066904801457,3,'2026-09-10',2,NULL,NULL),(11667,'街头霸王','Street Fighter','据风靡全球的格斗游戏“街头霸王”游戏改编的真人版本，尚格 云顿主演，喜欢街霸的切莫错过！经逊将军掳走了六十三名解放工人为人质，威胁联军部队在七十二小时内交出二十亿赎金，联军基路上校与甘美将军查探比逊总部保垒地点企图救人，却因记者春丽把事情越弄越复杂。','The fight to save the world is on!',35000000,99423521,19.286099,4.1,325,102,'1994-12-22','en','/yBW6JgyKiQ7WpNc7o8B1uhl9giU.jpg',2.9481679766113054,3,'2026-09-10',2,NULL,NULL),(11676,'再无可失','Nothing to Lose','任职于广告公司的尼克（蒂姆•罗宾斯 Tim Robbins 饰）深爱自己的妻子，时常为工作拖累而不能陪伴妻子感到内疚，这天客户取消了约会使尼克可以提前回家，然而他看到的却是妻子正和自己的上司偷情，万念俱灰的尼克一言不发开车离家，劫匪泰伦斯（马丁•劳伦斯 Martin Lawrence 饰）半路冲上了尼克的车打劫，可身材矮小的泰伦斯根本无法唬住狂暴状态的尼克，尼克驾车一路狂奔，将泰伦斯带到了亚利桑那。身无分文的两人很快开始为钱担忧，在泰伦斯的示范下，尼克很快也学起了行劫，并且计划偷窃上司的巨额现金。初出茅庐的尼克二人组被拥有当地“犯罪专属权”的另一对儿匪徒痛打，侥幸逃脱后尼克与泰伦斯开始执行盗窃计划，而他们的犯罪行为很快遭遇了一系列变故……','When the odds are against you, sometimes the only bet is yourself.',25000000,0,8.618208,6.3,174,97,'1997-07-18','en','/umbzQyRMeB1oHTKiymTlH591xNB.jpg',2.985826560384244,3,'2026-09-10',2,NULL,NULL),(11678,'垂直极限','Vertical Limit','彼得·盖瑞特（克里斯欧唐纳饰）的父亲带著一对儿女攀爬悬崖，不料发生意外，为了逼儿子救回自己和姐姐，父亲迫不得已割断绳子牺牲自己，彼得虽然获救，但对自己相当自责，他放弃了成为一个登山好手的志愿，成为了一名摄影师，而他的姐姐却追随父亲踏入了登山界。  　　有一天，他的姐姐在挑战喜马拉雅山的最高峰——圣母峰时遇险，包括她在内的整个登山队都被困在海拔2600英尺高峰上的岩洞里，彼得不惜冒生命危险与时间竞赛，临时组织一队营救队伍，攀登世界第一高峰，以求救回生命危在旦夕的姐姐和她的攀山队伍。','The Mountain Will Decide.',75000000,215663859,13.318744,5.9,283,124,'2000-12-08','en','/aezVeIzvdyXKGjqxosgOMFosJIS.jpg',3.0730177638489473,3,'2026-09-10',2,NULL,NULL),(11679,'极限特工2','xXx: State of the Union','特工头子奥古斯塔斯这次遇到了大麻烦，他和武器专家托尼在国家安全局的地下指挥中心竟遭到杀手追杀。奥古斯塔斯怀疑这些杀手是被政府内部激进分子指派，蓄意颠覆国家政权，于是他希望物色一名合适的特工戳穿害群之马的险恶阴谋。最后，奥古斯塔斯找到了最佳人选前特种兵戴瑞斯，他因殴打上级军官现在正被军警监禁。奥古斯塔斯想方设法帮助戴瑞斯越狱成功，并说服他接受了这一国家重任。于是，戴瑞斯开始行动了！','Prepare for the next level',60000000,71073932,36.689223,4.7,549,101,'2005-04-27','en','/1WmatXPnuSajAQYwidbx4PXl7uT.jpg',3.1056405952127437,3,'2026-09-10',2,NULL,NULL),(11683,'活死人之地','Land of the Dead','未来的世界，僵尸霸占了地球的大部分领土，而残存的人类则躲在一座围墙坚固的铁甲城里苟且偷生。城市的首领考夫曼（丹尼斯•霍珀 Dennis Hopper 饰）唯利是图，疯狂压榨着城市的底层人民。为了保证食物和物品的运输，城市里有着一群特殊的人群——雇佣兵军团。他们专门负责到城外僵尸地带的物资运输。雇佣兵队长莱利（西蒙•贝克尔 Simon Baker 饰）和助手切洛也是唯利是图的人，他们都渴望紧张赚足金钱实现自己的目的。这时，城外的僵尸开始进化，他们懂得了如何组织和进行交流，这块人类最后的安身之所已经岌岌可危，而切洛为了敲诈考夫曼，私自控制了装甲车部队……','The dead shall inherit the Earth.',15000000,46770602,15.262492,6,381,93,'2005-06-24','en','/ZJDLeiFFQ5JZYJLf37XSg6Zwzs.jpg',3.148075072799546,3,'2026-09-10',2,NULL,NULL),(11687,'时空急转弯','Les Visiteurs','故事发生在十二世纪的法国，一种神奇且危险的时光穿梭魔力药水令戈德弗鲁瓦骑士（让·雷诺 Jean Reno 饰）和其仆人拉弗里普伊（克里斯汀·克拉维尔 Christian Clavier 饰）一同穿越到了二十一世纪的美国芝加哥。翻天覆地的变化和车水马龙的大街让这两个“老古董”既好奇又恐惧，就在此时，一位名为茱莉亚（瓦莱丽·勒梅西埃 Pierre Aussedat 饰）的美丽女子出现在了两人的面前。巧合的是，这位茱莉亚不是别人，竟然就是戈德弗鲁瓦骑士的后代。  　　很快，戈德弗鲁瓦骑士和拉弗里普伊便明白了他们的处境，与此同时，一个严重的问题浮出了水面——如果他们无法返回属于自己的时代，那也就意味着，他们的后代，也就是茱莉亚也将不复存在。十万火急之下，戈德弗鲁瓦骑士一行人开始寻找起了回到过去的方法。','They Weren\'t Born Yesterday!',0,0,8.893676,7.1,420,107,'1993-01-27','fr','/eEtLpbKCEne4R7hFaoZ2ETofHTN.jpg',3.2745700246083675,3,'2026-09-10',2,NULL,NULL),(11688,'变身国王','The Emperor\'s New Groove','很久以前，在南方的崇山峻岭中有一座神奇的王国。王国里的人们不但丰衣足食，能够和睦相处，而且每个人都充满乐趣，懂得生活。只是年轻的国王卡克十分骄傲自负，爱慕虚荣。一天，他在筹划自己18岁的生日庆典时突发奇想，决定修建一个山间的水上乐园。尽管这个建议遭到了众人的反对——因为这将淹没王国中的一个村庄，但他仍旧一意孤行。  　　与此同时，一个篡权夺位的大阴谋正在秘密进行，幕后主使就是国王前任的行政顾问扎玛。通过周密的安排，国王卡克终于落入圈套——被库龙克变成一只骆驼。如今卡克发现自己已经成为巴夏的一份财产。巴夏是一个地位低下的牧民，他的家所在的村庄已被那座水上乐园淹没。  　　一次偶然事件使得巴夏得知了卡克的身份，两人私下达成协议，只要巴夏把卡克带回城市，并帮助他夺回王位，卡克就下令将水上乐园移走。于是，一个大胆的计划开始实施，一次疯狂的行动正式展开了……','It\'s All About.....ME!',100000000,169327687,51.113717,7.2,1490,78,'2000-12-09','en','/wwbgkXQBEKtnyIJapk6gUgWkVw8.jpg',3.7563777673142598,3,'2026-09-10',2,NULL,NULL),(11690,'拳霸天下','Bloodsport','本片是根据真实事件改编而成。尚克劳范达美在本片中饰演一位功夫高手，必须在毫无规则限制的拳赛中为自己的性命放手一搏。尚克劳范达美饰演法兰克，参加一种传自香港九龙的非法秘密拳赛，并希望成为首位赢得该赛事的西方人。然而在赢得第一场胜利后，法兰克发现自己要烦恼的事不只是要如何赢得冠军，情报局探员要他退出比赛，一位美丽的记者想报导他的故事，更不用说他的对手想要他的小命！','The true story of an American ninja.',1500000,11806119,17.49699,6.6,363,92,'1988-02-26','en','/jq5oQHs7sfNrkyAzTXyGlC8jW89.jpg',3.2029303187376295,3,'2026-09-10',2,NULL,NULL),(11692,'星际冒险王','The Adventures of Pluto Nash','The year is 2087, the setting is the moon. Pluto Nash, the high-flying successful owner of the hottest nightclub in the universe, finds himself in trouble when he refuses to sell his club to lunar gangster Mogan, who just happens to be helping the mysterious Rex Crater mastermind a plan to take over the entire moon.','Action\'s future has arrived...',100000000,7103973,12.092241,4.4,142,95,'2002-08-15','en','/96vvhLWWDosS1zRrfQ6XEGAzByL.jpg',2.855254191151175,3,'2026-09-10',2,NULL,NULL),(11697,'双虎屠龙','The Man Who Shot Liberty Valance','一位因击毙恶名昭彰的歹徒而名声大噪的参议员，回到小镇参加老友的葬礼，并道出了当年事迹背后的真相。','Together For The First Time - James Stewart - John Wayne - in the masterpiece of four-time Academy Award winner John Ford',3200000,8000000,11.735287,7.4,265,123,'1962-04-22','en','/4C1R0LEivLjbv3swAzJfzh0tzXl.jpg',3.1760534084453313,3,'2026-09-10',2,NULL,NULL),(11699,'坏中尉','Bad Lieutenant: Port of Call New Orleans','飓风后的奥尔良，全城陷入瘫痪。当地的监狱中，所有狱警和囚犯已全部撤离，却有一个囚徒被遗忘在这里。警官特伦斯·麦克多纳和同事巡查牢房时发现了他，特伦斯出手相助。这个英勇举动使他晋升为中尉，但他的脊柱也受到严重损伤，从此只能靠药物缓解疼痛。不断加剧的疼痛令各种药物失去效力，特伦斯在这一过程中饱受折磨，他不得以求助毒品，身体和经济状况都接近崩溃边缘，脾气也越来越糟。一个英雄警察逐渐堕落。不久，城内发生一起灭门惨案，大毒枭达费特具有重大嫌疑。特伦斯受命调查此案，在这一过程中，他泯灭已久的良知逐渐复苏……','The only criminal he can\'t catch is himself.',25000000,10589102,17.339852,6,326,122,'2009-09-11','en','/928yUo4lHXToTI7PgWyY67SZ6VX.jpg',3.120219339337793,3,'2026-09-10',2,NULL,NULL),(11702,'替身杀手','The Replacement Killers','周润发扮演一位来自中国的冷面杀手李强，为把母亲和妹妹从上海接到美国，他向纽约曼哈顿的亚裔黑帮头目魏先生借钱。魏先生的儿子在警察辑毒行动中被击毙，负责这次行动的斯坦警官就成为了魏先生的仇人。作为借钱的代价，魏先生让李强去杀斯坦警官年仅７岁的儿子。关键时刻，李强良心发现，他决定枪下留人。李强的决定招来杀身之祸。他的家人也危在旦夕。李强打算回国保护家人，他约伪造护照的梅格在机场相会，然而，他的行踪被魏先生所雇佣的杀手们发现了，一场生死追逐由此拉开帷幕。','Kill or be replaced.',30000000,19204929,9.607391,6,127,87,'1998-02-06','en','/p8ThLDxnOjc9KKP4KoBxwlrRDxd.jpg',2.9043170980122013,3,'2026-09-10',2,NULL,NULL),(11770,'少林足球','少林足球','二十年前有“黄金右脚”之称，但因一场被师兄强雄设计陷害的比赛而断了右脚自此名誉扫地的明锋偶然认识了有惊人脚力的星，说服了对方练习足球参加不久会举行的全国超级杯足球大赛，星找来曾一同在少林寺习武的一帮师兄弟，并唤醒了他们快被平庸生活消磨光了的潜在斗志，众人经过历练终结成名副其实的“少林队”。阿梅以太极功夫制造馒头，令星十分敬佩与之成了好友，但阿梅不只当星为好友，只因样貌奇丑而自卑一直不敢表露心意。  “少林队”在全国超级杯足球大赛上屡战屡捷杀进决赛，不想卫冕之战对手竟是强雄所带领的“魔鬼队”，同二十年前一样，强雄再耍阴招令“少林队”节节败退，关键时刻，阿梅现身。','Get ready to kick some grass!',0,42776760,17.54768,6.6,491,113,'2001-07-12','cn','/rwfeeT02j1z5SBgJOH2eOwNCNQO.jpg',3.2787213768342234,3,'2026-09-10',2,NULL,NULL),(11775,'真情假爱','Intolerable Cruelty','作为南加州最好的离婚官司律师，迈尔斯•马西（乔治•克鲁尼 饰）的精明之道令客户非常满意。而玛丽莲（凯瑟琳•泽塔-琼斯 饰）这个拜金女郎想利用自己的美色嫁入豪门后以离婚的名义取得高额的财产。而玛丽莲的丈夫请来了迈尔斯，以确保自己能在离婚官司中稳操胜券。  　　玛丽莲的美丽吸引住了迈尔斯，但他还是帮自己的客户保全了家产。深深不忿的玛丽莲想要报复迈尔斯，便想假装与他结婚。  　　他们一边算计对方，一边被对方吸引，到底爱情的力量又能否胜出呢？','They can\'t keep their hands off each others assets.',60000000,119940815,22.620125,5.8,391,100,'2003-09-02','en','/7K8hDwOWsZv0MluyrB8nWlhJOgB.jpg',3.149337475173837,3,'2026-09-10',2,NULL,NULL),(11778,'猎鹿人','The Deer Hunter','本片追踪了一群钢铁工人伙伴——从宾夕法尼亚州的熔炉到阿勒格尼山脉清凉的猎场，再到越南致命的战争熔炉。罗伯特·德尼罗出色地饰演了迈克尔，这群人天生的领袖。本片是一部关于友谊与勇气的灼热戏剧——以及在艰难困苦中这些品质将经历怎样的考验。[环球影业]','One of the most important and powerful films of all time!',15000000,50000000,19.786392,7.8,921,183,'1978-12-08','en','/x6yEZCGoX4JnDsUUpycwAofsqR1.jpg',3.6440029085973435,3,'2026-09-10',2,NULL,NULL),(11780,'赤胆豪情','Rob Roy','麦格哥族领袖Rob Roy向侯爵借钱，以帮助整个民族捱过败政上的难关，可是Rob Roy遇人不淑，堕入侯爵亲信所设计的陷井，几乎被全族人鄙弃。Rob Roy的妻子玛莉安抚着丈夫的心灵。怎知狂妄之徒竟强暴了玛莉。然而在种种压迫下，玛莉依然坚持地活下去，丈夫也因而誓言要一雪前耻。','Honor made him a man. Courage made him a hero. History made him a legend.',28000000,31596911,10.703456,6.5,148,139,'1995-04-13','en','/3NYeM8eAEhF9CyChCYV9Rd6Y2Jn.jpg',2.9644496168819514,3,'2026-09-10',2,NULL,NULL),(11798,'这就是英格兰','This Is England','故事发生在1983年，12岁的肖恩是一个在阴郁海滨小镇孤独成长的男孩，他的父亲死于福克兰群岛战争。当本地光头党群体接纳他时，他找到了新的男性榜样。在那里，他结识了康博——一个刚出狱、年长且充满种族主义的光头党。随着康博的帮派开始骚扰当地少数族裔，一场将肖恩从天真推向世故的成长仪式就此展开。[IFC Films]','Run with the crowd, stand alone, you decide.',2380000,8176544,8.395624,7.4,363,101,'2006-09-12','en','/6ZVx7wLrlgSKxkYC2CRg6Zek0fG.jpg',3.2619628652667356,3,'2026-09-10',2,NULL,NULL),(11802,'太空黑猩猩','Space Chimps','《太空黑猩猩》是由美国二十世纪福斯电影公司发行，由科克·德·米科执导，安迪·萨姆伯格、切瑞·海恩斯、帕特里克·沃伯顿联合配音。该片于2008年7月18日在美国上映。该片讲述了汉姆被美国国家航空和宇宙航行局选中，和其他两位黑猩猩一起去外太空寻找失踪船员的故事。','Houston, we have a problem!',37000000,63800345,6.293217,5.2,99,81,'2008-07-17','en','/ecAKgzlt78OvEVpZURYYdSz8K5v.jpg',2.8153999454745557,3,'2026-09-10',2,NULL,NULL),(11804,'鬼讯号','White Noise','强纳森瑞佛（米高基顿饰演）在妻子安娜失踪以后，一直郁郁寡欢。一天，一个神秘男子找上强纳森，神秘男子问他是否想听亡妻安娜的声音，半信半疑的强纳森在听了安娜的声音后才相信爱妻已经遇害。而神秘男子给强纳森听的的声音竟是安娜遇害以后才录到的，原来男子专门研究EVP(Electronic Voice Phenomenon)「超自然电子异象」，他们能利用现代电子仪器追踪并记录到往生者死后的声音或影像，换句...','The line separating the living from the dead has been crossed.',10000000,91196419,14.447723,5.6,261,101,'2005-01-07','en','/8xqlaqWRSryvurLsqKAsNkV2soH.jpg',3.0353685038099854,3,'2026-09-10',2,NULL,NULL),(11812,'爱情甜不辣','The Sweetest Thing','克里斯蒂娜（（卡梅隆·迪亚茨 Cameron Diaz 饰））与好姐妹简（塞尔玛·布莱尔 Selma Blair 饰）和康妮（克里斯蒂娜·艾伯盖特 Christina Applegate 饰）常常出入各大酒吧与夜总会，在克里斯蒂娜的眼里，没有她搞不定的男人，她深知自己魅力无穷，也十分享受被帅哥俊男包围和簇拥的快感，但同时她也明白，那些为了自己的容貌和身材神魂颠倒的男人们没有一个值得自己托付终身。一次偶然中，克里斯蒂娜结识了名叫彼得（托马斯·简 Thomas Jane 饰）的男子，对于克里斯蒂娜风情万种的热烈攻势，他居然视而不见很快就拍屁股走了人。第一次尝到失败滋味的克里斯蒂娜燃起了斗志，她不相信彼得真的对自己无动于衷。在姐妹们的帮助下，一场男女之间的猫鼠游戏就此展开，与此同时，真爱也悄悄降临到了她们的头上。','A romantic comedy without the sugar.',43000000,68696770,18.65632,5.3,280,84,'2002-04-12','en','/qLysz4B5YmiDq52Op0zq4eD75LC.jpg',3.033061822492904,3,'2026-09-10',2,NULL,NULL),(11817,'防弹武僧','Bulletproof Monk','一卷神秘的中国古代卷轴，由于蕴藏着巨大的力量，邪恶的坏蛋们个个都想得到它来统治世界；一个来自中国西藏的无名武僧（周润发 饰），为了保护着卷卷轴，一直过着颠沛流离的生活，他几乎躲遍了世界的每一个角落。直到有一天，武僧觉得累了，于是，他开始物色合适的人成为自己的弟子，将这个艰巨的任务继承下去。街头混混卡尔（西恩•威廉•斯科特 Seann William Scott 饰）偶然中帮武僧解了围，或许是心灵感应，武僧感应到这个混小子就是自己的传人了，于是决定将一身武功传给卡尔。卡尔开始了他对抗邪恶的艰难宿命。','A power beyond measure requires a protector without equal.',52000000,0,15.20707,5.1,278,104,'2003-03-28','en','/lkuo599Ec4Ul0hPnM0UwRQYICKY.jpg',3.0074085094895673,3,'2026-09-10',2,NULL,NULL),(11818,'伊拉克恶狼谷','Kurtlar Vadisi: Irak','\"阿莱姆达尔（内贾蒂·萨斯马兹 Necati Sasmaz 饰）是一位机智而又神勇的土耳其特工，某日，他收到了朋友的遗书，遗书中，朋友控诉了自己曾经遭到美国特工头目马歇尔（比利·赞恩 Billy Zane 饰）的非人对待，阿莱姆达尔发誓要为朋友报仇雪恨。\r 就这样，阿莱姆达尔来到了混乱的伊拉克北部，在这里，马歇尔控制并作为独裁者统治着他的占领区。马歇尔的专横和草菅人命激怒了当地的居民，然而他们的肉身却不断的破碎在无情的子弹之下，阿莱姆达尔的到来给当地人带来了一线的希望，很快，阿莱姆达尔便有了追随者，势力渐渐壮大。马歇尔不仅滥杀无辜，还联手监狱里的医生经营着非法贩卖器官的勾当，面对错综复杂的权利和强大的对手，阿莱姆达尔最终能否带领人民走向自由呢？\"','Some Men Are Born to be Heroes',10000000,0,1.465762,4.3,7,122,'2006-02-03','tr','/6Z0pkbGdKrfZ37sY0WCsSHpi7mK.jpg',2.2834996185054868,3,'2026-09-10',2,NULL,NULL),(11820,'蒙娜丽莎的微笑','Mona Lisa Smile','1950年代，美国女性的社会地位表面看来有了明显提高，然而在如威斯理般著名的女子大学里，教师们教授学生，仍是一切围绕将来的好姻缘打转，并不鼓励她们主动获取自己感兴趣的知识，也不注重培养她们的心里素质。美丽成熟的凯瑟琳（朱莉娅·罗伯茨 Julia Roberts 饰）大学毕业，怀揣理想和热情来到该学校担 任艺术史教师时，便因想散播自由的种子碰壁连连。  然而因为风趣、率直、热情、渊博，凯瑟琳很快赢得了学生们的喜爱，她的几个学生，想同男孩一样干出一番事业的琼（朱丽娅·斯蒂尔斯 Julia Stiles 饰）、活泼好动的丽薇（玛吉·吉伦哈尔 Maggie Gyllenhaal 饰）等，也慢慢地展露出真性情。然而，另一名学生贝蒂（克斯汀·邓斯特 Kirsten Dunst 饰）要结婚的消息，又将自由浪漫的氛围打破。','In a world that told them how to think, she showed them how to live.',65000000,0,19.718544,6.5,393,117,'2003-12-19','en','/bg0VKsXnLjIZ0cHmZHZLs9gzrvm.jpg',3.217299447328987,3,'2026-09-10',2,NULL,NULL),(11823,'温布尔登','Wimbledon','温布尔登是英国有名的网球公开赛，这里的选手呈现着网球的最高水平和精彩战况，是网球选手施展拳脚的绝佳舞台。梦想着在温布尔登实现网球事业巅峰的，还有片中的男主角彼特（保罗·贝坦尼 Paul Bettany饰）。无奈温布尔登的辉煌不是轻而易举就能收归囊下，他像无数怀揣着梦想来到这里的选手那样，终究要黯淡离去，现在他正准备作收山一战，怎料事情来了个峰回路转。  　　来自美国的种子选手利兹（克尔斯滕·邓斯特 Kirsten Dunst饰）有着优异的成绩和漂亮迷人的相貌身材，有着与众不同的个性，深深吸引着彼特的心。爱情的滋润令彼特得到神奇的力量，在赛场上所向披靡，成绩骄人。网球生涯的光明前景在彼特面前徐徐铺开，然而爱情的狂热似乎只为他带来好运，却令到利兹耽于爱情而分了赛场的心。对于利兹来说，放弃原本辉煌的战绩未免牺牲太大，她选择离去。这对因网球结缘的情人，却即将要因网球而分离，除非上天再次给事情一个神奇的转机。','She\'s the golden girl. He\'s the longshot. It\'s a match made in...',31000000,41512007,16.736734,6,293,98,'2004-09-13','en','/agiItFfsvNsjpinLGwjfpYOhLaX.jpg',3.09649547807926,3,'2026-09-10',2,NULL,NULL),(11826,'性感野兽','Sexy Beast','盖尔·德夫（雷·温斯顿）曾经是叱咤伦敦东区的一名江洋大盗，如今他已金盆洗手隐居田园，和爱妻迪迪（阿曼达·莱德曼）及小男仆安利奎住在西班牙一所幽静的山间别墅里；闲来无事时，同两个邻居兼旧友艾奇、杰基凑上一桌牌打打，小日子过得真是自在惬意。  　　只可惜好景不长，另一位昔日同伙唐·劳根（本·金斯利）的不请自来一下子搅乱了盖尔他们的宁静生活。唐暴虐的脾气和神经质的言行让每个人心中都惴惴不安，更加令大家惶恐的是：唐的此番来访将会使盖尔重新陷入麻烦和危险之中。原来，伦敦大恶棍泰德·巴斯（伊恩·麦克什）和金融家哈里精心策划了一次抢劫英格兰银行的行动，其中唐也有份，他这次来的目的就是要将盖尔也拉下水，以协助他们完成计划。  　　为了妻子的安全和幸福、为了捍卫自己得来不易的和平生活，从西班牙到伦敦，盖尔义无返顾地同唐一伙人展开了意志、胆量与力量的较量……','There\'s a bit of the beast in all of us.',5000000,0,11.21273,7,217,89,'2000-09-13','en','/uabD9uIrEuvaF9EJmxoutsc6M1O.jpg',3.0897263380229094,3,'2026-09-10',2,NULL,NULL),(11827,'宇宙奇趣录','Heavy Metal','本片是集合电影、漫画及音乐三种媒体艺术精华的“坏孩子\"，片中短篇全部以暴力、性爱为骨干，挖苦人性丑恶之余，不忘宣扬法西斯独裁主义，正因其疯狂丰富的想像力及惊人梦幻幕后组合，令这部腐败的卡通被誉为科幻片的里程碑，超凡脱俗的cult film被誉为是天使与魔鬼的混合体。也是80年代堕落荒淫世界与当代艺术的巅峰结合。  本片为八０年代恶名昭彰的 cul 名动画 “Heavy Metal”，动画改编自美国同名漫画期刊 “Heavy Metal”。这杂志从70年代创刊一直到现在都还在发行,杂志的内容融合了科幻,惊悚,奇幻,以及成人色彩。共结合了七个来自杂志或原创的短篇故事,并以一篇序和一篇跋来连贯作品。  由于是由不同的年轻动画家制作的，所以每篇风格都有不同，但就算以现在的眼光来看，制作依旧非常精美。  此片近些年又被提起，很大程度上是因为《南方公园》（south park）在“Major Boobage”一集中向 Heavy Metal 的致敬。','A Step Beyond Science Fiction',9300000,0,12.928269,6.2,148,90,'1981-08-07','en','/atUtWrDlLzT1yeVK2EoYtvbS963.jpg',2.9543335148822196,3,'2026-09-10',2,NULL,NULL),(11831,'勇者无惧','Amistad','1839年，运送黑奴的阿米斯塔德号在大洋上遭遇暴风雨，黑奴们趁乱暴动，将船员砍杀，控制了阿米斯塔德号后试图驶回家乡，然而六周后，他们阴差阳错抵达了美国，幸存下来的44名黑奴被美国军方逮捕，并将面临杀人罪的指控。此时，西班牙女王向美国总统要求引渡这些属于西班牙的黑奴；两名海军军官也宣称黑奴是他们的战利品；另有人拿出了在古巴购买这些黑奴的证明。各方争执之际，废奴会的领袖之一、同时也是船公司负责人的乔德森（摩根·弗里曼 Morgan Freeman 饰）与友人塔培安雇佣了律师罗杰，希望证明这些黑奴来自非洲，从而在废奴观念深入人心的大环境下为他们谋取自由……','Freedom is not given. It is our right at birth. But there are some moments when it must be taken.',36000000,74000000,3.698276,6.8,316,155,'1997-12-03','en','/6QqNyIHKow0jngiQgTNBOBrLILM.jpg',3.155152244379565,3,'2026-09-10',2,NULL,NULL),(11835,'非法制裁','Death Sentence','成功的事业、美丽的妻子、两个乖巧的儿子，尼克·休姆（凯文·贝肯）过着人人称羡的完美生活。大儿子布莱登更是尼克的骄傲，他不仅学业一流，还是个很可能成为“明日之星”的出色冰球选手。一天夜晚，载着刚赢了一场比赛的儿子回家的途中，父子俩有说有笑。然而，在途经加油站的时候，一场抢劫却改变了一切！还没等尼克回过神来，在加油站便利店买东西的儿子就死在了歹徒刀下！  歹徒在大笑中开车逃走，愤怒的尼克在一片混乱中扯了其中一个的面具，但还是被他溜走。警方很快抓获了嫌疑人，永远不可能忘记歹徒的脸的尼克自然毫不犹豫指证出了凶手。然而，虽然凶手就在眼前，可因为缺乏其他证人和证物，法庭竟然只判凶手无罪释放！眼睁睁地看着家里人饱受丧子的痛苦折磨，平静的生活变得支离破碎，本来极度痛恨暴力的尼克几近疯狂，他决定亲手复仇，让每一个哪怕是动了他儿子一根汗毛的坏蛋都不得好死！  可复仇把尼克甜蜜温暖的家庭更引向了崩溃的深渊！在杀死被无罪释放的凶手之后，得知此事的黑帮暴徒竟然决定血债血偿，对尼克全家下达了追杀令，非致他们于死地不可！再也无法承受痛失最爱之痛，沉默寡言的一家之主尼克，为了保护自己的家人，决定展开一场腥风血雨的骇人杀戮！','Protect what\'s yours.',20000000,16974459,12.643703,6.5,297,105,'2007-08-31','en','/4HKFWuxDCnqv3FY0jUnUwoXae0e.jpg',3.1334318521418867,3,'2026-09-10',2,NULL,NULL),(11836,'海绵宝宝历险记','The SpongeBob SquarePants Movie','蟹堡王毗邻本店的二号店即将开张了！海绵宝宝满心期待，以为分店经理一职非自己莫属，然而蟹老板却以他不够成熟为理由，将分店交给章鱼哥打理。同时看着蟹堡王做大的痞老板再出毒计，他偷走了海王星国王的王冠，并嫁祸蟹老板，盛怒的海王星要处死蟹老板，但为了拿回王冠，给忠诚的海绵宝宝和派大星六天时间，让他们去无人能够生还的贝壳城取回王冠。而痞老板得逞后偷走了蟹老板的蟹黄堡配方，生意迅速大热，他趁机把能够操纵思想的头盔赠送给顾客们，要通过控制海洋生物称霸世界。另一面，海绵宝宝和派大星踏上了无厘头又凶险万分的寻冠之路，前往传说中独眼巨人栖息的贝壳城……','Bigger. Better. More absorbent.',30000000,140161792,27.870755,6.7,574,87,'2004-11-14','en','/z9oTDyDMkxlECLBBLEwGLYTtTNd.jpg',3.354940260949217,3,'2026-09-10',2,NULL,NULL),(11843,'The Return of the Pink Panther','The Return of the Pink Panther','The famous Pink Panther jewel has once again been stolen and Inspector Clouseau is called in to catch the thief. The Inspector is convinced that \'The Phantom\' has returned and utilises all of his resources – himself and his Asian manservant – to reveal the identity of \'The Phantom\'.',NULL,5000000,41833347,6.470766,6.7,137,113,'1975-05-21','en','/cDi6lHXmY12SxtjcP6IdK7mB3W1.jpg',2.9463981626445226,3,'2026-09-10',2,NULL,NULL),(11858,'天兵总动员','Renaissance Man','中年广告人丹尼．德维托突然被公司解雇，使他一下子陷入困境，不得已接受了另一份工作，跑到军营里教英文。不料这群学生都是脑筋有问题的大兵，令他备感烦恼。后来，他干脆赌气地以莎士比亚戏剧为教材，不料反而收到意想不到的效果，师生之间的关系也有了令人振奋的转变。曾导过《红粉联盟》的女导演彭尼．马歇尔处理这个男性化的题材，成绩虽不如前，但对男主角置之死地而后生的挑战精神还是表现得很不错，全片的发展也流畅而具趣味性。','One Man\'s Mission To Teach The Few, The Proud... The Impossible!',40000000,24332324,4.516953,5.9,81,128,'1994-06-03','en','/iPRtaSfN8gNWFclgrcg5oD3V41i.jpg',2.7946241939150394,3,'2026-09-10',2,NULL,NULL),(11863,'玉焰','Jade','警方人员发现一具被挂在墙上血肉模糊的男性尸体，从他的穿着可知此人属有钱人家；探长在房间内仔细地逐一细看下，终于发现房内摆放着精致的细小纸盒，每一个盒内载着一小撮女人之物，而其中一个放着的是一张列满女人名字的纸条，“玉”是其中一个名字，由于名字是以中国字书写的，因此引起探长的注目，案件亦由此开始逐步揭开……','Some fantasies go too far.',50000000,9851610,8.189406,5.2,44,95,'1995-10-13','en','/8KWiZKDYpAgh8n27lanvTuDquyX.jpg',2.663499373868272,3,'2026-09-10',2,NULL,NULL),(11866,'凤凰劫','Flight of the Phoenix','机长弗兰克（丹尼斯·奎德 Dennis Quaid 饰）与飞机打交道多年，这次他将负责一架“凤凰号”货机，运送一批石油工人和物资到北京去。然而令他意想不到的是，飞机在途中遇到了风暴，弗兰克不得不迫降在荒无人烟的内蒙古戈壁滩上。幸好死伤人员并不多，然而他们的储备水却只够维持一个月的使用，但在一个月内能等到救援的可能性有如买彩票。饥饿和慌张中，幸存者间开始了各种意见分歧与争吵。最后一名自称是飞机设计师的乘客提议，用飞机残骸再造一架飞机自救。然而造飞机并非想象中那么简单，人心在不断尝试中渐渐消耗，仅存的生命之水也越来越少，重伤的“凤凰”还能否在广漠戈壁中涅槃重生？\r 　　本片翻拍自1965年同名电影，两者皆改编自英国小说家Elleston Trevor的同名小说。 ©豆瓣','Out of the ashes, hope will rise.',45000000,21009180,20.374308,5.7,276,113,'2004-12-17','en','/dNiCxmglxQtHwHTYHsJCK4wZfDk.jpg',3.06754795180312,3,'2026-09-10',2,NULL,NULL),(11870,'超级大骗子','Big Fat Liar','14岁的杰森（弗朗基·穆尼兹 Frankie Muniz 饰）相貌帅气聪明伶俐，才华横溢的他小小年纪即在编剧上展现出了过人的天赋。一次偶然中，他发现自己的作业被好莱坞制片人马迪（保罗·吉亚玛提 Paul Giamatti 饰）偷偷窃取拍成了电影《超级大骗子》，不仅如此，这部电影更因为优秀的剧本而获得了巨大的成功。眼看着自己的劳动果实被强取豪夺，杰森决定不再沉默，他伙同自己的死党凯利（阿曼达·贝尼斯 Amanda Bynes 饰），两人来到了好莱坞。','The truth is never overrated',15000000,52970014,9.125594,5.6,197,88,'2002-02-08','en','/3EjpQeyOpH8VIaWqIq6SpCQrCks.jpg',2.970223372400939,3,'2026-09-10',2,NULL,NULL),(11873,'金钱本色','The Color of Money','在经营了多年的桌球室里，艾迪（保罗·纽曼 Paul Newman饰）发现了一个优质的桌球苗子——文森（汤姆·克鲁斯 Tom Cruise饰）。文森暗藏着艾迪当年在桌球台上的风采，令艾迪决心收他为徒，助他在桌球事业上大显身手。于是，艾迪、文森和文森的女友，一同前往大西洋城参加大赛。一路上，文森参加了不少小型比赛，虽然和艾迪之间不断有分歧，但也赢回不少金钱。同时，艾迪在培养文森的过程中，内心对桌球的热爱又重新被唤起，他重新拿起球杆，不料却败北而归。失落的艾迪决定离开文森，一个人苦练球技重振雄风。当踌躇满怀的艾迪重回大西洋赛场，却发现文森成为了自己的对手。此时的文森对金钱的追求，已经远远超过了桌球本身。艾迪和文森的比赛成为一场尊严与金钱之战。','The Hustler isn\'t what he used to be. But he has the next best thing. A kid who is.',13800000,52293982,17.3393,6.7,291,119,'1986-10-07','en','/dVdnHmdQu3JtLAAksjTmTEF76gD.jpg',3.1563821245233497,3,'2026-09-10',2,NULL,NULL),(11876,'屋顶上的轻骑兵','Le Hussard sur le toit','十九世纪中期，意大利正处在奥匈帝国水深火热的统治中。为了解放祖国，轻骑兵上教安吉罗（奥利维•马丁内兹 Olivier Martinez 饰）密谋发动暴动推翻殖民统治，然而却因计划外漏而不得不流亡法国。因为儿时好友的出卖，安吉罗在法国受到了奥地利间谍的追杀。逃亡中的安吉罗无意闯进了法国的一个瘟疫区，那里哀鸿遍野，人们近乎疯狂。当地人认为是安吉罗投的毒药，安吉罗无端又成了追捕的对象。 一天，安吉罗无意中从屋顶掉到了一间阁楼里，偶遇了与丈夫失散了的女子宝林娜（朱丽叶•比诺什 Juliette Binoche 饰）。得知宝林娜现在处境艰难时，安吉罗决心帮助她找回她的丈夫。当他们在疫区穿行时，宝林娜不幸身染疫症……',NULL,35000000,15000000,2.877488,6.7,25,135,'1995-09-20','en','/p6SGK8GIWIkosGPucLA5l4JAp6v.jpg',2.553688984600586,3,'2026-09-10',2,NULL,NULL),(11887,'High School Musical 3: Senior Year','High School Musical 3: Senior Year','It\'s almost graduation day for high school seniors Troy, Gabriella, Sharpay, Chad, Ryan and Taylor ― and the thought of heading off in separate directions after leaving East High has these Wildcats thinking they need to do something they\'ll remember forever. Together with the rest of the Wildcats, they stage a spring musical reflecting their hopes and fears about the future and their unforgettable experiences growing up together. But with graduation approaching and college plans in question, what will become of the dreams, romances, and friendships of East High\'s senior Wildcats?',NULL,0,0,21.801188,6.2,821,116,'2008-10-22','en','/8WH3bzbpJ974qb3GDMCN6TIDmiY.jpg',3.354908481352299,3,'2026-09-10',2,NULL,NULL),(11888,'雪地狂奔','Snow Dogs','一笔天降的遗产让牙医泰德（小库珀·古丁 Cuba Gooding Jr. 饰）心中充满了兴奋，在他的幻想里，他终于可以摆脱入不敷出的生活，转而过上锦衣玉食的日子了。令泰德没有想到的是，当他按照指示来到了阿拉斯加准备接收遗产之时，他所要接收的却并不是巨额的支票或是辉煌的豪宅，而是八只活蹦乱跳的雪橇狗。\r 　　生活中一下子多出的这八个“朋友”让泰特感到不知所措，殊不知，这八只雪橇狗并非凡夫俗子，而是曾经在拉雪橇比赛中夺得过第一名的冠军团队。新一届拉雪橇比赛即将开始，尽管泰德对此毫无经验，但他还是决定带领他的八个朋友参加比赛。就这样，泰德开始了对于雪橇狗的训练，一个菜鸟教练和八个精干的队员，这样的组合真的没有问题吗','Get ready for mush hour!',33000000,0,13.655735,5.3,185,99,'2002-01-18','en','/8DDC6z1XyLSiNLzKw1pXcYeAOJ3.jpg',2.9503572107139675,3,'2026-09-10',2,NULL,NULL),(11889,'长路将尽','Iris','电影改编自英国著名女作家艾莉丝·默克多的生平。艾莉丝（凯特·温丝莱特 Kate Winslet 饰）从小就有一颗充满了热情和灵感的心，她前卫的思想和先进的学说曾经影响了一代人的思考方式。沉默寡言的学者约翰（休·博内威利 Hugh Bonneville 饰）捕获了艾莉丝的芳心，两人的恋情炙热又长久，人们在惊愕之余亦将这段感情传为佳话。  　　不幸的是，艾莉丝患上了失忆症，她的记忆会随着时间的推移而消失殆尽，这种不可逆的病症给艾莉丝和约翰的心灵蒙上了阴影，也没能撼动两人之间坚固的感情。面对病重的妻子，约翰不仅不离不弃，更是承担起了整个家庭的责任。一段感情，跨越了四十年的时光，容颜会改变，记忆会退却，唯爱永生。',NULL,0,0,2.714043,6.2,47,91,'2001-12-14','en','/3SzSoazQRIQXGNf4uPggJ2vzX8Z.jpg',2.682191501307395,3,'2026-09-10',2,NULL,NULL),(11891,'Kung Pow: Enter the Fist','Kung Pow: Enter the Fist','A movie within a movie, created to spoof the martial arts genre. Writer/director Steve Oedekerk uses contemporary characters and splices them into a 1970s kung-fu film, weaving the new and old together.\r As the main character, The Chosen One, Oedekerk sets off to avenge the deaths of his parents at the hands of kung-fu legend Master Pain. Along the way, he encounters some strange characters',NULL,0,0,8.288813,6.1,159,81,'2002-01-25','en','/ySQQEZ2WD8bnN4Vr3PuwWQlhW3l.jpg',2.9540979704981276,3,'2026-09-10',2,NULL,NULL),(11892,'数字谋杀案','Murder by Numbers','探员凯西（桑德拉·布洛克 Sandra Bullock 饰）的有勇有谋人尽皆知，而此次摆在她面前的案件却让她伤透了脑经，这宗案件不仅案情扑朔迷离，手法更是完美得找不到一丝漏洞。山姆（本·卓别林 Ben Chaplin 饰）受命协助凯西办案，可是对于这个做事毛毛躁躁的楞头青，凯西却并不信任，她觉得山姆资历尚浅，凭借的不过是纸上谈兵的本事。\r 　　随着调查的深入，凯西终于找到了突破口，名叫理查德（瑞恩·高斯林 Ryan Gosling 饰）和贾斯汀（迈克尔·皮特 Michael Pitt 饰）的两名少年出现在了她的视线中。然而，凯西无法相信，竟然是这两个看似善良的少年犯下了如此邪恶的罪行。当犯罪动机渐渐显露，一个残酷而又冷血的世界逐渐露出了真容。','The only flaw in their plan was her.',50000000,56714147,16.167093,6,268,120,'2002-04-19','en','/plH3TujSUVttiIikToKfwdCorJI.jpg',3.076501233877426,3,'2026-09-10',2,NULL,NULL),(11901,'荒野浪子','High Plains Drifter','克林特·伊斯特伍德饰演一名神秘客，从热浪逼人的沙漠来到罪恶满城的拉高镇，并被邀请出手阻止三个刚出狱的枪手继续犯案。','Welcome to Hell',5500000,15700000,19.127239,7.4,278,105,'1973-04-19','en','/AjkJCFkqanK1OZqiHxc6Kl2wPQO.jpg',3.2069573529907007,3,'2026-09-10',2,NULL,NULL),(11904,'少年福尔摩斯','Young Sherlock Holmes','19世纪，年幼的福尔摩斯和年幼的华生医生在同一所寄宿学校就读。福尔摩斯在幼年就表现出了非凡的观察和逻辑推理能力，这让他在学校里很受同学注目。他与华生还有他暗恋的姑娘Elizabeth Hardy一起，在一次偶发的自杀案中抽丝剥茧逐渐走入伦敦的黑巷中破获了惊人的罪案。','Before a lifetime of adventure, they lived the adventure of a lifetime.',18000000,0,8.321586,6.7,167,109,'1985-12-04','en','/aOxVYvQoAfNSns4hW5Ah55GBzgq.jpg',2.9983101910641126,3,'2026-09-10',2,NULL,NULL),(11908,'短柄斧','Hatchet','所有的悲剧都发生在那个万圣节的夜晚，邻居家的孩子们都往房子里投掷鞭炮，为了愚弄和吓唬“傻大个”维克托，然而，罗克利家的老房子是由那种易燃的木头建成的，结果可想而知，鞭炮的火星点燃了房子……当维克托的父亲回到家时，房子已经被大火包围了，惊悉维克托仍然被困在房子里后，父亲冲进谷仓，拿起一把短柄斧，拼命地冲着房门砍去……但是他不知道受到惊吓的维克托其实就躲在门后，正在想办法打开门逃出来。父亲手中的斧头就这样不幸又意外地砍在了维克托的脸上，可怜的维克托一命呜呼。从此以后，那个经历了丧子的痛苦的老男人的后半生都沉浸在自责与悲哀中不能自拔，他不肯离开房子一步，不肯与其他人交谈，渐渐和所有人都断了联系。差不多10年后，他抑郁 而终。\r 似乎闯下大祸的总是那些无知且冒失的年轻人，本刚刚和他的女友分手，所以他还没什么情绪盯着其他姑娘的胸部瞧，因为他发现这只会提醒自己前任女友的一切，以及两人在妈妈的床上共度的那些美好时光。于是他决定做一些惊险刺激的事情来调整心情，他的目光对准在新奥尔良一处因为闹鬼而闻名的沼泽地里，伙同好友马库斯进行一场探索“闹鬼的沼泽”之旅。然而他们做梦也没想到，由于那个没什么经验的导游的失误，他们竟然真的进入了一个古老的传说之中，里面所有的一切，都是有关维克托·克罗利的。','Stay out of the swamp.',0,0,12.677016,5.7,159,83,'2006-04-27','en','/lkh3Fwruds78feXfP1Zb9kBLydL.jpg',2.942621211464411,3,'2026-09-10',2,NULL,NULL),(11917,'电锯惊魂5','Saw V','竖锯的尸体躺在解剖台之上，被开肠破肚。冒犯游戏规则的学徒阿曼达，也被自己的狠毒了结。但天才杀戮恶魔的神髓，还远远没到终结的时刻。传承拼图杀人魔意志的马克·霍夫曼，成为了新一代嗜血游戏的谜局主导人。','You Won\'t Believe How It Ends',10800000,113857533,32.943848,5.9,820,92,'2008-10-23','en','/towVIYtwFXaeqr6LugOeGZmTmTa.jpg',3.332427051406671,3,'2026-09-10',2,NULL,NULL),(11918,'超级英雄','Superhero Movie','这回终于轮到神奇漫画中的一众超级英雄了，有一个算一个，在这里扎了堆地被恶搞一番，再也找不到当初拯救世界的英勇气势了。','The greatest Superhero movie of all time! (not counting all the others)',35000000,25871834,19.088655,4.9,379,85,'2008-03-27','en','/hJuBG6r2WmoKHQCKq9tbUXMOb2n.jpg',3.042777834757993,3,'2026-09-10',2,NULL,NULL),(11932,'鬼娃回魂4','Bride of Chucky','在查尔斯·李·雷伊将灵魂注入公仔十年后，他当年的女友蒂芬妮（珍妮佛·提莉 Jennifer Tilly 饰）多年不懈寻找他的下落，终于买通警察将玩偶“楚其”的残体带出，蒂芬妮凭借不熟练的伏都仪式，将缝合的楚其再次唤醒。然而觉醒的楚其对蒂芬妮并无爱意，伤心的蒂芬妮将楚其禁锢，不想却被楚其把她的灵魂移入了另一个女玩偶的体内。两个玩偶要恢复人类身体，就必须找到埋藏在查尔斯·李·雷伊坟墓中的护身符。于是他们盯上了一对儿被长辈阻挠的恋人杰德（凯瑟琳·海格尔 Katherine Heig 饰）与杰西。两个玩偶委托后者驾车将它们送去埋葬雷的坟场，同时一路大开杀戒，私奔的杰德与杰西惊觉自己陷入了玩偶情侣的掌控…… ©豆瓣','Chucky Gets Lucky.',25000000,50671850,14.340095,5.5,350,89,'1998-10-16','en','/4ZojtZw28Gepl0eqlOi1xSC7Gnr.jpg',3.0795457495846636,3,'2026-09-10',2,NULL,NULL),(11934,'影子大亨','The Hudsucker Proxy','诺维尔（蒂姆·罗宾斯 Tim Robbins 饰）从大学毕业后便来到纽约街头找工作，缺乏经验的他只能在一家金融公司里担任一名收发室小职员。不久后总裁自杀身亡，公司的实权落入了老奸巨猾的董事会成员马斯伯（保罗·纽曼 Paul Newman 饰）手中，这本来没有诺维尔什么事，不料马斯伯为了达到他低价收购公司的目的，竟将看似愚蠢的诺维尔任命为他的傀儡总裁。而诺维尔此刻正在一门心思地研发他的新发明——呼啦圈，马斯伯想借此发明使公司的股票跌入冰点，不料呼啦圈推出后竟大肆流行，公司的股票直线上升。恼羞成怒的马斯伯开始在暗中大动手脚，将公司的局势搅得一落千丈，诺维尔也变成了众矢之的，甚至有可能被关进精神病院。绝望的他再次回到公司大楼的顶层，准备纵身一跃一了百了，然而就在此时，原已故去的前任总裁竟然出现了……','They took him for a fall guy... but he threw them for a hoop.',30000000,0,14.188982,7.1,275,111,'1994-03-11','en','/6w9Qcol2qHzbZL6H0S71prr2q84.jpg',3.1678287147383615,3,'2026-09-10',2,NULL,NULL),(11935,'摩羯星一号','Capricorn One','美国航天中心准备实施一项耗资204亿美元的登陆火星计划。在离火箭点火发射3分钟的时候，宇航员布鲁上校、皮特中尉和沃克被强行请出飞行舱并当即送离发射场。在一个沙漠中摄影棚的密室里，登陆计划的总负责人凯勒威博士接见并向他们解释了事情整个原因。原来，政府认为花204亿到达另一个星球并不划算，同时飞船里的生命系统也根本不能保证他们能到达火星表面。但为了赢得民众对政府的信任，航天局还是下达了如期发射的命令。在包括不知情的副总统和军方高级领导在场的注视下，火箭如期发射并取得巨大成功。就在举国欢庆时，布鲁、皮特和沃克却在凯勒威博士的要挟下，配合摄影师运用电影特技向公众“直播”登陆火星的全过程，从而设置了一套无人驾驶、模拟着陆和飞船烧毁的骗局。当隆重的追悼仪式正在进行的时候，死里逃生的一位航天员突然出现在致哀者的面前，这幕骗局终于大白于天下……','The mission was a sham. The murders were real.',5000000,0,11.095219,6.4,131,123,'1977-12-10','en','/bxsCARg2rxQ2PzFW5ZsADLT9e9c.jpg',2.9325548672855035,3,'2026-09-10',2,NULL,NULL),(11954,'宇宙天魔','Lifeforce','宇宙飞船邱吉尔号接近哈雷彗星，欲探知其内部构造。船长汤姆•卡尔森（Steve Railsback 饰）带领一组队员走出船舱，发现彗星内部藏有一艘废弃的飞船，内有多具奇怪生物的干尸以及三个沉睡在水晶棺内的人类。为解开其中奥秘，汤姆下令将他们带回飞船。三十天后，空无一人的邱吉尔号飞临地球，航天总署派出哥伦比亚号与之对接。宇航员在船中发现焚烧的痕迹和那三个沉睡之人，而机组成员全部死亡。回到地球后，三个人中的女性（Mathilda May 饰）突然苏醒，吸取了年轻守卫的精气。之后守卫变成干尸，并最终风化。不久其他两人苏醒，似乎一场灾难正降临地球……','In the blink of an eye, the terror begins.',25000000,0,12.18362,6.2,135,116,'1985-06-20','en','/kkyY3mxSJ6w41M5xQLQtPLzay5G.jpg',2.9324808299542715,3,'2026-09-10',2,NULL,NULL),(11956,'When the Cat\'s Away','Chacun Cherche Son Chat','When Chloe (Garance Clavel), a young Parisian, decides to take a long-overdue vacation, she has to find someone to look after Gris-Gris, her beloved cat. Everyone, including her gay male roommate, refuses to help her, but she finally makes an arrangement with the elderly Madame Renée (Renée Le Calm), who often watches over other peoples\' cats and dogs. However, when Chloe comes back, Madame Renée tells her that unfortunately the cat has been lost, and the unlucky owner goes on a search for her dear animal friend. While looking for the cat, she meets many colorful characters who populate the neighborhood.','No man. No job. No cat.',0,0,1.410387,6.1,16,91,'1996-04-03','fr','/v8Ib2wuFOujeGA3Du2eDJwvivSq.jpg',2.4521471528643857,3,'2026-09-10',2,NULL,NULL),(11959,'超高频','UHF','一个超高频电视频道的新经理性格古怪，试图通过一系列奇特的节目来挽救电视台，使其免于破产。','A lot of TV stations have forgotten what \"quality\" means, but not Channel 62. They NEVER knew what it meant.',5000000,0,4.070044,6.7,89,97,'1989-07-21','en','/wxx5YQLKVH1WMSRXQAUnC76r4iY.jpg',2.8393866031063513,3,'2026-09-10',2,NULL,NULL),(11967,'少壮屠龙阵','Young Guns','在一个没有法律又充满暴力的年代，一个英国商人手下有六位年轻流浪汉，为了自己的家园，为了报仇，在法律无法制裁凶手时，六个人毅然向那批杀人犯宣战，从此展开一场无法回头的战斗。','Six reasons why the west was wild.',13000000,44726644,9.499325,6.6,258,107,'1988-08-12','en','/3AgCq7xY1rHRAAn0iVcnNr2OWL.jpg',3.100373683845172,3,'2026-09-10',2,NULL,NULL),(11968,'碧海追踪','Into the Blue','风暴之夜，一架飞机在海上失事，坠入无边的大海深处……碧水蓝天的巴哈马海域上，失业潜水员杰拉德和女友萨曼预备寻宝深海的沉船宝藏，然而破旧的小船和竞争对手贝茨的打压让他们难以如愿，幸好律师好友布莱斯和女友阿曼达来到，于是四人出海，竟意外的发现了著名海盗的宝藏线索以及一架载满毒品的飞机。布莱斯与阿曼达打起了毒品的主意，但一心挖掘宝藏的杰拉德劝说好友远离毒品。不久，杰拉德陷入财政危机，布莱斯要杰拉德不顾萨曼的劝告以毒品获利支持发掘。而贝茨和毒枭的眼镜，也在暗中盯上了这几个寻宝的好友……','Treasure has its price.',50000000,44434439,14.723467,5.8,458,110,'2005-09-30','en','/wKSuUq5bsliOSUgxPd9WGnTCHVL.jpg',3.162117029494663,3,'2026-09-10',2,NULL,NULL),(11969,'墓碑镇','Tombstone','厄普警长向来执法强悍，令匪徒闻风丧胆而威震四方，在19世纪无法无天的西部，自成一股安定人心的力量。然而，他曾有过厌倦之感，希望能在别的地方度日，从此不问世事，可是人在江湖身不由己，他无故被卷入一场纷争，为了维护自己所追求的和平，再次披甲上阵...','Justice is coming.',25000000,56505065,30.537845,7.4,626,130,'1993-12-25','en','/9QsL2FYoCiQhxejj2anp1NQv7L8.jpg',3.4806753315705885,3,'2026-09-10',2,NULL,NULL),(11971,'无事生非','Much Ado About Nothing','王子殿下率领部下打了胜仗归来，下榻在莱奥纳多大人家，王子一行的到来立刻令整座庄园蓬壁生辉。王子的亲信克拉迪奥对莱奥纳多的女儿希洛一见钟情，王子承诺将在假面舞会上替他向希洛小姐求婚。王子的弟弟约翰伯爵和哥哥之间一直存在隔阂，他欺骗克拉迪奥王子是在为自己求婚，令克拉迪奥十分沮丧。但好在很快克拉迪奥知道了真相，婚礼将在一周后举行，大家都在期待着这一天的到来。与此同时，王子很想促成部下佩尼和希洛的表姐贝特里斯的婚姻，尽管这一对欢喜冤家见面就吵架，但他们的个性却十分相像，王子鼓动大家制造两个人彼此相爱的传言，很快佩尼和贝特里斯也坠入了爱河。眼看婚礼马上就要举行了，约翰伯爵一计不成又施一计。他的部下曾和希洛的女仆有染，约翰伯爵令他与女仆在希洛的房间里偷欢，并将王子和克拉迪奥带至希洛的窗下，令他们相信希洛是一个不值得克拉迪奥迎娶的风流女子。婚礼上，克拉迪奥当众羞辱希洛，尽管希洛和父亲都感到冤屈，但这一次王子却始终站在克拉迪奥一边，无奈之下莱奥纳多只得对外宣称希洛因过度悲伤意外身亡。经过调查幕后黑手约翰伯爵逐渐浮出水面，事情真相大白。克拉迪奥为自己鲁莽的行为悲痛不已，为求得莱奥纳多的原谅，他答应当众向希洛道歉，并迎娶莱奥纳多的侄女。当克拉迪奥揭开新娘的面纱时，他惊喜地发现此刻站在他面前的就是心爱的希洛。两个人重归于好，在王子和众人的祝福声中两人发誓要珍惜彼此一生。','Romance. Mischief. Seduction. Revenge. Remarkable.',8000000,0,10.19377,7.2,189,111,'1993-05-07','en','/tvltGP6vYOkHdURag0jPSjhPUAV.jpg',3.063647912973597,3,'2026-09-10',2,NULL,NULL),(11973,'惊爆十三天','Thirteen Days','故事发生在1962年10月中旬，华盛顿的美国情报官员在进行例行情报资料分析时，从飞临古巴上空的U-2飞机所拍摄照片中发现了重要情况：苏联正在古巴首都哈瓦那西南的圣克利斯托瓦尔修建基地，部署中短程导弹和运载核武器的伊尔-28重型轰炸机。令人恐惧的是从这些基地发射的导弹，可以击中从秘鲁利马到加拿大哈得逊湾的大多数美洲重要城市。  　　当白宫得知此消息后，引起上上下下一系列的恐慌，幸好当时的总统约翰·肯尼迪和其弟罗伯特·肯尼迪能够冷静应对。10月22日美国东部时间晚上7点，肯尼迪总统在白宫他的书房里，向美国和全世界发表广播讲话，通告了苏联在古巴部署核导弹的事实，并指出，这一“秘密、迅速和异乎寻常的导弹设施\"是“蓄意的挑衅和对现状作出的毫无道理的改变，是美国不能接受的\"，有效的缓解了美国人民心中的恐慌。同时美国单方面公开向苏联发出警告，要求苏联从古巴撤出其中短程核武器，并以美国海空力量在加勒比海的广大海域对古巴设立了海上封锁线，进行所谓的“隔离\"。就这样，在当时世界两个超级大国——美国和苏联之间爆发了一场危机，将整个世界带到了核灾难的边缘……','You\'ll never believe how close we came',80000000,34566746,18.26121,6.9,189,145,'2000-12-24','en','/aLx9UXH9fK2v6NDMvMyW4X88K3u.jpg',3.063534616986576,3,'2026-09-10',2,NULL,NULL),(11975,'造雨人','The Rainmaker','初出茅庐的鲁迪·贝勒（马特·达蒙 Matt Damon饰）是刚踏进律师界的新手。一腔热血的鲁迪接手的第一个案子是一宗涉及医疗保险赔偿的诉讼。无助的母亲，生命垂危的儿子，拒绝支付医疗费的保险公司，不择手段的辩护律师，一切都跟当初设想的大相径庭。面对种种举步维艰的行业阴暗面和陷于困境的弱势群体，鲁迪至始至终都没有放弃他的正义之心。影片的另一条主线还有一位遭受家庭暴力的受虐少妇。影片用写实的手法，向我们描绘了一场捍卫正义的道德之战。本片根据约翰·格里沙姆的同名小说改编。','They were totally unqualified to try the case of a lifetime... but every underdog has his day.',40000000,45916769,12.229516,6.7,235,135,'1997-11-18','en','/jlNHy7veOEPgHVf5dQS3mz7naVu.jpg',3.0911560198952395,3,'2026-09-10',2,NULL,NULL),(11977,'疯狂高尔夫','Caddyshack','一个名叫丹尼·诺能（Danny Noonen）的年轻人，为了赚点钱来贴补家用和上大学，到一家高尔夫球俱乐部当球童的故事。情节并不复杂，但却笑料百出。尤其是由比尔·穆利（Bill Murrey）饰演的园丁卡尔（Carl）。这是个有点歇斯底里的老兵，他声称曾与西藏喇嘛（Dalai Lama）打过一年半的交道。片中，他一直试图用塑料炸药来消灭讨厌的田鼠。当卡尔为了消灭几只小老鼠而亲手毁掉了自己的花园时，那种浑然不觉、沾沾自喜的表情更是令人忍俊不禁。难怪这部影片受到了如此广泛的欢迎。','The snobs against the slobs!',6000000,39846344,15.929648,6.6,365,98,'1980-07-25','en','/lXnNz7zOXCsftMDVoU3VSo0Eioi.jpg',3.2007185489105785,3,'2026-09-10',2,NULL,NULL),(11978,'怒海潜将','Men of Honor','卡尔-布拉希尔出生于一个贫苦的黑人小佃农家庭，年青时的他深深地被美国海军所吸引，应征进入军队服务，初入军营的他发现，在海军内部并非如他所想象的那样美好，处处都有种族歧视的阴影，就连舰艇乘员这样的工作都要将黑人排除在外。严酷的现实并没有让卡尔-布拉希尔放弃自己的理想，他立志要成为一个不平凡的人。在他见到了比尔-森迪(罗伯特-德尼罗饰)之后，这个黑人青年便狂热地着迷于当一名潜水员从事搜救工作。卡尔-布拉希尔几乎花了两年的时间四外游说，积极争取，才得以有机会参加海军潜水训练计划，他遇到的教员不是别人正是森迪。这是一个十分顽固的家伙，竭力想劝阻布拉希尔退出这个从来没有黑人加入的行当。但布拉希尔顽强地坚持了下来，他用自己的行动一举打破了白人独占潜水领域的局面，突破了海军中最为严格的种族界线，并进入美国海军的潜水精英——深海潜水搜救部队。','History is made by those who break the rules.',32000000,48814909,24.147269,7,544,129,'2000-09-13','en','/wNUAnXV1mzOOfvnVBIYsalkk078.jpg',3.370953315690503,3,'2026-09-10',2,NULL,NULL),(11979,'吸血鬼女王','Queen of the Damned','吸血鬼莱斯塔特（斯图尔特·汤森 Stuart Townsend 饰）从长眠中苏醒，他不甘于趋于黑暗之中，于是他曝光于大众之下成为了一个摇滚歌手，一次意外莱斯塔特救了图书管理员杰西·瑞薇丝（玛格丽特·莫罗 Marguerite Moreau 饰），他的身份被杰西发现。莱斯塔特用他的歌声唤醒了传说中沉睡千年的吸血鬼女王阿卡沙（阿丽雅 Aaliyah 饰），阿卡沙与莱斯塔特展开了一场向旧仇人的报复计划，可他没有想到阿卡沙最终目的是想和他一起变人间为炼狱，统治全人类。与此同时杰西也爱上了莱斯塔特，莱斯塔特会怎么选择？  　　本片与《夜访吸血鬼》一样改编自安妮·芮丝（Anne Rice）的畅销系列小说——《吸血鬼列传》(Vampire Chronicles)。','This time there are no interviews.',35000000,45479110,11.644243,5.4,239,101,'2002-02-10','en','/zkw9xEirdADjaUBuaBvVuGvlHPv.jpg',2.99767162231169,3,'2026-09-10',2,NULL,NULL),(11980,'魔翼杀手','The Prophecy','大天使Gabriel因为不满上帝将其所有注意力倾注到人类身上，计划发动一场天庭政变并杀死所有好天使。要政变成功，Gabriel必须获得一位残暴的将军的灵魂的支持，而将军的灵魂被得悉Gabriel阴谋的天使Simon附于美国小女孩Mary身上。由于天庭发生了战争，灵魂们暂不能升入天堂。Gabriel只得亲下人间寻找将军的灵魂……Thomas从神学院毕业后当了一名牧师，但由于对自己的信仰产生了怀疑，转行去当了一名警察，当他察觉Gabriel的阴谋后，联合教师Katherine一起保护懵然无知的Mary，撒旦由于担心这场战争将影响到自己的统治，他的加入使得事情更复杂了……','On ancient ground, at the edge of the world, an evil born in heaven is about to be unleashed on earth.',8,16,11.818333,6.4,138,98,'1995-09-01','en','/4ZWFhQipzBHJze2llzCzhrSIZsn.jpg',2.9460174247538853,3,'2026-09-10',2,NULL,NULL),(11983,'生命的证据','Proof of Life','工程师彼特被武装分子绑架，罪犯要求彼特的雇主支付六百万美元的赎金，面对数额如此巨大的赎金，皮特的雇主回绝了绑匪的要求，保险公司亦采取了回避的态度。丈夫遭遇如此不幸，四处求助无门的爱丽丝最终找到了谈判专家特瑞，这也是她能够找到的最后一根救命稻草。 在和绑匪谈判的过程中，特瑞发现整个绑架事件并没有他所想象的那么简单，与此同时，常年在婚姻中遇冷的爱丽丝对于稳重可靠的特瑞产生了真挚的感情。最后的期限眼看着就要到来，特瑞能够顺利的营救出彼特吗？他和爱丽丝之间的感情又是否能够有一个圆满的结局呢？',NULL,65000000,0,14.866901,6,208,135,'2000-12-08','en','/zwmfclu3ZLZtI5C4OnNzpEO94y1.jpg',3.0203107093313113,3,'2026-09-10',2,NULL,NULL),(12079,'与毒共舞','Spun','二十岁的罗斯（詹森·舒瓦兹曼 Jason Schwartzman 饰）年纪轻轻就已经深陷毒谭，为此甚至欠下了巨额的债务，可是，尽管现状是如此堪忧，但罗斯的脑袋里除了毒品和性爱外，几乎空空如也。蜘蛛麦克（约翰·雷吉扎莫 John Leguizamo 饰）是当地有名的毒贩，他负责给他的“上级”厨子（米基·洛克 Mickey Rourke 饰）提供毒品。除此之外，还有弗里斯（派屈克·福吉特 Patrick Fugit 饰），不幸的他被两个臭名昭著的警察给盯上了。  　　通过蜘蛛麦克，罗斯获得了和厨子接近的机会，罗斯替蜘蛛麦克给厨子送货，以此换取高档毒品，然而，让罗斯没有想到的是，这份来之不易的工作却并不简单，刚刚上任第一天，意外和麻烦就接踵而至。','The ultimate speed freak\'s tale.',2000000,0,6.249262,6.6,132,101,'2002-06-01','en','/jiwNobUsd29ooowQyTeh0cvPBFL.jpg',2.9324142280318832,3,'2026-09-10',2,NULL,NULL),(12085,'我为钱狂','Mad Money','布里奇特是一个普通的家庭主妇，居住在一间位于郊区的大房子里，丈夫那份薪水不菲的工作足以让她的生活衣食无忧。然而就在一瞬间，美好的生活化为了泡影，丈夫丢了工作，他们不仅即将失去舒适的住宅，布里奇特还不得不为了养家糊口而踏出家门寻找工作。来到人才市场，布里奇特才发现，在这个年头想要赚钱是这样的困难，在繁多的工作岗位之中，自己的古英语学位形同虚设。无奈之下，她成为了美国联邦储备银行的清洁工。在工作中，布里奇特结识了单身妈妈妮娜和充满个性的杰姬。每天面对着成捆的钞票，三个被贫穷逼迫的走投无路的女人打起了歪主意。',NULL,0,0,6.847133,5.9,140,104,'2008-01-17','en','/z6b6rQ1ZFEkM4tSt84yPtdAioCO.jpg',2.913749757590991,3,'2026-09-10',2,NULL,NULL),(12088,'魔鬼武器','Fortress','公元2013年，到处是受核能污染、酸雨破坏的城市。因为资源锐减，政府颁布法令，每个女人仅能生育一次。前黑帽特殊部队队长约翰的妻子凯伦在长子夭折后又怀孕，急欲越区逃亡国外。约翰掩护妻子逃走，自己遭到被捕。约翰被关进沙漠地底三十层的监狱城。所有的囚犯被植入ZED-10借以控制犯人。而二十四小时监控的电脑更会侵入犯人的梦境，犯人几乎无可遁形。约翰在一场打斗后无意发现释出体内ZED-10的方式。释出ZED-10后，约翰率伙伴循着网管逃出……','The high-tech prison thirty stories below ground. Built to withstand anything... Execpt an innocent man.',8000000,6739141,8.708229,5.7,168,95,'1992-09-30','en','/evjpqWPUY4VpOdyLpeRfkGU8DiR.jpg',2.9444189918062964,3,'2026-09-10',2,NULL,NULL),(12090,'新婚告急','Just Married','莎拉（布莱特妮•墨菲 Brittany Murphy 饰）出身豪门，天生叛逆的她从来不想接受父母的安排：家人安排的高薪厚职她不屑一顾，反而当起了一名作家；对于他们安排的富有的“未来女婿”，她更是深恶痛绝。这天，莎拉偶遇了出身平凡的交通报道员汤姆（艾什顿•库彻 Ashton Kutcher 饰），两人很快堕入了爱河。然而莎拉的父母坚决反对，原因很简单，汤姆出身平民，平平无奇，这和他们心目中的乘龙快婿相去甚远，他们可不想这个平凡的男人成为家里的一份子。于是，在萨拉和汤姆婚后度蜜月时，一场旨在拆散这对小夫妻的闹剧上演了。加上两人出身的文化差异，萨拉和汤姆能否在新婚告急时共渡难关？','Welcome to the honeymoon from hell.',18000000,101564935,18.47518,5.3,404,95,'2003-01-09','en','/FRqnYDjbstsCgLSJJ3SifOh2ca.jpg',3.092740301655461,3,'2026-09-10',2,NULL,NULL),(12093,'永远的莉莉亚','Lilja 4-ever','影片以当代俄罗斯为背景，讲述了13岁的莉莉亚在残酷街头挣扎求生的故事。',NULL,0,0,7.759215,7.7,139,109,'2002-08-23','sv','/okAvQWkb267u06qfCLCPNv74rCI.jpg',3.000880710714331,3,'2026-09-10',2,NULL,NULL),(12094,'蠢蛋搞怪秀2','Jackass Number Two','暌违四年，疯狂恶作剧的爱好者们再度回归，继续诠释自毁式恶作剧的精髓。本纪录片倾情奉献来自恶作剧先进国家的成功经验。连环计：先向车里灌入蜂群再用滑珠迎接逃出来的车中人；顺手牵羊计：帮助公马自慰，得到的液体不好浪费，喝掉了事；偷梁换柱计：把鱼钩从脸上穿过，用人当鱼饵钓鲨鱼；假痴不癫计：化装成老年人各种戏弄无辜路人；打草惊蛇计：把蟒蛇藏在海洋球中与之肉搏；美人计：在粉丝情书后面安装了机关拳头来一个打一个；声东击西计：扑克牌结合电椅，令受害人完全不知痛感因何而来；最终大计瞒天过海：假恐怖分子遭遇假出租车司机，整人反被整……当然我们的恶作剧英雄们依然彪悍，血肉之躯对抗公牛、玻璃、铁夹、防暴武器、水蛭、铁耙，看的连你也肉疼！','Guess who just made number two?',11000000,72778712,11.227087,6.4,298,95,'2006-09-22','en','/u73V8dMqUwjtPL6gWesCE7ji9GU.jpg',3.122294118930064,3,'2026-09-10',2,NULL,NULL),(12096,'粉红豹','The Pink Panther','时隔多年，“顽皮豹”再现江湖，而且这一次“顽皮豹”钻石戴在了一位在国际足坛上享有盛名的教练手上。而就在他带队比赛的当天，却惨遭毒手身亡。自然，他手上的那枚天价的戒指也不翼而飞，必定是被杀手一并带走了。此时，最大的嫌疑也落在了足球教练女友——美丽的歌星。','Pardon His French.',0,0,25.450534,5.6,550,93,'2006-01-18','en','/b9jwprAiK0O30ybzEMdk2zQsTQl.jpg',3.196332714674228,3,'2026-09-10',2,NULL,NULL),(12100,'风语者','Windtalkers','第二次世界大战期间初期，在太平洋战场上，日军总能用各种方法破译美军的密电码，这令美军在战场上吃尽了苦头。为了改变这种局面，1942年，几百名印第安纳瓦霍族人被征召入伍，因为他们的语言没有外族人能够听懂，所以美军将他们训练成了专门的译电员，人称“风语者”。作为美国海军的秘密武器，每个“风语者”都肩负着美军的至高机密，因此，他们也受到了特别的“照顾”──每个纳瓦霍译电员都由一名海军士兵贴身保护，一方面确保其人身安全，另一方面，如果译电员即将被日军俘获，保护者必须杀死他以保证密码不外泄。海军陆战队员乔·安德斯（尼古拉斯·凯奇饰）就是一名译电员保护者，他奉命保护一个名叫本·亚兹（亚当·比奇饰)的纳瓦霍士兵。在残酷的塞班岛战役中，被俘的命运就在眼前，执掌他人生杀大权的乔陷入了道德与军命两难的抉择：他到底能不能、该不该在紧急关头杀死已经和自己亲如兄弟的本，以履行军人的职责、保护美军的军事秘密呢……','Honor Was Their Code.',115000000,77628265,18.714197,5.8,341,134,'2002-06-14','en','/l4KelP1YBgMW8MqpspjAhufuNxV.jpg',3.113638770150051,3,'2026-09-10',2,NULL,NULL),(12103,'沉默生机','Don\'t Say a Word','纳森·康拉德（迈克尔·道格拉斯饰）是纽约著名的精神病医生，特别专长于青少年心理问题，他有一个温馨的三口之家。故事从他女儿被绑架开始，绑匪以他女儿的生命相威胁,要他在7天内办成一件事情：治好一个精神病患者。他必须与时间展开激烈的竞争，争分夺秒把女儿从绑匪手中解救出来。　　原来，一伙匪徒正在探寻他们多年前劫掠未遂的珠宝，而获取这一赃物的秘密则隐藏在一名年轻女子伊丽莎白·巴罗斯的大脑深处。数年前，伊丽莎白因目击这起突发的恐怖事件而精神失常，此后便一直辗转于精神病院，整日提心吊胆，害怕那些陌生的凶犯们发现自已的藏身之处。　　歹徒们绑架杰茜的目的很明确：纳森必须把伊丽莎白治好，并诱导她道出宝藏的秘密。糟糕的是，纳森必须在晚上5点钟以前把伊丽莎白搞定，否则杰茜就性命难保。由于歹徒们使用先进的监视器跟踪纳森和他妻子的一举一动，因此他们无法报警。与此同时，正在调查一起谋杀案的女侦探桑德拉·凯茜蒂顺藤摸瓜，与科斯特一伙以及正处于绝境中的康拉德医生撞了个正着……','...I\'ll never tell.',50000000,100020092,11.596207,6,220,113,'2001-09-28','en','/tZsPX8VJY4LhXKWwPTDuGOoLoLe.jpg',3.0246303043531677,3,'2026-09-10',2,NULL,NULL),(12106,'致命快感','The Quick and the Dead','在美国西部这个充满暴力的地方，赫罗德靠出色的枪法，成为远近闻名的魔王。他设立巨额奖金，在镇上举行枪击比赛，通过高手之间的互杀，使武艺高强的人越来越少，同时也趁机向居民收税。神枪手们蜂拥而至，其中有一个叫爱伦的神秘女郎。她父亲原是这个镇的警长，一次赫罗德袭击警署，把她父亲吊起来，说只要她能把绳子打断，就可放了他。她含泪用颤抖的手扣动扳机，不料子弹竟击中父亲的头部。枪击比赛越来越残酷，后来残忍的赫罗德居然亲手枪杀了自己的儿子基德。同时，在小镇弹药库爆炸的冲天火光中，爱伦出现在赫罗德面前。','Think you are quick enough?',32000000,18552460,16.473355,6.3,427,107,'1995-02-09','en','/yJlhgG4qNkPETyLlj5axPzzN7ot.jpg',3.2079083946361933,3,'2026-09-10',2,NULL,NULL),(12107,'肥佬教授2','Nutty Professor II: The Klumps','经历了上一集中的一番折腾后，舍曼教授（艾迪·墨菲 Eddie Murphy 饰）终于要结婚了，这位幸运的未婚妻不是别人，正是他的同事丹妮丝（珍妮·杰克逊 Janet Jackson 饰）。然而，就在这个节骨眼上，那个隐藏在教授脑中的“第二人格”布迪再度出现。为了期待已久的婚礼不被布迪破坏，教授决定好好对付一下自己的这位“老朋友”。\r 没想到，教授的举动非但没能让布迪消失，甚至让他有了一个独立的身体，脱离了教授掌控的他明目张胆地侵入了教授的生活，并且夺走了教授辛劳多年的研究成果——能够让人短暂返老还童的血清。血清的失窃在教授的家庭里引起了轩然大波，每一个人都渴望着能够享受重回青春的快感。局势是如此的混乱，教授感到梦幻般的婚礼仿佛离自己越来越远。','The Klumps are back!',84000000,123307945,17.783361,4.7,332,106,'2000-07-27','en','/v8gI95Eio7kAjixyqYHxNKmJTmm.jpg',3.002947226023731,3,'2026-09-10',2,NULL,NULL),(12109,'撼动生命','It\'s All Gone Pete Tong','片中DJ Frankie Wilde是虚构的人物，事实上并无此号DJ，不过电影从网站到宣传都刻意制造其“真人真事改编“的假像，连在片中受访的DJ Tiesto, Pete Tong和Carl Cox等都很配合的说，哦！没错 他真是个了不起的家伙...  　　剧情大纲：Frankie Wilde是世界知名的DJ，极具天份的他深受各大PUB及乐迷的拥戴，有着豪华的白色洋房，娇艳如花的美妻；除了音乐，不可或缺的菸酒与毒品，这些都让他享受如皇帝般的舒适生活！有一天，由右耳传来一阵阵鸣声干扰了他的听觉，渐渐地，当他把音量转到最大时，居然什么也听不到了…面对着满心期待的乐迷、满心信赖他的工作伙伴，他只能“佯装”一切如昔，只是，已经崩溃的听觉抓不到撼动的音乐；骤失工作及家人的他，彻底崩溃…直到，他终于又抓到音乐的震动…在国际上获奖大放光芒，加拿大多伦多电影节、最佳影片、HBO美国喜剧艺术节、最佳影片、最佳男主角、美国Gen Art电影节评审团大奖、观众票选最佳影片。',NULL,2000000,120620,3.911445,7.1,52,90,'2004-09-12','en','/4AvbVwbejmSMKGEdLmVYDLAss1i.jpg',2.7245917810149045,3,'2026-09-10',2,NULL,NULL),(12113,'Body of Lies','Body of Lies','The CIA’s hunt is on for the mastermind of a wave of terrorist attacks. Roger Ferris is the agency’s man on the ground, moving from place to place, scrambling to stay ahead of ever-shifting events. An eye in the sky – a satellite link – watches Ferris.  At the other end of that real-time link is the CIA’s Ed Hoffman, strategizing events from thousands of miles away. And as Ferris nears the target, he discovers trust can be just as dangerous as it is necessary for survival.','Trust no one. Deceive everyone.',70000000,113280098,37.507136,6.5,895,128,'2008-10-10','en','/1lKrYrJY3Eo4t2kCEOqIWFXwiND.jpg',3.4596810433223477,3,'2026-09-10',2,NULL,NULL),(12117,'本能反应','Instinct','伊森.鲍威尔是曾经是一位致力于大猩猩研究的人类学家。在非洲神秘失踪两年之後，终於被人们发现了行踪，但此时的他不但性情大变，而且由于杀人罪行被所有人视为极端危险分子。鲍威尔的奇怪转变引起了年轻的心理学家卡尔特的兴趣，他试图运用自己专业水平和聪明才智去揭开这位犯人的精神异常之谜。同时他更想引导鲍威尔说出当年的失踪原因和杀人经过。但同样有着高超心理分析能力的鲍威尔并不为年轻气盛的卡尔特所劝服，他对这位野心勃勃的心理学家一开始就充满着敌意。两位旗鼓相当的高手在气氛阴暗的监狱中展开了一场持久的心理战和智力竞赛。随着两人在心理上的逐渐认同和情感上的逐步接近，卡尔特发现在鲍威尔的内心深处，隐藏着一段有关人类残酷本性的悲剧性经历，而鲍威尔对自然生命的珍惜和保护使他开始意识到，平等和自由对于所有生命的重要意义。',NULL,80000000,0,7.386394,6.2,146,126,'1999-06-04','en','/8EKmzia6awjsqFxgBk5a82aTmb6.jpg',2.938690476091162,3,'2026-09-10',2,NULL,NULL),(12120,'天外飞仙','My Stepmother Is an Alien','史蒂文（丹艾克洛德，「福禄双霸天2000」、「另类杀手」）是个个性内向的天文学家，也是个鳏居的单亲父亲，当他的实验在阴错阳差下将一股巨大的能量送进太空时，他万万没想到竟会对另一个星球造成为威胁，引起他们的恐慌，因而派出一位特使前来地球调查原因；这位特使为了方便调查，遂化身身材火辣的性感美女（奥斯卡最佳女配角，「铁面特警队」、「梦游非洲」）接近史蒂文，想从他口中套出答案；飞来艳福的史蒂文爱上了这位举止诡异的美女，因而向她求婚，让她成为女儿的继母，而外星美女也爱上了这位害羞的天文学家--和性爱--但她能找出那股能量的起因，解救母星的危机，并打消上级为以绝后患而欲将地球毁灭的决定吗？本片是由理查班杰明（「1996麻雀变凤凰」、「风月俏佳人」）执导。','Man\'s closest encounter.',20000000,13854000,9.455596,5.3,131,108,'1988-12-09','en','/SIt5FbgvoxlZr8ay3cfi79pV6z.jpg',2.8785088870285915,3,'2026-09-10',2,NULL,NULL),(12123,'连锁反应','Chain Reaction','随着科技的进步和发展，科学家们终于研究出了能将水转化为能源的神奇技术，研究人员们想将研究结果公之于众造福人类，却遭到了金主保罗（摩根·弗里曼 Morgan Freeman 饰）的反对。  　　灾难降临了，在庆祝实验成功的晚宴后，有人杀害了巴克利博士（Nicholas Rudall 饰）后又在实验室里安装了定时炸弹，幸运地在悲剧中幸存的两名研究人员莉莉（蕾切尔·薇姿 Rachel Weisz 饰）和埃迪（基努·里维斯 Keanu Reeves 饰）还未能松一口气就发觉他们已经成为了警方的重大嫌疑人。为了证明自己的清白，莉莉和埃迪联手展开了对事件的调查。站在这一连串恐怖袭击事件背后究竟是谁？他这样的大动干戈又是为了得到什么呢？','Reaction Time 8-4-96',50000000,60209334,20.58862,5.3,284,107,'1996-08-02','en','/4ahjVHwXXsq5zK57ds8FwWY73MS.jpg',3.039849118319766,3,'2026-09-10',2,NULL,NULL),(12133,'非亲兄弟','Step Brothers','39岁的布伦南•哈夫（威尔•法瑞尔 Will Ferrell 饰）无业，一直在母亲南希（玛丽•斯汀伯根 Mary Steenburgen 饰）家蹭吃蹭住。40岁的戴尔•多巴克（约翰•赖利 John Reilly 饰）也是个与父亲罗伯特（理查德•詹金斯 Richard Jenkins 饰）住在一起的大龄男，靠父亲的接济生活。南希与罗伯特一见钟情，婚后搬入罗伯特家居住，布伦南也随母亲一起搬入，从此被迫以继兄弟的身份与戴尔同处一室。二人从相互敌视逐渐成为最佳拍档，共同对付布伦南的优秀弟弟德里克（亚当•斯科特 Adam Scott 饰），玩闹得不亦乐乎。可没想到他们的胡作非为却毁了父母刚建立起来的美满婚姻，二人后悔万分，终于决定痛改前非……','They grow up so fast.',65000000,128107642,22.977983,6.5,1062,98,'2008-07-25','en','/6nqlAgbw2mk3UwwreR32StExeWo.jpg',3.4684701344330984,3,'2026-09-10',2,NULL,NULL),(12138,'惊天骇地','3000 Miles to Graceland','莫非（凯文·科斯特纳 Kevin Costner 饰）、迈克尔（库尔特·拉塞尔 Kurt Russell 饰）、格斯（大卫·阿奎特 David Arquette 饰）等5名男子来到了位于拉斯维加斯的里维埃拉赌场，这里正在举行一场盛大的猫王模仿比赛，当然，这5个人来此可不是来参加比赛的，他们打算趁着人多将这个赌场洗劫一空。\r 　　计划非常顺利的进行着，一行人带着他们抢到的320万美金坐上了早已经在赌场天台等候多时的直升机，就在众人美滋滋的准备分赃之时，莫非却为了能够独吞赃款而举枪向另外四人射击。实际上，莫非的小算盘早已经被和他最为相熟的迈克尔知晓了，因此那天他特地穿上了防弹衣，逃过一死。','Crime Is King.',62000000,18720175,11.262655,5.8,178,125,'2001-02-23','en','/nJgr5sGoXnsgZ0EVt80i6X9dQiA.jpg',2.967518532661407,3,'2026-09-10',2,NULL,NULL),(12142,'鬼屋魔影','Alone in the Dark','距今一万年前的美洲，阿卡尼文明盛行一时，阿卡尼相信世界分为光明与黑暗两个世界，彼此间存在联络之门。有记载称阿卡尼曾打开两个世界间的门，使一些魔物肆虐世间，随后阿卡尼神秘灭亡。20世纪60年代，政府成立超自然研究部门713局，委派莱昂内尔•哈金斯博士（Matthew Walker 饰）研究阿卡尼文明，但他的研究随后被推翻。哈金斯躲在一个小岛，对儿童进行残酷的秘密试验，使他们和魔物融为一体。  21世纪初，各地接连发生儿童失踪案件，超自然现象调查员爱德华•卡比（Christian Slater 饰）受命前往小岛调查，但他才出机场，便遭到神秘之人的攻击。这一切注定他的旅程艰险无比……','Can mankind defeat the army of darkness unleashed by an ancient evil cult?',20000000,10442808,9.292987,3.1,173,96,'2005-01-28','en','/w8tWGl6qlGYAhFUMhs2bE2bynn0.jpg',2.801832629635639,3,'2026-09-10',2,NULL,NULL),(12144,'小脚板走天涯','The Land Before Time','当一场惊天动地的地震杀死了他的父母，一头名叫小脚板的年轻的雷龙与其他的恐龙孤儿们一起面临着生存的难题......','A new adventure is born.',12300000,84460846,28.670193,7,640,69,'1988-11-18','en','/7phV1ETZnQrLsEeuk4hNeceEl25.jpg',3.427206844850576,3,'2026-09-10',2,NULL,NULL),(12149,'替天行道','Frailty','韦斯利（鲍沃斯·布斯 Powers Boothe 饰）是一名探员，最近，他正在调查一宗名为“上帝之手”的恶性连环杀人案件，一个名叫芬顿（马修·麦康纳 Matthew McConaughey 饰）的神秘男人找到了韦斯利，并告诉他自己知道整个案件的来龙去脉，让韦斯利感到震惊的是，如果事实真的如芬顿所言，那么凶手不是别人，正是芬顿那已经自杀的弟弟亚当（杰瑞米·桑普特 Jeremy Sumpter 饰）。韦斯利跟随芬顿来到了亚当的墓前，在那里，芬顿向韦斯利讲述了他和亚当的过往。  　　原来，一切事件起源于兄弟两人的父亲梅克斯（比尔·帕克斯顿 Bill Paxton 饰），他告诉两兄弟自己遇见了天使，这位天使给了他一份名单，名单上记载的都是化身为人类的恶魔，而梅克斯要做的，就是将他们一一杀死。对于父亲的话，亚当信以为真，而芬顿却察觉到了其中的疯狂，两人的命运自此走上了截然不同的道路。','No Soul Is Safe.',11000000,13110448,16.003958,7,334,100,'2001-11-17','en','/iq0GvtEQxeYPLa4CXyphjl0rcVC.jpg',3.2165527524853132,3,'2026-09-10',2,NULL,NULL),(12150,'午夜惊情','Sea of Love','法兰克（阿尔·帕西诺 Al Pacino 饰）是一名脆弱又寂寞的纽约警察，无法面对妻子离他远去的事实，沉溺在酒精的麻痹中。此时，纽约市发生一连串的男尸谋杀案，法兰克受命与警探薛曼搭档调查，他们深信凶手是一名女子，藉由报纸上的征友启事结识受害者，然后在播放浪漫的“爱之海”歌曲时，借机杀死对方。于是，法兰克伪装身份在报上登了征友启事，设下陷阱引诱女嫌犯上钩，不久后，性感强悍的海伦（艾伦·巴金 Ellen Barkin 饰）出现了，两人很快地陷入情网，法兰克一步步地发现种种证据，全都指出头号嫌疑犯就是海伦，但是寂寞的他，却陷在海伦的情爱诱惑中无法自拔。当那首致命的《爱之海》旋律再度响起时，危机已向他逼近……','Deception is dangerous. Desire is deadly.',19000000,110879513,11.47316,6.7,141,113,'1989-09-15','en','/vJ88WmJ12eAK9CRb3cggn9CJthH.jpg',2.9647116303956773,3,'2026-09-10',2,NULL,NULL),(12153,'小姐好白','White Chicks','黑人警探马库斯（马龙•韦恩斯 Marlon Wayans 饰）和凯文（肖恩•韦恩斯 Shawn Wayans 饰）在一次扫毒行动中假扮小店老板，准备抓拿前来的毒贩，但是由于没人支援，这一行动搞砸了。为了挽回在上司和同事面前的面子，这两个黑人警探决定挑战一项艰巨的任务：那就是伪装成富有的白人姐妹——威尔顿姐妹，亲身引诱企图绑架这两姐妹的穷凶极恶的绑匪现身。在涂上了厚厚的白粉，浓妆艳抹后，这两个黑人小伙摇身变成了性感漂亮的白人姐妹。于是，一连串爆笑惊险的场面上演了。','They\'re going deep undercover.',37000000,113086475,28.703007,6.3,679,109,'2004-06-23','en','/kKBTZi21NCtAgyy42Ues9UGwQBR.jpg',3.3427217555410964,3,'2026-09-10',2,NULL,NULL),(12154,'三个奶爸一个娃','3 Men and a Baby','三个钻石王老五：建筑师彼得（汤姆•塞立克 Tom Selleck 饰）、艺术家麦克（斯蒂夫•古根伯格 Steve Guttenberg ）和演员杰克（特德•丹森 Ted Danson 饰）合住在曼哈顿的一套高级公寓内，三人风流成性，过着悠然自得的生活。然而，这种生活就在杰克出外地拍片的某天早上被打破了。另外两个室友在公寓门口发现了一名被遗弃的女婴，据遗弃者留下的字条称，这是杰克的亲生女儿。彼得和麦克只得将女婴抱进屋内，开始了“初为人父”的生活。虽然两人经常应付各种各样的女人，然而应付女婴还是第一次。他们被女婴搞得手忙脚乱，焦头烂额；然而通过一阵子的相处，他们内心的父爱情结又油然而生……','They changed her diapers. She changed their lives.',0,0,12.335827,5.8,253,102,'1987-11-27','es','/oYetboAljWR2N5A7MU3i63DvUtd.jpg',3.04020081950999,3,'2026-09-10',2,NULL,NULL),(12155,'爱丽丝梦游仙境','Alice in Wonderland','Alice, an unpretentious and individual 19-year-old, is betrothed to a dunce of an English nobleman. At her engagement party, she escapes the crowd to consider whether to go through with the marriage and falls down a hole in the garden after spotting an unusual rabbit. Arriving in a strange and surreal place called \'Underland,\' she finds herself in a world that resembles the nightmares she had as a child, filled with talking animals, villainous queens and knights, and frumious bandersnatches. Alice realizes that she is there for a reason – to conquer the horrific Jabberwocky and restore the rightful queen to her throne.','You\'re invited to a very important date.',200000000,1025491110,78.530105,6.4,4645,108,'2010-03-03','en','/o0kre9wRCZz3jjSjaru7QU0UtFz.jpg',3.921230025231508,3,'2026-09-10',2,NULL,NULL),(12158,'布鲁克林吸血鬼','Vampire in Brooklyn','恐怖的吸血鬼一直是影坛极爱采用的题材，但是这个题材交到搞笑见长的艾迪墨菲手上，却有不一样的新意。＂我＂片中墨菲饰演能随意幻化外貌的吸血鬼麦克斯，为了繁衍下一代，他来到世界之都－纽约，找寻合适的对象。女警丽塔是麦克斯看中的对象，他使出混身解数展开追求，但却遭到百般阻挠···。本片中墨菲变换了数种面貌、造型变化多端，令观众时时刻刻都有惊奇，而吸血鬼题材向来所见的惊悚感，配上本片刻意营造的喜剧特色，综合出一般又惊又喜的感受。','A comic tale of horror and seduction.',14000000,19800000,6.772615,4.5,111,100,'1995-10-27','en','/fodPA5x3REtOwColG17CucreZqM.jpg',2.8098896147291734,3,'2026-09-10',2,NULL,NULL),(12159,'美梦成真','What Dreams May Come','克里丝（罗宾·威廉姆斯 Robin Williams 饰）与安妮（安娜贝拉·莎拉 Annabella Sciorra 饰）深爱着彼此，这对让人艳羡的夫妻有个美满的家庭，聪明可爱的孩子们，坚贞不移的爱情。可是一切都在孩子们意外死亡后打碎了。自从孩子们逝世后，克里丝与安妮夫妇俩每天都活在痛苦之中，他们心里惦记的始终是死去的孩子，他们的生活彻底失去了快乐的根源，都变得郁郁寡欢，但两人依然互相依靠着生活。可是，厄运并没有就此停止。安妮最心爱的克里丝也在意外当中逝世，死后的克里丝在天堂上看到了自己的孩子，仿佛生活又回到了当初快乐的样子，但他的心里仍记挂着尚在人间的妻子。丈夫的逝世，使安妮心痛不已，生活变得更加难熬了。终于，她还是无法忍受独自生活的寂寥，自杀了。生前的她经常凭想象画出天堂的样子。可是由于自杀，她只能堕入地狱。克里丝誓要留在妻子身边，不让她继续受折磨。于是，他到地狱去了…… ©豆瓣','After life there is more. The end is just the beginning.',85000000,71485043,21.891078,6.8,577,113,'1998-10-02','en','/iEuJiQXj56by7f1gEAovAKi3YB7.jpg',3.3558979843472794,3,'2026-09-10',2,NULL,NULL),(12160,'义海倾情','Wyatt Earp','故事开始于怀俄明州的乡间，我们的主人公怀厄尔普（凯文·科斯特纳 Kevin Costner 饰）就出生在那里。为了参加南北战争报效祖国，怀厄尔普离家出走英勇的赶往前线，却因为年龄的问题而被拒绝入伍。之后，怀厄尔普开始攻读法律，并且邂逅了名为乌瑞拉（贝蒂·巴克利 Betty Buckley 饰）的女子。两人双双坠入爱河之后很快便携手步入了婚礼的殿堂。 然而，幸福美满的日子却并没有维系太长的时间，一场大病夺走了乌瑞拉的生命，令怀厄尔普陷入了绝望和自暴自弃之中。就在他濒临崩溃之时，父亲尼古拉斯（吉恩·哈克曼 Gene Hackman 饰）来到了他身旁，将怀厄尔普重新引回了正途。','The epic story of love and adventure in a lawless land.',63000000,25052000,13.859307,6.5,202,191,'1994-06-24','en','/51LItgyecu2KMAtIchYogEykCIu.jpg',3.044419078195783,3,'2026-09-10',2,NULL,NULL),(12162,'拆弹部队','The Hurt Locker','当新上任的上士詹姆斯在激烈冲突中接手一支训练有素的炸弹拆除小组时，他鲁莽地将两名下属桑伯恩与埃尔德里奇拖入致命的城市战斗游戏，令他们震惊不已。詹姆斯表现得仿佛对死亡毫不在意。当队员们试图掌控这位狂野的新领导时，整座城市已陷入爆炸与混乱，而詹姆斯的真实性格逐渐显露，将永远改变每个人的命运。[顶峰娱乐]','You\'ll know when you\'re in it.',15000000,42000000,47.006162,7.2,1840,131,'2008-10-10','en','/io2dfBJhasvGbgkCX9cCGVOiA99.jpg',3.8073799151768415,3,'2026-09-10',2,NULL,NULL),(12163,'摔角王','The Wrestler','绰号“大锤”的兰迪•罗宾森（Mickey Rourke 米基•洛克 饰）是上世纪80年代美国独立摔角圈中一颗耀眼的明星，他留下了无数经典的比赛，其绝招“大锤粉碎压”更虏获众多狂热的摔角爱好者。\r 　　但随着行业的飞速发展和身体健康状况的下降，属于“大锤”的时代早已远去。出于对摔角的热爱，兰迪始终没有离开这个圈子，他忍受着生活拮据，忍受着伤痛困扰，只为了和陪伴多年的摔角迷们享受每一次秀所带来的莫大快乐。他固执地追逐着最后一丝荣光，私人生活却越来越糟。长年奔波以致和女儿斯蒂芬妮（Evan Rachel Wood 埃文•蕾切尔•伍德 饰）的关系疏远，剧烈的撞击和不断摄取处方药又令他的心脏接近崩溃边缘。孤独的他只能在每次艰苦的比赛之后，从脱衣舞女卡西迪（Marisa Tomei 玛丽莎•托梅 饰）那里得到些许短暂的安慰。\r 　　因身体的原因，兰迪决定退出摔角圈，做一份稳定的工作，并找回家庭的温暖。但经理人策划了一场二十周年的经典重赛。为了毕生钟爱的摔角、为了狂热执著的摔角迷、为了心中长久以来所坚持的，兰迪终于再次披挂上阵，重返擂台……\r 　　本片荣获2008年威尼斯电影节金狮奖、2009年英国艺术电影电视学院奖（BAFTA）最佳男主角奖（Mickey Rourke）、2009年金球奖最佳原创歌曲和最佳男主角。','Love. Pain. Glory.',6000000,44703995,40.196514,7.3,1000,109,'2008-09-07','en','/5O7XKW2JhaGsuoUfiWy34XP5N0k.jpg',3.631909295229796,3,'2026-09-10',2,NULL,NULL),(12177,'爱情导师','The Love Guru','皮卡（麦克·梅尔斯 Mike Myers 饰）刚刚降生就被双亲遗弃，幸运的是，一个虔诚的印度宗教家收养了嗷嗷待哺的皮卡，将他养大成人。长大后的皮卡受到故乡的召唤，远渡重洋回到了故乡美国，在那里，他利用自己印度教导师的身份开办了一个“诊所”，专门治疗恋爱中的疑难杂症。这种融合了宗教和精神力量的新颖治疗方式很快就为皮卡赢得了金钱和名誉，但当球队经理布拉德（杰西卡·阿尔芭 Jessica Alba 饰）出现在他面前时，皮卡的一切经验都失去了效用。\r 　　在布拉德的委托下，皮卡开始了对球队主力戴伦（罗曼尼·马尔可 Romany Malco 饰）和其妻子之间感情的医治，没想到这一对关系诡异的夫妻让皮卡的治疗变得困难重重。皮卡能够顺利完成布拉德的委托吗？男人和女人之间的感情难道真的如此脆弱吗？','His Karma is Huge',62000000,41819064,13.218008,4.3,242,87,'2008-06-20','en','/sp8AV64ftAZCT9uWfgbCb3olGDW.jpg',2.9211729236795443,3,'2026-09-10',2,NULL,NULL),(12182,'爱情无限谱','Nick and Norah\'s Infinite Playlist','尼克（迈克尔·塞拉 Michael Cera 饰）是个高中生贝斯手，有着不凡的音乐才华，不过性格内向木讷，因此惨遭女友抛弃；诺拉（凯特·戴琳斯 Kat Dennings 饰）是个有头脑的个性女孩，从小受音乐人父亲影响深远，对音乐极其敏感。机缘巧合之下，诺拉拾到一张CD，被里面的音乐打动，后又在一场演唱会上遇到尼克，对他一见钟情。荒诞的一夜就此开启，尼克要求诺拉做他“五分钟女友”，恰逢诺拉好友卡罗拉喝醉走失，于是两个人拉上整个乐队成员踏上寻人之旅。期间，诺拉发现CD的原主人正是尼克，尼克也被诺拉带到父亲曾经的录音室，受到极大震撼，两个同样爱着音乐的年轻人，尝试和试探着走在一起…… ©豆瓣','Every night has a soundtrack.',9000000,32973937,20.452449,6.4,379,89,'2008-10-03','en','/cndxWgZEHnSUtytrMjal97ye34E.jpg',3.1998981754660156,3,'2026-09-10',2,NULL,NULL),(12183,'温德尔·贝克的故事','The Wendell Baker Story','Luke Wilson plays a good-hearted ex-con who gets a job in a retirement hotel. Three elderly residents help him win back his girlfriend as he lends them a hand in fighting hotel corruption.',NULL,0,0,1.265683,5.2,16,99,'2005-08-03','en','/sdBiC4J0QMDOoPzX4eudGnTM0MJ.jpg',2.4460135257212197,3,'2026-09-10',2,NULL,NULL),(12184,'另一个波琳家的女孩','The Other Boleyn Girl','玛丽•波琳（斯嘉丽•约翰逊 饰）与姐姐安妮（娜塔丽•波特曼 饰）美丽动人，如此优点却遭到了父亲与叔叔加以利用。为了提升自己家族的地位与权利，玛丽的父亲要把玛丽送进皇宫当中，成为了当时国王亨利八世（艾瑞克•巴纳 饰）的情妇。 　　玛丽后来怀上了国王的孩子，但她的姐姐安妮也在这个时候进入皇宫，她要勾引国王以得到宠爱。原来安妮早已对进入皇宫密谋已久，为的是得到国王的宠爱以得到皇后的位置，全然不顾自己妹妹玛丽早已对国王产生了真感情。 　　于是，同是波琳家族的一对姐妹为了各自的爱情与利益在皇宫中明争暗斗。姐妹俩争斗过后得到的结果到底如何？','Two sisters divided for the love of a king.',35000000,0,22.939557,6.4,477,115,'2008-02-28','en','/5vAZ1ZW7C4C3R3Vb3P2YE9bCcfB.jpg',3.260011907110017,3,'2026-09-10',2,NULL,NULL),(12192,'恐怖解剖室','Pathology','英俊帅气、年轻有为的泰德•格雷（Milo Ventimiglia 米洛•文堤米利亚 饰）事业爱情双得意，他以优异的成绩从哈佛医学院毕业，随后被推荐进入全国最有名的病理学研究小组；另一方面，泰德和女友格雯（Alyssa Milano 阿莱萨•米兰诺 饰）感情顺利，令人欣羡。凭借出众的才干与丰富的学识，泰德很快便在这人才辈出的研究小组中崭露头角，受到同侪的赏识与器重。但他很快便发现，这个小组的工作人员似乎隐藏着不为人知的秘密。原来，这些衣冠楚楚研究人员竟然暗中进行一连串的杀人事件，他们为了创造出完美的杀人纪录而疯狂竞赛。泰德同时发现，自己也在其中越陷越深。是逃脱，还是同流合污，他面临着痛苦而危险的选择……','No body is safe.',8000000,0,9.782433,5.6,144,95,'2008-04-11','en','/kbrolVrvJo0bNWShvT0RNyPAHvN.jpg',2.911428659825314,3,'2026-09-10',2,NULL,NULL),(12193,'四个圣诞节','Four Christmases','当最后一片落叶亲吻第一朵雪花,当商场挤满疯狂采购的人群,当预定云杉和火鸡的热线永远打不通......一定是圣诞节将至了.可旧金山的布拉德和凯特却总是如临大敌.一想到要把美好假期奉献给无聊老套的家庭聚会,还要伙同老少亲戚去教堂接受唱诗班的催眠,这对小夫妻就恨不得去跳金门大桥.前几年,两人都巧妙骗过家人,展开了美妙的圣诞旅行.  　　人算不如天算,今年的圣诞节,本来布拉德和凯特又已成功瞒过家人;本来,他们可以顺利飞往斐济,在热带小岛上拥抱圣诞;本来,即使不去旅行,红酒烛光+二人世界听起来也不错---不幸的是,圣诞节当日,这对活宝奔赴机场准备飞跃太平洋,被告知所有航班皆因大雾而取消,他们身着花衬衫,头戴大草帽的大傻样儿还上了电视新闻.双方父母都已离婚,并分别开始了新生活,被困旧金山,意味着这个佳节将被一分为四,可事已至此,两人只得一一拜访.岳父是个孤傲的老头,丈母娘时髦而神经质,为了营造欢乐祥和的气氛,两人姑且忍了,马不停蹄地赶往第三家,却被麻辣婆婆和小她25岁的新男友惊到下巴脱臼.气郁之下,布拉德拽着凯特赶往父亲家,却遇上了集异装癖,格斗狂于一身的同父异母兄弟,还有那满屋子乱窜的侄子侄女......梦寐以求的假期终以闹剧收场,疲于奔命后,两个倒霉蛋开始寻找新的浪漫......','His father, her mother, his mother and her father all in one day.',80000000,163733697,19.500893,5.3,331,88,'2008-11-26','en','/gq3zISFU8OcQ51vBK2nAlRuGaBw.jpg',3.062729874878214,3,'2026-09-10',2,NULL,NULL),(12201,'黑暗边缘','Edge of Darkness','梅尔吉布森在片中饰演一位思想固执而刻板的警察，他的女儿与其性格正相反，是一个激进分子。在女儿突然被杀后，主人公发誓要查清真相，然而随着调查的深入，他发现原来此中牵涉到一系列贪污腐败的案件……  一句话评论  一部令人激动的政治阴谋片。  梅尔吉布森重新在大银幕上绽放了他的魅力，非常明智！  ——《波士顿环球报》  一部强烈表现梅尔吉布森来势汹汹的犯罪惊悚片。  ——《好莱坞报道》','Some secrets take us to the edge.',80000000,74901339,24.657931,6.2,487,117,'2010-01-29','en','/6fXwoM0JAyNJarGLeddoYA4bs88.jpg',3.2448207660938873,3,'2026-09-10',2,NULL,NULL),(12207,'醉拳2','醉拳二','民初年间，年轻的黄飞鸿（成龙 饰）自学了一套威力无穷的拳法——醉拳。但是每次打出这套拳法，都要先喝得酩酊大醉，利用醉态打破一切武学定律，才能发挥出醉拳的威力。因为这样，黄飞鸿父亲黄麒英严禁儿子练这种有伤风雅、而且违背习武强身法则的拳法。年少顽皮的飞鸿常常背着父亲在练习醉拳，并以此打败了众多强手。这天，飞鸿和父亲一起上东北办事。半途上，父子俩遇上了一伙外国强盗，他们暗中将国宝玉玺偷运出境。为了阻止这伙强盗、夺回国宝，飞鸿只好使出他的拿手绝活——醉拳','He\'s got a secret weapon with a lot of kick.',0,0,15.046612,7.2,242,102,'1994-02-03','cn','/9OcJAuijrQxU261uzO5eBphxKWk.jpg',3.142305101031625,3,'2026-09-10',2,NULL,NULL),(12211,'高地人4：终极之战','Highlander: Endgame','几个世纪以来，不死人之间的战斗从来没有停止过。这一次，超级强大的不死人凯尔从过去来到了现在，他的强大是其他不死人难以望其项背的，无论柯南还是邓肯，若论单挑都不是他的对手。两个人遭到了拥有各种绝技的恶毒暗杀者的围攻，他俩不仅要在各个时空中穿梭联手抗敌，最后还要其中的一个做出牺牲才能战胜邪恶的力量……','It will take two immortals to defeat the ultimate evil. But in the end, there can be only one.',25000000,15843608,11.782725,4.4,104,87,'2000-09-01','en','/u7kIXMyagqcek2SaS9svfPTTGVT.jpg',2.807101503238247,3,'2026-09-10',2,NULL,NULL),(12212,'下一个就是你2','Urban Legends: Final Cut','阿尔派大学是一所旨在培养电影方面人才的高等学府，该校所特别设立的希区柯克奖更被学子们视为至高无上的荣誉。美丽女孩艾美·梅菲德（珍妮弗·莫瑞森 Jennifer Morrison 饰）此前多担任其他同学剧组里的工作人员，她无时无刻不想制作一部属于自己的作品。在与保安里斯（Loretta Devine 饰）聊天时，对方向她讲述了发生在另一所大学里的连环杀手的故事。艾美认为这是个不错的题材，并打算将其作为自己的处女作。在此之后，同学查韦斯（Matthew Davis 饰）、斯坦（Anthony Anderson 饰）、德克（Michael Bacall 饰）、珊德拉（Jessica Cauffiel 饰）等人先后加入剧组，连环杀手的故事正式开拍。然而在影片拍摄过程中，剧组成员接二连三死于非命。艾美渐渐意识到，一个隐藏在深处的连环杀手正一步步向他们逼近……','Legends Never Die.',14000000,38574362,8.885017,4.4,100,97,'2000-09-19','en','/9kjGrnhMz37RYEd5BFcrU1qkPkl.jpg',2.7942194228086588,3,'2026-09-10',2,NULL,NULL),(12220,'我们的故事','The Story of Us','当爱逐渐变得褪色无光，婚姻的瓶颈期就随之而来了。本（布鲁斯·威利斯 Bruce Willis饰）和凯迪（米歇尔·菲佛 Michelle Pfeiffer饰）的婚姻也面临着这个难题。一方面，他们还爱着对方，另一方面却又对每况愈下的婚姻质量失去耐性。孩子们去夏令营了。这一个月里面，他们可以有足够的空间和时间重温旧梦，寻回爱情的美妙感觉。然而，他们的努力一再白费。刻意的挽回婚姻只令彼此都更清楚到了非分开不可的地步了。于是，二人协商，在孩子们回来的那天，要跟他们好好谈论离婚的决定。  　　首先反悔的是凯迪，她对本的爱情明明还在，而这个家庭的气息让她如此舍不得摧毁。凯迪的爱意让本也觉得，他们应该再为婚姻的努力一下……',NULL,50000000,58900031,6.22577,5.9,75,95,'1999-10-13','en','/8rm0CZpHW1D7pIv8OguJNHF93LV.jpg',2.7824559975149494,3,'2026-09-10',2,NULL,NULL),(12227,'雪地黄金犬','White Fang','为了完成父亲的遗愿，杰克只身来到了遥远的阿拉斯加寻找金矿。在这里，他遇见了善良友好的艾利克斯，两人决定结伴共同奋斗。一只名叫白牙的阿拉斯加雪橇犬改变了杰克的命运，将他从死亡线上挽救了回来，而当白牙被赌狗的恶棍们当成摇钱树之时，杰克也毫不犹豫的对其伸出了援手。一人一狗之间，友谊和信任正在慢慢滋生。白牙靠着自己的天赋帮助杰克与艾利克斯找到了金矿，亦保护了金矿不被坏人夺走。当发了财的艾利克斯邀请杰克回纽约一起创业之时，面对依依不舍的白牙，杰克犹豫了。','Where civilization ends, their journey begins.',14000000,34793160,13.13724,6.5,135,107,'1991-01-18','en','/27wg0rVZW8hX7nWeHCwTf9DygGc.jpg',2.948730863011711,3,'2026-09-10',2,NULL,NULL),(12228,'深喉揭密','Inside Deep Throat','《深喉揭密》是一部解构1972年备受争议的著名色情电影《深喉》的纪录片，当中剪辑了大量热辣露骨的性爱场面。本片大胆谈「情」之余还探讨60年代一场传统保守派对性解放潮派的道德战。性革命、反淫秽法、妇权主义以及成人娱乐发展的课题亦一一解读，从《深喉》带出社会及文化遗产。片中更有博学多才的学者及作家如艾伦‧德苏韦兹(Alan Dershowitz)、哥尔‧韦度(Gore Vidal)、拿文‧密拉(Norman Mailer)、甘美‧柏丽雅(Camille Paglia)、约翰‧屈打士(John Waters)、艾丽加‧庄(Erica Jong)、迪‧加菲尔(Dick Cavett)、标‧马艾(Bill Maher)为大家深入浅出地解说《深喉》 。','It was filmed in 6 days for 25 thousand dollars. The government didn\'t want you to see it. It was banned in 23 states. It has grossed over 600 million dollars. And it is the most profitable film in motion picture history.',2000000,653621,3.980072,6.8,31,92,'2005-02-11','en','/iy96Ud1jpnjOEYiHh2XMooD1PfG.jpg',2.6038664592914533,3,'2026-09-10',2,NULL,NULL),(12244,'机器人9号','9','影片主角是由拉链、纽扣，别针和麻布头组成的布娃娃机器人9号。9号醒来时，美丽的城镇已经被破坏，到处是破败不堪的场景，自己是置身于毁 灭后的荒凉世界，人类消失了、漫游在地球上的巨大的机器想要杀死最后仅存的生命。9号幸运的碰到了外出的2号，但是刚见面不久就被一个恐怖机器怪兽袭击，在袭击当中2号被怪兽掠夺走，9号虽然逃过一命但是也身受重伤，最后支撑不住晕倒。9号晕倒时正好被5号发现，5号把9号带回来他们的栖息地-也是基地，1号告诉醒来的9号从1号出现以后的一些经过，这个世界的人类消失了，只剩下他们和一只怪兽，并且1号警告9号不要外出送死，想活命就得躲好，然后派勇猛粗壮的而且对1号言听计从的8号看好他们，9和5号站在楼顶观望远处，他们在一番口头争斗之后最后勇敢的9号终于说服5号跟他一起去寻找2号。','When our world ended their mission began.',30000000,48428063,55.806402,6.6,1262,79,'2009-08-19','en','/l0oJm2itWWiLj10jgFUsjSpgWHI.jpg',3.604663764404739,3,'2026-09-10',2,NULL,NULL),(12245,'深度谜案','The Oxford Murders','马丁（伊利亚•伍德 Elijah Wood 饰）为了追寻偶像逻辑数学家亚瑟（约翰•赫特 John Hurt 饰）的足迹，来到牛津大学深造。他发现，寄宿的房东伊格莱顿太太（安娜•玛西 Anna Massey 饰）仿佛跟亚瑟交往甚密，而她的养女贝丝（朱丽•考克斯 Julie Cox 饰）却总是故弄玄虚。后来，马丁结识了壁球伙伴洛娜（蕾欧诺•瓦特林 Leonor Watling 饰），两人堕入爱河……  　　亚瑟演讲时，马丁作为唯一的提问者，引起了他的注意。后来，二人在房东家不期而遇，发现伊格莱顿太太被人谋杀。现场唯一的线索是一个圆圈。二人被警方带走协助调查。此后又有一些人离奇地死去，而且他们的死因似乎还暗含着某个数学定律……','There is no way of finding a single absolute truth',14100000,0,9.318033,5.7,188,107,'2008-01-18','en','/aPGyZg44eCxccfoaNNbJwTJj66J.jpg',2.9679043208626164,3,'2026-09-10',2,NULL,NULL),(12246,'蒙古王','Монгол','少年铁木真随父亲——乞颜部落首领也速该（Ba Sen 饰）远行，为了平复与仇敌蔑儿乞人之间的恩怨，也速该希望儿子选择蔑儿乞人的女儿为妻，而铁木真却选择了弘吉剌部落首领的女儿孛儿帖，并承诺五年后前来迎娶。归途中，也速该死于敌人塔塔儿人的毒酒，部落的牛马和牧民也被叛徒虏去。铁木真从少年时起便经历了人生困苦，他一面和母亲四处漂泊，一面躲避着仇家的追杀。  长大成人的铁木真（浅野忠信 饰）依然生活在刀光剑影之中，纵然朝不保夕，他仍记得与孛儿帖的约定，终于将孛儿帖（Khulan Chuluun 饰）迎娶回家，生活开始出现转机。然一场灾难尾随而至，蔑儿乞人为报当年仇恨，射伤铁木真，虏去孛儿帖。伤愈的铁木真只得求助好友札木合（孙红雷 饰）……  　　  本片荣获包括2008年亚洲电影节最佳配角奖（孙红雷）、2007年俄罗斯金鹰电影节最佳服装设计和最佳音效在内等国际电影节11个奖项。','Greatness comes to those who take it.',18000000,26527510,10.1449,6.5,158,120,'2007-09-20','ru',NULL,2.9783688704428184,3,'2026-09-10',2,NULL,NULL),(12247,'猎枪往事','Shotgun Stories','海耶斯家的三兄弟没有名字，他们的父亲只是简单粗暴的称呼他们为儿子（迈克尔·珊农 Michael Shannon 饰）、孩子（Douglas Ligon 饰）和小子（巴洛·雅克布斯 Barlow Jacobs 饰）。在决定彻底和过去告别，开始新的生活后，父亲果断的将三个男孩丢给了他们的母亲，从此人间蒸发对四人的死活不闻不问。\r 一晃眼多年过去，曾经抛家弃子的男人，在另一个小镇上却成为了德高望重的好好先生，他再度组成了家庭，并有了另外的四个孩子，一家人无比的团结和恩爱。一晃眼多年过去，当三个男孩再度接收到有关父亲的消息时，得到的是他的死讯。为了处理父亲的后事，他们来到了父亲生前生活过的小镇上。','Two families. One feud. No going back.',0,0,5.251143,6.9,57,92,'2007-10-01','en','/aeIlHt28Z8KmHcKEgl4oLHpwZ8M.jpg',2.7446337345925795,3,'2026-09-10',2,NULL,NULL),(12257,'爱情向前冲','Home Fries','莎莉（德鲁·巴里摩尔 Drew Barrymore 饰）并不知道，曾经和自己各种柔情蜜意你侬我侬的“好男人”亨利（克里斯·埃里斯 Chris Ellis 饰）其实是一位有妇之夫，更糟的是，这位花花公子竟然因为心脏病突发而死亡了。\r 　　不久之前，亨利的老婆碧翠丝（凯瑟琳·欧·哈拉 Catherine O\'Hara 饰）得知了亨利的不轨，为了查明真相，她将这一重任托付给了儿子多利（卢克·威尔逊 Luke Wilson 饰）和安格斯（杰克·布塞 Jake Busey 饰），很快，两人便得知了莎莉的存在。脾气火爆的安格斯决定给莎莉一点颜色瞧瞧，但多利却发现，自己怎么也无法向莎莉下手，因为在内心深处，他早已经深深的爱上了这个漂亮的女孩。','A long shot romance in a short order world.',15000000,10443316,3.033471,4.8,32,93,'1998-11-25','en','/rXEpaJIPlBqKq7QepB8uowmeAT2.jpg',2.583397472877996,3,'2026-09-10',2,NULL,NULL),(12271,'工厂女孩','Factory Girl','一个前卫艺术大师，一位性感火辣纵情女郎，还有民谣大师。三角恋+狂野派对+写实，讽刺好莱坞的经典，不得不看。 《工厂女孩》讲述的是一代前卫艺术大师安迪·沃霍、名噪一时的电影明星伊迪·塞奇威克以及民谣大师鲍勃·迪伦之间三角恋情的故事…… 安迪·沃霍的工作室名叫“工厂”，他大量著名的平版画、电影剧本和表现性解放的短片就是在“工厂”诞生的。包括鲍勃·迪伦、杜鲁门·卡波特和卢·里德等流行文化标志性人物都曾是“工厂”的常客，这里的派对狂野异常。作为成功的模特，塞奇威克有其噩梦般的过去——她曾被父亲和兄长性骚扰，一直在与海洛因和精神疾病作战。1965年，她遇见了沃霍，成了他的“超级巨星”。沃霍让她主演了自己的许多电影，其中大多是讽刺好莱坞的。两人在1966年分道扬镳。塞奇威克后来因吸毒过量去世。《工厂女孩》回顾的正是两人在一起的这段时间。','When Andy met Edie, life imitated art.',7000000,0,11.400229,6.2,81,90,'2006-12-29','en','/A5Sq71054VptVUQYGdIjjim4hFn.jpg',2.819353284406296,3,'2026-09-10',2,NULL,NULL),(12277,'卧底兄弟','Undercover Brother','黑人喜剧明星艾迪格里芬在影片中饰演一位留着非洲发型，一副七十年代流行装扮的黑人英雄，绰号“Undercover Brother”的间谍。他被委派去打入一个邪恶的反政府组织的内部，以便在适当的时机瓦解他们，和他合作的是一位性感的新来女同事。他们在潜入这个组织之后，积极寻找组织的犯罪证据，但不久却被人发现，对方派来了另外一位性感女人来对付他……','He\'s All Action',25000000,41604473,6.086083,5.5,112,86,'2002-05-31','en','/vkPm29sqtEjoekOhXbqxTcgpJ4y.jpg',2.8497316486791893,3,'2026-09-10',2,NULL,NULL),(12279,'非常小特务3','Spy Kids 3-D: Game Over','科学狂人和荒岛惊魂后，这回天才特工小姐弟必须面对的，是解救全世界孩子的任务和一个庞大危险疯狂的虚拟游戏。在莫名其妙的失去了他的特工工作以后，“少年版007”朱尼·柯蒂斯 被告知他必须设法进入一个虚拟游戏的世界，他的姐姐卡门·柯蒂斯 的精神被禁锢在那里。游戏的设计者是一个被成为“玩具制造商” 的狂人，他有五个全然不同的分裂人格，出于邪恶的目的，他希望能够通过这个游戏控制全世界的孩子。为了打败他，朱尼加入了一个由全世界招募而来的孩子们组成的游戏测试小组中，进入虚拟世界接受层出不穷的挑战。朱尼面临着一系列考验：比如在炽热的火山岩浆上冲浪，和巨大的机器人与异种怪兽交战，又或者危险重重的夺命狂奔。即使有曾经也是天才特工的祖父帮忙，朱尼能够成功的通过这些关卡，拯救姐姐卡门并最终打败邪恶的玩具制造商吗？','3rd Mission. 3rd Dimension.',38000000,197011982,21.998734,4.7,511,84,'2003-07-25','en','/jsQ9h0vPTj8z4od1jVzTm8CYeeZ.jpg',3.063947187769462,3,'2026-09-10',2,NULL,NULL),(12281,'湖群狗党','Mean Creek','一群年青人为了向恶霸报复，以为年纪最小的同伴庆祝生日为由，筹备了一次划艇之旅，邀请恶霸同行。旅程中，一些队员开始衍生出邪恶的念头，游戏开始变成一项阴谋…','Beneath the surface, everyone has a secret.',500000,603943,8.519202,6.9,106,90,'2004-01-15','en','/nlU3SJzt5focTIkhLcO0ggnvbpW.jpg',2.897941185261822,3,'2026-09-10',2,NULL,NULL),(12289,'赤壁（上）','赤壁','影片以长坂坡之战开场，曹操在击溃刘备后，认为对他称霸天下有威胁的是东吴，再加上曹操钟爱的小乔誓死不从，令他大发雷霆，执意攻打东吴。孙权派鲁肃以吊唁刘表之名与刘备会面，商讨联合抗曹的事情。刘备在同意了与东吴联合抗曹的建议之后，派诸葛亮前往东吴。孙权的妹妹孙尚香与鲁肃用激将法坚定了孙权抗曹的决心，并且把周瑜召回，主持抗曹。两军最终在赤壁相遇，小乔夜探曹营，与曹操论茶道拖延时间，最终联军战胜曹军，小乔与其子平安均安然无恙。','The future will be decided.',80341000,127814609,14.8375,7.1,205,150,'2008-07-10','zh',NULL,3.089663084333637,3,'2026-09-10',2,NULL,NULL),(12312,'大人物乔','Joe Somebody','男主人公乔·赛佛（蒂姆·艾伦 Tim Allen饰）是个中规中矩的中年男人，他像所有失败的小人物一样，做梦都想成为一名“大人物”。他一直工作在明尼苏达州的一家制药公司，感叹怀才不遇，得不到应得的赏识。乔的老板本来许诺给他晋升的机会，最后却食言了。而且他的个人生活更是一团糟，他跟妻子凯丽（凯莉·林奇 Kelly Lynch饰）最后还是以离婚收场。本来这不好不坏的工作和浑浑噩噩的生活，如一汪死水般平静。直到他的同事马克（帕特里克·沃伯顿 Patrick Warburton饰）霸占了他心爱的私人泊车位，还在他早熟的女儿面前羞辱乔时，他的怒火终于被点燃了。忍无可忍的乔，决心改头换面，跟马克“决一死战”。\r 　　乔是否能像所有人证明：他现在是个“大人物”？而这样的改变，到底好坏与否呢？','Someone just picked on the wrong nobody.',38000000,0,5.257009,5.5,40,99,'2001-12-21','en','/cGIwt21uog08UjfZsRaTI7f7iy6.jpg',2.64261571850975,3,'2026-09-10',2,NULL,NULL),(12400,'红带高手','Redbelt','洛杉矶的西面，是一个龙蛇混杂的是非之地，因为一众“练家子”居于此地，自然而然地形成了一个由格斗家组成的动感世界。在这些类似于保镖、拳击手、警察和特种兵的形形色色的人当中，真正的主角却是一个看起来不怎么起眼的教授防身术的老师迈克·泰瑞……其实迈克是一个顶级的柔道高手，只是这位颇有看破红尘意思的“世外高人”，一点也不喜欢在赛场上发挥自己的“余热”，生平最大的愿望就是平凡度日，并小心翼翼地不越雷池一步。对于他来说，真正有荣誉感的生活，并不存在于格斗场上，所以他才会开办这个教授防身术的武馆，过着悠闲自得、修身养性的日子。','There\'s always a way out. You just have to find it.',7000000,0,5.091253,6.4,76,99,'2008-04-07','en','/tjLKe0QCGgSrvEd41Z4q2QpSoJF.jpg',2.7968027351269367,3,'2026-09-10',2,NULL,NULL),(12403,'完美逃亡','A Perfect Getaway','两对新婚夫妇克里夫和西德尼、尼克和吉娜分别来到夏威夷群岛度假，初到夏威夷的时候，他们拥有一段美好的时光，海水、沙滩、阳光和帅哥美女都让他们流连忘返。　　克里夫和西德尼是对极富有冒险精神的夫妻，他们在群岛上独自寻找人迹罕至的沙滩。功夫不负有心人，他们在一片背阴的地方发现了一片几乎没有被开发的海滩，于是这里便成了他们蜜月的首选之地－－他们相信自己发现了天堂。可是这种天堂般的宁静很快就被打破：一群惊慌失措的游客在岛上到处乱跑，无意中闯到了克里夫夫妇的面前，从他们的口中，克里夫了解到岛上出现了一个令人恐惧的精神病人，他正在一个接着一个地干掉岛上的游客。得知此事后，克里夫夫妇犯了难－－究竟是留下还是打点行包回到城市？　　此时，另一对夫妇尼克和吉娜也在为自己究竟是回到城市结束蜜月，还是继续留在夏威夷享受阳光而伤透脑筋。就在这两对夫妻犹豫不决的时候，这个杀手又开始行动了，事情越变越糟。人间天堂变成了人间地狱。在这个远离城市、远离文明、远离工业的小岛上，他们该相信谁？他们又能活着出来么？　　眼见着天堂般的美丽小岛竟变成了噬人性命的恐怖地狱。','Welcome to paradise. Enter at your own risk.',14000000,22852638,20.792603,6.2,351,98,'2009-06-08','en','/ncuGG0hIlA03dQBJmdoT2LWgodG.jpg',3.163073335155439,3,'2026-09-10',2,NULL,NULL),(12404,'我和奥逊·威尔斯','Me and Orson Welles','在1937年的纽约，17岁的理查德·萨缪尔一心想当演员，十分厌烦学校的生活。一个巧合的机会，他遇到了舞台导演奥逊·威尔斯，并加入了威尔斯导演的莎士比亚舞台剧《尤利乌斯·恺撒》的排演。在剧组，他遇到了也对舞台充满渴望的桑妮亚。理查德爱上了桑妮亚，但当向她表白时，桑妮亚却表示她愿意跟威尔斯在一起。他终于察觉桑妮亚为了实现她的舞台梦想而愿意与威尔斯进行性交易。理查德与威尔斯大吵了一架，并被驱逐出剧团。 突然有一天，威尔斯向他道歉，并邀请他重新加入剧团。在《尤利乌斯·恺撒》首演成功之夜，理查德明白了威尔斯的道歉只是为了保证首演的顺利进行，一个新的演员已经找到，并随时准备替换他。理查德再次离开剧团，他告之父母是由于薪水太少。理查德重新回到学校，并打算以后当一名编剧而不是演员。','If you want to discover life learn from the master',25000000,2336172,3.593165,6.6,49,114,'2009-11-25','en','/ujYD1SwLYeQJ8M4pTgIhCqrJchS.jpg',2.7006907094688892,3,'2026-09-10',2,NULL,NULL),(12405,'贫民窟的百万富翁','Slumdog Millionaire','Jamal Malik is an impoverished Indian teen who becomes a contestant on the Hindi version of ‘Who Wants to Be a Millionaire?’ but, after he wins, he is suspected of cheating.','What does it take to find a lost love? A. Money, B. Luck, C. Smarts, D. Destiny',15000000,377910544,59.258969,7.6,2827,120,'2008-05-12','en','/5leCCi7ZF0CawAfM5Qo2ECKPprc.jpg',4.049678561943579,3,'2026-09-10',2,NULL,NULL),(12410,'好人','Good','上个世纪的30年代，一位德国文学教授约翰·赫德 (英文John Halder ；Viggo Mortensen 饰)身边有年迈且病重的母亲、妻子、情人和犹太好友，由于撰写主张安乐死的小说，他受到了纳粹的注意。从开始的不情愿，到后来的纳粹军官，赫德在感性和理性的天平上一直小心翼翼得平衡着。这就是为什么你很难做到去恨这样一个人物的原因，一个极其脆弱和敏感又极其爱慕虚名、自负的结合体，一个被卷入纳粹运动洪流的人。本片有别于一般的纳粹电影，并非《朗读者》一样将观众牵入大是大非当中，更没有一个盖棺定论的“结局”。对于安乐死的主题和二战的特殊历史背景下，赫德教授的故事，还需要观众的一双慧眼自己去甄别其主旨。\r 本片改编自英国剧作家C. P. Taylor的同名戏剧。','Anything that makes people happy can\'t be bad can it?',0,0,2.397987,6.3,29,96,'2008-12-11','en','/AgNssumEnPaT6kzzJyj4oLypOOG.jpg',2.5799729102161915,3,'2026-09-10',2,NULL,NULL),(12412,'圣安娜奇迹','Miracle at St. Anna','1983年，纽约曼哈顿。退伍士兵赫克特·耐隆（拉兹·阿隆索 Laz Alonso饰）在一家邮局工作。某日他突然掏枪击杀了一名陌生的顾客，随后警方在他家中发现了一尊桃花女神的雕塑头像。1944年寒冬，意大利托斯卡纳地区。四名来自美国第92师的黑人士兵，奥布里·斯坦普斯(德瑞克·卢克 Derek Luke饰)、坡仕普·康明斯(迈克尔·伊雷 Michael Ealy饰)、山姆·崔恩（奥玛·本森·米勒 Omar Benson Miller饰）和赫克特，为了营救一个意大利男孩安吉洛，不幸与大部队失散，被包围在当地一个名为圣安娜的村子里。在这个语言不通的意大利村庄里，当地村民起初对他们防备敌视。可随着战斗进程，他们逐渐受到了村民的欢迎和尊敬。他们跨越种族、阶级和国别，用勇敢和信仰创造了一个被世人所赞颂的伟大奇迹。  本片由小说改编而成，是发生在二战时意大利托斯卡尼地区的真实事件。',NULL,45000000,9323833,11.387408,6.3,90,160,'2008-09-15','en','/7PqmgaQBuD0Zp9pDIkkEjkhCJUj.jpg',2.8454962217403286,3,'2026-09-10',2,NULL,NULL),(12429,'崖上的波妞','崖の上のポニョ','5岁的宗介和妈妈理莎住在海边小城的悬崖上。一天，他在岸边发现了一条被困在玻璃瓶里的小金鱼，并将她救了出来，给她取名“波妞”。来自海底世界的波妞很快喜欢上了宗介，宗介也答应会一直保护她。然而波妞的父亲藤本并不愿女儿留在人类世界，强行将她带回海底。无法忘记宗介的波妞却下定决心，要再次回到他的身边，甚至希望真正变成人类。为了兑现这份小小却坚定的心愿，波妞再次奔向陆地，也让原本平静的海边小城迎来一场意想不到的奇幻冒险……','Welcome To A World Where Anything Is Possible.',41677699,187479518,39.58676,7.5,926,100,'2008-07-19','ja','/tt6nw8QrwUZdIEyJuJrWCFliGTf.jpg',3.6407070548048375,3,'2026-09-10',2,NULL,NULL),(12437,'黑夜传说3：狼族崛起','Underworld: Rise of the Lycans','遥远的黑暗世纪，柯文诺斯的子孙一分为二。血族在维多的领导下独行天下，强大的吸血兵团压制极具传染性且无法进化成人的残暴狼族。直到某天，一个神奇的生命诞生，改变了这两个家族的命运。一只母狼诞下有着人类外表的狼人路西安，维多窥见狼人身体内的强大实力，于是对其大量繁殖，并将狼人纳为服务血族的奴隶。奴隶的苦难永无终结，而在这一过程中路西安还冒天下之大不韪与维多的女儿桑雅偷偷相恋。渴望自由的路西安最终设法解开维多对自己的禁锢，狼人与血族持续数百年的战争亦由此拉开序幕……','Every war has a beginning.',35000000,91353501,51.927471,6.2,1428,92,'2009-01-22','en','/uElDg82IDkO4iwGDQS8D1GOv2xF.jpg',3.5472725098709184,3,'2026-09-10',2,NULL,NULL),(12454,'一无所有','All or Nothing','在漫长而又乏味的婚姻生活中，佩妮（莱丝利·曼维尔 Lesley Manville 饰）感到自己的人生走入了谷底，收银员的工作让她日复一日重复着同样的动作，身为出租车司机的丈夫菲尔（蒂莫西·斯波 Timothy Spall 饰）则早就已经对妻子的喜怒哀乐无动于衷。女儿瑞秋（Alison Garland 饰）是个替老人打扫卫生的保姆，儿子罗伊（詹姆斯·柯登 James Corden 饰）失业闲赋在家，未来中佩妮觉得自己看不到任何的希望。\r 罗伊的突然病倒使整个家庭陷入了恐慌，本以为对家庭已经毫无感情的佩妮这才发现儿子的存在对自己来说是多么的重要。在对罗伊的照顾和看护之中，佩妮和菲尔逐渐的找回了昔日的激情，家庭的裂缝开始缓慢愈合。',NULL,9000000,0,2.872281,7,33,128,'2002-05-17','en','/5VRYeJ8DI3GkVzO7MUlug8v2BZO.jpg',2.617620433036711,3,'2026-09-10',2,NULL,NULL),(12479,'Breakfast of Champions','Breakfast of Champions','A portrait of a fictional town in the mid west that is home to a group of idiosyncratic and slightly neurotic characters. Dwayne Hoover is a wealthy car dealer-ship owner that\'s on the brink of suicide and is losing touch with reality.',NULL,12000000,0,2.695896,5.2,28,110,'1999-02-13','en','/5uNVeZNt7qxDWLJAZ0PER03WtKE.jpg',2.5610050221805136,3,'2026-09-10',2,NULL,NULL),(12484,'妖夜凶灵','The Forsaken','肖恩一路从洛杉矶开着一辆奔驰老爷车，前往佛罗里达去参加他姐姐的婚礼。他压根就没想到会碰上一位搭车者。从那时起，他的这次跨州旅行便成了一场闻末所闻、充满血腥味的恶梦……','The night... has an appetite.',5000000,0,2.739307,4.9,47,90,'2001-04-27','en','/4RN5EKSHawgUMoPzjzyyXCXckYk.jpg',2.658610723402728,3,'2026-09-10',2,NULL,NULL),(12486,'Farce of the Penguins','Farce of the Penguins','In this spoof of \"March of the Penguins,\" nature footage of penguins near the South Pole gets a soundtrack of human voices. Carl and Jimmy, best friends, walk 70 miles to the mating grounds where the female penguins wait. The huddled masses of females - especially Melissa and Vicki - talk about males, mating, and what might happen this year. Carl, Jimmy, and the other males make the long trek talking about food, fornication and flatulence. Until this year, Carl\'s sex life has been dismal, but he falls hard for Melissa. She seems to like him. A crisis develops when Jimmy comes upon something soft in the dark. Can friends forgive? Does parenthood await Carl and Melissa?','What Happens In Antarctica... Stays in Antarctica',0,0,1.963219,3.2,13,80,'2006-12-01','en','/bb3f1catVid2yDqHvhygai2RUoM.jpg',2.396010164456849,3,'2026-09-10',2,NULL,NULL),(12498,'弹簧刀','Sling Blade','一部南方哥特式故事，讲述名为卡尔（比利·鲍伯·松顿 饰）的男子在犯下骇人罪行的约二十五年后，从精神病院获释回到他少年时代的南方小镇。他沉静温和的举止与质朴的魅力为他赢得了一份工作，并使他意外地与一名男孩（卢卡斯·布莱克 饰）及其寡母建立起友谊。然而，当男孩母亲的施虐男友出现时，这个单纯的男人被卷入一场激烈的两难困境，给所有人带来深刻而动人的影响。[米拉麦克斯影业]','A simple man. A difficult choice.',1000000,24475416,14.805264,7.4,231,135,'1996-08-30','en','/rioWUWXPFNSjwm9NO2aau9x0wlP.jpg',3.143333303256585,3,'2026-09-10',2,NULL,NULL),(12506,'哭喊自由','Cry Freedom','丹泽尔·华盛顿（Denzel Washington）在片中饰演一位机智、温和、善良、勇敢的南非黑人民权解放运动领袖——斯蒂芬·毕柯（Steven Biko）,于1977年在狱中遭保安警察杀害,凯文·克莱（Kevin Kline）演他的白人记者朋友唐纳德·伍兹（Donald Woods）,他冒着生命危险,带着全家人设法逃离祖国南非,好将毕柯这位自由斗士的事迹昭告世人。丹泽尔·华盛顿因本片获当年奥斯卡最佳男配角奖提名。',NULL,0,0,3.735723,6.9,51,157,'1987-11-05','en','/zEONV1NAzzoQGFFgSIEs7vJzDrN.jpg',2.7157734689835027,3,'2026-09-10',2,NULL,NULL),(12508,'摇滚巨星','Rock Star','一位前往宾夕法尼亚州的致敬乐队的摇滚迷，当他的乐队把他踢出创立的团队时，他感到沮丧。当被邀请加入长期以来一直在模仿的重金属摇滚乐队Steel Dragon时，Izzy的情况开始好转。这部电影基于Judas Priest乐队的真实故事，但有所改编。','The story of a wanna be who got to be.',57000000,16991902,11.60815,6,190,105,'2001-09-04','en','/8pRMweo9WA1MvYOLsD2hWyFpZ1V.jpg',2.9938256473229004,3,'2026-09-10',2,NULL,NULL),(12509,'波洛克','Pollock','波洛克作为当时西方艺术的领袖人物，以其超乎寻常的天才和胆量创作了大量的抽象派油画作品，并为行为艺术的创立打下了基础。他当之无愧地成为美国人民心目中的艺术明星，但波拉克并不以一位成功者自居，反传统创作的精神激发了他原始的、充满野性的灵感，将灵感运用于油画作品，使他的内心世界得以表达，但自我封闭的个性又与其形成强烈的矛盾，加上对社会、对文化的不满，将他一次次推向痛苦的深渊。于是，他酗酒、颓废，却从不停止创作。充满怨愤的生活逐渐吞噬他的婚姻、事业、信仰……','A true portrait of life and art.',0,0,8.483531,6.6,91,122,'2000-09-06','en','/azsBSw2zw2uNHiCjTnbe9TJVEDB.jpg',2.851292221987593,3,'2026-09-10',2,NULL,NULL),(12535,'恐高症','High Anxiety','一名有恐高症的精神病专家到疯人院出任新院长一职，但院中的旧人却意图谋害他……','The Master of Comedy takes on The Master of Suspense!',3400000,31063038,5.690619,6.5,84,94,'1977-12-25','en','/qVuSJaGnomSPon8x3mIYywFGgD8.jpg',2.82350648484393,3,'2026-09-10',2,NULL,NULL),(12555,'I Served the King of England','Obsluhoval jsem anglického krále','Jan Dítě has been released from a Czech prison just before the very end of his 15-year sentence. Settling in a town near the border, he occupies his time with rebuilding a deserted house, and recalling his past. His main wish in life was to be a millionaire. Jan begins his career as a frankfurter vendor, and slowly learns the power of money and the influence it exerts over people.',NULL,0,0,2.387463,7,22,120,'2006-12-19','cs','/nMeXol5g4wKb3GwLKNERwBSzE6i.jpg',2.5279043101184278,3,'2026-09-10',2,NULL,NULL),(12569,'压榨','Extract','美丽女孩辛迪（米拉•库尼丝 Mila Kunis 饰）是个行骗高手，她在乐器行跟两个店员打情骂俏，趁对方心猿意马之际，盗走了昂贵的吉他。事后，她又在杂货店靠眼泪博得了伙计的同情，将赃物出手，狠赚了一笔。后来，她在报纸上读到某个香料精生产商的员工意外受伤，可能获得高额赔偿，便自告奋勇，前来应征。乔伊（杰森•巴特曼Jason Bateman 饰）就是这家香草精厂家的主管，他手下的人力主管布莱恩将美女招致麾下，但乔伊关心的只是如何让产品打开销路，以及让性趣索然的妻子苏茜（克里斯汀•韦格 Kristen Wiig 饰）重燃激情。这时，律师好友迪恩（本•阿弗莱克Ben Affleck 饰）便出谋划策，让他请一个男妓，考验一下妻子的忠贞度，没想到这一试，却导致了令人啼笑皆非的结果……','Sticking it to the man has never looked so good.',8000000,10848783,14.652342,5.7,192,92,'2009-09-03','en','/cjen0vxjybwItQPH3NNCJuME2MY.jpg',2.9842091056376647,3,'2026-09-10',2,NULL,NULL),(12573,'严肃的男人','A Serious Man','本片讲述了一个普通人在杰斐逊飞机乐队充斥电台、《F特遣队》占领电视的时代里寻求答案的故事。时值1967年，在中西部一所宁静大学任物理教授的拉里·戈普尼克，刚被妻子朱迪丝告知她决定离开。她爱上了拉里那位更为自负的熟人西·埃布尔曼——在她眼中，这位显得比懦弱的拉里更有分量。拉里无业可就的弟弟亚瑟终日睡在沙发上，儿子丹尼在犹太学校纪律涣散、逃避学习，女儿莎拉则从他钱包里偷钱攒鼻整形手术费。在挣扎求取平衡之际，拉里先后向三位拉比寻求指引。究竟谁能助他抵御苦难，成为一个正直的人——一个“正派人”——一个严肃的男人？','...seriously!',7000000,31430334,23.612409,6.6,483,105,'2009-10-02','en','/mEKishzTPgRCUL2IhC9UoHQFyoS.jpg',3.2884377447151545,3,'2026-09-10',2,NULL,NULL),(12586,'贝拉','Bella','杰斯（埃杜瓦多·维拉斯蒂吉 Eduardo Verástegui 饰）曾是一名英俊倜傥的足球运动员，事业和生活都处于上升期的他无疑有着充满了光明的未来，可是，如今的杰斯却沦为了默默无闻的无名小卒，在哥哥曼尼（曼尼·佩雷兹 Manny Perez 饰）经营的餐厅里掌勺，究竟发生了怎样的意外彻底改变了杰斯呢？','One person can change your life forever',0,0,1.814802,6.7,37,91,'2006-09-09','en','/gGr5z37fRaESbn8evVa4i12691e.jpg',2.636337699794325,3,'2026-09-10',2,NULL,NULL),(12589,'天才小子吉米','Jimmy Neutron: Boy Genius','小男孩吉米人小鬼大，具有超强智慧，而且还是个小发明家，他的机械狗高德是他最好的伙伴，同时也是最好的拍档。一次偶然的机会，他们意外涉及外层空间的冒险任务，执行一次不同寻常的营救工作，他们既要对抗邪恶异形、又要拯救地球..','He may be small, but he\'s got a big brain!',25000000,80936232,12.739721,5.6,231,83,'2001-12-21','en','/pUwdquA6Bf3Gq8yT5iQL1Yq0jkl.jpg',3.0086005514659577,3,'2026-09-10',2,NULL,NULL),(12596,'空中塞车','Pushing Tin','尼克（约翰·库萨克 John Cusack 饰）是一名空中雷达管制员，他的工作就是指挥和监控机场内的数千架飞机起飞降落。对于这份责任重大的工作，尼克热爱并且十分擅长，他细心谨慎的工作作风让他在公司内饱受好评。  　　一个名叫罗素（比利·鲍伯·松顿 Billy Bob Thornton 饰）的男人的出现终结了尼克平静的生活，他不仅在工作成绩上超越了罗素，甚至就连身形和相貌都要更胜罗素一筹。糟糕的不仅仅于此，当尼克和罗素的老婆玛丽（安吉丽娜·朱莉 Angelina Jolie 饰）的暧昧关系被罗素知晓后，后者以及其冷静和稳重的态度狠狠给了尼克一个下马威。面对如此强劲的敌人，尼克会做出怎样的举动呢？','A comedy about losing control',33000000,0,9.060642,5.7,116,124,'1999-04-23','en','/61FWajJNKeS27DO4KgvS5LUgcHh.jpg',2.8715675314110096,3,'2026-09-10',2,NULL,NULL),(12602,'蛇坑与钟摆','Die Schlangengrube und das Pendel','雷古拉伯爵因在地牢刑讯室杀害十二名处女而被分尸。三十五年后，他回来向第十三个受害者的女儿和检察官的儿子复仇，以获得永生。','UNBELIEVABLE! Until You See It With Your Own Eyes!',0,0,1.296784,6.3,12,85,'1967-10-05','de','/n0s1zXtfRFx2FSn2W6PfQcB9QZK.jpg',2.3946272784186795,3,'2026-09-10',2,NULL,NULL),(12610,'终极细胞战','Osmosis Jones','弗兰克是个规规矩矩的动物园管理人，但并不是一个健康的家伙。他自己知道这一点，他年轻的女儿沙恩和女儿的老师博伊德夫人也知道这一点。某天，贪嘴的他误吃掉一只被猴子口水污染过的苹果，镜头跟着苹果来到他的咽喉，肠胃……于是在弗兰克的体内，更准确地说，在他的血液里，发现了一个叫作奥兹的白血球。和所有的白血球一样，奥兹的工作就是每天在血液里不停地巡视，对付那些敢于滋扰人体的细菌啦，病毒啦什么的，别看肩负这么艰巨的任务，但奥兹可不是个循规蹈矩的人，不，应该说不是个循规蹈矩的白血球，他天性浪荡散漫，最抗拒那些条条框框的规定纪律，就喜欢证明自己是个与众不同的“个性”细胞。弗兰克-德托里的身体越变越糟，就连他的好朋友鲍勃也察觉到了他的异样。很多人看到弗兰克，都觉得他再也不是以前那个强壮的贴海报的人了。也许是为了约束他，奥兹的上司派给他一个新搭档——专门照本宣科的新型感冒药片德雷克斯，两个性情习惯截然不同的家伙硬凑到一起当然少不了吵架拌嘴，就在他们互不相让的时候，弗兰克吃下的那个 苹果带来了一种危险的病毒斯瑞克司，这个威力强大的病毒在弗兰克体内肆意横行，不可一世。不幸的是，他和他的搭档德雷克斯——一种12小时作用的止痛感冒胶囊只能为富兰克止痛一小会儿。为了尽到自己身为一个白血球的的神圣责任，为了挽救富兰克的生命，奥兹和德雷克斯决定先放下对彼此的成见，携手并肩共抗外敌。他们两个人同生物钟比赛争分夺秒：避开粘液泥浆、清理毒素以及所有你想象不到的各种工作。这是份很脏的工作，但是这些抗体必须去做。因为每个身体都需要英雄。与此同时，弗兰克因为身体不适去看医生，他的医生也正竭力想找出到底是什么导致了弗兰克的病症。','Every BODY needs a hero',75000000,13596911,10.54544,5.9,228,95,'2001-08-07','en','/foZpSG88IQUCEBJE3unc5QzO6bQ.jpg',3.0225831330233843,3,'2026-09-10',2,NULL,NULL),(12612,'Freeze Frame','Freeze Frame','Sean Veil is an ultra paranoid murder suspect who takes to filming himself round the clock to provide an alibi, just in case he\'s ever accused of another crime. Problems arise however when the police do come calling and the one tape that can prove his innocence has mysteriously disappeared.',NULL,0,0,4.922397,6.9,18,99,'2004-05-01','en','/A7SNMoBXWt0GAdktkVY1SB3y3vQ.jpg',2.4900992436284066,3,'2026-09-10',2,NULL,NULL),(12618,'驿动的心','Random Hearts','“荷兰人”范登布罗克（哈里森.福特饰）是华盛顿特区的一名警官，他的妻子与女国会议员凯.钱德勒（斯科特.托马斯饰）的丈夫有了私情，“荷兰人”和凯却毫无察觉，直到两人乘飞机去渡情人周末，死于空难，他们才知道事情的真相。生性耿直，清心寡欲，颇有敬业精神的“荷兰人”这时开始疯狂地寻找妻子不忠的线索，妻子为什么要背叛自己？他想从凯那儿去探求答案......由此引发了和凯关于他们各自感情、婚姻经历的交流。在抑郁的情绪中他们的关系也在萌发，以至于他们有了一个报复性的激情之夜。','In a perfect world...they never would have met.',64000000,74608570,4.137237,5.3,63,133,'1999-10-08','en','/k7LoKDWDesvYD7DXDh9Ewlxtcx8.jpg',2.7269168980985783,3,'2026-09-10',2,NULL,NULL),(12620,'校园兔女郎','The House Bunny','性感美丽的雪莉·达灵顿（安娜·法瑞丝 Anna Faris 饰）曾是一名隶属于《花花公子》旗下的兔女郎，在27岁之前，她过着奢华无忧的快乐生活。然而就在27岁生日的第二天，她却被老板扫地出门。无所依靠且别无所长，雪梨漫无目的四处游走，偶然加入了由莫娜（凯特·戴琳斯 Kat Dennings 饰）、娜塔丽（艾玛·斯通 Emma Stone 饰）等女孩组成的女子联谊会Zeta Alpha Zeta，这些女孩穿着老土、性格怪异，在学校内其他团体的眼里如同怪胎。雪梨的到来有如一支催化剂，她利用自己丰富的经验帮助女孩们改变造型，打造吸引男性眼球的外形和气质，原本无人问津的女孩开始受到追捧，而雪梨也收获了属于自己的爱情……','For the girls of ZETA house college life was no party, until Shelley showed up.',25000000,70442940,25.838073,5.6,529,97,'2008-08-22','en','/fmcEpBBtlNEFTCChXKDNW5UHab6.jpg',3.190243431205492,3,'2026-09-10',2,NULL,NULL),(12621,'续写哈姆雷特','Hamlet 2','丹拿（史蒂夫·库根 Steve Coogan 饰）是一位郁郁不得志的小演员，在演艺事业彻底泡汤后，心灰意冷的他来到了一所高中，成为了那里的戏剧课老师。对于自己的课程，丹拿从来都不放在心上，即使他的课程恶评连连，即使空空的教室里只坐了一个学生，丹拿都觉得无所谓，他只在乎自己那份微薄，但却是唯一的薪水。','One high school drama teacher is about to make a huge number 2.',0,0,5.293363,6.1,56,92,'2008-01-21','en','/ljdmxGNwhuWZBsCgANlZrruFkJj.jpg',2.723540873741084,3,'2026-09-10',2,NULL,NULL),(12634,'大反弹','The Big Bounce','根据传奇犯罪作家艾尔墨·莱昂纳多的小说改编。去年，丹泽尔·华盛顿的《视线之外》也是根据他的同名小说改编而成的。\r 　　杰克·瑞恩（欧文·威尔逊）是个居无定所、逃避法律的天才。他只身来到夏威夷，希望这里如画的风景能给自己带来一些好运。在充满热带风情的地方，杰克很快发现自己想要的是一段罗曼史。\r 　　房地产商雷·瑞奇（盖瑞·希尼斯）不顾当地居民的抗议强行建房。杰克在他那里找到份工作。但是，刚一开工，就跟工头哈里斯起了纠纷。瑞奇的左右手小鲍伯（查理斯·肖恩）警告杰克最好离开这个岛，但杰克对此置若罔闻。\r 　　杰克的出色搏击技术给法官沃尔特（摩根·弗里曼）留下深刻印象。他为杰克提供了一份充满危险的工作。漂亮姑娘南希·贺耶斯（萨拉·福斯特）可不像外她表看起来那么简单，她引诱杰克为自己工作，企图从雷那里偷走一笔巨款。杰克很感兴趣，但是一直在犹豫。对他而言，这可能是笔不错的买卖……','It\'s all in who you trust',50000000,6808550,6.397388,5,76,88,'2004-01-30','en','/l6tzLXXGubnC6TbFgg8acfcvGRO.jpg',2.7601059525943406,3,'2026-09-10',2,NULL,NULL),(12637,'纽约，纽约','New York, New York','本片以过三十年代的大乐队时代为故事背景，描述一名萨克斯爵士乐手与一名女歌手之间爱恨交缠的情感，充满着人生的困惑和无奈，跟一般好莱坞歌舞片的明亮轻快大异其趣。',NULL,0,0,3.876242,6.1,67,155,'1977-06-21','en','/1nD40aUcPAxYdE1WxERrTjZuFGe.jpg',2.7585723465881014,3,'2026-09-10',2,NULL,NULL),(12657,'灵魂梦飞翔','Soul Plane','继一个可怕的可怕的飞行，导致他的宠物的死亡，Nashawn Wade提起诉讼对航空公司，并赢得一个数百万美元的解决。 决定创造一个更好的飞行体验，Nashawn开始自己的航空公司，迎合一个非洲裔美国客户。 与平稳的Capt。Mack驾驶的飞机飞行，这家航空公司遇到了一个阻碍，当它必须处理Elvis Hunkee的家庭。','Announcing the arrival of the first airline with soul.',16000000,14822346,9.400404,4.7,108,86,'2004-05-28','en','/b5Rzb5JUwPinllWGYUYER3OV14F.jpg',2.819249169692686,3,'2026-09-10',2,NULL,NULL),(12658,'似曾相识','Someone Like You...','简（艾什莉·贾德 Ashley Judd 饰）是一个成功的脱口秀栏目制片人，在事业蒸蒸日上的同时，甜蜜的爱情也不期而至。刚刚上任，制片主任雷（格雷戈·金尼尔 Greg Kinnear 饰）就对简发起了猛烈的甜蜜攻势。而正当两人打得火热准备同居的时候，雷的态度突然发生了奇怪的转变，在日益冷淡的感情面前，简选择了离开。在痛苦中，简开始思考起雷奇怪的转变，她发现，在对待感情这码子事上，男人和动物有着异曲同工之处，她决心进行深入的研究。由于推掉了房子，简和同事简好友埃迪（休·杰克曼 Hugh Jackman 饰）住到了一起，同时，埃迪也成为了简的研究对象。简凭借着自己的研究成果开辟了一个匿名专栏，引起了强烈的社会反响，而她和埃迪之间的关系也渐渐变得奇妙起来。','The story about the one that got away and the one she never saw coming.',23000000,0,7.901891,6,118,97,'2001-03-30','en','/3ARyIRgTgx7XubNTzqUDmeJi0SK.jpg',2.8848957719596404,3,'2026-09-10',2,NULL,NULL),(12690,'阿帕鲁萨镇','Appaloosa','这是一部根据Robert B. Parker的同名原著改编的西部片，由艾德·哈里斯自导自演。电影讲述了维吉尔（艾德·哈里斯）和埃弗雷特（维果·莫特森）在一个偏远的小镇当警察，他们发现在这个小镇法律不起作用。农场主兰德尔（杰里米·艾恩斯）是当地势力最大的人，控制着镇上的物资、马匹和女人，维吉尔和埃弗雷特打算行使自己的职责，向兰德尔交涉。但一个颇具魅力的寡妇（芮妮·齐薇格）的到来打乱了他们的计划。','Feelings get you killed.',20000000,20211394,16.074397,6.3,299,115,'2008-09-12','en','/kQB0uxR3RDS2tGTZtBuFow9SF1T.jpg',3.1254203962482974,3,'2026-09-10',2,NULL,NULL),(12703,'棕兔','The Brown Bunny','职业摩托赛车手巴德·克雷（文森特·加洛 Vincent Gallo 饰）独自驾车从新罕布什尔州出发，他将要参加五天后在加州举行的比赛。孤独的旅程让人心绪万千，关于那旧日爱人的回忆慢慢浮现脑中。黛西（Chloë Sevigny 饰），一个让他魂牵梦绕且愁绪满怀的名字，这个美丽如同妖精的女孩曾让巴德感受到爱的温暖，而如今她身在何方？巴德一路前行，邂逅了一个又一个充满个性、美丽温柔的女孩，她们短暂慰藉着他的心灵，却最终都被抛在身后。无论怎样，她们无法取代黛西的地位，一如那旧日回忆久久萦绕盘桓……','I\'m not going to be okay, Bud.',10000000,0,3.412162,5.5,62,93,'2004-08-27','en','/bGzU4TgdqmMjIfPIgf2MjDW6H7c.jpg',2.72683113513633,3,'2026-09-10',2,NULL,NULL),(12704,'飞越迷城','Ishtar','一对时运不济的歌手兼作曲家查克和李，为了求最后一线生机，接了非洲内陆某城市的登台合约，途中，在中东伊斯达的机场，查克伸出援手帮助一位美丽的革命份子席拉，不料就此卷入一场满惊险和离奇的冒险……',NULL,55000000,14375181,2.410546,4.2,28,107,'1987-05-15','en','/2n6cDGd84I1KvCeYlTju7MBC9sN.jpg',2.549248437273732,3,'2026-09-10',2,NULL,NULL),(12763,'舞动天地','Take the Lead','杜兰尼（安东尼奥·班德拉斯 Antonio Banderas 饰）是一位小有名气的舞蹈家，但是，事业上的成功并不能弥补他的空虚感，因为在杜兰尼的内心里，将舞蹈的精髓发扬光大，让每一个人都感受到舞蹈的乐趣和自由才是他真正想要到达的终点。怀抱着这样的理想，杜兰尼开始行动了。  　　杜兰尼将据点设在了位于纽约的一间公共学校之中，虽然做好了最坏的打算，可接下来发生的事情依旧让杜兰尼感到沮丧和失落。不过世上无难事只怕有心人，随着时间的流逝，越来越多的学生们加入到了杜兰尼的舞蹈学习班里来，通过和这些年轻又富有活力的年轻人交流，杜兰尼也找到了自己新的人生意义。','Never Follow',30000000,34742066,8.999675,6.6,162,108,'2006-03-17','en','/vkGSs0eeOOISEe9jddBZnRSkn46.jpg',2.9870352439268366,3,'2026-09-10',2,NULL,NULL),(12770,'Stealing Harvard','Stealing Harvard','John and his girlfriend have vowed to marry once they save $30,000 for their dream house. But the minute they achieve their financial goal, John finds out his niece has been accepted at Harvard, and he\'s reminded of his promise to pay for her tuition (nearly $30,000). John\'s friend Duff convinces him to turn to petty crime to make the payment … but Duff\'s hare-brained schemes spin quickly out of control.','Their intentions were honorable. Their methods were criminal.',0,0,7.321181,4.4,46,85,'2002-09-13','en','/iCHAn0eVAXwybuzoQO598aKMVJD.jpg',2.6560364311911044,3,'2026-09-10',2,NULL,NULL),(12771,'拜金妙搭档','Serving Sara','乔（马修·派瑞 Matthew Perry 饰）在一间律师事务所里工作，在公司里不受领导待见，工作上又不思进取，因此，乔充其量只能算是一位文职人员。最近，老板指派给了乔一项任务，那就是将一份离婚文件送给住在纽约的名为莎拉（伊丽莎白·赫利 Elizabeth Hurley 饰）的女子。','The One Thing That Could Bring Them Together Is Revenge.',29000000,16930185,8.93941,5,85,100,'2002-08-20','en','/oJM32AMFY3oCzCsbjpmFsIOwViw.jpg',2.7865721489276294,3,'2026-09-10',2,NULL,NULL),(12779,'浩劫妙冤家','Swept Away','安贝尔是一个富有而又漂亮的女人，可惜她的脾气实在是太不可爱，他人看似美好的一切对于安贝尔来说都不足挂齿，就连他的丈夫托尼都不知道自己的妻子究竟要怎样生活才会快乐。为了讨安贝尔的欢心，托尼安排了一次邮轮上的旅行，从希腊前往意大利。尽管满心牢骚，但安贝儿好歹还是开始了她的旅程，并且在船上结识了大幅吉塞佩。安贝尔讨厌吉塞佩的粗俗和下流，逮着机会就在众人面前对他冷嘲热讽，对于安贝尔颐指气使的德行，吉塞佩也十分厌恶，只是按下不表。一次暴风雨后，船搁浅在了一座孤岛之上，在这个贫瘠又危险的地方，安贝尔和吉塞佩之间的关系发生了逆转。','A snooty socialite is stranded on a Mediterranean island with a communist sailor.',10000000,598645,4.570043,4.8,50,89,'2002-10-11','en','/siey7YlG8EUlH6lmojMvUepakm9.jpg',2.6727129915285794,3,'2026-09-10',2,NULL,NULL),(12783,'公爵夫人','The Duchess','在这部描写18世纪英国贵族生活的影片里，讲述的是一个关于爱情、憧憬、背叛、报复的故事。在成为德文郡的公爵夫人以前，乔治安娜·斯宾塞早已艳惊四座，她迷人的风度、举手投足间散发出的才情和魅力征服了当时的整个社会，成为众多男人心中的“女神”。在17岁时，她嫁给了比自己大9岁的威廉·卡文迪什公爵。然而，迷倒众生相的乔治安娜·斯宾塞却在丈夫那里遭受了前所未有的打击，丈夫对她表现冷漠，而且还与自己的闺密贝丝发生了“地下情”，这使她饱受精神上的折磨。身边两个最信赖的人的背叛，改变了乔治安娜的人生观，她变成了伦敦有名的交际花，喝酒、赌博、周旋于上流社会各色人等之间。热爱时尚的她同时又是流言中心，在其穿着成为整个伦敦的风向标的同时，其故事也成为人们摆谈的焦点，她成为当时受英国人欢迎的贵族。后来，她遇到了查理斯·格雷，并与之坠入情网，成为他宣扬辉格党政_治理念的帮手，也亦开始步入政坛。当她试图找到真正属于自己的方式并带着她所谓的忠心去履行职责之时，混乱的关系和相异的政_治立场把她推到了惨遭丈夫、家庭和整个伦敦抛弃的危险边缘，一场尔虞我诈和自我拯救的战争就此打响。','Based on the incredible true story.',0,0,18.591657,6.7,396,110,'2008-09-05','en','/9Gq2tU0pLXibKY11mh5eZAgn1ug.jpg',3.237704665115756,3,'2026-09-10',2,NULL,NULL),(12797,'鬼镇','Ghost Town','在纽约行医的伦敦牙医伯特伦•平库斯（瑞奇•吉弗斯 Richy Gervais 饰）不善与人相处，自私自利又愤世嫉俗。在一次结肠手术意外中，伯伦特假死7分钟，醒来后便具有了与鬼魂交流的能力。被众鬼魂骚扰烦不胜烦的伯伦特遇到了生前是公共关系专家的鬼魂弗兰克（格雷格•金尼尔 Greg Kinnear 饰），为求清净答应了他的请求，帮助阻止弗兰克遗孀、考古专家格温（蒂娅•莱欧妮Téa Leoni 饰）与人权律师男友理查德（比利•坎贝尔 Billy Campbell 饰）再婚。在与格温的接触中，伯伦特发现自己竟逐渐坠入爱河；而格温与理查德的婚事如愿取消，却并未达成弗兰克了结尘缘的心愿。不仅如此，众鬼魂求伯伦特协助完成最后愿望的请求愈演愈烈，这使一贯以自我为中心的伯伦特无所适从……','He sees dead people... and they annoy him.',0,0,17.98817,6.4,286,102,'2008-09-19','en','/b36N7aMplvcV5f3W0C0ZxJpl3No.jpg',3.128119325543324,3,'2026-09-10',2,NULL,NULL),(12819,'丛林有情狼','Alpha and Omega','住在加拿大绿宝石国家公园的凯特和亨弗雷是两只地位完全不同的狼，凯特是西部狼群“阿尔法”首领的女儿，对她来说原则、职责和责任重于一切；亨弗雷则完全相反，它是狼群里最低等的，成天嘻嘻哈哈，寻求当下的快乐，从来不为明天的事情发愁。凯特即将嫁给东部狼群首领的儿子加斯（Garth），并不是为了爱情，而是为了阻止两只狼群之间即将爆发的一场可怕战争。但谁都没有料到，就在婚礼即将举办的当口，凯特和亨弗雷被公园管理人员抓走送到了爱达华州的“锯齿”国家公园。急着回去阻止战争的凯特不得不和亨弗雷一同踏上回家的路，漫漫途中他们遭遇到很多惊险和意外，而且随着离家越来越近，他们俩发现已经爱上了对方……','A Pawsome 3D Adventure',20000000,39300000,12.300789,5.3,124,88,'2010-09-17','en','/d48ymGUo2a62qdFlyYdv6oNTtdY.jpg',2.874872662279695,3,'2026-09-10',2,NULL,NULL);
INSERT INTO `t_video_info` VALUES (12837,'蜜蜂的秘密生活','The Secret Life of Bees','14岁的莉莉（达科塔·范宁 Dakota Fanning 饰）和父亲生活在自家的农场里，母亲的早逝为莉莉幼小的心灵蒙上了阴影，父亲也因此变得脾气暴躁郁郁寡欢。好在有黑人姑娘罗萨琳（詹妮弗·哈德森 Jennifer Hudson 饰）的陪伴，莉莉才能够健康的成长，罗萨琳成为了莉莉唯一的港湾。  　　在那个年代，对于黑人的歧视和迫害从未停止，无奈之下，罗萨琳和莉莉只得离开了熟悉的家园，千里迢迢来到了位于卡罗莱纳州南部的小镇上。在这里不仅有莉莉关于母亲的回忆，还有性格开朗的鲍莱特三姐妹。鲍莱特三姐妹经营着一间蜜蜂养殖场，在这里，五个姑娘开始了她们充满了快乐和幸福的新生活。','Bring Your Girlfriends, Sisters, Mothers and Daughters.',11000000,38105395,7.645979,7.4,158,114,'2008-09-17','en','/m1LGEeoYfc6crbfG8WmTKg9SVqL.jpg',3.0207864501742407,3,'2026-09-10',2,NULL,NULL),(12838,'每一个夜晚','Chacun sa nuit','皮埃尔（亚瑟·杜彭 Arthur Dupont 饰）和露西（丽兹·布罗谢 Lizzie Brocheré 饰）是从小一起长大的兄妹，他们和四个同龄人一起度过了青春期，共同热爱摇滚音乐。皮埃尔是双性恋者，这在故事中为情节增添了复杂性。然而，突然有一天，皮埃尔失踪了，引起了露西和母亲的极大担忧。警察最终发现了皮埃尔的尸体，经过调查确认他是被人打死的。皮埃尔死因的谜团和他的双性恋生活是否有关呢？在调查的过程中，露西和皮埃尔的前情人开始探索真相，试图利用自己的魅力和身体来获取每个人嘴里的真相。渐渐地，她们揭示了皮埃尔被杀背后的恐怖真相。',NULL,0,0,4.665026,5.8,12,95,'2006-07-21','fr','/aYvGEuW7WObL3N1cJPe1P4wPHMS.jpg',2.399889987384442,3,'2026-09-10',2,NULL,NULL),(12877,'死人的鞋子','Dead Man\'s Shoes','哥哥在军队期间，弱智的弟弟被一帮毒品贩子欺辱，最后被逼上吊。哥哥复业归来，一场惊心动魄的仇杀之旅由此展开。。。','He\'s in all of us.',0,0,12.818441,7.2,151,90,'2004-09-29','en','/sCbXlGHmonE3QEOeM7I2PRkG8y6.jpg',3.009996254695646,3,'2026-09-10',2,NULL,NULL),(12901,'一望无际','No End in Sight','作为首部系统记录伊拉克如何陷入游击战、军阀统治、犯罪与无政府状态的纪录片，本片以震撼的内幕视角揭露了整体性的失职、鲁莽与腐败。影片基于逾200小时影像素材，通过前副国务卿理查德·阿米蒂奇、2003年春季负责巴格达事务的芭芭拉·博丁大使、前国务卿科林·鲍威尔办公室主任劳伦斯·威尔克森上校、2003年5月前负责伊拉克占领事务的杰伊·加纳将军等高级官员的坦率陈述，以及伊拉克平民、美国士兵与权威分析人士的证言，真实再现了2003年巴格达沦陷后的历史事件。影片深入剖析美国政策的重大失误——包括驻军兵力不足、放任巴格达劫掠、清除伊拉克政府专业人士、解散伊拉克军队等行为——如何催生了如今吞噬伊拉克的叛乱与混乱局面。[木兰花影业]','The American Occupation of Iraq. The Inside Story From the Ultimate Insiders.',2000000,1431623,2.283796,7.2,23,102,'2007-07-27','en','/vNLK1fRPHTHFfWfy63NJFDwX7MQ.jpg',2.5390896094839053,3,'2026-09-10',2,NULL,NULL),(12920,'梦想奔驰','Dreamer: Inspired By a True Story','高超的技艺和天赋曾为骑师本•科恩（科特•拉塞尔）赢来无数奖杯和荣耀，然而随着岁月流逝，他慢慢地被层出不穷的新人抛在身后，成了等待被“处理的垃圾”。与他命运相同的还有老马桑娅，后者曾作为一匹前途无量的种子选手为主人赢得过无数场比赛，但因运动强度过大在某次比赛中折断后腿后，它在主人眼中也就成了“废物”。后来，桑娅被主人当作遣散费送给了本•科恩。\r 本•科恩的沮丧被他的女儿凯尔（达柯塔•芬妮）尽收眼底，为了帮助爸爸和桑娅重拾自信，她制定了详细的计划，首先，她说服本•科恩同她一起精心照料桑娅，桑娅一点点恢复健康重新站立起来时，她又想方设法使本•科恩接下看似不可能完成的任务——赢得“育马者杯经典大赛”。',NULL,0,0,6.048743,6.3,67,106,'2005-09-10','en','/7Z5FuLTrP5myJ2Dl9VzDRa6q0CG.jpg',2.768588634220364,3,'2026-09-10',2,NULL,NULL),(13001,'星际之门：真理之盒','Stargate: The Ark of Truth','2008年美国经典剧集电影版。剧情紧接着第十季，本片将是Ori故事线的大结局。真理之箱（The Ark of Truth）已经透露是当年Alteran人研制的一个洗脑装置，它引起了在道德和哲学上的极大争议，赞成使用的一派Alteran人后来成为Ori，反对的一派离开家乡星系并最后到了银河系，就是古人。在这部电影里，主角们必须使用它来消灭Ori，但这个决定是艰难的，因为一旦使用，在本质上就与Ori 毫无区别。','The lines have been drawn. The battle has been waged. Only one thing can save us...',7000000,8900000,8.591387,6.9,140,97,'2008-03-11','en','/zoYwZjmHJLTttsXAcApitJ2Rmzu.jpg',2.9660970940385223,3,'2026-09-10',2,NULL,NULL),(13006,'血魔追魂','Split Second','2008年的伦敦，由于海平面上升，街道在涨潮时就被海水浸漫，到处垃圾成堆，鼠辈横行。警探斯通（鲁特格尔·哈尔 Rutger Hauer饰）因为办案疯狂及不服从上司管教而被停职，但多年前几起连环谋杀案悬而未破让斯通不得不在停职期间仍私自追查。一日，在夜总会查案的斯通又遇到另一起凶案 ，遇害女性被开膛剜胸，取走心脏，死状可怖，与前如出一辙的犯案手法令斯通确信凶手为同一个人。没多久，警局竟然收到凶手寄来的已被撕咬成半颗的受害者心脏，从心脏上的齿痕得到的牙齿模具来看凶手更是绝非人类。随着类似凶案不断发生，斯通的前女友亦遭到袭击，斯通和精通星象、神秘学的菜鸟新搭档必须争分夺秒和时间赛跑，在下一具尸体出现前逮住它，消灭它。','He\'s seen the future. Now he has to kill it.',7,5,4.857028,5.7,63,90,'1992-05-01','en','/c111nTTNsArsUqJx662hPrFymyz.jpg',2.738113367160741,3,'2026-09-10',2,NULL,NULL),(13007,'宗教的荒谬','Religulous','评论员兼喜剧演员比尔·马赫 (Bill Maher) 在与信徒谈论他们的信仰时扮演宗教的魔鬼代言人。马赫环游世界，审视基督教、犹太教和伊斯兰教的信条，并提出有关同性恋、基督存在的证据、犹太安息日法、暴力穆斯林极端分子的问题。','Heaven help us.',0,0,9.774126,7.2,197,101,'2008-10-01','en','/hBv5LCbWxPB8iU77dwurSGMVZ3N.jpg',3.0738842328197222,3,'2026-09-10',2,NULL,NULL),(13025,'死亡日记','Diary of the Dead','Jason Creed（Joshua Close）和一帮朋友正在森林中拍摄一部恐怖电影时，从广播上得知了死去又会活来的活死人的新闻，他们行动如僵尸，数目正如瘟疫般在迅速扩大。另一位导演Tony Ravello（Shawn Roberts）坚持认为这不过是媒体在制造新闻，但多数人都感觉到凉意正从背后袭来。胆小的男主角Ridley（Philip Riccio）率先逃往不远处自家的别墅后，一帮人跟着Jason的女友Debra（Michelle Morgan）开车去她的家。\r 　　上路没多久，他们便遇上恐怖事件，慢慢地，随着眼睛所见（世纪末景象之外，身边的伙伴变作活死人），包括Tony在内的所有人都完全相信了活死人正遍布这个世界的每一个角落，想办法自救成为他们认为的第一重要的事。然而Jason坚持不肯放下摄影机，他认为记录所看到的真相比保命更重要，媒体所发布的新闻都是在政府的操控下经过编辑的结果（隐瞒数目与尽可能延后发布），即便真相更为恐怖，大众也有权利知道，于是他每日把拍到的影像放到BLOG，哪怕举动不得Debra和其他伙伴的理解也在所不惜。','Where will you be when the end begins?',2000000,5364858,15.351412,5.4,190,95,'2007-09-08','en','/r9AmeGRapSNvclbjoPwFQf4GEEr.jpg',2.9651385500549665,3,'2026-09-10',2,NULL,NULL),(13027,'鹰眼','Eagle Eye','中东某地，美国军方的情报系统锁定了一名目标人物，总统不顾系统电脑运算出的建议处理方式，下令定点清除，由此引发了意外的连锁反应……公司小职员杰瑞的生活平淡乏味，时常手头拮据，连房租也成了问题，由于供职于军方的孪生兄弟意外过世，杰瑞赶回家中参加葬礼，但此行归来后，杰瑞发现家中居然堆满了武器，随即赶到的FBI破窗而入将他逮捕。与此同时，名叫蕾切尔的女人从大街上的电子广告牌上得知自己的儿子被某人绑架，绑架者拥有超乎寻常的能力，能够控制电子产品并监控一切。这名绑架者引导杰瑞摆脱FBI，最终上了蕾切尔的车，两名陌生人被迫合作，在FBI的追捕中落入了神秘绑架者的计划……究竟绑架者是谁？他又有何居心呢？','Don\'t walk. Run.',80000000,178066569,46.887983,6.3,1018,118,'2008-09-25','en','/xPvTlbzIGDoLscS4VoEq3DdlMZ3.jpg',3.4777402893934855,3,'2026-09-10',2,NULL,NULL),(13051,'马克思·佩恩','Max Payne','这个世界上最难以平复的痛苦，无疑是被迫与亲人至爱阴阳两隔的愤怒……马克思·佩恩是一个严肃至极的警察，虽然独来独往惯了的他还有点蔑视规章制度的小毛病，却仍然不啻为一个尽职尽责的优秀执法者。像警察这个行当，是最容易树敌的职业之一，马克思也不例外，每一个被他亲手抓住扔进监牢的罪犯，都对他恨这入骨，欲除之而后快。马克思了解自己职业所带来的危险，可是他也乐于接受这种刺激的挑战。然而让他想象不到的是，罪恶的魔爪竟然伸向了他的老婆和孩子，在家人被残忍地杀害后，几近疯狂的马克思开始在崩溃的边缘游走，为了给老婆孩子报仇，他什么事情都做得出来。 　　马克思所实施的一系列过于充满强迫性的调查，最终将他引导至黑暗的地下世界，这个时候，突然出现了一个对他穷追猛打的杀手，马克思从这个杀手身上感受到了和自己一样的愤怒的火花……杀手名叫莫娜·塞克斯，她误以为强暴了她的姐姐之后又将她杀死的那个人就是马克思，所以才会将他当成一生的仇敌，然而经过一番调查，莫娜却惊讶的发现，原来她和马克思所寻找的仇家，竟然是同一个人。两个为了共同的目标而暂时结成同盟的人，开始了一场有如噩梦般的旅程，随着他们越来越接近谋杀案的真相，马克思发现自己不仅需要面对一些超自然的力量，还将经历一次想象不到的背叛与抉择。','When a Man Has Lost Everything. He Only has Revenge',35000000,85416905,25.903237,5.2,613,100,'2008-10-15','en','/a2xhGUya0V4yM54HC3MUHmd3UtZ.jpg',3.1619229859020344,3,'2026-09-10',2,NULL,NULL),(13053,'闪电狗','Bolt','波特（约翰•卓佛塔配音）绝非一只普通的狗。在被女孩佩妮（麦莉•赛勒斯配音）带回家后，波特被她的父亲改造成一只“超级闪电狗”。它有强化的骨骼、风驰电掣的速度、无穷的力量。它要和佩妮一起去拯救被“绿眼人”绑架的父亲。波特靠着它的力量，战胜了无数强敌。\r 当然，这一切只是在大屏幕上。实际上，波特与佩妮只不过是一起演出一部戏剧。波特并没有什么超能力，但它坚信自己的力量是真实的。一次拍摄后，混淆了真实与戏剧的波特冲出牢笼，要去大街上拯救佩妮，而它无法预知到，它将面临一个没有超能力的真实又危险的世界','Fully Awesome. Ridonculous. Let It Begin.',150000000,309979994,41.845878,6.3,1750,98,'2008-11-21','en','/fq5HUe5bCBv0h0W2DVkLGgMzypU.jpg',3.5907044893826674,3,'2026-09-10',2,NULL,NULL),(13056,'惩罚者2：战争特区','Punisher: War Zone','前FBI探员弗兰克·卡斯特再次继续他的惩恶扬善之旅。黑帮头目比利被打败后，又邀请了一个更强大的搭档竖锯一起卷土重来。','Vengeance has a name',20500000,10089373,17.112498,5.6,294,102,'2008-12-05','en','/sxtMw1dkdZ4GpX0JnwzitA6CKLo.jpg',3.0635615594729813,3,'2026-09-10',2,NULL,NULL),(13064,'Airborne','Airborne','Mitchell Goosen is sixteen/seventeen year old kid from California who loves to surf and roller blade. Yet, his parents, who are two zoologists were given a grant to work in Australia. The only problem was: Mitchell couldn\'t go with them. So, he gets sent to stay with his aunt, uncle, and cousin in Cincinnati, Ohio. When he arrives, he meets his cousin who is also his new roommate for the next six months: Wiley. Mitchell then goes to school and gets on the bad side the high school hockey players. Mitchell and Wiley end up enduring weeks of torture from the guys. Then, the big guys and Mitchell and Wiley have to learn to get along to try to beat the Central High School rivals in a competition down Devil\'s Backbone','There are two kinds of people: those who get AIRBORNE...and those who don\'t.',2600000,2850263,8.001156,6.1,20,91,'1993-09-17','en','/4TPCzvOoQmmParPjgHCiqqiVYIJ.jpg',2.513067172340603,3,'2026-09-10',2,NULL,NULL),(13066,'I Want Someone to Eat Cheese With','I Want Someone to Eat Cheese With','Life has its downs for James, living with his mom in Chicago at 39, an aging performer at Second City, eating and weighing too much. A woman he\'s been dating drops him, as does his agent, her brother. James turns down roles in local TV, roles that make him sad. Someone\'s remaking his favorite movie, \"Marty,\" a role he\'d love, but he doesn\'t even get an audition.',NULL,0,0,1.742383,5.7,12,80,'2006-01-01','en','/4zVqWaiC9Y2GJSmuJjMDRlYv4ae.jpg',2.392727891931543,3,'2026-09-10',2,NULL,NULL),(13067,'女人领地','In the Land of Women','\"卡特（亚当·布罗迪 Adam Brody饰）在好莱坞的事业进展得不大顺利，也一直遇不上能相伴终生的爱人。当漂亮女友索菲娅（埃琳纳·安娜亚 Elena Anaya饰）和他摊牌分手之后，卡特的心情跌到了谷底。他离开了洛杉矶，来到密歇根的祖母家，这里有大片的田园和蓝天，卡特开始了波澜不惊的生活。\r 祖母是神经兮兮的老人家，孤僻倔强，不近人情；此外，邻局的母亲莎拉（梅格·瑞安 Meg Ryan饰）和她的两个女儿，也让卡特得到了不一样的生活视角：莎拉忍受着丈夫外遇的事实，为照顾家庭委曲求全；大女儿正处于青春期，性格暴躁易怒，焦躁不安；小女儿只有11岁，却早熟地陷入了感情的世界。卡特走进这些女子的生活中，看着她们走过人生的四季风景，心里也获得了某种意义的救赎。\"','Get ready to fall',10000000,17500000,12.792446,5.8,160,97,'2007-04-16','en','/qbfVeY8sE3luiRXYZTPT9rjV6p1.jpg',2.94952624591782,3,'2026-09-10',2,NULL,NULL),(13072,'布鲁克林规则','Brooklyn Rules','布鲁克林，1985年。以暴民世界为背景，三位终生好友在爱、失去和忠诚的问题上苦苦挣扎。','Not made to be broken',8000000,458232,4.090382,5.8,18,99,'2007-04-30','en','/jTmCII6EnK1h0nLPusWvQnp9QTa.jpg',2.48024088215674,3,'2026-09-10',2,NULL,NULL),(13074,'重整旗鼓','Resurrecting the Champ','丹佛那破败的街头，一个头发花白的老男人推着一辆超市用的购物车，里面装着他在这个世界上所拥有的一切……没有人知道他真正的名字，所以他们给他起了一个“反复嚼”的外号。可是这些人中，却没有一个人知道那个不起眼的老男人，曾经是拳击赛场上最有前途的天才拳击手，在经过了多年的拳坛洗礼之后，很多拳手都认清了一个事实，那就是自己的下巴永远没有拳头硬--这其中也包括“反复嚼”，他不可避免地从“明日之星”的辉煌变成了“过时”的落魄，甚至连一条重量级拳击冠军的腰带都没有留下。如今，这位曾经伟大的拳击手，已经沦为和警察、街头混混周旋的老无赖，他知道自己永远都不可能重新回到拳击舞台上了，只能在过去的阴影中继续穷困潦倒地生活着。 　　  也许“反复嚼”永远都不可能想到，这个城市里竟然有一个人与他有着相似的感觉，那就是《丹佛时报》的体育记者埃里克·科南，因为他也一直活在自己那 “有名”的父亲的阴影之下，所以他才会下定决心成为一名记者……然而事实证明埃里克实在不是当记者的料，主编总是派他去报道一些无关轻重的体育事件，而当他自己意识到可能发现了一些大新闻的时候，又总是被自己的编辑麦茨无情的痛击，被指责找来一些过时、无用的资料性的东西充当新闻，根本就没有刊登的价值。 　  事业上的不如意使得埃里克的婚姻生活也亮起了红灯，妻子乔伊丝决定和他分居。埃里克害怕离婚，并不是说和妻子之间的感情多么值得珍惜，而是离婚就意味着他不能时时刻刻陪伴着儿子特迪的成长，就像他和他的父亲曾经历过的一样。所以他必须得做出一些尝试和改变，将生命的重心重新找回来，也包括他的工作，但是要怎么做呢？ 　  一个傍晚，刚刚走出报社的埃里克看到一群混混在围殴一位无家可归的流浪汉，让他感到不可思议的是，那个被围在中间、头发灰白的老男人竟然用一组漂亮的直拳进行了反击，他上下闪躲、迂回前进，都是非常华丽的拳击招式……直到埃里克出面赶走了那群仗着人多欺负人的小流氓后，他才意识到，自己刚刚救下的，竟然是曾经在拳坛轰动一时的传奇人物“战士”鲍勃·塞特菲尔德，这个发现让他感到很吃惊，因为各方面的渠道都传闻鲍勃已经死了，可是他就活生生地站在那里。这一回，埃里克终于看到，成功似乎正在朝自己挥手，因为站在自己面前的“反复嚼”……',NULL,0,0,4.898437,5.9,60,112,'2007-06-14','en','/rJKTZf2QIhUwvqsfkher1JlLCdZ.jpg',2.7327824210735643,3,'2026-09-10',2,NULL,NULL),(13075,'雪莉宝贝','Sherrybaby','涉毒已深的雪莉（玛吉·吉伦哈尔 Maggie Gyllenhaal 饰）因为抢劫而被判入狱，一晃眼三年过去，当雪莉重新回归社会之时，她，以及这个社会，都已经截然不同了。对于雪莉来说，最重要的事情就是夺回女儿艾利克斯（芮安·辛普金斯 Ryan Simpkins 饰）的监护权，目前她正由雪莉的哥哥鲍比（布拉德·威廉姆·亨克 Brad William Henke 饰）一家人抚养，很显然，鲍比的妻子并不认为雪莉有足够的能力成为一名合格的母亲。  　　某日，雪莉遇见了名为迪恩（丹尼·特乔 Danny Trejo 饰）的男人，这个男人和雪莉灰暗的过去有着藕断丝连的关系。迪恩的出现让雪莉再度陷入了窘境之中，她能够鼓起勇气，和过去一刀两断吗？','No one makes it alone.',2000000,622806,4.261509,6.3,41,96,'2006-09-08','en','/iD7wuJwk4PscXIAR8dkJ9ANsqgO.jpg',2.6581367771955238,3,'2026-09-10',2,NULL,NULL),(13079,'眼前的生活','The Life Before Her Eyes','高中女孩戴安娜（埃文·蕾切尔·伍德 Evan Rachel Wood 饰）似乎等不及成年，就要开始她狂野热烈、放纵不羁的人生，毒品、性爱这些成人游戏皆不在话下，然而她的好朋友莫琳（伊娃·阿穆里 Eva Amurri 饰）却是个相对保守的女生，对戴安娜担心抱怨却又无可奈何。然而，一场突如其来的校园枪击案，彻底改变了两个女孩的命运。  　　如今的戴安娜（乌玛·瑟曼 Uma Thurman 饰）已经是一所大学的艺术史教授，有一个同为教授的丈夫和一个可爱的小女儿。然而她的心却始终不得安宁，枪击案15周年纪念日临近，那个深藏在戴安娜脑海中的血色阴影又再次弥漫开来……  　　本片根据美国作家Laura Kasischke的同名小说改编。 ©豆瓣','Your life can change in an instant. That instant can last forever.',8000000,0,9.728143,6.1,88,90,'2007-09-08','en','/1Kmy4EfYegTyQNQeHZomTWvmFPe.jpg',2.830290692312576,3,'2026-09-10',2,NULL,NULL),(13090,'Sunshine Cleaning','Sunshine Cleaning','A single mother and her slacker sister find an unexpected way to turn their lives around in the off-beat dramatic comedy. In order to raise the tuition to send her young son to private school the mom starts an unusual business – a biohazard removal/crime scene clean-up service.','life\'s a messy business.',5000000,16174377,19.336367,6.5,255,102,'2008-01-18','en','/naCjq31ZNGbufYlXbxvIIrSAnsR.jpg',3.1122052495197305,3,'2026-09-10',2,NULL,NULL),(13092,'如何众叛亲离','How to Lose Friends & Alienate People','西德尼·扬是个胆大包天、离经叛道的英国年轻人，他毕业于名校，出身高知家庭，却偏爱旁门左道——创办了一本名为“后现代评论”的杂志专门解构和讽刺明星名流，很不受人家待见。杂志濒临倒闭的当口，扬意外接到来自纽约知名八卦杂志的电话，请他过去上班。进入新坏境的扬依然坚持自己的原则，他不肯根据上流人士的意思改稿，和老板怒吼“新闻自由”，不肯去拍新锐导演马屁……不断挑战潜规则难免让他和周围的一切格格不入。职场磕磕绊绊中，扬和女同事阿里森产生感情，又受到新人女明星苏菲青睐。扬慢慢学会顺应规则，似乎融入这个上流社会，但内心仍有个真正的自己从未停止呐喊……','He\'s across the pond, and out of his depth.',27000000,17286299,16.785866,6.2,244,110,'2008-10-02','en','/8Xd1mO861aK2OirTbxZrODNhihW.jpg',3.0732861123637836,3,'2026-09-10',2,NULL,NULL),(13121,'阴齿','Teeth','性感美丽的金发少女唐恩（Jess Weixler 杰丝•威克斯勒 饰）与大多数同龄人不同，她对性有着自己的认识。她坚持性必须以真挚的爱情为前提，并在学校代领一众志同道合的同学成立一个名为“承诺”的宣传团队。唐恩恪守童贞，并将此推广至整个组织。 但她冰冷的心却由于帅气的男孩托比（Hale Appleman 哈勒•艾普曼 饰）所融化，两人逐渐陷入热恋。在某个周末，托比约唐恩去瀑布游玩。随着情欲蔓延，二人开始相互爱抚。然而在关键时刻托比的命根子竟被唐恩的下体咬断！ 惊恐的唐恩慢慢认识到，自己竟是传说中极为罕见的阴齿人。她的生活开始发生转变……','Every rose has its thorns.',0,0,7.359286,5.2,210,94,'2007-01-19','en','/tkzOXrRsuYdVRkMBRRVsDCexwjB.jpg',2.951467217033112,3,'2026-09-10',2,NULL,NULL),(13132,'最爱你','All the Real Girls','In a small North Carolina town, Paul, a womanizer, meets Noel, a confused intellectual returning home for the first time in years since she left for boarding school. The film depicts the typical romance of a good girl and a bad boy, in an interesting way.','Love is a puzzle. These are the pieces.',0,0,3.65924,5.9,30,108,'2003-08-01','en','/sQ6dMkwPIFucYSmFQcr38WBYzs.jpg',2.5852987201342623,3,'2026-09-10',2,NULL,NULL),(13150,'自豪与荣耀','Pride and Glory','在纽约警署，泰尔尼家族声名赫赫。老弗朗西斯·泰尔尼（强·沃特 Jon Voight 饰）创下无数丰功伟绩，在黑白两道皆有很高声望，他的儿子小弗朗西斯（诺亚·艾默里奇 Noah Emmerich 饰）、雷（爱德华·诺顿 Edward Norton 饰）以及女婿吉米·伊根（柯林·法瑞尔 Colin Farrell 饰）也同样在警察的岗位上兢兢业业。某晚，正在参加橄榄球比赛的吉米突然得到噩耗，他所负责的辖区发生枪战，数名警员中弹身亡。在父亲的鼓励下，雷加入特别行动小组，开始追捕相关疑犯。 　　在调查过程中，雷发现越来越多疑点，进而察觉吉米、小弗朗西斯甚至敬爱的父亲都可能牵涉其中。正义在这一刻染上污点，雷的调查之路也充满曲折和危险……','Truth. Honor. Loyalty. Family. What are you willing to sacrifice?',30000000,31148328,10.703602,6.3,240,130,'2008-09-09','en','/8VZ1ABbtXqwPcc06yXbf3gj3anG.jpg',3.0631720971795424,3,'2026-09-10',2,NULL,NULL),(13154,'浴血蛟龙','Showdown in Little Tokyo','在洛杉矶市日本人聚集的地区小东京，以吉田先生为首的铁爪帮横行霸道，欺凌善良百姓，并且野心勃勃的想独占全美毒品市场。肯纳与强尼是洛城警探负责缉毒扫黑的工作，面对高手如云的铁爪帮，他们仍然決定出生入死为民除害……','One\'s a warrior. One\'s a wise guy. They\'re two L.A. cops going after a gang of drug lords. Feet first.',8000000,2275557,8.403859,5.7,95,79,'1991-08-23','en','/phwuQrs557cJkRhoS1TVWsslnJK.jpg',2.829833169857352,3,'2026-09-10',2,NULL,NULL),(13155,'重返奥兹国','Return to Oz','桃乐丝（费尔鲁扎·鲍克 Fairuza Balk 饰）对曾在奥兹国经历的一切都无比的怀念，无奈她弄丢了能够帮助她前往彼处的红宝石鞋。叔叔和婶婶以为桃乐丝已经疯了，将她送进了精神病院，在那里，桃乐丝遇见了一个陌生的女孩，在女孩的帮助下，桃乐丝成功的逃离了医院，并且在误打误撞之中再度来到了奥兹国。\r 不知道该何去何从的桃乐丝向她的老朋友稻草人寻求帮助，哪知道却误入了石头国王诺姆精心编制的圈套。来到了翡翠城，桃乐丝震惊的发现这里已经成为了一片废墟，就在这个节骨眼上，她又遭到了女巫格林达和其爪牙的攻击，被关进了地牢之中。','An all-new adventure down the yellow brick road.',25000000,11137801,5.650125,6.7,120,109,'1985-06-21','en','/dyMwaXA9nVhPiA5wYHsvfUAnbaB.jpg',2.913004873398525,3,'2026-09-10',2,NULL,NULL),(13156,'二手狮王','Secondhand Lions','暑假刚刚开始，14岁的男孩沃尔特就在百般的不情愿中被母亲打发到了位于乡下的两个伯父家，他们分别是贾斯和哈勃。初来乍到的沃尔特十分不习惯乡下的生活，对于两个个性古怪的伯父，他更是敬而远之。一张神秘的照片的出现拉近了沃尔特和伯父们的关系，追寻着照片里的线索，伯父们向沃尔特讲述起了他们当年的故事。那时一个充满了梦想和激情的年代，伯父们的故事为沃尔特打开了新世界的大门，与此同时，通过回忆往昔，贾斯和哈勃两个有故事的男人也找到了各自人生的意义和快乐所在。',NULL,0,0,15.011624,6.9,260,111,'2003-09-19','en','/eFDF3pLbRzXNFX19FWalflbI1CT.jpg',3.1385276059323997,3,'2026-09-10',2,NULL,NULL),(13158,'饮料杯历险记','Aqua Teen Hunger Force Colon Movie Film for Theaters','奶昔、薯条和肉丸的组合在埃及同贵妇犬的大战中逃生，期间不幸身亡的薯条由于林肯的帮助死而复生，林肯在被中情局逮捕前将奶昔等送回了家……肉球在新泽西的勾女演唱会毫无效果，奶昔循循善诱传播性文化并展示了自己引以为傲的塑身机。薯条上网检索塑身机信息却意外发现隐藏在塑身机之中的恐怖消息：塑身机是可以改变人类历史的邪恶机械，会引发灾难性的未来。同时一艘飞船中的机器人小组筹划得到奶昔的塑身机，这边厢，奶昔、薯条和肉丸为了启动塑身机必须得到控制母板，在和机器人的竞争中获胜后，塑身机终于启动，并变形成足以毁灭城市的巨大机器，奶昔一众展开了与塑身机的无厘头对决……',NULL,0,0,1.453146,6.5,35,86,'2007-04-13','en','/q3Ln4x4rv4nJsBBfukjvH2wiU28.jpg',2.620580985013771,3,'2026-09-10',2,NULL,NULL),(13159,'乔治亚法则','Georgia Rule','雷切尔（林赛·洛翰 Lindsay Lohan饰）有一个不幸福的家庭，母亲（菲丽西提·霍夫曼 Felicity Huffman饰）长期酗酒，雷切尔更是受到继父的性骚扰。在这样的环境下，雷切尔的性格充满叛逆和狂暴。她冲动易怒的脾性终于让母亲忍无可忍，决定把女儿送到遥远的小镇上，有她外婆乔治亚来管教。\r 　　乔治亚（简·方达 Jane Fonda饰）是镇上受人爱戴的老人家，却不是一个慈祥和蔼的外婆。雷切尔在平静的小镇上继续着她的风流情性，勾引男孩以明证自己的魅力，对于这个似乎不可救药的外孙女，乔治亚制定了一系列“乔治亚法则”实行管束。随着雷切尔慢慢融入这个小镇，在各种规矩下开始适应这里的生活，外婆也渐渐解开了她内心的隐秘，洞悉了她的不幸。而雷切尔，也开始用一种新的眼光，去看待母亲，看待亲情。','In this family, attitude doesn\'t skip a generation.',20000000,0,7.878177,5.6,130,113,'2007-05-11','en','/9C7VaTib40dBaBrefxFesQ7pbKW.jpg',2.887124660015021,3,'2026-09-10',2,NULL,NULL),(13160,'Over Her Dead Body','Over Her Dead Body','After his fiancée, Kate, dies in an accident on their wedding day, veterinarian Henry grows depressed. To help him move on, his sister has him visit psychic Ashley and gives her Kate\'s diary. Ashley uses the journal\'s details to convincingly deliver the fake message that Kate wants Henry to move on. However, Kate\'s ghost is watching over Ashley and Henry. Furious when they fall for each other, she vows to sabotage their relationship.','She\'s passed on... But she\'s not moving on.',10000000,0,12.067921,5.3,145,95,'2008-02-01','en','/85moNqAncGlJXEwt4Ja3DfNbiQY.jpg',2.903053496909876,3,'2026-09-10',2,NULL,NULL),(13166,'漫画家之路','Freddy Got Fingered','An unemployed cartoonist moves back in with his parents and younger brother Freddy. When his parents demand he leave, he begins to spread rumors that his father is sexually abusing Freddy.','A touching story of a young man who desperately wants to make his daddy proud.',0,0,8.710294,4.6,115,87,'2001-04-18','en','/gVmSZgxiT7ynyRLsEgg8Xs8ZVWX.jpg',2.8240351090395586,3,'2026-09-10',2,NULL,NULL),(13173,'哈拉十诫','The Ten','影片彻底颠覆了经典《十诫》的“人神契约”，由10个相互独立又彼此相关的幽默小故事串联而成。贯穿始末的叙述者，用戏谑的口吻向观众娓娓道来这十个令人瞠目结舌的短篇：一个忘背伞包却奇迹生还的跳伞男子，居然瞬间成为电视明星；一个把自己处子之身献给耶稣的老处女；一个不告诉儿子生父是谁的母亲；一个拿病人生命开玩笑的医生，在下一章节被抓入狱，遭受性虐待却被视为稀松平常之事……叙述者一直置身事外的讲述这段段荒诞不经的故事，直到他“通奸”的故事上演。','If He\'d meant the commandments literally, He\'d have written them in stone.',0,0,3.865122,4.9,57,96,'2007-08-03','en','/byhpbEcL1tuoNhU3x5vYF45QM8X.jpg',2.697924783406651,3,'2026-09-10',2,NULL,NULL),(13183,'守望者','Watchmen','由于邪恶势力肆意蔓延，一群具有超群实力的正义之士挺身而出，他们戴着面具，身着奇装异服，与各种坏蛋展开较量。不久，他们的英雄事迹通过媒体传遍全国，美元钞票、丝绸鬼魂、罗夏、城市队长等超级英雄的名字广为传播，他们更参与到大大小小的重大事件之中，也因各自的性格遭受着不同的命运。但是在20世纪70年代，政府出台的法令导致一部分不愿成为权贵爪牙的英雄退休，超级英雄集团由此分化。1985年的一天，效力政府的超级英雄“喜剧演员”被人杀害。四处逃亡的“罗夏”意识到有人正向曾经的超级英雄痛下杀手，而这背后隐藏着更大的阴谋……','Justice is coming to all of us.  No matter what we do.',130000000,185258983,64.798873,7,2811,163,'2009-03-05','en','/aVURelN3pM56lFM7Dgfs5TixcIf.jpg',3.917732276543273,3,'2026-09-10',2,NULL,NULL),(13184,'曼谷杀手','Bangkok Dangerous','身为职业杀手的美国人乔，远赴泰国执行任务。在结识聋哑女芳后，两人萌生爱意。厌恶了杀人生活的乔，想金盆洗手从此跟芳在一起过平凡人的日子。但出于种种原因，乔一直没有向芳透露自己的真实身份。他很怕一旦芳得知自己是杀手之后，将不会再跟他在一起。同时乔的刺杀任务进行的也不顺利，各方面的利益权衡让他伤透脑筋，他最终是否能得偿所愿成功退隐呢？','There\'s only one way out.',45000000,42487390,14.813057,5,332,99,'2008-08-21','en','/tIt6MFiy8XFWJUbNAoygE0QSdin.jpg',3.0243397060128627,3,'2026-09-10',2,NULL,NULL),(13187,'查理布朗的圣诞节','A Charlie Brown Christmas','圣诞节就要到了，查理·布朗觉得很沮丧，因为他不知道什么是圣诞节。露茜让查理·布朗亲自参加一些圣诞活动，并让他做圣诞演出的表演，为了把戏演好，查理·布朗很认真地排演圣诞剧，最后大家一起祝查理·布朗圣诞快乐。','That\'s what Christmas is all about, Charlie Brown!',0,0,8.701183,7.5,153,25,'1965-12-09','en','/vtaufTzJBMJAeziQA1eP4BLU24C.jpg',3.0196656345251696,3,'2026-09-10',2,NULL,NULL),(13191,'战争公司','War, Inc.','Brand Hauser（著名的战争公司）打算在将来，当沙漠国家turagistan发生暴动之后，可以设立一个分公司，由前美国总统接管，可以控制接管这个国家。约翰·库萨克扮演一名中年男子，他受命充当职业杀手，去刺杀中东某国的石油部长。性感女记者，阿拉伯流行歌星，一切在这次行动中纷繁呈现……','When it comes to war... America means business',5000000,1296184,6.265659,5.6,86,106,'2008-04-28','en','/nlGsWWYC9n4lkbIoTXmI42dkJqb.jpg',2.8016153164254836,3,'2026-09-10',2,NULL,NULL),(13193,'Saved!','Saved!','Teenage Mary Cummings, who has \"been Born Again her whole life,\" is about to enter her senior year at American Eagle Christian High School near Baltimore with her Fundamentalist Christian friends Hilary Faye and Veronica, the three of whom have formed a girl group called the Christian Jewels. Everything seems perfect—until Mary’s \"perfect Christian boyfriend\" Dean tells her, as they’re swimming underwater, that he thinks he\'s gay.',NULL,0,0,9.85123,6.3,147,92,'2004-01-21','en','/nmf2tFTcRJZVEQ9e3mgLH5gAQYs.jpg',2.9508553070441415,3,'2026-09-10',2,NULL,NULL),(13197,'第十大道和狼','10th & Wolf','《撞车》编剧最新街头暴力作品。根据FBI密探的真实记录改编，一名昔日的街头硬汉(詹姆斯马斯登)加入海军陆战队，波湾大战退役后回到费城老家，却 被卷入他的黑道家族恩仇，再度与往日纠缠不清的黑道仇家狭路相逢，面临两难选择……','The Intersection Where Family, Honor and Betrayal Collide.',8000000,143451,3.942464,6.3,24,107,'2006-02-19','en','/wzrJMJKZIpp5iw1S0zRx8xkxh5F.jpg',2.5435509061948047,3,'2026-09-10',2,NULL,NULL),(13198,'割腕者的天堂','Wristcutters: A Love Story','故事设定在一个死后的奇异时空，所有自杀后的人都会被聚集到这里。在这个异次元的世界里，除了每个人都拥有神奇力量外，一切看似跟现实世界毫无分别。男主人公齐亚为情割腕自杀后，本以为能就此一了百了，却阴差阳错的坠入这个自杀者的天堂。在路上，齐亚先后遇见了因各种原因自杀的路人，后与另外两位自杀者结伴同行，一起踏上了神奇旅程。','Life is a trip, but the afterlife is one hell of a ride',0,0,8.542921,6.7,160,88,'2006-01-24','en','/qModiIR60IMLP28ruGZluQOtsOj.jpg',2.988444576650616,3,'2026-09-10',2,NULL,NULL),(13201,'狂野的青春','Deuces Wild','1950s New York City. A bad and bloody gang war is about to erupt on the dysfunctional streets of Brooklyn. The Deuces at war with the vicious Vipers. Scott Kalvert directs this tale of lust, drugs, mayhem and madness during one hot summer on the streets of New York.','Some lines should never be crossed.',0,0,0.753481,5.5,34,96,'2002-05-03','en','/hclpdQdBrH5fakkwCNFGQ4KJmX9.jpg',2.5993418713504024,3,'2026-09-10',2,NULL,NULL),(13223,'老爷车','Gran Torino','曾参加过朝鲜战争的福特车厂退休老工人沃尔特•科瓦尔斯基（克林特•伊斯特伍德 Clint Eastwood 饰）在妻子去世后独自居住在密歇根州小城的低收入亚洲移民区。邻居是个苗族大家庭，其中一对兄妹引起了沃尔特的注意。姐姐苏（安蕾•荷 Ahney Her 饰）幽默善谈，逐步与固执又有点种族主义的老沃尔特成为了朋友；沉默寡言的弟弟涛（比•王 Bee Vang 饰）则被自己的远房表兄强迫加入当地的苗族黑帮，第一次行动就被指派去偷沃尔特视为珍宝的1972年福特老爷车。偷车不成，涛被家人强迫，给沃尔特打工赎罪，却没曾想与沃尔特建立了深厚的友谊。而当地的苗族帮派却不肯就此罢手，为了苏与涛的安全和社区的安宁，老战士沃尔特该如何行动呢？','Ever come across somebody you shouldn\'t have messed with?',33000000,269958228,50.7453,7.8,3086,116,'2008-12-09','en','/zUybYvxWdAJy5hhYovsXtHSWI1l.jpg',4.104009699711106,3,'2026-09-10',2,NULL,NULL),(13250,'危情24小时','Butterfly on a Wheel','尼尔（杰瑞德.巴特勒 饰）和爱碧（玛丽亚.贝萝 饰），是对婚姻生活幸福美满的夫妇。他们居住在环境优美安宁的芝加哥郊区，尼尔是野心勃勃的广告业主管，爱碧是一位家庭主妇，照顾两人五岁大的女儿苏菲。 　　就在爱碧生日的这个週末，尼尔却不能在家里陪她，因为他的老闆邀请他去僻静的乡间住处，尼尔不愿因此影响他在公司里的合伙地位，于是不情愿地答应受邀了，条件是让爱碧和她最好的朋友，在这个特别的日一起狂欢度过。爱碧找来了一位保姆照顾女儿，尼尔便开著车载爱碧出门，準备顺道送她去她朋友住处。 　　两人在车上轻松地聊起多年来的心路历程，以及他们对未来的计画，眼前生活的一切似乎都令他们十分顺心如意…。未料，就在这时候，车上突然冒出一个不速之客莱恩（皮尔斯布洛斯南 饰），他从后座拿著枪坐起来，显然他有共犯，两人绑架了他们的女儿，爱碧听到了手机彼端，传来了一个惊恐而细弱的声音。','Lives will be broken',20000000,0,13.118983,6.3,130,95,'2007-07-27','en','/892TqYE0ndxOTSpG6HdB1maUDn6.jpg',2.930897921877685,3,'2026-09-10',2,NULL,NULL),(13260,'灌篮大帝','Semi-Pro','时间回溯到上个世纪70年代初，正是美国的两个篮球组织并驾齐驱的辉煌时代：毫无疑问，NBA统领着竞技界，除此之外还有一个ABA，因为其离经叛道的天分和才能，以及华丽的技巧表演为主的作秀类篮球比赛，也在象征着“篮球天堂”的美国占据着属于自己的一席之地。在这个篮球的大环境下，故事却是围绕着一个名叫杰基·姆恩的歌手展开的，在那一曲《Love Me Sexy》深情款款的旋律下，他不但成为一支来自于密歇根州的ABA球队--弗林特热带队的老板兼教练，甚至还成了场上的主力队员。 　　然而，NBA宣布了决定合并ABA的计划，同时表示只会接纳其中四支成绩最优秀的比赛队伍进入NBA。至于剩下的球队，也就只能眼睁睁地面临着被解散的命运了。杰基为了挽救自己的球队，在前NBA的板凳球员莫尼克斯以及球技浮华的“城里人”克拉伦斯·威瑟斯的帮助下，决定重整他那已经等同于一盘散沙的球队，在最关键的时刻放手一搏，抢夺最后的席位和荣耀。','Putting the funk into the dunk.',0,33472850,10.449975,5.4,251,91,'2008-02-28','en','/7KJrvJf96UpkXsWVOjzCo1IbnW6.jpg',3.003566142487499,3,'2026-09-10',2,NULL,NULL),(13279,'合法入侵','Lakeview Terrace','白人公司职员克里斯·马特森（帕特里克·威尔森 Patrick Wilson 饰）与黑人女作家丽莎（凯丽·华盛顿 Kerry Washington 饰）建立了超越种族的爱情，婚后他们搬到安详宁静的“湖景水坝”，享受着甜蜜的幸福。但是他们喜悦的心情并未持续太久，马特森夫妇的邻居名叫阿贝尔•特纳（塞缪尔·杰克逊 Samuel L. Jackson 饰），是供职于洛杉矶警署的一名黑人警官。阿贝尔严厉古板，不苟言笑，而且似乎对跨种族的婚姻存有深深的敌意，也因此马特森夫妇成了他的眼中钉，肉中刺。  在此之后，阿贝尔用尽制造各种各样的麻烦，只为将马特森夫妇从社区内赶走。双方的矛盾越积越深，直至到了无法挽回的地步……','What Could Be Safer Than Living Next to a Cop?',20000000,27640028,20.495749,5.9,292,110,'2008-09-19','en','/2PFuLfsJT8ab4jR1JB1R1ye0Ja8.jpg',3.095780949372259,3,'2026-09-10',2,NULL,NULL),(13282,'死亡车神','Death Race 2000','不久的将来，「死亡赛车」成为最炙手可热的运动盛事，参赛者之间必须一边竞速一边撞倒路人才能得分，有死忠赛车迷甚至会牺牲自己的生命让喜欢的车手赢得比赛，此时更有野心勃勃的车队想让比赛更加血腥，而这将危及所有车手和观众的性命...，他们的阴谋真能得逞？！  　　席维斯史特龙主演，五个全美著名的赛实手，在一场跨越全洲的大赛中，彼此勾心斗角的想争取全国冠军之名，不惜撞死沿途路人及车迷为他们准备的目标．．．因为这项比赛计分方式，就是以撞死人命来分胜负。  　　这是一部暴力影片，在一场死亡大赛中，众人以杀戮为人生最大乐趣，他们要比出谁杀人最快，谁杀人最多，而杀死老人和儿童就可以获得高分奖励，是一场货真价实的血腥场面……','A Cross Country Road Wreck!',300000,8000000,6.473667,5.9,124,80,'1975-04-27','en','/ghhLKMB7SzyS09PV2nIqfplghEB.jpg',2.887746325553769,3,'2026-09-10',2,NULL,NULL),(13335,'猪头逛大街2','Harold & Kumar Escape from Guantanamo Bay','哈罗德·李（约翰·赵 John Cho 饰）喜欢的女孩玛丽娅去了阿姆斯特丹，他决定追随而至，想尽一切办法赢得她的欢心。在机场，卡玛·派特（卡尔·潘 Kal Penn 饰）偶然遇到了他的前女友温妮莎，却惊讶地发现她就要结婚了。卡玛还没上飞机呢，他就和机场的警卫发生了激烈的争吵，差一点误了事，不过两人最终成功地登上了飞机。由于等不及在飞机上那漫长的6个小时，卡玛跑到厕所里自制了一个“无烟器”--骚乱由此引发，“无烟器”被误认成炸弹，而哈罗德和卡玛则不幸地被当成恐怖分子。这场突发事件致使飞机改变了航向，把他们送到了关塔那摩湾的监狱中关了起来。不甘心的两人成功越狱，从关塔那摩湾跑出来之后，哈罗德和卡玛途经迈阿密抵达德州--温妮莎婚礼的举办地，决定破坏婚礼。但不知道紧随在他们身后的是国家安全局的长官罗恩·福克斯，他要重新抓回这两个高度危险的恐怖分子......','This time they\'re running from the joint.',12000000,43493123,26.219598,6.2,497,107,'2008-04-25','en','/gmXKlm8c8O7JEISYP4WiWq2x3We.jpg',3.2529209031948727,3,'2026-09-10',2,NULL,NULL),(13342,'开放的美国学府','Fast Times at Ridgemont High','喧闹的中学校园里，一群中学生正为了爱情和兼职忙得不可开交。高大帅气的布拉德（祖德·莱茵霍尔德 Judge Reinhold 饰）颇受欢迎，同时也是连锁快餐店的出色员工，但他和女友的关系似乎走到了尽头。布拉德的妹妹史黛丝（詹妮弗·杰森·李 Jennifer Jason Leigh 饰）对爱情充满憧憬，在好友琳达的劝说下对亲近男青年跃跃欲试。冲浪小子杰夫（西恩·潘 Sean Penn 饰）整日嗑药浑浑噩噩，令古板的教师头大如斗。和史黛丝在同一座商场兼职的瑞特性格羞涩，想要接近史黛丝却始终笨拙，瑞特好友迈克自诩把妹达人，为瑞特连续出谋划策却把史黛丝勾搭到了手。史黛丝连续经历没有意义的混乱两性关系，终于留意到瑞特的可爱之处。而布拉德在遭遇失业打击后再难觅得称心工作。夏夜漫漫，年轻人的故事好笑又略显苦涩……','Fast Cars, Fast Girls, Fast Carrots...Fast Carrots?',4500000,27092880,20.403344,7,322,90,'1982-08-13','en','/fuQKCEQSCwEe1B08mgBjgVNvTWt.jpg',3.216595518545047,3,'2026-09-10',2,NULL,NULL),(13362,'开往暗处的的士','Taxi to the Dark Side','这部由奥斯卡提名导演亚历克斯·吉布尼执导、新近获奖的纪录片，印证了他作为当今顶尖非虚构电影创作者的地位。影片对2002年巴格拉姆空军基地一名阿富汗出租车司机可疑死亡事件进行了精密调查，细致梳理了这位无辜平民如何被地球上最强大的民主国家逮捕、监禁、酷刑折磨并最终杀害的过程。通过将事件文件记录与目击者及参与者的坦率证词交织呈现，影片揭示了巴格拉姆发生的悲剧与华盛顿最高层政策之间无可回避的关联。吉布尼以法医般的冷静超然与对美国持有高标准的激愤之情，揭露了布什政府如何系统性地背叛了其宣称要捍卫的理想。[THINKFilm]','In 2002, a young cap driver picked up a few passengers near his home in Afghanistan... He never returned',1000000,274661,0.748565,6.6,53,106,'2007-04-30','en','/ttCOk1fQGvFJvPIJS7D8J2jOjpo.jpg',2.7116062482865386,3,'2026-09-10',2,NULL,NULL),(13363,'这个男人来自地球','The Man from Earth','一个普通男人的秘密在他的辞职事件中开始显示出端倪。历史教授约翰奥德曼（David Lee Smith饰）说自己身上有一个让大家都匪夷所思的秘密，而为了保守这个秘密他不能在一个地方超过十年。他的朋友们试图去发掘他的故事中的秘密，这一举动让约翰非常生气，而他的朋友却发现约翰的故事是无法被否定也无法查证的，究竟约翰身上有着怎样的秘密？一幕幕碎片联系起来，带给我们一个意料之外的故事高潮。','From one of the acclaimed writers of Star Trek and The Twilight Zone comes a story that transcends both time and space...',0,0,31.339015,7.7,687,87,'2007-06-10','en','/6r3OUI4GC8i7nmTEa4i6fe3KKqW.jpg',3.55530032142031,3,'2026-09-10',2,NULL,NULL),(13370,'风载歌行','A Mighty Wind','秉承《摇滚万岁》、《等待古夫曼》和《爱犬大赛》的传统，这部仿纪录片聚焦于民间音乐世界。','Back together for the first time, again.',6000000,18750246,4.053017,6.6,74,91,'2003-04-16','en','/5wUYwAD75BxtJ0Mp4da6XzHIFex.jpg',2.7940550702590197,3,'2026-09-10',2,NULL,NULL),(13374,'冰雪公主','Ice Princess','在布莱尼•凯茜•卡勒里(米歇尔•崔切伯格饰)心中，有一片比哈佛大学更神圣的地方，那就是镁光灯聚焦的闪闪发光的冰上舞台。  　　凯茜天姿聪颖，被保送到哈佛大学，但入学之前她必须独立完成一个物理实验。一直以来都对花样滑冰有着莫名情愫的她，选择了这项运动作为实验主题。而正是这次实验激发了凯茜内心对花样滑冰的潜在渴望。一次次尝试中，凯西过人的天赋慢慢显露。是做一名高校的天之骄女，还是放弃机会走向专业的运动生涯？无疑，单身母亲(琼•库萨克饰)殷切的希望女儿选择前者。可冰上自由的旋转跳跃，曼妙的舞姿和偶然而至的爱情，着实令她难以割舍。',NULL,25000000,27645491,13.288177,5.9,185,98,'2005-03-17','en','/zMNDU41Sz5GO3HzRELarbc7zJrE.jpg',2.9859736163930677,3,'2026-09-10',2,NULL,NULL),(13389,'火线特攻','Righteous Kill','纽约两位资深警探特克（罗伯特•德•尼罗饰）和罗斯特（阿尔•帕西诺饰）是一对亲密无间的老搭档，二人合计已在警署工作100年。特克脾气火爆，而罗斯特处事圆滑。最近，纽约出现了一位连环凶手，特克与罗斯特二人负责调查此案。在调查过程中，他们发现凶手有特殊的习惯与高超的射击水平，而更奇怪的是，被害人都与特克有千丝万缕的联系。天使般代表正义的警察，与恶魔般代表罪恶的犯罪者。谁才是真正的特克？一段段迷雾拨开，惊人的真相在内心的黑暗处等待。','Most people respect the badge. Everybody respects the gun.',60000000,73174566,18.380176,5.9,375,101,'2008-09-11','en','/ajSpaWK94xcAqcwlIW7RYdf45Pn.jpg',3.141683850054605,3,'2026-09-10',2,NULL,NULL),(13403,'摇滚芭比','Hedwig and the Angry Inch','在这部开创性的音乐剧中，身兼编剧、导演与主演的约翰·卡梅隆·米切尔与作曲作词人斯蒂芬·特拉斯克将他们标志性的创作从舞台搬上银幕，成就了一部如主角般难以归类的电影。赫德维格（米切尔 饰）在东柏林以男孩身份长大，为了移民美国经历了一场创伤性的身体改造，此后她重塑自我，成为一名“国际级被忽视”却天赋异禀的摇滚巨星——米切尔将其诠释为置身于“独一无二的美丽性别”。影片通过赫德维格的音乐讲述她的故事，这些由特拉斯克创作的原创朋克圣歌与力量民谣风格多元，并与自由奔放的电影画面交织：音乐录像式的幻想、动画插叙以及刺痛人心的情感现实主义片段。本片既是一组激昂的歌曲循环，也是一段温柔的人物研究，致敬了摇滚乐超越性的力量。[标准收藏]','An anatomically incorrect rock odyssey',0,0,4.25422,7.4,80,95,'2001-07-20','en','/jafIFAW8sHQkzWPGoMDR4892dFI.jpg',2.8359613810227238,3,'2026-09-10',2,NULL,NULL),(13405,'黄石的孩子','黃石的孩子','英国记者乔治•何克（乔纳森•莱斯•梅耶斯 饰）潜入了南京，打算把日军在当地的暴行公诸于世。可是他被日军发现了，在即将被斩头之际，一名中国游击队员陈汉生（周润发 饰）救起了。何克还认识了战地外籍医生丽（拉达•米契尔 饰）。何克辗转到了黄石，与60多名孤儿一起居住。孩子们保饱受战争折磨，对外国人他们都有抵触心理，甚至不尊重。可是随着时间的过去，何克的热心与善良还是感动了孩子们，短短几个月他们的生活与周遭环境有了很大的改善。也幸得有好心人王太太（杨紫琼 饰）的帮助。生活日渐上了安稳的轨道，战争的步伐也逐渐逼近。何克与汉生还有丽决定带着孩子们到山丹，一个人迹罕至的地方。路途之艰辛，同伴的离世也无法阻挡他们的脚步。可是一场疾病，还是打击了汉克、丽与孩子们的生活……','War made them orphans, one man made them legends',40000000,7400000,8.978408,6.5,52,125,'2008-07-03','zh','/8XjJT03UgjcbUpVuqZg5z5j450A.jpg',2.724172339134141,3,'2026-09-10',2,NULL,NULL),(13408,'鱼龙混杂','The Wash','With the rent due and his car booted, Sean (Dr. Dre) has to come up with some ends...and fast. When his best buddy and roommate Dee Loc (Snoop Dogg), suggests that Sean get a job busting suds down at the local car wash.','When you\'re down \'n dirty, it all comes out in...',7000000,10229331,2.453459,5.3,26,93,'2001-11-16','en','/xb63VT8E4Q2RjLT7qnzvc5jRFAQ.jpg',2.5466669569115723,3,'2026-09-10',2,NULL,NULL),(13411,'马里布绑票案','Malibu\'s Most Wanted','布拉德是生活在加州马里布市的一个白人孩子，但是他却着迷于美国黑人的饶舌乐，认为自己是整个马里布最热的饶舌歌手，还管自己叫\"B-拉德\"。每天他和几个同伴一起玩音，虽出身当地一个显赫的白人家庭，说的却全是黑人贫民窟小孩的\"黑话\"，满嘴跑俚语。他幻想自己是贫民区的孩子，觉得黑帮分子的生活新鲜刺激，十分向往。他的这种怪癖让他的家人很是受不了。',NULL,0,0,7.314796,4.7,77,86,'2003-04-10','en','/bjYuoz2S8S1AED5QIMvmAi21drc.jpg',2.756024073760127,3,'2026-09-10',2,NULL,NULL),(13429,'驴子潘趣','Donkey Punch','“驴子潘趣”是一种既危险又变态的性爱游戏，然而，为了获得更大的快感，许多年轻人们冒着生命危险乐此不疲的沉溺于其中。在一次和四个男孩的放纵中，女孩莉莎（希安·布莱金 Sian Breckin 饰）成为了这个游戏的牺牲品，而误手将她杀死的男孩乔什（朱利安·莫里斯 Julian Morris 饰）不顾众人的反对，执意决定毁尸灭迹。乔什的举动大大的刺激到了莉莎的好友金姆（杰美·温斯顿 Jaime Winstone 饰）和黛米（妮可拉·布利 Nichola Burley 饰），而这两个很可能会泄露实情的目击证人成为了男孩们猎杀的对象。\r 　　在广袤而沉默的大海上，进行着一场生死攸关的大逃杀，面对丧心病狂的男孩们，金姆和黛米能够逃出生天吗？','This party is going overboard',0,0,3.283886,4.5,52,99,'2008-07-18','en','/7kk6dvvPVzZxii2Fez81LJZgtLS.jpg',2.6711869887547124,3,'2026-09-10',2,NULL,NULL),(13435,'冲出逆境','Antwone Fisher','安东尼·菲舍尔(德里克·卢克饰)，是一个从小失去父母的孩子。他先是被送进孤儿院，后来被一对夫妇领养。在养父母的家中，菲舍尔度过了一个悲惨的童年，不仅被养父母滥施以私刑，还被没有血缘的“姐姐”折磨。不幸的遭遇使菲舍尔养成了暴虐的性格和仇视女人的心理。 　　长大后的他，来到海军服役，因为性格问题经常引起麻烦。于是，他被命令接受军中的心理医生杰罗姆(丹泽尔·华盛顿饰)的心理治疗。 　　治疗的过程是艰难的。开始的时候，杰罗姆甚至无法了解菲舍尔的真正想法。直到后来通过慢慢接触，用感情的力量感化他，两人才渐渐开始了真正心灵上的沟通。而黑人女孩谢莉尔(乔伊·布赖恩特)、杰罗姆夫人（萨利·理查森饰）在菲舍尔转变中的作用也是不可小视。是她们温暖了菲舍尔的心，让他摆脱了儿时的阴影，重新找到了生活的航标。','Antwone Fisher is at war... with himself.',12500000,23367586,13.349012,6.7,137,120,'2002-12-19','en','/j9lCK1aFXqMO3hzhGiqCNU8coIX.jpg',2.9621094300293374,3,'2026-09-10',2,NULL,NULL),(13448,'天使与魔鬼','Angels & Demons','欧洲核子中心的科学家维多利亚•维特勒（阿耶莱特•祖瑞尔 Ayelet Zurer 饰）与父亲在高速粒子对撞机实验中收集到了反物质，却发现父亲遇害，尸体胸口被烙“光照派”符号，高爆炸性的反物质被偷走，出现在正待选新教皇的罗马梵蒂冈，威胁天主教廷及整个罗马的安危。于此同时，四位主要教皇候选人的红衣主教神秘失踪。在教皇内侍（伊万•麦克格雷格 Ewan McGregor 饰）的授意下，哈佛大学的符号学专家罗伯特•兰登教授和维多利亚都被请到梵蒂冈协助罗马警察开展搜寻行动。兰登说服罗马总探员奥利维迪（皮耶法兰西斯柯•法维诺Pierfrancesco Favino 饰）依照“土、气、火、水”的提示在罗马的名胜教堂间与“光照派”展开了时间战……',NULL,150000000,356613439,67.447636,6.5,2129,138,'2009-05-13','en','/tFZQAuulEOtFTp0gHbVdEXwGrYe.jpg',3.7386267019698396,3,'2026-09-10',2,NULL,NULL),(13460,'末日侵袭','Doomsday','致命病毒横扫英伦三岛，数十万人因此丧生。为应对威胁，临时政府对英国进行野蛮的隔离。虽然英国陷入恐惧和混乱，但是隔离检疫卓有成效，其它地区得以保全。三十年后，“收割者”病毒在主要城市爆发。一支精英小队被紧急派往任然处于隔离状态的英国，他们的任务是采取任何手段取得疫苗。孤立无援的小队必须依靠自己的力量杀出一条血路，完成任务。','Mankind has an expiration date.',30000000,22211426,21.538222,5.8,363,108,'2008-03-14','en','/2aON7R1G3TRRGO9FxIwZkq7yUUy.jpg',3.13233943040496,3,'2026-09-10',2,NULL,NULL),(13475,'星际迷航','Star Trek','史上最伟大的冒险，始于本片——一支年轻船员首次驾驶有史以来最先进的星舰“进取号”的传奇故事。在这场充满动作、喜剧与宇宙危机的旅程中，新招募的队员们必须设法阻止一个其复仇使命威胁全人类的邪恶存在。银河系的命运掌握在两位宿敌手中：一位是来自爱荷华州、叛逆而追求刺激的农场男孩詹姆斯·T·柯克；另一位是在摒弃一切情感的、基于逻辑的社会中长大的史波克。当炽热的本能与冷静的理性相撞，他们之间看似不可能却强大的伙伴关系，是引领团队穿越难以想象的险境、大胆前往前人未至之地的唯一希望！[派拉蒙]','The future begins.',150000000,385680446,73.616808,7.4,4518,127,'2009-05-06','en','/lV5OpzAss1z06YNagOVap1I35mH.jpg',4.162052816402733,3,'2026-09-10',2,NULL,NULL),(13476,'偶像有约','Win a Date with Tad Hamilton!','住在弗吉尼亚乡下的罗莎丽（凯特·波斯沃斯 Kate Bosworth 饰）是小猪仔超市的普通员工，生活虽然波澜不惊，却让她充满了幻想，罗莎丽疯狂迷恋英俊帅气的明星泰德·汉密尔顿（乔什·杜哈明 Josh Duhamel 饰），无时无刻不渴望与其见面。某天，即会从天而降。现实中的泰德与其在银幕上塑造的好男人形象截然相反，他养尊处优，浪荡不羁，负面新闻层出不穷。为了改变他的形象，泰德的团队策划一个为贫困儿童捐款的活动，有幸被选中的人可以与泰德共处一天。罗莎丽有幸当选，曾经远在天边的偶像竟然即将出现在自己面前。\r 在这一过程中，天真纯情的罗莎丽似乎渐渐找到真爱的方向…… ©豆瓣','In every love story, there\'s only room for one leading man.',17000000,16980098,7.701041,5.5,160,95,'2004-01-23','en','/5kXxbKlIEgMv0t8hLtZ3hfKLmG7.jpg',2.9216881143078552,3,'2026-09-10',2,NULL,NULL),(13483,'Awake','Awake','While undergoing heart surgery, a man experiences a phenomenon called ‘anesthetic awareness’, which leaves him awake but paralyzed throughout the operation. As various obstacles present themselves, his wife must make life-altering decisions while wrestling with her own personal drama.','Every year, one in 700 people wake up during surgery.',86000000,14373825,18.172736,6.3,395,84,'2007-11-28','en','/6MMxTxfqI4sfo3wNhyzadz0AzcA.jpg',3.1939062907581772,3,'2026-09-10',2,NULL,NULL),(13490,'欢迎回家，罗斯科·杰金斯','Welcome Home Roscoe Jenkins','史蒂文斯（马丁·劳伦斯 Martin Lawrence 饰）是目前大众视野中最当红的脱口秀明星，他的成功学演讲激励了无数深陷泥潭的年轻人们，引导着他们重新找回了人生的方向。实际上，史蒂文斯拥有着卑微的过去，在他的故乡，一座名为“旱泉”的小镇里，年幼的史蒂文斯，是邻里乡亲们嘲笑和欺负的对象。','Roscoe Jenkins aims for the heartstrings and funny bones, a raucous helping of family soul food.',35000000,43650785,6.248273,5.7,57,114,'2008-02-08','en','/1VzS2bkQHVcIxSeBJifOx65oxHK.jpg',2.7207855718445937,3,'2026-09-10',2,NULL,NULL),(13491,'圣殿骑士','Arn: Tempelriddaren','Arn是瑞典一位高层贵族的儿子，在修道院受教育后，被送往圣地耶路撒冷作为一个圣殿骑士，之后又抵抗封建领主。表现了主角为禁忌的爱而勇于保卫信仰来做忏悔的故事。','A Knight in the Holy Land. A Woman in the Frozen North. A War that Kept Them Apart.',25000000,0,6.091033,6.4,76,139,'2007-12-17','sv','/pbLOWq0vlc3Y6beOj0p5LehlUQy.jpg',2.7990864293864894,3,'2026-09-10',2,NULL,NULL),(13495,'佣兵传奇','Alatriste','故事发生在十七世纪的西班牙，阿拉特里斯德（维果·莫特森 Viggo Mortensen 饰）是誉满全国的军队上尉，同时亦是巴尔博亚（尤纳克斯·乌高德 Unax Ugalde 饰）的监护人。阿拉特里斯德希望能够将巴尔博亚培养成为和自己一样孔武有力的真正的男子汉，然而巴尔博亚却爱上了名为安杰丽卡（埃琳纳·安娜亚 Elena Anaya 饰）的危险女子，这令阿拉特里斯德忧心忡忡，因为安杰丽卡的父亲路易斯（Jesús Castejón 饰）和自己曾经有过一段恩怨。  　　受宗教裁判所首领弗雷（布兰卡·波蒂洛 Blanca Portillo 饰）所托，阿特拉里斯德和路易斯接受了一项十分危险的刺杀任务。然而，在执行任务之时，阿拉特里斯德却被刺杀对象的崇高精神所折服，将两人放走，亦给自己带来了麻烦。',NULL,24000000,23321954,6.009644,5.6,61,145,'2006-09-01','es','/iffLhhLtTNODIiCbrIxQMtQjkNS.jpg',2.7318225354115477,3,'2026-09-10',2,NULL,NULL),(13496,'狂风沙','American Outlaws','故事发生在美国中西部的一个小镇上。在美国内战期间，当地的一些农民小镇时，他们还是一群孩子。4年后，他们作为战败的南方人回到自己的家乡，想重新开始他们以前的生活——耕种土地、养家活口，此时他们已是一群强壮的男子了。但是，“回家”的梦景是短暂的：杰西·詹姆斯（科林·法瑞尔饰）和他的弟弟弗兰克·詹姆斯（加布里埃尔·麦希特饰）、科尔和鲍勃·扬格兄弟以及他们信得过的朋友科马奇·汤姆回到他们久违的家乡时，发现小镇已被联邦军队占领了。而财大气粗的铁路巨头撒迪厄斯·瑞恩斯的石岛铁路公司正在向西拓展，他公司强迫农民们以不合理的低价将他们世代的家园售出。更糟的是，恶名远扬的艾伦·平克顿私人侦探公司也竭尽全力地帮助这个铁路公司欺压无辜的农民。这一小群退役的士兵们为了共同的利益而团结起来，开始保卫家园。他们要向铁路公司最要害的地方下手，阻止他们无法无天地铺设铁路。起初，他们的对手低估了他们，但这帮兄弟们毁坏了铁路供应线、颠覆铁轨、抢劫公司存储薪水的银行，称得上无所不为。他们用事实证明，他们才是彻头彻尾的无法无天之徒。这些无法无天之徒将掠夺来的财物与人们分享，在人民心中成为了受人尊敬的英雄。','Sometimes the wrong side of the law is the right place to be.',35000000,13678913,6.727949,5.7,55,94,'2001-08-17','en','/ov9PIn56yrwvrwOfvVTKplmV0S6.jpg',2.7145543312054103,3,'2026-09-10',2,NULL,NULL),(13497,'乐鼓热线','Drumline','一个拥有天份且酷爱节奏的鼓手-戴文，高中毕业后，随即加入亚特兰大的大学鼓号乐队，学校为了年度校际鼓号乐队大赛，特别对这群菜鸟展开严格的魔鬼训练。然而，天赋异秉却特立独行的戴文，老是採取不妥协的态度，却造成了团体中的严重冲突，眼看比赛即将来临，他们要如何在年度大赛中脱颖而出？','Half time is game time',20000000,57588485,4.748929,6.2,116,118,'2002-12-13','en','/zl7gdxYqKdFCioPT3DAkZR5DDUP.jpg',2.8823243368667018,3,'2026-09-10',2,NULL,NULL),(13498,'辣妹保镖','Man of the House','家住美国德州的罗兰·夏普（汤米·里·琼斯 Tommy Lee Jones 饰）是一名为人古板、对工作及其专注负责的警察。他由于太过投入，结果导致老婆带着孩子离家出走。这一日，罗兰正在寻找的一名关键证人遇害身亡，而德州大学的无名拉拉队女孩则宣称亲眼目睹了凶案发生的全过程。为了保护女孩们的安全，警署不仅要求罗兰24小时跟在她们身边，还要求他以拉拉队教练的身份带着女孩们住在自己家中。这群正处在青春期的快乐女孩突然失去自由，她们又怎能忍受无休无止的禁足生活？为此，女孩们和罗兰之间发生不少的矛盾。\r 　　另一方面，杀害证人的凶手暗中观察，时刻寻找下手的良机。罗兰和女孩们该如何面对这个潜在的危险？','Protecting witnesses is a challenge. Living with them is impossible.',40000000,0,6.004422,5.4,120,100,'2005-02-25','en','/anBhlqCABytNvybE2Xr3tvsCOTp.jpg',2.8586534733846087,3,'2026-09-10',2,NULL,NULL),(13501,'晚安好梦','The Good Night','盖瑞（马丁·弗瑞曼 Martin Freeman 饰）是一名音乐制作人，曾经在职业上小有成就的他如今陷入了瓶颈之中，而他的好友保罗（西蒙·佩吉 Simon Pegg 饰）却迎来了事业的高峰，这让盖瑞的心中十分不是滋味。与此同时，盖瑞和女友朵拉（格温妮斯·帕特洛 Gwyneth Paltrow 饰）之间的感情亦跌落到了冰点之下。','Dreaming is believing.',15000000,20380,12.185204,5.7,41,93,'2007-01-25','en','/74TDF1OMKOkTonAUbtbsJOdqtVy.jpg',2.6666445447270117,3,'2026-09-10',2,NULL,NULL),(13503,'飙风特警','Texas Rangers','1875年的德克萨斯州，到处是一派空旷荒蛮的景象，在这片土地上，不存在着任何的法律和秩序，强盗们藐视一切、横行霸道，数不清的骗子、投机者和不法商人都聚集在这里，可谓是罪恶孳生，混乱之极。\r 　　当这一丑恶的现象让人们忍无可忍的时候，一位名叫林德·麦克内利（迪兰·麦克德莫特）的传奇人物出现了，他凭借着渴望正义的人们的信任和自身的号召力，组建起一支前所未有的执法生力军——德州游侠。\r 　　这支队伍由一群血气方刚，充满朝气和使命感的小伙子（詹姆斯·范德比克、阿什顿·库切尔等）组成，他们的职责就是铲除邪恶匡扶正义，他们的敌人就是在这里横行无忌的土匪恶棍们，他们的勇气来自保卫无辜者和自己爱人的誓言，支持他们战斗的动力就是他们对这片家园的深深眷恋，他们发誓要在这里树立起新的公正。',NULL,0,0,5.641978,5.4,19,110,'2001-11-30','en','/69tMHlxiCYlYKGZm1aPH1u7hY88.jpg',2.491750331440952,3,'2026-09-10',2,NULL,NULL),(13508,'谁消灭了电动车','Who Killed the Electric Car?','本片是一部探讨电动车兴衰的纪录片。1996年问世的电动车，拥有燃油车、混合型动力车和氢燃料电池车所不能比拟的环保节能费用低廉等优越性，但是不知为何，这种车却最终没能推广起来。到底是什么造成了这一结果呢？本片导演通过调查揭示，原来电动车的殒落是一场谋杀。','A lack of consumer confidence... or conspiracy?',1000000,1678874,5.323184,7.2,59,92,'2006-08-04','en','/uMamC9o5zNU9wn8fyuAo2gUCMiD.jpg',2.7594598020625134,3,'2026-09-10',2,NULL,NULL),(13510,'伊甸湖','Eden Lake','热恋中的珍妮（Kelly Reilly 饰）与史帝夫（Michael Fassbender 饰）来到美丽的湖边，计划度过一个浪漫而温馨的周末。但是他们的周末被一群胡作非为、大声喧哗的少年给搅乱。一番口角冲突过后，夫妇俩的食物以及车钥匙不翼而飞。他们只得徒步前往镇上求助，却不知道，这恰恰是恶梦的开始……\r 　　本片荣获2009年《帝国》杂志奖最佳恐怖片奖、2009年葡萄牙奇幻国际电影节最佳导演奖、2009年伦敦影评电影金像奖英国年度青年演员奖（Thomas Turgoose）、2008年Sitges – Catalonian国际电影节评审团特别奖最佳影片。','A weekend by the lake, with views to die for.',0,3983997,20.362373,6.7,406,91,'2008-09-12','en','/uOTrak7p2vc1PJUwQo7tCofPNeg.jpg',3.248157578925443,3,'2026-09-10',2,NULL,NULL),(13515,'鬼镜','Mirrors','《鬼镜》是2007年由亚历山大·阿嘉导演的恐怖电影，也是亚历山大的第二部好莱坞作品，由基弗·萨瑟兰、艾米·斯马特等主演。本片以一面诡异的镜子为主体，讲述了主人公无意发现了它，之后主人公以及家人挣扎在生存与死亡之间的故事。','There is evil...On the other side.',35000000,72436439,19.774543,6,485,110,'2008-08-15','en','/lDHpIFXP27I6WY08rZgSXMvCXv5.jpg',3.2087668741550774,3,'2026-09-10',2,NULL,NULL),(13516,'Slacker Uprising','Slacker Uprising','Slacker Uprising is a movie of Michael Moore\'s tour of colleges in swing states during the 2004 election, with a goal to encourage 18–29 year olds to vote, and the response it received. The film is a re-edited version of Captain Mike Across America, which played at the Toronto International Film Festival in 2007. It is one of the first feature length films made by a known director to be released as a free and legal download online. The free download is only available to those residing in the United States and Canada. The film was also made available free for online viewing and download on the Lycos Cinema platform as well as iTunes and blip.tv. It had a one-night-only run at the Michigan Theater, where Michael Moore spoke briefly. The film is available in DVD format. Slacker Uprising features live performances or appearances by Eddie Vedder, Roseanne Barr, Joan Baez, Tom Morello, R.E.M., Steve Earle, and Viggo Mortensen. The original score is by Anti-Flag.',NULL,0,0,1.619635,5.9,10,102,'2007-09-27','en','/aZappNo0qadtT2qyrPREAZ6GVoZ.jpg',2.357314536706943,3,'2026-09-10',2,NULL,NULL),(13518,'Fuel','Fuel','Record high oil prices, global warming, and an insatiable demand for energy: these issues define our generation. The film exposes shocking connections between the auto industry, the oil industry, and the government, while exploring alternative energies such as solar, wind, electricity, and non-food-based biofuels.',NULL,0,0,0.197469,7,3,90,'2008-11-14','en','/fg88f3Nis36udZAEryzB1iQ1iYo.jpg',2.1363553445291235,3,'2026-09-10',2,NULL,NULL),(13523,'破处之旅','Sex Drive','为了脱去十八岁处男身，他与好友开着1969年的GTO上路，展开一场跨越美国公路的寻爱之旅，二男一女将搞出多少笑话？！ 由Sean Anders编导的成长喜剧，讲述一名十八岁的青年伊恩（Josh Zuckerman饰）在网络上认识了一个甜美可人的女网友，对方答应只要伊恩前往Konxville见她，就为伊恩摆脱处男之身。 于是，伊恩便与好友兰斯（Clark Duke饰）及另一名友人费莉西亚（Amanda Crew饰），驾着弟弟雷克斯1969的GTO上路了。一路上，他们遇上各种奇人异事，三人的关系也渐渐产生异样的变化....。','He\'s leaving virgin territory',19000000,18755936,17.952817,6,342,109,'2008-10-16','en','/aO4swvDjqW635lesjYbytrEhBsn.jpg',3.131643819139589,3,'2026-09-10',2,NULL,NULL),(13536,'疑云重重','City by the Sea','文森特（罗伯特•德尼罗 Robert De Niro 饰）是一名经验丰富的警探，他凭借着冷静的思考个高超的智商破获了一起又一起疑难杂案，深受同僚和市民们的信任。在负责调查一宗重大案件时，文森特震惊的发现，自己一直在追捕的幕后黑手，竟然是自己的亲生儿子乔伊（詹姆斯•弗兰科 James Franco 饰），原来，早年间，文森特离开了妻子和儿子，因为父亲的缺席，乔伊心中充满了痛苦与愤怒。','When you\'re searching for a killer... the last suspect you want to see is your son.',40000000,22433915,3.476966,5.7,92,108,'2002-09-06','en','/vpjKtnE5SGTfmdw4YtJsnrfFJs0.jpg',2.8120854395132375,3,'2026-09-10',2,NULL,NULL),(13537,'欲盖弥彰','Shattered Glass','斯蒂芬•格拉斯（海登•克里斯滕森饰）95年从宾西法尼亚大学毕业后，加入了具有90年悠久历史、在美国颇有影响力的、以刊登政治和社会评论著称的杂志《新共和》。由于总能采集到新奇的选题、写出有趣的文章，他很快便得到大家的赏识。一天，新上任的主编查尔斯•雷恩（彼得•萨森加德饰）发现斯蒂芬•格拉斯所有的文章都是杜撰出来的，一切的名声与文采飞扬都如玻璃般脆弱，《新共和》面临揭开真相的关头。',NULL,6000000,2944752,6.27257,6.6,111,94,'2003-11-14','en','/bIFJ49tk79hiFr9Z6bF6QapTg66.jpg',2.892053905548956,3,'2026-09-10',2,NULL,NULL),(13538,'迷夜惨遇','Straightheads','故事发生在一幢地处偏远的豪华饭店之中，爱丽丝（吉莲·安德森 Gillian Anderson 饰）和亚当（丹尼·戴尔 Danny Dyer 饰）正在进行一场充满了浪漫气息的完美约会，情到浓时，无法自持的两人决定开溜，前往一条荒无人烟的小路。灾难就在此时毫无征兆地降临了，一帮穷凶极恶的歹徒将亚当打到，美丽迷人的爱丽丝在枪支的威胁之下惨遭强暴。这件事情在爱丽丝和亚当的心中留下了深深的阴影，警方的无能给予了两人除了暴力和伤害之外的第三重打击，久久无法释怀的他们决定自己拿起武器，进行复仇。一把枪，一个绝望的男人和一个痛苦的女人，一个正在悄然浮出水面的阴谋，亚当和爱丽丝最终能否寻得他们所谓的正义呢？','Let the revenge fit the crime',0,0,8.302951,5.2,40,88,'2007-04-27','en','/5W8jG9kt2UfEq8Tn0rb3BRaOPqe.jpg',2.6448883747694323,3,'2026-09-10',2,NULL,NULL),(13539,'Here On Earth','Here On Earth','A rich college kid is taught a lesson after a joy ride ends up destroying a country restaurant.',NULL,0,0,3.313257,5.4,48,96,'2000-03-23','en','/shvubL3pIrCyEK22ZHrx00oNtCY.jpg',2.6732322335167074,3,'2026-09-10',2,NULL,NULL),(13551,'死亡女孩','The Dead Girl','一次偶然中，一直默默无闻和母亲相依为命的雅顿（托妮·科莱特 Toni Collette 饰）发现了一具年轻的女性尸体，死去的女子名为克里斯塔（布莱特妮·墨菲 Brittany Murphy 饰），死因是谋杀。这一爆炸性的消息让雅顿瞬间成为了社区里的红人，她单调枯燥的生活一去不复返了。','One life ends. Seven others begin.',0,0,3.069605,6.4,66,85,'2006-11-07','en','/wBIn93ZY0Qd3BafjSJYvqgAZu88.jpg',2.7609941895121994,3,'2026-09-10',2,NULL,NULL),(13569,'猜谜杀手','Thr3e','Innocent lives hang on the whim of an elusive psychopathic murderer whose strange riddles and impossible timelines force three people into a mission to end the game before one or all of them die.',NULL,0,0,1.946715,4.8,21,101,'2006-12-01','en','/fGXWsdhfJ4UIdCnsCJMkT2Ulo9p.jpg',2.498406118573995,3,'2026-09-10',2,NULL,NULL),(13576,'就是这样','This Is It','2009年6月25日，这可以说是全球音乐界的巨大损失。迈克尔·杰克逊（迈克尔·杰克逊 Michael Jackson 饰），全球瞩目的流行音乐巨星在这一天就此陨落。原本，计划在2009年夏天举行的名为“This is it”告别演唱会，也无法如期与歌迷们见面。不过，在此之前迈克尔•杰克逊为了此次的演唱会，进行了大量的彩排工作，并亲力亲为的为选曲、编排、舞蹈、灯光等多个环节把关。整个过程，都被详实的记录了下来。没有了现场的演唱会，导演肯尼•奥特加就利用这些排练片段搭配上天王的传世名曲，为全球的乐迷们在大银幕上呈现出了一场完全不一样的演唱会。  这不单单是一部纪录片，这是对这位天皇巨星献上的最后的缅怀……用平凡的片段，展现着巨星真实、超越常人的一面。','Like You\'ve Never Seen Him Before',60000000,0,15.798622,6.7,247,111,'2009-10-28','en','/9Hke7uiaVTPWymZ0YdMquJEke2S.jpg',3.1117174862473598,3,'2026-09-10',2,NULL,NULL),(13579,'远射','The Longshots','The true story of Jasmine Plummer who, at the age of eleven, became the first female to play in Pop Warner football tournament in its 56-year history.',NULL,0,0,4.030724,6.5,11,94,'2008-08-22','en','/mrejNUR8giaAYIJkaLztELRrVXe.jpg',2.3843088651067226,3,'2026-09-10',2,NULL,NULL),(13596,'我最好朋友的女朋友','My Best Friend\'s Girl','开篇用倒叙的手法讲述了汤克（戴恩•库克 Dane Cook 饰）搞砸一次约会的全过程。原来他的工作是帮助被女友甩掉的男人，替他约会前女友并恶心对方。这样女友感念前男友好，容易重归于好。不过，汤克最新接到的任务竟然来自好友达斯汀（贾森•比格斯 Jason Biggs 饰）。后者追女友亚丽克西斯（凯特•哈德森 Kate Hudson 饰）始终不得法，在公司里眼睁睁看着小白脸亲近她，却无计可施。所以，才来找汤克出手。两人约法三章，随后汤克出手，从一起跑步开始，他就成为了亚丽克西斯如影相随的伴侣，两人关系迅速升温，以至于汤克都不敢相信，自己已经离不开这个女友。他觉得困扰，于是向经验丰富的老爸（亚历克•鲍德温 Alec Baldwin 饰）求教，但是后者却鼓励他鸠占鹊巢，这让他感到左右为难…… ©豆瓣','It\'s funny what love can make you do...',20000000,36620508,17.145287,5.4,220,101,'2008-09-19','en','/3Bk4eWlpTyAwwDSybwzGlxtIAXO.jpg',2.9955522984361047,3,'2026-09-10',2,NULL,NULL),(13600,'微光城市','City of Ember','沃尔顿媒体（Walden Media），纳尼亚特效年度巨献，根据Jeanne DuPrau少年奇幻故事《微光城市》（City of Ember）改编的同名影片，由《怪兽屋》（Monster House）导演吉尔·柯南（Gil Kenan）执导此片，汤姆·汉克斯（Tom Hanks）和盖瑞·高兹曼（Gary Goetzman）担任制片。 　　《微光城市》的故事发生在一个黑暗的城市“City of Ember”，那里唯一的照明就是街道上的灯泡。但是最近以来城市停电的次数越来越频繁，民众开始恐慌起来，两个孩子Lina和Doon计划着解开这座城市的秘密从而拯救整个城市，然而却遭到了腐败市长的阻拦。 　　除了比尔·莫瑞外，在《声名狼藉》和《面纱》中有出色表演的托比·琼斯（Toby Jones）也将加盟。影片将于今年夏天在贝尔法斯特开拍，计划2008年10月10日上映。二十世纪福克斯将通过其与沃尔顿组建的“福克斯沃尔顿公司”（Fox Walden）发行该片。','Escape is the only option',55000000,17869048,23.465539,6.2,605,90,'2008-10-07','en','/87pliVHFpQgBohPAOwrYvQu7OH8.jpg',3.290513982976588,3,'2026-09-10',2,NULL,NULL),(13649,'High School Musical 2','High School Musical 2','The East High Wildcats are ready to have the time of their lives. Troy (Zac Efron) is thrilled when he’s offered a job in a country club, but it’s all part of Sharpay’s (Ashley Tisdale) plot to lure him away from Gabriella (Vanessa Hudgens). How will it all turn out? All questions are answered on the night of the club’s Talent Show.',NULL,0,7000000,21.01755,6.1,843,104,'2007-08-17','en','/tyqt4dg69mRgue77aYyXJYXcNEp.jpg',3.342932753260664,3,'2026-09-10',2,NULL,NULL),(13673,'跷家大作战','Christmas with the Kranks','路德·克兰克和他的妻子决定不过圣诞节，拒绝圣诞树和屋顶雪人。家人及邻居对此反应强烈，他们应付得了吗？','No! Ho! Ho!',60000000,0,9.225166,5.2,193,99,'2004-11-24','en','/q866vL3KhAjbkZH1enT7AoxmRHx.jpg',2.941409720333342,3,'2026-09-10',2,NULL,NULL),(13680,'超级杯奶爸','The Game Plan','乔（道恩·强森 Dwayne Johnson 饰）是一名橄榄球运动员，身材强壮又高大的他不仅是队里的主力队员，更是女球迷心目中的完美男人。没有婚姻和家庭的束缚，乔穿梭于欢场与酒吧之间，充分享受着完全自由的单身汉生活，直到一个名叫佩顿（麦迪森·佩蒂丝 Madison Pettis 饰）的小女孩敲响了他的家门。  　　七岁的佩顿自称是乔的女儿，虽然半信半疑，但乔无法拒绝女孩清澈而又充满了希望的眼神，就这样，乔莫名其妙的开始了他的奶爸生涯。面对女儿，毫无经验的乔闹出了不少的笑话，古灵精怪的佩顿也没少给乔惹麻烦，但是，在忙碌的生活间隙，乔逐渐感受到了佩顿带给她的快乐和温馨。一个男人，一个女孩，两人在相处的过程中都迅速成熟起来。','Half his size, twice the trouble ... and she\'s moving in.',22000000,147880543,20.699212,6,428,110,'2007-09-28','en','/dNR9UGHUmsVLOgp04d4yGgAJBMo.jpg',3.1847890945708603,3,'2026-09-10',2,NULL,NULL),(13682,'小熊维尼之长鼻怪大冒险','Pooh\'s Heffalump Movie','故事是关于小熊维尼最怕的“长鼻怪”，在以前的小熊维尼作品中，维尼曾经作过恶梦，梦到“长鼻怪”和“大臭鼠”（其实是大象和黄鼠狼）来偷他的蜂蜜，从此这两个怪物就是他最怕的东西。而在本片当中，百亩森林的动物们居然发现有长鼻怪出没在森林的迹象，于是决定要一同缉捕这只长鼻怪。大家分头行动，行动力十足的小袋鼠小豆居然率先发现这只长鼻怪！没想到居然它是一只迷路的可爱小象，这只可爱过头、一点都不可怕的长鼻怪，会对维尼和他伙伴们的生活带来怎样的影响呢？','There\'s something new in the Hundred Acre Wood.',0,0,9.03154,6.4,88,68,'2005-02-11','en','/5kd5JqccroxOnC9sVMP5NtLrbkr.jpg',2.838400279926942,3,'2026-09-10',2,NULL,NULL),(13685,'瓶装火箭','Bottle Rocket','梦想成为了不起的罪犯的迪格南（欧文•威尔逊 Owen Wilson 饰）找来刚结束了精神病院治疗生活的好友安东尼（卢克•威尔逊 Luke Wilson 饰），以及能够充当司机的大麻爱好者鲍勃（Robert Musgrave 饰）组成了一个仓促上马的犯罪团伙。先用偷窃安东尼家来热身的这伙准罪犯们苦练枪法、设计路线，终于成功打劫了一家书店，兴高采烈进入罪犯行列的迪格南等人驾车逃窜，躲入了一家汽车旅馆，安东尼对旅馆的乌拉圭女服务员一见钟情，而鲍勃却因自己兄弟入狱的消息心神不定。在安东尼和服务员的恋情如火如荼之时，鲍勃丢下二人返家，迪格南和安东尼也终于散伙，各自回归了平静生活。然而迪格南仍然没有放弃犯罪之梦，他向自己的偶像——黑道人物亨利求助……','They\'re not really criminals, but everyone\'s got to have a dream.',7000000,560069,11.700578,6.8,281,91,'1996-02-21','en','/6E7mJ5wpzTFbYFbJvTzzZ8Til9C.jpg',3.1430391535655886,3,'2026-09-10',2,NULL,NULL),(13688,'长江七号','長江七號','小狄是一个在贵族学校念书的穷孩子。他诚实善良，却总是遭到富家子的欺负和嘲笑。小狄和爸爸住在一所废弃的旧房子里，爸爸每天拼命的工作，就是为了让他念好书，将来出人头地。平日，小狄总是很乖，就算体育课因为没有运动鞋而被老师罚站，他也从不埋怨爸爸。可是这一次，为了一个大家都有的玩具，小狄跟爸爸发起脾气来。爸爸买不起，就在垃圾堆里捡了一个“球”给儿子玩。谁知，这个透明的小球却变成一只活泼可爱，拥有超能力的太空狗。小狄欣喜极若狂，给他取名叫“长江七号”。小狄梦想着用七仔的超能力考100分，却没想到七仔非但没有帮到他，却让他得了个零蛋。他偷偷修改了成绩单，跟爸爸说了一次谎。爸爸大怒，小狄离家出走，赌气要凭真本事考好成绩给爸爸看。谁知，正当小狄笑着，拿着成绩单的时候，工地发生事故，爸爸从楼上摔了下来……','It\'s out of this world.',0,47301471,12.373248,6.1,107,86,'2008-01-30','cn','/v8xUyWtRrFmZ5iVEHI0pbQuxHD5.jpg',2.878272757132588,3,'2026-09-10',2,NULL,NULL),(13689,'和平战士','Peaceful Warrior','在比赛中，丹•米尔曼（斯科特•麦克洛维茨 Scott Mechlowicz 饰）完成了一组高难度的吊环动作，却在落地时把左腿摔得粉碎。他猛然惊醒。原来是南柯一梦。凌晨三点，受惊的米尔曼出去散心，意外在加油站结实了一位身怀绝技的老者苏格拉底（尼克•诺特 Nick Nolte 饰），两人成了忘年交。米尔曼外形俊朗，成绩优异，所以总有女孩子围绕身边，然而因为跟好友的女友上床而惹得兄弟反目。另外，他一直希望完成一个高难度动作，却遭到教练的强烈反对，因为后者怕他受伤。由于困扰的时候，他就会来加油站跟苏格拉底交谈。然而一场突如其来的车祸似的米尔曼丧失一切，双脚骨头碎了近100处，他的体操生涯遭到毁灭性打击。病床上的米尔曼这时想起了苏格拉底。在苏格拉底的指引下，米尔曼通过集中全部精神创造了奇迹……','There are no ordinary moments.',0,0,8.326131,7.3,90,120,'2006-03-30','en','/dgfe15NZCyCQFblKfQoK3tqT6f2.jpg',2.871493640497841,3,'2026-09-10',2,NULL,NULL),(13700,'母牛总动员','Home on the Range','三只母牛玛姬、格蕾丝和卡洛维夫人住在同一个农场里，最近，她们都在为自己的生计发愁。因为农场主——一个寡妇无力负担贷款，农场正面临着解散的危机。为了保住自己的安乐窝，三只母牛想出了一个办法，就是合力逮住当地的一名恶名昭著的通缉犯史林，用优厚的奖金挽救农场。一匹曾经是赏金猎人的坐骑的叫布克的马为了证明自己的实力也加入了她们的团队，这下抓捕军团可以说是兵强马壮了。只是，史林还拥有一件他们意想不到的武器，想抓住他真的这么简单吗？','Bust a Moo',110000000,103951461,19.625972,5.7,389,76,'2004-04-02','en','/zvKZWRV8XgXweYM4HLcspTH6Xkk.jpg',3.1310531317717336,3,'2026-09-10',2,NULL,NULL),(13751,'阿基拉和拼字大赛','Akeelah and the Bee','自从五年前父亲去世后，阿基拉·安德森（柯克·帕尔莫 Keke Palmer 饰）慢慢成了“问题女孩”，她逃课，整蛊，总是和母亲坦娅（安吉拉·巴塞特 Angela Bassett 饰）做对，老师也拿她没办法。事实上，已经十一岁的阿基拉所作的一切都来自于她内心的孤独，加之对父亲的怀念，她开始沉溺于拼字游戏，并逐渐发现自己在这种游戏上的天赋。忙于养家、经常忽略阿基拉的母亲对此十分不解，认为她在不务正业、浪费时间，幸而阿基拉得到一位神秘教授（劳伦斯·费斯伯尼 Laurence Fishburne 饰）的支持，并在学校的拼字比赛中一路胜出，还顺利拿到参加全国拼字大赛的机会。天赋加上努力，在一场场拼字比赛中，阿基拉找到了自信和自我，并且遇到一个强劲对手——一个亚裔男孩，两人从互看不顺眼的竞争发展成惺惺相惜…… ©豆瓣','Changing the world... one word at a time.',8000000,18948425,4.932893,6.7,81,112,'2006-04-28','en','/mEkmTQMCsnDSJbLLmLkSkJxISss.jpg',2.8195911723158944,3,'2026-09-10',2,NULL,NULL),(13768,'不老泉','Tuck Everlasting','母亲严厉的管教和无休止的控制欲让少女云妮（阿丽克西斯·布莱德尔 Alexis Bledel 饰）感到痛苦不堪，只有家附近的一片森林才能让她暂时放下忧愁和沮丧。一次偶然中，云妮在森林里结识了名叫杰西（乔纳森·杰克逊 Jonathan Jackson 饰）的男子，意趣相投的两人很快就成为了朋友。在杰西英俊的外表背后隐藏了一个惊人的秘密，他和他的家人因为饮用了带有魔力的泉水而获得了永生不老的特权，可是，这人人艳慕的永生却给杰西一家人带来了永恒的痛苦。不幸的是，发现了这个秘密的并不只有云妮一人，一双邪恶的眼睛正虎视眈眈的盯着无价的魔泉。是为了和杰西永远在一起而饮下魔泉，还是回归到自己原本的生活中去？面对这严酷的问题，云妮必须做出选择。','If you could choose to live forever, would you?',0,0,4.115398,6.4,128,90,'2002-10-11','en','/gjjRyWV5ymJxtUEnffjkA0ADyIx.jpg',2.911363494216969,3,'2026-09-10',2,NULL,NULL),(13776,'餐馆','Diner','1959年，巴尔的摩一家餐馆里，一群二十出头的年轻人在消磨时光，同时盘算着未来该做什么。','Suddenly, life was more than French fries, gravy, and girls.',0,0,5.87193,6.9,83,110,'1982-04-02','en','/2vKIdZ6JkFIzcQeaHg3xtdvOyRO.jpg',2.833497018571433,3,'2026-09-10',2,NULL,NULL),(13778,'过气童星','Dickie Roberts: Former Child Star','迪基曾是70年代的红极一时的电视童星，而今他年方35，一事无成，只落得个代客停车的差事。迪基极度渴望重回往日的聚光灯下，一次他前去试镜，角色要求是一个平凡普通的男人，导演迅即发现，迪基可以是任何人但绝对与“普通”、“平凡”等字眼沾不上边。 　　绝望之中，迪基决定临时组建一个“家庭”来帮助自己将童年时代重来一遍，这次迪基要活得像个普通、正常的孩子那样，迪基分别找来了乔治和格雷斯充当自己的临时父母，而围绕在迪基身边的一帮损友：包括他的经纪人西德尼、和他吵吵闹闹、三天分手两天和好的女朋友辛迪，以及迪基真正的妈妈佩吉都加入了这个拼凑家庭，一场好戏开演了。','50 million people used to watch him on TV. Now he washes their cars.',0,0,10.149569,5.1,64,98,'2003-09-05','en','/eyn1WbZmUUIXU8QoorKWJTQ1iLg.jpg',2.738887937271043,3,'2026-09-10',2,NULL,NULL),(13785,'人狗对对碰','Best in Show','空气中弥漫着竞争的气氛，从全美各地赶来的各种各样的狗以及它们的主人，正迫切地期待着无疑是他们一生中最重要的赛事——“五月花”犬类展览比赛。比赛在“五月花”狗俱乐部的主席西奥多和组委会主席格雷厄姆的注视下有条不紊地进行着。数百条参加比赛的狗聚集在一个巨大的平台上，观众们则围坐在这个庞大的舞台四周。比赛在热烈的气氛中开始了，而摄像机镜头将这个奇妙的狗的世界展现在数百万观众面前。','Some pets deserve a little more respect than others.',0,0,10.982255,6.7,166,90,'2000-09-19','en','/2SqHjWWqfJjQE6zLCbQR9HMla4Q.jpg',3.0029310048481808,3,'2026-09-10',2,NULL,NULL),(13788,'婴灵恶泣','The Unborn','正值花季的美丽女孩凯西（Odette Yustman 欧黛尤斯曼 饰）近来饱受困扰，她经常能看到一名面容阴森如幽灵般的男孩充满憎恨地望着她。凯西求助好友和医生，但都不见效果，不过却从眼科医生那里得知自己可能拥有双胞胎兄弟/姐妹的消息。这一点随后在父亲那里得到证实，凯西通过翻检母亲的遗物找到线索，并拜访了身在养老院的索菲（Jane Alexander 饰）——一个二战时期大屠杀的幸存者。索菲向其讲述了纳粹对集中营中的双胞胎所做的残酷试验。而这一切都与凯西的遭遇有着千丝万缕的关系。\r 　　随着调查的深入，凯西离事实的真相越来越近……','Evil will do anything to live.',16000000,76514050,15.788784,4.8,365,87,'2009-01-09','en','/jNcte4Zzk5TIGgXMVT2vKJPcenL.jpg',3.0201383972342772,3,'2026-09-10',2,NULL,NULL),(13805,'灾难大电影','Disaster Movie','男青年威尔（马特•兰特尔 Matt Lanter 饰）从一场诸多电影情节和明星串联而成的噩梦中惊醒，发现这天正是他梦中显示的世界末日——2008年8月29日。威尔不能确定与女友艾米（凡妮莎•米尼洛 Vanessa Minnillo 饰）的关系，后者愤而离去。为了弥补遗憾，已经25岁的威尔为自己举办甜蜜16岁的生日派对，这场疯狂派对变成了一场无尽恶搞电影的狂欢，所谓乐极生悲，狂欢中的人们突然发现城市已经陷入地动山摇陨石坠落的大灾难之中，混乱中威尔和艾米失散了，为了找回真爱，威尔偕同加尔文与女友、怀孕的朱妮踏上了前往博物馆解救艾米的旅程，一路上绿巨人、钢铁侠等英雄纷纷被灾难击溃，威尔一伙儿也连续击败欲望都市女郎、魔法奇缘王子等人，在这场无厘头电影中向博物馆前进。','Your favorite movies are going to be destroyed.',25000000,14109284,16.238961,3,240,87,'2008-08-29','en','/3J8XKUfhJiNzwobUZVtizXYPe8b.jpg',2.8304704826445017,3,'2026-09-10',2,NULL,NULL),(13807,'放·逐','放‧逐','杀手江贵和（张家辉 饰）为让妻子阿静（何超仪 饰）与孩子安稳生活，决定重返澳门落地生根。然而昔日好兄弟火（黄秋生 饰）与波（林雪 饰）奉大佬大飞（任达华 饰）之命前来杀他，另一对好兄弟泰（吴镇宇 饰）与猫（张耀扬 饰）却为情义出手保护。五人冲突一触即发。念及旧日情谊，四人最终让江贵和为家庭接下最后一宗买卖。\r 乱世中的Liberdade酒店罪恶暗藏，四人随江贵和来到此地，并与老板谢夫（张兆辉 饰）会面。谢夫提出两个选择：一是暗杀澳门大佬蛋卷强（林家栋 饰），二是抢夺一吨黄金。江贵和选择前者，却在行动中丧生。阿静认定火等人为杀夫仇人，誓要追杀到底。\r 宿命安排下，火等四人意外来到抢金地点，在冲突中夺得黄金，并结识神枪手陈警司（任贤齐 饰），众人惺惺相惜。正当一行人准备远走高飞之际，火接到大飞来电，得知阿静与孩子已落入其手中。\r 火四人得知阿静被困酒店，毅然折返，成功救出母子。面对大飞的重重人马，他们早已决心豁出性命，迎战最终对决……',NULL,4500000,0,8.48639,7,46,110,'2006-09-06','cn','/mRDznoR6prQZXeWOsNBe72qMsXB.jpg',2.7050288250623065,3,'2026-09-10',2,NULL,NULL),(13809,'摇滚黑帮','RocknRolla','莱尼（汤姆•威尔金森 Tom Wilkinson 饰）是伦敦黑帮的头目，他手下有个得力干将艾奇（马克•斯特朗 Mark Strong 饰）。莱尼曾经做套逼小流氓头二（杰拉德•巴特勒 Gerard Butler 饰）还债。结果，头二凭借情人史黛拉（桑迪•牛顿 Thandie Newton 饰）提供的情报，成功打劫，抢得巨款，还清了债务，并且一发而不可收拾……　　莱尼买通议员想进军房地产市场。为了重金担保，他从俄罗斯黑帮头目尤里（卡瑞尔•罗登 Karel Roden 饰）手中借来了一副名画。然而，这幅名画却不翼而飞。于是，一群人卷入了这场寻找名画的闹剧中，其中不乏有莱尼失散多年的儿子，盗卖皮草的毛贼，打不死的保镖，同性恋的律师等等。最后，在名画事件水落石出之时，黑帮最大告密者的身份也被揭穿……','A story of sex, thugs and rock \'n roll.',18000000,25739015,31.887978,6.9,836,114,'2008-09-04','en','/hL2j3IgayhBXWVy6fb0atCCYaDa.jpg',3.494213453963624,3,'2026-09-10',2,NULL,NULL),(13811,'神秘代码','Knowing','1959年，美国马塞诸塞州列辛顿威廉道斯小学，该校即将迎来校庆日，小女孩露辛达•安伯利（Lara Robinson 饰）提出的创意为校长所采纳。校庆日时，学生们将画下自己对未来的设想，并集中放入金属时间囊中埋入地下，准备50年后重新开启。校庆日之后，举止怪异的露辛达用鲜血在墙上写下奇怪文字，并向老师提出警告。2009年，威廉道斯小学再次迎来校庆日，被埋藏地下50年之久的时间囊重见天日。小男孩凯勒（Chandler Canterbury 饰）得到露辛达的信，上面没有任何图画，整页布满毫无规律可言的数字。凯勒的父亲约翰（尼古拉斯•凯奇 Nicolas Cage 饰）夜晚研究这些数字，竟发现这是一组具有预言性的密码。文中的数字清楚记录了世界上过去50年所发生的各种灾难。除此之外，这组数字还包括了接下来将发生的重大灾难……','Knowing is everything...',50000000,155446362,32.693093,5.9,1486,121,'2009-03-19','en','/oL8faEuALmzTHMJTnWUz6rh55fX.jpg',3.4518139706766826,3,'2026-09-10',2,NULL,NULL),(13812,'隔离区','Quarantine','电视台女主播安吉拉（珍妮弗•卡彭特 Jennifer Carpenter 饰）第一次出镜有些紧张，因为她要参加一个在洛杉矶某消防局与队员共度夜晚的节目。安吉拉性格热情开朗，所以逐渐融入了这个团队，她不但了解了每个人的个性，而且还迅速成为了他们的开心果。然而，突然接到911的报警电话，安吉拉随这群消防队员来到了出事地点。在这座阴森可怖的大楼里，不时传出女人凄厉的尖叫，当地警方已经封锁了大楼，消防队员试图疏散被困人群，却无意中身陷困境。在隔离的区域，一个女人不知感染什么病毒，残忍地伤害了许多人。眼看着消防队员惨遭不幸，自身难保的安吉拉被逼上了绝路……','Contain The Truth.',12000000,40855419,8.083995,5.5,339,89,'2008-10-10','en','/meIphDV4CGvW44EqzqRYEjiWv8x.jpg',3.0596207290793584,3,'2026-09-10',2,NULL,NULL),(13816,'黑磨坊','Idlewild','故事萌发的前传是1998年刚凭专辑“Aquemini”声名鹊起的OUTKAST产生制作与专辑同系列的电影，MTV认可了这个创意但要拿当时名气更大的Missy Elliott 和Busta Rhymes代替OUTKAST出演。自己的电影作了人家嫁衣两兄弟士气遭到打击。随后他们再构思的《爱德怀德》，终于在两人如日中天的时候面世了。\r 布莱恩·巴伯撰写这个故事的初衷是为了在被饶舌和街舞塞满脑子的年轻人心中培养他们对爵士时代的感情，让他们知道嬉哈、R&B是怎么从威灵顿公爵、Cab Calloway这些天才的作品衍生出来的；OUTKAST推动了嬉哈音乐的发展，自然也要担负起教育年轻人娱乐不忘本的责任，影片也瞄准了OUTKAST的广大粉丝，而为了在教育前先把目标观众抓在手中，OUTKAST同时担任影片音乐监制，亲自操刀所有曲目创作乃至编排，也正因为二人在音乐水准上精益求精，影片才一再修改背景音乐而姗姗来迟。\r OUTKAST的90分钟MTV',NULL,0,0,2.711955,5.1,17,121,'2006-08-25','en','/d1KW3hrGAJCsvs2GC2MCkYebD2u.jpg',2.4606853318983264,3,'2026-09-10',2,NULL,NULL),(13820,'追讨者','Repo Man','作为1980年代最纯粹的邪典经典之一，亚历克斯·考克斯这部独树一帜的科幻喜剧中，永远迷人的哈里·迪恩·斯坦顿饰演洛杉矶荒凉街区里饱经风霜的追讨者，艾米利奥·艾斯特维兹饰演他收留的虚无主义中产朋克青年。当两人卷入追讨一辆带有高额悬赏的神秘超现实雪佛兰马利布时，这份工作远超预期。影片以八十年代初洛杉矶朋克乐巅峰原声为底色，这部脏兮兮的荒诞奥德赛，亦是对里根总统内外政策的尖锐政治讽喻。[标准收藏]','It’s 4 a.m. Do you know where your car is?',1500000,2300000,11.35344,6.7,144,92,'1984-02-20','en','/bjuu5UceuVUNUjnOC2fBzL3hZKC.jpg',2.969485678763865,3,'2026-09-10',2,NULL,NULL),(13824,'Superstar','Superstar','Orphan Mary Katherine Gallagher, an ugly duckling at St. Monica High School, has a dream: to be kissed soulfully. She decides she can realize this dream if she becomes a superstar, so her prayers, her fantasies, and her conversations with her only friend focus on achieving super-stardom.','Dare to dream.',0,0,4.04701,5.1,83,81,'1999-10-08','en','/vfBUCPe6wgt3SwNP7dKlqh8xeyO.jpg',2.7740927496062002,3,'2026-09-10',2,NULL,NULL),(13827,'冲浪高手','Surfer, Dude','A wave twisting tale of a soul searching surfer experiencing an existential crisis.',NULL,6000000,69497,2.404626,4.7,25,85,'2008-09-05','en','/948AdP72iLQUjWvKp9r8981PT28.jpg',2.53269993497131,3,'2026-09-10',2,NULL,NULL),(13836,'魔鬼山历险记','Race to Witch Mountain','许多年以来，美国的内华达大沙漠一直是个 \"神秘\" 的地方，各种各样奇怪的现象层出不穷。有人说，这是因为外星人的飞船曾在巫山（Witch Mountain）降落。  　　杰克（道恩·强森 Dwayne Johnson 饰）是一个拉斯维加斯的普通出租车司机，有一天他在车上发现了一对神秘的兄妹俩。从伸出援手的那一刻开始，他就卷入了一场令人惊心动魄的冒险旅程。原来，这对拥有异能的兄妹来自外星，且还隐藏了不为人知，却足以使整个宇宙毁灭的秘密。兄妹两人必须在现有的时间内找到失踪的太空船，返回外星。这趟旅程是场生与死的追逐，他们必须躲过来自各方的追杀，包括黑道，美国政府以及外星人。时间正式倒数，宇宙毁灭在即。一个攸关全宇宙及人类生死的冒险正在进行','The race is on',50000000,106303988,23.935053,5.5,509,98,'2009-03-12','en','/mmAqbe5HAm8YyAgg6ryJ7tQCCYt.jpg',3.1666434829257613,3,'2026-09-10',2,NULL,NULL),(13849,'农家小屋','The Cottage','戴维（Andy Serkis 饰）和皮特（Reece Shearsmith 饰）是两个一事无成还笑话百出的小人物，这两个穷极生疯的家伙绑架了某黑帮老大的女儿崔茜（Jennifer Ellison 饰），并开口索要10万英镑赎金。然而黑帮老大也不是好对付的，更何况面对的是两个什么都不会的新手。不久，曾参与策划绑架的崔茜的弟弟安德鲁（Steven O\'Donnell 饰）连同两名华裔杀手赶到戴维他们的藏身地点。一来二去，形势陡然逆转，安德鲁被打晕，戴维和皮特反而成了崔茜的人质。\r 　　崔茜到附近农庄打电话求救，然而才出龙潭，又入虎穴。一个更为恐怖的对手向这群人慢慢逼近……','Sleeps Six Bloody Comfortably',0,0,8.39685,6.3,80,92,'2008-02-07','en','/fFmU7cQAWVAeBpSfDRRauKgtKDD.jpg',2.8127680898024106,3,'2026-09-10',2,NULL,NULL),(13853,'熊族之旅','The Clan of the Cave Bear','Natural changes have the clans moving. Iza, medicine woman of the \"Clan of the Cave Bear\" finds little Ayla from the \"others\"\' clan - tradition would have the clan kill Ayla immediately, but Iza insists on keeping her. When the little one finds a most needed new cave, she\'s allowed to stay - and thrive.','At The Dawn Of Mankind, A Woman Led The Way.',15000000,0,5.484679,4.8,27,98,'1986-01-17','en','/jbftdduVujKeoib5fwDBbEMamdj.jpg',2.555815225975843,3,'2026-09-10',2,NULL,NULL),(13856,'Special','Special','A lonely metermaid has a psychotic reaction to his medication and becomes convinced he\'s a superhero. A very select group of people in life are truly gifted. Special is a movie about everyone else.',NULL,1000000,7202,1.260314,6.6,32,81,'2006-01-30','en','/5oGxZ9Itu8buWnB15p6sri3zh9n.jpg',2.602071207205925,3,'2026-09-10',2,NULL,NULL),(13888,'重回蓝色珊瑚礁','Return to the Blue Lagoon','《蓝色珊瑚礁》的重拍之作：理查和莉莉在还是小婴孩的时候发生了船难，只有他们俩和一个寡妇倖存，他们一起漂流到了一个无人岛上，被寡妇抚养长大成人，长大后的小男孩小女孩对彼此产生了感情，并约定要互许终生，后来终于有艘船来到了无人岛上发现了他们，船长的女儿见到理查便爱上了他，并且企图把理查由莉莉的身边夺走……','Return to the Romance, Return to the Adventure...',11000000,2807854,9.705589,5.1,153,98,'1991-08-02','en','/jhUTLuPgc3Qcvr5xtji8oiWSfYy.jpg',2.896981221208509,3,'2026-09-10',2,NULL,NULL),(13889,'袅袅夕阳情','まあだだよ','充满生命情趣的教师内田百闲毅然辞去大学教书职务，从事写作工作。六十一岁开始，学生每年都为他筹备生日大会，每年学生都开玩笑问道：「你准备好没有呀？」(Mahda-kai) 他一口气饮尽为他而设的大杯啤酒，之后总是说一句：「还没呀！」(Madadayo) ……  　　1943年，百闲先生从大学退职后呆在家中一心从事写作。这个家“小偷很容易进来”，是以房租便宜，聚集了高山、甘木、桐山、泽村等弟子。澡堂的门是半开的，立着“小偷入口”的牌子，还有“小偷通道”，“小偷休息室”里甚至摆放了烟灰盆。每一个小偷看到了都会大吃一惊。空袭中这座房子被毁，百闲先生和夫人搬进了一个只有三铺席大小的门房，终日与猫为伍，过着悠然自在的生活。战后，弟子们创立了“摩阿陀会”。“摩阿陀会”是“好了吗？还没有呐”的谐音。弟子们每年都为先生的生日召开大会，在第17届会上，头发花白的先生这样问弟子们：“人生中最重要的是什么？”那天晚上，先生做了一个梦，好些孩子们在朝他呼唤：“好了吗？”',NULL,0,0,2.930853,7.5,20,134,'1993-04-17','ja',NULL,2.51270909139914,3,'2026-09-10',2,NULL,NULL),(13898,'生命的圆圈','دایره','本片交织讲述了七位伊朗女性的故事，她们每个人都因社会偏见与压迫性法律而背负着犯罪过往。',NULL,0,0,1.193779,6.6,17,90,'2000-09-08','fa',NULL,2.467480047005414,3,'2026-09-10',2,NULL,NULL),(13908,'The Master of Disguise','The Master of Disguise','A sweet-natured Italian waiter named Pistachio Disguisey at his father Fabbrizio\'s restaurant, who happens to be a member of a family with supernatural skills of disguise. But moments later the patriarch of the Disguisey family is kidnapped Fabbrizio\'s former arch-enemy, Devlin Bowman, a criminal mastermind in an attempt to steal the world\'s most precious treasures from around the world. And it\'s up to Pistachio to track down Bowman and save his family before Bowman kills them!','He can get into any disguise... getting out is another story.',0,0,4.382761,3.7,78,80,'2002-08-02','en','/JFKuKJeHHFFVb0ubpkPIXmkIOg.jpg',2.7226009438122767,3,'2026-09-10',2,NULL,NULL),(13909,'黄巾骑兵队','She Wore a Yellow Ribbon','临近退休的内森·布里特尔斯上尉奉命率队执行最后一次巡逻，以期阻止一场迫在眉睫的大规模印第安部落袭击。然而随行的妇孺撤离任务使得队伍行动迟缓，布里特尔斯的使命由此面临危机。','John Ford\'s New and Finest Picture of the Fighting Cavalry!',1600000,5400000,8.535178,7.1,61,103,'1949-10-22','en','/2IXtuwkTVcDsaa09AiQnlkfxe7I.jpg',2.772363259482794,3,'2026-09-10',2,NULL,NULL),(13919,'我行我素','The Chumscrubber','一次偶然中，迪恩（杰米·贝尔 Jamie Bell 饰）发现了好友特里（Josh Janowicz 饰）的尸体，死因为自杀。迪恩并没有将这件事情告诉他人。原来，特里是学校中的一名贩毒头目，随着他的死亡，他所控制的一大批毒品下落不明，如何搞到这批毒品并借此获利才是迪恩真正感兴趣的事情。\r 为了得知毒品的下落，迪恩计划绑架特里的弟弟查瑞（格伦·克洛斯 Glenn Close 饰），没想到，最后他们绑架来的居然是和查瑞有着相似名字的查理（罗瑞·卡尔金 Rory Culkin 饰），这一严重的错误彻底搅乱了迪恩的计划，更糟糕的是，对于儿子的失踪，查理的母亲竟然毫无察觉。市长麦克（拉尔夫·费因斯 Ralph Fiennes 饰）的遭袭让小镇上蛰伏已久的问题彻底的暴露了出来，人们终于发现，原来平静安宁的生活不过是虚有其表。','Fear. Trust. Love.',0,0,3.528643,6.7,62,108,'2005-06-08','en','/uMb26IjDgdq8p4H3XNO1CAsjT4m.jpg',2.7553349818058086,3,'2026-09-10',2,NULL,NULL),(13920,'真情电波','Radio','有着先天性智障的詹姆斯（小库珀·古丁 Cuba Gooding Jr. 饰）从小到大都是众人嘲笑的对象，由于他总带着一个收音机，“收音机”就成为了他的代号。没事的时候，詹姆斯喜欢呆在汉娜高中体育场，久而久之，一个名叫哈罗德（艾德·哈里斯 Ed Harris 饰）的教练注意到了他。\r 在又一次被人捉弄后，哈罗德帮詹姆斯解了围，不仅如此，他还当众宣布，从此往后，詹姆斯将会是他的橄榄球队中的一员。哈罗德的这个决定让队员们十分不解，但很快，他们就发现了詹姆斯身上所闪耀着的人性光辉。在詹姆斯乐观情绪的影响下，球队屡战屡胜，队员之间的关系也更加紧密，詹姆斯不仅走出了生命中的灰暗地带，还将快乐和希望带给了更多的人。','His courage made them champions.',32000000,52277485,9.254647,6.8,141,109,'2003-10-24','en','/uQ6ci4iFHhB6TWB2f4wftR7AEly.jpg',2.9645093645751825,3,'2026-09-10',2,NULL,NULL),(13922,'大偷袭','The Great Raid','太平洋战争初期，美军将兵力投入欧洲战场，无力挽回菲律宾战事，导致一万名美军、六万名菲军在巴丹半岛被俘。日军一直残酷对待这些战俘，军部更于1944年一月决定屠杀俘虏，这部电影，讲述的就是发生在44年一月四天中的故事。  　　游骑兵上尉普林斯分属幕西中校的队伍，他们接受了在麦克阿瑟将军北上过程中营救某战俘营里500名美军的任务，由于日军对待战俘毫不留情，此次行动必须高度隐秘。同一时间，战俘营中的少校吉布森（约瑟夫•费因斯 Joseph Fiennes 饰）正艰难的为生存和获取外界信息而努力，虽然当地有护士玛格丽特等人想法设法为战俘提供帮助，但缺药的状况一直存在。为执行屠杀命令，宪兵军官长井接管了战俘营，而战俘营外，游骑兵战士们经过秘密行军终于抵达了目的地，营救成败，很快就要揭晓……','The most daring rescue mission of our time is a story that has never been told',80000000,10166502,8.923215,6.8,91,132,'2005-08-12','en','/8Jnc9auL5BAqyLUFgBGrx5tiy50.jpg',2.8589597119988643,3,'2026-09-10',2,NULL,NULL),(13937,'危情羔羊','Raising Cain','卡特是一名儿童心理学家，他在自己女儿的房间里装了许多摄影机，用以观察儿童在平日里的一举一动。卡特的老婆詹妮，对他这种过分关注的行为有些担心，但她正在搞婚外恋，因此忽略了做母亲的责任，也就任由卡特去了。然而没过多久，当地发生了一连串儿童绑架事件，詹妮开始怀疑也许与丈夫有关，后者似乎正在进行一种心灵控制的试验。而詹妮不知道的是，卡特有着多重人格，知晓詹妮外遇的他，正打算对其大开杀戒……','Demented. Deranged. Deceptive. De Palma.',12000000,37170057,7.558959,5.9,65,91,'1992-08-07','en','/5vRn138vnZeUNFe32qTuPGKkVLR.jpg',2.755595274388296,3,'2026-09-10',2,NULL,NULL),(13938,'龙拳小子','The Last Dragon','影片设定在纽约市，故事围绕着一位名叫Leroy Green的有理想有抱负的青年武术家展开，他渴望像李小龙那样达到武术的最高境界，并希望得到名为“圣光”(The Glow)的神秘力量。在他成为“最后的猛龙”(The Last Dragon)的道路中，还必须勇敢面对邪恶的Sho’nuff等敌人的挑战。','His family thinks he\'s crazy. His enemies think he\'s no challenge. But she knows he\'s THE LAST DRAGON.',10000000,25754284,4.928777,6.4,69,108,'1985-03-22','en','/r5QnLY30gXlZ8luiJE3quDs1WNF.jpg',2.7750499336383356,3,'2026-09-10',2,NULL,NULL),(13948,'美国颂歌','An American Carol','肥胖邋遢的左翼导演迈克?马隆（Kevin P. Farley 饰）致力于揭露美国政治、军事、经济和医疗等方面的阴暗面，他所拍摄的纪录片更在国际上获奖（影射迈克?摩尔）。他为自己的成就沾沾自喜，美国国内也有一批狂热的粉丝对他疯狂追捧。有些飘飘然的马隆更提议取消7月4日的独立日，他甚至大张旗鼓搞起了宣传活动。\r 　　这时候，三个美国历史上重要人物的鬼魂：肯尼迪（Chriss Anglin 饰）、华盛顿（Jon Voight 饰）和巴顿（Kelsey Grammer 饰）先后拜访了马隆。他们一次次将马隆带入假定的历史中，向其展示纵容绝对民主和恐怖主义可能产生的各种后果。曾经坚定的左翼分子终于开始动摇了……','Laugh like you\'re country depends on it.',20000000,7000000,2.605374,4.1,20,83,'2008-10-03','en','/uEDdzt1ZTB1BRo95gMkBytl0NqM.jpg',2.48470858894215,3,'2026-09-10',2,NULL,NULL),(13950,'一切为了钱','All About the Benjamins','布坎曾经是个受同侪排挤的员警，做事不像别的员警一样循规蹈矩。于是布坎辞职做了赏金猎人，为攒钱开一家自己的私人侦探社而奋斗。这个目标十分遥远，因为布坎每天捉来捉去，捉的都是些不值钱的小贼。\r 　　有一天他在追捕异常滑溜的小贼雷吉，雷吉躲进了一辆汽车的后备箱，车子的主人却是一帮珠宝大盗，他们刚刚杀人越货，抢来一批价值两千万的钻石，却发现这些钻石是假的。\r 　　雷吉躲开大盗们逃回家，他的女朋友告诉他他们买的彩票中了六千万大奖。可是，雷吉的彩票却跟钱包一起落在了强盗们手里。幸好，这时布坎上门来抓人，雷吉理直气壮地要雇用布坎去抢回彩票。布坎考虑一番之后，同意了。不过他心里另有算盘：如果雷吉的话是假的，他就用雷吉作诱饵抓住强盗们换取奖金。','Money can make people do funny things.',14000000,25482931,5.102258,5.8,48,95,'2002-03-08','en','/sO7IpJHjZBGLevi8Ozj9EsAUw5h.jpg',2.6847372298487464,3,'2026-09-10',2,NULL,NULL),(13960,'新美国故事','ATL','亚特兰大南部的贫民区里，生活着17岁的黑人拉沙德（提普·哈里斯Tip Harris饰）和他14岁的弟弟安特（伊万·洛斯Evan Ross Naess饰）。拉沙德像很多黑人孩子一样，热衷溜旱冰、HIP-HOP音乐，青春似乎可以无忧无虑；然而现实却是非常残酷的，他的父母已经双亡，照顾弟弟成长，为弟弟赚够学费的重担，就落在了拉沙德身上。偏偏安特又任性不羁，这令拉沙德的状况雪上加霜。  女孩妞妞（劳伦·兰顿Lauren London 饰）的出现让拉沙德堕入了爱河，这个女孩的身世却有着不为人知的秘密——她的父亲，正是当地富商约翰（凯斯·大卫 Keith David 饰）。约翰虽是贫苦出身，却在发迹后禁止女儿和贫民来往，这令妞妞每次约会都要隐瞒身份。当拉沙德得知这个秘密，他感到分外的失望，无论是爱情，还是亲情，都令他感到力不从心。','A New American Story',20000000,21170563,5.422285,6,32,105,'2006-03-31','en','/wi9VRukGburXfDwDKqcQQdgFK5S.jpg',2.604003310026816,3,'2026-09-10',2,NULL,NULL),(13963,'最后华尔兹','The Last Waltz','这不仅仅是一部史上最伟大的音乐会电影，本片更是一次对美国摇滚乐黄金时代既狂热又深怀悼意的总结。1976年感恩节，马丁·斯科塞斯受邀记录传奇乐队“乐队”在旧金山冬季宫舞厅的告别演出，由此构思出一种全新的音乐纪录片形式。他集结了七位摄影师（由摄影指导迈克尔·查普曼领衔，还包括著名电影摄影师维尔莫斯·日格蒙德与拉兹洛·科瓦奇），并邀请美术指导鲍里斯·莱文设计极具戏剧张力的舞台布景，斯科塞斯打造出一场宏大而沉浸的体验，将观众带上舞台，引入音乐的内核之中。那些由“乐队”与一众定义时代的艺术家——包括鲍勃·迪伦、琼尼·米歇尔、范·莫里森、斯泰普尔合唱团、马迪·沃特斯及尼尔·杨——所演绎的音乐，至今依然回响，宛如对摇滚乐超越性可能的一种近乎信仰的宣示。','It Started as a Concert. It Became a Celebration.',0,321952,3.277287,7.9,64,117,'1978-05-01','en','/2K7CFH0AIHnGrA4yQjPCoIB5CmQ.jpg',2.7910322150401026,3,'2026-09-10',2,NULL,NULL),(13967,'波特小姐','Miss Potter','影片的时间背景是维多利亚女王与爱德华七世时代末期的英格兰，一个酷热的夏天。此时，波特女士已经逐步地显示出了她在写作方面迥异的天赋，许多人都认为她有着当一名艺术家的潜质。当她的第一部作品《彼得兔的故事》正式出版之后，波特女士成为了倍受欢迎的著名作家。事业成功之后，爱情也向波特女士走来。她的第一段爱情便是同由伊万·麦克格雷格饰演的出版商诺曼·韦恩之间的，他们之间的恋情，以及诺曼·韦恩于1905年7月的求婚，永远地改变了比阿特丽克斯的生活。\r 对于这段恋情，波特女士却无法向公众宣布，甚至不能谈及有关的事情。在伦敦的上流社会中，波特的父母坚持她应该找一个同她的身份地位都相配的人做她的终生伴侣，并且他们认为波特同韦恩在一起就是一个错误。他们认为韦恩只不过是个做小买卖的，他们要求波特重新考虑同韦恩在一起的这个决定。最终，比阿特丽克斯终于屈服了，放弃了这段感情，在家人的劝说下，她离开了伦敦，离开了她的未婚夫。在这段时间中，波特经历了痛苦和孤独，变得十分的沉寂。但是，经过了长时间的精神磨练，彻底的改变了波特的观念，她又以新的态度来勇敢地面对生活。她搬到了坎布里亚郡的湖区，这里拥有险峻的山峰和16个波光粼粼的湖泊，举世无双的美景激发了波特的灵感，她在这里生活、创作，一直到1930年。波特创作了多部优秀的童话作品，是一个超越时代的女性。即便是波特成为了世界上最成功的儿童作品创作者和富有的农场主，她也从来都没有忘记过她的第一段爱情。','The life of Beatrix Potter is the most enchanting tale of all.',30000000,35078241,8.386432,6.3,141,92,'2006-12-03','en','/en7qDtmANqvAq1iEViMYOJhv7UH.jpg',2.938199918481344,3,'2026-09-10',2,NULL,NULL),(13972,'女人们','The Women','玛丽·海恩斯（梅格·瑞恩 Meg Ryan 饰）住在纽约曼哈顿区，是小有成就的服装设计师，她还有英俊且事业有成的老公，乖巧可爱的女儿，一家人住在豪华别墅，在任何人眼中都是艳羡对象。在玛丽身边，围绕着一群多年死党，包括独立的时尚杂志撰稿人西尔维娅·福勒（安妮特·贝宁 Annette Bening 饰）、有点唠叨的艾迪·科恩（戴博拉·麦辛 Debra Messing 饰）和性感的散文家亚历克斯·费舍尔（贾达·平克特·史密斯 Jada Pinkett Smith 饰）。但是看似完美的生活被一个意外发现打破，玛丽老公出轨了，对象是外形完美的香水专柜小姐克瑞斯托·艾伦（伊娃·门德斯 Eva Mendes 饰），玛丽寻求好友们帮助，没想到却遭到西尔维娅的背叛……',NULL,16000000,50007546,8.8321,4.6,96,114,'2008-09-12','en','/wuAh1MLMdjYNGuLwfzJjEj0nwA3.jpg',2.7945022547327336,3,'2026-09-10',2,NULL,NULL),(13973,'窒色','Choke','为了给母亲艾达（安杰丽卡·休斯顿 Anjelica Huston 饰）治病，维克托（山姆·洛克威尔 Sam Rockwell 饰）想出了一个损招，在高级餐厅里，他做出被食物噎住的假象，以此赚取他人的同情。可即便是这样，维克托依然无法负担母亲高额的治疗费用，此时，一个名叫佩吉（凯莉·麦克唐纳 Kelly Macdonald 饰）女人找到了他。佩吉自称是负责照顾艾达的护士，她告诉维克托，有一种新兴的治疗方式可以治愈艾达的病痛，可这种疗法需要维克托提供含有他基因的新生儿脐带血，让维克托震惊的是，佩吉竟然提出愿意为此而怀上维克托的孩子。没想到，维克托的无法勃起让这个看似天衣无缝的计划遭遇了失败，与此同时，艾达和佩吉各自隐藏的秘密也逐渐的浮出了水面……','From the author of Fight Club',3000000,3830137,11.637458,6,127,92,'2008-09-26','en','/ta78cOyGnjbR5EQQvfKNWoiNGAn.jpg',2.9089541705225606,3,'2026-09-10',2,NULL,NULL),(13982,'一个布袋八个头','8 Heads in a Duffel Bag','一次行动，杀手集团一口气干掉8名黑帮人物。买命人要求亲眼看到该8个死人头才肯付钱，集团唯有派出金牌刽子手汤美(祖柏斯饰)，来一次金盘洗手前的最后任务－－就是要运送新鲜热辣的人头去见大佬。为了掩人耳目，汤美将8个人头塞满入一个最最普通的蓝色帆布旅行袋……','A mindless comedy.',0,0,5.016607,5.4,39,95,'1997-04-18','en','/dbjS5UH7JvsQwSLMYMY5GQOSwv1.jpg',2.635407103866621,3,'2026-09-10',2,NULL,NULL),(13983,'Finishing The Game','Finishing The Game','In 1973, martial arts great Bruce Lee died, his final film, Game of Death, left unfinished. With the public hungry for more Lee, movie execs decide to find a replacement. This outrageous satire looks at the entire process, from the oddball candidates to the greed and racial motivations that drive the final decision. There\'s big business in the movies, and Finishing the Game skewers it with an eye for \'70s detail.',NULL,0,0,0.459625,4.9,8,84,'2007-01-21','en','/9UwmkpujGoJhgL4Krnm6Fy0IyxD.jpg',2.3080016684728184,3,'2026-09-10',2,NULL,NULL),(13990,'古怪因子','The Wackness','故事发生在1994年的纽约，和大多数叛逆青年一样，卢克（乔希·佩克 Josh Peck 饰）和家人之间的关系跌落到了冰点，终日无所事事的他整日在街头徘徊，靠着贩卖大麻赚点零花钱。和大多数心理医生一样，斯奎尔斯（本·金斯利 Ben Kingsley 饰）自己也有一大堆剪不断理还乱的麻烦事，他和卢克之间唯一的枢纽就是大麻——斯奎尔为卢克提供心理诊疗，而卢克则用大麻来回报他。同是江湖沦落人，随着时间的推移，卢克和斯奎尔斯之间产生了一种奇妙的信任和友谊。\r 　　卢克一直暗恋着同班同学斯蒂芬妮（奥莉薇·瑟尔比 Olivia Thirlby 饰），同时，外表开朗乐观的斯蒂芬妮也对卢克情有独钟。令卢克没有想到的是，斯蒂芬妮那没有血缘关系的父亲不是别人，正是他的“老主顾”斯奎尔斯，一段有笑有泪的混乱关系就此展开。',NULL,6000000,2899975,7.161051,6.2,94,99,'2008-07-03','en','/gmtlqHZs8YBXcpMw4BgA3SGJfg8.jpg',2.8419979900935988,3,'2026-09-10',2,NULL,NULL),(13991,'大学预备生','College','三个即将毕业的高中男生决定造访当地大学，表面是为了考察校园提前做好准备，实际上却期待着周末狂欢尽情玩乐。不料刚到校园，一行人就被几个大学兄弟会的成员盯上。兄弟会准备“好好招呼”他们，拿他们取乐。可这帮高中生们很快吸引了女生联谊会里美女们的目光，如此一来兄弟会大哥们被气得够呛。除了想方设法羞辱三个傻小子，他们更威胁要曝光这帮高中生的真实年龄，主人公们要如何应对呢？',NULL,7000000,6230276,7.034618,4.8,48,94,'2008-08-28','en','/lY2AHNzHEtlWLisRj0ezSRmnDAt.jpg',2.6706047053357116,3,'2026-09-10',2,NULL,NULL),(13994,'爱情和香烟','Romance & Cigarettes','桥梁建筑工人尼克•莫德（James Gandolfini 饰）人过中年，对现有一成不变且枯燥乏味的生活逐渐感到厌倦。性感奔放的红发女郎图拉（Kate Winslet 凯特•温斯莱特 饰）适时闯入尼克的世界，他的激情被重新点燃，并疯狂迷恋上这个令人捉摸不定的尤物。尼克的妻子凯蒂（Susan Sarandon 饰）是个坚忍的贤妻良母，她靠剪裁衣服贴补家用，还要照顾丈夫和三个叛逆的女儿。尼克的出轨令凯蒂大为失望，随之而来的争吵更将他们的婚姻推向破裂的边缘。兜兜转转，走走停停，在露水姻缘消逝无踪之际，尼克才幡然醒悟，怀念起家的温暖……',NULL,0,2945242,4.056774,6,33,105,'2005-09-13','en','/phSntD46jD5IfYAa2lSoU6xJDJ6.jpg',2.607324202798047,3,'2026-09-10',2,NULL,NULL),(13996,'酒业风云','Bottle Shock','吉姆（比尔·普尔曼 Bill Pullman 饰）和阿博（克里斯·派恩 Chris Pine 饰）是性格迥异的父子两，尽管生活中两人常常因为意见不合而大动干戈，但也因此碰撞出了许多智慧的火花。吉姆和阿博想要酿造一种名为“莎当妮”的葡萄酒，以此同法国南部的酿造者们抗衡。  史蒂芬（阿伦·瑞克曼 Alan Rickman 饰）是一名酒商，为了挽救自己岌岌可危的酒庄，他四处游历，寻访美酒。史蒂芬发现了阿博酿造的莎当妮，决心将它“收入麾下”，然而他傲慢的态度却惹恼了吉姆。背着父亲，阿博将两支莎当妮送往了史蒂芬的品酒会，与此同时，吉姆震惊的发现自己酿的就竟然变色了，这也就意味着，他现在所拥有的一切，不过是一坛坛一文不值的酸水，绝望之中吉姆决定将这些酒全部销毁。','Based on a true story of love, victory, and fermentation',5000000,4040588,6.174435,6.6,60,110,'2008-08-06','en','/3Y6E1iHlfS588TASj3cfi2BoApm.jpg',2.7516781710050533,3,'2026-09-10',2,NULL,NULL),(14012,'真爱无缰','Flicka','在16岁的这一年，凯蒂（艾莉森·洛曼 Alison Lohman 饰）站在了人生的十字路口上，是继续学业还是回归自己心爱的农场？崇尚自由的凯蒂选择了后者。对于罗布（蒂姆·麦格罗 Tim McGraw 饰）来说，女儿的回归带来的并不是喜悦，一方面，农场的经营境况与日俱下，无法承担高额支出的他早已萌生了放弃的念头，另一方面，他并不希望女儿向自己一样，一生都锁定在一块土地上，很显然，走出农场，走上社会是更好的选择。  　　一匹野马的出现给凯蒂一家人带来了别样的乐趣，凯蒂给它取名“弗利卡”。弗利卡是个脾气火爆的姑娘，生性放浪的它讨厌束缚，这使得凯蒂想将它训练成一匹赛马的愿望无法实现。随着弗利卡的长大，罗布决定将其卖掉，对于父亲的决定，凯蒂无法接受。',NULL,15000000,21000000,3.043589,6.1,52,95,'2006-10-20','en','/nhJlXSmiHnlVxea5J5l3wfuATwY.jpg',2.702620456358137,3,'2026-09-10',2,NULL,NULL),(14014,'重锤','The Hammer','杰瑞（亚当·卡罗拉 Adam Carolla 饰）曾是一位人人看好前途无量的青年拳击手，人称“重锤出击”，然而，他的职业路线并没有像他想象中那样顺利的发展，如今，40岁的他以教练的身份在一间拳击馆教课，他的学生们都是已经发福的中年男人。\r 这一天，教练艾迪（Antonio Caballero 饰）喊来了杰瑞，让他和职业拳坛冉冉升起的新星布莱克（Jeff Lacy 饰）比试比试，本以为一定会挨揍的杰瑞，一拳就把身强体壮的布莱克给打倒了。这场意外让杰瑞开始考虑是否应该重新回归拳坛，可在此之前，他已经过着闲散的生活过了20年了，以这样的状态去追逐奥运会金牌，现实吗？','Some Guys Don\'t Know Their Destiny Till It Hits Them In The Face.',0,0,0.957022,6.5,15,88,'2007-04-01','en','/6Q7z71vQD7Rl8ehdlFu5qfmvenv.jpg',2.4403732955941093,3,'2026-09-10',2,NULL,NULL),(14022,'都市浪人','Slacker','影片开始是一个年轻人（理查德·林克莱特 Richard Linklater 饰）在的士上向司机叙述他的一个古怪的梦，还有他搭上这辆的士的可能性，然而司机毫不在意。年轻人下了车，目睹一个女人出了车祸躺在地上，他拿走了女人的手提包。女人是被她的儿子撞死的，两个警察把儿子从家里带走。街头有人在弹奏吉他唱着歌，餐厅里三个男人在讨论陀思妥耶夫斯基和伟大的作品。一个男人的朋友失踪了，一个陌生人告诉他关于美国登月的秘密还有一些人失踪的真正原因。一个年轻人从他悄无声息地搬走了，他的室友们在他的房间里找到了许多明信片，上面贴着的是从各本书上撕下来的话语。两个女人在街上说话，预言下一个从她们身边经过的人将在两周内死去.....这是一部没有具体情节和具体主角的电影。',NULL,0,0,3.320622,6.4,77,97,'1990-07-27','en','/f7Iov2nd0XX9bp2laQEPYPEhisc.jpg',2.795657136343837,3,'2026-09-10',2,NULL,NULL),(14024,'劲歌飞扬','Raise Your Voice','泰瑞（希拉里•达芙 Hilary Duff 饰）是天生的歌唱家，从小就加入了教堂的唱诗班。虽然她没有向任何人表明音乐就是自己的梦想和追求，但细心的哥哥还是知释了妹妹的心意。为了给妹妹一个惊喜，哥哥偷偷帮她报读了洛山矶表演艺术学校的暑期课程。然而不幸发生，哥哥在一次交通意外中身亡，只留下了悲伤的泰瑞独自一人接到了录取通知。\r 　　尽管爸爸不同意，但为了实现哥哥的期望，泰瑞还是来到了洛山矶。在这里，泰瑞遇到了和她一样怀揣着音乐梦想的各色同学：创作才子杰（奥利弗•詹姆斯 Oliver James 饰）、 打击乐小子奇卫、钢琴美人斯隆、小提琴黑珍珠丹尼斯、女主唱罗宾等。一班年轻人的音乐梦想就在这里开始起飞了！ ©豆瓣','Don\'t Hold Back ...Don\'t Give Up.',15000000,14867514,10.9071,6,211,103,'2004-08-10','en','/89sfBkVOsgFRPs6uKaBtSMCDSv3.jpg',3.014276613185664,3,'2026-09-10',2,NULL,NULL),(14033,'骇过阴阳线','Soul Survivors','凯西因一场车祸失去了心爱男友，并因脑部严重受损而产生种种后遗症，越过阴阳死亡界线的她开始怀疑，这一切究竟是幻觉还是…？',NULL,0,0,3.231848,4.4,49,84,'2001-09-06','en','/uWmHhtuEgX7oI0FuWR2oD08HRHD.jpg',2.65826681000415,3,'2026-09-10',2,NULL,NULL),(14034,'小偷遇到贼','What\'s the Worst That Could Happen?','凯文·卡尔菲（马丁·劳伦斯 Martin Lawrence 饰）是一名专职小偷，他手段高超，盗亦有道，凭借正直坦率的性格赢得了美丽女孩安柏·贝尔哈文（Carmen Ejogo 饰）的芳心。某晚，凯文潜入一桩豪宅行窃，结果被商人麦克斯·费尔班克斯（丹尼·德维托 Danny DeVito 饰）抓个正着。麦克斯头脑精明，经营有道，合理合法大赚其财，可以说是个高级扒手。凯文的到来搅了麦克斯的云雨好事，他因此气急败坏，抢走了安柏送给凯文的戒指。\r 这次遭遇不仅让凯文在业内颜面扫地，还让他和女友心生离析。为了一雪前耻，凯文决定向麦克斯宣战，两个顶尖高手的对决由此展开，斗智斗勇的好戏接连上演……','It takes a thief to nail a crook.',45000000,0,7.185212,5.1,66,94,'2001-05-31','en','/7vMQSpfza6sGvStWQjHDkKVJk6C.jpg',2.7379944720620344,3,'2026-09-10',2,NULL,NULL),(14043,'神探南茜','Nancy Drew','在本地小有盛名的少女侦探南茜•朱儿（艾玛•罗伯茨 饰），因为父亲的生意，离开了小镇，搬到洛杉矶生活。随着环境的改变，她也答应了爸爸，从此不再冒险破案，做一个普通的女孩儿。  　　巧合的是，朱儿一家的新宅正是神秘死亡的好莱坞著名女影星德丽娅•德雷克特生前的居所。自从德丽娅死后，这所宅子经常发生一些古怪的事件。这个神秘的地方以及女星离奇的死因又激起了朱儿的好奇心，她决定瞒着父亲，“重操旧业”。  　　在男友奈德•尼可森（马克斯•希尔洛特 饰）和新认识的小伙伴科奇（乔什•弗里特尔 饰）的帮助下，朱儿逐渐发现了一些线索，但与此同时她却收到了莫名的死亡威胁……','Small Town Girl. Big Time Adventure.',0,0,5.0348,5.8,143,99,'2007-06-15','en','/a1aAZolyLFRwKhs0IWhFyTa8Z2Z.jpg',2.9090746015308966,3,'2026-09-10',2,NULL,NULL),(14047,'激辩风云','The Great Debaters','1935年，美国南部各州还沿用着自19世纪70年代开始制定的对黑人实行种族隔离或种族歧视的法律--黑人被剥夺选举权，并在学校、住区、公共交通、公共场所以及就业、司法、军役、婚姻等各方面，受到残酷的隔离和歧视。马文·托尔森（丹泽尔·华盛顿），是一位出色的诗人，也是德克萨斯州东部一所济济无名的全黑人高校的教授。 马文相信团结，也相信语言的力量。于是，在空余时间，他一方面秘密组织佃农联合工会，反抗不公平的压榨，一方面决定成立黑人高校的第一支辩论队。在他的仔细选拔下，四位学生脱颖而出--汉密尔顿·伯格斯、亨利·劳伊、女生莎曼萨和年仅14岁的小詹姆斯·法默尔。马文相信：辩论就是战斗，就是要用语言这个武器摧毁对手。所以，他亲自撰写辩词，模拟辩论赛，并让孩子们经受军队般的严格训练。 然而，马文不同常规的、甚至有几分凶猛的教学法不仅让孩子们时有微词，年幼的法默尔的牧师父亲（弗雷斯特·惠特克）也相当反对孩子加入一个叛逆者建立的辩论队。更糟的是，麻烦接踵而来。小镇警长带着部下偷袭了工会聚会，并扣押了领头的马文不肯释放；之后，得知黑人辩论队消息的暴徒，更公然威胁要绞死他和辩论队成员...。即便艰难险阻，马文和辩论队却靠着自己的努力，得到了哈佛大学冠军辩论队的邀请，最终在全国辩论锦标赛上向顶级名校发起挑战！','When the nation was in need, he inspired them to give us hope.',15000000,30226144,10.84158,6.9,151,126,'2007-12-27','en','/nuF3DDlZzNb2qq0tEsYU0zpXf8K.jpg',2.9900275305151913,3,'2026-09-10',2,NULL,NULL),(14048,'走钢丝的人','Man on Wire','1974年8月7日，一位名叫菲利普·帕特的法国青年踏上非法架设在纽约世贸中心双子塔（当时世界最高建筑）间的钢索。在近一小时的高空行走后，他被逮捕并接受心理评估，最终在拘留后获释。历经六年半对双子塔的憧憬，帕特又在纽约耗费八个月精心策划这次行动。在一群朋友与同谋的协助下，帕特面临着无数非凡挑战：必须设法突破世贸中心的安保防线；将沉重的钢缆与索具装备偷运至塔楼；在两座塔顶间传递钢索；锚固并绷紧钢索以抵御强风与建筑晃动。所有索具安装均在深夜秘密完成。早晨7点15分，菲利普在距曼哈顿人行道1350英尺的高空迈出了钢索上的第一步。[木兰花影业]','1974. 1350 feet up. The artistic crime of the century.',0,2957978,14.331992,7.5,275,94,'2008-07-25','en','/gMDHuJeQzIOkhP3SYULWBaAOLJ5.jpg',3.2010425622733263,3,'2026-09-10',2,NULL,NULL),(14054,'雪天使','Snow Angels','学习之余，亚瑟（迈克尔·安格拉诺 Michael Angarano 饰）在一家中国餐馆里做着一份兼差，一次偶然中，亚瑟遇见了名叫安妮（凯特·贝金赛尔 Kate Beckinsale 饰）的女子，安妮曾是亚瑟家的保姆，而如今，刚刚和丈夫格伦（山姆·洛克威尔 Sam Rockwell 饰）离婚的她希望能够带着女儿过一段平静的生活。  　　莱拉（奥莉薇·瑟尔比 Olivia Thirlby 饰）是亚瑟为数不多的好友之一，随着时间的流逝，他们之间的关系却远远的超越了友谊。可是，目睹了亚瑟的失败婚姻，再加上经历了自己父母之间日复一日的争吵，亚瑟对于爱情和婚姻的期待与憧憬早已经烟消云散。三对恋人，三段破碎的感情，他们最终能否找到属于自己的那条道路呢','Some will fall. Some will fly.',0,414404,4.262374,6.5,48,106,'2008-03-07','en','/hKtht1ezc31mH1cBIHoDPmScnk9.jpg',2.6958012600238166,3,'2026-09-10',2,NULL,NULL),(14057,'相信男人','Trust the Man','女演员丽贝卡（朱莉安 摩尔Julianne Moore饰）和好友伊莱恩（玛姬 葛伦霍 Maggie Gyllenhaal饰）各自的感情，似乎都说明了男人不可信。丽贝卡有一个性欲旺盛在家待业的丈夫汤姆（大卫 杜契尼 David Duchovny饰），不过丈夫在婚姻中得不到性生活的满足，令他在外面的世界变得不堪一击。自从遇到孩子同学的母亲后，二人就如同干柴烈火走到一起；而丽贝卡，一边为失败的婚仪倍感崩溃，一边亦面临着年轻小生的倾慕。  伊莱恩是个作家，对婚姻大事非常苦恼。她八年来的男朋友——丽贝卡的弟弟托比（比利·克鲁德普Billy Crudup 饰），从来不把结婚放在日程表里，她无法忍受遥遥无期的等待，于是选择分手。而托比，亦和他的前度恋人打得火热，在失去伊莱恩之后，他才渐渐体会到她的无可替代。  这两段感情，看来已经千疮百孔了，丽贝卡和伊莱恩该就此放手，还是另有转机……','Men play the game. Women know the score.',9000000,0,5.2545,5.5,29,103,'2005-09-01','en','/njvBxeC3mj5XKjT9a2OdDglq9Yj.jpg',2.577308784639202,3,'2026-09-10',2,NULL,NULL),(14112,'聚焦人生','Auto Focus','1965年，曾担任电视剧配角并小有名气的鲍勃·克兰，已在洛杉矶KNX电台担任着成功的晨间音乐节目主持人。尽管对工作颇为满意，且沉醉于摄影（尤其热衷拍摄女性形体）与打鼓，克兰始终怀揣着成为电影明星的梦想。因此，他带着几分勉强接演了二战战俘营喜剧《霍根英雄》（1965）的主角。出乎意料的是，该剧大获成功，将他推向了电视明星的宝座。\r 然而名声带来的放纵，促使他与家庭录像设备销售员约翰·卡彭特结识。二人因共同嗜好结成密友——沉溺于荒淫的性关系（于克兰而言纯粹是异性恋行为）及用胶片记录女性裸体。明星光环让克兰得以纵情声色，这与他在电视荧幕上塑造的正面形象及在公众面前维持的人设形成强烈反差，唯有在卡彭特及其小圈子里他才展现真实面目……','A day without sex is a day wasted.',7000000,2062066,7.051521,6.1,56,104,'2002-10-18','en','/71CQUn4vtpDQtAPXtaLP7IGH0Sg.jpg',2.7275568525884166,3,'2026-09-10',2,NULL,NULL),(14113,'超人集中营','Zoom','别看如今的杰克（蒂姆·艾伦 Tim Allen 饰）肚大腰圆，他可是曾经为政府所雇佣的超能力秘密特工，当年，为了消灭人类最强大的敌人“激进派”，杰克不仅失去了他的战友们，同时也失去了自身的超能力。军队放弃了再也没有利用价值的杰克，后者则过上了梦寐以求的正常人的生活。二十多年后的今天，当“激进派”分子再一次蠢蠢欲动的时候，军队再度的找到了杰克，这一回，他将扮演一个十分特殊和重要的角色。\r 　　杰克的任务是教导四个个性极其顽劣的的孩子，教他们如何正确使用和控制各自强大的超能力。对于杰克来说，这四个孩子可比曾经所遇见的所有敌人加在一起都要难对付的多，年事已高的他能够顺利的完成任务吗？','They\'re going to save the world... as long as they\'re home for dinner.',35000000,12506188,10.304172,4.9,135,83,'2006-08-11','en','/fLpld0IdzkTtZ5KHyjl5wYz4ak3.jpg',2.867210099153154,3,'2026-09-10',2,NULL,NULL),(14114,'热力四射','You Got Served','At Mr. Rad\'s Warehouse, the best hip-hop crews in Los Angeles compete for money and respect. But when a suburban crew crashes the party, stealing their dancers - and their moves - two warring friends have to pull together to represent the street. Starring hip-hop sensations Marques Houston, Omari Grandberry, Lil\' Kim and comedian Steve Harvey.','If you want respect, you\'ve got to take it.',0,0,3.804597,4.8,75,95,'2004-01-30','en','/nFwT3QisWFQa3Wlfnw1gC458xJn.jpg',2.746120154644853,3,'2026-09-10',2,NULL,NULL),(14120,'长矛的尖端','End of the Spear','影片根据真实故事改编，五十年前，的确有一些虔诚的传教士进入蛮荒丛林地区，希望将上帝的福音传递到这里，然而迎接他们的只有清晰的敌意和锐利的长矛，如今五十年过去，这个部落已被现代文明完全改变。  　　  　　1956年，五名立志将基督之名传播到蛮夷之地的传教士，耐特(查德艾伦 饰)、吉姆、皮特、艾迪和罗杰抛弃了在美国的舒适安宁生活，乘飞机进入厄瓜多尔的原始丛林，希望能够向当地尚未开化的印第安部落Waodani族土著宣讲福音，然而不幸的是，他们几乎刚刚踏上这个部落的领地，就被手持长矛的印第安人杀害。  　　  　　明卡亚尼(露易莱昂纳多 饰)是Waodani部落的勇敢战士，他目睹了几位传教士被杀害的整个过程，也看到他们虽然手持枪械却始终未扣动扳机，直到被害前也坚决不放弃自己的宗教信仰，战斗结束之后，明卡亚尼找到传教士的遗物，并期待着能够再见到这些外面世界来的人，以便有机会解开自己心头的这些疑问。  　　  　　两年后，其中两位传教士的妻子和妹妹来到厄瓜多尔的热带雨林，心怀她们所爱之人的遗志，重新向部落居民宣传福音，在这里她们再次遇到已经成为部落首领的明卡亚尼……  　　  　　影片尽管具有争议性话题，优美的慢镜和漂亮的景色，但很明显这是一部缺乏明星号召力的电影。作为一部仅有1千万美元制作费用的独立影片，能够获得较大范围上映已经得益于宗教组织的影响力，一周就获得4百万美元的票房更是所有制作人员都没有预料到的皆大欢喜。',NULL,0,0,1.83428,6.1,15,108,'2005-12-02','en','/2jMM1cuF1FcxdPPdEJy8gquDmES.jpg',2.4399559169259626,3,'2026-09-10',2,NULL,NULL),(14137,'啤酒联盟','Beer League','主人公阿蒂是一个待业青年，年纪不小却仍和老妈住在一起。他和狐朋狗友组织了一支垒球队，原本只是想玩玩而已。结果却遇上了由阿蒂高中时候的老冤家所带领的另一队，新仇旧怨叠加在一起，比赛升级成了战斗。阿蒂和他的球队必须团结一心在赛季里将名次从末位提升到首位，否则他们将永远被踢出地方联盟……','No Gut... No Glory.',0,0,1.73892,5.3,22,86,'2006-09-15','en','/yoB3G8yGNLHdbr4TSKZqRp7UJ72.jpg',2.511471489950842,3,'2026-09-10',2,NULL,NULL),(14139,'时空罪恶','Los cronocrímenes','中年男子海克特（Karra Elejalde 饰）和妻子克莱拉（Candela Fernández 饰）搬到郊外一幢别墅居住，他用望远镜观察四周的景物，却意外看到一个正脱去衣衫的妙龄女子。海克特心感疑惑，决定前往女子出现的灌木丛中查看一番，结果遭到一个手持尖刀、全身缠满绷带的男子的追杀。海克特仓皇之中逃入一所空旷的实验室内，并在其中的大水槽内躲了起来。次日，当海克尔回到家时，却看到另一个自己正和妻子搬家具，他不知不觉穿越时空来到了一天前。原来水槽是一个时空机器，海克特的命运无意间发生了改变……本片荣获2008年阿姆斯特丹奇幻电影节黑郁金香奖、2007年奥斯汀奇幻电影节新浪潮奖。','A trip back in time from the present to...',2600000,553198,19.02965,7,308,92,'2007-09-20','es','/kEfeGaZB2UmdKfij9MHXGWBONio.jpg',3.201342002436955,3,'2026-09-10',2,NULL,NULL),(14144,'老爸夏令营','Daddy Day Camp','在这部《奶爸安亲班》的续集中，笨拙的爸爸查理和菲尔接管了夏令营，他们必须应对破旧的房屋和不守规矩的露营者。','The summer is going to be in tents.',6000000,18197398,12.601677,4.4,91,89,'2007-08-08','en','/fhuhSVb3j8SShe6FhnVUAfSRg6h.jpg',2.787404060269046,3,'2026-09-10',2,NULL,NULL),(14156,'沙排杀机','Impact Point','职业沙滩排球明星凯利雷耶斯，每天面对的最大挑战是激烈的竞争者和新闻界。但是为了他，她却什么也准备不了',NULL,0,0,1.532518,5.7,5,90,'2008-06-13','en','/p2SeFLxPU0fZno9XTYgx3w8IZAX.jpg',2.2255147240591557,3,'2026-09-10',2,NULL,NULL),(14160,'飞屋环游记','Up','小男孩卡尔从小怀揣着对冒险的向往，并因共同的梦想结识了活泼的艾莉。两人相伴一生，一直希望有朝一日能够前往南美洲的“仙境瀑布”探险，然而直到艾莉去世，这个愿望也始终未能实现。年老后的卡尔决定完成两人曾经的约定，他将成千上万只气球系在自己的房子上，连同整座房屋一起飞向天空。没想到，自称“荒野开拓者”的男孩小罗意外成为这趟旅程的不速之客。一老一少由此共同踏上前往仙境瀑布的冒险，并在途中遇见不会飞的大鸟凯文、会说话的狗狗逗逗，以及卡尔少年时代一直崇拜的传奇探险家查尔斯·蒙兹……',NULL,175000000,735099082,92.201962,7.7,6870,96,'2009-05-13','en','/mFvoEwSfLqbcWwFsDjQebn9bzFe.jpg',4.393464368359481,3,'2026-09-10',2,NULL,NULL),(14161,'2012','2012','太阳活动异常，地球内部的能量平衡系统面临崩溃，玛雅人的预言即将实现，人类将遭遇灭顶之灾。各国政府已经联手开始秘密制造方舟，希望能躲过这一浩劫。以写科幻小说谋生的杰克逊在带孩子们到黄石公园度周末时遭遇一连串怪事，并遇到了神经兮兮的查理，查理告诉他世界末日即将来临。伴随着火山爆发、强烈地震以及海啸，杰克逊带领家人驾驶一架临时租来的飞机冲出被灾难瞬间笼罩的城市，开始寻找查理口中各国政府正在联合秘密制造的方舟。在生死攸关的时刻，一些高尚的灵魂脱颖而出，而一些自私的心灵也无所遁形。当千千万万个生灵通过各种方法来到方舟制造基地时，方舟有限的容纳数量引发了前所未有的恐慌……','We Were Warned.',200000000,769653595,45.274225,5.6,4903,158,'2009-10-10','en','/3uAp9me7uwRDXueFDVsfT7JH3qp.jpg',3.6485823540456144,3,'2026-09-10',2,NULL,NULL),(14164,'七龙珠：进化','Dragonball Evolution','很久很久以前，来自遥远星系的比克大魔王及其手下大猩猩来到地球为非作歹，无恶不作，令人民时刻被死亡的阴影所困扰。此后一群优秀的武术家研究出魔封波，将比克大魔王封印，世界重归光明。  　　当代美国某座城市，看似孱弱不堪的青年悟空（贾斯汀·查特文 Justin Chatwin 饰）自幼随爷爷悟饭（兰德尔·杜克·金 Randall Duk Kim 饰）学习武术，但是爷爷禁止他将一身功夫用于好勇斗狠上面，所以悟空在学校饱受欺负与嘲笑。在一个毫无征兆的日子里，比克大魔王（詹姆斯·马斯特斯 James Marsters 饰）意外复活，而悟饭则因此毙命。悲伤的悟空按照爷爷的嘱咐前去寻找龟仙人（周润发 饰）和七颗龙珠，以阻止比克的野心。有关地球命运的冒险由此展开…','The legend comes to life.',100000000,0,21.677732,2.9,462,85,'2009-04-01','en','/ouOOyMzrB8aGBHjkIgklSKDjdNh.jpg',2.8420500242157134,3,'2026-09-10',2,NULL,NULL),(14165,'阳光会再来','Ta Ra Rum Pum','Rajveer Singh (Saif Ali Khan饰)是一个赛车队里的修车工人,并很希望驾驶赛车,后被队里的经理 Harry (Jaaved Jaaferi饰)发掘.就在同一天他邂逅了一个音乐系学生---Radhika (Rani Mukerji饰),并且爱上了她.',NULL,0,0,0.553752,6,13,156,'2007-04-27','hi','/2KfeenEAF4rgGW6wX9o6ejzL53G.jpg',2.4075189522988323,3,'2026-09-10',2,NULL,NULL),(14175,'战鸽总动员','Valiant','故事发生在第二次世界大战中，由于无线电通信已经不安全，所以英国军方开始训练军鸽，利用他们来和法国地下抵抗组织和盟军进行通讯。野鸽子“勇士”看到这么多同类为国出力，也跃跃欲试。于是，“勇士”想尽办法混到了军鸽中，未经过训练的“勇士”和其他军鸽相比显得有些力不从心。但事有凑巧，“勇士”接到二战中最严峻的任务，把诺曼底登陆的情报送到盟军手中。面对敌军凶狠的军用猎隼，“勇士”能否顺利完成任务？','Some pigeons eat crumbs, others make history.',35000000,19478106,14.051852,5.2,235,76,'2005-03-25','en','/r8EmfD7ptZEn4BVnyGV8MubTud0.jpg',2.9855545647770874,3,'2026-09-10',2,NULL,NULL),(14177,'美容店','Beauty Shop','吉娜（奎恩·拉提法 Queen Latifah 饰）是一名技艺精湛的美容师，离开了芝加哥，她带着女儿瓦尼萨（Paige Hurd 饰）千里迢迢来到了亚特兰大，瓦尼萨将要进入那里的音乐学校就读。在亚特兰大，吉娜重操旧业，来到一间美容沙龙中成为了美发师，虽然收入颇丰，但老板乔治（凯文·贝肯 Kevin Bacon 饰）却是个个性古怪的男人，常常找吉娜的麻烦。  在无数次被乔治羞辱刁难后，吉娜决定辞职，开一间属于自己的美容店，然而这件事情说来简单实践起来却困难重重。好在吉娜拥有过人的智慧和过硬的技术，随着时间的推移，她的美容店渐渐走上了正轨，有了一批忠实的顾客。与此同时，吉娜和修理工乔（杰曼·翰苏 Djimon Hounsou 饰）之间亦擦出了爱情的火花。','A Cut Above',25000000,36351350,5.625632,5.4,115,105,'2005-06-02','en','/3y5I9WKlfeNnSQbOvS4l3mVPqri.jpg',2.8497126411994063,3,'2026-09-10',2,NULL,NULL),(14181,'抢钱大作战','Boiler Room','19岁的少年赛斯·戴维斯（吉奥瓦尼·瑞比西 Giovanni Ribisi饰）一心希望能尽快淘到自己的第一桶金，好让父亲另眼相看。他本打算靠玩非法纸牌起家，却发现此路根本行不通，直到一家名为J.T.马林经纪公司的股票经纪商找上了赛维斯。  　　在这个号称“锅炉房”的核心办公室里，多少个一夜间成为百万富翁的故事深深诱惑着赛维斯。很快，野心勃勃的赛维斯便以优异的成绩通过了股票经济人认证考试，开始了他的“成功之路”。他把那些永远都没有前途的股票卖给利欲熏心的投资者。赛维斯正以极危险的速度追逐着金钱与利益，靠近着他所谓的功成名就，贪婪而不安。在纽约长岛这个瞬息万变的商业圈里，良心未泯的赛维斯终于开始面对良心的考验','Welcome to the new American dream.',26000000,28780255,11.233081,6.5,201,118,'2000-02-18','en','/jFB5uvCZ3HXF00liAEAuOruCPs6.jpg',3.037250032263674,3,'2026-09-10',2,NULL,NULL),(14191,'美人鱼','Aquamarine','少女克莱尔（艾玛·罗伯茨 Emma Roberts饰）和海莉（乔安娜·利维斯克Joanna \'JoJo\' Levesque饰）是一对靓丽活泼的好友。海莉的母亲是海洋生物学家，她开学之后就要随同家人离开美国前往澳洲。两个好姊妹的即将天各一方，她们趁着这个暑假来到海滩上尽情游玩，心里盼望着一起的日子可以长些，再长些。在这里，她们碰到了一件怪事：一条传说中的美人鱼阿夸玛（萨拉·帕克斯顿 Sara Paxton 饰）闯进了她们的生活。\r 　　原来，阿夸玛顺着洋流来到这里，是为了在三天内找到人间真爱。否则，她将被迫嫁给一个不爱的人。而潜水救生员雷蒙德（杰克·麦克道曼 Jake McDorman 饰），正是她心中的白马王子。阿夸玛请教克莱尔和海莉，如何才能赢得王子的心。然而，情窦初开的两个姊妹，心中也对雷蒙德这个帅哥心旷神怡，加上风骚的情敌赛西莉亚（阿莉尔·凯贝尔 Arielle Kebbel 饰）的干扰，这个夏天的海滩就要好戏连连了。 ©豆瓣','A Fish-Out-Of-Water Comedy.',12000000,23006849,16.931846,5.8,364,104,'2006-03-03','en','/8mioUyXqn60cwSoLrRCaO5ZAsCV.jpg',3.12235600620025,3,'2026-09-10',2,NULL,NULL),(14195,'疯狂的塞西尔','Cecil B. Demented','赛西尔·B·德门蒂德秘密控制着电影界一伙狂热的恐怖分子。他们通过制作一些低级电影捞取非法酬劳，对商业电影文化形成冲击……','Demented Forever!',10000000,0,4.176066,6.2,51,87,'2000-05-17','en','/gCXUA9BUOSDmOFVfkVBF4v15Td6.jpg',2.70303849510427,3,'2026-09-10',2,NULL,NULL),(14199,'立体小奇兵','The Adventures of Sharkboy and Lavagirl','有时候，那些无所不能的超级英雄离我们很近，就在我们自己的梦里。一个10岁小男孩马克斯(凯登·伯伊饰)，逐渐迷失于自己的幻想国度，试图逃避自己身边的日常烦恼：父母(大卫·艾奎特和克里斯汀·戴维斯饰)的罗嗦、同学的欺凌和乏味的暑假生活。当他发现自己想象中人物的酷炫威武、飞行的惊心动魄以及难以置信的神秘能量其实非常真实，只是任何人都不愿相信这样的幻想人物存在时，他的生活也开始发生改变。  　　现在，马克斯正被发射到口水行星(Planet Drool)执行任务，那里居住着鲨鱼男孩(泰勒·洛特内饰)和岩浆女孩(泰勒·杜雷饰)。鲨鱼男孩是个曾经在海上失踪的男孩，后来被鲨鱼抚养成长为半人半鲨鱼的男孩；岩浆女孩是一个火山美人，会喷射出跳动的火焰和火红的岩浆。口水行星是个让人惊奇不断的星球，一连串的思想会带你进入牛奶和饼干的口水王国。  　　紫色天空下的口水行星，看起来就像孩子们的梦中天堂，直到马克斯遇见了伊莱科崔克先生(乔治-洛佩兹饰)和他的同伴米纳斯(雅各布·达韦奇饰)，他们想除掉孩子们美好的梦境。可想而知，鲨鱼男孩和岩浆女孩遇到了麻烦，只有马克斯能指引他们，凭借他的想象设想出从伊莱科崔克老窝中机智逃脱。马克斯发挥自己的聪明才智，迅速组建起一支由小玩意和小发明组成的不可思议的军队，并且逐渐认知到将梦想变为现实的能力……','Smaller heroes. Just as super.',50000000,69425966,12.31101,4.4,269,92,'2005-06-10','en','/u5eTygrm3TzsdvfgBQUAW01qCHE.jpg',2.9390215192059475,3,'2026-09-10',2,NULL,NULL),(14202,'面纱','The Painted Veil','电影讲述了20年代一对年轻的英国夫妇来到中国乡村生活的故事，在这美丽却凶险的环境中，他们经历了在其英国家乡舒适生活中绝对无法想象和体验的情感波澜，并领悟到了爱与奉献的真谛。故事以女主角吉蒂开篇，为了逃离20年代伦敦浮华却又空虚的社交圈，也为了防止自己变成一位老姑娘，吉蒂接受了沉默寡言的医生沃特·费恩的求婚。费恩在把吉蒂带到上海后，便迅速地投入到了他的细菌学研究中去。孤独的吉蒂和迷人的已婚男子查理·唐森发生了婚外情，当费恩发现时，他羞恨交加。为了报复，也为了重整自己的生活，费恩决定孤注一掷，带着吉蒂远走霍乱肆虐的偏远城镇。沃特从一尘不染的研究室走向了瘟疫流行的最前线，他慢慢地协助控制了当地的疫情。吉蒂则开始在一家由法国修女住持的修道院兼医院中做义工，并逐渐找回了生活的勇气和意义。沃特和吉蒂终于可以互相敞开心扉，但就在他们日渐亲密的同时，沃特染上了霍乱。沃特的生死决定了他们新近迸发出来的激情能否转化为永恒的爱情……','Sometimes the greatest journey is the distance between two people.',19400000,0,20.746932,7.1,312,125,'2006-12-09','en','/8EDVJesIl6EN0pA1vxWE1Z5ABrE.jpg',3.217773154433151,3,'2026-09-10',2,NULL,NULL),(14220,'陌生荒漠','Strange Wilderness','With the ratings dropping for a wilderness-themed TV show, two animal fans go to the Andes in search of Bigfoot.','This ain\'t March of the Penguins.',0,6575282,4.961306,4.7,69,87,'2008-02-01','en','/6tamhOw4dSgn4lonjZyhEhIt9Wm.jpg',2.7309949918829455,3,'2026-09-10',2,NULL,NULL),(14256,'走过冬季','Winter Passing','美丽女孩瑞茜·霍尔登（佐伊·丹斯切尔 Zooey Deschanel 饰）心中怀有表演的梦想，为此她从密歇根州的老家来到大都会纽约，靠着自己的勤奋取得了些许成就。她的父亲丹（埃德·哈里斯 Ed Harries 饰）曾是一名知名作家，却因爱妻之死而将近二十年再未执笔。瑞茜 和父亲的关系颇为冷淡，父女二人分别多年几无联系。某晚，演出完毕的瑞茜迎来一位不速之客，她叫劳瑞·兰斯基（艾米·麦迪甘 Amy Madigen 饰），是一个以编书为生的女人。劳瑞对丹当年写给爱妻的情书极为感兴趣，她希望瑞茜能够提供这些情书。  　　虽然实现了演员的梦想，但是瑞茜仍为生计所迫。在丰厚报酬的诱惑下，她决定返回阔别七年之久的老家，却未曾想到这是一次改变人生的旅程……','Sometimes you go looking for something you want. . . and find what you need.',3500000,113783,3.643608,6.7,28,98,'2006-02-07','en','/uNAiNCHd7015BzeNggoRiTT4abf.jpg',2.579826966914173,3,'2026-09-10',2,NULL,NULL),(14271,'擂台之外','Beyond the Mat','Beyond the Mat is a 1999 professional wrestling documentary, directed by Barry W. Blaustein. The movie focuses on the lives of professional wrestlers outside of the ring, especially Mick Foley, Terry Funk, and Jake Roberts. The film heavily focuses on the World Wrestling Federation (WWF), often criticizing it and its chairman Vince McMahon. It also follows Extreme Championship Wrestling, it\'s rise in popularity, and many other independent wrestlers and organizations.',NULL,2053648,500000,2.778633,7.8,17,102,'1999-10-22','en','/48AfKc79mpRcavpA5Hc7UW9Qqq6.jpg',2.4793101876871573,3,'2026-09-10',2,NULL,NULL),(14275,'篮球梦','Hoop Dreams','这部关于希望与信仰的史诗纪事，记录了两个平凡的芝加哥贫民区少年追逐看似遥不可及的梦想——职业篮球荣光。史蒂夫·詹姆斯、弗雷德里克·马克斯与彼得·吉尔伯特耗时五年跟拍，镜头跟随年轻的阿瑟·艾吉与威廉·盖茨及其家庭，记录两位少年在应对家庭与社区生活重压的同时，如何闯荡学术体育界复杂而残酷的竞争世界。这部具有启示意义的电影持续为观众带来启迪与鼓舞，被广泛视为美国非虚构电影的伟大杰作。[标准收藏]','An Extraordinary True Story.',700000,7830611,9.188431,7.7,87,171,'1994-09-12','en','/gLzHl2XBtVwycl8DxdOXRHPm8G3.jpg',2.877820575356326,3,'2026-09-10',2,NULL,NULL),(14278,'轮椅上的竞技','Murderball','影片以激烈的竞争、分秒必争的悬念与鲜明的个性刻画，呈现了一部关于坚毅不屈、高度竞技的四肢瘫痪轮椅橄榄球运动员的纪录片。[ThinkFilm]',NULL,300000,1750211,1.085909,6.9,23,88,'2005-07-22','en','/qxaXzZnGsHaAJpSaF72nDhhL58n.jpg',2.5335986536204387,3,'2026-09-10',2,NULL,NULL),(14283,'红色小提琴','Le violon rouge','三百年来，一把红色小提琴在数个国家流浪，与数人的命运紧紧相牵。仿佛有某种魔咒，让人们为这把琴疯狂着迷。  　　小提琴的制造者，是十七世纪意大利的乐器大师（卡路•施齐Carlo Cecchi 饰 ）。妻儿死去，难抑悲伤的他，把爱人的血涂在小提琴上，从此琴就辗转流落到了奥地利。一个练琴的小男孩为了这把琴痴迷，直至倒落在舞台上。  　　小提琴的流浪从未间断，从盗墓者，到吉普赛人，到为之自杀的作曲家波普，再到文革期间上海的一位音乐老师。这期间，无论拥有者是否明白小提琴真正价值，都逃不出它的魔力。终于，有鉴别专家知道了小提琴的秘密——它的外壳染着三个世纪前一位大师的血和泪',NULL,18000000,9495408,6.18869,7.3,99,131,'1998-09-10','en',NULL,2.890539128471293,3,'2026-09-10',2,NULL,NULL),(14284,'In the Shadow of the Moon','In the Shadow of the Moon','Archival material from the original NASA film footage – much of it seen for the first time – plus interviews with the surviving astronauts, including Jim Lovell, Dave Scott, John Young, Gene Cernan, Mike Collins, Buzz Aldrin, Alan Bean, Edgar Mitchell, Charlie Duke and Harrison Schmitt.',NULL,2000000,0,3.43159,7.6,31,109,'2007-01-19','en','/xvthKnu7EjK0QvEBPY9ZnO3SiHe.jpg',2.6124104349062636,3,'2026-09-10',2,NULL,NULL),(14290,'火爆麻吉','Better Luck Tomorrow','本·马尼拜格(派瑞·沈饰)是一名亚裔美国高中少年——一个极其聪明的完美主义者，背负着亚洲人的传统思想，但是过于有成就感反而成为一种井蛙之见，直接束缚了他思想的正常发展。本生活在加利福尼亚州橘县的一个保守的郊区，学校和班级都是一样的压抑，生活中除了三点一线似乎再没有其他的激情可言。就这样平淡地渡过中学时光，本毕业时是班级成绩最优秀的学生，顺利地进入到最好的常春藤联盟大学。\r 在本高校生活开始的时候，他偶然帮助了达瑞克·鲁(罗格·范饰)，一个高年级致告别辞的毕业生代表——是另外一个过于有成就感的人。本在新环境里迅速结交了几个朋友，包括美丽的史蒂芬妮(卡琳·安娜·丘格饰)；还有关系最好的维吉尔(贾森·J·托宾饰)，他才华横溢却在社交上笨手笨脚；还有一个就是维吉尔的表兄韩(宋康饰)，一个丢失了灵魂、肌肉胜过大脑的家伙。但此时他发现达瑞克有些奇怪：作为班上最聪明的学生，他看上去似乎可信和亲切的背面潜藏着许多秘密。','Never underestimate an overachiever.',0,0,3.877036,6.5,27,101,'2002-01-12','en','/alJULQQnuiYXjgVmj2EYgwXOcIn.jpg',2.57037107297605,3,'2026-09-10',2,NULL,NULL),(14292,'冰上奇迹','Miracle','本片根据1980年盐湖城冬奥会上的真实故事改编。  1979年，陷入越战和冷战的美国，没有在科技大发展时代得到重生，反而滑向了信心危机的困局，“美国精神”发生了动摇。赫伯·布鲁克斯（库尔特·拉塞尔 Kurt Russell 饰）是带领明尼苏达大学冰球队夺得三连冠的功勋教练，在冬季奥运开赛的半年前，赫伯受命组建并训练新一届美国冰球队。当时苏联冰球队在国际上占据绝对统治地位，六十年代以来连续夺得奥运金牌。在赫伯组队伊始，他就把苏联作为最终对手看待。赫伯从各大学召来优秀冰球选手组成了一支26人的初选队，在严酷的训练中，这些非职业队员们形成了一个真正有战斗力的团体。奥运揭幕前三天，美苏两国冰球队进行了一场热身性质的比赛，美国队虽然落败，但赫伯和他的队员们都清楚，真正的较量在奥运会上……','If you believe in yourself, anything can happen.',28000000,64445708,7.534003,7,159,135,'2004-02-06','en','/mxtej2th8t8x0ufVBTyhsO6Htxj.jpg',3.000749461894236,3,'2026-09-10',2,NULL,NULL),(14293,'迷幻桌球','Poolhall Junkies','多年来一直远离赌局的高手，当他的小弟与他的敌人卷入其中时，他不得不重回从前的生活方式，而这个敌人正是曾经阻止他取得伟大成就的人。','It\'s your shot. Take it.',0,0,5.90259,6.5,25,99,'2002-06-07','en','/3MAGLk0AtuPi24PBwy3o4ILO0CV.jpg',2.558608018879749,3,'2026-09-10',2,NULL,NULL),(14295,'我办事你放心','You Can Count on Me','著名剧作家肯尼斯·洛纳根首次将其丰沛的人文视野注入银幕，以深邃的目光凝视一对姐弟间盘根错节又羁绊至深的关系。萨米与弟弟特里因车祸失去双亲多年后，小镇单亲妈妈萨米的生活再起波澜——迷茫而困顿的特里回到家乡，并意外开始了一段漫长的停留。这次相聚可能让彼此更紧密，也可能将两人彻底撕裂。洛纳根以极致的细腻笔触与无可比拟的对白掌控力，呈现了银幕上弥足珍贵的图景：那些美丽而残缺的凡人，他们的生命旅程以令人心颤的共情力，让我们窥见成长中究竟什么已然改变——而什么从未改变。[标准收藏]',NULL,0,0,7.142448,6.8,88,111,'2000-11-17','en','/7mGFmij1FZD5eUnNwvUjmpqrDl6.jpg',2.847019576652558,3,'2026-09-10',2,NULL,NULL),(14299,'蓝调传奇','Cadillac Records','《蓝调传奇》以芝加哥著名唱片公司切斯唱片(ChessRecords)的老板里奥纳德·切斯(LeonardChess)的一生为贯穿全片的主轴，讲述了1950到1960年代的芝加哥大环境下的一个关于暴力、种族、性和摇滚的故事。其中包括美国音乐界许多传奇人物的波澜壮阔的人生经历。 1947年的芝加哥南区某个逼仄的角落里，波兰裔移民里奥纳德·切斯(亚德里安·布洛迪饰)开了一间酒吧。野心勃勃的他聘请了极具天赋却又桀骜不驯的蓝调二人组——包括安静深沉的天才吉他手马迪·沃特斯(杰弗里·怀特饰)和个性冲动的口琴手利特·沃尔特(哥伦布·绍特饰)——在酒吧驻唱演出。基于对蓝调音乐的热爱和对正在起步的唱片行业的敏锐直觉，切斯为沃特斯的音乐录制了唱片。沃特斯早期音乐的唱片开创了节奏布鲁斯的先河，对于他个人也意味着大量的演出机会。',NULL,12000000,0,13.427427,6.9,86,109,'2008-12-05','en','/u2GtllItFwaXMLj4uCeKYt9wf4l.jpg',2.8591563612704576,3,'2026-09-10',2,NULL,NULL),(14306,'马利和我','Marley & Me','约翰（欧文·威尔逊 Owen Wilson饰）和珍妮（詹妮弗·安妮斯顿 Jennifer Aniston 饰）是一对正沉浸在幸福中的伉俪，婚后不久，他们前往佛罗里达州的西棕榈海岸的生活，并各自在新闻界找到满意的工作。按照传统的模式，这个已经步入正轨的家庭可以迎接新成员的到来了。不过约翰夫妇似乎对此尚未做好准备，在朋友萨宾斯坦（埃里克·迪恩 Eric Dane 饰）的建议下，约翰决定送给妻子一条黄色的拉布拉多犬，以此作为育儿之前的演练。这条名叫马利的小家伙就这样进入约翰的家中，它调皮捣蛋，不知疲倦，给约翰夫妇惹来不少的麻烦，却也同时成为这个家中不可或缺的一员……','Heel the love.',60000000,244082376,30.951203,6.9,1343,115,'2008-12-25','en','/uiF0sQ64eZtVDL78sF1WYwUTSkn.jpg',3.621830993153028,3,'2026-09-10',2,NULL,NULL),(14317,'野外怪家庭','The Wild Thornberrys Movie','这是一次野外的冒险。12岁的伊丽莎到非洲旅行，在这里她遇到一个神秘的巫师赋予她跟动物交谈的奇异力量。但有一个条件，她不能向别人泄露这个秘密，否则她将永远失去这种能力。一天，伊丽莎发现偷猎者打算捕杀象群，并用电网把它们隔离开，伊丽莎跟她的宠物非洲猩猩决心阻止他们拯救大象。','You don\'t need extraordinary powers to do extraordinary things.',35000000,0,5.784661,5.8,44,85,'2002-12-20','en','/nmWpcUQtWHC4kjVCygiFEDR1wCY.jpg',2.668259814360335,3,'2026-09-10',2,NULL,NULL),(14324,'处女地','Virgin Territory','讲述黑死病爆发的时候，女主父亲因欠钱把女主卖给债主，女主为逃避逃到修道院当修女，然后与逃避瘟疫到修道院的8个男女每天互相讲故事解闷的故事。','Anything Can Happen When You\'re In ... Virgin Territory',38000000,5410749,6.760922,4.3,75,93,'2007-12-17','en','/zofWP7ZKhoVTh2VUltaDo4LRQXc.jpg',2.7388705248385397,3,'2026-09-10',2,NULL,NULL),(14325,'生命快车','The Express','这部电影改编自美国著名的橄榄球好手厄尼·戴维斯（Ernie Davis）的生平，他是第一位获得美国大学橄榄球联盟最高奖项海斯曼奖（Heisman Trophy，相当于最有价值球员）的非裔美国人。他在1960和1961年带领锡拉丘兹大学橄榄球队两次获得全国冠军。但他毕业后，未能参加职业橄榄球比赛，因为他被诊断出患有白血病，第二年他就遗憾地告别了人世。','He changed our country... one yard at a time.',40000000,9793496,3.87823,7.1,71,130,'2008-10-10','en','/l4bOPaxwx1WebQXTeqXzXwf9n3M.jpg',2.7976153194078233,3,'2026-09-10',2,NULL,NULL),(14337,'初始者','Primer','获得第24届圣丹斯电影节剧情片类评委会大奖的《雷管》，讲述的是四位合作者出于兴趣发明了一台查错仪器，却意外地发现这台仪器拥有强大的商业价值，最终四人相互争斗的局面。《雷管》是导演什恩-卡鲁斯(ShaneCaruth)首次执导的剧情长片，该片由他自己投资，并身兼编剧、导演、主演数职，体现出独立电影的“DIY”精神。另外，令人津津乐道的是该片不足7000美元的超低制作成本，只相当于一辆富康车的价钱……','What happens if it actually works?',7000,424760,23.307949,6.9,658,77,'2004-10-08','en','/6YdsNkSeSkqIy6sswyV0Yhxuwg0.jpg',3.4085739390287926,3,'2026-09-10',2,NULL,NULL),(14351,'Crossover','Crossover','The clock strikes midnight, money changes hands, the crowd is on their feet, and the court is alive with fast-paced razzle-dazzle basketball. These players don\'t play for a school or a pro team. They play for the street and it\'s underground...way underground.',NULL,5800000,7000000,3.201886,4.2,10,95,'2006-09-01','en','/jMShqkxESzjcXWdhGJz65CPWi8L.jpg',2.3540221679114093,3,'2026-09-10',2,NULL,NULL),(14353,'遗传学歌剧','Repo! The Genetic Opera','故事设定在2056年，因为一场大规模瘟疫，人体健康深受其害，无数人因此死去。这时一个名叫Geneco的生物科技公司横空出世，人们可以以分期付款的方式向它购买器官存活下去，但是如果买家停止付钱，该公司便会派“器官收取人”——一种高级刺客，收回他所买的器官组织。  　　17岁的女孩希罗患有一种罕见的血液疾病，因此被爱女心切的父亲纳森关在房中，一直与外界隔离。纳森是一个“器官收取人”，他新的下手目标是玛格丽特，可后者是纳森已故妻子的好友，同时也是希罗的教母，这让纳森左右为难……  　　另一方面，Geneco公司的领导人将不久于人世，他的子女们明争暗斗都想成为新一任领导。在这个是非不分的世界里，各种疯狂事件正在火热上演……','Not Your Parent\'s Opera',0,188126,5.897479,6.7,100,98,'2008-07-18','en','/2G5LczM1clXu3byEudWk9w0KDYD.jpg',2.8706853390240883,3,'2026-09-10',2,NULL,NULL),(14358,'狂热舞厅','Mad Hot Ballroom','Eleven-year-old New York City public school kids journey into the world of ballroom dancing and reveal pieces of themselves and their world along the way. Told from their candid, sometimes hilarious perspectives, these kids are transformed, from reluctant participants to determined competitors, from typical urban kids to \"ladies and gentlemen,\" on their way to try to compete in the final citywide.',NULL,0,0,0.772668,7.2,8,105,'2005-05-13','en','/1wDU19PTEdR30QdnLFw93scXto7.jpg',2.316212337212437,3,'2026-09-10',2,NULL,NULL),(14359,'虐童疑云','Doubt','1964年，美国纽约布朗克斯区，圣尼古拉斯天主学校。修女阿洛伊修斯•贝维尔（Meryl Streep 梅丽尔•斯特里普 饰）令行禁止，教条严明，为学生们所畏惧；而新来的布伦丹•弗林的神父（Philip Seymour Hoffman 菲利普•塞默•霍夫曼 饰）则态度和蔼，处事开明，受到学生们的喜爱。\r 　　这期间，弗林尤其关心学校内有史以来第一位的黑人学生唐纳德•米勒（Joseph Foster 饰）。某天，詹姆斯修女（Amy Adams 饰）将唐纳德的奇怪表现报告给贝维尔修女。贝维尔认定弗林正与男孩发展不正当的关系，她决心不惜一切代价制止。然而事实究竟怎样？','There is no evidence. There are no witnesses. But for one, there is no doubt.',20000000,50907234,20.975165,7,435,104,'2008-11-27','en','/ydbTvChNwAnc8CyO6CQ4rQA2lk6.jpg',3.3009742861521856,3,'2026-09-10',2,NULL,NULL),(14369,'走出寒冷','Out Cold','小镇上的几个好兄弟里克（杰森·伦敦 Jason London 饰）、卢克（扎克·加利凡纳基斯 Zach Galifianakis 饰）、安东尼（福勒克斯·亚历山大 Flex Alexander 饰）和皮格终于有机会前往公牛山滑雪。他们来到了阿拉斯加深山的一个被遗弃的陡坡上，享受着滑雪带来的乐趣，沉浸在无忧无虑的时光中。然而，随着小镇创始人帕普的去世，他的儿子特德（威利·加森 Willie Garson 饰）决定将这片山脉出售给科罗拉多的滑雪巨头杰克（Lee R. Mayes 饰），以此来获得新的机遇。\r 　　梅杰斯身穿紧身的博格纳滑雪套装，驾驶赫默车，头戴皮质牛仔帽，对这片土地充满了野心。他的计划是将这个荒凉的地方改造成一个星光熠熠、吸引众多滑雪爱好者的热门胜地。这个计划让所有人看到了希望，并期待从中获益。不久之后，梅杰斯的继女，一位来自瑞士的绝美美女英嘉（维多利亚·希斯特德 Victoria Silvstedt 饰）也出现在公牛山上。当她提到她的法国姐妹安娜（卡罗利娜·达韦纳 Caroline Dhavernas 饰）将很快到来时，公牛山上的每个人都充满了兴奋和期待。','They haven\'t quite figured it all out, but they\'re getting a little warmer.',24000000,14782676,4.12064,5.8,53,89,'2001-11-21','en','/2aBepBnMXRs3hmde9Je3rn5bseJ.jpg',2.703030889426281,3,'2026-09-10',2,NULL,NULL),(14392,'投名状','投名狀','清末战乱频仍，清军将领庞青云在一场惨烈战役中遭同僚抛弃，所部几乎全军覆没，只有他侥幸生还。流落途中，他结识了性格豪爽的赵二虎和忠勇直接的姜午阳，也意外发现此前偶遇的女子莲生竟是赵二虎的妻子。面对饥荒、官军欺压和无路可走的村民，庞青云提出投军求生，并与赵二虎、姜午阳纳下“投名状”，结为生死兄弟。三人带着一群弟兄投身战场，凭借一次次出生入死不断立下战功。然而随着地位、权力与利益悄然改变，最初那份生死与共的兄弟情义也开始面对越来越严峻的考验……',NULL,40000000,0,6.884467,6.3,83,126,'2007-12-12','zh','/jqZrHEsaoKdnwPJHwVmQrnehVUA.jpg',2.8173979214719167,3,'2026-09-10',2,NULL,NULL),(14395,'永不说再见','कभी अलविदा ना कहना','本片主要讲述了戴夫和玛雅之间朦胧的浪漫爱情故事。\r 戴夫和玛雅都已经分别各自嫁娶，并相信他们自己都过着幸福的生活。但是，两个主人公却都觉得生活中应该追求一些更为深刻、更为有意义的东西。\r 最初，他们只是在对方身上感到了自己想要的感觉，随着感情的逐渐明朗，他们原来的生活和情感秩序将被打破…','A Love.... That Broke All Relationships',7400000,17000000,3.246903,6.1,42,193,'2006-08-11','hi',NULL,2.6577269818208915,3,'2026-09-10',2,NULL,NULL),(14396,'代号：杀手','Code Name: The Cleaner','身在何处，但是身边的尸体和巨款告诉他，他可能被卷入了一起危险的事件中。一个名叫戴安娜（妮可莱特·谢里丹 Nicollette Sheridan 饰）的女人出现在了杰克的面前，她告诉汤姆自己是他的妻子，并且手脚麻利的处理了一团糟的现场。对于戴安娜的身份，杰克心存疑虑，而之后戴安娜的言行则使她的身份显得更加可疑。\r 离开戴安娜后，杰克遇见了自称是他女友的吉娜（刘玉玲 Lucy Liu 饰）。通过吉娜的只言片语，杰克知道了自己是一家游戏公司的守门人，但有过一次受骗经历的杰克对此保持着怀疑的态度。糟糕的是，杰克发现，有一些神秘的黑衣人似乎对自己的行踪异常关心。',NULL,20000000,10337477,9.36146,4.7,78,84,'2007-01-05','en','/wSQkv51ygnds56lylNavYJzLmNZ.jpg',2.762990036129371,3,'2026-09-10',2,NULL,NULL),(14405,'比佛利拜金狗','Beverly Hills Chihuahua','克洛伊（德鲁·巴里摩尔配音）是比佛利山的一只吉娃娃狗，被宠坏了的她生活极其奢侈。她清高自傲，自视甚高，极少关注她的同类帕皮（乔治·洛佩兹配音），帕皮样貌平平、肥头大耳、略显粗野但精明多情。一次克洛伊去墨西哥度假，没想到却在那里迷了路。那些简陋的街道看起来跟比佛利山大相径庭。无奈之下，克洛伊只得就近求助于新朋友，一只经历复杂、因丧失嗅觉而被踢出警局，对生活灰心丧气的德国牧羊犬戴戈多（安迪·加西亚配音），去帮助她找到回家的路。而此时，聪明的帕皮终于赢得“救美”的机会，率众队向南边进发找到回家的路。这个品类复杂的“返家突击队”还包括两个人类、一只狡猾的老鼠和一只焦虑惊慌的美洲大蜥蜴。在返家路途中，经由大家的帮助，帕皮也赢得了自己的真爱。','50% Warrior. 50% Lover. 100% Chihuahua.',20000000,149281606,12.25264,4.9,209,91,'2008-10-03','en','/bNklJDctJxK9MlVAvSOIwQEmz9u.jpg',2.941774230561184,3,'2026-09-10',2,NULL,NULL),(14411,'辛巴达七海传奇','Sinbad: Legend of the Seven Seas','故事从希腊神话的纷争女神艾莉丝（米歇尔·菲佛 Michelle Pfeiffer 配音）开始，她是一个喜欢混乱的女神，她盗走了“和平宝典”，又将这个罪名嫁祸给了辛巴达（布拉德·皮特 Brad Pitt 配音），护送“和平宝典”的王普罗士（约瑟夫·费因斯 Joseph Fiennes 配音）是辛巴达的从小玩得好的朋友，“和平宝典”被窃也使得他的任务失败，无法向自己的王国交代，而王国里的大臣都一致认为是辛巴达盗走了。但普罗士相信辛巴达的清白，他主动提出以自己生命做抵押，让辛巴达追回宝物“和平之书”。普罗士的未婚妻玛琳娜（凯瑟琳·泽塔-琼斯 Catherine Zeta-Jones 配音），为监视辛巴达也偷偷登上了船。辛巴达能否经受考验，为夺回“和平之书”救出朋友的性命？他和玛琳娜又在患难中发生了怎样的爱情？',NULL,60000000,26288320,18.815442,6.6,372,86,'2003-07-02','en','/1kWWWrZitA4nYd4IkxGtHuGqBzk.jpg',3.2120437729767586,3,'2026-09-10',2,NULL,NULL),(14425,'政治正确的你','PCU','Nervous high school senior Tom Lawrence visits Port Chester University, where he gets a taste of politically correct college life when he\'s guided by fraternity wild man Droz and his housemates at The Pit. But Droz and his pals have rivals in nasty preppy Rand McPherson and the school\'s steely president. With their house threatened with expulsion, Droz and company decide to throw a raging party where the various factions will collide.','Flunk \'em if they can\'t take a joke.',9000000,4350774,8.738737,6,41,79,'1994-04-29','en','/xTToUzy9Im9nu2W8fz7TPWoDWN5.jpg',2.663567891441309,3,'2026-09-10',2,NULL,NULL),(14429,'让我疯狂','Drive Me Crazy','\"妮可尔（梅利莎·琼·哈特 Melissa Joan Hart 饰）是一个非常追逐时尚喜爱八卦的普通高中女生，暗恋着一位篮球明星，可惜她的白马王子似乎并没有将妮可尔放在心上。妮可尔的邻居切丝（艾德里安·格尼尔 Adrian Grenier 饰）本来拥有一个令人人羡慕的漂亮女友，但最近，这个女孩甩掉了他，这让切丝感到非常的郁闷。\r 一个是苦苦单恋无果的霉女，一个是刚刚经历失败恋情的宅男，原本性格大相径庭八竿子打不到一起的两人一拍即合，制定了一个傻瓜计划，那就是假装恋爱，企图以此吸引前任们的注意。这老套的招数真的管用吗？随着时间的推移，他们渐渐发现，与其苦苦追寻触摸不到的星星，还不如将寻求真爱的目光投向身边。\"','The last guy she wants is the only one she needs.',8000000,22593409,4.482714,5.8,62,91,'1999-10-01','en','/qq2jbAOw5yWTaSPJIRHxvTf0bND.jpg',2.7363359318566016,3,'2026-09-10',2,NULL,NULL),(14434,'I Think I Love My Wife','I Think I Love My Wife','Richard Cooper (Rock) is a married man and father of two who is just plain bored with married life. Not getting any sex from his wife, he resorts to ogling random women on the street to the point he takes lunch late to look at them. When old crush Nikki Tru (Kerry Washington) visits his office to get a reference letter, she becomes obsessed with Cooper and they begin a complicated relationship.','In marriage no one can hear you scream.',11000000,13196245,4.536745,5,55,90,'2007-03-16','en','/lJHg7ExSTszC8ItsufcmSPeN0vW.jpg',2.694806335656479,3,'2026-09-10',2,NULL,NULL),(14435,'My Bloody Valentine','My Bloody Valentine','Ten years ago, a tragedy changed the town of Harmony forever. Tom Hanniger, an inexperienced coal miner, caused an accident in the tunnels that trapped and killed five men and sent the only survivor, Harry Warden, into a permanent coma. But Harry Warden wanted revenge. Exactly one year later, on Valentine’s Day, he woke up…and brutally murdered twenty-two people with a pickaxe before being killed.','He\'s gonna break your heart.',15000000,100734718,13.706357,5.3,299,101,'2009-01-16','en','/n3PMynTM1TPa6jLvbbeGzQbzw01.jpg',3.0327061410743714,3,'2026-09-10',2,NULL,NULL),(14438,'消防员','Fireproof','凯勒（柯克·卡梅隆 Kirk Cameron 饰）是一名消防员，凯瑟琳（Erin Bethea 饰）是医院的公关主任，尽管在各自的职业领域里叱咤风云，但两人都无法否认的是，是他们的冲动和不成熟导致了两人之间感情的破灭和婚姻的破裂。在经历过了无数次激烈的正常和令人沮丧的冷战后，离婚成为了两人唯一的选择。  　　目睹年轻人们为感情所困苦，约翰（Harris Malcom 饰）决定不再坐视不管。他劝说儿子约翰，带着凯瑟琳参加名为“挑战爱情”的为期四十天的旅程，将其作为修复夫妻之间感情的最后努力。没想到，正是在这段看似无望的旅程中，凯勒明白了自己所犯下的过错，他决定要挽回凯瑟琳对自己的爱和信任，然而，面对去意已决的凯瑟琳，凯勒的挽留能够奏效吗？ ©豆瓣','Never Leave Your Partner Behind.',500000,33456317,6.093989,7,100,122,'2008-09-26','en','/csdRbetoObJHlAExU03BhwqKS85.jpg',2.8819981249126223,3,'2026-09-10',2,NULL,NULL),(14442,'魔法灰姑娘','Ella Enchanted','艾拉（安妮•海瑟薇 饰）出生与一个色彩斑斓的奇幻世界中，每个在这里出生的孩子都会得到仙女的“礼物”。而可爱的艾拉得到的“礼物”是服从。自此，无论是多苛刻的要求，只要一声命令，艾拉便会一一照办。艾拉母亲去世前便叮嘱她以后要用自己内心的真实信念去抗行咒语，而且必须找到下咒语的魔女才能完全解除咒语。此时的艾拉已经饱受继母及继母女儿的折磨，而她告诉自己必须要找到当年的魔女。  　　但一切进行得并不顺利，而在一个偶然的机会中，她认识了英俊的王子查尔。自小父母便离世的查尔十分听从叔叔的话。艾拉跟王子很快便坠入了爱河，当回到城堡的时候，艾拉发现了查尔叔叔的秘密，而且她身上的咒语更受到了查尔叔叔的利用……','Get enchanted',31000000,27388767,22.71592,5.9,437,96,'2004-04-09','en','/ls0hv9BtR2ARap2gVjP1TQi32Yv.jpg',3.1824906691138994,3,'2026-09-10',2,NULL,NULL),(14444,'淘气小兵兵大电影','The Rugrats Movie','淘气小兵兵们有了自己的弟弟或者妹妹，但是他们之间始终无法和平相处。他们的爸爸制作了一个“恐龙车”，准备参加东京的展览。在托运的时候，孩子们把恐龙车开走了，并且在森林里遇到了危险。孤立无援的孩子们开始寻找“会魔法”的蜥蜴巨人，大人们也开始了他们的搜索行动。',NULL,30000000,100491683,7.981116,5.7,147,79,'1998-11-20','en','/uZejGKCSd6nwfMx8U0Td37U2fTc.jpg',2.916358465184409,3,'2026-09-10',2,NULL,NULL),(14451,'死亡之雪','Død snø','就读于医科大学的维加德及好友们驱车前往厄克斯尼湾附近的雪山，计划与其先行到达那里的女友莎拉会合一同度假。当晚，他们从一个流浪汉那里听到流传在此地的一个恐怖传说：二战期间，一支德国部队驻扎这里，他们从当地人手中大肆搜刮金银财宝，手段残酷，贪婪无度，但在战争结束前夕该部队却被愤怒的民众杀死，只有为首的赫尔措格指挥官极少数几个人躲进了雪山之中。年轻人们对此当然嗤之以鼻，但随着一盒财宝的出现，埋藏在雪中的纳粹僵尸开始一一复活，准备夺回曾属于他们的财宝。','Eins, Zwei, Die!',800000,1984662,11.205726,6.1,311,91,'2009-01-09','no','/6QkPoC15DErpVMP7RZbpPVK9NgE.jpg',3.105324067074165,3,'2026-09-10',2,NULL,NULL),(14462,'满洲候选人','The Manchurian Candidate','荣获了诸多荣誉和奖章的本·马高（丹泽尔·华盛顿 Denzel Washington 饰）当年曾是一名海军陆战队上尉，第一次海湾战争期间，他所在的小分队夜晚执行搜查任务时遭到伏击，凭借战友雷蒙德·萧中士（利夫·史列巴 Liev Schreiber 饰）的机智与果敢，整个小队最终化险为夷，失去知觉的本也多亏雷蒙德才死里逃生。十年后，本在无数个场合讲过这段过去，并大力盛赞雷蒙德的果敢。由于战争期间的出色表现，雷蒙德的仕途一片光明，在参议院的母亲伊丽娜（梅丽尔·斯特里普 Meryl Streep 饰）的协助下，他如今已然成为副总统的候选人。然而就在此时，本却被感焦虑，在他的心中不断质疑着当年发生的一切，似乎那晚的袭击事件有着另一个不为人知的版本…… 　　本片根据1962年约翰·弗兰克海默经的同名影片改编。','This summer everything is under control.',80000000,96105964,21.394281,6.2,393,129,'2004-07-30','en','/dtQ1iHH02TpmBpBJpwioCrQD4GF.jpg',3.1895870837909515,3,'2026-09-10',2,NULL,NULL),(14474,'哈罗俄亥俄','The Oh in Ohio','这里讨论的，是关于一对结婚十年的夫妻在性方面的觉醒……普里西拉和杰克青梅竹马，从相恋到步入礼堂、再到共同生活了十年，他们几乎就要谱出一个让人艳羡的爱情传奇。然而，看似平静的表面下永远是波涛暗涌，两人在性方面的不和谐，已经到了无法弥补的程度：虽然普里西拉一再声称两人的性生活完美到无...','One woman\'s story is about to climax.',5000000,0,6.759235,5.8,27,88,'2006-03-30','en','/4R2wqT72RApomtBnfYG4BUpyoGh.jpg',2.56944892737811,3,'2026-09-10',2,NULL,NULL),(14517,'镜子面具','MirrorMask','故事讲述的是在一个梦幻般的国家里，一个15岁的女孩必须去找到一个面具，去拯救他的国家找回自己的家园。一个叫Helena的15岁女孩生活在一个马戏团里，她希望有一天能逃离现在的生活。一次她与父母为了将来的计划而吵架了，后来妈妈病倒了。Helena认为是因为自己的错误才把妈妈给气病的，很内疚。在妈妈临做手术的前夜，她梦到自己在一个奇特的世界，在那里有两个截然相反的女王，很多奇怪的人。在这个全新的世界里，白女王望病倒了而只有MIRRORMASK能让她恢复过来，后来她就派Helema去寻找面具……','The Other Side of Reason. The Other Side of Fate. The Other Side of Truth.',4000000,866999,7.758188,6.6,102,101,'2005-01-25','en','/itIJU3NKbdgScA1WPIxXzOlm0Uj.jpg',2.8758818248956297,3,'2026-09-10',2,NULL,NULL),(14536,'New in Town','New in Town','Lucy Hill is an ambitious up-and-coming executive living in Miami. She loves her shoes, she loves her cars and she loves climbing the corporate ladder. When she is offered a temporary assignment – in the middle of nowhere – to restructure a manufacturing plant, she jumps at the opportunity, knowing that a big promotion is close at hand. What begins as a straight-forward assignment becomes a life-changing experience as Lucy discovers greater meaning in her life and, most unexpectedly, the man of her dreams.','She\'s an executive on the move. But her career is taking her a little farther than she expected.',8000000,29010817,13.987772,5.2,99,97,'2009-01-30','en','/OMCGtMmmBE9NwmawLGZlaErdLk.jpg',2.832975823250978,3,'2026-09-10',2,NULL,NULL),(14538,'三国之见龙卸甲','三国之见龙卸甲','三国乱世，战火纷争。面对魏军强势压境，初任工兵的赵云主动请缨，借助军师诸葛亮以攻为守的策略，立下劫寨扰敌的大功。随后的长坂坡一战，赵云单枪匹马杀入曹营救回幼主，从而一战成名。随后并被委以重任与黄忠老将军一起出征定军山，收取汉中，奠定蜀国基业。不过此役，由于黄忠心急想争头功提前出兵，却中了曹操的奸计伤亡惨重。危机之时，赵云及时赶到救出了黄忠和罗平安，并在诸葛亮妙计的帮助下，烧掉曹军粮草扭转战局立下大功。赵云也因此荣升五虎上将，而身为同乡兄长的罗平安心中却是百般滋味。时间就在战争中飞逝而过，蜀国的五虎大将也先后辞世。在诸葛亮的再一次灭魏大计前，赵云坚持做先锋大将，却在凤鸣山前遇上曹操10万大军，面对人生的终极之战，赵云该如何应对？',NULL,0,0,4.127155,6.6,35,102,'2008-04-03','en','/vIZyykQmjKVgfNiNBNIG4bxa2Jf.jpg',2.628064318767201,3,'2026-09-10',2,NULL,NULL),(14544,'冰上迪斯科','Roll Bounce','1970年代的滑轮溜冰音乐推动了这部成长喜剧的情节，X（鲍伯）和他的朋友们在当地溜冰场称霸，但当他们的家园倒闭时，他们倍感震惊。他们前往Sweetwater溜冰场，却发现他们的技能在一开始无法与那些技巧高超的溜冰者和美丽的女孩相比。',NULL,0,0,2.596338,6.1,27,112,'2005-09-23','en','/lStFr3EHTNbnyOdOk2QDCqYGnlR.jpg',2.5631567608496493,3,'2026-09-10',2,NULL,NULL),(14557,'校园怪谭','Dead Man on Campus','在美国大学的校园里，有着这样一个传说，如果你的室友因为意外而去世了，那么你的期末成绩将会非常的优异。没有人知道这个传说是从什么时候开始流传的，亦没有人真的去证实它的真实性，除了乔什（汤姆·艾弗瑞特·斯科特 Tom Everett Scott 饰）和库珀（马克-保罗·戈塞拉 Mark-Paul Gosselaar 饰）。 　　期末考试将近，这两个成绩一塌糊涂的年轻人，只要他们再挂一门课，就将面临被退学的悲惨命运，为了保住自己的学位，他们决定选择铤而走险。然而，那个应该因为“意外”而死去的室友究竟是谁呢？一个疯狂的计划正在酝酿之中。 ©豆瓣',NULL,0,0,7.708227,5.6,49,96,'1998-08-21','en','/mTr7ARy7lj8ggvg6snLWDo3CnEu.jpg',2.691181875243336,3,'2026-09-10',2,NULL,NULL),(14560,'百货战警','Paul Blart: Mall Cop','商场保安保罗的梦想是成为一名警察，但低血糖的体质让他在新泽西警察学校的考试中再次失败，保罗带着颓意返回家中，母亲和女儿给予安慰并劝说他再找一位爱人。保罗又开始了每天平淡的工作：指路或是被商场的孩子们捉弄，但今天，他的目光被假发柜台的艾米深深吸引，保罗希望在艾米面前彰显男儿本色，但无奈庞大的身躯和偏弱的体质总是令他的自尊受损。这天，一群匪徒占领了商场，计划对店面和银行进行暴劫，而躲在游戏厅中的保罗对这一切浑然不觉，当他赤手空拳面对劫匪时，剩下的只有逃跑，然而保罗意识到艾米被劫为人质时，他决定不顾一切返回商场……','Safety Never Takes A Holiday.',26000000,183293131,31.250383,5.2,788,91,'2009-01-15','en','/1lOaS2svU3fiB57AeqfCOmQTIGc.jpg',3.211434249990529,3,'2026-09-10',2,NULL,NULL),(14574,'穿条纹睡衣的男孩','The Boy in the Striped Pyjamas','八岁的布鲁诺随身为纳粹军官的父亲从柏林搬到乡下。离开熟悉的朋友后，孤独的布鲁诺很快注意到新家附近一片被铁丝网围住的地方，那里的人终日穿着相似的“条纹睡衣”，这让他充满好奇。一次偷偷探索中，布鲁诺结识了铁丝网另一边的同龄男孩施穆尔，并时常带食物给他。尽管两人身处截然不同的世界，他们仍逐渐成为彼此重要的朋友。随着家庭中的紧张气氛不断加剧，布鲁诺也开始透过这段纯真的友情，接触到一个他尚无法理解的残酷现实……','Lines may divide us, but hope will unite us.',12500000,20416563,34.821223,7.7,1451,94,'2008-05-07','en','/2C8QCXdMlojTxZjfBlINr4FWcb6.jpg',3.8113557597407706,3,'2026-09-10',2,NULL,NULL),(14576,'摊牌','Shade','出没在洛杉矶酒吧，夜总会的扑克老千世界里，三名行骗高手各怀鬼胎准备大显身手，当他们将高额赌注压宝在下一头肥羊“THE DEAN”身上时，不料却卷入连串黑道复仇杀机中难以脱身，到底谁在骗谁？水能全身而退？不到最后一秒无法预知真相。','Lie, cheat, steal... your deal!',6800000,0,4.665309,6.1,73,101,'2003-05-18','en','/A0bk1z7kWD2ILr6W9IMUkQ4QHwM.jpg',2.778710202338644,3,'2026-09-10',2,NULL,NULL),(14577,'下流勾当','Dirty Work','米契連番失業又被女友給甩了，好友的老爸需要一顆心臟，不幸他們卻遇上愛錢的爛醫生，為了這筆錢，米契兩人幹起下流勾當，只要顧客要求，保證包君滿意。','Revenge is a dish best served DIRTY.',0,0,9.066881,6.5,66,82,'1998-06-12','en','/r6OcS6TQCHal2wHooJhHWSlFzfd.jpg',2.7771854998817713,3,'2026-09-10',2,NULL,NULL),(14578,'Outside Providence','Outside Providence','In this coming-of-age comedy, Tim Dunphy is leading a go-nowhere existence, spending his days smoking pot and hanging out with his best friend, Drugs Delaney. But Tim\'s lazy days of getting high are jettisoned after a brush with the law convinces his blue-collar dad to send him to a Connecticut prep school. The one saving grace of the new school is Jane, a fellow student Tim falls for immediately.','Tim\'s getting a future... whether he likes it or not!',7000000,7292175,2.627232,5.6,30,96,'1999-08-16','en','/xSqewkFWR0zs7OkXLOd10VnxFPN.jpg',2.5793814267911106,3,'2026-09-10',2,NULL,NULL),(14582,'帕斯尚尔战役','Passchendaele','《帕斯尚尔战役》讲述了一个受伤的军官（保罗·格罗斯饰）爱上一名护士（卡罗琳·德哈维纳斯饰）的故事。他与患慢性病的护士弟弟一起，协同加拿大士兵在帕斯尚尔的战场上同敌人作战……',NULL,0,0,2.405911,6.3,26,114,'2008-10-17','en','/2FMtSxzF2fR5dx5was9Kftjag0U.jpg',2.556897274132804,3,'2026-09-10',2,NULL,NULL),(14585,'与男人同行','In the Company of Men','尼尔.莱布特Neil LaBute原为美国剧场界经纪人，本片是他进军电影界的处女作，仅以一万五千美元的超低成本制作完成，但却获得如潮好评，不但在日舞电影节中当选最佳影片，并且成为当年全球最赚钱电影的第四名。两名城市的白领阶级因为工作和感情方面的不如意，遂在他们前往中西部小镇公干六个星期中决定向异性报复。方法是找到一名柔弱的女生，假装两人都在追求她，当她陶醉在爱情的幸福之中时，再甩掉她让她痛不欲生。他们选中了一名美丽却听觉失灵的打字员，分别跟她展开约会....','Are all men bastards...or just misunderstood?',0,0,2.634007,6.8,44,97,'1997-01-19','en','/1gPJ4H4TbGAiuEA6pFalFtqA0eL.jpg',2.6781520194373867,3,'2026-09-10',2,NULL,NULL),(14608,'悲恋印巴','Partition','锡克农夫有天拯救了一名逃难时和家人失散的年轻回教徒女孩，保护她免于被族人杀害，后来两人互生感情而结婚，但是前面仍有重重的宗教与种族障碍考验着他们……',NULL,0,0,2.131524,6.4,6,116,'2007-02-02','en','/qCq3QZbrf2ENAEyPJVaCGbWOQ1N.jpg',2.26190458873363,3,'2026-09-10',2,NULL,NULL),(14623,'雷鸟惊航','Thunderbirds','2065年，美国退役宇航员杰夫特雷西(比尔帕克斯顿)和他的5个儿子组成了一支名为“雷鸟”的太空救援队。他们利用火箭等运输工具去帮助那些遇到麻烦的人们。火箭飞船设计天才布莱恩斯(安东尼爱德华兹)以及可爱女郎佩妮洛普(索非亚迈尔斯)等人则是“雷鸟”们忠实的伙伴。这些人凭着善良和勇气令无数人脱离险境。  一次，亚里斯托特尔斯波德(本金斯利)统领下的邪恶集团攻击了杰夫等人所居住的小岛。而这场精心策划的阴谋目的是为了利用“雷鸟”来从事犯罪。于是，一场惊心动魄的大战开始了。',NULL,57000000,28283637,9.27875,4.2,91,95,'2004-07-23','en','/1jH0vADEIvuRlkvJzLUW5nVO96d.jpg',2.773150675873015,3,'2026-09-10',2,NULL,NULL),(14624,'超级礼物','The Ultimate Gift','杰森（德鲁·傅勒 Drew Fuller 饰）与爷爷霍华德·史蒂文斯（詹姆斯·加纳 James Garner 饰）之间似乎从未有过所谓祖孙情深的桥段，杰森唯一知道的就是向爷爷要钱。当爷爷去世后，杰森满心以为可以继承一大笔财产，前途无忧之时，他发现爷爷竟在他和这笔财产之间设置了十二道障碍，他必须依次完成遗嘱上的十二个有关“礼物”的任务后，方能得到这笔最终的超级礼物。为了获得遗产，杰森只好着手完成第一个任务，没想到得到的礼物竟是让他尝尝破产的滋味，而这仅仅是开始，对于几乎没有过正式工作的富二代杰森来说，遗嘱上的每一个任务都是一次艰难挑战，他不知道在这条发现之旅上他还会遇到什么，也不知道爷爷到底在卖什么药，然而他的人生却因为这份遗嘱正悄悄地被改写……  　　本片改编自吉姆·斯托维尔的同名畅销小说',NULL,0,0,4.976268,6.8,78,114,'2006-10-20','en','/gUzjxVZZPB0qdVol1MnpZTgt9vL.jpg',2.8139085992357527,3,'2026-09-10',2,NULL,NULL),(14629,'女人置上','Woman on Top','伊莎贝拉（佩内洛普·克鲁兹 Penélope Cruz 饰）是一个拥有着极为强烈的个性的女人，生活中充满了主见，有时甚至到了一意孤行的地步。虽然伊莎贝拉固执而又好强，但她是真心实意的爱着丈夫东尼奥（莫里奥·本尼西奥 Murilo Benício 饰）的，只是东尼奥无法接受妻子的性格，最终还是放弃了对婚姻的忠诚。\r 　　发现丈夫出轨的伊莎贝拉心碎欲绝，选择了离开，前往美国。之后，伊莎贝拉在朋友的帮助下找到了新的人生方向——成为一名电视台烹饪节目主持人。伊莎贝拉奔放的个性和对美食的热爱让她很快就名声大噪，一时之间吸引了大批追求者，此时才发现伊莎贝拉魅力的东尼奥想要挽回妻子的爱，可是已经为时已晚。','Want to know how she got there?',8000000,0,3.535789,5.5,46,92,'2000-09-22','en','/eYHvcMeVjWPwATYI0VCdecMy2n3.jpg',2.6669913547876156,3,'2026-09-10',2,NULL,NULL),(14631,'事业与荣誉2：美国天堂','The Work and the Glory II: American Zion','\"The Work and The Glory: American Zion\" sets the story of the fictional Steed family against the historically factual backdrop of the Mormon people\'s move into the West. Divided by their diverse reactions to a nascent ideology, the Steeds struggle to hold together as the strength of their convictions and their filial bonds are tested. The stirring narrative of the faith that led a persecuted people to Missouri and beyond is one of the most poignant untold tales of American history. It is the account of a valiant struggle to exercise the rights promised by a fledgling nation. \"The Work and the Glory: American Zion\" unearths the story of the passion behind the movement which eventually launched the largest American migration and the colonization of the West: the vision of a promised land in America.',NULL,6500000,2025032,2.639106,8,6,100,'2005-10-21','en','/uXGtTR0VhmP1CcJRbBMn07gHc7d.jpg',2.266985412330421,3,'2026-09-10',2,NULL,NULL),(14635,'心灵投手','The Rookie','吉姆莫瑞斯(丹尼斯奎德饰演)从小就喜欢棒球。但是在身为海军军官父亲的阻挠以及居住地─德州小镇只热衷美式足球的客观情势下，吉姆只能放弃自己的梦想，乖乖地唸书、结婚、生子，并且在小镇上的中学担任自然科学教师的工作。但是吉姆却在学校里组织了一支棒球队，并且担任指导教练的工作。 　　吉姆35岁的那年他与榜球队学生打赌，只要他们能打进州际杯的比赛，吉姆必须参加当年 大联盟 的选秀赛。吉姆不顾妻子的反对，带着三名幼小的子女出现在选秀会的会场，他边替小孩换尿布的空档边投球，居然能投出将近160公里时速的快速球，因此以三十五岁的高龄入选为三十年来大联盟最老的“菜鸟投手”。','Sometimes dreams come back to life.',20000000,75597042,11.263361,6.5,110,127,'2002-03-25','en','/wbGJucJ9ukPKp89FnP1Qoe2G8s3.jpg',2.897419072416907,3,'2026-09-10',2,NULL,NULL),(14652,'一路顺风','Bon voyage','德国法西斯1940年5月10日开始进攻西欧，英法联军防线在德国机械化部队快速攻势下崩溃。5月26日晚英法联军开始了“敦刻尔克大撤退”，同时法国政府宣布巴黎为不设防城市后逃到波尔多。临时政府就在当地一家豪华旅馆办公。',NULL,0,0,0.49446,5.7,20,114,'2003-04-16','fr','/rs4nJIrSwDUesSymgekea6D1IgA.jpg',2.492713690384985,3,'2026-09-10',2,NULL,NULL),(14655,'灵魂歌手','Soul Men','谁也没有想到，弗洛伊德（伯尼·麦克 Bernie Mac 饰）和路易斯（塞缪尔·杰克逊 Samuel L. Jackson 饰）这两个其貌不扬的男人在歌坛也有过红极一时的曾经，而如今，乐队主场离开，乐队亦已解散，两人的情况都不容乐观。\r 一眨眼，十年过去了，主唱的去世为两个潦倒的中年人带来了新的希望，他们接到了阿波罗剧院的邀请重新登台，在好不容易劝说路易斯加入后，说唱二人组诞生了。可是，娱乐圈的瞬息万变让弗洛伊德和路易斯成为了无人买账的老古董。在压力和挫折面前，两人的友谊更是经历了前所未有的考验。一次偶然中，一段路边的即兴表演让两人明白，没有作秀，没有技巧，灵魂发出的声音才是真正的天籁。',NULL,0,0,5.483671,6.3,47,103,'2008-11-07','en','/ewU8w8IPlAkauFutzSwYYFILiU8.jpg',2.6903362217402247,3,'2026-09-10',2,NULL,NULL),(14662,'比佛利山辣妹','Slums of Beverly Hills','《比佛利山辣妹》是1998年上映的喜剧片，由塔玛拉·詹金斯执导，艾伦·阿金、卡尔·雷纳等主演。剧情讲述了生活在70年代的青春少女薇薇安（娜塔莎·雷昂 饰），含苞待放，正走在蜕变为成熟女人的道路上。然而，她遭遇了两个问题：一个是她奇怪的游牧家庭，总是搬来搬去，但是她还是希望能够待在比佛利山的学区中。另一个是她日趋成熟的性征，再加上她讨人厌的表姐前来造访捣乱，把她的生活弄得乌烟瘴气，一团混乱......','Growing Up is Hard to Do',5000000,0,6.308298,6.5,44,91,'1998-08-14','en','/bTY6I0Mju4vTRHGoTZrNtxtAlAO.jpg',2.6814181474765095,3,'2026-09-10',2,NULL,NULL),(14709,'校园蓝调','Varsity Blues','橄榄球对于迦南镇的居民们来说实在是太重要了，身为他们挚爱的高中小狼队的教练，吉尔默（强·沃特 Jon Voight 饰）拥有着至高无上的发言权，因为在他的带领和执教下，小狼队曾经两次在州里夺得了金杯。  　　马克思（詹姆斯·范德比克 James Van Der Beek 饰）和兰斯（保罗·沃克 Paul Walker 饰）是无话不谈的好友，与此同时，兰斯亦是小狼队中的强力前锋。然而，在一场十分重要的比赛来临之际，兰斯却因受伤而退出了球队，取而代之的，竟然是半吊子的马克斯。让大家都没有想到的是，马克思竟然干得不错，一下子，他从默默无闻的小卒成为了小镇英雄。可是，胜利带来了荣耀，却也带来了麻烦。','It takes a hero to know what\'s worth winning.',0,0,9.229999,6,122,106,'1999-01-15','en','/g2jX2Xmx7drbc6J9MLJEBghR7Mg.jpg',2.894971762983301,3,'2026-09-10',2,NULL,NULL),(14729,'大贼龙虎斗','The Long Riders','故事描述詹姆斯、米勒、杨格等三个美国西部犯罪中著名的兄弟家族在年轻时闯荡江湖的事迹。','\"All the world likes an outlaw. For some damn reason they remember \'em.\" - Jesse James',10000000,15795189,2.959547,6.6,50,99,'1980-05-12','en','/1Dk9dieSkZeiEVarZFsPJdF9Qel.jpg',2.7037194846376997,3,'2026-09-10',2,NULL,NULL),(14736,'爱情和篮球','Love & Basketball','昆西（欧玛·艾普斯 Omar Epps 饰）和莫妮卡（桑娜·莱瑟 Sanaa Lathan 饰）从很小的时候起就在一起玩了，是青梅竹马的玩伴，两人之间的感情非常的要好。莫妮卡虽是女孩，但是打得一手好篮球，她矫健的身姿深深的吸引了昆西的注意，也让昆西对篮球这项风靡世界的运动产生了浓厚的兴趣。\r 随着时间的推移，昆西和莫妮卡都渐渐的长大了，他们发现他们对彼此的感情，逐渐从友情转变成为了爱情。就这样，两人的感情升级换代了。为了实现心目中的篮球梦想，昆西和莫妮卡携手共进，直到有一天，昆西告诉莫妮卡，他决定不念书了，他要辍学去打职业篮球，这也就意味着，他将要离开莫妮卡的生活。','All\'s fair in love and basketball.',20000000,27728118,2.027393,7.4,88,124,'2000-04-21','en','/zNZWNX19FZ5QyedprVM0ldsXFiP.jpg',2.8547373163692553,3,'2026-09-10',2,NULL,NULL),(14745,'如影随形','The Haunting of Molly Hartley','高中生莫利（海莉·贝内特 Haley Bennett 饰）和母亲莉亚（玛琳·辛科 Marin Hinkle 饰）过着相依为命的生活，尽管母亲和父亲离异，但莫利的生活依旧可以用无忧无虑来形容。一天夜里，母亲怪异的举动吓坏了莫利，在不知道发生了什么的情况下，母亲突然凶神恶煞地扑向了莫利，企图将她杀死。以此为契机，莫利快乐的生活被彻底的改变了。','Her past is yet to come.',0,0,8.309894,4.3,48,82,'2008-10-31','en','/XSy8BKHIa19yMAt7XyO2s9oIT5.jpg',2.664244479167984,3,'2026-09-10',2,NULL,NULL),(14757,'奥萨玛','Osama','塔利班关闭医院后，一名12岁的阿富汗女孩和她的母亲失去了工作。母亲自觉别无选择，只得将女儿伪装成男孩。化名“奥萨玛”的女孩，就此踏上一段令人恐惧又困惑的旅程，竭力避免塔利班发现她的真实身份。[United Artists]','To save her family a girl must become a boy',46000,0,1.447734,6.3,32,83,'2003-05-20','ps','/pOKz4zpccIjdib2pfDRkg69Ojej.jpg',2.5987119823931644,3,'2026-09-10',2,NULL,NULL),(14758,'好家伙','Good Dick','女人（玛莉安娜·帕卡 Marianna Palka 饰）是一个家财万贯的千金大小姐，男人（杰森·雷特 Jason Ritter 饰）是一个默默无闻的录像店打工仔，在这两个风马牛不相及的人之间，会发生怎样的故事呢？ 为了缓解内心的苦闷，女人不断的租借着色情录像带，男人对这个经常光顾的神秘女人产生了兴趣。一个借口之下，男人住进了女人的公寓，虽然女人的行为举止神秘莫测，但男人除了微笑着忍让并没有任何微词。随着时间的流逝，男人的温柔和体贴渐渐融化了女人心中的坚冰，但女人无法控制自己反复无常的脾气，因此常常给两人带来伤害。在误会和矛盾之中，男人和女人的身影渐行渐远，他们能够将这段坎坷的感情进行到底吗？','A hard man... is good to find.',0,0,1.948435,6.1,34,86,'2008-10-03','en','/a1DGYt4boLrfsHUnqbHxhUIVoe9.jpg',2.6100983438720267,3,'2026-09-10',2,NULL,NULL),(14778,'遗言','Last Orders','根据英国当代著名小说家格雷厄姆·斯威夫特的小说《杯酒留痕》改编，弗雷德·谢波西导演。汇集了迈克尔·凯恩、汤姆·卡特尼、大卫·海明斯等一批老戏骨，“女王”海伦·米伦也出演了该片。因此，影片也被戏称为英国演技派的“十一罗汉”。讲了一群退伍老兵，采用了大量的倒序手法。故事的主线是这群人遵循杰克·道兹的遗愿，从伯蒙德西前往马盖特，要将他的骨灰洒向大海。',NULL,0,0,3.603842,6,22,109,'2001-09-10','en','/rcc3eL3wcydEUmXpX1tW9ro8NR9.jpg',2.521887805979625,3,'2026-09-10',2,NULL,NULL),(14799,'供您决定','For Your Consideration','Three actors learn that their respective performances in the film \"Home for Purim,\" a drama set in the mid-1940s American South, are generating award-season buzz.',NULL,12000000,5542025,4.330428,5.9,43,86,'2006-11-22','en','/fvXClgY4ZJ7dBxalFuxPgb4nJ9s.jpg',2.6618450041881965,3,'2026-09-10',2,NULL,NULL),(14811,'屋顶上的小提琴手','Fiddler on the Roof','沙皇专制时期俄国的一个村子中，农夫特维（托波尔 Topol 饰）与妻子女儿住在乌克兰族的犹太人居住区里，虽然经常忍受来自非犹太居民的歧视，他却一直恪守传统生活着。村里来了一位贫穷的俄罗斯青年菲得卡，特维赏识他的才学，把他聘为家庭教师。渐渐地，各种挑战他的传统哲学的事情出现了。他想把大女儿特拉嫁给有钱的屠夫，特拉却爱上了贫穷的裁缝默特，相爱的两人坚决要在一起，特维不得不妥协接受两人的婚姻。二女儿夏娃爱上了家庭教师菲得卡，特维斩钉截铁地反对两个不同信仰的人相爱，为此与女儿断绝关系。当他和村民们被沙皇派人赶出村子时，准备投靠住在纽约的舅舅的一家人，遇到了也在逃亡的女儿夏娃和丈夫，在两人真诚的乞求中，特维放弃了自己所遵从的传统哲学，原谅了女儿的出格。对他来说，离开这里，就意味着抛弃传统，开始全新的生活。  　　本片获得第44届奥斯卡奖最佳摄影、最佳音响、最佳配乐。','To Life!',9000000,83304330,7.623979,7.4,134,181,'1971-11-03','en','/fKv7FlfRsO2yH431QLYhpNPfkR5.jpg',2.976372446080844,3,'2026-09-10',2,NULL,NULL),(14823,'亡命英伦','London to Brighton','Duncan Allen（亚历山大•马特恩 饰）要皮条客Derek（强尼•哈瑞思 饰）找一个未成年的女孩来满足他恋童癖的欲望。  　　Derek让妓女Kelly（罗瑞恩•斯坦利 饰）在路边找到了离家出走的14岁女孩Joanne（乔治娅•格洛梅 饰）。就算十分不愿意，但面对Derek的威逼与金钱的诱惑，Kelly还是把Joanne带到了Duncan的家中。Duncan很快想要带Joanne带上房间，这时候两名女生都不安起来。直到听到Joanne的求救，Kelly冲上了房间。挣扎中，Duncan被Joanne刺伤了，重伤死去。  　　两名女生落荒而逃，她们逃到了布莱顿。回想前天晚上的事，她们都十分后怕。另一方面看到父亲被杀的Stewart，找到了Derek要求他一天时间内找出两名女生。  　　Kelly与Joanne还是被Derek找到了，Stewart在一片空地上等待，他要Joanne告诉他事发的经过。Joanne与Kelly都以为自己凶多吉少，却没想到枪口并没有指向她们……','Innocence has nowhere to hide',0,0,3.060685,6.5,34,85,'2006-12-01','en','/gIWaX9DXgUVesbiJceitZirTyj2.jpg',2.61799025003653,3,'2026-09-10',2,NULL,NULL),(14834,'难以破解','Not Easily Broken','戴夫（摩里斯·切斯塔特 Morris Chestnut 饰）和克拉丽丝（塔拉吉·P·汉森 Taraji P. Henson 饰）曾经是朋友们心目中的神仙眷侣，在他们携手步入婚姻殿堂的时候，两人亦坚信，他们就是天设地造的那一对，是彼此生命中的唯一。\r 然而，随着时间的推移，再浓烈的情感都会受到磨损，戴夫和克拉丽丝个性上的差异在时间的流逝中显现的愈发明显。戴夫喜欢与世无争的生活，克拉丽丝则将此视作是一种懈怠，在一次又一次无果的争吵之中，两人的婚姻逐渐产生裂痕。在这个节骨眼上，一场车祸的意外发生让克拉丽丝不得不卧床休养，这是否能够给这段即将走入坟墓的婚姻带来转机呢？',NULL,0,0,5.1299,6.3,9,99,'2009-01-09','en','/8gmdToawg8gaSe9yWZjQ10v7noL.jpg',2.346186196636127,3,'2026-09-10',2,NULL,NULL),(14836,'鬼妈妈','Coraline','本片根据畅销小说改编而成。卡洛琳是一个充满好奇心的女孩，她在新家里发现了一扇神秘的门，通过那扇门，她进入了一个与现实平行的世界。表面看来，这个世界只是现实世界的镜像复制，其中的事物与现实里的几乎一模一样，但却充满了奇幻。在这里卡洛琳碰见了很多奇怪的人，包括她的“赝品母亲”，后者想将其永远留在这里。而卡洛琳必须依靠自己的机智、决心和勇气，才能重回现实，拯救自己的家庭。  10来岁的小女孩卡洛琳天生就有一颗好奇的心，凡事都喜欢问个究竟，不过她的父母却对她管教甚严，所以卡洛琳虽然有着打破砂锅问到底的精神，但也只能乖乖听父母的话。父母决定乔迁新居，搬到了新家的卡洛琳，来到了一个全新的环境里，这里大大的激发了她的好奇心。她开始对周围的邻居感到无比的新奇：有一个老头子，最大的乐趣就是整天在家里训练他自己的马戏团，这个马戏团可了不得，因为马戏团里的小丑，都是一只只可爱的小老鼠；除此之外，还有俩姐妹，整天的爱好就是你骂我，我骂你，生活还特别的古板。  玩了没多久，卡洛琳对这个新的居住环境渐渐的熟悉了，她开始觉得有些无聊。这时候，她又开始在家里找乐子玩，终于，让她发现了一个大秘密：客厅里，原来有一道她从来没有进去过的门！卡洛琳细心了数了数家里的房门，却在怀比送的娃娃的指引下，找到了一扇小门，这扇门究竟通往哪里呢？一天深夜里，卡洛琳鼓起勇气，打开了房门……  在房门背后的那个世界，有着和卡洛琳的世界相似的样子，还有一个自称为卡洛琳“另一个妈妈”、长着纽扣眼睛的家伙（或许她是个更完美的妈妈）。但事情渐渐变得越来越奇怪。原来，“另一个妈妈”是个可怕的怪物，她要做的是把卡洛琳永远的留在这个世界中，她绑架了卡洛琳真正的父母、甚至要为她缝上纽扣眼睛！在一只高傲的黑猫和三个鬼魂的帮助下，卡洛琳必须勇敢起来……','Be careful what you wish for.',60000000,124596398,51.146047,7.3,1386,100,'2009-02-05','en','/4jeFXQYytChdZYE9JYO7Un87IlW.jpg',3.7551473631566217,3,'2026-09-10',2,NULL,NULL),(14844,'总统千金欧游记','Chasing Liberty','美国女孩安娜（迪.摩尔 Mandy Moore 饰）和其他18岁女孩看起来没什么不一样，一样的青春无敌、精力充沛，不过，她有一个当总统的父亲。因为她是第一女儿，所以她必须时时刻刻保持完美形象，生活永远在镁光灯下。而且福斯特总统对她很严厉，身边总有一队保镖贴身保护，安娜完全没有一点自由。 　　这次，安娜随父亲一起访问欧洲。本以为处处顺从父亲就能换来一点自由:晚上自由自在和好友加布里――法国驻美大使的女儿――去泡吧。没想到，性感火辣的两个美女在吧里竟然无人问津，原来又是父亲派来了保镖暗中护花。愤怒的安娜乔装打扮后撇下保镖逃出了酒吧，就此展开了她的“逃亡之旅”。','How do you fall in love with the whole world watching?',23000000,12,3.362045,6.1,152,111,'2004-01-09','en','/aGh5zpJSuxcx4lzFFbZ2QyY8wQP.jpg',2.9331546713620336,3,'2026-09-10',2,NULL,NULL),(14846,'爱情黑名单','Little Black Book','在工作上一帆风顺的史黛西（布莱特妮·墨菲 Brittany Murphy 饰）在爱情中却栽了大跟头，心思缜密而敏感的她十分在意男朋友德里克（朗·里维斯顿 Ron Livingston 饰）的过去，似乎只有知道了他交往过什么样的女孩，有过怎样的感情经历，他们两才算真正的情投意合。但是，令史黛西头痛的是，德里克却是一个对过去闭口不谈的男人，更要命的是，一次偶然中，史黛西发现德里克竟然和自己认识的一个超模有过一段情缘。\r 　　这一发现让史黛西对德里克的信任彻底垮台，一时间，无论德里克做了什么，都显得那样鬼鬼祟祟。在损友巴布（霍利·亨特 Holly Hunter 饰）的建议下，史黛西暗中开始了对德里克的彻底调查。','Have you ever been tempted to look inside his...',35000000,22034832,6.246199,5.2,112,111,'2004-08-06','en','/c6TD54dLIryqhQAOdGExy8Lie1l.jpg',2.8381035302280386,3,'2026-09-10',2,NULL,NULL),(14849,'死神有约：死后的生活','Dead Like Me: Life After Death','在 Rube Sofer 离开后，一个名叫 Cameron Kane 的新的死神头目接手了。他是个狡猾的商人，根本不在乎帮助新近死去的人。混乱接踵而至，引出了黛西和梅森最坏的一面，他们开始重新喝酒。当乔治收获了雷吉的一个新朋友时，乔治和雷吉第一次重新建立了联系。',NULL,0,0,7.864905,5.8,65,87,'2009-02-17','en','/ekzGiwleJbx0ei1R3s0ylowFKT9.jpg',2.7538364326978955,3,'2026-09-10',2,NULL,NULL),(14854,'独行侠野狼','Lone Wolf McQuade','一辆满载运火的卡车被劫走，为了全州安全，当局只好派出一位素以强悍，不按常规行事著名的德州警骑，负责侦办此案。为首的歹徒是几个狡诈缠的家伙，不但功夫高强，且又施展美人计，最后还绑走他的女儿远墨西哥，他该如何追击，转逆局势？','The \'Mad Dog\' Criminal...The \'Lone Wolf\' Lawman...The Ultimate Showdown.',5000000,12232628,8.452666,5.5,67,107,'1983-04-14','en','/dLVegSmoFM5ekThmUauuhnAOejb.jpg',2.753864196053827,3,'2026-09-10',2,NULL,NULL),(14869,'特种部队Ⅰ：眼镜蛇的崛起','G.I. Joe: The Rise of Cobra','最近，地球上出现了一个极其神秘的恐怖组织，它的名字叫“眼镜蛇”，而让“眼镜蛇”闻名全球的原因，则是源自其对埃菲尔铁塔的一次恐怖行动，在“眼镜蛇”的恐怖轰炸之下，这座法国的标志性建筑物顷刻之间化为乌有。很显然，“眼镜蛇”的这次行动只是一个开始，它向全世界宣告“眼镜蛇”的成立，而他们的目的则隐藏得更深，许多国家开始感到不安，因为他们不知道什么时候“眼镜蛇”的恐怖行径就会落到自己的国家当中，世界陷入了恐慌状态。联合国对此也感到大为棘手，因此这时候，总部设在布鲁塞尔的一支秘密行动小组就开始发威了他的威力。这支名为 G.I.Joe 的特种部队由霍克将军（丹尼斯·奎德 饰）担任领头羊，手下高手云集，副指挥官是公爵（查宁·塔图姆 饰），参加过越南的他曾经与霍克一起多次出生入死；红发女（蕾切尔·尼科尔斯 饰）是一个武术高手，她的身手可不比男人差；除此之外还有专职执行高空任务的开伞索（马龙·韦恩斯 饰）、会七国语言的通讯员“断路器”（萨伊德·塔马乌伊 饰）、军火专家“重载”（阿德沃尔·阿吉纽依-艾格拜吉 饰）、沉默寡言的“蛇眼”（雷·帕克 饰）等 12 名成员。他们开始追查行动，很快查明了“眼镜蛇”的的阴谋，而他们首先要解决掉的是给“眼镜蛇”提供军火支持的战争狂人的迪斯特罗（克里斯托弗·埃克莱斯顿 饰）。而“眼镜蛇”组织里也有着不少心狠手辣的铁腕人物，例如外表性感漂亮，心肠却狠毒如蛇蝎的“男爵夫人”（西耶娜·米勒 饰）就是当中的代表人物。除此之外，还有与蛇眼是兄弟的白幽灵（李秉宪 饰）。G.I.Joe 为阻止“眼镜蛇”的阴谋而与其展开大战，随着两方战斗的白热化，原本一直深藏不露的一位“眼镜蛇”重要成员也逐渐显露出真身，他的真实身份会令 G.I.Joe 的成员大吃一惊……','When all else fails, they don\'t.',175000000,302469017,32.852443,5.6,1962,118,'2009-08-04','en','/ej0HwuQXqGTXdN8BM19NyIrq9Fm.jpg',3.443137966750094,3,'2026-09-10',2,NULL,NULL),(14873,'森林王子2','The Jungle Book 2','在第一集故事中回到人类小村庄里的莫格利（海利·乔·奥斯蒙特配音）在新的家庭环境里变得焦燥不安，他总在心里听到来自森林的呼唤。他决定抛下新女友珊迪，重新回到森林的怀抱中去，继续从前自由自在的“森林王子”生活。  　 可事情并没有那么简单，重新回到森林的莫格利正面临着一场危机，从前的老冤家、老虎沙汉正在酝酿一场复仇计划，莫格利的老朋友大熊巴洛等一班好朋友能帮助莫格利逃出沙汉的魔爪吗？','Feel the jungle beat',20000000,135680000,19.819893,5.6,269,72,'2003-02-07','en','/9fpmSrfP4fLLAlGiwmO82BBVMfN.jpg',3.0532627689506557,3,'2026-09-10',2,NULL,NULL),(14877,'九月黎明','September Dawn','\"本片讲述的是19世纪一个罗密欧和朱丽叶式的爱情故事。故事以1857年9月11日发生的美洲历史上著名的高原惨案为背景，一批去往加利福尼亚的马车队路经犹他州南部，摩门教探知其中有1838年曾参与执行“清剿令”，强行将摩门教徒驱逐出密苏里州的Han\'s Mill惨案的凶手，随即作出复仇决定。他们暗中联合印第安人部落，对车队包围突袭，以上帝的名义击毙和处死120名男女，只有17名10岁以下儿童幸免。后来，参与指挥策划的摩门教首领John D.Lee被判死刑，20年后，摩门教领导人杨百翰的养子被判处死刑。因为电影所反应出来的观点，到今天这个事件一直饱受争议。\r 两个年轻人，一个是摩门教徒，是当地摩门主教的儿子，另一个是车马队牧师的小女儿，是从阿肯色州迁往加利福尼亚的移民，不管两个家族之间的仇恨多深，也不管世俗的看法多么顽固，两人还是萌生了美丽动人的爱情之苗，向对方倾诉自己的爱慕之情……\r 来源：时光网\"',NULL,11000000,0,3.646848,5,16,110,'2007-05-17','en','/hZomhyZMwrRk8D57BXz4xDcFT4H.jpg',2.450162998546553,3,'2026-09-10',2,NULL,NULL),(14902,'1776','1776','时值1776年，美国独立战争刚刚开始，国会一片混乱。约翰·亚当斯作为激进的政治家是国会的活跃分子，他积极地提出取得殖民地独立，建立美利坚联合国，并获得同是国会议员的富兰克林和杰斐逊的支持。提议一经提出，就遭到了近一半的国会议员的反对，尤其是以特拉华为首的一些顽固的保守主义者坚持认为，美国作为英国的殖民地，在英国的庇护下是最好的选择。而此时，英军已攻占纽约，与对方作战的华盛顿将军从前线带来的如供给不足、士兵气势不佳等坏消息，更给了他们足够的理由，反对美国独立。\r 　　亚当斯因其犀利的个性在国会被受争议，几经考虑，他决定让好友查德·李把议案正式提交给国会，并由富兰克林等人支持，希望能过得到讨论。但提议当天，查德·李德迟迟不来和其他国会议员的讽刺让亚当斯焦急万分，最后，他决定抱着最坏的打算自己提出议案。关键时刻，姗姗来迟的查德·李赶到，提出美国独立的议案。但同意和不同意各占一半让场面陷入了进退两难的境地，还好，酒醉出去的霍克金斯重新回到国会，处于微醺状态的他迷迷糊糊中投给了亚当斯一方一票，提议总算被正式提上了日程，予以讨论。\r 　　美国独立的议案进展缓慢，又陷入了一半同意一半反对的局面。为了打破僵局，亚当斯深刻地觉得应该起草一份独立宣言。而这个重任就自然落到了文笔出色的杰斐逊的手中，但此时，杰斐逊急于回家见妻子，哪里有心思起草独立宣言，一个礼拜过去了，独立宣言连个影子都没有。焦急万分的亚当斯灵机一动，把远在故乡的杰斐逊的妻子接来，这样，一篇洋洋洒洒的独立宣言才由此诞生。要通过美国独立的议案，可谓困难重重，但即使有再大的阻碍，也决不放弃。亚当斯等人几经奔波，终于，通过了该法案。','The award winning musical comes to the screen!',0,0,1.807571,7.1,20,142,'1972-11-09','en','/o50REDExdajGxTWczsmC3qcawGr.jpg',2.5069365831658885,3,'2026-09-10',2,NULL,NULL),(14914,'天才闪光','Flash of Genius','本片根据真实事件改编。鲍勃（格雷戈·金尼尔 Greg Kinnear 饰）是一名风度翩翩的大学教授，深受老师和同学们的喜爱。课余时间里，鲍勃喜欢搞些小发明，某日，他设想了一种能够自动刷除车窗上的雨水的装置——雨刷器，并且将它发明了出来。雨刷器刚刚问世，却并没有得到厂商的重视，可是，没过多久，鲍勃便发现，这种装置在未经过他授权的情况下，开始大量被底特律汽车制造商运用在它们的商品之上。愤怒的鲍勃一纸诉状将汽车厂商告上了法庭，没想到这场旷日持久的官司却将鲍勃和他的家人拖入了一个深不见底的漩涡之中。维权之路漫长而又艰难，期间，鲍勃甚至收到了对于他生命的死亡威胁。','Corporations have time, money, and power on their side. All Bob Kearns had was the truth.',0,0,3.350297,6.3,59,119,'2008-09-07','en','/14gyR9JMVfngQlolzD2N365ZeRz.jpg',2.7347229799305564,3,'2026-09-10',2,NULL,NULL),(14976,'蕾切尔的婚礼','Rachel Getting Married','当金姆回到布赫曼家族宅邸参加姐姐蕾切尔的婚礼时，她一并带回了漫长的个人危机史、家庭矛盾与悲剧记忆。新婚夫妇众多的亲友齐聚一堂，准备共度一个充满盛宴、音乐与爱意的欢愉周末，但金姆——凭借其尖酸刻薄的对白和引爆戏剧性场面的天赋——成为了这个家庭动态中长期暗涌矛盾的导火索。[索尼影业经典]',NULL,0,0,14.345428,6.1,163,113,'2008-10-03','en','/6lV9IL7EaAdB6Z2gCgJE8KZSg2K.jpg',2.9732804723776805,3,'2026-09-10',2,NULL,NULL),(15005,'与王一夜','One Night with the King','《与王一夜》来自圣经故事《以斯帖记》，女主角以斯帖是波斯女王，传说中她拯救了濒临灭绝的犹太民族。电影描写了犹太王后以斯帖（Esther）以人品和美丽赢得国王薛西斯（Xerxes）的欢心，从奸臣手中救了犹太人的命，帮助犹太人复仇的故事。','Feel The Touch Of Destiny',20000000,13391174,3.476925,6.1,12,123,'2006-10-13','en','/9ejzABqu2bqjuqSSUk5OwPAnedZ.jpg',2.3986347420472356,3,'2026-09-10',2,NULL,NULL),(15013,'哇哇岁月','Wah-Wah','原片名Wah-Wah代表什么意思？原来指称叽哩咕噜的非洲土话，一方面摆明讽刺当地英国白人统治阶级明明鄙视却又刻意去亲近原住民的虚伪假面；另一方面对李察E葛兰来说，Wah-Wah是他烦恼苦闷时的忘情大喊，一种释放、一种情绪宣泄。集合了米兰达李察逊（Miranda Richardson）、茱莉华特丝（Julie Walters）及埃米莉华森三位杰出的英国女演员，李察E葛兰聪明又刻意地把琵琶别抱的生母、父亲新娶的继母两个身份代入政治批判。米兰达李察逊饰演的生母是个欲求不满的悲哀怨妇，担任殖民官的父亲（盖布瑞拜恩）象征着日渐萎糜的大英帝国，至于充满年轻活力却被当地保守上层阶级排挤的美国空姐继母，自然代表着美国新世界了。当剧情走到史瓦济兰脱离英国独立，主人翁瑞夫正巧也因为父亲健康一蹶不振而必须走出其羽翼，至此，政治暗喻已经非常明显了。独立的个体注定要脱离父权的五指山，生母早已离去，连继母也注定随着父亲过世而淡出瑞夫的生命。在结尾的画面里，所有中老年角色悄然退场后，只剩下三个年轻人的背影，然后瑞夫戴上了父亲那顶象征大英帝国旧日荣光的官帽……','Every family has its own language',0,0,2.356244,6.3,8,120,'2005-08-17','en','/awDKSn5dEJYJZXCQuXkoaQETzE2.jpg',2.316896468924195,3,'2026-09-10',2,NULL,NULL),(15017,'美眉的野心','Blonde Ambition','故事的主人公是一个金发美女，为了追寻不久之前去纽约发展的男友而随后来到这个城市，却发现男友早已变心。沮丧的她，为了养活自己，成了一名职业女性，却无意中成为两个企业主管为了谋取利益所争夺的棋子，在一系列跌宕起伏的遭遇过后，她终于找到了自己真正的另一半……','Small-town girl. Big-time dreams.',10000000,0,3.064563,3.9,29,93,'2007-12-21','en','/t3H5WVxxkNyFoaXfwKKkvKq7G0y.jpg',2.5539286108256825,3,'2026-09-10',2,NULL,NULL),(15028,'时光骇客','Clockstoppers','该片主要讲述了赞克·吉布斯偶然间从他父亲那数不清的发明物中发现了一块奇怪的手表并且偷偷据为己有后，开始奇妙之旅的故事。','The adventure of a lifetime, in a few mere seconds.',26000000,38793283,5.894163,4.9,89,94,'2002-03-17','en','/6XZJ58gStdLZV8uJyTRcA5bGNyi.jpg',2.784759251809045,3,'2026-09-10',2,NULL,NULL),(15037,'等不及说爱你','Can\'t Hardly Wait','普里斯自校花爱曼达高一时坐在他旁边座位时起，就为她神魂颠倒，但生性害羞的他却只感在心中暗恋，迟迟不敢表白，如今毕业舞会将至，爱曼达又正好刚与校队男友分手，他准备将那封已经改过几百万次的情书交给她……','Yesterday\'s history.  Tomorrow\'s the future.  Tonight\'s the party.',10000000,25605015,11.350382,6.1,122,100,'1998-06-12','en','/r3a5gGWfS0SDS9nriNrJzSSrErf.jpg',2.904118838286041,3,'2026-09-10',2,NULL,NULL),(15045,'胖子阿伯特','Fat Albert','An obese boy named Fat Albert and his friends Rudy, Mushmouth, Bill, Dumb Donald, Russell, and Weird Harold, pulls into trouble when they \"fall\" out of their TV world into the real world, where Fat Albert tries to help a young girl, Doris, make friends.',NULL,0,0,7.157635,4.3,69,93,'2004-12-12','en','/biA3teAO8xZQfdBfLIK9ATdfOkJ.jpg',2.7256284878970405,3,'2026-09-10',2,NULL,NULL),(15049,'好警察，坏警察','Bon Cop Bad Cop','冰球是令加拿大举国疯狂的体育项目，电视上，多伦多与蒙特利尔两地的评论员唇枪舌剑，电视前，分处两地的警员马丁 与大卫 却同样面对和子女沟通的障碍。一起发生在州界上的凶杀案让两人走到了一起，但法语区和英语区的差异为他们貌合神离的合作增加了不少佐料。以死者身上的纹身以及现场的直升机为线索，两人逐渐接近事情的真相，但那位纹身杀人狂的动作始终快他们一步，甚至在电视节目中直接向二人挑衅。在办案过程中，马丁和大卫求同存异增进了了解，幕后那位视出卖球队为叛国行为的狂热冰球爱好者也浮出了水面……','Shoot First Translate Later',8000000,12671300,5.069095,6.5,42,116,'2006-07-06','fr','/1dOG48LlY6as4zdRDByKXKMqkvU.jpg',2.6684310250541854,3,'2026-09-10',2,NULL,NULL),(15059,'迷失禁果','The Loss of Sexual Innocence','力克一生中的三个阶段，都从性开始：五岁对性产生好奇、十六岁初尝禁果及成年迷失自我，犯上填补不了的错。在肯雅长大的他，每个人生交叉点，都似乎遭性操控…',NULL,4000000,0,2.866934,5.2,9,106,'1999-04-29','en','/eVg5oHFnzEE51cZ8Tq1qe8iWMZk.jpg',2.3369896381238044,3,'2026-09-10',2,NULL,NULL),(15067,'好家伙、坏家伙、怪家伙','좋은 놈, 나쁜 놈, 이상한 놈','上世纪三十年代，世界局势动荡不安。日本入侵朝鲜，使得大批流亡者涌入与朝鲜接壤的中国满洲，这片荒芜的平原很快成为不法之徒的栖息场所和暴力乐园。  貌不惊人的小土匪尹道九（Song Kang ho 宋康昊 饰）只身打劫甘道线火车上的几名日本军官和银行家金丸。同一时刻，冷血匪首朴昌二（Lee Byung Hun 李秉宪 饰）亦率部众劫停火车，其间更与赏金枪手朴道元（Jung Woo-sung 郑宇成 饰）发生火拼。混乱中道九卷走日本人财物跳车逃跑，各方势力却对他穷追不舍。不久道九醒悟，原来土匪和军人的目标不在他手中的财物，而是一张大清国在满洲里的藏宝图……','A Fistful of Fun!',10000000,0,11.847324,7.1,193,130,'2008-07-16','ko',NULL,3.066789708904164,3,'2026-09-10',2,NULL,NULL),(15070,'终极斗士','Undisputed','加州沙漠的甜水监狱，在一群疯狂的犯人观众之中，监狱拳王蒙罗•哈金（韦斯利•斯奈普斯 Wesley Snipes 饰）再一次击败了他的对手。哈金曾是一名拳手，因杀人被判终身监禁，他凭借出色的拳击技术，在监狱之间的拳击联赛中蝉联十年冠军。此时，重量级拳击冠军“冰人”乔治•钱伯斯（文•瑞姆斯 Ving Rhames 饰）因强奸罪被起诉，被收押在甜水监狱。监狱众人认为蒙罗和冰人之间必有一战，阅拳手无数的狱中拳赛安排者——雷顿开始筹划两人的比赛。冰人坚称自己并未犯罪，利用自己拳王的影响力在狱中向监狱长施压，同时不忘挑衅蒙罗这种他根本看不上眼的狱中拳手。蒙罗在和冰人的对峙中尽落下风，早早就被监狱方面关入了单人牢房，二人的决战，似乎已不可避免……','Two Enemies ... The Mob ... The Ultimate Showdown.',20000000,12398628,17.227376,6.1,139,96,'2002-08-23','en','/ndzBPpHJWXnTRqKP2I47bEMVwhT.jpg',2.945591017681356,3,'2026-09-10',2,NULL,NULL),(15074,'生死雪域','Extreme Ops','六名年轻大胆、不知天高地厚的极限运动选手，千里拔涉来此挑战不可能的任务－－在千钧一发的冰暴雪崩前，拍摄一部超越人类极限的广告片，殊不知，这片冰雪笼罩的边缘地带，竟是国际恐怖分子的躲藏要塞，恐怖分子首脑更是恶名昭著的塞尔维亚战犯！在摄影小组无意拍摄到他们身影后，生怕秘密藏身地点暴光，便对这些手无寸铁的年轻人展开一场天上地下的狙击猎杀行动，另一方面，人类无法预测的大自然灾难，也蕴集巨大的能量，分秒逼近……','Fear is a trigger',40000000,10959475,2.911819,5,28,93,'2002-11-27','en','/qBernKX0bmIRbTYlfTZ7PK4kadx.jpg',2.559277274931497,3,'2026-09-10',2,NULL,NULL),(15092,'怒火攻心2：高压电','Crank: High Voltage','从直升机上坠落的切弗（杰森•斯达森Jason Statham 饰）并没有死，当他醒来的时候，正躺在一家黑诊所，几个蹩脚的香港医生正在做心脏移植手术。期间，小混混强尼万不时在身边干扰。手术后的切弗拥有了一颗Avicor公司的人造心脏以和一块腰带电池。医生告诉切弗，为了保持心脏的活力，他必须不停给身体充电。切弗认定是强尼万偷了他的心脏，所以疯狂追击。在性爱社交俱乐部，他碰巧搭救了妓女瑞亚（白灵 饰），在夜总会，他又见到了跳钢管舞的女友伊芙（艾米•斯玛特Amy Smart 饰）。夜总会的枪战，引来了警察，但是电棍只会给切弗充电。追到跑马场的切弗，为了摩擦充电，在众目睽睽之下出尽洋相。直到香港三合会老大唐金出现，切弗才真正了解心脏被盗的真正原因……','Stay Charged, Stay Alive!',20000000,34560577,35.542809,5.9,861,96,'2009-04-16','en','/9xR2yab5QAyyDzsadNZbfZt3vAx.jpg',3.348171646770205,3,'2026-09-10',2,NULL,NULL),(15121,'音乐之声','The Sound of Music','玛利亚是一个年轻活泼、热爱歌唱的奥地利修女，她到退役海军上校特拉普家中为他七个失去母亲的孩子担任家庭教师，用音乐和爱温暖了上校家七个顽皮的孩子，同样也融化了上校的心。纳粹德国吞并了奥地利，要求上校加入德国海军为其效力。忠于祖国的上校坚决不从。他们全家利用一次公开表演的机会在修女们的帮助下逃出了魔掌，奔向自由。\r 　　有趣的故事、悦耳的歌曲、美丽的山河、活泼的孩子、可爱的修女、温馨的人情、天真无邪的笑料，构成了这部曾打破影史上最高卖座纪录的歌舞片，并曾获最佳影片等5项奥斯卡金像奖。片中表达玛利亚对大自然热爱的主题曲《音乐之声》、轻松愉快的《孤独的牧羊人》、特拉普演唱的深情无限的《雪绒花》、欢乐有趣的《哆来咪》、以及可爱的孩子们在比赛和客厅里演唱的《晚安，再见！》等等，都成了我们记忆中最值得细细回味的旋律。','The happiest sound in all the world!',8200000,286214286,37.960289,7.4,941,174,'1965-03-02','en','/6DKMWqCivb22X6NBhk04lhare85.jpg',3.625214080298849,3,'2026-09-10',2,NULL,NULL),(15122,'泼辣新娘','Love Stinks','电视喜剧作家赛斯·威尼克（富兰史·斯图尔特 French Stewart 饰）似乎拥有完美的一切：事业有成的职业，好友成群的社交圈，最重要的是，他找到了人生中的完美另一半，美丽泼辣的女孩切尔西·特纳（布里吉特·威尔逊 Bridgette Wilson 饰）。爱情的火花在两人之间迸发燃烧，一发不可收拾。切尔西也认定赛斯就是自己的命中注定，非君不嫁。然而一切的天作之合却败在了一个小小的细节上。情人节当天，赛斯送给切尔西一个首饰盒。满怀期待的切尔西本以为是一枚订婚戒指，而出乎她意料的是，赛斯送给她的是一对钻石耳环。大失所望的切尔西暴跳如雷，大闹分手。甚至，切尔西怒言一定不会让赛斯好过，爱之战正式爆发。这对天造地设的准夫妻，又能否破镜重圆呢？',NULL,0,0,3.347885,5.4,11,94,'1999-09-10','en','/srHcbkCyQFfdmqt5rPQMshxp1Yt.jpg',2.37783994215773,3,'2026-09-10',2,NULL,NULL),(15158,'鬼追人2','Phantasm II','麦克进入居住了大批僵尸的坟场中，他遭到了来自四面八方僵尸的攻击。四周一片漆黑，恐惧和惊慌吞噬着他的心。为了生存，他只有拼命地漫无目的四处奔跑。然而，僵尸和恶魔在他气息的指引下紧紧地追赶着他，不知他能否逃出生机……','The ball is back!',3000000,7282851,5.003615,6.3,94,97,'1988-07-08','en','/cZ5mPtOXcvmg224oBM2k1db5Fnn.jpg',2.8404988433974503,3,'2026-09-10',2,NULL,NULL),(15173,'蔬菜宝贝历险记','Jonah: A VeggieTales Movie','这个一群可爱的蔬菜们的故事，开始于一次意外事故。 在一个月光皎洁的夜晚，一群驾驶着大篷车旅行的“蔬菜”们在大道上一边前进，一边快乐的唱歌。但是他们不小心与一群由“衣服”为主力组成的小团体发生了争执，于是引发了一场战斗。在和这伙晒衣绳、拳击短裤和豪猪等的作战中，“蔬菜”们的大蓬车出了事故，于是他们只好来到一个破旧萧条的海鲜市场寻求帮助。 　　在这里他们遇到了一群号称“什么事也懒的做”的海盗。在等待拖车帮忙的时候，他们与这群海盗坐在一起闲聊。海盗们讲了一个关于主人公芦笋约拿的故事： 　　故事发生在很久以前的另一个地方。主人公芦笋约拿是一个信使。不过他可不是一个普通的投递员，他是上帝的信使。约拿很喜欢自己的工作，一天，他接到一个任务，要他把信送给古亚述国尼尼微城的人们。 　　约拿不喜欢尼尼微人，因为他们不仅喜欢撒谎、偷窃，而且还喜欢用鱼砸人。于是，约拿不仅不着急去完成任务，却坐上了一家相反方向行驶的船。船的主人正是这群“什么事也懒的做”的海盗。在船上，他还遇到了一个地毯“商人”，毛虫卡里尔。 　　不幸的是，约拿被一只巨大的鲸鱼吞到了肚子里面。在鲸鱼的肚子里，又发生了一段惊险、刺激却又好玩的故事','Fresh Fish. Mixed Vegetables.',0,0,1.446172,6.4,22,82,'2002-10-04','en','/xJ6ImpQIqZxBh4eE2813ljQ0TQ3.jpg',2.5204772443621137,3,'2026-09-10',2,NULL,NULL),(15186,'正面全裸','Full Frontal','卡尔（大卫·海德·皮尔斯 David Hyde Pierce 饰）是一位小有名气的作家，他深深爱着自己的妻子李（凯瑟琳·基纳 Catherine Keener 饰），无奈落花有意流水无情，李的一片真心却全部放在了当红电影明星卡尔文（布莱尔·安德伍德 Blair Underwood 饰）的身上，即便如此，卡尔还是努力的为妻子创造着出人头地的机会。卡尔文因为一部名叫《尼古拉斯》的电影而获得了观众的认可，与此同时，凯瑟琳（朱莉娅·罗伯茨 Julia Roberts 饰）、古斯（大卫·杜楚尼 David Duchovny 饰）、尼基（尼基·凯特 Nicky Katt 饰）等人走到了一起。一天之内，导演展现了众角色之间错综复杂的关系，一场在贝弗利山庄举行的盛大生日晚宴将气氛烘托到了最高点。','Everybody Needs A Release',2000000,2506446,1.95686,4.8,26,96,'2002-08-02','en','/7FeoefSYELryi04Kz74xYTayPZk.jpg',2.5403631639684767,3,'2026-09-10',2,NULL,NULL),(15189,'狗狗旅馆','Hotel for Dogs','本片改编自由路易斯·邓肯(Lois Duncan)创作出来的一本深受读者喜爱的同名儿童读物。  　　16岁的孤儿安迪（艾玛·罗伯茨 Emma Roberts 饰）和弟弟布鲁斯（杰克·T·奥斯汀 Jake T. Austin 饰）被一户人家收养，但这家人却不允许他们养宠物。只能把与 他们相依为命的小狗“星期五”安顿在一所被废弃的旅馆中。旅馆虽然破旧，但是很适合狗狗居住。安迪、布鲁斯与朋友们开始改建旅馆，还发明创造出一系列方便实用的自动装置来帮助狗狗们“自给自足”。很快，这里成了越来越多流浪狗狗的甜蜜小窝。也让身为孤儿的安迪和布鲁斯有生以来第一次体验到了家的温馨与可贵。然而随着旅馆里狗狗的数量越来越多，“流浪狗旅馆”也引起了警察地怀疑，他们逐渐查到了这个地方。孩子们为了保护狗狗打算将其转移，一场斗智斗勇大战就要开始了……','No stray gets turned away.',35000000,73034460,13.25753,5.7,202,100,'2009-01-16','en','/xD2AssTeySNCamlGueai4yAZZfX.jpg',2.9909395815037074,3,'2026-09-10',2,NULL,NULL),(15198,'魂系冰球','Mystery, Alaska','秘密镇是阿拉斯加一个偏远的小镇，这里的人们酷爱冰球，小镇上有一支援棒的冰球队，只是他们不知道自己有多棒。杂志上说他们有全国第一流的实力，所以著名的”勇士队“要来与他们比赛。偏在这时队中的主力被个年轻人顶替了。主力于是想尽办法要重新归队，此时来采访的体育记者又与主力的妻子眉来眼去。随着比赛临近，小镇日益变成一个大马戏场，人人都卖力地在其中扮演着角色，突然有消息说”勇士队”不来了……','A Small Town on the Outskirts of Greatness.',28000000,8888143,4.436792,6,69,119,'1999-10-01','en','/bmg4sjOQswcrP5mPL9YzNom9cXx.jpg',2.7635427914623536,3,'2026-09-10',2,NULL,NULL),(15208,'吸血女伯爵','Bathory','天真可爱的伊丽莎白（安娜·弗莱尔 Anna Friel 饰）自幼嫁入贵族，肩负着振兴家世的的重任。适时战争不断，匈牙利的土地上未见安宁之地，伊丽莎白的夫家弗伦茨·纳达斯第（文森特·瑞根 Vincent Regan 饰）则在战争中愈加强大。弗伦茨连年征战在外，伊丽莎白则体验着孤独与无聊，她沉湎黑魔法、不伦之爱、蕾丝之情，更成为百姓谈及色变的吸血鬼女伯爵。真相在历史的长河中早已扑朔迷离，真正的伊丽莎白究竟如何无人得知…… 　　本片根据中世纪匈牙利臭名昭著的“吸血女伯爵”伊丽莎白·巴瑟（Elizabeth Bathory）的故事改编，并荣获2009年捷克金狮奖最佳艺术指导奖。',NULL,0,0,2.500218,5.6,31,141,'2008-07-04','en','/qZsQ02liDzz9Ydb1dzFwLxef7me.jpg',2.585790956893587,3,'2026-09-10',2,NULL,NULL),(15237,'小可爱','De-Lovely','电影改编自美国作曲家科尔·波特的生平。  　　故事发生在法国巴黎，美国人波特（凯文·克莱恩 Kevin Kline 饰）带着对未来的憧憬和远大梦想来到了这个处处充满了艺术气息的都市，在这里，波特结识了名叫琳达（艾什莉·贾德 Ashley Judd 饰）的美丽女子，琳达的出现重新唤起了波特对于女人的渴望，两人之间的关系迅速热络了起来，之后走入了婚姻的殿堂。  　　对于波特的事业，琳达十分关注，她将波特的作品推荐给了著名作曲家欧文（基思·艾伦 Keith Allen 饰），以此为契机，波特逐渐在业内站稳了脚跟。随着波特的逐渐出名，他和琳达之间的关系开始产生了裂缝，相爱但无法相守的两人沉浸在痛苦之中，一个家庭眼看就要破碎。',NULL,20000000,0,3.138118,6.3,32,125,'2004-07-02','en','/QBqiBQW7MGqlDSyvid4fKzS0Xz.jpg',2.6025731520877367,3,'2026-09-10',2,NULL,NULL),(15239,'毒魔复仇','The Toxic Avenger','讲述一个弱智的小伙子，他是健身中心的拖把清洁工，某天，他被玩弄，成了大众群体中的取乐笑柄，他不小心从楼上的玻璃窗摔了下来，意外地跌入了某种化学工业用途的废水里，身体受到了严重辐射创伤，基因突变~ 成了半兽怪人，他决定要复仇，向社会恶势力宣战…','He was 98lbs. of solid nerd until he became...',0,0,6.672008,6.3,113,82,'1984-05-01','en','/vuxRW5GKuCnKvdYlUAYNxlicm54.jpg',2.885024741943538,3,'2026-09-10',2,NULL,NULL),(15250,'今年圣诞节','This Christmas','雪莉（洛雷塔·迪万恩 Loretta Devine 饰）早年间被丈夫抛弃，丈夫留给了她六个孩子，坚强的雪莉将孩子们抚养长大，却发现已经长大成人的孩子们似乎并不领她的情。如今，孩子们似乎约好了一般的纷纷回到了她的身边，但雪莉知道，这背后的原因并不单纯。','You can\'t exchange family.',13000000,0,2.388918,7.1,29,117,'2007-11-27','en','/dBuLAw4mRlO83LPA2s4zOlVesUe.jpg',2.5891411582173114,3,'2026-09-10',2,NULL,NULL),(15256,'200支香烟','200 Cigarettes','露西及凯文是一对纯友谊的男女朋友，而彼此正苦于无伴侣。当沮丧的凯文正抱怨他的前任女友如何在他生日当天甩掉他的时候，露西正使出浑身解数去诱惑英俊的酒保。距离几张桌子之遥，坐着艾瑞克及布莉吉特，艾瑞克被指责为一个差劲的男朋友而遭布莉吉特抛弃。而布莉吉特与她的好友凯特琳在接下来的夜晚又在彼此争夺那英俊的酒保。总之，就是没人想在除夕夜回家。蒙妮卡一个人在家里痴痴的等着，因为没有人在她的舞会中。','It\'s 11:59 on New Years Eve... do you know where your date is?',6000000,6852450,3.561198,6.1,44,101,'1999-02-26','en','/ssbx2Mk5ZCJWpXALuP2AdG0GFIT.jpg',2.6683076629712734,3,'2026-09-10',2,NULL,NULL),(15268,'街头霸王：春丽传奇','Street Fighter: The Legend of Chun-Li','影片改编自著名格斗游戏，讲述了春丽从一个普通女孩成为一个格斗高手、最终为父报仇的故事。','Some fight for power. Some fight for us.',50000000,12764201,8.139676,3.9,112,97,'2009-02-27','en','/lbNemoc9bRIAIVck0e2cv1cgftN.jpg',2.790455233052487,3,'2026-09-10',2,NULL,NULL),(15301,'阴阳魔界','Twilight Zone: The Movie','电影由乔治·米勒、乔·丹特、约翰·兰迪斯和史蒂文·斯皮尔伯格四位导演所拍摄的四部短片所组成。\r 　　某一天，种族歧视者比尔（维克·莫罗 Vic Morrow 饰）乘坐着时光旅行机回到了过去，可是，在那里等着他的，却是被歧视和侮辱的可怕命运。\r 　　没有人知道布鲁先生（斯加特克罗索斯 Scatman Crothers 饰）从哪里来，他又有着怎样的过去，人们只知道，这个神秘的男人拥有能够让人返老还童的奇妙魔力。\r 　　海伦（凯瑟琳·奎南 Kathleen Quinlan 饰）遇见了名叫安东尼（Jeremy Licht 饰）的男孩，在他平凡的外表下面，隐藏了一个惊人又残酷的秘密。\r 　　没有人相信神经兮兮的瓦伦汀（约翰·利特高 John Lithgow 饰）的所言所语，因为他竟然声称一只巨大的怪兽出现在了半空中将一架飞机撕成两半，然而他的话真的只是胡言乱语吗？','You\'re travelling through another dimension. A dimension, not only of sight and sound, but of mind. A journey into a wondrous land whose boundaries are that of imagination. Next stop, the Twilight Zone!',10000000,29450919,12.902975,6.2,161,101,'1983-06-24','en','/sDWARc5aYTUKE8Y2FIGVgWXuI4K.jpg',2.97275860103137,3,'2026-09-10',2,NULL,NULL),(15365,'乌龙保镖','Witless Protection','拉里（王牌接线员拉里 Larry The Cable Guy 饰）从小就有着壮阔的英雄梦，帅气的拿着手枪追捕四处逃窜的犯人是常常在他梦中出现的景致，因此，他成为了一名小镇治安官。可是，现实是这样的无奈，自拉里上任以来，小镇上不仅没有发生过一起犯罪事件，甚至连个陌生人的影子都没有。','Protecting America\'s assets.',0,0,1.82184,4,26,97,'2008-02-22','en','/8oqQn2Yp0yc52mxZH1TDn6ByOb0.jpg',2.5317836107509666,3,'2026-09-10',2,NULL,NULL),(15373,'模范贱兄弟','Role Models','惠勒和丹尼兄弟俩是一对精力充沛却极度没有责任感，永远处于后进状态的推销员，他们因酒醉后的失控行为、搞坏公司的卡车而被法院判罚。在三个月的牢狱之灾和150个小时的社区服务之间，他们认为150小时比3个月更容易\"混\"，于是他们选择了社区服务。然而这两个只有一身蛮力且行为不端的傻大个儿，不可能成为年轻夫妇寻找临时保姆时的首要人选，而且他们连开列购物清单都不会。于是，法院改判他们去帮助一群有智力障碍或情绪障碍以致于不能适应社会和工作环境的孩子。　　一身酒气的惠勒被分配去调教好满嘴脏话、年纪小小就很好色的五年级学生罗尼，要让他学会，尊敬长辈；丹尼则要去去帮助害羞、被女朋友抛弃并对中世纪喜剧的角色着迷的怪人奥基，要让他成为一个真正的男人。一开始，他们除了挖苦、嘲笑和刺伤之外，会做的并不太多，但在社区中心主任向他们发出最后通牒后，他们必须认真对待这两个任务，因为如果他们不想在监牢里度过他们的惩罚期，就必须对这一群需要帮助的人给予真正的关心和帮助。','They\'re about to get more than they plea-bargained for.',28000000,92380927,24.917665,6.4,564,99,'2008-02-03','en','/97jX5kiHrU0hR9bAqWRpv6aTwtX.jpg',3.3043477180179672,3,'2026-09-10',2,NULL,NULL),(15389,'Metropolitan','Metropolitan','A sparkling comedic chronicle of a middle-class young man’s romantic misadventures among New York City’s debutante society. Stillman’s deft, literate dialogue and hilariously highbrow observations earned this debut film an Academy Award nomination for Best Original Screenplay. Alongside the wit and sophistication, though, lies a tender tale of adolescent anxiety.','Finally... A film about the downwardly mobile.',225000,0,1.014966,7,38,98,'1990-08-03','en','/852ZwTRj9tRxkGOT0Pu0Ep8yimk.jpg',2.6448322728940425,3,'2026-09-10',2,NULL,NULL),(15394,'银行经理','Owning Mahowny','布莱恩·哈曼尼是一个银行经理，他有两个难题：他是亚特兰大城一个天生的赌徒，另一方面他的银行经理职务又给了他可以支配20亿美元的特权。当他的赌债日益增加后，他发掘了一项创造性的计划，即让银行和赌业互相利用玩弄，但即使这项计划成功，他能从中脱身吗？','To some it\'s a game. To others it\'s a habit. But to Dan Mahowny -- beating the odds is everything',0,0,8.045488,6.8,37,104,'2003-05-02','en','/xQYKqpN6fD7Dc7Vu8xnShHPKDwe.jpg',2.6520199772624533,3,'2026-09-10',2,NULL,NULL),(15487,'那些最伟大的比赛','The Greatest Game Ever Played','20世纪之初，高尔夫球还只是英国贵族和绅士们的游戏，底层人民没有资格染指其中，它无疑是身份和权力的象征。少年弗朗西斯·奥密特出身平民家庭，读书之余他经常担任球童贴补家用。在这一过程中，对高尔夫球的热爱悄悄在他的心中生根发芽。他勤奋努力，且天资聪颖，渐渐成长为一名出色的业余选手。1913年，弗朗西斯有幸参加绅士云集的公开赛，它不仅有机会与自己的偶像哈里·瓦顿正面对决，还将成为改写高尔夫球史的重要人物……','Based on a True Story',25000000,15431177,7.538513,6.9,110,120,'2005-09-30','en','/cZW0R3DYYfQ2UyE06qXjJCs4gAS.jpg',2.904654490977151,3,'2026-09-10',2,NULL,NULL),(15489,'下雪的日子','Snow Day','没有什么时候比下雪天更酷的了，它又好象是什么人给你的最好的生日礼物，尽管此时并不是你的生日。下雪天就意味着不用上学，没有了约束和无穷无尽的乐趣。对于哈尔和纳塔列.布郎德斯通来说，下雪天里什么事情都可能发生。哈尔15岁了，在这个雪天，他决定向他的的梦中情人，高中生克莱尔.伯纳宣布他对她的爱慕之情，哪怕她可能根本没有在意过他的存在，哪怕他要面对她的那个准男朋友-库克.维勒的竞争。下雪天充满魔力，在哈尔的伙伴比尔和拉尼的支持下，这一天注定将要永远改变他一生的命运。而此时他10岁的妹妹也正在酝酿着她的一个计划……  当太阳升起在这壮丽的雪天时，哈尔是否将与克莱尔拥抱在一起呢，这是在情人节到来之际，献给你的一部最酷的喜剧片。','Roads closed. Schools shut. Rules were made to be frozen!',0,0,7.964289,4.8,51,89,'2000-02-11','en','/myTnHKy178rrd1oUG3GkEvc641G.jpg',2.684209934007206,3,'2026-09-10',2,NULL,NULL),(15511,'无所事事的海盗','The Pirates Who Don\'t Do Anything: A VeggieTales Movie','艾略特（Mike Nawrocki 配音）、乔治（Phil Vischer 配音）和塞其维克在同一间餐厅打工，每天重复着日复一日的枯燥生活，它们感到自己的灵魂正在繁重的工作中慢慢死去。三人的心中都有着各自的英雄梦，它们都觉得自己不会在碌碌无为中了却此生，然而残酷的现实预示着，这恐怖噩梦的预想或许就要成真。',NULL,0,0,1.800119,5.9,25,85,'2008-01-11','en','/hwawxSwOkjeld4eQLSkIyyYNnqO.jpg',2.5432644858887907,3,'2026-09-10',2,NULL,NULL),(15512,'大战外星人','Monsters vs Aliens','住在加州某小镇的美丽女孩苏珊·墨菲（瑞茜·威瑟斯彭 Reese Witherspoon 饰）即将和他深爱的男友德里克·迪尔特（保罗·路德 Paul Rudd 饰）走入婚姻的殿堂。可就在这关键时刻，她先是被一颗陨石砸到脑袋，继而全身发光变成一个身形高大头发雪白的巨人。她的变化吓跑了亲朋好友，随后一群全副武装的神秘之人将其抓获并囚禁起来。苏珊被军方带到52区的秘密基地，与来自地球各个角落的怪物们称为科学家们研究的对象。　　与此同时，一个藏有邪恶力量的不明飞行物正以极高的速度接近地球，它所带来的外星人加莱克萨哈（瑞恩·威尔森 Rainn Wilson 饰）扬言要摧毁地球，毁灭人类。人类奋起反抗，但是他们的武器在加莱克萨哈面前全部败下阵来。地球危在旦夕，人们把命运寄托在了苏珊及其怪物朋友的身上……','When aliens attack, monsters fight back.',175000000,381509870,36.167578,6,1423,94,'2009-03-19','en','/5pMxWyuVuI5JZ27geaCQpYUw8k3.jpg',3.47080688553824,3,'2026-09-10',2,NULL,NULL),(15544,'性事电影','Extreme Movie','本片讲述了处于青春期躁动时期的性启蒙事例：生性腼腆的迈克（瑞恩•平克斯顿 Ryan Pinkston 饰）总是无法对暗恋女生表白；弗瑞德（迈克尔•塞拉 Michael Cera 饰）本想约会网恋女孩，却走错了房间；当查克（弗兰奇•莫尼兹 Frankie Muniz 饰）小心翼翼地试探女友南希（克里斯廷娜•迪罗萨 Christina DeRosa 饰）得到肯定后，他享受到了性爱的快感，然而对方如狼似虎的样子却令他仓皇逃窜…… 学校新来了一个讲述青春期性教育的老师（约翰`法利 John Farley 饰），他的第一堂课就是让男孩女孩们自由组合，选择可能产生性行为的伙伴，此后，几乎每堂课他都以独特的方式讲授性知识，让那些青葱懵懂的学生体会到比性事更重要的东西……','UNRATED. A film with many happy endings...',0,0,8.148187,3.9,44,88,'2008-12-05','en','/3N5XjwUITJo5MFhvWCJHVJt8pAg.jpg',2.6411896271110593,3,'2026-09-10',2,NULL,NULL),(15556,'一见钟情','At First Sight','艾米（米拉·索维诺 Mira Sorvino 饰）是业内小有名气的建筑师，强大的工作压力让她有些喘不过气，为了放松，艾米来到了位于纽约北部的一个恬静小镇度假，在这里，她遇见了名叫维奇奥（方·基默 Val Kilmer 饰）的盲人按摩师。维奇奥拥有一双神奇的手，在他的抚摸之下，艾米的疲劳一扫而空，随后，两人坠入了爱河。\r 艾米在互联网上得知某地有一个医生有可能帮助维奇奥重见光明，在两人的共同努力之下，维奇奥最终找回了视力。然而，重新出现在眼前的这个光怪陆离的世界让维奇奥感到无法适应，而他和艾米之间的恋情亦因此走入了瓶颈，即便如此，善良的艾米还是一如既往地陪伴和支持着维奇奥。','Science gave him sight. She gave him vision.',0,0,5.778724,5.9,48,128,'1999-01-15','en','/w5BvOBk6B7882rbUOmI1GRbALuD.jpg',2.6881370528104833,3,'2026-09-10',2,NULL,NULL),(15568,'足球女将','Gracie','格蕾丝（卡莉·许洛德 Carly Schroeder 饰）出生在一个声名远扬的足球世家之中，有三个哥哥，兄妹之间感情十分要好。他们的父亲曾是一位十分著名的足球明星，因此足球这项运动贯彻了孩子们的整个童年。一场车祸夺走了哥哥约翰尼（杰西·李·索弗 Jesse Lee Soffer 饰）的生命，让整个家庭笼罩在悲伤和抑郁的氛围之下，足球作为开启伤心之门的钥匙也渐渐不再被提起。无法忍受的格蕾丝决定代替哥哥实现他再也无法实现的梦想——代替哥哥的位置，成为校队中的一份子。起初，包括父亲在内，所有人都反对和质疑着格蕾丝的决定，然而，随着时间的推移，格蕾丝用实力和努力证明了自己。',NULL,9000000,2955039,2.365328,6,17,97,'2007-06-01','en','/kxyI0dcToPz90OSL5zLl3Dmp6iH.jpg',2.466051084325327,3,'2026-09-10',2,NULL,NULL),(15581,'Who\'s Your Caddy?','Who\'s Your Caddy?','When \"street smart\" rapper Christopher \"C-Note\" Hawkins (Big Boi) applies for a membership to all-white Carolina Pines Country Club, the establishment\'s proprietors are hardly ready to oblige him.',NULL,0,0,2.881239,3.8,18,93,'2007-07-27','en','/5wBBy7y5woqSICjbQekzZjwJBe7.jpg',2.4630100970872517,3,'2026-09-10',2,NULL,NULL),(15582,'十八岁之狼续集','Teen Wolf Too','托德·霍华德和其他上大学的人一样年轻。他只有一件事使他与众不同：就像他的表弟和叔叔一样，他有能力成为一只狼。当他成为狼人时，各级的事情都会开始做得很好。但并不是一切都会像一开始看起来那么容易。随着他的性格突然改变，他也将失去他所爱的人，他必须重新考虑是否真的值得成为大学的明星。杰森·贝特曼在这部《十八岁之狼》续集中接替了迈克尔·J·福克斯，该续集以青年喜剧的语气讲述了一个十几岁的男孩变成狼人的冒险经历。','High school was easy. But college is a whole different ANIMAL.',0,0,4.103764,3.8,46,95,'1987-11-20','en','/unfbmoUTIsQzQF09RJZVN1GKr6b.jpg',2.637995488271698,3,'2026-09-10',2,NULL,NULL),(15624,'与女人们的对话','Conversations with Other Women','故事的男女主人公在一场婚宴上相遇，表面上看来，他们像是一对素不相识的陌生人，互相搭讪、调情，随后开了房。但随着谈话的深入，剧情到此这才真相大白，两人原来曾经相识，并且有过一段很深的爱恨纠缠，连数年后的这次相遇也是一场有意的安排……','There are two sides to every love story.',450000,973525,4.442355,6.2,38,84,'2006-06-07','en','/5iA72q3avmveCiOtx1Uaj22pgXI.jpg',2.6407617842332063,3,'2026-09-10',2,NULL,NULL),(15639,'卫生督查员','Larry the Cable Guy: Health Inspector','内容简介',NULL,0,0,2.184708,3.3,17,89,'2006-03-24','en','/vlPadYpBkSvgTbGFhYTDgacAOEM.jpg',2.4471659625866655,3,'2026-09-10',2,NULL,NULL),(15644,'狗仔队','Paparazzi','好莱坞明星莱拉米（科尔·豪瑟 Cole Hauser 饰）的成名让他梦寐以求的一切都变成了现实，而他所要为此付出的代价便是他的隐私。狗仔队的镜头和惹人烦的闪光灯无时不刻捕捉着他的生活细节，这一切莱拉米都可以忍受，可当那些镜头伸展到了他的妻子艾比（罗宾·汤尼 Robin Tunney 饰）和儿子的生活中去时，莱拉米发现事态的发展有些过火了。\r 　　被愤怒冲昏了头脑的莱拉米狠狠的揍了经常缠着他的四个狗仔，这不理智的行为虽然过瘾，但也为莱拉米带来了严重的后果。让莱拉米没有想到的是，经历了这一番波折，狗仔们非但没有收敛，反而更加猖獗，为了躲闪他们的镜头，莱拉米一家发生了车祸，伤亡惨重。在法律无能为力的情况下，濒临崩溃的莱拉米决定亲自出马，以其人之道还治其人之身。','One good shot deserves another.',20000000,16605763,9.149089,5.8,52,84,'2004-09-03','en','/m9swmQKxrbRTYY3wN2bWmRiebM4.jpg',2.7105699285837175,3,'2026-09-10',2,NULL,NULL),(15647,'谁吻了洁西卡','Kissing Jessica Stein','等回过神来时，杰西卡（詹妮弗·韦斯特费尔德 Jennifer Westfeldt 饰）才发现自己竟然已经踏入剩女的行列了，可怕的是，她早已经不记得自己的上一次约会是在什么时候，而下一次约会也同样貌似遥遥无期。一次偶然中，杰西卡在报纸上看到了一则征友广告，广告十分独特的引用了诗人里尔克的诗，杰西卡被吸引了，就这样，她结识了名叫海伦（茜瑟·朱尔杰森 Heather Juergensen 饰）的女人。\r 海伦同杰西卡一样，事业成功，感情空白，两个相似的女人一见如故，天南海北无所不谈。在欢快友好的气氛中，杰西卡发现她和海伦之间的关系慢慢的发生了变化，一种小鹿乱撞的感觉在本事异性恋的她的内心里升腾起来。在一个天雷勾地火的吻之后，她们的关系会向何处发展呢？','When it comes to love, sometimes she just can\'t think straight.',1000000,10013424,3.990215,5.9,48,97,'2001-04-21','en','/8b2g8QZRLTJMYyzc3HirTSRQpLW.jpg',2.6840517463065945,3,'2026-09-10',2,NULL,NULL),(15648,'超完美男人','The Perfect Man','单亲妈妈简（海瑟•洛克莱尔 Heather Locklear 饰）带着两个女儿霍莉（希拉里•达芙 Hilary Duff 饰）和佐伊一起生活。简虽然在照顾两个女儿方面得心应手，可是在处理自己的感情方面却弄得一塌糊涂，她总是和一个不怎么样的男人开始同居，然后很快出现问题，最后分手。简走马灯似的换男友可苦了两个女儿，她们跟着妈妈一起老是居无定所，从一个男友家搬到另一个男友家，从一座城市搬到另一座城市。\r 　　为了能过上正常人的生活，霍莉决定用自己的力量帮妈妈寻找一个可靠的完美男人。当发现简的同事心地善良的兰尼开始追求简时，霍莉正式开始行动了。她暗中以兰尼的名义给妈妈送花、发email、写情书，然而老实巴交不懂情趣的兰尼却迟迟未能赢得简的芳心。霍莉的行动进一步升级，然而，事情却开始慢慢失去控制。','Is it all too good to be true?',0,0,11.158906,5.5,203,100,'2005-06-17','en','/sT4sCDXcqQBjAqyDaofkRmP0er5.jpg',2.9740322713653358,3,'2026-09-10',2,NULL,NULL),(15655,'跳跳虎历险记','The Tigger Movie','维尼（吉姆·库宁斯 Jim Cummings 配音）、小猪（约翰·菲尔德 John Fiedler 配音）、猫头鹰（Andre Stojka 配音）、小兔（Ken Sansom 配音）和跳跳虎（吉姆·库宁斯 Jim Cummings 配音）等朋友们正聚在一起，布置它们的新家，然而跳跳虎总是淘气的跳来跳去惹出一堆麻烦，于是小兔建议跳跳虎先去找其他的跳跳虎一起玩。然而，跳跳虎从来没有见过其他的跳跳虎，它甚至开始怀疑，这个世界里是否还有自己的同类。  　　博学多识的猫头鹰告诉跳跳虎，在家族之树上刻有问题的答案，于是，在朋友们的陪伴和帮助下，跳跳虎踏上了寻根溯源的旅途。一路上，它们历经艰险和磨难，友情亦受到重重考验，最终，会有怎样的结局等待着它们呢？',NULL,30000000,45554533,9.829859,6.3,143,77,'2000-02-11','en','/9OdZKUdGfaBAUwRLbtWpFWKbILO.jpg',2.944642162965057,3,'2026-09-10',2,NULL,NULL),(15660,'亲爱的妈咪','Mommie Dearest','在这本传记电影中，迷人但孤独的明星琼·克劳福德（Joan Crawford）接手了两个孤儿，起初他们的非常规家庭似乎很开心。但是，在Joan尝试浪漫实现之后，她与米高梅工作室的合同被解雇，她对她女儿克里斯蒂娜的冷酷和虐待行为变得更加明显。克里斯蒂娜离开家乡，承担起她的第一个角色，只有找到她母亲的存在仍然掩盖了她。','The meanest mother of them all',0,0,3.102862,6.5,54,129,'1981-09-18','en','/3Amv5uQfadEonn7SmYLfNnoeOSu.jpg',2.7190721204393693,3,'2026-09-10',2,NULL,NULL),(15670,'黑疯婆子闹监狱','Madea Goes to Jail','歌剧改编的黑人喜剧，本片讲述了一个妈妈级的黑人妇女不幸入狱，在监狱里与各色人等斗得死去活来的故事。',NULL,0,90508336,3.107371,6.4,52,103,'2009-02-16','en','/qiXNNmSFXsfUdKDkylBF2LfX0DR.jpg',2.708762838229419,3,'2026-09-10',2,NULL,NULL),(15673,'Connie and Carla','Connie and Carla','After accidentally witnessing a mafia hit in the Windy City, gal pals Connie and Carla skip town for L.A., where they go way undercover as singers working the city\'s dinner theater circuit ... as drag queens. Now, it\'s not enough that they become big hits on the scene; things get extra-weird when Connie meets Jeff -- a guy she\'d like to be a woman with','When you follow your dream, there\'s no telling what you\'ll become.',20000000,11341016,6.102663,6.4,24,98,'2004-04-16','en','/mR0K8S5s2c5uxpcevnVam17HFrh.jpg',2.5494421249664,3,'2026-09-10',2,NULL,NULL),(15699,'蛋白石之梦','Opal Dream','本片由人气童话《我的隐形朋友》改编。一个关於存在於想像世界朋友的感动故事。8岁的Kellyanne有一个非常理想主义的父亲Rex，他是蛋白石矿的矿工。Kellyanne的母亲和11岁的哥哥支撑着这个家。她非常爱她的父母和哥哥。但是，除此之外，她还有两个非常要好的朋友Pobby和Dingan,有一天她发现她的两个死党不见了，身边所有人的生活从此起了不寻常的变化。女孩为此而生病了，原本怀疑妹妹失踪朋友真实性的哥哥开始著急，并发起全镇寻人的活动…',NULL,5000000,140666,1.458884,6.1,7,86,'2006-11-22','en','/3CNwFxtb3TYs1rzBsg9DnoPAbJS.jpg',2.288623755319729,3,'2026-09-10',2,NULL,NULL),(15708,'闪亮的日子','Latter Days','克里斯蒂安（韦斯利•拉姆齐Wes Ramsey 饰）是个同性恋者，他年轻英俊、风流倜傥，经常在朋友面前炫耀自己的风流史。这天，有四位年轻英俊的摩门教徒搬进克里斯蒂安的公寓。乐不可支的克里斯蒂安拿着一箱啤酒去窜门，可是他同性恋的身份一眼就被看穿了，被他们赶了出来。克里斯蒂安发誓一定要追到其中的一位英俊小伙阿隆（史蒂夫•山德沃斯 Steve Sandvoss 饰），一雪前耻。\r 　　克里斯蒂安经常撞见帮同伴洗衣服的阿隆，一次，他假装伤的很重，将好心的阿隆骗到了自己的公寓，两人的第一次就这样开始了。完事后，阿隆惊慌得不知所措，因为摩门教规禁止同性恋，可是克里斯蒂安却不以为然，阿隆气愤得大骂。这次之后，克里斯蒂安开始反思自己的人生，渐渐地，他发现生活除了游戏和性，还有其他更丰富的东西，他也发现，自己开始爱上了阿隆……','Aaron prays. Christian plays... Opposites attract.',850000,819939,5.424916,6.7,56,107,'2003-07-10','en','/rUJn97Ptu4cmqsIDn7T40QFTdNW.jpg',2.7366914554753548,3,'2026-09-10',2,NULL,NULL),(15745,'搞定','Made','鲍比（乔恩·费儒 Jon Favreau 饰）是一位热爱拳击运动的健壮男人，白天，他在建筑工地搬砖，晚上，他回来到夜总会，担任自己在那里工作的女友杰西卡（法米克·詹森 Famke Janssen 饰）的保镖，与此同时，鲍比还在为黑帮大佬麦克斯（彼得·福克 Peter Falk 饰）打工。\r 鲍比非常满意现在的生活，虽然穷了点，但非常的稳定，可是鲍比的朋友瑞奇（文斯·沃恩 Vince Vaughn 饰）却不这么想，他一心想要进入黑帮，过上翻云覆雨妻妾成群的生活。在鲍比的介绍下，瑞奇加入了麦克斯的帮派。一天，麦克斯交给了鲍比一个重要的任务，命令他前往纽约，就这样，鲍比带着瑞奇一起上路了。','Welcome to disorganized crime.',5000000,5476060,4.149628,6.3,55,94,'2001-07-13','en','/4HC6ieptXO2gjqbSEsfkOwsGubN.jpg',2.7213016710334186,3,'2026-09-10',2,NULL,NULL),(15765,'与爱何干','What\'s Love Got to Do with It','对黑人灵魂乐爱好者来说,蒂娜·特纳大概是各全盛时期最具代表性的女歌手,她1984年推出的专辑《独自跳舞》曾风靡全球,创下了500万张的销量。1991年,她的名字被载入摇滚名人堂,她还四次获得格莱美最佳摇滚女歌手奖。但是光辉生活的另一面却笼罩着家庭暴力的阴影,她的前夫艾克曾经长期虐待她。结婚18年后,蒂娜以家庭暴力为由提出离婚。但是这位精力充沛的女歌星没有把与家庭暴力的对抗止步于在自传中的揭露,而是进一步成立了“蒂娜·特纳家庭暴力援助中心”来帮助更多家庭暴力事件的受害者。','Who needs a heart when a heart can be broken?',0,0,7.921311,6.9,72,118,'1993-06-09','en','/btC4819GhihmkCELqO3qgepNGos.jpg',2.8047858029039356,3,'2026-09-10',2,NULL,NULL),(15797,'Only the Strong','Only the Strong','Former Green Beret Louis Stevens returns to his hometown of Miami after completing military service in Brazil, only to learn that his old high school has become a haven for gangs and drug dealers. After Stevens uses his capoeira skills to kick several drug dealers off of the school property, Kerrigan, one of Stevens\' old teachers, sees the impact that Stevens has on the students. Kerrigan gives him the task of teaching Capoeira to a handful of the worst at-risk students at the school.','The ultimate martial art.',6000000,3283371,5.411243,6.9,29,99,'1993-08-27','en','/pPWV5rBhCgzlzhwkpdRG7a7UZqt.jpg',2.5937475024135868,3,'2026-09-10',2,NULL,NULL),(15800,'星舰家族','Trekkies','1997年，正是star trek最热的时候。TOS刚刚过了30岁生日，TNG才结束几年，DS9正在进入最后最精彩的几季，VOY刚刚开始头几季，这也是在ST的历史上首次有二套剧同时初播。trekkies 1是1997年拍摄的第一部电影，讲述ST迷自己的故事，剖析ST现象。trekkie这个词发明于1967年，也是牛津字典中唯一收录的粉丝群名字，足见其影响之深远。而克林贡语更成为第二大虚拟语言（第一是“世界语”），甚至连google都提供克林贡版。采访者是TNG中女安全官及那个罗幕伦女高官的扮演者，片长一个半小时。',NULL,0,0,2.77754,6.3,22,86,'1997-10-18','en','/o6MYZAcI2A7VfJkcIvCDbFPISLP.jpg',2.5226388555507637,3,'2026-09-10',2,NULL,NULL),(15875,'珊岛乐园','Donovan\'s Reef','二次大战结束后，在法属的哈里阿克洛群岛上，一位有妻室的威廉戴医生（约翰·韦恩饰）深爱着这里的一位土著公主，为了她威廉医生舍弃了美国拥有的千万家产与公主结婚，并育有二女一男。几年以后，在美国长大的女儿艾蜜莉（伊丽莎白·艾伦饰）辛辛苦苦的找来，但是为了隐瞒医生再婚的秘密，便由唐纳文叔叔冒充孩子们的父亲，岛上的总督安迪贪恋艾蜜莉的家产，处处对艾蜜莉挑拔示好，但是艾蜜莉仍识破他的诡计，与弟妹相认，并与心地善良的唐纳文（李·马文饰）结合。','Gangway...For This Years BIG Adventure!',2686000,6600000,1.897263,6,30,109,'1963-06-12','en','/xxZ6VUmnsxNiMa812IP3ohUf3BS.jpg',2.58246067926931,3,'2026-09-10',2,NULL,NULL),(15907,'小豹杜玛','Duma','故事发生在异域国度南非，讲述一只名为杜玛的猎豹与勇敢少年赞之间牢不可破的友谊羁绊的震撼冒险故事。[华纳兄弟]','Some friendships are wilder than others',12000000,0,4.795244,6.9,41,100,'2005-04-22','en','/wot6NjxJYg63qtrRMZv5RCztz8k.jpg',2.66894744406117,3,'2026-09-10',2,NULL,NULL),(15927,'A Passage to India','A Passage to India','The film is set during the period of growing influence of the Indian independence movement in the British Raj. It begins with the arrival in India of a British woman, Miss Adela Quested (Judy Davis), who is joining her fiancé, a city magistrate named Ronny Heaslop (Nigel Havers). She and Ronny\'s mother, Mrs. Moore (Peggy Ashcroft), befriend an Indian doctor, Aziz H. Ahmed (Victor Banerjee).','David Lean, the Director of \"Doctor Zhivago\", \"Lawrence of Arabia\" and \"The Bridge on the River Kwai\", invites you on . .',8000000,27187653,9.548391,6.9,67,163,'1984-12-14','en','/rx2PathbXFy0qy3P0NvA94hkBbE.jpg',2.791744122435061,3,'2026-09-10',2,NULL,NULL),(15976,'泡沫','הבועה','路路（Daniela Virtzer 饰）、诺姆（欧哈德·诺勒 Ohad Knoller 饰）和叶利（阿隆·弗莱德曼 Alon Friedman 饰）等人居住生活在一起，整日过着无所事事的闲散生活。安于享乐的他们不关心政治，对外界发生的种种更是一无所知。\r 　　某日，诺曼偶然之中遇见了名为阿什拉（约塞夫·斯威德 Yousef \'Joe\' Sweid 饰）的男子，阿什拉的英俊和善良很快就吸引了诺姆的注意，两人迅速陷入了情网无法自拔。然而，让诺曼感到痛苦的是，阿什拉是巴勒斯坦人，而他是以色列人，这两人的结合，在周遭看来，简直荒唐的如同一个笑话。与此同时，路路和叶利之间的爱情亦产生了问题，两对恋人在世俗和流言的夹缝之中该如何生存？',NULL,0,0,1.49436,7.6,20,114,'2006-06-06','he',NULL,2.510229536485617,3,'2026-09-10',2,NULL,NULL),(15983,'大侵袭','Invasion U.S.A.','一人部隊羅禮士這回要拯救全美國了！劇情簡介 一個退休的美國中情局探員麥特杭特（查克羅禮士飾）防禦的是整個美國免於受俄羅斯恐怖份的威脅。當俄羅斯恐怖份子入侵佛羅里達州並想接管整個國家 ...','America wasn\'t ready...but HE was!',0,0,4.192064,5.3,49,107,'1985-09-27','en','/uwVCRwgMQ6joWHf6cSiqKZU1kJO.jpg',2.6774777333486304,3,'2026-09-10',2,NULL,NULL),(15992,'失魂落魄','Abandon','凯蒂（凯蒂·霍尔姆斯 Katie Holmes 饰）是一名即将毕业的大学学生，怀揣着对步入社会的憧憬，凯蒂这段时间正在马不停蹄的忙着她的毕业论文和答辩。一天，一个名叫韦德（本杰明·布拉特 Benjamin Bratt 饰）的探员找到了凯蒂，命令他协助调查，调查的对象是凯蒂的前男友埃姆雷（查理·汉纳姆 Charlie Hunnam 饰），他在某一日忽然失踪，从此再也没有过音信。\r 埃姆雷的出现让凯蒂十分的困扰，因为她再也分不出多余的精力去应付这个缠人的男人了。与此同时，埃姆雷也有着自己的烦恼，他刚刚只好自己的酒精成瘾症，而这次的案件是他证明自己在警队中的能力的唯一机会了。','Watch who you leave behind.',25000000,10719357,3.888776,4.6,45,99,'2002-10-14','en','/7zRmopB7pnveyhFaCRSMZMiGO0v.jpg',2.647641903407774,3,'2026-09-10',2,NULL,NULL),(16005,'The Lucky Ones','The Lucky Ones','The story revolves around three soldiers — Colee, T.K. and Cheaver — who return from the Iraq War after suffering injuries and learn that life has moved on without them. They end up on an unexpected road trip across the U.S.',NULL,0,0,8.747922,6.3,55,113,'2008-09-26','en','/zZv0mXxd7kfyKuCLMyS0DFCk0JC.jpg',2.731805079394793,3,'2026-09-10',2,NULL,NULL),(16016,'土星之旅','Rejsen til Saturn','珀尔•杰森是丹麦飞碟协会的成员，他曾经为了接近心爱的姑娘苏珊而接受宇航员培训，对航天一窍不通的他考核失败，作弊的事情又被苏珊发现，两人分道扬镳。\r 　　多年后，丹麦大富翁库尔特•玛加以保护环境之名，声称要投资赞助土星之旅的航天计划。在出发前，航天队的领航员病倒，库尔特不顾技术顾问苏珊的反对，执意任命珀尔担任领航员的职务。在退伍老兵阿恩的率领下，这支极不专业航天队向土星进发。当他们抵达目的地时，却被当地的生物所抓获。不久，他们更得知这次土星之旅背后真正的目的……',NULL,0,0,1.776624,4.9,10,90,'2008-09-26','en','/lB8iKvq6UTDvp1C60JcALvdH1gX.jpg',2.353610459040752,3,'2026-09-10',2,NULL,NULL),(16028,'噩梦缠身','They','茱莉亚（劳拉·里根 Laura Regan 饰）是一位心理学系的学生，成绩优异的她正在准备着毕业论文的答辩工作，前途一片光明。某天夜晚，茱莉亚意外的接到了儿时好友比利（乔·阿布拉汉姆斯 Jon Abrahams 饰）打来的电话，比利的声音听上去充满了绝望与恐惧，他告诉茱莉亚，有某些邪恶而又恐怖的生物躲在黑暗之中，随时准备向他发起进攻，之后，比利自杀了。  　　在比利的葬礼上，茱莉亚与比利的大学校友山姆（伊桑·恩布里 Ethan Embry 饰）和特里（达格玛拉·多敏齐克 Dagmara Dominczyk 饰）相遇了，让茱莉亚感到震惊的是，山姆和特里竟然拥有着和比利相似的遭遇，勇敢的茱莉亚决定将此事调查个水落石出。','Are you afraid of the dark? You should be.',17000000,0,4.544216,4.6,74,89,'2002-11-01','en','/6i3ixJTacgdEAypVes6uUmsJr64.jpg',2.7398451621773514,3,'2026-09-10',2,NULL,NULL),(16052,'哭泣的玫瑰','Selena','墨西哥裔美国人赛琳娜（詹妮弗·洛佩兹 Jennifer Lopez 饰）从小就展现出了过人的音乐天赋，长相甜美可爱的她热爱唱歌和跳舞，这为她之后的人生历程奠定了坚实的基础。父亲埃布拉罕（爱德华·詹姆斯·奥莫斯 Edward James Olmos 饰）坚定的支持着赛琳娜向自己的理想前进，果不其然，没过多久，年纪轻轻的赛琳娜便成为了拉丁美洲最受欢迎的女歌手之一。  　　在事业蒸蒸日上的同时，赛琳娜邂逅了自己的一生挚爱，那就是之后成为了他丈夫的克里斯（乔恩·塞达 Jon Seda 饰），在亲人，爱人，朋友和歌迷会的陪伴下，赛琳娜来到了人生的顶峰。现在，这个快乐的女孩正在为打入美国乐坛而准备她的一张英语专辑……','Discover the true story of one of America\'s brightest stars... that faded too soon.',20000000,60000000,6.92592,7,114,127,'1997-03-21','en','/j8xX3yBAFOayfSaImgLZPnAcdWz.jpg',2.915976770875344,3,'2026-09-10',2,NULL,NULL),(16072,'众神与将军','Gods and Generals','《众神与将军》(Gods and Generals)名为《葛底士堡》的续集，其实是一部前传，算是赶了当今前传续拍的潮流。本片几乎完全由《葛底士堡》原班人马演出，只不过扮演传奇李将军的，已由马丁·辛改为另一奥斯卡级的老演员罗伯特杜瓦尔担任，而导演、摄影等幕后人员则基本不变，因而可以推断是和《葛底士堡》同一风格的。','The nations heart was touched by...',56000000,12923936,4.362535,6.1,48,214,'2003-02-21','en','/cgTb9rFEgAi2hq8B5AUABZHX8I.jpg',2.68861148145445,3,'2026-09-10',2,NULL,NULL),(16096,'House Party 2','House Party 2','Kid\'N\'Play leave their neighborhood and enter the world of adulthood and higher education. Play attempts to get rich quick in the music business while Kid faces the challenges of college.',NULL,0,0,3.673566,4.7,21,94,'1991-10-23','en','/4iKDkzUZtS6vzINfbwYHAb1bNbA.jpg',2.501509947610163,3,'2026-09-10',2,NULL,NULL),(16110,'魔幻铁路历险记','Thomas and the Magic Railroad','《魔幻铁路历险记》由最受孩子们欢迎的电视连续剧《火车头托马斯和他的朋友们》改编而成。该片秉承了原片无与伦比的魔法魅力，而且首次采用宽荧幕的形式向观众展示这种\"半真人演绎半动画制作\"的新派电影。 11岁的Lily（由Mara Wilson扮演）坐火车去她爷爷家玩。她爷爷（由Peter Fonda扮演）年轻时可是一名快乐的铁路工程师，但是现在过着孤独的生活。没想到Lily坐错了火车，最后在一个景色优美的小镇下了车。那个小镇名为\" 美丽时光\"， 在那里Lily遇上了一位会使魔法的列车长（由Alec Baldwin扮演），跟着他又上了火车，沿着\"魔幻铁路\"开始去苏达岛的探险之旅。要知道苏达岛可是一个玩具王国，可爱的Thomas（迷你型蓝色蒸气车头玩具）就住在那,但是现在这个\"世外桃源\"正在受到贪婪和愚昧的侵蚀。于是Lily 和Thomas联手，在小狗Mutt、小男孩Patch等其他许多好朋友们的帮助下，共同惩治坏蛋，最终使故事有了一个圆满的结尾。','Little Engines CAN Do Big Things...',0,0,1.916351,4.6,8,85,'2000-07-26','en','/aPEJ36e8a7gLu28KVfsGDQdmruk.jpg',2.3103514281512276,3,'2026-09-10',2,NULL,NULL),(16112,'艾莫奇遇记','The Adventures of Elmo in Grouchland','Elmo loves his fuzzy, blue blanket, and would never let anything happen to it. However, a tug-of-war with his friend Zoe sends his blanket to a faraway land, and Elmo in hot pursuit. Facing life without his cherished blanket, Elmo musters all of his determination and courage and heads off on an action-packed rescue mission that plunges him into Grouchland-a place full of grouchy creatures, stinky garbage and the villainous Huxley. Along the way, Elmo learns an important lesson about sharing, realizing that he was selfish with his friend and responsible for what happened.','The Good, The Bad and The Stinky.',0,0,3.09159,6.3,14,73,'1999-10-01','en','/u9i4frT1XPaTqJxRYLJ8j2r8LYO.jpg',2.429949909612212,3,'2026-09-10',2,NULL,NULL),(16148,'零办法','Zero Effect','冷血无情是私家侦探最须俱备的特质，戴瑞（比尔普曼饰）就因此成为世上少有的优秀侦探。他没有私人的牵扯，不会产生愚蠢的激情，只有工作。戴瑞的助理史提夫（班史提勒饰）则能言善道，让客户无法了解戴瑞神秘的生活方式。两人联手侦破了许多最棘手的案件，但这次却遭逢前所未有的挑战。木材业钜子史塔克（雷恩欧尼尔饰）遗失了保险箱钥匙，虽然要求戴瑞帮他寻找，却不提供任何线索、不透露一点讯息，也隐瞒他被勒索的内幕。此时，戴瑞又碰上从来没遇过的困扰一跟一名优美女子发生情感纠葛。他要如何在心思受绊的情形下侦查案件？那串遗失的钥匙又在何方。。。','The world\'s most private detective.',5000000,1980338,2.732031,6,55,116,'1998-01-30','en','/yFALvZFwqnh5ESarNoVd5KtizCo.jpg',2.7117452343459734,3,'2026-09-10',2,NULL,NULL),(16155,'冒牌高手','Safe Men','两个没有天赋的歌手 塞缪尔和埃迪 被卓普设计陷害去撬保险箱，从而被卓普的老大——黑手党老大误认为他们两人的能帮助他撬开保险柜，紧接着，两人的出人意料的命运开始了……','Welcome to the world of disorganised crime.',0,0,1.190729,6.3,16,88,'1998-08-17','en','/857L7x6uFNr4c2oHD5KJw5pkbxn.jpg',2.4529349873745487,3,'2026-09-10',2,NULL,NULL),(16158,'The Wood','The Wood','In the panicky, uncertain hours before his wedding, a groom with prenuptial jitters and his two best friends reminisce about growing up together in the middle-class African-American neighborhood of Inglewood, California. Flashing back to the twenty-something trio\'s childhood exploits, the memories capture the mood and nostalgia of the \'80s era.','From best friends to best men.',6000000,25059640,5.537646,7.1,34,106,'1999-07-16','en','/yEWMSJHkzMLgsTgsvR5TxuP3lBt.jpg',2.6316750788231387,3,'2026-09-10',2,NULL,NULL),(16161,'宝贝男孩','Baby Boy','讲述了20岁的非裔青年乔迪（Jody）在洛杉矶南区的成长故事。他虽已成年，却心理不成熟，没有固定工作，与母亲同住，并周旋于两位为他生下孩子的女友伊薇特和琵娜特之间，拒绝承担家庭责任。 当母亲开始与退役打手马尔文交往并同居后，乔迪被迫面对自己不能再依赖母亲的现实。在朋友“甜豆”的麻烦不断以及生活压力的逼迫下，他逐渐经历从男孩到男人的心理转变，开始直面责任与成长的阵痛。','Just a Baby Boy.',16000000,29381649,7.854989,7.4,55,130,'2001-06-27','en','/9dcic3zV5Gq6BQ1Et696qBtp9Xg.jpg',2.752932787371372,3,'2026-09-10',2,NULL,NULL),(16162,'伴郎','The Best Man','一名新锐作家，在某一个周末告别女友前往纽约，担任大学挚友(目前是知名橄榄球员)婚礼的伴郎。谁知道他即将出版的第一本小说的‘抢先版’，竟先被电视台工作的死党(也是他曾爱慕的女人)流出给大学时代的死党们阅读。尽管该小说注明要献给过去的大学死党们，但由于人物与内容皆是七分真实三分虚构，作家急欲在婚礼前收回该本‘抢先版小说’，以免发生任何事情妨碍婚礼的进行。于是，这一个周末，这一场婚礼，成了男主角人生中最关键的时刻，因为他必须同时面对自己的过去、现在，与未来。',NULL,9000000,34573780,3.951041,6.8,38,120,'1999-10-22','en','/ub2Njdn4kq49ndyg7QglnE8PUqT.jpg',2.6485640160661847,3,'2026-09-10',2,NULL,NULL),(16172,'魔法一点灵','Simply Irresistible','母亲去世之后，阿曼达（莎拉•米歇尔•盖拉 Sarah Michelle Gellar 饰）继承了母亲生前精心经营的餐馆。然而没过多久，阿曼达便发现，从前门庭若市的餐馆，如今生意一天不如一天，甚至濒临了倒闭的边缘。\r 　　一次偶然中，阿曼达邂逅了名为汤姆（肖恩•派特里克•弗兰纳里 Sean Patrick Flanery）的男子。之后，汤姆在机缘巧合之下来到了阿曼达的餐厅吃饭，让阿曼达感到不敢相信的是，汤姆的存在令自己的厨艺大增，餐厅就此度过了这次经营危机。随着时间的推移，阿曼达和汤姆之间的距离越来越近，然而，汤姆对于阿曼达产生的种种误会使得后者感到深深的受伤，两人之间的感情产生了裂痕。','Magic opened up their hearts... Love did the rest.',6000000,4398989,5.696491,5.5,52,95,'1999-02-05','en','/xbRj1bRGvm3E3mt6QVe08hHOIlV.jpg',2.6966868241075823,3,'2026-09-10',2,NULL,NULL),(16186,'一个疯黑婆子的日记','Diary of a Mad Black Woman','Charles McCarter and his wife Helen are about to celebrate their 18th-wedding anniversary when Helen comes home to find her clothes packed up in a U-Haul van parked in the driveway. Charles is divorcing Her. Helen moves in with her grandmother Madea, an old woman who doesn\'t take any lip from anyone. Madea helps Helen through these tough times by showing her what is really important in life.','Time heals the heart. Faith heals the rest.',0,0,3.784535,6.4,71,116,'2005-02-25','en','/4w36ckDhsWFPD9XaHOOJb1ru7JZ.jpg',2.778750521702639,3,'2026-09-10',2,NULL,NULL),(16205,'杰克.布鲁克斯：怪物杀手','Jack Brooks: Monster Slayer','杰克•布鲁克斯（Trevor Matthews 饰）是一个不起眼且运气颇差的水管工，他童年时曾目睹亲人被残忍杀害的恐怖场面，至今心中留有阴影；虽然有个金发美女作女朋友，却依然烦心事不断。  　　某天，迷迷糊糊的杰克无意中弄露了水管，一件年代久远的物体重现人间。杰克的夜校教授戈登（Robert Englund 饰）在检查时发现一颗跳动的黑色心脏。随后心脏钻入戈登教授口中。受到控制的教授化身为恐怖的恶魔，开始对周遭人类展开大规模的杀戮，情况万分紧急。  　　因偶然的过错释放出如此可怕的恶魔，杰克决定亲手将恶魔铲除……','...I used to be a plumber',0,0,2.659804,5.7,59,85,'2007-10-09','en','/xAieCaFdEiIwhHS7FKcltPDUnRc.jpg',2.7196588513789517,3,'2026-09-10',2,NULL,NULL),(16222,'爱你不论代价','Whatever It Takes','\"爱情是盲目的\"，没人比雷恩（尚恩卫斯特）更了解这句话的真意；雷恩爱上了全校最辣的金发美女艾希莉，却看不到其实真爱就在身边…或者该说就在隔壁-- 他的死党兼邻居玛姬身上；雷恩的表哥兼足球校队明星克里斯（詹姆斯法兰柯）看上了聪慧美丽的玛姬，因而向他提出交换条件，只要雷恩帮他追求玛姬，他愿意帮雷恩追求艾希莉；为了得到梦中情人的青睐，雷恩一口答应帮徒具外表的草包表哥追求玛姬，但雷恩不知道的是，克里斯并非真心喜欢玛姬，而仅是将她视为另一个猎艳的目标；如今毕业舞会在即，这场校园版\"大鼻子情圣\"将会如何收场呢？','How low will they go to get the girls of their dreams?',15000000,9902115,8.074807,5,37,94,'2000-03-31','en','/u9UtZNMj2m7dtOP6RcMAeRfqmnF.jpg',2.625983985691702,3,'2026-09-10',2,NULL,NULL),(16232,'三千大佬','Mr. 3000','十年前，斯坦·罗斯是名极具天赋的职业棒球运动员，长着一张大嘴的他还是个极其自负的家伙，幸运的他命中注定走上成功之路。当他完成确保进入棒球名人榜的第3000次安打之后，立即决定退出比赛，抛弃了处在困境中的队友。很快，罗斯开始了他的“Mr.30 00”商业计划，凭借这个传奇般的数字，他不断的满足着自我。而现在，最终认证罗斯进入名人榜之际，却节外生枝，他的3次安打记录遭到否定，转眼之间罗斯变成了“Mr.2997”。他只有一种选择，就是戒除不良嗜好，恢复训练，重操球棒，回到密尔沃基·布 鲁尔球队，这是体坛界极为罕见的复出。 47岁的罗斯不得不从一垒开始打起，失常的表现一度遭到非议，很快他变成了新闻的笑柄和球队的祸害，只有体育记者西蒙丝(安吉拉·贝赛特饰)还对他的实力深信不疑。随着赛季的延续，罗斯逐渐找回了当初的感觉，他开始意识到这并不只是数字的游戏，狂妄自 大的罗斯终于体会到了团队合作的乐趣，学会用道德规范约束自己，甚至坠入了爱河……','Big league. Big mouth. Big time.',30000000,21800302,2.850896,5,66,104,'2004-06-15','en','/g7CNkytZsZzQ8ZEr8F4SmrhjI5y.jpg',2.7256016895744617,3,'2026-09-10',2,NULL,NULL),(16241,'巴西来的男孩','The Boys from Brazil','利伯曼发现纳粹猎人拉到险恶和离奇的情节重振的第三帝国。','If they survive...will we?',0,0,5.315213,6.6,101,125,'1978-10-05','en','/w7IZT1HJNmWcEj3Axwlwhya02OX.jpg',2.868028428934816,3,'2026-09-10',2,NULL,NULL),(16281,'鬼作秀','Creepshow','全片分六段描述、恐怖的事，有鬼屋、杀人断头．．．．等，集恐怖之大成、饮血吸髓、包您大呼过瘾。','The Most Fun You\'ll Ever Have... BEING SCARED!',8000000,21028755,13.661289,6.7,226,120,'1982-11-12','en','/4SoyTCEpsgLjX6yAyMsx3AsAyRQ.jpg',3.0847270348551397,3,'2026-09-10',2,NULL,NULL),(16288,'鬼作秀2','Creepshow 2','本片以分段式描述三个令人毛骨悚然的恐怖故事。故事一：《Old Chief Wood\'nhead》一个印第安人还魂后为被谋杀的小士多店主复仇；故事二：《The Raft》池塘的食肉浮渣袭击小艇上的四个年轻人；故事三：《Dawn Of The Dead》富婆在和男妓风流后的返家途中意外撞死一名搭便车的男子……','When the curtain goes up, the terror begins.',3500000,14000000,10.729884,5.9,129,92,'1987-05-01','en','/bbanIymLuTYmQGis9nlCkFlT1eg.jpg',2.905667197889388,3,'2026-09-10',2,NULL,NULL),(16290,'蠢蛋搞怪秀3D','Jackass 3D','约翰尼·诺克斯维尔和斯蒂夫·噢、巴姆、胖子佩斯顿、矮人威曼等人再度集结，制作了全新的3D版蠢蛋搞怪秀。2000至2010，十年时光，记录了他们的青春和友情，这种友情不会因为受各种弹性装置发射的巨掌、棒球、水果的击打而消散；不会因为被故意置入充满蛇的陷阱、在空中翻飞或是爆炸的厕所等险境而倒退；不会因为尿水攻击、喝下对方的汗水、用万能胶拔体毛而反目成仇。他们拥抱彼此，还包括动物，他们用身体承受蝎子、狗、岩羊、驴、牛和蜂群的攻击，他们和新朋友“屁王”一起开怀大笑。不用怀疑，这部纪录片不仅是自毁式恶搞的集合，更是一曲友谊的赞歌。','Don\'t try this at home',20000000,117224271,20.99174,6.4,428,94,'2010-10-15','en','/uPirN07su7LFixyZyLrNMMQ9u1E.jpg',3.2298698171087685,3,'2026-09-10',2,NULL,NULL),(16300,'来去天堂','Down to Earth','小人物兰斯·巴顿（克里斯·罗克 Chris Rock 饰）一心成为一名专业喜剧演员，能在业余演员的殿堂阿波罗剧场成名更是他无上的梦想。但是他演技了了，时运不济，久久得不到出头的机会。某晚夜归，兰斯遭遇一场严重车祸，结果一命呜呼。他的灵魂来到天堂，却发现天堂工作人员搞错了名字。在天堂负责人金先生（查兹·帕明特瑞 Chazz Palminteri 饰）的帮助下，兰斯获准重返人间，不过由于他的身体已经毁坏，因此必须借助别人的身体还魂。\r 与此同时，曼哈顿大富翁威灵顿（Brian Rhodes 饰）刚被老婆（Jennifer Coolidge 饰）及其情妇杀害。为了接近心仪的姑娘，兰斯同意附身威灵顿，由此展开一段全新的人生……',NULL,0,0,9.166658,4.9,95,87,'2001-02-16','en','/w2XM4YCfBOOWEL4a0abQji7QxwI.jpg',2.8038865088114533,3,'2026-09-10',2,NULL,NULL),(16320,'Serenity','Serenity','When the renegade crew of Serenity agrees to hide a fugitive on their ship, they find themselves in an action-packed battle between the relentless military might of a totalitarian regime who will destroy anything – or anyone – to get the girl back and the bloodthirsty creatures who roam the uncharted areas of space. But... the greatest danger of all may be on their ship.','Can\'t stop the signal.',39000000,38869464,45.388937,7.4,1264,119,'2005-08-25','en','/4sqUOaPFoP2W81mq1UYqZqf5WzA.jpg',3.733521787092607,3,'2026-09-10',2,NULL,NULL),(16323,'歌声泪痕','The Rose','Rose（贝特·米德勒 Bette Midler 饰）从很小的时候起就不是人群中受欢迎的那一个，她十分自卑于自己的样貌，也从未获得过一段真正的友谊。在十七岁那一年，Rose对音乐燃起了热情，她加入了一支乐队，并且在旧金山一代打响了名气。Rose的音乐风格非常的随性和狂野，通过 尖叫和怒吼，她试图发泄出内心的郁闷。随着时间的推移，Rose的名气越来越大，她的梦想终于实现了——成为一名天王巨星。然而，成名带给她的除了金钱和利益外，却也有压力与痛苦。她放纵自己的欲望，贪图于享受声色犬马的乐趣，而这所有的一切，都是因为，在内心的深处，Rose依然觉得，自己是一个不被爱着的孩子','She gave and gave, until she had nothing left to give',9250000,29174648,7.000949,6.8,28,125,'1979-11-07','en','/3hYyA2g5r0TDRbkSAOEeKelylh2.jpg',2.5886062733607655,3,'2026-09-10',2,NULL,NULL),(16337,'德州电锯杀人狂2','The Texas Chainsaw Massacre Part 2','故事发生于德州电锯大屠杀事件的十三年后，警方一直无法破案，甚至找的尸体，然而电锯带给德州的恐惧却从未停止。探长域士决心要为当年被屠杀的兄弟报仇，多年来追查电锯食人家族的下落。\r 　　唱片骑师史琪芝在接听听众点唱时，无意中听到电话筒内传来惨叫和电锯的声音，她主动向域士提供线索并不断在电台播放那段声带，意图引起电锯食人家族的注意。不出所料，声带惹怒了电锯食人家族，一场血肉横飞，惨绝人寰的大决战即将展开','After a decade of silence... The buzzz is back!',4700000,8025872,9.617777,5.9,139,101,'1986-08-22','en','/qUpQtCAjyNLpndY9q1bACY6Q56H.jpg',2.918594591635738,3,'2026-09-10',2,NULL,NULL),(16340,'小鬼闯巴黎','Rugrats in Paris: The Movie','查克想要一个新妈妈，他的爸爸查斯也开始约会。查克的好朋友汤米的父亲被派去巴黎一家新开的游乐园修理机器人，他把一帮小鬼：汤米、查克、迪利以及莉莲等都带在他的身边。于是查克开始了一个伟大的冒险计划：给自己找一个新妈妈。','Ooo la la! Paris will never be the same!',30,103,4.590277,6,100,78,'2000-09-14','it','/grIL8mvfLznaWsv7EEEPhCpkH81.jpg',2.842350289537438,3,'2026-09-10',2,NULL,NULL),(16351,'烽烟岁月','Ararat','加拿大青年拉菲（David Alpay 饰）是亚美尼亚后裔，他的母亲安妮（Arsinée Khanjian 饰）是艺术史学者，最近新发表了关于亚美尼亚画家高基的著作。拉菲的女友西莉娅是继父的女儿，他的亲生父亲则死于行刺土耳其驻加拿大大使，西莉娅认为父亲的跳崖完全因为安妮，在公开场合对她的研究成果百般诘难。\r 导演索拉杨正在筹拍一部关于亚美尼亚大屠杀的影片，由于计划将少年时期的高基写入剧情，遂邀请安妮担任顾问，拉菲得以进入剧组帮手。拉菲将胶片带回加拿大时被海关安检扣留，因为女友有贩毒记录，拉菲一时难以脱身，开始向安检员讲述电影内容：1915年，土耳其军队包围凡城，破城后在亚美尼亚的圣山阿拉若山脚下展开了对亚美尼亚人的血腥屠杀……\r 本片获2003年吉尼奖最佳配乐、最佳艺术设计等多项褒奖。时空交错的剧本结构尤为精巧。',NULL,0,0,1.326264,5.7,16,115,'2002-05-20','en','/kQkn715VQYLIs2nddAUf19Bz5Wj.jpg',2.449375846164244,3,'2026-09-10',2,NULL,NULL),(16353,'拳霸2','องค์บาก 2','距今五、六百年前的泰国，时局动荡，阴阳逆反。邪恶阴险的军官Rajasena发动叛乱，夺取政权，为此展开大规模的血腥屠杀。少年泰恩出身于一个正直的武将家庭，他的父母双亲皆被叛军杀害。泰恩侥幸逃脱，然而才出龙潭，又入虎穴，他被迫与凶猛的鳄鱼同处一池。泰恩面对鳄鱼时的果敢引起夫毕克匪帮的头目车南的注意，车南将少年留在部落里，延请各路流派的好手教习泰恩格斗技巧。经过多年的磨练，泰恩（托尼·贾 Tony Jaa 饰）终于成长为身怀绝技的高手，并接任车南晋升为匪帮的新任首领。  　　虽然数年过去，但他始终没有忘记Rajasena加诸在其家族身上的厄运，他开始走上一条充满血腥和艰险的复仇之路……','Warrior. Conqueror. Legend.',8500000,8936663,9.029489,6,152,98,'2008-12-04','th','/svxO8AYCWXZ7f5Rikh94KRhA2U9.jpg',2.9409209435388726,3,'2026-09-10',2,NULL,NULL),(16358,'天才家族','Eulogy','一出黑色喜剧关于三代失和家庭因为家族长老丧礼而齐聚一堂，结果一桩桩关于家族的丑闻及秘密接二连三被赤裸裸拆穿。',NULL,0,0,9.085482,6.4,34,91,'2004-10-15','en','/u56l2hEhbiVHT4wcjBapcVtAtY6.jpg',2.6304142448880268,3,'2026-09-10',2,NULL,NULL),(16363,'春城花满天','The Best Little Whorehouse in Texas','当一位大电视斗士梅尔文·P·索普威胁要让养鸡场暴露在公众丑闻中并将其关闭时，莫娜小姐并没有不战而退。','With Burt and Dolly this much fun just couldn\'t be legal!',35000000,69701637,4.189378,5.9,41,114,'1982-07-23','en','/yw3PNR3NVeKKfLWv8SgFQnXoHZh.jpg',2.651577675066877,3,'2026-09-10',2,NULL,NULL),(16388,'The Brothers McMullen','The Brothers McMullen','Deals with the lives of the three Irish Catholic McMullen brothers from Long Island, New York, over three months, as they grapple with basic ideas and values — love, sex, marriage, religion and family — in the 1990s. Directed, written, produced by and starring Edward Burns.','Sometimes the Best Friends Are the Ones You\'ve Known Your Whole Life.',0,0,1.578903,6.3,23,98,'1995-08-09','en','/6oWsOJP0ed5gs8n2UywcailoxFN.jpg',2.5292152564654895,3,'2026-09-10',2,NULL,NULL),(16406,'迪克','Dick','由克斯汀·邓斯特与米歇尔·威廉丝饰演的两个高中女学生，在一次参观白宫校外教学的行程中，迷路而遇到尼克松总统（Dan Hedaya饰演），后来又参与了记者鲍勃·伍德沃德(威尔·法洛饰演)和卡尔·伯恩斯坦（Bruce McCulloch饰演）的揭发行动。','The unmaking of the president',13000000,27500000,4.742537,5.7,67,94,'1999-08-04','en','/aBG4XoK5xkujl4crloPs6bStl4m.jpg',2.750443399165424,3,'2026-09-10',2,NULL,NULL),(16428,'Breakin\' All the Rules','Breakin\' All the Rules','Inspired by his fiancée (who dumped him), a man publishes a break-up handbook for men, becoming a bestselling author in the process.','When it comes to getting dumped... He wrote the book.',0,0,6.904734,5.8,21,85,'2004-05-14','en','/piEqcDe7CTbxxPUSwswrsoKWzMw.jpg',2.5181375942479214,3,'2026-09-10',2,NULL,NULL),(16433,'Grand Theft Parsons','Grand Theft Parsons','There are times when it\'s right and proper to simply bury the dead. This is not one of those times... Gram Parsons was one of the most influential musicians of his time; a bitter, brilliant, genius who knew Elvis, tripped with the Stones and fatally overdosed on morphine and tequila in 1973. And from his dying came a story. A story from deep within folklore; a story of friendship, honour and adventure; a story so extraordinary that if it didn\'t really happen, no one would believe it. Two men, a hearse, a dead rock star, five gallons of petrol, and a promise. And the most extraordinary chase of modern times.','It\'s better to burn out than to fade away.',0,0,1.998557,6,11,88,'2003-06-18','en','/5sWWj5tlTDyAi2yiEjQZUmJCoKr.jpg',2.377435548373123,3,'2026-09-10',2,NULL,NULL),(16441,'兽王伏魔','The Beastmaster','上古洪荒时代，流传著神奇的冒险故事。“万兽王”达尔即是这个时代的英雄。  达尔出生皇室，却被巫师亚刚追杀，流落民间。他成人不久，养父就被野蛮人杀死，但他也发现了他能与动物交流的能力。  同时，他必须阻止巫师亚刚拿到“布朗斯之眼”。因为一 旦亚刚拿到此颗宝石，邪魔恶神布朗斯将重返人间，助亚刚王为恶，荼毒生灵。为了取得布朗斯的魔力，亚刚绑架了达尔的亲兄弟——泰尔王，兄弟情深的达尔誓言救回兄弟，为父报仇，他带领著忠心的动物军队以及军师塞斯向亚刚王宣战。达尔将和这位神秘没测的魔头刀锋相对决一死战。','Born with the courage of an eagle, the strength of a black tiger, and the power of a god.',0,14056528,6.377523,6,97,118,'1982-08-20','en','/ytaKNYpHdQnClTbWL2m19Xv6PXZ.jpg',2.839993022124229,3,'2026-09-10',2,NULL,NULL),(16448,'等待古夫曼','Waiting for Guffman','密苏里州的布雷恩小镇，正为该镇150周年纪念的庆典活动准备，一名非常，非常，非常过气的百老汇导演考基负责招集一群业余演员，演出一出纪录该镇历史的戏剧。他对这部名为《红、白与布雷恩小镇》的剧作寄予厚望，并邀请了百老汇的制作人古夫曼先生，前来观赏此剧的首映，他相信这部剧将是他重回百老汇的跳板。但是这一群努力有余却天赋不足的演员聚在一起后，又会出现什么样的故事呢......','There\'s a good reason some talent remains undiscovered.',0,0,4.348416,7.3,63,84,'1996-01-31','en','/zuArI6EBpV6mExrvfnyidoOtzdf.jpg',2.7751608963691927,3,'2026-09-10',2,NULL,NULL),(16471,'Modern Problems','Modern Problems','Jealous, harried air traffic controller Max Fielder, recently dumped by his girlfriend, comes into contact with nuclear waste and is granted the power of telekinesis, which he uses to not only win her back, but to gain a little revenge.',NULL,0,0,4.293706,5.6,23,89,'1981-12-25','en','/aH21h3sMMN3r6d9I8VSBw28fW7V.jpg',2.528988659536485,3,'2026-09-10',2,NULL,NULL),(16508,'阿德日记电影版','Doug\'s 1st Movie','Doug and his friends find a \"monster\" living in the woods outside their town, but when they find the monster is actually kind of nice, they find themselves hunted by \"bad guys\" who want the monster. In addition, Doug has to compete for the attention of Patti Mayonnaise with a snobby 8th grader, Guy Graham. Will Doug get to take Patti to the Valentine\'s Day dance? 这部电视影集最早是由 Nickelodeon 于１９９１年所推出的，在迪士尼１９９６年买下其制片公司 Jumbo Pictures 之后，全新的【阿德日记】开始于美国迪士尼ＡＢＣ电视台的“Disney\'s One Saturday Morning”时段推出，影集的主角是一个喜欢作白日梦的少年 Doug，内容就是以他的眼光来看他生活周遭的一切事物。本影集在美国推出很受欢迎，更衍生出一系列受欢迎的读物，因此才有推出电影版的打算。当初制作本片，原本只是想要直接发行录影带，但是到了１９９９年１月时，迪士尼才决定本片要在大萤幕推出，本片剧情的内容是Doug 一次“生活上的冒险”，一方面他想邀心仪许久的女孩 Patti 去参加情人节舞会，却偏偏发现一位学校高年级的酷哥是他的情敌；另一方面他最要好的朋友Skeeter 却在此时发现“幸运鸭湖”边的怪物传说是真实的，邀他一同前往湖边去探险，且看我们这位具有丰富想像力的主人翁，该如何面对他生活中大冒险！','You\'ll Dig Doug!',0,0,1.88484,5.4,22,77,'1999-03-26','en','/hZduJdSSWCkmvnBpNyRaIszubVm.jpg',2.5126842952591275,3,'2026-09-10',2,NULL,NULL),(16523,'野兽家园','Where the Wild Things Are','本片主要是围绕着主人公马克斯的历险展开。马克斯是个非常聪明的孩子，一次在跟妈妈吵架后，他赌气离家出走了。结果不料却中途迷了路，只能在一个神秘的森林里转来转去，森林的周围都被无边无际的海洋所包裹着，很多的惊险正在等待着他……','There\'s one in all of us.',100000000,100086793,31.586215,6.4,572,101,'2009-10-16','en','/u7EtoA6jErpKOsj70QoJQURqxKP.jpg',3.322932022619933,3,'2026-09-10',2,NULL,NULL),(16538,'寻找伴郎','I Love You, Man','彼得（保罗·路德 Paul Rudd 饰）和佐伊（拉希达·琼斯 Rashida jones 饰）订婚了。在佐伊兴奋地向姐妹们报喜之时，彼得却发现自己居然找不出可以来做伴郎的死党。在走投无路的情况下，彼德开始了寻找伴郎的“相亲”过程。　　寻找伴郎的过程并不顺利，直到他遇到了神奇希德尼（杰森·西格尔 Jason Segel 饰）。希德尼激发出来不善于交际的彼得内心深处的潜能，俩个人成为无话不谈的朋友，曾至还组成了一个乐队。他们没完没了的聊天、打游戏、遛狗，几乎每天24个小时都粘在一起，这种狂热的关系最终影响到了彼得和未婚妻佐伊的感情。佐伊受不了自己的未婚夫满脑子装着另外一个男人，于是向他发出最后通牒，让他在哥们和自己中做出一个选择。','He needed a best man... He got the worst.',41000000,91636986,25.391899,6.5,515,105,'2009-03-20','en','/9vlPLiBN345woaYP5fev9fOhdYW.jpg',3.2962419685240687,3,'2026-09-10',2,NULL,NULL),(16558,'口是心非','Duplicity','英国军情六处的前特工雷（克里夫•欧文 饰）转行做了商业间谍。在酒会上，他邂逅了曾在美国中情局工作的特工克莱尔（茱莉亚•罗伯茨 饰）。不过，克莱尔却装作不认识，这勾起了他的好奇。终于，雷依靠软磨硬泡，拉克莱尔去开房。没想到，却被对方下药迷倒，还偷走了他的重要文件。原来，此时的克莱尔已经做了竞争对手公司的间谍。这令如梦初醒的雷非常愤怒。在一次接头任务中，雷再次见到克莱尔的身影，于是不顾命令，拦住了她，结果他意外发现她恰恰就是接头人。虽然因为他的鲁莽，这场碰头不欢而散，但是这两人的纠缠却并未结束，因为他们先后卷入了两家竞争公司的明争暗斗之中，为了窃取商业情报，两人大打出手，互相斗法，并在其中擦出了爱情的火花……','Outwit. Outspy. Outsmart. Outplay. Then get out.',78146652,60000000,13.630049,5.7,201,125,'2009-03-19','en','/cIMII0x2GpLnapomRbrxAXqZFzM.jpg',2.990822420797501,3,'2026-09-10',2,NULL,NULL),(16564,'战时冬天','Oorlogswinter','二战末，冬季的荷兰小城冰天雪地，战争让整个城市显得阴霾异常。小男孩米歇尔（马丁·拉克迈尔 Martijn Lakemeier 饰）和同伴跑去一架坠毁的飞机残骸附近玩，却被驻扎的德军抓住，还好米歇尔的市长父亲和德国人关系看起来不错，他很快便被父亲领回了家。\r 　　本叔叔的到来让米歇尔兴奋不已，但是本叔叔却警告他千万不要卷入到战争中去。德克在临出发去炸德军的军火库之前交给他一个信封，可是在行动过程中德克被德军抓住。后来米歇尔打开信封，根据信封里的内容，他发现了隐匿在树林里负伤的英国飞行员杰克，米歇尔开始了照顾并帮助他逃走的活动，其间得到了做护士的姐姐埃里卡（梅乐蒂·克拉弗尔 Melody Klaver 饰）的帮助。\r 　　杰克伤好之后，米歇尔几次帮助杰克逃走的计划都最终失败。而这段时间内，由于有德国军人被害的事情，米歇尔的父亲最终被德军杀害。米歇尔在万般无奈之下，只好找本叔叔帮忙，而本叔叔也乐意帮忙，但是要求米歇尔不再插手此事。\r 　　米歇尔看着本叔叔带着杰克和姐姐越走越远，他回想这个冬天的整个事件，发现本叔叔是隐藏在自己家的德军奸细……','In 1945 Holland, a boy must choose between good and evil.',4000000,530048,5.013575,6.8,66,103,'2008-11-17','nl','/nnKqG14HRkvG2BmIfOcmAH3cEip.jpg',2.775404006830306,3,'2026-09-10',2,NULL,NULL),(16577,'阿童木','Astro Boy','天马博士的儿子因意外丧生，悲痛的他制造了一个与儿子一模一样的机器人来排解忧伤，但发现机器人无法成长的事实后愤然将其卖给了马戏团，这个机器人就是阿童木。苦难中的阿童木被科学家茶水博士收留并被赋予了新的能力，阿童木化身为正义与和平的守护者，与恶势力战斗。','Have a blast.',65000000,44091067,24.857079,6.1,409,94,'2009-10-15','en','/oEytzLEp1WYuVJIaVLZt05cY8ZS.jpg',3.1955926941888193,3,'2026-09-10',2,NULL,NULL),(16608,'关键协议','The Proposition','1880年的澳大利亚，警方与黑帮的斗争已经到了白热化的程度，大屠杀事件时有发生。黑帮分子查尔斯与兄弟米基绑架了警长斯坦利，希望可以得到小镇的控制权。同时查尔斯家最小的弟弟亚瑟因为精神失常而更加手段毒辣，他藏在郊外灌木丛里，准备伏击路人。小镇变成了修罗场，所有人都变成了罪犯。为了挽救小镇的命运，斯坦利说服查尔斯制定关键协议，以停止冤冤相报的怪圈，平息血腥暴力的屠杀事件。','This land will be civilized.',2000000,5048693,14.617944,7.1,218,104,'2005-10-06','en','/bbSHSJuO5XjrIKMh6QXXLTg3Yzr.jpg',3.1056252268023012,3,'2026-09-10',2,NULL,NULL),(16614,'冒险乐园','Adventureland','1987年的夏天，刚刚走出大学校园的小伙子詹姆斯·布兰纳(杰西·艾森伯格饰)，像许许多多普通的毕业生一样，面临着未来的选择，尤其是就业生存问题。但詹姆斯眼下最想实现的梦想，就是去梦寐以求的欧洲大陆去游览一番。但显然父母已经给出了他明确的答复，将不再给已经成年的詹姆斯经济资助。\r 于是，找一份暑期临时工，实现自己的欧洲游梦想成了詹姆斯迫切的愿望。餐馆、超市，詹姆斯四处碰壁。终于外形上还算过得去的小伙子在距离家不是很远的一个大型游乐场“冒险乐园”找到了一份杂工的工作。然而，在这里，形形色色的游客，性格各异的同事，再加上神经质到了极点的老板(比尔·哈德尔饰)，简直让詹姆斯亲生经历一一番“现实世界版”的“冒险乐园”之旅。让刚刚踏入社会的詹姆斯对人生对自己的未来有了全新而深刻的认识。与此同时，这位在学校里就很羞涩内向的小伙子也在这份新工作中，与漂亮的女同事安(克里斯汀·斯图尔特饰)的“亲密接触”中，体会到了年轻人该有心理和生理上的双重冲动以及成长……','Nothing brings people together like a crappy summer job.',9500000,17164377,19.978021,6.4,737,107,'2009-04-03','en','/lk3tRyXdiMt08iL2vLU3j8i7Sha.jpg',3.356805198877576,3,'2026-09-10',2,NULL,NULL),(16617,'八面埋伏','Mindhunters','莎拉、妮可、卢卡斯等七名FBI成员在资深教官杰克·哈里斯的带领下，来到离加州不远的弗涅戈小岛，他们将在岛上的虚拟小镇中进行演练，通过推理来找出绰号为“酒吧眼泪”的连环杀手。这群探员业务精湛，自命不凡，与世隔绝的小岛之行对他们来说更像一个无聊难耐的假期。但是，他们的狂妄并未持续太久。原本看似平常的推理演习，竟然开始出现死者，所有的逃生之路被切断，众人完全孤立在小岛之上。演习随即演变成一场精心策划的杀戮游戏……','For seven elite profilers, finding a serial killer is a process of elimination. Their own.',27000000,21148829,17.193659,6.3,333,106,'2004-05-07','en','/hNqUOxkJTyN55yy0LKe8u19W46p.jpg',3.1525663363769625,3,'2026-09-10',2,NULL,NULL),(16619,'普通人','Ordinary People','在罗伯特·雷德福的导演处女作中，一个富裕家庭的长子意外离世，使严厉的母亲（玛丽·泰勒·摩尔 饰）、温和善良的父亲（唐纳德·萨瑟兰 饰）与深陷自责的小儿子（蒂莫西·赫顿 饰）之间的关系陷入重重裂痕。','Everything is in its proper place...except the past.',6000000,0,12.541983,7.4,145,124,'1980-09-19','en','/tJVETEDAKgD3fEh88SHOvMvOQue.jpg',3.0087239627864153,3,'2026-09-10',2,NULL,NULL),(16620,'青春传奇','La Bamba','在美国加利福尼亚州的南部，素有“高音王子”之称的里奇在哥哥和妈妈的帮助下，加入了希路埃特乐队，并以其娴熟的弹奏和高亢的歌喉一举成名。天有不测风云，一步步走向成功的里奇在飞往北科他州演出的途中，不幸空难身亡。那年，里奇才17岁，可由他创作并演唱的三首摇滚乐《唐娜》、《拉巴马》和《快点、一起来》，却早已风靡全美……','Born into poverty. Destined for stardom. He lived the American dream.',6500000,54215416,6.847099,6.8,116,108,'1987-07-24','en','/6Znulqtc7cdqlUC69HGf26Ef5fi.jpg',2.911843697733173,3,'2026-09-10',2,NULL,NULL),(16633,'Somewhere in Time','Somewhere in Time','Young writer, Richard Collier is met on the opening night of his first play by an old lady who begs him to, \"Come back to me.\" Mystified, he tries to find out about her, and learns that she is a famous stage actress from the early 1900s. Becoming more and more obsessed with her, he manages – by self-hypnosis – to travel back in time where he meets her. They fall in love, a matching that is not appreciated by her manager. Can their love outlast the immense problems caused by their \'time\" difference, and can Richard remain in a time that is not his?','Beyond fantasy. Beyond obsession. Beyond time itself... he will find her.',5100000,0,5.934016,7.2,102,103,'1980-10-02','en','/ea6kR7BbwJDmcviSgxmOyU6hEKx.jpg',2.8938240748934017,3,'2026-09-10',2,NULL,NULL),(16642,'Days of Heaven','Days of Heaven','In 1910, a Chicago steel worker accidentally kills his supervisor and flees to the Texas panhandle with his girlfriend and little sister to work harvesting wheat in the fields of a stoic farmer. A love triangle, a swarm of locusts, a hellish fire—Malick captures it all with dreamlike authenticity, creating at once a timeless American idyll and a gritty evocation of turn-of-the-century labor.','Your eyes... Your ears... Your senses... will be overwhelmed.',0,0,13.857194,7.6,234,94,'1978-09-13','en','/rwxTYjOZmX2rGhz7avLe1qsjNqe.jpg',3.159459757816335,3,'2026-09-10',2,NULL,NULL),(16643,'天算不如人算','Life or Something Like It','莱尼（安吉丽娜·朱莉 Angelina Jolie 饰）年轻貌美，是电视台的当家花旦，靠着自己的不懈努力，她终于爬到了如今的位置，高薪的工作、舒适的住宅、宽裕的经济条件和英俊帅气的男朋友卡尔（克里斯蒂安·凯恩 Christian Kane 饰），坐拥着这令旁人羡煞的一切，莱尼觉得自己或许就是世界上最幸福的女人。\r 　　在一次采访中，莱尼的采访对象是一位善于占卜和寓言的流浪汉，令莱尼感到惊讶的是，流浪汉竟然寓言自己将会在一周之内死去。流浪汉的寓言点醒了莱尼，她开始思考起自己人生真正的意义。与此同时，一件令莱尼心烦的事情发生了，那就是她必须跟向来不合的摄影师皮特（爱德华·伯恩斯 Edward Burns 饰）一同工作，站在人生的低谷中，莱尼会怎样处理自己和皮特之间的关系呢？',NULL,40000000,16872671,8.980846,5.7,124,103,'2002-04-26','en','/t80fLTbd7gyjuEkBidaqbtq6dEm.jpg',2.8847452302263457,3,'2026-09-10',2,NULL,NULL),(16651,'天堂的彼端','The Other Side of Heaven','本片是一部改编自真人真事的感人电影，十分适合阖家观赏，父母可藉此向孩子传达正确的信仰态度，和行善助人的观念。剧情叙述一名年方十九的年轻人，由于教会的指派，到一个家乡无人听过的小岛去，但直到与另一处教会人员碰面，才知道自己必须学习当地原住民语言，且要在当地建立新教会。年轻人开始了他在小岛三年的传教生涯，其间不但遇到语言沟通上的阻碍，迫使年轻人必须认真面对，重新了解当地原住民的文化，也碰到过无数次人祸天灾的试炼。最后，年轻人可以回到自己的家乡，但对年轻人来说，这三年与这些原住民的相处，渐渐建立的生活习惯，却永难忘怀。本片的摄影和配乐方面的表现相当好，采光、取景、构图，无一不是经典级的水准，优美的管弦乐旋律加上片中不时出现的原住民曲调歌曲，让观赏者享受视觉和听觉的飨宴，可惜整个剧情太平淡，没有明显的情绪起伏，也让主角的成长无法真的引起观赏者的共鸣。','An Epic Journey.',7000000,4720371,2.206097,6.7,14,113,'2001-04-12','en','/1jHSJULA0nEDfVeewlLvppsjve8.jpg',2.430190107795128,3,'2026-09-10',2,NULL,NULL),(16653,'The Singles Ward','The Singles Ward','When Jonathan Jordan gets divorced he\'s thrust back into the world of being a single Mormon - a world who\'s ultimate goal is eternal marriage. Struggling to fit in, Jonathan decides to stop going to church only to be pursued by the members of the local singles ward who want to reactivate him. Nothing works until Jonathan falls for Cammie Giles, the ward activities director. Suddenly, going to church becomes much more appealing, But is he going for the right reasons?','The Road to Eternal Marriage Has Never Been Longer',0,0,0.920591,7.5,4,102,'2002-01-30','en','/A1l7mSbptwFdutUbOq4zzhH4goa.jpg',2.1876432752360566,3,'2026-09-10',2,NULL,NULL),(16690,'小飞侠2：梦不落帝国','Return to Never Land','现在，温迪(Wendy)已长大成人，并有了自己的孩子。当凶猛的闪电来临时，她会用小飞侠彼得·潘(Peter Pan)的故事来抚慰孩子，而小飞侠彼得·潘是个不愿意长大的孩子。温迪那固执的12岁女儿简(Jane)根本没有耐心听这些无聊的故事，直到胡克(Hook)船长用这个女孩当作诱饵来捕获他的竞争对手。小飞侠、廷克·贝尔(Tinker Bell)和迷失的男孩们都来帮助她。然而，无论如何他们不能使简相信想象中的魔法。除非她相信，否则她是飞不起来的，而且她也没有其它办法回家。更糟的是，在仙境中如果没有简的信念，廷克·贝尔就无法活下去。当这个小精灵开始慢慢地消失时，彼德奋力去寻找一个从危险的胡克船长手中拯救这个女孩的方法，让她明白只要有了信仰、信任和精灵的魔力，任何事情都是可能发生的。','The Classic Continues',20000000,109862682,15.341196,6.1,290,72,'2002-02-14','en','/aI5vIO7S084m5prI0AB1e9U7iyx.jpg',3.0996941488995073,3,'2026-09-10',2,NULL,NULL),(16727,'同名人','The Namesake','影片跨越两代人，展现两种文化、两种截然不同的生活方式彼此碰撞，最终以温情交织。归根结底，本片探讨的是一个极具当下意义的问题：成为一个美国家庭，究竟意味着什么？[福克斯探照灯影业]','Two Worlds. One Journey.',12000000,20138836,3.604863,6.8,50,122,'2006-09-02','en','/hxrf7HDwh0nIX4xXE06BdpEKW1V.jpg',2.7090474225789416,3,'2026-09-10',2,NULL,NULL),(16769,'矿工的女儿','Coal Miner\'s Daughter','本片讲述了乡村音乐传奇人物洛蕾塔·林恩的传记故事，她出身贫困，最终赢得世界性声誉。从肯塔基州卑微的起点一路攀升至超级巨星地位，她永远改变了乡村音乐的声音与风格。','She was married at 13. She had four kids by the time she was 20. She\'s been hungry and poor. She\'s been loved and cheated on. She became a singer because it was the only thing she could do. She became a star because it was the only way she could do it.',15000000,67182787,3.826685,7.2,67,125,'1980-03-07','en','/bzHFDAdUad4QcHPi2UOqvaQKNWA.jpg',2.786255421753481,3,'2026-09-10',2,NULL,NULL),(16781,'玛蒂的家人重逢','Madea\'s Family Reunion','Based upon Tyler Perry\'s acclaimed stage production, Madea\'s Family Reunion continues the adventures of Southern matriarch Madea. She has just been court ordered to be in charge of Nikki, a rebellious runaway, her nieces, Lisa and Vanessa, are suffering relationship trouble, and through it all, she has to organize her family reunion.',NULL,6000000,57231524,5.882208,6,77,110,'2006-02-24','en','/lAzrDS5bJJSSdPAUxuctCoomXUc.jpg',2.790036175318221,3,'2026-09-10',2,NULL,NULL),(16784,'总统接招','Welcome to Mooseport','在白宫完成两个任期的工作后，前美国总统门罗·寇尔（金·哈克曼 饰）搬到了新西兰海岸的一个小镇，他想在那里撰写自己的回忆录，享受退休后的休闲日子。这个小镇其实就是他的家乡，缅因州的莫斯普特（Mooseport），原本打算安享晚年的前总统门罗，适逢莫斯普特举行市长选举，被街坊邻居们推选为候选人，极力怂恿他担任他们的新市长。\r 　　也许是从政生涯造就的好大喜功的心理，也许是不能接受失去众人焦点的地位，也许真想为街坊市民们做点实事，门罗答应了邻居们，投入到了市长的竞选中。不想，当地一个五金店的老板汉迪·哈里逊（雷·罗曼诺 饰），却不买他的帐，公然反对他竞选。\r 　　已经征服过整过美国的前总统门罗，怎能忍受在一个无名小镇上翻船？所以，他开始利用政治生涯学来的各种手段，与反对他的人开始了争夺。不想，他这样做反而打乱了当地人们的生活，他本该清闲的退休生活，竟也成为了他一生中最好争吵的日子……',NULL,30000000,14000000,3.314094,4.8,54,110,'2004-02-24','en','/xesXaNCtdGUO5FsMDYooPQAMHxQ.jpg',2.68435659597613,3,'2026-09-10',2,NULL,NULL),(16857,'叛逆骄阳','The Dangerous Lives of Altar Boys','两个可爱又顽皮的天主教中学生Francis和Tim，不愿服从成人世界的游戏规则，并深信正邪两立，非黑即白。他们作了本漫画，笔下处处影射他们的头号敌人雅森达修女。漫画世界与现实经历一起双线发展，带出年轻人的成长之路。现实中连串的痛苦经历，令他们渐渐成长，原来生活可不是这么容易。',NULL,0,0,2.24888,6.4,53,104,'2002-06-14','en','/4uTWXZ2Rvizl3ycMHtODfRjks4W.jpg',2.7109638025511003,3,'2026-09-10',2,NULL,NULL),(16858,'爵士春秋','All That Jazz','作为一个音乐剧迷，即使你不太熟悉金像奖导演Bob Fosse这个名字，我打赌你也一定听说过托尼奖和奥斯卡的大赢家《芝加哥》和《歌厅》，Fosse分别是这两部音乐剧电影版的编剧和导演，他的另一部著名作品就是这部《爵士春秋》。（其实只要稍微留意就可以从《芝加哥》的编舞上发现许多《爵士春秋》的影子，而且《芝加哥》开门见山的第一只曲子就是‘All That Jazz’。）《爵士春秋》可称是Bob Fosse本人的半自传影片，片中的主人公是一位叫Joe Gideon的百老汇资深导演，他天马行空，我行我素，才华横溢，但是由于没有树立起远大的理想和正确的人生观和世界观，工作的压力和情感的放纵使他灰心厌世，健康每况愈下，最后在其作品的歌声舞影中，Gideon哼着《再见我爱》在手术台上踏上了不归之路。人生就是这般无常，Gideon先生可以创造票房奇迹，可以吸引各式各样的女子投怀送抱，但他和我们一样，常常对心灵的空虚和肉体的软弱束然无策。有志趣相投的朋友聊天，有喜欢的文章可读可写，有好听的音乐剧可以欣赏，有幽默的心情可以时常微笑，有不含SARS病毒的空气可以呼吸――不知道这样简单的幸福上天还可以赐我们多久？金曲提示：《在百老汇》(On Broadway)、《自君别后》(After You\'ve Gone)、《重焕生机》(Everything Old Is New Again) 、《再见我爱》(Bye Bye Love) 。本片是一部音乐歌舞片，集七十年代爵士乐之大成。在1980年第33届戛纳国际电影节上获得金棕榈奖，获52届奥斯卡（1979）最佳服装设计、最佳剪辑，最佳音乐三项金像奖。','All that work. All that glitter. All that pain. All that love. All that crazy rhythm. All that jazz.',0,37823676,5.159407,7.3,85,123,'1979-12-20','en','/wGkBiRrpjONLU17xK6mJKEFD7rP.jpg',2.8500399310315117,3,'2026-09-10',2,NULL,NULL),(16866,'51号星球','Planet 51','在一颗名为51号星球的行星上，居住着一群通体绿色的高智慧生物，他们的文明高度发达，生活安宁幸福。不过他们也有自己的恐慌，那就是远在几百光年之外的地球人，他们生怕会遭到地球人的入侵和杀害。雷（Justin Long 音）是一个热衷星球研究的青年，他和地球上的小青年没什么两样，做实习报告、跟朋友聊天、追女朋友、找工作。这一日，一艘来自地球的宇航飞船降临51号星球，且刚好落在雷的院子里。宇航员查理·T·巴克（“巨石”强森 Dwayne Johnson 音）在当地引起一系列恐慌，自己也受到不小的惊吓。　　由于长久以来的宣传，51号星球的居民生怕地球人会对自己造成伤害。万般无奈之下，巴克船长找到雷，希望他能帮助自己回到正被当地居民围观的飞船，启程返回地球。而另一方面，当地防卫军也针对“入侵”的地球人展开了行动。巴克船长最终能否回到故乡呢？','Something strange is coming to their planet...Us!',70000000,104945765,23.661071,5.6,556,91,'2009-11-19','en','/x7Itcg3ZdExKwdKguy73WPEqosW.jpg',3.1941877116592017,3,'2026-09-10',2,NULL,NULL),(16869,'无耻混蛋','Inglourious Basterds','故事分五章进行。二战中德占法国，德军上校汉斯（克里斯托弗·瓦尔兹 Christoph Waltz 饰）号称“犹太猎人”，在一次屠犹行动中，少女苏珊娜（梅勒尼·劳伦特 Mélanie Laurent 饰）侥幸逃脱。与此同时，八名美国犹太士兵在中尉奥尔多（布拉德·皮特 饰） 的带领下潜入德占法国刺杀德国军人，其行动神出鬼没，手法残忍，对德军造成相当威胁，被称为“杂种”。三年后苏珊娜来到巴黎继承了姑母的电影院，结识了德国战斗英雄，电影《国家荣耀》的主演弗里德里克（丹尼尔·布鲁赫 Daniel Brühl 饰）。对苏珊娜一见钟情的弗里德里克说服德国宣传部长约瑟夫·戈培尔（西尔维斯特·格洛斯 Sylvester Groth 饰）在苏珊娜的影院首映《国家荣耀》，希特勒（马丁·乌特克 Martin Wuttke 饰）本人也将出席。苏珊娜决定借放映之机烧毁影院；而在德国间谍女演员布里奇特（戴安娜·克鲁格 Diane Kruger 饰）的安排下，英美联合的刺杀行动“奇诺”也将在首映当晚行动……','Once upon a time in Nazi occupied France...',70000000,319131050,72.595961,7.9,6430,153,'2009-08-18','en','/aupnPtagH9JVBuMrGEanf4iqXEQ.jpg',4.385398072168856,3,'2026-09-10',2,NULL,NULL),(16871,'堕入地狱','Drag Me to Hell','克里斯汀·布朗是洛杉矶一位野心勃勃的信贷员。生活原本顺遂，直到神秘的加努什夫人来到银行，恳求延长她的房贷期限。克里斯汀是该凭直觉给这位老妇人一次机会？还是该拒绝延期以讨好上司杰克先生，为升职铺路？克里斯汀做出了命运性的选择——后者，她羞辱了加努什夫人并收走了她的房子。作为报复，老妇人对克里斯汀施以强大的拉弥亚诅咒，让她的生活坠入活地狱。被邪恶之灵缠身的克里斯汀，只得寻求先知拉姆·贾斯的帮助，以拯救自己的灵魂免遭永恒诅咒。随着邪恶力量步步紧逼，克里斯汀必须面对这个骇人的问题：她愿意付出多大代价来破除诅咒？[环球影业]','Christine Brown has a good job, a great boyfriend, and a bright future. But in three days, she\'s going to hell.',30000000,90810892,45.083509,6.2,966,99,'2009-03-15','en','/ekyCjBFNpkGCQfASprQaaZXRRUK.jpg',3.4444219718163644,3,'2026-09-10',2,NULL,NULL),(16888,'恋上大情圣','The Ladies Man','Because of his salacious language, late-night radio advice-show host Leon Phelps, along with his sweet and loyal producer Julie, is fired from his Chicago gig. Leon gets a letter from a former lover promising a life of wealth, but he doesn\'t know who she is. Can Leon find his secret sugar-mama? What about Julie?','He\'s cool. He\'s clean. He\'s a love machine.',24000000,13700000,2.259537,5.7,34,84,'2000-10-13','en','/kKMhGSwydCVjrOWwggDlSvcgzCl.jpg',2.6054576537667784,3,'2026-09-10',2,NULL,NULL),(16899,'水性杨花','Easy Virtue','1929年的英国，惠特克太太（克里斯汀•斯科特•托马斯 Kristin Scott Thomas 饰）是贵族家庭的掌门人，她精心操持着家务，平衡着丈夫（科林•费斯 Colin Firth 饰）及两个女儿的关系。不过，一切却因长子约翰•惠特克（本•巴恩斯 Ben Barnes 饰）的归来被打破了。约翰闪婚的妻子是明艳动人的美国赛车手拉丽达（杰西卡•贝尔 Jessica Biel 饰）。她的很多行为都被正统的婆婆视为放浪。并且，两个女儿也看她不顺眼，替哥哥惋惜。拉丽达跟老公的朋友们前去兜风，别人优雅地骑马，她却驾驶着摩托风驰电掣。孤立时，她会跟公公吐露心事，两人甚至在舞会上翩翩起舞。这让事情演变为婆媳间的恶斗……\r 　　本片改编自诺埃尔•考沃德的戏剧，克里斯汀•斯科特•托马斯凭借此片获英国独立电影奖最佳女配角奖提名，该片还被选作多伦多电影节的放映影片，杰西卡•贝尔在本片中首次献声。','Let\'s Misbehave!',0,0,8.387573,6.3,108,93,'2008-01-01','en','/k9bGewoi6SWPTFQfUbn6ve06TY9.jpg',2.8789133273343332,3,'2026-09-10',2,NULL,NULL),(16911,'人烟之岛','Обитаемый остров','2157年，人类文明得到全面跃升，战争、饥饿、贫穷早已不复存在，自然界再次复兴，人类的潜能得到极大开发，并且开始向天外星系延伸。22岁的青年马克西姆·卡梅尔（瓦西里·史特帕诺夫 Vasiliy Stepanov 饰）正独自驾驶飞船进行宇宙旅行，却突然遭到陨石碰撞，继而坠落在一个偏远的殖民星球萨拉什上。由于飞船迫降后完全坠毁，马克西姆只得独自踏上旅程，寻求帮助。萨拉什荒凉破败，杳无人烟，其文明与地球相比似乎也落后了好几个世纪，专政是这颗星球的主导。对从小养尊处优的马克西姆来说，这里的一切都如此新奇，而他也不知不觉扮演了革命者的角色……',NULL,36500000,21834845,2.785832,5.3,23,115,'2008-12-18','ru',NULL,2.5227896323648946,3,'2026-09-10',2,NULL,NULL),(16988,'舞动青春','How She Move','拉娅（卢蒂娜·卫斯理 Rutina Wesley 饰）的姐姐是个无可救药的毒虫，她挪用了拉娅的学费购买毒品，并最终死于吸毒过量。经历了这一番变故，再也无法承担私立学校高昂学费的拉娅只能选择离开，她回到了老家，回到了位于多伦多黑人社区的公立学校。 同学们将拉娅在私立学校就读当做是一种“背叛”，其中名为米歇尔（翠茜·阿姆斯特朗 Tracey Armstrong 饰）的强势女生和拉娅之间的关系更是水火不容。舞蹈大赛即将举行，为了赢得巨额的奖金，拉娅想方设法加入了一支踢踏舞团。在训练期间，拉娅和同伴们培养了深厚的友谊，同时亦对踢踏舞产生了由衷的热爱，随着时间的推移，一个问题在拉娅的心中不断翻滚：公立学校和私立学校，究竟哪里才是她真正的归属？',NULL,0,0,1.782666,3,6,94,'2008-01-25','en','/xbQnpPZZXfuYcYs4n1AgH0Tjgi6.jpg',2.2527747397584674,3,'2026-09-10',2,NULL,NULL),(16991,'监视与报告','Observe and Report','安罗尼是一个商场保安，虽然已经年逾而立，但除了一身膘以外一无所有。不过俗话说的好，人生最重要的是态度！这家伙可是个无敌乐观主义者，对他来说在自己的岗位上站好每一班岗就是最大的人生目标！所以对于一个其他人来说压根没什么劲的保安也能让他干得异常带劲！只要“森林山脉”购物中心一开门，安罗尼立马进入戒备状态，任何一点小状况都堪称风声鹤唳，而那些小偷小摸的飞贼、四处捣乱的少年、还有不守规矩的顾客都是他追击的对象！于是一场场臆想中的火拼枪战、飙车武打就在和滑板少年的猫鼠游戏中延续着。 　　当然，再专注的人也有分神的时候。那什么事情能让我们如此敬业的小保安走神呢？当然是商场化妆专柜的售货员布兰蒂啦！看那曼妙地身材、光洁地面庞以及纤纤玉手，每每都引得我们体型“膘”健的小保安口水横流，目光发呆。情商高的时候一般智商都比较低，安罗尼最大的梦想就是有一天能够在梦中情人面前大展身手，缉拿凶犯。','Right now, the world needs a hero.',0,24007324,10.529143,5.6,225,86,'2009-04-10','en','/zHuouWUKlRK0SeIjzTlmtoPLrFA.jpg',2.9985961399476815,3,'2026-09-10',2,NULL,NULL),(16995,'国家要案','State of Play','身为《华盛顿报道》的一位名记，卡尔·麦卡弗里（罗素·克劳饰）最近的日子不怎么好过，身边有不少烦心事困扰着他，而曾经很热爱这份工作的他，也已经好几年没有拿到过一个好题材来进行报道了。本打算昏昏僵僵继续过日子的卡尔，正好让他碰上了斯蒂芬·柯林斯身边的这起谋杀案，政治谋杀，光鲜政客背后的丑闻，种种讯息使触角敏锐的卡尔感觉到，这起新闻背后有着很多可供挖掘的内容。报社也知道他在这方面的兴趣与能力，于是委派他作为这起报道的记者。当然，一个更重要的原因报社和卡尔都心照不宣：卡尔曾经是斯蒂芬的竞选顾问，在他身边出谋划策的日子不再少数。　　卡尔和漂亮的女助手德拉（瑞秋·麦克亚当斯饰）一起开始追查这起案件背后的诸多故事。虽然警方一直对外宣称正在侦破，但从诸多信息来看，这起案件警局一直没有深入追查，这是为什么呢？卡尔和德拉决心要找出真相，查明凶手是谁。鉴于自己过去和斯蒂芬的关系，卡尔发现斯蒂芬已经不再是过去他所认识的那位充满干劲活力的年轻人，在政坛浸淫多年的他，已经变得圆滑世故。同时在追查过程里，卡尔逐渐发现这起案件牵扯了许许多多的富得流油的政客。最终，卡尔发现了一个事实：当一个人面对改变自己命运的时刻，爱情和别人的性命……一切东西，他都可以出卖。','Find The Truth',60000000,87784194,21.685719,6.7,484,127,'2009-04-17','en','/djVeoh9qcMDVplxy89bf5CjXjx9.jpg',3.296533455267976,3,'2026-09-10',2,NULL,NULL),(16996,'重返十七岁','17 Again','17岁的迈克（扎克·埃夫隆 Zac Efron 饰）是校园风云人物，在一次关键性的篮球冠军赛上，他决定放弃前途，向怀有身孕的女友斯佳丽求婚。20年后，人到中年的迈克（马修·佩里Matthew Perry 饰）生活事业两失意，妻子斯佳丽（莱斯利·曼恩 Leslie Mann 饰）决定与迈克分居，一双儿女也对他形同路人，迈克只好搬入科技新贵的朋友奈德（托马斯·列侬 Thomas Lennon 饰）家暂住。迈克追忆自己本来可有的锦绣前程，却在重返高中校园过程中遇到一位神秘的清洁工，让他突然重返17岁。迈克决定与奈德假扮父子，重入高中，相信这是上天给他第二次机会让他做出正确决定，却发现自己的女儿玛吉（米歇尔·崔切伯格Michelle Trachtenberg 饰）与儿子亚历克斯（斯特林·克耐特Sterling Knight 饰）在学校问题重重……','Who says you\'re only young once?',20000000,136267476,52.571674,6.1,1350,102,'2009-03-11','en','/ogC9PcXG0DJyoZPGVhlYoSIymj0.jpg',3.5167373409604106,3,'2026-09-10',2,NULL,NULL),(17043,'鳄鱼猎手：激情之旅','The Crocodile Hunter: Collision Course','史蒂夫·艾尔文(本人饰)是澳洲的一个具有传奇性的野生动物保护者，一直为了自己的事业而奋斗不懈，顽强的与偷猎者进行体力与脑力的斗争。而这一次，他又发现一些“偷猎者”正在围剿一只野生鳄鱼。正义感十足的他勇敢出发，殊不知这些偷猎者原来有惊人的来历。他们是美国政府派来的秘密侦探，此行目的是为了一个珍贵的电子芯片。那个可怜无辜的鳄鱼就是因为误吞了它才引来这场杀身大祸的。 于是，一场各怀目的的较量在澳洲神秘的野生地带展开，同时也为我们展示了一个美丽却充满危险的澳洲风情。','His First Big-Screen Adventure!',0,33082548,1.714972,5.3,34,90,'2002-07-26','en','/8JyI97jCN1BIzdTjWfIxV4GKlyw.jpg',2.5988624518529444,3,'2026-09-10',2,NULL,NULL),(17044,'大地的女儿','The Land Girls','1941年，第二次世界大战战火正炽，英国的年轻男子纷纷被徵召赴前线作战。于是在后方的家乡，有一群英国年轻女子所组成了“妇女家乡工作服务队”，她们的工作是被分派到全国各地，到乡间的农场进行各种农事。 在这项工作的号召下，三个年轻貌美、完全不同背景出身的女孩子，一同来到多塞特乡间的农庄。史黛拉是一个浪漫的大家闺秀，她的未婚夫在海军服务。剑桥大学研究生艾格既聪明又任性，对世事却有些懵懂无知。擅于打情骂俏的蒲如则是专业的美发师，她的老练世故，使大家几乎都忘了她纯真的一面。 她们工作的农庄为劳伦斯家所有。劳伦斯的儿子乔伊英俊潇洒，他一直怀抱著一个梦想——离开农庄，成为一个空军飞行官。漫漫长日，战争似乎永无止尽。对这几个女孩子来说，工作的辛苦，唯有靠彼此之间的鼓励和关爱支持下去，她们因此建立了深厚的友谊。而乔伊不仅和她们成为好朋友，也渐渐产生了情愫。快乐、激情、和悲剧在他们身边一一发生，但随着战争的结束，一切似乎都成了冥冥之中命运的安排……','The story of three young women and the events that would change their lives... The friendships that would stay with them forever... and the loves that would change their hearts.',0,0,1.278092,7,3,111,'1998-09-25','en','/tfdj6Wx8vCDNZbzmIRR2hDn5mAr.jpg',2.138823700109192,3,'2026-09-10',2,NULL,NULL),(17047,'少年特工科迪2','Agent Cody Banks 2: Destination London','\"故事紧接着上一部继续发展。中情局发现手下的一名特工叛变，还带走了一份关乎到国家秘密的重要图纸，这名特工逃往了伦敦，准备将这份图纸献给野心勃勃的邪恶势力。如此危机的情况之下，中情局再度找到了科迪（弗朗基·穆尼兹 Frankie Muniz 饰），要求他在事态发展到无法挽回的局面之前夺回图纸。\r 就这样，科迪来到了伦敦，进入了一所音乐学院就读以隐藏自己的真实身份，与此同时，科迪还必须不断精进小提琴的技艺，以应付学校中繁杂的试验。聪明的科迪一遍小心翼翼不露出马脚，一遍亦步亦趋的追踪着图纸的下落，殊不知，自己已经被卷入了一个复杂而又危险的阴谋之中。\"','Adventure is an attitude.',26000000,28818995,10.925618,5.2,144,100,'2004-12-03','en','/zlAltvp84rYVTYs3kdemqHBaiat.jpg',2.8942331812142106,3,'2026-09-10',2,NULL,NULL),(17113,'杰克和露丝的情歌','The Ballad of Jack and Rose','为了逃离尘世的喧嚣，环保主义者杰克带着女儿萝丝生活居住在一个荒芜人烟的岛上。他们相依为命，转眼萝丝已经十六岁了，就在此时，杰克发现自己患上了重病，他开始为女儿的未来做打算了。杰克找来了自己的前女友凯瑟琳。凯瑟琳带着自己的两个儿子来到了岛上，开始了一家人新的生活。然而，萝丝却将凯瑟琳的到来看做是一种背叛和挑战，陷入愤怒的情绪之中无法自拔……','Selfhood begins with a walking away, and love is proved in the letting go.',1500000,712294,3.618646,6.5,43,111,'2005-03-25','en','/jhID43WmWf3HeH3M3tBCPTSeBOi.jpg',2.6702524638813623,3,'2026-09-10',2,NULL,NULL),(17127,'我钟情的人','The Object of My Affection','小学老师乔治（Paul Rudd饰）与社工妮娜（Jennifer Aniston饰）在一次社交晚宴上认识，乔治从妮娜那里惊悉自己被同性恋伴侣抛弃的消息，伤心不已。然而除却感情上的打击，他还不得不从同住的家中搬走，一时间毫无着落的他狼狈万分。好心的妮娜让乔治在自己的公寓中暂住，渐渐地，二人成为无所不谈的好朋友。妮娜也正发现自己与男友原来不相衬，尽管已经怀孕，还是果断地分手。妮娜听说乔治中学时曾经与女孩有过性关系后，也想亲身上阵勾引。谁知乔治的男友回头，打断了这一段鸳梦。  　　然而乔治还是妮娜最理想的、养育自己孩子的父亲。','Sometimes The Most Desirable Relationship Is The One You Can\'t Have',15000000,46905889,5.164281,5.6,72,111,'1998-04-17','en','/2mA6QEdzhsftNIFV11SGsQLJvJR.jpg',2.7634070764929497,3,'2026-09-10',2,NULL,NULL),(17130,'穿越乡间路','Crossroads','分开八年后，三个儿时的朋友——露西、基特和咪咪——在一次越野旅行中重新发现了他们的友谊。几乎没有计划，几乎没有钱，但有很多梦想，女孩们和咪咪的帅哥朋友本开着他的敞篷车搭上了电梯。一路走来，他们不仅收集了改变他们生活的经验，而且还发现了坚持内心的愿望是多么重要。','Dreams change. Friends are forever',12000000,61141030,6.703319,4.7,158,93,'2002-02-15','en','/prdFY9Bc28frBhhWl7mPSr7JmFp.jpg',2.874256408114307,3,'2026-09-10',2,NULL,NULL),(17134,'12回合','12 Rounds','在美国新奥尔良，优秀的警探丹尼·巴克斯特尽职的工作让他终究在罪犯的心目中成为不共戴天的仇人。为了给自己在逃避丹尼追捕中不幸被撞死的女友报仇，已然在国际上小有名气的恐怖分子迈尔斯·杰克逊自然不会轻易咽下这口恶气，于是，他在出狱后便立刻对警探丹尼和他的女友茉莉·波特实施了报复行动。','Survive all 12',20000000,17280326,15.66135,5.7,220,108,'2009-03-19','en','/ns1TDyfYOzYf0kl4X95D16HNWd4.jpg',3.013039292615166,3,'2026-09-10',2,NULL,NULL),(17139,'角色','Karakter','故事发生在二十世纪初期的荷兰鹿特丹，德高望重的德莱文哈文（简·德克莱尔 Jan Decleir 饰）死于非命，一位名叫雅各布（费德贾·范·胡艾特 Fedja van Huêt 饰）的年轻律师遭到了逮捕，尽管证据确凿，但雅各布依然坚称自己的清白无辜，让大家感到惊讶的是，经过调查，德莱文哈文和雅各布看似毫无瓜葛，但却是血脉相连的父子。原来，雅各布是德莱文哈文的私生子，当年，冷酷无情的德莱文哈文抛弃了身怀六甲的约芭（Betty Schuurman 饰），后者正是雅各布的生母。长大后的雅各布诸事不顺，面临着破产的命运，之后，雅各布立志成为一名律师，但却处处受阻，而这一切的始作俑者不是别人，正是他的亲生父亲。',NULL,4500000,0,0.011697,7.7,25,122,'1997-04-17','nl','/rXU7gNAAkulPUr0F1XqSHuEhfHL.jpg',2.5570974239031545,3,'2026-09-10',2,NULL,NULL),(17170,'灯红酒绿','Bright Lights, Big City','纽约一位满怀理想抱负的年轻小说家杰米，在一家杂志社担任校稿的职务，心中填满许多不满，当他承受妻子成为有名的模特儿之后弃他而去，和母亲去世的双重打击后，意志消而沉于五光十色的妞约夜生活中，企图从十里红尘的狂欢派对、酒精、毒品中寻找短暂的快乐。然而杰米却陷入更空虚、苦闷的世界。',NULL,0,0,2.753501,4.7,28,107,'1988-04-01','en','/pimtITTxB2cJftgRhso2Xm195Co.jpg',2.5555842086587908,3,'2026-09-10',2,NULL,NULL),(17182,'以血还血','Eye for an Eye','凯伦麦肯井然有序的生活，因一名变态杀手闯入她家谋杀她17岁的女儿而整个破灭。但她的震惊悲伤转眼却变成愤怒怀疑，因为凶手在法律漏洞下竟被判无罪开释，所以当他又犯下另一桩血案且又逃过法律制裁后，凯伦决心亲手讨回公道……','What do you do when justice fails?',20000000,0,3.996392,5.8,63,101,'1996-01-12','en','/y2lZSdJ1o0VvLegTw3ad6KFtxra.jpg',2.738535586372251,3,'2026-09-10',2,NULL,NULL),(17186,'越野狂飙','Supercross','拉斯维加斯，世界著名的赌城，多少人成就梦想以及梦想破灭之地。然而，除了灯红酒绿的赌场与香飘四处的酒精之外，这里的摩托车冠军赛也极大地吸引着欲以此成就梦想的众多年轻人。激情四溢的卡莱尔兄弟便是此项赛事的众多拥趸之中的一双。然而，最近他们却遇到了相当的麻烦。而困难不仅仅在赛场上，父亲的不幸离世令兄弟二人整日与悲痛做伴，面对即将到来的摩托车冠军赛已是激情不再。 还好，此时有众多好友给予俩兄弟莫大的支持和帮助。哥俩终于克服了生理和心理上的重重阻力和困难，同心协力在这场名为“Suppercross www xiguatv8.com(超越)”的摩托车比赛中获得了胜利。但荣誉在手的兄弟俩却在随后的生活中产生了种种的分歧：在对待生活以及事业的选择甚至连俩人沟通的方式上都有着截然不同的走势……',NULL,0,3102550,3.71305,5.4,29,80,'2005-08-16','en','/82dbqeFOA2iPhwWuciZItw1ELew.jpg',2.572639189085568,3,'2026-09-10',2,NULL,NULL),(17187,'皇家俱乐部','The Emperor\'s Club','威廉姆（凯文·克莱恩 Kevin Kline 饰）是一位恪尽职守的教师，他不仅十分热爱自己所教授的课业，同时将教书育人当做是人生的终极目标。一位名叫贝尔（埃米尔·赫斯基 Emile Hirsch 饰）的男生出现在了威廉姆的课堂上，他是参议员的儿子。尽管贝尔桀骜不驯又喜欢带头捣乱，但威廉姆依旧从他的身上看到了闪光点，他决定绝不放弃贝尔。\r 　　在威廉姆的努力下，贝尔的成绩提升的很快，两人之间的敌对关系也有稍稍缓解。威廉姆十分重视的凯撒知识问答大赛即将开始，贝尔在预选赛中获得了第四名的好成绩，可是，只有前三名能够进入决赛，看着手上的成绩单，威廉姆陷入了深深的沉思，此时的威廉姆并不知道，他接下来的举动将彻底改变贝尔的一生。','In everyone\'s life there\'s that one person who makes all the difference.',0,0,6.796079,6.9,96,108,'2002-11-22','en','/s7BRKAq0DNcXe8Bphm6Wd5KnvlF.jpg',2.8701979665210016,3,'2026-09-10',2,NULL,NULL),(17202,'我为什么结婚了？','Why Did I Get Married?','戴安娜（莎朗·莉尔 Sharon Leal 饰）虽然已经毕业多年，但每年依旧要同大学时代的好友们赶赴科罗拉多州的山间聚会度假，一行人在优美秀丽的风景环绕之中，尽情的释放着社会和工作带来的压力。','Because we complete each other\'s sentences.',15000000,55184721,2.005111,6.1,33,113,'2007-10-12','en','/9kmqgVuELTEoMt0dqRt3H48VcOM.jpg',2.603937985307822,3,'2026-09-10',2,NULL,NULL),(17264,'黑神驹','The Black Stallion','一场可怕的沉船事故后，一匹野马拯救了一个男孩的生命，两个生命在卡罗尔·巴拉德的电影杰作中成为了意想不到的挚友。本片改编自沃尔特·法利的经典儿童小说。从荒岛晶莹的海岸，到1940年代美国郊区青翠的草地与尘土飞扬的道路，巴拉德与摄影指导凯莱布·德夏奈尔共同创造了一部贯穿始终、充满视觉创意与纯净美感的电影。影片中更包含米基·鲁尼饰演退役骑师的精彩配角演出，以及卡迈恩·科波拉谱写的华美配乐。[标准收藏]','From the moment he first saw the stallion, he knew it would either destroy him, or carry him where no one had ever been before…',2700000,37799643,11.35972,7,59,118,'1979-10-17','en','/uZtNc31LR5Ik3ZVo2jxwOvhkNRC.jpg',2.7687528026190975,3,'2026-09-10',2,NULL,NULL),(17277,'罗马帝国沦亡录','The Fall of the Roman Empire','本片描写的是罗马帝国逐步走向灭亡的过程。罗马皇帝晚年时决定将王位传给贤臣利比亚斯，而不是传给王子康莫德斯，因而被毒死。利比亚斯并没有作罗马的皇帝，而是辅佐自己的好友康莫德斯登上皇位，但却引来皇帝的记恨，于是派他去守边疆。新皇帝登位，治国无术，残暴不仁，因为赠税问题引起各联邦群的反抗，而带头的正是姐姐露西拉公主。新皇帝派遣利比亚斯去征讨，利比亚斯面对着爱人，却依然选择了忠君，但是皇帝却抓住了他与公主准备烧死他们。利比亚斯最后终于杀死了这个昏君，带着公主远离皇室而去。自此，罗马帝国逐渐走向灭亡……','The Most Magnificent Re-Creation . . . Of An Ancient Empire . . . Launches A New Epoch In Motion Pictures . . .',19000000,4750000,4.229942,6,33,188,'1964-03-24','en','/ggrPUKNYFZ6ogs896ZiT0lQG9Tr.jpg',2.6077197525865388,3,'2026-09-10',2,NULL,NULL),(17287,'活死鸡的攻击','Poultrygeist: Night of the Chicken Dead','阿比没有想到自己的女友原来是个同性恋，气恼的他决定不去上大学，而是在女友经常抨击的美国快餐鸡肉馆里找了份工作。问题是，这家快餐馆建立在印第安人的墓地上，当那些印第安人的灵魂附身到那些死鸡上，将会发生什么事呢？',NULL,0,0,3.905877,5.9,41,103,'2006-12-26','en','/vSeehH4s274kdZXEMKnPE2tlqco.jpg',2.650930102994744,3,'2026-09-10',2,NULL,NULL),(17332,'独奏者','The Soloist','《洛杉矶时报》的记者斯蒂夫·洛佩兹（小罗伯特·唐尼饰）最近有些流年不利，离婚不久的他在报社里他一直负责着一个专栏，常年来也积累了不少的读者，不过最近，他一直在写的专栏灵感枯竭，斯蒂夫找不到更好的题材来让他发挥，但主编给他的压力也越来越大，几次让斯蒂夫萌生转行的念头，转头骑着自行车早锻炼的时候，又因为要避让一只正在公路上悠闲遛弯的小狗而摔了个头破血流，在医院缝了十来针，伤口还没好的他，为了寻找新的新闻素材，不得不带伤上阵，四处奔波。　　某一天，斯蒂夫在街上偶遇了一个拣丢弃不要的东西的拾荒者（杰米·福克斯饰），坐在街边的这位黑人青年自顾自的拉着小提琴，而他身边则是拿着手推车装满的整整一车丢弃不要的东西。这位黑人拉出的旋律极其动听，吸引了斯蒂夫的注意，等着他走过去之后才发现，小提琴上竟然只有两根弦！靠这两根弦他也能拉得这么好，这让斯蒂夫有了强烈的好奇心，交谈下才得知，这名黑人青年叫纳撒尼尔·埃尔斯，而且他还自称去过城里最好的音乐学院进行学习。可为什么这么有天分的音乐人，会沦落到如今到街上拣丢弃不要的东西的地步呢？　　抱着这个疑惑，斯蒂夫打电话到了纳撒尼尔曾经就读的音乐学院，校长解开了他的疑惑。原来纳撒尼尔患有精神分裂，虽然他很有音乐天分，但却无法像正常人一样生活、学习，最终只能退学，靠着拾荒来解决温饱问题。斯蒂夫对纳撒尼尔产生了深深的同情，他给纳撒尼尔买了新的小提琴，并且和他结下了友谊，帮助他走出精神疾病的困扰，而且让纳撒尼尔重新站到了演奏的舞台上。同时，斯蒂夫也在纳撒尼尔的身上找到了新专栏的创作灵感，这个夜晚露宿街头，白天四处拾荒的独奏者让斯蒂夫的心灵受到了深深的触动……','Life has a mind of its own',60000000,31720158,17.299333,6.6,234,109,'2009-04-24','en','/u6nYX7ZSrU5YovJlMSSKgIcGksA.jpg',3.094381939541565,3,'2026-09-10',2,NULL,NULL),(17334,'电话情缘','The Other End of the Line','\"普拉亚（Shriya Saran 饰）是一个土生土长的印度女孩，成长在一个死板保守的典型印度家庭中，做着一份信用卡公司电话接线员的平淡工作。作为一个印度女孩，美国自由开放的作风和多元化的生活对普拉亚有着致命的吸引力，她不仅练就了一口流利标准的英语，甚至捏造了一个虚假的身份，她告诉每一个打电话给她的客户，说自己来自旧金山的珍妮弗。\r 一次偶然中，普拉亚接到了一个名叫格兰杰（杰西·麦特卡尔菲 Jesse Metcalfe 饰）的男人的电话，两人聊得十分投机，甚至约定了见面。为了维持谎言，普拉亚搭上了前往美国的飞机。普拉亚的离去让她的父亲雷蒙（阿努潘·凯尔 Anupam Kher 饰）火冒三丈，原来，他早已经在印度帮普拉亚找到了满意的夫婿。为了追回叛逆的女儿，雷蒙一家人竟然也踏上了美国的土地。\"',NULL,14000000,0,3.393648,6.1,50,106,'2008-10-29','en','/uiLgARBzUiE7PPRiJILXSh4zOIW.jpg',2.6950762837200224,3,'2026-09-10',2,NULL,NULL),(17339,'纳瓦隆第十突击队','Force 10 from Navarone','炸毁德军纳瓦隆大炮后，队长马龙和破坏专家米勒是仅存的生还者，现在上级派他们执行另一项更艰巨的任务，就是炸毁一条让德军和意军得以联结的桥梁。而队长马龙另外还有一个秘密任务，就是要处理掉德军潜伏在我军的间谍尼科莱，而马龙是唯一曾经见过他的人。',NULL,5000000,7230000,5.348446,6.4,91,118,'1978-11-01','en','/3bFRwivCZuXx7fHWt4SpYaiHkNL.jpg',2.837467905683646,3,'2026-09-10',2,NULL,NULL),(17345,'飞越生命','Flywheel','身为汽车代理的杰奥斯汀，贯以卑劣的手法销售二手汽车，为求成功卖出车辆，不择手段。其 处事态度渐渐影响到他和亲人的关系。但一次整修跑车的经验，让他体会到了上帝的力量，从 中检讨自己的所作所为。杰奥斯汀在事业上，在与亲人的关系上，在自己的生命里，慢慢看到 了上帝的光辉。',NULL,0,0,1.048524,6.8,19,120,'2003-01-01','en','/5M5h80QGQq5BXxcpoT1wkaxPdwm.jpg',2.491934558302689,3,'2026-09-10',2,NULL,NULL),(17379,'最后的假期','Last Holiday','体态丰腴的黑人女子乔姬娅（奎恩•拉提法 Queen Latifah 饰）是新奥尔良一家餐饮厨具连锁店的普通店员，生活在社会底层的她生性乐观，总是幻想无数的可能。她喜爱美食，暗暗喜欢着一位男同事，然而因种种原因这些都无一达成。某天，一个意外改变了乔姬娅的人生，在医院的例行检查中，她被诊断患有名为“蓝氏综合症”的绝症，只剩下三周左右的生命。倍感绝望的乔姬娅决定尽情享受最后的时光，她辞去工作，取出所有积蓄，乘飞机前往欧洲，只为品尝仰慕已久的名厨戴笛尔（杰拉尔•德帕迪约 Gérard Depardieu 饰）的手艺。在此期间，她入住昂贵的总统套房，滑雪、做SPA、游走上流社交圈。她的个性言语与生活作风引起了名流们的注意……','She always thought she was somebody special... and she was.',45000000,38399961,6.156015,6.4,119,112,'2006-01-13','en','/cSEHiuAY75r5dGqySIoyp5k4Tt1.jpg',2.899541624758321,3,'2026-09-10',2,NULL,NULL),(17403,'初恋十五十六时','How to Deal','Mandy Moore stars as Halley, a young hip high school student who\'s convinced true love doesn\'t exist based on the crazy relationships around her. Her mother is divorcing her father who is dating a younger woman Halley can\'t stand. Her crazed sister is planning a wedding but has second thoughts and her best friend has fallen madly in love for the first time leaving Halley to feel even more alone.','Rule #1 There are no rules.',0,0,3.199784,5.7,42,99,'2003-07-18','en','/pD87iTm4MP7JNcxIUssAbpri8nF.jpg',2.6510775546235124,3,'2026-09-10',2,NULL,NULL),(17431,'月球','Moon','未来世界，随着科技的飞速进步，地球的污染也越来越严重。为了遏制这种现状，一家名为月能工业有限公司的企业应运而生。该公司致力于月球能源的开发，通过采集氦-3来满足地球对能源的需求。月能公司在月球设有基地，山姆·贝尔（山姆·洛克威尔 Sam Rockwell 饰）正是该基地 上唯一的工作人员。山姆是公司聘用的合同工，他已在月球孤零零地生活3年，陪伴他的只有智能机器人戈蒂（凯文·斯派西 Kevin Spacey 饰）。枯燥乏味的生活令山姆归心似箭，在还有两周就离开月球的时候，山姆偶然遭遇一起事故。醒来后的他发现戈蒂似乎对其有所隐瞒，公司高层也拒绝他的回程请求。山姆借机逃出基地，却在事故发生地点发现另一个自己……本片荣获2009年爱丁堡国际电影节最佳英国影片奖、2009年西雅图国际电影节最佳男主角奖。','The last place you\'d ever expect to find yourself.',5000000,9760104,46.114184,7.6,1794,97,'2009-06-12','en','/35IU0Mq0zFsN1mYwDGts5mKc77n.jpg',3.883506855606046,3,'2026-09-10',2,NULL,NULL),(17436,'线人','The Informers','改编自「美国杀人魔」作家同名畅销小说。描述1980年代洛杉矶一群人纸醉金迷的放荡生活，无论是金字塔顶端的好莱坞富商、摇滚巨星、以及资深记者，或是底层阶级的守门人与窃贼，他们混杂在一群乳波浪臀的金发尤物或猛男酷哥之中，夜夜笙歌饮酒嗑药狂欢，却不知道他们早已身陷危机之中。','Greed is good. Sex is easy. Youth is forever.',18000000,382174,6.333869,4.4,60,98,'2008-11-05','en','/yiXkvghbkYMQ3iMyhiI08GgtonC.jpg',2.701815974362158,3,'2026-09-10',2,NULL,NULL),(17577,'恶魔的坟墓','The Devil\'s Tomb','该片是一部有血腥、色情、暴力还有惊悚的元素混合的一部影片，影片中的每个人在自己内心深处都有脆弱的伤口，也成为恶魔控制其思想的渠道，一次次出现的幻觉其实代表了大多数人内心的欲望、信仰等东西，最终逃出恶魔的坟墓的人才是坚守自己信仰的人，不受外界的干扰，准确作出自己的选择。','An evil entombed for 2000 years... until now.',10000000,0,5.099472,4,53,90,'2009-05-26','en','/ex0dNOuABfkWVrNFfhsC0qTviA2.jpg',2.6686415904463963,3,'2026-09-10',2,NULL,NULL),(17578,'丁丁历险记','The Adventures of Tintin','电影改编自比利时漫画家埃尔热（Hergé）笔下风靡全球多年的同名作品《丁丁历险记》。故事跟随着一个充满好奇心的年轻记者丁丁（杰米贝尔 饰）和他忠心无比的狗狗白雪，他们发现一艘藏有惊爆秘密的模型船，于是丁丁受到这个流传几世纪的秘密吸引，并引起残暴恶棍萨卡林（丹尼尔克雷格 饰）的注意，因为萨卡林相信丁丁偷了跟红色拉克姆有关的无价宝藏，不过由于狗狗白雪、坏脾气的航海家阿道克船长（安迪瑟金斯 饰）及笨手笨脚的侦探搭挡杜庞与杜邦（赛门佩吉和尼克弗斯特 饰）的帮助，丁丁将会游历半个地球，智取并赶过他的敌人，热切地寻找船舰独角兽号的最后落脚处，因为那正关键着一艘失事船的庞大财富……以及一则古老的诅咒。','This year, discover how far adventure will take you.',130000000,371940071,89.938296,6.7,2061,107,'2011-10-25','en','/fQZ3sLR1Fi63NMsNRbjm9q5qODJ.jpg',3.8265637219155053,3,'2026-09-10',2,NULL,NULL),(17610,'元年','Year One','在遥远的数千年以前，那时候的人类以部落狩猎而扎堆居住，其中就有这么两位猎人瑞德（杰克·布莱克饰）与奥（迈克尔·塞拉饰）。瑞德和奥都是部落里人人嘲笑和看不起的对象，因为他们的狩猎技能实在是差得可以，每逢猎人出去打猎，这两位要不是空手而归，要么是陷入猎物的包围圈，要让其他人来解围。长久这么下去，部落的人深深的感到一点：瑞德和奥拖了整个部落的后腿。于是，经过一次全部落的公投，瑞德与奥被部落酋长宣布：驱逐出部落，永远不得回来！  　　不过咱们的瑞德和奥可不觉得这是什么要命的判罚，因为这两位早就不想在部落里呆了。对于他们来说，这里每天的生活就是狩猎、吃饭和睡觉，实在是沉闷得要死，他们对外面未知的世界相当好奇，一直都想好好的探索探索部落外的土地，这次的驱逐令不就正好满足了他们的心愿么？于是瑞德和奥带上自己赖以生存的石矛就踏上了旅程……  　　雄心勃勃的瑞德和奥不知道的一点是，他们身处的时间恰好就在《圣经：旧约》所写的世界里，因为这个原因，他们的旅程也就正好成为了见证旧约一个个故事发生的过程，他们不仅见到了因为偷尝禁果而被上帝驱逐的夏娃所生下的该隐（大卫·克罗斯饰），还碰上了一直跟该隐关系不怎么好的亚伯（保罗·路德饰），甚至还跟犹太人的祖先亚伯拉罕（汉克·阿扎利亚饰）做起了朋友。不过这些都不算什么，因为他们最重要的任务就是帮助印安娜公主（奥利维亚·王尔德饰）摆脱一场政治阴谋带来的暗杀行为，因为瑞德已经彻底被这位漂亮的公主所迷上了。瑞德与奥在他们的奥德赛旅途上，慢慢的明白了自己生存的意','Meet your ancestors',60000000,62357900,25.293538,4.6,524,97,'2009-06-18','en','/qF573jdJYwtCbXVXPDn4xu8nW2a.jpg',3.0617810174247118,3,'2026-09-10',2,NULL,NULL),(17622,'五十活死人','Fifty Dead Men Walking','1980年代，爱尔兰内部最纷扰的时期，一名刚满22岁的青年Martin McGartland（Jim Sturgess饰），受英国警方的命令，到爱尔兰共和军（IRA）内部卧底，担任间谍提供情报，以阻止IRA的恐怖活动及瓦解反抗军势力。 他小心翼翼的隐藏身份，并接受各种严刑拷打，最后得以进入组织，经过长时间的卧底，Martin的身份还是曝了光，为了逃避组织下的格杀令，他开始了一连串艰辛的逃亡之旅。',NULL,0,0,4.481897,6.1,35,117,'2008-09-10','en','/ahHguslRzE5Qgx8KTJvlDeSEJE2.jpg',2.6219977643106804,3,'2026-09-10',2,NULL,NULL),(17644,'Barney\'s Great Adventure','Barney\'s Great Adventure','Mom and dad dump son Cody, daughter Abby, her best friend Marcella and a baby on the farm with Grandpa and Grandma. Purple dinosaur Barney soon appears to entertain kids, and when a large colorful egg deposited on a farm by a shooting star is accidentally carted off, Barney and kids start their chase for it',NULL,0,0,0.722911,2.9,8,76,'1998-01-01','en','/tSadXiI88soRyS4mcSr7PsKWaqN.jpg',2.3020851377451383,3,'2026-09-10',2,NULL,NULL),(17654,'第九区','District 9','1990 年，一艘巨大的飞船出现在地球上空，人们惶恐不安，却又分外好奇。经过一段时间紧张的等待，外星飞船始终没有动静。人类终于小心翼翼靠近它，强行走进舱内，结果发现了不计其数的外星人。他们形容丑陋，宛如虾子，而且健康状况极差，虚弱无力。原来这是一群来自外星的难民，他们最终被地球人接纳，并隔离在南非约翰内斯堡的一片区域内生活，此地名为“第九区”。经过长达 20 年的繁衍，外星难民的数量扩张至 180 万之多，且和周边人类的矛盾冲突不断，越来越多的人类呼吁将“大虾”赶出地球。MNU（列国同盟组织）经过磋商，决定将外星难民迁移到更为偏远的区域。MNU 外星事务部门的特工威库斯（Sharlto Copley 饰）专门负责搬迁工作。威库斯在动员过程中傲慢随意，与当地居民冲突频频。最终，他为自己的行为付出代价，外星人的神秘流体将其感染，威库斯慢慢变成了外星人的模样。此时威库斯才真正体会到了外星移民在地球上受到的不公待遇，他决定做些什么改变局面……','You are not welcome here.',30000000,210819611,63.13678,7.3,3382,112,'2009-08-05','en','/tuGlQkqLxnodDSk6mp5c2wvxUEd.jpg',4.035740684383394,3,'2026-09-10',2,NULL,NULL),(17663,'清秀佳人','Anne of Green Gables','马修（理查德·法恩斯沃斯Richard Farnsworth饰）和玛利亚（科琳·杜赫斯特Colleen Dewhurst饰）自觉年事已高，决定收养一个男孩来帮助他们料理农场里大大小小的事务。然而，孤儿院却闹出了马大哈，将一个名叫安妮（梅根·佛洛斯Megan Follows饰）的红发女孩送到了爱德华王子岛上。\r 　　安妮非常的活泼可爱，整天都有着说不完的话，问不完的问题，这让向来严肃缺乏幽默感的玛利亚感到招架不来。然而，随着时间的推移，老少之间渐渐产生了真挚的情谊。安妮梦想能够成为一名小说家，并且为了实现梦想而拒绝了一直爱慕她的少年吉尔伯特（强纳森·哥伦比Jonathan Crombie饰）的求婚。',NULL,0,0,8.772574,8.2,68,199,'1985-12-01','en','/z1owlDzKO3DQpFKNFBnuQlPF891.jpg',2.826712284832717,3,'2026-09-10',2,NULL,NULL),(17707,'铁狱魔难','Brokedown Palace','艾莉丝是个从高中毕业的边缘少女，她为了庆祝好不容易得来的高中毕业，特地游说她的乖乖牌知己，塔蓝妮一同前往泰国，来一个不一样的旅行。就这样，两人骗父母要去夏威夷玩，事实上两人已飞往传说中的情色之都，泰国。','Their graduation present was a trip to paradise, but they never thought they would land in hell.',25000000,13000000,7.296459,6.2,111,100,'1999-08-13','en','/pWxoggA0KCS5oMPDOjIDYZYzryE.jpg',2.8785247662706395,3,'2026-09-10',2,NULL,NULL),(17708,'联邦大蠢探','Corky Romano','心地善良的兽医可奇罗曼诺（克里斯凯坦饰）某天接获许久未曾联络的父亲来电。原来可奇的父亲，同时也是黑道老大，因为涉嫌不法活动即将被定罪，罗曼诺的「家族生意」眼见着即将化为灰烬。此时，老罗曼诺突然发现，可奇是家族里唯一可以拯救他免于牢狱之灾的不二人选。忠厚老实的可奇为了年迈卧病的父亲只好硬着头皮上场，成为美国联邦调查局的卧底探员─痞子桑。可奇的伪造证件显示他是最最顶尖的探员，让他在FBI的日子无比难过。出过多次化险为夷的任务之后，可奇慢慢发现原来他的父亲根本是被陷害，决定还他一个清白。','Undercover and Out The Way!',11000000,23978402,3.495758,4.1,54,86,'2001-10-12','en','/aLgzSIgHTyWggrP7ieDVYE3PB8g.jpg',2.6702782499812816,3,'2026-09-10',2,NULL,NULL),(17709,'骑警杜德雷','Dudley Do-Right','斯奈利和达利从小就是性情迥异的死对头，即使是长大后达利变成威风的骑警，斯奈利仍为无恶不赦的大坏蛋，在一次抢劫活动，斯奈利占据了小镇，一切都在乱无法纪的状况下进行，达利要如何解决这混乱的场面让小镇恢复平静？','From the creator of \'George of the Jungle\' comes a new kind of hero',70000000,0,8.792054,3.8,48,77,'1999-08-27','en','/4LP5BieqdFNlCFjxsvaA3d6hGGd.jpg',2.656072619984634,3,'2026-09-10',2,NULL,NULL),(17710,'大头仔天空','Hey Arnold! The Movie','生活在大都市里，很多时候意味着现代化的隔离，繁华难以掩盖心灵的孤单与寂寞。但对于生活在一个看上去有些古怪的社区的阿诺德来说，生活变成了一种亲密与温馨。这个热爱运动，穿着笔挺衣服，带着墨镜并且长着橄榄球一样脑壳的四年级学生，与他的爷爷奶奶一起生活在这里，和他的朋友杰拉尔德以及对他又爱又恨的海尔格一起享受着美好的童年时光。但是当贪婪的商业大亨史艾克煽动市长，准备将社区房地产收购用来建设他的伟大商业街区的时候，阿诺德他们的生活面临着最大的挑战。他与杰拉尔德一起，制定计划，并在“超级英雄”圣布里奇特和声音低沉的神秘人的帮助下，与史艾克和他的党羽们开始了一场“社区保卫战”。他们能在推土机把这些老房子被铲平前找到那份关键性的文件么？还是在下一部阿诺德的系列影片中他们只能异地而居了呢？让我们看下去吧。','A Big Problem Calls For a Big Head',0,0,5.856363,5.6,62,76,'2002-06-28','en','/etxcq4qiFNi5p0q71APw8MNzPPT.jpg',2.7347673196258238,3,'2026-09-10',2,NULL,NULL),(17711,'波波鹿与飞天鼠','The Adventures of Rocky & Bullwinkle','Rocky and Bullwinkle have been living off the finances made from the reruns of their cartoon show. Boris and Natasha somehow manage to crossover into reality and team up with Fearless Leader, an evil criminal turned media mogul with some evil plans up his sleeve. Rocky and Bullwinkle must stop the three of them before they wreak havoc.','This summer it\'s not the same old bull.',76000000,35134820,8.981427,3.9,87,88,'2000-06-30','en','/xCFSsftt2rglC81I6QLWcZSTCBM.jpg',2.7557187146071946,3,'2026-09-10',2,NULL,NULL),(17734,'命运的十三个交叉口','Thirteen Conversations About One Thing','\"《命运的十三个交叉口》命题是关于\"\"生活\"\"，更精确来说是烂透了的生活，藉由多位毫不相关的角色，他们的无心之过却对另一个生命造成严重冲击。毫无疑问人一生中都在追求幸福快乐的生活，然而现实总是背道而驰，看了这部电影我们明白理想遥不可及，即使达到也是一时的绚烂而已，唯有坚守信念、乐观面对才是长治久安之道。\r 影片之初，一个老人告诫一意气风发的律师好运是不可能持久的，指出一名中了两百万乐透彩的员工当下辞职不乾，结果亲朋好友人人觊觎这意外之财，发财后的生活反而不好过，过不了多久又回公司上班了。这名律师不以为意，他认为今日成就全是自己辛苦打拼的结果，绝非运气，结果当天晚上他因为酒醉驾车肇事，果然乐极生悲。更由于身为律师之故，对于法律责任心知肚明，让他更无法接受事实而近乎情绪崩溃。\r 一名高中物理老师，对于自己即将迈入一成不变的生活感到害怕，他出外寻找刺激却仍然无法填补空虚，发现到头来不过是另一种形式的例行公事，终于对人生感到心灰意冷，移情作用下，他也当面刺破学生对未来的憧憬：「你为何想当医生？帮助病人延续痛苦？」而这名学生隔日便自杀了！\r 一名愤世嫉俗的保险公司主管，官作的越大心眼也越小，总爱找一个笑口常开的职员麻烦，然而他的所作所为只是更加突显两人根本上的差异，一者钻牛角尖；一者有容乃大、无入而不自得。\r 《命运的十三个交叉口》充满了如上的人生插曲，让观众重新审查自己的生活态度，影片中所有命运注定、机缘巧合的安排，让人人在无意识的状况下擦身而过却深受影响，无非是为了呈现出人生的不确定性，我们难以掌控意外发生，可以改变的是自己的心态，例如一句话虽能击毁一个人的自信；一个微笑也却足以化解忧郁，快乐希望的源头其实都出自我们的内心。\r 结局是本片的神来之笔，不仅利用多线式电影惯用的人物交会，同时也蕴含了时间上的交会，之前所看到半独立的十三段故事，并非完全按照时间顺序排列，直到结局我们明白了事情的来龙去脉，当他们还在对捉摸不定的未来顾影自怜时，观众则早已看清了命运之手的狡猾，也明白了即使遭遇不顺遂仍该坦然面对的最高境界。「命运的十三个交叉口」或许是人生茫茫大路上的一面借镜，令人反覆吟咏仍觉有味。\"','Ask yourself if you\'re really happy.',0,0,6.997495,6.4,25,104,'2001-09-02','en','/mb3mEfzAudrPpQIxRzpLM12aiMV.jpg',2.560113550369762,3,'2026-09-10',2,NULL,NULL),(17768,'春光满古城','A Funny Thing Happened on the Way to the Forum','英国名导演理查德．莱斯特应邀赴好莱坞拍摄的第一部电影，改编自同名百老汇歌舞喜剧，并由原剧男主角胖子谐星泽罗．莫斯特尔饰演主人翁——一名古罗马的奴隶。他为了争取自由，先得帮主人追求到一名高级妓女，于是使尽各种手段，偷诈拐骗无所不为，整个罗马城的人几乎都被他逼疯了。整部影片拍得相当热闹有趣，演员也有逗笑演出。难得的是默片时代喜剧巨匠巴斯特．基顿也在片中客串一角，饰演女主角安妮特．安德烈的父亲。','Something for Everyone!',0,0,8.902102,6.1,24,99,'1966-10-16','en','/85GetJipw1F2tAGUEwbdD16VFLO.jpg',2.5529658970274984,3,'2026-09-10',2,NULL,NULL),(17795,'总统拍档','My Fellow Americans','由于现任总统把他俩卷入到了一桩丑闻之中，两个曾争吵不休的前任总统不得不走到了一起，走遍全国寻求证据以证明自己的清白。一路上趣事不断，笑料百出，却也让他们了解到了真正的美国，以及自己曾给普通百姓所带来的影响。更意想不到的是正当他们焦头烂额、疲于奔命时，又遭到了一伙武装分子的连连追杀','A comedy about life, liberty and the pursuit of two ex-presidents.',0,0,2.809378,6.3,46,101,'1996-12-20','en','/AkZUWdXXuOSat3J9HaHXm7HPtqA.jpg',2.679587728263642,3,'2026-09-10',2,NULL,NULL),(17813,'亚历克斯与艾玛','Alex & Emma','亚历克斯（卢克·威尔逊 Luke Wilson 饰）是一个失败的作家，由于负债累累，追债人在教训了他一顿后砸掉了他用以谋生的电脑，并且警告他，如果不能在一个月内还清债务，他的性命将面临危险。好在亚历克斯的脑中已经有了一个他自认为精妙的构思，无奈没有了电脑，他只得雇佣了速记员艾玛（凯特·哈德森 Kate Hudson 饰）协助他完成创作。\r 　　没想到艾玛竟然是个个性固执的女人，对于亚历克斯的叙述，她总是会提出这样或是那样的反对意见，让亚历克斯抓狂的是，艾玛所提出的构思似乎才是正确和有趣的。就这样，在矛盾和争吵之中，亚历克斯的小说创作还算顺利的进行着，眼看着大限将到，他能够顺利完成吗？','Is it love... or are they just imagining things?',30000000,15368897,4.352422,5,68,96,'2003-06-16','en','/1CVw4MMqeBdkUs3DfCDWkaP6O3U.jpg',2.7346500544125227,3,'2026-09-10',2,NULL,NULL),(17820,'画舫璇宫','Show Boat','一位潇洒的密西西比河赌徒赢得了 \"表演船 \"船主女儿的芳心。','It\'s NEW!',2300000,11000000,1.606314,6.9,18,107,'1951-07-13','en','/sk7s574pI9QAi6uVqbTg0bnLEUC.jpg',2.4825246575081605,3,'2026-09-10',2,NULL,NULL),(17834,'脱线教父','A Simple Wish','奥利弗是一位怀才不遇的歌手，女儿安娜贝尔相信魔法，暗暗企求仙女的帮助。谁知求来的却是魔法不精的仙童莫瑞，尽管莫瑞热心助人，却总是弄巧成拙，他不仅把自己和安娜贝尔送到了千里之外的蛮荒之地，还把准备试唱的奥利弗变成了一座塑像。 偏偏被仙女协会开除的魔女克劳迪亚也来捣乱，为了实现独霸天下的野心，她收缴所有魔棍，当她发现唯一流落在外的魔棍握在莫瑞之手，便发起了疯狂的进攻。被魔女困住的莫瑞和安娜贝尔利用智慧逃出了魔掌，并解救了被克劳迪亚陷害的仙女首领。当他们终于赶到奥利弗化成的塑像前，最好的恢复时机已经错过了……','Anabel made a wish. Murray made a mess',28000000,8345056,1.767479,5.5,46,86,'1997-07-11','en','/cfyJ7yIvNTlz2ooH8iU6r0pxAMj.jpg',2.6629521867745436,3,'2026-09-10',2,NULL,NULL),(17880,'都是戴茜惹的祸','Because of Winn-Dixie','十岁的小女孩欧宝（安娜索菲亚·罗伯 AnnaSophia Robb 饰）三岁时母亲离家出走，成为她心灵的创伤。父亲的牧师职业让二人一直过着颠沛流离的生活，这次来到了佛罗里达的一个小镇。小镇上的居民生活沉闷，不善于表达自己的真心，欧宝晚上对着天空许愿：希望上天赐给她一个朋友。\r 一天欧宝在超级市场购物，突然一条流狼狗从货物架冲了出来，气急败坏的员工正想捉拿这只狗，欧宝急中生智告诉员工这狗是自己的，还给它起了个名字——温·迪西。机灵的温•迪西从此成了欧宝最忠实的朋友。\r 自从温·迪西出现，欧宝的生活变得快乐起来，这对好朋友的活力也在感染着小镇上的每个人，蜜糖般的欢笑开始在小镇上流传。','Discover what happens when you go looking for a miracle and a miracle comes looking for you.',14000000,32645546,3.334804,6.1,61,106,'2005-02-18','en','/oMUFS7HmIyTeui5xuoIEkPYTWC8.jpg',2.7373033103000832,3,'2026-09-10',2,NULL,NULL),(17908,'我的小狗斯齐普','My Dog Skip','故事发生在1942年美国密西西比州的一个人名叫亚苏的小镇上，那时二战正如火如荼地进行着，可是在这里，战火的硝烟仿佛只有在新闻上才能看到。小镇上居住着一名叫威利·莫里斯的内向自卑的8岁男孩。威利的父亲叫杰克·莫里斯，是一个严厉但心肠很好的人，在西班牙内战中失去了双腿，威利极端自我保护的性格大多来自于他。\r 威利总是自己一个人静静地、孤独地审视周围的一切。他不懂得与人交往，更不善结交女孩子。威利唯一的好朋友也是他的精神支柱是隔壁邻居丁克·詹金斯，丁克是镇里的体育明星，但是他也要起程准备跨海参战。威利的母亲爱伦是个非常能干的女人，她深深地了解威利现在最需要一些自由和朋友。在威利9岁生日时，母亲实现了自己的承诺，送给威利一只小狗。欣喜若狂的威利给小狗取名斯齐普。\r 斯齐普活泼好动的天性深深感染了威利，他们经常一起外出奔跑，威利也因此与学校里最漂亮的女孩爱伯·怀特建立了友谊。斯齐普作为威利与爱伯的“媒人”，经常陪伴两人看电影。在斯齐普的帮助下，威利开始真正成为“男孩中的一员”。\r 就在这时，丁克意外地回到了亚苏，他在了解了战争的真相后，作了一名逃兵。曾经对丁克充满英雄式崇拜的威利开始对战争与人类行为的复杂关系有了新的看法。丁克没有来看威利的第一场棒球比赛，威利把失望全撒在斯齐普身上，斯齐普狂奔而去……','Every family needs an optimist.',7000000,0,5.675535,6.5,69,95,'2000-01-14','en','/nnPv7RuSn6UaPjZussIFljZdWS8.jpg',2.7793515137649423,3,'2026-09-10',2,NULL,NULL),(17917,'雾都孤儿','Oliver!','奥利弗（马克·莱斯特 Mark Lester 饰）是一名孤儿，从小在教会中长大。九岁时，奥利弗被派遣到工厂做工，之后又来到殡仪馆成为了学徒。奥利弗的聪慧和机敏让他很快就在殡仪馆里站稳了脚跟，但与此同时，他亦遭到了同伴们的妒忌，他们故意挑衅激怒奥利弗，最终奥利弗离开了殡仪馆。无家可归的奥利弗过起了四处流浪的生活，经过漫长的旅途，他来到了伦敦。一个名叫道奇（杰克·瓦尔德 Jack Wild 饰）的扒手将奥利弗带到了匪首费金（朗·穆迪 Ron Moody 饰）的面前，就这样，奥利弗成为了他们中的一员。一次意外中，奥利弗被警察逮捕了，但随后，他被证实是无辜的，当事人布朗罗先生（Joseph O\'Conor 饰）对奥利弗感到十分愧疚，于是收留了他，奥利弗的生活能够从此走上正轨吗？','Much Much More Than a Musical!',10000000,37402877,8.305998,7,103,153,'1968-09-26','en','/1XJgoaOWKrqxkKeBKWLKSigqG8c.jpg',2.8942513970098447,3,'2026-09-10',2,NULL,NULL),(17926,'未经发现','Undiscovered','在地铁站，一位纽约模特爱上了一个潦倒的音乐家。事业的成功让纽约的模特决定去洛杉矶开始自己的演艺事业，在经济人和母亲的支持下，模特来到了洛杉矶，在那里她认识了一位演员朋友，在事业的巅峰期，她再次在地铁站遇到了潦倒的音乐家，她的演员朋友决定帮助她追求到那位音乐家。在那段时间中，音乐家的事业也在蒸蒸日...','They Know Each Other By Heart.',9000000,1046166,2.009597,4.5,12,97,'2005-08-26','en','/7G9HOjUBcq1NDwff7Mc5GFhINSB.jpg',2.3875038167119222,3,'2026-09-10',2,NULL,NULL),(17979,'圣诞颂歌','A Christmas Carol','故事改编自狄更斯的作品《圣诞颂歌》，主要讲述了性情刻薄、冷酷的守财奴艾柏纳泽·斯克鲁奇，面对温暖的圣诞节，却讨厌周遭的一切庆祝活动。于是上天派来 3个精灵让他看看自己过去的所作所为，以及亲友私下对他的态度。这一切渐渐唤醒他人性的另一面——同情、仁慈、爱心及喜悦，瞬间，他那固有的自私及冷酷迅速崩塌，消失殆尽，从此变成了一个乐善好施的人。','Season\'s Greedings',200000000,325233863,39.744242,6.6,1095,96,'2009-11-04','en','/wZpDggInUoRGEqY7P8I1WOXza3x.jpg',3.532277420061153,3,'2026-09-10',2,NULL,NULL),(17994,'魔鬼碟仙','Witchboard','三个朋友在摆弄通灵板时，成功联系上了一个小男孩的鬼魂。当恶灵马尔菲特占据其中一人的身体后，灾祸便悄然降临。','It\'s more than just a game.',0,0,7.151154,5.9,58,98,'1986-12-31','en','/d5lDHBzEgBkgAarXpUl56u2vM8c.jpg',2.7308390215720135,3,'2026-09-10',2,NULL,NULL),(17995,'DysFunktional Family','DysFunktional Family','Between sets from his hilarious live stand-up routine, in which he riffs on everything from Michael Jackson to terrorism, comedian Eddie Griffin tours his hometown of Kansas City and introduces viewers to his eccentric clan in this edgy mockumentary. Griffin\'s uproarious family members include oddballs such as Uncle Buckey, a former pimp, and Uncle Curtis, who possesses an extensive porn collection ... much of which he filmed himself!',NULL,0,0,1.580027,6.1,4,89,'2003-04-04','en','/jYfGKG94Mfs8HMjqXsn9aIVqGTK.jpg',2.1868558234520727,3,'2026-09-10',2,NULL,NULL),(18041,'致命八卦站','Gossip','三个大学生为了一个课程项目，决定编造一个关于校园里最受欢迎的女孩的无稽之谈。但随着谣言的传播，情况开始失控。','It can turn you on, or turn on you.',14000000,5108820,5.833687,5.5,68,90,'2000-04-21','en','/1fyQiQyBFlqjeqgT6sAEh5vo4Fe.jpg',2.750840701010393,3,'2026-09-10',2,NULL,NULL),(18045,'The Dark Hours','The Dark Hours','Dr. Samantha Goodman is a beautiful, young psychiatrist. Burnt out, she drives to the family’s winter cottage to spend time with her husband and sister. A relaxing weekend is jarringly interrupted when a terrifying and unexpected guest arrives. What follows is an extraordinary night of terror and evil mind games where escape is not an option.',NULL,500000,0,1.428483,5.5,22,80,'2005-03-11','en','/yOYCpZ7jsMedfkHQpXQJw83F3GL.jpg',2.5125213813816307,3,'2026-09-10',2,NULL,NULL),(18065,'次日危机','Next Day Air','Two inept criminals are mistakenly delivered a package of cocaine and think they\'ve hit the jackpot, triggering a series of events that changes ten people\'s lives forever.',NULL,0,0,2.747402,5.3,36,84,'2009-02-06','en','/wLNzff5sWBWrKU4EI5gf4ZhUBKs.jpg',2.612678193356201,3,'2026-09-10',2,NULL,NULL),(18074,'风情万种','Duets','他们是六个有着不同境遇，但都一心想挣脱生活束缚的人。他们努力地追寻着自己的梦想，同时又在原有的生活中痛苦挣扎。一场卡拉OK大赛给了他们改变命运的机会，也许赢得了比赛就意味着新生活的开始。\r 　　出租车司机比利是个安分守己的年轻人，虽然在刚刚出狱的女老师那里听到了许多关于人生灰暗的观念，但他仍旧坚信世界是美好的。然而女友与自己的朋友通奸的事实让比利大受打击，与女友在酒吧不欢而散之后，他遇到了同样是人生失败者的女孩苏西，二人同病相怜，阴差阳错地一起踏上了追寻梦想的征程。在这过程中，二人互相鼓励，给了彼此重新开始生活的希望。\r 　　同样想改变生活的还有被工作压得近乎崩溃的推销员托德。他有着向往成功的美国式梦想，为了家庭生计他一年到头四处奔波，累得筋疲力尽，却得不到家人关怀。一怒之下，托德离家出走，并在一个偶然的机会下认识了有着天使般的嗓音，却迫于生活而拦路打劫的刑满释放人员瑞格，出于相同的爱好，两人开始了疯狂的卡拉OK之旅，并在旅途中结下了深厚的友谊；\r 　　四处流浪的中年歌手瑞奇则在教堂里意外地发现刚刚丧母的女孩丽芙竟是自己的女儿，这个突然出现的亲人让他措手不及。而丽芙则为了得到失去已久的父爱，坚持跟随父亲一起上路去参加歌唱比赛。\r 　　虽然这六个人有着各自不同的人生，但却有着相同的目标，那就是参加在美国中部的内布拉斯加州奥马哈城举办的“卡拉OK”大奖赛，为了赢得比赛，他们不惜旅途奔波，进出一个个充满破锣嗓子的酒吧。上演着一段段笑料百出但却感人至深的动人故事。\r 　　经过长途跋涉，六个人终于如愿以偿的参加了歌唱大赛。在追求梦想的过程中，他们各有所得。丽芙不仅与父亲互相谅解，共享天伦之乐，而且与初次邂逅的比利一见钟情；而销售员托德也重获妻子的关怀，开始了自己事业的新一轮冲刺；瑞格虽然因为抢劫被警察击毙，但在生命的尽头，他得到了最宝贵的友谊；而苏西则继续着她成为明星的梦想。','Six littles souls in search of a little harmony.',0,0,2.25453,5.5,34,112,'2000-09-09','en','/isxHRG54S1bz1A1CAlPaAAoh65k.jpg',2.6027705626470947,3,'2026-09-10',2,NULL,NULL),(18079,'九个皇后','Nueve reinas','《九个皇后》(Nine Queens)是阿根廷导演Fabian Bielinsky初试啼声即一鸣惊人的黑色喜剧。故事以老千马可(Marco)和菜鸟胡安(Juan)两个金光党在便利商店中的初识为起点，马可提议两人搭挡作案强过一人单打独斗，因为马可，胡安被卷入一桩贩卖古董邮票Nine Queens的交易行为中，进而无意间卷入了马可的家族遗产纷争之中，爱上了马可的妹妹……','Sticky & Square',1500000,0,8.589355,7.4,153,114,'2000-08-31','es','/v8l85vxFe9J1uEvK9qyIMBlYJNv.jpg',3.0142027526060655,3,'2026-09-10',2,NULL,NULL),(18126,'Hannah Montana: The Movie','Hannah Montana: The Movie','When Miley Stewart (aka pop-star Hannah Montana) gets too caught up in the superstar celebrity lifestyle, her dad decides it\'s time for a total change of scenery. But sweet nibblets! Miley must trade in all the glitz and glamour of Hollywood for some ol\' blue jeans on the family farm in Tennessee, and question if she can be both Miley Stewart and Hannah Montana. With a little help from her friends – and awesome guest stars Taylor Swift, Rascal Flatts and Vanessa Williams – will she figure out whether to choose Hannah or Miley?','She has the best of both worlds...now she has to choose just one.',35000000,155545279,13.788422,6,449,102,'2009-04-10','en','/gx41l9Bq3x7lF20Cx3TkGhHjvCj.jpg',3.1790015738632547,3,'2026-09-10',2,NULL,NULL),(18147,'无人陪伴的儿童','Unaccompanied Minors','由于暴风雪的袭击，机场取消了所有的航班，兄妹斯潘塞（戴连·克里斯托福 Dyllan Christopher 饰）和凯瑟琳（Dominique Saldana 饰）被滞留在了机场内。在航空术语里，斯潘塞和凯瑟琳被称为“UM”，即“无人陪伴的未成年人”，因此，他们被送往了机场专门设置的“UM看护中心”。  　　在看护中心里，有着许多和兄妹两情况相同的孩子，在那里，兄妹两认识了白富美格蕾丝（Gina Mantegna 饰），假小子多娜（奎恩·谢法德 Quinn Shephard 饰），天才查理（泰勒·詹姆斯·威廉姆 Tyler James Williams 饰）和宅男蒂莫西（布莱特·凯利 Brett Kelly 饰）。由于受不了看护中心内的混乱和吵闹，斯潘塞兄妹和他们的四个小伙伴们决定出逃。','No plane, no parents, no problem!',26000000,0,10.006282,5.4,66,90,'2006-12-08','en','/7yhaXxwxs1fIOyuPv3YuE2fea0t.jpg',2.751915406553833,3,'2026-09-10',2,NULL,NULL),(18162,'失落的大陆','Land of the Lost','年纪不小的瑞克·马绍尔（威尔·法瑞尔饰）是朋友眼里公认的怪人，他是一名科学家，但在同行眼里他是出了名的老不正经，经常有些荒唐的想法和行为，不过让大家都羡慕他的是，瑞克身边的助手霍莉（安娜·弗莱尔饰）总是能够替有些缺心眼的瑞克整理好各种大大小小的繁忙事务，最重要的是，霍莉可是个在圈内远近闻名的大美女！　　这天，又有新想法的瑞克决定去野外进行一次探索研究，而对野外勘探不怎么在行的他除了带上离开了她就寸步难行的霍莉之外，他还叫上了野外营救专家威尔（丹尼·麦克布莱德饰）一起出发。相对于瑞克的不正经，威尔就显得一丝不苟，尤其是他觉得野外遍布危险，因此必须听他行事，而向来不按牌理出牌的瑞克可不管这么多，两人在探险路上没少吵架，多得霍莉在中间调停，两人才不至于闹得翻脸。　　三个人进入了科罗拉多州，乘着皮筏漂流的时候意外的被河水的漩涡卷进一个神奇的世界，这里到处都是上古时期的生物，不但有巨大的吸血虫、特大号的霸王龙，还有着会英语的猿人和外形不怎么好看的外星来客……这里，就是“Land of the Lost”，失落的大陆！　　瑞克面对这个世界显得相当兴奋，但棘手的问题很快就来了，在这个处处危机的世界，三人如何才能生存下去？而且最重要的是，他们如何才能回到现实世界呢？解决一切问题的关键，似乎都在那个名叫查卡（乔玛·塔昆饰）身上……','Right place. Wrong time.',100000000,68688831,19.38841,5.3,381,102,'2009-06-05','en','/lSMApOuFXaXKzS4Rrn1X9dQxklV.jpg',3.0853813912314223,3,'2026-09-10',2,NULL,NULL),(18191,'艾德蒙','Edmond','一位看似温和的商人埃德蒙·伯克拜访了一个算命的人，听到了一句话，这句话促使他突然离开了妻子，去寻找他生活中缺失的东西。与陌生人和不良分子的相遇削弱了他长期抑制的愤怒，最终埃德蒙爆发了暴力。','Every fear hides a wish.',10000000,0,2.803642,6,50,82,'2005-08-31','en','/2VFdGJDrl5n9WoC7d4I07hN3v5c.jpg',2.6918016393079025,3,'2026-09-10',2,NULL,NULL),(18206,'与她在一起','Alone With Her','偷窥是道格（科林·汉克斯 Colin Hanks饰）生活中的重要部分。他曾经在情路上受伤，希望能找到厮守终生的人，艾米（安娜·克劳迪亚·塔兰康 Ana Claudia Talancón饰）就是他的目标。他用隐秘的摄像头摄下她生活中的一举一动，通过偷窥去还原艾米生活的形状，再伺机接近她。于是，艾米的私人生活就这样毫无遮掩地呈现在镜头面前。','Anytime. Anywhere. He\'s watching.',1000000,10018,2.175696,6.2,20,78,'2006-04-28','en','/636EGinwlVDyXuDo4l27hETmze2.jpg',2.500562353125668,3,'2026-09-10',2,NULL,NULL),(18238,'女同志吸血鬼杀手','Lesbian Vampire Killers','在传说中的年代，女吸血鬼卡米拉以女性为猎物祸及英国乡间，终于有勇士借圣剑威力将其封印，但卡米拉旗下一干女性吸血鬼得以隐匿……英国青年吉米（Mathew Horne 饰）最近被红杏出墙的神经质女友抛弃，好友胖子弗莱奇（James Corden 饰）则丢掉了小丑的工作，二人为排遣郁闷，前往用飞镖确定的不知名英国乡下远足。两人临近目的地，在一间酒吧内见识神秘牧师向当地居民发出警告，四名靓丽女子旅游经过此处，于是六人结伴前行，其中一人罗提似对当地的吸血鬼传说颇有认识，并默默属意吉米。当夜，女吸血鬼们袭击了这些年轻人，并将吉米和罗提掳走作为唤醒卡米拉的祭品，弗莱奇与随后赶到的牧师挖掘出圣剑，与这些擅于摆造型的女吸血鬼展开了战斗……','After Twilight, The Real Party Starts.',0,0,6.632891,5.3,124,86,'2009-03-16','en','/3IROnPMgDnI1TYQ4PZBB0nn6CwX.jpg',2.861926067902603,3,'2026-09-10',2,NULL,NULL),(18239,'暮光之城2：新月','The Twilight Saga: New Moon','贝拉的18岁生日到了，父亲送了她礼物。爱德华大方示爱，并为她讲述了意大利吸血鬼王族的传奇。爱德华的红发妹妹爱丽丝特意为贝拉举办的生日派对,期间,贝拉无意中划伤了手臂，遭到加斯帕的袭击，靠着爱德华的庇护，才逃过一劫。不过，此后，爱德华逐渐疏远贝拉，并提出了分手。这令贝拉心寒，但爱德华也有苦衷，仍在暗中保护贝拉。贝拉处于空窗期，昔日老友雅各布嘘寒问暖，两人的关系也由此升温。此后,贝拉因为跳崖获救,才得知雅各布是狼人,专门对付吸血鬼。与此同时，不知情的爱德华以为贝拉自杀，心灰意冷，来到意大利请求王族结束自己的生命……','The Next Chapter Begins.',50000000,709827462,94.815867,5.6,2436,130,'2009-03-15','en','/l3eepAtbP4yGRKpIactlE1qkB7x.jpg',3.6254055234290274,3,'2026-09-10',2,NULL,NULL),(18240,'假结婚','The Proposal','玛格丽特是美国一家知名出版公司的高管，办事出色，为人却极为强势，一旦她的身影出现在办公室，气氛立即会降至冰点，员工们在表面上无不对她噤若寒蝉，在心底则暗呼她为“女魔头”。玛格丽特对这一切置若罔闻，照旧施行铁腕政策，可就在她事业如日中天之际，一个噩耗却几乎把她砸晕——因为某些技术性原因，她的签证无法续签，而她本人不得不被遣送回原籍加拿大。为了保住她苦心经营的一切，玛格丽特决定和助手安德鲁伪装结婚，以取得在美居住权。在半利诱半胁迫之下，安德鲁答应了这个荒唐的要求。移民局将在一周后对两人进行测试，而玛格丽特对安德鲁还是一无所知，这个周末，她和安德鲁一同回到他的家乡……','Here comes the bribe...',40000000,317375031,36.238968,6.7,1804,108,'2009-06-01','en','/uvXXKVHuoenWgkH8ItFYSYr92Rp.jpg',3.670328156184581,3,'2026-09-10',2,NULL,NULL),(18254,'烽火赤焰万里情','Reds','二十年代初期，响往共产主义的美国名记者约翰·雷德千方百计跑到十月革命之后的苏俄体验生活，追求理想的政治国度，并写出了轰动世界的报导文学《震动世界的十天》。然而，他最后对共产主义彻底失望，重回自由世界。\r 　　电影摘要： 　　第一幕：雷德和露易丝·布莱恩特在波特兰相遇。 　　第二幕：20世纪10年代在格林威治村的知识分子生活。雷德和露易丝被尤金·奥尼尔和艾玛·高曼等思想家吸引。 　　第三幕：雷德和露易丝接受俄国革命的影响。 　　第四幕：雷德试图在美国建立共产党。 　　第五幕：雷德来到俄国接受布尔什维克的帮助宣传社会主义。1920年雷德去世，年仅32岁。 　　五个部分充满了乱糟糟的争吵，换句话说，这很难让你对这段历史激起足够的兴趣。在第一部分，观众必须容忍长时间谄媚性的诱导。在这之后，则是雷德和露易丝一段奇怪的爱情：当他们彼此凝视，伴随着革命的高潮和八十年庸俗的音乐，这对恋人的爱情似乎也达到了顶点。第二部分似乎值得一看，事实上，如果影片在这个间断之前结束的话，会比现在这个版本好的多，因为工人运动造成的气氛足以充实这部电影。也许沃伦·比蒂想得太多了，而且多是西方社会对苏联幻觉式的认知，所以才造就了这只嘈杂的万花筒。','Not since Gone With The Wind has there been a great romantic epic like it!',32000000,40382659,4.602185,7.1,67,195,'1981-12-25','en','/AeiKdVVM93fwfQG1m3N0cgVZgHl.jpg',2.7854998824399093,3,'2026-09-10',2,NULL,NULL),(18276,'我爱猫头鹰','Hoot','A young man (Lerman) moves from Montana to Florida with his family, where he\'s compelled to engage in a fight to protect a population of endangered owls.','It\'s time to stand up for the little guys.',0,0,7.712206,5.5,44,91,'2006-05-05','en','/99VEv4lpXbV4VF9aWH8lzQaEVVU.jpg',2.667536030805811,3,'2026-09-10',2,NULL,NULL),(18292,'乔治·华盛顿','George Washington','在一个酷热夏日里，美国南方日渐凋敝的乡村中，一群孩子被迫直面一系列艰难抉择。这部由大卫·戈登·格林执导的首部长片，以精心构建的叙事与优雅的摄影，谱写出一曲关于青春的沉思录。荣获大奖的群戏阵容贡献了非凡表演。本片是当代美国独立电影一部令人惊艳而独具特色的作品。[标准收藏]',NULL,0,0,2.058834,6.4,36,89,'2000-10-01','en','/g9nZi8u5LqSrVKEpSm199EM4hk5.jpg',2.6266463522048547,3,'2026-09-10',2,NULL,NULL),(18320,'The Young Victoria','The Young Victoria','From Academy Award® winners Graham King and Martin Scorsese, along with the makers of Gosford Park and The Departed, comes the story of Queen Victoria’s early rise to power. From an object of a royal power-struggle to her romantic courtship and legendary marriage to Prince Albert, Emily Blunt (The Devil Wears Prada) gives a stunning performance as the young Victoria. Packed with drama, romance, breath-taking cinematography, lavish costumes and featuring an outstanding British cast including Jim Broadbent, Harriet Walter, Mark Strong, Paul Bettany, Miranda Richardson, and Rupert Friend, The Young Victoria has captivated British audiences, and is the film that Company magazine called “an epic British film, which will sweep you up in her remarkable story.”','Love rules all.',35000000,27409889,16.343317,7,322,105,'2009-03-04','en','/iGyuReyij3bPCtzJdSjTR8PR0pa.jpg',3.2073216179333843,3,'2026-09-10',2,NULL,NULL),(18357,'草地英熊','The Country Bears','乡村熊的铁杆粉丝，年轻的贝里·巴林顿，离家出走加入他的英雄们，但发现乡村熊音乐厅有被贪婪的银行家取消抵押品赎回权的危险。在贝里的帮助下，乡村熊们让乐队重聚，举行一场全力以赴的重聚音乐会，以挽救使他们成名的音乐厅。','It\'s A Bear Getting The Family Together!',35000000,0,6.908351,4.3,20,88,'2002-07-26','en','/z0K5vNYSLDT8KOrXBrhwMj2Xnd8.jpg',2.496140790713517,3,'2026-09-10',2,NULL,NULL),(18360,'博物馆奇妙夜2：史密森尼之战','Night at the Museum: Battle of the Smithsonian','由于在纽约自然历史博物馆担任警卫有出色表现，拉瑞（本•斯蒂勒 Ben Stiller 饰）出任某家电小公司的CEO，而且还在电视上接受了著名脱口秀主持人的访谈，儿子对他仰慕，爱情如影随形，一派春风得意的样子。不过，好景不长，当他故地重游，却意外发现馆长已经因为经营惨淡准备关门大吉了。所有的藏品正在装箱，准备挪到华盛顿的史密森博物馆继续展出。这让拉瑞感到有些气愤，他觉得自己有责任重振博物馆之雄风，于是他决定留下来再做一晚警卫，以唤起那些老朋友的共同努力。事实上，在搞定了罗斯福（罗宾•威廉斯 Robin Williams 饰）、林肯、拿破仑、伊凡雷帝和阿尔•卡邦等人之后，他遭遇了一个劲敌——邪恶的古埃及法老的卡门拉，二人在夜晚再度上演了博物馆的惊魂对决……','When the lights go off the battle is on.',150000000,413106170,81.781591,5.9,1971,105,'2009-05-20','en','/niGFi5KOY430h5FId6ymL4WMy7N.jpg',3.6214701212545024,3,'2026-09-10',2,NULL,NULL),(18405,'杀人不分左右','The Last House on the Left','克林伍德夫妇携女儿玛丽驱车来到湖畔别墅度假，刚抵达不久，玛丽便开车去找朋友佩姬玩。期间她们邂逅碰巧路过此地的青年贾斯汀，在男孩的邀请下，玛丽和佩姬一同前往贾斯汀所在的旅馆。在旅馆中，她们遇见贾斯汀的父亲克鲁克。克鲁克是一个变态杀人犯，他刚刚被弟弟法兰西和女友莎蒂从监狱救出。为避免泄漏行踪，他们劫持了玛丽和佩姬开车跑路。途中玛丽试图逃跑，由此引发了一连串的血腥事件……','If someone hurt someone you love, how far would you go to get revenge?',15000000,32721635,19.760383,6.2,440,110,'2009-03-13','en','/qMNQEMnJ0DDL9gbFXYzAQa0CxcI.jpg',3.2110111441232374,3,'2026-09-10',2,NULL,NULL),(18442,'诱捕','Decoys','在一间学院的校园里，一连串无法解释的离奇死亡事件，留下了一个个受害者冻结至死的尸体。一名生性腼碘的大学一年级学生开始怀疑两个金发女郎是整个事件的幕后外星人。\r 唯没有人相信他，他只有靠自己去救他的朋友...','They can seduce anyone... Prey it isn\'t you!',5000000,0,3.05434,4.7,33,95,'2004-02-27','en','/hBmkzhN3BsF1DnwlxlwEGVIcITz.jpg',2.588132047340098,3,'2026-09-10',2,NULL,NULL),(18475,'野餐会','The Cookout','美国社会中，黑人和白人的隔膜似乎无法消除，就像篮球很棒的黑人小伙子托德（库伦·潘德Quran Pender饰），尽管他以三千万美金的身价加盟NBA，一夜跻身富人行列，却无助于改变他的肤色和由此带来的麻烦。\r 　　托德在白人区里买了一幢高级寓所，并叫来亲戚朋友助兴，举行隆重而吵闹的传统烤肉宴会。正如黑人的性格那样，烤肉宴会奔放热闹，不拘礼节，成为人人狂欢的美妙时刻。\r 　　这在白人区里引来不满。在白人的眼中，如此胡闹的新邻居简直是这个片区居民的灾星。然而，他们却不了解了这群黑人的优点——他们团结互助，不畏强暴，赶走了前来搅乱险些闹出人命的歹徒。也许，善良友好的托德妈妈，乐观直率的黑人朋友，终有一天能打破黑白世界的隔阂。','This summer, get your grill on!',16000000,12,0.830596,4.6,10,97,'2004-09-03','en','/t5UL6yNoZmirS9RHO4C0HpsVlo8.jpg',2.350230743496191,3,'2026-09-10',2,NULL,NULL),(18480,'Brüno','Brüno','来自奥地利的布鲁诺（Sacha Baron Cohen 饰）是一档德语时尚节目的主持人，生活中他着装怪异前卫，大玩疯狂的同性恋游戏；荧屏中的他更加乖张出格，或诱导嘉宾说出争议性的言论，或干脆大闹T型台秀场。最终，他成名的愿望没有实现，反而被米兰的时装界所驱逐。一夜之间，布鲁诺的事业跌到谷底，连长久以来的同性恋人也琵琶别抱，最后只有忠心耿耿的第二助理鲁特兹（Gustaf Hammarsten 饰）陪其勇闯好莱坞。在洛杉矶，布鲁诺不改其张扬出位的本性，或为嘉宾奉上令人不忍卒睹的“男体盛”、或宽衣解带挑逗议员、甚至将自己的男性器官录进NBC的试播节目中。可想而知，嘉宾及电视台官员的脸色该有多难看。  　　屡战屡败，屡挫屡勇，百折不挠的布鲁诺为了扬名，在娱乐的道路上高歌猛进……','Borat was so 2006',42000000,0,16.122168,5.4,518,83,'2009-07-08','en','/wcUc7TYtsb72dHVb51sYaGIvQsr.jpg',3.1393471331472163,3,'2026-09-10',2,NULL,NULL),(18487,'地铁惊魂','The Taking of Pelham 1 2 3','沃特（丹泽尔·华盛顿 Denzel Washington 饰）是一名纽约地铁调度员，负责控制各条线路的调配运营。某日，一群恐怖分子劫持了地铁123号线，匪首雷德（约翰·屈伏塔 John Travolta 饰）为前美国雇佣兵，声言要提供1000万赎金才释放人质。巧的是，该数额正式保险金、商业贷款等提取的上限。地铁123号线在隧道里飞驰，乘警多人毙命，司机被挟持，乘客人人自危。沃特因工作失职被调离，后因雷德点名，才被迫参与谈判，面对贪污的质问，他的坦诚拯救了一名年轻乘客的生命。面对劫匪提出的高额赎金和苛刻条件，纽约市长如坐针毡，正当他准备划破钱款平息事端之时，丧心病狂的劫匪又突然改变了主意。作为高速运输管理局要员，沃特决定用自己替换人质，与劫匪展开了一场惊心动魄的生死搏斗……','I can\'t get it out of my head. I\'m gonna die today.',100000000,150166126,40.597856,6.2,954,106,'2009-06-11','en','/4IL2KIHaTUSs0xcOlvesWFPe8pE.jpg',3.431383916486928,3,'2026-09-10',2,NULL,NULL),(18501,'天地逃生','Gamer','在不远的未来，技术天才肯•卡斯特（Michael C. Hall 饰）发明了将指令细胞植入人脑的纳米技术，以此为基础，卡斯特开发了两款真人在线操控游戏——“社会”和“凶手”，其中“凶手”是将死刑犯们置入残酷的杀戮战场，由线下的玩家指挥他们作战。卡贝尔（Gerard Butler 饰）是凶手游戏中的一名常胜战士，目前已经从27场比赛中存活，而按照规则，只要他再胜利三次，就可以重获自由。 　　一个反抗组织在暗中策划推翻富可敌国的卡斯特，他们找到卡贝尔在游戏中的线下配合者——少年西蒙（Logan Lerman 饰），并希望他放弃对卡贝尔的操控，因为后者即将面临卡斯特的阴谋暗算。此时的卡贝尔，成为了推翻卡斯特的关键力量……','In the near future, you don\'t live to play... you\'ll play to live.',50000000,40828540,27.631262,5.6,760,95,'2009-09-03','en','/zU95XwDfaLA6NkEMFhFTAdc4RUn.jpg',3.259067897865023,3,'2026-09-10',2,NULL,NULL),(18516,'苏醒的亚当','Adam Resurrected','该片又名《亚当复活》，根据1969年以色列著名畅销小说家尤拉里·卡纽克(Yoram Kaniuk)的作品改编，讲述了德裔以色列小丑演员亚当·斯坦的故事，他被迫在纳粹集中营内为在押犯们表演取乐，最后得以逃过生死劫只是因为能够为进入毒气室的囚犯们拉拉小提琴曲。杰夫·古德布鲁姆(Jeff Goldblum)在片中饰演亚当，威廉·达福则出演集中营指挥官，此人将亚当象条狗一样尽尽羞辱之能事。',NULL,10000000,0,2.574014,6.4,22,106,'2008-08-08','en','/k0Di5lSe0oIzpJle2O9T5di4w3M.jpg',2.5230534574300707,3,'2026-09-10',2,NULL,NULL),(18530,'猫头鹰的哭泣','The Cry of the Owl','影片由 悬疑推理大师Patricia Highsmith（海史密斯.帕特里夏）1962年的小说改编而成，Considine在片中饰演的男主角搬到Stile所在的郊区小镇上，并开始暗中监视她。Speedman在片中饰演Stile被甩的前男友，他谋划报复Stile时发现事情变得越来越复杂……','What would you do if someone was watching you?',11500000,0,4.75919,5.5,29,101,'2009-02-07','en','/h9VizOOadBJixcbpswSqM0bb30c.jpg',2.576177399130691,3,'2026-09-10',2,NULL,NULL),(18533,'布朗森','Bronson','影片根据英国历史上最臭名昭著的囚犯迈克尔·皮特森的故事改编。1974年，一名叫做查尔斯·布朗森的少年结交了一些街头的混混朋友，沾染上了一些不良少年。在那个狂热、躁动的年纪里，他想让自己快点出名，所以在家里做了一把手枪，并且实施了一起邮局抢劫案。战利品一点也不丰厚——区区26英镑，但是他却为此付出了7年牢狱生活的代价。  　　之后，这个少年在监狱里不断犯事、不断被加刑。总共在监狱里呆了34年的他有30年是一个人在禁闭室里独自渡过的。影片着重描写了他的34年的牢狱生涯，在那里，斗殴就是他生活的全部。','The Man. The Myth. The Celebrity.',230000,2260712,18.450613,6.9,733,92,'2008-10-09','en','/6diyyGIbBNiANsdIaCGtyv4IofR.jpg',3.427253357898179,3,'2026-09-10',2,NULL,NULL),(18550,'亡命悍将','Fled','在例行的监狱工作细节中，枪声爆发时，罪犯派珀被绑到网络黑客道奇。 显然，该攻击与黑手党追捕的赃款以及某些人迫切希望掩埋的某些计算机文件有关。 两人并不完全享受彼此的陪伴，他们逃脱了，要想活着到达亚特兰大，必须共同努力。 幸运的是，他们遇到了一个愿意帮助他们的女人。','See how they run.',25000000,17193231,2.77255,5.2,47,98,'1996-07-19','en','/5oGdTgWXCOKerrfdBxJrOlFyifL.jpg',2.6641416921530383,3,'2026-09-10',2,NULL,NULL),(18570,'食品公司','Food, Inc.','随着工业文明的高度发展，各种各样的食物也变得供不应求，但在这看似繁华的背后，食品安全却已到了不容忽视的地步。影片从快餐业入手，逐步向种植业、畜牧业、养殖业延展开去，揭露了大型食品公司经营者为了获取高额利润不惜改变动植物的生长方式和生长周期，他们在经营上取得丰厚的利润，而代价却是公众的健康和安全。在看似清洁的食品加工流水线上，沙门氏菌和希氏大肠杆菌毫无阻碍渗透到食物当中，毒害着人类的生命。由于政策等方面原因，人们无法也无力拒绝大公司强加于身的迫害。在金钱和欲望面前，我们自取灭亡……  　　本片荣获2009年华盛顿影评人协会最佳纪录片奖。','You\'ll never look at dinner the same way again.',0,0,15.017162,7.4,217,94,'2008-09-07','en','/q9bPzpk4PdwKckVcj1Zkhz29FkX.jpg',3.125959421121511,3,'2026-09-10',2,NULL,NULL),(18602,'默文·卡拉','Morvern Callar','默文的作家男友为了死后的名誉，写完新小说后自杀身亡。而默文掩盖了真相，她早已厌倦在超市里卖水果的乏味生活，拿走了男友的钱，把小说冠以自己的名字投稿，随后和唯一的好友一起前往阳光灿烂的西班牙，但旅行并没像想象中那样让她快乐起来……',NULL,0,0,2.507912,7.2,34,97,'2002-01-01','en','/kKGUF97v8a62MtSKM0V6fqDxGTS.jpg',2.6260923972406593,3,'2026-09-10',2,NULL,NULL),(18615,'皮毛','Fur: An Imaginary Portrait of Diane Arbus','1958年，美国纽约。此时的黛安•阿布斯（妮可•基德曼 Nicole Kidman 饰）还是一个只知相夫教子的平凡女人。她生在富有的犹太商人家庭，父母经营着著名的Russek皮草店。从小养尊处优的黛安与身份悬殊的艾伦•阿布斯（泰•布里尔 Ty Burrell 饰）结婚，并努力协助他的时尚摄影工作。来自父母家庭的苛责以及婚后生活的枯燥无聊都让黛安倍感压抑和孤独。某日，一个新搬来的邻居莱昂内尔（小罗伯特•唐尼 Robert Downey Jr. 饰）出现在黛安的生活中，她为对方的神秘所吸引，开始有意识地去注意和探究莱昂内尔的一切。不知不觉间，她的人生悄然发生改变……本片根据Patricia Bosworth在1984年出版的关于黛安•阿布斯的畅销传记小说改编。','A love story.',16800000,2281089,4.358255,5.8,73,122,'2006-08-30','en','/o2ig5NhuvenDT5Og61ARuGKYFIi.jpg',2.769810988088074,3,'2026-09-10',2,NULL,NULL),(18616,'No Man\'s Land: The Rise of Reeker','No Man\'s Land: The Rise of Reeker','A sheriff and his son who are tracking down a group of bank robbers on their way to Mexico, only to discover that they are being stalked by a far more deadly enemy — The Reeker.',NULL,2000000,0,4.346271,4.4,27,88,'2008-05-01','en','/1LAjKJ2Xcmb1ixIKq6ZA3LVq871.jpg',2.548925932209674,3,'2026-09-10',2,NULL,NULL),(18632,'A Dog\'s Breakfast','A Dog\'s Breakfast','If you\'ve never been good at anything in your life, why would murder be any different? Patrick (David Hewlett) has always had a somewhat combative relationship with his little sister Marilyn (Kate Hewlett), but when she brings home her new sci-fi soap star fiancé Ryan (Paul McGillion), it\'s all out war. When Patrick fails to drive a wedge between the happy couple, he reaches for sharper instruments.','Man\'s best friend makes the worst accomplice.',120000,0,2.213889,5.9,24,88,'2007-03-03','en','/w1Fgu2GxGTy4I5zQN3lkMNu4z6e.jpg',2.5357749040789366,3,'2026-09-10',2,NULL,NULL),(18681,'燃情追踪','Eye of the Beholder','默默无名的英国特工Eye（Ewan McGregor 饰）在美国花费了十多年的时间遮蔽一位女士Joanna——她被怀疑是多名凶杀案的凶手，被杀害的总是男士。Eye的妻女已经死去，但是女儿的幻觉却时时出现。Joanna与他的女儿几乎有着同样的身世——在圣诞节被父亲抛弃、孤独地长大——她还有着出众的美貌和难以言喻的魅力，她热衷乔装打扮、善于改换人名，Eye似是守护天使一般，了解她的身世和过去，还在她有难的时候挺身救护。她们的命运相处交叉，处处触碰却始终没有密切同行。 谜一样的故事，有着谜一样的结局。','Obsession is in the eye of the beholder.',15000000,0,4.302941,5.3,42,109,'1999-09-04','en','/4eB1Gw5r3Etbe4su6PhOo6OAN9E.jpg',2.647055584164717,3,'2026-09-10',2,NULL,NULL),(18701,'成为朱莉娅','Being Julia','朱莉娅（安妮特·贝宁 Annette Bening饰）的演艺事业如日中天，伦敦的舞台上她的霸气几乎无人能及。但是，这样一个人前辉煌的女性，却在身后承受着心灵的空虚。她因为事业的成功失去了幸福的家庭，和亲人的关系冷漠疏隔。汤姆（肖恩·埃文斯 Shaun Evans饰）正是趁着这个时机闯进朱莉娅生活的。他年轻、帅气，有着燃烧不尽的激情，把青春的感觉重新灌入朱莉娅的心中。朱莉娅情陷于此，不料在汤姆的心目中，有着另一番打算。年轻女演员想利用汤姆来撼动朱莉娅的一姐地位，初出茅庐的汤姆看不透圈内阴险，竟然乖乖上钩，以为利用和朱莉娅的感情就能大获全胜。然而，不是人人都能成为朱莉娅的，因为她有着过人的洞察力，果断利落的手段和深谙圈内之道的生存法则，时刻准备着给伤害她的人致命还击。','Passion. Obsession. Revenge. Prepare for the performance of a lifetime.',0,0,1.946634,6.4,23,104,'2004-09-03','en','/wiJp4pN2bYgtWQqZYZhGNLeFmx8.jpg',2.530973475176594,3,'2026-09-10',2,NULL,NULL),(18712,'硫磺岛浴血战','Sands of Iwo Jima','太平洋战争最惨烈一役，扭转第二次大战战局的硫磺岛……  1944年6月，联军在诺曼第成功登陆，成为联军战胜的转折点，美军得以将战力转向太平洋，六月登陆塞班岛，七月登陆关岛，麦克阿瑟将军随即又第二度踏上菲律宾国土。日本死守硫磺岛，军力约两万一千人，美军共出动三个师团75000人，舰船495艘，其他尚有驱逐舰，航空母舰等155艘，全力攻击硫磺岛。本纪录片为美军第三司令部摄影队冒死拍摄完成，为当今世上仅存，最忠实纪录第二次世界大战，“血战硫磺岛”之唯一史料！','A Great Human Story... Makes A Mighty Motion Picture!!!',1000000,7800000,3.851,6.2,33,100,'1949-12-14','en','/utpy9JLuyhsxpw2E3yExw23f3eS.jpg',2.6094545435569674,3,'2026-09-10',2,NULL,NULL),(18713,'捣蛋双宝','The Jerky Boys','一部美国搞笑电影。',NULL,0,0,1.735462,4.8,10,82,'1995-02-03','en','/yUbdqyZaeaoNKBQmnmtim1IIAf1.jpg',2.353110169789283,3,'2026-09-10',2,NULL,NULL),(18734,'长岛迷情','L.I.E.','豪依（保罗·达诺 Paul Dano 饰）是个性萌动的16岁男孩，但是在家中很少能得到父亲关心，面对父亲和继母肆无忌惮的做爱只能选择性失聪。豪依只好整日和一群年龄相仿的男孩子混在一起，装模作样的谈论性和女人的话题，但他对其中叫加里（比利·凯 Billy Kay 饰）的一个产生了莫名情感，开始对他言听计从，跟着他到其他街区小偷小摸。一次算不上多成功的入室盗窃后，二人得到一套枪支，并计划卖掉筹钱做旅费出走。枪主是个自称“大约翰”的老头（布莱恩·考克斯 Brian Cox 饰），他手段精明地找到了豪依，想从他们那里讨还枪支，却无意中戳破男孩们友谊的脆弱，接近豪依孤独的内心，豪依心知肚明，大约翰只是个恋童癖老男人，却似乎在他身上找到了缺失的父爱…','On the Long Island Expressway there are lanes going east, lanes going west, and lanes going straight to hell.',700000,1667192,7.731064,6.7,31,97,'2001-01-20','en','/ck5Tkq17M6khEN7JQlQznoYl37L.jpg',2.6112098610959977,3,'2026-09-10',2,NULL,NULL),(18736,'平民天后','The Lizzie McGuire Movie','暑假到来了，我们可爱的少女丽兹·麦戈瑞和几个同伴戈多、凯特和伊桑打点行装来到意大利开始了一段激动人心的夏日之旅。一次偶然中，丽兹被错当成意大利当红的明星伊莎贝拉，并迷上了伊莎贝拉的前男友、英俊的帅哥歌星保罗，丽兹的生活因此而发生了天翻地覆的变化。\r 从一个懵懵懂懂的少女迅速的“进化”成魅力四射的明星，而她周围的人也不由自主地被扯了进来，丽兹的爸爸妈妈得知女儿的奇遇后火速赶往意大利；戈多开始意识到自己对丽兹的真实情感，而丽兹也从这一连串旋风般的事件中了解了明星光环背后的压力与代价，体会到友谊的真正含义。','The only risk in taking an adventure is not taking it at all.',17000000,55534455,11.927667,5.7,280,94,'2003-04-25','en','/xP7YQ2pccDrDTE48eecqKsTnQVI.jpg',3.0510113623155566,3,'2026-09-10',2,NULL,NULL),(18777,'缓慢燃烧','Slow Burn','A district attorney (Ray Liotta) is involved in a 24-hour showdown with a gang leader (LL Cool J) and is, at the same time, being manipulated by an attractive assistant district attorney (Jolene Blalock) and a cryptic stranger.','The truth is just a trick of light.',15500000,1237615,6.630856,5.5,16,93,'2005-09-12','en','/ho43ENDjPpkuMZvBsGTV1STFFik.jpg',2.4602030015378586,3,'2026-09-10',2,NULL,NULL),(18785,'宿醉','The Hangover','When three friends finally come to after a raucous night of bachelor-party revelry, they find a baby in the closet and a tiger in the bathroom. But they can\'t seem to locate their best friend, Doug – who\'s supposed to be tying the knot. Launching a frantic search for Doug, the trio perseveres through a nasty hangover to try to make it to the church on time.','Some guys just can\'t handle Vegas.',35000000,459270619,82.21166,7.2,6173,100,'2009-06-05','en','/A0uS9rHR56FeBtpjVki16M5xxSW.jpg',4.2086393899701475,3,'2026-09-10',2,NULL,NULL),(18808,'亡命天涯路','Highway','杰克（杰瑞德·莱托 Jared Leto 饰）因为爱上了不该爱的女人而遭到了黑帮的追杀。和好朋友派洛特（杰克·吉伦哈尔 Jake Gyllenhaal 饰）一起，杰克踏上了逃亡的旅途。派洛特坚持要将两人的目的地定在西雅图，却不愿意告诉杰克这究竟是为什么。最终，黑帮还是知道了杰克和派洛特的下落，危险离两人越来越近。\r 　　途中，两人邂逅了名为凯西（塞尔玛·布莱尔 Selma Blair 饰）女孩，这个活泼开朗的女孩让杰克坠入了情网之后。杰克和派洛特的“逃亡队伍”不断的壮大着，一路上，他们遇见了一群有一群怀着迥异的目的想要前往西雅图的人们，当他们最终抵达目的地之时，会有什么在等待着他们呢？','It started as a desperate escape and became the wildest ride of their lives',14000000,0,3.419685,5.6,37,97,'2002-01-01','en','/jttL1E4eCQn7tHBbYlUkMz865Q4.jpg',2.624051758307628,3,'2026-09-10',2,NULL,NULL),(18823,'诸神之战','Clash of the Titans','不堪忍受奥林匹斯众神残暴压迫的阿戈斯国王亚克里斯（Jason Flemyng 饰）奋起反抗，对至高无上的神明大为不敬。在冥王哈迪斯（拉尔夫·费因斯 Ralph Fiennes 饰）的怂恿下，天神宙斯（连姆·尼森 Liam Neeson 饰）决定对愚蠢的人类施以惩罚。遭遇海难流落到阿戈斯的青年珀修斯（萨姆·沃辛顿 Sam Worthington 饰）是宙斯和亚克里斯的皇后生下的半神，他亲眼目睹哈迪斯所施下的恐怖神迹，并得知哈迪斯将释放北海怪兽克拉肯惩戒世人，除非亚克里斯将美丽的公主安德鲁美达（艾莉克莎·黛沃洛斯 Alexa Davalos 饰）作为牺牲献给众神。在女神爱娥（Gemma Arterton 饰）的点拨下，珀修斯知晓了自己的身世与使命，于是决定启程杀死北海怪兽并摧毁哈迪斯的阴谋……','Titans will clash.',125000000,232713139,47.686442,5.6,2233,106,'2010-04-01','en','/rUPbISixwKSSjX4xHaGb9Js1phR.jpg',3.5012930366423007,3,'2026-09-10',2,NULL,NULL),(18828,'妙探追缉令','Double Take','影片又名《双重身份》，主人公塔利尔是一位纽约的银行家，他过着非常快乐的上等生活，没想到一天却莫名其妙地遭人陷害，成为警方通缉的头号杀人犯。塔利尔只好狼狈出逃，却遇见街头小混混弗莱特。弗莱特不仅伶牙俐齿，而且头脑机灵，有了他的帮助，塔利尔总算顺利的从警察重重包围中逃脱。影片的笑料主要集中在两人互换身份的逃亡路上，洋相百出，令人捧腹。更搞笑的是后来，他发现他的化名福莱迪也是被通缉逃亡者中的一员，而且在警察眼中福莱迪要比他本名重要的多。所以他必须同时摆脱犯毒集团追杀和法律制裁。','One big shot. One big mouth. The switch is on.',0,0,1.903405,5.5,24,88,'2001-01-12','en','/gNyudcF4Z8LVJn4IxauOptG6dcb.jpg',2.53123810086305,3,'2026-09-10',2,NULL,NULL),(18840,'伯爵夫人','The White Countess','故事发生在20世纪30年代的上海，托德（拉尔夫·费因斯 Ralph Fiennes 饰）是一位生活和事业都陷入了瓶颈的外交官，整日混迹于欢场和酒馆之间。刚刚来到这里的时候，托德也有过宏大和高远的理想，但渐渐失去的视力和复杂的权谋争斗让他无法再在职业的道路上前进下去。  在一家夜总会里，托德结识了名叫索菲亚（娜塔莎·理查德森 Natasha Richardson 饰）女子。索菲亚曾是声名显赫的伯爵夫人，如今却沦为艳舞女郎，为了抚养十岁的女儿，她甚至不得不出卖自己的肉体。就是这样境遇相同的两人，不断的相互吸引着。不久之后，日侵华战争全面爆发，而此时，托德才发现了自己压抑已久的对于索菲亚的强烈爱意，这对心心相印的男女最终能否终成眷属呢？',NULL,0,0,4.488547,6.9,21,135,'2005-10-30','en','/65AKidOOKrfyQkiVYtkgDJVM4CA.jpg',2.521865570763098,3,'2026-09-10',2,NULL,NULL),(18841,'迷失的异型','The Lost Skeleton of Cadavra','Remember the good old days when anyone with a camera and a few thousand bucks could schlep up to Bronson canyon and quickly make a cheap sci-fi/horror B-movie? Well, they\'re back! The Lost Skeleton of Cadavra is an affectionate, meticulous re-creation of those notoriously cheesy clunkers, as a gaggle of beloved stereotypes pursue \"that rarest of radioactive elements - atmospherium.\"','No One Can Stand Its Mental Power!',0,0,1.680525,6.5,30,90,'2001-09-12','en','/nGUjqu7DotLx6yfakAeqaj8D1FO.jpg',2.5878989136764594,3,'2026-09-10',2,NULL,NULL),(18869,'吉米与朱迪','Jimmy and Judy','Two misunderstood suburban kids challenge society and run from the police while documenting all of their deeds with a digital camera.',NULL,0,0,1.255771,5.4,8,99,'2006-01-01','en','/eCrr9LMCYpHlKzzKNXlTcMBs9xD.jpg',2.3114497045451556,3,'2026-09-10',2,NULL,NULL),(18885,'忍者小英雄2','3 Ninjas Kick Back','洛奇、科特和唐唐是三个学功夫的小子，他们回日本参加典礼，在典礼中转赠一柄在五十年前赢得刀给赢家。 师父向他们证实这刀关系着黄金洞穴的秘密，所以他希望这三个小鬼可以赢得这次的比赛。','Colt, Rocky and Tum Tum are back for bigger kicks in an all new adventure',0,0,2.645722,4.5,48,93,'1994-05-06','en','/kXuh3c0DyvqSGo0DBatoemBwEtz.jpg',2.6550156787097716,3,'2026-09-10',2,NULL,NULL),(18886,'捍卫入侵者','Flight of the Intruder','根据史蒂芬昆兹（Stephen Coonts）的畅销小说所改编，并由执导过「黑狮震雄风」、「王者之剑」等卖座强片的约翰 米利厄斯(John Milius)亲自兼任编、导之职；越战期间，海军飞行员杰克（布莱德强森Brad Johnson）在一艘航行于南海的航空母舰上担任A6战斗机--匿称”入侵者”--的飞官，当其通讯官不幸因公殉职后，令杰克不禁开始质疑起这场战争是否有任何意义；在另一名同样愤世嫉俗的军官协助下，杰克开始了一场个人的战争，他决定枉顾上级指令，轰炸藏有大批飞弹的北越军事重镇--河内，好为死去的好友讨回公道！  越战期间，海军飞行员杰克（布莱德强森Brad Johnson）在一艘航行于南海的航空母舰上担任A6战斗机——匿称“入侵者”——的飞官，当其通讯官不幸因公殉职后，令杰克不禁开始质疑起这场战争是否有任何意义；在另一名同样愤世嫉俗的军官协助下，杰克开始了一场个人的战争，他决定枉顾上级指令，轰炸藏有大批飞弹的北越军事重镇--河内，好为死去的好友讨回公道！','The only thing they can count on is each other.',35000000,0,6.81729,5.7,31,115,'1991-01-18','en','/tzjCePBItSRfZxLnOd3KBGHQIJl.jpg',2.596876600921628,3,'2026-09-10',2,NULL,NULL),(18892,'风骚坏姊妹','Jawbreaker','谁说聪明才智不等于美丽，她们自认是集智慧与性感于一身的呛辣妹妹！寇妮、茱莉、丽兹三位在学校的风云人物，她们因恶作剧害死了一位女孩，三个女孩开始紧张渐渐的漏出狐狸尾巴...','Suck it and see...',3000000,3076820,4.337685,5.9,90,87,'1999-01-30','en','/hXNrltkJz9QsQgk6OwxYs7IAGSS.jpg',2.8161972760108585,3,'2026-09-10',2,NULL,NULL),(18900,'冷血','In Cold Blood','根据美国作家楚曼卡波堤著名的报告文学拍摄而成。导演采取黑白纪录片式的纪实手法，忠实地观察可以说是一个极其详尽和细腻的犯罪个案纪录。两名冷血罪犯如何在一个堪萨斯州的农家犯下冷血的灭门血案，直到两人被警方逮捕直至处刑。',NULL,3500000,13007551,7.821438,7.4,82,134,'1967-12-14','en','/sPEvsif5Y70mfVvtU39iOyrVJdF.jpg',2.8502649451574213,3,'2026-09-10',2,NULL,NULL),(18923,'天涯家园','A Home at the End of the World','一次偶然中，鲍比（柯林·法瑞尔 Colin Farrell 饰）与乔纳森（达拉斯·罗伯特斯 Dallas Roberts 饰）重逢了，原来，两人曾是童年时期的亲密玩伴，鲍比羡慕乔纳森拥有温柔的母亲和温馨的家庭，乔纳森在鲍比的身上看到了自己渴望许久的自由与不羁。多年后的重逢让两位老友都十分兴奋，鲍比更是搬进了乔纳森的屋子成为了他的室友。乔纳森并非独居，和他住在一起的是漂亮姑娘克莱尔（罗宾·怀特 Robin Wright 饰），随着时间的流逝，鲍比发现自己不可救药的爱上了她，而鲍比明白，在克莱尔和乔纳森之间，他鱼与熊掌不可兼得。在一个配置特殊的家庭中，在友情与爱情之间，善良的鲍比不知该何去何从。','Family can be whatever you want it to be.',6500000,1548955,5.483531,6.8,45,96,'2004-07-23','en','/o1YC1V30LR0LJzGR6JtbzpDSTYy.jpg',2.6896849912893646,3,'2026-09-10',2,NULL,NULL),(18925,'面对巨人','Facing the Giants','《面对巨人》片讲述一位教练如何重拾信心与勇气，并用信仰击败恐惧的故事。\r 在泰勒（埃里克斯·肯德里克 Alex Kendrick 饰）的六年教练生涯中，他从未在赛季中获胜。当球队中最优秀的队员决定转学后，他们连在新赛季中获胜的希望都随之而去了。赛季一开始便输了三场比赛之后，泰勒发现那些爸爸们决定解雇他。随之而来的一系列压力令他完全失去了希望。他将如何重拾勇气与信心，用信仰击败恐惧呢？','Never give up. Never back down. Never lose faith.',100000,10178331,4.563698,6.6,64,111,'2006-09-29','en','/1eY8O7fIGcmwetNqvwnnkQB0LYK.jpg',2.7624725955985974,3,'2026-09-10',2,NULL,NULL),(18937,'魔剑奇兵','Quest for Camelot','一千年前的布列颠群岛上，当时王刚登基为王。当邪恶的罗勃和他残暴的助手格利分抢走亚瑟王的石中剑亚瑟王的石中剑石中剑掉在一座浓密可怕的魔法森林；凯莉是一个好胜心强的女孩，她硬著头皮闯进去……','An evil knight gives nobility a bad name.',40000000,38172500,16.059443,6.9,190,86,'1998-05-15','en','/pLfFEQ9HTw0HRvBkW3nI9RUze03.jpg',3.0598494429015184,3,'2026-09-10',2,NULL,NULL),(18947,'海盗电台','The Boat That Rocked','1966年英国，北海上飘扬着一条游艇，这里有一群充满了摇滚梦想的年轻人，在24小时不间断播着自己喜欢的音乐，他们叫做海盗电台。全英国的年轻人，无论种族、信仰，都热衷于海盗电台的音乐。被学校开除的卡尔（Tom Sturridge 饰）被海盗电台的首领昆汀（Bill Nighy 饰）引荐入伙。通过游戏，他逐渐认识这些激情四射的DJ，其中，头牌DJ大胡子科特（Philip Seymour Hoffman 饰）是个善于拿音乐说事的美国佬；戴夫虽然大腹便便却颇讨女孩喜欢……羞涩的卡尔似乎总是难以融入，对于喜欢的女孩也手足无措。2年前离开的DJ加文（Rhys Ifans 饰）突然回归让科特面临危机，而西蒙则发现与妻子艾兰诺的婚姻另有隐情。与此同时，政府高官与国家电台却开始注意到这些无政府主义的小团伙，并多次召开紧急会议商议对策，从最初的封口令，到后来的军队驱逐，对抗愈演愈烈……','On air. Off shore. Out of control.',50000000,36348784,31.02233,7.2,666,116,'2009-04-01','en','/l7CBRLAXUnHi0kp2krhLtlJvtWI.jpg',3.472512632431516,3,'2026-09-10',2,NULL,NULL),(18975,'新木偶奇遇记','The Adventures of Pinocchio','本片改编自意大利作家科洛迪的同名童话，讲述了木偶皮诺曹为了变成一位真正的男孩，历经的种种艰险，从一位顽劣的孩子转变为一名懂事的孩子的故事。','A new angle on the classic tale... And that\'s no lie!',0,0,6.718497,5,54,90,'1996-07-26','en','/rGPFPkUmPam6arT22ey8jWpKzL2.jpg',2.6962738658760097,3,'2026-09-10',2,NULL,NULL),(19052,'Light It Up','Light It Up','On a winter day in a southside Queens high school, events collide and six students are suddenly in an armed standoff with the NYPD. At the school, classrooms freeze, teachers come and go, resources are scant.',NULL,0,0,1.212956,6.6,7,99,'1999-11-04','en','/sHbII8OHz2uoyOpPAVYe0LIJcdN.jpg',2.2894897427954604,3,'2026-09-10',2,NULL,NULL),(19084,'约翰逊一家的幸福之旅','Johnson Family Vacation','5口之家，1500英里，3天的行程，这就是约翰逊一家年度家庭聚会的全部安排。一家之主的内特·约翰逊(塞德瑞克饰)当然是责无旁贷的司机兼管家，车上其余成员分别是满腹牢骚的妻子桃乐西(温妮萨·威廉姆斯饰)，缺乏沟通而总幻想成为说唱歌手的儿子DJ(李奥宝娃饰)，有“洛丽塔”倾向的大女儿以及一直想“与狗同行”的小女儿。\r 　　一家人从加州出发，终点则锁定了中部的密苏里州。计划的身影通常总是在变化强行干涉中不得不改变着自己的步伐，这次编剧的思路也是如此。从所驾那辆豪华黑色林肯轿车“罢工”开始，约翰逊一家陷入了一场麻烦不断的怪圈当中。被人追赶复仇，被一个粗鲁的用餐者施暴，遇到修女伸手搭车佯装不知却被一个漂亮的搭便车女郎迷得神魂颠倒，甚至由于随手仍出车外的饮料瓶击中了后面摩托车警察而遭到拘捕……琐碎而妙趣横生。不过约翰逊一家的意志相当坚定，没有什么能够阻止他们前往密苏里州的决心，不过，首先得找出密苏里州到底在哪里才行！','Take the ride.',12000000,31179516,4.623609,4.7,30,97,'2004-04-07','en','/3F6bmetJSJvqLCB9PMxpNz1sngB.jpg',2.5732615927428095,3,'2026-09-10',2,NULL,NULL),(19150,'狐群狗党','The Crew','常言道“金屋、银屋，不如自己的狗屋”，世上没有一个地方能与家相提并论。本片主人公的家就在美国迈阿密市南海滩旁一栋破旧不堪的老人院里。他们是4位已过花甲之年的老头子，分别叫Bobby Bartellemeo、“黑蝙蝠”Joey Pistella、“钢砖”Mike Donatelli 和“大嘴巴”Tony Donato。别看他们现在穷困潦倒，年轻哪会可都是久经沙场的黑手党成员。\r 白色的沙滩上，性感女模cavort正在搔首弄势，为高级时装杂志拍封面照片，可他们却无心欣赏，因为他们即将面临被赶出老人院的命运。老人院的对面是繁华的商业区，地段很好。业主打算把这群糟老头赶出去，然后对旧房屋重新翻新一下，这样就可以吸引更多高级房客，收更高的租金，赚更多的钱。\r 虽然已到迟暮之年，但老人们人老心不老。为了要保住老人院，也就是他们的家，四人决定重操旧业。他们构思了一个表面看似简单，其实奥妙无穷的“保家计划”。在计划实施过程中，没想到还被一个毒品贩缠上，要他们帮忙对付与他有仇的黑帮成员。可惜他们忽视了自己的年纪和身手，事未办成，却闹了不少笑话。',NULL,0,0,2.634119,6.4,11,88,'2000-08-21','en','/kdQOz5enVVz113zZQcuoqh3oACy.jpg',2.380672454976819,3,'2026-09-10',2,NULL,NULL),(19153,'The Real Cancun','The Real Cancun','Sixteen American college students drink, flirt, fight and canoodle during their Spring Break vacation in Cancun, Mexico.',NULL,0,0,0.456485,3.3,8,96,'2003-04-23','en','/wyLs32hfhfShhHPJ8h8VzAash55.jpg',2.3027801538854415,3,'2026-09-10',2,NULL,NULL),(19187,'The Hebrew Hammer','The Hebrew Hammer','A Jewish blaxploitation hero saves Hanukkah from the clutches of Santa Claus\'s evil son.',NULL,1000000,0,1.600797,5.9,18,85,'2003-01-01','en','/HryOo5fCwJ5QUbNqjYAotgoj9c.jpg',2.4752776233350655,3,'2026-09-10',2,NULL,NULL),(19204,'鬼驱人','...E tu vivrai nel terrore! L\'aldilà','導演卢西奥·弗尔兹 Lucio Fulci Lucio Fulci的作品，英文片名是(The Beyond)，劇情敘述 利兹（Catriona MacColl 饰）是一位独立而又乐观的纽约女孩，她来到了路易斯安那州，希望能够在那里建立起自己的事业。很快，利兹就看中了一家十分有格调的老店，可惜已经破败不堪，利兹决定将这里作为自己的起点，开始着手修葺店铺。在此过程中，利兹结识了约翰（大卫·沃贝克 David Warbeck 饰）和艾米丽（琴祺雅·蒙内亚勒 Cinzia Monreale 饰）。艾米丽双目失明，却拥有着极强的第六感，她告诫利兹离开这个不祥之地，但利兹并不相信艾米丽所言。诡异的事情接二连三的发生，越来越多的人因为这间店铺死去，渐渐的，利兹开始意识到，也许她真的触碰到了禁忌的开关，放出了可怕的魔鬼','The seven dreaded gateways to Hell are concealed in seven cursed places… And from the day the gates of Hell are opened, the dead will walk the earth.',0,0,8.022122,6.6,117,87,'1981-04-22','it','/nx0z3PXyclLaQ6FWcqQcwlMhT12.jpg',2.9082827038775005,3,'2026-09-10',2,NULL,NULL),(19255,'Away We Go','Away We Go','Verona and Burt have moved to Colorado to be close to Burt\'s parents but, with Veronica expecting their first child, Burt’s parents decide to move to Belgium, now leaving them in a place they hate and without a support structure in place. They set off on a whirlwind tour of of disparate locations where they have friends or relatives, sampling not only different cities and climates but also different families. Along the way they realize that the journey is less about discovering where they want to live and more about figuring out what type of parents they want to be.',NULL,17000000,14899417,10.13559,6.7,189,98,'2009-06-05','en','/zWxjopWXpnC1vSbnO7mw2URna22.jpg',3.032613490936747,3,'2026-09-10',2,NULL,NULL),(19265,'Whatever Works','Whatever Works','Whatever Works explores the relationship between a crotchety misanthrope, Boris and a naïve, impressionable young runaway from the south, Melody. When Melody\'s uptight parents arrive in New York to rescue her, they are quickly drawn into wildly unexpected romantic entanglements. Everyone discovers that finding love is just a combination of lucky chance and appreciating the value of \"whatever works.\"','A new comedy',15000000,35097815,21.857387,6.8,350,92,'2009-06-19','en','/upIYOZbiutCBnvejGYaZlJxxKcs.jpg',3.223289567885139,3,'2026-09-10',2,NULL,NULL),(19316,'面子','Saving Face','年轻医生Wil（杨雅慧 饰）是个美国华裔。她事业如意，工作干炼，但就是不爱打扮，不喜欢结交男朋友，这令到母亲（陈冲 饰）非常操心。母亲刻意拉女儿到一些华人圈子的聚会，帮女儿物色对象，却总是一无所获。 不料母亲的生活也开始混乱——她怀上了孩子，却不愿公开谁是孩子父亲。为了面子问题，Wil的外公外婆把母亲赶出家门，责令她一定要找个人嫁出去。于是，妈妈投奔到女儿的门下，暂时寄宿在此，女儿开始四处网罗男人相亲。除了母亲的事情让Wil烦恼，她还有一个秘密需要苦心遮掩——自己女同的身份恐怕会让思想传统的母亲接受不了，于是，Wil和女朋友开始转战地下，二人爱得偷偷摸摸。人人为了面子，都有一个自己的心结，不知何时打开。','A romantic comedy about right, wrong and everything in between.',0,0,2.487255,6.8,32,91,'2004-09-12','en','/7XbbgkKi4nEMOu9iwiANXpjKKhe.jpg',2.607398667873399,3,'2026-09-10',2,NULL,NULL),(19344,'恋恋师情','Loving Annabelle','年轻女孩安娜贝尔（Erin Kelly 饰）在相继被两所学校开除后，参议员父亲将她安排到一所天主教寄宿学校继续学业。安娜贝尔很快又拥有了新的校园生活，以及三个性格各异的室友。学校的诗歌老师西蒙娜（戴安娜·加德瑞 Diane Gaidry 饰）则负责管理她们寝室。西蒙娜是一位工作上极其关心学生，私生活也严格遵守宗教和社会道德的女性，然而从不按常规出牌，甚至公然蔑视权威的安娜贝尔着实是最令她头疼的学生。西蒙娜甚至想要放弃，申请将安娜贝尔调到别的寝室去，然而她很快又发现了安娜贝尔身上独特的成熟与感性气息，决定耐心引导。而令人意想不到的是，就在两人朝夕相处的过程中，安娜贝尔竟渐渐爱上了西蒙娜，然而学校森严的天主教义却给这份单纯的情感蒙上荆棘……',NULL,900000,0,7.145832,6.4,55,76,'2006-03-08','en','/a6p1Oexil6Z2XO5d1QVHR3F2OoM.jpg',2.730251712631191,3,'2026-09-10',2,NULL,NULL),(19366,'猫女乐队','Josie and the Pussycats','Josie, Melody and Val are three small-town girl musicians determined to take their rock band out of their garage and straight to the top, while remaining true to their look, style and sound. They get a record deal which brings fame and fortune but soon realize they are pawns of two people who want to control the youth of America. They must clear their names, even if it means losing fame and fortune.','They were three small time girls, with big time dreams. Now, fate is giving the Pussycats, the chance of a lifetime.',22000000,0,6.404571,5.3,72,98,'2001-04-06','en','/mHOix87RdBO3YQuyvFFZAZxpt5P.jpg',2.7581444981465646,3,'2026-09-10',2,NULL,NULL),(19405,'下课后：暑假历险','Recess: School\'s Out','对孩子们最残忍的事情，莫过于剥夺他们的暑假。面对前校长想要消灭夏天，让暑假从此消失的阴谋，德维勒和他的小伙伴们当然要奋力顽抗，捍卫暑假。最早发现这个阴谋端倪的是德维勒。正值炎炎暑假，他在学校里闲逛时发现了一道奇异的绿光。德维勒哀求大人们调查此事，他觉得此事有蹊跷。只有校长愿意相信德维勒的话，前往一探究竟。然而，更奇怪的事情发生了，校长竟然神秘的消失在一道光之中。\r 为了弄清真相，挽救校长，德维勒和他的朋友们开始了冒险的侦探，前校长的阴谋也慢慢浮出水面，暑假行动正式开始！','Saving The World One Playground At A Time',10000000,44460850,5.699058,6.6,67,83,'2001-01-27','en','/qsUCoeTwCNIrvDrUiWlTCgyRFZy.jpg',2.775370686624359,3,'2026-09-10',2,NULL,NULL),(19419,'绑架计划','Screwed','维拉德-菲尔莫是克罗克小姐的司机，平日里受尽了这个恶婆的欺负。为了报复，他与性格卤莽的死党拉斯蒂设计了一个自以为高明的计划。他们绑架了克罗克小姐的爱犬，妄图以此要挟她。谁知小狗却趁其不备逃回了主人家，而克罗克小姐则误以为是维拉德被人绑架。阵脚大乱的维拉德和拉斯蒂为了掩盖自己的行踪，向殡仪馆工人格洛佛求助。可惜事与愿违，格洛佛的加入使得本已糟糕的状况变得更加糟糕，绑架计划变成了一场失去控制的闹剧。',NULL,0,0,5.359381,4.9,23,81,'2000-05-12','en','/m6FfMbH1ga1Kp5QI9Nm0ETOIG64.jpg',2.524995129735381,3,'2026-09-10',2,NULL,NULL),(19457,'家族情仇','The Yards','故事发生在车水马龙的繁华大都市纽约，李奥（马克·沃尔伯格 Mark Wahlberg 饰）终于结束了他的铁窗生涯，刑满释放，回归了社会，他已经不再想去洗清自己身上所蒙受的不白之冤，只想珍惜所剩不多的时间，做一个平凡的人。  李奥来到了叔叔弗兰克（詹姆斯·卡恩 James Caan 饰）所经营的车厂工作，这个李奥的家族世世代代经营的车厂让李奥能够卸下所有的心防，做一个真实的自己。和朋友威利（杰昆·菲尼克斯 Joaquin Phoenix 饰）、艾瑞卡（查理兹·塞隆 Charlize Theron 饰）等人的重逢令李奥觉得自己离理想生活越来越近。然而事与愿违，一个李奥无意之中发现的秘密让他再度成为众矢之的，而这一次，他所要面对的敌人正是他的家人们。','He\'s the target of the most merciless family in New York. His own.',0,0,10.150993,6,97,115,'2000-04-27','en','/AtwXtU8CDWvVADgOwRkOSRZFPWI.jpg',2.8486123701583903,3,'2026-09-10',2,NULL,NULL),(19489,'拦途截爱','Held Up','While they\'re on vacation in the Southwest, Rae finds out her man Michael spent their house money on a classic car, so she dumps him, hitching a ride to Vegas for a flight home. A kid promptly steals Michael\'s car, leaving him at the Zip &amp; Sip, a convenience store. Three bumbling robbers promptly stage a hold up. Two take off with the cash stranding the third, with a mysterious crate, just as the cops arrive. The robber takes the store hostage. As incompetent cops bring in a SWAT team and try a by-the-book rescue, Michael has to keep the robber calm, find out what\'s in the crate, aid the negotiations, and get back to Rae. The Stockholm Syndrome asserts its effect.',NULL,0,0,1.569449,4.9,11,89,'1999-10-08','en','/95AseMukZsjgDXC9NtgVQESAVgY.jpg',2.3715461969580387,3,'2026-09-10',2,NULL,NULL),(19495,'游牧战神','Nomad','电影讲述的是哈萨克斯坦可汗阿不赉成长的历程。影片采用旁述的形式，以恢宏的战争场面对我们娓娓道来：在无边无际的辽阔之地，从阿尔泰山到里海，远古就住着游牧的哈萨克民族，在这片土地上，一波又一波敌人倒下，在他们的身后留下灰烬和骨头，对他们来说最大的灾难。影片在努力定义哈萨克斯坦的民族意识形态，聚焦于如何让18世纪的哈萨克斯坦各部落团结起来一致对抗外来侵略。  　　关于影片：  　　中亚地区一向被认为是电影业的沙漠，中亚国家也有自己的电影业，但限于资金和技术和观念，很难拍出在世界上有影响力的影片。然而，最近一部名为《游牧战神》的影片，不仅创造了中亚电影的投资新纪录，影片场面也气势磅礴，情节感人。这部造价最高的中亚影片反映了一个哈萨克斯坦民族自豪感的主题，称得上是哈萨克的史诗巨片。','Courage know no limit',25000000,0,8.212018,4.3,17,112,'2005-07-17','en','/vLHtz57xpPBrIl9YAhEgC29LCyk.jpg',2.467775209925927,3,'2026-09-10',2,NULL,NULL),(19556,'三月女郎','Miss March','塔克（崔沃•摩尔 Trevor Moore 饰）和贝尔（扎克•克雷格 Zach Cregger 饰）是一对发小儿。一次，塔克在贝尔哥哥的储藏柜里翻到了一本《花花公子》，从此对性着迷，一发而不可收拾。他对着癫痫病女孩吹口哨，从而招致了对方的拳打脚踢。与塔克不同，贝尔是一个羞涩内向的男孩，他对于女生还是发乎情至于礼。但是由于被损友坏名声拖累，贝尔被暗恋的女友三振出局。两个谈性正浓的家伙，在一次舞会上结识了大亨人物埃匹克（克雷格•罗宾逊 Craig Robinson 饰），对方左拥右抱美女的霸道，深深影响了他们。后来，一次偶然的机会，两人坐上了他的豪华房车，但却在美色前纷纷败下阵来……','After four years in a coma, Eugene Pratt is going to be reunited with his high school sweetheart... on pages 95-97.',0,0,9.371534,5.4,77,89,'2009-03-13','en','/rJovsKIjVsSMuwURASoTZJB6jvI.jpg',2.780798291253024,3,'2026-09-10',2,NULL,NULL),(19585,'豚鼠特工队','G-Force','一群受过特别训练的动物突击队员，受到政府委派，前去阻止一个邪恶的亿万富翁控制地球。　　一个秘密政府组织训练动物们去执行间谍行动。当这些经过强化训练的豚鼠们全身武装上最先进的设备之后，它们发现地球的命运掌握在它们手中。“达尔文” （山姆·洛克威尔　配音）是他们的头儿，决定要不惜一切代价取得胜利；Blaster（崔西·摩根　配音）是一个出色的武器专家；由佩内洛普·克鲁兹配音的Juarez是一个性感的武功高手，另外，这个团队还有会飞檐走壁的侦查员Mooch，以及精通电脑技术的专家鼹鼠Speckles（尼古拉斯·凯奇配音）。','The world needs bigger heroes',150000000,292817841,26.710398,5.1,510,88,'2009-07-21','en','/pbn09AYm70U6PTsgPrfz88JgLmT.jpg',3.1239035292180146,3,'2026-09-10',2,NULL,NULL),(19615,'Flying By','Flying By','一位房地产商人参加他的高中25周年聚会，他没有带着妻子，而是独自前往。聚会上，大家青时代组建的乐队正在表演，同学们把他请上舞台一起唱了几首歌曲。回家后，他的家人表现出不同的态度，妻子很生气，女儿觉得爸爸很酷，退休在家的母亲鼓励他享受生活。而他自身感到很放松，暂时的摆脱了生意以及婚姻的压力。他的乐队在酒吧演出，甚至有机会举办巡回演出。但乐队的内部存在矛盾。总之，乐队，生意，还有家人，让他将面临艰难的选择。','It\'s about the music',0,0,1.546169,7,2,95,'2009-01-01','en','/xLMv1cpLK3qrvF0ehNEkowWXaFB.jpg',2.076603700515904,3,'2026-09-10',2,NULL,NULL),(19644,'实尾岛','실미도','60年代末朝鲜半岛南北局势紧张，双方都展开了疯狂的间谍与刺杀行动。1968年1月，康仁灿（薛景求饰）因谋杀罪名成立而被判死刑的，在行刑前突然被召到拘留室，与特种部队军官讨论替代死刑的条件，他将被送到西南部荒岛实尾岛接受特别军事训练。同时，另外30名死囚也接受了特种部队军官的条件，被征召到实尾岛执行特别任务。\r 　　这31名死囚乘坐渔船到达实尾岛后，便在上级崔在贤中尉（安圣基饰）宣布下，组成了以刺杀朝鲜元首金日成为目标的“684北派部队”，并随即接受一连串地狱式的体能和军事训练。\r 　　可是在三年后，由于韩国政府国策的改变，“684北派部队”的计划被取消，31名队员则前途未卜。他们纷感被国家出卖，只能设法自救……',NULL,8000000,0,2.60632,6.6,28,135,'2003-12-24','ko',NULL,2.5763471180662103,3,'2026-09-10',2,NULL,NULL),(19724,'幻想之地','Imagine That','埃文（艾迪·墨菲 Eddie Murphy 饰）是公司的财务总监，在职场上叱咤风云的他在家庭中却屡遭挫折。由于常年来对家庭的忽视，忍无可忍的妻子洛瑞（瓦妮萨·威廉姆斯 Vanessa Williams 饰）选择了离开，埃文反复承诺会每天分出时间来照顾家庭，这才保住了女儿奥利瓦（雅拉·莎希迪 Yara Shahidi 饰）的抚养权。然而，随着时间的流逝，承诺的力量越来越弱，当埃文在家里也开始摆弄他的手机时，奥利瓦隐隐明白旧事将要重演。  　　原来，埃文最近的工作很不顺利，即使努力如他，也无法阻止公司节节下滑的盈利，与此同时，奥利瓦的捣乱也让埃文一个头两个大。偶然之中，奥利瓦打开了一扇神奇的门扉，在门后面的，是一个充满了神奇魔力的宁静世界，在这个世界中，埃文洗刷了生活和工作中积累的压力，也明白了什么是生命里最终要的东西。','What if your daughter\'s imagination... Was the secret to your success?',55000000,0,12.340384,5.7,134,107,'2009-06-19','en','/lyCTP5C3raH46hJNS9WfBSnWHsG.jpg',2.9079044640832796,3,'2026-09-10',2,NULL,NULL),(19803,'大学新生','Underclassman','特雷西斯（尼克·卡农 Nick Cannon 饰）成为警探已经四年了，尽管他聪明伶俐办事可靠，但这么长时间过去，特雷西斯依然没有得到同僚们和老板的赏识，原因只有一个，那就是他长着的那张超级无敌可爱娃娃脸。一起由特雷西斯负责的恶性案件中，线索指向了一所贵族学校，想要追踪这些线索，唯一的方法就是在校园内安插卧底，毫无疑问，特雷西斯是成为卧底的最佳人选。就这样，特雷西斯重新回到了高中校园，没想到，此次他要面临的，是前所未有的挑战。繁重的功课，复杂的校园人际关系，扑朔迷离的案件，这一切都让特雷西斯感到力不从心，好在有漂亮性感的女老师为他撑腰，特雷西斯才得以度过难关，也就是在这一过程中，案件的真相逐渐浮出了水面。',NULL,0,0,2.083856,5.5,28,95,'2005-09-02','en','/kOpQ5doAbDaxKyGq91PugsCTOYO.jpg',2.5629384391879806,3,'2026-09-10',2,NULL,NULL),(19840,'校花我爱你','I Love You, Beth Cooper','布法罗格林高中迎来一年一度的毕业典礼，呆板木讷的男孩丹尼斯·库夫曼（保罗·鲁斯特 Paul Rust 饰）作为学生代表上台发表讲话。令所有人都大吃一惊的是，这个毫不起眼的家伙竟然在大庭广众之下向校花——啦啦队长贝丝·库珀（海顿·潘妮蒂尔 Hayden Panettiere 饰）说出“我爱你”三个字。对丹尼斯来说，这不过是了却了自己的一桩心愿，剩下的事就是和好哥们里奇（杰克·卡朋特 Jack Carpenter 饰）快乐地度过毕业晚会。不过当晚贝丝竟带着两位姐妹淘来到丹尼斯的身边。当然，尾随前来的还有贝丝气急败坏的男朋友。一番混乱之后，丹尼斯和贝丝等五个人冲了出来。开始了难忘而美好的夜晚……','Popularity is nice. Popular girls are not.',18000000,0,14.15192,5.1,197,102,'2009-07-10','en','/mUi6nEbo04DR1YwflbZX1RR7UwS.jpg',2.94977340079504,3,'2026-09-10',2,NULL,NULL),(19844,'亲吻新郎','Kiss the Bride','马特（菲利浦·卡纳 Philipp Karner 饰）和瑞恩（詹姆斯·奥谢 James O\'Shea 饰）之间的关系可不仅仅是高中好友那么简单，他们的感情早已经超越了友情，甚至有过一段露水情缘。不幸的是，这段感情并没能持续多久，最终马特选择了离开，杳无音信。',NULL,0,0,1.65426,4.2,11,100,'2007-01-01','en','/m1ycnhkFufW4NDFG38QaHtAWqDN.jpg',2.3686158955973933,3,'2026-09-10',2,NULL,NULL),(19848,'The Players Club','The Players Club','Young single mother Diana struggles to provide for her child and pay for her college education. She ends up working at a shoe store, but meets two strippers from at a nearby gentlemen\'s club who convince her there\'s fast money to be made stripping. At the Players Club, however, Diana faces danger and heartbreak.','Here, we get down and dirty.',0,0,5.769822,6.4,14,104,'1998-04-08','en','/8Y0ipbrZ6oiXffZkI1D9eahVsZ1.jpg',2.4366332281415106,3,'2026-09-10',2,NULL,NULL),(19898,'Pandorum','Pandorum','Two crew members wake up on an abandoned spacecraft with no idea who they are, how long they\'ve been asleep, or what their mission is. The two soon discover they\'re actually not alone – and the reality of their situation is more horrifying than they could have imagined.','Don\'t fear the end of the world. Fear what happens next.',33000000,20645327,28.353517,6.5,774,108,'2009-09-08','en','/gm7alBhdKP0nJXkwiDy1qEKhlB6.jpg',3.4030695315301402,3,'2026-09-10',2,NULL,NULL),(19899,'伴侣度假村','Couples Retreat','婚前热情如火的情侣们，婚后却未必如此。当柴米油盐取代了浓情蜜意，生活的裂缝就渐渐暴露出来：杰森（杰森·贝特曼 Jason Bateman 饰）与妻子辛西娅（克里斯汀·贝尔 Kristen Bell 饰）因为不孕症考虑离婚，乔伊（乔恩·费儒 Jon Favreau 饰）和露西也已经对对方身体没有兴趣，戴夫（文斯·沃恩 Vince Vaughn 饰）和萝尼则整日被房子和孩子的压力弄得心烦意乱。眼看曾经令人艳羡的婚姻就要面临崩溃，杰森夫妇决定最后一搏，他们费尽心力想出一个度假疗法，说服几对欢喜冤家们前往一个热带小岛二度蜜月。异国的碧海蓝天似乎让这些中年夫妇又重拾热情，但度假村老板马塞尔（让·雷诺 Jean Reno 饰）提供的硬性课程又让他们摸不着头脑：雷人不浅的猛男瑜伽、夫妻按摩、与鲨同游真的能唤醒这些夫妻的情感，拯救他们的婚姻么？','It may be paradise... but it\'s no vacation.',70000000,171844840,26.676487,5.3,588,113,'2009-09-19','en','/9DMOa6YwmrSZ6GmvmV5TwY6K8HO.jpg',3.170885944247615,3,'2026-09-10',2,NULL,NULL),(19901,'嗜血破晓','Daybreakers','2019年，一场神秘的鼠疫在全球各地爆发，人类几近灭绝，活下来的，绝大部分变成了嗜血为生的吸血鬼，剩下人口少得可怜的人类，四处躲避吸血鬼与瘟疫的侵蚀，而吸血鬼则堂而皇之的成为了文明的主宰，国家的政府高层、军队、知识分子……都已经是长着獠牙的吸血鬼。随着正常人类的日益减少，吸血鬼开始不得不面对一个严峻的问题，以人类的鲜血作为唯一养料来源的吸血鬼，必须把人类像珍稀动物一样保护起来，否则吸血鬼也将随人类一起灭亡。爱德华·多尔顿（伊桑·霍克饰）是一名高级研究员，他在一家大型企业里工作，老板则是地球上富可敌国的吸血鬼查尔斯·布罗姆利（山姆·尼尔饰），布罗姆利希望能够找到替代血液的供给品，摆脱目前的吸血鬼族群所面临的困境，同时给自己带来丰厚的利润，而爱德华也有着自己的信念，当他遇上奥德丽·班尼特（克劳蒂娅·卡万饰）之后，在她身上，研究取得了突破性的进展；而人类方面，一个神秘的退伍军人艾维斯（威廉·达福饰）也有着一个特殊的使命需要爱德华完成。周旋在人类、吸血鬼与瘟疫当中的爱德华，发现自己被数个阴谋所笼罩，每走一步都艰险万分……','In 2019, The Most Precious Natural Resource... Is Us.',20000000,51416464,28.019226,6,634,98,'2009-01-06','en','/kvylYUP77ru7k98HMeL4GNn7OEO.jpg',3.2834502138199193,3,'2026-09-10',2,NULL,NULL),(19904,'继父','The Stepfather','在名叫波特兰的小镇，单身母亲苏珊·哈丁（雪拉·渥德 Sela Ward 饰）和一双儿女肖恩（Braeden Lemasters 饰）、贝丝（Skyler Samuels 饰）共同生活在一起，其长子迈克尔（佩恩·拜德格雷 Penn Badgley 饰）则在外地的军校求学。某日，苏珊在超市遇见了名叫大卫·哈里斯（迪伦·沃尔什 Dylan Walsh 饰）的单身男子。大卫举止得当、言语风趣，俨然一个完美的居家好男人。两人相见恨晚，只有半年便到了谈婚论家的地步。哈丁一家对大卫颇为满意，独有迈克尔似乎心存顾忌。  　　他的顾忌不是没有道理。经过一段时间相处，迈克尔发现大卫温柔开朗的外表背后似乎隐藏着黑暗恐怖的一面，他试着调查大卫的一切，然而这也许为时已晚……','Daddy\'s home.',0,0,7.924428,5.4,167,101,'2009-10-16','en','/3iIv0nmukg7Xlg2XSu6ycfZiscA.jpg',2.9246670307444482,3,'2026-09-10',2,NULL,NULL),(19905,'The Goods: Live Hard, Sell Hard','The Goods: Live Hard, Sell Hard','Who is Don Ready? Salesman? Lover? Song Stylist? Semi-professional dolphin trainer? Ready is all of the above - except for a dolphin trainer. When he’s asked to help save an ailing local car dealership from bankruptcy, Ready and his ragtag crew descend on the town of Temecula like a pack of coyotes on a basket full of burgers.',NULL,10000000,0,3.352702,5.4,58,90,'2009-08-14','en','/1nEd4aLuRlAPFqUdcCYekAAjWsn.jpg',2.711099964835301,3,'2026-09-10',2,NULL,NULL),(19908,'丧尸乐园','Zombieland','未来某天，灾难降临世间，天灾人祸让地球濒临毁灭。更为可怕的是，恐怖病毒肆意蔓延，人类相继化身为丧失人性、嗜血如命的恐怖僵尸。并且随着时光的流逝，僵尸的智商不断提升，已经成为规模庞大的恐怖大军。经过几个月的厮杀，居住在得州某小镇的哥伦布（杰斯·艾森伯格 Jesse Eisenberg 饰）是少数的幸存者之一，他唯唯诺诺，行事谨慎，却凭着总结出来的经验一次又一次逃出生天。某天，哥伦布遇见作风骠悍的塔拉哈西（伍迪·哈里森 Woody Harrelson 饰），两人一路同行，继而邂逅性感美艳的姐妹花薇奇塔（艾玛·斯通 Emma Stone 饰）和小石头（阿比盖尔·布莱斯林 Abigail Breslin 饰），他们由此开始了一段妙趣横生、惊险刺激的旅程……本片荣获2009年Sitges – Catalonian国际电影节观众奖。','This place is so dead',23600000,102391382,57.300674,7.2,3550,88,'2009-10-07','en','/dUkAmAyPVqubSBNRjRqCgHggZcK.jpg',4.010520697623476,3,'2026-09-10',2,NULL,NULL),(19912,'死神来了4','The Final Destination','因为之前有所预感，尼克和他的朋友们借此在一场车祸中死里逃生，然而死神并未善罢甘休，继续制造种种事故，势必要将他们赶尽杀绝。','Rest In Pieces',40000000,186167139,32.478077,5.4,831,82,'2009-08-26','en','/tH6uOM8gYpi72FVEp6cr83TqKWE.jpg',3.2541085375414163,3,'2026-09-10',2,NULL,NULL),(19913,'和莎莫的500天','(500) Days of Summer','来自新泽西的汤姆是一个沉溺于英伦哀歌与《毕业生》情境的年轻人，他供职于一家贺卡公司，任务是撰写富有创意的祝辞。某次会议上，汤姆的老板把新助理介绍给大家，她是来自密歇根的魅力女孩莎莫。莎莫自幼父母离异，因此对于感情的态度与众不同。汤姆和莎莫没有一见钟情，但却在一次酒吧K歌后彼此示好，成了非典型的恋人。而且这段办公室恋情迅速升温，爱火烧得谁都无法预料。最后，在一个餐馆里，莎莫对汤姆说了绝情的分手。深陷情网的汤姆，经受不住失恋的打击，郁郁寡欢，却又不得不接受莎莫已经离去的事实。这使他开始反思自己是否是一个称职的男朋友，究竟都做错了什么？汤姆开始回想和莎莫在一起的500个日日夜夜，希望从中找到答案…','It was almost like falling in love.',7500000,60722734,45.610993,7.2,2904,95,'2009-07-17','en','/qXAuQ9hF30sQRsXf40OfRVl0MJZ.jpg',3.9303394170268446,3,'2026-09-10',2,NULL,NULL),(19933,'电器小英雄','The Brave Little Toaster','A group of dated appliances find themselves stranded in a summer home that their family had just sold decide to, a la The Incredible Journey, seek their young 8 year old \"master\". Children\'s film which on the surface is a frivolous fantasy, but with a dark subtext of abandonment, obsolescence, and loneliness.','Imagine if Your Toaster Went on a Journey of its Own!',2000000,0,6.86302,6.7,93,90,'1987-07-09','en','/mEZcPMNRqTcotOZSttN5MtmJbu1.jpg',2.8559736551036194,3,'2026-09-10',2,NULL,NULL),(19959,'未来战警','Surrogates','故事发生在并不遥远的未来，人类生活在互相隔绝的世界里，各自躲在家中，彼此之间保持联系的方式就是通过使用代理机器人。布鲁斯·威利斯所饰演的警察，被派去调查一宗代理机器人被杀案，因此他被迫冒险从家里出来，去追踪案件的蛛丝马迹。　　未来社会，科技的进步日新月异，尤其是网络的发展更是进化到了今时今日的人类无法想像的地步，这一切都是因为坎特博士（詹姆斯·克伦威尔饰）发明了机器代理人这样一种高科技产物。大家根本不需要自己亲自出门，只需要将大脑接入网络，就可以通过由思维来控制的机器代理人在替自己做一切想做的事情。这些机器代理人的外表可以根据客户的要求定制，可以是一位迷人的金发美女，也可以是一位体格壮硕的硬朗汉子。有了机器代理人的社会，一切都化繁为简，生活看上去变得更加完美。　　只是，在这看似完美的生活下面，总会有一些不那么美好的事情发生。零犯罪率保持了许多年的社会里，突然发生了一起谋杀案，彻底将这个人人向往的乌托邦社会击碎。格里尔（布鲁斯·威利斯饰）是一位经验老到的FBI探员，他和搭档彼得斯（拉妲·米契尔饰）奉命调查这起谋杀案件，随着两人对案件的抽丝剥茧，他们逐渐走进了事件的核心。原来机器代理人并非完美社会的解决方案，它的诞生其实是源于一个巨大的阴谋。而讽刺的事，格里尔调查这起案件时一直使用着机器代理人。为了真正找出真相，格里尔放弃了使用机器代理人而亲自出门调查这起案件，他却突然发现，这个曾经如此熟悉的社会看起来却冰冷陌生，而且危机四伏……','How do you save humanity when the only thing that\'s real is you?',80000000,122444772,36.664991,5.9,1195,89,'2009-09-24','en','/6BF3LgpNDJu4B6R9f9TDq6QcvSS.jpg',3.4167709386998104,3,'2026-09-10',2,NULL,NULL),(19994,'詹妮弗的肉体','Jennifer\'s Body','妮蒂（阿曼达•塞弗里德 Amanda Seyfried 饰）和詹妮弗（梅根•福克斯 Megan Fox 饰）是从小一起长大的好朋友，妮蒂其貌不扬，对朋友马首是瞻；詹妮弗是学校啦啦队队长，风光无限，追求者众，她们共同生活在偏僻的魔鬼壶小镇。某晚，一支名为Low Shoulder的摇滚乐队来到小镇唯一一间酒吧Melody Lane演出，詹妮弗拉着好友一同前往。演出伊始，酒吧即发生严重火灾。妮蒂侥幸逃生，却眼睁睁看着已经吓傻的詹妮弗被乐队成员拉进汽车，绝尘而去。\r 　　当晚，浑身是血的詹妮弗出现在妮蒂的家中，从这天起她的脾气变得张扬怪异。她开始诱惑校内的男生，并将他们杀害、吃掉。小镇人民尚未从大火的悲剧中解脱出来，又被接二连三的凶杀案给击倒。倍感疑惑的妮蒂慢慢知道了大火之夜发生在詹妮弗身上的一切……','She\'s evil... and not just high school evil.',16000000,31556061,32.257414,5.3,837,100,'2009-09-18','en','/qY8V9yyRHYe3PiL7RQ5mWij0efG.jpg',3.2387417819577538,3,'2026-09-10',2,NULL,NULL),(19995,'阿凡达','Avatar','战斗中负伤导致下肢瘫痪的前海军陆战队员杰克·萨利，在双胞胎哥哥意外去世后，代替他前往潘多拉星参与“阿凡达计划”，操纵由人类与纳威人基因培育出的“阿凡达”躯体。RDA希望借助杰克深入纳威人部落，说服他们离开世代居住的家园，以便开采当地地下极其珍贵的矿物。在探索潘多拉星的过程中，杰克遇到了纳威人奈蒂莉，并在她的引导下学习当地的生存方式以及对自然的信仰。随着他逐渐融入纳威人的生活，杰克开始重新审视自己的任务；与此同时，迈尔斯·夸里奇上校等人对谈判逐渐失去耐心，准备以武力解决阻碍……','Enter the World of Pandora.',237000000,2787965087,150.437577,7.2,11800,162,'2009-12-10','en','/gKY6q7SjCkAU6FqvqWybDYgUKIF.jpg',4.520621428108184,3,'2026-09-10',2,NULL,NULL),(19997,'飞瀑怒潮','Niagara','剧情描述一名红杏出墙的太太与情夫合谋，在大瀑布旅行时谋杀亲夫，不料事机不密，丈夫反过来先发制人对付妻子。约瑟夫·考登与琼·彼得斯饰演各怀鬼胎的夫妻，而身材性感的玛丽莲·梦露则首次在本片中饰演重要配角，没想到她的挑逗魅力与大瀑布的冲击力反而吸引了大部分观众的目光。','A raging torrent of emotion that even nature can\'t control!',1250000,8500000,9.903992,6.7,79,92,'1953-01-21','en','/wb9OBAiO3aUpY4UBkE07KscXSkA.jpg',2.8251913977426337,3,'2026-09-10',2,NULL,NULL),(20009,'懒虫陷情记','Slackers','戴夫、萨姆和杰夫三个是好兄弟，他们整天在一起上课，一起玩，度过了美好的大学时光。转眼间，他们即将从霍顿大学毕业。但由于他们这几年间只顾着享乐而忽略了学业，他们目前处在挂科的边缘中...这也将意味着他们无法毕业拿到毕业证书，于是他们想通过撒谎、欺骗和诡计而获得毕业荣誉证书。但这次他们的诡计却不巧被伊桑发现，不幸被伊桑抓住了把柄。平日里，他们一直认为伊桑是一个怪胎，从来不跟他一起玩耍，而伊桑也没有什么朋友，校园里更没有女孩喜欢他。当伊桑发现了戴夫他们三人的小秘密后，他决定以此威胁戴夫三兄弟来完成他想做的事情。而被揪住小辫子的戴夫三兄弟只好乖乖听从伊桑的话，原来伊桑一直对学校里最后欢迎的女神有好感，而这次正好可以利用戴夫三兄弟去接近女神，并创造机会赢取女神的新。一系列乌龙事件之后，四个人也成为了好朋友，戴夫他们也明白了舞弊的错误性，还是靠自己努力复习通过了考试，拿回了真正属于自己的荣誉。','When all else fails... cheat.',14000000,6413915,9.371811,5.4,60,86,'2002-02-01','en','/g3xn7tRnGxVwwKc2tge7nPssywQ.jpg',2.7315854022835593,3,'2026-09-10',2,NULL,NULL),(20024,'爱到尽头','The End of the Affair','1946年一个雨夜，小说家莫里斯·本德里克斯（拉尔夫·费恩斯Ralph Fiennes 饰）邂逅身为外交官的故友亨利·梅尔斯（斯蒂芬·瑞 Stephen Rea 饰）。从亨利口中，莫里斯得知对方的妻子莎拉（朱丽安·摩尔 Julianne Moore 饰）似乎正有一段外遇 ，这令他妒火中烧。原来，两年前莫里斯曾和莎拉暗通款曲，两人经常背着亨利共享鱼水之欢。但在一次大轰炸过后，莎拉却从床底上绝然离去。始终耿耿于怀的莫里斯接受了亨利的请求，帮助好友调查莎拉的行踪，然而结果却令他唏嘘不已，感慨良多……  　　本片根据格雷厄姆·格林（Graham Greene）1951年的神秘浪漫主义的自传体小说改编，并荣获2000年英国电影和电视艺术学院奖最佳剧本奖。 ©豆瓣',NULL,23000000,10827816,6.921263,6.6,55,102,'1999-12-03','en','/xTp5cyp6qG0YTdI4AEz4ytjODOQ.jpg',2.7339509969643134,3,'2026-09-10',2,NULL,NULL),(20055,'俘虏','The Betrayed','《恐怖游轮》女主梅丽莎·乔治主演。电影讲述了在自家餐厅给老公当财务的女主杰米·泰勒在遭遇车祸后发现自己被关押在一个废弃仓库里，一个蒙面男子告诉她，老公凯文从一个犯罪集团那偷走了4000万美金。她被迫不断听自己家庭私人谈话的窃听录音，从中找出赃款可能藏匿的地点，否则她6岁的儿子迈克尔将会被杀害。为了拯救儿子，她必须与时间赛跑..','What she doesn\'t know could kill her.',3500000,0,1.348114,5.2,10,98,'2008-09-27','en','/ypozb9oWIDZZIwDQZo0s7JgMa6K.jpg',2.353850459307815,3,'2026-09-10',2,NULL,NULL),(20065,'紫罗兰','Purple Violets','帕蒂（塞尔玛·布莱尔 Selma Blair 饰）在写作上的天赋曾让许多人认为她将来一定能够成为著名作家，她自己也将此当做了理想，然而，现实是残酷的，进入社会之后，工作、结婚，忙于经营职业和婚姻令帕蒂再也无心，也没有时间将功夫花在写作上了，就这样，随着时间的推移，她渐渐将这一理想淡忘了。','A second chance for a first love.',4000000,0,0.936232,5.7,9,103,'2007-04-30','en','/n61vWKkNn1cq8p6a0foAqgrcAwu.jpg',2.334410216124698,3,'2026-09-10',2,NULL,NULL),(20083,'新宿事件','新宿事件','20世纪90年代初，东北青年铁头（成龙 饰）为寻找失联的初恋秀秀（徐静蕾 饰），铤而走险偷渡至日本。在东京新宿，他投靠同乡阿杰（吴彦祖 饰），与其他偷渡客一起在底层挣扎，从事危险肮脏的黑工维生。  铁头最终发现，秀秀已改名为“结子”，并嫁给了日本黑帮“三和会”的副会长江口利成（加藤雅也 饰）。梦碎后的铁头，为带领同伴生存下去，开始在新宿从事不法勾当。期间，他与一家酒吧的老板娘丽丽（范冰冰 饰）相识。丽丽的坚强与温柔，逐渐成为铁头在异乡漂泊中重要的情感慰藉，两人相知相伴，度过了数年时光。  为替被残害的阿杰报仇，铁头卷入黑帮火并，并意外救下江口。由此，铁头与江口达成交易：他替江口铲除异己，助其登上会长宝座；作为回报，他和同伴们获得合法身份与地盘，迅速崛起。然而，权力与利益侵蚀了初心。铁头意欲转行正道，但他的兄弟们却在阿杰的带领下，在犯罪道路上越走越远，引发警方全面关注。  铁头决心终结这一切。他忍痛与深爱的丽丽分别，并跟随唯一相信他的刑警北野（竹中直人 饰）回去劝说兄弟、指证江口，却同时引爆了日本黑帮对华人势力的全面清洗。在新宿的腥风血雨中，兄弟反目，帮派火并，铁头失去了所有挚友。最终，身负重伤、失去一切的他，在追兵与警察的围堵下，带着对丽丽与过往的回忆，做出了最后的抉择。','They destroyed his life... Now he\'ll destroy them all.',15000000,0,5.294319,6.7,65,119,'2009-03-22','zh','/5Qq0Ku9gutF0C16BeIUZXMqxL98.jpg',2.7700838514605954,3,'2026-09-10',2,NULL,NULL),(20156,'色情酒店','Exotica','托马斯是一个有同性恋倾向的宠物店老板，他从国外偷带违禁动物并逃税。他的这些活动被税务稽核员弗朗西斯发现，而弗朗西斯是一位沉浸在恶梦般的回忆中无法自拔的中年人。他的妻子与他的弟弟有染，车祸中，妻死弟伤，而他唯一的女儿又惨遭杀害。他经常光顾色情酒店，因为那里有一位叫克里斯蒂娜的舞女，年貌与他死去的女儿相当。他深情注视的目光使得节目主持人埃里克心中不悦，他先诱导弗朗西斯违犯酒店规定，触摸了克里斯蒂娜的身体，然后将他痛揍一顿赶出酒店。弗朗西斯以不告发托马斯逃税为条件，让他去酒店引埃里克出来，他则携带枪等在酒店门外……','In a world of temptation, obsession is the deadliest desire.',0,0,5.446832,6.5,64,103,'1994-09-24','en','/pWcJdcIHjL3P6NaEJKeV6ONfAMV.jpg',2.7620669216472087,3,'2026-09-10',2,NULL,NULL),(20178,'World\'s Greatest Dad','World\'s Greatest Dad','Robin Williams stars as Lance Clayton, a man who has learned to settle. He dreamed of being a rich and famous writer, but has only managed to make it as a high school poetry teacher. His only son Kyle (Daryl Sabara) is an insufferable jackass who won’t give his father the time of day. He is dating Claire (Alexie Gilmore), the school’s adorable art teacher, but she doesn’t want to get serious --','Lance Clayton is about to get everything he deserves.',10000000,295750,9.805551,6.5,177,99,'2009-08-20','en','/1ESsZLvZPIvbCPCh7CPCSnF4EeH.jpg',3.0041092442894133,3,'2026-09-10',2,NULL,NULL),(20296,'Chocolate: Deep Dark Secrets','Chocolate: Deep Dark Secrets','Christmas Eve, London. While the snow-clad city gets ready to celebrate the festival of peace and joy, a series of bizarre incidents shatter the Christmas calm. A couple of luckless Indians find themselves hauled by the London police and made scapegoats. Or are they?Chocolate unfolds a web of sinister plots, slowly unearthing true and mystifying personalities of seven individuals. Seven high-strung, distinctive people who\'ve chosen to remain in the foreign land hoping to make or break their lives.',NULL,0,0,0.887821,3.4,6,200,'2005-09-16','en','/dAGpuhiI3kbvc5SAmuf839iaUIe.jpg',2.251711089294663,3,'2026-09-10',2,NULL,NULL),(20309,'芭乐鸳鸯','Say It Isn\'t So','Boy meets girl; boy falls in love (and had wild, non-stop sex) with girl; boy loses girl... when they discover they are brother and sister! But when he learns that he\'s the victim of the ultimate case of mistaken identity, the lovesick young man -- whom everyone still thinks is after some taboo thrills -- must race across the country to stop her from marrying another man.',NULL,25000000,0,2.909346,4.8,47,95,'2001-03-12','en','/gHEI41EWj9dEscfEiKgw6a2uUez.jpg',2.657180780873933,3,'2026-09-10',2,NULL,NULL),(20322,'The Brothers','The Brothers','This is the story of four African-American \"yuppies\" (a banker, a doctor, a lawyer, and a \"playboy\") who call themselves \"The Brothers\". When the playboy gets engaged, the other three friends find themselves having to come to terms with their own issues of commitment and honesty...',NULL,0,0,3.029944,6.5,10,106,'2001-03-23','en','/342I0mOBCNTzx4ls4GvIagfzu2m.jpg',2.3629735628485204,3,'2026-09-10',2,NULL,NULL),(20337,'Martin Lawrence Live: Runteldat','Martin Lawrence Live: Runteldat','The controversial bad-boy of comedy delivers a piercing look at his life, lifting the metaphorical smokescreen that he feels has clouded the public view, commenting on everything from the dangers of smoking to the trials of relationships, and unleashing a nonstop litany of raucous anecdotes, stinging social commentary and very personal reflections about life.',NULL,3000000,19184015,0.295226,5,1,113,'2002-08-01','en','/fRpS1sr1GFPgQobsXoNm5lxatcy.jpg',1.9845141442258458,3,'2026-09-10',2,NULL,NULL),(20352,'神偷奶爸','Despicable Me','超级坏蛋格鲁 在听说埃及金字塔被盗的新闻后不满市面上新贼辈出，决定在纳法利欧博士 的帮助下建造火箭升空盗取月亮。在向坏蛋银行贷款的过程中，格鲁盗取的收缩射线枪被新贼维克托 抢走。为了夺回收缩射线枪，格鲁决定领养三位孤儿——玛戈、伊迪丝 和阿格蕾丝，利用她们进入维克托的城堡兜售饼干的机会实施偷盗，计划成功后再偷偷处理掉三个小孩。然而在平凡的日常相处中，格鲁却发现自己越来越离不开这三个小鬼，但这样的感情用事却将严重影响周密的盗月计划……','Superbad. Superdad.',69000000,543513985,113.858273,7.1,6478,95,'2010-07-08','en','/b1BT309QWjtFUlJPLmXmrcHOWEL.jpg',4.265886833727661,3,'2026-09-10',2,NULL,NULL),(20360,'你好呀！亲爱的伦敦','Namastey London','Jazz（卡特莉娜•卡芙 Katrina Kaif 饰）是个从小生活在伦敦的印度女孩，生活的各个方面都浸染在英式的熏陶下，甚至把自己原来的名字Jasmeet改为Jazz。新潮时尚的女孩和她父亲观念上的矛盾让他们争吵不断，父女战争的升级终于让她父亲带她回了印度，开始接受各种相 亲。父亲决定让她嫁给乡下的男孩Arjun （阿克谢•库玛尔 Akshay Kumar 饰），Jazz觉得自己和这个不会说英语的传统印度男人没有任何的话题，然而形势所迫，在朋友Imran的建议下她假意和Arjun举行了印度的结婚仪式得以回到伦敦。回到伦敦的Jazz告诉父母和Arjun这个婚姻在英国不具有合法性，然后答应了男友Charlie（克莱夫•斯坦登 Clive Standen 饰）的求婚。Arjun对Charlie一行人的印度偏见的据理力争让Jazz对他有所改观，朝夕相处让她甚至觉得渐渐爱上了这个印度男人。',NULL,0,0,1.840511,6.6,29,128,'2007-03-27','en','/dO0F66lM1jehIH5bsooKSbdz7xG.jpg',2.582145386598632,3,'2026-09-10',2,NULL,NULL),(20391,'漆好你的马车','Paint Your Wagon','西部淘金热期间，一个无名城因淘金者的聚集而兴起。酒徒买下商人的爱妾在当地结婚，但她后来又与酒徒的好友日久生情，脚踩两只船。最后，整个无名城因地底挖沙掏空而整个陷落。','Stake Your Claim To The Musical Goldmine of \'69!',20000000,31678778,7.902536,6.2,63,158,'1969-10-15','en','/fwnYGuba3ZSM2bXwBZZs4DqqKTl.jpg',2.7570103127060213,3,'2026-09-10',2,NULL,NULL),(20406,'Rockaway','Rockaway','Trane is a decorated war hero just shipped home to the States from Afghanistan after the brutal murder of his wife and child back in Rockaway, Queens. Upon his return, Trane encounters his old friend Dave, who describes the new forces of crime and prostitution that have moved into their neighborhood and caused the destruction of his family.',NULL,0,0,0.361554,5.8,2,76,'2007-07-07','en','/9VlOskJuRF0rCqFzoZnfsBf4PC2.jpg',2.0729120865131447,3,'2026-09-10',2,NULL,NULL),(20455,'数码宝贝：剧场版','Digimon: The Movie','第一个故事集中在 Tai 和 Kari Kamiya 在他们在数字世界冒险的四年前。它展示了他们与 Digimon 的第一次接触以及发生在他们身上的事情(还有其他孩子)。一天早上，泰和卡莉醒来，发现前一天晚上他们的电脑里出现了一个电子蛋，这个蛋很快就孵化出来，露出了一个波塔蒙。然后，Digimon 演变成了 Koromon，然后是 Agumon (不是在系列中和 Tai 成为朋友的那个，然而，不知怎么的，Koromon 和 Kari 都记得对方) ，然后他走出去，无意中破坏了一大片社区，Kari 骑在他的背上。第二个数字蛋出现在天空中，显示出一个邪恶的数字，帕罗蒙。阿古蒙随后转投 Greymon，但是他的实力不足以击败帕罗特蒙，因此被淘汰出局。泰抓住卡莉的哨子，唤醒了格雷蒙，格雷蒙打败了帕罗蒙，和他一起消失了。',NULL,5500000,0,3.7387,6.2,72,82,'2000-03-17','en','/tiH1muonzAWzlLjPhjAcAYVAjzm.jpg',2.776342058507425,3,'2026-09-10',2,NULL,NULL),(20468,'The Big Tease','The Big Tease','Thinking he\'s competing in Los Angeles\' hot Platinum Scissors contest, Scottish hairstylist Crawford (Craig Ferguson) leaves Glasgow with a film crew to capture the event. When he learns he\'s a mere audience member, Crawford must find a way to become the mane event. Abhorrent Norwegian Stig is his stiff-as-gel competition. Drew Carey and others make cameo appearances in this hysterical mockumentar','He saw. He combed. He conquered.',0,0,0.502396,5.8,6,87,'1999-01-01','en','/i7HjSujyV4PpIcTzhlNxNGvMiRJ.jpg',2.256712812387677,3,'2026-09-10',2,NULL,NULL),(20483,'小鬼神偷','Catch That Kid','他们是各自领域里的专家：一个是攀岩高手、一个是电脑天才，还有一个机械狂人。他们的任务是：抢劫世界上防卫最严密的银行！\r 你或许会以为这肯定是哪个犯罪团伙又出动了吧？错。他们的目的只不过是为了挽救一个濒临死亡的父亲，而且他们三个都还没到能领驾驶执照的岁数，怀揣热情和充沛的精力，三个少年誓要要完成这次未经许可的使命！\r 12岁的梅蒂和她的父亲是乐此不疲的攀岩爱好者。但一次意外彻底改变了他们的生活，在一次攀岩中梅蒂的父亲不幸受伤，进而导致全身瘫痪，往日的欢乐从此一去不返，而繁重的医疗费用更压得他们喘不过气来。绝望之余，小小的梅蒂产生了一个绝对大胆而有疯狂的想法——抢劫一家由她的妈妈担任安全主管、防卫森严的当地银行。为此，她找来了她的两位好朋友，电脑天才格斯和机械狂人奥斯汀，拟定了一个巧妙、周密的计划……','They\'re on a mission without permission.',18000000,16702864,4.492859,4.9,76,92,'2004-02-06','en','/vNZTtrzrIsIAHzqH3143oWIzFjG.jpg',2.7529213298727373,3,'2026-09-10',2,NULL,NULL),(20504,'艾利之书','The Book of Eli','近未来，地球爆发一场毁灭性的战争。灾难过后，人类文明消失殆尽，整个星球满目疮痍。幸存者逆境求生，为了有限的资源回归原始，暴力血腥肆意蔓延。沉默的黑人艾利（丹泽·华盛顿 Denzel Washington 饰）是一个独来独往的旅者，他横越荒芜的美洲大陆，见识几多炎凉和凶险。这一日，艾利辗转来到一座喧嚣小镇。神秘危险的卡耐基（加里·奥德曼 Gary Oldman 饰）控制着小镇的水源，也因此成为富甲一方、不可一世的大头目。正当此时，世间流传着一本关乎人类未来命运的预言书的传说，而艾利正是这本书的护送人。卡耐基派出手下四处寻找预言书，结果一无所获，命运却指引着他和艾利宿命地相会。人类的命运终将如何……','Some will kill to have it. He will kill to protect it.',80000000,157107755,32.363538,6.6,2164,118,'2010-01-14','en','/tiXn3C4ZHmxuIBXE9lcjd5cQKFN.jpg',3.6848301597036675,3,'2026-09-10',2,NULL,NULL),(20520,'汽车旅馆','The Motel','Thirteen-year-old Ernest Chin lives and works at a sleazy hourly-rate motel on a strip of desolate suburban bi-way. Misunderstood by his family and blindly careening into puberty, Ernest befriends Sam Kim, a self-destructive yet charismatic Korean man who has checked in. Sam teaches the fatherless boy all the rites of manhood.','Out of Place in the Middle of Nowhere.',0,0,0.120505,7,3,75,'2005-01-01','en','/7dHilrksaDBIVulSBduS1dsHXai.jpg',2.1361795436079287,3,'2026-09-10',2,NULL,NULL),(20526,'创：战纪','TRON: Legacy','这部电影是1982年《Tron》的续集，故事讲述萨姆·弗林的儿子为了寻找失踪多年的父亲，在父亲好友艾伦·布拉德利（布鲁斯·巴克林纳饰）的引导下，和女友（奥利维亚·王尔德饰）一起进入了一款名为“Tron”的电玩中。游戏世界已经进化得更加先进危险，在与父亲重逢后，三人在这个视觉惊人的电子世界中展开了一段生死大冒险。','The Game Has Changed.',170000000,400062763,73.79505,6.3,2841,125,'2010-12-10','en','/xcO8Uun0mfmE3N9CaiCy0tvjpiu.jpg',3.7739018606308075,3,'2026-09-10',2,NULL,NULL),(20533,'西部英雄约拿·哈克斯','Jonah Hex','约拿·哈克斯（乔什·布洛林饰）他是一个赏金猎人，是一个残酷无情的枪手，还是一个无所畏惧亦无所需求的男人，他过着清心寡欲的生活，他存在的一切目的就是要找到、抓到、杀死。\r 约拿·哈克斯的暴力史以及他死里逃生的过往已经成为了传奇和谜团，没有人能确切地说清楚约拿·哈克斯是如何走到今天这个地步的，也没有人知道约拿·哈克斯到底过着什么样的生活。正是这样的经历，让约拿·哈克斯成为了横跨现实世界和超现实世界的神秘人物，不过，约拿·哈克斯也不是独来独往的侠客，他和人类还有联系，他和一名叫做赖莉（梅根·福克斯饰）的妓女还有密切的关系。\r 美国军人找到了约拿·哈克斯，他们给哈克斯开出了一个他无法拒绝的条件，只要能搞定巫毒术士昆汀·特恩布尔（约翰·马尔科维奇饰），哈克斯就能换回自己的自由，在很多年之前，昆汀·特恩布尔就曾经杀死了哈克斯的妻子和孩子，并在他的脸上留下了伤疤。这次，哈克斯迎来了自己的一个复仇的机会。不过，昆汀·特恩布尔却不是那么好对付的一个对手，他的手下正在召集一支死亡大军，并要跃跃欲试地在美国大开杀戒，同时昆汀·特恩布尔更视哈克斯为不共戴天的敌人，他也要杀死哈克斯为快。','Revenge gets ugly.',47000000,10539000,22.581313,4.4,420,80,'2010-06-18','en','/orMcEFIzfnZU1oHMfe86dh1Uzz0.jpg',3.0096048723010482,3,'2026-09-10',2,NULL,NULL),(20542,'德尔哥','Delgo','在一个魔幻的世界里，强大而发达的精灵一族诺瑞恩人正遭受着资源枯竭的困扰。为了拯救国中子民，国王派出使者寻找新的土地。他们来到富饶的吉哈莫拉，受到当地原著民洛克尼人的欢迎。然而随着时间的推移，两个民族间的矛盾逐渐凸现。在战争狂人——国王的妹妹西德莎的率领下，诺瑞恩军队对善良的洛克尼人展开大屠杀。饱受蒙蔽的诺瑞恩国王剥夺了西德莎的皇族身份，然西德莎却阴谋毒害国王一家，最终这个作恶多端的女人被流放边疆。',NULL,40000000,0,4.238482,5.4,15,94,'2008-12-12','en','/wtk430tDLZ0Ql5jCUWCja8qJJQQ.jpg',2.4412104724030965,3,'2026-09-10',2,NULL,NULL),(20616,'恶女上身','Swimfan','本（杰西·布拉德福特 Jesse Bradford 饰）拥有强健的体魄和优美的身姿，再过几个月，他就将踏出高中的校门走上社会，在游泳这项运动上的天赋令他获得了领取斯坦福大学游泳奖学金的资格，与此同时，他还有着一个美丽温柔的女友艾米（施瑞·阿普莱碧Shiri Appleby 饰），两人之间的感情十分要好。一天，一个名叫梅迪森（埃丽卡·克里斯滕森 Erika Christensen 饰）的姑娘来到了本的游泳池，她似乎对本有着浓厚的兴趣，对他百般挑逗，而本也有些把持不住。没过多久，本被查出服用禁药而被开除出了泳队，而艾米则遭受神秘人的恐吓骚扰最终住进医院。而这一切，似乎都和梅迪森有着千丝万缕的关联。','His biggest fan just became his worst nightmare.',8500000,34411240,4.844451,5,70,84,'2002-09-06','en','/mOAiqOivdVecMu0yhumN6pzDWmo.jpg',2.7412138647782878,3,'2026-09-10',2,NULL,NULL),(20653,'流浪狗罗密欧','Roadside Romeo','This is the story of Romeo. A dude who was living the life. He had the works - the mansion to live in, the chicks to party with and the cars to be driven around in. Until one day, the family he was the favourite pet of, decided to move and left him back, abandoned on the mean streets of Mumbai. Romeo is now faced with situations he has never been in before. He encounters four strays, who scare the daylights out of him. But soon, he smooth talks his way into their hearts and he makes friends. Then, Romeo finds love! He encounters the beautiful, ravishing Laila, the most beautiful girl he has ever seen - and he loses his heart to her at first sight. Finally, he encounters a villain! The dreaded Don of the area - Charlie Anna. The Don who everyone is scared of. So hop on to the adventure as Romeo, wins friendship, love and a new life - in spite of Charlie Anna and his gang!',NULL,7000000,1100000,0.253595,6.7,3,93,'2008-10-24','en','/tkeZApwgdXLjZPiGb1jVl489LoS.jpg',2.136114407644083,3,'2026-09-10',2,NULL,NULL),(20662,'罗宾汉','Robin Hood','这部电影将以全新的方式给你讲述历史上真正的罗宾汉的故事。公元13世纪的英国，弓箭手罗宾汉(罗素·克劳)跟随“狮心王”理查的大军上前线与法军作战，那时的罗宾汉只想着求得自保，并没有展现出后来的侠义精神。理查国王去世以后，罗宾汉来到了诺丁汉，这里被腐败的诺丁汉治安官弄得民不聊生，苛捐杂税多如牛毛。 　　罗宾汉在这里见到了一个独特的寡妇玛丽安女士（凯特·布兰切特），他很快就被其坚定勇敢的气质所吸引并深深爱上了她，不过玛丽安却对罗宾汉的身份和动机产生怀疑。为了改变玛丽安对自己的成见，也为了拯救村民于水火，罗宾汉召集了一群有能力有意愿的人，和他一起揭竿而起，惩治腐朽的上层阶级，改变社会不公。他的这一举动最终使人民重新凝聚在一起，让英国免予陷入内战。','Rise and rise again, until lambs become lions.',200000000,310669540,37.668301,6.2,1398,140,'2010-05-12','en','/aWagyUh0RC6CvVVOR5euAMtGyC0.jpg',3.5099695583474353,3,'2026-09-10',2,NULL,NULL),(20694,'Rugrats Go Wild','Rugrats Go Wild','Rugrats Go Wild is a 2003 crossover animated film, with two animated Nickelodeon television series Rugrats and The Wild Thornberrys.The film was produced by Klasky Csupo and released in theaters on June 13, 2003 by Paramount Pictures and Nickelodeon Movies. It also makes this the Rugrats series finale, after the show ceased production. As there are currently no further Rugrats movies in production, Rugrats Go Wild stands as the final Rugrats film. It is the only Nickelodeon film to be a crossover. Although it is a crossover film, it is primarily a Rugrats movie as the main plot focuses on the those characters.The Rugrats family vacation takes an exotic detour when their boat capsizes and they become shipwrecked on a deserted tropical island. With the jungle as their new backyard, the babies reace wildly from one dangerous adventure to the next…soon to discover that someone else is on the island. It\'s The Wild Thornberrys...on an island adventure of their own!','The Family Vacation Goes Overboard',0,0,8.255708,5.6,61,84,'2003-06-13','en','/hpVpXRNY2IsU0xvfXtYOxu0QDwc.jpg',2.736952987574411,3,'2026-09-10',2,NULL,NULL),(20697,'跤坛风云','Ready to Rumble','Two slacker wrestling fans are devastated by the ousting of their favorite character by an unscrupulous promoter.','They\'re headed to the big time...face first.',24000000,12372410,3.113009,4.7,49,107,'2000-04-07','en','/fRJNUXbeTte3MmpCqCRs53W7HIR.jpg',2.663667892024822,3,'2026-09-10',2,NULL,NULL),(20737,'飞狗巴迪','Air Bud','男孩乔治·菲姆的父亲在一次试飞中因事故身亡，从此爱打篮球的乔治性格变得内向寡言，在学校经常被同学嘲讽和取笑。在搬家的路上他遇见了金毛猎犬巴迪，它刚刚摆脱主人的虐待。乔治回家以后，在后院的篮球场上打篮球的时候再次遇见巴迪，并发现巴迪也喜欢玩篮球。后来他将巴迪带回家，开始了新的生活。他的性格开始发生了转变。偶然的一次交谈中，他发现和自己一起打扫卫生的黑人大叔居然是曾经的著名球星阿瑟。阿瑟使他的球技蒸蒸日上，并教会了他很多做人的道理。在一次比赛中，巴迪的主人在电视上看到了这只会打篮球的狗原来就是他的，于是前往领取。乔治把巴迪救回以后将它放生到荒岛上，防止主人再次寻找到它。由于失去了巴迪，乔治在比赛中节节失利，后来巴迪意外出场使全队取得胜利。最后巴迪被法官公正地判给了乔治，这对好朋友从此以后再也不会分开……','He Sits. He Stays. He Shoots. He Scores.',3000000,23144499,11.241802,5.3,106,98,'1997-08-01','en','/zG28OfaVMP3HhBzHycOZ04Sfj3K.jpg',2.8431844110788735,3,'2026-09-10',2,NULL,NULL),(20761,'玩到底','Play It to the Bone','Two aging fighters in LA, friends, get a call from a Vegas promoter because his undercard fighters for a Mike Tyson bout that night are suddenly unavailable. He wants them to box each other. They agree as long as the winner gets a shot at the middleweight title. They enlist Grace, Cesar\'s current and Vinnie\'s ex girlfriend, to drive them to Vegas.',NULL,24000000,8434146,5.566203,5.7,53,124,'1999-12-25','en','/qSJl8pD17doJsAkou5mPvDogBQT.jpg',2.7042981095644345,3,'2026-09-10',2,NULL,NULL),(20763,'海阔天空','Radio Flyer','麦克（Elijah Wood ）和弟弟巴比（Joseph Mazzello ）跟著离婚的妈妈（Lorraine Bracco ）搬到加州寻找新生活，当母亲再婚后，她为了养家活口每天从早到晚外出工作，更糟糕的是酗酒的继父常对巴比动辄拳脚相向，令两兄弟的生活过得很不顺遂，为了体贴辛劳的母亲，兄弟俩对此事三缄其口，转而用心策划改装巴比的玩具车，梦想让巴比乘坐著它飞离一切让人烦心的事，可是一切并非如此顺畅……','Powered by imagination.',35000000,4651977,3.503408,6.6,53,114,'1992-02-21','en','/nQjCKrwWYH6ES0HrnkLkPXnOEp0.jpg',2.717898851804381,3,'2026-09-10',2,NULL,NULL),(20764,'睡眠经销商','Sleep Dealer','曼莫（路易斯•费尔南多•佩纳 Luis Fernando Peña 饰）与父母生活在墨西哥小镇桑塔安那，靠务农为生。德里奥水公司在附近河流建坝拦水，至使整个地区严重缺水。高昂的水价致使走投无路的农民去坝上偷水。德里奥水公司在美国境内的总部则雇佣飞行员鲁迪（雅各布•维加斯 Jacob Vargas 饰）通过精神连线遥控操作无人轰炸机打击“恐怖分子”保护水坝，炸毁了曼莫的住所，曼莫的父亲被当场杀死。悲伤的曼莫离开家乡来到美墨边境城市蒂华纳找工作，遇见女作家鲁兹（莱诺•维埃拉 Lennor Varela 饰）。鲁兹帮曼莫装上“结点”，从此曼莫进入工厂精神连线遥控操纵美国各地的机器人从事繁重的体力劳动。鲁兹为了持续出售曼莫的故事，与他的接触逐步加深，二人终于相爱。但网络另一边购买曼莫故事的人竟是鲁迪……','Crossing the border just got easier. Plug into the new American dream.',2500000,107559,4.624691,6,40,90,'2008-12-10','en','/kFXQ4oMJkXAWjyo7Tr5GrLjmk61.jpg',2.6489795041974977,3,'2026-09-10',2,NULL,NULL),(20766,'末日危途','The Road','绝望的未来，世界恍如巨大的废墟，双眼所及之处尽是荒凉与灰暗。人类文明在末日的劫难中毁灭殆尽，在资源极度短缺的情况下，幸存者无所不用其极，甚至出现人吃人的惨烈情况，整个世界呈现地狱般的光景。一位父亲和他的儿子进行着漫无止境的旅程。他们不断向南，寻找着更为温暖的避难场所，破旧的超市小推车负载着父子二人所有的家当。前路漫漫，希望渺茫，父亲不断回忆着妻子的音容笑貌和他们过去美好的时光，而如今美好不在，父子俩的明天更不知将在何方……','In a moment the world changed forever.',32000000,27635305,41.075532,6.8,1087,111,'2009-11-25','en','/guyHsxj4O3EZf67n7XGtb55dOGV.jpg',3.569395484352041,3,'2026-09-10',2,NULL,NULL),(20770,'啦啦队长','But I\'m a Cheerleader','个性活泼开朗的梅根是校园拉拉队的队长，亦是男生们仰慕追求的对象。然而，在误打误撞之中，梅根竟然被父母误会是同性恋，而被送往了“治疗”同性恋的同情恋矫正学校之中，在这里就读的，都是被认为有同性恋倾向的年轻男女们。因为相同的境遇和性取向，大家很快就成为了无话不谈的好友，在这里，梅根结识了名为格拉汉姆的女孩，刚开始，两个个性迥异的女孩将对方视为眼中钉肉中刺，常常爆发激烈的争吵，但随着时间的推移，两颗年轻火热的心开始渐渐靠近……','A Comedy Of Sexual Disorientation.',0,0,4.826908,6.5,101,85,'1999-09-12','en','/8huDg3Q0EmcWuN9HgYsO8ylAp9f.jpg',2.863259934713212,3,'2026-09-10',2,NULL,NULL),(20794,'麻醉性谋杀','Novocaine','弗兰克·桑斯特（斯蒂夫·马丁饰）是一名私人牙医，在美国，这是一份很体面的工作，他和女友劳拉·邓恩过着幸福的生活。可谁曾想到，灾难已经降临到他的身上。\r 　　一天，一个名叫苏珊·艾维（海伦娜·邦汉·卡特饰）的女病人来到弗兰克的私人诊所看牙。起初，弗兰克只知道这个女人对止痛药有依赖性，但是不久以后，他就发现诊所里的药品开始丢失，而且他还成了警方的通缉犯，罪名是：偷运毒品。\r 　　很明显，弗兰克是被苏珊利用了。他现在要做的，就是深入虎穴，收集证据，来证明自己的清白......',NULL,6000000,2025238,4.148253,6,44,95,'2001-11-23','en','/6ZVFepWKzYho4DLhyFVuRk7klZ1.jpg',2.6679397202328556,3,'2026-09-10',2,NULL,NULL),(20829,'滑稽人物','Funny People','事业成功广受欢迎的喜剧演员乔治•西蒙斯 发现自己身患白血病，决定趁有生之年重返单口笑话表演舞台。在一次表演中乔治结识了单口笑话表演爱好者艾拉。穷困潦倒的艾拉一直梦想成为一名职业单口笑话演员，付不起房租的他一直借住朋友电视演员马克 的客厅，同住的还有单口笑话表演爱好者利奥。艾拉被乔治雇佣成为私人助理，说服乔治将患病消息通家人与前未婚妻劳拉。乔治的白血病在新型实验药物的作用下得到控制，惊喜的他与艾拉前往旧金山表演，在城北马林县家劳拉家中二人旧情复燃。但劳拉的丈夫克拉克 此时突然返家，一切变得尴尬又糟糕……','George Simmons was prepared to die, but then a funny thing happened.',75000000,61458982,20.199057,5.7,390,146,'2009-07-31','en','/gEYKD5cWCBGg8Za3hhwDBk3gEsP.jpg',3.1328460990040683,3,'2026-09-10',2,NULL,NULL),(20856,'楼上的外星人','Aliens in the Attic','皮尔森（凯文•尼龙 Kevin Nealon 饰）带着家人来到郊外的别墅和弟弟一家一起避暑度假。一场看似普通的流星雨让4个带着可以控制人思维的高科技仪器企图侵略地球的外星人迫降在别墅的阁楼里。他们起初利用控制贝瑟尼（阿什丽•提斯代尔 Ashley Tisdale 饰）的男朋友里基（罗伯特•霍夫曼 Robert Hoffman 饰）悄然打入这家人中，可不料还是被皮尔森家的孩子们敏锐的觉察到。虽然家里的大人不相信小孩子们的说法，可孩子们还是渐渐意识到了家中阁楼上这四个外星人存在的巨大潜在危机，悄悄的团结在一起开始了一场人类保卫战。而那四个外星人也不甘示弱，面对孩子们制造出的各种新奇的小武器，他们用控制人思维的机器控制了家里的大人来反攻这些孩子们。可这四个外星人里有一个例外，就是技师斯帕克斯，原本就无心恋战的他更是机缘巧合的和汉娜结成了好友，弃暗投明的开始帮助皮尔森一家。面对强大的外星人入侵，孩子们能否把这场人类危机化险为夷呢？','The aliens vs. the Pearsons',45000000,57881056,13.707183,5.3,244,86,'2009-07-31','en','/bb8ym5zSRGmhNx3gyDnzSN2waS4.jpg',2.9985060137963053,3,'2026-09-10',2,NULL,NULL),(20857,'追梦高手','Hardball','一个沉迷颇深的赌徒康纳欧尼尔（基努李维饰），他非常喜欢在运动比赛上下赌注，弄得他常常生活相对据，四处借贷，使得他的朋友也不堪其扰，最后他 的朋友要他接下一份工作否则就不帮他清偿赌债—他要成为一个企业赞助的青少年棒球队的教练。\r 　　刚开始这群小鬼头完全无法进入状态，让康纳头痛不已，不知道要如何训练他们，而他们更因为各自家庭背景的关系也产生了很多摩擦和隔阂，可是在每天相处的情况之下让 他们之间的互动越来越有默契，也让彼此更加了解对方。\r 　　另一方面更吸引康纳的是这群小鬼头的美丽级任导师，这使得康纳对于这份工作越来越有热诚，竟然露出了他生平最大的兴趣—人数。\r 　　同时康纳带着这群小鬼过关斩将，在当地小联盟球赛中所向披靡，而他们最终的目标就是赢得冠军','The most important thing in life is showing up',32000000,40222729,5.683281,6.3,123,106,'2001-09-14','en','/9RMcwwnK8a9WCt8dVlwmtNsFCg3.jpg',2.9015963130286404,3,'2026-09-10',2,NULL,NULL),(20862,'烟火讯号','Smoke Signals','年轻的印度男子托马斯是一个书呆子，他戴着超大眼镜，很喜欢跟大家的故事，但是这故事是没有人想听到的。他的父母在1976年的大火中丧生，并托马斯·阿诺德照顾。阿诺德很快就离开了他的家人（包括他严肃的儿子维克多），10年过去维克多还没有见过他的父亲。当维克多听到阿诺德已经去世，托马斯提供他资金让他去取回阿诺德的遗体，但阿诺德强调只有当托马斯和他一起去，他才回去。最后托马斯和维克多上路…',NULL,0,0,2.304552,6.6,24,89,'1998-01-16','en','/dZ6smtO2cEm3nxVhWscYfKS0mYX.jpg',2.5426802903702934,3,'2026-09-10',2,NULL,NULL),(20943,'丑陋的真相','The Ugly Truth','作为颇有名气的电视节目《挑战清晨》的制片人，漂亮知性的艾比里（凯瑟琳·海格尔 饰）一直是台里大家谈论的焦点，这不仅仅是因为她的节目有多么的受欢迎，更重要的是，已到而立之年的艾比里至今仍然单身一人，这不由得引起了台里大多数人的遐想，而对于艾比里自己而言，为什么单身她很清楚：因为她的择偶标准实在是高得惊人，而恰恰她又曾经碰上了符合自己所有标准的“完美先生”，但这位意中人最后却离开了她，于是现在的艾比里已经不再那么相信爱情，她把更多的心思放在了工作上面。　　对于婚姻与爱情的观点很快就引起了她的同事麦克（杰拉德·巴特勒 饰）的兴趣。他认为艾比里现在对爱情的看法大有问题，因此他略施小计，激将艾比里参加自己制作的一档挑战节目，在这个节目里艾比里逐渐的发现了一些她过去认为“丑陋事实”的真相……','The battle of the sexes is on.',38000000,205298907,22.332927,6.4,972,96,'2009-07-24','en','/ohXLIVsX64Qxe4fYd5BQCwcMwC4.jpg',3.428135317744571,3,'2026-09-10',2,NULL,NULL),(20981,'克苏鲁的呼唤','The Call of Cthulhu','A dying professor leaves his great-nephew a collection of documents pertaining to the Cthulhu Cult. The nephew begins to learn why the study of the cult so fascinated his grandfather. Bit-by-bit he begins piecing together the dread implications of his grandfather\'s inquiries, and soon he takes on investigating the Cthulhu cult as a crusade of his own.',NULL,50000,0,1.777148,6.9,41,47,'2005-01-01','en','/dCrOkzrWs8ux31oVCc1R8tt6zTC.jpg',2.662053518887653,3,'2026-09-10',2,NULL,NULL),(21014,'Keeping Up with the Steins','Keeping Up with the Steins','All hilarity breaks loose in this heartwarming coming-of-age comedy when three generations of Fiedlers collide in a crazy family reunion. As they prepare for the biggest Bar Mitzvah on the block, they begin to see that they\'re much more alike than they\'d originally thought.','A 13-year-old boy uses his upcoming bar mitzvah to reconcile the strained relationship between his father and grandfather.',0,0,3.562563,5.2,18,90,'2006-05-12','en','/bYp81rOQZEoFfDMX6xqRU1x3R7M.jpg',2.4746945803393485,3,'2026-09-10',2,NULL,NULL),(21074,'砖块街','Brick Lane','该片改编自英籍孟加拉裔女作家莫尼卡·阿里所著同名小说，以英国伦敦东区的砖块街为背景，讲述了一个远嫁伦敦的孟加拉少女在生活的艰辛中逐渐走向成熟的故事。',NULL,0,0,0.262135,5.2,15,102,'2007-11-16','en','/fOi0il1YvBj0d6wE5OyGIqMPV4S.jpg',2.4309171090934862,3,'2026-09-10',2,NULL,NULL),(21208,'孤儿怨','Orphan','凯特和约翰本来有个幸福美满的家庭，但是，凯特的一次意外流产把这一切都毁了。这次意外让他们的婚姻出现了裂痕，凯特原本就很脆弱的灵魂也处在崩溃的边缘。为了能让自己的生活恢复正常，这对夫妻决定到附近的孤儿院领养一个孩子，以安慰他们愧疚的灵魂。来到孤儿院，夫妻俩都被一个名叫艾斯特的女孩给吸引了，很快，他们就决定将艾斯特带回家。 然而，自此以后，不可思议的事件接二连三的发生。表面看上去如天使般天真可爱的艾斯特实际上并不那么简单，凯特坚信，肯定是艾斯特中了什么邪。凯特多次警告约翰以及自己的其他孩子注意观察艾斯特的举动行为，但是却没人理会。 当他们察觉时，一切都已经太晚了……','Can you keep a secret?',20000000,41596251,29.295801,6.7,1261,123,'2009-07-24','en','/mr3Ckc0okL8Onv3av6MPMAQYUy6.jpg',3.5629249328560837,3,'2026-09-10',2,NULL,NULL),(21283,'一往无前','Steppin: The Movie','每个大学校园都有其竞争，悉尼科技大学也不例外。在这所大学里，极客们管理着校园，最伟大的踏步者是山中之王。当当地一家广播电台宣布踏步比赛季开始时，校园兄弟会和联谊会努力招募最优秀的人才，帮助他们赢得巨额奖金。',NULL,0,0,0.328498,5,4,85,'2009-05-19','en','/wkBSpDIRqKU46rb6cUICx8xxPm1.jpg',2.1821948658573187,3,'2026-09-10',2,NULL,NULL),(21301,'哈啦大发师2','Barbershop 2: Back in Business','经历过经济危机的苦恼后，卡尔文(冰块•酷巴 饰)的理发店没有卖出去继续营业了，阴翳过后这里又恢复了往日的欢声和热闹。这间理发店是卡尔文的家族产业，位于南部芝加哥，虽然收入寥寥一直靠着几个老主顾维持，憨厚热心的卡尔文仍然继续营业，在他看来，这里至少能够带给社区的人们休息和交流的场所。\r 理发店似乎还是老样子，人们聚集在这里讨论着家长里短或者国家大事，人人畅所欲言争论不休，却又热闹非常充满生气。理发师老艾迪(锡德里克 饰)还是为顾客们剃着一成不变的发型，以前颇为清高的吉米(辛•派屈克•托马斯 饰)终于变得随和亲切了，而泰莉(伊娃 饰)在对男友的失望之下，选择了一直暗恋她的邓卡(莱昂纳多•艾•豪斯 饰)，理发店似乎更加团结亲密了。\r 正当卡尔文奢望着理发店安安稳稳的营业下去时，旁边忽然开了间美容院，新潮的设计、先进的设备、优秀的理发师以及周到的服务，尤其是开朗热情的理发师吉娜(奎因•莱提法 饰)十分受人欢迎。很快，美容院立刻引起了社区人们的注意，吸引了社区大部分的顾客，甚至连理发店的老顾客们也开始动摇，打算把脚挪到旁边的美容院去了。\r 在美容院的竞争之下，刚刚缓过危机的卡尔文眼看着又要面临关门的危险，他们气恼地和美容院发生了一系列的争执，几乎闹得不可开交。\r 此事未了，一波又起，有个大财团试图吞并芝加哥南部地区所有的服务业，他们开了咖啡店、录像出租店和连锁理发店，并且试图把所有家庭式经营的小店全部赶尽杀绝。为了共同的利益，卡尔文的理发店和吉娜的美容院很快停止争执，合力一起争取他们的利益了……','Let your hair down',18000000,65070412,6.501815,5.6,74,106,'2004-01-20','en','/ljEwtAcACAk8uTZAMtZKWHrxYZ8.jpg',2.771982655143854,3,'2026-09-10',2,NULL,NULL),(21309,'大河边缘','River\'s Edge','一群童党中的一名成员谋杀了一名女孩，把她弃尸河边，其他成员知道此事后不知道如何面对？导演提姆．亨特以紧凑有力的手法深入探讨八十年代年轻孩子在成长过程中种种心理问题，包括对社会，对人际关系，甚至对自己的长大成人都充满傍徨和不确定感。','The most controversial film you will see this year.',19000000,0,6.463806,6.7,59,99,'1986-08-27','en','/3CWr2uStevkgQZVvcZ0zBYEkO4Y.jpg',2.750826118279999,3,'2026-09-10',2,NULL,NULL),(21311,'梦游非洲','I Dreamed of Africa','库利（金·贝辛格 Kim Basinger 饰）很小的时候和家人一起去过非洲，那里壮阔的美景和辉煌的气魄深深的留在了库利幼小的心中，令她久久无法忘怀。一晃眼几十年过去，长大成人的库利和丈夫保罗（文森特·佩雷斯 Vincent Perez 饰）一起，带着小儿子伊曼纽尔（阿兰·罗伯茨 Ian Roberts 饰）再度回到了非洲这片神奇的土地上。\r 一家人在非洲建立了农场，他们的目的是保护生活在这片土地上的濒危野生动物，这其中的艰难险阻可想而知。之后，保罗不幸在一场意外中丧生，留下了孤儿寡母继续完成着他们未尽的理想，与此同时，库利发现自己的腹中再度怀上了保罗的孩子。','Sometimes the adventure of a lifetime becomes life itself.',34000000,0,1.656695,5.3,18,114,'2000-05-05','en','/kuDIrcsUI0duLSTUgKKLKEiEdrK.jpg',2.4710646460111665,3,'2026-09-10',2,NULL,NULL),(21334,'小鞋子','بچه‌های آسمان','家境贫寒的男孩Ali（Amir Farrokh Hashemian 饰）帮妹妹Zahra（Bahare Seddiqi 饰）取修补好的鞋子时，不慎将鞋子弄丢，为了不被父（Mohammad Amir Naji 饰）、母（Fereshte Sarabandi 饰）责罚，他央求Zahra暂时保密，说两人可以替换着穿他的鞋子上学，并答应一定会帮她买双新鞋子。Ali原本指望用他和父亲进城打工挣的钱帮Zahra买双新鞋，父亲的意外受伤打消了他的美梦。看到全市长跑比赛季军的奖品是一双运动鞋时，Ali决定参加比赛，但是他错过了报名日期。几经哀求，老师（Dariush Mokhtari 饰）破例让实力出众的Ali参加了比赛。比赛场上，Ali不断提醒自己，一定要得第三名！','A Little Secret...Their Biggest Adventure!',180000,900000,7.072118,7.8,112,89,'1997-08-01','fa',NULL,2.9439368342454117,3,'2026-09-10',2,NULL,NULL),(21338,'九反威龙','Stone Cold','美国飞车党是一有组织的犯罪集团，FBI找来史东渗入飞车党卧底，史东很快博取有爪牙信任，为了搜取证据引诱南茜合作，希望能指证飞车党杀警越货的证据，不幸南茜事发身亡，史东也成为人质，州政府欲将爪牙处死，首领欲劫狱救出爪牙，史东终将首领绳之于法。','A cop who enforces his own brand of justice.',0,0,3.623002,5.7,34,92,'1991-05-17','en','/4nW7wZKKjzZ5zriDfIjpJcZIyZS.jpg',2.6085720761332998,3,'2026-09-10',2,NULL,NULL),(21345,'南京！南京！','南京!南京!','1937年12月，侵华日军攻陷南京。面对即将沦陷的城市，以陆剑雄为代表的中国守军仍在街巷中进行最后的抵抗，但随着南京失守，大批中国军民沦为俘虏和难民，一场惨绝人寰的南京大屠杀随之发生。在南京安全区，唐先生、姜淑云等人竭力保护前来避难的同胞，而普通日军士兵角川也在亲历一幕幕暴行后陷入巨大的精神冲击。战争阴影笼罩下，不同身份的人们在这座满目疮痍的城市中挣扎求生，也不得不面对一次次关于生命、人性与尊严的艰难选择……',NULL,12000000,10652498,4.793348,7.6,55,132,'2009-04-22','zh','/nYz8Cqd5NcBWp5Nl1vTkx0LXMOC.jpg',2.750151640969396,3,'2026-09-10',2,NULL,NULL),(21349,'芳心天涯','Anywhere but Here','尽管阿黛勒（苏珊·萨兰登 Susan Sarandon 饰）已为人母，但她的个性却并不能用“成熟稳重”一词来形容，住在老家威斯康辛的她受不了这里无聊闭塞的生活，在她的梦想里，位于洛杉矶的贝弗利山庄才是她真正的归属。身为阿黛勒的女儿，戳破老妈的白日美梦成为了安（娜塔莉·波特曼 Natalie Portman 饰）每日必做的功课，和这样一个个性乖僻的母亲住在一起，安的生活并不轻松。  　　终于，阿黛勒的梦想已经不仅仅是一个梦想了，她决定将梦想变为现实。就这样，不顾安的阻止，阿黛勒带着安踏上了自己的追梦之旅，在旅途中，接踵而至的意外和麻烦逐渐让阿黛勒意识到了现实和梦想之间的巨大鸿沟，与此同时，安也开始明白，能够大胆追逐梦想的人生才有意义。','A story of a mother who knows best... and a daughter who knows better.',23000000,18653615,8.976738,5.9,66,114,'1999-11-12','en','/2DNtxmXkotuaJexU57geTLIPnQf.jpg',2.762025484583936,3,'2026-09-10',2,NULL,NULL),(21355,'骏马','All the Pretty Horses','故事发生在二战刚刚结束之际，满目疮痍的大地正在缓慢而又艰难的恢复着生计。约翰（马特·达蒙 Matt Damon 饰）和母亲过着相依为命的生活，然而，战后的日子实在难熬，为了维持生计，母亲不得不卖掉了家中的农场，约翰失去了童年唯一的记忆，陷入了深深的痛苦之中。','Some passions can never be tamed.',57000000,0,7.524671,5.8,60,117,'2000-12-11','en','/6E4E7wYXw1DE2321F2hVNryLSk7.jpg',2.7364982392695083,3,'2026-09-10',2,NULL,NULL),(21413,'The Battle of Shaker Heights','The Battle of Shaker Heights','A quirky teen with a penchant for war reenactments, Kelly Ernswiler obsesses over military tactics with his buddy Bart. The school bully is one of Kelly\'s regular headaches, and he also has to deal with a frustrating situation at home, where his father is a recovering drug addict. Kelly\'s life gets even more complicated when he falls for Tabby, Bart\'s pretty and soon-to-be-wed older sister.','When you\'re 17, every day is war.',1000000,0,5.20209,5.6,17,79,'2003-08-22','en','/l7PDR9rtbUN5b4gMVPSLMqIgfov.jpg',2.4697941328682016,3,'2026-09-10',2,NULL,NULL),(21461,'黑帮大佬和平梦','लगे रहो मुन्ना भाई','甘地热潮正席卷印度全国，其中一个原因可以说是拜本片所赐。本片讲述黑道人物姆纳为了追求一名电台女DJ，讹称自己是大学教授，不惜恶补甘地生平，以便参加电台问答比赛。当他日刨夜刨时，甘地的鬼魂就在他眼前出现，教导他如何以非暴力手段应付人生逆境。在这出黑道人物追女仔的电影中，圣雄甘地的角色几乎由头演到尾，甘地的哲学和精神也贯彻了全片。本片在首都新德里开画一星期后，市政府以该片宣扬甘地追求真理和非暴力抗争，宣布该片可以豁免缴交娱乐税。同样地，印度中部切蒂斯格尔邦也因本片表扬甘地的价值观，具有教育意义，宣扬正面讯息，也给予该片免税的地位。','They\'re back... and they\'re not alone!',0,0,2.436019,7.6,44,144,'2006-01-01','en',NULL,2.6913709109309116,3,'2026-09-10',2,NULL,NULL),(21494,'Moliere','Molière','Molière, a down-and-out actor-cum-playwright up to his ears in debt. When the wealthy Jourdain offers to cover that debt (so that Molière\'s theatrical talents might help Jourdain win the heart of a certain widowed marquise), hilarity ensues.',NULL,0,0,4.61335,6.7,45,115,'2007-01-31','fr','/aniCegBSRivp6SOx6kktYbme7IE.jpg',2.685951856028619,3,'2026-09-10',2,NULL,NULL),(21512,'壮士血','The Blood of Heroes','每次重温这部电影，我都为它纯粹的深度而感到惊喜。不仅角斗士运动令人信服、设计精良，且由优秀演员倾情演绎，而且影片所设定的后文明（而非后末世）世界也刻画得细腻入微，令人信服。简洁的剧本中，没有一处像往常一样，对核战争（或其他类似战争）——正是这场战争将人类带回了封建野蛮时代的——进行粗暴的科幻式描述。影片呈现给我们的是角斗士世界的原貌，没有一句“如你所知，我们的社会在天空之火之后崩溃了”的台词，也没有一丝暗示片名中的英雄们除了角斗士表演之外，还能以其他方式改善人类的悲惨处境。','When juggers play there is only one way to live - THE HARD WAY!',0,882290,6.41678,5.9,31,100,'1989-10-19','en','/ykdEyq2GCKRr8TsUBuVkRWuWkLj.jpg',2.5984109613767954,3,'2026-09-10',2,NULL,NULL),(21525,'图派克：风华再现','Tupac: Resurrection','导演劳伦.拉曾：调研和资料收集花了一年，把这些素材放在一起实际上是一部很传统的纪录片，而不是用他自己的语言讲述这个概念。然后，我就开始剪辑出戏剧线索，让其成为一部影片。可以肯定的是，故事本来就存在着，是他把整个故事支撑起来的。','In his own words',300000,7808524,1.314576,8,26,112,'2003-01-23','en','/dGJxjq8npqFZtuAtGsyjntip7uh.jpg',2.5719806247935653,3,'2026-09-10',2,NULL,NULL),(21610,'夜鹰','Nighthawks','Deke DaSilva （Sylvester Stallone饰）和Matthew Fox （Billy Dee Williams饰）是纽约市警察局的两个好搭档。Deke DaSilva非常喜欢他所做的警察工作，多次放弃晋级机会，当他和Matthew Fox被分派到反恐精英队时，DaSilva对此十分不满，心怀芥蒂。此时，反恐精英的英国反恐专家获悉，一个臭名昭著的恐怖分子团伙已经潜入纽约，意图通过连环恐怖袭击引发纽约市的骚乱。专家向反恐精英下达了赶尽杀绝的命令，亦引起DaSilva和Fox的反感。但是，随着炸弹声屡次在纽约市响起，他们开始重新认识了这伙恐怖分子的凶残和危害，于是携手，对恐怖分子一伙痛下杀手，经过一番血腥的厮杀，反恐精英击败了这伙恐怖分子，纽约市又恢复了往日的安宁','A terrorist holds New York in a grip of fear - and only Stallone can take him on.',5000000,19905359,7.058868,6.4,86,99,'1981-03-17','en','/2QgpCgOmlgvOPMMC0OrgCv5EKIf.jpg',2.8287700279759567,3,'2026-09-10',2,NULL,NULL),(21612,'江湖白事','The Funeral','The story concerns the funeral of one of three brothers in a family of gangsters that lived in New York in 1930s. Details of the past of the brothers and their families are shown through a series of flashbacks, climaxing in a shocking ending.','One family, one murder, too many lies.',12500000,1227324,2.950618,7.3,31,99,'1996-01-26','en','/sHbJbr6BvVwRJhliiX1PKPERejO.jpg',2.607637994048228,3,'2026-09-10',2,NULL,NULL),(21641,'魔鬼联队','The Damned United','故事背景设定在1960和1970年代的英格兰，本片讲述了布莱恩·克拉夫在当时的英格兰足球冠军利兹联队担任主教练时，那段注定失败的44天任期，充满了对抗与黑暗幽默。利兹联此前由他的宿敌唐·里维执教，并刚刚经历了俱乐部史上最成功的时期，被许多人视为一种激进而功利的足球新风格的代表——这对于有原则却张扬的布莱恩·克拉夫来说，无疑是大相径庭。克拉夫曾与得力助手彼得·泰勒携手，按照自己的理念在哈特尔普尔和德比郡成功建队。如今，在泰勒缺阵的情况下接手利兹联，面对更衣室里在他看来仍是“唐的子弟兵”的球员，将导致克拉夫的好斗与才华在44天内经受前所未有的考验。[索尼影业经典]','They love me for what I\'m not... ...they hate me for what I am.',10000000,0,13.409125,7.2,152,97,'2009-03-27','en','/ftlbCma6QoRiZgiflVmLuPKHrkq.jpg',3.013076316099064,3,'2026-09-10',2,NULL,NULL),(21724,'轻舞飞扬','Dance Flick','青春靓丽的白人女孩梅根•怀特（肖莎娜•布什 饰）出身于一个优渥的家庭，她自幼热爱舞蹈，并一心考入著名的纽约茱丽亚音乐学院去追寻瑰丽的舞蹈之梦。但是一场车祸夺去了母亲的生命，梅根也不得搬到另一座城市生活。她进入当地一所音乐高中，在此结识了崔茜（切尔希•梅克拉 Chelsea Makela 饰）、托马斯（小达蒙•韦恩斯 Damon Wayans Jr. 饰）等一众好友。对黑人街舞共同的热爱让他们亲密无间，黑人男孩托马斯和曾经的小公主梅根组成搭档，一同磨练他们的舞技，为了共同的舞蹈之梦不懈努力。在这一过程中，托马斯和梅根对彼此也产生了感情……',NULL,0,0,7.326034,4.7,71,83,'2009-05-22','en','/fCRdinI3aH3IAfRan1T81uJBAZ9.jpg',2.7415452511692475,3,'2026-09-10',2,NULL,NULL),(21755,'The Brothers Bloom','The Brothers Bloom','The Brothers Bloom are the best con men in the world, swindling millionaires with complex scenarios of lust and intrigue. Now they\'ve decided to take on one last job – showing a beautiful and eccentric heiress the time of her life with a romantic adventure that takes them around the world.','They\'d never let the truth come between them.',20000000,5530764,10.218307,6.8,203,114,'2008-09-09','en','/xIz8iwzyjgWGzcIwHKpqhBs77ML.jpg',3.0568820596291477,3,'2026-09-10',2,NULL,NULL),(21765,'外星神犬','Good Boy!','小男孩欧文（连姆·艾肯 Liam Aiken 饰）辛辛苦苦的工作了一整个夏天，父母终于同意了他在家里养宠物的请求，就这样，欧文将一条名为哈勃的狗狗迎回了家。有哈勃陪伴的生活每一天里都充满了新奇和快乐，然而，随着时间的推移，哈勃逐渐展现出了和一般狗狗大相径庭的特质，让欧文对哈勃的真实身份起了疑心。\r 原来，哈勃并不是一只普通的狗，它来自于遥远的“狗星”，是一条名副其实的“外形狗”。狗星的首领一只企图侵略地球抢夺人类的资源，因此派出了很多间谍前往地球，潜伏在人类的身边。可是，让它百思不得其解的是，这些间谍们在来到地球之后很快就纷纷音信全无，于是它派出了哈勃，狗星上最精明强干的特工前往地球一探究竟。','Rover is about to take over.',17000000,0,3.56033,4.7,30,87,'2003-10-10','en','/kZDXSPfeKNtai6l8yE4J5LwVQMY.jpg',2.570832854271743,3,'2026-09-10',2,NULL,NULL),(21801,'残酷的规则','The Slaughter Rule','一个年轻人找到慰藉与一名年轻女子，他的母亲，谁招募他四分卫一个六人团队高中足球教练。',NULL,0,0,1.390909,6.2,9,112,'2002-01-01','en','/menXGjXgiEaawdOUlxWI1youK6Q.jpg',2.3372794691632564,3,'2026-09-10',2,NULL,NULL),(21972,'小鬼魔鞋','Like Mike','对于14岁的男孩凯文（宝娃 Bow Wow 饰）来说，能够成为入驻NBA的超级篮球巨星一直以来都是他的梦想，为了实现这个梦想，他每天都做着不懈的努力。遗憾的是，梦想和现实之间的距离的遥远的，站在篮球场上，身形单薄的凯文成为了众矢之的。  一次偶然中，凯文捡到了一双球鞋，在球鞋上，写着“MJ”两个字母，对篮球十分关注的凯文立刻就认出，这双鞋属于他的偶像——篮球飞人迈克尔乔丹。在欣喜若狂之中，凯文穿上了乔丹的球鞋，意外地，他发现自己竟然拥有了如同飞人一般的体能和技巧，凭借着这双球鞋，他在球队中出尽了风头，甚至成为了NBA有史以来最年轻的选手，成功的达成了梦想。','Think like Mike, Achieve like Mike, Be Like Mike.',30000000,0,5.73667,5.7,100,99,'2002-07-03','en','/9HSaQmu1QwzvUE7R97RGoDqjTv5.jpg',2.8341049583611766,3,'2026-09-10',2,NULL,NULL),(22007,'恐怖列车','Train','五名美国业余摔跤选手艾历克斯（Thora Birch 饰）、托德、克莱尔、威利、谢尔顿，在教练带领下远赴东欧参加摔跤比赛，虽然他们输掉了比赛，但当晚仍兴致勃勃参加了派对，以致耽误了第二天开往敖德萨的火车，由于语言不通，他们一时买不到车票，一位说英语的金发女郎出现，带领他们登上了车站内的一列红色火车。  　　甫一上车，队员们的护照便被形容猥琐的男乘务员收去，这列经过改装的列车上赌场、餐车、休息室一应俱全，队员们很快远离其他语言不通的乘客，躲在休息室玩起了真心话大冒险，然而在游戏进行的过程中，托德消失在列车尾部，其他队员也一一失踪，艾历克斯很快发现，她要独自面对车上的几个活体器官摘除者……','You\'re in for a hell of a ride.',0,0,3.280081,4.8,36,94,'2008-10-16','en','/lXmnwPbeYUKFub5XMVDOrug0HGH.jpg',2.606830853532916,3,'2026-09-10',2,NULL,NULL),(22013,'孽海痴魂','Elmer Gantry','莎朗修女（简·西蒙斯 Jean Simmons 饰）正在进行她巡回传道的旅程，在途中，她遇见了名为埃尔默（伯特·兰卡斯特 Burt Lancaster 饰）的男子。埃尔默是一个精明狡猾的投机分子，在莎朗修女的身上，他看到了商机。\r 以在海边建立教堂为由头，埃尔默说服了莎朗和他一起赚钱，很快，单纯天真的莎朗就不可自持的爱上了埃尔默，甚至为他献上了本应该献给上帝的身体。可是没过多久，埃尔默就厌倦了莎朗，狠心的将她抛弃了。露露（雪莉·琼斯 Shirley Jones 饰）是牧师的女儿，在得知了莎朗的悲惨遭遇后她深表同情和愤怒。为了报复埃尔默，露露想出了一连串的计谋，并且最终令埃尔默身败名裂。','If there was a dollar to be made - Gantry would make it... If there was a soul to be saved - Gantry would save it...',3000000,10400000,6.734965,7.3,41,146,'1960-06-19','en','/5vd031r08rrfSMqtB9UarwqCUOz.jpg',2.6797724892594896,3,'2026-09-10',2,NULL,NULL),(22051,'亚当','Adam','亚当是一个声控娃娃的玩具设计师，同时也是一个天文爱好者。由于存在社交恐惧症，他一直独居。某天，公寓里搬来了一个性格开朗的女孩——贝丝，她和他在洗衣间相识，并开始了交往。贝丝发现亚当并不谙人情世故。虽然他不懂得约会，却带领她来中央公园看浣熊。慢慢地，两个人产生了感情。贝丝希望亚当进入自己的朋友圈，但是天生对于社交圈的恐惧，让他闹出了不少笑话。与此同时，老板认为亚当的工作效率无法适应竞争的环境，将他解雇。于是，贝丝开始帮助亚当克服心理恐惧，应对面试。两人的感情也随之加温。正在此时，贝丝的父亲突然卷入了一场诉讼案，并面临牢狱之灾，这时亚当却因为贝丝善意的欺骗而大发雷霆。口角时，两人失去了理智，这场恋爱岌岌可危……','A story about two strangers. One a little stranger than the other...',0,2277396,8.308442,6.9,150,99,'2009-07-29','en','/sSN5ec7llAzv0Up7wAQ9qeOM0lS.jpg',2.982585287953363,3,'2026-09-10',2,NULL,NULL),(22074,'资本主义：一个爱情故事','Capitalism: A Love Story','按照资本主义的理想化定义，在该社会体制下生活的人民可以自由自在的选择工作，并获得相应的报酬。但现实究竟如何？2008年金融风暴席卷全球之际，美国的土地上无数人因为丧失赎回权而被银行赶出家园；有的商人则与司法系统勾结兴建感化院，通过监禁犯错的少年大殓其财；还有的企业偷偷为员工投保，并待其死后赚其巨额赔偿金；而当成千上万的工人失业之际，华尔街的银行则向政府请求高达7000亿美元的救济金，这笔钱的最终走向却无人得知。纪录片导演迈克·摩尔（Michael Moore）再次拿起摄像机，试图揭穿政客和商人剥削民众、暴敛钱财的真实嘴脸……  　　本片荣获2009年威尼斯电影节小金狮奖。','Ask not what your C.E.O. can do for you, but what you can do for your C.E.O.',20000000,17436509,10.50098,7,167,120,'2009-09-06','en','/zJBkIPakBXdu3cEgGqKCPHUNXVE.jpg',3.0200735804337215,3,'2026-09-10',2,NULL,NULL),(22102,'比佛利山超级娘子军','Troop Beverly Hills','住在贝弗利山的贵妇菲丽斯平日养尊处优，靠购物、娱乐消磨时间。她的慵懒和享乐使她和丈夫之间产生了矛盾，眼看婚姻即将走到尽头，为了证明自己并不是依赖他人的寄生虫，菲丽斯报名参加女儿的童子军团，并被录取成为队长。贝弗利山队的队员不是贵族后裔就是明星子女，面对这群难缠的小女孩，菲丽斯费尽心思。她带着女孩们重新裁剪了队服，露营的过程中，为了躲避暴雨她和女孩们住进高档的饭店，还在家中举行聚会招待队员和家长。好在菲丽斯的努力并没有白费，傲慢的女孩们逐渐接受了这个开朗新潮的队长，贝弗利山队也开始变得团结有序。但菲丽斯为了证明自己所做的努力并没有挽救她的爱情，菲丽斯和丈夫的婚姻走到了尽头。在菲丽斯最失忆的时候，女孩们给了她莫大的鼓励，她不再为失败的婚姻感到沮丧，菲丽斯要带领自己的队伍去赢得一年一度的全国童子军大赛的冠军。另一只童子军队伍-红羽毛队的队长也就是童子军团的长官普仑敦把菲丽斯视作自己通向成功的障碍，她费劲心思想把菲丽斯挤出童子军团，同时把自己的下属安排在贝弗利山队做副队长，目的就是抓住菲丽斯的失误然后将她逐出军团。但让普仑敦失望的是，她的下属不但没有帮她找到什么有利的证据，反而和菲丽斯成为了好朋友，并和菲丽斯一起把贝弗利山队带入了童子军大赛。比赛正式开始，普仑敦亲自率领红羽毛队参赛，她为贝弗利山队设下障碍，却反而助贝弗利山队赢得了胜利。普仑敦因为作弊被童子军团开除，菲丽斯在和队员们庆祝胜利的宴会上看到了满面笑容向她走来的丈夫，她知道凭借自己的努力她赢回了已经破碎的婚姻，同时也赢得了他人的尊重。','When the going gets tough, the tough go shopping!',0,0,3.455018,5.6,56,105,'1989-03-22','en','/2HOzh7t2THdZ3r9BaDucEjfzLlL.jpg',2.7086333246772436,3,'2026-09-10',2,NULL,NULL),(22215,'谢利','Chéri','故事根据法国作家科莱特的小说改编。 上世纪20年代的法国巴黎，名妓皮萝丝（凯西·贝茨 Kathy Bates 饰）的儿子，一个年轻的富家子弟谢利（鲁伯特·弗兰德Rupert Friend 饰）爱上了妈妈的朋友——50岁的高级妓女莱娅（米歇尔·菲佛Michelle Pfeiffer 饰）。皮萝丝当初把儿子送到莱娅身边，只是为了利用这个情场老手教会儿子社交界的法则。她本以为，儿子会在莱娅身边成长为一个世故的花花公子，然后就会顺理成章地离开那个和自己一般岁数的女人，找个名门女眷晋身上流社会。 然而，对于这个教会他如何去爱的女人，谢利却爱得简直无法自拔。当皮萝丝发现事情的进展出乎她所料，便千方百计地强迫儿子放弃这段长达6年的感情。谢利在母亲的胁迫下终于妥协，但他始终无法忘记莱娅，甚至在终于迎娶豪门千金之后仍然如此。最终，谢利依然无法忘记这个教会自己如何去“爱”的人，最终选择了逃往一个幻想中的世界……',NULL,23000000,9366227,5.494047,5.9,56,86,'2009-02-10','en','/b35rv11ebJdqCe5chVmSUZ0RIlX.jpg',2.71971591255662,3,'2026-09-10',2,NULL,NULL),(22256,'永无止境','Without Limits','史蒂夫（比利·克鲁德普 Billy Crudup 饰）在跑步方面有着过人的天赋，许多教练想要将他收入麾下但却纷纷遭到了拒绝，因为，在心高气傲的史蒂夫心中，只有传奇田径教练比尔（唐纳德·萨瑟兰 Donald Sutherland 饰）有资格成为他的“师傅”，经历了一番波折之后，史蒂夫最终成为了比尔手下的得力战将。\r 　　经历了比尔别具一格的严格训练，史蒂夫获得了长足的进步。之后，他在校园里结识了名叫马瑞（莫妮卡·波特 Monica Potter 饰）的美丽女孩，两人双双坠入了爱河。一场竞争激烈的比赛中，初出茅庐的史蒂夫获得了第四名的好成绩，就在比尔和马瑞都在为他感到高兴的时候，史蒂夫却宣布要结束自己的职业生涯，因为他脆弱的自尊无法承受没能得到第一名的打击。','PRE. The way he competed. The way he lived his life.',25000000,777423,3.849873,6.2,19,117,'1998-09-11','en','/2HoKVqCzVOez7DEwHApc73bKobg.jpg',2.4937577136572506,3,'2026-09-10',2,NULL,NULL),(22267,'与魔鬼共骑','Ride with the Devil','美国南北战争时期，Jake Roedel（托比·马奎尔 Tobey Maguire 饰）是南方一个德国人的儿子，和他支持北方的父亲不同，他支持的是南方。他和好友Jack Bull Chiles（斯基特·乌尔里奇 Skeet Ulrich 饰）一起加入了南方的游击部队。他们又结识了George Clyde和George的之前的黑奴Daniel Holt（杰弗里·怀特 Jeffrey Wright 饰）。四人都在John Black的部队下效力。驻扎在山上的时候，村里的寡妇Sue Lee Shelley（珠儿 Jewel Kilcher 饰）和Jack Bull相爱了，在后来的战争中，Jack战死，而Jake则与部队里的一个叫Pitt（乔纳森·莱斯·梅耶斯 Jonathan Rhys Meyers 饰）的人产生了矛盾，Pitt更是开枪打伤了Jake和Holt。后来，Jake又娶了Sue，在他们去往另一个城市的路上，Jake和Holt又与Pitt相遇了......','In a No-man\'s Land between North and South, You didn\'t fight for the Blue or the Grey... You fought for your friends and family.',38000000,635096,5.516207,6.6,49,138,'1999-11-24','en','/pvCTHi1AIfpggTBEoipFZBMsRXf.jpg',2.7050833158185648,3,'2026-09-10',2,NULL,NULL),(22301,'地狱天使','Hell\'s Angels','第一次世界大战，两个兄弟从牛津大学应征入伍参加英国皇家空军参战，讲述两人如何面对战争和女友海伦……','Howard Hughes\' Thrilling Multi-Million Dollar Air Spectacle',3950000,8000000,8.484123,6.1,19,127,'1930-11-15','en','/vt6zF55B9WLzYENs6cuXy8J5o1X.jpg',2.5035806397616716,3,'2026-09-10',2,NULL,NULL),(22314,'陷得太深','In Too Deep','卧底警察准备深入辛辛那提的毒品交易组织机构。在俄亥俄州，一个自称为神的人物控制着一切。',NULL,7000000,14011454,2.772178,6.2,17,97,'1999-08-25','en','/mYteXffai9mmShyGCa4nPhfGCLQ.jpg',2.468348746832038,3,'2026-09-10',2,NULL,NULL),(22327,'Youth in Revolt','Youth in Revolt','Nick Twisp (Michael Cera), a teen with a taste for the finer things in life like Sinatra and Fellini, falls hopelessly in love with the beautiful, free-spirited Sheeni Saunders (Portia Doubleday) while on a family vacation.  But family, geography and jealous ex-lovers conspire to keep these two apart. Nick abandons his dull, predictable life and develops a rebellious alter ego: François.  With his ascot, his moustache and his cigarette, François will stop at nothing to be with Sheeni, and leads Nick on a path of destruction with unpredictable consequences..','Every \"Revolution\" Needs A Leader',18000000,0,13.462544,5.9,319,87,'2009-09-11','en','/7sd9UeCDCwqe1vIiv904r6cgPuH.jpg',3.0976832394661007,3,'2026-09-10',2,NULL,NULL),(22345,'天才宝贝','Baby Geniuses','艾莉娜博士发现婴儿在诞生时都是天才，直到两岁之后开始使用成人语，才丧生这种天赋。博士企图运用婴儿能量来统治世界，一场大人与两岁小孩之间斗智斗勇的战争开始了！','Think innocent. Think helpless. Think again. Naps are history.',12000000,36450736,4.580081,3.3,75,97,'1999-03-12','en','/7zvPhjHkz5YEMUMPyvANCR96RJA.jpg',2.705884139121729,3,'2026-09-10',2,NULL,NULL),(22479,'堪萨斯情仇','Kansas City','故事发生在1930年代，当时美国正值经济大萧条，人民精神萎靡不振，堪萨斯市里充满了赌博、卖淫等犯罪活动。欧哈拉的丈夫约翰尼是一个小混混，因为犯了事被当地老大西恩拘禁起来。欧哈拉为了解救丈夫，冒险绑架了当地一位政客的妻子卡洛琳，希望能借此逼迫其政客丈夫利用关系网，促使西恩释放约翰尼。结果在相处过程中，绑架者欧哈拉和被绑架者卡洛琳之间，反倒产生了一些微妙的感情变化。','Kansas City, 1934. Anything could happen here. One night it did.',18000000,0,5.380733,6.1,12,116,'1996-08-16','en','/deD8SAbQYGvzcpRr50HUb9uj8xJ.jpg',2.40298341415599,3,'2026-09-10',2,NULL,NULL),(22488,'爱的永恒欢乐','Love\'s Abiding Joy','Messie和welly展开了的新的生活，可爱的儿子和刚出生的女儿为他们带来了很多的快乐，父亲也从家中过来探望，一家和乐融融，可是不幸也随之而来，年幼的女儿kathy意外夭折，让Messie倍受打击，她的性格也发生巨大变化，他们一家再怎样面对以后的生活？寻回以前的快乐呢？',NULL,0,0,1.128559,5.8,12,87,'2006-10-06','en','/bnaJeSqEy4svDD0zaEdgoXtY4ug.jpg',2.391812000840406,3,'2026-09-10',2,NULL,NULL),(22530,'嗜血重生','Bled','塞依，是一个年轻的艺术家，她住在市中心的一个仓库，深入研究关于血液和欲望的课题。一个神秘的外国人，试图诱使她服用失忆药物，想迫使她成为吸血鬼的猎物。因为那吸血鬼需要她的新血液才得以重生','Every addiction has its price.',0,0,1.039149,3.8,4,95,'2008-01-01','en','/9pxm39gVHP8FDdLagyofsimnnhc.jpg',2.181852075407808,3,'2026-09-10',2,NULL,NULL),(22538,'歪小子斯科特对抗全世界','Scott Pilgrim vs. the World','Scott Pilgrim is a film adaptation of the critically acclaimed, award-winning series of graphic novels of the same name by Canadian cartoonist Bryan Lee O’Malley. Scott Pilgrim is a 23 year old Canadian slacker and wannabe rockstar who falls in love with an American delivery girl, Ramona V. Flowers, and must defeat her seven \"evil exes\" to be able to date her.','Get the hot girl. Defeat her evil exes. Hit love where it hurts.',60000000,47664559,38.885195,7.2,2126,112,'2010-07-27','en','/g5IoYeudx9XBEfwNL0fHvSckLBz.jpg',3.8294567618503583,3,'2026-09-10',2,NULL,NULL),(22556,'幸福的黄手帕','The Yellow Handkerchief','美国好莱坞一家电影公司翻拍上世纪70年代的日本电影名作《幸福的黄手帕》。日本电影大师山田洋次12日在新闻发布会上说，好莱坞要翻拍这部由他1977年导演的电影，让他“深受感动”。他希望美国版的《黄手帕》能够有力地传达影片的信息。山田洋次介绍说，美国版《黄手帕》将由尤达扬·普拉萨德执导，制片人由阿瑟·科恩担任。新影片将于3月在美国路易斯安那州开拍，预计2009年春可在日本上映。《幸福的黄手帕》改编自美国小说家皮特·哈米尔的作品，讲述了一名刚出狱的囚犯与一直在北海道等候着他的妻子的故事。日本演员高仓健在片中成功地塑造了获释囚犯的形象，该片当年曾在日本和中国等地掀起热潮。',NULL,15000000,317000,3.803495,6.4,52,102,'2008-12-17','en','/nYX4UmT6sIQFjPReliYFZ2IuGCj.jpg',2.71035292243068,3,'2026-09-10',2,NULL,NULL),(22597,'伤心俱乐部','The Broken Hearts Club: A Romantic Comedy','故事就从Dennis的生日开始，不能免俗的，在Dennis的家里开Party，朋友也邀请了一堆人来热闹，当然，他们这几个好朋友，和餐厅的老闆，都是当然的来宾，也各自带了朋友来。',NULL,1000000,1744858,3.424158,6.3,25,94,'2000-02-01','en','/g9bqbopRZYy5Z2137zFoFQRXVEW.jpg',2.550955898501835,3,'2026-09-10',2,NULL,NULL),(22600,'黑帮天堂：耶路撒冷','Jerusalema','上世纪九十年代，南非约翰内斯堡的Hillbrow区。拉奇·库内内（瑞普拉纳·赛斐默 Rapulana Seiphemo饰），一位来自南非身无分文的街头混混。出身于贫民窟的拉奇从小就目睹着南非人民遭受的苦难，便立志要逃离这样的窘困之境，改变这一切。于是他从街头的小偷小摸开始起家，在经历了无数的枪战、血腥和暴力之后，成长为约翰内斯堡地区的黑帮老大。然而此时的拉奇正一步步走向罪恶的深渊，他所创建的帝国、他所拥有的生活，终将倒塌。','Welcome to the promised land.',0,0,1.717376,6.8,16,120,'2008-02-11','en','/fVmlqgIyHjEsONDcaFiP8jBdqvU.jpg',2.4573618942753668,3,'2026-09-10',2,NULL,NULL),(22617,'五星级杀人夜','Dinner Rush','纽约某五星级意大利餐厅，为什么今晚份外满座？食客蜂拥，难道只为一尝老板独子兼天才大厨几道创新菜式？两个要求瓜分餐厅利润的黑帮、与大厨上过床的女食评人、刻薄又多话的美术馆馆主、多疑的警察夫妇、爱坐吧台的西装男人──个个互不相识，却统统不请自来，谁主谁客再已分不清。当晚宴接近尾声，一切味美佳肴，一切争端瓜葛，已被杀意悄悄盖过 。',NULL,0,0,1.096355,7.1,19,99,'2000-09-01','en','/6qhSssp1RT3IU53OkomdpJsyJ0D.jpg',2.4943316522284413,3,'2026-09-10',2,NULL,NULL),(22649,'告别武器','A Farewell to Arms','亨利（加里·库柏 Gary Cooper 饰）是一位热血沸腾的青年，战争爆发了，他自愿前往意大利，成为了一名救护车驾驶员。在意大利，亨利结识了名为凯瑟琳（海伦·海丝 Helen Hayes 饰）的美丽护士，之后，亨利因为受伤被送进了米兰医院，在那里，他和凯瑟琳重逢了。\r 　　住院期间，亨利和凯瑟琳坠入了情网，凯瑟琳的腹中亦怀上了亨利的骨肉。伤愈之后，亨利回到了战场，却发现我军的士气大跌，处处弥漫着惨淡的气氛。上司开始大量处决涉嫌逃跑的士兵，亨利亦难以幸免，他侥幸逃脱了自己人的枪子，他决定找到凯瑟琳，两人逃离战场，去过他们与世无争的日子。然而，意大利警察的追捕紧随其后，两人踏上了逃亡的旅途。','Every woman who has loved will understand',4,25,1.199451,6.2,28,89,'1932-12-08','en','/eNmPByGZJqlp60nCZRhsAlVAb3F.jpg',2.5686916366806067,3,'2026-09-10',2,NULL,NULL),(22787,'Whiteout','Whiteout','The only U.S. Marshal assigned to Antarctica, Carrie Stetko will soon leave the harsh environment behind for good – in three days, the sun will set and the Amundsen-Scott Research Station will shut down for the long winter. When a body is discovered out on the open ice, Carrie\'s investigation into the continent\'s first homicide plunges her deep into a mystery that may cost her her own life.','See Your Last Breath',40000000,12206028,14.818718,5.3,220,101,'2009-09-09','en','/90ydDtRDWQ8K9LaFwVw6LyC9cgT.jpg',2.9832790909111027,3,'2026-09-10',2,NULL,NULL),(22794,'天降美食','Cloudy with a Chance of Meatballs','在不久的将来，地球上的居民日益增多，而吃饭问题就成了全球面临的当务之急。从小就热爱发明，折腾出各种稀奇古怪东西的科学家弗林特·洛克伍德 最近一直在致力于解决这个问题，不过他的研究途径可和其他科学家不那么一样，他认为要解决所有人类的吃饭问题，有一个办法是最有效的：让食物像雨雪一样，直接从天上落下来，送到每家每户的门口！当然，对于这么无稽的事情，弗林特没少遭到白眼和嘲笑，大家都以为他疯了。但是弗林特总是觉得，自己的这个念头很靠谱，于是，他孜孜不倦的研究着如何让美食从天而降。眼瞅着过去勤奋上进的科学家变成现在这个偏执狂，他的好朋友，美艳傲慢又颇具智慧的小镇天气预报员萨姆·斯帕克斯 也感到相当头疼，她总是希望帮助弗林特摆脱掉这么不切实际的念头。不过，谁都没有想到，弗林特居然成功了！彩色的云朵载着无数美食飞来--肉丸子、烤乳猪、汉堡、意大利面、冰激凌还有更多数也数不过来的美食。斯帕克斯终于明白了，弗林特做的事并不是天方夜谭，而她也加入了弗林特的美食计划当中。不过，事情渐渐的开始失控，因为美食不停地掉下来，不但吃不完，连大家出行都有了困难，弗林特必须想办法让这件大好事不至于变成一桩灾难……','Prepare to get served.',100000000,242988466,46.781182,6.5,1747,90,'2009-09-17','en','/iBX9zxuVLr0IeTajOH3T7jRs8zk.jpg',3.6439294637875363,3,'2026-09-10',2,NULL,NULL),(22796,'一路上有你','Simon Birch','在所有人的眼里，西蒙（Ian Michael Smith 饰）是一个奇迹，刚刚出生的只有拳头一般大的他当即被医生判了死刑，可捏着这张死亡通知单，西蒙神奇的从嗷嗷待哺的婴孩成长为了12岁的少年。虽然西蒙矮小的身材常常遭到周遭伙伴的歧视和嘲笑，但他依然保有了一颗善良和真诚的内心。  　　作为西蒙的好友，乔（约瑟夫·梅泽罗 Joseph Mazzello 饰）有一个一直困扰着他的烦恼，成长于单亲家庭的他十分渴望能够得知父亲的下落。一次可怕的意外让乔永远的失去了母亲，而这整件事的始作俑者竟然是西蒙。怀着对乔的内疚，西蒙决定带着乔，踏上了寻找父亲的旅程，同时，西蒙坚强又脆弱的生命也渐渐的走向了尽头。','Destiny has big plans for little Simon Birch.',20000000,18253415,11.090254,6.5,52,114,'1998-09-11','en','/vRJcV9l3tLFoUWZel9RikS3nfJ6.jpg',2.728996210973204,3,'2026-09-10',2,NULL,NULL),(22798,'滑轮女孩','Whip It','在德州名叫伯顿的普通小镇里，生活着一个并不开心的少女布里丝·卡文德（艾伦·佩姬 Ellen Page 饰）。她迷恋摇滚乐，对人生有着别样的憧憬，但却常被母亲布鲁克（玛西亚·盖·哈登 Marcia Gay Harden 饰）打扮成乖乖女，参加镇上举行的各种选美比赛，这令她倍感乏味。某个夜晚，布里丝和好友佩希（阿莉雅·肖卡特 Alia Shawkat 饰）去临镇奥斯汀观看了全由女子参加的轮滑对抗赛，女孩们的飒爽英姿和出色表现令布里丝倾倒，于是她决定学习轮滑。布里丝瞒着父母，偷偷加入奥斯汀的胡安童子军轮滑队，在紧张激烈的训练和对抗中，布里丝结识了不少好朋友，同时也找到久违的乐趣……','Be Your Own Hero',15000000,16633035,20.05902,6.7,357,111,'2009-09-13','en','/nrFuiM2ZIXTDhRuhDaJXYmV9iYc.jpg',3.2145009374703832,3,'2026-09-10',2,NULL,NULL),(22803,'守法公民','Law Abiding Citizen','影片的主人公曾是一名治安警员，他认为由于有黑幕的交易，使得杀害他的妻子和女儿的其中一名谋杀者将被释放，所以他准备策划一次复仇，惩治那些谋杀者和幕后审判交易人；而负责这起案件的地方法院检察官 也卷入这次复仇阴谋的漩涡之中，他察觉秘密复仇的计划后，试图捍卫法律体制。克莱德·谢尔顿 是费城一名正直不阿的警员，拥有美满家庭的他却不想遭遇了人生的重大打击：妻子和女儿在家里被歹徒入侵，随后残酷的被杀害。凶手很快被抓捕归案，风头正盛的主控官尼克·赖斯 接下了这起案件，然而他的上司却要尼克按照他的意思处理这起案件，所有罪名都扛在了一个小角色身上，明摆着的真凶却得意的逍遥法外。 面对这个事实，谢尔顿明白腐败的司法系统已经无法为他伸张正义，深知幕后存在肮脏交易的谢尔顿决定按照自己的方式来处理警察无法做的事。在费城，一起又一起暗杀发了，所有的线索都指向谢尔顿，尼克明白，现在只有他才能阻止谢尔顿的疯狂行为，同时将真正的幕后黑手揪出来……','The System Must Pay.',53000000,126690726,49.593978,7.2,1486,109,'2009-10-15','en','/fcEXcip7v0O1ndV4VUdFqJSqbOg.jpg',3.752129561775159,3,'2026-09-10',2,NULL,NULL),(22804,'电锯惊魂6','Saw VI','对于民众而言，随着“竖锯”（托宾·贝尔饰）与亚曼达（肖妮·史密斯饰）的死亡，也许这个耸人听闻的事件可以就此画上句号。不过，虽然竖锯已死，但霍夫曼（考斯塔斯·曼迪特饰）屡次从那些竖锯安排的死亡陷井里不可思议的全身而退，这一点也足够引起FBI的警觉。传承了竖锯和亚曼达衣钵的霍夫曼知晓FBI 对自己的怀疑，他决定要按照竖锯的理念将这场用生命做赌注的游戏进行下去，同时也要用某种方式消除FBI对自己的怀疑。又一群受害者在失去知觉之后，带到了一个炼狱当中。这次霍夫曼依据竖锯留下的资料，设计出6种游戏来让受害者抉择，其中最残酷的一项则是让一个人决定六个人生死的轮盘游戏“喧闹酒会”。此外，霍夫曼还专门为一位叫黛比（卡洛琳·德芙饰）的女人和一个年轻小伙布兰特（戴文·博斯蒂克饰）准备了两个特别的游戏。这样做的原因很简单：在两人身上，隐藏着一个关于竖锯的重要秘密。霍夫曼并不仅仅只满足于竖锯定下的游戏规则，他要进一步以他的理念完善整个游戏。','The Game Has Come Full Circle',11000000,68233629,31.900899,6,722,90,'2009-10-22','en','/x7cHq8AlfPVJjkpfytoiGiu7TMz.jpg',3.3194031580427295,3,'2026-09-10',2,NULL,NULL),(22805,'Motherhood','Motherhood','Motherhood is a comedy written and directed by Katherine Dieckmann, and stars Uma Thurman, Anthony Edwards and Minnie Driver. Shot on location in New York’s West Village, focuses on the dilemmas of motherhood, such as marriage, work, and self, shown in the trials and tribulations of one pivotal day.',NULL,0,0,10.955567,4.7,44,90,'2009-01-21','en','/bzQCsmvPJU0L4tnPtQHlVliw2zn.jpg',2.6612733705214486,3,'2026-09-10',2,NULL,NULL),(22820,'绅士布朗科','Gentlemen Broncos','《绅士布朗科》承袭了杰瑞德·赫斯作品一贯神经质的“闷蛋”喜剧路线，不过加入了对于7、80年代经典科幻片——包括《星舰迷航》、卢卡斯的《五百年后》等片的戏仿，让电影更多了些怪调调。故事讲述了迈克尔·安格拉诺饰演的高中生本杰明参加了一个科幻/奇幻作家培训夏令营，却不成想自己的辛辛苦苦写出来的故事，被夏令营的导师、世界上最出名的科幻作家罗纳德·舍瓦里给偷了去。而山姆·洛克威尔出演的就是本杰明故事中男主角——他穿着廉价的银色紧身衣、骑着机器驯鹿和独眼怪人作战的场面，真是太有趣了。','Oinus, Ainous, Anous, Odious.',10000000,0,3.193777,6.2,51,89,'2009-09-30','en','/eRnUC60trqoRZuAtM8M3gOFT6ED.jpg',2.700794753730646,3,'2026-09-10',2,NULL,NULL),(22821,'处刑人2','The Boondock Saints II: All Saints Day','波士顿，一位深受爱戴的牧师神秘被杀，子弹交错穿过脑壳，死相极为惨烈，传言处刑人所为。负责此案的依旧是警察格林利、达菲和多利，但他们对此一筹莫展。幸有智慧性感的FBI特工尤妮斯・布鲁姆（朱莉•本茨 Julie Benz 饰）破解了处刑人的杀人手法。因10年前波士顿血案，异卵双生兄弟康纳（肖恩•派特里克•弗兰纳里 Sean Patrick Flanery 饰）和墨菲（诺曼•瑞杜斯 Norman Reedus 饰），随领袖父亲诺亚（比利•康诺利 Billy Connolly 饰）隐居在爱尔兰的乡村。此案一出，两兄弟削发明志，重新出山。期间，他们收服了墨西哥人罗密欧（小克利夫顿•克林斯 Clifton Collins Jr. 饰）。后者凭借机灵的头脑、出众的拳脚，战胜了人高马大的对手。虽然将对手置于死地有些残酷，但是兄弟俩觉得对味，并设计拉他入伙。这组搭档与美女特工都踏上征讨处刑人的危险之旅……','The Saints Are Calling',8000000,10629321,13.517017,5.9,261,118,'2009-11-24','en','/htOFPFA29hVkI3JSiCU3tt2YpAu.jpg',3.056983520863421,3,'2026-09-10',2,NULL,NULL),(22824,'第四类接触','The Fourth Kind','美国阿拉斯加德诺曼小镇，在过去的几十年里当地不断发生离奇事件。许多人神秘失踪，还有很多人被严重的失眠所困扰，自杀案件居高不下。单身母亲阿比盖尔•泰勒（米拉·乔沃维奇 Milla Jovovich 饰）当年曾经历一场诡异的灾难，在那场灾难中，睡在身边的丈夫神秘死亡。在此之后，阿比盖尔开始研究催眠。当得知诺曼镇发生的事情时，她直觉这与自己的经历有很大关系。经过对几名当事人的催眠，阿比盖尔得知他们都有着遭遇莫名生物的经历，在此期间，她更目睹了当事人杀害全家并自杀的悲惨场面。随着调查的深入，真相渐渐浮出水面，然而最为恐怖的事情也随之发生…… 本片据传由真实事件改编。','There are four kinds of alien encounters. The fourth kind is abduction.',10000000,42333295,22.888173,5.8,441,98,'2009-11-06','en','/kEUeAf1U5mhnAE3V2dN42FRffy3.jpg',3.173408647719831,3,'2026-09-10',2,NULL,NULL),(22825,'魔盒','The Box','1976年，美国弗吉尼亚州。担当中学教员的诺玛（卡梅隆·迪亚茨 Cameron Diaz 饰）和在NASA供职的丈夫亚瑟（詹姆斯·麦斯登 James Marsden 饰）过着幸福的生活，他们的事业小有成就，衣食无忧，唯一的不足则是儿子沃尔特（Sam Oz Stone 饰）身染重病，健康每况愈下。随着岁月的流逝，儿子的病情不断加重，夫妇俩渐渐无法负担这巨额的医疗费用。某个早晨，一辆神秘的黑色轿车在诺玛家的门口留下一个带有红色按钮的盒子。不久，一名脸上留着恐怖伤疤的男人拜访了诺玛。他声称这是一个能为所有者带来幸福的盒子，每按一次，便有巨大的财富入账，与之对应世上就会有某人死去。一方是儿子的巨额医疗费，一方是无辜者的性命，诺玛夫妇将会怎样选择？','All you have to do is push the button.',30000000,33333531,21.606001,5.4,597,115,'2009-09-17','en','/ppySXFdkdoo6jYhxhfD0wvxK2dl.jpg',3.175193529823732,3,'2026-09-10',2,NULL,NULL),(22832,'忍者刺客','Ninja Assassin','数千年来，来自东方的忍者刺客只是被当作一个传说，然而柏林的法院调查员米卡（娜奥米·哈里斯 Naomie Harris 饰）在调查一系列政治暗杀案时却把目标锁定在这个传说中古老而又成熟暗杀组织。通过秘密调查，米卡得知一个叫奥祖奴的暗杀集团，而且在一盘监控录像里，米卡看到一张年轻的东方面孔，这个人叫雷藏（Rain 饰）。雪藏年幼时即被奥祖奴的暗杀集团收养，并且把他训练为一个出色的忍者刺客。然而善良的雪藏并未在兽化的训练中泯灭良知，最终因厌倦杀戮而逃离集团，并且隐居于柏林。此时，米卡已成为暗杀集团的追杀对象，在危急关头，雷藏及时出现救下米卡。雪藏希望得到米卡的帮助，从而彻底摧毁奥祖奴……  　　本片由曾执导《V字仇杀队》的导演詹姆斯·麦克提格（James McTeigue）担当导演，亚洲人气小天王Rain主演，这是他在打入好莱坞之后的第二部作品。','Fear not the weapon, but the hand that wields it.',40000000,60462347,19.085403,6.2,371,99,'2009-09-29','en','/cg9v9m0lV2jrJOOoBRzqJJ9ZyQM.jpg',3.1714957391554734,3,'2026-09-10',2,NULL,NULL),(22881,'弱点','The Blind Side','窗明几净、精致餐点、其乐融融，对于住在田纳西州的图伊一家，这样温馨的生活仿佛是与生俱来的事情。妻子莉安 温柔贤惠，丈夫西恩 事业有成，还有一双听话乖巧的儿女，更在杯觥交错中深受上流社会欢迎。如果不是那天下午的意外，如果不是莉安心思细腻，他们或许还是像原来一样活在自己完美无缺的世界中。 那是一个高大壮硕、皮肤黝黑的孩子，面无表情的脸上，掩不住些许苦愁的滋味。明明天气阴冷，他却穿着单薄的T恤和短裤，在寒风中瑟瑟发抖。不管他看起来高大得多么让人戒备，他只是个16岁的孩子，和自己儿子同校的孩子。更别提这个名叫迈克尔·奥赫 的孩子从小就成了孤儿，辗转于无数收养家庭之间，在9年里上过11个学校，连小学一年级也能留级一年！莉安又有什么理由不收留他呢？从领进家门暂住一宿到提供衣食住所视为己出，甚至专门为他请来了私人家教苏小姐，奥赫第一次从图伊一家身上感觉到了家的温暖。 除了无微不至的照顾，因为图伊夫妇的鼓励，奥赫决定善用自己的天赋，加入学校的橄榄球队。在赛场上，他就像一堵铜墙铁壁，没人能够突破他的防线。很快，奥赫就成为了橄榄球场上的风云人物，不仅为所在的中学赢得了区域冠军，还吸引了众多大学球队星探的注意，愿意为他提供全额奖学金。可是，对于平均成绩只有0.9分，IQ仅在低智边缘的奥赫，要想顺利踏上橄榄球之路，眼前还横亘着诸多障碍……','Based on the extraordinary true story',29000000,309208309,25.767395,7.2,1597,129,'2009-11-20','en','/PhpAdRopu0sOWf0BY7vVtxrRD3.jpg',3.7184600198609328,3,'2026-09-10',2,NULL,NULL),(22894,'基督再临','Legion','若干年后，人类世界即将成为生灵涂炭的战场，上帝对被无休止的欲望和破坏欲所浸淫的人类失去信心，因此上帝决定再度对人类施行审判，因此他派遣加百利（凯文·杜兰饰）率领天使军团对人类进行灭绝行动。不过对于这起即将降临于人类社会的浩劫，天使中也有一位名为迈克尔（保罗·贝坦尼饰）的天使长对人类深感同情，他决定要以某种方式来保护人类。 　　美国一处僻静的小镇，成为了天使军团的前哨站。这里的一间小酒馆里，有一位身怀六甲的女招待克莱尔（阿德琳妮·帕里奇饰），还有一位终日和酒精为伍的老头子鲍勃（丹尼斯·奎德饰）。使命降临在了他们的身上，克莱尔尚未出生的孩子，将彻底改变整个世界的命运…','When the last angel falls, the fight for mankind begins.',26000000,67918658,30.981604,5.2,629,100,'2010-01-21','en','/69G64XnGbkNCodXGhAyskQQsy51.jpg',3.1773566864553326,3,'2026-09-10',2,NULL,NULL),(22897,'It\'s Complicated','It\'s Complicated','Ten years after their divorce, Jane and Jake Adler unite for their son\'s college graduation and unexpectedly end up sleeping together. But Jake is married, and Jane is embarking on a new romance with her architect. Now, she has to sort out her life – just when she thought she had it all figured out.','First comes marriage. Then comes divorce. And then...',85000000,219103655,16.479851,6.2,360,121,'2009-12-23','en','/80r3BluBjH32xrxDi6A1sAr8g8a.jpg',3.15885072477568,3,'2026-09-10',2,NULL,NULL),(22907,'银行匪帮','Takers','戈登等五人组成的银行抢劫团伙每隔一年作案一次，其成员AJ、约翰各有所长，抢劫所得和合理的投资令他们过着奢华的生活。在最近的一次劫案中，他们引起了铁腕警探杰克的注意。戈登团伙昔日的成员里弗斯新近出狱，里弗斯在狱中结识了俄罗斯黑帮，并取得一份银行的内线情报。里弗斯邀请众人行劫，否则就拿回当年属于自己的那份抢劫所得，尽管时间仓促，不符合团伙一贯的行事风格，然而一番讨论之下，他们决定再次出手。与此同时，杰克以抢劫所用的C4炸药为突破口，发现了这次有俄罗斯黑帮参与的抢劫计划图纸。距离计划时间所剩无几，这次抢劫会导致怎样的结局？','Who\'s Taking Who?',32000000,69055695,18.47242,6,394,107,'2010-08-26','en','/mTymtkJU4LrMlyVGvzykNNooUL8.jpg',3.1624171474662344,3,'2026-09-10',2,NULL,NULL),(22908,'罗密欧·布拉斯的房间','A Room for Romeo Brass','Two twelve-year-old boys, Romeo and Gavin, undergo an extraordinary test of character and friendship when Morell, a naive but eccentric and dangerous stranger, comes between them. Morell befriends with the two boys and later asks them to help him pursue Romeo\'s beautiful elder sister. He gradually becomes more violent after she rejects him.',NULL,0,0,1.391958,7.3,18,90,'1999-08-23','en','/gLpv2UUf5We4sXDKdo11aFfnKgw.jpg',2.484928799126355,3,'2026-09-10',2,NULL,NULL),(22913,'24 7: Twenty Four Seven','24 7: Twenty Four Seven','In a typical English working-class town, the juveniles have nothing more to do than hang around in gangs. One day, Alan Darcy, a highly motivated man with the same kind of youth experience, starts trying to get the young people off the street and into doing something they can believe in: Boxing. Darcy opens a boxing club, aiming to bring the rival gangs together.',NULL,0,0,0.744406,6.3,10,96,'1997-08-31','en','/g5rd7ljbR0VVcK7m2ogrMa4E0fE.jpg',2.356940410014864,3,'2026-09-10',2,NULL,NULL),(22947,'在云端','Up in the Air','瑞恩·宾厄姆是一名企业裁员专家，他钟爱的空中飞人生活正面临威胁——此刻他即将积累满一千万常旅客里程，同时也遇见了那位梦中同样是空中飞人的女性。[派拉蒙影业]','The story of a man ready to make a connection.',25000000,163670000,33.704181,6.7,1205,109,'2009-09-05','en','/cPiNDELuuquoVfnLwpAfhonUTvA.jpg',3.5612696939732245,3,'2026-09-10',2,NULL,NULL),(22949,'老家伙','Old Dogs','查理（约翰·特拉沃塔 John Travolta 饰）和丹（罗宾·威廉斯 Robin Williams 饰）不仅是相处多年的老友，还是合作无间的工作伙伴，一起经历了这么多年的风风雨雨，两人之间的友谊真挚诚恳牢不可破。  　　前妻的突然出现打破了丹平静的生活，因为她带来了两个小鬼头并告诉丹他们是他的孩子。对于这两个小孩，一向糊里糊涂的丹根本就闻所未闻，也无法确定，他们是否真的和自己血脉相通，在混乱之中，两个孩子就这样进入了丹的生活。对照顾孩子毫无经验的丹请来了查理充当“军师”，两个男人、两个孩子和一条狗，会有怎样妙趣横生的故事发生在这个奇特的“大家庭”之中呢？','Life is Not Child-Proof.',35000000,92219310,13.707843,5.2,210,88,'2009-11-24','en','/h0virQlY6gGsF7heQjYhBzRjkTF.jpg',2.9659685705082186,3,'2026-09-10',2,NULL,NULL),(22954,'成事在人','Invictus','刚刚结束牢狱之灾的纳尔逊•曼德拉（摩根•弗里曼 Morgan Freeman 饰），竞选南非总统成功。他领导人们破除种族隔离制度，并身先士卒，雇佣白人护卫队，在各方面建立不同肤色的沟通。作为1995年橄榄球世界杯的东道主，南非重回国际体育大家庭。不过，南非的英式橄榄球队——队员均为白人的跳羚队，却被很多黑人看做种族歧视的代名词。为了破除隔膜，曼德拉高瞻远瞩，支持跳羚队与国外来访球队的交流比赛。他接见了跳羚队队长皮耶那（马特•达蒙 Matt Damon 饰），两人进行了推心置腹的交谈。后者带领着白人球员走访了南非各地，把橄榄球运动普及给普通民众，让这项运动成为了黑白联合的纽带……\r 　　本片根据约翰•卡林的作品《与敌人战斗：纳尔逊曼德拉和一场改变国家的比赛》（Playing the Enemy：Nelson Mandela and the Game That Made a Nation）改编。','His people needed a leader. He gave them a champion.',60000000,122233971,23.85119,7,1125,134,'2009-12-10','en','/AlKaUfLVxvMrGMgsJ097jt97wCX.jpg',3.5756218535112705,3,'2026-09-10',2,NULL,NULL),(22970,'林中小屋','The Cabin in the Woods','一群喧闹的大学生来到了人迹罕至的小树林里，这五个朋友准备在这里度过一个放纵、开心、难忘的周末。根据指示，他们找到了位于树林深处的一个小木屋，准备在这里开始自己的派对。一开始，一切都很正常，但是到了晚上，这个小木屋里却接连出现了各种各样奇怪的超自然的以及无法解释的事情。而这五个大学生的性命也处在了危难之中--因为他们根本不知道自己面对的是什么，而这些背后还有一个多么庞大的组织在监视这这一切……','If you hear a strange sound outside... have sex',30000000,66486080,73.987775,6.5,2263,95,'2012-04-12','en','/zZZe5wn0udlhMtdlDjN4NB72R6e.jpg',3.768141196134864,3,'2026-09-10',2,NULL,NULL),(22971,'分手信','Dear John','美国陆军特种部队的约翰（钱宁·塔图姆 Channing Tatum 饰）在家乡渡假时意外结识渡假的女学生莎文娜（阿曼达·塞弗里德 Amanda Seyfried 饰），两人很快便深陷爱河。约翰成年后和自己的醉心于收集硬币的父亲鲜有交流，莎文娜却对约翰的父亲十分友善。两人的假期很快结束，分别时约翰承诺莎文娜自己的服役期一年后便结束，之后两人便再也不分离。海外驻军常常扎营在一些偏远的地区，约翰只能通过信件和莎文娜互诉衷肠，在那些充满浓情蜜意的文字间二人都憧憬着日后可以长相厮守。911事件爆发，面对约翰不得不延长的服役期，俩人的感情出现危机，不过很快便重归于好。约翰回到部队很久都没有收到莎文娜的来信，日思夜盼等来的却是莎文娜分手信。在失恋的怆痛未弥合之时，约翰不幸负伤，在昏迷的前一刻，约翰居然想到的是父亲收集的那些硬币。几年后，当约翰再一次见到莎文娜时，发现了那封分手信背后的秘密……','Love brought them together. Will fate tear them apart?',25000000,114977104,19.402816,6.6,1262,115,'2010-02-04','en','/qTn2uUIDwhH9SDmFptaEeIVy4g5.jpg',3.521510810379527,3,'2026-09-10',2,NULL,NULL),(22972,'绿区','Green Zone','2003年，伊拉克战争爆发。萨达姆政府受到重创，大规模杀伤性武器（WMD）成为美国出兵伊拉克的有力借口。罗伊·米勒所率领的小分队奉命在伊拉克境内寻找WMD，然而无数次的搜寻皆无所获，这令米勒对线报的来源心生疑惑。某次行动中，他遇到当地的独腿男子法哈迪，从对方口中米勒得知一众伊拉克关键人物正在某地集会，行动中意外发现扑克牌通缉令上的艾尔·拉威也在其中，而艾尔·拉威似乎和美国政府有着错综复杂的关系。米勒不顾劝阻展开独立调查，发现所谓的WMD不过是包藏了无数丑恶真相的谎言而已……','Chief Warrant Officer Roy Miller is done following orders',100000000,94882889,30.254021,6.4,717,115,'2010-03-11','en','/rdIsV1cBnFw2abOxbzBFTeUaWkv.jpg',3.3737186503421075,3,'2026-09-10',2,NULL,NULL),(23048,'热浴盆时光机','Hot Tub Time Machine','约翰·库萨克、克雷格·罗宾逊、罗伯·考德瑞和克拉克·杜克四位兄弟生活无聊，于是来到滑雪胜地度个小假、疯狂一把。不想，泡了一晚上热水澡就发现自己回到了80年代（克雷格·罗宾逊拉住路人问，迈克尔·杰克逊是啥颜色的？路人答曰，黑色）。本片的神奇元素也差不多就这么些了，几个穿越回过去的男人是如何在混乱中成长的才是电影主题。不过，既然是科幻片，片中主角难免也会遭遇一些科幻问题。比如克拉克·杜克就遇到了最尴尬的“祖父悖论”，他遇到了自己的母亲，然后发现自己的美女母亲被四兄弟中最猥琐那个给上了，并且怀了孕……正准备求婚却被女友甩了，遭遇人生如此大劫的亚当准备找自己的死党去滑雪胜地度假散散心，却没想到几个朋友也是麻烦事多多：卢喜欢每天都在各种不同的派对里消磨时光，他却既找不到好的派对地方也找不齐派对参加的人；尼克是个气管炎，不管走到哪都总是被老婆监管着一举一动；雅各布更是宅得不行，一把年纪还整天沉迷在电子游戏里。看着这些生活一团乱麻的死党，亚当觉得人到中年的自己，活得真是糟透了。在度假的地方，四人发现了一个露天的温泉浴盆，可这浴盆看起来总是有些古古怪怪，四人抱着试一试的心态泡到里面，喝得个酩酊大醉，接着神奇的事情发生了——他们竟然从2010年穿越到1986年！好家伙，这下亚当觉得改变自己人生的机会到了，他要借助这次奇妙的穿梭来修正他在过去所犯的种种错误。不过亚当可没法控制自己其他几个朋友的行为，他们都在过去的时光玩得要多疯狂有多疯狂。很快，他们就意识到这样下去，未来将会变得混乱不堪，因此几个人又开始想方设法的收拾这场烂摊子……四个由小玩到大的猪朋狗友：亚当、卢、尼克、雅各布，人到中年各自出现危机，失恋！失意！失去男性尊严！他们决定重游旧地，寻回久违了的轻狂岁月，怎料一夜喝酒玩High了，神奇按摩浴缸竟然载他们回到1986年……他们会像当年一样尽情玩乐，还是藉此机缘扭转未来，重设自己的人生……','Kick some past',36000000,64572262,33.926473,6,894,101,'2010-03-26','en','/dOOFJSMPkuGunOVMa9WaCUvRw8p.jpg',3.368573698311131,3,'2026-09-10',2,NULL,NULL),(23049,'我的废墟生活','My Life in Ruins','乔治娅（妮娅•瓦达拉斯 Nia Vardalos饰）是一位希腊裔美国人，是一位导游，常年带着游客在希腊的名胜古迹间穿行。日复一日的重复着旅行介绍，经过的地方也走过太多遍，还有来自不同文化背景的游客们，这一切都让乔治娅头疼不已。于是，乔治娅萌生了辞职的冲动，想彻底离开眼前的生活。无奈，老板还是把一个新旅游团交给了乔治娅，起初一切如她原来经历的没有什么不同，直至一名旅客厄夫（理查德•德莱福斯 Richard Dreyfuss 饰）的出现，这个形貌普通的人却总是快乐自在的生活。乔治娅慢慢被感染，开始换一种眼光去看自己的工作和生活，不仅重拾工作的乐趣，并注意到那个一直在他身边默默无闻的司机波皮（亚历克西斯•乔奇奥里斯 Alexis Georgoulis饰），一切悄然发生变化……','The most fun you can have without a passport.',17000000,20455276,5.787891,5.6,101,95,'2009-02-06','en','/f695mVyU0LyBb99rx7zkrtFcpxR.jpg',2.832577023386168,3,'2026-09-10',2,NULL,NULL),(23069,'狗侦探','Benji','A stray dog saves two kidnapped children.',NULL,0,0,2.651418,6.1,35,86,'1974-10-17','en','/aSowNmq4bZrmfazhQBePyNF8A2E.jpg',2.6178165900678154,3,'2026-09-10',2,NULL,NULL),(23082,'谎言的诞生','The Invention of Lying','这部喜剧片讲述在一个幻想的世界里，谎言这种概念根本不存在，而某天男主角发明了谎言这种东西，并得到意想不到的收获。　　曾经有过这样一个世界：里面的所有人类如同我们一样正常生活、工作、恋爱，但是……他们却完全不会一样我们已经技巧纯熟信手捏来的东西：撒谎。是的，这个世界里不存在谎言，大家根本不知道撒谎为何物。从政客到广告商再到街头的男男女女，他们的人生中说的每一句话都是发自内心的真话。但是有一天，这种情况发生了一丝略微的改变：一个走投无路，穷困潦倒的年轻人马克（瑞奇·热维斯饰）为了生计撒了一个谎，这个谎也是这个世界里的第一个谎。马克发现这个谎言给自己带来了不少好处，于是他开始接二连三的撒谎，在这个只说真话的世界里，马克一个又一个的谎言给自己带来了不少名利，事业也开始腾飞。　　不过在这个真话占据绝对主流的世界里，马克的谎言说得越多，他就越发现事情开始变得不受自己控制，因为自己说的谎言，通常都会被人们奉为真理，而人们按照他的谎言去做事，则只会让事情变得更糟。同时，马克深深地明白一点，有一样东西是马克撒再多的谎也无法得到的，那就是自己深爱着的女人——珍妮弗（珍妮弗·加纳饰）的心。马克必须要从谎言中抽身出来，真心真意的对珍妮弗表白，才有可能获得成功……','In a world where everyone can only tell the truth... This guy can lie.',18500000,31912793,16.665841,6,518,100,'2009-09-13','en','/clP8tDZeM9jgnqmu4VBClBDpLtS.jpg',3.2153946115506646,3,'2026-09-10',2,NULL,NULL),(23168,'The Town','The Town','Doug MacRay is a longtime thief, who, smarter than the rest of his crew, is looking for his chance to exit the game. When a bank job leads to the group kidnapping an attractive branch manager, he takes on the role of monitoring her – but their burgeoning relationship threatens to unveil the identities of Doug and his crew to the FBI Agent who is on their case.','Welcome to the bank robbery capital of America.',37000000,154026136,24.218358,7,1468,125,'2010-09-15','en','/zEbWFJhY3OdVfdra2QynHC7ENFn.jpg',3.650541231289235,3,'2026-09-10',2,NULL,NULL),(23169,'记住我','Remember Me','21岁的泰勒（罗伯特·帕丁森 Robert Pattinson 饰）十分的叛逆，与舍友挤在一幢狭小的公寓里，整日沉溺于书籍和尼古丁之中，脾气暴躁甚至因斗殴而被警察拘留。面对自己成功的企业家父亲查尔斯（皮尔斯·布鲁斯南 Pierce Brosnan 饰），泰勒充满了抵触，并且把哥哥的自杀和妹妹早熟的性格全部归咎于父亲对他们的疏忽。泰勒和艾丽（艾米莉·德瑞文 Emilie de Ravin 饰）的交往始于一场斗殴事件，泰勒因斗殴而被一名警察（克里斯·库珀 Chris Cooper 饰）拘留，几天后，泰勒的室友发现那名警察的女儿艾丽居然和他们在同一所学校。在室友的怂恿下，泰勒和艾丽开始了交往。　　面对生活中的种种不幸，泰勒选择了用对抗去保护自己，而与他有着类似不幸遭遇的艾丽却用乐观豁达的态度去享受生活……','Live in the moments.',20000000,0,36.764666,6.9,948,113,'2010-03-12','en','/6oULJpTBo0rXzfl3e3D0yPEqS68.jpg',3.539971272125178,3,'2026-09-10',2,NULL,NULL),(23172,'邻家特工','The Spy Next Door','鲍伯（成龙饰）是一个秘密特工，身手矫健的他曾经为CIA（美国中央情报局）立下了汗马功劳。他曾经单枪匹马闯进匪巢，直  取匪首的脑袋；他曾经阻止恐怖分子在纽约安放炸弹；他还曾经截堵住毒贩、逮到过通缉犯。在CIA高层的眼中，鲍伯是一个上天下地，无所不能的超级特工。\r 当鲍伯没有任务的时候，他会带起傻乎乎的黑框眼镜回到家中，过上普通人的生活。他现在准备退休了，所以搬到了现在的住所--女朋友吉莉安家的隔壁。不过，鲍勃又有了一个艰巨无比的任务--照顾孩子。这三个孩子并不是鲍伯的骨肉，而是吉莉安的宝贝。因为吉莉安有事要临时出去几天，所以把孩子交给这个看起来一点也不出众的、老实巴交的华裔男子照看。多年的特工生涯让鲍伯根本不会做家务，也不会照顾孩子。几天的相处之后，鲍伯和孩子之间好不容易积攒起来了一点信任。就在事情开始慢慢好转的时候，其中的一个孩子无意中在电脑上下载了一段秘密编码，这段编码不仅引来了俄罗斯的恐怖分子，还招来了一大堆别国的秘密特工。瞬间，鲍伯和三个孩子的平静生活就烟消云散……\r 走投无路的鲍伯只好带上了这三个孩子，拿起各种各样的特工工具，和那些坏蛋以及要窃取机密的同行开战。看起来，做一个能保护孩子的继父是鲍伯职业生涯中最大的一个挑战。','Spying is easy, Babysitting is hard',28000000,45236543,14.639324,5.5,345,94,'2010-01-15','en','/qiU1DiqVEdwkHZ4ppXbmHTchLwf.jpg',3.077691962439992,3,'2026-09-10',2,NULL,NULL),(23330,'牛郎血泪美人恩','The Ballad of Cable Hogue','胡格（杰森·罗巴兹 Jason Robards 饰）遭到了信赖的朋友塔格里（L·Q·琼斯 L.Q. Jones 饰）和布温（斯特罗瑟·马丁 Strother Martin 饰）的背叛，身无分文险些丧命。在一片荒漠之中，胡格意外的发现了一处水源，于是，他打起了卖水的主意。\r 　　牧师约书亚（大卫·沃纳 David Warner 饰）指责胡格不应该将公共资源据为己有，于是胡格前往附近的小镇，将这片地买了下来，紧接着，他又凭借着三寸不烂之舌说服了当地的银行家投资兴建旅店。与此同时，胡格邂逅了被小镇上的居民居住出镇的妓女西堤（斯黛拉·斯蒂文斯 Stella Stevens 饰），胡格收留了她，两人之间产生了真挚的感情。 ©豆瓣',NULL,3716946,5000000,2.676535,6.9,47,121,'1970-05-13','en','/bEth8XAYaytjzxnHkLkj4nZx2XD.jpg',2.6948342411133352,3,'2026-09-10',2,NULL,NULL),(23367,'摇滚斗阵','Bandslam','由于母亲的工作变动，刚刚升上高中的威尔·伯顿（盖南·科内尔 Gaelan Connell 饰）离开辛辛那提州，转学来到了新泽西的某个小镇的范·布伦高中。与那个充满着不安和压抑的初中时代有些不同，这里为热爱音乐的威尔带来全新的体验。该高中音乐氛围极浓，所有的学生都在为校内名为“乐团狂飙（Bandslam）”的至高荣誉而努力。威尔不仅找到了属于自己的天地，还结交了萨姆（瓦妮莎·安妮·哈金斯Vanessa Hudgens 饰）这个有些孤僻的女孩子。  偶然机会，极具创作和演唱天赋的美女夏洛特·班克萨克斯（艾莉森·米夏卡 Alyson Michalka 饰）邀请维尔加入自己的乐队，准备在新一届“乐团狂飙”上和前男友本（斯科特·波特 Scott Porter 饰）的乐队决一雌雄。威尔的全新生活就此展开……','Band Together',20000000,5210988,7.716606,5.4,126,111,'2009-08-06','en','/z654TmQygFasbyi52vwHv8fWxoi.jpg',2.871784716548189,3,'2026-09-10',2,NULL,NULL),(23398,'鼠来宝2：明星俱乐部','Alvin and the Chipmunks: The Squeakquel','上一集的相会，无意改变了作曲家戴夫·塞维利亚与三只可爱的花栗鼠艾尔文、西蒙与西奥多，他们结伴出游，享受音乐的乐趣，当然也闹出不少的乱子和笑话。意外受伤的戴夫将三只小家伙托付给杰姬阿姨，还为他们办了入学手续。但杰姬阿姨也出了事故，艾尔文他们只能和戴夫不着调的侄子托比混在一起，开始了校园生活，还结识了另外三只美丽可爱的小花栗鼠布列塔妮、埃莉诺与珍妮特。有趣、浪漫且韵律十足的校园故事轻松上演。','The Boys are back in town... and they have competition.',75000000,443140005,29.412262,5.4,666,88,'2009-12-21','en','/3HTeKaFrjN7octrvKcecNPc2DTI.jpg',3.210923155102554,3,'2026-09-10',2,NULL,NULL),(23479,'少棒闯天下','The Bad News Bears','一位年迈酗酒的前小联盟球员（沃尔特·马修 饰）勉强同意在竞争激烈的加州少年棒球联盟中执教一帮格格不入的孩子。','The coach is waiting for his next beer. The pitcher is waiting for her first bra. The team is waiting for a miracle. Consider the possibilities.',35000000,35323292,6.889633,6.9,97,102,'1976-04-07','en','/tRXMgxL518FOeeQ9RwCIX7cPS00.jpg',2.8728916846900066,3,'2026-09-10',2,NULL,NULL),(23483,'海扁王','Kick-Ass','戴夫·莱泽斯基和所有普通的男孩一样，梦想有一天可以成为超级英雄，只不过他把自己的这一梦想带入了现实。在网上购买到一套廉价的绿色连体衣之后，戴夫便开始了只身打击犯罪的行动。虽然第一次行动便让戴夫身负重伤，不过戴夫可不是一个轻言放弃的人，伤愈之后的戴夫在一次阻止斗殴时，被热心的群众发现并拍摄，之后关于超级英雄“海扁王”的事迹便传遍整个城市。成为传说中超级英雄的戴夫在一次行动中结识超级英雄父女“大老爸”和“超杀女”，之后戴夫遭毒枭集团老大弗兰克之子伪装成的英雄“红雾”的利用，让“大老爸”和自己身陷囹圄。危难之时，“超杀女”及时出现救出戴夫，但“大老爸”却不幸身亡。“超杀女”决定完成其父遗志，彻底消灭毒枭集团……','Shut up. Kick ass.',28000000,96188903,45.054936,7.1,4645,117,'2010-03-22','en','/iHMbrTHJwocsNvo5murCBw0CwTo.jpg',4.026298233180218,3,'2026-09-10',2,NULL,NULL),(23531,'泡妞四人组','Whipped','每个星期天，四名大学男生都要去当地的一家餐厅共进午餐。席间他们都谈得津津有味，因为主题是男人永恒的话题——“给女人打分”。每个小伙都先讲一通上周“性探索”经历，接着大家一起讨论。谈话总是很富有启迪性，很少会令人厌倦，时不时的还爆发出一阵阵狂笑。\r 　　然而，事情开始变得复杂。四位小伙不知不觉中追上了同一位姑娘。在每一位心目中，这姑娘都似圣女般完美无暇。为了博得姑娘的青睐，四位小伙争显“泡妞绝技”。于是一夜之间，多年的挚友产生了隔阂，他们的友谊也变得飘忽不定。到底谁最后能获得姑娘的芳心呢？','Never underestimate the power of a woman.',3000000,0,2.144354,3.1,11,82,'2000-09-01','en','/jIVMqADXH1fEAlf8K19FoDZYh0U.jpg',2.364826182433493,3,'2026-09-10',2,NULL,NULL),(23570,'出殡抱佳人','The Pallbearer','汤姆的生活一团糟，失业半年还找不到工作，每天赖在家里混吃等死，是大家眼中的失败者。有一天，他突然接到一通陌生女子的电话，他哭著要汤姆为他已死的儿子抬棺，虽然汤姆对这个人一点印象都没有，还是出席的葬礼，才发现原来大家将他误认为另一位同名同姓的同学，包括一位他仰慕已久的美丽女孩茱莉都对他另眼相看，汤姆利用这个新的来的身分为所欲为，一切看来都很顺利，然而他的人生真的从此改变了吗？','Something magical is about to unfold in the most unexpected place.',8000000,0,2.149469,4.6,30,97,'1996-05-03','en','/zwHI9B3kcj3WqZoE2LaLDi6ZeAO.jpg',2.566423508784608,3,'2026-09-10',2,NULL,NULL),(23618,'喜剧诸王','The Original Kings of Comedy','当喜剧演员史蒂夫·哈维（《史蒂夫·哈维秀》）、D.L.休利（《休利一家》）、塞德里克（《史蒂夫·哈维秀》）和伯尼·麦克（《生活》）齐聚这部由斯派克·李执导的爆笑喜剧盛宴时，整座房子都为之沸腾，笑声如潮水般汹涌。','We Got Jokes',0,0,1.918959,6.3,15,115,'2000-08-18','en','/vjbEcW9OqWoXKr9e2KySG1WZlNS.jpg',2.4413599447100727,3,'2026-09-10',2,NULL,NULL),(23629,'美少女特攻队','Sucker Punch','金发碧眼的洋娃娃（Emily Browning 饰）宛如一只时刻会受到惊吓的小鸟，这一天她被送进一家私人会所。该会所由蓝佬（Oscar Isaac 饰）掌控，他四处网罗妙龄女孩，并让葛斯基夫人（Carla Gugino 饰）教授她们舞蹈，旨在取悦那些腰缠万贯的富翁和手眼通天的政要。洋娃娃在此结识了小甜荳（Abbie Cornish 饰）、火箭女（Jena Malone 饰）、布女郎（Vanessa Hudgens 饰）、黑琥珀（Jamie Chung 饰）这4名好友。洋娃娃不愿沦为供人把玩的工具，她与朋友们商量从此逃走。逃亡计划需要4样工具：地图、打火机、刀和钥匙。朋友们负责盗取这些工具，而洋娃娃则用她那迷人且极具魔幻色彩的舞蹈吸引着蓝佬等人的注意力。\r 只是终究也分不清，这是谁人的魔幻世界……','You will be unprepared',82000000,89792502,39.127082,5.9,1623,110,'2011-03-24','en','/p45KzEdW7ad5MdtJ7hQkYCdYLQk.jpg',3.4844255905609653,3,'2026-09-10',2,NULL,NULL),(23631,'弯刀','Machete','故事的主人公弯刀（Machete）是一个技术娴熟的杀手，一次他被雇佣去刺杀某个参议员。然而就在他瞄准目标准备开枪的时候，突然发现另外有人正在向自己瞄准。弯刀明白自己被设计了，在好不容易从狙击手的枪下生还后，他决定要向当初的雇主复仇。同时弯刀还为自己找了个帮手——他以前的老朋友，如今已成为一名牧师并发誓不再使用暴力的马瑞恩。两人共同踏上了复仇之旅。','He was given an offer he couldn\'t refuse...',20000000,31327899,26.396191,6.3,1150,105,'2010-09-01','en','/8omSwts86kzQnfVEP9uGD6cePya.jpg',3.459031311301818,3,'2026-09-10',2,NULL,NULL),(23655,'Groove','Groove','An inside look into one night in the San Francisco underground rave scene.','Are you feeling it?',0,0,1.09454,5.6,6,86,'2000-06-08','en','/tVbs0q2duVWLwAR8wDuaemLuqj1.jpg',2.257575210004288,3,'2026-09-10',2,NULL,NULL),(23685,'蹦蹦猴','Monkeybone','人气漫画家斯图•米利（Brendan Fraser 布兰登•弗雷瑟 饰）自童年起便饱受噩梦困扰，醒来后他将梦中场景用画笔记录下来。回首过往，他的生命中满是恐怖阴暗的色调。在结识了美丽的茱莉（Bridget Fonda 布里奇特•方达 饰）后，斯图在她的鼓励下尝试用左手绘画，终于创作出可爱的蹦蹦猴及其同系列漫画。作品一经发行，大受欢迎，斯图的人生从此出现转机。\r 　　然而正当他准备向茱莉求婚时，却遭遇了一场离奇车祸。陷入重度昏迷的斯图来到一座怪异鬼魅的城堡，令他感到惊奇的是，这里出现的人和物竟和他噩梦中的景象何其相似。不久他更得知，自己必须在12个小时之内返回人间，否则将永远留在死亡之国。而周围唯一可以依靠的，正是那只他亲手创造的调皮搞怪的蹦蹦猴','If It Yells, If It Swings, It\'s Got To Be Monkeybone!',75000000,5409517,8.098369,4.3,78,93,'2001-02-23','en','/lgH7Wej9922C1MQv0wciAfesKH8.jpg',2.748498182099314,3,'2026-09-10',2,NULL,NULL),(23706,'关于史蒂夫的一切','All About Steve','玛丽（桑德拉·布洛克 Sandra Bullock 饰）是一个字谜游戏编撰者，她聪明漂亮却拙于社交，忧心她终身大事的父母一直为她安排各种相亲。本来不抱什么希望的玛丽，面对相亲对象史蒂夫（布莱德利·库珀 Bradley Cooper 饰）的英俊与才情，顿时沦陷。她滔滔不绝地对史蒂夫谈论自己的字谜工作，早觉枯燥的史蒂夫找了借口摆脱了她。玛丽在编撰一个“关于史蒂夫的一切”的字谜时，被上司发现而炒了鱿鱼。但是玛丽却认定了史蒂夫就是自己的灵魂伴侣，于是紧追史蒂夫不放。她在史蒂夫同事的鼓励下，跟随史蒂夫的新闻摄制组周游全国报道新闻。在跟随一次矿井塌陷新闻报道时，玛丽掉进陷塌的矿井中，她意外地发现井底下还遗漏了一个男孩，玛丽想尽各种办法拯救了男孩，并将功劳让给了别人。她的勇敢与智慧获得了史蒂夫的另眼相看，玛丽用她自己独特的方式赢得了大家的喜爱。','A Comedy That Clings',15000000,40105542,13.237835,4.7,295,99,'2009-09-04','en','/fLMT75G2tSuaMUdXb6LRt3XspD2.jpg',2.9775123644806465,3,'2026-09-10',2,NULL,NULL),(23730,'地下怪物','C.H.U.D.','在纽约市，一群奇怪的谋杀案似乎指向一群居住在下水道中的怪异变形的流浪者。 一个勇敢的警察，一个照片记者和他的女朋友，和一个健壮的屁股，似乎知道很多关于这些生物，乐队一起尝试和确定这些生物是什么，如何阻止他们。','They\'re not staying down there anymore!',1250000,3412497,4.45544,5.3,62,88,'1984-08-31','en','/8BVw5RIDBTZwdMAR1VKpAkwrMjj.jpg',2.724507890530206,3,'2026-09-10',2,NULL,NULL),(23742,'Cop Out','Cop Out','Detectives Jimmy and Paul, despite nine years as partners, can still sometimes seem like polar opposites – especially when Paul\'s unpredictable antics get them suspended without pay. Already strapped for cash and trying to pay for his daughter\'s wedding, Jimmy decides to sell a rare baseball card that\'s worth tens of thousands. Unfortunately, when the collector\'s shop is robbed and the card vanishes with the crook, Paul and Jimmy end up going rogue, tracking down the card and the drug ring behind its theft, all on their own time, and without any backup – except for each other.','Rock out with your Glock out',30000000,55583804,25.825771,5.3,511,107,'2010-02-26','en','/y4yof0wd2ZxbFPJfSqYtuRvJmyI.jpg',3.146900403510358,3,'2026-09-10',2,NULL,NULL),(23759,'百夫长','Centurion','在公元117年，罗马试图入侵英国，跟随罗马赫赫有名的第九军团以及军团统帅“Virilus将军”远征英国的百夫长昆图斯·迪亚斯（Quintus Dias），奉命北上除掉匹克特族人首领Gorlacon，并将该族人斩尽杀绝。不过在匹克特人偷袭中，该军团全军覆灭，只有昆图斯·迪亚斯得以幸存。而欧嘉·柯瑞兰寇饰演的艾泰恩，因为全家被罗马人杀害，她自己也被割掉了舌头，从而和昆图斯·迪亚斯一起走上了复仇之路。 　　公元117年，罗马帝国疆域跨越埃及和西班牙，最东延伸至黑海。但是，在英国北部，罗马帝国的扩张却面临着当地野蛮人，即皮克特人无情的游击战式的阻击。百夫长昆图斯·迪亚斯（迈克尔·法斯宾德），作为罗马边境曾经在皮克特人袭击中幸存的他，奉命随同罗马军团中的常胜军团——第九军团，前去剿灭皮克特战士。但是，当军团进入了陌生的苏格兰高地，竟遭到了皮克特人的伏击，军团统帅维流士将军（多米尼克·威斯特）被俘。昆图斯经过殊死搏斗，带领部分幸存者逃出险境。接下来，他们不但要忍受恶劣的地形和环境，更要面对皮克特人无情的追捕。同时，这少数的幸存者在昆图斯的率领下，还要试图去解救他们的将军，并逃往罗马边境；而在皮克特人这边，全家曾遭罗马军团灭门的悍女艾泰恩（欧嘉·柯瑞兰寇），带着复仇的火焰等待着他们的到来……','History is written in blood',12000000,6814789,22.708647,5.9,386,97,'2010-02-15','en','/iMWj77OpH3lAI5ZKVUMQORH2eUD.jpg',3.15741688190626,3,'2026-09-10',2,NULL,NULL),(23827,'灵动：鬼影实录','Paranormal Activity','如果连在家睡觉都不安全了，我们还能躲到什么地方去呢？一对年轻的夫妻卡蒂（卡蒂·范瑟斯藤饰）和弥加（弥加·斯洛特饰）终于搬进了他们期待已久的位于郊区的大房子，然而从他们的脸上，却看不到一丁点儿乔迁新居的喜悦，因为他们越来越惊恐地发现，这个房子里似乎有什么不干净的东西存在。　　两个人都因为越来越明显的灵异现象而深感困扰，不管这些令人无法理解的响声起因为何，却总是发生在午夜时分，尤其是当他们睡着或半梦半醒之间……后来，卡蒂和弥加想到一个办法，他们决定用摄像机代替熟睡的自己，看一看那些时不时烦扰他们的究竟是一些什么东西--于是，他们在房子里安装了多台摄像机，希望能够用真实的影像记录下鬼魂出没的证据，但显然，他们对随后出现的可怕事件，并没有做好充分的心理准备。','What Happens When You Sleep?',15000,193355800,47.456823,5.9,1316,86,'2007-09-14','en','/plt5mOFfteeVDgHFgPAITFUq7yl.jpg',3.4609192686057386,3,'2026-09-10',2,NULL,NULL),(23963,'澎堤池','Pontypool','在加拿大安大略省一个以法语为主的澎堤池的小村庄，当地的灯塔广播电台不分昼夜放送着村中以及国内外发生的大事小情。格兰特·马奇（史蒂芬·麦克海蒂 Stephen McHattie 饰）和西德妮·布莱尔（丽莎·霍尔 Lisa Houle 饰）、劳瑞·安（乔治娅·雷利 Georgina Reilly 饰）分任电台的主持人和导播，小村内的生活平淡悠闲。\r 　　一场大雪过后，村中的气氛却发生了翻天覆地的变化。不断有人狂性大发，化作嗜血如命的残酷丧尸，死亡数字节节攀升。格兰特等人很快发现，丧尸的病毒传染源竟来自电台，而传播的载体竟然是英语。澎堤池彻底陷入混乱，并且被政府所隔离，没人知道自己的命运将会如何……','Shut up or die.',1500000,32000,4.680206,6.6,183,93,'2009-03-06','en','/4wWMvurzg1AoArX57pqsPWwhps2.jpg',3.0062398636923424,3,'2026-09-10',2,NULL,NULL),(23988,'斯坦·海尔辛','Stan Helsing','杰克船长、黑超人等一众山寨英雄齐聚一堂，与美国史上最邪恶的恐怖片BOSS展开一场大对决。  　　恶搞还需要剧情吗?','The most feared monsters in cinematic history have met their match...',108,0,7.410523,4,97,90,'2009-10-27','en','/qDlmKahejt0NoQzw65tnLayEhHZ.jpg',2.771843925064653,3,'2026-09-10',2,NULL,NULL),(24021,'暮光之城3：月食','The Twilight Saga: Eclipse','贝拉即将毕业，她与爱德华在婚姻问题尚有分歧。父亲总担心女儿跟爱德华交往会吃亏，但是爱德华保守派风格令他安心。雅各布看到爱德华与贝拉依旧如胶似漆，内心十分挣扎。他感应到贝拉对自己的感觉，并私下对她示爱。在强吻遭拒后，两人不欢而散。贝拉的衣物神秘被盗，同时爱丽丝感到昔日库伦家族的维多利亚正在准备为死去的詹姆斯复仇。后者组建了一支吸血鬼新生儿军团，正在赶往此地，来势汹汹，不可不防。于是，库伦家族决定积极备战。考虑到贝拉的安全，雅各布也决定加入，昔日宿敌结盟，联手对抗外来的恶势力。然而大战在即，贝拉却还纠缠在同爱德华和雅各布的感情之间，难以抉择……','It all begins ... With a choice.',68000000,698491347,107.069763,5.8,2301,124,'2010-06-23','en','/asZJfHvBHBoG5YeIQ2qGj8QFkeV.jpg',3.6881711613493113,3,'2026-09-10',2,NULL,NULL),(24034,'酷狗上学记','Teacher\'s Pet','传奇狗肖立志学会说话后并不满足，它希望能够成为一个真正的男孩，在伊万教授的帮助下，通过DNA的转变，肖立志获得了人类的思维和性格……','A musical tail about one dog\'s dream of becoming a boy',10000000,0,1.374409,5.5,2,74,'2004-01-16','en','/3IiwOT4QF4beOOdCLbJxdw7xzH1.jpg',2.074979216587921,3,'2026-09-10',2,NULL,NULL),(24055,'肥大的椅子','The Puffy Chair','公路电影的奥义在于，不管终站在那，其实都没有关系，重点在于过程。过气的独立乐手和女朋友开大老远的箱型车，从纽约出发到亚特兰大，途中间自告奋勇加入旅程的老弟，到中古家具店去领一台在ebay上买的旧椅子，当作给老爸生日礼物。The Puffy Chair是这样一个简单的故事。\r 旅途上，男女主角在不停的在沟通方式上琐碎地争执，暗中累积吵架的资本，跟着感觉走的弟弟在喝醉酒以后和刚认识的女人结婚，然后不到24小时就要走人。像是其他公路电影一样，罗曼蒂克的时光和狗屁倒灶的事，交错的发生着。旅途终了，人们没有比起程前更有智慧，不同的是，他们开始能够从途中的摩擦里，更看清楚，自己是谁，不用再假装，而接下来抉择。',NULL,0,0,1.243955,6.2,15,85,'2005-01-17','en','/fybmkedrXx02p7i6TZMl9sC5NvM.jpg',2.4392128006024976,3,'2026-09-10',2,NULL,NULL),(24066,'Happy, Texas','Happy, Texas','Two escaped convicts roll into the village of Happy, Texas, where they\'re mistaken for a gay couple who work as beauty pageant consultants. They go along with it to duck the police, but the local sheriff has a secret of his own.','Escaped convicts disguised as beauty pageant experts? This could get ugly',1700000,1943649,2.079125,5.5,39,98,'1999-12-03','en','/5bUoL781c0YdWmqtcNWjbPATyAb.jpg',2.630221885199349,3,'2026-09-10',2,NULL,NULL),(24071,'冒牌医生','Mumford','In the small town of Mumford, a psychologist of the same name moves in and quickly becomes very popular, despite a questionable past.','Some towns have all the fun.',0,0,4.310168,6.3,26,112,'1999-09-24','en','/a2uqenG3BZICDrcrr49IZwoHA8Y.jpg',2.5612469718459137,3,'2026-09-10',2,NULL,NULL),(24100,'吸血小英雄','The Little Vampire','男孩托尼（乔纳森·利普尼基 Jonathan Lipnicki 饰）跟随着父母搬家来到了一座地处偏远的苏格兰小村庄里，自打在这里住下之后，托尼每天晚上都会梦见吸血鬼。这奇妙的梦境很快就引发了托尼对于吸血鬼的狂热，他借用手边一切的资料，想要找到成为吸血鬼的方法。托尼怪异的爱好让他沦为了同学们口中嘲笑的对象，老师也对这个整天神神叨叨的孩子十分的担心。\r 某天夜里，一只巨大的蝙蝠造访了托尼的卧室，并且在他面前变身成为人形，他的名字叫做鲁道夫（罗洛·韦克斯 Rollo Weeks 饰），鲁道夫因为体力不支而无法再次起飞，而此时吸血鬼猎人布克雷（吉姆·卡特 Jim Carter 饰）又恰好正在进行猎杀吸血鬼的行动，在这个危急时刻，托尼挺身而出救下了鲁道夫。','They\'re not just best friends, they\'re blood brothers.',22000000,13555988,4.365196,6.1,77,95,'2000-10-27','en','/zBGfZGKX3KJnljxsX6r24lzRe0i.jpg',2.7894390532697333,3,'2026-09-10',2,NULL,NULL),(24113,'城里城外','Town & Country','Porter Stoddard is a well-known New York architect who is at a crossroads... a nexus where twists and turns lead to myriad missteps some with his wife Ellie, others with longtime friends Mona and her husband Griffin. Deciding which direction to take often leads to unexpected encounters with hilarious consequences.','There\'s no such thing as a small affair.',90000000,10372291,1.004579,3.7,16,104,'2001-04-27','en','/4ckfJA1zqdXG7ttBqGZ2A91YHQs.jpg',2.435745288251264,3,'2026-09-10',2,NULL,NULL),(24126,'恶魔之子','Warlock: The Armageddon','每当日蚀之时，恶魔会有一次从地狱逃出来的机会，他派他的儿子寻找人间的魔石来释放他，而拥有特殊能力的人类必须阻止世界末日的发生。',NULL,0,0,3.107149,5.2,38,98,'1993-05-01','en','/qpRtxbnLb0qFP93db5vwDDXvWz2.jpg',2.622837761498329,3,'2026-09-10',2,NULL,NULL),(24137,'老公不及格','An Ideal Husband','电影改编自王尔德的作品《理想夫君》。  　　在众人眼中，罗伯特（杰瑞米·诺森 Jeremy Northam 饰）是一个完美的绅士，他为人正直温文尔雅，对妻子忠贞不二矢志不渝，享受着事业和家庭的双重成功的他几乎可以说是攀上了人生的巅峰。然而，这美好的一切在一个名叫西维利（朱丽安·摩尔 Julianne Moore 饰）的女人出现之后全部都化为了泡影。  　　西维利威胁罗伯特，高揭露他的秘密，拆穿他苦心经营的假象，这突如其来的进攻让罗伯特手足无措，无奈中，他只得请求朋友格林（鲁伯特·艾弗雷特 Rupert Everett 饰）帮忙。每个人都有秘密，那么罗伯特的秘密是什么呢？时至今日才出现在罗伯特的面前，西维利又在打着什么样的算盘呢？','He just doesn\'t know it yet.',14000000,18535191,4.519523,6.3,46,97,'1999-04-15','en','/kfFben7EGhCwRnw6PuzaxiNsjNW.jpg',2.68349403597084,3,'2026-09-10',2,NULL,NULL),(24150,'新万圣节2','Halloween II','故事发生在位于伊利诺斯州的哈登菲尔德小镇。臭名昭著的杀人狂迈克尔（泰勒·梅恩 Tyler Mane 饰）终于倒在了少女劳利（丝柯·泰勒-考普顿 Scout Taylor-Compton 饰）的枪下，然而之后他的尸体却神秘的消失了，与此同时，在医院里，出现了一个身份诡异而又神秘的病人，又一场血腥的杀戮即将拉开序幕。  　　幸运的劳利再一次的从迈克尔的屠刀下死里逃生，可是，巨大的阴影始终笼罩在她的周围，因为她知道，迈克尔一天不死，就总会再度回到她的身边。一晃眼一年过去，万圣节又要来了，与此同时将要举办的，是死难者的纪念会。劳利能够感觉到，一双熟悉的眼睛正在默默的注视着她。','Family Is Forever',15000000,39421467,12.929525,5.1,267,105,'2009-08-28','en','/4iI7w8iEykvGOR1I777DtCFImuG.jpg',2.9959011217590836,3,'2026-09-10',2,NULL,NULL),(24206,'重装捍将','Silent Trigger','特务组织成员飞鹰一号，在战时是一名优秀的狙击手，战争结束后，暗杀任务仍持续，他在执行多次暗杀行动后，痛恨自己如刽子手般的屠杀行动，任务指挥官察觉他的心态，暗中派杀手准备消灭他，女助理侦测员飞鹰二号并不知情，险些遇害，事后，他们俩人又再次被指派同一任务。飞鹰一号察觉有异、提高警觉，并决定任务结束后，退出组织。狙击行动在一栋未完工的摩天大楼展开，飞鹰二号伪装成电脑工程师通过大楼警卫检查，大楼警卫欧哈拉色迷心窍企图不轨，为达目的不惜暴力相向，纠缠不休，特务组织暗中派来消灭他们的杀手已准备就诸，伺机下手，飞鹰一号、二号被困在摩天大楼里展开了惊心动迫的自救行动。','The Terms are Clear. Kill or be Killed.',15000000,76382,2.609057,5,22,93,'1996-06-26','en','/wWG3mmGH2COTPzj9ZwmWJRS1KzT.jpg',2.5108205681456797,3,'2026-09-10',2,NULL,NULL),(24226,'大审判','The Verdict','酗酒成瘾的波士顿律师弗兰克·加尔文（Frank Galvin）力图重振声威。在同为律师朋友米基·莫里西（Mickey Morrissey）德介绍下得到了一宗医疗纠纷的案子，为一名在教会医院中因为生产处理不当而陷入错迷的女子索赔。弗兰克当初愿意庭外和解，这样他就可以有三分之一的赔偿金可以平安进口袋，但当他深入了解当事人的惨况后，决定要伸张正义，跟代表医院的大律师硬碰硬，藉此找回他个人失去已久的自尊心……','The doctors want to settle, the Church wants to settle, their lawyers want to settle, and even his own clients are desperate to settle. But Galvin is determined to defy them all. He will try the case.',16000000,53977250,7.980632,7.4,131,129,'1982-12-08','en','/iYEuFP1bpj5yOenKliiRFcNO3VE.jpg',2.9711685001122445,3,'2026-09-10',2,NULL,NULL),(24227,'缉毒警探','Excessive Force','Chicago policeman Terry McCain is determined to put away mobster Sal DiMarco, who always gets acquitted on technicalities. While monitoring a drug sale, a shootout ensues, and one of Terry\'s fellow officers gets away with $3 million of Sal\'s money. Suspecting Terry took the cash, the mobster sends his men to kill Terry\'s brother, Dylan, and partner, Frankie Hawkins. Furious, Terry sets out to take his revenge by any means necessary.','You have the right to remain silent... permanently.',3000000,1200000,1.279106,4.5,10,87,'1993-05-14','en','/4DzUkmxUAdlq993UpV0Cw5SiPH3.jpg',2.350848961451771,3,'2026-09-10',2,NULL,NULL),(24264,'森林女王','Sheena','在神秘的热带雨林，生活着成群的野生稀有动物和正规植物。这个被称为热带天堂的地方并没有成为世外桃源，人们贪婪的眼睛和形形色色的欲望时刻威胁着这里的生物。一名美丽充满原始野性的女泰山希娜是这个天堂的守护神。她自幼生长在这片雨林，与野兽为伍，身手矫健，还有着神奇的能力控制着整个地区。她不放过任何一个对雨林有不良企图的人，以她超人的本领和魅力维护着生态平衡。渐渐的，人们的兴趣转移到了这个神秘的女性身上，希望揭开她的身世之谜……',NULL,25000000,5778353,4.020194,5,22,117,'1984-08-17','en','/g3MC1eYoW1Se9fQzCOZ5tfyMatl.jpg',2.5140438827412326,3,'2026-09-10',2,NULL,NULL),(24266,'冰雪河来客','The Man from Snowy River','19世纪末的澳大利亚，在一个远离城镇的山区，青年吉姆和父亲居以养马为生。和其他男孩一样，吉姆自幼深爱马匹，幻想着能成为驾驭着良驹驰骋的英雄。当时有一群纯种野马经常出没在吉姆家附近的林区，许多爱马之人都曾尝试将它们抓回驯养，但都以失败告终。一天，野马群袭击了吉姆家的林子，吉姆说动父亲拦截野马，不想父亲却不幸被马群踩伤身亡。父亲的老朋友斯伯送给了失落的吉姆一匹良马，让他到山下的平原找工作谋生。很快，吉姆在牧场主哈里森家找到了工作，别人因为他是山里人而看不起他，但哈里森的女儿杰西卡却很喜欢能干、善良的吉姆。 一日，哈里森外出，只留下吉姆陪杰西卡。杰西卡鼓励吉姆和她一起驯服了父亲最为珍视的那匹价值一千英磅的小马驹，野马群恰在此时袭来，吉姆受了伤。哈里森回家后因为发现有人动了小马驹而大发脾气，将吉姆赶出农场，杰西卡也因此负气离家出走。吉姆在山里找到了杰西卡，他托斯伯把杰西卡送回家。 在斯伯家中，杰西卡意外发现了母亲玛蒂尔达的照片，原来斯伯是哈里森的兄弟，20年前，他们同时爱上了镇上最美丽的姑娘玛蒂尔达，无从选择的玛蒂尔达决定谁先赚到大钱就嫁给谁，但她怎么也没有想到，这个决定会造成日后如此巨大的伤害。哈里森选择了孤注一掷，很可能赔上性命的赌马，而斯伯则选择了暗无天日的挖金矿，最终玛蒂尔达嫁给了哈里森。20年的今天，哈里森成了惟利是图的商人，而斯伯依然没有放弃挖金矿，兄弟俩更在玛蒂尔达不幸去世后反目成仇。 此时的哈里森正在悬巨赏动员全镇的好骑手一起出动寻找小马驹，出于对斯伯的敌意，他拒绝吉姆同去，然而当众人追赶的野马群奔到一处陡峭的山崖时，连最有经验的骑手也不得不勒住了马缰，眼睁睁看着马群遁入林中。只有吉姆独自一人飞马向前，冲下山崖。哈里森一行人却只能站在那里惊恐地看着他远去。最后吉姆不但找回了小马驹，还赶回了成群的野马。于是这个来自雪河的男子汉成了人们心目中真正的英雄。','The story of a boy suddenly alone in the world. The men who challenge him. And the girl who helps him become a man.',3500000,20659423,3.656491,6.8,37,104,'1982-03-02','en','/1alAfoJf7Pjn0QuwzO9wY7SLQCt.jpg',2.641994644435138,3,'2026-09-10',2,NULL,NULL),(24356,'蒙面与匿名','Masked and Anonymous','摇滚乐传奇人物鲍勃·迪伦主演的喜剧。故事发生在某年某月某个内战连绵不断的国家，绰号“甜心大叔”的经理人正在筹划一场慈善音乐会，其实这只是一场所谓的慈善音乐会罢了，既没有明确的口号，而收入也最终将落入主办者的囊中。电视制作人妮娜受雇以确保将此次演出推广成一次国际盛会，而当甜心大叔请出了新近刚从牢里被释放的传奇乐手杰克·命运后，这场演出注定将成为一场闹剧。\r 　　鲍勃·迪伦当然知道自己在歌迷心中的名望早已根深蒂固，因此他毫不忌讳人们的负面评论。其实，这并不是他首次出演电影，只不过以前只是扮演一些零星角色。早在上个世纪60年代，鲍勃·迪伦就曾偶尔在一些电影中露面，但都没有太大影响力，人们更关注的是他的音乐。但是鲍勃·迪伦不服老，他亲自操刀撰写剧本，并招募来专业摄影队伍和大牌明星。终于在今年把影片《蒙面与匿名》拿到了圣丹斯电影节。然而事与愿违，在这个以追求独立精神为原则的电影节上，没有人买这个老歌手的帐。\r 　　“每一个历史时期都或多或少地有它的悲剧性”，《纽约时报》的这个评价已经很给鲍勃·迪伦留情面了。事实上，扑朔迷离的情节线索和隐晦的笑话实在让观众乐不起来。在影片最后，“杰克命运”饱经沧桑的脸上写上了某种满足，他说：“有时，仅仅了解事情的本身意义还不够，我们还必须知道那些没有意义的事。”弦外之音就是，你大不要管影片再说些什么，因为知道了也没有用；你只要知道，这是一部鲍勃·迪伦自说自话的影片就行了，尽管这些话对你来说意义不大。','Would you reach out your hand to save a drowning man if you thought he might pull you in?',0,0,1.71729,5.2,13,112,'2003-08-08','en','/zKxB2Ivm1717Hbnuvvy2lONC4R1.jpg',2.4059686198183186,3,'2026-09-10',2,NULL,NULL),(24363,'心碎往事','House of D','艺术之都巴黎。美国画家沃肖在这里过着吉普赛式令人艳羡的自由生活，其实他是一个怨这怨那、时常感叹上天对自己不公的烦人的家伙。故事开始于他和法国妻子的一次争吵，他觉得自己的生活已经被命运之神抛在了一团混乱之中，生活逼得他几乎走上了发疯的边缘，他要和妻子坦白自己的过去，虽然自从相识以来，他一直在对她说谎，但这一次，他要告诉她实情……时光之轮开始倒转，镜头回到1973年的格林威治村，13岁的汤姆和每个处于这个年龄段的青涩少年一样，正经历着从男孩到男人的尴尬转变。都说父母是孩子的第一任老师，可是汤姆的妈妈一直沉浸在丈夫去世的悲哀之中，这位自顾不暇的母亲已经没有能力，给孩子任何实质性的成长指导。在学校制造了一系列混乱之后，汤姆为了逃避责任，干脆辍学，和最好的朋友帕普帕斯一起为一家熟食店做送货员。帕普帕斯虽然有着41岁人应该有的身体，却只有11岁的心智，这个永远都长不到、实质名归的“老顽童”，也不是汤姆现在迫切需要的人。在一次送货的过程中，汤姆结识了蕾蒂，这名被关在格林威治“妇女拘留所”的妓女暂时成了汤姆的心理“辅导员”。在她的帮助下，汤姆品尝了苦涩的初恋，开始从男孩平稳地过度到男人……可是一场突如其来的事故，却以最激进的方式逼着汤姆做了一个足以影响一生的选择……',NULL,0,0,6.337735,6.1,23,97,'2005-04-15','en','/oVBMJQKHVTbXM8vEph3RhS4mKgr.jpg',2.538248867722085,3,'2026-09-10',2,NULL,NULL),(24418,'奇趣马戏团：吸血鬼的助手','Cirque du Freak: The Vampire\'s Assistant','Darren Shan是一个普通的十几岁的孩子。他和他的朋友史提夫发现了一个怪异的演出来到城里，努力寻找票。他们这样做，然后一起去“怪圈怪圈”，在那里他们看到许多奇怪的行为，包括一个狼男人和一个胡子女人。','Meet Darren. He\'s sixteen going on immortal.',40000000,28169671,16.424807,5.5,348,109,'2009-10-23','en','/AtNNp1PWJU2Dlo33ZuMINJtP6YS.jpg',3.0832974421825874,3,'2026-09-10',2,NULL,NULL),(24420,'时间旅行者的妻子','The Time Traveler\'s Wife','这是一个另类的爱情故事，根据奥黛丽·尼芬格（Audrey Niffenegger）同名畅销书改编。该书曾于2006年被英国“企鹅/奥兰治书友会奖”评为最受欢迎图书第二名，仅次于《追风筝的人》。 故事的主人公亨利（埃里克·巴纳）是芝加哥纽贝瑞图书馆的一名图书管理员，他患有一种罕见的“慢性时间错位症”，能穿梭时空却无法控制要去的年代、地点和什么时候去，而且在他时间旅行的时候无法携带任何东西，以至于每到一个时空都要先找件衣服穿上。他和自己的妻子克莱尔（瑞切尔·迈克亚当斯）第一次见面时，后者只有6岁，提前知道自己命运的克莱尔从此就一直等待在正常时间中见到亨利。终于她23岁的时候嫁给了当年31岁的亨利，之后两人还生了个女儿，遗传了父亲的能力。然而克莱尔、乃至亨利自己都不知道他会在什么时候突然消失、又去了哪里，面对亨利一次次的消失在时间的长河中，克莱尔所能做的只有静静的耐心等待……',NULL,39000000,101229792,37.492928,6.7,798,107,'2009-08-14','en','/r10eahSGG22KA1EKjGH6nNExEIk.jpg',3.4628215144050416,3,'2026-09-10',2,NULL,NULL),(24424,'阿亚米','עג\'מי','这部充满力量的犯罪剧情片以雅法阿亚米社区街头为背景——这里是犹太人、穆斯林与基督徒之间文化交融与观念碰撞的熔炉——透过城市中各阶层居民的多重视角展开叙述：卷入家族复仇事件的以色列青年、为筹措救命钱而非法打工的巴勒斯坦难民、执着寻找失踪兄弟的犹太警探，以及梦想与犹太女友共度未来的富裕巴勒斯坦青年。当他们的命运彼此交织——随着叙事时间线的回环穿梭——我们目睹不同世界的剧烈冲撞，以及敌我邻里共处一隅所酿成的悲剧宿命。[Kino International]',NULL,0,0,0.51799,6.8,27,120,'2009-09-17','he',NULL,2.565915060315676,3,'2026-09-10',2,NULL,NULL),(24428,'复仇者联盟','The Avengers','当洛基带着来自宇宙的威胁降临地球，并夺走拥有强大力量的宇宙魔方，一场前所未有的危机随之爆发。面对任何单一英雄都难以应对的敌人，神盾局局长尼克·弗瑞启动“复仇者计划”，试图将钢铁侠、美国队长、雷神、绿巨人、黑寡妇和鹰眼召集到一起。然而，这群性格与立场各不相同的超级英雄首先要面对的，却是彼此之间的矛盾与不信任。随着危机不断升级，他们必须学会并肩作战，共同迎战足以威胁地球的强敌……','',220000000,1519557910,55.5512,8.074,11776,143,'2012-04-25','en','/pOjGpquNBARqOAm3clMWSP7bAWm.jpg',4.550329657649666,3,'2026-09-10',2,NULL,NULL),(24432,'小狗多戈尔','Doogal','在传说中，有三块拥有强大魔力的魔法石头，它们目前流落在世界各地，但是一旦当三块石头重新汇聚到一起时，便会产生强大的魔力，这股魔力会令整个世界都重新回到了无生机的冰河时期。邪恶的法师泽巴达（乔恩·斯图尔特 Jon Stewart 配音）从囚禁他的远古监狱中越狱了，他要发誓要报复全人类，于是开始寻找这三块石头。','Things are about to get hairy.',0,0,1.682839,3.2,18,85,'2006-02-24','en','/4Z7h8xDBxQADSPFGj7vmMN76ynX.jpg',2.455932056307024,3,'2026-09-10',2,NULL,NULL),(24438,'蒸发的摩根夫妇','Did You Hear About the Morgans?','居住在纽约的摩根夫妇生活优渥，丈夫保罗（休·格兰特 Hugh Grant 饰）在司法界声名远播，妻子梅莉（莎拉·杰茜卡·帕克 Sarah Jessica Parker 饰）则是房地产界的精英女强人。事业上的卓越成就无法弥合夫妇俩日渐凸现的情感矛盾，保罗的外遇更致使两人长期分居，婚姻濒临崩溃。在分居后的第三个月，保罗主动约出妻子，希望与之重归于好。晚餐过后，摩根夫妇在瓢泼大雨中偶然目睹一桩杀人案，他们清楚看到凶手（麦克·凯利 Michael Kelly 饰）的长相，而自己的容貌也被凶手尽收眼底。  　　摩根夫妇此时恐怕首次要为自己的知名度而懊恼，因为凶手文森特毫不费力知道了他们的姓名。针对摩根夫妇的灭口追杀自此接连上演，他们只有抛弃一切，选择人间蒸发……','We\'re not in Manhattan anymore.',58000000,85280250,14.403696,5.1,276,103,'2009-12-17','en','/yPdZHCmAp9qkrJUHmdnbwXdgYkA.jpg',3.0044490293888093,3,'2026-09-10',2,NULL,NULL),(24469,'鱼缸','Fish Tank','英国导演安德里亚·阿诺德凭借这部激烈而充满活力的影片荣获戛纳评审团奖。影片讲述十五岁女孩米娅（由极具爆发力的新人凯蒂·贾维斯饰演）与母亲和妹妹住在埃塞克斯的住宅区。当母亲的新男友（魅力致命的迈克尔·法斯宾德 饰）出现后，米娅的青春期冲突与觉醒的性意识达到沸点。在年轻的职业生涯中，阿诺德已证明自己是社会现实主义的大师，其作品让人联想到迈克·李和肯·洛奇；她以自己独有的诗意而质朴的感性，赋予这些关于无望生活的同情性描绘以生命力。本片宣告了一位重要新电影人的正式登场。[标准收藏]','Live, love and give as good as you get.',3000000,2357852,12.68672,6.9,250,123,'2009-05-14','en','/4mLzQ1Sx0LPHeA6sjDHCeAck1vi.jpg',3.1229544766238426,3,'2026-09-10',2,NULL,NULL),(24575,'冲出地狱海','Raise the Titanic','为了获得一种稀有矿物的供应，对唯一已知的来源——泰坦尼克号进行了升船作业。','They\'ve found the Titanic. There\'s just one thing left to do...',0,0,1.630541,5.2,21,115,'1980-01-01','en','/XvukyvRCbkYKKv1TdtlyNxvzEl.jpg',2.501046468790314,3,'2026-09-10',2,NULL,NULL),(24621,'脚踏三条船','Chasing Papi','Playboy Thomas Fuentes has so far been able to skate by in life on good looks and charm alone. But when his duplicitous relationships with three women -- impassioned waitress Cici, meticulous lawyer Lorena and bored socialite Patricia -- spiral out of control, he suffers a mental breakdown. His doctor recommends that he choose just one girlfriend -- but can he choose in time before they discover his deception?','Three women. Three cities. Three times the trouble.',0,6126237,1.118511,6.3,16,80,'2003-04-16','en','/mdn6NwGZChgaSuWHQzYKYO1KBL6.jpg',2.4527700272512853,3,'2026-09-10',2,NULL,NULL),(24662,'猫咪不跳舞','Cats Don\'t Dance','《猫不跳舞》是个有关一夜成名的故事。主人公丹尼是一只极有天赋的猫，它毕生的愿望就是成为明星，然而当它发现在好莱坞只有人类才能获得好角色的这个事实之后，星路一度受挫。在大屏幕上，动物们可以发出各种叫声，但是猫却不能跳舞。幸好它新结交了一些朋友：热情的河马蒂利、可爱却悲观的猫小姐索亚、可爱的企鹅帕吉。在这些朋友的帮助下，丹尼打破种种障碍，刻苦努力，终于实现了自己的梦想。','It\'s a Jungle Out There!',32000000,3566637,4.098444,7.1,24,75,'1997-03-26','en','/6CrgfB0dNUsanaMWHTv0Y6AFeNd.jpg',2.5515623885329166,3,'2026-09-10',2,NULL,NULL),(24663,'The Open Road','The Open Road','Minor leaguer Carlton Garret takes an unexpected road trip to track down his estranged father, legendary baseball player Kyle Garret when Carlton’s mother becomes sick. Once reunited, Carlton struggles to deal with the series of misadventures caused by his father’s antics. Attempts at bonding come to a head as the mismatched duo make their way from Ohio back home to Houston to reunite the family.','They\'ve got a long way to go',0,0,1.388136,4.8,19,90,'2009-02-07','en','/oOy2b1oj3IZ7rbqvlgZImZCST8W.jpg',2.4774580422109582,3,'2026-09-10',2,NULL,NULL),(24664,'迷惑','Bamboozled','电视制片人皮埃尔·德拉克罗瓦感到沮丧，因为电视台高层拒绝了他的情景喜剧创意。希望能被解雇，德拉克罗瓦提出了他能想到的最糟糕的主意：一个21世纪的黑人歌舞团表演。电视台不仅播出了这个节目，而且它成为了一场轰动的成功。',NULL,0,0,2.23411,6.3,24,135,'2000-10-06','en','/oAg1mUUxdWJNLa6t1gctbQhXHVN.jpg',2.5396486894840447,3,'2026-09-10',2,NULL,NULL),(24684,'成长教育','An Education','在战后、披头士狂潮前夕的伦敦郊区，一名聪慧的女中学生不得不在刻苦攻读牛津大学入学资格与一位魅力四射的年长男子带来的鲜活世界之间做出抉择。[索尼影业经典]','An education isn\'t always by the book.',7500000,26096852,16.990308,6.8,409,100,'2009-10-29','en','/gLIvvUdlocGjm8XVLxhWHAKWrRq.jpg',3.253135755360609,3,'2026-09-10',2,NULL,NULL),(24746,'吉它武士','Six-String Samurai','在20世纪60年代内华达州，途中迷失拉斯维加斯摇滚摇滚乐武士的后启示录世界需要他的保护，死亡和在他们之后他metalhead骑士追逐下一个年轻的孤儿。','Vegas Needs a New King.',2000000,124494,1.892183,5.8,36,91,'1998-09-18','en','/4Lo0pT1gnDAL4hTVMYLwpVWcqR1.jpg',2.6177887883491473,3,'2026-09-10',2,NULL,NULL),(24747,'鲍比・琼斯：天才一击','Bobby Jones: Stroke of Genius','当你讲述高尔夫电影的时候，你不得不提高尔夫神童鲍比·琼斯(wiki)，20世纪30年代他拍摄了系列电影和著作，《短距离》（Short)等几部影片的放映都相当成功，但他也为此付出了巨大代价———失去了业余选手资格。\r 　　但琼斯在高尔夫球场上已经是一座丰碑。八十年来他的高尔夫纪录还没人能打破，在二十八岁时他夺得了所有赛事的冠军，于是，他决定归隐田园，和他娇小、美丽的妻子过着远离赛场的安静生活。《天才一击》就是讲述他高尔夫生涯的传记片。\r 　　在电影中再现真人的故事总难免要挨骂，就像当年奥利弗·斯通拍摄《尼克松》就曾引起极大争议一样，将20世纪最伟大的高尔夫球手、最富传奇色彩的鲍比·琼斯的故事改编成电影，当然也要冒一定的风险。影片描述了琼斯从一个脾气暴躁的人如何成长为一名完美的绅士球手，但甫一上映遭到美国媒体“差劲之极”、“缺乏深度”的谩骂，认为演员的表演极其失败。然而，就像当年人们无法阻止鲍比·琼斯赢得比赛的胜利一样，这部被影评家嗤之以鼻的影片大获全胜，上映之初就突破1300场，收入丝毫不亚于同期上映的《特洛伊》和《怪物史瑞克2》。\r 　　虽然《天才一击》算不上影史上经典的体育电影，但这为鲍比·琼斯的偶像地位聚集了极大的人气，不仅仅是高尔夫球迷，原本不熟悉琼斯和高尔夫的人，也能通过这部影片，对这项运动产生一点兴趣',NULL,0,0,2.897449,5.5,19,120,'2004-04-30','en','/wzbV4jsCWZqOEAmyjjGemLNZbK7.jpg',2.486243899965205,3,'2026-09-10',2,NULL,NULL),(24748,'原野铁汉','Hud','本片描写在美国的德克萨斯州，上了年纪的农场主和他的儿子赫德两代人的价值观和道德观有着明显的分歧，表现了美国具有反抗精神的现代青年的观念和生活状况。','The man with the barbed-wire soul.',2500000,10000000,6.82919,7.5,66,112,'1963-05-29','en','/A168bF52vmAIGkC2Qafj7M2EmaE.jpg',2.79699769154397,3,'2026-09-10',2,NULL,NULL),(24803,'Julie & Julia','Julie & Julia','Julia Child and Julie Powell – both of whom wrote memoirs – find their lives intertwined. Though separated by time and space, both women are at loose ends... until they discover that with the right combination of passion, fearlessness and butter, anything is possible.','Based on Two True Stories',40000000,129540499,22.853006,6.6,560,123,'2009-08-06','en','/vLhTMywuJV9TFbkYxQ6RVHY7IMh.jpg',3.3240162192957667,3,'2026-09-10',2,NULL,NULL),(24869,'墨水','Ink','随着白日落幕，城市在夜色中睡去，人们一如既往地进入梦乡。然而他们却不知道，一群被称为“说书人”的隐形灵体正在影响他们的梦境，这些说书人通过梦境向人们传递希望与力量。然而在今夜，世界不再只有一种善良的说书人，代表邪恶力量的“墨水”来到世上，他企图通过噩梦散播绝望。尽管几个说书人竭力阻挠，墨水还是成功绑架了一位名叫艾玛的小女孩（Quinn Hunchar 饰）的灵魂，使她的肉体处于昏迷状态。然而要进入小女孩的梦境，墨水还需要一个代码作为钥匙，一场严酷的善恶交战在艾玛和父亲的梦境中展开……  　　本片曾获坎昆电影节最佳独立电影奖。 ©豆瓣','dreams',250000,0,5.217002,6.4,101,106,'2009-01-23','en','/9vYyX7c8gZtxuqd6SiRukRb4gRd.jpg',2.860497876661462,3,'2026-09-10',2,NULL,NULL),(24913,'恐怖愚人节','April Fool\'s Day','一群大学生在四月一日愚人节结伴到一无人荒岛的巨宅中度周末，结果碰上血腥的愚人节恶作剧。他们在互相玩笑之余却逐一被杀，而邀请他们前来的富家女莫菲圣琼却始终未露面，这到底是什么回事？影片明显地采用了艾嘉莎克莉丝蒂的侦探名著《十个小印第安人》的故事模式，让剧中人一个一个被杀','Childish pranks turn into a bloody battle for survival!',5000000,0,8.190888,5.8,73,89,'1986-03-27','en','/prNp2xFZXIE6IwO2uOnqwtdfRQI.jpg',2.7785654760564986,3,'2026-09-10',2,NULL,NULL),(24940,'神魂颠倒','Head Over Heels','和许多独自在曼哈顿打拼的女孩们一样，阿曼达胸怀大志却囊中羞涩，为了节省房租，她不得不和四个惊为天人的超级模特合租了一间公寓。刚开始，阿曼达的合租生活进行的并不顺利，她仿佛是跌落到了白天鹅之中的丑小鸭，处处力不从心，但逐渐的，阿曼达发现，表面看起来高高在上的“天鹅”们并没有她想象的那样难以接近，正相反，从她们的身上，阿曼达学会了如何成为一个更好的女人。 邻居吉姆是阿曼达的梦中情人，他的一颦一笑都令阿曼达为之神魂颠倒。一次偶然中，阿曼达目睹了一场凶杀案，而凶手不是别人，正是她朝思暮想的吉姆，无论如何都不愿意相信吉姆是杀人犯的阿曼达决心和室友们联起手来，查出真相。','Unleash your inner model.',14000000,10424470,4.66723,5.3,73,86,'2001-02-02','en','/5v0EwZxSMiyQJV64bVwu5NS0juA.jpg',2.756853676969703,3,'2026-09-10',2,NULL,NULL),(24961,'新绿野仙踪','The Wiz','桃乐丝是一名24岁的布鲁克林学校老师。一日，当她在暴风雨中走出家门，没想到竟走入了神秘的欧兹国，她沿着黄砖道寻找回家的路，一路上碰到了稻草人、锡铁人与胆小的狮子，四人一同往翡翠市前进，却遇上大巫师的百般阻挠。勇敢的桃乐丝是否能找到回家的路呢？','From the book that\'s an American tradition… from the smash-hit Broadway show… the entertainment of the year!',24000000,21049053,2.753313,5.9,58,134,'1978-10-24','en','/rgfB8hBRSwbEb0SK7pt9mW9jsyP.jpg',2.720793487308351,3,'2026-09-10',2,NULL,NULL),(24973,'埃及人','The Egyptian','埃及医生辛奴耶与挚友赫伦黑救了法老王，分别被封为御医和侍卫长。但辛奴耶为 美色所迷，千金散尽被赶出门，只有逃难埃及流浪天涯，历经磨难再为名医。他因治愈希泰国指挥官脑疾 而知该国已能铸铁剑的消息，专诚返国告知赫伦黑，希望他能发动战争平息国内动乱。在法老王被各方反 对时，辛奴耶赫然发现了自己是埃及皇帝的身份。','To Nefer, shameless temptress of Babylon, he surrendered his parents\' hope of immortality!',5000000,15000000,4.079111,6,11,139,'1954-08-25','en','/vYLY2YIGCWINPSzLg6tBiN6ub7X.jpg',2.382187943126458,3,'2026-09-10',2,NULL,NULL),(24977,'极限乔丹','Michael Jordan to the Max','------1998年NBA季后赛是上天赐给HOLLYWOOD的最好的剧本。20世纪福克斯公司与NBA娱乐公司合作制作了这部名叫Michael Jordan TO THE MAX的影片，并成为当年票房前10名的作品，成为体育影片的奇迹，影片讲述的是乔丹在1998 年季后赛的传奇故事。许多传播中看不到的场边境头，展现了乔丹的不同侧面，而经过精心处理的声效以及电脑特技的运用使影片更像好莱坞大片。如果你是篮球迷、乔丹迷，而你却还没有看过这部影片，那么这将成为你终身的遗憾，本片将把你带回98年NBA PLAYOFFS，重温乔丹与公牛最辉煌的时刻。','Up close some heroes get even bigger.',0,21268532,1.830306,7.5,10,46,'2000-05-05','en','/ppOsOvabD2TmHz5LosHDI9CZeEp.jpg',2.3642960250232754,3,'2026-09-10',2,NULL,NULL),(24985,'我的心','The Heart of Me','故事发生在1936年的英国伦敦，里奇（保罗·贝坦尼 Paul Bettany 饰）是一位拥有着大好前途的银行实业家。然而，事业上的成功却并不能弥补里奇婚姻中的缺憾，他和妻子玛德琳（奥莉维亚·威廉姆斯 Olivia Williams 饰）之间的关系早已经名存实亡。\r 玛德琳的妹妹蒂娜（海伦娜·伯翰·卡特 Helena Bonham Carter 饰）要来家中小住，蒂娜是一名艺术家，她那无拘无束的举止和古灵精怪的性格很快就吸引了里奇的注意，随着时间的推移，两人终于决定坦诚相待，越过了伦理和道德的界限。之后，蒂娜怀上了里奇的孩子，遗憾的是，孩子并没有能够平安的诞生，与此同时，里奇亦意识到，对于眼前所发生的一切，一直保持沉默的玛德琳并非一无所知。',NULL,7000000,0,1.498245,7.7,5,96,'2002-01-01','en','/4zxVdxQoptVl7lShV7FJTMiKez5.jpg',2.2295268055851323,3,'2026-09-10',2,NULL,NULL),(25066,'幽冥时代','Tales from the Hood','A strange funeral director tells four strange tales of horror with an African American focus to three drug dealers he traps in his place of business.','Chill or be Chilled',6000000,12000000,3.89204,5.4,32,98,'1995-05-24','en','/glPNCcI7V8zTTI3BG0iIUJJcwXN.jpg',2.5929332713732482,3,'2026-09-10',2,NULL,NULL),(25113,'四季情','The Four Seasons','三对中年夫妇每个季节都一起度假，但在其中一个男人为了年轻女子抛弃妻子后，他们之间的关系因此颠覆。',NULL,0,0,8.067702,6.3,16,107,'1981-05-22','en','/bNLuiBVpRYP28VCyyVEhxYBGhyl.jpg',2.468643346976859,3,'2026-09-10',2,NULL,NULL),(25132,'奇石','Shorts','黑福斯小镇上的一切都被“黑盒环球无限工业集团公司”的所有者黑先生（詹姆斯·斯派德 James Spader 饰）所拥有和操控着，那里居住的所有人都无一例外都是黑先生的雇员，在辛苦工作养家糊口的同时，他们也为黑先生创造了数量庞大的受益。\r 男孩托（吉米·本内特 Jimmy Bennett 饰）是小镇上的一员，平静但是枯燥的生活让他感到痛苦，格格不入的违和感令他成为了同龄孩子们欺负和取笑的对象。一次偶然中，托得到了一块古怪的彩色石头，很快托就发现，这块石头所拥有的神秘力量能够让他的梦想成真。神秘石头的力量给托带来的快乐却令小镇陷入了混乱之中，更危险的是，有些心怀不轨的大人也开始打起了这块石头的主意。','Not So TALL Tales From The Director Of \'Spy Kids\'',40000000,28972508,4.100942,5.1,44,89,'2009-08-21','en','/mgVuriiCXK1cGoXzZD7kO9w28DF.jpg',2.6524516256719246,3,'2026-09-10',2,NULL,NULL),(25166,'淹死莫娜','Drowning Mona','警长怀亚特·莱什觉得这并非一次事故，但几乎所有认识莫娜的人都认为这不过是一次意外，而且都希望她早点死。现在莱什所面临的问题已不是谁是嫌疑犯，而是谁不是嫌疑犯？','The death of Mona Dearly wasn\'t so much a whodunnit, as a who didn\'t.',16000000,15427192,3.021835,5.4,43,96,'2000-03-03','en','/iuN2SXCGPIlC7pAPCOzqAdeaDji.jpg',2.6504948287278323,3,'2026-09-10',2,NULL,NULL),(25186,'Janky Promoters','Janky Promoters','Two shady concert promoters get into hot water when their chance to book a superstar rapper goes awry.',NULL,10000000,9069,1.728816,7,5,85,'2009-10-16','en','/sQTn0iUDsfwSLOznzOzfDhC3J8I.jpg',2.2286218463907397,3,'2026-09-10',2,NULL,NULL),(25189,'双面镜','The Mirror Has Two Faces','格里高利（杰夫·布里吉斯 Jeff Bridges 饰）是一位个性腼腆的数学教授，许多女人带着热情和期待来到他的生活中，但最后无一不以失望和离开为结局。其貌不扬的罗斯（芭芭拉·史翠珊 Barbra Streisand 饰）是格里高利的同事，在姐姐的撮合下，两人开始了交往。交往的过程十分顺利，格里高利对于罗斯的聪慧敏锐十分的中意，不久之后，他们踏入了婚姻的殿堂。','A story about just how wrong two people can be before they can be right.',42000000,0,3.844926,6.5,47,126,'1996-11-15','en','/ekk8MKMp3tlJjcMuhOgKsMCRrvR.jpg',2.690229695814428,3,'2026-09-10',2,NULL,NULL),(25195,'闰年','Leap Year','城市女孩安娜（艾米·亚当斯 Amy Adams 饰）与男友杰里米（亚当·斯科特 Adam Scott 饰）相恋四年，共同申请购买波士顿顶级豪华社区的高尚住宅。安娜本以为杰里米要向自己求婚，失望后听从父亲建议，飞往爱尔兰首都都柏林，打算依照爱尔兰传统，在闰年的2月29日这天向在都柏林参加医学会议的杰里米求婚。没想到飞机遭遇气流，迫降威尔士加的夫。安娜从加的夫雇船航行至爱尔兰丁格尔半岛，狼狈不堪中投宿当地青年德克兰（马修·古迪 Matthew Goode 饰）的海滨旅店。德克兰同意次日开车带安娜前往都柏林，一路上二人相互看不顺眼，争吵不休。争执中又遭遇车坏、暴雨、误点、假扮夫妻投宿农家等爆笑事件，可这一对冤家却也在不断的摩擦中彼此了解，情愫渐生。2月29日终于到来，安娜的一颗芳心究竟要托与何人呢？','Anna planned to propose to her boyfriend on February 29th. This is not her boyfriend.',19000000,29922472,21.959742,6.4,465,100,'2010-01-08','en','/jVv6EgUAZw8bGyHAKftmjvF7xh9.jpg',3.25172895380279,3,'2026-09-10',2,NULL,NULL),(25196,'疯狂的心','Crazy Heart','坏蛋布雷克是个潦倒沉溺酒色的乡村歌手，经历了太多段婚姻，长年奔波巡演，无数次酗酒无度。然而，在记者简·克拉多克的帮助下——她发现了这位音乐人背后真实的灵魂——坏蛋仍忍不住试图寻求救赎。在救赎之路上艰难前行时，坏蛋才痛苦地领悟到，生活对一颗疯狂之心的折磨能有多残酷。[福克斯探照灯影业]','The harder the life, the sweeter the song.',7000000,39462438,17.697042,6.8,274,112,'2009-12-16','en','/zwao2YMsqf27IzNEtDNWSe0W9jH.jpg',3.1502388928797256,3,'2026-09-10',2,NULL,NULL),(25208,'The Caveman\'s Valentine','The Caveman\'s Valentine','In this spine-tingling and visually stunning thriller, Academy AwardÂ®-nominee Samuel L. Jackson (Unbreakable, Shaft, Pulp Fiction delivers a \"full-throttle performance\" (People) as Romulus Ledbetter, a misunderstood musician turned recluse, hiding from personal demons in a New York City cave.  When Romulus finds the frozen body of a young drifter in a tree, the authorities - including his police officer daughter (Aunjanne Ellis) - claim the death is accidental. Romulus is convinced the man was murdered by prominent art photographer David Leppenraub (Colm Feore). But how can he prove he\'s right when everyone thinks he\'s insane?',NULL,0,0,4.722403,6,27,105,'2001-01-19','en','/xWjoiGvFZPXuBi93reGblvDHIax.jpg',2.566940875214017,3,'2026-09-10',2,NULL,NULL),(25209,'飞燕金枪','Annie Get Your Gun','安妮（蓓蒂·赫顿 Betty Hutton 饰）是个性格大大咧咧的假小子，在一场射击比赛中她夺得头筹，于是受邀加入了《狂野西部》的演出队伍中，在这里，安妮邂逅了名为弗兰克（霍华德·基尔 Howard Keel 饰）的男子，随着时间的推移，安妮渐渐的爱上了弗兰克。然而，弗兰克喜欢的是那种长发穿裙子极富女人味的类型，安妮的形象和个性显然和弗兰克的理想型背道而驰。\r 当安妮在表演中一炮而红后，嫉妒心驱使弗兰克离开了《狂野西部》表演组，加入了他们的对头《波尼印第安人比尔秀》。在后者的挤兑之下，《狂野西部》损失了许多人气，面临歇业的命运。',NULL,3768785,8000000,1.726175,7.3,22,107,'1950-05-17','en','/c2ZLeqZVI2FYctcrFwm5C86zkLH.jpg',2.529032284137491,3,'2026-09-10',2,NULL,NULL),(25212,'Deterrence','Deterrence','The President of the United States must deal with an international military crisis while confined to a Colorado diner during a freak snowstorm.',NULL,0,0,2.171288,6.1,7,101,'2000-03-10','en','/qAkbSZ3RY7E6jVYi5FNvc27o019.jpg',2.2902510262446145,3,'2026-09-10',2,NULL,NULL),(25248,'Saint Ralph','Saint Ralph','This Canadian made comedy/drama, set in Hamilton, Ontario in 1954, is a sweet and - at times - goofy story that becomes increasingly poignant as the minutes tick by.\r It\'s the fictional tale of a wayward 9th grader, Ralph (Adam Butcher), who is secretly living on his own while his widowed, hospitalized mother remains immersed in a coma. Frequently in trouble with Father Fitzpatrick (Gordon Pinsent), the principal of his all-boys, Catholic school, Ralph is considered something of a joke among peers until he decides to pull off a miracle that could save his mother, i.e., winning the Boston Marathon.  Coached by a younger priest and former runner, Father Hibbert (Campbell Scott), whose cynicism has been lifted by the boy\'s pure hope, Ralph applies himself to his unlikely mission, fending off naysayers and getting help along a very challenging path from sundry allies and friends.','He\'s hoping for a miracle. He doesn\'t have a prayer.',0,0,1.688495,7.3,24,95,'2004-09-11','en','/tG1u1crdDvB9OyilNZepwYuBX6c.jpg',2.547971389111278,3,'2026-09-10',2,NULL,NULL),(25312,'我要','Yes','一段已婚美国女人与中东外科医生的激情恋曲，他们必须面对信仰、政治及性态度等种种冲突，展开一段旅程，从伦敦到贝尔法斯特、再到贝鲁特、抵达哈瓦那。',NULL,0,0,3.677831,5.9,7,100,'2005-08-05','en','/70PQCYF3ExuKHqyieJhYV0GJg9H.jpg',2.293121172749575,3,'2026-09-10',2,NULL,NULL),(25350,'假想英雄','Imaginary Heroes','Matt Travis is good-looking, popular, and his school\'s best competitive swimmer, so everyone is shocked when he inexplicably commits suicide. As the following year unfolds, each member of his family struggles to recover from the tragedy with mixed results.','People are never who they seem to be.',10000000,0,2.85283,6.3,29,111,'2004-09-14','en','/tHMgJGkovOFpHi2lnQ9xTrIaR7N.jpg',2.581011861133491,3,'2026-09-10',2,NULL,NULL),(25353,'穿长筒靴的猫','La véritable histoire du Chat Botté','本片是由法国MK2电影公司2009年出品的电脑动画作品，请区别梦工厂在2011年出品的《穿靴子的猫（Puss in Boots）》。',NULL,0,0,1.684948,3.8,7,82,'2009-04-01','fr','/bbvFY8odTt52DVuz1fLtt5JDbbY.jpg',2.282572547039389,3,'2026-09-10',2,NULL,NULL),(25376,'谜一样的双眼','El secreto de sus ojos','本杰明·艾斯玻希多（里卡杜·达林 Ricardo Darín 饰）是一名退休的检察官，几十年的司法工作经验让他积攒下诸多素材，而多年前一起奸杀案始终让他念念不忘，他希望将其付梓出版，了却心愿。25年前，23岁的美丽女教师莉莉安娜·科洛托（Carla Quevedo 饰）和银行职员里杜卡·莫拉莱斯（帕博罗·拉格 Pablo Rago 饰）相识相恋，然而就在两人已谈婚论嫁之际，莉莉安娜在公寓被人残忍强暴并杀害。是时司法腐败，为求尽快结案，本杰明的同事甚至随便找个外来移民顶罪。也许是为莉莉安娜死亡现场所震撼，本杰明执着地展开调查，从此卷入这桩扑朔迷离的爱恨疑案之中……本片荣获2010年第82届奥斯卡金像奖最佳外语片奖；2009年哈瓦那电影节观众奖、最佳男主角奖（Ricardo Darín）、最佳导演奖、最佳音乐奖、评审团特别奖。',NULL,2000000,33965843,25.894065,7.8,626,129,'2009-08-13','es','/zbp4ze2HCz0mOKNKFxPvA7I2Qoc.jpg',3.525530454246568,3,'2026-09-10',2,NULL,NULL),(25379,'蓝蝴蝶','The Blue Butterfly','在哥斯达黎加的热带雨林中的一个关于勇气、救赎和爱的故事。本片根据真实事件改编，一个10几岁的小男孩从小梦想寻找地球上传说中的最美丽的蝴蝶：一种虚幻般的大翅蓝色蝴蝶。他的母亲说服了一位著名的昆虫学家(威廉赫特)，与小男孩一同踏上寻蝶之旅，二人的生活从此发生了巨大的变化……',NULL,0,0,1.985552,6.8,6,97,'2004-02-20','en','/wuKQhiIrPPhY6DDOdYYrsWoVcK9.jpg',2.262551511567185,3,'2026-09-10',2,NULL,NULL),(25388,'前进或死亡','March or Die','站后期，由福斯特少校率领的法国雇佣兵被命令保护由马尼奥率领的一支考古远征队在阿拉伯进行的考古活动。但是考古队进行的主要工作是掘坟，去盗取阿拉伯珍贵的文物资源。福斯特虽然反对，但是作为一个军人，必须服从命令。考古队的掘坟掀起了萨尔的愤怒，萨尔是一个强而有力的阿拉伯领导人，他要用那坟墓来唤醒他部落成员之间的宗教狂热，进而对外国人发起了一个猛烈的进攻，将外国入侵者打出国境。',NULL,0,0,3.829937,6.2,16,107,'1977-09-08','en','/jW21NrRlcrA4kucmD9hfnPbQEvL.jpg',2.4583186694938624,3,'2026-09-10',2,NULL,NULL),(25428,'I Love Your Work','I Love Your Work','A fictional movie star, Gray Evans, goes through the disintegration of his marriage, his gradual mental breakdown, and his increasing obsession with a young film student who reminds Gray of his own life before becoming famous. A dark psychological drama, I Love Your Work explores the pressures of fame and the difference between getting what you want and wanting what you get.',NULL,0,0,3.313339,6.5,2,111,'2003-10-05','en','/eEHWma4acEcP0byL2a7h9MJxB57.jpg',2.08022954778179,3,'2026-09-10',2,NULL,NULL),(25461,'少年维特的成长','Raising Victor Vargas','16岁的多米尼加裔男孩维克多·巴尔加斯（维克多·拉苏克 饰）在纽约下东区长大。当街坊邻里发现他与一位不受欢迎且超重的女孩约会时，他自诩的初长成情圣形象便轰然崩塌。',NULL,800000,2816116,3.643662,7.8,13,88,'2002-05-16','en','/cMHMtMBca8VNxjYICc1WHK1Qqe5.jpg',2.4240450998129823,3,'2026-09-10',2,NULL,NULL),(25462,'Two Can Play That Game','Two Can Play That Game','Vivica A. Fox sizzles as a woman scorned who plans to get her man back by any means necessary. In this comedy about players and those who \"get played.\" As corporate overachiever and all-around fly chick Shanté Smith, Fox thinks she\'s got the goods to keep her slickster boyfriend (Morris Chestnut) from straying - until he discovers a greener pasture, Shanté\'s archrival (Gabrielle Union)',NULL,6000000,0,2.27213,6.6,17,90,'2001-09-07','en','/oDWVsSJMXvDeX9KohSOtfqCFD7e.jpg',2.4699432128903913,3,'2026-09-10',2,NULL,NULL),(25520,'欢乐之家','The House of Mirth','故事发生在20世纪初的纽约，在这样一个动荡的时代中，女人是无法依靠自己的力量立足的，她们想要得到稳定的生活，只有一种方法，那就是结婚，去寻求男人的庇护。莉莉（吉莲·安德森 Gillian Anderson 饰）是衔着金汤匙出生的千金小姐，聪慧的她自然懂得这个社会的规则，她亦明白，任何想要挺身而出和这个规则抗衡的女人，必定都不会有什么好下场。\r 　　所以，莉莉选择了妥协，把自己锋利叛逆的一面深深的隐藏起来，活跃在虚与委蛇的交际场之中，寻找着自己的庇护所。岁月如梭，年岁渐长的莉莉在情急之下未经慎重考虑就嫁给了一名富有的商人，虽然这场婚姻让莉莉暂时得到了自己想要的一切，但与此同时，她将会失去更多。','When a woman has the beauty men admire and women envy...it is wise to tread carefully.',10000000,5164404,3.007816,6.4,25,140,'2000-09-23','en','/gCEboOrNXFmqE5pKUn42fTHZx8R.jpg',2.551000338433379,3,'2026-09-10',2,NULL,NULL),(25636,'耶稣之子','Jesus\' Son','A young man turns from drug addiction and petty crime to a life redeemed by a discovery of compassion',NULL,0,0,5.581743,6.7,22,107,'1999-09-05','en','/A2lVDbF1oTuCMlh69vLnqugWEAM.jpg',2.5325621882767364,3,'2026-09-10',2,NULL,NULL),(25643,'爱不胜防','Love Happens','伯克·瑞恩（亚伦·艾克哈特 Aaron Eckhart 饰）因写了一本关于如何自救的畅销书而成为许多人推崇的疗伤大师。一夜间，读者为他疯狂，多家媒体竞相抛来橄榄枝。但在他内心深处，却一直还未能真正面对妻子的过世。在一次前往西雅图的售书行程中，他遇到了一个经营小花店的女读者艾萝依（詹妮弗·安妮斯顿 Jennifer Aniston 饰）。他的成熟稳重让她心动，她的有趣可爱也同样让他倾心。与她一起，他总能体验到意料之外的人生，发自内心的久违笑容回到了他的脸上。  　　他只会在西雅图停留三天，而艾萝依也并不确定他是否真正走出丧妻的阴影，做好开始一段新恋情的准备。可突如其来的爱情，是否真的能携子之手与君偕老？','Sometimes when you least expect it...',18000000,36133014,13.472365,5.6,180,109,'2009-09-18','en','/yxxBM4pqMlW7WYBFl3OC6BhYKqB.jpg',2.962924153439458,3,'2026-09-10',2,NULL,NULL),(25678,'美国忍者2：战斗人','American Ninja 2: The Confrontation','乔阿姆斯壮(迈克尔·杜迪考夫 饰)和杰克森(史蒂夫·詹姆斯 饰)两人是美国特种部队成员，他们奉命前往加勒比海某国的美国大使馆，调查当地无故失踪的美国海军陆战队士兵下落。结果发现毒枭盖瑞康威绑架了这些士兵，并要挟一名科学家将这些士兵予以改造，并训练成暗杀忍者。乔与杰克森不只要对付毒枭，还有当地的腐败政权，他们凭着自身的超高武艺，直捣贼窝，将毒枭绳之以法。',NULL,0,0,5.061107,4.9,49,90,'1987-05-01','en','/4a4pASHNv68ZhfKJESekI2b6Dse.jpg',2.6718994203305204,3,'2026-09-10',2,NULL,NULL),(25704,'Post Grad','Post Grad','Ryden Malby has a master plan. Graduate college, get a great job, hang out with her best friend and find the perfect guy. But her plan spins hilariously out of control when she’s forced to move back home with her eccentric family.','A Pre-Life Crisis.',15000000,6405245,7.446069,5,100,89,'2009-08-21','en','/vCcTGYg5SgR7sbrn4J9TzV2sILi.jpg',2.8126604191738536,3,'2026-09-10',2,NULL,NULL),(25719,'轻而易举','Shooting Fish','两名骗子雇佣了一名不知情的医学院学生作为他们最新骗局的秘书。','Fat cats are too easy. Go for the big fish.',3000000,302204,1.204941,7,23,109,'1997-08-22','en','/sBA1vTqjhKmtogB6PKQ3tOn2HNX.jpg',2.5347887948758463,3,'2026-09-10',2,NULL,NULL),(25763,'核战大灾难','Damnation Alley','\"主角们是一群在核战爆发后仍然幸存的核弹基地工作人员，虽然他们的基地很幸运的没被攻击，但对外的联络也断绝了，认为生还无望的指挥官因而意志消沉终日藉酒消愁，身为副手的男主角金麦可文生只好取而代之成为众人的意见领袖，但是一直在基地守到老死不是办法，于是众人拖着意兴阑珊的指挥官，驾驶12轮水陆装甲车Landmaster，准备横跨充满危机的北美大陆，寻找幸存的文明与栖身之地。沿途遇上辐射突变的大蝎子、会追着人死咬的大蟑螂、还有无ZF状态下四处流窜掠夺其他倖存者的武装盗匪，甚至，最后还遇上了避无可避的大海啸...  A small group of survivors at a military installation who survived World War 3 attempt to drive across the desolate wasteland to where they hope more survivors are living. Hopefully their specially built vehicles will protect them against the freakish weather mutated plant and animal life and other dangers along the way.\"',NULL,17000000,8720000,2.215261,5,27,91,'1977-09-10','en','/le6eG9xm7xmDWvnQIRK7prH5U69.jpg',2.5504917048359705,3,'2026-09-10',2,NULL,NULL),(25769,'末日病毒','Carriers','一种高致命性和传染性的病毒在世界上蔓延开来，为了避难，丹尼（卢·泰勒·普奇 Lou Taylor Pucci 饰）和哥哥布莱恩（克里斯·派恩 Chris Pine 饰），女友波比（派珀·佩拉博 Piper Perabo 饰）还有好友凯特（艾米丽·万凯普 Emily VanCamp 饰），驾车以最快的速度穿越美国西南部的沙漠地带。他们希望寻找的是一个相对安全的地方，可是花掉了整整几天的时间，他们却意识到，也许偌大的国家再也没有可供他们容身的地方了。不仅是病毒的肆虐压迫着每个人的神经，他们还不断地被迫去面对道德伦理方面的决定和挑战制造出来的压力--都是一些他们以前无法想象出来的艰难与人性抉择。很快，他们就发现，原来阻挡在他们面前的最大的敌人，并不是不断袭击并打垮人类的致命细菌或病毒，而是隐藏在他们内心深处的黑暗与邪恶......','The rules are simple. You break them, you die...',0,5802422,12.708963,5.8,282,84,'2009-09-04','en','/z3t5G9kf34pfd7ojkWaAZiPlJN8.jpg',3.0625317436721637,3,'2026-09-10',2,NULL,NULL),(25784,'秋季的旅程','Vượt Sóng','1975年4月30日，龙决定留在自己心爱的国家越南，这尽管让妻子心碎，而他也明白这次分手很可能是和家人的永别。他让妻子儿子和岳母离开这个充满战乱和危险的地方，去往遥远的美国而生死未卜。而后，龙被政府抓获，被囚禁在教育营地。忍受着监禁和身边朋友的相继死亡，龙陷入绝望，更相信亲人们已不在世上。而一个神秘的访客带来外面新世界的消息，一切变的清晰起来，他的命运发生转变，一个危险的逃脱计划开始酝酿，他要回到他的家人身边……',NULL,1300000,639000,0.072066,5,1,135,'2006-02-22','vi','/20QLLHVKEkkABlRf17e9jWYcibe.jpg',1.9840044028717863,3,'2026-09-10',2,NULL,NULL),(25786,'萨曼莎：一个美国女孩的假期','Samantha: An American Girl Holiday','新科童星AnnaSophia Robb（主演电影Because of Winn-Dixie）饰演一个1904年时候的小女孩，成长为为多利亚时代的小妇人的好看故事！绝对值得一看！',NULL,0,0,4.980585,4.6,9,86,'2004-11-23','en','/hJwb18mOK68CJfREiNaBD0Xfrpn.jpg',2.3396208153805507,3,'2026-09-10',2,NULL,NULL),(25793,'珍爱','Precious: Based on the Novel \'Push\' by Sapphire','上世纪80年代，又胖又丑的黑人女孩叫克拉丽丝·珍爱·琼斯（嘉伯蕾·西蒂比 Gabourey Sidibe 饰）和暴虐的母亲依靠救济金一起生活，目不识丁的她给自己取名珍爱。年仅16岁的她有个智障女儿的同时还怀有两个月的身孕，而孩子们的父亲就是强奸她的父亲。珍爱时常幻想着自己有迷人的舞姿，有艳丽的舞台，还有一个帅气的男友，而这些只存在于她的白日梦里，现实中的她不但要忍受外人的侮辱，而且还要想办法应付自己亲生母亲的讽刺和刁难。直到她被学校退学并被介绍到一对一选修学校，在那里她认识到其他几个问题少女以及一个让她们每天都写日记的老师布鲁·瑞恩。珍爱慢慢的重新燃起了对生活的热情，可是她却发现自己感染了艾滋病。在希望和不幸的夹缝里，珍爱将何去何从？  　　影片由萨菲尔（Sapphire）的小说《推》（Push）改编。第82届奥斯卡上荣获最佳改编剧本和最佳女配角两项大奖；2009年多伦多国际电影节最高奖项——观众选择大奖；第25届圣丹斯国际电影节美国剧情片评审团大奖和观众选择奖。','Life is hard. Life is short. Life is painful. Life is rich. Life is....Precious.',10000000,47536959,18.664624,6.9,417,110,'2009-11-06','en','/mYyq9eATWocPyQnj9zae9slVP6k.jpg',3.2730004749645314,3,'2026-09-10',2,NULL,NULL),(25941,'哈里·布朗','Harry Brown','70多岁的哈里·布朗（迈克尔·凯恩 Michael Caine 饰）是一名退役的皇家海军军官，妻子去世后，靠退休金生活的哈里独自住在贫民窟附近的小公寓。附近的人行隧道是小混混们街头斗殴、毒品交易和肉体买卖的场所，跟布朗下象棋的好朋友，老头子莱昂纳德（大卫·布莱德利 David Bradley 饰）就常被这帮混混骚扰，甚至终被残忍杀害。女警官弗兰普顿（艾米莉·莫迪默 Emily Mortimer 饰）与下属负责调查案件，却因证据不足而不得不释放杀害莱昂纳德的凶手。一把年纪的布朗忍无可忍，决定亲自上阵，铲除混混，为莱昂纳德报仇。  　　本片获2010年英国《帝国》电影杂志评选的最佳英国影片、最佳惊悚片及最佳男主角（迈克尔·凯恩）提名，并获伦敦影评人协会最具突破性的英国影人（丹尼尔·巴伯 Daniel Barber）提名。 ©豆瓣','Every man has a breaking point.',7300000,10329747,16.829837,6.7,348,103,'2009-11-11','en','/kMiJqbIg33P6AE9zUos12IooabO.jpg',3.200607285771,3,'2026-09-10',2,NULL,NULL),(25968,'薇罗妮卡决定去死','Veronika Decides to Die','故事的女主人公薇罗妮卡（莎拉·米歇尔·盖拉饰）在28岁的时侯就有了其他年轻人梦想与希望有的东西：漂亮的长相、一个好的工作和很好的生活。而她因为不愿被一些规矩所束缚决定结束自己的生命，但没有成功，被维莱特精神病医院抢救又活了下来，但只有5天的生命。最终她离开了这里，独自去旅行，终于得到了自己想要的生活。','For Veronika, confronting death... is discovering life.',9000000,0,4.799022,5.8,75,103,'2009-05-16','en','/oUo9CNSKz4ELnxAh4l3BPcXcxKq.jpg',2.7763965327513476,3,'2026-09-10',2,NULL,NULL),(25975,'我和茱茱有个约会','My Date with Drew','Ever since the second grade when he first saw her in E.T. The Extraterrestrial, Brian Herzlinger has had a crush on Drew Barrymore. Now, 20 years later he\'s decided to try to fulfill his lifelong dream by asking her for a date. There\'s one small problem: She\'s Drew Barrymore and he\'s, well, Brian Herzlinger, a broke 27-year-old aspiring filmmaker from New Jersey.',NULL,0,0,1.929883,6.3,16,90,'2005-08-05','en','/19ChghJMN72BG9mQeDK0D209whF.jpg',2.4546233605633754,3,'2026-09-10',2,NULL,NULL),(25983,'邪恶之屋','The House of the Devil','20世纪80年代，美丽的女大学生萨曼莎·休斯（乔塞琳·多纳休 Jocelin Donahue 饰）看上一间公寓，好心的女房东已经免去了麻烦的保证金，不过萨曼莎还是要为了每月的房租而努力。她从布告栏找到一份保姆的工作，当晚，萨曼莎的好友梅根（格蕾塔·葛韦格 Greta G erwig 饰）送她前往雇主家面试。梅根对这份工作颇有顾忌，而萨曼莎似乎急于赚钱，全不在意。','Talk on the phone. Finish your homework. Watch TV. Die.',0,0,8.628485,6,197,95,'2009-04-25','en','/5SUPQLTWbsyl7zz3jjZaFJeF5nM.jpg',2.994632749050118,3,'2026-09-10',2,NULL,NULL),(26022,'我的名字叫可汗','My Name Is Khan','信奉伊斯兰教的里兹瓦·罕（沙鲁克·罕 Shahrukh Khan 饰）从小患有阿斯伯格综合症，母亲去世后，他追随弟弟扎克尔（吉米·舍尔吉勒 Jimmy Shergill 饰）的脚步从印度孟买移民美国旧金山。里兹瓦在帮哥哥的化妆品公司推销美容产品时认识了经营发廊的单身母亲曼迪娅（卡卓尔 Kajol 饰）。里兹瓦不顾哥哥的反对执意与印度教的曼迪娅结为夫妇，一家人和谐美满。9.11恐怖袭击的发生使美国国内掀起了反对、歧视穆斯林教徒的风潮，里兹瓦与曼迪娅的发廊被迫关张，而曼迪娅的独子山姆（Yuvaan Makaar 饰）更是在一场由种族歧视引发的少年争斗中意外身亡。悲愤的曼迪娅将愤怒发泄在了里兹瓦的穆斯林姓氏“罕”上，说只有里兹瓦告诉美国人民及美国总统他的姓氏并非与恐怖分子相关，才会与他再次相见。就这样，执着的里兹瓦踏上了艰难的觐见总统之途……','I am Muslim and i am not a terrorist',12000000,42345360,14.719886,7.7,232,145,'2010-02-12','en','/esimU1RBfiymL212ZBxYj24N1LZ.jpg',3.1661178146279476,3,'2026-09-10',2,NULL,NULL),(26039,'步步惊魂','Point Blank','一名神秘男子沃克遭人背叛并被弃于死地后，一心只想追回被夺走的钱财。','There are two kinds of people in his up-tight world: his victims and his women. And sometimes you can\'t tell them apart.',2500000,3200000,5.164423,7.1,95,92,'1967-08-30','en','/xvZc8EvB7tNPHM9VdmNA19EiwqU.jpg',2.8708894876863176,3,'2026-09-10',2,NULL,NULL),(26171,'天伦之旅','Everybody\'s Fine','年迈的弗兰克（罗伯特·德尼罗 Rovert De Niro 饰）曾是给电线涂保护层的工人，他的工作保护了电线不受外界的侵蚀。对于自己的四个孩子，弗兰克同样是百般呵护，可是在妻子去世的8个月时间里，他发觉自己和孩子们的距离越来越远。弗兰克不顾医生的告戒，独自踏上了拜访四个孩子的旅程。然而，在弗兰克的心目中应该成为画家的小儿子不知所踪，大女儿Amy（凯特·贝金赛尔 Kate Beckinsale 饰）的婚姻生活似乎并没有表面上那样幸福，本以为会是乐队指挥的儿子Robert（山姆·洛克威尔 Sam Rockwell 饰）其实只是个鼓手，而从小就喜欢跳舞的女儿Rosie（德鲁·巴里摩尔 Drew Barrymore 饰）似乎同样对父亲有所隐瞒。就这样，老弗兰克带着满腹的猜疑踏上归途。途中由于心脏病弗兰克住进医院，孩子们终于齐聚弗兰克的医床前，可是小儿子却依旧没有出现……\r 　　本片翻拍自意大利导演朱塞佩·多纳托雷1990年的同名电影，主演罗伯特·德尼罗由于在本片中的出色表演，荣获第13届好莱坞电影节年度男主角奖。','Frank\'s travelling light but carrying excess baggage.',21000000,0,15.440465,6.5,284,99,'2009-12-04','en','/nWCAegIf9YOKjaQvS28Kr9Irq01.jpg',3.129074441050941,3,'2026-09-10',2,NULL,NULL),(26268,'地狱先锋','Harper','杰克．斯米特执导的一部典型的美国式侦探片，内容讲述私家侦探哈柏为一贵妇所聘，追查其失踪已久的丈夫，不料因此发现了其家族秘密。该片情节较为单调，悬念性亦表现不足。','Harper takes a case - and the payoff is murder.',3500000,12000000,2.938973,6.2,35,121,'1966-02-23','en','/zy56CkGHBA9WubuJ7fjntTZCvRi.jpg',2.6198487932720385,3,'2026-09-10',2,NULL,NULL),(26306,'阿普正传','Prefontaine','这是传奇田径明星 Steve Prefontaine 的真实故事，他是令人兴奋的、有时也会引起争议的 \"田径界的詹姆斯-迪恩\"，他的精神俘获了全国人民的心！\"普雷 \"狂妄自大、魅力四射、性格刚毅，他在赛跑中反抗规则、挑战极限......并打破纪录......','He beat the odds... And became a legend!',8000000,589304,8.717235,6.7,21,106,'1997-01-24','en','/3jtG9mgfiZRTRQf19BiUAY6QPN3.jpg',2.5298434493633835,3,'2026-09-10',2,NULL,NULL),(26320,'Taking Woodstock','Taking Woodstock','The story of Elliot Tiber and his family, who inadvertently played a pivotal role in making the famed Woodstock Music and Arts Festival into the happening that it was. When Elliot hears that a neighboring town has pulled the permit on a hippie music festival, he calls the producers thinking he could drum up some much-needed business for his parents\' run-down motel. Three weeks later, half a million people are on their way to his neighbor’s farm in White Lake, New York, and Elliot finds himself swept up in a generation-defining experience that would change his life–and American culture–forever.','A Generation Began In His Backyard.',0,0,11.870161,6.2,127,120,'2009-09-03','en','/1mAdy1QjCLhcPKPfJk4qnGRpkwR.jpg',2.9183935067941733,3,'2026-09-10',2,NULL,NULL),(26352,'A Low Down Dirty Shame','A Low Down Dirty Shame','A black detective becomes embroiled in a web of danger while searching for a fortune in missing drug money. During the course of his investigation, he encounters various old connections, ultimately confronting the criminal responsible for Shame\'s expulsion from the force. He must also deal with two women, Angela, a beautiful old flame, and Peaches, his energetic but annoying sidekick.','He\'s armed and dangerously funny.',10000000,29392418,3.290639,6,31,100,'1994-11-23','en','/v5XUfLrdoGfatObGXhqckYTNqFT.jpg',2.5924948422162086,3,'2026-09-10',2,NULL,NULL),(26367,'我可以自己疯','I Can Do Bad All By Myself','全美最受欢迎的老太太湃玛蒂亚（泰勒·女派瑞饰），特立独行的她依然随身带着手枪到处行侠仗义，热心肠地帮助那些即便是不想要她来帮忙的人们。在上次因为多管闲事闹得还折腾进了监狱，出来后的玛蒂亚老实了一段时间后，眼瞧着又消停不住了。几个毛头孩子闯进了她的生活里，为首的是16岁的珍妮弗（侯普·威利森饰），这几个小孩可把玛蒂亚折腾得够呛，一怒之下玛蒂亚带着他们准备去找珍妮弗的家长算账，结果却发现珍妮弗的家里问题不少。',NULL,0,0,2.242809,6,40,113,'2009-09-11','en','/kl8RNyG7jokw2pTLJNwkPhsBAL9.jpg',2.643538816995982,3,'2026-09-10',2,NULL,NULL),(26371,'莫里斯','Maurice','1908年的剑桥，他们相遇，心中隐约情动。那时的克里夫（休•格兰特 Hugh Grant 饰）和莫里斯（詹姆斯•威尔比James Wilby 饰）还是青葱年岁，克里夫终于突破同性禁忌向莫里斯吐露爱意，莫里斯欣然接受，甚至爱得比克里夫还要真诚炽热。在克里夫选择了仕途而放弃这段感情时，莫里斯仍然坚守。他在等待克里夫回来，却只等到了他和一个贵族女子的婚姻。 莫里斯认识了克里夫的家仆桑德。他身上有着异于克里夫的气质。当他爱上莫里斯时，万念俱灰的莫里斯没有拒绝这段新感情的开始。然而，两个阶层，不同志趣，终究是二人发展的绊脚石。桑德家人叫桑德辞工前往阿根廷定居，桑德却宁愿留在莫里斯的天地。',NULL,0,0,11.552247,7.1,61,134,'1987-09-18','en','/4K3T8rPbzn5mkYabevPABIvh2Zs.jpg',2.7792548387862146,3,'2026-09-10',2,NULL,NULL),(26379,'爸爸','पा','讲述了一位政治家与他的发育不正常的儿子的关系，这个孩子患有一种疾病，导致他迅速老化，很快使他变成一位老人。',NULL,3250000,0,2.126139,6.6,19,133,'2009-12-04','en',NULL,2.49287081734588,3,'2026-09-10',2,NULL,NULL),(26388,'活埋','Buried','一个美国承包商在伊拉克遭到绑架，醒来后发现自己被人活埋在沙漠的一个棺材里，手边只有手机、打火机和一把小刀，他该怎么办？','170,000 sq miles of desert. 90 minutes of oxygen. No way out.',1987650,19152480,32.841229,6.6,827,94,'2010-09-24','en','/fFj0S1Uwxxb5DfhpePtoX2wtVfd.jpg',3.445555189797304,3,'2026-09-10',2,NULL,NULL),(26389,'巴黎谍影','From Paris with Love','身为美国驻法国大使的私人助理，詹姆斯·里斯在巴黎过的是令人羡慕的高端生活，更别提他还有一个美丽的法国女友陪伴左右了。不知道是不是电影和漫画看得太多了，詹姆斯惟一渴望实现的梦想，就是成为一个真正的特工，好能执行一些惊险刺激的重要任务——所以当他接到第一个比较高水平的委派时，他简直不敢相信自己竟然能有如此好的运气，直到他遇到了他的新搭档——查理·怀克斯特工。很快，詹姆斯就惊恐地发现，他的这位工作伙伴是一个异常好斗、喜欢满嘴胡说八道、懒散自由的粗俗之人，而查理被派到巴黎的目的，则是为了阻止一场由恐怖分子发起的袭击。查理带着詹姆斯在巴黎的地下犯罪世界里横冲直撞，引发了一系列无节制的枪战……','Two agents. One city. No merci.',52000000,52826594,27.916284,6.1,675,92,'2010-02-05','en','/7CklgLOSKV0KdZRVB9JvBywV1YY.jpg',3.3107028268400227,3,'2026-09-10',2,NULL,NULL),(26390,'布鲁克林警察','Brooklyn\'s Finest','影片聚焦于三个不同的纽约警察的生活，展示了一幅另类的警察生活的画卷。每个警察都面临着自己的困境、每个警察都要正视自己的生活。 理查·基尔扮演的艾迪·杜根是一个快要退休的老警察。还有7天，他就要永远告别警察这个岗位，靠领取退休金生活了。因此，他不想惹任何麻烦，不想再执行什么任务，更不想发生什么意外。可是，事不遂人愿，他被要求带领一名新丁上岗。于是在熬到退休之后，艾迪·杜根还是继续在生活中扮演着警察的角色。伊桑· 霍克扮演的萨尔，有好几个孩子，可是他却和她的妻子以及孩子们挤在一个小小的房子里。他在纽约警局的薪水根本不够他去买一栋大房子。换房心切的他急于搞到一笔钱，于是他开始把手伸向了缴获来的贩毒的赃款。在鲸吞了一大笔钱之后，毒贩和警察都在调查赃款的去向，萨尔要为此做一个了断。唐·钱德尔扮演的谭戈是一个打入毒贩内部的卧底，他希望在这次任务之后能有一份在办公室里的工作。警局派给他的任务是卧底到一名名叫卡兹（韦斯利·斯奈普斯）的暴徒身边，伺机揣掉她的整个犯罪集团。可是这个卡兹却在监狱里救过谭戈一命，心存感激的谭戈应该何去何从，又要如何选择…… 在生活中，这三个警察并没有任何交集，可是在阴差阳错之下，他们聚集到了同一个地点，并且都死在了这里。','This is War. This is Brooklyn.',17000000,29536299,18.790102,6.2,293,133,'2009-01-16','en','/9ZyJJpMsc3bF8gduDaxo0zo1gwK.jpg',3.1183969330432135,3,'2026-09-10',2,NULL,NULL),(26428,'城市广场','Agora','公元4世纪，罗马帝国日渐衰落，在亚历山大港，多神教的智者希帕提娅（蕾切尔•薇姿 Rachel Weisz 饰）为弟子们授课。奥利斯蒂斯（奥斯卡•伊撒克 Oscar Isaac 饰）对她暗送秋波，甚至在图书馆大胆表白；奴隶达乌斯（麦克思•明格拉 Max Minghella 饰）也对她颇有好感，但碍于身份卑微不便行动。与此同时，基督教徒宣扬的自由，让达乌斯的信仰开始动摇，此举令他遭受鞭刑，是希帕提娅为他疗伤，抚慰了他的心灵。时局动荡，基督教对多神教采取了进攻。双方在亚历山大图书馆对峙。后来，接到了罗马统治者的号令，让多神教撤出图书馆，允许基督教徒进入，于是一场残酷的浩劫开始了……','Alexandria, Egypt. 391 A.D. The World Changed Forever.',70000000,39041505,18.888806,6.9,395,127,'2009-05-17','en','/iU8RGaXv8IJOq3kev0DKXCG2j1H.jpg',3.2588302366707413,3,'2026-09-10',2,NULL,NULL),(26466,'恐怖游轮','Triangle','单亲母亲杰西和一帮朋友乘游艇出海游玩，但她总有一种有不好的事情发生的感觉。不久，他们便在海上遭遇一场强烈的风暴。游艇翻船，众人落海，几经挣扎他们好不容易爬到游艇残骸上来。正当他们无计可施之时，一艘巨大的游轮向众人缓缓驶来。众人欣喜过望，未加思索便登上这艘名为“艾俄洛斯”的游轮，结果发现这竟是一艘1930年便告失踪的神秘之船，而船上更是空无一人。随处可见的鲜血、神秘的指示以及突如其来的凶杀事件，将这群男女带入万劫不复的恐怖轮回之中……','A Passage to Hell',12000000,0,25.496926,6.9,612,99,'2009-10-16','en','/JPF79YnhjuVP545OLYli4w6gq1.jpg',3.393602442863646,3,'2026-09-10',2,NULL,NULL),(26486,'黑道开麦啦','The Last Shot','A movie director-screenwriter finds a man to finance his latest project but soon discovers that the producer is actually an undercover FBI agent working on a mob sting operation.',NULL,0,0,6.7698,5.9,15,90,'2004-09-24','en','/2Rm4xsJnrZaZL0qPO2wBP5MJJpE.jpg',2.4500190115468925,3,'2026-09-10',2,NULL,NULL),(26518,'昨日欢愉','Old Joy','在这部凯莉·雷查德的突破性长片中，两位老友重聚，进行了一次静谧而富有启示的隔夜露营旅行。这部小成本作品专注于人物性格与男性气质的刻画，将这位当代美国影坛最具独立精神的艺术家之一介绍给了众多观众。当即将为人父的马克（丹尼尔·伦敦 饰）与流浪者库尔特（威尔·奥德哈姆 饰）驾车徒步深入森林，寻找一处偏僻温泉时，他们试图重建联系的努力屡屡受挫，不断触及友谊的边界，也迫使他们面对自青年时代分道扬镳后的现实。本片改编自乔纳森·雷蒙德的短篇小说，由“呦啦腾哥”乐队营造氛围的配乐相伴，是一部沉思冥想、观察犀利的佳作，其质朴的格局之下蕴含着丰富的洞见。[标准收藏]',NULL,300000,0,1.673208,6.3,36,73,'2006-01-01','en','/AdFKZOf0LtPpGq8be9T8qsNHTbs.jpg',2.6243526898399985,3,'2026-09-10',2,NULL,NULL),(26602,'夏日捕手','Summer Catch','每年的夏天，一所名气最响的大学棒球队的选手们白天都会从科德角来到雷恩的家乡寻求他们的棒球梦，晚上则到小镇上去渲泄自我。今年夏天对于一心想成为职业联盟棒球队球员的小伙子雷恩来说是个不寻常的季节，一心想成为大联盟球员的他，跟随着学校校队来到鳕鱼角，过着白天练球、晚上狂欢作乐的生活。但是，他忽然发现来自球场外的诱惑，妨碍了他对赛事的承诺。\r 　　阳光，沙滩，碧海，青天——风景如画的鳕鱼角，爱情发生的理想之地。漂亮的富家女滕妮·帕瑞诗和父母一起来到这里度假，结识了为她家割草的男孩瑞恩·雷恩，他们很快坠入了爱河。而雷恩作为波士顿学院棒球队的一名明星投手，刚刚开始在“鳕鱼角棒球联盟巡回赛”中崭露头角，前途无量。但可惜的是，他出身一个蓝领家庭，配不上帕瑞诗那高贵的身份，两人的交往受到了帕瑞诗家人强烈的反对。雷恩非常苦恼，他与帕瑞诗的爱情也几次濒临结束。\r 　　为了得到自己的爱人，雷恩唯有抓住仅有的一线希望——以出色的表现赢得与联盟正式签约的机会，成为一名职业球员而不是一个穷学生。恰巧，此时一位大联盟球探看上他的潜力，有意引荐他到职业球队比赛。但条件是他必须将儿女情长及球队中的勾心斗角搁置一旁，因为这将是他唯一的机会，他必须赢得比赛。在比赛中，雷恩充分发挥实力，在女友的鼓励下，终于赢得比赛，成为赛场上最亮的一颗新星。','Are you game?',34000000,19693891,3.960098,4.8,63,108,'2001-08-22','en','/hMp5Iev56BUu3xJGpAeCCPC1ZwY.jpg',2.7145718717951097,3,'2026-09-10',2,NULL,NULL),(26618,'靶鸽','Clay Pigeons','Earl知道Clay和其妻Amanda有染，于是制造自己被谋杀的假像，嫁祸于Clay。Clay尽力掩饰此事，并结束与Amanda的关系。正当此事未完，他又被怀疑与近日多宗谋杀案有关；究竟这是谁布下的陷阱？','Some killers are strange, some are deranged, and some are just plain psycho.',0,0,4.221313,6.3,39,104,'1998-09-25','en','/6cxoftMuiwcQ9xzXfvGWAQfWUmK.jpg',2.647311610271536,3,'2026-09-10',2,NULL,NULL),(26665,'阿伯丁的最后之旅','Aberdeen','将不久于人世的母亲，在病榻上请凯莎到挪威去把父亲汤玛士找来做戒酒医治，也希望临终能再见一面。汤玛士是个酒鬼，自从十年前母女搬离奥斯陆，凯莎就没有再见过这位父亲，与母亲的关系也一样疏远。但是对于母亲最后的心愿，凯莎无法拒绝，即使她完全对父亲没有任何期待或感情。找到父亲并不难，但是带他“回家”则非易事，父亲的脾气和酒癮让她在归程中吃尽了麻烦，也让凯莎看见了自己的软弱。顺着苏格兰高地起伏的公路，这对争执不休的父女有能力找到回家的路吗？',NULL,0,0,1.068819,7,6,113,'2000-07-05','en','/yjDBeAxrXXd4kt4DpTbjHsmtukk.jpg',2.260947688801027,3,'2026-09-10',2,NULL,NULL),(26672,'小偷与鞋匠','The Thief and the Cobbler','当Tack惹恼了大臣ZigZag时，巫师把他拖到了皇家城堡，在那里，YumYum公主爱上了这个害羞的男孩，并把他从死刑中救了出来。不幸的是，ZigZag为了继承公主的父亲Nod国王的王位，打算娶公主为妻。与此同时，盗贼对金子比对爱情更感兴趣，他带着宫殿顶部的保护球离开了。为了防止ZigZag和独眼军团征服这座城市，Tack和YumYum一起试图找回他们。',NULL,28000000,669276,2.439184,6.8,26,72,'1993-09-23','en','/3OKtFuTxahr7hokPB9aO38qgOfc.jpg',2.5621427393172915,3,'2026-09-10',2,NULL,NULL),(26673,'Frat Party','Frat Party','Duffy the big man on campus who is marrying Adriana, a debutante heiress to a global wine fortune, right after they both graduate from the same prestigious University. Unfortunately , the final Frat Party of his college career is the night before his wedding and there are many obstacles in his way, including a soon to be Father -In-Law who is less than happy with his daughter\'s choice.',NULL,0,0,0.783842,3.5,4,84,'2009-01-01','en','/tBevHrPcJOlDVLsIpWU5N7Rskox.jpg',2.180777389685411,3,'2026-09-10',2,NULL,NULL),(26688,'姐妹联谊会惊魂','Sorority Row','卡希蒂（布蕾安娜·伊薇根 Briana Evigan 饰）、艾莉（卢默尔·威利斯 Rumer Willis 饰）、克莱尔（洁米·张 Jamie Chung 饰）、杰西卡（莉娅·派普斯 Leah Pipes 饰）、查格丝（Margo Harshman 饰）和梅根（奥德丽娜·帕特里奇 Audrina Patridge 饰）是某所高校的六个亲密无间的好姐妹，她们组成名为“西塔派”的姐妹联谊会，一起玩耍，同进同退。在庆祝大四新学年的狂欢派对上，姐妹们合伙戏耍了梅根的花心男友加勒特（Matt O\'Leary 饰），结果却导致梅根被加勒特无意中杀害。为了掩盖罪行，这五个女孩将好友的尸体丢入废井，制造失踪的假象，并相约谨守这个秘密。  　　转眼8个月过去，少女们即将迎来毕业的时刻。梅根的惨剧让她们的心中渐生离析。与此同时，似乎有一个神秘之人正躲在暗处，伺机夺取她们的生命……','The Sisters of Theta Pi Are Dying To Keep a Secret.',12500000,27206120,8.780512,5.4,177,101,'2009-09-09','en','/j1ZQuDpjSnXw448OyTHYfbRxMre.jpg',2.9372570954450246,3,'2026-09-10',2,NULL,NULL),(26710,'三个奶爸三个娃','My Baby\'s Daddy','三个大老粗一样的男人，这回不得不学着照顾他们自己的小孩子了，因为，他们的老婆竟然都在同一时间怀孕了。于是，从没有照顾过小Baby的三个男人，开始了自己的奶爸日子……',NULL,0,51,4.480167,4.3,15,86,'2004-01-09','en','/lah4ZvLmjxwF8Pa1UHIm3u2xNuR.jpg',2.435104204936512,3,'2026-09-10',2,NULL,NULL),(26748,'小镇疑云','Lone Star','两位已卸任的陆军军官，在美国德州南方沙漠某地，意外发现一个警徽和一个骷髅。于是邻近小镇的警察山姆狄斯开始调查这一切的始末。初步调查中，山姆来到一间酒吧，在他和老板的谈话过程中，山姆从老板那里得到一些过去的事情，这其中还包括山姆的父亲鲍迪狄斯和一位恶名昭彰的警长，原来酒吧老板曾经受迫于这个无恶不做的警长，但是又无可奈何。于是，一连串的老故事和新发现由此开始……','John Sayles invites you to return to the scene of the crime.',5000000,13269963,5.960149,6.9,77,135,'1996-06-21','en','/lBxY8znsRoqa9Dy2NCe8I6GPsRm.jpg',2.8160264948327134,3,'2026-09-10',2,NULL,NULL),(26791,'Brigham City','Brigham City','Wes Clayton is a lawman and a bishop in a Mormon community called Brigham. The town is shaken when a woman from California is found murdered. Clayton and his young deputy work with an FBI agent sent to investigate. As a civil and spiritual leader in the frightened town, Clayton must uncover the town\'s deepest secrets, find the murderer and keep Brigham from ripping itself apart.',NULL,1000000,852206,0.280083,7.3,4,119,'2001-03-30','en','/8CM2YIX0qLcqDY7d6iVb4uRXGG8.jpg',2.1858525527268307,3,'2026-09-10',2,NULL,NULL),(26815,'年度推销员','रॉकेट सिंह','哈尔普瑞特（兰碧 卡普尔 Ranbir Kapoor  饰）以B等成绩勉强大学毕业，家境一般的他没有听从朋友的建议去考工商管理硕士，而是去应聘做销售人员。幸运的是他机缘巧合的获得了为你服务公司老总的赏识进入电脑销售行业，满心欢喜原本大展拳脚的哈尔普瑞特却在一开始就犯了致命的错误，正直的性格让他与索要回扣的客户起了冲突，老板罚他不准再涉及公司业务，同事们也为此排斥他。渐渐的他发现单一的指标数字和销售行业的潜规则让他感到厌倦，于是他决定开始创业，在其他伙伴的合作下，各自发挥所长，并凭着诚信的服务和售后建立起了火箭电脑销售公司。','Welcome to the world of sales boss!',1250000,0,3.000435,7,27,156,'2009-12-11','hi',NULL,2.5737299261357673,3,'2026-09-10',2,NULL,NULL),(26837,'街舞小妞','B-Girl','A young female breakdancer, Angel, moves to Los Angeles after an attack by an ex-boyfriend nearly ends her dance career forever. B-Girl follows Angel through recovery and acceptance of a new life as she busts a move into the male-centric world of underground hip hop.',NULL,0,0,0.631571,5.5,7,84,'2009-07-29','en','/kgPoFMvfrvNBT0HQtqZ5vcMzT.jpg',2.285020727120152,3,'2026-09-10',2,NULL,NULL),(26843,'大地雄狮','Lion of the Desert','内容描述在第二次世界大战之前，利比亚回教游击队领袖奥玛穆德在北非沙漠对抗墨索里尼的意大利占领军，终因寡不敌众而被意军杀害。但他的精神鼓舞着利比亚人们，他们坚持不懈地进行反抗，最终取得了独立。','He was a man of honor in a war without any.',35000000,0,2.864979,7.4,34,173,'1981-04-17','en','/xm7CKN5mo09RNAcL1IP1xmJ5avT.jpg',2.6295836626797118,3,'2026-09-10',2,NULL,NULL),(26899,'马奇男孩','The Mudge Boy','14岁的乡村男孩马奇（埃米尔·赫斯基 Emile Hirsch 饰）在努力适应失去母亲的生活。因为强烈想念，他会穿上妈妈的衣服，模仿妈妈的动作，喜欢妈妈生前养的鸡。他和一只鸡冠血红的白色公鸡同吃同住，连洗澡都不分离，乡村的其他男孩经常为此嘲笑欺负他。有次放牛少年佩里（汤姆·盖里 Tom Guiry 饰）保护了他，两人成为好朋友。在健壮和性经验丰富的佩里面前，马奇就像未经人事的天真孩子。他会好奇抚摸佩里的手臂肌肉，告诉他关于母亲的一切，穿婚纱给他看，分享含鸡头的秘密。他不知道这些对血气方刚的佩里都意味着挑逗，最终佩里粗暴的侵犯了马奇…\r 　　《马奇男孩》入围2003年圣丹斯主竞赛单元。电影以美国田园乡村为背景，讲述了一个单纯男孩在成人世界经历的残酷成长痛。饰演马奇的埃米尔·赫斯基的表演极为传神，干净俊俏的脸庞背后是浓郁忧伤，有种被伤害的惊恐。作为美国新生代演员中少有的演技派，他在《荒野生存》、《狗镇之主》和《米尔克》等众多口碑文艺片中都有才华横溢的演出。',NULL,800000,62852,5.292536,7.3,23,94,'2003-01-17','en','/daxDdN3vBBqx8KuOXNHBtu9QcbQ.jpg',2.5468804124562734,3,'2026-09-10',2,NULL,NULL),(26916,'Mercy Streets','Mercy Streets','Estranged twin brothers - one a con man, the other an Episcopal deacon - accidentally switch places... and find God in the process.',NULL,0,0,0.099902,5.5,2,106,'2000-10-31','en','/cszKiUooItVoSQPKz9k8LkJIyRj.jpg',2.0720679917988076,3,'2026-09-10',2,NULL,NULL),(26963,'凯尔经的秘密','The Secret of Kells','魔法、奇幻与凯尔特神话汇聚成一场绚烂多姿、令人目眩的视觉盛宴，讲述了一个关于想象力与信仰如何带领人类穿越黑暗时代的宏大故事。少年布兰登居住在偏远的中世纪边陲哨站，饱受蛮族侵袭之苦。当一位来自异乡的著名绘经师携带一部古老却未完成、蕴藏着秘密智慧与力量的书籍到来时，布兰登的冒险新生活就此开启。为协助完成这本神奇的经书，布兰登必须战胜内心最深的恐惧，闯入神话生物藏身的魔法森林。在那里，他遇见了神秘的狼女精灵阿诗铃，她帮助布兰登完成危险的使命。[GKIDS]','Turn the darkness into light',0,0,10.621353,7.3,181,75,'2009-02-09','en','/zEtxQ5ZYiGLP95aCrnrHm6xp4m.jpg',3.0589757929574706,3,'2026-09-10',2,NULL,NULL),(27004,'Ca$h','Ca$h','A stroke of good luck turns lethal for Sam Phelan and his wife Leslie when they are faced with a life-changing decision that brings strange and sinister Pyke Kubic to their doorstep. As Pyke leads Sam and Leslie on a tumultuous adventure through the streets of Chicago, each are pulled deeper and deeper into a desperate spiral of deception and violence – all in the name of money.',NULL,7000000,46488,8.207425,6,73,108,'2010-01-01','en','/e5B7nG6xREL6lNnS34ZoAvXbB9l.jpg',2.7840684781464367,3,'2026-09-10',2,NULL,NULL),(27022,'The Sorcerer\'s Apprentice','The Sorcerer\'s Apprentice','Balthazar Blake is a master sorcerer in modern-day Manhattan trying to defend the city from his arch-nemesis, Maxim Horvath. Balthazar can\'t do it alone, so he recruits Dave Stutler, a seemingly average guy who demonstrates hidden potential, as his reluctant protégé. The sorcerer gives his unwilling accomplice a crash course in the art and science of magic, and together, these unlikely partners work to stop the forces of darkness.','It\'s The Coolest Job Ever.',150000000,215283742,35.580815,5.8,1470,109,'2010-07-13','en','/bqzvElmnm7pZfBgMhWVGM2kjGRo.jpg',3.436153879839873,3,'2026-09-10',2,NULL,NULL),(27023,'赌城圣约翰','Saint John of Las Vegas','在经历了一系列连续的打击和糟糕的运气之后，意志薄弱的赌徒约翰（史蒂夫·布西密饰）终于决定逃离拉斯维加斯，为自己以后的日子好好做做打算，在他的想象中，他应该找一份正常一点的工作，然后过上普通人的生活。随着约翰在阿尔伯克基市的一家汽车保险公司谋得了一份没什么发展的职位，他也开始进入一个真实的世界、像身边的人一样努力地打拼，同时又在不断地抵御着纸牌所带来的诱惑，挣扎并反抗着。\r 当老板汤桑德先生（彼特·丁拉基饰）让约翰陪同公司里最优秀的谎言辨别师维吉尔（罗曼尼·马尔可饰）一起去调查一起发生在拉斯维加斯附近的可疑的车祸时，他也将此看成了一个升职的机会，虽然他真正挂念的其实是能否重新回到赌桌上去……然而就在约翰出发之前，他却和他那行为举止稍嫌古怪的同事吉尔（萨拉·丝沃曼饰）纠缠不清起来，本来俩个人只是调调情以打发无聊的时间和枯燥的工作，让约翰始料不及的是，他们竟然发展出一段真实的恋爱关系。\r 很快，约翰就和维吉尔一起上路了，并在旅途中遭遇了一大堆各种各样的人，包括一位坐在轮椅上的脱衣舞娘（埃曼纽尔·施莱琪饰）、一个喜欢裸奔的好战分子（蒂姆·布雷克·尼尔森饰）、一位停车场管理员（杰西·加西亚饰）以及一个疯狂的纵火犯（约翰·赵饰）……就这次保险公司的调查行为而言，维吉尔本来是那个起到主导作用的人，可是最终他的位置却被约翰所取代了，不断地推动着整个事件的发展，越来越接近真相。\r 在这个过程中，约翰的自信心也在一点一点地建立起来，然而他随即意识到，光是远远地离开拉斯维加斯，并不能帮助他逃离赌博的诱惑，无论他走到哪里，一个念头都在时刻折磨着他的灵魂——他知道，自己不得不再次回到拉斯维加斯，只有在那里，他才能找到最终的解脱和真正的自由。',NULL,3800000,111731,2.559806,5.9,18,84,'2009-06-10','en','/fFW0KMESYWfI74UAZ5gc3Ct8MBI.jpg',2.4774681886075847,3,'2026-09-10',2,NULL,NULL),(27029,'修女传','The Nun\'s Story','《修女传》由四度夺得奥斯卡金像奖的导演弗雷德·金尼曼执导，是奥黛莉·赫本的代表作之一，曾荣膺奥斯卡最佳影片等八项提名。  　　女主角嘉比雅（奥黛丽·赫本 Audrey Hepburn 饰）投身修道院，学习教会的戒律变成璐克修女。其后被送到医学院学习当护士，毕业后派到非洲的比属刚果服务。在那儿她认识了无神论的医生福图纳提，引起了她对宗教信仰的质疑。不久璐克生病，病后被送回比利时，当时正值二次世界大战爆发，医院旁炮声隆隆，修女们却不顾个人安危继续工作。比利时沦陷后，璐克参加了敌后工作，爱心使她无法保持修道者的沉默和自制。当她听到父亲被杀害的消息时，撤去了她修女的誓愿，请求还俗退出了修道院。','Her Faith Remained Strong and True in the Face of Africa\'s Terrors!',3500000,12800000,3.281509,7.4,46,149,'1959-06-18','en','/4vNWFhPyjTehPpZsvTnTywwXSiF.jpg',2.7002676721996415,3,'2026-09-10',2,NULL,NULL),(27191,'戏王之王','The Greatest Show on Earth','故事描述一个在财政上出现问题的马戏团，为了让团员继续作一整季的表演，签下了有着名空中飞人圣巴斯蒂安加盟的演出。这使一心想在新一季成名的女空中飞人哈莉大为不满，另外经理布莱特为了事业一直刻意冷落暗恋他的哈莉。蒂安却因一次表演危险性高的动作发生意外，跌断了一只手而断送了表演前途。同时一名十年前失手杀妻的医生以小丑身份在马戏团里表演，后因火车翻覆而救布莱特，被警察发现。哈莉因此而被感动，于是对布莱特重燃爱火，并负起整顿马戏团表演的工作。',NULL,4000000,36000000,8.988455,6.6,50,152,'1952-01-10','en','/cKI0yGPRh1IlvRKKJRoMZruior8.jpg',2.717490696895367,3,'2026-09-10',2,NULL,NULL),(27205,'盗梦空间','Inception','道姆·柯布与同事阿瑟和纳什在一次针对日本能源大亨齐藤（渡边谦 饰）的盗梦行动中失败，反被齐藤利用。齐藤威逼利诱因遭通缉而流亡海外的柯布帮他拆分他竞争对手的公司，采取极端措施在其唯一继承人罗伯特·费希尔的深层潜意识中种下放弃家族公司、自立门户的想法。为了重返美国，柯布偷偷求助于岳父迈尔斯，吸收了年轻的梦境设计师艾里阿德妮、梦境演员艾姆斯和药剂师约瑟夫加入行动。在一层层递进的梦境中，柯布不仅要对付费希尔潜意识的本能反抗，还必须直面已逝妻子梅尔的处处破坏，实际情况远比预想危险得多……','',160000000,825532764,50.9672,8.373,13752,148,'2010-07-15','en','/89W962aAnPS3N3BdKgy2BvUhnCh.jpg',4.6634054884835425,3,'2026-09-10',2,NULL,NULL),(27322,'爱琼斯','Love Jones','故事发生在芝加哥，描写一对受过高等教育的中产阶级黑人情侣，爱情生活的起起落落。达瑞（劳伦斯泰特，「何苦坠入情网」）是个才华洋溢的年轻诗人，妮娜（妮雅朗）则是位美丽聪明的摄影师，两人都在芝加哥过著玩世不恭的自由生活。一日，两人在酒吧中一见锺情，第一次约会开始就打得如火如荼，但双方都不确定这到底是真爱，还是只有三分钟热度。他们都觉得自己在情感上很脆弱，禁不起对爱情许下承诺，根据以往的经验，两人都否定了这段爱情。为了试验达瑞斯的用情有多深，妮娜决定展开一连串复杂的爱情考验...这对欢喜冤家是否能破镜重圆呢？','Get Together. Fall Apart. Start Over.',10000000,0,1.000178,8.1,12,104,'1997-03-14','en','/iuwimPkDm7kfptKm5zlK0pIzqXM.jpg',2.4027014388158348,3,'2026-09-10',2,NULL,NULL),(27329,'暹罗王后','สุริโยไท','During the 16th century, as Thailand contends with both a civil war and Burmese invasion, a beautiful princess rises up to help protect the glory of the Kingdom of Ayothaya. Based on the life of Queen Suriyothai.',NULL,0,0,0.843067,5.1,6,185,'2001-08-17','th',NULL,2.25577535667879,3,'2026-09-10',2,NULL,NULL),(27342,'猛虎出山','Malone','中情局杀手想金盆洗手是多么的艰难......','Ex-Cop, Ex-CIA, Explosive',0,0,1.610132,6.8,15,92,'1987-05-01','en','/uA32G48OnKutmWdifMSi9hp2jed.jpg',2.443681033782056,3,'2026-09-10',2,NULL,NULL),(27360,'国王的赎金','King\'s Ransom','安东尼·安德森饰演一位富有的自恋商人，人人都讨厌他。当前妻企图在离婚协议中榨干他的钱财时，他与糊涂的情妇及其有前科的兄弟合谋，伪造了自己的绑架案。然而当那些憎恨他的人也策划绑架行动时，他的阴谋彻底失控了。',NULL,0,0,5.079017,5.1,14,95,'2005-04-22','en','/lH8Nugl7DnMaMHfOChEFNXXQ3zX.jpg',2.427701068637508,3,'2026-09-10',2,NULL,NULL),(27374,'蒙哥湖','Lake Mungo','2005年12月的一天，帕尔默一家四口在澳大利亚阿拉拉特山脉附近的水库休闲度假，然而厄运突然降临，帕尔默家16岁的女儿爱丽丝（塔莉娅·扎莫 Talia Zucker 饰）在游泳时突然失踪。此后不久，搜救队找到了爱丽丝的尸体，帕尔默一家度过了一个充满悲痛、永生难忘的圣诞节。悲伤尚未退却，恐怖的气氛却又肆意弥漫。在爱丽丝下葬后的第10天，诡异现象开始在帕尔默家频频出现。他们能够感觉到，死去的女儿重新回到家中。莫大的恐惧萦绕心头，盘桓数月，经久不散。他们希望尽快摆脱这无尽的梦魇……  　　本片采用纪录片形式拍摄，并荣获2008年东京国际电影节丰田地球奖特别奖。','If you\'ve never seen a ghost... Look closer.',0,0,4.653047,6.1,90,84,'2008-06-17','en','/g0zCELYfBfSv8TOGC13buABVN53.jpg',2.823515620443152,3,'2026-09-10',2,NULL,NULL),(27380,'未来先锋','MegaForce','Megaforce is an elite multi-national military unit that does the jobs that individual governments wont. When the peaceful Republic of Sardun in under threat from their more aggressive neighbour the beautiful Major Zara (Persis Khambatta) and General Byrne-White (Edward Mulhare) see the help of Ace Hunter (Barry Bostwick) and Megaforce.','Deeds not Words',0,0,1.110179,3.5,15,99,'1982-06-25','en','/hX5p2thHjpARwAs6MvBlrrvwutL.jpg',2.4225640720497443,3,'2026-09-10',2,NULL,NULL),(27404,'My Big Fat Independent Movie','My Big Fat Independent Movie','This film is a spoof along the lines of \"Scary Movie\" and \"Not Another Teen Movie.\" It includes parodies of some of the indie film world\'s most renowned movies such as \"Memento,\" \"Pulp Fiction,\" \"Magnolia,\" \"My Big Fat Greek Wedding,\" \"Amelie,\" \"Run Lola Run,\" \"El Mariachi,\" \"The Good Girl,\" \"Pi,\" \"Swingers\" and many others.','The lowbrow comedy for the highbrow crowd.',0,0,0.68822,3,5,80,'2005-03-04','en','/xPmQ4BCANMoiS7bvQU5wdFFqsUR.jpg',2.218064184750669,3,'2026-09-10',2,NULL,NULL),(27420,'血溅毕业日','Graduation Day','一名田径运动员在完成 30 秒 200 米比赛后死亡，一名蒙面杀手开始谋杀学校田径队的学生。','Some kids are dying to graduate...',0,0,1.452199,5,22,96,'1981-05-01','en','/bbNtkM0oFTCnFfblOzeEuaDUaZB.jpg',2.5081780768238713,3,'2026-09-10',2,NULL,NULL),(27451,'哈佛人','Harvard Man','College has always been a time for experimentation, sexual, cultural and otherwise. \"Harvard Man\" plays out against a background of love, sex, basketball, crime and experimentation. Action and philosophy in young people\'s quest to discover their true identity.','Passion, Seduction, Deception.',0,0,5.336243,4.8,15,99,'2001-01-01','en','/vxZG1UXh8gA3nYmrPNUWCHGGBFn.jpg',2.440086161693422,3,'2026-09-10',2,NULL,NULL),(27455,'Foolish','Foolish','\'Foolish\' Waise is a talented comedian with a hard-edge trying to make it in the comedy clubs in LA while his brother is a hard-nosed gangster trying to make it on the streets. With all the competition they face in their chosen \"professions,\" their biggest battle is with each other over the love of a pretty girl.','This big mouth is ready for the big time',0,6033999,0.796009,6.3,3,84,'1999-04-09','en','/bCBsJyLnZbnlfwooB5733LLXF24.jpg',2.1368612016729536,3,'2026-09-10',2,NULL,NULL),(27549,'兽王伏魔2：穿越时空之门','Beastmaster 2: Through the Portal of Time','Mark Singer returns as Dar, the warrior who can talk to the beasts. Dar is forced to travel to earth to stop his evil brother from stealing an atomic bomb, and turning their native land from a desert into... well... a desert! Written by Jim Palin',NULL,6000000,869325,1.478505,4.6,17,107,'1991-06-08','en','/3bIxjt2uyyeinjU23k115YPhXe1.jpg',2.4544470467624997,3,'2026-09-10',2,NULL,NULL),(27551,'伏魔神将','The Barbarians','一对孤儿兄弟 Kutchek 和 Gore 被拥有强大珠宝的 Canary 领导的部落收养。 邪恶的卡达尔想要金丝雀和珠宝。 他在袭击部落时绑架了金丝雀，但石头躲过了他。 兄弟俩被带去接受角斗士的训练，多年后长得非常高大。 他们逃脱并开始寻找宝石并营救金丝雀。','Warriors. Conquerors. Heroes.',0,0,1.631993,5.1,8,87,'1987-03-01','en','/dYr9p8YOOw5gERVpg8cJHA5PsnY.jpg',2.3113313804629136,3,'2026-09-10',2,NULL,NULL),(27569,'良医妙药','Extraordinary Measures','约翰·克罗雷和妻子艾琳育有三个子女，除大儿子之外，另两个孩子都患有庞贝氏症。在二女儿的一次并发症发作濒危抢救后，约翰冲动之下飞去了内布拉斯加大学求见庞贝氏症研究领域中的领先专家罗伯特·斯通希尔教授，并许诺将成立庞贝氏研究基金，支持斯通希尔教授的研究，尽快将理论成果用于药物实践。不通人情的斯通希尔教授为约翰一家的真诚所动，决定辞职与约翰共同建立生化创业公司，致力于庞贝氏症药物的研发。为了给新公司拉投资，约翰不得不克服一系列困难，甚至频频惹恼已经极难相处的斯通希尔教授，全力以赴和死神赛跑。','Don\'t hope for a miracle. Make one.',31000000,15134293,6.487344,6,89,105,'2010-01-21','en','/tgeJ4xurJPr7mqxIF7stR4GblhS.jpg',2.822043859415054,3,'2026-09-10',2,NULL,NULL),(27573,'赏金猎手','The Bounty Hunter','因沉迷赌博而负债累累的赏金猎手米洛·博伊德（杰拉德·巴特勒 Gerald Butler 饰）接到工作追捕自己的前妻，记者妮可·赫莉（詹妮弗·安妮斯顿 Jennifer Anniston 饰）。妮可因追踪一件离奇自杀事件，错过自己袭警交通案的出庭而被法院通缉。对自杀事件内情紧追不舍的她想尽了一切办法逃跑，使得本来就因彼此憎恨而离婚的两人关系更加糟糕，直到有神秘杀手突然出现要至妮可于死地。米洛这才发现自己对妮可一直不能忘情。为了保护妮可的安全，米洛带她来到了二人当初渡蜜月的“丘比特庄园”，前尘往事涌上心头，二人也都对是否应重续前缘而举棋不定。与此同时，米洛的赌债和妮可的调查只将情况搞得更加复杂……','It\'s a Job. It Isn\'t Personal. Well, Maybe a Little...',40000000,136000000,33.747825,5.5,858,110,'2010-03-16','en','/jFOlqWmzR56GW08EEjH6ykxvsfV.jpg',3.2784693550859405,3,'2026-09-10',2,NULL,NULL),(27576,'特工绍特','Salt','作为一名中央情报局的女特工，伊夫林·绍特（安吉丽娜·朱莉饰）发誓要忠于她的责任、荣誉和国家。然而，当一个叛徒在审问后，诬蔑绍特就是一个俄国间谍，并透露一起秘密计划时，她的忠诚度需要经受巨大的考验。为了证明自己的清白，绍特被迫逃亡，而她昔日的同事温特尔（列维·施瑞博尔 饰）与皮博迪（切瓦特·埃加福特饰）则奉命将她捉拿归案。绍特使用她所有的技能和经验躲避追捕，并试图查明真相，证明她的清白，随着她一步步揭开真相，却对自己的身份也产生了疑惑，究竟，究竟绍特是谁？','Who is Salt?',110000000,293329073,48.829437,6.2,2093,100,'2010-07-21','en','/mWNEFuPtmzOF3JwtCpW1Kg6Dn21.jpg',3.6252555783808122,3,'2026-09-10',2,NULL,NULL),(27578,'敢死队','The Expendables','美国政府想雇人深入南美某国推翻当地的独裁统治，但是却没人敢接受这样的任务，最终这个任务落到史泰龙率领的一支特别行动小组身上。\r 史泰龙饰演的头领巴尼·罗斯是个没什么可以失去的男人，他深谋远虑却又愤世嫉俗，他唯一信任的伙伴就是他那辆破旧的卡车、水上飞机和他忠诚的小队。他的队员Lee Christmas（杰森·斯坦森饰）是名SAS成员；Bao Thao(李连杰饰)是个近身搏斗高手；Hale Caesar（泰瑞·克鲁斯饰）这个和巴尼·罗斯相熟10年家伙是个远距离武器专家；Toll Road（兰迪·库卓饰）精通爆炸，并且是团队的智囊；最后是Gunnar Jensen（杜夫·朗格饰）一个精通狙击的老兵，但却需要时时刻刻与自己的心魔作斗争。','Choose Your Weapon.',80000000,274470394,77.580661,6,2926,103,'2010-08-03','en','/j09ZkH6R4JWVylBcDai1laCmGw7.jpg',3.7171546335151473,3,'2026-09-10',2,NULL,NULL),(27579,'美国人','The American','------在《美国人》中,克鲁尼饰演一位独自行动、技术高超的杀手,名叫杰克。当杰克在瑞典完成了一个任务之后,又一个更艰巨的任务等待着他——他会被派往美国去暗杀。他对他的联系人拉里发誓,这将是他的最后一票。杰克来到意大利乡下的某个小城,享受暂时远离死亡的时光。然而,那份由比利时女人 Mathilde(斯科拉·鲁特饰,出演过《杀手没有假期》)委任的工作刻不容缓。令人惊讶的是,杰克找到了当地的好友、神父Benedetto叙旧(意大利老演员Paolo Bonacelli饰),又和当地的女人Clara(薇奥兰特·普拉西多饰)继续着浪漫的关系。但是,杰克的冒险生涯即将开始……',NULL,20000000,65464324,18.632156,5.8,481,104,'2010-08-31','en','/y78XxwoXhczxEZHOvhjo343yPDk.jpg',3.180567420911971,3,'2026-09-10',2,NULL,NULL),(27581,'二流警探','The Other Guys','道恩·强森和塞缪尔·杰克逊饰演一对超级警察，他们是警局里的超级精英，所以他们不但是部门的骄傲，也使得位于\"第二档次\"的威尔·法瑞尔和马克·沃尔伯格也对他们羡慕不已。一次偶然机会，却让他们得以替补偶像出更，两人自然不会放过这个出头的机会……','When the cops are busy... Our only hope is...',100000000,170432927,24.399642,6.1,1383,107,'2010-08-06','en','/nNiw5cVq6EjB03v2PwhoihM7pVF.jpg',3.45760652828267,3,'2026-09-10',2,NULL,NULL),(27582,'机械师','The Mechanic','稳定的心态，精妙的手法，杀人于无形，这是一个顶尖杀手的必备特质。亚瑟（杰森•斯坦森Jason Statham 饰）入行多年，在自己以前的搭档哈里（唐纳德•萨瑟兰Donald Sutherland 饰）的帮助下，已经成为一个出色的杀人机器。亚瑟接到一项新任务，暗杀对象是哈里。虽然亚瑟不忍下手，但在清楚的得知哈里难逃一死之后，最终还是决定亲自送哈里一程。哈里的儿子史蒂夫（本•福斯特 Ben Foster 饰）为了替父报仇，决意要跟随亚瑟学习。在亚瑟的训练下，史蒂夫逐渐掌握了作为一个机械师所必备的技能，与亚瑟合作完成一项又一项暗杀任务。虽然亚瑟从未告诉史蒂夫杀害哈里的凶手，但史蒂夫还是知道了其父被害为亚瑟所为，复仇的火焰在史蒂夫心中逐渐升腾……','Someone has to fix the problems.',40000000,51070807,44.094856,6.3,1045,93,'2011-01-13','en','/vB3hhRricKBRcygAh35hxLcyXJW.jpg',3.4773959802141055,3,'2026-09-10',2,NULL,NULL),(27585,'兔子洞','Rabbit Hole','贝卡和豪伊是一对幸福的夫妻，就在8个月前，他们还有一个美满的家庭。他们的儿子丹尼在车祸中不幸遇难，突如其来的打击彻底改变了他们原本完美的生活。从噩梦中醒来后，回到了现实生活中，夫妻俩沉浸在回忆、渴望、愧疚中，相互指责挖苦，无法从痛苦中解脱。贝卡开始重新定义自己的生活，她变得苦闷，尖刻，有时甚至有些滑稽，居然和肇事司机杰森发展出了神秘的关系，杰森是一个忧虑的漫画书作家，正处在青春期。和杰森的交往让贝卡暂时从丹尼的痛苦回忆中解脱出来。与此同时，豪伊整日沉湎于过去，并努力从外人那里寻找贝卡无法给予他的安慰。尽管这样，夫妻俩还在努力找回充满欢笑和幸福的美好生活。这段历程反映了两个人从脱轨的生活中重新接受彼此的过程。','The only way out is through.',5000000,5129058,10.095184,6.9,165,91,'2010-12-16','en','/6BrzY5kFGkAVHClDhzW3gaH8Co7.jpg',3.0105208231160074,3,'2026-09-10',2,NULL,NULL),(27586,'逃亡乐队','The Runaways','在20世纪70年代以前，摇滚乐还是男性的天下，即使它的影响力以遍及世界各地，但全女子的摇滚乐团却从未出现。18岁的琼·杰特（克莉丝汀·斯图尔特 Kristen Stewart 饰）是一个狂迷摇滚乐的叛逆女孩，她始终渴望组建一支女子摇滚乐团。在经纪人金·弗利（麦克·谢农 Michael Shannon 饰）的帮助下，他们找到了15岁的切丽·柯里（达科塔·范宁 Dakota Fanning 饰）——与琼同样来自南加州且喜爱大卫·鲍伊的女孩——担任主唱。在此之后，吉他手丽塔·福特（Scout Taylor-Compton 饰）、鼓手珊蒂·韦斯特（Stella Maeve 饰）、贝司杰基·福克斯先后入队，全女子乐队“逃亡”正式成立。女孩们由此展开了多姿多彩、忧喜相伴的音乐之旅……','It\'s 1975 and they\'re about to explode.',10000000,2995811,17.611971,6.3,254,106,'2010-03-19','en','/byeTXKg9paqiFQbtfI28FOIhebg.jpg',3.0918163253477187,3,'2026-09-10',2,NULL,NULL),(27588,'勿忘我','Forget Me Not','又是一年毕业季，金发美女桑迪·切宁（卡莉·许洛德 Carly Schroeder 饰）和英俊帅气的弟弟伊莱（科迪·林雷 Cody Linley 饰）学业无忧，前途光明。夜幕降临，姐弟二人和莱克丝（Jillian Murray 饰）、蕾拉（Chloe Bridges 饰）、查德（Zachary Abel 饰）、汉娜（Brie Gabrielle 饰）等好友聚在一起饮酒狂欢。兴之所至，他们驱车来到墓地玩抓鬼游戏。游戏刚要开始，一名陌生女孩（Brittany Renee Finamore 饰）突然出现要求加入他们。谁知之后女孩问桑迪是否记得她之后，纵身从悬崖边跌落下去。受到惊吓的年轻人们叫来警察搜查，结果一无所获。',NULL,0,0,5.065752,5,66,103,'2009-10-22','en','/jDux50AIllCTIeAwg8wJ32oN1EE.jpg',2.7306608565241257,3,'2026-09-10',2,NULL,NULL),(27686,'坠入爱河','State Fair','这是一部想当令人愉悦的歌舞片，获1946年奥斯卡最佳音乐歌曲奖和最佳音乐—音乐片配乐提名奖！  在美国中心地带，一年一度的“爱与欢笑”的盛会又要举行了，弗雷克一家报名参加，每一个人都想获得大奖 。父亲带着心家的宠物猪参展，一心要获得头奖蓝丝带奖。妈妈也参加了烤馅饼比赛。最开心的是孩子们，因为他们在盛典上找到了自己的真爱。',NULL,0,0,1.847822,6.2,19,96,'1945-08-29','en','/cmy55K7Qs1WQeGPksHBphjyjh3b.jpg',2.4891846352039595,3,'2026-09-10',2,NULL,NULL),(27723,'九九九玉女寻凶','Psycho Beach Party','一个人格分裂的妹子Florence和闺蜜一起看露天电影的时候，遭遇了一起凶杀案。\r 　　没过几天，她受到朋友的邀请，去海滩度假。在这次party上，又接连发生了好几次凶杀案，而且每次她都精神分裂成一个叫Ann Bowman的彪悍女。','Party till you drop. Dead.',1500000,0,2.855963,6,26,95,'2000-08-06','en','/28mzKFDyVzMVx9nhDrJQ3G2H7It.jpg',2.554823603600358,3,'2026-09-10',2,NULL,NULL),(27759,'北京55日','55 Days at Peking','1900年北京，慈禧太后当权、中国领土四分五裂。端亲王力主出兵，并派义和团围困外国使馆，当千军万马兵临城下之际，美国军官义无反顾，率领各国联军作困兽之斗，终于扭转命运，杀出重围。','A handful of men and women held out against the frenzied hordes of bloodthirsty fanatics!',17000000,10000000,3.321095,6.3,36,154,'1963-05-06','en','/uR0xaqmqlbhatf9014mHuwV1Uly.jpg',2.62811678802389,3,'2026-09-10',2,NULL,NULL),(27845,'伤心树屋','Trees Lounge','汤米失去了工作、爱情和生活。他住在 \"树木酒廊\"（Trees Lounge）楼上的一间小公寓里。他找了一份开冰淇淋车的工作，结果和前女友 17 岁的侄女发生了关系。这让他和她的父亲陷入了严重的麻烦之中。',NULL,0,0,3.443916,6.7,51,95,'1996-10-11','en','/2DtoVhI9RkArGbzkvctGxY578QN.jpg',2.711180980389125,3,'2026-09-10',2,NULL,NULL),(27936,'尽情游戏','Micmacs à tire-larigot','在这出讽刺意味浓厚的喜剧片里，丹尼·伯恩饰演了一位企图捣毁一起军火交易的绅士。一个男人中了一枪，大难不死，联合了一帮奇奇怪怪的朋友，准备迎头痛击那个敌人。这是一个错综复杂，却又相当新颖的复仇计划，必然使他们按捺不住激动。他们还发现，敌人不仅是一个非法军火商，还是一起秘密的军火交易。','Non Stop Madness',33000000,14000000,7.663515,6.8,148,100,'2009-10-28','fr','/hmBpoe4MHkYIcm4buDZw0ayR5Gg.jpg',2.9727038061264768,3,'2026-09-10',2,NULL,NULL),(27983,'欢乐满堂','Yours, Mine and Ours','讲述弗兰克是一名海军上将，妻子去世后，他独自抚养着八个孩子。一次邂逅，弗兰克遇到了寡居的女设计师海伦，并很快和这位性格独立的漂亮妈坠入爱河，柔情蜜意的两人准备组建一个全新的家庭，准新娘也带来了自己的十个孩子。不过这群小鬼可不像父母那样投缘，不仅互相看不顺眼，对即将成为继父或继母的弗兰克和海伦也不是那么爽歪歪，于是他们准备各显神通的大闹一场，借此拆散父母的这段婚姻。','Their wedding night set new attendence records',0,0,2.094151,6.2,26,111,'1968-04-24','en','/ejbrAFkAHP5W5mzI8wA0zUTcDdg.jpg',2.5551512603227984,3,'2026-09-10',2,NULL,NULL),(27995,'稳操胜券','She\'s Gotta Have It','诺拉•达林是个住在纽约布鲁克林区的年轻黑人妇女。她与三个男人有性关系：体贴但保护过度的杰米；富有但傲慢的格里尔；风趣但幼稚的马斯。三人都想独占她的爱，但诺拉想维持她的独立，拒绝选定一个单一伴侣。三个追求者的急躁——和不安全感——迫使她做出选择，但不久后，她开始怀疑自己是否选择了那个正确的人，甚至怀疑她到底需不需要一个男人。','A Seriously Sexy Comedy',0,0,6.722213,6.1,25,84,'1986-08-08','en','/qiJuXvPONqTSSnzhbCBqE7EotV.jpg',2.556498411145465,3,'2026-09-10',2,NULL,NULL),(28005,'欲望和智慧','Kama Sutra: A Tale of Love','宫女玛雅（英迪拉·瓦尔玛 Indira Varma饰）自幼和公主塔拉（萨莉塔·乔德霍里 Sarita Choudhury饰）生活在一起，形影不离。她们拥有共同的口味、习惯以及爱好，直到多年之后，二人仍然保持着超越身份地位的深厚友谊。然而这一切都被强烈的嫉妒心和爱欲，瓦解得不堪一击。  公主塔拉嫁给了当地王子拉杰·辛格（纳威恩·安德利维斯 Naveen Andrews饰），拉杰很快就会成为王位继承人。然而在结婚之后，不甘寂寞的拉杰很快就厌倦了与塔拉的夫妻生活，他开始寻求其他女人来满足自己的性需求。能歌善舞的玛雅一下子就吸引了拉杰的注意力，拉杰被她的美貌与妖媚迷得神魂颠倒。玛雅开始作为拉杰的妾侍侍奉左右。将一切看在眼里的公主塔拉只能无可奈何地在一旁嫉妒。为了守护她的婚姻与爱情，玛雅被赶出宫廷。流浪的玛雅被宫廷雕刻师杰·库马尔（拉蒙·蒂卡拉姆 Ramon Tikaram饰）发现，几经接触，玛雅逐渐爱上了这位英俊而有才华的杰·库马尔。',NULL,3000000,4109095,3.937939,5.7,35,117,'1996-09-11','en','/kUaWgLrI7HqpPqPxgR54wSGokCV.jpg',2.61525377320375,3,'2026-09-10',2,NULL,NULL),(28029,'月球漫步','A Walk on the Moon','沃尔（戴安·琳恩 Diane Lane饰）和马迪（列维·施瑞博尔 Liev Schreiber饰）是一对幸福的夫妻，然而工作忙碌的丈夫和日益平淡的生活，却令这段婚姻潜伏着某种危机。在阿波罗号成功登月的那年，妻子沃尔偶然陷入了一段新鲜而缠绵的婚外情，和仪表不凡的威克（维果·莫特森 Viggo Mortensen饰）难舍难分，腹中甚至有了他的骨肉。  　　家庭的责任和丈夫的爱始终牵绊着沃尔的心，婆婆的劝说也让她终于立下决心回归家庭。要告别一段浪漫的爱情，回到心如止水的家庭生活中，让沃尔陷入了极度痛苦的挣扎当中。当丈夫和女儿都知道了沃尔的婚外恋，事情变得一发不可收拾，作为妻子和母亲，作为威克的情人，沃尔陷入了两难境地。','It was the summer of Woodstock... when she became the woman she always wanted to be.',14000000,0,6.370267,6.2,21,107,'1999-01-29','en','/6aNMyAP82sDoVFmopFzGDWeVVne.jpg',2.520279320295922,3,'2026-09-10',2,NULL,NULL),(28053,'城市岛屿','City Island','纽约附近城岛的监狱看守文斯（安迪·加西亚 Andy Garcia 饰）瞒着老婆乔伊斯（朱丽安娜· 玛格丽丝 Julianna Margulies 饰）到城里上表演课，梦想成为一名演员。乔伊斯瞒着文斯抽烟，女儿和儿子也都有自己的大小秘密，一家人各自为政。有一天文斯发现新转来的犯人汤尼（史蒂文·斯崔特 Steven Strait 饰）竟是自己遗弃二十多年的儿子。文斯把汤尼带回了家，向所有人隐瞒了事实，希望能利用假释好好照顾这个儿子，让他重返正途。与此同时，在表演课同学莫莉（艾米莉·莫迪默 Emily Mortimer 饰）的鼓励下，文斯参加了一次重要的电影角色面试，没想到这却引起了乔伊斯的误会，造成了家庭危机大爆发……\r 　　本片获纽约曼哈顿特里贝卡（Tribeca）电影节观众票选奖。','Truth is stranger than family',6000000,6670712,6.497285,6.9,113,104,'2009-03-06','en','/t7LJY2LCcGRLP9E4QbwBkLpZ2W7.jpg',2.908798763225277,3,'2026-09-10',2,NULL,NULL),(28089,'The Messenger','The Messenger','Will Montgomery (Ben Foster), a U.S. Army Staff Sergeant who has returned home from Iraq, is assigned to the Army’s Casualty Notification service. Montgomery is partnered with Captain Tony Stone (Woody Harrelson), to give notice to the families of fallen soldiers. The Sergeant is drawn to Olivia Pitterson (Samantha Morton), to whom he has delivered news of her husband’s death.','The Scars of War Will Last Forever',6500000,1521261,8.432401,7.1,119,113,'2009-11-13','en','/p4fJyH7mMbasiFYwiw2nE7D6pMY.jpg',2.9342304865579414,3,'2026-09-10',2,NULL,NULL),(28121,'A Thin Line Between Love and Hate','A Thin Line Between Love and Hate','Nightclub manager Darnell Wright is a perpetual playboy who is almost as devoted to his job as he is to the pursuit of beautiful women. After he sets his sights on the ultra-classy Brandi Web, he launches an all-out assault to win her heart. Ultimately, charm, lust and passion prevail, but Darnell learns the hard way that when you play, you pay. Brandi is much harder to get rid of than she was to get--especially when she realizes that she has a rival vying for Darnell\'s affection. When he finally decides to call it quits, Brandi becomes an obsessed femme fatale stalking the new love of her life.','When you play, you pay.',0,0,2.088251,5.7,15,108,'1996-04-04','en','/wo9AGi5LlFXZUj8MDPq3eKCUMpd.jpg',2.438114828097627,3,'2026-09-10',2,NULL,NULL),(28165,'毒魔复仇2','The Toxic Avenger Part II','毒魔被邪恶的天启公司引诱到日本东京。因此，当毒魔在东京打击犯罪时，天启公司在特罗马维尔传播邪恶。',NULL,0,0,1.791331,5.3,39,96,'1989-02-24','en','/m5o7B3VSAjvinjtSYxXD38senvb.jpg',2.6265153705368425,3,'2026-09-10',2,NULL,NULL),(28178,'忠犬八公的故事','Hachi: A Dog\'s Tale','八公 是一条谜一样的犬，因为没有人知道它从哪里来。教授帕克 在小镇的火车站拣到一只走失的小狗，冥冥中似乎注定小狗和帕克教授有着某种缘分，帕克一抱起这只小狗就再也放不下来，最终，帕克对小狗八公的疼爱感化了起初极力反对养狗的妻子卡特。八公在帕克的呵护下慢慢长大，帕克上班时八公会一直把他送到车站，下班时八公也会早早便爬在车站等候，八公的忠诚让小镇的人家对它更加疼爱。有一天，八公在帕克要上班时表现异常，居然玩起了以往从来不会的捡球游戏，八公的表现让帕克非常满意，可是就是在那天，帕克因病去世。帕克的妻子、女儿安迪 及女婿迈克尔 怀着无比沉痛的心情埋葬了帕克，可是不明就里的八公却依然每天傍晚五点准时守候在小站的门前，等待着主人归来……','A true story of faith, devotion and undying love.',16000000,47801389,43.217089,7.7,1717,93,'2009-06-13','en','/lsy3aEsEfYIHdLRk4dontZ4s85h.jpg',3.8843750211611208,3,'2026-09-10',2,NULL,NULL),(28211,'克洛伊','Chloe','丈夫戴维（连姆·尼森）错过了从纽约回家的航班，当然也赶不上妻子凯瑟琳（朱莉安·摩尔）为他准备的惊喜派对了，凯瑟琳只好咽下自己的失望和怀疑，独自去向等待着的宾客们解释。 　　第二天早上，她读到了丈夫以前的女学生发给戴维的短信后，凯瑟琳的恐惧开始增长，她开始怀疑丈夫是不是出轨了。她和戴维是很一对令人艳羡的夫妻，凯瑟琳是医生，戴维是音乐教授，他们还有一个17岁的儿子迈克尔（马克斯·希尔莱耶），对于外人来说他们什么都有了－－事业、金钱和家庭。但是由于他们各自的职业的性质，并且要养育孩子，他们的婚姻生活存在很多压力。而且因为、、由于缺乏沟通和亲热，他们的关系已经大不如前了。 　　在惊喜派对两周后，凯瑟琳和戴维在和朋友们吃晚餐。凯瑟琳中途去洗手间的时候碰到了迷人的年轻女郎克洛伊（阿曼达·塞弗里德），后来她们开始了简短的联系。回到餐桌旁，凯瑟琳看到克洛伊在玩“指出谁是妓女”的游戏，她饶有兴趣地看着克洛伊如何去接近一位年老的生意人。在回家路上凯瑟琳终于忍不住问起戴维他是不是故意留在纽约不回家，戴维极力否认，但凯瑟琳知道他撒谎了。 　　凯瑟琳对于戴维出轨的怀疑越来越深，她找到了克洛伊，雇佣她来测试大卫是否忠实。她们定期会面交流情况，克洛伊对自己和戴维每次相见的细枝末节毫无隐瞒，这终于点燃了凯瑟琳嫉妒的火花，也唤醒了她内心深处潜藏的对戴维的深情。在一家色情网站上看到克洛伊的资料之后，凯瑟琳意识到她正在一步步把她的家庭置于危险的境地－－现在要阻止克洛伊，她还来得及吗？','If the one you love was lying to you, how far would you go to find out the truth?',15000000,8459458,26.373864,5.9,498,96,'2009-03-25','en','/rQsFmvUKQU8mbkwRDcRIkNs0xSF.jpg',3.2171765026629955,3,'2026-09-10',2,NULL,NULL),(28260,'活死人归来3','Return of the Living Dead III','寇特为军方科学家之子，其父在军中利用特殊药剂将死人复活。某日寇特女友茱莉车祸身亡，为了让女友复活，遂利用其父的特殊技术将茱莉还魂，却不知此一技术并无法使死人真正复活，只能使死人具活动能力，成为吃人僵尸……尽管茱莉头脑清醒，尚有思想，可无法克制自己吃人的欲望，无奈之下寇特将她交给军方，不料他发现军方科学家对这些”活死人”进行残酷的人身实验，于心不忍，终将茱莉又解救出来。 二人逃跑时不小心打破了装有可以使僵尸复活气体的容器，致使僵尸全部复活，寇特不幸被怪物咬伤，得知自己也将会变成僵尸，寇特和茱莉一起走进火中，在烈火中得到永生。','She\'s to die for.',2000000,54207,7.502934,5.9,88,97,'1993-10-01','en','/lu4Eit7pR5I8hGHJmy3K9Re8FPo.jpg',2.8187406997763613,3,'2026-09-10',2,NULL,NULL),(28353,'Def Jam\'s How to Be a Player','How to Be a Player','Dray is a young playboy whose only objective in life seems to be to have sex with as many girls as he can without getting caught by his girlfriend Lisa. Dray\'s sister Jenny and her friend Katrina plan to show him that the way he lives is wrong and organize a party in Malibu, inviting all of his girlfriends.',NULL,0,13960203,1.20245,5.3,8,93,'1997-08-06','en','/1BFKMh1ogtWzGOjKTzxCD2tG0K3.jpg',2.3110020125004054,3,'2026-09-10',2,NULL,NULL),(28355,'第39号案件','Case 39','社工艾米丽·詹金斯（芮妮·齐薇格 Renée Zellweger 饰）做着单调、繁冗的工作，她每天要和不同的家庭打交道，处理他们的子女教育问题，结果得到的抱怨远远多于感谢。原本的38宗案件已经不堪重负，上司又将第39号案件安排给她。迫于责任，疲惫的艾米丽依旧驱车前往小女孩莉莉·沙利文（祖蒂·弗兰 Jodelle Ferland 饰）的家中。一如既往，艾米丽受到不友好地对待，在此之外，这个家庭的怪异气氛又让她倍感焦虑。有感于莉莉的孤独和无助，艾米丽更为主动地参与到这个案件中来。在一个残酷的虐待之夜，她和同事从莉莉的父母手中将小女孩成功解救。','Some cases should  never be opened.',27000000,29000000,23.917982,6.1,563,109,'2009-08-13','en','/qENeG8cFU9VufsV7ib7eULY0jQu.jpg',3.2624063812533293,3,'2026-09-10',2,NULL,NULL),(28580,'失去的周末','The Lost Weekend','改编自查尔斯．杰克逊的同名小说，也是讽刺喜剧导演比利怀尔德的一部严肃的作品。 　　描述有才华的知识分子唐包翰是个自尊心很容易受挫的人，在一次退稿的打击后开始酗酒。后遇女友海伦，爱情的力量使唐把酒精抛开，但由于海伦的父亲批评他醉生梦死，使他再次失去自信，沉溺在酒精中不能自拔。后来他失去生存的勇气，想要自杀，在海伦的极力劝阻和鼓励下，又使他重新燃起生活的希望。 　　这是美国影史上出现的第一部以严肃态度探讨酗酒问题的电影。 　　影片开始的第一个镜头是纽约市高楼大厦的全景，暗示这是一个有普遍性的故事。编导单刀直入切进主题，紧盯着男主角在这个三天的长周末饱受酒精折磨的遭遇，将酒徒的精神状态和肉体行为都刻划得入木三分。','The screen dares to open the strange and savage pages of a shocking bestseller!',1250000,11000000,6.903314,7.4,112,101,'1945-11-25','en','/yL6EJxPeYIcB9TChm56lHqXKzHC.jpg',2.927559446154037,3,'2026-09-10',2,NULL,NULL),(28665,'名扬四海','Fame','根据1980年艾伦-帕克导演的经典歌舞片《名扬四海》改编。在纽约表演艺术高中，年轻人的任何梦想都将可能被实现。无论是舞蹈、歌唱、表演或是拥有其他艺术才华的学生们都将可能在这里得到实现自己艺术梦想的宝贵机会。在舞蹈、歌唱、表演等着有天分并期待着能在艺术方面有所建树的几个年轻人，马可（阿什·布克 Asher Book 饰）、罗茜、尼尔、凯文、丹尼斯（娜图里·劳顿 Naturi Naughton 饰）以及珍妮（凯·帕娜贝克 Kay Panabaker 饰）等，心怀希望来到了这里。 然而，在孩子们入学之初便遭遇了及其严格的考核：来自自己内心不坚定的意志的折磨，使得他们原有的激情都面临考验。另外，青春校园中从来就不缺乏的青春躁动、同学友谊、爱情的萌芽、以及种种对于成功失败的处理方式，都让前来参加入学应试并最终在这所学校里走到一起的孩子们茁壮成长……',NULL,0,0,7.668063,5.5,135,107,'2009-01-01','en','/2jtSvunlKTRyEo2its5ba44pXBU.jpg',2.889332262098892,3,'2026-09-10',2,NULL,NULL),(28666,'The Woman Chaser','The Woman Chaser','A 1950s used-car salesman (Patrick Warburton) wants to make a low-budget film about a trucker who accidentally runs down a child.',NULL,0,0,0.619979,4.9,4,90,'1999-10-08','en','/n7YRKEz7wsT11DX9UhLuoyN8NYw.jpg',2.1826968277216596,3,'2026-09-10',2,NULL,NULL),(28902,'在梦中','In Dreams','《在梦中》是美国1999年罗伯特·唐尼主演电影，影片讲述的是在一个平静的新英格兰小镇中，出现了一名恐怖的连续杀人凶手，这名凶手出现在克蕾儿的梦中，克蕾儿发现他的梦能预知凶手的下一步行动，但她的丈夫和心理医生以及警方都不相信她拥有这种预知能力，克蕾儿必须单独面对杀人凶手，以阻止下一个命案的发生，该影片于1999年01月15日在美国上映。','You don\'t have to sleep to dream',0,0,3.226243,5.4,44,100,'1999-01-15','en','/q3Q00fCgeZGjAYaiwbfTMuIrUb0.jpg',2.65558031667248,3,'2026-09-10',2,NULL,NULL),(28932,'拳头大风暴','F.I.S.T.','约翰尼科瓦克在上世纪30年代加入了运输工人工会的一个地方分会，并在组织中一步步晋升。随着他地位的不断提升，他的手段变得更加残酷，最终参议员麦迪逊展开了一场运动，试图揭露他与黑手党的所谓联系的真相。',NULL,11,11,3.375208,6.4,29,145,'1978-04-26','en','/yiqQHB0vZg9O6z7VvAefV3fSPqX.jpg',2.5833536957032375,3,'2026-09-10',2,NULL,NULL),(29015,'The Specials','The Specials','America\'s 7th Best Superhero Team, the Specials, are a group of geeks and oddballs. We get to see one day in their lives as fan and new member Nightbird joins the group, just in time for the group to get a new line of action figures. But the members\' extreme personalities and personal issues threaten to rip the group apart.',NULL,0,0,9.055447,5.5,11,82,'2000-09-22','en','/kCoifvSC6tUa7Ia4YClf4npqjQp.jpg',2.3913234263980163,3,'2026-09-10',2,NULL,NULL),(29064,'欧米茄密码','The Omega Code','In this spiritual thriller, an ancient prophecy is about to be fulfilled as a secret code brings the world to the edge of Apocalypse. Gillen Lane (Casper Van Dien) is a expert on theology and mythology who has gained international fame as a motivational speaker.',NULL,0,2400000,1.288173,4.4,17,100,'1999-10-15','en','/vU73cxp7kxi5142nYZVzRibF5QP.jpg',2.4526439539748166,3,'2026-09-10',2,NULL,NULL),(29076,'爱情枪手','Gun Shy','著名侦探查理·梅欧突然间失去了特有的敏感度，而他精心策划的一次侦破也以失败告终，这使他对自己彻底丧失了自信，请求上级准许退休，现在他还需要完成最后一次秘密行动。查理已经处在了精神崩溃的边缘，内心甚至充满了对杀人不眨眼的黑手党头头奈斯特拉的惧怕。查理向心理医生寻求帮助。幸运的是，他得到了医疗小组的热情帮助，特别是护士朱蒂对他更是关心备至……','The Agency\'s best has a bad case of nerves.',10000000,1631839,3.988432,5.4,24,101,'2000-02-04','en','/3GnnrUDhYfBZOtvttzeeOp7x9fj.jpg',2.535043813663104,3,'2026-09-10',2,NULL,NULL),(29078,'赢向一生的挑战','The Game of Their Lives','影片根据真实故事改编，讲述了1950年世界杯美国队在几乎不可能的情况下以1:0战胜了实力强大的英格兰队的故事。虽然美国的足球水平根本无法和英格兰相提并论，但正是这些半职业的球员，用这个近乎奇迹的成绩向人们展示了一个道理——因为有了激情和信心，所以没有什么不可能。',NULL,0,0,2.013405,5.8,14,101,'2005-01-01','en','/iZkVLxvWfx9PzuixNnlVz1Y9fa6.jpg',2.4246585748479657,3,'2026-09-10',2,NULL,NULL),(29122,'An Everlasting Piece','An Everlasting Piece','Colin (Barry McEvoy) is a Catholic and George (Brian O\'Byrne) is a poetry-loving Protestant. In Belfast in the 1980s, they could have been enemies, but instead they became business partners. After persuading a mad wig salesman, known as the Scalper (Billy Connolly), to sell them his leads, the two embark on a series of house calls','Piece on Earth.',0,0,0.068246,6,1,103,'2000-12-22','en','/b4DApzfh4GxpDCWuS5JIyFMhXeD.jpg',1.9844069570679952,3,'2026-09-10',2,NULL,NULL),(29146,'查利','Charly','30岁的查利是个低能儿，其智力水平仅相当于6岁儿童的智商。他白天在面包房做清洁工，挣得菲薄的薪水养活自己，同时还得忍受人们对他恶意的嘲弄。为了改善自己的境遇，他一直坚持上夜校，但收效甚微。他的老师阿丽丝对他伸出了援助的手。为了让他的智力恢复正常，阿丽丝带他去看正在进行一项有关改善大脑实验的神经系统专家理查德大夫和精神病专家安娜大夫，他们的实验是让迟钝的大脑通过手术可以恢复到正常人的水平。查利决定冒险一试手术，结果十分成功，其智力不仅达到、且远远超过了正常人的水平，他成了一个天才，并和阿丽丝相爱了。他们度过了一个美好甜蜜的假期，这是查利一生中最幸福的日子。但意外总是发生。理查德和安娜大夫的下一个研究则是将恢复正常的大脑倒退回原来的迟钝，为此，他们希望查利再次同他们合作。虽然查利对这个文明社会有着强烈的不满，但他还是同意了这个荒诞的请求。在阿丽丝的陪伴下，手术后的查利回到家，等待着自己的命运：再次成为一个白痴。','A love story that begins with an incredible experiment!',950000,814666,0.178689,6.6,28,103,'1968-09-23','en','/uxGt80D4hxEEwGwdOJ5tdVvjXEC.jpg',2.570801931146076,3,'2026-09-10',2,NULL,NULL),(29193,'西班牙囚犯','The Spanish Prisoner','一位秘密工艺的发明者突然发现自己孤身一人，因为他的朋友和他为之工作的公司都与他反目成仇。','It\'s the oldest con in the book.',10000000,13835130,3.091077,7.1,73,110,'1997-09-08','en','/cwkWlWfFrvH6WW6ovX5gfGHo7ks.jpg',2.802440488307494,3,'2026-09-10',2,NULL,NULL),(29262,'沙屋','Casa de Areia','A woman is taken along with her mother in 1910 to a far-away desert by her husband, and after his passing, is forced to spend the next 59 years of her life hopelessly trying to escape it.',NULL,0,0,0.389471,6.7,9,115,'2005-05-13','pt','/6pCen50dO4Eg2cMWBoGXGMrdPWX.jpg',2.336822669003363,3,'2026-09-10',2,NULL,NULL),(29339,'尼古拉斯·尼克贝','Nicholas Nickleby','尼古拉斯•尼克贝（查理•汉纳姆 饰）的父亲死后，家中失去经济支柱。他与母亲、妹妹便到了伦敦想要投靠伯父拉尔夫，拉尔夫是个惟利是图的人，他只想从尼古拉斯身上得到最多的得意。于是尼古拉斯被送到伯父好友沃克弗德（吉姆•布劳德本特 饰），但所谓的学校里面的孩子都遭沃克弗德夫妻虐待。尼古拉斯愤怒之下，教训了沃克弗德后便带着最可怜的史迈克(杰米•贝尔 饰)离开了。\r 路上他们得到过好心人帮助。得知妹妹凯特因伯父的关系险被破坏名声，尼古拉斯回到伦敦后与伯父断绝了关系。幸运的是他得到了采瑞博兄弟的赏识，得到了收入不菲的工作。而不幸的是相处已久的史迈克因病逝世。\r 拉尔夫不甘被反抗，暗地里想办法打垮尼古拉斯，但拉尔夫的助手正义的站到了尼古拉斯那边，向他通风报信。尼古拉斯对美丽的玛德琳（安妮•海瑟薇 饰）一见钟情，拉尔夫又想从中破坏他们之间的关系。这时拉尔夫正面临破产，而且从尼古拉斯口中得知了一个多年的秘密……',NULL,0,0,5.099923,6.8,49,132,'2002-12-27','en','/uLilCY2We3Ore9Ke7CdafntHvmT.jpg',2.7079141303664467,3,'2026-09-10',2,NULL,NULL),(29371,'双姝奇恋','The Incredibly True Adventure of Two Girls in Love','蓝迪（劳蕾尔·霍勒曼 Laurel Holloman 饰）是一个外表帅气个性洒脱的女孩，不熟悉她的人很容易将其误认为男孩。蓝迪和自己的同性恋姑妈一家住在一起，对于这种外人看来无法接受的性取向，蓝迪习以为常。一次偶然中，蓝迪遇见了高中同学伊薇（妮可·阿丽·帕克 Nicole Ari Parker 饰），后者的活泼美丽让蓝迪心动不已。　　随着时间的流逝，蓝迪和伊薇之间的距离越走越近，可是，在这个民风保守的小镇里，她们只得将感情藏在心底。纸包不住火，蓝迪和伊薇的秘密终于被撞破，随即掀起了轩然大波……',NULL,0,0,1.70819,5.7,13,94,'1995-06-16','en','/dPbYJaH1j7sgj1NuA4VRyb7O4Mt.jpg',2.4085778850256148,3,'2026-09-10',2,NULL,NULL),(29406,'卡车司机','Trucker','女主人公是一个卡车司机，生活自由自在，没有任何负担。然而因为父亲突然住院，她必须接回一直由其照顾的自己11岁的儿子。由于之前长期不在一起，女主人公和儿子之间的感情已经生疏，如今住在同一屋檐下的两人矛盾不断……','Some Things in life you can\'t leave behind',2000000,0,1.20173,6.8,16,90,'2008-04-24','en','/kiOEBjIsTiGtYBDfaoaCwwXGIFP.jpg',2.45618405734108,3,'2026-09-10',2,NULL,NULL),(29426,'死人岛','Survival of the Dead','故事发生在一个丧尸的攻击已经威胁到人类存亡的世界中，作为为数不多的人类，克罗特（Alan Van Sprang 饰）决定带领自己手下的弟兄们寻找人类最后的家园。在长老帕特里克欧弗林（肯尼斯·威尔什 Kenneth Welsh 饰）的指引下，他们得知在一处偏远的海岛上还有一方净土，然而克罗特并不知道的是，他和他的部下们被卷入了一个阴谋之中。  　　来到海岛的克罗特这才发现，这里存在着新的危机，他们似乎被卷入了欧弗林家族和其对立方穆顿斯家族之间的斗争中。原来，在丧尸大规模爆发之后，欧弗林提倡将这些早已经失去了人性的怪物们赶尽杀绝，可是穆顿斯却认为，杀死这些曾经是亲人和朋友的丧尸们太过残酷，他将它们圈禁起来，期待它们能够康复。','Death isn\'t what it used to be.',4000000,0,10.789912,4.6,116,90,'2010-05-06','en','/dRKWXOUUXBPMZsbuvrJI15xiCkA.jpg',2.8301851902602273,3,'2026-09-10',2,NULL,NULL),(29427,'杀出狂人镇','The Crazies','一位杀手正在制造具有极大杀伤力的病毒，能治人于死地，或是感染的人会永远精神错乱，于是军方决定要控制这个杀手。 　　奥格登马什镇是一个坐落于宾夕法尼亚州的安宁小镇，这里被居民自诩为\"世界上最友好的小镇\"，一向风平浪静，无甚大事，大家也都安居乐业，乐得清闲。可是近日来，奥格登马什镇却人心惶惶，原因是因为小镇上的居民接二连三的开始生一种怪病，这种病发作起来，人首先会愤怒发狂，到处杀人，最后暴毙而亡，死状十分骇人。　　为了保护小镇，同时也为了保护怀有身孕的妻子妻子茱迪（拉妲•米契尔饰），镇上的治安官大卫（蒂莫西•奥利芬特饰）和下属拉塞尔（乔•安德森饰）决定要找出病因，两人很快发现病源来自于饮用水。在追查谁最有可能在水里下毒之后，大卫发现比尔（布雷特•里克比饰）最有嫌疑。ZF封锁了整个地区，不让任何人进出，无论是感染的还是没有被感染的，都被困在了这个小镇上。居民逐渐的变异感染，真正的凶手的目的到底是什么？答案逐渐的浮出水面……','Fear Thy Neighbor',20000000,54956140,28.867568,6.2,633,101,'2010-02-26','en','/gU0C85YFcpDXa6ufDtrRB3DA9En.jpg',3.312956156896016,3,'2026-09-10',2,NULL,NULL),(29461,'灵魂大补贴','Soul Food','李安的《饮食男女》被翻拍了两个版本，而黑人版就是这部《Soul Food》。跟饮食男女相似的地方都是三个女儿一台戏，也是全家星期天正式晚餐，只不过晚餐的灵魂是母亲，而且三代同堂，故事是从外孙的眼光叙述。美国黑人唱的是灵魂乐，美国黑人的饭自然也是soul food。黑奴时代，在地里干了一天活的黑人回家好好吃一顿，重储体力。他们边吃饭边讲故事，所以晚饭也是黑人文化传播站。星期天上教堂，之后全家人也要吃顿大餐。','There\'s Plenty For Everyone!',0,0,4.105363,6.6,19,114,'1997-09-26','en','/97t6YjxjTpwQ439MJcPiPDrMAg0.jpg',2.497391754439209,3,'2026-09-10',2,NULL,NULL),(29463,'破碎的节拍','Krush Groove','Russell Walker is a young, successful manager of rap performers, handling acts for the Krush Groove label, including Run-DMC and The Fat Boys. When Run-D.M.C. has a hit record and Russell needs more money to press more copies, he borrows it from a street hustler and soon regrets his decision.','It\'s chillin\'!',3000000,0,0.720091,7,11,97,'1985-10-25','en','/83jp1uZp9405rkHKzDuX8qnJbhw.jpg',2.3789781752689394,3,'2026-09-10',2,NULL,NULL),(29514,'魔鬼双瞳','Due occhi diabolici','影片分为两个故事，全部根据爱伦•坡的小说改编。杰西卡（Adrienne Barbeau 饰）的丈夫厄尼斯特（Bingo O\'Malley 饰）病入膏肓，精神病医生罗伯特（Ramy Zada 饰）与杰西卡有染。两人合伙撺掇厄尼斯特将数百万遗产留给妻子。这对男女最终如愿以偿，但愤怒的厄尼斯特再度复活，势要复仇……摄影师罗德（Harvey Keitel 饰）的女友安娜贝尔（Madeleine Potter 饰）带回一只流浪的黑猫。黑猫的叫声让本就烦躁不已的罗德难以忍受。他一气之下杀死黑猫，却不曾想从此走入黑暗恐怖的噩梦之中……','When I wake you... you\'ll be dead',9000000,0,8.218383,6,35,120,'1990-01-25','en','/zVWaQfaSZ7AWE0XqbMT57szVmXo.jpg',2.6291572626126927,3,'2026-09-10',2,NULL,NULL),(29595,'Wal-Mart: The High Cost of Low Price','Wal-Mart: The High Cost of Low Price','This documentary takes the viewer on a deeply personal journey into the everyday lives of families struggling to fight Goliath. From a family business owner in the Midwest to a preacher in California, from workers in Florida to a poet in Mexico, dozens of film crews on three continents bring the intensely personal stories of an assault on families and American values.',NULL,0,0,1.404175,6.9,24,98,'2005-11-04','en','/6PYx4HEbczd9QUCex5Wspkhjef5.jpg',2.5434943496200173,3,'2026-09-10',2,NULL,NULL),(29697,'像土豆一样的信仰','Faith Like Potatoes','影片讲述了苏格兰裔赞比亚人Angus Buchan到南非 KwaZulu Natal开始新生活的故事。依靠一片田地，他最终在当地站稳了脚跟。',NULL,0,0,0.147886,6,9,97,'2006-10-27','en','/rj80MS3Ixfw3cs7Kr6Lokbe5iSv.jpg',2.3337078875064843,3,'2026-09-10',2,NULL,NULL),(29715,'邓迪少校','Major Dundee','在内战的最后一个冬天，骑兵军官阿莫斯·邓迪（Amos Dundee）率领一支由陆军正规军、同盟囚犯和侦察兵组成的一支有争议的部队，远征墨西哥，摧毁一群袭击美国在德克萨斯州基地的阿帕奇人。',NULL,3800000,14873,3.490215,6.2,38,123,'1965-04-07','en','/afdhdupMyfn3tDoL3XosgQF82gX.jpg',2.6385869091083887,3,'2026-09-10',2,NULL,NULL),(29731,'然后爱情来临','And Then Came Love','单身妈妈',NULL,0,0,0.280829,5,1,90,'2007-01-01','en','/bGQWkjifQDEKJf6CBU2gxErRzDw.jpg',1.9844812586447633,3,'2026-09-10',2,NULL,NULL),(29912,'圣袍','The Robe','本片讲述的是一个监督将耶稣钉在十字架上的护民官，在惊恐之中了解了神的旨意，继而相信神，成为神的信徒，宁愿放弃自己的生命也不与罪恶妥协的故事。  罗马帝国时期，马赛勒护民官任职期间正面临基督耶稣被罗马当局指为妖言惑众，并被捕定罪，由马赛勒监督执行将耶稣钉于十字架上。老皇帝调马赛勒回罗马并指挥派他捉拿耶稣的门徒及烧毁圣袍，然而心存恐惧的马赛勒在追寻中遇见的耶稣门徒——彼得，从跛脚女子亦能将快乐传给人到遇见贫穷的小孩好不容易得到赏赐却毫不吝惜给比他需要的人。于是，他改变了，相信在一个爱的国度里才有生命，有盼望……此时老皇帝却已去世，卡里格拉登基，马赛勒在一次劫狱行动后被捕并被罗马帝国审判。他承认皇帝是帝贵的，但要他放弃心中的上帝，他愿意选择死亡……','The first motion picture in CinemaScope--the modern miracle you see without glasses!',4100000,36000000,4.028875,6.4,42,135,'1953-09-16','en','/qFYZNGzftIM8dqGMJBToGraAFJp.jpg',2.6644195083444426,3,'2026-09-10',2,NULL,NULL),(29917,'终极面试','Exam','《心战》奇才史釗活希素甸 首次执导一鸣惊人！\r 一家背景神秘的国际大企业招聘人材，8位晋身最后面试的精英，获安排在一间没有窗户的密闭房间进行终极比拼。房内有8张桌椅，桌上各有一份试卷及一支铅笔，面前是一度装上单向镜的墙壁，房间四处有闭路电视监控，唯一的房门由佩枪警卫把守。\r 应徵者须在限时80分鐘内回答一条问题，三个规则：1.不得与监考官或警卫交谈，2.不得离开面试房间，3.不得损毁答题试卷，违者立即出局。监考官讲解面试规则后，随即啟动倒数计时器，离开房间。8名求职者翻开试卷，发现竟是白纸一张！结束时间愈来愈近，要争取获聘，就要用尽一切方法……','How far would you go to win the ultimate job?',0,0,20.265518,6.6,523,101,'2009-06-19','en','/AlQDgjGu9fpEBS7bjRTgC5mYC0d.jpg',3.300845984366677,3,'2026-09-10',2,NULL,NULL),(29920,'不义之财','Snabba cash','讲述三个生活在斯德哥尔摩的边缘人物：一个从小就从智利移民到瑞典从事毒品买卖，在斯德哥尔摩市没有人比他更有人脉，另一个人则过着双重的生活，一边跟有钱有势的朋友交往一边贩卖毒品，还有一个是南斯拉夫帮派下的得力助手，主要是帮帮派老大收取俱乐部跟酒吧的保护费。当这些人从事毒品买卖或犯罪行为的过程中，因为钱太容易赚到，即使想过要回去那领着实在薪水平凡过活，可能社会无法接受他们，又或者那容易钱诱惑太大，结果往往总是又回到以前犯罪生活。',NULL,0,0,7.217328,6.5,63,124,'2010-01-15','sv','/qovBVud3Eydo8NFbO9KuoJFEgrR.jpg',2.7626094063785738,3,'2026-09-10',2,NULL,NULL),(29963,'明亮的星','Bright Star','1818年，伦敦：一段秘恋在23岁的英国诗人约翰·济慈与邻家女孩芬妮·布劳恩之间悄然萌发。芬妮是个直言不讳的时装爱好者。这对看似不般配的男女起初互不对眼——他觉得她是个时髦精，她对文学则整体无感。是济慈弟弟的病情将他们拉近。芬妮的帮助令济慈感动，他同意教她诗歌。待到芬妮警觉的母亲与济慈挚友布朗察觉两人情意时，这段关系已势不可挡。这对年轻恋人全然沉溺于彼此，被一股崭新的强烈情感席卷。“我感觉自己仿佛正在消融，”济慈在信中写道。他们共同乘着浪漫痴迷的浪潮，这份痴迷随着困境加剧而愈加深沉。唯有济慈的疾病，最终成为无法逾越的鸿沟。','First love burns brightest.',8500000,4440055,9.230073,6.8,107,119,'2009-11-05','en','/b74NTiOYxhXIMBZSIHh2KOXmE0o.jpg',2.897989443603612,3,'2026-09-10',2,NULL,NULL),(29996,'新所罗门王','Solomon and Sheba','所罗门王与雪芭女王之间的故事，是圣经电影经常拍摄的题材。大导演金．维多执导的这个版本只是中规中矩，因男主角泰隆．鲍华在演出中途去世，乃由尤．伯连纳取代重拍，细心的观众或许可以看到所罗门王在近景和远景之中会出现不同的体型。剧情描述以色列王子所罗门王与弟弟阿多奈贾正准备进攻埃及时，雪芭女王前来离间，一方面用美色勾引所罗门，另一方面让阿多奈贾意图谋夺大卫王病逝后遗下的皇位。两兄弟为此反目，上帝亦以神力毁坏所罗门的神庙来表示他的愤怒。','Only once in 3000 years...anything like...',5000000,12200000,0.835617,5.4,8,139,'1959-12-25','en','/sQPLRT014vOADFyvh54TpXFyBPZ.jpg',2.310489990130056,3,'2026-09-10',2,NULL,NULL),(30082,'蓝色的40道阴影','Forty Shades of Blue','本片围绕年迈的音乐制作人艾伦·詹姆斯（雷普·汤恩 Rip Torn饰）与小他三十岁的俄罗斯女郎劳拉（蒂娜·高逊Dina Korzun饰）展开，讲述他们之间一段阴郁而扭曲的虐心之恋。劳拉为了移民美国而嫁给比自己年长一倍的丈夫艾伦，他们相敬如宾，毫无感情可言。这使得劳拉变得越来越沉闷，甚至对生活失去了热情。直到艾伦关系疏远的儿子迈克尔·詹姆斯（达伦·布罗斯 Darren Burrows饰）的无意造访，突然让劳拉重新找回热恋的感觉。随着劳拉与迈克尔感情的日益升温，劳拉的负罪感越来越强。她觉得自己对不起艾伦，背叛了这个带给她全新生活的男人，而这样的生活她之前连想都不曾想过。面对如此扭曲而奇异的三角关系，劳拉到底该何去何从？',NULL,1500000,0,0.071377,6,2,108,'2005-12-07','en','/tWhkFzXkqS9afk2KKTTwd6IBmZ6.jpg',2.072413551848431,3,'2026-09-10',2,NULL,NULL),(30128,'I Hope They Serve Beer in Hell','I Hope They Serve Beer in Hell','Tucker decides to take an impromptu trip to celebrate his friend\'s bachelor party. He drags his friend into a lie with his fiancée, gets him into trouble and then abandons him in order to pursue a hilarious carnal interest. Tucker is disinvited to the wedding, and in order to get back in, Tucker has to find a way to balance his narcissism with the demands of friendship.',NULL,7000000,1429299,7.155519,5.7,20,106,'2009-09-25','en','/oBBood3JcOu0LQstdL9FeqCxMwa.jpg',2.507928859923124,3,'2026-09-10',2,NULL,NULL),(30139,'肥女孩','Phat Girlz','首先要声明一点，站在我们眼前的大块头肥妞贾兹敏·比特摩尔可没披挂什么橡胶皮囊，她是个货真价实的肥妹有情天，虽然她在人前一副“性感肥妞”代言人的派头，可心里压根就不相信是因为脂肪而美丽。',NULL,0,0,0.982624,3.7,10,99,'2006-01-01','en','/zzylksiJ8hmzvsHIDBTuqYZJYTe.jpg',2.346921601073253,3,'2026-09-10',2,NULL,NULL),(30141,'唱歌神探','The Singing Detective','一名侦探小说作家（Robert Downey Jr. 饰）躺在医院病榻上构思新作情节：一名愤世嫉俗的私家侦探一到夜晚摇身一变成为乐团主唱歌手，故事主人翁被卷入1950年代洛杉矶一宗妓女凶杀案……随着病情加剧，他渐渐无法分辨故事与现实，精神状态陷入疯狂边缘……','When it comes to murder, seduction and betrayal he wrote the book. Now he\'s living it!',0,0,6.335881,5.9,41,109,'2003-10-24','en','/uLR8cJOiWRg92AMMNR18wBat9sQ.jpg',2.656480710313844,3,'2026-09-10',2,NULL,NULL),(30246,'民间商标','Civil Brand','怀特黑德惩教所（Whitehead Correction al）是一所以非裔美国人为主的女性监狱，囚犯们被迫在类似奴隶的条件下在“营利监狱”项目中工作，试图接管该监狱。',NULL,0,0,0.665512,5.3,4,95,'2003-08-29','en','/nPjGdwuJ3aejtawx94rd2iwFfTI.jpg',2.183456186446252,3,'2026-09-10',2,NULL,NULL),(30309,'Real Women Have Curves','Real Women Have Curves','There\'s more to Ana Garcia than meets the eye. Should she leave home, go to college and experience life? Or stay home, get married, and keep working in her sister’s struggling garment factory? It may seem like an east decision, but for 18 year-old Ana, every choice she makes this summer will change her life. At home, she is bound to a mother who wants her to become someone she\'s not. But at school, she\'s encouraged by a teacher who sees her potential and adored by a boyfriend who loves her for who she is. Right now, Ana may be making clothes for less shapely women. But she\'s about to discover that real women take chances, have flaws, embrace life, and above all, have curves!',NULL,0,0,1.026243,5.8,19,86,'2002-01-01','en','/ziemD3ATULYKt399FkO1ZhAwrOH.jpg',2.4842575357493972,3,'2026-09-10',2,NULL,NULL),(30315,'蜘蛛王国','Kingdom of the Spiders','Investigating the mysterious deaths of a number of farm animals, vet Rack Hansen discovers that his town lies in the path of hoards of migrating tarantulas. Before he can take action, the streets are overrun by killer spiders, trapping a small group of towns folk in a remote hotel.','A Living, Crawling, Hell on Earth!',500000,17000000,2.537032,5.7,30,97,'1977-08-24','en','/7NMnHnb721MwczHJ486Ltfo68F4.jpg',2.5803620535711915,3,'2026-09-10',2,NULL,NULL),(30379,'神魔交战','Megiddo: The Omega Code 2','影片描述一权谋政治家聚世界军事力量对抗圣经记载世界末日的来临。六岁男孩史东·亚历山大（迈克·约克饰）痛失因难产死亡的养母，他憎恨他刚出生的弟弟大卫（迈克·宾汉饰），恶魔因而挑选他成为这一世传播反基督思想代言人。在企图活活烧死弟弟之后，史东的父亲丹尼尔·亚历山大将史东送往欧洲军事学校，在那里他在邪恶使者羽翼之下成长。多年后，史东与大卫再度相见之时，他们爱上同一女子嘉碧烈叶（戴安·凡诺拉饰）。而当大卫在美国政坛崭露头角时史东也在欧洲展开政治生涯。三十年后，两兄弟再聚首之际，大卫与史东分别代表世界两大政治势力，美国与欧洲。史东进行着一连串邪恶计划，史东与他的新世界帝国已威胁到美国人民自由与前途。借由超自然黑暗力量帮肋，大卫如史东计划中成为美国总统，并驱使美国人民运用公众力量加入史东的新世界帝国，全球落入史东掌控，大卫深知史东诡计顽强抵抗，却遭到属下反叛，此时，大卫感知到上帝的召唤与处于水深火热中人民请求，与意大利、中国组成联军，合力对抗史东的邪恶军队。正当史东沉醉于摧毁世界的快感之时，大卫的联合军队已渐渐逼退邪恶军团，史东恼羞成怒之际深藏已久的真面目就要显现吗？正邪交锋究竟谁是最后赢家？','In The Beginning, The End Had A Name.',0,0,0.809588,3.6,8,104,'2001-09-07','en','/gBFh6xxEManI9YJ5acKBfhqT9Nu.jpg',2.3045643997863317,3,'2026-09-10',2,NULL,NULL),(30497,'德州电锯杀人狂','The Texas Chain Saw Massacre','故事始于五个天真的年轻人，他们正要去核实有关盗墓的传闻。当莎莉、她残疾的弟弟富兰克林以及三位朋友动身前往查看其家族墓地时，很快便偏离原路，踏上了一段终极恐怖之旅。他们一个接一个地落入“人皮脸”及其手中那柄可靠电锯的杀人魔掌。','Who will survive and what will be left of them?',85000,30859000,29.262427,7.2,590,83,'1974-10-01','en','/5oAkINbeNtj2XWp0I2rXSL6rUMj.jpg',3.4324002453097755,3,'2026-09-10',2,NULL,NULL),(30596,'十月围城','十月圍城','1906年。清末。正是清廷疯狂暗杀“革命党”的黑暗年代。10月15日。革命领袖孙中山决定冒险赴港，名为探望母亲，实则与十三省革命代表见面会谈。这是清廷“刺杀孙贼”的大好时机，将军白孝国(胡军饰)买通香港警察，在全港织起了一张“刺孙”的天罗地网。而“中国日报”社长陈少白(梁家辉饰)作为革命党人，必须在24小时内完成保卫孙中山的任务。大商人李玉堂(王学圻饰)是陈少白老友，多年来一直在暗中出资支持陈的革命工作。10月15日前夕，李玉堂正在为17岁的独子李重光(王柏杰饰)考上大学大宴宾客，陈少白寻上门来，希望其能出资支援——当李玉堂随后发现儿子重光竟然也受革命思想影响时，不仅不愿再度投资，更欲与陈决裂。然而，就在此时，陈少白的突然被捕失踪，以及香港各革命据点的连续遭袭，令李玉堂无法袖手旁观，他被迫担负起“保孙”的指挥工作，并花钱找寻民间力量，来替补遭到毁坏的保镖队伍。香港。卧虎藏龙之地。曾是贵公子，如今沦为“乞丐”的刘郁白(黎明 饰)；对李家父子忠心耿耿的“车夫”阿四(谢霆锋饰)；因父亲被杀而欲替父报仇的戏班“打女”方红(李宇春 饰)；被南少林逐出山门，如今靠卖炸臭豆腐为生的“小贩”王复明(巴特尔饰)；他们身怀绝技，虽然并不明白“革命”真正的意义和惨烈，却因自身的各种原因，最先加入到保镖的队伍中。而原本一事无成的“赌徒”沈重阳(甄子丹饰)因为与李玉堂“妾侍”月茹(范冰冰饰)的复杂恩怨，最终担负起了重要的护卫工作。甚至是老奸巨猾的华人警察司长史密夫(曾志伟饰)都因深受感染而对保卫工作暗施援手。15日前夜，陈少白冒险逃狱成功，回归保卫革命的队伍中。李玉堂不知，他最心爱的儿子李重光已成为这次反刺杀行动中，最重要最特别的一员。15日。孙中山抵港。阎孝国组织的杀手队伍一拨又一拨地逼近了保镖队伍。双方展开了一场又一场惊心动魄的“全城追杀”……最终，孙中山安全离境，身后的香港已染满保镖和杀手们的鲜血。一年内，全国革命相继爆发。1911年，辛亥革命爆发。','To save a nations future, they must protect one man from its past.',23000000,5837674,7.876883,6.5,57,139,'2009-12-18','cn','/w8Z6tsP0E4YzdmeEQVALSKvwOVE.jpg',2.7419228401578115,3,'2026-09-10',2,NULL,NULL),(30867,'斯科特·沃克传','Scott Walker: 30 Century Man','A documentary on the influential musician Scott Walker.',NULL,0,0,0.607782,7,8,95,'2006-10-31','en','/foDbZTQKsbJmdOuu2QfIJ8dbaen.jpg',2.315183912365516,3,'2026-09-10',2,NULL,NULL),(30890,'无线电时代','Radio Days','画外音中，一个中年男子带领观众回到他童年时生活的洛格威小镇，那里有太多围绕着收音机广播的有趣故事……两名小偷潜入一户人家作案，恰巧广播中的电话竞答节目选中了这里，小偷答中了所有问题，第二天男主人返家，发现钱物丢失但竞答节目的奖品却堆满了门口。碧姨妈与别人相亲时广播中传来火星人进攻地球的消息，对方抛下姨妈落荒而逃。广播明星罗杰与一名夜总会女郎莎莉（Mia Farrow 饰）纠缠不清，莎莉没有如愿得到广播的工作机会却在战时节目中大展拳脚。蒙面游侠的连续广播吸引了无数少年，但主人公始终无法得到一枚游侠戒指……1944年的新年广播中，所有这些经典时代的记忆落下了帷幕。',NULL,16000000,0,7.612849,7,127,90,'1987-01-30','en','/ljZ3yyYznAiq1vF6nHITdJn6qXB.jpg',2.9443001557308253,3,'2026-09-10',2,NULL,NULL),(30943,'海洋深处','The Deep End of the Ocean','贝斯（米歇尔·菲佛 Michelle Pfeiffer 饰）是一名非常成功的摄影师，和丈夫派特（特里特·威廉斯 Treat Williams 饰）一起抚养着三个可爱的孩子文森特（乔纳森·杰克逊 Jonathan Jackson 饰）、本（瑞恩·莫里曼 Ryan Merriman 饰）以及凯丽（阿丽夏·潘娜维加 Alexa PenaVega 饰）。一天，在一场排队中，最小的本走丢失踪了，尽管贝斯和派特找来了全城最精明强干的警探，都未能觅得本的下落。这巨大的打击让贝斯的家庭濒临了崩溃的边缘。  一晃眼九年过去了，贝斯和派特渐渐走出了过去的阴影，全家人在芝加哥开了一家餐馆。一天，一个名为山姆的男孩敲响了贝斯家的们，请求为他们修剪后院草坪。让贝斯没有想到的是，这个山姆，竟然就是从前失踪的本。','The search for her son was over. The search for her family was just beginning.',38000000,28121100,4.746085,5.9,54,106,'1999-03-12','en','/4Q8g9CfW7EiwxRCpLSDpOmcaEZb.jpg',2.710402734570146,3,'2026-09-10',2,NULL,NULL),(30973,'约翰福音','The Gospel of John','逐字逐句地描绘了约翰福音中记录的好消息翻译圣经中耶稣基督的生平。','For God loved the world So much...',10000000,4069090,3.208172,8.2,12,125,'2003-09-11','en','/rKbmbnYfFhgTjGoDU9F4pIhVvKh.jpg',2.4082311353220707,3,'2026-09-10',2,NULL,NULL),(30979,'远山远处','The Horse Boy','Filmmaker Michel Orion Scott captures a magical journey into a little-known world, in a documentary which chronicles Rupert Isaacson and Kristin Neff\'s personal odyssey to make sense of their child\'s autism, and find healing for him and themselves in the unlikeliest of places.',NULL,0,0,0.465404,5.5,2,93,'2009-11-25','en','/qdwiIajiJUNd5578l0cqe7PCYrA.jpg',2.072902870291331,3,'2026-09-10',2,NULL,NULL),(31005,'月光旅程','Moonlight Mile','故事发生在1973年的马萨诸塞州，乔（杰克•吉伦哈尔 Jake Gyllenhaal 饰）是一个生活在那里的心碎的男人。曾经，他也有过堪称完美的生活，和未婚妻戴安娜（Careena Melia 饰）即将携手步入婚礼的殿堂，可是，在一间咖啡馆中，戴安娜成为了一场枪击事件里的无故牺牲者，戴安娜的死将乔瞬间抛入了绝望之中。\r 虽然戴安娜死了，但乔还是和戴安娜的父母本（达斯汀•霍夫曼 Dustin Hoffman 饰）以及周周（苏珊•萨兰登 Susan Sarandon 饰）生活在一起。本和周周早已经将乔当成是自己的家人了。他们邀请乔一同参与当地的房地产建设经营工作，为了摆脱精神的痛苦，乔将所有的精力都投入了工作之中。',NULL,21000000,10011050,8.982335,6.5,52,117,'2002-09-09','en','/jKDnCPUkL4QsgeqKCtyNMPL2XUU.jpg',2.724181309174907,3,'2026-09-10',2,NULL,NULL),(31007,'Welcome to the Rileys','Welcome to the Rileys','Years after their teenage daughter’s death, Lois and Doug Riley, an upstanding Indiana couple, are frozen by estranging grief. Doug escapes to New Orleans on a business trip. Compelled by urgencies he doesn’t understand, he insinuates himself into the life of an underage hooker, becoming her platonic guardian.',NULL,0,42145,6.085879,6.4,139,110,'2010-10-29','en','/py3Ey2iEjJ3s9G8W7IEHpDF1wRE.jpg',2.9345635528144993,3,'2026-09-10',2,NULL,NULL),(31064,'The Business of Strangers','The Business of Strangers','Julie Styron thinks she is going to be fired, but instead discovers that she is being promoted. Trapped in an airport hotel, she wants to celebrate but finds only the company of her young assistant, Paula Murphy. As the night progresses, the two women get to know each other. They flirt, they drink, they lie; personal flaws are revealed and exposed. But at the end of the night their relationship turns and becomes a complex battle of power, authority, and wit.',NULL,0,0,1.369649,5.7,19,84,'2001-01-19','en','/5iVwXnV2fraxy6NYzxZ07jMWW0u.jpg',2.4842793297933294,3,'2026-09-10',2,NULL,NULL),(31117,'Superbabies: Baby Geniuses 2','Superbabies: Baby Geniuses 2','Following on from the plot of the last movie, babies can communicate with each other using \'baby talk\', and have an innate knowledge of the secrets of the universe. The baby geniuses become involved in a scheme by media mogul Bill Biscane (Jon Voight). Helping the geniuses is a legendary superbaby named Kahuna. He joins up with several other babies in an attempt to stop Biscane, who intends to use a state-of-the-art satellite system to control the world\'s population.','Meet the new generation of superheroes.',0,9109322,5.886228,1.9,35,88,'2004-08-27','en','/7viULokoVzqrgVj0EljfXDzEKMk.jpg',2.5674399507329855,3,'2026-09-10',2,NULL,NULL),(31163,'Chicken Tikka Masala','Chicken Tikka Masala','Jimi (Chris Bisson), the Chopra family\'s only son, gets caught off guard when his high-handed parents (Saeed Jaffrey and Jamila Massey) announce an arranged marriage to Simran (Jinder Mahal), a lovely girl from a respectable family. Problem is, Jimi\'s gay, so to hide his homosexuality, he spins an ever-more elaborate web of deceit -- but how long can he conceal the truth?',NULL,0,0,0.258413,3.5,5,90,'2005-04-22','en','/sz7TBagHKYx6NI1XmRWIwoDDLri.jpg',2.218105012934603,3,'2026-09-10',2,NULL,NULL),(31166,'伴雨行','I Come with the Rain','故事讲述饰演警员的乔什·哈奈特在枪杀连环杀手后情绪大受打击，转做私家侦探，受富豪委托寻找失踪儿子Shitao（木村拓哉饰），当他到菲律宾时，被告知Shitao已被3名男子枪杀，但又有人说Shitao其实人在香港，于是他来港找警察朋友余文乐帮忙，其间与黑帮大佬Su Dongpo（李秉宪饰）扯上关系，黑帮大佬Su Dongpo迷恋一个女人，并用毒品控制她，老大有个手下，也喜欢此女，而且他了解到有个人可以转移别人的伤痛，此人正是富豪失踪的儿子Shitao（木村拓哉），于是拼死把深染毒品的女人送到木村拓哉处，自己却死了，木村拓哉治好了这个女人，而女人也爱上了他。原来木村拓哉在被三人枪杀后，不但没有死，反倒有了承受别人伤痛的能力，成了不死之身，而他自己也看透世事，放弃自我，不断的拯救他人。后来李秉宪找到他，把他钉在十字架上，最后被乔什·哈奈特拯救了。',NULL,18000000,0,8.266124,5.6,20,114,'2009-05-14','en','/wOJZ3XvHjcGfLBh0GLJU3HhsJKE.jpg',2.509664022515479,3,'2026-09-10',2,NULL,NULL),(31174,'理查三世','Richard III','在1930年代，当时世界被战争而分裂，人类处在激情与痛苦当中。导演理查德·隆克瑞恩巧妙地将故事中的狡诈、阴谋、残暴，与当代法西斯象征主义结合在一起。伊安·麦克莱恩演出理查三世，他欲夺取兄长的王位，谋杀、骗婚、歼灭亲族无所不用其极，这样强烈的欲望，驱使他永无止尽的毁掉周遭的人。\r 　　影片是根据莎士比亚的名剧《理查三世》改编而成的，但是影片将故事发生的时间背景由原著中1483-1485年转换到1930年。将莎士比亚的剧作移植到其它年代，是电影人常常做的事，但是却不一定每次都做的好。难能可贵的是，这版《理查三世》不但以睿哲的智能改编了这部剧作，并且在不破坏莎翁美丽的词句下，为此剧注入现代的活力。','I can smile, and murder while I smile',0,0,5.107235,6.9,49,104,'1995-12-29','en','/cBg1AMH1ucPsDlNMfcHlrreQXQX.jpg',2.7098216769740393,3,'2026-09-10',2,NULL,NULL),(31175,'心灵厨房','Soul Kitchen','一个希腊后裔的德国人Zinos（亚当·布斯多柯斯 Adam Bousdoukos 饰）在汉堡开了间餐厅，名字叫“Soul Kitchen”，最近遭遇了严重的财政危机，入不敷出，难以为继。祸不单行，Zinos还因为一次意外而腰椎间盘突出。而他的情感生活也有麻烦，他的女友Nadine（菲琳·罗根 Pheline Roggan 饰）是一名记者，决定到上海工作。他的弟弟Illias（莫里兹·布雷多 Moritz Bleibtreu 饰）刚从监狱里假释出来，来到Zino的餐厅打工。因为身体问题，Zino只能雇了另外一个厨师Shayn（波热尔·尤内尔 Birol Ünel 饰），但是Shayn做出的新菜，却没有受到老顾客们的欢迎，餐厅的收入每况愈下。而Zinos的女友也决定抛弃他，和一个在上海萍水相逢的人在一起。问题多多的Zinos该如何咸鱼翻生？Soul Kitchen能否继续营业？',NULL,5000000,17872796,5.461487,7.1,116,99,'2009-09-09','de','/qu49WgLAsAiBvw4uPKCvygWnHcg.jpg',2.921042051111807,3,'2026-09-10',2,NULL,NULL),(31203,'巴黎淘气帮','Le Petit Nicolas','小尼古拉（马克西姆·戈达尔 Maxime Godart 饰）深受父母宠爱，在学校也与一帮朋友玩得开心，这其中包括：想当大官的亚斯特Alceste（Vincent Claude 饰）、以后会继承父业的杰夫Geoffroy（Charles Vaillant 饰）、梦想成为自行车冠军在班上却总是被罚站的克劳岱Clotaire（Victor Carles 饰）、长大要当黑道的奥德Eudes（Benjamin Averty 饰）、希望跟老爸一样成为警察的鲁夫Rufus（Germain Petit Damico 饰）以及全班第一名永远不会被罚站也是老师（Sandrine Kiberlain 饰）的最爱学生同时是其他同学眼中讨厌的大蟑螂的阿南Agnan（Damien Ferdel 饰）。  有一天，尼古拉的妈妈（瓦莱丽·勒梅西埃 Valérie Lemercier 饰）建议爸爸（凯德·麦拉德 Kad Merad 饰）请老板及夫人来家里吃饭，以便获得老板青睐涨工资；但小尼古拉听到和观察到的结果却让他以为父母要生个小弟弟，不要他了。沮丧的小尼古拉请求朋友们的帮助，大家七嘴八舌给他出了一堆建议，包括送花、大扫除，甚至找罪犯领养弟弟等荒谬办法。与此同时，教育部长也要来学校参观，班级又换了严厉的代课老师……  本片根据由法国作家勒内·戈西尼（René Goscinny）创作，漫画家让-雅克·桑贝（Jean-Jacques Sempé）配画的系列同名漫画故事改编。影片在法国本土上映后一举拿下全法双周票房冠军，并获2010年凯撒奖最佳改编剧本提名。',NULL,0,0,20.362025,5.9,306,91,'2009-09-30','fr','/ad60SNMHyU0Wgi0vpXyI9joor8I.jpg',3.104994660100964,3,'2026-09-10',2,NULL,NULL),(31246,'From Justin to Kelly','From Justin to Kelly','A lonely, sexually repressed man. A depressed woman. A summer camp. On this fateful night, they will meet... and their hearts will become one.','The tale of two American Idols.',12000000,4922166,1.623338,3,23,90,'2003-06-20','en','/bLLlgQ6nZPGxvAjp0qjTX1wD2hl.jpg',2.4990145461991284,3,'2026-09-10',2,NULL,NULL),(31306,'疯狂阿拉巴马','Crazy in Alabama','疯狂辣妈闯影坛、用尽手段圆美梦！有时候你必须失去理智才能换取自由！1965年炙热的阿拉巴马州，男孩皮裘迷人的阿姨露西儿，用非常的手段离开了丈夫并且留下了一团谜，奔向好莱坞寻求她的明星梦，到底露西儿阿姨作出什么骇人的事？',NULL,0,0,5.770246,6.5,12,111,'1999-10-22','en','/bAlevqRg9KG9y725tt4YkNajLrk.jpg',2.4058179533570496,3,'2026-09-10',2,NULL,NULL),(31535,'Chairman of the Board','Chairman of the Board','A surfer becomes the head of a major company.','Work sucks!',0,0,0.587276,2.7,13,95,'1998-03-13','en','/1eGB1EjaUjGbiuPBAqndlO3khyn.jpg',2.3902371884848517,3,'2026-09-10',2,NULL,NULL),(31582,'完美无瑕','Flawless','一位个性保守又传统的警官，因为中枪变成半身不遂的靠轮椅生活，让他身心都受到煎熬。而他的医生要求他学习唱歌来进行声音复建，他因为没钱又求救无门的情况下，只找上他隔壁邻居来当他的歌唱老师，偏偏他的芳邻却是个有变装癖的同性恋…\r 　　一名极端保守的警察患上了使人衰弱的中风，被分配到一个包括唱歌课程在内的康复项目中，而变装皇后就在隔壁。',NULL,0,4488529,5.271559,5.9,56,112,'1999-11-26','en','/17Q9FDlkPOhmHJx1kas5Jp9azmk.jpg',2.7192077061827984,3,'2026-09-10',2,NULL,NULL),(31640,'血与酒','Blood and Wine','一名看似风光但早已面濒临产边缘的酒商，「婚内出轨」了富有客户家的褓姆，酒商利用褓姆对豪宅的熟悉，潜入客户家偷走一条钻石项链后，计划竟开始分崩离析，原来褓姆为了远在古巴的家人，宁作小三也要留在梦想之地美国，周旋在酒商和他的继子之间，复杂的感情关系剪不断理还乱。','There is no honour amongst thieves.',26000000,0,1.492056,5.5,34,101,'1996-10-03','en','/diFSUAvHZE6rkKqfP3J3qf19Z2X.jpg',2.601028921989292,3,'2026-09-10',2,NULL,NULL),(31668,'女王密使','All the Queen\'s Men','以二战为背景的喜剧，一伙英国特工奉命潜入德国工厂窃取密码机，不料情报有误，该工厂只招收女工，特工们只好男扮女装……',NULL,15000000,23000,1.833058,6.1,7,99,'2001-10-14','en','/oU5qvvUCj1DTCk2kKKTPQDIx7nd.jpg',2.289478442366753,3,'2026-09-10',2,NULL,NULL),(31867,'重生男人','Repo Men','本片根据埃里克·加西亚小说《重生曼波》（The Repossession Mambo）改编，故事设定在未来，人类已经开始广泛使用昂贵的机器器官来延长生命，这些机器器官全部由一家名为“The Union”的公司垄断制造，他们雇了一群追讨人，专门负责收回付不起钱的顾客的机器器官，哪怕那些人的机器器官被粗暴的取出后生命会陷入垂危。 雷米（裘德·洛）就是工作最出色的一名追讨人，然而在一天执行任务的时候，他因突发的心脏衰竭而奄奄一息，等他醒来后“The Union”公司已经为他换上了最好的机器心脏，而他自己的心脏已经失去功效了。可惜，这个机器心脏不是免费的，雷米必须为其支付一大笔钱，付不起钱的雷米成为了追讨人新的猎物，而负责追讨回他的心脏的正是当初他的搭档杰克（福里斯特·惠特克）。','For a price, any organ in your body can be replaced. But it can also be repossessed.',32000000,18409891,25.799697,6.2,620,111,'2010-03-18','en','/mg94BKSicLO6ENWW6Qh11ymutSi.jpg',3.301314468391682,3,'2026-09-10',2,NULL,NULL),(31908,'等待黑色黎明','Ghosts of Mississippi','故事发生在1963年的密西西比，麦格（小詹姆斯·皮肯斯 James Pickens Jr. 饰）是当地有名的民权运动领袖，一天，他被发现遭到了谋杀，死在了自家的车道上。嫌疑人是一个名叫布莱恩（詹姆斯·伍兹 James Woods 饰）的男人，他是一名白人种族主义者，虽然证据确凿，但布莱恩最终还是获得了无罪判决，逍遥法外，只因为当时庭审中，陪审团均为白人。\r 一晃眼30年过去，当所有人都逐渐淡忘了这个耸人听闻的案件之时，一位年轻的地方检察官巴比（亚历克·鲍德温 Alec Baldwin 饰）重新拾起了布满灰尘的档案，在麦格的遗孀玛丽（乌比·戈德堡 Whoopi Goldberg 饰）的帮助下，巴比决定对布莱恩提起第三次诉讼。','From the director of A FEW GOOD MEN comes a compelling TRUE STORY.',0,0,8.102925,6.2,40,130,'1996-12-20','en','/gu81MbuLTPbw95xWuDuM7ddcCir.jpg',2.6600477248819114,3,'2026-09-10',2,NULL,NULL),(31909,'火星大接触','Invaders from Mars','1953年同名电影的重拍版。\r 　　小男孩David在暴风雨夜看到一架不明飞行物降落在他家附近的沙丘，隔天他的父亲爬上去探视，回来之后整个人就变得冷漠且充满敌意，接下来他的母亲也是如此。后来，他发现外星人绑架镇民并在颈椎植入控制头脑的东西，可是没人相信他的话。再后来，David发现父母开始吃生肉，学校的老师开始活吞青蛙……（豆瓣电影）','Their conquest has already begun... He know they\'re here.',12000000,4884663,4.234269,5.5,57,100,'1986-01-01','en','/rs3cOVZtrXD27XQQdut1FWFYrUG.jpg',2.7118308897394794,3,'2026-09-10',2,NULL,NULL),(31915,'预言','Prophecy','缅因州某山区的一个造纸公司,因将有毒废物排泄至附近水域,造成当地的印地安居民中毒,病魔缠身,胎儿畸形.更糟的是,污染让一个生物长成为一个凶残可怕的巨兽,出没于山区,残杀居民,整个山林因此笼罩在恐怖的气氛之中........',NULL,12000000,54000000,8.61659,5.4,25,102,'1979-01-01','en','/8jCyz5IRWmu8R5FhRO2BqtQXnCj.jpg',2.5538574120748088,3,'2026-09-10',2,NULL,NULL),(31932,'魅影危程','City of Ghosts','美国部分州遭受飓风灾害，很多人流离失所。保险公司职员杰米还没从突如其来的灾难中回过神来，就被联邦调查局的人员找上了家门。原来，经过调查，他所在的保险公司根本就是个空壳，并且涉嫌诈骗。很多受灾的居民投了该公司的保险，可现在却面临着一无所有的局面。作为该保险公司唯一的职员杰米既困惑又气愤，决定躲过美国联邦调查局，只身前往柬埔寨向同僚索取保险诈骗金额股份。 可到了柬埔寨，杰米发现事情并没有想象中的那样简单。同样想追回保险金的同事卡斯帕言辞行为十分怪异，而大老板马文则远在泰国曼谷，不日将返回。杰米本想再度赶去曼谷，却不想到柬埔寨的第一天，护照就不翼而飞。杰米又气又恼，身边的人看起了一个个都心怀不轨，只有朴实的三轮车夫阿索才是他真正可靠的朋友。在这个古旧的国度里，杰米陷入谜样的境况，有人被杀，有人失踪。 而他自己也被所谓马文留下的字条引去笑脸街，被一群高棉人打到半死，还好阿索舍命相救，才幸免于难。而他与马文的关系亦变得扑朔迷离，找不到护照的杰米，已走上了一条不归之路。危难之时，杰米认识了来柬埔寨工作的美国女孩索菲，并对她产生好感。虽然心有不甘，但杰米知道此时的爱来得太不是时候。在这个异国他乡，他对索菲的关爱会让她陷入危险之中。 几经周折，杰米终于见到了马文，马文意图将保险公司诈骗来的全部钱财全部用于兴建赌场上，而与他一起合作的西尼看起来更是虎视眈眈。马文的这种做法引起了卡斯帕的强烈不满，他几次陷害杰米都没有得逞。事情变得越来越复杂，就在拿到巨额现金的杰米即将重返美国之际，传来马文被绑架的消息。而杰米只能在所不辞，却没想到期间险象环生，而这一切不过是马文设下的圈套而已。',NULL,0,0,2.64486,5.4,18,116,'2002-01-01','en','/1nZbFdgEjJELfbZeXWLjXx5evHa.jpg',2.47404525255103,3,'2026-09-10',2,NULL,NULL),(32222,'American Desi','American Desi','This is a fun-loving romantic comedy reminiscent of the great teen films of the 80\'s.From Kris, an All-American boy from India, to Ajay, an Afro-Centric Hindu homeboy, to Farah, a devoutly religious but modern Muslim girl, \'American Desi\' tells the story of a unique set of characters and their culture from a decidedly hip and youthful point of view.',NULL,250000,0,0.126304,5,4,100,'2001-01-01','en','/hklG9Ehe1Rt2dlgBplTIyov62qi.jpg',2.181733014973008,3,'2026-09-10',2,NULL,NULL),(32235,'诺斯福克','Northfork','1955年，一场大洪水即将来袭蒙大拿州的诺思福克。一座新的水力发电坝即将安装在山上，为了进步的名义，将淹没这个山谷。一个由六人组成的疏散委员会负责将居民迁移到较高的地方。大多数人已经离开了，但还有一些顽固的人留了下来，其中包括一个照顾一个病弱孤儿的牧师，一个男孩，他发热时的幻觉让他相信自己是一群流浪的失落天使中的一员，他们正在绝望地寻找回家的路。',NULL,0,0,1.980265,6.7,24,103,'2003-01-01','en','/jb3qheP75UgVibpnfubotrBDY5v.jpg',2.5428964542136656,3,'2026-09-10',2,NULL,NULL),(32274,'大厦将倾','Cradle Will Rock','本片讲述的是在本世纪30年代纽约艺术和戏剧界发生的故事。当时，美国各地都在爆发罢工，文化革新思想的萌芽充满个整个纽约城。本片由多个故事互相编织在一起：纳尔逊.洛克菲勒(Nelson Rockefeller)授权墨西哥艺术家迪戈.李维拉(Diego Rivera)将达芬奇的名作出卖给百万富翁，以便为墨索里尼的战争筹备基金；一个偏执的口技艺术家试图解散他的轻歌舞剧团，因为他发现剧团的成员们竟然都是共产主义者；22岁的青年导演奥森.威勒斯(Orson Welles)导演了一出名为“大厦将倾”(The Cradle Will Rock)的戏剧，在公演当日晚即遭美国士兵强行禁演。',NULL,0,0,4.901553,7.2,18,132,'1999-12-10','en','/d8LJWY8kaAIlfMiQLOGglL8VqVT.jpg',2.4922219615084984,3,'2026-09-10',2,NULL,NULL),(32275,'阳光下的决斗','Duel in the Sun','美丽的混血儿珀尔·查韦斯成为她已故父亲初恋的监护人，发现自己在两个儿子之间左右为难，一个是好的，另一个是坏的。','Emotions . . . As Violent As The Wind-Swept Prairie !',6000000,20400000,7.60445,6.2,37,144,'1946-12-31','en','/dW479xuDWrcuFuxr7yfoReztlzF.jpg',2.642311572369665,3,'2026-09-10',2,NULL,NULL),(32316,'Marci X','Marci X','A Jewish-American Princess is forced to take control of a hard-core hip-hop record label and tries to rein the one of the label\'s most controversial rappers.','Uptown Gets Down.',20000000,1675706,5.65327,3.3,12,84,'2003-08-22','en','/8gDhnXFVARqa5F2sCZdelDhiVjc.jpg',2.3899922382775087,3,'2026-09-10',2,NULL,NULL),(32395,'最伟大的','The Greatest','爱子班尼特（亚伦·泰勒-约翰逊 Aaron Taylor-Johnson 饰）的意外身亡让身为父母的艾伦（皮尔斯·布鲁斯南 Pierce Brosnan 饰）和格蕾丝（苏珊·萨兰登 Susan Sarandon 饰）痛不欲生，两人之间的关系也降到了冰点。在绝望的情绪弥漫了数月之久后，一个名叫罗斯（凯瑞·穆丽根 Carey Mulligan 饰）的女孩的出现打破了压抑的平静。\r 罗斯自称班尼特的女友，腹中怀了他的孩子。在半信半疑之间，艾伦和格蕾丝接纳了这样一个几乎是凭空出现的女孩。刚开始，误会和争吵在所难免，关于罗斯真实身份的猜疑也从未停止，但随着罗斯的肚子渐渐变大，一种久违的亲情和温情重新出现在了这个四分五裂的家庭之中。',NULL,6000000,0,6.903186,6.2,34,99,'2009-01-17','en','/7dNynUNdYSxeOpuJJNv3Fyk54NA.jpg',2.6227537972392194,3,'2026-09-10',2,NULL,NULL),(32456,'两女一男','Two Girls and a Guy','两个女人面对她们的男朋友，一个两面派的演员，他向每个人承诺了永恒的爱。','Thanks to his two girlfriends Blake is about to learn a new sexual position. Honesty',1000000,2057193,4.86805,5.4,24,84,'1997-09-07','en','/9Hj90OgXLBReJCAGqOOzzxjZfCh.jpg',2.5370530342688364,3,'2026-09-10',2,NULL,NULL),(32579,'一样的月光','La misma luna','迫于生计，罗莎里奥（凯特·德尔·卡斯蒂洛 Kate del Castillo 饰）不得不离开了自己挚爱的儿子卡利托斯（阿德里安·阿龙索 Adrian Alonso 饰），只身前往洛杉矶赚钱养家。临行前，她将卡利托斯托付给了母亲班尼塔（Angelina Peláez 饰），并允诺一定会回来接他。可几年过去，罗莎里奥似乎里当初的承诺越来越远。\r 班尼塔的去世让九岁的卡利托斯成为了无依无靠的孤儿，然而，和当地诸多相同情况的孩子们不同，他并没有向艰苦的生活屈服，也没有放纵生活一味堕落，一个坚定的信念支撑着他，他决定要远赴洛杉矶寻找母亲。这漫长的旅途充满了艰险，好在有善良的人们出手相助，这段亲情维系的旅程得以画上了完满的句号。','The love between a mother and a son knows no Boundraries.',0,23311391,2.756435,7,28,106,'2008-03-20','es','/mxH1BES4YFFcfcVeL68Q8NdptER.jpg',2.5811319260081853,3,'2026-09-10',2,NULL,NULL),(32657,'波西·杰克逊与神火之盗','Percy Jackson & the Olympians: The Lightning Thief','黑夜，天神宙斯召见海神波塞冬，称其子偷了闪电火，要挟他若不尽快找回，必将开战。现实中，波塞冬与人妻萨利之子波西杰克逊是个大学生，17岁的他可以在水下呆7分钟，但对老师关于莎翁的提问不感兴趣。参观博物馆时，他遇到了摇着轮椅的人马老师。而文学老师却变身成了复仇女神，向他逼问闪电火的下落。幸好人马教授和羊男朋友及时赶到，化险为夷。他们带波西来到营地，训练波西，他们找来了一个女战士安娜贝斯与之比武。落败后，触水的波西被激活了潜能，成为奋勇无敌的战士，并开始踏上了追寻闪电火的英雄之旅。面对蛇女美杜莎等神怪的攻击，冥王冥后珀尔赛弗涅的刁难，他的自我救赎只剩下10天。','Worlds Collide',95000000,226497209,61.121717,6,2010,118,'2010-02-01','en','/9CN3GECarukhxKsR6fTnTvJrQdg.jpg',3.600306276545744,3,'2026-09-10',2,NULL,NULL),(32740,'印度超人','कृष','延续了印度英雄罗希的故事：罗希得到外星人所赋予的超能力与智慧后，邂逅了一位美丽女子并生下儿子克里许那。然而因为一场交通意外，克里许那失去了双亲，和祖母相依为命。  　　当克里许那长大成人后，他发现自己除了从父亲身上遗传了俊俏脸庞外，竟同时拥有超能力，而这种力量将会改变他的一生。一次偶遇，克里许那爱上从新加坡来的少女琵莉亚，其后琵莉亚回国，克里许那伤心不已，祖母便建议他到新加坡去追寻自己的真爱。  　　一晚，克里许那与琵莉亚去欣赏一个马戏团表演，却发生了大火，堵住了所有的出口，把观众和马戏团团员都困在帐棚里。绝望的观众在火场中只能期待渺茫的奇迹。此时，克里许那马上化身为奇魔侠并发挥了他强大的力量，拯救了所有在场的人。  　　经此一役，克里许那领悟到他强大力量的背后，背负着保护大众的宿命，而这个宿命的最终任务，就是对抗邪恶博士，阻止他控制世界的骇人计划……',NULL,0,0,3.759988,5.5,46,154,'2006-06-23','hi',NULL,2.6675034694221327,3,'2026-09-10',2,NULL,NULL),(32823,'前往希腊剧院','Get Him to the Greek','亚伦（乔纳•希尔饰）是一个刚离开校园，走进社会的大学毕业生，他找到的第一份工作则是在一家唱片公司做助理。可对于他自己而言，这工作干得并非那么开心，因为这个助理每天都会被人呼之则来，挥之则去，最让亚伦头疼的就是还要应付公司里那帮说着色情笑话，总是让自己难堪的同事和上司。　　一天，上司突然派给亚伦一个工作：要陪伴公司的签约艺人、著名摇滚歌手奥尔德斯（拉塞尔•布兰德饰）到洛杉矶的希腊剧院，完成他的演出活动。其实这本来是一件再简单不过的事，但这位奥尔德斯可不是一般人，他每天都生活在殴打记者、酒后驾车、吸毒、夜场泡马子的醉生梦死状态中，而要把这位无论白天黑夜都处于神志不清的大人物按时弄到希腊剧院去，亚伦的这趟旅途注定充满了诸多不可预知的意外……','Aaron Green has 72 hours to get a Rock Star from London to L.A. Pray for him.',40000000,90029656,17.869443,5.9,612,109,'2010-06-04','en','/6g0li87w8LIK77QRUtOkQkM6bD7.jpg',3.23920883727279,3,'2026-09-10',2,NULL,NULL),(32856,'情人节','Valentine\'s Day','故事从一班巴格达至洛杉矶的飞机上悄然发生……从伊拉克战场上归国的美军军官凯特（朱莉娅·罗伯茨饰），在飞机上意外的结识了霍顿（布莱德利·库珀饰），两人在飞机上同坐一排，越聊越投机，凯特对这个帅气的男人颇有好感，但哪知霍顿却是一个同性恋，他正烦恼的是自己心仪的西恩（埃里克·迪恩饰）碍于压力，迟迟不敢公开自己的恋情，不过这也怪不得西恩，因为他是一名橄榄球运动员，如果自己一旦出柜，很可能就会毁了自己的前程。凯特回到家中，发现自己的母亲埃斯特尔（雪莉·麦克雷恩饰）正在和父亲埃德加（赫克托·埃里仲杜饰）聊着过去的风花雪月…… 洛杉矶一间花店的老板瑞德（艾什顿·库彻饰）一直挖空心思讨好女朋友摩莉（杰西卡·阿尔芭饰），他经常求教于自己青梅竹马的死党朱莉娅（珍妮弗·加纳饰）如何追到摩莉，但当他真正向摩莉求婚之后，却发现自己一直在意的，却是朱莉娅，与此同时，朱莉娅也发现自己的男朋友早就结婚了；高级白领莉兹（安妮·海瑟薇饰）正与男友乔许（托弗·戈瑞斯饰）商量如何过情人节，看上去甜甜蜜蜜的两人其实有着各自的秘密…… 2月14日的洛杉矶，10位男男女女，5对情各有别的恋人，在这个繁华的城市上演着爱的故事。','A Love Story. More or Less.',52000000,216485654,25.41929,5.7,1013,125,'2010-02-10','en','/gMdCXJnL8nX1tPsuxuf4SnxwPAN.jpg',3.3228591024922802,3,'2026-09-10',2,NULL,NULL),(33106,'疯狂的赛车','疯狂的赛车','职业自行车手耿浩在一次全国锦标赛中以0.01秒之差屈居亚军，随后又因商人李法拉的算计导致药检呈阳性，被终身禁赛，人生从此跌入谷底。多年后，耿浩靠运送水产维持生活，并照顾中风的教练，而李法拉早已靠推销补品“肾白银”发了财。教练去世后，耿浩决定找李法拉讨个说法；与此同时，李法拉为了摆脱妻子找来两名业余杀手，一伙台湾黑帮也正与泰国毒贩秘密交易。原本毫无关系的几路人马，因为一连串阴差阳错不断相遇，彼此的计划也被一次次搅乱，一场越来越失控的荒诞追逐由此展开……',NULL,0,0,0.406645,7.4,13,99,'2009-01-20','zh','/eOA1kBmrapjjuDIvogqAJyMruA2.jpg',2.414547074877153,3,'2026-09-10',2,NULL,NULL),(33155,'银河女战士','Galaxina','加拉西娜（Galaxina ）是一个栩栩如生而且性感的机器人，它被指派负责监督由无能的科尼利厄斯·巴特（Cornelius Butt）担任队长的星际太空警察巡洋舰的运行。当前任务要求船员在假死状态下休眠数十年，加拉西娜（Galaxina ）发现自己多年来一直孤身一人，随着情绪发展并爱上了船上的飞行员托尔（Thor）。','She\'s too good to be true...and too real to be otherwise.',5500000,4865000,2.141143,3.3,16,95,'1980-06-06','en','/A66Uw4QFyESPwnDnlvudKKR2Qsv.jpg',2.4357622708693825,3,'2026-09-10',2,NULL,NULL),(33157,'滑铁卢战役','Waterloo','1815年6月18日早晨，惠灵顿公爵所指挥的部队，聚集在比利时一个名为滑铁卢的小镇营地里。连绵不断的降雨带来了痛苦、潮湿和寒冷给士兵。但是这些士兵将会感谢这场从前夜就开始下的大雨，因为这场夏日暴雨不仅挽救了很多人的生命，同时，也即将改写了整个欧洲的历史，就是在这儿──滑铁卢战场。滑铁卢这场战役，是以拿破仑为首的法国军队独力抵抗以奥地利、普鲁士、俄国、英国为首的联盟国。拿破仑是个自信而又轻视敌人的人。他从未和惠灵顿交锋过，他相信惠灵顿不会在滑铁卢进行顽强抵抗。他期望一次进攻就能将惠灵顿赶下山脊，逼他後退。因此他根本没有料到会有一场大规模的战斗。战事一开始，法国好不容易才击败英国的先锋，但是法军的实力已被削弱了大半。当联军越接近法军，法军的士气越下降，军队也发生了骚动。不久，法军被彻底击败，这场战役只是打了一整日便结束。',NULL,25000000,3052000,1.894749,7,31,128,'1970-10-26','en','/zd4SV3qs5Xg7Yl8kqshU2fxTT0D.jpg',2.601552375312326,3,'2026-09-10',2,NULL,NULL),(33196,'海云台','해운대','2004年史上伤亡最惨重的海啸在印度尼西亚发生，给全球带来了巨大的冲击。当时韩国海云台地区土生土长的一个渔民万植正坐着远洋渔船驶向印度洋，却被突如其来的海啸卷入，而瞬间的判断失误让他失去了最信任和尊敬的长辈，妍熙的爸爸。就因为此事，他虽然很喜欢妍熙，却从不敢说出口。不过终于有一天，他鼓起勇气决心要向妍熙说出自己埋藏了多年的感情，准备了一个浪漫的求婚。万植的弟弟亨植是海云台海洋救生员，在进行海洋巡逻时他发现一名在海中挣扎的女子希美，并历尽周折将她救起。希美对这个淳朴的、又是自己救命恩人的青年亨植一见钟情，展开了猛烈的爱情攻势，亨植也并不讨厌她。国际海洋研究所的地质学家金辉博士，发现海云台一代的地壳运动异常，于是来到了海云台。他在那里偶遇离婚7年的前妻惟珍和女儿智敏，但智敏却完全对他的存在一无所知，这让他心情复杂。事业型女强人惟珍每天忙于工作，经常照顾不到小智敏。而海底每时每刻都在发生变化，终于，金辉博士的预言变成了现实，日本大马岛的塌陷引发了超大型海啸。时速达到800km的超大型海啸正在向着海云台的百万游人、享受平静生活的釜山市民无情袭来。  最幸福的瞬间面临的巨大考验，剩下的时间只有10分钟!海啸也无法席卷而去的他们的故事，现在开始了!',NULL,16000000,11301649,4.628525,6.5,48,120,'2009-06-06','ko',NULL,2.6966376209600518,3,'2026-09-10',2,NULL,NULL),(33217,'Diary of a Wimpy Kid','Diary of a Wimpy Kid','Greg Heffley is headed for big things, but first he has to survive the scariest, most humiliating experience of any kid’s life – middle school! That won’t be easy, considering he’s surrounded by hairy-freckled morons, wedgie-loving bullies and a moldy slice of cheese with nuclear cooties!','It\'s not a diary, it\'s a movie.',15000000,75700498,21.095489,5.9,355,92,'2010-03-19','en','/wnKqid7XLDD6d4EntCGKLL4OpNl.jpg',3.136794507498977,3,'2026-09-10',2,NULL,NULL),(33430,'双子的天空','Twin Falls Idaho','弗朗西斯和布莱克-福尔斯是一对连体婴儿，他们住在一家破旧旅馆的一个整洁的小房间里。虽然共享一些器官，但布雷克总是身体健康，而弗朗西斯则体弱多病。一位年轻女士闯入了他们的世界，颠覆了他们的世界。她与布雷克发生了关系，并说服两人参加万圣节派对，在那里他们可以穿上戏服冒充自己。最后，弗朗西斯真的病倒了，他们不得不分开。随后，他们面临着因分离而带来的身体和精神上的双重压力。','A different kind of love story.',0,0,0.619136,7,11,111,'1999-07-30','en','/boBbVY67YhGC4PWuqyQFysP3mN4.jpg',2.3787475741827273,3,'2026-09-10',2,NULL,NULL),(33468,'The Brain That Wouldn\'t Die','The Brain That Wouldn\'t Die','Dr. Bill Cortner (Jason Evers) and his fiancée, Jan Compton (Virginia Leith), are driving to his lab when they get into a horrible car accident. Compton is decapitated. But Cortner is not fazed by this seemingly insurmountable hurdle. His expertise is in transplants, and he is excited to perform the first head transplant. Keeping Compton\'s head alive in his lab, Cortner plans the groundbreaking yet unorthodox surgery. First, however, he needs a body.','Alive... without a body... fed by an unspeakable horror from hell!',62000,0,2.407048,4.4,32,82,'1962-02-25','en','/npg6NH4maZ4NTTWzA71KNCTvQNG.jpg',2.5769168275116274,3,'2026-09-10',2,NULL,NULL),(33511,'无处的男孩','Nowhere Boy','本片将揭示约翰·列侬没有父亲的童年生活，其\"生活在罪恶里\"的母亲和膝下无子的婶婶对他的争夺，他同两位同母异父的妹妹之间的亲情，以及母亲的意外身亡，而披头士的另一位成员保罗·麦卡特尼要到十七岁时才出现在他的生命里。','As a boy all John Lennon needed was love.',0,0,1.950959,7.2,244,98,'2009-12-25','en','/hNSxa74x44QN3sohb44dtUYGjw6.jpg',3.114675577480004,3,'2026-09-10',2,NULL,NULL),(33542,'红番区','紅番區','货车司机黄家驹（成龙）赴美向移居美国的骠叔祝贺新婚之喜，知晓其打算婚后与黑人妻子过安静的晚年生活，经营多年的超级市场也已卖给了年轻寡妇Elaine（梅艳芳）经营。由于一见面就对Elaine有好感，黄家驹主动协助Elaine打点起业务来。不久，以Johnny为首的一帮朋克党开始恶意捣乱破坏超市，面对他们，黄家驹面无惧色勇敢地用起了自己的拳头，同时不忘晓他们以人生大义，然而这波未平那波又起，黄家驹又被卷入了钻石赃物被盗的漩涡，受到了黑手党的追杀。','No Fear. No Stuntman. No Equal.',7500000,32392047,17.318839,6.5,240,91,'1995-01-30','cn','/mAxAlHJ4YsRGdTKF06a3Dqx4K1W.jpg',3.093152022298439,3,'2026-09-10',2,NULL,NULL),(33644,'当老牛碰上嫩草','How Stella Got Her Groove Back','Through good times and bad, Stella and Delilah have always had each other. Now, Stella\'s so busy building a life that she\'s forgotten how to really live. But Delilah is about to change all that. What starts as a quick trip to Jamaica, end as an exhilarating voyage of self discovery as Stella learns to open her heart and find love - even if it\'s with a man 20 years her junior.','Sometimes you have to break the rules to free your heart.',20000000,37672350,2.003047,6,24,124,'1998-08-14','en','/ygmuaJDLYxWJo8eNhq0A63hagrQ.jpg',2.5362501986263384,3,'2026-09-10',2,NULL,NULL),(33667,'君子协定','Gentleman\'s Agreement','菲利普（格利高里·派克 Gregory Peck 饰）是一名记者，带着儿子汤米（迪恩·斯托克维尔 Dean Stockwell 饰）和母亲（安妮·里维尔 Anne Revere 饰）来到大都市纽约，踌躇满志的他准备要在此干一番大事业。  　　上司交给了菲利普一个任务，撰写一系列关于美国存在的反犹主义的文章，为了能够更好地完成任务，菲利普决定假扮犹太人，切身体会一下身为一名犹太人的滋味与境遇。让菲利普没有想到的是，他的这一举动令他同女友凯西（多萝西·麦克吉尔 Dorothy McGuire 饰）之间的感情产生了裂缝，儿子亦因为父亲这一虚假的身份而遭到了同龄人的排挤与欺侮。在经历了种种挫折与困难之后，菲利普出色的完成了任务，然而，他的内心里却并不轻松',NULL,2000000,7800000,5.381536,6.8,47,118,'1947-11-11','en','/aCCRbcmigPk00f34hpJuWZuvABo.jpg',2.6991946506295745,3,'2026-09-10',2,NULL,NULL),(33676,'失贞记','Losin\' It','这是一部由柯蒂斯·汉森（Curtis Hanson）执导的1983年美籍加拿大喜剧电影，由汤姆·克鲁斯（Tom Cruise），雪莱·朗（Shelley Long），杰基·厄尔·海莉（Jackie Earle Haley）和约翰·斯托克威尔（John Stockwell）主演。 情节涉及试图失去童贞的四名少年。 Losin\'它主要在加利福尼亚的Calexico拍摄。','The last word about the first time.',7000000,1246141,2.550045,4.5,31,100,'1983-04-08','en','/7BQP8GzBW4ZZxqcc5tDH68yNeAI.jpg',2.5724341489690308,3,'2026-09-10',2,NULL,NULL),(33693,'哈哈笑','Funny Ha Ha','23 岁的玛妮（Marnie）不知道下一步该做什么，她竭尽全力探索大学毕业后的生活。玛妮还在尽情狂欢，她拖着疲惫的身躯起床去做那份可怜的临时工，她不知道自己是否在浪费时间去追求最好的朋友亚历克斯，而亚历克斯似乎对她并不感兴趣。',NULL,0,76901,0.362633,6.3,8,85,'2002-09-20','en','/4UsciNkAvuOZiM7ZfgLbfNR0WNJ.jpg',2.312342669091751,3,'2026-09-10',2,NULL,NULL),(33870,'最后的舞者','Mao’s Last Dancer','1972年，山东青岛某山村迎来了不同寻常的客人。来自北京的专员到此选拔具有舞蹈资质的孩子，11岁的少年李存信有幸当选。乘坐开往北京的列车，他来到中央五七艺术学校。经过七年的封闭式艰苦训练，他从一个最初并不喜欢芭蕾的后进生成长为优秀的舞者。在此期间，外面的世界风云变幻，身处象牙塔中的艺术工作者们也不难感觉那分毫的变化。1979年，休斯敦芭蕾舞团邀请李存信以交换生的身份前往美国。他踏足这块陌生的土地，内心深深感到旧有的信仰和资本主义物质精神文明的巨大碰撞。随着时间的流逝，李感受到自由、艺术和爱情的召唤，从而决定留在这片土地上……本片荣获2009年圣保罗国际电影节最佳外语片奖。','最后的舞者',25000000,20719451,1.876811,6.8,28,117,'2009-10-01','en','/mvHW6UTlrn60RhyYsoqxXxTPIFn.jpg',2.5769017338263134,3,'2026-09-10',2,NULL,NULL),(33909,'华尔街：金钱永不眠','Wall Street: Money Never Sleeps','20年后，戈登·盖柯（迈克尔·道格拉斯）从监狱出来了，准备重新投身到华尔街商战中，但他很快就无奈的发现自己已经跟不上时代了，现在这个华尔街比他当年更加贪婪和凶险。他警告人们危机随时都有可能降临，但没人把他当回事。戈登只好转向自己的家庭，试图修补与女儿（凯芮·穆里根）破裂的关系。戈登女儿与一个年轻的华尔街股票交易员杰克·摩尔（希亚·拉博夫）订婚了，后者希望戈登能帮他对付一个操纵全球股市的投资银行老板（乔什·布洛林），因为这个人导致了他导师（弗兰克·兰格拉）的自杀，并间接毁掉了他的前程。戈登与这个年轻人做了个交易，他帮助杰克复仇，而杰克也要帮他和女儿和好。','Gordon never gives up.',70000000,134748021,23.25645,5.8,493,133,'2010-09-02','en','/yBDscprDP8hyBHq49JQztNzHpNq.jpg',3.1959152401847835,3,'2026-09-10',2,NULL,NULL),(34016,'我配不上她','She\'s Out of My League','将疯狂的滑稽喜剧表演结合进老式风格的爱情故事，影片制造出来的是充满着狂野气息的娱乐氛围……刚刚20岁出头的柯克·凯特纳（杰伊·巴鲁切尔饰）是匹兹堡机场运输部门的一名普通的保安，如今他仍然和高中就认识的朋友们混在一起，他们分别是杰克（迈克·沃格尔饰）、斯坦纳（T·J·米勒饰）和德文（内特· 特罗伦斯饰）。柯克整天幻想着如何和他的前女友玛妮（林赛·斯隆饰）重修旧好，可是她却早就已经有了新男友——总而言之，柯克看起来似乎特别满足于自己日复一日的无所作为，直到有一天，一个让人眼前一亮的美丽女子莫莉（爱丽丝·伊芙饰）从他在机场的检查窗口前走过，并不小心把自己的手机遗失在了地上。莫莉是个聪明、世故且圆滑的女子，而且拥有着惊人的美貌，怎么看都与柯克是两个世界的人，所以当柯克出于礼貌归还手机，莫莉提出要拿两张曲棍球比赛的票来表达自己对柯克拾金不昧的感谢时，他没有多想就收下了——可是让他感到无比惊讶的是，这个美好得只存在于梦中的女孩，下一秒钟竟然向他提出了约会的要求。即使如此，莫莉却像是中了魔一样地下定决心，发誓一定要赢得柯克的青睐——这一切都令柯克感到纠结不已，他始终搞不明白，像莫莉这么优秀的女孩，怎么可能会对自己产生如此强烈的兴趣呢？在莫莉无法抵挡的攻势下，柯克也开始渐渐地相信，也许自己身上真的有什么特殊的品质吸引了这个美丽的女孩吧，他觉得是时候投入一份认真的感情了。随着两个人之间的关系越来越深厚，柯克第一次对自己有了信心，并思考是不是应该创造一个全然不同的未来。然而，当柯克第一次见到莫莉那身份尊贵的父母时，却因为一系列灾难性的意外而给他们留下了非常惨痛的糟糕印象，连带着也令这段爱情关系迅速走向灭亡。失去方知其珍贵，在好友的帮助下，醒悟过来的柯克开始想尽一切办法，就为了让莫莉重新回到自己的怀抱，所付诸的全部都是极尽献媚之能事的非常手段。但是，随着莫莉轻浮的前男友的加入和柯克前女友玛妮的突然回头，柯克的情感之路一下子变得复杂了许多，他只不过是在尝试着想要证明一个事实——只要你足够努力和坚持，真爱的力量是否真的能够弥补任何客观上的差距？','When she\'s this hot, You get one shot.',20000000,49779728,16.176976,5.9,525,104,'2010-03-11','en','/vQGgMQK5rHudXj8cps1xo073UZ5.jpg',3.2045113669069467,3,'2026-09-10',2,NULL,NULL),(34043,'恋爱蜜令','On the Line','性格缺乏自信的奇云，在火车上邂逅了梦中女神艾比，却不敢询问对方的姓名和联络方式。此后奇云对艾比朝思暮想，既找不到她，又无法忘记她。他的一群死党为了帮助他，决定发起一次 “寻人” 行动，试图通过缘分来决定两人是否会再次相遇.......',NULL,0,0,3.084874,4.1,10,85,'2001-10-26','en','/xJWpaR7btIdbv8KJEwb7nlBLbyB.jpg',2.3533486223339617,3,'2026-09-10',2,NULL,NULL),(34069,'太空运输','Cargo','地球不适合居住了，地球生态在人类的破坏下崩溃。人类企图在土卫五建立一个新的类似于地球的生态系统。故事发生在一艘生锈的太空货船KASSANDRA上。准备前往被开发成人类新的乐园的土卫五，却只有少数人才能去那里。事实上土卫五开发失败，如今呈现在众人面前的只是虚拟世界，一切都是假象。一部分知晓真相的自由斗士与当局做着斗争，并致力在地球上寻找已恢复或可改造至适宜人居的生态系统。年轻的女医官劳拉为了见到远在土卫五上生活居住亲人，踏上了前往42号太空站的货船，开始了为期48个月的太空生活。在她每天巡逻的过程中，劳拉穿过古怪而空荡荡的船舱，一开始直觉告诉劳拉她并不是一个人，好像有什么诡异的事情发生在隐藏在船舱中，直到货船船长离奇的死亡引发了一系列让人措手不及的阴谋，随船发现了这一真相，原来土卫五计划，是一个幌子，为了揭穿谎言，年轻的劳拉开始了一段探寻之路。并协同潜伏在该船上的自由组织领导人一起摧毁土卫五信号发射塔，向世人揭穿这一谎言，使住在拥挤不堪，瘟疫横行的太空城市中的人们有望回归地球开始新生活。',NULL,0,0,10.142218,5.9,140,120,'2009-09-24','de','/fLeOjQgNLd8N3xOfA73I0jSUXAS.jpg',2.9212763801471913,3,'2026-09-10',2,NULL,NULL),(34086,'太空入侵者','Spaced Invaders','A crew of Martians overhears a radio broadcast of Orson Welles\' \"War of the Worlds\" coming from Earth, and, thinking the Martian fleet is attacking Earth, they land their broken-down ship in a backwater mid-American town. As luck would have it, they land on Halloween and get mistaken for trick-or-treaters. Comedy ensues as the Martians try to get taken seriously.',NULL,3000000,15369573,1.586598,4.7,25,100,'1990-04-27','en','/vchyoV7mnaUd46meVO81yolXH2D.jpg',2.530831398045433,3,'2026-09-10',2,NULL,NULL),(34099,'Brave New Girl','Brave New Girl','Holly has everything it takes to be a star; the voice, the dream and the dedication, but she lacks the means to break away from her humble Texas upbringing. Then she gets the chance to attend an art and music school on the East coast and her future suddenly looks bright. But the road to stardom is a bumpy one.',NULL,0,0,0.18094,3.7,3,120,'2004-04-25','en','/zM2CFpnSwM8zvC22FFDWjTdJiPQ.jpg',2.1322570521900794,3,'2026-09-10',2,NULL,NULL),(34101,'好莱坞洗牌','Hollywood Shuffle','有抱负的演员和热狗摊员工鲍比泰勒因试镜剥削电影“Jivetime Jimmy\'s Revenge”中令人遗憾的角色而引起了祖母的愤怒。当Tinseltown Studios让泰勒担任主角时，他有一系列矛盾的梦想，用来讽刺好莱坞的非裔美国人的刻板印象，并且必须调和他的职业目标与他希望成为兄弟们的积极榜样的愿望。','Bobby Taylor was on his way to becoming a star, when a funny thing happened...',0,0,2.353483,5.7,19,78,'1987-03-20','en','/xidkzvrJfBeZ6wVcVOxobZruiR7.jpg',2.4865266002509827,3,'2026-09-10',2,NULL,NULL),(34106,'浮生若梦','You Can\'t Take It with You','故事描述华尔街巨子卡比为了赚钱而有意将工厂扩展到住宅区，但遭该地范德霍夫家族强烈反对。范家成员个个性情古怪，次女爱丽丝并在卡比公司担任秘书，又和卡比的儿子托尼相恋，引起卡比的不满。双方的纠纷最后由德高望重的祖父居中调解，卡比也变成乐善好施的慈善家。  改编自获得普立兹奖的百老汇舞台剧，采用喜剧手法宣扬新睦邻的主题，在三十年代面对经济不景气打击的美国老百姓因而感受到人际温情和生活希望，使这部洋溢着乐天思想的影片勇夺当年金像奖最佳影片奖殊荣。导演弗兰克．卡普拉以其一贯兼具讽刺性与娱乐性的手法拍出人情世态的微妙冲突，莱昂内尔．巴里莫尔、琪恩．阿瑟、詹姆斯．斯图尔特等演得也成功。','YOU\'LL LOVE THEM ALL FOR GIVING YOU THE SWELLEST TIME YOU\'VE EVER HAD!',1644736,7433101,3.426314,7.2,79,126,'1938-08-23','en','/9JltqbDyWstYW6gnvqDO6L5bOrx.jpg',2.8250712944796184,3,'2026-09-10',2,NULL,NULL),(34152,'种族情深','Crooklyn','《Crooklyn（种族情深）》是Spike Lee在94年拍的一部半自传电影，这部电影真实还原了美国纽约布鲁克林区和Bedford-Stuyvesant中普通黑人家庭70年代的生活，Spike Lee小时候就在布鲁克林区居住。这部电影的主角是一个叫Troy的小女孩，以及她的家庭，她的4个兄弟，她的父母。同时斯派克·李在里面也饰演了一个瘾君子的角色。Spike Lee是美国最具黑人意识的导演，所拍摄的题材大都跟黑人的出路、觉醒、种族歧视相关。他的电影风格犀利、节奏明快且极具爆发力，对于黑人的习性和社会困境有相当深刻的体会。所以本片就是通过对一个70年代普通黑人家庭故事的叙述，反映当时美国黑人的生活环境。',NULL,0,0,1.89218,6.7,31,115,'1994-05-13','en','/iFqe07F78SO0SIBzWcK4I5MwNvP.jpg',2.5978727010477938,3,'2026-09-10',2,NULL,NULL),(34314,'插翅难飞','Turbulence','圣诞节前夕，空气中弥漫着节日的气息，“越州47”航班上，坐满了即将赶回家中同亲人们团聚的乘客，其中，有两个人显得是那样的格格不入，他们是穷凶极恶的罪犯史达斯（布莱丹·格里森 Brendan Gleeson 饰）和韦弗（雷·利奥塔Ray Liotta 饰），两人被四名警察押解着，前往洛杉矶。  　　最坏的情况发生了，史达斯袭击了警察，击毙了机长，一时间，飞机进入了无人驾驶的危险状态。就在这个节骨眼上，机智的空姐泰利（罗伦·荷莉 Lauren Holly 饰）果断出手，飞机重新回到了掌控之中，然而，真正危险的不仅仅是前方即将飞入的雷暴区，还有阴险狡诈，杀人如麻，对泰利垂涎已久的韦弗。','If you weren\'t afraid of flying before, you will be now.',55000000,11466088,4.700024,5.2,62,100,'1997-01-09','en','/8N63NGWIErS7jUvR5NeVWDZEeZJ.jpg',2.7227134200874734,3,'2026-09-10',2,NULL,NULL),(34335,'九死','Nine Dead','洛杉矶接连发生9起绑架案，被绑架者来自各行各业，有神父（马克·麦克雷 Marc Macaulay 饰）、检察官（梅丽莎·乔·哈特 Melissa Joan Hart 饰）、演员还有俱乐部老板，彼此间似乎没有任何关联，而绑架案却都由一人所为，一个戴着蓝色面具、一身黑衣的男子。此案惊动洛城，警方全员出动，却始终找不到任何头绪。与此同时，在城市某各个角落黑暗潮湿的地下室内，9个被绑架者迎来了人生中最为痛苦难熬的时刻。蒙面人要求他们思考被绑架的原因，然后每个10分钟便杀掉一人，直到他们找到原因为止。  人质们激烈争论，相互攻讦，抑或检讨人生中所犯下的错误。时间一分一秒地流逝，死神的判决越来越近……','It doesn\'t have to end this way',2000000,0,9.68793,5.2,84,98,'2010-01-01','en','/3zAYW3q6gawnV68XdXtkBNBgUEX.jpg',2.792313674467725,3,'2026-09-10',2,NULL,NULL),(34341,'Men with Brooms','Men with Brooms','A witty and clever comedy that follows four longtime curling friends reunited by the last wishes of their recently deceased coach and set out to win the Golden Broom. Realising that the out of shape crew will be hard-pressed to win without a coach, Cutter swallows his pride and calls upon a retired curling champion - his estranged father. Now, these men with brooms, along with their new eccentric coach and Cutter\'s new romantic interest Amy, set off on a comedic journey which takes them from frozen lakes to huge arenas, searching for perfect stones, lost loves and second chances.',NULL,7500000,4245870,1.369528,4.5,7,102,'2002-09-20','en','/qWWvljKlmYwf1XtlJ0vu0u66xpi.jpg',2.283850895281144,3,'2026-09-10',2,NULL,NULL),(34417,'Good Intentions','Good Intentions','Meet Etta Milford. Loving Wife. Doting Mother. Armed Robber. Etta\'s husband constantly blows their money on make-shift inventions. When she decides to secretly take \"investment\" matters into her own hands - things quickly go awry! With their savings gone, her husband suspicious, and their children out of control, Etta concocts a scheme to get back their money and save her family.',NULL,0,0,0.304566,5,6,85,'2010-03-09','en','/xBv29yp2y7jYnRJTyNio9MYKCZs.jpg',2.254300226525446,3,'2026-09-10',2,NULL,NULL),(34549,'迈克斯的壮举','Max Keeble\'s Big Move','12岁的初中生迈克斯·基伯是个倒霉蛋，学校里的小混混经常欺负他，校长也总是找他的麻烦，还有一个恶毒的冰激凌小贩跟他作对，受尽劫难的迈克斯被冠以“傻冒”的绰号，成为众人取笑的对象。\r 不过迈克斯的苦日子好像就要过去了，他的父亲因为工作关系准备举家迁往芝加哥，迈克斯兴奋之余拟订了一个计划：在离开之前报复所有欺负过他的人，于是一系列恶作剧式的报复行动展开了，迈克斯的仇敌们也被搞得晕头转向、狼狈不堪。就在这时，他的父亲突然宣布了取消迁往芝加哥的计划，并辞掉工作，自立门户的打算。这无疑给正在兴头上的迈克斯当头一棒：这下可没法逃脱那些如狼似虎的对手了......','His World. His Rules.',12000000,17292381,1.081822,5.4,33,86,'2001-10-05','en','/eJ4olY0dZMC1MfMhRkLOWisWYtu.jpg',2.5927277198073906,3,'2026-09-10',2,NULL,NULL),(34563,'我们家的婚礼','Our Family Wedding','非洲裔的美国人马库斯（兰斯·格罗斯 Lance Gross 饰）和来自墨西哥的美女露西亚（亚美莉卡·费雷拉 America Ferrera 饰）决定结婚了！他们的决定立刻就得到了身边朋友们的真诚祝福，因为在周遭人眼中，马库斯和露西亚简直仿佛生来就注定会走到一起一样，是一对天设地造的神仙眷侣。  　　沉浸在深深幸福中的马库斯和露西亚决定将彼此的父母拉拢到一起进行一次聚餐，没想到在餐桌上，一连串的不愉快让双方的父亲布拉德（福里斯特·惠特克 Forest Whitaker 饰）与米格尔（卡洛斯·曼西亚 Carlos Mencia 饰）成为了水火不容的死对头。可是，个人恩怨并不能阻止马库斯和露西亚迈向婚姻的坚定步伐，收起了各自的情绪之后，布拉德开始同米格尔一起，筹备孩子们的盛大婚礼。','To have and to hold... \'Til dads do us part.',14000000,21409028,6.733485,5.7,39,103,'2010-03-12','en','/zvRn8aM9lmuBbbJVJgxZl41zarB.jpg',2.643902495871135,3,'2026-09-10',2,NULL,NULL),(34584,'大魔域','Die unendliche Geschichte','故事讲述小男孩Bastian Bux迷上了一本名叫《永不结束的故事》的书，故事将Bastian Bux深深吸引到书本里，甚至让他幻想自己就是其中最重要的角色。而书中描述的幻想国逐渐被“空无”吞噬，女王因为重病无法抵抗“空无”，于是幻想国派出勇者Atreyu寻找拯救女王的药，Bastian Bux就在Atreyu的追寻中体验幻想国的每个地方、认识每个人物，随着Atreyu的欢喜与挫折起伏……','A boy who needs a friend finds a world that needs a hero in a land beyond imagination!',27000000,20158808,47.862016,7,1002,102,'1984-04-05','en',NULL,3.5979115461409963,3,'2026-09-10',2,NULL,NULL),(34592,'毁灭僵尸','ZMD: Zombies of Mass Destruction','这次同志电影扩展到了丧尸题材，故事很简单一个在美国华盛顿的小岛生活美好安宁，直到病毒爆发僵尸横行连带同志角色也卷入其中，是让同志一起杀出个黎明还是消灭同志僵尸?','They\'re just like you ... only dead',0,0,1.563711,4.7,31,92,'2009-01-01','en','/3K80OoyUb93qhx5jMUsNuKlV3IT.jpg',2.572630372128085,3,'2026-09-10',2,NULL,NULL),(34647,'遁入虚无','Enter the Void','《遁入虚无》讲述了奥斯卡和妹妹琳达来到东京后发生的故事，哥哥靠卖毒品为生，妹妹则在夜总会跳钢管舞。在一次毒品交易中，奥斯卡被警察撞见，并被手枪击中。就在奥斯卡垂死的时候，他的意识发生了变化。他又看到了五岁时候父母的死亡。种种的幻象让奥斯卡无法死去，他的精神脱离了身体，自由地穿越在各个时空，但是他无法与任何一个人对话，连自己的妹妹也不例外。',NULL,13000000,754249,20.39955,7.2,387,161,'2009-05-05','en','/krKnsfvSJM1PL40tLicRhVQ6kuG.jpg',3.287976454416668,3,'2026-09-10',2,NULL,NULL),(34653,'单身男子','A Single Man','本片根据美国小说家克里斯托弗·伊舍伍德（Christopher Isherwood）1964年的同名小说改编。故事发生于1962年11月30日的美国加州洛杉矶。中年英语教授乔治·费尔科纳（科林·费斯 Colin Firth 饰）沉浸在与自己十六年共同生活的同性伴侣吉姆（马修·古迪 Matthew Goode 饰）车祸死亡的阴影中无法自拔，精心准备打算自杀。电影记录了乔治从早到晚一天的活动，包括他在学习授课，处理与学生肯尼（尼古拉斯·霍尔特 Nicholas Hoult 饰）的关系，并参加伦敦旧情人夏洛特（朱丽安·摩尔 Julian Moore 饰）私人晚餐的过程。\r 　　本片获奥斯卡最佳男主角提名（科林·费斯），英国电影电视协会最佳服装设计提名和最佳男主角奖，金球奖最佳男主角提名，最佳女配角提名（朱丽安·摩尔）和最佳原创电影音乐提名，以及威尼斯电影节金狮奖提名和最佳男主角奖。 ©豆瓣',NULL,7000000,0,21.626288,7.3,463,101,'2009-10-19','en','/aCusmxD8dKq3IqmXTmjyCVcUiBB.jpg',3.3548692744407163,3,'2026-09-10',2,NULL,NULL),(34697,'蝴蝶','Butterfly','奥逊·威尔斯所扮演的劳奇法官，指控十年前被妻子遗弃的矿场看守员杰斯·泰勒与其女乱伦通奸。而此时据说是凯蒂所诞婴儿之父沃什，又回来想带凯蒂离开······','A Controversial Thriller of Murder and Revenge.',0,0,1.063615,5,12,107,'1982-02-05','en','/nzcjcO4dX1laL6zP2Poq5gcwM3R.jpg',2.3877740262453733,3,'2026-09-10',2,NULL,NULL),(34723,'小鬼闯天关','The Adventures of Huck Finn','虎克（伊利亚·伍德 Elijah Wood 饰）的父亲在他很小的时候就抛弃了他，可是近日来，这个男人的行为非常的反常，竟然开始主动关心起自己的儿子来，实际上，他心里打着自己的算盘。原来，虎克得到了一笔价值不菲的遗产，这就是父亲接近他的原因。不仅如此，虎克的父亲甚至打算杀死亲生儿子来获得这笔钱。\r 　　为了避开父亲，也为了保命，虎克踏上了冒险的旅途。在途中，虎克结识了名为吉姆（考特尼·万斯 Courtney B. Vance 饰）的黑人奴隶，吉姆因为担心自己被卖掉而从雇主家里逃了出来。就这样，虎克和吉姆结伴前行，虎克决定帮助吉姆重新获得本就应该属于他的自由。','For anyone who has ever dreamed of running away from it all',6500000,0,2.163683,6.2,42,108,'1993-04-02','en','/8VpQZ43hdaTUmkMoe2CnED1Y2fS.jpg',2.6568881437140703,3,'2026-09-10',2,NULL,NULL),(34769,'保卫者','Defendor','这是一部走超级英雄模式的非漫画改编电影……长得虎背熊腰但精神上却有点萎靡不振的亚瑟·帕平顿（伍迪·哈里森饰），身上脸上满是受到重创之后留下的於痕，脖子上还打着用来固定头部的劲托，总是旧伤未好，又添新伤，让人忍不住感到困惑，想知道他究竟是如何把自己搞得这么狼狈的。在法庭指派的精神病专家帕克医生（吴珊卓饰）的穷追不舍之下，并得到了她再三的保守秘密的声明，亚瑟终于决定将自己隐藏起来的真相告诉她，原来他还拥有另外一个身份——“保卫者”，过着全然不同的双重人生。','An unexpected hero will rise.',3500000,44462,8.45342,6.5,195,101,'2009-09-12','en','/a1ce5xYYkwSCqIHh0nGKnh7Zs7Q.jpg',3.0237612696886615,3,'2026-09-10',2,NULL,NULL),(34806,'后备计划','The Back-Up Plan','多年寻觅真爱不获，大龄女青年佐伊 决定通过生个孩子改变自己的生活。就在她人工受孕的当天，在大街上遭遇“抢车男”斯坦。斯坦的风趣和浪漫似乎契合了佐伊对于另一半的所有幻想，可是不幸的是通过人工受孕，佐伊真的怀孕了。遭遇真爱之时，受孕成功的消息无疑成为一颗定时炸弹，佐伊不知道面前的这个男人能否接受这件事情。满怀忐忑的佐伊告诉了斯坦自己怀孕的事情，幸运的是斯坦最终选择了继续和她在一起。不过，对于即将到来的新生命，斯坦的内心依旧充满不安。','Fall in love, get married, have a baby. Not necessarily in that order.',35000000,77477008,18.38292,5.7,458,106,'2010-04-23','en','/om4I64yOJq9wWtN88gx7LjUHEPJ.jpg',3.1588949825743122,3,'2026-09-10',2,NULL,NULL),(34813,'绝命反击','The Losers','有一个受聘于美国政府的机密组织，里面的成员均是来自中情局、国家安全局、特种部队等等的精英，分别有为首的领军人物克莱（杰弗里·迪恩·摩根饰）、玩世不恭的简森（克里斯·埃文斯饰）、武器专家罗克（伊德瑞斯·艾尔巴饰）以及普奇（哥伦布·绍特饰）、酷格（奥斯卡·贾恩那达饰）等人。这群特工在玻利维亚执行一次并不算难度太高的任务，却不想因为内鬼麦克斯（杰森·帕特里克饰）的出卖，不但行动砸锅了不说，还让几个人背上了不光彩的骂名，而且每个人的生命也笼罩在死亡的威胁里。 　　好歹大家都是受过专业军事训练的，怎能就此吃瘪？克莱将计就计，扔了一个烟雾弹，伪造了大家的死亡，而后改名换姓为\"失败者\"，秘密的潜回美国，准备一雪前耻。这时候，一位叫做爱莎（佐伊·索尔达娜饰）的神秘女郎的出现，也加入失败者组织，与克莱一行人开始复仇。克莱一行人能否顺利的抓出内鬼，重新找回尊严呢？关键之处的秘密，其实全系于功夫高强的爱莎一身……','Anyone Else Would Be Dead By Now.',25000000,23580000,24.903418,6.2,515,97,'2010-04-23','en','/hvBrrM3nPRxmHBDnAc43EC1hhDP.jpg',3.257850270854854,3,'2026-09-10',2,NULL,NULL),(34851,'新铁血战士','Predators','一道极强的亮光，将分处五大洲的8个人带到了一片未知所在。他们身背降落伞从高空坠落，继而落入一望无边的雨林。这群人中有车臣部队战士、以色列国防军、墨西哥特种部队成员、FBI通缉的要犯、日本黑帮稻川会头目以及一名与其他人格格不入的医生。他们彼此互不相识，也不知道为何被带到了这片陌生丛林。在罗伊斯（阿德连·布隆迪 Adrien Brody 饰）的带领下，众人开始朝制高点进发，最终发现他们竟然置身在一颗外星球中。与此同时，凶猛邪恶的猛兽接连向他们袭来，罗伊斯意识到，他们不过是一群外星生物选出的猎物，而这片雨林正是外星人的狩猎场。\r 　　危机四伏，这些无所依靠的人类不得不去面对身形巨大、嗜好杀戮的铁血战士……','Fear is Reborn',40000000,126248813,47.649554,6,1206,107,'2010-07-03','en','/mZWmj2is6Ixw0WCYGt15S6kgRhC.jpg',3.462415710270723,3,'2026-09-10',2,NULL,NULL),(34941,'意气风发','The Last Time I Committed Suicide','这是一部美得让人心悸，但很少有人看过的电影。片名直译是“我的最后一次自杀”。影片改编自“垮掉的一代”先驱人物尼尔凯塞迪写给凯鲁亚克的一封信。尼尔凯塞迪一生不停地流浪，1968年客死于墨西哥的一条铁路边上，终年42岁......','Life is what happens when you\'re busy making plans',0,0,0.596889,6.7,7,92,'1997-06-20','en','/5AM1oDIlsWBBLYecetUAHOWv9dW.jpg',2.288368071620472,3,'2026-09-10',2,NULL,NULL),(35019,'Nanny McPhee and the Big Bang','Nanny McPhee and the Big Bang','Nanny McPhee appears at the door of a harried young mother, Mrs. Isabel Green, who is trying to run the family farm while her husband is away at war. But once she’s arrived, Nanny McPhee discovers that the children are fighting a war of their own against two spoiled city cousins who have just moved in. Relying on everything from a flying motorcycle and a statue that comes to life to a tree-climbing piglet and a baby elephant, Nanny uses her magic to teach her mischievous charges five new lessons.','You\'ll Believe That Pigs Can Fly!',35000000,93246388,23.835055,6,436,109,'2010-03-26','en','/9cgHfgBXVZmVR63AhwJ82R1kAFS.jpg',3.195817853510138,3,'2026-09-10',2,NULL,NULL),(35032,'风流海盗','The Pirate','曼纽娜（朱迪·加兰 Judy Garland 饰）即将和镇长佩德罗（沃尔特·斯勒扎克 Walter Slezak 饰）携手步入婚姻的殿堂，可实际上，曼纽娜并不爱佩德罗。当地流传着关于海盗的传说，曼纽娜对海盗的生活充满了好奇和希冀，觉得那一定充满了无数的乐趣。\r 　　吟游诗人萨拉芬（吉恩·凯利 Gene Kelly 饰）爱慕着曼纽娜的美貌，同时也知道曼纽娜对于海盗的好奇，于是，他谎称自己就是传说中的海盗。果不其然，曼纽娜立刻就对萨拉芬产生了浓厚的兴趣。萨拉芬的所作所为激怒了佩德罗，在镇民们的帮助下，曼纽娜躲了起来。哪知道这场闹剧却意外的揭开了佩德罗隐藏了多年的秘密。','The great MGM musical romance',3700000,2956000,0.90522,6.6,17,102,'1948-06-11','en','/ltoy9asHYuLcEq78jjvZPjH6LCG.jpg',2.466820921465953,3,'2026-09-10',2,NULL,NULL),(35056,'Date Night','Date Night','Phil and Claire Foster fear that their mild-mannered relationship may be falling into a stale rut. During their weekly date night, their dinner reservation leads to their being mistaken for a couple of thieves – and now a number of unsavoury characters want Phil and Claire killed.','One ordinary couple. One little white lie.',55000000,152263880,38.06168,5.9,1122,97,'2010-04-08','en','/3qnFJGHEODr2n0bTizjUAV1yZOe.jpg',3.4072384726975744,3,'2026-09-10',2,NULL,NULL),(35073,'The Beast from 20,000 Fathoms','The Beast from 20,000 Fathoms','The Beast from 20,000 Fathoms is a 1953 science fiction film directed by Eugène Lourié and stars Paul Christian, Paula Raymond and Cecil Kellaway with visual effects by Ray Harryhausen. The film is about an atomic bomb test in the Arctic Circle that unfreezes a hibernating fictional dinosaur, a Rhedosaurus, that begins to wreak havoc in New York City.','It\'s alive !',210000,5000000,2.043661,6.7,41,80,'1953-06-13','en','/llJIxUTCmlDKbd4yBLTjrJW5QUF.jpg',2.659465116659588,3,'2026-09-10',2,NULL,NULL),(35169,'回到荒野','Furry Vengeance','自信满满野心勃勃的丹尼（布兰登·费舍 Brendan Fraser 饰）做梦也没有想到，自己竟然会有被一群野生动物整的狼狈不堪的一天，故事要从不久之前说起。作为一名小有成就的房地产开发商，丹尼的眼中除了利益和金钱别无他物，只要能够赚钱，他可以付出一切代价。  　　一片原始森林的出现让丹尼嗅到了商机，他决定铲除这片森林，将其开发成为一个集住宅、娱乐、商业于一体的成熟商圈。没想到，丹尼的计划被森林中的动物们得知了，眼看着赖以生存的家园将被毁于一旦，不愿坐以待毙的动物们决定行动起来，为捍卫自己生存的权利而展开了一场与人类的斗争。面对动物们的强烈反抗，丹尼会采取怎样的对策呢？','He came. He saw. They conquered.',35000000,39340177,13.668633,4.6,149,92,'2010-04-02','en','/604qqquWBgFy34jLhHLtebFPQy6.jpg',2.8759912407751913,3,'2026-09-10',2,NULL,NULL),(35199,'Wordplay','Wordplay','From the masters who create the mind-bending diversions to the tense competition at the American Crossword Puzzle Tournament, Patrick Creadon\'s documentary reveals a fascinating look at a decidedly addictive pastime. Creadon captures New York Times editor Will Shortz at work, talks to celebrity solvers -- including Bill Clinton and Ken Burns -- and presents an intimate look at the national tournament and its competitors.',NULL,0,0,0.906096,7.3,10,94,'2006-06-26','en','/8AY7EkxJwB8Ow5iPe41GOJesxzn.jpg',2.3613724132276155,3,'2026-09-10',2,NULL,NULL),(35219,'失踪的人','The Missing Person','Private detective John Rosow is hired to tail a man on a train from Chicago to Los Angeles. Rosow gradually uncovers the man\'s identity as a missing person; one of the thousands presumed dead after the 9/11 terrorist attacks on the World Trade Center. Persuaded by a large reward, Rosow is charged with bringing the missing person back to his wife in New York City.','John Rosow is a private investigator. And an alcoholic. He just got the case of his life.',0,0,1.161034,6.4,9,95,'2009-01-16','en','/fwjX5pXrylMXtPCmYq7MzoTVJ5H.jpg',2.33748666194697,3,'2026-09-10',2,NULL,NULL),(35688,'我为什么也结婚了？','Why Did I Get Married Too?','泰勒·佩里携其热门喜剧《我为什么结婚了？》中的魅力演员阵容再度集结，为我们带来八位大学好友在婚姻生活中挣扎的下一篇章——《我为什么结婚了2》？','Marriage is an institution they\'re committed to.',20000000,60072596,2.986286,6.1,29,121,'2010-04-02','en','/ctWuunKnm8bcG8cz40wndtdvV0W.jpg',2.5790194600539063,3,'2026-09-10',2,NULL,NULL),(35689,'骗局','Don McKay','唐·麦凯是一所中学的看门人，在一场悲剧后背井离乡。25年后，当他回到家乡时，又与老情人重新燃起了爱火，只是，老情人此时正遭受癌症的折磨，但不管怎么说，这次回家带给唐·麦凯的要比希望的多……一个略带惊悚意味的爱情故事，情节基调微微伤感，却在伤感中蕴藏着深厚的情感爆发力。影片的三位主演均为好莱坞的奥斯卡级人物，托马斯·哈登·丘奇曾凭借《杯酒人生》获得奥斯卡最佳男配角提名，伊丽莎白·苏和梅丽莎·里奥则分别凭借《远离赌城》和《冰冻之河》获得奥斯卡最佳女主角提名。','Some secrets are better left buried.',0,0,1.496454,5.4,21,87,'2009-04-24','en','/pkziSZ6vmwFnhybgBAM96Q6xKMr.jpg',2.50242146462126,3,'2026-09-10',2,NULL,NULL),(35690,'最后一支歌','The Last Song','父母的离婚让17岁的维罗妮卡（麦莉·赛勒斯 Miley Cyrus 饰）始终不能释怀。她曾是远近闻名的钢琴神童，可在父亲搬到泰碧岛上生活之后，就拒绝弹钢琴，并且不再和父亲说话。为化解父女之间的矛盾，母亲带着她一起到岛上和父亲共度夏天。父亲史蒂夫（格雷戈·金尼尔 Greg Kinnear 饰）是一位钢琴教师，在海岸的小镇上过着平静的生活，为当地教堂创作音乐。刚到达泰碧岛的时候，维罗妮卡对一切都充满了恐惧和敌意，连父女二人都无法有很好的交流。而在当地极受欢迎的帅哥维尔布雷克里（利亚姆·海姆斯沃斯 Liam Hemsworth 饰）也吃了闭门羹。不过在一起看护海龟巢穴之后，维罗妮卡改变了自己的敌对态度，这两个年轻人也开始慢慢坠入爱河。渐渐解开自己心结的维罗妮卡开始尝试着用钢琴和音乐来和自己的父亲沟通，而她不知道的是，史蒂夫这个时候已经罹患了不治之症……','A story about family, first love, second chances and the moment in life that lead you back home.',0,0,23.139971,6.9,923,107,'2010-03-31','en','/f9E4hMoqCYhKK3oUpMFiT2EMUqC.jpg',3.501498869077719,3,'2026-09-10',2,NULL,NULL),(35691,'写给上帝的信','Letters to God','影片基于真实故事改编。一个与癌症抗争的小男孩写信给上帝，感动了他的街坊四邻，也帮助周围的人看到希望。',NULL,0,0,3.644872,6.5,37,110,'2010-04-09','en','/vkOXEUy9J0GNtrqXY9Z9rl9pDHf.jpg',2.6376176106966804,3,'2026-09-10',2,NULL,NULL),(35696,'女篮辣哥','Juwanna Mann','杰尼尔（小米盖尔-A·努耐兹 Miguel A. Núñez Jr. 饰）美国男子篮球联盟的大明星，虽然球技了得，但是他的个性却非常的自大和自私。在比赛中，杰尼尔从来不会给队友传球，只想着自己表现，不仅如此，他还明目张胆的顶撞教练裁判甚至观众。终于，忍无可忍的职业篮球联盟处罚了杰尼尔，对他进行了禁赛处理。\r 无法比赛的杰尼尔一下子就是去了所有的经济来源，陷入了拮据之中，与此同时，无法再站到赛场上与篮球为伴，令杰尼尔感到十分的痛苦。为了打球，杰尼尔男扮女装参加了女子篮球队女妖队的入队考核，顺利的拿到了名额，但在这里打球，杰尼尔必须时时刻刻注意，不能让自己的“小秘密”泄露出去。',NULL,15600000,0,2.244947,4.2,20,91,'2002-06-21','en','/1m5sbTbifesBhCrkE0gJncwMGXw.jpg',2.4846869805239558,3,'2026-09-10',2,NULL,NULL),(35791,'生化危机4：战神再生','Resident Evil: Afterlife','爱丽丝（米拉·乔沃维奇 Milla Jovovich 饰）来到东京，向保护伞公司复仇。后者潜藏在地球的底部，威斯克（肖恩·罗伯茨 Shawn Roberts 饰）执行着自以为是的安全技术标准。爱丽丝闯入了禁区，直捣黄龙。而威斯克竟然不惜毁灭城市做困兽斗。最终，当他驾驶着直升机逃离时，却被爱丽丝胁迫，情急之下，他向爱丽丝身上注入了具有对T细胞的免疫病毒，令她丧失了超能力，只能驾机飞翔荒无人烟的阿拉斯加。地球上已经177天没有生命迹象。然而，爱丽丝却意外发现了克莱尔（艾丽·拉特 Ali Larter 饰）。她们循着阿卡迪亚信号，回到了地狱之城，满眼的僵尸令人触目惊心。迎接她们的是同样听到信号的幸存者。在神秘犯人克里斯（文特沃斯·米勒 Wentworth Miller 饰）的帮助下，她们向阿卡迪亚之船进发……','She\'s back...And she\'s bringing a few of her friends.',60000000,300228084,2.143764,5.8,1363,97,'2010-09-09','en','/sAgqj0pblY8BWrjml6FD6tZlrRe.jpg',3.3449677041084613,3,'2026-09-10',2,NULL,NULL),(35944,'逃狱松一松','Lucky Break','Half-way through his 12-year prison sentence for an incompetent armed robbery, Jimmy Hands gets a lucky break: he\'s transferred to a prison from which he can probably escape. He convinces the governor to stage a musical in an old chapel next to the prison\'s outer wall. He rounds up volunteer actors and puts his escape plan into production. Two other barriers, besides the wall, confront him: the arrival of a nasty inmate, John Toombes, who insists on joining the escape, and Jimmy\'s feelings of attraction for Anabel, a social worker who agrees to appear in the play. Opening night approaches: is this Jimmy\'s breakout performance?',NULL,0,0,0.669169,6.5,11,107,'2001-08-24','en','/63JHVXD2bkPBdIFgprqXKu3k8bw.jpg',2.376630411990367,3,'2026-09-10',2,NULL,NULL),(36046,'事业与荣誉','The Work and the Glory','Steed一家从他们佛蒙特州的老家搬到纽约北部的新家，宗教的冲突几乎要毁掉他们家庭间的紧密关系。雇来的帮手间的宗教冲突使这个辛勤努力的家庭的生活更加困难。两兄弟同时爱上了一个富商的女儿立即使矛盾更加恶化。','One Man....A Remarkable Vision; One Family....A Desperate Struggle',7500000,3347647,0.571663,6.1,7,110,'2004-11-24','en','/b5Y3hNp7jY2rVea9EP0iCToNMlO.jpg',2.2865971679658563,3,'2026-09-10',2,NULL,NULL),(36047,'辣手美眉','The In Crowd','A mentally disturbed young woman takes a job at a posh country club and falls in with a clique of wealthy college kids where she\'s taken under the wing of the clique\'s twisted leader, who harbors some dark secrets too terrifying to tell.','What would you do to get in?',15000000,5217498,0.249245,4.7,15,105,'2000-07-19','en','/j77l405846qiLb8RGb1egu7ON3r.jpg',2.427861155085117,3,'2026-09-10',2,NULL,NULL),(36095,'X圣治','キュア','东京连续发生数起离奇命案，所有尸体上皆刻上“X”符号，而在场的嫌犯都不记得自己所为，这令警察们大为困惑。刑警高部断定有人利用催眠术行凶，一名在海岸徘徊的半失忆青年间宫成为怀疑重点，与该青年接触过的教师、警察和女医生都这样杀了人。随后高部着手对间宫进行审讯，却总被他的言语打乱，调查毫无进展，再加上妻子因精神疾病住院，高部的情绪变得极为糟糕。高部的朋友心理学家佐久间劝他不要再和间宫接触，自己却被无意识使用催眠术的间宫逐渐操控。不久后，间宫从精神病院逃走，而佐久间被发现自杀身亡。高部来到以前间宫提过的一间废弃小屋中，遇到了间宫并将他杀死，对方满足地死去。然而一切并没有就此结束……','Madness. Terror. Murder.',20000,99000,0.212443,7.4,63,111,'1997-11-06','ja',NULL,2.768101601342571,3,'2026-09-10',2,NULL,NULL),(36334,'截稿','Deadline - U.S.A.','With three days before his paper folds, a crusading editor tries to expose a vicious gangster.',NULL,0,0,0.225627,6.9,17,87,'1952-03-14','en','/mXT9BjqJFwoIq48zviZ0Vc9O8B9.jpg',2.467321102890126,3,'2026-09-10',2,NULL,NULL),(36351,'迷幻人生','Light Sleeper','施罗德曾说，“迷幻人生”是一部关于男性孤独者的三部曲中的最后一幕，另两部是出租车司机和美国舞男。作为施罗德最紧张和最有效的剧本之一，“迷幻人生”讲述了纽约市一名毒贩与中年危机作斗争并被陷害进毒品有关的谋杀案的故事。Schrader回到曼哈顿的那些简陋的街道上，是一种明显的忧郁，弥漫着一种悔恨和渴望的气氛，这给它所有的人物都增添了微妙的色彩。威廉达福提供了一个令人痛苦和强大的表演，展现毒贩的动人斗争，重新组合他的生活，并与失去的爱重新联系。','He was a good man in a deadly business. She was his only way out.',5000000,0,6.063868,5.7,15,103,'1992-08-21','en','/fFSdOYKp80rcK81KuNW3rz7FcLX.jpg',2.4471959196588497,3,'2026-09-10',2,NULL,NULL),(36355,'海豚的故事','Flipper','十二岁的男孩桑迪十分不开心，因为他的这个暑假注定非常无聊。因为父母离异，母亲没有时间照顾他，于是把桑迪送到了住在海边的舅舅波特那里。但是，面对这个从未谋面的舅舅，桑迪一点好感也没有。在这里，桑迪没有一个朋友，唯一一个年纪相仿的小男孩马维还患有自闭症，从来不愿意和人交谈。海边的枯燥生活更是让他十分懊恼，他唯一想的就是快点逃离这里，和他的音乐组合一起去纽约即将举行的摇滚音乐节。在一次出海的时候，桑迪救了一只险些被猎杀的海豚。\r 　　枯燥的生活和海边猎杀者的残忍让桑迪更坚定了离开这里的决心，在一个飓风的晚上，桑迪偷偷离开了海边，却险些发生意外。还好波特赶来，他才幸免于难，但是海边的房子已经狼籍一片。经历这次事故，波特和桑迪之间定下君子协议，桑迪帮舅舅把房子修好，不许私自溜走，波特满足他去纽约看演唱会的要求，桑迪欣然同意。被桑迪救过的那只海豚对恩人念念不忘，时常来海边光顾。而桑迪也对这只可爱聪明的小动物充满了好感，二人成为了非常要好的朋友，并为海豚取名为费力佩。\r 　　由于海豚的缘故，桑迪认识了同样喜欢海豚的女孩金。为了让费力佩有更多的鱼吃，桑迪在废旧的钓鱼场和好友上演了一出精彩的海豚游戏节目，吸引了不少孩子来看，而唯一的要求就是每个人必须要为海豚带一条鱼来。这一举动引起了警察局的注意，因为有规定不经允许是不可以圈养海豚的。但费力佩显然已经习惯了被喂养的生活，对于桑迪他总是恋恋不舍。\r 　　受到政府和警察局的压力，波特和桑迪不得不把费力佩送到大海深处，重新开始适应没有海豚好友陪伴的生活。就当桑迪开始思念他的海豚好友时，费力佩回来了，但是这一次它濒临死亡。波特、金、桑迪都在为救活费力佩而努力着，但是在这一过程中，他们发现了一个惊人的秘密——费力佩是因为中毒才濒临死亡的。究竟是谁投毒？桑迪决心展开调查，并最终将罪魁祸首绳之于法。','This summer it\'s finally safe to go back in the water.',25530000,20080020,4.475007,5.3,84,95,'1996-05-17','en','/c3KEzecZ5oE6CpSrWX6wCLrBJbf.jpg',2.783508136775941,3,'2026-09-10',2,NULL,NULL),(36419,'身后事','After.Life','安娜（克里斯蒂娜•里奇 Christina Ricci 饰）是一次车祸的幸存者，然而她惊讶的发现自己已经被判定了死亡。证据是她的葬礼已经在准备中，负责人正是葬礼主管艾略特（连姆•尼森 Liam Neeson 饰）。\r 安娜对此既不解又恐惧。因为她很清楚，葬礼的终点就是入棺活埋。她对艾略特现身，希望后者坚持自己还活着的真相。两个人在封闭的停尸间进行着辩论，艾略特坚持履行自己的职责，并对安娜解释她到“来世”的种种缘由。而安娜面对不见底的黑暗，内心无比悲凉。然而，艾略特并不认同安娜的说法。他坚持自己是因为通灵才能辨识安娜的游魂。\r 只有一个人还坚信安娜活着，那就是她的男友保罗（贾斯汀•朗 Justin Long 饰）。他并不认同艾略特的说法，坚持调查安娜的死因，慢慢地，他接近了真相……','Life is the symptom. Death is the cure.',4500000,3606395,14.570359,5.4,251,104,'2010-04-09','en','/iIBXtNCGSFpafjeDOJhvS2m63nH.jpg',3.0129779103643837,3,'2026-09-10',2,NULL,NULL),(36549,'Yesterday Was a Lie','Yesterday Was a Lie','Hoyle a girl with a sharp mind and a weakness for bourbon -- finds herself on the trail of a reclusive genius. But her work takes a series of unforeseen twists as events around her grow increasingly fragmented... disconnected... surreal. With an ethereal lounge singer and her loyal partner as her only allies, Hoyle is plunged into a dark world of intrigue and earth-shattering cosmological secrets. Haunted by an ever-present shadow whom she is destined to face, Hoyle discovers that the most powerful force in the universe -- the power to bend reality, the power to know the truth -- lies within the depths of the human heart.',NULL,0,0,0.145014,6,4,89,'2008-01-01','en','/dJtY4pXjfnyKaYO1pP4C0u2XsQp.jpg',2.1834141332760124,3,'2026-09-10',2,NULL,NULL),(36557,'007：大战皇家赌场','Casino Royale','Le Chiffre, a banker to the world\'s terrorists, is scheduled to participate in a high-stakes poker game in Montenegro, where he intends to use his winnings to establish his financial grip on the terrorist market. M sends Bond – on his maiden mission as a 00 Agent – to attend this game and prevent Le Chiffre from winning. With the help of Vesper Lynd and Felix Leiter, Bond enters the most important poker game in his already dangerous career.','Everyone has a past. Every legend has a beginning.',150000000,599045960,88.935165,7.3,3855,144,'2006-11-14','en','/lMrxYKKhd4lqRzwUHAy5gcx9PSO.jpg',4.129601369478043,3,'2026-09-10',2,NULL,NULL),(36584,'Interview with the Assassin','Interview with the Assassin','Out of work TV cameraman Ron Kobelski is approached by his formerly reclusive neighbor Walter Ohlinger. Ohlinger claims that he was the mysterious \"second gunman\" that shot and killed President Kennedy. Ohlinger has kept quiet all these years, but has decided to tell his story now that he has been diagnosed with terminal cancer. Kobelski is skeptical of his neighbor\'s story, after his investigations provide ambiguous answers. His attitude changes, however, after he receives threatening messages on his answering machine, and spots shadowy figures in his backyard. Is Ohlinger telling the truth? Or is there a bigger conspiracy at work?','Dallas. 1963. The second shooter.',500000,0,0.471264,5.6,5,88,'2002-05-09','en','/yCEP43DIYqx8NM9ttcmgSnxScRI.jpg',2.222886092696459,3,'2026-09-10',2,NULL,NULL),(36586,'刀锋战士2','Blade II','在这个纷扰复杂的世界上，灾难总是从最隐蔽的角落里出现，正义与邪恶的战争也永远会在不知名的地方继续着。 　　新世纪到来没多久，一种不知名的新病毒便意外诞生了。被这种可怕的病毒感染后，无论是人类或是吸血鬼，都会演变为令人发指的吸血变种——“收割者（Reapers）”。收割者有着永无止境的嗜血欲望，因此他们较之吸血鬼更加残忍恐怖。更为骇人的是“收割者”口器会张开里面有吸血触手，一经触碰人类，就能吸干人血！ 　　为了对抗这种可怕的怪物，保护人类的未来，刀锋战士也需要寻求必要的协助。在与吸血鬼长老会达成停战协议后，刀锋战士与吸血鬼组织Bloodpack结成联盟，准备一道对抗共同的敌人——收割者！ 　　在新伙伴斯库德的帮助下，刀锋战士为了拯救自己好友惠斯特，杀向了收割者的老巢。收割者背后有一场巨大的阴谋。至此，一场腥风“血”雨是免不了的，只怕观众届时还须多带把雨伞，以免溅得自己一身血。','Faster. Sharper. Deadlier.',54000000,155010032,67.169587,6.2,1528,117,'2002-03-22','en','/a5YLMkupOXgb2KeCwF50JQiH0tA.jpg',3.597168616219772,3,'2026-09-10',2,NULL,NULL),(36593,'The Naked Gun 33⅓: The Final Insult','The Naked Gun 33⅓: The Final Insult','白头翁莱斯利·尼尔森主演的第三部无厘头警探喜剧。他在本片中已荣退回家当家庭主夫，无须与妻子闹意见。另一方面恐怖分子在狱中计划炸弹事宜，警方束手无策，要求法兰克重出江湖。他假扮犯人入狱，取得恐怖分子的信任一齐逃狱，终于误打误撞解决危机。','A Mad Bomber is on the Loose, and If Anyone Can Stop Him....So Can Frank!',30000000,51132598,28.624038,6.3,521,83,'1994-03-18','en','/uJU3ibFSphc8fDO3q2hqAUUDM24.jpg',3.2814427566948123,3,'2026-09-10',2,NULL,NULL),(36597,'Wuthering Heights','Wuthering Heights','Foundling Heathcliff is raised by the wealthy Earnshaws in Yorkshire but in later life launches a vendetta against the family.',NULL,0,0,4.409263,6.9,37,142,'2009-01-18','en',NULL,2.645164288367766,3,'2026-09-10',2,NULL,NULL),(36643,'The World Is Not Enough','The World Is Not Enough','Greed, revenge, world dominance and high-tech terrorism – it\'s all in a day\'s work for Bond, who\'s on a mission to a protect beautiful oil heiress from a notorious terrorist. In a race against time that culminates in a dramatic submarine showdown, Bond works to defuse the international power struggle that has the world\'s oil supply hanging in the balance.','As the countdown begins for the new millennium there is still one number you can always count on.',135000000,361832400,39.604363,6,862,128,'1999-11-08','en','/qtJsbZ9vISsI9nZzqreXolAKJpz.jpg',3.373942170635963,3,'2026-09-10',2,NULL,NULL),(36647,'刀锋战士','Blade','刀锋战士自小就被专门打造新式武器的吸血鬼猎人惠斯特（克里斯多佛森饰）收养，专门出入有吸血鬼出没的场所，拯救即将被消灭吞噬的人类，凭着他驾骑着银翼机车，手持无敌火力的巨型火焰枪，以及无敌旋风刀和身后背负着的那把长剑，不死的无敌战神刀锋战士所向披靡，只要他一出现，躲藏在人群当中的吸血鬼将无所遁形。 　　于是，在这个未来的世界中，刀锋战士成了人类和吸血鬼双方争夺生存空间下最勇猛的正义战士，也因此，吸血鬼领袖佛斯特（史蒂芬德尔饰）处心积虑要除去这心头大患，以完成他一统天下的大梦，他先利用刀锋战士的心理弱点给他致命的攻击，原来，刀锋出身时被吸血鬼血液浸满子宫，也成了半个吸血鬼，必须随时克制着自己对血的渴望。 　　佛特斯先是邀请刀锋战士加入邪恶势力的一方，只要他们两方联手，相信没有人可以逃过他们的力量，然而刀锋战士作为献祭品以请出血王，增强自己的力量。在正邪双方的互斗之下，究竟谁才能获得最后的胜利。','Part Man. Part Vampire. All Hero.',45000000,131183530,43.815492,6.5,1905,120,'1998-08-21','en','/8tq6NV2izXRjegQUpur6OMrmFUl.jpg',3.657997823164836,3,'2026-09-10',2,NULL,NULL),(36648,'刀锋战士3','Blade: Trinity','这个世界上总是有两种势力，一方是邪恶的黑暗势力，而另一方则是永远和黑暗势力相抗争的正义的力量。黑暗势力似乎一刻都不会安宁，他们总是不甘心一直“黑暗”下去。在遥远的沙漠深处，吸血鬼的首领唤醒了沉睡七千年的吸血鬼德雷克(多米尼克·珀塞尔饰)，这位古老的吸血鬼家族的祖先因为纯正的血统而拥有吸血鬼后辈永远无法企及的超强法力，那就是阳光无法阻挡他的黑暗力量，对于其他吸血鬼来说是致命的阳光对他却没有任何的影响，他在白天还能自由行动。吸血鬼们将他唤醒的目的是希望通过对他基因的研究，找出吸血鬼对抗日光的秘密。','The final hunt begins.',65000000,128905366,49.660055,5.7,1252,123,'2004-12-08','en','/bB51NIR4SfIIUvdT4Yq1Wt7V1nk.jpg',3.417937790040654,3,'2026-09-10',2,NULL,NULL),(36657,'X战警','X-Men','镭射眼、琴·葛蕾、暴风女是X战警的核心人物。而X战警队伍来了一位危险人物——金刚狼，他是个脾气暴躁，几乎不受控制的变种人，使X战警内部危机四伏。更糟的是，又来了一个反派人物“万磁王”，它能控制地球磁场和金属。 而且还憎恨人类，认为变种人比人类更优秀，应该主宰人类。而誓死保卫人类的X战警，将会发现他们在尽力保卫人类之时，人类也对他们也产生了极大的恐惧，双方关系渐渐紧绷。X战警必须面对金刚狼的脾气暴躁与万磁王的到处杀戮，X战警陷入了进退两难的重重危机中。','Evolution Begins',75000000,296339527,4.66891,6.8,4097,104,'2000-07-13','en','/bRDAc4GogyS9ci3ow7UnInOcriN.jpg',3.8258207842153595,3,'2026-09-10',2,NULL,NULL),(36658,'X2','X2','Professor Charles Xavier and his team of genetically gifted superheroes face a rising tide of anti-mutant sentiment led by Col. William Stryker. Storm, Wolverine and Jean Grey must join their usual nemeses –  Magneto and Mystique – to unhinge Stryker\'s scheme to exterminate all mutants.','The time has come for those who are different to stand united.',110000000,407711549,2.871739,6.8,3506,133,'2003-04-24','en','/bst4alFUXCxISwdRUKSMhhkrX1M.jpg',3.783552793422367,3,'2026-09-10',2,NULL,NULL),(36668,'X战警3：背水一战','X-Men: The Last Stand','琴的死亡在X战警中造成了持续的影响，斯科特和罗根恍然若失。学院的教学任务落在了暴风女和金刚狼等人的肩上，变种人在这里才能得到身份的认同。某公司从一名变种人儿童的基因中提取出了还原变异的X基因的“解药”，可以令变种人的身体与常人无异，“解药”的问世在变种人中引起了强烈反响，万磁王四处联系不愿改变体质的变种人，试图用暴力反抗人类社会的不公平待遇。金刚狼等人发现琴并未死去，而且她被唤醒的第二重人格拥有极为强大的力量，X教授和万磁王各自争取琴，她成为了改变变种人世界的关键人物。','Take a Stand',210000000,459359555,3.857526,6.3,3525,104,'2006-05-24','en','/xSLQmlEchtkSqY0NC0uACfsytrn.jpg',3.6628248338184126,3,'2026-09-10',2,NULL,NULL),(36669,'007：择日而亡','Die Another Day','007（皮尔斯·布鲁斯南 Pierce Brosnan 饰）这次在北朝鲜发现了一位世界级的媒体大亨——盖斯特维的阴谋诡计。盖斯特维妄图研制一枚类似于第二颗太阳那样的卫星来挑起全球战争，进而达到他控制地球的企图。007当然不会允许盖斯特维的阴谋得逞，于是在北朝鲜展开了调查。经过调查，007发现盖斯特维的真实身份，那是经过整容后改头换面的原北朝鲜领导人Zao。现在，007必须抓紧时间找到Zao，制止他的阴谋以阻止战争的全面爆发。本片是皮尔斯·布鲁斯南的最后一部007作品。','He’s never been cooler.',140000000,431971116,54.159392,5.8,1092,133,'2002-11-17','en','/b63hw5cUm3dBvEy8oowf0kg6fO.jpg',3.420547047011758,3,'2026-09-10',2,NULL,NULL),(36670,'007：巡弋飞弹','Never Say Never Again','007（肖恩·康纳利 Sean Connery 饰）屡立战功，这次，他运用一系列新奇而惊人的武器，竟然单枪匹马就除掉了敌人的一支军队。由于007的出色表现，他获得难得的一个长假期。然而正在此时，魔鬼党却将军队的两枚重要的飞弹偷走，英国情报部无奈之下只好将正在泡温泉的007召了回来。经过调查，007发现这次计划的幕后首脑是狂人拉尔果（克劳斯·马利亚·布朗道尔 Klaus Maria Brandauer 饰），他正在准备世界核能勒索计划，而且，拉尔果还得到了最危险的女杀手法蒂玛和魔鬼党首脑布罗非的帮助。这次对007的考验异常严峻！（007外传之巡弋飞弹）','Sean Connery is James Bond 007',36000000,160000000,23.380757,5.8,338,134,'1983-10-07','en','/oVt0auTo59HsvGSglNvNA9gXrzi.jpg',3.1225646065186643,3,'2026-09-10',2,NULL,NULL),(36691,'孤独的人','Solitary Man','迈克尔·道格拉斯扮演一个富得冒油的汽车电影下载商，但是由于其卓绝的个性一直消耗着他的控制力，使得这个呼风唤雨的有钱人，最终落得个事业家庭全部崩盘的下场。  让我们一起走进曼哈顿的上东区，那里因为聚集了金融、投资银行的富豪们而被称为 “富人的天堂”……整个故事都是围绕着一个名叫本·卡尔曼（迈克尔·道格拉斯饰）的50多岁的纽约人展开的，他之前曾经是一位非常成功的汽车经销商，却因为经历了一系列糟糕的抉择和动荡之后，失去了他辛苦奋斗所得来的一切，也使得他的事业根基全部付之东流。在经过了潜心地休整，本已经下定决心从头来过，凭借着努力和与生俱来的商业天分，找回那个曾经无限风光的自己。但是，出于某些同样的因素和动机，汇聚成了强大的反作用力，直接威胁到了本所实施的过度以及转变，很可能让他再一次受到沉重的经济打击，就此一蹶不振，再也无法翻身。  本已经与大学时代就在一起、同时也是最了解他、知道他拥有着别人无法企及的才能的爱人南茜（苏珊·萨兰登饰）离婚了，虽然他仍然可以找时间和他们的女儿苏珊（珍娜·费舍饰）以及可爱的外孙聚聚，可是自从南茜知道本正在与自己的一个好朋友约会之后，就彻底地切断了两个人之间的联系，再也不肯露面了。本现在的女朋友乔丹（玛丽·露易斯·帕克饰）的父亲是一位非常有影响力的商人，经营着一家实力雄厚的汽车制造厂，如果本可以将自己的傲慢与狂妄暂时隐藏起来，他就有可能得到生命中最强大、最有力的支持和帮助。然而他周遭的环境却在不断地逼迫他接近一个他不应该接触的女孩，同时也让他再一次置身在了危险的境地当中。','Ben loves his family almost as much as he loves himself',15000000,5024782,7.497306,5.8,84,90,'2009-09-07','en','/5Dpm8QDoL3w3ZOwVl6rgvjRWxrj.jpg',2.805920683698703,3,'2026-09-10',2,NULL,NULL),(36696,'松鼠和箭-星狗','Белка и Стрелка. Звёздные собаки','Belka, the amazing flying dog is unexpectedly hurdled into the streets of Moscow when the rocket she is in malfunctions during one of her circus routines. Fortunately the crash leads her to meet a streetwise dog named Strelka and her irredeemable rat friend Venya. Together with other amusing friends found along the way, the three find themselves in a space program-training center where they get sent away in a rocket, leaving planet Earth...',NULL,25000000,6500000,5.753564,6.3,10,85,'2010-03-18','ru',NULL,2.368382312603225,3,'2026-09-10',2,NULL,NULL),(36739,'黑色学府','School Daze','返校节周末，在一所历史悠久的黑人大学，兄弟会和姐妹会成员与其他学生发生冲突。',NULL,0,0,3.159574,6.2,26,121,'1988-02-12','en','/vnfjKHcmah7ReMxLNF18JMXFgSZ.jpg',2.557584896111767,3,'2026-09-10',2,NULL,NULL),(36811,'红尘极路','The Last Station','年轻的瓦伦汀（詹姆斯·麦卡沃伊 James McAvoy 饰）应聘成为大文豪列夫·托尔斯泰（克里斯托弗·普卢默 Christopher Plummer 饰）的秘书和助手，目睹了晚年文豪和他妻子索菲娅（海伦·米伦 Helen Mirren 饰）之间爱恨交织的深刻情感。托尔斯泰不满索菲娅奢侈的生活习惯，索菲娅则看不惯托尔斯泰和“激进派”弟子弗拉基米尔·切科夫（保罗·吉亚玛提 Paul Giamatti 饰）的合作，围绕着托尔斯泰，两度力量始终较劲，瓦伦汀也被牵扯进去，分别为索菲娅和切科夫写日记，记录托翁晚年生活，同时也和托翁崇拜者玛莎（凯瑞·康顿 Kerry Condon 饰）产生了感情。疲惫的托尔斯泰终于选择离家出走，弥留在最后的车站，而索菲娅和切科夫的斗争直到最后一刻都未止息……','Intoxicating. Infuriating. Impossible. Love.',0,0,3.659292,6.7,55,112,'2009-09-04','en','/nf9cYwKcvxTbSsCz4o6eRJ8P0IH.jpg',2.728606135360606,3,'2026-09-10',2,NULL,NULL),(36819,'时光大盗','Time Bandits','男童凯文的一家和其他普通家庭一样，在忙碌快速的现代生活中周转不停，然而某个夜里，六个由衣柜闯出来的矮人打破了凯文平静的生活，他们自称是上帝的雇工，窃取了上帝的地图可以让他们在不同的时空游走。凯文由此进入了超出想象的奇妙生活。一行人先后降临拿破仑的战场，加入了罗宾汉的队伍，矮人们瞅准任何机会偷窃不停。与此同时，黑暗城堡中的邪恶之神醉心高科技，妄图通过科技的力量取代上帝统治，他施法将凯文与矮人们分开。坠落古希腊的凯文不经意间救得英雄阿伽门农国王（肖恩·康纳利 Sean Connery 饰）的性命，感恩的英雄将凯文立为继承人，这时矮人们却匆匆赶来将凯文一步步带入了邪恶之神的陷阱……','All the dreams you\'ve ever had and not just the good ones.',5000000,42365581,14.779537,6.6,249,116,'1981-07-13','en','/8Q3IfCCnLUDnzEcY1bTqG8puYAk.jpg',3.1037606397342485,3,'2026-09-10',2,NULL,NULL),(36825,'The R.M.','The R.M.','Jared Phelps (Kirby Heyborne) has completed two years of full-time missionary service for The Church of Jesus Christ of Latter-day Saints. His mission president has promised him that he will be blessed for his service, and he thinks he has it all worked out. His girlfriend has waited for him. His boss promised that he could have his old job back, and he has already sent his application to BYU. Everything that can go wrong does go wrong. His girlfriend dumps him. His loses his job, and he isn\'t accepted to BYU. Then, it gets even worse, and he has to decide if choosing the right is worth all the trouble.','Just when you thought it was safe to go back into the world...',0,0,0.082978,4.8,4,101,'2003-01-31','en','/OQ3X7k13koP833iZx1PRIPngZ8.jpg',2.1813063736669553,3,'2026-09-10',2,NULL,NULL),(36955,'真实的谎言','True Lies','哈里（阿诺·施瓦辛格 Arnold Schwarzenegger 饰）是美国FBI的高级特工，他正在奉命调查一起跨国核武器走私案件。出于安全考虑，哈里连结婚15年的妻子海伦（杰米·李·柯蒂斯 Jamie Lee Curtis 饰）都没有告诉他的真实身份。海伦是一名普通白领，平凡的生活已令她心生厌倦。一次，汽车商西蒙假扮FBI特工，溜到海伦家谎称自己被人追杀。紧张刺激的经历很快令海伦着迷。这一切都没有逃过真正的FBI特工哈里眼睛。哈里利用间谍侦查手段令到西蒙洋相百出，并化妆成法国人正欲调戏海伦时，被恐怖分子突然袭击，两人被挟持到一个热带小岛。哈里和海伦最终能否逃出生天，挫败恐怖分子阴谋？','When he said I do, he never said what he did.',115000000,378882411,38.729418,6.8,1116,141,'1994-07-14','en','/mfrGFyRYn8dyXP4RSseR1EtHrCr.jpg',3.571049615143464,3,'2026-09-10',2,NULL,NULL),(36970,'海洋','Oceans','《海洋》耗时五年，耗资5000万欧元，动用12个摄制组、70艘船，在全球50个拍摄地，有超过100个物种被拍摄，超过500小时的海底世界及海洋相关素材，是史上投资最大的纪录片。 海洋是什么？这部电影告诉你答案。这是一部令人心旷神怡、叹为观止的生态学纪录片。本片聚焦于覆盖着地球表面的四分之三的“蓝色领土”。导演深入探索这个幽深而富饶的神秘世界、完整地呈现海洋的壮美辽阔。真实的动物世界的冒险远比动画片中的故事来的精彩，接下来银幕展开——巨大的水母群、露脊鲸、大白鲨、企鹅等。毫不吝啬在镜头前展示他们旺盛的生命力，让人叹为观止。','Explore the depths of our planet\'s oceans.  Experience the stories that connect their world to ours.',0,19406406,10.706613,7.3,111,84,'2009-10-17','en','/AoC9dqAYZYV3p8llAURsuEDLZ5Z.jpg',2.9299509629712377,3,'2026-09-10',2,NULL,NULL),(37003,'U2 3D','U2 3D','本片将这支世界顶级乐队的系列现场演唱会，转化为一种全新的娱乐体验，带领观众踏上一场非凡的银幕之旅，实现了对传统演唱会电影及传统3D技术的质的飞跃。该片在2007年戛纳电影节期间以制作中作品亮相，便征服了全球观众。[National Geographic Cinema Ventures]','Hear See Experience',15000000,22730842,0.335195,6.7,10,85,'2007-05-19','en','/5OT1s7NOpnJ5IVlpe5hGC7dYGoK.jpg',2.357630760139133,3,'2026-09-10',2,NULL,NULL),(37028,'魔笛','The Magic Flute','剧情：',NULL,0,0,0.548435,6.9,6,133,'2006-09-07','en','/qjUjatQEMIHtCngnyTib943x7TU.jpg',2.2595139414407988,3,'2026-09-10',2,NULL,NULL),(37056,'给朱丽叶的信','Letters to Juliet','苏菲·霍尔（阿曼达·塞弗里德 Amanda Seyf 饰）是《纽约客》的调查员。她的未婚夫维克多为开餐馆忙碌着。他们来意大利的维罗纳旅行。不过，维克多却醉心于品尝美食，对她疏于照顾。两人感情因此矛盾丛生。苏菲闲逛到许愿墙下，发现很多人给朱丽叶写信。她很好奇，尾随取信的 妇女，发现有四位女士扮演朱丽叶，回信解答情感问题。苏菲被感动了，决定加入她们的队伍。她读到一封50年前的来信：克莱尔·史密斯（瓦妮莎·雷德格瑞夫 Vanessa Redgrave 饰）讲述了一段留有遗憾的当年情。苏菲用心地回了信。没想到，某天，老人的孙子查理（克里斯·艾根 Chris Egan 饰）找上门来。她这才了解，老人读了她的信，决定重拾真爱。但查理觉得这很荒谬。在争执中，三个人共同踏上了寻爱之旅……','What if you had a second chance to find true love?',30000000,0,16.52083,6.6,796,105,'2010-05-14','en','/20Y66WKtpbNBk7QfyDdmVk6XDn6.jpg',3.398597691836984,3,'2026-09-10',2,NULL,NULL),(37080,'母与子','Mother and Child','凯瑞安（安妮特·贝宁 Annette Bening 饰）年仅十四岁就怀孕生子，之后，年少无知的她放弃了孩子的抚养权，一晃眼三十多年过去，当初的那个小小婴孩在凯瑞安的心中分量却越来越重，她无时不刻不思念着她。伊莉莎白（娜奥米·沃茨 Naomi Watts 饰）漂亮性感，辗转在不同的男人之间，如鱼得水。向往自由的她从来没有想过会让孩子牵制住自己前进的脚步，因此早早就做了节育手术，然而，一场意外的到来让她陷入了两难的境地之中无法做出选择。露西（凯丽·华盛顿 Kerry Washington 饰）和丈夫结婚多年但一直都没有孩子，爱子心切的露西决定领养，但此事谈何容易。终于，露西等来了一个千载难逢的好机会，那么这一次，她能够如愿吗？一个孩子将三个身份和个性都截然不同的女人联系到了一起，在波折和悲伤之中，每个人发现了她们生命中最珍贵的所在…',NULL,7000000,0,5.517597,6.7,46,125,'2009-11-07','en','/k5CjH4scjbBlGWLdZyUS7NEZf16.jpg',2.692901652963306,3,'2026-09-10',2,NULL,NULL),(37137,'The Naked Gun 2½: The Smell of Fear','The Naked Gun 2½: The Smell of Fear','顶尖的科学家梅博士计画公开发表新报告，这份关于未来的新能源的研究，让传统能源供应商惊骇不已，为避免霸权被毁，一夥人挟持了梅博士。法兰追查案情过程中，意外与旧情人珍相遇，面对案情的越发纠葛，两人纠纠缠的恋情也越演越烈。','If you see only one movie this year...you ought to get out more often',23000000,86930411,27.33256,6.6,546,85,'1991-06-28','en','/bzWpy4y60j6KYApkJoVHH2k3cxx.jpg',3.3278525241457717,3,'2026-09-10',2,NULL,NULL),(37165,'楚门的世界','The Truman Show','楚门·伯班克过着看似平凡而安稳的生活，却总觉得身边有些事情不太对劲：曾经突然消失的初恋、早已溺水身亡却似乎再次出现的父亲，以及一次次阻止他离开家乡的意外。随着越来越多无法解释的异常发生，楚门开始怀疑自己熟悉的生活并不像表面那样真实，甚至感觉无论走到哪里都有人在注视着自己。为了找到失踪的初恋，也为了弄清隐藏在日常生活背后的真相，他决定不惜一切代价离开这个生活了三十多年的世界……','On the air. Unaware.',60000000,264118201,56.488027,7.8,4537,103,'1998-06-04','en','/vuza0WqY239yBXOadKlGwJsZJFE.jpg',4.2274308380770105,3,'2026-09-10',2,NULL,NULL),(37206,'A Shine of Rainbows','A Shine of Rainbows','An orphaned boy named Tomás is adopted by Maire O’Donnell to live on a whimsical Irish isle filled with new friends, secret caves and a lost baby pup seal stranded on the coast. But when Maire\'s reluctant husband Alec refuses to accept Tomás as his own son, the boy drifts down a fateful path of adventure and self-discovery, illuminating how rainbows can shine around - and within - us all.','An abandoned child brings the colors of love into their lives.',6000000,0,12.099486,6.3,14,101,'2009-10-01','en','/9FWxI20tzm9LuP3KT9cbmp5YN6Q.jpg',2.4505257166756116,3,'2026-09-10',2,NULL,NULL),(37232,'旅行者与魔法师','ཆང་ཧུབ་ཐེངས་གཅིག་གི་འཁྲུལ་སྣང','不丹村官敦杜（Tsewang Dandup 饰）很快厌倦了乡村乏味的生活，怀念大城市的绚烂，并计划借朋友的关系前往梦想之地——美国。敦杜在帕罗节（不丹最大的宗教节日）期间请假，不声不响的包好行李，踏上了前往美国的旅程。在乡村公路旁，敦杜邂逅一位僧人，后者为他讲述了一个梦想之地的故事：不丹青年塔西荒废了自己法术的学业，整日心中只是思量女人，这天他骑上了新买的马，却被马儿丢弃在森林深处，塔西向林中的隐居老人求助，并被他年轻貌美的妻子吸引，遂滞留此处。不久塔西和老人的对立愈发明显……在故事之外，敦杜和僧人的旅程中加入了一位少女，这使敦杜的看法发生了些许变化……','The bitter and the sweet of temporary things.',0,0,0.749699,6.8,9,108,'2003-09-09','en',NULL,2.338011636901639,3,'2026-09-10',2,NULL,NULL),(37233,'糖衣陷阱','The Firm','一位刚自长春藤联盟大学毕业的法学院学生，受雇于纽约一家律师务所，即获得公司许多优厚的待遇，还帮他偿助学贷款，租给他一辆宾士骄车代步，然而天下没有白吃的午餐，不久他就发现，如此的厚遇却招来FBI的调查……。 　　米奇刚自哈佛法学院毕业，对未来充满理想，富正义感，有人情味，与爱妻碧只想过有计划的婚姻生活。旦米奇似乎时来运转，受“班?蓝?罗律师务所”高薪礼聘，在顾问艾弗瑞指导下，认真展开业务。 　　米奇踏入豪门企业之后，渐渐发现许多异象，起先察觉该事务所有四位生代律师莫名死亡，而后又在一次案件中发现客户竟是黑道大亨卡桑尼，且当夜被人设下美人计，留下不利的证据。 　　尽管米奇一切都依法行事，但却依然受到重重阻碍。只好求助于狱中之兄雷所推介之好友-罗艾迪展开调查，却即遭人暗杀，此举不但使米奇为之警惕，同时也引来司法部的调查。 　　米奇察觉自己命在旦夕，若与律师事务所合作，将导致身败名裂，甚至死无葬身之地；若与司法部配合，势必招来杀身之祸，若和黑道挂钩更是死无了期，在多番挣札之后，决定先设法救出雷，在妻子与秘书暗中协助搜证下，面对三方面威胁，毅然向黑色豪门企业宣战.....','Power can be murder to resist.',42000000,270248367,23.736535,6.6,501,154,'1993-06-30','en','/cGLBJPVIgQ3mn5aAbpJbhqmdoCv.jpg',3.297937685703379,3,'2026-09-10',2,NULL,NULL),(37414,'心中的杀手','The Killer Inside Me','美国德克萨斯州一座小镇的警官卢·福特（卡西·阿弗莱克 饰）的生活显得无趣而单调，他显得平凡而木讷，但是他渐渐却发掘着内心的罪恶，并愈发在分裂的人格中不能自拔。尽管有固定女友艾米·斯坦顿（凯特·哈德森 饰），但是他仍然更享受与妓女乔伊斯·莱克兰（杰西·阿尔芭 饰）间充满刺激与暴力的关系，渐渐的他终于成为残忍的凶手，并嫁祸于人。当他以为成功转移他人注意力时，更多证据却渐渐将嫌疑的对象指向了他，他不得不开始新的凶杀以便逃脱惩罚，并因此在不归之路上越走越远。','Nobody See\'s It Coming',13000000,0,11.892615,6,173,109,'2010-02-19','en','/fhmdzywgGF9cvoLPuW8qqDn0Gtx.jpg',2.9747386613592823,3,'2026-09-10',2,NULL,NULL),(37495,'四头狮子','Four Lions','------在英国北部的一座城市，四名男子正在制定一个秘密计划。奥马尔已经对穆斯林在这个世界上得到正确的认识和对待不抱幻想，并决心要成为一名圣战战士。这在他的朋友瓦伊看来，这是世上最令人兴奋的想法了，于是，他们专程前往巴基斯坦恐怖分子训练营受训。同时，信仰伊斯兰教的白人巴里，与他的同伴费萨尔一道，尝试着训练乌鸦携带炸弹，为了充实队伍，巴里又招募了第五名恐怖分子哈桑。一天，意外发生了，费舍尔在一次训练中炸死了自己，而剩下的四人继续着他们心中荣耀的事业，将目标对准了即将开始的伦敦马拉松赛...','We are 4 Lions.',967686,4270000,20.544999,7,423,101,'2010-05-07','en','/x4JzaRPXBs9wiHCe3e3ymXWuwfd.jpg',3.2921942733006504,3,'2026-09-10',2,NULL,NULL),(37498,'K.O.雷霆一击','Knock Off','这是一部典型的美国英雄主义电影。香港回归前夕，国际恐怖组织和香港的造假巨头准备抢在回归前完成一项走私活动――将一批香港生产的内藏微型炸弹的假冒名牌V6牛仔裤偷运到美国。幸好美国中情局及早察觉了恐怖分子的计划，于是先后派出了特工哈利（保罗•索尔维诺 Paul Sorvino 饰）、汤米（罗伯•施奈德 Rob Schneider 饰）和凯伦（莱拉•罗尚 Lela Rochon 饰）前往香港调查。','There is no substitute.',33000000,0,2.706207,4.7,64,91,'1998-09-04','en','/hK7hKDA51FCbtFCuXZNiQ6gPq3S.jpg',2.7121941305650568,3,'2026-09-10',2,NULL,NULL),(37532,'啪','Slam','Slam，大致可以翻译成“诗喃”，对大多数人来说或许是一个陌生的名词。这是一场艺术运动，起源于1986年，美国诗人Marc Smith希望能让诗从精英主义的高阁走下来，让诗歌的阅读更普及并且更加有趣，诗喃由此诞生。诗喃创作者不需要考虑统一的格律，只需要根据自己对生活的观察和感悟用他们喜欢的文字和风格表达出来，这一种超越，让诗喃本身承载着自由、开放、平等、分享的意味。\r 如何进入这个自由狂放又诗意的世界？导演Marc Levin在《Slam》这部作品中，从黑人街头文化、帮派文化、说唱文化（注：诗喃不是说唱，而是比说唱更自由的形式），进行切入，讲述了一个通过自我思考和自由表达，最终达至自我发现、自我救赎的故事。通过镜头，我们将与男主人公一起，走过黑人街区、监狱、城市街头、诗喃大会，在命运面前求索，一步步走近生活与内心的真实，并以此为源，化为蓬勃而真挚的诗喃。\r 诗喃的表演形式非常纯粹，没有服饰、没有布景、没有音乐，整个过程仅靠诗喃者的声音与肢体语言进行表达。舞台、诗喃者、观众三个元素即构成了这个简单、自由、原生的场域，乃至于，当诗喃的精神深入骨髓，连日常的对话，都可以化律动的诗喃，绽放出语言美妙的流动性。而随着影片的深入，相信你会在最后的演绎中，感受到诗喃者的自我挖掘诚挚脆弱如赤裸婴儿，诗喃者的情感澎湃汹涌野生如荒岛巨浪。那是简单如一、一即是全的彻底的生命表达。','Words make sense of a world that won\'t.',1,0,0.29245,6.7,7,100,'1998-10-07','en','/qU0QR2ax1hyjfACni4Clgsc5YyX.jpg',2.2876726730360994,3,'2026-09-10',2,NULL,NULL),(37686,'超级8','Super 8','时间是1979年，美国俄亥俄州一个平凡小镇。少年乔·兰布（乔尔·科特尼 Joel Courtney 饰）痛失母亲，生死悲痛让他久久地沉默。数月后，他应好朋友查尔斯（雷利·格里芬斯 Riley Griffiths 饰）的邀请，决定约上几个朋友一起用超8摄像机（8 mm）拍摄一部恐怖电影。当然令他下定决心的，是那个令她心仪的美丽女孩爱丽丝（艾丽·范宁 Elle Fanning 饰）也参与其中。在某个夜晚，爱丽丝驾驶父亲的汽车载着伙伴们来到火车站拍戏，谁知却目睹了一场极其惨烈的火车事故。这起事故还只是一系列不寻常事件的开始，小镇上的人们相继离奇失踪，各种奇怪的事件也接连发生。少年们的摄像机记录关于这一切的秘密……','It Arrives.',50000000,260095987,37.069253,6.6,2435,112,'2011-06-08','en','/pUWIjaMMYJjeBm5bJyE3mIXdQ62.jpg',3.7243431689568487,3,'2026-09-10',2,NULL,NULL),(37694,'Proud','Proud','The true story of the only African-American crew to take a Navy warship into combat in World War II.','Proudly We Served',0,0,0.023681,5.5,3,87,'2004-07-02','en','/2DvxkWSNjAWot5RdcM2K2TpKe1Y.jpg',2.134112679970254,3,'2026-09-10',2,NULL,NULL),(37707,'人工进化','Splice','在大公司纽斯特德的支持下，生物科学家克里夫·尼科利（阿德里安·布洛迪 Adrien Brody 饰）和女友艾尔莎·卡斯特（萨拉·波莉 Sarah Polley 饰）进行基因重组的实验，并取得初步进展。然而由于资金和公众舆论等原因，纽斯特德高层决定中断对他们现有研究的支持。克里夫和艾尔莎不愿半途而废，于是偷偷展开实验。他们对基因进行优化重组，并混入了艾尔沙的一部分基因，终于孕育出一个相貌奇特的雌性怪物。　　秉着科学家的道德和良知，克里夫执意要杀死怪物，而艾尔莎则全力保护，视若己出，并将其命名为卓伦。卓伦以飞快的速度成长，最终变成一位拥有独特美感的女孩（Delphine Chanéac 饰）。在这一过程中，克里夫和艾尔莎越陷越深……','Science\'s newest miracle...is a mistake.',26000000,0,23.227877,5.5,671,104,'2009-10-06','en','/uT4aRoZiLTXTdZxzVIhTwamftdu.jpg',3.212403938202227,3,'2026-09-10',2,NULL,NULL),(37710,'The Tourist','The Tourist','American tourist Frank (Johnny Depp) meets mysterious British woman Elsie (Angelina Jolie) on the train to Venice. Romance seems to bud, but there\'s more to her than meets the eye. Remake of the 2005 French film \"Anthony Zimmer\", written and directed by Jérôme Salle.','It all started when he met a woman',100000000,278731369,41.426678,6,1699,103,'2010-12-08','en','/2XnN3cchYNhW6BfpDdkxMoMyf4u.jpg',3.519988661874793,3,'2026-09-10',2,NULL,NULL),(37718,'缪斯','The Muse','曾经荣获奥斯卡人道主义奖的大编剧史蒂文（艾伯特·布鲁克斯 Albert Brooks 饰），如今却沦为了无人问津的无名小卒，个中滋味，他只有自己默默咀嚼。在好友杰克（杰夫·布里吉斯 Jeff Bridges 饰）的引荐下，史蒂文结识了美丽性感的莎拉（莎朗·斯通 Sharon Stone 饰），杰克告诉史蒂文，当初正是由于莎拉这位“缪斯”的存在，他才取得现今如日中天的地位。','In Goddess we trust.',0,0,2.857936,5.3,31,97,'1999-08-27','en','/hmtvDW52V3EuFmbhTOLjaGMYCDx.jpg',2.5829342490353553,3,'2026-09-10',2,NULL,NULL),(37724,'007：大破天幕杀机','Skyfall','随着M的过往找上门来，邦德对她的忠诚面临考验。当军情六处遭遇袭击，007必须追踪并摧毁威胁，无论将付出多么个人的代价。[哥伦比亚影业]','Think on your sins.',200000000,1108561013,93.004993,6.9,7604,143,'2012-10-25','en','/d0IVecFQvsGdSbnMAHqiYsNYaJT.jpg',4.202340907085564,3,'2026-09-10',2,NULL,NULL),(37735,'绯闻计划','Easy A','女高中生奥利弗（艾玛·斯通饰）为帮助男性朋友布兰登（丹·伯德饰）消除因同性恋问题被人嘲弄的苦恼，策划了一出自己失身的绯闻。奥利弗却因此成名，很多男生慕名而来，希望她假意与他们约会一段时间，以便也跟着出名。渐渐地，奥利弗发现这成了一笔生意，她以她的名气带动着其他人的名气，不但自己变得越来越有名，更因此在经济上也获益匪浅。当然，同时树大招风的她，也招来了对她出名不满的对手玛丽安（阿曼达·拜恩斯　饰），玛丽安进一步散布对奥利弗不利的谣言，试图逼迫其离开学校。而奥利弗则决定利用对自己有利的绯闻展开反击，于是，两位女生开始了一场绯闻对绯闻的荒诞而有趣的“战斗”。','The rumour-filled totally false account of how I ruined my flawless reputation.',8000000,74952305,45.395839,6.7,2210,92,'2010-09-10','en','/v5f1qO6NJnxWgONgkYg21TW39DT.jpg',3.7423034446132735,3,'2026-09-10',2,NULL,NULL),(37737,'风筝','Kites','Jay（Hrithik Roshan 饰）做梦都想过上有钱人的生活，然而命运总是跟他开玩笑。在拉斯维加斯打拼的他在最潦倒的时候，甚至会和那些想拿到美国绿卡的女人假结婚，赚取一定的佣金。Jay 凭借自己出色的舞技赢得富家千金 Gina（Kangana Ranaut 饰）及其父亲 Bob 的赏识，本来自此便可以飞黄腾达……',NULL,0,0,4.807549,6,40,131,'2010-05-21','en','/lYJhUIsKtlke4gNNHkYZNppYlTZ.jpg',2.649397187852815,3,'2026-09-10',2,NULL,NULL),(37786,'欲望都市2','Sex and the City 2','凯瑞（萨拉·杰西卡·帕克 Sarah Jessica Parker 饰）和夏洛特（克里斯汀·戴维斯 Kristin Davis 饰）的两位同性好友，安东尼（马里奥·坎通 Mario Cantone 饰）与斯坦福（威利·加森 Willie Garson 饰）终于成婚，而凯瑞与“大先生”（克里斯·诺斯 Chris North 饰）婚后却不满生活日渐平淡，二人矛盾渐生。全职妈妈夏洛特日夜担心丈夫哈里（伊万·汉德勒 Evan Handler 饰）会与青春洋溢的爱尔兰保姆艾琳（爱丽丝·伊芙 Alice Eve 饰）出轨。律师米兰达（辛西娅·尼克松 Cynthia Nixon 饰）不满老板对女性的歧视，愤而辞职。就在此时，萨曼莎（金·凯特罗尔 Kim Cattrall 饰）应阿联酋酋长之邀，带领三人出游中东的阿布扎比。在香料集市上，凯瑞重逢多年前的旧爱艾登（约翰·考伯特 John Corbett 饰）。心猿意马的凯瑞盛装赴约，果然犯了不该犯下的错误……','Carrie on.',100000000,288347692,18.325897,5.4,426,146,'2010-05-26','en','/35P6BZ4AzUn1MFYjnN0OHdrBX1k.jpg',3.111967764517796,3,'2026-09-10',2,NULL,NULL),(37799,'社交网络','The Social Network','2003年秋夜，哈佛大学本科生兼编程天才马克·扎克伯格坐在电脑前，热烈地开始酝酿一个新创意。在一连串怒涛般的博客写作与程序编码中，这个始于宿舍房间的构想迅速演变为全球社交网络，掀起了一场通信革命。仅仅六年后，当这个平台拥有5亿好友时，马克·扎克伯格已成为史上最年轻的亿万富翁……但对这位创业者而言，成功却引向了个人与法律的双重困境。[哥伦比亚影业]','You don\'t get to 500 million friends without making a few enemies.',40000000,224920315,69.27822,7.1,3391,120,'2010-09-30','en','/n0ybibhJtQ5icDqTp8eRytcIHJx.jpg',4.0010934591901135,3,'2026-09-10',2,NULL,NULL),(37821,'整编特工','Killers','简 一家人乘飞机去法国尼斯旅行，途中父母谈起女儿的情事，令她很是不爽。在海滨宾馆的电梯间，简邂逅了身着泳装的帅哥斯宾塞，两人一见钟情。他们相约在酒吧共进晚餐，但是刚好简的父母路过。简为了躲避他们的目光，情急之下编造了一个关于父亲的丑事，并不断圆谎。但随着她和斯宾塞情感加温，她还是对他袒露了实情。而斯宾塞却隐瞒了自己是杀手的事实。本来，斯宾塞要金盆洗手，但是最后一个任务，竟然就是对付简的父亲，自己未来的岳父。这令斯宾塞左右为难。与此同时，在这对如胶似漆的恋人周围，突然冒出了很多杀手，其中有喝得酩酊大醉的酒鬼，身材惹火的性感女郎，甚至邻居社区的小夫妻，纷纷对他下手……','Perfect wife. Perfect target.',75000000,98159963,23.004607,5.7,772,100,'2010-06-04','en','/vEyTE39KfRRAE2fU5k3YrscwU6O.jpg',3.2667307872887794,3,'2026-09-10',2,NULL,NULL),(37834,'Knight and Day','Knight and Day','A fugitive couple goes on a glamorous and sometimes deadly adventure where nothing and no one – even themselves – are what they seem. Amid shifting alliances and unexpected betrayals, they race across the globe, with their survival ultimately hinging on the battle of truth vs. trust.','Every Hit Man Deserves a Second Shot!',117000000,261930431,44.906918,5.9,1547,109,'2010-06-15','en','/hAU5zyoMNi7Y1lqAuNr9Mn95Uou.jpg',3.4878802825266724,3,'2026-09-10',2,NULL,NULL),(37842,'疯草','Les Herbes folles','影片根据克里斯蒂安·加伊1996年的小说《意外》改编，这也是雷奈首次直接使用小说改编的剧本。影片讲述一个名叫玛格丽塔的女人从一家商食店走出来时被人抢走了皮包，她没有料到小偷会把空包丢在了停车场，一个名叫乔治的男人捡到这个钱包并对钱包的主人产生了兴趣，故事随着这股情欲流动演变成一个哭笑不得的猫鼠游戏。影片里仍然是充满了雷奈对于意象的追求。雷奈表示，这部影片的主题是关于“欲望的欲望”，取名为《疯草》是因为“片中人物的行动完全是非理性的，就像那些散落在马路和石头缝里的野草种子，没来由地疯长起来。”',NULL,0,0,1.866443,5.8,22,104,'2009-05-20','fr','/jOhHDa4PVaeWkIy97ileFPfEIb6.jpg',2.5161602541458428,3,'2026-09-10',2,NULL,NULL),(37903,'白丝带','Das weiße Band - Eine deutsche Kindergeschichte','德国北部一个新教村庄。1913-1914年。第一次世界大战前夕。故事围绕乡村教师带领的唱诗班里的孩童与少年，以及他们的家庭展开：男爵、管家、牧师、医生、助产士、租户。离奇事故接连发生，逐渐显露出一种惩戒仪式的特征。幕后黑手究竟是谁？乡村教师观察着、调查着，一点一点揭开了不可思议的真相。我们是否被引导去思考：这些事件是否预示了多年后纳粹德国崛起时将爆发的一切？其中是否已埋下后续悲剧的种子？',NULL,15238800,0,17.94739,7.2,255,144,'2009-05-21','de',NULL,3.1634848060245133,3,'2026-09-10',2,NULL,NULL),(37931,'百战天虫','MacGruber','在西伯利亚，一枚核弹头被美国黑市军火商康兹（方•基默 Val Kilmer 饰）一伙夺走。美国方面的吉姆上校迅速前往厄瓜多尔，在那里找到了传说中的顶尖特工马克•鲁柏（威尔•福特 Will Forte 饰），委托他解决核弹危机。十年前与康兹有杀妻之仇的马克决定再出江湖，他召来了自己的梦幻团队，不料因粗心大意导致所有队友死亡。为避免任务取消，狂妄的马克只得低声下气跪求自己看不起的新丁特工派波（瑞恩•菲利普 Ryan Phillippe 饰）和自己组队，加上他的好友维琪（克里斯汀•韦格 Kristen Wiig 饰），马克总算拼凑成一个三人小组向康兹发起进攻。行事风格毫无章法可言的马克几乎搞砸了整个任务，令他很快被吉姆上校踢出局，但这并不能阻止马克拯救核弹头瞄准下华盛顿人民的雄心壮志……','He\'s the ultimate tool.',10000000,6110000,14.038512,5.1,179,90,'2010-05-21','en','/9cO8JD7aaQzI4q8lBS8MYXH8LrJ.jpg',2.9335611534822466,3,'2026-09-10',2,NULL,NULL),(37950,'查理的生与死','Charlie St. Cloud','查理（扎克•埃夫隆 Zac Efron 饰）和山姆是一对形影不离的好兄弟，就在二人刚刚一举拿下帆船比赛的冠军的同时，查理就收到了斯坦福大学的全额奖学金，让本是英俊潇洒的查理更是成了女孩们心中炽热的梦中情人。满心憧憬大学生活的查理带着弟弟山姆在离家前一夜开车出去狂欢，却不料遭遇飞来横祸，醉酒的司机让这两兄弟一死一伤从此阴阳两隔。存活下来的查理活在痛苦与愧疚中，从此放弃了过去光芒的生活和远大的前程，留在镇上当一名守墓人。他遵守着和山姆生前的约定，每日黄昏陪着山姆的魂魄练习棒球，风雨无阻。而这种平静的生活和固若金汤的诺言，在查理爱上性感美丽的帆船女孩苔丝（阿曼达•克鲁 Amanda Crew 饰）后，开始发生了变化…\r 　　本片改编自本•舍伍德的同名畅销小说《查理•圣克劳德的生与死》，该片也是男主演扎克•埃夫隆和导演博尔•斯蒂尔斯继《重返十七岁》的二次合作。 ©豆瓣','Life is for living.',44000000,48190704,21.75433,6.8,566,99,'2010-05-01','en','/yn5mPSiPKC6AAkIyW5oMtUffAfy.jpg',3.3504353810944023,3,'2026-09-10',2,NULL,NULL),(37958,'惊天战神','Immortals','权欲熏心、冷酷嗜血的海恩波利国王（米基.洛克饰）为寻找失落多年的传说中的厄皮洛斯神弓，不惜带领他残暴的军队将古希腊夷为平地。凭借这把威力无比的神弓，他释放了足以毁灭众生的魔兽泰坦，他将有能力推翻奥林匹斯山的众神，成为他的世界的绝对统治者。 此时此刻宇宙之神宙斯也需要一个英雄。一位叫忒修斯的石匠(亨利.卡维尔饰)发誓要为在海恩波利的袭击中死去的母亲报仇。他成为被神选中的英雄，在先知的帮助下，最终他在决定人类未来的殊死决战中成为不朽的战神。','The Gods need a hero.',75000000,226904017,37.917002,5.7,880,110,'2011-11-10','en','/sNaTFuim0sIK5fFK1xU04rlA8h5.jpg',3.3251567556225377,3,'2026-09-10',2,NULL,NULL),(37964,'甜心情缘','Brown Sugar','安德鲁（泰雅·迪格斯 Taye Diggs 饰）和西德尼（桑娜·莱瑟 Sanaa Lathan 饰）都出生在繁华的大都市纽约，两人从很小的时候起就认识了，他们都喜欢说唱音乐，这一共同的爱好令两人之间的友谊格外的坚韧。\r 一晃眼15年过去，安德鲁和西德尼都长大成人，他们都坚持追求梦想，安德鲁成为了一名音乐制作人，而西德尼则成为了音乐评论家。这有趣的巧合让重逢的两人开始重新审视起了他们之间的感情，并且发掘出了全新的可能新。可是，此时的安德鲁已经订婚了，即将和未婚妻携手步入婚姻的殿堂，而西德尼也有了一位品质优良的追求者。','When did you first fall in love with hip-hop?',8000000,27362712,3.501158,7,31,109,'2002-10-05','en','/n9SnhQk29094VoLfyiYM4viyCrU.jpg',2.6052217295820586,3,'2026-09-10',2,NULL,NULL),(37985,'The Trials Of Darryl Hunt','The Trials Of Darryl Hunt','\"The Trials of Darryl Hunt\" is a feature documentary about a brutal rape/murder case and a wrongly convicted man, Darryl Hunt, who spent nearly twenty years in prison for a crime he did not commit. Both a social justice story and a personally driven narrative, the film chronicles this capital case from 1984 through 2004. With exclusive footage from two decades, the film frames the judicial and emotional response to a chilling crime - and the implications that reverberate from Hunt\'s conviction - against a backdrop of class and racial bias in the South and in the American criminal justice system.',NULL,0,0,0.15066,6.8,4,106,'2007-06-15','en','/7NHcKecimvicA4JLpN9CFaoaRjK.jpg',2.184737734636006,3,'2026-09-10',2,NULL,NULL),(38007,'艾拉和阿弼','Ira & Abby','婚姻是什么？ 步入礼堂的王子和公主是否真从此过着幸福快乐的日子？\r 获2006 Boston Jewish Film Festival与2006 Los Angeles Film Festival观众票选奖等奖项，由Robert Cary执导的爱情喜剧，搞笑颠覆你对神圣婚姻的想象，探讨婚姻的问题与现代人的焦虑。\r 贫穷的Ira遇到了活泼可人的Abby，俩人一见钟情的闪电结婚，可惜激情来的也也去的快，很快的，俩人就办妥的离婚手续，只是八竿子打不着的两家子与两人的生活，也在这个短暂的婚姻中改变了，婚姻到底是什么呢？','First comes love, then comes marriage, then comes therapy.',0,0,0.595136,5.8,9,104,'2006-01-01','en','/gK2XUjqWoqqYw6auny29W8tFwUG.jpg',2.3339972219984415,3,'2026-09-10',2,NULL,NULL),(38031,'遭遇陌生人','You Will Meet a Tall Dark Stranger','在共同度过了40年平静的婚姻生活后，阿尔菲（安东尼·霍普金斯 Anthony Hopkins 饰）突然决定离开妻子海伦娜（盖玛·琼斯 Gemma Jones 饰），转而投向和自己年龄差距极大的应召女郎查梅尼（露茜·彭奇 Lucy Punch 饰）的怀抱。在巨大的打击之下，海伦的精神开始崩溃，她选择了自我麻醉的手段，将意识和身体全部托付给了一个神神叨叨的算命师，唯命是从。  　　父母的婚变让身为女儿的莎莉（娜奥米·沃茨 Naomi Watts 饰）感到十分的头痛，同时，她和丈夫罗伊（乔什·布洛林 Josh Brolin 饰）的婚姻也出现了问题，莎莉爱上了其他的人。巧的是，同样的情况也出现在了罗伊的身上，并且，对于一个半红不紫的小说作者来说，还能有什么事情要比发现自己的死党拥有着高出自己千百倍的创作天赋更令人沮丧的呢？几乎完全相同的故事发生在了两代人之间，此时此刻，除了直面自己的处境，他们没有更好的选择。 ©豆瓣',NULL,22000000,0,12.4654,5.8,251,98,'2010-05-23','en','/oBhnI8UZQzTkAH1LMEtrBUmfpjS.jpg',3.0389223385287205,3,'2026-09-10',2,NULL,NULL),(38033,'连锁信','Chain Letter','现代科技飞速发展，各种通讯手段越来越先进，极大拉近了人与人之间的距离，也让人们的隐私无处遁形，甚至生命也受到极大的威胁。','If you don\'t forward it, you die.',0,0,2.504156,3.9,37,96,'2010-10-01','en','/5BveaRfU1KHW7fMttXScG96qPQ0.jpg',2.597307712527013,3,'2026-09-10',2,NULL,NULL),(38050,'The Adjustment Bureau','The Adjustment Bureau','A man glimpses the future Fate has planned for him – and chooses to fight for his own destiny. Battling the powerful Adjustment Bureau across, under and through the streets of New York, he risks his destined greatness to be with the only woman he\'s ever loved.','Fight for your fate.',50200000,127869379,26.60772,6.5,1652,106,'2011-03-03','en','/dWyX4tK36hInd1odXHxrmGnpSWU.jpg',3.584350193034348,3,'2026-09-10',2,NULL,NULL),(38055,'超级大坏蛋','Megamind','很多年前，银河系另一端的两颗行星被黑洞所吞噬，两个尚在襁褓中的外星孩子乘坐飞行器来到地球。拥有超能力的他们在截然不同的环境中长大，也造就了各自不同的性格和人生走向。长大后，仪表堂堂、正气凌然的成为了保卫城市和平的城市超人（布莱德·彼特 Brad Pitt 饰），而相貌猥琐、蓝皮大头的则化身破坏人民安康的大坏蛋麦克迈（威尔·法瑞尔 Will Ferrell 饰）。他们终日争斗，战争不断。城市超人博物馆开幕当天，麦克迈成功越狱，并劫持了美丽的女主播罗珊（蒂娜·费 Tina Fey 饰）。在天文台的终极决战中，麦克迈成功击败多年的老对手，完全统治了这座城市。好景不长，失去对手的麦克迈很快便觉得寡然无味。偶然间受到罗珊的启发，他决心创造出一个新的正义英雄，恢复当初此消彼长的快乐日子。只是，一切开始朝着不可预测的方向发展……','His brain is off the chain.',130000000,321887208,68.757242,6.7,1918,95,'2010-10-28','en','/uZ9ytt3sPTx62XTfN56ILSuYWRe.jpg',3.7600886322108025,3,'2026-09-10',2,NULL,NULL),(38073,'远距离爱情','Going the Distance','Erin（德鲁·巴里摩尔 Drew Barrymore 饰）和Garrett（贾斯汀·朗 Justin Long 饰）在灯红酒绿酒吧邂逅，两个青年对彼此人敞开了心胸，喝酒谈心度过了无比浪漫的美好一夜。第二天两人甚至还一块吃了早餐，火花就这样在两人中间闪现了。经过一段短暂但又甜蜜的时光，他们不得不面对一个严重的现实问题——Erin的家在旧金山，而Garrett的事业在纽约，但是他们两个都谁不愿意放弃现有的一切，更加舍不得让这段关系结束。于是，他们凭借着手机和各式通信工具开始了一场“远距离的恋爱”。\r 　　而最后他们的工作跟感情不能兼顾？是否又会为了对方放下一切来成全这一段感情？ ©豆瓣','A comedy about meeting each other halfway.',32000000,42045846,13.611544,6,262,102,'2010-09-01','en','/9dQVqzoWgeI3iSYsh047kiHz4Ul.jpg',3.065915200654175,3,'2026-09-10',2,NULL,NULL),(38093,'抚爱伤痛','Just Wright','莱斯利（奎恩·拉提法 Queen Latifah 饰）是一名经验丰富的康复训练师，著名NBA球星斯科特（科曼Common 饰）是她的客户。实际上，莱斯利对斯科特的感情可不是医生对病人这么简单，一直以来，她都默默的爱慕着斯科特，只不过她觉得自己和这位球场上的巨星身份地位相差甚远，于是选择将这份感情默默的埋藏在心底。\r 　　在一场比赛中，科特身受重伤，即将面临告别赛场的命运，此时莱斯利挺身而出，开始为他进行精密而细致的康复训练。让莱斯利没有想到的是，科特竟然和自己的好朋友摩根（宝拉·巴顿 Paula Patton 饰）走到了一起，看到整日出双入对的两人，莱斯利的心里非常的不是滋味','In this game every shot counts.',0,21520719,10.409253,6.1,99,100,'2010-05-14','en','/qx1SumoTQYtB9VyxQ7irlfE2e7L.jpg',2.8571066144783392,3,'2026-09-10',2,NULL,NULL),(38117,'野兽男孩','Beastly','《野兽男孩》是由CBS Films发行的爱情片，由丹尼尔·巴尔兹执导，亚历克斯·帕蒂弗和凡妮莎·哈金斯主演，于2011年3月4日在美国上映。\r 影片讲述了富家子弟凯尔被受他侮辱的同学肯德拉下了恶咒，把他变成了人见人厌的“怪物野兽”，只有当一个女孩真正发自内心爱上这个野兽，咒语才会解除的故事。','Love is never ugly.',17000000,43165571,24.054062,6,849,86,'2011-01-21','en','/4p1QmDN9vgk8a1wLbuPEKyClbbE.jpg',3.3352538018197144,3,'2026-09-10',2,NULL,NULL),(38153,'Shadow Conspiracy','Shadow Conspiracy','Bobby Bishop (Sheen) is a special assistant to the President of the United States. Accidentally, he meets his friend professor Pochenko on the street. Pochenko has time to tell Bishop about some conspiracy in the White House but then immediately gets killed by an assassin. Now bad guys are after Bobby as the only man who knows about a plot. Bishop must now not only survive, but to stop the conspirators from achieving their goal. And he doesn\'t know whom to trust.',NULL,45000000,2154540,3.848893,4,11,103,'1997-01-31','en','/m8dgxxCrpLhKjkjH2DPxkz0inoJ.jpg',2.37273629027152,3,'2026-09-10',2,NULL,NULL),(38167,'Eat Pray Love','Eat Pray Love','Liz Gilbert had everything a modern woman is supposed to dream of having – a husband, a house and a successful career – yet like so many others, she found herself lost, confused and searching for what she really wanted in life. Newly divorced and at a crossroads, Gilbert steps out of her comfort zone, risking everything to change her life, embarking on a journey around the world that becomes a quest for self-discovery. In her travels, she discovers the true pleasure of nourishment by eating in Italy, the power of prayer in India and, finally and unexpectedly, the inner peace and balance of true love in Bali.','Let Yourself GO',60000000,204594016,28.800112,5.8,636,133,'2010-08-12','en','/2cJ4ET5Ce3oj6rXPumRr3A83CE0.jpg',3.257922574168542,3,'2026-09-10',2,NULL,NULL),(38223,'超级大间谍','Harriet the Spy','When the secret notebook of a young girl who fancies herself a spy is found by her friends, her speculations make her very unpopular! Can she win her friends back?','On your case!',12000000,0,4.63093,5.7,46,100,'1996-07-10','en','/spTUUMgIVm4gOdWL35IoYWEuZQl.jpg',2.67305678212289,3,'2026-09-10',2,NULL,NULL),(38303,'怎么又是你','You Again','所有美国高校里都有一个美丽的啦啦队队长，当然也会有一个其貌不扬受人排挤的丑小鸭，玛妮（克里斯汀·贝尔饰）是丑小鸭故事里的励志小鸭，长大后除去眼镜摘掉牙箍终于成为了公关公司受人追捧的魅力主管。而噩梦是回老家参加哥哥威尔（詹姆斯·沃克饰）的婚礼，未来大嫂就是那位曾经带头欺负她的啦啦队队长头乔安娜（奥黛塔·雅丝曼饰）。回到家后，所有家人都围绕在美丽的乔安娜身边，玛妮不堪回首的回忆又涌上心头。故事总有不可思议的巧合，玛妮的妈妈盖尔（杰米·李·柯蒂斯饰）中学时期的死对头竟然是乔安娜的姑姑拉蒙纳（西格妮·韦弗饰）。  　　误解、报复、争吵、妒忌、重归于好……男人永远无法理解的女人间的斗争在这两代人当中开战。','What doesn\'t kill you... is going to marry your brother.',20000000,32005248,19.962713,6,368,105,'2010-09-24','en','/9qI5JE6yjmtakTankuDOMZ1vgEx.jpg',3.1515557949363595,3,'2026-09-10',2,NULL,NULL),(38317,'动物园看守','Zookeeper','格里芬·凯耶斯是富兰克林公园动物园里的一个饲养员，他工作认真负责，加上热爱小动物，所以深得动物们的喜爱。凯耶斯是一个超重的大胖子，年龄不小的他一直想找个漂亮的姑娘结婚生子，过上平凡而快乐的生活。但是，生性腼腆的他并不善于和女孩子相处。他甚至觉得和一只狮子呆在一起也比和一个顾念呆在一起要舒服。只是，年龄到了，不谈婚论嫁不行。　　凯耶斯决定辞职，他准备换一份更有吸引力的工作，好找个女孩。这么一来，动物们闹起了情绪，因为它们舍不得这个胖乎乎的饲养员离开它们。于是，动物们决定打破沉默，站出来教会凯耶斯动物世界里的“把妹技巧”。而且它们也决定要告诉凯耶斯一个天大的秘密－－它们会说人话。　　动物的伎俩能成功么？它们能帮助凯耶斯追到女孩，并顺利地把他留在动物园么？','Welcome to his jungle.',80000000,169852759,27.46264,5.3,498,102,'2011-07-06','en','/v3qIzv94BHpsxmyx2hnxtErwPfT.jpg',3.146573315180811,3,'2026-09-10',2,NULL,NULL),(38319,'王子殿下','Your Highness','由丹尼·麦克布耐德饰演的Thadeous是个不靠谱的王子，他的前半生都用来观摩自己完美的哥哥Fabious（詹姆斯·弗兰科 饰）勇敢又英俊的上进了，而自己则每天陷入毒品、大麻、与仆人自娱自乐等颓废人生里。而某日他们的国家遭遇了邪恶巫师的打击，Fabious的未婚妻也就是佐伊·丹斯切尔饰演的Belladonna被绑架了，于是天降大任，或者说是过往老爹胁迫给了Thadeous任务，他要和哥哥去经历冒险拯救国家了，两位王子被迫遭遇了许多艰难险阻，不过和《菠萝快车》一样，他们处理艰难险阻的方式都是插科打诨和囧囧有神式的。','Get your quest on.',49900000,26121638,21.408222,5.2,501,102,'2011-04-08','en','/zw1tEKhR1ncGGtuYkkf30GYlvYQ.jpg',3.1214669278476275,3,'2026-09-10',2,NULL,NULL),(38321,'驱魔者','Priest','备受吸血鬼肆虐的人类社会里，毫无希望的人类开始沉迷于宗教和信仰，而教会也成为了这个敌托邦城市里权力最大的组织，他们控制了整个城市，并且还和吸血鬼私下达成了龌龊的勾当。　　老实本份的牧师（保罗·贝坦尼饰）在人类和吸血鬼之间周旋已久，他曾经经历过上一次人类和吸血鬼的惊世大战，存活下来的他希望通过自己的布道能够力所能及的拯救苍生，但吸血鬼势力越来越强大，甚至还把他的侄女露西（莉莉·柯林斯饰）捉走，牧师求助于教会，但教会却对此睁一只眼闭一只眼。愤怒的牧师几近绝望，不再听命于教会，他决定以暴制暴，救回露西。他与同样遭受亲人离别之痛的女祭司（李美琪饰）一起搭档，走上猎杀吸血鬼的征途，他们的标记则是眉心之间的十字印记。牧师和女祭司加入了城市里的警长希克斯（凯姆·吉甘戴饰）所领导的地下反抗组织，他本是露西的男朋友，为了拯救自己心爱女人，他也就此踏上除魔路，并且在战斗中发挥出了令牧师意外的超凡能力……','Vampire Killer',60000000,78309131,28.350927,5.4,692,87,'2011-05-05','en','/g2hT62qxW5q8vjs7DRtpMki0rhy.jpg',3.214758389726335,3,'2026-09-10',2,NULL,NULL),(38322,'卧底肥妈3','Big Mommas: Like Father, Like Son','他聪明能干，他一身正气，他屡破奇案，他就是马尔科姆·特纳(马丁·劳伦斯)——什么都能搞定的联邦调查局密探!行家一出手，就知有没有。老马之所以一把还征战街头，还真因为他能人所不能，深得上司器重。可金钟罩铁布衫也怕命门被戳中，老马破起大案来头头是道，但一摊上家中妻小就只能手足无措。特别是他那个刚好青春期的继子川特(布兰登·杰克逊)，老爱给他找麻烦，让他除了每天念阿弥陀佛上帝保佑别无选择。这不，老马最近忙着盯梢某犯罪大鳄，神经绷到了极点，川特倒好，误打误撞亲眼目击了一场惊心动魄的谋杀案，还不知死活地差点被别人灭口。','Momma\'s got back-up.',32000000,83615414,15.901137,5.3,313,107,'2011-02-16','en','/n1GSxFcDaZ6lMVf21M0KloPfuhu.jpg',3.0453001841549776,3,'2026-09-10',2,NULL,NULL),(38356,'变形金刚3：月黑之时','Transformers: Dark of the Moon','距今50多年前，一艘来自赛博坦的飞船坠落月球，由此引发了美苏两国的太空竞赛。人类争相登上月球，只为一探飞船残骸中的秘密。时间回到21世纪初，经过几番征战，汽车人终于挫败霸天虎的入侵，继而与人类合作，共同保卫美丽的地球。然而发生在切尔诺贝利的事件却将尘封已久的月球计划重新摆到桌面。为了防止霸天虎找到能量柱为非作歹，擎天柱与战友飞赴月球，更从当年的飞船中救出了汽车人的先代领导者——御天敌。御天敌是能量柱的发明者，将上百根能量柱集合在一起便可制造太空桥，实现物质的瞬间传送。忙着找工作以及和女友卡莉（罗茜·汉丁顿·惠特莉饰）经营爱情的山姆（希亚·拉博夫饰）无可避免地卷入其中，他渐渐发现霸天虎的操纵一切的阴谋，却不知更大的阴谋和危机隐藏在那月影背后……','The invasion we always feared. An enemy we never expected.',195000000,1123746996,28.529607,6.1,3299,154,'2011-06-28','en','/bVYQHmSyFZpEClcf0npT8OfG4tZ.jpg',3.655108316208599,3,'2026-09-10',2,NULL,NULL),(38357,'早间主播','Morning Glory','电视制片人贝克丽·弗勒尔为了让收视率不佳的《早间秀》节目起死回生，把脱口秀明星迈克·波默罗伊挖到节目组。他那传统、经典而沉闷的主持风格，与轻松、俏皮带有些可爱成分的女主持人格格不入。可《早间秀》就是一档轻松娱乐的搞笑节目，波默罗伊只有硬着头皮和选美小姐出身，被他称之为“白痴”的克林恩·匹克合作。两人常起冲突，斗争越来越公开化，甚至还被现场直播了出去。同时，弗勒尔发疯似地爱上了另一制片人亚当·本内特，不过他们的爱情似乎也在这时出现了问题。随着节目收视率的下降、主持人冲突的公开化和激烈化，弗勒尔似乎是走投无路了。她能力挽狂澜，挽救自己的事业、生活和爱情么？不苟言笑的波默罗伊能敞开自己的心扉面对曾经的辉煌和自己并不如意的家庭生活么？','Breakfast TV just got interesting.',40000000,58785180,22.491388,6.1,412,102,'2010-01-12','en','/aFRXEoB3QkeHNHYmVGC3uzFSol8.jpg',3.191765715802029,3,'2026-09-10',2,NULL,NULL),(38358,'The Last Exorcism','The Last Exorcism','After years of performing “exorcisms” and taking believers’ money, Reverend Marcus travels to rural Louisiana with a film crew so he can dispel what he believes is the myth of demonic possession. The dynamic reverend is certain that this will be another routine “exorcism” on a disturbed religious fanatic but instead comes upon the blood-soaked farm of the Sweetzer family and a true evil he would have never thought imaginable.','Believe In Him.',1800000,67738090,14.838986,5.6,328,87,'2010-08-27','en','/xktasIoL3bUMyFeT90PWNdqmCK2.jpg',3.0785292166772953,3,'2026-09-10',2,NULL,NULL),(38363,'众矢之的','Fair Game','在美国被政治笼罩的大氛围中，所谓的“公平”，也变成了一种特殊的存在，只有靠着自己的不断争取与抗争，才有可能变为现实……瓦莱丽·普莱姆（娜奥米·沃茨饰）在美国CIA武器不扩散部门工作，秘密领导伊拉克大规模杀伤性武器调查。瓦莱丽的丈夫乔（西恩·潘饰）是外交官，接到了寻找尼日尔向伊拉克售卖浓缩铀嫌疑案证据的任务。当布什政府无视调查结论，毫无证据地发动战争时，乔在《纽约时报》发表了一篇文章，引发了激烈争论。没过多久，瓦莱丽高度机密的特工身份就被泄露给了华盛顿时事记者。身份的暴露、国外联系人遭遇生命危险、丈夫的猜疑、家庭濒临崩溃的危局让她身心疲惫。瓦莱丽不得不奋起捍卫事实和真理，挽救自己的家庭、工作和生活。','Wife. Mother. Spy.',22000000,24188922,12.54949,6.5,235,108,'2010-05-20','en','/m1Ye2ujLLTSTREEng30gXUFQ9Wu.jpg',3.0772516995904176,3,'2026-09-10',2,NULL,NULL),(38365,'长大成人','Grown Ups','1978年，有五虎之称的少年篮球队在赛事中最终获胜，他们的教练罗伯特鼓励少年们去夺取更大的人生胜利。三十年后，五虎之一的费德（亚当•桑德勒 Adam Sandler 饰）已经是好莱坞知名的大牌经纪人，他和妻子莱克斯（萨尔玛•海耶克 Salma Hayek 饰）生活无忧，孩子们养尊处优。这天费德突然接到告知罗伯特教练逝世的电话，于是匆匆赶回新英格兰，和当年的四位队友一起参加葬礼。今日的家具商艾瑞克（凯文•詹姆斯 Kevin James 饰）、取得老妻的卡林（罗伯•施奈德 Rob Schneider 饰）、吃软饭的科特（克里斯•洛克 Chris Rock 饰）以及西吉（大卫•史派德 David Spade 饰）和费德五个家庭一起回到年少时生活过的湖边别墅，他们在这里找到了被吵吵闹闹的日常生活淹没已久的珍贵情感……','Boys will be boys. . . some longer than others.',80000000,271430189,38.864027,6,1705,102,'2010-06-24','en','/9NRApTZQrsiKBM2pvatUEUi1DBb.jpg',3.5148751198122947,3,'2026-09-10',2,NULL,NULL),(38415,'Bran Nue Dae','Bran Nue Dae','In the Summer of 1965 a young man is filled with the life of the idyllic old pearling port Broome - fishing, hanging out with his mates and his girl. However his mother returns him to the religious mission for further schooling. After being punished for an act of youthful rebellion, he runs away from the mission on a journey that ultimately leads him back home.','Bran Nue Dae',7,7,0.050456,5.2,6,82,'2009-08-09','en','/7tB7mr0OqHsgATo58PAtSNJpaP7.jpg',2.254209965084127,3,'2026-09-10',2,NULL,NULL),(38428,'Gandhi, My Father','Gandhi, My Father','With Gandhi My Father, producer Anil Kapoor and director Feroz Abbas Khan have shed light onto Gandhi the person, rather than Gandhi the icon. Using Gandhi’s political career as a canvas, the film paints a picture of his intricate, complex, and strained relationship with his son Harilal Gandhi.','To the People...He was a Father. To his Son...he was a Father he never had.',0,0,0.080704,6,2,136,'2007-08-03','hi','/sFzo2Ss4PQfNUlrzeTfwoVp5ajE.jpg',2.0724348565518245,3,'2026-09-10',2,NULL,NULL),(38448,'水中仙','Ondine','爱尔兰渔夫锡拉丘兹（科林·法瑞尔 Colin Farrell 饰）从海上捞起了一个神秘的美丽女子，名唤奥丁（艾丽卡·巴赫蕾达 Alicja Bachleda 饰）。锡拉丘兹将不愿见人的奥丁安置在自己母亲的海滨老屋中，意外发现奥丁竟给他的渔船带来了好运。锡拉丘兹的女儿安妮（艾莉森·巴瑞 Alison Barry 饰）患有肾脏衰竭，与酗酒的母亲莫拉（德乌拉·基尔万 Dervla Kirwan 饰）及其男友一起生活。安妮与奥丁结下了坚固的友谊，她相信奥丁是苏格兰神话中的海豹少女，上岸后埋下自己的海豹皮，便可在陆地生活七年，直到自己的海豹丈夫前来带她返回大海深处。锡拉丘兹果然与奥丁彼此相爱，但他对奥丁是真正身份一直半信半疑，直到某个黑发男子的神秘出现，要带走奥丁……  　　本片被提名爱尔兰电影电视协会最佳服装设计、最佳导演、最佳影片及最佳电影剧本奖，并获最佳男主角（科林·法瑞尔）、最佳女配角（德乌拉·基尔万）、最佳布景及最佳声音奖。','The truth is not what you know. It\'s what you believe.',12000000,1644755,5.841285,6.5,84,111,'2009-09-14','en','/rQSQisWjIjXnGGenrpjG1GlQcRf.jpg',2.823850635636414,3,'2026-09-10',2,NULL,NULL),(38541,'隔绝','The Divide','影片讲述纽约市一场灾难性的爆炸后，8个陌生人躲进了一座公寓大楼的地下室中。地下室由三个相连的房间组成，幸运的是里面有食物和水储备着，8个幸存者于是开始等待救援……直到一个身着核生化防护服的男子出现……他是来寻找什么的？是什么让他如此残忍冷酷？当生化防护服的一小队人马暂时退去，更糟的情况来了，幽闭恐惧症让这次从避难所变成了牢笼……误解及羁绊又如何化解？','The lucky ones died in the blast',3000000,22000,11.882563,5.7,197,112,'2011-03-13','en','/hnwX5cUuzBDM0OWJB2UtnjkrHDm.jpg',2.9829070499780674,3,'2026-09-10',2,NULL,NULL),(38543,'铁甲衣','Ironclad','公元1215年，英国男爵叛乱，约翰王被迫签署了大宪章，大宪章抑制了王权，保证了人们享受自由的权利，也为今后英国的普通法系奠定了基础。然而不甘心受限的国王出尔反尔，在英国南部海岸集结了一支雇佣兵军队准备将男爵们抓获，试图将国家重新收归他的独裁统治之下。就在国王军队一步步向伦敦逼近，王权即将收回之时，Albany男爵率领的7人小组在罗切斯特城堡奋力抵抗，等待法国的救援。罗切斯特城堡也成为了公平、正义和自由而奋起反抗的重要象征。','Heavy metal goes medieval.',25000000,0,12.31708,6.2,227,121,'2011-03-03','en','/h7CP12wAThhw2WSOA1uIAqxg1fS.jpg',3.047113467103632,3,'2026-09-10',2,NULL,NULL),(38570,'The 41–Year–Old Virgin Who Knocked Up Sarah Marshall and Felt Superbad About It','The 41–Year–Old Virgin Who Knocked Up Sarah Marshall and Felt Superbad About It','Follows Andy, who needs to hook up with a hottie, pronto, because he hasn\'t had sex in... well, forever - and his luck isn\'t the only thing that\'s hard. His equally horny teenage roommates also need it superbad, and with the help of their nerdy pal, McAnalovin\' and his fake I.D., they may tap more than just a keg.',NULL,0,0,5.628399,3.2,34,82,'2010-06-08','en','/rqShY7xY6sUEXsr9cglmclryfjp.jpg',2.5797071206791244,3,'2026-09-10',2,NULL,NULL),(38579,'大丹麦狗马默杜克','Marmaduke','一个幸福的家庭从城郊搬迁到一个新的环境之中，不过他们养的可爱的大丹犬却似乎不买主人的账，它要用自己的方式给新邻居们“搞搞震”。  　　改编自同名漫画，《大丹麦狗马默杜克》漫画最早由布拉德·安德森发表在报纸上，连载了几十年，后又被改编成电视动画片。故事的主角是一只顽皮的大丹麦狗，它和Winslow一家生活在一起','Live Large',50000000,83761844,12.25622,5,149,87,'2010-06-04','en','/wNNqAqvOn717AWBhBQskH2Lnzmz.jpg',2.893142696732224,3,'2026-09-10',2,NULL,NULL),(38665,'游侠传奇','The Legend of the Lone Ranger','John Reid，是德克萨斯一名年轻的骑警，在一次黑帮头领Butch Cavendich设下的埋伏中被童年的伙伴--印第安科曼奇族的Tonto所救，成为唯一的幸存者。当他从伤势中恢复过来后，他决定誓死对抗Cavendich所犯下的罪恶。由此，他带上面具，成为一名伟大的西部英雄--独行侠。最后，他和他的伙伴Tonto，救出了被Canvendich绑架的总统Grant。','The untold story of the man behind the mask, and the legend behind the man.',18000000,2945600,11.725805,3.7,14,98,'1981-08-20','en','/6AgJFQsZm3JHry8ek13X0xKGWt6.jpg',2.4349637058467426,3,'2026-09-10',2,NULL,NULL),(38717,'麦迪逊','Madison','影片根据真实事件改编，讲述了在 1971 年印第安纳州因航运萧条而死气沉沉的麦迪逊小镇上，曾遭受重创的赛艇好手巴迪不甘心家乡就此沉沦，在濒临绝境的物资匮乏与家庭危机中，毅然带领一群由当地普通居民临时组建的业余团队，顶住所有人的冷眼与嘲笑修复了一艘破旧的水上超级飞艇，并在家乡举办的美国总统金杯赛（Gold Cup）中，与全美最顶级的职业巨头车队在水面上展开一场尊严与速度的终极生死对决。','A town\'s future is riding with one man.',0,0,0.212108,5.3,3,99,'2001-01-23','en','/hlZUHqnwcOv5yPXW7BmguKedNP.jpg',2.134296991175005,3,'2026-09-10',2,NULL,NULL),(38745,'格列佛游记','Gulliver\'s Travels','杰克·布莱克饰演的格列佛是个邮政室小职员，岁数也不小了，却事业爱情一无所成。一次阴差阳错的公派任务，把他带到了百慕大群岛，不想，出海即遭遇到大风暴。风平浪静之后，格列佛发现自己来到了一个地图上没有的神秘小岛Lilliput，这里住着成百上千”小人”，他们把格列佛”钉”在了海滩上。不过随着故事的发展，格列佛从最开始的俘虏，变成了这里的英雄人物–在小人国的经历让他明白了人类的内心的强大与否无关外表。','Something big is going down.',112000000,237382724,22.845143,4.9,621,85,'2010-12-25','en','/yJ30J7wyohNZ1JFR4c87QaxRtZk.jpg',3.1154498448865,3,'2026-09-10',2,NULL,NULL),(38757,'魔发奇缘','Tangled','女巫Gothel靠着一朵神奇的金色花朵保持青春。王后重病，国王派人找到了这朵金花给王后治病，王后病愈，生下了一个一头金发的小女孩Rapunzel。女巫失去金花，却发现小公主的金发有 着同样的魔力，因此她偷走Rapunzel，把她关到森林中的一座没有楼梯高塔之上。十八年后，Rapunzel在女巫的抚养下长成一个拥有长长金发的美人，她越发渴望外面的世界，女巫为了自己青春永驻，想方设法把Rapunzel留在身边。一天，窃贼Flynn盗取公主王冠后逃入森林，在好奇心趋势下登上了这座神秘的高塔，误打误撞见到了塔中的长发公主。在Flynn的陪伴下，Rapunzel走下高塔，开始了人生和爱情的大冒险。','They\'re taking adventure to new lengths.',260000000,591794936,48.681969,7.4,3330,100,'2010-11-24','en','/ym7Kst6a4uodryxqbGOxmewF235.jpg',4.023165959166849,3,'2026-09-10',2,NULL,NULL),(38778,'笨人晚宴','Dinner for Schmucks','《笨人晚宴》根据1998年的法国电影《Le Diner de Cons》改编而成。主人公蒂姆（保罗·路德　饰）为了升职，不得不去讨好他的混蛋老板，并且答应参加他所谓的“白痴晚宴”。晚宴的规则很简单，即每人携一名“白痴之最”共赴晚餐，看看到底谁带来的客人最愚不可及，以此来逗乐取笑。后来主人公找到了一个看起来很傻的男人（史蒂夫·卡瑞尔 饰），原以为他是最佳人选。没想到因为阴差阳错，对方傻头傻脑的举动，反倒将主人公愚弄了一番，让其叫苦不迭。','Takes One To Know One.',69000000,86387857,11.023691,5.5,531,114,'2010-07-30','en','/eqCyt9ILsInMYPa2iveiINeVOJD.jpg',3.1444323028097876,3,'2026-09-10',2,NULL,NULL),(38780,'狂暴','Rampage','一个充满了报复心的人，用牢固的凯夫拉合成纤维为自己打造了全身盔甲，开始了一场杀人狂欢。','Vengeance is ruthless.',0,0,7.101197,6,131,85,'2009-08-14','en','/xZZlA5obgTrQMyAF16yqCiVxHlO.jpg',2.9051405501096803,3,'2026-09-10',2,NULL,NULL),(38786,'The Blood of My Brother: A Story of Death in Iraq','The Blood of My Brother: A Story of Death in Iraq','THE BLOOD OF MY BROTHER goes behind the scenes of one Iraqi family\'s struggle to survive amidst the carnage of the growing Shia insurgency. Nineteen-year-old Ibrahim dreams of revenge when his brother is shot and killed by an American patrol. With scenes of fighting and death on the streets of Baghdad, this is the closest most viewers will ever come to being in Iraq; kneeling in prayer amidst a thousand Muslim worshipers, feeling the roar of low-flying Apaches, riding atop a sixty-ton tank, driving with masked resistance fighters to attack American positions, fleeing the threat of an overwhelming response, the blood in the street, a tank on fire, or the cold, distant stare of a dead Iraqi fighter. Written by Andrew Berends.',NULL,0,0,0.005256,0,0,90,'2005-11-25','en',NULL,1.8337943910593917,3,'2026-09-10',2,NULL,NULL),(38810,'狗牙','Κυνόδοντας','本片讲述了一个与世隔绝的奇怪家庭。家庭成员由一对父母和大儿子、两个女儿组成，一家五口终日生活在一座隐秘的大宅子里。三个孩子自小被父亲隔离于此，他们不能接触除父母外的人，对高墙之外的世界几乎一无所知。父亲上班后，他们就与母亲在屋子里学习、玩耍。他们所有的知识都由父母教导，父亲告诉他们，外面的世界极其危险，而孩子们如果想要出去，必须等到“狗牙”脱落。父亲是唯一可以驾车到外面去的人，他有一份正常的工作，会为孩子们带回生活必需品以及奖赏，他有时也会带回公司里一个女员工——克里斯蒂安，她是受雇来满足大儿子的性需求的。而她的几次到来，正在悄悄地改变这个家庭……','The cat is the most feared animal there is!',0,110197,28.858238,6.9,332,94,'2009-06-01','el',NULL,3.234877509190881,3,'2026-09-10',2,NULL,NULL),(38843,'蕾蒙娜和姐姐','Ramona and Beezus','9岁的小女孩蕾蒙娜·昆比（乔伊·金 Joey King 饰）生活在一个幸福美满的家庭里，父亲罗伯特（约翰·考伯特 John Corbett 饰）和善宽容，尽心支撑着这个家；母亲桃乐丝（布丽姬·穆娜 Bridget Moynahan 饰）善良温柔，悉心打理家中的一切；她的姐姐碧祖丝（赛琳娜·戈麦斯 Selena Gomez 饰）美丽聪颖，品学兼优，姐妹俩还有一个牙牙学语的小妹妹。古灵精怪的蕾蒙娜每天尽情玩耍、调皮捣蛋，无忧无虑地享受这份宛如天堂般的快乐时光。然而随着父亲的失业，昆比家的快乐不复存在，人人脸上挂满愁容。蕾蒙娜不愿看到这一切，她决定用自己的奇思妙想为家人们找回久违的快乐……','A Little Sister Goes A Long Way.',0,0,9.681147,6.1,245,103,'2010-07-23','en','/njFC0fuHoiX5tlcEueiF8sLTU3v.jpg',3.0504116056016297,3,'2026-09-10',2,NULL,NULL),(38940,'魔鬼悍将','Men of War','一退役庸兵，再度奉召，远赴南太平洋的小岛，说服该地岛民授权该岛矿产的开采权；由于该地岛民的纯朴与善良，使得＂杜夫朗格＂与其伙伴改变初衷，而决定留下保卫此岛的居民；因而引爆一场与恶势力阴谋的对抗','Killers for hire are paid for what they can do, not for what they believe... until today.',0,0,1.734764,5.4,29,103,'1994-09-04','en','/rrwG9foUMulWBI2Nk7s6Bcgwfim.jpg',2.568120394568821,3,'2026-09-10',2,NULL,NULL),(38970,'同床异梦','Ricordati di me','人过中年的瑞斯图西亚夫妇生活优渥、饮食无忧。然而富足的物质条件总与匮乏的精神状况形成鲜明的对比。担任公司高管职务的丈夫卡罗（Fabrizio Bentivoglio 饰）与妻子激情不在，在某次同学会上他重逢了已为人妇的昔日恋人爱莉西娅（Monica Bellucci 莫妮卡•贝鲁奇 饰），他们的爱火重燃；妻子吉莉娅（Laura Morante 饰）为了家庭放弃自己钟爱的舞蹈事业，在好友的帮助下，她走入话剧圈真正去做一件自己想做的事情；19岁的儿子保罗（Silvio Muccino 饰）孤独无助，缺乏认同感，他只希望融入其他的同龄人中；18岁的女儿瓦伦蒂娜（Nicoletta Romanoff 饰）一心走上电视荧幕，为此不惜出卖肉体。','Some loves are never forgotten',0,0,4.240495,5.8,44,125,'2003-02-11','it','/xuVUKWjSkY5LntEBwAHCXMO1Tei.jpg',2.664732635350957,3,'2026-09-10',2,NULL,NULL),(38985,'千惊万险','Sorcerer','四名犯罪流放者冒着生命危险寻求法律和道德上的救赎，穿越危险的拉丁美洲丛林去运送大量硝化甘油。','WANTED. Four men willing to drive a cargo of death to escape a life in hell.',22000000,12000000,9.088209,7.4,98,121,'1977-06-24','en','/2b7oexm173SF1FSEq0DdgxZZNRH.jpg',2.8981578064587326,3,'2026-09-10',2,NULL,NULL),(39013,'冬天的骨头','Winter\'s Bone','这部张力十足的自然主义惊悚片，讲述17岁的芮·多利为寻回以家宅抵押保释后失踪的父亲，被迫直面当地犯罪黑社会与严酷的奥扎克荒野。詹妮弗·劳伦斯凭借突破性演出崭露头角，本片注定成为年度最受好评的影片之一。[Roadside Attractions]','Talking Just Causes Witnesses',2000000,13831503,20.834883,6.8,565,100,'2010-06-11','en','/kIe9cD1QpqnDxm6RomdCacvY8SG.jpg',3.3478621487863056,3,'2026-09-10',2,NULL,NULL),(39037,'好男孩','The Good Guy','和所有生活在曼哈顿的女孩一样，贝丝（阿丽克西斯·布莱德尔 Alexis Bledel 饰）觉得自己的人生才刚刚起步，令她十分确定的是，在可以预见的未来里，她会领着一份不菲的薪水，和自己心爱的男人住在温馨的房子里。怀着对未来的憧憬，贝丝遇见了华尔街的宠儿汤米（斯科特·波特 Scott Porter 饰）。汤米高大帅气，慷慨多金，他似乎就是为了贝丝量身定做的Mr Right，而他和贝丝之间的距离也似乎越来越近。\r   有一个人让贝丝十分的在意，那就是汤米的同事丹尼尔（布赖恩·加连保格 Bryan Greenberg 饰），无意之中贝丝发现在丹尼尔的身上，竟然存在是异常吸引她的特质。身处感情的岔路口，贝丝不知道该何去何从。',NULL,3200000,0,2.631688,5.4,59,90,'2009-04-25','en','/xwSQ62M3B1LTpHhau4MaREIwfSy.jpg',2.7128511755709916,3,'2026-09-10',2,NULL,NULL),(39053,'Cyrus','Cyrus','With John\'s social life at a standstill and his ex-wife about to get remarried, a down on his luck divorcée finally meets the woman of his dreams, only to discover she has another man in her life - her son. Before long, the two are locked in a battle of wits for the woman they both love-and it appears only one man can be left standing when it\'s over.','John met the woman of his dreams. Then he met her son ...',7000000,0,15.212569,6.1,133,91,'2010-06-18','en','/qkJ0rB1qf62TJ6thxEVRT7Eccqn.jpg',2.9314993066750348,3,'2026-09-10',2,NULL,NULL),(39055,'Free Style','Free Style','Cale Bryant is determined to win a coveted spot on the Grand National motocross racing team. With the support of his loving mother, precocious little sister and new girlfriend, Cale proves against all odds that he has the heart, the willpower and the courage never to give up on his dream.','It\'s Time To Soar.',0,140987,0.122874,5.8,4,94,'2008-12-24','en','/h74c8DziH9VAcVbr4aKGlrIawvw.jpg',2.183035884963001,3,'2026-09-10',2,NULL,NULL),(39141,'诱惑我小妈','Tadpole','15岁的奥斯卡(艾伦史丹佛饰)既早熟又善体人意，他说流利法文、还勤读伏尔泰，所有同年纪的女生都哈他，不过，他却偏偏只甲意“老女人”。这个假期，他即将跨出他“转大人”的第一步，诱惑他心爱的女人上勾，而这对象不是别人，正是他的小妈---伊芙(雪歌妮薇佛饰)。然而，天不从人愿，奥斯卡还没钓到伊芙却先煞到一群高龄欲女，伊芙的姊妹淘黛安。  　　15岁的Oscar，聪明好学。他不满同龄女孩的浅薄，爱上了成熟又有学问的女性——他的继母Eve，而他的教授父亲对此一无所知。他想在感恩节之夜对继母表白，却又难以开口，醉醺醺地跟继母的密友Diane上了床，失了童贞。父亲慈爱的关心、Diane的纠缠和Oscar对继母的纯真爱情，构成了本片的喜剧元素。情节有些荒唐，但正象电影中Diane对Eve所说的：你还记得我们15岁的时候是如何梦想的吗？','Everyone says he should date girls his own age. Oscar respectfully disagrees.',150000,2891288,8.570328,5.5,19,78,'2002-11-01','en','/r7wCSE5Hj82GHywm2evC1ERmK0E.jpg',2.4992018719264726,3,'2026-09-10',2,NULL,NULL),(39180,'天翻地覆','See Spot Run','特警11号是全美国最优秀的警犬，在和训导员天衣无缝的配合之下，他们破获了多起重案要案，这也让特警11号成为了诸多犯罪分子们的眼中钉肉中刺。毒枭桑尼（保罗·索维诺 Paul Sorvino 饰）就是其中之一，曾经栽在了特警11号手上的他发誓一定要将条警犬从除之而后快。 为了保护特警11号，训导员决定把它送往警犬基地保护起来，然而，桑尼早就在警队中安插了内线，特警11号实际上早就落入了圈套之中。好在特警11号拥有着过人的智慧，它识破了阴谋，躲过了暗杀，藏身于平凡邮差戈德（大卫·阿奎特 David Arquette 饰）的车中，并因此邂逅了热爱小动物的男孩詹姆斯（安加斯·T·琼斯 Angus T. Jones 饰）。','The Smart One Isn\'t Wearing Any Pants.',0,0,6.579017,4.8,44,94,'2001-03-02','en','/29iKqRGRcNqhrT710ohxVq5WwcE.jpg',2.6529853609722602,3,'2026-09-10',2,NULL,NULL),(39183,'Once in a Lifetime: The Extraordinary Story of the New York Cosmos','Once in a Lifetime: The Extraordinary Story of the New York Cosmos','In the 1970s the North American Soccer League marked the first attempt to introduce soccer to American sports fans. While most teams had only limited success at best, one managed to break through to genuine mainstream popularity - the New York Cosmos. The brainchild of Steve Ross (Major executive at Warner Communications) and the Ertegun brothers (Founders of Atlantic Records), the Cosmos got off to a rocky start in 1971, but things changed in 1975 when the world\'s most celebrated soccer star, the Brazilian champion Pele, signed with the Cosmos for a five-million-dollar payday. With the arrival of Pele, the Cosmos became a hit  and the players became the toast of the town, earning their own private table at Studio 54. A number of other international soccer stars were soon lured to the Cosmos, including Franz Beckenbauer, Rodney Marsh, and Carlos Alberto, but with the turn of the decade, the team began losing favor with fans and folded in 1985.','The untold story of the team that had America at its feet.',1000000,0,0.436148,4.7,3,97,'2006-01-01','en','/ubgZkHS1KoVILTH051zr47vMfDv.jpg',2.1340704631948846,3,'2026-09-10',2,NULL,NULL),(39209,'沙拉克','Shalako','十九世纪末，一伙庞大的队伍来到西部的新墨西哥城。这一伙没落的欧洲贵族来这里的目的是狩猎。队伍停留在当地的阿帕奇印第安部落中宿营，起初他们受到阿帕奇人的盛情款待，哪知道后来他们触犯了当地人民，阿帕奇人要把他们处死。队伍中的领头人伯爵夫人埃瑞娜（碧姬·巴铎 饰）决定率领自己的队伍和这里的阿帕奇部落展开了反击……','Sean Connery is Shalako! Shalako means action! Action means Bardot!',1455000,2620000,3.598457,5.4,12,113,'1968-11-06','en','/ywxINymAsSGAJmPvDqMkdFY3PNH.jpg',2.3955089190463768,3,'2026-09-10',2,NULL,NULL),(39210,'在某处','Somewhere','约翰尼是好莱坞著名的“浪荡子”。他的各种负面新闻会迅速抢占各个报纸的八卦头条。这个浪荡子现在居住在好莱坞的一间酒店里，每天过着声色犬马的生活：天天开着自己的法拉利出去飙车，身边的美女如云，成天嗑药，似乎这样坐吃等死才是他活着的唯一目的。这种麻痹的生活让约翰尼如坠云雾，他也乐得享受这种状态。突然有一天，一个名叫克里奥的11岁小姑娘出现在他的面前。这个女孩是他一次在酒店里巫山云雨之后避孕失败的产物。这个不期而遇的人逼迫约翰尼不得不去面对自己的生活和过往。一个现实的问题摆在他的面前：到底应该怎么才能和一个11岁的女儿相处？',NULL,8000000,0,9.590373,6,208,98,'2010-09-03','en','/zOf1sdfF4eH3CVRCpmRO5ugVGdo.jpg',3.0082580810491213,3,'2026-09-10',2,NULL,NULL),(39254,'铁甲钢拳','Real Steel','在不远的未来2020年，观众不再满足于传统拳击肉搏，取而代之是更具官能刺激的机械人拳击。过气拳手查理生活潦倒，只能靠带着次货机械人参加黑市拳赛维生，同一时间多年不见的11岁儿子麦克斯又突然出现，更令他苦恼不堪。一次意外，麦克斯偶然从垃圾堆中检回一个残破机械人亚当，决心把他改造训练再上擂台，麦克斯的努力感染了查理，父子同心作战竟令被人看扁的亚当创造了一次又一次的奇迹，更打入冠军联赛与不败神话宙斯大帝一决高下。强弱悬殊下，亚当一直处于挨打劣势，查理父子档最后能否扭转局面？','If you get one shot, make it real.',110000000,299268508,37.195046,6.6,2692,127,'2011-09-28','en','/4GIeI5K5YdDUkR3mNQBoScpSFEf.jpg',3.7489398142680326,3,'2026-09-10',2,NULL,NULL),(39269,'走出忧郁','Out of the Blue','一个父亲是前罪犯，母亲是瘾君子的年轻女孩发现很难顺从，并试图在猫王和朋克场景的古怪组合中找到安慰。','A harrowing drama from the director of Easy Rider',0,0,0.679351,6.5,17,94,'1980-05-01','en','/rEWfWQDbx2upk9CAPRDDjCjc9a8.jpg',2.4656208237000037,3,'2026-09-10',2,NULL,NULL),(39303,'2:13','2:13','A police profiler has just returned from psychiatric leave only to find that he is caught up in a serial killer\'s rampage. Fighting to keep buried the trauma of his childhood, he must confront the all too-familiar flesh masks that the killer leaves on the faces of his victims. He must face his own demons along with the killer to save his small eroding existence.','Killers Are Not Born ... They Are Made',3500000,0,1.271621,4.6,10,96,'2009-04-25','en','/duqvQOzzjJ4W3yjZIjE10KM8dFw.jpg',2.351238131382345,3,'2026-09-10',2,NULL,NULL),(39349,'义胆情深','Sugar Hill','Sugar Hill is a 1994 American crime-drama/neo-noir film starring Wesley Snipes and Michael Wright as brothers Roemello and Raynathan Skuggs. The film focuses on the two brothers, who are major drug dealers in the Harlem neighborhood of New York City.','He wanted power. He wanted revenge. Now he just wants out.',0,0,2.580808,5.2,13,123,'1994-02-25','en','/6bnYhhJS7vuDMRPVSplWaXdK49g.jpg',2.407941064855847,3,'2026-09-10',2,NULL,NULL),(39437,'真爱','Beloved','故事发生于1873年，赛斯（奥普拉·温弗里 Oprah Winfrey 饰）曾是一名黑人奴隶，遭受过种种非人的待遇，为了不使自己的女儿重复自己悲惨的道路，她毅然杀死了刚刚出生的大女儿。一晃眼十八年过去了，每一个黑奴都没有料到，奴隶制度竟然遭到了全盘的推翻，如今的他们成为了自由人。\r 带着二女儿丹佛（金伯莉·伊丽丝 Kimberly Elise 饰），赛斯定居辛辛那提，和她的朋友保罗（丹尼·格洛弗 Danny Glover 饰）住在种植园中。一天，一个名为宠儿（桑迪·牛顿 Thandie Newton 饰）的陌生女孩敲响了赛斯家的大门，她行文怪异口齿不清，赛斯收留了这个女孩，之后种种怪事接二连三的发生在她的身边。','The past has a life of its own.',0,0,1.453765,5.9,26,172,'1998-10-16','en','/jIoT0J2fNXXCYZst6OkKStQIPw9.jpg',2.5505868148188604,3,'2026-09-10',2,NULL,NULL),(39451,'拜见岳父大人3','Little Fockers','这次的故事发生在10年后，格雷格·福克（本·斯蒂勒饰）在经历了岳父大人杰克·伯恩斯（罗伯特·德尼罗饰）的一系列“斗法”后，终于获得认可，也过上了幸福的小日子，两个孩子也相继出生成长。为了改善生活，格雷格还在一家药品公司找了一份兼职工作，哪里想到这让他岳父担心自己的孙子是否能受到好的照顾，于是以照看孙子为名，他重新回到了格雷格的生活。而同时，帕梅拉（泰瑞·波罗饰）的前男友凯文（欧文·威尔逊饰）也突然出现，格雷格要一边忙着吃醋，一边忙着向多疑的岳父证明自己可以照料这个家庭，但是此时一起美女销售（杰西卡·阿尔芭饰）引发的“小药丸”危机让格雷格的生活更是一片大乱。在种种误解、猜疑和杰克的特工侦查之后，格雷格能够通过岳父的最终测试吗？','Kids bring everyone closer, right?',100000000,310650585,32.389353,5.4,1060,98,'2010-12-21','en','/1jQwKyOndCaCO4XN1oJH27Xk9WC.jpg',3.293915234313772,3,'2026-09-10',2,NULL,NULL),(39486,'一代骄马','Secretariat','因为父亲的病重，家庭主妇彭妮·钱娜丽（戴安·琳恩饰）接管了父亲在弗吉尼亚州的马槛，对赛马一窍不通的她，赶鸭子上架的要开始经营马场，而她还要完成父亲的心愿，那就是让自己的赛马夺冠。面对重重困难，彭妮开始从零学起，她在马场里留意到了一匹名为\"勇敢统治者\"的纯种赛马，它是一头曾经红极一时的赛马，后来因伤而退出赛场，在农场务农，彭妮决定从这头赛马入手，开始自己的赛马之路。\r 　　彭妮邀请了老教练吕西安劳林（约翰·马尔科维奇饰）来进行培养和训练，最终，\"勇敢统治者\"所配种而产下的小马驹，赢得了赛马大赛的冠军，而彭妮也终于从一个对赛马一窍不通的人，成为了举世瞩目的赛马高手……','The Impossible True Story',35000000,60251371,9.525037,6.8,103,123,'2010-08-20','en','/aVZtb5aCrjOvdUcAnAXUWZnzSwn.jpg',2.8896029484243844,3,'2026-09-10',2,NULL,NULL),(39513,'Paul','Paul','For the past 60 years, a space-traveling smart-ass named Paul has been locked up in a top-secret military base, advising world leaders about his kind. But when he worries he’s outlived his usefulness and the dissection table is drawing uncomfortably close, Paul escapes on the first RV that passes by his compound in Area 51. Fortunately, it contains the two earthlings who are most likely to rescue and harbor an alien on the run.','Who\'s up for a close encounter?',40000000,97552050,43.151268,6.5,1789,104,'2011-02-14','en','/7ON50tA6pDFhjxyvGHVrlhfhjCF.jpg',3.641364386972176,3,'2026-09-10',2,NULL,NULL),(39514,'赤焰战场','RED','退休CIA探员法兰克原本过着单调乏味的养老生活，每天靠着用电话和联邦假释官莎拉闲聊来排遣无聊，这一切从三个职业杀手闯进他家意图夺命而彻底改变。运用所有昔日训练技巧脱困的法兰克逐渐发现，还会有更多的杀手接踵而至，而他们的目标除了他自己以外还包括所有和他有关连的人！于是法兰克立刻带着莎拉展开逃亡与追凶的惊险旅程，但更惊人的真相是当他发现追杀他的组织正是CIA当局中的神秘官员，忍无可忍的法兰克号召了昔日老搭档，组成一支老而弥坚的特种部队，准备与新世代特务杀手展开一场血肉横飞的城市激战…','Still armed. Still dangerous. Still got it.',58000000,71664962,41.430245,6.6,2808,111,'2010-10-13','en','/8eeK3OB5PeSRQD7BpZcGZKkehG.jpg',3.7687929445288537,3,'2026-09-10',2,NULL,NULL),(39538,'传染病','Contagion','贝丝·埃姆霍夫结束香港出差返回明尼阿波利斯后突然病倒，并在短短数日内死亡。很快，类似病例开始在世界各地接连出现，一种能够通过日常接触迅速传播的未知病毒引发全球疫情。随着感染人数不断攀升，美国疾控中心与世界卫生组织紧急展开调查，一边追查病毒的传播途径和起源，一边争分夺秒寻找控制疫情的方法。与此同时，恐慌、谣言与社会秩序的动荡也随疫情不断蔓延。在这场看不见敌人的全球危机中，科学家、医务人员和普通人都不得不面对前所未有的考验……','Nothing spreads like fear',60000000,137551594,38.820858,6.2,1325,106,'2011-09-08','en','/wgayMV2j6LexxqLaQgGhk2caJ7t.jpg',3.5006458492304033,3,'2026-09-10',2,NULL,NULL),(39541,'孩子梦天堂','Stolen Summer','1976年，芝加哥。','You saw the back-stabbing. Now see the final cut.',0,0,0.87066,6.4,9,91,'2002-03-22','en','/marKnaLfvEnQ1DK3U2SLKYRGVdh.jpg',2.3368233905903484,3,'2026-09-10',2,NULL,NULL),(39563,'The Eclipse','The Eclipse','Michael Farr (Hinds) is a widower living in a misty Irish seaside town who is struggling to adjust to his new role as the sole caretaker of his two children. Still reeling from the death of his wife, he has been plagued by terrifying apparitions. When he volunteers at a local literary festival, he finds himself drawn to Lena Morelle (Hjejle), an empathetic author of supernatural fiction (Hjelje). While Lena tries to help Michael with the mystery of his nightmarish visions, she must contend with problems of her own—she’s being jealously pursued by a self-obsessed novelist (Quinn), her one-time lover. As the three adults’ lives converge, the turbulence of the phantom world will soon have nothing on that of the living.','If there is life after death - love lives on',0,0,9.342465,6.1,15,88,'2009-04-24','en','/96ma6Hn8aW3FbHoaDzHiRflCHls.jpg',2.4571060889479654,3,'2026-09-10',2,NULL,NULL),(39691,'猫狗大战2：珍珠猫复仇','Cats & Dogs: The Revenge of Kitty Galore','本片为2001年在《猫狗大战》的续集。\r 故事发生在距离上一次猫咪和狗狗的大战已经过去了数年之后。来之不易的和平再一次受到威胁。这次的敌人可不是上一部中的笨蛋，它可是原猫咪间谍组织“喵”（MEOWS）的顶级特工，名为Kitty Galore。它顺利地窃取到了狗狗组织的核心机密，并且为了报复狗狗组织和人类，它设计了一个恐怖而毒辣的计划意图控制全世界！在面对这样一个迫在眉睫且前所未有的致命威胁的紧要关头，猫与狗在万不得已的情况下，只能被迫选择结成同盟——这还是这两种生物历史上的第一次，在这个由一只猫所制造的浩劫当中，它们需要拯救的不仅仅是自己，还有他们深爱着的人类。为了阻挠邪恶计划的征途，它们必须得将身体里潜藏的一切生物本能发挥到极致才行……','Just like real spies... only furrier.',85000000,112483764,11.77398,4.9,119,82,'2010-07-30','en','/u4BWBpdvvYc2B7L9bDnzITqQIah.jpg',2.8491831304333672,3,'2026-09-10',2,NULL,NULL),(39780,'奥斯卡与露辛达','Oscar and Lucinda','故事发生在19世纪的英格兰，青年奥斯卡（拉尔夫·费因斯 Ralph Fiennes 饰）是一位传教士，心怀远大理想的他踏上了前往澳洲内陆的旅途，准备在那里展开自己的事业，让更多的人承蒙主的恩赐。露辛迪亚（凯特·布兰切特 Cate Blanchett 饰）从小在富裕的家庭长大，衣食无忧的生活让她保留了美好的梦想和纯洁的心灵，在继承了父亲的玻璃厂之后，她决心将解放女性自立自强的态度发扬光大。  　　在漂泊在大海上的一艘轮船上，就是这样相似又迥异的两人，他们相遇了。好强又好胜的两人打了一个赌，赌局里奥斯卡必须建造一幢玻璃教堂并将它运往内陆山区，赌注是露辛迪亚的全部财产。而正是这个大胆又疯狂的赌局彻底改变了两人的命运。 ©豆瓣','They dared to play the game of love, faith, and chance.',0,0,0.139384,6.2,25,132,'1997-12-31','en','/9naDX3u4hsRM8jZ0Y7k5e2HAKmY.jpg',2.542457381310155,3,'2026-09-10',2,NULL,NULL),(39781,'孩子们都很好','The Kids Are All Right','两名通过人工授精孕育的孩子，将他们的生物学父亲带入了家庭生活。','Nic and Jules had the perfect family, until they met the man who made it all possible.',3500000,34705850,15.338211,6.5,506,106,'2010-07-09','en','/i32nNgtnsc3Pmshe96zcJ9jVBas.jpg',3.2689601154005894,3,'2026-09-10',2,NULL,NULL),(39800,'战争时期的生活','Life During Wartime','自从丈夫比尔被关进监狱后，崔西就希望能再找个男人。因为比尔是一个恋童癖患者，所以没有什么选择比哈维这个“正常”的父亲更让崔西更兴奋的了。可是当比尔从监狱里出来，崔西的两个孩子见到了自己未来的继父之后，这个家庭却陷入了烦恼之中——究竟是应该原谅自己的生父还是应该忘记自己的继父？有烦恼的并不是只有崔西一个人，她的妹妹乔伊是一个像天使一般纯洁的处女，可是她却陷在和以前恋人的爱情中无法自拔。艾伦离开了自己堕落的丈夫，辞掉了在新泽西的工作。来到乔伊身边，希望能和她携手走向未来。对自己性取向一头雾水的乔伊，莫名其妙地答应了艾伦的要求……',NULL,4500000,744816,3.108881,6.3,30,97,'2009-10-10','en','/qXCuzXPqd21orMT59JbGV01VRMT.jpg',2.588788237196629,3,'2026-09-10',2,NULL,NULL),(39806,'凯尤拉尼公主','Princess Ka\'iulani','凯乌拉尼是19世纪夏威夷公主，在英国长大，但决心维护她的人民不受侵略的美国商人的独立。凯乌拉尼是由她苏格兰父亲送到英国的小孩，后来回到夏威夷，成为一名政治活动家，她为保留自己的王位而奋斗，尽管她必须离开她的英国情人。','Her heart was torn between love and the future of Hawaii...',9000000,771499,0.717811,4.8,14,130,'2010-05-14','en','/6dsQxILe0AHmQoxhK8O9dXpLTYd.jpg',2.4160420870894237,3,'2026-09-10',2,NULL,NULL),(39833,'铁血柔情','Love Me Tender','《铁血柔情》是于1956年拍摄的一部黑白电影，由20世纪福克斯发行，为猫王参演的首部电影，与电影同名的主题曲也是他的代表曲目。','HEAR ELVIS SING . . .',1000000,9000000,1.444258,5.5,21,89,'1956-11-15','en','/4PdRIIrBN4q8H7f8yGbd0ScpTjh.jpg',2.5031428771484676,3,'2026-09-10',2,NULL,NULL),(39845,'爱情牧场','Love Ranch','格蕾丝（海伦·米伦 Helen Mirren 饰）和查理（乔·佩西 Joe Pesci 饰）是一对非常恩爱的夫妻，两人共同经营者他们独特的事业，那就是一家名为“爱情牧场”的合法妓院。格蕾丝是一个情商非常高的女人，能够妥善的处理各种复杂的人际关系和人情往来，任何看上去非常棘手的纠纷和问题，来到她的手上都能够被轻松的化解。而查理拥有一身非常结实的肌肉，一文一武的两人里应外合，配合的简直天衣无缝。\r 一天，一位名叫阿曼多（塞尔乔·佩里斯-曼切塔 Sergio Peris-Mencheta 饰）的拳击手来到了爱情牧场，年轻而又充满了性魅力的他深深地吸引了格蕾丝的注意，两人之间碰撞出了激情的火花。','When It Comes To Love... Everyone Pays A Price.',0,0,5.000126,6,21,117,'2010-06-30','en','/INezZQ0bkYMRHUl0AHX699NJak.jpg',2.5154683717067097,3,'2026-09-10',2,NULL,NULL),(39851,'清洁','Clean','艾米利（张曼玉 饰）曾经是一个音乐节目主持人，她的丈夫行为先锋不羁，是一个过气的摇滚歌星。他们都嗜毒，丈夫还因为吸毒过量而死。而艾米利则被搜出毒品而被判6个月监禁。因为夫妻一直过着不正常的生活，所以儿子被爷爷奶奶领走抚养，想给他一个清洁的成长环境。','When you don\'t have a choice, you change.',0,0,1.464566,6.7,17,111,'2004-09-01','en','/srenglG0ITLow4pR35IvJiAYuiX.jpg',2.4687827463224563,3,'2026-09-10',2,NULL,NULL),(39895,'从耳语到尖叫','From a Whisper to a Scream','因犯杀人罪被处决的大叔向记者奥德菲尔德讲述了在他故乡的4 个故事：一位老人爱上了一个年轻女人，甚至严重到进入坟墓之后......一名受伤的男子被一个蛮荒的隐士赋予了永恒的生命... 一个吃玻璃的戏班演员为寻找爱情而付出了最终的代价...内战的士兵是由一个家庭的孤儿与他们奇怪的意图而俘虏。','Welcome to Oldfield. Stop in for a night of pure terror.',1100000,1400000,1.220072,6.8,15,99,'1987-09-25','en','/h2UzUndAmuqJsluhCK7vZuVjyhu.jpg',2.4427900599849397,3,'2026-09-10',2,NULL,NULL),(39939,'超级骑警','Super Troopers','索尼、拉比特、马克和福斯特是几个驻扎在邻近加拿大边境地区的佛蒙特州巡警。他们每天的大部分时间就是在高速公路上作弄那些超速驾驶者，并用扣留下的跑车出去兜风。  平时他们全力支持慈父般的良师益友奥黑根上尉，并站在他这一边，避免与那位没有经验、倔强的罗德-法瓦警官接触。不幸的是，他们默默无闻的工作并未引起人们的注意：政府为了削减预算，已将他们那个地位低下的哨所列入了裁减。  这几个人试图改进他们的工作作风，但是要改变他们那种厚脸皮的做法并不是件容易的事，尤其是他们在与执法相面对的时候。看准时机的当地厄尔维莱警署正好想方设法尽全力关掉这个哨所。',NULL,3000000,18492362,16.312803,6.6,362,100,'2001-01-18','en','/yJyxPItcLNVfYr7idOphQTmQ9hK.jpg',3.1995385293274032,3,'2026-09-10',2,NULL,NULL),(40001,'麻雀变凤凰','Mrs. Winterbourne','单纯善良的女孩康妮（里琪·雷克 Ricki Lake 饰）动身前往纽约，希望能够在那里开始属于自己的全新的生活。在纽约，康妮结识了名为史蒂夫（劳恩·迪恩 Loren Dean 饰）的经纪人，在史蒂夫的花言巧语之下，康妮上了史蒂夫的当，开始了和他的同居生活。然而，当康妮告诉史蒂夫自己怀孕之后，史蒂夫残忍的抛弃了她。\r 　　再度变为孤身一人的康妮在火车上偶遇了温德邦太太（Susan Haskell 饰），两人交谈甚欢，温德邦太太甚至将自己的戒指脱下来给康妮试戴，然而，就在这个瞬间，火车发生了事故，温德邦夫妇两人双双遇难，而带着结识的康妮则被误认为是温德邦太太，被送往了温德邦家的豪宅之中。','The story of a girl who is going from filthy to rich',25000000,10070000,7.946769,5.3,25,105,'1996-04-19','en','/ppHqVo9uAFZYMvRm9x0XUtnyQPR.jpg',2.5513319621130197,3,'2026-09-10',2,NULL,NULL),(40160,'地球浩劫','Meteor','在与一颗彗星发生碰撞后，小行星“奥菲斯”上一块近8公里宽的碎片正朝地球飞来。如果撞击发生，将会引发一场毁灭性的灾难，人类可能会因此灭绝。为了阻止流星，美国宇航局想使用非法核武器卫星“大力神”，但很快就发现它的火力不足。他们唯一拯救世界的机会就是与苏联合作，苏联也发射了类似的非法卫星。但两国政府会同意合作吗？','There\'s No Place On Earth To Hide!',0,0,2.637355,5.1,36,107,'1979-10-19','en','/xMUuS1KFHRTFSf3PAY2tsbBdqkL.jpg',2.60960119096029,3,'2026-09-10',2,NULL,NULL),(40185,'Camping Sauvage','Camping Sauvage','Un camping au bord d\'un lac pendant les vacances d\'été. Camille, 17 ans, y traîne son ennui coincée entre ses parents et son petit ami. Elle rencontre Blaise, la quarantaine, tout juste embauché comme moniteur de voile. Camille et Blaise connaissent tous deux ce même mal de vivre qui les rapproche et les éloigne des autres. Mais leur complicité alimente la rumeur d\'une liaison qui exaspère leur entourage et déchaîne les passions. Ils se lancent alors à corps perdus dans une dangereuse histoire d\'amour...',NULL,0,0,0.20323,4.8,4,80,'2005-10-13','fr','/fklGo3i1Fwkt6xTk9mBCEnqzE0s.jpg',2.181581052898486,3,'2026-09-10',2,NULL,NULL),(40247,'请给予','Please Give','和所有生活在纽约这个大都市的居民一样，凯特（凯瑟琳·基纳 Catherine Keener 饰）很少能够有闲工夫静下来想一想自己的生活及处境，可是一旦开始思考，凯特发现自己的生活完全不如表面上那样的美好。\r 　　凯特从事着一份不能说的神秘职业，她低价收购二手商品，经过修缮后再将它们高价买到家具行，这份如履薄冰的职业让凯特随时有着被逮捕的危险。同时，凯特和丈夫之间的关系也渐渐的不再如从前般甜蜜美满。再加上那个让凯特头疼的拜金女儿，一时间凯特觉得自己从天堂坠入了地狱。凯特家的隔壁住着一个性格古怪的老太太安德拉（安·摩根·吉尔伯特 Ann Morgan Guilbert 饰），而这个故事就要从老太太之处开始说起。',NULL,3000000,0,5.325156,6,57,90,'2010-01-22','en','/kft7oy2SoImjDUXgeFbUxhICdc2.jpg',2.7252084419345204,3,'2026-09-10',2,NULL,NULL),(40264,'暮色大电影','Vampires Suck','17岁的少女贝卡（珍·普罗斯克 Jenn Proske 饰）随着父亲来到了一个无论怎么看都十分诡异的小镇上学，在这里，她和儿时的玩伴雅各布（克里斯·里吉 Chris Riggi 饰）重逢了，这个进入青春期的大男孩处处透露出一股奇怪的气息。在学校，打扮老土的她成为了同学们欺负的对象。这时，面色苍白瞳孔金黄的大帅哥爱德华（马特·兰特尔 Matt Lanter 饰）出现在了她的面前，两人一见钟情眉来眼去。欲火焚身的贝卡向爱德华求欢却惨遭拒绝，原来爱德华是吸血鬼，归属于庞大的库伦家族，一方面，爱德华对贝卡有着强烈的爱意，而另一方面，他还必须忍受着存在于他基因里的嗜血的欲望。  　　爱德华带贝卡去见自己的家人，聚会却被贝卡搅得一团糟。伤心的爱德华深知他只能带给贝卡带来灾难而忍痛提出分手，而雅各布在成为吉娃娃人之后也终于向贝卡袒露了自己的爱意，作为一个默默无闻的平凡少女，突然间被两大帅哥同时追求的她该做出怎样的选择？','Some sagas just won\'t die.',20000000,80547866,17.165039,4.2,315,82,'2010-08-18','en','/dr4oBOQvozxIDyep7Q0dyWAs0Bi.jpg',2.9496157471767677,3,'2026-09-10',2,NULL,NULL),(40428,'8号提案','8: The Mormon Proposition','影片讲述的是美国禁止同性婚姻的8号提案。在2009年，数千名同志被剥夺了公民的民事权利。于是摩门教开始了全国性的组织活动，并带头融资和带头作用，努力制止超过三十年的婚姻平等地位。','Equality for some.',0,0,0.424957,5.5,6,80,'2010-01-01','en','/glTnodgy1tZa794mnETfHjCPekC.jpg',2.255800662768255,3,'2026-09-10',2,NULL,NULL),(40494,'空中飞人','Trapeze','两个男人试图在他们的飞人表演中进行危险的“三重”动作。问题出现在另加入一个性感女表演者后，这个双人组变成了三人组。','High...High...High...Above Them All! - in excitement! - in spectacle! - in fire, flesh and fury!',4000000,14400000,1.379354,6.4,22,105,'1956-05-30','en','/3EZKz21OMvvyYg3UqZ3BBzHjWiq.jpg',2.5203246189014776,3,'2026-09-10',2,NULL,NULL),(40505,'我接了2号线','I Got the Hook-Up','Two broke buddies feel lucky when they come upon a truckload of cellular phones and begin selling them out of the back of their van. Trouble arises though, when the phones develop faults. The two friends then not only have to deal with unsatisfied customers but also the FBI.','A truckload of cell phones... turns into a boatload of cash!',0,0,0.593068,5.4,8,93,'1998-05-27','en','/u8kdtt80gFiqGKLTdQqdGWy9FfZ.jpg',2.309935960484574,3,'2026-09-10',2,NULL,NULL),(40652,'已婚女人','Une femme mariée: Suite de fragments d\'un film tourné en 1964','与儿子居住的再婚妇女夏洛特，与三个男人住在一起，但她又与地方剧团成员保持着性关系，最终她怀孕了，只是谁也不能断定这孩子的父亲是谁……','She Loves Two Men... She is Married to One!',120000,0,1.112792,7.1,20,95,'1964-12-04','fr','/i3KxuoQeuXxQeQuEj2twdEl2dhZ.jpg',2.5053495712093006,3,'2026-09-10',2,NULL,NULL),(40658,'Starsuckers','Starsuckers','Starsuckers is the most controversial documentary of the year, and was released in British cinemas in November 2009 to critical acclaim. It\'s a darkly humourous and shocking exposé of the celebrity obsessed media, that uncovers the real reasons behind our addiction to fame and blows the lid on the corporations and individuals who profit from it.',NULL,0,0,0.429083,6.2,5,103,'2009-09-30','en','/1z05uhHmSdXV8LGM8DPnBkf86DU.jpg',2.2240168533326563,3,'2026-09-10',2,NULL,NULL),(40688,'Meet the Deedles','Meet the Deedles','Two surfers end up as Yellowstone park rangers and have to stop a former ranger who is out for revenge.','Fish out of water...Surfers in Yellowstone',24000000,4562146,2.353441,4.1,19,93,'1998-03-27','en','/7hSCyqtYZ2ICMiV2rI5ZtZQTUnF.jpg',2.4743246989310808,3,'2026-09-10',2,NULL,NULL),(40769,'彼此欣赏','Mutual Appreciation','音乐人艾伦的乐队刚解散，他来到纽约发展自己初露头角的摇滚事业。他先是为一场已安排的演出寻找鼓手，其余时间则忙于自我推广的种种琐事。电台DJ萨拉看中了艾伦——这位温和却略显疏离的乐手，并主动为他找到了鼓手。闲暇时，艾伦与老友、研究生劳伦斯及其女友、记者艾莉一起喝酒、筹划未来。艾伦努力坚持着自己的事业，而艾莉却不由自主被他吸引。这份好感是相互的，但双方都犹豫着是否该向前一步。[Goodbye Cruel Releasing]',NULL,500000,0,0.123068,6.1,8,109,'2005-03-01','en','/yjKHIcFue6Et3qsBbxcVUrGjGRM.jpg',2.3111436627132838,3,'2026-09-10',2,NULL,NULL),(40794,'我行我素','Mine vaganti','托马索（Tommaso）是Cantones家族的最小儿子，Cantones家族自1960年代开始经营面食业务是意大利南部传统的大型家族。 在罗马旅行期间，他学习文学并与男友住在一起，汤玛索决定将自己的真实情况告诉父母。 但是，当他终于准备在全家人面前走出来时，他的哥哥安东尼奥（Antonio）毁了他的计划。',NULL,7000000,8220215,7.720692,7,118,110,'2010-02-12','it','/shEZkF19XczvFEEpbgfZvM1W9Rs.jpg',2.92630457337401,3,'2026-09-10',2,NULL,NULL),(40805,'青蜂侠','The Green Hornet','本片改编自著名的电视剧《青蜂侠》，影片的主角布利特·雷德是一个出版界的百万富翁，他白天西装革履地出现在自己的公司，晚上就带上面具化身为惩罚罪恶的超级英雄青蜂侠。知道他真实身份的除了他的助手“加藤”以外，就是美丽的女记者Lenore Case。而最近进入青蜂侠视野的是洛杉矶黑帮大佬“查德诺夫斯基”，他意图将洛杉矶所有的黑帮势力全部吞并，形成一个超级巨大的黑帮组织，彻底控制洛杉矶......','Breaking the Law to Protect It.',120000000,227817248,31.703608,5.5,1251,119,'2011-01-12','en','/AbhMUinCPjqO516Mq1k0FbBmLjB.jpg',3.3388513614821105,3,'2026-09-10',2,NULL,NULL),(40807,'抗癌的我','50/50','改编自电影编剧威尔瑞瑟尔Will Reiser本人真实经历，以幽默逗趣的剧情带出令人为之动容的生命启发！　 　　25岁的亚当是个电台节目企划，某天，他被检查出罹患癌症，这给了他极大的打击。然而在他的风趣好友凯尔、对他呵护有加的母亲以及一位年轻医师凯蒂的陪伴与支持下，亚当逐渐体认到自己生命中最重要的事物，也决定绝不让这场病轻易地毁了他的人生。','It takes a pair to beat the odds.',8000000,39187783,33.372828,7,1261,100,'2011-09-30','en','/eax48jEZ39HitBDqMYi0Inoa1lC.jpg',3.629284144701263,3,'2026-09-10',2,NULL,NULL),(40862,'Iraq for Sale: The War Profiteers','Iraq for Sale: The War Profiteers','Documentary portraying the actions of U.S. corporate contractors in the U.S.-Iraq war. Interviews with employees and former employees of such companies as Halliburton, CACI, and KBR suggest that government cronyism is behind apparent \"sweetheart\" deals that give such contractors enormous freedom to profit from supplying support and material to American troops while providing little oversight. Survivors of employees who were killed discuss the claim that the companies cared more for profit than for the welfare of their own workers, and soldiers indicate that the quality of services provided is sub-standard and severely in contradiction to the comparatively huge profits being generated. Also depicted are the unsuccessful attempts by the filmmakers to get company spokesmen to respond to the charges made by the interviewees.',NULL,0,0,1.517771,8,6,75,'2006-01-01','en','/nIAgVj3KtdJiyFRUmUFdGAMxcRE.jpg',2.2644240625309298,3,'2026-09-10',2,NULL,NULL),(40880,'Pandaemonium','Pandaemonium','Set in England during the early 19th century, Pandaemonium evokes late-1960s America in its depiction of the relationship between Samuel Taylor Coleridge (Linus Roach) and William Wordsworth (John Hannah). Instead of going to Vietnam, Wordsworth goes off to fight against the French while Coleridge stays at home and promotes utopianism. After the war, the poets live and work together with Coleridge\'s wife, Sara (Samantha Morton), and Wordsworth\'s sister, Dorothy (Emily Woof). At first this communal arrangement works to the advantage of Coleridge--who does some of his best writing while Wordsworth stagnates--until Coleridge becomes addicted to opium. Wordsworth, meanwhile, doesn\'t find his voice until he abandons his friend. In 20th-century vernacular, Wordsworth is the yuppie, Coleridge the hippie.',NULL,0,0,0.165367,4.5,2,124,'2001-06-29','en','/dO7wct6RAdDKEaQrA9IYD4BsKJL.jpg',2.0713960932154882,3,'2026-09-10',2,NULL,NULL),(40914,'皇家猎杀','Royal Kill','一个女刺客被送到美国，她的刺杀目标是最后一个活着的喜马拉雅王国王位继承人。',NULL,0,0,1.088501,2.8,6,90,'2009-04-10','en','/bfvSyXcyyBoXKsquUSXrMYtvDX5.jpg',2.2506989544955336,3,'2026-09-10',2,NULL,NULL),(40920,'花式舞事业','The Business of Fancydancing','Seymour Polatkin is a successful, gay Indian poet from Spokane who confronts his past when he returns to his childhood home on the reservation to attend the funeral of a dear friend.','Sometimes going home is the hardest journey of all.',200000,0,0.06104,8,2,103,'2002-01-14','en','/9QjlmxgwN9kVsEjbNNm2NkzLvuz.jpg',2.0740328071577028,3,'2026-09-10',2,NULL,NULL),(40932,'停不了的音乐','Can\'t Stop the Music','一部松散的传记，讲述了创新的迪斯科热门歌手——村民和他们的作曲家雅克·莫拉里。','The Musical Comedy Smash of the 80\'s!',0,0,6.574285,4.9,9,124,'1980-06-20','en','/j4Qu0WPS04bYOLwV3d9vSSsvYQb.jpg',2.3443595485721254,3,'2026-09-10',2,NULL,NULL),(40963,'Little Big Top','Little Big Top','An aging out of work clown returns to his small hometown, resigned to spend the rest of his days in a drunken stupor. But when his passion for clowning is reawakened by the local amateur circus he finds his smile.',NULL,0,0,0.0921,10,1,0,'2006-01-01','en','/kLyiTbf0lRSZrISYMN67VuapRyP.jpg',1.9861065636097304,3,'2026-09-10',2,NULL,NULL),(41009,'Perrier’s Bounty','Perrier’s Bounty','迈克尔（希里安•墨菲 Cillian Murphy 饰）是一个不学无术，整天游手好闲的青年，他欠了达伦（布莱丹•格里森 Brendan Gleeson 饰）一大笔钱无力偿还，糟糕的是，达伦是当地最臭名昭著的黑帮头头。布兰达（茱蒂•惠特克 Jodie Whittaker 饰）是迈克尔的朋友，在一场意外中，她误杀了达伦手下的一个小喽啰，巧合的是，迈克尔的父亲吉姆（吉姆•布劳德本特 Jim Broadbent 饰）刚好出现在凶杀现场，成为了目击证人，三人为了躲避达伦的追杀不得不踏上了逃亡的旅途。\r 　　父亲难产而又固执的性格，布兰达脸上永远愁云惨淡的表情，接二连三的麻烦和意外简直要将迈克尔给逼疯。','Blood is thicker than water. Nothing is thicker than thieves.',0,0,3.810943,5.1,24,88,'2009-09-11','en','/rZnWNxcIFNaTdshmkaFkmFkpQsB.jpg',2.531767696363842,3,'2026-09-10',2,NULL,NULL),(41110,'我是爱','Io sono l\'amore','意大利米兰的瑞奇家族靠纺织业致富，在家长的寿宴上，爷爷将企业传给了儿子坦科雷德（加布里埃尔.费泽蒂 Gabriele Ferzetti 饰）和孙子爱德瓦多（弗拉维奥·帕伦蒂 Flavio Parenti 饰）。坦科雷德的俄国妻子艾玛（蒂尔达·斯维顿 Tilda Swinton 饰）酷爱烹饪。在结识了儿子爱德瓦多的厨师朋友安东尼奥（爱德瓦多·加布瑞尔利尼 Edoardo Gabbriellini 饰）之后，艾玛被安东尼奥高超的烹饪手艺所吸引，情不自禁坠入爱河。不仅如此，艾玛还必须隐瞒她偶然发现女儿伊丽莎白（阿尔芭·洛尔瓦彻Alba Rohrwacher 饰）是同性恋的事实。与此同时，家族的事业也在变迁，尽管爱德瓦多独力反对出售家族企业，却还是无法抵挡资本全球化大潮的冲击，并购势在必行。在探讨商务的晚宴上，一个意外打破了艾玛苦心枯守的表面平静，她的灵魂就要破茧而出……',NULL,0,0,5.355763,6.9,73,120,'2009-09-05','it','/sAZ5arxWaqqtvti5ML35dVwvw4e.jpg',2.802148248455107,3,'2026-09-10',2,NULL,NULL),(41144,'拯救生命','To Save a Life','杰克（兰迪·韦恩 Randy Wayne 饰）和罗杰（小罗伯特·拜利 Robert Bailey Jr. 饰）相识于同年时代，两人是感情十分要好的好友，如今，就读于同一所高中，他们的处境却截然相反。杰克开朗帅气，拥有众多朋友，罗杰却沉默寡言，处处受人排挤。无法忍受校园欺凌的罗杰最终选择了结束自己的生命，伴随着他的死，杰克心中某些重要的东西碎裂了。  　　在内疚和自责之中，杰克一直诘问着自己，为何在事态尚可挽回之时没能拉罗杰一把，这种自责逐渐变成了一种责任感，他决定帮助和罗杰有着相同遭遇的人们。可是，这种帮助说来简单做来困难，在无数次挫折和失败之后，杰克还能贯彻自己的梦想，不忘初心吗？','Some people are just dying to be heard.',0,0,0.05021,6.2,21,120,'2009-11-05','en','/xtJrFdGB5QyatbNgLGXy1BogYtP.jpg',2.5058430664291267,3,'2026-09-10',2,NULL,NULL),(41154,'黑衣人3','Men in Black 3','在上一集J重新召回K作为搭档之后，时间又过去了许多年，但是曾经被K捕获的外星人鲍里斯对地球的觊觎却一直没有停歇。知道机会来临，鲍里斯 成功从月球监狱越狱。为了向斩去自己一只手臂的K复仇，他取得了时空机，回到了1969年，干掉了当时还没有太多经验的K，因而使得K没能成功设置空间A网以保护地球。第二天一早，J就发现老搭档K人间蒸发了；在诸多麻烦误解之后，J终于了解到了K已经死了四十多年。但无论未来如何发展，K都和地球的命运有着千丝万缕的联系。而且这段时间里，鲍里斯成为了地球最大的威胁，甚至引发了外星人攻击地球。没有A网的保护，地球行将毁灭。而为了阻止鲍里斯的计划，J只有穿越回1969年，去拯救年轻版的K。','They are back... in time.',225000000,624026776,52.035179,6.2,4160,106,'2012-05-23','en','/90DdoEStzeObs96fsYf4GG544iN.jpg',3.7845507308172417,3,'2026-09-10',2,NULL,NULL),(41210,'换精计划','The Switch','辛格尔顿•凯西已经40岁了，她没有结婚，没有固定的男朋友，但是她喜欢孩子，她希望成为一个母亲。所以，凯西决定进行人工受精。虽然这个决定遭到了她最好的朋友沃利的反对，但是凯西依然决定要去找一个捐精者，她执意要怀孕。在现代医学的帮助下，凯西很快找到了合适的捐精人－－英俊潇洒的罗纳德。在找到精子的来源之后，凯西决定为自己开一个“受孕派对”。\r 虽然沃利对凯西一直有所牵挂，虽然他一直爱慕着凯西，但是这个有些神经质的男人已经错过了向凯西表白的最佳时刻，而凯西现在也仅仅只是把他当做自己的朋友，而不是情人，更不是结婚对象。以想象，在“受孕派对”上见到帅气的罗纳德之后，沃利有多么的失落。多喝了几杯之后，沃利进了厕所，阴差阳错之中，他失手倒掉了罗纳德捐献的精子。惊恐、无奈之下，他只好用自己的精子取代了罗纳德的精子。\r 7年之后，凯西带着自己的那个有点神经质、又有点早熟的儿子塞巴斯蒂安回到了纽约居住。她和沃利见面，让自己的孩子叫他沃利叔叔。沃利和萨巴斯蒂安不但外貌上很相似，就连小动作、小脾气都非常类似。看起来，沃利这回总有机会向凯西表白了－－她甚至都生了自己的孩子。可是，麻烦就在这里：罗纳德也出现在了凯西的生活中。\r 沃利最终能把凯西揽入怀中么？他能让塞巴斯蒂安叫自己爸爸么……','The most unexpected comedy ever conceived.',19000000,49830607,27.494037,5.9,583,101,'2010-05-11','en','/ncvWKbfnAJVP6I0j3SCjAOY1Wk9.jpg',3.25143596400066,3,'2026-09-10',2,NULL,NULL),(41216,'猫头鹰王国：守卫者传奇','Legend of the Guardians: The Owls of Ga\'Hoole','《猫头鹰王国：守卫者传奇》是近年因执导影片《300勇士》声名鹊起的导演扎克·斯奈德的首部动画作品。这部家庭梦幻历险片是根据凯瑟琳·拉斯基的畅销系列小说《猫头鹰王国》的头三本改编，以3D效果，呈现动物的瑰丽世界，号称“猫头鹰版魔戒”。\r 在茂密宁静的仓鸮森林，猫头鹰诺克图斯和妻儿们生活在一棵参天大树的枝干上。她的儿子索伦（吉姆·斯特吉斯 Jim Sturgess 配音）无比迷恋“守护者”的传说。据说很久以前，佩戴着钢喙的邪恶“纯种者”（草鸮）国王压迫猫头鹰子民，关键时刻守护者挺身而出，打败了国王及其爪牙，但失败者从未放弃复仇的念头。憧憬古老传说的索伦令哥哥库鲁德（瑞恩·科万腾 Ryan Kwanten 配音）颇为气恼，以致于被哥哥从树上推下。两只还没学会自由飞翔的小家伙跌落到危机四伏的地面，他们躲避各种猛兽的袭击，却无法避免成为邪恶猎手捕获的目标。兄弟俩连同其他种类的猫头鹰被抓到神秘的圣鸮学校，他们在这里接受严格的训练，学到不同的技能，而猫头鹰王国沉寂已久的战火即将再次点燃……','On his way to finding a legend...he will become one.',80000000,140073390,37.321848,6.5,703,97,'2010-07-10','en','/e0AKLiJpomHldj9snBzlIirfhbZ.jpg',3.3998956231352597,3,'2026-09-10',2,NULL,NULL),(41233,'舞出我人生3','Step Up 3D','电影依然讲述发生在纽约地下街舞圈的故事。一群年轻人，包括卢克（Rick Malambri）、娜塔莉（Sharni Vinson）以及纽约大学的新生莫斯（Adam G. Sevani）组成团队，为了高额奖金和世界上最好的街舞舞者一绝高下，而这次比赛也将永远改变他们的生活……','Two Worlds. One Dream.',30000000,159291809,25.060342,6.6,582,107,'2010-08-04','en','/wXFFtxK55KzubYt9LtwQ1nopEMG.jpg',3.338798883425786,3,'2026-09-10',2,NULL,NULL),(41248,'The Girl on the Train','La Fille du RER','The Girl on the Train is a 2009 French drama film directed by André Téchiné. Jeanne is a young woman, striking but otherwise without qualities. Her mother tries to get her a job in the office of a lawyer, Bleistein, her lover years ago. Jeanne fails the interview but falls into a relationship with Franck, a wrestler whose dreams and claims of being in a legitimate business partnership Jeanne is only too happy to believe. When Franck is arrested, he turns on Jeanne for her naivety; she\'s stung and seeks attention by making up a story of an attack on a train. Is there any way out for her?',NULL,0,0,2.351706,5.6,10,105,'2009-03-18','fr','/1dYAuTgdR8IR0YXU8S8BhlQm84G.jpg',2.357767929499477,3,'2026-09-10',2,NULL,NULL),(41283,'极速复仇','Faster','经历了长达十年常人难以想象的牢狱生活，绰号“司机”的男子重返自由。但是他并不想就此展开平静的日子，而是迅速向当年的仇人展开血腥复仇。十年前，司机和哥哥加里等人打劫银行，并凭借其出色的车技成功摆脱警察的追捕。然而他们却遭到另一伙人的暗算，现金被一抢而空，哥哥和伙伴们遭到杀害，司机也鬼门关前走上一遭。凭借手中的资料，司机逐一展开报复。与此同时，手法干练的杀手和即将退休的警察也紧随司机的脚步。三个人展开了一场极速的生死追逐战……','Slow Justice is no Justice',24000000,23081726,26.324874,6.1,568,98,'2010-11-23','en','/m4k3HU9cEeGWoIyqBbC5MoKEyKV.jpg',3.2698125492452377,3,'2026-09-10',2,NULL,NULL),(41317,'万里狂沙绝世情','Caravans','This epic adventure-drama based on James Michener\'s best-selling novel concerns a young American embassy official who is sent into the Middle-Eastern desert to find the missing daughter of a US Senator. The young woman has left her husband, a Colonel in the Shadom - she was his number two wife - and has opted for the lifestyle of a nomadic tribe. When the diplomat locates the girl he joins the caravan and attempts to persuade the girl to return.',NULL,0,0,0.633004,5.8,1,127,'1978-11-02','en','/bKX4NG5QMuyqDQTAcnpn83Tmokc.jpg',1.985614719509097,3,'2026-09-10',2,NULL,NULL),(41382,'彩票当头','Lottery Ticket','Kevin Carson is a young man living in the projects who has to survive a three-day weekend after his opportunistic neighbors find out he\'s holding a winning lottery ticket worth $370 million','Winning is Just the Beginning Surviving is Another Story',0,0,9.054803,5.6,54,99,'2010-08-20','en','/6Eg93S0cMHLMFkeunqpmMkzs10A.jpg',2.714033279084271,3,'2026-09-10',2,NULL,NULL),(41402,'Let Me In','Let Me In','A bullied young boy befriends a young female vampire who lives in secrecy with her guardian.  A remake of the movie “Let The Right One In” which was an adaptation of a book.','Innocence dies. Abby doesn\'t.',20000000,24145613,19.705311,6.7,641,116,'2010-10-01','en','/wYvUi86fvzJyNRJIf72eVTycJC8.jpg',3.365044266126005,3,'2026-09-10',2,NULL,NULL),(41436,'灵动：鬼影实录2','Paranormal Activity 2','单身父亲丹尼尔·雷（布赖恩·波兰德 Brian Boland 饰）与美丽的克里斯蒂（Sprague Grayden 饰）结为夫妇，并育有可爱的孩子亨特（William Juan Prieto 饰），连同丹尼尔的女儿艾丽（Molly Ephraim 饰），一家四口过着幸福快乐的生活。2006年的某一天，他们的房子被人闯入，东西翻得乱七八糟，却几乎没有丢失任何东西。此后不久，丹尼尔请人在房子的不同角落安装了摄像头。夜深人静，万籁俱寂，摄像头却记录下一幕幕令人难以置信的画面。　　雷家的奇怪事件层出不穷，且愈演愈烈，连一向不迷信的丹尼尔也变得深为惶恐。最令他们担忧的是，一切似乎全部指向了那个刚刚1岁多的孩子——亨特。夜晚变得可怕而漫长……','In 2009 you demanded it. Nothing can prepare you for what\'s next.',3000000,177512032,22.789649,5.7,722,91,'2010-10-20','en','/ahFKYvkArWgKcyOCkYgzrHnNljF.jpg',3.2537907743191177,3,'2026-09-10',2,NULL,NULL),(41439,'电锯惊魂7','Saw 3D','大都会，人来人往的广场，行色匆匆的路人。伴随着此起彼落的吸气声，有人摸出手机，有人掏出照相机，一间透明玻璃房子被里三层外三层围了个水泄不通。玻璃房子的空间不大，里面架着一台用电锯制成的古怪器具。被链子拷在它两端的，是两个似乎毫无知觉的大老爷们儿。“我想和你们玩个游戏。”一个熟悉的声音幽幽响起。面面相觑的人群很快会发现，光天化日众目睽睽之下，残杀即将发生，这一切并不是动物园看马戏……','The Traps Come Alive',20000000,136150434,36.133536,5.8,730,90,'2010-10-21','en','/gZ8TuqNDnsDILoUTPbDNTjDsTyr.jpg',3.301335521590843,3,'2026-09-10',2,NULL,NULL),(41446,'惊声尖叫4','Scream 4','继震惊全国的威兹堡命案发生已经过去10个年头了，当年的幸存者悉妮·普利斯科特（内维·坎贝尔 Neve Campbell 饰）经历了常人无法想象的痛苦与磨难，如今终于从过去的阴影走出。她将那段不堪回首的往事写成书，其经历也被拍成系列电影，一时间红遍全国。在全国签售的最后一站，悉妮来到故乡威兹堡。然而厄运似乎如影随形，前一晚两名妙龄女孩在家中即遭鬼脸杀手杀害，悉妮的车厢内更发现了带血的刀子。警长戴维（David Arquette 饰）对此高度关注，与妻子盖尔（Courteney Cox 饰）各自积极追查真凶。　　与此同时，悉妮的表妹吉尔（Emma Roberts 饰）和朋友们也受到陌生人的死亡来电。新一轮的屠杀就此展开，血雨腥风在所难免……','New Decade. New Rules.',40000000,97138686,35.21926,6.1,902,111,'2011-04-11','en','/uRlLLxXn2VvN3q9jaYUTxp6Q006.jpg',3.38998145878678,3,'2026-09-10',2,NULL,NULL),(41469,'缘来就是你','Next Stop Wonderland','爱伦是夜班护士，刚与男友分手；她的母亲遂替她登了徵婚启事，结果反应热烈，但在一连串口不对心的约会后，她对男人更加失去信心。在水族馆打工的艾伦是半工读的进取男人，正当他要接纳向他展开追求的风骚女同学，竟发现她已搭上他们的教授。艾伦和爱伦在屡战屡败的爱情路上流连，终于偶然相遇，这次的缘份能让他们共度一生吗？','Romance Is Her Destination.',0,0,1.334481,6,20,96,'1998-08-21','en','/cygwoUJ1LqXkYT451E7W3dHtfHZ.jpg',2.497037496977675,3,'2026-09-10',2,NULL,NULL),(41479,'模范家庭','The Joneses','在小镇居民的心目中，由史蒂夫（大卫·杜楚尼 David Duchovny 饰）和凯特（黛咪·摩尔 Demi Moore 饰）组成的琼斯家堪称模范家庭的典范。史蒂夫温文尔雅，做着一份收入颇丰的工作，却还有足够的时间来满足自己的兴趣；凯特漂亮端庄，无论是穿着还是行为，无疑都引领着整个小镇的时尚。每个人都希望能够成为琼斯先生和琼斯太太，每个人又都绝望的发现，无论自己如何的向他们靠拢，都永远无法赶上他们奔向幸福的脚步。  　　然而，对于史蒂夫和凯特来说，生活又是另一番模样，关于这个家庭的秘密让两人永远都无法心安理得的享受生活的美好，同时，充沛的物质条件无法弥补情感上的苍白裂缝，这个外人眼中的模范家庭已然濒临崩溃。','They\'re not just living the American dream, they\'re selling it.',10000000,7022728,14.979375,6.1,210,96,'2009-09-13','en','/5YINGouZK9pmPdMPAHv158eQf3o.jpg',3.029293038825581,3,'2026-09-10',2,NULL,NULL),(41488,'屠杀报告','The Statement','1992年，法国，已经70岁的皮埃尔在天主教会的帮助下，躲藏了近50年。现在他正躲在普罗斯旺地区的一间修道院里，过着隐姓埋名的生活。然而想杀死皮埃尔的人却并未停止对他的追杀，一次皮埃尔偶然在一个前来杀他的杀手那里发现了一份报告，原来皮埃尔这些年的行踪早已被法国政府所掌握，而且已经被列为军方消灭的对象，新上任的陆军军官鲁克斯就是负责追杀他的人。惊慌的皮埃尔马上离开修道院踏上了逃亡之路，然而他不知道的是，此时追杀他的人还有纳粹猎人安玛丽·丽维。而鲁克斯与安玛丽也在追踪皮埃尔的过程中，发现了当年的事情真相，这其中似乎隐藏着一个更大的阴谋。皮埃尔在朋友和前妻的帮助下一次次从鲁克斯与安玛丽手中逃脱，十年过去了，越来越老的皮埃尔还能够顺利地逃生吗？对波洛萨德恨之入骨的犹太刺客组织正在追踪着他的行踪，并试图运用法律程序对他的罪行进行审判并把他关入监狱中。然而一个天主教牧师组成的秘密社团却将他隐匿在法国各个修道院中。这个被高度通缉的人就是皮埃尔·波洛萨德，他是二战中的纳粹党人，犯有战争罪。他不仅屠杀犹太人，更把他们的财产据为己有。但是，波洛萨德的罪行发生在40年前，他长时间的消声匿迹使得人们相信不再有人保护着他，甚至连他的妻子也这么认为。波洛萨德不断地从一个隐藏地逃跑到下一个，勉强摆脱众多的追击者。而他又不得不面对心脏病发作的危险……','At the end of World War II, many of those involved in war crimes were prosecuted. Some got away. Until now.',0,0,2.653988,5.9,23,120,'2003-12-12','en','/a7IvoBJ70dp6U1fjRlvB04ZtxvF.jpg',2.527997967187968,3,'2026-09-10',2,NULL,NULL),(41508,'Fateless','Sorstalanság','An Hungarian youth comes of age at Buchenwald during World War II. György Köves is 14, the son of a merchant who\'s sent to a forced labor camp. After his father\'s departure, György gets a job at a brickyard; his bus is stopped and its Jewish occupants sent to camps. There, György find camaraderie, suffering, cruelty, illness, and death. He hears advice on preserving one\'s dignity and self-esteem. He discovers hatred. If he does survive and returns to Budapest, what will he find? What is natural; what is it to be a Jew? Sepia, black and white, and color alternate to shade the mood.','You can close your eyes. You can turn away. But you will never forget.',0,0,1.906807,6.5,28,140,'2005-02-10','hu','/zBxyqGxRSKzCNNg1kUHu2jTD9Ze.jpg',2.5736388137865718,3,'2026-09-10',2,NULL,NULL),(41513,'蓝精灵','The Smurfs','邪恶的格格巫突然闯进精灵村庄，受惊的蓝精灵慌失失走避，误闯神秘石洞，在奇异的蓝月亮照耀下竟然穿越结界来到纽约中央公园！一众蓝精灵人生路不熟，只好寄居在一对年轻夫妇家中，他们开朗活泼反应快，搞到屋主晕头转向又无计可施；精灵们首要的任务就是避开格格巫的追捕返回精灵村庄。到底蓝爸爸同蓝妹妹、笨笨、聪聪、厌厌以及勇勇（新角色）能否顺利返家乡呢？','Smurf Happens.',110000000,563749323,36.65422,5.5,1179,103,'2011-07-29','en','/80sQoBft5bRFRh8K7jIv5IxdpKb.jpg',3.3398512826943465,3,'2026-09-10',2,NULL,NULL),(41515,'瑜伽熊','Yogi Bear','华纳兄弟将把Hanna-Barbera公司创造的电视动画明星“瑜珈熊”（Yogi Bear）搬上大银幕，《冲浪企鹅》（Surf\'s Up）的编导之一Ash Brannon将有望执导。　　这部电影版《瑜珈熊》会和去年底的《艾尔文和花栗鼠》（Alvin and the Chipmunks）一样采取真人加动画的制作方式：瑜珈熊和他的朋友Boo Boo将会由CG动画制作，其他部分采用真人实景。故事仍旧以瑜珈熊和Boo Boo恶作剧以及躲避他们的对头——Jellystone公园看守人史密斯（Ranger Smith）为主。　　为福克斯创作新片《牙仙》（Tooth Fairy）剧本的Joshua Sternin和Jeffrey Ventimilia将担任编剧。','Life\'s a Pic-A-Nic',80000000,201584141,11.187696,5.2,220,80,'2010-12-11','en','/3K7ARxwWRynfoLDs6x94s340BBW.jpg',2.9680262560401296,3,'2026-09-10',2,NULL,NULL),(41630,'爱情无线牵','No Strings Attached','在亚当（阿什顿•库奇 Ashton Kutcher 饰）的成长经历中，艾玛（娜塔丽•波特曼 Natalie Portman 饰）总是时不时的出现，所以两个人可以算是朋友。一次，亚当探望自己明星父亲时发现，父亲居然和自己的前女友同居了，这让亚当无论如何也不能接受，在遭遇情感的重创之后，亚当决定要随便找一个女性朋友上床发泻抑郁。宿醉的亚当醒来之后，发现自己居然裸着身体在艾玛家里，在达成“只谈性不谈爱”的协议之后，两人便开始时不时的幽会。随着时间的推移，亚当发现自己似乎对身边这个特立独行的女孩动了心，但是艾玛却表示不能接受亚当的爱意，所以他们最终决定结束这种关系。但是，分手之后二人才发现，他们早已习惯了彼此……','Friendship has its benefits.',25000000,147780440,38.688822,6.1,1331,107,'2011-01-21','en','/7GOjOLFESpJlYRA3IwGVse1FS4F.jpg',3.481962842945421,3,'2026-09-10',2,NULL,NULL),(41730,'酷男痞女电到你','Desert Blue','一个痴迷于“路边景点”的学者和他的电视明星女儿终于发现了世界上最大的冰淇淋甜筒，这是一个淘金热古城努力保持在地图上的中心。他们最终停留的时间比预期的要长，因为一场事故将一种不知名的可乐成分洒在了高速公路上。他们在接下来的几天里与镇上的各种居民一起度过，其中包括一个喜欢炸毁东西的十几岁女孩和一个试图实现他父亲在沙漠中建造海滨度假胜地的梦想的男孩。','Once You Get There, You\'ll Never Want To Leave',0,0,1.116206,5.5,9,90,'1999-06-06','en','/m81tA5hmjJ4Xzp3Yxs0dcnl8B1q.jpg',2.3340890396373233,3,'2026-09-10',2,NULL,NULL),(41733,'预产期','Due Date','妻子莎拉（米歇尔·莫娜汉 Michelle Monaghan 饰）预产期只有5天的时间了，为了尽快赶到妻子身边，一起等待新生儿的降临，彼得·海曼（小罗伯特·唐尼 Robert Downey Jr. 饰）急匆匆地登上一架从亚特兰大起飞的飞机。然而，彼得本来很有把握的计划却因为偶然遇到了积极且很有抱负的演员伊桑·特莱布利（扎克·加利凡纳基斯 Zach Galifianakis 饰）而被全盘打乱，甚至还朝着愈加错误的方向不断地发展，迫使着彼得不得不走下飞机，与伊桑一起搭车从公路返家。他们即将展开的是一场几乎穿越了整个国家的公路之旅，中间不仅毁掉了很多辆汽车以及好不容易建立起来的不甚牢靠的友谊，彼得甚至就连最后的勇气，也全部都丧失殆尽了。','Leave Your Comfort Zone',65000000,211780824,43.865294,6.2,1685,95,'2010-11-04','en','/jXvqjOc6oiTsK3N5woACOaHpfhc.jpg',3.5657126522938243,3,'2026-09-10',2,NULL,NULL),(41823,'爵士风情','Mo\' Better Blues','丹泽尔．华盛顿饰演一名自我中心意识强烈的爵士喇叭手， 他对身边的每个人都希望能加以掌控，包括他生命中的两个女人在内。斯派克．李在他这部自导自演的作品中，透过男主角对爱情与事业的纠葛来探讨黑人艺术家的生存处境， 强调画面色彩和音乐感性的丰富感觉。导演的父亲比尔．李负责为本片配乐。',NULL,10000000,16153593,3.079862,6.3,47,129,'1990-08-03','en','/sEa6m5RjfrqfTzY1eHkC85shiUF.jpg',2.6848454489558513,3,'2026-09-10',2,NULL,NULL),(41830,'The Party\'s Over','The Party\'s Over','An American businessman visits London and is horrified to discover his nubile teenage daughter has become involved with a gang of thuggish \"beatniks\". Her involvement leads to wild parties, sex, death and necrophilia.',NULL,0,0,0.118324,6.1,6,94,'1965-04-22','en','/lpAlr22qHyXKcNNFDLasXBlGFuJ.jpg',2.2565707800656516,3,'2026-09-10',2,NULL,NULL),(41894,'血签名','Blood Done Sign My Name','本片基于1970年的真实故事改编。1970年5月11日，美国北卡罗来纳州牛津市发生了一起当地白人商人涉嫌杀害一名黑人越战老兵的事件，涉嫌谋杀的三名白人被当地法院判处无罪。由此引起了当地群众，尤其是黑人居民的和平抗议活动，抗议活动影响范围遍及全国。','No one changes the world alone.',0,0,0.397341,6,5,0,'2010-02-01','en','/lI71wTBxaqChXMIW8TyUWnqw1ED.jpg',2.2235353115781438,3,'2026-09-10',2,NULL,NULL),(42033,'反防御','DEFCON-4','Two men and a woman circle the globe in a satellite armed with a nuclear device. The third world war breaks out, and a few months later the satellite crashes. They survive the crash but one man gets killed by survivors and the other man gets caught. The woman stays by the remains of the the satellite but is soon caught by evil punks who have taken power.','The last defense. The last hope. The battle for the future of the world has begun.',0,0,0.319792,2.8,10,88,'1985-03-15','en','/qPQ8gUy228PrCkIFQlUVMppaD5.jpg',2.3417511580598465,3,'2026-09-10',2,NULL,NULL),(42057,'来生多美好','It\'s a Wonderful Afterlife','Indian mother Mrs Sethi\'s (Azmi) obsession with marrying off her daughter turns murderous. With jokes that routinely miss the mark and cringeworthy slapstick, this black comedy farce shouldn\'t work. Somehow, though, it does. (c) Empire Magazine','Finding the right man can be murder',0,0,1.259968,4.3,9,99,'2010-05-07','en','/uHXO6Fu4rWKmD2LLudXOeURWKDe.jpg',2.3300237852201984,3,'2026-09-10',2,NULL,NULL),(42109,'加布里埃拉','Gabriela','在一座由地方军阀把控的巴西沿海小镇上，加布里埃拉（Gabriela）成为了酒吧老板纳西布（Nacib）的厨师兼情人，并最终嫁给了他。本片改编自巴西著名作家若热·阿马多（Jorge Amado）的同名畅销小说。',NULL,0,0,0.557602,6,2,99,'1983-03-24','pt','/Ap0Vxi2AtXXsbYIPmpB2LCrVva7.jpg',2.0735241854291697,3,'2026-09-10',2,NULL,NULL),(42151,'罪恶之家','Down Terrace','因为一起神秘的犯罪事件和内奸出卖,比尔(罗伯特·希尔　饰)和卡尔(罗宾·希尔　饰)度过了一段监狱时光。在出狱后,两人怀着复仇之心,试图找出当年是谁把他们暴露给了警察?谁是那个叛徒?与此同时,他们的家族生意却面临更大危机,这个以“阳台之下”为据点的帮派已经濒临破产,而内部人员也相互争斗, 互不信任。他们能找到内奸,并重新恢复这个犯罪之家昔日的荣光吗?','You\'re only as good as the people you know.',31192,10000,1.330379,6.3,26,89,'2009-09-01','en','/2WMwkZ4Qmsi3X6WvfjvBsC1er6F.jpg',2.5544405473985576,3,'2026-09-10',2,NULL,NULL),(42188,'别让我走','Never Let Me Go','28岁的女子凯西（凯瑞·穆丽根 Carey Mulligan 饰）自幼生活在校风严谨的寄宿学校海尔森，汤米（查理·罗 Charlie Rowe 饰）和露丝（艾拉·彭内尔 Ella Purnell 饰）是她最重要的两个朋友。少男少女们在英国乡间那温暖阳光的沐浴下，度过了人生最青涩浪漫的时刻，也收获着真挚的友情。然而某天，少男少女们却从露西老师（莎莉·霍金斯 Sally Hawkins 饰）的口中得到一个令人震惊的消息：海尔森的终极目标是将他们培养成器官捐献者，他们必须无私地奉献自己的一切，直到年轻的生命之花凋零。在18岁之际，他们得以走出海尔森，去往各地的寄宿学校。黯然的命运如影随形，在短暂的生命中他们还将经历更多……\r 　　本片根据英国日裔小说作家石黑一雄的同名原作改编，并荣获2010年英国独立电影节最佳女主角奖（Carey Mulligan）。','These students have everything they need. Except time.',15000000,9455232,30.983397,6.8,737,104,'2010-09-15','en','/bA8wtmUaqyLN9Ll4w1NDs1zaV4C.jpg',3.442294514568357,3,'2026-09-10',2,NULL,NULL),(42222,'茱莉亚','Julia','故事发生在二十世纪三十年代初期，莉莲（简·方达 Jane Fonda 饰）前往维也纳寻找自己曾经的好友茱莉亚（瓦妮莎·雷德格瑞夫 Vanessa Redgrave 饰），到达目的地之后，莉莲才知道，茱莉亚因为和法西斯支持者发生了激烈冲突而受伤住进了医院，之后不知所踪。  　　在莉莲回归自己的生活之后，她意外的收到了茱莉亚的来信，在信中，茱莉亚请求莉莲帮助自己投运五万美元给反纳粹组织，尽管这一举动在当时意味着巨大的危险，但是莉莲还是答应了茱莉亚，最终，两个多年未见的好友在柏林重逢。然而，没过多久，莉莲便受到了茱莉亚的死讯，在悲痛之中，莉莲明白，自己还有未完成的任务。','The story of two women whose friendship suddenly became a matter of life and death.',0,0,6.077735,6.3,30,117,'1977-10-02','en','/qHtPzs9eVCilp88c1arq73gH6xk.jpg',2.595569683952165,3,'2026-09-10',2,NULL,NULL),(42297,'滑稽戏','Burlesque','酷爱歌舞表演的女服务员艾丽（克里斯蒂娜•阿奎莱拉Christina Aguilera 饰）决定离开生活的小镇，奔赴洛杉矶追寻自己的明星之梦。然而这件事从一开始便并不那么容易，她不仅被人偷走了所有积累，而且只得到在日落大道的一家滑稽戏俱乐部作服务员的工作。因为没有钱付房租，她只好借住在极具创作天份的酒保杰克（凯姆•吉甘戴Cam Gigandet 饰）的家里。俱乐部老板苔丝（雪儿 Cher 饰）是一位面冷心热的女人，此时她正面临巨额债务和俱乐部被收购的窘境，在艾丽的多次请求下，苔丝最终决定给予她上台的机会，杰出的天份很快让艾丽很快在众多女演员中脱颖而出并成为整个俱乐部的头牌舞娘。俱乐部走到了生死存亡的关键时刻，此时小有名气的艾丽开始受到各种诱惑，在情感与名利的漩涡里，艾丽最终会做出何种决择，俱乐部将会面对什么样的命运……  　　本片集结了克里斯蒂娜•阿奎莱拉和雪儿两位歌坛天后，华丽的歌舞场面让人叹为观止。  　　【金球奖1项获奖】最佳歌曲“You Haven\'t Seen The Last of Me”  　　【另2项提名】最佳影片（音乐/喜剧类）、最佳歌曲“Bound to You” ©豆瓣','It takes a legend... to make a star',55000000,89519773,22.863516,6.9,573,119,'2010-11-23','en','/9lghKJkHqBPczeNGkcG4SWmrQgg.jpg',3.3694661240286994,3,'2026-09-10',2,NULL,NULL),(42345,'莫莉·马圭尔斯','The Molly Maguires','本片改编自真实事件，“莫利马贵”是一个以武力反抗矿主的秘密矿工团体，它的主要目的是反抗矿主对矿工们的剥削、协迫甚至是谋杀。为此，矿主秘密雇佣了一个侦探，他的任务是要赢得矿工们的信任，渗透在他们之中。\r 　　1876年，宾夕法尼亚州舒伊尔基尔县。一个由爱尔兰煤矿工人组成的秘密社团，以神圣的誓言为纽带，通过破坏采矿设施，向他们工作的贪婪无情的公司施加压力，希望改善他们的工作条件和家人的生活。',NULL,11000000,2200000,1.396985,5.9,16,124,'1970-01-27','en','/lyvUamPDT8kZzV4ItTxvxnDDGdu.jpg',2.450826963452013,3,'2026-09-10',2,NULL,NULL),(42497,'粉红水仙','Pink Narcissus','1971年的一部美国文艺片。尽管年代久远，但是这却被称为永恒的经典，整部电影从头到尾没有一个写实的镜头，虽然电影中有大量的 体镜头，但全是在虚幻的梦境之中，大片的红色或蓝，没有故事情节，像一部音乐录影带，电影截图仿佛是象征主义的绘画作品。','A unique experience in visual fantasy!',27000,0,0.027811,6,9,64,'1971-01-01','en','/kaZiiGE6820KyFF9XkzPB9Rx9qn.jpg',2.3334336125777844,3,'2026-09-10',2,NULL,NULL),(42586,'拂晓出击','Darling Lili','第一次世界大战期间，莉莉·史密斯是一位深受喜爱的英国音乐厅歌手，经常为英国和法国军队和普通民众演唱爱国歌曲提供灵感。她也是半个德国人，是一名德国卧底间谍，利用她的女性诡计从她引诱的高级军官和外交官那里收集信息。','She gave away secrets to one side and her heart to the other.',0,0,0.816883,4.9,8,107,'1970-01-01','en','/ugypriAtGu3LdUrp5bLkeIcg5Jf.jpg',2.308817716047064,3,'2026-09-10',2,NULL,NULL),(42618,'生命的旋律','Sweet Charity','描述由奥斯卡影后莎莉麦克琳饰演的风尘女郎，即使屡次遇人不淑，依然对浪漫的爱情抱持梦想。鲍伯佛西惊人的歌舞编排、舞者高难度的表演，不仅将通俗的故事展露新貌，更是日后天王天后的MV和演唱会的参考经典。','Love is what it\'s all about!',8000000,20000000,0.709143,6.5,15,149,'1969-01-01','en','/brwDwtckSCp2t4Hz3JU3vwCv83h.jpg',2.4398070911797745,3,'2026-09-10',2,NULL,NULL),(42684,'天际浩劫','Skyline','科学家史提芬霍金曾警告：“不要尝试接触外星人…否则人类可能会惨遭屠杀！”但国家似乎没有理会这位天才的忠告，更多次向外太空发放强劲讯号，试图得到外星生物的注意。终于，外星人的种族灭绝计划正式展开……在一场疯狂派对结束后，一 群年轻好友被窗外一道神秘诡异的强光从夜半熟睡中唤醒，就像飞蛾扑火般，他们发现人们自然地被强光吸引到户外，恐怖地消失在光晕之中，毫无理由地人间蒸发！很快地他们发现这个来自异次元的光束杀阵，已经垄罩整个地表，甚至即将吞噬地球上所有的人类！如今，这群世上最后的幸存伙伴，赶在已经进入倒数计时的地球末日前，要如何找出破解漫天杀机的求生密码？','Don\'t look up',10000000,66821036,26.268209,4.7,507,100,'2010-11-11','en','/1Q8HzB8T1yDxAm0IuNhSklYK6ck.jpg',3.072802784501771,3,'2026-09-10',2,NULL,NULL),(42807,'牛顿小子','The Newton Boys','一部美国史上最成功的亡命之徒真实故事。原来是穷困无名的四个小子，一起火车抢案使这群男孩蜕变成男人。这群小子用硝化油做炸弹连抢了80家银行，足迹遍及德州和加拿大。','Four Brothers. Four Criminals. For The Money... They Would Stop At Nothing.',27000000,76000000,3.123583,5.9,44,113,'1998-03-26','en','/v3VuDClmFZNjfI6YLTkeinae9HK.jpg',2.663890280434607,3,'2026-09-10',2,NULL,NULL),(42819,'终点之城','The City of Your Final Destination','28岁的博士生奥玛（奥玛尔·梅特瓦利 Omar Metwally 饰）决定撰写一本关于作家裘洛斯·关德的传记小说，他的前程和事业均紧紧的与这本小说相连着。据相关记载，裘洛斯早已经自杀身亡，他的哥哥亚当（安东尼·霍普金斯 Anthony Hopkins 饰）、妻子卡洛琳（劳拉·琳妮 Laura Linney 饰）和情妇雅登（夏洛特·甘斯布 Charlotte Gainsbourg 饰）是世界上仅存的同裘洛斯有关联的三人。\r 　　不知为何，这三人都回绝了奥玛希望得到小说授权的请求。在女友蒂德莉（亚历山德拉·玛丽亚·拉那 Alexandra Maria Lara 饰）的劝说下，不甘心的奥玛决定亲自前往他们位于乌拉圭的一处偏僻小镇的豪宅进行拜访。奥玛的到来打破了小镇上的宁静，一段尘封多年的往事就此渐渐浮出了水面。',NULL,0,0,1.353971,5.7,9,114,'2009-03-21','en','/2vQDkPdxKXOY4RtVDFalEclM33j.jpg',2.3353644142045664,3,'2026-09-10',2,NULL,NULL),(42888,'你怎么知道','How Do You Know','丽莎·约根森（瑞茜·威瑟斯彭 饰）是一位昔日的女运动员，她曾经在自己的领域首屈一指，而如今却陷入了一场三角恋爱的苦恼中。本来她与现在的棒球运动员曼尼（欧文·威尔逊 饰）情投意合，又同样是运动领域的情侣，有很多共同话题。但是，突然，一位事业上正深陷苦恼的白领高管乔治（保罗·路德 饰），对丽莎却心生爱意。于是，两个男人为了争夺丽莎的芳心，开始了一场激烈的争夺。在这场\"战争\"中，他们施展各自功夫，上演了一幕幕浪漫与啼笑皆非的场面，在这两个男人间，丽莎又该如何抉择？你怎知道呢？她又真正清楚吗？','How do you know it\'s love?',120000000,48668907,11.137655,4.9,223,121,'2010-12-17','en','/jbOnp79eUZxQHgcdnTIRlxel1dE.jpg',2.949082241600123,3,'2026-09-10',2,NULL,NULL),(42889,'失贞','The Virginity Hit','摄像机是人类社会的一大发明，它能事无巨细、没有偏颇地记录下来发生在它面前的一切。这种原始而现实的影像就叫做“纪录片”。现在网络上最流行、点击率最高的的“纪录片”就是“自拍”。而自拍往往和色*情以及欲望相关。四个青涩的少年，一台老旧但是还能运转的摄像机。他们通过自己的亲身经历和一些令人目瞪口呆的体验，完整、原始、甚至有几分令人不可思议地记录下来了自己是如何进行下半身的体验的。但是这四个好朋友中的一个，却还是一个处男，因为自己的这种“不合格”的身份，他经常被其他三个同伴嘲笑。不过嘲笑归嘲笑，他们还是团结在一起，要为这个处男电影下载朋友结束处男生涯－－同时，他们要用摄像机把这一切都“自拍”下来。不过，要有送出第一次，并不是一件容易的事情，尤其是他们在遭受了诸如自身利益受损、网络出错和一个艳星的突然出现等等问题。他们的这些做法，无非就是在讨论“第一次”到底是什么感觉，第一次为什么那么重要——不管是对男人还是对女人而言。',NULL,2000000,563706,3.125382,4.6,19,120,'2010-09-10','en','/krUYZAjEZ5n5GL7tuLoQGfxja0S.jpg',2.4799010282622134,3,'2026-09-10',2,NULL,NULL),(43074,'超能敢死队','Ghostbusters','哥伦毕业大学教授Erin Gilbert 和Abby Yates 是合作愉快的作家。如今，为了告诉人们“幽灵是存在的”，她们将一起编著一本关于幽灵的书籍。当对“鬼魂”的深入研究中，当“鬼魂”入侵她们所居住的城市时，她们和另外两个搭档Jillian Holtzmann、Patty Tolan一起投入到拯救城市、拯救世界的行动中……','Who You Gonna Call?',144000000,229147509,66.21806,5.3,2142,116,'2016-07-14','en','/hTuqVvOBTjj5v2Rul16QZjtiq4r.jpg',3.46863092810239,3,'2026-09-10',2,NULL,NULL),(43090,'无枪侠','Gunless','影片是一部加拿大西部片。讲述一个美国蒙大拿枪手小子来到加拿大的小镇时，发现这里没有人能理解和欣赏美国西部的硬汉精神....','Fastest draw in the North... kinda.',10000000,0,3.753703,6.7,27,89,'2010-04-30','en','/8Y4pBlpDZzzDYCJlsrhgwmFNYM8.jpg',2.5722338290717337,3,'2026-09-10',2,NULL,NULL),(43213,'最后的决战','Chicago Overcoat','一个年迈的杀手和一个潦倒的警探的命运纠缠在一起，因为最后一次工作导致了最后一次清算旧账的机会。','The glory days are back',3200000,0,1.034844,6.1,5,95,'2009-10-10','en','/6saeAm5xt4vVM632Hxw3tV0tRsJ.jpg',2.225196012269913,3,'2026-09-10',2,NULL,NULL),(43266,'青山翠谷','How Green Was My Valley','世纪之交的威尔士采矿村庄里，摩根一家父严母慈，养育了当矿工的儿子们，同时期盼他们的小儿子能找到更美好的生活。','Millions Have Read This Great Novel... Millions more will see an even greater picture!',1250000,6000000,7.70019,6.8,72,118,'1941-10-28','en','/8N7OmxBqjRVUrqergUduGgr6exy.jpg',2.8015821707690565,3,'2026-09-10',2,NULL,NULL),(43306,'祖儿小子','A Guy Named Joe','影片描写了二战期间，一群以皮特Sandidge为代表的英国B-52轰炸机飞行员们的战斗、爱情生活...','A GUY - A GAL - A PAL - It\'s Swell!',2627000,5363000,0.531444,6,8,120,'1944-03-01','en','/rrdaUol9hZEde4HloyVuG860OH7.jpg',2.3117505774705824,3,'2026-09-10',2,NULL,NULL),(43347,'爱情与灵药','Love & Other Drugs','杰米（杰克•吉伦哈尔 Jake Gyllenhaal 饰）出身医药世家，舌灿莲花，热情似火，是电器行的金牌销售，不过由于桃花运太壮，以至于因为跟女同事在工作时间亲热，被老板开除。此后，他在辉瑞公司连番洗脑后，成为了一名医药销售代表。为了能打开区域市场，他摸清了某医院的底细，决定从主治医师斯坦下手。他用1千美元的支票，换取了一个实习生的身份，穿梭于诊室。某日，他偶然间邂逅了因帕金森症就诊的女患者玛姬（安妮•海瑟薇 Anne Hathaway 饰），并阴差阳错瞥见了她的乳房。正当花花公子以为占了便宜时，却被玛姬抡包打伤，甚至还拍了照片。为了讨回声誉，他利用关系要到了对方号码，并约她面谈。没想到这次约会，却让两人陷入了匪夷所思的亲密关系之中，令他难以自拔。正当杰米因伟哥成为销售红人时，玛姬的病患却每况愈下……','Addicted to one-night stands or dependent on one another?',30000000,102820008,20.236951,6.6,1233,112,'2010-11-22','en','/nShAAM76tUo7QNXFOwPp5TSz51g.jpg',3.5175808806443745,3,'2026-09-10',2,NULL,NULL),(43418,'Beneath Hill 60','Beneath Hill 60','The true story of Australia\'s cat-and-mouse underground mine warfare – one of the most misunderstood, misrepresented and mystifying conflicts of WW I. It was a secret struggle BENEATH the Western Front that combined daring engineering, technology and science, and few on the surface knew of the brave, claustrophobic and sometimes barbaric work of these tunnellers.','BENEATH HILL 60 featuring Captain Woodward MC commanding the Australian Hill 60 Tunnelers of World War 1',7347125,0,3.949796,7.3,40,122,'2010-04-15','en','/6cnmhZId23yPvc3bRZW7IT0CkDC.jpg',2.6677390347253533,3,'2026-09-10',2,NULL,NULL),(43434,'卡洛斯','Carlos','奥利维耶·阿萨亚斯执导的本片以史诗格局与精微细节，刻画了恶名昭彰的国际恐怖分子伊里奇·拉米雷斯·桑切斯——即“豺狼卡洛斯”——的一生。作为二十世纪最受通缉的逃犯之一，卡洛斯在七十年代至八十年代期间致力于激进的左翼行动，在欧洲与中东策划多起炸弹袭击、绑架与劫机事件。阿萨亚斯并未将他描绘为犯罪主谋，而是将其塑造成世界政治格局剧变的象征；魅力非凡的埃德加·拉米雷斯则以张扬恣肆的演绎，鲜活塑造出这位全球化的枭雄形象。标准收藏呈现的是经导演认可、完整未删减、长达五个半小时的版本。[标准收藏]','The man who hijacked the world',18000000,871279,1.138383,6.7,50,338,'2010-05-19','en','/ee6EiUOXdvr7DvnBBEG691TNSKh.jpg',2.701486542292929,3,'2026-09-10',2,NULL,NULL),(43539,'危情三日','The Next Three Days','原本幸福的三口之家突遭横祸：男主人公约翰 的妻子劳拉 被以“莫须有”的谋杀罪名逮捕，在被逮捕时，她对丈夫坚称自己是清白的。约翰深信妻子的无辜，团结着破碎的家庭，拼尽全力与这一神秘事件周旋到底。然而随着最后一次上诉的驳回，狱中的妻子绝望地试图自杀。为了拯救心爱的女人，约翰决定铤而走险、孤注一掷：精心策划一起越狱。','What if you had 72 hours to save everything you live for?',30000000,51148651,34.421696,6.9,905,133,'2010-11-18','en','/lQV7Aio8vvQOMc8Ea3IL0OnCOAh.jpg',3.521848477077482,3,'2026-09-10',2,NULL,NULL),(43546,'出水芙蓉','Bathing Beauty','流行音乐作曲家史蒂夫（Red Skelton）在加州与美丽多情的大学游泳课老师卡罗琳（Esther Williams）一见倾心，两人谈婚论嫁之际，遭到唱片公司高层的反对，他们怕影响到史蒂夫为“水上盛典”作曲，但史蒂夫无视阻挠。  　　史蒂夫的经纪人乔治雇用女演员玛丽娅假冒史蒂夫的妻子，后者带着三个假冒的孩子来到婚礼上大闹，卡罗琳一气之下出走，史蒂夫得知卡罗琳任教的学院虽是女子学院，但章程规定也招男生，于是报名入学，笑话自此层出不穷。','M.G.M\'s Mammoth Technicolor Musical Spectacle!',2361000,6892000,0.628051,7,4,101,'1944-07-01','en','/9vqXU1hFpyLkJK4Wvt3bfUVMbqI.jpg',2.186155865818604,3,'2026-09-10',2,NULL,NULL),(43593,'食人鱼3D','Piranha 3D','史前的一场火山爆发形成现在的哈瓦苏湖，当地球再次震动，让湖底裂出一条缝隙，也让隐藏了百万年的饥饿史前杀人鱼重见天日，它们是永不停止的杀人机器，尖牙利齿在分秒之间就可以将猎物撕成碎片。失踪人口越来越多，这让美丽好胜的码头经理茱莉发现这恐怖的事实，这个祥和小镇将面临一场大屠杀，却没人愿意相信，此时茱莉担任潜水教练的未婚夫也在水里失踪了，她和镇民们该如何面对这场屠杀？','There\'s something in the water.',24000000,83188165,23.343839,5.3,581,88,'2010-08-20','en','/bQ6DttxsHMvO4541SkTiKOQ0csF.jpg',3.161398486273747,3,'2026-09-10',2,NULL,NULL),(43595,'侬本多情','She Done Him Wrong','New York singer and nightclub owner Lady Lou has more men friends than you can imagine. Unfortunately one of them is a vicious criminal who\'s escaped and is on the way to see \"his\" girl, not realising she hasn\'t exactly been faithful in his absence. Help is at hand in the form of young Captain Cummings a local temperance league leader though.','Mae West gives a \'Hot Time\' to the nation!',200000,2200000,0.622752,5.1,27,66,'1933-02-09','en','/kwxAUj8tf9kO2ESAriD8foYN28q.jpg',2.5479263373702703,3,'2026-09-10',2,NULL,NULL),(43610,'空谷芳草','The Valley of Decision','故事发生在1873年的美国匹兹堡斯考特钢厂之中。玛丽（葛丽亚·嘉逊 Greer Garson 饰）跟姐姐和身患残疾的父亲帕特（莱昂纳尔·巴里摩尔 Lionel Barrymore 饰）一起过着相依为命的生活。因为家中赤贫，玛丽决定到当地的富豪斯考特先生家所举办的宴会上做女佣来补贴家用，在宴会上，玛丽有幸结识了斯考特家的大小姐康妮（玛莎·亨特 Marsha Hunt 饰）、二少爷威利（丹·德亚 Dan Duryea 饰）、三少爷泰德（马歇尔·汤普森 Marshall Thompson 饰）以及大少爷保罗（格利高里·派克 Gregory Peck 饰）。',NULL,2160000,9132000,0.1813,5.8,4,119,'1945-06-01','en','/kiHMWi0OWMIovdCnd4AbMEyQh3c.jpg',2.183169341444235,3,'2026-09-10',2,NULL,NULL),(43630,'The Helix... Loaded','The Helix... Loaded',NULL,NULL,0,0,0.0206,4.8,2,97,'2005-01-01','en','/yG81A3umqQ5Z4la0uA642A506s5.jpg',2.0713118469575384,3,'2026-09-10',2,NULL,NULL),(43653,'The Living Wake','The Living Wake','“The Living Wake” is a dark comedy set in a timeless storybook universe. Self-proclaimed artist and genius, K. Roth Binew, has one day to live. He has enlisted his best and only friend, Mills Joquin, to take him around on a bicycle powered rickshaw. In a final attempt to probe life’s deepest mysteries, Binew endures one ridiculous trial after the next. He concludes his day with a final performance, his living wake. On a makeshift stage in an open field, Binew’s friends and enemies gather to witness his madness one final time.',NULL,0,0,0.383442,5,1,91,'2007-01-01','en','/yYs01G2MrUMR9Up2kwww1OmGgWq.jpg',1.9847156469292413,3,'2026-09-10',2,NULL,NULL),(43743,'疑心生暗鬼','Fabled','约瑟夫是个典型的失败者，女朋友被他的心理医生翘了墙角，接着他的狗也丢了，约瑟夫怀疑是一个看他不顺眼的同事搞鬼，但是又没有证据……倒霉事接连发生，约瑟夫开始怀疑这一切的背后，是不是有一只看不到的手在操纵……','There once was a wolf named Lupold...',0,0,0.003352,0,0,84,'2002-01-01','en','/1klhTzYcWdTmnL8sPIMwCqV9SGP.jpg',1.8337900419487172,3,'2026-09-10',2,NULL,NULL),(43839,'亚历山大的爵士乐队','Alexander\'s Ragtime Band','Roger Grant, a classical violinist, disappoints his family and teacher when he organizes a jazz band, but he and the band become successful. Roger falls in love with his singer Stella, but his reluctance to lose her leads him to thwart her efforts to become a solo star. When the World War separates them in 1917, Stella marries Roger\'s best friend Charlie. Roger comes home after the war and an important concert at Carnegie Hall brings the corners of the romantic triangle together.','An American Cavalcade!',2000000,4000000,0.483974,4.8,6,106,'1938-05-24','en','/tbmvwfs9C1eTIyCcuhdbnFeuQSA.jpg',2.254219853898692,3,'2026-09-10',2,NULL,NULL),(43867,'The Prisoner of Zenda','The Prisoner of Zenda','An Englishman on a Ruritarian holiday must impersonate the king when the rightful monarch, a distant cousin, is drugged and kidnapped.','The most thrilling swordfight ever filmed...',0,0,4.021389,8.4,11,101,'1937-09-03','en','/tvMF7iljOgOXLvkVsWGr5GrPE4j.jpg',2.392767042287741,3,'2026-09-10',2,NULL,NULL),(43884,'英烈传','The Charge of the Light Brigade','1853年，英俄两大帝国为争夺印度及边境地区的控制权，在充满政治阴谋与联盟的\"大博弈\"中激烈角逐。杰弗里·维克斯少校历经数次背叛与磨难，最终在1854年10月25日——克里米亚战争中最辉煌的一天——于巴拉克拉瓦高地实现了自己的复仇。','The reckless lancers sweep on and on - so that a woman\'s heart might not be broken! You\'re not fighting a single legion - you\'re fighting the entire British army, Surat Khan!',1200000,2736000,2.968235,6.8,18,115,'1936-10-20','en','/v7PFjyhEAWKGQ8g6cTGw4GzYKsa.jpg',2.484912109848905,3,'2026-09-10',2,NULL,NULL),(43923,'说来有点可笑','It\'s Kind of a Funny Story','本片改编自Ned Vizzini的同名小说。16岁的男孩Craig克雷格经常会想象自己的死亡，在尝试多种药物皆没有效果后，自己来到精神病院接受治疗。在那里，他和一个自杀了几次却没能死掉的神神叨叨的Bobby鲍比成了朋友，还认识了一个特别的女孩Noelle，当然还有许许多多的“非正常人”。他们几个在医院的生活中，渐渐寻回了生命的意义，尤其是鲍勃·迪伦的歌词“He Not Busy Being Born Is Busy Dying”给了他们巨大的力量，让他们重新拥有勇气去面对生活的压力。最后，出院的克雷格是否能让他原本阴霾密布的生活重见阳光，他又将通过怎样的方式找回轻松充实的生活？','Sometimes what\'s in your head isn\'t as crazy as you think.',8000000,6491240,13.143045,6.9,672,101,'2010-07-06','en','/4QlcP56vhE30QemfoynV6v9ZEXU.jpg',3.391160828524794,3,'2026-09-10',2,NULL,NULL),(43931,'猛鬼生日宴','My Soul to Take','15年前，马萨诸塞州的里夫顿镇上，一个臭名昭著的连环杀手在抓获之前意外身亡，同日，7个孩子在当天晚上于镇上出生。居民们并没有把这两件看似风马牛不相及的事联系在一块，直到15年后，镇上再度发生人口失踪案件，受害人均是当年同一天出生的人。所有的线索都指向了15年前的这个连环杀手，究竟是连环杀手转世，成为这7个孩子里的一员，抑或他当年其实并没有死掉？平时唯唯诺诺，被大家奚落嘲笑的、外号“臭虫”的亚当·海勒（马克斯·希尔莱耶饰），成为解开谜题，找出真凶的关键……','Only One Has The Power To Save Their Souls',25000000,19829957,7.001176,5.2,147,107,'2010-10-08','en','/m6ZmXGQ82MS2KLVMmSXoKrlmyZv.jpg',2.888932478157878,3,'2026-09-10',2,NULL,NULL),(43933,'怪兽','Monsters','六年前，美国太空总署观测到地外文明，但是派出勘测的飞船返航时在墨西哥坠毁。从此之后，墨西哥许多地区受到外星神秘生物的感染，无数百姓丧生。美国方面派出军队与巨大的外星怪兽作战，彼此伤亡惨重。\r 洛杉矶的记者安德烈·卡特（斯科特·麦克奈利饰）接受某富翁的请求，前往墨西哥感染区寻找其女儿萨曼莎·温登（惠特尼·阿贝勒饰）。安德烈顺利见到萨曼莎，二人随即踏上开往美国的列车，然而列车却在中途折返。他们被迫寻找其他归国的途径，只是命运难测，回国之路似乎充满险阻。万般无奈，安德烈和萨曼莎只得步行穿越危险重重的感染区。','After Six Years, They\'re No Longer Aliens. They\'re Residents',500000,4242978,26.406001,6.2,587,94,'2010-06-18','en','/nuGTvvSZml9xfLHtU02x99se1XV.jpg',3.2904869460728907,3,'2026-09-10',2,NULL,NULL),(43935,'夜之亡灵','Dylan Dog: Dead of Night','私人侦探迪伦·道格（布兰登·罗斯 Brandon Routh 饰）是一个具有超自然能力的男人，因某些原因，他蜷缩在城市的一角，过着隐姓埋名尽量不引起他人注意的生活。某天，超级富翁阿尔弗自杀身亡，他的女儿却认定父亲系被人所杀。迪伦在朋友马库斯（山姆·汉丁顿 Sam Huntington 饰）的拜托下来到阿尔弗的住所，结果反拒绝了这个案子。此后不久，马库斯横尸家中。好友的死令迪伦大为触动，于是重新接受了关于阿尔弗的委托。经过对现场的勘查，他断定阿尔弗死于一匹女性狼人之手。迪伦循着蛛丝马迹深入追查，也渐渐置身巨大的危险之中……　　本片根据Tiziano Sclavi的系列漫画《迪伦·道格（Dylan Dog）》改编。','No pulse? No problem',20000000,4634062,10.617236,4.5,139,107,'2011-03-16','en','/nZdYn5IktnGVg7pRA2JHD1rdZDH.jpg',2.8535753212305712,3,'2026-09-10',2,NULL,NULL),(43942,'魔鬼经济学','Freakonomics','浅显易懂的告诉你，那些个经济学家怎么把你的辛苦劳动塞进他的荷包。','Things you always thought you knew but didn\'t',3000000,103735,1.781462,6.6,36,93,'2010-10-01','en','/cPXdZeUKmIylEG8ml0tQOPt9SJ9.jpg',2.628838413367353,3,'2026-09-10',2,NULL,NULL),(43947,'我唾弃你的坟墓','I Spit on Your Grave','该片讲述了一个漂亮的年轻女作家珍妮为了开始她的第一部长篇小说，来到一个河边小镇寻找灵感。送外卖的马修很快对这个美丽又聪慧的女孩流露出爱慕之心，他把这个秘密告诉了他的三个在加油站工作的朋友。这三个年轻的男子早就对性感的珍妮虎视眈眈，在几次试探之后，他们和马修一起截住了小船上身穿比基尼的珍妮，对她进行了轮奸。在遭受了粗暴的凌辱之后，珍妮放弃了投案，而是按照自己的意志和方法，将四个男人一个个杀死。','It\'s Date Night',2000000,572809,26.281839,6.3,519,108,'2010-06-17','en','/45APllGlBVySh3ANeQa6YwZbwlM.jpg',3.275206584877692,3,'2026-09-10',2,NULL,NULL),(43949,'怦然心动','Flipped','1957年，布莱斯·罗斯基一家搬到小镇，与邻家女孩朱丽·贝克成为邻居。第一次见到布莱斯，朱丽便对他怦然心动，此后总想方设法接近他，而布莱斯却一直对这个过分热情的女孩避之不及。随着两人渐渐长大，一棵朱丽深爱的梧桐树以及生活中接连发生的小事，让他们开始用不同的眼光重新认识彼此。曾经深信布莱斯就是自己心中那个特别之人的朱丽逐渐产生动摇，而一直想要摆脱她的布莱斯，却开始发现这个邻家女孩身上从未留意过的美好。两颗原本错开方向的心，也在成长中悄然发生着变化……','You never forget your first love.',14000000,1755212,24.210698,7.4,418,89,'2010-08-06','en','/tOp4DkdonY1a1AS5ESWDia8JP63.jpg',3.3410102065732166,3,'2026-09-10',2,NULL,NULL),(43959,'灵魂冲浪人','Soul Surfer','影片改编自2004年出版的传记文学《灵魂冲浪：一个关于信念、家庭和重新站上冲浪板的真实故事》。成长在夏威夷考艾岛的贝瑟尼·汉密尔顿（安娜索菲亚·罗伯 AnnaSophia Robb 饰）是一个天生的冲浪天才，从小就展示出了在冲浪方面的过人的才华。她与好友埃兰娜（洛琳·尼科尔森 Lorraine Nicholson 饰）一起参加了全国的冲浪比赛，并且获得了不俗的成绩。但在她13岁那一年的一个早晨，在她在冲浪的时候一条14英尺长的虎鲨袭击了她，咬下了她的左臂。一瞬间，她的生活和未来都被冲垮了。就在所有人都在准备为她另谋出路的时候，她决定用自己残缺的身体重返冲浪的赛场。在好朋友汤姆、切瑞和萨拉的帮助下，她用自己惊人的毅力重新起立，站在了冲浪板和浪头之上。','When you come back from a loss, beat the odds, and never say never, you find a champion.',18000000,47088990,19.234672,6.9,342,106,'2011-04-08','en','/cvgRxrEupUFeJ0xzUExJo4dMXbL.jpg',3.220836196230728,3,'2026-09-10',2,NULL,NULL),(44009,'Another Year','Another Year','Mike Leigh’s much praised 2010 tragicomical drama. During a year, a very content couple approaching retirement are visited by friends and family less happy with their lives.',NULL,8000000,18124262,7.235794,7,97,129,'2010-11-05','en','/i1pUpxsTzNTa0Lc7DVJsQO4U2Jc.jpg',2.877207818149365,3,'2026-09-10',2,NULL,NULL),(44040,'电梯里的恶魔','Devil','影片开始于一个平凡的早晨，克里斯·梅西纳、吉奥弗瑞·阿伦德、博基姆·伍德拜因、卡洛琳·达芙娜、伯亚娜·诺瓦科维奇扮演的五人搭乘同一座电梯上楼，不想，半途电梯故障，将他们困在中间。先是其中一人遭受袭击，其后猜疑、争斗相伴而生……究竟是谁挑起的争端？这五个人中究竟谁是伪装成人类的恶魔？　　在一幢办公大楼，五个人被困在升降机中，封闭狭窄的空间令众人逐渐陷入恐慌及歇斯底里，互相猜忌、尔虞我诈，甚至杀人自保！但他们并不知道，来自地狱的魔鬼，原来早已在升降机内恭候……','Bad Things Happen For A Reason',10000000,33583175,30.934688,5.8,816,80,'2010-01-13','en','/9yksb3siodD9cy0IZPZtEUBB2MI.jpg',3.311004392345371,3,'2026-09-10',2,NULL,NULL),(44048,'危情时速','Unstoppable','宾夕法尼亚州南部的布鲁斯特市，资深的火车机师弗兰克·巴恩斯即将提前退休，作为拥有丰富阅历和经验的老员工，他和伙伴们虽然对公司出于成本雇用相对便宜却没有经验的新员工不满，却也无可奈何。这天早晨，弗兰克迎来了新的搭档，年轻气盛的领航员威尔·科尔森，新老交替正式开始。与此同时，位于北部的富勒站出现状况，满载危险化学品的777号列车在无人驾驶的情况下径自开走，如野兽般咆哮着冲向人口密集的城镇。危险随时降临，弗兰克和威尔即将度过难忘的一天……','1,000,000 Tons. 100,000 Lives. 100 Minutes.',100000000,167805466,37.698465,6.3,1165,98,'2010-11-04','en','/sEl9TSSZU58Z7OfTR2AUnRIC3uP.jpg',3.487832248549638,3,'2026-09-10',2,NULL,NULL),(44092,'剑雨','剑雨','八百年前，天竺人罗摩来至中原弘法，其死后尸体被人盗取并分为两部分。传说拿到罗摩尸体的人能练成绝世武功，因此江湖上风波骤起。时有转轮王（王学圻 饰）操控的黑石杀手集团，专为朝廷杀害谋逆相左之人。转轮王率徒众夜袭藏匿半具达摩尸首的首辅张海端（李庆祥 饰）宅邸，但是他的手下细 雨 （林熙蕾 饰）却带着残尸绝走江湖，致令转轮王发出江湖追杀令，引出一阵血雨腥风。\r 为避追杀，细雨易容，更名曾静（杨紫琼 饰），逃亡期间结识了木讷善良的江阿生（郑雨盛 饰）。一段时间相处，二人渐渐萌生感情，更喜结连理。但是江湖恩怨，因蔓不断，怎可轻易了结……',NULL,12000000,0,4.930129,6.7,57,117,'2010-09-01','zh','/fNSFl35PqSqc3vpkl0txC3eZLm0.jpg',2.739546174798854,3,'2026-09-10',2,NULL,NULL),(44113,'危狱惊情','Stone','假释官杰克·马布里只有几个星期就要退休了，他希望把自己手上最后的案子都处理好。其中一个案子涉及一个名叫杰拉德·斯通（\"石头\"）·科里森的纵火犯，他试图申请假释。杰克最初并不满意 \"石头\"粗鲁的态度，对他申请提前释放的请求也没有太大同情。眼看着假释希望渺茫，\"石头\"安排让他的妻子鲁斯塔去诱惑杰克，但是这样的动机和意图渐渐在激情与堕落中迷失，而渐渐的，这场关于假释的博弈也成为了一场死亡的游戏。','Some People Tell Lies. Others Live Them.',22000000,9479718,12.445176,5.2,192,105,'2010-10-07','en','/uk13QR5MSRkiGuKHo492cNcJqhK.jpg',2.9478777937013887,3,'2026-09-10',2,NULL,NULL),(44115,'127小时','127 Hours','本片根据登山者阿伦·拉尔斯顿的真实经历改编，讲述他在犹他州一处偏远峡谷被落石压住手臂、身陷绝境后，以非凡的毅力展开断臂自救的惊险历程。[福克斯探照灯影业]','There is no force more powerful than the will to live.',18000000,35692920,52.464877,7,2606,94,'2010-11-05','en','/h0RMdn0rfl9l5hWXz3tUh6QVkhi.jpg',3.8697534598850316,3,'2026-09-10',2,NULL,NULL),(44147,'狂野目标','Wild Target','中年杀手维克多（比尔·奈伊扮演）一向独来独往的生活里闯进了两个人： 一个名叫托尼的年轻人（鲁珀特扮演）成为了维克多的徒弟，还有一个胆大包天的女贼Rose（艾米莉扮演），她得罪了黑道上的人，维克多受雇去杀她。然而环境所迫致使维克多无法下手，黑道老大遂又派出了两路人马过来杀她（并且顺带着把这师徒二人也结果掉）。维克多决定帮助Rose，这个另类三人组来到维克多家里避风头，家中还有他那坏脾气的老妈路易萨（艾琳·阿特金斯饰演）。在躲避追杀的过程中维克多对Rose渐生情愫，可是她发现了他的身份和使命，害怕他会杀死她，而他们与追杀者的最终对决也不可避免。','They said \'Take her out\'. He got the wrong idea.',8000000,3453043,10.791954,6.4,215,98,'2010-06-17','en','/nydUkkl9IJ4JMo6igDxXJMkZZHE.jpg',3.045308490625452,3,'2026-09-10',2,NULL,NULL),(44214,'黑天鹅','Black Swan','纽约剧团要重排《天鹅湖》，因前领舞Beth离去，总监Thomas（文森特•卡索尔 Vincent Cassel. 饰）决定海选新领舞，且要求领舞要分饰黑天鹅与白天鹅。Nina（娜塔莉•波特曼Natalie Portman 饰）自幼练习芭蕾舞，在母亲的细心关照下，技艺出众。这次，她希望可以脱颖而出。然而，在竞争中，她发现心机颇重的Lily（米拉•库妮丝 Mila Kunis 饰）是自己的强劲对手。在选拔中，她的白天鹅表演的无可挑剔，但是黑天鹅不及Lily。她感到身心俱疲，回家还发现了背部的红斑与脚伤。她一个人找到总监，希望争取一下。总监趁机亲吻她，却被她强硬拒绝。结果，总监居然选了她。队友怀疑她靠色相上位。在酒会上，Beth甚至当众发泄。这种压力外加伤病，一直影响着她的发挥。总监启发她要释放激情，表现出黑天鹅的诱惑。在强大的心理暗示中，她似乎也滑向了黑天鹅的角色。','In the era of personal branding, the scariest possibility is that someone might be better at being you than you are.',13000000,327803731,91.285683,7.3,4430,108,'2010-12-02','en','/viWheBd44bouiLCHgNMvahLThqx.jpg',4.171463267379634,3,'2026-09-10',2,NULL,NULL),(44260,'地狱之火','Lake of Fire','以《美国X档案》闻名的电影人托尼·凯，历时十五年创作了本片。这部作品无疑成为探讨堕胎议题的权威之作。影片以富有层次的黑白影像呈现——那实质上是无穷尽的灰度色阶——其美学风格与这个不存在绝对“对错”的议题完美契合。导演给予对立双方同等篇幅，既涵盖光谱两端的极端观点，也记录中间地带的聲音——那些承认最终人人皆“对”或皆“错”的思考。[THINKFilm]','Exploring the Issue that Divides the World',0,25,0.475748,8,10,152,'2006-09-09','en','/uFdUv0neGCpaYLRJN45mnpc0pdR.jpg',2.3632332837149654,3,'2026-09-10',2,NULL,NULL),(44264,'大地惊雷','True Grit','因父亲被害，14岁的玛蒂·罗斯抵达案发地史密斯堡，作为长女代表家人处理后事。杀死父亲的凶手汤姆·切尼已不知去向，在这枯燥又忙碌的西部小镇上，没人关心杀死异乡人的逃犯何时落网。玛蒂决定自己雇佣警察为父亲报仇，经人介绍，她选择与醉醺醺的警长罗斯特·考波恩合作，同时，一名来自德克萨斯的骑警拉博夫亦希望抓获汤姆·切尼，好在德州获得高额悬赏，为了让切尼在本地被正法，玛蒂必须在拉博夫之前抓到杀父仇人。成熟而坚强的玛蒂与罗斯特踏入了保留地，在那里有众多不法之徒，以及暂时逍遥法外的仇人……','Punishment Comes One Way or Another.',38000000,252276927,49.292384,7.2,1668,110,'2010-12-22','en','/tCrB8pcjadZjsDk7rleGJaIv78k.jpg',3.7846630153293264,3,'2026-09-10',2,NULL,NULL),(44413,'圣女','La niña santa','少女愛瑪的世界，就是母親經營的一家失修的酒店。一群耳鼻喉專科醫生來到開交流會，其中一個竟在圍觀街頭表演時用下體湊近愛瑪。愛瑪認定這是天主感召，要打救沉淪的醫生。她的虔诚與無知，令拯救者與被拯救者陷落更騷動的境地……','She is both temptation and salvation.',1400000,0,0.684881,6.8,10,106,'2004-05-06','es','/6Wjt2ZIWSNLudz6MByaIknWeval.jpg',2.358835778918832,3,'2026-09-10',2,NULL,NULL),(44490,'查克和贝克','Chuck & Buck','Buck is a man-child who has lived his existence in a life of kindergarten collages and lollipops. Buck remembers his old childhood friend Chuck, with whom he feels a need to reconnect with after having invited him to his mother\'s funeral. Buck treks out to LA where Chuck, now a music record executive, is living his life. Buck ends up developing an obsession with Chuck and begins stalking him.','REMEMBER THOSE GAMES WE USED TO PLAY?',0,0,0.812855,5.7,16,96,'2000-01-21','en','/k0GY9haWiwZtBOf2T7winwNcsep.jpg',2.4482031189781606,3,'2026-09-10',2,NULL,NULL),(44555,'A Woman, a Gun and a Noodle Shop','三枪拍案惊奇','Wang is a gloomy, cunning and avaricious noodle shop owner in a desert town in China. His neglected, sharp-tongued wife is involved in a secret affair with Li, one of Wang’s employees. A timid man, Li reluctantly keeps the gun his lover has bought to kill her husband. But Wang is watching their every move. He bribes patrol officer Zhang to murder the illicit couple. It seems like a perfect plan: the affair will come to a cruel, bloody but satisfying end… or so he thinks. The equally wicked Zhang has an agenda of his own. As the plot twists, more blood will flow, and ever greater violence will erupt…',NULL,0,0,1.416796,4.8,13,95,'2009-12-11','zh','/9ERo2j4ITrUVqZ3xNkIHAtY4dKG.jpg',2.403178191271839,3,'2026-09-10',2,NULL,NULL),(44562,'艾德与亡母','Ed and His Dead Mother','艾德的母亲已经逝世一年了，但他却始终沉浸在失去生命中所至爱的人的悲痛之中，直到一家名为“快乐人”的公司声称只要支付五千元就可复活他的母亲的一天。半信半疑的艾德接受了代理的要求，惊奇的是其母果然复活了，并照顾起艾德的衣食住行，生活似乎恢复到了以前一样。但舒心的日子并没有过太久，艾德发现他的母亲竟然以吃活物为生，且胃口越来越大，从最小的蟑螂一直到人类无所不吃。艾德开始对母亲产生了恐惧，母亲也开始对艾德的新交女友虎视耽耽起来，于是危机爆发，死亡的气息弥漫了整个街区，忍无可忍的艾德终于举起电锯，决定了结这一切……','A family reunion with some minor complications.',0,0,0.023436,5.5,12,93,'1993-06-04','en','/AnF4FFmJPIJhZ3FoOhlTWClPHFR.jpg',2.3878290712944703,3,'2026-09-10',2,NULL,NULL),(44564,'劈腿困境','The Dilemma','罗尼（文斯·沃恩 Vince Vaughn 饰）和尼克（凯文·詹姆斯 Kevin James 饰）是一对关系十分要好的死党，从大学时代一路陪伴进入职场，他们似乎是世界上最熟悉彼此的存在。不仅如此，罗尼的女友贝丝（詹妮弗·康纳利 Jennifer Connelly 饰）和尼克的妻子吉妮瓦（薇诺娜·瑞德 Winona Ryder 饰）也是一对无话不谈的好朋友。  　　故事要从罗尼在街上偶遇吉妮瓦的那一天说起，要命的是，那一天和吉妮瓦亲密的站在一起的却并非她的丈夫，亦是罗尼的好友尼克，而是另一个他并不认识的英俊男人。这件事情成为了罗尼的心结，在友情和道义面前，罗尼不知该如何选择。更让罗尼震惊的是，他逐渐发现尼克竟然也有着不能对他倾诉的秘密。','Two best friends. Nothing could come between them... or could it?',70000000,67112664,14.780634,5.2,304,111,'2011-01-13','en','/a7EVBTqeh6NoCFDW24qIp11kyi9.jpg',3.0290787261156957,3,'2026-09-10',2,NULL,NULL),(44594,'巴里·穆迪','Barry Munday','巴里（帕特里克·威尔森 Patrick Wilson 饰）是朋友圈里出了名的花花公子，他整日里无所事事游手好闲，并且对自己糜烂的现状感到十分满意，丝毫没有任何的悔改之意和进取之心。然而，让巴里没有想到的是，自己竟然在一场意外之中失去了他的睾丸，这也就意味着，他将彻底告别灯红酒绿的花花公子式生活，亦再也不可能做一名父亲了。\r 　　尚未从蛋碎的阴影下完全走出，巴里又陷入了另一个麻烦之中。一位名叫金吉尔（朱迪·格雷尔 Judy Greer 饰）的女士对他提起了诉讼，只因为她的腹中怀上了巴里的孩子。可是别说孩子了，巴里甚至对金吉尔没有任何印象，这个敏感而又神经质的女人绝对不是他会喜欢的类型。','A comedy that hits you right where it counts.',0,0,1.975941,6.3,22,95,'2010-03-13','en','/ctHpUBRpnuGtwF4mYkKQVdjG8NI.jpg',2.520807845693832,3,'2026-09-10',2,NULL,NULL),(44603,'从今以后','Hereafter','------马特•达蒙扮演的乔治是一个美国的蓝领工人。不过乔治不是那种除了工作就去泡酒吧的工人，他有一种灵异的特异功能，他能看到死去的坚人，并且能和他们进行交流侍。这样的“能力”大大影响了他的正常生活，他时时刻刻都能理解到“活着”的意义。与此同时，在地球的另一个大陆上，一个叫做马瑞的法国女记者久久无法逃遁于自己的一次濒死体验，那次痛苦的经历发生在海啸中，马瑞差点为此送了小命。英国，伦敦，一个叫做马库斯的男孩失去了自己的兄弟，带走他兄弟的并不是上帝，而是车祸。马库斯后来也能在冥冥之中看到自己的兄弟，并且和他说话。虽然如此，但是马库斯还是久久不能从兄弟的死中释怀，他需要一个对于生命无常的合理的解释。　　三个人，三种生活，三次对生命意义和生活真相的追问。在影片的结尾，三个主角以一种出其不意的方式相见－－唯一可以确定的是，死亡本身以及有关死亡的体验和认知，将会彻头彻尾地改变他们的生活和生命。','Touched by death. Changed by life.',50000000,105197635,13.365715,5.8,510,129,'2010-10-15','en','/drYCspLQboS0z4iLWXt0orAuLsG.jpg',3.1799020840706276,3,'2026-09-10',2,NULL,NULL),(44634,'Woman Thou Art Loosed','Woman Thou Art Loosed','An adaptation of Bishop T.D. Jakes\' self-help novel, chronciling a woman\'s struggle to come to terms with her legacy of abuse, addiction and poverty.',NULL,3000000,6804016,0.019984,5,3,94,'2004-09-30','en','/oiSE4CMsoipS6l1KLEAPIgN9VVY.jpg',2.133489002438623,3,'2026-09-10',2,NULL,NULL),(44638,'暴风雨','The Tempest','普洛斯佩拉女爵（海伦·米伦 Helen Mirren 饰）生性善良喜爱研究魔法，在弟弟安东尼奥（克里斯·库柏 Chris Cooper 饰）和国王阿隆佐（大卫·斯特雷泽恩 David Strathairn 饰）的联手迫害之下，普洛斯佩拉女爵不得已带着女儿米兰达（菲丽希缇·琼斯 Felicity Jones 饰）流落孤岛。',NULL,20000000,346594,3.620537,6,31,110,'2010-12-10','en','/hFMLZ1oFZgY43FuPgZ8mIhz7oti.jpg',2.5932483941664755,3,'2026-09-10',2,NULL,NULL),(44639,'监守自盗','Inside Job','本片是首部揭露2008年经济危机背后惊人真相的影片。这场导致全球金融体系崩溃的危机耗费超过20万亿美元，令数百万人流离失所、丧失工作。影片通过大量调查以及对金融界核心人士、政客与记者的访谈，追溯了一个失控行业的崛起，并揭露了腐蚀政治、监管与学术界的共生关系。[索尼影业经典]','The film that cost $20,000,000,000,000 to make.',2000000,7871522,16.930914,7.7,286,109,'2010-10-08','en','/7yXXIWec24htucjsZS1sDuPLqw8.jpg',3.2356576767387764,3,'2026-09-10',2,NULL,NULL),(44718,'自己的葬礼','Get Low','长久以来，小镇居民们对菲利克斯（罗伯特·杜瓦尔 Robert Duvall 饰）的猜测和怀疑从未停歇。有人觉得他生性孤僻是个怪胎，有人觉得他犯下了什么不可饶恕的残酷罪行，有人甚至信誓旦旦的说他将灵魂交予了魔鬼换来了可怕的能力，总而言之，所有的言论最终都以这样的一句话来结尾——“要不然他怎么会常年躲在森林里不愿露面呢？”  　　某一天，神秘的菲利克斯出现在了惊恐的居民们面前，他的出现除了带来恐慌外，还造就了大家茶余饭后的谈资，因为菲利克斯提出了一个非常奇怪的要求——举办一个他自己的葬礼。唯利是图的殡仪馆老板弗兰克（比尔·默瑞 Bill Murray 饰）看见了其中的商机并且揽下了这笔生意，但在葬礼的准备工作进行之际，弗兰克逐渐发现了菲利克斯那深藏于个人历史中的不为人知的秘密。','Every secret dies somewhere.',7500000,0,6.557643,6.5,100,103,'2010-01-22','en','/6uUaQ5zn9neK1VLqO2sGClbJrb9.jpg',2.8649506712565462,3,'2026-09-10',2,NULL,NULL),(44754,'玛格丽特','Margaret','丽莎（安娜·帕奎因 Anna Paquin 饰）是一名17岁的高中生，和大多数高中生一样，虽然处于尴尬的青春期，但丽莎的生活中并没有太大的烦恼和困扰。一次意外中，丽莎被卷入了一场惨烈的交通事故中，一个陌生的女人在事故中身亡。女人的死颠覆了丽莎的世界，她再也无法用曾经的眼光来看待周围的一切了。为了弥补内心的创伤，丽莎做出了很多的努力，但很快她便发现，所有企图弥补创伤的举动，最终都会带来新的伤痛，唯一的解决方法，就是还原车祸的全部真相……',NULL,14000000,46495,4.898424,6.1,86,149,'2011-09-30','en','/zqBao8uRH6TQAJd13tqC22vPB76.jpg',2.814331573952434,3,'2026-09-10',2,NULL,NULL),(44770,'The Exploding Girl','The Exploding Girl','On a summer break from college, Ivy, a young epileptic woman, struggles to balance her feelings for her fledgling boyfriend while her friend Al crashes with her for the season.',NULL,0,0,0.611081,6.4,15,80,'2009-04-22','en','/xRJ4wgDtxwoDzKjVRjZ457kf85f.jpg',2.4389777961324874,3,'2026-09-10',2,NULL,NULL),(44826,'雨果','Hugo','改编自布莱恩·塞尔兹尼克引人入胜又充满想象力的《纽约时报》畅销书《造梦的雨果》。马丁·斯科塞斯首部采用3D技术拍摄的电影，讲述了一个孤儿男孩在巴黎火车站墙壁内秘密生活的故事。当雨果遇到一台损坏的机器、一个古灵精怪的女孩，以及经营玩具店的那位冷漠寡言的男人时，他被卷入一场神奇而神秘的冒险，这可能让他所有的秘密陷入危机。[索尼影业]','One of the most legendary directors of our time takes you on an extraordinary adventure.',170000000,185770160,32.319043,7,2141,126,'2011-11-22','en','/1dxRq3o3l3bVWNRvvSb7rRf68qp.jpg',3.7716510822230402,3,'2026-09-10',2,NULL,NULL),(44833,'Battleship','Battleship','When mankind beams a radio signal into space, a reply comes from ‘Planet G’, in the form of several alien crafts that splash down in the waters off Hawaii. Lieutenant Alex Hopper is a weapons officer assigned to the USS John Paul Jones, part of an international naval coalition which becomes the world\'s last hope for survival as they engage the hostile alien force of unimaginable strength. While taking on the invaders, Hopper must also try to live up to the potential his brother, and his fiancée\'s father, Admiral Shane, expect of him.','The Battle for Earth Begins at Sea',209000000,303025485,64.928382,5.5,2114,131,'2012-04-11','en','/cU7hyTvGP7FA527LkDI25dAvSBn.jpg',3.5080623471526207,3,'2026-09-10',2,NULL,NULL),(44835,'海瑟','Hesher','T.J（戴文·波切Devin Brochu 饰）是个刚刚因车祸失去母亲的13岁男孩，因为父亲承受不了打击开始整天嗑药，他只好和祖母生活在一起。就在T.J最低落的时候，一个古怪的家伙闯进祖母的老房子，他长发油腻，满身纹身，疯疯癫癫，仇恨社会，自称名叫海瑟（约瑟夫·高登-莱维特 Joseph Gordon-Levitt 饰），就此赖下不走。附近的杂货店员妮可（娜塔丽·波曼 Natalie Portman 饰）时常关心T.J，令他对她产生暧昧感情，同时妮可和海瑟的关系也在发展。一个普通女孩，两个各自带着内心伤痛的“大”“小”男人，他们的人生都在被彼此改变。','Sometimes life gives you the finger and sometimes it gives you...',7000000,382946,13.635828,6.7,212,106,'2010-01-22','en','/dD03azf3h1hUHVzVkkqJs96Kkay.jpg',3.06884360977739,3,'2026-09-10',2,NULL,NULL),(44853,'雪岭传奇','The Claim','故事发生在1849年，“淘金热”的来袭让世界发生了翻天覆地的变化。投机商人迪伦（彼得·穆兰 Peter Mullan 饰）凭借着自己的手腕和智慧，成为了加州小镇中富有到足以一手遮天的所在，就连平日里高高在上的妓院老板娘露西亚（米拉·乔沃维奇 Milla Jovovich 饰）都无法抵御黄金的诱惑，主动对迪伦投怀送抱。\r 就在迪伦最春风得意的时刻，三个客人的到来彻底改变了他的生活。埃莱娜（娜塔莎·金斯基 Nastassja Kinski 饰）和霍普（萨拉·波莉 Sarah Polley 饰），一个是弱不禁风的中年妇人，一个是瘦小苍白的稚嫩女童，她们两人的真实身份，竟然是迪伦在早年抛弃的妻子和女儿。另一位是名叫达格里斯（韦斯·本特利 Wes Bentley 饰）的男人，他的存在对于小镇的存亡来说至关重要。','Everything has a price.',0,0,2.996284,5.6,17,120,'2000-12-29','en','/drpLBTmnMOzDUVAd3jqeLjdolcf.jpg',2.464755637899422,3,'2026-09-10',2,NULL,NULL),(44857,'莫莉的世界','Molly','莫莉的哥哥在电影厂拍片，突然收到疗养院的一封信，妹妹莫莉所在的疗养院就要关闭了，他必须要把妹妹给接出来。父母早亡，照顾妹妹是哥哥义不容辞的责任。但是所有的人都没有听说过这个妹妹的存在，包括女朋友。所以当女朋友第一次看到这个当哥哥的为妹妹换尿湿内裤的惊讶是可想而知的。女朋友再也没有回来，接着说再见的是工作，原因是哥哥在会议室与客户介绍产品时匆忙带到办公室的妹妹在玻璃窗外脱衣服，客户失掉了。工作一个接一个地失去。但哥哥仍然耐心地为妹妹做所有的一切，偶尔他也冲妹妹大发脾气，完了之后再道歉。工夫不负有心人，莫莉在哥哥耐心照顾下智力在不断提高，并且在医院的手术后莫莉越来越像个正常的大姑娘，只是人太过坦率，并且对真诚有些执著地偏激。','Innocence is bliss. See the world through her.',0,0,2.636193,5.5,14,102,'1999-10-22','en','/bKyRoZ8uutxdCMMmrVoivZJ0Mc7.jpg',2.424384016360399,3,'2026-09-10',2,NULL,NULL),(44865,'一代宗师','一代宗師','20世纪30年代，佛山咏春拳师叶问家境优渥，潜心习武，过着平静的生活。1936年，声望卓著的北方武术宗师宫宝森南下佛山举行引退仪式，希望在退出武林之前推动南北武术的交流与传承。叶问被南方武林推举出来，与宫宝森以武会友，也由此结识了他的女儿宫二。不同门派、不同出身的武林人物因为这场南北之会产生交集，而随后席卷而来的战争却彻底改变了他们原本的人生轨迹。在动荡的时代里，叶问、宫二以及一众习武之人不得不面对各自关于传承、尊严与去留的选择……','In Martial Arts there is no right or wrong, only the last man standing.',3860000,64076736,19.947265,6.3,273,130,'2013-01-08','zh','/pdj2KHRL8xG5NuKx5V5MH2qLrXZ.jpg',3.1135466328506913,3,'2026-09-10',2,NULL,NULL),(44896,'兰戈','Rango','兰戈是一只被饲养在玻璃箱里的变色龙，它时常幻想自己是一个伟大的英雄。突然，它从当代的美国社会穿越到了一个老旧的西部边陲小镇德特（Dirt，有肮脏的含义）。由于一来就阴错阳差地结束了一只鹰的寿命，兰戈莫名其妙地成为了小镇的英雄。小镇人民很欢迎它，它也乐得其所地成为了这些可怜巴巴的小镇居民－－都是些沙漠动物－－的救世主。因为兰戈时常幻想自己是一个英雄，所以它很愉快地接受了小镇镇长的任命，他成了德特镇的警长。从此，兰戈开始了每天在镇子上巡逻的生活。兰戈喜欢这种成为“英雄”和“好人”的生活。只是，它不知道的是，在德特镇，“好人”就意味着死掉。在镇子的尽头，有一片专门为“好人”而设置的坟场。不过，这些并没有成为阻止兰戈前进的障碍，它反倒是越挫越勇地带领小镇人民争取自己的利益。最后，出现了终极的大坏蛋－－一条眼镜蛇，兰戈也发现自己面临着有史以来最为严峻的挑战。它能全身而退么？它是否能成为那个自己假想出的英雄？','Heroes come in all different colors.',135000000,245724603,29.91353,6.6,2051,107,'2011-03-02','en','/l2UBsmfgp1X2nrOJTRMif7xXa2o.jpg',3.666096498691534,3,'2026-09-10',2,NULL,NULL),(44912,'绿灯侠','Green Lantern','------在浩瀚无垠，神秘莫测的宇宙中，有一支拥有强大力量的精英团体，几个世纪以来，他们一直是正义与和平的坚强守卫者，被称作绿灯军团。每一个团员都曾立下誓言，誓死维护星系间的和谐与秩序。每一个绿灯团员都佩戴着一只能量戒指，藉此拥有创造心智想象所能涉及的一切物质的非凡能力。但是，当不速之客Parallax威胁要破坏宇宙中各种能量的平衡，绿灯军团的命运，乃至整个地球的命运，便落到了一个新晋应征入伍的，也是军团中第一个以人类身份被征募的人物手里。他的名字叫：哈尔•乔丹（瑞安•雷诺兹饰演）。哈尔是个天赋秉义却有些自命不凡的试飞员。人类从未有谁能成功驾驭过能量戒指的无穷神力，这一事实令绿灯军团内历来有轻视人类的风气。但是哈尔身上散发出的人性也是军团内部其他任何团员所不具备的。所以，哈尔必须将自己的意志力和决心迅速培养起来，与此同时，同伴飞行员，同时也是青梅竹马的初恋女友卡洛尔•菲利斯（布蕾克•莱弗利饰演）的支持与鼓励也是帮助他证明自己价值的关键因素之一。只有拥有了这一切，哈尔才能够克服恐惧，熟练运用自己拥有的新能力，用勇气、智慧和力量打败Parallax，战胜邪恶，拯救地球和人类免受灾难。','In our darkest hour, there will be light.',200000000,219851172,51.872839,5.1,2487,114,'2011-06-16','en','/jIR62taAhqyU7hTPRqZY0RmdOtr.jpg',3.415232462045985,3,'2026-09-10',2,NULL,NULL),(44943,'洛杉矶之战','Battle: Los Angeles','一个平静的早上，无数道强光划过世界各大城市的天际，美国太空总署（NASA）初时以为是彗星碎片划过大气层，随即惊觉这些碎片竟然像会蠕动，碎片坠落大海，随即变身武器袭击世界各地沿岸城市！海军陆战队中士Michael Nantz奉命率领小队在洛杉矶某区营救被困市民，谁知现场只余一片颓垣败瓦，尸横遍野；几经辛苦找到被困市民，却受到来历不明的敌人疯狂袭击，军方总部更传来惊人消息：“全球有二十个大城市已遭毁灭，洛杉矶将是人类的最后一道防线！”面对外星异形突袭侵略，海军陆战队将如何突围反击挽救人类？！','It\'s not war. It\'s survival.',70000000,202466756,49.199234,5.5,1448,116,'2011-03-08','en','/n7ZLqZtyiZgYyDuamJ4jJey6Awo.jpg',3.4044251268108097,3,'2026-09-10',2,NULL,NULL),(44944,'彩虹艳尽半边天','For Colored Girls','在当代美国，八个黑皮肤的女性有着各自的烦恼和心事。其中的七个，是生活在城市中的现代女性，她们独自面对着自己的生命和生命中的人。七个人，有七种不同的生活：坠入爱河、遭到遗弃、被强奸、要堕胎等等，不一而足。第八个女人是一个宗教界人士，她常常为有色人种指点迷津，但她也时常遭到误解。在影片的最后，这八个女人汇集到了一起，其中的一个说出了古老的咒语：\"我在我的体内找到了上帝，我爱她，我爱得疯狂\"。','Many voices. One poem.',0,37000000,1.934524,7,22,134,'2010-11-05','en','/iEGTE4dRhckbfX8KVGZFxystznL.jpg',2.526869708311803,3,'2026-09-10',2,NULL,NULL),(44945,'信任','Trust','威尔和林恩（克里夫·欧文与凯瑟琳·基纳 饰）住在一个平静的郊区，生活安稳美满，但直到他们14岁的女儿安妮在网上交了一个新朋友——16岁的男孩查理，事情统统改变了。一开始，夫妇俩并不在意女儿的交友，但随后，安妮与查理约会见面，她惊讶的发现：真正的查理是个40岁的恋童癖，他强奸了安妮，将整个家庭拖入悲剧的深渊，而此时威尔的复仇行动也展开了……','What took her family years to build, a stranger stole in an instant.',9500000,120000,21.230737,6.6,307,104,'2010-09-10','en','/pRjhynBqerGzQEoyvlbdVZid4pa.jpg',3.169905726318858,3,'2026-09-10',2,NULL,NULL),(44990,'分手事件','Breaking Upwards','影片根据主创的真实经历改编而成。纽约年轻夫妇达里尔和佐伊在经历了四年的婚姻生活后，开始彼此生厌，绝望之下，他们决定逃离这种枯燥的婚姻生活，但又害怕独自生活，于是他们策划了一个分手计划，两人都试着和别人交往。\r 影片模糊了纪录片与叙事电影的界限，内容就是达里尔·韦恩和佐伊·里斯特·琼斯的真实生活。',NULL,0,0,0.67457,5.6,12,88,'2009-03-14','en','/mEA5Vs7LoVS4dtotal9dc0kdgHz.jpg',2.389802593197367,3,'2026-09-10',2,NULL,NULL),(45054,'There Be Dragons','There Be Dragons','Arising out of the horror of the Spanish Civil War, a candidate for canonization is investigated by a journalist who discovers his own estranged father had a deep, dark and devastating connection to the saint\'s life.While researching the life of Josemaria Escriva, the controversial founder of Opus Dei, the young journalist Robert uncovers hidden stories of his estranged father Manolo, and is taken on a journey through the dark, terrible secrets of his family’s past.',NULL,0,0,6.668679,5.9,27,112,'2011-03-25','en','/7y6ehxTLB1ZJl3xFVFbhcnoJx1m.jpg',2.570314316122994,3,'2026-09-10',2,NULL,NULL);
INSERT INTO `t_video_info` VALUES (45132,'超级英雄','Super','片中雷恩·威尔森饰演一个普普通通的家伙弗兰克，然而他的妻子莎拉（丽芙·泰勒 饰）却和一个名叫雅克的毒贩（凯文·贝肯 饰）搞在了一起，这让弗莱克很崩溃。于是他拉上在当地漫画店里打工的患有精神病的可爱女孩莉比（艾伦·佩姬 饰）协助他一起，化身一对超级英雄组合，誓要打垮毒贩雅克……　　衰男也有反击的一天！人生输家法兰克的美丽妻子离开了他，但一切都是毒枭在背后控制，法兰克决定化身蒙面英雄，与他的超级扳手一同行侠仗义、犀利复仇，只是还有个瞎搅和的女伙伴助阵，一切渐渐失控……','Shut up, crime!',2500000,324138,12.204569,6.6,441,96,'2010-09-09','en','/1wJ79WOm93lEYvAM4M49YbOV81d.jpg',3.239510795592264,3,'2026-09-10',2,NULL,NULL),(45138,'铤而走险','Gli intoccabili','汉克 麦凯恩 (约翰·卡萨维茨饰)是一个在监狱服刑的歹徒,由于黑帮的帮助而提前出狱.一个财团(辛迪加)需要他参与抢劫拉斯维加斯赌场的计划.但是这个计划由于黑帮的干预而很快被放弃.不过汉克却决定继续实行抢劫.他伪装成一个消防员,他依靠他现时的情人艾瑞(布里特 伊可兰饰)的帮助而实行大胆的犯罪.愤怒的黑帮头目决定处死他.他们很快地找到了他的前女友罗斯玛丽(金娜 罗兰饰)以图找到汉克,但她仍然忠于她的前男友宁愿选择自杀也不愿向黑帮提供信息. 既使这样,黑帮仍然通过他们的强大的系统而找出汉克的行踪并使他落网.在1969年的嘎纳电影节上这部电影由于存在争论而未能获奖\r 　　在纽约的一座摩天大楼里,一个辛迪加财团的六位黑帮大佬正在开会,他们从西岸加州头目查理 阿达莫那里得到情报,黑帮成员埃斯波西托从他们的竞选基金中窃取了二十万占为己有.在六个大佬逐个投票认定有罪之后,黑帮大头目萨尔瓦托下命令给阿达莫去处死他.不久阿达莫也被提升为西海岸六个州的总头目\r 　　但是查理 阿达莫并不满足,他又看上了拉斯维加斯皇家饭店如火如荼的赌场生意,他违背大佬们的规定,想插足这里发大财.一天,他来到了皇家饭店,找到了新上任的总经理阿贝,要他告诉饭店老板,他要收买这里,否则对他不利.但阿贝拒绝了他的要求,也不肯告诉他谁是真正的老板.阿达莫决心要按他自己的设想,实施他的另一个被叫作\"专家\"的行动计划。','Even the Mafia Calls Him Mister!',0,0,0.700127,7.3,6,116,'1969-04-01','it','/A50EdDLrdWinWz8uKWKtTLgHxiu.jpg',2.260840787425522,3,'2026-09-10',2,NULL,NULL),(45145,'Johnny Suede','Johnny Suede','A struggling young musician and devoted fan of Ricky Nelson wants to be just like his idol and become a rock star.','Keeping up an image can be a full time job.',500000,0,1.354816,4.7,13,97,'1991-08-18','en','/x1ZvgHwDUFsgqWhYUEcJcyHmZQW.jpg',2.4025106064756345,3,'2026-09-10',2,NULL,NULL),(45153,'仲夏夜玫瑰','Eve\'s Bayou','卡西·莱蒙斯(KasiLemmons)导演处女作。讲述1962年美国南部一个医生家庭中发生的偷情故事。影片密集地充斥着家庭成员间的欺骗以及自欺，未来、过去与同样昏暗模糊的现在混合在一起。萨缪尔·杰克逊、林·威特菲尔德及莱蒙斯的丈夫冯迪·科蒂斯-豪的优秀表演使得影片血肉丰满。','The secrets that hold us together can also tear us apart.',0,0,1.126941,6.1,27,109,'1997-09-07','en','/33yTPcGSv7eo3FVlb7XKACHl1M8.jpg',2.559800368949528,3,'2026-09-10',2,NULL,NULL),(45226,'捕鹰','The Pursuit of D.B. Cooper','A speculation on the fate of the famous hijacker who parachuted with his ransom and disappeared in the mountains. Has Cooper succeeded in following a meticulous plan to disappear into anonymity despite the best efforts of a dogged cop?','Who says you can\'t take it with you?',0,0,1.379643,6.8,4,100,'1981-11-13','en','/4uDT9RF7JlZf1T0bn0p68DRVmNv.jpg',2.187544973650777,3,'2026-09-10',2,NULL,NULL),(45243,'宿醉2','The Hangover Part II','《宿醉2》的故事依然以一场婚礼开始，为庆祝Stu（艾德·赫尔姆斯）与杰米·钟结婚，一帮兄弟们集体移师泰国曼谷，然后在这座人生地不熟亚洲大都市，艾德·赫尔姆斯饰演的Stu惹了麻烦：这位老兄在一次，或者叫又一次喝得酩酊大醉之后搞上了一个泰国mm，结果却发现这是一个人妖！于是第二天，这帮兄弟再次必须拼凑线索，弄清这个宿醉之夜都发生了什么！','The Wolfpack Is Back',80000000,254455986,58.040149,6.2,3739,102,'2011-05-25','en','/cKZu0Fdkj7dmwbfMpgDqVVCkLJQ.jpg',3.7747360476065106,3,'2026-09-10',2,NULL,NULL),(45269,'国王的演讲','The King\'s Speech','本片改编自英国女王的父亲与特立独行的澳大利亚语言治疗师莱纳尔·罗格之间非凡友谊的真实故事。由奥斯卡奖提名者科林·费尔斯饰演乔治六世——他在兄长爱德华退位后意外继承王位；奥斯卡奖得主杰弗里·拉什则饰演罗格，这位帮助国王寻回声音、引领国家走向战争的良师益友。[韦恩斯坦影业]','Find your voice.',15000000,414211549,54.053576,7.6,2752,118,'2010-09-06','en','/pVNKXVQFukBaCz6ML7GH3kiPlQP.jpg',4.029981801964196,3,'2026-09-10',2,NULL,NULL),(45272,'乡谣情缘','Country Strong','凯莉（格温妮斯·帕特洛饰）是著名的乡村音乐歌后，数月前因一次登台意外导致了流产，而意外正是凯莉本人酗酒过度之后出现精神恍惚所致，因此她被送去了勒戒所，演唱事业也一度停滞。期间她认识了一个才华横溢的乡村音乐作曲家比奥（加内特·赫德兰饰），温柔英俊的比奥给了她莫大的安慰。为了重振演艺事业，凯莉的丈夫兼经纪人詹姆斯（蒂姆·麦格罗饰）开始安排她的复出巡回演唱会，在选择暖场歌手的时候，凯莉推荐了唱作俱佳的比奥，詹姆斯则选中了年轻漂亮的前选美小姐查尔丝（莉顿·梅斯特饰）。然而，在无数媒体和歌迷的强烈关注下，尚未彻底恢复状态的凯莉，在巡回演出中状况连连。每日都要面对镜头的围追堵截，凯莉是否能顶住压力，把握住最后一次的复出机会，她和丈夫的关系是否开始发生改变，在这次巡演中，四个人又该如何面对自我，如何面对彼此之间的关系','It doesn\'t matter where you\'ve been as long as you come back strong.',15000000,20529194,7.809701,5.9,80,117,'2010-12-22','en','/6C95tD92E9xm5poyyzs37bYemM0.jpg',2.799552062913259,3,'2026-09-10',2,NULL,NULL),(45317,'斗士','The Fighter','本片主要讲述了拳击手米奇·沃德（马克·沃尔伯格饰）成为世界轻中量级拳王的经历。米奇同父异母的兄弟迪克·爱克兰德（克里斯蒂安·贝尔饰），曾经也是一个颇具天赋的拳击手，却因为毒品而一蹶不振。然而后来他终于重新振作，监督米奇进行各种训练，最终帮助他夺得了拳王桂冠。　　迪克·爱克兰德曾经是一个天赋异禀的拳击手，也是家庭的骄傲。但是在成名之后，他却忘记了自己的成长经历，开始沉溺于酒精和毒品，最终自毁前程。他同父异母的兄弟米奇·沃德也是一名拳击手，但是没有什么成绩、也没有什么名气，年龄不小的他一直生活在爱克兰德的名声与阴影之中。沃德正在努力训练，希望自己有朝一日能站在拳击台上比赛。　　兄弟俩居住在贫困的马萨诸塞州的洛厄尔，家里都是普通的蓝领工人。在爱克兰德是拳击手的时候，他被叫做“洛厄尔的骄傲”－－因为他曾经把最重要的东西－－荣誉带回到这个贫困的小镇里。但是现在他失去了拳王头衔，他也开始自暴自弃地吸毒酗酒，所以他也不再是小镇人民所爱戴和用户的对象，反而成为了警察的眼中钉和大家心里的阶下囚。兄弟俩的家庭生活也因此而蒙上了阴影。与此同时，年轻的弟弟沃德成为了家庭的新希望，他也成为了一名拳击手。但是弟弟的拳击之路走得并不顺畅。在输掉第一场比赛后，他有些一蹶不振。这个时候，母亲爱丽丝站了出来。她给沃德规划了职业生涯，并且让哥哥爱克兰德做他的教练。不过这个招数并没有见效，沃德的成绩还是很糟糕。在随后的一场比赛里，他的对手差一点把他给打死。出于对自己男朋友的保护，沃德的女朋友卡琳要求沃德离开那个让他难过也曾带给他欢笑的家庭，要他离开那个动辄使用暴力、在街头犯罪的瘾君子哥哥。　　离开的家庭后，沃德的拳击成绩开始提升。渐渐地，他成为了具有拳王挑战资格的“斗士”。就在挑战赛前夕，他的哥哥和那个糟糕的家庭有一次闯进了他的生活。这一次是所有人的机会－－对于沃德而言，他一定要拿到拳王头衔，为自己和小镇带回荣誉；对于爱克兰德和爱丽丝来说，他们要冰释前嫌，让这个家庭不再是名存实亡的躯壳。一番恶战之后，沃德成为了拳王，他成为了新的“洛厄尔的骄傲”。而这个家庭终于也重修于好。','Every dream deserves a fighting chance.',25000000,93617009,31.019381,7.2,1486,116,'2010-12-17','en','/xfsFerGhO1h6rLk8vwLgMyQ8WVJ.jpg',3.7097015270651212,3,'2026-09-10',2,NULL,NULL),(45324,'Casino Jack','Casino Jack','Based on a true story, a hot shot Washington DC lobbyist and his protégé go down hard as their schemes to peddle influence lead to corruption and murder.','Honor. Integrity. Principles. Everything is negotiable.',12500000,1083683,6.546037,6,94,108,'2010-09-16','en','/3Dpicp6VEtCSj39XBG5mnbe5TQ9.jpg',2.8337354537449038,3,'2026-09-10',2,NULL,NULL),(45380,'疯狂的石头','疯狂的石头','重庆一家濒临倒闭的工艺品厂在拆除旧厂房时，意外从厕所里发现了一块价值不菲的翡翠。为了缓解经营困境，厂里决定举办翡翠展览，并由保卫科长包世宏负责看守。没想到消息传开后，国际大盗麦克和本地一伙小偷都盯上了这块宝物，各自使出不同手段试图将其弄到手。包世宏一边想方设法保护翡翠，一边与这些不速之客斗智斗勇。随着几路人马不断交错，一场围绕翡翠展开的明争暗斗也变得越来越失控……',NULL,0,0,1.68502,6.9,22,98,'2006-01-01','zh','/4NVNv2sQKZKb1HtGExUqp3Ukd7f.jpg',2.525420296763964,3,'2026-09-10',2,NULL,NULL),(45610,'机关枪牧师','Machine Gun Preacher','主人公萨姆·奇尔德斯,他曾经是一名毒贩，当他皈依上帝之后，于1998年前往非洲修建了一所孤儿院收容了300名孩子，而且一直呆在那里并组建一队民兵保护这些孩子，防止当地的叛军绑架儿童，让他们成为性奴或者童军。','Hope is the greatest weapon of all',30000000,2527904,13.268936,6.4,286,129,'2011-09-23','en','/62AOl3AZw4k2oN4LJ36belwJ6Bw.jpg',3.1173396664230326,3,'2026-09-10',2,NULL,NULL),(45612,'源代码','Source Code','美国军方直升机飞行员柯尔特·史蒂文斯上尉突然在一列驶向芝加哥的列车上醒来，身边名叫克里斯蒂安的女子似乎认识他，他却发现镜中的自己竟变成了另一个人。还没来得及弄清发生了什么，列车便在爆炸中被摧毁。再次醒来时，柯尔特发现自己身处一个封闭空间，女军官古德温通过屏幕告诉他正在执行一项特殊任务：借助名为“源代码”的项目，他必须一次次回到列车爆炸前最后的8分钟，在有限的时间里寻找制造爆炸的凶手，并阻止即将发生的下一场袭击。然而随着一次次重返同样的8分钟，柯尔特也开始对自己身处的现实产生越来越多的疑问……','Make Every Second Count',32000000,147332697,59.19888,7.1,2699,93,'2011-03-30','en','/nTr0lvAzeQmUjgSgDEHTJpnrxTz.jpg',3.917948764748768,3,'2026-09-10',2,NULL,NULL),(45649,'橡皮轮胎杀手','Rubber','一望无际的荒漠旷野之上，盘桓着十多名不同身份不同年龄的普通人，他们手里各自拿着一个望远镜，透过镜片兀自眺望着远方。其中一人发现了一处垃圾场，所有的人也都向那里望去。视野中，一只蒙满沙尘的轮胎动了起来，匪夷所思的是，它的动作完全没有借助任何外力，仿佛全由其自身掌控一般。它蹒跚学步，磕磕绊绊，碾压着路上的空瓶子和蝎子。偶然间，轮胎似乎发现自己具有神奇的能力，只要集中注意力盯着（如果它有眼的话）前方的生命体数秒钟，对方就会脑袋炸裂爆头倒毙。\r 　　“哦耶！这简直太给力呐！”轮胎心中一定这样想到。于是，它滚着矫健的步伐，向前方走去，一路上掀起血雨腥风。而那群完全没有头脑的观着，始终注视着这离奇的一切……','Are you TIRED of the expected?',500000,98017,9.108949,5.7,251,85,'2010-07-09','en','/qo353Eg6vCoibKfIYc2geL1tP3P.jpg',3.023567401767705,3,'2026-09-10',2,NULL,NULL),(45650,'神秘洞穴','The Hole','一对兄弟在地下室发现了一个神秘的洞穴，由此开始了一段噩梦般的经历。17岁的丹和弟弟卢卡斯跟著母兼父职的妈妈苏珊从纽约搬到无聊小镇，在没有任何娱乐的小镇里，唯一能引起丹注意的就只有住在隔壁的美丽女孩茱莉。苏珊的工作越来越繁忙，无所是事的丹和卢卡斯只有每天在家附近四处探索这个安静小镇，两人无意间打开一个锁上的暗门之后发现一道无底洞，好奇心驱使下，兄弟俩开始查访这栋废弃房屋的过去，并带著茱莉一起来分享他们的新发现，没想到这却是真正梦饜的开始，尘封已久的恶魔即将再次甦醒.......','What Are You So Afraid Of?',0,0,9.983004,5.6,244,92,'2009-09-09','en','/e4u9WW5MLt8Pv6k0E0PBqQ1eu78.jpg',3.012581849693594,3,'2026-09-10',2,NULL,NULL),(45658,'大甩卖','Everything Must Go','尼克（威尔·法瑞尔 Will Ferrell 饰）只是一届小小推销员，在为公司做牛做马16年后，他非但没有得到晋升，反而落得了被残忍开除的下场，而尼克所获得的遣散补偿，竟然只是一把小小的军刀。老天爷似乎存心要和尼克作对，失意的他回到家后，眼见出现的景象简直让他抓狂。原来，妻子对终日浑浑噩噩的尼克失去了信任，她将他的所有家当扫地出门后更换了门锁拒绝再与尼克相见。  　　无家可归的尼克所拥有的全部就是身边的那一堆破破烂烂的垃圾，不甘于现状的他决定利用自己推销员的技能搞一个户外大甩卖。然而，正是这大甩卖让尼克找到了生活的方向，同时将名为撒玛利亚（丽贝卡·豪尔 Rebecca Hall 饰）的漂亮女人带到了他的身边。','Lost is a good place to find yourself',5000000,2614773,9.169411,6,208,97,'2010-10-15','en','/n4wMD3LHyo3nYZNWEOGLzgdyWjX.jpg',3.0072965210030214,3,'2026-09-10',2,NULL,NULL),(45767,'时间改变者','Time Changer','这一年是1890年，圣经教授罗素-卡莱尔写了一份新的手稿，题为 \"变化的时代\"。他的同事诺里斯-安德森博士认为，卡莱尔所写的东西可能会极大地影响未来几代人的未来，于是安德森利用他的秘密时间机器，将卡莱尔送到100多年后的未来，让他看到他的信仰将导致什么。','What if you could see the future impact of your beliefs? One man will.',0,0,0.339757,5.2,9,95,'2002-10-25','en','/cqkfKoK5YLqrOhvnsqdz9Zbgni6.jpg',2.331217068550725,3,'2026-09-10',2,NULL,NULL),(45791,'崎路父子情','And When Did You Last See Your Father?','本片根据布雷克·莫里森同名小说改编，由曾拍摄《她比烟花寂寞》和《导购女郎》的著名导演安南德·图克尔执导。  　　四十岁的专栏作家布雷克·莫里森（柯林·费斯 饰）刚辞了工作，准备创作一部小说。父亲阿瑟（吉姆·布劳特本 饰）身患绝症的消息，让他一些字陷入了对过去的回忆：父亲专制的爱不仅带走了童年短暂的快乐，还使父子二人的感情渐渐疏远。当成年的布雷克不断和父亲对抗时，父亲也在不断与病魔斗争。可是，即便到了此刻，对于记忆中女人贝蒂（萨拉·兰凯萨 饰）和父亲的关系，布雷克始终无法释怀，面对即将离世的父亲，已为人父的布雷克终于明白，缠绕心中多年的疑问，是时候找到答案了。','Between every father and his son there is a story to be told.',0,92,1.939054,6.9,13,92,'2007-10-05','en','/fWzhqUMGva7sKENr4L6M1RC7BlA.jpg',2.4154173471869362,3,'2026-09-10',2,NULL,NULL),(45881,'圣路伊斯大桥','The Bridge of San Luis Rey','这是一个讲述一座吊桥坍塌造成5个人离奇死亡的故事，一个牧师要去解开它的原因，在秘鲁首都利马拍摄，改编于Thornton Wilder novel的小说.',NULL,0,0,0.515677,5.4,15,120,'2004-01-01','en','/jp26f92Z28eFVmwZ90Q09bnrBEB.jpg',2.432706853198938,3,'2026-09-10',2,NULL,NULL),(45958,'美错','Biutiful','影片讲述了一个叫做乌克斯·鲍尔的男人的故事。　　乌克斯·鲍尔是慈祥的父亲，是充满了激情的恋人，也是一个不知所措的儿子，更是一个从事着非法交易的商人。　　他具有通灵的能力，能和死者对话；他亦被鬼魂所召唤，能感知精灵的存在。　　他从巴塞罗那的危机中逃遁了出来，学会了自我保护。他试图找回宁静的生活，保护自己的孩子，并拯救自我。　　乌克斯·鲍尔的故事既简单又复杂，反射的是人们的生活。','You don\'t choose your family. We all belong to somebody, but to belong to Uxbal and Marambra, is both a blessing and a curse.',0,25147786,13.930763,7,291,148,'2010-10-20','es','/eSr0AfM7hwhCEGoIh9i2unebBNx.jpg',3.174287172995698,3,'2026-09-10',2,NULL,NULL),(46138,'达格纳姆制造','Made in Dagenham','1968年，英国达格南。福特汽车制造厂无疑是英国私营企业里的龙头翘楚。然而在以男性为主导的汽车行业里，女性的地位却显得尤为低下。187位缝纫女工在条件极为恶劣的工厂车间里，汗流浃背地埋头缝纫汽车座椅衬垫。肮脏闷热的工作环境，漫长无比的工作时间，而最重要的是，她们的工资却因为性别原因而被压榨到异常低廉。然而为了维持生活最基本的开销花费，这些女工们一直隐忍着这些不公平对待。终于，她们决定高举标语走上街头，罢工抗议在工作中受到的性别歧视，要求同工同酬。','In the fight for equal rights, an ordinary woman achieves something extraordinary.',7200000,0,6.138802,6.6,94,113,'2010-09-11','en','/lcQGPxuk0fclp9UrFevI2lhDi1l.jpg',2.8533784189135125,3,'2026-09-10',2,NULL,NULL),(46146,'追击巨怪','Trolljegeren','2008年的一天，挪威沃达大学托马斯（Glenn Erland Tosterud 饰）、乔安娜（Johanna Mørck 饰）组成的摄制组，前往偏远山区追踪猎熊人。在合法的猎人中间，他们口耳相传着一个名叫汉斯的男子，他被形容成为无法无天的刽子手。摄制组来到汉斯的所在的 拖车公园等候，并成功见到汉斯，然而对方并不予以配合。这群年轻人百折不挠，决定持续跟踪，结果在一座森林里见到难以置信的一幕：身高十几米长着三个脑袋的巨型怪物。汉斯将其称之为巨怪，是政府秘密进行的转基因产物，多以石头为生，害怕紫外线照射。','You believe it when you see it!',3500000,4159678,12.982319,6.7,583,103,'2010-10-29','nb','/j30cIr29BCRlH9bQ8FHEQWIhEWd.jpg',3.3249810079813282,3,'2026-09-10',2,NULL,NULL),(46195,'里约大冒险','Rio','阿蓝 是一只世界上极其稀少的蓝色金刚鹦鹉，当他还是雏鸟时，便被可鄙的偷猎者从里约的热带丛林中掳到美国。阴差阳错，他变成了小女孩琳达的宠物，从此相伴多年，如今的阿蓝俨然一个养尊处优的宅男，甚至到忘记了如何飞行。某天，名叫图里奥 的鸟类学家经过琳达 经营的书店，他被阿蓝所震惊，并希望能将阿蓝带回里约，与世上仅存的另外一只雌鸟繁衍后代。  　　虽然心怀不安，但是考虑到蓝色金刚鹦鹉的命运，琳达还是带着阿蓝来到里约。阿蓝顺利见到了美丽的同类茱儿 。茱儿则一心逃离樊笼，回归大自然。与此同时，一伙犯罪分子盯上了这群可爱的小生灵……','1 out of every 8 Americans is afraid of flying. Most of them don\'t have feathers.',90000000,484635760,46.200042,6.5,2166,96,'2011-04-03','en','/4nJxhUknKV8Gqdhov8pU1YWDYfb.jpg',3.694211394172465,3,'2026-09-10',2,NULL,NULL),(46252,'Rust','Rust','In the midst of a midlife crisis of faith, a man finds hope where he least expects it – his hometown. James Moore (Golden Globe nominee Corbin Bernsen) is a former pastor who returns home to discover a family new to the area has been killed in a mysterious fire, and his childhood friend is implicated in the murder. Convinced of his friend’s innocence, James sets out on a mission to find the truth… and in the process, rediscovers his own lost faith. An uplifting drama about faith, family, and the powerful ties that bind a community together.',NULL,0,0,0.399491,0,0,94,'2010-10-07','en','/4f08y1AJ7LD3qpOVOShtMPOiWCe.jpg',1.8346949013780764,3,'2026-09-10',2,NULL,NULL),(46256,'犹太狮子','The Lion of Judah','本片要从一只名叫犹大的羔羊开始说起，洁白无斑点的身体，让他成为逾越节的最佳祭品，当犹大被村民抓走后，朋友们为了营救牠，离开舒适的马房，就此展开一场英勇却又充满欢笑的冒险旅程。马房里的动物们各有显明的角色刻划，展现不同的“人性”。','The lamb who saved the world!',15000000,0,0.165909,5.8,2,87,'2011-06-03','en','/dOF8yD82vboFuC0gbJdZtz2JeI8.jpg',2.072465194833565,3,'2026-09-10',2,NULL,NULL),(46261,'黑夜勿怕','Don\'t Be Afraid of the Dark','暂时告别了母亲，小女孩莎莉（拜莉·麦迪逊 Bailee Madison 饰）独自乘坐飞机来到异地和父亲艾历克斯（盖·皮尔斯 Guy Pearce 饰）小聚。父母的离异令莎莉闷闷不乐，对待父亲的新女友吉姆（凯蒂·霍尔姆斯 Katie Holmes 饰）自然也提不起多大的兴趣。经过一路颠簸，莎莉来到了父亲最新的寓所——位于郊外的一幢19世纪的豪宅。此前这所房子属于知名的动物画家布莱克伍德（Garry McDonald 饰），但是画家最后神秘消失了。玩耍期间，莎莉偶然发现一间地下室。为了讨得女儿的欢心，艾历克斯不顾管理员的警告强行打开这所尘封的房间。与此同时，神秘和恐怖的事件接连发生，古宅的秘密渐渐被揭开……  　　本片根据本片根据1973年ABC的同名电视电影改编。','Fear is never just make believe',25000000,36993168,14.562197,5.4,341,99,'2010-11-06','en','/jMBMm1jwqvILV8p1K44brBnmwLK.jpg',3.065891424655518,3,'2026-09-10',2,NULL,NULL),(46332,'人与神','Des hommes et des dieux','20世纪90年代，八名法国基督徒修士在北非群山中的修道院里，与当地的穆斯林弟兄和谐共居。当一群外籍工人遭伊斯兰原教旨主义组织屠杀后，恐惧席卷该地区。军队表示愿提供保护，但修士们拒绝了。他们该离开吗？尽管身边的威胁日益加剧，他们逐渐意识到自己别无选择，唯有留下……无论未来如何。本片大致基于1993年至1996年间阿尔及利亚提比邻西多会修士的生活经历创作。[索尼影业]','In the face of terror, their greatest weapon was faith...',4000000,41424067,4.992475,6.5,91,120,'2010-05-18','fr','/g2MwFq3htJm55jkAOnm2VGaD8qK.jpg',2.839986380487161,3,'2026-09-10',2,NULL,NULL),(46415,'Neal \'n\' Nikki','Neal \'n\' Nikki','搞笑、空洞又惊喜！故事发生在加拿大不列颠哥伦比亚，讲述了两个出生成长在加拿大的印度人，一次奇妙的旅程改变了他们的一生:)','Nice is out...Naughty is in',0,0,0.285131,2.3,4,122,'2005-12-09','en','/aCjfuhKLvnH4K1QaxB2GJkGicWY.jpg',2.177672178446205,3,'2026-09-10',2,NULL,NULL),(46420,'夺命之爱','The Loved Ones','17岁的叛逆男孩布兰特，还没拿到驾照就开车载着父亲开在乡间的路上，没有注意到突然出现在路中央的浑身是血的男子，避让之中发生了车祸，父亲丧生...6个月后，低迷期的布兰特在与女友亲热时，女友发现布兰特脖子上的项链坠是一个刀片，得知布兰特始终沉浸在丧失父亲的悲痛之中，并有自残行为。 　　 年终舞会到了，班上最不起眼的女生劳拉邀请布兰特作为自己的舞伴但遭到拒绝。对此劳拉怀恨在心，在父亲的帮助下绑架了布兰特，并对其进行了惨绝人寰的折磨...失踪后布兰特的女友及母亲都焦急的寻找。 　　 劳拉得意的向布兰特展示自己的纪念簿，里面都是自己喜欢过的男生的，不过他们都已经被劳拉父女残害推下了自家藏尸的地下室，只有一个逃脱，那就是布兰特发生车祸前看到的路中央的男子...关键时刻布兰特用项链坠割断了绳子并进行反击，杀死了劳拉的父亲，这大大的激怒了有恋父情节的劳拉。劳拉决定前往布兰特家以同样的方式去报复布兰特的母亲... 　　 千钧一发之际布兰特急中生智，踏着用尸骨堆起的山，爬出了藏尸的坑，急急的开车回家，路上遇到了劳拉和前来寻找自己的女友，并撞死了劳拉，跟女友安全抵达家中与母亲紧紧的抱在了一起...','Don\'t break her heart',0,0,4.989985,6.6,207,84,'2009-09-13','en','/ydsLYdSiPSIL1LOWWYu7VCvDTT8.jpg',3.0365684394537142,3,'2026-09-10',2,NULL,NULL),(46435,'酣歌畅戏','Topsy-Turvy','在导演迈克·李非凡的戏剧演绎中，吉尔伯特与沙利文的世界被生动呈现——影片聚焦于二人1885年传奇喜剧歌剧《天皇》的创作历程。吉姆·布劳德本特与艾伦·科德勒精湛诠释了这位维多利亚时代举世闻名的编剧与作曲家的角色；他们与一群性情多变的演员们，在筹备这部重要作品时必须同时对抗个人与职业上的困境。本片是一部制作华丽的史诗，既揭示了艺术创作的严酷现实，又凭借精湛的表演与荣获奥斯卡的服装设计及化妆，成为这位当代电影大师作品中一部出人意料又令人愉悦的时代篇章。[标准收藏]','Gilbert & Sullivan & So Much More',0,0,8.628519,6.7,41,160,'1999-09-03','en','/nxHjVAVOFgWbD2RptBBCLVO6SIR.jpg',2.6745062281186778,3,'2026-09-10',2,NULL,NULL),(46503,'所有美好的东西','All Good Things','影片根据纽约历史上最声名狼藉的谋杀悬案改编。  　　1973年纽约地产富豪的儿子Robert Durst（瑞恩·高斯林 Ryan Gosling 饰）娶了美丽的穷学生Kathleen McCormack（克斯汀·邓斯特 Kirsten Dunst 饰）。两人婚后离开 城市，到乡村享受了一段恬静的时光，当返程时卡蒂回到了学校继续学业。一切看似幸福，可1982年Kathleen突然失踪寻访不得。2000年Durst的好友Susan Berman被发现死在家中，20年前的失踪案被重新唤起，Durst因这两个案件受到询问，但都因为证据不足而未受起诉。2001年Durst的邻居Morris Black被杀，尸体被分解，他再一次受到怀疑被起诉，可经著名律师辩护后被无罪释放。直到2004年再次接受审判Durst最终被判5年监禁，媒体将\"百万富翁凶手\"的名号赠予他。','The perfect love story. Until it became the perfect crime.',0,0,20.086645,5.9,286,101,'2010-12-03','en','/oZqL7zEF6Nv6FhE8VMqwf3CAjcQ.jpg',3.0906229123297826,3,'2026-09-10',2,NULL,NULL),(46528,'黄沙武士','The Warrior\'s Way','经过多年在武术和剑术上的修炼，杨（张东健饰）除掉了异族敌人，但有个敌人的女婴，她的微笑瞬间让他心软了下来，不舍得杀她又不能让她免受族人的伤害，杨带着这个婴儿逃离族人，打算去找一位在美国西部边界城镇鲁德镇的老朋友。到达城镇之后，他发现朋友已故，曾经为淘金热而繁荣一时的城镇如今也混乱不堪，仅有为数不多的几个怪人居住，其中包括漂亮的飞刀手琳妮（凯特·波茨维斯饰）以及邋遢醉鬼罗恩（杰佛里·拉什饰）。为避免族人血腥屠杀，杨将女婴决定做城镇新来的洗衣工，为婴孩创造安全的环境，并将其宝剑永远尘封。杨和琳妮意气相投，相见恨晚。杨从琳妮得知，琳妮在一场灭绝人性的屠杀中成为孤儿，琳妮十年来一直策划报复屠杀中的袭击者——上校（丹尼·赫斯顿饰）。在教杨洗衣和照顾婴孩过程中，琳妮发现杨在剑术方面的天赋并请求杨教她武功。在鲁德镇年度圣诞节庆祝会上，上校和他的变节团伙重返城镇，威胁毁掉城镇。知道琳妮会不惜一切代价找上校报仇，杨充分意识到其剑上的环回暴露他的来历和杀人事实，杨还是迫于无奈拔出了宝剑。他带领着镇上勇猛机智的市民，仅仅携带临时准备的武器及一套作战技巧全力以赴迎战上校，但是，正如杨所担心的，他的挥舞宝剑的声音将那些无情的侵略者引来战斗并使杨、琳妮和市民走向最终的命运。','Assassin. Hero. Legend.',42000000,11087569,7.349497,6.3,136,100,'2010-12-02','en','/otjBqNDpZ3C9mzfDOI4kaiib3Qd.jpg',2.92777502956059,3,'2026-09-10',2,NULL,NULL),(46529,'关键第四号','I Am Number Four','作为从外星球为了躲避茅迦人的杀戮而逃到地球的九个青少年之一，约翰·史密斯这个帅气的年轻人是其中的第四号。茅迦人为了斩尽杀绝，也追踪他们到了地球，前三号已经死在他们手中。茅迦人的下一个目标就是第四号--约翰·史密斯。这时史密斯已经和自己的保护者逃亡到了天堂镇，他邂逅并爱上了美丽的女同学萨拉，也认识了痴迷研究外星人的朋友萨姆。危险在步步逼近，茅迦人已经发现了史密斯的行踪。 这位关键第四号在萨姆和突然现身的第六号的帮助下，施展自己的超能力，击败了邪恶的茅迦人。他和第六号也要踏上新的旅程，去寻找其它的四个同伴。','Three like him have already been killed…he is Number Four.',50000000,144492830,43.450266,5.9,1567,109,'2011-02-18','en','/1ck7OEfHOjRDuGeP1Yk7InvOxBO.jpg',3.487162647498401,3,'2026-09-10',2,NULL,NULL),(46705,'蓝色情人节','Blue Valentine','本片讲述了一段爱情从萌芽到消逝的故事，在过去与现在的时光交错中徐徐展开。迪恩与辛迪被往昔恋爱时的浪漫记忆所淹没，试图用一夜时间来挽救他们岌岌可危的婚姻。真诚描绘了一段濒临破裂的情感关系。[韦恩斯坦公司]','Nobody Baby But You And Me',3500000,16566240,26.881611,6.9,890,112,'2010-12-27','en','/2BRjIYwn4LVgzL7T6zJ9Cu2PCxf.jpg',3.500023861675238,3,'2026-09-10',2,NULL,NULL),(46727,'Speedway Junky','Speedway Junky','A naive drifter runs away from his army father in hopes of making it on the car racing circuit. In Las Vegas, he meets a young scam artist, who develops a crush on him. He is then introduced to a whole gang led by a young hustler. The racer-to-be then gets a lesson in the wild side, getting involved in one situation after another. Patsy Kensit makes a cameo as another hustler and Daryl Hannah appears as the scam artist\'s surrogate mom.','There\'s no place for dreams on the streets of Vegas',1000000,0,0.340019,5.2,7,104,'1999-02-11','en','/tk5Y7CIC9B4a2mXx8pOB1wJJwHN.jpg',2.2834981237264342,3,'2026-09-10',2,NULL,NULL),(46729,'挽救科迪','Fetching Cody','一个街头小子用时间机器挽救女朋友的生命','How far would you go for love?',1,0,0.077876,6.8,6,87,'2005-10-01','en','/p7vuoA0vIldc9t48CRwougpidoj.jpg',2.258194004185275,3,'2026-09-10',2,NULL,NULL),(46738,'焦土之城','Incendies','双胞胎姐弟珍妮（梅丽莎·德索蒙斯-波林 Mélissa Désormeaux-Poulin 饰）跟西蒙（马克西姆·高德特 Maxim Gaudette 饰）收到过世的母亲娜瓦尔（卢布娜·阿扎宝 Lubna Azabal 饰）的遗嘱，可当宣读完内容之后，两姐弟却一时难以接受这样的遗嘱：一份是写给他们从未蒙面的父亲；一份是写给她的第三个孩子——他们更是不知道这个哥哥的存在。影片巧妙的游走在两个不同的时空：母亲终其一生苦苦寻觅自己的长子；姐弟遵循母亲的遗嘱前往中东寻找他们的父亲与兄长。可越是穷其究竟，他们面对的越是理不清的头绪跟令人震惊的真相。本片改编自加拿大著名法语作家瓦基迪·穆阿瓦德的同名剧作。导演丹尼斯·维伦纽瓦荣获第83届奥斯卡金像奖最佳外语片提名。','The search began at the opening of their mother\'s will.',6800000,7103838,21.285206,7.9,479,130,'2010-09-04','fr','/izl7jy8T5AZU3D3ULxg0IGkPiGc.jpg',3.4357456240375535,3,'2026-09-10',2,NULL,NULL),(46829,'巴尼的人生','Barney\'s Version','该片改编自加拿大作家Mordecai Richler1997年的同名传记体小说。\r 　　男主角保罗·吉亚玛提曾获第68届金球奖最佳男主角奖项。\r 　　巴尼·潘诺夫斯基（保罗·吉亚玛提 Paul Giamatti 饰）是一位酗酒、嗜烟、粗俗的曲棍球爱好者和电视导演，65岁的他陷入对自己人生的追忆中。他与信奉自由的灵魂的第一任妻子克拉拉（蕾切尔·李费佛 Rachelle Lefevre 饰）在罗马相识，之后又与富有的犹太公主P夫人（明妮·德里弗 Minnie Driver 饰）相爱，最终，他找到了真爱――第三任妻子米利亚姆（罗莎曼德·派克 Rosamund Pike 饰），并与她养育了两个孩子。而与他的父亲伊西（达斯汀·霍夫曼 Dustin Hoffman 饰）之间，更像是一种与助手的关系。就这样，巴尼带给了我们一种五彩斑斓的人生，而已到暮年的他，对于自己的人生又会有怎样的感受呢⋯⋯','First he got married. Then he got married again. Then he met the love of his life.',30000000,8454301,4.952735,7.2,129,134,'2010-10-26','en','/vdsSaFbBWl8N6RV2XJuPBFyKeV8.jpg',2.9511463706793255,3,'2026-09-10',2,NULL,NULL),(46838,'双宝斗恶魔','Tucker and Dale vs. Evil','一对死党塔克和戴尔在林子里工作，结果因为外貌比较粗犷被一群放假旅游的学生当成了传说中的森林杀手。而当其中一个学生艾莉森溺水被戴尔救起的时候，学生们还以为戴尔是要把艾莉森拖往林中木屋生死，为了救自己的同伴，这些学生一个一个的在活宝兄弟面前假装自杀好让他们放了艾莉森，面对这失控的场面，塔克和戴尔只想知道为什么这帮脑残学生非在自己的地方整死自己不可。','Evil just messed with the wrong hillbillies.',5000000,5476793,19.940245,7.3,847,89,'2010-01-22','en','/m4JdqFM9Cd0jL6MuU620hL8bL2p.jpg',3.535041340044409,3,'2026-09-10',2,NULL,NULL),(46849,'海豚之眼','Eye of the Dolphin','Alyssa is a troubled 14-year old, suspended from school a year after her mother has drowned. Her grandmother Lucy, at wit\'s end, decides to take Alyssa to her father, James, whom Alyssa thought was dead for years. He studies dolphin communication at Smith\'s Point, on the Grand Bahama Island. James has not known of Alyssa\'s existence and is clueless about parenthood. The women arrive at the same time that James may lose his research operation to a tourist attraction. Father, daughter, dolphins, and town are on a collision course. Alyssa and James get encouragement from James\'s girlfriend and her father. It\'s the dolphins who can teach, and Alyssa who discovers how to listen.','She found her voice in the ocean... And within herself.',2500000,71904,0.301884,7.1,7,100,'2007-08-24','en','/8oaWtuz9pfRtCOtHQ5KIWB3vnYP.jpg',2.288836410486263,3,'2026-09-10',2,NULL,NULL),(46889,'Living Out Loud','Living Out Loud','Dramatic comedy about two unlikely people who find each other while looking for love. Judith Nelson (Holly Hunter) is suddenly single after discovering her husband of fifteen years, a successful doctor (Martin Donovan), has been having an affair with a younger woman. Judith stews, plans, plots and fantasizes, but she can\'t decide what to do with her life until she goes out to a night club to see singer Liz Bailey (Queen Latifah), who is full of advice on life and love. While out on the town, Judith is suddenly kissed by a total stranger, which opens her eyes to new possibilities ... which is when she notices Pat (Danny De Vito), the elevator operator in her building.',NULL,12000000,12902790,0.700792,5.3,11,100,'1998-10-30','en','/uegG68vP7leUDQbG8fP4ihgTo0i.jpg',2.37134717136124,3,'2026-09-10',2,NULL,NULL),(46989,'蓝色大车','Blue Car','18岁的梅根自从父亲驾驶着蓝色汽车离开后，便给撇弃不顾，就在读高校最后一年的她，遇上她人生的救生索 ─ 她的诗歌老师：奥斯特先生。他发掘她的天赋才能，使她成功，而且似乎是真心真意地关心她，那是她人生中从未经历过的。\r 梅根每天都活于两个完全不同的世界。家中的生活是黑暗的，在学校的日子是充满希望的。就在梅根为诗歌比赛作准备时，家里开始四分五裂，她崩溃了，她只有一条出路：奥斯特先生。','Ready or not... the future comes just the same.',1000000,464000,0.672695,6.7,13,92,'2002-01-11','en','/6xld6dA6rlctR9mUtcVRigZTfu5.jpg',2.411472713474002,3,'2026-09-10',2,NULL,NULL),(47088,'多余的人','The Extra Man','因为自己小小的特殊癖好被人发现，艾维斯（保罗·达诺 Paul Dano 饰）不得不离开了自己热爱的工作岗位，希望改头换面的他来到了纽约，并很快就找到了一份稳定的工作。表面上看来，艾维斯的新生活过得风生水起，但真实的情况，却只有他自己心里清楚。','They\'re not gigolos, they\'re gentlemen.',7000000,453079,2.26778,5.9,29,108,'2010-08-01','en','/tkQkXXedFIe9HrVgl6wOfKMJQet.jpg',2.575081010114816,3,'2026-09-10',2,NULL,NULL),(47327,'狂暴飞车','Drive Angry','故事讲述尼古拉斯·凯奇饰演的暴徒弥尔顿，他冲出地狱寻找最后一次赎罪的机会。弥尔顿意图阻止一群邪教徒在月圆之夜、用他的孙女完成祭祀仪式，但他只有三天时间……在艾梅柏·希尔德饰演的性感女招待Piper的帮助下，他追踪邪教头目Jonah King的行踪，因为King相信，他注定要牺牲婴儿来献祭，以开启地狱的大门。当然麻烦还不止这些，弥尔顿还要面对警察的追捕以及一个名叫“The Accountant”的神秘杀手（威廉·菲德内尔 饰演）的追杀，传说他是由魔鬼派来，为了将弥尔顿重新带回地狱……','One hell of a ride.',50000000,28931401,30.387148,5.3,600,105,'2011-02-24','en','/h31PXb8GuaZEGBzPqNNHVoaX4XP.jpg',3.182522886428276,3,'2026-09-10',2,NULL,NULL),(47452,'长岛爱与死','Love and Death on Long Island','古板的作家吉尔斯-德阿斯是个鳏夫，对现代流行文化非常反感，他试图买一张 E.M. 福斯特小说改编电影的票，却发现自己在看一部俗气的青少年性喜剧。然而，当美丽的罗尼-博斯托克（Ronnie Bostock）出现在电影银幕上时，盖尔斯发现自己陷入了一股旋风之中，对自己的性取向以及自己在 20 世纪晚期社会中的地位都产生了疑问。',NULL,0,0,0.933891,6.9,11,93,'1997-01-01','en','/2jCmP9j43QXy48oQFpzM4oaYRc7.jpg',2.3790202470591124,3,'2026-09-10',2,NULL,NULL),(47502,'非常背叛','Faithful','一名结婚已经二十年的贵妇玛格丽特，她正在迎接结婚周年的到来时却发现了丈夫杰克有外遇，心里感到十分沮丧。此时，杰克雇请的杀手东尼闯进她家将她捆绑，然后等候杰克的下一步指示。伤心的玛格丽特苦苦哀求东尼帮她结束生命，引起了东尼的好奇心想知道这对夫妻在搞什么？','A comedy about a wife, her husband and his hit man.',13000000,9789900,1.647335,4.8,4,91,'1996-04-03','en','/nbDb2ESmcDT2tDpwdgOPPReRSl6.jpg',2.184879672893576,3,'2026-09-10',2,NULL,NULL),(47534,'Fighting Tommy Riley','Fighting Tommy Riley','An aging trainer and a young fighter, both in need of a second chance, team-up to overcome the demons of their past...and chase the dreams of their future.',NULL,0,0,0.045429,5.3,4,0,'2005-05-06','en','/19nKfguTd9HZhYkh1SEnMulhitI.jpg',2.182039794852555,3,'2026-09-10',2,NULL,NULL),(47546,'I Want Your Money','I Want Your Money','Two versions of the American dream now stand in sharp contrast. One views the money you earned as yours and best allocated by you; the other believes that an elite in Washington knows best how to allocate your wealth. One champions the traditional American dream, which has played out millions of times through generations of Americans, of improving one\'s lot in life and even daring to dream and build big. The other holds that there is no end to the \"good\" the government can do by taking and spending other peoples\' money in an ever-burgeoning list of programs. The documentary film I Want Your Money exposes the high cost in lost freedom and in lost opportunity to support a Leviathan-like bureaucratic state.','The film contrasts two views of role that the federal government should play in our daily lives using the words and actions of Ronald Reagan and Barack Obama.',0,0,0.084344,3.8,5,92,'2010-07-06','en','/ukFRXI9Dg9JdjebQPFde7Gfel3.jpg',2.2183209602551575,3,'2026-09-10',2,NULL,NULL),(47607,'微型家具','Tiny Furniture','女大学生欧拉大学毕业后返家与作为艺术家的母亲和妹妹同住，对生活感到迷惘的她，在工作和生活中接触到了形形色色的人，也试图弄清楚未来的方向。','Aura would like you to know that she is having a very, very hard time.',65000,416498,2.380332,5.6,59,99,'2010-11-12','en','/5T81WvUlc1Our3UwmluXBBc3L0k.jpg',2.7167726645585852,3,'2026-09-10',2,NULL,NULL),(47686,'欲海狂情','Dream with the Fishes','Terry is a suicidal voyeur who treats a dying addict to a final binge, but Terry will only do this if he promises to kill him.','An oddball odyssey about voyeurism, LSD and nude bowling!',0,0,0.948316,7.7,10,97,'1997-01-01','en','/wEYVS0WSCC7ZtT9D1ZnpGA3RvDK.jpg',2.3630939205897605,3,'2026-09-10',2,NULL,NULL),(47692,'意外的旅程','Felicia\'s Journey','爱尔兰少女费丽莎（Elaine Cassidy 饰）的男友尊尼赴英国打工音信全无，父亲认为尊尼参加了英军而勃然大怒反对他们结婚，费丽莎无奈之下以怀孕之身赶赴英国寻人，一无所获之际遇到了乔（Bob Hoskins 饰）。乔因依恋母亲，虽年过半百仍未婚娶，他留有所有母亲主持烹饪节目的录像带每日观看。乔为费丽莎的寻人之旅提供了多次帮助，但暗中却偷走了女孩的钱，费丽莎无处可去只得借宿乔家中，乔为方便接触费丽莎，虚构出在医院奄奄一息的妻子。原来乔有搭讪街头落魄女孩，然而把她们诓骗至家中杀死的爱好，乔又一次即将达到目的时，两名传教人员的到来让形势出现了转机……  本片获2000年加拿大吉尼奖最佳摄影奖等多项褒奖。',NULL,0,0,0.470645,6.6,23,116,'1999-11-24','en','/itqEwiINuYvaqvFKw5YWitnqAUc.jpg',2.529438523339183,3,'2026-09-10',2,NULL,NULL),(47816,'3 Strikes','3 Strikes','Brian Hooks plays a character who is just released from jail. And the state adopts a \"3 strikes\" rule for felons that involves serious penalties. Hooks has 2 strikes, and wants to change his life for the better. When a friend picks him up, they are pulled over, and his friend shoots at police officers, and Hooks escapes. Now Hooks, a wanted man, must clear his name of having nothing to do with the shooting.','the few, the proud, the paroled.',6000000,9000000,1.433692,5.9,15,82,'2000-03-01','en','/ca7xVIgh7UYsFOCBLP8ERmBktC5.jpg',2.43783029082038,3,'2026-09-10',2,NULL,NULL),(47889,'Ruby in Paradise','Ruby in Paradise','Reeling from her mother\'s recent death, Ruby Lee Gissing relocates to Florida to start anew. After finding a job at a souvenir store, Ruby becomes friends with the shop\'s owner, Mildred Chambers, and slowly acclimates to her new surroundings. Before long, she\'s juggling the affections of Mildred\'s Lothario son, Ricky, and the good-natured Mike. As she wavers between Ricky and Mike, Ruby also tries to come to terms with her past.','A woman\'s search for herself.',800000,1001437,0.59424,5.6,10,114,'1993-10-08','en','/gk0vbIVYwpXxSf1wQbS2r9IsBoV.jpg',2.3537535313163183,3,'2026-09-10',2,NULL,NULL),(47890,'大探索','Sphinx','Egyptologist Erica Baron finds more than she bargained for during her long-planned trip to The Land of the Pharoahs - murder, theft, betrayal, love, and a mummy\'s curse!','Someone is hunting tourists out of season.',14000000,439564,0.310513,6,2,118,'1981-02-11','en','/kqAEPlF6TzBHZJK5RKusam0Y79Y.jpg',2.0729597855302933,3,'2026-09-10',2,NULL,NULL),(47933,'Independence Day: Resurgence','Independence Day: Resurgence','We always knew they were coming back. Using recovered alien technology, the nations of Earth have collaborated on an immense defense program to protect the planet. But nothing can prepare us for the aliens’ advanced and unprecedented force. Only the ingenuity of a few brave men and women can bring our world back from the brink of extinction.','We had twenty years to prepare. So did they.',165000000,389681935,48.775723,4.9,2491,120,'2016-06-22','en','/zvUPCBSAOEXO3LevxADVEeCzHRu.jpg',3.3619970038285936,3,'2026-09-10',2,NULL,NULL),(47941,'Under the Rainbow','Under the Rainbow','In World War II era Los Angeles, the manager of the Culver Hotel leaves his nephew in charge for a weekend. The nephew changes the name to the Hotel Rainbow and overbooks with royalty, assassins, secret agents, Japanese tourists, and munchkins (from the cast of _Wizard of Oz, The (1939)_ ). Secret Service agent Bruce Thorpe and casting director Annie Clark find romance amidst the intrigue and confusion.','Who knew so many little people would throw such a huge party?',20000000,2297493,0.173964,4.9,7,98,'1981-07-31','en','/mCdXzpghn4tPz6hbQcvS2UwOh1C.jpg',2.282262180176373,3,'2026-09-10',2,NULL,NULL),(47964,'虎胆龙威5','A Good Day to Die Hard','由布鲁斯·威利斯所饰演的超级\"平凡英雄\"约翰麦克莱恩又回来了。这次他为了去俄罗斯救惹事的儿子杰克出监狱，向警察局告了假，以游客身份来到俄罗斯首都莫斯科。到了莫斯科，他意外发现杰克在当地为美国中情局执行着一项惊天任务：保护被逮捕的俄罗斯大亨并带他到中情局指定地点交人。可由于老爸约翰的出现，杰克错过了完成第一方案任务的时机，只好跑到备用安全房，但是也很快暴露遭到伏击。随后，三人与大亨的独女约好去取藏有揭发当局某高层进行核武交易罪证文件的钥匙。然而，这次见面差点要了父子俩的命，大亨的女儿为了钱，竟然绑架亲爹出卖了他们。而随着事态的发展，他们发现这一切的幕后操作者居然是大亨本人，其真正目的是要贩卖核武原料。生死关头，这对原本就意见不和的父子必须一起出生入死，冲出危险。即使个性迥异，冲突不断，却也因为血浓于水的亲情开始无间合作，共同面临一触即发的灾难。最终，父子俩人经过与恐怖分子的殊死搏斗，将其一网打尽，避免了核武原料的外流。','Yippee Ki-Yay Mother Russia',92000000,304654182,65.402595,5.2,3493,98,'2013-02-06','en','/vYq1hKEwamInyEgFLX7WH2Q1V5o.jpg',3.528296461498514,3,'2026-09-10',2,NULL,NULL),(48034,'小小的白色谎言','Les Petits Mouchoirs','每一年，餐馆老板马克思（弗朗索瓦·克鲁塞 François Cluzet 饰）都会请他的朋友们来到他在海边的别墅度假，而这一年的假期，却被一场发生在卢多（让·杜雅尔丹 Jean Dujardin 饰）身上的严重车祸蒙上了阴影。为了冲淡悲伤，朋友们决定像往常一样前往海边。  　　文森特（伯努瓦·马吉梅 Benoît Magimel 饰）的心情非常沉重，他发现他对自己同性好友马克思的爱意随着时间的流逝愈演愈烈，已经到了无法掩饰的地步，但事实是，他们均已结婚生子。玛丽（玛丽昂·歌迪亚 Marion Cotillard 饰）也不轻松，她身边围绕着一群她并不喜欢的男人，真正爱着的，却是此刻躺在病床上生命垂尾的前男友卢多，并且，在这个节骨眼上，她发现自己有了身孕。一向对自己的魅力充满自信的安东尼（Laurent Lafitte 饰）却被劈腿，表面上豁达的他却不能克制的一遍遍的质问心上人为何将他抛弃。  　　每个人都想在这宁静的海边短暂的忘却烦恼，但烦恼又是如此狡猾的在千疮百孔的生活中无孔不入，于是，作为成年人，他们不得不互相编制起小小的，善意的白色谎言。 ©豆瓣','The one thing friends can\'t escape is a few home truths.',25000000,48531470,15.279021,7.1,380,154,'2010-10-20','fr','/qoHIdk4jZTwNjRz23ql3TO8yH9b.jpg',3.260696597129415,3,'2026-09-10',2,NULL,NULL),(48035,'词语','Ordet','故事发生在丹麦一个宗教氛围极浓的村子里，农夫波根有三个儿子，大儿子对宗教持怀疑态度，性情叛逆；小儿子居然与不同信仰的女孩谈恋爱，而影片的主角、三兄弟中的老二相信自己就是耶稣，被大家当成疯子，因为本来读神学的他在经历未婚妻离世后打击太大而成疯癫；但有一天老二开始“显灵”，让死人复活，自己的神智也开始恢复。',NULL,0,0,3.225189,7.8,65,126,'1955-01-09','da','/e3oh96Zrqdaku8DoD10pXZHLZoU.jpg',2.7923920595238845,3,'2026-09-10',2,NULL,NULL),(48138,'不明身份','Unknown','马丁·哈里斯博士（Liam Neeson）在柏林遭遇一场车祸后从昏迷中苏醒，发现妻子（January Jones）突然不认识自己了，而另一个陌生人（Aidan Quinn）盗用了他的身份。柏林当地警署对他的申诉将信将疑，无意展开调查，同时又有杀手不断追杀。虽然希望渺茫，在异国他乡举目无亲的马丁，别无选择地试图从一个偶然结识的人（Diane Kruger）那里，获得援助。一场突如其来的意外让他身陷绝境，致命的谜团死死缠绕着他，逼着他开始质疑自己是否神经正常，他的身份怎么丢了，他还要冒多大的生命危险才能查出事情的真相，一场无助的亡命之旅就此展开。','Take Back Your Life',30000000,130786397,38.643914,6.5,1265,113,'2011-02-16','en','/goA9moQ3BYVsPPiGdA8n6bHrVx5.jpg',3.54701943798117,3,'2026-09-10',2,NULL,NULL),(48171,'The Rite','The Rite','Seminary student Michael Kovak (Colin O\'Donoghue) reluctantly attends exorcism school at the Vatican. While he’s in Rome, Michael meets an unorthodox priest, Father Lucas (Anthony Hopkins), who introduces him to the darker side of his faith, uncovering the devil’s reach even to one of the holiest places on Earth.','You can only defeat it when you believe.',37000000,96047633,11.492474,5.8,556,114,'2011-01-28','en','/rQTsktdRwKl4OosGJrXhAInIQtI.jpg',3.192364844331978,3,'2026-09-10',2,NULL,NULL),(48217,'雪地里的情人','La Veuve de Saint-Pierre','故事发生于1849年，在加拿大沿海法属一个岛上，渔夫尼尔酒醉后杀了人，被判处死刑。根据法国的法律，他需要被断头处决，但岛上并没有断头台，需要从千里迢迢的母国运送过来。在等待的日子里，他被交由部队上尉羁押看管。然而，和蔼、纤细、相信性本善的上尉夫人则看到尼尔有着纯真善良的一面。在获得丈夫的许可后，夫人开始让尼尔整理花园、修屋顶、并跟着她在岛上帮忙慈善事业。慢慢地，岛上的市井小民开始喜欢他，一次他勇敢救人的事迹，更让他成为地方英雄。夫人与犯人间，也产生了微妙的情感。然而，断头台还是到了，夫人设法营救尼尔，深爱妻子的上尉也因此违抗地方政府的命令。',NULL,0,0,1.780065,6.7,11,112,'2000-01-01','en','/dBV8yw7t9Glq1JmhfTemG0Thhqq.jpg',2.380060496023641,3,'2026-09-10',2,NULL,NULL),(48231,'A Dangerous Method','A Dangerous Method','Seduced by the challenge of an impossible case, the driven Dr. Carl Jung takes the unbalanced yet beautiful Sabina Spielrein as his patient. Jung’s weapon is the method of his master, the renowned Sigmund Freud. Both men fall under Sabina’s spell.','Why deny what you desire the most.',15000000,27462041,27.133277,6.2,571,99,'2011-09-30','en','/xCAplIDLIOehYk8KjSA2GsYHyeL.jpg',3.2859787748230262,3,'2026-09-10',2,NULL,NULL),(48289,'The Debt','The Debt','Rachel Singer is a former Mossad agent who tried to capture a notorious Nazi war criminal – the Surgeon of Birkenau – in a secret Israeli mission that ended with his death on the streets of East Berlin. Now, 30 years later, a man claiming to be the doctor has surfaced, and Rachel must return to Eastern Europe to uncover the truth. Overwhelmed by haunting memories of her younger self and her two fellow agents, the still-celebrated heroine must relive the trauma of those events and confront the debt she has incurred.','Every secret comes with a price.',20000000,45636368,14.857884,6.3,257,113,'2010-04-11','en','/zlavkPAIzIIQppcU9vcQrKZjfmb.jpg',3.088192109217026,3,'2026-09-10',2,NULL,NULL),(48309,'鬼哭山河','Prison','封闭多年的克利得摩监狱再度开张，新进的典狱长和囚犯们却发现这尘封已久的黑牢隐约透着一丝不寻常。果然，怪事接连发生，黑暗中疯狂愤怒的幽灵正以残酷手段发磨着牢狱中的囚犯。为了拯救无辜者的性命，囚犯康尼和犯罪学家凯萨琳试图找出恶灵大肆凌虐的原因，并得知唯有揭露三九年前随着监狱关闭一起深埋的秘密，才能终止这场腥风血两，而这个秘密只有当年曾担任过监狱警卫的典狱长知道……','Horror Has A New Home.',1300000,354704,7.605291,6.7,27,102,'1988-03-04','en','/bB6iCnYO1dlVA1kZp04acFyXTpg.jpg',2.581031613990177,3,'2026-09-10',2,NULL,NULL),(48340,'夺命深渊','Sanctum','拥有丰富潜水经验的弗兰克·麦克盖尔数月以来都在南太平洋的沿岸几内亚的埃萨阿拉附近潜水探险,兼带进行一些洞穴探险。不过这些小打小闹的探险无法满足麦克盖尔的雄心壮志,因为当地有一个尚未被探明的巨大洞穴。这个被人尊称为“洞穴之母”的洞穴是世界上最大、最深、结构最为复杂、最危险,也是最雄伟、最美丽的洞穴。为了成为名垂历史的探险家,并创造人类洞穴潜水的世界纪录,麦克盖尔拉来了投资,找来了一批精兵强将,准备下洞穴探险。　　开始的一切非常顺利,所有的队员都显示出了良好的专业素质,所有的装备都是顶级的,所有的计划看上去都天衣无缝。不过随着探险小队的深入,大自然开始渐渐发威--路越来越狭窄、水流越来越湍急、水下的地形也越来越复杂。这时候,几内亚计入了雨季,强热带风暴袭击了这个国家。连续的大雨致使河水上涨,地下的水位也随之上升。雨水倒灌进洞穴深处,在地底形成了“洪水”。巨大的洪水成为了探险小组的障碍,在失去几名队员之后,麦克盖尔和队内的乔什以及他们的资助人卡尔·何雷面对着食物和饮用水的短缺,不得不改变原先走回洞口的逃生计划。他们只有通过潜水的方法,在复杂如迷宫搬的洞穴水体中,找到通往海洋的道路。　　这时候,麦克盖尔不得不去思考一个问题,那就是主宰着人类性命的什么?是人类自己还是伟大的自然的伟力?或许在洞穴的处境里,人类只是匆匆而渺小的过客。','The only way out is down.',30000000,108609310,20.063165,5.8,339,108,'2011-02-03','en','/ic6WWQmdcnHhWABCeiIkCnXEv19.jpg',3.115566171081504,3,'2026-09-10',2,NULL,NULL),(48382,'The Book of Mormon Movie, Volume 1: The Journey','The Book of Mormon Movie, Volume 1: The Journey','The story of Lehi and his wife Sariah and their four sons: Laman, Lemuel, Sam, and Nephi. Lehi leaves Jerusalem because he prophesied unto the people concerning the destruction of Jerusalem, and they sought his life. He journeys into the wilderness with his family. He sends Nephi and his brethren back to Jerusalem after the brass plates and the family of Ishmael. The sons and daughters of Lehi marry the sons and daughters of Ishmael. They take their families and continue into the wilderness. Ishmael dies in the wilderness. They come to the sea. Nephi\'s brethren rebel against him. He confounds them, and builds a ship. They cross the sea to the promised land in the Americas. Lehi dies in the promised land. Nephi\'s brethren rebel against him again. Nephi departs again into the wilderness.','2600 years ago, one family began a remarkable journey and set the course for a latter-day faith. This is their story.',2000000,1672730,0.031947,5,2,120,'2003-09-12','en','/ov4rsTmjJ28jUnSRRYwhIGWUWUn.jpg',2.071502052443575,3,'2026-09-10',2,NULL,NULL),(48463,'尼斯湖事件','Incident at Loch Ness','不能说太多没有给关键因素了。刚看到这个在波士顿筛选并认为这是我在过去的两年里看到的更聪明独立电影之一。任何电影迷，科幻迷，或纪录片爱好者会发现这是一个非常有创造力，良好的执行，具有很强的娱乐片。看起来这将是不可原谅的沃纳·赫尔佐格的不看这部电影的任何风扇。你不必成为他电影的粉丝彻底享受这个文档，虽然。我以前从未见过他的电影之一，但我去的权利，并看到这部电影后，租了他们。伟大的摄影，奇幻剧情，有的笑，有的很可怕的镜头，你不会相信你刚才看到的！',NULL,1,0,1.452152,5.9,18,94,'2004-12-17','en','/hsBmbcL4KiZerEwFJO4BHlvnbA8.jpg',2.4749380889042794,3,'2026-09-10',2,NULL,NULL),(48572,'红色之州','Red State','在一个平凡的美国小镇，同性恋男孩被人杀害，他的死却引起了广泛争议。自称代表上帝的牧师艾宾·库伯（麦克·帕克斯 Michael Parks 饰）带领信众游行示威，控诉着世间各种丑态与罪行。另一边，高中生特拉维斯（Michael Angarano 饰）、贾罗德（Kyle Gallner 饰）、比利-雷（Nicholas Braun 饰）却相约夜晚出行，寻找属于青春时代的放浪与刺激。谁知渴望狩猎的少年，反倒成了他人的猎物。他们落入库伯及其信众的陷阱，随时都会失去生命。 　　另一方面，美国枪支管理局的特工约瑟夫·吉南（约翰·古德曼 John Goodman 饰）逐渐掌握库伯囤积枪支的证据，一场无关正义与道德缺失的攻防战即将展开……','Fear God.',4000000,1104682,12.062371,5.9,316,88,'2011-08-19','en','/mbukOgivZWGNAxEQVt4hLUVME2P.jpg',3.092567021305914,3,'2026-09-10',2,NULL,NULL),(48620,'女人的胜利','The Mighty Macs','故事的背景设定在1972年，女权运动正进行的如火如荼。主人公凯西去了一家天主学校教篮球，学校里全都是女生，而且既没有体育馆，也没有统一的队服。更让人沮丧的是，学校正面临着被卖给房地产开放商的危险。在种种困难中，凯西还是带领她一手培养出来的篮球队，打进了第一届全国女子篮球锦标赛。',NULL,7000000,0,2.932784,5,15,102,'2009-10-21','en','/frNp8Rmkr8wBDyKrZ89gYvrtxBa.jpg',2.435806792662658,3,'2026-09-10',2,NULL,NULL),(48988,'嘿咻卡','Hall Pass','《嘿咻卡》出自专攻低速喜剧和厕所幽默的法拉利兄弟之手。Hall Pass是在美国和加拿大，学生使用的一种“特权卡”。当在上课或者是在讲座中，如果有特殊情况就可使用这种卡片就可以临时走出教室。 里奇（欧文·威尔逊 Owen Wilson 饰）与弗雷德（杰森·苏戴奇斯 Jason Sudeikis 饰）是一对非常要好的朋友。他们虽有稳定的婚姻，但总也免不了幻想一番艳遇，对来来往往的女性充满了幻想。二人的老婆想出一个大胆的招数，给他们一个星期的特权，让他们放风一周，绝不过问他们的生活。当拿到七天的“嘿咻卡”后两人觉得美梦终于成真，和几位已婚的朋友过上了梦想中的生活。但是这样的自由快乐单生活却又带来始料未及的难过与痛苦。原来自由自在的生活一点也没有家庭生活愉快。发现了这些的里奇和弗雷德恍然大悟，开始拼命向家庭回归……','One Week, No Rules',36000000,83160734,27.11589,5.4,611,105,'2011-02-25','en','/yd64cz223MBcoNbWFTFMciur44c.jpg',3.1915762840813855,3,'2026-09-10',2,NULL,NULL),(49010,'持枪流浪汉','Hobo with a Shotgun','一个老流浪汉（Rutger Hauer 饰）路经一座被疯狂犯罪行为所笼罩的城市，这里充斥着杀童、强迫卖淫等等极恶罪行，暗中统治这里的德瑞克一家热衷于当街杀人，老德瑞克（Brian Downey 饰）和两个儿子横行街头。流浪汉从德瑞克之子的手中救下妓女艾比（Molly Dunsworth 饰），结果反被警察设计陷害，身受重伤。流浪汉试图遵守这座罪恶之城的生存法则，忍辱求生，然而事与愿违，抢劫案偏偏又找上他，忍无可忍的流浪汉终于决定拿起枪寻求公平，他对暴力罪犯大开杀戒，在城市中引发了居民群起反抗的热血，德瑞克一家同样不甘示弱，借助媒体发布了针对所有流浪汉的绝杀令，一时间，罪恶之城血流成河……','Delivering justice, one shell at a time...',3000000,748453,16.900433,5.7,211,86,'2011-05-06','en','/xxMaO7VoN2BnZit79PedVHnTjcO.jpg',3.007752187939774,3,'2026-09-10',2,NULL,NULL),(49013,'赛车总动员2','Cars 2','和上集一样，由欧文·威尔逊配音的主角“闪电麦昆”（Lightning McQueen）依然要参加各种赛车比赛，不过这次他将跨出美国国门、周游世界。拉塞特透露，麦昆和他的团队将辗转5个国家，参加F1赛车和拉力赛的重大赛事：第一站是日本东京，他们要从富士山出发，往市区开；第二站是德国，他们要穿过黑森林；第三站是意大利的“Porto Corsa”大赛，它类似于蒙特卡洛汽车大赛；第四站是巴黎的24小时拉力赛；最后一站是伦敦，这也是全片的高潮部分，终点是白金汉宫，有趣的是王宫守卫也是汽车（路虎）。\r 除了精彩的赛车部分，在《赛车总动员2》中还有另一条故事线，主要是围绕拖车板牙（Mater）展开的，这个角色由“有线电视的拉瑞”（Larry the Cable Guy，艺名）配音。拖车板牙在救了一个英国秘密特工“Finn McMissile”（车型为阿斯顿·马丁）后，被人错当成间谍，卷入了麻烦之中。','Ka-ciao!',200000000,559852396,49.98659,5.8,2033,106,'2011-06-11','en','/tTfutdvOthTneSmEhqetSyR067R.jpg',3.5330932884341824,3,'2026-09-10',2,NULL,NULL),(49017,'德古拉元年','Dracula Untold','15世纪中叶，作风彪悍残忍的穿刺王弗拉德（卢克·伊万斯 Luke Evans 饰）在土耳其苏丹的扶持下回到故乡特兰西瓦尼亚，建立起一个和平祥和的国家。然而此时此刻他仍受制于土耳其苏丹王穆罕默德（多米尼克·库珀 Dominic Cooper 饰），苏丹要求弗拉德献上一千个男孩充军，包括他儿子在内的孩子们都将成为嗜血统治者的牺牲品。不愿孩子重走自己当年血腥之路的弗拉德奋起反抗，屠杀使者。为了赢得战争的胜利，他闯入神秘而恐怖的断牙山，期望借助传说中的怪物之手击退土耳其的入侵者。他为了国家不惜抛弃良知和灵魂，由此注定了千古悲剧的开始。吸血鬼德古拉的传说由此上演……','Every bloodline has a beginning',70000000,215529201,64.457947,6.2,2389,92,'2014-10-01','en','/zyjUmBJILcKhVx64n2ybhsy0gmv.jpg',3.6903074802783324,3,'2026-09-10',2,NULL,NULL),(49018,'潜伏','Insidious','在高中担任教师的乔什·莱姆波特和身为自由音乐人的妻子兰娜拥有一个幸福的五口之家。然而自他们乔迁新居之后，恐慌和不安便尾随而至。尚在襁褓中的女儿凯莉经常莫名大哭，次子福斯特对卧室充满恐惧，而长子达尔顿更在一次惊吓过后陷入长久的昏迷之中。在此之后，各种奇怪恐怖的事件接连发生。莱姆波特夫妇不胜其扰，精神几近崩溃，他们最终决定搬离这个不祥之地。但是一切并未就此结束，侵扰他们的魔鬼似乎尾随莱姆波特一家来至新的住所，更扬言要占据达尔顿的身体。','It\'s not the house that\'s haunted.',1500000,97009150,58.594852,6.8,1737,103,'2010-09-13','en','/8su4HXNbbOHBDT3dIc9aWlL5aZ6.jpg',3.732938477322192,3,'2026-09-10',2,NULL,NULL),(49020,'潜水艇','Submarine','十五岁的奥利弗（克雷格•罗伯兹 Craig Roberts 饰）坐在教室里的时候脑中总是充满各种幻想，周围的一切对他来说都是普通中蕴含奇异的存在。在同学里他总是显得不合群，他注意到同学祖娜（雅思敏•派吉 Yasmin Paige 饰）也是如此。祖娜在铁桥下约见奥利弗并拍下两人亲吻的照片以此来刺激前男友，奥利弗为此付出了被祖娜前男友教训的代价，而这却让两个人真正走在一起了。奥利弗的父母关系紧张，眼下他又发现母亲和隔壁新搬来的格雷厄姆走的很近，他开始试图挽救自己的家庭。而祖娜的母亲正患脑瘤，奥利弗想要解决问题却分身乏术，和祖娜误会重重最终导致两人分手。最后他的父母重归于好，祖娜的母亲也病愈。而他和祖娜将走向什么结局呢？','A comedy that doesn\'t let principles stand in the way of progress.',0,864659,8.518866,7.4,443,97,'2011-03-18','en','/nbzXX3CYtKUBrPeMcG7PVoLQHXB.jpg',3.322988609487626,3,'2026-09-10',2,NULL,NULL),(49021,'Killer Elite','Killer Elite','Based on a shocking true story, Killer Elite pits two of the world’s most elite operatives—Danny, an ex-special ops agent and Hunter, his longtime mentor—against the cunning leader of a secret military society. Covering the globe from Australia to Paris, London and the Middle East, Danny and Hunter are plunged into a highly dangerous game of cat and mouse—where the predators become the prey.','May the best man live.',66000000,57777106,29.501489,6.1,695,116,'2011-09-23','en','/9OaVYS1rQIu5GxhZXg6rIn1dwu2.jpg',3.32062743486948,3,'2026-09-10',2,NULL,NULL),(49022,'大婚告急','Something Borrowed','蕾切尔（金妮弗·古德温 Ginnifer Goodwin 饰）年近三十却依然单身，对于自己的终身大事，这位咋咋呼呼的傻大姐保持着乐观的态度，加上好闺蜜达茜（凯特·哈德森 Kate Hudson 饰）的陪伴，日子过得还算有滋有味。可是，一个“噩耗”的到来让蕾切尔无法继续淡定——达茜即将和男友走入婚姻的殿堂并邀请蕾切尔成为伴娘，而达茜的男友不是别人，正是蕾切尔曾经暗恋过的德克士（科林·伊格斯菲德 Colin Egglesfield 饰）。\r 原来，大学时代的蕾切尔对当时英俊帅气的德克士十分倾慕，可达茜的出现立刻就将德克士的目光吸引了过去，面对好友的横刀夺爱，蕾切尔也只能忍气吞声。现在，当初青涩的三人都已经长大成人，内心的情感早已不复往日的单纯。达茜的婚期将近，蕾切尔绝望的发现，自己已经无法再抑制内心里的蠢蠢欲动。','It\'s a thin line between love and friendship.',35000000,59901913,14.029012,5.9,296,112,'2011-05-05','en','/zB5lhfRFpJRzm2JzyYyWk0mtokM.jpg',3.0837762839749723,3,'2026-09-10',2,NULL,NULL),(49026,'蝙蝠侠：黑暗骑士崛起','The Dark Knight Rises','哈维·登特死后的八年间，哥谭市的犯罪活动受到有效遏制，而背负杀害登特罪名的蝙蝠侠也从城市中销声匿迹，布鲁斯·韦恩则过着与世隔绝的生活。然而，神秘而强大的贝恩突然出现，打破了哥谭维持多年的平静。与此同时，行踪莫测的女贼赛琳娜·凯尔也闯入布鲁斯的生活。随着贝恩的计划逐渐展开，整个哥谭陷入前所未有的危机。面对这个比以往更加强大的敌人，沉寂多年的布鲁斯不得不重新作出选择，再次肩负起守护哥谭的使命……','The Legend Ends',250000000,1084939099,112.31295,7.6,9106,165,'2012-07-16','en','/hr0L2aueqlP2BYUblTTjmtn0hw4.jpg',4.4831814754632,3,'2026-09-10',2,NULL,NULL),(49040,'谍影重重4','The Bourne Legacy','继杰森·伯恩后，另一美国中情局特工艾伦·克劳斯（杰瑞米·雷纳 饰）亦将身陷险境。因为“杰森·伯恩事件”，令中情局的特工行动“绊脚石”被公开，为了隐瞒其它特工行动，以拜亚（爱德华·诺顿饰）为首的美国中情局，正计划铲除过去数十年来发展的特工行动，包括对“结果”行动当中，体能和智能更“先进”的“5号”特工艾伦·克劳斯，展开横跨全球的逃杀。而艾伦·克劳斯剩下的唯一希望，竟然就是过去四年来，不断在背后监控和研究其活动的科学研究员玛泰博士（蕾切尔·薇兹 饰）……','There Was Never Just One',130000000,276572938,90.33681,6,2651,120,'2012-08-08','en','/1aExL5DTGHj25ZfIC3dDwS84RWi.jpg',3.725415545411066,3,'2026-09-10',2,NULL,NULL),(49047,'地心引力','Gravity','瑞安·斯通博士首次执行太空任务，与经验丰富的宇航员马特·科沃斯基搭乘“探索者”号航天飞机，在太空中维修哈勃太空望远镜，而这也是科沃斯基退休前的最后一次飞行。就在两人进行舱外作业时，一颗俄罗斯卫星被摧毁后产生的大量碎片引发连锁碰撞，“探索者”号也遭到重创。突如其来的灾难令两人与地面失去联系，被困在浩瀚无垠的太空之中。面对高速袭来的碎片、不断消耗的氧气和几乎无处可逃的绝境，两名幸存者只能彼此依靠，寻找返回地球的一线生机……','Don\'t Let Go',105000000,716392705,110.153618,7.3,5751,91,'2013-09-27','en','/kZ2nZw8D681aphje8NJi8EfbL1U.jpg',4.281475289819176,3,'2026-09-10',2,NULL,NULL),(49049,'Dredd','Dredd','In the future, America is a dystopian wasteland. The latest scourge is Ma-Ma, a prostitute-turned-drug pusher with a dangerous new drug and aims to take over the city. The only possibility of stopping her is an elite group of urban police called Judges, who combine the duties of judge, jury and executioner to deliver a brutal brand of swift justice. But even the top-ranking Judge, Dredd, discovers that taking down Ma-Ma isn’t as easy as it seems in this explosive adaptation of the hugely popular comic series.','Judgement is coming',50000000,41037742,57.673932,6.6,1940,95,'2012-09-07','en','/wLx65gtGVnUFCxceHWGszcruCZj.jpg',3.715836769724143,3,'2026-09-10',2,NULL,NULL),(49051,'霍比特人1：意外之旅','The Hobbit: An Unexpected Journey','中土最后一座矮人王国埃尔波尔，巍峨壮丽，庄严雄伟。老国王索尔积聚大量财富，却引来恶龙史茅革的觊觎和荼毒，最终导致这座城池陷落。许多年后，灰袍巫师甘道夫（伊恩·麦凯伦 Ian McKellen 饰）找到弗罗多的舅舅——霍比特人比尔博·巴金斯（马丁·弗里曼 Martin John C. Freeman 饰），邀请他加入由13名矮人组成的远征队伍。原来史茅革已多年不见声息，背负家国仇恨的矮人王子索林（理查德·阿米蒂奇 Richard Armitage 饰）希望借此机会收复故土。经过一番考虑，巴金斯决定加入。令他想不到的是，远征旅途多灾多难，与索林结下深仇大恨的苍白半兽人及其爪牙阴魂不散，更有食人鬼和石人制造的无数艰险。而在旅途中，巴金斯也意外得到了日后影响整个中土的重要宝物…','From the smallest beginnings come the greatest legends.',250000000,1021103568,108.849621,7,8297,169,'2012-11-26','en','/yHA9Fc37VmpUA5UncTxxo3rTGVA.jpg',4.286634602827061,3,'2026-09-10',2,NULL,NULL),(49081,'冰球英豪','Maurice Richard','20世纪30年代后期，名叫莫里斯·理查德的一名年轻机械师表现出具有冰球运动员的超常天资。虽然那些表现足够让他进入蒙特利尔加拿大人队，但是频繁的受伤使他丧失了球队和球迷对他的信心。面对怀疑，理查德最终展现了他的上进心和技艺超群，使他成为一直以来最伟大的“火箭（得分）”运动员之一。然而尽管取得了成功，但理查德和他那些法裔加拿大队员在英语语系支配的联盟中，依然受到歧视。原本话语不多的理查德开始发表自己关于不公的看法，并导致一场体制上的冲突，在臭名昭著的1955年赛季停赛期间达到顶峰，抗议激起了种族冲突。面对挑战理查德必须裁决，他到底是在为谁打球。',NULL,8000000,2019009,0.983484,6.1,17,124,'2005-10-25','fr','/2jRjKd4fDXANEWQ0smd5YJwQioE.jpg',2.463578849228939,3,'2026-09-10',2,NULL,NULL),(49365,'白衣幽魂','Lady in White','Locked in a school closet during Halloween 1962, young Frank witnesses the ghost of a young girl and the man who murdered her years ago. Shortly afterward he finds himself stalked by the killer and is soon drawn to an old house where a mysterious Lady In White lives. As he discovers the secret of the woman he soon finds that the killer may be someone close to him.','The year is 1962. The place is Willowpoint Falls. Nobody talks about what happened in the school cloakroom 10 years ago. Now, in the dead of night, Frankie Scarlatti is going to find out why.',0,0,1.435742,6.3,25,112,'1988-04-22','en','/AevfLQ5c0ZGtO3clHawg9L2XAQ2.jpg',2.546413965071678,3,'2026-09-10',2,NULL,NULL),(49444,'Kung Fu Panda 2','Kung Fu Panda 2','Po is now living his dream as The Dragon Warrior, protecting the Valley of Peace alongside his friends and fellow kung fu masters, The Furious Five - Tigress, Crane, Mantis, Viper and Monkey. But Po’s new life of awesomeness is threatened by the emergence of a formidable villain, who plans to use a secret, unstoppable weapon to conquer China and destroy kung fu. It is up to Po and The Furious Five to journey across China to face this threat and vanquish it. But how can Po stop a weapon that can stop kung fu? He must look to his past and uncover the secrets of his mysterious origins; only then will he be able to unlock the strength he needs to succeed.','Prepare for the Year of Awesomeness!',150000000,665692281,51.247321,6.7,1880,91,'2011-05-25','en','/mtqqD00vB4PGRt20gWtGqFhrkd0.jpg',3.7150428250236898,3,'2026-09-10',2,NULL,NULL),(49471,'登上巴士','Get on the Bus','影片跟随一群背景各异的男性，从洛杉矶前往华盛顿参加百万人大游行。旅途中，他们将结交朋友、树立敌人并创造历史。','On October 16, 1996, the one year anniversary of the Million Man March, Spike Lee invites you to lift your head, raise your voice, and...get on the bus.',2400000,5731103,4.623059,7,11,120,'1996-10-16','en','/7p8FvHMSr11LQw9Xv6dPJdrBeU2.jpg',2.387893322218085,3,'2026-09-10',2,NULL,NULL),(49478,'五行战士','Warriors of Virtue','五行战士是道的防御战士，但是，邪恶的灵魔Komodo的出现，破坏了一切，他想将生命之泉据为己有，便展开了他侵略的行动，于是，莱恩在此时加入了五行战士与灵魔奋战的阵容中，一决生死……','In a world beyond your imagination a battle for the universe has begun.',0,0,0.912395,4.7,9,103,'1997-05-02','en','/8fT8cttGyXx36P24W0tum2QxsLf.jpg',2.3306944051301346,3,'2026-09-10',2,NULL,NULL),(49517,'Tinker Tailor Soldier Spy','Tinker Tailor Soldier Spy','Recently-retired MI6 agent, George Smiley is doing his best to adjust to a life outside the secret service until a disgraced agent reappears with information concerning a mole at the heart of the service. Smiley is drawn back into the murky field of espionage, tasked with investigating which of his trusted former colleagues has chosen to betray him and their country. Smiley narrows his search to four suspects – all experienced, skilled and successful agents – but past histories, rivalries and friendships make it far from easy to pinpoint the man who is eating away at the heart of the British establishment.','How do you find an enemy who is hidden right before your eyes?',30000000,0,33.649652,6.6,840,127,'2011-09-16','en','/5ep9pP05lphChmOn5HHh18n9PRr.jpg',3.451352181085957,3,'2026-09-10',2,NULL,NULL),(49519,'疯狂原始人','The Croods','原始人咕噜一家六口在老爸Grug的庇护下生活。每天抢夺鸵鸟蛋为食，躲避野兽的追击，每晚听老爸叙述同一个故事，在山洞里过着一成不变的生活。大女儿Eep是一个和老爸性格截然相反的充满好奇心的女孩，她不满足一辈子留在这个小山洞里，一心想要追逐山洞外面的新奇世界。 没想到世界末日突然降临，山洞被毁，一家人被迫离开家园，与之前和Eep偶遇的有着超凡创造力和革新思想的游牧部落族人Guy展开一场全新的旅程...','Meet the first modern family.',135000000,585178928,64.183321,6.8,2399,98,'2013-03-20','en','/27zvjVOtOi5ped1HSlJKNsKXkFH.jpg',3.8286814553400004,3,'2026-09-10',2,NULL,NULL),(49520,'两男变错身','The Change-Up','米奇和戴夫在一起长大,曾经是最要好的朋友。在一起时间长了,两个人难免会在脾气、性格上有些相似。随着时间的逝去,好朋友也会有自己的生活而疏于联系,所以在成年后,米奇和戴夫简直成了截然不同的两个人。 　　戴夫现在是一个工作勤勉的律师,一个好丈夫和几个孩子的爹;而米奇则依然单身,工作不稳定,年龄不小了却还孩子气十足,从来不为明天考虑,整日和漂亮姑娘厮混。在戴夫的眼里,米奇拥有他所幻想的一切:高薪的工作、极为崇高的社会地位、漂亮的对他崇拜有加的老婆、完满的家庭和和谐的生活。可是在米奇看来,戴夫的那种无忧无虑、没有负担和责任的生活才是“梦想中”的完美。 　　在一个喝得醉醺醺的晚上,两个人对生活大发感慨。在许愿喷泉和女神下尿尿的时候,他们不禁说出了“我想要你的生活”的愿望。结果第二天早上起来,戴夫和米奇互换了身体。 　　有了负担的米奇和丢掉了负担的戴夫对这种互换的生活一开始还觉得很新鲜,但是渐渐地,他们才发现对方的生活并没有表面上看起来那么光鲜亮丽。三个孩子的确很烦,单身生活也并非那么有趣。在律师事务所里,漂亮性感的女同事赛伯瑞纳频频向住在米奇身体里的戴夫示好;而与米奇长期分居的老父亲现在又重出江湖,跑来和儿子“捣蛋”,这弄得变成了单身汉的戴夫焦头烂额。 　　互换了身体的戴夫和米奇都在小心翼翼地过着他人的生活,生怕自己的愚蠢和以往的性格将好朋友的生活毁于一旦。与此同时,他们还要努力地找到把身体换回来的办法。','Who says men can\'t change?',52000000,75450437,32.015477,5.9,736,112,'2011-08-05','en','/zZEZYxcd8rxEtmjcn0LQKF66R4S.jpg',3.3085897409671765,3,'2026-09-10',2,NULL,NULL),(49521,'超人：钢铁之躯','Man of Steel','氪星人乔·艾尔（罗素·克劳 Russell Crowe 饰）抵死反抗佐德将军（迈克尔·珊农 Michael Shannon 饰）的邪恶计划，冒险将刚出生不久的儿子卡尔·艾尔送到地球。卡尔降落在美国堪萨斯一座小镇，他幸运地成为乔纳森·肯特（凯文·科斯特纳 Kevin Costner 饰）和玛莎（黛安·莲恩 Diane Lane 饰）的养子，并且得名克拉克。克拉克从小显露出与众不同的能力与特征，但这些带给他惊讶的同时还有数不清的烦恼。通过养父的引导，克拉克（亨利·卡维尔 Henry Cavill 饰）慢慢弄清自己的身世以及所肩负的使命。终于有一天，遥远故乡的“同胞”莅临地球。站在故乡与地球、邪恶与正义的两端，超人即将面临重大的抉择……','You will believe that a man can fly.',225000000,662845518,99.398009,6.5,6359,143,'2013-06-12','en','/8GFtkImmK0K1VaUChR0n9O61CFU.jpg',4.066828581489244,3,'2026-09-10',2,NULL,NULL),(49524,'冥界警局','R.I.P.D.','杰夫·布里吉斯将饰演老警察Roy Powell，他已死数百年，并且是个神枪手。瑞安·雷诺兹饰演他的搭档，一个刚死不久的新警察Nick Cruz——他在人间被谋杀，必须用在地下当100年警察来换得回去调查自己死因的权利。这两个不死警察将与各种稀奇古怪的家伙较量，合力维护冥界的安宁。','To protect and serve the living',130000000,61648500,39.448066,5.4,1260,96,'2013-07-18','en','/nXacFJ2tPYjxQDlnBuN1JxIlE4E.jpg',3.338780522849978,3,'2026-09-10',2,NULL,NULL),(49526,'致命急件','Premium Rush','速递员威利（约瑟夫·高登-莱维特 Joseph Gordon-Levitt 饰）的自行车是一辆经过改装的fixed gear，钢制车架，，再加上他的车技和灵敏的反应，每天都能在拥挤的街道上穿行。\r 　　一天，一个女人给了他一个“非常重要的急件”，要他在90分钟内把这个东西送到唐人街。可是在半路上，却又警察把威利拦了下来，并用强迫的方法要威利交出那个急件。走投无路的威利只好私自拆开了信封，并发现了一个惊人的秘密。\r 　　那么，发现秘密的威利能在90分钟内把这个消息准确送达么？他的自行车能跑得过警车和黑帮的速度么？','Ride Like Hell',35000000,31083599,17.709888,6.2,832,91,'2012-08-24','en','/mOywq8VTNS4uaP0b54SDA59LWCP.jpg',3.348536626517243,3,'2026-09-10',2,NULL,NULL),(49527,'窗台上的男人','Man on a Ledge','前纽约警局警探尼克·卡西迪（萨姆·沃辛顿 Sam Worthington 饰）因重大窃盗罪入狱，之后又成为逃犯。如今，他进入位于纽约市第45街和麦迪逊大道交界著名的罗斯福饭店，在最高楼层的房间里爬出窗外，站在大楼外墙边缘，这不只威胁到他自身的安危，也捕捉到全市的目光，其中有些人正担心某个天大的秘密会曝光。尼克站在高楼窗台边缘的惊心动魄举动不仅爆发媒体追踪，也引来不被看好的谈判女警探莉迪亚·梅瑟（伊丽莎白·班克斯 Elizabeth Banks 饰），她必须说服他回到房间，同时还要应付刁难的纽约警局同事（爱德华·伯恩斯 Edward Burns 饰）。这可能跟一个声东击西的惊人计划有关。尼克在大楼边缘等待时机的同时，他的忠心弟弟（杰米·贝尔 Jamie Bell 饰）跟女友正在秘密进行什么？或者尼克在警力的好友兼搭挡（安东尼·麦凯 Anthony Mackie 饰）正想说动他进来房间？或者这一切都跟商界大亨（艾德·哈里斯 Ed Harris 饰）的卑鄙勾当脱不了关系？在尼克大胆展开惊险行动的过程中，更多谜团将随之揭露，而不消多久，这个不名誉警探想证明自己清白的决心和幕后故事无疑成为更令人大开眼界的焦点。最后，这场风险变得愈益诡谲危急，不再只是他可能会失去平衡掉下大楼。','You can only push an innocent man so far',42000000,46221189,34.041407,6.2,925,102,'2012-01-13','en','/6A9FK0JZlefioWcd1m8ugqgAslk.jpg',3.409512411223142,3,'2026-09-10',2,NULL,NULL),(49529,'异星战场','John Carter','曾荣获奥斯卡金像奖的著名导演安德鲁·斯坦顿带来全新力作《异星战场》，一部以神秘壮丽的火星为背景的史诗动作冒险巨制。影片根据埃德加·赖斯·巴勒斯于20世纪初创作的经典科幻小说《火星公主》改编，故事 讲述美国内战时期，饱受创伤的前军官约翰·卡特（泰勒·克奇 Taylor Kitsch 饰）无意间穿越到了火星。由于引力不同，约翰成为了力大无穷、弹跳如飞的“超人”，也因此卷入当地几大族群的冲突，周旋于美丽的公主德佳·索丽斯（琳恩·柯林斯 Lynn Collins 饰），英勇的盟友塔斯·塔卡斯（威廉·达福 Willem Dafoe 饰）与狡猾的敌人萨博·赞恩之间。然而地球上战火纷飞带来的痛苦，早已让约翰无心恋战；虽然几大族群都将他视为能够拯救火星的关键人物，可他真的能抛下过去，担负起保卫人民的重任，拯救这个水深火热的世界，扭转异星战场的命运吗？','Lost in our world, found in another.',260000000,284139100,43.926995,6.1,2124,132,'2012-03-07','en','/wrTtdEboTbYdQ7jHtRTp7uCKtmM.jpg',3.594983282529066,3,'2026-09-10',2,NULL,NULL),(49530,'时间规划局','In Time','在未来，人类可以随心所欲的操控时间，改写年龄。在人类社会，不管这个人活多久，他的年龄被永远定格在25岁。因为没有了自然死亡，为了避免人口膨胀。人类社会抛弃了以往的货币，改用时间作为货币流通。一个人的时间用完之后，这个人就会死亡。一个名叫威尔（贾斯汀·丁伯莱克 Justin Timberlake 饰）的穷人，却意外获得了一笔巨大的财富，拥有了用不完的时间。但是却因为此事被锁定为一场谋杀案的嫌疑人，由此走上了逃亡之路。在逃亡过程中，绑架了时间银行的女继承人（阿曼达·塞弗里德 Amanda Seyfried 饰）。在整个逃亡过程中，他们之间迸发出了感情的火花。而且两人都对现有的时间管理机制都非常不满，进而联手起来对抗这个统治机构。仅凭两人之力能够推翻成熟的权力机构吗？','Time Is Power',40000000,173930596,60.231382,6.7,3417,109,'2011-10-27','en','/3Mwj2sIONQckOZP3YwsUXF7U5I4.jpg',3.8835015965431228,3,'2026-09-10',2,NULL,NULL),(49538,'X战警：第一战','X-Men: First Class','年轻的X教授查尔斯（詹姆斯·麦卡沃伊 James McAvoy 饰）和万磁王埃里克（迈克尔·法斯宾德 Michael Fassbender 饰）是一对志向相投的好朋友。他们最早发现了自己的超能力，并与其他几个变种人一起在CIA工作。引发埃里克超能力的纳粹战争犯肖（凯文·贝肯 Kevin Bacon 饰）一直试图挑起核战争，而想方设法挑起美苏两国的矛盾。埃里克和查尔斯一直与肖手下的变种人战斗，努力阻止肖的阴谋。肖怂恿苏联引发古巴导弹危机，查尔斯和埃里克获知消息后，在海湾与肖手下的变种人拉开了对决的一战。最终，肖被查尔斯和埃里克合力消灭。可是，在这个过程中，埃里克逐渐被肖的政治观点影响，与查尔斯产生裂痕。通过海湾的这一战，埃里克和查尔斯最终决裂，一方是支持人类与变种人和平共存的X教授；另一方坚持通过消灭人类换来变种人兴起的观点，自称万磁王……','Witness the moment that will change our world.',160000000,353624124,3.195174,7.1,5181,132,'2011-05-24','en','/hNEokmUke0dazoBhttFN0o3L7Xv.jpg',3.958033623575908,3,'2026-09-10',2,NULL,NULL),(49730,'Red Riding Hood','Red Riding Hood','Valerie is in love with a brooding outsider, Peter, but her parents have arranged for her to marry another man – who is wealthy. Unwilling to lose each other, Valerie and Peter plan to run away together when they learn that Valerie\'s older sister has been killed by a werewolf that prowls the dark forest surrounding their village. Hungry for revenge, the people call on famed werewolf hunter, Father Solomon, to help them kill the wolf. But Solomon\'s arrival brings unintended consequences as he warns that the wolf, who takes human form by day, could be any one of them.','Who\'s afraid?',42000000,89162162,45.151657,5.6,922,100,'2011-03-11','en','/2MTcukA6wAia1oqH6cFvJ6gE7Gw.jpg',3.333609180733373,3,'2026-09-10',2,NULL,NULL),(49787,'大堡礁惊魂','The Reef','来自英国的麦特（Gyton Grantley 饰）带着女友苏西（Adrienne Pickering 饰）以及居住在悉尼的妹妹凯特（Zoe Naylor 饰）来到澳大利亚某个港口小镇游玩，麦特的朋友卢克（Damian Walshe-Howling 饰）热情接待了他们。而在面对前女友凯特时，他的心中涌起别样的涟漪。阳光明媚，碧海蓝天，莫要辜负这个天堂一般的胜地和假期，他们租用水手沃伦（Kieran Darcy-Smith 饰）的游艇，启程前往天鹅大堡礁附近潜水玩耍。夜幕降临，游艇突然撞到了什么东西，伙伴们顿时陷入恐慌之中。五个人好不容易逃出生天，但船底破了打洞，他们被困在大海中央。  　　本就处在孤立无援的危险境地，恐怖的食人鲨又悄悄向这几名遇难者逼近……','Pray That You Drown First',0,0,7.245108,5.4,130,94,'2010-05-15','en','/s5JGAqmdv1cHlDjMqsmQUkVo2lW.jpg',2.8765922545110585,3,'2026-09-10',2,NULL,NULL),(49852,'胡桃夹子：魔境冒险','The Nutcracker','圣诞节，9岁女孩玛丽得到一只胡桃夹子。夜晚，她梦见这胡桃夹子变成了一位王子，领着她走入另外一个世界。这个世界中，所有的玩具都有了生命。在这里原本美好的王国被老鼠占领，并且为了遮住太阳的光芒，老鼠兵抓了王国的人民为他们制造黑色的浓烟。当晚在雪仙子的帮助下，玛丽为胡桃夹子恢复了肉身，但是在老鼠王后的破坏下胡桃夹子还是不能破除诅咒，并且玛丽又回到了现实当中。玛丽为了能解除胡桃夹子身上的魔咒，帮他恢复王国。她再次回到了梦境中，并且和胡桃夹子制定了关闭浓烟制造工厂，让阳光晒到大地，赶走老鼠的计划。胡桃夹子和玛丽带领他们的玩具朋友们来到了工厂，但是不幸的是胡桃夹子被抓，将要被扔经火炉中烧掉。在最危急的一刻玛丽救下了小夹，用真情的眼泪为他破除了诅咒。小夹恢复了王子的身份，关闭了浓烟工厂。带领着人们反击老鼠兵，把老鼠赶出了自己的王国。胜利之后玛丽受到人民的欢迎和爱戴。',NULL,90000000,16178959,3.593349,5.4,50,110,'2010-11-24','en','/9pHyzYAjVKa4NHmhmNCNao2VX7q.jpg',2.6820437578663237,3,'2026-09-10',2,NULL,NULL),(49948,'幻想曲2000','Fantasia 2000','本片是迪士尼电影公司重新整理编撰1940年的「幻想曲」故事而成，其中包括一段旧「幻想曲」中的米老鼠变魔术的段落，而其他七个段落全是2000年崭新的创作。这次唐老鸭也如愿以偿当上主角，主演一段由诺亚方舟改编的故事。 　　各个段落的故事可看见动画创作者天马行空的想像力，内容包罗万象，有飞天的鲸鱼，有调皮的火鹤，为爱牺牲的玩具小士兵，现代纽约的日常生活以及带来满山春意的春神等等，各成一格，风格迥异。是喜爱古典乐的成人视觉上的一顿飨宴。',NULL,80000000,90874570,14.530946,7,292,74,'1999-12-17','en','/dmBiVthK04fUKfFWoKcCi5haCeR.jpg',3.176586909827669,3,'2026-09-10',2,NULL,NULL),(49950,'室友','The Roommate','丰富的知识、充满魅惑的舞会、以及帅气的鼓手史蒂芬（凯姆•吉甘戴Cam Gigandet 饰）让刚迈进大学校门的女孩子莎拉（敏卡•凯莉 Minka Kelly 饰）兴奋不已，而友善的室友蕾贝卡（莉顿•梅斯特 Leighton Meester 饰）则让她的大学生活显得更加完美。然而，生活并不像表面那样平静，蕾贝卡乖戾的性格渐渐显露，她不仅恐吓与莎拉亲近的好友崔西（艾莉•米夏卡Alyson Michalka 饰）远离莎拉，而且因为莎拉要搬走，残忍的杀死了莎拉的宠物猫。蕾贝卡怪异的占有欲让莎拉感到恐惧，她终于忍受不了自己的病态室友，决定远离这一切，然而事情并没有那么简单……  　　本片集结了当前几部热播美剧中的俊男美女，加之取材于报纸上真实报道，在该片未上映之前便为本片攒足了噱头。','2,000 colleges. 8 million roommates. Which one will you get?',16000000,40492759,11.807269,5.3,224,91,'2011-02-04','en','/kQZcOn5rDuwpbQTluC4Wm0amYmR.jpg',2.9795091286532043,3,'2026-09-10',2,NULL,NULL),(49951,'Certifiably Jonathan','Certifiably Jonathan','A famous comedian and artist wants to display his work at an art museum. Just when he thinks he\'s lost his touch, a series of famous comedians drop by to help him rekindle his artistic and comedic spark.',NULL,1200000,0,0.047781,0,0,85,'2007-03-01','en','/9iZuJ4I5Fxr8EeRMvoDIJRxOL3e.jpg',1.8338915265275821,3,'2026-09-10',2,NULL,NULL),(49953,'萨米大冒险','A Turtle\'s Tale: Sammy\'s Adventures','阳光明媚、寂静平和的海滩，一群小海龟孵化出壳，他们摆动着稚嫩的臂膀，奋力向大海爬去。名叫萨米的小海龟最后爬出蛋壳，但是他怎么也无法爬出沙坑。焦急时分，塞米更被海鸟捉到空中，眼看就成为了对方的点心。混乱之际，他结识了美丽的女孩莎莉。此后，他乘坐轮船的碎木板像海洋中心飘去，偶然遇到了他一生的好朋友雷。在此后的50年里，两个小家伙乘坐破木板周游世界，见识了海洋各处的美景奇观，也经历着人类为了私欲对海洋做出的无可弥补的破坏，他们的冒险从未结束……','He\'s Turtly Amazing',0,0,15.805449,5.6,151,88,'2010-08-03','en','/jYz1FQjspxQCUCMXuB4ihnH9Y03.jpg',2.9344021839909176,3,'2026-09-10',2,NULL,NULL),(49963,'良缘知己','Walking and Talking','Amelia和Laura是一对自幼便极为要好的朋友，但由于Laura与男友Frank的订婚，Amelia感觉自己被疏远了。于是，Amelia开始寻找自己的另一半。','A movie for everyone who wants to get married and stay single at the same time.',0,0,0.367312,6.6,7,86,'1996-07-17','en','/m8JMJQUfGwGt7gse8aoduAcTYE.jpg',2.2875581254912283,3,'2026-09-10',2,NULL,NULL),(50014,'相助','The Help','上世纪60年代，在密西西比州，黑佣艾比里恩（维奥拉•戴维斯 Viola Davis 饰）勤勤恳恳照顾女主人的女儿，后者因产后抑郁症只顾与闺蜜贪欢。密西西比大学毕业生斯基特（艾玛•斯通 Emma Stone 饰）在报社负责家庭主妇信箱，并由此开始黑佣的生存状态。其中，希利（布莱丝•达拉斯•霍华德 Bryce Dallas Howard 饰）无疑是反面教材，她态度傲慢，对黑佣米妮（奥克塔维亚•斯宾瑟 Octavia Spencer 饰）抱有偏见，并力主黑佣不能与主人共用厕所。最终因不堪受辱，米妮愤然离去，并以牙还牙，假借道歉之机让她蒙羞。斯基特开始采访艾比里恩和米妮，希望了解黑佣的生存状态，并为自己的新书积累素材。与此同时，马丁路德金领导的平权运动正在如火如荼地开展，而斯基特所在的密西西比州正是斗争的前沿，因为黑人遭射杀的血案，种族隔离开始，一场肤色之争在所难免……','Change begins with a whisper.',25000000,124272124,42.191509,7.8,1910,146,'2011-08-09','en','/3kmfoWWEc9Vtyuaf9v5VipRgdjx.jpg',3.9372450917225326,3,'2026-09-10',2,NULL,NULL),(50035,'美丽与动人','Lovely & Amazing','由美国独立制片界著名的女导演尼科尔·哈罗芬瑟(Nicole Holofcener)自编自导，影片围绕一位母亲(布兰达·布雷辛)和她的三个女儿以多线式的形式展开叙述，是一部关于爱情、事业和家庭的轻喜剧。',NULL,250000,4186931,1.45917,6.3,23,91,'2001-08-31','en','/4HZ7Y7N4KHapO5ylOY8BePQYC5X.jpg',2.528941762732089,3,'2026-09-10',2,NULL,NULL),(50037,'Beyond the Black Rainbow','Beyond the Black Rainbow','Deep within the mysterious Arboria Institute, a disturbed and beautiful girl is held captive by a doctor in search of inner peace. Her mind controlled by a sinister technology. Silently, she waits for her next session with deranged therapist Dr. Barry Nyle. If she hopes to escape, she must journey through the darkest reaches of The Institute, but Nyle wonʼt easily part with his most gifted and dangerous creation.','Beyond Science. Beyond Sanity. Beyond Control.',1100000,0,7.717237,5.7,77,110,'2010-12-03','en','/uhomcCTQ3lO8L6mLhkCMypsnroO.jpg',2.785623647012101,3,'2026-09-10',2,NULL,NULL),(50135,'动物总动员','Konferenz der Tiere','广袤无际的非洲大草原上，饱受干旱所侵扰的动物们耐心却又焦灼地等待着洪水的到来。今年的汛期似乎姗姗来迟，动物们心中满是不安。他们无论如何也不会想到，不远处的峡谷间耸起一座大坝，人类用它拦截了本该滋润草原和万物的水源。  与此同时，草原上迎来了几名罕见的来客：孤独的北极熊、聒噪的高卢鸡、相伴上百年沧桑岁月的乌龟夫妇、活泼的袋鼠以及爱放臭屁的笑笑。他们都是因为人类的颟顸与无知，而被迫离开赖以栖息的家园，只为寻找一个没有人类足迹的乐土。只是非洲草原的情况也不容乐观，来自异乡的动物们不得不和当地的动物朋友联合起来，踏上寻找水源的惊险之旅……',NULL,0,0,8.010046,5.5,90,93,'2010-10-07','de','/lFKP0GZX3oKqwNra23RFDBj0YSU.jpg',2.8113896800595795,3,'2026-09-10',2,NULL,NULL),(50321,'火星需要妈妈','Mars Needs Moms','在一个宁静的夜晚，少年迈洛和妈妈发生争吵。自感言语过于伤人，迈洛决定向妈妈道歉，前看见黑暗中一道强光将妈妈虏去。他一路追赶，登上了那艘神秘的飞船，竟意外来到了万里之遥的火星。原来火星人都从土壤中长出，住在火星的雌性不知如何照顾孩子，因此发明了保姆机器人，并从地球上劫持她们相中的母亲，提取她的记忆和经验输入机器人的程序中。迈洛从躲藏在火星垃圾站附近的人类格里布口中得知，妈妈的记忆在提取后将忘记一切。在格里布和火星女孩葵的帮助下，迈洛展开了营救妈妈的不可能任务……　　本片根据插画师伯克利•布雷斯德（Berkeley Breathed）的原著改编。','Mom needs a little space.',150000000,38992758,12.362599,5.5,199,88,'2011-03-09','en','/8L6uLJoFlRXCcTJc9VOpLhhkg36.jpg',2.9731015551257673,3,'2026-09-10',2,NULL,NULL),(50348,'林肯律师','The Lincoln Lawyer','米克·哈勒 是一位洛杉矶的刑事辩护律师，他有个特别的习惯，喜欢在他的林肯豪车的后部办公，因而得到了一个称号\"林肯律师\"。哈勒大部分时间处理的都是些看上去平淡无奇的案子，直到他遇上了他职业生涯中最棘手的一桩：路易斯·鲁莱特，一位贝弗利山庄商人的儿子，也是一位彻头彻尾的花花公子，被指控强奸和谋杀未遂。但是这桩案子在进行过程中却渐渐显得失控，哈勒和助手弗兰克·雷文 发现路易斯似乎是无辜之人，同时这起案件背后又有隐情，而接着他的前妻麦琪 又陷入生命危险，更与他有着斩不断理还乱的感情纠葛。慢慢地，危险不断袭来，哈勒发现自己陷入了一场死亡游戏之中。','This Case is a Dangerous Game of Life and Death',40000000,85412898,26.072228,7,902,119,'2011-03-17','en','/vFCXDXLI5cu5TOudhNuSsOCYOKU.jpg',3.5184594413225856,3,'2026-09-10',2,NULL,NULL),(50357,'阿波罗18号','Apollo 18','1969年7月20日,“阿波罗”登月舱降落到月面,开始了人类有史以来的第一次登月。随后“阿波罗”飞船执行过多次登月任务,但到了70年代,当“阿波罗18号”按照既定计划准备起飞前往月球时,却意外的接到了尼克松总统的命令:取消登月,并且禁止随后的一系列登月计划。于是,“阿波罗18号”的登月计划胎死腹中,人类也从此再未上过月球。  　　数十年后,两名NASA的宇航员意外的发现了几十前的一卷录像带,在当中从未公布的绝密视频里,两人惊奇的发现了为何美国再未登月的真正原因。原来“阿波罗18号”其实曾按照既定计划顺利登陆月球,而当时的宇航员,在月球上发现了外星生命……','There\'s a reason we\'ve never gone back to the moon.',5000000,25562924,17.028252,5,356,86,'2011-07-20','en','/2k5EKXEKk2LaXhlwNBqqSOyeUrK.jpg',3.0394373067131473,3,'2026-09-10',2,NULL,NULL),(50359,'拯救小兔','Hop','故事讲述詹姆斯·麦斯登饰演的失业“米虫”不小心让复活节兔子（拉塞尔·布兰德 配音）受伤了，因此他不得不担负起照料小兔子的任务。在他照顾这只堪称世界上最难伺候的客人的时候，他也逐渐的成熟起来。值得一提的是，《生活大爆炸》中的Penny卡蕾·措科也将出场。','Candy, chicks and rock \'n\' roll.',63000000,183953723,16.791058,5.5,331,95,'2011-03-30','en','/2FrDmwXWjRE1zpNP288YncRt5RF.jpg',3.075286001230339,3,'2026-09-10',2,NULL,NULL),(50456,'汉娜','Hanna','位于北极圈附近的冰原森林，生活着一对平凡却有着非凡身手的父女。父亲艾利克·海勒 是受雇于CIA的特工，在上世纪90年代活跃于东欧和中亚等地，具有丰富的经验。然而最终却因为某种原因，令他带着女儿汉娜隐居在这人类罕至的寒冷所在。经过十多年的艰苦磨练，汉娜 终于成长为拥有广博知识和出色身手的战斗少女。  某天，自认已做好准备的汉娜按下了父亲那台信号发射器，不久美国方面便收到消息。艾利克当年的联系人玛丽莎 声称这个消失多年的特工掌握非常敏感的秘密，于是在她的主持下，一场居心叵测的围捕旋即展开。汉娜也已柔弱的身躯投入了血腥的战斗之中……','Adapt or die.',30000000,63782078,31.191975,6.5,1263,111,'2011-04-07','en','/cKUvwvW3NxpFuU4CXC2Q4z9leke.jpg',3.529611776555822,3,'2026-09-10',2,NULL,NULL),(50497,'灯火熄时','When the Lights Went Out','1974年的一天，梅那德一家驱车搬到了约克郡一栋远离城市喧嚣的房子里。男主人莱恩（史蒂文·威丁顿 Steven Waddington 饰）和妻子珍妮（凯特·艾什菲尔德 Kate Ashfield 饰）均沉浸在乔迁的喜悦之中，但女儿莎莉（塔莎·科纳 Tasha Connor 饰）却一脸愁云，不仅因为这个美丽敏感的女孩正处在青春叛逆期，还因为乔迁当晚卧室内诡异的景象让她惶恐不安。每当莎莉独处之时，各种恐怖经历便纷至沓来，且愈演愈烈。随着事态的恶化，反感超自然现象的父母终于相信这一切并非源自莎莉的恶作剧。似乎在毗邻的森林内，有一个恶灵正冷冷地注视着这家人……\r 　　本片根据欧洲恶名昭著的鬼屋场景及真实事件改编。','Set in 1974 and based on true events.',0,0,2.805351,5.8,49,86,'2012-01-31','en','/bdsUVOLDADbfIWSJflJSgE8J3Ai.jpg',2.6837644307788815,3,'2026-09-10',2,NULL,NULL),(50538,'Evil Words','Sur le seuil','One day, for no apparent reason, a cop kills 11 children. The same day, horror novelist Thomas Roy tries to commit suicide after cutting his fingers. At first glance, nothing seems to link the two events – until Dr. Paul Lacasse, a disillusioned psychiatrist, takes over the case. Prompted by his colleague Jeanne, a fan of Thomas Roy, Dr. Lacasse investigates the writer’s past. Hounded by a gossip columnist, Dr. Lacasse uncovers a series of troubling facts that bolster his convictions about the case. As he tries to reassemble the pieces of the puzzle in order to better treat the famous writer, Dr. Lacasse is dragged further and further into a series of events, with terrifying consequences.',NULL,0,0,0.205034,6.9,8,100,'2003-10-03','fr','/UpIqDBcQo3ra07FXmJoJBI7AOF.jpg',2.3139380602915263,3,'2026-09-10',2,NULL,NULL),(50544,'朋友也上床','Friends with Benefits','杰米是一位在纽约供职的猎头，为了将身在洛杉矶的迪伦挖角到纽约，她提供的不仅是丰厚薪资，还给了这位初来乍到者真挚的友情，带着他领略了纽约的美好夜晚。“挖角”成功了，两人成了最好的朋友，也难免受到对方吸引。此时恰逢迪伦与前任分手，而曾经受过情伤的杰米也不想进入一段正式关系，于是两人商定只谈性不谈爱。在迪伦的鼓励下，杰米在公园搭讪到令她动心的人——医生帕克，可是很快发现对方只是想把她搞上床，令她再度受伤。为了帮杰米走出阴霾，迪伦带杰米回到自己家乡，两人隐隐意识到对彼此的感情，却在这当口发生一场误会。唯有失去才会懂得珍惜，迪伦在杰米心灰意冷独自回纽约后，明白自己已经深深爱上她，而她却仿佛在他生活中消失了，迪伦不知该怎样迈出挽回杰米的那一步。','Some friends come with a happy ending.',35000000,150483765,40.526587,6.5,2237,109,'2011-07-21','en','/ElAsiPWDL3iuNzzuLyfzzBbAlf.jpg',3.688952965165139,3,'2026-09-10',2,NULL,NULL),(50546,'随波逐流','Just Go with It','丹尼（亚当·桑德勒 Adam Sandler 饰）是一个有家庭、有地位的整形外科医生，但是他和自己的妻子相处的并不愉快。目前，丹尼正在“贼头贼脑”地寻找新的刺激。有一天，他碰到了一个年轻、有活力、而且还很开放的女孩帕玛（布鲁克琳·黛克 Brooklyn Decker 饰）。为了哄帕玛开心，并且把她钓到手，丹尼一直没有告诉帕玛自己是个已婚男人的事实。但是帕玛很快便发现了丹尼已婚的蛛丝马迹，并且准备离开这个花心的老男人。而丹尼呢，似乎也真的是喜欢上了这个女孩，他不仅没有用自己“玩弄”女人的手段来对付她，反而对她百依百顺。在自己已婚的事实破败之后，丹尼告诉帕玛自己正在准备和妻子离婚，他的太太很快就会变成前妻。为了让自己的谎言圆满，他找来了自己的客户经理凯瑟琳（詹妮弗·安妮斯顿 Jennifer Aniston 饰）假扮那位传说中即将离婚的妻子，以便圆满自己的谎言，让女孩相信他。而凯瑟琳也毫不含糊，短暂地做起了“临时妻子”。不过，一个谎言没有办法自圆其说，所以丹尼只好带着凯瑟琳又撒了一个谎。于是，一个谎言接着谎言的“循环战”开始了。连凯瑟琳的两个孩子（格里芬·格鲁克 Griffin Gluck 和 拜莉·麦迪逊 Bailee Madison 饰）也没能幸免于难，被卷入到丹尼的“阴谋”之中。更悲催的是，在他们集体夏威夷的旅游中，恰好又碰到了德芙琳（妮可·基德曼 Nicole Kidman 饰）及其老公（戴夫·马休斯 Dave Matthews 饰）给他们乱上添乱。然而就是在这次夏威夷旅游之后，他们的生活永远地被改变了……','Sometimes a guy\'s best wingman... is a wingwoman',80000000,214918407,37.02665,6.3,1543,117,'2011-02-10','en','/s3nbxbJkr2j7YV6m87H5B6bpQe1.jpg',3.5508712430632388,3,'2026-09-10',2,NULL,NULL),(50601,'五日战争','5 Days of War','影片讲述了2008年8月俄罗斯与格鲁吉亚的冲突,2008年南奥塞梯战争是2008年8月在格鲁吉亚境内发生的一场战争，交战一方为格鲁吉亚ZF，另一方为单方面宣布独立的南奥塞梯，及其支持者阿布哈兹和俄罗斯。自8月1日开始，格鲁吉亚和南奥塞梯发生数次交火，8月8日凌晨格鲁吉亚展开全面军事行动并很快控制了2/3以上的南奥塞梯地区，包围了其首府茨欣瓦利。俄罗斯军队于8日进入南奥塞梯地区，9日展开军事行动很快控制了茨欣瓦利，并在随后几日占领了南奥塞梯以外的格鲁吉亚领土和军事基地。在国际各方的调停下，格鲁吉亚和俄罗斯分别于15日和16日在停火协议上签字，俄军于18日开始撤离格鲁吉亚，战争结束。这次战争共造成格鲁吉亚军队215人死亡、1469人受伤；俄罗斯军队74人死亡，171人负伤，19人失踪，以及约1600南奥塞梯平民死亡。','Their only weapon is the truth.',20000000,17479,5.727602,5.8,62,113,'2011-04-14','en','/iRH1VspiF7lyHj7P4mRP5tqmqxv.jpg',2.7391795010212037,3,'2026-09-10',2,NULL,NULL),(50620,'暮光之城4：破晓（下）','The Twilight Saga: Breaking Dawn - Part 2','Alice预见了Volturi即将到了，大家猜到一是因为Renesmme,二是因为Volturi不满Cullen家族的壮大，他们想维护自己的权威与声望。Volturi的首领Aro一直都很想把Alice和Edward收归旗下，Alice和Ed的叛逆已经让Aro心存不满。Bella心烦意乱,Cullen家族也很紧张。Bella头一次看到一贯平静优雅的Charlisle出现担忧的神情，对于Volturi那段恐怖的在Bella还是human的时候的那段记忆让Bella更加恐惧，她担心Renesmme早于不测。但没有人能估到Volturi什么时候来。Edward和charlisle商量着对策，而这时候Bella和Jacob带着Renesmme去hunting,却与Tanya三姐妹中的Irina不期而遇。Irina是Tanya三姐妹中的一员，虽然没有直接服务于Volturi,但对这个有几千年历史的V氏家族一贯衷心，Irina没有等Bella解释，便认定Cullens创造了一个baby vampire,疾速感到意大利Volturi家族报告。这一刻开始，Bella知道，一场毁灭性的灾难将要来临……','The epic finale that will live forever',120000000,829000000,99.687084,6.1,2553,115,'2012-11-13','en','/7IGdPaKujv0BjI0Zd0m0a4CzEjJ.jpg',3.762154998201774,3,'2026-09-10',2,NULL,NULL),(50646,'疯狂愚蠢的爱','Crazy, Stupid, Love.','卡尔（史蒂夫·卡瑞尔 Steve Carell 饰）人到中年，中年危机如约到来——妻子艾米丽（朱丽安·摩尔 Julianne Moore 饰）提出离婚，令他面对儿女不知所措。重回情场的卡尔发现自己已经脱离男欢女爱的时代了，幸亏遇到泡妞高手雅各（瑞恩·高斯林 Ryan Gosling 饰），帮他重整行头，教他当今最时髦的方法俘获女人芳心。卡尔重战情场了，反而是雅各遇上感情烦恼，他遇见一个叫汉娜（艾玛·斯通 Emma Stone 饰）的姑娘，令他发现真爱原来和招数、游戏根本无关。女人缘变好的卡尔渐渐发现家庭仍是自己最大牵挂，雅各渐渐发现自己愿意为汉娜放弃花花公子的日子，加上卡尔13岁的小儿子也开始情窦初开为爱烦恼，爱有多疯狂，又有多愚蠢，在汉娜邀请雅各回家吃饭的那刻，终于见了分晓…','This Is Stupid',50000000,142851197,37.990705,7,2443,118,'2011-07-29','en','/p4RafgAPk558muOjnBMHhMArjS2.jpg',3.819682621276356,3,'2026-09-10',2,NULL,NULL),(50647,'漫游','Wanderlust','乔治（保罗·路德 Paul Rudd 饰）和琳达（詹妮弗·安妮斯顿 Jennifer Aniston 饰）是一对刚刚决定置业的年轻夫妇，却在买下房子的当口双双遭遇失业，赔掉所有身家的二人决定离开压力繁重的纽约另谋生路。投奔亲戚失败后，二人来到路上偶然经过的“伊甸园”式社区，结识了一群不拘世俗的怪人，抱着好奇姿态，接触他们崇尚的玄学、东方神秘学、自然主义哲学理论，尝试各种迷幻药物。本来只是找个一时容身之所，但琳达却越来越投入这种所谓“自由”“自然”理念的生活，社区统领也对她展开追求，乔治发现二人出现裂痕，努力未果之下选择离开，只身回纽约找工作。  　　在二人对生活和彼此关系进行反思、梳理的同时，社区的真相也慢慢浮出水面……','Leave your baggage behind',35000000,24159934,20.908494,5.3,394,98,'2012-02-23','en','/hH1Bla0W4YIn9sdd9NwODzDCcE4.jpg',3.0942665799934614,3,'2026-09-10',2,NULL,NULL),(50698,'墓地邂逅','Grave Encounters','电视台制作人杰瑞•哈尔福德与信心满满的青年兰斯•普雷斯顿（辛恩·罗格斯 Sean Rogerson 饰）合作，制作了一档名为《墓地邂逅》的灵异纪实节目，他自称年少时曾遭遇超自然现象，所以长久以来一直致力于揭示灵魂的真面目。此次，他和他的团队来到了一家始建于1893年的医院——科林伍德精神病院，该医院曾受纳上千名病患，1963年因闹鬼被迫关闭。兰斯团队决定将自己反锁在医院8小时，通过摄像机以及其他高精仪器寻找鬼魂的蛛丝马迹。\r 　　为了制造恐怖氛围，兰斯不惜弄虚作假，可是他很快发现这座医院真的有什么东西存在，他们将面临最为恐怖与难熬的不眠之夜……','They Were Searching For Proof.  They Found it.',1000000,0,13.222268,6.1,381,92,'2011-09-09','en','/8vnsB3Rg9Gb91UOaecXRb7dYB37.jpg',3.1537173840153208,3,'2026-09-10',2,NULL,NULL),(50725,'今夜带我回家','Take Me Home Tonight','在上世纪80年代晚期，华尔街的指数依然高攀，整个国家似乎都在享受着这巨大的金融繁荣带来的幸福中。但是，一名麻省理工学院的天才毕业生马特·富兰克林（托弗·戈瑞斯 饰）却对这样的物质主义深深的厌恶，他辞去了一个当地实验室薪水丰厚的职位，在父亲比尔（迈克尔·比恩 饰）无法理解的目光中成为了一名底层的录像店员。而同时，马特周围的人也深陷自己人生的危机，好友巴里被炒了鱿鱼，妹妹温迪（安娜·法瑞丝 饰）被她无趣的男友凯尔（克里斯·帕拉特 饰）套住烦心无比，还有马特深爱却一直无法追求的托丽·弗里德克金（泰莉莎·帕尔墨 饰），突然重新在他生活中出现。而在一个夜晚，在这个狂野不羁的夜晚里，所以的事情最终都似乎将指向爆炸性的结果。','Best. Night. Ever.',19000000,6928068,11.766564,6.2,208,97,'2011-03-04','en','/nInduPOusI1alDIC0UttFjDIKsO.jpg',3.0265561349522896,3,'2026-09-10',2,NULL,NULL),(50780,'海狸','The Beaver','曾经风光无限的企业家沃尔特·布莱克（梅尔·吉布森饰）在经历了让他痛苦欲绝的金融风暴之后濒临破产，意志越来越消沉的他还患上了抑郁症，纵使妻儿一直对他不离不弃，但他自己早已放弃了自己，在他对自己的家人动粗之后，他被心灰意冷的家人拒之门外，流浪街头。在垃圾箱旁边喝得烂醉沃尔特准备草草结束自己的生命，但这个时候，一只自称是海狸的布偶出现了，沃尔特借着醉意和海狸打起了招呼，这只布偶甚至还让他放弃了轻生的念头。　　随后，沃尔特在海狸的帮助下重新开始审视自己的生活，妻子梅瑞迪斯（朱迪·福斯特饰）和儿子珀特（安东·尤金饰）也开始接受了振作的沃尔特，而海狸更让沃尔特的公司起死回生，可是海狸的真实身份究竟是什么？沃尔特真的重新振作了吗？','He\'s here to save Walter\'s life.',21000000,970816,13.847872,6.3,276,91,'2011-02-11','en','/ozXmefxzvQM0xC711UNFz0K1tl8.jpg',3.1021011573807757,3,'2026-09-10',2,NULL,NULL),(50837,'双面玛莎','Martha Marcy May Marlene','凌晨时分，一个疾奔的身影出现在乡间的农场边……她是玛莎（伊丽莎白·奥尔森饰），离开家里已经很久很久，终于有一日，心急如焚的姐姐露西（莎拉·保罗森饰）接到了她的电话，玛莎告诉了她在哪里，希望她能接她回家。又惊又喜的露西带着姐姐回到家里，但她却一直一言不发，随后才在平淡瑟静的家庭生活中慢慢的讲述了自己的经历。原来她误入邪教，被教主帕里克（约翰·哈克斯饰）洗脑，最后好不容易才逃脱邪教控制，得以脱身。在日复一日的正常生活里，玛莎逐渐忘记了不堪回首的过去，并且和泰德（休·丹西饰）开始谈婚论嫁。泰德很富有，玛莎和他很恩爱，她告诉了他自己的往事，但却始终不肯透露在邪教里最后的那段日子。原来，她曾经以宗教仪式的名义被强奸，这是玛莎心里最大的心结，不过这个秘密最终被泰德知晓，两人的关系顿时处在一种不安的境地当中……','You can get away. But you can never escape.',0,3538446,17.806082,6.7,277,101,'2011-10-21','en','/bgB4sa9UfCyGdamfKAZXyEWuAwR.jpg',3.1450260203296216,3,'2026-09-10',2,NULL,NULL),(50839,'商海通牒','Margin Call','2008年经济危机爆发时，华尔街一家投资银行的分析师皮特·苏利文（扎克瑞·昆图 Zachary Quinto 饰）发现公司的财产评估有着巨大的漏洞，即将导致银行的破产。公司高层连夜开会希望挽救公司。富有经验的股票经纪人山姆·罗吉斯（凯文·史派西 Kevin Spacey 饰）、证券经纪人贾德·科恩（西蒙·贝克 Simon Baker 饰）、金融危机分析师萨拉·罗伯特森（黛米·摩尔 Demi Moore 饰）、老总约翰·图尔德（杰瑞米·艾恩斯 Jeremy Irons 饰）都来到了会议现场。会议决定，银行要以极低的价格抛售债权和股票。但此一举虽能使银行能得到暂时的安稳，但却会引发一系列连锁反应.......','Be first. Be smarter. Or cheat.',3500000,19504039,26.259389,6.7,524,107,'2011-09-28','en','/iwHaKIF56tNpQlOuMO9ilfekzpc.jpg',3.3275707252883517,3,'2026-09-10',2,NULL,NULL),(50848,'爱情的名字','Le Nom des gens','2011年第36届凯撒奖最佳原创剧本（巴娅·卡斯米Baya Kasmi；米歇尔·勒克莱尔）和最佳女主角（萨拉·福雷斯捷）作品。阿拉伯裔的巴希娅·本·穆罕默德Bahia Benmahmoud（萨拉·福雷斯捷饰）是一个活跃于法国政坛的右翼人士，她年轻外向，作事主断而果敢，为了她的事业发展，甚至可以和政治对手上床。通常情况下，她都能游刃有余地处理感情与事业问题，直到她遇上一个40岁厨师阿蒂尔·马尔丹Arthur Martin（雅克·冈布兰饰）的狂热追求......','Make Love, Not War',4600000,0,6.368933,7.3,93,100,'2010-11-24','fr','/e0QQs3oUe06ob4J9jFhxDCCQILb.jpg',2.8752241488034325,3,'2026-09-10',2,NULL,NULL),(50875,'更高境界','Higher Ground','影片据卡洛琳·布里格斯（Carolyn Briggs）的自传体小说《黑暗世界》（This Dark World）改编，讲述了一位年轻母亲的心灵发现之旅，她开始质疑笼罩着自己生活周围的“宗教信条”，不断抗争，去寻找自己在这个世界上真正的位置，从而理解到自己的信仰的本质。  　　年幼的科瑞妮是一个具有自我意识的女孩，她对周遭的世界充满了好奇。正是因为如此，她被当地侃侃而谈的牧师所“诱使”信奉了耶稣，将其视为自己唯一的神，而她自己也将一生都贡献给了这个“耶稣”。可是在那个时候，科瑞妮并不明白耶稣和信仰是什么。科瑞妮很喜欢阅读，她时常会去图书馆借书，她甚至能弄到成人读物阅读。  　　科瑞妮父母之间不断的争吵让她无法在这个家里待下去，所以科瑞妮走到了伊桑·米勒的儿童合唱团中。不久之后，科瑞妮怀了孕，匆匆忙忙地和伊桑结了婚。后来，她的女儿降生到这个世界上，一家人倒也生活得安静和平稳。一场潜在的事故被及时终止，他们的女儿保住了自己的性命，科瑞妮夫妇俩觉得这是牧师在显灵，于是便加入了当地的基要主义者组成的小圈子里。  　　时间到了1960年代，各种各样新鲜的事物涌入了这个小镇。文化的冲击和女权主义的兴起搅乱了科瑞妮和伊桑的生活。于此同时，科瑞妮最好的女性朋友又给了她无微不至的关怀与照顾－－这种体验她从来没有在伊桑的身上获得。于是，对婚姻的不满以及埋怨三个孩子占用了她太多时间的抱怨便一点一点地发泄了出来。她开始怀疑身边的宗教信仰、她开始抗争，她要尝试着去理解自己所信奉的宗教的意义……',NULL,2000000,841733,1.699101,5.3,14,109,'2011-08-26','en','/xFvN6OVYGwPokUnkZlKxd1coxbS.jpg',2.421112094606396,3,'2026-09-10',2,NULL,NULL),(50942,'Creature','Creature','An amphibious shark-like monster terrorizes an abandoned secret military base and the people who live on the island it is located on. A marine biologist, as well as several other people, try to stop it before it is too late...','Death from the depths',0,0,2.857848,4,21,176,'1998-05-17','en',NULL,2.4937622179414642,3,'2026-09-10',2,NULL,NULL),(51052,'Arthur Christmas','Arthur Christmas','Each Christmas, Santa and his vast army of highly trained elves produce gifts and distribute them around the world in one night. However, when one of 600 million children to receive a gift from Santa on Christmas Eve is missed, it is deemed ‘acceptable’ to all but one – Arthur. Arthur Claus is Santa’s misfit son who executes an unauthorized rookie mission to get the last present half way around the globe before dawn on Christmas morning.','Ever wonder how 2 Billion presents get delivered all in 1 night?',0,0,19.83683,6.7,333,97,'2011-02-22','en','/2n2W7LS3QdReT1ZsV8jcprd3cel.jpg',3.196251170529524,3,'2026-09-10',2,NULL,NULL),(51130,'Open Secret','Open Secret','A couple discovers that their friend has gone missing. Their investigation leads them to believe that anti-semites are behind the disappearance.','The Pull-No-Punch drama of men chained together by hate!',0,0,0.186401,7,2,68,'1948-02-14','en','/hPxKrniv4RmgdK2qldLWtgUoeHO.jpg',2.073497722824889,3,'2026-09-10',2,NULL,NULL),(51162,'小熊维尼','Winnie the Pooh','维尼和他的各位朋友重回百亩森林，屹耳丢掉了自己的尾巴，忧郁的找啊找；维尼不断的和自己的饥饿感奋斗；猫头鹰召集大家去拯救被假想敌人劫持的人类好友克里斯托夫·罗宾……','Oh Pooh.',30000000,14460000,19.143721,6.8,258,63,'2011-04-13','en','/8KjA0uSrgStXoE5PrMheO33bA30.jpg',3.1380963295379103,3,'2026-09-10',2,NULL,NULL),(51384,'我爱，依旧','Lovely, Still','影片讲述了两位老人在迟暮之年第一次尝到爱情滋味的故事。','Something mysterious, new, unexpected and lovely is happening to Robert Malone.',0,0,1.286991,6.2,13,92,'2008-01-01','en','/p5o2waFH3ioBOZuHKlx1kzk9Rdi.jpg',2.410245835022897,3,'2026-09-10',2,NULL,NULL),(51497,'速度与激情5','Fast Five','蛰伏2年之后，布莱恩（保罗·沃克 Paul Walker 饰）与多米尼克（范·迪塞尔 Vin Diesel饰）再度联手把火车中的神秘豪车盗走，遭到了警察和黑帮分子的火线追杀。布莱恩和米娅（乔丹娜·布鲁斯特 Jordana Brewster 饰）到里约寻找援兵，并与多米尼克会和。为了寻找多米尼克等人的下落，FBI王牌探员卢克（道恩·强森 Dwayne Johnson饰）挺身而出，组成精英部队，追查来到里约。他雇佣了丧夫的美丽女警艾莲娜（埃尔莎·帕塔奇 Elsa Pataky 饰），一同寻找多米尼克。与此同时，里约的地头蛇也对这些不速之客开火。三股势力开始相互缠斗。期间，因米娅怀孕，布莱恩决定陪她一起逃亡，所以多米尼克只得依靠昔日老友探寻新车的秘密。在罗曼、韩等人的帮助下，多米尼克终于找到了这辆车的秘密，并由此揭开了其中隐藏的一个不可告人的计划……','Get the Fifth Gear.',125000000,626137675,7.255718,7.1,2438,130,'2011-04-20','en','/gEfQjjQwY7fh5bI4GlG0RrBu7Pz.jpg',3.7720351740130416,3,'2026-09-10',2,NULL,NULL),(51540,'恶老板','Horrible Bosses','杰森·贝特曼、查理·戴和杰森·苏戴奇斯在片中饰演三个好友，他们都在工作中遇到了挫折，倍感沮丧和不满，最后他们得出结论：自己的种种不如意都要归罪于苛刻的老板。于是他们决定互相帮助，杀掉对方的老板。而詹妮弗·安妮斯顿和柯林·法瑞尔已经确定出演三个老板中的两个。如果凯文·史派西加盟，将是那第三个老板。另外，杰米·福克斯已经确定出演一名骗子艺术家，他将给主角们提供很多杀人的建议。','Ever wish your boss was dead?',35000000,117000000,50.309843,6.5,2277,98,'2011-07-08','en','/uQkUwgyFHAm0jGQERPG6Z9o9Zbj.jpg',3.715526615073228,3,'2026-09-10',2,NULL,NULL),(51588,'Prom','Prom','At “Prom,” every couple has a story and no two are exactly alike. As the big dance approaches for Nova Prescott, it’s a battle of wills as she finds herself drawn to the guy who gets in the way of her perfect prom. Fellow seniors Mei and Tyler harbor secrets, while others face all the insecurity and anticipation that surrounds one of high school’s most seminal events.','There are hundreds of nights in high school, but there’s only one prom.',8000000,10130000,11.837067,5.7,134,104,'2011-04-29','en','/istkPkmNTmKMCpEL1wH7I8Xa9he.jpg',2.9067547890111283,3,'2026-09-10',2,NULL,NULL),(51820,'The Salon','The Salon','A Beauty shop owner finds romance as she struggles to save her business.','Where you get more than just a hair cut!',1500000,0,2.02817,3.5,1,0,'2005-01-13','en','/uI38GTzFL00G2VJSzRUEuOnSE3s.jpg',1.9878556095936168,3,'2026-09-10',2,NULL,NULL),(51828,'一天','One Day','1988年7月15日，一所大学为毕业生的狂热所充盈。籍着这股躁动，轻浮的德克斯特（吉姆·斯特吉斯 Jim Sturgess 饰）穿过层层人墙，寻找可以与之共度这最后狂欢与浪漫之夜的尤物。他将目光锁定在艾玛（安妮·海瑟薇 Anne Hathaway 饰）的身上，一个来自普通工薪家庭的聪慧女孩。然而短短的交流过后，他们之间什么也没发生，却又注定改变了彼此的一生。在之后的岁月里，两人以友人知己的身份时聚时散，彼此分享着人生的苦辣酸甜和各种感悟。德克斯特经历着事业和婚姻的起落，艾玛品味着底层人生的辛酸。他们是远在天边心也紧紧相连的知己，是深锁心中最为笃真却相隔最远的爱恋……本片根据英国作家大卫·尼克尔斯（David Nicholls）的同名畅销小说改编。','Twenty years. Two people.',15000000,59389433,16.629173,7,978,107,'2011-03-02','en','/vdEgXbuem8d9rOIPfvU9KjW8Ob.jpg',3.5197343311747296,3,'2026-09-10',2,NULL,NULL),(51942,'我嫁了个怪蜀黍！','I Married a Strange Person!','这部片可以是加了幽默的《Akira》，添了人情味的《RoadRunner》，动画版的《低俗小说》（Pulp Fiction）。一个关于一对新婚夫妇在新婚之夜发生的温馨故事。丈夫格兰特（Grant）突然得到奇异的超自然力量，与此同时妻子凯丽（Kerry）窘于应付。无论何时，只要Grant一想什么，就会变为现实，尽管他并不知道这些魔力来自哪里。他从此成为清谈节目的风云人物。拉森·扎尔斯（Larson Giles），笑笑公司（Smile Corp.）老总，一个Ted Turner型媒体巨头，派遣他的私家军团，由粗暴但无脑的菲古森（Ferguson）上校率领，去绑架格兰特，以便霸占全球媒体收视率。接下来就是电影史上最暴力和奇怪的对战之一。除了多个足以开罪所有人的极端暴力画面，还有曾被称为“电影中有史以来出现的最怪异和滑稽的性场面”。',NULL,250,203,0.293649,7.5,12,72,'1998-08-28','en','/dyP1Zlj1lbhBHeO5veF5L7uqdsb.jpg',2.398170365257672,3,'2026-09-10',2,NULL,NULL),(51955,'浪漫之约','Hav Plenty','该片讲述的是一个小说家最终功成名就并且抱得美人归的故事。',NULL,0,0,0.003142,0,0,92,'1997-09-11','en','/vJutTuVdm5XxL3ixMFqw2o0AS8C.jpg',1.8337895622673928,3,'2026-09-10',2,NULL,NULL),(51995,'拯救林荫大道','Salvation Boulevard','改编美国著名作家Larry Beinhart最新创作的同名小说，讲述了一个牧师（皮尔斯·布鲁斯南饰）无中生有诬陷一个狂热嬉皮士犯罪的故事。  　　牧师Dan Day是个十分有魅力的家伙，他迷住了整个小镇并许诺他么发现不动产的美好前景。Carl则是个嬉皮士，the Grateful Dead乐队的前追随者，他发现Dan Day的福音新社区不过是为其心灵、道德改善计划服务……  　　丹是一个极有魅力的牧师,他的布道往往充满了ttmkv影视激情和发人深省的内容。整个城市的居民都很喜欢他,他的画像遍及整个城市,甚至还出现在了健身馆之中。他用“精神控制”的方法建立起了自己的“宗教商业帝国”。  　　正当丹踌躇满志地要进一步扩大自己的宗教商业的时候,卡尔莫名其妙地目睹了丹的罪恶--丹杀掉了一个有可能阻碍他敛财的教授。曾经的嬉皮士卡尔是丹的忠实听众,也是他的追随者之一。现在卡尔目睹了丹的罪恶,丹必须要有所行动才能自保。而卡尔,一样要有所行动才能让自己免于陷入不公正的牢狱之灾。  　　在信仰混乱,失控倒置的年代里,似乎没有什么是稳定且正确的选择。在谋杀案发生之后,地狱般的风暴开始酝酿。在这个小城里,究竟会发生什么?究竟还有多少不为人知的秘密藏匿于黑暗之中?  　　私家侦探卡尔接到一个棘手的案件，他原以为案情很简单，就是一名学生谋杀了他的大学教授，而警方也已拘留了这名学生，照理说这个案情已算是破案。  　　然而，卡尔偶然间发现死者是名无神论者，而这名被控告杀害教授的学生是信奉伊斯兰教的外籍留学生阿曼德，所以案情绝不单纯……  　　于是，卡尔请来了一名犹太律师为阿曼德辩护，而同时卡尔暗中调查此教授生前的交友状况，还有他死前所提倡的学说和著作，卡尔一步步发觉教授的死亡真相将指向上帝？难道一份驳斥上帝存在论的手稿，竟成了杀人动机？','Faith alone doesn’t cut it anymore',8000000,0,3.653305,5.6,28,96,'2011-07-15','en','/q8kPPcpPUGhdAOP5LYHDMKZBXYP.jpg',2.5676338484800993,3,'2026-09-10',2,NULL,NULL),(52010,'战锤40000：极限战士','Ultramarines: A Warhammer 40,000 Movie','极限战士团获得一个来自帝国神社世界的求救信号，一个完整的帝国公司掌握着那里，外界没有更多的消息，极限战士团打算调查那里看发生了什么事情。  　　《战鎚40K》的故事发生在遥远的未来。在《战鎚40K》的世界中，人类已经征服了不少星球。在人类君王的统治下，极限战士团的士兵们勇猛的和宇宙中的各种势力作战。虽然游戏被设定在未来并有著大量的科幻元素，但电影《战鎚40K》中也不乏经典的奇幻元素，精灵和兽人等种族都在游戏中出现过。  　　本片由马丁-皮克(Martyn Pick)执导，为这部时长70分鐘的CG电影配音的演员包括特伦斯-斯坦普(Terence Stamp)、西恩-帕特维(Sean Pertwee )以及史蒂芬-威丁顿(Steven Waddington)。负责编剧的是布拉克-莱布罗瑞(Black Library)和丹-阿佈内特(Dan Abnett)。','In the grim darkness of the far future there is only war',0,0,3.891186,5.2,27,76,'2010-12-10','en','/eFfkF9uVqOhAxIKEyNCHfRRdGgj.jpg',2.556464320266762,3,'2026-09-10',2,NULL,NULL),(52015,'刑柱之地','Stake Land','在一场吸血鬼疫情爆发后，美国进入后世界末日时期，一个少年在逃亡的旅程中，被一个灰白的吸血鬼猎人俘虏。这些吸血鬼和这个少年都是为上帝工作。　　美国是个失落的国度。吸血鬼活动猖獗，人们必须在这些阴险恶毒的野兽口中逃生，城市已沦为墓园，幸存者逃亡乡下，惧怕黑夜的降临。年轻的Martin家园被毁，但是他受到了一位头发灰白，刚愎固执的吸血鬼猎人的保护。 吸血鬼猎人带 Martin踏上了前往美国中心地带——封闭之城的旅途， 去寻找更合适的居住地，然而一路上充满了来自吸血鬼和怪物的威胁。一路上他们救下很多幸存者，包括一位因同伴都变成嗜血怪物而逐渐丧失信仰的修女。一群人谨慎地向北前行, 避开了被兄弟会封锁住的主道,。所谓的兄弟会是一支由Jebedia Loven率领的基督自卫队，他们认为这场灾难是上帝的杰作。寻找新的伊甸园之旅仍在继续。','The Most Dangerous Thing Is To Be Alive.',650000,33245,12.496261,6.2,285,98,'2010-09-30','en','/iNtaVkU2CEDidrhTjFrsjYGJfZW.jpg',3.0978823190983884,3,'2026-09-10',2,NULL,NULL),(52032,'牧羊犬郁金香','My Dog Tulip','改编自英国作家艾克利的小说，讲述自己晚年与新收牧羊犬苦乐交缠的生活。狗狗时而神经质，时而狗性流露，人狗之间，有点像情人，又有点像父女，细致温馨。Roger Ebert再次为这部电影亮出了满分。','Sometimes, love really is a bitch.',0,246574,1.170257,7.6,9,83,'2009-01-01','en','/8Q71A1mENLzE8jUlNe1HGybMJKW.jpg',2.3419013642089186,3,'2026-09-10',2,NULL,NULL),(52067,'大假一场','Cedar Rapids','艾德·赫尔姆斯扮演的Tim Lippe是个典型的“纯真”小镇青年，他从来没离开过他家乡的小城，他从来没住过酒店。所以，可想而知，当他作为保险代理人被总部召集到爱达荷州的Cedar Rapids大酒店，参加一年一度的保险业大会时，他的心情是多么激动。不过，兴奋劲儿还没过，几个讨厌鬼、也是大会的常驻代表（约翰·C·赖利、安·海切与Isiah Whitlock Jr. ）就掺乎了进来。他们带着Tim折腾得天昏地暗，不断挑战他的底线，除了“开会”别的什么他们都干了个遍……','Today is the first day... of the rest of his weekend.',0,6861102,10.254807,5.9,135,87,'2011-02-11','en','/cHi06HRvVNTNT12YUHvl5mRMLZj.jpg',2.914003264183579,3,'2026-09-10',2,NULL,NULL),(52449,'Bad Teacher','Bad Teacher','A lazy, incompetent middle school teacher who hates her job and her students is forced to return to her job to make enough money for a boob job after her rich fiancé dumps her.','She doesn\'t give an F.',20000000,216197492,28.497242,5.4,1584,92,'2011-05-16','en','/uUO8Mecko716EGfg46Fo5wc75nh.jpg',3.3524507621706063,3,'2026-09-10',2,NULL,NULL),(52451,'三个火枪手','The Three Musketeers','在一次行动，三剑客被米莱迪（米拉•乔沃维奇 Milla Jovovich 饰）和白金汉公爵（奥兰多•布鲁姆 Orlando Bloom 饰）背叛暗算，以失败归隐告终乡间。三年后，练就一手好剑术的达达尼昂（罗根•勒曼 Logan Lerman 饰）初出茅庐，来到巴黎投奔火枪队长特雷维尔（马修•麦克费登 Matthew Macfadyen 饰），与三剑客不打不相识，意外成为惺惺相惜的好友，同时也偶遇王后侍女，与之一见倾心。不久后众人意外得知权倾朝野的红衣教主黎塞留（克里斯托弗•沃尔兹 Christoph Waltz 饰）为了自己的灭国计划，想要挑拨英法两国关系，意欲制造一起皇室丑闻，使国王路易十三对王后安娜产生误会。富有正义感的众人为了抗击红衣教主的邪恶阴谋，维护安娜王后的清白，保持英法两国的和平关系，和敌人展开了斗智斗勇的比拼。达达尼昂更是凭借出色的剑术和足智多谋的头脑在这场争斗中崭露头角….','Every legend has a new beginning.',75000000,132274484,36.605246,5.6,924,110,'2011-08-31','en','/7CGzKcSOCMWc1yrAQBfSGUUpZa7.jpg',3.314475362704829,3,'2026-09-10',2,NULL,NULL),(52462,'私人宠物','The Pet','一个面临严重经济困难的女人接受了当一个有钱贵族宠物六个月的工作。然而这个残忍的“宠物绑架者”绑架了这个女人并把她卖到了国际奴隶市场上。',NULL,0,0,1.284741,5.3,3,94,'2006-05-17','en','/k6UZzTszSpIysEt3mk47U93iS0v.jpg',2.136747096022778,3,'2026-09-10',2,NULL,NULL),(52520,'黑夜传说4：觉醒','Underworld: Awakening','终于有一天，人类向日渐增多的血族和狼族宣战，这两个族群遭到大肆围剿与屠杀，人类取得绝对的优势。塞琳娜和约翰也在这场浩劫中遭难，当她再次醒来时，却发现自己被名为抗原研究所的机构囚禁起来，编号实验品1号。她奋力突破了束缚，根据共视的能力在黑暗的都市中寻找实验品2号——约翰。途中她遭遇血族的同伴相助以及狼人的袭击，当她找到被狼人们追逐的实验品2号时却发现，眼前竟是一个从没见过面但有着极为恐怖力量的小女孩——伊薇，而她是血族与狼族的混血儿。在这个陌生的时代，塞琳娜注定继续过着血雨腥风的生活……','Vengeance Returns',70000000,160112671,58.401204,6.1,1862,88,'2012-01-19','en','/n9hAw7YTxXPBwVt5V6cGOC8puNB.jpg',3.599569878470117,3,'2026-09-10',2,NULL,NULL),(52790,'The Basket','The Basket','Peter Coyote (E.T., Erin Brokovich) and Karen Allen (The Perfect Storm) star in this touching family drama about the unifying power of basketball in a community torn apart by war. Both a riveting sports film and a tale of triumph over adversity, The Basket is \"a hoop dream movie with a whole lot of heart\" (Dallas Morning News)! In 1918, when the wheat-farming townspeople of Waterville, Washington, welcome home their first wounded son from WWI, they\'restruck by the harsh reality of war. And just as bigotry and hatred toward two German orphans dividethe close-knit community, a new schoolteacher, Martin (Coyote), rolls into town with some strange ideas and an even stranger leather ball. Through the brand-new game called basketball, Martin strivesto bring harmony to the town...before it tears itself apart!',NULL,0,619042,0.430758,6.5,6,105,'2000-05-05','en','/4i98DTRSDGk6JiKBc1LDBvxelw.jpg',2.2582647924096433,3,'2026-09-10',2,NULL,NULL),(53113,'亲情无价','One True Thing','本片根据《纽约时报》专栏作家安娜·昆德兰（Anna Quindlen）1994年的同名小说改编。艾伦·戈尔登（芮妮·齐薇格 Renée Zellweger 饰）从哈佛大学毕业后供职于纽约某杂志，事业正在上升期，却因母亲凯特（梅丽尔·斯特里普 Meryl Streep 饰）身患癌症不得不放下工作返回宾夕法尼亚州的朗赫恩小镇照顾家庭。艾伦一直很崇拜教授美国文学的学者父亲乔治（威廉·赫特 William Hurt 饰），但不太看得起身为家庭妇女的母亲。在照顾母亲的过程中，艾伦发现了母亲生活的不易，也发现了父亲的很多黑暗秘密。就在家庭关系的摇摆震荡中，艾伦终于第一次了解了自己的父母，也终于找到了生命中最真实的感动。  　　本片被提名奥斯卡、金球奖和金卫星奖最佳女主角奖（梅丽尔·斯特里普），并获美国电影音效剪辑工会金胶卷奖最佳声音剪辑提名。 ©豆瓣','Love What You Have.',0,0,2.644427,6.2,27,127,'1998-09-18','en','/pYl3a0FkmGGne3ffkO5Bo7Tv9Y2.jpg',2.564338842057491,3,'2026-09-10',2,NULL,NULL),(53182,'300勇士：帝国崛起','300: Rise of an Empire','据漫画家弗兰克·米勒介绍，前传故事比《300勇士》要早上10年，以马拉松战役为起点。前传暂以“薛西斯”（Xerxes）为名，他就是《300勇士》中的波斯王，薛西斯在公元前5世纪成为“万王之王”，继承父亲大流士的意志远征希腊。前传的主要人物是被称为雅典海军之父的特米斯托克利（Themistocles），他成为希腊的统治者并建立了海军，同时也是斯巴达国王列奥尼达斯（Leonidas）的死对头。','Seize your glory!',110000000,337580051,71.510596,6.1,2397,102,'2014-03-05','en','/gNvSHWW4vQozM3754dUrzRpCyyn.jpg',3.684150406694207,3,'2026-09-10',2,NULL,NULL),(53256,'三角恋','Drei','汉娜（苏菲·罗艺斯 Sophie Rois 饰）和西蒙（塞巴斯蒂安·施普尔 Sebastian Schipper 饰）永远都不会想到，他们之间稳定而坚固的婚姻也会有濒临破碎的这一天，一个名叫亚当（大卫·史崔梭德 Devid Striesow 饰）的男人的出现让这一切变成了现实。面对英俊又深情的亚当，汉娜沦陷了，尽管背叛婚姻的罪恶感从未放过她，但她还是义无返顾的跌进了偷情的深渊中去。','Imagine the possibilities.',0,2611555,5.937602,6.3,31,119,'2010-12-23','de','/z3P5uHDMhH5voOtZnspMRs6Olyp.jpg',2.6022148327481145,3,'2026-09-10',2,NULL,NULL),(53457,'莎拉的钥匙','Elle s\'appelait Sarah','本片通过女记者朱丽娅（克里斯汀·斯科特·托马斯 Kristin Scott Thomas 饰）的视角重现了二战期间发生在法国巴黎东赛馆事件中的一个悲伤的故事。1942年，在德国占领下的法国巴黎被要求交出居住在巴黎的犹太人。十岁的萨拉（梅路什·玛亚奇 Mélusine M ayance 饰）和她的家人也未能在这次浩劫中幸免于难。在军队搜捕来临之际，萨拉将年幼的弟弟悄悄锁进家中的衣柜保护起来，并小心翼翼地收好了衣柜的钥匙，满心希冀可以通过这个方法让弟弟免于德军的搜捕。可是向往集中营的萨拉意识到这次离开不是一天两天的时候，她拼命逃出集中营回到旧居。可是迎接她的不仅是已经搬进的新住户，还有在衣柜中已经不幸遇难的弟弟。朱丽娅因工作原因受命对这则故事进行挖掘。在采访的过程中她不仅发现了当年掩盖的真相，同时也发现了自己与萨拉一家千丝万缕却又好似命中注定的联系。',NULL,10000000,17511906,10.072199,7.2,196,111,'2010-09-16','fr','/73mNU1Dgc5ClgMEIyklLwMRwinI.jpg',3.0731878431728084,3,'2026-09-10',2,NULL,NULL),(53502,'死者的亡灵','The Dead Undead','Good Vampires battle Zombie Vampires while trying to hide their own identity and prevent the infection from spreading.','How Do You Kill Something That\'s Already Dead?',0,0,0.249457,3.1,6,90,'2010-05-13','en','/hnRcpyyhjhjBrS5KVGXM2SA1Dz3.jpg',2.2495176765948237,3,'2026-09-10',2,NULL,NULL),(53862,'Trippin\'','Trippin\'','Greg is near the end of his senior year in high school, wanting to go to the prom, eyeing Cinny (the school\'s beauty with brains) from afar, and regularly trippin\', daydreaming about being a big success as a poet, a student, a lover. His mom wants him to apply to colleges, but Greg hasn\'t a clue. One of his teachers, Mr. Shapic, tries to inspire him, too. He finally figures out he can get close to Cinny if he asks her for help with college applications. But friendship isn\'t enough, he wants romance and a prom date. So, he tells a few lies and, for awhile, it seems to be working. Then, things fall apart and Greg has to figure out how to put the trippin aside and get real.','He\'s a legend in his own mind.',0,9016377,0.185373,4.5,4,94,'1999-05-12','en','/gKdbdPg6Ye8TOpGGDFQ0NeVVSSI.jpg',2.181048749702176,3,'2026-09-10',2,NULL,NULL),(53953,'The Tooth Fairy','The Tooth Fairy','A woman and her daughter (Nicole Muñoz) encounter a deadly legend at a bed-and-breakfast.',NULL,0,0,0.716764,4.3,13,0,'2006-08-08','de','/i0dms1hH1ObbysPscPDKjgqNns0.jpg',2.3989491290315312,3,'2026-09-10',2,NULL,NULL),(54054,'One for the Money','One for the Money','An unemployed lingerie buyer convinces her bail bondsman cousin to give her a shot as a bounty hunter. Her first assignment is to track down a former cop on the run for murder – the same man who broke her heart years before. With the help of some friends and the best bounty hunter in the business, she slowly learns what it takes to be a true bounty hunter.','She\'s looking for a few not-so-good men',40000000,36893721,19.438503,5.3,388,91,'2012-01-26','en','/eeltLl5jLUl9d96tpKkCAWu4JWu.jpg',3.0884353418121675,3,'2026-09-10',2,NULL,NULL),(54138,'星际迷航2：暗黑无界','Star Trek Into Darkness','在尼比鲁星球探查期间，企业号舰长柯克为营救史波克采取了胆大妄为的举动，几乎危及全舰队员的生命，他也为此付出代价。 不久，柯克官复原职，而伦敦发生一起死亡超过四十人的恐怖袭击事件。该事件的始作俑者约翰·哈里森正来自联盟内部。此后他驾驶飞机袭击了高层会议，柯克最为敬重的派克将军不幸遇难。为了阻止哈里森的外逃阴谋，柯克重新率领企业号启程追击。危机重重的旅途，他和舰员、朋友之间的信任也受到巨大考验。  当他们最终找到哈里森，才终于知晓他的真实身份，以及伦敦袭击事件背后的阴谋和黑幕……','Earth Will Fall',190000000,467365246,78.291018,7.4,4418,132,'2013-05-05','en','/Aim3kVNh1MPIxPEFeJrl9e9Uf1a.jpg',4.166828504210744,3,'2026-09-10',2,NULL,NULL),(54518,'贾斯汀·比伯：永不言败','Justin Bieber: Never Say Never','该片为贾斯汀·比伯（Justin Bieber）职业生涯的首支纪录片音乐电影。讲述了加拿大歌手贾斯汀·比伯的成长经历，2010年贾斯汀·比伯展开了他的首次巡回演唱会，其中包含了演唱会的片段与贾斯汀·比伯的成长影像。','Find out what\'s possible if you never give up.',13000000,98441954,6.735922,4.8,154,105,'2011-02-11','en','/dGNMD5XTBQN3teIth21ohKOCJcR.jpg',2.875612284557629,3,'2026-09-10',2,NULL,NULL),(54580,'Mondays in the Sun','Los lunes al sol','After the closure of their shipyard in Northern Spain, a few former workers: Santa, José, Lino, Amador, Sergei and Reina keep in touch. They meet mainly at a bar owned by their former colleague Rico. Santa is the most superficially confident and the unofficial leader of the group. A court case hangs over him relating to a shipyard lamp he smashed during protest against the closure. José is bitter that his wife, Ana, is employed when he is not. The gap between them is widening and he is fearful that she will leave him for a co-worker. Despite arthritic legs, Ana endures night shifts at a fish factory and thinks her looks are now lost. Not everyone seems to agree including her boss. Lino, an aging family man doggedly pursuing positions beyond his qualifications. The oldest member of the group, Amador, has degenerated into alcoholism after being abandoned by his wife; maintaining an increasingly transparent pretense that his wife will soon return from holiday.','This film is not based on a real story. It is based on thousands.',4000000,146402,3.663108,7.1,36,113,'2002-09-27','es','/zQ5i3LDn25k2HhLOm3fjaXcjkux.jpg',2.6402005465883795,3,'2026-09-10',2,NULL,NULL),(54702,'怨恨','Malevolence','It\'s ten years after the kidnapping of Martin Bristol. Taken from a backyard swing at his home at the age of six, he is forced to witness unspeakable crimes of a deranged madman. For years, Martin\'s whereabouts have remained a mystery...until now.',NULL,450000,0,1.077321,4.9,14,90,'2004-09-10','en','/l7JVY5uGMeOkEDNYIFLmZcEEQze.jpg',2.417428988286011,3,'2026-09-10',2,NULL,NULL),(54897,'宽恕的力量','The Grace Card','讲述同为警察的两位主人公Sam与Mac是好友，在一次事故中Mac失去了一个儿子，从此他失去了对上帝的信任。同时Sam也厌倦于警察的差事，希望能够进入ZF，于是这两人便在各自的烦恼中互相扶持前进的故事。','Never Underestimate The Power Of Grace ...',200000,2295733,0.616283,6.5,10,101,'2011-02-25','en','/bbWsYKtWTNtECusWJs3tvpTGlwO.jpg',2.3574602861574427,3,'2026-09-10',2,NULL,NULL),(55123,'风滚草','Tumbleweeds','A woman constantly runs from town to town with her 12 year old daughter to escape failed relationships. The film opens with one escape and the shift into a new start in San Diego. There Mom takes up with a controlling trucker and fights with her weirdo boss. Meanwhile, the daughter, used to making the constant shifts, finds a fit at school including getting chosen for a play lead.','They ran away from everything but each other.',312000,1281176,1.505703,6.2,11,102,'1999-11-28','en','/2SdW45O7bPDTe0zLzNHhEcacNAk.jpg',2.3772023518159093,3,'2026-09-10',2,NULL,NULL),(55180,'The Last Big Thing','The Last Big Thing','From a bland tract house on the outskirts of Los Angeles, Simon Geist (with occasional help from his platonic girlfriend Darla) wages war against all of modern American popular culture. Geist starts up a magazine called \"The Next Big Thing\", which he uses to confront and insult upcoming actors, comics, models and rock bands. As Geist\'s mysterious Underground Agenda escalates, will he become the \"last big thing\", or be co-opted by the very forces he is railing against? Written by Van Film Fest','The culture is going down on itself... go ahead, Scream!',0,0,0.678475,6,3,98,'1998-09-23','en','/cWacMZJuVBXxjlH5MoogNGd4B1C.jpg',2.1362235911746037,3,'2026-09-10',2,NULL,NULL),(55301,'鼠来宝3：破碎的旅程','Alvin and the Chipmunks: Chipwrecked','戴夫和自己的花栗鼠们又开始了一次冒险之旅。 这次，他们的旅行来到了一艘豪华的游船上，去参加国际音乐大赛。花栗鼠们不顾戴夫的劝阻，在游船上又跳舞、又喝酒还兼带着赌博。一开始，事情总是很好玩，但是渐渐玩过火的花栗鼠们在船上玩起了“动力伞”。一不小心，出了事故。一大群花栗鼠被风吹到了一个锡利群岛上。戴夫和伊恩也不能幸免，他们也落到岛上，上岸的地点却与花栗鼠门不同。刚刚登陆的花栗鼠们觉得既慌张又恐怖，它们想尽一切办法找食物和晚上睡觉的栖身之所。很快，它们就适应了荒岛上的生活，认识了一位已在荒岛上生活9年的女士，她声称在一场飞机事故中，戴夫（是另一个）与其它乘客遇难，只有她幸存。岛上有一个活火山，即将爆发，花栗鼠们这个时候还没有意识到这很危险。戴夫和伊恩则努力去找花栗鼠们，戴夫希望找到和他像亲人一般的花栗鼠，而伊恩只想着赚钱，希望找到它们并重新变富有，甚至为此吃掉了花栗鼠们送给戴夫的项链，戴夫愤怒不已，与伊恩厮打。而花栗鼠们找到了两人，他们重新相逢，但Jeanette被那位女士拐走，她来这座岛的目的是找到藏在这里的财宝，而财宝藏在瀑布后面，入口很小，她便拐走Jeanette以取出。但火山已经爆发，他们制作的简易木船正在危险之中，但女士丝毫不愿离开，也不愿救在危险之中的戴夫，关键时刻，伊恩的话感动了女士，她和两位男士以及花栗鼠们逃离了活火山，成功参加了国际音乐大赛。','This holiday it\'s gonna get squeaky.',75000000,342695435,23.473004,5.4,484,87,'2011-12-14','en','/d5cLmFtWcg3P654LudS16vufQON.jpg',3.144928675696167,3,'2026-09-10',2,NULL,NULL),(55306,'养蜂人家','Ulee\'s Gold','Ulee是一名越战老兵，在佛罗里达州以养蜂为生。Ulee的家庭并不幸福，妻子病逝好几年，他至今未从悲痛中走出，儿子Jimmy在监狱里服刑，儿媳妇Helen离家出走，丢下两个女儿由Ulee抚养。所幸Ulee生性隐忍达观，生活还算平静稳定。Ulee从Jimmy口中得知，Helen由于与一群毒贩混在一起，在苦海中不能自拔。Ulee立刻出发去救出Helen，才发现原来控制Helen的人正是当年Jimmy的抢劫同伙，如果不把抢劫所得的十万美元还给他们，他们可能就会对Jimmy的两个女儿下手。与此同时，Ulee还必须帮Helen戒毒，幸好一位邻居，离异护士Connie向焦头烂额的他伸出了援手……',NULL,0,0,0.93392,6.5,19,112,'1997-06-13','en','/wMpZ7U7A0QHJptR9L573V3Y7SI0.jpg',2.4893849417051563,3,'2026-09-10',2,NULL,NULL),(55347,'初学者','Beginners','本片讲述了一个苦乐参半的故事：一名男子得知自己生命垂危的父亲是同性恋，并且有一位年轻的恋人。[焦点影业]','This is what love feels like.',3200000,5332926,11.933449,6.8,347,105,'2010-09-11','en','/mAquHAmoBgZ1omUNdNsnGVNX74c.jpg',3.1983688420826213,3,'2026-09-10',2,NULL,NULL),(55420,'另一个地球','Another Earth','讲述耶鲁的音乐教授一家人，一场车祸妻女去世，只有父亲活了下来，开车的女孩被判了4年，4年后她仍然非常愧疚，负罪感让她想离开，重新开始。她出狱后没有去尝试找好工作，而是自我惩罚地在一家家政公司做事。期间她尝试过各种方法，想死去，那个罪感压得她根本不能生活下去。后来她试着接近教授，发现他活得非常潦倒，就尝试着找借口成为他得家政工，每天去给他收拾房间，那房间真的很乱，常年的垃圾堆在那，酒瓶子，堆得满满的。后来她帮他慢慢恢复了继续生活下去的勇气，他爱上了她，后来女孩真的可以去另一个世界了，教授知道后为她庆贺。就在这晚，诚实的女孩把4年前她意外带走教授家人的真相告诉了蒙在鼓里的教授，教授知道真相懵了，把女孩赶走。后来女孩担心教授出事，又跑到他家强行爬窗户进去。教授见到她仍不肯原谅，仇恨差点使他掐死女孩。女孩绝望地不知所措，就把去另一世界的票给了教授。教授真的去了。女孩在回家路上碰到跟她长得一模一样的另一个她，在另一个地球，还有机会吗？',NULL,100000,1776935,25.402697,6.8,527,92,'2011-07-22','en','/qvGJK3lFzpifAdyIupMNdWNX0qr.jpg',3.3396893860008716,3,'2026-09-10',2,NULL,NULL),(55465,'猪头逛大街3','A Very Harold & Kumar Christmas','自上一次冒险已经过去了六年时间,哈罗德·李和卡玛都过着安静的生活,有了新的朋友和家庭。现在,他们在准备自己家的圣诞节。可是就在这个节骨眼上,卡玛收到了一个神秘的包裹。为了和自己的好朋友一起“探秘”,卡玛带着这个包裹来到了哈罗德的家。不过,事情的发展却变成了一出悲剧,他们不小心烧掉了哈罗德的岳父最钟爱的一棵圣诞树。为了不让老丈人发怒,他们发誓要走遍纽约,找一棵看不出来是赝品的替代品回来。可是,按照这两个人一贯的品行,这次的寻找圣诞树之旅,怕又是个充满了意想不到事情的奇幻大冒险了。','Christmas comes prematurely.',19000000,35387212,17.971883,6,328,108,'2011-11-04','en','/a9s6CExOaa3emMrLjfmiGxqUYcL.jpg',3.12294291273279,3,'2026-09-10',2,NULL,NULL),(55561,'等放工','Clockwatchers','随着一名新员工的到来，四位在同一信贷公司工作的女性临时员工之间的关系岌岌可危，因为这名新员工获得了一个永久职位，而这个职位本是其中一名女性一直在争取的。',NULL,0,0,1.196943,5.6,13,96,'1997-01-01','en','/s6Gm06rGhopHumkAiYkJ4DsdaK8.jpg',2.4068840859933713,3,'2026-09-10',2,NULL,NULL),(55567,'Standing Ovation','Standing Ovation','A group of young girls is competing in a nation teen music video competition.','Dance - Sing - Dream',0,531826,0.305922,3.9,6,105,'2010-07-16','en','/tPd7dnvIgzkvM8XLyC4mQCq21T1.jpg',2.2516073569788477,3,'2026-09-10',2,NULL,NULL),(55604,'繁荣小镇','Boom Town','麦克马斯克斯（克拉克·盖博 Clark Gable 饰）和桑德（斯宾塞·屈塞 Spencer Tracy 饰）是两名石油开采者，在经历了一系列的失败和破产之后，总算赚来了足够的钱，不仅偿还了债务，还在石油开采业站稳了脚跟。\r 　　一天，麦克斯马斯克斯在小镇上邂逅了一位名叫贝斯迪（克劳黛·考尔白 Claudette Colbert 饰）的女孩，两人共度了浪漫的一夜，然而，当麦克斯马斯克斯向贝斯迪表露真情时，后者却后娱乐。原来，桑德也爱慕着贝斯迪，最终，桑德选择了离开这段三角恋，成全了麦克马斯克斯和贝斯迪的爱情。哪知道在两人结婚一周年纪念日那天，贝斯迪发现麦克马斯克斯出轨了，得知此事怒火中烧的桑德和麦克马斯克斯一刀两断。','Where Men Are Rough And Tough . . . And Like Their Women The Same Way !',2000000,9172000,1.867004,6.5,8,119,'1940-08-30','en','/upPOcyAhnL0tDPL8MsTRrOJquiJ.jpg',2.3164307412663407,3,'2026-09-10',2,NULL,NULL),(55616,'寻找暗夜里的情人','Dracula: Pages from a Virgin\'s Diary','盖·麦丁将皇家温尼伯芭蕾舞团对布拉姆·斯托克经典吸血鬼故事的演绎，从舞台华丽移植至银幕，打造出一场融合舞蹈、戏剧与暗影的奢华盛宴，充满情欲张力。[Zeitgeist Films]',NULL,1596010,0,0.552361,6.9,8,75,'2002-02-28','en','/qioaICsGsr8Bu8yr6UGPLmV9crX.jpg',2.3147314235075216,3,'2026-09-10',2,NULL,NULL),(55720,'更好的生活','A Better Life','卡洛斯（德米安·比齐尔 Demián Bichir 饰）是一个从墨西哥偷渡到美国的“黑户口”。老婆离开了他，如今他和14岁的儿子相依为命。为了能让自己和儿子过上更好的生活，卡洛斯拼尽了全力，找自己的妹妹借了钱买来了人家淘汰的旧卡车和园丁必备的工具，整日里兢兢业业、少言寡语地给洛杉矶富有的人家整理花园。每当他爬上高树，眺望整个繁华的都市时，他心里都会充满对未来美好生活的希望。然而，正处在叛逆年龄的儿子却很难理解父亲的苦心，身为“外来人口”儿子，却在学校里遭受歧视和欺辱，也更加剧了与父亲关系的隔阂。\r 　　直到有一天，父亲赖以为生的旧卡车被街区里的小混混偷走，父子俩共同维持生计的救命稻草就此不见。两人也终于开始渐渐地消除隔阂，在一同寻找卡车的过程中，父子情得到恢复和加温。但残酷的现实却给这一对非法移民父子带来了更加残酷的考验……','Every father wants more for his son.',10000000,1759252,4.123533,7,54,98,'2011-06-24','en','/9zo2JyCP4Hz7mRkD9MiqW4wsywa.jpg',2.7317558926533456,3,'2026-09-10',2,NULL,NULL),(55721,'Bridesmaids','Bridesmaids','Annie’s life is a mess. But when she finds out her lifetime best friend is engaged, she simply must serve as Lillian’s maid of honor. Though lovelorn and broke, Annie bluffs her way through the expensive and bizarre rituals. With one chance to get it perfect, she’ll show Lillian and her bridesmaids just how far you’ll go for someone you love.','Save the date',32500000,288383523,17.107065,6.5,1661,125,'2011-04-28','en','/vARBoJMKVTaPMOkFhgzLiCe9hAy.jpg',3.563961863450473,3,'2026-09-10',2,NULL,NULL),(55779,'Final Destination 5','Final Destination 5','In this fifth installment, Death is just as omnipresent as ever, and is unleashed after one man’s premonition saves a group of coworkers from a terrifying suspension bridge collapse. But this group of unsuspecting souls was never supposed to survive, and, in a terrifying race against time, the ill-fated group frantically tries to discover a way to escape Death’s sinister agenda.','We all share a common destination.',47000000,157887643,38.555482,5.9,866,92,'2011-08-12','en','/hpsxQ5FvF27kNEepTAxslkYE8ye.jpg',3.356217433839975,3,'2026-09-10',2,NULL,NULL),(55787,'大象的眼泪','Water for Elephants','该片根据Sara Gruen的同名小说改编，讲述了大萧条时期一个流动马戏团的故事。《大象的眼泪》由《我是传奇》（I Am Legend）的导演弗朗西斯·劳伦斯（Francis Lawrence）执导，影片剧本由Richard LaGravenese改编。故事始于一位90多岁的老人对自己在经济大萧条时期生活的追忆，当时他来到一个二流马戏团承担起了打杂和照顾动物的工作，他亲眼目睹了马戏团对动物的种种虐待行为，并不知不觉爱上了一位残暴驯兽师的妻子。','Life is the most spectacular show on earth.',38000000,114156230,16.801218,6.7,850,120,'2011-03-15','en','/z7kf0rxRxilE7gsaF0DwEEvlmTV.jpg',3.432019340592635,3,'2026-09-10',2,NULL,NULL),(55831,'Boynton Beach Club','Boynton Beach Club','A handful of men and women of a certain age pick up the pieces of their lives and look for new love after the loss of their mates in this comedy drama from writer-director Susan Seidelman.',NULL,0,0,0.18887,6.8,3,105,'2005-08-05','en','/fUcoCzSGBTm2xHnGqH0D5kQV9lH.jpg',2.1360896095785384,3,'2026-09-10',2,NULL,NULL),(55903,'贝蒂·费希尔','Betty Fisher et autres histoires','贝蒂是法国知名的小说家，独立扶养四岁儿子约瑟夫，过着幸福快乐的日子；隔着几条街外的卡洛是郊区购物商场里的服务生，对儿子荷西漠不关心，并常常将生活的不如意发泄在荷西身上。  贝蒂患有精神燥郁症的母亲玛葛突然来访，再度勾起贝蒂幼年时期不愉快的回忆，而这时，约瑟夫又不幸于一场意外中过世，面对这个残酷的打击，贝蒂伤心欲绝，精神几乎崩溃。玛葛爱女心切，为了拯救女儿，也为了证明自己对贝蒂的爱，她「受朋友之托」「收容了」荷西','Crimes of passion are not always between lovers.',0,0,0.024186,7,3,103,'2001-09-01','fr','/ebo9Tgo8IYMmV7evHKEPXeKa7PQ.jpg',2.135959532058002,3,'2026-09-10',2,NULL,NULL),(56288,'非常小特务4：时间大盗','Spy Kids: All the Time in the World','表面上， 玛丽莎·柯兹·威尔逊有着叫人艳羡的生活，嫁给了著名的特务追踪电视新闻记者，刚生下了一个可爱的小宝宝，还有一对聪明伶俐的继子继女，但其实玛丽莎是个退休的特务。当疯狂的时间控制者发出警告说要偷走时间并征服全世界的时候，玛丽莎的生活发生了翻天覆地的变化。继女瑞贝卡和继子塞西也被卷入了战争，而他们发现自己无聊透顶的继母居然是曾经最棒的特务。带着令人眼界大开的新奇装备，非常小特务们非常有可能依靠智慧再一次拯救世界，并且让全家人团聚。',NULL,27000000,85564310,14.788073,4.4,222,89,'2011-08-18','en','/kci72YHN2CMAmhR4bZs4m02xmwb.jpg',2.9217052217860373,3,'2026-09-10',2,NULL,NULL),(56292,'碟中谍4：幽灵协议','Mission: Impossible - Ghost Protocol','特工汉纳威执行任务时遇害，核机密文件被女杀手莫洛（蕾雅·赛杜 Léa Seydoux 饰）截获。为了找回文件，特工班吉（西蒙·佩吉 Simon Pegg 饰）和特工简（宝拉·巴顿 Paula Patton 饰）从俄罗斯监狱救出了伊桑·亨特（汤姆·克鲁斯 Tom Cruise 饰）。他们接受的幽灵协议任务便是从克林姆林宫盗取核军事密码。然而，当他们接近目标时，却发现被恐怖分子亨德里克斯（迈克尔·恩奎斯特 Michael Nyqvist 饰）捷足先登，抢走了核军事密码。在爆炸中，亨特受困医院，遭俄特工的追捕，幸好他身手矫捷，才化险为夷。不过，亨特的上司也在混乱中丧生，只剩下其助手布兰德（杰瑞米·雷纳 Jeremy Renner 饰）与亨特死里逃生，加上班吉和简，逼上绝境的四人开始了最后一搏，从迪拜到印度，他们出生入死，与恐怖分子斗智斗勇……','No Plan. No Backup. No Choice.',145000000,694713380,77.77477,6.8,3972,133,'2011-12-07','en','/eRZTGx7GsiKqPch96k27LK005ZL.jpg',3.9852544128091614,3,'2026-09-10',2,NULL,NULL),(56491,'发射线','In Her Line of Fire','美国副总统,被称为是世界上第二个最有权利的人,在一次飞行中,遇到了飞机失事.幸存下来的三个人最后竟被附近岛上的叛军抓获.他们计划将总统\"出卖\"给仇视美国的恐怖分子.保护总统的女特工英勇矫健,但是无奈寡不低众,再加上没见过大世面的记者拖泥带水,如何才能确保总统安全?美国政府又将做出什么反应?是否能在危急中既救回总统,又不会引起国际争端....','Behind Enemy Lines No Man Can Stop Her. Only One Woman Can Touch Her.',0,0,0.429587,3.3,9,88,'2006-04-21','en','/oAIWeBpaJUXCdv1UDlYvFoawk7c.jpg',2.3244656690156122,3,'2026-09-10',2,NULL,NULL),(56601,'完美比赛','The Perfect Game','半个世纪之前，一群来自墨西哥北部蒙特雷城里的贫民窟里，一群衣衫褴褛的孩子们对棒球这项运动早已有了浓\r 　　厚的兴趣和天赋的能力。在别人眼里，这群瘦弱、寒酸的穷孩子们简直与棒球这项当时还算得上高贵的运动无法相提并论。就是这群连像样的球衣、球鞋、甚至球棒和球都买不起的孩子们，在“老邻居”塞萨尔(小克里夫顿·柯林斯饰)的教导和带领下，一战成名，继而征服并得到了墨西哥当地各界人士的支持，徒步北上，穿越国界，来到经济和棒球运动皆为世界前列的美国，参加享誉北美的职业棒球联盟的儿童级别比赛。\r 　　原来，这位隐姓埋名的塞萨尔，曾是多年前扬名职业棒球联盟的最出色职业棒球选手之一。但因不堪忍受种族歧视而愤怒退出。当他看到同样在贫民窟里为生活所困的孩子们却对棒球运动如此痴迷后，重新又唤起了对这项运动的热爱与激情。而在塞萨尔则还有另外一个高于棒球、高于体育比赛的梦想等待着他和孩子们去实现——在球场上用表现去打破部分美国人的种族歧视的观念，用奇迹去战胜自己、实现自己未竟的目标……','Dream for the fences.',12500000,3878993,0.903529,6.3,30,118,'2010-04-01','en','/kwn02B0AyQYXzftAo9StX8JD2JY.jpg',2.583750779253189,3,'2026-09-10',2,NULL,NULL),(56666,'फ़िज़ा','फ़िज़ा','In 1993 Fiza\'s brother disappears during the riots in Mumbai. In 1999 Fiza is tired of waiting and goes looking for him.','In Search of her brother',1000000,623791,0.043023,6.1,7,170,'2000-09-08','hi',NULL,2.2853896501785735,3,'2026-09-10',2,NULL,NULL),(56715,'时空访客','Just Visiting','康德公爵（让·雷诺 Jean Reno饰）是12世纪的贵族，这天他前来城堡与公主订婚，却遭到奸人迫害。他的酒杯里被投下巫婆的毒药，让他喝下了迷魂药。神志不清中，康德杀死了公主，被抓入大牢。  　　  仆人安德烈（克里斯汀·克拉维尔 Christian Clavier饰）去找巫师，让康德回到事件之前。但是，粗心的巫师却抓错了药，结果康德和安德烈去到了21世纪的芝加哥。他们遇上了康德的后人朱莉亚（克里斯蒂娜•艾伯盖特 Christina Applegate 饰），得知如果他们不及时回到12世纪，罗萨琳公主将无法复活，后人就会消失。但是安德烈却乐不思蜀了。他和一个女孩打得火热，并不大愿意回到12世纪。然而时间不等人，康德的归去越来越迫切，而安德烈却还在温柔乡里磨蹭。事情越来越棘手。','They\'re not just from another time, they\'re from France.',0,0,10.844882,4.8,171,88,'2001-04-06','en','/5D6NqNUqEPdN6rYeEQ4eYwrcuVg.jpg',2.9014524163562077,3,'2026-09-10',2,NULL,NULL),(56930,'烈焰狂澜','Tycoon','约翰.韦恩主演的彩色片，来自芝加哥的工程师在矿区修铁路....','Breath-taking Adventure !',0,0,0.042442,6.6,4,128,'1947-12-27','en','/kinlg9PjTwa6iCe0EdXDPBqUoRD.jpg',2.184162867232321,3,'2026-09-10',2,NULL,NULL),(57022,'阳光天堂','Sunshine State','一年一度的海盗节即将举行的前夕，黛兹瑞带着她的新婚丈夫瑞德回到了阔别十几年的家乡——迪勒那海滩。和以居住白人为主的林肯海滩一样，迪瑞那海滩不仅是大西洋海岸线上风景最为优美的海滩之一，也是当地黑人心中的一块圣地，因为，据生活在这里的长者说，早在一百多年前，是他们的祖辈把曾经的沼泽建造成今天这样一个美不胜收的圣地。\r 　　尽管离开家乡已有十几年的时间，但当初因为未婚先孕的旧事依然在熟悉的几个朋友之间被再次提起。然而，与不堪回忆的未婚先孕这件往事相比，一件更为重大的事情正在整个迪勒那海滩悄悄地进行。\r 　　为了开发迪勒那的旅游资源，并继而把迪勒那建成富人居住的风景区，圣地地产公司在政府的帮助下，开始不顾当地黑人意愿地规划迪勒那开发用地。尽管老一点的居民积极组织抗议聚会，但隆隆的推土机并没有因此而放慢前进的速度。\r 　　直到有一天，在被推土机锨开的地下发现一堆后来被证实是早期印地安人的头颅遗骨时，地产商才暂时停下继续推进的步伐。但尽管如此，多年以后，当现代文明的步伐一步步吞噬着迪勒那海滩时，一个“我们能为印地安人做些什么？”的诘问，仍然萦绕在当地长者和黛兹瑞的心头。','Greetings from ...',0,0,4.245123,6,10,141,'2002-06-21','en','/8OsgdG53vzF5uC8pCE61SA1tiNF.jpg',2.363717935093434,3,'2026-09-10',2,NULL,NULL),(57089,'小红帽2','Hoodwinked Too! Hood VS. Evil','上一集结束后，小红帽（Hayden Panettiere 配音）、奶奶阿比盖尔·帕科特（Glenn Close 配音）、大坏狼（Patrick Warburton 配音）和松鼠特维奇加入了尼基（David Ogden Stiers 配音）所领导的“永远快乐办事处”（简称 永乐会），共同维护着童话世界的和平与安宁。此后不久，小红帽受命前往遥远的山中接受“红帽姐妹淘”的集训。在此期间，两名德国小孩被邪恶的巫婆囚禁在姜饼屋，永乐会派出阿比盖尔等人前往营救，然而营救行动失败，阿比盖尔还被巫婆俘虏。 另一方面，红帽姐妹淘的最高秘宝——松露蛋糕的配方被窃，而松露蛋糕可以赋予人以神奇的力量。这两起事件之间有着千丝万缕的关系，小红帽匆忙赶回营救奶奶……','Not All Fairy Tales Go By the Book.',30000000,13521829,10.694417,4.8,131,86,'2011-04-29','en','/b6Y1PAyik8Cx3qwdcYquAYQSGVV.jpg',2.858474616755297,3,'2026-09-10',2,NULL,NULL),(57119,'婚礼大斗阵','Jumping the Broom','这部黑人喜剧讲述了两个不同背景的家庭聚集在一个葡萄园中，为期一周筹备一个婚礼，却发生很多笑料。','Sometimes the only way to get past family drama... is to jump right over it.',6600000,37710610,4.492455,6,56,112,'2011-05-06','en','/60OXQUsWfAdSimqwAAJ5EvBxTre.jpg',2.719569760798313,3,'2026-09-10',2,NULL,NULL),(57120,'米克的近路','Meek\'s Cutoff','故事发生在1845年，俄勒冈小道开辟的早期，三户家庭的篷车队雇佣了山地人史蒂芬·米克带领他们穿越卡斯卡德山脉。米克声称知晓一条捷径，却将队伍引向高原荒漠中一条无迹可循的小径，最终迷失于干旱的岩石与鼠尾草丛中。在随后的日子里，拓荒者面临着饥饿、干渴的折磨，以及对彼此求生本能日渐丧失的信任。当一名印第安流浪者偶然出现，拓荒者陷入两难：是继续追随已被证明不可靠的向导，还是信任这个一直被视作天生敌人的人。[Oscilloscope Films]','The Road to Civilisation is Not Always Civilised',0,876302,4.749885,6.5,77,104,'2010-09-05','en','/oc28NmVqLx0x8epu3Ih3LvX4zE9.jpg',2.8017898861717248,3,'2026-09-10',2,NULL,NULL),(57157,'青少年','Young Adult','尽管自己并不承认，但麦维斯 就是一个标标准准的大龄剩女。她独居，没有朋友，吃垃圾食品，写垃圾小说，更可悲的是，她的小说卖的并不好。某一天，她收到了喜当爹的前男友巴迪 的邮件，却错误的认为这是巴迪发给她的求偶信号。麦维斯振奋不已，决定改头换面，重返学生时代住过的水星镇，拯救她深陷婚姻漩涡的前男友。在水星镇，她遇见了曾经嘲笑过的胖子马特，马特让她赶紧打消挖墙脚的念头，因为巴迪的生活其实非常幸福美满，他的妻子也是一个非常有魅力的家庭主妇。麦维斯当然不相信，无奈现实狠狠的甩了她一个耳光，在旧日同学面前出尽了洋相的麦维斯猛然醒悟，巴迪快乐的生活让她充满嫉妒，但自己的生活又何尝不是他人眼中“最好的生活”。一夜之间，麦维斯终于从一个“青少年”变成了一个真正的“成年人”。','Everyone gets old. Not everyone grows up.',12000000,22939027,16.183746,5.6,364,94,'2011-12-16','en','/hoOOSHyHj7zVEkX3zE64AgDyjv4.jpg',3.1006550778473234,3,'2026-09-10',2,NULL,NULL),(57158,'霍比特人2：史矛革之战','The Hobbit: The Desolation of Smaug','距离孤山越来越近，矮人远征军的道路却变得异常艰险。他们躲过了苍白半兽人的不懈追杀，在幽暗密林前和甘道夫（伊恩·麦凯伦 Ian McKellen 饰）兵分两路，后者前往多尔哥多探寻索伦的动向，而霍比特人比尔博·巴金斯（马丁·弗里曼 Martin John C. Freeman 饰）和矮人们先是遭到巨大蜘蛛的袭击，随后又被精灵王子莱戈拉斯（奥兰多·布鲁姆 Orlando Bloom 饰）及其木精灵同伴捕获。比尔博急中生智，利用魔戒救出伙伴，继而引发了木精灵、半兽人和矮人远征军之间精彩纷呈的三方会战。借助巴德（卢克·伊万斯 Luke Evans 饰）的帮助，疲惫的矮人们暂时落脚长湖镇。近在咫尺的孤山城堡，沉睡在财宝中的巨龙即将醒来……','Beyond darkness... beyond desolation... lies the greatest danger of all.',250000000,958400000,94.370564,7.6,4524,161,'2013-12-11','en','/xQYiXsheRCDBA39DOrmaw1aSpbk.jpg',4.261486789453366,3,'2026-09-10',2,NULL,NULL),(57165,'诸神之怒','Wrath of the Titans','结束了与北海巨妖的战争，英雄珀修斯（萨姆·沃辛顿 Sam Worthington 饰）与儿子赫利俄斯（约翰·贝尔 John Bell 饰）在一座小村庄过着平静的生活。但是奥林匹亚的战火从未停歇，以宙斯（连姆•尼森 Liam Neeson 饰）为首的众神与泰坦巨人进行着旷日持久的惨烈战争，甚至连被宙斯囚禁良久的三神（天神宙斯、海神波塞冬、冥王哈迪斯）之父——克洛诺斯也即将复活。战争的天平渐渐向泰坦巨人一方倾斜，在冥王哈迪斯（拉尔夫·费因斯 Ralph Fiennes 饰）的策划下，宙斯误入冥界，神力尽失，遭到囚禁。为了驱逐黑暗，将光明带回大地，珀修斯重披铠甲，与一众英雄前往冥界营救宙斯，诸神的战火迎来了最关键的时刻……','Feel the Wrath',150000000,301000000,44.927635,5.5,1431,99,'2012-03-27','en','/1uqSFgRsC2pt9rIWHPxuLk02CPJ.jpg',3.392589506139344,3,'2026-09-10',2,NULL,NULL),(57201,'独行侠','The Lone Ranger','《独行侠》是一部惊心动魄的冒险电影，充满动作与幽默。独行侠这位带面具的著名英雄人物将会被以全新角度演绎。通过土著印第安人武士Tonto（约翰尼·德普饰演）之口，描述了主角约翰·雷德（John Reid，由艾米·汉莫饰演），一位法律的化身，正义的使者的故事——他们两人将带领观众登上逃亡列车，来一次史诗般的惊险之旅。两位主角在逃亡中不断产生各种搞笑的摩擦，他们必须通力合作，对抗贪婪和腐败。','Never Take Off the Mask',255000000,89289910,49.046956,5.9,2311,149,'2013-07-03','en','/27JtPp3pq9O8KRqOP0jKqwgm6qc.jpg',3.579312910788889,3,'2026-09-10',2,NULL,NULL),(57212,'战马','War Horse','1914年，在德文郡小镇，男孩艾尔伯特（杰瑞米·艾文 Jeremy Irvine 饰）目睹了幼驹乔伊的诞生。在集市上，它被频繁叫价，最终被艾尔伯特的父亲泰德（彼得·穆兰 Peter Mullan 饰）用30基尼的天价收入囊中，跛脚的他也因此得罪了地主。艾尔伯特与乔伊尽情 嬉戏，与朋友分享。然而，好景不长，地主登门拜访，称如果乔伊不能犁地将立刻将其带走，于是泰德赌上了全部家当。于是，艾尔伯特在逼迫之下，为乔伊套上了鞍蹬，强迫它犁地，甚至还使用了皮鞭，却不能让它屈服就范。为了还债，泰德亲自上阵犁地，功夫不负有心人，辛苦换来了收成，但是一场大雨毁了一切。德军来袭，父亲被迫将马变卖给骑兵军，换了30基尼。艾尔伯特虽然难以割舍也只能含泪送别乔伊踏上了前途未卜的战场。战争中，乔伊的主人不停在变，从英国上尉，法国老农与孙女，到德国骑兵，然而它真正等待的是艾尔伯特，他们能够重逢吗……','Separated by War. Tested by Battle. Bound by Friendship.',66000000,177584879,29.505574,7,992,146,'2011-12-25','en','/jZKBIbjU9hWHiMyh2lmwYIjubjx.jpg',3.553154599341545,3,'2026-09-10',2,NULL,NULL),(57214,'X计划','Project X','汤玛斯（汤玛斯·曼 Thomas Mann 饰）要过生日了，他在学校里的两个好友科斯塔（奥利弗·库珀 Oliver Cooper 饰）和JB（乔纳森·丹尼尔·布朗 Jonathan Daniel Brown 饰）打算为他筹办一场最疯狂的party，洗刷掉三人的屌丝身份。趁汤玛斯父母出去度周末，三人开始着手准备，他们向高中所有能接触到的同学发出了邀请，用假身份证买了酒，还搞来了摇头丸。入夜，原本担心无人前来的三人看着一波波人潮心花怒放，尤其是其中还有许多陌生美女，令三人更加荷尔蒙爆棚。人越来越多，派对也越来越疯狂，邻居投诉不断，无法阻止人们上楼和进父亲书房……汤玛斯感到越来越不安，但是科斯塔始终鼓动他享受疯狂，随着近两千人聚集，事态再也非三个少年能掌控……','Witness it',12000000,100000000,49.070321,6.5,1564,88,'2012-03-01','en','/iXaB2pWKkPvjDvKUML4iQxFOwFU.jpg',3.6224147545998,3,'2026-09-10',2,NULL,NULL),(57294,'Crying with Laughter','Crying with Laughter','Powerfully redemptive and darkly comedic revenge thriller set in the vicious world of stand-up comedy, starring Stephen McCole and Malcolm Shields.','A Bad Trip Down Memory Lane',0,0,0.108135,7,1,93,'2009-06-01','en','/cYAaZuFnhymi4jA1xMRV97xhZ6e.jpg',1.9849093512213851,3,'2026-09-10',2,NULL,NULL),(57431,'保姆奇遇记','The Sitter','诺亚•格里芬（乔纳•希尔 Jonah Hill 饰）是一个肥肥胖胖长的有些腼腆憨厚的大男孩，没有保姆经验的他因为妈妈的约会而不得不临时代替她去佩杜拉太太家做保姆的工作。佩杜拉太太有三个性格古怪的孩子，长相俊美的斯拉特是个同性恋，酷爱打扮的布莱斯总是喜欢浓妆艳抹，而罗德里格则是一个喜欢破坏的顽皮领养生。三个难对付的孩子让诺亚十分头疼，而与此同时他接到了女友玛丽萨以做爱为诱惑邀请他一起参加派对的电话。诺亚决定带上三个小孩一同前往，却不料在途中为女友买毒品的过程中，不仅三个孩子状况百出争吵不断，罗德里格更是顺手带走了毒贩卡尔装满卡洛因的罐子令四人引祸上身。而更加危险的意外是，罐子在争抢的过程中摔碎了。诺亚四人只得齐心协力，为了活命开始了逃亡之旅…','Worst. Babysitter. Ever.',25000000,34942188,19.428994,5.4,325,81,'2011-12-09','en','/jlGzZ8McDp73PAaWMeYCHWeHiM4.jpg',3.068815570173472,3,'2026-09-10',2,NULL,NULL),(57612,'海豚和鲸鱼','IMAX Dolphins and Whales: Tribes of the Ocean','本片导演是法国3D影像制作的先驱，从1986年起，参与超过三十部3D影像的制作。本片纪录了海豚与鲸鱼的栖息生态，透过3D的呈现方式，观众将体验彷如亲自在海底看到座头鲸在眼前游过的全新感受。',NULL,6000000,7518876,0.041651,8,3,42,'2008-02-15','en','/gvrzdrxr69ZdzjfMQ4evhujAGbF.jpg',2.137229891267063,3,'2026-09-10',2,NULL,NULL),(57800,'冰川时代4：大陆漂移','Ice Age: Continental Drift','《冰川时代4》紧接着《冰川时代3》的结尾，希德（约翰·雷吉扎莫配音）、曼尼（雷·罗马诺配音）、迪亚哥（丹尼斯·利瑞配音）等动物好不容易在这个冰冷彻骨找到一个适合居住的住所，但是，突如其来的大地震，使得他们又不得不继续迁居了——这次，给大家制造了大麻烦的，是那只视松果为毕生所求的小松鼠奎特。它与它的松果的追逐赛这次引发了地球板块分裂，原本相连的地表径自分裂成五大洲七大洋，导致生活在冰川的希德、曼尼和迪亚哥与家人、伙伴们分开，被迫以一块流冰开始了海上漂流，在海上他们会遇到恶劣的自然环境，大海怪以及海盗，这些阻碍会让他们回家的路变得坎坷漫长。\r 而在回家的旅途里，希德一行还遇到了另一个麻烦事：冰川时代的头号海盗，以及海盗们的奴隶。这些名为海瑞克斯的奴隶，它们长期受到海盗的压迫失去自由，因而不会说话，希德一行希望他们能一起联合对抗海盗，需要找到跟他们沟通的方式，话唠希德自告奋勇要与他们谈合作，却没想到海瑞克斯居然听懂了，合作就此展开。希德、曼尼、迪亚哥，加上这些小海瑞克斯，组成了一支特殊的作战团队，他们能否战胜凶恶的海盗，在变幻莫测的冰川时代重建自己的居所呢？','Manny, Diego, and Sid embark upon another adventure after their continent is set adrift.',95000000,877244782,65.229868,6.2,2672,88,'2012-06-26','en','/dfp1BZF7FxbBUyzHvMOI9t8NWDD.jpg',3.7168810722921535,3,'2026-09-10',2,NULL,NULL),(57825,'新娘与偏见','Bride & Prejudice','娜丽达（艾西瓦娅·雷 Aishwarya Rai Bachchan 饰）出生在一个传统的印度家庭之中，她有三个姐妹，都到了嫁人的年龄，为了将女儿们嫁进好人家，白先生（阿努潘·凯尔 Anupam Kher 饰）和白太太（Nadira Babbar 饰）可谓是费了不少的周章。  　　然而，聪慧机敏的娜丽达却并不愿意接受父母安排的姻缘，她相信，只有她自己才能决定，谁才是真正适合她的男人，父亲和母亲将娜丽达的举动视为叛逆，深感头痛。一次偶然中，娜丽达结识了名为达西（马丁·亨德森 Martin Henderson 饰）的富翁，起初，两人都看对方很不顺眼，处处挑刺找茬，关系十分紧张。然而，随着时间的推移，达西渐渐发现娜丽达并不是那种脑袋里空空的绣花枕头，而娜丽达亦发现了达西善良真挚的一面，爱情的火苗暗自滋长。','Bollywood meets Hollywood... And it\'s a perfect match',7000000,0,12.150871,6.5,110,111,'2004-02-11','en','/yqqo00GZqyG0dijKCqBbdQLUvht.jpg',2.8994463199036495,3,'2026-09-10',2,NULL,NULL),(57876,'51区','Area 51','今年秋季一部《午夜灵异录像》（Paranormal Activity）以一万多美元的超低成本在北美取得了一亿多美元的票房回报，让人啧啧称奇。眼下该片导演Oren Peli已经和派拉蒙公司再度签约，将让他们继续来发行自己的新片《51区》（Area 51）。\r 　　和《午夜灵异录像》一样，《51区》也是超自然惊悚片，不过其成本已经大幅攀升到了500万美元，尽管和别的影片比起来仍然属于低成本，但这已经是其前作成本的百倍了。《51区》讲述的是3个青少年受好奇心驱使溜进了位于美国内华达沙漠内利斯空军基地俗称51区的地方，外界盛传美国军方在这里掩盖了外星人存在的证据。\r 　　据透露，派拉蒙是在前不久的美国电影市场展会上达成这一协议的，他们将联合Incentive电影娱乐公司和Aramid娱乐公司，为这部《51区》及可能的续集提供高达七位数的拍摄资金。目前《51区》已经拍摄完毕，正在进行后期制作，预计明年就能和观众见面。另外，完成该片后导演Oren Peli还将为派拉蒙制作《午夜灵异录像》的续集。',NULL,5000000,0,7.794,4.2,151,91,'2015-05-15','en','/2ybImgPkkyJ2iLIVC67dgpgpy2K.jpg',2.843987596286616,3,'2026-09-10',2,NULL,NULL),(57943,'情书','The Love Letter','本片是坎贝尔史考特与珍妮佛杰森李主演的电视电影，剧情架构有点近似多年前轰动一时的《似曾相识》，是一部拍得十分细腻动人的超时空爱情片。剧情描述青年史科蒂柯里甘偶然在一张古董桌中发现了一封在一百多年前写好的情书，被信中传达的情意深深感动，进而对写信的女主人产生一种微妙的情愫。他不顾在现实生活中即将举行的婚礼，用一百多年前的墨水和邮票来响应了那封情书，不料因此产生了一段隔代的恋情。本片获得美国编剧协会的最佳电视编剧奖，导演丹寇蒂斯对浪漫迷离的气氛亦处理得可圈可点。','A letter from the past would change their future forever.',0,0,0.116873,4.7,3,98,'1998-02-01','en','/q7DKV2pIP6u5WvXIdUl2VA5hz3l.jpg',2.133341176267042,3,'2026-09-10',2,NULL,NULL),(58048,'惊爆上海滩','Shanghai Surprise','Glendon Wasey is a fortune hunter looking for a fast track out of China. Gloria Tatlock is a missionary nurse seeking the curing powers of opium for her patients. Fate sets them on a hectic, exotic, and even romantic quest for stolen drugs. But they are up against every thug and smuggler in Shangai.','A romantic adventure for the dangerous at heart.',17000000,0,0.138564,2.9,15,97,'1986-08-29','en','/8zsU3Vq9FG9Q0kTEYrl0CWDlvX2.jpg',2.4167128993383735,3,'2026-09-10',2,NULL,NULL),(58051,'真爱满屋','हाउसफुल','本片是喜剧，讲述了一个全世界最倒霉的小男人Aarush的故事。他相信只有找到“真爱”才能解决所有问题。  　　在他追求梦想的路上，他明白到人们是如何地互相依靠，而且这个世界的人们形形色色，各不相同。于是有趣的故事不断上演。','He found the girl of his dreams, he fell in love and he got married... to all three.',0,0,0.12082,5.2,29,135,'2010-04-30','hi',NULL,2.5621365880308935,3,'2026-09-10',2,NULL,NULL),(58151,'新天师斗僵尸','Fright Night','影片翻拍自80年代的同名经典恐怖片《天师斗僵尸》，故事讲述：。高中生查理（安东·尤金 饰）隔壁搬来了一户人家，是独居的男子杰瑞（柯林·法瑞尔 饰）。这个新邻居给查理的母亲（托妮·科莱特 饰）和女友艾米（伊莫珍·波茨 饰）留下了不错的印象，但很快查理在好友艾德（克里斯托夫·梅兹-普莱瑟 饰）的提示下发现了其中的问题。经过周密的调查，他发现杰瑞其实是一个吸血鬼！与此同时，杰瑞也开始露出狰狞面目，查理的家人也成为了捕食目标，查理要如何孤身一人与之对抗呢？','You can\'t run from evil when it lives next door.',17000000,24922237,18.27083,6,603,106,'2011-08-18','en','/hekpxaaqsJx2liu1XKBita5J8n7.jpg',3.250735105668162,3,'2026-09-10',2,NULL,NULL),(58224,'Mr. Popper\'s Penguins','Mr. Popper\'s Penguins','Jim Carrey stars as Tom Popper, a successful businessman who’s clueless when it comes to the really important things in life...until he inherits six “adorable” penguins, each with its own unique personality. Soon Tom’s rambunctious roommates turn his swank New York apartment into a snowy winter wonderland — and the rest of his world upside-down.',NULL,55000000,187361754,32.835777,5.7,751,94,'2011-06-17','en','/6E4VU9sCwfvhVSYfY2TNJ4ZFr9g.jpg',3.2840593008269052,3,'2026-09-10',2,NULL,NULL),(58233,'憨豆特工2','Johnny English Reborn','英国军情七处顶级特工约翰·英格利士（罗温·艾金森 Rowan Atkinson 饰）自5年前在莫桑比克的行动中失手后，从此销声匿迹，隐居在深山的寺院中修炼身心。但是他的人生注定充满波澜，受军情七处的召唤，约翰返回阔别已久的伦敦。此时他的老东家早已改组，新任领导帕梅拉（吉莲·安德森 Gillian Anderson 饰）命令他前往香港，阻止针对中国领导人的暗杀计划。令他意想不到的是，他的对手是一支名为“旋风”的全顶尖杀手的暗杀集团。5年时间让世界发生天翻地覆的变化，但约翰凭借修行得来的坚韧意志和智慧与杀手集团进行连番精彩刺激的较量，当然在这一过程中也闹出不少笑话。道高一尺，魔高一丈，约翰能否拯救前所未有的危机呢……','One man. One mission. No chance.',45000000,160078586,35.6585,6,1007,101,'2011-09-15','en','/BP1oKD2JXoc1h2uRmJtpMjAx0W.jpg',3.3973611316202588,3,'2026-09-10',2,NULL,NULL),(58428,'鬼店另有主','The Innkeepers','克莱儿（莎拉·派克斯顿 Sara Paxton 饰）和卢克（派特·希利 Pat Healy 饰）是一家有着悠久历史的洋基旅舍（Yankee Pedlar）的店员，无尽长夜中，两人插科打诨，海阔天空神聊，顺便应付各种各样的客人。这家旅舍以闹鬼著称，传说曾有个名叫玛德琳·奥马利的新娘，在旅舍举行婚礼的当天上吊自杀。店主害怕影响生意，于是偷偷藏起尸体长达三天时间。事发后店主引起民众的愤慨，而闹鬼的传言也不胫而走。克莱儿与卢克架起摄像机拍摄旅社的超自然画面，并试图探访鬼魂的真面目，这个糟糕的决定将他们带入万劫不复……\r 本片荣获2011年尖叫电影节（Screamfest）最佳配乐奖、2011年多伦多午夜电影节特别奖观众选择最恐怖影片。','Some guests never checked out.',750000,78396,14.386807,5.4,219,102,'2011-12-01','en','/piB48zE03wdje2R648EcQcdWjyE.jpg',2.988439894312255,3,'2026-09-10',2,NULL,NULL),(58431,'Pride and Prejudice and Zombies','Pride and Prejudice and Zombies','A zombie outbreak has fallen upon the land in this reimagining of Jane Austen’s classic tale of the tangled relationships between lovers from different social classes in 19th century England. Feisty heroine Elizabeth Bennet (Lily James) is a master of martial arts and weaponry and the handsome Mr. Darcy (Sam Riley) is a fierce zombie killer, yet the epitome of upper class prejudice. As the zombie outbreak intensifies, they must swallow their pride and join forces on the blood-soaked battlefield in order to conquer the undead once and for all.','Bloody lovely.',28000000,16374328,28.397048,5.5,640,108,'2016-02-04','en','/8bobvxNnCij8Pd38j9fsVhGx7GR.jpg',3.2161228235513986,3,'2026-09-10',2,NULL,NULL),(58492,'有史以来卖得最好的电影','POM Wonderful Presents: The Greatest Movie Ever Sold','初次公告中描述的影片作为“品牌宣传，广告和植入式广告的资助和品牌推广，广告和植入式广告成为可能的纪录片。”听起来像一个有趣的，如果不花哨，概念。','He\'s not selling out, he\'s buying in.',0,621951,0.692497,6.4,88,87,'2011-04-22','en','/qyPsCqMbTJznLu8KBWg0CLNRbIH.jpg',2.819352264734338,3,'2026-09-10',2,NULL,NULL),(58574,'大侦探福尔摩斯2：诡影游戏','Sherlock Holmes: A Game of Shadows','There is a new criminal mastermind at large (Professor Moriarty) and not only is he Holmes’ intellectual equal, but his capacity for evil and lack of conscience may give him an advantage over the  detective.','The game is afoot.',125000000,334615000,81.499621,7,3886,129,'2011-11-22','en','/2HsHurlnTOyU6yUS14gY6BQCyRs.jpg',4.038943537571751,3,'2026-09-10',2,NULL,NULL),(58595,'白雪公主与猎人','Snow White and the Huntsman','向冷酷无情的女王雷雯娜正在通过武力扩张着自己的版图。他已经讨伐下了好几个国家。就在他准备泰伯国的时候，她突然得到了一个消息：她的继女，白雪公主，已经命中注定地要成为“世界上最美的女人”，并且要取代她成为统一后的大王国的统治者。咽不下这口气的女王找来了自己的看家宝魔镜，魔镜告诉她，如果要继续保持美貌、统治王国并且永垂不朽的话，那么一定要杀死白雪公主并且吸尽她的生命。 　　被关押起来的白雪公主费尽千辛万苦从牢里逃了出来，并跑到了黑暗森林中。得知这个消息的女王非常生气，她派出了自己手下的猎人埃里克前往黑暗森林，杀了白雪公主。在黑暗森林中，埃里克突然良心发觉，他非但没有杀了白雪公主，反而成了她的守护神。两个人在黑暗森林里不断地逃命，突然之间，他们走到了黑暗森林的边界，进入了一个世外桃源般的地方。在这里，他们得知了女王的滔天罪行，并决议要复仇。而埃里克则教会了白雪公主战斗的技巧。 　　实力日渐强大的白雪公主带着埃里克、八个小矮人、从泰伯国里来的骑士、从小青梅竹马的情人威廉王子和一些随从，准备重新杀回皇宫，夺回属于自己的生活，并让命运成真……','The Fairytale is Over',170000000,396600000,77.178973,5.8,3118,127,'2012-05-30','en','/gZojVl1MJt7uBo5KHOsIMBVUcWo.jpg',3.6810599962347377,3,'2026-09-10',2,NULL,NULL),(58626,'暗杀名单','The Hit List','某晚，老实商人艾伦.坎贝尔（科尔.豪瑟 饰）在酒吧遇到一个神秘的陌生人，自称是一个专业杀手的乔纳斯.乔穆（小古巴.戈丁 饰），说他可以免费为艾伦暗杀5个人。开始艾伦以为这是一个拙劣的玩笑，随便拟定了他自己的私人暗杀名单。没料到，第二天名单上的人陆续被杀，所有的证据都指向艾伦。阿伦必须和时间比赛，停止这场荒唐的杀戮游戏......','Who\'s on your list?',6000000,0,4.957014,5.2,73,90,'2011-04-02','en','/tR88diuLaMMdxl9rBVdAKERzIjo.jpg',2.7547829864863527,3,'2026-09-10',2,NULL,NULL),(58680,'Woo','Woo','Gorgeous and extraverted Woo meets insecure and straight-laced law clerk Tim at a blind date.','It\'s Woo\'s world.. we\'re just living in it.',13000000,8026971,1.750054,5.5,10,84,'1998-05-08','en','/8K1IfJXWPW1N5J6ar8ZOLU47c98.jpg',2.3559873707931915,3,'2026-09-10',2,NULL,NULL),(58882,'雪花秘扇','Snow Flower and the Secret Fan','18世纪初的中国，妇女还保留着裹小脚的复苏。在湖南的某个小镇，百合与雪花按照当地风俗结为老同，自幼生活在一起，靠着女书交流彼此的心事，她们之间深厚的情感无人能够取代。随着年龄的长大，百合与雪花必须嫁作人妇，从此开始了各自的苦难人生。21世纪初，尼娜即将因公赴美，却在临行前夕得知好友索菲娅车祸住院的消息。索菲娅是她自学生时代便在一起的好友，她们更按照古老的风俗结为老同。这场车祸，让久久失去联系的两人重新聚首……',NULL,134005,1332231,2.260315,5.3,22,104,'2011-07-15','en','/jux5sZ3SJ6yYFtgnDVDJOUPa5JC.jpg',2.5126624587324335,3,'2026-09-10',2,NULL,NULL),(59108,'Tower Heist','Tower Heist','A luxury condo manager leads a staff of workers to seek payback on the Wall Street swindler who defrauded them. With only days until the billionaire gets away with the perfect crime, the unlikely crew of amateur thieves enlists the help of petty crook Slide to steal the $20 million they’re sure is hidden in the penthouse.','Ordinary guys. An extraordinary robbery.',75000000,152930623,36.743324,5.8,932,104,'2011-11-02','en','/5ICxhDpuuGfGoDJr8cT8Pca9svO.jpg',3.3500121125384346,3,'2026-09-10',2,NULL,NULL),(59436,'午夜巴黎','Midnight in Paris','吉尔（欧文•威尔逊 Owen Wilson 饰）携未婚妻伊内兹（瑞秋•麦克亚当斯 Rachel McAdams 饰）陪着岳父岳母来巴黎度假。他希望留在巴黎完成自己的第一部小说，但是伊内兹及其父母坚决反对。在一次用餐时，伊内兹遇到了昔日同学保罗夫妇，他们一同出游。保罗到处卖弄，跟导游（卡拉•布吕尼 Carla Bruni 饰）喋喋不休，令吉尔反感不已。午夜时分，他独自走在巴黎的街头，却被一辆路过的马车吸引住了。他随马车来到了一个名流派对，阴差阳错地结识了海明威、毕加索、菲茨杰拉德、达利（阿德里安•布洛迪 Adrien Brody 饰）、斯坦因（凯西•贝茨 Kathy Bates 饰）等，而且他更是迷恋上了毕加索和莫迪尼亚里的情人阿德里亚娜（玛丽昂•歌迪亚 Marion Cotillard 饰）...伍迪艾伦凭此片获69届金球奖最佳编剧',NULL,30000000,151119219,43.753585,7.4,1990,94,'2011-05-11','en','/4wBG5kbfagTQclETblPRRGihk0I.jpg',3.8659865882872895,3,'2026-09-10',2,NULL,NULL),(59440,'Warrior','Warrior','The inspirational story of an estranged family that finds redemption in the unlikeliest of places…the MMA ring. Tommy Riordan (Tom Hardy), an ex-marine with a tragic past, returns home and enlists his father (Nick Nolte), a recovering alcoholic and former wrestling coach, to train him for “Sparta”, the biggest MMA tournament ever held. But when Tommy’s underdog brother, Brendan (Joel Edgerton), fights his way into the tournament, the two brothers must finally confront each other and the forces that pulled them apart. What ensues is the most gut-wrenching, soul-stirring, and unforgettable battle of their lives.','Fight for Family',25000000,23057115,51.915025,7.7,1272,140,'2011-09-09','en','/iM8n4nZJPR2abpnyZ36FUgHiRjr.jpg',3.807589962078317,3,'2026-09-10',2,NULL,NULL),(59457,'克隆丈夫','Womb','瑞贝卡（伊娃·格林 Eva Green 饰）回到了童年生活过的临海小镇，在那里，住着一个她无论如何也要见到的人——儿时玩伴托马斯（马特·史密斯 Matt Smith 饰）。曾经的懵懂少年如今已经成长为男人，两人之间迅速的产生了奇妙的化学反应。没过多久，一场车祸夺走了托马斯的生命，悲痛欲绝的瑞贝卡做出了一个危险的决定——利用当代先进的基因克隆技术，复制托马斯的基因。十个月之后，一个名叫托马斯的婴儿呱呱坠地，作为生下他的母亲，瑞贝卡的心情十分复杂。  　　在托马斯的眼中，母亲是一个即神秘又极具魅力的女人，在她惊人的美貌里，隐藏着的是深深的哀愁和绝望，而她望向自己的眼神，也似乎包含了千言万语。纸终究包不住火，随着托马斯的渐渐长大，那个不能说的秘密也在逐渐的显影，待到真相被揭露的那一天，这两个痛苦的人该何去何从？','What are the consequences of giving birth to your dead boyfriend?',3100000,0,7.453347,5.9,92,111,'2010-07-15','en','/raTEzBZBflPyVhOls4PmrryvPos.jpg',2.827896452233322,3,'2026-09-10',2,NULL,NULL),(59678,'街区大作战','Attack the Block','英国伦敦南部篝火节的晚上，一群街头小混混Moses、Pest、Dennis、Jerome和Biggz正在抢劫一名护士Sam，突然一个庞然大物从天而降，把停在旁边的汽车砸出了一个大洞。当他们着手进行调查时，发现了一种寄居在陨石里的生物并杀了它。随着更多的外星生物侵入地球，为了保卫自己和整座城市，小混混与外星人展开了一场殊死搏斗。','Inner City vs. Outer Space',14350531,3964682,30.952377,6.3,733,88,'2011-05-12','en','/cApgYWZpRlbzGzbdJVzSkTeGwUm.jpg',3.3655284336316718,3,'2026-09-10',2,NULL,NULL),(59728,'第五节','The 5th Quarter','2006年2月，年轻的卢克接受了一名高中生的团队练习。在一个严重的不负责任和鲁莽的青少年驾驶的情况下，超过了卢克和其他年轻乘客的反对意见，司机失去了控制汽车几乎每小时90英里，旋转在一条狭窄的道路，并降落在堤坝约七十英尺以下。卢克遭受了无法弥补的脑损伤，两天之后在医院去世了——就在他第十六岁生日的前四天。','Rising from tragedy to triumph',6000000,399611,0.215464,4.7,12,97,'2011-03-25','en','/syFkrTRZ5aaHqia45cQbhLADkFB.jpg',2.3843780713151186,3,'2026-09-10',2,NULL,NULL),(59859,'Kick-Ass 2','Kick-Ass 2','After Kick-Ass’ insane bravery inspires a new wave of self-made masked crusaders, he joins a patrol led by the Colonel Stars and Stripes. When these amateur superheroes are hunted down by Red Mist — reborn as The Mother Fucker — only the blade-wielding Hit-Girl can prevent their annihilation.','You Can\'t Fight Your Destiny.',28000000,60700000,40.28635,6.3,2224,103,'2013-07-17','en','/rydDxelHmRilf6Pl028aAe1DPBt.jpg',3.641816820213909,3,'2026-09-10',2,NULL,NULL),(59860,'蒙特卡洛','Monte Carlo','三个年轻女孩Grace、Emma和Meg决定用她们攒下的钱踏上梦想中的巴黎之旅，却发现旅行完全变成了灾难。当她们决定从他们糟糕的游览中休息一下，进入了一家5星级酒店大堂时，Grace却被误认为是一位叫Cordelia的富有英国继承人。Grace便将计就计，假扮成Cordelia好让大家体验到她们应得的梦想中的假期，但事情并没有按计划进行，Grace喜欢上了一个叫Theo的法国男孩。Theo爱上了作为Cordelia的Grace，完全不知道Grace是个骗子。当真正的Cordelia到达酒店时，女孩子们该如何搞定这场意外呢？','She\'s having the time of someone else\'s life.',20000000,17425000,17.237143,6,593,109,'2011-07-01','en','/q5N7apcCXqU5z9DEp3cCQC8kg7k.jpg',3.2448885814418027,3,'2026-09-10',2,NULL,NULL),(59861,'拉里·克劳','Larry Crowne','汤姆·汉克斯自导自演，影片讲述了拉瑞·克劳因为失业不得不洗心革面，争取重新上岗，开始一次新生活。 　　拉瑞·克劳是一个工作勤勉、为人和善的大卖场工作人员。自从海军退伍之后，他就一直在这里工作，因为卖力、肯吃苦而且几乎从不发脾气，所以他是大卖场里的明星工作人员。不仅顾客喜欢他，而起老板对他也颇为赏识。可是裁员风暴来袭之后，拉瑞·克劳不幸被逐出了他工作了二十余年的卖场。 　　这突然而来的闲适生活要了拉瑞·克劳的命，他是一个闲不下来的人。在近几天思考自己的前途和规划未来无果之后，他向当地社区里的大学报了名，希望能用知识改变命运。在这所大学里，拉瑞很快就和各色人等结成了好朋友，他们有的是流浪汉、有的是贫民窟的孩子，到这里来的目的都是要改善自己的生活。没有课的时候，拉瑞会和朋友一起骑着自己的踏板车在城市中四处溜达。 　　在公共演讲的课堂上，拉瑞出乎意料地爱上了自己的老师，迷人的梅赛德斯·坦纳特。只不过拉瑞没有办法直接向其诉说他的情感，因为坦纳特是一个已婚女子，而且她把自己的精力都放在了教学上，无暇顾及学生的爱慕。 　　现在，一切难题都到了拉瑞的身上，这个单纯而善良的大男人似乎就要学到人生中最重要的一课了：当你认为生命中最美好的东西都不为你做停留的时候，你也就能发现生活的意义了。','Rediscover life and love',30000000,36160375,20.355458,5.7,359,98,'2011-06-30','en','/fgIaVBG58JgyEXRt8owSrU2v0bL.jpg',3.1175644761453034,3,'2026-09-10',2,NULL,NULL),(59917,'龙虎黑煞星','Cotton Comes to Harlem','The Charismatic black nationalist leader Rev Deke O\'Malley is trying to sell the people of Harlem a dream. Invest $100 in his company and live in Africa. But cops Gravedigger and Coffin know all about Deke and his fraudulent schemes that take advantage of the poor and the ignorant and can\'t wait for a chance to expose him.','Introducing COFFIN ED and GRAVEDIGGER, two detectives only a mother could love.',1200000,0,1.079125,6.7,13,97,'1970-05-27','en','/tW30OfbGhe2uFBw4cr6tKsZwCcl.jpg',2.4124010795724535,3,'2026-09-10',2,NULL,NULL),(59930,'墨水瓶','The Inkwell','16 岁的德鲁·泰特 (Drew Tate) 来自一个普通家庭，住在一个普通街区。只有德鲁是个问题儿童。他的父母经常吵架，为了避免吵架，他经常逃到街上。他陷入了严重的麻烦，他的父母决定与亲戚一起在玛莎葡萄园岛度过夏天。','Summer\'s Never Been So Much Fun!',0,8880705,0.269661,3.9,5,110,'1994-04-22','en','/b5qUq9l6ci9KzzAqYhpdxzjY7qi.jpg',2.2189487791404794,3,'2026-09-10',2,NULL,NULL),(59961,'藏身之所','Safe House','传奇间谍托宾·福斯特 曾经是CIA训练出的最顶尖的谍报工作者，也是CIA历史上最大的叛徒。因为他把很多秘密情报卖给了外国的谍报结构，给美国造成的损失难以估计。而CIA也派出了大量的人力和物力来追踪他，只是一无所获。在隐匿了十几年之后，福斯特因为被追杀，不得已进入大使馆，从而浮出水面，回到了众人的视线里。马特·威斯顿 作为开普敦“安全屋负责人”的一名新人感到百无聊赖。福斯特正在被CIA送到自己的安全屋中，威斯顿已经做好全然的准备来迎接这个“贵客”。但是刚刚到达这个安全屋，一群雇佣兵就从天而降，他们是来追杀福斯特的。在护卫人员全部被杀之后，威斯顿不得不带着福斯特逃走。在东躲西藏的过程中，两人化敌为友，最后威斯顿可以证明自己的实力吗？福斯特又会面对怎样的命运？','No one is safe',85000000,208076205,34.773106,6.3,1345,115,'2012-02-09','en','/g4HTNLXGGc1sExuKGV2sKZNkgaB.jpg',3.51420096916317,3,'2026-09-10',2,NULL,NULL),(59962,'特工争风','This Means War','Tuck（汤姆·哈迪 Tom Hardy 饰）和FDR Foster（克里斯·派恩 Chris Pine 饰）是美国中情局的顶尖探员，两人是生死与共的好拍档、好朋友。两人各自身怀绝技，任何任务遇到他们都会迎刃而解。可这两个好朋友却有一个共同的硬伤——都是单身。后来两人分别使用交友网站找到了自己心仪的对象，并认定对方就是可以厮守终身的人。造化弄人，两人竟然爱上同一个姑娘——事业有成的女强人Lauren（瑞茜·威瑟斯彭 Reese Witherspoon 饰）。 为了赢得美人芳心，两个昔日好友大打出手，各自使出独门看家本领，更不惜出动中情局的特技武器。而Lauren也因他们各自拥独树一格的特有魅力陷入两难，究竟谁才会成为她的真命天子呢？','It\'s SPY Against SPY',65000000,156974557,38.994297,5.9,1389,103,'2012-02-14','en','/23FQscbQPnj2Dy9FwusThh6soqP.jpg',3.4525202224633773,3,'2026-09-10',2,NULL,NULL),(59965,'在劫难逃','Abduction','20岁出头的年轻人尼敦（泰勒·洛特纳饰）拥有一个看上去颇为完美的家庭，从小他生活在一个幸福的环境当中，不过自懂事起，尼敦总觉得自己过着形同虚设的生活，直到有一天他无意在失踪人口的网页里看到有人在寻找自己，盯着显示器里自己幼年的照片，尼敦才明白自己朝夕相处的“双亲”，竟然另有特殊身份，尼敦这才明白原来20多年来，自己一直活在一个精心编织的谎言当中。  　　尼敦准备查明真相，他清楚自己所谓的“父母”根本信不过，于是他只能将这一切告诉邻居凯伦（莉莉·科林斯饰）。正当尼敦和凯伦想搞清楚这是怎么一回事时，却意外的遭遇了职业杀手的追杀，他的“父母”在自己的眼前被害，警察把他当成凶手来追捕，于是尼敦和凯伦只能开始了惊心动魄的逃亡生涯，而他也在逃亡当中，离真相越来越近……','They stole his life. He\'s taking it back.',35000000,82087155,19.893646,5.6,961,106,'2011-09-22','en','/zWZnWpZrNHZNCkfdZjMs02kD2in.jpg',3.283334769266896,3,'2026-09-10',2,NULL,NULL),(59967,'环形使者','Looper','在本片的世界里，时间旅行虽已实现，却被列为非法且仅存于黑市。当黑帮需要清除某个目标时，他们会将目标送至30年前，由一位被称为“环形使者”的雇佣杀手——例如乔——负责解决。作为环形使者，乔一直表现优异，直到某天黑帮决定“封环”，将他未来的自己传送回来接受刺杀。[TriStar Pictures]','Hunted By Your Future, Haunted By Your Past',30000000,47042000,46.377628,6.6,4697,118,'2012-09-26','en','/sNjL6SqErDBE8OUZlrDLkexfsCj.jpg',3.902260631989608,3,'2026-09-10',2,NULL,NULL),(59968,'我们的傻老哥','Our Idiot Brother','Ned（保罗·路德 Paul Rudd 饰）是一个居住在城市里的“农民”。有一天，他在市场上出于同情卖了些毒品给一个警察，不料警察竟以贩卖毒品罪逮捕了他。因此Ned的女朋友将他赶出了家门，Ned只能去投奔他的妹妹们。他有三个妹妹，Miranda（伊丽莎白·班克斯 Elizabeth Banks 饰）是一个期待成名的记者；Natalie（佐伊·丹斯切尔 Zooey Deschanel 饰）是一个双性恋者，和她的同性恋人Cindy（拉什达·琼斯 Rashida Jones 饰）纠纷不断；还有Liz （艾米莉·莫迪默 Emily Mortimer 饰）嫁给了一个纪录片导演，两人的婚姻岌岌可危。Ned不管寄居在哪个妹妹的家里，都免不了和她们闹矛盾，更麻烦的是，三个妹妹本身的生活就有不少烦心的事。最后Ned竟然面临无家可归的危险。Ned该如何是好，来拯救他的生活，“顺便”拯救一下他的那三个妹妹？ ©豆瓣','Everybody has one',10000000,17273593,15.688439,5.9,365,90,'2011-08-26','en','/2HahJCcUEduvMUTQhsqRwutpFw1.jpg',3.130067094862965,3,'2026-09-10',2,NULL,NULL),(59981,'奥兹国的桃乐西','Legends of Oz: Dorothy\'s Return','美国动画片《奥兹国的桃乐西》，讲述桃乐西回到堪萨斯州，帮助她朋友的故事。 　　桃乐西刚回到堪萨斯州就发现她的朋友们正处在困难之中，于是她决定重回奥兹国帮助她的朋友们，他们会发生怎样的故事呢？让我们共同期待！','There\'s trouble in OZ...',70000000,18662027,6.682006,5.9,43,88,'2013-06-13','en','/5XiNCjFudNX0Wj5LanPuIb8E9pU.jpg',2.6672164710904047,3,'2026-09-10',2,NULL,NULL),(60243,'一次别离','جدایی نادر از سیمین','影片以当代伊朗为背景，讲述一段婚姻分崩离析的动人故事。西敏渴望与丈夫纳德、女儿特梅一同离开伊朗，在纳德因需照顾患阿尔茨海默症的父亲而拒绝离开后，西敏愤而提起离婚诉讼。离婚请求被驳回后，西敏搬回娘家，特梅却决定留在父亲身边。纳德在妻子离开后聘请年轻女工照顾父亲，期盼生活重归平静，然而当他发现女工竟对他隐瞒真相时，才惊觉自己面临的危机已远不止婚姻破碎这般简单。[索尼经典]','Ugly truth, sweet lies.',800000,0,12.049373,7.7,469,123,'2011-03-15','fa',NULL,3.3838755785197585,3,'2026-09-10',2,NULL,NULL),(60304,'韩赛尔与格蕾特：女巫猎人','Hansel & Gretel: Witch Hunters','在童话故事的15年后，韩赛尔与格蕾特兄妹已经长大，他们成为了两位厉害的女巫猎人，在一个小镇他们遇到了一个艰难的任务。','Classic tale. New twist.',50000000,224803475,53.02787,5.7,3239,88,'2013-01-17','en','/40X8zNy8vIfyWGrS70ezb96PsI5.jpg',3.609125358089131,3,'2026-09-10',2,NULL,NULL),(60307,'小屁孩日记2','Diary of a Wimpy Kid: Rodrick Rules','格雷格·赫夫利（扎克瑞·戈登 饰）又长了一岁，终于也进入了7年级，在生活中，他的哥哥罗德里格·赫夫利（戴文·博斯蒂克 饰）堪称他苦恼的源泉，格雷格也几乎习惯了被他捉弄。两人同时还要面对他们的父母，赫夫利夫妇（史蒂夫·茨恩 与 拉琪儿·哈里斯 饰）的折腾，夫妻俩总是认为兄弟俩关系出了大问题，试图重建他们的亲情关系。而与此同时，一个叫霍莉·希尔斯（佩顿·利斯特 饰）的女孩也走入了格雷格的生活，他也竭尽全力想要引起女孩的主意，这一次，小屁孩格雷格又将闹出怎样的笑话，同时收获怎样的成长感悟呢？','Welcome to the next grade',21000000,72417394,14.329891,6.3,238,99,'2011-03-25','en','/5A2OKHuGLKvl7PVyXu5MBY6cj2X.jpg',3.069558175283172,3,'2026-09-10',2,NULL,NULL),(60308,'点球成金','Moneyball','改编自迈克尔·刘易斯的纪实畅销书《点球成金：不公平比赛中的获胜艺术》，影片聚焦奥克兰运动家队总经理比利·比恩如何运用精密复杂的计算机数据分析选拔球员，以有限预算组建出一支棒球强队。[索尼影业]','What are you really worth?',50000000,110206216,46.180421,7,1381,133,'2011-09-22','en','/tS455u9EL6OnhsaOvIGBmzNvZd9.jpg',3.683808686719525,3,'2026-09-10',2,NULL,NULL),(60309,'共犯','The Conspirator','影片主要讲述了被宣判为刺杀林肯总统的凶手的“同谋”的玛丽·苏拉特的故事，由罗宾·怀特饰演。詹姆斯·麦卡沃伊将饰演玛丽·苏拉特的律师Frederick Aiken。这位信奉唯心主义的昔日的战斗英雄，不情愿地为玛丽·苏拉特进行辩护。然而在这一过程中，他渐渐地相信玛丽·苏拉特是清白的。　　林肯总统被刺，美国全体上下群情激愤，七个男人与一个女人遭到逮捕，被指控为凶手。本片的讲述的就是对这位“女同谋”玛丽·苏拉特（罗宾·怀特 饰）审判的故事。詹姆斯·麦卡沃伊扮演玛丽·苏拉特的律师Frederick Aiken，一位28岁的前战斗英雄。在辩护的过程中，他逐渐发现，玛丽·苏拉特是无辜的，她只是警方逮捕真正的凶手——她的儿子约翰——所放下的诱饵与人质。但是在全国上下一片的反对声中，玛丽·苏拉特必须依靠律师Frederick Aiken揭露事实、保住性命。　　在林肯遇刺案发生后，七个男人和一个女人立刻被逮捕，并被指控共谋刺杀美国总统、副总统，以及美国国务卿。那唯一被指控的女性名叫玛丽·苏拉特（罗宾·怀特 饰），42岁，拥有一个寄宿公寓，也正是在这里，约翰·威尔科斯·布思（托比·凯贝尔 饰）和其他人碰面并计划了这场刺杀行动。昔日的美国内战战士，新晋律师弗雷德里克·艾肯（詹姆斯·麦卡沃伊 饰），作为一个28岁的战斗英雄，极其不情愿的接下来为苏拉特在一个军事法庭辩护的任务。艾肯逐渐认识到，苏拉特是冤枉的，她的被捕很可能只是被用作一个诱饵和人质，以便诱出在大规模抓捕中逃脱的真正的同谋者：苏拉特的儿子，约翰·苏拉特（约翰尼·西蒙斯 饰）。','One bullet killed the President. But not one man.',25000000,15478800,9.169271,6.2,137,122,'2010-09-10','en','/2RKdHz88djPrnkm00yWD3q4JUEX.jpg',2.92881666808135,3,'2026-09-10',2,NULL,NULL),(60400,'青鸟','The Blue Bird','战争期间，迈蒂与蒂蒂俩人梦想着能有快乐的自由生活，贝露恩仙女告诉他们，有一种蓝色的鸟可以给人们带来幸福，于是他们偷偷离家出走，踏上了寻找“幸福鸟”旅途，最后发现就在自己的身边，而无需到远处探求。',NULL,0,0,1.280733,6.4,8,88,'1940-01-19','en','/4MLru2banKCbCC5iGOmqon3h569.jpg',2.314765686546173,3,'2026-09-10',2,NULL,NULL),(60420,'爱疯了','Like Crazy','安娜Anna（菲丽希缇·琼斯 Felicity Jones 饰）是来自英国的留学生，雅各布Jacob（安东·尤金 Anton Yelchin 饰）是土生土长的美国人。他们就读于同一所大学，不久两人相恋并过上了甜蜜的同居生活。可安娜的护照签证即将到期，为了爱情她留在美国，可移民局找上了门来强制遣送她回国，并宣布她永远不能再次踏上美国国土。远距离的恋爱让两人备受煎熬，在爱情的驱使下，雅各布一次次踏上了去英国寻找爱情的旅途。可紧跟着距离是不断发生的争执，两人分手了。随着时间推移两人在各自的国度都有了新的生活，可彼此心中却割舍不下彼此。他们会为了爱情再不顾一切的疯狂一次吗？这份热情还会跟当初一样吗？本片在2011年圣丹斯电影节上获得剧情片评委会大奖，女主角也赢得评委团特别奖。','I Want You. I Need You. I Love You. I Miss You.',250000,3542353,21.825564,6.4,381,90,'2011-10-28','en','/lIIBxXaZYBWoPRqcBVPV0LgTxGi.jpg',3.2042767579989557,3,'2026-09-10',2,NULL,NULL),(60421,'曖妹','Circumstance','一个富裕的伊朗家庭正在努力遏制一个青少年日益增长的性反叛和她哥哥新发现的保守主义。',NULL,0,0,2.34239,7.4,23,107,'2011-08-26','fa','/fs4Qi07K9htZzI73YaukSQFqmHk.jpg',2.541059947198103,3,'2026-09-10',2,NULL,NULL),(60422,'开心又一天','Another Happy Day','林恩（艾伦•巴金 Ellen Barkin 饰）有过一段非常失败的婚姻，虽然前夫如今已经再婚，但两人之间的关系依然十分的紧张。因为身无分文，林恩失去了儿子迪伦（迈克尔•纳德利 Michael Nardelli 饰）的抚养权，她带着另外的三个孩子独自生活。随着时间的推移，单亲家庭的恶果渐渐显现在了林恩的三个孩子身上，他们不是行为不端就是染上毒瘾，又或是脾气异常暴躁。  迪伦即将和未婚妻携手步入婚姻的殿堂，他邀请母亲出席他的婚礼。然而，这次赴约对于林恩来说无异于是酷刑，因为她知道，等待着她的，会是种种冷嘲热讽。没错，从小到大，家人对于林恩来说并不是规避风雨的港湾。','At this wedding, the F-word stands for Family',4000000,355688,3.238466,6.2,37,119,'2011-11-18','en','/yOS14Pr563QEUd3bath9LwhhId3.jpg',2.6323388057629136,3,'2026-09-10',2,NULL,NULL),(60463,'Sunday School Musical','Sunday School Musical','Two competing groups of high school students must rally together and enter a song and dance competition in order to save their church from closing.',NULL,0,0,0.46049,5.5,4,93,'2008-10-21','en','/vs7wexp8wnSpjQjpO3dM50E8ZJO.jpg',2.1833155520496788,3,'2026-09-10',2,NULL,NULL),(60599,'套利交易','Arbitrage','60岁的罗伯特·米勒（理查·基尔 Richard Gere 饰）是个事业有成的亿万富翁，备受业界尊重和家人崇拜。然而这都是表象，实际上他不仅私自在公司的账目上动手脚以掩盖投资损失和欺诈嫌疑，还背着妻子在外偷腥。一天夜里，米勒因疲劳驾驶而发生车祸，情妇当场死亡，而他逃离现 场。为了掩盖涉嫌谋杀和保住商业洽谈，米勒开始疯狂地销毁和制造证据，然而随着探员布莱尔（蒂姆·罗斯 Tim Roth 饰）的层层介入，以及自己的女儿似乎也觉察了个中蹊跷，米勒渐渐发现，他在谎言的路上已经越走越远……','Power is the best alibi.',12000000,35485056,16.40512,6.1,294,100,'2012-09-14','en','/oVJF2KTmNB8ZFkp0aUSay7d0Opf.jpg',3.105078290200698,3,'2026-09-10',2,NULL,NULL),(61012,'寂静岭2：启示录','Silent Hill: Revelation 3D','海瑟·梅森和父亲哈利·梅森在外面逃命已经多年，但她却总不明白那些对他们造成危险的东西是什么。多年来受神秘力量骚扰，更长期被毛骨悚然的恶梦弄得心绪不宁。18岁生日当日，她发现自己被偷偷跟踪，随之而来的事故也让父亲离奇失踪，只遗下一个神秘的讯息。在那场事件中，她发现自己的身份是伪造的，而自己对从前的回忆也成为了梦魇。这一切奇怪的梦和事，引领着她到达那个既陌生又可怕的国度——寂静岭。踏进这里后，海瑟发现很多惊人的真相，路上等待她的是恐惧的威吓，而她的身世之谜也慢慢被揭开。各种可怕的生物在这个地方出现，更有人告诉她她就是那个命中注定要来杀光所有梦魇和怪兽的人……','This Halloween prepare for a 3D ride through hell.',20000000,52302796,23.292761,5,432,94,'2012-10-10','en','/djn69YVetQnKUY8bxDxdo6rJwsV.jpg',3.080972520999934,3,'2026-09-10',2,NULL,NULL),(61038,'冲吧，舞动的节奏','Go for It!','影片讲述了一名墨西哥裔美国女孩卡门追逐舞蹈梦想的故事。',NULL,2450000,0,0.500753,4.6,5,105,'2011-05-13','en','/otMNSW5NH26XGVR7Y4Ok6YlsReR.jpg',2.220908267474231,3,'2026-09-10',2,NULL,NULL),(61337,'医院人生','Critical Care','沃纳·恩斯特（Werner Ernst）是一名年轻的住院部医生，他卷入一场因两个同父异母的姐妹之间的法律纠纷，这两个姐妹为了照顾昏迷的父亲而产生争执。但他们真的是在为如何更好的照顾父亲而争斗？还是为他的1000万美元的遗产而争斗？与此同时，沃纳必须与他的神经质主管抗争，后者坚持让他只照顾有全额保险的病人。沃纳能避开医院的法律团队，为病人做最好的事吗？',NULL,0,0,2.678715,6.1,9,107,'1997-10-31','en','/p4UPT3vvdKHsv6PbhvvtFm8w5Zx.jpg',2.3398549352257993,3,'2026-09-10',2,NULL,NULL),(61752,'6号女郎','Girl 6','一位在纽约奋斗的女演员，为了生计成为了一名电话性爱接线员。','A fresh, sassy and sexy comedy!',12000000,4939939,2.993939,5.7,16,108,'1996-03-22','en','/1SSYCOTrHucd9aBCyTfbLWcJ2zD.jpg',2.4531851440340744,3,'2026-09-10',2,NULL,NULL),(61791,'猩球崛起','Rise of the Planet of the Apes','Scientist Will Rodman is determined to find a cure for Alzheimer\'s, the disease which has slowly consumed his father. Will feels certain he is close to a breakthrough and tests his latest serum on apes, noticing dramatic increases in intelligence and brain activity in the primate subjects – especially Caesar, his pet chimpanzee.','Evolution Becomes Revolution.',93000000,482860185,138.433168,7,4347,105,'2011-08-03','en','/oqA45qMyyo1TtrnVEBKxqmTPhbN.jpg',4.1971455708578835,3,'2026-09-10',2,NULL,NULL),(61891,'匿名者','Anonymous','在伊丽莎白女王统治英格兰的时代里，政治风云变幻。都铎王朝的成员和一些贵族都在预谋着反叛计划。影片的主角是爱德华·德维尔，他就是著名的牛津伯爵，影片从他的视角展开了叙述。实际上，爱德华·德维尔不仅仅是伊丽莎白女王的乱伦情人，他更是所有莎士比亚作品的执笔人。在影片的讲述中，莎士比亚，不过是一个傀儡而已……','Was Shakespeare a Fraud?',30000000,15395087,16.698316,6.3,288,130,'2011-10-21','en','/mRjdFP0kqCPaDKeXgQtsb7how6e.jpg',3.118302500686003,3,'2026-09-10',2,NULL,NULL),(61984,'宇宙战舰大和号','SPACE BATTLESHIP ヤマト','公元2194年，突然出现在宇宙中身份不明的敌人对地球发起了进攻，全世界的战斗力量团结在一起抵御外敌。然而，人类所掌握的技术水平远负于敌方，因此在敌方宇宙舰队极具威胁力的攻击之下，地球军全线溃败。敌人在世界各地投下了无数的游星炸弹，超过半数的人类死亡。五年后，即公元2199年。游星炸弹中的放射性物质地球造成了严重污染，那个美丽的青色星球已经无迹可寻，残存下来的人们逃到地下生活。昔日的王牌飞行员古代进（木村拓哉 饰）已经退伍，为了回收资源而到地表进行搜寻工作。这一天，天空中出现了不明飞行物并落到了他的身边。事实上，这个不明飞行物是一个通讯密封舱，来自距地球14万8千光年的伊斯坦达鲁星。据此，人们判断出伊斯坦达鲁星有清除放射能的装置。地球联军在这个飞行器中找到了驱动器、波动引擎的设计图，并将唯一一个残留下来的战舰改造为宇宙战舰大和号。距离放射性物质毁灭人类还有仅仅一年的时间，为获得解除这种威胁的装置，古代进与船员们驾驶着大和号再度踏上旅程，伟大的战斗即将打响……',NULL,12000000,11212294,5.158067,6.3,59,131,'2010-12-01','ja','/4czAHcIlyVXjwWs4VpuyGJHyzOm.jpg',2.7388522823486796,3,'2026-09-10',2,NULL,NULL),(62008,'好人好事','Good Deeds','韦斯利是一个普世意义上的好人和成功者，无论是生活还是工作还是感情，他都能够安排的仅仅有条。无论是什么人提出的什么样的请求，出于好心韦斯利都会应允下来，而他的答复又总能够让所有的人都感到满意。可即便如此，韦斯利却始终对于生活缺乏真实感，他总觉得自己并不像一个有血有肉的人，而是一个被操纵的木偶。一天，韦斯利在楼梯间邂逅了名为林赛的清洁工。林赛是一名单身母亲，她的丈夫在不久之前离开了她，丢给了她一个调皮的孩子，林赛仅剩的，就是这份大楼保洁的既辛苦又卑微的工作。林赛的出现彻底打乱了韦斯利的人生，让他的生活走向失控。','Wesley Deeds is About to Discover the Person He Was Meant to Be.',0,0,4.448494,6.2,45,111,'2012-02-23','en','/vIiWJq4WPcTfaIH8VkVlU2irzXo.jpg',2.6768479393835216,3,'2026-09-10',2,NULL,NULL),(62116,'娜内，莫扎特的姐姐','Nannerl, la soeur de Mozart','A re-imagined account of the early life of Maria Anna \'Nannerl\' Mozart, five years older than Wolfgang and a musical prodigy in her own right.',NULL,0,0,0.774442,6.2,13,120,'2010-06-09','fr','/zLfi1AmYF3i6qn0J02Kcdaf0Nba.jpg',2.4090750722460466,3,'2026-09-10',2,NULL,NULL),(62177,'勇敢传说','Brave','Brave is set in the mystical Scottish Highlands, where Mérida is the princess of a kingdom ruled by King Fergus and Queen Elinor. An unruly daughter and an accomplished archer, Mérida one day defies a sacred custom of the land and inadvertently brings turmoil to the kingdom. In an attempt to set things right, Mérida seeks out an eccentric old Wise Woman and is granted an ill-fated wish. Also figuring into Mérida’s quest — and serving as comic relief — are the kingdom’s three lords: the enormous Lord MacGuffin, the surly Lord Macintosh, and the disagreeable Lord Dingwall.','Change your fate.',185000000,538983207,125.114374,6.7,4641,93,'2012-06-21','en','/1XAuDtMWpL0sYSFK0R6EZate2Ux.jpg',4.10523229554761,3,'2026-09-10',2,NULL,NULL),(62204,'火之战','La Guerre du feu','本片获奥斯卡最佳化妆奖、法国凯撒奖最佳影片及最佳导演奖。  　　围绕着寻求火种，电影极其科学而又生动地再现了旧石器时代人类的生活侧面。一个旧石器时代的部落在被其他部落的偷袭残杀和狼群的追逐噬啮之余，流落到了一片沼泽地。惊魂未定，饥寒交加，死的死，伤的伤，部落里专人看守的火种又在这紧要关口无情地熄灭了。一夜之间，部落从穴居安处篝火围坐的殷实的经济生活跌落成流离失所露宿荒野，在寒夜中瑟瑟颤抖。没有了火，既便没有敌人野兽追杀，部落也不会在冻馁伤病中生存多久。部落一老者作出了具有深远历史意义的决策，老者指定了三个勇猛之士出去寻找火种........',NULL,12000000,55260558,6.537986,7.1,109,100,'1981-12-15','xx','/gWinejy6s33cxENfcnpio2zKsSG.jpg',2.907968481183292,3,'2026-09-10',2,NULL,NULL),(62206,'惊魂半小时','30 Minutes or Less','尼克（艾森柏格 饰）是一个小镇上的披萨送餐员，他一直都过着平凡的生活。一天，他的平凡生活却和两个有计划犯罪的罪犯（丹尼·麦克布耐德和尼克·斯旺森 饰）碰撞到一起，疯狂的两个罪犯绑架尼克去抢劫银行。在短短的不到一小时时间内，抢银行或者脱险都是无法完成的任务，而尼克便找到他以前的好朋友、历史老师查特（阿兹·安萨里 饰）帮忙。就在这短短的半个小时里，尼克在查特的帮助下，完成了不可能完成的任务。时间滴答滴答的在流走，这两个罪犯必须同警察、雇佣的刺客还有别人手中拿着的喷火器，甚至是他们两人自己出现的分歧做斗争。在紧张的半小时内，他们要处理被迫抢银行、警察、杀手、重型武器的危险，同时还要面对彼此之间友谊的考验……','A lot can happen in 30 minutes.',28000000,40547440,25.039383,5.6,531,83,'2011-08-11','en','/12VgS5G6OG7ANKrSbhtUD2POHb8.jpg',3.1890954767167403,3,'2026-09-10',2,NULL,NULL),(62211,'怪兽大学','Monsters University','A look at the relationship between Mike and Sulley during their days at Monsters University — when they weren\'t necessarily the best of friends.','School never looked this scary.',200000000,743559607,89.186492,7,3528,104,'2013-06-20','en','/y7thwJ7z5Bplv6vwl6RI0yteaDD.jpg',4.031985790229692,3,'2026-09-10',2,NULL,NULL),(62213,'黑暗阴影','Dark Shadows','1760年的利物浦码头，科林斯夫妇正带着年幼的巴纳巴斯登上开往新大陆的船，前去扩张科林斯家族帝国。16年后，巴纳巴斯（约翰尼·德普 Johnny Depp 饰）长大成人，继承了家族产业，坐拥科林伍德庄园。女巫安琪莉可（伊娃·格林 Eva Green 饰）投怀送抱，而巴纳巴斯却心系善良姑娘乔赛特（贝拉·希思科特 Bella Heathcote 饰），无情地拒绝了女巫。女巫恼羞成怒，对两人施行毒咒，乔赛特香消玉损，而巴纳巴斯则变成了一只永远的吸血鬼被封在棺中。两个世纪后，一个施工队无意间挖开了棺木，巴纳巴斯回到庄园准备东山再起时，却发现曾经属于自己的科林斯港已经变成了女巫的天使海湾，良民们被她统治长达200年之久，地位难以撼动。身为吸血鬼的巴纳巴斯能否夺回家族产业，击碎女巫的谎言呢？与此同时，一位长相酷似昔日爱人乔赛特的年轻女孩也鬼使神差地来到了科林斯港……本片改编自20世纪60年代于ABC电视台播出的一档肥皂剧，讲述了吸血鬼巴纳巴斯·科林斯与狼人、女巫、僵尸等非人类生物在各个时空间的冒险经历。','Every Family Has Its Demons',150000000,245527149,50.306728,5.7,2320,113,'2012-05-08','en','/krwfLnyqr37l3vA9m1BkvJKXN4F.jpg',3.5373261598002568,3,'2026-09-10',2,NULL,NULL),(62214,'科学怪狗','Frankenweenie','小男孩维克多的爱狗Sparky被车撞死后，他十分伤心。在学校上课的时候，当老师做用电击青蛙的方法使其神经抽搐的实验时，他有了救活他的小狗的灵感。于是晚上，他引了天上的雷电电击小狗的尸体，使它复活。重生的小狗吓坏了男孩家的邻居们，他们视这只狗为怪物。邻居们追赶狗时将狗和男孩逼进一间小木屋，失手几乎烧死他们。但小狗却将男孩救出，自己死去。邻居和男孩的父母为之感动，决心再次救活它。他们用汽车发动机制造电能，又一次救活了这只狗……','The electrifying dog is back from beyond the grave',39000000,35287788,27.908783,6.6,932,87,'2012-10-04','en','/4zYfUSa8Fgl6bJw4Fqoqh4GMSUs.jpg',3.4645443444592208,3,'2026-09-10',2,NULL,NULL),(62215,'忧郁症','Melancholia','在这部关于世界末日的唯美影片中，贾斯汀和迈克尔在姐姐克莱尔与姐夫约翰的庄园里举办了一场盛大的婚宴。尽管克莱尔竭尽全力，这场婚礼仍以失败告终——至亲好友汇聚一堂，家族矛盾激化，人际关系渐趋崩坏。与此同时，一颗名为“忧郁症”的星球正朝着地球正面撞来。','Enjoy it while it lasts',7400000,21817298,36.173598,7,885,136,'2011-05-26','da','/wkzJxtnBDShi9971UwNugQWEAoR.jpg',3.536152741415252,3,'2026-09-10',2,NULL,NULL),(62255,'狂野追踪','Tracker','英布战争中的幸存游击队员Arjan（雷·温斯顿饰）在英属殖民地新西兰安了家，为了巨额悬赏，他奉命捉拿Kerama，一个被指控杀害英国士兵的毛利船员。对于精通追踪术的Arjan来说，这本是一件再容易不过的事，然而Kereama被抓后一再逃跑让这个猫鼠游戏变得紧张刺激，险象环生。Kereama坚持下去的唯一动力是他是无辜的。在不停的追逐中，两人互不相让、各占上风，他们也开始互相了解和尊重。决战的危急时刻却令他们发现，除了讨厌英国佬之外，他们还有很多共同之处。面对由Carlyle率领的英国军队，他们的命运会是如何？',NULL,6500000,0,2.074295,6,16,102,'2010-05-20','en','/lPPLs4SFP4Pk3SCJbQfhp9vtbL8.jpg',2.453018861078546,3,'2026-09-10',2,NULL,NULL),(62402,'Guiana 1838','Guiana 1838','The abolition of slavery in the British Caribbean in 1834 prompts Gillanders, Arbuthnot &amp; Company in Calcutta, a part of the East India Company, to recruit Coolies from India to fill the resulting labor void. The company hires Sinha, a fierce small-timer to sell dreams of El Dorado to the unsuspecting, impoverished Coolies who are signed to five-year contracts as indentured servants. Upon the Coolies\' arrival in British Guiana in 1838, the British planters promptly enslave them to ensure that the growth of sugar in the British West Indies will continue uninterrupted. John Scoble of the British and Foreign Anti Slavery Society arrives on the colony a year later to discover a new form of slavery; this time on the backs of Indians.',NULL,0,0,0.030253,2.8,3,120,'2004-09-24','en','/d6YNDQZQRM1io2Etq5I1T8YObsc.jpg',2.1308054342884395,3,'2026-09-10',2,NULL,NULL),(62630,'魔鬼的替身','The Devil\'s Double','征集令从萨达姆·侯赛因的宫殿里传到前线的部队中。伊拉克的本土军官，拉提夫·亚希艾被召集到了萨达姆的家族中，他被要求直接为这个国家的最高独裁者效力。把他召集到这里并不是让他来做什么保镖，而是要他“变身”成为萨达姆的长子乌代·侯赛因的替身。乌代·侯赛因是臭名昭著的黑暗王子，他做事恶毒、心狠手辣，热衷于奢侈品、跑车，热衷于派对，而且最要命的是他还很热衷于美女。 　　为了能避免给自己招惹来更大的麻烦，亚希艾只能去学着做乌代的替身，学习他的说话、走路、吃饭——只不过，这些外在的东西学起来都很简单，亚希艾永远也学不到乌代的行事风格，他对那些容易得来的美女、跑车、毒品以及暴力一点都没有兴趣。但这容不得亚希艾的讨价还价，他被赶鸭子上架似的做成了乌代。 　　在这个处处布满陷阱的地方，亚希艾只有小心翼翼地做着乌代。时间一长，他和乌代那诱人而性感的女仆人萨拉巴接下了不错的友谊。与此同时，他也发现萨拉巴并不是一个简简单单的女仆。 　　随着伊拉克和科威特的战事的临近，亚希艾觉得时候逃离这个可笑的国家和这种荒诞的生活了。可是，处处都是乌代的爪牙，他能这么简单地离开么？','The 80\'s were brilliant, if you were in charge.',19100000,5728213,10.559414,6.5,208,109,'2011-02-11','en','/sDnnV0QbfvXthf8K4cYod4HVlug.jpg',3.043789574939048,3,'2026-09-10',2,NULL,NULL),(62676,'丛林地狱','Limbo','Unconventional narrative about the interactions amongst a group of people in a small town in Alaska, each of whom has guards a secret.','The Only Thing More Dangerous Than Death... Is Survival.',8000000,1997807,0.034259,7,17,126,'1999-06-04','en','/1ytI3G3dT6j888ySOwYhpJHz8ED.jpg',2.4675681492429917,3,'2026-09-10',2,NULL,NULL),(62677,'民谣搜集者','Songcatcher','故事发生在1907年的美国，虽然彼时女性已经被允许进入大学教书，但她们的升职道路依然困难重重。莉莉（珍妮·麦克蒂尔 Janet McTeer 饰）是一名十分具有天赋的音乐理论家，虽然她在学术上非常的卓越，但依然一次又一次的失去升职的机会，这让她感到心灰意冷。于是，莉莉决定暂时离开学校，前往阿帕拉奇山区看望姐姐埃娜（简·亚当斯 Jane Adams 饰）。\r 很快，莉莉就发现，山区里流传的古老的苏格兰和爱尔兰民谣有着非常丰富的文化价值，如果能够将这些民谣带出大山，一定能够让自己重新得到业界的认可。于是，莉莉带着录音设备，开始了她民谣搜集的计划。','Fall under its spell..',0,0,3.363321,5.6,9,109,'2001-03-01','en','/qpUSLY5BPi42rqO097tNF8e53Qm.jpg',2.3395880287505904,3,'2026-09-10',2,NULL,NULL),(62728,'布赖顿硬糖','Brighton Rock','英国海滨小镇布赖顿，凯特斯和卡林奥里两大黑帮组织盘踞于此，互相角力，此消彼长。某夜，凯特斯被对头当街杀害，视老大如亲父的平基（Sam Riley 饰）目睹了凶案的全过程，于是想参与者之一的福瑞德（Sean Harris 饰）展开追杀。福瑞德虽死，却留下一堆的麻烦，他生前为了躲避跟踪曾某餐馆女侍应生罗丝（Andrea Riseborough 饰），并与之留下合影。为了销毁证据，平基开始接近这名单纯的女孩，而罗丝也渐渐爱上了帅气冷酷的平基。与此同时，凯特斯的死亡也让布赖顿的黑帮势力失衡，一方面卡林奥里迅速扩张，一方面本帮内部展开权力争夺，平基深陷其中无法自拔……  　　本片根据Graham Greene 的小说改编。','Love. Murder. Revenge.',0,0,3.122152,5.6,35,111,'2010-09-13','en','/7uq3onOHexPe4Xcj5bdRL7NKkIi.jpg',2.6120149841645315,3,'2026-09-10',2,NULL,NULL),(62764,'白雪公主之魔镜魔镜','Mirror Mirror','很久以前，有位相貌出众的公主名叫白雪（莉莉·柯林斯饰），白雪有位邪恶又毒舌的继母皇后（朱莉娅·罗伯茨饰）。皇后不仅嫉妒白雪公主的美貌，还成天肖想着帅气迷人的白马王子，并意图榨干他的财富与精力，却怎么也没想到白马王子竟然对白雪公主一见钟情；坏心的皇后见状立刻将白雪公主放逐到危机伺伏的幽暗森林，而白马王子也因中了坏皇后下的爱情魔药而沦为她的爱情俘虏。  　　被驱逐到森林里白雪公主不幸遇上了一帮矮人盗匪，却在盗匪们的训练下，成了七矮人山贼团的领袖！彻底改头换面的白雪公主，在偶然的机会下意外与白马王子重逢，但不甘心被坏皇后这般欺压的她，决定率领小不隆咚的手下们一同进攻邪恶皇后的堡垒，誓言夺权复仇！而白雪公主和坏皇后两人，究竟谁最后能永远过着幸福快乐的日子呢？','The Snow White legend comes alive.',85000000,183018522,48.126297,5.5,1114,106,'2012-03-15','en','/esENdlQ024yegaUz4z6blt1GH6e.jpg',3.35622827887926,3,'2026-09-10',2,NULL,NULL),(62835,'Colombiana','Colombiana','Zoe Saldana plays a young woman who, after witnessing her parents’ murder as a child in Bogota, grows up to be a stone-cold assassin. She works for her uncle as a hitman by day, but her personal time is spent engaging in vigilante murders that she hopes will lead her to her ultimate target: the mobster responsible for her parents\' death.','Revenge is beautiful.',40000000,60965854,33.785969,6.5,824,108,'2011-07-27','en','/op09XmBZ9eoH3On704rAw0st3Sg.jpg',3.430869222002117,3,'2026-09-10',2,NULL,NULL),(62837,'海豚的故事','Dolphin Tale','一只年幼的海豚在海洋里随意地嬉戏,却不幸地被捉螃蟹的陷阱抓了个正着,它的尾巴受到了严重的损坏。被当地人发现之后,这头雌性小海豚被送到了克利尔沃特海洋医院(Clearwater Marine Hospital)。在那里,人们给它起名叫做温特。不过,这个时候,它与命运的抗争才刚刚开始。 　　海豚这样的哺乳动物没有了尾巴就失去了在水中保持平衡和游泳的能力。倘若没有了游泳能力,它就没有办法来到水面上呼吸。这也就意味着温特要么一辈子都在半露出水面的状态下生活;要么就在水里窒息而死。为了不让这个生命活的没有尊严,同时也为了拯救这一条生命,一群海洋生物学家、兽医、假肢制作者们联合了起来,用自己的聪明才智为温特带来了一个奇迹--一个人工尾鳍。 　　这个人工尾鳍不仅帮助温特活了下去,更是让它成为了千万美国人的偶像,成为希望、勇气以及不屈不饶与命运相抗争的符号。','Inspired by the amazing true story of Winter.',37000000,95404397,6.63839,6.7,163,113,'2011-09-23','en','/af2SRFllNW26WFG84AfTv3xLT5t.jpg',2.9885894758396967,3,'2026-09-10',2,NULL,NULL),(62838,'新年前夜','New Year\'s Eve','《新年前夜》的故事和《情人节》一样，仍然延续浪漫路线，并且融合了多重人物线索。德尼罗饰演一名住在医院里的垂死的人；斯万克的角色则是时代广场新年前夜表演秀的制作人；库彻出演的角色则非常痛恨新年前夜；邦·乔维将本色出演一名摇滚明星，在一次派对上偶遇被自己甩掉的前女友；塞斯·梅耶斯则将饰演一名失败的父亲，为了拿到25000 美元的的奖金，极力让怀孕的妻子 生下新年全美国第一个宝宝，却发现自己面临着来自众多家庭的超乎想象的激烈竞争。艾斯·库珀饰演一位纽约警察，在时代广场新年前夜表演秀周围巡逻，而瑞安·西克莱斯特则是本色演出，饰演表演秀的主持人。','The one night anything is possible.',56000000,142044638,21.219292,5.7,718,118,'2011-12-08','en','/tGO4eIrCHjMiu0kKff2c8uBMYlz.jpg',3.2491709809393137,3,'2026-09-10',2,NULL,NULL),(63006,'来吧！吐个烟圈','दम मारो दम','来吧!吐个烟圈 碧帕莎芭素 让人眼前一亮的印度悬疑犯罪佳作','Goa. Paradise on Earth. But every Paradise has a few snakes.',0,0,0.075817,5.4,7,130,'2011-04-22','hi',NULL,2.28346572853687,3,'2026-09-10',2,NULL,NULL),(63020,'旧爱新欢一家亲','The Perez Family','2001年的威尼斯电影节上，印度女导演米拉．奈尔（Mira Nair）开始为世界影坛关注，她的《季风婚宴》获得了金狮大奖。米拉．奈尔早年以《早安孟买》成名，并拍摄了我们熟悉的《爱经》等作品。《旧爱新欢一家亲》（The Perez Family）是她1995年一部通过古巴流亡移民的题材，描写自由、家庭与爱情的影片。男主人公浩安．帕莱兹从古巴来到美国，想在\"自由国土\"上找到自己原有的家庭。但为了对付移民局的检查，他又不得不\"组成\"另一个\"临时家庭\"，先是风骚、热情的女郎杜蒂做妻子，又找来也姓帕莱兹的疯癫老人做父亲，以及\"失散多年\"的\"儿子\"。影像中仿佛透出奈尔柔软的目光，故事在温暖的情调中结束……','On the way to finding a family, she found love.',11000000,2832826,1.187671,6.6,9,113,'1995-05-12','en','/jxi3UDHf86kDk5hqJxnpEMzVch2.jpg',2.3382797786158447,3,'2026-09-10',2,NULL,NULL),(63287,'扑克房','The Poker House','由导演Lori Petty自己个人的童年故事改编。  　　故事背景设定在上世纪70年代中期爱荷华州的一个小镇上，Agnes（Jennifer Lawrence饰）是一个14岁的女孩，有两个妹妹，Bee和 Cammie (Sophie Bairley 和Chloe Grace Moretz饰)，还有一个成天沉浸在酒精和可卡因里的瘾君子母亲。她生活在扑克房里，在扑克房里，当地的黑人成天进行着赌博、吸毒、卖淫、酗酒一类的活动，而Duvall（Bokeem Woodbine饰）是这个扑克房里所有非法活动的组织者。但即使是在这种环境下，Agnes还是健康地成长着， 她是学校篮球队的主力，热爱诗歌，还承担起了保护两个小妹妹不受混乱不堪的家庭环境侵犯的责任。Agnes一直幻想着皮条客Duval是深爱着她的，直到有一天Duval强奸了她。Agnes的幻想彻底破损，但也因此...','Lust, drugs and violence... no place for a kid.',0,0,2.948576,6.1,47,93,'2008-06-20','en','/yTaqEbszsqhunQIjIMkkfwNMiiv.jpg',2.680908875765913,3,'2026-09-10',2,NULL,NULL),(63492,'床伴逐个数','What\'s Your Number?','人缘极好的单身女郎艾莉（安娜·法瑞丝 Anna Faris 饰）忽然在杂志上读到 “女人只要睡超过20个男人，一辈子就可能单身”，这论点让她心惊，当下决定要回头寻找过去的“床友”。邻居柯林(克里斯·埃文斯 Chris Evans 饰)，他为逃避女人的情债而借躲进艾莉家，两人不打不相识，于是达成协议，只要柯林帮艾莉从”床友”们中找到理想的另一半，她就要无条件提供避风港让他躲女人！柯林像秘书般开始寻索并安排艾莉的行程，让艾莉和”回头草”们一一约会，而他也顺利在一夜情之后次次落跑成功。 就在艾莉还幻想这些前男友可能有长高变帅或功成名就的同时，她和柯林的盟友关系也开始有了变化……\r 　　电影改编自小说《黛丽拉和她的20个前男友》。','Ally\'s looking for the best ex of her life.',20000000,30426096,19.220789,6.2,671,106,'2011-09-30','en','/hF0E1ZYTuJnNvUSrCEJ1d11Kl78.jpg',3.303941929166058,3,'2026-09-10',2,NULL,NULL),(63574,'快乐的噪音','Joyful Noise','故事发生在位于佐治亚州的帕萨豪小镇，当地教堂的唱诗班即将去参加一个名为“快乐噪音”的全国性比赛，可是，就在这个节骨眼上，唱诗班的总指挥却猝死了，失去了指挥的领导，整个唱诗班都走到了濒临崩溃的边缘。教会指派名叫罗斯（奎恩·拉提法 Queen Latifah 饰）女子成为了唱诗班的新指挥，罗斯是一个非常古板的人，希望所有的事情都能按照常规发生，而总指挥的遗孀斯派洛（多莉·帕顿 Dolly Parton 饰）却并不这么认为，她觉得唱诗班应该由她接手，并且应该尝试新的风格。','Dream a whole lot louder',0,0,5.753705,6.7,33,117,'2012-01-13','en','/pIgrIGFMZ7CslGPCWI7JHV3R96H.jpg',2.6203016188659527,3,'2026-09-10',2,NULL,NULL),(64328,'布偶大电影','The Muppets','布偶家族的布偶秀在前几年就停演了。后来，德州富商在布偶剧院的地下发现了石油，他计划要毁掉这个剧院，把石油给挖出来。不过他的邪恶计划却被沃尔特获悉了，于是沃尔特便联合起自己的弟弟加里和弟弟的女朋友玛丽一起，希望能够找回布偶家族的成员，在电视、广播和网络里继续演出，好筹集到1000万美元去拯救布偶剧院。为了达到这个目的，这三个人必须帮助科米蛙找回自己当年的朋友——那些布偶家族的布偶们。这些布偶的境遇都不相同：福滋熊在一家赌场的乐队里演出，这个乐队叫做Moopets（这是对布偶的英文Muppets的改写）；猪小姐成为了时尚界的风云人物；伟大的冈佐成为了贩卖下水管道的高手……面对着财大气粗的德州富商，这群布偶有机会拯救自己的剧院么？在帮助布偶挽救剧院的同时，玛丽和加里的爱情，加里和哥哥沃尔特的关系也面临着考验。','They\'re closer than you think.',45000000,165184237,17.047276,6.5,501,103,'2011-11-22','en','/cPHo60ziFB3hiW8d7RKx1ksA4M7.jpg',3.270432928045128,3,'2026-09-10',2,NULL,NULL),(64499,'Quinceañera','Quinceañera','马格德雷娜（艾米莉·里奥斯 Emily Rios 饰）即将迎来她的十五岁生日，对于即将到来的成人仪式，马格德雷娜充满了期待和幻想，起码在那一天，她能够成为自己小小宇宙的中心，享受众星捧月的虚荣。','Life\'s no walk in the park',0,0,0.034135,7,7,90,'2006-06-05','it','/kJv276uU9K0Z9MRhz6F3BEEetEO.jpg',2.2879392719974248,3,'2026-09-10',2,NULL,NULL),(64559,'一切搞定','Rien ne va plus','贝蒂和维克多是一对骗子。有一天，贝蒂带来了莫里斯，跨国公司的财务...',NULL,0,0,0.627964,6.4,5,105,'1997-10-15','fr','/i5WXCF18gdbTFDSAhluD2WLdgpu.jpg',2.224880173453257,3,'2026-09-10',2,NULL,NULL),(64639,'稻草狗','Straw Dogs','美国数学教授大卫·萨姆纳带着英国妻子来到英国郊外定居。在这里，有个修屋工认为他为人软弱，设计将他骗出去打猎，并在这段时间内强暴了他的妻子。更要命的是，大卫·萨姆纳为了拯救一个低能儿，导致当地居民围攻他的住宅。大卫·萨姆纳在愤怒中展开了血腥报复。','Everyone Has A Breaking Point',25000000,10324441,7.473455,5.5,144,110,'2011-09-16','en','/hSW5Msz5Cr6vUQxChPSPdxufnss.jpg',2.90120281517848,3,'2026-09-10',2,NULL,NULL),(64678,'家庭作业','The Art of Getting By','乔治（弗莱迪·海默 Freddie Highmore 饰）是一个聪明的男孩，一直逃避学习的他总是在课堂上涂涂画画，因此从未完成任何一门功课，将要面临无法毕业的困境。而校花莎莉（艾玛·罗伯茨 Emma Roberts 饰）在极受欢迎的外表下掩藏着忧伤的内心世界。莎莉和乔治发现彼此有着许多相似的地方而成为朋友，并且互相产生了好感。可是，好景不长。临近毕业，乔治却还有一大堆的作业需要完成；他与莎莉的关系也因自己的“畏缩”而触礁。面对学业、爱情上的难题，乔治到底该如何解决...','The toughest lesson is love.',0,1406224,12.690224,6.5,415,83,'2011-06-17','en','/3ahdKyzHbYhvqJdtpsEWipEai98.jpg',3.2144963839710394,3,'2026-09-10',2,NULL,NULL),(64682,'了不起的盖茨比','The Great Gatsby','1922年的春天，作家尼克(托比•马奎尔 Tobey Maguire 饰)满怀希望离开家乡，随淘金热潮来到纽约这个新兴的城市，虽然这里爵士乐流行，股票飞涨，但是贫富两极分化，人们沉沦在纸醉金迷中。尼克为了追寻美国梦，放弃写作而进入证券市场，并搬入纽约附近的海湾居住，成为了神秘富豪盖茨比（莱昂纳多•迪卡普里奥 Leonardo DiCaprio 饰）的邻居。而海湾的对岸住着尼克的表妹黛西（凯瑞•穆里根 Carey Mulligan 饰）和她的贵族丈夫汤姆（乔尔•埃哲顿 Joel Edgerton 饰），尼克不仅被邀请去赴宴，之后汤姆还带着他去找情妇寻欢，尼克渐渐迷失在这个充满魅力，以及富豪编制的假象、爱与谎言的世界中。  但是只有盖茨比最特别，他是唯一让尼克感到在这个迷失城市里充满希望的人。尼克被邀请参加了盖茨比豪宅中的盛宴，还发现盖茨比心中的秘密，原来他一直深爱着黛西，即使她没等到他战后归来，转而嫁给富豪汤姆，盖茨比一直深信他们的爱情矢志不渝。尼克作为盖茨比与黛西爱情的见证者，终于在盖茨比被谋杀之后，看清了这个上流社会的虚情寡义，决心远离喧嚣、冷漠、虚假的大都市，黯然回到故乡……','Reserving judgments is a matter of infinite hope... I come to the admission that it has a limit.',105000000,351040419,61.196071,7.3,3769,143,'2013-05-10','en','/nimh1rrDDLhgpG8XAYoUZXHYwb6.jpg',4.060259435585892,3,'2026-09-10',2,NULL,NULL),(64685,'特别响，非常近','Extremely Loud & Incredibly Close','九岁男孩奥斯卡·史埃尔的父亲在911事故中丧生，在他幼小的内心中留下了阴影。无意间奥斯卡发现了一封写着“布莱克”的信封和一把钥匙。奥斯卡认为这是父亲给他留下的寻找线索，钥匙背后一定隐藏着什么 秘密。奥斯卡把这一秘密告诉了不会说话的老爷爷。此后的每个周末，奥斯卡开始在五个城区里寻找姓“布莱克”的人。父亲生前跟奥斯卡一起规划了寻找第六城区的“侦查探险”游戏，告诉奥斯卡：不要停止寻找。','This is not a story about September 11th, it\'s a story about every day after.',40000000,55247881,31.066874,6.9,708,129,'2011-12-24','en','/cZAXcwShibsKtHZWe4uxJOllmbV.jpg',3.4464973000341286,3,'2026-09-10',2,NULL,NULL),(64686,'47 Ronin','47 Ronin','Based on the original 1941 movie from Japan, and from ancient Japan’s most enduring tale, the epic 3D fantasy-adventure 47 Ronin is born.  Keanu Reeves leads the cast as Kai, an outcast who joins Oishi (Hiroyuki Sanada), the leader of the 47 outcast samurai.  Together they seek vengeance upon the treacherous overlord who killed their master and banished their kind.  To restore honor to their homeland, the warriors embark upon a quest that challenges them with a series of trials that would destroy ordinary warriors.','For courage. For loyalty. For honor.',175000000,150962475,41.796339,5.9,1326,119,'2013-12-06','en','/eIpmIiOqxjhpCPkz7CAvOOVnei4.jpg',3.4495215654059317,3,'2026-09-10',2,NULL,NULL),(64688,'龙虎少年队','21 Jump Street','施密特和延科已经长大了。他们希望能用工作来改变自己的现状，并把诸多青少年时代的问题一一抛诸脑后。他们加入了警方的一个特种组织：龙虎少年队，并凭借着自己年轻的外表，混迹到了当地的一间高中做了卧底。把自己的手枪和警徽换成了高中生用的书包之后，施密特和延科就来到了高中，重新做起了“学生”。他们来到学校，并不是要重新回炉念书，而是奉命调查一桩毒品走私案。危险，似乎离学校很远，但又时时刻刻地如影随形。现在的学校，已经和几年前的学校大相径庭了，施密特和延科已经不再适应这里的生活。更悲催的是，他们似乎还要面对那些他们本以为已经甩到身后的“青少年问题”。','They thought the streets were mean. Then they went back to high school.',42000000,201585328,62.714026,6.7,4074,109,'2012-03-12','en','/8v3Sqv9UcIUC4ebmpKWROqPBINZ.jpg',3.9315863781887024,3,'2026-09-10',2,NULL,NULL),(64689,'温柔杀戮','Killing Them Softly','布拉德·皮特饰演的杰基·柯根是一位强硬的职业执法人，他介入调查一桩抢劫案，案件发生在一次由黑帮保护的重金扑克赌局中。','In America you\'re on your own.',15000000,37930465,24.612603,5.8,742,97,'2012-09-20','en','/iOlKg2GB51MltY6ONja0UQj4DV5.jpg',3.2781729005372964,3,'2026-09-10',2,NULL,NULL),(64690,'亡命驾驶','Drive','黑夜里，他协助黑帮分子抢劫，是运送车手。白天，他在好友香农的车行从事电影飞车特技工作。在一次逛超市时，他邂逅了艾琳母子， 双方互有好感，并度过愉快的周末。不过，艾琳的老公斯坦德出狱了，这让他们的感情被拦腰斩断，尽管双方心有灵犀，却只剩无奈。香农把他推荐给黑帮大佬伯尼和尼诺。与此同时，他无意中发现斯坦德被人痛扁，原来后者在狱中欠了保护费。为了偿还高利贷并保证母子平安，斯坦德决定再次铤而走险。他为了艾琳决定帮斯坦德完成这一票。然而，在打劫银行的过程中，斯坦德被店主意外击毙，而他和女同伙布兰奇陷入了黑吃黑的迷局……','There are no clean getaways.',15000000,78054825,49.294864,7.4,3725,100,'2011-08-06','en','/602vevIURmpDfzbnv5Ubi6wIkQm.jpg',4.055048474022313,3,'2026-09-10',2,NULL,NULL),(64720,'存身','Take Shelter','柯蒂斯·拉弗奇与妻子萨曼莎及六岁失聪女儿汉娜生活在俄亥俄州小镇。当他开始被骇人梦境困扰时，选择独自承受这些幻象，并将焦虑转化为在后院执迷于修建风暴避难所的行为。他看似难以解释的举动令亲友忧虑不解，但婚姻因此产生的裂痕与社区内的紧张氛围，更无法与他内心深处对梦境预兆的恐惧相提并论。[索尼影业经典]',NULL,5000000,3099314,19.807295,7.1,471,120,'2011-11-25','en','/dmvhXcmfYmftUWvrxI88hSUCJ9X.jpg',3.332317773654311,3,'2026-09-10',2,NULL,NULL),(64807,'旗鼓相当','Grudge Match','取材于运动题材的喜剧故事，讲述了两个退役的拳击手重返拳台，发起一场宿命的拳战，以了结他们之间多年的积怨。','DeNiro vs Stallone',40000000,44907260,21.362949,6,433,113,'2013-12-25','en','/wMD46eZOaw8P2XRhKIemE95sciK.jpg',3.188729810671687,3,'2026-09-10',2,NULL,NULL),(64973,'Peace, Propaganda & the Promised Land','Peace, Propaganda & the Promised Land','This video shows how the foreign policy interests of American political elites-working in combination with Israeli public relations stratgies-influence US news reporting about the Middle East conflict. Combining American and British TV news clips with observations of analysts, journalists and political activists, Peace, Propaganda &amp; the Promised Land provides a brief historical overview, a striking media comparison, and an examination of factors that have distorted U.S. media coverage and, in turn, American public opinion.',NULL,0,0,0.020168,6.4,4,80,'2005-01-28','en','/AsJA9DQFxCP9jpuNsqC17ZcaUqN.jpg',2.18378431283694,3,'2026-09-10',2,NULL,NULL),(65055,'鲨鱼惊魂夜','Shark Night 3D','七位年轻人前往路易斯安那湖边游玩,本来是令人期待的完美假期,却因为突然出现的饥渴鲨鱼,让全部的人身陷恐惧……血染湖面隐藏的又是什么样的真相?  影片承袭了《食人鱼3D》的作风：《大白鲨》+美女胸部+3D效果，并展示狂欢的美国青少年们被鲨鱼弄得痛哭流涕、精神崩溃的场景','Terror runs deep.',28000000,10126458,8.363702,4.9,132,91,'2011-09-02','en','/gQ1TJBCtenoLMSFVnZYdmuzgvFk.jpg',2.85900410958102,3,'2026-09-10',2,NULL,NULL),(65057,'后裔','The Descendants','马特·金是一个对家庭漠不关心的丈夫和两个女儿的父亲，当妻子在威基基附近遭遇划船事故后，他被迫重新审视自己的过去并直面未来。这场变故让他与年幼的女儿们重新走近，同时马特也在为是否出售家族继承自夏威夷原住民贵族与传教士的土地而艰难抉择。[福克斯探照灯影业]','The South Pacific ain\'t that terrific.',20000000,177243185,40.903931,6.7,934,115,'2011-09-09','en','/kTZbC9hLFwbyEgC1byyMmL9XbhH.jpg',3.511624815375174,3,'2026-09-10',2,NULL,NULL),(65086,'The Woman in Black','The Woman in Black','The story follows a young lawyer, Arthur Kipps, who is ordered to travel to a remote village and sort out a recently deceased client’s papers. As he works alone in the client’s isolated house, Kipps begins to uncover tragic secrets, his unease growing when he glimpses a mysterious woman dressed only in black. Receiving only silence from the locals, Kipps is forced to uncover the true identity of the Woman in Black on his own, leading to a desperate race against time when he discovers her true identity.','What did they see?',17000000,127730736,43.675191,6.1,1206,95,'2012-02-01','en','/5x6jXWAbGDdJcb7TUdP0oehwrOw.jpg',3.472040663329232,3,'2026-09-10',2,NULL,NULL),(65203,'百老汇旋律','The Broadway Melody','汉克（贝茜·洛芙 Bessie Love 饰）和奎妮（安妮塔·佩姬 Anita Page 饰）是情同手足的好姐妹，两人相约来到车水马龙的繁华大都市纽约，在汉克的老相好艾迪（查尔斯·金 Charles King 饰）的帮助之下，两人进入了歌舞团成为了歌舞女郎，很快就声名鹊起。\r 虽然汉克和艾迪已经相恋多年，但艾迪发现自己竟然情不自禁的被奎妮深深的吸引，与此同时，娇俏可人的奎妮赢得了大富豪贾科（肯尼思·汤姆森 Kenneth Thomson 饰）的青睐，后者对她展开了非常热烈的攻势。汉克看出贾科是一个心术不正的纨绔子弟，屡屡劝说奎妮离他远一点，但奎妮早已经陷入了贾科为她编织的美梦之中。','The pulsating drama of Broadway\'s bared heart speaks and sings with a voice to stir your soul!',379000,4358000,0.968865,5,19,100,'1929-02-08','en','/giq8GJs8YGMzHxeKxNSuwzAdd1c.jpg',2.4780255704145726,3,'2026-09-10',2,NULL,NULL),(65448,'黑狱拳王','Penitentiary','A hitchhiker named Martel Gordone gets in a fight with two bikers over a prostitute, and one of the bikers is killed. Gordone is arrested and sent to prison, where he joins the prison\'s boxing team in an effort to secure an early parole and to establish his dominance over the prison\'s toughest gang.','There\'s only one way out, and 100 fools stand in the way!',0,0,0.001117,4.9,8,99,'1979-12-01','en','/1XQOTbjwaFSSEdoJlhTcwRsJxG.jpg',2.30695434597431,3,'2026-09-10',2,NULL,NULL),(65749,'探戈狂恋','Tango, no me dejes nunca','马里奥的前妻离开了他，他的深情和挽留似乎已经没有什么用了，与此同时作为导演的他正在排演一场关于探戈的音乐剧，虽然情绪低落外加脚伤，马里奥依然专注于工作。有黑道背景的安杰罗来找马里奥，他希望投资这部作品，为的是让自己热爱舞蹈的情人伊莲娜演上主角。安杰罗是个可怕的人物，马里奥只能同意他的要求，没有想到的是，在充满情欲性感热情的探戈排演中，马里奥与伊莲娜之间爱意丛生。不知是否是安杰罗的安排，在排演的众多演员中，也似乎出现了一位类似杀手的危险人物，马里奥和伊莲娜陷入了爱情游戏的危机中。','Tango: do not ever leave me',0,0,0.425551,6.8,6,115,'1998-02-12','es','/cMCiEzgHx7TKdgxEZwzl1mxqotw.jpg',2.2589881623017503,3,'2026-09-10',2,NULL,NULL),(65754,'龙纹身的女孩','The Girl with the Dragon Tattoo','《千禧年》杂志的财经记者米克尔·布隆克维斯特（丹尼尔·克雷格 Daniel Craig 饰）正被一桩报导引起的诽谤诉讼案搞得焦头烂额之际，却意外接到了瑞典顶尖家族企业范耶尔工业集团的创始人亨利·范耶尔（克里斯托弗·普卢默 Christopher Plummer 饰）的邀请。表面上米克尔要为对方写传记，实则是帮迪奇调查一桩40年前发生在家族里的悬而未决的杀人案。米克尔认真梳理堆积如山的资料，与家族成员交流攀谈。却在关键时刻，被一个边缘女孩莉丝贝丝·沙兰德（鲁妮·玛拉 Rooney Mara 饰）入侵电脑盗取了资料。他找到同要具有非凡调查能力的莉丝，邀请她一同调查，却发现面前是一个深不见底的欲望黑洞……','Evil shall with evil be expelled.',90000000,232617430,47.651083,7.2,2434,158,'2011-12-14','en','/8bokS83zGdhaXgN9tjidUKmAftW.jpg',3.8869533635876765,3,'2026-09-10',2,NULL,NULL),(65759,'快乐的大脚2','Happy Feet Two','会跳舞的企鹅又回来了，而且还增加了一只会飞的企鹅！除了我们熟知的冰天雪地的场景、动感十足的音乐，这部续集还采用3D上映。在这一集中增加不少新的角色，更重要的是企鹅马布尔（Mumble）和葛洛丽娅（Gloria）有了一个儿子。小儿子Erik在企鹅的王国里希望能够寻找到属于自己的特殊天分。而此时此刻又有新的危机威胁着这个国度……','Every step counts.',130000000,150406466,17.7735,5.8,373,100,'2011-11-17','en','/2rnLZgphfKFkJV3ja2yllF172Z1.jpg',3.1290569018285614,3,'2026-09-10',2,NULL,NULL),(66025,'Mooz-lum','Mooz-lum','Thanks to a strict Muslim upbringing that largely shielded him from the outside world, Tariq\'s first year of college proves transformative. That is, until the 9/11 terrorist attacks invite growing suspicion and distrust from his angry classmates.',NULL,0,330048,0.414754,4.5,3,95,'2011-02-11','en','/adSb3QS8wW234v7HVhbFWABhgy7.jpg',2.133775501946463,3,'2026-09-10',2,NULL,NULL),(66125,'红犬历险记','Red Dog','在澳大利亚西北部的一个铁矿上，有一只小狗是所有矿工的宠物，它没有主人，每天混迹在矿工之中。矿工们也很喜爱这只狗，给它取名叫做小红（Red）。但是随着一个美国青年的到来，这一切都改变了。 　　这个美国人叫做约翰·格兰特，在一次铤身而出救出小红之后，小红就把它当做了自己的主人。约翰在矿上爱上了一个秘书，两个人喜结连理。但就是在订婚之后的第二天的早上，约翰在上班的路上撞死了一只袋鼠，自己骑的摩托车翻车，他自己当场丧命。从那以后，小红就走遍了澳大利亚，甚至搭乘轮渡东至日本，去寻找自己的主人。遍寻无果之后，它回到了铁矿上。 　　小红误食了毒药，气数将尽。在临死前，它跑到了自己主人的坟墓前，和主人死在了一起……','He\'s Been Everywhere Mate.',0,0,5.499412,7.1,83,92,'2011-08-04','en','/cbLh0tVqjqcDnob7w79XkIQ7gGI.jpg',2.8387834244400914,3,'2026-09-10',2,NULL,NULL),(66195,'完美的主人','The Perfect Host','克莱恩·克劳福德饰演的约翰是个抢劫犯，在犯罪之后他企图躲到大卫·海德·皮尔斯饰演的沃威克的家中。不过，他没想到的是，沃威克并不像他开起来的那么正常。在他这个“完美主人”的款待下，一切都将走入疯狂。','Dinner Parties Are A Dying Art.',0,14870,6.507094,6.2,135,93,'2010-07-01','en','/tYqk1u5d3eARg5gV8cF4RZFZKKQ.jpg',2.919514527527337,3,'2026-09-10',2,NULL,NULL),(66468,'疑路囚牢','N-Secure','N-Secure is a no holds-barred thrilling drama mixed with murder, mayhem and manipulation among affluent professionals. This film sheds light on a man\'s downfall from the pinnacles of success into the depths of his damaged character. His insecurities lead him into a series of troubled romantic relationships and eventually a web of events that include betrayal and murder.',NULL,0,2592808,0.13456,4.3,4,0,'2010-10-15','en','/eYbnGcx48fnujZkR7Wo0x4RzL12.jpg',2.1806050066148095,3,'2026-09-10',2,NULL,NULL),(66607,'Saving Private Perez','Salvando al Soldado Perez','La vida ha llevado a Julián Pérez por caminos equivocados, pero el destino le presentará a este hombre la oportunidad de encontrar su redención cuando es enviado a la misión más peligrosa y noble de toda su vida, una misión ordenada por la única autoridad que todavía respeta, su madre, Doña Elvira. Julián debe viajar hasta el otro extremo del mundo, a un lugar llamado Irak, a traer de vuelta vivo, a su hermano menor el soldado de infantería Juan Pérez. Con la promesa hecha, Julián Pérez regresa a su natal Sinaloa donde reclutará a un comando de elite, destinado a cumplir una misión suicida: viajar a Irak y salvar al soldado Pérez.',NULL,0,0,0.177356,6.1,18,105,'2011-03-18','en','/lH4IsN5hwg9rKdosyYdmeEPtViP.jpg',2.473473090434185,3,'2026-09-10',2,NULL,NULL),(66767,'Beat the World','Beat the World','Three dance crews – one Latin American, one European and one Canadian – prepare to battle at the International Beat the World competition in Detroit. Along the way, they struggle with gambling debt, bad break-ups and their own egos. In the final showdown to become world champions they find that their lifelong hopes, dreams and even lives, are at stake.','Feel the beat, live the dream.',10000000,0,2.873796,4.3,16,91,'2011-06-10','en','/nZCPl2Du2PRkky4Mzb4YiXk9C1Q.jpg',2.4438836775303696,3,'2026-09-10',2,NULL,NULL),(66942,'隐形的格里夫','Griff the Invisible','在外人眼中，格里夫（瑞恩·科万腾 Ryan Kwanten 饰）是个循规蹈矩的上班族，他的个性软弱怕事，生活简单划一，是个再平凡不过的普通人。然而，每当夜幕降临，格里夫这个他人眼中的普通人便会摇身一变，成为惩奸除恶的超级英雄，用自己微弱的力量维护着小镇上的和平。  　　“隐形”是格里夫梦寐以求的超能力，单纯的他对这一能力的存在深信不疑。格里夫的哥哥发现了弟弟一些不寻常的举动，他只当格里夫是个陷入幻想世界无法自拔的蠢蛋罢了，但这一切在格里夫的准嫂子梅勒迪（梅芙·德莫迪 Maeve Dermody 饰）的眼中却有了别样的意义，这个古灵精怪的姑娘不仅没有嘲笑格里夫，反而积极的帮助他寻找隐形的种种方法，日积月累间，两人擦出了感情的火花。','He\'s a dreamer, stuck in the real world.',2902660,0,1.35088,6.1,34,93,'2011-08-19','en','/12DpWfDhBacOE09wJgR75rwCVUH.jpg',2.608733410663454,3,'2026-09-10',2,NULL,NULL),(67238,'Cavite','Cavite','Adam, a security guard, travels from California to the Philippines, his native land, for his father\'s funeral. He arrives in Manila. As he waits, a phone rings in his backpack; he answers it, and a male voice tells him that his mother and sister are captives and will be killed if Adam doesn\'t cooperate. Over the next hour, the voice sends Adam by bus, taxi, motorized tricycle, and on foot through an urban landscape of busy streets, cramped apartments, a fetid squatters\' camp, a bank, a cockfighting arena, and a church. Adam\'s conversations with the voice cover murder, Islam, jihad, rebellion in Mindanao, and his family. What is it Adam will be commanded to do?',NULL,0,0,0.022173,7.5,2,80,'2005-03-12','en','/s3pDLyGpJ4ZGvY7fL6ie5bV7Ge7.jpg',2.0735333105184903,3,'2026-09-10',2,NULL,NULL),(67373,'This Thing of Ours','This Thing of Ours','Using the Internet and global satellites, a group of gangsters pull off the biggest bank heist in the Mafia\'s history.',NULL,0,0,0.046868,5,1,100,'2005-01-01','en','/rS7neBxeRMBeN8095SZnUZTrtQN.jpg',1.9839468456812521,3,'2026-09-10',2,NULL,NULL),(67660,'Think Like a Man','Think Like a Man','The balance of power in four couples’ relationships is upset when the women start using the advice in Steve Harvey’s book, Act Like A Lady, Think Like A Man, to get more of what they want from their men. When the men realize that the women have gotten a hold of their relationship “playbook,” they decide that the best defense is a good offense and come up with a plan to use this information to their advantage.','Let the mind games begin.',12000000,96070507,6.035152,6.9,281,122,'2012-04-16','en','/kfIrKVPDzXJDBzPnFEuoatlaZPW.jpg',3.1384494503364317,3,'2026-09-10',2,NULL,NULL),(67675,'欢乐合唱团：演唱会3D电影版','Glee: The Concert Movie','丽亚·米雪儿、克里斯·柯尔弗和柯瑞·蒙特斯也许在Glee中停留的时间不会太长了，但Fox绝对把他们还在的时间利用得相当充分。如果你还没有看过Glee的任何一场演唱会，或者你想全方位立体式观瞧小哈里·沙姆的腹肌，那么Glee今夏的3D电影已经为你做好了充足准备。\r 　　Glee的3D电影——《欢乐合唱团：演唱会3D电影版》（Glee: The 3D Concert Movie）即将在8月12日的时候全面来袭各大剧场，它将带领粉丝们进入这部热剧的第二次全国巡演的幕后台前。Gleeks不仅可以看到他们表演像\"Don\'t Stop Believing\"这样的热门歌曲，还可以知晓“新航向”成员们的各种八卦和趣事。你知道娜亚·里维拉已经被求过两次婚了吗？你知道小哈里·沙姆的每块腹肌都代表了一个食品集团吗？可能从没人知道，但现在机会来了。今天这部电影的首发预告片能让我们率先一睹其真容。\r 　　Glee这部3D电影是在6月16日的新泽西州东拉瑟福德站演唱会上进行的拍摄，电影中包括最近巡演的曲目，还另外包括一些特别附加的歌曲，比如格温妮丝·帕特洛为此拍摄的那首\"Forget You\"。',NULL,9000000,18663238,9.933926,6.8,79,84,'2011-08-11','en','/y5NCu183zREb4XmHSB6QP3K7TH2.jpg',2.828195010486109,3,'2026-09-10',2,NULL,NULL),(67911,'大屌拉森：天生明星','Bucky Larson: Born to Be a Star','一个男人意外发现了自己的父母曾是70年代的色情片明星，于是也萌生了当“明星”的念头。但这个过程却不是他想象的那么容易。','There Are No Small Actors. Just Small Parts.',10000000,0,3.919057,4.4,51,97,'2011-09-09','en','/avCsg52549PHT5nVXIW7c3BEZ7b.jpg',2.6671179401194127,3,'2026-09-10',2,NULL,NULL),(67913,'国民警卫队','The Guard','格里·鲍伊尔警长是一个有着暴脾气的怪人,他没有什么幽默感,性格古怪。因为常年在戈尔韦郡工作,所以他对整个地区都了若指掌。他见过了太多的悲欢离合故事,所以他从来也就不曾考虑世界的意义。  　　当这个宁静的小镇成为一宗巨大的毒品交易案的关键地点后,鲍伊尔不得不和更不懂幽默的FBI探员温德尔合作进行调查。在自己的地界上工作,他根本没有把FBI放在眼里。温德尔是一个典型的美国人,恪守时间和规章,亦步亦趋地工作并且一心要将犯罪分子绳之以法。他根本不想去了解案犯与当地的背景,他想的只是破案。他看不起鲍伊尔,觉得他只是一个最基层的小警员。而鲍伊尔则觉得温德尔太书呆子气,什么都按照书本和教条来做,根本不了解真实的生活是如何运作的。  　　尽管看上去鲍伊尔不想帮助温德尔破案,可他还是给温德尔的工作带来了不少方便。鲍伊尔找到了于案件有关的很多蛛丝马迹,一点点把案情梳理开来。随后,怪事一桩一桩袭来,首先是鲍伊尔的搭档不见了,随后是他最喜欢的妓女要他对这个案子睁一只眼闭一只眼,最后毒贩子自己上门求情,希望鲍伊尔能放他一马——看上去,毒贩早已渗透到了警局内部,只有鲍伊尔还不知道而已。  　　怪脾气的鲍伊尔觉得事情蹊跷,他决定要依靠自己的双手把整个案件查个水落石出。现在,在戈尔韦郡的地界上,他唯一能信任的人只有他不喜欢的温德尔了。他们能摒弃前嫌,一起破案,找到幕后的黑手么?','The FBI are about to discover that things work a little differently around here.',6000000,19560274,19.411141,6.8,372,96,'2011-07-07','en','/dtQiStID0le2EMTmJXupPRybARB.jpg',3.233687440053751,3,'2026-09-10',2,NULL,NULL),(68179,'逃离地球','Escape from Planet Earth','在距离地球15光年的外太空，科技昌明的Baab星上生活着一群爱好和平的蓝色小人。其中斯科奇（布兰登·费舍 Brendan Fraser 配音）是该星球一个勇猛果敢、正义感十足的超级英雄，他经常驾驶超新星-9号飞船穿梭宇宙，在BASA总部他的兄弟盖里（罗伯·考德瑞 Rob Corddry 配音）的指挥下，一次次圆满完成营救受困外星人的任务。这一日，刚回家不久的斯科奇被BASA负责人莉娜（杰西卡·阿尔芭 Jessica Alba 配音）命令即刻前往黑暗星球——地球执行救援任务。担心兄弟的安危，盖里与执意前行的斯科奇发生争吵。在全Baab星人民的注视下，斯科奇成功抵达著名的51区，结果却被夏克尔将军（威廉·夏特纳 William Shatner 配音）为首的军方抓获。  　　为了救回最亲密的兄弟，一向谨小慎微的盖里不得不踏上凶险的征途，而这一切背后的阴谋也悄悄浮出水面……','Earth\'s greatest secrets are about to break out!',40000000,74597643,18.14218,5.7,332,89,'2013-02-14','en','/1h0IzTWxPgNSY7n6svKX4VJcwii.jpg',3.097690968662495,3,'2026-09-10',2,NULL,NULL),(68202,'无需男人的女人','Without Men','影片改编自詹姆斯·卡农的畅销小说《小镇上的寡妇们》（Tales From the Town of Widows），讲述了一群以艾娃·朗格利亚·帕克为首的生活在拉美小山村的女人，当男人们都去参加卫国战争的时候，她们只能靠自己支撑起整个的家，而当男人们从战场上返回后，女人们拒绝退居二线。这时一场关于“家庭权力”的战争开始打响了。',NULL,4,0,0.28076,4.6,8,83,'2011-06-29','en','/1EzXn6ZkhGBBlNizXQiGOeDvwwp.jpg',2.306615416450978,3,'2026-09-10',2,NULL,NULL),(68412,'3 Backyards','3 Backyards','The story of three people from the same suburban town during the course of one curious autumn day.',NULL,0,0,0.17817,4.8,4,88,'2010-01-01','en','/aBVKjA5A0JkKBKJfIMvhTSdRSn3.jpg',2.181523810927108,3,'2026-09-10',2,NULL,NULL),(68684,'致命禁闭','Detention','灰熊湖镇是一个地处偏远的宁静小镇，然而，一个变态杀手的出现打破了这里的平静。莱尼（珊妮·卡斯韦尔 Shanley Caswell 饰）是一个外表平庸作风古板的素食主义学生，个性别扭好强的她在学校里成为了大家排斥的对象。莱尼的好友艾恩（史宾塞·洛克 Spencer Locke 饰）是校内人气颇高的啦啦队队长，可惜的是，由于同时喜欢上了男生克莱普顿（乔什·哈切森 Josh Hutcherson 饰），两人的友情很快就以破裂告终。一个女生的死亡使得包括艾恩和克莱普顿在内的八人被罚留校察看，除非他们找出凶手，否则不能步出学校一步。然而，根据一名神秘学生的回顾，往届留校察看的学生们都会被变态杀手所杀，与此同时，他们发现世界在十分钟内就要毁灭。为了保命，莱尼驾驶着时光机，穿越到一切的源头1992年，在那里，她能够成为拯救世界的英雄吗？','Cancel Your Future',10000000,0,10.424596,5.7,129,93,'2011-03-16','en','/wLuMoe16Z27DH96B2vg4FQNiAjj.jpg',2.8959428880296776,3,'2026-09-10',2,NULL,NULL),(68718,'被解救的姜戈','Django Unchained','姜戈是一名奴隶，他与前主人间那段饱受虐待的过往，让他最终与德裔赏金猎人金·舒尔茨医生狭路相逢。舒尔茨正在追踪杀人如麻的布里特尔兄弟，而只有姜戈能带他找到这帮悬赏目标。行事不循常规的舒尔茨赎下了姜戈，并承诺抓住布里特尔兄弟后——无论死活——便给予他自由。','Life, liberty and the pursuit of vengeance.',100000000,425368238,82.121691,7.8,10099,165,'2012-12-25','en','/7oWY8VDWW7thTzWh3OKYRkWUlD5.jpg',4.495686298017094,3,'2026-09-10',2,NULL,NULL),(68721,'钢铁侠3','Iron Man 3','纽约大战之后，托尼·斯塔克一直受到严重焦虑和恐慌发作的困扰，只能疯狂投入钢铁战甲的研发来获得安全感，甚至因此忽略了佩珀·波茨。与此同时，自称“满大人”的神秘恐怖分子制造了一连串爆炸袭击，托尼的好友哈皮也在其中一次袭击中身受重伤。愤怒的托尼公开向对方发起挑战，却很快遭到猛烈报复，自己的住所和生活也被彻底摧毁。失去往日资源与依靠后，他不得不独自寻找袭击背后的真相，而线索逐渐指向多年前结识的科学家奥尔德里奇·基里安以及一种名为“绝境病毒”的危险技术……','Unleash the power behind the armor.',200000000,1215439994,77.68208,6.8,8806,130,'2013-04-18','en','/qhPtAc1TKbMPqNvcdXSOn9Bn7hZ.jpg',4.174100131872632,3,'2026-09-10',2,NULL,NULL),(68722,'大师','The Master','二战后，一位美国知识分子创立了一种宗教。当他遇到一名陷入困境的流浪者时，便邀请此人协助传播这一新信仰。随着信徒增多，流浪者开始质疑他曾接受的教义，以及那位曾给予他人生方向的导师。','Every Man Needs a Guide',32000000,28258060,25.682509,7,701,137,'2012-09-07','en','/4OUaqfpCFlmhwPjx3t1oJAdUTcD.jpg',3.4461693316276354,3,'2026-09-10',2,NULL,NULL),(68724,'Elysium','Elysium','In the year 2159, two classes of people exist: the very wealthy who live on a pristine man-made space station called Elysium, and the rest, who live on an overpopulated, ruined Earth. Secretary Rhodes (Jodie Foster), a hard line government ofﬁcial, will stop at nothing to enforce anti-immigration laws and preserve the luxurious lifestyle of the citizens of Elysium. That doesn’t stop the people of Earth from trying to get in, by any means they can. When unlucky Max (Matt Damon) is backed into a corner, he agrees to take on a daunting mission that, if successful, will not only save his life, but could bring equality to these polarized worlds.','He can save us all.',115000000,286140700,67.33767,6.4,3439,109,'2013-08-07','en','/aRjuJuPXHtVs6YegfeeQWXGRs1E.jpg',3.827021625568781,3,'2026-09-10',2,NULL,NULL),(68726,'环太平洋','Pacific Rim','When legions of monstrous creatures, known as Kaiju, started rising from the sea, a war began that would take millions of lives and consume humanity\'s resources for years on end. To combat the giant Kaiju, a special type of weapon was devised: massive robots, called Jaegers, which are controlled simultaneously by two pilots whose minds are locked in a neural bridge. But even the Jaegers are proving nearly defenseless in the face of the relentless Kaiju. On the verge of defeat, the forces defending mankind have no choice but to turn to two unlikely heroes—a washed-up former pilot (Charlie Hunnam) and an untested trainee (Rinko Kikuchi)—who are teamed to drive a legendary but seemingly obsolete Jaeger from the past. Together, they stand as mankind\'s last hope against the mounting apocalypse.','To Fight Monsters, We Created Monsters',180000000,407602906,56.523205,6.7,4794,131,'2013-07-11','en','/8wo4eN8dWKaKlxhSvBz19uvj8gA.jpg',3.956260629436227,3,'2026-09-10',2,NULL,NULL),(68727,'迷幻','Trance','如果你将一副价值2500万英镑的天价名画藏在了一个“安全的地方”，那你最好把地址记牢了。但是如果碰巧你真的忘记了，那该怎么办？  西蒙(詹姆斯·麦卡沃伊饰演)是伦敦一家著名拍卖行的员工。如果拍卖行遇到抢劫，西蒙要负责把名画转移到安全的地方去藏起来。但是章程告诉他们，名画再贵也比不上人的性命值钱，换句话说关键时刻还是保性最要紧。没过多久，抢劫案真的发生了，目标是一副刚刚拍得2700万英镑的油画。西蒙试图把画转移到保险箱，但他被遭到了劫匪弗兰克(文森特卡索)的袭击昏迷不醒。  尽管丢失了名画，但西蒙还是被封为一名英雄。脑补受创让他患上了失忆症，对事情的经过模模糊糊，甚至想不起来究竟把画藏在哪里。同样没有得到名画的弗兰克失望透顶，他绑架了西蒙，试图逼他讲出地址。为此弗兰克找来了女催眠师(罗莎里奥道森)来帮助西蒙恢复记忆。这名叫做伊丽莎白·蓝布的催眠师很是神通广大，很快找到了“开启”西蒙大脑的方式，然而——她的真正目的又是什么？','Don\'t be a hero.',20000000,24261569,38.802415,6.5,956,101,'2013-03-27','en','/9w4TTQTMfG9LMyXPfdmisRisg57.jpg',3.4788301191440674,3,'2026-09-10',2,NULL,NULL),(68728,'魔境仙踪','Oz the Great and Powerful','《奥兹巫师》是童话《绿野仙踪》的前传，其剧情是：一个卖蛇油的打扮成魔法师走街串巷推销他的产品，他和一个女人偷情，结果被这个女人的丈夫发现，不得已坐上了热气球。他来到了奥兹国，成为“奥兹国的魔法师”。他还爱上了“北方好女巫”格林达，并和她一起对抗“东方坏女巫”伊瓦诺拉和“西方坏女巫”西奥多拉。西奥多拉本来也是好女巫，但被奥兹甩了以后，真正的坏女巫伊瓦诺拉说服了她变坏，并让其帮助自己统治整个奥兹国。','In Oz, nothing is what it seems',200000000,491868548,46.985445,5.7,3530,130,'2013-03-07','en','/fkbpV9HW7yNb8pxq45gOgwdGJgQ.jpg',3.6124465898220794,3,'2026-09-10',2,NULL,NULL),(68734,'逃离德黑兰','Argo','1979年11月，伊朗局势剧烈动荡，武装人员占领美国驻德黑兰大使馆，大批使馆人员被扣为人质。混乱之中，六名美国外交人员侥幸逃脱，秘密藏身于加拿大外交官的住所，但他们随时面临身份暴露的危险。为了将六人安全带离伊朗，中央情报局专家托尼·门德斯提出了一个近乎异想天开的计划：虚构一部正在筹拍的科幻电影，将自己伪装成电影制片人，再把六名外交人员包装成前来伊朗勘察外景的加拿大摄制组。随着计划一步步展开，一场稍有差错便可能满盘皆输的秘密撤离行动由此开始……','The movie was fake. The mission was real.',44500000,232324128,62.01056,7.1,3423,120,'2012-10-11','en','/m5gPWFZFIp4UJFABgWyLkbXv8GX.jpg',3.9869354011537204,3,'2026-09-10',2,NULL,NULL),(68735,'魔兽','Warcraft','艾泽拉斯与德拉诺本是两颗祥和安宁的星球，人类在艾泽拉斯大陆上世代繁衍生息，兽人则在德拉诺的土地上辛勤耕耘。直到古尔丹的出现，打破了两个星球的和平。邪恶的古尔丹为了一己私利，使用恶魔能量打开了一扇传送门 —— 黑暗之门，并残忍的破坏兽人的家园。霜狼氏族的酋长杜隆坦不得不带领着自己的族人离开支离破碎的德拉诺，在举步维艰的艾泽拉斯大陆上寻找着庇护所。面临家园危机的人类在领袖洛萨的带领下一边痛击着野蛮的入侵者，一边苦苦寻求着战争之外的解救方法。两个种族面临着同样的危机，他们必须设法渡过这场灾难。','Two worlds. One home.',160000000,433677183,63.148529,6.3,2268,123,'2016-05-25','en','/eGi5aoxaZveqNLtE7BZJCuWwR3G.jpg',3.6984944472595602,3,'2026-09-10',2,NULL,NULL),(68737,'第七子：降魔之战','Seventh Son','在古老传说和魔法相互碰撞的魔力时代，某神秘组织唯一幸存的一名武士（由奥斯卡影帝杰夫·布里吉斯扮演）经四处巡游找到了预言中天赋异能的英雄——最后的第七子（由本·巴恩斯扮演）。这位起于田亩、与英雄形象相去甚远的年轻人在身经百战的师父的陪同下，开启了征服黑暗女王（朱丽安·摩尔扮演）和其手下具有超自然力量的刺客军团的勇敢之旅。','When darkness falls, the son will rise. When the son falls, the dark knight will rise.',95000000,114178613,63.628459,5.2,957,102,'2014-12-12','en','/qAWr69f3h7gXkVWgnFUZfJcMnw.jpg',3.314349370895254,3,'2026-09-10',2,NULL,NULL),(68812,'冰人','The Iceman','影片根据Anthony Bruno的小说《The Iceman: The True Story of a Cold-Blooded Killer》改编，以编年体的结构了讲述了职业杀手Richard Kuklinski狂杀百人的故事，他经常将受害人的尸体冻成冰以掩盖死亡时间，江湖人称“冰人”，他有职业操守，不杀女人和小孩。另一方面，他是个顾家的好男人，他的家庭从不知道他的阴暗身份。\r ...','Loving husband. Devoted father. Ruthless killer.',20000000,1969193,19.494703,6.4,365,105,'2012-09-01','en','/3edygPSm9XdISHza8zqHUVAQHAD.jpg',3.188833126007723,3,'2026-09-10',2,NULL,NULL),(68818,'黑荆棘','Blackthorn','影片故事发生在中美洲的玻利维亚，也就是《虎豹小霸王》的两位主人公最后丧生的地方。山姆·夏普德扮演的美国男子杰克·布莱克索恩（Blackthorn）以养马为生，感到死期不远的他决心回到美国。在途中杰克与爱德华多·诺列加扮演的逃犯相遇，两人渐渐建立起了不一般的友谊。  　　本片堪称《虎豹小霸王》的后传，是西班牙电影中并不常见的西部题材，由美国男星山姆・夏普德与西班牙帅哥爱德华多・诺列加合演。  　　“西部题材事实上是一种道德题材，角色面临的选择简单而纯粹，生与死亦或是自由、诺言、忠诚、勇气、正义甚至是爱”，导演马泰奥・吉尔称，“他们做出的决定不仅充满了戏剧效果，而且有着教化意义”。  　　吉尔是著名导演亚历桑德・阿曼巴的编剧搭档，曾执笔过《睁开你的双眼》、《深海长眠》、《城市广场》等作品。他在1999年执导的处女作《邪魔重生》也是由诺列加主演，曾获得戈雅特效提名，之后还在2005年推出过名为《魔鬼》的电视电影，《黑荆棘》是他的第三部长片。','No destiny',0,623528,5.223096,6.6,73,98,'2011-08-31','en','/3QtOCerjSPkS9fo8IBwDr7qAwoj.jpg',2.7936473684289074,3,'2026-09-10',2,NULL,NULL),(68924,'冰风暴','The Ice Storm','1973年美国康涅狄格州，感恩节快要到来，一场冰风暴也即将到来。平凡乏味的家庭生活使中年夫妻厌倦，丈夫本•胡德（凯文•克莱恩饰）一直在引诱邻居珍妮特•哈珀，而妻子（琼•艾伦饰）对丈夫的谎言也早已不耐烦了。儿子保罗（托比•马奎尔饰）迷恋着学校里最有人缘的那位女生。女儿温迪（克里斯蒂娜•里奇）兴趣于电视里的水门事件听证会。  　　冰风暴的夜晚，夫妻两个去朋友家参加一个鸡尾酒会，鸡尾酒会的一个重要内容是进行换房间钥匙的游戏。在酒会结束后，每个妻子都可以和别家男人结成新欢。而他们儿子则赶去面对一场诱惑与考验，女儿正陶醉在同邻家男孩子的性游戏中……','It was 1973, and the climate was changing.',18000000,8038061,14.916264,6.9,176,112,'1997-09-27','en','/ze4lE4N9Z8lnfaBDWVxEvtHsh7b.jpg',3.037808086661229,3,'2026-09-10',2,NULL,NULL),(69270,'混合','Super Hybrid','Late one night, a mysterious car is brought into the Chicago police impound garage after a deadly traffic accident. The on-call mechanics soon discover the car has a mind of its own. With hundreds of horsepower and two tons of reinforced steel at its command, it\'s a seemingly unstoppable killing machine capable of outrunning -- and outwitting -- humans.',NULL,13000000,0,4.009379,4.6,24,95,'2010-01-01','en','/iK3RR1bNWN99jt3EwEAqYanw6Br.jpg',2.5274364674091903,3,'2026-09-10',2,NULL,NULL),(69382,'The Legend of God\'s Gun','The Legend of God\'s Gun','A gun-slinging preacher returns to the debaucherous town of Playa Diablo seeking revenge from the notorious scorpion-venom drinking bandito El Sobero - lead outlaw and number one bad guy. El Sobero and his band of bad banditos are also returning to Playa Diablo seeking their own revenge against the town sheriff. With the Bounty Hunter dragging up slowly behind there is sure to be a confrontation of Biblical proportions as they all meet in the circle of death.',NULL,0,0,0.003582,0,0,78,'2007-07-08','en','/7cw3jSGvm3XoHwnRRA9dCrkAFXi.jpg',1.8337905673139772,3,'2026-09-10',2,NULL,NULL),(69640,'Lies in Plain Sight','Lies in Plain Sight','“Lies in Plain Sight” tells the story of Eva and her blind cousin Sofia (Martha Higareda), who were inseparable as children, with Eva the loyal companion who helped Sofia through her tough adolescent years. When Eva suddenly commits suicide, Sofia rushes home to her father, Hector (Benito Martinez), and Eva’s parents, Marisol (Rosie Perez) and Rafael (Yul Vásquez), to find answers. But the more she delves into Eva’s life, questioning her past boyfriends Ethan (Chad Michael Murray) and Christian (Christoph Sanders), the more Sofia realizes that their childhood was actually filled with dark, disturbing secrets.',NULL,0,0,0.47909,4.5,4,88,'2010-10-03','en','/4VzDK2Ki8kKoEMwFQglhywiy1no.jpg',2.181719657128643,3,'2026-09-10',2,NULL,NULL),(69668,'梦宅诡影','Dream House','在一个飘雪的季节，小有成就的出版人威尔·艾藤森（丹尼尔·克雷格 Daniel Craig 饰）辞去工作，带着妻子莉比（瑞切尔·薇兹 Rachel Weisz 饰）和一双可爱的女儿离开喧嚣的纽约市，来到安静的新英格兰镇展开新的生活。新的环境，新的磨合，表情冷淡甚至露着敌意目光的邻居，化着浓重哥特妆容不请自来的小青年，都令维尔的的幸福显得那么脆弱不堪。与此同时，女儿们似乎也受到神秘诡异的事物所侵扰。随着奇怪的事情不断涌现，艾藤森夫妇渐渐察觉他们的房子当年曾经发生过凶杀案。  　　威尔偷偷对房子的过去展开调查，而这个平凡的四口之家好像也成了他人锁定的目标……','Once upon a time, there were two little girls who lived in a house.',50000000,38502340,19.267479,5.8,391,84,'2011-09-30','en','/prZMuhuPbmMgY9ilBgNpYgZGg1I.jpg',3.14167937196662,3,'2026-09-10',2,NULL,NULL),(69848,'一个人的英雄','One Man\'s Hero','在美墨战争期间，一群爱尔兰移民士兵因宗教信仰遭受迫害而叛逃到墨西哥一方。','One man\'s hero is another man\'s traitor.',0,0,0.910529,9.3,2,121,'1999-08-02','en','/6QbunsUllQT0aQWWgMBnSlqwrfF.jpg',2.0770410707819855,3,'2026-09-10',2,NULL,NULL),(70006,'永不退缩2','Never Back Down 2: The Beatdown','本片是好莱坞动作巨星迈克尔·加·怀特的首部自导自演的以MMA为题材的电影,也是迈克尔·加·怀特第一部导演作品,本片也是2008年上映的那部永不退缩的续集 。永不退缩2：关注怀特的导演水平，而且此片动作方面绝对值得期待，因为武指是终极斗士3的Larnell Stovall。怀特是导演，但不是男一号 而是男一号的导师，电影里找来不少UFC的选手参加演出。',NULL,3000000,0,9.249229,5.8,136,90,'2011-09-13','en','/7VjtTMQpfy9GxMyjUfuYTfyatZz.jpg',2.9085150355238296,3,'2026-09-10',2,NULL,NULL),(70074,'赤警威龙','Bullet to the Head','一起案件，两个无辜的人死掉，黑白两道都想找出幕后的黑手。  　　史泰龙扮演的吉米·波波是一个杀手，为了找到隐匿在暗处的敌人，他不得不和成康所扮演的纽约的警察合作。而这个叫做泰勒的警察，也需要借助吉米的力量，找出他所想找到的真相。虽然说他们的调查充满了危险性，但是这个跨越了黑白两道的组合却战无不胜攻无不克。  　　随着他们的调查的深入，他们发现自己所面对的敌人不仅仅是隐藏在街头巷尾的那些小混混，而且有新奥尔良的一些高官。但是，事已至此，吉米和泰勒只有一往无前，冲破藩篱，才能得到最终的真相并把罪魁祸首绳之以法。','Revenge Never Gets Old.',55000000,9489829,22.503935,5.2,481,92,'2013-01-31','en','/iHaWoAPBrJ64kN9FrhRmpFersbp.jpg',3.117823906354373,3,'2026-09-10',2,NULL,NULL),(70160,'饥饿游戏','The Hunger Games','Every year in the ruins of what was once North America, the nation of Panem forces each of its twelve districts to send a teenage boy and girl to compete in the Hunger Games.  Part twisted entertainment, part government intimidation tactic, the Hunger Games are a nationally televised event in which “Tributes” must fight with one another until one survivor remains.  Pitted against highly-trained Tributes who have prepared for these Games their entire lives, Katniss is forced to rely upon her sharp instincts as well as the mentorship of drunken former victor Haymitch Abernathy.  If she’s ever to return home to District 12, Katniss must make impossible choices in the arena that weigh survival against humanity and life against love. The world will be watching.','May The Odds Be Ever In Your Favor.',75000000,691210692,68.550698,6.9,9455,142,'2012-03-12','en','/apa5G43Hha7kH7wJG0gkkHT7FA9.jpg',4.197540146886704,3,'2026-09-10',2,NULL,NULL),(70435,'制胜一击','Haywire','漂亮强悍的女特工玛洛里（吉娜·卡拉诺 Gina Carano 饰）一直是杀手公司的香饽饽，因为无论何种难题，交到玛洛里手上总能被完美解决。一个星期前，玛洛里顺利从巴塞罗那解救出人质江后，又被紧急调派到都柏林执行另一个所谓“小菜一碟”的任务，然而她却在执行任务中发现，自己从巴塞罗那救下的人质在都柏林被杀害，而证据却指向她。玛洛里意识到自己被算计了，迎接她的是一场国际性的大围剿。被逼无奈，玛洛里只好在几个江湖老友的帮助下四处奔逃，还要赶在对方之前，保护好自己在美国的家人，更艰难的是，玛洛里凭一己之力能否在全身而退之后，揪出幕后黑手呢？','They left her no choice.',23000000,33372606,26.257951,5.6,505,93,'2011-11-06','en','/6sqkGGRT8yZKUFPNaV1iPyTRzfI.jpg',3.1828732727401614,3,'2026-09-10',2,NULL,NULL),(70436,'乌鸦','The Raven','十九世纪末的一天,一位母亲和她的女儿被一个凶手残忍地杀害了。并被抛尸在了巴尔的摩。当地的警官艾迈特·菲尔兹通过对现场详细的调查后发现了一个惊人的事实。现实中的这个凶手的犯罪手段和当地报纸上刊登的一个凶杀小说里虚构的凶手的作案手法一模一样。而这个小说的作者就是充满了争议的爱伦·坡。于是,爱伦·坡便被带到了警察局去做调查。就在爱伦·坡被审问的当下,又一起杀人案发生在了当地,毫无疑问,凶手又一次使用了爱伦·坡在小说中所描绘的那种犯罪手段。在意识到当地出现了一个使用`爱伦·坡方法`的连环杀人凶手后,菲尔兹立刻请爱伦·坡当作自己的顾问,用他对凶手心理的理解和对小说人物的掌控来帮助自己断案。可是,案件却并不像菲尔兹所料想的那么发展,种种迹象表明,爱伦·坡会成为这个杀人凶手的下一个行凶目标。现在,猎人变成了猎物,而爱伦·坡是不是能用自己对犯罪份子的心理的掌控来使自己从这出杀人的游戏中全身而退呢?','The only one who can stop a serial killer is the man who inspired him.',26000000,29657751,22.520842,6.1,426,111,'2012-03-09','en','/hvPHJ6RrTZHf1EPmkXxbwmxMR6c.jpg',3.1990426077221334,3,'2026-09-10',2,NULL,NULL),(70478,'空中小姐','The Stewardesses','The Stewardesses is a 1969 Softcore 3-D film. Produced on a budget of just over $100,000, the film grossed over $27,000,000 (USD) in 1970 dollars, becoming the most profitable 3-D film ever released. This has now been passed by James Camerons Avatar.','The Unpublishable Novel Is Now America\'s Most Controversial Film!',100000,27000000,1.183892,4.3,5,69,'1969-07-25','en','/otrgebmsmyFVXv2R5pWp3DqY9eQ.jpg',2.2218551362099195,3,'2026-09-10',2,NULL,NULL),(70670,'猎头游戏','Hodejegerne','故事讲述了一个猎头为了支付自己奢靡的生活，铤而走险盗取富翁客户的艺术收藏，却没想到自己身陷一个谋杀计划中。罗杰的表面工作是猎头公司的总裁，可是背地里他却是一个名画大盗。为了维持自己奢侈的生活和妻子画廊的开销，他只有不停地偷画、卖画来改善自己即将破产的经济状况。罗杰的妻子遇到了一位荷兰的做GPS的商人。名义上他是来挪威继承遗产并找工作的，可实际上，他另有计划。罗杰的财务遇到了麻烦，就在这个时候，他了解到荷兰电子商人家里有一副失踪已久的名画，搞定它，自己下半生就衣食无忧了。说干就干的罗杰很轻松地就偷到了画。可是随着画到手的，还有不停的麻烦事。起先，罗杰以为自己的妻子出轨，可是随着事件的发展他愈发觉得自己正在和一个无形的组织打交道。在误杀了自己的好朋友之后，罗杰成为了逃犯。逃命途中，他也得知自己偷来的名画是个赝品，而且那个神秘的荷兰商人是在利用自己。走投无路的罗杰回到了家中，在确信自己和妻子之间的爱情之后，他朝着那个要夺他性命的荷兰商人、前特种部队军人展开了倒戈一击……','The hunt is on.',0,15699707,20.821846,7.1,399,100,'2011-08-04','en','/b444Dp2KOhhhSKAvYKwC2xnIqMW.jpg',3.2872056162814567,3,'2026-09-10',2,NULL,NULL),(70687,'The Sticky Fingers of Time','The Sticky Fingers of Time','A 1950s author (Terumi Matthews) is transported to 1990s Brooklyn, where she meets a woman (Nicole Zaray) who reads about her life.',NULL,250000,0,0.130169,4.8,3,90,'1997-06-06','en','/rTyNAfz8znLPMzytmKGhvlXFee.jpg',2.133494593518691,3,'2026-09-10',2,NULL,NULL),(70829,'最后的教父','라스트 갓파더','黑社会教父遗失的儿子...是\"英九\"！？  　　平凡的外貌，笨拙的行动，任谁看瞬都十分特别的\"英寨九\"来到纽约投奔失散已久俐的黑社会教父爸爸，继而被指定为教父继承人而且需要接受一系列的课程训练，而训练他的正是组织的2号人物。本来很有可能接替教父位置的2号人物因为英九的出现倍感郁闷，还在对英九的训练过程中遭遇了重重挫折。而英九却在他糟糕的训练中，偶然搭救了对手黑社会组织头目的女儿南希并和她成为了朋友。不仅如此，英九为了赚钱讨好父亲而找商家的麻烦，却不小心造就了超级热卖的商品而成为了城市英雄。而看不惯英九的对头组织的2号人物绑架了南希，并栽赃给英九，从而挑起了两派组织间的战争，深陷阴谋的英九究竟会如何面对这一切呢！？  　　幕后制作  　　“傻瓜英九”大否闹“美国往事”  　　在韩国电影界有一个异类，他究竟是旷傻瓜还是英雄，没人知道。擅长肢体表演的沈炯来塑造了韩国人家喻户晓的“傻瓜英久”这个角色，但在之后却转行导演，1996年推出了意图革命韩国科幻电影的《怪兽大决战》最后却沦为笑柄，他的国际梦想却并未就此罢休。就在《太极旗飘扬》的姜帝圭到好莱坞发展处处受挫的同时，沈炯来却打造出了首部在美国影院大规模上映的《龙之战》，在韩国本土更突破了800万人次。且不论影片的质量究竟如何，沈炯来在吃螃蟹方面永远走的比别人先。最新，沈炯来又回到喜剧本行推出了《最后的教父》，该片在美国取景、使用英文对白，并邀请到受人尊敬的好莱坞影星哈威•凯特尔主演，在韩国再度引发话题。  　　《最后的教父》由沈炯来自编自导自演，挂名编剧还包括创作过《儿女一箩筐》、《加菲猫》的好莱坞编剧搭档Alec Sokolow、Joel Cohen（此科恩非彼科恩，比尔•莫瑞就曾声称自己是看错了才接拍的《加菲猫》）。与《龙之战》相似，《最后的教父》又打出了韩国与好莱坞的“合体”，瞄准两端市场。影片的主人公其实就是沈炯来80年代在影视剧中塑造的“傻瓜英九”，继续以笨拙滑稽的肢体语言来搞笑，只不过背景穿越到了50年代的美国黑帮。影片预告片的开头从黑帮片的气氛跳转到喜剧片颇有些出其不意，但之后全都是老掉牙的身体搞笑，“傻瓜英久”究竟能否得到韩国之外观众的欢迎得打上大大的问号',NULL,13400000,16700000,0.680753,4.7,7,100,'2010-12-29','en',NULL,2.2828486918108974,3,'2026-09-10',2,NULL,NULL),(70868,'凯特的外遇日记','I Don\'t Know How She Does It','作为一个事业蒸蒸日上的基金经理人，凯特·瑞迪（莎拉·杰西卡·帕克饰）虽然年过中年，但她的生活乍看上去挺让人羡慕，不仅两个小孩听话懂事，丈夫更是温柔体贴，家庭和睦。其实内中的烦心事只有她自己清楚，由于工作繁忙，她无暇照看小孩，请来的小保姆常常懈怠两个小孩；自己太过强势，丈夫理查德·瑞迪（格雷戈·金尼尔饰）每天忍气吞声，和自己渐行渐远；公司里更是隔三岔五的便有男人大献殷勤……在这之外，并没打算要出轨的凯特，则将一个网上的聊天对象作为了自己生活的发泄口。周旋在这堆破事之间，凯特微妙的维持着生活方方面面的平衡，但这种平衡，某天终于被突如其来的意外给打破了……','If it were easy, men would do it too.',24000000,30551495,8.630825,5,141,89,'2011-09-16','en','/k2spvQZSdPjoVRxcZlQipYtr8nj.jpg',2.875509852507239,3,'2026-09-10',2,NULL,NULL),(70875,'The Harvest (La Cosecha)','The Harvest (La Cosecha)','The story of the children who work 12-14 hour days in the fields without the protection of child labor laws. These children are not toiling in the fields in some far away land. They are working in America.',NULL,56000,0,0.010909,0,0,80,'2011-07-29','en',NULL,1.8338073036238052,3,'2026-09-10',2,NULL,NULL),(70981,'普罗米修斯','Prometheus','21世纪末，人类的科技水平已高度发达，克隆人技术和宇宙航行早已实现，不再是梦想。与此同时，许多科学家仍孜孜不倦追索着人类起源的秘密与真相。通过对许多古老文明的考察与对比，科学家伊丽莎白·肖和查理·赫洛维发现，人类可能是来自一个遥远星系的外星人创造的。在维兰德公司的资助下，他们乘坐维克丝所掌管的宇宙飞船普罗米修斯号前往那颗未知的星球。经过对当地的考察，地球人的设想成功得到印证。可是他们贸然探查“神的秘密”的行为，也将自己引入万劫不复的深渊……','The Search for Our Beginning Could Lead to Our End.',130000000,403170142,68.889395,6.3,5080,124,'2012-05-30','en','/qsYQflQhOuhDpQ0W2aOcwqgDAeI.jpg',3.893281328026562,3,'2026-09-10',2,NULL,NULL),(71157,'警员','Polisse','未成年人保护署的警察们日常除了要看管恋童癖、逮捕少年扒手之外，也许还要在吃午餐的间隙去解决青少年的家庭问题。他们的工作中充斥着糟糕的事，比如审讯虐待儿童的父母，对青少年和儿童的性暴力行为取证，但他们的工作也有好的一面，比如同事间的集体协作和成功的欢笑，这些都让人感到不可思议。至今为止，这些警察们认为最糟糕的事就是，在努力工作的同时，他们应该如何在私生活和现实工作中找到一个平衡点。内务部派一个女记者梅丽莎来制作一本关于未成年人保护署警察们的生活相册，但是性格古怪的弗雷德却十分不喜欢她，想将她排挤出队伍。',NULL,0,20374201,14.038703,7.9,285,127,'2011-10-06','fr','/jt5iH1ffawf3NXX0YVgfSexQH8H.jpg',3.2448293248973985,3,'2026-09-10',2,NULL,NULL),(71469,'至暗之时','The Darkest Hour','在多个白色光球出现之后，恐怖的外星人出现在了莫斯科红场，瞬间便杀死了城中的9成居民。幸存者在埃米尔·赫斯基扮演的主角的带领下，与外星人做殊死的抵抗。影片中的外星人有着不可思议的能量，触碰到其能量范围的东西马上会被撕碎，更令人恐怖的是，外星人还可以伸出自己的能量场，来摧毁目标；外星人在白天可以隐形，人们看不见他们，但是在晚上，他们自身的能量会使周围的灯泡发亮，录音机发声，从而暴露自己的目标。他们通过物体发出的电信号捕捉目标，幸存者们借助科学家的力量，制造了一种可以屏蔽自身电信号的装置，试图反戈一击。','Survive The Holidays',30000000,64626786,23.328823,4.8,469,89,'2011-12-22','en','/8MmdJd3qBrVpPLUIsUFH7a0LtpJ.jpg',3.0688853860922243,3,'2026-09-10',2,NULL,NULL),(71547,'Fascination','Fascination','Young Scott Doherty (Adam Garcia) gets suspicious when his mother (Jacqueline Bisset) plans to wed Oliver Vance (Stuart Wilson) soon after her husband\'s untimely death. Scott investigates with Oliver\'s pretty daughter, Kelly (Alice Evans), who shared Scott\'s doubts about the upcoming nuptials. Along the way, he falls in love with Kelly, but a fatal explosion turns Scott\'s life upside down - and the evidence points to him as the murderer. Has he been framed?',NULL,0,0,0.219799,3.8,4,95,'2004-10-13','de','/h9IsB1pv6U7H4bEUiKG92VXlNrn.jpg',2.1799805187737844,3,'2026-09-10',2,NULL,NULL),(71552,'American Reunion','American Reunion','The characters we met a little more than a decade ago are returning to East Great Falls for their high-school reunion. In one long-overdue weekend, they will discover what has changed, who hasn’t and that time and distance can’t break the bonds of friendship. It was summer 1999 when four small-town Michigan boys began a quest to lose their virginity. In the years that have passed, Jim and Michelle married while Kevin and Vicky said goodbye. Oz and Heather grew apart, but Finch still longs for Stifler’s mom. Now these lifelong friends have come home as adults to reminisce about – and get inspired by – the hormonal teens who launched a comedy legend.','Save the best piece for last.',50000000,234989584,39.920035,6.1,1611,113,'2012-04-04','en','/m7PFrqjTOSTdQlriwTX9jd9LjiZ.jpg',3.526045458707619,3,'2026-09-10',2,NULL,NULL),(71676,'恶灵骑士2：复仇时刻','Ghost Rider: Spirit of Vengeance','约翰·布雷斯（尼古拉斯·凯奇 Nicolas Cage 饰）被正义天使拉萨罗斯附体，但天使暴躁乖戾，遇到坏人就要吸取他们的灵魂。莫罗（伊德瑞斯·艾尔巴 Idris Elba 饰）请求布雷斯把小孩丹尼带来神殿以避免恶魔夺取他的灵魂，作为回报他将驱除布雷斯身上的诅咒。丹尼是魔鬼罗尔科的儿子，罗尔科为了把自己的魔力植入儿子体内正派卡里跟追踪逃跑途中的母子两人。正当母子俩被困在采石场的时候，布雷斯到来，他体内的天使爆发了出来，压制住了卡里根。他变成了恶灵骑士，毫不手软的把对手撕成碎片。当战争结束时，三人前往神殿，同时，罗尔科也救醒了死亡边缘的卡里根，并赋予他更可怕的摧毁力，让他再去把丹尼找回来。在神殿里，莫罗履行协议把布雷斯体内的扎萨罗斯驱赶了出来。但正当他做法时，神殿的牧师试图杀死丹尼——他认为丹尼就是恶魔。还没等他们行动，卡里根就到了。把丹尼带去见了罗尔科。罗尔科逼迫丹尼参与一个仪式，想使他变成一个彻头彻尾的恶魔。布雷斯试图阻止这个仪式，说服丹尼弃恶从善。在最后一战中，为了打败恶魔，丹尼用了他的力量把扎萨罗斯再次植入布雷斯体内。这次扎萨罗斯变成了正义的化身，打败了恶魔。','He Rides Again.',57000000,149217355,48.622278,4.7,1135,95,'2011-12-10','en','/6bspjWkTW4dLYJyvqhzYaeUSape.jpg',3.214412063086484,3,'2026-09-10',2,NULL,NULL),(71679,'Resident Evil: Retribution','Resident Evil: Retribution','The Umbrella Corporation’s deadly T-virus continues to ravage the Earth, transforming the global population into legions of the flesh eating Undead. The human race’s last and only hope, Alice, awakens in the heart of Umbrella’s most clandestine operations facility and unveils more of her mysterious past as she delves further into the complex. Without a safe haven, Alice continues to hunt those responsible for the outbreak; a chase that takes her from Tokyo to New York, Washington, D.C. and Moscow, culminating in a mind-blowing revelation that will force her to rethink everything that she once thought to be true. Aided by new found allies and familiar friends, Alice must fight to survive long enough to escape a hostile world on the brink of oblivion. The countdown has begun.','The Ultimate Battle Begins',65000000,240159255,6.227675,5.6,1600,95,'2012-09-12','en','/naUpPXmuDBWukjGEenF1pjxQbfA.jpg',3.344530461161341,3,'2026-09-10',2,NULL,NULL),(71688,'铁娘子：坚固柔情','The Iron Lady','耄耋之年的撒切尔夫人（梅丽尔•斯特里普 Meryl Streep 饰）罹患老年痴呆症，时常在幻觉和回忆中切换。她感觉深爱的丈夫一直在身边陪伴，其实后者早已亡故。她作为杂货店的女儿，因为出身贫寒，时常饱受世人的白眼。然而，在聆听了保守党的演讲后，她坚定了自己的政治信仰，并以优异成绩考入牛津大学，虽然在一次议员选举中落败，但是她却收获了真挚的爱情与他相伴，坚定了自己从政的人生道路。从此，她逐渐走到了保守党魁的位置。终于，保守党在选举中大胜，而她也成为了英国历史上第一位女首相，组建了自己的内阁政府。面对纷繁复杂的国际国内局势，她力主的自由市场政策也饱受非议，但是她用过人的智慧和超强的忍耐力，战胜了左辅右弼众叛亲离的局面，凭一己之力拯救了英国经济，捍卫了领土主权，被世人称作铁娘子……','Never Compromise',13000000,114956699,23.3784,6.2,527,105,'2011-12-30','en','/bzD6sJdvwx3NPzFfwV0imlAml32.jpg',3.259505747639986,3,'2026-09-10',2,NULL,NULL),(71805,'海难','Håkon Håkonsen','本片叙述了一位名为哈肯的挪威男孩，他为了要协助父母双亲，因此小小年纪就跑去当水手远赴重洋，开始他的艰险旅程。但不料途中船只却被一位假冒的英国海军官员约翰·麦里克劫持，后来又意外遇上了强度飓风的侵袭，整艘船因此触礁沉没。哈肯侥幸逃上临近丛林密布的小岛，但是船员们却已失去踪影。在好朋友和一偷渡女孩的帮忙下，他们必须共同合作，不但要在荒岛上冒险求生，还要跟凶恶的海盗周旋到底。',NULL,0,0,0.702971,6.1,14,92,'1990-10-03','en','/t2zySHDygpoPhhGUNJNOca5S5os.jpg',2.423362414554596,3,'2026-09-10',2,NULL,NULL),(71859,'凯文怎么了','We Need to Talk About Kevin','伊娃是一名梦想周游世界的职业女性，但突如其来的婚姻和意外的怀孕使她放弃了自己的理想，成为了一名家庭主妇。可是，她的牺牲换来的却只有失望。从小凯文就不是个令人省心的孩子，无休止的哭闹，对母亲的关怀无动于衷，对于这样一个孩子，伊娃难免有些自暴自弃。很快，一个小女儿的诞生打破了僵局，遗憾的是，小姑娘天生失语，这悲惨经历更是让伊娃将自己全部的爱倾注在了她的身上。成年后的凯文与母亲之间的距离越来越远，倒是和父亲颇为亲近，他爱好射箭，父亲便送了一副弓箭给他，没想到，正是这副弓箭带给了这个家庭以及整个社会一次破灭性的打击。凯文到底怎么了？谁也无法回答，就连凯文自己，面对这样一个问题，也只能沉默以对。',NULL,7000000,6038942,21.276864,7.4,677,112,'2011-09-28','en','/yTLz5bmz5qKU8ijqYyfT7wxQ7jK.jpg',3.4840399522344923,3,'2026-09-10',2,NULL,NULL),(71864,'蒂莫西的奇异生活','The Odd Life of Timothy Green','一对无法生育的夫妻吉姆及辛蒂，一直希望能够有个孩子，所以他们把所有的期望都写了下来，希望能上天能赐与他们一个可爱的宝贝，然后将这些纸条都装进一个盒子，埋在后院。没想到，神奇的事情发生了！经过一个暴风雨的夜晚，一个小男孩小芽竟出现在他们家门口，并自认是他们的孩子，他们得到了一个独一无二的宝贝！这个奇幻的男孩，会给这对夫妻带来什么样的新人生呢？','He\'s a force of nature.',0,51854875,16.394452,6.5,386,105,'2012-08-15','en','/24HWf4QBnEbNYDJfNFR1CmwtST5.jpg',3.2053397700763204,3,'2026-09-10',2,NULL,NULL),(71866,'坦纳大厅','Tanner Hall','这是发生在新英格兰一所私立女子寄宿学校里，四个即将成年的女孩之间青春成长故事……',NULL,0,0,2.015525,5.4,32,96,'2009-09-14','en','/qoGtVlqaFWngUXuUzAS6uuNcwsI.jpg',2.5886469418472884,3,'2026-09-10',2,NULL,NULL),(71880,'杰克与吉尔','Jack and Jill','著名笑星亚当·桑德勒片中一人分饰两角、一对孪生兄妹：哥哥杰克和妹妹吉尔。而两人之间则是水火不相容，笑料不断。','His twin sister is coming for the holidays... ...and it ain\'t pretty.',79000000,149673788,22.132418,4.1,604,91,'2011-11-11','en','/qRZ48goJAHaZviDNghNzrUOnXpL.jpg',3.0015160965920704,3,'2026-09-10',2,NULL,NULL),(72086,'夜缉者','The Night Visitor','An insane Swedish farmer escapes from an asylum to get revenge on his sister, her husband and others.','Locked in the cold asylum of his mind - a sane man stalks his prey...',0,0,0.074005,7.3,6,106,'1971-01-01','en','/bOKz7uhdjuLC9MNNY2874T5h6pX.jpg',2.259410601567454,3,'2026-09-10',2,NULL,NULL),(72105,'泰迪熊','Ted','孤僻的约翰儿时许了一个愿，希望他的玩具泰迪熊可以活过来，成为他真正的朋友。奇迹发生了，泰迪有了生命，并和约翰一起生活了二十多年。如今老大不小的约翰无所事事，整天和泰迪一起抽烟喝酒吸大麻，过着醉生梦死的生活。直到他遇上美丽的劳丽，决心要改变自己。可是，泰迪却并不喜欢约翰的新女友劳丽，总是处处给劳丽找麻烦，甚至破坏约翰和劳丽的感情。面对陪伴多年的老友，和刚刚俘获的女友，约翰要如何处理两者之间的关系？他是不是能找到一个平衡点呢？','Ted is coming.',50000000,549368315,68.87691,6.3,4697,106,'2012-06-29','en','/1QVZXQQHCEIj8lyUhdBYd2qOYtq.jpg',3.8757370201842702,3,'2026-09-10',2,NULL,NULL),(72113,'杀戮','Carnage','平凡的一天，名叫扎克利和伊森的小男孩在某公园内发生争执，前者用棍子将后者的嘴打破。这起不大不小的儿童纠纷，将两对本没有任何交集的夫妇拉到了一起。经营小百货商店的麦克·朗斯特里特（约翰·C·赖利 John C Reilly 饰）与身为作家的潘妮洛普（朱迪·福斯特 Jodie Foster 饰）是伊森的父母，他们在家中迎来扎克利的父母——律师艾伦·考温（克里斯托弗·沃尔兹 Christoph Waltz 饰）以及投资经纪人南希（凯特·温斯莱特 KateWinslet 饰）——的拜访。他们就孩子的伤害事件协商、讨论、争执、冷嘲热讽、旁敲侧击，时而强作欢颜，时而面露不快，可是又不得不面对面度过这难熬与痛苦的一天……\r 　　本片荣获2011年波士顿影评人奖最佳群戏奖、2011年威尼斯电影节小金狮奖。','A new comedy of no manners',25000000,27603069,20.011435,7,738,80,'2011-09-16','en','/vgafyaqCrowYsMyhopWyvkDjLBS.jpg',3.447792107986506,3,'2026-09-10',2,NULL,NULL),(72190,'僵尸世界大战','World War Z','费城一个毫无征兆的宁静早晨，前联合国调查员盖瑞·雷恩（布拉德·皮特 Brad Pitt 饰）驾车载着妻子凯伦（米瑞·伊诺丝 Mireille Enos 饰）和两个女儿蕾切尔（Abigail Hargrove 饰）、康妮（Sterling Jerins 饰）外出。谁知原本快乐的气氛很快变为恐慌与死亡所替代，连环的爆炸，惊恐逃散的人群，无序的车祸以及啃咬他人的丧尸，繁华大都会转瞬沦陷。盖瑞费尽九牛二虎之力带着妻女逃生，最终逃到联合国副秘书长所在的航母上，进而得知包括美国总统在内的数名大国首脑均已死亡，丧尸病毒业已蔓延全球。为了阻止世界毁灭，格里无奈受命，和来自哈佛的病毒学博士法斯巴克（Elyes Gabel 饰）前往病毒的源头之地寻找解除危机的办法。  这是一场几乎完全没有希望且充满磨难的征程，世界命运危在旦夕……','Remember Philly!',200000000,531865000,81.834855,6.7,5560,116,'2013-06-20','en','/aCnVdvExw6UWSeQfr0tUH3jr4qG.jpg',4.049090911187608,3,'2026-09-10',2,NULL,NULL),(72197,'The Pirates! In an Adventure with Scientists!','The Pirates! In an Adventure with Scientists!','The luxuriantly bearded Pirate Captain is a boundlessly enthusiastic, if somewhat less-than-successful, terror of the High Seas. With a rag-tag crew at his side, and seemingly blind to the impossible odds stacked against him, the Captain has one dream: to beat his bitter rivals Black Bellamy and Cutlass Liz to the much coveted Pirate of the Year Award. It’s a quest that takes our heroes from the shores of exotic Blood Island to the foggy streets of Victorian London. Along the way they battle a diabolical queen and team up with a haplessly smitten young scientist, but never lose sight of what a pirate loves best: adventure!','It\'s A Plunderful Life',60000000,118338361,23.700759,6.4,374,88,'2012-03-12','en','/h3sigb1mbv3LGPGaMmKoRXqrcTO.jpg',3.204184581100473,3,'2026-09-10',2,NULL,NULL),(72207,'五年之约','The Five-Year Engagement','在众人眼里，汤姆（杰森·席格尔 Jason Segel 饰）和薇莱特（艾米莉·布朗特 Emily Blunt 饰）是天设地造的一对，他们经过1年的爱情短跑，都自认为是世界上最了解对方的那个人，两人闪电订婚。薇莱特渴望有一个完美的家庭，但同时也希望能够有自己的事业，她收到了密歇根大学的一个梦寐以求的职位，但前提是汤姆必须放弃现在的工作，两人一起迁往密歇根。汤姆同意了，但在密歇根的生活并不如他所想得那么美好，一方面，专业技能很强的他居然只能在小吃店找到一份仅够糊口的工作，另一方面，薇莱特在职场上屡屡获得成功，两人的距离越来越远。\r 　　矛盾随着薇莱特的步步高升日益激化，两人的婚礼年复一年的推迟着，而正当他们两人下定决心要举行婚礼的时候，一个第三者的吻却给两人的感情制造了难以愈合的伤痕。 ©豆瓣','A comedy about the journey between popping the question and tying the knot.',30000000,53909751,27.71063,5.7,457,124,'2012-04-27','en','/4Bj6pw3ZCo1f2DXP4k7AUDwMTFX.jpg',3.179791814395628,3,'2026-09-10',2,NULL,NULL),(72213,'勇气','Courageous','影片讲述了四个执法者的故事。作为打击犯罪的执法者，每天都生活在危险之中。虽然他们可以保护自己的安全，可是他们的家人还是遭遇到了不幸。剩下的这些男人只有依靠自己的力量和命运、希望、信仰和责任角力。正如同打铁的工具是另一块铁一样，这种命运改变了他们接下来的命运，在友谊和父爱的支撑下，他们做出了改变自己下半生的决定。','Honor Begins at Home.',1000000,34522221,5.961119,6.8,77,129,'2011-09-30','en','/hVRkbZRCoHtnfi0V9GFZ3uXjCNp.jpg',2.8131606786221437,3,'2026-09-10',2,NULL,NULL),(72331,'吸血鬼猎人林肯','Abraham Lincoln: Vampire Hunter','19世纪上半叶，后来在美国历史上留下重要足迹的亚伯拉罕·林肯（本杰明·沃克 Benjamin Walker 饰）还只是一个背负着杀母仇恨的年轻人。在一个充满不祥气息的夜晚，他举枪刺杀了仇人，但已经遭受了致命伤的仇家却凶恶反扑。关键时刻，林肯被名叫亨利·斯特吉斯（多米尼克· 库伯 Dominic Cooper 饰）的男人所救。从亨利口中得知，他险些被变成吸血鬼的仇家杀害。经过一番艰苦特训，林肯成为吸血鬼猎人。正值此时，吸血鬼业已蔓延整个美国南部，并渐次向北方推进。在亨利的指示下，林肯返回城镇，展开了针对吸血鬼似乎永无止境的猎杀，而吸血鬼制造者杰克·巴兹（Marton Csokas 饰）也注意到了这名“索命死神”的存在……','Are you a patriot or a vampire?',69000000,112265139,38.634767,5.5,1269,94,'2012-06-20','en','/hDx79VNRH4GQvkTxr2fcbrwLFL5.jpg',3.3571737182988315,3,'2026-09-10',2,NULL,NULL),(72358,'A Thousand Words','A Thousand Words','Jack McCall is a fast-talking literary agent, who can close any deal, any time, any way. He has set his sights on New Age guru Dr. Sinja (Cliff Curtis) for his own selfish purposes. But Dr. Sinja is on to him, and Jack’s life comes unglued after a magical Bodhi tree mysteriously appears in his backyard. With every word Jack speaks, a leaf falls from the tree and he realizes that when the last leaf falls, both he and the tree are toast. Words have never failed Jack McCall, but now he’s got to stop talking and conjure up some outrageous ways to communicate or he’s a goner.','He only has 1000 words left to discover what matters the most.',40000000,22044277,13.119133,6,373,91,'2012-03-07','en','/9w1SJ4yVDpvojPGT1NWO3PYzKDQ.jpg',3.138744444536795,3,'2026-09-10',2,NULL,NULL),(72359,'皮尔普斯一家','Peeples','克雷格·罗宾逊饰演的韦德·沃克是一个普通的蓝领工人，他爱上了凯丽·华盛顿扮演的葛瑞丝并打算向她求婚，为了得到心爱的姑娘他不得不与她的家庭交手，并在与这一家人的相处中闹出了各种令人捧腹的笑料。',NULL,15,0,5.112809,5.6,26,95,'2013-05-09','en','/6ZBSsBfxKK5GdTzz1BOKGl4BnzJ.jpg',2.555843113488989,3,'2026-09-10',2,NULL,NULL),(72387,'暂告安全','Safe','莱特是一个不守规矩、只认死理的前纽约警察。一天，他在地铁站里看到一群持械的黑帮成员在围剿一个12岁的华裔女孩。他心里的正义感油然而生，遂出手教育了这群黑帮，并把小女孩保护了起来。  可不料，这只是一连串事件的开端。更多的黑帮--香港的三合会成员、俄罗斯混混以及政客派来的杀手和警局里的恶棍源源不断地找上门来。无奈之下，莱特只得带着这个小姑娘在纽约的版图上开始了东躲西藏的亡命生涯。这个华裔女孩既不是名流后代，身上也没有被藏入钻石，为什么会成为黑帮的热门眼中钉呢？打听之下，莱特才知道这个女孩有着过目不忘的本领，她记下来了一连串的数字，而这些数字经过解密后是一个密码。  知道了事件原委的莱特，此时更加不能让这个女孩落入黑帮的手中了--不仅是正义感使然，更重要的是在和女孩的相处中，莱特体会到了一种责任感……','She has the code. He is the key.',30000000,40346186,31.92695,6.3,799,94,'2012-04-16','en','/joM19NFUyYoTv27TI7bX51ur0LC.jpg',3.3876622925830326,3,'2026-09-10',2,NULL,NULL),(72431,'红色机尾','Red Tails','第二次世界大战正进行的如火如荼，此时，一个完全由黑人飞行员组成的小分队，正在接受塔斯克基主办的一次带有实验性的训练计划，而且他们还会以一种无比英勇的姿态，同时展开两场声势浩大的战斗，其中之一是对抗那些来自于海外的侵略者，另一场则是要努力地消除存在于祖国和军队内部让人挫败的偏见与歧视。由于长久以来的种族问题，白人战友只接受为期3个月的密集训练就可以被送到战场上，虽然是军队里的王牌飞行员，马丁·朱利安（内特·派帕克饰）和他的黑人队友们却始终只能驻守在基地里，做一些后勤方面的工作。由于他们整日无所事事，反倒有着大把的时间可以提升自己的飞行技能。直到有一天，他们终于等到了期盼已久的转折。发生在欧洲的战争没有任何结束的苗头，联军的损失与伤亡也是想象不到的惨重，而五角大楼已经调配不出军队进行支援，就在这时，他们想到了这些被无情忽视掉的战斗飞行员，终于给他们发出了奔赴战场的调令。这支黑人飞行队一步入战场，就肩负上了一个需要在大白天为友军的轰炸机护航的重担，由于这项任务实在是太危险了，之前曾经遭受到了英国皇家空军的拒绝，而白人飞行员需要做的则是保存实力以便继续后援工作。抱着必死的决心，马丁带领着其他无所畏惧的飞行员直接冲向了蔚蓝的天际，并在对抗敌人的时候做出了一系列勇敢的努力和放手一搏','High-Octane Action and Daring Dogfights!',58000000,50365377,12.29603,5.9,178,125,'2012-01-19','en','/qKMF5cwU4qz6F1J4YXgJegPFQaY.jpg',2.9757702057307522,3,'2026-09-10',2,NULL,NULL),(72545,'地心历险记2：神秘岛','Journey 2: The Mysterious Island','乔什·哈彻森饰演的男主角肖恩接收到来自神秘岛屿的求救信号，这个信号与他失踪的祖父息息相关。肖恩决定去神秘岛一探究竟，但母亲的男友（巨石·强森饰演）竭力阻止他，因为传说神秘岛有许多未知的危险。肖恩一意孤行，为了保证他的安全，母亲的男友只好陪同他前往，与他们一起去的还有飞行员父女。  　　在经历重重困难后，肖恩祖孙终于重逢，然而这份高兴没持续多久，岛上的五个人就面临着更大的危机：神秘岛火山喷发地震袭来，岛屿岌岌可危，他们必须赶在岛屿沉没于大海前逃出去。','Believe the Impossible. Discover the Incredible.',79000000,355692760,40.723459,5.8,1030,94,'2012-01-19','en','/d91RYzuuaDDDkbHQG2XBgK2nFhC.jpg',3.3784991114442797,3,'2026-09-10',2,NULL,NULL),(72559,'特种部队Ⅱ：全面反击','G.I. Joe: Retaliation','在公爵（钱宁·塔图姆 Channing Tatum 饰）的率领下，特种部队给恐怖组织“眼镜蛇”以沉重的打击。虽然眼镜蛇指挥官等中心人物落网，但白幽灵（李秉宪 饰）等组织骨干依然逍遥法外，时刻准备向特种部队和全世界展开反扑。在干净利落解决某中东国家的核危机后，特种部队突然遭 到来自美国政府的惨烈打击，公爵等队员英勇殉职，只有拦路虎（道恩·强森 Dwayne Johnson 饰）、杰伊小姐（阿德琳妮·帕里奇 Adrianne Palicki 饰）和弗林（D·J·科特罗纳 D.J. Cotrona 饰）三人侥幸逃生。原来眼镜蛇早已渗透到美国高层，他们藉此抹黑特种部队，栽赃重要成员之一的蛇眼，其目的是为了找出并解救被囚禁的指挥官。名义上已经“死亡”的拦路虎三人，必须想尽各种办法阻止眼镜蛇的邪恶计划，为死去的战友和特种部队正名……',NULL,130000000,371876278,59.325589,5.4,3025,110,'2013-03-26','en','/9l0T0d9CeTqQdljnl9Ih6JQ3j0n.jpg',3.537434651004397,3,'2026-09-10',2,NULL,NULL),(72570,'誓约','The Vow','Leo(查宁·塔图姆 饰)和Paige(瑞秋·麦克亚当斯 饰)是一对恩爱的小夫妻。在一个寒冷的冬天，一场车祸使Paige失去了记忆，醒来的她忘记了她曾经深爱的Leo。同样深爱Paige的Leo不愿意放弃，努力通过各种方法试图恢复Paige的记忆。他先是说服Paige的父母，让她继续和他在一起生活。同时，他通过各种细节来帮助她回忆。他们的第一次见面，他们最爱去的一家餐馆，还有她的艺术创作。然而失忆了的Paige也失去了创作的灵感，准备像以前一样回去学习法律。更糟糕的是，Paige似乎也准备回到前男友Jeremy(斯科特·斯比德曼 饰)的怀抱里。一次次遭遇挫折的Leo似乎看不到一丝让Paige重新爱上他的希望。故事是否也会向悲剧的结局发展？Paige是否又将像她遇见Leo之前一样，放弃艺术去学习她根本不喜欢的法律？在又一个寒冷的冬夜，Leo和Paige的再一次相遇将告诉我们答案。影片改编自真实的故事。',NULL,30000000,196114570,26.780961,7,1293,104,'2012-02-05','en','/epwSxxkk0ym01tTakrhI29fxqiI.jpg',3.6212075598958666,3,'2026-09-10',2,NULL,NULL),(72571,'灵动：鬼影实录3','Paranormal Activity 3','1988，还是孩童的凯蒂（科萝尔·森格瑞 Chloe Csengery 饰）和克莉丝蒂（杰茜卡·泰勒·布朗 Jessica Tyler Brown 饰）随着妈妈朱莉（劳伦·彼特纳 Lauren Bittner 饰）以及继父丹尼尔（克里斯托弗·尼古拉斯·史密斯 Christopher Nicholas Smith 饰）搬入一幢全新的大房子居住。丹尼尔是摄影工作者，平时经常拿着摄像机拍来拍去。某晚他拍摄和朱莉的私生活，却在画面中看到奇怪的影响。他直觉房子内似乎藏着不为人知的秘密，于是在房间的各个角落假设摄像机日夜拍摄。  　　镜头前，先是看到克莉丝蒂与看不见的“朋友”托比聊天，随后的日子里，各种恐怖离奇的事件相继发生。困扰克莉丝蒂与凯蒂多年的噩梦由此展开……','It Runs In The Family',5000000,205703818,29.15813,5.9,669,83,'2011-10-19','en','/y4qkITBCTQmMODfZVVIiZiF6t8r.jpg',3.2828877798463236,3,'2026-09-10',2,NULL,NULL),(72710,'宿主','The Host','未来的某个时间，神秘外星人大举入侵地球。没有毁灭，没有战火，他们以特殊的方式占据人类的身体，将这颗早已被人类文明折磨得疲惫不堪的地球改造成一片看似和平幸福的乐土。然而，依旧有少数人不愿放弃自主的人格和丰富的情感与回忆，他们为此做着最后的抵抗。美丽女孩梅兰妮·斯特德抵死顽抗，仍不免被侵蚀的命运。新生的漫游者占据了她的身体，然而梅兰妮的意识并未就此消失。漫游者按照探索者的命令搜索梅兰妮的记忆，得知她的弟弟吉米以及深爱的男孩杰莱德·霍华的存在。在这一过程中，原本对立的漫游者和梅兰妮渐渐变得融洽，突如其来的事件迫使她们携手奔上拯救所爱之人的征途……','You will be one of us',44000000,63327201,42.933027,6,1817,125,'2013-03-22','en','/qfO3TDO7OixiIuCGrUpHjuSK8vU.jpg',3.5375319874021947,3,'2026-09-10',2,NULL,NULL),(72766,'Newlyweds','Newlyweds','A newlywed couple\'s honeymoon is upended by the arrivals of their respective sisters.','A newlywed couple\'s honeymoon is upended by the arrivals of their respective sisters.',9000,0,0.642552,5.9,5,85,'2011-12-26','en','/t09NlDBh0z1HEhPu6Xs5c4hRk64.jpg',2.2238909033653464,3,'2026-09-10',2,NULL,NULL),(72913,'Amigo','Amigo','Rafael, a village mayor caught in the murderous crossfire of the Philippine-American War. When U.S. troops occupy his village, Rafael comes under pressure from a tough-as-nails officer to help the Americans in their hunt for Filipino guerilla fighters. But Rafael\'s brother is the head of the local guerillas, and considers anyone who cooperates with the Americans to be a traitor. Rafael quickly finds himself forced to make the impossible, potentially deadly decisions faced by ordinary civilians in an occupied country.',NULL,1200000,0,0.193172,6,2,128,'2010-07-14','en','/fKSc6ZB8DOdwxtSBPjv7NjGMWBr.jpg',2.0726917555955975,3,'2026-09-10',2,NULL,NULL),(72914,'Fat, Sick & Nearly Dead','Fat, Sick & Nearly Dead','100 pounds overweight, loaded up on steroids and suffering from a debilitating autoimmune disease, Joe Cross is at the end of his rope and the end of his hope. In the mirror he saw a 310lb man whose gut was bigger than a beach ball and a path laid out before him that wouldn\'t end well— with one foot already in the grave, the other wasn\'t far behind. FAT, SICK &amp; NEARLY DEAD is an inspiring film that chronicles Joe\'s personal mission to regain his health.','FAT, SICK & NEARLY DEAD is an inspiring film that chronicles Joe\'s personal mission to regain his health.',0,0,0.545825,7.1,47,97,'2010-04-16','en','/yKXRwMValA4ZbCaC68ANO24ALcY.jpg',2.693603970317266,3,'2026-09-10',2,NULL,NULL),(72976,'林肯','Lincoln','本片是一部深刻揭示历史时刻的剧情片，聚焦于这位第十六任总统任期最后数月间的动荡岁月。在因战争而分裂、变革之风强劲席卷的国家中，林肯采取了一系列旨在终结战争、统一国家并废除奴隶制的行动。凭借崇高的道德勇气与必胜的坚定决心，他在此关键时刻做出的抉择将改变未来世代的命运。','With the moral courage and fierce determination to succeed, his choices will change the fate of generations to come.',65000000,275293450,36.307296,6.7,1429,149,'2012-11-09','en','/ceFYpQVIwQicAgImn9sVs7XdaCs.jpg',3.611103272674938,3,'2026-09-10',2,NULL,NULL),(73191,'胡桃夹子','The Nutcracker','在平安夜，一个叫玛丽的小女孩睡着了，梦见自己进入了一个奇妙的世界，在这个世界里，她的玩具变得比生命还大。她遇到了胡桃夹子王子谁带她去他的王国，并保护她从老鼠王。','The joy of the New York City Ballet in an exciting family holiday motion picture.',19000000,2119994,0.068228,5.6,5,93,'1993-11-24','en','/mKGGzL6o27cOurOO0gCUopDCxts.jpg',2.2219654791618884,3,'2026-09-10',2,NULL,NULL),(73247,'Heartbeeps','Heartbeeps','Heartbeeps stars Andy Kaufman and Bernadette Peters as domestic robots who fall in love and run off together.','Meet a modern nuclear family unlike any other.',10000000,2154696,0.518056,3.8,6,79,'1981-12-18','en','/zxK1jyN8apEUyYerMLStaHIM2z8.jpg',2.2518468248775947,3,'2026-09-10',2,NULL,NULL),(73511,'The Californians','The Californians','When real estate mogul Gavin Ransom (Noah Wyle) announces his plan to cover California\'s northern coast with scores of mini-mansions, his environmentalist sister, Olive (Ileana Douglas), launches a protest to stop him. But there\'s trouble ahead when Gavin begins falling for the pretty folk singer (Kate Mara) who\'s helping Olive\'s cause. This clever West Coast satire from writer-director Jonathan Parker is a twist on Henry James\'s The Bostonians.','All is fair in love and real estate.',0,0,0.218736,4,1,91,'2005-10-21','en','/94w3CM4V8AG9OEgtPQSwDfFd6Vw.jpg',1.9839281461860065,3,'2026-09-10',2,NULL,NULL),(73532,'勒阿弗尔','Le Havre','在这部阿基·考里斯马基执导的温情喜剧故事中，命运将年轻的非洲难民伊德里萨抛到了马塞尔·马克斯的跟前。马塞尔是一位在法国港口城市勒阿弗尔以擦鞋为生的善良老波西米亚人。凭借与生俱来的乐观精神和紧密社区的支持，马塞尔挺身对抗执意追捕男孩、企图将其驱逐出境的官员。这部政治童话游走于当代法国的现实与经典法国电影的往昔之间，是一部迷人而冷面滑稽的欢乐之作，也是这位芬兰导演最优秀的作品之一。[标准收藏]',NULL,3850000,0,10.787322,6.8,97,93,'2011-05-17','fr','/lx9jiNuoC13IqKg6pYNgQmBqgKo.jpg',2.878269339747523,3,'2026-09-10',2,NULL,NULL),(73567,'杀手乔','Killer Joe','22岁的毒贩克里斯（埃米尔·赫斯基 Emile Hirsch 饰）欠了一屁股债，高利贷主正威胁要追杀他。为保性命，他想到了唯一的办法，就是谋杀亲母阿黛尔以赚取高额保险，并联合了父亲、继母和妹妹多蒂（朱诺·坦普尔 Juno Temple 饰）一起瓜分这笔横财。然而克里斯不愿自己动手，遂瞄准了专业杀手乔（马修·麦康纳 Matthew McConaughey 饰），然而乔只做买卖不做慈善，筹不够钱不会动手。束手无策之时，克里斯只好先把妹妹暂时当“订金”交给乔。本以为万事办妥，只等坐收巨款的克里斯，却没想到事情竟往戏剧化的方向发展而去……','A Totally Deep-Fried Texas Redneck Trailer Park Murder Story.',10000000,3665069,16.436178,6.5,425,102,'2011-09-10','en','/fPISkf617izRUhTYKaSw9bzI2Pf.jpg',3.228852901750304,3,'2026-09-10',2,NULL,NULL),(73873,'雌雄莫辨','Albert Nobbs','影片改编自乔治·摩尔（George Moore）的短篇小说《阿尔伯特·诺伯斯的奇异生活》。  　　Albert Nobbs（格伦·克洛斯 Glenn Close 饰）在一家专门给上层人士提供寻欢作乐的场所的酒店工作。他生性害羞做事谨慎，深得客人和老板的赏识，并坚守着最大的秘密 ——“他”其实是一个女人。他忙碌但乐在其中，甚至悄悄积攒了一大笔钱，却没有人生目标。直到同样是女扮男装的粉刷工 Hubert Page（珍妮·麦克蒂尔 Janet McTeer 饰）来到酒店，Albert的内心第一次有了期盼，他决心走出自己的孤独世界，寻找自己的人生伴侣。于是他选中了酒店最美丽的女仆Helen（米娅·华希科沃斯卡 Mia Wasikowska 饰），可Helen心系新来的杂工。Albert能完成自己的人生目标吗？','A man with a secret. A woman with a dream.',8000000,5634828,7.802245,6.2,132,113,'2011-12-21','en','/knWjzIyRdKyZl9Bogx70bysDkEb.jpg',2.917552154922794,3,'2026-09-10',2,NULL,NULL),(73935,'吸血女郎','Vamps','\"据报道，西格妮·韦佛将参演一部叫做《妖妇》（Vamps）的现代吸血鬼电影，该片集合了浪漫、恐怖和喜剧元素，主角是两个年轻美丽的女吸血鬼，分别由艾丽西娅·西尔维斯通（Alicia Silverstone）和克里斯滕·蕊特（Krysten Ritter）扮演，她们陷入爱河后，必须做出选择，而这将威胁到她们的永生……\r 西格妮·韦佛在片中扮演吸血鬼女王“Ciccerus”，她嗜血如命，两个女孩就是被她变成吸血鬼的。\r 《妖妇》由女导演艾米·海克林（Amy Heckerling）导演，将于4月底开拍。（文章来源/Moviesoon）\"','Dating Sucks',16000000,0,7.251897,4.8,91,93,'2012-08-25','en','/43nUqYJMyqS9HbgD9XoKDvaz6AC.jpg',2.788510440470125,3,'2026-09-10',2,NULL,NULL),(73937,'观鸟大年','The Big Year','“大年（big year）”是观鸟爱好者的一种竞赛，参赛者需要用一整年的时间和精力，记录自己观察到的鸟类种类数量，数量最多者取胜。布莱德、斯图和肯尼就是三位铁杆观鸟爱好者。布莱德（杰克·布莱克 Jack Black 饰）是个一事无成的大龄宅男，因此决定花掉一大笔钱参加“大年”时，他父母觉得他疯了；斯图（史蒂夫·马丁 Steve Martin 饰）是一家大公司的总裁，所以当他决定放下手头百万生意，跑去参加“大年”，他助理觉得他疯了。此一老一少在竞争中相识，很快成为朋友，决定共同对付他们最强的对手——上一届“大年”的得胜者肯尼（欧文·威尔逊 Owen Wilson 饰）。只有鸟友才懂，放弃整整一年的事业和生活意味着什么，三个“鸟友”在大年中奋力竞争，最终要回头面对的还是生活中的问题……  　　影片改编自1998年马克·欧布马克西(Mark Obmascik)的同名小说。','Everyone is searching for something.',41000000,7448385,9.419726,5.6,248,100,'2011-10-13','en','/1akIYzcQkkp08X7GilnbUYqp2EK.jpg',3.0143399379867923,3,'2026-09-10',2,NULL,NULL),(73981,'Ayurveda: Art of Being','Ayurveda: Art of Being','Ayurveda is a science of life and a healing art, where body, mind and spirit are given equal importance. This voyage of thousands of miles across India and abroad takes you on a unique poetic journey, where we encounter remarkable men of medicine or simply a villager who lives in harmony with nature. \"Hope is nature\'s way of enabling us to survive so that we can discover nature itself.\"',NULL,300000,2074000,0.055868,5.5,3,101,'2001-09-20','en','/lgmPBTWogUZBkDMb9zxNz0jyt7.jpg',2.134186201412103,3,'2026-09-10',2,NULL,NULL),(74084,'दिल जो भी कहे','दिल जो भी कहे','During the British rule in India, several Indians were lured by the British to travel to distant Mauritius where they would have a better life. Upon reaching this island, the Indians were enslaved, tortured and made to labor in what is now known as the \"Coolie Ghat\". After the British left India, the Indians in Mauritius decided to continue to live there along with other nationals from different countries.',NULL,0,0,0.122704,0,0,0,'2006-12-07','hi',NULL,1.8340626654031433,3,'2026-09-10',2,NULL,NULL),(74457,'救赎之路','Redemption Road','《救赎之路》讲述两个看似完全不同的男人却走上了同一条道路。',NULL,0,0,0.197264,4.7,6,91,'2011-08-26','en','/w1NBcLgbJAyuuat0UcIpKQnHmJA.jpg',2.253319863937498,3,'2026-09-10',2,NULL,NULL),(74465,'We Bought a Zoo','We Bought a Zoo','Benjamin has lost his wife and, in a bid to start his life over, purchases a large house that has a zoo – welcome news for his daughter, but his son is not happy about it. The zoo is need of renovation and Benjamin sets about the work with the head keeper and the rest of the staff, but, the zoo soon runs into financial trouble.','A True Zoo Story',50000000,120081841,38.629763,6.5,909,124,'2011-12-22','en','/gaJ9beAwLA2oUZHW9cz45Eg27Xj.jpg',3.4660578884665734,3,'2026-09-10',2,NULL,NULL),(74510,'凯文·哈特：嘲笑我的痛苦','Kevin Hart: Laugh at My Pain','喜剧演员凯文哈特回来了，由他主演的“2011嘲笑我的痛苦”巡回演出横扫整个美国，并且总共售出价值超过1500万美元的售票！总计达到90个城市巡演的“嘲笑我的痛苦”是历史上最为成功的喜剧表演之一。哈特在洛杉矶诺基亚剧院为期两天的“嘲笑我的痛苦”现场表演将其提高到了新的高度，超越艾迪墨菲曾经两天表演售票收入达110万美元，同时打破了后者长期保持的非裔美国人表演记录。通过“嘲笑我的痛苦”的表现，这场演出迅速成为了一种国际潮流。跟随最原始，从未有过的无剪辑幕后镜头，回到费城，这个让凯文哈特成为有史以来最为有趣和成功的喜剧演员的起点。零距离的了解凯文哈特，准备再次笑破肚皮吧','Alright! Alright! Alright!',0,0,5.498834,7.7,43,89,'2011-09-09','en','/jk7C5sIDHSGiJjBQz6bmPNP1WOF.jpg',2.694613802957412,3,'2026-09-10',2,NULL,NULL),(74534,'涉外大饭店','The Best Exotic Marigold Hotel','人生已至暮年的七位英国老人辗转前往印度斋浦尔度假。七人中，善解人意的伊芙琳试图在丧夫后独立生活；患心脏疾病的大法官格雷厄姆怀揣着无法启齿的秘密；道格拉斯和琼希望能改善僵化的夫妻关系；老顽童诺曼和老来俏玛琪则时刻期盼着艳遇；至于穆瑞尔，等待手术的她总是显得有几分冷漠刻薄。各怀心事的七人被异域风情广告吸引，不约而同下榻在玛丽戈德饭店。但是真实的饭店并不如广告宣扬的那般舒适，这趟印度心灵之旅也不似预想般尽如人意。在陌生的国度里，众人对余下的人生展开了新的思考，不希望抱憾终身的他们向着皆大欢喜的结局努力着。','Share the journey. Share the laughter.',10000000,136836156,21.258991,6.9,459,124,'2011-11-28','en','/sXi311xpH6ii17RiUzaRKFQDxo4.jpg',3.3050306978010466,3,'2026-09-10',2,NULL,NULL),(74536,'无人之子','The Son of No One','事业小有成绩的警察Jonathan “Milk” White（查宁·塔图姆）被调回他成长的蓝领街区，在那里，他年幼时与朋友Vinnie（崔西·摩根）犯下的谋杀罪面临着被曝光的威胁。他的妻子（凯蒂·霍尔姆斯）与儿子，他的家庭与事业，都可能被这个秘密摧毁。','Serve. Protect. Lie.',15000000,0,7.701186,4.8,92,90,'2011-11-04','en','/koxJAJTPTKzMxKu3vVhPvoZc4w6.jpg',2.79145759710093,3,'2026-09-10',2,NULL,NULL),(74643,'艺术家','The Artist','好莱坞，1927年。乔治·瓦伦丁是默片时代的超级巨星，而有声电影的兴起将为他辉煌的职业生涯敲响丧钟，令他逐渐被人遗忘。对年轻临时演员佩皮·米勒而言，前途却不可限量——巨星之路正等待着她。影片讲述的正是二人命运交汇的故事。[韦恩斯坦公司]','A Breath Of Fresh Vintage Air',15000000,133432856,29.943316,7.3,1049,100,'2011-05-15','en','/aDtMjJf3G0kUb2tBEW6ehG8mpPs.jpg',3.623005199174318,3,'2026-09-10',2,NULL,NULL),(74725,'杀戮名单','Kill List','退伍士兵Jay回到英国后发现生计困难，工作也相当难找。迫于无奈，他和老搭档Gal联手干起了职业杀手的工作。但随后出现的神秘雇佣人、诡异的夜半邪教仪式，让他们惊觉自己被利用了……  　　该片被评为史上“最奇怪”、“最恐怖”和“最出乎意料”的英国恐怖片。尽管电影中交错穿插着家庭剧、恐怖片和死党喜剧三种类型，但是导演完美的融合了这三种不同的类型，尤其是在塑造杀手兄弟的时候融入了仿佛与生俱来的搞笑手法，令人叹为观止，其经典程度并不亚于昆丁在《低俗小说》中所塑造的兄弟形象。电影开场的基调会让观众误认为是一部后伊拉克时代的黑帮警匪片，随着故事的发展，电影整体风格就正式转为恐怖片。导演喜欢70年代的恐怖片，原因是“电影是当时那个年代的写照。”因此他想把年代感带入到自己的影片中去，塑造一个受到许多现实的压力而负债累累，无法翻身的平凡家庭，唯一的救赎就是封闭自己。  　　《杀戮名单》在英国独立电影奖上斩获不少提名，更被誉为二十年来英国最好的恐怖片。',NULL,500000,171760,12.203041,6,210,95,'2011-09-02','en','/qwT2I3ons0oD58jIppKmd4qLtvB.jpg',3.0162380079664914,3,'2026-09-10',2,NULL,NULL),(74777,'永久失踪','Absentia','片名是个拉丁单词，意思是“永久失踪”，这是个专门的词汇，如果一个人失踪了一段时间之后，在法律上就认定为死亡了。Tricia的丈夫失踪7年了，但她始终没有放弃希望，在妹妹的帮助下，她终于接受丈夫死亡的事实并重新开始生活。但这个时候，她们发现家中和附近不详的隧道里发生了很多诡异的事件，也许Tricia的丈夫遇到了比死还可怕的事……','There are fates worse than death.',70000,0,6.328665,5.8,121,92,'2011-03-03','en','/imUIPWoe0Yma5UhZVl6bqX5lF.jpg',2.8780590659485057,3,'2026-09-10',2,NULL,NULL),(75033,'温妮','Winnie Mandela','讲述南非第一任黑人总统曼德拉前妻温妮的故事：纳尔逊·曼德拉曾在狱中度过27个春秋，他的妻子温妮为了帮他出狱四处奔走活动，并几次入狱。温妮也是一位反对种族隔离的斗士，其战斗、忠贞、母爱的形象赢得了广大黑人的爱戴，曾享有“黑人母亲”的尊称。不过随着个人威信的提升，温妮个性中的阴暗一面逐渐暴露在公众面前，1991年她因涉嫌包庇一位虐杀14岁少年的前保镖被判处6年监禁徒刑，2003年她又因盗窃和欺诈等共计68项罪名而被判入狱5年。1996年曼德拉与她离婚。','Her courage inspired a nation.',15000000,0,1.897761,5.2,5,107,'2011-09-16','en','/42VAbyctqy6VmwlHjQB73E2pnFB.jpg',2.225326418994134,3,'2026-09-10',2,NULL,NULL),(75174,'人狼大战','The Grey','冰天雪地极度严寒的阿拉斯加荒原，来自各地的杀人犯等非法之徒加入某石油公司，在这个蛮荒之地辛苦作业。约翰·奥特维（连姆·尼森 Liam Neeson 饰）是这家公司的守护猎人，专门负责猎杀野狼以使工人灭受残害。他日夜思念妻子，于生早已了无所望。某天，他和工人们乘坐的飞机遭受空难，当他再次醒来时，发现自己正置身在暴雪纷飞的冰原。与之一同侥幸逃生的汉德里克（Dallas Roberts 饰）、迪亚兹（Frank Grillo 饰）、博克（Nonso Anozie 饰）、塔尔盖特（Dermot Mulroney 饰）、弗兰纳瑞（Joe Anderson 饰）以及赫南德兹（Ben Bray 饰）等6人。虽然暂时逃生，但在救援迟迟不曾到来的危机时刻，他们的生命依然受到威胁。  　　性格各异的7名幸存者，即将踏上似乎永无止境的求生之路……','Live or Die on This Day',25000000,77278331,48.552871,6.4,1451,117,'2012-01-26','en','/HFGhIYN6BITIgQlM5mQFnaZSQy.jpg',3.583071131794928,3,'2026-09-10',2,NULL,NULL),(75531,'伟大的苏珊','Isn\'t She Great','An unsuccessful over-the-top actress becomes a successful over-the-top authoress in this biography of Jacqueline Susann, the famed writer of \"The Valley Of The Dolls\" and other trashy novels. Facing a failing career, Susann meets a successful promoter who becomes her husband. After several failures to place her in commercials and a TV quiz show, he hits upon the idea for her to become a writer. In the pre-60\'s, her books were looked upon as trash and non-printable. But then the sexual revolution hit and an audience was born for her books. The story shows the hidden behind the scenes story of Susan\'s life, including her autistic son and her continuing bout with cancer that she hid up to her death','Talent Isn\'t Everything...',36000000,3003296,1.068453,4.6,14,95,'2000-01-28','de','/ikmulTGVfW6jYYNz4iO5yoN7dla.jpg',2.4157116031953803,3,'2026-09-10',2,NULL,NULL),(75612,'遗落战境','Oblivion','Jack Harper is one of the last few drone repairmen stationed on Earth.  Part of a massive operation to extract vital resources after decades of war with a terrifying threat known as the Scavs, Jack’s mission is nearly complete.  His existence is brought crashing down when he rescues a beautiful  stranger from a downed spacecraft.  Her arrival triggers a chain of events that  forces him to question everything he knows and puts the fate of humanity in his hands.','Earth is a memory worth fighting for',120000000,286168572,67.698004,6.4,4800,124,'2013-04-10','en','/bYLM3GpNUZnoFElPXp1zlhDPdtv.jpg',3.903941314542407,3,'2026-09-10',2,NULL,NULL),(75638,'红灯','Red Lights','心理学博士玛格丽特·麦瑟森（西格妮·韦弗 Sigourney Weaver 饰）擅长用科学的手段分析各种难以解释的超自然现象，对于所谓的超能力更是充满质疑。在助手汤姆·巴克利（希里安·墨菲 Cillian Murphy 饰）的协助下，她们深入乡间，戳穿了一个又一个“灵媒”的骗局。与此同时，曾经在20世纪60~70年代引起轰动的超能力者西蒙·希尔沃（罗伯特·德尼罗 Robert De Niro 饰）强势复出，引起新一波的热潮。玛格丽特曾让西蒙的弟子的原形毕露，可她始终回避与西蒙的正面对决。一些人的推波助澜似乎要将他们的对决变成可能，但玛格丽特却突然去世。悲愤交加的汤姆决定独自挑战西蒙，他不知道自己即将面对的是什么……','How much do you want to believe?',14000000,13551174,22.748174,6,376,119,'2012-03-02','en','/hdI8eIkWcKrPyfHiRJXjYk4nlTd.jpg',3.1624132548184956,3,'2026-09-10',2,NULL,NULL),(75656,'惊天魔盗团','Now You See Me','不夜赌城拉斯维加斯，豪华的表演大厅内正在进行一场前所未有的魔术表演，由丹尼尔·阿特拉斯（Jesse Eisenberg）、亨莉·里维斯（Isla Fisher）、杰克·怀尔德（Dave Franco）和梅里特·麦克金尼（Woody Harrelson）四位魔术师组成的“四骑士”配合天衣无缝，在众目睽睽之下偷来了某法国银行金库内350万欧元纸币，此举在现场至全世界引起轰动。FBI探员罗德（Mark Ruffalo）和国际刑警埃尔玛·德雷（Mélanie Laurent）奉命对四人展开调查，却一无所获。无奈之下，他们只得求助于极具名气的揭露魔术师布莱德利（Morgan Freeman）。  魔术师、盗贼、FBI探员，光影交错下最精彩的较量，连番上演……','4 amazing magicians. 3 impossible heists. 1 billion dollars. This is no illusion.',75000000,117698894,71.124686,7.3,5487,115,'2013-05-29','en','/tWsNYbrqy1p1w6K9zRk0mSchztT.jpg',4.180422161076553,3,'2026-09-10',2,NULL,NULL),(75674,'勇者行动','Act of Valor','洛克，即将成为人父，正准备与大家分享这份喜悦。却突然接到上级命令，带领自己的小队去营救被绑架的CIA人质。虽然与家人才团聚没有多久，但是时刻为祖国效命是海豹突击队员的职责。洛克所率领的小队很快集结，按照计划前往目的地营救人质。不过，在营救过程中，洛克却发现了恐怖分子布下的天罗地网，一场惊天阴谋正在酝酿实施中。如果不能加以阻止，美国本土很可能会遭受严重的恐怖袭击。因此，海豹突击小队，一刻都没有停息，在全球展开了一场大围剿……本片被认为是真人版的《战地3》，片方在全球多个地方取景，根据真实的事件改编。','The only easy day was yesterday',12000000,81272766,21.958055,6.3,417,110,'2012-02-24','en','/dTLkclyA9yPiADPDLGSrFfKZ5wa.jpg',3.2149933653945615,3,'2026-09-10',2,NULL,NULL),(75780,'侠探杰克','Jack Reacher','六发子弹，五名死者，神秘枪手在闹市区制造了一起惨案让整个城市都陷入魁了恐慌。所有的证据都指向了前军队狙击手詹姆斯·巴尔。但他坚持自己的清白并要求把老相识 杰克·理查尔 找来，两人曾同在军队中服役。随着杰克调查的深入，他发现了更大的谜团，炮制这场惨案的真凶似乎另有其人，而别有用心的幕后黑手抓走了巴尔 ，只留下杰克一人探明真相。六发子弹中有一发漏空的子弹是杀手故意放空的。为了了解狙击手的工作，杰克特意来到了狙击手的训练营找到了一个叫做萨缪尔·卡什 的教练。在卡什和巴尔妹妹以及律师的帮助下，杰克渐渐走进了事件的中心位置，一个关于苏联改造营和俄罗斯黑帮的秘密也慢慢浮出水面……','The Law Has Limits. He Does Not.',60000000,218340595,56.868399,6.3,2998,130,'2012-12-20','en','/uQBbjrLVsUibWxNDGA4Czzo8lwz.jpg',3.7473976121523838,3,'2026-09-10',2,NULL,NULL),(75861,'To Write Love on Her Arms','To Write Love on Her Arms','The story follows 19-year-old Renee who has always loved fairy tales: the idea of a princess, a hero and a happily ever after. But Renee’s life is that of a darker tale: she’s a young woman battling addiction, depression and self-injury. In a creative blend of artistic fantasy balanced with harsh reality, the movie follows Renee on her courageous journey towards recovery.','Based on the True Story that started a Global Movement.',3400000,0,6.723057,6.8,47,118,'2015-03-13','en','/naQRUuVa4j0uIrgxACIeFlwgKSn.jpg',2.702258948581893,3,'2026-09-10',2,NULL,NULL),(75900,'我与梦露的一周','My Week with Marilyn','刚刚踏入社会的英国青年科林·克拉克  不顾家庭反对，将满腔热情投入自己热爱的电影事业之中，希望能闯出一番天地。勤奋的他得到的第一个跟组机会，竟是担任他的偶像劳伦斯·奥利弗  导演并主演的新片《游龙戏凤》剧组的第三助理导演。这部电影邀请了当时红遍全球的美国影星玛丽莲·梦露  主演，而科林的工作便是统筹剧组的各项杂务。开拍之后，梦露与劳伦斯·奥利弗之间因表演方法不同而产生了激烈冲突，致使剧组进度远远落后预期。科林负责于当中调停，他开始与梦露频繁接触。不知不觉间，科林发现自己已为梦露的魅力所深深吸引……  米歇尔·威廉姆斯凭借本片荣获2012年金球奖最佳女主角（喜剧/音乐类）。',NULL,6400000,35057696,21.006078,6.6,406,99,'2011-10-17','en','/j3jlQXXR17oq6UVEgAoEeYR8xWr.jpg',3.2388912618683343,3,'2026-09-10',2,NULL,NULL),(75986,'情书','Love Letters','A story of love and obsession. A young radio personality who, after her mother dies, discovers she had been having a love affair for 15 years. Now she finds herself recreating her mother\'s romance by getting involved with a married man.','Sometimes It\'s Right To Do the Wrong Thing.',550000,0,0.001586,4.6,4,98,'1983-04-01','en','/pu6BqPRbEaIeKs6YmmSEFGKDiBj.jpg',2.180792782126167,3,'2026-09-10',2,NULL,NULL),(76025,'羞耻','Shame','布兰顿（迈克尔·法斯宾德 Michael Fassbender 饰）是纽约衣着光鲜的白领。他酷爱成人电影，习惯自慰，并寻花问柳。不过，他与妹妹希西（凯瑞•穆里根 Carey Mulligan 饰）的关系却忽冷忽热。希西总给他电话留言，他却总是避之不及。然而，当希西搬来与他同住 ，他又表现出特别的关心。布兰顿和上司一同去听希西的演唱，结果上司被她的风姿所打动，而他却沉浸在她的歌声中潸然泪下。在妹妹面前，布兰顿表现的无所谓，而上司却大胆追求。这令布兰顿极为羞耻。某日，上司在与家人视频通话后，开始斥责布兰顿往电脑硬盘塞满了成人电影，称之为耻辱。气急败坏的布兰顿却对妹妹发火，令她十分伤心。布兰顿曾约会公司的黑人女秘书，却发现自己真正难以割舍的不是性瘾，而是心中惦念的兄妹之情……',NULL,6500000,17693675,40.688426,7,875,100,'2011-10-02','en','/12bJQuVNRIb5S54v3KXTJsZMxdZ.jpg',3.543251097913226,3,'2026-09-10',2,NULL,NULL),(76163,'敢死队2','The Expendables 2','再次经历了一番炮火密集的血雨腥风，巴尼（西尔维斯特·史泰龙 Sylvester Stallone 饰）、圣诞（杰森·斯坦森 Jason Statham饰）、贡纳（杜夫·龙格尔 Dolph Lundgren 饰）、比利（利亚姆·海姆斯沃斯 Liam Hemsworth 饰）、收费公路（兰迪·库卓 Randy Couture 饰）和凯撒（泰瑞·克鲁斯 Terry Crews 饰）这几个敢死队的铁哥们正享受大战之后的难得惬意。可是好景不长，某晚教堂（布鲁斯·威利斯 Bruce Willis 饰）找上门来，迫令他前往阿尔巴尼亚噶扎克山区找一架被击落飞机上的保险箱，并确保箱子不会落入敌人之手，教堂还委派麦琪·张（余男 饰）与这群硬汉同行。看似简单的任务实则充满凶险，比利被对手残忍杀害。这已不再是一项任务，而是一场关乎战士们友情与荣誉的战争……','Back for War.',100000000,312573423,53.732892,6.1,2896,103,'2012-08-08','en','/e28zlsaV998tNCaARf96YK8CLY1.jpg',3.684470922470065,3,'2026-09-10',2,NULL,NULL),(76170,'金刚狼2','The Wolverine','位于加拿大的深山老林，背负着永生之苦的“金刚狼”罗根隐居于此。在一次与猎人的冲突中，他得到日本女子雪绪的帮助。雪绪是罗根二战期间的旧相识矢志田派来的下属，似乎不久于人世的老友渴望死去之间再见罗根一面。跨越重洋的罗根终于见到在虚弱的矢志田，对方希望他能够保护自己的孙女真理子。随着老人谢世，葬礼上突然战火点燃。罗根在雪绪的帮助下拼死救出真理子，而矢志田的儿子信玄似乎另有所图。逃亡途中，罗根意外发现他丧失了自愈的能力，金刚狼最大的危机降临。','When he\'s most vulnerable, he\'s most dangerous.',120000000,415440673,15.953444,6.3,4053,126,'2013-07-23','en','/t2wVAcoRlKvEIVSbiYDb8d0QqqS.jpg',3.7218181655504288,3,'2026-09-10',2,NULL,NULL),(76203,'为奴十二年','12 Years a Slave','In the pre-Civil War United States, Solomon Northup, a free black man from upstate New York, is abducted and sold into slavery. Facing cruelty as well as unexpected kindnesses Solomon struggles not only to stay alive, but to retain his dignity. In the twelfth year of his unforgettable odyssey, Solomon’s chance meeting with a Canadian abolitionist will forever alter his life.','The extraordinary true story of Solomon Northup',20000000,187000000,95.9229,7.9,3674,134,'2013-10-18','en','/xdANQijuNrJaw1HA61rDccME4Tm.jpg',4.283012367485178,3,'2026-09-10',2,NULL,NULL),(76285,'波西·杰克逊与魔兽之海','Percy Jackson: Sea of Monsters','波西·杰克逊在混血人集中营平静的度过七年级后，忽然日子就变的纷乱了起来，原本和同学间的躲避球竞赛，阴错阳差的变成了一场死亡游戏，丑陋的食人族巨无霸也跟着搅和其中，波西无意中发现，他们的家园和族人正遭遇空前的灾难，必须找到“金羊毛”，才能拯救众人，为了解除灾难，波西奋不顾身带着伙伴们共同踏上冒险的旅程，他们要到魔兽之海完成任务，才能取得金羊毛并拯救面临毁灭的混血人集中营，在这趟危机重重的冒险之旅中，他们将会遇到哪些惊人的意外难关？他们真的能够顺利的突破困难，并且让所有族人和希腊众神们幸免于难吗？','Where There Are Gods, There Are Monsters.',90000000,174578751,40.262261,5.9,1648,106,'2013-08-07','en','/2lHzViAt5DbkLDq5EFngnn3Kb6Z.jpg',3.4901280178289724,3,'2026-09-10',2,NULL,NULL),(76338,'雷神2：黑暗世界','Thor: The Dark World','Thor fights to restore order across the cosmos… but an ancient race led by the vengeful Malekith returns to plunge the universe back into darkness. Faced with an enemy that even Odin and Asgard cannot withstand, Thor must embark on his most perilous and personal journey yet, one that will reunite him with Jane Foster and force him to sacrifice everything to save us all.','Delve into the darkness',170000000,644571402,99.499595,6.8,4755,112,'2013-10-29','en','/wp6OxE4poJ4G7c0U2ZIXasTSMR7.jpg',4.0785031978791615,3,'2026-09-10',2,NULL,NULL),(76341,'疯狂的麦克斯4：狂暴之路','Mad Max: Fury Road','在我们星球最偏远的角落，一片荒芜的沙漠景观中，人性已然破碎，人人都在为生存必需品而战。两位反抗者或许能恢复秩序——一个是麦克斯，他行动果决、沉默寡言，在经历混乱失去妻儿后寻求内心平静；另一个是弗瑞奥萨，她坚信唯有穿越沙漠重返童年故土，才能找到生存之路。','What a Lovely Day.',150000000,378858340,434.278564,7.2,9427,120,'2015-05-13','en','/ulcAi4dKpAjHwYGS08vNyx9H6I9.jpg',5.115788495057176,3,'2026-09-10',2,NULL,NULL),(76349,'辛亥革命','辛亥革命','19世纪末20世纪初，清王朝三百年江山气数将近，内忧外患，时局动荡，正是乱世之际，英雄辈出，中华民族面临着重大的历史变革。以孙中山（赵文瑄 饰）为首的仁人志士意识到只有民主共和才能救中国，他们组成一个个革命政党，旨在推翻满清政府，建立人民当家作主的民主国家。 　　在这一过程中，无数革命者流血牺牲，但是更多的革命家站出来与落后的封建体制作斗争，终于在武昌打响了辛亥革命的第一枪。在此期间，黄兴（成龙 饰）、黎元洪（姜武 饰）、隆裕太后（陈冲 饰）、袁世凯（孙淳 饰）、汪精卫（余少群 饰）、宋教仁（邢桂栋 饰）、秋瑾（宁静 饰）等各方人物你方唱罢我登场，谱写了中国近代史上最为辉煌的篇章……','Fall of the Last Empire',30000000,108348,4.065212,5,41,125,'2011-07-03','zh','/2RrL39rXUwcXvlnYcomsNV2zE8p.jpg',2.6369067888455064,3,'2026-09-10',2,NULL,NULL),(76487,'心中的恶魔','The Devil Inside','1989年的寂静深夜，南哈特福特三名神职人员遭到屠杀。行凶者名叫玛莉娅·罗西（苏珊·克萝蕾 Suzan Crowley 饰），事后被诊断体内藏有七重人格。在此后的岁月里，她被带往意大利驱魔。时隔20年，玛莉娅的女儿伊莎贝拉·罗西（费尔南达·安德拉德 Fernanda Andrade 饰）决定拍摄一部关于母亲的纪录片，她启程前往罗马，见到了久违的母亲，而玛莉娅所说的话令她颇为震惊。为了探明母亲的病因，她在当地找到了两位瞒着教会偷偷进行驱魔的教士年轻驱魔师（赛门·克特曼 Simon Quarterman 与 伊凡·海慕特 Evan Helmuth 饰）。在他们的努力下，玛莉娅体内的魔鬼们渐渐显现出来……  　　本片荣获2012年BMI电影与电视奖最佳电影配乐奖。','No soul is safe.',1000000,101758490,13.152822,4.6,262,83,'2012-01-06','en','/mtyFRIRBmrCE2XKU5EnEK8dtu2X.jpg',2.953764173466037,3,'2026-09-10',2,NULL,NULL),(76489,'三个臭皮匠','The Three Stooges','影片由三个小段落组成，每一个小段落自成一章，之间有着微弱的联系。  　　段落一，讲述的是科雷、摩尔、拉里三个婴儿被装载一个旅行包内丢到了孤儿院的门口，一个修女看到了这个包裹，便上前查看。不了却被科雷用“插眼二指禅”戳了个人仰马翻。从此之后，这三个小朋友就在孤儿院里生活了下来。  　　段落二，讲述的是这三个人长到了40来岁，变成了三个臭皮匠。他们走到了社会上，在社会上闹出的各种各样的喜剧和笑话。  　　段落三，讲述的是三个臭皮匠自娱自乐的故事。只有他们三个人，互相插科打诨，制造喜剧。','Just Say Moe.',30000000,54819301,14.585968,4.9,140,92,'2012-04-13','en','/b0nNQCL90RGTwjxLEFsFFLQZKNe.jpg',2.8830636625286905,3,'2026-09-10',2,NULL,NULL),(76492,'精灵旅社','Hotel Transylvania','在阴森恐怖令人谈之色变的幽灵森林深处，耸立着一幢巍峨庄严的古堡。这里的主人正是声名显赫的吸血鬼德古拉（亚当·桑德勒 Adam Sandler 配音）。与传说中不同，德古拉是一个无比温柔的好爸爸，他独自抚养爱女梅菲丝（赛琳娜·戈麦斯 Selena Gomez 配音），为了保护女儿免遭人类的戕害，而特意修建了这座名为尖叫旅社的城堡，普通人类绝对无法接近这里。每年梅菲丝生日之际，科学怪人、狼人、木乃伊、隐形人等怪物都从世界各地赶来为小女孩庆生。在梅菲丝118岁生日之际，她渴望见识外面的世界，早有准备的德古拉设下骗局，却意外将人类少年乔纳森（安迪·萨姆伯格 Andy Samberg 配音）引入古堡。  　　乔纳森的到来似乎为怪物世界带来一股全新的气息，德古拉伯爵则不得不费尽心机隐藏他是人类的真相……','Where monsters go to get away from it all',85000000,358375603,56.257411,6.8,2566,91,'2012-09-20','en','/eJGvzGrsfe2sqTUPv5IwLWXjVuR.jpg',3.8276192250996814,3,'2026-09-10',2,NULL,NULL),(76493,'独裁者','The Dictator','阿拉底（萨莎•拜伦•科恩 Sacha Baron Cohen 饰）是中东瓦迪亚共和国领导人。一出生，他就开始了专制的统治。他参加百米比赛，自己鸣枪自己跑，凡是跟随者统统被射杀。他视察核武器实验室，对于不合心意的科学家统统铲除。他接见外国元首，总习惯炫耀自己独特的腋臭。他每每睡过一个明星，总习惯拍张裸照存在自己的王宫。他荒淫无度，备受瞩目，用沾满了血腥的手握紧了权杖。某日，他来美国纽约参加联合国会议，却意外被牧羊人将军（本•金斯利 Ben Kingsley 饰）出卖，后者竟然找了个山寨货作了他的替代者，成立了傀儡政府。他眼看着那个脑残的李鬼在联合国大会上胡作非为，极度气愤。他来到瓦迪亚驻美大使馆前示威游行，认识了收容难民有机食物女店主（安娜•法瑞丝 Anna Faris 饰）。他隐姓埋名来到店中闹出很多笑话，后来他离店出走，意外遇到了昔日的下属，开始谋划重新夺取政权，阴错阳差之后，他爱上了那个女店主，并开始了复仇之旅……','kurd',65000000,179379533,31.349143,5.9,1743,83,'2012-05-15','en','/tD93U0Ve5C03lD5Dct7F2jVM36u.jpg',3.481180097626387,3,'2026-09-10',2,NULL,NULL),(76494,'孕期完全指导','What to Expect When You\'re Expecting','减肥教练朱尔斯和搭档伊万的孩子比结婚戒指来的要更早一些。经营婴儿用品商店的温蒂和她年轻的岳母同时有了身孕，但她发现本该充满幸福的怀胎十月似乎并没有想象中的那么美好。摄影师霍莉决定领养一个孩子，可在此之前，她需要的是一桩房子和一份工作，并且，她的丈夫对于成为一名合格的父亲感到压力很大。洛熙和马克经营着各自的餐车，在竞争中擦出了火花，意外的怀孕让洛熙开始正视与马克的这段露水情缘，而随之而来的失去更让她开始思考作为一个母亲的责任和义务。五对情侣五个故事，在并行的时空中又有着暗中的交错，这些在职场上春风得意的女人们，面对着腹中幼小的生命，会发生怎样有趣又感人的故事呢？','It\'s too late to pull out now.',40000000,79700000,27.009723,5.8,594,110,'2012-05-17','en','/a6UbE8I2AXf5taG7s6oRmJ8BX8p.jpg',3.2406118766100214,3,'2026-09-10',2,NULL,NULL),(76617,'Texas Chainsaw 3D','Texas Chainsaw 3D','A young woman learns that she has inherited a Texas estate from her deceased grandmother. After embarking on a road trip with friends to uncover her roots, she finds she is the sole owner of a lavish, isolated Victorian mansion. But her newfound wealth comes at a price as she stumbles upon a horror that awaits her in the mansion’s dank cellars.','Evil wears many faces.',20000000,47241945,26.497025,5.3,465,92,'2013-01-03','en','/wPcqo5v1yCD28aabtXasISsXn3v.jpg',3.1335140718097594,3,'2026-09-10',2,NULL,NULL),(76640,'背水一战','The Last Stand','《背水一战》的剧本被描述为“以汽车为主题的《正午》”，讲述了“一名大毒枭驾车以每小时200英里的速度逃离审判，但是在他与自由的墨西哥之间却有一个小镇的警察成为艰难的阻隔”。1952年的《正午》是影史上的经典西部片之一，描写了一名小镇警长在无法寻得助手之下，只身对抗四个前来报仇的恶徒。本片曾在2000年被翻拍成同名电视电影。','Not in his town. Not on his watch.',30000000,0,43.882857,5.7,1266,107,'2013-01-12','en','/l9JJAeDxKEfoCUJU18wSAa45g9m.jpg',3.406834712478482,3,'2026-09-10',2,NULL,NULL),(76649,'庞贝末日','Pompeii','一个叫做迈洛（Milo）的船王奴隶爱上了船王的女儿，梦想着有一天能够赎回自由身迎娶心上人。然而迈洛没有料到，就在他被卖给那不勒斯另一名奴隶主的同时，他的心上人也被许配给一个腐败的罗马议员。这时维苏威火山爆发了，迈洛不顾生命危险回到庞贝想救出心上人和被困在竞技场的角斗士好友。','No warning. No escape.',130000000,117831631,50.561849,5.2,1267,105,'2014-02-18','en','/9LKkHmEni1yX84XWWQzikk390I5.jpg',3.3269968960149536,3,'2026-09-10',2,NULL,NULL),(76706,'圣诞来信','Christmas Mail','圣诞节前夕，一个金发美女空降邮局，她的工作是为圣诞老人回信，实现人们的圣诞愿望。有一个小女孩在信中说，希望帮她孤独的叔叔找一个女朋友，这位孤独的叔叔正是邮局的信件分拣员，由于工作接触，与神秘的圣诞女孩情投意合，小女孩也非常喜欢这位金发美女。可是平安夜却发生了误会，有情人能不能终成眷属呢？',NULL,0,0,0.630226,5,15,89,'2010-12-01','en','/dumR7pD3PxK200RzJNycAZlMmIC.jpg',2.4305472970867448,3,'2026-09-10',2,NULL,NULL),(76726,'超能失控','Chronicle','少年安德鲁（戴恩·德哈恩 Dane DeHaan 饰）就像绝大多数宅男那样，内向、不善言辞，还有轻度的社交恐惧。来自父亲的打骂以及母亲的病重，更让他对周遭的一切充满戒心，成了躲在镜头后面的拍摄狂人，整日陶醉在自己的小世界里。\r 　　为了替安德鲁的未来打开局面，表哥麦特 （亚历 克斯·罗素 Alex Russell 饰）邀请他出席校园派对。聚会过程中，在表哥好友史蒂夫（迈克尔·B·乔丹 Michael B. Jordan 饰）的建议下，三人进行了一次惊险的野外探洞之旅，并意外获得了自由操纵物体的超能力。这成了他们生活的分水岭——强烈的好奇心与表现欲催促三人不停对自身能力的上限发起挑战，而安德鲁无穷的创意使得他成为了伙伴当中的佼佼者，聚会的明星。可惜好景不长，日渐增强的能力并没有带来幸福，不加节制的安德鲁越玩越过火，终致走向了一条不可挽回的毁灭之路…… ©豆瓣','What are you capable of?',15000000,145000000,64.504747,6.6,1935,84,'2012-02-01','en','/kdyrdFIt29FUmLIKvedAc2j4rpo.jpg',3.7308046733368543,3,'2026-09-10',2,NULL,NULL),(76757,'Jupiter Ascending','Jupiter Ascending','In a universe where human genetic material is the most precious commodity, an impoverished young Earth woman becomes the key to strategic maneuvers and internal strife within a powerful dynasty…','Expand your universe.',176000003,183987723,85.36908,5.2,2768,124,'2015-02-04','en','/gaGnKZ2jmtzYP8m3TLyIuaFU7K2.jpg',3.533199830734782,3,'2026-09-10',2,NULL,NULL),(76758,'金陵十三钗','金陵十三釵','1937年，日军入侵南京，战火中的古城沦为废墟，众多中国军民被困其中。一支十余人的国军德械教导队余部在李教官指挥下，从日军手中救出一批教会学校女学生，也因此失去了撤离南京的机会。幸免于难的书娟等学生返回文彻斯特教堂，与此同时，受雇前来收殓神父遗体的美国人约翰·米勒也来到这里。随着城中局势不断恶化，十四名来自秦淮河畔的风尘女子闯入教堂寻求庇护，其中精通英语的玉墨希望借助约翰的外国人身份获得更多保护。然而，教堂的围墙并不能真正隔绝战争，当日军的威胁一步步逼近，这群原本身份、经历各不相同的人，也不得不共同面对生死抉择……',NULL,94000000,95311434,12.516546,7.1,187,145,'2011-12-15','zh','/3iJ8eXVd2jAmL5KbnIacDsTUWCn.jpg',3.059961566049478,3,'2026-09-10',2,NULL,NULL),(76996,'爱情爬虫类','Love and Other Catastrophes','A day in the life of two film-school students trying to find love and another house-mate.',NULL,0,0,0.619348,5.8,9,78,'1996-08-01','it','/sO91zO8XY5o10R48RKAE6UDvJd7.jpg',2.3340525269709476,3,'2026-09-10',2,NULL,NULL),(77016,'警戒结束','End of Watch','泰勒和萨瓦拉是工作上的搭档，也是生活中的好兄弟。他们一起在美国洛杉矶的街头巡逻，出生入死，也一起相互经历着结婚、孩子诞生等等家庭生活。 　　可是，在一次例行的巡逻之后，他们发现了黑帮的一个秘密活动。而这个发现，也使得他们成为了洛杉矶最大的毒品贩子的眼中钉。于是，一场正邪较量、力量悬殊的猫鼠游戏就开始了……','Every moment of your life they stand watch',7000000,48126384,49.517264,7.2,1170,109,'2012-09-20','en','/pda6YNXLCGJnFquohKztuBAhVQU.jpg',3.682215470013674,3,'2026-09-10',2,NULL,NULL),(77156,'异形地带','The House of the Dead','一名男子与已婚女子有婚外情，在回酒店时被送到错误的街道上。当一位老人邀请他进来时，他躲避雨。他原来是一个殡仪馆的人，在四个故事的过程中给他讲了那些在他的公司里结束的人的故事。','Don\'t you dare go in there!',0,0,0.000372,4,3,90,'1978-11-22','en',NULL,2.1322137390590696,3,'2026-09-10',2,NULL,NULL),(77174,'通灵男孩诺曼','ParaNorman','建立已三百年的懒洋洋小镇，生活着一个能看到鬼魂的小男孩诺曼（柯蒂·斯密特-麦菲 Kodi Smit-McPhee 配音）。可是这种能力给他带来无限困扰，周围的人甚至父母姐姐都认为他是个满口胡言乱语的神经病，只有学校里同样受大家嘲笑的小胖子奈尔（Tucker Albrizzi 配音）相信并愿意和诺曼做朋友。这一天，深居简出且疯疯癫癫的普兰德叔叔（约翰·古德曼 John Goodman 配音）找到诺曼。叔叔也是个通令者，他告诉诺曼一个重大的秘密，当年建镇之初被人们杀死的女巫鬼魂即将苏醒，届时女巫要携着恐怖的僵尸实现对镇民的诅咒。不久，叔叔死去，而女巫注定苏醒的忌日即将到来。诺曼必须想方设法拯救他的小镇……','It\'s all fun and games until someone raises the dead.',60000000,107139399,39.539045,6.7,789,90,'2012-08-03','en','/whGYeEM9uq72lEfcQ0QW2lDMN4u.jpg',3.4645366414071606,3,'2026-09-10',2,NULL,NULL),(77332,'都市传奇','Urbania','Charlie takes an odyssey through grief during a fall weekend in New York City. His encounters are planned and chance: with a homeless man who sleeps by his building, with a friend who\'s dying, with the couple who lives (and noisily loves) in the flat above him, with a bartender and a one-night-stand he follows home, and with a tattooed stranger whom he seeks out and befriends. Along the way, Charlie inhabits a city full of moments of violence and of stories and legends: a kidney thief, a microwaved poodle, a rat in a hot dog bun, a baby left on a car top, a tourist\'s toothbrush, needles in public-phone change slots. Charlie lives and tells his own stories. What caused his melancholy?','Heard any good stories lately?',0,0,0.065155,5.2,10,103,'2000-01-24','en','/bl2RsU7kzOm1AjZhCBepCxuFToY.jpg',2.3509199284874933,3,'2026-09-10',2,NULL,NULL),(77459,'怪兽在巴黎','Un monstre à Paris','1910年，法国巴黎。电影院放映员埃米尔（Sébastien Desjours 配音）和他的朋友罗尔（Gad Elmaleh 配音）来到某科学家的实验室送货，科学家恰好不在，两个人胡乱动实验室的药品，结果引发大混乱，更令一只小跳蚤巨大化，变成恐怖的大怪物。怪物跳蚤逃出实验室，在巴黎引来了一阵骚乱和恐慌。而事实上，这只跳蚤温柔无辜，有着一颗纯洁的心。它偶然结识了美丽的酒吧驻唱歌手露西（Vanessa Paradis 配音），由此得名弗兰卡。弗兰卡具有令人惊叹的音乐天赋，它和露西的演出得到人们的欢迎。\r 而另一方面，贪心的警察局长却想消灭怪物以壮大自己的威信。为了保护弗兰卡，埃米尔、罗尔和露西通力合作……',NULL,25000000,0,17.375562,6.5,313,90,'2011-10-12','fr','/aLV3pkUyx7STSYhyclRwzOEjIt6.jpg',3.156865404256871,3,'2026-09-10',2,NULL,NULL),(77495,'当你熟睡','Mientras duermes','人过中年的塞萨尔是某幢公寓的管理员，上班期间他兢兢业业，和每个经过他面前的邻居问好，认真处理所有事务，偶尔帮助住户照看小狗；休息时则前往医院看望母亲，为其讲述一天的经历和见闻。然而看似老实内向的塞萨尔，却有着不可为人道的秘密。每天晚上，他都偷 偷潜入青春靓丽的女住户克拉拉的房间，用药物令其陷入深深的熟睡之中，日常海发各种言辞热辣的短信进行骚扰。然而这一切似乎并非处于近乎疯狂的迷恋，他的行为背后隐藏着更深的企图。在此期间，克拉拉的身体状况愈来愈差，她的生活也由此变得一团糟。在他乖张的行为进行过程中，一切朝着不可逆转的方向发展……','Someone is watching over you',5000000,0,9.136965,7,202,107,'2011-10-14','es','/aDi56oSNirZStVwgl8R12nkQrIk.jpg',3.0661978945448194,3,'2026-09-10',2,NULL,NULL),(77866,'Contraband','Contraband','When his brother-in-law runs afoul of a drug lord, family man Chris Farraday turns to a skill he abandoned long ago – smuggling – to repay the debt. But the job goes wrong, and Farraday finds himself wanted by cops, crooks and killers alike.','What would you hide to protect your family?',25000000,63100000,31.364901,6.1,770,109,'2012-01-12','en','/1jk7C6fIrwKzjT76ziknFBuvpNU.jpg',3.3470095219665184,3,'2026-09-10',2,NULL,NULL),(77875,'情场玩咖','Playing for Keeps','《绿茵场》的主人公是一名退役的足球明星（杰拉德·巴特勒饰），他被迫去给自己儿子所在的少年球队当教练，却受到了小队员们性感火辣的妈妈们以及几位风韵犹存的“邻家”少妇的诱惑。乌玛·瑟曼、凯瑟琳·泽塔-琼斯、朱迪·格雷尔将饰演诱惑杰拉德·巴特勒的魅力少妇，杰西卡·贝尔则饰演杰拉德·巴特勒的前妻。',NULL,35000000,0,17.932561,5.4,240,106,'2012-11-29','en','/1fy2qH4VKotOzhCsgSYvSsbyVTi.jpg',3.0127720628648236,3,'2026-09-10',2,NULL,NULL),(77877,'幸运符','The Lucky One','美国海军陆战队中士罗根提伯特结束他第三期在伊拉克的战斗任务后返回美国，身上带着一件他相信是保佑他在多场无情战火中得以幸存的幸运物，那是一张陌生女子的照片。经过不断的四处打听之后，罗根终于知道她的名字─贝丝及她的住处，想要向她道谢的罗根于是出现在她的家门口，阴错阳差地在她家所经营的动物旅社工作。尽管她最初对他并不信任以及她颇为复杂的环境背景，他们俩仍不顾一切地展开恋情，罗根开始希望贝丝不仅只能当他的幸运符，他更希望自己能尽一切力量保护这个日常生活中饱受威胁的女人。',NULL,25000000,99357138,26.811541,6.8,946,101,'2012-04-19','en','/r6KFGPLxDx7KbdHO9ljRFqAPpDx.jpg',3.4997066154104375,3,'2026-09-10',2,NULL,NULL),(77883,'死魂盒','The Possession','克莱德和斯蒂芬妮是一对离婚的夫妻。在离婚之后，他们的关系还维持的不错。但是，在他们的分手中，最受伤的，则是他们的两个女儿。其中一个叫做艾姆的孩子，是最可怜的一个。  　　这一天，克莱德把女儿接到自己家里小住几天。一个偶然的机会，在邻居的后院大甩卖上，艾姆看上了一个奇奇怪怪的旧盒子。为了让自己的女儿开心，克莱德就买下了这个东西。因为是邻居的旧物，所以克莱德并没有对这个玩意上心。可是随着艾姆打开盒子，见到、触摸了其中的东西之后，她就变得越来越怪异，而且还充满了暴力倾向。随着艾姆的暴力事件越来越升级，克莱德和斯蒂芬妮不得不到处求医问药，从把她送去做脑检查到咨询犹太拉比的办法都用上了。  　　最后，一个拉比告诉他们，克莱德买回来的那个盒子根本不是什么装饰品，而是一个恶灵盒。当艾姆把盒子打开的时候，恶灵就附体了。而现在，避免艾姆被恶灵摧毁的最好方法就是找一个懂得宗教的人前来驱魔…','Fear The Demon That Doesn\'t Fear God',14000000,85446075,21.680424,5.8,498,92,'2012-08-30','en','/mfSZikEXJKuANngC6H9yHWzz4UF.jpg',3.1942740677614165,3,'2026-09-10',2,NULL,NULL),(77930,'魔力麦克','Magic Mike','十九岁的亚当（亚历克斯·帕蒂弗 Alex Pettyfer 饰）在工地上认识了麦克（查宁·塔图姆 Channing Tatum 饰），后来一次偶遇得知原来麦克是个脱衣舞男，而且还是脱衣舞场的台柱“魔力麦克”。第一次迷迷糊糊登台后，亚当尝到了赚快钱的滋味。于是麦克领着亚当入行，让他改变行头，教他跳舞的技巧以及如何取悦挑逗女性。将艺名改为“The Kid”的亚当，和舞场一众舞男里奇、肯特、提托以及泰山，度过了一个疯狂、刺激、纸醉金迷的夏天。另一方面，麦克并不想一直干舞男这一行，他想创办一所家具定制公司，然而他申请银行贷款却失败。同时，他发现自己爱上了亚当的姐姐，他决定不去迈阿密……影片根据主演查宁·塔图姆19岁时在弗罗里达州坦帕市做脱衣舞男的经历改编。','Work all day. Work it all night.',7000000,167221571,35.897151,6.1,1040,110,'2012-06-28','en','/acwTBRAduVoG2Pq6Z0QKOnmGHwf.jpg',3.4222795158366544,3,'2026-09-10',2,NULL,NULL),(77931,'The Smurfs 2','The Smurfs 2','The evil wizard Gargamel creates a couple of mischievous Smurf-like creatures called the Naughties that he hopes will let him harness the all-powerful, magical Smurf-essence. But when he discovers that only a real Smurf can give him what he wants, and only a secret spell that Smurfette knows can turn the Naughties into real Smurfs, Gargamel kidnaps Smurfette and brings her to Paris, where he has been winning the adoration of millions as the world¹s greatest sorcerer. It\'s up to Papa, Clumsy, Grouchy, and Vanity to return to our world, reunite with their human friends Patrick and Grace Winslow, and rescue her! Will Smurfette, who has always felt different from the other Smurfs, find a new connection with the Naughties Vexy and Hackus or will the Smurfs convince her that their love for her is True Blue?','Get ready to get naughty!',105000000,347434178,32.473628,5.5,695,105,'2013-07-30','en','/q5ffCgXrb5qIbIksOW4UAtQAgSs.jpg',3.2395301056948784,3,'2026-09-10',2,NULL,NULL),(77934,'圣诞兔子','The Christmas Bunny','《圣诞兔子》是讲述一个孤独的养子在平安夜的时候发现了一只受伤的兔子被遗弃在树林里。住在旧谷仓旁边的一位夫人好心的收留了这只兔子，并治愈了它......','Everybody needs some bunny to love.',250000,0,0.065103,5.7,7,96,'2010-11-28','en','/naQJmUIeS6XTfmOUO52JOPhMVeI.jpg',2.2842978969058247,3,'2026-09-10',2,NULL,NULL),(77948,'白昼冷光','The Cold Light of Day','在华尔街经营一家公司的年轻商人威尔（亨利·卡维尔 Henry Cavill 饰）从百忙之中抽身，飞往西班牙一处海滨小镇与家人度假。事隔多年，他与父亲马丁（布鲁斯·威利斯 Bruce Willis 饰）、母亲、弟弟乔什（莱菲·盖夫隆 Rafi Gavron 饰）及其女友达 拉（艾玛·汉密尔顿 Emma Hamilton 饰）相聚。家人围坐餐桌，其乐融融。但是祥和的气氛很快便被破坏，威尔接到公司破产的电话，心情糟糕到极点，由此也与家人的关系紧张起来。航海途中达拉意外受伤，当威尔去镇上买药期间，留在船上的家人却遭到绑架。焦急的威尔在当地无人可信，他独自搜索家人的下落，在此过程中竟发现了关于父亲和事件背后的诸多秘密……','Be careful who you trust.',20000000,16863583,15.131867,4.8,271,93,'2012-04-04','en','/9aNOShkH7Z1m39WtIDD5luwN3My.jpg',2.978855150874675,3,'2026-09-10',2,NULL,NULL),(77949,'觉醒','The Awakening','故事发生在1921年的英格兰，在一战中所经历的失败令压抑而又沉痛的气氛笼罩了在全国上下。弗洛伦斯（丽贝卡·豪尔 Rebecca Hall 饰）是一位打假义士，正义感极强的她将戳穿谎言揭露真相视为己任，她不相信世间有鬼魂存在，存在的只有险恶的人心。  　　在一所男子寄宿学校中，盛传着闹鬼的传闻，在人们口中，一个非正常死亡的男孩的鬼魂终日徘徊在校园中不肯离去。为了打消学生和家长的恐惧，学校委托弗洛伦斯前来调查。弗洛伦斯很快便展开了工作，在她的精明强干之下，事件的真相逐渐浮出了水面。而正当她以为问题已经得到了解决准备离开时，却发生了一件足以颠覆她此生全部信仰的事件。','Sometimes dead does not mean gone.',4798235,209696,25.30216,6.3,458,107,'2011-08-17','en','/nfw7wIJ7XE1DOQKLM3rAl11av4r.jpg',3.244185634461577,3,'2026-09-10',2,NULL,NULL),(77950,'极速蜗牛','Turbo','在某个普通的郊外住宅区青草丛内，生活着一群普普通通的菜园蜗牛。这群慢吞吞的小家伙安于现状，朝九晚五，躲避着人类和乌鸦等强大天敌的袭击，享受着来自大自然的馈赠。但是，在它们中间却有一个异想天开的家伙，它叫特伯（瑞恩·雷诺兹 Ryan Reynolds 配音），极度崇拜方程 式赛车手盖·盖尼耶，梦想能够体验风驰电掣所带来的无上快感。在一次意外事件过后，特伯的身体悄悄发生了变化，它拥有梦寐以求的极速，俨然成为一辆蜗牛赛车，并且盲打误撞被带入人类社会。从此以后，印第安纳波利斯的500赛车赛不再是梦想，特伯注定在人类世界书写属于刺激的速度传奇…','SLO NO MO',135000000,282570682,44.765377,6.1,1074,96,'2013-07-11','en','/svFTbiVxf0N0uOjbXjhYt1tb8is.jpg',3.4494857674070287,3,'2026-09-10',2,NULL,NULL),(77951,'与恐龙同行','Walking with Dinosaurs','炎热的假期，男孩里奇（查理·罗 Charlie Rowe 饰）和妹妹跟随身为考古学家的叔叔（Karl Urban 饰）来到了辽阔壮丽的阿拉斯加，体验一次难得的寻访史前动物的旅程。在森林中，他受到一只乌鸦的指引，竟然穿越时空来到了七千万年前的白垩纪中期。在某个厚鼻龙家族中，小家伙派西（Justin Long 配音）刚刚出生就被伤齿龙在脑袋上开了一个大洞，幸运活下来的他注定拥有传奇的一生。时光荏苒，派西和伙伴们一天天长大，他也偶然邂逅令之心动的女孩裘妮波（Tiya Sircar 配音）。厚鼻龙家族的大迁徙开始，但从旅途之处便伴随着大火和猎杀。  　　七千万年前，一段充满惊险的挑战的旅程再度呈现……','The Greatest Adventure in 70 Million Years',80000000,126546518,10.088006,5.2,133,87,'2013-12-18','en','/lkElT9HpOUIjIL20Hwy3LZqgXWc.jpg',2.878107316576502,3,'2026-09-10',2,NULL,NULL),(77953,'政坛混战','The Campaign','在全国性的大选来临之际，一直被各界看好的种子选手－－国会议员坎姆·布莱迪（威尔·法瑞尔饰）不慎在公开场合失态，于是幕后金主策划推举一名敌对候选人，想要在其地盘北卡罗莱纳区造成影响力，而他们的人选就是菜鸟新人马帝·哈金斯（扎克·加利费安纳基斯饰），这位有些娘娘腔的中年男人是当地旅游中心的主任，一直过着安稳的小男人生活。起先，马帝似乎是最不被人看好的选择，毫无政坛经验的他也数次在公开场合出糗。不过由于新赞助者的支持和金援到位，再加上拼命三郎般的竞选经理及其家族的政治人脉，他得快成为魅力政客坎姆不容小觑的黑马候选人。随着选举日逐渐逼近，这两人的激烈竞争依然僵持不下，而且很快就演变成势不两立、水火不容的情况，他们倾全力互相毁谤和中伤，想尽办法玩阴，耍贱招陷害、弄臭对方，誓言斗个你死我活。暗涌连连的政坛，迎来了一场大混战。','May The Best Loser Win.',0,104907746,16.460356,5.6,578,85,'2012-08-09','en','/61HgY1B3Y5LaT8cbrd7xgl0Zwpv.jpg',3.184682888545619,3,'2026-09-10',2,NULL,NULL),(77987,'唯神能恕','Only God Forgives','十年前，Julian（瑞恩·高斯林 Ryan Gosling 饰）因杀了一名警察而跑路到了曼谷，现在他经营着一家泰拳俱乐部以掩饰毒品走私交易。Julian的弟弟Billy（Tom Burke 饰）因残杀了一名妓女而遭到“复仇天使”退休警察Chang（Vithaya Pansringram 饰）的杀害。身为庞大犯罪组织头目的Julian的母亲Crystal (克里斯汀·斯科特·托马斯Kristin Scott Thomas饰演）来到曼谷为爱儿收尸。满腔愤怒与强烈报复心态的母亲要求Julian为兄弟报仇，使得Julian不得不与Chang正面交锋......','Time to Meet The Devil',4800000,10337387,35.754865,5.6,862,90,'2013-05-30','en','/7LhofsoxgiAoo6iIkvAtZaptXz2.jpg',3.300110160506505,3,'2026-09-10',2,NULL,NULL),(78149,'双龙一虎闯天关','An Alan Smithee Film: Burn, Hollywood, Burn','这是一部揶揄好莱坞乱相的嘲讽喜剧，也是一部关于倒楣导演遭人作贱的悲惨过程。依据美国电影界的惯例，一部电影拍完后，导演如果不具名，便一律挂名为Alan Smithee，就像中文里（无名氏）的用法，偏偏片中导演的名字就叫做Alan Smithee，而他的运气也不见得太好，夹杂在制片、经纪人、律师、还有三个大牌明星（席维斯史特龙、成龙和琥碧戈柏分饰自己）合演的史上耗资最大钜片「Trio」之间，影片终于完成了……',NULL,10000000,45779,0.666218,3,9,86,'1998-02-20','en','/KSGv5uV6SJS7mUMlttvLfWA6Lv.jpg',2.3239077720057786,3,'2026-09-10',2,NULL,NULL),(78307,'堕落边缘','On the Outs','本片讲述了三个女孩在泽西艰难无奈的生活，在挣扎后她们做出了自己的抉择，一个做了毒品贩，一个是君子，还有一个是逃亡者，在这些残酷的事情面前，她们遭受了不同程度的心理压力和痛苦，然而她们最后能悔过自新，浪子回头吗？','A drug dealer. An addict. A runaway. The story of 3 girls.',0,0,0.493223,5.9,6,86,'2004-09-11','en','/dyumIFLdjo6KRsPgL2VdAb7ulkc.jpg',2.256936947352173,3,'2026-09-10',2,NULL,NULL),(78373,'Dancer, Texas Pop. 81','Dancer, Texas Pop. 81','Four guys, best friends, have grown up together in DANCER, TEXAS POP. 81, a tiny town in West Texas. Years ago, they made a solemn vow to leave town together as soon as they graduate. Now, it\'s that weekend and the time has come to \"put up or shut up.\" The clock is ticking and as all 81 people in the town watch, comment, offer advice and place bets, these four very different boys with unique backgrounds struggle with the biggest decision of their lives... whether to stay or leave home.','in the middle of nowhere they had everything',0,565592,0.376662,10,1,97,'1998-05-01','en','/khV9zPcvgOjrqwlk3dI1lGojZib.jpg',1.98675655921465,3,'2026-09-10',2,NULL,NULL),(78381,'从此刻到日出','Twixt','影片的故事灵感取自艾伦·坡的诗歌（诗人本尊也在电影中现身，由本·卓别林饰演）。伴随着Tom Waits的旁白，方·基默饰演的过气小说作家带到一座加利福尼亚的诡异小镇。随即被卷入一桩神秘的谋杀事件。在夜晚的梦中，有一个名叫V的年轻女鬼（艾丽·范宁）接近他。小说家不能确定谋杀案是否与年轻女子有关系，但是却感谢这场事件为他提供了故事素材。最终他找到了故事的真相，惊讶地发现结局超乎他想象地裹挟着自己的人生。\r 《此刻与日出之间》是科波拉第一部自己筹款拍摄的电影，成本只有700万美元，或许这也解释了影片为什么呈现出一种如此质感。再加上影片后期还要进行3D化的转制，多少让人有点担心，但愿科波拉不要为影片的低成本所负累。\r 影片将于9月多伦多电影节首映。具体公映日期还未确定。','Between the living and the dead, eviil is waiting.',7000000,0,5.060656,5,85,84,'2011-09-10','en','/iDBPiZHNLoFjc41bhDrZGGe3ke7.jpg',2.7777123115193834,3,'2026-09-10',2,NULL,NULL),(78383,'护士3D','Nurse 3-D','护士的暗黑故事,主人公艾比·罗素（帕兹·德拉维尔塔 饰）是一名护士长，白天她看起来童叟无欺，但每到晚上，她就露出真面目，以性感诱骗男人，用残酷的死亡来暴露他们猥琐的真面目。新来的年轻护士丹妮（卡特里娜·宝登 饰）成为艾比眼中的猎物，一夜在酒吧狂欢之后，丹妮被艾比带回家中一番云雨。然而已有男友的丹妮却拒绝了艾比的示爱，而后一系列惊悚的事件开始围绕她发生。丹妮开始怀疑这一切与艾比有关……','Your pain is her pleasure.',10,10000000,10.013629,4.9,119,99,'2013-09-28','en','/sZhXsT6ch1Z7NKFspMH7QyfpsBa.jpg',2.84516214234249,3,'2026-09-10',2,NULL,NULL),(78394,'雷克斯海3D：史前世界','Sea Rex 3D: Journey to a Prehistoric World','跟着想像力丰富的Julie回到三叠纪、侏罗纪和白垩纪时期，发掘惊人的海底世界，一起看看力量强大的巨型滑齿龙、长颈的薄板龙和巨大的秀尼鱼龙如何在恐龙统治地球之前称霸海底王国。','The T-Rex of the Seas come alive.',5000000,4074023,4.498368,5.9,11,41,'2010-05-14','en','/au49zJtESBEz4zAOsXTv5xLWOHS.jpg',2.3826993191350443,3,'2026-09-10',2,NULL,NULL),(78698,'Big Miracle','Big Miracle','Based on an inspiring true story, a small-town news reporter (Krasinski) and a Greenpeace volunteer (Barrymore) enlist the help of rival superpowers to save three majestic gray whales trapped under the ice of the Arctic Circle. ‘Big Miracle’ is adapted from the nonfiction book ‘Freeing the Whales: How the Media Created the World’s Greatest Non-Event’ by Tom Rose.','A family of whales trapped beneath the ice. One unforgettable rescue.',40000000,24719215,8.303696,6.6,152,107,'2012-02-02','en','/hqdrgC5oHK06DDaAlulReUC7Nog.jpg',2.9703388005527414,3,'2026-09-10',2,NULL,NULL),(78705,'Live-In Maid','Cama adentro','Buenos Aires is in a deep recession. As the money runs out, the relationship between an employer and her live-in maid changes dramatically.',NULL,0,0,0.038706,7.8,3,83,'2004-09-21','en','/dkTvwzxEomaarn1uy0fjvu8ZzQy.jpg',2.136977071165088,3,'2026-09-10',2,NULL,NULL),(78814,'We Have Your Husband','We Have Your Husband','American-born Jayne Valseca, her husband Eduardo, the son of a legendary Mexican newspaper publisher, and their two children live an idyllic life on their 1,000 acre ranch outside of a peaceful Mexico town. But in the summer of 2007, their peaceful life is turned into a real-life nightmare when Eduardo is ambushed and kidnapped by strangers. With kidnapping becoming a pervasive and lucrative business in Mexico, Jayne is at the mercy of the kidnappers when they demand millions for the husband\'s safe release. She\'s pushed to the limit to do everything she possibly can to raise the money necessary to bring Eduardo back alive. As Eduardo is starved and tortured, he looses hope of ever seeing his family again but despite the dire and bleak times, Jayne refuses to give up and decides to turn the tables on the kidnappers and makes demands of her own. The film is based on a true story from the book, We Have Your Husband: One Woman\'s Terrifying Story of a Kidnapping in Mexico.',NULL,0,0,0.102003,5,3,89,'2011-11-12','en','/n3vcScSfTYM3XS4sBwhHUwxw0pL.jpg',2.1336763499745555,3,'2026-09-10',2,NULL,NULL),(79120,'周末时光','Weekend','周五夜晚在酒吧相遇后，拉塞尔与格伦陷入了一个充满性、毒品与私密对话的迷失周末。尽管他们对人生的期许与实现路径各执一词，却建立起令人惊异的情感联结——这羁绊将在此后余生中久久回荡。[圣丹斯精选]','A (sort of) love story between two guys over a cold weekend in October.',8000,469947,1.041254,7.4,163,96,'2011-09-22','en','/pdLaHJL07VWPgY56WGO7gDIMTs4.jpg',3.014203476473377,3,'2026-09-10',2,NULL,NULL),(79161,'51 Birch Street','51 Birch Street','Documentary filmmaker Doug Block had every reason to believe his parents\' 54-year marriage was a good one. But when his mother dies unexpectedly and his father swiftly marries his former secretary, he discovers two parents who are far more complex and troubled than he ever imagined. 51 Birch Street is a riveting personal documentary that explores a universal human question: how much about your parents do you really want to know?','Do you really want to know your parents?',0,0,0.049921,6.8,6,90,'2006-10-18','en','/7eG63TqqdUcIyAvPelJajXF3gZN.jpg',2.2581301494642103,3,'2026-09-10',2,NULL,NULL),(79316,'恶魔预产期','Devil\'s Due','有情男女扎克·麦考尔（扎克·吉尔福德 Zach Gilford 饰）和萨曼莎（艾莉森·米勒 Allison Miller 饰）即将结为夫妇，为了纪念这一重要时刻，扎克拿起摄像机，希望记录下父亲婚后生活的点点滴滴和每一个重要时刻。浪漫而温馨的婚礼过后，麦考尔夫妇踏上前往圣多明各的快乐无忧的蜜月之旅。在一个万众狂欢的夜晚，他们随同当地人进入一间地下酒吧。纵情歌舞过后，夫妻俩陷入无意识状态，时断时续的摄像机则记录下片段化的神秘场景。回家后不久，萨曼莎发现自己怀有身孕，夫妻俩随感意外，却也为此喜悦非常。只不过快乐并未持续太久，随着孕期的进行，接二连三有诡异且无法解释的事件发生在夫妇俩的身边。  　　萨曼莎腹中的宝贝，似乎带着不祥的征兆即将降临人间，而无处不在的摄像机记录下恐怖的时刻……','The Devil Always Gets His Due',7000000,36433975,14.741589,4.4,216,89,'2014-01-08','en','/2qgX92HqsqWNf8vCoVb7lMSwfyn.jpg',2.9181781384046634,3,'2026-09-10',2,NULL,NULL),(79587,'Four Single Fathers','Four Single Fathers','A comedy/drama about four Italian single fathers trying to cope with American ex-wives, children, family, and new relationships, set in New York and Rome.','Comedy',3,0,0.008263,0,0,100,'2009-01-15','en','/A3aNmcPhcICa0WG8Qn5IZ2gag1A.jpg',1.8338012596391178,3,'2026-09-10',2,NULL,NULL),(79694,'幻影','The Apparition','影片讲述了一次大学实验唤醒了一股超自然力量，一对夫妇备受其恐吓的故事。','Once You Believe You Die',17000000,9627492,6.385234,4.5,140,82,'2012-08-23','en','/gNY9J4qs6bces9U1nLcO8DX4oE0.jpg',2.844986325480018,3,'2026-09-10',2,NULL,NULL),(79698,'The Lovers','The Lovers','The Lovers is an epic romance time travel adventure film. Helmed by Roland Joffé from a story by Ajey Jhankar, the film is a sweeping tale of an impossible love set against the backdrop of the first Anglo-Maratha war across two time periods and continents and centred around four characters — a British officer in 18th century colonial India, the Indian woman he falls deeply in love with, an American present-day marine biologist and his wife.','Love is longer than life.',27000000,0,2.418535,4.8,34,109,'2015-02-13','en','/6esL8UH2sXXqbfbaV6bFEUBCDOr.jpg',2.5937803928280925,3,'2026-09-10',2,NULL,NULL),(79777,'血与蜜之地','In the Land of Blood and Honey','《血与蜜之地》讲述的是一段战争中的爱情故事。一个塞族男子和一个波斯尼亚穆斯林女子相爱了。但很快，南斯拉夫在1991年到1992年分裂成了几个部分，波黑战争爆发。这次第二次世界大战结束后在欧洲爆发的规模最大的局部战争使得两人成了新的罗密欧与朱丽叶，他们的生活完全被改变了。','Love can change what we want… war can change who we are',10000000,303877,4.267466,5.8,45,127,'2011-12-23','en','/h1r4qey0K8PG9OgQdDqQcXtMq6c.jpg',2.6694525533281053,3,'2026-09-10',2,NULL,NULL),(79940,'提姆和艾瑞克的十亿美元大电影','Tim and Eric\'s Billion Dollar Movie','Two guys get a billion dollars to make a movie, only to watch their dream run off course.',NULL,0,0,1.75311,5.2,34,94,'2012-03-02','en','/bcipzEhr7xh9bfvqLq3iqJjnFdk.jpg',2.5976117394766525,3,'2026-09-10',2,NULL,NULL),(80035,'新邻里联防','The Watch','艾文、鲍勃、富兰克林和贾马克斯是四个生活在同一片街区的邻居。生活对于他们来说就是无聊的上班和回家。所以艾文想到了一个在业余生活里的解闷方式——去巡逻，去看看街坊邻居中有没有需要帮助的人。 　　他的这个想法得到了鲍勃、富兰克林和贾马克斯的支持。很快，这四个好兄弟就成为了整个街区的不拿报酬的“片警”。在一次日常的“巡逻中”，艾文驾驶的车撞到了什么东西。四个人下来查看，结果发现是有外星怪物入侵地球。于是，这四个人便按照自己的方式展开了对外星人的“驱逐”。在驱逐的过程中，他们拿起了富兰克林珍藏已久的武器而且还找到了外星人的“大杀器”——有武力武装的这四个“家庭妇男”决定要对外星人实行围剿，大干一场了…','Got Protection?',68000000,68267862,39.395881,5.3,881,98,'2012-07-26','en','/7mKOkvN4fCev72hlR0J9P4oAu8.jpg',3.2630584762885984,3,'2026-09-10',2,NULL,NULL),(80215,'独立游戏大电影','Indie Game: The Movie','Indie Game: The Movie 独立游戏大电影 是一部关于独立游戏的纪录片，讲述独立游戏过往的精彩故事。\r 关于该电影：\r 随着二十一世纪的到来，新的一类独立艺术家诞生了：独立游戏开发者。他们有独立的构思，特别的设计以及个性鲜明的游戏。当然，他们也希望获得成功。\r 影片中，设计师 Edmund McMillen 和程序员 Tommy Refenes 经过两年的努力，等待着他们第一款XBOX的游戏 Super Meat Boy “超级肉食男孩” 的发布。游戏讲述的是一个绷带男孩寻找女友的故事。\r 而在一个名为 PAX 的视频游戏展中，开发者 Phil Fish 则推出了众人翘首以盼的画了四年制作的游戏 FEZ “费兹”。\r Jonathan Blow 则在考虑继 Braid “时空幻境” 之后的新游戏。而时空幻境曾一度是历史上平均最高的游戏之一。\r Lisanne Pajot 和 James Swirsky 第一次共同制作了这部电影，他们精心捕捉独立游戏艺术家们奋斗历程的点点滴滴，以及其艺术表现过程中的情感历程。\r 四个开发者，三款游戏，一个终极目标 —— 通过这部纪录片共同表达了出来。',NULL,0,0,7.676677,7.4,203,96,'2012-05-18','en','/2B1IqPg97ZhpEov4Fg3si4hI1Kw.jpg',3.090306461855455,3,'2026-09-10',2,NULL,NULL),(80271,'放声大笑','LOL','这部青春喜剧片讲述的是互联网和网络无所不在的当下，高中女生劳拉和她的死党们一边要忙于应付学校的压力和同窗好友的罗曼蒂克，一边还要与落伍的父母怎样才能和谐相处的故事。  本片翻拍自2008年的同名法国电影，LOL是“Laughing out loud”的缩写，意为“大笑”，在片中也是罗拉的昵称。罗拉（麦莉-赛勒斯 饰演）是一名十七岁的少女，与单亲母亲安妮（黛咪-摩尔 饰演）住在一起。她们各自都经历着自己的艰难时期，罗拉对抗着青春性意识的苏醒和毒品的诱惑，安妮正在试图走出离婚的阴影。在高中新学期的伊始，罗拉面临着全新挑战，即要努力寻找家庭与学校、爱情与友情的平衡点。在被男友抛弃之后，她努力表现得毫不在乎，却在一个人的时候痛哭失声。安妮（黛咪-摩尔 饰演）由于担心女儿，偷看了她的日记，这令她意识到和女儿之间已经产生了多么大的隔阂，她总是不知道何时该严厉管教女儿，何时又该随遇而安。与此同时，罗拉结识了在摇滚乐队做乐手的凯尔（道格拉斯-布斯 饰演），他们彼此吸引，成为了至交好友，就在他们的友情即将进展为爱情的时候，却遭到了阻挠……','You can change your status, but not your heart.',11000000,0,31.763201,5.9,881,97,'2012-02-10','en','/AlnBUoKzzPnczrzzxuh0SYwDa3Z.jpg',3.3441556884288874,3,'2026-09-10',2,NULL,NULL),(80274,'安德的游戏','Ender\'s Game','并不遥远的未来，来自外星系的异星蜓入侵地球，造成超过一千万人死亡。危难时刻，勇敢的队长瑞克汉姆阻挡了侵略者扩张的步伐。利用这有限宝贵的时间，地球人致力寻找具有极高天赋的少年加以训练培养，以期他们能够成为挫败外星入侵者的领袖人物。身形瘦小、神色忧郁但目光无比坚定的安德·维京（阿沙·巴特菲尔德 Asa Butterfield 饰）正是这群少年中的一员，他也是国际舰队寄予厚望并重点培养的对象。经过数轮严苛的考评，安德的潜质得到战斗学校的指挥官格拉夫上校（哈里森·福特 Harrison Ford 饰）的肯定，他被上校带到了位于轨道空间站上的战斗学校，在全封闭的环境下，未来的英雄迎来新一轮的磨练……','This is not a game.',110000000,125537191,45.94834,6.6,2303,114,'2013-10-23','en','/pVcRI5YKnkkgaAD876jBeKb189d.jpg',3.7310612726369166,3,'2026-09-10',2,NULL,NULL),(80278,'海啸奇迹','The Impossible','玛莉雅和亨利带着三个儿子，一同前往泰国共渡圣诞佳节，不料就在圣诞节隔天，当这幸福的一家人在泳池旁享受着悠闲时光时，一股猛兽般的万呎滔天巨浪竟迎面袭来。被眼前景象震慑住的玛莉雅，一时反应不及，不幸惨遭巨浪袭卷；而尽管亨利及时抓住两个儿子准备逃亡， 一切仍旧太迟，凶猛的大水最后仍冲散了他们。一度被巨浪击昏的玛莉雅，醒来后发现自己正漂浮在海面，而原本围绕在身旁的所有景物，都已被淹没于水面下，她深信家人们皆已罹难的同时，竟发现自己的大儿子卢卡斯，竟然就漂浮在距离她仅有几公尺远的海面上。玛丽雅顿时犹如被打了一剂强心针，她决定想尽办法，要带着大儿子卢卡斯一起活着离开......','Nothing is more powerful than the human spirit.',42000000,180274123,47.559928,7,2025,113,'2012-09-09','en','/k0DLCiDbnYywOHiISALbl2EH2NE.jpg',3.791527082361279,3,'2026-09-10',2,NULL,NULL),(80304,'我父亲的房子','Casa de Mi Padre','故事讲述Armando Alvarez（威尔·法瑞尔）一辈子都在父亲的大农场里生活、工作。但如今农场遭遇了财政危机，Armando的弟弟Raul（迭戈·鲁纳 ）从外地归来，并且带来了未婚妻Sonia（Genesis Rodriguez）。看起来Raul的成功跨国生意似乎能挽救农场，他还保证将偿还父亲所有的债务。不过，渐渐的，Armando爱上了Sonia，而Raul的生意看起来似乎不是什么合法的买卖，而这一切，把他们卷入一场与墨西哥最吓人的毒枭Onza（盖尔·加西亚·贝纳尔）的战争。  本片幕后来自《周末夜现场》，恶搞必不可少，融合西部、喜剧、枪战等元素。影片还有浓郁的墨西哥特色，法瑞尔全程说西班牙语。','Funniest movie you\'ll ever read.',0,0,5.754416,5.5,103,84,'2012-03-15','en','/kVCc7xwTAlckBofazrwIz8x1TXC.jpg',2.832675780008607,3,'2026-09-10',2,NULL,NULL),(80321,'马达加斯加3：欧洲通缉犯','Madagascar 3: Europe\'s Most Wanted','四个好伙伴逃出非洲后，他们便迫切想要回到纽约。按照惯例企鹅和猴子是要出马帮忙的，并且按照惯例它们也是会把整个计划搞黄的，所以按照惯例四个好兄弟们又一次发现自己错误地降落在了错误的地方—蒙特卡洛。他们的到来惊动了当地的动物管制中心，经过几个回合的拼死搏斗之后，动物们加入了一个欧洲巡演马戏团寻求保护。在马戏团的日子他们可谓是春风得意，旅途上的演出也唤醒了四人内心对表演事业的渴望与热情。到底他们最后能否成功回纽约，到底他们会否重新进入“演艺圈”，请大家拭目以待吧！','Six years ago, they disappeared without a trace. Next summer, they finally resurface.',145000000,746921274,44.989192,6.4,1808,93,'2012-06-06','en','/dtaVn1UoXuHfoObi2ahF748WD8y.jpg',3.6267228543779066,3,'2026-09-10',2,NULL,NULL),(80468,'杀人之人','Some Guy Who Kills People','A former mental patient\'s repressed anger reaches the boiling point, leading him to embark on a mission of revenge against the thugs who once subjected him to severe physical and mental trauma.','Your number is up.',300000,0,2.733725,5.7,45,97,'2011-04-14','en','/m6sqWQDcg7er0dg7LomMQGeVBMO.jpg',2.664203716450135,3,'2026-09-10',2,NULL,NULL),(80585,'摇滚年代','Rock of Ages','1987年的洛杉矶,各种各样的摇滚乐队和歌手如同雨后春笋一样的遍地开花,就在这个梦想的城市里,有两个从外地赶来寻梦,但是现在却只能在酒吧里做男女招待的年轻人。  　　那个女孩叫做谢丽·克里斯蒂安,那个男孩叫做德鲁·波利。他们怀揣着梦想,在洛杉矶这个大都市里做了飘在洛杉矶的人。他们相亲相爱,他们共同奋斗。虽然洛杉矶里明星很多,不过,他们对歌唱和摇滚的热爱,还是让他们从芸芸众生中脱颖而出。很快,他们得到了演出的机会,有成为巨星的可能。而与此同时,他们的爱情也接受了挑战。','Nothin\' but a good time',75000000,59418613,23.515938,6,385,123,'2012-06-13','en','/bpm4eK6nnJPFGEIQKNNx79TBczF.jpg',3.1691098537268916,3,'2026-09-10',2,NULL,NULL),(81005,'Jack the Giant Slayer','Jack the Giant Slayer','The story of an ancient war that is reignited when a young farmhand unwittingly opens a gateway between our world and a fearsome race of giants. Unleashed on the Earth for the first time in centuries, the giants strive to reclaim the land they once lost, forcing the young man, Jack into the battle of his life to stop them. Fighting for a kingdom, its people, and the love of a brave princess, he comes face to face with the unstoppable warriors he thought only existed in legend–and gets the chance to become a legend himself.','Prepare for a giant adventure',195000000,197687603,43.349855,5.5,2598,114,'2013-02-27','en','/xtugCVDQiEgQ4Hkxz0KIVaWfvv5.jpg',3.4966678838962615,3,'2026-09-10',2,NULL,NULL),(81188,'守护者联盟','Rise of the Guardians','圣诞老人诺斯、复活节兔子、牙仙和沙人，这些童年的守护者个个长生不老、力量强大又动作敏捷，他们的任务就是尽其所能保护所有孩子的天真与想象力，但一个心怀不轨的坏蛋出现了，他打算抢夺孩子们的希望和梦想来抹去守护者的存在。此时这群深受喜爱的英雄需要杰克冻人助其一臂之力，但这位新加入的守护者却只喜欢玩雪，对拯救世界毫不关心。从北极最深的隐蔽处、上海的屋顶到新英格兰的迷你小镇，守护者在世界各个角落进行一场规模浩大的战争以对抗邪恶又擅于蛊惑人心的的食虫人。他的阴谋是到处散布恐惧来征服全世界，而唯一能够阻止他的就是相信的力量，以及守护者拥有的神奇魔力。','You better believe.',145000000,306941670,61.788035,7.1,1922,97,'2012-11-21','en','/yfzmfWGjcmyugH6FZ13WcsUGiNj.jpg',3.831714778019035,3,'2026-09-10',2,NULL,NULL),(81220,'Everything Put Together','Everything Put Together','Everything Put Together is a 2000 film directed by Marc Forster starring Radha Mitchell and Megan Mullally.',NULL,500000,0,0.046903,5,2,87,'2001-11-02','en','/w9Zk7Sdwy1htXYpqrZF1JUnxB4v.jpg',2.071536214890659,3,'2026-09-10',2,NULL,NULL),(81390,'孤独的死亡之所','A Lonely Place to Die','一行5人的登山小组正在苏格兰高地徒步和攀岩，途中，他们偶然发现一个地下室，里面关着一个塞尔维亚小女孩，没有食物、没有水喝，她就靠着一个通往地面的呼吸管道来维持生命。登山小组决定救她逃出生天。从那一刻开始，整个团队也陷入一个非常危险的境地。绑架女孩的这帮亡命之徒开始追踪登山小组一行人，一场惊心动魄的猫鼠游戏就此展开。他们的处境相当危险，想要活命似乎很难……','Out here, there\'s nowhere to hide.',4000000,25345000,8.30723,6.2,157,99,'2011-04-09','en','/xVYY1U5nYfx2PfJMs6knO8VZRk0.jpg',2.9567350505996917,3,'2026-09-10',2,NULL,NULL),(81796,'太空一号','Lockout','------未来的世界里，地球上已经没有空间供犯人坐牢使用了，于是人类制造出了一个绕着地球飞行的类似于空间站的监狱。在其中的一个监狱里，关押着许许多多的重刑犯，死囚等等极度危险的人。这里保安严密，似乎是坚不可摧的。可是，挂一漏万，意外总是不期而遇。这一天，总统的女儿造访监狱。监狱里的工作人员自然觉得有无限荣光。可是，事情就在总统的女儿和一个犯人对话时出现的错误。很快，一场由各种犯罪头子组成的暴动和越狱就在监狱里发生了起来。总统的女儿死里逃生，但是很明显，她呆在这个卫星一样的监狱里并不安全。地球上的人们也坐如针毡，军队里的人正在想尽办法要把总统的女儿从监狱里救出来，然后彻底抛弃这个孤岛一样的监狱，让它在外太空自生自灭。得到解救总统女儿任务的是一个有着\"污点\"的特工，他在一次任务中，莫名其妙地被陷害成了卖国贼。如今，他只有把总统女儿平平安安地带回地球，才能重获自由。 于是，他走上进监狱，展开了一长营救的血腥之旅……','Take no prisoners.',20000000,32204030,35.232278,5.8,715,95,'2012-04-12','en','/iplHJu10wi1M7ugJ5LPm95PIKfO.jpg',3.295261458301481,3,'2026-09-10',2,NULL,NULL),(81836,'爱在罗马','To Rome with Love','约翰是美国著名的建筑师，他回到罗马度假。年轻的时候，他在罗马住过一段时间，算是故地重游了。在罗马的日子里，他见到了正处在热恋中的杰克和莫妮卡。从他们的恋爱关系里，约翰回想起了自己年轻时的一段刻骨铭心的爱情。 　　杰瑞是一个退了休的歌剧导演，他和自己的妻子菲利普斯飞到意大利去看女儿海丽的未婚夫米开朗基罗。在罗马，杰瑞对未来女婿的那个从事殡葬业的父亲占卡罗很感兴趣。占卡罗是个天生的歌唱家，杰瑞就开始怂恿占卡罗去开始自己的歌唱生涯。 　　莱奥波尔多·皮萨内罗是个很无趣的男人，有一天他从床上惊醒，发现自己变成了意大利最红的明星，每天都是无穷无尽的狗仔队和闪光灯。渐渐地，皮萨内罗熟悉了这一切，但他同时也体会到了成名的代价。 　　安东尼奥从罗马外围的小镇上来到了罗马，他带着自己的未婚妻米莉。希望自己能用表现和漂亮的米莉打动自己的那些在城市里的亲戚，好让他在这里定居，并找到一份城市里的工作。可是他的计划并不成功，安东尼奥莫名其妙地和一个陌生人结了婚，同时他的未婚妻和一个电影明星搞到了一起…… 　　这些故事错综复杂，但是有两个共同点。首先它们都是喜剧；其次，故事都发生在罗马这个充满了惊奇的城市。',NULL,17000000,73244881,15.013386,5.6,546,111,'2012-04-20','en','/yjZSnDvBXF6HqBaPZDZ8sfYpy0r.jpg',3.171185096732241,3,'2026-09-10',2,NULL,NULL),(82505,'街尾之宅','House at the End of the Street','结束了一段破败的婚姻，干练自强的凯瑟琳（伊丽莎白·苏 Elisabeth Shue 饰）带着女儿艾莉莎（詹妮弗·劳伦斯 Jennifer Lawrence 饰）远离芝加哥，搬到了一处位于州际公园丛林深处的房子居住。这里风光秀美，景色宜人，深得母女二人的欢心。美中不足的是，附近一处住宅四年前曾经发生惨绝人寰的杀人案件，失踪的女儿更成为当地人口中盘桓不去的幽怨鬼魂，这一切令人不免心怀惴惴。未过多久，心情烦乱的艾莉莎结识了那户悲剧人家幸存的独子瑞恩（马克斯·希尔莱耶 Max Thieriot 饰）。  　　短暂的交流让艾莉莎隐隐从瑞恩的身上找到些许认同感，却不知这名看似敏感纤细的男孩，心中隐藏着怎样黑暗的秘密……','Fear reaches out... for the girl next door.',6900000,44287131,25.613197,5.6,555,101,'2012-09-21','en','/r3mrCZhhkhZWhnhWOaQGWw8sR0X.jpg',3.198324503281117,3,'2026-09-10',2,NULL,NULL),(82507,'险恶','Sinister','埃里森·奥斯沃特（伊桑·霍克 Ethan Hawke 饰）是一个十几年前小有名气的犯罪小说作家，为了寻找创作灵感，他不惜一次次搬入曾经发生过命案的凶宅。时至今日，为了重现往昔的辉煌，他再次带着妻子崔茜（Juliet Rylance 饰）以及一双儿女特里夫（Michael Hall D\'Addario 饰）和艾丝莉（Clare Foley 饰）搬入一栋凶宅。在收拾阁楼时，他偶然发现一卷家庭录影带，里面记录着房子前主人一家快乐幸福的生活瞬间以及他们被吊死在树上的惨烈画面。此后的日子里，他一遍遍观看录影带，从中寻找罪犯的蛛丝马迹，并且在房屋内的每个角落追查线索。在这一过程中，各种诡异事件相继在家人身上发生。埃里森此时已难以抽身……','Once you see him, nothing can save you.',3000000,77712439,41.045084,6.7,1573,110,'2012-03-29','en','/6LNYg08ShR61OTHCPSYvgxQP97u.jpg',3.6464824196849475,3,'2026-09-10',2,NULL,NULL),(82525,'野蛮人','Savages','影片改编自同名畅销小说，故事讲述了在洛杉矶的拉古纳海滩，两个最要好的毒贩子Chon和Ben拒绝了墨西哥大毒枭为其卖命的要求，后者便绑架了二人的“红颜知己”Ophelia并索要一大笔赎金，为了救出女伴，他们偷偷盗取大毒枭自己的货物以换取赎金；真不啻是一场危险的角逐。','Young Beautiful Deadly.',45000000,82966152,31.856589,6.2,766,131,'2012-07-06','en','/smSHHMNs5epg8lZBUZQ00FnZZP7.jpg',3.36238514502757,3,'2026-09-10',2,NULL,NULL),(82532,'住在家里的杰夫','Jeff, Who Lives at Home','杰夫（杰森·席格尔 Jason Segel 饰）是个整天无所事事的宅男，被母亲莎伦（苏珊·萨兰登 Susan Sarandon 饰）呼来喝去嫌他办事不力，他的哥哥帕特（艾德·赫尔姆斯 Ed Helms 饰）倒是事业不错还结婚了，但与妻子琳达（朱迪·格雷尔 Judy Gr eer 饰）也在闹婚姻危机。一日杰夫接到一个打错的电话，又在公交车上遇见个高中生，球衣背后名字恰好印着打电话人要找的那个名字，一向着迷电影《天兆》的杰夫认为这是一个启示，跟着高中生下车的他遭遇抢劫，无奈游荡在大街上偶遇哥哥帕特，两人又莫名遇见和另一个男人单独吃饭的琳达，帕特拉着杰夫去追查琳达“外遇”的真相，混乱的一天随着杰夫的“启示”而展开……','The first step to finding your destiny is leaving your mother\'s basement.',10000000,4417580,10.409155,6.1,217,83,'2011-09-13','en','/9zn7I5dmZ7IGng87gWVk9K37eq7.jpg',3.025919038124921,3,'2026-09-10',2,NULL,NULL),(82533,'待解救的少女','Damsels in Distress','电影讲述了三个美丽的女孩子跨入大学并一起影响和改变美国式大学的蹩脚生活。主要女演员是浪漫的惠斯特(格蕾塔·葛韦格 饰)、墨守成规的罗斯(梅歌林·艾奇坤沃克 饰)和性感的海泽(卡莉·麦克勒摩尔 饰)。在片中，她们非常欢迎交换生莉莉(阿兰勒·普顿)加入她们小组，并希望通过她的帮助让更多在情感上受挫的学生，一起参与到她们共同合办的一个音乐歌舞项目中。而后，这些女孩与三位男生一起卷入了一系列浪漫的故事。','For these girls... it\'s not what you learn, it\'s whom you educate.',0,0,3.750338,5.6,67,99,'2012-04-06','en','/kF5kdsQbRh1U8Bvjyu6iIxOAsEx.jpg',2.745650087483014,3,'2026-09-10',2,NULL,NULL),(82631,'Won\'t Back Down','Won\'t Back Down','Two determined mothers­, one a teacher, look to transform their children\'s failing inner city school. Facing a powerful and entrenched bureaucracy, they risk everything to make a difference in the education and future of their children','If you can\'t beat the system... change it',0,5310554,2.366251,5.8,40,121,'2012-09-28','en','/7Repugxu8BQXMYSGpzqRrBjFRna.jpg',2.6406975330436167,3,'2026-09-10',2,NULL,NULL),(82650,'小屁孩日记3','Diary of a Wimpy Kid: Dog Days','三年过去了，当年那个不知天高地厚的小屁孩格雷格·赫夫利（扎克瑞·戈登饰），经历了捉弄老师的恶作剧，也经历了和损友的争吵与拌嘴，更为自己喜欢过的姑娘而做出傻事，如今，小屁孩面临着自己青春期的到来－－他，就快升上高中了。\r 　　上高中之前的最后一个暑假到来了。为了纪念自己的学校生活，更是为了贪玩，格雷格决定和死党罗尼（罗伯特·卡普荣饰）一起盘算一个“不一样的暑假”。可是，如何才能让这个暑假过得不一样呢？格雷格想出了一次“暴走旅行”，不过，他的父母可不太同意。于是，为了这次暑假旅行，格雷格开始筹谋起来。当然，这么好玩的事，也没少得了霍莉（佩顿·利斯特饰）的参加。究竟小屁孩的暑假之旅会有什么样的趣事呢？','School\'s Out for the summer',22000000,77112176,13.410919,6,223,94,'2012-08-02','en','/nlvYuvwPJs9PDUMBwJVeSmpNHPq.jpg',3.0316215239642927,3,'2026-09-10',2,NULL,NULL),(82654,'温暖的尸体','Warm Bodies','他（尼古拉斯·霍尔特 Nicholas Hoult 饰）是一只生活在末世的僵尸，依稀只记得自己的名字里有个“R”。与世俗观念不同，作为僵尸他能够思考，依旧残存着些许生前记忆。R生活在废弃的班机上，喜欢收集唱片和饰品，除了吃人外似乎与常人没有两样。这一日，R和僵尸好友们外出觅食，期间遭遇一伙从隔离区来到污染区搜寻药品的人类。在残忍吞噬青年佩里（戴夫·弗兰科 Dave Franco 饰）的大脑后，R拥有了对方的记忆，由此也对和佩里同行而来的女孩朱莉（泰莉莎·帕尔墨 Teresa Palmer 饰）产生恻隐与好感。他将女孩带回自己的住地，通过数日的相处渐渐取得对方的信任，而美丽的朱莉也让R找回作为人类久违的温暖和复杂情感……  本片根据艾萨克·马里昂（Isaac Marion）的同名小说改编。','Cold body. Warm heart.',35000000,116980662,43.742241,6.4,2652,97,'2013-01-31','en','/pvVpl38YOBDOANb0pWbXFb8X3iZ.jpg',3.7132059508646518,3,'2026-09-10',2,NULL,NULL),(82675,'飓风营救2','Taken 2','为了弥合与家人的鸿沟，前中情局特工布莱恩·米尔斯（连姆·尼森 Liam Neeson 饰）邀请情感方面正遭受挫折的前妻丽诺尔（法米克·詹森 Famke Janssen 饰）以及正处在青春期的女儿小金（玛姬·格蕾斯 Maggie Grace 饰）前往伊斯坦布尔度假。然而，他们的快乐假期还没开始，一伙匪徒便盯上了这一家人。一番激烈的较量过后，布莱恩和丽诺尔沦落敌手，小金则成为最后被追捕的对象。而这一切始于布莱恩当初捣毁阿尔巴尼亚黑帮，当初埋下的仇恨种子生根发芽，围着一家人带来前所未有的灾难。身陷囹圄的布莱恩利用身藏的迷你电话指导女儿如何自救求生，而这一边他也想方设法摆脱匪徒的控制。生死攸关，刻不容缓……','First they took his daughter. Now they\'re coming for him.',45000000,376141306,49.353524,6.1,2757,91,'2012-09-27','en','/qpAnPPsYsWYP4QITlfp4reo9547.jpg',3.6638207835297356,3,'2026-09-10',2,NULL,NULL),(82679,'疯狂万圣夜','Fun Size','像许多青春期的叛逆少女一样，蕾恩（维多利亚-嘉蒂丝 饰演）希望通过上大学来摆脱不讲理的母亲乔伊（切尔西-汉德勒 饰演）和捣蛋鬼弟弟阿尔伯特。不过在这之前，她还要设法度过一个状况百出的万圣节。最开始，一切都是那么美妙，蕾恩心仪的男生阿伦-瑞里（托马斯-麦克唐纳 饰演）约她参加一个万圣节派对，这让她欣喜若狂。在一番精心打扮后，蕾恩却被母亲告知，照顾阿尔伯特成了她晚间的首要任务。这还只是噩梦的开始，在带着弟弟心烦意乱地走在参加派对的路上时，姐弟俩在人群中走散了。慌乱的蕾恩和好友艾普莉（简-拉维 饰演）为了能在母亲发现前找到弟弟，并如愿参加派对，不得不向辩论队成员彭与其好友罗斯福特求助。罗斯福特一直暗恋着蕾恩，总想在佳人面前一显身手却弄巧成拙的他，导致一行人多次陷入窘境。在蕾恩等人疯狂地寻找弟弟的同时，阿尔伯特正与富奇（托马斯-米德尔迪奇 饰演）一起趁乱打劫……','Some people just can\'t handle Halloween.',14000000,11417362,7.487843,5.5,134,87,'2012-10-25','en','/h9DYic4zo3Oweb11009FmqZBxN4.jpg',2.8874978138806746,3,'2026-09-10',2,NULL,NULL),(82682,'Gangster Squad','Gangster Squad','Los Angeles, 1949. Ruthless, Brooklyn-born mob king Mickey Cohen runs the show in this town, reaping the ill-gotten gains from the drugs, the guns, the prostitutes and — if he has his way — every wire bet placed west of Chicago. And he does it all with the protection of not only his own paid goons, but also the police and the politicians who are under his control. It’s enough to intimidate even the bravest, street-hardened cop… except, perhaps, for the small, secret crew of LAPD outsiders led by Sgt. John O’Mara and Jerry Wooters who come together to try to tear Cohen’s world apart.','No Names. No Badges. No Mercy.',60000000,105200903,29.041198,6.2,1778,113,'2013-01-10','en','/xXv5wqytmnzC0BG3ul43UDjsqvH.jpg',3.5438043007671265,3,'2026-09-10',2,NULL,NULL),(82684,'冲浪英豪','Chasing Mavericks','《冲浪男人》根据真实故事改编，讲述了英年早逝的著名冲浪运动员杰伊·莫里瑞蒂的生平事迹。  　　半月湾已经成为了冲浪爱好者的圣地，而Mavericks海浪也成为了所有冲浪运动员最想征服的浪潮。  　　杰伊的父亲也是一个冲浪运动员，在杰伊9岁的时候，就带着他一起下海冲浪。杰伊很快就掌握了冲浪的技巧，并从此爱上了冲浪运。在杰伊（约翰尼·韦斯顿 Jonny Weston 饰）15岁时，他在半月湾海岸发现了传说中世界上最大海浪之一的Mavericks。为了征服Mavericks这个巨浪，杰伊恳请冲浪教练弗罗斯提·海森（杰拉德·巴特勒 Gerard Butler 饰）指导自己的技能。在学习指导的探索中，二人逐渐产生亦师亦友的亲情，这也影响着各自的生活态度。在杰伊16岁时，他成功征服了Mavericks海浪，精彩的表演被摄影师捕捉下来，成为了冲浪界的新星和全世界冲浪爱好者所爱戴的偶像。','Legends Start Somewhere',0,0,13.621201,7,216,117,'2012-10-25','en','/7wxJmFqTMcdE05sfWedB6458US1.jpg',3.094012197100331,3,'2026-09-10',2,NULL,NULL),(82687,'纠结之旅','The Guilt Trip','安迪·布鲁斯特 正在准备着一场公路之旅，这是他人生中的第一次公路之旅。但是要和谁一起开始这段旅程却难住了安迪。思来想去，他只好把自己的那个骄傲自大的妈妈乔伊斯 带上了车，和她开始了这段让他毕生难忘的旅途。但是，几乎是一上路，安迪就后悔带上了妈妈。 3000英里的旅途，带来的是妈妈无穷无尽的抱怨和吐槽，而安迪也早已厌烦了这一切。终于，在冲突之后，旅途重新回归平静。而安迪也渐渐发现他和妈妈之间的共同点要远远大于他们之间的区别--也就是说，在母子关系，和亲情上，他们有着不可回避的情感纽带。而妈妈在路途中给安迪的忠告和建议，似乎能让安迪重新找到生活的目标和方向——这正是安迪所迫切需要的……','Get ready for one mother of a road trip',40000000,41863726,15.283444,5.4,284,95,'2012-12-19','en','/55JqWqocsMNx5uanELDRDFqu40J.jpg',3.0361464458531207,3,'2026-09-10',2,NULL,NULL),(82690,'无敌破坏王','Wreck-It Ralph','无敌破坏王（约翰·C·赖利 John C. Reilly 配音）生活在一个80年代出品的低精度游戏中。他的设定身份是一个反派，每天的生活就是在游戏《快手阿修》中大搞破坏，其后由玩家操作的英雄人物快手阿修（杰克·麦克布瑞尔 Jack McBrayer 配音） 会及时赶到进行修补，赢得奖牌，包揽一切荣耀。身为反派，破坏王厌倦了自己的生活，眼看阿修被胜利者的光环围绕，自己却日复一日在无趣中过活，他终于决定改变。单纯的他以为只要自己也能得到一枚奖牌，就可以摆脱反派的身份，于是某日在游戏厅歇业后，破坏王偷偷离开了自己的游戏，前去闯荡其他电子游戏的世界。在途中，破坏王结识了来自《英雄使命》的冷酷队长（简·林奇 Jane Lynch 配音）和来自90年代糖果赛车游戏《甜蜜冲刺》的小女孩云妮（萨拉·丝沃曼 Sarah Silverman 配音）。后者梦想着能上场比赛，但其身份也不允许她梦想成真。破坏王所属的游戏《快手阿修》由于失去了他被认定为系统错误，如不尽快返回，则游戏就会被永久删除；而《甜蜜冲刺》的游戏世界则在悄悄酝酿着一场巨大的、威胁到整个游戏世界的阴谋。这也许是无敌破坏王实现梦想的机会，但也可能是一条不归路…… 他可以扭转乾坤，成为一名真正的英雄吗？','The story of a regular guy just looking for a little wreck-ognition.',165000000,471222889,62.341073,7.1,4570,108,'2012-11-01','en','/nrEupcBwf4O1zihCM34NoXusZDq.jpg',4.06168077010757,3,'2026-09-10',2,NULL,NULL),(82693,'乌云背后的幸福线','Silver Linings Playbook','中学教师帕特因妻子出轨精神受挫入院，出院后寄居父母家倍感压抑。聚会中他结识性格尖锐的蒂凡妮，二人起初冲突不断，相处中互相被对方吸引。蒂凡妮邀他搭档参加舞蹈比赛，历经磨合，两人收获真爱，走出人生低谷。','Watch For The Signs',21000000,205738714,63.599973,6.9,4742,122,'2012-09-08','en','/fhHB1uvfFKKFbj6bTKE8xdtsjKi.jpg',4.02184720233433,3,'2026-09-10',2,NULL,NULL),(82695,'Les Misérables','Les Misérables','贫苦的冉·阿让（休·杰克曼 Hugh Jackman 饰）为了挨饿的孩子去偷面包，结果被判处19年的苦役。出狱后，走投无路的他偷走了收留他过夜的主教的银器潜逃，被警察捉回。主教声称银器是送给他的，使他免于被捕。主教的言行感化了他，他化名马德兰，从此洗心革面奋发向上开始新生活。但缉拿过他的警长沙威（罗素·克劳 Russell Crowe 饰）却一心要找他麻烦。在得知了芳汀（安妮·海瑟薇 Anne Hathaway 饰）的悲惨遭遇后，他承诺照顾她的私生女柯赛特（阿曼达·塞弗里德 Amanda Seyfried 饰）。八年后，柯赛特爱上了共和派青年马利尤斯（埃迪·雷德梅恩 Eddie Redmayne 饰），轰轰烈烈的巴黎人民起义爆发了，无赖德纳迪埃（萨莎·拜伦·科恩 Sacha Baron Cohen 饰）和他又狭路相逢，而多年来从未放弃追捕他的沙威又出现在他的面前……','Fight. Dream. Hope. Love.',61000000,441809770,48.356214,7.1,1884,157,'2012-12-18','en','/6CuzBs2Lb8At7qQr64mLXg2RYRb.jpg',3.795515700825451,3,'2026-09-10',2,NULL,NULL),(82696,'希望温泉','Hope Springs','影片讲述的是一对结婚30年的夫妻利用一个周末来到度假胜地来拯救他们的婚姻故事。\r 　　Kay（梅丽尔·斯特里普）和Arnold（汤米·李·琼斯）是一对彼此忠诚的好伴侣，然而漫长的婚姻让他俩的生活缺少激情。所以，当Kay听说小镇大希望温泉来了一位婚姻专家时（史蒂夫·卡瑞尔），她说服极其固执、生活固守成规的老公一起，去小镇旅行一周顺便治疗他们的婚姻。希望借机重燃激情，虽然这对二人来说都是不小的挑战。','Sometimes to keep the magic, you need to learn a few tricks.',30000000,114281051,12.967137,5.8,284,100,'2012-08-07','en','/n6l5c6vOCWaAYBB42ITmc2hFhSB.jpg',3.0645171187955604,3,'2026-09-10',2,NULL,NULL),(82700,'重返地球','After Earth','影片讲述地球毁灭1000年以后，一对父子的飞船遭遇重创，这个自甘堕落和疯狂的年轻人尝试拯救自己，修复和父亲之间的关系的故事。\r 　　在地球严重毁灭、人类迁移至尊星后的1000年，传奇将军赛弗·瑞奇（威尔·史密斯 饰）在执行任务返回途中，不慎遭遇一场“小行星风暴”，导致自己与13岁儿子契丹·瑞奇（贾登·史密斯 饰）驾驶的飞船坠落在如今异常陌生的地球上。为了拯救身负致命伤的父亲，同时更为了成为一名真正的战士，契丹在这颗险象环生的星球上开始了一场惊心动魄的徒步穿越。','Danger is real, fear is a choice',130000000,243843127,42.840582,5,2532,100,'2013-05-30','en','/qkDBD5PX9HfDZqi48FjFkb9cLZD.jpg',3.374246041680419,3,'2026-09-10',2,NULL,NULL),(82702,'驯龙高手2','How to Train Your Dragon 2','故事发生在前部的五年之后，赛龙比赛已成为岛上最受欢迎的一项运动，男女主人公小嗝嗝与阿斯特丽德驾着自己的龙开始探索未知的世界。他俩发现自己已卷入一场战争的中心地带，必须率领族人捍卫这片土地的平静。','The training is over.',145000000,609123048,100.21391,7.6,3106,102,'2014-06-12','en','/d13Uj86LdbDLrfDoHR5aDOFYyJC.jpg',4.170310533778072,3,'2026-09-10',2,NULL,NULL),(82703,'天才眼镜狗','Mr. Peabody & Sherman','世界上“最聪明狗狗” 皮博迪先生收养了一个人类小男孩舍曼，为了让他的养子能更好的见证世界的奇妙，他自己发明了一台时光穿梭机。皮博迪与舍曼一起穿越时空，四处冒险，并闹出各种笑话。穿越的旅途中，他们遇到了法国大革命时期的玛丽皇后、埃及法老王、特洛伊木马、达芬奇及蒙娜丽莎等著名人物和事件，天才狗爸爸更是为小男孩支招，帮他赢得可爱但又傲慢的女同学佩妮的芳心。  世界上最有成就的狗皮博迪先生和他收养的调皮小子舍曼常常用时光机踏上无论对人对狗都无比惊险刺激的时空旅行。舍曼为了讨好朋友佩妮，带着她坐上时光机兜风，却不慎在宇宙中撕开了一个洞，搅乱了最重要的历史事件。为了不让他们给过去、现在和未来造成永久性的改变，皮博迪先生必须挺身而出拯救他们，也因此面临着史上最严峻的挑战：如何为人父母。','He\'s Leaving His Mark On History',145000000,272912430,38.73494,6.7,843,92,'2014-02-07','en','/q3kzJ9mIe59BQdRqKJNX3lTFBva.jpg',3.479964465721276,3,'2026-09-10',2,NULL,NULL),(82990,'灵动：鬼影实录4','Paranormal Activity 4','五年前，仿佛被魔鬼所控制的凯蒂杀害了自己的男朋友、姐姐、姐夫，并带走他们尚在襁褓中的孩子亨特，不知所终。时间来到2011年，一个平凡幸福的四口之家，美丽女孩爱丽克丝过着无忧无虑的生活，她每天和男友本通过视频聊天，平日里本也会拿着摄像机随时拍摄。某天，无依无靠的小男孩罗比入住爱丽克丝的家，罗比沉默寡言，并声称有一个名叫托比的朋友。爱丽克丝他们起初不以为意，但是渐渐却发现房屋里接二连三有奇怪诡异的事情发生。在本的建议下，他们在家中各个角落安装摄像头，监控着白天夜晚所发生的一切。屏幕前，令人匪夷所思且毛骨悚然的景象悄悄上演……','It\'s closer than you think',5000000,142817992,20.326337,5.2,563,95,'2012-10-17','en','/dznYwc6iUgAzC2O4uJQclg4Uphe.jpg',3.1364956634752934,3,'2026-09-10',2,NULL,NULL),(83542,'云图','Cloud Atlas','1850年，南太平洋，美国公证人亚当·尤因 在船上被不明寄生虫病折磨，他用日记记录下自己所见所闻；1931年，苏格兰，落魄青年罗伯特·弗罗比舍 为音乐大师记录曲谱，受到半本旅行日记的启发创作出了恢宏壮阔的《云图六重奏》；1975年，美国加州，小报记者路易莎·雷 冒着生命危险调查一桩核电站丑闻，在老唱片店她被一首不知名的乐章打动；2012年，英国伦敦，被囚禁在养老院的出版商蒂莫西·卡文迪什 揣着一叠由女记者写成的纪实文学，打算将自己的“越狱经历”拍成电影；乌托邦未来，首尔，餐厅服务员克隆人星美-451 开始形成自我意识和反抗人类，她在人类图书馆看了一部飞跃老人院的电影；文明毁灭后的未来，夏威夷，牧羊土着扎克里 对高科技文明的先知心怀敌意，他的部落唯一相信的女神叫星美…… 不同的人物、场景和事件在时空中更迭变幻，不变的是每个主角身上都带有彗星形状的胎记。它像亘古灵魂的烙印，将人性中的反抗精神代代延续，最终织成一幅浩瀚璀璨的云图。','Everything is Connected',102000000,130482868,73.872343,6.6,2977,172,'2012-10-26','en','/8naVv2Xu3rWI5JKHz0vCujx6GaJ.jpg',3.8569571903970816,3,'2026-09-10',2,NULL,NULL),(83588,'不知所踪','Middle of Nowhere','露比是一个城市里普通人，开着公交车，这在城市里来来回回地穿梭。她正在努力让自己不去回想起那些不愉快的往事。4年前，她还是一个充满活力的医学院学生，她碰到了一个叫做德瑞克的男人，她和他结了婚，过上了自认为的幸福生活。可是不幸却降临到了这个小家庭身上，德瑞克犯了罪，被判了8年的有期徒刑。于是，这对新婚的夫妻从此便过上了大墙内外的生活。对于露比来说，这种生活更为困难一些，因为她要学会自己独处、并且慢慢等待时间的消逝……　　　 　　德瑞克获得了减刑的机会，而露比也在世俗的生活中遇见了一个叫做布莱恩的公车司机。一面是还有刑期但是就要出狱的老公，而另一边则是唾手可得，并没有道德焦虑的幸福生活。露比发现自己处在刀锋的两端，她的生活开始慢慢进入纠结和困顿。',NULL,0,0,2.836537,6.6,7,101,'2012-10-12','en','/s0Jtw4YYRQ460vo0QfrjrdLqJCf.jpg',2.293198321292348,3,'2026-09-10',2,NULL,NULL),(83666,'月升王国','Moonrise Kingdom','Set on an island off the coast of New England in the summer of 1965, Moonrise Kingdom tells the story of two twelve-year-olds who fall in love, make a secret pact, and run away together into the wilderness. As various authorities try to hunt them down, a violent storm is brewing off-shore – and the peaceful island community is turned upside down in more ways than anyone can handle.','A tormenting and surprising story of children and adults during the stormy days of the summer of 1965.',16000000,68263166,41.083914,7.6,1662,94,'2012-05-16','en','/y4SXcbNl6CEF2t36icuzuBioj7K.jpg',3.848314996461125,3,'2026-09-10',2,NULL,NULL),(83686,'妙笔生花','The Words','本片是《创：战纪》两位编剧布莱恩·克鲁格曼和李·斯特恩斯奥的导演处女作。  　　罗里（布莱德利·库珀 Bradley Cooper 饰）虽然一直在努力写作，却从未得到出版社的青睐，时不时还要靠父亲的接济度日。和新婚妻子多拉（佐伊·索尔达娜 Zoe Saldana 饰）去巴黎度 蜜月时在二手店买了一个书稿包。罗里偶然发现了里面的一份旧小说手稿，内容深深吸引了他。最后他把小说占为己有并出版，终于让他一举成名，成为文学界的新锐。而一个神秘的老人（杰瑞米·艾恩斯 Jeremy Irons 饰）突然出现，告诉罗里自己才是小说的作者，并给他讲述了一个小说中发生在巴黎的真实爱情故事。  　　面对这一切，罗里有了无法逃遁的负罪感。他会把成功当做理所当然，还是一场道德考验？','There\'s more than one way to take a life.',6000000,13231461,14.988746,6.4,379,96,'2012-09-07','en','/aJtPLZS7tlpiQl6pEr8H42K565x.jpg',3.1874180026509964,3,'2026-09-10',2,NULL,NULL),(83770,'在路上','On the Road','改编自同名原著小说，小说创作于1957年，表现了战后美国青年的精神空虚和浑浑噩噩的状态，被视为“垮掉的一代”奠基之作，主要写“我”同一个狂热的垮掉分子迪安·莫里亚蒂以及其他几个朋友三次从美国西海岸到东海岸的穿梭旅行。在自己的父亲去世之后，处在天人交战、心情不佳时期的作家萨尔·派瑞戴斯决定要开始一趟横跨美国的旅途，去寻找“它”的意义。和他一起上路的是他的好朋友迪恩·莫里亚蒂。迪恩是一个天生的旅行家和神秘主义者。这一路上，发生了各种各样的怪事，而这两个年轻人也渐渐找到了自己生命的方向。','The best teacher is experience.',25000000,8784318,14.613152,5.5,301,137,'2012-05-22','en','/d77xMAuWpCy8nEkWJaOpH30VXbK.jpg',3.053428173718639,3,'2026-09-10',2,NULL,NULL),(83860,'怀胎十月','October Baby','\"帷幕升起，汉娜心怀激动地开始了她在大学剧团的首场演出，但她却因为身体不适晕倒在舞台上；通过种种检查化验，最后医生得出了这样的结论：汉娜其实是父母失败流产的幸存儿，但这导致了她身体有某些天然的缺陷。听到这一消息，汉娜觉得困惑和失落，而且很愤怒。\r 汉娜在好友贾森的鼓励下，开始了一段新生的旅程，在旅程中她开始重新梳理自己的生命，她越来越坚信每个生命都是美丽、独一无二，不应该被不负责任的堕胎剥夺……\"','Every Life Is Beautiful',0,5355847,1.86221,6.8,35,107,'2011-10-30','en','/dZWU5Hn4lkhid3MqVMCEPk9z9QI.jpg',2.6256414806815447,3,'2026-09-10',2,NULL,NULL),(84174,'未婚女子','Bachelorette','雷根（克尔斯滕·邓斯特 Kirsten Dunst 饰），吉娜（丽兹·卡潘 Lizzy Caplan 饰）和凯蒂（艾拉·菲舍尔 Isla Fisher 饰）是学生时代的好友，年少时期的轻狂为三个女人带来的美好的回忆，但对另一个女孩贝姬（瑞贝尔·威尔森 Rebel Wilson 饰）来说，事情就完全不同了。原来，心宽体胖的贝姬曾经经常遭到雷根一伙人的嘲笑，她们甚至为她取了“猪脸”这样一个可笑又愚蠢的外号。\r 时间流逝，贝姬即将结婚的消息犹如一枚炸弹丢到了三个女人的身边，不仅如此，贝姬还邀请了她们来做她的伴娘，“猪脸”都有了老公，三个漂亮的单身女人感到了危机。在婚礼之前，雷根决定为贝姬办一场单身派对，但此时的她不会想到，这个派对会带来怎样的麻烦与疯狂。','Old habits party hard.',3000000,11947954,20.95282,5.3,444,87,'2012-08-06','en','/eF7AQKws5MXyMD13US8KFePtDVf.jpg',3.1135022374069083,3,'2026-09-10',2,NULL,NULL),(84175,'Beasts of the Southern Wild','Beasts of the Southern Wild','Hushpuppy, an intrepid six-year-old girl, lives with her father, Wink in \'the Bathtub\', a southern Delta community at the edge of the world. Wink’s tough love prepares her for the unraveling of the universe – for a time when he’s no longer there to protect her. When Wink contracts a mysterious illness, nature flies out of whack – temperatures rise, and the ice caps melt, unleashing an army of prehistoric creatures called aurochs. With the waters rising, the aurochs coming, and Wink’s health fading, Hushpuppy goes in search of her lost mother.','I  gotta take care of mine.',1800000,21107746,12.471239,6.8,403,93,'2012-06-29','en','/4UXDPBMpgpCOehcj9avuxmQLuea.jpg',3.2389117210910836,3,'2026-09-10',2,NULL,NULL),(84178,'Black Rock','Black Rock','Three childhood friends set aside their personal issues and reunite for a girls’ weekend on a remote island off the coast of Maine. One wrong move turns their weekend getaway into a deadly fight for survival.','Not every island is a paradise.',0,0,7.207051,4.9,78,83,'2012-01-21','en','/dkUDpTgP634Mt7fl2rR5N7P9HRS.jpg',2.7638722948383476,3,'2026-09-10',2,NULL,NULL),(84184,'Celeste & Jesse Forever','Celeste & Jesse Forever','Celeste and Jesse met in high school and got married young. They laugh at the same jokes and finish each other’s sentences. They are forever linked in their friends’ minds as the perfect couple – she, a high-powered businesswoman and budding novelist; he, a free spirit who keeps things from getting boring. Their only problem is that they have decided to get divorced. Can their perfect relationship withstand this minor setback?','A Loved Story',0,3094813,9.436431,6.4,163,91,'2012-08-03','en','/5Cr8kW7DjZEORU8jI32bqyHSGKW.jpg',2.9785240546567255,3,'2026-09-10',2,NULL,NULL),(84188,'Compliance','Compliance','Sandra is the manager at a fast-food restaurant, and Becky is her teenaged counter girl who really needs the job. One stressful day, a police officer telephones and accuses Becky of stealing money from a customer’s purse, which Becky vehemently denies. Sandra, overwhelmed by her managerial responsibilities, complies with the officer’s orders to detain Becky, beginning a nightmare that tragically blurs the lines between expedience, prudence, legality and reason.','Power. Manipulation. Obedience.',0,319285,8.942203,6.3,221,90,'2012-08-23','en','/bLdu28fr9txYlHLmEOyGplDT3nH.jpg',3.0404704626459367,3,'2026-09-10',2,NULL,NULL),(84197,'Filly Brown','Filly Brown','“Majo” Tonorio, a.k.a. Filly Brown, is a raw, young Los Angeles hip-hop artist who spits from the heart. When a sleazy record producer offers her a crack at rap stardom, Majo faces some daunting choices. With an incarcerated mother, a record contract could be the ticket out for her struggling family. But taking the deal means selling out her talent and the true friends who helped her to the cusp of success.','This is my life.',0,0,0.106949,5.9,10,100,'2013-04-19','en','/5CdRIAll52h0s0cbFH0VKiCp7pg.jpg',2.353859264212289,3,'2026-09-10',2,NULL,NULL),(84200,'激情热线','For a Good Time, Call...','剧情简介  　　由两位80后美女阿丽·格雷勒、劳伦·米勒主演的喜剧《激情热线》首度曝光限制级预告片。两位性感美女、一条电话热线，且不说剧情如何，单单这样的设定便相当吸引眼球。影片的路线并非情色到底，故事讲述两个女孩在纽约合租，当她们为生计发愁时，开始化敌为友共同经营一条提供情色聊天的电话热线，也让她们重新理解了青春、友谊与爱情。','Lose your hang-ups. Find your calling.',850000,1243961,14.238376,5.8,110,85,'2012-08-31','en','/9eIlVo8lvk9fmfP05JGFKlPha80.jpg',2.8766631094465676,3,'2026-09-10',2,NULL,NULL),(84204,'Grabbers','Grabbers','Something sinister has come to the shores of Erin Island, unbeknownst to the quaint population of this sleepy fishing village resting somewhere off Ireland’s coast. First, some fishermen go missing. Then there is the rash of whale carcasses suddenly washing up on the beach. When the murders start, it’s up to two mismatched cops – an irresponsible alcoholic and his new partner, a by-the-book woman from the mainland – to protect the townsfolk from the giant, bloodsucking, tentacled aliens that prey upon them. Their only weapon, they discover, is booze. If they want to survive the creatures’ onslaught, everyone will have to get very, very drunk!','For the locals on Erin Island, it\'s last orders.',0,0,9.451228,6,140,94,'2012-08-10','en','/n1CkFfuDCh4NDZgaXmyna3V0Hxc.jpg',2.9245343347194406,3,'2026-09-10',2,NULL,NULL),(84318,'The Other Dream Team','Kita svajonių komanda','The incredible story of the 1992 Lithuanian basketball team, whose athletes struggled under Soviet rule, became symbols of Lithuania\'s independence movement, and – with help from the Grateful Dead – triumphed at the Barcelona Olympics.',NULL,0,0,0.388401,6.9,7,89,'2012-09-28','en','/ngO7nruFL9bUn6ezxik7ynC8Af0.jpg',2.2884629381704675,3,'2026-09-10',2,NULL,NULL),(84329,'Robot & Frank','Robot & Frank','A delightful dramatic comedy, a buddy picture, and, for good measure, a heist film. Curmudgeonly old Frank lives by himself. His routine involves daily visits to his local library, where he has a twinkle in his eye for the librarian. His grown children are concerned about their father’s well-being and buy him a caretaker robot. Initially resistant to the idea, Frank soon appreciates the benefits of robotic support – like nutritious meals and a clean house – and eventually begins to treat his robot like a true companion. With his robot’s assistance, Frank’s passion for his old, unlawful profession is reignited, for better or worse.','Friendship doesn\'t have an off switch',2500000,3325038,23.419061,6.8,450,85,'2012-08-16','en','/eoxxXAVse7gjaqhsuEaB3Tkvzij.jpg',3.2931114591955866,3,'2026-09-10',2,NULL,NULL),(84332,'安全没有保障','Safety Not Guaranteed','新加入杂志社的布里特（奥布瑞·普拉扎饰）一直都小心翼翼的做着实习生的工作，在一次杂志编辑头脑风暴的会议上，编辑们讨论起报纸上的一则有趣的征人广告：我要找个人跟我一起穿越时空，回到过去。我不是开玩笑。完成这事，回来之后，我会给你钱。注意：自己带武器，安全没有保障，因为这事之前我也就干过一回。资深杂志编辑杰夫（杰克·M·约翰森饰）觉得这事或许是好的素材点子，因此决定带俩个实习生去接触登广告的人，而布里特也被选中，加入了这个三人组合。 　　三人找到了登广告的人，他们发现这位名叫肯尼思·卡洛维（马克·杜普拉斯饰）的男子是一名超市售货员，业已中年的他看起来有些神神叨叨，作为三人中唯一的女性，布里特使劲浑身解数，终于取得了布里特的信任。他开始训练布里特打枪、跑步，做穿越时空前的准备，在和肯尼思朝夕相处的过程里，布里特开始被这个孤独的男人所吸引，渐渐的认同了他的信念。随着穿越之日的接近，布里特发现，还有另一股神秘势力在监视着肯尼思。究竟穿越时空是不是真的，监视肯尼思的又是什么人？布里特开始慢慢的接近事情的真相……','What would you go back for?',750000,4007792,25.186002,6.8,556,85,'2012-06-08','en','/hRD2B7PhEUkK1ghTrU8UK5VBawt.jpg',3.353506570894923,3,'2026-09-10',2,NULL,NULL),(84355,'姐妹情深','Your Sister\'s Sister','Jack（马克·杜普拉斯 Mark Duplass 饰）因为弟弟Tom的去世已经消沉很长一段时间了，他的好朋友，也是Tom的前女友Iris（艾米莉·布朗特 Emily Blunt 饰）劝他骑着单车到她父亲在一座小岛上的屋子里去思考人生。来到屋子的Jack却意外发现了Iris的姐姐Hanna（罗丝玛丽·德薇特 Rosemarie DeWitt 饰）也在。两人喝了酒，相谈甚欢。Jack得知Hanna是个女同性恋，最近刚刚和相恋七年的女友Pam分手。最后两人情不自禁地发生了性关系。第二天，因为工作调整而放假的Iris也来到了这屋子里。Jack和Hanna相约保守秘密。Iris向姐姐坦诚她对Jack的喜爱。而孤独的Hanna和Jack上床的真正原因在于为了获取精子生个小孩....三人的关系陷入了僵局。','A comedy about doing the right thing with the wrong person.',125000,3200000,12.833247,6.5,137,90,'2011-09-11','en','/m6xeI6iuIpNcoyOSfG01JTaoVYx.jpg',2.9514331568745686,3,'2026-09-10',2,NULL,NULL),(84401,'Sholem Aleichem: Laughing In The Darkness','Sholem Aleichem: Laughing In The Darkness','A riveting portrait of the great writer whose stories became the basis of the Broadway musical Fiddler on the Roof. Sholem Aleichem: Laughing in the Darkness tells the tale of the rebellious genius who created an entirely new literature. Plumbing the depths of a Jewish world locked in crisis and on the cusp of profound change, he captured that world with brilliant humor. Sholem Aleichem was not just a witness to the creation of a new modern Jewish identity, but one of the very men who forged it.','Before there was Fiddler, there was Tevye... and the man who created him.',500000,845188,0.109579,7,2,93,'2012-02-24','en','/k5X4gevz5mSY3KESnZNoBHo26qY.jpg',2.0733222462596372,3,'2026-09-10',2,NULL,NULL),(84659,'The Naked Ape','The Naked Ape','The Naked Ape is a coming-of-age film following three teenagers on a road trip across the Pacific Southwest.',NULL,0,0,0.077577,5,1,110,'2006-09-16','en','/pGaLUnim5CG5booE4Xe3N7qKooc.jpg',1.9840169910802565,3,'2026-09-10',2,NULL,NULL),(84892,'壁花少年','The Perks of Being a Wallflower','查理（罗根·勒曼 Logan Lerman 饰）是个害羞和孤独的高中新生，拥有超越年龄的敏感和泪腺，总是默默观察身边的家人和朋友，是个典型的「壁花少年」。他的青春期充满各种挫折，先后经历了阿姨为给他买生日礼物去世、最好朋友自杀、受同学排挤欺负、单恋没有回应等各种事情。然而查理还不是最惨的，因为和他一样被生活逼入墙角罚站的人实在太多。他幸运的拥有一个开明的老师和两个高年级的好友：叛逆娇俏的少女珊（艾玛·沃森 Emma Watson 饰）和自信满满的同志男生帕特里克（埃兹拉·米勒 Ezra Miller 饰），他们让查理明白了有时候不能永远旁观，必须要参与进来才能拥有属于自己的精彩。','We are infinite.',13000000,33400000,43.444135,7.7,2968,102,'2012-09-20','en','/aKCvdFFF5n80P2VdS7d8YBwbCjh.jpg',4.051695087927949,3,'2026-09-10',2,NULL,NULL),(85350,'少年时代','Boyhood','理查德·林克莱特执导，是一部前所未有的电影作品。这部极具朴实风格的时代之作，历时十二年在其家乡得克萨斯州拍摄完成，记录了一个名叫梅森的男孩、他离异的父母以及他姐姐所经历的身心变迁。林克莱特并未聚焦于人生重大节点，而是撷取那些构成生活的、细微的日常片段，打造出一部表演浑然天成、充满幽默感的画卷，让岁月在其中自然流转。本片让我们得以在银幕上以纪录片般的真实感观看人物的成长衰老，同时又将我们牢牢吸引在一个描绘极致平凡生活的虚构叙事中，它所拥有的力量，唯有电影艺术方能驾驭。[标准收藏]','12 years in the making.',4000000,44349000,43.40352,7.5,1971,164,'2014-06-05','en','/2BvtvDUyxiMJ4dmKfiQf4qdOHQN.jpg',3.884280994929287,3,'2026-09-10',2,NULL,NULL),(85446,'舞出我人生4','Step Up Revolution','影片讲述一个富商的女儿艾米莉（凯瑟琳·麦考米克 饰）前往迈阿密想要成为一名专业的舞者，她结识了一个顶尖舞蹈团的领队西恩（瑞安·古兹曼 饰），并很快坠入爱河。为了舞团的生存，他们必须拿下一个很重要的赞助项目。但是这时艾米莉的父亲横插一脚，企图改变和拆散舞团，艾米莉、西恩和舞团的其他成员必须团结起来，捍卫并且实现他们的梦想。','One Step Can Change Your World',33000000,140470746,29.775441,6.7,663,99,'2012-07-26','en','/2oY7b9w0dNTv0m0XBSvFzg13mgt.jpg',3.3968449858352328,3,'2026-09-10',2,NULL,NULL),(85860,'致命格斗','The FP','Two rival gangs fight for control of Frazier Park -- a deadly arena in competitive dance-fight video game \"Beat-Beat Revolution.\"','An Ancient Game Becomes A Deadly Sport.',0,0,0.838957,4.5,11,82,'2011-03-13','en','/nmo8R1FpBEsC80qYOaXtx2vMrSa.jpg',2.3680924515537476,3,'2026-09-10',2,NULL,NULL),(86304,'超级英雄必死','All Superheroes Must Die','夜深人静，先锋（Jason Trost 饰）、魅影（Sophie Merkley 饰）、利刃（Lucas Till 饰）和铁壁（Lee Valmassy 饰）这四个超级英雄从昏迷中醒来，他们全然不知道发生了什么事，也不知晓自己身处何方，而且被个人的手臂都留下了神秘针孔。不久后，身边的电视开启，他们的老对手瑞克·肖（James Remar 饰）现身。瑞克曾设定无数号称完美的犯罪计划，但无一例外都遭到这些英雄的破坏。这个恼羞成怒的恶棍决心跟四个英雄玩上一场危险游戏，他在一百多名无辜百姓身上安装了各种致命装置，药效拯救这个城市还有百姓，超能力被锁定起来的英雄们必须按照瑞克的指示完成各种任务。','May The Best Man Win',0,0,3.545991,4.2,13,78,'2011-10-26','en','/lt5hf1FtNEjEOHJpjeWO2YD3tNE.jpg',2.404885629963265,3,'2026-09-10',2,NULL,NULL),(86331,'巴黎Q娘','Q','塞西尔（Déborah Révy 饰）刚刚丧父，而她排解悲痛的方式竟然是成为性瘾者，她向男友索取无度，还当着他面勾搭他朋友；她认识了修车店男孩麦特（Gowan Didi 饰），不住挑逗他，又不和他来真的；她在渡轮上勾引了一个英国教授，带他到海边用男女错位的方式做爱……似乎她需要用男人对她欲望来证明自己的存在。麦特本来有个女朋友爱丽丝（Helene Zimmer 饰），她出身保守，缺乏安全感，和麦特的关系岌岌可危。巧合之下，爱丽丝结识了塞西尔，被她引领入性的另一个领域；麦特不断被塞西尔诱惑，最终发现自己仍爱着爱丽丝；塞西尔的行为越来越出格，开始筹划群体性爱派对，但闯进来找她的男友还是抱着拯救她的念头……  　　继《露西雅与欲乐园》后，作风开放惹争议的异色导演罗虹布尼克（Laurent Bouhnik）推出法国近代影史上最大胆赤裸的都会女性爱欲实录。法国影坛嫩模黛柏哈海薇真实性爱演出，毫不畏惧。  一位身材姣好的妙龄女子赛西(黛柏哈海薇饰)堪称欲望的化身，犹如帕索里尼经典《定理》中的访客般席卷众人，所到之处皆令人为之疯狂。一群被社会困境吞噬的迷惘年轻人，碰上性开放的赛西，男人为她倾倒，奉她为女神，女人为之着迷，视她为启蒙者。',NULL,1344000,0,20.422246,4.1,140,103,'2011-09-14','fr','/yBTElYnRkwySYzMunE6urPT9LvT.jpg',2.857704376302264,3,'2026-09-10',2,NULL,NULL),(86549,'燃烬八月','August','成功设计师特洛雷（穆雷·巴特利特 Murray Bartlett 饰）回到洛杉矶，发现旧爱强纳森（丹尼尔·杜根 Daniel Dugan 饰）已另有新欢——阿根廷型男劳尔（阿德里安·冈萨雷斯 Adrian Gonzalez 饰）。当初的分手或许无因，重逢也并非云淡风轻：强纳森看似掀开新的一页，但从未对当年真正释怀；特洛雷倦鸟知返，却不知如何从头再来；劳尔为留在美国和强纳森的女性友人结了婚，但这显然并不足以羁绊男友的心。骄阳似火的八月天，前度情人再度相逢，汗水与泪水交缠，欲望与理智鏖战，剪不断理还乱。当爱情死灰复燃，该如何决定得失挑选？《燃烬八月》改编自希伯来裔导演埃尔达尔·拉帕波特自己导演的2005年短片《灰烬之后》，两位男主角都没有更换。拉帕波特用六年时间对故事大纲做出了扩容，令原来的二人对戏变成虐心的三角关系。炽烈汹涌的情欲，优美深广的长镜，开到荼蘼的希伯来配乐，令这部电影获得了2011年Iris电影节最佳剧情长片奖。',NULL,0,0,1.419431,6.2,15,100,'2011-06-09','en','/l54G35FYDnA7gr2UglHn1HZKPEI.jpg',2.439613622317164,3,'2026-09-10',2,NULL,NULL),(86812,'倾听我的声音','Sound of My Voice','Peter和Lorna潜入旧金山的一个神秘组织，这个组织由一个名叫Maggie的女人控制，这个女人从未离开过她的地下室，但却得到一干信徒的盲目追随，他们为她弄来食物、打扫房间、甚至奉献血液为之输液……Peter和Lorna带着隐藏的摄像机，希望揭穿Maggie的骗局',NULL,0,0,6.192383,6.3,108,85,'2011-01-22','en','/6wStc532wuBrW2NZM3TicEWDmaL.jpg',2.8738990813986,3,'2026-09-10',2,NULL,NULL),(86825,'斯托克','Stoker','恬静娴淑的女孩印蒂雅·斯托克（米娅·华希科沃斯卡 Mia Wasikowska 饰）18岁生日之际，惊闻父亲理查德（德蒙特·莫罗尼 Dermot Mulroney 饰）死于意外的噩耗。相对于和丈夫一向不睦的母亲伊芙琳（妮可·基德曼 Nicole Kidman 饰），从小和父亲一起打猎的印蒂雅自然承受难以排遣的哀伤与痛苦。葬礼当天，一名有着和善笑容却周身散发阴冷气息的男子毫无征兆出现在斯托克母女身边。他是理查德的弟弟查理（马修·古迪 Matthew Goode 饰），自称刚刚结束环球旅行赶来。伊芙琳对查理表现出不加掩饰的热情和好感，并主动留查理在家中居住。而印蒂雅对这个突然到来的叔叔怀有深深的抗拒与戒备之心。紧张的气氛在这个刚刚失去男主人的家中蔓延，斯托克一家朝向万劫不复的深渊疾驰……','Innocence Ends.',12000000,12077441,27.322212,6.5,882,99,'2013-02-28','en','/t7HVYhw5vmUrffaqRaojhlhHzhO.jpg',3.4328220723379825,3,'2026-09-10',2,NULL,NULL),(86829,'醉乡民谣','Inside Llewyn Davis','美国怪诞风貌的造梦者乔尔与伊桑·科恩兄弟，借勒维恩·戴维斯这一角色呈现了他们最杰出的创作之一——这位歌手在六十年代初格林威治村民谣热潮的边缘勉强维生。奥斯卡·伊萨克以突破性表演塑造的勒维恩（其形象松散取材于民谣传奇戴夫·范·容克）才华横溢却又暴躁、粗鲁且自我毁灭。影片由摄影师布鲁诺·德尔邦内尔以动情的镜头捕捉他在严寒冬日城市里循环往复的漂泊轨迹，以辛酸幽默与间或超现实的笔触实现。由T·本恩·伯内特策划的民谣原声贯穿全片，本片再次印证科恩兄弟的世界里，历史未必由胜者书写。',NULL,11000000,32935319,36.319205,7.2,834,105,'2013-10-06','en','/z3wkJMclpXiqMeXlvYGsWvX4Hto.jpg',3.5517155072672146,3,'2026-09-10',2,NULL,NULL),(86834,'诺亚方舟：创世之旅','Noah','《诺亚方舟》根据圣经故事改编，由达伦·阿伦诺夫斯基亲自创作剧本和同名漫画。这是一个没有希望的世界，没有雨、没有粮食，军阀和野蛮的游牧部落统治一切。诺亚是这个残酷世界的一个好人，一个久经沙场的战士、法师和治疗师，他只想和家人过上安宁平静的生活。然而，每天晚上他都会被一个噩梦所折磨，梦里整个世界被一场大洪水吞没。久而久之他意识到，这正是造物主给他的讯号，上帝要惩罚人类，把他们杀光……但他给了诺亚一个机会，让他得以保存地球上的物种。','The end of the world is just the beginning.',125000000,362637473,46.115758,5.6,2350,139,'2014-03-20','en','/vCxUSTNWX3zxW738t2yk0eNr8uU.jpg',3.5073523771547,3,'2026-09-10',2,NULL,NULL),(86837,'爱','Amour','乔治与安妮已年逾八旬。他们是一对有教养的退休音乐教师。女儿同样身为音乐家，与家人定居海外。一日，安妮突发中风。这对夫妻相濡以沫的情感羁绊，自此面临严峻的考验。',NULL,8900000,19839492,17.151293,7.5,400,127,'2012-07-01','fr','/nEk5dZvtfcbE3CO8EJjyPpLeZBc.jpg',3.3220701068595964,3,'2026-09-10',2,NULL,NULL),(86838,'七个神经病','Seven Psychopaths','马迪Marty（柯林·法瑞尔 Colin Farrell 饰）是一个爱喝酒的电影编剧，他的好友比利Billy（山姆·洛克威尔 Sam Rockwell 饰）则和汉斯Hans（克里斯托弗·沃肯 Christopher Walken饰）靠偷狗然后把狗还回给失主来赚钱。马迪Marty近期在写一个叫《七个神经病》的剧本，却没有什么灵感，于是比利Billy给他提供了一些素材。有一个神经病是一个杀手，每次杀完人都会扔下一张J扑克牌，有一个越南的复仇者，有一个自刎的贵格教徒······比利Billy偷了一条狗，这条狗的主人是一个黑帮老大查理Charlie（迈克尔·斯图巴 Michael Stuhlbarg 饰）的爱犬。查理Charlie丢了他视如生命的狗，到处在寻找。他找到了汉斯Hans住院的妻子并杀害了她。比利Billy知道这件事后，愤怒的将他的情人杀害，而她也是查理Charlie的情人，随后比利Billy扔下了一张扑克牌。原来比利Billy就是那个神经病杀手。他和马迪Marty、汉斯Hans来到野外继续写剧本，同时他也让查理Charlie单枪匹马前来决斗 ······','They Won\'t Take Any Shih Tzu.',15000000,19422261,32.306455,6.7,1206,110,'2012-09-07','en','/gn5L3gXAk2KvOCfGkvzOpGcSxYT.jpg',3.5582913145548143,3,'2026-09-10',2,NULL,NULL),(87093,'大眼睛','Big Eyes','《大眼睛》故事发生在上个世纪60年代，一种名为“大眼孩子”的插图流行起来。不久，其作者沃尔特·基恩遭到起诉，被指责盗取他人作品，而对方正是沃尔特的妻子玛格丽特。玛格丽特表示，大眼孩子的绘画原本出自她之手，性格内向的她每天在地下室里作画，而丈夫沃尔特仅仅是在画作下方签上自己的名字进行销售而已。最终二人婚姻破裂。事情闹上法庭后，法官让二人现场作画，沃尔特推三阻四，借口不断，最终版权案真相大白。','She created it. He sold it. And they bought it.',10000000,28883511,28.570174,6.8,1196,105,'2014-12-24','en','/hB1giXpGrxEEZGb03mWAKJQGAkj.jpg',3.566250020005495,3,'2026-09-10',2,NULL,NULL),(87101,'终结者：创世纪','Terminator Genisys','故事追溯到莎拉·康纳的幼年时期，阿诺饰演的终结者T-800成为了她的“养父”。2029年“审判日”后人类与机器决战的末世未来开始，人类反抗军领袖约翰·康纳将忠实部下凯尔·里斯送回1984年，保护自己的亲生母亲莎拉·康纳不被终结者杀害。而回到过去的凯尔·里斯却遭遇液态金属终结者T-1000，在被莎拉·康纳救下后，莎拉告诉凯尔·里斯约翰将他送回的时代已经不复存在。而更可怕的是，约翰·康纳竟堕落为“天网”的爪牙。','Reset the future',155000000,440603537,202.042635,5.8,3631,126,'2015-06-23','en','/oZRVDpNtmHk8M1VYy1aeOWUXgbC.jpg',3.997248438559242,3,'2026-09-10',2,NULL,NULL),(87421,'星际传奇3','Riddick','剧情承接上部。主人公瑞迪克延续了之前一直被抛弃的命运，被独自滞留在一个荒凉的外星星球上。然而没过多久他发现自己需要和比之前对抗过的任何人类都危险的外星异形进行斗争才能获得生存，唯一的出路就是激活紧急装置并且躲避降落在这个星球的其他势力雇佣军。','Survival Is His Revenge',38000000,98337295,46.630062,6.2,2035,119,'2013-09-02','en','/1LmtB9qsswAguFAbiNq3OvpjiU0.jpg',3.613990254849757,3,'2026-09-10',2,NULL,NULL),(87428,'爸爸的好儿子','That\'s My Boy','影片是《周六夜现场》两代明星亚当·桑德勒与安迪·萨姆伯格的首度合作，讲述了一个不负责任的父亲与已经成年的儿子之间的趣事。[2]\r 话说上世纪80年代，在美国的一个小镇上，有着这样一个叫唐尼的毛头小子。还未成年的唐尼（亚当·桑德勒饰）并不是什么三好少年，抽烟酗酒什么事都干得出来，而他做得最离谱的，是一件实在太过火的不伦丑事--老师\"上\"了唐尼，结果怀上了唐尼的孩子。法院判决老师勾引未成年少年，性感的女老师锒铛入狱，唐尼却逍遥法外。在进监狱前，女老师托唐尼照顾好他们的孩子，但年少的唐尼根本没把这当回事，依然继续风流。13岁的唐尼根本不懂得如何做一个称职的父亲，所以当自己的小孩年满18，便愤然离他而去。\r 一眨眼，十多年过去了。唐尼已经成了一个坐吃等死、落魄潦倒的中年老男人，一直偷税漏税的他，被税务问题困扰得苦不堪言，直到他在报纸上看到自己儿子托德(安迪·萨姆伯格饰)结婚的消息，又得知自己的儿子事业有成，是年轻有为的金融经理的时候，为了让自己不至于在监狱度过下半生，他决定无论如何都要去参加已经几十年没见的儿子的婚礼。托德很讨厌自己的父亲，他认为唐尼是世界上最差劲的爸爸，而年过中年的唐尼则开始试着去了解自己的儿子，两人不可避免的发生了一系列的碰撞，搅得托德一家鸡犬不宁。显然托德的大婚，也没那么轻易能结成。[3]','The story of a child… and his son.',70000000,58058367,21.723897,5.5,453,116,'2012-06-14','en','/oaLhdRsZ5Mq8VfZtA4Wlvjzzn0X.jpg',3.1414636417383166,3,'2026-09-10',2,NULL,NULL),(87499,'东方','The East','一个秘密的私人公司专为大企业提供保护，防止企业遭受环保恐怖分子以及反商业激进人士的攻击。秘密特工为了一次任务潜入了一个神秘的无政府激进组织“东方”（The East），并爱上了组织的首领。','Spy on us, we\'ll spy on you.',6500000,2401510,16.574756,6.5,305,116,'2013-05-31','en','/qTJPT1jFz94vSkmiHMUxQTfQsL7.jpg',3.148802822797508,3,'2026-09-10',2,NULL,NULL),(87502,'迫降航班','Flight','飞行员让一架损坏的客机奇迹般地平安着陆，因此受到了嘉奖，而调查事故起因时，飞行员却竭力隐瞒真相。',NULL,31000000,161772375,42.213765,6.5,2415,138,'2012-11-02','en','/tFsHDNclXoCKy2xMxskzXXMaFJS.jpg',3.7110417829552524,3,'2026-09-10',2,NULL,NULL),(87567,'盛大婚礼','The Big Wedding','德尼罗与基顿饰演一对早已分手的老夫妻，他们收养的儿子（本·巴恩斯 饰）与女友（阿曼达·塞弗里德 饰）到了谈婚论嫁的阶段，但本的生母（苏珊·萨兰登）突然杀将出来决定参加亲儿子的婚礼，而且她还是位虔诚的清教徒。为瞒住生母，德尼罗与基顿只能逢场作戏再次扮演夫妻，一系列貌合神离的搞笑事接踵而至……','It\'s never too late to start acting like a family',35000000,21819348,18.84332,5.7,414,90,'2013-04-25','en','/ooSGwWVJRp81ErEH7VmTmVwjoMc.jpg',3.140991365046707,3,'2026-09-10',2,NULL,NULL),(87729,'总统的秘密情人','Jefferson in Paris','这部电影以1784-1789年为背景，讲述了杰斐逊在法国大革命前担任美国驻法国大使的经历。法国的自由主义者和知识分子希望他能带领他们远离路易十六和玛丽·安托瓦内特的宫廷的腐败，走向更民主的政府形式。虽然他对普通百姓的贫穷感到悲哀，但他却欣然接受了法国文化和文明的财富。这是他第一次出国，他利用这个机会扩展自己的人文和科学知识。','A powerful man torn between his love for one woman and his secret desire for another.',14000000,2474000,0.900442,5.2,10,139,'1995-03-31','en','/vcZCvsm920LoNDb7pMibJkxIE4n.jpg',2.3528278883656455,3,'2026-09-10',2,NULL,NULL),(87818,'电影43','Movie 43','众多大明星们做出各种稀奇古怪的行为竭力搞笑，甚至还拿超级英雄出来开涮，当然，穿上超级英雄战服的他们总让人觉得充满了弱弱的萌感。  和《巴黎，我爱你》类似，《电影43》也是一部多人执导的，充满了大明星的拼盘类电影。但是与《巴黎，我爱你》每个小短片独立成片不同的是，《电影43》里的小故事却是有联系的，最后汇总成一条线。这些故事或是一味地搞笑，或是走冷幽默的路线；甚至还有的短片已经拿超级英雄开开涮了…','The biggest cast ever assembled for the most outrageous comedy ever made.',6000000,32438988,35.350303,4.4,797,90,'2013-01-01','en','/6NXWW2gm9poQWaKQmYwM7bwjpgK.jpg',3.097092170391452,3,'2026-09-10',2,NULL,NULL),(87825,'曲线难题','Trouble with the Curve','加斯（克林特·伊斯特伍德 Clint Eastwood 饰）是亚历山大勇士队的资深球探，然而近来他可够呛。上了年纪又有些视力衰退的他因此被认为已经无法适应当今变化的市场，并被分配了最后一次招新任务来证明自己的价值。加斯的老板兼好友彼特（约翰·古德曼 John Goodman 饰）有些不忍，便找来了加斯的女儿米琪（艾米·亚当斯 Amy Adams 饰）帮忙一起完成这段任务旅程。然而这并不是什么轻松的事，自从米琪六岁丧母后，父女俩的关系就不见得多好，不巧还搭上了对手球队的年轻球探约翰尼（贾斯汀·丁伯莱克 Justin Timberlake 饰），一路上的磕磕绊绊可不少。面对这堆难题，三人最后能否顺利渡过？','Whatever Life Throws at You',0,0,18.587114,6.6,366,111,'2012-09-21','en','/v9BwdnRnH3JmUNmxwnXqOuCy4d5.jpg',3.2074702174107785,3,'2026-09-10',2,NULL,NULL),(87826,'好景在望','Here Comes the Boom','在这部喜剧中，凯文·詹姆斯扮演了一个叫做斯科特·沃斯的42岁的生物老师，他在一间破败的学校里教书，生活索然无味。可是突然有一天，他却萌生了要为学校的几乎已经停摆的音乐计划筹款的想法。为了搞到钱，他不得不在业余时间去打MMA的比赛。很多人都认为沃斯疯掉了，尤其是学校的护士贝拉。可是沃斯却知道自己没有疯，因为他从这些事情中得到了不一样的生活体验。','No one will fight for his students like Mr. Voss.',0,73100172,26.799913,6,593,105,'2012-10-11','en','/g3ZjNkQP4M7Cs0clPD9q7EO2P1g.jpg',3.266731829910887,3,'2026-09-10',2,NULL,NULL),(87827,'少年派的奇幻漂流','Life of Pi','一名作家偶然得知了派·帕帖尔不同寻常的人生经历，并听他讲起少年时代的往事。派从小在父亲经营的动物园中长大，对动物、信仰与世界始终怀有强烈的好奇。17岁那年，父母决定带着全家和部分动物离开印度，乘船前往加拿大开始新的生活。然而航行途中，一场突如其来的暴风雨令货船沉没，派侥幸登上一艘救生艇，在茫茫太平洋上开始漂流。更加不可思议的是，与他一同困在海上的，还有一只名叫理查德·帕克的孟加拉虎。面对无边的大海、饥饿与随时可能袭来的危险，一人一虎不得不在彼此戒备中寻找共同生存下去的方法，一段超乎想象的奇幻漂流由此展开……','Believe The Unbelievable',120000000,609016565,51.328145,7.2,5797,127,'2012-11-20','en','/iLgRu4hhSr6V1uManX6ukDriiSc.jpg',4.1224671876249,3,'2026-09-10',2,NULL,NULL),(87943,'法网好姊妹','Sisters in Law','Set in Kumba in South West Cameroon Sisters in Law follows Adultery, Rape and Abuse cases led by a Female Judge.',NULL,0,0,0.025211,7.3,2,104,'2005-09-03','en','/7kAVD6eSwXN5YmEppspyQzVeTA3.jpg',2.073375963203175,3,'2026-09-10',2,NULL,NULL),(88005,'末日情缘','Seeking a Friend for the End of the World','地球将被一颗小行星撞击，人类面临着毁灭的危机，在慌乱中，男主角（史蒂夫·卡瑞尔 Steve Carell 饰）的妻子离家出走，只剩下他孤单一人。这时他高中时的恋人写信给他，希望在世界末日前能和他在一起。于是男主人公在女邻居（凯拉·耐特丽 Keira Knightley 饰）的陪伴下开始了公路之旅，意外的爱情之花也在这两人之间慢慢绽放。','Nice knowing you.',10000000,9636289,30.863082,6.3,700,101,'2012-06-22','en','/6gekwaUwnEVEQYu3jOjsvuY1w1n.jpg',3.354688098222465,3,'2026-09-10',2,NULL,NULL),(88036,'闪耀的花火','Sparkle','音乐奇才斯派克尔正在努力地成为一名新星，但在另一方面，她的野心正在让她渐渐远离自己的家庭和亲人。斯派克尔来自于一个底特律的家庭，成长于一个单亲家庭，她的妈妈艾玛也很喜爱唱歌[1]。\r 而目前，斯派克尔正处在自己事业的上升期，她一方面在和自己的音乐制作人斯蒂克斯恋爱，而另一方面不期而遇的挑战和意外又把自己的妹妹希斯特和多罗尔斯搅了了进来。希斯特和多罗尔斯也是乐坛上的新人，她们组成的团体也面临着挑战。与此同时，希斯特还卷入了毒贩斯塔廷的交易中，麻烦连连……\r 究竟斯派克尔要如何处理这一切，音乐真的能拯救人的灵魂么？','Celebrate the legend.',14000000,24637469,2.698185,5.8,36,116,'2012-08-17','en','/6LqVIhz0xxoFjiGjftDW69DbvNi.jpg',2.6196298555245137,3,'2026-09-10',2,NULL,NULL),(88042,'家长指导','Parental Guidance','一对跟儿女很久不见面的父母，应女儿爱丽丝的要求去帮她照顾几天孩子。孩子们对没怎么见过面的祖父母感到很陌生，虽然爱丽丝对他们说了一些与祖父母相处的方法，不过见面后祖孙两代人之间的代沟依然无法逾越。祖父亚迪和女儿爱丽丝之间积压了多年的问题，也开始显现出来。随着与孩子们接触的增加，亚迪认识到了自己的问题，并开始学习改变的方法，重新修复和女儿的关系。','Here come the grandparents.  There go the rules.',25000000,119772232,14.604911,5.7,210,104,'2012-12-25','en','/815zxi87kTUvleFHjnE5SNzWmVZ.jpg',3.0015843386887435,3,'2026-09-10',2,NULL,NULL),(88641,'There Goes My Baby','There Goes My Baby','A group of high school seniors meets in the summer of 1965 and all struggle with the choices they have to make.',NULL,10500000,123509,0.037073,8.5,2,99,'1994-09-02','en','/3KM98skbDojKhXFvShERFsTxv3a.jpg',2.074388778576263,3,'2026-09-10',2,NULL,NULL),(88751,'地心历险记','Journey to the Center of the Earth','虽然特雷弗（布兰登·费舍 Brendan Fraser 饰）是大学的地址教授，但是却经常做出挑战传统的事情。他认为，凡尔纳的小说并不是科幻，而是真是存在的。就是因为这样的对立理论，使其被传为学院里的笑话，使得他的学术名声毁于一旦。不过特雷弗却毫不在意这些，他坚信自己的理论是正确的。为了验证自己的理论，特雷弗带着侄子肖恩（乔什·哈切森 Josh Hutcherson 饰）和当地的向导汉娜（安妮塔·布瑞姆 Anita Briem 饰）开始了在冰岛的旅行。在旅行时，三人意外发现一个奇特的洞穴，并在探询时踏破薄冰跌入了无底深渊。不过，当他们醒来时，却发现了一个神秘的地心世界，里面有着各种稀奇古怪的生物，与凡尔纳小说里面描述的场景一模一样。证据终于找到了，但是如何将证据带回地上？特雷弗三人开始了寻找出路之旅……','Same Planet. Different World.',45000000,101702060,53.090422,5.8,1309,93,'2008-07-10','en','/bO93bLcKDURjRsFZM7QpRjG2v1q.jpg',3.4534340779672417,3,'2026-09-10',2,NULL,NULL),(88794,'胡佛','J. Edgar','影片改编自美国FBI传奇人物J·埃德加·胡佛的故事。1924年，年仅29岁的J·埃德加·胡佛被司法部长提升成为调查局主管。胡佛将“彻底杜绝犯罪行为”作为目标，立即对调查局漏洞百出的体制进行了调整改革，一口气辞掉了上百名特工，并规定只有受过大学教育并具备执法经验的人才有机会得到这份工作。随后，他成立FBI犯罪实验室，并改名调查局为联邦调查局。1950年，他还建立了大名鼎鼎的十大通缉犯名单。据悉，胡佛在任职期间曾利用不法手段收集对手罪证，获得诸多政治权力。在他去世前，关于他是“同性恋加异装癖”的传闻更是为这位强硬执法者的阅历，平添了几分传奇色彩。','The most powerful man in the world.',35000000,84606030,28.069419,6,741,137,'2011-11-09','en','/1ICxLe41NSWnmWZ1IXAS29Zr6F9.jpg',3.3160647332877793,3,'2026-09-10',2,NULL,NULL),(89325,'亲爱伴侣','Darling Companion','在丹佛寒冷的落基山地区，贝西（戴安·基顿饰）从高速路边救下一只全身污泥的流浪狗，并给它取名“自由奔腾（Freeway）”。贝西的儿女都已结婚成家，丈夫约瑟夫（凯文·克莱恩）又只生活在自己的世界里，孤独的贝西和小狗间结成了一段特别的情谊。然而当女儿格蕾丝（伊丽莎白·莫斯）举行婚礼时，约瑟夫弄丢了小狗。贝西对约瑟夫发怒生气之后，和赴婚宴的亲朋好友（黛安娜·维斯特，理查·詹金斯，马克·杜普拉斯等）组织成一支临时搜救队。在神秘的卡曼（阿耶莱特·祖里尔）的指引下，深入落基山寻找丢失的爱犬。这次冒险将改变搜救队每一个成员的人生，带领他们体验一段出乎意料的旅程---滑稽，感伤而又极其动人。',NULL,0,0,2.303865,5.3,22,103,'2012-04-20','en','/krKAMxPbzPcb0FvF9QoySiCHihi.jpg',2.5127619355023265,3,'2026-09-10',2,NULL,NULL),(89492,'四十而惑','This Is 40','本片延续贾德·阿帕图《一夜大肚》剧情，主角换成片中年过四十、性格迥异的姐姐和姐夫，讲述他们焦头烂额的家庭故事。','The sort-of sequel to \'Knocked Up\'',35000000,88058786,38.429648,5.6,896,134,'2012-12-20','en','/2ndmQNo1bBCVdbOtqiglpNaPk4G.jpg',3.3131365101853145,3,'2026-09-10',2,NULL,NULL),(89540,'The Other Conquest','La otra conquista','The film is a drama about the aftermath of the 1520s Spanish Conquest of Mexico told from the perspective of the indigenous Aztec people. It explores the social, religious, and psychological changes brought about by a historical process of colonization that both defined the American continent and is also highly reminiscent of today’s neocolonialism.','The spirit of a people can never be conquered.',0,0,0.015597,5.4,4,105,'1999-04-01','es','/cD1V0wj6CkKvEPrXb0ZAa0v7uJi.jpg',2.1821354907922488,3,'2026-09-10',2,NULL,NULL),(89708,'轮回','Samsara','《轮回》是一场跨越25个国家的视觉之旅，Ron Fricke花费了5年之间捕捉每种文化中令人震撼的场面，试图建立人类与自然的桥梁。影片的名字“Samsara”来自藏语，Frricke希望借此诠释其独特的视觉风格。全片使用70mm胶片拍摄，才得以保证影像如此细腻丰富的质感 。Samsara是藏语，又叫做依业轮回，是表示生命流转循环的意思。编剧罗恩·弗里克和Mark Magidson用精彩的画面诠释了这一个深奥的词汇。揭示了大自然与我们生活的微妙关系。本片是曾以《天地玄黄》带来无言震撼的导演Ron Fricke时隔20年之后再出的新作。',NULL,4000000,0,12.781973,8,167,102,'2011-09-16','en','/qodkea4k0pNUmNTl5TJO2PdTqgW.jpg',3.081234565993538,3,'2026-09-10',2,NULL,NULL),(89750,'Pink Ribbons, Inc.','Pink Ribbons, Inc.','Breast cancer has become the poster child of corporate cause-related marketing campaigns. Countless women and men walk, bike, climb and shop for the cure. Each year, millions of dollars are raised in the name of breast cancer, but where does this money go and what does it actually achieve? Pink Ribbons, Inc. is a feature documentary that shows how the devastating reality of breast cancer, which marketing experts have labeled a \"dream cause,\" becomes obfuscated by a shiny, pink story of success.','Capitalizing on hope.',900000,25000,0.097913,6.8,6,97,'2011-09-11','en','/kiGhBNHtACElOoGpQDY26JcFc3W.jpg',2.258239772636213,3,'2026-09-10',2,NULL,NULL),(89857,'High Road','High Road','Directed by Matt Walsh, a co-founding member of world-renowned comedy troupe Upright Citizens Brigade, High Road showcases a totally improvised script about Glenn “Fitz” Fitzgerald (James Pumphrey), a young man whose loyalties are split among his band, his girlfriend Monica(Abby Elliottt) and selling drugs. After his band breaks up, Fitz finds himself dealing drugs out of his garage and bonding with 16-year-old neighborhood kid Jimmy (Dylan O’Brien). As his former band mates (Zach Woods, Matt L. Jones, Lizzy Caplan) begin finding success and one of his drug deals goes awry, Fitz hits the road with Jimmy. Amid car chases, guns, broken bones, sassy cabbies and a suspicious doctor (Horatio Sanz), Fitz has to navigate their way to safe harbor--and he doesn’t even know about the surprise Monica has in store for him back home!','The road less traveled is filled with pot holes.',0,0,1.292948,5.8,22,87,'2012-03-06','en','/qQRZwequtuXOcYVHvdyAD5A5L2X.jpg',2.514850278711865,3,'2026-09-10',2,NULL,NULL),(89861,'Stiff Upper Lips','Stiff Upper Lips','Stiff Upper Lips is a broad parody of British period films, especially the lavish Merchant-Ivory productions of the \'eighties and early \'nineties. Although it specifically targets A Room with a View, Chariots of Fire, Maurice, A Passage to India, and many other films, in a more general way Stiff Upper Lips satirises popular perceptions of certain Edwardian traits: propriety, sexual repression, xenophobia, and class snobbery.',NULL,0,0,0.356495,10,1,99,'1998-06-12','en','/3BKL5t6z6kudeDmuwYiIF5dzAV8.jpg',1.9867104938181306,3,'2026-09-10',2,NULL,NULL),(90369,'活在当下','Now Is Good','《活在当下》是一本文笔优美、充满诗意的身心灵散文集，有爱的能量与发人深省的力量洋溢在字里行间。读起来，对我们的心、我们的灵魂都是一种很好的滋养。安吉丽思努力在每一个生命的片刻，每一桩人生中都带着爱、带着欣赏、带着觉察去全身心地品味。保持这样的生活态度，必然会在生活中体会到许许多多别人未曾发现的美妙滋味和人生领悟。生命其实可以被看作一种物质，它是以时间为单位的。我们大部分人的生命长度看似相近，但是在这相近数量的生命里，我们能够萃取的精华却是大相径庭。生命的宽度与高度完全取决于我们以什么样的态度和方式去活。安吉丽思在书中给予我们的重要练习，就是从我们日以继夜运转不息的头脑中跳出来的，回归到我们的身心。  别以为这只是在谈生活的态度，在成为生活美食家的过程中，你的灵性也将获得提升。许多灵修体系的精髓其实就是一个片刻接一个片刻地活在当下，全身心专注地生活。这样的生活，几近于道。世界闻名的越南高僧一行禅师（Thich Nhat Hanh），一本深具启发的书《一步一莲花（Peace Is Every Step）》，在书中写道：  生命的意义只能从当下去寻找。  逝者已矣，来者不可追，  如果我们不反求当下，  就永远探触不到生命的脉动。  来吧，还等什么，当下这个片刻，对于生活，你品味到什么。','Live every moment, love every minute',0,0,14.142073,7.3,371,103,'2012-05-25','en','/2h8I7vbWb9b7GjZraDxxO1rs7sh.jpg',3.2715618660082955,3,'2026-09-10',2,NULL,NULL),(90414,'I Love You, Don\'t Touch Me!','I Love You, Don\'t Touch Me!','The story of a 25 year old virgin girl, looking for the right boyfriend, not realizing that \"the one\" has been next to her for many years.','Just Your Typical Boy-Loves-Girl Who Doesn\'t Love Boy Till He Loves Other Girl Story',0,0,0.020839,6,1,86,'1997-01-21','fr','/v3EUGs3qYU9zzqWoKdBncy2YczK.jpg',1.984298670151111,3,'2026-09-10',2,NULL,NULL),(91070,'好友有喜','L!fe Happens','电影的主要情节是围绕克里斯滕·丽特扮演的角色怀孕后的生活展开，她和她的最好的朋友如何去应对这突如其来的变化，并且让生活归于正常','A comedy that\'s a real mother.',930000,30905,5.974156,5.3,66,100,'2011-06-18','en','/xFq3IQEWCBBoPP7pCb4TarAi8tt.jpg',2.7402128854920687,3,'2026-09-10',2,NULL,NULL),(91076,'Illuminata','Illuminata','It\'s the start of the 20th century, and Tuccio, resident playwright of a theatre repertory company offers the owners of the company his new play, \"Illuminata\". They reject it, saying it\'s not finished, and intrigue starts that involves influential critic Bevalaqua, theatre star Celimene, young lead actors and other theatre residents',NULL,0,0,0.111313,6.3,7,119,'1998-05-21','en','/vovb7pbU3CkKjfcmOxwz7AMbpCX.jpg',2.286116732145731,3,'2026-09-10',2,NULL,NULL),(91122,'16 to Life','16 to Life','Romantic comedy. A small town teenager\'s angst about sexual inexperience drives a comic quest for love and understanding on a birthday to end all birthdays.',NULL,0,0,0.108468,4.4,5,118,'2009-09-19','en','/yM3rD0Iqinb003T9vg9tl6JgxpN.jpg',2.219603174559041,3,'2026-09-10',2,NULL,NULL),(91314,'变形金刚4：绝迹重生','Transformers: Age of Extinction','当年那场惨烈的芝加哥大战，汽车人虽然成功击退了霸天虎的入侵，却也让地球人对他们失去了应有的信任与尊重。由美国中情局组建的“墓风”部队对所有的变形金刚进行无差别的猎杀，一时间汽车人和霸天虎全都在地球不见了踪影。某天，居住在得州的落魄机械发明家凯德·伊格 买回来一辆破旧的卡车车头，谁知那竟是处在休眠中的汽车人首领擎天柱。嗅到气息的墓风部队蜂拥而至，苏醒后的擎天柱救走了凯德一家，也和散落在各个角落的汽车人相继取得联系。另一方面，疯狂的人类科学家从变形金刚的残骸中获知了他们变形的秘密，并企图借此制造出人造金刚，而脱胎自威震天的惊破天正是他们的得意作品以及催命死神。新一轮的危机卷土而来，地球面临更大的灾难……','This is not war. It\'s extinction.',210000000,1091405097,116.840296,5.8,3095,165,'2014-06-25','en','/jyzrfx2WaeY60kYZpPYepSjGz4S.jpg',3.7701538893470774,3,'2026-09-10',2,NULL,NULL),(91586,'潜伏2','Insidious: Chapter 2','莱姆伯特一家人近来竭力对抗侵扰儿子的恶灵，父亲乔什必须面对自己可怕的童年。','It will take what you love most.',5000000,0,48.375848,6.5,1211,106,'2013-09-12','en','/dEiYKGdTXboyHJH02rfzaeK4spX.jpg',3.558601109057234,3,'2026-09-10',2,NULL,NULL),(91721,'只是个男人','Nothing But a Man','在 20 世纪 60 年代的美国，一位骄傲的黑人男子和他的教师妻子面临着歧视性的挑战。',NULL,0,0,0.008453,7,2,95,'1964-01-01','en','/6vWkmRHsX1yIUJSimDKEJLU4UkD.jpg',2.073091254575775,3,'2026-09-10',2,NULL,NULL),(92182,'寂静的房子','Silent House','银幕上的时间与真实事件发生的时间保持绝对的一致，以第一人称视点让观众跟随剧中角色体验最身历其境的真实恐惧！  　　萨拉是一个年轻的女孩子。这一天晚上，她和自己的父亲来到自己家位于湖边的小屋里打扫卫生，并做一点修葺的工作，因为这间位于湖边的寂静的小屋即将被出售。到了凌晨，萨拉的父亲在一阵奇怪的声响之后就消失不见了。只留下萨拉一个人在黑暗中摸索。  　　这间湖边的小屋与世隔绝，没有电话、没有网络、手机没有信号，而且只有一扇通往外面的门。随着夜越来越深，各种离奇的声音和不详的事件也愈发地密集起来。而萨拉，只有慢慢熬过生命中最恐怖的88分钟了。  　　时间一分一秒过去，她是否能发掘隐藏在小屋的恐怖秘密、并安然迎接翌日晨光呢？','Experience 88 minutes of real fear, captured In real time',2000000,13101672,11.66632,5.2,125,85,'2011-01-21','en','/mbkvYlx1scovMi80rOOkNBvgU11.jpg',2.870515547225723,3,'2026-09-10',2,NULL,NULL),(92591,'伯尼','Bernie','伯尼（杰克·布莱克 Jack Black 饰）是德州小镇迦太基的殡仪师，他专业技术过硬，为人厚道、慷慨、热心公益、在教堂担任领唱还参加社区剧团演出，赢得小镇所有人的欢心，但他始终单身，被人猜测要么奉承独身主义，要么是个基佬。镇上一位富商去世后，留下脾气古怪、被所有人讨厌的高龄寡妇玛佳丽（雪莉·麦克雷恩 Shirley MacLaine 饰）。伯尼本着“对每个家属赋以最真诚同情和善意”的原则，热心接近玛佳丽，很快赢得她的欢心，她负担起两人所有玩乐开销，让伯尼参与她的财产管理，甚至为他改动遗嘱。两年过去，人人都爱的伯尼几乎成了玛佳丽的私人所有物，她辞退所有用人，生活中的所有琐事都交予伯尼一手包办。好脾气的伯尼也有爆发的一天，而且是一步到位地结束了玛佳丽的性命，演着一出“玛佳丽中风了”的戏，伯尼撑着这个秘密，试图逃过法律制裁…… 　　本片根据发生在德州的一起真实事件改编。','A story so unbelievable it must be true.',5000000,9206470,12.68514,6.5,320,100,'2012-04-27','en','/rW5CetooG545jpkPNpD4FjFAXfe.jpg',3.1514819850545868,3,'2026-09-10',2,NULL,NULL),(92635,'白雪公主：一个致命的夏天','Snow White: A Deadly Summer','白雪是一个正处在青春叛逆期的女孩，她不满父亲格兰特（艾瑞克•罗伯特斯 Eric Roberts 饰）和继母伊芙（玛瑞恩•麦柯米克 Maureen McCormick 饰）的婚姻，在家里处处与他们作对，在外逃课、飙车、惹祸，令人头痛。在伊芙的挑唆下，格兰特忍无可忍，将白雪强制送入“四周忠诚训练营”，一个旨在改造所有问题少年的活动。白雪被逼无奈，只得在烈日酷暑和教官呵斥怒骂下进行各种各样高强度的训练。\r 与此同时，心怀叵测的伊芙时刻图谋吞并格兰特的家产，为此，她必须除掉排在她前面法定继承人白雪。白雪不仅要想方设法保护自己，还要彻底挫败狠心继母的阴谋……','This is no fairy tale',1000000,0,0.653495,4.8,11,85,'2012-03-16','en','/9X1rn2qC3ltQjZdclPINTWIAX7Y.jpg',2.3690076882960054,3,'2026-09-10',2,NULL,NULL),(93456,'神偷奶爸2','Despicable Me 2','自从与玛戈、伊迪丝 和阿格蕾丝 三个可爱的小女孩实现宿命的邂逅，曾经的大坏蛋格鲁 可真彻底转型了，他金盆洗手，转而化身为慈祥可亲的爸爸和做得一手烂口味布丁果冻的商人。当然凡事没有尽善尽美的，在此期间，憧憬大坏蛋传奇人生的老搭档纳法利欧博士 离他而去，另谋高就。某天，格鲁被身怀绝技却鲁莽的特工露西·王尔德 绑架，原来露西所在的集团研制出可以改变生物基因的药物，可他们位于南极的实验室被神秘窃贼偷走，因此才委托有过坏蛋经验的格鲁做卧底。经过一番考虑，格鲁接受了这项任务，带着超萌的小黄人们，和露西组成了爆笑连连的追凶搭档……','Back 2 Work',76000000,970761885,136.886704,7,4637,98,'2013-06-25','en','/5Fh4NdoEnCjCK9wLjdJ9DJNFl2b.jpg',4.209698867698576,3,'2026-09-10',2,NULL,NULL),(93856,'切尔诺贝利日记','Chernobyl Diaries','六个爱玩的年轻人想在这个地球上寻觅一点刺激，于是他们便来到了切尔诺贝利。而为了追求更为惊悚的体验，在知情人士的指引下，他们雇佣来了一个知道“极端游”行程的向导。不顾警告、蔑视一切的年轻人和这个向导走进了普里皮亚特。\r 　  26年前，这里曾是是一个繁荣的城市，但是在切尔诺贝利核电站发生了爆炸之后，这里就变成了一个弃城。初来乍到的几个年轻人对这里的一切都觉得很好奇，他们渐渐地把这里当成了一个巨大的游乐场，开始了开心的玩闹和嬉笑。\r 　  但是，到了夜晚，事情开始渐渐起了变化。一些超自然的东西出现在了这座弃城之中，而且极为惊悚。现在，这群年轻人处在了进退两难的境地，既无法深入普里皮亚特寻找庇护，也没有办法离开这里，更可怕的是，方圆十几公里的范围内都是死一样的寂静……','Experience the fallout',0,18112929,20.649145,4.9,483,88,'2012-05-24','en','/xLi0hody35yh7HZXrjNC7JBkiuD.jpg',3.0783309263162453,3,'2026-09-10',2,NULL,NULL),(94072,'冲出布鲁克林','Straight Out of Brooklyn','A Special Jury Award winner at the Sundance Film Festival, this drama stars a then-19-year-old Matty Rich (who also wrote and directed it). Rich plays Larry, a troubled teen living in the rough Red Hook section of Brooklyn who decides he wants out and turns to crime to fund his escape. But his plan involves scamming the neighborhood\'s biggest drug kingpin, a heist that\'s dangerous at best.',NULL,0,0,0.161517,4.3,4,0,'1991-06-13','en','/g0C6BbyDKbI33fn14Yqb8TZO4Hq.jpg',2.180666581707485,3,'2026-09-10',2,NULL,NULL),(94329,'突袭','Serbuan Maut','在雅加达的贫民窟的深处，世界上最危险的杀手和黑帮集结在一个坚不可摧的房子内。到现在为止，破旧的公寓甚至被神勇的警察也视为无法接近的。在黎明前黑暗和寂静的掩护下，一个身兼重要任务精英特警队与执法人员慢慢接近了房子，以便接近臭名昭著的毒枭。但他们袭击的消息被毒枭偶然发现，接 着建筑物的灯光被切断，所有的通道被堵。这群特警必须要在世界上最残酷的环境下为生存展开搏斗。','1 Ruthless Crime Lord, 20 Elite Cops, 30 Floors of Hell',1100000,4105187,40.285095,7.3,1055,101,'2011-09-08','id','/undTka3bJ1oVKTU3rvb0Banynxn.jpg',3.648356307767219,3,'2026-09-10',2,NULL,NULL),(94348,'亚历克斯·克洛斯','Alex Cross','剧情介绍:亚历克斯专门负责大型刑事案件的侦查和侦破。一名台湾女孩在一栋豪宅内遭受性虐杀，连同她的私人保镖等数人也都无一幸免，亚历克斯奉命接受此案的调查。而这起凶案似乎与环杀手迈克尔有关。他经验丰富、冷血残酷，总比警方快一步，每次犯案后都能顺利逃脱。为了挑衅亚历克斯，他在他们的结婚周年日给亚历克斯打了警告电话，并当着他的面杀死了他的妻子。亚历克斯失去妻子的痛苦，也激发他抓拿迈克尔的决心。而通过对虐杀案抽丝剥茧慢慢靠近谋杀案的真相时，重要的涉案关系人却一一遭到杀害。....','Don\'t Ever Cross Alex Cross',45000000,30353232,14.513243,5.1,300,101,'2012-10-18','en','/xuXoVeh3P2yujaFoXem6hHAruY1.jpg',3.0176013882525865,3,'2026-09-10',2,NULL,NULL),(94352,'太阳马戏团：遥远的世界','Cirque du Soleil: Worlds Away','詹姆斯·卡梅隆出任制片，和闻名世界的加拿大太阳马戏团（Cirque du Soleil）合作，马戏表演和CG场景相互交融，带给观众耳目一新的艺术之旅。','Experience a Journey Like Never Before',0,34153101,5.987486,6.1,58,91,'2012-11-09','en','/jAt4ugebhXKmAnirHAWe5P6gnMi.jpg',2.732606032829523,3,'2026-09-10',2,NULL,NULL),(95755,'小公寓','Small Apartments','马特·卢卡斯主演的叫弗兰克的家伙不小心杀死了自己的房东，而他必须想尽办法来藏尸，这听起来似乎又是一个愚蠢的罪犯故事，而所谓的笑料也必然穿插在掩饰罪行的整个过程中。但是这个故事显然并不想按想照常规路线走，弗郭兰阴差阳错地开始了一次旅程，而在这次旅程中，他竟然邂逅了无数幸运…',NULL,2000000,0,5.100741,5.7,50,96,'2012-03-10','en','/z7j98OiCC6v0gOXJ9VF5t2kV169.jpg',2.691267801638394,3,'2026-09-10',2,NULL,NULL),(96238,'到此为止','Never Again','Two people who have pledged never to fall in love again then discover each other in a gay bar.','A mature love story for immature people.',0,0,0.039077,4,3,98,'2002-07-12','en','/oNPg56hNSdAdr9ttVYwVtxbBIrM.jpg',2.13230214889555,3,'2026-09-10',2,NULL,NULL),(96399,'墨西哥往事','For Greater Glory: The True Story of Cristiada','20世纪20年代，墨西哥。  　　随着新总统卡列斯的上任，一场关于政府和宗教的对峙在所难免。卡列斯是一位无神论者，而这时候墨西哥的天主教已经成为当地根深蒂固的一种文化，深入人心。卡列斯认为天主教破坏了整个墨西哥人民的思想，因此，他决定对墨西哥的教会进行肃清。卡列斯的做法自然引起了民众的级别反弹，周旋在墨西哥政府与教会之间的美国驻墨西哥大使（布鲁斯·格林伍德 Bruce Greenwood饰）努力想化解这场争执，但，这场关于信仰的战争，不可避免的爆发了。  　　政府一意孤行的采取血洗政策抓捕、杀害天主教徒，甚至在教堂里将牧师就地处决；牧师们被迫拿起武器自卫，在当地颇有威望的牧师维克多里奥（奥斯卡·伊撒克 Oscar Isaac饰）拿起机关枪，号召民众反抗强权；同时，曾立下赫赫战功、墨西哥最年轻的将军恩里克（安迪·加西亚 Andy Garcia 饰）也对政府的做法深感不满，他加入了反叛军，克多里奥一起对抗卡列斯的政府军。和在他的带领下，教会形成了一股强有力的武装力量。政府军视恩里克和克多里奥为眼中钉，一场针对他们二人的阴谋正在暗地里计划着；同时，恩里克并不是一个虔诚的天主教徒，他的一些所作所为，也引得反叛军内部不满，危机四伏，这场辉煌的信仰之战，能否取得最终的胜利？','The True Story of Cristiada',12000000,9622846,5.759545,6.4,35,145,'2012-06-01','en','/7jgh0ej04j98q2NFpSZLlpDazUo.jpg',2.629042276756884,3,'2026-09-10',2,NULL,NULL),(96534,'没有你的最后的日子','My Last Day Without You','On a one-day business trip to New York, a young German business executive falls in love with a singer-songwriter who exposes him to her Brooklyn world and emotions he\'s never experienced before.',NULL,1000000,0,0.153625,5.7,3,90,'2011-06-11','de','/5ZuTQgxk0OXhE8qTzmIoYEl6Ih.jpg',2.1346555907794538,3,'2026-09-10',2,NULL,NULL),(96721,'极速风流','Rush','一直以来，尼基 和詹姆斯 都是针锋相对的死对头。尼基认真严肃，对赛车的职业十分尊重，詹姆斯喜欢铤而走险，将赛车作为自己寻花问柳的筹码，虽然两人有着截然不同的个性，但他们之间的较量却从未停止过。 为了改变自己不够成熟的性格，詹姆斯和偶然遇见的名模苏西 结婚了，尼基亦找到了自己的一生挚爱并且加入了法拉利车队，而此时生活已经走上了下坡路的詹姆斯则加入了麦克拉伦车队，一对冤家再次站在了人生的战场之上。一次比赛中，天降大雨，尼基出了车祸身受重伤，詹姆斯因此夺得了冠军。可是，尼基并没有因此而放弃，在极短的时间内，尽管受到了众人的制止，但他依然毅然地回到了赛场上。','Everyone\'s driven by something.',38000000,90247624,33.003828,7.7,2277,123,'2013-09-02','en','/95BDrWmcfJDEa2WCfjmLgi67jhi.jpg',3.9487425662023434,3,'2026-09-10',2,NULL,NULL),(96724,'安娜·卡列尼娜','Anna Karenina','故事发生在1874年，美丽而又充满朝气的女主角安娜•卡列尼娜（凯拉•耐特丽 Keira Knightley 饰）已经拥有了一切同龄人渴求的东西，她的丈夫卡列宁(裘德•洛 Jude Law 饰)是一位高级政府官员，两人已经育有一子，而她在圣彼得堡也拥有无与伦比的社交地位。 她收到哥哥奥布朗斯基（马修•麦克费登 Matthew Macfadyen 饰）的来信，这位花花公子希望她能来帮忙挽救他与妻子多丽（凯莉•麦克唐纳 Kelly Macdonald 饰）之间的婚姻，而她也随即踏上前往莫斯科的旅程。在路途中她结识了渥伦斯基伯爵夫人，之后又在车站遇到了伯爵夫人的儿子，帅气的骑兵军官渥伦斯基（亚伦•约翰逊 Aaron Johnson 饰）。当安娜被介绍给渥伦斯基时，两人之间擦出了火花，双方都被彼此吸引住了。  　　奥布朗斯基在莫斯科的住宅还迎来了另外一位访客——奥布朗斯基的好友列文(多姆纳尔•格利森 Domhnall Gleeson 饰)，一位敏感而好心的农场主。列文爱上了多丽的妹妹凯蒂（艾丽西卡•维坎德 Alicia Vikander 饰）。他不合时宜的向凯蒂求婚，但后者却被渥伦斯基迷的神魂颠倒。不知所措的列文回到了他位于波克罗夫斯科的家，一心投入农场工作之中。而在一次社交舞会上，凯蒂发现渥伦斯基的眼中只有安娜，而已婚的安娜也同样回应了年轻人的好感，目睹这一切的凯蒂伤心欲绝。  　　安娜挣扎着重归平静，她急忙赶回圣彼得堡的家，但渥伦斯基却一路尾随。她试图重新回到过去的生活，但却又对渥伦斯基充满迷恋。两人之间擦出了激情的火花，这一切也在圣彼得堡的社交圈闹得沸沸扬扬。卡列宁陷入一个进退不能的境地，他不得不给自己的妻子下达最后通牒。安娜看穿了那个虚伪而不切实际的社交圈，她的应对带来一些浪漫而又悲剧的后果，也严重改变了她以及她周围人群的命运','An epic story of love.',0,68929150,26.38704,6.5,639,130,'2012-09-06','en','/b9mvt1kKqDuveD1AJuGSkBEuagU.jpg',3.3514540372352593,3,'2026-09-10',2,NULL,NULL),(97020,'RoboCop','RoboCop','In RoboCop, the year is 2028 and multinational conglomerate OmniCorp is at the center of robot technology.  Overseas, their drones have been used by the military for years, but have been forbidden for law enforcement in America.  Now OmniCorp wants to bring their controversial technology to the home front, and they see a golden opportunity to do it.  When Alex Murphy – a loving husband, father and good cop doing his best to stem the tide of crime and corruption in Detroit – is critically injured, OmniCorp sees their chance to build a part-man, part-robot police officer.  OmniCorp envisions a RoboCop in every city and even more billions for their shareholders, but they never counted on one thing: there is still a man inside the machine.','We\'ve got the future under control.',120000000,242688965,66.757869,5.7,2342,102,'2014-01-30','en','/bNeE1kUMFYG1sG6blHMwkG9sXXM.jpg',3.576740446434416,3,'2026-09-10',2,NULL,NULL),(97367,'松林外','The Place Beyond the Pines','卢克是一个神秘的摩托车特技演员，在一个嘉年华的场地里表演飞车绝技，并以此为生。他试图联系上自己的前女友，想和这个叫做罗米尼亚的女人重归于好。罗米尼亚前不久秘密地生下了卢克的儿子。为了给自己的孩子创造一个美好好的未来和宽裕的生活，卢克开始做起了抢劫银行的营生。凭借着自己过硬的车技，他次次都能逃过警方的追捕。就在卢克混得风生水起的时候，一个叫做艾福瑞·克洛斯的警察盯上了他。克洛斯刚刚来到警局不久，想做掉一个大案子来保证自己的前途。和卢克一样，他也刚刚有了自己的孩子。都是为了下一代考虑，都是为了生存。两个火爆的男人之间展开了一场旷日持久的追捕与逃脱的游戏。','If you ride like lightning you\'re gonna crash like thunder',15000000,35485608,35.395129,6.8,1653,140,'2013-03-20','en','/dY629wrWN2jfzCV5cl3ZyMP01fS.jpg',3.667039482346882,3,'2026-09-10',2,NULL,NULL),(97370,'皮囊之下','Under the Skin','不知从何时起，萧索的苏格兰街头出现了一个神秘女子（斯嘉丽·约翰逊 Scarlett Johansson 饰），她身着皮草，驾驶一辆汽车，不苟言笑的面庞隐约间弥散着摄人魅力。她时不时地与路边的男人搭讪，向他们问路，间或载着相中的男人同归。她走向黑暗的劲头，被欲望支配的男人们紧随其后，却全然未能觉察自己步入了怎样的深渊。男人有如飞蛾扑火，被抽取了骨血，只剩空空皮囊，薄如蝉翼。直到某个晚上，女人搭载了一个相貌极其丑陋的男子。他宛如怪物一般，自知丑陋而深深隐藏自己。女人如往常一样接纳了他，而从第二天起，似乎女人发现自己在悄悄发生着变化。她发现了这幅皮囊的可欣赏之处，享受作为女人的乐趣，却几乎忘记了本来的面目……\r 本片根据米歇尔·法贝尔（Michel Faber）的小说改编。','A mysterious seductress preys upon the population of Scotland',13300000,5380251,29.782161,6,1102,108,'2014-03-14','en','/v989miv3tCInJzewQc4jcZ9WSRX.jpg',3.4027599685925938,3,'2026-09-10',2,NULL,NULL),(97430,'铁拳','The Man with the Iron Fists','这是一部融合了爱情、谋杀、种族清洗和暗杀的故事片。背景被设置在了19世纪的纷乱的中国。  在这个时代里,有一个超级恶棍要杀死一个村庄里的所有的人。当他来到这个中国的山区中的小村落的时候,他命令这里的一个铁匠为他打造一件能够震慑住所有人的兵器。当这个地方渐渐被这个恶棍控制住之后,来自中国远古的力量把他变成了一个真正意义上的人类怪物--他自己就变成了兵器的一种。  而这个间接推波助澜的铁匠觉得自己难辞其咎,于是便联合起几个原本也是法外之徒的绿林好汉,结成联盟,并为自己装配上了铁拳,准备和这个人形怪物展开最后的搏斗……','You can\'t spell Kung Fu without F and U!',15000000,15608545,17.672021,5.2,358,96,'2012-11-02','en','/nHgkRj6Igx3QsHmTyF4oAfBjAE7.jpg',3.0614793470614874,3,'2026-09-10',2,NULL,NULL),(97614,'致命陷阱','Deadfall','影片讲述了两个铤而走险的逃亡兄妹的故事。在他们逃亡的路上，他们还碰到了个正回家、麻烦不断的前拳击手。  　艾瑞克·巴纳与奥利维亚·王尔德在此片中饰演一对兄妹，他们从一场赌场抢劫中全身而退，开始了逃亡之旅。当他们逃到冰天雪地的边境地带，偶遇一个落魄的拳击手，而他无辜的家庭被这两位煞星搅得天翻地覆。','Twisty thriller... a wild ride.',12000000,66351,10.19041,5.6,224,95,'2012-11-08','en','/duz8MfBVzlf6gzDgjj5DhkYpTOV.jpg',2.9969828060490515,3,'2026-09-10',2,NULL,NULL),(97630,'猎杀本·拉登','Zero Dark Thirty','十年来，一支由情报与军事精英组成的团队在全球秘密行动，倾尽全力只为达成一个目标：追踪并消灭奥萨马·本·拉登。[哥伦比亚影业]','The Greatest Manhunt in History',40000000,132820716,38.306954,6.7,1702,157,'2012-12-19','en','/wf5Ugq39zmHnBY8CBtcm1bJrB1Z.jpg',3.660293322304816,3,'2026-09-10',2,NULL,NULL),(98357,'破碎之城','Broken City','主人公是一名转行做私家侦探的前警员，他受市长委托，调查市长夫人的婚外情，随后卷入了一场涉及谋杀与丑闻的政治漩涡。','Proof Can Be a Powerful Weapon.',56000000,19701164,29.490057,5.7,593,109,'2013-01-18','en','/ur4olRDYYAqvmKVkdCPhFHnQKYU.jpg',3.232488595263409,3,'2026-09-10',2,NULL,NULL),(98369,'像爵士那样忧郁','Blue Like Jazz','影片改编自Donald Miller的半自传性小说，讲述在大学中，男孩在周围人不认同的目光里，必须要和他童年形成的宗教身份的认定做斗争，并寻找自我的故事','Everybody belongs somewhere',1250000,0,1.6116,5.8,25,106,'2012-04-13','en','/t6boEESUOnO31vD0FPfNAAHV8y.jpg',2.5418384244069787,3,'2026-09-10',2,NULL,NULL),(98549,'The Legend of Hell\'s Gate: An American Conspiracy','The Legend of Hell\'s Gate: An American Conspiracy','In 1870s Texas, a ruthless bounty hunter and an Irish desperado flee the law with a young criminal claiming to possess a treasure more valuable than gold. Crossing paths with some of the West’s most notorious figures, the three outlaws fight for their lives in the pursuit of fame and fortune. Fueled by an ensemble cast and inspired by actual events, THE LEGEND OF HELL’S GATE blends legend and history into a Western spectacle that recounts a treacherous existence in post Civil War Texas.','Justice was delieverd by the fastest gun.',0,0,1.002585,3.9,8,108,'2011-03-03','en','/meg2YdNDQFAPodjz8IHCYepc0vw.jpg',2.3059829320771077,3,'2026-09-10',2,NULL,NULL),(98557,'Dysfunctional Friends','Dysfunctional Friends','A group of college friends are reunited after the death of their very successful friend. The will dictates that each person will receive a large sum of money if they can all successfully stay in his mansion for a week. If one person leaves, everyone forfeits the money.','There\'s a thin line between money and friends.',1800000,0,0.21544,5,4,101,'2012-02-03','en','/oq9UGUeaGzLNR0nAcQZuYLIpuBg.jpg',2.181936619137444,3,'2026-09-10',2,NULL,NULL),(98566,'忍者神龟：变种时代','Teenage Mutant Ninja Turtles','纽约市笼罩在犯罪组织大脚帮的威胁之下，神秘首领施莱德不断扩张势力。女记者爱普莉尔·奥尼尔在追查大脚帮的过程中，意外目睹四名神秘侠客挫败犯罪行动，并发现他们竟是生活在城市下水道中的变异忍者神龟——莱昂纳多、拉斐尔、多纳泰罗和米开朗基罗。随着调查深入，爱普莉尔逐渐意识到自己与这些神龟之间有着意想不到的过去，而施莱德的威胁也正在不断逼近。为了守护这座城市，四兄弟不得不走出隐藏多年的地下世界，与爱普莉尔一同面对真正的敌人……','Mysterious. Dangerous. Reptilious. You\'ve never seen heroes like this.',125000000,477200000,143.350376,5.8,2636,101,'2014-08-07','en','/azL2ThbJMIkts3ZMt3j1YgBUeDB.jpg',3.7983002887014194,3,'2026-09-10',2,NULL,NULL),(98568,'鬼打墙','Enter Nowhere','三个互相不认识的年轻人，不约而同在林间迷路，相聚在一个林间小屋中，三个人怎麽走都走不出去，困了许多天……渐渐的水与食物都已耗尽，他们想办法一直要逃出这片树林，终於发现了这间屋子藏着许多诡异的事件，究竟这片树林与小屋藏着什麽神秘的力量呢？ 他们是否能得救？','Welcome to our nightmare!',0,0,3.637857,6.5,49,90,'2011-10-22','en','/eBWZmjzehYXmVTCsFan9RnzmZ7Z.jpg',2.698901950230792,3,'2026-09-10',2,NULL,NULL),(99826,'The Jimmy Show','The Jimmy Show','A failed New Jersey inventor embarks on a career as a standup comic, turns to drink, and labors to keep his family together.',NULL,0,0,0.098351,8,1,96,'2002-01-16','en','/sqH5e5goeThOmM4DqrrjVQOIuw2.jpg',1.9852982824679812,3,'2026-09-10',2,NULL,NULL),(99861,'复仇者联盟2：奥创纪元','Avengers: Age of Ultron','When Tony Stark tries to jumpstart a dormant peacekeeping program, things go awry and Earth’s Mightiest Heroes are put to the ultimate test as the fate of the planet hangs in the balance. As the villainous Ultron emerges, it is up to The Avengers to stop him from enacting his terrible plans, and soon uneasy alliances and unexpected action pave the way for an epic and unique global adventure.','A New Age Has Come.',280000000,1405403694,134.279229,7.3,6767,141,'2015-04-22','en','/4ssDuvEDkSArWEdyBl2X5EHvYKU.jpg',4.377331967980312,3,'2026-09-10',2,NULL,NULL),(100042,'阿呆与阿瓜2','Dumb and Dumber To','二十年了，罗伊就这么在疗养院待了二十个年头。每个礼拜，他的傻好友哈利贴心照顾探访。突然间，罗伊醒了，哈利惊了，原以为是奇迹，应该大肆庆祝。但靠杯的是，原来罗伊是装的，这只是长达20年的恶作剧...。就这么，阿呆与阿瓜重回归，这次他们不追女人，而是要寻找哈利的肾，究竟，亲爱的小肾肾，你到底在天涯的哪里呢？','The Second Parts Are More Fools',40000000,169837010,67.767785,5.4,1127,110,'2014-11-12','en','/fzh3nxJUOZ2WIJBHVONRSWM30pr.jpg',3.384879135506004,3,'2026-09-10',2,NULL,NULL),(100241,'屠魔战士','I, Frankenstein','在两个百年争斗不休的不朽家族中，其中一个家族制造出科学怪人，具有超人的能力，并且被命名为亚当。自此之后，亚当发现自己身陷争斗中无法脱身，因为两大家族都希望能够获得亚当不死身躯的秘密，好为自己建立一支最强的军团。生性善良的亚当，该如何运用自己的超能力来制止这场因为他的诞生所引发的全面性毁灭战争？','In the battle between good and evil, an immortal holds the key',65000000,71154592,31.324734,5,687,92,'2014-01-22','en','/unrejYZynIS8KCA42JGGAYNKJD6.jpg',3.1621222596900362,3,'2026-09-10',2,NULL,NULL),(100275,'埃迪：梦游食人族','Eddie: The Sleepwalking Cannibal','A once-famous painter rediscovers inspiration when he befriends a sleepwalking cannibal.','Part muse. Part sleepwalking cannibal.',0,1632,0.143784,6.1,30,79,'2012-04-22','en','/2B4wSzrsbK2nnZs5HcZ3LSALQkh.jpg',2.5796420495086183,3,'2026-09-10',2,NULL,NULL),(100402,'美国队长2','Captain America: The Winter Soldier','After the cataclysmic events in New York with The Avengers, Steve Rogers, aka Captain America is living quietly in Washington, D.C. and trying to adjust to the modern world. But when a S.H.I.E.L.D. colleague comes under attack, Steve becomes embroiled in a web of intrigue that threatens to put the world at risk. Joining forces with the Black Widow, Captain America struggles to expose the ever-widening conspiracy while fighting off professional assassins sent to silence him at every turn. When the full scope of the villainous plot is revealed, Captain America and the Black Widow enlist the help of a new ally, the Falcon. However, they soon find themselves up against an unexpected and formidable enemy—the Winter Soldier.','In heroes we trust.',170000000,714766572,72.225265,7.6,5764,136,'2014-03-20','en','/tVFRpFw3xTedgPGqxW0AOI8Qhh0.jpg',4.275312153364673,3,'2026-09-10',2,NULL,NULL),(100975,'纯情的偷窥','Just Looking','1955 年，14 岁的布朗克斯区少年莱尼（Lenny）对自己的暑假充满好奇，他的暑假任务是：目睹两个成年人的 \"爱情行动\"。当母亲把他送到皇后区和怀孕的舅舅舅妈住在一起时，莱尼认为自己的计划注定要失败，直到他遇到了漂亮的成年邻居海蒂，并和一些志同道合的邻居孩子们结成了朋友。很快，莱尼对生活、爱情和成长的理解超出了他的预期。','A voyeuristic coming-of-age comedy.',3000000,0,0.431332,5.8,5,97,'1999-10-21','en','/mNCDnjP2pMCH1PLKE3l6eXyDVUK.jpg',2.2232039169307583,3,'2026-09-10',2,NULL,NULL),(101173,'科里奥兰纳斯','Coriolanus','《科里奥兰纳斯》由莎士比亚的作品改编。原作发生在古罗马时代，大将军科里奥兰纳斯战功累累，却因为倔强的脾气被放逐。科里奥兰纳斯因此纠结过去的敌人进攻罗马帝国，最后他终于被自己的母亲说服，却因此献出自己的生命。电影版把背景搬到了现代的伊拉克战场，“伏地魔”也变身成大将军科里奥兰纳斯。','Nature teaches beasts to know their friends.',7700000,1072602,7.554799,5.9,131,123,'2011-02-14','en','/gyqZU4J9aKu2sIgwLeUBCTZcsHK.jpg',2.9016038700955686,3,'2026-09-10',2,NULL,NULL),(101179,'Truth or Dare','Truth or Dare','A group of college friends celebrate the end of term with a party to end all parties. During a drink and drug-fuelled evening, an innocent game of ‘Truth or Dare’ has a very sore loser, sparking a terrifying sequence of events and a whole new twist on the game of truth or dare – where the truth can kill you.','Truth or Die',0,0,6.679954,5.7,117,95,'2012-08-05','en','/iS6xzzAJIQaGmkcpx4PY3UeAwpq.jpg',2.867851343782726,3,'2026-09-10',2,NULL,NULL),(101267,'Katy Perry: Part of Me','Katy Perry: Part of Me','Giving fans unprecedented access to the real life of the music sensation, Katy Perry: Part of Me exposes the hard work, dedication and phenomenal talent of a girl who remained true to herself and her vision in order to achieve her dreams. Featuring rare behind-the-scenes interviews, personal moments between Katy and her friends, and all-access footage of rehearsals, choreography, Katy’s signature style and more, Katy Perry: Part of Me reveals the singer’s unwavering belief that if you can be yourself, then you can be anything.','Be yourself and you can be anything',12000000,32726956,8.410688,6.5,85,93,'2012-06-28','en','/aCOPVt8ycxXxlWzBuNLabjJb61v.jpg',2.8323875217464014,3,'2026-09-10',2,NULL,NULL),(101299,'饥饿游戏2：星火燎原','The Hunger Games: Catching Fire','第七十四届饥饿游戏已经结束，凯特尼斯出人意料地活了下来，她和“恋人”皮塔将会过上安定闲适的生活。然而，噩梦才刚刚开始，此时，十二个区也暗波涌动，凯特尼斯竟然成了反叛的象征，情窦初开的凯特尼斯陷入爱情的纠结中不能自拔，狩猎伙伴盖尔和竞技场“恋人”皮塔让她难以取舍盖尔和皮塔都深爱着凯特尼斯，为了不让凯特尼斯痛苦，他们不约而同地冷落疏远她。第七十五届饥饿游戏“世纪极限赛”的赛制是，选手是历届获胜者，他们中只有一人能存活。凯特尼斯又将重返杀戮赛场，凯特尼斯没有未来，她只有一死，才能挽救皮塔，这是对皮塔深情的最后报答，爱情与友谊，真诚与猜忌，血腥与牺牲，越来越扑朔迷离……','Every revolution begins with a spark.',130000000,847423452,76.310119,7.4,6495,146,'2013-11-15','en','/vrQHDXjVmbYzadOXQ0UaObunoy2.jpg',4.261683101113247,3,'2026-09-10',2,NULL,NULL),(102362,'死人的复仇','Dead Man Down','剧情  法瑞尔扮演了纽约地下犯罪恶霸Victor，在失去家人之后他一心踏上复仇之路，却又受到了来自拉佩斯所出演的角色的引诱以及敲诈，原来拉佩斯是一起法瑞尔罪行的受害者，两人之间将上演一场复仇大战。','Blood demands blood',0,18074539,29.647844,5.9,638,118,'2013-03-08','en','/v3q5Z1SUc2dMd63pI23ply2k5Yr.jpg',3.27447369109865,3,'2026-09-10',2,NULL,NULL),(102382,'超凡蜘蛛侠2','The Amazing Spider-Man 2','For Peter Parker, life is busy. Between taking out the bad guys as Spider-Man and spending time with the person he loves, Gwen Stacy, high school graduation cannot come quickly enough. Peter has not forgotten about the promise he made to Gwen’s father to protect her by staying away, but that is a promise he cannot keep. Things will change for Peter when a new villain, Electro, emerges, an old friend, Harry Osborn, returns, and Peter uncovers new clues about his past.','No more secrets.',200000000,705717432,89.270217,6.5,4179,142,'2014-04-16','en','/bU7nTmvmy0h3VUP01v1T2imgH6N.jpg',3.94724821766045,3,'2026-09-10',2,NULL,NULL),(102651,'沉睡魔咒','Maleficent','The untold story of Disney\'s most iconic villain from the 1959 classic \'Sleeping Beauty\'. A beautiful, pure-hearted young woman, Maleficent has an idyllic life growing up in a peaceable forest kingdom, until one day when an invading army threatens the harmony of the land.  Maleficent rises to be the land\'s fiercest protector, but she ultimately suffers a ruthless betrayal – an act that begins to turn her heart into stone. Bent on revenge, Maleficent faces an epic battle with the invading King\'s successor and, as a result, places a curse upon his newborn infant Aurora. As the child grows, Maleficent realizes that Aurora holds the key to peace in the kingdom - and to Maleficent\'s true happiness as well.','Don\'t believe the fairy tale.',180000000,758539785,110.620647,7,4496,97,'2014-05-28','en','/ik8PugpL41s137RAWEGTAWu0dPo.jpg',4.142022656707033,3,'2026-09-10',2,NULL,NULL),(102840,'陌生性接触','Sex with Strangers','对于一些已婚夫妇来说，性是一种痴迷，压倒了他们对严格一夫一妻制的信念。实现性幻想的能力比坚持任何爱情或婚姻的传统都更重要。《陌生性接触》为三对这样的夫妇描绘了一幅真实亲密的肖像，从幻想实现的喜悦到关系破裂的绝望，展示了他们的生活方式如何深刻地影响着他们的生活。詹姆斯和特蕾莎，一对三十多岁的夫妇，把他们的房车当作一座快乐的宫殿，从一个俱乐部到另一个俱乐部，无论他们走到哪里，都会引诱情侣。Calvin和Sarah正在考虑结婚，这时他们遇到了Julie，Julie不会摇摆，也不是双性恋——直到她爱上Calvin。对于Shannon和Gerard来说，心理剧几乎取代了性，他们热衷于荡秋千，尽管他们质疑这种生活方式是否真的适合他们。。。',NULL,0,0,0.014406,5,1,0,'2002-02-22','en','/hKoiQdPIwPpLvDq60pLkhVNBTe5.jpg',1.9838726960852875,3,'2026-09-10',2,NULL,NULL),(102899,'蚁人','Ant-Man','曾因违法入狱的斯科特·朗刑满释放后，一心希望重新开始生活，并修复与女儿凯茜的关系。然而前科让他处处碰壁，一次铤而走险的入室盗窃，却让他得到了一套能够将身体缩小到蚂蚁大小、同时增强力量的神秘战衣。战衣的主人、科学家汉克·皮姆很快现身，并告诉斯科特，这一切其实是为了考验他。随着汉克昔日的门生达伦·克劳斯逐渐逼近皮姆留下的技术，斯科特不得不接受训练，成为新一代“蚁人”，并利用自己最擅长的方式完成一场危险的秘密行动……','Heroes don\'t get any bigger.',130000000,519311965,120.09361,7,5880,117,'2015-07-14','en','/rQRnQfUl3kfp78nCWq8Ks04vnq1.jpg',4.2296985405792915,3,'2026-09-10',2,NULL,NULL),(103328,'神圣车行','Holy Motors','受导演对加长礼车在收工后生活的着迷启发，德尼·拉旺饰演的奥斯卡先生在一天之内，先后化身为十个截然不同的角色——从帮派分子、年老富翁，到忧心忡忡的父亲和无政府主义流浪汉。本片包含若干意想不到的客串演出，堪称影坛罕见的珍宝：一部真正独一无二的作品。[Indomina Releasing]','From dawn to dusk, a few hours in the shadowy life of a mystic man named Monsieur Oscar.',0,641100,9.140936,6.9,228,115,'2012-07-02','en','/htqJeUz86S2sowWpnQX4LK0Nlcm.jpg',3.0908908912417736,3,'2026-09-10',2,NULL,NULL),(103370,'黑疯婆子的证人保护计划','Madea\'s Witness Protection','乔治·尼德曼是一个投资银行家，因卷入案件和家人被列入证人保护计划中，被迫搬到玛蒂南部的家中。两人也由此冲突不断。本片的剧本从2009年起就开始筹备，是泰勒的电影里剧本写作周期最长的一部。','Believe it or not, they know too much.',0,0,7.050951,5.9,52,114,'2012-06-29','en','/4P6d7kVDB60Ydmk9WAhrPCWrARI.jpg',2.7077762655915127,3,'2026-09-10',2,NULL,NULL),(103620,'杀人狂魔','Maniac','多年前，影片主人公弗兰克的母亲惨死于一场车祸，尽管母亲生前粗暴的虐待他，还以卖身为生，但弗兰克仍然想念她，弗兰克不想让母亲离开自己，甚至希望她能改过自新，而弗兰克在变态心理的唆使下，将杀人视作自己的发泄途径。于是，很多无辜的女性成了这个恶魔的猎物，弗兰克剥下她们的头皮，像假发一般戴在公寓里摆放的服装模特的头上，如数家珍的陈列起来。一次在公园里，弗兰克邂逅了摄影师安娜，安娜希望帮助他完成展览，他们的友谊发展成弗兰科着魔般的困扰，她正解开他压抑着的跟踪与杀戮的欲望…','I Warned You Not to Go Out Tonight.',6000000,31081,19.331884,6,316,89,'2012-12-26','en','/nbDkRvhmbYnHDXkoq0sF0PLeo8j.jpg',3.1182487375093686,3,'2026-09-10',2,NULL,NULL),(103663,'The Hunt','Jagten','A teacher lives a lonely life, all the while struggling over his son’s custody. His life slowly gets better as he finds love and receives good news from his son, but his new luck is about to be brutally shattered by an innocent little lie.','The lie is spreading.',3800000,16800000,21.826888,7.9,927,115,'2012-08-28','da','/phBQ7y7FwqhpUzQid32mnX91CmO.jpg',3.6676818608803994,3,'2026-09-10',2,NULL,NULL),(103731,'污泥','Mud','影片讲述了两个小男孩的冒险之旅。这两个小男孩叫做艾莱斯和奈科伯恩再一次很普通的出游里，他们在密西西比河的小岛上发现了一名叫做玛德的男人。玛德说自己有着辉煌的过去，他说自己曾经在德克萨斯杀了一个人，而为政府卖命的赏金猎人正在气势汹汹找她。他说自己正在计划这要和自己的爱人珍妮弗见面，并私奔。而现在，珍妮弗正在镇子上等他。  　　虽然对玛德的说辞表示怀疑，但是好奇心还是驱使两个男孩同意帮助玛德。不久之后，玛德的说辞就得到了印证。赏金猎人来了，和他们一起的，还有一个漂亮的女孩……',NULL,10000000,21587700,17.663353,7,1068,130,'2013-05-01','en','/o2jT5jQdKh1HAF0fMKuGwBOwOYB.jpg',3.54688746504701,3,'2026-09-10',2,NULL,NULL),(103903,'Outside Bet','Outside Bet','A group of print workers in 1980s London club together to buy a race horse.',NULL,7500000,0,0.086731,5.8,2,101,'2012-04-27','en','/3VROYF5j0AjqI8hAtcBAYcQzHA6.jpg',2.072284336700693,3,'2026-09-10',2,NULL,NULL),(104755,'塞拉的领主','The Lords of Salem','小镇上一个当地的DJ错误的释放了一个地狱般的诅咒，原来三百年前在塞拉镇上的乡民每天走着的这条街道，曾经聚集了无辜的人们，他们因为身为女巫而被判有罪并且将执行死刑。这就是塞拉的领主在塞拉实行的铁腕手段，但是四个女巫在被拷打和杀害时秘密发誓，总有一天他们会回来报仇的。','We\'ve been waiting... we\'ve always been waiting',1500000,1165882,14.504326,5.1,242,101,'2012-09-10','en','/nqZ6CGGZpQWt139YioekSYHvvkU.jpg',2.9839608611798067,3,'2026-09-10',2,NULL,NULL),(104896,'义犬报恩','A Dog of Flanders','尼洛和爷爷相依为命，住在安特卫普镇的北方。爷孙两人靠运送牛奶维生。在教堂里有幅画深深影响着尼洛，这是让尼洛热衷于绘画的原因……尼洛在运送牛奶的途中，看到了受到五金行老板虐待的狗帕奇，心中念念不忘帕奇被欺负的情景，不知帕奇会再和尼洛有任何的奇遇吗？',NULL,0,0,0.838938,6.4,6,96,'1999-08-27','en','/w65gcoD1zwmaPLM0gM8s9eynGcj.jpg',2.25895206795088,3,'2026-09-10',2,NULL,NULL),(105864,'恐龙当家','The Good Dinosaur','6500万年前，一颗小行星与地球擦肩而过，称霸这个世界的恐龙懵懵懂懂地逃过了灭顶之灾。之后又过了数百万年，恐龙的智力得到进化，它们学会种植、畜牧、建筑，并且拥有属于自己的语言和家庭。某座山脚下的平原地带，雷龙一家迎来三个性格各异的娃娃，最小的阿洛（雷蒙德·奥乔亚 Raymond Ochoa 配音）孱弱胆怯，与父亲的生离死别更在他的心中投下难以磨灭的阴影。一连串的事件过后，他与妈妈、两个哥哥相隔万里。阿洛将这一切都归罪于原始人类的小孩点点（杰克·布赖特 Jack Bright 配音）。而点点似乎不为所动，他主动亲近阿洛，仿佛是一条忠诚勇敢的小狗。在充满坎坷和危险的回家之路上，阿洛与点点结伴而行，而这两个本不该碰面的恐龙和人类，将缔结超越了种族和时空的纯真友情…… ©豆瓣','Little Arms With Big Attitude',175000000,331926147,51.692953,6.6,1736,93,'2015-11-14','en','/h5Wz87AAmosFSFJymx1xoywAype.jpg',3.6747581368562634,3,'2026-09-10',2,NULL,NULL),(106646,'华尔街之狼','The Wolf of Wall Street','在危机四伏的投资界，掌管史崔顿·奥克蒙公司的乔丹·贝尔福特生活侈靡、实力雄厚。1987年，22岁的乔丹进入罗斯柴尔德公司，从接线员做起，在高级经纪人马克指点下，进入了股票经纪人充满毒品和欲望的世界，半年后因“黑色星期一”，乔丹转投靠贩卖“便士股票”的小公司，凭借巧舌如簧获得成功，与邻居唐尼和一班朋友另立门户，游走在灰色地带获利颇丰，获称“华尔街之狼”，然而，FBI已经开始留意他。','EARN. SPEND. PARTY.',100000000,392000694,95.007934,7.9,6571,180,'2013-12-25','en','/kW9LmvYHAaS9iA0tHmZVq8hQYoq.jpg',4.442354953447569,3,'2026-09-10',2,NULL,NULL),(106747,'Machete Kills','Machete Kills','Ex-Federale agent Machete is recruited by the President of the United States for a mission which would be impossible for any mortal man – he must take down a madman revolutionary and an eccentric billionaire arms dealer who has hatched a plan to spread war and anarchy across the planet.','Trained to kill. Left for dead. Back for more.',12000000,15008161,29.072964,5.3,631,107,'2013-09-12','en','/rIKFa687P6adopP5g4jGnnbdKvB.jpg',3.18739404459872,3,'2026-09-10',2,NULL,NULL),(106845,'最后一日','Re-Kill','丧尸病毒爆发已经五年了，人们渐渐觉得丧尸的威胁开始减弱。R-Division部队里的男人和女人们，发现了丧尸病毒二次爆发的迹象。如果这种情况真的发生，那么人类可能面临无法生存的境地。','We are the endangered species.',9500000,0,5.346205,4.9,34,87,'2015-10-16','en','/1YXUBM7JNroEMThH6Kls71Twg4v.jpg',2.6018055942965197,3,'2026-09-10',2,NULL,NULL),(107315,'低于零度','Below Zero','创作进入瓶颈的知名作家杰克（爱德华·福隆 Edward Furlong 饰），为了写出足够恫吓人心的恐怖之作，在经纪人的安排下来到了冰天雪地的山区。单亲妈妈佩妮（克莉丝汀·布丝 Kristin Booth 饰）带着儿子科尔接到了杰克，并将其带回丈夫曾经经营的屠宰场。佩妮风趣幽默，屠宰场内的摆设也足够阴森。谁知刚刚还有说有笑的佩妮，突然一转身将杰克锁在屠宰室内，声称是受经纪人所托，要在接下来的五天内逼迫杰克写出合格出色的剧本','There\'s nothing scarier than a blank page.',0,0,1.36514,4.4,12,0,'2011-10-22','en','/yZtJz83LOjn5tI6QSKMQfrNHpvC.jpg',2.3855455463909445,3,'2026-09-10',2,NULL,NULL),(107811,'二十一岁派对','21 & Over','成绩优异的男孩杰夫·陈（贾斯汀·钱 Justin Chon饰）从来不会做出什么出格的事情。他正准备参加医学院的入学面试。面试的前一天，是他21岁的生日。在杰夫两个死党凯西（斯盖拉·阿斯丁 Skylar Astin饰）和米勒（迈尔斯·特勒 Miles Teller饰）的怂恿和劝说下，他们相约去花花世界里庆祝杰夫的生日，也狠狠地疯狂一把。然而他们一开始喝酒就无法停止了。局面慢慢变得失去了控制，变得疯狂而可怕。©豆瓣','Finally.',13000000,48065672,35.522027,5.7,737,93,'2013-03-01','en','/azrjh38R7X9bznCocChvmXTOtF9.jpg',3.286696742709522,3,'2026-09-10',2,NULL,NULL),(107846,'金蝉脱壳','Escape Plan','雷·布雷斯林（西尔维斯特·史泰龙 Sylvester Stallone 饰）是最强的越狱高手，曾在8年内成功逃出14座安全防卫工程最严密的重刑监狱。他的真正身份是美国国家安全局的监狱安管专家，每一次越狱成功，就代表他能找出该个监狱的安管漏洞，进而强化改善。这回是雷退休前的最后一次任务，要挑战传说中最滴水不漏的超级监狱“坟墓”，然而当他入狱后，却发现这不但是个深埋海底不见天日的死狱，就连他决定放弃任务，想表明身份出狱时，典狱长竟更变本加厉地折磨他。雷发现他真的被出卖了，想要逃出去，似乎只有找狱中最莫测高深的牢友“教堂”（阿诺·施瓦辛格 Arnold Schwarzenegger 饰）来合作，两人不但要面对无情看守员霍布斯（詹姆斯·卡维泽 Jim Caviezel 饰），还要面对野蛮警卫（维尼·琼斯 Vinnie Jones 饰）的威胁。如何在乌烟瘴气的监狱中保持稀有的人性之光，并逃出监狱成为两人的最大挑战……','No one breaks out alone.',50000000,122915111,44.478043,6.7,1659,115,'2013-10-09','en','/pP9oRWH5bmpwPWWdXHzz4RaKPsb.jpg',3.6678847800019403,3,'2026-09-10',2,NULL,NULL),(107985,'世界尽头','The World\'s End','“血与冰激淋三部曲”（Blood and Ice Cream Trilogy）的最后一部（前两部是《僵尸肖恩》和《热血警探》）\r 　　影片讲述少年时代尝试过“超棒酒吧漫游”的五位好友，因为其中一人想参加豪饮马拉松而在多年之后重新聚首。他们被一个名叫Gary King的家伙说服，准备再来一次当年的“壮举”。Gary是个40岁的老家伙，青少年时期就深坠烟海。他将有点不情不愿的五人帮拽回他们的家乡，并试图再 次去寻找那个传说中的酒吧“世界尽头”。几人回望过去检视现在，意识到真正的难题是未来，并不只是他们自己，而是关系到全人类的生存。','Good food. Fine ales. Total Annihilation.',20000000,46089287,55.964605,6.7,1778,109,'2013-07-18','en','/kpglnOBYmKn0AkkWDzGxzKHDbds.jpg',3.711708967345191,3,'2026-09-10',2,NULL,NULL),(108346,'当你微笑时','Dreaming of Joseph Lees','在可怕复杂的心理纠缠下，一部叙述激情、禁忌与背叛之爱情片。伊娃（萨曼莎·莫顿饰）非常爱慕大胆又世俗的约瑟（鲁伯特·格雷夫斯饰）。当伊娃与亨利交往时，她对约瑟的幻想有增无减。终于约瑟再次进入她的世界，他们就像干柴遇到烈火般地展开热恋，同时，伊娃对亨利的忠贞面临极大考验…',NULL,2000000,7,0.11615,8,1,92,'1999-10-29','en','/xiDtcNXOhSPcjFcnX6BUTWiws3B.jpg',1.985338938886519,3,'2026-09-10',2,NULL,NULL),(109091,'The Counselor','The Counselor','A rich and successful lawyer named Counselor is about to get married to his fiancée but soon meets up with the middle-man known as Westray who tells him his drug trafficking plan has taken a horrible twist and now he must protect himself and his soon bride-to-be lover as the truth of the drug business uncovers and targets become chosen.','Sin Is A Choice.',25000000,71009334,35.022029,5,712,117,'2013-10-25','en','/9Vmj9fbiRLYcsin88bBFMFTaytP.jpg',3.175336820467156,3,'2026-09-10',2,NULL,NULL),(109410,'42','42','The powerful story of Jackie Robinson, the legendary baseball player who broke Major League Baseball’s color barrier when he joined the roster of the Brooklyn Dodgers. The film follows the innovative Dodgers’ general manager Branch Rickey, the MLB executive who first signed Robinson to the minors and then helped to bring him up to the show.','The True Story Of An American Legend',40000000,95020213,31.884559,6.8,787,128,'2013-04-12','en','/zU0G5HB4vcxYa3Jv9c0fClHAkTL.jpg',3.461969944065454,3,'2026-09-10',2,NULL,NULL),(109414,'世界末日','This Is the End','故事讲述了烂仔帮好兄弟一齐来到詹姆斯·弗兰科家中开末日狂欢派对，没想到一切关于末日的猜想都应验了。本片中各路明星均以现实身份登场。','Nothing ruins a party like the end of the world.',32000000,126041322,38.21708,6.3,2359,107,'2013-06-12','en','/zvAajCc2zAyLrO1HufnAm6KY9hO.jpg',3.6504876754343893,3,'2026-09-10',2,NULL,NULL),(109417,'年度之战：梦之队','Battle of the Year','根据2005年一群男孩参加奥林匹克大赛街舞\"年度之战\"的经历改编，讲述了乔什·哈洛威饰演的教练如何带领他的队伍夺魁的故事。','The World is watching',20000000,16549477,8.237336,5.9,88,110,'2013-09-21','en','/dB4L9yt9eFbVhx8tSuDUHoMeN4x.jpg',2.820418218462076,3,'2026-09-10',2,NULL,NULL),(109418,'长大成人2','Grown Ups 2','亚当·桑德勒和妻子（萨尔玛·海耶克 饰）为了让孩子有更好的生活，把家搬回了家乡的小镇，这里有很多他儿时的玩伴。小镇上雷人趣事不断：清晨睁眼醒来你能看到一只麋鹿在床头向你道早安；还会在一帮年轻小伙（泰勒·洛特纳、帕特里克·施瓦辛格等人饰）的挑衅下玩裸泳；这里的警察（沙奎尔·奥尼尔 饰）也很不一般，喜剧细胞与众非凡；凯文·詹姆斯遇到的年轻洗车队真是囧到家……','Just because they\'re a little older doesn\'t mean they\'ve grown up.',80000000,246984278,45.589568,5.8,1155,100,'2013-07-11','en','/d0uw6R0ig33QM16pB13Api1TOrW.jpg',3.4118854802357683,3,'2026-09-10',2,NULL,NULL),(109421,'副作用','Side Effects','艾米丽是一位性感美丽却令人不安的年轻女子。她的丈夫被囚禁在监狱中，而她则天天服用大量的处方药来缓解焦虑和低落。如今她的丈夫已经入狱三年，而她在按医嘱服用了一种新药物后，不知情的谋杀了自己的丈夫并最终接受法庭的审判。','One pill can change your life.',30000000,63372757,48.237797,6.4,1323,106,'2013-02-07','en','/1mqoQemH9pRrol1wJHxFEwYowKz.jpg',3.560514106301395,3,'2026-09-10',2,NULL,NULL),(109424,'菲利普船长','Captain Phillips','本片是一部多层次的电影，深入探讨了2009年索马里海盗劫持美国货轮“马士基·阿拉巴马”号的事件。通过导演保罗·格林格拉斯特有的镜头语言，它既是一部扣人心弦的惊悚片，也是对全球化多重影响的一次复杂描绘。影片聚焦于“阿拉巴马”号指挥官理查德·菲利普斯船长与劫持他的索马里海盗头目缪斯之间的关系。当缪斯及其同伙盯上菲利普斯手无寸铁的货轮时，两人便踏上了无法避免的冲撞之路；在索马里海岸外145英里处随后的对峙中，两人都将发现自己受制于无法掌控的力量。[索尼影视娱乐]','Out here survival is everything.',55000000,95000000,52.786917,7.6,2454,134,'2013-10-10','en','/8Td0kkocW6sD3uRpzwfMfkqMWhx.jpg',3.993466159226642,3,'2026-09-10',2,NULL,NULL),(109428,'鬼玩人','Evil Dead','改编自同名电影，1981年上映的《鬼玩人》是《蜘蛛侠》导演山姆·雷米的成名作，故事中，五个年轻人驾车外出度假，来到一个偏僻的地方，住进一座破旧小木屋，当晚他们在屋里发现了一本看起来很恐怖的书，并无意中引来了住在附近森林中的魔鬼。主人公们陆续被恶魔附体，只剩下最后一人与魔鬼血战到底。','The most terrifying film you will ever experience.',17000000,97542952,33.912116,6.4,1723,91,'2013-04-05','en','/btuI4YavfJupHnHwUs9MZejdsol.jpg',3.590111440459585,3,'2026-09-10',2,NULL,NULL),(109431,'身份窃贼','Identity Thief','在外人眼里，戴安娜（梅丽莎·麦卡西 Melissa McCarthy 饰）是一个挥金如土的富婆，无论是多么贵重的奢侈品，戴安娜都能连眼睛都不眨一下的刷卡将它收入囊中。对于自己的挥霍，戴安娜并不感动心疼，因为她刷卡后产生的账单，都将被寄到一个名为桑迪（杰森·贝特曼 Jason Bateman 饰）的男人那里。原来，戴安娜是一个信用卡大盗，她所使用的钱，全都是桑迪辛辛苦苦赚来的积蓄。\r 　　当警察找到桑迪时，他才发现自己的信用卡被盗刷了，愤怒的桑迪决定亲自前往戴安娜所在的迈阿密，发誓要将这个懒惰的蛀虫捉拿归案。而当桑迪顺利的找到了戴安娜并准备将她带回丹佛时，这个可怜男人的好运用光了，这件看似简单的事情渐渐的脱离的桑迪的控制。','She\'s having the time of his life',35000000,173965010,34.005726,5.6,1645,111,'2013-02-07','en','/p9Lq8K7xG4ote5C4ihx7ZWX6taD.jpg',3.413088092973895,3,'2026-09-10',2,NULL,NULL),(109443,'王牌播音员2','Anchorman 2: The Legend Continues','七零年代圣地牙哥最出名的王牌主播朗伯甘地(威尔法洛 饰演)又回来了！另外当然还有朗美丽的主播搭档兼贤内助妻子薇洛妮卡(克莉丝汀娜亚柏盖特 饰演)、气象专家布瑞克(史提夫卡尔 饰演)、街头热血主播布莱恩(保罗路德 饰演)以及体育播报员钱普等。当他们接下纽约第一个24小时新闻频道挑战时，所有人皮都绷紧严阵以待。','It\'s kind of a big deal',50000000,173649015,38.125008,6,923,119,'2013-12-18','en','/23UgSzLB7NKnfLIXquBTDXdI0BL.jpg',3.384822098047483,3,'2026-09-10',2,NULL,NULL),(109445,'冰雪奇缘','Frozen','Young princess Anna of Arendelle dreams about finding true love at her sister Elsa’s coronation. Fate takes her on a dangerous journey in an attempt to end the eternal winter that has fallen over the kingdom. She\'s accompanied by ice delivery man Kristoff, his reindeer Sven, and snowman Olaf. On an adventure where she will find out what friendship, courage, family, and true love really means.','Only the act of true love will thaw a frozen heart.',150000000,1274219009,165.125366,7.3,5295,102,'2013-11-27','en','/itAKcobTYGpYT8Phwjd8c9hleTo.jpg',4.386074419949123,3,'2026-09-10',2,NULL,NULL),(109451,'天降美食2','Cloudy with a Chance of Meatballs 2','一度平静的斯沃罗夫小岛被弗林德·洛克伍德（比尔·哈德 Bill Hader 配音）的天才发明复食机所摧毁。最终他成功破坏复食机，并打算和山姆（安娜·法瑞丝 Anna Faris 配音）他们重建美好家园。这时候，弗林德最崇拜的偶像——丽芙公司老板切斯特 V（威尔·福特 Will Forte 配音）从天而降。切斯特是一个天才发明家，他的公司更是云集了全世界顶尖的科学家。切斯特邀请弗林德加入丽芙公司，并承诺带着岛民前往加利福尼亚，而他的公司将负责清理破败的小岛。为了成为幻想发明家，弗林德拼尽全力开展研发。与此同时，故乡却传来不好的消息。许多清理者被活着的食物所捕获，似乎复食机并未完全摧毁，并且朝着弗林德不曾预料的方向继续发展。在切斯特的命令下，他和山姆、老爹以及其他伙伴们踏上了返乡的旅途，寻找解决麻烦的办法……','Something big was leftover.',78000000,248384621,41.247402,6.4,915,95,'2013-09-26','en','/juxyifgkCPqGRr03SPmc9PS7Gdk.jpg',3.456950018530436,3,'2026-09-10',2,NULL,NULL),(109491,'美丽生灵','Beautiful Creatures','故事描述平凡少年伊森，竟然爱上了来自女巫家族的蕾娜，而且在还没见过她之前，就已经在梦中爱上她了。伊森几个月来，一直重复做着相同的梦，有个神秘女孩在南北战争的战场上等待他。伊森渴望跟她在一起，不过有个未知的危险伺机而动，天空不时出现枪响般的闪电，而在他未能触及那个女孩之前就遭到闪电击毙。然而，这场危机四伏的怪梦却唤醒伊森的自觉，他从小就住在南卡罗来纳州的盖林镇，是一个跟不上21世纪的保守南方小镇，凡事从不改变或进展。他感觉受困在单亲的家中，父亲因母亲的骤逝变得孤僻自闭，伊森只能靠阅读幻想不同的生活。不过伊森的平凡人生因蕾娜的出现起了变化，这个美丽又神秘的女孩是麦坎雷的姪女，人称雷老头的麦坎是隐遁在雷氏庄园的主人。伊森立刻受到蕾娜吸引，即使她似乎会带来不明的毁灭力量，而且她竟然是一名巫师，拥有无法掌控的强大力量。思想保守的林肯太太领导全部镇民想要驱逐蕾娜，另一方面了解隐情的当地图书馆员艾玛害怕历史可能会重演，这段无人知晓的过去叙说着雷氏家族的秘密及蕾娜所受的诅咒，在她逼近的16岁生日来到时，她注定会转化为光明或黑暗巫师。蕾娜的命运似乎已由这个诅咒决定，这也使她和伊森卷入充满魔咒和危险的混乱局面，他们可能永远无法逃脱既定的宿命……。','Dark secrets will come to light.',60000000,60052138,40.721373,5.6,984,124,'2013-02-13','en','/xWsWF2wkfvifOOlswqy2Dq8JCKD.jpg',3.3351494030554285,3,'2026-09-10',2,NULL,NULL),(109513,'逃脱','Hit & Run','查理·布朗森和自己的女朋友安妮准备安安静静地在一个小镇上生活，但是过去的麻烦却自己找上了门来，布朗森以前的冤家埃里克斯·迪米特希望能从上一次的抢劫中分到自己应有的那笔钱。发觉此地已经不再安全的布朗森决定带着安妮驱车前往洛杉矶，开始一段新的生活。 　　于是，他们坐上了自己的那辆老式林肯，走上了追寻新生活的道路。直到这个时候，安妮才知道布朗森曾经是一个抢劫团伙里的司机。 　　可是，他们追寻新生活的道路走得并不平坦。布朗森的同伙、安妮的前男友，还有一个美国警察，都对他们紧追不舍，这对亡命鸳鸯能顺利地逃到洛杉矶，开始自己的新生活么？','A Comedy That Never Takes Its Foot Off The Gas',2000000,14400000,16.668854,5.5,224,100,'2012-08-22','en','/2n3FTpj2AmucfvgZ5tunZxZ2Jvf.jpg',3.004725213151038,3,'2026-09-10',2,NULL,NULL),(109729,'峡谷','The Canyons','《峡谷》的故事发生在美国洛杉矶，一群光鲜亮丽的二十多岁年轻人沉浸在荒淫无度及物质横流的生活中，当他们无比享受这种纸醉金迷的生活时，一个前来复仇的神秘人打破了他们极致享乐的生活，他恐吓这些年轻人将毁掉这美好的一切。这部电影包含了性欲、贪念、背叛等元素。著名男艳星詹姆斯·丁恩在片中继续他的老本行，招揽女性做性交易，而坏女孩琳赛·洛翰将饰演丁恩的好友。','It\'s not the hills.',250000,56825,6.978907,4.1,75,99,'2013-07-29','en','/5tZR5o2KJXY6UGxoCsuCmZqROwO.jpg',2.7337674623301047,3,'2026-09-10',2,NULL,NULL),(110402,'上帝难为','Трудно быть богом','一群科研人员被派往行星阿尔卡纳，该星球正处于类似地球中世纪的受压迫政权统治下。当地民众正遭受一项禁令的折磨——任何具备读写能力者都将被查禁。科学家们必须避免影响阿尔卡纳的政治与历史进程，必须隐姓埋名工作，且必须保持中立。被当地人视为某种未来神灵的唐·鲁马达，试图拯救当地知识分子免遭迫害。他不得不面对这样的立场抉择：“若置身上帝之位，你当如何作为？”[Kino Lorber]',NULL,7000000,1310673,3.120016,6.7,41,170,'2013-02-27','ru',NULL,2.6619237232877873,3,'2026-09-10',2,NULL,NULL),(110415,'雪国列车','설국열차','为了遏制全球变暖，人类实施了一场大规模气候干预实验，却意外让整个地球陷入极寒，绝大多数生命因此消亡。幸存者只能生活在一列依靠永动引擎不断环绕地球行驶的列车上，并在封闭的车厢中形成了森严的等级制度。十七年后，长期挨饿受压迫的末节车厢居民终于决定反抗，在柯蒂斯的带领下向列车前方进军。为了打开一道道封锁的车厢门，他们救出被囚禁的安保专家南宫民秀，而随着众人不断靠近车头，这列维系着人类最后文明的列车也开始显露出越来越多隐藏在秩序背后的秘密……','AD 2031, the passengers in the train are the only survivors on Earth.',39200000,86758912,64.238688,6.7,2854,126,'2013-08-01','ko','/kw6YQudA0TMcNmGUGy5XIw7zbnV.jpg',3.8487058047369667,3,'2026-09-10',2,NULL,NULL),(110683,'女强盗','The Wicked Lady','芭芭拉被邀请去参加她孪生姐妹卡洛琳和拉尔夫爵士的婚礼，本来她只是当伴娘的，可是她却勾引了拉尔夫爵士并和他结婚了。婚后她只是个家庭主妇，不久她就觉得生活太无聊了。她开始蒙面抢劫去寻求刺激。她还遇见了另一个著名的劫匪并与他们结成了团伙。虽然身份可能暴露会带来生命风险，她还是继续着她的蒙面大盗的生涯……','She seduced, robbed and murdered...That was on her good days.',0,0,0.289433,4.3,4,98,'1983-04-21','en','/wpePR1PBAT3gQDsmDZQtB3q6ZLi.jpg',2.180958767023159,3,'2026-09-10',2,NULL,NULL),(111190,'忘年恋曲','Adoration','影片讲述了娜奥米·沃茨与罗宾·怀特饰演的两个母亲分别与对方的儿子产生了忘年恋情。',NULL,16000000,318982,18.790221,6.1,291,100,'2013-04-03','en','/hIQqIeG7Ude0QRUFntdLtsAUEBB.jpg',3.1083146781598012,3,'2026-09-10',2,NULL,NULL),(111794,'20 Dates','20 Dates','Myles is divorced in L.A. He wants a love life and a film career. So he decides to go on 20 dates and find true love in front of a camera, making his first feature. His patient agent, Richard, finds a $60,000 investor, the shadowy Elie. Myles starts his search, sometimes telling his date she\'s being filmed, sometimes not. Elie wants sex and titillation, Myles wants it \"real.\" Myles regularly talks with his old film teacher, Robert McKee, who wonders if love is possible in modern life. Half-way through the 20 dates, Myles meets Elisabeth; she\'s everything he desires and she likes him. Can he finish the 20 dates, satisfy Elie, and complete his film without losing Elisabeth?','A comedy so real you\'ll think it\'s fiction.',0,0,0.408073,3.7,3,87,'1998-01-01','en','/79TTGQZrOAzwuWxcOy8y6k6Ldm0.jpg',2.132775868657957,3,'2026-09-10',2,NULL,NULL),(112430,'The Company','The Company','Real-life figures from the Cold War era mix with a fictional story based on a group of CIA operatives and their counterparts in the KGB, MI6, and the Mossad.',NULL,0,0,1.485324,7,12,276,'2007-08-05','en',NULL,2.398461366884389,3,'2026-09-10',2,NULL,NULL),(112456,'滑板少年','Hardflip','Hardflip follows the story of Caleb (Randy Wayne) a young skater whose ill mother (Rosanna Arquette) and absent father (John Schneider) leave him reaching for the only hope he has...becoming a sponsored skater. After his mother falls ill, Caleb finds a stack of old love letters. He sets out to find the father he never knew and inadvertently begins a journey he never could have expected. This story explores what happens when we let go of our anger and pain and forgive those who have hurt us most.','What do you do when your life does a 180?',1000000,0,0.341461,4.7,5,114,'2012-06-01','en','/At3R00Jvpf3W03oWSYmplKjyWGZ.jpg',2.2207489315904136,3,'2026-09-10',2,NULL,NULL),(112937,'The Oogieloves in the Big Balloon Adventure','The Oogieloves in the Big Balloon Adventure','It\'s Schluufy\'s birthday, and the Oogieloves (Goobie, Zoozie and Toofie), along with their friends J. Edgar, Windy Window and Ruffy, are organizing a party. (Shh! It\'s a secret.) Everything is going along just perfectly until J. Edgar trips and loses the last five magical balloons in all of Lovelyloveville--OH NO! The Oogiloves set out to find the magical balloons in time to save their friend\'s party. Along the way, they meet some very interesting characters indeed, including Dotty Rounder (Cloris Leachman), Bobby Wobbly (Carey Elwes), Milky Marvin (Chazz Palminteri), Rosalie Rosebud (Toni Braxton) and Lola and Lero Sombero (Christopher Lloyd and Jaime Pressly). Can these new friends help them recover the magical balloons and get back to the cottage in time to celebrate Schluufy\'s surprise birthday?',NULL,0,0,0.28576,2.2,8,88,'2012-08-29','en','/qb6KVMsqljMnqYNLtOUfOIJrS6A.jpg',2.2988053241206736,3,'2026-09-10',2,NULL,NULL),(112949,'爱情避风港','Safe Haven','一个雨夜，一个叫做凯蒂的女人逃离了自己的生活，坐上长途汽车，来到了北卡罗来纳州的南港。并在这个小城里安定了下来。她的到来就像是一个意外，让南港的人猜测连连。  　　凯蒂是个漂亮的女人，平日里行事低调，小心翼翼，而且还很恭谦。看上去，她是不想在这里久留的。可是一连串的时间，把她和一个叫做艾利克斯的男人联系在了一起。艾利克斯做了一辆自行车给了凯蒂，这两个人就这么像是在了一起。慢慢地，凯蒂卸下了自己的心防。随后，这两个年轻人相爱的。可是，即便是相爱，也没有办法让凯蒂逃离自己之前的生活，她无时不刻不再被自己过去的黑暗所困扰。而凯蒂也明白，自己必须在安定生活、爱情和不断的逃离之间做出一个选择——哪怕这个选择是痛苦的。  　　当然，在人生中最黑暗的时刻，似乎只有爱情才是她的真正意义上的避风港。','You know it when you find it',28000000,97594140,37.729059,6.9,823,115,'2013-02-07','en','/2CbJ3HTb6SFbMeguYH52UQSHOwY.jpg',3.503234882328474,3,'2026-09-10',2,NULL,NULL),(113406,'Should\'ve Been Romeo','Should\'ve Been Romeo','A self-centered, middle-aged pitchman for a potato chip company loses his job and his livelihood just as his octogenarian grandfather is dropped on his doorstep unexpectedly by his mother on her way to a singles cruise.','Even Shakespeare didn\'t see this one coming.',0,0,0.40703,0,0,0,'2012-04-28','en','/yMwD0qEj3p87iG6wTnTniKgCfWB.jpg',1.8347121219376223,3,'2026-09-10',2,NULL,NULL),(113464,'Inchon','Inchon','A noisy and absurd re-telling of the great 1950 invasion of Inchon during the Korean War which was masterminded by General Douglas MacArthur.','LOVE. DESTINY. HEROES. War Changes Everything.',46000000,5200000,0.146783,6.5,2,140,'1981-05-04','en','/s0yJZQlZ6g7e3lTjSaUKWltYByA.jpg',2.072996510753892,3,'2026-09-10',2,NULL,NULL),(113947,'亲密治疗','The Sessions','马克·欧布莱恩（约翰·浩克斯 John Hawkes 饰）曾在幼年时期患上过小儿麻痹症。疾病的后遗症不仅让他再也没有站起来过，并且还让他饱受呼吸困难的折磨。虽然已过而立之年的他早已成为一名成功的诗人兼记者，但作为一个男人，却从未尝试过性的滋味。在向牧师朋友多次寻求指引 后，他毅然决定通过雇佣专业性从业者来帮助自己完成这个愿望。于是谢尔（海伦·亨特 Helen Hunt 饰）出现在了马克的生活里。然而对于马克这样特殊的情况，谢尔一开始也觉得无所适从。但是渐渐地，两人不仅从医患关系变为朋友，谢尔同时也给予了马克追求幸福和爱的勇气，让马克迈出了追寻爱的第一步。\r 　　本片根据真人真事改编。片中谢尔的扮演者海伦·亨特获得第85届奥斯卡最佳女配角等多项电影节提名。','The festival hit of the year!',1000000,9138338,9.115486,6.6,179,98,'2012-05-02','en','/nM7mgndH0UHqa3Lu1yQ89elUiWp.jpg',3.0110831340693567,3,'2026-09-10',2,NULL,NULL),(114065,'Down & Out With The Dolls','Down & Out With The Dolls','The raunchy, spunky tale of the rise and fall of an all-girl rock band from Portland, Oregon.','Ain\'t Rock \'N\' Roll a bitch.',0,0,0.002386,0,0,88,'2003-03-20','en',NULL,1.8337878354146249,3,'2026-09-10',2,NULL,NULL),(114150,'完美音调','Pitch Perfect','巴顿大学新人贝卡（安娜·肯德里克 Anna Kendrick 饰），意外加入学校的阿卡贝拉女子美声合唱团，该社团集结了又乖又坏又怪的各样女性成员，唯一共通点就是能清唱出犹如天籁的美声。社团成员包括：自认歌声最好，自信过人的“胖艾美”（蕾蓓尔·威尔森 Rebel Wilson 饰）、常常出言不逊又固执墨守成规，但其实焦虑不已的欧柏莉（安娜·坎普 Anna Camp 饰）、团员精神支柱克萝伊（布兰特妮·斯诺 Brittany Snow 饰）、性事无度的撩人歌姬史黛西（亚历克西斯·克纳普 Alexis Knapp 饰）、歌声动人的男人婆辛西亚萝丝（伊斯特·迪恩 Ester Dean 饰）、声音小如蚊子但即兴饶舌却令大家惊艳不已的莉莉（哈娜·梅·李 Hana Mae Lee 饰）。  　　与校园格格不入的贝卡，如何以她惊人的才华改变阿卡贝拉的传统表演方式？又如何率领这群女生与竞争激烈的全国美声团体一较高下？','Get pitch slapped.',17000000,115350426,32.746486,7.3,2247,112,'2012-09-28','en','/gsFoJk9g8W3zgaipRrrURk7LbiF.jpg',3.8534901094650857,3,'2026-09-10',2,NULL,NULL),(114635,'佣工','The Helpers','Seven friends from Sacramento, California head out on a documented road trip to Las Vegas. Their trip takes a very unexpected turn for the worse when their back tires mysteriously blow out. A couple miles down the road, they find a little gas station Diner/Motel, run by the most friendly, polite and \"helpful\" people. It appears that their problems are solved, but boy are they wrong! When convinced by \"The Helpers\" to stay overnight, the friends all wake up in their rooms to a new kind of gruesome and bloody terror!','Can we help you?',4000000,0,1.390659,4.1,8,78,'2012-10-27','en','/5YEzcIGM4TFSdG9fllCLx4ZMDK5.jpg',2.3075211622355987,3,'2026-09-10',2,NULL,NULL),(115210,'针','Stitches','小男孩汤姆（瑞恩·博克 Ryan Burke 饰）过生日，小伙伴们齐来祝贺，妈妈还特意请来一个蹩脚的小丑演员理查德·格林多（罗斯·诺贝尔 Ross Noble 饰）为大家表演。但是这个绰号“针（Stitches）”的小丑表演太糟糕了，接连遭到小伙伴们的嘲弄和笑话，更因孩子们的恶作剧惨死现场。6年后，至今依旧为当年的噩梦所困扰的汤姆（汤米·奈特 Tommy Knight 饰）迎来新的生日。派对当天，新朋旧友齐齐到来，当然小丑理查德也不会缺席。\r 　　传说一个小丑没完成表演就死去的话，他的灵魂永远也得不到安息。夜幕降临，汤姆再次经历了一个充满血浆和死亡的生日……','You\'ll die laughing...',100000,95000,7.447714,5.5,92,86,'2012-05-19','en','/s7epDHtoh0oychM8HXKlyW49Mg5.jpg',2.8144272332878058,3,'2026-09-10',2,NULL,NULL),(115872,'泰坦尼克号上的女佣','La femme de chambre du Titanic','故事开始于1912年，贺迪（奥利维·马丁内兹Olivier Martinez 饰）是一名普通的工厂工人，幸运的他在一次比赛中获得了登上铁达尼号的船票。贺迪将妻子留在家中，独自一人登上了游轮。在船上，贺迪遇见了无处可去的女佣马希（埃塔娜·桑切斯-吉永 Aitana Sánchez-Gijón 饰），贺迪好心的收留了她和自己住在同一间船舱中。  　　马希有着非常美丽的样貌，深深的吸引着贺迪的注意，然而第二天天刚刚亮，这个神秘的女人便失去了踪迹。下船后的贺迪对马希念念不忘，与此同时，他开始察觉到了妻子在自己离家的这段日子里对自己的不忠。在小酒馆中，贺迪添油加醋的诉说着自己和马希的故事。',NULL,0,0,1.031142,5.3,3,100,'1997-10-10','en','/mMPED3zn786jkID7TWtLPt3WMyR.jpg',2.1361678260028456,3,'2026-09-10',2,NULL,NULL),(116149,'帕丁顿熊','Paddington','神秘的秘鲁，生活着一种十分稀有的果酱熊，他们拥有非常高的智商和语言能力。当年果酱熊夫妇帕斯图佐和露西曾与来自伦敦的探险家结下深厚的友谊，并且学到了压制果酱的技巧。时至今日，一场灾难摧毁了果酱熊安宁快乐的生活，露西阿姨将淘气的侄子送上开往伦敦的邮轮，嘱咐他在那个友好的国度展开新的生活。万里漂泊而来的小熊懵懵懂懂来到帕丁顿火车站，可是当代人的冷漠却让他倍感失落。幸运的是小熊遇到了布朗一家，并且得到了一个好听的名字——帕丁顿（本·卫肖 Ben Whishaw 配音）。善良的女主人玛丽（莎莉·霍金斯 Sally Hawkins 饰）殷切要帮助帕丁顿找到可以栖身的地方，而男主人亨利（休·博内威利 Hugh Bonneville 饰）则时刻想把这个突如其来的麻烦赶走。在此过程中，搞怪不断的帕丁顿和布朗一家关系逐渐融洽，而自然历史博物馆的标本师米莉森特（妮可·基德曼 Nicole Kidman 饰）则怀着邪恶的目的悄然向帕丁顿接近……','The Adventure Begins',55000000,259207227,39.882276,7,883,95,'2014-11-27','en','/1v1AZTI4QM2c6PYcm446RXDkZQu.jpg',3.543984189361573,3,'2026-09-10',2,NULL,NULL),(116584,'Valley of the Heart\'s Delight','Valley of the Heart\'s Delight','When a fatal kidnapping ignites a firestorm of suspicion and rage in idyllic 1933 San Jose, California, a hard-nosed young reporter takes on the powers-that-be to prevent the lynching of two men he believes are innocent.','The roar of the mob drowned out the truth.',0,0,0.142255,7,1,100,'2006-04-24','en','/WTohWlSGwFNDfjJJtyPMraH3qo.jpg',1.9849872880156159,3,'2026-09-10',2,NULL,NULL),(116613,'The Sweeney','The Sweeney','Based on the \'70s UK TV show, The Sweeney is an action-packed British police thriller from the director of Football Factory. Jack Regan (Ray Winstone), a hardened cop who doesn’t play by the rules, is confronted with a criminal from his past. With sidekick George Carter (Ben Drew aka Plan B) they are put on the case of a jewellery store heist that ends in a killing. But is that killing really an execution in disguise? With pressure from his boss and the fact that Regan is having an affair with that boss’s wife, it’s not going to be easy for him to stay out of trouble.','Act like a criminal to catch a criminal.',3730500,6294161,6.938854,5.7,109,112,'2012-09-11','en','/nwGo7AoYXG4C03wbyfdeYvcVbnV.jpg',2.8542169114299236,3,'2026-09-10',2,NULL,NULL),(116711,'森林战士','Epic','改编自美国作家威廉·乔西的儿童文学《树叶人和勇敢好虫子》，刚刚失去母亲的少女玛丽·凯瑟琳“M.K”乘坐出租车来到一座几乎与世隔绝的大森林。这里生活着他的父亲，一个坚信森林里生活着矮人族的科学家，为了找到这些小生灵，他不惜牺牲家庭和婚姻。玛丽到达的那天刚好是夏至和满月，一个百年一次的特殊日子。并不相信父亲说法的玛丽意外卷入了两个矮人族的存亡纷争之中……','Discover a world beyond your imagination',100000000,268426634,36.711378,6.4,1121,102,'2013-05-15','en','/oo4arvvy2ycXksermSoFXk5kWGt.jpg',3.494894130247663,3,'2026-09-10',2,NULL,NULL),(116741,'实习大叔','The Internship','本片剧本由主演之一的文斯·沃恩执笔：随着互联网时代来临，两个年已四旬的老友忽然下岗。为了重新整顿人生方向，两人一同面试加入了大名鼎鼎的IT公司“谷歌”，从实习生做起。他们必须在这个位置上和20岁出头的狡黠的年轻人竞争，目标就是：转正！\r 　　对于那些谷歌的粉丝来说，本片当然是一窥IT圣地的好机会。而对于热爱烂仔帮喜剧的影迷而言，当谷歌的IT男、技术宅们遇上一对做销售的大龄贱男、老江湖，这样基情四射的故事怎可错过围观？这支预告片很聪明的未过多透露剧情，而是充分展示了两位男主角之间的化学反应。《伴娘》之后喜剧路线走得顺风顺水的美女萝丝·拜恩也在预告中惊喜亮相，此外，威尔·法瑞尔、约翰·古德曼等一众喜剧常客也将助阵。','Hiring them was a brilliant mistake.',58000000,44000000,1.551497,6.1,1658,119,'2013-06-07','en','/mQ0w6A0Ig0xWWOBWcDwcwz9l6KY.jpg',3.4446216470083604,3,'2026-09-10',2,NULL,NULL),(116745,'白日梦想家','The Secret Life of Walter Mitty','沃尔特在《生活》杂志的底片资产部工作多年，性格内向的他习惯把自己藏在平凡的生活中，并时常陷入白日梦，幻想自己成为无所不能的英雄。他甚至始终没有勇气向心仪的同事谢莉尔表达心意。直到公司被并购，杂志即将推出最后一期，摄影师尚恩寄来的底片中，用作封面的第25号底片却神秘失踪。为了找到这张至关重要的照片，沃尔特不得不走出熟悉的生活，踏上一段真正的冒险旅程，而那些曾经只存在于幻想中的经历，也开始一步步成为现实……','Stop Dreaming, Start Living',90000000,188133322,43.348022,7,3144,114,'2013-12-18','en','/iAo1hlzsPV9XpYcLQp6Ud065tGO.jpg',3.8977484011992516,3,'2026-09-10',2,NULL,NULL),(116977,'食物大战','Foodfight!','当超市里一个人都没有的时候，整个超市就活过来了，货架成为一个个社区，通道成为一条条大街，中国食品货架就是唐人街、意大利食品货架则变成了威尼斯……然而在热闹之余，一场好食物与坏食物之间的大战也一触即发。','When good food... goes bad!',65000000,73706,5.258726,2.3,28,87,'2012-06-15','en','/to9ggXVyhNTCICHcHMCtFtANd8P.jpg',2.5346551410925797,3,'2026-09-10',2,NULL,NULL),(117251,'惊天危机','White House Down','年轻的凯尔从阿富汗前线退伍后在国会安保部门工作，他的终极梦想是保护美国总统索亚。凯尔与离婚的妻子育有一个正在上小学的女儿艾米莉，她因为父亲入伍的经历变成了一个政治迷，尤其对索亚总统和白宫极其崇拜。凯尔为了让女儿高兴承诺带她参加白宫内部一日游，顺便在当天去应征由卡罗领导的特勤部门的工作。可是就在同一天，一伙身份不明的武装分子乔装潜入白宫并对索亚总统进行搜捕，一场腥风血雨蓄势待发。正在陪女儿参观的凯尔能否临危不惧解救总统？凯尔是否能同时保护女儿？而这场动机不明的暴力背后是否掩盖着不为人知的肮脏秘密？','It will start like any other day.',150000000,205366737,39.004588,6.4,1891,131,'2013-06-27','en','/1RYAbgbgywikVX0b0W2lGVvsee7.jpg',3.6235786949355724,3,'2026-09-10',2,NULL,NULL),(117263,'奥林匹斯的陷落','Olympus Has Fallen','特情局秘密代号为“奥林匹斯”的白宫正处在危机之中，一伙恐怖分子先用重型的飞机和机枪袭击了这里，并派入了一支敢死队进入，彻底占领了美国总统府并劫持了美国总统，并以此为要挟，妄图控制世界。此时坐在文员办公室的迈克·班宁（杰拉德·巴特勒饰）从刚刚的突袭中幸存了下来，并成为了美国最后的一丝希望。班宁原先是一个特种兵，负责美国总统和第一夫人的安全。但却因为一次发生在圣诞节的突发事故中，因为自己的失误造成第一夫人的死亡，也因此被调到了文职。而此刻面对遭受重创的白宫，班宁只能依靠自己，在危机密布的白宫中只身力挽狂澜，拯救被劫持的总统和濒于沦陷的国家……','When our flag falls our nation will rise.',70000000,161025640,59.428223,6.2,2981,120,'2013-03-20','en','/u3GTFGwesNBNd0t1hiLaEk1iqZU.jpg',3.727851154966089,3,'2026-09-10',2,NULL,NULL),(117942,'小妞死翘翘','Girls Gone Dead','在大学第一次春假期间，六名前高中啦啦队成员被一名手持中世纪战锤和战斧的杀手跟踪。',NULL,500000,0,1.600171,3.5,14,104,'2012-03-28','en','/h4fkp6KuY55vocpkInbFeXOSrgT.jpg',2.4107033460173053,3,'2026-09-10',2,NULL,NULL),(118340,'银河护卫队','Guardians of the Galaxy','幼年时被带离地球的彼得·奎尔在掠夺者勇度的抚养下长大，如今以“星爵”之名在宇宙中四处冒险。一次行动中，他偷走了一颗来历不明的神秘球体，却因此成为强大敌人罗南追捕的目标。围绕这件宝物，彼得先后与卡魔拉、赏金猎人火箭浣熊和格鲁特产生冲突，又结识了满怀复仇之心的毁灭者德拉克斯。几个原本各怀目的、互不信任的边缘人物不得不暂时联手，而随着他们逐渐发现球体背后隐藏的巨大力量，这场原本只为自保的逃亡也开始关系到整个银河系的安危……','All heroes start somewhere.',170000000,773328629,481.098624,7.9,9742,121,'2014-07-30','en','/r7vmZjiyZw9rpJMQJdXpjgiCOk9.jpg',5.425965491127335,3,'2026-09-10',2,NULL,NULL),(118452,'First Love, Last Rites','First Love, Last Rites','Joey and Sissel are two misfits spending most of their time together talking or having sex. Gradually and slowly their relationships are becoming boring for them.',NULL,300000,40542,0.374291,3,1,94,'1998-08-07','en','/w4yN57gmVvLKdHOdUZ5GDQk6gW9.jpg',1.9838721845886431,3,'2026-09-10',2,NULL,NULL),(118612,'车祸之后','After','小镇里的两辆巴士相撞之后，醒来的幸存者惊悚地发现他们是这个镇子上仅剩的居民，究竟发生了什么，是他们穿越了还是小镇根本不是他们印象中的模样，太多的疑惑等待解答，但是时间却不待人。',NULL,0,0,4.596157,5.6,63,90,'2012-08-27','en','/kT2GoRg8aqVPdEvYofX1RlIKJXR.jpg',2.735129405267893,3,'2026-09-10',2,NULL,NULL),(118957,'大海啸之鲨口逃生','Bait','宁静的澳洲海滩上，宿醉的救生员乔许（泽维尔·塞缪尔 Xavier Samuel 饰）让女友蒂娜（沙妮·文森 Sharni Vinson 饰）的哥哥罗利替他去海上例行检查防鲨网的设置，结果罗利遭到了鲨鱼的袭击，罗利的死对乔许和蒂娜造成了很大的心理阴影，乔许为此对女友充满了歉疚，乔许为此放弃了救生员的工作去超市做了理货员，蒂娜也远赴中国学习舞蹈。一年后，当蒂娜重新返回澳洲后，和乔许在超市不期而遇，与此同时，超市里风起云涌，偷窃、抢劫……就在这起突发事件白炽化的时候，地动天摇，海啸铺天盖地而来，超市立刻沦为孤岛，大鲨鱼随之而来，一场人鲨大战瞬间展开……','Cleanup on aisle 7.',30000000,0,9.780588,5.3,191,93,'2012-09-05','en','/pjxHHFYwymvWy1c5kxCvXdKJzNE.jpg',2.9471310885843103,3,'2026-09-10',2,NULL,NULL),(119283,'帕克','Parker','帕克 是个极其有原则的职业劫匪，他的信条是不劫无财之人、不伤无罪之人。然而一次作案时，他却被同伙出卖，几乎送命。死里逃生后，帕克决定复仇，让他们付出应有的代价。他打听到以前的同伙正准备做一票前所未有的大劫案。于是，他物色了一 个不太符合他标准的新搭档—— 美艳、精明充满野心的莱思莉，他们将有备而来，准备洗劫一空后全身而退……','To get away clean, you have to play dirty.',35000000,46216641,28.670477,5.7,1455,118,'2013-01-23','en','/mShQupxHEZQ6ujqVuZ7e2bKBcjr.jpg',3.3983656570318965,3,'2026-09-10',2,NULL,NULL),(119450,'猩球崛起2：黎明之战','Dawn of the Planet of the Apes','十年前，人类为自己的愚蠢付出惨痛代价，凶险致命的猿流感病毒蔓延全球，世界毁灭殆尽。而在毗邻旧金山的原始丛林，凯撒（安迪·瑟金斯 Andy Serkis 饰）带领猩猩伙伴们建立起无忧无虑的王国，直到某一天，猩猩的家园的宁静再度被人类打破。在旧城苟延残喘的人类面临能源危机，他们试图利用森林腹地大坝的发电站提供能源。青年科学家马尔科姆（杰森·克拉科 Jason Clarke 饰）试图说服聚集地负责人德里弗斯（加里·奥德曼 Gary Oldman 饰），希望通过和平手段取得猩猩部落的信任和同意。然而凯撒的好盟友科巴（托比·凯贝尔 Toby Kebbell 饰）却无法摒除对人类的憎恨，他尝试着挑战者凯撒的权威。人类和猩猩，双方小心翼翼试探，而战争在所难免……','One last chance for peace.',170000000,710644566,243.791743,7.3,4410,130,'2014-06-26','en','/mSmAc9G25fhOHH45SLEeagR0qi7.jpg',4.518638985177896,3,'2026-09-10',2,NULL,NULL),(119458,'商战','Supercapitalist','一名性格特立独行的纽约对冲基金交易员Conner Lee（丁温庆 饰）受到美国及亚洲两般金融恶势力的牵引，到香港展开了一场惊天动地的家族企业并购商战。为求达成这项市值数十亿元的世纪商业买卖，Conner不择手段，并甘愿以自己的生命以及一间公司的未来作赌注，决意在香港这个复杂的弹丸之地以身犯险。','Money for Life',0,0,0.174311,3.5,2,103,'2012-08-10','en','/qQrVjSPIarrSnpY9O1eZH01VbUh.jpg',2.0705950895458054,3,'2026-09-10',2,NULL,NULL),(119657,'El Rey de Najayo','El Rey de Najayo','The dramatic story of Julian, a Dominican drug lord who despite his confinement in prison, was still able to maintain Dominican society in a state of suspense, for over 13 years. At the early age of 12, he witnessed the death of his father at the hands of local military authorities, during a well-meant attempt to hand-over a package of drugs he had incidentally found at sea while fishing. As a result of this experience, Julian develops a thirst for revenge that leads him to kill all those involved in his father\'s death. In the process he becomes a major drug lord and a very powerful headman within Dominican society.',NULL,500,0,0.080105,0,0,101,'2012-03-01','en','/d9QZi1QppknaybAabCYcRelrCh2.jpg',1.8339653609043909,3,'2026-09-10',2,NULL,NULL),(120467,'布达佩斯大饭店','The Grand Budapest Hotel','The Grand Budapest Hotel tells of a legendary concierge at a famous European hotel between the wars and his friendship with a young employee who becomes his trusted protégé. The story involves the theft and recovery of a priceless Renaissance painting, the battle for an enormous family fortune and the slow and then sudden upheavals that transformed Europe during the first half of the 20th century.','A perfect holiday without leaving home.',30000000,174600318,74.417456,8,4519,99,'2014-02-26','en','/eWdyYQreja6JGCzqHWXpWHDrrPo.jpg',4.318952934037252,3,'2026-09-10',2,NULL,NULL),(121676,'无法逃避','Inescapable','亚历山大·西迪格、约书亚·杰克逊和玛丽莎·托梅主演了这部紧张的惊悚片，讲述了一个男人的女儿在大马士革失踪，迫使他回到三十多年前离开的国家。','You can never escape your past',0,0,6.783053,5.2,13,93,'2012-09-14','en','/gCeZGBFcxjyGdvFncJqCGffBCpw.jpg',2.4175398193655724,3,'2026-09-10',2,NULL,NULL),(121826,'四重唱','Quartet','影片讲述了一家专门为退休歌剧演员服务的养老院住着Wilf （比利·康纳利）、Reggie（汤姆·康特奈）和他们的大学同学Cissy（宝琳·柯林斯），每年威尔第诞辰那天他们都会举行音乐会募捐，用于养老院的维持。然而有一天，养老院来了位不速之客——Reggie的前妻、歌剧界大名鼎鼎的女歌唱家Jean Horton（玛姬·史密斯），由于经济问题她现在不得不搬进养老院居住。她的到来给原本和谐的养老院带来了不安定的因子，原本的三重唱变成了四重唱，而且经常由于Jean Horton的原因而无法正常排练……四个英国最好的歌剧演员生活在同一屋檐下，却并不能保证演出继续下去。','Four Friends Looking For A Little Harmony',11000000,59520298,7.722021,6.3,139,98,'2012-09-08','en','/lDg2DfB5MuEoUeRFQqzBFVoWGep.jpg',2.9334935208616373,3,'2026-09-10',2,NULL,NULL),(121986,'弗兰西丝·哈','Frances Ha','索菲（米凯·萨姆纳 饰）是弗朗西斯（格蕾塔·葛韦格 饰）最要好的朋友兼室友，两人整日里出双入对，关系俨然比情侣要亲密的多。然而某日，索菲忽然告诉弗朗西斯，自己要搬到城中和另一个女孩同住。虽然索菲万般保证两人还是朋友，但弗朗西斯的内心依旧十分失落。\r 无法独自负担房租的弗朗西斯只得另觅住处，索菲的朋友列夫（亚当·德赖弗 饰）在关键时刻助了弗朗西斯一臂之力，就这样，弗朗西斯开始了和列夫以及列夫的室友本吉（迈克尔·泽根 饰）一起的同居生活，并承诺会在圣诞节的舞蹈演出后付齐房租。糟糕的是，没过多久，弗朗西斯便丢掉了工作。一时之间，她不知道自己究竟该何去何从。',NULL,0,4069826,15.492257,7.2,345,86,'2013-05-17','en','/qlsqosFBLXHth4fZqSz21yJCZ5Q.jpg',3.243553980665733,3,'2026-09-10',2,NULL,NULL),(122081,'春假','Spring Breakers','Brit、Candy、Cotty和Faith从小学就是最好的朋友。她们同住在一个无聊的大学宿舍都渴望冒险。她们一直盼望的就是有足够的钱在春假时去寻找真正的乐趣。一个偶然机会她们遇到一个说唱歌手“alien”，他承诺帮助实现女孩们的愿望。在新朋友的鼓励下,女孩们渐渐开始一个她们永生难忘的不可思议的春假。','A little sun can bring out your dark side.',5000000,31724284,62.554173,5,1551,94,'2013-01-24','en','/A08omT5vFz6bhv5WFgtN3QVIplN.jpg',3.3449976834343422,3,'2026-09-10',2,NULL,NULL),(122906,'时空恋旅人','About Time','The night after another unsatisfactory New Year party, Tim\'s father tells his son that the men in his family have always had the ability to travel through time. Tim can\'t change history, but he can change what happens and has happened in his own life – so he decides to make his world a better place... by getting a girlfriend. Sadly, that turns out not to be as easy as he thinks.','What if every moment in life came with a second chance?',0,87100449,74.817641,7.8,2067,123,'2013-08-16','en','/ls6zswrOZVhCXQBh96DlbnLBajM.jpg',4.036763815864807,3,'2026-09-10',2,NULL,NULL),(122917,'霍比特人3：五军之战','The Hobbit: The Battle of the Five Armies','在上一部结尾处，比尔博一行人对巨龙史矛革声称将要重新收复自己的家园，但却不知不觉地被一股强大致命的力量推向世界黑暗的更深处，而巨龙史矛革的重现将自身无尽的愤怒对准了长湖镇的男女老少。索林迷恋自己收回的财富，他牺牲了队友的友谊，却把霍比特人推向了绝望与危险的境地，殊不知有更大的危险在前方等待。劲敌索伦派出了第四军团的半兽人在孤山秘密埋伏袭击，但只有灰袍巫师甘道夫洞悉了这一危险。面对不断高涨的黑暗势力的冲突，矮人、精灵以及人类必须决定是否联合，否则均将会被毁灭。比尔博在五军联合的史诗战中为自己的生命而决斗，而迷失的索林也将面对财富的欲望完成自我救赎。','Witness the defining chapter of the Middle-Earth saga',250000000,956019788,120.965743,7.1,4760,144,'2014-12-10','en','/xT98tLqatZPQApyRmlPL12LtiWp.jpg',4.205844331616001,3,'2026-09-10',2,NULL,NULL),(123553,'The Mortal Instruments: City of Bones','The Mortal Instruments: City of Bones','In New York City, Clary Fray, a seemingly ordinary teenager, learns that she is descended from a line of Shadowhunters — half-angel warriors who protect humanity from evil forces. After her mother disappears, Clary joins forces with a group of Shadowhunters and enters Downworld, an alternate realm filled with demons, vampires, and a host of other creatures. Clary and her companions must find and protect an ancient cup that holds the key to her mother\'s future.','You have been chosen',60000000,90565421,45.514031,6.2,1602,130,'2013-08-21','en','/uFu4oh20DIHS1PL4CNgJaJ4o5Eo.jpg',3.558234837306004,3,'2026-09-10',2,NULL,NULL),(123678,'杀戮演绎','The Act of Killing','一部纪录片，其中印尼前处决队成员以各类电影风格重演他们现实中的大规模杀戮。','A story of killers who win, and the society they build.',1000000,444575,8.887411,7.5,210,115,'2012-08-31','id','/sp5B7Tz5ttsgOLnIlCP5uEhtesI.jpg',3.109364521610185,3,'2026-09-10',2,NULL,NULL),(124459,'超级魔术师','The Incredible Burt Wonderstone','魔术界的超级明星，明星界的超级魔术师波特·汪德斯通和安东·马福顿已经统治了拉斯维加斯的魔术界好多年。他们的童年就是被魔术所拯救的，所以，魔术对于他们来说，是生活的唯一重心和重点。也是他们的经济来源。  　　可是，这一对伟大魔术师的友谊目前正在经受着考验，在表演一个危险魔术的时候，安东受了伤，从此便和波特的关系陷入了僵局。虽然在表面上，大家还是一团和气，但是在私下里，他们已经不再是朋友了。不久之后，安东离开了拉斯维加斯，远赴陌生的地方表演魔术。  　　独木难支的波特开始了一个人的表演生涯，雪上加霜的是，这个时节拉斯维加斯的街头多了一个街头魔术师史蒂夫·盖瑞。这个剑走偏锋的魔术师的魔术很快就吸引走了大量人的目光。要找回自己的江湖地位，要重新得到辉煌，波特只有找回自己的老搭档，并再一次学会几个新的把戏，找回他对魔术第一次心跳的回忆。只有这样，他才能搞定观众，并且在魔术的战场上击败似乎无懈可击的盖瑞。','Abracatastic!',30000000,27437881,26.9385,5.3,724,100,'2013-03-14','en','/4rjVi3CKNEp29S42oPFUWK2ONM6.jpg',3.2039648381015255,3,'2026-09-10',2,NULL,NULL),(124606,'Bang','Bang','A young woman in L.A. is having a bad day: she\'s evicted, an audition ends with a producer furious she won\'t trade sex for the part, and a policeman nabs her for something she didn\'t do, demanding fellatio to release her. She snaps, grabs his gun, takes his uniform, and leaves him cuffed to a tree where he\'s soon having a defenseless chat with a homeless man. She takes off on the cop\'s motorcycle and, for an afternoon, experiences a cop\'s life. She talks a young man out of suicide and then is plunged into violence after a friendly encounter with two \"vatos.\" She is torn between self-protection and others\' expectations. Is there any resolution for her torrent of feelings?','Sometimes you\'ve got to break the rules',0,0,0.918116,6,1,98,'1995-09-09','en','/pDvf5rsulgcJtZx6voFEO05aC3p.jpg',1.9863482273878315,3,'2026-09-10',2,NULL,NULL),(125052,'飓风街道','Hurricane Streets','马库斯和哈罗德、切普、贾斯汀等几个十五六岁的男孩终日混迹在城市的各个街区，以偷东西然后在学校附近低价兜售为生，他们还拥有一个隐蔽的俱乐部——一间废弃的地下室。','Know life. No limits.',0,0,0.36447,4.8,4,86,'1997-01-21','en','/kI8WAtPfjiPygfdKcwYJUkMZyh4.jpg',2.1819493567877517,3,'2026-09-10',2,NULL,NULL),(125123,'在巨人中间','Among Giants','A manager hires Ray, off the books, to paint all the power towers in a 15-mile stretch of high-tension wires outside Sheffield. Ray\'s crew of men are friends, especially Ray with Steve, a young Romeo. Into the mix comes Gerry, an Australian with a spirit of adventure and mountain climbing skills. She wants a job, and against the others\' advice, who don\'t want a woman on the job, Ray hires her. Then she and Ray fall in love. He asks her to marry him, gives her a ring. Steve\'s jealous; Ray\'s ex-wife complains that he spends on Gerry, not his own kids, and she predicts that Gerry won\'t stay around. Plus, there\'s pressure to finish the job fast. Economics, romance, and wanderlust spark the end.','a love story from the writer of \"The Full Monty\".',0,0,0.541652,4.5,2,93,'1998-06-24','en','/u90H3K6XeQEzECkarfysZ2p5IZE.jpg',2.072255602201921,3,'2026-09-10',2,NULL,NULL),(125263,'Broken Vessels','Broken Vessels','A young Pennsylvania man moves to Los Angeles to begin work for an ambulance service. There he is teamed with a supremely confident vet who seemingly has gone through a large number of partners. Initially the novice is awed by the more experienced man\'s capabilities to deal with the high pressure situations they encounter. However, gradually he discovers that all is not as it seems. While the vet is ice on the surface, he actually gets through the ordeals by heavy drug use and avoids commitments. Soon the younger man finds himself pulled into the same world and has to decide what direction he wants to take.','Over the edge and out of control.',0,0,0.069277,6,2,90,'1998-04-18','en','/iMvLeE872FGGV4XrAfhKRCULtXk.jpg',2.072408755035187,3,'2026-09-10',2,NULL,NULL),(125490,'病毒抗体','Antiviral','故事讲述一名诊所职员Syd（卡赖伯·兰德里·琼斯饰）倒卖名人的活体病毒卖给粉丝，并通过自己的身体走私病毒。直到有一次他感染了令一位当红明星致死的病毒，于是他成为收藏家和疯狂粉丝的目标，同时还要查出病毒真相。','What If You Could Feel Like They Do ...',2400000,0,11.753553,5.7,112,110,'2012-09-19','en','/rIn0ruFDU8psnCGkPgA9fbKJJUy.jpg',2.87067316868888,3,'2026-09-10',2,NULL,NULL),(125537,'Smiling Fish & Goat On Fire','Smiling Fish & Goat On Fire','Two brothers share a house in LA\'s Fairfax district: Tony\'s a feckless actor, Chris is an accountant. Both are in relationships on rocky ground. As these emotions swirl, Tony meets his US Postal Service letter carrier, a single mom named Kathy who\'s come to LA from Wyoming with her daughter, a budding actress. Chris meets Anna, an Italian beauty working in the States for a few months wrangling animals on movie sets. Chris also befriends Clive, an aging and crusty man whose longing for his recently-deceased wife is a portrait of true love. Can Clive\'s example help Chris sort out his love life, and can Tony grow up enough to see the possibilities with Kathy and her daughter?','two brothers, four women and the search for Magnetic Perfection',0,0,0.00734,7,1,90,'1999-09-16','en','/cGCNG3Md9t0Zvhksr27aqXa1AI9.jpg',1.9846791156066583,3,'2026-09-10',2,NULL,NULL),(126141,'巴黎墙上的猫','Chats perchés','2002年，一些猫开始在巴黎屋顶上出现。它们是些黄色的龇牙微笑的猫。跟随着它们的足迹，通过这些奇特壁画的眼睛，导演讲述了法国最近的历史――战争、选举、示威、政府丑闻等。',NULL,0,0,0.092562,7.7,3,59,'2004-12-05','en','/A85JH3Mxijik6PbQVttXXZZfeIo.jpg',2.1369770422957997,3,'2026-09-10',2,NULL,NULL),(126186,'纽约客@上海','纽约客@上海','上海，21世纪全球贸易中心。每天都有更多的外籍商人来到上海，渴望了解到中国做生意的方式。这些外国人中有我们的同事，老板，邻居，客户……\r 　　当雄心勃勃的纽约律师山姆（丹尼尔·海尼 Daniel Henney 饰）被意外的派到上海时，他立即陷入了法律泥潭，使他差点丢了工作。但随着一位聪明性感的助理（朱珠 饰），一个机灵的上海记者（耿乐 饰），一位漂亮的迁居专家（伊丽莎·库伯 Eliza Coupe 饰），以及一个人脉广泛的老前辈（比尔·帕克斯顿 Bill Paxton 饰）的帮助，山姆可能有机会保住工作，寻找到爱情，并且学着去欣赏他美好的故乡……','A New Yorker in Shanghai',0,0,0.857008,5.7,7,98,'2012-05-03','en',NULL,2.2861067637591432,3,'2026-09-10',2,NULL,NULL),(126319,'艾特熊和赛娜鼠','Ernest et Célestine','在白雪覆盖的鹅卵石街道深处，蜿蜒的地下隧道网络中，栖息着一个勤劳努力的小鼠文明，它们对生活在地面上的熊族心怀恐惧。与其他老鼠不同，赛娜鼠是一位艺术家和梦想家——当她险些成为熊族游吟诗人艾特熊的早餐时，两者却结下了一段奇妙的情谊。但很快，这段友谊便受到了各自惧怕熊族与嗜食鼠类的族群审判。','Bonnie and Clyde, Sid and Nancy...',12516654,8109160,11.103202,7.6,142,78,'2012-12-12','fr','/xhtv7GkQZ01pdyxDWZhOBFDFWoU.jpg',3.00960721270587,3,'2026-09-10',2,NULL,NULL),(126509,'2016：奥巴马的美利坚','2016: Obama\'s America','它检查的问题，一部纪录片“如果奥巴马赢得连任，在那里我们会在2016年？”','Love Him, Hate Him, You Don\'t Know Him',2500000,33400000,0.973582,4.6,19,87,'2012-07-13','en','/9Ht3rh0GVgh0rGqW99wCXWE4DP1.jpg',2.474985893624888,3,'2026-09-10',2,NULL,NULL),(127493,'劫案迷云','Stolen','窃盗集团首领威尔(尼古拉斯·凯奇饰)在行动中被同伙出卖，威尔在警方赶到前，将抢来的巨款丢入铁桶烧毁，但仍入狱八年。威尔出狱后原本想金盆洗手，并与女儿艾莉森修复关系，却同时被FBI以及过去同伙找上，逼迫他交出当年的1000万美金。\r 同伙文森掳走爱丽森，要威尔用巨款来赎回女儿，他必须在24小时内凭着一个5K20编号找到被藏在计程车后车厢的女儿，当时却适逢纽奥良嘉年华会，街道上挤满了成千上万的人潮车辆，时间迫在眉梢，面对FBI的追捕以及文森的双重威胁下，威尔决定铤而走险，找回昔日拍档蕾莉(玛琳·阿克曼饰)，再大干一票。','Never steal from the world\'s greatest thief.',35000000,2106557,16.830184,5.1,344,96,'2012-05-17','en','/a6MPF25FYGm50ugKhdxzs6zGW2E.jpg',3.043692098452116,3,'2026-09-10',2,NULL,NULL),(127560,'铁路劳工','The Railway Man','二战期间英国士兵洛马克斯被日军俘虏，被迫在在缅甸-暹罗（泰国旧称）做铁路苦工，身心受尽难以想象的摧残，他一生都难以逃出阴影。三十年后，洛马克斯获悉曾经折磨过他的一个日本兵还活在人世，他决定去见见这个人，不是为了报复寻仇，而是想要与过去和解。','Revenge is never a straight line.',18000000,22309223,13.916583,6.7,273,116,'2013-12-26','en','/3q15eHUxbVgLAZEZcKB8ryaR7AM.jpg',3.1324845762024993,3,'2026-09-10',2,NULL,NULL),(127585,'X战警：逆转未来','X-Men: Days of Future Past','The ultimate X-Men ensemble fights a war for the survival of the species across two time periods as they join forces with their younger selves in an epic battle that must change the past – to save our future.','To save the future, they must alter the past',250000000,747862775,118.078691,7.5,6032,131,'2014-05-15','en','/tYfijzolzgoMOtegh1Y7j2Enorg.jpg',4.365134549933771,3,'2026-09-10',2,NULL,NULL),(127867,'黄铜茶壶','The Brass Teapot','约翰和爱丽丝这对小夫妻生活在美国一个小镇上，在高中时代，貌美又有才的爱丽丝相当被看好，被评为“最有可能成功的人”，但事实上，当高中那些同学早已变身为成功人士，爱丽丝却还过着入不敷出的生活。而她的神经质丈夫约翰整天疑心重重，只关心账单该怎么支付。\r 　　有一次爱丽丝在路边的一家古玩店发现了一个黄铜茶壶，这个茶壶可不一般，它竟然有产生钞票的“特异功能”，但是必须要他们感觉到疼痛和痛苦时，茶壶的“特异功能”才能显灵。\r 　　有这把神奇的茶壶以后，爱丽丝和约翰再也不差钱了，但是他们得变着法子互相折磨，无论是精神上的还是肉体上的……渐渐的，他们发现这把茶壶已经把自己引上了不归路……','Everyone Has A Price. What\'s Yours?',0,0,10.639774,5.8,160,100,'2012-09-08','en','/6txTmb8OIimrQezgD8ERMmrrbnT.jpg',2.9446091194608996,3,'2026-09-10',2,NULL,NULL),(127918,'The Gatekeepers','The Gatekeepers','In an unprecedented and candid series of interviews, six former heads of the Shin Bet — Israel\'s intelligence and security agency — speak about their role in Israel\'s decades-long counterterrorism campaign, discussing their controversial methods and whether the ends ultimately justify the means. (TIFF)',NULL,0,0,2.828303,6.5,39,101,'2012-07-09','en',NULL,2.6471788378446504,3,'2026-09-10',2,NULL,NULL),(129139,'性愿清单','The To Do List','纯朴的布兰蒂（奥布瑞·普拉扎 Aubrey Plaza 饰）发现自己直到高中毕了业，对于男女之间的“互动”仍是毫无经验。在即将步入大学生活之际，为了不让自己输在起跑点上，她详细列出一张学习清单，决定来一场全面“性”成长……','She\'s going from straight A\'s to getting her first F.',1500000,3566225,15.017068,5.5,342,104,'2013-07-24','en','/vSVYCcvDJljrESZo1jJyXPVvwfk.jpg',3.077013341816291,3,'2026-09-10',2,NULL,NULL),(129670,'内布拉斯加','Nebraska','一位嗜酒的老父亲与关系疏远的儿子从蒙大拿前往内布拉斯加，只为领取一份声称价值百万美元的营销抽奖大奖。','Life\'s not about winning or losing. It\'s about how you get there in the end.',12000000,17654912,29.223881,7.4,636,115,'2013-09-21','en','/6Jlglxw8fRdynrKTphiH1gWgC1U.jpg',3.4826322663893285,3,'2026-09-10',2,NULL,NULL),(130150,'情动假日','Labor Day','故事发生在1987年的美国，阿黛尔（凯特·温丝莱特 Kate Winslet 饰）和亨利（加特林·格里菲斯 Gattlin Griffith 饰）是一对相依为命的母子，一次偶然中，两人在购物途中遇见了满身是血的流浪汉弗兰克（乔什·布洛林 Josh Brolin 饰），误打误撞之下，阿黛尔和亨利将弗兰克带回了家，弗兰克亦诚恳地坦白了他灰暗的过往。原来，弗兰克是一名逃犯，他因为发现深爱的儿子并非自己亲生而在愤怒之中失手杀死了女友曼迪（Maika Buckley 饰）。随着时间的推移，弗兰克和阿黛尔之间的关系越来越亲密，两人决定带着亨利远走高飞，然而，正当计划即将顺利实施之时，亨利却将这个秘密告诉了早熟的女孩莲诺（布丽吉德·弗莱明 Brighid Fleming 饰），这一举动为阿黛尔和弗兰克带来了灾难性的麻烦。',NULL,18000000,20275812,17.683563,6.7,299,111,'2013-12-27','en','/w0aWbWDtoCW89R5bQUxK6m87dg3.jpg',3.164018122378273,3,'2026-09-10',2,NULL,NULL),(131631,'饥饿游戏3：嘲笑鸟（上）','The Hunger Games: Mockingjay - Part 1','凯特尼斯·伊夫狄恩，燃烧的女孩，虽然她的家被毁了，可她却活了下来。盖尔也逃了出来，凯特尼斯的家人也安全了，皮塔被凯匹特抓走了。十三区并不真的存在，出现了反抗，出现了新的领导者，一个革命的序幕正在缓缓拉开。凯特尼斯从噩梦般的竞技场逃出来是已经设计好的，她是反抗运动的参与者，也是设计好的，而她对此并不知情。十三区从隐蔽处出来了，并计划推翻凯匹特的统治。似乎每个人都参与了这项精心策划的行动，而只有凯特尼斯并不知情。反抗运动将凯特尼斯卷入了漩涡，她被迫成为棋子，她被迫为许多人的使命负责，不得不肩负起改变帕纳姆国的未来的负责。为了做到这一切，她必须抛却愤怒和不信任，她必须要成为反抗者的嘲笑鸟――不管要付出多大的代价。','Fire burns brighter in the darkness',125000000,752100229,206.227151,6.6,5584,123,'2014-11-18','en','/4FAA18ZIja70d1Tu5hr5cj2q1sB.jpg',4.307702028810607,3,'2026-09-10',2,NULL,NULL),(131634,'饥饿游戏3：嘲笑鸟（下）','The Hunger Games: Mockingjay - Part 2','With the nation of Panem in a full scale war, Katniss confronts President Snow in the final showdown. Teamed with a group of her closest friends – including Gale, Finnick, and Peeta – Katniss goes off on a mission with the unit from District 13 as they risk their lives to stage an assassination attempt on President Snow who has become increasingly obsessed with destroying her. The mortal traps, enemies, and moral choices that await Katniss will challenge her more than any arena she faced in The Hunger Games.','The fire will burn forever.',160000000,653428261,127.284427,6.6,3984,137,'2015-11-18','en','/lImKHDfExAulp16grYm8zD5eONE.jpg',4.048355053555534,3,'2026-09-10',2,NULL,NULL),(132232,'妈妈','Mama','一对女孩维多利亚·迪桑（梅根·查彭提尔 饰）和莉莉·迪桑（伊莎贝尔·内利瑟 饰）的母亲被他们的父亲所杀，父亲也随即自杀并将两个女儿遗弃在树林里。五年后，她们被发现时状况极差，孤独、饥饿，她们对一切的肢体接触都会感到恐惧和抗拒，没人知道她们是如何在如此孤独的环境中存活的。叔叔卢卡斯（尼可拉·科斯特-瓦尔道 饰）和女友安娜贝尔（杰西卡·查斯坦 饰）收养了她们，原本平静的生活就此打破。黑暗中，总有一个如影随形的亡魂，而这个想要置他们于死地的鬼魂，两个女孩叫她：妈妈。','A Mother\'s Love is Forever',15000000,146497771,47.455148,6,1401,100,'2013-01-17','en','/kDd0oGVc2WiKKXnZsGgEzWeIkzC.jpg',3.493327099616843,3,'2026-09-10',2,NULL,NULL),(132316,'爱无止境','जब तक है जान','萨马尔•阿南德少校（沙鲁克•汗 Shahrukh Khan 饰）是个排雷防爆的专家，在军队中保持着自己的拆弹记录。他每天的工作穿梭于生死边缘，坦然面对生死的他却从不穿防护设备。意外救下了少女阿琪拉•拉耶（安努舒卡•莎玛 Anushka Sharma 饰），遗留的日记本里记忆的爱情故事让这个女孩对萨马尔深深着迷。利用探索频道实习生的身份，阿琪拉对萨马尔进行为期两周的故事记录，渐渐的，她深入到了萨马尔的故事中..',NULL,0,0,5.900535,7.3,66,176,'2012-11-13','hi',NULL,2.7898917571315174,3,'2026-09-10',2,NULL,NULL),(132344,'爱在午夜降临前','Before Midnight','作为“爱在”三部曲的终章，故事展现塞利娜与杰西相伴数年后，带着双胞胎女儿与友人们在希腊展开阳光斑驳的夏日旅居。然而这对伴侣很快发现，长久积压的矛盾逐渐浮出水面，使假期陷入波澜。林克莱特与演员们历经二十年打磨出的情感深度、锐利机锋与酣畅对白，在此凝结成篇。本片深入探讨长期亲密关系的复杂肌理，叩问当爱情褪去往日幻影，究竟将归于何种模样。[标准收藏]','Everything\'s better with maturity.',3000000,11176469,23.299907,7.4,568,108,'2013-04-05','en','/ywRDktMWN1muuK7D2bxfs9l9tcc.jpg',3.433772112847158,3,'2026-09-10',2,NULL,NULL),(132363,'白宫管家','The Butler','影片灵感源自于华盛顿邮报上的一篇文章，改编自真人真事。主人公是一位黑人，1952年他应聘食品管理员而走进白宫工作。在他任职的34年间，美国总统轮换了八位，而他最终也成为了白宫里人人尊敬的首席管家。  　　塞西尔·盖恩斯是白宫里的一个工作人员，他从头到尾一共服侍了8位总统，从1952年一直工作到1986年。在这34年的时间里，他从一个小小的服务生工作到了整个白宫的管家。这段时间里，美国发生了翻天覆地的变化。而身处暴风中心的塞西尔·盖恩斯，虽然只是一个小小的管家，但是他的所见所闻，也已经超出了事件本身的意义。  　　在白宫期间，他见证了美国的联邦高中一体化的教育改革，纳什维尔静坐，自由骑士运动，肯尼迪遇刺，1965年投票权法案，马丁·路德·金遇刺，黑豹党事件，越南战争，尼克松辞职，南非解放运动以及最近发生的奥巴马竞选总统并成功当选的历史事件。','One quiet voice can ignite a revolution.',25000000,115922175,32.105328,7.2,1101,132,'2013-08-16','en','/6TlbMJvBwA9y2RHYN5hWc0qQZUj.jpg',3.6245345316930297,3,'2026-09-10',2,NULL,NULL),(133575,'加里的速度','The Velocity of Gary','Gary is in love with Valentino. So is Mary Carmen. Their life changes when Valentino is hit with a deadly disease and is slowly dying in their hands. They tear each other off to end up re-uniting upon their love for the same man.','*(Not His Real Name)',4000000,0,0.409089,4.2,5,100,'1999-07-16','en','/8wQlK0QukCXXmvmDARAx65wnX4j.jpg',2.2198808152998657,3,'2026-09-10',2,NULL,NULL),(133694,'应许之地','Promised Land','GLOBAL公司派遣员工Steve Butler（马特·达蒙 Matt Damon 饰）和Sue Thomason（弗兰西斯·麦克多蒙德 Frances McDormand 饰）到一个以农业为经济支柱却蕴含丰富天然气资源的小镇，试图说服当地居民和GLOBAL公司合作，一起开采天然气，此举也将振兴当地的经济。Steve本以为这是水到渠成的事情，却遭到了当地高中的一名教科学的老师Frank（哈尔·霍尔布鲁克 Hal Holbrook 饰）的反对，Frank提出要整个镇上的人进行投票，以决定是否开始天然气的开采。而一名来自环保组织“雅典娜”的年轻人Dustin Noble（约翰·卡拉辛斯基 John Krasinski 饰）的突然出现，他以自己家乡因为开采石油气而遭到破坏为证据，更加剧了当地人民对开采天然气的抵触。Steve在当地认识的一名颇有好感的女性Alice（罗丝玛丽·德薇特 Rosemarie DeWitt 饰）似乎也对他失去了信任。Steve能否顺利完成公司的任务？','What\'s your price?',15000000,8138788,13.568302,6,243,106,'2012-09-23','en','/zoZWhLZMPoCGBW5xqm01sVK9pQB.jpg',3.050019421647696,3,'2026-09-10',2,NULL,NULL),(133698,'私奔B计划','Un plan parfait','伊萨贝拉为了绕过她家所有人的第一次婚姻都会破裂的厄运，她想出了能嫁给她爱的人的策略：找个好骗的，诱惑他、嫁给他然后再离婚。  　　这真是个完美的计划，如果她要骗的人不是那个令人受不了的让-伊夫·贝尔蒂埃，他是本旅游指南的编辑，于是她追着他从乞力马扎罗山一直到莫斯科。  　　一场无论安乐尤其是患难的结婚旅行。',NULL,0,0,11.60921,5.6,194,104,'2012-10-29','fr','/tZVfp3R7KmiSY7WgIRUckYz2Gb0.jpg',2.9729748262742595,3,'2026-09-10',2,NULL,NULL),(133805,'魔女嘉莉','Carrie','玛格丽特·怀特（朱丽安·摩尔饰）与女儿嘉莉·怀特（科洛·莫瑞兹饰）居住在缅因州Chamberlain的宁静郊区，嘉莉是个可爱的女孩，但性格严厉的母亲却禁止她一切社交活动。在学校中，以克丽丝为首的坏女孩们则常常以欺负嘉莉为乐，体育老师德斯贾丁斯小姐对饱受欺辱的嘉莉呵护有加，克丽丝的好友苏心中愧疚，为了表示歉意，苏让她的男友、帅哥Tommy Ross带嘉莉参加学校舞会。然而在舞会上，嘉莉再度受到的羞辱令她濒临崩溃，从而释放出可怕的超能力……','Know her name. Fear her power.',30000000,82394288,63.848541,5.8,1463,100,'2013-10-16','en','/AobuUPGSbOEx8KNtxFLTgm3GVK0.jpg',3.499786388956066,3,'2026-09-10',2,NULL,NULL),(133931,'Zambezia','Zambezia','Set in a bustling bird city on the edge of the majestic Victoria Falls, \"Zambezia\" is the story of Kai - a naïve, but high-spirited young falcon who travels to the bird city of \"Zambezia\" where he discovers the truth about his origins and, in defending the city, learns how to be part of a community','Airborne to be wild.',20000000,0,14.182301,5.3,68,83,'2012-06-05','en','/7aJl440TlbyqthklVrvCnSbjKYe.jpg',2.7647877199102737,3,'2026-09-10',2,NULL,NULL),(134371,'Atlas Shrugged Part II','Atlas Shrugged Part II','The global economy is on the brink of collapse. Brilliant creators, from artists to industrialists, continue to mysteriously disappear. Unemployment has risen to 24%. Gas is now $42 per gallon.  Dagny Taggart, Vice President in Charge of Operations for Taggart Transcontinental, has discovered what may very well be the answer to the mounting energy crisis - found abandoned amongst ruins, a miraculous motor that could seemingly power the World.  But, the motor is dead... there is no one left to decipher its secret... and, someone is watching.  It’s a race against the clock to find the inventor and stop the destroyer before the motor of the World is stopped for good.  A motor that would power the World. A World whose motor would be stopped.  Who is John Galt?','Who is John Galt?',0,0,4.725357,5.4,41,112,'2012-10-12','en','/9iwPz9zy1uCP73QMxhNs6gaTTom.jpg',2.6448090306612206,3,'2026-09-10',2,NULL,NULL),(134374,'健男抢钱团','Pain & Gain','满怀美国梦的丹尼尔是一名健美教练，为改变困顿现状，他连同好友艾德里安与刚出狱的保罗一起密谋敲诈勒索的勾当，企图从中致富。因此三位同样健壮猛龙，一起浩浩荡荡地干了一宗绑架案。由于他们的智商有限，导致犯罪之路越陷越深而一发不可收拾，使得他们遭到警察的追查及全面围剿……','Their American dream is bigger than yours.',25000000,86175291,31.893932,6.1,1573,130,'2013-04-18','en','/jq2O75frs4726Y7KaQsdKTVVjTt.jpg',3.502551551295934,3,'2026-09-10',2,NULL,NULL),(134411,'告密者','Snitch','根据真实故事改编，讲述了强森饰演的父亲为了被陷害贩毒入狱的儿子讨回公道，与律师达成协议，不惜铤而走险，伪装成卧底混入贩毒集团内部。','How far would you go to save your son?',35000000,42930462,30.556135,5.8,1138,112,'2013-02-21','en','/n6jEpfjRKkr8y2VcnMWCAVNIKjJ.jpg',3.3746594731067345,3,'2026-09-10',2,NULL,NULL),(134597,'藏品','The Collection','音浪滚滚，群魔乱舞的夜店内，目睹男友出轨的艾莲娜（艾玛·费兹帕特里克 Emma Fitzpatrick 饰）无意中掣动某开关，致使寻欢场所顿时化作绞肉地狱，无数男女惨遭屠戮，搜尸者（Randall Archer 饰）静观这一血腥残酷场景，并在最终时刻虏走艾莲娜。混乱之中，饱经磨难的阿金（乔什·斯图沃特 Josh Stewart 饰）侥幸逃脱。正当他待在医院接受治疗时，受某富翁之托的警方找上门来，要求阿金在48小时之内找到艾伦娜。无论如何，阿金必须再次返回留下无数梦魇的魔窟，时间紧迫，尝试逃亡的艾莲娜时时处在危险之中。而阿金和警察部队也面临搜尸魔布下的致命陷阱。死神的脚步渐次清晰……','Every great collector has a vision.',0,6842058,16.361743,5.9,289,94,'2012-09-21','en','/poDWlSRsGQewaia8q6DKj3pRKNn.jpg',3.08423750731547,3,'2026-09-10',2,NULL,NULL),(135397,'侏罗纪世界','Jurassic World','多年过去，努布拉岛终于实现了约翰·哈蒙德曾经的梦想，一座拥有大量活体恐龙的主题公园“侏罗纪世界”每天吸引着成千上万的游客。然而随着人们逐渐习惯恐龙带来的震撼，公园为了制造新的吸引力，利用多种生物的基因培育出前所未有的混种恐龙“暴虐霸王龙”。负责公园运营的克莱尔邀请长期研究迅猛龙的欧文·格雷迪评估它的安全设施，却很快发现这种聪明而危险的生物远比任何人预想的更加难以控制。当暴虐霸王龙成功逃出围栏，一座原本井然有序的恐龙乐园也随之陷入前所未有的危机……','The park is open.',150000000,1513528810,418.708552,6.5,8662,124,'2015-06-09','en','/rhr4y79GpxQF9IsfJItRXVaoGs4.jpg',4.866231702416052,3,'2026-09-10',2,NULL,NULL),(135595,'纯真的交易','Trade of Innocents','In the back streets of a tourist town in present-day Southeast Asia, we find a filthy cinder block room; a bed with soiled sheets; a little girl waits for the next man. Alex (Dermot Mulroney), a human trafficking investigator, plays the role of her next customer as he negotiates with the pimp for the use of the child. Claire (Mira Sorvino), Alex\'s wife, is caught up in the flow of her new life in Southeast Asia and her role as a volunteer in an aftercare shelter for rescued girls where lives of local neighborhood girl\'s freedoms and dignity are threatened. Parallel story lines intertwine and unfold twists against the backdrop of the dangerous human trafficking world, in a story of struggle, life, hope and redemption in the \"TRADE of INNOCENTS.\"','Justice needs a hero',0,0,2.204138,5.5,12,91,'2012-09-27','en','/fEr6rVOHpXpnBK2WRZZ1wn0PEF9.jpg',2.392810223787213,3,'2026-09-10',2,NULL,NULL),(136400,'双龙出手','2 Guns','鲍比-特伦奇（丹泽尔-华盛顿 饰）在抢银行前对马库斯-西格曼（马克-沃尔伯格 饰）说，行内有不成文的规矩，不要打劫贩卖美味的甜甜圈的旁边的银行。因为警察都会去那里买吃的。不管怎么说，他们的行动很顺利：现场没有人报警，保险柜被轻易打开，他们用汽车装走了四千万美元的现金。待行至荒野，清点钱数的时候，他们突然举枪指向彼此。在鲍比还没明白怎么回事的时候，已经摔倒在地，而马库斯这才看到鲍比手里拿着的警徽，发现他是美国缉毒局的探员。而马库斯也是海军罪案调查处的警官。他们二人都用了12个月的时间进行卧底，试图掌握犯罪集团的动向和犯罪证据。他们在同时渗透墨西哥毒品组织的过程中不明就里的碰到了一起，让彼此都乱了阵脚。他们的上司见状变了脸，希望他们退出行动，并且要追究他们违法抢劫。孤立无援的两个人只好通力合作调查事件真相。过程中，他们发现中情局在其中捣了鬼……','2 Guns, 1 Bank.',61000000,131940411,42.881415,6.6,1589,109,'2013-08-02','en','/c0nmGLvzCJWHU5Oldvuaoy9BD1j.jpg',3.6326880435738507,3,'2026-09-10',2,NULL,NULL),(136795,'辣手警花','The Heat','飞扬跋扈的联邦调查局女特工桑德拉·布洛克与一个满嘴脏话的胖女警察梅丽莎携手合作，追捕一个俄罗斯毒品集团，两人在这一过程中也建立了友谊。影片的其他主要演员还有奥斯卡影帝提名获得者德米安·比齐尔、托尼·海尔、泰伦·基勒姆、迈克尔·拉帕波特等。该片的 导演保罗·费格两年前曾拿出了卖座女人戏《伴娘》，并一手将梅丽莎送入奥斯卡最佳女配角决赛圈。','Action\'s never been so hot!',43000000,158674180,37.654688,6.5,1575,117,'2013-06-27','en','/2Pu69s5S1VzIk4NMIW8oqMMAnAD.jpg',3.598036490491896,3,'2026-09-10',2,NULL,NULL),(136797,'极品飞车','Need for Speed','故事围绕托比·马歇尔展开，他本是一名蓝领机修工，偶尔参加地下赛车巡回赛作为副业，却遭陷害锒铛入狱。出狱后，托比决定要报仇雪恨，让陷害他的奸人付出代价——惟一能达成此目标的机会就是参加一项贯穿全美的地下赛车。等待托比的将是一系列令人心跳加速的飞车考验；而始于复仇的任务，也渐渐演变成一场赎罪之旅。','For honor. For love. For redemption.',66000000,203277636,54.81489,6.1,1520,130,'2014-03-13','en','/kSS6rdbtcqAESoxDvJlawTP1EeQ.jpg',3.5474979925348635,3,'2026-09-10',2,NULL,NULL),(136835,'危险行为','No Good Deed','艾尔巴的角色埃文斯被描述为“恶性自恋”，为引起女性的注意“不惜使用暴力”，申请保释被驳回后，他从押解车中逃出，来到昔日恋人家中报仇。报仇完毕，又在一片漆黑的雨夜，出现在了泰瑞家门口。泰瑞有两个孩子，丈夫外出未归，她好心想借电话给埃文斯一用，却不料让自己和孩子都陷入了险境之中。','First he gets into your house. Then he gets into your head.',13200000,53830415,24.656068,5.6,181,83,'2014-09-10','en','/wcDLqCS70LsPcovieuQrb311Qr1.jpg',2.9895307465757677,3,'2026-09-10',2,NULL,NULL),(137093,'最后的维加斯','Last Vegas','该剧讲述了四个年过六旬的好友在拉斯维加斯为重回单身的好友开单身派对时，发生的一些轶事，所以该片也被戏称为老年版《宿醉》。加盟该片的还有罗伯特•德•尼罗，摩根•弗里曼以及凯文•克莱恩。堪称“奥斯卡影帝的豪华聚会”。','It\'s going to be legendary',28000000,134402450,28.043508,6.4,799,105,'2013-10-31','en','/otQ01cPgJbXgjT5SeT1BKLVCG21.jpg',3.394484769834233,3,'2026-09-10',2,NULL,NULL),(137094,'一触即发','Jack Ryan: Shadow Recruit','杰克·莱恩原本只是CIA金融情报科的一名分析师，他发现所在公司的老板正在策划一起颠覆美国经济的惊天阴谋。在CIA老将哈勃的招募和指引下，莱恩不得不初出茅庐，从分析师摇身一变成为外勤特工，前往莫斯科执行任务。而他的未婚妻凯蒂也在随之前往的途中，意外发现了他的特工身份……','Trust no one.',60000000,50549107,42.538258,5.9,1173,105,'2014-01-15','en','/vNSuMl9gBKEVX8p4c41jKu3tclC.jpg',3.4264345773951725,3,'2026-09-10',2,NULL,NULL),(137106,'乐高大电影','The Lego Movie','一个普通的乐高小人，被误认为是非凡的“建筑大师”，因而被招募加入一场冒险之旅，以阻止一名邪恶的乐高狂人用胶水将宇宙粘合在一起。','The story of a nobody who saved everybody.',60000000,469160692,59.547928,7.5,3070,100,'2014-02-06','en','/lbctonEnewCYZ4FYoTZhs8cidAl.jpg',4.049840451887722,3,'2026-09-10',2,NULL,NULL),(137113,'明日边缘','Edge of Tomorrow','未来世界陷入外星人入侵的恐慌中，军事演说家凯奇少校畏惧上战场，他从没想过将军会让他去指挥即将开始的“诺曼底战役”，拒绝接受命令之后将军居然恶整了他，那就是把他当做逃兵扔进了军营中。凯奇被归入了J小队中进行战斗，战役的第一天就惨死在战场，没想到这一死让他拥有了时空循环的能力，而唯一相信他的人就是被称为“全金属战士”的丽塔·沃拉塔斯基。二人开始了时空循环作战，在训练凯奇的同时他们发现了控制时间的奥秘，这与外星人“主脑”欧米茄有关，但是唯一能取得胜利的方法就是让凯奇不断死去、不断重启时间。在不断重复登陆那天的战斗的同时，凯奇越来越不想失去丽塔……','Live, Die, Repeat',178000000,370541256,79.456485,7.6,4858,113,'2014-05-27','en','/nBM9MMa2WCwvMG4IJ3eiGUdbPe6.jpg',4.246584126504524,3,'2026-09-10',2,NULL,NULL),(137321,'冬日奇缘','Winter\'s Tale','皮特（柯林·法瑞尔 Colin Farrell 饰）是一名心地善良的男子，却在无奈之下加入了名为“短尾巴”的黑帮组织，成为了一名小偷。一场意外中，皮特得罪了黑帮大佬索穆斯（罗素·克劳 Russell Crowe 饰），引来了杀身之祸，为了保命，他不得不踏上了逃亡的旅途。  　　某日，皮特潜入了报业大亨艾萨克（威廉·赫特 William Hurt 饰）的豪宅之中企图行窃，没想到却遇见了艾萨克的女儿贝弗利（杰西卡·布朗·芬德利 Jessica Brown Findlay 饰）， 贝弗利的温柔和美丽很快就吸引了皮特的注意，两人双双坠入了爱河。然而，灾难发生了，贝弗利因为感染了肺病不幸去世，皮特陷入了痛苦和绝望中无法自拔。一场意外中，皮特闯入了环绕城市的云墙之中，从此了无音讯，当他再度出现在人们的视野中之时，百年已经匆匆流逝。','This is not a true story. This is true love.',60000000,30800231,22.736038,6,487,118,'2014-02-13','en','/cy8PnOSYJj5YdtZtNITjMGCW816.jpg',3.216389917323513,3,'2026-09-10',2,NULL,NULL),(137347,'近月行动','Closer to the Moon','该片根据1959年发生在罗马尼亚的真实案件改编，曾被拍成纪录片《共产主义大劫案》，一群罪犯在冒充拍摄一部影片的过程中对布加勒斯特国家银行进行了抢劫——这样的剧情是否让你似曾相识呢？由本·阿弗莱克执导的新片《逃离德黑兰》就是讲述了FBI假冒成好莱坞电影拍摄剧组解救人质的故事。不过《近月行动》并不是一部纯粹的heist商业片，而关注的是这起事件背后的的政治阴谋。首先五名罪犯都是二战中留下功绩的战斗英雄',NULL,9000000,0,9.159265,6.4,13,112,'2013-11-29','en','/pBqnSEkLMZoEFgOCQLxM7wKmmS0.jpg',2.429279678526577,3,'2026-09-10',2,NULL,NULL),(137955,'乌鸦魔地','Crowsnest','In late summer of 2011, five young friends on a road trip went missing after being attacked by nomadic cannibals in a huge RV. Video was recorded by the victims &amp; recovered by police as evidence in their still-unsolved murders.',NULL,1200000,0,0.057564,4.8,12,84,'2012-01-01','en','/g2swX9YGaIq1dpGr7gva8DGnWe4.jpg',2.3845036003580034,3,'2026-09-10',2,NULL,NULL),(138103,'The Expendables 3','The Expendables 3','Barney, Christmas and the rest of the team comes face-to-face with Conrad Stonebanks, who years ago co-founded The Expendables with Barney. Stonebanks subsequently became a ruthless arms trader and someone who Barney was forced to kill… or so he thought. Stonebanks, who eluded death once before, now is making it his mission to end The Expendables -- but Barney has other plans. Barney decides that he has to fight old blood with new blood, and brings in a new era of Expendables team members, recruiting individuals who are younger, faster and more tech-savvy. The latest mission becomes a clash of classic old-school style versus high-tech expertise in the Expendables’ most personal battle yet.','New team. New attitude. New mission.',90000000,206172544,61.025639,6.1,1795,127,'2014-08-04','en','/4R1D4dibHpK3KvMRAJ8qNDgfsqn.jpg',3.59763958321546,3,'2026-09-10',2,NULL,NULL),(138697,'唐璜','Don Jon','在Jon（约瑟夫·高登-莱维特 Joseph Gordon-Levitt 饰）的人生里他只在乎这几件事：健身、飙车、去教堂、泡妞和看色情录像。虽然Jon的周围并不缺少和他上床的漂亮姑娘，可是Jon从来没有从与这些女孩的关系中得到满足感。相反，只有在看色情录像的时候Jon才能感受到“忘我的快感”。Jon不知不觉间将这样的矛盾带入了与新女友芭芭拉（斯嘉丽·约翰逊 Scarlett Johansson 饰）的关系中。虽然Jon不可自拔疯狂地爱上了芭芭拉，可是芭芭拉不能接受男友背着自己看色情录像这个事实。而这时熟女艾斯特（朱丽安·摩尔 Julianne Moore 饰）的出现令Jon对男女关系产生了新的认识。当面对美丽的女友和令人不能自拔的色情录像，Jon将做出怎样的选择？而这两个女性又将给Jon在对待男女关系的态度上带来怎样的改变？本片是约瑟夫·高登-莱维特首次执导的影片。','Everyone loves a happy ending.',6000000,0,33.296684,5.9,1671,90,'2013-07-26','en','/qN7pZFsWOWmm0YZlArgIWFVtzuc.jpg',3.4770376720263196,3,'2026-09-10',2,NULL,NULL),(138832,'冒牌家庭','We\'re the Millers','David（杰森·苏戴奇斯 Jason Sudeikis 饰）是丹佛的毒贩子，生活过得有滋有味。一个夜里，和David住在同一个公寓的十八岁男孩Kenny（威尔·保尔特 Will Poulter 饰）看见一个流浪女孩正被人勒索，便出手相助。David不忍心看到Kenny被小混混们欺负，也加入战局，无奈寡不敌众，救人不成反而全副身家被抢走。原本已负债累累的David只能接受他的老板交给他的一个任务——去墨西哥运一批大麻回美国。为了掩人耳目，David找来同住同一座公寓的脱衣女郎Rose（詹妮弗·安妮斯顿 Jennifer Aniston 饰）、Kenny还有那个流浪女孩Casey（艾玛·罗伯茨 Emma Roberts 饰）假冒米勒一家，开着一辆房车直奔墨西哥而去。这冒牌家庭在一路上历经艰辛，能否顺利将毒品运输回国？','-If anyone asks.',37000000,269994119,100.348805,6.8,2972,110,'2013-08-07','en','/qF2LJ0jwWrtXSuT4AFD5OS2IqaT.jpg',3.965219898059479,3,'2026-09-10',2,NULL,NULL),(138843,'招魂','The Conjuring','二十世纪七十年代，罗杰与卡罗琳两夫妇带着他们五个可爱美丽的女儿，搬到了位于罗德岛哈瑞斯维尔的一幢旧宅居住。房屋虽然古旧沧桑，历史悠久，但是却让佩隆一家体会到回归田园的快乐与喜悦。谁知好景不长，接二连三的怪异事件相继出现，令女孩们惊声尖叫，也让佩隆夫妇的神经绷到极点。为此，他们辗转找到当时最负盛名的沃伦夫妇。','Based on the true case files of the Warrens',13000000,318000141,49.975409,7.4,3092,112,'2013-07-18','en','/wVYREutTvI2tmxr6ujrHT704wGF.jpg',4.005704636264932,3,'2026-09-10',2,NULL,NULL),(138976,'Treachery','Treachery','Treachery centers on a man (Biehn) who is reunited with his estranged son at a remote wedding party. When a storm strands the party, ugly truths are revealed.','Deep roots... Deeper Secrets',625000,0,0.283059,4.8,5,68,'2013-05-16','en','/3uJmk8lk4e5SUf15WcrathmOQNE.jpg',2.220820048320018,3,'2026-09-10',2,NULL,NULL),(139038,'鬼屋大电影','A Haunted House','影片与《鬼影实录》同样采用伪纪录片风格的拍摄方式，剧情更是基本复制了《鬼影实录》：一对年轻夫妇搬进新家，谁知这竟是一间凶宅，妻子遭遇鬼附身，男主人（马龙·韦恩斯 饰）于是请来各路神仙驱魔，试图挽救自己的幸福生活，或者说“性”福生活。影片其实并非仅仅恶搞了《鬼影实录》，前年北美大卖的另一部伪纪录恐怖片《驱魔》也未能幸免。','This $*%! ain\'t paranormal.',2500000,60141683,18.661541,5.4,516,86,'2013-01-11','en','/ubdym2FqFpO2reCTny0thOxKJKJ.jpg',3.144509947685633,3,'2026-09-10',2,NULL,NULL),(139715,'留堂生大战僵尸','Detention of the Dead','A group of oddball high school students find themselves trapped in detention with their classmates having turned into a horde of Zombies.','When there\'s no more room in Hell, the dead will go to DETENTION!',500000,0,2.391847,4.5,34,87,'2012-04-27','en','/tf2baOEkFodZ5NYXMfb7gxcZgV.jpg',2.5897059509647637,3,'2026-09-10',2,NULL,NULL),(139948,'燃烧','Burn','A character-driven, action-packed documentary about Detroit, told through the eyes of the Detroit firefighters, the men and women charged with the thankless task of saving a city that many have written off as dead.','One Year on the Front Lines of the Battle to Save Detroit',225000,111300,0.126676,6.9,6,86,'2012-11-01','en','/eJdm7heehvPAASGw5cc8q22yius.jpg',2.2585505608898626,3,'2026-09-10',2,NULL,NULL),(139998,'配角','Supporting Characters','尼克（亚历克斯·卡普夫斯基 Alex Karpovsky 饰）是一名电影剪辑师，靠着相亲网站，尼克邂逅了名为艾米（索菲亚·塔卡尔 Sophia Takal 饰）的姑娘。最终，两人走到了一起，并且决定携手步入婚姻的殿堂，虽然这段感情对于尼克来说并没有什么不足之处，但敏感的他总觉得两人之间缺少了什么，直到有一天，他在片场邂逅了杰米（阿莉尔·凯贝尔 Arielle Kebbel 饰），尼克终于发现他苦苦在追寻的是什么了。',NULL,0,0,0.620554,6.7,10,87,'2012-01-23','en','/rSAfIqMTRwEsW51baMXaNK5i2fg.jpg',2.3582825762488886,3,'2026-09-10',2,NULL,NULL),(140300,'功夫熊猫3','Kung Fu Panda 3','当熊猫阿宝为成为真正的神龙大侠做准备的时候，他的生父——熊猫李山突然到访。与此同时，拥有神秘力量的反派天煞登场，妄图制服 所有高手，统治武林。相传在与世隔绝的熊猫村有着对抗天煞的力量，为了拯救苍生，阿宝与父亲踏上了归途，而阿宝的好伙伴悍娇虎、金猴、灵蛇、螳螂则一同拖延天煞，阿宝不仅肩负着成为真正的熊猫大侠的使命，还要让村民美美等新伙伴练就新功夫，继承乌龟大师的遗志，共同抵挡天煞。','Grab destiny by the rice dumplings.',145000000,521170825,56.747978,6.7,1603,95,'2016-01-23','en','/1lIojkLuYEqX1QjhnKvqapGHNLQ.jpg',3.687168429974357,3,'2026-09-10',2,NULL,NULL),(140823,'大梦想家','Saving Mr. Banks','曾两度荣获奥斯卡金像奖的艾玛·汤普森和汤姆·汉克斯将领衔主演迪士尼影片《拯救班克斯先生》。本片讲述了迪士尼经典影片《欢乐满人间》在版权购买历程中不为人知的故事。\r 当华特·迪士尼先生应允女儿将她们挚爱的P.L.特拉弗斯作品《欢乐满人间》搬上银幕时，他不曾料到，兑现这个诺言花了20年时间。在寻求改编权的过程中，迪士尼先生面对的是一位态度强硬的原作者老太太，她坚决不同意让好莱坞改编她笔下的精彩故事与传奇人物。直到原著的销售收入持续下滑，特拉弗斯才勉强同意飞往洛杉矶，与迪士尼先生一谈此事。\r 为了这短短的会面期，迪士尼使出浑身解数，试图用极富想像的改编故事和谢尔曼兄弟的精彩音乐打动特拉弗斯。然而，这位固执的作者一点也不买账。事情似乎变得越来越糟糕，改编权的事眼看要泡汤……\r 迪士尼先生开始认真思索自己的童年经历，他才发现了特拉弗斯不愿放手的真正原因，也开始化解她冰冷坚定的心。最后历经千辛万苦，并在两人的共同努力下，他们将《欢乐满人间》改编成了电影史上最受热爱的影片之一。','Where her book ended, their story began.',35000000,112544580,31.957947,7.3,1226,125,'2013-11-16','en','/kVe8D8zUWxil6j39Qut3fZ52eSM.jpg',3.67465563242948,3,'2026-09-10',2,NULL,NULL),(142061,'蝙蝠侠：黑暗骑士归来（下）','Batman: The Dark Knight Returns, Part 2','曾经罪恶横行的高谭市，自布鲁斯·韦恩决定以蝙蝠侠的身份归来后，仿佛终于发生了新的变化。变种人头目双面人被除掉，然而原变种人团伙摇身变成蝙蝠狂热者，以暴力的方式执行着对善恶之行的裁断。因此，蝙蝠侠的法外行为引起广泛争论，甚至惊动白宫，而高谭的新任探长对其存在颇有微词。正值美苏交恶的危机时刻，超人卷入战火，蝙蝠侠和这位昔日的战友因理念不同分道扬镳。在此期间，小丑高调复出，受邀参加某电视节目访问，实则暗藏新的阴谋。 为了阻止小丑的破坏，蝙蝠侠和新一代的罗宾突破重重阻隔，杀向对手……','Justice Returns... Vengeance Returns... Redemption Comes to Gotham.',3500000,0,25.891466,7.9,419,78,'2013-01-18','en','/edoxSu8c1xE9YsG81cE71d7Ln98.jpg',3.400355478484103,3,'2026-09-10',2,NULL,NULL),(142132,'Sugar Town','Sugar Town','Look at the lives of struggling L.A. scene rock stars follows main character, Gwen, on her quest for the top. Working as an assistant to a film production designer, she tries to steal her boy friend who is a music producer by offering sexual favors. The producer meanwhile is trying to orchestrate a comeback for a former glam band comprised of Michael Des Barres, John Taylor and Martin Kemp. Rosanna Arquette plays the former movie star wife of the lead singer, who is fretting because she has just been offered the role as the mother of one of the new ingenious. Beverly D\'Angelo also shows up as a millionairess who agrees to bankroll the group, but only if she gets a roll in the hay with the lead singer. All of the career problems, including drug proclivity, are represented in this film.',NULL,0,0,0.375423,5.5,2,92,'1999-09-17','en','/9VpZ9apNn5uym9TYEtYEhMYOTEX.jpg',2.072697335980614,3,'2026-09-10',2,NULL,NULL),(144336,'破坏者','Sabotage','一支精英缉毒队去对付全世界最高端的贩毒组织想要通过精妙的战术对毒贩的藏身之所进行突袭。经过巧妙安排，缉毒队认为他们的计划万无一失，直到成员一个接一个被暗杀。','Leave no loose ends',35000000,17508518,27.903999,5.5,555,110,'2014-03-28','en','/gjsmL75PysLQTxNNsJcMgjXwIj.jpg',3.1905841008687483,3,'2026-09-10',2,NULL,NULL),(144340,'Admission','Admission','Strait-laced Princeton University admissions officer Portia Nathan is caught off-guard when she makes a recruiting visit to an alternative high school overseen by her former college classmate, the freewheeling John Pressman. Pressman has surmised that Jeremiah, his gifted yet very unconventional student, might well be the son that Portia secretly gave up for adoption many years ago. Soon, Portia finds herself bending the rules for Jeremiah, putting at risk the life she thought she always wanted – but in the process finding her way to a surprising and exhilarating life and romance she never dreamed of having.','Let someone in.',13000000,18000000,17.632446,5.4,304,107,'2013-03-21','en','/f3HoCikJxypRtLJptBwvs7L7etE.jpg',3.0532598767880303,3,'2026-09-10',2,NULL,NULL),(145220,'布偶大电影2','Muppets Most Wanted','科米蛙将面对最大的挑战：布偶团正在进行欧洲巡演，到达了柏林、马德里、伦敦等令人兴奋的城市。但很快一个和科米蛙长得几乎一模一样，却操着一口带有浓重俄国口音英语的青蛙大盗康斯坦丁，摇身一变，和他的搭档多米尼克(瑞奇·热维斯饰演)混入了布偶团，而可怜的科米蛙则被蒂娜·菲饰演的狱警娜佳打入大牢，身陷囹圄。此外，《摩登家庭》男星泰·布利尔将饰演国际刑警，调查这桩奇怪的案件。','Taking the world by farce',50000000,80383290,14.808304,6.2,316,112,'2014-03-20','en','/AmX19leUR5gzBZrvA2QXVxGpgHK.jpg',3.126069426618441,3,'2026-09-10',2,NULL,NULL),(146198,'红色警戒999','Triple 9','黑手党势力横行的亚特兰大阴云密布。现役警察、被警队除名的瘾君子、亡命匪徒组成的团伙受命于黑手党的蛇蝎美人头目，抢劫了市中心的金库却只为一个神秘保险箱。本以为可以借此金盆洗手的五人却被蛇蝎美人继续要挟完成一个不可能的抢劫任务……','The Code on the Street is Never Black & White',20000000,12639297,29.371987,5.6,797,115,'2016-02-19','en','/tr4L9cPkp8EaOVFhlDNlLlmNJqM.jpg',3.271527700447504,3,'2026-09-10',2,NULL,NULL),(146203,'最后一次驱魔2','The Last Exorcism Part II','续集故事紧接上集展开，女主角Nell Sweetzer（阿什丽·贝尔 饰演）经历了噩梦般的驱魔过程，厌倦了独自一人在偏僻乡村的生活，搬到相对安全的新奥尔良州尝试开始新生活。岂料，她的新生活依旧被一些灵异事件所包围，她发现，严峻的“驱魔”冒险才刚刚开始...','The second coming',5000000,15179302,10.605752,4.4,203,88,'2013-02-28','en','/zkqerctRFkkCJiMGGaVis1ABrc7.jpg',2.900847119069722,3,'2026-09-10',2,NULL,NULL),(146216,'赤焰战场2','RED 2','前中情局特工弗兰克·摩西（布鲁斯·威利斯 Bruce Willis 饰）退休后远离杀戮战场，无比享受与莎拉（玛丽·露易斯·帕克 Mary-Louise Parker 饰）为伴的悠闲岁月。某天他毫无征兆地目击了老搭档马文·博格斯（约翰·马尔科维奇 John Malkovich 饰）惨死的一幕，自己也成为下一个被追杀的目标。一切源于冷战时代的龙葵之光计划，美国政府为了防止该计划流传网络，因此急于抹杀知情者弗兰克和马文。马文死而复生，救出被困的弗兰克，二人带着莎拉一路逃亡，寻找龙葵之光的关键人物。与此同时，维多利亚（海伦·米伦 Helen Mirren 饰）被英国军情六处命令追杀弗兰克等人，而曾和弗兰克有过交集的世界顶尖杀手韩朝培（李秉宪 饰）也受雇于美国政府尾随前来。久违的搏杀再起……','The best never rest.',84000000,0,44.34333,6.4,1526,116,'2013-07-18','en','/yTcyxCtsFiu1LXIr6PQDubrxxby.jpg',3.585350584076204,3,'2026-09-10',2,NULL,NULL),(146227,'逃脱','Getaway','影片讲述了伊桑霍克饰演的前赛车手必须遵守一个神秘男人的指示，才能拯救他被绑架的妻子，霍克抢了赛琳娜的一辆野马眼镜蛇赛车竞速救妻，带着妹子一起在路上狂飙驰骋。','Get in. Get out. Getaway.',18000000,10501938,16.520516,4.9,246,90,'2013-08-29','en','/uIcaW8EZgckZNuQiLF6mDi0eLRI.jpg',2.9760282224876016,3,'2026-09-10',2,NULL,NULL),(146233,'囚徒','Prisoners','为了自己孩子的性命你会做到哪一步？凯勒.多佛 面对的是每个父母最恐惧的恶梦。他六岁的女儿安娜和小玩伴祖儿一起失踪了。唯一的线索是早前停在他家附近的一辆休闲车。在调查中，警探洛基 逮捕了这辆车的车主亚历克斯.琼斯，但因为缺乏证据而不得不放了他。 想到自己的孩子身处险境，急疯了的多佛决定靠自己。这位绝望的父亲决定不顾一切找到失踪的小女生们，但在找寻女儿的过程中，他渐渐迷失了自己，从而引出一个问题：寻求正义是不是可以超越法治？','Every moment matters.',46000000,122126687,88.496873,7.9,3085,153,'2013-09-18','en','/uhviyknTT5cEQXbn6vWIqfM4vGm.jpg',4.214415504592753,3,'2026-09-10',2,NULL,NULL),(146238,'逆转王牌','Runner Runner','影片刻画了神秘莫测的线上德州扑克的阴暗故事。Ben Affleck饰演的是一名腐败的线上德州扑克网站老板。而Anthony Mackie将饰演一名FBI警员。Timberlake饰演的角色会前往哥斯达黎加，去讨回他被Affleck饰演的角色所拥有的德州扑克网站欺诈的学费。','The house always wins.',30000000,62616646,22.975918,5.5,543,91,'2013-09-24','en','/eyRFJyZSobOVDYnUIkeBNXCXyId.jpg',3.17557393129629,3,'2026-09-10',2,NULL,NULL),(146239,'送子先生','Delivery Man','翻拍自《星爸客》。文斯·沃恩扮演的精子捐献者，其精子贡献了533个孩子，而这些孩子们现在要起诉他。与《星爸客》展现奇葩囧事的着力点不同，本片更侧重于后期诉讼和这位爸爸真的想要走出来面对一切的部分。','You\'re never quite ready for what life delivers.',26000000,51164106,30.114383,6.2,551,105,'2013-10-10','en','/dPywwr8wUsXz3MxRbGDya5fFswx.jpg',3.2848299894172466,3,'2026-09-10',2,NULL,NULL),(146269,'The Young Unknowns','The Young Unknowns','Charlie, his sexy girlfriend, and his moronic best friend drink, drug, and self-destruct over the course of one day at Charlie\'s father home in Los Angeles.',NULL,0,0,0.004922,0,0,87,'2000-03-12','en',NULL,1.833793628137666,3,'2026-09-10',2,NULL,NULL),(146304,'伴郎假期','The Best Man Holiday','故事讲述了15年后这群大学同学团聚在圣诞假期的浪漫喜剧故事。他们喝酒、打牌、参加婚礼、甚至乌龙滚床单，总之将时光拨回那段最令人怀念的友情时刻。','Times change. Friendship doesn\'t.',17000000,71625195,7.210095,6.7,110,123,'2013-11-15','en','/i4ecMHJQpclIEr4mh5uzjWr38GC.jpg',2.896032467448908,3,'2026-09-10',2,NULL,NULL),(146631,'不明飞行物','U.F.O.','老牌动作明星尚格·云顿在这部科幻新片中饰演一位退役军事顾问，不过他并非主角，影片主人公是五个年轻人，某日他们早上醒来发现生活陷入了一种说不出的诡异状态，在一阵剧烈的地震过后，天空出现了一个城市般大小的巨型UFO。整个城镇电力消失，手机也没了信号……人类面临庞大的外星军队的突袭','Try to remain calm',2500000,0,8.248149,3.1,47,101,'2012-12-14','en','/u6YRCDCiauJFYltBklD1X8m6OQm.jpg',2.6384637913963735,3,'2026-09-10',2,NULL,NULL),(146882,'Elza','Le bonheur d\'Elza','A young Parisian woman of Caribbean descent returns to her native island of Guadeloupe looking for the father she has never known.',NULL,0,0,0.007254,0,0,78,'2011-04-11','fr',NULL,1.833798954884564,3,'2026-09-10',2,NULL,NULL),(147441,'法老与众神','Exodus: Gods and Kings','摩西（克里斯蒂安·贝尔 Christian Bale 饰）和法老拉美西斯二世（乔尔·埃哲顿 Joel Edgerton 饰）是情同手足的好兄弟，彼此之间感情十分要好。摩西得到了神的旨意，决心将成千上万的犹太人民从水深火热的生活之中解救出来，他向拉美西斯寻求帮助，然而，这位好友却十分坚决地拒绝了他。不仅如此，拉美西斯还对犹太人进行了惨无人道的屠杀。为了惩罚拉美西斯的暴行，神在埃及降下了“十灾”，一时间，埃及陷入了混乱与死亡的阴影之中，然而，拉美西斯并没有因此而有所醒悟，最终，他和摩西成为了宿敌。摩西知道何为自己的使命，他带领着四十万希伯来人踏上了漫漫旅途，寻找一片属于他们的家园。','Once brothers, now enemies.',140000000,268031828,101.599427,5.6,1921,150,'2014-12-03','en','/hOm8Af0o5sHwS1KcHclQWoLbjDG.jpg',3.596230472181536,3,'2026-09-10',2,NULL,NULL),(147767,'天生大玩家','Khiladi 786','生来就继承了一家婚姻介绍所的曼苏克简直衰爆了。从他长大成年、懂事儿那天起，他便努力尝试帮助父亲强棒克经营家族事业。但所有经他戳和的准夫妻，婚前必然分手[2]  。\r 为了向父亲证明他的价值，他接手了一单不同寻常的挑战——为当地黑帮大佬T.T.大哥那位从小被溺爱的淘气女儿茵杜物色一门亲事，让她嫁给旁遮普一个名叫柒贰·辛格的警察(也就是我们的\"玩家\"先生)。但是更多的问题出现了，曼苏克说服T.T.大哥在未来的警察亲家面前假扮警察，然而T.T.大哥并不知道，无论是柒贰·辛格，还是他老爸柒零·辛格，亦或是他叔叔柒壹·辛格都不是警察，他们全家都是老千。两个和警察完全对立的强大家族在对方面前假扮警察，谎言随时会露馅，可怜的曼苏克随时有生命危险。',NULL,0,126,0.114342,4.7,11,139,'2012-12-07','en','/3chNHVi7j0jmUvJ1k7n2EYPfFmC.jpg',2.367329867265945,3,'2026-09-10',2,NULL,NULL),(147773,'迷途知返','The Way Way Back','一个夏天，14岁的少年Duncan（连姆·詹姆斯 Liam James 饰）跟着妈妈Pam、妈妈的男朋友Trent还有Trent的女儿一起去Trent在海边的小屋度假。像大部分离异家庭儿女一样，Duncan不喜欢妈妈的男朋友。Duncan发现自己和Trent的朋友们格格不入，原本就沉默寡言的他变得更加郁郁寡欢。直到他在一次单车出游中遇见了Owen（山姆·洛克威尔 Sam Rockwell 饰）。Owen是当地水上乐园的工作人员，在Owen的介绍下，Duncan成了水上乐园的一个兼职员工。在那里，他认识了新的朋友，度过了欢乐的时光，同时也和邻居家同样遭受家庭问题困恼的女孩Susanna（安娜·索菲亚·罗伯 Anna Sophia Robb 饰）越走越近。在一个夜里，Duncan发现了Trent的秘密，他和家庭的矛盾也越来越深.....','We\'ve all been there.',4600000,23198652,32.14444,7.1,688,103,'2013-06-06','en','/aHmrQnreex6pSt9rTUPinGtylNA.jpg',3.4701974343695308,3,'2026-09-10',2,NULL,NULL),(150202,'太平间闹鬼事件2：佐治亚鬼屋事件','The Haunting in Connecticut 2: Ghosts of Georgia','1993年，拥有幸福美满家庭的丽萨·威瑞克精神饱受折磨，她的家族患有遗传病症，她和姐姐乔希都能看到奇怪的景象，去世母亲的身影时时出现在她面前，声称要告诉她一些事情。为了帮助妻子治疗，丈夫安迪在佐治亚的林间买了一间小屋，可是宝贝女儿海蒂却由此声称能够看到一位名叫高迪的老人。乔希和安迪先后印证了海蒂的说法，但依赖药物的丽萨坚信这都是小女孩的臆想。在此之后，事态朝着不可预知的方向发展……',NULL,0,0,11.708343,5.6,175,101,'2013-02-01','en','/8ZT8sJshrP1Zm3sk346Evzv71DO.jpg',2.95349428827346,3,'2026-09-10',2,NULL,NULL),(150211,'冰冻','The Frozen','不久前刚刚得知自己怀孕的艾玛（布丽特·摩根 Brit Morgan 饰），怀着异样复杂的心情随同尚不知情的男友麦克（希斯·戴维·米切尔 Seth David Mitchell 饰）来到一处位于雪山冰原之间的小镇度假。无垠旷野，万籁俱寂，看似一切都是那么浪漫美好，但是他们驾驶雪地摩托时遭遇事故，二人相互搀扶，勉强回到帐篷。在完全没有信号的深山腹地，麦克他们不仅要对抗严苛冰冷的自然环境，还要承受莫大的精神压力尽快修好雪橇摩托逃离此地。',NULL,0,0,1.084387,4.2,14,0,'2012-10-10','en','/jbSBwAGNP4N4AcNX2Rxq4h5u5g3.jpg',2.413485161142171,3,'2026-09-10',2,NULL,NULL),(150540,'头脑特工队','Inside Out','11岁的莱莉原本在明尼苏达州过着快乐而熟悉的生活，直到父亲因为工作带着全家搬到旧金山。陌生的城市、新家和学校让她一时难以适应，而在莱莉的大脑总部里，乐乐、忧忧、怒怒、怕怕和厌厌五种情绪也在努力帮助她面对生活中的变化。一次意外却让乐乐和忧忧带着重要的核心记忆离开了总部，迷失在莱莉庞大而复杂的脑海世界。失去她们的平衡后，莱莉的生活也开始逐渐失控。为了回到大脑总部，乐乐与忧忧不得不携手穿越记忆深处，而这段旅程也将让她们重新认识每一种情绪真正的意义……','Meet the little voices inside your head.',175000000,857611174,128.655964,8,6560,94,'2015-06-09','en','/2H1TmgdfNtsKlU9jKdeNyYL5y8T.jpg',4.545770854908493,3,'2026-09-10',2,NULL,NULL),(150689,'灰姑娘','Cinderella','母亲去世后，瑞拉（莉莉·詹姆斯 Lily James 饰）的父亲迎娶了美丽的特曼妮夫人（凯特·布兰切特 Cate Blanchett 饰），特曼妮夫人还带来了她的两个女儿安泰西亚（荷丽黛·格兰杰 Holliday Grainger 饰）和崔西里亚（索菲·麦希拉 Sophie McShera 饰）。瑞拉本着善待他人的善良之心和继母与两个姐姐和平共处，然而，这一切却在父亲去世后发生了翻天覆地的变化。  　　失去了父亲的庇护，瑞拉彻底沦为了特曼妮夫人的奴隶和家中的女佣，可是，即使饱受亲人们的压迫与侮辱，瑞拉依然决定留下来，守护这个家庭。一次偶然中，瑞拉邂逅了名为基特（理查德·麦登 Richard Madden 饰）的男子，然而，她并不知道眼前这个充满了魅力的年轻人贵为王子，还以为他只是区区侍从。王子在王宫里举办了大型的宴会，邀请全国上下的少女们前往参加，瑞拉也想去，但特曼妮夫人显然并不喜欢她的这个主意。','Midnight is just the beginning.',95000000,543514353,101.187052,6.7,2374,105,'2015-03-12','en','/j91LJmcWo16CArFOoapsz84bwxb.jpg',3.8875882013372576,3,'2026-09-10',2,NULL,NULL),(152532,'达拉斯买家俱乐部','Dallas Buyers Club','1986年美国达拉斯市，恐同的德州电工罗恩·伍德鲁夫（马修·麦康纳 Matthew McConaughey 饰）发现自己患上“同志病”——艾滋，生命只剩30天。他使用的AZT（叠氮胸苷）是当时美国药管局唯一批准面市的抗艾药物，但毒性极大。为了活下去，罗恩开始研究各种抗艾处方和替代疗法，甚至走私来自世界各地未经批准的药物。在医生萨克斯（詹妮弗·加纳 Jennifer Garner 饰）和异装癖同性恋雷蒙（杰瑞德·莱托 Jared Leto 饰）的帮助下，罗恩开始成立了一个叫做“达拉斯买家俱乐部”的地下组织，为艾滋病人提供更多“非常规疗法”，很多患病的男女同性恋亦求助于他。他的举动自然受到了药管局和药商的阻挠和施压。罗恩最终在1992年9月去世，离他被告知只剩30天可活已经过去了2557天。在这近7年时间里，他坚持不懈的与病魔、与药管局及制药商进行艰苦的斗争，享受真正活过的人生...... 本片根据真人真事改编，讲述一个绝症病人如何努力求生并拯救成千上万面临同样境遇的人的故事，提名金球奖剧情类最佳男主/男配以及获得大小29个奖项。','Sometimes it takes a hustler to change the world',5000000,55198285,59.454473,7.9,2886,117,'2013-09-07','en','/7Fdh7gUq3plvQqxRbNYhWvDABXA.jpg',4.127963061920066,3,'2026-09-10',2,NULL,NULL),(152599,'移民','The Immigrant','故事发生在1921一年，艾娃（玛丽昂·歌迪亚 Marion Cotillard 饰）和姐姐玛格达（安吉拉·萨拉弗安 Angela Sarafyan 饰）经受不住繁华都市的霓虹诱惑，启程从波兰前往纽约淘金。半路上，玛格达不幸患上了当时是不治之症的肺结核，因此而被医生隔离在了位于埃利斯岛上的医院之中，情同手足的姐妹两人就此分道扬镳。来到纽约之后，艾娃才发现，这里的一切远不如幻想中的美好，她不幸的落入了皮条客布鲁诺（华金·菲尼克斯 Joaquin Phoenix 饰）的手中，成为了一名妓女。艾娃的生活中充满了伤痛和屈辱，能够再次和姐姐相见成为了她心中的唯一信念。一次偶然中，艾娃结识了名叫奥兰多（杰瑞米·雷纳 Jeremy Renner 饰）的魔术师，善良的奥兰多让艾娃明白，他可能是自己迈向新生活的唯一跳板。',NULL,16000000,5867686,13.832464,6.2,250,117,'2013-07-03','en','/hHUhFKcNQQogdCUnWxVujR0Z43B.jpg',3.0719142121663547,3,'2026-09-10',2,NULL,NULL),(152601,'她','Her','故事发生于不远的未来洛杉矶，讲述情感丰沛而复杂的西奥多·托姆布里——他以替人代写真挚书信为生。经历漫长关系终结后的心碎时期，他被一款全新高级操作系统吸引，该系统承诺将成为专属于每位用户的直觉型实体。启动系统后，他欣喜地遇见了“萨曼莎”——一个聪慧的女声，她富有洞察力、敏感且出人意料地幽默。随着她的需求与渴望和西奥多的内心同步滋长，他们的友谊逐渐深化为一段不可思议的爱情。[华纳兄弟]','A Spike Jonze Love Story',23000000,47351251,53.682367,7.9,4097,126,'2013-12-18','en','/eCOtqtfvn7mxGl6nfmq4b1exJRc.jpg',4.2179614997383235,3,'2026-09-10',2,NULL,NULL),(152737,'八月：奥色治郡','August: Osage County','Beverly和Violet（梅丽尔·斯特里普 Meryl Streep 饰）是一对老夫妻了，如今的他们，一个靠喝酒，另一个靠嗑药来维持这段夫妻关系。一天早上，Beverly出了家门后就再也没回来，Violet只能把他们的三个女儿还有她的表妹、表妹夫叫到家里来。二女儿Ivy来到了，之后大女儿Barbara（朱莉娅·罗伯茨 Julia Roberts 饰）和丈夫Bill（伊万·麦克格雷格 Ewan McGregor 饰）也带着14岁的女儿远道而来。噩耗随即传来，警察在湖里发现了Beverly的尸体，死因是自杀。小女儿Karen带着未婚夫赶到了葬礼。葬礼后的餐桌上，嗑药过头的Violet开始发脾气，而各怀心事的女儿们也如坐针毡。大女儿Barbara受不了母亲的刻薄，两人大声争吵起来，这个家庭潜藏着的种种矛盾和那些刻意隐瞒的真相也渐渐显露出来......\r 　　本剧改编自同名话剧，由原话剧作者Tracy Letts改编为电影剧本。','Misery loves family',25000000,74188937,20.561682,6.9,483,121,'2013-12-26','en','/e9242V7CajHWjQArhiMYjMGjFhZ.jpg',3.3173524851464267,3,'2026-09-10',2,NULL,NULL),(152742,'The Best Offer','La migliore offerta','Virgil Oldman is a world renowned antiques expert and auctioneer. An eccentric genius, he leads a solitary life, going to extreme lengths to keep his distance from the messiness of human relationships. When appointed by the beautiful but emotionally damaged Claire to oversee the valuation and sale of her family’s priceless art collection, Virgil allows himself to form an attachment to her – and soon he is engulfed by a passion which will rock his bland existence to the core.','A Master of Possession. A Crime of Obsession',13500000,19255873,30.058263,7.7,704,124,'2013-01-01','en','/9akIvcLeZR0DsXi1OIc9EZNt6GI.jpg',3.5605837470307637,3,'2026-09-10',2,NULL,NULL),(152747,'一切尽失','All Is Lost','在印度洋独自航行的深海中，一名无名男子（罗伯特·雷德福 饰）醒来发现他的39英尺帆船因与公海漂浮的货运集装箱相撞而进水。导航设备和无线电均已失灵，男子在不知不觉中驶入一场猛烈风暴的路径。尽管他成功修补了船体破口，凭借水手的直觉和与年龄不符的毅力勉强熬过暴风雨，但此后只能依靠六分仪和海图定位，被迫借助洋流漂向航线，期盼能拦截过往船只。然而烈日无情炙烤，鲨群环伺，本就匮乏的补给日益减少，这位素来足智多谋的水手终究不得不直面死亡的逼近。[Roadside Attractions]','Never give up.',9000000,6108720,28.540614,6.6,671,106,'2013-10-18','en','/9cVA4oX2xHgiglv6hemxwAaofsq.jpg',3.382767939723166,3,'2026-09-10',2,NULL,NULL),(152760,'The Monuments Men','The Monuments Men','Based on the true story of the greatest treasure hunt in history, The Monuments Men is an action drama focusing on seven over-the-hill, out-of-shape museum directors, artists, architects, curators, and art historians who went to the front lines of WWII to rescue the world’s artistic masterpieces from Nazi thieves and return them to their rightful owners.  With the art hidden behind enemy lines, how could these guys hope to succeed?','It was the greatest art heist in history',70000000,154984035,43.873266,5.8,1523,118,'2014-01-24','en','/wYI5NVOYqWi5GxRqsYJnDRLgAk6.jpg',3.4620501175064056,3,'2026-09-10',2,NULL,NULL),(153158,'挑战者联盟','Metegol','在南美某个安静祥和的小镇，少年阿玛迪奥（Rupert Grint 配音）痴迷于酒吧里的桌面足球，他出色的技巧赢得了女孩劳拉（Eve Ponsonby 配音）的放心，也击败了高傲自大的少年格罗索（Diego Ramos 配音）。此去经年，孩子们都已长大，阿玛迪奥依然不改对桌面足球的喜爱，即使劳拉即将去外地念书他也找不到合适的言辞应对。这一天，早已成为国际球星的格罗索突然高调返回，他买下小镇，并准备在此修建奢华的宇宙星河球场。格罗索不顾相亲的反对，率先推翻曾让他蒙受耻辱的酒吧，更带走了劳拉。阿玛迪奥痛哭流涕，谁知木头做的桌面足球队长突然活了过来。面对这群肩作战多年的老战友，阿玛迪奥似乎鼓起拯救劳拉和小镇的决心……  　　本片根据Roberto Fontanarrosa的短篇故事《一位右前锋的回忆录》改编。','There\'s only one team this summer.',22000000,24000000,14.866351,6,122,106,'2013-07-18','es','/22F3HAUI649GMaR7mlz7rWOoUT6.jpg',2.9078463000886816,3,'2026-09-10',2,NULL,NULL),(153397,'Restless','Restless','A young woman finds out that her mother worked as a spy for the British Secret Service during World War II and has been on the run ever since.',NULL,0,0,0.812776,4.9,8,180,'2012-12-07','en',NULL,2.3088083348508768,3,'2026-09-10',2,NULL,NULL),(153518,'The Angry Birds Movie','The Angry Birds Movie','An island populated entirely by happy, flightless birds or almost entirely. In this paradise, Red, a bird with a temper problem, speedy Chuck, and the volatile Bomb have always been outsiders. But when the island is visited by mysterious green piggies, it’s up to these unlikely outcasts to figure out what the pigs are up to.','Why so angry?',73000000,349779543,45.720894,5.9,1022,97,'2016-05-11','en','/avvphl1DzsOjVZqB8XbNGkINeTE.jpg',3.405915966499003,3,'2026-09-10',2,NULL,NULL),(153795,'救赎','Straight A\'s','一个改过自新的吸毒者史葛，回到他的家乡，却使得他身边每个人的生活陷入一片混乱之中。',NULL,7000000,0,4.50829,5.2,46,88,'2013-01-16','en','/92bkt0yTztGrNy44bOIHkxpkcDn.jpg',2.663866873763661,3,'2026-09-10',2,NULL,NULL),(156022,'伸冤人','The Equalizer','In The Equalizer, Denzel Washington plays McCall, a man who believes he has put his mysterious past behind him and dedicated himself to beginning a new, quiet life. But when McCall meets Teri (Chloë Grace Moretz), a young girl under the control of ultra-violent Russian gangsters, he can’t stand idly by – he has to help her. Armed with hidden skills that allow him to serve vengeance against anyone who would brutalize the helpless, McCall comes out of his self-imposed retirement and finds his desire for justice reawakened. If someone has a problem, if the odds are stacked against them, if they have nowhere else to turn, McCall will help. He is The Equalizer.','What do you see when you look at me?',55000000,192330738,79.922059,7.1,2954,132,'2014-09-24','en','/9u4yW7yPA0BQ2pv9XwiNzItwvp8.jpg',3.9892409364647587,3,'2026-09-10',2,NULL,NULL),(157058,'那部片名长得离谱的恶搞片','30 Nights of Paranormal Activity With the Devil Inside the Girl With the Dragon Tattoo','这是一部纯粹为了让你“笑出声”而存在的电影。它疯狂恶搞了《灵动：鬼影实录》、《驱魔》、《龙纹身的女孩》、《嗜血破晓》甚至《林肯律师》和《盗梦空间》。故事讲述了一个刚从精神病院出来的男人和他的家人搬进了一座闹鬼的房子，而他的女儿身上正好有个龙纹身。接下来，你会看到各种低成本但极具创意的廉价特效，以及对好莱坞大片桥段的无情嘲讽。','Based on true events... that may not have happened',0,0,1.737032,2.9,28,80,'2013-01-14','en','/xng4MvtKEj8mV2aHgc51tGZzkdN.jpg',2.5332737726004946,3,'2026-09-10',2,NULL,NULL),(157185,'Tin Can Man','Tin Can Man','Recently dumped by his girlfirend for another man, working in a job he hates, things could be better for Peter.  One night, while he is alone in his apartment, there is a knock on the door.  His life will never be the same again.','Everything You\'ve Heard is True',13,0,0.332679,2,1,84,'2007-01-01','en','/2IMSeaHnjPCYSJ2P2J8BjvbMWZ4.jpg',1.983365854764196,3,'2026-09-10',2,NULL,NULL),(157293,'人人皆舞者','एबीसीडी','《宝莱坞舞林争霸》讲述了对于印度公认的最棒舞者毗湿奴而言，舞蹈不仅仅是激情，也是他活下去的动力！所以，当他发现自己被精于世故、擅长操纵他人的合作伙伴逐出他亲手创办的舞蹈学校时，仿佛他呼吸的空气中的氧气被一丝丝抽净。心碎的毗湿奴决定放弃舞蹈，永远离开孟买这个伤心地。然而，就在他动身的前一天夜里，他看到了惊人的一幕——一群年轻的舞者在为即将到来的《冈帕蒂舞蹈对决》备战——这是孟买最棒舞蹈团队一年一度的竞赛盛事。看着这些天赋惊人的舞者，毗湿奴做出一个决定——他收这支迥然不同的团队为徒，帮他们客服个人敌对的情绪，排出他们因伤痛往事受到的干扰，使他们成为印度最棒的舞蹈队！而他自己，也将在这场舞力较量中，与老伙伴狭路相逢......','India\'s First 3D Dance movie',0,222000,1.294967,5.6,10,160,'2013-02-07','hi',NULL,2.3553541296753706,3,'2026-09-10',2,NULL,NULL),(157336,'星际穿越','Interstellar','近未来，地球环境持续恶化，枯萎病和沙尘暴让越来越多农作物消失，人类的生存前景也变得岌岌可危。曾为NASA飞行员的库珀如今与家人在农场生活，一次偶然发现的异常重力现象，却将他和女儿墨菲引向一个仍在秘密运作的NASA基地。布兰德教授告诉他，多年前土星附近出现了一处神秘虫洞，人类已经通过它寻找太阳系之外可能适合居住的新世界。为了给地球上的人类寻找延续文明的希望，库珀决定告别家人，与艾米莉亚·布兰德等人踏上一场穿越虫洞、前往遥远星系的探索之旅。然而在浩瀚宇宙中，距离与时间都将成为他们从未真正面对过的考验……','',165000000,675120017,59.086,8.487,10867,169,'2014-11-05','en','/spQm5r317XPNHK1941ChWmqzkZs.jpg',4.654390739192315,3,'2026-09-10',2,NULL,NULL),(157350,'分歧者：异类觉醒','Divergent','故事的女主角名翠丝，生活在反乌托邦背景下的芝加哥，那时的社会已经被分成了五个派系，每个派系都是纯粹的美德，每个人都将进入一个派系被培养，这五个派系是：友好、诚实、博学、无私、无畏。每年都有一个固定的日期，所有16岁的人必须在这一天选择他们余生将要奉献给的派别。对于翠丝，她更想跟家人在一起，于是她做出了一个令所有人（包括她自己在内）惊讶的选择……','What makes you different makes you dangerous.',85000000,288747895,80.316463,6.9,4663,139,'2014-03-14','en','/aNh4Q3iuPKDMPi2SL7GgOpiLukX.jpg',4.055922768640382,3,'2026-09-10',2,NULL,NULL),(157353,'超验骇客','Transcendence','威尔·卡斯特博士（约翰尼·德普 Johnny Depp 饰）是人工智能领域首屈一指的研究者，他致力于开创有史以来最人性化的有感知的机器人，全方位结合了人类情感和智慧。虽然威尔极具争议的实验令他一举成名，但同时也让他成为反科技极端分子的眼中钉，这些极端分子开始极尽一切阻止他。然而没想到的是，他们对威尔的摧毁行动，却在不经意间成为了威尔人工智能人实验成功的催化剂——成为了他“超验”的参与者。威尔的妻子伊芙琳（丽贝卡·豪尔 Rebecca Hall 饰）和他最好的朋友马克斯（保罗·贝坦尼 Paul Bettany 饰）同是这个实验的研究员，但问题不在于他们能不能……而是他们应不应该继续着这项研究。伊芙琳和马克斯最担心的是，他们逐渐察觉到，威尔已经不再是单纯的进行探索研究，而是逐步演变成追求一种权力，他无所不在，让人无法预料在他的掌控下未来的结局是什么，唯一越来越清晰的可怕事情是没有人能够阻止他。','Yesterday, Dr. Will Caster was only human...',100000000,103039258,58.991388,5.9,2295,119,'2014-04-16','en','/hZY0kqShLLcEMMezzobvKgvD400.jpg',3.600600871416134,3,'2026-09-10',2,NULL,NULL),(157354,'弗鲁特维尔车站','Fruitvale Station','本片改编自真实事件。22岁的湾区居民奥斯卡在2008年12月31日清晨醒来，莫名感到空气中的异样。虽不确定缘由，他视其为改变的契机，决意提早实践新年期许：成为母亲更称职的儿子（恰逢母亲生日就在除夕当日）、对近来未能坦诚相待的女友成为更可靠的伴侣、以及为他们四岁美丽女儿T担任更尽责的父亲。一日之初看似顺利，但随着时间推移，他逐渐意识到改变绝非易事。在与朋友、家人及陌生人的相遇交集中，每个片段都揭示出奥斯卡远比表面更为复杂的生命轨迹。然而当日终结前，他在弗鲁特维尔湾区捷运车站与警察的最后一次际遇，将彻底震撼湾区根基，并迫使整个国家共同见证奥斯卡·格兰特的故事。[韦恩斯坦影业]','Every step brings you closer to the edge',0,17385830,20.967146,7.3,390,85,'2013-07-25','en','/lfn9qqr2wOglQpVx6M4b1u9bbPV.jpg',3.3019779934919504,3,'2026-09-10',2,NULL,NULL),(157386,'好景当前','The Spectacular Now','这是一个关于萨特·基利的故事——一位魅力浑然天成的高中毕业生，以及他如何意外地爱上“乖乖女”艾米·菲尼基。这段看似不可能的恋情，成为了一幅目光锐利、直截了当的快照，定格了青春那令人晕眩的困惑与萦绕心头的激情——它并不去寻找那些简单的答案。[A24]','From the Writers of (500) Days of Summer',2500000,6854611,25.722747,6.8,1048,95,'2013-08-02','en','/obDS8pTWVWZiNAaTyfIFWYZbRsZ.jpg',3.5245834349883816,3,'2026-09-10',2,NULL,NULL),(157422,'邪恶之人','The Wicked Within','After a year passes since the sudden death of a child, a family gathering takes place whilst unexplainable events occur. Tension over peculiar circumstances cracks the veneer of cordiality and dark secrets emerge.','Every family has its demons. The truth will possess us all.',0,0,1.906151,4.2,26,91,'2015-10-16','en','/82lKQXWuPBaGA9048pHB9WsPAPO.jpg',2.5340439789078975,3,'2026-09-10',2,NULL,NULL),(157544,'梵蒂冈录像带','The Vatican Tapes','在梵蒂冈城墙内的高度保护的拱顶中，天主教会举办了数以千计的旧电影和视频录像，记录了驱魔/推定的驱魔和其他不明原因的宗教现象，他们觉得世界还没有准备好看。这是第一个磁带 - 案例83-G  - 这些档案被盗，并被匿名人士暴露给公众。','For 2,000 years the Vatican has recorded evidence of evil. May God have mercy on their souls.',13000000,1784763,10.475368,4.6,243,91,'2015-07-24','en','/eXN0zdTpm772ZCfnCeLAONguqxe.jpg',2.9378929823429,3,'2026-09-10',2,NULL,NULL),(157547,'鬼遮眼','Oculus','13岁的凯莉与10岁的提姆跟随父母搬到新家，没想到邪恶力量早已在此滋长壮大。家中陆续发生难用常理解释的诡异现象，然而两人的双亲，最终也不敌邪灵入侵命丧黄泉。这对年幼的姊弟，不仅目睹父母惨死，提姆更被指控是这桩惨剧的兇手。  经过长年调查，凯莉确信老家裡的那面古董镜藏有邪恶诅咒，歷代拥有者都不得善终，而这也是导致他们家破人亡的主要原因。於是姊弟俩重回老家，试图摧毁古董镜；岂料他们的记忆竟开始回溯，无法分辨现实与幻觉。身处记忆中惨案发生的那一夜，他们能否找到证明提姆清白的证据？或是被尘封的恐惧所吞噬？','You see what it wants you to see',5000000,44030246,35.871248,6.3,1050,104,'2013-09-08','en','/u9EEu13FVEWfhOqPyl0DNelTHk9.jpg',3.459712077166898,3,'2026-09-10',2,NULL,NULL),(157841,'少年斯派维的奇异旅行','The Young and Prodigious T.S. Spivet','T.S. Spivet是个12岁的奇才，酷爱制图学和科学图解。有一天，史密森尼博物馆打电话给他说：享有盛誉的贝尔德奖授予了他，他也被邀请去做次演讲。不为人知的是，他决定乘运货的火车穿越美国去华盛顿。但那儿没有一个人料想到他只是个小孩儿。带着一个望远镜，4个圆规，和他曾曾祖母留给他的回忆，T.S.开始了他神秘的旅程，这旅程最终将让他明白这个世界是怎么运作的……各种笔记、地图和图纸掺杂在幽默而又无法抵抗的具有想象力的故事叙述之中。',NULL,33000000,9494789,10.651202,6.7,232,105,'2013-10-16','en','/oysKliAtQ6WWcA2NQMFehYhOf06.jpg',3.0843566276023457,3,'2026-09-10',2,NULL,NULL),(157847,'乔','Joe','在密西西比的一个小镇里，十五岁的加里·琼斯生活在一个支离破碎的家庭，他有一个毫无责任感的酒鬼父亲。有一天，男孩遇到了一个有犯罪前科的男人，两人的生活都开始向暖变化，前罪犯变成了精神楷模。',NULL,4000000,2365467,22.987897,6.5,338,118,'2014-04-11','en','/zepqX8anTBY2eWFqTHioy14gPAK.jpg',3.188225731101805,3,'2026-09-10',2,NULL,NULL),(157849,'最高通缉犯','A Most Wanted Man','影片改编自《锅匠，裁缝，士兵，间谍》作者约翰·勒·卡雷的小说。故事发生在当代的德国汉堡。一名神秘男子来到当地的穆斯林社区寻求帮助。此人有着一半车臣和一半俄罗斯血统，身上受了很严重的伤。他来到这里的目的是收回他父亲的巨额不法所得。周围人都人都对他的身份表示怀疑。他究竟是一名受害者还是一名贼，抑或更糟糕的，有着极端恐怖的目的？卷入这件事的还有一名英国银行家以及一名年轻的女律师。与此同时，一名老道的德国间谍也在时刻监视着他们，试图解开神秘男子的葫芦里究竟卖的什么药。',NULL,15000000,31554855,26.708193,6.5,541,121,'2014-07-25','en','/kpgQnUyw8Q5fUoqhf3RIG0wpj6d.jpg',3.3113178856527536,3,'2026-09-10',2,NULL,NULL),(157909,'Show Me','Show Me','When two squeegee kids descend upon Sarah and her luxury sedan, the fuse is lit on a tense cat and mouse tale of captors and captives. Sarah is forced to continue her trip to an isolated cottage where the twisted trio bait and entice one another in a reckless search for truth.',NULL,0,0,0.231297,5.6,4,97,'2004-09-23','en','/eIfFa00THsuUEerMeiehvVtVGCn.jpg',2.1829558682345476,3,'2026-09-10',2,NULL,NULL),(158011,'致命呼叫','The Call','哈莉·贝瑞担任报案中心接线员，当年曾接到一个女孩的求救电话，最后却无法拯救她。事隔多年，再次接到一通报案电话，发现凶手是同一人，这回，贝瑞终于找到救赎的机会，亲自出马将凶手缉拿归案。\r 　　让人联想到类似主题电影《玩命手机》（Cellular），当年是美国队长Chris Evans的大荧幕处女作，对抗的是Jason Statham，拯救对象是Kim Basinger。\r 　　这回轮到暴风女出马，两人先后都已经成为漫画超级英雄，这年头，有哪位台面上的明星，还没当过超级英雄呢？','There are 188 million 911 calls a year. This one made it personal.',13000000,68572378,34.532418,6.6,1257,94,'2013-03-14','en','/clDSqtGtGwHJx0nVNqDKPqtAI9b.jpg',3.555073685393557,3,'2026-09-10',2,NULL,NULL),(158015,'人类清除计划','The Purge','近未来的美国，全国失业率仅为1%，犯罪率则创下史上最低纪录，暴力几乎消失无踪。美利坚合众国仿佛进入宛如天堂的美好黄金时代，而促成这完美表象的则是前所未闻的大扫荡计划。国家为了有效释放公民心底的压抑和不满情绪，特别规定每年有一天的晚上7点之后举行长达十二小时的全国性大扫荡，届时人们将走上街头，展开完全不用承担法律责任的殴斗与杀戮。在这个畸形的时代，安保系统推销员詹姆斯·桑丁（伊森·霍克 Ethan Hawke）大发其财，与妻子儿女过着养尊处优的幸福生活。又是一年大扫荡之夜到来，桑丁一家端坐固若金汤的豪华府邸，在屏幕前观赏杀戮之夜的表演。谁知这一晚，詹姆斯的儿子查理出手拯救了一名被追杀的流浪汉，桑丁一家不可避免被卷入血腥的漩涡之中…… ©豆瓣','One night a year, all crime is legal.',3000000,89328627,54.403033,6,2428,86,'2013-05-31','en','/bCIBPWV4xQwCh0JKq3McmsSCeaN.jpg',3.6247771755232256,3,'2026-09-10',2,NULL,NULL),(158150,'How to Fall in Love','How to Fall in Love','An accountant, who never quite grew out of his awkward teenage years, finds himself with a dating coach - she happens to be his high school crush as well. Thanks to his coach, he gets a pretty woman he has his sights on for some time, but realizes they are incompatible. Meanwhile, his dating lessons with his teenage crush reawaken old feelings. Not realizing the feelings are mutual, he finds himself unable to act on them due to his fear of being rejected by the one he truly loves.',NULL,4000000,0,1.923514,5.2,20,0,'2012-07-21','en','/vpZavsKDpoAyNoeXFTpVW8Q6R8A.jpg',2.4919695420560166,3,'2026-09-10',2,NULL,NULL),(158752,'逃离未来','Escape from Tomorrow','一家四口去迪士尼乐园游玩，父亲在接到老板电话后就开始变得古怪异常，他把乐园里的动画角色都想象成邪恶的坏蛋，还经历了自杀、洗脑等恐怖事件。','Bad things happen everywhere.',650,0,1.352222,4.8,87,90,'2013-10-11','en','/g3qZofBWiLauJviv27f8zpEFbki.jpg',2.767098982930128,3,'2026-09-10',2,NULL,NULL),(158852,'明日世界','Tomorrowland','二十世纪初，爱迪生、巴黎铁塔总设计师埃菲尔、“交流电之父”尼古拉·特斯拉和其他顶尖的科学家、艺术家组成了一个秘密团体，共同打造一个理想计划——明日世界，传言中，华特·迪士尼也是创办人之一，在他的遗物中有一个黑盒子，装着神秘的机关。可是这个计划却出了意外，“明日世界”也从此消失。弗兰克（乔治·克鲁尼 George Clooney 饰）少年时曾亲眼目睹“明日世界”，但意外之后便过着半隐居的生活，直到聪明的少女凯茜（布丽特·罗伯森 Britt Robertson 饰）找上门，凯茜对科学和生命都充满热情，在无意间发现了神秘的徽章，她需要弗兰克的协助，破解零星线索，找到隐藏在神秘时空里的“明日世界”，以改变人类的命运……','Imagine a world where nothing is impossible.',190000000,209154322,130.311355,6.2,2846,130,'2015-05-19','en','/kziYpr5Nfw60P0My8aj1sgCEqed.jpg',3.879507644196777,3,'2026-09-10',2,NULL,NULL),(158895,'这是马丁邦纳','This Is Martin Bonner','Two men, at opposite ends of the social spectrum, find themselves starting new lives in the same, small town and form an unlikely friendship.','Sometimes You Have to Lose Your Life in Order to Find It',0,0,0.76368,6.6,4,83,'2013-06-28','en','/mN96fbXB92XQGKLS28W7PQRhAA8.jpg',2.185810316751586,3,'2026-09-10',2,NULL,NULL),(159014,'离巨星二十英尺','20 Feet from Stardom','和声歌手生活在聚光灯外的世界。她们的声音成就了流行乐坛最负盛名的乐队，用和声衬托着台前巨星，世人却鲜知她们姓名——直到本片出现。',NULL,1000000,0,5.247956,7.4,85,89,'2013-06-14','en','/bn8ogxrmRjJXXzC9ZhgwvZke5PI.jpg',2.853377066233115,3,'2026-09-10',2,NULL,NULL),(159037,'The Square','The Square','The Square, a new film by Jehane Noujaim (Control Room; Rafea: Solar Mama), looks at the hard realities faced day-to-day by people working to build Egypt’s new democracy. Catapulting us into the action spread across 2011 and 2012, the film provides a kaleidoscopic, visceral experience of the struggle. Cairo’s Tahrir Square is the heart and soul of the film, which follows several young activists. Armed with values, determination, music, humor, an abundance of social media, and sheer obstinacy, they know that the thorny path to democracy only began with Hosni Mubarek’s fall. The life-and-death struggle between the people and the power of the state is still playing out.','What does it mean to risk your life for your ideals? How far will five revolutionaries go in defending their beliefs in the fight for their nation?',0,0,4.892203,7.8,55,88,'2013-06-07','ar','/fbhmYUTdRgnFvumVewTCLgbvYm9.jpg',2.7545896893628146,3,'2026-09-10',2,NULL,NULL),(159770,'脏货恶人帮','The Dirties','两个高中好友为了逃避无聊的校园生活，召集一帮狐朋狗友再校园里扮演劫匪，岂料，他们中德一员趁机杀掉了几个无辜的学生...',NULL,0,0,0.833937,6,42,83,'2013-10-04','en','/1oPjkd0200Nt7sdLRqp5Ot1oPxK.jpg',2.650579843114286,3,'2026-09-10',2,NULL,NULL),(159824,'精灵旅社2','Hotel Transylvania 2','人类青年乔纳森（安迪·萨姆伯格 Andy Samberg 配音）与吸血鬼梅菲丝（赛琳娜·戈麦斯 Selena Gomez 配音）婚后生下了混血儿子丹尼斯。精灵旅社也放宽了入住规则，面向人类游客开放，生意更加兴隆。吸血鬼公爵德古拉（亚当·桑德勒 Adam Sandler 配音）用尽浑身解数，只为激发孙子丹尼斯的吸血鬼潜能。德古拉的老爸弗拉德（梅尔·布鲁克斯 Mel Brooks 配音）突然造访，古板的弗拉德无法接受孙女与人类相爱，一怒之下决定毁掉旅社，精灵旅社顿时人仰马翻。就在这时，丹尼斯的身体却发生了奇妙的变化……','They\'re back to raise a little terror',80000000,473226958,61.692197,6.7,1497,89,'2015-09-21','en','/nJs21lhjOU0DBWLoHpAXt5l8k9l.jpg',3.6809932765160407,3,'2026-09-10',2,NULL,NULL),(160588,'蓝色茉莉','Blue Jasmine','纽约的名媛茉莉和她富商丈夫之间的婚姻亮起了红灯，眼见爱情面和经济面都濒临重大危机，茉莉决定搬到旧金山，住进妹妹金洁的一般公寓，重新开始过一个和以前大大不同的生活。然而，其实也非恋爱高手的茉莉老爱帮金洁的感情出主意，导致一团乱。就在此时，茉莉邂逅了一名英俊的外交官……','Blue Moon. I used to know the words. Now they\'re all a jumble.',18000000,99206215,34.694216,7,1098,98,'2013-07-25','en','/9YoyAIyMr1wBc9HuhAgmmGkGxGy.jpg',3.593572398471419,3,'2026-09-10',2,NULL,NULL),(161795,'Déjà Vu','Déjà Vu','L.A. shop owner Dana and Englishman Sean meet and fall in love at first sight, but Sean is married and Dana is to marry her business partner Alex.','Your future is set...',0,0,0.605645,8,1,117,'1998-04-22','en','/1fAIdDUVhQaqBr4lVPOeEiNPA3l.jpg',1.9864570417907377,3,'2026-09-10',2,NULL,NULL),(162396,'让我们谈谈性','The Big Swap','在这部英国电影中，艾伦（索查·布鲁克斯饰）和杰克（安东尼·埃德里奇饰）回忆起他们交换伴侣的时光，他们的言论引发了其他四对夫妇之间的伴侣交换派对。随着漫长的性爱之旅的进展，各种恐惧和焦虑浮出水面。\r 在蒙特利尔的1997年世界电影节和1997年圣塞巴斯蒂安电影节上放映。',NULL,0,0,0.627763,0,0,0,'1998-06-11','en','/yAg2bhuRaWvs3nYViIGtp6efkbF.jpg',1.83521631954609,3,'2026-09-10',2,NULL,NULL),(162903,'危机解密','The Fifth Estate','本尼迪克特·康伯巴奇饰演“维基解密”创始人朱利安·保罗·阿桑奇（Julian Paul Assange）。维基解密是一个大型文档泄露及分析网站，曾经在2010年公开了多达9.2万份的驻阿美军秘密文件而引起轩然大波。康伯巴奇将要饰演的朱利安·保罗·阿桑奇是网站的董事与发言人，曾主修过物理、数学，做过程序员和黑客。阿桑奇本人和网站一样都备受争议，他曾经因为解密工作获得过多项荣誉，也曾收到过国际刑警组织的逮捕令。2010年阿桑奇因涉嫌在瑞典强奸及性侵犯2名女性被通缉，2010年12月7日他向伦敦警方自首，随即被押送到威斯敏斯特地方法院出席引渡聆讯，保释申请被驳回。2012年8月16日，阿桑奇获厄瓜多尔政治庇护。','You can\'t expose the world\'s secrets without exposing yourself',28000000,8555008,20.267062,5.7,364,128,'2013-10-11','en','/h9qSi5dL6ovsSObflmsYAoy64ZM.jpg',3.119978235487702,3,'2026-09-10',2,NULL,NULL),(164372,'冰雪女王','Снежная королева','为了创造一个新的世界，邪恶的冰雪女王想要用寒冷的暴风雪冷冻人类的心灵，并消灭所有的艺术家和他们的子女，因为艺术家的作品可以温暖人们的心灵。\r 　　根据魔镜的预言，对冰雪女王最大的威胁来自艺术家Glazier Vegard, 冰雪女王用北风带走了Vegard和他的妻子，但是他们的孩子Gerda和Kai却被留了下来，并失落在人间。\r 　　13年后，不仅仅是大地，人心也被冷冻了起来，再也没有人创造艺术作品了，人人只顾自己的生存。冰雪女王发现了Vegard的孩子还在人间，担心他们的存在会威胁到自己，于是派出怪物Troll寻找Vegard的后代，Troll找到了男孩Kai,把他抓回了冰雪女王的宫殿，但却落下了Gerda——Vergard的女儿。为了救回Kai, Gerda历尽艰险，并在路上得到了很多新朋友的帮助，最终，她打败冰雪女王，救回了Kai, 并把温暖带回了人世间','Cold can freeze your heart, love can set you free',7000000,12400000,5.33861,5.1,47,76,'2012-10-11','ru',NULL,2.6681847330840727,3,'2026-09-10',2,NULL,NULL),(164457,'逃出熔炉','Out of the Furnace','影片讲述了贝尔饰演的主人公罗塞尔·贝兹（Russell Baze）在经历了四年牢狱被释放后，发现自己的弟弟（卡西·阿弗莱克饰）被残忍地谋杀了。为了复仇，罗塞尔踏上了追踪杀手的历程。佐伊·索尔达娜饰演罗塞尔的爱情对象，山姆·夏普德出演贝兹兄弟的叔叔。','Sometimes your battles choose you.',22000000,15400000,29.230298,6.5,720,116,'2013-12-06','en','/cOuQQ4eRpSBxb0G9OXzWE1pHPeq.jpg',3.387288363859201,3,'2026-09-10',2,NULL,NULL),(164558,'单向乐队：这就是我们','One Direction: This Is Us','继贾斯汀-比伯、凯蒂-佩瑞之后，英国当红偶像团体“单向乐队”(One Direction)也将拥有自己的3D音乐会纪录片，索尼公司今天宣布这部名为《单向乐队》(One Direction)的3D纪录电影将于2013年8月30日上映，索尼旗下三星影业(TriStar Pictures)将负责发行。','A motion picture event.',10000000,0,7.944457,8,201,92,'2013-08-28','en','/d4OdJwP9lSoWKvpHbv8wqNhkrlZ.jpg',3.1270558392660552,3,'2026-09-10',2,NULL,NULL),(165864,'Hansel and Gretel Get Baked','Hansel and Gretel Get Baked','An intense new marijuana strain named “Black Forest” is taking Los Angeles by storm, and Gretel’s stoner boyfriend can’t get enough. But when the old woman growing the popular drug (Lara Flynn Boyle) turns out to be an evil witch, cooking and eating her wasted patrons for their youth, Gretel and her brother Hansel must save him from a gruesome death — or face the last high of their lives.',NULL,4500000,0,2.503612,4.8,67,86,'2013-02-19','en','/shYb3LezqJF4P90CGgp9zoD2MjF.jpg',2.7225868486153817,3,'2026-09-10',2,NULL,NULL),(166424,'神奇四侠','Fantastic Four','四位原本过着平凡生活的年轻人，被传送到一个危机四伏的宇宙时空，四人的外貌身形都发生了巨大的变化，并拥有了强大而独特的超能力：“神奇先生”（迈尔斯·特勒 Miles Teller 饰）的身体能屈能伸，“隐形女”（凯特·玛拉 Kate Mara 饰）拥有变透明的能力，“霹雳火”（迈克尔·B·乔丹 Michael B. Jordan 饰）可以喷火飞天，“石头人”（杰米·贝尔 Jamie Bell 饰）肤如岩石无坚不摧，他们组成了“神奇四侠”。  “神奇四侠”需要学习，并善用他们的超能力，并肩作战以抵御外敌，保护即将遭敌军破坏殆尽的地球家园，意想不到的是，他们所要对抗的竟是昔日挚友……','Change is coming.',120000000,167977596,38.126095,4.4,2278,100,'2015-08-05','en','/2YDBLAWfeeERBAf06bEA7IbEbwI.jpg',3.210444403767071,3,'2026-09-10',2,NULL,NULL),(166624,'鱼味男孩','Treading Water','乍一看，米卡是个在普通不过的男孩儿。但第一眼往往带有欺骗性。比如米卡住在一个博物馆里，这个博物馆是米卡妈妈为了纪念墨西哥传奇歌手Guillermo Garibai 而开的。当妈妈为了满足日渐衰老的歌迷各地巡展时，米卡就住在这里。但更为奇怪的是米卡的气味。他身上散发着一股鱼腥的味道。无数的医生，包括他的终身私人医生，还有父母，没有人知道病因。没有人想和他做朋友。女孩子不愿和他说话。尽管他的私人医生再给他做一些治疗，但还是觉得人生没有意义，直到一个叫劳拉的女孩子走进他的生命。','Mica is a perfectly normal boy. Well he would be if he didn\'t smell of fish.',4700000,0,0.217538,5.6,6,92,'2013-09-13','en','/zFY2dXaZ9SBI1x9lZkDKG0rECOt.jpg',2.255571964857339,3,'2026-09-10',2,NULL,NULL),(167073,'布鲁克林','Brooklyn','艾莉丝·莱西是一位年轻的爱尔兰移民，在20世纪50年代的布鲁克林摸索着新生活的方向。受美国梦的感召，艾莉丝离开爱尔兰与母亲温馨的家，远赴纽约。初时的思乡之苦很快被一段崭新的恋情冲淡，她沉浸于令人沉醉的爱之芬芳中。然而过往悄然袭来，打破她新生的朝气，迫使她在两个国度、两种人生之间做出抉择。[福克斯探照灯影业]','Two countries, two loves, one heart',11000000,62076141,39.337949,7.2,1213,111,'2015-10-20','en','/xkHTy5lNVC9HpZ7ZDl2cDgecCcB.jpg',3.6695671531815783,3,'2026-09-10',2,NULL,NULL),(168027,'疯狂玩弹家','Freaky Deaky','Set in 1974, a pair of \'60s radicals rely on their bomb-making skills on their way to becoming capitalists.','Crime is such a trippy thing',0,0,4.448353,4.9,18,90,'2012-04-22','en','/1rMr42ppp05ikGgoJf1efx0ouJZ.jpg',2.4745475693297916,3,'2026-09-10',2,NULL,NULL),(168259,'速度与激情7','Furious 7','经历了紧张刺激的伦敦大战，多米尼克·托莱多（范·迪塞尔 Vin Diesel 饰）和他的伙伴们重新回归平静的生活，但是江湖的恩恩怨怨却决不允许他们轻易抽身而去。棘手的死对头欧文·肖瘫在医院，不得动弹，他的哥哥戴克·肖（杰森·斯坦森 Jason Stantham 饰）则发誓要为弟弟复仇。戴克曾是英国特种部队的王牌杀手，不仅身怀绝技，而且心狠手辣。他干掉了远在东京的韩，还几乎把探长卢克·霍布斯（道恩·强森 Dwayne Johnson 饰）送到另一个世界，甚至多米尼克那世外桃源般的家也被对方炸毁。复仇的利刃已经架在脖子上，多米尼克再也没有选择，他找到长久以来最为信赖的团队，与来势汹汹的戴克展开生死对决……','Vengeance Hits Home',190000000,1506249360,102.322217,7.3,4176,137,'2015-04-01','en','/ktofZ9Htrjiy0P6LEowsDaxd3Ri.jpg',4.181249105800055,3,'2026-09-10',2,NULL,NULL),(168530,'佐州自救兄弟','Ride Along','影片主角为一个吊儿郎当的警察，他企图破坏他妹妹和一个精神病医生的婚约，想尽办法让妹妹的未婚夫出丑。','Propose to this cop\'s sister? Rookie mistake.',25000000,153997819,28.468,6.1,853,99,'2014-01-07','en','/qrt65VVaP5DEEBZgB5XYctA82Qv.jpg',3.362497672352228,3,'2026-09-10',2,NULL,NULL),(168672,'美国骗局','American Hustle','本片以轰动全美的惊天丑闻为背景，虚构出一段充满诱惑的迷离故事。骗子高手欧文·罗森菲尔德与搭档西德尼·普罗斯美艳狡黠，两人被迫为行事狂放的联邦调查局探员里奇·迪马索效力。迪马索将这对搭档卷入新泽西权谋者与黑手党交织的险恶世界，那里危机四伏却又令人迷醉。在这场骗子与联邦探员的角力中，身处风暴中心的是新泽西激情善变的政坛操盘手卡明·波利托。然而最终扯断引线、让整个骗局崩塌的，却可能是欧文那位难以捉摸的妻子罗莎琳。[索尼影业]','Everyone Hustles To Survive',40000000,251171807,49.664128,6.8,2807,138,'2013-12-12','en','/z6O1KDhfWDTm5ZBr6Ovr0eg8LqO.jpg',3.835152681459228,3,'2026-09-10',2,NULL,NULL),(168705,'吸血莱恩','BloodRayne','故事发生在遥远的1723年，那是吸血鬼与人类共存的时代，身为吸血鬼之王，卡甘（本·金斯利 Ben Kingsley 饰）凭借自己强大的力量和邪恶的本性将人类尽数驱赶，那些还未沦为吸血鬼们盘中餐的人类，只能如同蝼蚁一般躲藏在硫磺城之中。即便是在这样一个黑暗的时代，依然有勇士为了自由和光明勇敢的斗争着，他们是名叫“地狱之火”的团体。为了得到更强大的力量，卡甘决定寻找吸血鬼祖先留下的法宝，这也意味着，一旦卡甘得手，人类的末日将真正来临，而在传说中，有一个名为莱恩（克里斯塔娜·洛肯 Kristanna Loken 饰）的神秘女人，她是唯一一个知道除掉卡甘方法的存在。','Revenge never tasted so sweet.',25000000,2405420,7.008216,3.5,118,95,'2005-10-22','en','/1Xy9uu5INNMnyF7W6BTEQkkGOZC.jpg',2.7782977034316696,3,'2026-09-10',2,NULL,NULL),(169917,'行过死荫之地','A Walk Among the Tombstones','影片改编自劳伦斯·布洛克1992年出版的同名犯罪小说，尼森饰演的马修·斯卡德（Matthew Scudder）曾是一位纽约警察，如今则是无证行业的私家侦探。纽约发生了一系列针对毒贩妻子的绑架案，受害人均惨遭杀害。斯卡德答应了其中一人（丹·史蒂文斯），以及自己弟弟的要求，在前任同事及一名17岁的街头艺术家帮助下，找出幕后的两名凶手。','Some people are afraid of all the wrong things',28000000,53181600,61.309619,6.2,1131,113,'2014-09-18','en','/euPgyPsiNFp6gOBB7nUFxvN5ZaY.jpg',3.5166957181231746,3,'2026-09-10',2,NULL,NULL),(170480,'The Deported','The Deported','An Italian-American actor is deported to Mexico by some crooked INS Agents, and a pack of orphans helps him find his way back to America',NULL,0,0,0.194848,0,0,90,'2010-06-15','en','/42KLDWL2zRXzv6QH1vwBlELGMOs.jpg',1.8342274564958447,3,'2026-09-10',2,NULL,NULL),(170687,'盒子怪','The Boxtrolls','《盒子怪》根据阿兰·斯诺（Alan Snow）的小说《这里有怪兽》（Here Be Monsters）改编，是一个幽默的寓言故事。“奶酪桥”（Cheesebridge）是维多利亚时期一个光鲜亮丽的城市，这里的居民痴迷于财富、等级，还有臭奶酪！然而在他们别致的鹅卵石道路之下住着一群“可怕”的怪物，他们每天晚上都会从下水道爬出来，偷走居民家中的孩子和奶酪——当然，这只是当地居民的一面之词！事实上“盒子怪”是一群非常可爱害羞的生物，他们躲在可回收的纸板箱里，就像乌龟喜欢缩在自己的壳里一样。盒子怪们收养了一个人类孤儿，给他起名“蛋生”（Eggs），这个小男孩和一个爱冒险的地上世界的女孩温妮（Winnie）成为了好朋友，他们需要在盒子怪与人类之间架起一座桥梁——尤其是当人类政客为了选票而把盒子怪们描绘成一群可怕怪物，进而煽动民众驱逐他们的时候……','When troubles strikes friends stack together',60000000,108255770,30.656345,6.6,668,97,'2014-09-10','en','/iIz6i84y1PmykOzsLMu9MdxirBg.jpg',3.386465600246914,3,'2026-09-10',2,NULL,NULL),(171274,'性本恶','Inherent Vice','当私家侦探多克·斯波特洛的前女友突然不知从哪儿冒出来，跟他讲了一个关于她现任男友——一位她恰好爱着的亿万富翁土地开发商——以及他妻子和她男友密谋绑架这位富翁并把他送进疯人院的故事……好吧，她说起来倒轻松。那是在迷幻的60年代末期，偏执狂横行，多克知道“爱”是当下另一个被过度滥用的词，就像“旅行”或“绝妙”一样——只是这个词通常都会惹来麻烦。','Under the paving stones, the beach!',20000000,11110975,45.742217,6.5,833,148,'2014-12-25','en','/lmuoirZjwHHSrVfBJh0bZjmTXGm.jpg',3.460850013181728,3,'2026-09-10',2,NULL,NULL),(171424,'The Green Inferno','The Green Inferno','A group of student activists travel from New York City to the Amazon to save the rainforest.  However, once they arrive in this vast green landscape, they soon discover that they are not alone… and that no good deed goes unpunished.','Fear will eat you alive.',5000000,6833445,17.845161,5,349,100,'2014-09-04','en','/nTavMI3yVTWqSSdPDPOkXAS4oEl.jpg',3.0384598631418127,3,'2026-09-10',2,NULL,NULL),(171759,'遗失的徽章：比利·斯通历险记','The Lost Medallion: The Adventures of Billy Stone','考古学家迈克尔斯通博士寻找丢失的奖章，他的整个生命，而现在他的儿子比利已采取了搜索。令人惊讶的是，大奖章在比利的手中结束了，在一个不稳定的情况下需要一个自发的愿望比利和他最好的朋友艾莉，200年前他们意识到什么是一个非常不同的Aumakua岛。当比利和他的朋友们不跳下瀑布，避免动物陷阱，穿越海洋，偷偷通过洞穴或逃离监狱，他们面对的是他们的克星眼镜蛇，谁想要什么比他们都消失。由于没有其他的方式来获得回家，搁在他的肩膀整个岛屿的福祉，比利必须发现收回奖章和它的巨大威力的关键。这种或那种方式，将改变这种冒险比利，并在岛上的生活，直到永远。','Finding it is only the beginning.',0,0,2.952932,5.6,13,97,'2013-03-01','en','/tDPwBwGAERB4B1yQjR0xwTWwbFQ.jpg',2.4108951104178824,3,'2026-09-10',2,NULL,NULL),(172385,'里约大冒险2','Rio 2','在第二集中，《里约大冒险》主角们在续集全部回归，这一集中布鲁和珠儿有了三个可爱的宝宝，在里约过着完美的家庭生活，但珠儿决定孩子们应该要回到丛林，学习如何去过身为一只鸟应有的生活，坚持全家进入亚马逊丛林，展开一场更欢乐、更刺激、更多音乐及乐趣的狂欢冒险。','He\'s villainous, she\'s venomous.',103000000,500188435,42.40024,6.3,978,102,'2014-03-19','en','/qldWHOAHx9kKzMViDjL7VGPwIDz.jpg',3.4582440122923637,3,'2026-09-10',2,NULL,NULL),(172391,'斑马总动员','Khumba','卡鲁草原上，在一疯狂崇拜花纹的斑马里，他们愚昧又迷信。一只可爱的小斑马出生了，可惜它身上只有一半的花纹。一时间谣言四起，说这是可怕的诅咒。不久之后，一场大旱降临，小斑马库姆巴被当成罪魁祸首。甚至它的父亲，整个族群的首领，也把雨水稀少和它母亲的死亡怪罪在库姆巴的头上。伤心欲绝的库姆巴离开了家园。他跨过藩篱，迈入了豹子潘哥的领地。潘哥掌管着所有水井，卡鲁的动物听到它的名字都闻风丧胆。库姆巴与一只野狗狭路相逢，遭遇生命危险，但它被一对奇怪的组合：一只羚羊和一只鸵鸟拯救了下来。妈妈V是一直与众不同的母羚羊，她可不想呆在家做个家庭主妇。让人哭笑不得是，她的孩子是一只继夸张又缺乏安全感的鸵鸟，有着杂乱不堪的羽毛。在他俩的帮助之下，库姆巴踏上了一条寻找自我的旅程。','Half a zebra, a whole lot of adventure!',20000000,27187375,6.459787,5.8,72,85,'2013-07-18','en','/bG32hRPM9LguHXj2tbyeILJisOK.jpg',2.771763363646426,3,'2026-09-10',2,NULL,NULL),(172533,'Drinking Buddies','Drinking Buddies','Weekend trips, office parties, late night conversations, drinking on the job, marriage pressure, biological clocks, holding eye contact a second too long… you know what makes the line between “friends” and “more than friends” really blurry? Beer.','A comedy about knowing when to say when.',0,343341,17.378455,6,356,90,'2013-08-23','en','/iunbsMWtkwfrtRzU7hdCHhPjjJf.jpg',3.1387221233701186,3,'2026-09-10',2,NULL,NULL),(173224,'一路同行','Along the Roadside','瓦恩是生活在城市里的白领，每日面临各种的压力，他的妻子西拉很希望他们有个孩子，而瓦恩觉的很有压力，一次争吵之后，他离家出走。内纳是一个音乐发烧友，她的理想是到洛杉矶看“金发牧师”的表演。瓦恩和内纳认识了，他们都要去洛杉矶，自然成了同路人，瓦恩也成了内纳的司机，他们开着破破的车就出发了。一路上他们经历了许多有趣的人和事，他们一同到朋友的家里看画展，愉快的聊天分享人生的美好经历。他们遇到了可爱的警察，原本很严肃的警察也成了他们的同行者，在一辆车上一路上音乐、聊天。经历了沿途的种种人，他们来到了音乐流浪者聚集的地方，内纳很喜欢这里，她热爱音乐，想要留下来。瓦恩依依不舍的与她告别，他们一路上也埋下了友谊。',NULL,250,0,0.166655,7.7,3,118,'2013-02-28','en','/bI3dchK7VTdOuFQ418bgIQ2dp15.jpg',2.137146285288031,3,'2026-09-10',2,NULL,NULL),(173931,'兔侠传奇','兔侠传奇','剧情简介  皓月当空，诗情画意，一派美景背后却是江湖凶险。武林老盟主（濮存昕 配音）遭江湖败类熊天霸（张丰毅 配音）暗算，身染剧毒，命在旦夕。在危机时刻，老盟主得到卖炸糕的小贩兔二（范伟 配音）的救助，自知不久于人世的老盟主将毕生绝学传给兔二，嘱他前往京城虎啸武馆，将代表江湖至尊的令牌交给其女儿牡丹（闫妮 配音）。\r 　　兔二信守诺言，忍受艰险一路来至虎啸武馆，此时熊天霸早已自立为武林盟主，霸占武馆，兔儿则稀里糊涂成为武馆厨房的杂役。另一方面，毫不知情的牡丹也和老盟主的徒弟两米（张一山 配音）返回京城，等待他们的将是一场震动江湖的正邪之战……','From zero to hero.',19000000,2570000,0.738652,3,3,89,'2011-01-01','zh','/1uEDPgJfuYb6J1IAocdQTPwWbJF.jpg',2.1326696501476596,3,'2026-09-10',2,NULL,NULL),(174311,'All Is Bright','All Is Bright','Two French Canadian ne’er-do-wells travel to New York City with a scheme to a get rich quick selling Christmas trees. Easygoing charmer Rene (Paul Rudd) clashes with misanthropic ex-con Dennis (Paul Giamatti), whose wife Rene just stole. Still, this odd couple must make an honest go of it in this fresh buddy comedy co-starring Sally Hawkins, by the director of the indie breakout hit Junebug.','All is busted. All is broke. All is bitter. All is BRIGHT.',0,0,3.613577,5.3,36,107,'2013-09-10','en','/spCLVHZnOCcjrGwCEaVi8ADKRsn.jpg',2.6146567075045817,3,'2026-09-10',2,NULL,NULL),(174362,'Bending Steel','Bending Steel','The Cyclone, The Freakshow, The Mermaid Parade: all Coney Island icons. But Chris “Wonder” Schoeck has always preferred the Coney Island Strongman. Bending Steel follows the sweet, unassuming Schoeck as he parlays his extraordinary strength into the pursuit of his lifelong dream. Training with an elite group of men whose hands bend, drag, twist and shred metal, he tackles an enormous physical and mental challenge, taking a surprisingly emotional journey as a result.','The Limiting Factor Is The Mind',0,0,0.048726,5,1,93,'2013-04-20','en','/naepnR4XLlMz2NkT6bf10xdPnNo.jpg',1.9839510897188746,3,'2026-09-10',2,NULL,NULL),(174751,'拿起枪的简','Jane Got a Gun','讲述女主角的丈夫有一天带着枪伤回到家中，女主角为保护丈夫不被人追杀，不得不求助于前男友帮助的故事。',NULL,25000000,1397284,15.333575,5.4,285,98,'2016-01-01','en','/oCsAz0OYggjdL9bVrQKFi8lrKIN.jpg',3.0368697662585737,3,'2026-09-10',2,NULL,NULL),(175291,'绝命赌局','Cheap Thrills','落魄男克雷格深陷重重债务，和三五好友借酒消愁。酒性大发之际，为还债务答应参加朋友的打赌。于是，一而再，再而三地犯下种种不可挽回的弥天大错。为了钱，他真的豁出去了。但有了钱，他还能回归以往的平静生活么。','Get ready for the night of your life',0,0,10.826253,6.3,155,85,'2013-03-08','en','/mnOifypguJ1gVU971KCjnmek043.jpg',2.964937493467531,3,'2026-09-10',2,NULL,NULL),(175528,'Baggage Claim','Baggage Claim','Pledging to keep herself from being the oldest and the only woman in her entire family never to wed, Montana embarks on a thirty-day, thirty-thousand-mile expedition to charm a potential suitor into becoming her fiancé.','She\'s done flying solo.',8500000,22456509,11.436405,5.6,85,96,'2013-09-27','en','/qSKvf23QuEJGt8MMrKvoFk85TZo.jpg',2.811085008037485,3,'2026-09-10',2,NULL,NULL),(175541,'Black Nativity','Black Nativity','A street-wise teen from Baltimore who has been raised by a single mother travels to New York City to spend the Christmas holiday with his estranged relatives, where he embarks on a surprising and inspirational journey.','The Musical Event of the Holiday Season',17500000,7018189,7.180403,5.8,16,93,'2013-11-27','en','/dIOk8uCYZMP69D6WhiRCZAGX9kE.jpg',2.463392639937915,3,'2026-09-10',2,NULL,NULL),(175555,'黑疯婆娘的圣诞节','A Madea Christmas','Madea dispenses her unique form of holiday spirit on rural town when she\'s coaxed into helping a friend pay her daughter a surprise visit in the country for Christmas.','This Little Fool Thinks She\'s Getting A Damn Pony',0,0,5.377155,7,35,100,'2013-12-13','en','/tbwm8GptynNoxbkC5AhjYMYfnn7.jpg',2.636421048739085,3,'2026-09-10',2,NULL,NULL),(175574,'火鸡总动员','Free Birds','两只火鸡乘坐时间机器回到了第一个感恩节，试图阻止人们拿火鸡来做节日大餐。','Hang On To Your Nuggets',55000000,110000000,14.414937,5.7,254,91,'2013-10-30','en','/ikD6X4CTKT4PtXJsxyoKIFmxFY3.jpg',3.037976021630833,3,'2026-09-10',2,NULL,NULL),(176074,'Reality Show','Reality Show','The Warwick family are unknowingly being filmed for a new reality show. Problem is, they\'re boring. So the producer must add conflict and drama to their lives. Their lives begin to unravel with shocking consequences.',NULL,0,0,0.472123,5.5,2,92,'2015-01-01','en',NULL,2.072918217809515,3,'2026-09-10',2,NULL,NULL),(176077,'危思禁入','Enter the Dangerous Mind','A psychological thriller set in the world of underground dubstep, Snap is the story of Jim Whitman, a brilliant but painfully introverted musician who develops a crush on a young social worker.',NULL,0,0,1.998826,4.8,14,88,'2013-03-11','en','/jzoozJFGbMxpjGli5moZuBfbzKS.jpg',2.4189681774312,3,'2026-09-10',2,NULL,NULL),(176124,'本垒打','Home Run','一位职业棒球选手由于滥用药物问题被迫回到故乡戒毒，当他认真面对自己的错误过往，他重拾热爱的棒球，当起教练领导一支小联盟队伍重新开始。','Freedom is possible',1200000,2861020,3.085411,6.3,24,114,'2013-04-19','en','/687pD1t23ptW7mxhA34ASLEaFrE.jpg',2.5415932284894773,3,'2026-09-10',2,NULL,NULL),(177572,'超能陆战队','Big Hero 6','热爱发明创造的天才少年小宏生活在未来都市旧京山，在哥哥泰迪的鼓励下参加了罗伯特·卡拉汉教授主持的理工学院入学展示会。他凭借自己发明的微型磁力机器人赢得众人认可，然而一场突如其来的大火却彻底改变了他的生活，泰迪也在火灾中不幸丧生。深受打击的小宏从此闭门不出，哥哥生前留下的医疗机器人大白成为陪伴他的伙伴。原以为微型机器人已经毁于火灾的小宏，却意外发现有人正在一座废弃工厂中大量生产他的发明。为了查明背后的真相，小宏与大白展开调查，泰迪生前的好友弗雷德等人也加入其中。经过小宏的改造，一群年轻人化身超级英雄，共同面对隐藏在事件背后的神秘对手……','From the creators of Wreck-it Ralph and Frozen',165000000,652105443,203.73459,7.8,6135,102,'2014-10-24','en','/2mxS4wUimwlLmI1xp6QW6NSU361.jpg',4.645586624769239,3,'2026-09-10',2,NULL,NULL),(177677,'碟中谍5：神秘国度','Mission: Impossible - Rogue Nation','资深特工伊森·亨特也有百密一疏时刻，他在接收最新任务时遭到神秘组织“辛迪加”的暗算落入对方手中。辛迪加是一支由全球各地前特工组成的秘密组织，此前一直被CIA视为空穴来风。在对方成员伊尔莎·福斯特的帮助下，伊森逃出生天，并及时向威廉·布莱德汇报了辛迪加确切存在的消息。然而此时布莱德的日子并不好过，他负责的IMF机构因俄罗斯核弹头等事件遭到CIA指控并责令解散。在得知该组织密谋刺杀奥地利总统时，伊森联系上了老搭档班吉·邓恩展开行动，并于谜样女郎伊莎再度相会。接下来的一连串事件中，辛迪加的真面目逐渐揭开，而他们也终于显露出真实的目的……','Desperate Times. Desperate Measures.',150000000,682330139,114.522237,7.1,3224,131,'2015-07-23','en','/fRJLXQBHK2wyznK5yZbO7vmsuVK.jpg',4.091263468882797,3,'2026-09-10',2,NULL,NULL),(178862,'唤醒','Aroused','导演黛博拉·安德森 (Deborah Anderson) 对16 位成人电影明星进行了深入的采访。这些明星与导演坦诚相对，讲述了她们个人的生活故事，从他们为什么选择性行业到他们最初是如何进入这个行业的。这些色情明星过去一直对他们的私生活保持谨慎，但安德森有一种打开对话的方式，让他们在屏幕上分享的不仅仅是他们的裸露皮肤。他们真正的内心脆弱是动人的，但他们塑造的角色却是自信而令人陶醉的。一旦你听到他们的故事，你就再也不会以同样的方式看待他们了。','16 porn stars reveal more than just their naked skin.',0,0,2.557258,7.2,11,73,'2013-02-20','en','/dsaqRUvGpkSoLmDKuTMys4j8GQI.jpg',2.3840672051838867,3,'2026-09-10',2,NULL,NULL),(179144,'绝美之城','La grande bellezza','数十年来，记者杰普·甘巴尔代拉游走于罗马璀璨的夜生活，凭借魅力与手腕处处逢源。自从他唯一的小说取得传奇成功后，他便成了这座城市文学与精英社交圈永久的焦点。然而在六十五岁生日之际，杰普意外开始审视自己的人生，将犀利的机锋转向自己和同代人，越过奢华的夜店、派对与咖啡馆，去探寻罗马本身恢弘壮丽的本质：一片永恒而荒诞又绝美的风景。凭借感性的摄影、华丽的配乐，以及伟大演员托尼·瑟维洛的获奖表演，意大利杰出导演保罗·索伦蒂诺打造的这部令人身临其境的电影，是一个关于颓废与逝去爱情的、令人屏息的费里尼式故事。[标准收藏]',NULL,12400000,8371085,32.523573,7.3,720,142,'2013-05-21','it','/hEYM9xpCxfmTgC6d9190kZsbXMc.jpg',3.514112409570151,3,'2026-09-10',2,NULL,NULL),(180296,'不是冤家不聚头','They Came Together','这部作品由保罗·路德和艾米·波勒领衔主演，他们饰演一对彼此看不顺眼的男女，其中路德的公司更是试图挤垮波勒的蜡烛商店。','He came...She came...They both came',0,0,12.036888,5.3,171,84,'2014-06-27','en','/ifvKTtvmPYOGed2hP9ogPq98In7.jpg',2.9326932421067173,3,'2026-09-10',2,NULL,NULL),(180383,'Deceptive Practice: The Mysteries and Mentors of Ricky Jay','Deceptive Practice: The Mysteries and Mentors of Ricky Jay','The life and career of renowned magician and sleight of hand artist Ricky Jay.',NULL,500000,0,0.425195,7.1,17,88,'2012-10-04','en','/ug2OCvSvGqId1nT9SKBe9FUjspx.jpg',2.4691452925192947,3,'2026-09-10',2,NULL,NULL),(181283,'44号孩子','Child 44','故事发生在斯大林时代的前苏联，男主角Leo Demidov是一名苏联国家安全部(MGB)的特工，他尽忠职守、热爱自己的国家，充满理想主义。作为一名战斗英雄，Leo享受国家给予的特别待遇，不仅他自己一家住在莫斯科的豪宅区，他的父母也分到了很好的公寓。尽管也秘密逮捕和刑讯逼供，但Leo认为这都是为了国家利益。不过一桩儿童系列凶杀案改变了Leo的生活轨迹，ZF不愿承认凶案的事实，一心想捉到凶手的Leo成为ZF猜疑的目标，只有他的妻子始终站在他这一边……','How do you find a killer who doesn’t exist?',50000000,3324330,40.371098,6.1,547,137,'2015-03-15','en','/xe1qy5zAFpTTnzjvHFpxB181YPL.jpg',3.293766026832241,3,'2026-09-10',2,NULL,NULL),(181330,'凯文·哈特：听我解释','Kevin Hart: Let Me Explain','美国喜剧演员凯文·哈特用他最新的演唱会电影带我们进入他2012年整年全球巡演的故事。这对凯文的粉丝来说是种新的戏剧体验，粉丝们可以看到凯文10个国家，80个城市，收益超过3200万美元的巡回演出的幕后。','Witness the rise of a legend',0,32230907,9.799357,7.1,95,74,'2013-07-03','en','/lzYQkVuEN0zw2JvJsMUsOU47nb4.jpg',2.881476589017815,3,'2026-09-10',2,NULL,NULL),(181533,'博物馆奇妙夜3：墓葬秘密','Night at the Museum: Secret of the Tomb','担任博物馆守卫的赖瑞（本·斯蒂勒饰），这次要带着他的博物馆老古董伙伴们改走国际化路线，在前两集中那块能让整个博物馆古物复活的神奇“复活黄金碑”正逐渐消失法力，赖瑞的小伙伴们即将面临再也无法复活的命运。为了抢救这块“复活黄金碑”，赖瑞与他的馆藏好友们必须踏出美国，前往伦敦大英博物馆求助法老王阿卡曼拉的父亲以解开这个谜团，并抢在黄金碑的神秘力量消逝前达成任务，但这趟冒险旅途却也意外地唤醒了更多古物，这些老古董远赴重洋来到英国街头，究竟会与地头蛇们闹出什么笑话？刺激惊险的旅程又会碰上什么难题？','One Final Night to Save the Day.',127000000,349424282,115.597753,6.1,1851,97,'2014-12-17','en','/xwgy305K6qDs3D20xUO4OZu1HPY.jpg',3.728936651177907,3,'2026-09-10',2,NULL,NULL),(181940,'Carousel of Revenge','Arnolds Park','When strangers Frank Delano and his Uncle Bobby purchase the local amusement park of a \"peaceful\" resort town they stir up guilt and suspicion among the locals over a murder and suicide the town would rather forget.',NULL,0,0,0.006069,0,0,103,'2007-07-20','en','/7E5dd2evQgkqZ2JIY0hrkhYfFGX.jpg',1.833796248111376,3,'2026-09-10',2,NULL,NULL),(182291,'On The Downlow','On The Downlow','Isaac and Angel are two young Latinos involved in a south side Chicago gang. They have a secret in a world where secrets are forbidden.','Two gangs. One secret. One crossroad.',0,0,0.029757,6,2,90,'2004-04-11','en','/s0NBfjLiE4Six0IQn94zdhuG2fG.jpg',2.072318483578329,3,'2026-09-10',2,NULL,NULL),(182873,'足球流氓3','Green Street Hooligans: Underground','该剧系列的第三部聚焦于英国足球流氓的暴力世界。14年前，丹尼·哈维（斯科特·阿德金斯饰）背弃了绿街精英，将精力投入到混合武术中，当他的弟弟乔伊（比利·库克饰）在一场似乎是事先计划好的战斗中被杀时，他的世界被粉碎了。由于没有线索，丹尼决心寻找真相，他被迫重新进入有组织的足球流氓世界，以查明杀害他兄弟的凶手的身份，并以他唯一知道的方式进行报复。',NULL,0,0,5.0005,5.4,33,90,'2013-01-01','en','/jtlDK3r8G282Vi0cGMxLVJJkhke.jpg',2.601678751487995,3,'2026-09-10',2,NULL,NULL),(183894,'Emma','Emma','Emma Woodhouse seems to be perfectly content, a loving father whom she cares for, friends, and a home. But Emma has a terrible habit - matchmaking. She cannot resist finding suitors for her friends, most of all Harriet Smith. Emma is desperate for Harriet to find happiness, but every suitor she finds for her friend ends up attracted to Emma herself. But is Emma so focused on Harriet\'s happiness that she is not considering her own happiness in love?',NULL,0,0,2.135689,7.6,38,240,'2009-10-11','en',NULL,2.656316714456248,3,'2026-09-10',2,NULL,NULL),(184098,'像男人一样思考2','Think Like a Man Too','所有的情侣都为了坎迪斯（雷吉娜-赫尔 饰演）和迈克尔（特伦斯-詹金斯 饰演）的婚礼聚集在拉斯维加斯。女孩们和男孩们的单身派对都陷入了大麻烦。本来计划好的浪漫周末因为几对情侣不同的问题面临崩溃的边缘。伴随着乌龙事件发生的是情侣们关系的裂痕：玛雅（梅根-古德 饰演）和泽克（罗曼尼-马尔可 饰演）一直相处的很好，不过泽克不堪回首的过去一直试图抬头破坏这一切。多米尼克和劳伦的关系向来很稳定，但他们都将面临各自的挑战。身为伴郎的塞德里克经历着又一次离婚，而他也是最差劲的伴郎，甚至威胁到了婚礼的正常进行。杰瑞米和克莉丝汀结婚了，这让他们面临着新的难题…',NULL,24000000,70181428,15.237142,6.4,225,105,'2014-06-20','en','/yKI9Nof9MH3dNHM469hEfCjCbjJ.jpg',3.065987727380469,3,'2026-09-10',2,NULL,NULL),(184315,'宙斯之子：赫拉克勒斯','Hercules','赫拉克勒斯是天神宙斯与底比斯王后所生的儿子。半人半神的他，自幼在凡尘中成长，饱受人世间的各种磨难。在误杀家人并完成十二件赎罪苦差之后，身心疲惫的他背弃诸神，以血腥残酷的战争麻醉自己。六名与他有相似经历的战友，全视战争及死亡为乐事。他们从不问为何征战，亦不会问要杀的是什么人；只在乎有多少奖金。这群悍将，受色雷斯国王邀请，要为他训练出史上最强的军队，与另一暴君作战。在重赏之下，他们欣然受命；但透过训练新军，他们终觉悟到自己罪孽深重，因此决定踏上充满荆棘的救赎之路……','Before he was a legend, he was a man.',100000000,243400000,76.842247,5.6,1680,99,'2014-07-23','en','/8lUJOrinH9TSpNi951byy1GdWYq.jpg',3.514818191467568,3,'2026-09-10',2,NULL,NULL),(184341,'顽石之拳','Hands of Stone','委内瑞拉男星埃德加·拉米雷斯在片中出演著名的巴拿马拳手罗伯特·杜兰，而罗伯特德尼罗饰演他的训练师，同样很有名气的雷·阿赛尔。  　　上个世纪70年代，杜兰是拳击界最可怕的人物。野性的眼神、黑色的头发、凶恶的战斗作风，使得杜兰在轻量级比赛中是个让对方感到恐怖的人物。从1972 年到1979年，杜兰在拳坛上势不可挡。他在至少三个级别的比赛中获得过冠军。这位巴拿马拳手是世界上唯一一位跨越五个不同十年还在战斗的拳手。杜兰2002年退休时已经51岁了。本片围绕杜兰与另外一位著名拳手舒格·雷·伦纳德（Sugar Ray Leonard）的一场传奇之战展开。1980年11月25日，这两位拳手在路易斯安那州第二次相逢，而在此7个月前两人的第一次比赛中，杜兰险胜伦纳德，尽管那场比赛很悬，但是场外裁判一致判定杜兰胜出。在第二场对峙中，本来结局会大不一样，但是杜兰在第八轮比赛中..','No más. No surrender.',20000000,0,7.444189,6.1,109,105,'2016-08-26','en','/y7wjsefRtasJM73TCztdAu4LVF5.jpg',2.8709904049109864,3,'2026-09-10',2,NULL,NULL),(184345,'鬼屋大电影2','A Haunted House 2','恶搞近年来的伪纪录恐怖片如《鬼影实录》系列《最后一次驱魔》《心中的恶魔》等影片。与《鬼影实录》同样采用伪纪录片风格的拍摄方式，剧情更是基本复制了《鬼影实录》：一对年轻夫妇搬进新家，谁知这竟是一间凶宅，妻子遭遇鬼附身，男主人（马龙·韦恩斯 饰）于是请来各路神仙驱魔，试图 挽救自己的幸福生活，或者说“性”福生活。影片其实并非仅仅恶搞了《鬼影实录》，前年北美大卖的另一部伪纪录恐怖片《驱魔》也未能幸免 马尔科姆和姬莎是一对年轻的新婚夫妻，他们刚刚搬到了一栋新的房子里，这栋房子是他们梦寐以求的，宽敞、舒适。但是事情却没有他们想的那么简单。','It\'ll scare the #2 out of you.',0,0,18.428909,5.4,346,87,'2014-04-17','en','/kvV7QChGdkBxCYE5jeeJzHzI3lR.jpg',3.0771977999104148,3,'2026-09-10',2,NULL,NULL),(184346,'驱魔警探','Deliver Us from Evil','纽约市发生了一系列令人不安的神秘事件，纽约警探拉尔夫与一位学过驱魔的牧师结盟，通过驱魔等手段共同调查这些超自然的案件。  一系列超自然犯罪困扰着纽约。该向谁求助呢？一个纽约警察(艾瑞克·巴纳 饰)和一个学过驱魔的牧师(埃德加·拉米雷兹 饰)怎么样?本片改编自警官拉夫·萨阿齐(Ralph Sarchie)经历的真实案件。  自一连串骇人又匪夷所思的凶杀案发生后，纽约市人心惶惶，恐慌蔓延整个城市。警官拉尔夫(艾瑞克·巴纳 饰) 虽然有自身的烦恼，仍决定亲自调查这些接踵而来、无法解释的凶杀案。自问是无神论者的他，面对神父门多扎(埃德加·拉米雷兹 饰)的邪灵附体之说只觉得故弄玄虚，然而随着调查时灵异事件不断的发生，更令拉尔夫妻女陷入生命危险，拉尔夫不得不放下以前的观点，与神父联手对凶手进行一场驱魔仪式，却发现邪灵的最终目标竟是自己……',NULL,30000000,0,29.359201,5.9,690,118,'2014-07-01','en','/pf5OgZtEPgs1fln3euuOElZinPo.jpg',3.2895564558540795,3,'2026-09-10',2,NULL,NULL),(184374,'五月五之战','Cinco de mayo: la batalla','5月5日,1862年,几千名墨西哥士兵冒着生命的危险与世界上最大的和最强大的军队在一个传奇战役为自由和墨西哥。表现了1862年5月5日普埃布拉之战，此役是第二次法墨战争中墨西哥共和军少有的胜利。',NULL,10000000,0,0.072085,5.8,14,125,'2013-05-03','es','/rS1QWmamAy4cOMzHprMf0dvIJNZ.jpg',2.4202242179494937,3,'2026-09-10',2,NULL,NULL),(185008,'那些年我们疯狂的青春','ये जवानी है दीवानी','邦尼（兰比·卡普尔 Ranbir Kapoor 饰）同好友艾维（阿迪亚·罗伊·卡普尔 Aditya Roy Kapoor 饰）和艾迪提（卡尔吉·柯伊切林 Kalki Koechlin 饰）一同踏上了前往马纳里的徒步旅程，一次偶然中，他们遇见了名为娜妮雅（迪皮卡·帕度柯妮 Deepika Padukone 饰）的美丽女子，巧合的是，娜妮雅和邦尼曾经是旧相识。  　　就这样，一心想要逃脱一成不变的生活的娜妮雅也加入了邦尼一行人的旅程，在此过程中，邦尼的开朗和乐观渐渐的吸引了娜妮雅。遗憾的是，此时的邦尼并不想被感情所束缚，得知这一事实后，娜妮雅选择了退出。时间一晃八年过去，邦尼和娜妮雅在一场婚礼上重逢了，知道这时，邦尼才发现自己其实一直都深深的爱着娜妮雅，这么多年的兜兜转转后，这对有情人能否终成眷属呢？',NULL,7700000,46000000,3.353176,7.2,79,159,'2013-05-31','hi',NULL,2.8249042328953147,3,'2026-09-10',2,NULL,NULL),(185465,'Manito','Manito','Fifteen years ago, their Washington Heights neighborhood was dubbed the crack-cocaine capital of the world, but today it is transforming into one of the most vibrant, Spanish-speaking communities in the United States. While the drug dealers continue to disappear, their violent legacy still casts a shadow over the neighborhood and its residents. Junior, an ex-convict struggling to get his life back on track, is a product of this legacy. His younger brother Manny, the salutatorian of his high school class, embodies the hope of the future. On the night of his graduation party, Manny finds himself faced with an ill-fated decision that could change his life forever',NULL,0,0,0.039264,5.5,2,78,'2002-01-15','en','/8Nzotyqv1Yj00Nw5REAvRYjdCTT.jpg',2.0719294826742893,3,'2026-09-10',2,NULL,NULL),(185567,'祖鲁','Zulu','阿里·努曼( 福里斯特·惠特克饰演)小的时候逃过了一场屠杀。当时名叫因克哈塔(Inkhata)的军事政党与尼尔森·曼德拉领导下的非洲民族议会处在战争状态。阿里和他的母亲幸运地存活了下来，但是和许多幸存者一样，他们心中的精神创伤一直无法愈合。到了今天，阿里已经成为首都开普敦警局重案组的一名负责人。他的下属中有一个叫做布莱恩·艾普肯(奥兰多·布鲁姆饰演)的白人警员。这个人个性不爱听指挥。艾普肯的家族曾经参与种族隔离政策的施行，但是他和努曼的相处很融洽。平时他们的工作总是同失业的穷人、黑帮和毒贩子打交道。当两名年轻女子的尸首被发现后，情况变得更加严峻。一种新的毒品和新的犯罪形式正在威胁当地的居民。在野蛮和文明相交的这个喧闹的交叉路口，种族隔离政策留下的阴影依旧在挣扎着寻求和解的南非社会上空游荡。',NULL,16000000,0,14.529496,6.7,172,110,'2013-12-04','en','/h5OZD7pVkIKR5jf4lGFzQQrLmLc.jpg',3.019654712436748,3,'2026-09-10',2,NULL,NULL),(186935,'赫利','Heli','Estela是一个12岁的小女孩，她爱上了一个17岁的特警学员，而这个特警学员也想带她远走高飞。可没想到的是为了实现自己的梦想，Estela让自己的家庭陷入了灭顶之灾，暴力血案枪战复仇席卷了这个墨西哥小镇…','Police corruption, drug trafficking, sexual exploitation, love, guilt and revenge.',1000000,0,3.629777,6.2,32,105,'2013-08-09','es','/l3Coj0lecjava65HIawIqVAIeWJ.jpg',2.602433755002526,3,'2026-09-10',2,NULL,NULL),(187017,'龙虎少年队2','22 Jump Street','难忘的高中卧底生涯不仅让施密特和延科经历了课业上的考验，还帮他们解决了一些“青少年问题”。时光飞逝，当地警方继续派他们在大学做卧底，他们和年轻人的良好关系为警方拿到不少情报。一切进入正轨，施密特加入了学校足球队，和一帮臭味相投的球友打得火热，延科则进入艺术专业，被班上的青春美少女和完美雕塑勾去了魂魄。破案对他们来说，简直成了负担。他们之间的搭档关系也急转直下。究竟他们要不要维持搭档的关系，还是放任自己享受“大学第二春”呢？','They\'re not 21 anymore',50000000,188441614,52.380982,7,3319,112,'2014-06-05','en','/850chzYHYbT3IISl6Q7dbBuFP2B.jpg',3.9323053856127688,3,'2026-09-10',2,NULL,NULL),(188161,'死在西部的一百万种方式','A Million Ways to Die in the West','影片主要讲述一个懦弱的农场主（塞斯·麦克法兰 饰）在决斗面前退缩，结果女友（阿曼达·塞弗里德 饰）弃他而去和另一个男人（尼尔·帕特里克·哈里斯 饰）跑了。之后这名农场主遇到了一位江洋大盗的妻子（莎莉兹·塞隆 饰），这名神秘美丽的女人教会他开枪射击，帮助他找了了勇气，两人也陷入了爱河。不过好日子没过多久，这名江洋大盗（利亚姆·尼森 饰）回来了，在他的复仇面前，农场主刚刚找回的勇气遭到了考验。','Bring protection.',0,0,32.808675,5.8,1468,116,'2014-05-22','en','/yEL1QUnIFMlB1VHhk1Wxo4VQp4j.jpg',3.4295546230666396,3,'2026-09-10',2,NULL,NULL),(188166,'蓝色废墟','Blue Ruin','德怀特是个整日无所事事的流浪汉，他的父母多年前被一个名叫韦德·克里兰德的男人杀害。当德怀特得知韦德刑满释放的消息时，他的复仇行动开始了。然而，一切并不如计划得那么顺利，他不得不考虑如何保护自己的妹妹免受韦德的伤害。','Revenge comes home',0,258384,25.349758,6.9,462,90,'2014-04-25','en','/q0itEsso2drJXqH9kfdidxIT5dF.jpg',3.3161515763443297,3,'2026-09-10',2,NULL,NULL),(188207,'大力神','The Legend of Hercules','为从暴君丈夫手中拯救万民、让自由重返大地，王后阿尔克墨涅祈神相助，结果她获赐与战神宙斯诞下半人半神的儿子海克力斯。真实身分成谜的他海克力斯被父王国王安菲达顿嫌弃，他的兄长依佛季斯王子反之被宠。  　　年轻的海克力斯爱上美女希碧公主，父王却将她许配给兄长。二人打算私奔之际，海克力斯被父王的护卫逮住，他被罚战死沙场。海克力斯大难不死，更与战友索迪裡斯誓言推翻父王，同时救出爱人，令他成为史上最伟大的古希腊英雄之一。','Every Man Has a Destiny',70000000,61279452,25.020428,4.4,533,99,'2014-01-10','en','/lwQMGmEVXofv9iCVO5mP9ZGjEK1.jpg',3.0376129374971685,3,'2026-09-10',2,NULL,NULL),(188652,'The Ghastly Love of Johnny X','The Ghastly Love of Johnny X','A truly mad concoction, blending 1950s juvenile delinquents, sci-fi melodrama, song-and-dance, and a touch of horror, everything in just the right combination to create an engaging big screen spectacle! This curious and curiously entertaining story involves one Jonathan Xavier and his devoted misfit gang who, incidentally, have been exiled to Earth from the far reaches of outer space. Johnny\'s former girlfriend Bliss has left him and stolen his Resurrection Suit, a cosmic, mind-bending uniform that gives the owner power over others. Along the way, there will be several highly stylized musical numbers, lots of genuinely humorous dialogue, and a wacky plot-twist or two, all beautifully captured on the very last of Kodak\'s black-and-white Plus-X film stock.','They Sing! They Dance! They\'re Juvenile Delinquents from Outer Space!',0,0,0.209475,6.6,8,106,'2013-04-26','en','/x5f1DNKwid7Pce9afAQd2waPtDs.jpg',2.312970515245161,3,'2026-09-10',2,NULL,NULL),(188927,'星际迷航3：超越星辰','Star Trek Beyond','柯克船长带领企业号继续踏上宇宙探索的旅程，他向老骨头讲述了自己对于船长身份的忧虑，而在他与最好的朋友史波克互诉衷肠前，他们又接到了一个紧急救援的任务。而神秘敌人剋劳开始攻击企业号，而幸存的企业号成员也分散至一个行星上求生……',NULL,185000000,343471816,65.352913,6.6,2568,122,'2016-07-07','en','/wI5VghYNYLktDRPUa5rrVcVA1h7.jpg',3.801850454075742,3,'2026-09-10',2,NULL,NULL),(189711,'怪物时代的爱情','Love in the Time of Monsters','Two sisters travel to a cheesy tourist trap where they battle toxic monsters dressed in bigfoot costumes in order to save the ones they love.',NULL,0,0,0.133619,5,2,0,'2014-03-08','en','/mm6hcoQg5tHZ71ydsotXal3EeeO.jpg',2.0717342912988803,3,'2026-09-10',2,NULL,NULL),(190847,'The Last Days on Mars','The Last Days on Mars','On the last day of the first manned mission to Mars, a crew member of Tantalus Base believes he has made an astounding discovery – fossilized evidence of bacterial life. Unwilling to let the relief crew claims all the glory, he disobeys orders to pack up and goes out on an unauthorized expedition to collect further samples. But a routine excavation turns to disaster when the porous ground collapses and he falls into a deep crevice and near certain death. His devastated colleagues attempt to recover his body. However, when another vanishes, they start to suspect that the life-form they have discovered is not without danger.','The search for life is about to end.',0,0,18.764453,5.2,302,98,'2013-08-11','en','/oyaNfMknRauNPTrRpN8n0gFuCOV.jpg',3.0371248719945227,3,'2026-09-10',2,NULL,NULL),(190859,'美国狙击手','American Sniper','U.S. Navy SEAL Chris Kyle takes his sole mission—protect his comrades—to heart and becomes one of the most lethal snipers in American history. His pinpoint accuracy not only saves countless lives but also makes him a prime target of insurgents. Despite grave danger and his struggle to be a good husband and father to his family back in the States, Kyle serves four tours of duty in Iraq. However, when he finally returns home, he finds that he cannot leave the war behind.','The most lethal sniper in U.S. history.',58800000,542307423,87.53437,7.4,4469,133,'2014-12-11','en','/i1U46OwMc6vlm7OoSUKfqUH615e.jpg',4.190970308234303,3,'2026-09-10',2,NULL,NULL),(190955,'血缘','Blood Ties','翻拍自2008年的法国电影《血缘关系》，还邀请了詹姆士·格雷担任编剧。讲述刚从监狱里放出来的黑帮头目加布里埃尔与身为警察的亲弟弟相隔十年后重逢，两人决定从此脱离黑帮，金盆洗手，开始过正常人的生活。卡内的女友玛丽昂·歌迪亚也加盟本片，本片也是卡内的首部英语电影。','Crime runs in the family.',25500000,2415472,12.756344,6,171,128,'2013-08-22','en','/7tMuywiZUoaAihEIkCu3BAL1xPC.jpg',2.9742618904595655,3,'2026-09-10',2,NULL,NULL),(191229,'鬣蜥','Iguana','A grotesquely disfigured harpooner called Iguana is severely mistreated by his fellow sailors on a whaling ship in the 19th century. One night he escapes and takes up residence on a remote island. He makes himself ruler of the island and declares war on mankind. Anyone unfortunate enough to wind up on the island with Iguana is subjected to his cruel tyranny.',NULL,0,0,0.214704,6,1,88,'1988-04-01','en','/yN6FIIICpMp9DyRXk9trUm3t3zt.jpg',1.984741495960417,3,'2026-09-10',2,NULL,NULL),(191714,'午餐盒','The Lunchbox','在政府部门服务35年的佛南德斯，自老婆去世后便独来独往，届退生活更是平淡无味；漂亮贤慧的人妻伊拉，每天费尽心思料理美味，尝试激活丈夫的爱，挽救走味婚姻。一次阴错阳差，精準无比的百年便当快递，竟将伊拉準备的餐盒，送到佛南德斯手中。这个美丽的错误，让素未谋面的两人，开始以繽纷美食和贴心书信交流互动，分享生命的喜悦与哀愁，成為彼此的心灵支柱。是否要不顾后果交往？或如缘份初始，任由命运安排？渴爱的心，五味杂陈。',NULL,1000000,4235151,14.017809,7.3,221,104,'2013-09-19','hi','/eZvdKgnFLjkxe9rpYZhRMLE0X0U.jpg',3.121895490308963,3,'2026-09-10',2,NULL,NULL),(192102,'三日刺杀','3 Days to Kill','本片故事讲述凯文·科斯特纳饰演的国际特工伊桑·雷纳，多年危险暴力的职业生涯使得他与妻子（康妮·尼尔森 饰）及女儿的关系渐行渐远，为了修复家庭，他准备洗手退休。然而，神秘冷艳的美女上级（艾梅柏·希尔德 饰）交给他最后一单任务：搞定全世界最难对付的两个恐怖分子；此外还要在妻子出城期间，独自照看正处于青春叛逆期的女儿，要知道，他已经足足十年没有和女儿单独相处过了……曾在《大地惊雷》中有惊艳表现的90后女星海莉·斯坦菲尔德将在片中饰演科斯特纳的女儿，父女戏份温情十足。',NULL,28000000,52597999,41.638961,6,883,113,'2014-02-14','en','/tcwhHqmRR7aObvlxo0RQxvgXgEC.jpg',3.3836086899250386,3,'2026-09-10',2,NULL,NULL),(192132,'帕罗奥图','Palo Alto','一部以一群爱惹麻烦的青少年为中心的黑色青春电影。在加利福尼亚的帕罗奥图这座小镇上，有寻爱的姑娘，有惹麻烦的男孩，也有两者兼顾的男人，而弗兰科便是这位“左右逢源”的男人，他在片中不但与年轻的罗伯茨之间有千丝万缕的情爱联系，也会参与年轻人的荒唐事……',NULL,0,0,16.570708,6.4,348,100,'2014-05-09','en','/yjcwwYP3eSigxLKKVBoVVz85ZWv.jpg',3.170919215301494,3,'2026-09-10',2,NULL,NULL),(192134,'唐·海明威','Dom Hemingway','《唐·海明威》是一部黑色犯罪喜剧，由理查德·谢帕德执导，讲述了裘德·洛饰演的电脑黑客唐·海明威为一名黑帮大佬（德米安·比齐尔饰）服务，但是12年前他东窗事发被捕入狱，他与搭档迪克（理查德·格兰特饰）经过12年的牢狱之灾，出狱后两人决定拿回自己当年所应得的酬劳，他们与黑帮大佬的争端一触即发。同时，海明威还希望能够取得女儿伊芙琳（艾米莉亚·克拉克饰）的谅解，在亲情和债务之间，海明威陷入了很危险的境地。','I want my money plus interest.... and a present',0,523511,10.416332,5.8,212,93,'2013-11-15','en','/hvrUPdZUDlSn1S4KCW5IdIMGS5D.jpg',3.0006238976153154,3,'2026-09-10',2,NULL,NULL),(192136,'曼德拉','Mandela: Long Walk to Freedom','出生于1918年的曼德拉是深受全世界人民尊敬的民主斗士与政治家，为了推翻南非白人种族主义统治，他进行了长达50年（1944—1994年）艰苦卓绝的斗争，被南非当局关押了27年（1962—1990年）。在1994年南非举行的首次民主大选中，曼德拉成功当选南非第一任黑人总统 ，为新南非开创了一个民主统一的局面。  　　电影《漫漫自由路》改编自曼德拉的同名自传，故事将从曼德拉的孩提时代一直讲到他的总统就职演说。','It is an ideal for which I am prepared to die.',35000000,27330000,15.50957,6.5,224,141,'2013-12-06','en','/lj78eI5MLwXqCfI4v007Xo7Svb3.jpg',3.07263351877437,3,'2026-09-10',2,NULL,NULL),(192141,'无处可逃','No Escape','某东南亚政府与跨国企业合作，在落后地区大肆发展基建。美国工程师杰克（欧文·威尔逊 Owen Wilson 饰） 因而被公司外派，携同妻女长驻当地参与项目发展。杰克以为能在椰林树影的东南亚惬意展开新生活之际，但是愤怒的当地居民却因政府借基建为名中饱私囊而爆发骚乱。政府警察 、军队节节败退，地区陷入无政府状态，民怨矛头迅即转向杰克等一班无辜的外国侨民，血腥的排外屠杀一发不可收拾。杰克能否在长居东南亚几十年的哈蒙德（皮尔斯·布鲁斯南 Pierce Brosnan 饰）的帮助下，带领家人成功逃离险境？','No rescue. No refuge.',5000000,54418872,38.006982,6.7,777,103,'2015-08-26','en','/8vNHolUCQhAjErlKrqnWxg6HERl.jpg',3.457039067085167,3,'2026-09-10',2,NULL,NULL),(192210,'大路','Open Road','一个在旅途中寻找生命真谛的年轻女子Angie，不仅最终找回了自我，还领悟到了各种爱......',NULL,3000000,0,2.680629,5.2,18,85,'2013-04-12','en','/y8Ecw1WdbgTacszNR1C0G4WK21r.jpg',2.472680069533867,3,'2026-09-10',2,NULL,NULL),(192577,'船长哈洛克','キャプテンハーロック','或许过去，又或许未来，人类大规模向宇宙殖民。当人口膨胀到五千亿的时候，散落在宇宙各个角落的人类返回故土地球，却引发了伤亡惨重的归乡战争。为了保护地球这片圣地，人类制定了盖亚制裁，约定不许任何人染指这里。可是曾经作为联合舰队舰长的哈洛克却背叛盖亚制裁，驾驶着他的阿尔卡迪亚号高举叛旗，成为逃逸一百年之久的通缉犯。联合舰队长官伊索拉指使自己的弟弟亚马混入阿尔卡迪亚号，探寻尼伯龙根人发明的永动机的秘密。在此期间，哈洛克率领船员向地球挺近，而联合舰队则在太阳系布下天罗地网阻挡他的步伐。遥远的故土，失落已久的真相，令所有人为之震惊……',NULL,30000000,17137302,14.726338,6.5,356,115,'2013-09-07','ja',NULL,3.1819066082965053,3,'2026-09-10',2,NULL,NULL),(193603,'恐怖出游','Hayride','A college student returning home for Halloween is forced to face his childhood fears when an escaped killer takes refuge in his family\'s \"Haunted Hayride\".','Southern Fried Horror',60000,0,0.412342,5.1,6,93,'2012-10-13','en','/gFmvxOn5oSbIRcunwhVxrBwfxx3.jpg',2.2547914960194992,3,'2026-09-10',2,NULL,NULL),(193610,'情敌复仇战','The Other Woman','卡莉（卡梅隆·迪亚茨 Cameron Diaz 饰）是一位精明强干的律师，无论对于生活还是男人，她所要求的无疑都是最好和最完美的。一次偶然中，卡莉结识了名叫马克（尼可拉·科斯特-瓦尔道 Nikolaj Coster-Waldau 饰）的男子，后者的英俊和潇洒立刻就吸引了卡莉的注意，没过多久，两人就坠入了爱河。\r 　　为了给马克一个惊喜，卡莉瞒着他来到了他的家乡，让卡莉没有想到的是，在这里迎接她的，竟然是一个自称是马克妻子的女人凯特（莱斯利·曼恩 Leslie Mann 饰），而凯特对于卡莉的存在亦是一无所知。直到这时，卡莉才开始渐渐看清马克的真实面目，她和凯特决定联手，将其揭穿。之后，一个名为艾伯（凯特·阿普顿 Kate Upton 饰）的女人加入了她们，三个女人联合在一起，好戏即将上演。 ©豆瓣','The oddest friends are about to get even',40000000,196781193,34.519636,6.2,1437,109,'2014-04-16','en','/lT0awXQ9dUhdWSNwEo6aVotpmY8.jpg',3.508909725952213,3,'2026-09-10',2,NULL,NULL),(193613,'金属乐队：穿越永恒','Metallica: Through the Never','“金属乐队”的这部3D电影《金属乐队：穿越永恒》，由曾经导演过科幻惊悚片《新铁血战士》的尼姆罗德·安塔尔执导，主演是好莱坞新生代演员戴恩·德哈恩。  　　在影片中，戴恩·德哈恩受“金属乐队”派遣，去找回一辆破旧的卡车和秘密包裹，但想要完成这项特殊任务并不容易，等待他的是一段惊险刺激的冒险旅程。观众在银幕上会看到戴恩·德哈恩的这场冒险和“金属乐队”极具冲击力的演唱会交替上演，影片的IMAX版本更是能够带来顶尖的视听体验。  　　乐队鼓手拉尔斯·乌尔里克感叹道：“我以前觉得IMAX或者3D技术是噱头，但是这部影片只有用这些高科技呈现才更震撼。观众观影时仿佛身临其境于演唱会现场！”本片是“金属乐队”在加拿大巡演时拍摄完成的，之前乐队成员曾在墨西哥城做了八场排练表演，最终呈现的效果令人满意。','Experience Metallica like never before',18000000,7972967,7.871686,6.7,83,93,'2013-09-25','en','/6szqjCuVRZQbL1otckVPDCfRgiI.jpg',2.831927544507299,3,'2026-09-10',2,NULL,NULL),(193722,'限制级100岁','R100','你是S还是M？  在东京知名家具店工作的中年男子片山贵文有一个不能说的秘密，他其实是一个被虐狂。某日，他因为抵受不住诱惑加入了一家神秘的俱乐部，并签下一年合约，规定期间不论发生何事也不能中途退会。从此，俱乐部定期派出不同类型的皮衣女王在他的日常生活中出现，引诱他走入未曾体验过的世界。可是，情况逐渐失控，女王们开始在他的职场和家庭中出现，片山和家人更被卷入无法预测的事态当中…','M For Father',5500000,0,3.21392,5.4,31,100,'2013-10-05','ja','/gkvlBuA839yF4MZBwaSEfYc5HMx.jpg',2.584971988597232,3,'2026-09-10',2,NULL,NULL),(193756,'孤独的幸存者','Lone Survivor','根据马库斯·拉特尔（Marcus Luttrell）的同名回忆录改编。2005年他和另外三位美军“海豹突击队”的同伴负责执行一次暗杀基地组织领导人的任务，在途中他们遇到了当地牧羊人（三个孩子和一个老人），按照交战法则他们是可以杀掉他们的，但海豹队员并没有这样做，反而放了他们——尽管他们也知道这些人有可能去通风报信。不多久他们就遭到了250名塔利班士兵的攻击，四位海豹队员中有三名先后牺牲，最后只剩下马库斯·拉特尔成为“孤独的生还者”。','Based on True Acts of Courage',40000000,149295601,37.084384,7.4,1526,121,'2013-12-24','en','/zaBIrloyhGK7iNTZMb3f9SARsl8.jpg',3.7718365396038975,3,'2026-09-10',2,NULL,NULL),(193893,'Let\'s Be Cops','Let\'s Be Cops','It\'s the ultimate buddy cop movie except for one thing: they\'re not cops.  When two struggling pals dress as police officers for a costume party, they become neighborhood sensations.  But when these newly-minted “heroes” get tangled in a real life web of mobsters and dirty detectives, they must put their fake badges on the line.','Fake Cops. Real Trouble.',17000000,136621271,70.668923,6.4,1219,104,'2014-08-13','en','/rf439opXrgWxrJU3yDar8QUv5bt.jpg',3.59235220679146,3,'2026-09-10',2,NULL,NULL),(194588,'Short Cut to Nirvana: Kumbh Mela','Short Cut to Nirvana: Kumbh Mela','Every 12 years over 70 million pilgrims gather at the meeting of India\'s holiest rivers, the Ganges and the Yamuna, for a spectacular spiritual festival: the Kumbh Mela. This documentary takes a voyage of discovery through this colorful event through the eyes of several Westerners and an ebullient young Hindu monk, Swami Krishnanand. Featuring encounters with some of India\'s most respected holy men and exclusive footage of His Holiness the Dalai Lama.',NULL,0,0,0.004998,0,0,85,'2004-05-11','en',NULL,1.8337938017366218,3,'2026-09-10',2,NULL,NULL),(194662,'鸟人','Birdman or (The Unexpected Virtue of Ignorance)','一位曾因饰演标志性超级英雄而闻名的演员，正艰难筹备一部百老汇舞台剧。在首演前夕的几天里，他与自我角力，试图找回自己的家庭、事业与自我。','or (The Unexpected Virtue of Ignorance)',18000000,103215094,89.811154,7.4,4535,119,'2014-08-27','en','/rHUg2AuIuLSIYMYFgavVwqt1jtc.jpg',4.20003243707216,3,'2026-09-10',2,NULL,NULL),(195589,'邻居大战','Neighbors','影片讲述了一个热血又放荡不羁的青年，在几次巧合之下无意中影响了邻居一家生活的故事。塞斯·罗根与萝丝·拜恩在片中饰演这对新生儿年轻夫妇，而扎克·埃夫隆饰演的公子哥这二货的节奏将会给罗根夫妇惹不少麻烦。','Family vs. Frat',18000000,268157400,36.471231,6.2,2713,96,'2014-05-08','en','/62nLtpLmYbK15jsGVJebKFJBvKL.jpg',3.6545630386426255,3,'2026-09-10',2,NULL,NULL),(196867,'安妮：纽约奇缘','Annie','安妮（奎文赞妮·瓦利斯 Quvenzhané Wallis 饰）是一位年幼的孤儿，生活在当今的纽约市，她在养母汉尼根小姐（卡梅隆·迪亚茨 Cameron Diaz 饰）照料下，过着举步维艰的日子。有一天，安妮的命运终于出现了转机。威尔•史塔克（杰米·福克斯 Jamie Foxx 饰），一位正在竞选市长的固执大亨，在他精干的副总裁格雷斯（萝丝•拜恩饰）和投机倒把的幕僚盖 （鲍比·坎纳瓦尔 Bobby Cannavale 饰）的建议下，将安妮拉入自己的竞选阵营，计划出一个“纸包不住火”的竞选方案。史塔克坚信自己是安妮的守护天使，但安妮自身固有的自信、积极向上，坚信“柳暗花明又一村”的性格与生活信念，或许正证明了她对史塔克的意义。','It\'s a Hard Knock Life',65000000,133821816,33.439187,6,466,119,'2014-12-19','en','/vHjrntS42qwL7UN20M6qm3LdIRZ.jpg',3.2316425096498342,3,'2026-09-10',2,NULL,NULL),(198062,'咖啡镇','Coffee Town','威尔（格伦·霍顿 Glenn Howerton 饰）经营着一家咖啡店，因为行业不景气，店主决定收回铺子，将咖啡店改造成一间酒吧，以赚取更多的利润。为了留住自己赖以生存的店铺，威尔决定反击。他找到了好友查得（史蒂夫·李特 Steve Little 饰）和基诺（本·施瓦兹 Ben Schwartz 饰），三人策划了一场抢劫案，为的是让店主明白，这里并不是经营酒吧的好地方。\r 　　就在计划顺利进行的节骨眼上，店小二山姆（乔许·葛洛班 Josh Groban 饰）却成为了计划里最大的阻碍。山姆一心想成为一名摇滚明星，对威尔怨气冲天，因此屡屡破坏他们的行动。与此同时，威尔暗恋的女孩贝卡（阿德琳妮·帕里奇 Adrianne Palicki 饰）也对威尔的示爱毫无反应。',NULL,0,0,2.253589,6.7,45,87,'2013-07-09','en','/475PTJRhikorye5BnTan5BPm85j.jpg',2.680561697544136,3,'2026-09-10',2,NULL,NULL),(198184,'超能查派','Chappie','Every child comes into the world full of promise, and none more so than Chappie: he is gifted, special, a prodigy. Like any child, Chappie will come under the influence of his surroundings—some good, some bad—and he will rely on his heart and soul to find his way in the world and become his own man. But there\'s one thing that makes Chappie different from any one else: he is a robot.','I am consciousness. I am alive. I am Chappie.',49000000,104399548,116.700319,6.6,3062,120,'2015-03-04','en','/uuDUpzlMFomdSfNWlpEPS9nVZWV.jpg',3.961540451037392,3,'2026-09-10',2,NULL,NULL),(198185,'Million Dollar Arm','Million Dollar Arm','In a last-ditch effort to save his career, sports agent JB Bernstein (Jon Hamm) dreams up a wild game plan to find Major League Baseball’s next great pitcher from a pool of cricket players in India. He soon discovers two young men who can throw a fastball but know nothing about the game of baseball. Or America. It’s an incredible and touching journey that will change them all — especially JB, who learns valuable lessons about teamwork, commitment and family.','Sometimes to win, sometimes you have to change the game',25000000,38307627,17.312433,6.6,259,124,'2014-05-09','en','/r6ecPGLE5qYEIm4OON1pulBLKqi.jpg',3.1191665009490794,3,'2026-09-10',2,NULL,NULL),(198277,'再次出发之纽约遇见你','Begin Again','格雷塔（凯拉·奈特莉 Keira Knightley 饰）抛弃了一切跟随着男友戴夫（亚当·李维 Adam Levine 饰）来到美国纽约实现他们的音乐和爱情梦想，没想到曾经幻想过的美好一切化作泡影，在获得了更好的工作机会后，戴夫果断抛弃了格雷塔，留下她一人苦苦在底层挣扎。  　　丹（马克·鲁法洛 Mark Ruffalo 饰）最近的生活也不好过，他发现自己无法从思念前妻马瑞安（凯瑟琳·基纳 Catherine Keener 饰）的感情中走出来，与此同时，他的女儿维奥莱特（海莉·斯坦菲尔德 Hailee Steinfeld 饰）正处于一生中最叛逆的阶段。丹和格雷塔，命运让这失意的两人于一间小小的酒吧里相遇了，等待着他们的，会是怎样充满波折而又浪漫满满的故事呢？','You\'re only as strong as your next move.',8000000,63464861,35.735689,7.3,1254,104,'2013-09-07','en','/fuFl2Se8EBsGKnLli0whkpfSq85.jpg',3.690059501654888,3,'2026-09-10',2,NULL,NULL),(198370,'Mutual Friends','Mutual Friends','Surprise parties rarely go well. This one is no different, as a group of 30-somethings head through life, love and a day in New York City.','Surprise parties rarely go well.',0,0,0.136721,0,0,0,'2014-04-15','en','/dAUXuqcrAGaFT318snL3sgqGHyv.jpg',1.8340946829894484,3,'2026-09-10',2,NULL,NULL),(198663,'移动迷宫','The Maze Runner','男孩托马斯（迪伦·欧布莱恩 Dylan O\'Brien 饰）在电梯中醒来，奇怪的是他除了名字之外什么都记不得。当电梯打开，他来到了一个陌生的地方“林间空地”。这里四周被高大的石头墙包围着，墙内住着许多男孩，有纽特（托马斯·桑斯特 Thomas Sangster 饰）、查克（布雷克·库珀 Blake Cooper 饰）、米诺（李基弘 Ki Hong Lee 饰）等人，他们都被困在迷宫里，而墙外还有一群巨大的怪兽威胁着。一天，电梯为他们送来了一个女孩特雷莎（卡雅·斯考达里奥 Kaya Scodelario 饰），她是来这里的第一个女孩。此后，迷宫逐渐开始发生变化，一切都陷入了混乱中，托马斯和特雷莎决定一起走上破解迷宫之路，找出迷宫背后令人不寒而栗的秘密。影片改编自詹姆斯·达什纳撰写的同名反乌托邦科幻小说三部曲的第一本。 ©豆瓣','Run - Remember - Survive',34000000,348319861,131.815575,7,5371,113,'2014-09-10','en','/ode14q7WtDugFDp78fo9lCsmay9.jpg',4.234367418005057,3,'2026-09-10',2,NULL,NULL),(199373,'冰封之地','The Frozen Ground','根据真实故事改编，讲述的是20世纪80年底阿拉斯加发生的一系列妓女猎杀案。50 Cent原名柯蒂斯-杰克逊(Curtis Jackson)，是目前全美正当红的说唱明星，他将在这部影片中饰演一位皮条客，而约翰-库萨克将饰演那位臭名昭著的连环杀手罗伯特-汉森(Robert Hansen)，他的对手则是凯奇饰演的一位阿拉斯加州立警察。','The hunter becomes the hunted',27220000,5496951,28.060472,6.1,465,105,'2013-07-18','en','/4X1UPzCpIy5s5hExJ5WGxao20Mb.jpg',3.2305972409442067,3,'2026-09-10',2,NULL,NULL),(199933,'阿特拉斯耸耸肩3','Atlas Shrugged: Part III','国家的经济正在快速崩溃，罪犯和黑暗势力控制了整个国家，政府已经无能为力，一个女人有了答案，她和其他人会不惜一切去找到他。他是谁？他是约翰.高尔特。本片获得第35届金酸莓奖提名最差翻拍、节选与续集。','Who is John Galt?',5000000,846704,1.731035,3.9,15,99,'2014-09-12','en','/wR7NM125F63zxECZKCVMzibkWpZ.jpg',2.426403437897025,3,'2026-09-10',2,NULL,NULL),(200505,'选秀日','Draft Day','讲述美国职业橄榄球联盟克利夫兰布朗队总经理桑尼，在高压下，为球队抢下选秀第一顺位的故事。','The greatest victories don\'t always happen on the field.',25000000,28831145,14.17009,6.5,304,109,'2014-04-11','en','/bnl2ocjS1io4UCPhjoFuPKmJ9bf.jpg',3.142519954173377,3,'2026-09-10',2,NULL,NULL),(201088,'骇客交锋','Blackhat','中国香港和美国洛杉矶同时发生了导致严重后果的黑客入侵事件，中国政府和美国联邦调查局决定联手，找到事件的真相。经过调查，黑客在犯罪过程中使用了远程访问工具，而程序的编写者是一位名为尼古拉斯（克里斯·海姆斯沃斯 Chris Hemsworth 饰）的神秘男子，身为网络高手的他此时正身陷囹圄。  　　陈大伟（王力宏 饰）是负责此案的军官，他和妹妹（汤唯 饰）远赴洛杉矶，在特工卡罗尔（维奥拉·戴维斯 Viola Davis 饰）的帮助下寻得了尼古拉斯的踪迹。两人和尼古拉斯之间达成了一个交易，如果尼古拉斯能够帮助他们找到黑客事件的幕后真凶，那么尼古拉斯就将重新获得自由。','We are no longer in control.',70000000,17752940,46.832372,5.1,826,133,'2015-01-13','en','/Aog9EGFjzZnOytDKbEQmXpT8314.jpg',3.2380842834171477,3,'2026-09-10',2,NULL,NULL),(201132,'Antarctica: A Year on Ice','Antarctica: A Year on Ice','Filling the giant screen with stunning time-lapse vistas of Antarctica, and detailing year-round life at McMurdo and Scott Base, Anthony Powell’s documentary is a potent hymn to the icy continent and the heavens above.','Step Outside The Box',1000000,0,1.883947,7.2,29,92,'2013-09-05','en','/agXQuqqqvF0Th77y2nEZg7INOXl.jpg',2.5891363255063995,3,'2026-09-10',2,NULL,NULL),(202575,'魔法总动员','The House of Magic','劳伦斯（道格·斯通 Doug Stone 配音）曾经是一名魔术师，某日，他收留了一只流浪的小猫，取名闪电（穆雷·布鲁 Murray Blue 配音）。闪电成为了劳伦斯家中的一份子，很快，它就和别墅里的各种机器人和玩偶们打成了一片。然而，在这欢乐祥和的气氛中，却产生了一丝不和谐的声音，对于闪电的到来，白兔和小鼠的态度一直不是十分友好。某日，为了把雷电赶走，白兔和小鼠想出了一个计划，然而，这个计划却令劳伦斯发生了车祸，受伤住院。劳伦斯离开后，一直觊觎他财产的侄子接管了别墅，并想要将它偷偷卖掉。为了保护自己赖以生存的家园，闪电、白兔和小鼠决定联手，奋起反击。','One lost little cat. One magical adventure.',34000000,0,12.867326,6.3,121,85,'2013-12-24','en','/wfokPQjyyCFluMxXsp2txHfVhUW.jpg',2.9143619146975,3,'2026-09-10',2,NULL,NULL),(202604,'驱魔实录','The Vatican Exorcisms','Documentary following US film-maker Joe Marino as he heads to Italy to investigate exorcisms and the truth behind rumors of demonic possession.','The public were never meant to know',0,0,0.447166,4.4,11,0,'2013-05-29','en','/dLouGrpKl02GrlUK4wfNZiUW7Wy.jpg',2.366751234330001,3,'2026-09-10',2,NULL,NULL),(203801,'秘密特工','The Man from U.N.C.L.E.','故事发生在1963年的德国，时值冷战期间，德国女汽车技师嘉比 的父亲是一位精通核武器的专家，最近，有证据表情他正在帮助纳粹制造核武器，来达到统一全人类的邪恶野望。拿破仑 是CIA的特工，他曾经犯过的错误让他的仕途岌岌可危，他必须做出点成绩来证明自己并非无用之才。伊利亚 是苏联国家安全委员会特工，他的父亲被政府打上了贪污分子的烙印，为了摆脱父亲带给自己的不良影响，伊利亚必须比其他人更加努力。这样的两个人都想要赶在对方之前将核弹大师捉拿归案。','Saving the world never goes out of style.',75000000,108145109,48.744209,7.1,2265,116,'2015-08-13','en','/y5yZaForGSJbPD66Cvq9AT5WMAD.jpg',3.846888830296504,3,'2026-09-10',2,NULL,NULL),(203833,'偷书贼','The Book Thief','1939年的德国，9岁的小女孩莉赛尔和弟弟被迫送往慕尼黑远郊的寄养家庭。6岁的弟弟不幸死在了路途中。在冷清的葬礼后，莉赛尔意外得到她的第一本书《掘墓人手册》。这将是14本给她带来无限安慰的书之一。她是个孤苦的孩子，父亲被打上了共产主义者的烙印，被纳粹带走了；母亲随后也失踪了。在弹奏手风琴的养父的帮助下，她学会了阅读。尽管生活艰苦，她却发现了一个比食物更难以抗拒的东西——书。她忍不住开始偷书。莉赛尔，这个被死神称为“偷书贼”的可怜女孩，在战乱的德国努力地生存着，并不可思议地帮助了周围同样承受苦难的人。','Courage beyond words.',0,76586316,57.84156,7.4,1486,131,'2013-11-08','en','/wj4U5sMLcJMa3WR9CpRR9e2sdgZ.jpg',3.811231838038768,3,'2026-09-10',2,NULL,NULL),(204082,'家园防线','Homefront','布洛克（杰森·斯坦森 Jason Statham 饰）的灰暗过往令他不得不携家带口过起了离群索居隐姓埋名的生活，和从前经历的大风大浪相比，如今和家人待在一起的平静日子显得尤为可贵。然而，现实却不愿轻易放过布洛克，一场意外的冲突让毒枭盖特（詹姆斯·弗兰科 James Franco 饰）在无意之中发现了布洛克的真实身份，布洛克好不容易构筑起的安稳即将毁于一旦。\r 盖瑞找来了前女友雪莉（薇诺娜·瑞德 Winona Ryder 饰），在小镇之中散布着搅乱人心的流言蜚语，一时间，矛头全部指向了布洛克一家人，此时唯一信任和支持布洛克的，只有布洛克的女儿和她的老师。与此同时，盖瑞此举亦将自己推上了一条不归路。','How far would you go to protect your home?',22000000,43058898,35.737655,6.4,875,100,'2013-11-27','en','/iGk93F3C1iBRJuHkNJA4pDsJkIW.jpg',3.4337156598004785,3,'2026-09-10',2,NULL,NULL),(204922,'在我入睡前','Before I Go to Sleep','一个女人20年前遭遇了神秘的事故，结果患上健忘症，每天早上起来都对之前的自己毫无记忆。她试着用记日记的形式来写下一些残缺的回忆，结果慢慢发现她的丈夫Ben非常可疑。','Who do you trust?',22000000,15447154,48.784734,6.2,659,92,'2014-09-03','en','/te6xzYPivgX3Dxgg03PZ5dWfiM0.jpg',3.367441096410466,3,'2026-09-10',2,NULL,NULL),(205126,'Independence Daysaster','Independence Daysaster','When Earth is attacked by a hostile alien force, a small town firefighter and a rogue SETI scientist team up to activate the only technology capable of defeating the invaders.',NULL,1800000,0,1.959405,4.2,22,86,'2013-06-27','en','/6jor0EqECPgHqu89GrQIy9Wetkf.jpg',2.5023006726274524,3,'2026-09-10',2,NULL,NULL),(205220,'菲洛梅娜','Philomena','影片讲述了一个真实的故事。一名妇女用了50多年时间找寻被从自己身边强迫带走的孩子。那是在1952年的爱尔兰，社会风气保守，菲洛梅娜·李(Philomena Lee )生下孩子时是一个未成年少女，她以“堕落”的罪名被关押进罗斯克里(Roscrea)的修道院，而襁褓中的婴孩被修女强行抱走，送到了美国供人收养。菲洛梅娜在接下来的五十年时间里，没有一天不再想念自己的孩子，她也没有放弃找寻到他再次拥抱他的希望。《菲洛梅娜》改编自 BBC 记者马丁·斯克斯史密斯出版的作品《菲诺梅娜的遗失孩子》，来自真人真事。1952年的爱尔兰世风依旧保守，未成年的菲洛梅娜不仅不能抚养刚出生的孩子，自己也被迫在修道院受罚。三年后儿子在修道院安排下远赴美国被领养。50年无果的寻找后，她将这一秘密告诉记者马丁，在后者帮助下，踏上了前往美国的寻子之路。寻子途中，既有菲洛梅娜对儿子精彩人生的发现，也有处在人生不同阶段的老人和记者的彼此互助和情怀。','These two unlikely companions are on a journey to find her long lost son.',12000000,100129872,29.019504,7.4,579,98,'2013-11-01','en','/eBUv2GmGdXmCk1AaSOmyiu70hN8.jpg',3.4528204271860305,3,'2026-09-10',2,NULL,NULL),(205321,'鲨卷风','Sharknado','所谓“鲨龙卷”，其实就是龙卷风袭过鲨鱼活跃的海域，将那里的海水和鲨鱼一同卷起带到别的地方，有点类似青蛙雨，只不过从天而降的是张着血盆大口的大白鲨！\r 这部《鲨龙卷》（Sharknado）的故事发生地设定在洛杉矶，主演有塔拉·蕾德（Tara Reid）等。本周四晚九点该片将在Syfy科幻频道全球首播','Enough said!',1000000,0,20.466433,3.8,476,86,'2013-07-11','en','/x2bC4XszzFXgfTpWHcVBUUQ8xp1.jpg',2.9456028861387304,3,'2026-09-10',2,NULL,NULL),(205584,'神战：权力之眼','Gods of Egypt','故事发生在繁荣昌盛的尼罗河畔，在天神荷鲁斯（尼古拉·科斯特-瓦尔道 Nikolaj Coster-Waldau 饰）的和平统治之下，百姓们安居乐业，生活在一片祥和之中。然而好景不长，邪恶的黑暗之神赛特（杰拉德·巴特勒 Gerard Butler 饰）利用阴谋诡计夺走了荷鲁斯的王座和双眼，将他驱逐囚禁，赛特生性残暴而好战，很快，整个国家陷入了混乱之中。  贝克（布兰顿·思怀兹 Brenton Thwaites 饰）只是一介平凡的人类窃贼，却在意外之中成为了拯救人类的唯一希望。为了对抗强大的赛特，他千里迢迢找到了荷鲁斯，向他寻求帮助。就这样，一人一神的奇怪组合成立了。为了重新获得力量，荷鲁斯必须夺回他的眼睛，以此为目标，一行人踏上了旅途。','The battle for eternity begins',140000000,150680864,56.257249,5.3,1277,127,'2016-02-25','en','/p2iVn8og6Sq2Rjq3TaAsWN2qevr.jpg',3.360316874784645,3,'2026-09-10',2,NULL,NULL),(205587,'法官老爹','The Judge','一名成功律师回家乡参加母亲的葬礼。随着他与亲朋好友的接触，他感觉自己的父亲有杀人的嫌疑，而他父亲是当地德高望重的法官。这一切让父子俩的关系蒙上阴影。','Defend your Honor.',50000000,83719388,42.472324,7.2,1417,141,'2014-10-08','en','/3K93GWotLXe4FqpErri0xkpLaD5.jpg',3.7220937499662687,3,'2026-09-10',2,NULL,NULL),(205588,'我们这种叛徒','Our Kind of Traitor','牛津大学导师佩里和女友嘉儿在怡人的安提瓜岛上享受美妙的假期时，偶然结识了俄国富豪迪马——一场精彩的网球比赛让佩里和迪马的人生轨迹有了交集。谁料，迪马竟是俄国犯罪组织的洗钱专家，组织内部斗争的残酷令迪马萌生去意，于是他希望通过佩里向英国情报部门传达寻求政治庇护的请求…… 自此，佩里和嘉儿渐渐脱离了正常的生活轨道，一系列政治阴谋、间谍行动扑面而来，就此开启了一场惊心动魄的跨国逃亡之旅：从法国巴黎到瑞士阿尔卑斯山，再到伦敦城里黑暗的走廊，哪里才是安全港湾？谁才是真正的叛徒？','Who Can You Trust With The Truth?',0,9930095,10.547959,6,160,108,'2016-05-05','en','/orgYOrCdrET4qmhLc8p8gmIm0xH.jpg',2.9552049697258194,3,'2026-09-10',2,NULL,NULL),(205596,'模仿游戏','The Imitation Game','根据Andrew Hodges所写的传记《艾伦·图灵》（Alan Turing: The Enigma）改编。艾伦·图灵是英国数学家、逻辑学家，二战中曾协助军方破解德国的著名密码系统Enigma，对盟军取得了二战的胜利有一定的帮助。图灵对于人工智能的发展有诸多贡献，著名的图灵机模型为现代计算机的逻辑工作方式奠定了基础。图灵是著名的同性恋之一，并因为其同性恋倾向而遭到迫害，使得他的职业生涯尽毁。1952年，他的同性伴侣协同一名同谋一起闯进了图灵的房子实施盗窃。图灵为此而报警。但是警方的调查结果使得他被控以“明显的猥亵和性颠倒行为”。他没有申辩，并被定罪。在著名的公审后，他被给予了两个选择：坐牢或荷尔蒙疗法。他选择了荷尔蒙注射，并持续了一年。在这段时间里，药物产生了包括乳房不断发育的副作用。1954年，图灵因食用浸过氰化物溶液的苹果死亡。很多人相信他是自杀。但是他的母亲极力争论他的死是意外，因为他在实验室里不小心堆放了很多化学物品。','The true enigma was the man who cracked the code.',14000000,233555708,145.364591,8,5723,113,'2014-11-14','en','/zSqJ1qFq8NXFfi7JeIYMlzyR0dx.jpg',4.546959567777029,3,'2026-09-10',2,NULL,NULL),(205775,'In the Heart of the Sea','In the Heart of the Sea','In the winter of 1820, the New England whaling ship Essex was assaulted by something no one could believe: a whale of mammoth size and will, and an almost human sense of vengeance.  The real-life maritime disaster would inspire Herman Melville’s Moby Dick.  But that told only half the story.  “Heart of the Sea” reveals the encounter’s harrowing aftermath, as the ship’s surviving crew is pushed to their limits and forced to do the unthinkable to stay alive.  Braving storms, starvation, panic and despair, the men will call into question their deepest beliefs, from the value of their lives to the morality of their trade, as their captain searches for direction on the open sea and his first mate still seeks to bring the great whale down.','Based on the incredible true story that inspired Moby Dick',100000000,93820758,50.767332,6.5,1276,122,'2015-11-20','en','/9TEDH6X28K7khJ4TH6sSJNeemN6.jpg',3.5768233623554004,3,'2026-09-10',2,NULL,NULL),(206197,'The Sisterhood of Night','The Sisterhood of Night','When a teenage girl says she\'s the victim of a secret network called The Sisterhood of Night, a quiet suburban town becomes the backdrop for a modern-day Salem witch trial.','The Salem Witch Trials remixed.',0,0,2.868942,6.5,31,104,'2015-04-10','en','/5s619nEEbpHj7E8BrypoQ2ghq5Q.jpg',2.597654613557135,3,'2026-09-10',2,NULL,NULL),(206213,'僵尸猎人','Zombie Hunter','菊花哥在片中大開殺戒并抱得美人歸',NULL,0,0,3.418372,3.5,34,93,'2013-07-25','en','/9FkPEWRpuMbOArFrklObdvxN099.jpg',2.5786724653353126,3,'2026-09-10',2,NULL,NULL),(206284,'Grace Unplugged','Grace Unplugged','A talented young singer and aspiring songwriter’s Christian faith and family ties are tested when she defies her worship-pastor father and pursues pop-music stardom in GRACE UNPLUGGED, a moving and inspiring new film that explores the true meaning of success.','Would you give up what you need... to get everything you want?',0,0,2.160586,6,24,102,'2013-10-04','en','/1woGP3DCEyfPuifRPSkrwDanOQm.jpg',2.536610048703311,3,'2026-09-10',2,NULL,NULL),(206296,'恋恋如歌','The Last Five Years','影片改编自杰森·罗伯特·布朗2002年的同名音乐剧。男主角杰米（《名声大噪》男星杰瑞米·乔登饰）邂逅了女主角凯西（肯德里克饰），彼时，他是初出茅庐的作家，她是前途光明的演员，两人坠入爱河，步入婚姻殿堂，度过一段快乐时光。  　　随后杰米的第一本书便大获成功，写作事业从此蒸蒸日上；而凯西却一直在俄亥俄州的小剧场默默表演，始终未能等到成名的机会。两人一度美满的婚姻也因此触礁，相爱五年，悲剧收场。','There are two sides to every love story.',0,0,5.563068,5.5,143,94,'2014-11-03','en','/dxTLKSTyGb5IXB64iNgU9AWAsXT.jpg',2.895512447741291,3,'2026-09-10',2,NULL,NULL),(206412,'Lisa Picard Is Famous','Lisa Picard Is Famous','A documentarian decides to follow the career of New York actress Lisa Picard, believing she is on the brink of fame. Instead, he bears witness to Lisa\'s continued, humorous, struggles as an actress, as well as the conflict that arises when Lisa\'s best friend Tate hits it big with an off-Broadway one-man show.',NULL,0,0,0.690089,4,1,90,'2000-05-14','en','/cVC2chP5nJxAOs5FIBeZJ6KfDfm.jpg',1.9850048091921908,3,'2026-09-10',2,NULL,NULL),(206563,'垃圾男孩','Trash','拉斐尔是一个拾荒男孩，他在垃圾山每天靠筛分垃圾为生。然而一个幸运而又不幸的一天将他的世界就此改变。这天他无意拾到了一个小钱包，一个充满谜团、线索并足以改变一切的钱包。然而不久，拉斐尔和他的朋友便遭到了腐败警方的追捕，三个男孩便与警方展开了斗智斗勇的追逐。渐渐地，他们逐渐发现这里面是一个关于一位死去的男人未完成的使命，三个拾荒男孩决心接手这份使命，他们将要独自面对危机四伏的世界......','You never know what you might find',0,0,14.637357,7.1,242,112,'2014-10-09','pt','/q8iDavUHwOxCDNMhmCMn4pMumLy.jpg',3.133889065319393,3,'2026-09-10',2,NULL,NULL),(206647,'007：幽灵党','Spectre','A cryptic message from Bond’s past sends him on a trail to uncover a sinister organization. While M battles political forces to keep the secret service alive, Bond peels back the layers of deceit to reveal the terrible truth behind SPECTRE.','A Plan No One Escapes',245000000,880674609,107.376788,6.3,4466,148,'2015-10-26','en','/zj8ongFhtWNsVlfjOGo8pSr7PQg.jpg',3.9523941271039695,3,'2026-09-10',2,NULL,NULL),(207769,'丧妖集聚','Banshee Chapter','自20世纪60年代起，美国政府便秘密进行各种药物试，许多人牵涉其中，许多人就此杳无音讯。供职于新闻界的女记者安妮·若兰特（凯蒂娅·温特 Katia Winter 饰）得知一个消息，她在大学时候的好朋友詹姆斯（麦克·麦克米兰 Michael McMillian 饰）服用了代号为DMT19的神秘药物，并用摄像机记录下来。可是食品中呈现恐怖怪异的画面，詹姆斯下落不明。警方怀疑视频的拍摄者雷尼（Alex Gianopoulos 饰）杀害了詹姆斯，但苦于找不到尸体无法定案，不久后雷尼也宣告失踪。安妮深感事件的蹊跷，于是决定只身调查朋友失踪的真相。他顺着詹姆斯在视频提供的线索，辗转找到了臭名昭著的极端主义小说家托马斯·布莱克伯恩（泰德·拉文 Ted Levine 饰）。','The experiments are over, the terror has just begun...',950000,0,7.310879,5.7,92,87,'2013-08-26','en','/nyXKB77RrItfUsAcgoIlXmUfged.jpg',2.820842851253544,3,'2026-09-10',2,NULL,NULL),(208134,'蠢蛋搞怪秀4：坏祖父','Jackass Presents: Bad Grandpa','约翰尼·诺克斯维尔饰演的男主角有个八岁的孙子，祖孙俩将开始一段横跨美国的旅程，一路上他们偷东西撞路牌婚礼葬礼四处搅局蠢事不断。','Real people. Real reactions. Real messed up.',15000000,151831537,27.165222,6,680,92,'2013-10-22','en','/82prA3bxdR5ZpdswZx5eAWN1iz0.jpg',3.296096282947396,3,'2026-09-10',2,NULL,NULL),(208763,'魔鬼的精神','Вий','十八世纪初，制图家格林在从欧洲向东方的科考旅途上。在翻越喀尔巴阡山脉的过程中，他迷失在森林深处一座被遗弃的村庄——只有偶然的意志和浓雾能将他带到这个被诅咒的地方。在这里生活的人不像任何他在旅途上曾经见过的人。这些通过深深的沟渠将自己与世界隔绝的人们，天真地相信这样便能摆脱不纯净，却不明白腐朽早已深入他们的灵魂，只是在等待时机爆发。这位唯物主义的科学家在梦里也不会预料到，在这里迎接他的是魔鬼的忠实仆人。','The truth is in you',26000000,0,7.182761,4.9,71,127,'2014-01-30','ru',NULL,2.7465467816971834,3,'2026-09-10',2,NULL,NULL),(208869,'Plastic','Plastic','Sam &amp; Fordy run a credit card fraud scheme, but when they steal from the wrong man, they find themselves threatened by sadistic gangster. They need to raise £5m and pull off a daring diamond heist to clear their debt.','HUSTLE. HEIST. REPEAT.',10,0,9.70276,6.1,86,102,'2014-04-30','en','/1jva5sTJnlz9g11Xm0GTxl6WAIk.jpg',2.8253056227873397,3,'2026-09-10',2,NULL,NULL),(209112,'蝙蝠侠大战超人：正义黎明','Batman v Superman: Dawn of Justice','Fearing the actions of a god-like Super Hero left unchecked, Gotham City’s own formidable, forceful vigilante takes on Metropolis’s most revered, modern-day savior, while the world wrestles with what sort of hero it really needs. And with Batman and Superman at war with one another, a new threat quickly arises, putting mankind in greater danger than it’s ever known before.','Justice or revenge',250000000,873260194,155.790452,5.7,7004,151,'2016-03-23','en','/5UsK3grJvtQrtzEgqNlDljJW96w.jpg',4.000220987025666,3,'2026-09-10',2,NULL,NULL),(209263,'Enough Said','Enough Said','Eva is a divorced soon-to-be empty-nester wondering about her next act. Then she meets Marianne, the embodiment of her perfect self. Armed with a restored outlook on being middle-aged and single, Eva decides to take a chance on her new love interest Albert — a sweet, funny and like-minded man. But things get complicated when Eva discovers that Albert is in fact the dreaded ex–husband of Marianne...',NULL,0,25288872,14.969093,6.6,348,93,'2013-09-18','en','/p5naJg0K8xF0h0HWEfiz6rc9lC4.jpg',3.186658257365381,3,'2026-09-10',2,NULL,NULL),(209274,'修女艾达','Ida','1962年，波兰。十八岁的见习修女安娜在即将宣誓皈依前，发现了一个可追溯至纳粹占领时期的黑暗家庭秘密。',NULL,2159280,10700000,13.265432,7.1,260,80,'2013-10-25','pl','/duBCjRYvx4qxwWR930C18F1wNyL.jpg',3.150321558498235,3,'2026-09-10',2,NULL,NULL),(209403,'脏话','Bad Words','片中饰演一位四十多岁的男子盖伊,他偶然发现了在全美拼字比赛(National Spelling Bee)的规则中有一个巨大的漏洞。结果盖伊在这项全部由中小学生参加的比赛中大获全胜。过程中，他与一名性格古怪的印度男孩结成了非一般的友谊。而一名女记者最终解开了盖伊参加这项比赛背后的真正动机。','The end justifies the means',9500000,7800000,14.105392,6.4,334,88,'2013-09-06','en','/hZo399sszo6QxEPOmqJiq5NhQeU.jpg',3.155628816711315,3,'2026-09-10',2,NULL,NULL),(209451,'Jersey Boys','Jersey Boys','From director Clint Eastwood comes the big-screen version of the Tony Award-winning musical Jersey Boys. The film tells the story of four young men from the wrong side of the tracks in New Jersey who came together to form the iconic 1960s rock group The Four Seasons. The story of their trials and triumphs are accompanied by the songs that influenced a generation, including “Sherry,” “Big Girls Don’t Cry,” “Walk Like a Man,” “Rag Doll,” and many more.',NULL,40000000,67347013,14.199933,6.8,255,134,'2014-06-05','en','/mNB6RjZBvrizSG1BiPoS3PVw8fo.jpg',3.123809303487191,3,'2026-09-10',2,NULL,NULL),(210577,'消失的爱人','Gone Girl','结婚五周年纪念日当天，尼克·邓恩回到家中，却发现妻子艾米离奇失踪，屋内还留下了不同寻常的痕迹。随着警方展开调查，一个个疑点逐渐指向尼克，而艾米的失踪也在媒体持续报道下迅速成为全国关注的案件。面对越来越强烈的怀疑，尼克原本展现在众人面前的幸福婚姻开始出现裂缝，他与艾米之间不为人知的矛盾也一点点浮出水面。妻子究竟去了哪里，这段看似美满的婚姻背后又隐藏着怎样的真相……','You don\'t know what you\'ve got \'til it\'s...',61000000,369330363,143.041543,7.9,5862,145,'2014-10-01','en','/ts996lKsxvjkO2yiYG0ht4qAicO.jpg',4.521527651353463,3,'2026-09-10',2,NULL,NULL),(210860,'贵族大盗','Mortdecai','查理·摩迪凯（约翰尼·德普 Johnny Depp 饰）白天是位生活浪漫不羁，酷爱美食的伦敦艺术品商人，到了夜晚是艺高人胆大的怪盗，经常边做买卖，边偷该偷的艺术品，虽然从不失手，但总是遇到光怪陆离的谋杀案。\r 　　智商过人的他平日在黑白两道间游刃有余，吃香喝辣得心应手。但唯一能把他吃得死死的，就是他心爱的老婆（格温妮斯·帕特洛 Gwyneth Paltrow 饰）。某日一名修复西班牙画家戈雅名画的师傅离奇暴毙，画作不翼而飞。摩迪凯觊觎寻回画作的优沃赏金，便和贴身保镖展开一场横跨伦敦、莫斯科、洛杉矶的寻画大作战。\r 　　其间他遇到形形色色的怪异坏蛋：以电击人为乐的俄罗斯黑道、不想当妈妈乖宝贝的中东革命份子、贪得无厌的美国富商和他性欲旺盛的女儿。此外，他还得注意紧迫盯人的英国军情五处探员马特兰（伊万·麦克格雷格 Ewan McGregor 饰），这位从大学就暗恋着他老婆的情敌，始终锲而不舍地假藉办案之名，趁机接近他老婆……','Sophistication Has a Name.',60000000,30418560,52.417529,5.4,1055,106,'2015-01-21','en','/qaUNBrdeISWnIGPfj2po8PQEZAY.jpg',3.3388819157550857,3,'2026-09-10',2,NULL,NULL),(211086,'信仰连系','Faith Connections','A filmmaker\'s insight into the biggest gathering on earth -the Kumbh Mela.',NULL,550000,0,0.48088,4.2,3,115,'2013-11-21','hi','/cPdgSTu7SV9HCxuBujWSbm3RUbZ.jpg',2.1335574070292505,3,'2026-09-10',2,NULL,NULL),(211557,'Vessel','Vessel','Vessel is the story of the passengers of Flight 298, a red-eye on its way from Boston to San Francisco. Midway through the flight the passengers encounter an otherworldly force and are subsequently thrown into a fight for their lives. The story focuses on Danny (an everyday traveler), Emma (a flight attendant), Chloe (an unattended underage passenger) and Jim and Murray (the two pilots). Written by Anonymous',NULL,0,0,0.322553,5.9,8,14,'2012-10-28','en','/tTByGBfliHYjOa7qmUzWx6EJwbR.jpg',2.310947532932325,3,'2026-09-10',2,NULL,NULL),(211672,'小黄人大眼萌','Minions','从地球诞生之初，一种奇怪的生物便出现在这颗蓝色的星球上。他们不断进化、蜕变，终于成为我们所熟悉的小黄人的模样。小黄人们毕生寻找邪恶的老大，以成为他的部属为荣，但是千百万年来的努力最终化成一场空。经历了一段长久的沉寂，名叫凯文的小黄人决定再度上路，他带着热爱音乐的斯图尔特、成事不足败事有余的鲍勃，漂洋过海来到了1968年的美国。三个小家伙偶然听说奥兰多即将召开“恶人大会”，于是忙不迭地赶了过去，并且阴差阳错成为女魔头斯嘉丽·杀人狂 的随从。很快斯嘉丽交给他们一个任务，那就是窃取英国女王的王冠。不知轻重的小家伙们笑嘻嘻地出征，等待他们的将是前所未有的大冒险…','Before Gru, they had a history of bad bosses',74000000,1156730962,875.581305,6.4,4571,91,'2015-06-17','en','/dr02BdCNAUPVU07aOodwPYv6HCf.jpg',5.738202114601813,3,'2026-09-10',2,NULL,NULL),(211954,'非常父女档','No se aceptan devoluciones','瓦伦丁是阿卡普尔科（墨西哥南部海滨度假城市）远近闻名的花花公子，直到有一天他发现某位旧情人把他们新出生的孩子扔在他家门口便消失之后，他的快活日子结束了。瓦伦丁带着孩子来到洛杉矶，起初是为了寻找孩子的母亲，结果只能和孩子两个人租了一间公寓在那里下来。孩子取名叫玛姬。六年过去了，玛姬渐渐长大，瓦伦丁也成为了好莱坞最受欢迎、薪水最高的特效演员之一，绰号“钢筋男子”。他总把玛姬带在身边，玛姬成了他的经纪人','Life doesn\'t care if you\'re ready.',5500000,99067206,9.59729,7.5,205,115,'2013-07-20','es','/zZyaSXJaGAFpoIkEZoakYe6ygag.jpg',3.1040478161542295,3,'2026-09-10',2,NULL,NULL),(214756,'泰迪熊2','Ted 2','泰迪与超市收款员泰米琳恩恋情升温，决定结婚生子！可是问题来了，泰迪是玩具不可能有孩子，不过它可以借精生子，但政府要求泰迪证明自己是符合法律定义的人类，否则不能拥有自己的孩子，于是泰迪与好友约翰不断东奔西走，几经辛苦找到女律师萨曼莎帮忙，坚决要争取“熊性”平等权，究竟泰迪最后能否成功挑战法律，捍卫自己的幸福？','Ted is Coming, Again.',68000000,217022588,68.734513,6.2,2463,115,'2015-06-25','en','/38C91I7Xft0gyY7BITm8i4yvuRb.jpg',3.7068394464375523,3,'2026-09-10',2,NULL,NULL),(215211,'摩纳哥王妃','Grace of Monaco','1962年，格蕾丝（妮可·基德曼 Nicole Kidman 饰）大婚已经有六年，她的一颦一笑已经成为20世纪王妃的经典影像，但此时，她正在力图使自己的过去与现在和解。她渴望重返大银幕，却因如今身兼三职——两个孩子的母亲、欧洲公国的王妃、雷尼尔三世（蒂姆·罗斯 Tim Roth 饰）的妻子——而踌躇不前。  　　希区柯克（罗杰·阿什顿-格里菲斯 Roger Ashton-Griffiths 饰）建议她重返好莱坞，这个提议令格蕾丝陷入苦恼。当时丈夫雷尼尔的现代化改革措施遭到了法国总统戴高乐的抵制，戴高乐要对摩纳哥课以重税，并推动武力以保证此项措施得以实行。  　　逐渐膨胀的国际性危机和法国迫近的入侵脚步，不仅是格蕾丝家庭、婚姻、国家的危机，也是她个人生活的危机。这是一个远离美国家乡的银幕明星不得不做出艰难决定的时刻，是回去做那个受全球瞩目和万千影迷爱戴的大明星，还是拥抱她的新身份，拥抱她对于丈夫、子女，以及这个世界第二小却是她的家、她的王国的责任……',NULL,30000000,0,10.958697,5.8,195,103,'2014-05-14','en','/pOjmUjPMrxphbyjWO33HVZfZG8W.jpg',2.985138295632921,3,'2026-09-10',2,NULL,NULL),(215881,'毛绒','Plush','哈蕾（艾米莉·布朗宁 Emily Browning 饰）是一位小有名气的乐队主唱，成功的事业，幸福的婚姻，一对可爱又懂事的双胞胎，坐拥这一切的哈蕾无疑成为了朋友和同事们羡慕的对象，就连她自己也觉得受到了上天的眷顾。然而，不幸还是发生了，哈蕾的哥哥卡特（凯姆·吉甘戴 Cam Gigandet 饰）吸毒成瘾最终命丧黄泉，这件事情让哈蕾陷入了悲伤的深渊无法自拔。  就在此时，一位名叫恩佐（沙维尔·塞缪尔 Xavier Samuel 饰）的神秘男子以吉他手的身份出现在了哈蕾的身边，很快，英俊帅气的恩佐就吸引了哈蕾的注意，也让她逐渐走出了阴霾。然而，随着时间的推移，哈蕾渐渐发现，恩佐有着不可告人的过去和一大堆的秘密，知道了这些之后，她又该如何面对这个曾经帮助过自己的男人呢？','There\'s a fine line between love and obsession.',0,0,5.099368,5.4,40,98,'2013-09-13','en','/a8J9q7YFi92fTKibv1rMAaZl903.jpg',2.640694010558889,3,'2026-09-10',2,NULL,NULL),(215918,'1982','1982','1982, a film inspired by true events at the onset of the crack epidemic in Philadelphia, tells the story of a father and his efforts to protect his gifted daughter from the insidious epidemic which has literally come home via her drug-addicted mother. As his wife becomes more distant and unreliable, he struggles to raise his daughter on his own, while still striving to help his wife become clean. In the process, he learns some hard truths about his marriage and his life, which will ultimately test him as a parent, a husband, and a man',NULL,1000000,0,0.175885,5,1,90,'2013-12-31','en','/suJnawPMpozKwbOhQn0qqHkJoIX.jpg',1.9842415458975844,3,'2026-09-10',2,NULL,NULL),(215924,'神奇的鲶鱼','Los insólitos peces gato','克劳蒂（Ximena Ayala 饰）一直过着形单影只无亲无故的生活，一场肠胃炎将她送进了医院，克劳蒂就此结识了隔壁病床的女子玛莎（莉萨·欧文 Lisa Owen 饰）。玛莎有四个孩子，这四个孩子分别来自于四个不同的父亲，虽然身体里留着不一样的血脉，但一家人相处起来意外的和谐热闹。\r 　　虽然克劳蒂并不像让玛莎知道自己无依无靠，但聪明的玛莎还是通过观察判断出了克劳蒂孤单的处境。玛莎热情的邀请克劳蒂出院后来自己家里和孩子们同住，禁不住玛莎的热情，克劳蒂答应了这个请求。就这样，克劳蒂和玛莎开始了同居生活。刚开始，克劳蒂被这一家子闹腾的头都要炸了，但随着时间的推移，她开始真正的融入了这个家庭之中。',NULL,1300000,0,1.473405,5.7,17,87,'2013-08-10','es','/111QEZPK95JUiRSZ8febedf5uln.jpg',2.4619612511097664,3,'2026-09-10',2,NULL,NULL),(216015,'五十度灰','Fifty Shades of Grey','安娜是一名校报记者，某日，她代替朋友凯特去采访名为格雷的男子。格雷年轻而又英俊，是大财团的董事长，关于他的新闻几乎寥寥无几，这让这位多金的男人显得更加神秘。格雷很快就迷恋上了安娜的聪慧和青涩，安娜亦不自觉的被格雷强大的气场所吸引，随着时间的推移，两人之间产生了感情，然而，让安娜没有想到的是，她发现了格雷极力想要隐藏的惊天秘密，并且成为了格雷的“猎物”。就这样，安娜陷入了格雷一手编织的情网之中，在激情，性感和缠绵之中不可自持，越陷越深。','Are you curious?',40000000,571006128,98.755657,5.2,3254,125,'2015-02-11','en','/yyygvyW4etXl7sWjQPna2Yb0Fob.jpg',3.5919306640838813,3,'2026-09-10',2,NULL,NULL),(216282,'不惧风暴','Into the Storm','故事背景设定在一个名为西弗敦的小镇，在同一天中，史无前例的多个龙卷同时席卷这个小镇，在这些难以预测且极度致命的龙卷风群袭击下，整个小镇面临灭顶之灾。但专门研究龙卷风的追风人预测，更糟糕的情况还尚未真正到来。大多数居民都在紧迫寻找避难所，而这些追风者们却“逆向而行”赶到龙卷漩涡前，测试需要走多远才能拍到这千载难逢的极端时刻。','Prepare to go',50000000,160602194,20.566554,5.8,817,89,'2014-08-06','en','/eTxwwW5Plfu50KsWKFFhybepL3v.jpg',3.287558536143744,3,'2026-09-10',2,NULL,NULL),(217708,'马与人','Hross í oss','一个关于马和人之间人性的乡村爱情故事。爱与死交织在一起，带来可怕的后果。通过马的感知，揭示了乡村人民的命运。',NULL,10,11,1.617943,6.9,26,85,'2013-08-30','is','/gLLnT8K5EbfsxqH4PrC4R6UrkIA.jpg',2.5613007558881375,3,'2026-09-10',2,NULL,NULL),(218043,'末日迷踪','Left Behind','影片改编自同名小说，讲述由凯奇扮演的机长驾驶飞机在万米高空突遇诡异气象，同时地球上成百万人神秘消失。凯奇要将破损的飞机迫降，地面上他的女儿也要寻找失踪的妈妈和弟弟。','The End Begins',16000000,19682924,33.452469,3.7,392,110,'2014-10-03','en','/e9hBaMyi03IAVX7RamndWOkXZ8h.jpg',2.954164153889275,3,'2026-09-10',2,NULL,NULL),(218500,'格雷的歌谣','The Ballad of Gregorio Cortez','The entire cause of the problem evolves from the use of a deputy to translate. His command of Spanish is inadequate and he mistranslates what a witness tells the sheriff as to whether the real perpetrator of the crime is riding a mare (yegua) or a male horse (caballo). This error results in destroying a family and the death of an innocent man.',NULL,0,0,0.592821,0,0,104,'1983-08-19','en','/nU5xLRQBn1nLqhW9UumdRQTGjbF.jpg',1.8351365051421038,3,'2026-09-10',2,NULL,NULL),(218778,'亚历山大和他最糟糕的一天','Alexander and the Terrible, Horrible, No Good, Very Bad Day','二儿子感觉自己每天都过得糟透了，但家人却每天都有好消息，过的很自在。二儿子在生日的前天晚上自己为自己庆祝并无意许下了想让家人也过一天糟糕日子，结果第二天真的实现了：妈妈的工作不顺利，爸爸的面试也不顺利，姐姐感冒参演皮特潘失败，哥哥长了痘痘，驾照考试失败还把车给撞报废，小弟弟吃了满口马克笔。但这一连串事情发生后，大家觉得团结了起来。最后二儿子的生日party如期举行，妈妈工作也得以挽回，爸爸面试最终也成功了。结局很欢乐！','One day can change everything.',28000000,100654149,22.14595,6.1,493,81,'2014-10-08','en','/pAqjFZdXpRYrz4x8y8DWTi8OiJK.jpg',3.2297049017428283,3,'2026-09-10',2,NULL,NULL),(219716,'Sparkler','Sparkler','Melba is a Californian trailer-park girl who is told to look for three kings by a phone psychic, and when she meets three guys - Trent, Brad and Joel traveling to Las Vegas, she decides they are those kings and joins them on a trip. In Vegas she meets her old high school pal Dottie.',NULL,0,0,0.547654,0,1,96,'1999-03-19','en','/qPG70Y2ZnFudN5Ip85YfQua3n4P.jpg',1.9830343403117492,3,'2026-09-10',2,NULL,NULL),(220488,'非常幸运','非常幸运','一次偶然的机会，在闺蜜李莉（姚晨饰）和陆小夕（林心如 饰）的怂恿下，宅女漫画家苏菲（章子怡饰）踏上了去往新加坡的旅程，遇见了她梦寐以求的“邦德男人”大卫（王力宏饰）。然而，在一系列歪打误撞之后，苏菲搅黄了“特工”大卫的计划。原来大卫和助手阿宝（郑恺饰）正在追查世界上最大的钻石“幸运星”的下落……然而，大卫不得不与苏菲配合才能完成这次任务，于是两人踏上了令人“啼笑皆非”的冒险之旅。  　　一路上，苏菲扮演各种角色，上演无数惊险而喜剧的桥段。对自己的心上人，当苏菲自以为即将得手时，却发现头号反派黑寡妇（关颖饰）竟原是大卫的准前妻！在整个迷局里，苏菲只是其中一颗小小的棋子……这一切到底是真是假，大卫的感情又是真是假？苏菲到底能否拯救她的爱人？',NULL,0,0,1.86453,4.3,8,114,'2013-09-17','zh','/bHYymfOg9D49Id3R6R1WWE8tpBm.jpg',2.3092553696254665,3,'2026-09-10',2,NULL,NULL),(220490,'Her Cry: La Llorona Investigation','Her Cry: La Llorona Investigation','Crew of \"Paranormal Legends\" went to film their 4th season at the place where La Llorona (Weeping woman) was reportedly seen. Only thing that\'s left was 17 hours of tapes and 2 camcorders.',NULL,0,0,0.056459,0,0,89,'2013-04-19','en','/r0DF0V4PVzTAgqVxI2i9c4Okruf.jpg',1.8339113487872636,3,'2026-09-10',2,NULL,NULL),(222250,'A True Story','A True Story','Mike and Matt own nothing and share everything, including their life\'s work, a screenplay, which seems to be their only escape from the harsh reality that is the Hollywood machine.',NULL,0,0,0.970351,6.8,2,96,'2013-09-20','en','/wkcJMCPQyGZ9BePFkyM6jU69Xd0.jpg',2.075124132187659,3,'2026-09-10',2,NULL,NULL),(222649,'Rosewater','Rosewater','In 2009, Iranian Canadian journalist Maziar Bahari was covering Iran\'s volatile elections for Newsweek. One of the few reporters living in the country with access to US media, he made an appearance on The Daily Show with Jon Stewart, in a taped interview with comedian Jason Jones. The interview was intended as satire, but if the Tehran authorities got the joke they didn\'t like it - and it would quickly came back to haunt Bahari when he was rousted from his family home and thrown into prison. Making his directorial debut, Jon Stewart tells the tale of Bahari\'s months-long imprisonment and interrogation in this powerful and affecting docudrama featuring a potent and performance by Gael García Bernal recounting Bahari\'s efforts to maintain his hope and his sanity in the face of isolation and persecution-through memories of his family, recollections of the music he loves, and thoughts of his wife and unborn child.',NULL,0,0,5.75555,6.5,98,103,'2014-11-07','en','/bhhWG0BtWzJt1AC7mgvcqIFDcCX.jpg',2.8585281413651864,3,'2026-09-10',2,NULL,NULL),(222899,'昨夜风流','About Last Night','迈克尔·伊雷饰演的男主角丹尼和女友黛比（乔伊·布赖恩特　饰演）是一对普通恋人，而他们的朋友--凯文·哈特饰演的本尼和女友琼（雷吉娜·赫尔　饰演）则是一对“亡命鸳鸯”，沉迷于夜店、飞车和性生活。丹尼和黛比的恋情无比寻常，偶遇、相恋，同居三部曲一气呵成，随后两人开始争执，黛比在公寓里养狗令丹尼十分不爽。而本尼和琼则依靠夜生活来维持彼此的感情。','It\'s about compromise. It\'s about love. It\'s about a good wingman.',12500000,49002684,11.828068,6,210,100,'2014-02-14','en','/z3dVYQtxXldDawz7d15wqt2PQLe.jpg',3.015381495846238,3,'2026-09-10',2,NULL,NULL),(222935,'星运里的错','The Fault in Our Stars','海泽尔（谢琳·伍德蕾 Shailene Woodley 饰）是一名十六岁的美丽少女，正处在黄金年代的她本该和其他同龄人一样尽情享受生命和青春带来的快乐与希望，但无情的病魔找上了海泽尔，她是一名肺癌患者。\r 　　尽管最近病情有所好转，但海泽尔的心情却并没有因此而轻松半分，癌症随时可能复发的阴影和无法中断的治疗如影随形，让海泽尔对生命几乎失去了所有的热情和希望。一次偶然中，海泽尔在癌友互助会中结识了名叫奥古斯都（安塞尔·埃尔格特 Ansel Elgort 饰）的英俊男孩，他所患的是骨癌。两个境遇相似的年轻人很快就越走越近，他们在一起，探索着上帝留给他们的小小的一片世界，海泽尔也因此看到了未来和希望。 ©豆瓣','One Sick Love Story',12000000,307166834,74.358971,7.6,3759,125,'2014-05-16','en','/kcVuktIlrn9SAN1uBmPDnocTQmF.jpg',4.165011351013612,3,'2026-09-10',2,NULL,NULL),(222936,'阿罗哈','Aloha','事业有成的军火承包商布莱恩·吉尔克雷斯特，被派遣到他创下职业生涯最高峰的地方——夏威夷火奴鲁鲁军事基地，监督开发一项先进的间谍卫星，并被安排与一名冷酷无趣的女飞行员丽莎·吴 共事。 布莱恩联系到了挚爱的前女友，并纠结在和前女友的感情漩涡中。但随着相处的时间越来越长，布莱恩开始对工作伙伴丽莎产生好感，自己也在不知不觉中发生蜕变……','Sometimes you have to say goodbye before you can say hello.',37000000,26250020,29.652536,5.2,692,105,'2015-05-27','en','/sMW8PdcYaN3GWxNAHxvNABPEAj8.jpg',3.1885009434737284,3,'2026-09-10',2,NULL,NULL),(223485,'西部慢调','Slow West','19 世纪末，16 岁男孩杰（柯蒂·斯密特-麦菲 Kodi Smit-McPhee 饰）来到美国，企图横跨北美寻找自己的心爱的姑娘，一名神秘的旅人塞勒斯（迈克尔·法斯宾德 Michael Fassbender 饰）加入杰的行列，两人一同向西行进，不料在美国西部荒地，被人盯上……','Wanted Dead or Dead',0,229094,14.936661,6.6,367,84,'2015-04-16','en','/j3PmbRZvf5KpNbapSjn8b0CpD6a.jpg',3.1998115829064893,3,'2026-09-10',2,NULL,NULL),(223702,'香肠派对','Sausage Party','故事从食物视角出发，讲述单纯的它们被采购回家，没想到会面临被生吞、活剥、碎尸的危险境遇。香肠组成逃亡小分队，誓要将秘密公布于众！','Always use condiments',19000000,140752617,66.242737,5.6,2238,83,'2016-07-11','en','/3sObp4Jz7VcJ5y56mXyqV5J6Aei.jpg',3.54410097122319,3,'2026-09-10',2,NULL,NULL),(224141,'魔法黑森林','Into the Woods','黑森林有一个村庄，三个经典童话按照既定脉络展开：饱受压迫的灰姑娘（安娜·肯德里克 Anna Kendrick 饰）想参加国王的舞会，但是坏心眼的继母和姐妹们想尽办法折磨她；杰克（丹尼尔·赫特斯通 Daniel Huttlestone 饰）将那头不再产奶的白色乳牛当做朋友，而妈妈却命令他将牛卖掉；小红帽（莉拉·克劳馥 Lilla Crawford 饰）装满好吃的面包，一蹦一跳朝着外婆所在的黑森林深处走去。小红帽刚刚离开，邪恶的女巫（梅丽尔·斯特里普 Meryl Streep 饰）突然出现，她对面包师（詹姆斯·柯登 James Corden 饰）施以可怕的诅咒，除非他在三天后能准备好四样东西：白色乳牛、红色斗篷、金黄色头发以及黄金鞋。  　　在命运的驱使下，童话人物聚首黑森林…… ©豆瓣','Be careful what you wish for...',50000000,212902372,65.90161,5.6,1652,125,'2014-12-25','en','/87QAZwRTapLovmgvf321zFiBPtW.jpg',3.4867272891331966,3,'2026-09-10',2,NULL,NULL),(224569,'Taxman','Taxman','After a homocide that the police believe is over gasoline theft, a tax investigator discovers the Russian mafia is involved and that they are stealing millions in gasoline tax money. Only one rookie cop is willing to believe him and together they must get the evidence they need or die trying.','In life only two things are certain, death and taxes.',0,0,0.964802,2,1,104,'1999-09-16','en','/y6uvUy5wgF21wcIN3lY3G8dkjab.jpg',1.984809748087158,3,'2026-09-10',2,NULL,NULL),(225235,'迷途终返','Географ глобус пропил','维克多·斯路兹是一名中学的地理老师，他迷失在慌乱的现实世界找不到自我，于是他开始了到乌尔拉的漂流之旅，遭遇了狂风暴雨，在大自然中各种历险后，他终于找到自我，一个真实的维克多·斯路兹。  Victor Sluzhkin,a geographer teacher in a secondary school,gets lost in the reality life.He goes on a rafting tour to the Urals.Accompanied by wild,adventure-seeking adolescents,faced with the numerous grim surprises of the nature,Geographer is poised to find himself and his own truth.',NULL,0,4037782,1.876621,7.3,23,120,'2013-07-26','ru',NULL,2.539077790402802,3,'2026-09-10',2,NULL,NULL),(225565,'尴尬时刻','That Awkward Moment','三个曼哈顿单身汉的故事。因为埃夫隆的情伤，他的好基友决定跟他“同甘共苦”保持单身，聊天喝酒泡吧，三人的单身生活过得不亦乐乎。但是桃花运总在你意想不到的时刻降临，三人开始各自坠入情网，眼看着单身计划行将瓦解，但他们还要在基友面前佯装单身浪子，由此引发了一系列笑料。','When you realize getting some means wanting more.',8000000,26049082,37.821106,6.1,1004,94,'2014-01-29','en','/tjDAdesZNYFyRNnZvLT0osc7S2t.jpg',3.419064248988594,3,'2026-09-10',2,NULL,NULL),(225574,'空中营救','Non-Stop','曾任警察、如今担任美国联邦空警的比尔·马克斯，在一架从纽约飞往伦敦的跨大西洋航班上执行安保任务。飞行途中，他突然收到一个未知号码发来的神秘短信，对方似乎对他在机上的一举一动了如指掌，并要求向一个秘密账户转入1.5亿美元，否则每隔20分钟就会有一名乘客死亡。面对机舱内百余名身份各异的乘客，比尔必须在有限时间里找出隐藏其中的威胁者。然而随着调查不断深入，越来越多的疑点和证据反而开始指向比尔本人，让原本肩负保护乘客职责的他逐渐被怀疑成这场劫机事件的制造者……','The hijacking was just the beginning.',50000000,222809600,83.295796,6.8,2268,106,'2014-01-26','en','/Nkgaj3X0W2jHQ1TzHEgWFpN3kJ.jpg',3.858049862210267,3,'2026-09-10',2,NULL,NULL),(225886,'Sex Tape','Sex Tape','When Jay and Annie first got together, their romantic connection was intense – but ten years and two kids later, the flame of their love needs a spark.  To kick things up a notch, they decide – why not? – to make a video of themselves trying out every position in The Joy of Sex in one marathon three-hour session.  It seems like a great idea – until they discover that their most private video is no longer private.  With their reputations on the line, they know they’re just one click away from being laid bare to the world... but as their race to reclaim their video leads to a night they\'ll never forget, they\'ll find that their video will expose even more than they bargained for.','A movie about a movie they don\'t want you to see.',40000000,126069509,72.641296,5.3,1695,97,'2014-07-17','en','/k0E9g85XYbxxFbnUprHJKyy3Ayn.jpg',3.4439156128356876,3,'2026-09-10',2,NULL,NULL),(226354,'圣诞奇迹蜡烛','The Christmas Candle','格拉伯里(Gladbury)是一个平凡无奇的小村庄，但一个神奇的传说一直在格拉伯里的住民中流传：每隔25年就会有一位天使造访格拉伯里的蜡烛匠人家，并为一根新蜡烛施加魔法。将那根具有魔力的蜡烛点燃的人将会在平安夜受到意想不到的奇迹赐福。这个传说一直延续着，但在1890年的钟声敲响之时，大卫·里士满（汉斯·麦瑟逊 饰）这位年轻的怀疑论者牧师风尘而至，这一传说也受到了遭破除的威胁。格拉伯里的蜡烛匠师爱德华·海丁顿（西尔维斯特·迈考伊 饰）要为这份无形的家族遗产挺身而出。一旦蜡烛传说不复存在，格拉伯里将会迎来史上最为惨淡的圣诞节......','Believe the Miracle',0,0,1.799504,5.8,8,100,'2013-11-22','en','/7PpESUrwE2du9tWTjbQia4j9IKs.jpg',2.313995283266852,3,'2026-09-10',2,NULL,NULL),(226458,'鬼附身','Exeter','建立于一百年前的埃克赛特疗养院曾经收治许多心理有障碍的青少年，此后入院治疗的病患逐渐攀升，医疗条件则每况愈下，甚至不断爆出青少年被虐待致死的丑闻。如今该疗养院早已废弃，此地闹鬼的传闻却越传越凶，当然这无法吓退那些寻求刺激、胆大妄为的年轻人。某天，帕特里克（Kelly Blatz 饰）和好友罗里（Michael Ormsby 饰）、诺尔斯前往该疗养院参加这里举行的狂欢派对。年轻人们寻欢作乐，各取所需。一夜狂欢过后，从酒精麻醉中渐渐醒来的年轻人们闲聊打屁。稍后众人挑战禁忌，举行招魂仪式，结果见到了超自然的一幕。','nederlands',0,0,3.619167,4.7,79,91,'2015-01-16','en',NULL,2.7521308687573374,3,'2026-09-10',2,NULL,NULL),(226486,'塔米的旅行','Tammy','塔米（梅丽莎·麦卡西 Melissa McCarthy 饰）岁数不小，生活却越过越惨淡，一场意外让她失去了爱车，之后，在工作中又惨遭上司解雇。接二连三的打击和挫折让她心灰意冷，当她想要在丈夫身上寻求温暖和安慰时，却发现丈夫竟然有了情人，更让塔米崩溃的是，这位情人竟然就住在他们家隔壁。  　　人生走入了死胡同，塔米感到走投无路，正当她陷入绝望之时，她的外婆帕尔（苏珊·萨兰登 Susan Sarandon 饰）来到了塔米的身边。然而，帕尔的到来并没有给塔米带来快乐，因为帕尔是一个酗酒又粗鲁的老太太。帕尔让塔米带她去尼加拉瓜大瀑布旅行，就这样两人踏上了注定不会平静的旅途。','She hit the road. The road hit back.',20000000,100525432,21.657563,5,500,97,'2014-07-02','en','/efsVMziwE9BNTDX5fNmYVA5oAzJ.jpg',3.097314117863584,3,'2026-09-10',2,NULL,NULL),(226857,'无尽的爱','Endless Love','年轻的大卫和朱迪爱上了彼此，但对于他们的父母来说，这段身份悬殊的感情太不合适。为了阻止这段爱情，双方的父母试图将朱迪和大卫分开，不让他们见面。这对大卫并不起效，他点燃了自家的房子，随后被父母送走。这段初恋就此结束了..','Say Goodbye to Innocence',20000000,34077920,27.256849,6.7,542,103,'2014-02-12','en','/7WDqvNmy4p6IJx8JjvzOtaV2IRr.jpg',3.3386215130081003,3,'2026-09-10',2,NULL,NULL),(227156,'记忆传授人','The Giver','主人公是一个叫乔纳思的少年，他生活在一个看似非常完美的社区里，没有战争、没有灾难、没有痛苦。在这里，人们的生活都被安排得井井有条，他们不用决定工作，不用决定配偶，一切都已经被社区领导者决定好了。然而，这个世界里没有记忆、感情、颜色以及音乐，人们也没有选择的权力。年满十二岁的时候，少年乔纳思 被选中担任下一任“记忆传授人”，跟从上一任“传授人” 接受训练，将来他将一个人去承担整个社会该有的记忆。他必须独自承受痛苦、恐惧和孤单，同时也知道了什么是温暖、幸福和爱，就此得到了他以前所不曾有过的经验。而当他知道的越多，越发现这个世界的虚假，于是有了想要离开的念头……','Search for truth. Find freedom.',25000000,66980456,53.811461,6.4,1798,94,'2014-08-11','en','/pvTw13DwulwrJTFRXWfUEPuStxD.jpg',3.6455729448381007,3,'2026-09-10',2,NULL,NULL),(227159,'恶老板2','Horrible Bosses 2','故事紧接第一集，Nick、Dale和Kurt这三个难兄难弟决定自己当老板，但是再次被狡猾的投资人欺骗。眼看着合同成了一纸空文，三人迫不得已决定绑架投资人的儿子，以重新夺回对公司的控制权……','New Crime. Same Tools.',42000000,107670357,82.185281,6.1,1536,108,'2014-11-26','en','/6w7GyC1tx2H8LrerZIxtaedDmnF.jpg',3.6122810199707214,3,'2026-09-10',2,NULL,NULL),(227306,'坚不可摧','Unbroken','二次世界大战时，前奥林匹克长跑选手路易·赞贝里尼（杰克·奥康奈尔 Jack O\'Connell 饰）驾驶的战机意外坠毁，路易与其他两位同机组员在海上漂流了47天之后，遭到日本海军长期囚禁，并受其中一位军官渡边长野（石原贵雅 Miyavi 饰）残忍虐待，甚至到战争结束后这个痛苦的梦魇仍挥之不去，他经常作恶梦、酗酒，在看似失去一切的时候，信仰解救了他，他最后更前往日本希望与渡边长野会面，愿意原谅他……  　　本片由安吉丽娜·朱莉执导并担任制片，改编自前奥运会长跑运动员的路易·赞贝里尼的真实经历，浓缩他从街头顽童、奥运选手以及二战期间个人跌宕起伏的经历，97岁的路易亲自出镜讲解。','Survival. Resilience. Redemption.',65000000,163442937,43.055253,7.3,1400,137,'2014-12-25','en','/vAlHUjHwLWMV5mg4epGR9WSIfiy.jpg',3.7396544299612144,3,'2026-09-10',2,NULL,NULL),(227348,'Paranormal Activity: The Marked Ones','Paranormal Activity: The Marked Ones','Seventeen-year-old Jesse has been hearing terrifying sounds coming from his neighbor’s apartment, but when he turns on his camera and sets out to uncover their source, he encounters an ancient evil that won’t rest until it’s claimed his very soul.','You\'re one of us now.',5000000,86362372,19.984477,5.2,449,84,'2014-01-01','en','/xhxVyRVrJhd4nPNeOi4Vj4bm7Zh.jpg',3.1016332477502226,3,'2026-09-10',2,NULL,NULL),(227707,'The Adventurer: The Curse of the Midas Box','The Adventurer: The Curse of the Midas Box','17-year-old Mariah Mundi\'s life is turned upside down when his parents vanish and his younger brother is kidnapped. Following a trail of clues to the darkly majestic Prince Regent Hotel, Mariah discovers a hidden realm of child-stealing monsters, deadly secrets and a long-lost artifact that grants limitless wealth – but also devastating supernatural power. With the fate of his world, and his family at stake, Mariah will risk everything to unravel the Curse of the Midas Box.','The new name for adventure.',25000000,6399,8.842722,5.1,73,99,'2013-12-05','en','/biQxzNzKANLbJ2flyIezV954TGD.jpg',2.760926094035157,3,'2026-09-10',2,NULL,NULL),(227719,'年鉴计划','Project Almanac','影片讲述美国几名青少年无意间发现了一个时光机器，他们在时光旅行中改变着自己的过去和未来，但是在他们随意改写了历史之后，周围的世界也发生了不可思议的变化。','Today is better the second time around',12000000,32248241,32.940597,6.4,933,106,'2015-01-30','en','/flFupyCLKnaJuL8WDBZK4Gg2EIw.jpg',3.4426153642508424,3,'2026-09-10',2,NULL,NULL),(227735,'海豚的故事2','Dolphin Tale 2','《海豚的故事2》依旧根据真实事件改编，影片里按照美国农业部的规则，海洋馆的海豚不能单独被喂养，必须要找到陪伴的海豚，否则这头名为“温特”的海豚将被送走，男主角索亚·尼尔森和朋友们再找科学家卡梅伦想办法。真实世界里，故事没有这么曲折，确实有头幼年大西洋宽吻海豚在“温特”被救的附近海滩发现，也被送到克利尔沃特海洋馆，如今两头海豚快乐地生活在一起。　　\r 　　《海豚的故事》改编自真实故事，2005年一头做温特（Winter）的雌性海豚在美国弗罗里达州的海滩被渔具切断了尾巴，被营救到克利尔沃特海洋馆（CMA）。为了让它能快乐的游泳，小男孩索耶·尼尔森等人找到科学家卡梅伦·麦卡锡（摩根·弗里曼扮演）给她制作了人工尾鳍。小海豚温特与死亡相抗争的故事成为了整个美国的传奇。无数人－－无论是健全的人还是残疾人，都从温特的故事里看到了希望与生命的力量。','WINTER\'s amazing true story... now has HOPE.',36000000,52424533,6.967857,6.7,96,107,'2014-09-12','en','/7ujGA9YqxQ3uwtMelCEsaBKasuR.jpg',2.86360369915368,3,'2026-09-10',2,NULL,NULL),(227783,'抢劫坚果店','The Nut Job','炎热的夏天过去，枝上的树叶慢慢转成红色。中央公园内，松鼠、浣熊们发现过冬的坚果根本不够用，这群小动物可能面临一场前所未有的饥荒。松鼠塞利（威尔·阿奈特 Will Arnett 配音）和安迪（凯瑟琳·海格尔 Katherine Heigl 配音）奉命前去寻找坚果，它们计划打劫一辆坚果车，谁知却造成了一场大混乱，还导致好不容易的手的坚果毁于大火。在此之后，塞利遭到流放，只有他的老鼠朋友巴蒂（Robert Tinkler 配音）自始至终跟着他。另一方面，安迪则和自我感觉良好的同伴格里森踏上寻找坚果的征途。最终，安迪和塞利在一座库藏丰富的坚果店重逢，而那里的幕后老板竟然是一个臭名昭著、穷凶极恶的罪犯。 　　螳螂捕蝉，黄雀在后，犯罪分子策划新的劫案同时，却不知有一群小动物正准备打劫他们。','Let\'s Get Nuts!',0,0,18.568021,5.5,319,85,'2014-01-17','en','/9vVMQ29LX4SV7b9po9tKHdFRd0x.jpg',3.0727985717651576,3,'2026-09-10',2,NULL,NULL),(227973,'史努比：花生大电影','The Peanuts Movie','总是闹出一堆笑话的查理·布朗，这一次有了暗恋的“红头发小女孩”，他能否获得她的注意呢？而史努比也将自己的幻想能力升级，变成王牌飞行员，飞上蓝天追逐自己的头号敌人“红色男爵”，还邂逅了梦中情人“菲菲”……','The story of an underdog. And his dog.',99000000,246233113,34.308098,6.5,604,88,'2015-11-05','en','/oHP9RLm2STwljotvlDuBUh8QSQf.jpg',3.355708776500491,3,'2026-09-10',2,NULL,NULL),(227975,'未来海岸','Praia do Futuro','海是Donato的生命，Donato在一次海上意外中救起了德国游客Konrad，但他最好的朋友却遇难了。他们沿着海岸线寻找同伴的尸体，他们也从最开始的被对对方的外表吸引而慢慢的相爱了。Donato跟随Konrad来到柏林，一座远离海的城市，他试图在这里重新开始。几年之后，当他的弟弟Ayrton突然出现在他的家门前的时候，他不得不开始免得自己的过去，他当初为什么会突然的不辞而别。兄弟两人都各自在陌生的城市迷失，这是一个关于寻找爱与身份认同的故事，他们时刻准备着不惜一切的去发现自我和他们的情感。','A hero split in half.',0,0,2.611364,6.4,31,106,'2014-05-01','pt','/u0svu7MxWp4OryaEqXDbDXX0q4r.jpg',2.595841652663871,3,'2026-09-10',2,NULL,NULL),(228066,'维克多·弗兰肯斯坦','Victor Frankenstein','由20世纪福克斯公司拍摄的新版《科学怪人》，詹姆斯·麦卡沃伊出演男主角维克托-弗兰肯斯坦，丹尼尔·雷德克里夫出演维克托的助手Igor，杰西卡·布朗·芬德利饰演女主角。影片将由保罗·麦奎根（《神探夏洛克》《天王流氓》导演）执导，Max Landis（《超能失控》编剧）负责剧本。','Discover the origin of the monster and his creation.',40000000,34227298,24.821138,5.6,685,109,'2015-11-10','en','/3THh7TgYeOL2iZ9fdoYuZbYi29E.jpg',3.234112244423915,3,'2026-09-10',2,NULL,NULL),(228150,'狂怒','Fury','情节设定在1945年二战硝烟即将消散之时，同盟国军队准备在欧洲战场发动最后一轮猛烈攻击。在以寡敌众、弹尽粮绝的不利条件下，身经百战的陆军中士Wardaddy指挥谢尔曼坦克的几名坦克手以及二等兵Norman深入纳粹德国的中心地带，执行一项死亡任务。','War never ends quietly.',68000000,211817906,139.575085,7.4,3946,135,'2014-10-15','en','/pfte7wdMobMF4CVHuOxyu6oqeeA.jpg',4.276765084661453,3,'2026-09-10',2,NULL,NULL),(228161,'Home','Home','When Earth is taken over by the overly-confident Boov, an alien race in search of a new place to call home, all humans are promptly relocated, while all Boov get busy reorganizing the planet. But when one resourceful girl, Tip, manages to avoid capture, she finds herself the accidental accomplice of a banished Boov named Oh. The two fugitives realize there’s a lot more at stake than intergalactic relations as they embark on the road trip of a lifetime.','Worlds Collide',135000000,368871007,63.473086,6.8,1519,94,'2015-03-18','en','/usFenYnk6mr8C62dB1MoAfSWMGR.jpg',3.7090681795142992,3,'2026-09-10',2,NULL,NULL),(228165,'海绵宝宝：水兵陆战队','The SpongeBob Movie: Sponge Out of Water','围绕蟹黄堡的神秘配方，痞老板和蟹老板展开了新一轮的战争。虽然海绵宝宝成功挫败痞老板的猛烈攻势，但是却依然中了对方的诡计。关键时刻，配方凭空消失，直接后果便是导致没人能再做出蟹黄堡。对于日常极度依赖蟹黄堡的比奇堡的居民来说，这一消息无异于晴天霹雳。小镇的宁静荡然无存，海底世界陷入末世般的混乱与动荡之中。由于搭救了痞老板，海绵宝宝被大家当作叛徒对待。危机时刻，海绵宝宝、派大星、痞老板、蟹老板、松鼠珊蒂、章鱼哥得以穿越时空，并顺着蟹黄堡的香味来到了人头攒动的沙滩上。 在那里他们遇见了利用诡计偷走秘方的胡子海盗（安东尼奥·班德拉斯 Antonio Banderas 饰），于是一场蟹黄堡的攻防战由此展开……','He\'s leaving his world behind.',74000000,311594032,36.952268,5.8,719,93,'2015-02-05','en','/7j8zawA761S6LKUoimrwHGkzVK8.jpg',3.3002692006109617,3,'2026-09-10',2,NULL,NULL),(228194,'米其林情缘','The Hundred-Foot Journey','22岁的印度青年Hassan Haji随家人搬到法国南部开了一家印度餐馆，很快便引起了街对面一家米其林星级餐厅的女大厨Mallory女士的注意，在她的帮助下Hassan最终成为了一名著名厨师。','Life\'s greatest journey begins with the first step.',22000000,88880821,27.898438,7.3,508,122,'2014-08-06','en','/bZRneTByr2jGsSluvxQUf6rOKEe.jpg',3.3972224299927256,3,'2026-09-10',2,NULL,NULL),(228203,'麦克法兰','McFarland, USA','《麦克法兰》取材于真人真事。1980年代，加州小镇麦克法兰，一位居住在拉丁人社区的教练，在一所高中创办田径队，排除了自己心理上、身体上和外界压力等等困难，把田径队送上冠军位置。','Champions Can Come From Anywhere.',0,45710059,14.023082,7.4,213,128,'2015-02-20','en','/3c5Gs12gyzVPKfsnNvtVMFOi6mS.jpg',3.118403051083041,3,'2026-09-10',2,NULL,NULL),(228205,'最长的旅程','The Longest Ride','职业牛仔卢克（斯科特·伊斯特伍德 Scott Eastwood 饰）和大学生苏菲亚（布丽特·罗伯森 Britt Robertson 饰）在一次牛仔竞技比赛中相遇，两人一见倾心迅速坠入爱河。然而，身处两个不同世界的他们，对未来和理想都有许多冲突，两人多舛的爱情也处处充满挑战。在一次意外中他们救了一位老人伊拉（阿伦·阿尔达 Alan Alda 饰），得知老人与他已故妻子露丝（奥娜·卓别林 Oona Chaplin 饰）之间动人的爱情故事后，他们深受鼓舞，这能否让他们跨越重重阻碍，共同迎向美好的未来……','Two couples. Two love stories. One epic tale.',34000000,63013281,41.946523,7.3,1064,128,'2015-04-09','en','/yiDhx9LxV3Sk7fqEemEMQPC2kKP.jpg',3.65472472692506,3,'2026-09-10',2,NULL,NULL),(228326,'生命之书','The Book of Life','影片灵感来自于墨西哥传统节日“鬼节”(Day of the Dead)的传说，讲述了三位青梅竹马的好友，马诺洛、玛利亚 和华金 之间的故事。故事从博物馆里的一本书神秘之书讲起，随着镜头的推进，影片来到了另一个世界。这是一个关于拉丁神话的世界，马诺洛、玛利亚和华金是青梅竹马的好朋友，马诺洛和华金同时喜欢上了玛利亚，但是爱情的最终决定权不在于玛利亚，而是神灵。虽然影片讲述了一个很古老、常规的童话故事，但其中墨西哥神话的元素还是备受期待。',NULL,50000000,97437106,34.890999,7.3,755,95,'2014-10-01','en','/AoPlcOxaSSethYfaGRtLzzXa1bR.jpg',3.5340400930807983,3,'2026-09-10',2,NULL,NULL),(228550,'Raymond Did It','Raymond Did It','Mentally challenged Raymond Rourke gets blamed and framed by several kids after they accidentally kill his younger brother Bryce. Six years later, Raymond escapes from the state mental hospital he\'s been locked up in so he can exact a harsh revenge on the folks who killed his brother and set him up.','Mom\'s Pretty Mad At Me',0,0,0.160779,3.2,8,83,'2011-03-27','en','/tFKSA6EXmA9IV5gr7hwJ3VPbTJJ.jpg',2.301778806803481,3,'2026-09-10',2,NULL,NULL),(228967,'刺杀金正恩','The Interview','戴夫·斯盖拉克和好基友亚伦是某八卦脱口秀的主持人和制作人，虽然收视率节节攀升，但是新闻记者出身的亚伦还是希望能在正统的领域内大有作为。与此同时，北朝鲜统治着金正恩号称要用核武器轰炸美国西海岸，朝美两国关系瞬间跌至冰点，剑拔弩张。而戴夫则突发奇想，要面对面采访这个世人眼里如同恶魔一般的独裁者。当两人还未动身之际，CIA探员主动找上门来，要求他们在采访期间伺机刺杀金正恩。几个回合下来，不靠谱的戴夫和亚伦答应了这个危险的任务。他们总算来到神秘的朝鲜，可是突发状况却接二连三出现……','The Film Hackers Tried To Get Banned',44000000,12342632,74.168016,6.1,2304,112,'2014-12-25','en','/qiNE5aABc74ZHcE14QJ3tc8tQmD.jpg',3.6816583879956983,3,'2026-09-10',2,NULL,NULL),(228970,'涉足荒野','Wild','改编自美国作家谢莉尔·斯瑞德2012年的同名自传，讲述婚姻触礁，母亲去世，自己在绝望中生活多年之后，虽然毫无徒步经验，却独自一人踏上Pacific Crest Trail 远足之路，通过长途步行找回自我的故事。',NULL,15000000,52501541,42.952942,7,951,115,'2014-12-05','en','/3SJ0IowA0Uc7iWCwt0Rx81h0LI.jpg',3.571963130135332,3,'2026-09-10',2,NULL,NULL),(230266,'朱莉小姐','Miss Julie','在公爵父亲离家的一个仲夏节夜的晚上，男仆让（柯林·法瑞尔 Colin Farrell 饰）和厨娘克里斯汀（萨曼莎·莫顿 Samantha Morton 饰）相互调侃着，朱莉（杰西卡·查斯坦 Jessica Chastain 饰）迫不及待地想让让陪她跳舞，一开始让因身份地位的不同一直拒绝，但最终两人发生了关系。\r 之后朱莉感到困惑不知所措，而让对她的态度也急剧恶化，他们彼此谩骂唾弃。朱莉乞求让带她离开，为此她甚至偷了父亲的钱，这一切被让的情人、厨娘克里斯汀发现。为了阻止他们离开，克里斯汀杀了朱莉的宠物鸟。朱莉伤心欲绝，双方陷入僵持不下，就在这时，朱莉的父亲归来了。让迅速认识到现实，回到自己原本的地位。朱莉感到悲愤交加，无路可走，而让为了保全自己的安全，怂恿朱莉走上了绝路。','Love is a foolish game',5500000,5000000,5.033065,5.9,45,120,'2014-09-07','en','/11X9DZGT3P7bJhWxfwFdCkWHILS.jpg',2.672946802720907,3,'2026-09-10',2,NULL,NULL),(231576,'心在彼处','Wish I Was Here','35岁的艾丹是一名籍籍无名的演员，拖家带口的他依然在各个剧组间跑龙套打零工。当他的父亲告诉他，自己再也负担不了孙儿们的私校学费时，艾丹不得不把两个孩子带回家。因为儿时阴影，他不愿意把孩子们送去公立学校，可是在家自己教又谈何容易？而父亲的突然过世让艾丹发现了自己身上以前不愿意正视的部分。','Life is an occasion. Rise to it.',5500000,5483299,15.015271,6.4,300,120,'2014-01-18','en','/r7OKflpuEko9tqasN8GMMDybz0A.jpg',3.1325137200485984,3,'2026-09-10',2,NULL,NULL),(231617,'死信投递员(试播集)','Signed, Sealed, Delivered','\"Signed, Sealed, Delivered\" introduces a dedicated quartet of civil servants in the Dead Letter Office of the U.S. Postal System who transform themselves into an elite team of lost-mail detectives. Their determination to deliver the seemingly undeliverable takes them out of the post office into an unpredictable world where letters and packages from the past save lives, solve crimes, reunite old loves, and change futures by arriving late, but always miraculously on time.',NULL,0,0,1.444476,7,6,120,'2013-10-13','en','/6BVCgmhLeSTF8nPBuE9ncHHcCNv.jpg',2.26180576331188,3,'2026-09-10',2,NULL,NULL),(232672,'单亲度假村','Blended','一对大龄男女在一次糟糕的约会之后，各自带着自己的孩子去非洲草原旅行。渐渐地他们发现在这个度假胜地彼此已经不能分开，并且他们的孩子们也在他们逐渐升温的关系中感受到了旅行的快乐...','Single Dad, No Clue. Single Mum, Flying Solo.',40000000,123494610,44.120328,6.6,1006,117,'2014-05-21','en','/c5M0zpMHUJm0YiBaXKBG1Il99Yl.jpg',3.520885409616092,3,'2026-09-10',2,NULL,NULL),(232679,'决胜巅峰','When the Game Stands Tall','本片根据传奇教练 Bob Ladouceur 的传记 When the Game Stands Tall 改编，讲诉这位年轻教练是如何带领De La Salle高中的橄榄球队伍，打破美国历史上所有记录取得151场比赛连胜的故事。','Its Not How Hard You Fall, Its How You Get Back Up',15000000,30127963,7.297757,6.3,130,115,'2014-08-22','en','/p5i7JnBgYP5ntk1jBuDgZGugDBs.jpg',2.917601096176273,3,'2026-09-10',2,NULL,NULL),(234212,'恶魔','Demonic','某个夜晚，一处弥漫着死亡和不详气息住宅发生杀人事件。警探路易斯率队前往，在那里发现了惊慌失措的嫌疑人约翰（达斯汀·米利甘 Dustin Milligan 饰）。此前不久，约翰和女友米歇尔（科迪·霍恩 Cody Horn 饰）、米歇尔的前男友布莱恩（斯科特·麦克洛维茨 Scott Mechlowicz 饰）以及朱尔斯（Megan Park 饰）、唐纳德（Aaron Yoo 饰）、塞缪尔（Alex Goode 饰）闯入这所房子。20年前，名叫玛莎·利文斯顿的女性和朋友们在房子内举行通灵仪式，最终引发残酷的杀人案。对此颇为好奇且有着深深渊源的年轻人们希望利用高科技手段捕捉到鬼魂的身影。  　　约翰的自白让路易斯颇感挠头，他只得求助担任心理医生的女友伊丽莎白，试图通过耐心问询还原数日前房子内所发生的一切……','Every House Has It\'s Secrets',3000000,3387000,12.564554,4.9,148,83,'2015-02-12','en','/ghYdXadF5VLmyJvtgw9g8I3AbNR.jpg',2.8876446632300414,3,'2026-09-10',2,NULL,NULL),(235260,'上帝之子','Son of God','影片讲述神之子耶稣的生平故事，从他的诞生，传道，受难，到最终的复活，生动地刻画出一个丰满的人物形象。','Their Empire. His Kingdom.',22000000,67800064,9.175762,5.9,83,138,'2014-02-28','en','/bCNcVQ1sts0WfuGzus90OYHTIlt.jpg',2.810357069567847,3,'2026-09-10',2,NULL,NULL),(235271,'危情瘾难耐','Addicted','在朋友们的眼里，佐伊 俨然拥有完美无缺的幸福生活，她有一份稳定而收入优渥的工作，和丈夫杰森 结婚多年彼此之间感情一直十分亲密，两人共同养育了两个可爱乖巧的孩子，一切都是那样的妥帖。然而只有佐伊自己知道，在快乐的表象都无法填补她心里巨大的黑洞，燃烧的欲望无时不刻不在折磨和摧毁着她。','Every Woman Needs an Escape',0,0,7.544515,5.4,63,105,'2014-10-10','en','/fAERrD6vvmznDoL99wlgjhSfPcH.jpg',2.7370878727383463,3,'2026-09-10',2,NULL,NULL),(236751,'天堂真的存在','Heaven Is for Real','美国一位男童自称3岁时因盲肠破裂动手术，濒危之际，灵魂出窍上天堂，不但坐在耶稣腿上，还见到了因妈妈流产、来不及出世的姐姐。令人惊讶的是，他的父母亲从未告诉过他这段往事。他的牧师父亲相信这是神迹，已将儿子7年前的经历写成书，《天堂真的存在》(《Heaven Is For Real》)，在美国连续7周登上畅销书榜首，目前已经印刷超过100万本。\r 　　◎幕后花絮\r 　　本片改编自2010年出版的同名畅销书，此书曾登上《纽约时报》畅销书榜首。传教士陶德-伯波在书中记录了四岁儿子讲述自己游览天堂的见闻。虽然一些基督教徒批评这本书没有任何事实依据，无神论者苏珊-雅各比认为其缺乏基本的逻辑，但该书依然在出版不到一年就热卖20万册，并连续四年销量不俗。市场嗅觉敏锐的索尼电影公司在2011年买下了该书的电影改编版权，找来《勇敢的心》的编剧兰道尔-华莱士担任导演。从小，华莱士的母亲就带领他去教堂，了解上帝。他听了福音布道家比利-格拉汉姆的许多演讲。在田纳西州的小教堂中，华莱士被赞美诗感动，希望以后有机会能与别人分享这些珍贵的感受。《天堂真的存在》无疑给了他千载难逢的机会。在第一次听到伯波家庭的事迹后，与大多数人一样，华莱士有着满腹疑问。通过公司，他认识了陶德，了解到他是如此诚实和脚踏实地的人，而且并不在乎外人怎么看待自己。陶德有许多工作，并非依靠教堂工作维生，不是那种只有付钱才会做牧师的人。这些都令华莱士印象深刻，并开始了解并相信他所讲述的故事。\r 　　华莱士说，本片并非为了传道，更多关注的是人的内心，让人了解神的作为远非人类可以控制和了解的。他本人就在拍摄期间有了奇迹般的经历。在接拍后，他因为严重感染接受了手术，并被告知需要截肢，但后来他们找到办法避免于此。在拍摄期间，华莱士度过母亲离世的艰难时日，坚信亲人能在天堂开始更好的生活。“我相信，这个电影能给基督徒们真正的鼓励和为他们对上帝的渴望代言。它也会给那些没有信仰和心存疑窦的人感受爱和希望的机会。”','Unlock the mystery',12000000,101332962,11.150261,6,229,99,'2014-04-16','en','/iQ4Q1hU2q6tcEIFeZ5yzNSrVF2r.jpg',3.0320355591165926,3,'2026-09-10',2,NULL,NULL),(238603,'地球回音','Earth to Echo','正当一个新的建筑项目在一个社区周边启动时，居住在附近的一群小伙伴们不约而同的收到了奇怪的神秘信息。黑夜中不断有奇怪的声音发出，是坏蛋？还是外星访客？…于是，在好奇心的驱使下，一场探险之旅由此展开','No one will ever believe our story.',13000000,45300000,17.371327,5.7,290,89,'2014-06-14','en','/a026TDG1roqQG8N1waoBfwJqGLM.jpg',3.070161137821112,3,'2026-09-10',2,NULL,NULL),(238615,'幻体：续命游戏','Self/less','曾在纽约建筑界享有极高声誉的富豪马丁·戴米恩（本·金斯利 Ben Kingsley 饰），而今饱受癌症折磨，不得不面对即将在半年后去世的事实。除此之外，他与女儿克莱尔的关系始终处于冰封状态，这令他不仅慨叹金钱的无力。不久前，马丁与菲尼克斯生物科技公司取得联系，对方声称使用最先进的脱换技术可以帮助马丁重获新生，简而言之就是将他的意识或者灵魂注入一具更加年轻健康的躯体内再生。经过慎重的考虑，马丁以爱德华·基德纳（瑞恩·雷诺兹 Ryan Reynolds 饰）的身份复活。此后的一段时间里，爱德华尽情享受重返青春的乐趣。\r 　　与此同时，这具陌生躯体背后所隐藏的秘密，则让他渐渐感到不安……','God Created Man. Man Created Immortality.',26000000,30523226,66.097437,6.3,1091,116,'2015-07-10','en','/lSdmJgfUnRHfLagSPv8YhHGPEdl.jpg',3.537583488076997,3,'2026-09-10',2,NULL,NULL),(238636,'人类清除计划2','The Purge: Anarchy','2023年，美国新政府所推行的“人类清除计划”迎来了第六个年头。剑走偏锋的极端政策，旨在抑制持续上升的失业率和犯罪率，在此期间却也有越来越多的无辜之人遇害，而富人们则斟好杯中酒，脑满肠肥欣赏甚至以看似高贵优雅的姿态参与一年一度的屠杀狂欢。在大屠杀即将开始之际，面临分手的情侣谢恩和莉兹的车在路上抛锚，他们慌乱不安地寻找藏身之地。刚刚失去最重要亲人的伊娃及其女儿卡莉躲在家中亦难免厄运临头，关键时刻母女被逡巡在城市巷尾的中士救下，与此同时谢恩和莉兹也阴差阳错搭上了中士的车。新仇旧恨以及对世界的各种愤懑不满，在这个夜晚集中爆发，脆弱的生命面临最惨烈的考验……','Welcome to America, where one night a year, all crime Is legal.',9000000,108782847,82.975841,6.6,1954,104,'2014-07-17','en','/qwqHHZLZSUvMkAMQ47ymtfjEifY.jpg',3.775400242262583,3,'2026-09-10',2,NULL,NULL),(239563,'圣人文森特','St. Vincent','影片讲述了单身母亲玛姬（梅丽莎·麦卡西 饰）带着儿子奥利弗（杰顿·李博赫 饰）搬到了布鲁克林，为了维持全家生计不得不在医院加倍工作，为此她只能把儿子交付给看似无害的隔壁邻居文森特（比尔·默瑞饰）照看。文森特是个退役老兵，脾气暴躁、抽烟酗酒、嗜赌如命。圣文森把自己堕落的生活方式一览无遗的呈现在男孩面前，教奥利弗喝酒、赌博、撒谎、偷窃，还和怀孕的脱衣舞女达卡（娜奥米·沃茨 饰）一起带奥利弗去夜总会游荡。然而奥利弗却在这些不堪中找到了闪亮之处，两人也慢慢建立起友谊。','Love Thy Neighbor',13000000,54837234,43.791745,7.1,763,102,'2014-10-09','en','/5secRUEM28Fer4kgX2nqJ4Et7NA.jpg',3.526899825017755,3,'2026-09-10',2,NULL,NULL),(239566,'激乐人心','Get On Up','美国灵魂音乐教父詹姆斯布朗的传记电影，从他被家人抛弃、在贫民区长大的经历讲起，横跨他传奇的一生，一直到他成为灵魂音乐教父 的辉煌年代。','The Funk Don\'t Quit',0,31911598,13.064264,6.4,158,139,'2014-08-01','en','/dVbGeU5agxFGcJnL5hk4uO8W7i2.jpg',2.979689982628437,3,'2026-09-10',2,NULL,NULL),(239571,'最好的我','The Best of Me','焦点影业从华纳手里拿下[最好的我]的发行权，影片改编自爱情小说大师尼古拉斯·斯帕克斯同名作品，讲述小情侣阿曼达和道森18年前爱得惊天动地，分得痛彻心扉，18年后纠结要不要复合的纯爱故事。该片预计2014年上映。','You never forget your first love.',26000000,35926213,33.93914,7.2,765,117,'2014-10-16','en','/eVE8rZITPWudk69dm38zc7ONmox.jpg',3.52052329649872,3,'2026-09-10',2,NULL,NULL),(239573,'Unfinished Business','Unfinished Business','A hard-working small business owner and his two associates travel to Europe to close the most important deal of their lives.  But what began as a routine business trip goes off the rails in every imaginable – and unimaginable – way, including unplanned stops at a massive sex fetish event and a global economic summit.','Best business trip ever.',35000000,14431253,16.832312,5,320,91,'2015-03-05','en','/eVWVZf3fkx9eNqbHyn9xNlmC2h4.jpg',3.0236067659631902,3,'2026-09-10',2,NULL,NULL),(239678,'离别七日情','This Is Where I Leave You','父亲的去世让贾德（杰森·贝特曼 Jason Bateman 饰）回到了久违的家乡，同样回到这里的，还有贾德许久未曾谋面的兄弟姐妹们，父亲的遗愿将散落在天涯各处的他们重新聚集在了一起，共同度过七日短暂的时光。 久别重逢，众人心中的喜悦溢于言表，然而，随着时间的推移，隐藏在深处的秘密渐渐显露出狰狞的面目。其实，近日里贾德陷入了人生的最低谷，他的妻子竟然和他的老板搞在了一起，这使得贾德失去了妻子，同时丢掉了工作。让贾德没有想到的是，他的兄弟姐妹们居然各个都有着不可告人的麻烦，当他们暂时卸掉身上的枷锁，以孩童一般的赤子之心度过这七天后，能否迎来一个不一样的未来呢？','Welcome Home. Get Uncomfortable.',19800000,41296320,20.311684,6.5,505,103,'2014-09-10','en','/4TIPqyhiVa0QRReUXJjy0KOsCvn.jpg',3.2798361846712294,3,'2026-09-10',2,NULL,NULL),(239897,'Dwegons','Dwegons','Family inherits an old house and to their surprise, finds the home filled with wonderful colorful creatures that brings the family together.',NULL,0,0,0.485405,0.5,1,98,'2014-01-24','en','/eCWjbEI7v3ThQ32gM3aiID568P4.jpg',1.9830977912601735,3,'2026-09-10',2,NULL,NULL),(240832,'超体','Lucy','居住在台北的年轻女子露西，被迫成为“人体快递”， 胃里被黑帮植入一种新型病毒，在一次被暴打后，胃里的病毒融入血液，从而使她意外拥有了用意念便可控制周围物体的超能力，比如预见未来、用意念移动物品、消除疼痛、瞬间变身等。她的顽强反抗和逃脱也因此引起非法组织的追杀，在调查非法组织并与之斗争的同时，自己的生命也在迅速走向消亡，在挽救生命、寻找真相的道路上，露西从手无缚鸡之力的弱女子逐渐成长为一名无所不能、无所不在的超级女英雄。','The average person uses 10% of their brain capacity. Imagine what she could do with 100%.',40000000,126546825,115.241998,6.3,5878,89,'2014-07-14','en','/kRbpUTRNm6QbLQFPFWUcNC4czEm.jpg',4.031688531337002,3,'2026-09-10',2,NULL,NULL),(241239,'至暴之年','A Most Violent Year','电影《至暴之年》影片讲述在20世纪80年代的纽约，一名野心勃勃的商人被迫与一家腐败的商业机构打交道的故事。','The result is never in question. Just the path you take to get there.',20000000,12007070,37.629309,6.5,546,125,'2014-12-30','en','/xqb0KhnmAHWBgIyWNEXaWufJIvd.jpg',3.3385195241057892,3,'2026-09-10',2,NULL,NULL),(241251,'隔壁的男孩','The Boy Next Door','詹妮弗·洛佩兹饰演的离婚少妇，与隔壁邻居，年轻学生诺阿（《舞出我人生》男星瑞安·古兹曼饰）擦出火花，生活随之急转直下……\r 　　J Lo扮演一位教师，丈夫是个花心大萝卜，离婚后不久，隔壁搬来一位英俊美少年诺阿，他与自己的儿子关系融洽，他去她的班上上课，他说她很美。于是他们越走越近，东风一夜之后，J Lo想要中断这不伦的关系，诺阿却成了危险，变态的跟踪狂，要毁了她的生活，她的工作，她的一切。','A Moment She Couldn\'t Resist. An Obsession He Can\'t Control.',4000000,52425855,24.161735,4.1,1022,91,'2015-01-23','en','/z1RyR2KBs5KANEJolKrx3Qgb6H3.jpg',3.0413881422262574,3,'2026-09-10',2,NULL,NULL),(241254,'王子','The Prince','影片故事讲述的是一位退休的前杀手回归平静的生活，但因为他的一些所谓“错误的过去”，他的女儿却被以前的死对头绑架了，为了救女儿，双方引发了一场暴力冲突。','Mercy is for the Weak',18000000,266586800,21.638673,4.6,218,93,'2014-08-22','en','/22b2fmxhZveWSyWkgUz2y94fp3w.jpg',2.94890756602278,3,'2026-09-10',2,NULL,NULL),(241257,'回溯迷踪','Regression','故事发生在1990年，美国一名汽车修理工约翰·格雷（大卫·丹席克 David Dencik 饰）因涉嫌猥亵自己的女儿安吉拉（艾玛·沃森 Emma Watson 饰）而遭到逮捕。负责调查此案的警官布鲁斯·肯纳（伊桑·霍克 Ethan Hawke 饰）对约翰展开问询，而在这一过程中约翰起先承认罪行，随后又突然失忆。为了应对这一突发状况，心理学教授肯尼斯·睿恩斯博士（大卫·休里斯 David Thewlis 饰）也介入调查之中。他们发现，约翰信奉崇拜魔鬼撒旦的黑宗教，甚至布鲁斯的搭档都有可能参与其中。布鲁斯和肯尼斯想方设法要打开嫌疑人和受害者的记忆闸门，让他们想起最不堪回首的一段往事……\r 本片根据真实事件改编。','Fear always finds its victim',0,17671101,27.215666,5.3,585,106,'2015-10-01','en','/kkj6Cq88P1Na0I9E1U2ljCHPHdf.jpg',3.1713168064243815,3,'2026-09-10',2,NULL,NULL),(241259,'爱丽丝梦游仙境：镜中奇遇记','Alice Through the Looking Glass','爱丽丝·金斯利作为船长纵横四海3年后回到伦敦，却发现对于女性社会角色的陈腐观念依然盛行，她为自己所设想的未来可能无法成为现实。此时白皇后希望她借助时空魔球回到过去去拯救疯帽子匠全家。而被流放外域的红皇后也与“时间”结盟，并暗中计划偷取时空魔球。爱丽丝回到过去，与各个朋友和敌人在不同的时间点上交错，并且与红皇后和时间本人在时间的海洋上展开了一场奇妙的追逐。','It\'s time for a little madness.',170000000,299370084,56.268916,6.5,1725,113,'2016-05-25','en','/xVTVDp4ZO1UVstLoyhAEHjNSWtD.jpg',3.6625443360296295,3,'2026-09-10',2,NULL,NULL),(241554,'Run All Night','Run All Night','Brooklyn mobster and prolific hit man Jimmy Conlon has seen better days. Longtime best friend of a mob boss, Jimmy is haunted by the sins of his past—as well as a dogged police detective who’s been one step behind Jimmy for 30 years. But when Jimmy’s estranged son becomes a target, Jimmy must make a choice between the crime family he chose and the real family he abandoned long ago. Now, with nowhere safe to turn, Jimmy has just one night to figure out exactly where his loyalties lie and to see if he can finally make things right.','No sin goes unpunished',50000000,71561644,74.64653,6.3,1148,114,'2015-03-11','en','/zHyexVBdFnf0v9xNoDqptzFTBps.jpg',3.568843696864013,3,'2026-09-10',2,NULL,NULL),(241766,'Lords of London','Lords of London','Tony is a notorious gangster with a big problem. He has woken up in an abandoned farmhouse, with blood on his shirt, and no memory of how he got there. He stumbles into a small town and discovers he’s in an Italian village that seems to be lost in time.','In this city, crime is a family business.',3440000,0,1.913302,3.6,6,90,'2014-01-06','en','/7MQ8Uf4JTxjaExZ7lYxz4AVuFR2.jpg',2.2545436654989017,3,'2026-09-10',2,NULL,NULL),(241771,'灯光之外','Beyond the Lights','新人女歌手Noni Jean在获得格莱美奖，并引来万众注目后，由于承受不住成功带来的压力，她想要结束自己的生命。这时一名年轻的警察救了她，于是……爱情引领着Noni Jean重新走回正轨。','Open your heart, find your voice.',7000000,14618727,8.079046,7,139,116,'2014-09-10','en','/5Di9UXTa2bDec68WOFcZzgB1ot3.jpg',2.9679601519368086,3,'2026-09-10',2,NULL,NULL),(242083,'成名记','Hits','A talentless teen will do anything to get on TV\'s \"The Voice.\" Meanwhile, her father, a municipal worker, creates an uproar when a video of his rants at City Hall goes viral.','Based on a true story... that hasn\'t happened yet.',1000000,0,3.638411,4.9,23,96,'2014-01-21','en','/w7TdwnSh5McR5J28ZHTvttTKaCi.jpg',2.521064095598009,3,'2026-09-10',2,NULL,NULL),(242095,'The Signal','The Signal','Three college students on a road trip across the Southwest experience a detour – the tracking of a computer genius who has already hacked into MIT and exposed security faults. When the trio find themselves drawn to an eerily isolated area, suddenly everything goes dark. When one of the students regains consciousness, he finds himself in a waking nightmare.','R U Agitated?',4000000,600896,27.662696,5.8,631,95,'2014-03-15','en','/ksfyMjlCESLylnnhLiloBxPmVzc.jpg',3.253797464857919,3,'2026-09-10',2,NULL,NULL),(242166,'红色天空','Red Sky','失宠的顶尖战斗机驾驶员布奇·马斯特斯带领凶猛的大规模杀伤性武器的小队重返天空,只为了取回属于自己的那份军事和个人上的荣耀,因此马斯特斯必须从受挫的友谊中找到一条明路...','Go Rogue',25000000,0,3.344158,4.1,26,100,'2014-03-12','en','/kk5KtMpJeqFPYmWo93V7wXOE7jt.jpg',2.5362947772500197,3,'2026-09-10',2,NULL,NULL),(242512,'死亡占卜','Ouija','莱妮（奥利维亚·库克 Olivia Cooke 饰）和黛比（雪莱·亨尼格 Shelley Hennig 饰）是一对从小玩到大的好朋友，谁知在某个毫无征兆的夜晚，黛比突然上吊自杀，这起变故给了莱妮极其沉痛的打击。她决然不相信好友会选择如此残酷的方式离开，在多方调查问询无果后，莱妮召集了妹妹萨拉（安娜·科托 Ana Coto 饰）以及伊莎贝尔（比安卡·A·桑托斯 Bianca A. Santos 饰）、特里弗（达伦·卡加索夫 Daren Kagasoff 饰）、皮特（道格拉斯·史密斯 Douglas Smith 饰）等好友，用她和黛比小时候最常玩的通灵板，试图召唤黛比问清死因。  阴暗的房间里，他们的问询得到回应，而恐怖的噩梦似乎就此开始……','Keep telling yourself it\'s just a game',5000000,103590271,56.30466,4.9,983,89,'2014-10-24','en','/9K7FSMG1u3SRcY47QPcezpfFlZB.jpg',3.2499439502327547,3,'2026-09-10',2,NULL,NULL),(242575,'Guten Tag, Ramón','Guten Tag, Ramón','After five failed attempts to go to the United States, 18-year-old Ramón decides to look for a friend’s aunt in Germany, but never finds her. With no papers or money, and without knowing the language, he barely survives living on the street until he meets Ruth, an old retired nurse who doesn’t speak Spanish. Beyond language barriers and prejudices, they discover that solidarity and humanity make life bearable.',NULL,4000000,0,1.771584,8.1,18,119,'2013-10-18','en','/7xaQAc01TZOHEku2uC520OIENWx.jpg',2.491583485421794,3,'2026-09-10',2,NULL,NULL),(242582,'夜行者','Nightcrawler','卢·布鲁姆(杰克·吉伦哈尔 饰演)是一名充满激情的年轻人，迫切地想得到一份工作。他发现，自己或许可以在报道洛杉矶地下犯罪活动方面有一番作为。他与一群敢于冒险的摄影师们合作，闯入了那个危险而又刺激的“夜行”的世界。所谓“夜行”(Nightcrawler)，指的就是自由记者和摄影师们四处拍摄暴力犯罪影像，并将其卖给电视台相关节目组的行为。一位来自电视台的经验丰富的女记者尼娜(蕾妮·罗素 饰演)也成为卢的助手。然而很快，他就模糊了正与邪的界限，从一名旁观者变成了他镜头中故事里犯下罪行的“明星”。','The city shines brightest at night',8500000,38697217,89.095538,7.6,3395,117,'2014-10-23','en','/j9HrX8f7GbZQm1BrBiR40uFQZSb.jpg',4.170168383426016,3,'2026-09-10',2,NULL,NULL),(243938,'热浴盆时光机2','Hot Tub Time Machine 2','在上一部的结尾，卢成为“互联网之父”。之后卢却不幸遭到一名不明身份的袭击者枪击，性命危在旦夕，为了再次拯救他们的朋友，雅各布和尼克再次启动了时间机器——热浴盆时光机。','The Laws of Space and Time are About to be Violated.',14000000,12314651,16.618874,5,354,93,'2015-02-20','en','/lBroHetSm8RMI8zp7ThpFJsw9E1.jpg',3.0376965417708894,3,'2026-09-10',2,NULL,NULL),(243940,'起死回生','The Lazarus Effect','影片讲述一个大学医疗小组进行一项不可能的研究：让人起死回生的技术，弗兰克(马克·杜普拉斯 饰)和他的未婚妻佐伊(奥利维亚·王尔德 饰)是这个小组的领导者。他们的秘密试验在一只刚刚死亡的动物上获得了成功，小组成员们兴奋异常，准备向世人揭示这个创世之举。然而当大学校长得知这项秘密研究之后，他下令关闭研究小组，科研器材也全被没收。弗兰克，佐伊和组员们依然不肯放弃，他们进行更加危险的实验，然而可怕的事故发生了，佐伊在这次实验中丧生。既痛苦又内疚的弗兰克决定铤而走险，他想把佐伊变成第一个通过他们的实验手段起死回生的人。起初，实验的结果看似很成功，佐伊又回活了过来。然而在佐伊身上发生了可怕的变化，她似乎已经丧失了人性，而且拥有了超能力。很快组员们就要面临着可怕的命运……','Evil will rise.',3300000,64110728,20.304235,5.1,505,83,'2015-01-29','en','/uGJ8DjyK1nNzJpNgp85n2tw0EvF.jpg',3.107859727205655,3,'2026-09-10',2,NULL,NULL),(244114,'Firestorm','風暴','A crew of seasoned criminals led by the notorious Nam, armed with high-powered weapons, pulls off another smooth and violent armored car heist in broad daylight in a crowded street. Whoever tries to get in their way, they will show no mercy. This puts the police force to shame and humiliation. A hardboiled senior police inspector Lui, hot on the trails of Nam and his tight crew, determines to put an end to this madness that causes the lives of innocent people. But he soon comes face to face with the cruel reality that the usual police tactics are too futile to send these armed thieves behind bars. Extreme crime requires extreme justice, even if it means crossing his moral line. Tou, an ex-con desperate to leave his criminal past behind, volunteers to be Lui’s snitch in exchange for a fresh start with her girlfriend Bing. But little does he know what hellish situation he’s getting himself into.',NULL,0,0,3.376967,5.9,43,110,'2013-12-12','zh','/tr7pYZ6f0KUS8l1BaFQU4kx6hi5.jpg',2.6596671116394286,3,'2026-09-10',2,NULL,NULL),(244267,'I型起源','I Origins','伊恩·格雷是一名分子生物学在读博士，专攻眼睛的进化。在一个聚会上，他邂逅了一位神秘的面具女郎，凭着记忆里女孩美丽动人的眼睛，他找到了她，两人陷入爱河。尽管两人对于生活的基本信条完全不同，但却丝毫未影响感情。多年后，伊恩和他的实验搭档凯伦有了一次具有深远意义的发现，他必须要离开家人，穿越世界各地去找寻这项新发现的意义。',NULL,0,336472,37.555398,7.5,1063,106,'2014-07-18','en','/cFKUQmqOWiX5MbbvUsyddLKr2VK.jpg',3.6800125690703913,3,'2026-09-10',2,NULL,NULL),(244316,'嗜血灰熊','Into the Grizzly Maze','从小就不合的两兄弟终于在老家阿拉斯加团聚，他们开始了一段2天的野外徒步旅行，怎料却惹上了一只巨大的灰熊，人熊大战就此展开.....','Hunt or be hunted.',10000000,0,10.073144,5.1,74,94,'2015-02-27','en','/i5GbFCeZ0fG5xb2ta6B3yNgzIM7.jpg',2.766307297541833,3,'2026-09-10',2,NULL,NULL),(244339,'逃出生天','逃出生天','故事讲述一对消防兄弟因一场火灾而关系决裂，但三年后再因一场大火灾，令二人再次碰头，在这危急存亡时刻，两兄弟联手率领众人逃出生天。片中有不少爆炸场面，导演更要求用真火拍摄，画面逼真震撼，绝对令观众有置身现场的感觉。',NULL,0,0,1.583918,5.8,11,107,'2013-03-10','cn','/gCse7YoPl9OEW8T0OhZ5MR7sAQl.jpg',2.375595852339283,3,'2026-09-10',2,NULL,NULL),(244403,'无人引航','Rudderless','山姆（比利·克鲁德普 Billy Crudup 饰）是一位事业有成的广告公司总裁，一场意外夺取了他的儿子乔什（迈尔斯·赫尔泽 Miles Heizer 饰）的生命，这突如其来的打击让山姆陷入了绝望之中，他放弃了所拥有的一切，躲在自己的帆船里，每日靠酗酒过活。  　　一次偶然中，山姆意外发现了乔什生前写的几首歌曲，歌曲让山姆仿佛重新回到了父子两人共同为音乐而狂的美好时代。山姆决定让乔什的生命在音乐中延续，他学会了儿子创作的歌曲，于酒吧之中自弹自唱。山姆真挚的歌声吸引了一位名叫昆汀（安东·尤金 Anton Yelchin 饰）的年轻人，两人一拍即合组成了乐队，专门表演乔什所谱的歌曲。','The way back begins with a single chord.',5000000,0,10.619574,7.4,105,105,'2014-10-17','en','/28uuzZsVRtmMchOHa6FCkJNiLlr.jpg',2.919350267847177,3,'2026-09-10',2,NULL,NULL),(244534,'圣诞快乐','Happy Christmas','分手后，珍妮搬到作家凯莉、她的电影制片人丈夫和他们的孩子那里住。尽管一开始很不顺利，但珍妮的影响帮助凯莉认识到，为了她的幸福，她的生活、事业和关系的演变是必要的。','Family is the gift that keeps on taking.',0,0,7.052422,5.2,58,82,'2014-06-26','en','/gjOQUlsprWkmyZP4hhMGr0GP3LG.jpg',2.7151257953973187,3,'2026-09-10',2,NULL,NULL),(244772,'失魂姐弟','The Skeleton Twins','关系疏远的孪生姐弟玛吉和米勒在同一天自杀未遂。两人结伴回到儿时小镇，面对各自未解的心结。玛吉烦恼着她并不快乐的婚姻，米勒则要面对有过有过难忘回忆的前男友。姐弟的父亲曾经告诫他们不管发生什么都要在一起，也许这句话自有它的道理...','Family is a cruel joke.',0,5284309,15.699363,6.7,292,90,'2014-01-18','en','/lDygTdg1KlrVJVzqsFL515uGzSe.jpg',3.15350196483146,3,'2026-09-10',2,NULL,NULL),(244776,'梦游者','The Sleepwalker','凯娅与安德鲁是一对年轻的夫妇。他们正在休憩一同凯娅祖辈留下来的与世隔绝的老宅。但是当凯娅的姐姐克里斯汀带着未婚夫伊拉到来之后，给他们的生活带来了意想不到的变化。',NULL,0,0,0.926084,4.1,7,92,'2014-01-20','en','/asTg7u7yYQIBeEx9tTvpTQVkjFJ.jpg',2.281695793585258,3,'2026-09-10',2,NULL,NULL),(244783,'Song One','Song One','Estranged from her family, Franny returns home when an accident leaves her brother comatose. Retracing his life as an aspiring musician, she tracks down his favorite musician, James Forester. Against the backdrop of Brooklyn’s music scene, Franny and James develop an unexpected relationship and face the realities of their lives.','A moment can change everything.',6000000,32251,6.349218,5.5,87,86,'2014-01-20','en','/sY4CD3Wj4OIdiVCrU4qOJMxOzVg.jpg',2.8009184514369023,3,'2026-09-10',2,NULL,NULL),(244786,'爆裂鼓手','Whiplash','年轻的爵士鼓手安德鲁·奈曼就读于全国顶尖的音乐学院，师从令人畏惧的爵士乐导师特伦斯·弗莱彻，在成为顶尖爵士鼓手的道路上奋力挣扎。','',3300000,13092000,26.7202,8.375,4254,105,'2014-10-10','en','/wOBIYg8cJUNumlBGyUk47Sw4olf.jpg',4.288755590411639,3,'2026-09-10',2,NULL,NULL),(245700,'透纳先生','Mr. Turner','聚焦英国绘画大师透纳生命中最后二十五载的岁月。在父亲离世的深刻影响下，这位性情古怪的画家与长期照料他却备受忽视的女管家保持着若即若离的关系，其间亦存在肉体牵扯。后来他与一位海滨旅店女主人缔结深厚情谊，最终隐姓埋名同居切尔西并于此离世。在此期间，他游历四方、潜心创作，出入乡间贵族宅邸，涉足风月场所，以桀骜不驯的姿态活跃于皇家艺术学院，曾为描绘暴风雪将自己绑缚在船桅之上，其艺术成就既受公众与王室推崇，亦遭遇激烈批判。',NULL,0,5405500,9.242554,6.3,204,150,'2014-10-31','en','/v1qQqzvRYJP23jTW1O78k8q8zul.jpg',3.0230705914656038,3,'2026-09-10',2,NULL,NULL),(245703,'午夜逃亡','Midnight Special','在得知亲生儿子拥有超能力后，父亲载著儿子展开了一趟亡命旅程，并揭开儿子拥有超能力的神秘真相。','He\'s not like us.',18000000,6212282,32.717853,6.2,694,112,'2016-02-18','en','/uogcouZVZgtStFH8qHaD3g1MHxQ.jpg',3.3423003066920844,3,'2026-09-10',2,NULL,NULL),(245846,'陌生之地','Strangerland','讲述一对夫妇的两个10几岁的儿子失踪于沙尘暴，两人的关系也因此濒临崩溃。','To find the truth they must lose themselves.',10000000,17472,5.145655,5.1,83,111,'2015-07-01','en','/qXYoQNsT2qCraSuPUK5HiUCI9k7.jpg',2.776602270980689,3,'2026-09-10',2,NULL,NULL),(245916,'杀死信使','Kill the Messenger','该片改编自记者盖瑞·韦布的真人事件，他因揭露中情局毒品内幕而被CIA毁了整个生活的故事。','Can you keep a national secret?',5000000,2450846,21.343093,6.6,355,112,'2014-10-09','en','/7HTNqFUUL2rKaNoKK14WnXdONba.jpg',3.20616930451872,3,'2026-09-10',2,NULL,NULL),(246403,'长牙','Tusk','贾斯汀·朗（Justin Long）饰演的播客（Podcast）主持人华莱士（Wallace）去采访环球探险家Mr. Howe（Michael Parks 饰演），结果被后者变成了半人半海象的怪物。而华莱士失踪后，哈里·乔·奥斯蒙特（Haley Joel Osment）所饰演的他的搭档Teddy Craft偕同华莱士的女友（Genesis Rodriguez 饰演）一同出发去寻找他。据说，约翰尼·德普（Johnny Depp）扮演的角色叫Guy Lapointe，是一名加拿大法语区的侦探。','Let me tell you a story...',2800000,1826705,15.754614,5.1,366,102,'2014-09-19','en','/1DWeNoK2h07nWasR3qWrt18xomC.jpg',3.05051098608767,3,'2026-09-10',2,NULL,NULL),(246449,'对抗荒野','Against the Wild','飞机坠毁后，两个小孩和一只阿拉斯加犬在野外生存的故事。','Partners in survival. Friends for life.',1493619,0,2.492747,4.9,19,90,'2013-12-29','en','/cTs2mJEJMa6WxYt4ZJnlz2xK0VC.jpg',2.4807438039399305,3,'2026-09-10',2,NULL,NULL),(246655,'X战警：天启','X-Men: Apocalypse','变种人天启（奥斯卡·伊萨克 Oscar Isaac 饰）诞生于人类文明的最开端，被人类当做神一般敬仰膜拜，然而，这样的他，却遭到了他最蔑视的人类的背叛，被埋葬于废墟石砾之下，一晃眼就是数千年过去。一场意外使得沉睡千年的天启从混沌中醒来，重返人间的他却发现曾经高贵的变种人，如今境遇十分糟糕。为了创造一个属于变种人的新世界，他找到了暴风女（亚历山德拉·西普 Alexandra Shipp 饰）、灵蝶（奥立薇娅·玛恩 Olivia Munn 饰），天使（本·哈迪 Ben Hardy 饰），还有想要过平凡生活却依旧遭到人类驱逐的万磁王（迈克尔·法斯宾德 Michael Fassbender 饰）组成了天启四骑士。在察觉到天启的动向后，X教授（詹姆斯·麦卡沃伊 James McAvoy 饰）带领着魔形女（詹妮弗·劳伦斯 Jennifer Lawrence 饰）、野兽（尼古拉斯·霍尔特 Nicholas Hoult 饰）和凤凰女（索菲·特纳 Sophie Turner 饰）等人，发誓要粉碎天启的阴谋。','Only the strong will survive',178000000,543934787,139.272042,6.4,4721,144,'2016-05-18','en','/ikA8UhYdTGpqbatFa93nIf6noSr.jpg',4.063662953691772,3,'2026-09-10',2,NULL,NULL),(248402,'烈马柔情','A Fine Step','A Fine Step is an uplifting family drama centering on Cal Masterson (Luke Perry, Beverly Hills 90210) an award winning horseman whose relationship with his beloved horse Fandango allows him to achieve multiple championship wins. However tragedy strikes when Cal and Fandango are involved in a serious accident, ending Cal\'s horse riding days forever. Cal\'s devastation is slowly overcome when his new neighbour, 14 year old Claire Mason (Anna Claire Sneed, Glee) takes an interest in Fandango and convinces him that Fandango\'s competing days might not be over.','Together they learnt to dream again',0,0,0.65434,4.1,7,90,'2014-04-16','en','/lIs7Uuk0his0PFFrLyxJkaF3ygZ.jpg',2.2810750768147003,3,'2026-09-10',2,NULL,NULL),(248774,'平淡无奇的孩子','Obvious Child','多娜（珍妮·斯蕾特 Jenny Slate 饰）是一位小有名气的喜剧演员，正处在事业高峰期的她深受各路观众的喜爱，然而，在现实中，多娜的生活简直就是一出悲剧，她那花心成性的男朋友不仅背叛了她，更毫不留恋地选择了离开，之后，糟糕的心情影响到了多娜的演出，在一次失败的表演后，多娜的事业开始走上了下坡路。  　　一次偶然中，多娜结识了名叫麦克斯（杰克·雷西 Jake Lacy 饰）的男子，就连多娜自己也搞不清楚是怎么回事，她竟然在浑浑噩噩之中同相识不久的麦克斯发生了关系，糟糕的事情还不止于此，几个星期后，多娜意外的发现自己竟然已经身怀六甲，面对如此残酷的现实，多娜一时间竟然不知道该怎么办了。',NULL,0,3123963,10.12895,6.7,187,83,'2014-06-06','en','/vAVuQuboHiqc6ClsFeWQXBHJkOX.jpg',3.02999476668679,3,'2026-09-10',2,NULL,NULL),(249164,'如果我留下','If I Stay','改编自美国作家盖尔·福尔曼畅销18个国家的同名小说，天赋超群的古典音乐少女米娅，与家人遭遇严重车祸，在昏迷之中忽然灵魂出窍，在生死之间看见未来。这段预告片中，莫瑞兹朗读小说的序言作为旁白，一边亲眼看着自己倒在车祸现场，躺在手术台上，男友和同伴奔向医院，护士在耳边喃喃低语，一边思索要如何做出这艰难的选择：是随父母离世而去，还是苏醒过来继续人生。','Live for Love.',11000000,78874843,31.162838,7.3,1368,106,'2014-08-21','en','/7Twh8h3Wh7GC9npTAEUThgkxkWL.jpg',3.705611611052605,3,'2026-09-10',2,NULL,NULL),(250066,'美国劫案','American Heist','弗兰奇（艾德里安·布洛迪 Adrien Brody 饰）刚刚结束为期十年的漫长牢狱之灾，然而，艰苦的铁窗生活却并没有改变他暴戾邪恶的性格，刚刚出狱没多久，他便开始筹划着干一笔大买卖，以此作为收官之战。 弗兰奇找到了自己的弟弟詹姆斯（海登·克里斯滕森 Hayden Christensen 饰），希望能够得到他的帮助，然而，詹姆斯早已经弃暗投明，成为了一名汽车修理工。他打算和女友艾米丽（乔丹娜·布鲁斯特 Jordana Brewster 饰）一起踏踏实实过日子，共同打造美好安定的未来。弗兰奇的出现彻底搅乱了詹姆斯的人生计划，眼见弟弟不情不愿，弗兰奇竟然以艾米的性命为威胁，无奈之下，詹姆斯只得就范。','Brothers in arms for life.',10000000,0,11.431434,4.3,158,94,'2014-09-11','en','/526uxanwv4mMK0YTxjVrsmMXXo2.jpg',2.8636671945016907,3,'2026-09-10',2,NULL,NULL),(250124,'The Diary of a Teenage Girl','The Diary of a Teenage Girl','Minnie Goetze is a 15-year-old aspiring comic-book artist, coming of age in the haze of the 1970s in San Francisco. Insatiably curious about the world around her, Minnie is a pretty typical teenage girl. Oh, except that she’s sleeping with her mother’s boyfriend.','Some things are best kept secret.',2000000,1477002,18.224326,6.8,279,98,'2015-08-07','en','/5YlUrdYKuscD7pwf3yy9duVLbui.jpg',3.156099710769459,3,'2026-09-10',2,NULL,NULL),(250184,'Locker 13','Locker 13','The story of Skip, a young ex-convict who takes a position as a night janitor at an old-west theme park. His supervisor Archie, teaches him the ropes, but more importantly attempts to convey critical philosophical messages through a series of four stories: a down and out boxer is given the opportunity to become a real golden gloves killer; an assassin kidnaps three people in order to find out who hired him for his latest hit; a new recruit is initiated into a lodge of fez-wearing businessmen where hazing can take a malevolent turn; and a member of a suicide club introduces real fear into a man about to jump to his death.',NULL,0,0,1.905197,6.8,3,90,'2014-03-29','en','/cafljB271v1L4smQT0n0Tznor79.jpg',2.140010038190248,3,'2026-09-10',2,NULL,NULL),(250349,'Barbecue','Barbecue','On his 50th birthday, a man who\'s been watching his weight, health and temper all his life suffers a heart attack. He\'s been doing everything he was told he should do and it still didn\'t help. He decides to turn the page and let loose.',NULL,6000000,14348529,5.119593,5.8,214,98,'2014-04-30','fr','/f6qSHIFvo2NhvlbAi8WBehd4Xne.jpg',2.9904003746193935,3,'2026-09-10',2,NULL,NULL),(250546,'安娜贝尔','Annabelle','新婚燕尔的约翰·戈登（瓦德·霍尔顿 Ward Horton 饰）和妻子米娅（安娜贝拉·沃丽丝 Annabelle Wallis 饰）共同孕育了新的生命，对于这对未经世事的小夫妻来说，喜悦和担忧相伴而行。那个晚上，约翰找到了妻子寻觅已久的娃娃安娜贝尔，与此同时，邻居彼得家则发生了残忍血案，更为可怕的厄运也朝着戈登夫妇袭来。几名丧失人性的邪教男女闯入戈登家中，试图对他们展开屠杀。虽然戈登夫妇侥幸保住性命，但其中一名女子抱着安娜贝尔死去。在此之后，惴惴不安的米娅待在家中安胎，她试图从阴影中走出，然而接二连三的怪事相继在家中发生。\r 　　诡异而恐怖的恶魔盛宴就此拉开帷幕…… ©豆瓣','Before the Conjuring, there was Annabelle.',6500000,255273813,60.225219,5.6,1517,99,'2014-10-02','en','/udiXYwya8piLGV5Ac1w5yJSHKQb.jpg',3.458090017148319,3,'2026-09-10',2,NULL,NULL),(250902,'The Image Revolution','The Image Revolution','Twenty years ago, seven superstar artists left Marvel Comics to create their own company, Image Comics, a company that continues to influence mainstream comics and pop culture to this day. Image began as more than just a publisher - it was a response to years of creator mistreatment, and changed comics forever. The Image Revolution tells the story of Image Comics, from its founders\' work at Marvel, through Image\'s early success, company difficulties during the comics market implosion, and ultimately the publisher\'s new generation of properties like The Walking Dead. Filled with colorful characters, the film is a clarion call to artists to take control of their destiny.',NULL,50000,0,0.54562,5.7,3,81,'2013-11-21','en','/p49QvZ3Ci0yE5FNgAUThL77QAAt.jpg',2.135550984497345,3,'2026-09-10',2,NULL,NULL),(251321,'在空中','Aloft','伊万在他还是个孩子的时候，他的母亲娜娜(詹妮弗·康纳利 饰演)在农场工作，同时拉扯着小伊万(Zen McGrath 饰演)和他患有衰竭性疾病的弟弟古利(Winta McGrath 饰演)。娜娜希望伊万能够照顾古利，但叛逆的伊万却沉浸在自己的世界当中，他和一只名叫做因蒂(Inti)的猎鹰形影不离。一天来了一位治病的术士，通过他，娜娜发现了自己有着治愈的能力。接下来他们用树枝搭起帐篷，在帐篷里面帮助医治了许多生病的孩子。然而一件不幸的意外降临到了娜娜和她的孩子们身上。多年以后，长大成人的伊万(希里安·墨菲 饰演)前来寻找他的母亲。他如今也成为了一名父亲。他从别人口中听说，娜娜把她的帐篷搭在了一个冰冻的湖面的尽头……',NULL,8000000,53086,6.500835,5.1,41,112,'2014-02-12','en','/fxwJywCV6XLAFi0FcqVyduw0Fu.jpg',2.644068816248955,3,'2026-09-10',2,NULL,NULL),(251471,'乐高积木世界','Beyond the Brick: A LEGO® Brickumentary','乐高玩具公司官方纪录片，透过镜头一步步抽丝剥茧的来述说乐高积木的文化背景、艺术价值、教育意义。电影的采访对象将不只有主要年龄层的玩家，也有更多成人乐高迷、乐高迷自行组成的玩家团体、乐高艺术家以及乐高名人等等都会一同出现......',NULL,650000,0,1.631274,6.4,55,93,'2015-07-31','en','/4YKDmHzTpS4mbas02UpvVDCXbNY.jpg',2.71765537698878,3,'2026-09-10',2,NULL,NULL),(251979,'The Perfect Wave','The Perfect Wave','“The Perfect Wave” is the true story of Ian McCormack who grew up surfing the waters of New Zealand. Wanting to dive deeper, Ian sets out on a journey with his best friend that will change his life as they chase the perfect wave.',NULL,0,0,4.118612,4.4,21,113,'2014-02-28','en','/sRbFTl2OkANyTm26IbwUZ3Vr3ay.jpg',2.500004604864128,3,'2026-09-10',2,NULL,NULL),(252360,'地牢围攻3','In the Name of the King III','一位残酷的赏金杀手Hazen Kaine（多米尼克·珀塞尔 饰）返回到了中世纪的欧洲，在那里，他必须为自己的生命来对抗邪恶骑士的军队。Hazen Kaine一直想摆脱卖身契，成为一个自由人，过上隐居自由的生活。但是，他必须执行最后一个任务。  《地牢围攻3》是乌维·鲍尔执导，多米尼克·珀塞尔、Shelly Varod、Marian Valev、拉里特萨·帕斯卡莱瓦主演的一部穿越题材的动作奇幻电影。本片是由加拿大、保加利亚联合出品。',NULL,3500000,0,4.304341,3.3,19,85,'2013-12-27','en','/8trjHL8mvHcmtEtbdRC0GxFywxS.jpg',2.4726800357429144,3,'2026-09-10',2,NULL,NULL),(252512,'年轻时候','While We\'re Young','一对夫妇过着平凡又重复的生活，直到他们遇见一对新鲜潮人。生活是变得丰富，还是终归各活各的。','Life Never Gets Old.',10000000,7587485,19.263477,5.8,383,97,'2015-04-03','en','/kbFyw7THCfARzY8aZwIjn6LLWyn.jpg',3.137632067567758,3,'2026-09-10',2,NULL,NULL),(252680,'母亲外出之夜','Moms\' Night Out','艾莉森和她所有的主妇朋友们最期望的事情就是一个安静的、只属于成年人的夜晚。来一顿大餐，和朋友们聊聊天，一个“妈妈外出的夜晚”是她们最需要的事情了。但是，那些成人间的愉快谈话，穿着漂亮的新高跟鞋出去的时光可不是那么容易得到的。','What could go wrong?',5000000,10429707,10.274542,5.5,121,98,'2014-03-25','en','/gP97yU8YrVZY2yLxTwsicS8KuSe.jpg',2.8742518693001973,3,'2026-09-10',2,NULL,NULL),(253235,'情到自然明','And So It Goes','影片中，道格拉斯饰演的房产经纪人急功近利脾气暴躁，周围的人对他充满了厌恶，本以为事情会愈演愈烈，没想到却出现了转机，在小孙女的调和下，他与周围人的接触渐渐平和......',NULL,18000000,25312387,9.633711,5.7,164,94,'2014-07-20','en','/bJoWtA8OAIqavlb5mbx3EzvxFUA.jpg',2.9417824279037292,3,'2026-09-10',2,NULL,NULL),(253253,'Animals','Animals','ANIMALS tells the story of Jude and Bobbie: a young couple that exist somewhere between homelessness and the fantasy of their imaginations. Though they masterfully con and steal in an attempt to stay one step ahead of their addiction, they are ultimately forced to face the reality of their situation when one of them gets hospitalized.',NULL,0,0,1.5846,6.2,9,90,'2014-05-15','en','/2mwMeQ5SEmw1cEUBVYEtP3helTo.jpg',2.3377218975223224,3,'2026-09-10',2,NULL,NULL),(253261,'生而飞翔','Born to Fly: Elizabeth Streb vs. Gravity','Born to Fly pushes the boundaries between action and art, daring us to join choreographer Elizabeth Streb and her dancers in pursuit of human flight.',NULL,0,0,0.069244,5,1,82,'2014-03-08','en','/3Dvthr7XOP045DY2sXhgzKaYTEY.jpg',1.9839979568684651,3,'2026-09-10',2,NULL,NULL),(253290,'Butterfly Girl','Butterfly Girl','Abbie came of age in honky tonks, defying her life threatening disease, but all the while longing for an identity of her own. Now that she is 18, how much is she willing to sacrifice for her independence?',NULL,0,0,0.015189,0,0,77,'2014-03-10','en','/nQRsj3wRXOesAaN0I31rSNz2WX7.jpg',1.8338170799860356,3,'2026-09-10',2,NULL,NULL),(253306,'足不出户','Housebound','吸毒成瘾凯莉·巴克奈尔（Morgana O\'Reilly 饰）和同伴抢劫取款机，结果被警方抓个正着。在此之后，她被法官判处家中监禁八个月。凯莉的老家位于一处偏远小镇，母亲米莉亚（Rima Te Wiata 饰）现正和另一个男人居住。在被装上监控装置后，凯莉失去了自由，每日只能蜷缩在这幢老旧破败的房子内。某天，她听广播时意外发现母亲向电台打进了热线，米莉亚声称曾在家中的地下室见过鬼影，这让她惶恐不安。凯莉一向反感妈妈神神叨叨的言行，可是没过多少天，她便真的遭遇了一连串的奇怪事件。在法律禁止逃离的情况下，凯莉只能求助于对灵异事件感兴趣的保安员阿莫斯（格伦-保罗·瓦鲁 Glen-Paul Waru 饰）。','Terror Gets Domesticated',0,0,10.322858,6.5,358,109,'2014-09-04','en','/jPKEeHmUuoDnIaRs6VUqSr4qRGR.jpg',3.1732050194941173,3,'2026-09-10',2,NULL,NULL),(253331,'黑白祖孙情','Black or White','影片讲述一个名叫埃利奥特的鳏夫（凯文·科斯特纳 饰）悲伤地卷入一场争夺抚养权的官司，他将跟由他抚养大的黑人孙女的亲祖母（奥克塔维亚·斯宾瑟 饰）争夺监护权。','There\'s more to family than what you see.',9000000,21571189,12.172131,6.5,115,121,'2014-09-06','en','/hOxxudUwgh5KGC7LtxDCkkwn1YP.jpg',2.9096609555216686,3,'2026-09-10',2,NULL,NULL),(253412,'绝命海拔','Everest','友善谨慎的新西兰领队罗布·霍尔（杰森·克拉科 Jason Clarke 饰），他的队伍名为“冒险顾问”；而斯科特·费雪（杰克·吉伦哈尔 Jake Gyllenhaal 饰）则风趣搞怪，他带领来自西雅图的“疯狂山脉”登山队。他们相互竞争，又彼此帮助。两支队伍中的勇士们来自各行各业，他们中有邮差、记者、医生，还有一名来自日本的职业女性。这些登山者看似平凡， 但每个人背后都有一个属于自己的梦想，激励着他们前往海拔 8000 米以上、氧气稀薄的珠峰。在攀登过程中，他们的身体机能急速下降，在应对体力衰竭、缺氧、雪盲的同时，他们又极为不幸地遭遇了一场剧烈的暴风雪，因此命悬一线。影片改编自 1996 年的一次真实探险经历。','The Storm Awaits.',55000000,203427584,60.246978,6.7,1772,121,'2015-09-10','en','/2jKOu2bjpLP6NXJcm7Ep14bDGtA.jpg',3.7206342532631913,3,'2026-09-10',2,NULL,NULL),(253450,'刺客聂隐娘','刺客聶隱娘','九世纪的中国。将军之女聂隐娘在十岁时被一名尼姑掳走，从此被带入武学殿堂。她被训练成一名技艺超群的顶尖刺客，专门负责铲除残暴贪婪的地方藩镇。一日，隐娘因未能完成任务，被师父遣回故里。她接到的新指令，是去刺杀曾与她有婚约的青梅竹马——如今统领华北最强悍藩镇的表兄。阔别十三载，重归故土的聂隐娘必须直面双亲、尘封的记忆以及内心深处压抑已久的情感。在师命的束缚下，她陷入了两难抉择：是亲手牺牲所爱之人，还是永远背弃刺客的“大义之道”？',NULL,15000000,632542,8.142166,6.6,157,105,'2015-08-27','zh','/7cFx665GKJ9YZGgKW2UVXcsLw37.jpg',2.977635800106705,3,'2026-09-10',2,NULL,NULL),(253626,'Good Kill','Good Kill','In the shadowy world of drone warfare, combat unfolds like a video game–only with real lives at stake. After six tours of duty, Air Force pilot Tom Egan (Ethan Hawke) now fights the Taliban from an air-conditioned bunker in the Nevada desert. But as he yearns to get back in the cockpit of a real plane and becomes increasingly troubled by the collateral damage he causes each time he pushes a button, Egan’s nerves—and his relationship with his wife (Mad Men\'s January Jones)—begin to unravel.',NULL,0,316472,10.924273,5.9,208,104,'2015-04-09','en','/w1s0XeYemVLmcdq4WTuAsjoBXwX.jpg',3.004641368426701,3,'2026-09-10',2,NULL,NULL),(254024,'天使面庞','The Face of an Angel','故事灵感来自讲述阿曼达·诺克斯案件(被控谋杀英国室友)的小说《Angel Face》。片中，女记者西蒙妮和男纪录片导演托马斯追踪一宗谋杀案，故事将着重于两人的心理变化。导演迈克尔·温特伯顿把男主角……','Forget the truth, find the story.',0,0,7.336256,4.7,64,100,'2014-09-06','en','/100pHE252kgwxwVNbiflYV9j1yi.jpg',2.7227700735952705,3,'2026-09-10',2,NULL,NULL),(254128,'末日崩塌','San Andreas','雷·盖恩斯正驱车前往旧金山，随着一声巨响，周围的树木与电线杆变得七扭八歪，紧急刹车查看状况的盖恩斯被眼前的景象“惊呆了”:公路被一条深不见底的裂隙截断，甚至错位，加油站被裂成两半隔着“峡谷”遥遥相对。随着这场超级地震毫无预 兆的来袭，整个城市浓烟滚滚、火光冲天，高楼大厦相继倒塌，到处都是惊慌失措的市民。更要命的是，如此强烈的地震，“摧枯拉朽”般粉碎了坚实的大坝，洪水如猛兽一般涌向已经水深火热的城市，“天崩地陷”的景象犹如“末日”已然来临……','A rescue pilot survived an earthquake, this is what happens next',110000000,470490832,100.412364,6,2968,114,'2015-05-27','en','/2Gfjn962aaFSD6eST6QU3oLDZTo.jpg',3.7723239623628504,3,'2026-09-10',2,NULL,NULL),(254470,'完美音调2','Pitch Perfect 2','贝卡（安娜·肯德里克 Anna Kendrick 饰）率领的巴顿大学阿卡贝拉女子美声合唱团终于出人头地，应邀为美国总统的生日宴会光荣献唱。谁知表演期间，“胖艾美”（蕾蓓尔·威尔森 Rebel Wilson 饰）竟意外走光，引起全场恐慌，令合唱团蒙上不雅污名，更被禁止公开演出！力挽狂澜的最后机会，就是赢得阿卡贝拉世界锦标赛的冠军，她们能否战胜来自德国的劲敌，挽回失去的名声，称霸阿卡贝拉的世界？','We\'re back pitches',29000000,287506194,71.496894,6.8,1940,115,'2015-05-07','en','/fQaEGzFmvTYu3G641WV0Tg9auAt.jpg',3.791032284399265,3,'2026-09-10',2,NULL,NULL),(254472,'蜂螫','Stung','一辆货车行驶在泥泞的乡间小路上，酒保保罗（马特·欧莱瑞 Matt O\'Leary 饰）和派对组织者茱莉娅（Jessica Cook 饰）正前往他们的目的地，某个山间别墅。别墅所有人波奇妇人（Eve Slatner 饰）每年都会组织派对，请来至交亲朋共同缅怀她去世的丈夫。晴朗的午后，保罗他们有条不紊地布置会场，除了不知从何处而来的马蜂比较讨厌外，其他还都顺利。夜幕降临，宾客相继来到别墅庭院，大家共斟美酒，喜形于色。而就在此时，诡异疯狂的麻风再次出现，它们肆无忌惮袭击在场的每个人，被袭击者受到感染，体内很快诞生出巨大的马蜂怪。  　　人们一个接一个倒下，而无情冷酷的杀手正向为数不多的幸存者们逼近……','Get inside, get away, just don\'t get stung',2500000,0,4.270489,4.9,63,87,'2015-07-03','de','/biYNeIVCX2lOqKoGeHJ55m9i28A.jpg',2.7176689471126436,3,'2026-09-10',2,NULL,NULL),(254473,'暴力街区','Brick Mansions','美国底特律罪恶横行，为了保障市民安全，当局将市内最危险的罪犯隔离，安置他们在令人闻风丧胆的罪恶禁区“红砖特区”（Brick Mansions）。\r 　　在弱肉强食的“红砖特区”内，残暴冷酷的大毒枭特里梅因（RZA 饰）为邪恶核心，卧底探员达米安（保罗·沃克 Paul Walker 饰）一直希望将他绳之于法。另一方面，希望离开禁区重过新生活的利诺（大卫·贝利 David Belle 饰），因为女友罗拉被特里梅因掳走而心急如焚。拥有共同敌人，来自不同世界，背景各异的达米安与利诺决定联手对付特里梅因……\r 　　本片翻拍自2004年同名法国动作电影《暴力特区》，也是保罗·沃克最后的完整作品。','Undercover and never Outgunned',28000000,68896829,25.520976,5.7,615,90,'2014-04-22','en','/fykYBitCBcjRvYsueBiLmtCnBoI.jpg',3.2302021630491096,3,'2026-09-10',2,NULL,NULL),(254904,'谍影特工','The November Man','人称“十一月杀手”的彼得·德卫洛克斯（皮尔斯·布鲁斯南 Pierce Brosnan 饰）是一名前CIA探员，本已金盘洗手的他打算享受来之不易的安静生活，然而他的计划却被打乱了——一个与他有非同寻常关系的重要证人正面临杀身之祸（欧嘉·柯瑞兰寇 Olga Kurylenko 饰），而她掌握着揭发数十年阴谋的关键证据。为了保护证人彼得不得不与CIA全面开战，而局里派来解决他的正是他昔日的徒弟与挚友（卢克·布雷西 Luke Bracey 饰）。面临阴谋和背叛，一场恶战即将展开……  　　影片改编自比尔·格兰杰1987年的小说《没有间谍》。','A spy is never out of the game.',15000000,32556119,45.317278,6,639,108,'2014-08-27','en','/AvgtNpVP7FlJjUZdRQEu0JPK0H7.jpg',3.324599449585122,3,'2026-09-10',2,NULL,NULL),(255266,'Dry Spell','Dry Spell','Sasha tries to get her soon-to-be ex husband Kyle laid so she can move on with her sex life guilt-free.','Getting divorced does funny things to a girl',22000,0,0.048948,6,1,90,'2013-02-14','en','/u9oGJbBEFoyiHQ1rE3dRFOcyfqD.jpg',1.9843628766384798,3,'2026-09-10',2,NULL,NULL),(255343,'毒枭帝国','Escobar: Paradise Lost','尼克是个涉世未深的大学生，与哥哥一起来到哥伦比亚旅行冲浪时，爱上了一个当地的女孩玛利亚，而玛利亚正是毒枭帕布罗·埃斯科巴的侄女，尼克由此进入埃斯科巴的毒品网络，成为其亲信之一。政府对贩毒组织的大规模调查和打击开始之后，埃斯科巴的疑心也日渐加重，尼克的处境岌岌可危……  本尼西奥·德尔·托罗在片中扮演的毒枭帕布罗·埃斯科巴（Pablo Escobar），历史上确有其人。他是哥伦比亚臭名昭著的“可卡因之王”，1993年死于哥伦比亚警方的追捕行动。','Welcome to the family',17000000,3758328,25.112567,6.1,271,120,'2014-10-11','en','/4HngNLzCmUYCPB8FbxSZWN0eDKM.jpg',3.1074032714553197,3,'2026-09-10',2,NULL,NULL),(256040,'Baahubali: The Beginning','Baahubali: The Beginning','The young Shivudu is left as a foundling in a small village by his mother. By the time he’s grown up, it has become apparent that he possesses exceptional gifts. He meets the beautiful warrior/princess Avanthika and learns that her queen has been held captive for the last 25 years. Shividu sets off to rescue her, discovering his own origins in the process.',NULL,40000000,100000000,16.254032,7.5,135,159,'2015-07-10','te',NULL,3.0027561536755174,3,'2026-09-10',2,NULL,NULL),(256092,'惊天追逐','Drive Hard','一名前赛车手退役后转行成为驾校教练，却在教学途中被一个神秘的盗贼绑架并被迫为犯罪组织驾车比赛 。这让他在警察与黑帮的追捕中夹缝求生，澳大利亚黄金海岸就此上演一出火爆追逐大戏！','One Hell of A Ride',12000000,0,3.94487,3.9,74,96,'2014-05-26','en','/wSujXhZJPvwKtMhIAuIuXZ93gYO.jpg',2.719109971832319,3,'2026-09-10',2,NULL,NULL),(256274,'巴黎地下墓穴','As Above, So Below','伦敦大学的教授斯嘉丽（佩蒂塔·维克斯 Perdita Weeks 饰），年纪轻轻便拥有考古学、符号学等专业学位，更掌握四国语言。她的父亲曾经致力于点金石的探索研究，可悲的是最后死于非命。继承了父亲遗志的斯嘉丽在新近一次冒险中，从伊朗一座即将被炸毁的墓穴里找到了传说中的罗塞秘钥，这个关键发现可以帮她找到点金石的蛛丝马迹。为了实现这个目标，她请来班吉（艾德文·霍德吉 Edwin Hodge 饰）担任摄影记录工作，还拜托曾经与之一同出生入死的乔治（本·费德曼 Ben Feldman 饰）担任翻译。  这几个胆大妄为的年轻人，随后试图闯入埋葬着六百万尸体的巴黎地下墓穴探险，而恐怖的体验也就此展开…','The only way out is down.',5000000,40100000,26.510558,6.1,766,93,'2014-08-14','en','/z13JwYlouKfgk49LU84NfXydkw6.jpg',3.334796661798163,3,'2026-09-10',2,NULL,NULL),(256591,'焦点','Focus','本片的编导组合格伦•费卡拉、约翰•雷夸此前作品《我爱你莫里斯》和《疯狂愚蠢的爱》都颇受好评。在该片中，史密斯扮演一名以诈骗为业的中年男子，他同一名年轻的女小偷协同作案，但当两人之间产生了爱情事情变得复杂了起来。','Never Drop The Con.',50100000,153962963,59.634029,6.7,2542,105,'2015-02-25','en','/lOzGWjceYTd0kd5HyX7Ch46O9kh.jpg',3.809639688195083,3,'2026-09-10',2,NULL,NULL),(256687,'燥热','Swelter','这是在拉斯维加斯历史上最臭名昭著的抢劫。五名男子，绰号“五鼠”，曾打劫卢克索赌场一亿美元。不久，四名劫匪被抓获，而另一名劫匪勉强逃脱。十年后，四名劫匪逃脱监狱，准备追击那名逃脱的劫匪和那一大笔赃款。经过追查，他们发现了以前的同伙已经成为了现在的州长……于是，州长必须再次成为铁血汉子，与四名劫匪斗智斗勇，保护自己现在所珍视的一切。','Greed. Revenge. Redemption.',0,0,2.214925,4.6,21,96,'2014-04-20','en','/3DJ8KOT2t8y8FiLn3hrMyPT9MyS.jpg',2.497337486068153,3,'2026-09-10',2,NULL,NULL),(256740,'邪恶骨血','Wicked Blood','汉娜·李·贝克是一个明亮的十几岁的女孩被困在暴力和枪支，冰毒实验室和恶性骑自行车团伙，而其唯一的避难所是国际象棋的黑暗南方黑道。她与琥珀，她的姐姐，和她的叔叔唐尼，一个吸毒者。每个人都生活在恐惧之中叔叔弗兰克·斯廷森，谁运行非法的家族企业以铁腕，他的精神病的弟弟鲍比辅助的。事情变坏时，琥珀爱上野生比尔，一个甲基毒贩谁发现自己在与弗兰克战争。汉娜认识到拯救她的家庭的唯一途径是通过巧妙策划坑一兵对抗另一个狡猾的棋局。','The Ultimate Endgame',3500000,0,3.158056,5.3,37,92,'2014-03-04','en','/dTxOsk0wVG1EgyCbWbaNxQXZLxy.jpg',2.6191036525314915,3,'2026-09-10',2,NULL,NULL),(256917,'占水师','The Water Diviner','一名在澳洲以农为业的的占水师康纳（罗素·克劳 Russell Crowe 饰）在第一次世界大战加里波利战役后前往土耳其伊斯坦堡，试图寻找他三个参战阵亡儿子的遗骸。即使一开始遭到军方的百般阻挠，他也不屈不挠，更遇到于伊斯坦堡入住旅馆女主人爱莎（欧嘉·柯瑞兰寇 Olga Kurylenko 饰）及一名曾与他儿子对战的土耳其军官出手协助。康纳抓住一丝希望，为查出真相，穿越饱受战火蹂躏的土地，九死一生，只为寻回儿子阵亡的真相，了结自己及妻子的心愿……','To honour a promise. To find his sons. To make his peace.',22500000,15520023,22.096286,6.8,431,112,'2014-12-25','en','/15s8IN6cQLRv6VMRHpsr36fPfNO.jpg',3.2786546777098926,3,'2026-09-10',2,NULL,NULL),(256924,'丹尼·科林斯','Danny Collins','1970年代传奇摇滚乐手丹尼柯林斯（阿尔·帕西诺 Al Pacino 饰）在经历人生低潮时，由经纪人（克里斯托弗·普卢默 Christopher Plummer 饰）发现了一封40年来从未送达的信，这封信居然是来自披头士主唱约翰·列侬在40年前写给当时19岁的他，这让他 再度受到启发，毅然决然地离开现在奢华的生活，踏上寻找生命意义的旅程，而他也在这段旅程中收获了真爱和消失已久的创作灵感……','A letter from John Lennon changed his life',10000000,10835752,16.318608,6.6,183,107,'2015-03-19','en','/55Cr4BftavTYPigEjLE4v0MDW21.jpg',3.032824264098196,3,'2026-09-10',2,NULL,NULL),(256961,'百货战警2','Paul Blart: Mall Cop 2','在商场当了六年保安的保罗（凯文·詹姆斯 Kevin James 饰）攒够了假期，带着即将上大学的女儿玛雅（莱妮·罗德里格兹 Raini Rodriguez 饰），来到“赌城”拉斯维加斯的安可酒店，参加保安大会。\r 　　会议中途，保罗无意间发现了一个密谋抢劫拉斯维加斯所有赌场的黑帮团伙，于是，他继续跨着电动平衡车，与其他前来参加大会的保安们一起，和天才黑帮首领斗智斗勇，保卫赌城……','Vegas has a new high roller.',38000000,107597242,41.258487,5,567,94,'2015-04-16','en','/83j0E2AkcA29ft6U9JgOIcXnIoE.jpg',3.1591050510779084,3,'2026-09-10',2,NULL,NULL),(256962,'小男孩','Little Boy','一个8岁的美国小孩（雅各布·萨尔瓦提 Jakob Salvati 饰）要用他父亲詹姆斯（迈克尔·拉帕波特 Michael Rapaport 饰）曾经教导他所要拥有的信念与意志，去完成一个不可能的任务，就是要把他爸爸从第二次世界大战的战场中带回来。','Believe the impossible.',20000000,6420319,12.232048,7,185,106,'2015-04-23','en','/vVmRcFUscMsz5diDMohNLVaE2Xc.jpg',3.050397174142717,3,'2026-09-10',2,NULL,NULL),(257087,'恐怖面纱','The Veil','三十年后一个宗教的成员大规模自杀,唯一的幸存者回到现场。。。','The dead come back',4000000,0,12.822534,4.5,118,93,'2016-04-21','en','/ggtoK1s0FekFue1kkvp93lOLdQY.jpg',2.833401445488931,3,'2026-09-10',2,NULL,NULL),(257088,'极盗者','Point Break','年轻的FBI特工强尼·犹他，潜伏到一队喜欢寻找刺激挑战的盗匪里，该队伍由富有个人魅力的鲍迪领导。这些盗匪被怀疑是在用极不寻常的方式进行着系列犯罪。在与鲍迪这一伙人的交往中，犹他发现自己无可自拔的与这伙人产生了伙伴情谊，犹他陷入了职业伦理与追求真我之间的矛盾，他放弃了自己的一切，加入到了对人类极限界的八项巅峰挑战的追寻中……','The only law that matters is gravity',105000000,133718711,33.507289,5.5,783,114,'2015-12-03','en','/jwPJluOJNS47RGQJK0CaSsjBxen.jpg',3.2622687689387546,3,'2026-09-10',2,NULL,NULL),(257091,'狱前教育','Get Hard','家财万贯的对冲基金经理詹姆斯（威尔·法瑞尔 Will Ferrell 饰）因为诈欺被判刑，法官特别给了他30天的时间让他安排处理工作上的相关事宜，身家百万的他为了准备好自己即将面对的恐怖监禁生活，雇用了平常帮他洗车的男子（凯文·哈特 Kevin Hart 饰），在最后自由的30天内对他加强训练，以应付之后的监狱生活……','An education in incarceration.',40000000,111811453,36.301202,5.9,944,100,'2015-03-26','en','/fk8EnGD6mHdYRlnOuLX3USOHiCj.jpg',3.3684155378634304,3,'2026-09-10',2,NULL,NULL),(257211,'实习生','The Intern','70 岁的鳏夫本回应了一则招聘老年实习生的广告，肩负巨大压力的时尚企业家朱尔斯从他那里得到了意想不到的支持。','Experience never gets old',35000000,194564672,53.114573,7.1,1881,121,'2015-09-24','en','/u7o3TwUgukRzTIyPwdMVdqmMRMD.jpg',3.8059439038162504,3,'2026-09-10',2,NULL,NULL),(257344,'像素大战','Pixels','作为1980年代的小孩，山姆·布伦纳（亚当·桑德勒 Adam Sandler 饰）, 威尔·库珀（凯文·詹姆斯 Kevin James 饰），勒德洛·莱门梢夫（乔什·加德 Josh Gad 饰）和“火焰爆破枪”埃迪·普兰特（彼特·丁克拉奇 Peter Dinklage 饰）拯救过世界成千上万次——在游戏机室里二十五美分玩一次的游戏里。现在，他们必须得真刀真枪作战了。\r 在像素大战中，当外星人发现经典街机游戏视频流并且误以为这是在宣战后，他们袭击了地球，运用游戏作为他们袭击策略——而现在美国总统库珀必须召集他旧日的街机战友一起拯救世界免受吃豆人、大金刚、小蜜蜂、蜈蚣还有太空入侵者毁灭。加入他们一起战斗的，还有一名向街机斗士提供外星人战斗专用武器的专家，维奥莱特·冯·帕顿中校（米歇尔·莫纳汉 Michelle Monaghan 饰）。他们的唯一目标是，战胜8比特像素外星人，保卫地球……','Game On.',88000000,243637091,140.849495,5.6,2513,105,'2015-07-16','en','/d26S5EfVXLNxRXqyFy1yyl3qRq3.jpg',3.7364693435079745,3,'2026-09-10',2,NULL,NULL),(257445,'鸡皮疙瘩','Goosebumps','影片的故事讲述了迪兰·米内特饰演的邻居家男孩在一次偶然中，将斯坦书里奇幻而恐怖的生物带到了真实世界。为了避免这些数量巨大的恐怖怪物毁灭宁静的小镇，斯坦必须联合他的邻居和女儿进行殊死抵抗······','The stories are alive.',58000000,158162788,45.351617,6.2,995,103,'2015-08-05','en','/pv4I99Cf3N3Nymb8zwTE6AjKOjY.jpg',3.451640469305826,3,'2026-09-10',2,NULL,NULL),(257932,'龙之谷：破晓奇兵','龙之谷：破晓奇兵','不务正业的流浪少年兰伯特意外听到了邪恶的大黑龙手下魔族准备攻占阿尔特里亚大陆的情况，为了保护家乡他与魔物周旋被困，却被游侠巴尔纳救下，加入到了游侠杰兰特、阿尔杰塔（景甜 配音）的队伍中。精灵一族中的法师首领卡拉秋（夏梓桐 配音）也带着公主内尔文与弓箭手随从莉亚（徐娇 配音）前来邀请人类国王参战，面对魔物的入侵，他们和游侠队伍以及人类骑士贝斯柯德（胡歌 配音）组成了对付大黑龙的联盟。众人历经困难来到了大黑龙的巢穴，兰伯特与莉亚日久生情，但是他们却不知道杰兰特和阿尔杰塔，以及贝斯柯德各自带着不为人知的秘密……',NULL,40000000,0,5.057695,6.8,19,88,'2014-05-20','zh',NULL,2.5010922938027633,3,'2026-09-10',2,NULL,NULL),(258489,'泰山归来：险战丛林','The Legend of Tarzan','19世纪80年代，泰山（亚历山大·斯卡斯加德饰）已经离开了刚果丛林十年了，他与心爱的珍·波特（玛歌特·罗比饰）在维多利亚女王时代的英国伦敦生活。看似平静的城市生活对泰山来说并非真的自在，甚至感到窒息，身着考究的礼服，住在豪宅里，却找不到家的感觉。一次，他以英国议会贸易大使的身份重新回到刚果，但这次派遣实际上是一次比利时人里昂·罗姆（克里斯托弗·瓦尔兹饰）的阴谋。泰山、珍以及他的朋友们都陷入了危险，但丛林是泰山的天下，他开始重新飞檐走壁，拯救爱人和朋友 。','Human. Nature.',180000000,356743061,42.741719,5.5,2430,109,'2016-06-29','en','/5CC1TgJmJhg6Ai9MEjhfUcziHk8.jpg',3.4829087998763097,3,'2026-09-10',2,NULL,NULL),(258509,'鼠来宝4：萌在囧途','Alvin and the Chipmunks: The Road Chip','《鼠来宝4：萌在囧途》还是以三只可爱的花栗鼠为主角，讲述了花栗鼠艾文、赛门 以及喜多 由于一系列误会，以为它们的主人大卫 要在迈阿密向其新女朋友求婚，并有可能抛弃它们。它们得赶往迈阿密，找到大卫并阻止求婚。因为这样不仅不会失去大卫，还可能避免获得一位可怕的伙伴——大卫新女友的“小恶魔”儿子。一场跨越美国的音乐之旅即将爆笑启程。','Fast & furry-ous',0,233755553,27.867368,5.8,428,92,'2015-12-17','en','/6nRCZxelFUmFunoHEiXUDmL0sj3.jpg',3.178956307934282,3,'2026-09-10',2,NULL,NULL),(258755,'爱，藏起来','A escondidas','“只因在人群中多看了你一眼，再也没能忘掉你容颜。”讲述男孩与男孩清新初恋的《爱，藏起来》，在刚结束的都灵同志电影节上获得最佳剧情片奖。电影讲述摩洛哥男孩伊布拉在西班牙已经生活三年，一直面临被遣返的压力。某晚在拥挤夜店的洗手间，他和西班牙少年拉法一个照面后竟久久无法忘怀。两人最终发展出一段难忘的初恋...',NULL,0,0,1.233688,7.6,26,96,'2014-10-03','es','/wsmwaihsRJpBKyjHGZxJ3UEpJj0.jpg',2.5676602902002497,3,'2026-09-10',2,NULL,NULL),(259693,'招魂2','The Conjuring 2','身在英国伦敦的单身母亲佩吉·哈德森（弗兰西丝·奥康纳饰）家中遭遇灵异事件。她家中的家具突然自己移动起来，11岁的女儿珍妮特（麦迪逊·沃芙饰）甚至被魔鬼缠身。随后罗琳（维拉·法梅加饰）与艾德（帕特里克·威尔森饰）被教会叫去调查此事，他们终于明白原来珍妮特说得都是真的。只是在亲眼目睹了哈德森家的灵异，罗琳开始怀疑是否应该接受此次驱魔任务。','The next true story from the case files of Ed and Lorraine Warren',40000000,320170008,68.794673,7,1949,134,'2016-05-13','en','/zEqyD0SBt6HL7W9JQoWwtd5Do1T.jpg',3.829729850238624,3,'2026-09-10',2,NULL,NULL),(259694,'单身指南','How to Be Single','这部新片由《爱你，罗茜》克利斯汀·迪特执导，女作家Liz Tuccillo（《他其实没那么喜欢你》）作品改编，讲述了在纽约生活的一组人互不相干但又相互交织的情感经历。','Welcome to the party',38000000,112343513,46.078371,5.9,1201,110,'2016-01-21','en','/9ldXx0FDYdfSZD3jYNmRAcm1lPs.jpg',3.439284478669282,3,'2026-09-10',2,NULL,NULL),(259943,'归来','归来','陆焉识与冯婉瑜本是一对恩爱夫妻，却因陆焉识被当作政治犯逮捕并送往劳改营而被迫分离，妻子亦在此时受伤。文化大革命末期获释归来的他，发现深爱的妻子因失忆症几乎忘记了过去。无法认出丈夫的冯婉瑜，仍在苦苦等待自己的丈夫归来。在这个破碎的家庭中形同陌客的陆焉识，决心重拾两人共同的过去，唤醒妻子的记忆。',NULL,0,0,6.017273,6.9,49,111,'2014-05-16','zh','/37RL5PYX42RBLXJ6HI38XcRZehQ.jpg',2.7119003828459056,3,'2026-09-10',2,NULL,NULL),(260346,'飓风营救3','Taken 3','连姆·尼森所扮演的硬汉特工布赖恩与前妻诺尔破镜重圆，岂料好景不长。诺尔在家里被谋杀，而布赖恩成了杀妻凶手。带着满腔的愤怒，布赖恩以熟练的身手躲开CIA，FBI和警方的追捕。这一次，布赖恩将会运用他的特别技巧寻找真正的凶手，以独特的方法伸张正义，并保护唯一一个对他对最重要的人——他的女儿小金。','It Ends Here',48000000,325771424,88.844777,6.1,2200,109,'2014-12-16','en','/vzvMXMypMq7ieDofKThsxjHj9hn.jpg',3.7051898218783204,3,'2026-09-10',2,NULL,NULL),(260778,'வாலு','வாலு','Sharp (Simbu), a happy-go-lucky guy, loves Priya (Hansika), a college student, but later learns that she is enagaged to Anbu ( Aditya), a businessman-gangster. Priya wants them to remain friends and Sharp agrees, all the while scheming to make her fall in love with him.','Life is what u make it',0,0,0.320387,6.7,5,155,'2015-08-14','ta',NULL,2.2247911622297267,3,'2026-09-10',2,NULL,NULL),(260947,'恶行','Something Wicked','A young couple embark upon their honeymoon against the chilling landscapes of the Pacific Northwest. But when tragedy strikes, gruesome secrets from their past collide with sinister forces of the present...',NULL,3000000,0,1.968679,4.6,16,95,'2014-04-04','en','/fmKcL3irtCGs1ZWcpx2tKcebp3i.jpg',2.4437505771015053,3,'2026-09-10',2,NULL,NULL),(261023,'黑色弥撒','Black Mass','影片讲述了臭名昭著的波士顿黑帮头目詹姆斯·巴尔杰（James \"Whitey\" Bulger，为美版《无色间道》人物原型）的故事，根据名为《黑弥撒：FBI和爱尔兰黑帮不光彩合作的真实故事》（Black Mass: The True Story of an Unholy Alliance Between the FBI and the Irish Mob）的纪实小说改编，该书由普利策获奖得主、《波士顿环球报》记者Dick Lehr和Gerard O\'Neill共同创作。\r 　　詹姆斯·巴尔杰是全球十大在逃通缉犯之一，他发迹于波士顿，获奥斯卡最佳影片的《无间道风云》中的黑帮大佬就有他的影子。巴尔杰建立的“冬日山岗”帮（Winter Hill Gang）是波士顿著名的黑帮组织，从贩卖毒品到倒卖军火无恶不作，另外他们和包括爱尔兰共和军（Irish Republican Army）在内的北美及欧洲许多主要的犯罪集团都有联系。姆斯·巴尔杰之所以能够逐渐壮大而不受法律制裁，和他在FBI任职的一位好友也有关系，这位探员名叫约翰·康纳利（John Connolly），是和巴尔杰从小玩到大的哥们，两人长大后选择了黑白不同的两条道路，但却拥有共同的利益点：巴尔杰为康纳利提供黑帮线报，康纳利则对巴尔杰的犯罪勾当睁一眼闭一眼。FBI一直想将巴尔杰捉拿归案，但得到了康纳利通风报信的巴尔杰14年前突然失踪，直到现在依然逍遥法外。而康纳利则在退休后才被发现是FBI的“内鬼”，此事成为美国法律体系的一大丑闻。','Keep your enemies close.',53000000,98837872,46.049902,6.3,1242,122,'2015-09-04','en','/mQrDe0eol4S1qjn8hHp2G1xBvan.jpg',3.5216400267266734,3,'2026-09-10',2,NULL,NULL),(262500,'分歧者2：绝地反击','Insurgent','翠丝（谢琳·伍德蕾 Shailene Woodley 饰）与老四（提奥·詹姆斯 Theo James 饰）捣毁旧世界的秩序，曝露他们的分歧者身分之后，如今已沦为逃犯，被博学派领导人珍宁（凯特·温丝莱特 Kate Winslet 饰）布下天罗地网追捕。大权在握并掌控无畏派叛军的珍宁，在已成为反乌托邦本营的芝加哥废墟中，大肆搜索所有潜在的分歧者。翠丝与老四暗中游走于友好派、直言派、克己派、无畏派等派别，企图寻找同盟。亲友受她牵连而丧命的悲痛，令翠丝必须勇敢抛开内疚，重亲定义自己，找出她家人不借牺牲生命所要保护的信念，和博学派对她不择手段赶尽杀绝的原因。翠丝决定面对自己最深沉黑暗的恐惧，接受一连串近乎不可能的挑战，才能揭开这个世界过去的祕密，以及未来的真相……','One Choice Can Destroy You',110000000,295238201,103.718387,6.2,3829,119,'2015-03-18','en','/dP5Fb6YRfzmCQtRbHOr2kO7tJW9.jpg',3.884322137883263,3,'2026-09-10',2,NULL,NULL),(262504,'分歧者3：忠诚世界','Allegiant','世界已经分崩离析，翠丝（谢琳·伍德蕾 Shailene Woodley 饰）和老四（提奥·詹姆斯 Theo James 饰）必须逃往芝加哥城外的世界。这是他们第一次远离自己熟悉的城市和家人。可他们一来到外面的世界，就发现过去的一切都变得毫无意义，令人震惊的真相呈现在他们面前。芝加哥城外的战争一触即发，整个人类受到了威胁，这让翠丝和老四必须立刻做出判断究竟谁才值得信任。为了生存，翠丝被迫做出了关于勇气、忠诚、牺牲和爱的抉择。','Break the boundaries of your world',110000000,179246868,86.105615,5.9,1998,121,'2016-03-09','en','/eDVojWwnrotsLpSvTSZEgwLFVNv.jpg',3.6341295390295127,3,'2026-09-10',2,NULL,NULL),(262543,'机器纪元','Autómata','21世纪中叶，地球环境遭到巨大的破坏，人类文明和信仰不可遏止地崩塌。在一片乱象的关头，名为ROC的科技公司凭借他们研发的“朝圣者 7000”智能机器人迅速崛起。朝圣者深入民间每一个角落，帮助人们从生到死处理身边的一切事务。在两条根本原则的约束下，机器人们任劳任怨，不辞辛苦，与此同时也遭遇种种残酷无情的对待。贾克·波根（安东尼奥·班德拉斯 Antonio Banderas 饰）是ROC旗下的一名保险理赔员，在工作中他意外发现，许多朝圣者不仅被人私自篡改，连根本原则都遭到破坏。机器人们或伤害他人，或者自残，令贾克隐隐察觉背后似乎有什么阴谋存在。\r 　　他离开城市前往贫民窟寻找真相，在此见识到机器人可丽儿自我修复的神奇一幕。而执着的追索，也将贾克置身于莫大的危险中央…… ©豆瓣','Your time is coming to an end – Ours is now beginning',7000000,0,49.808505,5.6,670,110,'2014-10-09','en','/fQE5mjOUOZZmMjSbRydjYInekaz.jpg',3.2872376111705712,3,'2026-09-10',2,NULL,NULL),(263503,'Water & Power','Water & Power','绰号 \"Water\" 和 \"Power\" 双胞胎兄弟在危险和复杂的洛杉矶权利网中杀出了一片天体，他们牢牢的控制了洛杉矶的东部街区并渗透到了警界和政界……',NULL,0,0,0.350557,3,1,0,'2014-05-02','en','/qCtw7zmL2dbMqK1u6K8ZQUMip6j.jpg',1.983817971462199,3,'2026-09-10',2,NULL,NULL),(264644,'房间','Room','影片讲述了五岁男孩杰克的非凡故事。他性格活泼，由挚爱且无私的母亲悉心照料。如同所有伟大的母亲，妈妈倾尽全力守护杰克的快乐与安全，以温暖和慈爱哺育他，陪他游戏、讲故事，践行着平凡母子间的日常。然而，他们的生活却远非寻常——二人被困于一个仅十英尺乘十英尺、被母亲委婉称为“房间”的封闭空间。妈妈在“房间”里为杰克构筑了完整的天地，并拼尽一切确保即使在这险恶环境中，杰克仍能度过充实而有意义的人生。但随着杰克对处境的好奇日渐增长，妈妈的坚韧也逼近极限，他们策划了一场危险的逃脱计划。最终，二人不得不直面可能比囚禁更令人畏惧的存在：现实世界。[A24]','Love knows no boundaries',6000000,35401758,66.11334,8.1,2757,117,'2015-10-16','en','/2hHDMeYyZjbGWn0BeNH1cTMxuM7.jpg',4.17670773121083,3,'2026-09-10',2,NULL,NULL),(264656,'送乡人','The Homesman','故事发生在美国拓荒时期，无赖琼斯和一个边境小镇的女人护送三个患有精神疾病的妇女从内布拉斯加州前往爱荷华州，一路上他们将在严酷的自然环境中经历诸多磨难。无赖琼斯的角色应该由汤米·李·琼斯出演，希拉里·斯万克确定饰演那个边境小镇的女人，梅丽尔·斯特里普的角色目前尚未确定，据猜测可能是被护送精神病妇女中的一员。',NULL,16000000,3442853,20.59148,6.4,258,122,'2014-05-18','en','/hZnWBR830dGHqrzotjgz3hDNqeq.jpg',3.1100174012339292,3,'2026-09-10',2,NULL,NULL),(264660,'机械姬','Ex Machina','片中，伊萨克饰演一名神秘的亿万富翁，格里森饰演他公司的一名程序员，后者由于赢得公司一项幸运大奖而被邀请到老板的别墅共度周末。这栋别墅隐匿于林间，它其实是一座高科技的研究所。在那里，格里森被介绍给名为“伊娃”的人工智能机器人(艾丽西卡·维坎德 饰演)，原来他被邀请到这里的真正目的是进行针对伊娃的“图灵测试”(注：一项由图灵提出的测试机器是否具备人类智能的的著名实验）……','There is nothing more human than the will to survive',15000000,36869414,95.130041,7.6,4737,108,'2015-01-21','en','/dmJW8IAKHKxFNiUnoDR7JfsK7Rp.jpg',4.275621556382148,3,'2026-09-10',2,NULL,NULL),(264999,'魔力麦克2','Magic Mike XXL','麦克（查宁·塔图姆 Channing Tatum 饰）在脱衣舞男生涯的颠峰之时，急流勇退，远离了舞男的生活。后来，其他的舞男同伴也准备洗手不干。不过在收山之前，他们想要在美特尔海滩，展开一场盛大的告别秀，并邀请“魔力麦克”重出江湖。麦克与伙伴们上路，中途在小镇杰克逊维尔及萨凡纳短暂停留，与老友重聚，也结识了许多新朋友，还学到新的舞技。在他们的最后一场大秀中，绝对会有让人大开眼界的劲爆演出……','Back to the grind.',14800000,122513057,29.660993,6.3,706,115,'2015-07-01','en','/rt4AWBLpTtr32e66DtYxOBLUosp.jpg',3.3539129032145842,3,'2026-09-10',2,NULL,NULL),(265208,'Wild Card','Wild Card','When a Las Vegas bodyguard with lethal skills and a gambling problem gets in trouble with the mob, he has one last play… and it\'s all or nothing.','Never bet against a man with a killer hand.',30000000,0,48.0343,5.4,656,92,'2015-01-14','en','/m2fy0j9d04SNZFM1R9RSHtgfmRt.jpg',3.2509859849810083,3,'2026-09-10',2,NULL,NULL),(266034,'蓝色房间','La chambre bleue','在机械公司上班的中产阶级中年男子Julien被日渐乏味的生活和逐渐到来的中年危机打消了生活的热情，却在此时，意外邂逅了昔日的同窗Esther，进而无法抵挡对方富有侵略性的挑逗而与之发生了不伦之恋。他们屡次在一个酒店的蓝色房间偷情，而后他们的配偶分别凶残被害 ……',NULL,0,0,2.486992,6.2,32,75,'2014-05-16','fr','/1l6YEO5cC787mOb35wwZyxhkFvU.jpg',2.5998234091820427,3,'2026-09-10',2,NULL,NULL),(266102,'沙漠舞者','Desert Dancer','艾信的梦想是成为出色的舞蹈员。然而，在伊朗，跳舞是被禁止的行为。不过，艾信没有放弃，更与一群志同道合的朋友组成地下舞团。他们设法突破网络审查，翻墙到YouTube观看迈克尔·杰克逊等的表演片段自学跳舞。地下舞团更以打游击的形式大胆于沙漠表演，为自由起舞！这群年青人被冠上‘沙漠舞者’的称号。与此同时，伊朗正举行大选，无数群众上街争取自由，艾信的举动触怒政府，国民自卫队更奉命捉拿艾信。性命危在旦夕的艾信，为了跳舞，孤注一掷……','Be Brave. Be Bold. Be Free.',0,0,1.972668,6.5,18,98,'2014-07-03','en','/uV1GYM2gdit0SnNWAweG321evbg.jpg',2.480467709232565,3,'2026-09-10',2,NULL,NULL),(266396,'使命召唤','The Gunman','一位国际特种部队间谍吉姆 为了他的爱人而想要退出组织，但天不从人愿，就在他完成最后一项”任务“时，为了确保自身安全与公司利益，他必须要人间蒸发匿身他处，与心爱的人从此分开。离开组织在欧洲流亡多年后，吉姆以为能够脱离危险，就此过著 平静的生活；无奈人生并非他想像中单纯，在刚果被神秘人物追杀的他，被迫放下所有，展开逃亡。逃亡途中他辗转联系到昔日战友，并寻求他们的协助，却也因此发现追杀行动里暗藏著不为人知的祕密，而现在，唯有找出追杀他的幕后主使，才能给他一条生路……','Armed With the Truth.',40000000,13644292,26.935458,5.5,392,115,'2015-02-16','en','/t3PxDG0m9arlIFSiFk7m8slpDy.jpg',3.128205420079512,3,'2026-09-10',2,NULL,NULL),(266647,'小飞侠：幻梦启航','Pan','彼得·潘（莱维·米勒 Levi Miller 饰）是一个淘气的12岁小男孩，他是孤儿院院长眼中的头痛人物，因为他经常有叛逆的行为，这使他在成长的伦敦孤儿院中，显得特立独行。一个不寻常的夜里，彼得从孤儿院被带走，来到了一个名叫\"梦幻岛\"地方——一个充满海盗、战士与精灵的神奇国度。在梦幻岛上，他经历了许多惊心动魄的冒险和生死一线的对决，但这一切似乎与当年将他留在孤儿院的生母有关，在重重的谜团下，他与女战士虎莲公主（鲁妮·玛拉 Rooney Mara 饰）以及新朋友胡克船长（加内特·赫德兰 Garrett Hedlund 饰）结成盟友，一起面对一项古老的预言。预言中有一个佩戴着牧笛项链的勇士来到梦幻岛，他将带领所有人一起对抗邪恶的海盗黑胡子船长（休·杰克曼 Hugh Jackman 饰），但是只有12岁的小男孩彼得，是那个能够打败海盗黑胡子船长的勇士吗？  影片改编自英国作家詹姆斯·巴利的著名剧作 《彼得·潘》。','Every legend has a beginning.',150000000,128388320,48.03528,5.9,954,111,'2015-09-24','en','/8y2LYYncU1qAfcLs60Vc1SeK0jI.jpg',3.3973391411058276,3,'2026-09-10',2,NULL,NULL),(266856,'万物理论','The Theory of Everything','The Theory of Everything is the extraordinary story of one of the world’s greatest living minds, the renowned astrophysicist Stephen Hawking, who falls deeply in love with fellow Cambridge student Jane Wilde.','His Mind Changed Our World. Her Love Changed His.',15000000,123726688,61.182331,7.8,3311,123,'2014-11-26','en','/7kwcLFNt887saoQAL7EY0XnW7VI.jpg',4.148511438114827,3,'2026-09-10',2,NULL,NULL),(266857,'The Work and The Story','The Work and The Story','It is July, 2000 Richard Dutcher, the man who pioneered \"Mormon Cinema\" with his film \"God\'s Army\" is missing and presumed dead. Three amateur Mormon Filmmakers: Judy Shumway, Peter Beuhmann and Kevin Evans individually set out to make their first feature-length films to take Dutcher\'s place as the next \"Mormon Spielberg\". Who will win? Who will lose? Who will find Richard? And does everyone want Richard found?','Dream big. Make it happen?',0,0,0.002388,0,0,70,'2003-01-01','en',NULL,1.8337878399830185,3,'2026-09-10',2,NULL,NULL),(267860,'伦敦陷落','London Has Fallen','英国首相神秘逝世，美国特勤局特工迈克·班宁（杰拉德·巴特勒 饰）将配合特勤局局长琳·雅各布（安吉拉·贝塞特 饰）做好准备，陪同本杰明·阿瑟总统（艾伦·艾克哈特 饰）前往伦敦圣保罗教堂参加英国首相的国葬仪式。  由于所有大国首脑都必然要出席，这场葬礼理应是全世界安保最严密的活动。然而，各国首脑刚刚抵达不久便遭遇暗杀，伦敦地标建筑也纷纷遭袭。阿瑟、班宁和雅各布也遭到伏击，在连天的炮火和爆炸中撤退。满目疮痍的英国首都进入封锁状态。奉雅各布之命保护阿瑟总统的班宁必须躲开敌人的视线，抢在对手的前头先下手为强，不惜一切代价保护阿瑟总统安全回国。','The world\'s leaders have assembled. So have their enemies.',60000000,205754447,61.849521,5.8,1621,99,'2016-03-02','en','/3L7qSwiPCcXqutARdPFbdLNGYHu.jpg',3.5153787108157575,3,'2026-09-10',2,NULL,NULL),(267935,'The BFG','The BFG','The BFG is no ordinary bone-crunching giant. He is far too nice and jumbly. It\'s lucky for Sophie that he is. Had she been carried off in the middle of the night by the Bloodbottler, or any of the other giants—rather than the BFG—she would have soon become breakfast. When Sophie hears that the giants are flush-bunking off to England to swollomp a few nice little chiddlers, she decides she must stop them once and for all. And the BFG is going to help her!','The world is more giant than you can imagine.',140000000,183345589,44.19092,6,1000,120,'2016-06-01','en','/lhlLvaDXuuDi3Y56ezMrLQ1Siw.jpg',3.4153950577757315,3,'2026-09-10',2,NULL,NULL),(268171,'Elsa & Fred','Elsa & Fred','Aged, embittered widower, Fred learns to enjoy life thanks to his elderly yet vibrant neighbor, Elsa. Upon learning Elsa is terminally ill, Fred takes her to the Fontana di Trevi in Rome in order to reenact her favorite scene from ‘La Dolce Vita’.','It\'s never too late.',10000000,0,2.849895,6.2,31,104,'2014-03-07','en','/yNzVwtlqOmPLVKD5zZIzAME9vYc.jpg',2.5939373002980153,3,'2026-09-10',2,NULL,NULL),(268238,'涉外大饭店2','The Second Best Exotic Marigold Hotel','金盏花大酒店已住满了长期房客，联合经理穆瑞尔（玛吉·史密斯 Maggie Smith 饰）和桑尼（戴夫·帕特尔 Dev Patel 饰）梦想扩大经营，而他们正好找到了一个地点——“玛丽戈德饭店”。随着计划进行，伊芙琳（朱迪·丹奇 Judi Dench 饰）和道格拉斯（比尔·奈伊 Bill Nighy 饰）进入斋浦尔的职场中探索，摸索著他们的早餐约会将有何进展。  　　同时，诺曼（罗纳德·皮卡普 Ronald Pickup 饰）与卡萝（黛安娜·哈卡索 Diana Hardcastle 饰）在他们交往关系的漩涡中寻找方向，而玛琪（西莉亚·伊姆里 Celia Imrie 饰）面临两位“优质”黄金单身汉的追求，新房客盖钱伯斯（理查·基尔 Richard Gere 饰）则在桑尼的母亲卡普尔太太（莉蕾特·杜贝 Lillete Dubey 饰）身上，找到他下一本小说的灵感。当桑尼与真命天女苏奈娜（蒂娜·德赛 Tina Desai 饰）的婚礼逐步逼近时，寻找新酒店的计划更占据了他所能投入的时间，也许唯一知道答案的人是穆瑞尔，她保守著每个人的秘密。随着大喜之日接近，家人和宾客很可能会深陷印度婚礼无法抗拒的魅力中而无法自拔',NULL,10000000,85978266,17.592299,6.3,272,122,'2015-02-26','en','/gLdhUEOsDQNIQrALdbvBYKomICN.jpg',3.1073325946643346,3,'2026-09-10',2,NULL,NULL),(268917,'The Past Is a Grotesque Animal','The Past Is a Grotesque Animal','A personal, accessible look at an artist - Kevin Barnes, frontman of the endlessly versatile indie pop band of Montreal - whose pursuit to make transcendent music at all costs drives him to value art over human relationships. As he struggles with all of those around him, family and bandmates alike, he\'s forced to reconsider the future of the band, begging the question - is this really worth it?',NULL,100,0,0.394575,5.5,2,77,'2014-06-15','en','/wdvK5u5rP0KGMR8uIu2eSv3Z1zQ.jpg',2.072741082917399,3,'2026-09-10',2,NULL,NULL),(268920,'别惹德州','Hot Pursuit','性格暴躁、行为古板的女警库珀（瑞茜·威瑟斯彭 Reese Witherspoon 饰），被上司安排护送一位做了污点证人的毒枭妻子丹妮艾拉·里瓦（索菲娅·维加拉 Sofía Vergara 饰）横越德州，让她和丈夫去指证一个黑帮大佬。丹妮艾拉是一个身材火辣、脾气火爆的的哥伦比亚美女，两人明显相处不来。她们的行程还没开始，同行警察和里瓦先生就中了埋伏，让里瓦太太变成寡妇，这场从圣安东尼奥到达拉斯的旅程，转变成一场与时间和子弹赛跑的爆笑逃亡……','Armed and Sort-of Dangerous.',35000000,51680201,18.262017,5.4,647,87,'2015-05-08','en','/lobNOBHuJQCP9ZYAf86MBMwRrmZ.jpg',3.180721075392846,3,'2026-09-10',2,NULL,NULL),(269057,'砰砰宝宝','Bang Bang Baby','A small town teenager in the 1960s believes her dreams of becoming a famous singer will come true when her rock star idol gets stranded in town. But a leak in a nearby chemical plant that is believed to be causing mass mutations threatens to turn her dream into a nightmare.','Once upon a time, there was a girl...',1000000,0,0.973323,6.6,8,90,'2014-09-08','en','/5NLzhk3hQ6M6X1A27ZST5nNhUya.jpg',2.3147152943893436,3,'2026-09-10',2,NULL,NULL),(270303,'它在身后','It Follows','对19岁的洁来说，秋天本该充满学业、男孩和湖畔周末。然而一次看似寻常的性接触后，她发现自己被诡异幻象所扰，并笼罩在某种事物正尾随其后的不安感中。面对这一重负，洁与她的青少年朋友们必须设法逃脱那些似乎仅几步之遥的恐怖。','It doesn\'t think, it doesn\'t feel, it doesn\'t give up',2000000,14674076,100.876794,6.6,1832,100,'2015-02-04','en','/iwnQ1JH1wdWrGYkgWySptJ5284A.jpg',3.800405458423106,3,'2026-09-10',2,NULL,NULL),(270487,'凯撒万岁','Hail, Caesar!','大片厂的危机公关高手艾迪（乔什·布洛林），应付麻烦不断的《凯撒万岁：基督的一生》剧组。酗酒主演贝尔德（乔治·克鲁尼）遭人绑架。导演劳伦斯（拉尔夫·费恩斯）令女星（斯嘉丽·约翰逊）意外怀孕，八卦专栏作家（蒂尔达·斯文顿）虎视眈眈，鲜肉演员查宁·塔图姆和阿尔登·埃伦瑞奇也不是省油的灯。','Lights. Camera. Abduction.',22000000,63647656,39.006187,5.7,1309,106,'2016-02-05','en','/9CbHZLje0fXMTAmMrj5N8fdPvuW.jpg',3.401988635443622,3,'2026-09-10',2,NULL,NULL),(270554,'机器的逆袭','Echo Dr.','Mike一家原本是一个和睦的家庭。一天晚上家中报警系统失灵来了劫匪，幸好警察及时赶到控制住了劫匪。这也因此迎来了Mike家的新成员——机器人保镖“Dell”.可是Dell的种种举止使Jessica无法接受，直到有一天Dell有了新的意识……','To Serve & Terminate',0,0,0.053755,5,1,85,'2013-11-08','en','/4rGhxVIN0c1kLUNeh9Gw6CsGRRl.jpg',1.9839625769444955,3,'2026-09-10',2,NULL,NULL),(270938,'猎鹰突起','Falcon Rising','怀特扮演的退伍海军陆战队士兵查普曼，被描述为一位“黑暗的反英雄”，被罪恶感和创伤后应激障碍（PTSD）折磨。本片中，他的妹妹作为慈善组织成员前往巴西贫民窟工作，却遭残忍杀害，曝尸街头。查普曼遂飞往圣保罗，追踪杀害妹妹的凶手，控制贫民窟的日本黑帮海外势力，以孤胆英雄之姿，一人展开血战。',NULL,0,0,6.988357,5.5,71,103,'2014-09-05','en','/4wnfTO8mvqcTU62YMkUeKq49VMT.jpg',2.7620891074666254,3,'2026-09-10',2,NULL,NULL),(270946,'马达加斯加的企鹅','Penguins of Madagascar','为了给最疼爱的小老弟菜鸟（克里斯多夫·奈茨 Christopher Knights 配音）庆生，老大（汤姆·麦格拉思 Tom McGrath 配音）带领菜鸟以及好搭档科斯基（克里斯·米勒 Chris Miller 配音）、瑞哥闯入了防守最严密的美国黄金储备中心，只为找到金库尽头仅有的那台销售炸薯条的自动贩卖机。谁知他们刚刚完成任务没多久，便被长着触角的贩卖机吞了进去，随后被运到一个神秘的所在。在全封闭的设施内，四只企鹅见到了伪装成基因遗传科学家的章鱼戴夫（约翰·马尔科维奇 John Malkovich 配音）。原来戴夫曾是动物园一只明星章鱼，但随着萌态十足的企鹅们的到来，他便跌入了绝望的深谷。因此戴夫潜心研制了可怕的血清，发誓要向所有他曾待过的动物园中的企鹅展开报复。老大和伙伴们在逃亡途中得到北风特工队的救助，而他们和这些高傲的特工队员将分别阻止戴夫的阴谋……','The Movie Event That Will Blow Their Cover',132000000,373552094,84.366984,6.5,1346,92,'2014-11-22','en','/ybaPXeIQw4uAMkXaHMgx5eIxbR.jpg',3.6665851036251778,3,'2026-09-10',2,NULL,NULL),(271110,'美国队长3','Captain America: Civil War','美国队长史蒂夫·罗杰斯带领新组建的复仇者联盟继续维护世界和平，但一次行动造成的严重伤亡再次引发外界对超级英雄的质疑。为加强监管，联合国推动《索科维亚协议》，要求复仇者接受监督。史蒂夫担心因此失去行动自主权，而托尼·史塔克则认为复仇者必须为自己的行动承担责任。理念上的分歧令昔日并肩作战的伙伴逐渐分裂，而巴基·巴恩斯再次卷入事件，更让双方的矛盾不断升级……','Divided We Fall',250000000,1153304495,198.372395,7.1,7241,147,'2016-04-27','en','/rAGiXaUfPzY7CDEyNKUofk3Kw2e.jpg',4.485975648281232,3,'2026-09-10',2,NULL,NULL),(271185,'知无不言','Ask Me Anything','Katie Kampenfelt美丽、狂野、有趣、迷失，她在大学前休息了一年，寻找自己，同时在一个匿名博客中记录了自己的冒险经历，她在博客中倾诉了自己内心的秘密。最终，凯蒂无所畏惧的叙述开始破裂，她过去的黑暗片段浮出水面。','Young. Not so innocent.',950000,0,8.976128,5.5,155,100,'2014-04-19','en','/u0rEtOp6jI7oU6u3m7v1aAOJNQr.jpg',2.918602862435961,3,'2026-09-10',2,NULL,NULL),(271331,'激情联盟','United Passions','An epic, untold story that brings to life the inspiring saga of the World Cup and the three determined men who created it. Driven by their vision and passion, three men, overcame their doubts and fought obstacles and scandals to make the World Cup a reality. Spanning the tumultuous 20th Century, this timeless saga celebrates the event that became the most popular sporting event in the world.','Every dream has it\'s own rules',27000000,0,6.036684,3,16,110,'2014-06-19','en','/oQhVvz3N86DdHnYGsZ9Y2420II5.jpg',2.4427260881783885,3,'2026-09-10',2,NULL,NULL),(271718,'生活残骸','Trainwreck','女孩艾米（艾米·舒默 Amy Schumer 饰），从小被父亲教导婚姻不现实，一夫一妻不现实，长大后热衷泡吧，一直与不同男人约会却从不恋爱。一天，身为男性杂志编辑的她，前去采访一位专为运动员治疗运动损伤的医生亚伦（比尔·哈德尔 Bill Hader 饰），不料遇见了可能终结她完美单身生活的真命天子。 本片由女主角艾米·舒默编剧，根据她本人的真实经历改编。','We All Know One.',35000000,140795793,72.774941,5.9,1181,125,'2015-07-17','en','/wrY629UTCUAKLJ4CxQXz6DCE7pr.jpg',3.496873426097806,3,'2026-09-10',2,NULL,NULL),(271969,'宾虚','Ben-Hur','《宾虚：一个基督徒的故事》虚构了一个犹太王子——犹大·宾虚（Judah Ben-Hur），以一个类似《基督山伯爵》的故事为我们展现了他因与好友信念不同而遭到陷害、继而流放、被卖为奴、成为角斗士回乡复仇，最终成为一名耶稣信徒的曲折而传奇的一生。  　　新版《宾虚》由《刺客联盟》（Wanted）导演提莫·贝克曼贝托夫（Timur Bekmambetov）导演，剧本由《为奴十二年》的编剧约翰·雷德利（John Ridley）在基思·克拉克（Keith Clarke）初稿剧本基础上创作。','First to finish. Last to die.',100000000,94061311,29.608322,5.3,621,125,'2016-08-17','en','/rr4IbeHb59ZRQvgNmYC0rwFvyQ1.jpg',3.1861215776765865,3,'2026-09-10',2,NULL,NULL),(272693,'The DUFF','The DUFF','Bianca\'s universe turns upside down when she learns that her high school refers to her as a ‘DUFF\' (Designated Ugly Fat Friend). Hoping to erase that label, she enlists the help of a charming jock and her favorite teacher. Together they\'ll face the school\'s mean girl and remind everyone that we are all someone\'s DUFF… and that\'s totally fine.','You either know one, you have one, or you are one.',8500000,43528634,40.28709,6.8,1322,100,'2015-02-20','en','/jBh5lzkCdd50jeaRVSdA95RTeR.jpg',3.6195432486950025,3,'2026-09-10',2,NULL,NULL),(272724,'Doc Holliday\'s Revenge','Doc Holliday\'s Revenge','In 1882, Joseph and Elizabeth Cooley head West to reunite with family she never knew. But when she, Joseph, and her older brother, Millard, are stranded in a logging camp just outside Tucson a wounded Indian stumbles into their camp and they must defend him against Doc Holliday, his would-be killer. Elizabeth considers Doc a stone-cold killer -- but may find, during the course of their tense stand-off, that this courtly, ailing man has a surprisingly well-honed sense of justice, frontier-style...',NULL,1000000,0,0.4594,3.2,3,84,'2014-06-01','en','/lFN8h6gO3jMZikAErVVuPBcBrcu.jpg',2.1322778767701065,3,'2026-09-10',2,NULL,NULL),(272726,'Dude Where\'s My Dog?','Dude Where\'s My Dog?','Left home alone with his dog Harry, young Ray finds himself in a bit of trouble when Harry gets loose in the suspicious neighbor\'s house and accidentally knocks over a top-secret invisibility potion! Now, with crooks and the FBI on his tail, Ray needs to find his invisible mischievous mutt before they do - and get Harry back before his parents get home!',NULL,0,0,0.28397,0,0,0,'2014-06-12','en','/nUBGYq2qekustBm0Misdobk2FlJ.jpg',1.8344310286815255,3,'2026-09-10',2,NULL,NULL),(272878,'军犬麦克斯','Max','凯尔（罗比·阿梅尔 Robbie Amell 饰）是一名海军陆战队队员，忠心耿耿的军犬麦克斯是他的搭档和战友，两人穿梭在枪林弹雨之间，经历过许多生死攸关的危急时刻，结下了深厚的友谊。最终，凯尔死在了战场上，心碎的麦克斯竟患上了战后创伤应激症，无法作战也不肯认新主人的麦克斯只能离开了军队。凯尔的家人领养了麦克斯，凯尔的弟弟贾斯汀（乔什·维金斯 Josh Wiggins 饰）格外疼爱这是有故事的忠犬，在凯尔家人的温柔守护下，麦克斯的心理疾病渐渐康复，重新展现出了活力。就在一家人其乐融融之时，一位名为泰勒（卢克·克莱坦克 Luke Kleintank 饰）的男子出现在了麦克斯面前，声称自己是凯尔曾经的战友。','Best Friend. Hero. Marine.',20000000,43967255,14.136476,6.8,276,111,'2015-06-26','en','/hG9tVqvo599gLkC7zqyj98YTbve.jpg',3.1439777771193387,3,'2026-09-10',2,NULL,NULL),(273248,'八恶人','The Hateful Eight','寒冷的怀俄明州山谷中，一辆马车载着赏金猎人“绞刑者”约翰·鲁斯 及其价值一万美元的猎物黛西·多摩格 踏雪而行。途中，黑人赏金猎人马奎斯·沃伦少校 和新人警长克里斯·马尼克斯 相继登上马车，红石镇是他们共同的目标。由于风雪太大，马车停在了米妮男装店，然而熟悉的店主人不知去向，却另有四名不速之客百无聊赖地待在店里。约翰时刻担心他人抢走猎物，马奎斯警惕地扫视面前的陌生人们，多嘴多舌的克里斯不时为紧张的气氛中加油添醋，黛西则似乎等待更大的风暴到来。 仿佛与世隔绝的小店内，即将刮起一场更为猛烈的风暴……','No one comes up here without a damn good reason.',44000000,155760117,68.717016,7.6,4274,167,'2015-12-25','en','/jIywvdPjia2t3eKYbjVTcwBQlG8.jpg',4.18745513662495,3,'2026-09-10',2,NULL,NULL),(273481,'边境杀手','Sicario','在美国与墨西哥的边界有一块灰色地带，那里是毒贩和杀手们的天堂，他们在此交易火并，完全视法律为无物。凯特是联邦调查局的探员，心里怀揣着惩奸除恶的正义理想，她来到此地，加入了联邦政府特种部队，成为了马特的部下...','The border is just another line to cross.',30000000,84025816,55.424027,7.2,2416,121,'2015-09-17','en','/lz8vNyXeidqqOdJW9ZjnDAMb5Vr.jpg',3.9026670044735403,3,'2026-09-10',2,NULL,NULL),(273895,'塞尔玛','Selma','历史传记题材电影《塞尔玛》由阿娃·杜威内执导，蒂姆·罗斯、大卫·奥伊罗、小库珀·古丁、汤姆·威尔金森主演，影片聚焦美国民权斗士马丁·路德·金1965年组织的“由塞尔玛向蒙哥马利进军”行动。','One dream can change the world.',20000000,66787908,29.023184,7.4,817,127,'2014-12-25','en','/a15OMpRsHDIz3i3fQozt5veZU9L.jpg',3.560629699709706,3,'2026-09-10',2,NULL,NULL),(273899,'石墙','Stonewall','影片取材自真实历史事件，1969年的纽约“石墙酒吧暴动”。','Where Pride Began',13500000,187674,5.16023,5.2,32,129,'2015-09-18','en','/wiEx8UAZr6rgL559ILRQMDrYrYa.jpg',2.59330518090875,3,'2026-09-10',2,NULL,NULL),(274167,'老爸当家','Daddy\'s Home','性格温和的老爸布拉德（威尔·法瑞尔 Will Ferrell 饰），他的人生目标就是要成为继子女心目中最棒的父亲。当孩子们游手好闲的亲生父亲达斯蒂（马克·沃尔伯格 Mark Wahlberg 饰）登门造访之后，两位老爸为了争取孩子们的欢心开始明争暗斗，闹出不少笑话。','Choose your Daddy',50000000,242786137,38.616744,5.8,854,96,'2015-12-25','en','/6s4TgdPWFBTo3CLnQXfdtAkMxTl.jpg',3.337361564510368,3,'2026-09-10',2,NULL,NULL),(274479,'奋斗的乔伊','Joy','上世纪八十年代一名居住在长岛的单身母亲乔伊通过自身努力，贩卖神奇拖把发家致富，最终成为一代拖把女王……',NULL,60000000,101134059,29.876507,6.4,1581,124,'2015-12-24','en','/tpsoPY5E6yITGusEPoEcoahIXzp.jpg',3.560652679748846,3,'2026-09-10',2,NULL,NULL),(274758,'Give Me Shelter','Give Me Shelter','Give Me Shelter is a documentary to raise awareness for important animal issues around the world. This film uncovers the most prevalent issues in the animal world through the eyes of individuals dedicating their lives to them daily.',NULL,0,0,0.278981,0,0,90,'2014-06-24','en',NULL,1.8344196328237758,3,'2026-09-10',2,NULL,NULL),(274854,'最后的巫师猎人','The Last Witch Hunter','作为世界上最后一个女巫猎人，寇特（范·迪塞尔 Vin Diesel 饰）被黑巫后诅咒，得到了不死之身。如今，寇特寄居在纽约的一所教堂，与教会派来的第37代助手多兰（伊利亚·伍德 Elijah Wood 饰）联手斩妖除魔。与此同时，黑巫后得到秘术即将复活，邪恶女巫们倾巢而出 ，企图释放超级瘟疫灭绝人类。势单力薄的寇特，求助于善良的梦之女巫克洛伊（露丝·莱斯利 Rose Leslie 饰），在她的帮助下，寇特与邪恶女巫之间的终极之战一触即发。','Hunt forever.',90000000,146936910,52.612025,5.7,1316,106,'2015-10-21','en','/m8hN5GaDM1764ZZdazOFTy4MUqM.jpg',3.4340727595508787,3,'2026-09-10',2,NULL,NULL),(276907,'传奇','Legend','汤姆·哈迪一人分饰两角出演伦敦黑帮史上最叱咤风云的克雷兄弟，雷金纳德 和罗纳德。他们统治了上世纪五六十年代整个伦敦的东区，从持械抢劫到暴力袭击，从收保护费到走私军火，谋杀，可以说是无恶不作。黑白两道通吃的他们在商界、政界、娱乐界都广受欢迎。兄弟中的弟弟自称是双性恋，与许多政客有染……警方在1968年将两兄弟捉拿归案，最终判处终身监禁，结束了他们罪恶的黄金时代……','Love, fight, live, rule like a legend.',25000000,42972994,32.854557,6.7,973,131,'2015-09-09','en','/oT1L8vxBEgsWWMWQadyirKY9o6i.jpg',3.503882016236301,3,'2026-09-10',2,NULL,NULL),(277216,'冲出康普顿','Straight Outta Compton','In 1987, five young men, using brutally honest rhymes and hardcore beats, put their frustration and anger about life in the most dangerous place in America into the most powerful weapon they had: their music.  Taking us back to where it all began, Straight Outta Compton tells the true story of how these cultural rebels—armed only with their lyrics, swagger, bravado and raw talent—stood up to the authorities that meant to keep them down and formed the world’s most dangerous group, N.W.A.  And as they spoke the truth that no one had before and exposed life in the hood, their voice ignited a social revolution that is still reverberating today.','The Story of N.W.A.',28000000,201634991,61.76233,7.7,1355,147,'2015-08-13','en','/1CiLJx8Xtv3TbbFj6k7BboSmKgC.jpg',3.850707055197146,3,'2026-09-10',2,NULL,NULL),(277519,'反贪风暴','Z 風暴','商业犯罪搜查科警司黄文彬（林家栋 饰）的妻子前往廉政公署举报丈夫巨额先进来路不明，廉记首席调查主任陆志廉（古天乐 饰）奉命传唤黄到署问话，然而对手老奸巨猾，深谙暗箱一切套路，最终平安脱险。此前不久，黄曾调查素有香港会计界教父之称的罗德永（卢海鹏 饰）未果，视频中二人的反常举止引起陆的怀疑。与此同时，身份难辨的Z基金在道貌岸然的律师胡志勇（王敏德 饰）的推动下即将上市，该基金打着扶贫旗号，有望吸引港府150亿的专项关怀基金投入其中。陆敏感察觉其中的蹊跷，他和同事利用有限的时间展开全面调查。金钱巨大的诱惑之下，贪婪之徒铤而走险，更不惜为此杀人嗜血。狂扫污秽的Z风暴即将到来，黑云压城城欲摧……',NULL,0,0,0.542814,5.8,5,92,'2014-06-19','cn','/y3pIY3AR0jndDeTB2NpLt6dZx98.jpg',2.223458563756503,3,'2026-09-10',2,NULL,NULL),(277685,'解除好友','Unfriended','2013年，某所高中名叫劳拉·巴恩斯（Heather Sossaman 饰）的女孩自杀，一度引起轰动。劳拉自杀一年后的某个夜晚，她的同学布莱尔·莉莉（雪莱·亨尼格 Shelley Hennig 饰）正与男朋友米奇•卢塞尔（Moses Storm 饰）在网络上调情，这时朋 友圈的亚当·休厄尔（Will Peltz 饰）、肯（Jacob Wysocki 饰）、洁丝（Renee Olstead 饰）等人加入进来，少男少女嬉笑调侃，好不热闹。可是一同加入讨论的还有一个没有头像的神秘用户，他无法被踢出和挂断，更令几人震惊的是对方居然以劳拉的身份和他们说话。起初布莱尔等人认为这是某个黑客的恶作剧，谁知之前曾诅咒过劳拉的另一位辣妹瓦尔（Courtney Halverson 饰）暴走继而惨遭意外。 在鬼魂的逼迫下，布莱尔等人不为人知的黑色秘密浮出水面。。。','Online, your memories last forever. But so do your mistakes.',1000000,62882090,41.972329,5.5,1047,82,'2015-04-17','en','/pDOA60PxLEIsz0km8ZMuV7QO134.jpg',3.331456641350105,3,'2026-09-10',2,NULL,NULL),(278316,'耶稣哒圣血','Da Sweet Blood of Jesus','本片讲述了一群嗜血人类的故事。',NULL,0,0,4.480579,4.1,13,123,'2014-06-22','en','/dUqIwSKX9cEkahmv1lsolT8ouE9.jpg',2.4064944025865462,3,'2026-09-10',2,NULL,NULL),(278348,'The Maid\'s Room','The Maid\'s Room','Drina, a young immigrant working as a live-in maid for a wealthy Long Island family, finds herself entangled in the family\'s web of dark secrets once she begins to suspect her employer\'s son has committed a terrible crime.','How far will a family go to bury the truth?',0,0,1.501688,4.8,4,98,'2014-08-08','en','/jKqWJh3w88vxUwy0obaanuOej4L.jpg',2.184546986484745,3,'2026-09-10',2,NULL,NULL),(278927,'奇幻森林','The Jungle Book','毛克利（尼尔·塞西 Neel Sethi 饰）是一个由狼群养大的人类男孩，影片围绕他的森林冒险徐徐展开。谢利·可汗，一只受过人类伤害的老虎（伊德里斯·艾尔巴 Idris Elba 配音），发誓要将毛克利铲除。为了逃脱追捕，毛克利跟随严厉的导师黑豹巴希拉（本·金斯利 Ben Kingsley 配音）和自由自在的好友棕熊巴鲁（比尔·默瑞 Bill Murray 配音），踏上了一场精彩纷呈的自我探索旅程。在这趟旅途中，毛克利遇到了一些对他居心叵测的丛林生物，包括巨蟒卡奥（斯嘉丽·约翰逊 Scarlett Johansson 配音），她用迷人的声音和眼神迷惑毛克利；还有花言巧语的猩猩路易王（克里斯托弗·沃肯 Christopher Walken 配音），他试图通过威逼利诱让毛克利交出迷幻而致命的“红花”——火焰的秘密。当森林不再是安全的家园，毛克利该何去何从？而毕生难忘的伟大冒险，才刚刚拉开序幕……',NULL,175000000,966550600,94.199316,6.7,2892,106,'2016-04-07','en','/2Epx7F9X7DrFptn4seqn4mzBVks.jpg',3.920389017755047,3,'2026-09-10',2,NULL,NULL),(279759,'Harrison Montgomery','Harrison Montgomery','Film from Daniel Davila',NULL,0,0,0.006943,0,0,0,'2008-01-01','en','/nx5gAaeFDw7WkybkuKLVwLBGXmw.jpg',1.8337982444993643,3,'2026-09-10',2,NULL,NULL),(280092,'潜伏3','Insidious: Chapter 3','灵媒伊莉丝不情愿地帮一名少女联系她去世的母亲，结果意外释放出了一个恶魔，让这名少女饱受折磨。','This is how you die',10000000,104303851,45.946524,6.2,983,97,'2015-06-04','en','/5ZicXx5Q1MQBvgXYSPFfDVwi0DS.jpg',3.450289536027539,3,'2026-09-10',2,NULL,NULL),(280381,'House at the End of the Drive','House at the End of the Drive','When David King purchases a house in the hills far above the angst of Los Angeles, he gets much more than he bargained for when strange and unexplainable occurrences in and around the house begin to take control of his daily life','It\'s where they died.',0,0,0.43049,0,0,91,'2014-01-11','en','/AmW0Rz1McoXMYPxl5WoootpiJsz.jpg',1.8347657091941478,3,'2026-09-10',2,NULL,NULL),(280391,'疯狂进化人','Pourquoi j\'ai pas mangé mon père','故事发生在遥远的远古时代，主人公爱德华是元族首领西梅恩的长子，却因为身材瘦弱且外形异于同族被视为异类，加之族中女巫的谗言，刚刚出生即被抛弃。爱德华大难不死，与不会讲话的伊安一起在丛林中不断发现新事物。当然阴错阳差重返猿族部落后，掀起了一场改变猿组命运的大波澜。','These feet are made for walkin\'',0,0,5.794466,5.3,125,100,'2015-04-08','fr','/lInt3XAVl4BWstRtlinVPBWGXjX.jpg',2.861497108756078,3,'2026-09-10',2,NULL,NULL),(280871,'天才','ராமானுஜன்','《拉马努金》是一部以20世纪早期英属印度和英国为背景的历史传记片，围绕着数学天才斯里尼瓦萨·拉马努金的生活和时代展开。拉马努金被认为是数学史上最浪漫的故事之一，他是南印度一个贫穷家庭的辍学生，在独立的情况下做出了非凡的数学发现。他给剑桥大学三一学院的哈代教授写了一封充满定理和公式的奇怪的信，哈代教授立即发现了他的才华，并邀请他到英国进行进一步的研究。《拉马努金》记录了这位天才跨越大陆和文化寻求认可的旅程。',NULL,0,0,0.416179,5,3,170,'2014-07-11','ta',NULL,2.1343939897830024,3,'2026-09-10',2,NULL,NULL),(281189,'Gory Gory Hallelujah','Gory Gory Hallelujah','Four actors compete for the role of Jesus - a black revolutionary, a bisexual hippie, a Jew, and a feminist. When all four are rejected, they hit the road on bad-ass motorcycles, bound for glory in New York City. But when a run-in with a gang of Elvises ends in murder, they find themselves taken prisoner in a little town called Jackville - where folk don\'t take kindly to blasphemers. The Jesuses fall prey to an evil conspiracy that can only lead to the Apocalypse.',NULL,0,0,0.033883,1,1,0,'2003-11-05','en','/6YZqVQYZ1vTVpnXioFHPny5g81E.jpg',1.9822720660743498,3,'2026-09-10',2,NULL,NULL),(281230,'Fort McCoy','Fort McCoy','Unable to serve in World War II because of a heart condition, a barber moves his family adjacent to a Wisconsin army base and prisoner-of-war camp to provide his services. But even in rural America -- far from the frontline -- the war finds victims.',NULL,0,0,0.384496,6.3,2,0,'2014-01-01','en','/4ok9jMdmjQUKtuTNwX0w0My9wib.jpg',2.0733752073185907,3,'2026-09-10',2,NULL,NULL),(281730,'Fugly','Fugly','It is a story of 4 friends - Dev, Gaurav, Aditya &amp; Devi. The cast is young &amp; fresh. They are at the cusp of their lives - The college has just about finished, but career path is yet to be set. These are the last few days of true freedom that we have all gone through, and still cherish. These friends are conscientious, they will have fun but would never cross the boundaries - They all have dreams and expectations from life, but as they say - man proposes, god disposes. Their fun filled and care free life comes to an abrupt halt, when they are faced with an extremely corrupt and seemingly fearless Police Officer. This puts a series of events in motion which will test their friendship and characters - their life becomes \'Fugly\'.',NULL,0,0,0.371337,5.3,2,134,'2014-06-13','en','/gK1d772yMqHjvBpMRVz1XWN5OTU.jpg',2.0725237160474173,3,'2026-09-10',2,NULL,NULL),(281957,'荒野猎人','The Revenant','故事讲述19世纪一个皮草猎人被一头熊所伤，他乘的船的船长试图把他带回文明世界，但形势所迫，他无法做到，于是只好雇了两个人留下，目的是让他们送这个猎人最后一程。但这两个人利欲熏心，他们把这个受伤的可怜人洗劫一空，之后把他一个人抛弃在荒凉冰冷的野外等死。然而猎人奇迹般的活了下来，之后开始寻找这两个人开始复仇…','(n. One who has returned, as if from the dead.)',135000000,532950503,100.635882,7.3,6396,156,'2015-12-25','en','/ji3ecJphATlVgWNY0B0RVXZizdf.jpg',4.2864392135826,3,'2026-09-10',2,NULL,NULL),(282128,'An American in Hollywood','An American in Hollywood','A talented young filmmaker from New York sets off to Los Angeles in pursuit of the Hollywood dream, only to discover through his relationship with a beautiful feisty young actress, that Hollywood is not all that it seems.',NULL,0,0,0.015697,0,0,89,'2014-07-18','en','/rsWhg2RPqraO0EEdXuRQr43G60K.jpg',1.8338182403580015,3,'2026-09-10',2,NULL,NULL),(283384,'召唤','The Calling','白雪纷飞的某个小镇，女警察海泽尔（苏珊·萨兰登 Susan Sarandon 饰）按照长官指示前往一位相熟的的老人家探望，谁知却发现老人被残忍割喉，死状凄惨。然而这仅仅是一个开始，两天后另一名农场主死在自家马厩，他的胃更被摘除后丢弃在荒野，任野狗蚕食。虽然两起案件距离颇远，且没有什么共同之处，但海泽尔坚信这是同一人所为。根据一系列针对老年人的谋杀案死者照片比对，海泽尔和同事发现他们的嘴被凶手刻意弄出了正在讲述什么的样子。经人介绍，海泽尔找到精通拉丁语的普莱斯神父（唐纳德·萨瑟兰 Donald Sutherland 饰），进而得知这一系列案件和天主教被禁止的祷词有关，其中语言会有12名信徒牺牲自己以换取某人的复活。','Pray for the Prey',0,0,5.759493,5.6,88,108,'2014-08-05','en','/kqJGIh2mZVwTD20GeDVTUNOwd5p.jpg',2.805057571507197,3,'2026-09-10',2,NULL,NULL),(283445,'险恶2','Sinister 2','曾经发生过灭门惨案的凶宅，而今又迎来了新的主人。单亲妈妈考特尼（莎妮·索萨蒙 Shannyn Sossamon 饰）在摆脱了失败的婚姻后，带着双胞胎儿子迪伦（罗伯特·丹尼尔·斯隆 Robert Daniel Sloan 饰）和扎克（达塔尼安·斯隆 Dartanian Sloan 饰）搬进了这里。考特尼为了生计疲于奔波，而迪安似乎又收到某种神秘的力量所影响。他能看见穿戴整洁却一脸阴气的朋友米洛，更在对方的指引下看了那卷凶残可怖的录像带。在此期间，一名前警官以私人侦探（詹姆斯· 兰索恩 James Ransone 饰）的身份入住母子的家中，他曾持续追查这栋凶宅幕后的真相。迪安似乎越陷越深，恐怖邪恶的力量牵扯着这一家人沉向死亡的泥潭……','Be careful, children at play.',10000000,52882018,26.090495,5.4,581,97,'2015-08-19','en','/uku6FuIlj0qczJexNSzHYgGYvIN.jpg',3.1809835206179278,3,'2026-09-10',2,NULL,NULL),(283671,'熊熊大冒险','Jungle Shuffle','在墨西哥的原始森林里，Sacha（艾丽西亚·希尔维斯通配音）和Manu（德雷克·贝尔配音）是一对十分要好的朋友，他们每天在丛林里奔跑嬉戏，活的自由自在，仿佛世间从未有过任何纷扰。生性活泼好动的Manu对一切充满了好奇，这天，他不小心弄坏了一尊雕像，这尊雕像原本是供奉给森林之神的，闯下大祸的Manu就这样遭到了驱逐，被逐出森林的Manu再也不能与Sacha在一起了。这天，没有Manu陪伴的Sacha被狩猎者捉住，为了救出Sacha，也为了保护同伴赖以生存的森林，Manu开始了自己的作战计划！',NULL,0,0,1.413934,6.5,1,85,'2014-08-07','en','/crcj3IEAUtzIySVjw3HN2tS910S.jpg',1.9876864131822676,3,'2026-09-10',2,NULL,NULL),(283686,'走出黑暗','Out of the Dark','萨拉·哈里曼（朱丽娅·斯蒂尔斯 Julia Stiles 饰）的父亲乔丹（斯蒂芬•瑞 Stephen Rea 饰）在南美某国家经营一家大型造纸厂，某天她带着身为绘本画家的丈夫保罗（斯科特·斯比德曼 Scott Speedman 饰）以及乖巧可爱的女儿汉娜（Pixie Davies 饰）来到圣达克拉拉度假，当然与此同时也要接任纸厂经理的职务。乔丹热情地接待了女儿一家，并把他们安排在一处装潢考究、宽大舒适的庭园别墅内居住。只不过快乐之余，噩梦正悄悄向这一家逼近。',NULL,0,0,3.215465,4.6,55,92,'2014-08-27','en','/Lql2rnNRmKJrjq4FhEUh7IwkNd.jpg',2.683363783890342,3,'2026-09-10',2,NULL,NULL),(283708,'远离人迹','Loin des hommes','1954年，当叛乱的力量在山谷里滋长，两个男人不顾一切地在阿尔及利亚山脉间逃亡。严酷的冬天里，独居的老师Daru必须将被指控谋杀的男孩Mohanmed送去给法国当局。被复仇的骑兵和居民盯上，两人不得不争取赢回自由。电影灵感来自1957年加缪出版的《流放与王国》里的短篇小说《来客》。（via one world films，翻译by上校）',NULL,7700000,0,3.363973,6.6,43,110,'2014-08-30','fr','/efhEOjjqLhnmBsLiS6Ep69hMAzy.jpg',2.6713429589420277,3,'2026-09-10',2,NULL,NULL),(284293,'依然爱丽丝','Still Alice','改编自同名小说《我想念我自己》内容简介：爱丽丝·豪兰是一位事业有成、家庭幸福的成功女性。她是哈佛大学认知心理学教授、知名的语言学家，丈夫也是哈佛教授，三个孩子都已长大并各有自己的追求。五十岁那年，爱丽丝发现自己的记忆力越来越差，有一天，她还突然在自己最熟悉的地方迷了路。医生的诊断彻底改变了她的生命，也改变了她与家人和世界的关系。她患的是阿尔兹海默病，她的记忆跟不上遗忘的脚步，她逐渐失去了自己的思想，也失去了与外在世界的连结。她渐渐记不起女儿的名字、想不起丈夫的面孔，她眼中世界的模样也在不断改变。但是，在家人的浓浓爱意陪伴下，她勇敢地为每一天而活，为当下而活。她能够体会到生活中的美好与爱。她还是爱丽丝·豪兰，一个坚强的女人。',NULL,5000000,43884652,35.307577,7.5,1104,99,'2014-12-05','en','/4GPV1FjOzHGwP53wiHzq9pwdmP2.jpg',3.6868751638710826,3,'2026-09-10',2,NULL,NULL),(284296,'Top Five','Top Five','A comedian tries to make it as a serious actor when his reality-TV star fiancé talks him into broadcasting their wedding on her TV show.',NULL,0,25434291,15.896312,6.3,210,102,'2014-12-12','en','/d0zPiFZEI0P1JWwS3pbwPmppdgB.jpg',3.0448141787074245,3,'2026-09-10',2,NULL,NULL),(284536,'赌徒','The Gambler','沃尔伯格饰演的吉姆·本内特（Jim Bennett）既是大学英语文学教授，又是一个大手笔的赌徒。他让学生打假球，使自己在赌局中牟利。随着赌瘾日渐加深，他的生活陷入万劫不复之中。由于债台高筑，他不得不已自己的生命为代价，向一位高利贷大佬弗兰克借债。','The only way out is all in',25000000,39171130,22.622453,5.7,543,111,'2014-12-25','en','/wdCkeWZsz5GYcEcUBmxIdLsIPpD.jpg',3.2003912303882878,3,'2026-09-10',2,NULL,NULL),(285743,'Alleluia! The Devil\'s Carnival','Alleluia! The Devil\'s Carnival','The Devil\'s Carnival: Alleluia! is the second episode of The Devil\'s Carnival. The episode will revolve around the war between Hell and Heaven.','Hell ain\'t got a prayer.',0,0,0.674398,6,2,0,'2016-03-29','en','/naDJqNmD2WuWOBBmH7THxHh0aE4.jpg',2.073790970476619,3,'2026-09-10',2,NULL,NULL),(285783,'云中行走','The Walk','本片根据法国杂技艺术家菲利普·帕特的个人自传改编，翻拍自2009年奥斯卡最佳纪录长片《走钢丝的人》，真实还原了1974年8月7日的惊世壮举。从小就拥有杂技表演天赋的菲利普·帕特（约瑟夫·高登-莱维特 Joseph Gordon-Levitt 饰）在街头卖艺时，邂逅美丽的街头音乐女孩安妮（夏洛特·莱本 Charlotte Le Bon 饰）。偶然的机会，菲利普得知纽约世贸双子大厦即将竣工。从此，菲利普就萌生了在这两座摩天大厦间走钢索的的想法。然而这疯狂的“艺术犯罪”却遭到了一系列的质疑和误解，但这并没有击垮菲利普的坚定信念，他深入调查缜密部署，先后得到走钢丝经验丰富的鲁迪爸爸（本·金斯利 Ben Kingsley 饰）的执导，以及让-路易（克雷蒙·史鲍尼 Clement Sibony 饰）和杰夫（塞萨·多姆波伊 César Domboy 饰）等人的帮助。在110层412米的云中，菲利普开始了他的钢丝行走。','Dream High.',35000000,61181942,37.335721,6.9,1121,123,'2015-09-30','en','/7cjNZY6GiDQvkKrvcUToE6a3E8T.jpg',3.587240139029604,3,'2026-09-10',2,NULL,NULL),(285923,'刑房','Grindhouse','本片由两部电影组成，分别为昆汀·塔伦蒂诺（Quentin Tarantino）所拍的《死亡证据》，以及罗伯特·罗德里格兹（Robert Rodriguez）所拍的《恐怖星球》。《死亡证据》讲述了一个变态杀手麦克（库尔特·拉塞尔 Kurt Russell 饰）用他的爱车谋杀四个美女的故事。他出没于公路边的酒吧，寻找猎物取得信任，然后在公路上通过车祸的方式残忍的杀害她们，同时自己也身负重伤，这就是他满足自己嗜血欲望的方式。这一次，他又盯上了四个目标，但这一次，他的直觉失灵了，这个恶贯满盈的杀人魔王终于遇到了他生命中最后的克星。在《恐怖星球》里，小镇被嗜血的丧失包围，一种奇怪的病毒迅速传染开来。切瑞（罗丝·麦高恩 Rose McGowan 饰）是一个脱衣舞女郎，她遭到丧失的袭击失去了右腿。男友在她的残肢上装上了一挺机关枪，为了生存，也为了保护所爱的人，切瑞必须成为英雄。','A double feature that\'ll tear you in two!',67000000,25037897,16.637642,6.8,459,191,'2007-04-06','en','/tvMBwJlmQTIQf5EBjHzzyE9tjcN.jpg',3.2828781579110036,3,'2026-09-10',2,NULL,NULL),(286217,'火星救援','The Martian','载人航天宇宙飞船阿瑞斯3号成功抵达火星，谁知一场破坏力极其巨大的风暴向宇航员们袭来，阿瑞斯3号被迫中断任务，紧急返航。撤离途中，宇航员马克·沃特尼被飞船上吹落的零件击中，由于生还希望渺茫，队友们只得匆匆返航，并向世人宣告他已牺牲的事实。出乎意料的是，马克以极低的概率活了下来。他躲进驻火星的航天基地疗伤。下一次火星任务要等到四年后，而基地内的补给仅够他维持31天。短暂的绝望后，马克决定利用有限的食物，在这颗空无一人的星球上种植作物，寻找一线生机。与此同时，地球方面也很快发现马克生还的事实，他们想尽办法部署营救计划。孤军奋战的马克，能否等到救援队伍的到来？','Bring Him Home',108000000,630161890,167.93287,7.6,7268,141,'2015-09-30','en','/fASz8A0yFE3QB6LgGoOfwvFSseV.jpg',4.5536811104173704,3,'2026-09-10',2,NULL,NULL),(286565,'纸镇','Paper Towns','昆汀（纳特·沃尔夫 Nat Wolff 饰）从小就单恋勇敢漂亮的邻居玛戈（卡拉·迪瓦伊 Cara Delevingne 饰），但两人多年的校园生活却是天差地别，没机会好好交流。一天夜里，玛戈突然潜入昆汀的房间，要求他协助报复她的花心男友，昆汀也乖乖答应。  　　通宵冒险结束后 ，玛戈离奇失踪，她的家人和警察都认为这是她的一个小玩笑，只有昆汀察觉出其中异样。根据玛戈昨夜的反常举动与她刻意留下的蛛丝马迹，昆汀与他的朋友开始了寻找玛戈的旅程。一张惠特曼的诗歌残片、一段网站上的留言，线索零碎又环环相扣。昆汀发现他越接近目的地，越对自己的发小感到陌生……  　　“你将前往纸上城市，永远不会回来。”玛戈留下的文字，引领昆汀逐步走进那座由现实与虚构交杂而成的纸上城市。','Get Lost. Get Found.',12000000,85512300,64.610671,6.1,1937,109,'2015-06-18','en','/1hXXs7Bw7RuS39jAl0vatTaULMC.jpg',3.6222940540535746,3,'2026-09-10',2,NULL,NULL),(286939,'Sanctuary: Quite a Conundrum','Sanctuary: Quite a Conundrum','It should have been just a normal day of sex, fun, alcohol, hormones and debauchery for Tabitha and Mimi, two over-privileged twenty-somethings. But that so-called normalcy gets tossed out the window when a devastating event occurs at a pool party.',NULL,0,0,0.166513,0,0,82,'2012-01-20','en','/xwMvze2e4lFjxT90lrCTuE0hFeO.jpg',1.8341627337800028,3,'2026-09-10',2,NULL,NULL),(287424,'玛姬','Maggie','近未来，可怕的丧尸病毒蔓延全球，数以万计的平民遭受感染，许多人失去了生命，许多人化身为嗜血如命的活死人，也有许多人从此得到尴尬的身份。农夫韦德（阿诺·施瓦辛格 Arnold Schwarzenegger 饰）忧心忡忡地开车驶向位于隔离区的医院，他的女儿麦琪（阿比盖尔·布蕾斯琳 Abigail Breslin 饰）不久前被送到这里。麦琪遭到了丧尸的攻击，从而感染病毒。虽然离完全变成丧尸还有一段时间，但是她的悲剧命运似乎就此注定。韦德取得院方的同意，带女儿回到了家中。熟悉的环境和气息，对麦琪来说却平添了几多忧伤与烦恼。她与家人的维系不断，然而那距离正一点点地来开。  　　时间流逝，麦琪身上生的气息不断消逝，死亡的味道与日俱增，她和彼此深爱的亲人终将迎来痛苦的诀别时刻……','Don\'t Get Bitten',4000000,187112,40.016306,5.2,593,95,'2015-05-08','en','/yQT8LDs2t1n7ZNDOi83JgeFphKi.jpg',3.1892191978351856,3,'2026-09-10',2,NULL,NULL),(287524,'恐影档案','Fear Clinic','A doctor works to cure patients suffering from crippling phobias by placing them inside his invention which induces and controls hallucinations.',NULL,1,0,1.859965,4,42,95,'2014-10-31','en','/sYLfCI8dzueqGUfSsrOarR2JZKQ.jpg',2.620214502325153,3,'2026-09-10',2,NULL,NULL),(287625,'Stories of Our Lives','Stories of Our Lives','Created by the members of a Nairobi-based arts collective — who have removed their names from the film for fear of reprisal — this anthology film that dramatizes true-life stories from Kenya’s oppressed LGBTQ community is both a labour of love and a bold act of militancy.',NULL,0,0,0.327794,0,0,60,'2014-09-05','en','/uHa34QtV3B5zDMUozKEdkkQJy2G.jpg',1.8345311313213368,3,'2026-09-10',2,NULL,NULL),(287815,'Call + Response','Call + Response','Call + Response is a first of its kind feature documentary film that reveals the world’s 27 million dirtiest secrets: there are more slaves today than ever before in human history. Call + Response goes deep undercover where slavery is thriving from the child brothels of Cambodia to the slave brick kilns of rural India to reveal that in 2007, Slave Traders made more money than Google, Nike and Starbucks combined. Luminaries on the issue and many other prominent political and cultural figures offer first hand account of this 21st century trade. Performances from Grammy-winning and critically acclaimed artists move this chilling information into inspiration for stopping it. Music is part of the movement against human slavery. Dr. Cornel West connects the music of the American slave fields to the popular music we listen to today, and offers this connection as a rallying cry for the modern abolitionist movement currently brewing.','A FILM ABOUT THE WORLD\'S 27 MILLION MOST TERRIFYING SECRETS.',0,0,0.062089,8,1,86,'2008-10-10','en',NULL,1.9852154529242416,3,'2026-09-10',2,NULL,NULL),(287903,'克朗普斯','Krampus','这部名为《克朗普斯》（Krampus）的影片其灵感来自德国民间传说，将在2015年11月25日上映。  在德国民间故事里，“克朗普斯”（Krampus）是一个可怕的魔鬼，他专门在圣诞节惩罚那些不听话的小孩。','You don\'t want to be on his list.',15000000,61548707,31.565117,5.9,584,98,'2015-11-26','en','/iQXlmoHsCmlyD8maD5eYnmleypm.jpg',3.2610796273212213,3,'2026-09-10',2,NULL,NULL),(287948,'The Transporter Refueled','The Transporter Refueled','The fast-paced action movie is again set in the criminal underworld in France, where Frank Martin is known as The Transporter, because he is the best driver and mercenary money can buy. In this installment, he meets Anna and they attempt to take down a group of ruthless Russian human traffickers who also have kidnapped Frank’s father.','He Delivers.',25000000,72629670,25.002715,5.2,559,96,'2015-09-03','en','/997UAQAv4PsJ1ont51jO88cxzpT.jpg',3.146111690966993,3,'2026-09-10',2,NULL,NULL),(288927,'Archaeology of a Woman','Archaeology of a Woman','A woman\'s dementia uncovers secrets of a 30-year-old crime as her daughter struggles to deal with the fallout',NULL,0,0,0.254659,0,0,94,'2014-09-12','en','/wncmCHqnGaqCpWgN8nIOxJC1m9y.jpg',1.8343640765896234,3,'2026-09-10',2,NULL,NULL),(288980,'自由之路','Freedom','100岁的男人在寻找自由的追寻中被团结起来。1856个奴隶，塞缪尔和他的家人，逃离里士满附近的梦露林，弗吉尼亚。被称为“地下铁路”的普通百姓的一个秘密网络，在他们向北加拿大的旅程中引导着他们的家人。他们是由臭名昭著的奴隶猎人Plimpton不懈追求。猎杀像狗，被他和他的祖先所经历的难以想象的痛苦，塞缪尔被迫决定报复或自由之间。1748年前的100年，牛顿的一个奴隶贩子从非洲航行，带着奴隶的货物，开往美国。在船上，塞缪尔的曾祖父，他的生存与牛顿船长的命运联系在一起。这一航程改变了牛顿的一生，他创造了一个能激励塞缪尔和千百万人的生命的遗产。','John Newton\'s Amazing Grace',14500000,0,4.389363,5.8,9,98,'2014-08-21','en','/j94GeQu4CBSmvaxzmsRRGvRGvsT.jpg',2.3426639831052243,3,'2026-09-10',2,NULL,NULL),(289180,'H.','H.','H. is a modern interpretation of a classic Greek tragedy in which two women, each named Helen, live out their mirrored lives of one another in the town of Troy, NY.  The first Helen is in her 60s, lives with her husband Roy, and takes care of a small, extremely lifelike baby doll called a “Reborn Doll,” which she cares for as a living baby.  The second Helen is in her 30s, has a successful art career with her partner Alex, and is four months pregnant.  One night, something falls out of the sky and explodes over the town. In the aftermath of this event, bizarre and unexplainable things begin to happen.  Many people in the town go missing—Helen’s husband being one of them—and unnatural cloud formations begin appearing in the sky.  Meanwhile, the two Helens find themselves, and their lives spinning out of control.',NULL,0,0,1.045623,6.5,4,93,'2014-08-28','en','/zxRz4wFGXtsgcoVQ4wGSNO3PCtD.jpg',2.186290491947012,3,'2026-09-10',2,NULL,NULL),(290370,'Mutant World','Mutant World','A decade after a disastrous meteor impact wipes out most of society, a group of survivalists emerge to find themselves on a twisted version of the old Earth, with a nascent society besieged by vicious marauders, ferocious mutants, and the dreadful symptoms of a post-apocalyptic environment.',NULL,0,1500000,1.893697,2.6,9,85,'2014-09-27','en','/qW10Tx8IQsDZRr7seAz2Ld8YRLy.jpg',2.325247030550248,3,'2026-09-10',2,NULL,NULL),(290391,'Run, Hide, Die','Run, Hide, Die','On the anniversary weekend of the death of a young women\'s husband, five girls head out to a cabin to help their friend move past her husband\'s death. As the party continues a dark secret begins to unravel and a hideous past crawls out to seek revenge.','Five girls, one secret. Revenge stalks them in the night.',50000,0,0.595809,3.5,2,75,'2015-09-01','en','/zVSkZFH9zuU3oeRs3vgrJ41xkv5.jpg',2.071557873921381,3,'2026-09-10',2,NULL,NULL),(290555,'狼人镇','Wolves','影片讲述了18岁的高中橄榄球队队长卡登一天醒来，发现变成了一个狼人，并无意识中杀害了自己的父母，于是他逃到一个狼人聚居的小镇，那里由狼人康纳用野蛮的方式统治着，而农夫约翰则保护着人类的权益。在那里，卡登爱上了本应嫁给康纳的女孩安吉丽娜，一场决斗不可避免，而卡登也发现了自己的潜力，想对这个小镇做出改变……','Unleash the beast',18000000,0,7.922639,5.7,82,90,'2014-08-28','en','/xcuXfRZYan6xQq4e1MLC1hMhTPK.jpg',2.7988938963211,3,'2026-09-10',2,NULL,NULL),(290595,'The Huntsman: Winter\'s War','The Huntsman: Winter\'s War','As two evil sisters prepare to conquer the land, two renegades—Eric the Huntsman, who aided Snow White in defeating Ravenna in Snowwhite and the Huntsman, and his forbidden lover, Sara—set out to stop them.','The story before Snow White',115000000,164602163,60.467984,6,1523,114,'2016-04-06','en','/pJVpdOXVIE1GQ5bZDBIlLOmWPHP.jpg',3.5405432498731417,3,'2026-09-10',2,NULL,NULL),(290751,'谜一样的双眼','Secret in Their Eyes','故事讲述了一对警探搭档和一名女法官联手调查一桩强奸凶杀案，这起案件发生在1974年，当时正处于阿根廷最黑暗的时代，正义经常得不到伸张，受害者只有用私刑来为死者复仇。','The truth lies in the most unexpected places.',19500000,34854990,15.012237,6.2,336,111,'2015-10-14','en','/y4Wnp4T8qmObhlvOiUB4wBlJUcK.jpg',3.140164138439208,3,'2026-09-10',2,NULL,NULL),(290825,'瑜伽妹斗罗','Yoga Hosers','科琳·格蕾朵（Colleen Collette）和科琳·麦肯奇（Colleen McKenzie），她们放学后在一家叫做“Eh-2-Zed”的便利店里打零工....','Do your \'wurst...',5000000,0,8.618793,4.7,102,88,'2016-07-08','en','/cc40P3lKEiK0H8ZSd8hmBBI0HEV.jpg',2.807835726331426,3,'2026-09-10',2,NULL,NULL),(290864,'一个人的武林','一個人的武林','封号南拳王的洪拳武术家暴毙于隧道中的自家车上，尸体并没刀伤或枪伤痕迹，初步监定死于重拳，重案组总督察陆玄心（杨采妮 饰）负责调查，对死因感到不解；此时却收到监狱传来消息，犯了误杀罪的服刑犯人夏侯武（甄子丹 饰），主动表示愿意协助警方调查，条件是即时假释。  “先练拳次练腿，后擒拿用兵器，由内而外”，夏侯武断言凶手行凶目的并非寻仇，且会继续犯案。果然，号称北腿王、擒拿王、兵器王的武术界精英相继遇害，均死于各自成名的武功之下。得到夏侯武提供线索，以及现场遗下的仿古暗器“堂前燕”，陆玄心终于发现凶手藏身之所，这时夏侯武却违反假释令突然失踪。  　　  两个武艺超凡的杀人犯同时在逃，他们是敌是友？两雄相遇，一场巅峰对决势所难免。','Kung Fu is a Skill for Killing',25000000,0,6.895866,6.5,114,100,'2014-10-31','cn','/kchVm5veesO5c31f6VxNu9rvuTV.jpg',2.8956097082922247,3,'2026-09-10',2,NULL,NULL),(291081,'血色侦程：1974','Red Riding: The Year of Our Lord 1974','1974年的英国约克郡，时刻笼罩在一片氤氲雾气之中，空气中弥漫着哀愁和不祥的气息，接连数起儿童绑架案件让约克的气氛愈加压抑起来。年轻气盛的记者埃迪·丹福德（安德鲁·加菲尔德 Andrew Garfield 饰）对此极为关注，积极展开调查，甚至无暇顾及业已病危的父亲。然而随着调查的深入，他却发现这些并非简单的绑架案，设计政界的黑幕渐渐浮出水面，埃迪也不自觉地为层层危险所包围。浓浓黑雾，难以散去……','An epic tale of murder, corruption and obsession.',0,0,7.247023,7,54,102,'2009-02-28','en','/1MGUwUFkcAKawdsT2q88Sdo2vv6.jpg',2.7388905584625935,3,'2026-09-10',2,NULL,NULL),(291270,'失常','Anomalisa','客户服务主题书籍的作者迈克尔·斯通，始终难以与人建立联结。在一次寻常的出差夜晚，他遇见了一位嗓音独特的陌生女子丽莎，她的出现将彻底打破他那单调沉寂的世界。',NULL,8000000,5659286,21.024346,7,459,90,'2015-12-30','en','/4DJ1zNr4Y6q7zQ27goEYla46VdO.jpg',3.316091191818776,3,'2026-09-10',2,NULL,NULL),(291362,'艰难之路','Road Hard','在他的电影和电视事业枯竭后，布鲁斯·马德森（亚当·卡罗拉）被迫回到路上，一个接一个地扮演一个肮脏的喜剧俱乐部，在经济型酒店房间度过无尽的夜晚，总是乘坐长途汽车。在努力振兴他的事业、重燃他的爱情生活并让他的女儿读完大学的过程中，布鲁斯肯定知道一件事——他必须下车。 艰难之路就是那段旅程的故事。',NULL,1500000,0,0.859014,6.6,8,97,'2015-03-06','en','/aClpHJtwN2I6DmCZpu54LUVoQJK.jpg',2.314454190139293,3,'2026-09-10',2,NULL,NULL),(291805,'惊天魔盗团2','Now You See Me 2','One year after outwitting the FBI and winning the public’s adulation with their mind-bending spectacles, the Four Horsemen resurface only to find themselves face to face with a new enemy who enlists them to pull off their most dangerous heist yet.','You Haven\'t Seen Anything Yet',90000000,334901337,51.535701,6.7,3235,129,'2016-06-02','en','/A81kDB6a1K86YLlcOtZB27jriJh.jpg',3.850335281049424,3,'2026-09-10',2,NULL,NULL),(291870,'下流祖父','Dirty Grandpa','杰森（扎克·埃夫隆饰）是位一板一眼的准新郎，过着无趣保守的生活，被重度控制狂未婚妻使唤，结婚前夕，他去陪刚丧偶的爷爷迪克（罗伯特·德尼罗饰）度假散心，爷爷生性好色，带着保守的孙子踏上了一段啼笑皆非的风流旅程。','This is Jason. He\'s a little worried about his grandpa.',11500000,94073028,56.805781,5.7,1406,102,'2016-01-21','en','/uXw4gDvdi8vs2PCr79dRMcsrIzI.jpg',3.4561466181684444,3,'2026-09-10',2,NULL,NULL),(292481,'Henry & Me','Henry & Me','Henry &amp; Me tells the courageous story of Jack (AUSTIN WILLIAMS), a brave young boy who is dealt a life changing blow. Low on confidence and filled with self-doubt, hope seems lost until a mysterious stranger named Henry (RICHARD GERE) appears. With the touch of his pin, Henry sweeps Jack away to a magical world where illness no longer exists and New York Yankee legends play forever. The incredible journey brings Jack face to face with Babe Ruth (CHAZZ PALMINTERI), Thurman Munson (PAUL SIMON), Lefty Gomez (LUIS GUZMAN) and Mickey Mantle (DAVID MANTLE) – who all teach Jack to face his fears and never give up. The movie climaxes at Yankee stadium, where Jack must test his newfound courage to save the season and find his way home. Featuring an all star-cast of unforgettable characters, Henry &amp; Me is heartwarming movie experience for the entire family with a message of hope… when life throws a curve… swing away!',NULL,5000000,0,0.999655,3,3,67,'2014-08-18','en','/e37dlFgfDk2unRU96NFKgYi9Vxq.jpg',2.133265832360572,3,'2026-09-10',2,NULL,NULL),(292483,'Not Cool','Not Cool','NOT COOL follows former prom king and college freshman Scott (Shane Dawson) who has just returned home for Thanksgiving break only to be dumped by his eccentric, long-term girlfriend. With his world turned upside down, Scott strikes an unlikely friendship with former classmate Tori (Cherami Leigh), an ugly duckling who blossomed in her first semester of college. Together, the two embark on an outrageous adventure through their hometown. But when Scott and Tori find their friendship turning into something deeper, they realize that a few months away may have changed them more than they realized.',NULL,0,0,1.186971,3.7,25,90,'2014-09-23','en','/ikLuZGHTYTVYHDBPsN8dPnoVnYd.jpg',2.5199641014526217,3,'2026-09-10',2,NULL,NULL),(292539,'Food Chains','Food Chains',NULL,NULL,913000,0,0.795698,7.4,8,83,'2014-04-26','de','/ibue9QCounLfYJW6Lwnf6lxGcZ3.jpg',2.3169167350405306,3,'2026-09-10',2,NULL,NULL),(293644,'猫老大前传','Don Gato: El Inicio de la Pandilla','Top Cat has arrived to charm his way into your hearts! Ever wonder how this scheming feline got his start? Well Top Cat Begins reveals the origins of everything you know and love about this classic comedy hero. What follows is an adventure so crazy that it has to be seen to be believed!',NULL,8000000,0,0.719996,5.3,9,89,'2015-10-30','es','/71h3zDCJwhmmOg8gWHRGAgfy79c.jpg',2.3324517455108222,3,'2026-09-10',2,NULL,NULL),(293646,'地心营救','The 33','2010年智利33名矿工遭遇矿难被困于矿井下，在经历了长达69天之后，33名矿工竟然能够全部被成功救出，创造了一个矿难史上的奇迹。','Hope Runs Deep',25000000,24902723,10.699952,6,378,120,'2015-08-06','en','/hTZv0tv0kCOX9vfHeIojvMNu9M0.jpg',3.1360013988063518,3,'2026-09-10',2,NULL,NULL),(293660,'死侍','Deadpool','油嘴滑舌的雇佣兵韦德·威尔逊与瓦妮莎相识相爱，原本混乱的人生也第一次有了真正想要珍惜的未来。然而就在两人感情最幸福的时候，韦德被诊断出晚期癌症。走投无路之下，他接受了一个神秘组织提出的实验治疗，却在那里遭受了漫长而残酷的折磨。实验最终激发出韦德惊人的自愈能力，同时也令他严重毁容。无法以如今的模样重新面对瓦妮莎，他选择隐藏自己的身份，并化身为“死侍”，开始追踪那个将自己变成如今模样的男人阿贾克斯，希望找到让自己恢复原貌的方法……','Witness the beginning of a happy ending',58000000,783112979,514.569956,7.4,10995,108,'2016-02-09','en','/3E53WEZJqP6aM84D8CckXx4pIHw.jpg',5.391998935851042,3,'2026-09-10',2,NULL,NULL),(293670,'哭声','곡성','一名外国人的神秘现身，在宁静的乡间村落中引起居民猜疑——当村民们开始毫无缘由地残暴相残时，猜疑迅速升级为恐慌。负责调查的警察眼见女儿也染上同样的疯狂，便同意请教一位巫师以求解答——却未料到此举令事态陷入更危险的境地。[Well Go USA]','Never be tempted.',0,0,9.05029,7.2,250,156,'2016-05-12','ko',NULL,3.1376441702951956,3,'2026-09-10',2,NULL,NULL),(293863,'时光尽头的恋人','The Age of Adaline','布莱克·莱弗利(BlakeLively)饰演的阿戴琳，已经成家并有了一个女儿，她遭遇一场严重的意外事故，九死一生之后，离奇的事情也发生了，阿戴琳不再变老，年龄永远定格在29岁。长生不老听上去令人艳羡，但亲眼看着朋友和爱人老去的心痛却让阿戴琳无法忍受，为了保守秘密，也为了不再心碎，她开始独自一人生活。如此过了八十多年之后，与慈善家埃利·斯琼斯（米契尔·哈思曼饰）的一次偶遇，重新点燃了阿戴琳的生命和爱情，让她愿意放弃不朽的生命，坠入爱河。','Love is timeless.',25000000,65663276,82.052056,7.4,1990,112,'2015-04-16','en','/3XFuCS6wBfpSnUQboLd1JtkJqe0.jpg',3.953467832533362,3,'2026-09-10',2,NULL,NULL),(294086,'虎橘','Tiger Orange','Chet和Todd自小在单亲爸爸抚养下成长，Chet尽责而抑制，Todd野性而奔放，一有机会就离家出走，前往洛杉矶发展演艺事业，留下Chet独自照顾久病的爸爸。父亲死后Todd更拒绝出席丧礼，过了很久才因其他事回到故乡。结果久别重逢的同志两兄弟因为一位男子而新仇旧恨再度爆发。他们能否重新认识、重新了解？同志钙星Johnny Hazzard转型出演的首部非色情文艺片，本色演技大受赞赏，获2014洛杉矶同志影展最佳男主角奖。','Do We Stand Out or Do We Fit In?',0,0,0.176377,6.4,4,75,'2014-07-26','en','/dxqjlxB346gLTUsbMCdV4LGL0t2.jpg',2.1841411249321916,3,'2026-09-10',2,NULL,NULL),(294254,'移动迷宫2：烧痕审判','Maze Runner: The Scorch Trials','Thomas and his fellow Gladers face their greatest challenge yet: searching for clues about the mysterious and powerful organization known as WCKD. Their journey takes them to the Scorch, a desolate landscape filled with unimaginable obstacles. Teaming up with resistance fighters, the Gladers take on WCKD’s vastly superior forces and uncover its shocking plans for them all.','The Maze Was Just the Beginning.',61000000,311256926,113.161483,6.4,3040,132,'2015-09-09','en','/mYw7ZyejqSCPFlrT2jHZOESZDU3.jpg',3.9033256056306307,3,'2026-09-10',2,NULL,NULL),(294272,'彼得的龙','Pete\'s Dragon','根据1977年经典真人动画歌舞电影《妙妙龙》改编，罗伯特·雷德福、Bryce Dallas Howard、Wes Bentley等参演，讲述小男孩Pete为逃离贪婪的父母而离家并在路上结识了忽隐忽现的妙妙龙Elliott，并一起流浪的故事。','Some secrets are too big to keep.',65000000,143695338,31.974359,6.2,679,102,'2016-08-10','en','/j4fwo99dyxiy3MM2pE9Olid73RR.jpg',3.3357209824137395,3,'2026-09-10',2,NULL,NULL),(294512,'丛林有情狼4：锯齿洞的传说','Alpha and Omega: The Legend of the Saw Tooth Cave','在伦特发现锯齿形洞穴后，阿尔法和欧米茄分享了一次惊险的冒险。小矮子找到一只需要帮助的狼，伸出一只援助之爪。',NULL,0,0,1.874783,6.5,4,53,'2014-07-21','en','/rUgutlhSQabaKO5DPBE2Co8mlyF.jpg',2.188184456551476,3,'2026-09-10',2,NULL,NULL),(294550,'The Outrageous Sophie Tucker','The Outrageous Sophie Tucker','The rags to riches story of Sophie Tucker, an iconic superstar who ruled the worlds of vaudeville, Broadway, radio, television, and Hollywood throughout the 20th century. Before Beyoncé, Lady Gaga, Madonna, Bette Midler, Marilyn Monroe, and Mae West, Sophie Tucker was the first woman to infatuate her audiences with a bold, bawdy and brassy style unlike any other. Using all of \"The Last of the Red Hot Mamas\" 400-plus recently rediscovered personal scrapbooks, authors Susan and Lloyd Ecker take you on their seven-year journey retracing Tucker\'s sixty-year career in show business.`',NULL,0,0,0.021419,0,0,96,'2014-05-02','en','/3mLk5YeXWS8bdtd2glG3PoxqIIK.jpg',1.8338313105319928,3,'2026-09-10',2,NULL,NULL),(294600,'Last I Heard','Last I Heard','Released from federal prison after 20 years due to his ailing health, a formerly powerful New York mobster moves back home and attempts to reconnect with former life in this poignant Sopranos-esque character study.',NULL,0,0,0.35819,6,1,98,'2013-01-01','en','/plfE6Ijfse0ALy4UFdgcAu23F7z.jpg',1.9850692462200004,3,'2026-09-10',2,NULL,NULL),(295886,'街头荣耀','Brotherly Love','影片聚焦费城著名的欧弗布鲁克高中，讲述了全国顶尖高中篮球新星塞尔吉奥·泰勒初尝街头成名滋味，却不得不直面青春期的特殊压力的故事。',NULL,1900000,0,1.367751,6.9,21,89,'2015-04-24','en','/z8Fg0EcHvNLjvASg0h1FbwvrIXe.jpg',2.5147370585799833,3,'2026-09-10',2,NULL,NULL),(295914,'Queen of the Mountains','Kurmanjan Datka. Queen of the Mountains','At a time when most females in Asia possess little or no power over their lives, headstrong Kurmanjan Datka defies her family\'s authority -- and ultimately becomes the ruler of her native Kyrgyzstan region.',NULL,0,0,0.077873,0,0,135,'2014-08-22','ky','/9my4y17YNNIIx6A1aP8BvuO5WdG.jpg',1.8339602625771716,3,'2026-09-10',2,NULL,NULL),(295964,'燃情主厨','Burnt','米其林餐厅如日中天的当红大厨亚当·琼斯（布莱德利·库珀 Bradley Cooper 饰）因浪荡度日，毁了前程。然而受挫的他深信天分并未衰减，于是毅然回到伦敦，卷土重来，找来一群年轻厨师，开一家史无前例的超级餐厅重振雄风。','Never underestimate a man with everything to lose.',20000000,36606743,30.477114,6.3,950,100,'2015-10-02','en','/clSjGfICUauJNcXEtt13dDjm0FP.jpg',3.424307821016711,3,'2026-09-10',2,NULL,NULL),(296096,'遇见你之前','Me Before You','小露是一个年轻又活泼的小镇女孩，不久前突然被咖啡馆解雇，家境不好，学历不高的她，无奈之下只好接下一份需要细心与专业技巧的工作：成为一名四肢瘫痪病人的全职看护。到了病人家中，她才发现看护对象是一名因车祸导致全身瘫痪的年轻人威尔·特雷纳。威尔年轻英俊，博学富有，过去热爱旅行冒险，却因一场车祸而一蹶不振，变得自暴自弃又愤世嫉俗；生性乐观的小露向他展示生命的美好。为了让威尔重新展开笑颜，小露使出浑身解数，两人都得到宝贵的的意外收获，重新找到人生与心灵的归属。','#LiveBoldly',20000000,207945075,53.161905,7.6,2562,110,'2016-06-02','en','/Ia3dzj5LnCj1ZBdlVeJrbKJQxG.jpg',4.007023591503555,3,'2026-09-10',2,NULL,NULL),(296098,'间谍之桥','Bridge of Spies','本片讲述了布鲁克林律师詹姆斯·多诺万的故事，当中央情报局派他执行一项几乎不可能完成的任务——谈判释放被俘的美国U-2飞行员时，他发现自己被推入冷战的中心。','In the shadow of war, one man showed the world what we stood for.',40000000,165478348,48.445978,7.2,2583,141,'2015-10-15','en','/fmOOjHAQzxr0c1sfcY4qkiSRBH6.jpg',3.905046831706072,3,'2026-09-10',2,NULL,NULL),(296099,'假期历险记','Vacation','鲁斯蒂（艾德·赫尔姆斯 Ed Helms 饰）为了活跃家庭气氛，决定效仿老爸克拉克（切维·切斯 Chevy Chase 饰）当年的做法，带妻子与孩子们度过一个难忘而美好的假期。于是他买了辆新车，带着妻子黛比（克里斯蒂娜·艾伯盖特 Christina Applegat e 饰）及两个儿子：詹姆斯（斯凯勒·吉桑多 Sky ler Gisondo 饰）与凯文（斯蒂尔·史泰宾斯 Steele Stebbins 饰），驾车前往美国“最受家庭欢迎的”游乐园——威利鹿乐园。一路上他们经历许多奇妙的遭遇：被大型货车追逐，骑著四轮车在草原上奔驰，在湍急的溪水中泛舟，泡进误以为是温泉的污水池，更有鲁斯蒂的健壮的妹夫斯通（克里斯·海姆斯沃斯 Chris Hemsworth 饰）大秀肌肉……格里斯沃尔德一家能够平安地抵达传说中的威利鹿乐园吗？他们一家人的感情会因此回暖吗？本片是切维·切斯与比佛莉·德安姬罗主演的八十年代经典喜剧片《假期历险记》的续集。','What could go wrong?',31000000,104384188,47.753598,6.2,1195,99,'2015-07-28','en','/5iHs8MxNoNcPCxEkg6DvduKOyZi.jpg',3.4980152220421648,3,'2026-09-10',2,NULL,NULL),(296943,'The Hadza:  Last of the First','The Hadza:  Last of the First','A look at human origins in the very place of our origins, Africa\'s Rift Valley',NULL,0,0,0.045648,0,0,70,'2014-10-31','en','/r2ZshBSTKD8BrBL6lAv1iwCjPVd.jpg',1.8338866543358443,3,'2026-09-10',2,NULL,NULL),(297100,'The Little Ponderosa Zoo','The Little Ponderosa Zoo','The Little Ponderosa Zoo is preparing for their annual fundraiser festival that keeps the zoo afloat. The Freeman family, Jack, Judy, and their young daughter, Charlie opened the zoo years earlier after sharing their own home with the many animals they had rescued through the years With the help of Mr. Baker, their dependable zookeeper, the zoo has always been a huge hit with the small town. But, one day, the local bank owner discovers some dusty old documents in the basement of his bank that show that the zoo is sitting on a gold mine and, with the help of the town Mayor, and the Mayor s bumbling nephew, they immediately devise a devious plan to get the gold for themselves. The greedy trio see the annual festival as the perfect opportunity to put their dangerous plan into action and close the zoo forever and get their hands on the gold!',NULL,500000,0,0.073079,2,1,84,'2014-09-11','en','/qH6NOGiEyBdK6eP9SRd3Hkadshk.jpg',1.9827728772793694,3,'2026-09-10',2,NULL,NULL),(297596,'Dying of the Light','Dying of the Light','Evan Lake, a veteran CIA agent, has been ordered to retire. But when his protégé uncovers evidence that Lake\'s nemesis, the terrorist Banir, has resurfaced, Lake goes rogue, embarking on a perilous, intercontinental mission to eliminate his sworn enemy.',NULL,15000000,0,10.48009,4.5,118,94,'2014-12-04','en','/gL6riNxQeyPXT5YsgqE2aWhl1zi.jpg',2.828050842440137,3,'2026-09-10',2,NULL,NULL),(297621,'纽约女郎乡下情','There\'s Always Woodstock','当有些神经质、苦苦挣扎的词曲作家凯瑟琳·布朗在纽约的生活就快崩溃时，她不得不去面对自己的过去。她花了整个夏天的时间在她小时候成长的家生活，最终明白了要想成功首先要做真正的自己。','Let your heart sing',0,0,2.025701,5.4,12,90,'2014-11-14','en','/4EOoojQInBDbwDtsTQwj7l8Lcw7.jpg',2.3919164348509767,3,'2026-09-10',2,NULL,NULL),(297761,'自杀小队','Suicide Squad','阿曼达·沃勒身为政府秘密机构的领导人，面对社会中出现的层出不穷的暴力恐怖袭击事件，决心启用一批被关押在监狱中判了无期徒刑的超级反派们，他们是小丑女、死亡射手、回旋镖队长、复仇恶魔和杀手鳄。他们所要面对的，是拥有强大法力的魅巫，她和她的哥哥一起制造了一种非常危险的武器，企图用此控制全人类。除此之外，阿曼达还必须提防为了解救女友小丑女而不惜一切手段的危险人物小丑。','Worst Heroes Ever',175000000,745000000,90.23792,5.9,7458,123,'2016-08-02','en','/sk3FZgh3sRrmr8vyhaitNobMcfh.jpg',3.918136840817844,3,'2026-09-10',2,NULL,NULL),(298312,'探访惊魂','The Visit','单亲妈妈罗莱塔（凯瑟琳·哈恩 饰）送女儿贝卡（奥利维亚·德扬 饰）和儿子泰勒（艾德·奥克森博尔德 饰）到乡下探访外祖父母，姐弟二人原本以为这是一次愉快的探亲之旅，没想到的是，外表慈爱的外祖父 （皮特·麦克罗比 饰）与外祖母（狄安娜·杜纳甘 饰），背后却隐藏着凶残的一面，还对两个小孩施以残暴的恐吓，而姐弟俩则用录像机记录下了这一切...','No one loves you like your grandparents.',5000000,98450062,38.94708,6,1360,94,'2015-09-10','en','/nOOiC5xApxfGgtTZ2TEoyHqY2GT.jpg',3.467674924736714,3,'2026-09-10',2,NULL,NULL),(298584,'新尸骨无存','Cabin Fever','在一个阳光明媚的日子里，凯伦（盖琦·格莱特利 Gage Golightly 饰）、保罗（塞缪尔·戴维斯 Samuel Davis 饰）、杰夫（马修·达达里奥 Matthew Daddario 饰）、玛茜（娜蒂安·克劳克 Nadine Crocker 饰）、伯特（达斯汀·英格拉姆 Dustin Ingram 饰）等五位好友来到了一个远离城市喧嚣的山林度假。男男女女尽情享受浪漫时光，脑子有点儿二的伯特则拿着半自动步枪玩耍，却不小心伤到了路人。夜幕降临，他们回到小屋休息。而就在此时，被伯特射伤的男人前来求救。伯特为了隐藏真相谎称该男子被神秘病毒感染，以致于众人下狠手将其拒之门外。  　　这一事件彻底摧毁了他们的假期，等待几个年轻人的还有更为恐怖的事情……','You can\'t run from what\'s inside.',0,0,5.379319,4.4,111,99,'2016-02-12','en','/yHItp5KNzq58CzQEQ7ySo4PGWue.jpg',2.8027400766788966,3,'2026-09-10',2,NULL,NULL),(299145,'Stranded','Dawn Patrol','After the brutal murder of his beloved brother, a small-town surfer seeks revenge against the gang of merciless thugs he holds responsible. However, when another tragedy brings him face to face with the consequences of his actions, he must seek forgiveness from the very people he despises most.','Revenge comes at a price.',0,0,3.230779,5,11,86,'2015-06-05','en','/ijUz1buTZBIqNMAOe5s3EXEie2K.jpg',2.375787291081281,3,'2026-09-10',2,NULL,NULL),(299245,'绞刑架','The Gallows','20年前，小镇上一所高中在戏剧表演时发生意外，主角无辜命丧舞台。20年后，同校的师弟师妹为纪念惨剧发生20周年，决定重新编排当年未能圆满谢幕的舞台剧，没想到骇人的事情发生了……','Every School Has Its Spirit',100000,42664410,18.045782,4.9,361,87,'2015-07-10','en','/kw2uZbmbRXdm9YGx71PSO1E8mB0.jpg',3.033811736110999,3,'2026-09-10',2,NULL,NULL),(299552,'Born Of War','Born Of War','Mina, a young college student, has her life ripped away after her family is killed. When she finds out their murder was part of a botched kidnapping to return her to her real father—a terrorist in the middle east.',NULL,0,0,1.136568,4.1,7,109,'2013-12-05','en','/rmAzBd173UrSWF8K3lEBS5JfnfY.jpg',2.282176580460898,3,'2026-09-10',2,NULL,NULL),(299553,'鲨鱼湖泊','Shark Lake','在一个名为高山湖的美国小镇，静谧的夜幕下响起刺耳的警笛。女警长梅瑞狄斯·赫尔南德兹（莎拉·玛卢库·莱恩 Sara Malakul Lane 饰）抓住了在逃罪犯克林特·格雷（杜夫·龙格尔 Dolph Lundgren 饰），此后收养了克林特年幼的女儿卡莉（Lily Brooks O\'Briant 饰）。如是过了五年，梅瑞狄斯和卡莉亲密无间，形同母女，当得知克林特即将出狱并且法院要将卡莉还给对方时，她的心中升起重重愁云。与此同时，小镇发生熊袭击人的事件。警方据此发布警告，然而一位生物学家研究发现，肇事者实则是一头能在淡水中生存的牛鲨。','In this lake you have to fight to survive',2000000,0,1.187764,4.4,19,92,'2015-10-02','en','/rAvFko64iscEmDQkVnmc8rpmqCw.jpg',2.473949901787277,3,'2026-09-10',2,NULL,NULL),(299687,'第五波','The 5th Wave','改编自同名畅销小说，故事讲述地球遭到外星人攻击，人类文明退回石器时代，16岁少女凯西作为仅存人类之一，挣扎生存，寻找希望。','Protect Your Own',38000000,109906372,57.889964,5.6,1945,112,'2016-01-14','en','/kX3ZmeShzt8Chx5CxCAWNKi8xJW.jpg',3.498704620172685,3,'2026-09-10',2,NULL,NULL),(300168,'天将雄师','天將雄師','西汉汉元帝年间，西域都护府大都护霍安（成龙 饰）遭奸人陷害，沦为奴役，被刺配至雁门关修城。恰在此时，罗马将军卢魁斯（约翰·库萨克 John Cusack 饰）护卫遭到哥哥迫害的罗马小王子（西蒙子 饰）逃命至雁门关。双雄在西域戈壁相遇，从开始的兵戎相见到惺惺相惜，最终化敌为友。一日，霍安为洗清自己冤屈四处追查时，无意间撞破了好兄弟殷破（崔始源 饰）与罗马大王子提比斯（艾德里安·布洛迪 Adrien Brody 饰）不可告人的秘密。与此同时，提比斯为追杀卢魁斯与小王子一行人也亲自带兵赶来西域。为保护小王子和西域诸国的安危，霍安与卢魁斯联手与提比斯在戈壁大漠展开了一场生死之战','When the Eagle meets the Dragon',65000000,121545703,9.568884,5.9,145,127,'2015-02-19','zh','/kAMpDcY8dPuuBajNNzr7GFwWuhp.jpg',2.9272273803432,3,'2026-09-10',2,NULL,NULL),(300327,'Death Calls','Death Calls','An action-packed love story on the Mexican border featuring oppression, revenge, reincarnation and rebirth.',NULL,0,0,0.005883,0,0,0,'2010-09-01','en','/aAfg4t3Aoz2KSfaN0q9vYqsYZBo.jpg',1.8337958232507745,3,'2026-09-10',2,NULL,NULL),(300671,'危机13小时','13 Hours: The Secret Soldiers of Benghazi','2012年9月11日，恐怖分子袭击美国领事馆，美国中央情报局处于绝对劣势下。六位精锐部队退役军人临危受命保护中央情报局。在诸事不利的情况下，六位精英展现出了过人的勇气，力挽狂澜。','When everything went wrong, six men had the courage to do what was right.',50000000,69411370,42.526529,7,938,144,'2016-01-13','en','/4EY2nJs3iECTLumhIgHcvBB9uvT.jpg',3.567102660301693,3,'2026-09-10',2,NULL,NULL),(300673,'怒海救援','The Finest Hours','影片改编自2009年的一部小说，讲述了1952年2月海岸警卫队救援失事油轮的真实故事。一艘名为SS Pendleton油轮在开往波士顿的航程中因风暴抛锚，船只开始渗水并有沉没的风险，而船上30位水手的命运危在旦夕。雷·希伯特（卡西·阿弗莱克饰）作为当时船上职位最高的工作人员开始组织众人自救，与此同时，马萨诸塞州海岸警卫队派出了救援队开始海上搜救。在队长伯尼·韦伯（克里斯·派恩饰）的带领下，四名警卫队成员开着一艘发动机都坏掉的木质救生船出发，等待他们的将是一场面对海浪的殊死搏斗……','32 survivors, room for 12.',80000000,52099090,28.223664,6.3,588,114,'2016-01-25','en','/uhH74IJa4aazZSs1gRt2474FmBc.jpg',3.308418731981014,3,'2026-09-10',2,NULL,NULL),(300706,'Let\'s Kill Ward\'s Wife','Let\'s Kill Ward\'s Wife','Everyone hates Ward’s wife and wants her dead, Ward (Donald Faison) most of all. But when his friends’ murderous fantasies turn into an (accidental) reality, they have to deal with a whole new set of problems — like how to dispose of the body and still make their 3 p.m. tee time. Scott Foley\'s directorial debut, also starring Foley, Patrick Wilson, Amy Acker, and Nicolette Sheridan, is a blackly comic caper about helping a friend out of a bad relationship by any means necessary.','Real Friends Do the Dirty Work.',5000000,0,8.496364,5.5,76,81,'2014-12-23','en','/A6jwjS9mS4qBzhaA6ob4PUd9PJ0.jpg',2.7790719453556503,3,'2026-09-10',2,NULL,NULL),(301325,'惊恐地','#Horror','#HORROR是一部关于六位年轻女性的生活的电影，山姆、吉雷吉、索菲亚、弗朗西斯卡、猫和伊娃由我们年轻的女星合唱团饰演。他们的世界是金钱、成功、轻松和腐朽的世界。这是一部关于网络欺凌的恐怖电影。这部电影是一个整体的洞察，女孩在成长过程中承受的压力，这个世界越来越依赖于社交媒体平台提供的推广和关注，但防止欺凌。以及父母在控制孩子使用互联网和欺凌方面必须发挥的作用，在社会中扮演了如此可怕的角色。这些年轻女子在一座玻璃豪宅里讲述这个故事，里面摆满了价值数百万美元的艺术品，仿佛她们住在一个当代博物馆里，里面收藏着乌尔斯·菲舍尔、罗布·普鲁伊特、丹·科伦、弗朗茨·韦斯特、史蒂文·希勒的作品。','Death is trending.',1500000,0,2.815228,3.3,52,90,'2015-11-20','de','/v9pTHwhpSWmPHU8i1pEt9VIG9Kg.jpg',2.646129716730544,3,'2026-09-10',2,NULL,NULL),(301351,'我们是你的朋友','We Are Your Friends','年轻电音DJ科尔（扎克·埃夫隆 Zac Efron 饰），希望有一天能够成为伟大的音乐制作人。在他追逐梦想的过程中，认识了DJ詹姆斯（韦斯·本特利 Wes Bentley 饰），詹姆斯也曾因年少成名而轻佻自负过，但随着年龄的增长，现在他拥有的正是科尔想要的生活。直到有一 天，他和詹姆斯爱上了同一个女孩苏菲（艾米丽·拉塔科斯基 Emily Ratajkowski 饰），这时科尔才了解到，当你的音乐被越多人听到，你的世界就会变得越复杂。','The world is yours.',6000000,11122090,28.819424,6.3,658,96,'2015-08-26','en','/4fZEQ1dJtK7LhaVYvhbod1LIdKg.jpg',3.335735213927255,3,'2026-09-10',2,NULL,NULL),(301365,'霓虹恶魔','The Neon Demon','一个年轻女孩来到洛杉矶，希望成为一名模特。她的纯洁与热情使她大获成功，也激起了其他他人的嫉妒和垂涎。一些女孩在她面前俯首称臣，另一些人却决定使出所有手段偷走她的美丽容颜。','Beauty is vicious.',7000000,1333124,38.150787,6.4,887,117,'2016-06-08','en','/x7ZM5QOv5xvKeKtkyI15bffaYmI.jpg',3.442473113707567,3,'2026-09-10',2,NULL,NULL),(301748,'愿赌服输','The Opposite Sex','男主为了追求女主，总是不断向女主提出各种挑战。可是，每次挑战的结果男主都惨败……','A battle of the sexes, winner takes all.',3300000,45000,2.964785,4.1,9,96,'2014-11-08','en','/4OGyobNioLlo1aj4ioxxmsssSCj.jpg',2.333185650207767,3,'2026-09-10',2,NULL,NULL),(302156,'超脑48小时','Criminal','一位知悉国家机密的CIA探员比利·波普 意外身亡，在弗兰克斯博士 的协助下将其记忆与技能植入了一位极度危险且无法预测的罪犯杰里科·斯图尔特 身上，而探员贵格·威尔斯 必须靠这位不定时炸弹来摧毁企图攫取国家机密的犯罪组织。杰里科·斯图尔特为了救回换脑后渐渐爱上的比利·波普被胁迫的妻子和孩子，重新找回自己的生活，不得不在48小时的时间里，与犯罪组织展开殊死搏斗。',NULL,31500000,14708696,27.891012,5.7,557,113,'2016-04-14','en','/wClqxwXOOS1RTSSLYH9YJcZlKPn.jpg',3.217170920600228,3,'2026-09-10',2,NULL,NULL),(302579,'Naturally Native','Naturally Native','Naturally Native follows the lives, loves, pain, joy and relationships of three sisters as they attempt to start their own business. Of American Indian ancestry, but adopted by white foster parents as young children, each sister has her own identity issues and each has chosen a very different career path. Now dedicated to starting a Native cosmetic business, they attempt to overcome obstacles both in the business world and in the home. A touching love story of family and culture, Naturally Native also interweaves a subtle, but strong wake-up call regarding the treatment of Native people in corporate America. Naturally Native also provides some insight into tribal infrastructure and gaming issues.','Sometimes When You\'re Going Home, It\'s Important To Know Where You\'ve Come From...',700000,10508,0.578798,0,0,107,'1999-10-08','en','/yTQPrKLhKC8qUe2CMn8MxmfaxA5.jpg',1.835104473850618,3,'2026-09-10',2,NULL,NULL),(302688,'我盛大的希腊婚礼2','My Big Fat Greek Wedding 2','《我盛大的希腊婚礼2》仍将由尼娅·瓦达拉斯（Nia Vardalos）自己编剧、自己主演，而片中饰演他老公的约翰·科伯特（John Corbett）以及她那个吵吵闹闹的希腊大家庭成员也都将回归。  　　据悉，这部续集还会由汤姆·汉克斯（Tom Hanks）和他夫人丽塔·威尔森（Rita Wilson）通过Playtone制片公司制作。  　　对于自己为何等了12年才创作续集，尼娅·瓦达拉斯解释说，十二年前的那部电影是她根据自己家庭生活创作的，如今她当了妈妈，自己的家庭生活又翻开了新的篇章，因此才会创作续集。“当然，有些媒体会说我缺钱了，或者我想亲吻约翰·科伯特了”，她开玩笑说，“这两者中有一个是真的”。','People change. Greeks don\'t.',18000000,88923251,16.027955,5.5,322,94,'2016-03-23','en','/21sPYw1Cu4Ed8kpQYdvhXGlgbJW.jpg',3.0686578097486117,3,'2026-09-10',2,NULL,NULL),(302699,'乌龙特工','Central Intelligence','会计师卡尔文（凯文·哈特 Kevin Hart 饰）在高中时代曾是学校的体育明星，他热心张罗高中同学聚会，于是在Facebook上联系到了老同学鲍勃（道恩·强森 Dwayne Johnson 饰），他没想到这个在高中时常受欺负的老同学现在已经是CIA的职业杀手，而他也万万没想到自己将被卷入制止军事秘密泄露的任务中。','Saving the world takes a little Hart and a big Johnson',50000000,216972543,45.318703,6.2,1650,107,'2016-06-15','en','/2Grmes5rPxr9h4WVAfMzMduvZVL.jpg',3.5643608300831464,3,'2026-09-10',2,NULL,NULL),(303858,'金钱怪兽','Money Monster','知名电视财经专家李·盖茨（乔治·克鲁尼 George Clooney 饰）在电视财经节目《金钱怪兽》中担任主持人而声名大噪，在节目中经常出现疯狂举动，会大声说出投资建议，不时在节目中用搞笑的道具和音效介绍股市。然而，事实上他是透过内线消息让他在华尔街成为赚钱高手。一名不速之客（杰克·奥康奈尔 Jack O\'Connell 饰），因为听信投资分析而赔光积蓄，因此在节目直播中绑架了盖茨与节目制作人帕蒂·芬恩（朱莉娅·罗伯茨 Julia Roberts 饰）。同时全国民众也透过电视在看着这场玩命直播，而这场挟持行动也揭发了背后更巨大的金融操弄丑闻。','Not every conspiracy is a theory.',27000000,93282604,38.279458,6.5,1068,98,'2016-05-12','en','/qKapu5Kv2enlJ3OAXAVeQDrHo8j.jpg',3.504801857031978,3,'2026-09-10',2,NULL,NULL),(304357,'金衣女人','Woman in Gold','犹太裔美国妇女玛丽亚（海伦·米伦 Helen Mirren 饰）为讨回在第二次世界大战中被纳粹掠走的传家宝——《艾蒂儿肖像一号》，向年轻律师兰迪（瑞恩·雷诺兹 Ryan Reynolds 饰）求助，兰迪被名画不凡的价值与传奇的经历所吸引，决定陪玛丽亚追讨名画，这本是正义行为，但他们却发现奥地利当局使出种种手段，只为留住被视为“奥地利蒙娜丽莎”的国宝画作，玛丽亚与政府机器不屈不挠地抗争的同时，重回维也纳故地，掩埋超过半个世纪的痛苦记忆再度浮上她的脑海……','Justice is priceless.',11000000,61619773,21.204929,7.3,440,120,'2015-04-10','en','/cSAjBlHOK6fwhXq5qY46PjEHzDl.jpg',3.33858004999368,3,'2026-09-10',2,NULL,NULL),(304410,'The Bélier Family','La Famille Bélier','The whole Bélier family is deaf, except for sixteen year old Paula who is the important translator in her parents\' day to day life especially when it comes to matters concerning the family farm. When her music teacher discovers she has a fantastic singing voice and she gets an opportunity to enter a big Radio France contest the whole family\'s future is set up for big changes.',NULL,11000000,0,25.302978,7,766,105,'2014-12-17','fr','/ludVWYu7m7ZJx5VhTa3TpdNyd23.jpg',3.4704321792111092,3,'2026-09-10',2,NULL,NULL),(306667,'Horse Camp','Horse Camp','What’s the matter with Kathy (Jordan Trovillion, Highland Park)? She’s your typical 17 year-old girl in search of something more in her life. It seems the only place she is going to find it is at Horse Camp. Her father Luke (Dean Cain, Lois &amp; Clark: The New Adventures of Superman) recognizes that she’s got it in her blood, a sensibility in her being - she understands horses just as much as they understand her. But at Horse Camp there is much more to learn, not only about horses, but about people and the many challenges of friendship.','The summer they\'ll never forget',0,0,0.172299,5.5,2,108,'2015-01-10','en','/bgAHH1m44RyRefLbUFAG0iOX03B.jpg',2.072233360793295,3,'2026-09-10',2,NULL,NULL),(306745,'被拒人生','Freeheld','电影《被拒人生》根据真实事件改编，讲述汽车维修工泰西·安德里（艾伦·佩吉饰）与其警探女友罗拉·海斯特（朱丽安·摩尔饰）在后者被诊断身患绝症后，进行养老金维权的故事。  电影剧本由《费城故事》的编剧罗恩·内斯万尼尔负责，除了新晋奥斯卡影后朱丽安·摩尔和艾伦·佩吉外，两位实力男星迈克尔·珊农和史蒂夫·卡瑞尔也有加盟。  影片在年初的柏林电影节引发好莱坞各大片商的疯狂竞标，最终狮门影业以七位数的高价拿下本片的北美发行权。  影片定于10月2日在北美公映。','A true story of love and injustice.',7000000,573335,8.184588,7.1,164,103,'2015-10-02','en','/ijJjbfBxq7tRuAK8oYF58H15TTn.jpg',3.015654837309218,3,'2026-09-10',2,NULL,NULL),(307081,'铁拳','Southpaw','比利·霍普（杰克·吉伦哈尔 Jake Gyllenhaal 饰）曾是一位知名的左撇子拳击手，他靠着冷酷野蛮的出拳，为自己赢得拳王的荣耀。一次枪击意外，打破了他和妻子莫琳（瑞秋·麦克亚当斯 Rachel McAdams 饰）及女儿莱拉（乌娜·劳伦斯 Oona Laurence 饰）的幸福生活。比利开始自暴自弃、酗酒吸毒，女儿也将被送往福利机构。这时，他幡然醒悟，并在教练提克（福里斯特·惠特克 Forest Whitaker 饰）的帮助下重返拳击界，以挽回女儿的尊重和爱，以及自己职业生涯的希望……','Believe in Hope.',30000000,91709827,65.364452,7.3,2067,123,'2015-06-15','en','/kSQ49Fi3NVTqGGXILmxV2T2pdkG.jpg',3.904257717934375,3,'2026-09-10',2,NULL,NULL),(308467,'Roadside','Roadside','Dan Summers and his pregnant wife, Mindy, fight for their lives when they are held hostage in their car by an unseen gunman on the side of a desolate mountain road.','Their fate...is in his hands.',0,0,0.160234,4.2,5,90,'2013-03-01','en','/26zPkq5RwGl08O3y04FYbPBZqvX.jpg',2.2193123815094706,3,'2026-09-10',2,NULL,NULL),(308529,'Kickboxer: Vengeance','Kickboxer: Vengeance','Eric and Kurt Sloane are the descendants of a well-known Venice, California-based family of martial artists.  Kurt, the younger of the two,  has always been in his brother Eric’s shadow, and despite his talent has been told he lacks the instinct needed to become a champion.  But when Kurt witnesses the merciless murder of his brother at the hands of Muay Thai champion Tong Po, he vows revenge.  He trains with his brother’s mentor for a fight to the death with Tong Po. At first it seems impossible to turn Kurt into the living weapon he must become to beat Tong Po, but through a series of tests and dangerous encounters, Kurt proves he has a deeper strength that will carry him through to his final showdown with Tong Po.',NULL,17000000,0,6.526588,4.5,99,90,'2016-07-14','en','/ccRh8i0CKhwtqDeKBiRU0yDa8Rc.jpg',2.790807029684013,3,'2026-09-10',2,NULL,NULL),(308531,'忍者神龟2：破影而出','Teenage Mutant Ninja Turtles: Out of the Shadows','纽约恢复平静后，忍者神龟依旧隐藏在城市暗处守护着人们。然而被捕的施莱德在转移途中成功逃脱，并与科学家巴克斯特·斯托克曼联手，还将两名手下改造成力量惊人的猪面和牛头。为了阻止施莱德再次威胁纽约，莱昂纳多、拉斐尔、多纳泰罗和米开朗基罗重新出动，并与爱普莉尔·奥尼尔以及新结识的凯西·琼斯并肩作战。随着追查深入，他们却发现施莱德背后还存在来自异世界的强大势力朗格，一场远比之前更加危险的危机正在逼近……','Raise some shell.',135000000,245623848,39.873791,5.8,963,112,'2016-06-01','en','/9xeqNOkJUrKEkHvqfK1Td6jZ3y2.jpg',3.363506367078733,3,'2026-09-10',2,NULL,NULL),(308639,'酷毙了','Dope','高中生马尔科姆（Shameik Moore 饰）是一个热爱嘻哈音乐、颇具表演天份的极客，古怪的性格使他成为同学眼中的异类，因此常被欺负，他只好处处小心，希望能低调过完高中的最后一年。  　　一天，马尔科姆和他的朋友，受邀参加一个毒贩的生日派对，马尔科姆为了与心仪已久的纳吉亚（佐伊·克罗维兹 Zoë Kravitz 饰）见面才答应前往。不料他和朋友却因此卷入一场可怕的毒品纠纷，被迫在洛杉矶四处逃命。马尔科姆可不想进监狱，考上哈佛才是他一直以来的梦想，而这场意外会影响他的哈佛梦吗？','It\'s hard out here for a geek.',700000,17986781,29.761163,7.2,691,103,'2015-06-19','en','/n6u00imN7AX2NiyWUc5kTgHXmEf.jpg',3.4806234136337064,3,'2026-09-10',2,NULL,NULL),(309425,'你相信么？','Do You Believe?','十二个不同的灵魂在世界各个地方游荡，他们都渴望获取更多。随着生命的意外相交，他们每个人都将会发现基督的十字架力量……即使他们仍旧不相信它。一位当地牧师被一位年老的街头传教士的信心所撼动，他开始领悟到真正的信仰是需要行动的。这位牧师点燃了自己的信仰旅程，并以上帝的旨意来作工把这种信仰的感动传递给每一个人。这不仅仅是一部电影，同时也是一个我们人生中必须回答的问题：你相信上帝吗？',NULL,0,0,2.470443,6.6,48,115,'2015-03-20','en','/89fJ4hV9fCB01EvhhLOgjMJI4A6.jpg',2.6935627784993703,3,'2026-09-10',2,NULL,NULL),(309503,'Zipper','Zipper','Sam Ellis is a man on the rise — a hot-shot federal prosecutor on the cusp of a bright political future. But what was meant to be a one-time experience with an escort turns into a growing addiction — a new demon threatening to destroy his life, family, and career.','Why take the risk',0,0,8.516229,5.5,58,103,'2015-08-28','en','/qHQbXfdYhh3CRtIufoiD4AxPWi0.jpg',2.725107005576537,3,'2026-09-10',2,NULL,NULL),(309809,'小王子','The Little Prince','灰蒙蒙的都市丛林，美丽的小女孩眼神中没有渴望和雀跃，她跟随妈妈穿梭钢筋水泥的光影之间，按照社会既定法则亦步亦趋。她的未来似乎早被注定和规划，即使生日礼物也找不到些许惊奇。为了进入好学校，母女俩搬到郊外一幢独栋房子里，旁边则是一间与周遭格格不入的破房子。某天，一个飞机螺旋桨突然破墙而入，从而建立起女孩和隔壁那个怪爷爷的友谊。老人自称曾是一名飞行员，年轻时他迫降沙漠，在那里认识了有着纯真心灵的小王子。女孩听老人讲述着有着童话般瑰丽色彩的往事，不知不觉间心驰神往……','Growing up isn\'t the problem... forgetting is.',64000000,97571250,35.384423,7.6,756,92,'2015-07-29','en','/tOrC44Smwlhfp4dnA25vN5cJVIV.jpg',3.581407811874272,3,'2026-09-10',2,NULL,NULL),(309919,'魔鬼诅咒','The Curse of Downers Grove','The town of Downers Grove looks like your average suburban neighborhood -- but Downers Grove has a disturbing secret.... For the past eight years, one senior from every high school graduating class has met a bizarre death right before graduation day. And this year, Chrissie Swanson has a terrible feeling that she is going to be the one to die. Can Chrissie survive the curse of Downers Grove or will she, like those seniors before her, fall prey to the town\'s deadly secret?','High school can be murder.',2000000,0,2.00163,4.4,24,89,'2015-08-21','en','/fTpYTV0a23Diw344tE199bIHo7l.jpg',2.5209365752716493,3,'2026-09-10',2,NULL,NULL),(310131,'女巫','The Witch','1630年，新英格兰。一位英国农民面临被教会驱逐的威胁，带着妻子和五个孩子离开殖民种植园，迁至一片不祥森林边缘的偏僻土地——林中潜伏着未知的邪恶。几乎立刻，诡异骇人之事接连发生：牲畜变得邪异，庄稼枯萎凋败，一个孩子失踪，另一个则仿佛被恶灵附身。随着猜疑与偏执日益加剧，家庭成员指控正值青春期的女儿托马辛施行巫术，但她坚决否认。当处境愈发凶险，每个家庭成员的信仰、忠诚与爱都将经受震撼而难忘的考验。[A24]','Evil takes many forms.',3500000,40423945,50.319662,6.3,1434,92,'2016-02-19','en','/rsOXBPIhfa8av3mL0IQlOeyghQD.jpg',3.564428648805081,3,'2026-09-10',2,NULL,NULL),(310569,'The Second Mother','Que Horas Ela Volta?','After leaving her daughter Jessica in a small town in Pernambuco to be raised by relatives, Val spends the next 13 years working as a nanny to Fabinho in São Paulo. She has financial stability but has to live with the guilt of having not raised Jessica herself. As Fabinho’s university entrance exams approach, Jessica reappears in her life and seems to want to give her mother a second chance. However Jessica has not been raised to be a servant and her very existence will turn Val’s routine on its head. With precision and humour, Anna Muylaert turns her eye on the subtle and powerful forces that keep rigid class structures in place and how the youth may just be the ones to shake it all up.',NULL,0,0,9.683622,7.8,165,110,'2015-02-08','pt','/d5aIZjwdG87YradTjmtmyZtR1dy.jpg',3.05944472072227,3,'2026-09-10',2,NULL,NULL),(310706,'Black Water Transit','Black Water Transit','In this action thriller set in post-Katrina New Orleans, business owner Jack Vermillion (Laurence Fishburne) is struggling to run a legitimate shipping company while bad guy Ernest Pike (Karl Urban) is struggling to get his family\'s illegal gun collection out of the country. When their paths collide, Jack realizes that exposing Pike might get him just the sway he needs to persuade law enforcement officials to treat his imprisoned son kindly.',NULL,0,0,0.126738,0,0,100,'2009-05-13','en',NULL,1.8340718798529652,3,'2026-09-10',2,NULL,NULL),(310933,'情劫','Bleeding Hearts','在十九世纪的美国西部草原，白人和印第安人始终以水和火的姿态对立着，白人喜欢痛斥印第安人，印第安人则咒骂白人。在某天的草原上，印第安的勇士又遇见了一车队的白人。在一番激战之后，印第安人成功消灭了毫无作战能力的白人车队，当他们企图杀死最后的两名妇女时，勇士领袖米托万因为看见其中一位姑娘安娜手拥《圣经》而放弃了原来的打算。安娜和同行孕妇逃回白人小镇，安娜因为她的勇敢而受到了大家的尊敬，也得到了丹尼尔--一个老实淳朴的小镇农民的垂青。虽然没有浓烈的感情，但安娜还是欣然接受了哥哥为她安排的这场婚姻。不管和丹尼尔结婚是因为丹尼尔老实可靠，还只是因为他有一双蓝色的眼睛，总之安娜已经下决心和这个深爱她的男人过完平淡的一生，并且努力扮演好妻子的角色。但是上帝似乎并不满足安娜这样的选择。新婚不久的一个早晨，当安娜和小镇上的女孩莎拉同在厨房讨论着生活的乏味和梦想的时候，米托万带着他的族人闯进了她和丹尼尔的小屋，并在丹尼尔不在时轻易虏走了安娜以及莎拉……@m.yakutv.cc',NULL,0,0,0.100533,2,1,0,'2013-06-01','en','/o8alLhpTJUKuFPEU7dECEUj1MNL.jpg',1.9828355876178456,3,'2026-09-10',2,NULL,NULL),(312113,'Black November','Black November','A volatile, oil-rich Nigerian community wages war against their corrupt government and a multi-national oil corporation to protect their land from being destroyed by excessive drilling and spills.  To seek justice, a rebel organization kidnaps an American oil executive and demands that his corporation end the destruction and pollution.  Inspired by true events, Black November is the gripping story of how a community rises up and takes drastic measures to make sure their voices are heard.','Blood Will Be Spilled',12500000,0,1.589693,6.4,4,95,'2012-12-07','en','/onBy6iJt3BX8MSc7GjzIRgE07oV.jpg',2.1873694167925346,3,'2026-09-10',2,NULL,NULL),(312221,'奎迪','Creed','阿多尼斯·约翰逊从未见过他著名的父亲——世界重量级拳王阿波罗·奎迪，父亲在他出生前便已离世。然而，拳击无疑流淌在他的血液中。为此，阿多尼斯前往费城——阿波罗·奎迪当年与名为洛奇·巴尔博亚的顽强新秀进行传奇之战的地方。在这座“兄弟友爱之城”，阿多尼斯找到了洛奇，并请求他担任自己的教练。尽管洛奇坚称自己已永远退出拳坛，但他从阿多尼斯身上看到了阿波罗曾拥有的力量与决心——那位从劲敌成为挚友的人。洛奇最终同意训练这位年轻拳手，尽管这位前冠军自己正在对抗一个比他在拳台上面对过的任何对手都更可怕的敌人。有了洛奇的指导，阿多尼斯很快获得了争夺冠军的机会……但他能否及时培养出真正拳击手的斗志与心性，踏上擂台？[华纳兄弟]','Your legacy is more than a name',37000000,173567581,57.773583,7.3,1915,133,'2015-11-25','en','/1BfTsk5VWuw8FCocAhCyqnRbEzq.jpg',3.8650037557003687,3,'2026-09-10',2,NULL,NULL),(312791,'女孩闺房','GirlHouse','凯莉（艾丽·柯布琳饰）是一名大学生，性感漂亮。她的父亲刚刚去世不久，母亲又没有工作。为了赚取学费和生活费，并且让母亲安心，凯莉决定加入“女孩闺房”，以赚取高额报酬。“女孩闺房”里住着一群同样性感美丽的女孩，每天在网络上进行不同程度的情色表演提高人气。而凯莉一去就成功吸引了大批观众，但是，在这批观众里，有一个名为loverboy的盯上了她……','Enjoy the show.',3150000,0,8.039223,5.2,97,100,'2014-10-16','en','/cQgjpjFHbfmUJgkOfzpxMjBSUqO.jpg',2.8155852029837796,3,'2026-09-10',2,NULL,NULL),(312793,'The Walking Deceased','Walking with the Dead','THE WALKING DECEASED is the Scary Movie of the zombie genre, ripping on the biggest and best of zombie pop-culture, arguably the most crazed genre in the world. The story follows a group of survivors from all walks of the apocalypse – an idiotic Sheriff with definite coma-induced brain damage, his hardass son and a hobo with only a crossbow to stave off the walking dead, four squabbling friends forced to survive this zombieland together, and a lonely zombie who just needs love to fully regain his warm body – who leave their once-safe mall hideout in search of the rumored Safe Haven Ranch, a refuge untouched by the zombie virus that has ravaged humanity. But despite the comforting name, they discover that this sanctuary may not be as welcoming as advertised.',NULL,0,0,1.332804,4.2,35,90,'2015-03-20','en','/ss6eqPxe9vmsYOxb3LGUs5mIXvq.jpg',2.5886725672428934,3,'2026-09-10',2,NULL,NULL),(313922,'绿色房间','Green Room','讲述朋克乐队成员被犯罪团伙困于一间小房间，选择坐等命运还是反抗火拼同时，人心也在幽闭的空间内慢慢改变。','One way in. No way out.',5000000,3220371,30.001024,6.7,683,95,'2016-04-15','en','/BmtP6DNKD9u9ct4vX6QDWoN8ZA.jpg',3.405111486165547,3,'2026-09-10',2,NULL,NULL),(314365,'聚焦','Spotlight','本片以震撼人心的真实事件改编，荣获普利策奖的《波士顿环球报》调查报道撼动了整座城市，并引发全球最古老、最具威望的机构之一陷入信任危机。当报社锲而不舍的“聚焦”调查组记者深入挖掘天主教会的性侵指控时，长达一年的调查揭露了波士顿宗教、司法与政府高层长达数十年的掩盖行径，随即在全球掀起揭露真相的浪潮。[开路影业]','Break the story. Break the silence.',20000000,88346473,41.503588,7.8,2686,128,'2015-11-06','en','/8DPGG400FgaFWaqcv11n8mRd2NG.jpg',4.04144035209757,3,'2026-09-10',2,NULL,NULL),(314385,'By the Sea','By the Sea','Set in France during the mid-1970s, Vanessa, a former dancer, and her husband Roland, an American writer, travel the country together. They seem to be growing apart, but when they linger in one quiet, seaside town they begin to draw close to some of its more vibrant inhabitants, such as a local bar/café-keeper and a hotel owner.',NULL,10000000,3727746,11.267676,5.4,156,122,'2015-11-12','en','/Xoz9uKrdm0fx8kuhLqsGJahPNL.jpg',2.9197618556915064,3,'2026-09-10',2,NULL,NULL),(315011,'新哥斯拉','シン・ゴジラ','东京湾水隧轰然巨响、大水灌入，突发原因不明的崩塌事件。首相官邸召集阁僚开紧急会议，大多认为“原因是地震、海底火山”，看过网络目击影片的内阁官房副长官矢口兰堂（长谷川博己）指出海中可能栖息巨大生物，内阁总理大臣辅佐官赤坂秀树（竹野内丰）及周围的人对矢口意见皆付之一笑。其后，在海上巨大不明生物现身，惊慌失措的政府相关人员收集情报追踪之际，巨大生物登陆镰仓沿路破坏建物前进，日本政府因应设置紧急对策本部下达防卫出动命令，美国国务院则派遣总统特使加代子·安·派特森（石原聪美）关切，面临未曾有的威胁，不仅日本、世界也注视其动向。自卫队与称作“哥斯拉”的巨大生物在川崎市展开大决战，究竟人类是否抵御得了这远远超出所知的“完全生物”。','A god incarnate. A city doomed.',15000000,77000000,9.476999,6.5,143,120,'2016-07-29','ja',NULL,2.9536820425253865,3,'2026-09-10',2,NULL,NULL),(315664,'跑调天后','Florence Foster Jenkins','Florence Foster Jenkins，为20世纪早期美国女高音歌唱家，以糟糕的唱功，然而绝佳的娱乐才能，得到了观众的欢迎。Jenkins非常自信，将自己与当时著名的女高音家Frieda Hempel和Luisa Tetrazzini相媲美，毫不介意表演时台下观众传出的阵阵嘲笑。她对自己的表演场地有严格的选择，通常是在纽约市的丽嘉宴会厅。演唱会的听众也仅限于自己忠诚的会员和一些邀请嘉宾，甚至自己决定门票的所有人。76岁时，Jenkins要求在卡内基音乐厅进行一次公演，人们很期待这次表演，因此门票早早地售完，然而，Florence Foster Jenkins却在一个月后去世了。','People may say I couldn\'t sing, but no one can say I didn\'t sing',29000000,48902953,19.237254,6.6,392,110,'2016-05-06','en','/fQVDQjc33MtNsLr1Hxg0V9rRPrE.jpg',3.2260768416719303,3,'2026-09-10',2,NULL,NULL),(316002,'意外的爱情','Accidental Love','贝尔在片中将饰演Sammy Joyce，一位不善于社交的小城镇酒店接待员。Sammy的运气很差，一位粗心的工人把一根钉子射进了她的脑子，压迫了她的神经，让她一直感受到强烈的性欲。没有社保的Sammy来到华盛顿治疗她的怪病。她遇见了放荡的国会议员（吉伦哈尔），把她的性欲当成是一种资本从而获得某些政治利益，也让Sammy开始了自己的政治生涯。','Sometimes you nail love. Sometimes it nails you.',26000000,0,5.644844,3.9,95,100,'2015-02-10','en','/znPsDmQVKW0BuBnaErIAPo49X3i.jpg',2.761230687518306,3,'2026-09-10',2,NULL,NULL),(316152,'琼斯的自由国度','Free State of Jones','纽顿·奈特（马修·麦康纳饰）为了保护那些富有的南方种植园主的蓄奴权而拼死战斗，但那些园主们却在想方设法帮自己的孩子逃脱兵役，看透了的纽顿逃离了军队，开始筹建一个名为自由国度的多种族、是个跨地区的国家。被迫与妻子赛琳娜（凯丽·拉塞尔饰）分离之后，纽顿最初向一群由摩西（马赫莎拉哈什巴兹·阿里饰）领导逃亡奴隶寻求了庇护，跟他们一起住在沼泽当中。\r 蕾切尔（古古·玛芭塔劳饰）也是一个奴隶，一次偶然的机会，她给这一群人带来了补给和一些食物。后来，这群穷苦劳动者和曾经当过奴隶的人们组成的势力发展壮大，人数众多，武器也有不少，他们终于开始反抗那些一直掠夺他们的农作物和牲畜的南方同盟军。他们的抵抗最终招来了打击和报复。纽顿和他的伙伴们努力想要开辟一片乐土，可以让农民们安居乐业，他们在建造这样一个国度的过程中所遇到的种种困难和挣扎','Based on the incredible true story.',50000000,25035950,21.589393,6.6,428,139,'2016-06-24','en','/wCWswU04VBGqQLn3HtMOeRAvAuX.jpg',3.253441239679334,3,'2026-09-10',2,NULL,NULL),(316727,'人类清除计划3','The Purge: Election Year','一年一度的国定杀戮日即将到来，与此同时，美国总统大选也到了如火如荼的阶段，一方是创立并推行国定杀戮日的NFFA的代言人艾德维奇•欧文斯，一方则是曾被这个可怕的杀戮夺走家人的女参议员查理·罗恩（伊丽莎白·米切尔 Elizabeth Mitchell 饰）。查理不惜一切代价要将国定杀戮日废止，因此成为了NFFA的眼中钉，对方策划在杀戮之夜夺走她的性命。刚强的查理坚持当晚待在家中，而她的安全主管里奥（弗兰克·格里罗 Frank Grillo 饰）则打起十二分的精神准备应对四面八方的对手。由于内部出现奸细，里奥只能被迫带着罗恩逃离住所，在这一路上，他们得到一些支持者的救助，而对手也决不肯放过这个千载难逢的机会。','Keep America great',10000000,118587880,53.727146,6.1,1306,105,'2016-06-29','en','/w5xuVWh9gs5F4t7N66kX2GFfc2b.jpg',3.5122154556969787,3,'2026-09-10',2,NULL,NULL),(317930,'Compadres','Compadres','A disgruntled Mexican cop is forced to work with a teenage hacker to hunt down the criminals who killed his wife, and dismantle their operation.',NULL,3000000,0,1.569246,5.2,17,101,'2016-03-31','es','/w3NXqlE28A2melukcBQTRsOdhUR.jpg',2.458759328199604,3,'2026-09-10',2,NULL,NULL),(318040,'Bizarre','Bizarre','Maurice, a reticent young homeless man, somehow manages to get by in Brooklyn; he spends his nights in parked cars until he finds himself at Bizarre, an underground club renowned for its burlesque shows. Maurice is fascinated by the club’s playful revues celebrating self-determined sexuality and creative otherness, and the two female club owners both adore him. He soon becomes a part of their self-selected family, and begins to bond with introverted Luka. But Maurice turns his back on Luka’s growing affection. Running away from his true emotions he drifts aimlessly through the city. He tries to find his feet at a boxing club, where he meets Charlie. Unable to withstand the pressure of his repressed feelings, Maurice unleashes a mounting foment of emotions, pervaded by tenderness and menace.',NULL,0,0,0.583446,6.2,11,99,'2015-02-07','en','/pbuL9CcBAQMFgXboOV1iFOCYd4B.jpg',2.3750957353435536,3,'2026-09-10',2,NULL,NULL),(318846,'大空头','The Big Short','当四个局外人看到了大银行、媒体和政府都视而不见的东西——全球经济即将崩溃时，他们萌生了一个想法：大空头。他们大胆的投资将他们引入现代银行业的阴暗角落，在那里，他们必须对每一个人、每一件事都提出质疑。[派拉蒙影业]','This is a true story.',28000000,133346506,57.518472,7.3,2607,130,'2015-12-11','en','/scVEaJEwP8zUix8vgmMoJJ9Nq0w.jpg',3.9517423246457413,3,'2026-09-10',2,NULL,NULL),(318850,'耶稣基督：走出埃及','The Young Messiah','讲述了7岁的耶稣和他的家人离开埃及回到拿撒勒的故事，耶稣发现了自己出生的真相、以及自己的使命。','Before he was the savior, he was a child.',18500000,6490401,1.884558,6.4,30,120,'2016-03-10','en','/bErwO5QhOJKfXJVi4cgKr7RLTP0.jpg',2.58717830386876,3,'2026-09-10',2,NULL,NULL),(319069,'Censored Voices','Censored Voices','The 1967 \'Six-Day\' war ended with Israel\'s decisive victory; conquering Jerusalem, Gaza, Sinai and the West Bank. It is a war portrayed, to this day, as a righteous undertaking - a radiant emblem of Jewish pride. One week after the war, a group of young kibbutzniks, led by renowned author Amos Oz, recorded intimate conversations with soldiers returning from the battlefield. The recording revealed an honest look at the moment Israel turned from David to Goliath. The Israeli army censored the recordings, allowing the kibbutzniks to publish only a fragment of the conversations. \'Censored Voices\' reveals the original recordings for the first time.','The Six-Day War, Uncut.',0,0,0.59458,5.1,8,84,'2015-01-24','en','/jkAfM4NETuEguSIWteDMgobh4B0.jpg',2.3089617250258323,3,'2026-09-10',2,NULL,NULL),(319888,'飞鹰艾迪','Eddie the Eagle','详述了英国历史上最著名的跳台滑雪运动员，有“飞鹰艾迪”之称的迈克尔.爱德华兹激励人心的真实事迹。影片刻画了艾迪在运动赛场上永不言弃的宝贵精神，赞扬了他在面对巨大困难和挑战时所表现的非凡毅力和乐观精神。影片的男主人公“飞鹰”艾迪，由曾在《王牌特工：特工学院》中有杰出表现的新晋英国小生塔伦·埃格顿饰演，而好莱坞著名影星“金刚狼”休·杰克曼也重磅加盟，饰演艾迪的教练，为帮他圆梦卡尔加里冬奥会，对他进行严格训练。冬奥会上艾迪有趣又颇具历史性的展示让他名声鹊起，成为记者关注的焦点人物，并俘获了全世界观众的心。','Win or lose, always aim high',23000000,46152800,29.365851,7.2,661,106,'2016-02-26','en','/yyiHRXpnRwKAJSKvKcTOCYI3Fl7.jpg',3.466481744268753,3,'2026-09-10',2,NULL,NULL),(319910,'受伤的马','Broken Horses','故事讲述了兄弟间的羁绊，并诠释了忠诚的含义，描绘了美国和墨西哥边境的帮派暴力生活。年轻的Buddy Heckum在射击训练场亲眼目睹了身为警察的父亲被黑帮成员暗杀，父亲就躺在他的脚边，此时他的心中已经燃起复仇的火焰，之后不久就手刃了仇人。失去父亲的Buddy Heckum不仅没有消沉下去，还主动担负起照顾年幼的弟弟Jacob Heckum的责任，让弟弟可以安心学习小提琴的演奏。成年后的弟弟Jacob Heckum（安东·尤金 饰）回到了出生的小镇，也再次见到了他的哥哥Buddy Heckum（克里斯·马奎特 饰），可是原本他熟悉的生活早已面目全非……',NULL,0,0,4.289676,5,10,101,'2015-03-15','en','/y75BF30IZX2VcU31YAkEdmjhDy6.jpg',2.3597570314777663,3,'2026-09-10',2,NULL,NULL),(320146,'虚拟性成瘾','Creative Control','未来的布鲁克林，年轻广告创意监制戴维经常在工作之余去喝酒嗑药泡吧，他与崇尚瑜珈的女友渐行渐远，还暗恋麻吉的性感女友苏菲并介绍苏菲去他的广告公司。戴维的广告公司接了一个广告订单，为虚拟现实眼镜「AUGMENTA」策划一个推销案。戴维用这个「AUGMENTA」做了一個「虚拟苏菲」，「虚拟苏菲」跃然眼前，性感胴体或是诱人对话，任由操控。戴维暂时解决心底的「瘾」，但愈来愈大的欲望加上嗑药，让他戴上眼镜却再也看不清真实……','A story about virtually everything',1000000,0,1.50211,5.4,25,97,'2016-03-11','en','/y8toiQT0xb6mLWT84xVhUNXICdg.jpg',2.537606539747195,3,'2026-09-10',2,NULL,NULL),(320435,'UnDivided','UnDivided','UnDivided documents the true story of how a suburban church unites with at-risk Roosevelt High School to create a beautiful transformation for students, the school and the volunteers serving it.',NULL,0,0,0.010607,0,0,0,'2013-02-01','en',NULL,1.8338066137963767,3,'2026-09-10',2,NULL,NULL),(321258,'灵偶契约','The Boy','在英国郊外某个安静的角落，耸立着豪华考究的别墅。这幢别墅属于年迈的希夏尔先生 和希夏尔太太 夫妇。这一天，别墅迎来了一个年轻女孩。女孩名叫格丽塔，因某些原因她希望逃离之前的生活，同时也受雇于希夏尔完成一项奇怪的工作。希夏尔夫妇即将外出度假，他们要求格丽塔在此期间照顾他们的“儿子”布拉姆斯——一个男孩模样的人偶。格丽塔起初感到好笑，但看到夫妇俩一本正经的模样也便尽可能控制自己的好奇心。夫妇为格丽塔规定了不可逾越的条款，但是当他们离开后，格丽塔却最终逾越了戒条。令她难以置信的是，布拉姆斯仿佛真的拥有鲜活的生命……','Every child needs to feel loved.',10000000,64188367,38.179483,5.8,1102,97,'2016-01-22','en','/96ytUBuNR0e4s1p62LA4zkOoeCd.jpg',3.385818452229786,3,'2026-09-10',2,NULL,NULL),(321697,'史蒂夫·乔布斯','Steve Jobs','影片设定在三场标志性产品发布会的幕后，以1998年iMac的发布为终点，带领观众走进数字革命的幕后，描绘这位处于革命核心的天才人物的亲密肖像。[环球影业]','Can a great man be a good man?',30000000,34441873,53.670525,6.8,1573,122,'2015-10-09','en','/ljiRO29Y9khEERRqMluptUYunJ9.jpg',3.6958260508043583,3,'2026-09-10',2,NULL,NULL),(321741,'震荡效应','Concussion','改编自真人真事，由《关键目击》彼得蓝斯曼编导，《当幸福来敲门》威尔史密斯主演。美国脑­神经学权威班奈特医生，打算将慢性创伤性脑病变­真相公诸于世，却遭受到美式足球联盟的干涉，迫使他的事业面临强大危机。','Even Legends Need a Hero',35000000,50363790,35.120736,7,823,123,'2015-11-12','en','/tENh6aeNh9yDgOZ9p4YbaH1bBA0.jpg',3.5131913054411243,3,'2026-09-10',2,NULL,NULL),(322194,'Subconscious','Subconscious','An investigation into a retired WWII sub plunges a research team into a supernatural journey across the dark abyss of time - with history hanging in the balance.',NULL,0,0,0.397323,3.4,4,110,'2015-03-10','en','/673Kdb6ogKGM0unP9piVK74jpKf.jpg',2.179730666130983,3,'2026-09-10',2,NULL,NULL),(322443,'狭路','The Timber','在狂野的西部，两兄弟踏上征途去舍命换取赏金来拯救他们家。但他们渐渐发现任务远不止这么简单……','Fortunes will be made, lives will be lost.',0,0,0.803761,4.1,15,81,'2015-02-27','de','/kV0jEsELVEhqIU9MPyidKaHpvh9.jpg',2.4254959658941453,3,'2026-09-10',2,NULL,NULL),(322745,'城市的十五个片刻','Counting','杰姆·科恩最新的电影是在15章个人，小品纪录片。导演组成的图像，声音和音乐具有显着的强度，将它们合并为通过我们的世界大都市催眠突袭：纽约，莫斯科，圣彼得堡，伊斯坦布尔，波尔图和城市意欲仍下落不明。时间的流逝，在同一时间仍然有效。相机是像吸引和捕获短暂的磁体：在窗口闪烁灯，彩旗和塑料袋在风中飘扬。在经过的地方都受欢迎的和未知的和的人，日常生活中的重大发现，一个温柔的现实衡量，配音的片段快照。这是生命本身，导演为我们展示。杰姆·科恩是在一次漫游者和街头智慧工人，他的电影他的脚步存档 - 储藏室充满了梦幻般的回忆，包括克里斯标记的聊天栖架的。各种形状和大小的猫出现在框架连连。计数就像把一个星期天穿行的空间和时间的空隙，因为感人，因为它是神奇的。 2015年柏林',NULL,50000,0,0.293587,8.3,3,111,'2015-02-09','en','/lQzBtr4ganEcNiXxJMnWil1zibr.jpg',2.1381745023814203,3,'2026-09-10',2,NULL,NULL),(323270,'The Horror Network Vol. 1','The Horror Network Vol. 1','Serial killers, ghostly phone calls, inner demons, otherworld monsters and creepy stalkers collide in this frightening anthology. Six of horror\'s most promising new directing talents join forces to pay homage to classic horror in the tradition of \"Creepshow\", \"Tales From the Crypt\", \"Tales From the Darkside\", and \"Trilogy of Terror,\" and weave an unforgettable, disturbing tapestry of terror.',NULL,0,0,0.392658,5,2,0,'2015-10-27','en','/lQmgIgxNMCdeDbzXv7V8I55Oa6m.jpg',2.0723259873493114,3,'2026-09-10',2,NULL,NULL),(323271,'未受污染','Unsullied','When car trouble strands track star Reagan Farrow in the Florida boondocks, she accepts an offer of help from a pair of charming strangers only to find herself trapped in a brutal backwoods nightmare. Held captive in an isolated cabin, Reagan manages to escape and take refuge in the forest. Relentlessly pursued by the savage sociopaths who kidnapped her, Reagan will need all of her inner strength and resourcefulness in order to survive in this gripping thriller.','The Hunt Is On',0,0,0.06124,3,1,93,'2015-08-28','en','/3cby5ym34M2N1kNvz4bIezFYJFb.jpg',1.9831571145015767,3,'2026-09-10',2,NULL,NULL),(323675,'佐州自救兄弟2','Ride Along 2','故事发生在第一部的一年后，菜鸟警察本（凯文·哈特 Kevin Hart 饰）与他的大舅子、老鸟警官詹姆斯（艾斯·库珀 Ice Cube 饰）再度联手，从亚特兰大前往迈阿密侦破一桩毒品大案。案件能否顺利侦破？本的婚礼能否如期举行？','The brothers-in-law are back',40000000,124827316,25.136082,6.1,555,102,'2016-01-14','en','/qKvVUHdiwqkXdlRsW4fHO7SAZef.jpg',3.2620999035875866,3,'2026-09-10',2,NULL,NULL),(323676,'老板','The Boss','由于童年缺失亲生父母的关爱，从小在寄养家庭长大的米歇尔养成了“独立”“自负”“不相信他人”的个性，面对其他人，都是一副“老娘最牛”的姿态，对合作伙伴、下属皆是一张高傲的嘴脸，所以当她因内幕交易被判入狱8个月后，没有人站出来为她说话，甚至在出狱后，也没有人愿意伸出援手。然而，曾经被她无视的助理、单身母亲克莱尔（克里斯汀·贝尔 饰）却成为她唯一的救命稻草。米歇尔利用克莱尔的同情心，在对方的家中落脚，并重新摆出了曾经的老板姿态。在一次被强迫去替克莱尔开家长会后，米歇尔在学校中突然发现了“商机”——带领一群乳臭未干的奇葩少女卖起了克莱尔制作的布朗尼蛋糕，并将所取得的一部分利润用作这些少女的大学基金。随着生意越做越火，米歇尔引起了前任男友兼现任敌手雷诺（彼特·丁拉基 饰）的注意，为了复仇，雷诺从中作梗挑拨克莱尔与米歇尔的关系，这让米歇尔极度不满，又变回了曾经那个自私、偏执的个性。在经历了一系列事件后，米歇尔终于认识到自己对待事业、朋友时的错误，于是她开始计划改变自己。','Watch your assets',29000000,78636257,20.55509,5.5,431,91,'2016-04-07','en','/8SqIjYVb3KrxPJMcM6FwZ7qZCN1.jpg',3.1301579191036586,3,'2026-09-10',2,NULL,NULL),(323677,'黑色闪电','Race','这部传记电影讲述了美国黑人田径明星杰西·欧文斯传奇的一生。杰西·欧文斯是世界体育史和世界田径史上一个伟大而特殊的人物，他在1936年柏林奥运会上一人独得男子100米、200米、跳远和4×100米接力4枚金牌，不仅创下了前无古人的奇迹，还对打破希特勒纳粹的“种族歧视”、奠定黑人运动员的历史地位起到了石破天惊的作用，因此成为体坛佳话。','The incredible true story of gold medal champion Jesse Owens',5000000,24804129,22.9951,7.1,478,134,'2016-02-19','en','/ubbNizkhjEYw06XB7b0YMgsHXG1.jpg',3.3438399106631804,3,'2026-09-10',2,NULL,NULL),(323967,'Walter','Walter','A ticket-taker at the local cinema believes he is the son of God. He has agreed to decide the eternal fate of everyone he comes in to contact with.','Heaven or hell. It\'s in his hands.',700000,0,2.659006,5.3,26,87,'2015-03-13','en','/cwwL3zfVNpVsLrRr35U4QQVXmeG.jpg',2.5471364667076957,3,'2026-09-10',2,NULL,NULL),(324322,'They Will Have to Kill Us First','They Will Have to Kill Us First','In 2012, jihadists took control of northern Mali. They imposed one of the strictest interpretations of sharia law in history. On August 12th they banned music - radio stations destroyed, instruments burned and musicians facing torture, even death. Overnight, Mali’s most revered members of society – the musicians – were forced into hiding or exile. This film follows Mali’s musicians as they fight to keep music alive in their country. We witness fierce battles between the army and the jihadists, capture life over borders at refugee camps where money and hope are scarce, follow perilous journeys home to war ravaged cities, and for one band, Songhoy Blues, their path to international stardom.',NULL,522360,0,0.071349,5,1,105,'2015-10-13','fr','/7xOKJs1Q1M0KsrHgpfiFu9QcIbe.jpg',1.984002765102693,3,'2026-09-10',2,NULL,NULL),(324352,'Anderson\'s Cross','Anderson\'s Cross','Nick Anderson, Kevin Daniels, and Tracey Green do everything together. They are the best of friends, and yet they couldn\'t be more different. Neighbors from adolescence, they finish each other\'s thoughts and sentences, joys and pains, happiness and tears. Using Nick\'s house as their own members only clubhouse, they escape into their own world of contentment. Yet the inevitable intrusion of others tests their stability in ways never imagined.','Sometimes the boy next door is more than the boy next door...',300000,0,0.006323,0,0,98,'2010-05-20','en','/2j90os0c2HJuIjWXxMg9vMvOliw.jpg',1.833796828297359,3,'2026-09-10',2,NULL,NULL),(324668,'谍影重重5','Jason Bourne','在后斯诺登时代，中情局系统被黑客入侵，多项特工计划可能泄露。与此同时，中情局还发现了杰森·伯恩（马特·达蒙 饰）和好搭档尼基（朱丽娅·斯蒂尔斯 饰）的踪迹。年轻的网络专家海瑟·李（艾丽西亚·维坎德饰）自告奋勇追踪杰森·伯恩，而杰森·伯恩也在寻找着关于自己身世的惊天黑幕。中情局高官罗伯特·杜威（汤米·李·琼斯饰）是知晓一切幕后秘密的人。罗伯特·杜威、海瑟·李和杰森·伯恩之间的角力悬念，不到最后一刻，就无法了解真正的结局。','You know his name',120000000,415484914,62.641286,5.9,2341,123,'2016-07-27','en','/ccTy6uy4zJperTnxBm22tZEfXMP.jpg',3.6130151628738614,3,'2026-09-10',2,NULL,NULL),(325123,'Teeth and Blood','Teeth and Blood','A beautiful diva is murdered on the set of horror director Vincent Augustine\'s latest film \"Chapel Blood.\" Somewhere between the crime scene and the coroner\'s van, the body mysteriously disappears. Meanwhile, the city\'s supply of donated blood is being dangerously depleted. Suspecting a connection between the events, detectives Mike Hung and Sasha Colfax go undercover at the studio to investigate. Their attempt to crack the case quickly turns into a desperate battle for survival when they uncover an age-old war between rival vampire covens that threatens to consume humanity in a final, grisly assault of Teeth and Blood!',NULL,0,0,0.055325,3,1,96,'2015-03-10','en','/str9ckfPjtAuSCpBgmxxEeKwy1N.jpg',1.9831436034776062,3,'2026-09-10',2,NULL,NULL),(325133,'邻居大战2：姐妹会崛起','Neighbors 2: Sorority Rising','罗根与拜恩饰演一对拥有新生女儿的年轻夫妻，将面对的新邻居是一群大学姐妹会的女学生。在几轮交锋之后，小夫妻感到力不从心，于是他们请来了外援，这就是在第一部中与他们从敌到友——由恶魔兄弟会会长“从良”为A&amp;F花样男模的扎克·埃夫隆。','New neighbors.',35000000,108758521,50.179171,5.6,1462,91,'2016-05-04','en','/k2HNn1UaUR69ogcjTZ0QdQz71qo.jpg',3.4283817897008473,3,'2026-09-10',2,NULL,NULL),(325140,'Hum To Mohabbat Karega','Hum To Mohabbat Karega','Raju, a waiter, is in love with the famous TV reporter Greeta Kapoor. After a man is murdered, Kapoor shows up at Raju\'s door to ask him some questions - it turns out that Raju served the dead man his last supper, and the authorities hope that he might be able to help them. Raju lies and says that he was an eye witness, in order to spend more time with Kapoor. He gives the police a false description of the killer, but it matches his best friend Kutti, so soon Kutti is wanted by the police, and the Mafia, who is responsible for the killing, is after Raju.',NULL,0,0,0.001186,0,0,0,'2000-05-26','en','/dCzznqwqDtdwc0zqUBTDY3BMYae.jpg',1.8337850943784855,3,'2026-09-10',2,NULL,NULL),(325173,'近距离','Close Range','一个士兵与一个腐败警长不懈的斗争。他的副官，和一个危险的贩毒集团勾结，开始抢夺自己的妹妹和她的小女儿。','Colton MacReady...is coming home.',0,0,5.485217,4.9,54,80,'2015-12-11','en','/pzE3dfnmiNqjqLygS4HbMADFKa8.jpg',2.6913863399077766,3,'2026-09-10',2,NULL,NULL),(325373,'两个爱人和一只熊','Two Lovers and a Bear','故事发生在北极附近一个前不着村后不着店的小镇，两个年轻人在这里相遇并坠入爱河。',NULL,0,0,3.139294,6.8,27,96,'2016-10-02','en','/q8anLL9m6ON7kTJ4Pbcuofls4gQ.jpg',2.571902634479334,3,'2026-09-10',2,NULL,NULL),(325579,'Diamond Ruff','Diamond Ruff','Action - Orphan, con artist, crime boss and millionaire, Diamond Ruff has seen it all. In prison for a murder he did not commit, he meets the Reverend Trek Woods, who overwhelms him with kindness, character and faith in god. Falling in love with April, a young woman with terminal illness, Ruff is again challenged to grow and change. Will he be redeemed? There are no easy answers. -  Felicia Pearson, Fredro Starr, Michael Barra',NULL,0,0,0.165257,2.4,4,0,'2015-01-01','en','/4ETeHJqXwyBQSFfXL9et7cPlkuR.jpg',2.1775622007391786,3,'2026-09-10',2,NULL,NULL),(325789,'潜伏者','The Infiltrator','据美国《综艺》杂志报道，布莱恩·科兰斯顿将出演一部犯罪新片《潜伏者》，在片中再现一名传奇联盟探员的卧底经历。该片由《林肯律师》导演布拉德·福尔曼执导，根据前联邦探员罗伯·梅若同名《 The Infiltrator（潜伏者）》改编。  　　全程参与卧底特工的作者罗伯·梅若在书中 披露侦破美国史上最严重的一宗洗钱案内幕。早些时候，曾被一家美国电影制作公司已买下此书的电影版权。本书作者担任卧底特工多年，暗中调查麦德林犯罪集团洗钱案，并与涉及参与洗钱的银行家和商业人士密切来往，这些人至今在世界各地仍拥有极高的权势。  　　罗伯·梅若乔装是位有钱商人，设法与这些银行家们搭上线，陪同举行私人派对、分享自己的豪华别墅、驾驶劳斯莱斯敞篷车和乘坐私人飞机到世界各地享受奢华生活。通过调查发现，这些人不但参与洗黑钱，还勾结银行家、商人建立起了一个数十亿美元规模的毒品走私帝国。 最后，梅若搜集的证据令40多人锒铛入狱。','The true story of one man against the biggest drug cartel in history.',25000000,15436808,24.672234,6.6,573,127,'2016-07-13','en','/gWD47KuNmHtlvTtYrLGfYHiFrv0.jpg',3.333971960786826,3,'2026-09-10',2,NULL,NULL),(326284,'致命追击','Pound of Flesh','此次加盟《致命追击》，尚格云顿扮演了一名一心想要拯救亲人的铁血硬汉：迪金。为了给弟弟乔治的女儿伊莎贝拉治病，迪金不惜捐献出自己的肾脏。但在准备移植前，迪金却被自己救了的女人安娜陷害，醒来发现已经失去了想要移植的肾脏，经过好友乔治和瓦桑的帮助下，一路进行追查，揭开了一个隐藏已久的秘密。','The black market is about to get bloody',7500000,0,4.943588,5.5,63,104,'2015-05-07','en','/lLxgyIuENnjPLeNIoqwIg3XBwJ1.jpg',2.733534924846443,3,'2026-09-10',2,NULL,NULL),(326576,'Dawn of the Crescent Moon','Dawn of the Crescent Moon','A group of college students travel to a small Texas town to research the Legend of Blood Lake, an obscure folktale forged by events surrounding the horrible massacre of a Comanche village.','The past is present.',0,0,0.049469,2,1,95,'2014-04-05','en','/nXnVHrHR0fmmUugxRLHVlIJLp7z.jpg',1.9827189473933264,3,'2026-09-10',2,NULL,NULL),(327833,'人皮交易','Skin Trade','人贩集团的触角遍布东南亚、欧洲、美国等地，将无知少女从欠发达地区拐走并迫使她们出卖肉体。美国警察尼克·卡西迪（道夫·龙格尔扮演），在家人遭到欧洲黑帮杀害后，决定为他们复仇，一路追杀到泰国。联手泰国警察（托尼·贾扮演）清剿并复仇该黑帮组织，但同时，他的家人、爱人与自己也陷入巨大危机，他们能否联手捣毁这个人贩集团呢...','Two Cops. One Mission. No Mercy.',9000000,0,6.677926,5.6,61,96,'2014-11-07','en','/wKSPLmjcjErWsVSlUOJDHJIc53X.jpg',2.7333490230059807,3,'2026-09-10',2,NULL,NULL),(328111,'爱宠大机密','The Secret Life of Pets','讲述了在纽约一幢热闹的公寓大楼里，有一群宠物，每天主人出门后、回家前这里就变成了它们的乐园：有的和其他宠物一起出去玩；有的聚在一起交流主人的糗事；还有的在不停捯饬自己的外貌，使自己看上去更可爱以便从主人那里要来更多的零食……总之，宠物们每天的“朝九晚五”是他们一天中最自由、最惬意的时光。在这群宠物中，有一只小猎犬是当仁不让的领袖，他叫麦克斯（Max），机智可爱，自认为是女主人生活的中心——直到她从外带回家一只懒散、没有家教的杂种狗“公爵”（Duke）。麦克斯和公爵人生观价值观都不一样，自然很难和平共处。但当它们一起流落纽约街头后，两人又必须抛弃分歧、共同阻止一只被主人抛弃的宠物兔“雪球”（Snowball）——后者为了报复人类，准备组织一支遭弃宠物大军在晚饭前向人类发起总攻……','Think this is what they do all day?',75000000,875958308,31.482872,5.9,3462,87,'2016-06-18','en','/2BorMD4ALSHSenAuLzmVp31MOlI.jpg',3.6227267324605688,3,'2026-09-10',2,NULL,NULL),(328307,'Rise of the Entrepreneur: The Search for a Better Way','Rise of the Entrepreneur: The Search for a Better Way','The world is changing faster than ever. Technology is accelerating, job security is declining and income inequality is increasing. People are overworked and underpaid. With less time and freedom, people are left wondering if there is a better way. Our changing economy has led to the rise of the entrepreneur. The fastest, most dependable and controllable way to become wealthy is to own your own business. This documentary gathers today\'s best experts and thought leaders to forever change how you view work and wealth. Featuring experts Jordan Adler, John Assaraf, Kody Bateman, Chris Brogan, Richard Bliss Brooke, Ali Brown, Les Brown, Jack Canfield, Harry S. Dent, Jr., Dr. Linda Ferrell, Dr. OC Ferrell, Mark Victor Hansen, Kevin Harrington, Kim Kiyosaki, Robert Kiyosaki, Joseph N. Mariano, Dr. Ivan Misner, Paul Zane Pilzer, Bob Proctor, Susan Sly, Loren Slocum, Kevin Thompson, Brian Tracy, Eric Worre and Sandra Yancey.',NULL,0,0,0.052942,8,1,0,'2014-11-20','en','/zd40Et14AUiOCM9dOk9T7YD88fh.jpg',1.985194559376269,3,'2026-09-10',2,NULL,NULL),(328387,'玩命直播','Nerve','一款名为Nerve的真人大冒险直播游戏正席卷纽约城，游戏参与者有两个不同的选择，要么当“观看者”，要么当“玩家”，观看者付费决定玩家去挑战各种冒险游戏。  　　高中女生Vee（艾玛·罗伯茨 Emma Roberts 饰）是个平凡无奇的乖乖女，平日最大的乐趣就是“窥视”学校里的男神JP。她的好友Sydney正沉迷于这个直播游戏里，为了吸引观看者而作出种种大胆行为。受其影响，平日习惯于当旁观者的Vee，也加入了这个直播游戏，成为了“玩家”。她的第一项冒险，就是亲吻一个陌生人。挑战成功后，她才发现这个陌生人Ian（戴夫·弗兰科 Dave Franco 饰）也是游戏玩家之一。他们俩的大冒险直播，从刚开始的好玩刺激，到逐渐走向失控。他们必须携手逃出这场玩命直播……','Are you a watcher or a player?',20000000,83707310,62.933899,7.1,2181,96,'2016-07-27','en','/qmSpHC0CSNyNll9WhlwWYuwoQ28.jpg',3.869017155922534,3,'2026-09-10',2,NULL,NULL),(328425,'致命礼物','The Gift','西蒙（杰森·贝特曼 Jason Bateman 饰）与萝宾（丽贝卡·豪尔 Rebecca Hall 饰）是一对刚搬到加州的年轻夫妇，两人事业有成，生活美满。一天，西蒙无意间与高中同学戈多（乔尔·埃哲顿 Joel Edgerton 饰）重逢。许久不见，戈多依然如西蒙记忆中一样古怪，但萝宾却觉得戈多温和而有风度，夫妻俩的感情因戈多的出现而产生了分歧，周遭也开始发生一连串的怪事。在萝宾锲而不舍地追查之下，一个隐藏了20多年的可怕秘密逐渐浮出水面……','Not every gift is welcome.',5000000,58978653,27.247013,6.7,1049,108,'2015-07-30','en','/ysox3OMZUjl7MoNJ8O2LbwCSDh9.jpg',3.5106143034371176,3,'2026-09-10',2,NULL,NULL),(329440,'自杀森林','The Forest','生活在美国的莎拉·普斯（娜塔莉·多默尔 Natalie Dormer 饰）近日来心神不宁，她有一个孪生妹妹杰西（娜塔莉•多默尔 Natalie Dormer 饰）在日本担任外教。然而杰西突然下落不明，莎拉拜托山梨县警方帮助搜查，最终得到的结果是杰西可能进入了拥有“自杀胜地”之称的青木原森林自我了断。莎拉绝不认同警方的推测，她不顾男朋友的阻拦，独自踏上前往日本的旅途。她最先来到了妹妹任教的学校，在调查未果之后乘上了前往青木原森林的列车。他人的劝阻无法拦住莎拉的脚步，她朝向森林深处走去。  　　在这一过程中，恐怖诡异的经历交替袭来……','Everyone comes here looking for a way out',10000000,40055439,19.865989,4.8,448,95,'2016-01-07','en','/dmxePayF0uajJnf5QC2wwDnwmOT.jpg',3.055325926197069,3,'2026-09-10',2,NULL,NULL),(329540,'海军陆战队员4：移动标靶','The Marine 4: Moving Target','世界摔角联盟(WWE)明星拳击手米克米兹文再度以美国英雄杰克卡特身份回归，伙拍WWE拳击天后Summer Rae展开连场驳火，展开全新怒火反击！一队全副武装的雇佣兵受聘要追杀一位试图揭露军火商腐败黑幕的重要女线人，杰克受命保护她及阻挡拦路者。目标已被锁定，只有最无所畏惧的人型战争机器才可以阻止这场暗杀阴谋。',NULL,1950000,0,3.696123,5.8,49,90,'2015-04-10','en','/jYFXK03ohNGVcTPzT1LdRg7UyWa.jpg',2.6857991293155297,3,'2026-09-10',2,NULL,NULL),(329833,'超级名模2','Zoolander 2','《超级名模2》的故事发生在第一部的10年之后，故事发生地在罗马。当年的名模Derek（本·斯蒂勒饰演）和Hansel（欧文·威尔逊饰演）已经被人遗忘，他们不得不重新奋斗，上演一段搞笑之旅。','Long time no Z',50000000,55969000,37.253774,4.7,797,100,'2016-02-06','en','/uWZug1vuEJbbC12NvNEKWSdAR27.jpg',3.148462867783411,3,'2026-09-10',2,NULL,NULL),(330770,'进化岛','Évolution','在孤绝的海岛之上，一个只有女人和男孩的隔离群体，高处的医院监视着他们的一举一动。主角尼古拉斯对母亲及其他女人在暗地里在海滩的神秘活动感到不解与好奇，他决定挖掘真相，竟发现这是场恐怖的人体实验……',NULL,0,0,3.300061,6.4,47,81,'2015-09-14','fr','/rDqBkd4pXiQEjgC5CdJBDBXdAyJ.jpg',2.68716677186879,3,'2026-09-10',2,NULL,NULL),(331190,'Captive','Captive','Based on a miraculous true story that drew the attention of the entire nation, is the dramatic, thrilling, and spiritual journey of Ashley Smith and Brian Nichols.  After being taken hostage by Brian in her own apartment, Ashley turns to Rick Warren’s inspirational book, The Purpose Driven Life, for guidance.  In reading from the book, Ashley not only finds purpose in her own life, but helps Brian find a more peaceful resolution to a harrowing situation.','Faith. Redemption. Survival.',2000000,2801508,6.728882,5.6,92,97,'2015-09-17','en','/rKOY6QwmnuZYPaMIvdmZQHjxDLI.jpg',2.816149367562259,3,'2026-09-10',2,NULL,NULL),(331493,'Light from the Darkroom','Light from the Darkroom','Light in the Darkroom is the story of two best friends whose faith is tested when their friends disappear during a religious pilgrimage.',NULL,0,0,0.012942,0,0,0,'2014-01-01','en','/1bWVwd3MIgMhLgAVKEPptzms29i.jpg',1.8338119473958647,3,'2026-09-10',2,NULL,NULL),(331592,'Listening','Listening','For years, we have tried to harness the power of the human mind… and failed. Now, one breakthrough will change everything. Beyond technology. Beyond humanity. Beyond control. David, Ryan, and Jordan hope the telepathy invention will solve all their problems, but the bleeding-edge technology opens a Pandora’s box of new dangers, as the team discovers that when they open their minds, there is nowhere to hide their thoughts.','Hide your thoughts.',0,0,2.414721,5.5,31,100,'2015-09-11','en','/swjFcBEBmP1V7yhPj8h0qJZ2ugQ.jpg',2.5843710628669117,3,'2026-09-10',2,NULL,NULL),(331745,'旋转吧！乒乓球','Top Spin','这部影片从场边一窥竞争激烈的乒乓球运动，三个志在必得的青少年运动员接受严格的培训，希望能够获得参加奥运的资格。',NULL,0,0,0.523122,6.8,6,80,'2014-11-15','en','/68RPd324H8KaxzZvwt0MVSgg9JB.jpg',2.259211033666049,3,'2026-09-10',2,NULL,NULL),(332285,'抗生','Antibirth','在一个充斥着吸毒成瘾的海军陆战队员和绑架传闻的荒凉社区里，一个名叫卢(Lou)的疯疯癫癫的嗑药者在狂欢一晚后醒来，她的症状是一种奇怪的疾病，反复出现幻觉，她努力控制现实，而阴谋的故事却在蔓延。',NULL,35000000,0,3.674294,4.8,40,94,'2016-09-02','en','/p4KSOLDlg1mY4SUbFL3Rd72CoMR.jpg',2.6280691117978745,3,'2026-09-10',2,NULL,NULL),(332411,'我怒了','I Am Wrath','讲述了约翰 特拉沃尔塔扮演的警察遭到了大盗的杀妻报复，愤慨之下，决议本身靠武力为老婆报仇。','I lay my vengeance upon them.',18000000,0,10.144222,4.5,179,92,'2016-04-14','en','/lb4BnQ5dXEJKvapxelw6i9FyL5b.jpg',2.8891589724975137,3,'2026-09-10',2,NULL,NULL),(332567,'鲨滩','The Shallows','南希（布蕾克·莱弗利饰）的母亲刚刚去世，为让自己的心情从郁闷中解脱出来，她只身来到了一处偏远的海岸冲浪，阳光、沙滩和巨浪一切都非常美妙。但是因为意外发生，直到一个大浪扑来，水墙中隐约出现了一只鲨鱼的巨影，遭到攻击后，导致南希被困在了一个礁石上，在她和海岸之间虽然没有太远的距离，但一条大白鲨阻挡了她的求生之路。在这个绝望的关头，她必须通过自己的努力才能找到出路。','What was once in the deep is now in the shallows.',17000000,119100758,60.829621,6.2,1567,86,'2016-06-24','en','/4VbrGmOslW0uwD5RDTkAZkc6kv4.jpg',3.588299973039779,3,'2026-09-10',2,NULL,NULL),(333348,'爱上库珀一家','Love the Coopers','库珀一家四代同堂欢庆圣诞，没想到一家人却被几位不速之客搞得人仰马翻，却也让一家人重新审视家人与节日的意义。','Christmas means comfort, joy and chaos.',17000000,24000000,9.191187,5.4,167,107,'2015-11-12','en','/fPW1BHZhUEViOmDAHFfyLezoQdI.jpg',2.927560557576888,3,'2026-09-10',2,NULL,NULL),(333355,'Star Wars: Clone Wars: Volume 1','Star Wars: Clone Wars (Volume 1)','The Saga continues with the Emmy-winning \"Star Wars: Clone Wars.\" This animated micro-series, directed by Genndy Tartakovsky, captures George Lucas\' vision in a dynamic animated style that is a visual delight for all ages.  \"Star Wars: Clone Wars\" Volume 1 reveals the epic adventures that bridge the story arc between \"Star Wars: Episode II: Attack of the Clones\" and \"Star Wars: Episode III: Revenge of the Sith.\" Follow the valiant Jedi Knights and the Brave soldiers of the Republic\'s clone army as they battle against the droid forces of the Separatists, led by the evil Sith Lord, Count Dooku. Witness the battles that made galactic heroes out of Anakin Skywalker and Obi-Wan Kenobi, and along the way get a first look at the new menace from Episode III, General Grevious.  This is a must-have for any \"Star Wars\" collection.',NULL,0,0,1.881466,8,27,69,'2005-03-21','en',NULL,2.581896345433376,3,'2026-09-10',2,NULL,NULL),(333371,'科洛弗道10号','10 Cloverfield Lane','年轻女子米歇尔（玛丽·伊丽莎白·温斯特德 Mary Elizabeth Winstead 饰）不久前刚和男友发生争吵，她夜晚驾车奔驰在黑暗的公路上，突然遭遇严重车祸昏迷过去。当她再度醒来时，发现自己被绑住手脚，关在一个密闭的空间里。少顷，一个健硕冷峻的男子霍华德（约翰·古德曼 John Goodman 饰）走了进来。军人出身的霍华德声称地球刚刚遭遇可怕的生化危机，地球人几乎灭亡殆尽。他在数年前未雨绸缪修建了这个设备、资源齐全的避难所，只为生存下去。避难所内，除了霍华德、米歇尔外，还有另外一个年轻男子埃米特。米歇尔对霍华德的说辞半信半疑，她坚信自己遭到了变态狂的拘禁。真相究竟为何？威胁无处不在……','Monsters come in many forms.',15000000,108286421,53.698683,6.8,2468,103,'2016-03-10','en','/q8A39vcBDruhvoDTJd6L8a4lnTi.jpg',3.8119242388962578,3,'2026-09-10',2,NULL,NULL);
INSERT INTO `t_video_info` VALUES (334074,'幸存者','Survivor','一位任职于伦敦美国大使馆的签证官，因察觉了一场即将引爆的恐怖事件而让自己身陷险境，她不仅被恐怖份子栽赃，更遭深信的同僚背叛、诬陷。在身陷最毒阴谋与最狠背叛名声败坏的情况下，她被迫展开一场洗刷罪名的大逃亡，而同时还得设法阻止这场危及全美国的恐怖攻击。','His Next Target is Now Hunting Him',20000000,0,33.625477,5.4,404,96,'2015-05-21','en','/ca1tkuCg7kGEmFCQAkZy06akr0L.jpg',3.138049206044701,3,'2026-09-10',2,NULL,NULL),(334527,'犯罪活动','Criminal Activities','几个因葬礼而重聚的老同学被其中一人蛊惑去投资，结果血本无归还欠下黑帮的钱，只能帮黑帮做事来偿还！','Leave the crime to the criminals',7000000,0,6.665164,5.8,110,94,'2015-11-20','en','/3d7sa2efl5I7mI4abLUomNvsru2.jpg',2.859364402960366,3,'2026-09-10',2,NULL,NULL),(334531,'我的美国心','My All American','Freddie Steinmark，一个失败者，在领导他的球队参加冠军赛季后面临着他生命中最棘手的挑战。','Hope never quits',20000000,0,3.102987,6.8,36,118,'2015-11-13','en','/yFVCCtA5f07vyc9IYscmSJpvoPB.jpg',2.634682669913351,3,'2026-09-10',2,NULL,NULL),(335244,'Antarctic Edge: 70° South','Antarctic Edge: 70° South','In 2014, scientists declared West Antarctic ice sheet melt unstoppable, threatening the future of our planet. A group of world-class researchers is in a race to understand climate change in the fastest winter-warming place on earth: the West Antarctic Peninsula. Trekking through dangerous and uncharted landscape, these scientists push the limits of their research and come to terms with the sacrifices necessary to understand this rapidly changing world.',NULL,0,0,0.021392,0,0,72,'2015-04-17','en','/m1TNhDblKnIig8QTWG2mCZxTByZ.jpg',1.8338312488586797,3,'2026-09-10',2,NULL,NULL),(335778,'复活','Risen','不可知论百夫长调查耶稣尸体失踪一案，当他发现耶稣复活，信念遭受考验。','Witness the manhunt that changed the course of human history',20000000,46069568,16.663797,5.7,295,107,'2016-02-19','en','/A4TIawrZRlpuzszheBjmmLy0Zb3.jpg',3.0718118201355766,3,'2026-09-10',2,NULL,NULL),(335866,'生存回圈','Circle','被俘虏的人，面对即将到来的处决，五十个陌生人被迫选择一个值得生活的人。','In here… everything gets you killed.',0,0,6.752141,6,333,87,'2015-10-02','en','/hbIL53MdZFJXsgxXaSOVuApWTs8.jpg',3.1004803709599584,3,'2026-09-10',2,NULL,NULL),(335874,'Childless','Childless','Katherine is a typical teenager. Today\'s her funeral. The four adults in her life have a lot on their mind - and it\'s not all about Katherine either. With a frankness that\'s strikingly disarming as well as frequently self-serving, the grown-ups struggle with being... well... grown-up.',NULL,0,0,0.243853,4.5,2,90,'2015-04-03','en','/A3xnS8K4II7puaFO8Cwc5MubuRU.jpg',2.0715753706841866,3,'2026-09-10',2,NULL,NULL),(336004,'双面劫匪','Heist','沃恩（杰弗里·迪恩·摩根 Jeffrey Dean Morgan 饰）本质上是个善良的男人，可小女儿的重病逼得他不得不成为了一名劫匪。和搭档考克斯（戴夫·巴蒂斯塔 Dave Bautista 饰）一起，两人设计从赌场大亨教皇（罗伯特·德尼罗 Robert De Niro 饰）的手中抢走了300万美元的巨款，哪知道这个看似完美无瑕的计划却在最后一步掉了链子，本应该负责接应他们的那个人临阵脱逃，导致沃恩最终劫持了一辆巴士车开始了逃往之旅。\r 巴士车上搭载着的除了老人和小孩外，还有即将临盆的孕妇，开着这辆车，沃恩不仅要躲避特警克里斯（吉娜·卡拉诺 Gina Carano 饰）和她的手下们的追踪，还要对抗教皇所派出的杀手的猎杀。','Never make a bet you can\'t afford to lose.',8900000,4100000,15.079993,5.6,318,93,'2015-11-13','en','/xkAwx3xBk5bfvkxlM8SgWKBioVD.jpg',3.07339042919716,3,'2026-09-10',2,NULL,NULL),(339408,'一个国家的诞生','The Birth of a Nation','故事描述于1831年，黑人牧师奈特于美国弗吉尼亚洲，率领黑奴解放非裔美国人的自由运动，最终成为引发内战爆发的导火线。','The Untold Story of Nat Turner',8500000,15861566,9.452808,6.5,178,120,'2016-09-09','en','/8ZYKe24hDf5dK1a0i2khF3iZZWv.jpg',3.004623174498678,3,'2026-09-10',2,NULL,NULL),(339984,'天堂奇迹','Miracles from Heaven','一个年轻的女孩儿发现自己罕见的消化系统失调症在一场严重的事故后奇迹般地治愈了。电影改编自Christy Beam的小说《Three Miracles From Heaven 》','How do we explain the impossible?',16000000,77000000,10.248439,6.7,186,117,'2016-03-17','en','/hz9VF1TfaM0D04pYneSXUkNeOZv.jpg',3.0289562396141045,3,'2026-09-10',2,NULL,NULL),(340611,'愤怒','Indignation','改编自菲利普·罗斯2008年出版的同名小说，故事围绕上世纪50年代美国一名犹太裔男青年马科斯·梅思纳的苦闷与彷徨展开。','Based on the novel by Philip Roth.',0,0,5.625989,6.8,69,110,'2016-07-29','en','/lh3tx877oO0z88L8NZRMJrLXu1z.jpg',2.78702585466747,3,'2026-09-10',2,NULL,NULL),(340816,'圣诞节前夜','Christmas Eve','该片讲述了平安夜，一起意外事故导致整片街区停电，六组人被困于电梯中无法与外界联系，他们在这个漫长的夜里所发生的故事。','They\'ll be home for Christmas...if only in their dreams.',0,0,1.985243,6.1,24,95,'2015-12-04','en','/vViH6PCa56kvCTm58gF45uucZWi.jpg',2.5371664299523076,3,'2026-09-10',2,NULL,NULL),(342502,'任务迷走72小时','AWOL-72','一个手握政府机密的AWOL海军成员正被俄国特工和一个危险的杀手追缉','72 Hours On The Clock. Starting Now...',3000000,0,1.141463,2.8,10,79,'2015-08-07','en','/9xnzd7yq9vXrjuQjlRLNZ0kFQYU.jpg',2.3436280163146033,3,'2026-09-10',2,NULL,NULL),(342521,'基努猫','Keanu','故事讲述鲍伯刚和恋情长跑的女友分手，心碎不已时巧遇一只可爱到不行的流浪猫，而鲍伯好友克拉伦斯更被小猫萌翻，两人给小猫取名‘Keanu’，而‘百炼钢化为绕指柔’大男人从此化身猫奴，每天陪猫、爱猫，与猫为伍。某天鲍伯的家被流氓集团闯空门，更惨的是他们的爱猫‘Keanu’竟然被绑架！为了营救爱猫，两人决定混入贩卖毒品的圈子，为方便接近流氓集团......','Kitten, please.',15000000,20566327,18.268009,6,421,94,'2016-04-21','en','/uswOLfIUdDjqSz1x28GR72ffhff.jpg',3.1757929187083227,3,'2026-09-10',2,NULL,NULL),(343409,'Windsor Drive','Windsor Drive','River Miller, a mentally unstable actor haunted by the past, moves to Hollywood to start his life over, only to find his inner demons are inescapable.',NULL,0,0,0.504251,2,1,90,'2015-06-26','en','/xxErk15goAoQQh9TgfTo6W7fCtA.jpg',1.983757758974622,3,'2026-09-10',2,NULL,NULL),(343795,'天堂90分钟','90 Minutes in Heaven','1989年1月的一天，牧师唐·派珀（海登·克里斯滕森 Hayden Christensen 饰）在开车回家的路上遭遇严重车祸，救护人员到达后，便判定他没有生命迹象。没想到一个半小时后， 他却奇迹般地苏醒，并声称在自己失去意识的这段时间，见过天堂的全貌。 在友人的虔诚祈祷和妻子伊娃（凯特·波茨沃斯 Kate Bosworth 饰）的精心照料下，唐终于痊愈并开始新的生活。  　　本片改编自2004年纽约时报同名畅销书，由唐·派珀根据亲身经历所著。','Hope lives',5000000,4842699,3.943706,5.4,40,121,'2015-09-11','en','/e3LKk8UdDyXDkov9k8iP2JJNChi.jpg',2.6380542511364333,3,'2026-09-10',2,NULL,NULL),(344466,'The World Is Mine','Lumea e a mea','Larisa is 16 and lives in a city by the sea. It\'s a small city, where gossip and news spread fast. It\'s a city where your image and influence, \"manelele\", money and power are all that matters. And Larisa… wants it all. And even if she doesn\'t have it, she fights for it. Larisa believes in herself. She knows that she deserves better. She is convinced that it\'s worth doing everything it takes to fulfill her dreams. And for her courage and recklessness - we love her.',NULL,0,0,0.327622,0,0,104,'2015-06-05','ro','/emdjO6Bl71aOirfNh0OcPdyKp5Q.jpg',1.8345307384394902,3,'2026-09-10',2,NULL,NULL),(345003,'疯人院十日','10 Days in a Madhouse','1887年的纽约，一位名叫内莉·布莱的女记者为了在男性主导的新闻界证明自己，接受了调查布莱克威尔岛疯人院的严峻任务。内莉·布莱通过自己装疯卖傻进入疯人院开始了调查。然而，现实的真相却是残酷的，在这里病人毫无自由与权益可言，她们每天遭受着非人的待遇，生命气息也随之越来越稀薄。内莉·布莱在疯人院的十日度日如眠，她是否能够勇敢如初，拯救疯人院的“病人”，让罪恶曝露在阳光下。',NULL,1200000,0,0.489271,4.3,5,111,'2015-11-20','en','/iTvJ5tc6Os90JXza9XfDktYlAOj.jpg',2.220268485156423,3,'2026-09-10',2,NULL,NULL),(345911,'Lights Out','Lights Out','When Rebecca left home, she thought she left her childhood fears behind. Growing up, she was never really sure of what was and wasn’t real when the lights went out…and now her little brother, Martin, is experiencing the same unexplained and terrifying events that had once tested her sanity and threatened her safety. A frightening entity with a mysterious attachment to their mother, Sophie, has reemerged.',NULL,4900000,44107032,48.170508,6.3,1129,81,'2016-07-21','en','/jhiOG0bEerJhtoOjv3QcRW1NoT4.jpg',3.5045232215024154,3,'2026-09-10',2,NULL,NULL),(346081,'ਸਰਦਾਰ ਜੀ','ਸਰਦਾਰ ਜੀ','A ghost hunter uses bottles to capture troublesome spirits.',NULL,0,0,0.296981,9.5,2,0,'2015-06-26','en',NULL,2.0758038931194065,3,'2026-09-10',2,NULL,NULL),(347126,'上帝未死2','God\'s Not Dead 2','本片讲述的是一位女高中教师在课堂上回答了一个学生关于耶稣的提问，这给她带了深深的麻烦，她将为此争取在公共场所讨论耶稣的权力。',NULL,5000000,23507567,6.96858,5.7,72,121,'2016-04-01','en','/xsRYqQJv6t0f4J6DYeYraM9uKKT.jpg',2.7702269987220998,3,'2026-09-10',2,NULL,NULL),(347548,'无处逃生','Containment','没有水。没有电源。没有任何解释。无法逃避。','No water. No power. No explanation. No escape.',0,0,2.122451,5.1,36,77,'2015-07-09','en','/rqS1BAK4BUuFDjXqkFEbneyrzHN.jpg',2.608425048900016,3,'2026-09-10',2,NULL,NULL),(347755,'Wind Walkers','Wind Walkers','A group of friends and family descend into the Everglades swamplands for their annual hunting trip only to discover that they are the ones being hunted. A malevolent entity is tracking them and they begin to realise one of their party may be possessed by something brought home from a tour of duty in the Middle East – a demon of war so horrible and deadly they are unaware of its devilish presence. Or are they facing something even more unspeakable, a legendary Native American curse about to unleash its dreadful legacy of thirsting for colonial revenge by claiming more souls?',NULL,0,0,0.446858,7.5,6,93,'2016-01-28','en','/3G8rw9hY9fvqCtFf1jUzww189yO.jpg',2.2607524469936977,3,'2026-09-10',2,NULL,NULL),(347764,'Goddess of Love','Goddess of Love','Enter into a baroque vortex of madness when an emotionally unstable woman is shattered after tremendous heartbreak. Brian was the love of Venus’ life and the thought of him having an affair with another woman begins her volatile descent into the dark side of psychosexual insanity.','Be Careful Who You Get Close To',0,0,1.273773,6.2,9,96,'2015-08-31','en','/5zrBskQtkPzthObgssDuUTG7hcd.jpg',2.337011907488901,3,'2026-09-10',2,NULL,NULL),(347969,'荒唐六蛟龙','The Ridiculous 6','影片灵感来源于约翰·斯特奇斯指导的著名西部片《豪勇七蛟龙》，但也有人指出该片的预告片皆模仿知名导演昆丁的第八部长片《八恶人》。由Netflix原创出品的电影，将于今年12月11日在Netflix上全面放出。影片讲述素不相识的六位陌生人，只因有着共同父亲而聚集到一起的故事，成为整个西部最为“臭名远扬”的黑帮小队。影片投资高达6600万美金，同时强大的阵容也受到很多关注。影片最早是派拉蒙在2012年的项目，但后改为由华纳兄弟，Netflix和亚当·桑德勒的公司出品，但因华纳兄弟中途退出，在2014年由Netflix全盘接手。Netflix接手后，除去亚当·桑德勒以外加入了其他数位明星，打造了本片全明星的阵容。本片试用极多的美国印第安原住民，从而更为深刻打造出西部片和印第安风的画面感。',NULL,60000000,0,19.694695,4.9,388,119,'2015-12-11','en','/vkB0ww6uyNgVZxG1tUkgDtFHQfA.jpg',3.0473161876206087,3,'2026-09-10',2,NULL,NULL),(351043,'失忆症','Amnesiac','一辆老式轿车载着一男两女行驶在阳光明媚的山间公路上，谁知突如其来的车祸摧毁了看似美好的一切。不知过了多久，男人（韦斯•本特利 Wes Bentley 饰）从昏迷中醒来，此时他躺在一间空旷的大房子中央，窗边摆着医疗设备和仪器。清脆的脚步声响起，美丽而略带神秘感的女人（凯特•波茨沃斯 Kate Bosworth 饰）走到他的面前。男人似乎因车祸而大脑受创，他记不起眼前的女人是谁，而对方则声称是他的妻子。在昏睡的梦中，关于车祸的碎片时时闪现眼前，这令坠入记忆裂缝中的男人愈加无助。越是迷惑，他越是渴望了解这个家，了解他所谓曾深爱而如今却如此陌生的女子。\r 女人那矜持的神秘笑容背后，藏着可怕的秘密……','What he can\'t remember is killing him.',3000000,0,3.077885,4.1,52,90,'2015-08-14','en','/dazYq2JoKpKjtVySA9vmLCv16J.jpg',2.662720853623812,3,'2026-09-10',2,NULL,NULL),(351819,'五十度黑','Fifty Shades of Black','《五十度黑》是由开路影业发行，迈克尔·泰迪斯执导，马龙·韦恩斯、凯莉·霍克 、简·西摩尔领衔主演的喜剧片，该片于2016年1月29日在美国上映。该片讲述了一个专门恶搞萨姆·泰勒·伍德执导的《五十度灰》的故事。','Way shadier than gray.',20000000,21164799,14.947588,4.3,331,92,'2016-01-28','en','/95yLVMbCjrkWe2WqbRNG0mD8f3W.jpg',2.9585996165400785,3,'2026-09-10',2,NULL,NULL),(352978,'连环劫','Chain of Command','種兵詹姆斯·韋伯斯特(Michael潔白“血與骨”|“黑闇騎士”)剛從責任|回家只見證他哥哥的殘酷的殺戮。韋伯斯特立即試圖報復,追捕兇手|但是當他深入到腐敗和謀殺的秘密世界|他發現自己致命的中心深處的陰謀,削減美國政府的城牆。最無情的軍事刺客(Steve Austin“消耗品”|“WWF生”)在他的小道|韋伯斯特必須揭露腐敗高官之前他變成另一個邪惡的陰謀的受害者。','When duty calls, plans change',5000000,0,1.398981,5.3,11,88,'2015-08-30','en','/xUHN0DIWS7fs3bMjg6RktQksK9v.jpg',2.3729419724288574,3,'2026-09-10',2,NULL,NULL),(354110,'遗弃','Forsaken','影片讲述一位内心充满愤恨的枪手约翰·亨利·克莱顿（基弗·萨瑟兰 Kiefer Sutherland 饰）回到故乡试图弥补和他疏远的父亲（唐纳德·萨瑟兰 Donald Sutherland 饰）的关系，力图挣脱多年前因一场意外导致弟弟威廉溺亡的阴影，却陷入了故乡资本家抢夺农民土地的争斗中。一忍再忍，直到资本家手下对约翰·亨利的父亲也就是牧师下黑手，他决定从新拿起武器， 消灭那些恶人！',NULL,11000000,0,11.071522,5.8,101,90,'2015-09-16','en','/fbTpSiqGn6ImqSAyawHlLf7goat.jpg',2.8519520953412205,3,'2026-09-10',2,NULL,NULL),(354624,'越野英雄','Heroes of Dirt','菲·库伯是一位满怀热情的小轮车越野赛车手，生活唯一想要实现的目标就是获得赛车荣誉并且能够获得不菲的经济收入。因为要回自己未付的奖金，他入狱，因此也错失了一场比赛机会。法院要求他在社区义务服务并且要求他无偿训练一个叛逆的少年，蓝·斯宾诺莎。菲带领他一起开始越野冒险的历程，越过高山，领略都市风情。两人一起走过很多地方，在这个过程当中，他们互相也没有偏激，相处变得更加融洽。对菲·库伯来说，蓝早已经不是一个义务，而是一个朋友。蓝秘密的毒品交易的世界也在威胁着菲·库伯的终极理想。一些职业的越野赛车手和对这项运动忠实的拥护者也有着惊艳的特技表演。本片的宗旨已经远远超出了极限越野这一主题，你会在影片中发现一次难忘的旅程能够对生活产生绝大的影响，只有付出代价，你才能到达终点。',NULL,0,0,0.076647,0,0,98,'2015-09-04','en','/zhWwhbUc7v2WxOsX1uj2OGesVEU.jpg',1.8339574621519157,3,'2026-09-10',2,NULL,NULL),(355629,'The Blade of Don Juan','La Navaja De Don Juan','The fate of an arm-wrestling match leads two rival brothers on an adventure through the streets of Lima, Peru. Armed with the spoils of victory, the boys must navigate many obstacles that stand in the way of their goal: a house party on the other side of the tracks and the hope of lost virginity.',NULL,0,0,0.021678,0,0,98,'2013-10-27','en','/sb7lZhOmQN5QrAVx4voyBDuPilM.jpg',1.8338319021389595,3,'2026-09-10',2,NULL,NULL),(356216,'克雷兄弟的崛起','The Rise of the Krays','Follows the early years of two unknown 18 year old amateur boxers who quickly fought their way to becoming the most feared and respected villains in all of London. Told through the eyes of a close friend that survived them, we see them rise to infamy through drugs, sex and murder.','Brutal. Notorious. Legendary',2500000,0,1.759506,4.5,19,110,'2015-08-29','en','/mIvQHEkuwUxqUr3XicrUWzdmrv4.jpg',2.4760184858607714,3,'2026-09-10',2,NULL,NULL),(356483,'反常','Unnatural','知名摄影师马丁带领拍摄团队前往阿拉斯加荒野，希望记录全球暖化下北极熊的生活，一行人寄居在猎人小屋，却听到当地人谣传阿拉斯加出现疯狂杀人熊，马丁下定决心要以摄影镜头捕捉杀人熊的英姿。但他万万没想到，这头杀人熊竟是地下研究机构进行非法实验之下的失败品，面对这头凶性大发的野兽，马丁一行人只能倚靠自己，在渺无人烟的冰天雪地中杀出一条血路……','Some things were never meant to be.',0,0,0.687656,4.3,12,89,'2015-10-16','en','/ykkTUVh6ubdBtHJWOFZIpMTQa8V.jpg',2.3835118359028202,3,'2026-09-10',2,NULL,NULL),(356841,'将杀','Checkmate','六个人精心策划了一场银行抢劫。因为孩子生病变得穷困潦倒的父亲，因为怀孕变得神经兮兮的妻子，修车的混沌小工，看似文弱实则果断的神父，还有隐藏在故事中的两大幕后黑手，外加警方的介入。当这一切都交织在一起的时候，他们中任何人的行为都可以改变这场行动的结果。这到底是巧合,还是他们只是一场更大游戏中的棋子？',NULL,0,0,1.105357,4.2,13,102,'2015-07-03','en','/gG4iRaSrivB7hWtzwkM9UsQ7nma.jpg',2.3993107416323634,3,'2026-09-10',2,NULL,NULL),(356987,'119天：海上历险记','Abandoned','船長約翰與船員吉姆、瑞克和菲爾，航行前往東加王國。途中，船隻遭遇巨浪翻覆，在無法求救的狀況下，四人想盡辦法在海上求生，祈禱能有路過的船隻或飛機發現他們。一天天過去，絕望與恐懼漸漸侵襲，有人陷入恐慌，有人變得脾氣暴躁；但也認知到唯有團結合作，才能在孤立無援的海上生存下去…',NULL,0,0,3.068463,5.8,27,82,'2015-08-30','en','/9iUsETntqb2hCZnM5wwlH0IWZ8Y.jpg',2.5610184778494967,3,'2026-09-10',2,NULL,NULL),(357441,'کراچی سے لاہور','کراچی سے لاہور','A road trip from Karachi to Lahore where 5 friends discover themselves and the country amidst getting to their destination.',NULL,0,0,0.060003,8,1,0,'2015-07-31','en',NULL,1.9852106880897527,3,'2026-09-10',2,NULL,NULL),(357834,'潜伏危情','The Algerian','The Algerian is an international political thriller about the colliding worlds of the Middle East and America. It follows Ali (Ben Youcef) across the world from Algeria to New York, Las Vegas and Los Angeles as it reveals he is a sleeper cell part of an international plot.',NULL,1,0,0.025364,0,0,99,'2015-08-07','en','/AsjTIGBTA5mrFk6lVLYTKs5aJEy.jpg',1.833840321688301,3,'2026-09-10',2,NULL,NULL),(357837,'东区故事','Dancin\': It\'s On!','这是一部年轻题材的音乐剧，暑假里，来自比佛利山庄的年轻女孩儿詹妮弗，去参观其父位于巴拿马城的沙滩酒店。在那里，她与酒店洗碗工肯相爱了。尽管他们的生活背景不一样，但都拥有对舞蹈的热忱，两人搭档参加了第二年度佛罗里达州全国舞蹈大赛。但就在这时，詹妮弗的父亲发现了他们的恋情，并且反对两人在一起。詹妮弗和肯必须克服困难，完成比赛，还要获得詹妮弗父亲的首肯……','Dancin\' Like You\'ve Never Seen Before',0,0,0.186234,4.3,2,89,'2015-10-16','cs','/3FYGf3V8SSPAbQ422rBORCEzkNE.jpg',2.071279470844614,3,'2026-09-10',2,NULL,NULL),(358451,'三城记','三城记','在那个动荡的四、五十年代，爱情绝对得来不易——一件订情信物、一首情歌、一个约定都足以令恋人魂牵梦萦。 身份复杂的警察房道龙（刘青云 饰）遇上具有传奇色彩的女子陈月荣（汤唯 饰），他们的爱情故事横越了三个城市：他们在安徽相爱，在上海分离，彼此仍坚守一个约定——在香港等候重聚。那夜，房道龙在港岛岸边等待接载月容的小船靠岸，却不料小船发生变故，月荣最后能否顺利抵港，与道龙开展新生活？ 影片取材自真实故事，讲述一段父辈的爱情故事。',NULL,0,0,0.753362,6.3,5,130,'2015-08-28','zh','/fRnFmQ8kkTLptnm8cDUXQ1ZYP9o.jpg',2.224962088771316,3,'2026-09-10',2,NULL,NULL),(360188,'螃蟹怪物来袭','Queen Crab','A meteor crashes into a quiet lake in the remote countryside and awakens a centuries-old beast, who tears through a nearby town and its inhabitants, who must fight for their lives and stop this Queen Crab before she can hatch an army of babies.',NULL,75000,0,0.140989,3.3,3,90,'2015-09-29','en','/vMVMlJKf6E2AkImOjweUMGxulIj.jpg',2.131673609959509,3,'2026-09-10',2,NULL,NULL),(360339,'伊甸','Eden','一部现代成人版《蝇王》，讲述一群美国橄榄球队员被困在孤岛上发生的故事。一架飞机失事后落在杳无人烟的太平洋小岛附近。飞机上的乘客都是美国一只橄榄球队的队员。幸存者们没有足够的食物和水，更不知道何时才会被拯救。球队的团队精神逐渐瓦解，人员分裂成对立的两派，一派由独断专横的 Andreas(伊森·派克)领导，另一派是由更具同情心的Slim(内特·派克)领导。','Survive at any cost.',2300000,0,2.713171,5.6,19,97,'2015-10-22','en','/nVtCuhdg1mYjMMFdUKqijgrAWAS.jpg',2.486585585586933,3,'2026-09-10',2,NULL,NULL),(361159,'海豹突击队大战僵尸','Navy Seals vs. Zombies','影片讲述了一队技术高超的海豹突击队发现自己面对的是一群不死族.，致命的感染在新奥尔良爆发了后,海豹突击队必须为了他们的生命和城市而大战一群僵尸。',NULL,0,0,2.394613,3.5,36,97,'2015-10-08','en','/oTvwjUMXjeKxAXY2Cggy5DZweMn.jpg',2.586441653324431,3,'2026-09-10',2,NULL,NULL),(361398,'Theresa Is a Mother','Theresa Is a Mother','Singer/songwriter and single mother Theresa McDermott has finally hit the end of the line in NYC. Unable to make ends meet, she is forced to pack up her life and her 3 girls and move back to the small town and parents she ran from a decade ago. Teresa needs a job, her parents need their space and a family tragedy that was never dealt with from years past needs closure. Old wounds, unattainable dreams and a few other things expose themselves as a fractured family works to become whole and a single mom, a responsible mother.',NULL,0,0,0.036532,0,0,105,'2015-09-25','en',NULL,1.833865831597972,3,'2026-09-10',2,NULL,NULL),(361475,'Departure','Departure','An English mother and her teenage son spend a week preparing the sale of their remote holiday house in the South of France. Fifteen-year-old Elliot struggles with his dawning sexuality and an increasing alienation from his mother, Beatrice. She in turn is confronted by the realisation that her marriage to his father, Philip, has grown loveless and the life she knows is coming to an end. When an enigmatic local teenager, Clément, quietly enters their lives, both mother and son are compelled to confront their desires and, finally, each other.',NULL,0,0,0.42583,7.5,12,109,'2016-05-20','en','/6TZ4H3iOHcpWr9zmClps3jZGhQV.jpg',2.3984722926726256,3,'2026-09-10',2,NULL,NULL),(361505,'Me You and Five Bucks','Me You and Five Bucks','A womanizing yet lovable loser, Charlie, a waiter in his early 30\'s who dreams of selling his book entitled \"7 STEPS OF HEALING THE MALE BROKEN HEART\" finds himself still working in restaurants to survive in the Big Apple. Low on cash, he\'s left with no other choice but to look for a roommate to share his tiny studio. Surprisingly, the first person to answer the ad is his ex and only love of his life Pam, who broke his heart and disappeared without reason and the inspiration behind his book. The Pam he remembered was a youthful spirit with lots of money who is now broke and disheveled. A new story begins and it is up to Charlie to find out why she ran out on him and what\'s happened to her over the past three years. With a potential new love in his life, he must gather the strength to help Pam get back on her feet without rekindling old feelings.','A story about second, second chances',1,0,0.094105,10,2,90,'2015-07-07','en','/ukQf5WWnLerLsMR1bo33HmQ6EUG.jpg',2.075751201175744,3,'2026-09-10',2,NULL,NULL),(362105,'R.L.斯泰恩怪物镇：灵魂密室','R.L. Stine\'s Monsterville: The Cabinet of Souls','Teenage friends must resist the spell of an evil showman staging a house of horrors show in their small town.',NULL,4400000,0,3.898737,6.9,35,85,'2015-09-29','en','/z3qgKFySWDs7vCjMn5gSxGV2fpI.jpg',2.6316686801014533,3,'2026-09-10',2,NULL,NULL),(362765,'The Sound and the Shadow','The Sound and the Shadow','An allergy-ridden, eavesdropping sound engineer and his boisterous new roommate are thrust into a missing girl case when he discovers clues to her disappearance in his neighborhood recordings.','Be careful what you listen for.',0,0,0.072359,0,0,90,'2014-10-19','en','/rSaQxBE2hqV377qTlXYhbicq51l.jpg',1.8339476675161108,3,'2026-09-10',2,NULL,NULL),(364083,'Mi America','Mi America','A hate-crime has been committed in a the small city of Braxton, N.Y. Five migrant laborers have been beaten, shot, then ditched. This will upset the delicate balance of an ethnically diverse populace.',NULL,2100000,3330,0.039007,0,0,126,'2015-10-16','en',NULL,1.8338714849850095,3,'2026-09-10',2,NULL,NULL),(365052,'爱如明镜','The Looking Glass','十三岁的朱莉失去了母亲，她必须要去印第安纳和她的祖母凯伦住在一起。凯伦曾是舞台上的明星，在她阿兹海默症还未完全爆发时，她想把所有知道的一切都教给孙女，这一切的一切会成功么？',NULL,0,0,0.062979,7,1,110,'2015-10-23','en','/2DddsZbo5oBnKveKiA0JmHZMMFv.jpg',1.9848062060314589,3,'2026-09-10',2,NULL,NULL),(365222,'叶问3','葉問3','1959年，叶问（甄子丹饰）与张永成（熊黛林饰）将大儿子叶准送回广东，小儿子叶正继续在香港读书。在与马鲸笙（谭耀文饰）与其老板（泰森饰）所带领的帮派抗争的过程中，叶问带领着自己的弟子保卫了小学，并结识了依靠拉车和在地下赌场斗武为生的张天志（张晋饰），二 人惺惺相惜。然而 此时，自称 “咏春正宗” 的张天志却向叶问公开宣战，要为自己新开的武馆争取名誉。可是张永成突然病危，让叶问不得不肩负起照顾妻儿的责任。面对家庭和武术，叶问究竟会作何选择？他是否会应战张天志，夺回属于他 “咏春正宗” 的头衔？',NULL,36000000,156844753,19.167377,6.5,379,105,'2015-12-19','cn','/bDaeLlpmuvsVuinCG9IyB1cpuH1.jpg',3.2072298292606094,3,'2026-09-10',2,NULL,NULL),(366967,'荷兰杀手','Dutch Kills','一个绝望的前科罪犯为了从一个危险的当地犯罪团伙手下解救她的妹妹，不得不重新组织起旧时的队伍。',NULL,0,0,0.038143,0,0,90,'2015-10-02','en','/gtPYRWywBpy18CrQTBhULz9RA6Q.jpg',1.8338695114389891,3,'2026-09-10',2,NULL,NULL),(367551,'American Hero','American Hero','Melvin, a reluctant hero who is far from super, has been suppressing his telekinetic powers for years with booze, drugs, and women. In the process, he has failed at practically everything, most of all as a parent to his son. After a brush with death, Melvin decides to use his powers for good and clean up the streets of New Orleans with the help of his best friend/definitely-not-a-sidekick, Lucille. For a man who can do the impossible, it might be a fight even he can’t win.','From zero to superhero',0,0,5.023091,5,62,86,'2015-12-11','en','/uYHb5CG90zHp5CDj3dJDP98c77q.jpg',2.7187450718321813,3,'2026-09-10',2,NULL,NULL),(367961,'灵狼传奇','Савва. Сердце воина','一部关于林中小村十岁小子萨瓦的传奇！崇高的白狼曾保护着村子免受敌人入侵。但白狼的突然消失导致残酷的土狼匪帮袭击了村子。萨瓦成功地逃离到森林后，认识了最后一匹白狼安加。安加告诉了萨瓦术师的故事：这位术师魔力无边，他深居山林，有能力帮助萨瓦解放村子，但这座大山却被三头怪邪恶猴王——若比妈妈统领的庞大军团团团围住。克服着沿途重重困难，萨瓦同安加开始了漫漫征程，这征途——危险而又充满神奇，其他旅行者也在途中加入了他们。有普斯科——奇怪的粉红色小毛毛，有自以为是，看着像是法国人，但实际上却是魔法公爵，肩膀上还被迫扛着蚊子之王的法夫尔，还有沼泽部落的南堤公主……  　　每个人都有自己拜访术师的原因。漫漫征途，坚守目标，朋友们面临着重重阻碍，揭开一个个那不为人知的可怕秘密，等待他们的，是一场与万恶猴王若斯妈妈千军万马的输死搏斗……那么，他们能成功到达目的地吗？','You need only wish with all of your heart!',30000000,0,2.625594,6.4,7,85,'2015-11-12','ru',NULL,2.2921453918015273,3,'2026-09-10',2,NULL,NULL),(370464,'面具圣徒','The Masked Saint','The journey of a professional wrestler who becomes a small town pastor and moonlights as a masked vigilante fighting injustice. While facing crises at home and at the church, the Pastor must evade the police and somehow reconcile his violent secret identity with his calling as a pastor.',NULL,0,0,0.909067,2.9,7,111,'2016-01-08','en','/zlT1Tc9hA1Ntye5hr7Gxos9U6U9.jpg',2.278230358395461,3,'2026-09-10',2,NULL,NULL),(370662,'Time to Choose','Time to Choose','Academy Award® winning director Charles Ferguson\'s new film investigates global climate change villains and heroes, and reveals practical solutions to act on.','Climate change for good.',3500000,0,1.618138,0,0,100,'2015-09-04','en','/ak6Bl7WnbzFTuBONiey2BgVGqPn.jpg',1.8374785309348998,3,'2026-09-10',2,NULL,NULL),(370980,'Chiamatemi Francesco - Il Papa della gente','Chiamatemi Francesco - Il Papa della gente',NULL,NULL,15000000,0,0.738646,7.3,12,NULL,'2015-12-03','it','/kD7pwuUxUQiElcOv4cJbt9Bzsye.jpg',2.3982144185436556,3,'2026-09-10',2,NULL,NULL),(371085,'曼哈顿往事','Sharkskin','意大利裁缝迈克·埃斯波西托(Mike Esposito)为黑手党的唐·皮斯(Don Piano)制造西装，陷入了道德困境。',NULL,0,0,0.027801,0,0,0,'2015-01-01','en','/jQHUYbrzHpAA8ZkFLoF6bwNxAyA.jpg',1.8338458882758608,3,'2026-09-10',2,NULL,NULL),(371690,'洛特DR1','Rotor DR1','16岁的男孩基奇(Kitch)身在的城市经历了毁灭性的灾难，过半的人口失踪和死亡。天空上到处是无人机，奇怪的是这些无人机是有自主意识的，它们脱离人类的控制，与人类展开对抗。男主角在寻找父亲的过程中无意间知晓了可以在人体植入某种物质的密集，在一连串遭遇后带着他的无人机加入了一个叫DR1的组织，然后各种开挂用人控无人机打无人机的故事。',NULL,350000,0,0.249561,4.7,3,98,'2015-10-20','en','/iQ8fn12g3OHUldSaUMwW6vbdONv.jpg',2.133644261769764,3,'2026-09-10',2,NULL,NULL),(373314,'Misconduct','Misconduct','An ambitious lawyer finds himself caught in a power struggle between a corrupt pharmaceutical executive and his firm’s senior partner. When the case takes a deadly turn, he must race to uncover the truth before he loses everything.','Ambition can be deadly',11000000,0,10.016909,5.3,149,106,'2016-02-05','en','/2rsJMTF8B3zArOfuaTdPycSZWwf.jpg',2.903310933640996,3,'2026-09-10',2,NULL,NULL),(374461,'丘奇先生','Mr. Church','一个小女孩和她将死的母亲遇到了一位神奇的厨师——丘奇先生，一段美好的故事展开了。','He was the one person she could always count on.',8000000,0,7.828459,7,129,104,'2016-09-16','en','/srAdc3ryF9PxvcvSmehQLSzaQqI.jpg',2.948688118196205,3,'2026-09-10',2,NULL,NULL),(375290,'空中撤离','Airlift','根据真实故事改编，1990年8月，伊拉克对科威特发动侵略战争,萨达姆-侯赛因下令其军队悍然入侵科威特，意图将科威特变为伊拉克的第十九个省，17万印度侨民滞留科威特，一位旅居科威特多年的印度侨民兰吉特;挺身而出，带领17万印度侨民逃离危险的科威特。','170,000 Refugees, 488 Flights, 59 Days, 1 Man',4500000,32000000,2.551559,7.3,57,126,'2016-01-22','hi','/oyaxIm3kTWDQtcYQ45eN5sZ6WIz.jpg',2.747175954800115,3,'2026-09-10',2,NULL,NULL),(375950,'乡村医生','Médecin de campagne','故事发生在法国一个偏远地区的乡村，这里所有的人都依靠着他们的医生让-皮埃尔（弗朗索瓦·克鲁塞 饰演）。让-皮埃尔一个星期工作七天，日日夜夜地为村民们服务。然而现在医生本人却生了病。从大医院来的娜塔莉（玛丽安娜·德尼库尔 饰演）成了让-皮埃尔的助手。然而，娜塔莉究竟能否适应乡村的生活，并且最终成为村民们眼中“无法替代”的让-皮埃尔的接替者呢？',NULL,0,0,2.651304,6,63,102,'2016-03-23','fr','/b0l6lOK0aLYK2Wt4DWNmeCXay6M.jpg',2.7402393030778294,3,'2026-09-10',2,NULL,NULL),(376004,'跨时空情杀','Adulterers','A man who returns home to find his wife cheating on him on their anniversary. He holds her and her naked and humiliated lover captive at gunpoint while he decides whether or not he\'s going to kill them. The story, inspired by true events, takes place over one day and is set in New Orleans during a stifling heat wave.','Love. Betrayal. Vengeance',750000,0,1.471139,5.2,16,80,'2016-01-05','en','/7weaBxcimjsN9zi89Dfk4fZFCUE.jpg',2.446482827655436,3,'2026-09-10',2,NULL,NULL),(376010,'Western Religion','Western Religion','The year is 1879. Gunfighters from the far reaches of the globe descend on Religion, AZ to compete in a legendary poker tournament. Drawn by the gold prize, the players come to realize that in this game, their very souls are at stake.','Your soul is at stake in Religion, Arizona.',0,0,0.58954,0,0,106,'2015-10-09','en','/i4Gz2KRCgPpOig6boTphl0Ck10N.jpg',1.8351290106924594,3,'2026-09-10',2,NULL,NULL),(376659,'坏妈妈','Bad Moms','艾咪（蜜拉库妮丝 饰）外表看起来光鲜亮丽，有美好的婚姻家庭、品学兼优的孩子，还有稳定的工作，生活看似完美无瑕，但她却早已受够每天不断地为家庭操劳付出，还得被其他妈妈们欺压，精神濒临崩溃。忍无可忍的她决定断开家庭、抛夫弃子，甩开狗屁倒灶的鸟事，和她两名闺蜜相揪“解放”，放纵快活、狂欢畅饮享受婚后丧失的自由，但这场冒险之旅却极度失控。  　　艾咪总是把家庭放在第一位，但要维持美好的家庭生活令她备感压力，幼稚的丈夫和挑剔的孩子，还有白目的主管更让她耗尽精力，元气大伤，加上学校强势的妈妈们老是欺负她，她再也受不了了，决定让自己从传统的家庭责任中解放，揪她两名人妻闺蜜一起摆脱家庭，展开一场“醉后”之旅，狂欢整夜，不醉不归，享受睽违已久的放荡生活，俗话说的好“不怕当妈累，就怕姐妹不Play”，究竟艾咪能借由这趟旅程找回渴望已久的“姐脱”吗？','Party like a mother.',20000000,183936074,42.512296,6.3,1252,100,'2016-07-28','en','/AjrzimcGa7lwswORZkMMrlafJaf.jpg',3.515404349351825,3,'2026-09-10',2,NULL,NULL),(378200,'佳偶天成','The Perfect Match','Terrence J. stars as Charlie, a playboy who\'s convinced that relationships are dead. His two best friends, Donald Faison and Robert C. Riley, bet him that if he sticks to one woman for one month, he\'s bound to get attached. Charlie denies this until he crosses paths with the beautiful and mysterious Eva, played by singer/actress Cassie. They may agree to a casual affair, but eventually Charlie is questioning whether he may actually want more.','t\'s what everyone\'s looking for',0,0,3.810827,5.2,42,96,'2016-03-11','en','/sAiF9gKhb3gPbnp9g5nNhrfTqpL.jpg',2.6442960494168317,3,'2026-09-10',2,NULL,NULL),(378237,'Amidst the Devil\'s Wings','Amidst the Devil\'s Wings','Prequel to \"5th of a Degree.\"','Prequel to \"5th of a Degree.\"',300000,0,0.018087,0,0,90,'2014-12-01','en','/akV2i3dRYbWDNZ7PEJOpcclSpQY.jpg',1.8338236995883124,3,'2026-09-10',2,NULL,NULL),(379532,'Rodeo Girl','Rodeo Girl','Shipped off to her American dad\'s ranch for the summer, a teen and her horse Lucky Lad compete for a spot at the National Youth Rodeo.',NULL,0,0,0.087574,5.5,1,108,'2016-01-05','en','/y12q73PAVPax4hAZvaAZzNFUtOA.jpg',1.9842454661094542,3,'2026-09-10',2,NULL,NULL),(380097,'America Is Still the Place','America Is Still the Place','1971 post civil rights San Francisco seemed like the perfect place for a black Korean War veteran and his family to realize their dream of economic independence and his own chance to be his a \"boss\". Charlie Walker would soon find out how naive he was. In a city full of impostors and naysayers, he refused to take \"No\" for an answer. Until a catastrophic disaster opened a door that had never been open to a black man before. This is a story about what happened when he stepped through that door, with both feet!.',NULL,0,0,0,0,0,0,NULL,'en',NULL,1.833782385321101,3,'2026-09-10',2,NULL,NULL),(380733,'Fight to the Finish','Fight to the Finish','A young amateur fighter makes an enemy with a hardened thug when he gets in-between his next-door neighbor and her abusive ex- boyfriend. As his personal life becomes threatened, he realizes he must finish the fight that he started, but this time they\'ll settle it in the ring for the championship.','It\'s all or nothing',0,0,0.251828,5.2,3,94,'2016-02-02','en','/skTmWx5vwwvuKRmHXJF2jGNP6tP.jpg',2.134264672899995,3,'2026-09-10',2,NULL,NULL),(381902,'西游记之孙悟空三打白骨精','西遊記之孫悟空三打白骨精','影片讲述了师徒四人在西行的路上，白骨精（巩俐 饰）为夺唐僧（冯绍峰 饰）而巧设圈套，被孙悟空（郭富城 饰）识破，屡次受挫。唐僧却误会孙悟空滥杀无辜，将其逐出师门。白骨精趁虚而入，掳走唐僧。悟空闻讯前往营救，彻底击溃白骨精。师徒冰释前嫌，重新上路。',NULL,68490000,193677158,4.72629,6,24,120,'2016-01-22','zh','/ktV3cAM6nCB6RJg6JxlqRyJO998.jpg',2.542470621525843,3,'2026-09-10',2,NULL,NULL),(385383,'搏击谷','Fight Valley','22 岁的托里·科罗 (Tori Coro) 参加了新泽西州卡姆登一个贫民窟的地下拳击场。当她的尸体被遗弃在树林中时，谣言四起，说托里死在搏击谷，搏击谷是一个非官方的社区，拳击手们会去那里赚钱。托里的妹妹温莎搬到镇上开始自己的调查。Jab\'s 是一位受人尊敬的拳击手，后来成为健身房老板，他同意训练温莎，而温莎则准备与杀害托里的凶手面对面，为正义而战。','One way in. No way out.',27000000,0,1.224105,3.9,8,90,'2016-07-22','en','/jIPWkzF9srlU8eZTldLM6JYZwkO.jpg',2.3064889273484432,3,'2026-09-10',2,NULL,NULL),(385636,'Juliet and Alfa Romeo','Julija in Alfa Romeo','Tilen (18), an attractive high school student, swears to be faithful forever in the hope that his girlfriend will let him sleep with her. Suddenly, a sequence of tragic events turns his world upside down. He starts to believe he is under a spell which could put his life in jeopardy, which prevents him from having a relationship with Sara (18), his one true love. He finally succeeds to get his life back on the right track with the help of his best friend Zeljko, a mysterious fortune-teller, and the power of love.',NULL,0,0,0.061248,6,1,83,'2015-09-17','sl','/3NIkJPZe7TEtoGKG8gcd1Vy5I0h.jpg',1.9843909722589088,3,'2026-09-10',2,NULL,NULL),(385736,'无敌球鞋','Kicks','布兰登是一个15岁的孩子，他的梦想是一对新鲜空气乔丹。在他拿到他们的手后不久，他们就被当地的一个流氓偷走了，导致布兰登和他的两个朋友在奥克兰执行一项危险的任务去取回他们。','They aren\'t just shoes',0,0,3.467923,7.5,18,80,'2016-09-09','en','/5lW7mFOQW5wPlCIT0gUuYbhNtVP.jpg',2.4911175981525417,3,'2026-09-10',2,NULL,NULL),(386826,'初学者的鼻烟指南','A Beginner\'s Guide to Snuff','渴望闯入影视世界的两个兄弟决定参加恐怖电影比赛，还有什么比难以捉摸的鼻烟影片更恐怖的呢？',NULL,0,0,0.060127,0,0,87,'2016-03-04','en','/kv0i6XqUULBcgCHwXedZZulOPyv.jpg',1.8339197272210632,3,'2026-09-10',2,NULL,NULL),(389425,'Code of Honor','Code of Honor','Colonel Robert Sikes is on a mission to rid his city of crime. As a stealthy, one-man assault team, he will take on street gangs, mobsters, and politicians with extreme prejudice until his mission is complete. His former protégé, William Porter, teams up with the local police department to bring his former commander to justice and prevent him from further vigilantism.','There is no honor in revenge.',8000000,0,2.101718,4.1,16,106,'2016-05-06','en','/zoNvd5DNrQwGjc9lVit7rJMYFQY.jpg',2.4408305228395757,3,'2026-09-10',2,NULL,NULL),(394047,'爱狗人士','The Dog Lover','萨拉是一个动物权利组织的新星，她去了一个非法饲养小狗的地方实习，当该组织与当地执法部门联手打击时，她在做好本职工作和做正确的事情之间左右为难。','She ended up on the wrong side of right.',2000000,0,1.193219,5.3,6,101,'2016-07-08','en','/sDPBBKZAIP6r2OaLfNBSI1hdp2Q.jpg',2.2570653485538665,3,'2026-09-10',2,NULL,NULL),(395766,'The Secret','The Secret','The Secret is the story of a real-life double murder. James Nesbitt plays Colin Howell, a respectable dentist and pillar of the community, who became a killer in partnership with a Sunday school teacher, Hazel Buchanan, played by Genevieve O\'Reilly.',NULL,0,0,0.042346,0,0,200,'2016-04-29','en',NULL,1.8338791119180673,3,'2026-09-10',2,NULL,NULL),(396152,'Restoration','Restoration','During home renovations, a young couple release a fiery spirit seeking retribution. To save themselves and set the spirit free, they must uncover the dire truth. But nothing is as simple as it seems...',NULL,0,0,2.525569,5.3,11,90,'2016-05-03','en','/bSFXkIFwPVanwLCI0DQfMMfVBMN.jpg',2.375515321114049,3,'2026-09-10',2,NULL,NULL),(402515,'American Beast','Solitude','After finding an old storage locker filled with his family\'s history, James Erikson begins a journey to discover the truth behind a mysterious piece of land in the small town of Solitude.',NULL,0,0,0.018716,0,0,89,'2014-10-21','pt','/ivQ9rzNV3HzGlwbWNS6bavjsOJk.jpg',1.8338251363480889,3,'2026-09-10',2,NULL,NULL),(407887,'仁川登陆作战','인천상륙작전','《仁川登陆作战》讲述了战役的指挥官麦克阿瑟将军与在这场战役中秘密展开X-RAY谍战行动的8名韩国士兵的故事。','The Odds Were 5000 to 1 … One was all They Needed.',0,0,6.116436,5.8,29,110,'2016-07-27','ko',NULL,2.5827234773455743,3,'2026-09-10',2,NULL,NULL),(408429,'Perfect Cowboy','Perfect Cowboy','Two gay fathers of a straight country western singers, all living in a rural community and playing music together. Jimmy Poole gets out of prison and kicks his step-son Mark out of the family\'s band.',NULL,200,0,0.050978,5,1,109,'2014-07-13','en','/t12YIm3IajbE1erieS9Yee9iUqQ.jpg',1.9839562337300296,3,'2026-09-10',2,NULL,NULL),(417859,'穿靴子的猫','Puss in Boots','他是一只穿靴子的猫（Antonio Banderas 配音），多年来行侠仗义，行走江湖，剑术高明，胆大卖萌，虽是官兵通缉捉拿的要犯，但从来都无所畏惧，泰然自若。在某个极不友好的小酒馆里，靴猫听说杰克（Billy Bob Thornton 配音）和吉尔 （Amy Sedaris 配音）这对雌雄恶棍拿到了传说中的魔豆，魔豆长出的豆荚直通巨人的宫殿，而那里住着令人垂涎可以下金蛋的鹅。靴猫决定铤而走险劫掠魔豆，却遭到神秘的黑猫阻挠。在黑猫引诱下，他来到一处猫儿聚会的场所，结果意外遇到当年孤儿院的好友矮蛋（Zach Galifianakis 配音），黑猫则是性感的小母猫咪·柔爪（Salma Hayek 配音）。矮蛋希望和靴猫重组魔豆帮，拿到下蛋的金鹅……','Live for danger. Fight for justice. Pray for mercy.',130000000,554987477,20.678787,6.4,451,90,'2011-10-28','en','/5P2FRAC9WZeEe3lvAHQwezjP7PD.jpg',3.241554601021169,3,'2026-09-10',2,NULL,NULL),(426067,'Midnight Cabaret','Midnight Cabaret','A Broadway producer puts on a play with a Devil character in it. Soon the actors begin having nightmares, and events that are mentioned in the play really start happening.','The hot spot where Satan\'s waitin\'.',0,0,0.001389,0,0,94,'1990-01-01','en','/lRToQoX2cQCwbq9hIzWuc6YcKNw.jpg',1.8337855580704325,3,'2026-09-10',2,NULL,NULL),(426469,'小伙不错','Growing Up Smith','In 1979, an Indian family moves to America with hopes of living the American Dream. While their 10-year-old boy Smith falls head-over-heels for the girl next door, his desire to become a \"good old boy\" propels him further away from his family\'s ideals than ever before.','It’s better to stand out than to fit in.',0,0,0.71087,7.4,7,102,'2017-02-03','en','/ncALkAajnctju0CYKH4bFm40QJD.jpg',2.290627256244978,3,'2026-09-10',2,NULL,NULL),(433715,'8 Days','8 Days','After sneaking to a party with her friends, 16-year-old Amber Stevens goes missing. Forced into the world of sex trafficking, her family and community fight to get her back. Inspired by actual events.','She never knew it could happen to her...',0,0,0.015295,0,0,90,'2014-06-15','en','/fvYRa0Zw9G3KVKuxDjmtQlzZngx.jpg',1.8338173221108947,3,'2026-09-10',2,NULL,NULL),(447027,'Running Forever','Running Forever','After being estranged since her mother\'s death in the 9/11 attacks, both daughter and father must work together to re-establish their relationship. When the difficulty nearly consumes them both, a bond with a beautiful horse that has also gone through its own tragic loss brings Taylor Sims, back to what is important - family, friendship and faith. With help from the community and from above, they repair the pieces of their lives and learn to stop running, forever.',NULL,0,0,0.028756,0,0,88,'2015-10-27','en','/u4KHwcZmNH0Vr6xpGvDKdkBTopg.jpg',1.8338480696837884,3,'2026-09-10',2,NULL,NULL),(459488,'To Be Frank, Sinatra at 100','To Be Frank, Sinatra at 100',NULL,NULL,2,0,0.050625,0,0,NULL,'2015-12-12','en','/fdWfdl8p4W7TZ20BHCcCb7BUiel.jpg',1.8338980227832327,3,'2026-09-10',2,NULL,NULL),(459490,'歪心狼对阵ACME','Coyote vs. Acme','　　故事讲述了乐一通经典角色歪心狼（Wile E. Coyote）在长期使用Acme公司的产品追捕BB鸟（Road Runner）失败并遭受身心创伤后，决定不再忍受。他聘请了一位倒霉的人类律师，向Acme公司提起诉讼，要求巨额赔偿。而Acme公司的首席律师则试图捍卫公司利益，双方在法庭上展开了一场荒诞又爆笑的对决。  影片改编自1990年《纽约客》的一篇同名文章。','',0,0,586.1606,7.579,303,0,'2026-08-20','en','/xONOMna5Z102bw0jMPBM4H73B9m.jpg',4.543358523239443,NULL,NULL,NULL,NULL,NULL),(459491,'奥德赛','The Odyssey','特洛伊战争之后，奥德修斯踏上返回伊萨卡的艰险归途，途中遭遇了诸如独眼巨人波吕斐摩斯、塞壬女妖和喀耳刻等神话生物。','',0,0,386.7119,8.006,3611,0,'2026-07-15','en','/mboVwZEcA3hczicbdJL3OrsbzZ4.jpg',4.968650732470005,NULL,NULL,NULL,NULL,NULL),(459492,'怒之杀','Mutiny','　　在目睹亿万富豪蒂布遇害，自己被诬陷为凶手后，科尔·里德只身闯入一艘远洋货轮，决心为老板复仇，却由此意外揭开了一个骇人听闻的惊天阴谋。','',0,0,343.6508,6.44,361,0,'2026-08-19','en','/txMVA9gNEvADAVYZpHVvGg0YQnW.jpg',3.9306486836741006,NULL,NULL,NULL,NULL,NULL),(459493,'群体','군체','因不明感染事件被封锁在一栋大楼内的幸存者们，与以不可预测形态进化的感染者展开殊死搏斗。随着感染不断扩散，幸存者被迫在有限空间中寻找生路，同时面对越来越聪明、越来越危险的感染者。全智贤在片中饰演生命工程学教授兼幸存者领袖权世贞。她不仅要带领众人逃出生天，更试图破解感染者不断进化的规律，在绝境中寻找唯一的生机。  如果说《釜山行》让观众见识了高速奔袭的感染者，那么延尚昊导演的新作《群体》，则把恐惧再次升级。影片于2026年5月21日在韩国上映，仅4天突破100万观影人次，随后迅速突破500万人次，不仅成功跨越损益平衡点，也成为今年韩国最具话题性的商业电影之一。彻底颠覆了传统丧尸设定。电影中的感染者不再只是凭本能行动，而是会不断进化，并逐渐形成拥有群体智慧（Hive Mind）”的全新生命体。他们会集结、协同行动，甚至能够根据环境不断改变攻击方式，让每一次逃亡都充满未知。','',0,0,331.2021,8.101,756,0,'2026-05-21','ko','/tLIpowwkaEVrkywUZa7tKA2pMNe.jpg',4.333659323368776,NULL,NULL,NULL,NULL,NULL),(459494,'海洋奇缘：启航','Moana','海的召唤，从未停止。熟悉的旋律响起，属于“莫阿娜”的冒险，再次扬帆启航。','',0,0,297.8453,7.029,509,0,'2026-07-08','en','/8eNUlSoXmLR8lfkRVxR1aJZwCJG.jpg',3.9809883365438643,NULL,NULL,NULL,NULL,NULL),(459495,'求救信号','Mayday','在冷战高峰期，自视甚高的美国海军飞行员Troy \'Assassin\' Kelly上尉飞到苏联去执行秘密任务，然而任务崩了，他一个人被困在敌后方，被性情暴躁、喜好美国文化的前克格勃特工Nikolai Ustinov发现。Troy以为自己完了，但是他们之间出人意料的结盟，是否会让Troy获救，以及发展出一段双方都没想到的情谊？','',0,0,212.8735,7.892,420,0,'2026-09-03','en','/lsgU1r3B57cCfEKKkOEmWNdsx93.jpg',3.827394335575261,NULL,NULL,NULL,NULL,NULL),(459496,'生死时限','The Runner','一位才华横溢的伦敦律师玛雅马滕正在晨跑，突然接到一个电话，生活瞬间崩塌：她的儿子被绑架了。为了救回儿子，她必须不停奔跑，服从绑匪给的每个冷酷命令，不能信任任何人--每一秒都在考验这位母亲为了救孩子，愿意付出多大的代价。','',0,0,205.9811,6.72,394,0,'2026-09-03','en','/ixvgtY8zSfNJsFwCtLlYYvqoCKE.jpg',3.666545054940225,NULL,NULL,NULL,NULL,NULL),(459497,'雷霆家族大对决','Clash of the Thundermans','当克洛伊觉醒了一股危险的全新超能力后，她接到命令，必须前往超级英雄寄宿学校。菲比、芭芭拉和比利陪同她躲藏，而麦克斯、汉克和诺拉则追赶他们，家庭因此分裂，一场关乎他们未来的战争就此爆发。','',0,0,193.545,6.682,44,0,'2026-09-03','en','/ujVxsOmxig7U7tOXLv1eOQV7chf.jpg',3.112213803038372,NULL,NULL,NULL,NULL,NULL),(459498,'牢笼鬼魂','Hantu Dalam Sel','故事舞台设在一座狱警贪腐、帮派割据、管理极端残暴的重型监狱，一名自带恶灵的新囚犯入狱后，牢房区接连爆发无差别血腥命案，死者遗体都会被恶灵改造成诡异惊悚的人体陈列造型，监狱里水火不容的几大囚犯帮派、收受贿赂草菅人命的狱警，在持续不断的死亡恐慌下被迫放下仇怨抱团求生。其中一名囚犯意外获得感知人身上黑暗气场的能力，能预判恶灵的猎杀目标，众人一边对抗恶灵的疯狂屠戮，一边逐层揭开监狱长期掩盖的虐囚黑幕、以及恶灵复仇背后埋藏的陈年冤屈，在不间断的血腥杀戮、暴力冲突里，完成一场底层绝境的反抗。 \\n《撒旦的奴隶》恐怖片名导乔科·安瓦尔最新恐怖力作，主打重口血腥，超自然肉体恐怖，视觉冲击力是近几年东南亚恐怖片的天花板，肉体恐怖、猎奇怪物造型全程高能，血浆场面密集且设计极具想象力。','',0,0,183.5352,7.2,55,0,'2026-04-16','id','/qinuFdSWHS2itkyNFEpzonAIJQA.jpg',3.1500087160266075,NULL,NULL,NULL,NULL,NULL),(459499,'保镖恋人','Enfrentados: Marfil','玛菲尔（Marfil）是一个西班牙富商的女儿，她在纽约的生活因一次绑架然后莫名其妙的获释而彻底颠覆。她的父亲雇佣了塞巴斯蒂安·摩尔（Sebastián Moore）作为她的保镖，两人被迫朝夕相处。在这个看似一切都不真实的世界里，一种无法避免的吸引力在他们之间悄然萌生。本片改编自《罪爱/错误》（Culpables）系列畅销书作者梅塞德斯·罗恩（Mercedes Ron）的同名小说。','',0,0,208.476,6.579,38,0,'2026-09-09','es','/rJjaFQvYgFICyrFvcbqxDIHsH6M.jpg',3.112452082389199,NULL,NULL,NULL,NULL,NULL),(459500,'痴迷','Obsession','在折断神秘的“心愿柳”以赢得暗恋对象的心之后，一个对爱情充满幻想的人如愿以偿地得到了自己想要的一切，但很快他发现，有些欲望需要付出黑暗而可怕的代价。','',0,0,158.47,8.192,5437,0,'2026-05-13','en','/32HbiLe4AWBqsM7WrYEYpL3oHmS.jpg',4.613593754778717,NULL,NULL,NULL,NULL,NULL),(459501,'最后的曙光','The Last Sunrise','身患慢性疾病的大学生小莱与母亲一同前往马略卡岛度过夏天的故事。她在那里意外邂逅了胡利安，并开始学会活在当下。然而，随着病情不断恶化，尘封多年的家族秘密也逐渐浮出水面，一切美好都可能在夏天结束前分崩离析。','',0,0,143.6744,6.691,149,0,'2026-08-26','en','/hgQRJIV1s8NjWxu6D08eAjIRaGF.jpg',3.279474344826456,NULL,NULL,NULL,NULL,NULL),(459502,'夜巡毒枭','La captura','两位墨西哥员警不幸得罪一名残忍的毒枭后，必须拼命撑过值勤的最后几小时。改编自真实事件。','',0,0,130.2284,8.791,608,0,'2026-08-21','es','/u0YAsKWZ4SFg0yTGj3Dgs3m37te.jpg',3.889113251520647,NULL,NULL,NULL,NULL,NULL),(459503,'星辰之怒','Rage of Stars','故事讲述一位国际特种部队女兵预感到人类即将灭亡。《群星之怒》是根据屡获殊荣的短片《不再有星辰》改编的电影长片。','',0,0,126.9085,6.1,95,0,'2026-08-06','en','/rH3Aqbc3a8ze4WulcBvNCw8OlAU.jpg',3.1143656116155505,NULL,NULL,NULL,NULL,NULL),(459504,'小黄人与大怪兽','Minions & Monsters','为了拍摄心中理想的怪兽电影，这群萌趣活宝四处物色演员，竟然真的集齐了各式怪兽，上演疯狂大乱斗！','',0,0,124.8064,7.6,1078,0,'2026-06-24','en','/1YXOk6K50XgZwEABGAbDve35vxc.jpg',3.901658976875494,NULL,NULL,NULL,NULL,NULL),(459505,'鲨笼绝境','Above & Below','五位挚友相约前往热带海岛度假，计划在碧蓝海域中体验刺激的鲨鱼笼潜水，同时享受奢靡的派对狂欢。然而他们浑然不知，这趟旅程不过是一场精心布局的犯罪幌子，幕后主谋正是行事冷酷、算无遗策的危险人物“伯恩斯”——他在暴力中淬炼成型，对大海了如指掌。当阴谋突然引爆，一场激烈冲突 让女主角塔蒂亚娜与好友卡莉被困深海之中：头顶是氧气瓶指针飞速下滑的恐慌，四周是游弋不去的鲨鱼，水面之上则是伯恩斯穷凶极恶的手下虎视眈眈。夹在水下猛兽与水面上暴徒的双重绞杀之间，塔蒂亚娜必须凭借全部的智慧与勇气，在生命流逝之前找到逃出生天、拯救同伴的唯一出路。影片将海洋生存惊悚的窒息感与犯罪动作的高燃节奏融于一体，充满意料之外的反转，令人屏息。','',0,0,114.7068,6.321,28,0,'2026-07-29','en','/uHHgdcPk53xlAGrejtt7rOqzd5.jpg',2.8293084376075726,NULL,NULL,NULL,NULL,NULL),(459506,'匹诺曹：弦断','Pinocchio: Unstrung','老木匠杰佩托为孙子詹姆斯打造了一具栩栩如生的木偶匹诺曹，木偶意外觉醒了自我意识，本心单纯地想要守护小主人。但在邪恶化的蟋蟀蛊惑、以及自身木质本源的执念驱使下，匹诺曹偏执地认定所有让詹姆斯受委屈、产生不快的人都是威胁，为了真正变成人类，他开始疯狂猎杀目标，通过收集受害者的牙齿、皮肤、器官来完成肉身蜕变，牙医、校霸、刻薄的成年人接连沦为他的猎物，一场失控的血腥屠杀就此铺开，原本纯真的童话人偶彻底沦为残忍的杀人傀儡。','',0,0,106.3727,6.578,96,0,'2026-07-22','en','/4cY4TgrzcKfdBgaRgzGsHsb9AJk.jpg',3.0864020700388735,NULL,NULL,NULL,NULL,NULL),(459507,'耳语者','The Whisper Man','年幼的儿子失踪后，这名鳏夫向关系疏远的父亲求助，后者是一名退休的警探，而他曾送进监狱的一名连环杀手现在与这起案件有关。','',0,0,92.4119,6.814,597,0,'2026-08-27','en','/nP9y4iXZWBQx7Sz8EtLzsQgLE3d.jpg',3.5279961883548756,NULL,NULL,NULL,NULL,NULL),(459508,'蔷薇修剪术','Rosebush Pruning','在加泰罗尼亚阳光下的一座豪华别墅里，美国兄妹杰克、艾德、安娜和罗伯特沉溺于与世隔绝的生活和继承的巨额财富，对失明父亲的要求置之不理，在彼此之间以及他们最新款的名牌服饰中寻求爱与认同。当作为家中支柱的大哥杰克宣布要搬去和女友玛莎同住时，血缘关系就此断裂，艾德被迫揭开母亲死亡的真相。代代相传的谎言开始瓦解，这个家庭的根基也逐渐崩塌。','',0,0,91.7243,6.134,41,0,'2026-04-23','en','/wCbvDXgBYTEhfiZg0Wokdu0iEKI.jpg',2.8552653516131867,NULL,NULL,NULL,NULL,NULL),(459509,'后室','Backrooms','一位心理治疗师的病人，在一次诡异的事故中“切入”到了一个超越现实的奇异维度。为了带回病人，这位治疗师不得不亲自踏入那片无边无际、充满黄色壁纸和嗡嗡荧光灯响声的未知迷宫。','',0,0,83.2717,7.055,3221,0,'2026-05-27','en','/7flxvNLk48fvJel8zHDGqMFvQ9C.jpg',4.008627463802725,NULL,NULL,NULL,NULL,NULL),(459510,'毒：成人童话','ಟಾಕ್ಸಿಕ್','','',0,0,68.8795,8,73,0,'2026-08-26','kn','/oiIPU4lvnI0Ag2K9cyAi44eCaoE.jpg',2.9773077199473534,NULL,NULL,NULL,NULL,NULL),(459511,'一夜限定','One Night Only','在架空版本的纽约，当地立法全面禁止婚前亲密行为，全年仅有固定12小时被解禁，全城单身人群都会在这天争相寻找临时约会。女主角艾莉刚刚经历失恋，并不想随便将就一夜情，男主欧文是披萨店打工的普通青年，同样渴望真挚的感情。两人在解禁之夜偶然相遇，原本只是结伴躲避各种疯狂的路人搭讪与城市管控，一路上接连遭遇乌龙意外、旧日仇家阻拦，在横穿整座混乱都市的奔波里，慢慢对彼此动了真心，在这个只为放纵设立的夜晚，追寻一份长久的爱恋。','',0,0,79.9062,6.703,101,0,'2026-08-06','en','/4BGqt7dmq9dpShnvMaw2IaVulmG.jpg',3.0421716242663344,NULL,NULL,NULL,NULL,NULL),(459512,'惊声尖笑6','Scary Movie','在逃离那个似曾相识的面具杀手二十六年后，核心四人组再度成为猎杀目标，而这一次，所有恐怖电影IP都将无一幸免。','',0,0,73.4977,6.403,1853,0,'2026-06-03','en','/er55juixQ6eEUXbPokukFcHDXyE.jpg',3.698255146860658,NULL,NULL,NULL,NULL,NULL),(459513,'深水','Deep Water','一架从洛杉矶飞往上海的国际航班，在飞越太平洋时遭遇货舱锂电池起火事故，安全系统接连失效，机长理查德与副机长本被迫驾驶飞机紧急迫降在海域。机上三十余名幸存者被困在破损的飞机残骸上，很快发现这片海域已是鲨鱼的猎场。成群的灰鲭鲨被残骸的血腥味吸引，不断发起攻击。幸存者们来自不同国家、背景各异，必须放下隔阂与猜忌，利用有限的资源搭建防御、寻找逃生机会，在茫茫大海中与饥饿的鲨群展开殊死对抗。','',0,0,80.0078,7.11,480,0,'2026-04-30','en','/xYHvLKVtghw4v5tEA2IMKJcqEpu.jpg',3.476460555575493,NULL,NULL,NULL,NULL,NULL),(459514,'坠落2：死点','Fall 2: Deadpoint','痛失姐妹汉特之后，杰克斯与汉特那无畏的好友露斯再度重聚。为了抚平内心的伤痛，两人结伴前往泰国著名的坤山山脉徒步疗伤。不料突如其来的山体滑坡将她们逼入绝境，两人被困在一段摇摇欲坠、高耸入云的3000英尺高空栈道上。面对死神的威胁，杰克斯必须直面内心深处的恐惧，在绝壁之上觅得一线生机。','',0,0,69.7068,6.692,26,0,'2026-09-01','en','/1NleXZfkuNobbPD5LaAsWafP1Op.jpg',2.7146786073434614,NULL,NULL,NULL,NULL,NULL),(459515,'逃出绝命街','The End of Oak Street','居住在花谷街的一对夫妻，察觉到社区里发生了一些细微的变化。当一场剧烈的雷暴袭来后，他们连同他们的孩子和邻居醒来发现自己竟被“传送回了史前时代”，身边被恐龙和其他野生生物包围。','',0,0,81.2687,6.344,471,0,'2026-08-12','en','/a3rWaD4nbPlJ6kSOMO26j8fKS8a.jpg',3.383646441110691,NULL,NULL,NULL,NULL,NULL),(459516,'罗宾汉之死','The Death of Robin Hood','罗宾汉一生沉沦于罪恶和杀戮，饱受过往阴影的折磨。一场他以为是绝唱的战斗后，他身负重伤。一位神秘女子给了他救赎的希望。','',0,0,67.7778,6.203,296,0,'2026-06-18','en','/zCrqSZacpRun28bl9rDWHE7TiLZ.jpg',3.2328138350424904,NULL,NULL,NULL,NULL,NULL),(459517,'捕风追影','捕风追影','一伙天才盗匪劫走数亿资产，却凭借超强反侦察能力全身而退，戏耍警方“天眼”系统。一筹莫展之际，澳门司警局请回了隐退多年的跟踪专家黄德忠，他培养年轻司警何秋果等人，重组“神秘跟踪队”，最终锁定了盗匪团的幕后狼王傅隆生。当警方布下天罗地网之时，盗匪团也设下局中局，斗智斗勇斗心眼，一场高端猫鼠局拉开帷幕……','',0,0,66.0309,8.24,1379,0,'2025-08-16','zh','/o25Tk1FYQi2BLk0OEAvx2h69QvB.jpg',3.972168082179199,NULL,NULL,NULL,NULL,NULL),(459518,'监狱风云','監獄風雲','年轻有为的广告设计师卢家耀（梁家辉 饰）在一次阻止不良分子寻衅滋事中失手伤人，被判服刑三年，在狱中，他因个性憨直得罪了黑帮老大，受尽欺辱，老囚犯钟天正（周润发 饰）看不过仗义相助，两人结为患难之交。  钟天正原本有完好家庭，只因嗜赌成性才误杀妻子，身陷囹圄的他追忆往事时后悔不已， 决心走出高墙后重新做人。然而，因为替卢家耀出头，他得罪了狐假虎威心狠手辣的典狱长（张耀扬 饰），自此卷入狱中恶势力的漩涡，走投无路之际，他放弃了“能忍则忍”的处世哲学，决意以暴施暴。','',0,0,56.134,7,109,0,'1987-11-13','cn','/scVTfajaEkHdIsa2ceo1jGdsbI2.jpg',3.017350734579064,NULL,NULL,NULL,NULL,NULL),(459519,'魔法情缘','Practical Magic 2','一个世代都是女巫的家族，被诅咒几个世纪都无法拥有爱情，他们试​​图通过直面黑暗的秘密和为彼此牺牲来打破诅咒。','',0,0,76.8252,6.28,25,0,'2026-09-09','en','/6iAUCCLOIOMSNWPNnQmjHmK8N5U.jpg',2.7184192330979853,NULL,NULL,NULL,NULL,NULL),(459520,'希望','호프','20世纪70至80年代，生活在非军事区附近孤立村庄——湖浦港的居民，与不明外星生物对抗。','',0,0,67.5172,8.024,42,0,'2026-07-15','ko','/1ow5XV795B9nNyN0xPspTuUAxJy.jpg',2.8359990364620673,NULL,NULL,NULL,NULL,NULL),(459521,'超级马力欧银河大电影','The Super Mario Galaxy Movie','击败酷霸后，马力欧和路易吉在蘑菇王国开始了新的生活，并结识了新伙伴耀西。与此同时，酷霸Jr.为了救出父亲、重振酷霸家族，将目标指向生活在彗星天文台、守护奇可们的罗莎塔公主。随着碧姬公主的生日庆典被突如其来的危机打破，马力欧、路易吉、碧姬公主、奇诺比奥和耀西踏上跨越银河的全新冒险，在一个个陌生世界中追寻罗莎塔的下落，并阻止酷霸Jr.的计划……','',0,0,59.8295,8.229,3650,0,'2026-04-01','en','/a7q0dUnrfKpg2b0oftQP1Dl5ZCW.jpg',4.280938341712781,NULL,NULL,NULL,NULL,NULL),(459522,'孤军突围','Lucky Strike','取材于二战阿登突出部战役，一名负伤的美军士兵在德军反攻中和大部队失联，独自被困战火毁坏的比利时敌后区域。他仅依靠自身作战经验、基础单兵装备与一台损坏的无线电，全程躲避德军巡逻搜捕，在严寒荒野中艰难求生，想方设法联络己方部队。','',0,0,57.8565,6.89,41,0,'2026-06-26','en','/qxIpqGJQ7zDRmzeBuh0bIGkeC3j.jpg',2.7899899357918088,NULL,NULL,NULL,NULL,NULL),(459523,'蒙眼追凶','गांधारी','一个母亲在绑架事件中失去视力和爱女，她决定亲自出马，追捕凶手。','',0,0,51.5391,5.063,8,0,'2026-09-03','hi','/i7p7ReqlvC9QRRNkZIz0mfHJCzQ.jpg',2.425208452049808,NULL,NULL,NULL,NULL,NULL),(459524,'汪汪队立大功大电影3：勇闯恐龙岛','PAW Patrol: The Dino Movie','一场突如其来的超强风暴，将莱德队长与汪汪队意外带到神秘恐龙岛，还邂逅了被困荒岛的新朋友小狗乐乐。与此同时，宿敌海丁那市长大肆采矿，不慎唤醒沉睡火山！岩浆喷涌、岛屿崩塌，恐龙岛陷入巨大危机。面对这场规模空前的惊险灾难，勇敢的汪汪队绝不退缩！狗狗们携手恐龙并肩作战，能否冲破险境、化解危机，守护恐龙岛？','',0,0,64.104,7,51,0,'2026-07-23','en','/sKf1q33koQGKSHsYc9l48KI0blw.jpg',2.8556294650846663,NULL,NULL,NULL,NULL,NULL),(459525,'你的心会破碎','Твоё сердце будет разбито','高中生波琳娜在新学校饱受欺凌，为了摆脱困境，她和校霸巴尔斯达成了一场交易：他假装成她的男友保护她，而她则对他言听计从。在这场假扮情侣的游戏中，两人渐渐动了真情，可她的家人和同学却千方百计想要拆散这对恋人。','',0,0,51.0752,7.124,121,0,'2026-03-26','ru','/eQmllIDbIKUOH9rsiRItfdQPzgB.jpg',3.0368494625893057,NULL,NULL,NULL,NULL,NULL),(459526,'死亡之森','Deathwoods','','',0,0,55.2022,6.3,3,0,'2026-08-07','en','/tFH4YchNeEg1WxFvHNE8yQDo8DO.jpg',2.26113564812199,NULL,NULL,NULL,NULL,NULL),(459527,'迈克尔·杰克逊：巨星之路','Michael','　　本片将通过一段从未展现过的深度视角，真实记录传奇巨星迈克尔·杰克逊的复杂人生。影片不仅再现了他最具标志性的艺术表演瞬间，更深入挖掘了他的内心世界——从天才神童的成长阵痛到全球偶像背后的争议与坚韧，全面呈现这位伟大艺术家的辉煌与坎坷。','',0,0,55.0827,8.646,4302,0,'2026-04-22','en','/dU2Ph8TZbZMX4VLZutvKsdDVx9s.jpg',4.426451213703487,NULL,NULL,NULL,NULL,NULL),(459528,'我要你的性','I Want Your Sex','面容清秀的艾略特（库珀·霍夫曼 Cooper Hoffman 饰）在著名艺术家艾丽卡·特蕾西（奥利维亚·王尔德 Olivia Wilde 饰）那里找到了一份工作，当她邀请他成为自己的灵感缪斯时，他的梦想成真了。但很快他就被艾丽卡带入了一个充满性、痴迷、权力、背叛和谋杀的世界，他变得不知所措','',0,0,51.4371,6.2,60,0,'2026-07-29','en','/cLzE0ll50sUpFiuMM3eBkfTeRzz.jpg',2.8459349365496194,NULL,NULL,NULL,NULL,NULL),(459529,'末世行者','The Dog Stars','一场大流行病席卷全球后，人口锐减。在科罗拉多州的飞机库里，一名男子与他的狗和一位阴郁的枪手相伴过着孤寂的生活。当他驾驶着老旧的塞斯纳飞机时，无线电里突然传来神秘的信号，由此引发了一场追寻声音来源的探索之旅。','',0,0,49.1562,6.618,242,0,'2026-08-26','en','/52aOWuclk95Xi1TTtBL1eGtM8P7.jpg',3.17667743067459,NULL,NULL,NULL,NULL,NULL),(459530,'我为什么又结婚了？','Why Did I Get Married Again?','几对夫妻因马库斯和安吉拉女儿的目的地婚礼重聚，新旧矛盾再次爆发，也让他们不禁发问：\"我们为什么又结婚了？\"','',0,0,48.289,6.821,14,0,'2026-09-08','en','/AhMITLQnS83vUs0XL3nOjaBgQwh.jpg',2.53613703520141,NULL,NULL,NULL,NULL,NULL),(459531,'穿普拉达的女王2','The Devil Wears Prada 2','　　随着传统出版业的式微，时尚女王米兰达在职业生涯中迎来新挑战。她不得不与手握广告预算的曾经的助理，如今已是奢侈品牌集团高管的艾米莉正面交锋。两人在行业变局中展开了一场关乎权力与生存的较量。','',0,0,48.652,7.046,2303,0,'2026-04-29','en','/ce3iOpr7DJ0spfwjuyHog22Otjc.jpg',3.838885810253236,NULL,NULL,NULL,NULL,NULL),(459532,'诈死游戏','Just Play Dead','犯罪天才杰克（塞缪尔·杰克逊 饰）计划制造一场假死骗局，好跟妻子诺拉（伊娃·格林 饰）共同诈领3000万美元保险金，还打算陷害妻子的年轻情夫查德（杰森·费尔南德斯 饰）成为杀害自己的凶手。然而，早已受够杰克的诺拉心中另有盘算，她要真的杀死杰克，并独吞这笔钜款。这对尔虞我诈的夫妻，究竟谁能够笑到最后？','',0,0,43.8288,6.222,36,0,'2026-08-28','en','/qLML8chldbnZiHDtxZ6n66ylAA2.jpg',2.7195423604422193,NULL,NULL,NULL,NULL,NULL),(459533,'庇护之地','Shelter','隐居孤岛的特工界黄金王牌迈克尔·梅森（杰森·斯坦森 饰）本想就此隔绝过往，一场风暴却让他救下少女杰茜（博德希·蕾·布里纳希 饰），命运的齿轮彻底反转……他们的行踪不慎暴露在严密的监控网络之下，神秘势力的追杀接踵而至，无路可退的梅森被迫重操旧业，携手少女开启生死突围之路。 面对顶尖特工小队和冷血杀手的轮番围剿，梅森一路火力全开：近身肉搏、飞车追逃、枪林弹雨，硬核爽战全程高能！随着追杀不断升级，层层阴谋被逐一揭开，互相防备的两人成为彼此唯一的依靠。当滔天阴谋席卷而来，他们能否冲破死局？这份绝境中的守护，又会成为铠甲还是软肋？','',0,0,50.4145,7.774,1845,0,'2026-01-28','en','/l6hrmQZnIFLiA72olr8HjdKdIoT.jpg',3.939391331616855,NULL,NULL,NULL,NULL,NULL),(459534,'潜伏6：血域','Insidious: Out of the Further','　　三名潜行者悄然入侵静谧的郊区，将一户新搬来的家庭困于灵薄狱的夹缝之中。他们原以为这只是场残酷的猎杀游戏，却在此撕裂了现实与异界的边界——一个令人战栗的真相逐渐浮现：深渊彼岸的“灵薄狱”，正从裂缝中不断渗入现实世界。','',0,0,44.1513,6.5,134,0,'2026-08-19','en','/gJepjWP4cMVS8gZeynWP64DcEXz.jpg',3.017856822716957,NULL,NULL,NULL,NULL,NULL),(459535,'乐高星球大战：曼达洛人','LEGO Star Wars: The Mandalorian','曼达洛人带着古古去任务执行地点，结果是派丽乔装客户骗他们来与好友同乐，众人在派对上接力讲述回忆曼达洛人与古古的冒险故事，不料曾被赶跑的海盗却集结来袭，众人最后齐力赶跑海盗，并且让曼达洛人终于心甘情愿享受派对。','',0,0,43.3438,6.891,23,0,'2026-09-02','en','/cdhQzX4W9l5ESbVQSbUe56Gqzh0.jpg',2.6300413499054867,NULL,NULL,NULL,NULL,NULL),(459536,'河狸变身计划','Hoppers','梅宝是一位对动物世界充满好奇的年轻女孩，她利用先进的意识上传技术，将自己的思维注入一只机械河狸体内。以这种独特的形态，梅宝结识了河狸王国的乔治国王等动物伙伴。然而，一个由房地产开发计划带来的威胁，正试图破坏动物们的栖息地。梅宝与她的新朋友们联手，利用机械河狸的能力和人类的智慧，共同对抗这个危机，守护动物们的家园。','',0,0,45.7866,8.151,2318,0,'2026-03-04','en','/wlgYLMIYMRZPZqD6ICsC9YK5UDM.jpg',4.086316321119053,NULL,NULL,NULL,NULL,NULL),(459537,'生化危机：爆发夜','Resident Evil','奉命奔赴浣熊市的医疗速递员布莱恩，意外深陷全城失控的病毒浩劫。浣熊市彻底沦陷，异变怪物横行肆虐、嗜血猎捕，身陷末日绝境的他，能否在这场惊魂噩梦中突围求生，搏出一线生机？','',0,0,41.5839,0,0,0,'2026-09-16','en','/3mILtkNzKWPGX9aVIOkAbuOraW0.jpg',1.9287681959192384,NULL,NULL,NULL,NULL,NULL),(459538,'最后孤屋','The Last House','一场全球性诡异灾难毫无征兆降临，一层无形屏障封锁全球所有建筑，门窗墙体全部无法破坏，人类被强制困在自家房屋里，完全无法外出。主角混血夫妻带着一双儿女被困城郊独栋小屋，起初只是等待外界救援，可外界通讯彻底中断，水源、食物持续消耗，狭小空间里压抑感不断发酵，家人之间猜忌、矛盾接连爆发。外部时常传来未知异响与黑影，某天屋外出现一名陌生神秘女子，对方知晓封锁灾难的真相，也带来了外星未知生物的致命威胁，一家人必须在资源耗尽、怪物窥视、内部人心崩塌的多重绝境下，寻找破开屏障活下去的办法，同时揭开这场全球囚禁灾难的外星起源秘密。','',0,0,46.1359,6.877,1302,0,'2026-08-06','en','/mcAwGHjZsIOUBSSRkfhBSXCjNle.jpg',3.6436864655798513,NULL,NULL,NULL,NULL,NULL),(459539,'她的秘密人生','Den hemmelige kvinde','丧失记忆的女子发现自己有家庭，还是航运巨头的继承人。她回归富有且看似完美的过去，探究自己离开的原因。','',0,0,38.9351,6.185,81,0,'2026-08-28','da','/cKSxHIVvxwVgMCozKephCiBrYpN.jpg',2.88179803148071,NULL,NULL,NULL,NULL,NULL),(459540,'巴雷达：灭门凶案','Barreda','本片改编自阿根廷史上轰动一时的重大刑事案件，还原 1992 年里卡多・巴雷达制造的四口灭门惨案，叙事视角侧重于受害者。','',0,0,36.6767,7.262,61,0,'2026-08-28','es','/fTibssp1eMqsRCOKvCVNYa4TpVZ.jpg',2.840399399502364,NULL,NULL,NULL,NULL,NULL),(459541,'逃出布迪秀','Buddy','一行人意外坠入诡异老式儿童节目次元。画风酷似玛卡巴卡，软萌橙色独角兽巴迪主持欢乐秀场。一旦拒绝配合演出，便会惨遭猎杀，死者还会被节目直接替换。众人被困虚假片场，一边躲避玩偶的疯狂追杀，一边拼死寻找逃出电视空间的出路。','',0,0,41.1821,8.12,50,0,'2026-08-27','en','/97au7Q0S6a7mawwIMLYkRZGkiLa.jpg',2.820317027229346,NULL,NULL,NULL,NULL,NULL),(459542,'金谍行动','In the Grey','　　当一名冷酷无情的独裁者窃取了数十亿美元的巨额财富后，一支潜伏于暗影之中的精英特工小队受命夺回这笔巨款。这些特工游走于全球暗网，既能操控权谋博弈，亦精通爆破突袭。这场本已险象环生的惊天盗局却风云突变，最终升级为一场充斥着谋略、欺诈与生死较量的全面战争。','',0,0,38.2145,7.581,927,0,'2026-05-13','en','/1ELrh0rODksZ8DS1hQn95pVCjs9.jpg',3.6515247623368783,NULL,NULL,NULL,NULL,NULL),(459543,'哈利·波特与死亡圣器（下）','Harry Potter and the Deathly Hallows: Part 2','哈利、罗恩和赫敏继续寻找并摧毁伏地魔剩余的魂器，而新的线索最终将他们再次带回已经被食死徒控制的霍格沃茨。随着哈利归来，麦格教授、纳威以及学校的师生和反抗力量开始集结，准备守卫霍格沃茨；伏地魔则率领食死徒大军向学校逼近，一场决定魔法世界命运的大战就此爆发。在战火之中，哈利三人必须赶在伏地魔之前找到最后的魂器，而关于伏地魔、死亡圣器以及哈利自身命运的秘密也逐渐接近最终答案。多年恩怨与所有未解的谜团，都将在霍格沃茨迎来最后的对决……','',0,0,36.9433,8.1,22414,0,'2011-07-12','en','/eGHZV4rsliPchSkzCz0LU7b9ojT.jpg',4.670888612584489,NULL,NULL,NULL,NULL,NULL),(459544,'蠢蛋搞怪秀5','Jackass: Best and Last','蠢蛋们的最后一次疯狂的冒险之旅。','',0,0,35.5655,7.483,236,0,'2026-06-25','en','/vZPYreFiRsCA1wRU9u2fuZ8kbat.jpg',3.2029972961449333,NULL,NULL,NULL,NULL,NULL),(459545,'猫鼬','The Mongoose','一位被冤枉的战争英雄，一无所有，在昔日特种部队成员的帮助下，与警方展开了一场史诗般的全国汽车追逐，全程电视直播。而着迷的公众则密切关注着他，希望他能安全逃脱。','',0,0,236.0432,0,0,0,'2026-10-30','en','/1unGBt5JCA8zd5RfdPr97pEOYgh.jpg',2.372951503373479,NULL,NULL,NULL,NULL,NULL),(459546,'爱的温暖','愛のぬくもり','电影讲述小说家半美高与发型师横泽里美相遇、从楼梯上摔下来并最终交换身体的故事。两人开始假装彼此，过着各自的生活，但 Takashi 的妻子 Yurina 与另一个男人偷偷有染，而女同性恋者 Satomi 则被同居伴侣 Maki 抛弃，因为她找到了另一个男人。','',0,0,176.8071,5.167,6,0,'2024-07-06','ja','/bnGWrxdjoUvCBHmphvIA4eU3AuJ.jpg',2.6578760436478377,NULL,NULL,NULL,NULL,NULL),(459547,'玩具总动员5','Toy Story 5','胡迪、巴斯光年、翠斯等“元老级”玩具将跟随小主人邦妮的成长脚步，共同迎接数字时代下的全新挑战。随着无所不能的科技产品逐渐走进童年世界，一批充满科技感的崭新角色也随之重磅亮相：青蛙造型的智能平板小荷、憨态可掬的导航玩具小不丢、活力十足的抓拍好手小拍侠，以及自带笑点的臭屁小机灵。当身边的同龄朋友们开始沉浸在科技玩具带来的“电子陪伴”中，而玩具伙伴们也迎来了前所未有的生存难题：在屏幕占据注意力的时代，玩具的时代真的结束了吗？在“被取代”危机的当下，这群玩具伙伴还能否携手，帮助邦妮找回属于自己的真实友谊与快乐？','',0,0,149.0524,8.346,2084,0,'2026-06-17','en','/oo46YfPuMcV9t7KsTiaMVUVRjvJ.jpg',4.330280880995078,NULL,NULL,NULL,NULL,NULL),(459548,'蝙蝠侠：骑士陨落 第一部：骑士陨落','Batman: Knightfall Part 1: Knightfall','被称为“贝恩”的神秘巨兽只身突破阿卡姆疯人院，将蝙蝠侠的全部宿敌尽数释放到哥谭街头，整座城市瞬间陷入前所未有的犯罪狂潮。蝙蝠侠为了追捕四散的反派，日夜不休地奔波在哥谭的各个角落，精神与体力都被消耗到极限。而这一切，都是贝恩精心策划的棋局——他在暗处冷眼观察，步步紧逼，用连绵不绝的危机一点点消磨披风斗士的意志，一步步将蝙蝠侠推向身心双重崩溃的临界点。','',0,0,122.1361,9.136,276,0,'2026-06-23','en','/AkfBWqT1iUYRRPL8IGdjmKt4X3e.jpg',3.583237823477257,NULL,NULL,NULL,NULL,NULL),(459549,'Bajo tus pies','Bajo tus pies','','',0,0,101.1595,5.091,11,0,'2026-02-19','es','/fQTACeQLpFoMUqYitxY0DMzfQu9.jpg',2.5998818839662006,NULL,NULL,NULL,NULL,NULL),(459550,'揭秘日','Disclosure Day','如果有人告诉你，我们并非宇宙中唯一的智慧生命，并且向你展示、证明了这一点，你会感到恐惧吗？今年夏天，真相将属于七十亿人。我们正一步步接近……揭秘日。','',0,0,92.3494,7.469,3267,0,'2026-06-10','en','/gMGu5lyv6fjeaoYQGW54eHVA7H8.jpg',4.134597686154438,NULL,NULL,NULL,NULL,NULL),(459551,'挽救计划','Project Hail Mary','太阳正在被“吃”掉，绝望吞噬地球。一名“平凡”的中学教师格雷斯背负全人类的希望，踏上“太空不归路”。末路孤旅中，他意外遇到一位外星萌友，一个同样身陷绝境的外星工程师，这对“宇宙搭子”成了两个文明最后的救命稻草。他们能否在资源紧缺的情况下攻克重重科学谜 题，寻回唯一的希望火种？','',0,0,91.9486,8.643,7674,0,'2026-03-15','en','/qf8HaEGNUFXU6nVAq9BVEk4Tiqb.jpg',4.679657842293511,NULL,NULL,NULL,NULL,NULL),(459552,'安昂传奇：最后的气宗','Avatar Aang: The Last Airbender','派拉蒙和尼克宣布“降世神通”系列开发三部新的电影，仍是动画形式。第一部由《降世神通：最后的气宗》导演Lauren Montgomery执导，《最后的气宗》主创Bryan Konietzko和Michael DiMartino担任制片人。','',0,0,87.6858,9.2,1093,0,'2026-07-24','en','/uMnhXLchOwDUdlKxCoPO6ijJbEU.jpg',4.1093853308925,NULL,NULL,NULL,NULL,NULL),(459553,'星球大战：曼达洛人与古古','The Mandalorian and Grogu','“曼达洛人”丁·贾伦和“尤达宝宝”古古的星际冒险全面升级，“此乃正道”的誓言响彻宇宙，原力将继续与你同在。','',0,0,78.2155,7.473,1568,0,'2026-05-20','en','/d9xUyUXFSXlXLBAzS87LxiiUpKu.jpg',3.8889156848835977,NULL,NULL,NULL,NULL,NULL),(459554,'世界大战','War of the Worlds','威尔·拉德福德是国土安全部的顶级网络安全分析师，他通过大规模监控项目追踪国家安全的潜在威胁。直到有一天，一个不明实体的攻击让他开始怀疑政府是否对他……以及世界其他地方隐瞒了什么。','',0,0,81.9432,4.018,1129,0,'2025-07-29','en','/pFHchrzlbzzzZPEHnagb1WBK8PA.jpg',3.1655469804746645,NULL,NULL,NULL,NULL,NULL),(459555,'Animales','Animales','','',0,0,75.9828,6.2,40,0,'2026-02-05','es','/9fbZdiOI9fRinl44mNm3CYgEtYR.jpg',2.8150987169768147,NULL,NULL,NULL,NULL,NULL),(459556,'邻家小侦探','NABOspionen','神秘客公开了蜘蛛侠的真实身份后，彼得·帕克原本的生活彻底失控，MJ、内德和身边亲近的人也因此受到牵连。为了让一切恢复正常，彼得找到奇异博士，希望借助魔法让世人重新忘记自己就是蜘蛛侠。然而一次失控的咒语意外撕开了不同宇宙之间的界限，那些曾在其他世界与蜘蛛侠交手的危险人物开始接连出现在他的世界。面对不断扩大的多元宇宙危机，彼得不得不与奇异博士联手寻找解决办法，而这一次，他所作出的选择也将彻底改变自己作为蜘蛛侠的人生……','',0,0,71.3958,7.9,23075,0,'2021-12-15','en','/eHbfXqJpm7IJV6W5xO6wTUIv9sQ.jpg',4.698253039909252,NULL,NULL,NULL,NULL,NULL),(459557,'洞穴少女','Cavegirl','由于一块奇特的晶体，一位害羞的学生穿越到了石器时代，在那里他爱上了一位美丽的穴居女子，并帮助她的族人击退了一群食人族。','',0,0,86.0097,3.9,24,0,'1985-05-01','en','/2baiP07w14Fk5DMPAPuuu6zC5ak.jpg',2.7080430426711923,NULL,NULL,NULL,NULL,NULL),(459558,'超级少女','Supergirl','当一位冷酷无情、突如其来的劲敌突袭家园，“超级少女”卡拉·佐-艾尔不得不与一位意想不到的同伴结盟，横跨星际，踏上一段交织复仇与正义的壮阔征途。','',0,0,74.636,6.705,2224,0,'2026-06-24','en','/hpG9LilPRwY39BhRGlU1H9N4FE2.jpg',3.8118014222704595,NULL,NULL,NULL,NULL,NULL),(459559,'月球小姐','La donna della luna','一名前往西西里岛的意大利裔美国女子接了一名自称与毒贩有麻烦的青少年。','',0,0,58.8693,5.6,8,0,'1988-03-31','it','/9STSK30Z2TG9MPiMujUVYqKV0mQ.jpg',2.4437021349114727,NULL,NULL,NULL,NULL,NULL),(459560,'Blood Covenant','Blood Covenant','','',0,0,60.2372,5.5,2,0,'2026-05-26','en','/Avx9Qb3pn86ilzSM3C7nRs5LifX.jpg',2.209433414419383,NULL,NULL,NULL,NULL,NULL),(459561,'鬼灭之刃：无限城篇 第一章 猗窝座再袭','劇場版「鬼滅の刃」無限城編 第一章 猗窩座再来','当鬼杀队的成员和柱之人在为即将到来的与鬼的战斗做准备，完成共同的体能训练——柱之训练时，鬼舞辻无惨在产屋敷宅邸出现。由于鬼杀队的主公处于危险之中，炭治郎和柱急忙赶往总部，但却被鸣女推入一个神秘的异空间。炭治郎和鬼杀队的目标是鬼的堡垒——无限城。因此，鬼杀队和鬼之间的最终战斗的战场已经准备就绪。','',0,0,65.2953,8.787,2112,0,'2025-07-18','ja','/bljRBxXUaX73M3nbjeS3Hq1cohv.jpg',4.241942143549008,NULL,NULL,NULL,NULL,NULL),(459562,'疯狂动物城2','Zootopia 2','在经历上一场案件后，兔警官朱迪与狐狸尼克已经成为搭档。一个神秘爬行动物突然出现在疯狂动物城，并引发一连串意外事件，让这座原本由哺乳动物构成的城市面临新的危机。为了追查真相，朱迪和尼克再次携手行动，在追捕过程中前往此前鲜少接触的新领域，并深入神秘的地下黑市寻找线索。随着调查不断深入，这对老搭档逐渐发现，神秘爬行动物的出现背后还隐藏着更多关于疯狂动物城的秘密……','',0,0,62.6823,7.7,3411,0,'2025-11-26','en','/lauN6Sx5FZhCIjrti77mqhqKRpI.jpg',4.135881501363607,NULL,NULL,NULL,NULL,NULL),(459563,'阿凡达：火与烬','Avatar: Fire and Ash','在梅卡伊纳部落安顿下来后，杰克·萨利与奈蒂莉一家仍深陷失去长子的悲痛之中，奈蒂莉对人类的仇恨也愈发强烈。由于人类少年“蜘蛛”无法长期依靠呼吸设备生活，杰克一家决定陪同“风之商人”护送他前往更适合人类居住的地方。然而途中，商队突然遭到“灰烬族”的袭击。这个家园曾被灾难摧毁、并因此背弃大地之母爱娃的纳威人族群，在首领瓦朗的带领下烧毁船只、掠夺物资，使萨利一家再度陷入危机。与此同时，迈尔斯·夸里奇上校依然没有放弃对杰克的追踪。面对来自人类以及纳威人内部的新威胁，原本尚未走出伤痛的一家人不得不再次为了彼此和潘多拉的未来而战……','',0,0,61.6147,7.647,4298,0,'2025-12-17','en','/tIfllOpkhZl5sbqZd1X77iiaJDj.jpg',4.184814585396267,NULL,NULL,NULL,NULL,NULL),(459564,'复仇者联盟3：无限战争','Avengers: Infinity War','来自宇宙深处的强大敌人灭霸开始寻找六颗无限宝石，企图利用它们的力量实现自己的计划。随着他的军团向地球和宇宙各处发动袭击，复仇者联盟、银河护卫队以及众多超级英雄被迫卷入这场前所未有的战争。此时的复仇者们仍因过去的分裂而各自行动，却不得不在不断逼近的危机中寻找彼此的力量。面对一个远比以往任何敌人都更加强大的对手，他们必须竭尽所能阻止灭霸集齐无限宝石，而整个宇宙的命运也因此悬于一线……','',0,0,68.5077,8.2,32867,0,'2018-04-25','en','/yr6eDd7JEIWfLW4kv21XlzMd4FC.jpg',4.861293791043152,NULL,NULL,NULL,NULL,NULL),(459565,'复仇者联盟4：终局之战','Avengers: Endgame','灭霸集齐六颗无限宝石后的一声响指，让宇宙中半数生命灰飞烟灭。幸存的复仇者们几近绝望，即使找到灭霸，也发现无限宝石已经被毁，希望似乎彻底破灭。五年后，迷失在量子领域的蚁人意外回到现实世界，并带来了一个可能逆转一切的办法。托尼·斯塔克、美国队长等幸存的英雄再度集结，尝试穿越不同的时间节点寻找过去的无限宝石。然而在行动过程中，过去的灭霸也逐渐察觉了他们的计划。为了挽回失去的一切，复仇者们不得不再次面对一场决定整个宇宙命运的终极挑战……','',0,0,54.8454,8.242,28615,0,'2019-04-24','en','/wXyZYO6BKDh8Evf80DF80VzKcz3.jpg',4.810323944065569,NULL,NULL,NULL,NULL,NULL),(459566,'奇幻变身大冒险','Swapped','森林中的一个小生物和一只高贵的鸟突然互换了身体，他们不得不结伴而行，共同应对此生最疯狂的冒险。','',0,0,40.4427,8.9,2171,0,'2026-05-01','en','/7eJO1JUx6C52lufZpcmHpdI0kJe.jpg',4.220724174458735,NULL,NULL,NULL,NULL,NULL),(459567,'不期而遇的姐妹','Socias por accidente','两位女子发现自己被同一个男人欺骗，且两人都被他弄怀孕了。于是她们联手展开报复。','',0,0,19.2481,8.859,377,0,'2026-03-12','es','/w1CqRnBWcR4R50dfc3X42jFztoX.jpg',3.4474865960074204,NULL,NULL,NULL,NULL,NULL),(459568,'年轻的心','Young Hearts','　　埃利亚斯是一个十四岁的男孩，在一个小村庄长大，他在这里感到自己像个局外人。在遇到新邻居兼同龄人亚历山大后，埃利亚斯开始面对自己逐渐显露的性意识。','',0,0,15.8798,8.566,310,0,'2024-10-26','nl','/7bYbISJTgdeT4PTb0g44QzSmmw1.jpg',3.336156649064786,NULL,NULL,NULL,NULL,NULL),(459569,'电锯人剧场版：蕾塞篇','劇場版 チェンソーマン レゼ篇','故事延续TV动画的最终章，讲述男主角电次在偶然邂逅的神秘少女蕾塞的庇护下，在快节奏的战斗中，奔向难以预测的命运。  电次，一个少年，与“电锯恶魔”签订契约，化身“电锯人”，成为隶属于公安部魔物对策特别课四课的魔物猎人，与魔物战斗。正兴奋地等待着与心仪的女性、公安部上司玛奇玛约会，却遭遇突如其来的暴雨，不得不在雨中避雨。在避雨的过程中，他邂逅了名为蕾塞的少女。在附近咖啡馆工作的蕾塞对电次露出了和善的笑容，两人迅速成为了好朋友。这次邂逅标志着电次的日常生活发生了重大改变。','',0,0,28.9523,8.546,1170,0,'2025-09-19','ja','/yFsmS9rayF2iGogqB9McesEN5kG.jpg',3.884102423564303,NULL,NULL,NULL,NULL,NULL),(459570,'勇夺芳心','दिलवाले दुल्हनिया ले जायेंगे','乔德利和妻子结婚多年，一直十分恩爱。两人共同养育了两个女儿希姆莱和图吉，两个姑娘都出落得亭亭玉立。一晃眼，希姆莱就到了该嫁人的年纪了，尽管乔德利一家人已经在伦敦生活了二十多年了，但乔德利骨子里依旧是一个传统的印度人。乔德利将希姆莱许配给了朋友的儿子库杰，这让希姆莱感到十分不满。一次偶然中，希姆莱邂逅了名为拉杰的印度男子，尽管拉杰为人轻浮，油腔滑调，但希姆莱还是同他坠入了情网。得知此事的乔德利举家迁回了印度，拉杰亦紧跟其后，他要如何才能获得乔德利的认可呢？','',0,0,17.0654,8.5,4620,0,'1995-10-20','hi','/zJW6zDJNmotX0SmE3ayJzZyWdnp.jpg',4.323803337224692,NULL,NULL,NULL,NULL,NULL),(459571,'寄生虫','기생충','金基泽一家四口挤在首尔一间狭小的半地下室里，没有稳定工作，只能靠零散的活计勉强维持生活。一天，儿子基宇经朋友介绍，得到前往富裕的朴社长家担任英语家教的机会。进入这个与自己生活截然不同的家庭后，基宇发现了新的机会，并设法将妹妹基婷包装成艺术老师介绍给朴家。随后，一家人通过精心设计，让父亲和母亲也先后进入朴家工作，而朴家始终不知道这四名新雇员其实来自同一个家庭。就在金家逐渐适应这份来之不易的优渥生活时，一个隐藏在朴家豪宅中的秘密突然出现，两个家庭之间看似稳定的关系也开始走向无法预料的方向……','',0,0,36.3011,8.49,21276,0,'2019-05-30','ko','/nwTQE4vWe6NoFSEgxGu4hO9J4Tv.jpg',4.770263835628985,NULL,NULL,NULL,NULL,NULL),(459573,'切腹','切腹','家族没落后，失业武士仲代达矢来到井伊藩主的宅邸，请求允许他在此切腹自尽。藩主家臣认定这名走投无路的浪人只是想讨份差事，遂逼迫他当场切腹——却低估了他坚守的信念与对尊严的执着。本片由小林正树执导，荣获戛纳电影节评委会特别奖，以凌厉笔触刻画了个体在腐朽伪善体制下的抗争。','',0,0,10.7364,8.5,1274,0,'1962-09-15','ja','/ipZGgAWhN3obNvkmSLlPbio67j0.jpg',3.8667384152449835,NULL,NULL,NULL,NULL,NULL),(459574,'萤火虫之墓','火垂るの墓','1945年，第二次世界大战接近尾声，日本神户在空袭中化为一片火海。14岁的清太带着4岁的妹妹节子逃过轰炸，却在灾难中失去了母亲，而在海军服役的父亲也远在战场。无家可归的兄妹只得寄住在亲戚家中，但随着战争持续、物资愈发匮乏，寄人篱下的生活也变得越来越艰难。最终，清太带着节子离开亲戚家，住进一处废弃的防空洞，试图只依靠彼此活下去。在被战争摧毁的日常中，微弱的萤火与短暂的欢笑，也成为兄妹俩所能拥有的少数温暖……','',0,0,0.0206,8.449,6779,0,'1988-04-16','ja','/u8fiQxH8BZKARS2Y9vrnBygOCzi.jpg',4.3823533209845875,NULL,NULL,NULL,NULL,NULL),(459575,'要不要做我儿子？','¿Quieres ser mi hijo?','四十岁的卢发现相伴十五年的伴侣出轨，生活瞬间崩塌。她在重建自我的过程中，与一位年轻放浪的男子产生了出乎意料的关系。','',0,0,6.4471,8.447,370,0,'2023-09-21','en','/sjLn3cdD1tM84nvaBDrPKv4kUsR.jpg',3.3690937745725367,NULL,NULL,NULL,NULL,NULL),(459576,'美丽人生','La vita è bella','1939年的意大利，乐观幽默的犹太青年圭多邂逅了女教师多拉。经过一连串阴差阳错，两人相爱成家，并有了儿子乔舒亚。然而随着战争的阴影逼近，圭多和儿子因犹太身份被强行送往集中营，没有犹太血统的多拉也毅然选择同行。为了保护年幼的乔舒亚免受残酷现实的伤害，圭多把集中营里的生活编成一场游戏，并告诉他获胜的奖品是一辆真正的坦克。在恐惧与苦难之中，圭多用幽默、想象和父爱守护着儿子的童真，也始终怀抱着一家人再次团聚的希望……','',0,0,20.9971,8.437,14227,0,'1997-12-20','it','/gAoRTn5nNFZQh2X3hjre9eK3m7e.jpg',4.621669363259238,NULL,NULL,NULL,NULL,NULL),(459577,'天堂电影院','Nuovo Cinema Paradiso','意大利南部的小镇上，男孩多多从小便痴迷电影，总爱跑到“天堂电影院”观看放映，并因此结识了放映师艾佛特。一个古灵精怪，一个嘴硬心软，两人在一卷卷胶片和无数银幕故事中逐渐成为忘年之交，电影院也成了多多童年最重要的地方。一次意外改变了两人的生活，多多开始更加深入地走进电影的世界。随着年岁增长，他经历了青春、初恋与离别，也逐渐发现小镇之外还有更广阔的人生。在艾佛特的陪伴与指引下，多多不得不面对一个重要的选择：是留在熟悉的故乡，还是离开这里，去寻找真正属于自己的未来……','',0,0,13.4575,8.4,4969,0,'1988-11-17','it','/edRt1FKEkohCqGYTqrpxUFBsa0n.jpg',4.31118317595752,NULL,NULL,NULL,NULL,NULL),(459578,'幸运有八只触手','Remarkably Bright Creatures','一名寡妇在小镇水族馆值夜班，与一只聪明的章鱼及一个迷茫的年轻人培养出独特情谊。','',0,0,17.7443,8.422,901,0,'2026-05-07','en','/qJPkSzyZPvDn3BsILd7po25uLdV.jpg',3.7350133793349465,NULL,NULL,NULL,NULL,NULL),(459579,'妙不可言','Cosas imposibles','生活是如此奇妙且难以预测，有时会在最不经意的地方发现幸福：一位七旬老妪和她的少年邻居之间产生了深厚的友谊。','',0,0,5.2862,8.421,434,0,'2021-06-17','es','/bY0lzllMYas6mydLnktQriwV1c8.jpg',3.4236571293522493,NULL,NULL,NULL,NULL,NULL),(459580,'蛊惑兄弟','O Auto da Compadecida','智高和杰克，一对患难穷兄弟，四出寻找工作，最终在面包店找到差事。但店主极为刻薄，兄弟俩的食物比狗还要差。阴差阳错，他们弄死了店主的狗，更要哄骗神父替小狗祈福，闹出笑话连篇。及后智高暗恋大财主之女路仙霞。但智高过于害羞，久久未能成事；杰克唯有替智高制造机会。一日，镇里来了一班悍匪，洗劫村民之余，更进行杀戮游戏……','',0,0,6.334,8.4,1243,0,'2000-09-15','pt','/8th22EYunAehjPwfh4CdCzh5MXb.jpg',3.8283254602665235,NULL,NULL,NULL,NULL,NULL),(459581,'罗小黑战记','罗小黑战记','在熙攘的人类世界里，许多妖精隐匿其中，与人类相安无事地生活着。猫妖罗小黑因为家园遭到破坏，被迫开始流浪。在旅途中，他先后遇到妖精同类与人类伙伴，并逐渐卷入人类与妖精之间的纷争。面对截然不同的立场与选择，小黑也开始寻找真正属于自己的归宿……','',0,0,10.2427,8.402,553,0,'2019-08-27','zh','/yey8JRsqYOsNg3cXpbbnqfvUnjt.jpg',3.5253290660300514,NULL,NULL,NULL,NULL,NULL),(459583,'声之形','映画 聲の形','西宫硝子（早见沙织 配音）生来患有听觉障碍，要依靠助听器和外界交流，口语发音也因此格外的古怪。小学时，硝子转入了一所新的学校，特殊的生理缺陷让她成为了班上引人注目的独特存在，她因此收获了坚实的友情，却也遭到了以男生石田将也（入野自由 配音）为首的小团体的孤立和排挤。随着时 间的推移，无心或有意的恶作剧渐渐升级，最终演变成为了无法挽回的伤害，硝子永远的消失在了众人的眼前。排挤硝子的事情曝光后，将也成为了下一个被欺负的对象，孤独痛苦的他终于理解了硝子的隐忍和温柔，只是他再也没有机会跟硝子道歉了。一次偶然中，将也同硝子重逢了，命运的齿轮重新开始了转动。','',0,0,13.9205,8.396,4677,0,'2016-09-17','ja','/xa00FlF3cpNzisAyezJL0svun2j.jpg',4.293314983220408,NULL,NULL,NULL,NULL,NULL),(459584,'保护者','Protector','退役军人尼基与女儿克洛伊平静生活，却在废弃工厂醒来后发现女儿遭绑架，她必须重返黑暗世界，对抗人贩子、警察与军方，在72小时黄金救援期内救回女儿。','',0,0,15.1253,8.392,575,0,'2026-02-20','en','/6bxKVHLsHXXZMgW8fpkvlIJ4Fec.jpg',3.550204569214081,NULL,NULL,NULL,NULL,NULL),(459585,'素媛','소원','素媛是一个生活在普通家庭里的小女孩，每天在父母的疼爱中平静成长。一个下着雨的早晨，她独自上学途中遭到陌生男子性侵，原本无忧无虑的生活从此被彻底改变。严重的身体伤害和心理创伤让素媛变得恐惧而敏感，甚至一度无法接受父亲的靠近，而突如其来的打击也让整个家庭陷入痛苦。面对女儿难以言说的伤痕，父母和身边的人小心翼翼地陪伴着她，用各自的方式重新给予她安全与温暖。在漫长的伤痛之后，这个家庭也开始努力寻找重新生活下去的希望……','',0,0,10.9596,8.392,913,0,'2013-10-02','ko','/8My8xdJdiHbbcGQ40N63HXh6PwQ.jpg',3.7196438978132087,NULL,NULL,NULL,NULL,NULL),(459586,'露西·希姆斯和和平王子','Lucy Shimmers and the Prince of Peace','假日季节，一位天使帮助一个冷酷的罪犯和一个早熟的小女孩相遇，并改变了他们的内心，从而给予他们第二次机会。','',0,0,8.4122,8.4,374,0,'2020-10-19','en','/wNiS0ZcUuDvuFk5xH4WWh0P7ezf.jpg',3.3728127729762263,NULL,NULL,NULL,NULL,NULL),(459587,'天国与地狱','天国と地獄','在黑泽明这部极具影响力的家庭伦理剧与刑侦叙事杰作中，三船敏郎饰演的富商权藤金吾令人过目难忘——其家人沦为冷血绑匪的勒索目标。改编自艾德·麦可班恩侦探小说《国王的赎金》的本片，游刃有余地从分秒必争的惊悚剧过渡为精准的社会剖析，铸就了一部关于阶级矛盾与当代日本社会的犀利影像论著。[标准收藏公司]','',0,0,9.4348,8.4,1191,0,'1963-03-01','ja','/gJHkgprhkYyyWSh7fFgTUy3W1X9.jpg',3.819267141386932,NULL,NULL,NULL,NULL,NULL),(459588,'加百列的地狱','Gabriel\'s Inferno','一个迷人的探索诱惑，禁止的爱，和救赎，一个迷人和激情的故事，一个人从他自己的地狱，因为他试图赢得不可能的宽恕和爱。','',0,0,4.0038,8.379,2480,0,'2020-05-29','en','/to5KjK4TrSZyHTskuJX4wxBLQ91.jpg',4.065792824000177,NULL,NULL,NULL,NULL,NULL),(459589,'蜘蛛侠：纵横宇宙','Spider-Man: Across the Spider-Verse','成为蜘蛛侠后的迈尔斯·莫拉莱斯一边守护自己的城市，一边努力在英雄身份与家庭生活之间寻找平衡，却始终怀念曾与自己并肩作战的格温和其他伙伴。一次意外重逢后，迈尔斯跟随蜘蛛格温穿越平行宇宙，第一次来到由来自不同世界的蜘蛛侠组成的“蜘蛛联盟”。然而，随着新的威胁不断穿梭于各个宇宙，迈尔斯也发现蜘蛛联盟对于维持多元宇宙秩序有着一套不容挑战的规则。当他的选择与蜘蛛侠2099米格尔·奥哈拉产生冲突时，迈尔斯不得不在众多蜘蛛侠的阻拦下，坚持自己对于“成为蜘蛛侠”究竟意味着什么的答案……','',0,0,47.4738,8.347,9216,0,'2023-05-31','en','/tLs8J0pxV4qTkKpBvBdlOWQAX96.jpg',4.545733472266328,NULL,NULL,NULL,NULL,NULL),(459590,'加百列的地狱：第二部','Gabriel\'s Inferno: Part II','加布里埃尔·爱默生教授终于发现了朱莉娅·米切尔身份的真相，但他的意识到为时已晚。茱莉亚最终希望这位受人尊敬的但丁专家会记住她，并且不想再与他有任何关系。加布里埃尔能在别人的怀抱中找到爱之前赢回她的心吗？','',0,0,2.8346,8.344,1562,0,'2020-07-31','en','/x5o8cLZfEXMoZczTYWLrUo1P7UJ.jpg',3.8937579850700508,NULL,NULL,NULL,NULL,NULL);
